-- =========================================================




-- =========================================================
-- A4.9 pay_batches_list / pay_batch_get
-- =========================================================








DROP FUNCTION IF EXISTS public.pay_batch_get(uuid);




DROP FUNCTION IF EXISTS public.pay_batch_get(uuid, uuid);
















create or replace function public.pay_batch_get(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_detail_mode text DEFAULT 'AUTO'::text,
  p_recommended_page_size integer DEFAULT NULL::integer
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch record;
  v_candidates jsonb := '[]'::jsonb;
  v_transfers jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;

  -- ✅ NEW: derived batch kind + channels
  v_batch_kind text := null;
  v_pay_channels_present jsonb := '[]'::jsonb;

  -- ✅ NEW: child modal support payloads
  v_candidate_breakdown jsonb := '[]'::jsonb;
  v_candidate_lines jsonb := '[]'::jsonb;
  v_finance_case_groups jsonb := '[]'::jsonb;
  v_finance_summaries jsonb := '{}'::jsonb;
  v_remittance_summary jsonb := '{}'::jsonb;
  v_communications_summary jsonb := '{}'::jsonb;

  -- ✅ C: schedule recommendations / UI defaults
  v_default_schedule_umbrella_local text := null;
  v_default_schedule_paye_local text := null;
  v_funds_warning_hours_json jsonb := null;
  v_rail_default_funding_account_ref text := null;

  -- ✅ D: authorisation summary (lightweight, for Banking UI)
  v_ar record;
  v_auth_approved_count int := 0;
  v_auth_approved_by jsonb := '[]'::jsonb;
  v_auth_invited_to jsonb := '[]'::jsonb;
  v_auth jsonb := null;

  v_batch_kind_fixed text := null;

  v_provider_normalized text := null;
  v_provider_known boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_batch_status_upper text := null;
  v_has_external_submission_evidence boolean := false;
  v_submission_evidence jsonb := '{}'::jsonb;
  v_current_transfer_hash text := null;
  v_pending_transfer_hash text := null;
  v_stable_transfer_hash text := null;
  v_execution_transfer_hash text := null;
  v_csv_comparison_transfer_hash text := null;
  v_csv_export_match_basis text := null;
  v_bank_csv_export_hash text := null;
  v_has_cloudtms_csv_export boolean := false;
  v_csv_export_matches_current_transfers boolean := false;
  v_can_create_bank_csv_file boolean := false;
  v_can_start_standard_execution boolean := false;
  v_can_start_csv_settlement boolean := false;
  v_can_start_external_settlement boolean := false;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_active_auth_execution_intent_json jsonb := null;
  v_execution_mode_pending text := null;
  v_suppress_remittances_pending boolean := false;

  -- Payment correction summary payloads for Banking Pay batch modal
  v_payment_correction jsonb := '{}'::jsonb;
  v_bank_evidence jsonb := '[]'::jsonb;
  v_movement_classification jsonb := '{}'::jsonb;
  v_manual_actions jsonb := '{}'::jsonb;
  v_communication_status jsonb := '{}'::jsonb;
  v_finance_case_correction_summary jsonb := '[]'::jsonb;
  v_correction_progress jsonb := '{}'::jsonb;
  v_open_correction_request_id uuid := NULL::uuid;
  v_latest_correction_request jsonb := '{}'::jsonb;
  v_latest_correction_request_status text := NULL::text;
  v_open_correction_request_count integer := 0;
  v_open_settled_reversal_request_count integer := 0;
  v_awaiting_authorisation_count integer := 0;
  v_processing_request_count integer := 0;
  v_blocked_request_count integer := 0;
  v_failed_request_count integer := 0;
  v_work_item_pending_count integer := 0;
  v_work_item_processing_count integer := 0;
  v_work_item_blocked_count integer := 0;
  v_work_item_failed_retryable_count integer := 0;
  v_work_item_failed_final_count integer := 0;
  v_work_item_failed_count integer := 0;
  v_work_item_requires_user_action boolean := false;
  v_work_item_processing_continues boolean := false;
  v_bank_event_count integer := 0;
  v_bank_failure_event_count integer := 0;
  v_bank_return_event_count integer := 0;
  v_transfer_failure_count integer := 0;
  v_transfer_completed_count integer := 0;
  v_transfer_provider_evidence_count integer := 0;
  v_settlement_evidence_count integer := 0;
  v_applied_unwind_item_count integer := 0;
  v_applied_reversal_item_count integer := 0;
  v_applied_precancel_item_count integer := 0;
  v_correctable_item_count integer := 0;
  v_corrected_item_count integer := 0;
  v_derived_correction_state text := 'NONE';
  v_can_cancel_payment_attempt boolean := false;
  v_can_unwind_failed_payment boolean := false;
  v_can_reverse_settled_payment boolean := false;
  v_can_review_bank_evidence boolean := false;
  v_active_effective_item_count integer := 0;
  v_active_effective_amount_ex_vat numeric := 0;
  v_active_effective_amount_inc_vat numeric := 0;
  v_payment_issue_candidate_count integer := 0;

  -- Banking alert / legacy funds-check compatibility support
  v_alert_actor_user_id uuid := '00000000-0000-0000-0000-000000000000'::uuid;
  v_alert_registry jsonb := jsonb_build_object('alerts', '[]'::jsonb, 'unacknowledged_count', 0, 'highest_severity', NULL::text, 'highest_label', NULL::text);
  v_banking_alerts jsonb := '[]'::jsonb;
  v_banking_alert_kind text := NULL::text;
  v_banking_alert_severity text := NULL::text;
  v_banking_alert_label text := NULL::text;
  v_banking_alert_reason text := NULL::text;
  v_banking_alert_fingerprint text := NULL::text;
  v_banking_alert_acknowledged_for_user boolean := false;
  v_banking_alert_requires_attention boolean := false;
  v_blocked_funds_required_gbp numeric := NULL::numeric;
  v_blocked_funds_available_gbp numeric := NULL::numeric;
  v_blocked_funds_required_gbp_display text := '—';
  v_blocked_funds_available_gbp_display text := '—';
  v_blocked_funds_reason text := NULL::text;
  v_blocked_funds_sufficient boolean := NULL::boolean;
  v_blocked_funds_provider text := NULL::text;
  v_blocked_funds_env text := NULL::text;
  v_blocked_funds_account_ref text := NULL::text;
  v_no_bank_transfer_events boolean := true;
  v_no_rail_tx_id boolean := true;
  v_no_provider_submission_reference boolean := true;
  v_no_submitted_or_completed_transfer_state boolean := true;
  v_no_provider_attempt_request_or_idempotency_reference boolean := true;
  v_no_possible_provider_attempt_evidence boolean := true;
  v_no_external_submission_evidence boolean := true;
  v_no_submission_evidence_flags jsonb := '{}'::jsonb;
  v_can_retry_blocked_funds boolean := false;
  v_blocked_funds_alert_payload jsonb := '{}'::jsonb;
  v_blocked_funds_payment_issue jsonb := NULL::jsonb;
  v_batch_stale_payment_issue jsonb := NULL::jsonb;
  v_batch_stale_payment_execution_review jsonb := NULL::jsonb;
  v_payment_issues jsonb := '[]'::jsonb;

  -- Scalable batch-open controls. These allow large batches to return a compact
  -- bootstrap payload without building heavy candidate/item/transfer arrays.
  v_detail_mode text := 'AUTO';
  v_effective_page_size integer := 100;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_item_breakdown_count integer := 0;
  v_transfer_count integer := 0;
  v_large_batch boolean := false;
  v_large_batch_reasons jsonb := '[]'::jsonb;
  v_bootstrap_only boolean := false;
  v_total_amount numeric := 0;
  v_provider_submitted_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_failed_transfer_count integer := 0;
  v_ambiguous_transfer_count integer := 0;
  v_attempted_but_unproven_transfer_count integer := 0;
  v_remittance_status_summary jsonb := '{}'::jsonb;
  v_settlement_status_summary jsonb := '{}'::jsonb;
  v_active_operation_id uuid := NULL::uuid;
  v_active_operation_type text := NULL::text;
  v_active_operation_status text := NULL::text;
  v_active_operation_phase text := NULL::text;
  v_active_operation_progress jsonb := NULL::jsonb;
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_freshness_is_stale boolean := false;
  v_provider_environment_summary jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_provider_submit_review_reason_code text := NULL::text;
  v_provider_submit_headline text := NULL::text;
  v_provider_submit_summary text := NULL::text;
  v_provider_submit_action_required text := NULL::text;
  v_provider_submit_actual_context boolean := false;
  v_payment_provider_review_required boolean := false;
  v_provider_submit_is_diagnostic_only boolean := false;
  v_provider_submit_backend_review_required boolean := false;
  v_provider_submit_operation_review_required boolean := false;
  v_provider_submit_acceptance_retry_unsafe boolean := false;
  v_provider_submit_issue_present boolean := false;
  v_provider_submit_manual_resolution_required boolean := false;
  v_provider_submit_manual_resolution_available boolean := false;
  v_provider_submit_safe_retry_available boolean := false;
  v_provider_submit_acceptance_evidence_present boolean := false;
  v_provider_submit_response_present boolean := false;
  v_provider_submit_stale_chunk boolean := false;
  v_payment_execution_review jsonb := NULL::jsonb;
  v_provider_submit_payment_issue jsonb := NULL::jsonb;
  v_available_sections jsonb := '["candidates","items","item_breakdowns","transfers","finance_case_groups","remittances","communications","auth_history","events"]'::jsonb;

  -- 3.41 backend-derived lifecycle/action/carry-forward payloads for Overview and Current Payment Status.
  v_batch_cancelability_diagnostic jsonb := '{}'::jsonb;
  v_batch_payment_lifecycle_state text := NULL::text;
  v_batch_payment_lifecycle_label text := NULL::text;
  v_batch_recommended_action text := NULL::text;
  v_whole_batch_cancel_available boolean := false;
  v_batch_can_pre_provider_cancel boolean := false;
  v_batch_requires_bank_check boolean := false;
  v_batch_requires_provider_cancel boolean := false;
  v_retry_state text := NULL::text;
  v_retry_after_utc text := NULL::text;
  v_retry_reason text := NULL::text;
  v_next_retry_description text := NULL::text;
  v_retry_plan_json jsonb := '{}'::jsonb;
  v_retry_eligible_count integer := 0;
  v_retry_ineligible_count integer := 0;
  v_retry_in_progress boolean := false;
  v_retry_already_in_progress boolean := false;
  v_retry_operation_id uuid := NULL::uuid;
  v_retry_operation_status text := NULL::text;
  v_retry_eligible_scope_json jsonb := '{}'::jsonb;
  v_retry_ineligible_summary_json jsonb := '[]'::jsonb;
  v_retry_scope_signature text := NULL::text;
  v_retry_status_label text := NULL::text;
  v_retry_button_label text := 'Retry unsent payments';
  v_retry_button_disabled_reason text := NULL::text;
  v_retry_button_visible boolean := false;
  v_partial_cancel_count integer := 0;
  v_cancelled_before_bank_submission_count integer := 0;
  v_financials_rewound_count integer := 0;
  v_manual_adjustments_carried_forward_count integer := 0;
  v_manual_adjustment_carry_forward_records_json jsonb := '[]'::jsonb;
  v_remittance_already_sent boolean := false;
  v_batch_support_details_json jsonb := '{}'::jsonb;
  v_batch_signal_version bigint := 0;
  v_batch_payment_status_version bigint := 0;
  v_batch_correction_progress_version bigint := 0;
  v_batch_alert_version bigint := 0;
  v_batch_overview_version bigint := 0;
  v_batch_last_status_hash text := NULL::text;
  v_batch_last_alert_hash text := NULL::text;
  v_provider_webhook_evidence_json jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  select
    pb.*
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if not found then
    raise exception 'pay_batch not found';
  end if;

  v_batch_kind_fixed := upper(btrim(coalesce(v_batch.batch_kind_fixed::text,'')));
  v_batch_status_upper := upper(btrim(coalesce(v_batch.status::text, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state::text, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED','SUBMITTED_NOT_COMMITTED','COMMITTED') then
    v_execution_commit_state := null;
  end if;

  v_provider_normalized := upper(btrim(coalesce(v_batch.rail_provider_snapshot::text, '')));
  if v_provider_normalized = 'REV' then
    v_provider_normalized := 'REVOLUT';
  end if;
  v_provider_known := (v_provider_normalized in ('REVOLUT','CSV'));

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  -- ✅ NEW: derive batch kind + channels from items (excludes DEBT_CREATED)
  select
    case
      when ch.channels is null then null
      when array_position(ch.channels,'PAYE') is not null and array_position(ch.channels,'UMBRELLA') is not null then 'MIXED'
      when array_position(ch.channels,'PAYE') is not null then 'PAYE'
      when array_position(ch.channels,'UMBRELLA') is not null then 'UMBRELLA'
      else null
    end as batch_kind,
    coalesce(to_jsonb(ch.channels), '[]'::jsonb) as channels_json
  into
    v_batch_kind,
    v_pay_channels_present
  from (
    select
      array_agg(distinct upper(coalesce(pbi.pay_channel::text,'')) order by upper(coalesce(pbi.pay_channel::text,'')))
        filter (where upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA')) as channels
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ) ch;


  v_detail_mode := upper(btrim(coalesce(p_detail_mode, 'AUTO')));
  IF v_detail_mode NOT IN ('AUTO','FULL','BOOTSTRAP_ONLY') THEN
    RAISE EXCEPTION 'PAY_BATCH_GET_INVALID_DETAIL_MODE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_GET_INVALID_DETAIL_MODE',
              'detail_mode', p_detail_mode,
              'allowed_modes', jsonb_build_array('AUTO','FULL','BOOTSTRAP_ONLY')
            )::text;
  END IF;

  v_effective_page_size := LEAST(250, GREATEST(25, COALESCE(p_recommended_page_size, 100)));

  SELECT COUNT(*)::integer
  INTO v_candidate_count
  FROM public.pay_batch_candidates AS candidate_count_scope
  WHERE candidate_count_scope.pay_batch_id = p_pay_batch_id;

  WITH item_scope AS (
    SELECT
      pbc_count.id AS pay_batch_candidate_id,
      pbc_count.candidate_id,
      pbi_count.id AS pay_batch_item_id,
      pbi_count.item_type,
      pbi_count.amount_ex_vat,
      pbi_count.amount_inc_vat,
      COALESCE(pbi_count.is_voided, false) AS is_voided,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS precancel_items
        WHERE precancel_items.pay_batch_item_id = pbi_count.id
          AND precancel_items.status = 'APPLIED'
          AND precancel_items.correction_item_kind = 'PRE_BANK_CANCEL'
      ) AS has_precancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS unwind_items
        WHERE unwind_items.pay_batch_item_id = pbi_count.id
          AND unwind_items.status = 'APPLIED'
          AND unwind_items.correction_item_kind = 'NO_MONEY_UNWIND'
      ) AS has_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reversal_items
        WHERE reversal_items.pay_batch_item_id = pbi_count.id
          AND reversal_items.status = 'APPLIED'
          AND reversal_items.correction_item_kind = 'SETTLED_REVERSAL'
      ) AS has_settled_reversal
    FROM public.pay_batch_candidates AS pbc_count
    LEFT JOIN public.pay_batch_items AS pbi_count
      ON pbi_count.pay_batch_candidate_id = pbc_count.id
    WHERE pbc_count.pay_batch_id = p_pay_batch_id
  ), candidate_rollup AS (
    SELECT
      item_scope.pay_batch_candidate_id,
      item_scope.candidate_id,
      COUNT(item_scope.pay_batch_item_id)::integer AS total_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.pay_batch_item_id IS NOT NULL
          AND COALESCE(item_scope.is_voided, false) = false
          AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
      )::integer AS active_effective_item_count,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_inc_vat,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal
      )::integer AS corrected_item_count
    FROM item_scope
    GROUP BY item_scope.pay_batch_candidate_id, item_scope.candidate_id
  )
  SELECT
    COALESCE(SUM(COALESCE(candidate_rollup.total_item_count, 0)), 0)::integer,
    COALESCE(SUM(COALESCE(candidate_rollup.active_effective_item_count, 0)), 0)::integer,
    ROUND(COALESCE(SUM(COALESCE(candidate_rollup.active_effective_amount_ex_vat, 0)), 0), 2)::numeric,
    ROUND(COALESCE(SUM(COALESCE(candidate_rollup.active_effective_amount_inc_vat, 0)), 0), 2)::numeric,
    COUNT(*) FILTER (WHERE COALESCE(candidate_rollup.corrected_item_count, 0) > 0)::integer
  INTO
    v_item_count,
    v_active_effective_item_count,
    v_active_effective_amount_ex_vat,
    v_active_effective_amount_inc_vat,
    v_payment_issue_candidate_count
  FROM candidate_rollup;

  SELECT COUNT(*)::integer
  INTO v_item_breakdown_count
  FROM public.pay_batch_item_breakdowns AS breakdown_count_scope
  JOIN public.pay_batch_items AS item_count_scope
    ON item_count_scope.id = breakdown_count_scope.pay_batch_item_id
  JOIN public.pay_batch_candidates AS candidate_count_scope
    ON candidate_count_scope.id = item_count_scope.pay_batch_candidate_id
  WHERE candidate_count_scope.pay_batch_id = p_pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_transfer_count
  FROM public.pay_bank_transfers AS transfer_count_scope
  WHERE transfer_count_scope.pay_batch_id = p_pay_batch_id;

  -- Use counts-only evidence for the summary/bootstrap path so large batch open
  -- does not build evidence samples or event-detail arrays. Full mode refreshes
  -- v_submission_evidence later with p_counts_only = false before detailed
  -- legacy funds-check/evidence payload construction.
  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      'ALL'::text,
      NULL::uuid,
      true
    ) AS classification_row
  ), classified_rows_with_sample AS (
    SELECT
      classified_rows.*,
      row_number() OVER (
        ORDER BY
          CASE
            WHEN classified_rows.evidence_classification IN ('local_only_evidence', 'attempted_but_unproven', 'ambiguous', 'failed', 'pending', 'scope_without_transfer') THEN 0
            ELSE 1
          END,
          classified_rows.pay_bank_transfer_id NULLS LAST,
          classified_rows.scope_id NULLS LAST
      ) AS evidence_sample_ordinality
    FROM classified_rows
  ), evidence_counts AS (
    SELECT
      count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer AS transfer_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'provider_evidence_present')::integer AS provider_submitted_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'local_only_evidence')::integer AS local_only_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'failed' OR classified_rows.is_failed_or_blocked IS TRUE)::integer AS failed_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'ambiguous' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer AS ambiguous_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS attempted_but_unproven_count,
      count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer AS provider_attempt_without_external_id_count,
      count(*) FILTER (
        WHERE classified_rows.evidence_classification = 'ambiguous'
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS requires_provider_poll_count,
      count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer AS committed_count,
      COALESCE(bool_or(
        EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
            AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        )
      ), false) AS has_rail_tx_id,
      COALESCE(bool_or(classified_rows.has_local_prepare_identity IS TRUE), false) AS has_local_generated_request_identity,
      COALESCE(bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE), false) AS has_external_submission_evidence,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_count,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_transfer_count,
      count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer AS unattempted_submit_eligible_count,
      count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer AS safe_local_cleanup_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS provider_attempt_or_evidence_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
      )::integer AS provider_or_ambiguous_evidence_count,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND false), '[]'::jsonb) AS evidence_sample,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'evidence_classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_route_ready', classified_rows.has_route_ready,
          'has_local_prepare_identity', classified_rows.has_local_prepare_identity,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_failed_or_blocked', classified_rows.is_failed_or_blocked,
          'is_terminal_or_completed', classified_rows.is_terminal_or_completed,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND false), '[]'::jsonb) AS execution_classification_sample
    FROM classified_rows_with_sample AS classified_rows
  ), status_sets AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(status_item.status_value ORDER BY status_item.status_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.status, ''))) AS status_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.status, '')), '') IS NOT NULL
        ) AS status_item
      ), '[]'::jsonb) AS transfer_statuses,
      COALESCE((
        SELECT jsonb_agg(rail_state_item.rail_state_value ORDER BY rail_state_item.rail_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.rail_state, ''))) AS rail_state_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.rail_state, '')), '') IS NOT NULL
        ) AS rail_state_item
      ), '[]'::jsonb) AS transfer_rail_states,
      COALESCE((
        SELECT jsonb_agg(event_state_item.normalised_state_value ORDER BY event_state_item.normalised_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.normalised_state, ''))) AS normalised_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.normalised_state, '')), '') IS NOT NULL
        ) AS event_state_item
      ), '[]'::jsonb) AS event_normalised_states,
      COALESCE((
        SELECT jsonb_agg(provider_state_item.provider_state_value ORDER BY provider_state_item.provider_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.provider_state, ''))) AS provider_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.provider_state, '')), '') IS NOT NULL
        ) AS provider_state_item
      ), '[]'::jsonb) AS event_provider_states,
      (SELECT count(*)::integer FROM public.pay_bank_transfer_events AS event_row WHERE event_row.pay_batch_id = p_pay_batch_id) AS transfer_event_count
  ), prepared_counts AS (
    SELECT
      evidence_counts.*,
      status_sets.*,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_unattempted_submit_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) AS remaining_evidence_unresolved_count,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_submit_attempt_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) + COALESCE(evidence_counts.ambiguous_count, 0) + COALESCE(evidence_counts.attempted_but_unproven_count, 0) AS remaining_provider_evidence_required,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_provider_submission_required,
      (
        COALESCE(evidence_counts.transfer_count, 0) > 0
        AND COALESCE(evidence_counts.provider_submitted_count, 0) = COALESCE(evidence_counts.transfer_count, 0)
        AND COALESCE(evidence_counts.failed_count, 0) = 0
        AND COALESCE(evidence_counts.ambiguous_count, 0) = 0
        AND COALESCE(evidence_counts.local_only_count, 0) = 0
        AND COALESCE(evidence_counts.pending_count, 0) = 0
        AND COALESCE(evidence_counts.attempted_but_unproven_count, 0) = 0
      ) AS can_mark_submitted
    FROM evidence_counts
    CROSS JOIN status_sets
  )
  SELECT
    jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'counts_only', true,
      'transfer_count', COALESCE(prepared_counts.transfer_count, 0),
      'transfer_event_count', COALESCE(prepared_counts.transfer_event_count, 0),
      'has_transfer_events', COALESCE(prepared_counts.transfer_event_count, 0) > 0,
      'provider_submitted_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'provider_evidence_present_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'local_idempotency_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_evidence_count', COALESCE(prepared_counts.local_only_count, 0),
      'pending_count', COALESCE(prepared_counts.pending_count, 0),
      'failed_count', COALESCE(prepared_counts.failed_count, 0),
      'ambiguous_count', COALESCE(prepared_counts.ambiguous_count, 0),
      'attempted_but_unproven_count', COALESCE(prepared_counts.attempted_but_unproven_count, 0),
      'provider_attempt_without_external_id_count', COALESCE(prepared_counts.provider_attempt_without_external_id_count, 0)
    )
    || jsonb_build_object(
      'requires_provider_poll_count', COALESCE(prepared_counts.requires_provider_poll_count, 0),
      'authorisation_ready_count', COALESCE(prepared_counts.authorisation_ready_count, 0),
      'authorisation_ready_transfer_count', COALESCE(prepared_counts.authorisation_ready_transfer_count, 0),
      'unattempted_submit_eligible_count', COALESCE(prepared_counts.unattempted_submit_eligible_count, 0),
      'safe_local_cleanup_count', COALESCE(prepared_counts.safe_local_cleanup_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(prepared_counts.provider_attempt_or_evidence_count, 0),
      'provider_or_ambiguous_evidence_count', COALESCE(prepared_counts.provider_or_ambiguous_evidence_count, 0),
      'cancellable_local_auth_request_count', 0,
      'non_cancellable_auth_request_count', 0,
      'same_operation_active_auth_request_count', 0,
      'other_operation_active_auth_request_count', 0,
      'auth_request_provider_risk_count', 0,
      'auth_request_retry_blocker_count', 0,
      'remaining_submit_attempt_required', COALESCE(prepared_counts.remaining_submit_attempt_required, 0),
      'remaining_unattempted_submit_required', COALESCE(prepared_counts.remaining_unattempted_submit_required, 0),
      'remaining_evidence_unresolved_count', COALESCE(prepared_counts.remaining_evidence_unresolved_count, 0)
    )
    || jsonb_build_object(
      'remaining_submit_attempt_required_definition', 'unattempted_submit_eligible_count',
      'remaining_provider_evidence_required', COALESCE(prepared_counts.remaining_provider_evidence_required, 0),
      'remaining_provider_submission_required', COALESCE(prepared_counts.remaining_provider_submission_required, 0),
      'submission_count_semantics', jsonb_build_object(
        'remaining_submit_attempt_required', 'count of transfers currently eligible for an unattempted provider submit',
        'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
        'pending_count', 'evidence-level pending classification, not submit eligibility'
      ),
      'batch_can_be_marked_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_committed', COALESCE(prepared_counts.can_mark_submitted, false) AND COALESCE(prepared_counts.committed_count, 0) = COALESCE(prepared_counts.transfer_count, 0),
      'has_rail_tx_id', COALESCE(prepared_counts.has_rail_tx_id, false),
      'has_local_generated_request_identity', COALESCE(prepared_counts.has_local_generated_request_identity, false),
      'has_external_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'no_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) = false,
      'transfer_statuses', COALESCE(prepared_counts.transfer_statuses, '[]'::jsonb),
      'transfer_rail_states', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb),
      'event_normalised_states', COALESCE(prepared_counts.event_normalised_states, '[]'::jsonb),
      'event_provider_states', COALESCE(prepared_counts.event_provider_states, '[]'::jsonb)
    )
    || jsonb_build_object(
      'evidence_sample', CASE WHEN false THEN COALESCE(prepared_counts.evidence_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'execution_classification_sample', CASE WHEN false THEN COALESCE(prepared_counts.execution_classification_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'has_possible_provider_attempt_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_provider_attempt_request_or_idempotency_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_request_or_idempotency_reference', COALESCE(prepared_counts.local_only_count, 0) > 0 OR COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_submitted_state', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_processing_state', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb) ?| array['PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION'],
      'has_completed_state', COALESCE(prepared_counts.committed_count, 0) > 0,
      'has_failed_or_rejected_provider_state', COALESCE(prepared_counts.failed_count, 0) > 0,
      'has_unknown_or_timeout_state', COALESCE(prepared_counts.ambiguous_count, 0) > 0,
      'requires_provider_poll', COALESCE(prepared_counts.requires_provider_poll_count, 0) > 0,
      'requires_review', COALESCE(prepared_counts.ambiguous_count, 0) > 0 OR (COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0 AND COALESCE(prepared_counts.requires_provider_poll_count, 0) = 0),
      'has_provider_submission_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_payment_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transfer_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transaction_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_external_payment_reference', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'has_external_transfer_reference', COALESCE(prepared_counts.has_external_submission_evidence, false)
    )
  INTO v_submission_evidence
  FROM prepared_counts;
  v_provider_submitted_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'provider_submitted_count', '')::integer, 0);
  v_local_only_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'local_only_count', '')::integer, COALESCE(NULLIF(v_submission_evidence ->> 'local_idempotency_only_count', '')::integer, 0));
  v_pending_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'pending_count', '')::integer, 0);
  v_failed_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'failed_count', '')::integer, 0);
  v_ambiguous_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'ambiguous_count', '')::integer, 0);
  v_attempted_but_unproven_transfer_count := COALESCE(NULLIF(v_submission_evidence ->> 'attempted_but_unproven_count', '')::integer, 0);
  v_has_external_submission_evidence := COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false);

  v_total_amount := COALESCE(v_batch.total_bank_out, v_active_effective_amount_inc_vat, v_active_effective_amount_ex_vat, 0);
  v_has_cloudtms_csv_export := (
    v_batch.bank_csv_export_json is not null
    and jsonb_typeof(v_batch.bank_csv_export_json) = 'object'
    and NULLIF(btrim(coalesce(v_batch.bank_csv_export_json ->> 'transfer_hash', '')), '') IS NOT NULL
  );

  v_can_create_bank_csv_file := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
  );
  v_can_start_standard_execution := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_provider_normalized <> 'CSV'
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );
  v_can_start_csv_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
    and v_has_cloudtms_csv_export = true
  );
  v_can_start_external_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );

  WITH settlement_status_counts AS (
    SELECT
      COALESCE(NULLIF(btrim(coalesce(settlement_candidate.settlement_status, '')), ''), 'UNKNOWN') AS settlement_status,
      COUNT(*)::integer AS status_count
    FROM public.pay_batch_candidates AS settlement_candidate
    WHERE settlement_candidate.pay_batch_id = p_pay_batch_id
    GROUP BY COALESCE(NULLIF(btrim(coalesce(settlement_candidate.settlement_status, '')), ''), 'UNKNOWN')
  )
  SELECT jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'settled_count', COALESCE((
      SELECT SUM(settlement_status_counts.status_count)::integer
      FROM settlement_status_counts
      WHERE upper(settlement_status_counts.settlement_status) IN ('SETTLED','PAID','CONFIRMED')
    ), 0),
    'status_counts', COALESCE((
      SELECT jsonb_object_agg(settlement_status_counts.settlement_status, settlement_status_counts.status_count ORDER BY settlement_status_counts.settlement_status)
      FROM settlement_status_counts
    ), '{}'::jsonb)
  )
  INTO v_settlement_status_summary;

  WITH remittance_status_counts AS (
    SELECT
      COALESCE(NULLIF(btrim(coalesce(remittance_candidate.remittance_trigger_status, '')), ''), 'UNKNOWN') AS remittance_status,
      COUNT(*)::integer AS status_count
    FROM public.pay_batch_candidates AS remittance_candidate
    WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
    GROUP BY COALESCE(NULLIF(btrim(coalesce(remittance_candidate.remittance_trigger_status, '')), ''), 'UNKNOWN')
  )
  SELECT jsonb_build_object(
    'candidate_count', COALESCE(v_candidate_count, 0),
    'sent_count', COALESCE((
      SELECT COUNT(*)::integer
      FROM public.pay_batch_candidates AS sent_remittance_candidate
      WHERE sent_remittance_candidate.pay_batch_id = p_pay_batch_id
        AND sent_remittance_candidate.remittance_sent_at_utc IS NOT NULL
    ), 0),
    'status_counts', COALESCE((
      SELECT jsonb_object_agg(remittance_status_counts.remittance_status, remittance_status_counts.status_count ORDER BY remittance_status_counts.remittance_status)
      FROM remittance_status_counts
    ), '{}'::jsonb)
  )
  INTO v_remittance_status_summary;

  SELECT
    operation_scope.id,
    operation_scope.operation_type,
    operation_scope.status,
    operation_scope.phase,
    operation_scope.progress_json
  INTO
    v_active_operation_id,
    v_active_operation_type,
    v_active_operation_status,
    v_active_operation_phase,
    v_active_operation_progress
  FROM public.banking_pay_operations AS operation_scope
  WHERE operation_scope.pay_batch_id = p_pay_batch_id
    AND operation_scope.status NOT IN ('COMPLETE','FAILED','CANCELLED')
  ORDER BY COALESCE(operation_scope.updated_at_utc, operation_scope.created_at_utc) DESC, operation_scope.created_at_utc DESC, operation_scope.id DESC
  LIMIT 1;

  v_provider_environment_summary := jsonb_build_object(
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'provider_normalized', v_provider_normalized,
    'provider_known', v_provider_known,
    'funding_account_ref', v_batch.funding_account_ref
  );

  v_batch_cancelability_diagnostic := COALESCE(
    public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object('scope_type', 'BATCH'),
      p_actor_user_id
    ),
    '{}'::jsonb
  );

  v_batch_payment_lifecycle_state := COALESCE(
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'payment_lifecycle_state', '')), ''),
    'LOCAL_PREPARED_NOT_SENT'
  );

  v_batch_payment_lifecycle_label := CASE v_batch_payment_lifecycle_state
    WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
    WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
    WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
    WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried'
    WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
    WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
    WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
    WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
    WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
    WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
    WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
    ELSE initcap(replace(lower(COALESCE(v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
  END;

  v_batch_recommended_action := NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'recommended_action', '')), '');
  v_whole_batch_cancel_available := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'whole_batch_cancel_available', 'false'))) IN ('true','1','yes','y','on');
  v_batch_can_pre_provider_cancel := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_pre_provider_cancel', 'false'))) IN ('true','1','yes','y','on');
  v_batch_requires_bank_check := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_bank_check', 'false'))) IN ('true','1','yes','y','on');
  v_batch_requires_provider_cancel := lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_provider_cancel', 'false'))) IN ('true','1','yes','y','on');
  v_retry_state := CASE
    WHEN lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'requires_retry_later', 'false'))) IN ('true','1','yes','y','on')
      OR upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER'
      THEN 'RETRY_UNSENT_AVAILABLE'
    ELSE NULL::text
  END;
  v_retry_after_utc := COALESCE(
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'next_retry_at_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_after_utc', '')), '')
  );
  v_retry_reason := COALESCE(
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_active_operation_progress->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_reason', '')), '')
  );
  v_next_retry_description := CASE
    WHEN v_retry_state IN ('RETRY_UNSENT_AVAILABLE','RETRY_UNSENT_IN_PROGRESS') THEN COALESCE(v_retry_reason, 'Payments were not sent to the bank/provider and can be retried.')
    ELSE NULL::text
  END;

  SELECT
    COALESCE(COUNT(DISTINCT correction_items.pay_batch_item_id) FILTER (WHERE correction_items.correction_item_kind = 'PRE_BANK_CANCEL' AND correction_items.status = 'APPLIED'), 0)::integer,
    COALESCE(COUNT(DISTINCT correction_items.pay_batch_item_id) FILTER (WHERE correction_items.correction_item_kind = 'NO_MONEY_UNWIND' AND correction_items.status = 'APPLIED'), 0)::integer
  INTO
    v_cancelled_before_bank_submission_count,
    v_financials_rewound_count
  FROM public.pay_payment_correction_items AS correction_items
  WHERE correction_items.pay_batch_id = p_pay_batch_id;

  v_partial_cancel_count := CASE
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_active_effective_item_count, 0) > 0
     AND v_batch_payment_lifecycle_state <> 'CANCELLED_BEFORE_BANK_SUBMISSION'
      THEN COALESCE(v_cancelled_before_bank_submission_count, 0)
    ELSE 0
  END;

  SELECT
    COALESCE(COUNT(*)::integer, 0),
    COALESCE(jsonb_agg(
      jsonb_build_object(
        'id', carry_forward_rows.id::text,
        'status', carry_forward_rows.status,
        'source_pay_batch_id', CASE WHEN carry_forward_rows.source_pay_batch_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_batch_id::text END,
        'source_pay_batch_item_id', CASE WHEN carry_forward_rows.source_pay_batch_item_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_batch_item_id::text END,
        'source_pay_bank_transfer_id', CASE WHEN carry_forward_rows.source_pay_bank_transfer_id IS NULL THEN NULL ELSE carry_forward_rows.source_pay_bank_transfer_id::text END,
        'target_pay_batch_id', CASE WHEN carry_forward_rows.target_pay_batch_id IS NULL THEN NULL ELSE carry_forward_rows.target_pay_batch_id::text END,
        'target_pay_batch_item_id', CASE WHEN carry_forward_rows.target_pay_batch_item_id IS NULL THEN NULL ELSE carry_forward_rows.target_pay_batch_item_id::text END,
        'adjustment_direction', carry_forward_rows.adjustment_direction,
        'amount_ex_vat', carry_forward_rows.amount_ex_vat,
        'amount_vat', carry_forward_rows.amount_vat,
        'amount_inc_vat', carry_forward_rows.amount_inc_vat,
        'signed_amount_convention', 'SIGNED_AMOUNTS'
      )
      ORDER BY carry_forward_rows.id
    ), '[]'::jsonb)
  INTO
    v_manual_adjustments_carried_forward_count,
    v_manual_adjustment_carry_forward_records_json
  FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_rows
  WHERE carry_forward_rows.source_pay_batch_id = p_pay_batch_id
     OR carry_forward_rows.target_pay_batch_id = p_pay_batch_id;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_batch_candidates AS remittance_candidate
    WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
      AND remittance_candidate.remittance_sent_at_utc IS NOT NULL
  )
  INTO v_remittance_already_sent;

  SELECT
    COALESCE(batch_signal.version, 0),
    COALESCE(batch_signal.payment_status_version, 0),
    COALESCE(batch_signal.correction_progress_version, 0),
    COALESCE(batch_signal.alert_version, 0),
    COALESCE(batch_signal.overview_version, 0),
    batch_signal.last_status_hash,
    batch_signal.last_alert_hash
  INTO
    v_batch_signal_version,
    v_batch_payment_status_version,
    v_batch_correction_progress_version,
    v_batch_alert_version,
    v_batch_overview_version,
    v_batch_last_status_hash,
    v_batch_last_alert_hash
  FROM public.banking_pay_batch_change_signals AS batch_signal
  WHERE batch_signal.pay_batch_id = p_pay_batch_id;

  IF NOT FOUND THEN
    v_batch_signal_version := 0;
    v_batch_payment_status_version := 0;
    v_batch_correction_progress_version := 0;
    v_batch_alert_version := 0;
    v_batch_overview_version := 0;
    v_batch_last_status_hash := NULL::text;
    v_batch_last_alert_hash := NULL::text;
  END IF;

  v_provider_webhook_evidence_json := COALESCE(
    v_batch_cancelability_diagnostic->'provider_webhook_evidence_json',
    v_batch_cancelability_diagnostic#>'{provider_evidence,provider_webhook_evidence_json}',
    '{}'::jsonb
  );

  v_batch_support_details_json := jsonb_strip_nulls(
    COALESCE(v_batch_cancelability_diagnostic->'support_details_json', '{}'::jsonb)
    || jsonb_build_object(
      'live_signal_version', COALESCE(v_batch_signal_version, 0),
      'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
      'alert_version', COALESCE(v_batch_alert_version, 0),
      'overview_version', COALESCE(v_batch_overview_version, 0),
      'last_status_hash', v_batch_last_status_hash,
      'last_alert_hash', v_batch_last_alert_hash,
      'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb)
    )
    || jsonb_build_object(
      'db_status', v_batch.status,
      'payment_lifecycle_state', v_batch_payment_lifecycle_state,
      'recommended_action', v_batch_recommended_action,
      'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
      'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
      'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
      'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
      'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
      'derived_lifecycle_values_are_payload_only', true
    )
  );

  v_provider_submit_diagnostic_result := COALESCE(
    public.pay_provider_submit_diagnostic_get(p_pay_batch_id => p_pay_batch_id),
    '{}'::jsonb
  );

  IF jsonb_typeof(v_provider_submit_diagnostic_result -> 'provider_submit_diagnostic') = 'object' THEN
    v_provider_submit_diagnostic := v_provider_submit_diagnostic_result -> 'provider_submit_diagnostic';
  ELSE
    v_provider_submit_diagnostic := '{}'::jsonb;
  END IF;

  -- 3.41: finalise retry metadata after provider-submit diagnostics are loaded.
  -- The earlier batch diagnostic is intentionally kept, but provider retry
  -- metadata is not available until this point.
  v_retry_after_utc := COALESCE(
    NULLIF(btrim(COALESCE(v_retry_after_utc, '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,retry_after_utc}', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,retry_after_utc}', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_after_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'next_retry_at_utc', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic #>> '{support_details_json,retry_after_utc}', '')), '')
  );

  v_retry_reason := COALESCE(
    NULLIF(btrim(COALESCE(v_retry_reason, '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,retry_reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_batch_cancelability_diagnostic #>> '{support_details_json,provider_evidence,reason}', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic->>'retry_reason', '')), ''),
    NULLIF(btrim(COALESCE(v_provider_submit_diagnostic #>> '{support_details_json,retry_reason}', '')), '')
  );

  v_next_retry_description := CASE
    WHEN v_retry_state IN ('RETRY_UNSENT_AVAILABLE','RETRY_UNSENT_IN_PROGRESS') THEN COALESCE(v_retry_reason, 'Payments were not sent to the bank/provider and can be retried.')
    ELSE NULL::text
  END;

  IF upper(btrim(COALESCE(v_active_operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
     AND upper(btrim(COALESCE(v_active_operation_status, ''))) NOT IN ('COMPLETED','COMPLETE','SUCCEEDED','SUCCESS','FAILED','FAILED_FINAL','CANCELLED','CANCELED') THEN
    v_retry_in_progress := true;
    v_retry_already_in_progress := true;
    v_retry_operation_id := v_active_operation_id;
    v_retry_operation_status := v_active_operation_status;
    v_retry_state := 'RETRY_UNSENT_IN_PROGRESS';
  END IF;

  IF upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER'
     OR COALESCE(v_retry_in_progress, false) THEN
    BEGIN
      v_retry_plan_json := public.pay_payment_correction_plan(
        p_pay_batch_id,
        jsonb_build_object(
          'scope_type', 'BATCH',
          'source_context', 'PAY_BATCH_GET_OVERVIEW',
          'requested_action', 'RETRY_PROVIDER_LATER'
        ),
        p_actor_user_id
      );
    EXCEPTION WHEN OTHERS THEN
      v_retry_plan_json := jsonb_build_object(
        'ok', false,
        'retry_eligible_count', 0,
        'retry_ineligible_count', 0,
        'retry_eligible_scope_json', '{}'::jsonb,
        'retry_ineligible_summary_json', jsonb_build_array(jsonb_build_object(
          'code', 'RETRY_UNSENT_PLAN_UNAVAILABLE',
          'message', SQLERRM,
          'sqlstate', SQLSTATE
        )),
        'retry_in_progress', COALESCE(v_retry_in_progress, false),
        'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
        'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
        'retry_operation_status', v_retry_operation_status,
        'retry_button_visible', false,
        'retry_button_disabled_reason', 'Retry status could not be checked'
      );
    END;

    v_retry_eligible_count := CASE
      WHEN COALESCE(v_retry_plan_json->>'retry_eligible_count', '') ~ '^\d+$' THEN (v_retry_plan_json->>'retry_eligible_count')::integer
      ELSE 0
    END;
    v_retry_ineligible_count := CASE
      WHEN COALESCE(v_retry_plan_json->>'retry_ineligible_count', '') ~ '^\d+$' THEN (v_retry_plan_json->>'retry_ineligible_count')::integer
      ELSE 0
    END;
    v_retry_eligible_scope_json := COALESCE(v_retry_plan_json->'retry_eligible_scope_json', '{}'::jsonb);
    v_retry_ineligible_summary_json := COALESCE(v_retry_plan_json->'retry_ineligible_summary_json', '[]'::jsonb);
    v_retry_scope_signature := NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_scope_signature', '')), '');

    IF NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_operation_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_retry_operation_id := (v_retry_plan_json->>'retry_operation_id')::uuid;
    END IF;
    v_retry_operation_status := COALESCE(NULLIF(btrim(COALESCE(v_retry_plan_json->>'retry_operation_status', '')), ''), v_retry_operation_status);
    v_retry_in_progress := COALESCE(NULLIF(v_retry_plan_json->>'retry_in_progress', '')::boolean, v_retry_in_progress, false);
    v_retry_already_in_progress := COALESCE(NULLIF(v_retry_plan_json->>'retry_already_in_progress', '')::boolean, v_retry_in_progress, false);
  END IF;

  IF v_retry_operation_id IS NULL THEN
    SELECT retry_operation_rows.id,
           retry_operation_rows.status
    INTO v_retry_operation_id,
         v_retry_operation_status
    FROM public.banking_pay_operations AS retry_operation_rows
    WHERE retry_operation_rows.pay_batch_id = p_pay_batch_id
      AND upper(btrim(COALESCE(retry_operation_rows.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
    ORDER BY COALESCE(retry_operation_rows.updated_at_utc, retry_operation_rows.created_at_utc) DESC NULLS LAST,
             retry_operation_rows.created_at_utc DESC NULLS LAST,
             retry_operation_rows.id DESC
    LIMIT 1;
  END IF;

  IF COALESCE(v_retry_in_progress, false) THEN
    v_retry_state := 'RETRY_UNSENT_IN_PROGRESS';
    v_retry_status_label := 'Retrying unsent payments';
    v_retry_button_disabled_reason := 'Retry in progress';
    v_retry_button_visible := false;
  ELSIF COALESCE(v_retry_eligible_count, 0) > 0 THEN
    v_retry_state := 'RETRY_UNSENT_AVAILABLE';
    v_retry_status_label := 'Bank unavailable — unsent payments can be retried';
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := true;
  ELSIF upper(btrim(COALESCE(v_retry_operation_status, ''))) IN ('COMPLETED','COMPLETE','SUCCEEDED','SUCCESS') THEN
    v_retry_state := 'RETRY_UNSENT_COMPLETE';
    v_retry_status_label := 'Retry complete';
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := false;
  ELSIF upper(btrim(COALESCE(v_batch_recommended_action, ''))) = 'RETRY_PROVIDER_LATER' THEN
    v_retry_state := 'NO_UNSENT_RETRY_AVAILABLE';
    v_retry_status_label := 'No unsent payments available to retry';
    v_retry_button_disabled_reason := 'No unsent payments available to retry';
    v_retry_button_visible := false;
  ELSE
    v_retry_state := NULL::text;
    v_retry_status_label := NULL::text;
    v_retry_button_disabled_reason := NULL::text;
    v_retry_button_visible := false;
  END IF;

  v_next_retry_description := CASE
    WHEN v_retry_state = 'RETRY_UNSENT_AVAILABLE' THEN 'Payments were not sent to the bank/provider and can be retried.'
    WHEN v_retry_state = 'RETRY_UNSENT_IN_PROGRESS' THEN 'CloudTMS is retrying payments confirmed as not sent. You can continue using CloudTMS while this runs.'
    WHEN v_retry_state = 'NO_UNSENT_RETRY_AVAILABLE' THEN 'No unsent payments are currently available to retry.'
    WHEN v_retry_state = 'RETRY_UNSENT_COMPLETE' THEN 'Retry complete.'
    ELSE NULL::text
  END;

  v_batch_support_details_json := COALESCE(v_batch_support_details_json, '{}'::jsonb) || jsonb_build_object(
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_scope_signature', v_retry_scope_signature,
    'retry_status_label', v_retry_status_label,
    'retry_button_label', v_retry_button_label,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason
  );

  v_provider_submission_status := upper(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'provider_submission_status',
    v_provider_submit_diagnostic_result ->> 'provider_submission_status',
    'NO_PROVIDER_SUBMISSION_ATTEMPTED'
  )));

  v_provider_submit_review_reason_code := upper(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'review_reason_code',
    v_provider_submit_diagnostic_result ->> 'review_reason_code',
    ''
  )));

  v_provider_submit_actual_context := (
    COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,operation_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,chunk_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '')::integer, 0) > 0
    OR COALESCE(NULLIF(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', '')::integer, 0) > 0
    OR v_provider_submission_status NOT IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED')
  );

  v_provider_submit_acceptance_evidence_present := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'provider_acceptance_evidence_present', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_response_present := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'provider_response_present', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_stale_chunk := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'stale_submit_chunk', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_manual_resolution_required := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'manual_resolution_required', 'false'))) IN ('true','1','yes','y','on');
  v_provider_submit_safe_retry_available := lower(btrim(coalesce(v_provider_submit_diagnostic ->> 'safe_retry_available', 'false'))) IN ('true','1','yes','y','on');

  v_provider_submit_backend_review_required := lower(btrim(coalesce(
    v_provider_submit_diagnostic ->> 'payment_provider_review_required',
    v_provider_submit_diagnostic_result ->> 'payment_provider_review_required',
    v_provider_submit_diagnostic ->> 'provider_submit_review_required',
    v_provider_submit_diagnostic_result ->> 'provider_submit_review_required',
    'false'
  ))) IN ('true','1','yes','y','on');

  v_provider_submit_operation_review_required := (
    upper(btrim(coalesce(v_active_operation_type, ''))) IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND upper(btrim(coalesce(v_active_operation_status, ''))) = 'REVIEW_REQUIRED'
  );

  v_provider_submit_acceptance_retry_unsafe := (
    v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
    AND v_provider_submit_acceptance_evidence_present
    AND (
      v_provider_submit_backend_review_required
      OR v_provider_submit_operation_review_required
      OR lower(btrim(coalesce(
        v_provider_submit_diagnostic ->> 'duplicate_payment_risk',
        v_provider_submit_diagnostic_result ->> 'duplicate_payment_risk',
        v_provider_submit_diagnostic ->> 'provider_duplicate_payment_risk',
        v_provider_submit_diagnostic_result ->> 'provider_duplicate_payment_risk',
        'false'
      ))) IN ('true','1','yes','y','on')
    )
  );

  IF v_provider_submit_acceptance_evidence_present THEN
    v_has_external_submission_evidence := true;
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;
  v_provider_submit_manual_resolution_available := (
    v_provider_submit_actual_context
    AND v_provider_submit_manual_resolution_required
    AND v_provider_submit_acceptance_evidence_present = false
  );

  v_payment_provider_review_required := (
    v_provider_submit_actual_context
    AND v_provider_submission_status <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
    AND (
      v_provider_submit_backend_review_required
      OR v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_REJECTED',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      )
      OR v_provider_submit_acceptance_retry_unsafe
    )
  );

  v_provider_submit_issue_present := COALESCE(v_payment_provider_review_required, false);

  v_provider_submit_is_diagnostic_only := (
    v_provider_submit_actual_context
    AND COALESCE(v_provider_submit_issue_present, false) = false
  );

  IF v_provider_submit_issue_present AND COALESCE(v_provider_submit_safe_retry_available, false) IS NOT TRUE THEN
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;

  IF v_provider_submit_issue_present THEN
    v_provider_submit_headline := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected payment'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
      ELSE 'Provider submission outcome unknown'
    END;

    v_provider_submit_summary := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider returned a rejection/failure.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Submission failed before the payment request was sent.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider accepted/submitted the payment.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'A provider request may have been sent, but no usable response was recorded.'
      ELSE 'Submit chunk is stale with no provider response, transfer event, rail transaction ID, or rail state.'
    END;

    v_provider_submit_action_required := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Review provider error and correct before retry.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Retry may be available after local cleanup.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Do not retry until reconciled.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Reconcile with provider before retry.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Reconcile with provider before retry.'
      ELSE 'Check Revolut/bank before retry.'
    END;

    v_payment_execution_review := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_submission_status', v_provider_submission_status,
      'headline', v_provider_submit_headline,
      'summary', v_provider_submit_summary,
      'recommended_action', COALESCE(NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'recommended_action', '')), ''), v_provider_submit_action_required),
      'operation_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'operation_id', '')), ''),
      'chunk_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'chunk_id', '')), ''),
      'transfer_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'auth_request_id', '')), ''),
      'provider_acceptance_evidence_present', v_provider_submit_acceptance_evidence_present,
      'provider_response_present', v_provider_submit_response_present,
      'stale_submit_chunk', v_provider_submit_stale_chunk,
      'manual_resolution_required', v_provider_submit_manual_resolution_required,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', false,
      'provider_submit_diagnostic', v_provider_submit_diagnostic
    ));

    v_provider_submit_payment_issue := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'issue_type', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'status', 'NEEDS_REVIEW',
      'severity', CASE WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'danger' ELSE 'warning' END,
      'headline', v_provider_submit_headline,
      'summary', v_provider_submit_summary,
      'action_required', v_provider_submit_action_required,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'manual_resolution_required', v_provider_submit_manual_resolution_required,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', false,
      'operation_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'operation_id', '')), ''),
      'chunk_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'chunk_id', '')), ''),
      'transfer_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'auth_request_id', '')), ''),
      'request_id', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'request_id', '')), ''),
      'idempotency_key', NULLIF(btrim(coalesce(v_provider_submit_diagnostic ->> 'idempotency_key', '')), '')
    ));
  ELSE
    v_payment_execution_review := NULL::jsonb;
    v_provider_submit_payment_issue := NULL::jsonb;
  END IF;

  v_freshness_is_stale := upper(btrim(coalesce(to_jsonb(v_batch) ->> 'freshness_validation_status', ''))) = 'STALE';
  v_stale_reason_counts := COALESCE((to_jsonb(v_batch) -> 'freshness_result_json') -> 'stale_reason_counts', '{}'::jsonb);

  IF v_batch_status_upper IN ('DRAFT','DRAFT_CREATED')
     AND COALESCE(v_freshness_is_stale, false) = true THEN
    v_batch_stale_payment_issue := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_BATCH_STALE',
      'issue_type', 'PAYMENT_BATCH_STALE',
      'status', 'NEEDS_REVIEW',
      'severity', 'warning',
      'headline', 'Draft payment is no longer valid',
      'title', 'Draft payment is no longer valid',
      'summary', 'Some payments in this draft are no longer valid.',
      'message', 'Some payments in this draft are no longer valid. Delete this draft and create a new draft payment batch.',
      'action_required', 'Delete this draft and create a new draft payment batch.',
      'recommended_action', 'Delete this draft and create a new draft payment batch.',
      'user_action', 'DELETE_DRAFT_AND_CREATE_NEW',
      'delete_draft_recommended', true,
      'create_new_draft_recommended', true,
      'requires_user_action', true,
      'whole_batch_issue', true,
      'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
      'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
      'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
      'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
      'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
    ));

    v_batch_stale_payment_execution_review := jsonb_strip_nulls(jsonb_build_object(
      'issue_kind', 'PAYMENT_BATCH_STALE',
      'review_reason_code', 'BATCH_STALE',
      'headline', 'Draft payment is no longer valid',
      'summary', 'Some payments in this draft are no longer valid.',
      'message', 'Some payments in this draft are no longer valid. Delete this draft and create a new draft payment batch.',
      'recommended_action', 'Delete this draft and create a new draft payment batch.',
      'user_action', 'DELETE_DRAFT_AND_CREATE_NEW',
      'delete_draft_recommended', true,
      'create_new_draft_recommended', true,
      'manual_resolution_required', false,
      'manual_resolution_available', false,
      'safe_retry_available', false,
      'payment_provider_review_required', false,
      'provider_submit_issue_present', false,
      'provider_submit_is_diagnostic_only', true,
      'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
      'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
      'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
      'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
      'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
      'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
      'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
      'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
    ));

    IF v_payment_execution_review IS NULL THEN
      v_payment_execution_review := v_batch_stale_payment_execution_review;
    END IF;

    v_payment_issues := COALESCE(v_payment_issues, '[]'::jsonb) || jsonb_build_array(v_batch_stale_payment_issue);
  END IF;

  v_large_batch := (
    COALESCE(v_candidate_count, 0) > 100
    OR COALESCE(v_item_count, 0) > 250
    OR COALESCE(v_transfer_count, 0) > 100
    OR COALESCE(v_item_breakdown_count, 0) > 500
  );

  SELECT COALESCE(jsonb_agg(large_reason.reason ORDER BY large_reason.reason), '[]'::jsonb)
  INTO v_large_batch_reasons
  FROM (
    SELECT 'candidate_count'::text AS reason WHERE COALESCE(v_candidate_count, 0) > 100
    UNION ALL
    SELECT 'item_count'::text AS reason WHERE COALESCE(v_item_count, 0) > 250
    UNION ALL
    SELECT 'transfer_count'::text AS reason WHERE COALESCE(v_transfer_count, 0) > 100
    UNION ALL
    SELECT 'item_breakdown_count'::text AS reason WHERE COALESCE(v_item_breakdown_count, 0) > 500
  ) AS large_reason;

  v_bootstrap_only := (
    v_detail_mode = 'BOOTSTRAP_ONLY'
    OR (v_detail_mode IN ('AUTO','FULL') AND v_large_batch = true)
  );

  IF v_bootstrap_only THEN
    RETURN
      jsonb_build_object(
        'ok', true,
        'bootstrap_only', true,
        'detail_mode_requested', v_detail_mode,
        'detail_mode_applied', 'BOOTSTRAP_ONLY',
        'full_mode_downgraded_to_bootstrap', v_detail_mode = 'FULL' AND v_large_batch = true,
        'large_batch', v_large_batch,
        'large_batch_reasons', v_large_batch_reasons,
        'available_sections', v_available_sections,
        'recommended_page_size', v_effective_page_size,
        'id', v_batch.id::text,
        'pay_batch_id', v_batch.id::text,
        'status', v_batch.status,
        'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
        'batch_kind', v_batch_kind,
        'batch_kind_fixed', v_batch.batch_kind_fixed,
        'pay_channel', v_batch_kind,
        'pay_channels_present', COALESCE(v_pay_channels_present, '[]'::jsonb),
        'execution_commit_state', v_batch.execution_commit_state
      )
      || jsonb_build_object(
        'candidate_count', COALESCE(v_candidate_count, 0),
        'item_count', COALESCE(v_item_count, 0),
        'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
        'transfer_count', COALESCE(v_transfer_count, 0),
        'total_amount', COALESCE(v_total_amount, 0),
        'total_bank_out', COALESCE(v_batch.total_bank_out, COALESCE(v_total_amount, 0)),
        'provider_environment_summary', v_provider_environment_summary,
        'submitted_transfer_count', COALESCE(v_provider_submitted_transfer_count, 0),
        'provider_submitted_transfer_count', COALESCE(v_provider_submitted_transfer_count, 0),
        'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
        'pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
        'failed_transfer_count', COALESCE(v_failed_transfer_count, 0),
        'ambiguous_transfer_count', COALESCE(v_ambiguous_transfer_count, 0),
        'attempted_but_unproven_transfer_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
        'attempted_but_unproven_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
        'remittance_summary', v_remittance_status_summary,
        'settlement_summary', v_settlement_status_summary,
        'active_operation', CASE
          WHEN v_active_operation_id IS NULL THEN NULL::jsonb
          ELSE jsonb_build_object(
            'id', v_active_operation_id::text,
            'operation_id', v_active_operation_id::text,
            'operation_type', v_active_operation_type,
            'status', v_active_operation_status,
            'phase', v_active_operation_phase,
            'progress_json', COALESCE(v_active_operation_progress, '{}'::jsonb)
          )
        END,
        'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
        'payment_execution_review', v_payment_execution_review,
        'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
        'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
        'review_reason_code', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_review_reason_code ELSE NULL::text END,
        'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
        'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
        'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
        'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
        'payment_issues', COALESCE(v_payment_issues, '[]'::jsonb) || CASE WHEN v_provider_submit_issue_present AND v_provider_submit_payment_issue IS NOT NULL THEN jsonb_build_array(v_provider_submit_payment_issue) ELSE '[]'::jsonb END,
        'db_status', v_batch.status,
        'payment_lifecycle_state', v_batch_payment_lifecycle_state,
        'payment_lifecycle_label', v_batch_payment_lifecycle_label,
        'recommended_action', v_batch_recommended_action,
        'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
        'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
        'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
        'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
        'retry_state', v_retry_state,
        'retry_after_utc', v_retry_after_utc,
        'retry_reason', v_retry_reason,
        'next_retry_description', v_next_retry_description,
        'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
        'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
        'retry_in_progress', COALESCE(v_retry_in_progress, false),
        'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
        'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
        'retry_operation_status', v_retry_operation_status,
        'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
        'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
        'retry_status_label', v_retry_status_label,
        'retry_button_label', v_retry_button_label,
        'retry_button_visible', COALESCE(v_retry_button_visible, false),
        'retry_button_disabled_reason', v_retry_button_disabled_reason,
        'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
        'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
        'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
        'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
        'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
        'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
        'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb)
      )
      || jsonb_build_object(
        'live_signal_version', COALESCE(v_batch_signal_version, 0),
        'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
        'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
        'alert_version', COALESCE(v_batch_alert_version, 0),
        'overview_version', COALESCE(v_batch_overview_version, 0),
        'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
        'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
        'retry_in_progress', COALESCE(v_retry_in_progress, false),
        'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
        'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
        'retry_operation_status', v_retry_operation_status,
        'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
        'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
        'retry_status_label', v_retry_status_label,
        'retry_button_label', v_retry_button_label,
        'retry_button_visible', COALESCE(v_retry_button_visible, false),
        'retry_button_disabled_reason', v_retry_button_disabled_reason,
        'last_status_hash', v_batch_last_status_hash,
        'last_alert_hash', v_batch_last_alert_hash,
        'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb)
      )
      || jsonb_build_object(
        'freshness', jsonb_build_object(
          'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
          'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
          'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
          'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
          'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
          'freshness_is_stale', COALESCE(v_freshness_is_stale, false),
          'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
          'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
        ),
        'can_create_bank_csv_file', COALESCE(v_can_create_bank_csv_file, false),
        'can_start_standard_execution', COALESCE(v_can_start_standard_execution, false),
        'can_start_csv_settlement', COALESCE(v_can_start_csv_settlement, false),
        'can_start_external_settlement', COALESCE(v_can_start_external_settlement, false),
        'has_external_submission_evidence', COALESCE(v_has_external_submission_evidence, false),
        'has_cloudtms_csv_export', COALESCE(v_has_cloudtms_csv_export, false),
        'active_effective_item_count', COALESCE(v_active_effective_item_count, 0),
        'active_effective_amount_ex_vat', COALESCE(v_active_effective_amount_ex_vat, 0),
        'active_effective_amount_inc_vat', COALESCE(v_active_effective_amount_inc_vat, 0),
        'active_item_count', COALESCE(v_active_effective_item_count, 0),
        'active_batch_item_count', COALESCE(v_active_effective_item_count, 0),
        'active_payment_item_count', COALESCE(v_active_effective_item_count, 0),
        'active_bank_out', COALESCE(v_active_effective_amount_ex_vat, 0),
        'payment_issue_candidate_count', COALESCE(v_payment_issue_candidate_count, 0),
        'has_payment_issue_candidates', COALESCE(v_payment_issue_candidate_count, 0) > 0
      )
      || jsonb_build_object(
        'batch', (
          (jsonb_build_object(
            'id', v_batch.id::text,
            'bootstrap_only', true,
            'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
            'status', v_batch.status,
            'db_status', v_batch.status,
            'payment_lifecycle_state', v_batch_payment_lifecycle_state,
            'payment_lifecycle_label', v_batch_payment_lifecycle_label,
            'recommended_action', v_batch_recommended_action,
            'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
            'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
            'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
            'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
            'retry_state', v_retry_state,
            'retry_after_utc', v_retry_after_utc,
            'retry_reason', v_retry_reason,
            'next_retry_description', v_next_retry_description,
            'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
            'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
            'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
            'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
            'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
            'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
            'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb),
            'live_signal_version', COALESCE(v_batch_signal_version, 0),
            'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
            'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
            'alert_version', COALESCE(v_batch_alert_version, 0),
            'overview_version', COALESCE(v_batch_overview_version, 0),
            'last_status_hash', v_batch_last_status_hash,
            'last_alert_hash', v_batch_last_alert_hash,
            'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb),
            'batch_kind', v_batch_kind,
            'batch_kind_fixed', v_batch.batch_kind_fixed,
            'pay_channel', v_batch_kind,
            'pay_channels_present', COALESCE(v_pay_channels_present, '[]'::jsonb),
            'execution_commit_state', v_batch.execution_commit_state,
            'execution_commit_ref', v_batch.execution_commit_ref,
            'execution_committed_at_utc', v_batch.execution_committed_at_utc,
            'created_at_utc', v_batch.created_at_utc,
            'created_by_user_id', CASE WHEN v_batch.created_by_user_id IS NULL THEN NULL ELSE v_batch.created_by_user_id::text END) || jsonb_build_object(
            'authoritative_payment_date', CASE WHEN v_batch.authoritative_payment_date IS NULL THEN NULL ELSE v_batch.authoritative_payment_date::text END,
            'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
            'same_week_paye_override_used', v_batch.same_week_paye_override_used,
            'same_week_paye_override_reason', v_batch.same_week_paye_override_reason,
            'same_week_paye_override_verified_at_utc', v_batch.same_week_paye_override_verified_at_utc,
            'same_week_paye_override_verified_by_user_id', CASE WHEN v_batch.same_week_paye_override_verified_by_user_id IS NULL THEN NULL ELSE v_batch.same_week_paye_override_verified_by_user_id::text END,
            'source_workbench_session_id', CASE WHEN v_batch.source_workbench_session_id IS NULL THEN NULL ELSE v_batch.source_workbench_session_id::text END,
            'source_snapshot_run_id', CASE WHEN v_batch.source_snapshot_run_id IS NULL THEN NULL ELSE v_batch.source_snapshot_run_id::text END,
            'source_session_version', v_batch.source_session_version,
            'banking_system_snapshot', v_batch.banking_system_snapshot,
            'external_paye_system_snapshot', v_batch.external_paye_system_snapshot
          ))
          || jsonb_build_object(
            'total_bank_out', COALESCE(v_batch.total_bank_out, COALESCE(v_total_amount, 0)),
            'candidate_count', COALESCE(v_candidate_count, 0),
            'item_count', COALESCE(v_item_count, 0),
            'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
            'transfer_count', COALESCE(v_transfer_count, 0),
            'provider_submitted_transfer_count', COALESCE(v_provider_submitted_transfer_count, 0),
            'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
            'pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
            'failed_transfer_count', COALESCE(v_failed_transfer_count, 0),
            'ambiguous_transfer_count', COALESCE(v_ambiguous_transfer_count, 0),
            'attempted_but_unproven_transfer_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
            'attempted_but_unproven_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
            'rail_provider_snapshot', v_batch.rail_provider_snapshot,
            'rail_env_snapshot', v_batch.rail_env_snapshot,
            'provider_environment_summary', v_provider_environment_summary,
            'schedule_kind', v_batch.schedule_kind,
            'scheduled_at_utc', v_batch.scheduled_at_utc,
            'scheduled_by_user_id', CASE WHEN v_batch.scheduled_by_user_id IS NULL THEN NULL ELSE v_batch.scheduled_by_user_id::text END,
            'executing_started_at_utc', v_batch.executing_started_at_utc,
            'completed_at_utc', v_batch.completed_at_utc,
            'cancelled_at_utc', v_batch.cancelled_at_utc,
            'cancelled_by_user_id', CASE WHEN v_batch.cancelled_by_user_id IS NULL THEN NULL ELSE v_batch.cancelled_by_user_id::text END,
            'cancel_reason', v_batch.cancel_reason,
            'funding_account_ref', v_batch.funding_account_ref,
            'bulk_ref_num', v_batch.bulk_ref_num,
            'bulk_ref_date', CASE WHEN v_batch.bulk_ref_date IS NULL THEN NULL ELSE v_batch.bulk_ref_date::text END,
            'bulk_reference', v_batch.bulk_reference
          )
          || jsonb_build_object(
            'bank_csv_export_available', v_has_cloudtms_csv_export,
            'bank_csv_export_transfer_hash', CASE
              WHEN v_batch.bank_csv_export_json IS NOT NULL
               AND jsonb_typeof(v_batch.bank_csv_export_json) = 'object'
              THEN NULLIF(btrim(coalesce(v_batch.bank_csv_export_json ->> 'transfer_hash', '')), '')
              ELSE NULL::text
            END,
            'execution_intent_present', v_batch.execution_intent_json IS NOT NULL,
            'settlement_confirmation_present', v_batch.settlement_confirmation_json IS NOT NULL,
            'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
            'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
            'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
            'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
            'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
            'freshness_is_stale', COALESCE(v_freshness_is_stale, false),
            'can_create_bank_csv_file', COALESCE(v_can_create_bank_csv_file, false),
            'can_start_standard_execution', COALESCE(v_can_start_standard_execution, false),
            'can_start_csv_settlement', COALESCE(v_can_start_csv_settlement, false),
            'can_start_external_settlement', COALESCE(v_can_start_external_settlement, false),
            'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
            'payment_execution_review', v_payment_execution_review,
            'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
            'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
            'review_reason_code', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_review_reason_code ELSE NULL::text END,
            'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
            'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
            'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
            'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
            'payment_issues', COALESCE(v_payment_issues, '[]'::jsonb) || CASE WHEN v_provider_submit_issue_present AND v_provider_submit_payment_issue IS NOT NULL THEN jsonb_build_array(v_provider_submit_payment_issue) ELSE '[]'::jsonb END
          )
        ),
        'candidates', NULL::jsonb,
        'items', NULL::jsonb,
        'transfers', NULL::jsonb
      );
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_pay_batch_get_candidate_effective;
  CREATE TEMP TABLE _tmp_pay_batch_get_candidate_effective ON COMMIT DROP AS
  WITH item_scope AS (
    SELECT
      pbc_effective.id AS pay_batch_candidate_id,
      pbc_effective.candidate_id,
      pbi_effective.id AS pay_batch_item_id,
      pbi_effective.item_type,
      pbi_effective.amount_ex_vat,
      pbi_effective.amount_inc_vat,
      COALESCE(pbi_effective.is_voided, false) AS is_voided,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS precancel_items
        WHERE precancel_items.pay_batch_item_id = pbi_effective.id
          AND precancel_items.status = 'APPLIED'
          AND precancel_items.correction_item_kind = 'PRE_BANK_CANCEL'
      ) AS has_precancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS unwind_items
        WHERE unwind_items.pay_batch_item_id = pbi_effective.id
          AND unwind_items.status = 'APPLIED'
          AND unwind_items.correction_item_kind = 'NO_MONEY_UNWIND'
      ) AS has_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS reversal_items
        WHERE reversal_items.pay_batch_item_id = pbi_effective.id
          AND reversal_items.status = 'APPLIED'
          AND reversal_items.correction_item_kind = 'SETTLED_REVERSAL'
      ) AS has_settled_reversal
    FROM public.pay_batch_candidates AS pbc_effective
    LEFT JOIN public.pay_batch_items AS pbi_effective
      ON pbi_effective.pay_batch_candidate_id = pbc_effective.id
    WHERE pbc_effective.pay_batch_id = p_pay_batch_id
  ), candidate_effective AS (
    SELECT
      item_scope.pay_batch_candidate_id,
      item_scope.candidate_id,
      COUNT(item_scope.pay_batch_item_id)::integer AS total_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (
        WHERE item_scope.pay_batch_item_id IS NOT NULL
          AND COALESCE(item_scope.is_voided, false) = false
          AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
      )::integer AS active_effective_item_count,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
           AND COALESCE(item_scope.is_voided, false) = false
           AND NOT (item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS active_effective_amount_inc_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
          THEN COALESCE(item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS original_frozen_amount_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN item_scope.pay_batch_item_id IS NOT NULL
           AND item_scope.item_type <> 'DEBT_CREATED'
          THEN COALESCE(item_scope.amount_inc_vat, item_scope.amount_ex_vat, 0)
          ELSE 0
        END
      ), 0), 2)::numeric AS original_frozen_amount_inc_vat,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_precancel)::integer AS applied_precancel_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_no_money_unwind)::integer AS applied_unwind_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_settled_reversal)::integer AS applied_reversal_item_count,
      COUNT(item_scope.pay_batch_item_id) FILTER (WHERE item_scope.has_precancel OR item_scope.has_no_money_unwind OR item_scope.has_settled_reversal)::integer AS corrected_item_count
    FROM item_scope
    GROUP BY item_scope.pay_batch_candidate_id, item_scope.candidate_id
  )
  SELECT
    candidate_effective.pay_batch_candidate_id,
    candidate_effective.candidate_id,
    COALESCE(candidate_effective.total_item_count, 0)::integer AS total_item_count,
    COALESCE(candidate_effective.active_effective_item_count, 0)::integer AS active_effective_item_count,
    COALESCE(candidate_effective.active_effective_amount_ex_vat, 0)::numeric AS active_effective_amount_ex_vat,
    COALESCE(candidate_effective.active_effective_amount_inc_vat, 0)::numeric AS active_effective_amount_inc_vat,
    COALESCE(candidate_effective.original_frozen_amount_ex_vat, 0)::numeric AS original_frozen_amount_ex_vat,
    COALESCE(candidate_effective.original_frozen_amount_inc_vat, 0)::numeric AS original_frozen_amount_inc_vat,
    COALESCE(candidate_effective.applied_precancel_item_count, 0)::integer AS applied_precancel_item_count,
    COALESCE(candidate_effective.applied_unwind_item_count, 0)::integer AS applied_unwind_item_count,
    COALESCE(candidate_effective.applied_reversal_item_count, 0)::integer AS applied_reversal_item_count,
    COALESCE(candidate_effective.corrected_item_count, 0)::integer AS corrected_item_count,
    (COALESCE(candidate_effective.corrected_item_count, 0) > 0) AS payment_issue_badge,
    (
      COALESCE(candidate_effective.corrected_item_count, 0) > 0
      AND COALESCE(candidate_effective.active_effective_item_count, 0) = 0
    ) AS current_effective_zero,
    CASE
      WHEN COALESCE(candidate_effective.applied_reversal_item_count, 0) > 0 THEN 'Overpayment recovery applied'
      WHEN COALESCE(candidate_effective.applied_unwind_item_count, 0) > 0 THEN 'Financials rewound'
      WHEN COALESCE(candidate_effective.applied_precancel_item_count, 0) > 0 THEN 'Cancelled before bank submission'
      ELSE NULL::text
    END AS payment_issue_label,
    COALESCE((
      SELECT jsonb_agg(issue_kind_values.issue_kind ORDER BY issue_kind_values.issue_kind)
      FROM (
        SELECT 'PRE_BANK_CANCEL'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_precancel_item_count, 0) > 0
        UNION ALL
        SELECT 'NO_MONEY_UNWIND'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_unwind_item_count, 0) > 0
        UNION ALL
        SELECT 'SETTLED_REVERSAL'::text AS issue_kind WHERE COALESCE(candidate_effective.applied_reversal_item_count, 0) > 0
      ) AS issue_kind_values
    ), '[]'::jsonb) AS payment_issue_kinds
  FROM candidate_effective;

  SELECT
    COALESCE(SUM(COALESCE(candidate_effective.active_effective_item_count, 0)), 0)::integer,
    ROUND(COALESCE(SUM(COALESCE(candidate_effective.active_effective_amount_ex_vat, 0)), 0), 2)::numeric,
    ROUND(COALESCE(SUM(COALESCE(candidate_effective.active_effective_amount_inc_vat, 0)), 0), 2)::numeric,
    COUNT(*) FILTER (WHERE COALESCE(candidate_effective.payment_issue_badge, false))::integer
  INTO
    v_active_effective_item_count,
    v_active_effective_amount_ex_vat,
    v_active_effective_amount_inc_vat,
    v_payment_issue_candidate_count
  FROM pg_temp._tmp_pay_batch_get_candidate_effective AS candidate_effective;

  -- ✅ C: load schedule defaults for UI preselect (do not change batch state)
  select
    sd.default_schedule_umbrella_local,
    sd.default_schedule_paye_local,
    sd.funds_warning_hours_json,
    sd.rail_default_funding_account_ref
  into
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_rail_default_funding_account_ref
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  -- ✅ D: authorisation summary (latest active request if present)
  v_auth := jsonb_build_object(
    'auth_request_id', null,
    'auth_state', null,
    'required_quantity', null,
    'approved_count', 0,
    'approved_by', '[]'::jsonb,
    'invited_to', '[]'::jsonb,
    'golden_key_used', false,
    'golden_key_user_id', null,
    'execution_intent_json', null,
    'execution_mode', null,
    'suppress_remittances', false
  );

  select
    pbar0.id as auth_request_id,
    pbar0.state as auth_state,
    pbar0.required_quantity as required_quantity,
    pbar0.golden_key_used as golden_key_used,
    pbar0.golden_key_user_id as golden_key_user_id,
    pbar0.execution_intent_json as execution_intent_json
  into v_ar
  from public.pay_batch_auth_requests pbar0
  where pbar0.pay_batch_id = p_pay_batch_id
    and pbar0.state in ('AWAITING','AUTHORISED')
  order by pbar0.created_at_utc desc, pbar0.id desc
  limit 1;

  if v_ar.auth_request_id is not null then
    if v_ar.execution_intent_json is not null and jsonb_typeof(v_ar.execution_intent_json) = 'object' then
      v_active_auth_execution_intent_json := v_ar.execution_intent_json;
    else
      v_active_auth_execution_intent_json := null;
    end if;

    select count(*)::int
    into v_auth_approved_count
    from public.pay_batch_auth_actions pbaa0
    where pbaa0.auth_request_id = v_ar.auth_request_id
      and pbaa0.action in ('AUTHORISE','USE_GOLDEN_KEY');

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'actor_user_id', pbaa1.actor_user_id::text,
          'actor_display_name', tu1.display_name,
          'action', pbaa1.action,
          'action_at_utc', pbaa1.action_at_utc,
          'note', pbaa1.note
        )
        order by pbaa1.action_at_utc asc nulls last, pbaa1.id asc
      ),
      '[]'::jsonb
    )
    into v_auth_approved_by
    from public.pay_batch_auth_actions pbaa1
    left join public.tms_users tu1
      on tu1.id = pbaa1.actor_user_id
    where pbaa1.auth_request_id = v_ar.auth_request_id;

    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'target_user_id', pbat0.target_user_id::text,
          'target_display_name', tu2.display_name,
          'invited_at_utc', pbat0.created_at_utc,
          'expires_at_utc', pbat0.expires_at_utc,
          'used_at_utc', pbat0.used_at_utc
        )
        order by pbat0.created_at_utc asc nulls last, pbat0.token asc
      ),
      '[]'::jsonb
    )
    into v_auth_invited_to
    from public.pay_batch_auth_tokens pbat0
    left join public.tms_users tu2
      on tu2.id = pbat0.target_user_id
    where pbat0.auth_request_id = v_ar.auth_request_id;

    v_auth := jsonb_build_object(
      'auth_request_id', v_ar.auth_request_id::text,
      'auth_state', v_ar.auth_state,
      'required_quantity', v_ar.required_quantity,
      'approved_count', v_auth_approved_count,
      'approved_by', v_auth_approved_by,
      'invited_to', v_auth_invited_to,
      'golden_key_used', coalesce(v_ar.golden_key_used,false),
      'golden_key_user_id', case when v_ar.golden_key_user_id is null then null else v_ar.golden_key_user_id::text end,
      'execution_intent_json', v_active_auth_execution_intent_json,
      'execution_mode', case when v_active_auth_execution_intent_json is null then null else v_active_auth_execution_intent_json->>'execution_mode' end,
      'suppress_remittances', lower(btrim(coalesce(v_active_auth_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on')
    );
  end if;

  -- Candidates + PAYE net input summary (latest per candidate)
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
          'id',
          pbc.id::text,
          'candidate_id',
          pbc.candidate_id::text,
          'candidate_tms_ref',
          pbc.candidate_tms_ref,
          'candidate_display_name',
          pbc.candidate_display_name,
          'paye_state',
          pbc.paye_state,
          'mismatch_settlement_choice',
          pbc.mismatch_settlement_choice,
          'original_gross_preview',
          pbc.gross_preview,
          'original_net_bank_amount',
          pbc.net_bank_amount,
          'gross_preview',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'net_bank_amount',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'current_effective_gross_preview',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'current_effective_net_bank_amount',
          case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'current_effective_item_count',
          coalesce(ce.active_effective_item_count, 0),
          'active_effective_item_count',
          coalesce(ce.active_effective_item_count, 0),
          'total_item_count',
          coalesce(ce.total_item_count, 0),
          'current_effective_amount_ex_vat',
          coalesce(ce.active_effective_amount_ex_vat, 0),
          'current_effective_amount_inc_vat',
          coalesce(ce.active_effective_amount_inc_vat, 0),
          'original_frozen_amount_ex_vat',
          coalesce(ce.original_frozen_amount_ex_vat, 0),
          'original_frozen_amount_inc_vat',
          coalesce(ce.original_frozen_amount_inc_vat, 0),
          'payment_issue_badge',
          coalesce(ce.payment_issue_badge, false),
          'payment_issue_badge_label',
          case when coalesce(ce.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
          'payment_issue_label',
          ce.payment_issue_label,
          'payment_issue_kinds',
          coalesce(ce.payment_issue_kinds, '[]'::jsonb),
          'payment_lifecycle_state',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state),
          'payment_lifecycle_label',
          CASE COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state)
          WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
          WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
          WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
          WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
          WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
          WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
          WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
          WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
          WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
          ELSE initcap(replace(lower(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
        END,
          'recommended_action',
          candidate_payment_diagnostic.diagnostic_json->>'recommended_action',
          'row_action',
          CASE
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
            ELSE candidate_payment_diagnostic.diagnostic_json->>'recommended_action'
          END,
          'row_action_label',
          CASE
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
            WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
            ELSE 'View details'
          END,
          'retry_row_context',
          CASE WHEN candidate_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OVERVIEW_ONLY' ELSE NULL::text END,
          'row_cancel_available',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
          'can_no_money_unwind',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
          'can_recover_overpayment',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustment_carry_forward_required',
          lower(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustments_to_carry_forward',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
          'manual_adjustments_carried_forward',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
          'carry_forward_blockers',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
          'blocking_paid_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
          'terminal_no_money_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
          'pending_provider_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
          'resolved_full_payment_scope_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
          'finance_scope_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
          'provider_failure_reason_group',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
          'provider_failure_reason_label',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), '')
        )
        || jsonb_build_object(
          'status_update_signature',
          NULLIF(btrim(COALESCE(candidate_payment_diagnostic.diagnostic_json->>'status_update_signature', candidate_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
          'provider_outcome_unknown_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
          'provider_webhook_evidence_json',
          COALESCE(candidate_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
          'applied_precancel_item_count',
          coalesce(ce.applied_precancel_item_count, 0),
          'applied_unwind_item_count',
          coalesce(ce.applied_unwind_item_count, 0),
          'applied_reversal_item_count',
          coalesce(ce.applied_reversal_item_count, 0),
          'corrected_item_count',
          coalesce(ce.corrected_item_count, 0),
          'debt_created',
          pbc.debt_created,
          'overpayment_recovery_taken',
          pbc.overpayment_recovery_taken,
          'loan_repayment_taken',
          pbc.loan_repayment_taken,
          'awaiting_net_amount',
          case when v_batch_kind_fixed = 'LOANS' then false else coalesce(pbc.awaiting_net_amount,false) end,
          'settlement_status',
          pbc.settlement_status,
          'settled_at_utc',
          pbc.settled_at_utc,
          'settled_via',
          pbc.settled_via,
          'settled_note',
          pbc.settled_note,
          'remittance_sent_at_utc',
          pbc.remittance_sent_at_utc,
          'remittance_sent_by_user_id',
          case when pbc.remittance_sent_by_user_id is null then null else pbc.remittance_sent_by_user_id::text end,
          'remittance_trigger_status',
          pbc.remittance_trigger_status,
          'last_remittance_error',
          pbc.last_remittance_error,
          -- Latest PAYE net input summary
        'paye_net_amount',
          ni.net_amount,
          'paye_net_source',
          ni.source,
          'paye_net_imported_at_utc',
          ni.imported_at_utc,
          'paye_net_file_name',
          ni.file_name,
          -- ✅ NEW: explicit deductions summary for child modal / UI
        'deductions_summary',
          jsonb_build_object(
          'gross_positive', case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.gross_preview end,
          'manual_debt_recovery', coalesce(fs.manual_debt_recovery,0),
          'manual_debt_net_deductions', coalesce(fs.manual_debt_net_deductions,0),
          'payment_advance_repayment', coalesce(fs.payment_advance_repayment,0),
          'loan_repayment', coalesce(fs.payment_advance_repayment,0),
          'repayment', coalesce(fs.repayment,0),
          'overpayment_recovery', coalesce(fs.overpayment_recovery,0),
          'final_payable', case when coalesce(ce.current_effective_zero, false) then 0::numeric else pbc.net_bank_amount end,
          'awaiting_net_amount', case when v_batch_kind_fixed = 'LOANS' then false else coalesce(pbc.awaiting_net_amount,false) end,
          'paye_net_amount', ni.net_amount
        ),
          'finance_summary',
          jsonb_build_object(
          'gross_additions_ex_vat', coalesce(fs.gross_additions_ex_vat,0),
          'gross_deductions_ex_vat', coalesce(fs.gross_deductions_ex_vat,0),
          'net_deductions_ex_vat', coalesce(fs.net_deductions_ex_vat,0)
        )
        )
      order by pbc.candidate_display_name nulls last, pbc.candidate_tms_ref nulls last, pbc.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidates
  from public.pay_batch_candidates pbc
  left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
    on ce.pay_batch_candidate_id = pbc.id
  left join lateral (
    select
      pni.net_amount,
      pni.source,
      pni.imported_at_utc,
      pni.file_name
    from public.pay_batch_paye_net_inputs pni
    where pni.pay_batch_candidate_id = pbc.id
    order by pni.imported_at_utc desc
    limit 1
  ) ni on true
  left join lateral (
    select
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_recovery,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_net_deductions,
      round(coalesce(sum(case when pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as payment_advance_repayment,
      round(coalesce(sum(case when pbi.item_type = 'OVERPAYMENT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as overpayment_recovery,
      round(coalesce(sum(case when (pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') or (pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as repayment
    from public.pay_batch_items pbi
    where pbi.pay_batch_candidate_id = pbc.id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ) fs on true
  left join lateral (
    select public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object(
        'scope_type', 'CANDIDATES',
        'pay_batch_candidate_ids', jsonb_build_array(pbc.id::text),
        'candidate_ids', jsonb_build_array(pbc.candidate_id::text)
      ),
      p_actor_user_id
    ) as diagnostic_json
  ) AS candidate_payment_diagnostic ON true
  where pbc.pay_batch_id = p_pay_batch_id;

  -- Transfers + snapshot fields + rail-generic fields
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'candidate_id', case when pbt.candidate_id is null then null else pbt.candidate_id::text end,
        'umbrella_id', case when pbt.umbrella_id is null then null else pbt.umbrella_id::text end,
        'pay_channel', pbt.pay_channel,
        'amount', pbt.amount,
        'currency', pbt.currency,
        'status', pbt.status,

        -- Rail-generic equivalents
        'rail_provider', pbt.rail_provider,
        'rail_env', pbt.rail_env,
        'request_id', pbt.request_id,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,

        -- Snapshot bank fields
        'payment_reference', pbt.payment_reference,
        'payee_name', pbt.payee_name,
        'sort_code', pbt.sort_code,
        'account_number', pbt.account_number,
        'account_type', pbt.account_type,
        'bank_details_hash_snapshot', pbt.bank_details_hash_snapshot,

        -- Drilldown/grouping fields
        'transfer_group_key', pbt.transfer_group_key,
        'grouping_mode_used', pbt.grouping_mode_used,
        'week_ending_bucket', case when pbt.week_ending_bucket is null then null else pbt.week_ending_bucket::text end,

        'created_at_utc', pbt.created_at_utc,
        'completed_at_utc', pbt.completed_at_utc,
        'payment_lifecycle_state', COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state),
        'payment_lifecycle_label', CASE COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state)
          WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Prepared locally — not sent to bank'
          WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled locally — not sent to bank'
          WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check bank'
          WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Provider cancelled — no money moved'
          WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Provider failed — no money moved'
          WHEN 'PAID_OR_SETTLED' THEN 'Paid or settled'
          WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
          WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
          WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
          ELSE initcap(replace(lower(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', v_batch_payment_lifecycle_state, 'unknown')), '_', ' '))
        END,
        'recommended_action', transfer_payment_diagnostic.diagnostic_json->>'recommended_action',
        'row_action', CASE
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
          ELSE transfer_payment_diagnostic.diagnostic_json->>'recommended_action'
        END,
        'row_action_label', CASE
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
          WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
          ELSE 'View details'
        END,
        'retry_row_context', CASE WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OVERVIEW_ONLY' ELSE NULL::text END,
        'row_cancel_available', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
        'can_no_money_unwind', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
        'can_recover_overpayment', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
        'manual_adjustment_carry_forward_required', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
        'manual_adjustments_to_carry_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
        'manual_adjustments_carried_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
        'carry_forward_blockers', COALESCE(transfer_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
        'blocking_paid_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
        'terminal_no_money_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
        'pending_provider_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
        'resolved_full_payment_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
        'finance_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
        'provider_failure_reason_group', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
        'provider_failure_reason_label', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), ''),
        'status_update_signature', NULLIF(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'status_update_signature', transfer_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
        'provider_outcome_unknown_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
        'provider_webhook_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
        'failed_reason', pbt.failed_reason
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_transfers
  from public.pay_bank_transfers pbt
  left join lateral (
    select public.pay_payment_cancelability_diagnostic(
      p_pay_batch_id,
      jsonb_build_object(
        'scope_type', 'TRANSFER',
        'pay_bank_transfer_ids', jsonb_build_array(pbt.id::text)
      ),
      p_actor_user_id
    ) as diagnostic_json
  ) AS transfer_payment_diagnostic ON true
  where pbt.pay_batch_id = p_pay_batch_id;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_pending_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_hash.status,'')) = 'PENDING'
    order by pbt_hash.id
  ) transfer_hash_rows;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_stable_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_hash.status,'')) <> 'BLOCKED'
    order by pbt_hash.id
  ) transfer_hash_rows;

  v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch.bank_csv_export_json->>'transfer_hash', '')), '');
  v_execution_transfer_hash := nullif(btrim(coalesce(v_execution_intent_json->>'current_transfer_hash', '')), '');
  v_has_cloudtms_csv_export := (
    v_batch.bank_csv_export_json is not null
    and jsonb_typeof(v_batch.bank_csv_export_json) = 'object'
    and v_bank_csv_export_hash is not null
  );

  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      'ALL'::text,
      NULL::uuid,
      true
    ) AS classification_row
  ), classified_rows_with_sample AS (
    SELECT
      classified_rows.*,
      row_number() OVER (
        ORDER BY
          CASE
            WHEN classified_rows.evidence_classification IN ('local_only_evidence', 'attempted_but_unproven', 'ambiguous', 'failed', 'pending', 'scope_without_transfer') THEN 0
            ELSE 1
          END,
          classified_rows.pay_bank_transfer_id NULLS LAST,
          classified_rows.scope_id NULLS LAST
      ) AS evidence_sample_ordinality
    FROM classified_rows
  ), evidence_counts AS (
    SELECT
      count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer AS transfer_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'provider_evidence_present')::integer AS provider_submitted_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'local_only_evidence')::integer AS local_only_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'pending')::integer AS pending_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'failed' OR classified_rows.is_failed_or_blocked IS TRUE)::integer AS failed_count,
      count(*) FILTER (WHERE classified_rows.evidence_classification = 'ambiguous' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer AS ambiguous_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS attempted_but_unproven_count,
      count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer AS provider_attempt_without_external_id_count,
      count(*) FILTER (
        WHERE classified_rows.evidence_classification = 'ambiguous'
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS requires_provider_poll_count,
      count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer AS committed_count,
      COALESCE(bool_or(
        EXISTS (
          SELECT 1
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
            AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        )
      ), false) AS has_rail_tx_id,
      COALESCE(bool_or(classified_rows.has_local_prepare_identity IS TRUE), false) AS has_local_generated_request_identity,
      COALESCE(bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE), false) AS has_external_submission_evidence,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_count,
      count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer AS authorisation_ready_transfer_count,
      count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer AS unattempted_submit_eligible_count,
      count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer AS safe_local_cleanup_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_provider_attempt_without_external_id IS TRUE
      )::integer AS provider_attempt_or_evidence_count,
      count(*) FILTER (
        WHERE classified_rows.has_provider_submission_evidence IS TRUE
           OR classified_rows.has_provider_event_evidence IS TRUE
           OR classified_rows.has_ambiguous_external_evidence IS TRUE
      )::integer AS provider_or_ambiguous_evidence_count,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND true), '[]'::jsonb) AS evidence_sample,
      COALESCE(jsonb_agg(
        jsonb_strip_nulls(jsonb_build_object(
          'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
          'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
          'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
          'pay_channel', classified_rows.pay_channel,
          'evidence_classification', classified_rows.evidence_classification,
          'status', classified_rows.status_upper,
          'rail_state', classified_rows.rail_state_upper,
          'has_route_ready', classified_rows.has_route_ready,
          'has_local_prepare_identity', classified_rows.has_local_prepare_identity,
          'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
          'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
          'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
          'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
          'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
          'is_failed_or_blocked', classified_rows.is_failed_or_blocked,
          'is_terminal_or_completed', classified_rows.is_terminal_or_completed,
          'is_authorisation_ready', classified_rows.is_authorisation_ready,
          'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
          'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
          'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
          'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
          'has_different_operation_scope', classified_rows.has_different_operation_scope,
          'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
          'unsafe_reason', classified_rows.unsafe_reason
        ))
        ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
      ) FILTER (WHERE classified_rows.evidence_sample_ordinality <= 50 AND true), '[]'::jsonb) AS execution_classification_sample
    FROM classified_rows_with_sample AS classified_rows
  ), status_sets AS (
    SELECT
      COALESCE((
        SELECT jsonb_agg(status_item.status_value ORDER BY status_item.status_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.status, ''))) AS status_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.status, '')), '') IS NOT NULL
        ) AS status_item
      ), '[]'::jsonb) AS transfer_statuses,
      COALESCE((
        SELECT jsonb_agg(rail_state_item.rail_state_value ORDER BY rail_state_item.rail_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(transfer_row.rail_state, ''))) AS rail_state_value
          FROM public.pay_bank_transfers AS transfer_row
          WHERE transfer_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(transfer_row.rail_state, '')), '') IS NOT NULL
        ) AS rail_state_item
      ), '[]'::jsonb) AS transfer_rail_states,
      COALESCE((
        SELECT jsonb_agg(event_state_item.normalised_state_value ORDER BY event_state_item.normalised_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.normalised_state, ''))) AS normalised_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.normalised_state, '')), '') IS NOT NULL
        ) AS event_state_item
      ), '[]'::jsonb) AS event_normalised_states,
      COALESCE((
        SELECT jsonb_agg(provider_state_item.provider_state_value ORDER BY provider_state_item.provider_state_value)
        FROM (
          SELECT DISTINCT upper(btrim(coalesce(event_row.provider_state, ''))) AS provider_state_value
          FROM public.pay_bank_transfer_events AS event_row
          WHERE event_row.pay_batch_id = p_pay_batch_id
            AND nullif(btrim(coalesce(event_row.provider_state, '')), '') IS NOT NULL
        ) AS provider_state_item
      ), '[]'::jsonb) AS event_provider_states,
      (SELECT count(*)::integer FROM public.pay_bank_transfer_events AS event_row WHERE event_row.pay_batch_id = p_pay_batch_id) AS transfer_event_count
  ), prepared_counts AS (
    SELECT
      evidence_counts.*,
      status_sets.*,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_unattempted_submit_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) AS remaining_evidence_unresolved_count,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_submit_attempt_required,
      COALESCE(evidence_counts.pending_count, 0) + COALESCE(evidence_counts.local_only_count, 0) + COALESCE(evidence_counts.ambiguous_count, 0) + COALESCE(evidence_counts.attempted_but_unproven_count, 0) AS remaining_provider_evidence_required,
      COALESCE(evidence_counts.unattempted_submit_eligible_count, 0) AS remaining_provider_submission_required,
      (
        COALESCE(evidence_counts.transfer_count, 0) > 0
        AND COALESCE(evidence_counts.provider_submitted_count, 0) = COALESCE(evidence_counts.transfer_count, 0)
        AND COALESCE(evidence_counts.failed_count, 0) = 0
        AND COALESCE(evidence_counts.ambiguous_count, 0) = 0
        AND COALESCE(evidence_counts.local_only_count, 0) = 0
        AND COALESCE(evidence_counts.pending_count, 0) = 0
        AND COALESCE(evidence_counts.attempted_but_unproven_count, 0) = 0
      ) AS can_mark_submitted
    FROM evidence_counts
    CROSS JOIN status_sets
  )
  SELECT
    jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'counts_only', false,
      'transfer_count', COALESCE(prepared_counts.transfer_count, 0),
      'transfer_event_count', COALESCE(prepared_counts.transfer_event_count, 0),
      'has_transfer_events', COALESCE(prepared_counts.transfer_event_count, 0) > 0,
      'provider_submitted_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'provider_evidence_present_count', COALESCE(prepared_counts.provider_submitted_count, 0),
      'local_idempotency_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_count', COALESCE(prepared_counts.local_only_count, 0),
      'local_only_evidence_count', COALESCE(prepared_counts.local_only_count, 0),
      'pending_count', COALESCE(prepared_counts.pending_count, 0),
      'failed_count', COALESCE(prepared_counts.failed_count, 0),
      'ambiguous_count', COALESCE(prepared_counts.ambiguous_count, 0),
      'attempted_but_unproven_count', COALESCE(prepared_counts.attempted_but_unproven_count, 0),
      'provider_attempt_without_external_id_count', COALESCE(prepared_counts.provider_attempt_without_external_id_count, 0)
    )
    || jsonb_build_object(
      'requires_provider_poll_count', COALESCE(prepared_counts.requires_provider_poll_count, 0),
      'authorisation_ready_count', COALESCE(prepared_counts.authorisation_ready_count, 0),
      'authorisation_ready_transfer_count', COALESCE(prepared_counts.authorisation_ready_transfer_count, 0),
      'unattempted_submit_eligible_count', COALESCE(prepared_counts.unattempted_submit_eligible_count, 0),
      'safe_local_cleanup_count', COALESCE(prepared_counts.safe_local_cleanup_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(prepared_counts.provider_attempt_or_evidence_count, 0),
      'provider_or_ambiguous_evidence_count', COALESCE(prepared_counts.provider_or_ambiguous_evidence_count, 0),
      'cancellable_local_auth_request_count', 0,
      'non_cancellable_auth_request_count', 0,
      'same_operation_active_auth_request_count', 0,
      'other_operation_active_auth_request_count', 0,
      'auth_request_provider_risk_count', 0,
      'auth_request_retry_blocker_count', 0,
      'remaining_submit_attempt_required', COALESCE(prepared_counts.remaining_submit_attempt_required, 0),
      'remaining_unattempted_submit_required', COALESCE(prepared_counts.remaining_unattempted_submit_required, 0),
      'remaining_evidence_unresolved_count', COALESCE(prepared_counts.remaining_evidence_unresolved_count, 0)
    )
    || jsonb_build_object(
      'remaining_submit_attempt_required_definition', 'unattempted_submit_eligible_count',
      'remaining_provider_evidence_required', COALESCE(prepared_counts.remaining_provider_evidence_required, 0),
      'remaining_provider_submission_required', COALESCE(prepared_counts.remaining_provider_submission_required, 0),
      'submission_count_semantics', jsonb_build_object(
        'remaining_submit_attempt_required', 'count of transfers currently eligible for an unattempted provider submit',
        'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
        'pending_count', 'evidence-level pending classification, not submit eligibility'
      ),
      'batch_can_be_marked_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_submitted', COALESCE(prepared_counts.can_mark_submitted, false),
      'can_mark_committed', COALESCE(prepared_counts.can_mark_submitted, false) AND COALESCE(prepared_counts.committed_count, 0) = COALESCE(prepared_counts.transfer_count, 0),
      'has_rail_tx_id', COALESCE(prepared_counts.has_rail_tx_id, false),
      'has_local_generated_request_identity', COALESCE(prepared_counts.has_local_generated_request_identity, false),
      'has_external_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'no_submission_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) = false,
      'transfer_statuses', COALESCE(prepared_counts.transfer_statuses, '[]'::jsonb),
      'transfer_rail_states', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb),
      'event_normalised_states', COALESCE(prepared_counts.event_normalised_states, '[]'::jsonb),
      'event_provider_states', COALESCE(prepared_counts.event_provider_states, '[]'::jsonb)
    )
    || jsonb_build_object(
      'evidence_sample', CASE WHEN true THEN COALESCE(prepared_counts.evidence_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'execution_classification_sample', CASE WHEN true THEN COALESCE(prepared_counts.execution_classification_sample, '[]'::jsonb) ELSE '[]'::jsonb END,
      'has_possible_provider_attempt_evidence', COALESCE(prepared_counts.has_external_submission_evidence, false) OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_provider_attempt_request_or_idempotency_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_request_or_idempotency_reference', COALESCE(prepared_counts.local_only_count, 0) > 0 OR COALESCE(prepared_counts.provider_submitted_count, 0) > 0 OR COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0,
      'has_submitted_state', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_processing_state', COALESCE(prepared_counts.transfer_rail_states, '[]'::jsonb) ?| array['PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION'],
      'has_completed_state', COALESCE(prepared_counts.committed_count, 0) > 0,
      'has_failed_or_rejected_provider_state', COALESCE(prepared_counts.failed_count, 0) > 0,
      'has_unknown_or_timeout_state', COALESCE(prepared_counts.ambiguous_count, 0) > 0,
      'requires_provider_poll', COALESCE(prepared_counts.requires_provider_poll_count, 0) > 0,
      'requires_review', COALESCE(prepared_counts.ambiguous_count, 0) > 0 OR (COALESCE(prepared_counts.attempted_but_unproven_count, 0) > 0 AND COALESCE(prepared_counts.requires_provider_poll_count, 0) = 0),
      'has_provider_submission_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_payment_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transfer_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_provider_transaction_reference', COALESCE(prepared_counts.provider_submitted_count, 0) > 0,
      'has_external_payment_reference', COALESCE(prepared_counts.has_external_submission_evidence, false),
      'has_external_transfer_reference', COALESCE(prepared_counts.has_external_submission_evidence, false)
    )
  INTO v_submission_evidence
  FROM prepared_counts;

  v_has_external_submission_evidence := COALESCE(
    (v_submission_evidence ->> 'has_external_submission_evidence')::boolean,
    false
  );

  v_alert_actor_user_id := COALESCE(p_actor_user_id, '00000000-0000-0000-0000-000000000000'::uuid);

  v_alert_registry := public.banking_alerts_active_for_user(
    v_alert_actor_user_id,
    'pay_batch'::text,
    p_pay_batch_id,
    true,
    50
  );

  SELECT
    COALESCE(jsonb_agg(alert_scope.alert_json ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC), '[]'::jsonb),
    (array_agg(alert_scope.alert_json ->> 'alert_kind' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'severity' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'label' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_json ->> 'description' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    (array_agg(alert_scope.alert_fingerprint ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1],
    COALESCE(bool_and(alert_scope.acknowledged_for_current_user), false),
    COALESCE(bool_or(alert_scope.acknowledged_for_current_user = false), false)
  INTO
    v_banking_alerts,
    v_banking_alert_kind,
    v_banking_alert_severity,
    v_banking_alert_label,
    v_banking_alert_reason,
    v_banking_alert_fingerprint,
    v_banking_alert_acknowledged_for_user,
    v_banking_alert_requires_attention
  FROM (
    SELECT
      alert_items.alert_json,
      alert_items.alert_json ->> 'alert_fingerprint' AS alert_fingerprint,
      CASE
        WHEN (alert_items.alert_json ->> 'severity_rank') ~ '^[0-9]+$' THEN (alert_items.alert_json ->> 'severity_rank')::integer
        ELSE 0
      END AS severity_rank,
      CASE
        WHEN NULLIF(alert_items.alert_json ->> 'sort_at_utc', '') IS NULL THEN NULL::timestamptz
        ELSE (alert_items.alert_json ->> 'sort_at_utc')::timestamptz
      END AS sort_at_utc,
      COALESCE((alert_items.alert_json ->> 'acknowledged_for_current_user')::boolean, false) AS acknowledged_for_current_user
    FROM jsonb_array_elements(COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)) AS alert_items(alert_json)
    WHERE alert_items.alert_json ->> 'pay_batch_id' = p_pay_batch_id::text
  ) AS alert_scope;

  v_banking_alerts := COALESCE(v_banking_alerts, '[]'::jsonb);
  v_banking_alert_acknowledged_for_user := COALESCE(v_banking_alert_acknowledged_for_user, false);
  v_banking_alert_requires_attention := COALESCE(v_banking_alert_requires_attention, false);

  v_blocked_funds_required_gbp := CASE
    WHEN COALESCE(
      v_batch.last_funds_check_json #>> '{required_gbp}',
      v_batch.last_funds_check_json #>> '{required}',
      v_batch.last_funds_check_json #>> '{required_amount_gbp}',
      v_batch.last_funds_check_json #>> '{required_amount}'
    ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN COALESCE(
        v_batch.last_funds_check_json #>> '{required_gbp}',
        v_batch.last_funds_check_json #>> '{required}',
        v_batch.last_funds_check_json #>> '{required_amount_gbp}',
        v_batch.last_funds_check_json #>> '{required_amount}'
      )::numeric
    ELSE NULL::numeric
  END;

  v_blocked_funds_available_gbp := CASE
    WHEN COALESCE(
      v_batch.last_funds_check_json #>> '{available_gbp}',
      v_batch.last_funds_check_json #>> '{available}',
      v_batch.last_funds_check_json #>> '{available_amount_gbp}',
      v_batch.last_funds_check_json #>> '{available_amount}'
    ) ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN COALESCE(
        v_batch.last_funds_check_json #>> '{available_gbp}',
        v_batch.last_funds_check_json #>> '{available}',
        v_batch.last_funds_check_json #>> '{available_amount_gbp}',
        v_batch.last_funds_check_json #>> '{available_amount}'
      )::numeric
    ELSE NULL::numeric
  END;

  v_blocked_funds_required_gbp_display := public.cloudtms_format_gbp(v_blocked_funds_required_gbp);
  v_blocked_funds_available_gbp_display := public.cloudtms_format_gbp(v_blocked_funds_available_gbp);

  v_blocked_funds_sufficient := CASE
    WHEN lower(btrim(COALESCE(v_batch.last_funds_check_json #>> '{sufficient}', v_batch.last_funds_check_json #>> '{is_sufficient}', ''))) IN ('true','1','yes','y','on') THEN true
    WHEN lower(btrim(COALESCE(v_batch.last_funds_check_json #>> '{sufficient}', v_batch.last_funds_check_json #>> '{is_sufficient}', ''))) IN ('false','0','no','n','off') THEN false
    ELSE NULL::boolean
  END;

  v_blocked_funds_provider := COALESCE(
    v_batch.last_funds_check_json #>> '{rail_provider}',
    v_batch.last_funds_check_json #>> '{provider}',
    v_batch.rail_provider_snapshot
  );

  v_blocked_funds_env := COALESCE(
    v_batch.last_funds_check_json #>> '{rail_env}',
    v_batch.last_funds_check_json #>> '{env}',
    v_batch.rail_env_snapshot
  );

  v_blocked_funds_account_ref := COALESCE(
    v_batch.last_funds_check_json #>> '{funding_account_ref}',
    v_batch.last_funds_check_json #>> '{account_ref}',
    v_batch.funding_account_ref
  );

  v_no_bank_transfer_events := COALESCE((v_submission_evidence ->> 'transfer_event_count')::integer, 0) = 0;
  v_no_rail_tx_id := COALESCE((v_submission_evidence ->> 'has_rail_tx_id')::boolean, false) = false;
  v_no_provider_submission_reference := (
    COALESCE((v_submission_evidence ->> 'has_provider_submission_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_payment_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_transfer_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_provider_transaction_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_external_payment_reference')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_external_transfer_reference')::boolean, false) = false
  );
  v_no_submitted_or_completed_transfer_state := (
    COALESCE((v_submission_evidence ->> 'has_submitted_state')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_processing_state')::boolean, false) = false
    AND COALESCE((v_submission_evidence ->> 'has_completed_state')::boolean, false) = false
  );

  v_no_provider_attempt_request_or_idempotency_reference :=
    COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false) = false;

  v_no_possible_provider_attempt_evidence :=
    COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false) = false;

  v_no_external_submission_evidence :=
    COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false) = false;

  v_no_submission_evidence_flags := jsonb_build_object(
    'execution_commit_not_submitted', v_execution_commit_state = 'NOT_SUBMITTED',
    'execution_commit_ref_absent', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NULL,
    'execution_committed_at_absent', v_batch.execution_committed_at_utc IS NULL,
    'no_bank_transfer_events', COALESCE(v_no_bank_transfer_events, false),
    'no_rail_tx_id', COALESCE(v_no_rail_tx_id, false),
    'no_provider_submission_reference', COALESCE(v_no_provider_submission_reference, false),
    'no_submitted_or_completed_transfer_state', COALESCE(v_no_submitted_or_completed_transfer_state, false),
    'no_provider_attempt_request_or_idempotency_reference', COALESCE(v_no_provider_attempt_request_or_idempotency_reference, false),
    'no_possible_provider_attempt_evidence', COALESCE(v_no_possible_provider_attempt_evidence, false),
    'no_external_submission_evidence', COALESCE(v_no_external_submission_evidence, false),
    'no_submission_evidence', COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false),
    'has_local_generated_request_identity', COALESCE((v_submission_evidence ->> 'has_local_generated_request_identity')::boolean, false),
    'has_provider_attempt_request_or_idempotency_reference', COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false),
    'has_possible_provider_attempt_evidence', COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false),
    'has_external_submission_evidence', COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false),
    'submission_evidence', v_submission_evidence
  );

  v_can_retry_blocked_funds := (
    v_batch_status_upper = 'BLOCKED_FUNDS'
    AND v_execution_commit_state = 'NOT_SUBMITTED'
    AND NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), '') IS NULL
    AND v_batch.execution_committed_at_utc IS NULL
    AND COALESCE(v_active_effective_item_count, 0) > 0
    AND COALESCE(v_no_bank_transfer_events, false) = true
    AND COALESCE(v_no_rail_tx_id, false) = true
    AND COALESCE(v_no_provider_submission_reference, false) = true
    AND COALESCE(v_no_submitted_or_completed_transfer_state, false) = true
    AND COALESCE(v_no_provider_attempt_request_or_idempotency_reference, false) = true
    AND COALESCE(v_no_possible_provider_attempt_evidence, false) = true
    AND COALESCE(v_no_external_submission_evidence, false) = true
    AND COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false) = true
    AND v_blocked_funds_sufficient IS FALSE
  );

  IF v_batch_status_upper = 'BLOCKED_FUNDS' THEN
    v_blocked_funds_alert_payload := public.banking_alert_payload_for_pay_batch('BLOCKED_FUNDS', p_pay_batch_id);

    IF NULLIF(BTRIM(COALESCE(v_banking_alert_fingerprint, '')), '') IS NULL THEN
      v_banking_alert_fingerprint := public.banking_alert_fingerprint(
        'BLOCKED_FUNDS',
        'pay_batch',
        p_pay_batch_id,
        v_blocked_funds_alert_payload
      );
    END IF;

    v_blocked_funds_reason := concat(
      'Bank unavailable',
      CASE WHEN v_blocked_funds_required_gbp IS NULL THEN '' ELSE ' — required ' || v_blocked_funds_required_gbp_display END,
      CASE WHEN v_blocked_funds_available_gbp IS NULL THEN '' ELSE ', available ' || v_blocked_funds_available_gbp_display END
    );

    IF NULLIF(BTRIM(COALESCE(v_banking_alert_kind, '')), '') IS NULL
       OR COALESCE(v_banking_alert_kind, '') = 'BLOCKED_FUNDS' THEN
      v_banking_alert_kind := 'BLOCKED_FUNDS';
      v_banking_alert_severity := 'critical';
      v_banking_alert_label := 'Bank unavailable — unsent payments can be retried';
      v_banking_alert_reason := v_blocked_funds_reason;
    END IF;

    v_blocked_funds_alert_payload := v_blocked_funds_alert_payload || jsonb_build_object('alert_fingerprint', v_banking_alert_fingerprint);

    IF v_banking_alerts = '[]'::jsonb THEN
      v_banking_alerts := jsonb_build_array(jsonb_build_object(
        'alert_kind', 'BLOCKED_FUNDS',
        'severity', 'critical',
        'severity_rank', 100,
        'entity_kind', 'pay_batch',
        'entity_id', p_pay_batch_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'alert_fingerprint', v_banking_alert_fingerprint,
        'label', 'Bank unavailable — unsent payments can be retried',
        'title', 'Bank unavailable — unsent payments can be retried',
        'description', v_blocked_funds_reason,
        'action_guidance', 'Retry unsent payments from Overview if eligible, or cancel scheduled batch and recalculate.',
        'acknowledged_for_current_user', v_banking_alert_acknowledged_for_user,
        'requires_attention_for_current_user', v_banking_alert_requires_attention,
        'payload_json', v_blocked_funds_alert_payload
      ));
    ELSE
      SELECT COALESCE(
        jsonb_agg(
          CASE
            WHEN COALESCE(alert_item.alert_json ->> 'alert_kind', '') = 'BLOCKED_FUNDS' THEN
              alert_item.alert_json
              || jsonb_build_object(
                'label', 'Bank unavailable — unsent payments can be retried',
                'title', 'Bank unavailable — unsent payments can be retried',
                'description', v_blocked_funds_reason,
                'action_guidance', 'Retry unsent payments from Overview if eligible, or cancel scheduled batch and recalculate.',
                'payload_json', COALESCE(alert_item.alert_json -> 'payload_json', '{}'::jsonb) || v_blocked_funds_alert_payload
              )
            ELSE alert_item.alert_json
          END
          ORDER BY alert_item.alert_ordinality
        ),
        '[]'::jsonb
      )
      INTO v_banking_alerts
      FROM jsonb_array_elements(COALESCE(v_banking_alerts, '[]'::jsonb)) WITH ORDINALITY AS alert_item(alert_json, alert_ordinality);
    END IF;

    v_blocked_funds_payment_issue := jsonb_build_object(
      'issue_kind', 'BLOCKED_FUNDS',
      'severity', 'critical',
      'bank_status_label', 'Bank unavailable — unsent payments can be retried',
      'what_happened', v_blocked_funds_reason,
      'what_happened_label', v_blocked_funds_reason,
      'action_label', 'Retry unsent payments',
      'status_label', 'Urgent action needed',
      'requires_user_action', true,
      'whole_batch_issue', true,
      'can_retry_blocked_funds', v_can_retry_blocked_funds,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false),
      'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
      'retry_operation_status', v_retry_operation_status,
      'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
      'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
      'retry_status_label', v_retry_status_label,
      'retry_button_label', v_retry_button_label,
      'retry_button_visible', COALESCE(v_retry_button_visible, false),
      'retry_button_disabled_reason', v_retry_button_disabled_reason,
      'required_gbp', v_blocked_funds_required_gbp,
      'available_gbp', v_blocked_funds_available_gbp,
      'required_gbp_display', v_blocked_funds_required_gbp_display,
      'available_gbp_display', v_blocked_funds_available_gbp_display,
      'sufficient', v_blocked_funds_sufficient,
      'provider', v_blocked_funds_provider,
      'rail_provider', v_blocked_funds_provider,
      'rail_env', v_blocked_funds_env,
      'funding_account_ref', v_blocked_funds_account_ref,
      'last_funds_check_at_utc', CASE WHEN v_batch.last_funds_check_at_utc IS NULL THEN NULL ELSE v_batch.last_funds_check_at_utc::text END,
      'last_funds_check_json', v_batch.last_funds_check_json,
      'alert_fingerprint', v_banking_alert_fingerprint,
      'no_submission_evidence_flags', v_no_submission_evidence_flags
    );

    v_payment_issues := jsonb_build_array(v_blocked_funds_payment_issue);
  END IF;

  IF v_provider_submit_issue_present AND v_provider_submit_payment_issue IS NOT NULL THEN
    v_payment_issues := COALESCE(v_payment_issues, '[]'::jsonb) || jsonb_build_array(v_provider_submit_payment_issue);

    v_payment_correction := v_payment_correction || jsonb_build_object(
      'provider_submit_review_issue', v_provider_submit_payment_issue,
      'payment_execution_review', v_payment_execution_review,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'payment_issues', v_payment_issues,
      'provider_submit_review_action_required', true,
      'manual_resolution_available', v_provider_submit_manual_resolution_available,
      'safe_retry_available', v_provider_submit_safe_retry_available,
      'payment_provider_review_required', v_payment_provider_review_required,
      'provider_submit_issue_present', v_provider_submit_issue_present,
      'provider_submit_is_diagnostic_only', v_provider_submit_is_diagnostic_only,
      'requires_user_action', true
    );
  END IF;


  if v_has_cloudtms_csv_export = true then
    if v_execution_commit_state = 'COMMITTED'
       or v_batch_status_upper in ('COMMITTED','PAID','SETTLED')
       or v_has_external_submission_evidence = true then
      v_csv_comparison_transfer_hash := coalesce(v_execution_transfer_hash, v_stable_transfer_hash, v_pending_transfer_hash);
      v_csv_export_match_basis := case
        when v_execution_transfer_hash is not null then 'EXECUTION_INTENT_CURRENT_TRANSFER_HASH'
        when v_stable_transfer_hash is not null then 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH'
        when v_pending_transfer_hash is not null then 'PENDING_TRANSFER_HASH'
        else 'NO_TRANSFER_HASH_AVAILABLE'
      end;
    else
      v_csv_comparison_transfer_hash := coalesce(v_pending_transfer_hash, v_stable_transfer_hash, v_execution_transfer_hash);
      v_csv_export_match_basis := case
        when v_pending_transfer_hash is not null then 'PENDING_TRANSFER_HASH'
        when v_stable_transfer_hash is not null then 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH'
        when v_execution_transfer_hash is not null then 'EXECUTION_INTENT_CURRENT_TRANSFER_HASH'
        else 'NO_TRANSFER_HASH_AVAILABLE'
      end;
    end if;
  else
    v_csv_comparison_transfer_hash := coalesce(v_pending_transfer_hash, v_stable_transfer_hash, v_execution_transfer_hash);
    v_csv_export_match_basis := 'NO_CLOUDTMS_CSV_EXPORT';
  end if;

  v_current_transfer_hash := v_csv_comparison_transfer_hash;
  v_csv_export_matches_current_transfers := (
    v_has_cloudtms_csv_export = true
    and v_bank_csv_export_hash is not null
    and v_csv_comparison_transfer_hash is not null
    and v_bank_csv_export_hash = v_csv_comparison_transfer_hash
  );

  if v_active_auth_execution_intent_json is not null then
    v_execution_mode_pending := upper(nullif(btrim(coalesce(v_active_auth_execution_intent_json->>'execution_mode','')), ''));
    v_suppress_remittances_pending := lower(btrim(coalesce(v_active_auth_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on');
  elsif v_execution_intent_json is not null and jsonb_typeof(v_execution_intent_json) = 'object' then
    v_execution_mode_pending := upper(nullif(btrim(coalesce(v_execution_intent_json->>'execution_mode','')), ''));
    v_suppress_remittances_pending := lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on');
  else
    v_execution_mode_pending := null;
    v_suppress_remittances_pending := false;
  end if;

  v_can_create_bank_csv_file := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
  );
  v_can_start_standard_execution := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_provider_normalized <> 'CSV'
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );
  v_can_start_csv_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
    and v_has_cloudtms_csv_export = true
    and v_csv_export_matches_current_transfers = true
  );
  v_can_start_external_settlement := (
    v_provider_known = true
    and COALESCE(v_active_effective_item_count, 0) > 0
    and v_batch_status_upper not in ('COMMITTED','PAID','SETTLED','CANCELLED','BLOCKED_FUNDS')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_has_external_submission_evidence = false
  );

  IF v_provider_submit_issue_present AND COALESCE(v_provider_submit_safe_retry_available, false) IS NOT TRUE THEN
    v_can_start_standard_execution := false;
    v_can_start_csv_settlement := false;
    v_can_start_external_settlement := false;
  END IF;

  -- Items returned for audit/debug and UI fallback
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbi.id::text,
        'pay_batch_candidate_id', pbi.pay_batch_candidate_id::text,
        'item_type', pbi.item_type,
        'timesheet_id', case when pbi.timesheet_id is null then null else pbi.timesheet_id::text end,
        'segment_key', pbi.segment_key,
        'source_ref', pbi.source_ref,
        'description', pbi.description,
        'finance_case_id', case when pbi.finance_case_id is null then null else pbi.finance_case_id::text end,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'reservation_id', case when pbi.reservation_id is null then null else pbi.reservation_id::text end,
        'frozen_component_snapshot_json', pbi.frozen_component_snapshot_json,
        'frozen_component_key_type', pbi.frozen_component_key_type,
        'frozen_component_key_value', pbi.frozen_component_key_value,
        'frozen_component_classification', case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end,
        'frozen_source_basis_json', pbi.frozen_source_basis_json,
        'frozen_source_pay_method', pbi.frozen_source_pay_method,
        'frozen_target_pay_method', pbi.frozen_target_pay_method,
        'frozen_resolution_mode', case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end,
        'frozen_resolution_payload_json', pbi.frozen_resolution_payload_json,
        'frozen_resolution_result_json', pbi.frozen_resolution_result_json,
        'frozen_source_amount', pbi.frozen_source_amount,
        'frozen_target_amount_ex_vat', pbi.frozen_target_amount_ex_vat,
        'frozen_target_amount_vat', pbi.frozen_target_amount_vat,
        'frozen_target_amount_inc_vat', pbi.frozen_target_amount_inc_vat,
        'payout_instruction_snapshot_json', pbi.payout_instruction_snapshot_json,
        'paye_treatment', pbi.paye_treatment,
        'is_voided', coalesce(pbi.is_voided, false),
        'amount_ex_vat', pbi.amount_ex_vat,
        'amount_vat', pbi.amount_vat,
        'amount_inc_vat', pbi.amount_inc_vat,
        'pay_channel', pbi.pay_channel,
        'umbrella_id', case when pbi.umbrella_id is null then null else pbi.umbrella_id::text end,
        'pay_bank_transfer_id', case when pbi.pay_bank_transfer_id is null then null else pbi.pay_bank_transfer_id::text end,
        'repayment_week_start', case when pbi.repayment_week_start is null then null else pbi.repayment_week_start::text end
      )
      order by pbi.pay_batch_candidate_id, pbi.id
    ),
    '[]'::jsonb
  )
  into v_items
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc2
    on pbc2.id = pbi.pay_batch_candidate_id
  where pbc2.pay_batch_id = p_pay_batch_id;

  -- ✅ NEW: candidate_breakdown for child modal (aggregates + status rollup)
  with cand as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      pbc.candidate_tms_ref,
      pbc.candidate_display_name,
      pbc.paye_state,
      pbc.gross_preview,
      pbc.awaiting_net_amount,
      pbc.net_bank_amount,
      pbc.overpayment_recovery_taken,
      pbc.loan_repayment_taken,
      pbc.remittance_sent_at_utc,
      pbc.remittance_sent_by_user_id,
      pbc.remittance_trigger_status,
      pbc.last_remittance_error,
      ce.total_item_count,
      ce.active_effective_item_count,
      ce.active_effective_amount_ex_vat,
      ce.active_effective_amount_inc_vat,
      ce.original_frozen_amount_ex_vat,
      ce.original_frozen_amount_inc_vat,
      ce.applied_precancel_item_count,
      ce.applied_unwind_item_count,
      ce.applied_reversal_item_count,
      ce.corrected_item_count,
      ce.payment_issue_badge,
      ce.payment_issue_label,
      ce.payment_issue_kinds,
      ce.current_effective_zero
    from public.pay_batch_candidates pbc
    left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
      on ce.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  ni as (
    select
      pbc.id as pay_batch_candidate_id,
      pni.net_amount,
      pni.source,
      pni.imported_at_utc,
      pni.file_name
    from public.pay_batch_candidates pbc
    left join lateral (
      select
        pni0.net_amount,
        pni0.source,
        pni0.imported_at_utc,
        pni0.file_name
      from public.pay_batch_paye_net_inputs pni0
      where pni0.pay_batch_candidate_id = pbc.id
      order by pni0.imported_at_utc desc
      limit 1
    ) pni on true
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  sums as (
    select
      pbc.id as pay_batch_candidate_id,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then coalesce(pbi.amount_ex_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as paye_total_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then coalesce(pbi.amount_inc_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as umbrella_total_inc_vat
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  fs as (
    select
      pbc.id as pay_batch_candidate_id,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_recovery,
      round(coalesce(sum(case when pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as manual_debt_net_deductions,
      round(coalesce(sum(case when pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as payment_advance_repayment,
      round(coalesce(sum(case when pbi.item_type = 'OVERPAYMENT_RECOVERY' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as overpayment_recovery,
      round(coalesce(sum(case when (pbi.item_type = 'MANUAL_DEBT_RECOVERY' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') or (pbi.item_type = 'LOAN_REPAYMENT' and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as repayment
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  tr as (
    select
      pbc.id as pay_batch_candidate_id,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
      )::int as total_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'BLOCKED'
      )::int as blocked_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'FAILED'
      )::int as failed_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'COMPLETED'
      )::int as completed_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.pay_bank_transfer_id is not null
          and upper(coalesce(pbt.status::text,'')) = 'PENDING'
      )::int as pending_transfers
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', c.pay_batch_candidate_id::text,
        'candidate_id', c.candidate_id::text,
        'candidate_tms_ref', c.candidate_tms_ref,
        'candidate_display_name', c.candidate_display_name,
        'batch_kind', v_batch_kind,
        'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
        'paye_state', c.paye_state,
        'paye_net_amount', n.net_amount,
        'paye_net_source', n.source,
        'paye_net_imported_at_utc', n.imported_at_utc,
        'paye_net_file_name', n.file_name,
        'awaiting_net_amount',
          (case
            when v_batch_kind_fixed = 'LOANS' then false
            when v_batch_kind = 'PAYE' then (n.net_amount is null)
            else false
          end),
        'overpayment_recovery_taken', c.overpayment_recovery_taken,
        'loan_repayment_taken', c.loan_repayment_taken,
        'remittance_sent_at_utc', c.remittance_sent_at_utc,
        'remittance_sent_by_user_id', case when c.remittance_sent_by_user_id is null then null else c.remittance_sent_by_user_id::text end,
        'remittance_trigger_status', c.remittance_trigger_status,
        'last_remittance_error', c.last_remittance_error,
        'original_gross_preview', c.gross_preview,
        'original_net_bank_amount', c.net_bank_amount,
        'current_effective_item_count', coalesce(c.active_effective_item_count, 0),
        'active_effective_item_count', coalesce(c.active_effective_item_count, 0),
        'total_item_count', coalesce(c.total_item_count, 0),
        'current_effective_amount_ex_vat', coalesce(c.active_effective_amount_ex_vat, 0),
        'current_effective_amount_inc_vat', coalesce(c.active_effective_amount_inc_vat, 0),
        'original_frozen_amount_ex_vat', coalesce(c.original_frozen_amount_ex_vat, 0),
        'original_frozen_amount_inc_vat', coalesce(c.original_frozen_amount_inc_vat, 0),
        'payment_issue_badge', coalesce(c.payment_issue_badge, false),
        'payment_issue_badge_label', case when coalesce(c.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
        'payment_issue_label', c.payment_issue_label,
        'payment_issue_kinds', coalesce(c.payment_issue_kinds, '[]'::jsonb),
        'applied_precancel_item_count', coalesce(c.applied_precancel_item_count, 0),
        'applied_unwind_item_count', coalesce(c.applied_unwind_item_count, 0),
        'applied_reversal_item_count', coalesce(c.applied_reversal_item_count, 0),
        'corrected_item_count', coalesce(c.corrected_item_count, 0),
        'final_net_paid', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.net_bank_amount end,
        'deductions_summary', jsonb_build_object(
          'gross_positive', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.gross_preview end,
          'manual_debt_recovery', coalesce(fs.manual_debt_recovery,0),
          'manual_debt_net_deductions', coalesce(fs.manual_debt_net_deductions,0),
          'payment_advance_repayment', coalesce(fs.payment_advance_repayment,0),
          'loan_repayment', coalesce(fs.payment_advance_repayment,0),
          'repayment', coalesce(fs.repayment,0),
          'overpayment_recovery', coalesce(fs.overpayment_recovery,0),
          'final_payable', case when coalesce(c.current_effective_zero, false) then 0::numeric else c.net_bank_amount end,
          'awaiting_net_amount', case when v_batch_kind_fixed = 'LOANS' then false else coalesce(c.awaiting_net_amount, false) end,
          'paye_net_amount', n.net_amount
        ),
        'finance_summary', jsonb_build_object(
          'gross_additions_ex_vat', coalesce(fs.gross_additions_ex_vat,0),
          'gross_deductions_ex_vat', coalesce(fs.gross_deductions_ex_vat,0),
          'net_deductions_ex_vat', coalesce(fs.net_deductions_ex_vat,0)
        ),
        'paye_total_ex_vat', s.paye_total_ex_vat,
        'umbrella_total_inc_vat', s.umbrella_total_inc_vat,
        'payment_amount',
          (case
            when coalesce(c.current_effective_zero, false) then 0::numeric
            when v_batch_kind = 'PAYE' then s.paye_total_ex_vat
            when v_batch_kind = 'UMBRELLA' then s.umbrella_total_inc_vat
            else round(coalesce(s.paye_total_ex_vat,0) + coalesce(s.umbrella_total_inc_vat,0),2)
          end),
        'transfer_rollup', jsonb_build_object(
          'total', tr0.total_transfers,
          'pending', tr0.pending_transfers,
          'blocked', tr0.blocked_transfers,
          'failed', tr0.failed_transfers,
          'completed', tr0.completed_transfers
        ),
        'payment_status',
          (case
            when coalesce(c.payment_issue_badge, false) and coalesce(c.active_effective_item_count, 0) = 0 then 'PAYMENT_ISSUE'
            when coalesce(c.payment_issue_badge, false) then 'PAYMENT_ISSUE_PARTIAL'
            when coalesce(tr0.total_transfers,0) = 0 then 'DRAFT'
            when coalesce(tr0.blocked_transfers,0) > 0 then 'BLOCKED'
            when coalesce(tr0.failed_transfers,0) > 0 then 'FAILED'
            when coalesce(tr0.completed_transfers,0) = coalesce(tr0.total_transfers,0) then 'PAID'
            else 'PENDING'
          end)
      )
      order by c.candidate_display_name nulls last, c.candidate_tms_ref nulls last, c.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidate_breakdown
  from cand c
  left join ni n
    on n.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join sums s
    on s.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join fs
    on fs.pay_batch_candidate_id = c.pay_batch_candidate_id
  left join tr tr0
    on tr0.pay_batch_candidate_id = c.pay_batch_candidate_id;

  -- ✅ UPDATED: candidate_lines for expandable table
  -- HARD RULE: do NOT derive units/rate from total_hours; use canonical pay_batch_item_breakdowns.
  with pbci as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      pbc.candidate_display_name,
      pbc.candidate_tms_ref,
      ce.total_item_count,
      ce.active_effective_item_count,
      ce.payment_issue_badge,
      ce.payment_issue_label,
      ce.payment_issue_kinds,
      ce.corrected_item_count
    from public.pay_batch_candidates pbc
    left join pg_temp._tmp_pay_batch_get_candidate_effective AS ce
      on ce.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  ts_groups as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.timesheet_id as timesheet_id,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,''))='PAYE' then coalesce(pbi.amount_ex_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as subtotal_paye_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.pay_channel::text,''))='UMBRELLA' then coalesce(pbi.amount_inc_vat,0) else 0 end) filter (where pbi.item_type <> 'DEBT_CREATED'),0),2) as subtotal_umbrella_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is not null
    group by pbc.id, pbc.candidate_id, pbi.timesheet_id
  ),
  ts_enriched as (
    select
      tg.pay_batch_candidate_id,
      tg.candidate_id,
      tg.timesheet_id,
      vts.week_ending_date,
      vts.client_id,
      vts.client_name,
      nullif(btrim(coalesce(vts.hospital_norm,'')), '') as hospital_norm,
      tg.subtotal_paye_ex_vat,
      tg.subtotal_umbrella_inc_vat,
      case
        when v_batch_kind = 'PAYE' then tg.subtotal_paye_ex_vat
        when v_batch_kind = 'UMBRELLA' then tg.subtotal_umbrella_inc_vat
        else round(coalesce(tg.subtotal_paye_ex_vat,0) + coalesce(tg.subtotal_umbrella_inc_vat,0),2)
      end as payment_amount
    from ts_groups tg
    left join public.v_timesheets_summary_base vts
      on vts.timesheet_id = tg.timesheet_id
  ),
  ts_breakdown_rows as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.timesheet_id as timesheet_id,
      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.rate as rate,
      case
        when bool_and(pbib.units is null) then null::numeric
        else round(sum(coalesce(pbib.units,0)),2)
      end as units,
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) as amount_ex_vat,
      round(coalesce(sum(coalesce(pbib.amount_vat,0)),0),2) as amount_vat,
      round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) as amount_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = pbi.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is not null
    group by
      pbc.id,
      pbc.candidate_id,
      pbi.timesheet_id,
      pbib.line_kind,
      pbib.bucket_code,
      pbib.unit_name,
      pbib.rate
    having
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) <> 0
      or round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) <> 0
      or (case when bool_and(pbib.units is null) then 0 else round(sum(coalesce(pbib.units,0)),2) end) <> 0
  ),
  ts_breakdown_json as (
    select
      tbr.pay_batch_candidate_id,
      tbr.candidate_id,
      tbr.timesheet_id,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'line_kind', tbr.line_kind,
            'bucket_code', tbr.bucket_code,
            'unit_name', tbr.unit_name,
            'units', tbr.units,
            'rate', tbr.rate,
            'amount_ex_vat', tbr.amount_ex_vat,
            'amount_vat', tbr.amount_vat,
            'amount_inc_vat', tbr.amount_inc_vat
          )
          order by
            case upper(coalesce(tbr.line_kind,''))
              when 'TS_BUCKET' then 1
              when 'ADDITIONAL_UNIT' then 2
              when 'MILEAGE' then 3
              when 'EXPENSE' then 4
              when 'ADJUSTMENT' then 5
              when 'CONVERSION_ADJ' then 6
              when 'LOAN_REPAYMENT' then 7
              when 'DEBT_CREATED' then 8
              else 99
            end,
            case upper(coalesce(tbr.bucket_code,''))
              when 'DAY' then 1
              when 'NIGHT' then 2
              when 'SAT' then 3
              when 'SUN' then 4
              when 'BH' then 5
              else 99
            end,
            coalesce(tbr.unit_name,'') asc,
            coalesce(tbr.rate,0) asc
        ),
        '[]'::jsonb
      ) as breakdown_lines
    from ts_breakdown_rows tbr
    group by tbr.pay_batch_candidate_id, tbr.candidate_id, tbr.timesheet_id
  ),
  ts_lines as (
    select
      te.pay_batch_candidate_id,
      te.candidate_id,
      jsonb_build_object(
        'timesheet_id', te.timesheet_id::text,
        'week_ending_date', case when te.week_ending_date is null then null else te.week_ending_date::text end,
        'client_id', case when te.client_id is null then null else te.client_id::text end,
        'client_name', te.client_name,
        'hospital_norm', te.hospital_norm,
        'subtotal_paye_ex_vat', te.subtotal_paye_ex_vat,
        'subtotal_umbrella_inc_vat', te.subtotal_umbrella_inc_vat,
        'payment_amount', te.payment_amount,
        'breakdown_lines', coalesce(tbj.breakdown_lines, '[]'::jsonb)
      ) as ts_line
    from ts_enriched te
    left join ts_breakdown_json tbj
      on tbj.pay_batch_candidate_id = te.pay_batch_candidate_id
     and tbj.timesheet_id = te.timesheet_id
  ),
  non_ts_detail as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type as item_type,
      pbi.source_ref as source_ref,
      pbi.repayment_week_start as repayment_week_start,
      pbi.finance_case_id as finance_case_id,
      pbi.paye_treatment as paye_treatment,
      coalesce(pbi.is_voided, false) as is_voided,
      pbi.description as description,
      upper(coalesce(pbi.pay_channel::text,'')) as pay_channel_txt,
      case when pbi.umbrella_id is null then null else pbi.umbrella_id::text end as umbrella_id_txt,
      coalesce(
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'taxability','')), ''),
        case when vfcr.taxability is null then null else vfcr.taxability::text end
      ) as taxability_txt,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') is not null
          then nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '')
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'NORMAL_PAY_ROUTE'
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'UMBRELLA_COMPANY'
        else case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end
      end as routing_kind_txt,
      coalesce(
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'destination_label','')), ''),
        case
          when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'UMBRELLA_COMPANY' then 'umbrella company'
          when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
          when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'normal PAYE route'
          when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'umbrella company'
          when case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end = 'UMBRELLA_COMPANY' then 'umbrella company'
          when case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
          else null
        end
      ) as destination_label,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'masked_bank_account','')), '') as masked_bank_account,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), '') as beneficiary_name,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as bank_details_hash,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_note','')), '') as bank_details_note,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'is_candidate_directed_oneoff_payout'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.is_candidate_directed_oneoff_payout, false)
      end as is_candidate_directed_oneoff_payout,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_created_by_user_id,
      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_updated_by_user_id,
      tuc.display_name as bank_details_created_by_display_name,
      tuc.email as bank_details_created_by_email,
      tuu.display_name as bank_details_updated_by_display_name,
      tuu.email as bank_details_updated_by_email,
      case when vfcr.management_group is null then null else vfcr.management_group::text end as management_group,
      vfcr.lifecycle_status_display as lifecycle_status_display,
      vfcr.status as finance_case_status,
      vfcr.payout_status as finance_payout_status,
      coalesce(vfcr.edit_bank_details_allowed, false) as edit_bank_details_allowed,
      pbi.amount_ex_vat as amount_ex_vat,
      pbi.amount_vat as amount_vat,
      pbi.amount_inc_vat as amount_inc_vat
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    left join public.tms_users tuc
      on tuc.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end
    left join public.tms_users tuu
      on tuu.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.timesheet_id is null
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  non_ts_groups as (
    select
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type as item_type,
      ntd.source_ref as source_ref,
      ntd.repayment_week_start as repayment_week_start,
      ntd.finance_case_id as finance_case_id,
      max(case when ntd.paye_treatment is null then null else ntd.paye_treatment::text end) as paye_treatment,
      bool_or(coalesce(ntd.is_voided, false)) as is_voided,
      max(ntd.description) as description,
      max(ntd.pay_channel_txt) as pay_channel_txt,
      max(ntd.umbrella_id_txt) as umbrella_id_txt,
      max(ntd.taxability_txt) as taxability_txt,
      max(ntd.routing_kind_txt) as routing_kind_txt,
      max(ntd.destination_label) as destination_label,
      max(ntd.masked_bank_account) as masked_bank_account,
      max(ntd.beneficiary_name) as beneficiary_name,
      max(ntd.bank_details_hash) as bank_details_hash,
      max(ntd.bank_details_note) as bank_details_note,
      max(case when ntd.bank_details_created_by_user_id is null then null else ntd.bank_details_created_by_user_id::text end) as bank_details_created_by_user_id,
      max(ntd.bank_details_created_by_display_name) as bank_details_created_by_display_name,
      max(ntd.bank_details_created_by_email) as bank_details_created_by_email,
      max(case when ntd.bank_details_updated_by_user_id is null then null else ntd.bank_details_updated_by_user_id::text end) as bank_details_updated_by_user_id,
      max(ntd.bank_details_updated_by_display_name) as bank_details_updated_by_display_name,
      max(ntd.bank_details_updated_by_email) as bank_details_updated_by_email,
      bool_or(ntd.appears_on_umbrella_remittance) as appears_on_umbrella_remittance,
      bool_or(ntd.generates_candidate_payment_advice) as generates_candidate_payment_advice,
      bool_or(ntd.is_candidate_directed_oneoff_payout) as is_candidate_directed_oneoff_payout,
      max(ntd.management_group) as management_group,
      max(ntd.lifecycle_status_display) as lifecycle_status_display,
      max(ntd.finance_case_status) as finance_case_status,
      max(ntd.finance_payout_status) as finance_payout_status,
      bool_or(coalesce(ntd.edit_bank_details_allowed, false)) as edit_bank_details_allowed,
      round(coalesce(sum(case when ntd.pay_channel_txt = 'PAYE' then coalesce(ntd.amount_ex_vat,0) else 0 end),0),2) as subtotal_paye_ex_vat,
      round(coalesce(sum(case when ntd.pay_channel_txt = 'UMBRELLA' then coalesce(ntd.amount_inc_vat,0) else 0 end),0),2) as subtotal_umbrella_inc_vat
    from non_ts_detail ntd
    group by
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type,
      ntd.source_ref,
      ntd.repayment_week_start,
      ntd.finance_case_id,
      ntd.taxability_txt,
      ntd.routing_kind_txt,
      ntd.destination_label,
      ntd.masked_bank_account,
      ntd.beneficiary_name,
      ntd.bank_details_hash,
      ntd.bank_details_note,
      ntd.bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name,
      ntd.bank_details_created_by_email,
      ntd.bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email
  ),
  non_ts_breakdown_rows as (
    select
      ntd.pay_batch_candidate_id,
      ntd.candidate_id as candidate_id,
      ntd.item_type as item_type,
      ntd.source_ref as source_ref,
      ntd.repayment_week_start as repayment_week_start,
      ntd.finance_case_id as finance_case_id,
      ntd.taxability_txt as taxability_txt,
      ntd.routing_kind_txt as routing_kind_txt,
      ntd.destination_label as destination_label,
      ntd.masked_bank_account as masked_bank_account,
      ntd.beneficiary_name as beneficiary_name,
      ntd.bank_details_hash as bank_details_hash,
      ntd.bank_details_note as bank_details_note,
      case when ntd.bank_details_created_by_user_id is null then null else ntd.bank_details_created_by_user_id::text end as bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name as bank_details_created_by_display_name,
      ntd.bank_details_created_by_email as bank_details_created_by_email,
      case when ntd.bank_details_updated_by_user_id is null then null else ntd.bank_details_updated_by_user_id::text end as bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name as bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email as bank_details_updated_by_email,
      ntd.appears_on_umbrella_remittance as appears_on_umbrella_remittance,
      ntd.generates_candidate_payment_advice as generates_candidate_payment_advice,
      ntd.is_candidate_directed_oneoff_payout as is_candidate_directed_oneoff_payout,
      ntd.management_group as management_group,
      ntd.lifecycle_status_display as lifecycle_status_display,
      ntd.finance_case_status as finance_case_status,
      ntd.finance_payout_status as finance_payout_status,
      ntd.edit_bank_details_allowed as edit_bank_details_allowed,
      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.rate as rate,
      case
        when bool_and(pbib.units is null) then null::numeric
        else round(sum(coalesce(pbib.units,0)),2)
      end as units,
      round(coalesce(sum(coalesce(pbib.amount_ex_vat,0)),0),2) as amount_ex_vat,
      round(coalesce(sum(coalesce(pbib.amount_vat,0)),0),2) as amount_vat,
      round(coalesce(sum(coalesce(pbib.amount_inc_vat,0)),0),2) as amount_inc_vat
    from non_ts_detail ntd
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = ntd.pay_batch_item_id
    group by
      ntd.pay_batch_candidate_id,
      ntd.candidate_id,
      ntd.item_type,
      ntd.source_ref,
      ntd.repayment_week_start,
      ntd.finance_case_id,
      ntd.taxability_txt,
      ntd.routing_kind_txt,
      ntd.destination_label,
      ntd.masked_bank_account,
      ntd.beneficiary_name,
      ntd.bank_details_hash,
      ntd.bank_details_note,
      ntd.bank_details_created_by_user_id,
      ntd.bank_details_created_by_display_name,
      ntd.bank_details_created_by_email,
      ntd.bank_details_updated_by_user_id,
      ntd.bank_details_updated_by_display_name,
      ntd.bank_details_updated_by_email,
      ntd.appears_on_umbrella_remittance,
      ntd.generates_candidate_payment_advice,
      ntd.is_candidate_directed_oneoff_payout,
      ntd.management_group,
      ntd.lifecycle_status_display,
      ntd.finance_case_status,
      ntd.finance_payout_status,
      ntd.edit_bank_details_allowed,
      pbib.line_kind,
      pbib.bucket_code,
      pbib.unit_name,
      pbib.rate
  ),
  non_ts_breakdown_json as (
    select
      ntr.pay_batch_candidate_id,
      ntr.candidate_id,
      ntr.item_type,
      ntr.source_ref,
      ntr.repayment_week_start,
      ntr.finance_case_id,
      ntr.taxability_txt,
      ntr.routing_kind_txt,
      ntr.destination_label,
      ntr.masked_bank_account,
      ntr.beneficiary_name,
      ntr.bank_details_hash,
      ntr.bank_details_note,
      ntr.bank_details_created_by_user_id,
      ntr.bank_details_created_by_display_name,
      ntr.bank_details_created_by_email,
      ntr.bank_details_updated_by_user_id,
      ntr.bank_details_updated_by_display_name,
      ntr.bank_details_updated_by_email,
      ntr.appears_on_umbrella_remittance,
      ntr.generates_candidate_payment_advice,
      ntr.is_candidate_directed_oneoff_payout,
      ntr.management_group,
      ntr.lifecycle_status_display,
      ntr.finance_case_status,
      ntr.finance_payout_status,
      ntr.edit_bank_details_allowed,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'line_kind', ntr.line_kind,
            'bucket_code', ntr.bucket_code,
            'unit_name', ntr.unit_name,
            'units', ntr.units,
            'rate', ntr.rate,
            'amount_ex_vat', ntr.amount_ex_vat,
            'amount_vat', ntr.amount_vat,
            'amount_inc_vat', ntr.amount_inc_vat
          )
          order by
            case upper(coalesce(ntr.line_kind,''))
              when 'TS_BUCKET' then 1
              when 'ADDITIONAL_UNIT' then 2
              when 'MILEAGE' then 3
              when 'EXPENSE' then 4
              when 'ADJUSTMENT' then 5
              when 'CONVERSION_ADJ' then 6
              when 'LOAN_REPAYMENT' then 7
              when 'DEBT_CREATED' then 8
              else 99
            end,
            coalesce(ntr.unit_name,'') asc
        ),
        '[]'::jsonb
      ) as breakdown_lines
    from non_ts_breakdown_rows ntr
    group by
      ntr.pay_batch_candidate_id,
      ntr.candidate_id,
      ntr.item_type,
      ntr.source_ref,
      ntr.repayment_week_start,
      ntr.finance_case_id,
      ntr.taxability_txt,
      ntr.routing_kind_txt,
      ntr.destination_label,
      ntr.masked_bank_account,
      ntr.beneficiary_name,
      ntr.bank_details_hash,
      ntr.bank_details_note,
      ntr.bank_details_created_by_user_id,
      ntr.bank_details_created_by_display_name,
      ntr.bank_details_created_by_email,
      ntr.bank_details_updated_by_user_id,
      ntr.bank_details_updated_by_display_name,
      ntr.bank_details_updated_by_email,
      ntr.appears_on_umbrella_remittance,
      ntr.generates_candidate_payment_advice,
      ntr.is_candidate_directed_oneoff_payout,
      ntr.management_group,
      ntr.lifecycle_status_display,
      ntr.finance_case_status,
      ntr.finance_payout_status,
      ntr.edit_bank_details_allowed
  ),
  candidate_destination_rollup as (
    select
      pbc.id as pay_batch_candidate_id,
      count(distinct
        case
          when pbi.item_type = 'DEBT_CREATED' then null
          when pbi.timesheet_id is not null then
            case
              when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then 'NORMAL_PAYE_ROUTE'
              when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then 'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              else 'ROUTE|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL') || '|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
            end
          else
            case
              when coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then
                'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''), 'NO_HASH')
                || '|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL')
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), 'NO_BENEFICIARY')
              when coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = 'UMBRELLA_COMPANY' then
                'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then
                'NORMAL_PAYE_ROUTE'
              when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' and coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '') = '' then
                'UMBRELLA_COMPANY|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
              else
                coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), 'NO_ROUTING')
                || '|' || coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''), 'NO_HASH')
                || '|' || coalesce(upper(coalesce(pbi.pay_channel::text,'')), 'NO_CHANNEL')
                || '|' || coalesce(pbi.umbrella_id::text,'NO_UMBRELLA')
            end
        end
      )::int as destination_count
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
     and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.id
  ),
  non_ts_lines as (
    select
      ng.pay_batch_candidate_id,
      ng.candidate_id,
      jsonb_build_object(
        'item_type', ng.item_type,
        'source_ref', ng.source_ref,
        'finance_case_id', case when ng.finance_case_id is null then null else ng.finance_case_id::text end,
        'paye_treatment', ng.paye_treatment,
        'is_voided', ng.is_voided,
        'finance_case_reference', coalesce(ng.source_ref, case when ng.finance_case_id is null then null else ng.finance_case_id::text end),
        'repayment_week_start', case when ng.repayment_week_start is null then null else ng.repayment_week_start::text end,
        'week_ending_date', case when ng.repayment_week_start is null then null else (ng.repayment_week_start + 6)::text end,
        'description', ng.description,
        'pay_channel', ng.pay_channel_txt,
        'umbrella_id', ng.umbrella_id_txt,
        'taxability', ng.taxability_txt,
        'routing_kind', ng.routing_kind_txt,
        'destination_label', ng.destination_label,
        'payout_destination', ng.destination_label,
        'masked_bank_account', ng.masked_bank_account,
        'beneficiary_name', ng.beneficiary_name,
        'bank_details_hash', ng.bank_details_hash,
        'bank_details_note', ng.bank_details_note,
        'bank_details_created_by_user_id', ng.bank_details_created_by_user_id,
        'bank_details_created_by_display_name', ng.bank_details_created_by_display_name,
        'bank_details_created_by_email', ng.bank_details_created_by_email,
        'bank_details_updated_by_user_id', ng.bank_details_updated_by_user_id,
        'bank_details_updated_by_display_name', ng.bank_details_updated_by_display_name,
        'bank_details_updated_by_email', ng.bank_details_updated_by_email,
        'appears_on_umbrella_remittance', ng.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', ng.generates_candidate_payment_advice,
        'is_candidate_directed_oneoff_payout', ng.is_candidate_directed_oneoff_payout,
        'management_group', ng.management_group,
        'lifecycle_status_display', ng.lifecycle_status_display,
        'finance_case_status', ng.finance_case_status,
        'finance_payout_status', ng.finance_payout_status,
        'edit_bank_details_allowed', ng.edit_bank_details_allowed,
        'communication_kind',
          case
            when ng.generates_candidate_payment_advice then 'PAYOUT_NOTICE'
            when ng.appears_on_umbrella_remittance then 'REMITTANCE'
            else null
          end,
        'destination_group_key',
          coalesce(ng.routing_kind_txt, 'NO_ROUTING')
          || '|' || coalesce(ng.bank_details_hash, 'NO_HASH')
          || '|' || coalesce(ng.pay_channel_txt, 'NO_CHANNEL')
          || '|' || coalesce(ng.destination_label, 'NO_DESTINATION')
          || '|' || coalesce(ng.beneficiary_name, 'NO_BENEFICIARY'),
        'candidate_has_multiple_payment_destinations', coalesce(cdr.destination_count,0) > 1,
        'is_separate_destination_payment', (coalesce(cdr.destination_count,0) > 1 and nullif(btrim(coalesce(ng.destination_label,'')), '') is not null),
        'different_destination_marker', (coalesce(cdr.destination_count,0) > 1 and nullif(btrim(coalesce(ng.destination_label,'')), '') is not null),
        'subtotal_paye_ex_vat', ng.subtotal_paye_ex_vat,
        'subtotal_umbrella_inc_vat', ng.subtotal_umbrella_inc_vat,
        'payment_amount',
          case
            when v_batch_kind = 'PAYE' then ng.subtotal_paye_ex_vat
            when v_batch_kind = 'UMBRELLA' then ng.subtotal_umbrella_inc_vat
            else round(coalesce(ng.subtotal_paye_ex_vat,0) + coalesce(ng.subtotal_umbrella_inc_vat,0),2)
          end,
        'breakdown_lines', coalesce(ntbj.breakdown_lines, '[]'::jsonb)
      ) as non_ts_line
    from non_ts_groups ng
    left join non_ts_breakdown_json ntbj
      on ntbj.pay_batch_candidate_id = ng.pay_batch_candidate_id
     and ntbj.item_type = ng.item_type
     and ntbj.source_ref is not distinct from ng.source_ref
     and ntbj.repayment_week_start is not distinct from ng.repayment_week_start
     and ntbj.finance_case_id is not distinct from ng.finance_case_id
     and ntbj.taxability_txt is not distinct from ng.taxability_txt
     and ntbj.routing_kind_txt is not distinct from ng.routing_kind_txt
     and ntbj.destination_label is not distinct from ng.destination_label
     and ntbj.masked_bank_account is not distinct from ng.masked_bank_account
     and ntbj.beneficiary_name is not distinct from ng.beneficiary_name
     and ntbj.bank_details_hash is not distinct from ng.bank_details_hash
     and ntbj.bank_details_note is not distinct from ng.bank_details_note
     and ntbj.bank_details_created_by_user_id is not distinct from ng.bank_details_created_by_user_id
     and ntbj.bank_details_created_by_display_name is not distinct from ng.bank_details_created_by_display_name
     and ntbj.bank_details_created_by_email is not distinct from ng.bank_details_created_by_email
     and ntbj.bank_details_updated_by_user_id is not distinct from ng.bank_details_updated_by_user_id
     and ntbj.bank_details_updated_by_display_name is not distinct from ng.bank_details_updated_by_display_name
     and ntbj.bank_details_updated_by_email is not distinct from ng.bank_details_updated_by_email
     and ntbj.appears_on_umbrella_remittance is not distinct from ng.appears_on_umbrella_remittance
     and ntbj.generates_candidate_payment_advice is not distinct from ng.generates_candidate_payment_advice
     and ntbj.is_candidate_directed_oneoff_payout is not distinct from ng.is_candidate_directed_oneoff_payout
     and ntbj.management_group is not distinct from ng.management_group
     and ntbj.lifecycle_status_display is not distinct from ng.lifecycle_status_display
     and ntbj.finance_case_status is not distinct from ng.finance_case_status
     and ntbj.finance_payout_status is not distinct from ng.finance_payout_status
     and ntbj.edit_bank_details_allowed is not distinct from ng.edit_bank_details_allowed
    left join candidate_destination_rollup cdr
      on cdr.pay_batch_candidate_id = ng.pay_batch_candidate_id
  ),
  ts_lines_agg as (
    select
      ts.pay_batch_candidate_id,
      ts.candidate_id,
      coalesce(
        jsonb_agg(
          ts.ts_line
          order by (ts.ts_line->>'week_ending_date')::date desc nulls last, ts.ts_line->>'timesheet_id'
        ),
        '[]'::jsonb
      ) as ts_lines
    from ts_lines ts
    group by ts.pay_batch_candidate_id, ts.candidate_id
  ),
  non_ts_lines_agg as (
    select
      nt.pay_batch_candidate_id,
      nt.candidate_id,
      coalesce(
        jsonb_agg(
          nt.non_ts_line
          order by nt.non_ts_line->>'item_type', nt.non_ts_line->>'source_ref', nt.non_ts_line->>'payout_destination', nt.non_ts_line->>'masked_bank_account', nt.non_ts_line->>'beneficiary_name'
        ),
        '[]'::jsonb
      ) as non_ts_lines
    from non_ts_lines nt
    group by nt.pay_batch_candidate_id, nt.candidate_id
  ),
  cand_lines as (
    select
      p.pay_batch_candidate_id,
      p.candidate_id,
      p.candidate_display_name,
      p.candidate_tms_ref,
      p.total_item_count,
      p.active_effective_item_count,
      p.payment_issue_badge,
      p.payment_issue_label,
      p.payment_issue_kinds,
      p.corrected_item_count,
      coalesce(tsa.ts_lines, '[]'::jsonb) as ts_lines,
      coalesce(nta.non_ts_lines, '[]'::jsonb) as non_ts_lines
    from pbci p
    left join ts_lines_agg tsa
      on tsa.pay_batch_candidate_id = p.pay_batch_candidate_id
     and tsa.candidate_id = p.candidate_id
    left join non_ts_lines_agg nta
      on nta.pay_batch_candidate_id = p.pay_batch_candidate_id
     and nta.candidate_id = p.candidate_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_candidate_id', cl.pay_batch_candidate_id::text,
        'candidate_id', cl.candidate_id::text,
        'candidate_display_name', cl.candidate_display_name,
        'candidate_tms_ref', cl.candidate_tms_ref,
        'total_item_count', coalesce(cl.total_item_count, 0),
        'active_effective_item_count', coalesce(cl.active_effective_item_count, 0),
        'current_effective_item_count', coalesce(cl.active_effective_item_count, 0),
        'payment_issue_badge', coalesce(cl.payment_issue_badge, false),
        'payment_issue_badge_label', case when coalesce(cl.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
        'payment_issue_label', cl.payment_issue_label,
        'payment_issue_kinds', coalesce(cl.payment_issue_kinds, '[]'::jsonb),
        'corrected_item_count', coalesce(cl.corrected_item_count, 0),
        'candidate_lines', jsonb_build_object(
          'ts_lines', cl.ts_lines,
          'non_ts_lines', cl.non_ts_lines,
          'payment_issue_badge', coalesce(cl.payment_issue_badge, false),
          'payment_issue_badge_label', case when coalesce(cl.payment_issue_badge, false) then 'PAYMENT ISSUE' else null end,
          'payment_issue_label', cl.payment_issue_label,
          'payment_issue_kinds', coalesce(cl.payment_issue_kinds, '[]'::jsonb)
        ),
        'ts_lines', cl.ts_lines,
        'non_ts_lines', cl.non_ts_lines
      )
      order by cl.candidate_display_name nulls last, cl.candidate_tms_ref nulls last, cl.candidate_id
    ),
    '[]'::jsonb
  )
  into v_candidate_lines
  from cand_lines cl;

  with cand_src as (
    select
      cand.value as cand_json,
      cand.ordinality as cand_ord
    from jsonb_array_elements(v_candidates) with ordinality as cand(value, ordinality)
  ),
  line_src as (
    select
      ln.value as line_json
    from jsonb_array_elements(v_candidate_lines) as ln(value)
  )
  select coalesce(
    jsonb_agg(
      cand_src.cand_json || jsonb_build_object(
        'candidate_lines',
          coalesce(
            (
              select jsonb_build_object(
                'ts_lines', coalesce(line_src.line_json->'ts_lines', '[]'::jsonb),
                'non_ts_lines', coalesce(line_src.line_json->'non_ts_lines', '[]'::jsonb),
                'payment_issue_badge', coalesce((line_src.line_json->>'payment_issue_badge')::boolean, false),
                'payment_issue_badge_label', line_src.line_json->>'payment_issue_badge_label',
                'payment_issue_label', line_src.line_json->>'payment_issue_label',
                'payment_issue_kinds', coalesce(line_src.line_json->'payment_issue_kinds', '[]'::jsonb)
              )
              from line_src
              where coalesce(line_src.line_json->>'pay_batch_candidate_id','') = coalesce(cand_src.cand_json->>'id','')
              limit 1
            ),
            jsonb_build_object(
              'ts_lines', '[]'::jsonb,
              'non_ts_lines', '[]'::jsonb,
              'payment_issue_badge', coalesce((cand_src.cand_json->>'payment_issue_badge')::boolean, false),
              'payment_issue_badge_label', cand_src.cand_json->>'payment_issue_badge_label',
              'payment_issue_label', cand_src.cand_json->>'payment_issue_label',
              'payment_issue_kinds', coalesce(cand_src.cand_json->'payment_issue_kinds', '[]'::jsonb)
            )
          )
      )
      order by cand_src.cand_ord
    ),
    '[]'::jsonb
  )
  into v_candidates
  from cand_src;


  ---------------------------------------------------------------------------
  -- 3.41: Mirror backend-derived payment action diagnostics onto the actual
  -- Overview / Current Payment Status row surfaces.  The candidate array above
  -- is diagnostic-rich, but the Banking child modal commonly reads
  -- candidate_breakdown / candidate_lines directly; do not leave those surfaces
  -- to infer action eligibility from raw rail state.
  ---------------------------------------------------------------------------
  WITH candidate_action_payloads AS (
    SELECT
      candidate_payload.value->>'id' AS pay_batch_candidate_id,
      candidate_payload.value->>'candidate_id' AS candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'payment_lifecycle_state', candidate_payload.value->'payment_lifecycle_state',
        'payment_lifecycle_label', candidate_payload.value->'payment_lifecycle_label',
        'recommended_action', candidate_payload.value->'recommended_action',
        'row_action', candidate_payload.value->'row_action',
        'row_action_label', candidate_payload.value->'row_action_label',
        'retry_row_context', candidate_payload.value->'retry_row_context',
        'row_cancel_available', candidate_payload.value->'row_cancel_available',
        'can_no_money_unwind', candidate_payload.value->'can_no_money_unwind',
        'can_recover_overpayment', candidate_payload.value->'can_recover_overpayment',
        'manual_adjustment_carry_forward_required', candidate_payload.value->'manual_adjustment_carry_forward_required',
        'manual_adjustments_to_carry_forward', candidate_payload.value->'manual_adjustments_to_carry_forward',
        'manual_adjustments_carried_forward', candidate_payload.value->'manual_adjustments_carried_forward',
        'carry_forward_blockers', candidate_payload.value->'carry_forward_blockers',
        'blocking_paid_evidence_json', candidate_payload.value->'blocking_paid_evidence_json',
        'terminal_no_money_evidence_json', candidate_payload.value->'terminal_no_money_evidence_json',
        'pending_provider_evidence_json', candidate_payload.value->'pending_provider_evidence_json',
        'resolved_full_payment_scope_json', candidate_payload.value->'resolved_full_payment_scope_json',
        'finance_scope_json', candidate_payload.value->'finance_scope_json',
        'provider_failure_reason_group', candidate_payload.value->'provider_failure_reason_group',
        'provider_failure_reason_label', candidate_payload.value->'provider_failure_reason_label',
        'status_update_signature', candidate_payload.value->'status_update_signature',
        'provider_outcome_unknown_evidence_json', candidate_payload.value->'provider_outcome_unknown_evidence_json',
        'provider_webhook_evidence_json', candidate_payload.value->'provider_webhook_evidence_json'
      )) AS action_payload
    FROM jsonb_array_elements(COALESCE(v_candidates, '[]'::jsonb)) AS candidate_payload(value)
    WHERE jsonb_typeof(candidate_payload.value) = 'object'
  ),
  breakdown_rows AS (
    SELECT
      breakdown_payload.value AS row_payload,
      breakdown_payload.ordinality AS row_ordinality,
      action_payloads.action_payload
    FROM jsonb_array_elements(COALESCE(v_candidate_breakdown, '[]'::jsonb)) WITH ORDINALITY AS breakdown_payload(value, ordinality)
    LEFT JOIN candidate_action_payloads AS action_payloads
      ON action_payloads.pay_batch_candidate_id = breakdown_payload.value->>'pay_batch_candidate_id'
      OR action_payloads.candidate_id = breakdown_payload.value->>'candidate_id'
  )
  SELECT COALESCE(
    jsonb_agg(
      breakdown_rows.row_payload || COALESCE(breakdown_rows.action_payload, '{}'::jsonb)
      ORDER BY breakdown_rows.row_ordinality
    ),
    '[]'::jsonb
  )
  INTO v_candidate_breakdown
  FROM breakdown_rows;

  WITH candidate_action_payloads AS (
    SELECT
      candidate_payload.value->>'id' AS pay_batch_candidate_id,
      candidate_payload.value->>'candidate_id' AS candidate_id,
      jsonb_strip_nulls(jsonb_build_object(
        'payment_lifecycle_state', candidate_payload.value->'payment_lifecycle_state',
        'payment_lifecycle_label', candidate_payload.value->'payment_lifecycle_label',
        'recommended_action', candidate_payload.value->'recommended_action',
        'row_action', candidate_payload.value->'row_action',
        'row_action_label', candidate_payload.value->'row_action_label',
        'retry_row_context', candidate_payload.value->'retry_row_context',
        'row_cancel_available', candidate_payload.value->'row_cancel_available',
        'can_no_money_unwind', candidate_payload.value->'can_no_money_unwind',
        'can_recover_overpayment', candidate_payload.value->'can_recover_overpayment',
        'manual_adjustment_carry_forward_required', candidate_payload.value->'manual_adjustment_carry_forward_required',
        'manual_adjustments_to_carry_forward', candidate_payload.value->'manual_adjustments_to_carry_forward',
        'manual_adjustments_carried_forward', candidate_payload.value->'manual_adjustments_carried_forward',
        'carry_forward_blockers', candidate_payload.value->'carry_forward_blockers',
        'blocking_paid_evidence_json', candidate_payload.value->'blocking_paid_evidence_json',
        'terminal_no_money_evidence_json', candidate_payload.value->'terminal_no_money_evidence_json',
        'pending_provider_evidence_json', candidate_payload.value->'pending_provider_evidence_json',
        'resolved_full_payment_scope_json', candidate_payload.value->'resolved_full_payment_scope_json',
        'finance_scope_json', candidate_payload.value->'finance_scope_json',
        'provider_failure_reason_group', candidate_payload.value->'provider_failure_reason_group',
        'provider_failure_reason_label', candidate_payload.value->'provider_failure_reason_label',
        'status_update_signature', candidate_payload.value->'status_update_signature',
        'provider_outcome_unknown_evidence_json', candidate_payload.value->'provider_outcome_unknown_evidence_json',
        'provider_webhook_evidence_json', candidate_payload.value->'provider_webhook_evidence_json'
      )) AS action_payload
    FROM jsonb_array_elements(COALESCE(v_candidates, '[]'::jsonb)) AS candidate_payload(value)
    WHERE jsonb_typeof(candidate_payload.value) = 'object'
  ),
  line_rows AS (
    SELECT
      line_payload.value AS row_payload,
      line_payload.ordinality AS row_ordinality,
      action_payloads.action_payload
    FROM jsonb_array_elements(COALESCE(v_candidate_lines, '[]'::jsonb)) WITH ORDINALITY AS line_payload(value, ordinality)
    LEFT JOIN candidate_action_payloads AS action_payloads
      ON action_payloads.pay_batch_candidate_id = line_payload.value->>'pay_batch_candidate_id'
      OR action_payloads.candidate_id = line_payload.value->>'candidate_id'
  )
  SELECT COALESCE(
    jsonb_agg(
      line_rows.row_payload
      || COALESCE(line_rows.action_payload, '{}'::jsonb)
      || jsonb_build_object(
        'candidate_lines',
        COALESCE(line_rows.row_payload->'candidate_lines', '{}'::jsonb)
        || COALESCE(line_rows.action_payload, '{}'::jsonb)
      )
      ORDER BY line_rows.row_ordinality
    ),
    '[]'::jsonb
  )
  INTO v_candidate_lines
  FROM line_rows;

  with item_flags as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.finance_case_id as finance_case_id,
      pbi.item_type as item_type,
      pbi.umbrella_id as umbrella_id,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  transfer_remittance_targets as (
    select distinct
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbt.umbrella_id as umbrella_id
    from public.pay_bank_transfers pbt
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = pbt.pay_batch_id
     and pbc.candidate_id = pbt.candidate_id
    where pbt.pay_batch_id = p_pay_batch_id
      and pbt.umbrella_id is not null
      and upper(coalesce(pbt.pay_channel::text,'')) = 'UMBRELLA'
      and upper(coalesce(pbt.status::text,'')) <> 'BLOCKED'
  ),
  rem_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id,
      ifl.umbrella_id
    from item_flags ifl
    where ifl.appears_on_umbrella_remittance = true
      and ifl.umbrella_id is not null

    union

    select distinct
      trt.pay_batch_candidate_id,
      trt.candidate_id,
      trt.umbrella_id
    from transfer_remittance_targets trt
  )
  select jsonb_build_object(
    'candidate_count', count(distinct pbc.id)::int,
    'umbrella_count', count(distinct rt.umbrella_id) filter (where rt.umbrella_id is not null)::int,
    'umbrella_remittance_job_count', count(distinct rt.umbrella_id) filter (where rt.umbrella_id is not null)::int,
    'candidate_copy_job_count', count(distinct pbc.id)::int,
    'job_kinds', case
      when count(distinct pbc.id) = 0 then '[]'::jsonb
      else jsonb_build_array('UMBRELLA_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE')
    end,
    'queued_count', count(distinct pbc.id) filter (where pbc.remittance_sent_at_utc is null and upper(coalesce(pbc.remittance_trigger_status,'')) in ('QUEUED_TO_MAIL_OUTBOX','MAIL_OUTBOX_DUPLICATE_EXISTS'))::int,
    'sent_count', count(distinct pbc.id) filter (where pbc.remittance_sent_at_utc is not null)::int,
    'unsent_count', count(distinct pbc.id) filter (where pbc.remittance_sent_at_utc is null)::int,
    'error_count', count(distinct pbc.id) filter (where nullif(btrim(coalesce(pbc.last_remittance_error,'')), '') is not null)::int,
    'latest_sent_at_utc', max(pbc.remittance_sent_at_utc),
    'all_sent', case when count(distinct pbc.id) = 0 then false else bool_and(pbc.remittance_sent_at_utc is not null) end,
    'trigger_statuses', coalesce(
      to_jsonb(
        array_agg(distinct pbc.remittance_trigger_status order by pbc.remittance_trigger_status)
        filter (where pbc.remittance_trigger_status is not null and btrim(coalesce(pbc.remittance_trigger_status::text,'')) <> '')
      ),
      '[]'::jsonb
    )
  )
  into v_remittance_summary
  from rem_targets rt
  join public.pay_batch_candidates pbc
    on pbc.id = rt.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id;

  with item_flags as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbi.finance_case_id as finance_case_id,
      pbi.item_type as item_type,
      pbi.umbrella_id as umbrella_id,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'appears_on_umbrella_remittance'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'UMBRELLA_COMPANY' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','ONE_OFF_SPECIFIED_BANK_ACCOUNT') then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'PAYE' then false
        when upper(coalesce(pbi.pay_channel::text,'')) = 'UMBRELLA' then true
        else coalesce(vfcr.appears_on_umbrella_remittance, false)
      end as appears_on_umbrella_remittance,
      case
        when jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
         and pbi.payout_instruction_snapshot_json ? 'generates_candidate_payment_advice'
          then lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on')
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then true
        when upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) in ('NORMAL_PAY_ROUTE','UMBRELLA_COMPANY') then false
        when upper(coalesce(pbi.pay_channel::text,'')) in ('PAYE','UMBRELLA') then false
        else coalesce(vfcr.generates_candidate_payment_advice, false)
      end as generates_candidate_payment_advice
    from public.pay_batch_candidates pbc
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  transfer_remittance_targets as (
    select distinct
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id as candidate_id,
      pbt.umbrella_id as umbrella_id
    from public.pay_bank_transfers pbt
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = pbt.pay_batch_id
     and pbc.candidate_id = pbt.candidate_id
    where pbt.pay_batch_id = p_pay_batch_id
      and pbt.umbrella_id is not null
      and upper(coalesce(pbt.pay_channel::text,'')) = 'UMBRELLA'
      and upper(coalesce(pbt.status::text,'')) <> 'BLOCKED'
  ),
  rem_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id,
      ifl.umbrella_id
    from item_flags ifl
    where ifl.appears_on_umbrella_remittance = true
      and ifl.umbrella_id is not null

    union

    select distinct
      trt.pay_batch_candidate_id,
      trt.candidate_id,
      trt.umbrella_id
    from transfer_remittance_targets trt
  ),
  payout_notice_targets as (
    select distinct
      ifl.pay_batch_candidate_id,
      ifl.candidate_id
    from item_flags ifl
    where ifl.generates_candidate_payment_advice = true
  ),
  outbox_union as (
    select
      'MAIL'::text as outbox_channel,
      upper(coalesce(mo.type::text,'')) as outbox_type,
      upper(coalesce(mo.status::text,'')) as outbox_status,
      mo.reference as reference,
      mo.created_at_utc as created_at_utc,
      mo.sent_at as sent_at_utc,
      mo.delivered_at as delivered_at_utc,
      mo.read_at as read_at_utc,
      mo.failed_at as failed_at_utc,
      upper(coalesce(mo.recipient_kind::text,'')) as recipient_kind
    from public.mail_outbox mo
    where lower(coalesce(mo.context_kind,'')) = 'pay_batches'
      and mo.context_id = p_pay_batch_id

    union all

    select
      upper(coalesce(co.channel::text,'')) as outbox_channel,
      upper(coalesce(co.channel::text,'')) as outbox_type,
      upper(coalesce(co.status::text,'')) as outbox_status,
      coalesce(co.provider_payload_json->>'reference', co.provider_payload_json->>'mail_reference', '') as reference,
      co.created_at_utc as created_at_utc,
      co.sent_at as sent_at_utc,
      co.delivered_at as delivered_at_utc,
      co.read_at as read_at_utc,
      co.failed_at as failed_at_utc,
      upper(coalesce(co.recipient_kind::text,'')) as recipient_kind
    from public.comms_outbox co
    where lower(coalesce(co.context_kind,'')) = 'pay_batches'
      and co.context_id = p_pay_batch_id
  ),
  rem_outbox as (
    select *
    from outbox_union ou
    where ou.reference like ('remit:pay_batch:' || p_pay_batch_id::text || ':%')
      and (
        (ou.outbox_channel = 'MAIL' and ou.outbox_type = 'REMITTANCE')
        or ou.outbox_channel <> 'MAIL'
      )
  ),
  payout_notice_outbox as (
    select *
    from outbox_union ou
    where ou.reference like ('payout_notice:pay_batch:' || p_pay_batch_id::text || ':%')
      and (
        (ou.outbox_channel = 'MAIL' and ou.outbox_type = 'REMITTANCE')
        or ou.outbox_channel <> 'MAIL'
      )
  )
  select jsonb_build_object(
    'contains_remittance_items', exists(select 1 from rem_targets),
    'contains_payout_notice_items', exists(select 1 from payout_notice_targets),
    'contains_both', exists(select 1 from rem_targets) and exists(select 1 from payout_notice_targets),
    'communication_mode',
      case
        when exists(select 1 from rem_targets) and exists(select 1 from payout_notice_targets) then 'MIXED'
        when exists(select 1 from payout_notice_targets) then 'PAYOUT_NOTICE'
        when exists(select 1 from rem_targets) then 'REMITTANCE'
        else 'NONE'
      end,
    'remittance', jsonb_build_object(
      'contains_items', exists(select 1 from rem_targets),
      'item_count', (select count(*)::int from item_flags ifl where ifl.appears_on_umbrella_remittance = true),
      'job_kinds', case when exists(select 1 from rem_targets) then jsonb_build_array('UMBRELLA_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE') else '[]'::jsonb end,
      'umbrella_remittance_job_count', (select count(distinct rt.umbrella_id)::int from rem_targets rt where rt.umbrella_id is not null),
      'candidate_copy_job_count', (select count(distinct rt.candidate_id)::int from rem_targets rt),
      'candidate_count_targeted', (select count(distinct rt.candidate_id)::int from rem_targets rt),
      'umbrella_count_targeted', (select count(distinct rt.umbrella_id)::int from rem_targets rt where rt.umbrella_id is not null),
      'candidate_count_queued', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and pbc.remittance_sent_at_utc is null
          and upper(coalesce(pbc.remittance_trigger_status,'')) in ('QUEUED_TO_MAIL_OUTBOX','MAIL_OUTBOX_DUPLICATE_EXISTS')
      ),
      'candidate_count_sent', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and pbc.remittance_sent_at_utc is not null
      ),
      'candidate_count_unsent', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and pbc.remittance_sent_at_utc is null
      ),
      'candidate_count_error', (
        select count(*)::int
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
          and nullif(btrim(coalesce(pbc.last_remittance_error,'')), '') is not null
      ),
      'latest_sent_at_utc', (
        select max(pbc.remittance_sent_at_utc)
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
      ),
      'all_sent', (
        select case
          when count(*) = 0 then false
          else bool_and(pbc.remittance_sent_at_utc is not null)
        end
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
      ),
      'trigger_statuses', coalesce((
        select to_jsonb(
          array_agg(distinct pbc.remittance_trigger_status order by pbc.remittance_trigger_status)
          filter (where pbc.remittance_trigger_status is not null and btrim(coalesce(pbc.remittance_trigger_status::text,'')) <> '')
        )
        from public.pay_batch_candidates pbc
        where pbc.pay_batch_id = p_pay_batch_id
          and exists (
            select 1
            from rem_targets rt
            where rt.pay_batch_candidate_id = pbc.id
          )
      ), '[]'::jsonb),
      'outbox_row_count', (select count(*)::int from rem_outbox),
      'outbox_channels', coalesce((
        select to_jsonb(array_agg(oc.outbox_channel order by oc.outbox_channel))
        from (
          select distinct ro.outbox_channel
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_channel,'')), '') is not null
        ) oc
      ), '[]'::jsonb),
      'outbox_statuses', coalesce((
        select to_jsonb(array_agg(os.outbox_status order by os.outbox_status))
        from (
          select distinct ro.outbox_status
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_status,'')), '') is not null
        ) os
      ), '[]'::jsonb),
      'outbox_counts_by_status', coalesce((
        select jsonb_object_agg(osc.outbox_status, osc.status_count)
        from (
          select
            ro.outbox_status,
            count(*)::int as status_count
          from rem_outbox ro
          where nullif(btrim(coalesce(ro.outbox_status,'')), '') is not null
          group by ro.outbox_status
        ) osc
      ), '{}'::jsonb),
      'queued_count', (select count(*)::int from rem_outbox ro where ro.outbox_status = 'QUEUED'),
      'sent_count', (select count(*)::int from rem_outbox ro where ro.sent_at_utc is not null or ro.outbox_status = 'SENT'),
      'delivered_count', (select count(*)::int from rem_outbox ro where ro.delivered_at_utc is not null),
      'read_count', (select count(*)::int from rem_outbox ro where ro.read_at_utc is not null),
      'failed_count', (select count(*)::int from rem_outbox ro where ro.failed_at_utc is not null or ro.outbox_status = 'FAILED'),
      'latest_outbox_created_at_utc', (select max(ro.created_at_utc) from rem_outbox ro),
      'latest_outbox_sent_at_utc', (select max(ro.sent_at_utc) from rem_outbox ro)
    ),
    'payout_notice', jsonb_build_object(
      'contains_items', exists(select 1 from payout_notice_targets),
      'item_count', (select count(*)::int from item_flags ifl where ifl.generates_candidate_payment_advice = true),
      'candidate_count_targeted', (select count(distinct pnt.candidate_id)::int from payout_notice_targets pnt),
      'outbox_row_count', (select count(*)::int from payout_notice_outbox),
      'outbox_channels', coalesce((
        select to_jsonb(array_agg(oc.outbox_channel order by oc.outbox_channel))
        from (
          select distinct pno.outbox_channel
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_channel,'')), '') is not null
        ) oc
      ), '[]'::jsonb),
      'outbox_statuses', coalesce((
        select to_jsonb(array_agg(os.outbox_status order by os.outbox_status))
        from (
          select distinct pno.outbox_status
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_status,'')), '') is not null
        ) os
      ), '[]'::jsonb),
      'outbox_counts_by_status', coalesce((
        select jsonb_object_agg(osc.outbox_status, osc.status_count)
        from (
          select
            pno.outbox_status,
            count(*)::int as status_count
          from payout_notice_outbox pno
          where nullif(btrim(coalesce(pno.outbox_status,'')), '') is not null
          group by pno.outbox_status
        ) osc
      ), '{}'::jsonb),
      'queued_count', (select count(*)::int from payout_notice_outbox pno where pno.outbox_status = 'QUEUED'),
      'sent_count', (select count(*)::int from payout_notice_outbox pno where pno.sent_at_utc is not null or pno.outbox_status = 'SENT'),
      'delivered_count', (select count(*)::int from payout_notice_outbox pno where pno.delivered_at_utc is not null),
      'read_count', (select count(*)::int from payout_notice_outbox pno where pno.read_at_utc is not null),
      'failed_count', (select count(*)::int from payout_notice_outbox pno where pno.failed_at_utc is not null or pno.outbox_status = 'FAILED'),
      'latest_outbox_created_at_utc', (select max(pno.created_at_utc) from payout_notice_outbox pno),
      'latest_sent_at_utc', (select max(pno.sent_at_utc) from payout_notice_outbox pno)
    )
  )
  into v_communications_summary;

  select jsonb_build_object(
    'gross_additions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2),
    'gross_deductions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'net_deductions_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'payout_amount_inc_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT') then coalesce(pbi.amount_inc_vat,0) else 0 end),0),2),
    'recovery_amount_ex_vat', round(coalesce(sum(case when pbi.finance_case_id is not null and pbi.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2),
    'finance_case_count', count(distinct pbi.finance_case_id)
  )
  into v_finance_summaries
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbi.finance_case_id is not null
    and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      );

  with finance_items as (
    select
      pbi.finance_case_id,
      max(pbc.candidate_id::text) as candidate_id,
      max(pbc.candidate_display_name) as candidate_display_name,
      max(pbc.candidate_tms_ref) as candidate_tms_ref,
      round(coalesce(sum(coalesce(pbi.amount_ex_vat,0)),0),2) as batch_amount_ex_vat,
      round(coalesce(sum(coalesce(pbi.amount_inc_vat,0)),0),2) as batch_amount_inc_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_ADD' then coalesce(pbi.amount_ex_vat,0) else 0 end),0),2) as gross_additions_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'GROSS_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as gross_deductions_ex_vat,
      round(coalesce(sum(case when upper(coalesce(pbi.paye_treatment::text,'')) = 'NET_DEDUCT' then abs(coalesce(pbi.amount_ex_vat,0)) else 0 end),0),2) as net_deductions_ex_vat,
      coalesce(
        to_jsonb(
          array_agg(distinct pbi.item_type order by pbi.item_type)
          filter (where pbi.item_type is not null and btrim(coalesce(pbi.item_type::text,'')) <> '')
        ),
        '[]'::jsonb
      ) as item_types
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.finance_case_id is not null
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as active_item_corrections
        where active_item_corrections.pay_batch_item_id = pbi.id
          and active_item_corrections.status = 'APPLIED'
          and active_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    group by pbi.finance_case_id
  ),
  reservation_rollup as (
    select
      par.finance_case_id,
      case
        when bool_or(upper(coalesce(par.status::text,'')) = 'SETTLED') then 'SETTLED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'COMMITTED') then 'COMMITTED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'RESERVED') then 'RESERVED'
        when bool_or(upper(coalesce(par.status::text,'')) = 'RELEASED') then 'RELEASED'
        else null
      end as lifecycle_state,
      round(coalesce(sum(coalesce(par.reserved_amount,0)),0),2) as reservation_amount,
      coalesce(
        to_jsonb(
          array_agg(distinct par.status order by par.status)
          filter (where par.status is not null and btrim(coalesce(par.status::text,'')) <> '')
        ),
        '[]'::jsonb
      ) as reservation_statuses
    from public.pay_advance_reservations par
    where par.pay_batch_id = p_pay_batch_id
    group by par.finance_case_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'finance_case_id', vf.finance_case_id::text,
        'case_type', vf.case_type,
        'candidate_id', fi.candidate_id,
        'candidate_display_name', fi.candidate_display_name,
        'candidate_tms_ref', fi.candidate_tms_ref,
        'lifecycle_state', coalesce(rr.lifecycle_state, upper(coalesce(vf.status::text,''))),
        'finance_case_status', case when vf.status is null then null else vf.status::text end,
        'payout_status', case when vf.payout_status is null then null else vf.payout_status::text end,
        'payout_or_recovery_status', case when vf.case_type in ('PAYMENT_ADVANCE','MANUAL_CREDIT_ADJUSTMENT') and upper(coalesce(v_batch_kind_fixed,'')) = 'LOANS' then coalesce(vf.payout_status::text, vf.status::text) else vf.status::text end,
        'remaining_amount', vf.outstanding_amount,
        'batch_amount_ex_vat', fi.batch_amount_ex_vat,
        'batch_amount_inc_vat', fi.batch_amount_inc_vat,
        'item_types', fi.item_types,
        'reservation_amount', coalesce(rr.reservation_amount,0),
        'reservation_statuses', coalesce(rr.reservation_statuses,'[]'::jsonb),
        'comment_context', jsonb_build_object(
          'adjustment_comment', vf.adjustment_comment,
          'linked_timesheet_id', case when vf.linked_timesheet_id is null then null else vf.linked_timesheet_id::text end,
          'linked_shift_date', case when vf.linked_shift_date is null then null else vf.linked_shift_date::text end,
          'source_original_paid_amount', vf.source_original_paid_amount,
          'source_corrected_paid_amount', vf.source_corrected_paid_amount,
          'notes', vf.notes
        ),
        'paye_summary', jsonb_build_object(
          'gross_additions_ex_vat', fi.gross_additions_ex_vat,
          'gross_deductions_ex_vat', fi.gross_deductions_ex_vat,
          'net_deductions_ex_vat', fi.net_deductions_ex_vat
        ),
        'is_mixed_case', coalesce(vf.is_mixed_case, false),
        'open_taxable_count', coalesce(vf.open_taxable_count, 0),
        'open_reimbursement_count', coalesce(vf.open_reimbursement_count, 0),
        'unresolved_taxable_count', coalesce(vf.unresolved_taxable_count, 0),
        'stale_count', coalesce(vf.stale_count, 0),
        'component_resolution_summary_json', coalesce(vf.component_resolution_summary_json, '{}'::jsonb),
        'active_snooze_context', case
          when vf.active_snooze_id is null then null
          else jsonb_build_object(
            'snooze_id', vf.active_snooze_id::text,
            'snooze_kind', vf.active_snooze_kind,
            'snooze_until_date', case when vf.active_snooze_until_date is null then null else vf.active_snooze_until_date::text end,
            'note', vf.active_snooze_note,
            'created_at_utc', vf.active_snooze_created_at_utc,
            'updated_at_utc', vf.active_snooze_updated_at_utc
          )
        end
      )
      order by fi.candidate_display_name nulls last, fi.candidate_tms_ref nulls last, vf.finance_case_id
    ),
    '[]'::jsonb
  )
  into v_finance_case_groups
  from finance_items fi
  join public.v_finance_cases_register vf
    on vf.finance_case_id = fi.finance_case_id
  left join reservation_rollup rr
    on rr.finance_case_id = fi.finance_case_id;

  
  ---------------------------------------------------------------------------
  -- Payment correction / bank evidence summary for Banking Pay batch modal.
  -- This is display/planning metadata only: it does not mutate correction state
  -- and does not reinterpret batch economics from live TSFIN.
  ---------------------------------------------------------------------------

  SELECT
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', public.pay_bank_transfer_events.id::text,
          'pay_batch_id', public.pay_bank_transfer_events.pay_batch_id::text,
          'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
          'candidate_id', CASE WHEN public.pay_bank_transfer_events.candidate_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.candidate_id::text END,
          'umbrella_id', CASE WHEN public.pay_bank_transfer_events.umbrella_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.umbrella_id::text END,
          'provider_key', public.pay_bank_transfer_events.provider_key,
          'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
          'provider_reference', public.pay_bank_transfer_events.provider_reference,
          'provider_state', public.pay_bank_transfer_events.provider_state,
          'normalised_state', public.pay_bank_transfer_events.normalised_state,
          'event_source', public.pay_bank_transfer_events.event_source,
          'event_time_utc', CASE WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL ELSE public.pay_bank_transfer_events.event_time_utc::text END,
          'received_at_utc', public.pay_bank_transfer_events.received_at_utc::text,
          'amount', public.pay_bank_transfer_events.amount,
          'currency', public.pay_bank_transfer_events.currency,
          'mapping_status', public.pay_bank_transfer_events.mapping_status,
          'mapping_method', public.pay_bank_transfer_events.mapping_method,
          'movement_classification', public.pay_bank_transfer_events.movement_classification,
          'correction_disposition', public.pay_bank_transfer_events.correction_disposition
        )
        ORDER BY public.pay_bank_transfer_events.received_at_utc DESC, public.pay_bank_transfer_events.id DESC
      ),
      '[]'::jsonb
    ),
    COUNT(*)::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED')
    )::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfer_events.normalised_state, ''))) IN ('RETURNED','REVERTED')
    )::integer
  INTO
    v_bank_evidence,
    v_bank_event_count,
    v_bank_failure_event_count,
    v_bank_return_event_count
  FROM public.pay_bank_transfer_events
  WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')
         OR NULLIF(btrim(coalesce(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL
    )::integer,
    COUNT(*) FILTER (
      WHERE upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
         OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
    )::integer,
    COUNT(*) FILTER (
      WHERE (
        NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_tx_id, '')), '') IS NOT NULL
        AND NOT (
          NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_tx_id, '')), '') = ANY(
            ARRAY_REMOVE(ARRAY[
              public.pay_bank_transfers.id::text,
              NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
              NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
              NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), '')
            ]::text[], NULL::text)
          )
        )
      )
      OR (
        upper(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) = 'PROVIDER_SUBMISSION_ACCEPTED'
        AND (
          lower(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
          OR NULLIF(btrim(coalesce(
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}',
            ''
          )), '') IS NOT NULL
          OR upper(btrim(coalesce(
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_state}',
            public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_state}',
            ''
          ))) IN ('ACCEPTED','SUBMITTED','PROCESSING','SENT','COMPLETED','COMPLETE','APPROVED','EXECUTED','PAID')
        )
      )
      OR EXISTS (
        SELECT 1
        FROM (VALUES
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_event_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_reference}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{rail_submission_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{external_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{revolut_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_transfer_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{external_transfer_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
          (public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}')
        ) AS provider_rail_identifier(identifier_value)
        WHERE NULLIF(btrim(coalesce(provider_rail_identifier.identifier_value, '')), '') IS NOT NULL
          AND NOT (
            NULLIF(btrim(coalesce(provider_rail_identifier.identifier_value, '')), '') = ANY(
              ARRAY_REMOVE(ARRAY[
                public.pay_bank_transfers.id::text,
                NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
                NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
                NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), '')
              ]::text[], NULL::text)
            )
          )
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS provider_transfer_event
        WHERE provider_transfer_event.pay_batch_id = p_pay_batch_id
          AND provider_transfer_event.pay_bank_transfer_id = public.pay_bank_transfers.id
          AND upper(btrim(coalesce(provider_transfer_event.event_source, ''))) IN (
            'PROVIDER_RESPONSE',
            'PROVIDER_POLL',
            'PROVIDER_WEBHOOK',
            'WEBHOOK',
            'POLL',
            'RAIL_PROVIDER',
            'PROVIDER'
          )
          AND upper(btrim(coalesce(provider_transfer_event.normalised_state, provider_transfer_event.provider_state, provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN (
            'REJECTED',
            'FAILED',
            'ERROR',
            'DECLINED',
            'CANCELLED',
            'CANCELED',
            'MALFORMED',
            'UNKNOWN',
            'TIMEOUT',
            'TIMED_OUT'
          )
          AND upper(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN (
            'PROVIDER_SUBMISSION_REJECTED',
            'PROVIDER_SUBMISSION_FAILED',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
            'NO_PROVIDER_SUBMISSION_ATTEMPTED',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
            'MANUAL_RESOLVED_NO_PAYMENT_MADE'
          )
          AND (
            EXISTS (
              SELECT 1
              FROM (VALUES
                (provider_transfer_event.provider_event_id),
                (provider_transfer_event.provider_reference),
                (provider_transfer_event.raw_payload #>> '{provider_event_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_reference}'),
                (provider_transfer_event.raw_payload #>> '{provider_submission_id}'),
                (provider_transfer_event.raw_payload #>> '{submission_id}'),
                (provider_transfer_event.raw_payload #>> '{rail_submission_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{payment_id}'),
                (provider_transfer_event.raw_payload #>> '{external_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{revolut_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_transfer_id}'),
                (provider_transfer_event.raw_payload #>> '{external_transfer_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                (provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
              ) AS provider_event_identifier(identifier_value)
              WHERE NULLIF(btrim(coalesce(provider_event_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (
                  NULLIF(btrim(coalesce(provider_event_identifier.identifier_value, '')), '') = ANY(
                    ARRAY_REMOVE(ARRAY[
                      public.pay_bank_transfers.id::text,
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.request_id, '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.payment_reference, '')), ''),
                      NULLIF(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{payment_reference}', '')), ''),
                      NULLIF(btrim(coalesce(public.pay_bank_transfers.rail_meta_json #>> '{bulk_reference}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(provider_transfer_event.idempotency_key, '')), '')
                    ]::text[], NULL::text)
                  )
                )
            )
            OR upper(btrim(coalesce(provider_transfer_event.provider_state, provider_transfer_event.normalised_state, provider_transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) IN (
              'ACCEPTED',
              'SUBMITTED',
              'PROCESSING',
              'SENT',
              'COMPLETED',
              'COMPLETE',
              'APPROVED',
              'EXECUTED',
              'PAID'
            )
          )
      )
    )::integer
  INTO
    v_transfer_failure_count,
    v_transfer_completed_count,
    v_transfer_provider_evidence_count
  FROM public.pay_bank_transfers
  WHERE public.pay_bank_transfers.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*)::integer
  INTO
    v_settlement_evidence_count
  FROM (
    SELECT 1
    FROM public.pay_batch_candidates
    WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
        OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
      )

    UNION ALL

    SELECT 1
    FROM public.timesheet_pay_state_history
    WHERE public.timesheet_pay_state_history.pay_batch_id = p_pay_batch_id

    UNION ALL

    SELECT 1
    FROM public.pay_advance_reservations
    WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
      AND (
        upper(btrim(coalesce(public.pay_advance_reservations.status, ''))) = 'SETTLED'
        OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
      )
  ) AS settlement_evidence_rows;

  SELECT
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN (
        'REQUESTED',
        'AWAITING_AUTHORISATION',
        'AUTHORISED',
        'EXPANDED',
        'PROCESSING',
        'BLOCKED'
      )
        AND public.pay_payment_correction_requests.correction_kind IN ('SETTLED_REVERSAL','MANUAL_EVIDENCE_SETTLED_RETURN')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('REQUESTED','AWAITING_AUTHORISATION')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('AUTHORISED','EXPANDED','PROCESSING')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status IN ('BLOCKED','APPLIED_WITH_BLOCKERS')
    )::integer,
    COUNT(*) FILTER (
      WHERE public.pay_payment_correction_requests.status = 'FAILED'
    )::integer
  INTO
    v_open_correction_request_count,
    v_open_settled_reversal_request_count,
    v_awaiting_authorisation_count,
    v_processing_request_count,
    v_blocked_request_count,
    v_failed_request_count
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PROCESSING')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'BLOCKED')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_RETRYABLE')::integer,
    COUNT(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_FINAL')::integer
  INTO
    v_work_item_pending_count,
    v_work_item_processing_count,
    v_work_item_blocked_count,
    v_work_item_failed_retryable_count,
    v_work_item_failed_final_count
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id;

  v_work_item_failed_count := COALESCE(v_work_item_failed_retryable_count, 0) + COALESCE(v_work_item_failed_final_count, 0);
  v_work_item_requires_user_action := (
    COALESCE(v_work_item_blocked_count, 0) > 0
    OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
    OR COALESCE(v_work_item_failed_final_count, 0) > 0
  );
  v_work_item_processing_continues := (
    COALESCE(v_work_item_pending_count, 0) > 0
    OR COALESCE(v_work_item_processing_count, 0) > 0
    OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
  );

  SELECT
    public.pay_payment_correction_requests.id
  INTO
    v_open_correction_request_id
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
    AND public.pay_payment_correction_requests.status IN (
      'REQUESTED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED',
      'EXPANDED',
      'PROCESSING',
      'BLOCKED'
    )
  ORDER BY public.pay_payment_correction_requests.updated_at_utc DESC NULLS LAST,
           public.pay_payment_correction_requests.created_at_utc DESC,
           public.pay_payment_correction_requests.id DESC
  LIMIT 1;

  SELECT
    COALESCE(
      jsonb_build_object(
        'id', latest_correction_request.id::text,
        'pay_batch_id', latest_correction_request.pay_batch_id::text,
        'correction_kind', latest_correction_request.correction_kind,
        'status', latest_correction_request.status,
        'requested_by_user_id', CASE WHEN latest_correction_request.requested_by_user_id IS NULL THEN NULL ELSE latest_correction_request.requested_by_user_id::text END,
        'requested_at_utc', latest_correction_request.requested_at_utc::text,
        'required_quantity', latest_correction_request.required_quantity,
        'approved_count', latest_correction_request.approved_count,
        'golden_key_used', latest_correction_request.golden_key_used,
        'reason', latest_correction_request.reason,
        'selection_json', latest_correction_request.selection_json,
        'plan_json', latest_correction_request.plan_json,
        'source_bank_event_id', CASE WHEN latest_correction_request.source_bank_event_id IS NULL THEN NULL ELSE latest_correction_request.source_bank_event_id::text END,
        'auto_requested', latest_correction_request.auto_requested,
        'authorised_at_utc', CASE WHEN latest_correction_request.authorised_at_utc IS NULL THEN NULL ELSE latest_correction_request.authorised_at_utc::text END,
        'applied_at_utc', CASE WHEN latest_correction_request.applied_at_utc IS NULL THEN NULL ELSE latest_correction_request.applied_at_utc::text END,
        'cancelled_at_utc', CASE WHEN latest_correction_request.cancelled_at_utc IS NULL THEN NULL ELSE latest_correction_request.cancelled_at_utc::text END,
        'updated_at_utc', latest_correction_request.updated_at_utc::text
      ),
      '{}'::jsonb
    ),
    latest_correction_request.status
  INTO
    v_latest_correction_request,
    v_latest_correction_request_status
  FROM (
    SELECT public.pay_payment_correction_requests.*
    FROM public.pay_payment_correction_requests
    WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
    ORDER BY public.pay_payment_correction_requests.updated_at_utc DESC NULLS LAST,
             public.pay_payment_correction_requests.created_at_utc DESC,
             public.pay_payment_correction_requests.id DESC
    LIMIT 1
  ) AS latest_correction_request;

  SELECT
    COUNT(DISTINCT public.pay_batch_items.id)::integer
  INTO
    v_correctable_item_count
  FROM public.pay_batch_items
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
  WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
    AND COALESCE(public.pay_batch_items.is_voided, false) = false
    AND public.pay_batch_items.item_type <> 'DEBT_CREATED';

  SELECT
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'PRE_BANK_CANCEL'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'NO_MONEY_UNWIND'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id) FILTER (
      WHERE public.pay_payment_correction_items.correction_item_kind = 'SETTLED_REVERSAL'
    )::integer,
    COUNT(DISTINCT public.pay_payment_correction_items.pay_batch_item_id)::integer
  INTO
    v_applied_precancel_item_count,
    v_applied_unwind_item_count,
    v_applied_reversal_item_count,
    v_corrected_item_count
  FROM public.pay_payment_correction_items
  WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
    AND public.pay_payment_correction_items.status = 'APPLIED';

  IF (
    COALESCE(v_work_item_pending_count, 0) > 0
    OR COALESCE(v_work_item_processing_count, 0) > 0
    OR COALESCE(v_processing_request_count, 0) > 0
  ) THEN
    v_derived_correction_state := 'PROCESSING';
  ELSIF v_work_item_requires_user_action
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0 THEN
    v_derived_correction_state := 'ACTION_REQUIRED';
  ELSIF COALESCE(v_awaiting_authorisation_count, 0) > 0 THEN
    v_derived_correction_state := 'AWAITING_AUTHORISATION';
  ELSIF v_applied_reversal_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'REVERSED';
    ELSE
      v_derived_correction_state := 'PARTIALLY_REVERSED';
    END IF;
  ELSIF v_applied_unwind_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'NO_MONEY_UNWOUND';
    ELSE
      v_derived_correction_state := 'PARTIALLY_UNWOUND';
    END IF;
  ELSIF v_applied_precancel_item_count > 0 THEN
    IF COALESCE(v_active_effective_item_count, 0) = 0 THEN
      v_derived_correction_state := 'PRE_BANK_CANCELLED';
    ELSE
      v_derived_correction_state := 'PARTIALLY_PRE_BANK_CANCELLED';
    END IF;
  ELSIF v_bank_return_event_count > 0 THEN
    v_derived_correction_state := 'SETTLED_RETURNED';
  ELSIF v_bank_failure_event_count > 0 OR v_transfer_failure_count > 0 THEN
    v_derived_correction_state := 'ACTION_REQUIRED';
  ELSE
    v_derived_correction_state := 'NONE';
  END IF;

  v_can_cancel_payment_attempt := (
    COALESCE(v_open_correction_request_count, 0) = 0
    AND COALESCE(v_bank_event_count, 0) = 0
    AND COALESCE(v_transfer_provider_evidence_count, 0) = 0
    AND COALESCE(v_transfer_failure_count, 0) = 0
    AND COALESCE(v_transfer_completed_count, 0) = 0
    AND COALESCE(v_settlement_evidence_count, 0) = 0
    AND COALESCE(v_corrected_item_count, 0) = 0
    AND v_execution_commit_state = 'NOT_SUBMITTED'
    AND v_batch_status_upper IN (
      'DRAFT',
      'DRAFT_CREATED',
      'READY',
      'WAITING_BANK_CONFIRM',
      'PARTIAL',
      'BLOCKED_FUNDS',
      'SCHEDULED',
      'AWAITING_AUTHORISATION',
      'AUTHORISED_FOR_PAYMENT',
      'EXECUTING'
    )
  );

  v_can_reverse_settled_payment := (
    COALESCE(v_settlement_evidence_count, 0) > 0
    OR COALESCE(v_transfer_completed_count, 0) > 0
    OR COALESCE(v_bank_return_event_count, 0) > 0
  );

  v_can_unwind_failed_payment := (
    COALESCE(v_bank_failure_event_count, 0) > 0
    OR COALESCE(v_transfer_failure_count, 0) > 0
  ) AND v_can_reverse_settled_payment = false;

  v_can_review_bank_evidence := (
    COALESCE(v_bank_event_count, 0) > 0
    OR COALESCE(v_transfer_provider_evidence_count, 0) > 0
    OR COALESCE(v_open_correction_request_count, 0) > 0
    OR v_derived_correction_state <> 'NONE'
  );

  v_payment_correction := jsonb_build_object(
    'derived_state', v_derived_correction_state,
    'display_state', CASE
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      )
      AND (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'PARTLY_APPLIED_REVIEW_NEEDED'
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      ) THEN 'PROCESSING'
      WHEN (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'ACTION_REQUIRED'
      ELSE v_derived_correction_state
    END,
    'requires_user_action', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED')
      OR COALESCE(v_blocked_request_count, 0) > 0
      OR COALESCE(v_failed_request_count, 0) > 0
      OR v_work_item_requires_user_action
    ),
    'processing_count', GREATEST(
      COALESCE(v_processing_request_count, 0),
      CASE WHEN v_work_item_processing_continues THEN 1 ELSE 0 END
    ),
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'blocked_count', COALESCE(v_blocked_request_count, 0) + COALESCE(v_work_item_blocked_count, 0),
    'failed_count', COALESCE(v_failed_request_count, 0) + COALESCE(v_work_item_failed_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'open_request_id', CASE WHEN v_open_correction_request_id IS NULL THEN NULL ELSE v_open_correction_request_id::text END,
    'latest_request', COALESCE(v_latest_correction_request, '{}'::jsonb),
    'can_plan', true,
    'counts', jsonb_build_object(
      'open_request_count', COALESCE(v_open_correction_request_count, 0),
      'open_settled_reversal_request_count', COALESCE(v_open_settled_reversal_request_count, 0),
      'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
      'processing_request_count', COALESCE(v_processing_request_count, 0),
      'blocked_request_count', COALESCE(v_blocked_request_count, 0),
      'failed_request_count', COALESCE(v_failed_request_count, 0),
      'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
      'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
      'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
      'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
      'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
      'bank_event_count', COALESCE(v_bank_event_count, 0),
      'bank_failure_event_count', COALESCE(v_bank_failure_event_count, 0),
      'bank_return_event_count', COALESCE(v_bank_return_event_count, 0),
      'transfer_failure_count', COALESCE(v_transfer_failure_count, 0),
      'transfer_completed_count', COALESCE(v_transfer_completed_count, 0),
      'settlement_evidence_count', COALESCE(v_settlement_evidence_count, 0),
      'correctable_item_count', COALESCE(v_correctable_item_count, 0),
      'corrected_item_count', COALESCE(v_corrected_item_count, 0),
      'applied_precancel_item_count', COALESCE(v_applied_precancel_item_count, 0),
      'applied_unwind_item_count', COALESCE(v_applied_unwind_item_count, 0),
      'applied_reversal_item_count', COALESCE(v_applied_reversal_item_count, 0)
    )
  );

  IF v_batch_stale_payment_issue IS NOT NULL THEN
    v_payment_correction := v_payment_correction || jsonb_build_object(
      'batch_stale_issue', v_batch_stale_payment_issue,
      'payment_execution_review', v_batch_stale_payment_execution_review,
      'payment_issues', v_payment_issues,
      'batch_stale_action_required', true,
      'requires_user_action', true
    );
  END IF;

  IF v_blocked_funds_payment_issue IS NOT NULL THEN
    v_payment_correction := v_payment_correction || jsonb_build_object(
      'blocked_funds_issue', v_blocked_funds_payment_issue,
      'payment_issues', v_payment_issues,
      'blocked_funds_action_required', true,
      'can_retry_blocked_funds', v_can_retry_blocked_funds,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false),
      'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
      'retry_operation_status', v_retry_operation_status,
      'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
      'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
      'retry_status_label', v_retry_status_label,
      'retry_button_label', v_retry_button_label,
      'retry_button_visible', COALESCE(v_retry_button_visible, false),
      'retry_button_disabled_reason', v_retry_button_disabled_reason,
      'requires_user_action', true
    );
  END IF;

  v_movement_classification := jsonb_build_object(
    'classification', CASE
      WHEN COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
        THEN 'PROCESSING'
      WHEN v_work_item_requires_user_action
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
        THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      WHEN COALESCE(v_awaiting_authorisation_count, 0) > 0
        AND COALESCE(v_open_settled_reversal_request_count, 0) > 0
        THEN 'TRUE_SETTLED_REVERSAL_REQUIRED'
      WHEN COALESCE(v_awaiting_authorisation_count, 0) > 0
        THEN 'AWAITING_AUTHORISATION'
      WHEN COALESCE(v_processing_request_count, 0) > 0
        AND COALESCE(v_blocked_request_count, 0) = 0
        AND COALESCE(v_failed_request_count, 0) = 0
        THEN 'PROCESSING'
      WHEN COALESCE(v_bank_return_event_count, 0) > 0
        AND COALESCE(v_applied_reversal_item_count, 0) = 0
        THEN 'TRUE_SETTLED_REVERSAL_REQUIRED'
      WHEN COALESCE(v_applied_reversal_item_count, 0) > 0
        THEN 'SETTLED_REVERSAL_APPLIED'
      WHEN v_can_unwind_failed_payment THEN 'NO_MONEY_UNWIND'
      WHEN v_can_cancel_payment_attempt THEN 'PRE_BANK_CANCEL'
      WHEN v_can_reverse_settled_payment
        AND (
          COALESCE(v_bank_failure_event_count, 0) > 0
          OR COALESCE(v_transfer_failure_count, 0) > 0
        )
        THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      WHEN v_can_reverse_settled_payment THEN 'SETTLED_NO_CORRECTION_REQUIRED'
      WHEN v_can_review_bank_evidence THEN 'AMBIGUOUS_REVIEW_REQUIRED'
      ELSE 'NONE'
    END,
    'source', 'pay_batch_get_summary',
    'derived_state', v_derived_correction_state,
    'can_reverse_settled_payment', v_can_reverse_settled_payment,
    'settled_reversal_required', (
      (
        COALESCE(v_open_settled_reversal_request_count, 0) > 0
        AND COALESCE(v_processing_request_count, 0) = 0
        AND COALESCE(v_work_item_pending_count, 0) = 0
        AND COALESCE(v_work_item_processing_count, 0) = 0
      )
      OR (
        COALESCE(v_bank_return_event_count, 0) > 0
        AND COALESCE(v_applied_reversal_item_count, 0) = 0
        AND COALESCE(v_processing_request_count, 0) = 0
        AND COALESCE(v_work_item_pending_count, 0) = 0
        AND COALESCE(v_work_item_processing_count, 0) = 0
      )
    ),
    'settlement_evidence_count', COALESCE(v_settlement_evidence_count, 0),
    'bank_failure_event_count', COALESCE(v_bank_failure_event_count, 0),
    'bank_return_event_count', COALESCE(v_bank_return_event_count, 0),
    'open_settled_reversal_request_count', COALESCE(v_open_settled_reversal_request_count, 0),
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'processing_request_count', COALESCE(v_processing_request_count, 0),
    'blocked_request_count', COALESCE(v_blocked_request_count, 0),
    'failed_request_count', COALESCE(v_failed_request_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'applied_reversal_item_count', COALESCE(v_applied_reversal_item_count, 0),
    'transfer_failure_count', COALESCE(v_transfer_failure_count, 0),
    'transfer_completed_count', COALESCE(v_transfer_completed_count, 0)
  );

  IF v_blocked_funds_payment_issue IS NOT NULL THEN
    v_movement_classification := v_movement_classification || jsonb_build_object(
      'blocked_funds_issue', v_blocked_funds_payment_issue,
      'blocked_funds_action_required', true,
      'bank_status_label', 'Bank unavailable — unsent payments can be retried',
      'issue_kind', 'BLOCKED_FUNDS',
      'can_retry_blocked_funds', v_can_retry_blocked_funds
    );
  END IF;

  v_movement_classification := v_movement_classification || jsonb_build_object(
    'classification', CASE
      WHEN v_batch_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'PAID_OR_SETTLED'
      WHEN v_batch_recommended_action = 'CHECK_PROVIDER_STATUS' THEN 'PROVIDER_OUTCOME_UNKNOWN'
      WHEN v_batch_recommended_action = 'RETRY_PROVIDER_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
      WHEN v_batch_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN COALESCE(v_batch_payment_lifecycle_state, 'PROVIDER_FAILED_NO_MONEY')
      WHEN v_batch_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN COALESCE(v_batch_payment_lifecycle_state, 'LOCAL_PREPARED_NOT_SENT')
      ELSE COALESCE(v_movement_classification->>'classification', v_batch_payment_lifecycle_state, 'NONE')
    END,
    'payment_lifecycle_state', v_batch_payment_lifecycle_state,
    'payment_lifecycle_label', v_batch_payment_lifecycle_label,
    'recommended_action', v_batch_recommended_action,
    'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
    'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
    'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
    'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
    'can_reverse_settled_payment', false,
    'settled_reversal_required', false,
    'action_source', 'pay_payment_cancelability_diagnostic'
  );

  v_manual_actions := jsonb_build_object(
    'can_cancel_payment_attempt', COALESCE(v_whole_batch_cancel_available, false) OR COALESCE(v_batch_can_pre_provider_cancel, false),
    'can_unwind_failed_payment', lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
    'can_reverse_settled_payment', false,
    'can_recover_overpayment', lower(btrim(COALESCE(v_batch_cancelability_diagnostic->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
    'can_review_bank_evidence', COALESCE(v_batch_requires_bank_check, false),
    'can_retry_blocked_funds', v_can_retry_blocked_funds,
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_status_label', v_retry_status_label,
    'retry_button_label', v_retry_button_label,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason,
    'payment_lifecycle_state', v_batch_payment_lifecycle_state,
    'payment_lifecycle_label', v_batch_payment_lifecycle_label,
    'recommended_action', v_batch_recommended_action,
    'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
    'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
    'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
    'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb),
    'action_source', 'pay_payment_cancelability_diagnostic'
  );


  SELECT jsonb_build_object(
    'queued_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'QUEUED'),
    'sent_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'SENT'),
    'failed_count', COUNT(*) FILTER (WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) = 'FAILED'),
    'external_correction_notice', false,
    'admin_notice_required', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED','PARTIALLY_UNWOUND','PARTIALLY_REVERSED','REVERSED','NO_MONEY_UNWOUND')
    )
  )
  INTO v_communication_status
  FROM public.mail_outbox
  WHERE public.mail_outbox.context_id = p_pay_batch_id
     OR public.mail_outbox.reference ILIKE '%' || p_pay_batch_id::text || '%';

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'finance_case_id', CASE WHEN correction_finance_rollup.finance_case_id IS NULL THEN NULL ELSE correction_finance_rollup.finance_case_id::text END,
        'correction_item_kind', correction_finance_rollup.correction_item_kind,
        'item_count', correction_finance_rollup.item_count,
        'amount_ex_vat', correction_finance_rollup.amount_ex_vat,
        'amount_inc_vat', correction_finance_rollup.amount_inc_vat
      )
      ORDER BY correction_finance_rollup.finance_case_id::text NULLS LAST, correction_finance_rollup.correction_item_kind
    ),
    '[]'::jsonb
  )
  INTO v_finance_case_correction_summary
  FROM (
    SELECT
      public.pay_payment_correction_items.finance_case_id,
      public.pay_payment_correction_items.correction_item_kind,
      COUNT(*)::integer AS item_count,
      ROUND(COALESCE(SUM(COALESCE(public.pay_payment_correction_items.amount_ex_vat, 0)), 0), 2)::numeric AS amount_ex_vat,
      ROUND(COALESCE(SUM(COALESCE(public.pay_payment_correction_items.amount_inc_vat, 0)), 0), 2)::numeric AS amount_inc_vat
    FROM public.pay_payment_correction_items
    WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
      AND public.pay_payment_correction_items.status = 'APPLIED'
      AND public.pay_payment_correction_items.finance_case_id IS NOT NULL
    GROUP BY
      public.pay_payment_correction_items.finance_case_id,
      public.pay_payment_correction_items.correction_item_kind
  ) AS correction_finance_rollup;

  SELECT jsonb_build_object(
    'request_count', COUNT(DISTINCT public.pay_payment_correction_requests.id),
    'work_items', COALESCE(
      (
        SELECT jsonb_object_agg(work_status_counts.status, work_status_counts.item_count ORDER BY work_status_counts.status)
        FROM (
          SELECT
            public.pay_payment_correction_work_items.status,
            COUNT(*)::integer AS item_count
          FROM public.pay_payment_correction_work_items
          WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id
          GROUP BY public.pay_payment_correction_work_items.status
        ) AS work_status_counts
      ),
      '{}'::jsonb
    ),
    'latest_request_status', v_latest_correction_request_status,
    'display_state', CASE
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      )
      AND (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'PARTLY_APPLIED_REVIEW_NEEDED'
      WHEN (
        COALESCE(v_work_item_pending_count, 0) > 0
        OR COALESCE(v_work_item_processing_count, 0) > 0
        OR COALESCE(v_processing_request_count, 0) > 0
      ) THEN 'PROCESSING'
      WHEN (
        COALESCE(v_work_item_blocked_count, 0) > 0
        OR COALESCE(v_work_item_failed_retryable_count, 0) > 0
        OR COALESCE(v_work_item_failed_final_count, 0) > 0
        OR COALESCE(v_blocked_request_count, 0) > 0
        OR COALESCE(v_failed_request_count, 0) > 0
      ) THEN 'ACTION_REQUIRED'
      ELSE v_derived_correction_state
    END,
    'open_request_id', CASE WHEN v_open_correction_request_id IS NULL THEN NULL ELSE v_open_correction_request_id::text END,
    'awaiting_authorisation_count', COALESCE(v_awaiting_authorisation_count, 0),
    'processing_request_count', COALESCE(v_processing_request_count, 0),
    'blocked_request_count', COALESCE(v_blocked_request_count, 0),
    'failed_request_count', COALESCE(v_failed_request_count, 0),
    'work_item_pending_count', COALESCE(v_work_item_pending_count, 0),
    'work_item_processing_count', COALESCE(v_work_item_processing_count, 0),
    'work_item_blocked_count', COALESCE(v_work_item_blocked_count, 0),
    'work_item_failed_retryable_count', COALESCE(v_work_item_failed_retryable_count, 0),
    'work_item_failed_final_count', COALESCE(v_work_item_failed_final_count, 0),
    'requires_user_action', (
      v_derived_correction_state IN ('ACTION_REQUIRED','SETTLED_RETURNED')
      OR COALESCE(v_blocked_request_count, 0) > 0
      OR COALESCE(v_failed_request_count, 0) > 0
      OR v_work_item_requires_user_action
    ),
    'processing_continues', v_work_item_processing_continues
  )
  INTO v_correction_progress
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id;


  return
    jsonb_build_object(
      'ok', true,
      'bootstrap_only', false,
      'detail_mode_requested', v_detail_mode,
      'detail_mode_applied', 'FULL',
      'available_sections', v_available_sections,
      'recommended_page_size', v_effective_page_size,
      'candidate_count', COALESCE(v_candidate_count, 0),
      'item_count', COALESCE(v_item_count, 0),
      'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
      'transfer_count', COALESCE(v_transfer_count, 0),
      'provider_submitted_transfer_count', COALESCE(v_provider_submitted_transfer_count, 0),
      'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
      'pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
      'failed_transfer_count', COALESCE(v_failed_transfer_count, 0),
      'ambiguous_transfer_count', COALESCE(v_ambiguous_transfer_count, 0),
      'attempted_but_unproven_transfer_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
      'attempted_but_unproven_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
      'freshness', jsonb_build_object(
        'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
        'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
        'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
        'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
        'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
        'freshness_is_stale', COALESCE(v_freshness_is_stale, false),
        'stale_reason_counts', COALESCE(v_stale_reason_counts, '{}'::jsonb),
        'freshness_result_json', COALESCE(to_jsonb(v_batch) -> 'freshness_result_json', '{}'::jsonb)
      ),
      'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
      'payment_execution_review', v_payment_execution_review,
      'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
      'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
      'review_reason_code', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_review_reason_code ELSE NULL::text END,
      'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
      'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
      'payment_lifecycle_state', v_batch_payment_lifecycle_state,
      'payment_lifecycle_label', v_batch_payment_lifecycle_label,
      'recommended_action', v_batch_recommended_action,
      'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
      'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
      'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
      'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
      'db_status', v_batch.status,
      'retry_state', v_retry_state,
      'retry_after_utc', v_retry_after_utc,
      'retry_reason', v_retry_reason,
      'next_retry_description', v_next_retry_description,
      'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
      'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
      'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
      'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
      'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
      'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
      'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb)
    )
    || jsonb_build_object(
      'live_signal_version', COALESCE(v_batch_signal_version, 0),
      'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
      'alert_version', COALESCE(v_batch_alert_version, 0),
      'overview_version', COALESCE(v_batch_overview_version, 0),
      'last_status_hash', v_batch_last_status_hash,
      'last_alert_hash', v_batch_last_alert_hash,
      'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb)
    )
    || jsonb_build_object(
      'bank_csv_export_json', v_batch.bank_csv_export_json,
      'execution_intent_json', v_execution_intent_json,
      'settlement_confirmation_json', v_batch.settlement_confirmation_json,
      'can_create_bank_csv_file', v_can_create_bank_csv_file,
      'can_start_standard_execution', v_can_start_standard_execution,
      'can_start_csv_settlement', v_can_start_csv_settlement,
      'can_start_external_settlement', v_can_start_external_settlement,
      'has_cloudtms_csv_export', v_has_cloudtms_csv_export,
      'csv_export_matches_current_transfers', v_csv_export_matches_current_transfers,
      'has_external_submission_evidence', v_has_external_submission_evidence,
      'execution_mode_pending', v_execution_mode_pending,
      'suppress_remittances_pending', v_suppress_remittances_pending,
      'current_transfer_hash', v_current_transfer_hash,
      'pending_transfer_hash', v_pending_transfer_hash,
      'stable_transfer_hash', v_stable_transfer_hash,
      'execution_transfer_hash', v_execution_transfer_hash,
      'csv_comparison_transfer_hash', v_csv_comparison_transfer_hash,
      'csv_export_match_basis', v_csv_export_match_basis,

      -- ✅ NEW: batch kind + channels for UI
      'batch_kind', v_batch_kind,
      'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
      'pay_channels_present', v_pay_channels_present,
      'active_effective_item_count', COALESCE(v_active_effective_item_count, 0),
      'active_effective_amount_ex_vat', COALESCE(v_active_effective_amount_ex_vat, 0),
      'active_effective_amount_inc_vat', COALESCE(v_active_effective_amount_inc_vat, 0),
      'active_item_count', COALESCE(v_active_effective_item_count, 0),
      'active_batch_item_count', COALESCE(v_active_effective_item_count, 0),
      'active_payment_item_count', COALESCE(v_active_effective_item_count, 0),
      'active_bank_out', COALESCE(v_active_effective_amount_ex_vat, 0),
      'payment_issue_candidate_count', COALESCE(v_payment_issue_candidate_count, 0),
      'has_payment_issue_candidates', COALESCE(v_payment_issue_candidate_count, 0) > 0,

      -- ✅ child modal datasets
      'candidate_breakdown', v_candidate_breakdown,
      'candidate_lines', v_candidate_lines,
      'finance_case_groups', v_finance_case_groups,
      'finance_summaries', v_finance_summaries,
      'remittance_summary', v_remittance_summary,
      'communications', v_communications_summary,

      -- payment correction / bank evidence / manual action summaries
      'payment_correction', v_payment_correction,
      'bank_evidence', v_bank_evidence,
      'movement_classification', v_movement_classification
    )
    || jsonb_build_object(
      'manual_actions', v_manual_actions,
      'communication_status', v_communication_status,
      'last_funds_check_at_utc', v_batch.last_funds_check_at_utc,
      'last_funds_check_json', v_batch.last_funds_check_json,
      'blocked_funds_required_gbp', v_blocked_funds_required_gbp,
      'blocked_funds_available_gbp', v_blocked_funds_available_gbp,
      'blocked_funds_required_gbp_display', v_blocked_funds_required_gbp_display,
      'blocked_funds_available_gbp_display', v_blocked_funds_available_gbp_display,
      'blocked_funds_sufficient', v_blocked_funds_sufficient,
      'blocked_funds_provider', v_blocked_funds_provider,
      'blocked_funds_env', v_blocked_funds_env,
      'blocked_funds_account_ref', v_blocked_funds_account_ref,
      'banking_alerts', v_banking_alerts,
      'banking_alert_kind', v_banking_alert_kind,
      'banking_alert_severity', v_banking_alert_severity,
      'banking_alert_label', v_banking_alert_label,
      'banking_alert_reason', v_banking_alert_reason,
      'banking_alert_fingerprint', v_banking_alert_fingerprint,
      'banking_alert_acknowledged_for_user', v_banking_alert_acknowledged_for_user,
      'banking_alert_requires_attention', v_banking_alert_requires_attention,
      'can_retry_blocked_funds', v_can_retry_blocked_funds,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false),
      'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
      'retry_operation_status', v_retry_operation_status,
      'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
      'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
      'retry_status_label', v_retry_status_label,
      'retry_button_label', v_retry_button_label,
      'retry_button_visible', COALESCE(v_retry_button_visible, false),
      'retry_button_disabled_reason', v_retry_button_disabled_reason,
      'no_submission_evidence_flags', v_no_submission_evidence_flags,
      'blocked_funds_payment_issue', v_blocked_funds_payment_issue,
      'payment_issues', v_payment_issues,
      'finance_case_correction_summary', v_finance_case_correction_summary,
      'correction_progress', v_correction_progress,

      -- schedule recommendations for UI preselect (includes default funding account)
      'schedule_recommendations', jsonb_build_object(
        'default_schedule_umbrella_local', v_default_schedule_umbrella_local,
        'default_schedule_paye_local', v_default_schedule_paye_local,
        'funds_warning_hours_json', v_funds_warning_hours_json,
        'rail_default_funding_account_ref', v_rail_default_funding_account_ref
      ),

      -- authorisation summary for Banking UI
      'auth', v_auth,

      'batch', (
        jsonb_build_object(
          'id', v_batch.id::text,
          'bootstrap_only', false,
          'candidate_count', COALESCE(v_candidate_count, 0),
          'item_count', COALESCE(v_item_count, 0),
          'item_breakdown_count', COALESCE(v_item_breakdown_count, 0),
          'transfer_count', COALESCE(v_transfer_count, 0),
          'provider_submitted_transfer_count', COALESCE(v_provider_submitted_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
          'failed_transfer_count', COALESCE(v_failed_transfer_count, 0),
          'ambiguous_transfer_count', COALESCE(v_ambiguous_transfer_count, 0),
          'attempted_but_unproven_transfer_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
          'attempted_but_unproven_count', COALESCE(v_attempted_but_unproven_transfer_count, 0),
          'freshness_validation_status', to_jsonb(v_batch) ->> 'freshness_validation_status',
          'freshness_checked_at_utc', to_jsonb(v_batch) ->> 'freshness_checked_at_utc',
          'freshness_result_hash', to_jsonb(v_batch) ->> 'freshness_result_hash',
          'freshness_scope_hash', to_jsonb(v_batch) ->> 'freshness_scope_hash',
          'freshness_operation_id', to_jsonb(v_batch) ->> 'freshness_operation_id',
          'freshness_is_stale', COALESCE(v_freshness_is_stale, false),
          'bank_csv_export_json', v_batch.bank_csv_export_json,
          'execution_intent_json', v_execution_intent_json,
          'settlement_confirmation_json', v_batch.settlement_confirmation_json
        )
        || jsonb_build_object(
          'can_create_bank_csv_file', v_can_create_bank_csv_file,
          'can_start_standard_execution', v_can_start_standard_execution,
          'can_start_csv_settlement', v_can_start_csv_settlement,
          'can_start_external_settlement', v_can_start_external_settlement,
          'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
          'payment_execution_review', v_payment_execution_review,
          'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
          'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
          'review_reason_code', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_review_reason_code ELSE NULL::text END,
          'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
          'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
          'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
          'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
          'has_cloudtms_csv_export', v_has_cloudtms_csv_export,
          'csv_export_matches_current_transfers', v_csv_export_matches_current_transfers,
          'has_external_submission_evidence', v_has_external_submission_evidence,
          'execution_mode_pending', v_execution_mode_pending,
          'suppress_remittances_pending', v_suppress_remittances_pending,
          'current_transfer_hash', v_current_transfer_hash,
          'pending_transfer_hash', v_pending_transfer_hash,
          'stable_transfer_hash', v_stable_transfer_hash,
          'execution_transfer_hash', v_execution_transfer_hash,
          'csv_comparison_transfer_hash', v_csv_comparison_transfer_hash,
          'csv_export_match_basis', v_csv_export_match_basis,
          'active_effective_item_count', COALESCE(v_active_effective_item_count, 0),
          'active_effective_amount_ex_vat', COALESCE(v_active_effective_amount_ex_vat, 0),
          'active_effective_amount_inc_vat', COALESCE(v_active_effective_amount_inc_vat, 0),
          'active_item_count', COALESCE(v_active_effective_item_count, 0),
          'active_batch_item_count', COALESCE(v_active_effective_item_count, 0),
          'active_payment_item_count', COALESCE(v_active_effective_item_count, 0),
          'active_bank_out', COALESCE(v_active_effective_amount_ex_vat, 0),
          'payment_issue_candidate_count', COALESCE(v_payment_issue_candidate_count, 0),
          'has_payment_issue_candidates', COALESCE(v_payment_issue_candidate_count, 0) > 0,
          'pay_date', v_batch.pay_date::text,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'same_week_paye_override_used', v_batch.same_week_paye_override_used,
          'same_week_paye_override_reason', v_batch.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', v_batch.same_week_paye_override_verified_at_utc,
          'same_week_paye_override_verified_by_user_id', case when v_batch.same_week_paye_override_verified_by_user_id is null then null else v_batch.same_week_paye_override_verified_by_user_id::text end,
          'source_workbench_session_id', case when v_batch.source_workbench_session_id is null then null else v_batch.source_workbench_session_id::text end,
          'source_snapshot_run_id', case when v_batch.source_snapshot_run_id is null then null else v_batch.source_snapshot_run_id::text end,
          'source_session_version', v_batch.source_session_version,
          'execution_commit_state', v_batch.execution_commit_state,
          'execution_commit_ref', v_batch.execution_commit_ref
        )
        || (jsonb_build_object(
          'execution_committed_at_utc', v_batch.execution_committed_at_utc,
          'created_at_utc', v_batch.created_at_utc,
          'created_by_user_id', case when v_batch.created_by_user_id is null then null else v_batch.created_by_user_id::text end,
          'status', v_batch.status,
          'db_status', v_batch.status,
          'payment_lifecycle_state', v_batch_payment_lifecycle_state,
          'payment_lifecycle_label', v_batch_payment_lifecycle_label,
          'recommended_action', v_batch_recommended_action,
          'whole_batch_cancel_available', COALESCE(v_whole_batch_cancel_available, false),
          'can_pre_provider_cancel', COALESCE(v_batch_can_pre_provider_cancel, false),
          'requires_bank_check', COALESCE(v_batch_requires_bank_check, false),
          'requires_provider_cancel', COALESCE(v_batch_requires_provider_cancel, false),
          'retry_state', v_retry_state,
          'retry_after_utc', v_retry_after_utc,
          'retry_reason', v_retry_reason,
          'next_retry_description', v_next_retry_description,
          'partial_cancel_count', COALESCE(v_partial_cancel_count, 0),
          'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
          'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
          'manual_adjustments_carried_forward_count', COALESCE(v_manual_adjustments_carried_forward_count, 0),
          'manual_adjustment_carry_forward_records_json', COALESCE(v_manual_adjustment_carry_forward_records_json, '[]'::jsonb),
          'remittance_already_sent', COALESCE(v_remittance_already_sent, false),
          'support_details_json', COALESCE(v_batch_support_details_json, '{}'::jsonb),
          'live_signal_version', COALESCE(v_batch_signal_version, 0),
          'payment_status_version', COALESCE(v_batch_payment_status_version, 0),
          'correction_progress_version', COALESCE(v_batch_correction_progress_version, 0),
          'alert_version', COALESCE(v_batch_alert_version, 0),
          'overview_version', COALESCE(v_batch_overview_version, 0),
          'last_status_hash', v_batch_last_status_hash,
          'last_alert_hash', v_batch_last_alert_hash,
          'provider_webhook_evidence_json', COALESCE(v_provider_webhook_evidence_json, '{}'::jsonb),
          'banking_system_snapshot', v_batch.banking_system_snapshot,
          'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,

          -- Neutral (rail-generic) manual confirm aliases (keep legacy keys too)
          'manual_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'manual_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'monzo_confirmed_at_utc', v_batch.monzo_confirmed_at_utc,
          'monzo_confirmed_by_user_id', case when v_batch.monzo_confirmed_by_user_id is null then null else v_batch.monzo_confirmed_by_user_id::text end,

          'last_status_checked_at_utc', v_batch.last_status_checked_at_utc,
          'last_funds_check_at_utc', v_batch.last_funds_check_at_utc,
          'last_funds_check_json', v_batch.last_funds_check_json) || jsonb_build_object(
          'funding_account_ref', v_batch.funding_account_ref,
          'blocked_funds_required_gbp', v_blocked_funds_required_gbp,
          'blocked_funds_available_gbp', v_blocked_funds_available_gbp,
          'blocked_funds_required_gbp_display', v_blocked_funds_required_gbp_display,
          'blocked_funds_available_gbp_display', v_blocked_funds_available_gbp_display,
          'blocked_funds_sufficient', v_blocked_funds_sufficient,
          'blocked_funds_provider', v_blocked_funds_provider,
          'blocked_funds_env', v_blocked_funds_env,
          'blocked_funds_account_ref', v_blocked_funds_account_ref,
          'banking_alerts', v_banking_alerts,
          'banking_alert_kind', v_banking_alert_kind,
          'banking_alert_severity', v_banking_alert_severity,
          'banking_alert_label', v_banking_alert_label,
          'banking_alert_reason', v_banking_alert_reason,
          'banking_alert_fingerprint', v_banking_alert_fingerprint,
          'banking_alert_acknowledged_for_user', v_banking_alert_acknowledged_for_user,
          'banking_alert_requires_attention', v_banking_alert_requires_attention
        ))
        || jsonb_build_object(
          'can_retry_blocked_funds', v_can_retry_blocked_funds,
          'no_submission_evidence_flags', v_no_submission_evidence_flags,
          'blocked_funds_payment_issue', v_blocked_funds_payment_issue,
          'payment_issues', v_payment_issues,
          'provider_submit_diagnostic', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_diagnostic ELSE NULL::jsonb END,
          'payment_execution_review', v_payment_execution_review,
          'manual_resolution_available', COALESCE(v_provider_submit_manual_resolution_available, false),
          'safe_retry_available', COALESCE(v_provider_submit_safe_retry_available, false),
          'review_reason_code', CASE WHEN v_provider_submit_actual_context THEN v_provider_submit_review_reason_code ELSE NULL::text END,
          'provider_submission_status', CASE WHEN v_provider_submit_actual_context THEN v_provider_submission_status ELSE NULL::text END,
          'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
          'provider_submit_issue_present', COALESCE(v_provider_submit_issue_present, false),
          'provider_submit_is_diagnostic_only', COALESCE(v_provider_submit_is_diagnostic_only, false),
          -- Rail-generic scheduling/execution fields
          'rail_provider_snapshot', v_batch.rail_provider_snapshot,
          'rail_env_snapshot', v_batch.rail_env_snapshot,
          'schedule_kind', v_batch.schedule_kind,
          'scheduled_at_utc', v_batch.scheduled_at_utc,
          'executing_started_at_utc', v_batch.executing_started_at_utc,

          -- Bulk payment reference fields
          'bulk_ref_num', v_batch.bulk_ref_num,
          'bulk_ref_date', case when v_batch.bulk_ref_date is null then null else v_batch.bulk_ref_date::text end,
          'bulk_reference', v_batch.bulk_reference
        )
      ),
      'candidates', v_candidates,
      'transfers', v_transfers,
      'items', v_items
    );
end;
$$;






DROP FUNCTION IF EXISTS public.pay_batches_list(integer, integer, text);



CREATE OR REPLACE FUNCTION public.pay_batches_list(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_status text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_limit int := greatest(1, least(coalesce(p_limit,50), 500));
  v_offset int := greatest(coalesce(p_offset,0), 0);
  v_status text := upper(nullif(btrim(coalesce(p_status,'')), ''));
  v_total int := 0;
  v_rows jsonb := '[]'::jsonb;
  v_alert_registry jsonb := jsonb_build_object('alerts', '[]'::jsonb, 'unacknowledged_count', 0, 'highest_severity', NULL::text, 'highest_label', NULL::text);
  v_nav_alerts jsonb := '[]'::jsonb;
  v_banking_unacknowledged_alert_count integer := 0;
  v_banking_highest_alert_label text := NULL::text;
  v_banking_highest_alert_severity text := NULL::text;
  v_alert_actor_user_id uuid := COALESCE(p_actor_user_id, '00000000-0000-0000-0000-000000000000'::uuid);
  v_alert_metadata_degraded boolean := false;
  v_alert_metadata_warning jsonb := NULL::jsonb;
begin
  BEGIN
    v_alert_registry := public.banking_alerts_active_for_user(
      v_alert_actor_user_id,
      NULL::text,
      NULL::uuid,
      true,
      0
    );
  EXCEPTION WHEN OTHERS THEN
    v_alert_registry := jsonb_build_object(
      'ok', true,
      'alerts', '[]'::jsonb,
      'unacknowledged_count', 0,
      'highest_severity', NULL::text,
      'highest_label', NULL::text,
      'alert_hash', NULL::text,
      'degraded', true
    );
    v_alert_metadata_degraded := true;
    v_alert_metadata_warning := jsonb_build_object(
      'code', 'PAY_BATCHES_LIST_ALERT_METADATA_DEGRADED',
      'message', 'Banking payment batch list was loaded without live alert metadata because alert enrichment failed.',
      'source', 'banking_alerts_active_for_user',
      'sqlstate', SQLSTATE,
      'error', SQLERRM
    );
  END;

  BEGIN
  SELECT
    COALESCE(jsonb_agg(nav_alerts.alert_json ORDER BY nav_alerts.severity_rank DESC, nav_alerts.sort_at_utc DESC NULLS LAST, nav_alerts.alert_fingerprint ASC), '[]'::jsonb),
    count(*)::integer,
    (array_agg(nav_alerts.alert_json ->> 'label' ORDER BY nav_alerts.severity_rank DESC, nav_alerts.sort_at_utc DESC NULLS LAST, nav_alerts.alert_fingerprint ASC))[1],
    (array_agg(nav_alerts.alert_json ->> 'severity' ORDER BY nav_alerts.severity_rank DESC, nav_alerts.sort_at_utc DESC NULLS LAST, nav_alerts.alert_fingerprint ASC))[1]
  INTO
    v_nav_alerts,
    v_banking_unacknowledged_alert_count,
    v_banking_highest_alert_label,
    v_banking_highest_alert_severity
  FROM (
    SELECT
      alert_items.alert_json,
      CASE
        WHEN (alert_items.alert_json ->> 'severity_rank') ~ '^[0-9]+$' THEN (alert_items.alert_json ->> 'severity_rank')::integer
        ELSE 0
      END AS severity_rank,
      CASE
        WHEN NULLIF(alert_items.alert_json ->> 'sort_at_utc', '') IS NULL THEN NULL::timestamptz
        WHEN (alert_items.alert_json ->> 'sort_at_utc') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:?[0-9]{2})?$' THEN (alert_items.alert_json ->> 'sort_at_utc')::timestamptz
        ELSE NULL::timestamptz
      END AS sort_at_utc,
      alert_items.alert_json ->> 'alert_fingerprint' AS alert_fingerprint
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)) = 'array' THEN COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS alert_items(alert_json)
    WHERE (
      CASE
        WHEN lower(btrim(coalesce(alert_items.alert_json ->> 'acknowledged_for_current_user', 'false'))) in ('true','t','1','yes','y','on') THEN true
        ELSE false
      END
    ) = false
  ) AS nav_alerts;
  EXCEPTION WHEN OTHERS THEN
    v_nav_alerts := '[]'::jsonb;
    v_banking_unacknowledged_alert_count := 0;
    v_banking_highest_alert_label := NULL::text;
    v_banking_highest_alert_severity := NULL::text;
    v_alert_metadata_degraded := true;
    v_alert_metadata_warning := COALESCE(v_alert_metadata_warning, jsonb_build_object(
      'code', 'PAY_BATCHES_LIST_ALERT_EXPANSION_DEGRADED',
      'message', 'Banking payment batch list was loaded without live alert expansion because alert metadata could not be parsed safely.',
      'source', 'pay_batches_list.nav_alert_expansion',
      'sqlstate', SQLSTATE,
      'error', SQLERRM
    ));
  END;

  v_nav_alerts := COALESCE(v_nav_alerts, '[]'::jsonb);
  v_banking_unacknowledged_alert_count := COALESCE(v_banking_unacknowledged_alert_count, 0);

  select count(*)::int
  into v_total
  from public.pay_batches pb
  where v_status is null or upper(coalesce(pb.status,'')) = v_status;

  select coalesce(
    jsonb_agg(
      (
        jsonb_build_object(
          'id', pb.id::text,
          'pay_date', pb.pay_date::text,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'authoritative_payment_date_source', pb.authoritative_payment_date_source,
          'created_at_utc', pb.created_at_utc,
          'created_by_user_id', case when pb.created_by_user_id is null then null else pb.created_by_user_id::text end,
          'status', pb.status,
          'db_status', pb.db_status,
          'payment_lifecycle_state', pb.payment_lifecycle_state,
          'payment_lifecycle_label', pb.payment_lifecycle_label,
          'whole_batch_cancel_available', COALESCE(pb.whole_batch_cancel_available, false),
          'provider_failure_reason_groups_json', COALESCE(pb.provider_failure_reason_groups_json, '{}'::jsonb),
          'live_signal_version', COALESCE(pb.live_signal_version, 0),
          'payment_status_version', COALESCE(pb.payment_status_version, 0),
          'correction_progress_version', COALESCE(pb.correction_progress_version, 0),
          'overview_version', COALESCE(pb.overview_version, 0),
          'manual_adjustments_carried_forward_count', COALESCE(pb.manual_adjustments_carried_forward_count, 0),
          'partial_cancel_count', COALESCE(pb.partial_cancel_count, 0),
          'retry_later_count', COALESCE(pb.retry_later_count, 0),
          'provider_unknown_count', COALESCE(pb.provider_unknown_count, 0),
          'terminal_no_money_count', COALESCE(pb.terminal_no_money_count, 0),
          'paid_recovery_required_count', COALESCE(pb.paid_recovery_required_count, 0),
          'banking_alert_group_count', COALESCE(pb.banking_alert_group_count, 0),
          'recommended_action', pb.recommended_action,
          'banking_system_snapshot', pb.banking_system_snapshot,
          'external_paye_system_snapshot', pb.external_paye_system_snapshot,

          'batch_kind_fixed', pb.batch_kind_fixed,
          'batch_kind', pb.batch_kind,
          'pay_channels_present', pb.pay_channels_present,
          'batch_display_classification', pb.batch_display_classification,

          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', pb.same_week_paye_override_verified_at_utc,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,

          'source_workbench_session_id', case when pb.source_workbench_session_id is null then null else pb.source_workbench_session_id::text end,
          'source_snapshot_run_id', case when pb.source_snapshot_run_id is null then null else pb.source_snapshot_run_id::text end,
          'source_session_version', pb.source_session_version,
          'execution_commit_state', pb.execution_commit_state,
          'execution_commit_ref', pb.execution_commit_ref,
          'execution_committed_at_utc', pb.execution_committed_at_utc,

          'remittance_summary', jsonb_build_object(
            'candidate_count', pb.remittance_candidate_count,
            'sent_count', pb.remittance_sent_count,
            'unsent_count', pb.remittance_unsent_count,
            'error_count', pb.remittance_error_count,
            'latest_sent_at_utc', pb.remittance_latest_sent_at_utc,
            'all_sent', pb.remittance_all_sent,
            'trigger_statuses', pb.remittance_trigger_statuses
          )
        )
        || jsonb_build_object(
          'rail_provider_snapshot', pb.rail_provider_snapshot,
          'rail_env_snapshot', pb.rail_env_snapshot,
          'schedule_kind', pb.schedule_kind,
          'scheduled_at_utc', pb.scheduled_at_utc,
          'executing_started_at_utc', pb.executing_started_at_utc,
          'last_status_checked_at_utc', pb.last_status_checked_at_utc,
          'last_funds_check_at_utc', pb.last_funds_check_at_utc,
          'last_funds_check_json', pb.last_funds_check_json,

          'funding_account_ref', pb.funding_account_ref,
          'blocked_funds_required_gbp', pb.blocked_funds_required_gbp,
          'blocked_funds_available_gbp', pb.blocked_funds_available_gbp,
          'blocked_funds_provider', pb.blocked_funds_provider,
          'blocked_funds_env', pb.blocked_funds_env,
          'blocked_funds_account_ref', pb.blocked_funds_account_ref,
          'banking_alerts', pb.banking_alerts,
          'banking_alert_kind', pb.banking_alert_kind,
          'banking_alert_severity', pb.banking_alert_severity,
          'banking_alert_label', pb.banking_alert_label,
          'banking_alert_reason', pb.banking_alert_reason,
          'banking_alert_fingerprint', pb.banking_alert_fingerprint,
          'banking_alert_acknowledged_for_user', pb.banking_alert_acknowledged_for_user,
          'banking_alert_requires_attention', pb.banking_alert_requires_attention,

          'manual_confirmed_at_utc', pb.monzo_confirmed_at_utc,
          'manual_confirmed_by_user_id', case when pb.monzo_confirmed_by_user_id is null then null else pb.monzo_confirmed_by_user_id::text end,

          'monzo_confirmed_at_utc', pb.monzo_confirmed_at_utc,
          'monzo_confirmed_by_user_id', case when pb.monzo_confirmed_by_user_id is null then null else pb.monzo_confirmed_by_user_id::text end,

          'total_bank_out', pb.total_bank_out,
          'total_debt_created', pb.total_debt_created,

          'bulk_ref_num', pb.bulk_ref_num,
          'bulk_ref_date', case when pb.bulk_ref_date is null then null else pb.bulk_ref_date::text end,
          'bulk_reference', pb.bulk_reference,

          'auth_required_quantity', pb.auth_required_quantity,
          'auth_approved_count', pb.auth_approved_count,
          'auth_label', pb.auth_label,
          'auth_state', pb.auth_state
        )
        || jsonb_build_object(
          'movement_classification', pb.movement_classification,
          'correction_status', pb.correction_status,
          'correction_required_count', pb.correction_required_count,
          'failed_returned_event_count', pb.failed_returned_event_count,
          'unwound_amount_inc_vat', pb.unwound_amount_inc_vat,
          'reversed_amount_inc_vat', pb.reversed_amount_inc_vat,
          'remaining_paid_amount_inc_vat', pb.remaining_paid_amount_inc_vat,
          'latest_bank_failure_at_utc', pb.latest_bank_failure_at_utc,
          'latest_correction_action_at_utc', pb.latest_correction_action_at_utc,
          'latest_correction_request_status', pb.latest_correction_request_status,
          'latest_correction_request_kind', pb.latest_correction_request_kind,
          'correction_processing_count', pb.correction_processing_count,
          'correction_waiting_approval_count', pb.correction_waiting_approval_count,
          'correction_blocked_count', pb.correction_blocked_count,
          'correction_failed_count', pb.correction_failed_count,
          'correction_work_blocked_count', pb.correction_work_blocked_count,
          'correction_work_failed_retryable_count', pb.correction_work_failed_retryable_count,
          'correction_work_failed_final_count', pb.correction_work_failed_final_count,
          'correction_work_pending_count', pb.correction_work_pending_count,
          'correction_work_processing_count', pb.correction_work_processing_count,
          'correction_requires_user_action', pb.correction_requires_user_action
        )
      )
      order by pb.created_at_utc desc, pb.id desc
    ),
    '[]'::jsonb
  )
  into v_rows
  from (
    select
      pb0.*,
      case
        when upper(coalesce(pb0.batch_kind_fixed,'')) = 'LOANS' then 'LOANS'
        when ch.channels is null then null
        when array_position(ch.channels,'PAYE') is not null and array_position(ch.channels,'UMBRELLA') is not null then 'MIXED'
        when array_position(ch.channels,'PAYE') is not null then 'PAYE'
        when array_position(ch.channels,'UMBRELLA') is not null then 'UMBRELLA'
        else null
      end as batch_kind,
      coalesce(to_jsonb(ch.channels), '[]'::jsonb) as pay_channels_present,
      case
        when upper(coalesce(pb0.batch_kind_fixed,'')) = 'LOANS' and coalesce(ft.has_payment_advance,false) = true and coalesce(ft.has_manual_credit,false) = false then 'PAYMENT_ADVANCE_PAYOUTS'
        when upper(coalesce(pb0.batch_kind_fixed,'')) = 'LOANS' and coalesce(ft.has_payment_advance,false) = false and coalesce(ft.has_manual_credit,false) = true then 'MANUAL_CREDIT_ADJUSTMENTS'
        when upper(coalesce(pb0.batch_kind_fixed,'')) = 'LOANS' then 'FINANCE_PAYOUTS'
        when ch.channels is null then null
        when array_position(ch.channels,'PAYE') is not null and array_position(ch.channels,'UMBRELLA') is not null then 'MIXED_PAYROLL'
        when array_position(ch.channels,'PAYE') is not null then 'PAYE_PAYROLL'
        when array_position(ch.channels,'UMBRELLA') is not null then 'UMBRELLA_PAYROLL'
        else null
      end as batch_display_classification,
      pbar.required_quantity as auth_required_quantity,
      pbar.state as auth_state,
      case
        when pbar.id is null then null
        else pbaa.approved_count
      end as auth_approved_count,
      case
        when pbar.id is null then null
        else (coalesce(pbaa.approved_count, 0)::text || '/' || pbar.required_quantity::text)
      end as auth_label,
      coalesce(rmt.candidate_count, 0) as remittance_candidate_count,
      coalesce(rmt.sent_count, 0) as remittance_sent_count,
      greatest(coalesce(rmt.candidate_count, 0) - coalesce(rmt.sent_count, 0), 0) as remittance_unsent_count,
      coalesce(rmt.error_count, 0) as remittance_error_count,
      rmt.latest_sent_at_utc as remittance_latest_sent_at_utc,
      case
        when coalesce(rmt.candidate_count, 0) = 0 then false
        else coalesce(rmt.all_sent, false)
      end as remittance_all_sent,
      coalesce(rmt.trigger_statuses, '[]'::jsonb) as remittance_trigger_statuses,
      corr.movement_classification,
      corr.correction_status,
      corr.correction_required_count,
      corr.failed_returned_event_count,
      corr.unwound_amount_inc_vat,
      corr.reversed_amount_inc_vat,
      corr.remaining_paid_amount_inc_vat,
      corr.latest_bank_failure_at_utc,
      corr.latest_correction_action_at_utc,
      corr.latest_correction_request_status,
      corr.latest_correction_request_kind,
      corr.correction_processing_count,
      corr.correction_waiting_approval_count,
      corr.correction_blocked_count,
      corr.correction_failed_count,
      corr.correction_work_blocked_count,
      corr.correction_work_failed_retryable_count,
      corr.correction_work_failed_final_count,
      corr.correction_work_pending_count,
      corr.correction_work_processing_count,
      corr.correction_requires_user_action,
      bf.blocked_funds_required_gbp,
      bf.blocked_funds_available_gbp,
      bf.blocked_funds_provider,
      bf.blocked_funds_env,
      bf.blocked_funds_account_ref,
      COALESCE(ba.banking_alerts, '[]'::jsonb) AS banking_alerts,
      ba.banking_alert_kind,
      ba.banking_alert_severity,
      ba.banking_alert_label,
      ba.banking_alert_reason,
      ba.banking_alert_fingerprint,
      COALESCE(ba.banking_alert_acknowledged_for_user, false) AS banking_alert_acknowledged_for_user,
      COALESCE(ba.banking_alert_requires_attention, false) AS banking_alert_requires_attention,
      pb0.status AS db_status,
      COALESCE(NULLIF(btrim(diag.diagnostic_json->>'payment_lifecycle_state'), ''), 'LOCAL_PREPARED_NOT_SENT') AS payment_lifecycle_state,
      CASE COALESCE(NULLIF(btrim(diag.diagnostic_json->>'payment_lifecycle_state'), ''), 'LOCAL_PREPARED_NOT_SENT')
        WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
        WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
        WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
        WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry later'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check provider'
        WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Failed — not paid'
        WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Failed — not paid'
        WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
        WHEN 'PAID_OR_SETTLED' THEN CASE WHEN diag.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment' ELSE 'Paid' END
        ELSE initcap(replace(lower(COALESCE(NULLIF(btrim(diag.diagnostic_json->>'payment_lifecycle_state'), ''), 'unknown')), '_', ' '))
      END AS payment_lifecycle_label,
      diag.diagnostic_json->>'recommended_action' AS recommended_action,
      lower(btrim(COALESCE(diag.diagnostic_json->>'whole_batch_cancel_available', 'false'))) IN ('true','1','yes','y','on') AS whole_batch_cancel_available,
      COALESCE(lifecycle_counts.manual_adjustments_carried_forward_count, 0) AS manual_adjustments_carried_forward_count,
      COALESCE(lifecycle_counts.partial_cancel_count, 0) AS partial_cancel_count,
      COALESCE(lifecycle_counts.retry_later_count, 0) AS retry_later_count,
      COALESCE(lifecycle_counts.provider_unknown_count, 0) AS provider_unknown_count,
      COALESCE(lifecycle_counts.terminal_no_money_count, 0) AS terminal_no_money_count,
      COALESCE(lifecycle_counts.paid_recovery_required_count, 0) AS paid_recovery_required_count,
      COALESCE(lifecycle_counts.banking_alert_group_count, 0) AS banking_alert_group_count,
      COALESCE(provider_failure_groups.provider_failure_reason_groups_json, '{}'::jsonb) AS provider_failure_reason_groups_json,
      COALESCE(batch_signal.version, 0) AS live_signal_version,
      COALESCE(batch_signal.payment_status_version, 0) AS payment_status_version,
      COALESCE(batch_signal.correction_progress_version, 0) AS correction_progress_version,
      COALESCE(batch_signal.overview_version, 0) AS overview_version
    from public.pay_batches pb0
    left join lateral (
      select
        array_agg(distinct upper(coalesce(pbi.pay_channel,'')) order by upper(coalesce(pbi.pay_channel,'')))
          filter (where upper(coalesce(pbi.pay_channel,'')) in ('PAYE','UMBRELLA')) as channels
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = pb0.id
        and pbi.item_type <> 'DEBT_CREATED'
    ) ch on true
    left join lateral (
      select
        bool_or(pa.case_type = 'PAYMENT_ADVANCE') as has_payment_advance,
        bool_or(pa.case_type = 'MANUAL_CREDIT_ADJUSTMENT') as has_manual_credit
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      join public.pay_advances pa
        on pa.id = pbi.finance_case_id
      where pbc.pay_batch_id = pb0.id
        and pbi.finance_case_id is not null
    ) ft on true
    left join lateral (
      select
        pbar0.id,
        pbar0.state,
        pbar0.required_quantity
      from public.pay_batch_auth_requests pbar0
      where pbar0.pay_batch_id = pb0.id
        and pbar0.state in ('AWAITING','AUTHORISED')
      order by pbar0.created_at_utc desc, pbar0.id desc
      limit 1
    ) pbar on true
    left join lateral (
      select
        count(*)::int as approved_count
      from public.pay_batch_auth_actions pbaa0
      where pbar.id is not null
        and pbaa0.auth_request_id = pbar.id
        and pbaa0.action in ('AUTHORISE','USE_GOLDEN_KEY')
    ) pbaa on true
    left join lateral (
      select
        count(*)::int as candidate_count,
        count(*) filter (where pbc0.remittance_sent_at_utc is not null)::int as sent_count,
        count(*) filter (where nullif(btrim(coalesce(pbc0.last_remittance_error,'')), '') is not null)::int as error_count,
        max(pbc0.remittance_sent_at_utc) as latest_sent_at_utc,
        bool_and(pbc0.remittance_sent_at_utc is not null) as all_sent,
        coalesce(
          to_jsonb(
            array_agg(distinct pbc0.remittance_trigger_status order by pbc0.remittance_trigger_status)
            filter (where pbc0.remittance_trigger_status is not null and btrim(coalesce(pbc0.remittance_trigger_status,'')) <> '')
          ),
          '[]'::jsonb
        ) as trigger_statuses
      from public.pay_batch_candidates pbc0
      where pbc0.pay_batch_id = pb0.id
    ) rmt on true
    left join lateral (
      select
        CASE
          WHEN COALESCE(
            pb0.last_funds_check_json #>> '{required_gbp}',
            pb0.last_funds_check_json #>> '{required}',
            pb0.last_funds_check_json #>> '{required_amount_gbp}',
            pb0.last_funds_check_json #>> '{required_amount}'
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(
              pb0.last_funds_check_json #>> '{required_gbp}',
              pb0.last_funds_check_json #>> '{required}',
              pb0.last_funds_check_json #>> '{required_amount_gbp}',
              pb0.last_funds_check_json #>> '{required_amount}'
            )::numeric
          ELSE NULL::numeric
        END AS blocked_funds_required_gbp,
        CASE
          WHEN COALESCE(
            pb0.last_funds_check_json #>> '{available_gbp}',
            pb0.last_funds_check_json #>> '{available}',
            pb0.last_funds_check_json #>> '{available_amount_gbp}',
            pb0.last_funds_check_json #>> '{available_amount}'
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(
              pb0.last_funds_check_json #>> '{available_gbp}',
              pb0.last_funds_check_json #>> '{available}',
              pb0.last_funds_check_json #>> '{available_amount_gbp}',
              pb0.last_funds_check_json #>> '{available_amount}'
            )::numeric
          ELSE NULL::numeric
        END AS blocked_funds_available_gbp,
        COALESCE(
          pb0.last_funds_check_json #>> '{rail_provider}',
          pb0.last_funds_check_json #>> '{provider}',
          pb0.rail_provider_snapshot
        ) AS blocked_funds_provider,
        COALESCE(
          pb0.last_funds_check_json #>> '{rail_env}',
          pb0.last_funds_check_json #>> '{env}',
          pb0.rail_env_snapshot
        ) AS blocked_funds_env,
        COALESCE(
          pb0.last_funds_check_json #>> '{funding_account_ref}',
          pb0.last_funds_check_json #>> '{account_ref}',
          pb0.funding_account_ref
        ) AS blocked_funds_account_ref
    ) bf on true
    left join lateral (
      SELECT
        COALESCE(jsonb_agg(alert_scope.alert_json ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC), '[]'::jsonb) AS banking_alerts,
        (array_agg(alert_scope.alert_json ->> 'alert_kind' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1] AS banking_alert_kind,
        (array_agg(alert_scope.alert_json ->> 'severity' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1] AS banking_alert_severity,
        (array_agg(alert_scope.alert_json ->> 'label' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1] AS banking_alert_label,
        (array_agg(alert_scope.alert_json ->> 'description' ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1] AS banking_alert_reason,
        (array_agg(alert_scope.alert_fingerprint ORDER BY alert_scope.severity_rank DESC, alert_scope.sort_at_utc DESC NULLS LAST, alert_scope.alert_fingerprint ASC))[1] AS banking_alert_fingerprint,
        COALESCE(bool_and(alert_scope.acknowledged_for_current_user), false) AS banking_alert_acknowledged_for_user,
        COALESCE(bool_or(alert_scope.acknowledged_for_current_user = false), false) AS banking_alert_requires_attention
      FROM (
        SELECT
          alert_items.alert_json,
          alert_items.alert_json ->> 'alert_fingerprint' AS alert_fingerprint,
          CASE
            WHEN (alert_items.alert_json ->> 'severity_rank') ~ '^[0-9]+$' THEN (alert_items.alert_json ->> 'severity_rank')::integer
            ELSE 0
          END AS severity_rank,
          CASE
            WHEN NULLIF(alert_items.alert_json ->> 'sort_at_utc', '') IS NULL THEN NULL::timestamptz
            WHEN (alert_items.alert_json ->> 'sort_at_utc') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?(Z|[+-][0-9]{2}:?[0-9]{2})?$' THEN (alert_items.alert_json ->> 'sort_at_utc')::timestamptz
            ELSE NULL::timestamptz
          END AS sort_at_utc,
          CASE
            WHEN lower(btrim(coalesce(alert_items.alert_json ->> 'acknowledged_for_current_user', 'false'))) in ('true','t','1','yes','y','on') THEN true
            ELSE false
          END AS acknowledged_for_current_user
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)) = 'array' THEN COALESCE(v_alert_registry -> 'alerts', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS alert_items(alert_json)
        WHERE alert_items.alert_json ->> 'pay_batch_id' = pb0.id::text
      ) AS alert_scope
    ) ba on true
    left join lateral (
      select public.pay_payment_cancelability_diagnostic(
        pb0.id,
        jsonb_build_object('scope_type', 'BATCH'),
        p_actor_user_id
      ) as diagnostic_json
    ) diag on true
    left join lateral (
      select
        COALESCE(count(distinct cf_rows.id), 0)::integer as manual_adjustments_carried_forward_count,
        COALESCE(count(distinct pci_pre.pay_batch_item_id), 0)::integer as partial_cancel_count,
        CASE
          WHEN lower(btrim(COALESCE(diag.diagnostic_json->>'requires_retry_later', 'false'))) IN ('true','1','yes','y','on')
            OR diag.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 1 ELSE 0
        END as retry_later_count,
        CASE WHEN diag.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 1 ELSE 0 END as provider_unknown_count,
        CASE WHEN COALESCE(NULLIF(btrim(diag.diagnostic_json->>'payment_lifecycle_state'), ''), '') IN ('PROVIDER_CANCELLED_NO_MONEY','PROVIDER_FAILED_NO_MONEY') THEN 1 ELSE 0 END as terminal_no_money_count,
        CASE WHEN diag.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 1 ELSE 0 END as paid_recovery_required_count,
        COALESCE(jsonb_array_length(COALESCE(ba.banking_alerts, '[]'::jsonb)), 0) as banking_alert_group_count
      from public.pay_batches as lifecycle_batch
      left join public.pay_manual_adjustment_carry_forwards as cf_rows
        on cf_rows.source_pay_batch_id = lifecycle_batch.id
        or cf_rows.target_pay_batch_id = lifecycle_batch.id
      left join public.pay_payment_correction_items as pci_pre
        on pci_pre.pay_batch_id = lifecycle_batch.id
       and pci_pre.status = 'APPLIED'
       and pci_pre.correction_item_kind = 'PRE_BANK_CANCEL'
      where lifecycle_batch.id = pb0.id
    ) lifecycle_counts on true
    left join public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = pb0.id
    left join lateral (
      SELECT COALESCE(jsonb_object_agg(failure_reason_groups.provider_failure_reason_group, failure_reason_groups.reason_count ORDER BY failure_reason_groups.provider_failure_reason_group), '{}'::jsonb) AS provider_failure_reason_groups_json
      FROM (
        SELECT
          UPPER(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, 'PROVIDER_FAILED_UNSPECIFIED'))) AS provider_failure_reason_group,
          COUNT(*)::integer AS reason_count
        FROM public.pay_bank_transfer_events AS provider_failure_event
        WHERE provider_failure_event.pay_batch_id = pb0.id
          AND NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), '') IS NOT NULL
          AND UPPER(BTRIM(COALESCE(provider_failure_event.normalised_state, provider_failure_event.provider_state, ''))) NOT IN ('COMPLETED','COMPLETE','PAID','SETTLED','EXECUTED','SUCCESS','SUCCEEDED')
        GROUP BY UPPER(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, 'PROVIDER_FAILED_UNSPECIFIED')))
      ) AS failure_reason_groups
    ) AS provider_failure_groups ON true
    left join lateral (
      with item_scope as (
        select
          pbi_corr.id as pay_batch_item_id,
          pbi_corr.item_type,
          round(coalesce(pbi_corr.amount_inc_vat, pbi_corr.amount_ex_vat, 0), 2)::numeric as amount_inc_vat,
          coalesce(pbi_corr.is_voided, false) as is_voided,
          pbc_corr.settlement_status,
          pbc_corr.settled_at_utc,
          pbt_corr.status as transfer_status,
          pbt_corr.completed_at_utc as transfer_completed_at_utc
        from public.pay_batch_items pbi_corr
        join public.pay_batch_candidates pbc_corr
          on pbc_corr.id = pbi_corr.pay_batch_candidate_id
        left join public.pay_bank_transfers pbt_corr
          on pbt_corr.id = pbi_corr.pay_bank_transfer_id
         and pbt_corr.pay_batch_id = pb0.id
        where pbc_corr.pay_batch_id = pb0.id
          and pbi_corr.item_type <> 'DEBT_CREATED'
      ),
      correction_items as (
        select
          ppci_corr.correction_item_kind,
          count(distinct ppci_corr.pay_batch_item_id)::integer as item_count,
          round(coalesce(sum(coalesce(ppci_corr.amount_inc_vat, ppci_corr.amount_ex_vat, ppci_corr.source_amount, 0)), 0), 2)::numeric as amount_inc_vat
        from public.pay_payment_correction_items ppci_corr
        where ppci_corr.pay_batch_id = pb0.id
          and ppci_corr.status = 'APPLIED'
        group by ppci_corr.correction_item_kind
      ),
      bank_events as (
        select
          count(*)::integer as event_count,
          count(*) filter (where upper(btrim(coalesce(pbte_corr.normalised_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED'))::integer as failed_returned_event_count,
          count(*) filter (where upper(btrim(coalesce(pbte_corr.normalised_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED'))::integer as failed_event_count,
          count(*) filter (where upper(btrim(coalesce(pbte_corr.normalised_state, ''))) in ('RETURNED','REVERTED'))::integer as returned_event_count,
          max(coalesce(pbte_corr.event_time_utc, pbte_corr.received_at_utc)) filter (where upper(btrim(coalesce(pbte_corr.normalised_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')) as latest_bank_failure_at_utc
        from public.pay_bank_transfer_events pbte_corr
        where pbte_corr.pay_batch_id = pb0.id
      ),
      transfer_evidence as (
        select
          count(*) filter (
            where upper(btrim(coalesce(pbt_evidence.status, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
               or (
                 nullif(btrim(coalesce(pbt_evidence.failed_reason, '')), '') is not null
                 and upper(btrim(coalesce(pbt_evidence.status, ''))) not in ('RETURNED','REVERTED')
               )
          )::integer as failed_transfer_count,
          count(*) filter (
            where upper(btrim(coalesce(pbt_evidence.status, ''))) in ('RETURNED','REVERTED')
          )::integer as returned_transfer_count,
          count(*) filter (
            where upper(btrim(coalesce(pbt_evidence.status, ''))) = 'COMPLETED'
               or pbt_evidence.completed_at_utc is not null
          )::integer as completed_transfer_count,
          count(*) filter (
            where nullif(btrim(coalesce(pbt_evidence.request_id, '')), '') is not null
               or nullif(btrim(coalesce(pbt_evidence.rail_tx_id, '')), '') is not null
               or nullif(btrim(coalesce(pbt_evidence.payment_reference, '')), '') is not null
               or upper(btrim(coalesce(pbt_evidence.status, ''))) in ('SUBMITTED','PROCESSING','PENDING','COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT','RETURNED','REVERTED')
          )::integer as submission_or_rail_evidence_count
        from public.pay_bank_transfers pbt_evidence
        where pbt_evidence.pay_batch_id = pb0.id
      ),
      request_summary as (
        select
          count(*) filter (where ppcr_corr.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED'))::integer as open_request_count,
          count(*) filter (where ppcr_corr.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED') and ppcr_corr.correction_kind in ('SETTLED_REVERSAL','MANUAL_EVIDENCE_SETTLED_RETURN'))::integer as open_settled_reversal_request_count,
          count(*) filter (where ppcr_corr.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED') and ppcr_corr.correction_kind in ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'))::integer as open_no_money_unwind_request_count,
          count(*) filter (where ppcr_corr.status in ('REQUESTED','AWAITING_AUTHORISATION'))::integer as correction_waiting_approval_count,
          count(*) filter (where ppcr_corr.status in ('AUTHORISED','EXPANDED','PROCESSING'))::integer as correction_processing_count,
          count(*) filter (where ppcr_corr.status in ('BLOCKED','APPLIED_WITH_BLOCKERS'))::integer as correction_blocked_count,
          count(*) filter (where ppcr_corr.status = 'FAILED')::integer as correction_failed_count,
          count(*) filter (where ppcr_corr.status in ('REQUESTED','AWAITING_AUTHORISATION') and ppcr_corr.correction_kind in ('SETTLED_REVERSAL','MANUAL_EVIDENCE_SETTLED_RETURN'))::integer as waiting_settled_reversal_request_count,
          max(ppcr_corr.updated_at_utc) as latest_request_at_utc,
          (
            select ppcr_latest.correction_kind
            from public.pay_payment_correction_requests ppcr_latest
            where ppcr_latest.pay_batch_id = pb0.id
            order by ppcr_latest.updated_at_utc desc nulls last, ppcr_latest.created_at_utc desc, ppcr_latest.id desc
            limit 1
          ) as latest_correction_kind,
          (
            select ppcr_latest.status
            from public.pay_payment_correction_requests ppcr_latest
            where ppcr_latest.pay_batch_id = pb0.id
            order by ppcr_latest.updated_at_utc desc nulls last, ppcr_latest.created_at_utc desc, ppcr_latest.id desc
            limit 1
          ) as latest_correction_request_status
        from public.pay_payment_correction_requests ppcr_corr
        where ppcr_corr.pay_batch_id = pb0.id
      ),
      work_item_summary as (
        select
          count(*) filter (where ppwi_corr.status = 'PENDING')::integer as correction_work_pending_count,
          count(*) filter (where ppwi_corr.status = 'PROCESSING')::integer as correction_work_processing_count,
          count(*) filter (where ppwi_corr.status = 'BLOCKED')::integer as correction_work_blocked_count,
          count(*) filter (where ppwi_corr.status = 'FAILED_RETRYABLE')::integer as correction_work_failed_retryable_count,
          count(*) filter (where ppwi_corr.status = 'FAILED_FINAL')::integer as correction_work_failed_final_count
        from public.pay_payment_correction_work_items ppwi_corr
        where ppwi_corr.pay_batch_id = pb0.id
      ),
      action_summary as (
        select
          max(ppca_corr.action_at_utc) as latest_correction_action_at_utc
        from public.pay_payment_correction_actions ppca_corr
        where ppca_corr.pay_batch_id = pb0.id
      ),
      item_totals as (
        select
          count(*) filter (where item_scope.is_voided = false)::integer as correctable_item_count,
          round(coalesce(sum(item_scope.amount_inc_vat) filter (
            where item_scope.is_voided = false
              and not exists (
                select 1
                from public.pay_payment_correction_items ppci_item_exclusion
                where ppci_item_exclusion.pay_batch_item_id = item_scope.pay_batch_item_id
                  and ppci_item_exclusion.status = 'APPLIED'
                  and ppci_item_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
              )
              and (
                upper(btrim(coalesce(item_scope.settlement_status, ''))) = 'SETTLED'
                or item_scope.settled_at_utc is not null
                or upper(btrim(coalesce(item_scope.transfer_status, ''))) = 'COMPLETED'
                or item_scope.transfer_completed_at_utc is not null
              )
          ), 0), 2)::numeric as remaining_paid_amount_inc_vat
        from item_scope
      )
      select
        case
          when coalesce((select correction_work_blocked_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_failed_retryable_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_failed_final_count from work_item_summary), 0) > 0
            or coalesce((select correction_blocked_count from request_summary), 0) > 0
            or coalesce((select correction_failed_count from request_summary), 0) > 0 then 'AMBIGUOUS_REVIEW_REQUIRED'
          when coalesce((select waiting_settled_reversal_request_count from request_summary), 0) > 0
            or (
              (
                coalesce((select returned_event_count from bank_events), 0) > 0
                or coalesce((select returned_transfer_count from transfer_evidence), 0) > 0
              )
              and coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0) = 0
              and coalesce((select correction_processing_count from request_summary), 0) = 0
            ) then 'TRUE_SETTLED_REVERSAL_REQUIRED'
          when coalesce((select correction_waiting_approval_count from request_summary), 0) > 0 then 'AWAITING_AUTHORISATION'
          when coalesce((select correction_processing_count from request_summary), 0) > 0
            or coalesce((select correction_work_pending_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_processing_count from work_item_summary), 0) > 0 then 'PROCESSING'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0) > 0 then 'SETTLED_REVERSAL_APPLIED'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) > 0
            and coalesce((select correctable_item_count from item_totals), 0) > 0
            and coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) >= coalesce((select correctable_item_count from item_totals), 0) then 'NO_MONEY_UNWOUND'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) > 0 then 'PARTIALLY_UNWOUND'
          when coalesce((select failed_event_count from bank_events), 0) > 0
            or coalesce((select failed_transfer_count from transfer_evidence), 0) > 0
            or coalesce((select open_no_money_unwind_request_count from request_summary), 0) > 0 then 'NO_MONEY_UNWIND'
          when coalesce((select open_request_count from request_summary), 0) > 0 then 'AMBIGUOUS_REVIEW_REQUIRED'
          when coalesce((select event_count from bank_events), 0) = 0
            and coalesce((select submission_or_rail_evidence_count from transfer_evidence), 0) = 0
            and nullif(btrim(coalesce(pb0.execution_commit_ref, '')), '') is null
            and pb0.execution_committed_at_utc is null
            and upper(btrim(coalesce(pb0.execution_commit_state, 'NOT_SUBMITTED'))) in ('', 'NOT_SUBMITTED', 'NONE') then 'PRE_BANK_CANCEL'
          when coalesce((select completed_transfer_count from transfer_evidence), 0) > 0
            or coalesce((select remaining_paid_amount_inc_vat from item_totals), 0) > 0 then 'SETTLED_NO_CORRECTION_REQUIRED'
          else 'NONE'
        end as movement_classification,
        case
          when (
              coalesce((select correction_processing_count from request_summary), 0) > 0
              or coalesce((select correction_work_pending_count from work_item_summary), 0) > 0
              or coalesce((select correction_work_processing_count from work_item_summary), 0) > 0
            )
            and (
              coalesce((select correction_work_blocked_count from work_item_summary), 0) > 0
              or coalesce((select correction_work_failed_retryable_count from work_item_summary), 0) > 0
              or coalesce((select correction_work_failed_final_count from work_item_summary), 0) > 0
              or coalesce((select correction_blocked_count from request_summary), 0) > 0
              or coalesce((select correction_failed_count from request_summary), 0) > 0
            ) then 'PARTLY_APPLIED_REVIEW_NEEDED'
          when coalesce((select correction_work_blocked_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_failed_retryable_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_failed_final_count from work_item_summary), 0) > 0
            or coalesce((select correction_blocked_count from request_summary), 0) > 0
            or coalesce((select correction_failed_count from request_summary), 0) > 0 then 'ACTION_REQUIRED'
          when coalesce((select correction_waiting_approval_count from request_summary), 0) > 0 then 'WAITING_FOR_APPROVAL'
          when coalesce((select correction_processing_count from request_summary), 0) > 0
            or coalesce((select correction_work_pending_count from work_item_summary), 0) > 0
            or coalesce((select correction_work_processing_count from work_item_summary), 0) > 0 then 'PROCESSING'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0) > 0
               and coalesce((select correctable_item_count from item_totals), 0) > 0
               and coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0) >= coalesce((select correctable_item_count from item_totals), 0) then 'REVERSED'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0) > 0 then 'PARTIALLY_REVERSED'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) > 0
               and coalesce((select correctable_item_count from item_totals), 0) > 0
               and coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) >= coalesce((select correctable_item_count from item_totals), 0) then 'NO_MONEY_UNWOUND'
          when coalesce((select sum(correction_items.item_count) from correction_items where correction_items.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL')), 0) > 0 then 'PARTIALLY_UNWOUND'
          when coalesce((select returned_event_count from bank_events), 0) > 0
            or coalesce((select returned_transfer_count from transfer_evidence), 0) > 0 then 'SETTLED_RETURNED'
          when coalesce((select failed_returned_event_count from bank_events), 0) > 0
            or coalesce((select failed_transfer_count from transfer_evidence), 0) > 0
            or coalesce((select returned_transfer_count from transfer_evidence), 0) > 0 then 'ACTION_REQUIRED'
          else 'NONE'
        end as correction_status,
        (
          coalesce((select correction_blocked_count from request_summary), 0)
          + coalesce((select correction_failed_count from request_summary), 0)
          + coalesce((select correction_work_blocked_count from work_item_summary), 0)
          + coalesce((select correction_work_failed_retryable_count from work_item_summary), 0)
          + coalesce((select correction_work_failed_final_count from work_item_summary), 0)
          + case
              when coalesce((select correction_processing_count from request_summary), 0) > 0
                or coalesce((select correction_waiting_approval_count from request_summary), 0) > 0 then 0
              else coalesce((select failed_returned_event_count from bank_events), 0)
                + coalesce((select failed_transfer_count from transfer_evidence), 0)
                + coalesce((select returned_transfer_count from transfer_evidence), 0)
            end
        )::integer as correction_required_count,
        coalesce((select failed_returned_event_count from bank_events), 0)::integer as failed_returned_event_count,
        coalesce((select sum(correction_items.amount_inc_vat) from correction_items where correction_items.correction_item_kind = 'NO_MONEY_UNWIND'), 0)::numeric as unwound_amount_inc_vat,
        coalesce((select sum(correction_items.amount_inc_vat) from correction_items where correction_items.correction_item_kind = 'SETTLED_REVERSAL'), 0)::numeric as reversed_amount_inc_vat,
        coalesce((select remaining_paid_amount_inc_vat from item_totals), 0)::numeric as remaining_paid_amount_inc_vat,
        (select latest_bank_failure_at_utc from bank_events) as latest_bank_failure_at_utc,
        (select latest_correction_request_status from request_summary) as latest_correction_request_status,
        (select latest_correction_kind from request_summary) as latest_correction_request_kind,
        coalesce((select correction_processing_count from request_summary), 0)::integer as correction_processing_count,
        coalesce((select correction_waiting_approval_count from request_summary), 0)::integer as correction_waiting_approval_count,
        coalesce((select correction_blocked_count from request_summary), 0)::integer as correction_blocked_count,
        coalesce((select correction_failed_count from request_summary), 0)::integer as correction_failed_count,
        coalesce((select correction_work_blocked_count from work_item_summary), 0)::integer as correction_work_blocked_count,
        coalesce((select correction_work_failed_retryable_count from work_item_summary), 0)::integer as correction_work_failed_retryable_count,
        coalesce((select correction_work_failed_final_count from work_item_summary), 0)::integer as correction_work_failed_final_count,
        coalesce((select correction_work_pending_count from work_item_summary), 0)::integer as correction_work_pending_count,
        coalesce((select correction_work_processing_count from work_item_summary), 0)::integer as correction_work_processing_count,
        (
          coalesce((select correction_blocked_count from request_summary), 0) > 0
          or coalesce((select correction_failed_count from request_summary), 0) > 0
          or coalesce((select correction_work_blocked_count from work_item_summary), 0) > 0
          or coalesce((select correction_work_failed_retryable_count from work_item_summary), 0) > 0
          or coalesce((select correction_work_failed_final_count from work_item_summary), 0) > 0
          or (
            coalesce((select correction_processing_count from request_summary), 0) = 0
            and coalesce((select correction_work_pending_count from work_item_summary), 0) = 0
            and coalesce((select correction_work_processing_count from work_item_summary), 0) = 0
            and coalesce((select correction_waiting_approval_count from request_summary), 0) = 0
            and (
              coalesce((select failed_returned_event_count from bank_events), 0) > 0
              or coalesce((select failed_transfer_count from transfer_evidence), 0) > 0
              or coalesce((select returned_transfer_count from transfer_evidence), 0) > 0
            )
          )
        )::boolean as correction_requires_user_action,
        case
          when (select latest_correction_action_at_utc from action_summary) is null
            and (select latest_request_at_utc from request_summary) is null then null::timestamptz
          else greatest(
            coalesce((select latest_correction_action_at_utc from action_summary), '-infinity'::timestamptz),
            coalesce((select latest_request_at_utc from request_summary), '-infinity'::timestamptz)
          )
        end as latest_correction_action_at_utc
    ) corr on true
    where v_status is null or upper(coalesce(pb0.status,'')) = v_status
    order by pb0.created_at_utc desc, pb0.id desc
    limit v_limit offset v_offset
  ) pb;

  return jsonb_build_object(
    'ok', true,
    'total_count', v_total,
    'limit', v_limit,
    'offset', v_offset,
    'rows', v_rows,
    'banking_alerts', v_nav_alerts,
    'banking_alert_summary', jsonb_build_object(
      'ok', true,
      'alerts', v_nav_alerts,
      'unacknowledged_count', v_banking_unacknowledged_alert_count,
      'highest_severity', v_banking_highest_alert_severity,
      'highest_label', v_banking_highest_alert_label,
      'alert_hash', NULL::text,
      'degraded', v_alert_metadata_degraded,
      'warning', v_alert_metadata_warning
    ),
    'banking_unacknowledged_alert_count', v_banking_unacknowledged_alert_count,
    'banking_highest_alert_label', v_banking_highest_alert_label,
    'banking_highest_alert_severity', v_banking_highest_alert_severity,
    'alert_metadata_degraded', v_alert_metadata_degraded,
    'alert_metadata_warning', v_alert_metadata_warning
  );
end;
$function$;




create or replace function public.pay_unpay_batch(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_reason text,
  p_force boolean
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_batch record;
  v_timesheet_id uuid;

  v_aff_timesheets uuid[] := array[]::uuid[];

  v_latest record;

  v_patch record;
  v_old_outstanding numeric;
  v_old_schedule jsonb;
  v_old_next_due date;

  v_component_restore record;
  v_component_before_json jsonb;
  v_component_after_json jsonb;

  v_reverted_adv int := 0;
  v_removed_hist int := 0;
  v_rebuilt_states int := 0;
  v_restored_components int := 0;
  v_released_reservations int := 0;
  v_changed_channel_audit record;
  v_changed_channel_audit_before_json jsonb := null;
  v_changed_channel_audit_after_json jsonb := null;
  v_changed_channel_unwound_ct int := 0;
  v_correction_flow_guard jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  if (
    upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
    or nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') is not null
    or v_batch.execution_committed_at_utc is not null
    or exists (
      select 1
      from public.pay_bank_transfers as pbt_guard
      where pbt_guard.pay_batch_id = p_pay_batch_id
        and (
          nullif(btrim(coalesce(pbt_guard.rail_tx_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.request_id, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.payment_reference, '')), '') is not null
          or nullif(btrim(coalesce(pbt_guard.rail_state, '')), '') is not null
          or coalesce(pbt_guard.rail_meta_json, '{}'::jsonb) <> '{}'::jsonb
          or pbt_guard.completed_at_utc is not null
          or upper(btrim(coalesce(pbt_guard.status, ''))) in ('COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED')
          or nullif(btrim(coalesce(pbt_guard.failed_reason, '')), '') is not null
          or upper(btrim(coalesce(pbt_guard.rail_state, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','RETURNED','REVERTED','COMPLETED','SETTLED','PAID','EXECUTED')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'completed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'failed', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'declined', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'rejected', 'false'))) in ('true','1','yes','y','on')
          or lower(btrim(coalesce(pbt_guard.rail_meta_json->>'returned', 'false'))) in ('true','1','yes','y','on')
        )
    )
    or exists (select 1 from public.pay_bank_transfer_events as pbte_guard where pbte_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.timesheet_pay_state_history as tpsh_guard where tpsh_guard.pay_batch_id = p_pay_batch_id)
    or exists (select 1 from public.pay_payment_correction_requests as ppcr_guard where ppcr_guard.pay_batch_id = p_pay_batch_id and ppcr_guard.status not in ('REJECTED','CANCELLED'))
    or exists (select 1 from public.pay_payment_correction_items as ppci_guard where ppci_guard.pay_batch_id = p_pay_batch_id)
  ) then
    v_correction_flow_guard := jsonb_build_object(
      'error', 'USE_PAYMENT_CORRECTION_FLOW',
      'code', 'USE_PAYMENT_CORRECTION_FLOW',
      'message', 'pay_unpay_batch is restricted to legacy/admin no-bank-evidence batches. Use the payment correction flow for submitted, failed, settled, returned, or corrected batches.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end
    );

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_UNPAY_BATCH_BLOCKED_USE_CORRECTION_FLOW',
        v_correction_flow_guard,
        'pay_batch',
        p_pay_batch_id::text,
        null::jsonb,
        null::text,
        null::text,
        null::text
      );
    exception when others then
      null;
    end;

    raise exception '%', v_correction_flow_guard::text;
  end if;

  if v_batch.status in
 ('SETTLED','PARTIAL') and p_force is distinct from true then
    raise exception 'UNPAY_REQUIRES_FORCE_FOR_SETTLED_BATCH';
  end if;

  -- Revert finance-case header patches first so header totals are restored
  for v_patch in
    select
      pap.advance_id,
      pap.old_outstanding_amount,
      pap.old_schedule_json,
      pap.old_next_due_week_start
    from public.pay_advance_patches pap
    where pap.pay_batch_id = p_pay_batch_id
  loop
    v_old_outstanding := v_patch.old_outstanding_amount;
    v_old_schedule := v_patch.old_schedule_json;
    v_old_next_due := v_patch.old_next_due_week_start;

    update public.pay_advances pa
    set
      outstanding_amount = v_old_outstanding,
      schedule_json = v_old_schedule,
      next_due_week_start = v_old_next_due,
      status = case
        when coalesce(v_old_outstanding, 0) <= 0 then 'PAID_OFF'::public.pay_advance_status_enum
        else 'ACTIVE'::public.pay_advance_status_enum
      end,
      updated_at = v_now
    where pa.id = v_patch.advance_id;

    v_reverted_adv := v_reverted_adv + 1;
  end loop;

  -- Restore component-level remainders from frozen snapshots on batch items first,
  -- then fall back to reservation snapshots only for components that had no batch item snapshot.
  for v_component_restore in
    with item_component_restore as (
      select
        pbi.finance_case_id,
        pbi.finance_component_id,
        round(
          sum(
            coalesce(
              pbi.frozen_source_amount,
              case
                when pbi.frozen_component_snapshot_json ? 'frozen_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'frozen_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'frozen_source_amount')::numeric
                else null::numeric
              end,
              case
                when pbi.frozen_component_snapshot_json ? 'reserved_source_amount'
                  and nullif(btrim(pbi.frozen_component_snapshot_json ->> 'reserved_source_amount'), '') is not null
                then (pbi.frozen_component_snapshot_json ->> 'reserved_source_amount')::numeric
                else null::numeric
              end,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.finance_component_id is not null
      group by
        pbi.finance_case_id,
        pbi.finance_component_id
    ),
    reservation_component_restore as (
      select
        par.finance_case_id,
        par.finance_component_id,
        round(
          sum(
            coalesce(
              par.reserved_source_amount,
              par.reserved_amount,
              0::numeric
            )
          ),
          2
        )::numeric(12,2) as restore_source_amount
      from public.pay_advance_reservations par
      where par.pay_batch_id = p_pay_batch_id
        and par.finance_component_id is not null
        and par.status in ('RESERVED','COMMITTED','SETTLED')
      group by
        par.finance_case_id,
        par.finance_component_id
    ),
    combined_restore as (
      select
        icr.finance_case_id,
        icr.finance_component_id,
        icr.restore_source_amount
      from item_component_restore icr

      union all

      select
        rcr.finance_case_id,
        rcr.finance_component_id,
        rcr.restore_source_amount
      from reservation_component_restore rcr
      where not exists (
        select 1
        from item_component_restore icr2
        where icr2.finance_case_id is not distinct from rcr.finance_case_id
          and icr2.finance_component_id = rcr.finance_component_id
      )
    )
    select
      cr.finance_case_id,
      cr.finance_component_id,
      cr.restore_source_amount,
      pfc.source_amount,
      pfc.remaining_source_amount,
      pfc.closed_at_utc,
      pfc.classification,
      pfc.source_pay_method,
      pfc.saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      pfc.stale_reason
    from combined_restore cr
    join public.pay_finance_case_components pfc
      on pfc.id = cr.finance_component_id
    where cr.restore_source_amount > 0
    order by
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc,
      pfc.id
  loop
    select jsonb_build_object(
      'finance_component_id', v_component_restore.finance_component_id::text,
      'classification', v_component_restore.classification::text,
      'source_pay_method', v_component_restore.source_pay_method,
      'saved_target_pay_method', v_component_restore.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_restore.saved_resolution_mode is null then null else v_component_restore.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_restore.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_restore.saved_resolution_result_json,
      'stale_reason', v_component_restore.stale_reason,
      'source_amount', round(coalesce(v_component_restore.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_restore.remaining_source_amount, 0), 2),
      'closed_at_utc', v_component_restore.closed_at_utc
    )
    into v_component_before_json;

    update public.pay_finance_case_components pfc
    set
      remaining_source_amount = least(
        round(coalesce(pfc.source_amount, 0), 2),
        round(coalesce(pfc.remaining_source_amount, 0), 2) + round(coalesce(v_component_restore.restore_source_amount, 0), 2)
      )::numeric(12,2),
      closed_at_utc = null,
      updated_at_utc = v_now
    where pfc.id = v_component_restore.finance_component_id
    returning jsonb_build_object(
      'finance_component_id', pfc.id::text,
      'classification', pfc.classification::text,
      'source_pay_method', pfc.source_pay_method,
      'saved_target_pay_method', pfc.saved_target_pay_method,
      'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
      'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
      'saved_resolution_result_json', pfc.saved_resolution_result_json,
      'stale_reason', pfc.stale_reason,
      'source_amount', round(coalesce(pfc.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
      'closed_at_utc', pfc.closed_at_utc
    )
    into v_component_after_json;

    insert into public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_component_restore.finance_case_id,
      v_component_restore.finance_component_id,
      'COMPONENT_RESTORED_ON_UNPAY',
      v_now,
      p_actor_user_id,
      p_pay_batch_id,
      null,
      v_component_before_json,
      v_component_after_json,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'Restored finance component remainder from frozen batch-item/reservation snapshot during unpay.'
    );

    v_restored_components := v_restored_components + 1;
  end loop;

  -- Release any reservations tied to the batch so finance cases remain open correctly.
  update public.pay_advance_reservations par
  set
    status = 'RELEASED',
    settled_at_utc = null,
    released_at_utc = coalesce(par.released_at_utc, v_now),
    released_reason = coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID')
  where par.pay_batch_id = p_pay_batch_id
    and par.status in ('RESERVED','COMMITTED','SETTLED');

  get diagnostics v_released_reservations = row_count;

  -- Revert LOANS payout status (if this batch paid out loans)
  if upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then
    with loan_ids as (
      select distinct
        replace(pbi.source_ref, 'advance:', '')::uuid as loan_id
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and pbi.item_type = 'LOAN_PAYOUT'
        and pbi.is_voided = false
        and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
    )
    update public.pay_advances pa
    set
      payout_status = 'PENDING'::public.pay_advance_payout_status_enum,
      payout_pay_batch_id = null,
      payout_transfer_id = null,
      updated_at = v_now
    from loan_ids li
    where pa.id = li.loan_id
      and pa.advance_kind = 'LOAN'::public.pay_advance_kind_enum
      and pa.payout_pay_batch_id = p_pay_batch_id;
  end if;

  -- Gather affected timesheets from history rows for this batch
  select coalesce(array_agg(distinct h.timesheet_id), array[]::uuid[])
  into v_aff_timesheets
  from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  -- Remove history rows for this batch
  delete from public.timesheet_pay_state_history h
  where h.pay_batch_id = p_pay_batch_id;

  get diagnostics v_removed_hist = row_count;

  -- Rebuild timesheet_pay_state for affected timesheets
  foreach v_timesheet_id in array v_aff_timesheets
  loop
    select
      h.timesheet_id,
      h.pay_batch_id,
      h.settled_at_utc,
      h.snapshot_json,
      h.signature
    into v_latest
    from public.timesheet_pay_state_history h
    where h.timesheet_id = v_timesheet_id
    order by h.settled_at_utc desc, h.id desc
    limit 1;

    if v_latest.timesheet_id is null then
      delete from public.timesheet_pay_state tps
      where tps.timesheet_id = v_timesheet_id;
    else
      insert into public.timesheet_pay_state(
        timesheet_id,
        last_settled_snapshot_json,
        last_settled_signature,
        last_settled_pay_batch_id,
        last_settled_at_utc
      )
      values (
        v_timesheet_id,
        v_latest.snapshot_json,
        v_latest.signature,
        v_latest.pay_batch_id,
        v_latest.settled_at_utc
      )
      on conflict (timesheet_id) do update
      set
        last_settled_snapshot_json = excluded.last_settled_snapshot_json,
        last_settled_signature = excluded.last_settled_signature,
        last_settled_pay_batch_id = excluded.last_settled_pay_batch_id,
        last_settled_at_utc = excluded.last_settled_at_utc;
    end if;

    v_rebuilt_states := v_rebuilt_states + 1;
  end loop;


  for v_changed_channel_audit in
    with settled_batch_item_portions as (
      select
        pbi.id as pay_batch_item_id,
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id as candidate_id,
        pbc.settled_at_utc as settled_at_utc,
        pbi.timesheet_id as timesheet_id,
        ts.booking_id as booking_id,
        pbi.pay_bank_transfer_id as pay_bank_transfer_id,
        pbi.item_type as item_type,
        pbi.segment_key as segment_key,
        pbi.source_ref as source_ref,
        pbi.description as description,
        upper(coalesce(nullif(btrim(coalesce(pbi.frozen_source_pay_method,'')), ''), '')) as source_pay_channel,
        upper(coalesce(nullif(btrim(coalesce(pbi.pay_channel,'')), ''), nullif(btrim(coalesce(pbi.frozen_target_pay_method,'')), ''), '')) as settled_pay_channel,
        case when pbi.frozen_component_key_type is null then null else pbi.frozen_component_key_type end as component_key_type,
        pbi.frozen_component_key_value as component_key_value,
        case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end as component_classification,
        case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end as resolution_mode,
        pbi.frozen_resolution_payload_json as resolution_payload_json,
        pbi.frozen_resolution_result_json as resolution_result_json,
        pbi.frozen_source_basis_json as frozen_source_basis_json,
        round(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0), 2) as item_source_amount_ex_vat,
        round(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0), 2) as item_settled_amount_ex_vat
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      left join public.timesheets ts
        on ts.timesheet_id = pbi.timesheet_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
        and pbi.item_type <> 'DEBT_CREATED'
        and pbi.timesheet_id is not null
        and pbc.settled_at_utc is not null
    ),
    portion_rows as (
      select
        sbip.pay_batch_item_id,
        sbip.pay_batch_candidate_id,
        sbip.candidate_id,
        sbip.settled_at_utc,
        sbip.timesheet_id,
        sbip.booking_id,
        sbip.pay_bank_transfer_id,
        sbip.source_pay_channel,
        sbip.settled_pay_channel,
        sbip.component_key_type,
        sbip.component_key_value,
        sbip.component_classification,
        sbip.resolution_mode,
        sbip.resolution_payload_json,
        sbip.resolution_result_json,
        sbip.segment_key,
        sbip.source_ref,
        sbip.description,
        pbib.id as pay_batch_item_breakdown_id,
        coalesce(
          nullif(btrim(coalesce(pbib.line_kind,'')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
            when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
            when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            else sbip.item_type
          end
        ) as line_kind,
        nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), '') as bucket_code,
        coalesce(
          nullif(btrim(coalesce(pbib.unit_name, '')), ''),
          nullif(btrim(coalesce(sbip.description, '')), ''),
          case
            when sbip.item_type = 'SEGMENT_DELTA' then 'Timesheet portion'
            when sbip.item_type = 'EXPENSE_DELTA' then 'Expense'
            when sbip.item_type = 'MILEAGE_DELTA' then 'Mileage'
            when sbip.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
            when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when sbip.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
            when sbip.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit payout'
            else 'Batch item'
          end
        ) as unit_name,
        case
          when pbib.units is not null then round(pbib.units, 4)
          when sbip.frozen_source_basis_json ? 'source_units'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)
          else null::numeric
        end as units,
        case
          when sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6)
          else null::numeric
        end as source_rate,
        case
          when pbib.rate is not null then round(pbib.rate, 6)
          else null::numeric
        end as settled_rate,
        case
          when pbib.units is not null
           and sbip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round(pbib.units * round((sbip.frozen_source_basis_json ->> 'source_rate')::numeric, 6), 2)
          else sbip.item_source_amount_ex_vat
        end as source_amount_ex_vat,
        round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2) as settled_amount_ex_vat,
        md5(concat_ws('|',
          sbip.pay_batch_item_id::text,
          coalesce(
            nullif(btrim(coalesce(pbib.line_kind,'')), ''),
            case
              when sbip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
              when sbip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
              when sbip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
              when sbip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
              when sbip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
              when sbip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
              when sbip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
              when sbip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
              when sbip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
              else sbip.item_type
            end
          ),
          coalesce(nullif(btrim(coalesce(pbib.bucket_code, sbip.frozen_source_basis_json ->> 'bucket_code', '')), ''), ''),
          coalesce(
            case
              when pbib.units is not null then round(pbib.units, 4)::text
              when sbip.frozen_source_basis_json ? 'source_units'
               and nullif(btrim(coalesce(sbip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
                then round((sbip.frozen_source_basis_json ->> 'source_units')::numeric, 4)::text
              else null::text
            end,
            ''
          ),
          coalesce(case when pbib.rate is not null then round(pbib.rate, 6)::text else null::text end, ''),
          round(coalesce(pbib.amount_ex_vat, sbip.item_settled_amount_ex_vat), 2)::text
        )) as portion_identity_key
      from settled_batch_item_portions sbip
      left join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = sbip.pay_batch_item_id
    )
    select
      pr.pay_batch_item_id,
      pr.pay_batch_item_breakdown_id,
      pr.pay_batch_candidate_id,
      pr.candidate_id,
      pr.settled_at_utc,
      pr.timesheet_id,
      pr.booking_id,
      pr.pay_bank_transfer_id,
      pr.source_pay_channel,
      pr.settled_pay_channel,
      pr.component_key_type,
      pr.component_key_value,
      pr.component_classification,
      pr.resolution_mode,
      pr.resolution_payload_json,
      pr.resolution_result_json,
      pr.segment_key,
      pr.source_ref,
      pr.description,
      pr.line_kind,
      pr.bucket_code,
      pr.unit_name,
      pr.units,
      pr.source_rate,
      pr.settled_rate,
      pr.source_amount_ex_vat,
      pr.settled_amount_ex_vat,
      pr.portion_identity_key
    from portion_rows pr
    where pr.source_pay_channel <> ''
      and pr.settled_pay_channel <> ''
      and pr.source_pay_channel <> pr.settled_pay_channel
    order by
      pr.timesheet_id,
      pr.pay_batch_item_id,
      pr.line_kind,
      pr.bucket_code nulls first,
      pr.unit_name,
      pr.settled_amount_ex_vat desc
  loop
    v_changed_channel_audit_before_json := jsonb_build_object(
      'event_kind', 'TIMESHEET_CHANNEL_CHANGE_PORTION',
      'audit_effective_state', 'SETTLED_ACTIVE',
      'channel_changed', true,
      'timesheet_id', v_changed_channel_audit.timesheet_id::text,
      'booking_id', case when v_changed_channel_audit.booking_id is null then null else v_changed_channel_audit.booking_id::text end,
      'candidate_id', case when v_changed_channel_audit.candidate_id is null then null else v_changed_channel_audit.candidate_id::text end,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_candidate_id', case when v_changed_channel_audit.pay_batch_candidate_id is null then null else v_changed_channel_audit.pay_batch_candidate_id::text end,
      'pay_batch_item_id', case when v_changed_channel_audit.pay_batch_item_id is null then null else v_changed_channel_audit.pay_batch_item_id::text end,
      'pay_batch_item_breakdown_id', case when v_changed_channel_audit.pay_batch_item_breakdown_id is null then null else v_changed_channel_audit.pay_batch_item_breakdown_id::text end,
      'portion_identity_key', v_changed_channel_audit.portion_identity_key,
      'source_pay_channel', v_changed_channel_audit.source_pay_channel,
      'settled_pay_channel', v_changed_channel_audit.settled_pay_channel,
      'component_key_type', v_changed_channel_audit.component_key_type,
      'component_key_value', v_changed_channel_audit.component_key_value,
      'component_classification', v_changed_channel_audit.component_classification,
      'line_kind', v_changed_channel_audit.line_kind,
      'bucket_code', v_changed_channel_audit.bucket_code,
      'unit_name', v_changed_channel_audit.unit_name,
      'units', case when v_changed_channel_audit.units is null then null else round(v_changed_channel_audit.units, 4) end,
      'source_rate', case when v_changed_channel_audit.source_rate is null then null else round(v_changed_channel_audit.source_rate, 6) end,
      'settled_rate', case when v_changed_channel_audit.settled_rate is null then null else round(v_changed_channel_audit.settled_rate, 6) end,
      'source_amount_ex_vat', round(coalesce(v_changed_channel_audit.source_amount_ex_vat, 0), 2),
      'settled_amount_ex_vat', round(coalesce(v_changed_channel_audit.settled_amount_ex_vat, 0), 2),
      'resolution_mode', v_changed_channel_audit.resolution_mode,
      'resolution_selection_kind', case
        when v_changed_channel_audit.resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED'
        when v_changed_channel_audit.resolution_mode in ('MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') then 'MANUAL'
        else null
      end,
      'pay_bank_transfer_id', case when v_changed_channel_audit.pay_bank_transfer_id is null then null else v_changed_channel_audit.pay_bank_transfer_id::text end,
      'segment_key', v_changed_channel_audit.segment_key,
      'source_ref', v_changed_channel_audit.source_ref,
      'description', v_changed_channel_audit.description,
      'settled_at_utc', v_changed_channel_audit.settled_at_utc
    );

    v_changed_channel_audit_after_json := v_changed_channel_audit_before_json || jsonb_build_object(
      'audit_effective_state', 'UNWOUND',
      'unwound_at_utc', v_now,
      'unwind_reason', coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
      'reverses_action', 'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED'
    );

    begin
      perform public._audit_insert(
        'timesheets',
        v_changed_channel_audit.timesheet_id::text,
        'TIMESHEET_CHANNEL_CHANGE_PORTION_UNWOUND',
        v_changed_channel_audit_before_json,
        v_changed_channel_audit_after_json,
        coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'UNPAID'),
        p_actor_user_id
      );
      v_changed_channel_unwound_ct := v_changed_channel_unwound_ct + 1;
    exception when others then
      null;
    end;
  end loop;

  -- Mark candidate rows as UNPAID
  update public.pay_batch_candidates pbc
  set
    settlement_status = 'UNPAID',
    settled_at_utc = null,
    settled_via = null,
    settled_note = coalesce(nullif(btrim(coalesce(p_reason,'')),''), 'UNPAID'),
    paye_state = case when pbc.paye_state is null then null else 'READY' end
  where pbc.pay_batch_id = p_pay_batch_id;

  -- Mark batch as UNPAID (preserve audit; do not delete)
  update public.pay_batches pb
  set status = 'UNPAID'
  where pb.id = p_pay_batch_id;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'action', 'UNPAID',
    'reverted_advances', v_reverted_adv,
    'restored_components', v_restored_components,
    'released_reservations', v_released_reservations,
    'deleted_history_rows', v_removed_hist,
    'rebuilt_timesheet_states', v_rebuilt_states,
    'timesheet_channel_change_audit', jsonb_build_object(
      'unwound_event_count', v_changed_channel_unwound_ct
    )
  );
end;
$$;



DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean, uuid, jsonb, boolean, boolean);

DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_execute_bank(uuid, text, uuid, boolean, uuid, jsonb, boolean, boolean);



CREATE OR REPLACE FUNCTION public.pay_execute_bank(
  p_pay_batch_id uuid,
  p_pay_channel_scope text,
  p_actor_user_id uuid,
  p_retry_blocked_funds boolean DEFAULT false,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_transfer_scope_ids jsonb DEFAULT NULL::jsonb,
  p_operation_mode boolean DEFAULT false,
  p_allow_legacy_unchunked boolean DEFAULT false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(coalesce(p_pay_channel_scope,''));
  v_batch record;

  v_bulk_ref_num int;
  v_bulk_ref_date date;
  v_bulk_reference text;

  v_provider text;
  v_env text;

  v_tax_year_start date;
  v_tax_week int;

  v_pay_week_start date;
  v_pay_week_end date;

  v_pending_count int := 0;
  v_blocked_count int := 0;

  v_auto_execute boolean := false;

  v_transfers jsonb := '[]'::jsonb;
  v_provider_submission_event_payloads jsonb := '[]'::jsonb;
  v_blocked_reasons jsonb := '[]'::jsonb;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_batch_kind_fixed text := null;
  v_is_loans boolean := false;

  v_do_paye boolean := false;
  v_do_umbrella boolean := false;
  v_do_loans boolean := false;

  v_invalid_loans_items int := 0;

  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_detected_submitted_transfer_count int := 0;
  v_detected_committed_transfer_count int := 0;
  v_detected_execution_commit_ref text := null;
  v_detected_execution_committed_at_utc timestamptz := null;

  v_retry_blocked_funds boolean := false;
  v_blocked_funds_transfer_event_count integer := 0;
  v_blocked_funds_submission_evidence_count integer := 0;
  v_blocked_funds_submission_evidence_json jsonb := '{}'::jsonb;
  v_blocked_funds_active_item_count integer := 0;
  v_blocked_funds_sufficient_text text := null;

  v_operation_mode boolean := false;
  v_operation_prepare_result jsonb := '{}'::jsonb;
  v_legacy_safe_transfer_item_threshold integer := 250;
  v_legacy_transfer_item_count integer := 0;
  v_stored_freshness_status text := null;
  v_stored_freshness_result_hash text := null;
  v_stored_freshness_scope_hash text := null;
  v_operation_expected_freshness_hash text := null;
  v_operation_expected_freshness_scope_hash text := null;
  v_operation_scope_count integer := 0;
  v_provider_submit_preflight_result jsonb := '{}'::jsonb;
  v_provider_submit_preflight_ok boolean := true;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE','UMBRELLA','ALL','LOANS') then
    raise exception 'Invalid pay_channel_scope (PAYE|UMBRELLA|ALL|LOANS)';
  end if;

  v_retry_blocked_funds := coalesce(p_retry_blocked_funds, false);
  v_operation_mode := (coalesce(p_operation_mode, false) = true OR p_operation_id IS NOT NULL OR p_transfer_scope_ids IS NOT NULL);

  -- Lock the batch row to prevent concurrent execution / bulk ref allocation races
  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.banking_system_snapshot,
    pb.external_paye_system_snapshot,
    pb.bulk_ref_num,
    pb.bulk_ref_date,
    pb.bulk_reference,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.last_funds_check_at_utc,
    pb.last_funds_check_json,
    pb.funding_account_ref
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_batch not found';
  end if;

  v_batch_kind_fixed := upper(btrim(coalesce(v_batch.batch_kind_fixed,'')));
  v_is_loans := (v_batch_kind_fixed = 'LOANS');

  v_do_loans := v_is_loans;

  if v_do_loans = true then
    v_do_paye := false;
    v_do_umbrella := false;
  else
    v_do_paye := (v_scope in ('PAYE','ALL'));
    v_do_umbrella := (v_scope in ('UMBRELLA','ALL'));
  end if;

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_execution_commit_state = 'NOT_SUBMITTED'
     and v_operation_mode is not true
     and not (
       v_retry_blocked_funds is true
       and upper(btrim(coalesce(v_batch.status, ''))) = 'BLOCKED_FUNDS'
     ) then
    select
      count(*) filter (
        where upper(coalesce(pbt_exec.status,'')) = 'COMPLETED'
           or upper(coalesce(pbt_exec.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
           or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
           or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
           or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
      )::int,
      count(*) filter (
        where not (
          upper(coalesce(pbt_exec.status,'')) = 'COMPLETED'
          or upper(coalesce(pbt_exec.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
        )
        and (
          nullif(btrim(coalesce(pbt_exec.rail_tx_id,'')), '') is not null
          or upper(coalesce(pbt_exec.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'submitted','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'queued','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'accepted','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'sent','false'))) in ('true', '1', 'yes', 'y', 'on')
          or lower(btrim(coalesce(pbt_exec.rail_meta_json->>'processing','false'))) in ('true', '1', 'yes', 'y', 'on')
          or coalesce(
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec.rail_meta_json->>'id','')), '')
          ) is not null
        )
      )::int,
      (
        select coalesce(
          nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
        )
        from public.pay_bank_transfers pbt_exec_ref
        where pbt_exec_ref.pay_batch_id = p_pay_batch_id
          and (
            (v_do_paye = true and pbt_exec_ref.pay_channel = 'PAYE')
            or (v_do_umbrella = true and pbt_exec_ref.pay_channel = 'UMBRELLA')
            or (v_do_loans = true and pbt_exec_ref.pay_channel = 'PAYE')
          )
          and upper(coalesce(pbt_exec_ref.status,'')) <> 'BLOCKED'
          and (
            nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), '') is not null
            or upper(coalesce(pbt_exec_ref.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION','COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submitted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'queued','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'accepted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'sent','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'processing','false'))) in ('true', '1', 'yes', 'y', 'on')
          or coalesce(
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
          ) is not null
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
        order by
          case when nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), '') is not null then 0 else 1 end,
          case when coalesce(
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
          ) is not null then 0 else 1 end,
          pbt_exec_ref.completed_at_utc desc nulls last,
          pbt_exec_ref.id desc
        limit 1
      ),
      (
        select pbt_exec_ts.completed_at_utc
        from public.pay_bank_transfers pbt_exec_ts
        where pbt_exec_ts.pay_batch_id = p_pay_batch_id
          and (
            (v_do_paye = true and pbt_exec_ts.pay_channel = 'PAYE')
            or (v_do_umbrella = true and pbt_exec_ts.pay_channel = 'UMBRELLA')
            or (v_do_loans = true and pbt_exec_ts.pay_channel = 'PAYE')
          )
          and (
            upper(coalesce(pbt_exec_ts.status,'')) = 'COMPLETED'
            or upper(coalesce(pbt_exec_ts.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
        order by pbt_exec_ts.completed_at_utc desc nulls last, pbt_exec_ts.id desc
        limit 1
      )
    into
      v_detected_committed_transfer_count,
      v_detected_submitted_transfer_count,
      v_detected_execution_commit_ref,
      v_detected_execution_committed_at_utc
    from public.pay_bank_transfers pbt_exec
    where pbt_exec.pay_batch_id = p_pay_batch_id
      and (
        (v_do_paye = true and pbt_exec.pay_channel = 'PAYE')
        or (v_do_umbrella = true and pbt_exec.pay_channel = 'UMBRELLA')
        or (v_do_loans = true and pbt_exec.pay_channel = 'PAYE')
      );

    if coalesce(v_detected_committed_transfer_count, 0) > 0 then
      v_execution_commit_state := 'COMMITTED';
      v_execution_commit_ref := coalesce(v_execution_commit_ref, v_detected_execution_commit_ref);
      v_execution_committed_at_utc := coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc, now());
    elsif coalesce(v_detected_submitted_transfer_count, 0) > 0 then
      v_execution_commit_state := 'SUBMITTED_NOT_COMMITTED';
      v_execution_commit_ref := coalesce(v_execution_commit_ref, v_detected_execution_commit_ref);
    end if;

    if v_execution_commit_state <> 'NOT_SUBMITTED' then
      update public.pay_batches pb_exec
      set
        execution_commit_state = v_execution_commit_state,
        execution_commit_ref = v_execution_commit_ref,
        execution_committed_at_utc = case
          when v_execution_commit_state = 'COMMITTED' then v_execution_committed_at_utc
          else null
        end
      where pb_exec.id = p_pay_batch_id;
    end if;
  end if;

  if v_execution_commit_state = 'NOT_SUBMITTED'
     and (
       nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') is not null
       or v_batch.execution_committed_at_utc is not null
     ) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_execute_bank: batch has execution commit reference/timestamp despite NOT_SUBMITTED state',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), ''),
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end
    )::text;
  end if;

  if v_execution_commit_state <> 'NOT_SUBMITTED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_execute_bank: batch has already crossed the execution submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  if upper(btrim(coalesce(v_batch.status, ''))) = 'BLOCKED_FUNDS' and v_retry_blocked_funds is not true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'BLOCKED_FUNDS_RETRY_REQUIRED',
      'message', 'pay_execute_bank: BLOCKED_FUNDS batches cannot use generic execute; use the dedicated blocked-funds retry path',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  if v_retry_blocked_funds is true and upper(btrim(coalesce(v_batch.status, ''))) <> 'BLOCKED_FUNDS' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'BLOCKED_FUNDS_RETRY_STATUS_MISMATCH',
      'message', 'pay_execute_bank: blocked-funds retry can only be used when the batch status is BLOCKED_FUNDS',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  IF v_operation_mode = true THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'OPERATION_ID_REQUIRED',
        'message', 'pay_execute_bank operation mode requires p_operation_id',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    END IF;

    IF p_transfer_scope_ids IS NULL OR jsonb_typeof(p_transfer_scope_ids) <> 'array' OR jsonb_array_length(p_transfer_scope_ids) = 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'TRANSFER_SCOPE_IDS_REQUIRED',
        'message', 'pay_execute_bank operation mode requires a non-empty p_transfer_scope_ids JSON array',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    SELECT nullif(btrim(coalesce(operation_row.progress_json->>'freshness_result_hash', '')), ''),
           nullif(btrim(coalesce(operation_row.result_json #>> '{freshness,freshness_result_hash}', '')), ''),
           nullif(btrim(coalesce(operation_row.progress_json->>'freshness_scope_hash', '')), ''),
           nullif(btrim(coalesce(operation_row.result_json #>> '{freshness,freshness_scope_hash}', '')), '')
    INTO v_operation_expected_freshness_hash,
         v_stored_freshness_result_hash,
         v_operation_expected_freshness_scope_hash,
         v_stored_freshness_scope_hash
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.pay_batch_id = p_pay_batch_id
      AND operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      AND (operation_row.actor_user_id IS NULL OR operation_row.actor_user_id = p_actor_user_id)
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_execute_bank operation mode requires a matching payment execution operation for this batch and actor',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    v_operation_expected_freshness_hash := nullif(btrim(coalesce(v_operation_expected_freshness_hash, v_stored_freshness_result_hash, '')), '');
    v_operation_expected_freshness_scope_hash := nullif(btrim(coalesce(v_operation_expected_freshness_scope_hash, v_stored_freshness_scope_hash, '')), '');

    SELECT upper(btrim(coalesce(batch_fresh.freshness_validation_status, ''))),
           nullif(btrim(coalesce(batch_fresh.freshness_result_hash, '')), ''),
           nullif(btrim(coalesce(batch_fresh.freshness_scope_hash, '')), '')
    INTO v_stored_freshness_status,
         v_stored_freshness_result_hash,
         v_stored_freshness_scope_hash
    FROM public.pay_batches AS batch_fresh
    WHERE batch_fresh.id = p_pay_batch_id;

    IF coalesce(v_stored_freshness_status, '') <> 'PASSED' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'FRESHNESS_NOT_PASSED',
        'message', 'pay_execute_bank operation mode requires completed passing chunked freshness before transfer preparation',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_result_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    END IF;

    IF v_operation_expected_freshness_hash IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'pay_execute_bank operation mode requires the operation to carry the completed freshness result hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_result_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    END IF;

    IF v_stored_freshness_result_hash IS DISTINCT FROM v_operation_expected_freshness_hash THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'pay_execute_bank operation freshness hash does not match stored batch freshness hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'expected_freshness_result_hash', v_operation_expected_freshness_hash,
        'actual_freshness_result_hash', v_stored_freshness_result_hash
      )::text;
    END IF;

    IF v_operation_expected_freshness_scope_hash IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'OPERATION_FRESHNESS_SCOPE_HASH_MISSING',
        'message', 'pay_execute_bank operation mode requires the operation to carry the completed freshness scope hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_result_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    END IF;

    IF v_stored_freshness_scope_hash IS DISTINCT FROM v_operation_expected_freshness_scope_hash THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'pay_execute_bank operation freshness scope hash does not match stored batch freshness scope hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'expected_freshness_scope_hash', v_operation_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    END IF;

    SELECT count(*)::integer
    INTO v_operation_scope_count
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope_check
    WHERE transfer_scope_check.operation_id = p_operation_id
      AND transfer_scope_check.pay_batch_id = p_pay_batch_id;

    IF coalesce(v_operation_scope_count, 0) <= 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'TRANSFER_SCOPE_NOT_SEEDED',
        'message', 'pay_execute_bank operation mode requires transfer scope to be seeded before chunk preparation',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    v_operation_prepare_result := public.pay_execute_bank_transfer_chunk_prepare(
      p_operation_id => p_operation_id,
      p_pay_batch_id => p_pay_batch_id,
      p_transfer_scope_ids => p_transfer_scope_ids,
      p_actor_user_id => p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'status', (SELECT pb_status.status FROM public.pay_batches AS pb_status WHERE pb_status.id = p_pay_batch_id),
      'retry_blocked_funds', v_retry_blocked_funds,
      'execution_commit_state', (SELECT pb_state.execution_commit_state FROM public.pay_batches AS pb_state WHERE pb_state.id = p_pay_batch_id),
      'execution_commit_ref', (SELECT pb_state.execution_commit_ref FROM public.pay_batches AS pb_state WHERE pb_state.id = p_pay_batch_id),
      'execution_committed_at_utc', (SELECT CASE WHEN pb_state.execution_committed_at_utc IS NULL THEN NULL ELSE pb_state.execution_committed_at_utc::text END FROM public.pay_batches AS pb_state WHERE pb_state.id = p_pay_batch_id),
      'freshness_result_hash', v_stored_freshness_result_hash,
      'freshness_scope_hash', v_stored_freshness_scope_hash,
      'prepared_count', COALESCE((v_operation_prepare_result->>'prepared_count')::integer, 0),
      'reused_count', COALESCE((v_operation_prepare_result->>'reused_count')::integer, 0),
      'skipped_count', COALESCE((v_operation_prepare_result->>'skipped_count')::integer, 0),
      'failed_count', COALESCE((v_operation_prepare_result->>'failed_count')::integer, 0),
      'remaining_count', COALESCE((v_operation_prepare_result->>'remaining_count')::integer, 0),
      'provider_submission_events_insertable', false,
      'provider_submission_event_payloads', '[]'::jsonb,
      'transfers', '[]'::jsonb,
      'chunk_result', COALESCE(v_operation_prepare_result, '{}'::jsonb)
    );
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) IS NOT TRUE THEN
    SELECT COUNT(*)::integer
    INTO v_legacy_transfer_item_count
    FROM public.pay_batch_candidates AS legacy_candidate
    JOIN public.pay_batch_items AS legacy_item
      ON legacy_item.pay_batch_candidate_id = legacy_candidate.id
    WHERE legacy_candidate.pay_batch_id = p_pay_batch_id
      AND COALESCE(legacy_item.is_voided, false) = false
      AND legacy_item.item_type <> 'DEBT_CREATED'
      AND (
        (v_do_paye = true AND legacy_item.pay_channel = 'PAYE')
        OR (v_do_umbrella = true AND legacy_item.pay_channel = 'UMBRELLA')
        OR (v_do_loans = true AND legacy_item.item_type = 'LOAN_PAYOUT')
      );

    IF COALESCE(v_legacy_transfer_item_count, 0) > v_legacy_safe_transfer_item_threshold THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'PAY_EXECUTE_BANK_LEGACY_UNCHUNKED_TOO_LARGE',
        'message', 'This payment batch is too large for the legacy all-at-once bank transfer materialisation path. Use the scalable Banking Pay execution operation flow.',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'active_item_count', v_legacy_transfer_item_count,
        'safe_legacy_threshold', v_legacy_safe_transfer_item_threshold
      )::text;
    END IF;
  END IF;

  v_fresh := public.pay_batch_validate_freshness(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id,
    p_allow_large_full_scan => false
  );
  v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
  v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

  if v_is_stale = true then
    select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
    from (
      select elem
      from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
      limit 50
    ) x;

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_EXECUTE_BANK:STALE',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff_sample', v_diff_sample
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', CASE WHEN coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) THEN 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' ELSE 'BATCH_STALE' END,
      'message', CASE WHEN coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) THEN 'pay_execute_bank: chunked freshness validation is required before proceeding' ELSE 'pay_execute_bank: batch is stale; regenerate draft before proceeding' END,
      'pay_batch_id', p_pay_batch_id::text,
      'stale_reasons', v_stale_reasons,
      'diff', v_diff_sample
    )::text;
  end if;

  if upper(btrim(coalesce(v_batch.status, ''))) = 'BLOCKED_FUNDS' then
    if v_retry_blocked_funds is not true then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_REQUIRED',
        'message', 'pay_execute_bank: BLOCKED_FUNDS batches require the dedicated blocked-funds retry path',
        'pay_batch_id', p_pay_batch_id::text,
        'status', v_batch.status
      )::text;
    end if;

    if v_execution_commit_state <> 'NOT_SUBMITTED'
       or nullif(btrim(coalesce(v_execution_commit_ref, '')), '') is not null
       or v_execution_committed_at_utc is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_EXECUTION_STATE_CONFLICT',
        'message', 'pay_execute_bank: blocked-funds retry is only allowed before any bank submission boundary has been crossed',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref', v_execution_commit_ref,
        'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
      )::text;
    end if;

    v_blocked_funds_submission_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id, true);

    SELECT COUNT(*)::integer
    INTO v_blocked_funds_transfer_event_count
    FROM public.pay_bank_transfer_events AS blocked_funds_event_rows
    WHERE blocked_funds_event_rows.pay_batch_id = p_pay_batch_id;

    IF COALESCE(v_blocked_funds_transfer_event_count, 0) > 0 THEN
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_TRANSFER_EVENTS_EXIST',
        'message', 'pay_execute_bank: blocked-funds retry is unsafe because bank/provider transfer events already exist for this batch',
        'pay_batch_id', p_pay_batch_id::text,
        'event_count', v_blocked_funds_transfer_event_count,
        'submission_evidence', v_blocked_funds_submission_evidence_json
      )::text;
    END IF;

    v_blocked_funds_submission_evidence_count := CASE
      WHEN COALESCE((v_blocked_funds_submission_evidence_json ->> 'has_external_provider_submission')::boolean, false) = true
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'has_pending_provider_outcome')::boolean, false) = true
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'has_unknown_provider_outcome')::boolean, false) = true
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'has_terminal_no_money')::boolean, false) = true
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'has_final_paid_or_settled')::boolean, false) = true
        OR COALESCE(NULLIF(v_blocked_funds_submission_evidence_json ->> 'provider_attempt_or_evidence_count', '')::integer, 0) > 0
        OR COALESCE(NULLIF(v_blocked_funds_submission_evidence_json ->> 'provider_or_ambiguous_evidence_count', '')::integer, 0) > 0
        OR COALESCE(NULLIF(v_blocked_funds_submission_evidence_json ->> 'attempted_but_unproven_count', '')::integer, 0) > 0
        OR COALESCE(NULLIF(v_blocked_funds_submission_evidence_json ->> 'provider_attempt_without_external_id_count', '')::integer, 0) > 0
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'requires_provider_poll')::boolean, false) = true
        OR COALESCE((v_blocked_funds_submission_evidence_json ->> 'requires_review')::boolean, false) = true
      THEN 1
      ELSE 0
    END;

    IF COALESCE(v_blocked_funds_submission_evidence_count, 0) > 0 THEN
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_SUBMISSION_EVIDENCE_EXISTS',
        'message', 'pay_execute_bank: blocked-funds retry is unsafe because provider submission, settlement, terminal outcome, unknown outcome, provider-attempt, or bank evidence already exists',
        'pay_batch_id', p_pay_batch_id::text,
        'submission_evidence_count', v_blocked_funds_submission_evidence_count,
        'submission_evidence', v_blocked_funds_submission_evidence_json
      )::text;
    END IF;

    select count(*)::integer
      into v_blocked_funds_active_item_count
    from public.pay_batch_candidates as pbc_active_guard
    join public.pay_batch_items as pbi_active_guard
      on pbi_active_guard.pay_batch_candidate_id = pbc_active_guard.id
    where pbc_active_guard.pay_batch_id = p_pay_batch_id
      and coalesce(pbi_active_guard.is_voided, false) = false
      and (
        (v_do_paye = true and pbi_active_guard.pay_channel = 'PAYE')
        or (v_do_umbrella = true and pbi_active_guard.pay_channel = 'UMBRELLA')
        or (v_do_loans = true and pbi_active_guard.pay_channel = 'PAYE')
      );

    if coalesce(v_blocked_funds_active_item_count, 0) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_NO_ACTIVE_ITEMS',
        'message', 'pay_execute_bank: blocked-funds retry requires active frozen batch items for the requested scope',
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope
      )::text;
    end if;

    v_blocked_funds_sufficient_text := lower(btrim(coalesce(
      v_batch.last_funds_check_json #>> '{sufficient}',
      v_batch.last_funds_check_json #>> '{is_sufficient}',
      ''
    )));

    if v_blocked_funds_sufficient_text not in ('false', '0', 'no', 'n', 'off') then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_BANK',
        'code', 'BLOCKED_FUNDS_RETRY_REQUIRES_INSUFFICIENT_FUNDS_CHECK',
        'message', 'pay_execute_bank: blocked-funds retry requires the latest stored funds check to explicitly show insufficient funds',
        'pay_batch_id', p_pay_batch_id::text,
        'last_funds_check_at_utc', case when v_batch.last_funds_check_at_utc is null then null else v_batch.last_funds_check_at_utc::text end,
        'sufficient', nullif(v_blocked_funds_sufficient_text, '')
      )::text;
    end if;
  elsif v_retry_blocked_funds is true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'BLOCKED_FUNDS_RETRY_STATUS_MISMATCH',
      'message', 'pay_execute_bank: blocked-funds retry can only be used when the batch status is BLOCKED_FUNDS',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  elsif v_batch.status not in ('DRAFT','READY','PARTIAL','WAITING_BANK_CONFIRM','DRAFT_CREATED') then
    raise exception 'pay_batch status not valid for execute (current=%)', v_batch.status;
  end if;

  if v_batch.pay_date is null then
    raise exception 'pay_batch pay_date is required';
  end if;

  v_provider := upper(btrim(coalesce(v_batch.rail_provider_snapshot, '')));
  if v_provider = 'REV' then
    v_provider := 'REVOLUT';
  end if;

  if v_provider = '' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'MISSING_RAIL_PROVIDER',
      'message', 'pay_execute_bank: rail_provider_snapshot is required and must be explicit; blank provider is not treated as CSV',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  if v_provider not in ('REVOLUT','CSV') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_BANK',
      'code', 'UNKNOWN_RAIL_PROVIDER',
      'message', 'pay_execute_bank: unsupported rail_provider_snapshot',
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  v_env := upper(btrim(coalesce(v_batch.rail_env_snapshot, 'PROD')));
  if v_env = '' then
    v_env := 'PROD';
  end if;

  -- Allocate bulk reference ONCE per batch (digits-only canonical)
  if v_batch.bulk_reference is null then
    v_bulk_ref_num := v_batch.bulk_ref_num;
    if v_bulk_ref_num is null then
      v_bulk_ref_num := nextval('public.pay_bulk_ref_seq')::int;
    end if;

    v_bulk_ref_date := coalesce(v_batch.bulk_ref_date, v_batch.pay_date);
    if v_bulk_ref_date is null then
      raise exception 'pay_batch pay_date is required to allocate bulk_reference';
    end if;

    v_bulk_reference := to_char(v_bulk_ref_date, 'DDMMYYYY') || lpad(v_bulk_ref_num::text, 7, '0');

    update public.pay_batches pb2
    set bulk_ref_num = v_bulk_ref_num,
        bulk_ref_date = v_bulk_ref_date,
        bulk_reference = v_bulk_reference
    where pb2.id = p_pay_batch_id;

    v_batch.bulk_ref_num := v_bulk_ref_num;
    v_batch.bulk_ref_date := v_bulk_ref_date;
    v_batch.bulk_reference := v_bulk_reference;
  else
    v_bulk_ref_num := v_batch.bulk_ref_num;
    v_bulk_ref_date := v_batch.bulk_ref_date;
    v_bulk_reference := v_batch.bulk_reference;
  end if;

  -- PAYE tax-week number (week 1 starts 6 April)
  v_tax_year_start := make_date(extract(year from v_batch.pay_date)::int, 4, 6);
  if v_batch.pay_date < v_tax_year_start then
    v_tax_year_start := make_date((extract(year from v_batch.pay_date)::int) - 1, 4, 6);
  end if;
  v_tax_week := ((v_batch.pay_date - v_tax_year_start) / 7) + 1;
  if v_tax_week < 1 then v_tax_week := 1; end if;

  -- Bucket for non-timesheet items (loan repayments etc.)
  v_pay_week_start := public._pay_week_start_monday(v_batch.pay_date);
  v_pay_week_end := (v_pay_week_start + 6);

  -- Validate PAYE net inputs if PAYE is being executed (not for LOANS batches)
  if v_do_paye = true then
    if exists (
      select 1
      from public.pay_batch_candidates pbc_chk
      where pbc_chk.pay_batch_id = p_pay_batch_id
        and pbc_chk.paye_state is not null
        and pbc_chk.paye_state <> 'READY'
      limit 1
    ) then
      raise exception 'PAYE_NOT_READY: some PAYE candidates are not READY';
    end if;

    if exists (
      select 1
      from public.pay_batch_candidates pbc_chk2
      left join lateral (
        select pni_chk.net_amount
        from public.pay_batch_paye_net_inputs pni_chk
        where pni_chk.pay_batch_candidate_id = pbc_chk2.id
        order by pni_chk.imported_at_utc desc
        limit 1
      ) ni_chk on true
      where pbc_chk2.pay_batch_id = p_pay_batch_id
        and pbc_chk2.paye_state is not null
        and ni_chk.net_amount is null
      limit 1
    ) then
      raise exception 'PAYE_NET_MISSING: missing net pay for one or more PAYE candidates';
    end if;

    if exists (
      select 1
      from public.pay_batch_candidates pbc_chk3
      where pbc_chk3.pay_batch_id = p_pay_batch_id
        and pbc_chk3.paye_state is not null
        and (pbc_chk3.net_bank_amount is null)
      limit 1
    ) then
      raise exception 'PAYE_NET_BANK_AMOUNT_MISSING: net_bank_amount missing for one or more PAYE candidates';
    end if;

    if exists (
      select 1
      from public.pay_batch_candidates pbc_chk4
      where pbc_chk4.pay_batch_id = p_pay_batch_id
        and pbc_chk4.paye_state is not null
        and pbc_chk4.net_bank_amount is not null
        and (
          pbc_chk4.net_bank_amount < 0
          or pbc_chk4.net_bank_amount <> round(pbc_chk4.net_bank_amount, 2)
        )
      limit 1
    ) then
      raise exception 'PAYE_NET_BANK_AMOUNT_INVALID: net_bank_amount must be >= 0 and 2dp';
    end if;
  end if;

  if v_do_loans = true then
    select count(*)::int
    into v_invalid_loans_items
    from public.pay_batch_items pbi_l
    join public.pay_batch_candidates pbc_l
      on pbc_l.id = pbi_l.pay_batch_candidate_id
    where pbc_l.pay_batch_id = p_pay_batch_id
      and pbi_l.is_voided = false
      and pbi_l.item_type = 'LOAN_PAYOUT'
      and (
        pbi_l.source_ref is null
        or btrim(pbi_l.source_ref) = ''
        or btrim(pbi_l.source_ref) !~ '^advance:[0-9a-fA-F-]{36}$'
        or not exists (
          select 1
          from public.pay_advances pa
          where pa.id = replace(pbi_l.source_ref, 'advance:', '')::uuid
            and pa.advance_kind = 'LOAN'::public.pay_advance_kind_enum
        )
      );

    if v_invalid_loans_items > 0 then
      raise exception 'LOANS_PAYOUT_INVALID: one or more LOAN_PAYOUT items missing/invalid advance reference';
    end if;
  end if;

  -- Temp staging for transfer groups (idempotent within transaction)
  create temp table if not exists _tmp_pay_transfer_groups (
    pay_channel text not null,
    candidate_id uuid not null,
    umbrella_id uuid null,
    week_ending_bucket date null,
    amount numeric not null,
    currency text not null,
    status text not null,
    rail_state text null,
    rail_meta_json jsonb null,
    payment_reference text null,
    payee_name text null,
    sort_code text null,
    account_number text null,
    account_type text null,
    bank_details_hash_snapshot text null,
    payee_entity_kind text not null,
    payee_entity_id uuid null,
    transfer_group_key text not null,
    grouping_mode_used text null
  ) on commit drop;

  truncate table _tmp_pay_transfer_groups;

  create temp table if not exists _tmp_pay_transfer_item_groups (
    pay_batch_item_id uuid not null,
    pay_channel text not null,
    candidate_id uuid not null,
    umbrella_id uuid null,
    week_ending_bucket date null,
    amount numeric not null,
    currency text not null,
    status text not null,
    rail_state text null,
    rail_meta_json jsonb null,
    payment_reference text null,
    payee_name text null,
    sort_code text null,
    account_number text null,
    account_type text null,
    bank_details_hash_snapshot text null,
    payee_entity_kind text not null,
    payee_entity_id uuid null,
    transfer_group_key text not null,
    grouping_mode_used text null
  ) on commit drop;

  truncate table _tmp_pay_transfer_item_groups;

  -- =========================================================
  -- LOANS groups: candidate_id only (one transfer per candidate)
  -- Payee is candidate (loan payout direct)
  -- Snapshot-only destination execution.
  -- =========================================================
  if v_do_loans = true then
    insert into _tmp_pay_transfer_groups(
      pay_channel,
      candidate_id,
      umbrella_id,
      week_ending_bucket,
      amount,
      currency,
      status,
      rail_state,
      rail_meta_json,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used
    )
    with loan_item_rows as (
      select
        pbc.candidate_id,
        coalesce(pbi.amount_inc_vat, pbi.amount_ex_vat, 0)::numeric as item_amount,
        (pbi.payout_instruction_snapshot_json is null) as is_missing_snapshot,
        upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', 'NORMAL_PAY_ROUTE')) as routing_kind_txt,
        upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind', 'CANDIDATE')) as payee_entity_kind_txt,
        case
          when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_id','')), '') is null then null::uuid
          else (pbi.payout_instruction_snapshot_json->>'payee_entity_id')::uuid
        end as snapshot_payee_entity_id,
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), '') as snapshot_beneficiary_name,
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'sort_code','')), '') as snapshot_sort_code,
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_number','')), '') as snapshot_account_number,
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_type','')), '') as snapshot_account_type,
        nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as snapshot_bank_details_hash,
        concat_ws(
          '|',
          upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', 'NORMAL_PAY_ROUTE')),
          upper(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_kind', 'CANDIDATE')),
          coalesce(
            case
              when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'payee_entity_id','')), '') is null then null
              else (pbi.payout_instruction_snapshot_json->>'payee_entity_id')
            end,
            ''
          ),
          coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), ''),
          coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'sort_code','')), ''), ''),
          coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_number','')), ''), ''),
          coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), ''), '')
        ) as destination_signature
      from public.pay_batch_candidates pbc
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
       and pbi.item_type = 'LOAN_PAYOUT'
       and coalesce(pbi.is_voided, false) = false
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    loan_candidate_rows as (
      select
        lir.candidate_id,
        round(sum(lir.item_amount), 2) as sum_amt,
        bool_or(lir.is_missing_snapshot) as has_missing_snapshot,
        count(distinct lir.destination_signature) filter (where lir.is_missing_snapshot = false) as destination_variant_count,
        min(lir.routing_kind_txt) filter (where lir.is_missing_snapshot = false) as routing_kind_txt,
        min(lir.payee_entity_kind_txt) filter (where lir.is_missing_snapshot = false) as payee_entity_kind_txt,
        (array_agg(lir.snapshot_payee_entity_id order by lir.snapshot_payee_entity_id::text nulls last) filter (where lir.is_missing_snapshot = false))[1] as snapshot_payee_entity_id,
        min(lir.snapshot_beneficiary_name) filter (where lir.is_missing_snapshot = false) as snapshot_beneficiary_name,
        min(lir.snapshot_sort_code) filter (where lir.is_missing_snapshot = false) as snapshot_sort_code,
        min(lir.snapshot_account_number) filter (where lir.is_missing_snapshot = false) as snapshot_account_number,
        min(lir.snapshot_account_type) filter (where lir.is_missing_snapshot = false) as snapshot_account_type,
        min(lir.snapshot_bank_details_hash) filter (where lir.is_missing_snapshot = false) as snapshot_bank_details_hash
      from loan_item_rows lir
      group by lir.candidate_id
      having round(greatest(sum(lir.item_amount), 0), 2) > 0
    )
    select
      'PAYE'::text as pay_channel,
      lcr.candidate_id,
      null::uuid as umbrella_id,
      null::date as week_ending_bucket,
      round(lcr.sum_amt, 2) as amount,
      'GBP'::text as currency,
      case
        when lcr.has_missing_snapshot then 'BLOCKED'
        when coalesce(lcr.destination_variant_count, 0) <> 1 then 'BLOCKED'
        when coalesce(lcr.routing_kind_txt, '') <> 'NORMAL_PAY_ROUTE' then 'BLOCKED'
        when coalesce(lcr.payee_entity_kind_txt, '') <> 'CANDIDATE' then 'BLOCKED'
        when lcr.snapshot_payee_entity_id is distinct from lcr.candidate_id then 'BLOCKED'
        when lcr.snapshot_bank_details_hash is null or btrim(coalesce(lcr.snapshot_bank_details_hash,'')) = '' then 'BLOCKED'
        when lcr.snapshot_beneficiary_name is null then 'BLOCKED'
        when length(regexp_replace(coalesce(lcr.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6 then 'BLOCKED'
        when nullif(regexp_replace(coalesce(lcr.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null then 'BLOCKED'
        when nullif(btrim(coalesce(lcr.snapshot_account_type,'')), '') is null then 'BLOCKED'
        else 'PENDING'
      end as status,
      case
        when lcr.has_missing_snapshot then 'BLOCKED_PAYOUT_INSTRUCTION_SNAPSHOT'
        when coalesce(lcr.destination_variant_count, 0) <> 1
          or coalesce(lcr.routing_kind_txt, '') <> 'NORMAL_PAY_ROUTE'
          or coalesce(lcr.payee_entity_kind_txt, '') <> 'CANDIDATE'
          or lcr.snapshot_payee_entity_id is distinct from lcr.candidate_id
          then 'BLOCKED_DESTINATION_INVALID'
        when lcr.snapshot_bank_details_hash is null
          or btrim(coalesce(lcr.snapshot_bank_details_hash,'')) = ''
          or lcr.snapshot_beneficiary_name is null
          or length(regexp_replace(coalesce(lcr.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
          or nullif(regexp_replace(coalesce(lcr.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
          or nullif(btrim(coalesce(lcr.snapshot_account_type,'')), '') is null
          then 'BLOCKED_BANK_DETAILS'
        else null
      end as rail_state,
      case
        when lcr.has_missing_snapshot then jsonb_build_object('reason_code', 'PAYOUT_INSTRUCTION_SNAPSHOT_MISSING')
        when coalesce(lcr.destination_variant_count, 0) <> 1
          or coalesce(lcr.routing_kind_txt, '') <> 'NORMAL_PAY_ROUTE'
          or coalesce(lcr.payee_entity_kind_txt, '') <> 'CANDIDATE'
          or lcr.snapshot_payee_entity_id is distinct from lcr.candidate_id
          then jsonb_build_object('reason_code', 'DESTINATION_INVALID')
        when lcr.snapshot_bank_details_hash is null
          or btrim(coalesce(lcr.snapshot_bank_details_hash,'')) = ''
          or lcr.snapshot_beneficiary_name is null
          or length(regexp_replace(coalesce(lcr.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
          or nullif(regexp_replace(coalesce(lcr.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
          or nullif(btrim(coalesce(lcr.snapshot_account_type,'')), '') is null
          then jsonb_build_object('reason_code', 'BANK_DETAILS_MISSING')
        else null
      end as rail_meta_json,
      ('Loan payout - week ' || v_tax_week::text) as payment_reference,
      lcr.snapshot_beneficiary_name as payee_name,
      lcr.snapshot_sort_code as sort_code,
      lcr.snapshot_account_number as account_number,
      lcr.snapshot_account_type as account_type,
      lcr.snapshot_bank_details_hash as bank_details_hash_snapshot,
      'CANDIDATE'::text as payee_entity_kind,
      lcr.candidate_id as payee_entity_id,
      lcr.candidate_id::text as transfer_group_key,
      'CANDIDATE'::text as grouping_mode_used
    from loan_candidate_rows lcr;

    if exists (
      select 1
      from _tmp_pay_transfer_groups gchk
      where gchk.pay_channel = 'PAYE'
        and round(coalesce(gchk.amount,0),2) <= 0
      limit 1
    ) then
      raise exception 'LOANS_PAYOUT_INVALID: payout amount must be > 0';
    end if;
  end if;

  -- =========================================================
  -- PAYE groups: destination-aware grouping
  -- Snapshot-only destination execution for all PAYE routes.
  -- =========================================================
  if v_do_paye = true then
    insert into _tmp_pay_transfer_item_groups(
      pay_batch_item_id,
      pay_channel,
      candidate_id,
      umbrella_id,
      week_ending_bucket,
      amount,
      currency,
      status,
      rail_state,
      rail_meta_json,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used
    )
    with paye_item_rows as (
      select
        pbi_p.id as pay_batch_item_id,
        'PAYE'::text as pay_channel,
        pbc_p.candidate_id,
        null::uuid as umbrella_id,
        null::date as week_ending_bucket,
        coalesce(pbi_p.amount_inc_vat, pbi_p.amount_ex_vat, 0)::numeric as item_amount,
        (pbi_p.payout_instruction_snapshot_json is null) as is_missing_snapshot,
        upper(coalesce(pbi_p.payout_instruction_snapshot_json->>'routing_kind', 'NORMAL_PAY_ROUTE')) as routing_kind_txt,
        upper(coalesce(pbi_p.payout_instruction_snapshot_json->>'payee_entity_kind', 'CANDIDATE')) as payee_entity_kind_txt,
        case
          when nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'payee_entity_id','')), '') is null then null::uuid
          else (pbi_p.payout_instruction_snapshot_json->>'payee_entity_id')::uuid
        end as snapshot_payee_entity_id,
        nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'beneficiary_name','')), '') as snapshot_beneficiary_name,
        nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'sort_code','')), '') as snapshot_sort_code,
        nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'account_number','')), '') as snapshot_account_number,
        nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'account_type','')), '') as snapshot_account_type,
        nullif(btrim(coalesce(pbi_p.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as snapshot_bank_details_hash
      from public.pay_batch_candidates pbc_p
      join public.pay_batch_items pbi_p
        on pbi_p.pay_batch_candidate_id = pbc_p.id
       and pbi_p.pay_channel = 'PAYE'
       and pbi_p.item_type <> 'DEBT_CREATED'
       and coalesce(pbi_p.is_voided, false) = false
      where pbc_p.pay_batch_id = p_pay_batch_id
    ),
    paye_item_final as (
      select
        pir.pay_batch_item_id,
        'PAYE'::text as pay_channel,
        pir.candidate_id,
        null::uuid as umbrella_id,
        null::date as week_ending_bucket,
        pir.item_amount as amount,
        'GBP'::text as currency,
        case
          when pir.is_missing_snapshot then 'BLOCKED'
          when upper(coalesce(pir.routing_kind_txt,'')) <> 'NORMAL_PAY_ROUTE' then 'BLOCKED'
          when pir.payee_entity_kind_txt <> 'CANDIDATE' then 'BLOCKED'
          when pir.snapshot_payee_entity_id is distinct from pir.candidate_id then 'BLOCKED'
          when pir.snapshot_bank_details_hash is null or pir.snapshot_bank_details_hash = '' then 'BLOCKED'
          when pir.snapshot_beneficiary_name is null then 'BLOCKED'
          when length(regexp_replace(coalesce(pir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6 then 'BLOCKED'
          when nullif(regexp_replace(coalesce(pir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null then 'BLOCKED'
          when pir.snapshot_account_type is null or btrim(coalesce(pir.snapshot_account_type,'')) = '' then 'BLOCKED'
          else 'PENDING'
        end as status,
        case
          when pir.is_missing_snapshot then 'BLOCKED_PAYOUT_INSTRUCTION_SNAPSHOT'
          when upper(coalesce(pir.routing_kind_txt,'')) <> 'NORMAL_PAY_ROUTE'
            or pir.payee_entity_kind_txt <> 'CANDIDATE'
            or pir.snapshot_payee_entity_id is distinct from pir.candidate_id
            then 'BLOCKED_DESTINATION_INVALID'
          when pir.snapshot_bank_details_hash is null or pir.snapshot_bank_details_hash = ''
            or pir.snapshot_beneficiary_name is null
            or length(regexp_replace(coalesce(pir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
            or nullif(regexp_replace(coalesce(pir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
            or pir.snapshot_account_type is null or btrim(coalesce(pir.snapshot_account_type,'')) = ''
            then 'BLOCKED_BANK_DETAILS'
          else null
        end as rail_state,
        case
          when pir.is_missing_snapshot then jsonb_build_object('reason_code', 'PAYOUT_INSTRUCTION_SNAPSHOT_MISSING')
          when upper(coalesce(pir.routing_kind_txt,'')) <> 'NORMAL_PAY_ROUTE'
            or pir.payee_entity_kind_txt <> 'CANDIDATE'
            or pir.snapshot_payee_entity_id is distinct from pir.candidate_id
            then jsonb_build_object('reason_code', 'DESTINATION_INVALID')
          when pir.snapshot_bank_details_hash is null or pir.snapshot_bank_details_hash = ''
            or pir.snapshot_beneficiary_name is null
            or length(regexp_replace(coalesce(pir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
            or nullif(regexp_replace(coalesce(pir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
            or pir.snapshot_account_type is null or btrim(coalesce(pir.snapshot_account_type,'')) = ''
            then jsonb_build_object('reason_code', 'BANK_DETAILS_MISSING')
          else null
        end as rail_meta_json,
        ('Pay - week ' || v_tax_week::text) as payment_reference,
        pir.snapshot_beneficiary_name as payee_name,
        pir.snapshot_sort_code as sort_code,
        pir.snapshot_account_number as account_number,
        pir.snapshot_account_type as account_type,
        pir.snapshot_bank_details_hash as bank_details_hash_snapshot,
        'CANDIDATE'::text as payee_entity_kind,
        pir.candidate_id as payee_entity_id,
        (pir.candidate_id::text || '|NORMAL_PAY_ROUTE|' || coalesce(pir.snapshot_bank_details_hash, '')) as transfer_group_key,
        'CANDIDATE_DESTINATION'::text as grouping_mode_used
      from paye_item_rows pir
    )
    select
      pif.pay_batch_item_id,
      pif.pay_channel,
      pif.candidate_id,
      pif.umbrella_id,
      pif.week_ending_bucket,
      pif.amount,
      pif.currency,
      pif.status,
      pif.rail_state,
      pif.rail_meta_json,
      pif.payment_reference,
      pif.payee_name,
      pif.sort_code,
      pif.account_number,
      pif.account_type,
      pif.bank_details_hash_snapshot,
      pif.payee_entity_kind,
      pif.payee_entity_id,
      pif.transfer_group_key,
      pif.grouping_mode_used
    from paye_item_final pif;

    insert into _tmp_pay_transfer_groups(
      pay_channel,
      candidate_id,
      umbrella_id,
      week_ending_bucket,
      amount,
      currency,
      status,
      rail_state,
      rail_meta_json,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used
    )
    with paye_candidate_destination_guard as (
      select
        tig_guard.candidate_id,
        count(*) filter (
          where round(greatest(coalesce(tig_guard.amount, 0), 0), 2) > 0
        )::int as positive_item_count,
        count(*) filter (
          where round(greatest(coalesce(tig_guard.amount, 0), 0), 2) > 0
            and tig_guard.status = 'BLOCKED'
        )::int as blocked_positive_item_count,
        count(distinct concat_ws(
          '|',
          upper(coalesce(nullif(btrim(tig_guard.payee_entity_kind), ''), '')),
          coalesce(tig_guard.payee_entity_id::text, ''),
          coalesce(nullif(btrim(tig_guard.payee_name), ''), ''),
          regexp_replace(coalesce(tig_guard.sort_code, ''), '[^0-9]', '', 'g'),
          regexp_replace(coalesce(tig_guard.account_number, ''), '[^0-9]', '', 'g'),
          upper(coalesce(nullif(btrim(tig_guard.account_type), ''), '')),
          coalesce(nullif(btrim(tig_guard.bank_details_hash_snapshot), ''), '')
        )) filter (
          where round(greatest(coalesce(tig_guard.amount, 0), 0), 2) > 0
        )::int as destination_variant_count,
        count(distinct concat_ws(
          '|',
          upper(coalesce(nullif(btrim(tig_guard.payee_entity_kind), ''), '')),
          coalesce(tig_guard.payee_entity_id::text, ''),
          coalesce(nullif(btrim(tig_guard.payee_name), ''), ''),
          regexp_replace(coalesce(tig_guard.sort_code, ''), '[^0-9]', '', 'g'),
          regexp_replace(coalesce(tig_guard.account_number, ''), '[^0-9]', '', 'g'),
          upper(coalesce(nullif(btrim(tig_guard.account_type), ''), '')),
          coalesce(nullif(btrim(tig_guard.bank_details_hash_snapshot), ''), '')
        )) filter (
          where round(greatest(coalesce(tig_guard.amount, 0), 0), 2) > 0
            and tig_guard.status <> 'BLOCKED'
        )::int as valid_destination_variant_count
      from _tmp_pay_transfer_item_groups tig_guard
      join public.pay_batch_candidates pbc_guard
        on pbc_guard.pay_batch_id = p_pay_batch_id
       and pbc_guard.candidate_id = tig_guard.candidate_id
      where tig_guard.pay_channel = 'PAYE'
        and round(greatest(coalesce(tig_guard.amount, 0), 0), 2) > 0
        and round(coalesce(pbc_guard.net_bank_amount, 0), 2) > 0
      group by tig_guard.candidate_id
    )
    select
      tig.pay_channel,
      tig.candidate_id,
      (array_agg(tig.umbrella_id order by tig.umbrella_id::text nulls last))[1] as umbrella_id,
      null::date as week_ending_bucket,
      case
        when coalesce(pcdg.positive_item_count, 0) > 0
          and coalesce(pcdg.blocked_positive_item_count, 0) = 0
          and coalesce(pcdg.destination_variant_count, 0) = 1
          and coalesce(pcdg.valid_destination_variant_count, 0) = 1
          then round(max(coalesce(pbc_net.net_bank_amount, 0)), 2)
        else round(sum(greatest(coalesce(tig.amount, 0), 0)), 2)
      end as amount,
      max(tig.currency) as currency,
      case
        when coalesce(pcdg.positive_item_count, 0) = 0 then 'BLOCKED'
        when coalesce(pcdg.blocked_positive_item_count, 0) <> 0 then 'BLOCKED'
        when coalesce(pcdg.destination_variant_count, 0) <> 1 then 'BLOCKED'
        when coalesce(pcdg.valid_destination_variant_count, 0) <> 1 then 'BLOCKED'
        when bool_or(tig.status = 'BLOCKED') then 'BLOCKED'
        else 'PENDING'
      end as status,
      case
        when coalesce(pcdg.positive_item_count, 0) = 0 then 'BLOCKED_PAYE_DESTINATION_MISSING'
        when coalesce(pcdg.blocked_positive_item_count, 0) <> 0 then 'BLOCKED_PAYE_DESTINATION_INVALID'
        when coalesce(pcdg.destination_variant_count, 0) <> 1 then 'BLOCKED_PAYE_DESTINATION_VARIANT'
        when coalesce(pcdg.valid_destination_variant_count, 0) <> 1 then 'BLOCKED_PAYE_DESTINATION_VARIANT'
        when bool_or(tig.status = 'BLOCKED') then min(tig.rail_state)
        else null
      end as rail_state,
      case
        when coalesce(pcdg.positive_item_count, 0) = 0
          or coalesce(pcdg.blocked_positive_item_count, 0) <> 0
          or coalesce(pcdg.destination_variant_count, 0) <> 1
          or coalesce(pcdg.valid_destination_variant_count, 0) <> 1
          then jsonb_build_object(
            'reason_code', case
              when coalesce(pcdg.blocked_positive_item_count, 0) <> 0 then 'PAYE_DESTINATION_INVALID'
              else 'PAYE_DESTINATION_VARIANT_COUNT_INVALID'
            end,
            'message', 'PAYE candidate must have exactly one valid frozen payout destination signature before candidate-level net_bank_amount can be materialised',
            'candidate_id', tig.candidate_id::text,
            'positive_item_count', coalesce(pcdg.positive_item_count, 0),
            'blocked_positive_item_count', coalesce(pcdg.blocked_positive_item_count, 0),
            'destination_variant_count', coalesce(pcdg.destination_variant_count, 0),
            'valid_destination_variant_count', coalesce(pcdg.valid_destination_variant_count, 0),
            'transfer_group_key', tig.transfer_group_key
          )
        when bool_or(tig.status = 'BLOCKED') then (array_agg(tig.rail_meta_json order by tig.rail_meta_json::text nulls last))[1]
        else null
      end as rail_meta_json,
      min(tig.payment_reference) as payment_reference,
      min(tig.payee_name) as payee_name,
      min(tig.sort_code) as sort_code,
      min(tig.account_number) as account_number,
      min(tig.account_type) as account_type,
      min(tig.bank_details_hash_snapshot) as bank_details_hash_snapshot,
      min(tig.payee_entity_kind) as payee_entity_kind,
      (array_agg(tig.payee_entity_id order by tig.payee_entity_id::text nulls last))[1] as payee_entity_id,
      tig.transfer_group_key,
      min(tig.grouping_mode_used) as grouping_mode_used
    from _tmp_pay_transfer_item_groups tig
    join public.pay_batch_candidates pbc_net
      on pbc_net.pay_batch_id = p_pay_batch_id
     and pbc_net.candidate_id = tig.candidate_id
    left join paye_candidate_destination_guard pcdg
      on pcdg.candidate_id = tig.candidate_id
    where tig.pay_channel = 'PAYE'
      and round(greatest(coalesce(tig.amount, 0), 0), 2) > 0
      and round(coalesce(pbc_net.net_bank_amount, 0), 2) > 0
    group by
      tig.pay_channel,
      tig.candidate_id,
      tig.transfer_group_key,
      pcdg.positive_item_count,
      pcdg.blocked_positive_item_count,
      pcdg.destination_variant_count,
      pcdg.valid_destination_variant_count
    having round(max(coalesce(pbc_net.net_bank_amount, 0)), 2) > 0;
  end if;

  -- =========================================================
  -- UMBRELLA groups: destination-aware grouping
  -- Snapshot-only destination execution for all umbrella routes.
  -- =========================================================
  if v_do_umbrella = true then
    insert into _tmp_pay_transfer_item_groups(
      pay_batch_item_id,
      pay_channel,
      candidate_id,
      umbrella_id,
      week_ending_bucket,
      amount,
      currency,
      status,
      rail_state,
      rail_meta_json,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used
    )
    with umbrella_item_rows as (
      select
        pbi_u.id as pay_batch_item_id,
        pbc_u.id as pay_batch_candidate_id,
        'UMBRELLA'::text as pay_channel,
        pbc_u.candidate_id,
        pbi_u.finance_case_id,
        pbi_u.item_type,
        coalesce(pbi_u.amount_inc_vat, pbi_u.amount_ex_vat, 0)::numeric as item_amount,
        pbi_u.payout_instruction_snapshot_json as payout_instruction_snapshot_json,
        c_u.first_name as candidate_first_name,
        c_u.last_name as candidate_last_name,
        (pbi_u.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY')) as is_finance_item,
        (pbi_u.payout_instruction_snapshot_json is null) as is_missing_snapshot,
        upper(coalesce(pbi_u.payout_instruction_snapshot_json->>'routing_kind', 'UMBRELLA_COMPANY')) as routing_kind_txt,
        upper(coalesce(pbi_u.payout_instruction_snapshot_json->>'payee_entity_kind', 'UMBRELLA')) as payee_entity_kind_txt,
        case
          when nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'payee_entity_id','')), '') is null then null::uuid
          else (pbi_u.payout_instruction_snapshot_json->>'payee_entity_id')::uuid
        end as snapshot_payee_entity_id,
        nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as snapshot_bank_details_hash,
        nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'beneficiary_name','')), '') as snapshot_beneficiary_name,
        nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'sort_code','')), '') as snapshot_sort_code,
        nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'account_number','')), '') as snapshot_account_number,
        nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'account_type','')), '') as snapshot_account_type,
        case
          when nullif(btrim(coalesce(pbi_u.payout_instruction_snapshot_json->>'week_ending_bucket','')), '') ~ '^\d{4}-\d{2}-\d{2}$'
            then (pbi_u.payout_instruction_snapshot_json->>'week_ending_bucket')::date
          else null::date
        end as snapshot_week_ending_bucket
      from public.pay_batch_candidates pbc_u
      join public.pay_batch_items pbi_u
        on pbi_u.pay_batch_candidate_id = pbc_u.id
       and pbi_u.pay_channel = 'UMBRELLA'
       and pbi_u.item_type <> 'DEBT_CREATED'
       and coalesce(pbi_u.is_voided, false) = false
      join public.candidates c_u
        on c_u.id = pbc_u.candidate_id
      where pbc_u.pay_batch_id = p_pay_batch_id
    ),
    umbrella_item_final as (
      select
        uir.pay_batch_item_id,
        'UMBRELLA'::text as pay_channel,
        uir.candidate_id,
        case
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then null::uuid
          else uir.snapshot_payee_entity_id
        end as umbrella_id,
        case
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then null::date
          when uir.is_finance_item = true then uir.snapshot_week_ending_bucket
          else uir.snapshot_week_ending_bucket
        end as week_ending_bucket,
        coalesce(pbi_amt.amount_value, 0)::numeric as amount,
        'GBP'::text as currency,
        case
          when uir.is_missing_snapshot then 'BLOCKED'
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'CANDIDATE' or uir.snapshot_payee_entity_id is distinct from uir.candidate_id) then 'BLOCKED'
          when upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'UMBRELLA' or uir.snapshot_payee_entity_id is null) then 'BLOCKED'
          when upper(coalesce(uir.routing_kind_txt,'')) not in ('ONE_OFF_SPECIFIED_BANK_ACCOUNT','UMBRELLA_COMPANY') then 'BLOCKED'
          when uir.snapshot_bank_details_hash is null or uir.snapshot_bank_details_hash = '' then 'BLOCKED'
          when uir.snapshot_beneficiary_name is null then 'BLOCKED'
          when length(regexp_replace(coalesce(uir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6 then 'BLOCKED'
          when nullif(regexp_replace(coalesce(uir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null then 'BLOCKED'
          when nullif(btrim(coalesce(uir.snapshot_account_type,'')), '') is null then 'BLOCKED'
          when uir.is_finance_item = false and upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY' and uir.snapshot_week_ending_bucket is null then 'BLOCKED'
          else 'PENDING'
        end as status,
        case
          when uir.is_missing_snapshot then 'BLOCKED_PAYOUT_INSTRUCTION_SNAPSHOT'
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'CANDIDATE' or uir.snapshot_payee_entity_id is distinct from uir.candidate_id) then 'BLOCKED_DESTINATION_INVALID'
          when upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'UMBRELLA' or uir.snapshot_payee_entity_id is null) then 'BLOCKED_DESTINATION_INVALID'
          when upper(coalesce(uir.routing_kind_txt,'')) not in ('ONE_OFF_SPECIFIED_BANK_ACCOUNT','UMBRELLA_COMPANY') then 'BLOCKED_DESTINATION_INVALID'
          when uir.snapshot_bank_details_hash is null or uir.snapshot_bank_details_hash = ''
            or uir.snapshot_beneficiary_name is null
            or length(regexp_replace(coalesce(uir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
            or nullif(regexp_replace(coalesce(uir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
            or nullif(btrim(coalesce(uir.snapshot_account_type,'')), '') is null
            or (uir.is_finance_item = false and upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY' and uir.snapshot_week_ending_bucket is null)
            then 'BLOCKED_BANK_DETAILS'
          else null
        end as rail_state,
        case
          when uir.is_missing_snapshot then jsonb_build_object('reason_code', 'PAYOUT_INSTRUCTION_SNAPSHOT_MISSING')
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'CANDIDATE' or uir.snapshot_payee_entity_id is distinct from uir.candidate_id) then jsonb_build_object('reason_code', 'DESTINATION_INVALID')
          when upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY'
               and (coalesce(uir.payee_entity_kind_txt,'') <> 'UMBRELLA' or uir.snapshot_payee_entity_id is null) then jsonb_build_object('reason_code', 'DESTINATION_INVALID')
          when upper(coalesce(uir.routing_kind_txt,'')) not in ('ONE_OFF_SPECIFIED_BANK_ACCOUNT','UMBRELLA_COMPANY') then jsonb_build_object('reason_code', 'DESTINATION_INVALID')
          when uir.snapshot_bank_details_hash is null or uir.snapshot_bank_details_hash = ''
            or uir.snapshot_beneficiary_name is null
            or length(regexp_replace(coalesce(uir.snapshot_sort_code,''), '[^0-9]', '', 'g')) <> 6
            or nullif(regexp_replace(coalesce(uir.snapshot_account_number,''), '[^0-9]', '', 'g'), '') is null
            or nullif(btrim(coalesce(uir.snapshot_account_type,'')), '') is null
            or (uir.is_finance_item = false and upper(coalesce(uir.routing_kind_txt,'')) = 'UMBRELLA_COMPANY' and uir.snapshot_week_ending_bucket is null)
            then jsonb_build_object('reason_code', 'BANK_DETAILS_MISSING')
          else null
        end as rail_meta_json,
        left(
          btrim(concat_ws(' ', nullif(btrim(coalesce(uir.candidate_last_name,'')),''), nullif(btrim(coalesce(uir.candidate_first_name,'')),''))),
          18
        ) as payment_reference,
        uir.snapshot_beneficiary_name as payee_name,
        uir.snapshot_sort_code as sort_code,
        uir.snapshot_account_number as account_number,
        uir.snapshot_account_type as account_type,
        uir.snapshot_bank_details_hash as bank_details_hash_snapshot,
        case
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'::text
          else 'UMBRELLA'::text
        end as payee_entity_kind,
        case
          when upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then uir.candidate_id
          else uir.snapshot_payee_entity_id
        end as payee_entity_id,
        case
          when uir.is_finance_item = true and upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then
            uir.candidate_id::text || '|ONEOFF|' || coalesce(uir.snapshot_bank_details_hash, '')
          when upper(coalesce(uir.routing_kind_txt,'')) <> 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and exists (
              select 1
              from umbrella_item_rows uir_net_adjustment
              where uir_net_adjustment.candidate_id = uir.candidate_id
                and upper(coalesce(uir_net_adjustment.routing_kind_txt,'')) = upper(coalesce(uir.routing_kind_txt,''))
                and upper(coalesce(uir_net_adjustment.payee_entity_kind_txt,'')) = upper(coalesce(uir.payee_entity_kind_txt,''))
                and uir_net_adjustment.snapshot_payee_entity_id is not distinct from uir.snapshot_payee_entity_id
                and coalesce(uir_net_adjustment.snapshot_bank_details_hash, '') = coalesce(uir.snapshot_bank_details_hash, '')
                and uir_net_adjustment.is_finance_item = true
                and round(coalesce(uir_net_adjustment.item_amount, 0), 2) < 0
            ) then
            uir.candidate_id::text || '|NET_UMBRELLA|' || upper(coalesce(uir.routing_kind_txt,'')) || '|' || coalesce(uir.payee_entity_kind_txt,'') || '|' ||
            coalesce(uir.snapshot_payee_entity_id::text, '') || '|' || coalesce(uir.snapshot_bank_details_hash, '')
          when uir.is_finance_item = true then
            uir.candidate_id::text || '|' || upper(coalesce(uir.routing_kind_txt,'')) || '|' || coalesce(uir.payee_entity_kind_txt,'') || '|' ||
            coalesce(uir.snapshot_payee_entity_id::text, '') || '|' || coalesce(uir.snapshot_bank_details_hash, '')
          else
            uir.candidate_id::text || '|' || uir.snapshot_week_ending_bucket::text || '|UMBRELLA|' || coalesce(uir.snapshot_payee_entity_id::text, '') || '|' || coalesce(uir.snapshot_bank_details_hash, '')
        end as transfer_group_key,
        case
          when uir.is_finance_item = true and upper(coalesce(uir.routing_kind_txt,'')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE_DESTINATION'::text
          when uir.is_finance_item = true then 'FINANCE_DESTINATION'::text
          else 'CANDIDATE_WEEK_DESTINATION'::text
        end as grouping_mode_used
      from umbrella_item_rows uir
      join lateral (
        select coalesce(uir.item_amount, 0)::numeric as amount_value
      ) pbi_amt on true
    )
    select
      uif.pay_batch_item_id,
      uif.pay_channel,
      uif.candidate_id,
      uif.umbrella_id,
      uif.week_ending_bucket,
      uif.amount,
      uif.currency,
      uif.status,
      uif.rail_state,
      uif.rail_meta_json,
      uif.payment_reference,
      uif.payee_name,
      uif.sort_code,
      uif.account_number,
      uif.account_type,
      uif.bank_details_hash_snapshot,
      uif.payee_entity_kind,
      uif.payee_entity_id,
      uif.transfer_group_key,
      uif.grouping_mode_used
    from umbrella_item_final uif;

    insert into _tmp_pay_transfer_groups(
      pay_channel,
      candidate_id,
      umbrella_id,
      week_ending_bucket,
      amount,
      currency,
      status,
      rail_state,
      rail_meta_json,
      payment_reference,
      payee_name,
      sort_code,
      account_number,
      account_type,
      bank_details_hash_snapshot,
      payee_entity_kind,
      payee_entity_id,
      transfer_group_key,
      grouping_mode_used
    )
    select
      tig.pay_channel,
      (array_agg(tig.candidate_id order by tig.candidate_id::text nulls last))[1] as candidate_id,
      (array_agg(tig.umbrella_id order by tig.umbrella_id::text nulls last))[1] as umbrella_id,
      min(tig.week_ending_bucket) as week_ending_bucket,
      round(sum(tig.amount), 2) as amount,
      max(tig.currency) as currency,
      case when bool_or(tig.status = 'BLOCKED') then 'BLOCKED' else 'PENDING' end as status,
      case when bool_or(tig.status = 'BLOCKED') then min(tig.rail_state) else null end as rail_state,
      case when bool_or(tig.status = 'BLOCKED') then (array_agg(tig.rail_meta_json order by tig.rail_meta_json::text nulls last))[1] else null end as rail_meta_json,
      min(tig.payment_reference) as payment_reference,
      min(tig.payee_name) as payee_name,
      min(tig.sort_code) as sort_code,
      min(tig.account_number) as account_number,
      min(tig.account_type) as account_type,
      min(tig.bank_details_hash_snapshot) as bank_details_hash_snapshot,
      min(tig.payee_entity_kind) as payee_entity_kind,
      (array_agg(tig.payee_entity_id order by tig.payee_entity_id::text nulls last))[1] as payee_entity_id,
      tig.transfer_group_key,
      min(tig.grouping_mode_used) as grouping_mode_used
    from _tmp_pay_transfer_item_groups tig
    where tig.pay_channel = 'UMBRELLA'
    group by tig.pay_channel, tig.transfer_group_key
    having round(sum(coalesce(tig.amount, 0)), 2) > 0
       and count(*) filter (where round(greatest(coalesce(tig.amount, 0), 0), 2) > 0) > 0;
  end if;

  -- Clear old item→transfer links for executed scopes (rebuild coherently)
  if v_do_paye = true then
    update public.pay_batch_items pbi_clr
    set pay_bank_transfer_id = null
    from public.pay_batch_candidates pbc_clr
    where pbi_clr.pay_batch_candidate_id = pbc_clr.id
      and pbc_clr.pay_batch_id = p_pay_batch_id
      and pbi_clr.pay_channel = 'PAYE'
      and pbi_clr.item_type <> 'DEBT_CREATED';
  end if;

  if v_do_umbrella = true then
    update public.pay_batch_items pbi_clr2
    set pay_bank_transfer_id = null
    from public.pay_batch_candidates pbc_clr2
    where pbi_clr2.pay_batch_candidate_id = pbc_clr2.id
      and pbc_clr2.pay_batch_id = p_pay_batch_id
      and pbi_clr2.pay_channel = 'UMBRELLA'
      and pbi_clr2.item_type <> 'DEBT_CREATED';
  end if;

  if v_do_loans = true then
    update public.pay_batch_items pbi_clr3
    set pay_bank_transfer_id = null
    from public.pay_batch_candidates pbc_clr3
    where pbi_clr3.pay_batch_candidate_id = pbc_clr3.id
      and pbc_clr3.pay_batch_id = p_pay_batch_id
      and pbi_clr3.item_type = 'LOAN_PAYOUT';
  end if;

  -- Upsert transfers (idempotent by (pay_batch_id, pay_channel, transfer_group_key))
  insert into public.pay_bank_transfers(
    pay_batch_id,
    candidate_id,
    umbrella_id,
    pay_channel,
    amount,
    currency,
    status,
    payment_reference,
    payee_name,
    sort_code,
    account_number,
    account_type,
    rail_provider,
    rail_env,
    request_id,
    rail_tx_id,
    rail_state,
    rail_meta_json,
    bank_details_hash_snapshot,
    payee_entity_kind,
    payee_entity_id,
    transfer_group_key,
    grouping_mode_used,
    week_ending_bucket
  )
  select
    p_pay_batch_id,
    g.candidate_id,
    g.umbrella_id,
    g.pay_channel,
    g.amount,
    g.currency,
    g.status,
    g.payment_reference,
    g.payee_name,
    g.sort_code,
    g.account_number,
    g.account_type,
    v_provider,
    v_env,
    null::text as request_id,
    null::text as rail_tx_id,
    g.rail_state,
    g.rail_meta_json,
    g.bank_details_hash_snapshot,
    g.payee_entity_kind,
    g.payee_entity_id,
    g.transfer_group_key,
    g.grouping_mode_used,
    g.week_ending_bucket
  from _tmp_pay_transfer_groups g
  where (
    (v_do_paye = true and g.pay_channel = 'PAYE')
    or (v_do_umbrella = true and g.pay_channel = 'UMBRELLA')
    or (v_do_loans = true and g.pay_channel = 'PAYE')
  )
  on conflict (pay_batch_id, pay_channel, transfer_group_key)
  do update set
    candidate_id = excluded.candidate_id,
    umbrella_id = excluded.umbrella_id,
    amount = excluded.amount,
    currency = excluded.currency,
    status = excluded.status,
    payment_reference = excluded.payment_reference,
    payee_name = excluded.payee_name,
    sort_code = excluded.sort_code,
    account_number = excluded.account_number,
    account_type = excluded.account_type,
    rail_provider = excluded.rail_provider,
    rail_env = excluded.rail_env,
    rail_state = excluded.rail_state,
    rail_meta_json = excluded.rail_meta_json,
    bank_details_hash_snapshot = excluded.bank_details_hash_snapshot,
    payee_entity_kind = excluded.payee_entity_kind,
    payee_entity_id = excluded.payee_entity_id,
    grouping_mode_used = excluded.grouping_mode_used,
    week_ending_bucket = excluded.week_ending_bucket
  where public.pay_bank_transfers.status in ('PENDING','BLOCKED','FAILED');

  -- Ensure request_id is populated and stable (default to id::text)
  update public.pay_bank_transfers pbt_req
  set request_id = coalesce(nullif(pbt_req.request_id,''), pbt_req.id::text)
  where pbt_req.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt_req.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt_req.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt_req.pay_channel = 'PAYE')
    )
    and (pbt_req.request_id is null or pbt_req.request_id = '');

  -- Link items → transfers
  if v_do_paye = true then
    update public.pay_batch_items pbi_l
    set pay_bank_transfer_id = pbt_l.id
    from _tmp_pay_transfer_item_groups tig_l
    join public.pay_bank_transfers pbt_l
      on pbt_l.pay_batch_id = p_pay_batch_id
     and pbt_l.pay_channel = 'PAYE'
     and pbt_l.transfer_group_key = tig_l.transfer_group_key
    where pbi_l.id = tig_l.pay_batch_item_id
      and pbi_l.pay_batch_candidate_id is not null;
  end if;
  if v_do_umbrella = true then
    update public.pay_batch_items pbi_u
    set pay_bank_transfer_id = pbt_u.id
    from _tmp_pay_transfer_item_groups tig_u
    join public.pay_bank_transfers pbt_u
      on pbt_u.pay_batch_id = p_pay_batch_id
     and pbt_u.pay_channel = 'UMBRELLA'
     and pbt_u.transfer_group_key = tig_u.transfer_group_key
    where pbi_u.id = tig_u.pay_batch_item_id
      and pbi_u.pay_batch_candidate_id is not null;
  end if;

  if v_do_loans = true then
    update public.pay_batch_items pbi_ln
    set pay_bank_transfer_id = pbt_ln.id
    from public.pay_batch_candidates pbc_ln
    join public.pay_bank_transfers pbt_ln
      on pbt_ln.pay_batch_id = p_pay_batch_id
     and pbt_ln.pay_channel = 'PAYE'
     and pbt_ln.candidate_id = pbc_ln.candidate_id
     and pbt_ln.transfer_group_key = (pbc_ln.candidate_id::text)
    where pbi_ln.pay_batch_candidate_id = pbc_ln.id
      and pbc_ln.pay_batch_id = p_pay_batch_id
      and pbi_ln.item_type = 'LOAN_PAYOUT';
  end if;

  -- Counts for UI
  select count(*)::int
  into v_pending_count
  from public.pay_bank_transfers pbt_cnt
  where pbt_cnt.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt_cnt.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt_cnt.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt_cnt.pay_channel = 'PAYE')
    )
    and pbt_cnt.status = 'PENDING';

  select count(*)::int
  into v_blocked_count
  from public.pay_bank_transfers pbt_cnt2
  where pbt_cnt2.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt_cnt2.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt_cnt2.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt_cnt2.pay_channel = 'PAYE')
    )
    and pbt_cnt2.status = 'BLOCKED';

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt_blk.id::text,
        'pay_channel', pbt_blk.pay_channel,
        'candidate_id', pbt_blk.candidate_id::text,
        'umbrella_id', case when pbt_blk.umbrella_id is null then null else pbt_blk.umbrella_id::text end,
        'transfer_group_key', pbt_blk.transfer_group_key,
        'week_ending_bucket', case when pbt_blk.week_ending_bucket is null then null else pbt_blk.week_ending_bucket::text end,
        'rail_state', pbt_blk.rail_state,
        'rail_meta_json', pbt_blk.rail_meta_json
      )
      order by pbt_blk.pay_channel, pbt_blk.candidate_id, pbt_blk.id
    ),
    '[]'::jsonb
  )
  into v_blocked_reasons
  from public.pay_bank_transfers pbt_blk
  where pbt_blk.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt_blk.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt_blk.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt_blk.pay_channel = 'PAYE')
    )
    and pbt_blk.status = 'BLOCKED';

  -- Determine READY vs WAITING_BANK_CONFIRM from rail capability, not provider string
  select coalesce(sd.rail_supports_auto_execute, false)
  into v_auto_execute
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  -- Execution-boundary reconciliation for non-manual rails.
  -- Local transfer rows, local PENDING status, bulk_reference, and request_id are not rail-submission evidence.
  -- pay_execute_bank materialises frozen local transfer instructions; real submission state is only inferred
  -- from rail evidence written back by the rail adaptor / rail update path.
  if v_provider <> 'CSV' then
    select
      count(*) filter (
        where upper(coalesce(pbt_exec_after.status,'')) <> 'BLOCKED'
          and (
            upper(coalesce(pbt_exec_after.status,'')) = 'COMPLETED'
            or upper(coalesce(pbt_exec_after.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
      )::int,
      count(*) filter (
        where upper(coalesce(pbt_exec_after.status,'')) <> 'BLOCKED'
          and not (
            upper(coalesce(pbt_exec_after.status,'')) = 'COMPLETED'
            or upper(coalesce(pbt_exec_after.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
          and (
            nullif(btrim(coalesce(pbt_exec_after.rail_tx_id,'')), '') is not null
            or upper(coalesce(pbt_exec_after.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'submitted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'queued','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'accepted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'sent','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_after.rail_meta_json->>'processing','false'))) in ('true', '1', 'yes', 'y', 'on')
          or coalesce(
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_after.rail_meta_json->>'id','')), '')
          ) is not null
          )
      )::int,
      (
        select coalesce(
          nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
          nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
        )
        from public.pay_bank_transfers pbt_exec_ref
        where pbt_exec_ref.pay_batch_id = p_pay_batch_id
          and (
            (v_do_paye = true and pbt_exec_ref.pay_channel = 'PAYE')
            or (v_do_umbrella = true and pbt_exec_ref.pay_channel = 'UMBRELLA')
            or (v_do_loans = true and pbt_exec_ref.pay_channel = 'PAYE')
          )
          and upper(coalesce(pbt_exec_ref.status,'')) <> 'BLOCKED'
          and (
            nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), '') is not null
            or upper(coalesce(pbt_exec_ref.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION','COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submitted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'queued','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'accepted','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'sent','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'processing','false'))) in ('true', '1', 'yes', 'y', 'on')
          or coalesce(
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
          ) is not null
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
        order by
          case when nullif(btrim(coalesce(pbt_exec_ref.rail_tx_id,'')), '') is not null then 0 else 1 end,
          case when coalesce(
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'submission_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_transfer_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'provider_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'external_payment_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'transaction_id','')), ''),
            nullif(btrim(coalesce(pbt_exec_ref.rail_meta_json->>'id','')), '')
          ) is not null then 0 else 1 end,
          pbt_exec_ref.completed_at_utc desc nulls last,
          pbt_exec_ref.id desc
        limit 1
      ),
      (
        select pbt_exec_ts.completed_at_utc
        from public.pay_bank_transfers pbt_exec_ts
        where pbt_exec_ts.pay_batch_id = p_pay_batch_id
          and (
            (v_do_paye = true and pbt_exec_ts.pay_channel = 'PAYE')
            or (v_do_umbrella = true and pbt_exec_ts.pay_channel = 'UMBRELLA')
            or (v_do_loans = true and pbt_exec_ts.pay_channel = 'PAYE')
          )
          and upper(coalesce(pbt_exec_ts.status,'')) <> 'BLOCKED'
          and (
            upper(coalesce(pbt_exec_ts.status,'')) = 'COMPLETED'
            or upper(coalesce(pbt_exec_ts.rail_state,'')) in ('COMPLETED','SETTLED','PAID','SUCCESS','SUCCEEDED')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'completed','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'settled','false'))) in ('true', '1', 'yes', 'y', 'on')
            or lower(btrim(coalesce(pbt_exec_ts.rail_meta_json->>'paid','false'))) in ('true', '1', 'yes', 'y', 'on')
          )
        order by pbt_exec_ts.completed_at_utc desc nulls last, pbt_exec_ts.id desc
        limit 1
      )
    into
      v_detected_committed_transfer_count,
      v_detected_submitted_transfer_count,
      v_detected_execution_commit_ref,
      v_detected_execution_committed_at_utc
    from public.pay_bank_transfers pbt_exec_after
    where pbt_exec_after.pay_batch_id = p_pay_batch_id
      and (
        (v_do_paye = true and pbt_exec_after.pay_channel = 'PAYE')
        or (v_do_umbrella = true and pbt_exec_after.pay_channel = 'UMBRELLA')
        or (v_do_loans = true and pbt_exec_after.pay_channel = 'PAYE')
      );

    if coalesce(v_detected_committed_transfer_count, 0) > 0 then
      v_execution_commit_state := 'COMMITTED';
      v_execution_commit_ref := coalesce(v_execution_commit_ref, v_detected_execution_commit_ref);
      v_execution_committed_at_utc := coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc, now());
    elsif coalesce(v_detected_submitted_transfer_count, 0) > 0 then
      v_execution_commit_state := 'SUBMITTED_NOT_COMMITTED';
      v_execution_commit_ref := coalesce(v_execution_commit_ref, v_detected_execution_commit_ref);
    end if;
  end if;

  -- Batch status update (rail-aware via capability)
  update public.pay_batches pb3
  set
    status = case
      when v_pending_count > 0 then
        case when coalesce(v_auto_execute,false) = true then 'READY' else 'WAITING_BANK_CONFIRM' end
      else
        'PARTIAL'
    end,
    execution_commit_state = v_execution_commit_state,
    execution_commit_ref = case
      when v_execution_commit_state = 'NOT_SUBMITTED' then null
      else v_execution_commit_ref
    end,
    execution_committed_at_utc = case
      when v_execution_commit_state = 'COMMITTED' then v_execution_committed_at_utc
      else null
    end
  where pb3.id = p_pay_batch_id;

  -- Return transfers (including snapshot fields)
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_batch_id', pbt.pay_batch_id::text,
        'candidate_id', pbt.candidate_id::text,
        'umbrella_id', case when pbt.umbrella_id is null then null else pbt.umbrella_id::text end,
        'pay_channel', pbt.pay_channel,
        'amount', pbt.amount,
        'currency', pbt.currency,
        'status', pbt.status,
        'payment_reference', pbt.payment_reference,
        'payee_name', pbt.payee_name,
        'sort_code', pbt.sort_code,
        'account_number', pbt.account_number,
        'account_type', pbt.account_type,
        'rail_provider', pbt.rail_provider,
        'rail_env', pbt.rail_env,
        'request_id', pbt.request_id,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,
        'bank_details_hash_snapshot', pbt.bank_details_hash_snapshot,
        'payee_entity_kind', pbt.payee_entity_kind,
        'payee_entity_id', case when pbt.payee_entity_id is null then null else pbt.payee_entity_id::text end,
        'transfer_group_key', pbt.transfer_group_key,
        'grouping_mode_used', pbt.grouping_mode_used,
        'week_ending_bucket', case when pbt.week_ending_bucket is null then null else pbt.week_ending_bucket::text end
      )
      order by pbt.pay_channel, pbt.week_ending_bucket nulls last, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt.pay_channel = 'PAYE')
    );


  IF v_provider <> 'CSV' AND COALESCE(v_pending_count, 0) > 0 THEN
    v_provider_submit_preflight_result := public._pay_batch_provider_submit_preflight_recheck(
      p_pay_batch_id,
      jsonb_build_object(
        'scope_type', 'BATCH',
        'pay_channel_scope', v_scope,
        'source_rpc', 'pay_execute_bank'
      ),
      p_operation_id,
      p_actor_user_id
    );
    v_provider_submit_preflight_ok := COALESCE(NULLIF(v_provider_submit_preflight_result->>'ok', '')::boolean, false);

    IF NOT COALESCE(v_provider_submit_preflight_ok, false) THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', p_pay_batch_id::text,
        'status', (select pb4.status from public.pay_batches pb4 where pb4.id = p_pay_batch_id),
        'code', 'PROVIDER_SUBMIT_PREFLIGHT_BLOCKED',
        'message', 'Provider submission was blocked by final preflight recheck.',
        'provider_submit_preflight_result', COALESCE(v_provider_submit_preflight_result, '{}'::jsonb),
        'transfers', COALESCE(v_transfers, '[]'::jsonb),
        'blocked', COALESCE(v_blocked_reasons, '[]'::jsonb),
        'provider_submission_events_insertable', false,
        'provider_submission_event_payloads', '[]'::jsonb,
        'policy_x_checked', true
      );
    END IF;
  ELSE
    v_provider_submit_preflight_result := jsonb_build_object(
      'ok', true,
      'skipped', true,
      'reason', CASE WHEN v_provider = 'CSV' THEN 'CSV rail does not perform provider API submission.' ELSE 'No pending provider-submit transfer rows.' END
    );
    v_provider_submit_preflight_ok := true;
  END IF;


  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'pay_bank_transfer_id', pbt_event.id::text,
          'provider_key', v_provider,
          'provider_reference', coalesce(
            nullif(btrim(coalesce(pbt_event.rail_tx_id, '')), ''),
            nullif(btrim(coalesce(pbt_event.request_id, '')), ''),
            nullif(btrim(coalesce(pbt_event.payment_reference, '')), '')
          ),
          'provider_state', coalesce(
            nullif(btrim(coalesce(pbt_event.rail_state, '')), ''),
            nullif(btrim(coalesce(pbt_event.status, '')), '')
          ),
          'normalised_state', case
            when upper(btrim(coalesce(pbt_event.status, ''))) IN ('COMPLETED','PAID','SETTLED','SUCCESS','SUCCEEDED')
              or upper(btrim(coalesce(pbt_event.rail_state, ''))) IN ('COMPLETED','PAID','SETTLED','SUCCESS','SUCCEEDED') then 'COMPLETED'
            when upper(btrim(coalesce(pbt_event.status, ''))) in ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED') then 'FAILED'
            when upper(btrim(coalesce(pbt_event.status, ''))) in ('RETURNED','REVERTED') then 'RETURNED'
            when upper(btrim(coalesce(pbt_event.status, ''))) = 'BLOCKED' then 'UNKNOWN'
            else 'PENDING'
          end,
          'event_source', 'PROVIDER_POLL',
          'event_time_utc', now()::text,
          'amount', pbt_event.amount,
          'currency', coalesce(nullif(btrim(coalesce(pbt_event.currency, '')), ''), 'GBP'),
          'raw_payload', jsonb_build_object(
            'source_rpc', 'pay_execute_bank',
            'transfer_group_key', pbt_event.transfer_group_key,
            'grouping_mode_used', pbt_event.grouping_mode_used,
            'pay_channel', pbt_event.pay_channel,
            'request_id', pbt_event.request_id,
            'payment_reference', pbt_event.payment_reference,
            'rail_tx_id', pbt_event.rail_tx_id,
            'rail_state', pbt_event.rail_state,
            'rail_meta_json', coalesce(pbt_event.rail_meta_json, '{}'::jsonb)
          )
        )
      )
      order by pbt_event.pay_channel, pbt_event.week_ending_bucket nulls last, pbt_event.amount desc, pbt_event.id
    ),
    '[]'::jsonb
  )
  into v_provider_submission_event_payloads
  from public.pay_bank_transfers pbt_event
  where pbt_event.pay_batch_id = p_pay_batch_id
    and (
      (v_do_paye = true and pbt_event.pay_channel = 'PAYE')
      or (v_do_umbrella = true and pbt_event.pay_channel = 'UMBRELLA')
      or (v_do_loans = true and pbt_event.pay_channel = 'PAYE')
    )
    and upper(coalesce(pbt_event.status, '')) <> 'BLOCKED';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_EXECUTE_BANK:OK',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'batch_kind_fixed', v_batch_kind_fixed,
        'scope', v_scope,
        'provider', v_provider,
        'env', v_env,
        'pending_count', v_pending_count,
        'blocked_count', v_blocked_count,
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref', v_execution_commit_ref,
        'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
      ),
      'pay_batches',
      p_pay_batch_id::text
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'status', (select pb4.status from public.pay_batches pb4 where pb4.id = p_pay_batch_id),
    'rail_provider_snapshot', v_provider,
    'rail_env_snapshot', v_env,
    'banking_system_snapshot', v_batch.banking_system_snapshot,
    'external_paye_system_snapshot', v_batch.external_paye_system_snapshot,
    'bulk_ref_num', v_bulk_ref_num,
    'bulk_ref_date', case when v_bulk_ref_date is null then null else v_bulk_ref_date::text end,
    'bulk_reference', v_bulk_reference,
    'pending_count', v_pending_count,
    'blocked_count', v_blocked_count,
    'retry_blocked_funds', v_retry_blocked_funds,
    'execution_commit_state', (select pb4.execution_commit_state from public.pay_batches pb4 where pb4.id = p_pay_batch_id),
    'execution_commit_ref', (select pb4.execution_commit_ref from public.pay_batches pb4 where pb4.id = p_pay_batch_id),
    'execution_committed_at_utc', (select case when pb4.execution_committed_at_utc is null then null else pb4.execution_committed_at_utc::text end from public.pay_batches pb4 where pb4.id = p_pay_batch_id),
    'blocked', v_blocked_reasons,
    'provider_submission_events_insertable', COALESCE(v_provider_submit_preflight_ok, true),
    'provider_submit_preflight_result', COALESCE(v_provider_submit_preflight_result, '{}'::jsonb),
    'provider_submission_events_insertable_note', 'Provider submission payloads are emitted only after _pay_batch_provider_submit_preflight_recheck passes.',
    'provider_submission_event_payloads', coalesce(v_provider_submission_event_payloads, '[]'::jsonb),
    'transfers', v_transfers,
    'policy_x_checked', true
  );
end;
$$;





CREATE OR REPLACE FUNCTION public.pay_sync_overpayments_from_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_pay_channel_scope text,
  p_candidate_ids uuid[],
  p_mismatch_choices jsonb default '{}'::jsonb,
  p_client_filter_single uuid default null,
  p_force_include_timesheet_ids uuid[] default null,
  p_exclude_timesheet_ids uuid[] default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_timesheet_case_count int := 0;
  v_cases_inserted int := 0;
  v_cases_touched int := 0;
  v_cases_amended int := 0;
  v_cases_reopened int := 0;
  v_cases_cleared int := 0;
  v_overpayment_case_count int := 0;
  v_underpayment_case_count int := 0;
  v_case_candidates_json jsonb := '[]'::jsonb;
  v_overpayment_json jsonb := '[]'::jsonb;
  v_underpayment_json jsonb := '[]'::jsonb;

  v_target_case_row record;
  v_existing_case_row record;
  v_case_before_json jsonb;
  v_case_after_json jsonb;
  v_components_sync_result jsonb;
  v_existing_recovered_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_selected_finance_case_id uuid;
  v_selected_event_type text;
  v_selected_reason text;
  v_selected_note text;
  v_open_case_candidate record;
  v_target_case_amount_ex numeric(12,2);
  v_case_taxability public.pay_finance_taxability_enum := NULL;
  v_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_case_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_case_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_synced_before_taxability public.pay_finance_taxability_enum := NULL;
  v_synced_before_routing_kind public.pay_finance_routing_kind_enum := NULL;
  v_case_metadata_component_count integer := 0;
  v_synced_open_component_count integer := 0;
  v_taxability_event_before_json jsonb;
  v_taxability_event_after_json jsonb;
begin
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_START',
    jsonb_build_object(
      'pay_date', p_pay_date,
      'week_ending_cutoff', p_week_ending_cutoff,
      'pay_channel_scope', p_pay_channel_scope,
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'force_include_timesheet_count', COALESCE(array_length(p_force_include_timesheet_ids, 1), 0),
      'exclude_timesheet_count', COALESCE(array_length(p_exclude_timesheet_ids, 1), 0)
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_date is null then
    raise exception 'pay_date is required';
  end if;

  if p_week_ending_cutoff is null then
    raise exception 'week_ending_cutoff is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'actor_user_id is required';
  end if;

  if v_scope not in ('PAYE', 'UMBRELLA') then
    raise exception 'Invalid pay_channel_scope (expected PAYE or UMBRELLA)';
  end if;

  create temporary table if not exists pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    client_id uuid null,
    linked_shift_date date null,
    corrected_amount_ex numeric(12,2) not null,
    baseline_signature text null,
    candidate_pay_method text not null,
    case_is_blocked boolean not null,
    needs_lifecycle_tracking boolean not null default false,
    overpayment_amount_ex numeric(12,2) not null,
    underpayment_amount_ex numeric(12,2) not null,
    desired_case_type public.pay_finance_case_type_enum null,
    desired_advance_kind public.pay_advance_kind_enum null,
    desired_reason public.pay_advance_reason_enum null,
    source_original_paid_amount numeric(12,2) null,
    source_corrected_paid_amount numeric(12,2) null,
    components_sync_json jsonb not null default '[]'::jsonb,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_links (
    candidate_id uuid not null,
    timesheet_id uuid not null,
    finance_case_id uuid not null,
    desired_case_type public.pay_finance_case_type_enum not null,
    source_original_paid_amount numeric(12,2) not null,
    source_corrected_paid_amount numeric(12,2) not null,
    case_amount_ex numeric(12,2) not null,
    linked_shift_date date null,
    baseline_signature text null,
    components_sync_json jsonb not null,
    primary key (candidate_id, timesheet_id)
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_sync_case_clears (
    finance_case_id uuid not null primary key,
    candidate_id uuid not null,
    timesheet_id uuid not null,
    old_case_type public.pay_finance_case_type_enum not null,
    old_original_amount numeric(12,2) not null,
    old_outstanding_amount numeric(12,2) not null,
    old_source_original_paid_amount numeric(12,2) null,
    old_source_corrected_paid_amount numeric(12,2) null,
    old_linked_shift_date date null,
    old_baseline_signature text null
  ) on commit drop;

  truncate table pg_temp.tmp_sync_timesheet_case_candidates;
  truncate table pg_temp.tmp_sync_case_links;
  truncate table pg_temp.tmp_sync_case_clears;

  insert into pg_temp.tmp_sync_timesheet_case_candidates (
    candidate_id,
    timesheet_id,
    client_id,
    linked_shift_date,
    corrected_amount_ex,
    baseline_signature,
    candidate_pay_method,
    case_is_blocked,
    needs_lifecycle_tracking,
    overpayment_amount_ex,
    underpayment_amount_ex,
    desired_case_type,
    desired_advance_kind,
    desired_reason,
    source_original_paid_amount,
    source_corrected_paid_amount,
    components_sync_json
  )
  with preview_payload as (
    select public.pay_preview(
      p_pay_date,
      p_week_ending_cutoff,
      p_actor_user_id,
      null::uuid,
      p_client_filter_single
    ) as payload
  ),
  preview_candidates as (
    select cand.value as candidate_json
    from preview_payload pp
    cross join lateral jsonb_array_elements(coalesce(pp.payload->'paye_candidates', '[]'::jsonb)) as cand(value)
    union all
    select cand.value as candidate_json
    from preview_payload pp
    cross join lateral jsonb_array_elements(coalesce(pp.payload->'non_paye_payees', '[]'::jsonb)) as cand(value)
  ),
  candidate_rows as (
    select
      nullif(btrim(coalesce(pc.candidate_json->>'candidate_id', '')), '')::uuid as candidate_id,
      upper(btrim(coalesce(pc.candidate_json->>'current_pay_method', ''))) as candidate_pay_method,
      coalesce(pc.candidate_json->'itemisation', '[]'::jsonb) as itemisation_json
    from preview_candidates pc
    where nullif(btrim(coalesce(pc.candidate_json->>'candidate_id', '')), '') is not null
      and upper(btrim(coalesce(pc.candidate_json->>'current_pay_method', ''))) = v_scope
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or nullif(btrim(coalesce(pc.candidate_json->>'candidate_id', '')), '')::uuid = any(p_candidate_ids)
      )
  ),
  timesheet_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      round(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as corrected_amount_ex,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') = 'TIMESHEET_PAYMENT'
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  active_settled_basis AS (
    SELECT
      distinct_timesheet_rows.timesheet_id,
      active_components.active_settled_component_count,
      active_components.active_settled_amount_ex,
      active_components.active_settled_signature
    FROM (
      SELECT DISTINCT timesheet_item_rows.timesheet_id
      FROM timesheet_item_rows
      WHERE timesheet_item_rows.timesheet_id IS NOT NULL
    ) AS distinct_timesheet_rows
    LEFT JOIN LATERAL (
      SELECT
        count(*)::integer AS active_settled_component_count,
        round(COALESCE(sum(COALESCE(active_settled_rows.amount_ex_vat, 0)), 0), 2)::numeric(12,2) AS active_settled_amount_ex,
        md5(COALESCE(jsonb_agg(
          jsonb_build_object(
            'key_type', active_settled_rows.key_type,
            'key_value', active_settled_rows.key_value,
            'amount_ex_vat', round(COALESCE(active_settled_rows.amount_ex_vat, 0), 2),
            'amount_inc_vat', round(COALESCE(active_settled_rows.amount_inc_vat, 0), 2)
          )
          ORDER BY active_settled_rows.key_type, active_settled_rows.key_value
        )::text, '[]')) AS active_settled_signature
      FROM public._pay_active_settled_components(ARRAY[distinct_timesheet_rows.timesheet_id]::uuid[]) AS active_settled_rows
    ) AS active_components
      ON true
  ),
  timesheet_item_with_baseline as (
    select
      tir.candidate_id,
      tir.timesheet_id,
      tir.client_id,
      coalesce(ts.worked_start_iso::date, ts.scheduled_start_iso::date, ts.week_ending_date) as linked_shift_date,
      tir.corrected_amount_ex,
      case
        when COALESCE(active_settled_basis.active_settled_component_count, 0) > 0
          then active_settled_basis.active_settled_signature
        else coalesce(
          tps.last_settled_signature,
          md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
        )
      end as baseline_signature,
      tir.candidate_pay_method,
      tir.case_is_blocked,
      tir.case_components_json
    from timesheet_item_rows tir
    join public.timesheets ts
      on ts.timesheet_id = tir.timesheet_id
    left join public.timesheet_pay_state tps
      on tps.timesheet_id = tir.timesheet_id
    left join active_settled_basis
      on active_settled_basis.timesheet_id = tir.timesheet_id
  ),
  timesheet_exploded_components as (
    select
      tiwb.candidate_id,
      tiwb.timesheet_id,
      tiwb.client_id,
      tiwb.linked_shift_date,
      tiwb.corrected_amount_ex,
      tiwb.baseline_signature,
      tiwb.candidate_pay_method,
      tiwb.case_is_blocked,
      comp.value as component_json,
      comp.ordinality::integer as component_order,
      round(coalesce(nullif(comp.value->>'component_amount_ex_vat', '')::numeric, 0), 2)::numeric(12,2) as component_amount_ex
    from timesheet_item_with_baseline tiwb
    cross join lateral jsonb_array_elements(coalesce(tiwb.case_components_json, '[]'::jsonb)) with ordinality as comp(value, ordinality)
  ),
  timesheet_case_rollup as (
    select
      tec.candidate_id,
      tec.timesheet_id,
      min(tec.client_id::text)::uuid as client_id,
      min(tec.linked_shift_date) as linked_shift_date,
      min(tec.corrected_amount_ex) as corrected_amount_ex,
      min(tec.baseline_signature) as baseline_signature,
      min(tec.candidate_pay_method) as candidate_pay_method,
      bool_or(tec.case_is_blocked) as case_is_blocked,
      round(coalesce(sum(case when tec.component_amount_ex < 0 then abs(tec.component_amount_ex) else 0 end), 0), 2)::numeric(12,2) as overpayment_amount_ex,
      round(coalesce(sum(case when tec.component_amount_ex > 0 then tec.component_amount_ex else 0 end), 0), 2)::numeric(12,2) as underpayment_amount_ex,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), 'CASE_TOTAL'),
            'component_key_value', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_value', '')), ''), 'TOTAL'),
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN upper(coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), '')) = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), 'CASE_TOTAL'),
                'component_key_value', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_value', '')), ''), 'TOTAL'),
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.component_amount_ex),
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.component_amount_ex < 0),
        '[]'::jsonb
      ) as overpayment_components_json,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'candidate_id', tec.candidate_id::text,
            'client_id', case when tec.client_id is null then null else tec.client_id::text end,
            'linked_timesheet_id', tec.timesheet_id::text,
            'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
            'component_key_type', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), 'CASE_TOTAL'),
            'component_key_value', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_value', '')), ''), 'TOTAL'),
            'classification', CASE
              WHEN upper(btrim(coalesce(tec.component_json->>'classification', ''))) IN ('TAXABLE_CHANNEL_SENSITIVE','REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY')
                THEN upper(btrim(coalesce(tec.component_json->>'classification', '')))
              WHEN upper(coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), '')) = 'EXPENSE_CODE'
                THEN 'REIMBURSEMENT_GROSS_FIXED'
              ELSE 'TAXABLE_CHANNEL_SENSITIVE'
            END,
            'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
            'current_target_pay_method', tec.candidate_pay_method,
            'source_basis_json', CASE
              WHEN jsonb_typeof(tec.component_json->'source_basis_json') = 'object'
                   AND coalesce(tec.component_json->'source_basis_json', '{}'::jsonb) <> '{}'::jsonb
                THEN tec.component_json->'source_basis_json'
              ELSE jsonb_strip_nulls(jsonb_build_object(
                'linked_timesheet_id', tec.timesheet_id::text,
                'source_family_key', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_family_key', '')), ''), 'timesheet:' || tec.timesheet_id::text),
                'component_key_type', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_type', '')), ''), 'CASE_TOTAL'),
                'component_key_value', coalesce(nullif(btrim(coalesce(tec.component_json->>'component_key_value', '')), ''), 'TOTAL'),
                'source_pay_method', coalesce(nullif(btrim(coalesce(tec.component_json->>'source_pay_method', '')), ''), tec.candidate_pay_method),
                'component_amount_ex_vat', abs(tec.component_amount_ex)
              ))
            END,
            'source_amount', abs(tec.component_amount_ex),
            'allocation_priority_group', case when tec.component_json->>'classification' = 'TAXABLE_CHANNEL_SENSITIVE' then 0 else 1 end,
            'allocation_priority_order', tec.component_order
          )
          order by coalesce(tec.component_json->>'classification',''), coalesce(tec.component_json->>'component_key_type',''), coalesce(tec.component_json->>'component_key_value','')
        ) filter (where tec.component_amount_ex > 0),
        '[]'::jsonb
      ) as underpayment_components_json
    from timesheet_exploded_components tec
    group by tec.candidate_id, tec.timesheet_id
  ),
  active_linked_underpayment_cases as (
    select
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      true as has_existing_active_underpayment_case
    from public.pay_advances pa
    where pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
      and pa.linked_timesheet_id is not null
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
    group by pa.candidate_id, pa.linked_timesheet_id
  ),
  timesheet_case_candidates as (
    select
      tcr.candidate_id,
      tcr.timesheet_id,
      tcr.client_id,
      tcr.linked_shift_date,
      tcr.corrected_amount_ex,
      tcr.baseline_signature,
      tcr.candidate_pay_method,
      tcr.case_is_blocked,
      (
        tcr.overpayment_amount_ex > 0
        or (
          tcr.underpayment_amount_ex > 0
          and (
            tcr.case_is_blocked = true
            or coalesce(aluc.has_existing_active_underpayment_case, false) = true
          )
        )
      ) as needs_lifecycle_tracking,
      tcr.overpayment_amount_ex,
      tcr.underpayment_amount_ex,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_finance_case_type_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then 'UNDERPAYMENT'::public.pay_finance_case_type_enum
        else null::public.pay_finance_case_type_enum
      end as desired_case_type,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_kind_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_kind_enum
        else null::public.pay_advance_kind_enum
      end as desired_advance_kind,
      case
        when tcr.overpayment_amount_ex > 0 then 'OVERPAYMENT'::public.pay_advance_reason_enum
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then 'UNDERPAYMENT'::public.pay_advance_reason_enum
        else null::public.pay_advance_reason_enum
      end as desired_reason,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex + tcr.overpayment_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then round(tcr.corrected_amount_ex - tcr.underpayment_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_original_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then round(tcr.corrected_amount_ex, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_corrected_paid_amount,
      case
        when tcr.overpayment_amount_ex > 0 then tcr.overpayment_components_json
        when tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         ) then tcr.underpayment_components_json
        else '[]'::jsonb
      end as components_sync_json,
      1 as candidate_priority
    from timesheet_case_rollup tcr
    left join active_linked_underpayment_cases aluc
      on aluc.candidate_id = tcr.candidate_id
     and aluc.timesheet_id = tcr.timesheet_id
    where tcr.overpayment_amount_ex > 0
       or (
         tcr.underpayment_amount_ex > 0
         and (
           tcr.case_is_blocked = true
           or coalesce(aluc.has_existing_active_underpayment_case, false) = true
         )
       )
  ),
  finance_case_item_rows as (
    select
      cr.candidate_id,
      cr.candidate_pay_method,
      itm.value as item_json,
      nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm.value->>'client_id', '')), '')::uuid as client_id,
      nullif(btrim(coalesce(itm.value->>'linked_shift_date', '')), '')::date as linked_shift_date,
      upper(btrim(coalesce(itm.value->>'case_type', ''))) as case_type_text,
      coalesce(itm.value->>'case_is_blocked', 'false')::boolean as case_is_blocked,
      round(abs(coalesce(nullif(itm.value->>'amount_ex_vat', '')::numeric, 0)), 2)::numeric(12,2) as line_amount_ex,
      coalesce(itm.value->'case_components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation_json, '[]'::jsonb)) as itm(value)
    where coalesce(itm.value->>'line_type', '') in ('OVERPAYMENT_RECOVERY', 'UNDERPAYMENT_PAYMENT')
      and nullif(btrim(coalesce(itm.value->>'finance_case_id', '')), '') is not null
      and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '') is not null
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and nullif(btrim(coalesce(itm.value->>'timesheet_id', '')), '')::uuid = any(p_exclude_timesheet_ids)
      )
  ),
  finance_case_candidates_raw as (
    select
      fcir.candidate_id,
      fcir.timesheet_id,
      coalesce(fcir.client_id, pa.client_id) as client_id,
      coalesce(fcir.linked_shift_date, pa.linked_shift_date) as linked_shift_date,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as corrected_amount_ex,
      pa.baseline_signature,
      fcir.candidate_pay_method,
      fcir.case_is_blocked,
      true as needs_lifecycle_tracking,
      case when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as overpayment_amount_ex,
      case when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) else 0::numeric(12,2) end as underpayment_amount_ex,
      pa.case_type as desired_case_type,
      pa.advance_kind as desired_advance_kind,
      pa.reason as desired_reason,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as source_corrected_paid_amount,
      coalesce(fcir.case_components_json, '[]'::jsonb) as components_sync_json,
      2 as candidate_priority
    from finance_case_item_rows fcir
    join public.pay_advances pa
      on pa.id = fcir.finance_case_id
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id = fcir.timesheet_id
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and round(coalesce(pa.outstanding_amount, 0), 2) > 0
  ),
  combined_case_candidates as (
    select
      tcc.candidate_id,
      tcc.timesheet_id,
      tcc.client_id,
      tcc.linked_shift_date,
      tcc.corrected_amount_ex,
      tcc.baseline_signature,
      tcc.candidate_pay_method,
      tcc.case_is_blocked,
      tcc.needs_lifecycle_tracking,
      tcc.overpayment_amount_ex,
      tcc.underpayment_amount_ex,
      tcc.desired_case_type,
      tcc.desired_advance_kind,
      tcc.desired_reason,
      tcc.source_original_paid_amount,
      tcc.source_corrected_paid_amount,
      tcc.components_sync_json,
      tcc.candidate_priority
    from timesheet_case_candidates tcc

    union all

    select
      fccr.candidate_id,
      fccr.timesheet_id,
      fccr.client_id,
      fccr.linked_shift_date,
      fccr.corrected_amount_ex,
      fccr.baseline_signature,
      fccr.candidate_pay_method,
      fccr.case_is_blocked,
      fccr.needs_lifecycle_tracking,
      fccr.overpayment_amount_ex,
      fccr.underpayment_amount_ex,
      fccr.desired_case_type,
      fccr.desired_advance_kind,
      fccr.desired_reason,
      fccr.source_original_paid_amount,
      fccr.source_corrected_paid_amount,
      fccr.components_sync_json,
      fccr.candidate_priority
    from finance_case_candidates_raw fccr
  ),
  deduped_case_candidates as (
    select
      ccc.candidate_id,
      ccc.timesheet_id,
      ccc.client_id,
      ccc.linked_shift_date,
      ccc.corrected_amount_ex,
      ccc.baseline_signature,
      ccc.candidate_pay_method,
      ccc.case_is_blocked,
      ccc.needs_lifecycle_tracking,
      ccc.overpayment_amount_ex,
      ccc.underpayment_amount_ex,
      ccc.desired_case_type,
      ccc.desired_advance_kind,
      ccc.desired_reason,
      ccc.source_original_paid_amount,
      ccc.source_corrected_paid_amount,
      ccc.components_sync_json
    from (
      select
        ccc_inner.*,
        row_number() over (
          partition by ccc_inner.candidate_id, ccc_inner.timesheet_id
          order by
            ccc_inner.candidate_priority asc,
            case when ccc_inner.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 0 else 1 end,
            case when ccc_inner.needs_lifecycle_tracking then 0 else 1 end
        ) as rn
      from combined_case_candidates ccc_inner
    ) ccc
    where ccc.rn = 1
  )
  select
    dcc.candidate_id,
    dcc.timesheet_id,
    dcc.client_id,
    dcc.linked_shift_date,
    dcc.corrected_amount_ex,
    dcc.baseline_signature,
    dcc.candidate_pay_method,
    dcc.case_is_blocked,
    dcc.needs_lifecycle_tracking,
    dcc.overpayment_amount_ex,
    dcc.underpayment_amount_ex,
    dcc.desired_case_type,
    dcc.desired_advance_kind,
    dcc.desired_reason,
    dcc.source_original_paid_amount,
    dcc.source_corrected_paid_amount,
    dcc.components_sync_json
  from deduped_case_candidates dcc
  where dcc.desired_case_type is not null;

  select count(*)::int into v_timesheet_case_count from pg_temp.tmp_sync_timesheet_case_candidates;
  select count(*)::int into v_overpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;
  select count(*)::int into v_underpayment_case_count from pg_temp.tmp_sync_timesheet_case_candidates where desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'client_id', case when t.client_id is null then null else t.client_id::text end,
        'linked_shift_date', case when t.linked_shift_date is null then null else t.linked_shift_date::text end,
        'baseline_signature', t.baseline_signature,
        'corrected_amount_ex', t.corrected_amount_ex,
        'case_is_blocked', t.case_is_blocked,
        'desired_case_type', case when t.desired_case_type is null then null else t.desired_case_type::text end,
        'needs_lifecycle_tracking', t.needs_lifecycle_tracking,
        'overpayment_amount_ex', t.overpayment_amount_ex,
        'underpayment_amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_case_candidates_json
  from pg_temp.tmp_sync_timesheet_case_candidates t;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.overpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_overpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', t.candidate_id::text,
        'timesheet_id', t.timesheet_id::text,
        'case_type', t.desired_case_type::text,
        'amount_ex', t.underpayment_amount_ex
      )
      order by t.candidate_id::text, t.timesheet_id::text
    ),
    '[]'::jsonb
  ) into v_underpayment_json
  from pg_temp.tmp_sync_timesheet_case_candidates t
  where t.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum;

  for v_target_case_row in
    select
      t.*
    from pg_temp.tmp_sync_timesheet_case_candidates t
    order by t.candidate_id, t.timesheet_id
  loop
    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.overpayment_amount_ex, 2)::numeric(12,2);
    elsif v_target_case_row.desired_case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum then
      v_target_case_amount_ex := round(v_target_case_row.underpayment_amount_ex, 2)::numeric(12,2);
    else
      v_target_case_amount_ex := null;
    end if;

    v_case_taxability := NULL;
    v_case_routing_kind := NULL;
    v_case_metadata_component_count := 0;
    IF v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN
      SELECT
        COUNT(*)::integer,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification = 'TAXABLE_CHANNEL_SENSITIVE', false)) THEN 'TAXABLE'::public.pay_finance_taxability_enum
          WHEN BOOL_AND(COALESCE(normalized_component.classification IN ('REIMBURSEMENT_GROSS_FIXED','NET_PAY_FIXED_RECOVERY'), false)) THEN 'NON_TAXABLE'::public.pay_finance_taxability_enum
          ELSE NULL::public.pay_finance_taxability_enum
        END,
        CASE
          WHEN COUNT(*) = 0 THEN NULL::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          WHEN upper(coalesce(v_target_case_row.candidate_pay_method, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          ELSE NULL::public.pay_finance_routing_kind_enum
        END
      INTO
        v_case_metadata_component_count,
        v_case_taxability,
        v_case_routing_kind
      FROM (
        SELECT
          upper(nullif(btrim(coalesce(component_element.value->>'classification', '')), '')) AS classification,
          upper(nullif(btrim(coalesce(
            component_element.value->>'source_pay_method',
            component_element.value->>'current_target_pay_method',
            v_target_case_row.candidate_pay_method,
            ''
          )), '')) AS source_pay_method
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(v_target_case_row.components_sync_json) = 'array' THEN v_target_case_row.components_sync_json
            ELSE '[]'::jsonb
          END
        ) AS component_element(value)
      ) AS normalized_component;
    END IF;

    select
      pa.id as finance_case_id,
      pa.case_type as old_case_type,
      pa.status as old_status,
      round(coalesce(pa.original_amount, 0), 2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount, 0), 2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount, 0), 2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount, 0), 2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature,
      pa.taxability as old_taxability,
      pa.routing_kind as old_routing_kind,
      pa.written_off_at_utc as old_written_off_at_utc,
      pa.cleared_at_utc as old_cleared_at_utc,
      exists (
        select 1
        from public.pay_finance_case_events sync_safety_events
        where sync_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%RESTRUCT%'
            or upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%MANUAL%'
            or upper(btrim(coalesce(sync_safety_events.event_type, ''))) like '%RESOLUTION%'
          )
      ) as old_has_manual_or_restructure_event
    into v_existing_case_row
    from public.pay_advances pa
    where pa.candidate_id = v_target_case_row.candidate_id
      and pa.linked_timesheet_id = v_target_case_row.timesheet_id
      and pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
    order by
      case when upper(coalesce(pa.status::text,'')) = 'ACTIVE' then 0 else 1 end,
      pa.updated_at desc,
      pa.created_at desc,
      pa.id desc
    limit 1
    for update;

    if v_existing_case_row.finance_case_id is not null
       and (
         v_existing_case_row.old_written_off_at_utc is not null
         or v_existing_case_row.old_cleared_at_utc is not null
         or upper(coalesce(v_existing_case_row.old_status::text,'')) not in ('ACTIVE','PAID_OFF')
         or coalesce(v_existing_case_row.old_has_manual_or_restructure_event, false)
       ) then
      insert into public.pay_finance_case_events (
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_existing_case_row.finance_case_id,
        'SYNC_SKIPPED',
        now(),
        p_actor_user_id,
        null,
        null,
        jsonb_build_object(
          'case_type', v_existing_case_row.old_case_type::text,
          'status', v_existing_case_row.old_status::text,
          'original_amount', v_existing_case_row.old_original_amount,
          'outstanding_amount', v_existing_case_row.old_outstanding_amount,
          'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
          'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
          'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
          'baseline_signature', v_existing_case_row.old_baseline_signature,
          'written_off_at_utc', v_existing_case_row.old_written_off_at_utc,
          'cleared_at_utc', v_existing_case_row.old_cleared_at_utc,
          'has_manual_or_restructure_event', v_existing_case_row.old_has_manual_or_restructure_event
        ),
        jsonb_build_object(
          'sync_skipped', true,
          'target_case_type', case when v_target_case_row.desired_case_type is null then null else v_target_case_row.desired_case_type::text end,
          'target_original_amount', v_target_case_amount_ex,
          'target_source_original_paid_amount', v_target_case_row.source_original_paid_amount,
          'target_source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
          'target_baseline_signature', v_target_case_row.baseline_signature
        ),
        'PREVIEW_FINANCE_SYNC_SKIPPED_PROTECTED_CASE',
        'Skipped overpayment/underpayment preview sync because the existing case is written-off, cleared, closed, manually resolved, or restructured.'
      );

      insert into pg_temp.tmp_sync_case_links (
        candidate_id,
        timesheet_id,
        finance_case_id,
        desired_case_type,
        source_original_paid_amount,
        source_corrected_paid_amount,
        case_amount_ex,
        linked_shift_date,
        baseline_signature,
        components_sync_json
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.timesheet_id,
        v_existing_case_row.finance_case_id,
        v_existing_case_row.old_case_type,
        v_existing_case_row.old_source_original_paid_amount,
        v_existing_case_row.old_source_corrected_paid_amount,
        v_existing_case_row.old_original_amount,
        v_existing_case_row.old_linked_shift_date,
        v_existing_case_row.old_baseline_signature,
        '[]'::jsonb
      )
      on conflict (candidate_id, timesheet_id) do nothing;

      continue;
    end if;

    v_existing_recovered_amount := greatest(coalesce(v_existing_case_row.old_original_amount, 0) - coalesce(v_existing_case_row.old_outstanding_amount, 0), 0);
    v_new_outstanding_amount := greatest(v_target_case_amount_ex - v_existing_recovered_amount, 0)::numeric(12,2);

    if v_existing_case_row.finance_case_id is null then
      insert into public.pay_advances (
        candidate_id,
        client_id,
        case_type,
        advance_kind,
        reason,
        linked_timesheet_id,
        linked_shift_date,
        baseline_signature,
        source_original_paid_amount,
        source_corrected_paid_amount,
        original_amount,
        outstanding_amount,
        status,
        created_by,
        updated_at,
        created_at,
        cleared_at_utc,
        cleared_by_user_id,
        write_off_reason,
        written_off_at_utc,
        written_off_by_user_id,
        taxability,
        routing_kind
      )
      values (
        v_target_case_row.candidate_id,
        v_target_case_row.client_id,
        v_target_case_row.desired_case_type,
        v_target_case_row.desired_advance_kind,
        v_target_case_row.desired_reason,
        v_target_case_row.timesheet_id,
        v_target_case_row.linked_shift_date,
        v_target_case_row.baseline_signature,
        v_target_case_row.source_original_paid_amount,
        v_target_case_row.source_corrected_paid_amount,
        v_target_case_amount_ex,
        v_target_case_amount_ex,
        'ACTIVE'::public.pay_advance_status_enum,
        p_actor_user_id,
        now(),
        now(),
        null,
        null,
        null,
        null,
        null,
        v_case_taxability,
        v_case_routing_kind
      )
      returning id into v_selected_finance_case_id;

      v_cases_inserted := v_cases_inserted + 1;
      v_selected_event_type := 'CREATED';
      v_selected_reason := 'PREVIEW_FINANCE_SYNC';
      v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Created overpayment finance case from component-aware preview sync' else 'Created lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      v_case_before_json := null;
      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'candidate_id', v_target_case_row.candidate_id::text,
        'linked_timesheet_id', v_target_case_row.timesheet_id::text,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature,
        'original_amount', v_target_case_amount_ex,
        'outstanding_amount', v_target_case_amount_ex,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
        'routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
        'status', 'ACTIVE'
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (v_case_taxability IS NOT NULL OR v_case_routing_kind IS NOT NULL) THEN jsonb_build_object(
          'before_taxability', null,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', null,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    else
      v_case_before_json := jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', v_existing_case_row.old_status::text,
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
        'routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      )
      || CASE
        WHEN v_existing_case_row.old_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        )
        ELSE '{}'::jsonb
      END;

      update public.pay_advances pa
      set
        client_id = v_target_case_row.client_id,
        case_type = v_target_case_row.desired_case_type,
        advance_kind = v_target_case_row.desired_advance_kind,
        reason = v_target_case_row.desired_reason,
        linked_shift_date = v_target_case_row.linked_shift_date,
        baseline_signature = v_target_case_row.baseline_signature,
        source_original_paid_amount = v_target_case_row.source_original_paid_amount,
        source_corrected_paid_amount = v_target_case_row.source_corrected_paid_amount,
        original_amount = v_target_case_amount_ex,
        outstanding_amount = v_new_outstanding_amount,
        status = case when v_new_outstanding_amount > 0 then 'ACTIVE'::public.pay_advance_status_enum else 'PAID_OFF'::public.pay_advance_status_enum end,
        cleared_at_utc = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_at_utc, now()) end,
        cleared_by_user_id = case when v_new_outstanding_amount > 0 then null else coalesce(pa.cleared_by_user_id, p_actor_user_id) end,
        taxability = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_taxability
          else pa.taxability
        end,
        routing_kind = case
          when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum and v_case_metadata_component_count > 0 then v_case_routing_kind
          else pa.routing_kind
        end,
        updated_at = now()
      where pa.id = v_existing_case_row.finance_case_id;

      v_selected_finance_case_id := v_existing_case_row.finance_case_id;
      v_cases_touched := v_cases_touched + 1;

      if upper(coalesce(v_existing_case_row.old_status::text,'')) = 'PAID_OFF' and v_new_outstanding_amount > 0 then
        v_cases_reopened := v_cases_reopened + 1;
        v_selected_event_type := 'REOPENED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Reopened overpayment finance case from component-aware preview sync' else 'Reopened lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      else
        if v_existing_case_row.old_case_type is distinct from v_target_case_row.desired_case_type
           or v_existing_case_row.old_original_amount is distinct from v_target_case_amount_ex
           or v_existing_case_row.old_outstanding_amount is distinct from v_new_outstanding_amount
           or v_existing_case_row.old_source_original_paid_amount is distinct from v_target_case_row.source_original_paid_amount
           or v_existing_case_row.old_source_corrected_paid_amount is distinct from v_target_case_row.source_corrected_paid_amount
           or (
             v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
             and v_case_metadata_component_count > 0
             and v_existing_case_row.old_taxability is distinct from v_case_taxability
           )
           or (
             v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
             and v_case_metadata_component_count > 0
             and v_existing_case_row.old_routing_kind is distinct from v_case_routing_kind
           )
           or v_existing_case_row.old_linked_shift_date is distinct from v_target_case_row.linked_shift_date
           or v_existing_case_row.old_baseline_signature is distinct from v_target_case_row.baseline_signature then
          v_cases_amended := v_cases_amended + 1;
        end if;
        v_selected_event_type := 'AMENDED';
        v_selected_reason := 'PREVIEW_FINANCE_SYNC';
        v_selected_note := case when v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then 'Amended overpayment finance case from component-aware preview sync' else 'Amended lifecycle-tracked underpayment finance case from component-aware preview sync' end;
      end if;

      v_case_after_json := jsonb_build_object(
        'case_type', v_target_case_row.desired_case_type::text,
        'status', case when v_new_outstanding_amount > 0 then 'ACTIVE' else 'PAID_OFF' end,
        'original_amount', v_target_case_amount_ex,
        'outstanding_amount', v_new_outstanding_amount,
        'source_original_paid_amount', v_target_case_row.source_original_paid_amount,
        'source_corrected_paid_amount', v_target_case_row.source_corrected_paid_amount,
        'taxability', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END
          ELSE CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END
        END,
        'routing_kind', CASE
          WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum AND v_case_metadata_component_count > 0 THEN CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END
          ELSE CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END
        END,
        'linked_shift_date', case when v_target_case_row.linked_shift_date is null then null else v_target_case_row.linked_shift_date::text end,
        'baseline_signature', v_target_case_row.baseline_signature
      )
      || CASE
        WHEN v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
         AND v_case_metadata_component_count > 0
         AND (
           v_existing_case_row.old_taxability IS DISTINCT FROM v_case_taxability
           OR v_existing_case_row.old_routing_kind IS DISTINCT FROM v_case_routing_kind
         ) THEN jsonb_build_object(
          'before_taxability', CASE WHEN v_existing_case_row.old_taxability IS NULL THEN NULL ELSE v_existing_case_row.old_taxability::text END,
          'after_taxability', CASE WHEN v_case_taxability IS NULL THEN NULL ELSE v_case_taxability::text END,
          'before_routing_kind', CASE WHEN v_existing_case_row.old_routing_kind IS NULL THEN NULL ELSE v_existing_case_row.old_routing_kind::text END,
          'after_routing_kind', CASE WHEN v_case_routing_kind IS NULL THEN NULL ELSE v_case_routing_kind::text END,
          'inferred_from_open_components', true
        )
        ELSE '{}'::jsonb
      END;
    end if;

    insert into pg_temp.tmp_sync_case_links (
      candidate_id,
      timesheet_id,
      finance_case_id,
      desired_case_type,
      source_original_paid_amount,
      source_corrected_paid_amount,
      case_amount_ex,
      linked_shift_date,
      baseline_signature,
      components_sync_json
    )
    values (
      v_target_case_row.candidate_id,
      v_target_case_row.timesheet_id,
      v_selected_finance_case_id,
      v_target_case_row.desired_case_type,
      v_target_case_row.source_original_paid_amount,
      v_target_case_row.source_corrected_paid_amount,
      v_target_case_amount_ex,
      v_target_case_row.linked_shift_date,
      v_target_case_row.baseline_signature,
      v_target_case_row.components_sync_json
    )
    on conflict (candidate_id, timesheet_id) do update
    set
      finance_case_id = excluded.finance_case_id,
      desired_case_type = excluded.desired_case_type,
      source_original_paid_amount = excluded.source_original_paid_amount,
      source_corrected_paid_amount = excluded.source_corrected_paid_amount,
      case_amount_ex = excluded.case_amount_ex,
      linked_shift_date = excluded.linked_shift_date,
      baseline_signature = excluded.baseline_signature,
      components_sync_json = excluded.components_sync_json;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_selected_finance_case_id,
      v_selected_event_type,
      now(),
      p_actor_user_id,
      null,
      null,
      v_case_before_json,
      v_case_after_json,
      v_selected_reason,
      v_selected_note
    );
  end loop;

  for v_open_case_candidate in
    select
      pa.id as finance_case_id,
      pa.candidate_id,
      pa.linked_timesheet_id as timesheet_id,
      pa.case_type as old_case_type,
      round(coalesce(pa.original_amount,0),2)::numeric(12,2) as old_original_amount,
      round(coalesce(pa.outstanding_amount,0),2)::numeric(12,2) as old_outstanding_amount,
      round(coalesce(pa.source_original_paid_amount,0),2)::numeric(12,2) as old_source_original_paid_amount,
      round(coalesce(pa.source_corrected_paid_amount,0),2)::numeric(12,2) as old_source_corrected_paid_amount,
      pa.linked_shift_date as old_linked_shift_date,
      pa.baseline_signature as old_baseline_signature
    from public.pay_advances pa
    where pa.case_type in ('OVERPAYMENT'::public.pay_finance_case_type_enum, 'UNDERPAYMENT'::public.pay_finance_case_type_enum)
      and pa.linked_timesheet_id is not null
      and (
        coalesce(array_length(p_candidate_ids, 1), 0) = 0
        or pa.candidate_id = any(p_candidate_ids)
      )
      and (
        p_client_filter_single is null
        or pa.client_id = p_client_filter_single
      )
      and (
        coalesce(array_length(p_force_include_timesheet_ids, 1), 0) = 0
        or pa.linked_timesheet_id = any(p_force_include_timesheet_ids)
        or p_force_include_timesheet_ids is null
      )
      and not (
        coalesce(array_length(p_exclude_timesheet_ids, 1), 0) > 0
        and pa.linked_timesheet_id = any(p_exclude_timesheet_ids)
      )
      and not exists (
        select 1
        from pg_temp.tmp_sync_case_links l
        where l.finance_case_id = pa.id
      )
      and exists (
        select 1
        from public.candidates c
        where c.id = pa.candidate_id
          and upper(coalesce(c.pay_method,'')) = v_scope
      )
      and upper(coalesce(pa.status::text, '')) = 'ACTIVE'
      and pa.written_off_at_utc is null
      and pa.cleared_at_utc is null
      and not exists (
        select 1
        from public.pay_finance_case_events sync_clear_safety_events
        where sync_clear_safety_events.finance_case_id = pa.id
          and (
            upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%WRITE%OFF%'
            or upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%RESTRUCT%'
            or upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%MANUAL%'
            or upper(btrim(coalesce(sync_clear_safety_events.event_type, ''))) like '%RESOLUTION%'
          )
      )
      and not exists (
        select 1
        from public.pay_item_snoozes pis
        where pis.source_ref = ('advance:' || pa.id::text)
          and pis.cleared_at_utc is null
      )
  loop
    insert into pg_temp.tmp_sync_case_clears (
      finance_case_id,
      candidate_id,
      timesheet_id,
      old_case_type,
      old_original_amount,
      old_outstanding_amount,
      old_source_original_paid_amount,
      old_source_corrected_paid_amount,
      old_linked_shift_date,
      old_baseline_signature
    )
    values (
      v_open_case_candidate.finance_case_id,
      v_open_case_candidate.candidate_id,
      v_open_case_candidate.timesheet_id,
      v_open_case_candidate.old_case_type,
      v_open_case_candidate.old_original_amount,
      v_open_case_candidate.old_outstanding_amount,
      v_open_case_candidate.old_source_original_paid_amount,
      v_open_case_candidate.old_source_corrected_paid_amount,
      v_open_case_candidate.old_linked_shift_date,
      v_open_case_candidate.old_baseline_signature
    )
    on conflict (finance_case_id) do nothing;
  end loop;

  for v_existing_case_row in
    select *
    from pg_temp.tmp_sync_case_clears
    order by candidate_id, timesheet_id, finance_case_id
  loop
    update public.pay_advances pa
    set
      status = 'PAID_OFF'::public.pay_advance_status_enum,
      outstanding_amount = 0,
      cleared_at_utc = coalesce(pa.cleared_at_utc, now()),
      cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id),
      updated_at = now()
    where pa.id = v_existing_case_row.finance_case_id;

    insert into public.pay_finance_case_events (
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_existing_case_row.finance_case_id,
      'CLEARED',
      now(),
      p_actor_user_id,
      null,
      null,
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'ACTIVE',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', v_existing_case_row.old_outstanding_amount,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      jsonb_build_object(
        'case_type', v_existing_case_row.old_case_type::text,
        'status', 'PAID_OFF',
        'original_amount', v_existing_case_row.old_original_amount,
        'outstanding_amount', 0,
        'source_original_paid_amount', v_existing_case_row.old_source_original_paid_amount,
        'source_corrected_paid_amount', v_existing_case_row.old_source_corrected_paid_amount,
        'linked_shift_date', case when v_existing_case_row.old_linked_shift_date is null then null else v_existing_case_row.old_linked_shift_date::text end,
        'baseline_signature', v_existing_case_row.old_baseline_signature
      ),
      'PREVIEW_FINANCE_SYNC',
      'Cleared finance case because the current preview no longer requires a persistent lifecycle-tracked overpayment/underpayment header'
    );

    perform public.pay_finance_components_sync_from_preview(
      v_existing_case_row.finance_case_id,
      '[]'::jsonb,
      p_actor_user_id
    );

    v_cases_cleared := v_cases_cleared + 1;
  end loop;

  for v_target_case_row in
    select l.*
    from pg_temp.tmp_sync_case_links l
    order by l.candidate_id, l.timesheet_id
  loop
    v_components_sync_result := public.pay_finance_components_sync_from_preview(
      v_target_case_row.finance_case_id,
      v_target_case_row.components_sync_json,
      p_actor_user_id
    );

    if v_target_case_row.desired_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_synced_open_component_count := 0;
      v_synced_case_taxability := NULL;
      v_synced_case_routing_kind := NULL;

      select
        pa.taxability,
        pa.routing_kind
      into
        v_synced_before_taxability,
        v_synced_before_routing_kind
      from public.pay_advances pa
      where pa.id = v_target_case_row.finance_case_id
      limit 1;

      select
        count(*)::integer,
        case
          when count(*) = 0 then null::public.pay_finance_taxability_enum
          when bool_and(pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) then 'TAXABLE'::public.pay_finance_taxability_enum
          when bool_and(pfc.classification in (
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
          )) then 'NON_TAXABLE'::public.pay_finance_taxability_enum
          else null::public.pay_finance_taxability_enum
        end,
        case
          when count(*) = 0 then null::public.pay_finance_routing_kind_enum
          when v_scope = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
          when v_scope = 'UMBRELLA' then 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
          else null::public.pay_finance_routing_kind_enum
        end
      into
        v_synced_open_component_count,
        v_synced_case_taxability,
        v_synced_case_routing_kind
      from public.pay_finance_case_components pfc
      where pfc.finance_case_id = v_target_case_row.finance_case_id
        and pfc.closed_at_utc is null
        and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

      if v_synced_open_component_count > 0
         and (v_synced_before_taxability is distinct from v_synced_case_taxability
              or v_synced_before_routing_kind is distinct from v_synced_case_routing_kind) then
        v_taxability_event_before_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end
        );

        v_taxability_event_after_json := jsonb_build_object(
          'case_type', 'OVERPAYMENT',
          'taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'before_taxability', case when v_synced_before_taxability is null then null else v_synced_before_taxability::text end,
          'after_taxability', case when v_synced_case_taxability is null then null else v_synced_case_taxability::text end,
          'before_routing_kind', case when v_synced_before_routing_kind is null then null else v_synced_before_routing_kind::text end,
          'after_routing_kind', case when v_synced_case_routing_kind is null then null else v_synced_case_routing_kind::text end,
          'inferred_from_open_components', true
        );

        update public.pay_advances pa
        set
          taxability = v_synced_case_taxability,
          routing_kind = v_synced_case_routing_kind,
          updated_at = now()
        where pa.id = v_target_case_row.finance_case_id;

        insert into public.pay_finance_case_events (
          finance_case_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        values (
          v_target_case_row.finance_case_id,
          case
            when v_synced_before_taxability is distinct from v_synced_case_taxability
             and v_synced_before_routing_kind is distinct from v_synced_case_routing_kind then 'HEADER_METADATA_INFERRED'
            when v_synced_before_taxability is distinct from v_synced_case_taxability then 'TAXABILITY_INFERRED'
            else 'ROUTING_KIND_INFERRED'
          end,
          now(),
          p_actor_user_id,
          null,
          null,
          v_taxability_event_before_json,
          v_taxability_event_after_json,
          'PREVIEW_FINANCE_SYNC',
          'Inferred overpayment taxability/routing metadata from open finance case components after component sync'
        );
      end if;
    end if;
  end loop;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'pay_channel_scope', v_scope,
      'overpayment_case_count', v_overpayment_case_count,
      'underpayment_case_count', v_underpayment_case_count,
      'cases_inserted', v_cases_inserted,
      'cases_touched', v_cases_touched,
      'cases_amended', v_cases_amended,
      'cases_reopened', v_cases_reopened,
      'cases_cleared', v_cases_cleared
    ),
    'pay_sync_overpayments',
    COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'pay_channel_scope', v_scope,
    'negative_preview_timesheets_count', v_overpayment_case_count,
    'negative_preview_timesheets', v_overpayment_json,
    'underpayment_case_count', v_underpayment_case_count,
    'underpayment_cases', v_underpayment_json,
    'timesheet_finance_case_candidates_count', v_timesheet_case_count,
    'timesheet_finance_case_candidates', v_case_candidates_json,
    'cases_inserted', v_cases_inserted,
    'cases_touched', v_cases_touched,
    'cases_amended', v_cases_amended,
    'cases_reopened', v_cases_reopened,
    'cases_cleared', v_cases_cleared
  );
exception
  when others then
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SYNC_OVERPAYMENTS_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'pay_date', p_pay_date,
        'week_ending_cutoff', p_week_ending_cutoff,
        'pay_channel_scope', p_pay_channel_scope,
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_sync_overpayments',
      COALESCE(p_pay_date::text, 'NO_PAY_DATE'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$$;






CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_ensure_run(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
  v_effective_week_ending_cutoff date := DATE '9999-12-31';
  v_pay_eligibility_months_back integer := 6;
  v_pay_eligibility_weeks_ahead integer := 2;
  v_pay_week_start date;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_snapshot_run_id uuid;
  v_status text;
  v_is_active boolean;
  v_was_created boolean := false;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_error_json jsonb := '{}'::jsonb;
  v_error_message text := NULL;
  v_error_sqlstate text := NULL;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  v_pay_week_start := public._pay_week_start_monday(p_pay_date);

  BEGIN
    SELECT
      sd.pay_eligibility_months_back,
      sd.pay_eligibility_weeks_ahead
    INTO
      v_pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead
    FROM public.settings_defaults AS sd
    ORDER BY sd.id ASC
    LIMIT 1;
  EXCEPTION
    WHEN undefined_column THEN
      v_pay_eligibility_months_back := 6;
      v_pay_eligibility_weeks_ahead := 2;
  END;

  v_pay_eligibility_months_back := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_months_back, 6), 120));
  v_pay_eligibility_weeks_ahead := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_weeks_ahead, 2), 52));

  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;

  SELECT
    sr.id,
    sr.status,
    sr.is_active
  INTO
    v_snapshot_run_id,
    v_status,
    v_is_active
  FROM public.banking_pay_snapshot_runs AS sr
  WHERE sr.pay_date = p_pay_date
    AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
    AND sr.is_active = true
  ORDER BY sr.created_at_utc DESC, sr.id DESC
  LIMIT 1;

  IF v_snapshot_run_id IS NULL THEN
    BEGIN
      INSERT INTO public.banking_pay_snapshot_runs (
        pay_date,
        week_ending_cutoff,
        pay_week_start,
        eligibility_from_date,
        eligibility_to_date,
        status,
        is_active,
        summary_json,
        paye_guardrails_json,
        created_at_utc,
        updated_at_utc,
        ready_at_utc,
        failed_at_utc,
        last_error_json
      )
      VALUES (
        p_pay_date,
        v_effective_week_ending_cutoff,
        v_pay_week_start,
        v_eligibility_from_date,
        v_eligibility_to_date,
        'OPEN',
        true,
        '{}'::jsonb,
        '{}'::jsonb,
        v_now,
        v_now,
        NULL,
        NULL,
        NULL
      )
      RETURNING
        public.banking_pay_snapshot_runs.id,
        public.banking_pay_snapshot_runs.status,
        public.banking_pay_snapshot_runs.is_active
      INTO
        v_snapshot_run_id,
        v_status,
        v_is_active;

      v_was_created := true;
    EXCEPTION
      WHEN unique_violation THEN
        SELECT
          sr.id,
          sr.status,
          sr.is_active
        INTO
          v_snapshot_run_id,
          v_status,
          v_is_active
        FROM public.banking_pay_snapshot_runs AS sr
        WHERE sr.pay_date = p_pay_date
          AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
          AND sr.is_active = true
        ORDER BY sr.created_at_utc DESC, sr.id DESC
        LIMIT 1;

        v_was_created := false;
      WHEN exclusion_violation THEN
        SELECT
          sr.id,
          sr.status,
          sr.is_active
        INTO
          v_snapshot_run_id,
          v_status,
          v_is_active
        FROM public.banking_pay_snapshot_runs AS sr
        WHERE sr.pay_date = p_pay_date
          AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
          AND sr.is_active = true
        ORDER BY sr.created_at_utc DESC, sr.id DESC
        LIMIT 1;

        v_was_created := false;
    END;
  END IF;

  IF v_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'Unable to create or reuse active banking pay snapshot run for pay_date % and cutoff %', p_pay_date, v_effective_week_ending_cutoff;
  END IF;

  v_audit_after_json := jsonb_build_object(
    'id', v_snapshot_run_id::text,
    'pay_date', p_pay_date::text,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'pay_week_start', v_pay_week_start::text,
    'eligibility_from_date', v_eligibility_from_date::text,
    'eligibility_to_date', v_eligibility_to_date::text,
    'status', v_status,
    'is_active', v_is_active
  );

  IF v_was_created THEN
    PERFORM public._audit_insert(
      'banking_pay_snapshot_run',
      v_snapshot_run_id::text,
      'CREATED',
      NULL,
      v_audit_after_json,
      'SNAPSHOT_RUN_CREATED_OR_REUSED',
      p_actor_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', v_snapshot_run_id::text,
    'pay_date', p_pay_date::text,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'pay_week_start', v_pay_week_start::text,
    'eligibility_from_date', v_eligibility_from_date::text,
    'eligibility_to_date', v_eligibility_to_date::text,
    'status', v_status,
    'is_active', v_is_active,
    'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
    'created_or_reused_at_utc', v_now
  );
EXCEPTION
  WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
      v_error_message = MESSAGE_TEXT,
      v_error_sqlstate = RETURNED_SQLSTATE;

    IF v_snapshot_run_id IS NOT NULL THEN
      v_error_json := jsonb_build_object(
        'sqlstate', v_error_sqlstate,
        'message', v_error_message,
        'failed_at_utc', v_now
      );

      UPDATE public.banking_pay_snapshot_runs AS sr
      SET updated_at_utc = v_now,
          failed_at_utc = v_now,
          last_error_json = v_error_json
      WHERE sr.id = v_snapshot_run_id;

      PERFORM public._audit_insert(
        'banking_pay_snapshot_run',
        v_snapshot_run_id::text,
        'FAILED',
        NULL,
        jsonb_build_object(
          'id', v_snapshot_run_id::text,
          'pay_date', p_pay_date::text,
          'week_ending_cutoff', v_effective_week_ending_cutoff::text,
          'pay_week_start', v_pay_week_start::text,
          'eligibility_from_date', v_eligibility_from_date::text,
          'eligibility_to_date', v_eligibility_to_date::text,
          'status', v_status,
          'is_active', v_is_active,
          'last_error_json', v_error_json
        ),
        'SNAPSHOT_RUN_IMMEDIATE_FAILURE',
        p_actor_user_id
      );
    END IF;

    RAISE;
END;
$function$;





CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_candidate_refresh(p_snapshot_run_id uuid, p_candidate_id uuid, p_reason text DEFAULT NULL::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_live_change_seq bigint := 0;
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
BEGIN
  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.banking_pay_snapshot_runs sr
  WHERE sr.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates c
  WHERE c.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  SELECT COALESCE(acc.seq, 0)
  INTO v_live_change_seq
  FROM public.app_change_counters acc
  WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_dedupe_key := 'SNAPSHOT_CANDIDATE_REFRESH:' || p_snapshot_run_id::text || ':' || p_candidate_id::text || ':s' || v_live_change_seq::text || ':pv' || v_required_projection_version::text || ':ht' || v_required_hidden_recovery_template_projection_version::text;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    'SNAPSHOT_CANDIDATE_REFRESH',
    'QUEUED',
    50,
    v_now,
    0,
    8,
    v_dedupe_key,
    p_snapshot_run_id,
    NULL,
    p_candidate_id,
    COALESCE(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'reason', p_reason,
        'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'snapshot_run_id', p_snapshot_run_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', v_live_change_seq,
        'projection_version', v_required_projection_version,
        'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
        'refresh_reason', COALESCE(NULLIF(BTRIM(COALESCE(p_payload_json->>'refresh_reason', '')), ''), p_reason),
        'job_type', 'SNAPSHOT_CANDIDATE_REFRESH'
      ),
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = public._pay_workbench_merge_targeted_scope_payload(
        COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb),
        COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
      ),
      updated_at_utc = v_now
  RETURNING public.banking_pay_workbench_jobs.id, public.banking_pay_workbench_jobs.status, (xmax = 0)
  INTO v_job_id, v_job_status, v_job_was_inserted;

  INSERT INTO public.banking_pay_snapshot_candidate_state (
    snapshot_run_id,
    candidate_id,
    status,
    candidate_fragment_json,
    summary_fragment_json,
    paye_candidate_json,
    non_paye_payee_json,
    payees_json,
    case_resolution_states_json,
    canonical_preview_lines_json,
    source_change_seq,
    created_at_utc,
    updated_at_utc,
    last_refreshed_at_utc,
    last_error_json
  )
  VALUES (
    p_snapshot_run_id,
    p_candidate_id,
    'PENDING',
    '{}'::jsonb,
    '{}'::jsonb,
    NULL,
    NULL,
    '[]'::jsonb,
    '[]'::jsonb,
    '[]'::jsonb,
    v_live_change_seq,
    v_now,
    v_now,
    NULL,
    NULL
  )
  ON CONFLICT (snapshot_run_id, candidate_id)
  DO UPDATE
  SET status = 'PENDING',
      source_change_seq = GREATEST(public.banking_pay_snapshot_candidate_state.source_change_seq, EXCLUDED.source_change_seq),
      updated_at_utc = v_now,
      last_error_json = NULL;

  UPDATE public.banking_pay_workbench_session_candidate_state scs
  SET status = 'PENDING',
      effective_candidate_fragment_json = '{}'::jsonb,
      effective_summary_fragment_json = '{}'::jsonb,
      effective_paye_candidate_json = NULL,
      effective_non_paye_payee_json = NULL,
      effective_payees_json = '[]'::jsonb,
      effective_case_resolution_states_json = '[]'::jsonb,
      effective_canonical_preview_lines_json = '[]'::jsonb,
      source_change_seq = GREATEST(scs.source_change_seq, v_live_change_seq),
      pending_job_id = v_job_id,
      updated_at_utc = v_now,
      last_recomputed_at_utc = NULL,
      last_error_json = NULL
  FROM public.banking_pay_workbench_sessions ws
  WHERE ws.id = scs.session_id
    AND ws.status = 'OPEN'
    AND ws.source_snapshot_run_id = p_snapshot_run_id
    AND scs.candidate_id = p_candidate_id
    AND ws.scope_candidate_ids @> ARRAY[p_candidate_id]::uuid[];

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', 'SNAPSHOT_CANDIDATE_REFRESH',
      'status', v_job_status,
      'snapshot_run_id', p_snapshot_run_id::text,
      'candidate_id', p_candidate_id::text,
      'dedupe_key', v_dedupe_key,
      'source_change_seq', v_live_change_seq,
      'projection_version', v_required_projection_version,
      'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version
    ),
    'WORKBENCH_JOB_ENQUEUE',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', 'SNAPSHOT_CANDIDATE_REFRESH',
    'snapshot_run_id', p_snapshot_run_id::text,
    'candidate_id', p_candidate_id::text,
    'source_change_seq', v_live_change_seq,
    'projection_version', v_required_projection_version,
    'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
    'dedupe_key', v_dedupe_key,
    'reason', p_reason
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_session_candidate_refresh(
  p_session_id uuid,
  p_candidate_id uuid,
  p_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_version bigint;
  v_source_snapshot_run_id uuid;
  v_session_status text;
  v_source_change_seq bigint := 0;
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_existing_session_candidate_status text := NULL;
  v_existing_session_candidate_source_change_seq bigint := 0;
  v_existing_session_candidate_session_version bigint := 0;
  v_existing_session_candidate_pending_job_id uuid := NULL;
  v_existing_job_id uuid := NULL;
  v_existing_job_status text := NULL;
  v_existing_job_source_change_seq bigint := 0;
  v_existing_job_session_version bigint := 0;
  v_existing_job_projection_version integer := 0;
  v_existing_job_hidden_recovery_template_projection_version integer := 0;
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_snapshot_candidate_status text := NULL;
  v_snapshot_candidate_source_change_seq bigint := 0;
  v_snapshot_candidate_projection_version integer := 0;
  v_snapshot_candidate_hidden_recovery_template_projection_version integer := 0;
  v_snapshot_candidate_last_refreshed_at_utc timestamptz := NULL;
  v_snapshot_has_hidden_recovery_templates boolean := false;
  v_existing_session_candidate_projection_version integer := 0;
  v_existing_session_candidate_hidden_recovery_template_projection_version integer := 0;
  v_existing_session_candidate_last_recomputed_at_utc timestamptz := NULL;
  v_session_has_hidden_recovery_templates boolean := false;
  v_session_missing_snapshot_hidden_manual_debt_template boolean := false;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  SELECT ws.version, ws.source_snapshot_run_id, ws.status
  INTO v_session_version, v_source_snapshot_run_id, v_session_status
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = p_session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  PERFORM 1
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = p_session_id
    AND ws.scope_candidate_ids @> ARRAY[p_candidate_id]::uuid[];

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  SELECT
    COALESCE(snap.status, NULL),
    COALESCE(snap.source_change_seq, 0),
    COALESCE(
      CASE
        WHEN COALESCE(snap.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
          THEN (snap.candidate_fragment_json->>'projection_version')::integer
        ELSE NULL::integer
      END,
      0
    ),
    COALESCE(
      CASE
        WHEN COALESCE(snap.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
          THEN (snap.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
        ELSE NULL::integer
      END,
      0
    ),
    snap.last_refreshed_at_utc,
    COALESCE(
      jsonb_array_length(
        CASE
          WHEN jsonb_typeof(snap.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(snap.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ),
      0
    ) > 0
  INTO v_snapshot_candidate_status,
       v_snapshot_candidate_source_change_seq,
       v_snapshot_candidate_projection_version,
       v_snapshot_candidate_hidden_recovery_template_projection_version,
       v_snapshot_candidate_last_refreshed_at_utc,
       v_snapshot_has_hidden_recovery_templates
  FROM public.banking_pay_snapshot_candidate_state AS snap
  WHERE snap.snapshot_run_id = v_source_snapshot_run_id
    AND snap.candidate_id = p_candidate_id;

  v_source_change_seq := v_snapshot_candidate_source_change_seq;

  IF v_source_change_seq = 0 THEN
    SELECT COALESCE(acc.seq, 0)
    INTO v_source_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  SELECT COALESCE(scs.status, NULL),
         COALESCE(scs.source_change_seq, 0),
         COALESCE(scs.session_version, 0),
         scs.pending_job_id,
         COALESCE(
           CASE
             WHEN COALESCE(scs.effective_candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
               THEN (scs.effective_candidate_fragment_json->>'projection_version')::integer
             ELSE NULL::integer
           END,
           0
         ),
         COALESCE(
           CASE
             WHEN COALESCE(scs.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
               THEN (scs.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
             ELSE NULL::integer
           END,
           0
         ),
         scs.last_recomputed_at_utc,
         COALESCE(
           jsonb_array_length(
             CASE
               WHEN jsonb_typeof(scs.effective_candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(scs.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
               ELSE '[]'::jsonb
             END
           ),
           0
         ) > 0
  INTO v_existing_session_candidate_status,
       v_existing_session_candidate_source_change_seq,
       v_existing_session_candidate_session_version,
       v_existing_session_candidate_pending_job_id,
       v_existing_session_candidate_projection_version,
       v_existing_session_candidate_hidden_recovery_template_projection_version,
       v_existing_session_candidate_last_recomputed_at_utc,
       v_session_has_hidden_recovery_templates
  FROM public.banking_pay_workbench_session_candidate_state AS scs
  WHERE scs.session_id = p_session_id
    AND scs.candidate_id = p_candidate_id
  LIMIT 1;

  SELECT j.id,
         j.status,
         COALESCE(
           CASE
             WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
               THEN (j.payload_json->>'source_change_seq')::bigint
             ELSE 0::bigint
           END,
           0::bigint
         ),
         COALESCE(
           CASE
             WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
               THEN (j.payload_json->>'session_version')::bigint
             ELSE 0::bigint
           END,
           0::bigint
         ),
         COALESCE(
           CASE
             WHEN COALESCE(j.payload_json->>'projection_version', '') ~ '^[0-9]+$'
               THEN (j.payload_json->>'projection_version')::integer
             ELSE 0::integer
           END,
           0::integer
         ),
         COALESCE(
           CASE
             WHEN COALESCE(j.payload_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
               THEN (j.payload_json->>'hidden_recovery_template_projection_version')::integer
             ELSE 0::integer
           END,
           0::integer
         )
  INTO v_existing_job_id,
       v_existing_job_status,
       v_existing_job_source_change_seq,
       v_existing_job_session_version,
       v_existing_job_projection_version,
       v_existing_job_hidden_recovery_template_projection_version
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.session_id = p_session_id
    AND j.candidate_id = p_candidate_id
    AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
    AND j.status IN ('QUEUED', 'RUNNING')
  ORDER BY COALESCE(
             CASE
               WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                 THEN (j.payload_json->>'session_version')::bigint
               ELSE 0::bigint
             END,
             0::bigint
           ) DESC,
           COALESCE(
             CASE
               WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                 THEN (j.payload_json->>'source_change_seq')::bigint
               ELSE 0::bigint
             END,
             0::bigint
           ) DESC,
           j.updated_at_utc DESC NULLS LAST,
           j.created_at_utc DESC NULLS LAST,
           j.id DESC
  LIMIT 1;

  SELECT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(snap.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(snap.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
               ELSE '[]'::jsonb
             END
           ) AS snap_tpl(value)
           WHERE jsonb_typeof(snap_tpl.value) = 'object'
             AND UPPER(COALESCE(snap_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
             AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
             AND NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(
                 CASE
                   WHEN jsonb_typeof(scs.effective_candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(scs.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
                   ELSE '[]'::jsonb
                 END
               ) AS eff_tpl(value)
               WHERE jsonb_typeof(eff_tpl.value) = 'object'
                 AND UPPER(COALESCE(eff_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                 AND COALESCE(NULLIF(BTRIM(COALESCE(eff_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'finance_case_id', '')), ''), '')
             )
         )
  INTO v_session_missing_snapshot_hidden_manual_debt_template
  FROM public.banking_pay_snapshot_candidate_state AS snap
  LEFT JOIN public.banking_pay_workbench_session_candidate_state AS scs
    ON scs.session_id = p_session_id
   AND scs.candidate_id = p_candidate_id
  WHERE snap.snapshot_run_id = v_source_snapshot_run_id
    AND snap.candidate_id = p_candidate_id
  LIMIT 1;

  IF UPPER(COALESCE(v_existing_session_candidate_status, '')) = 'READY'
     AND v_existing_session_candidate_session_version >= v_session_version
     AND v_existing_session_candidate_source_change_seq >= v_source_change_seq
     AND UPPER(COALESCE(v_snapshot_candidate_status, '')) = 'READY'
     AND v_snapshot_candidate_source_change_seq >= v_source_change_seq
     AND v_snapshot_candidate_projection_version >= v_required_projection_version
     AND (
       v_requires_hidden_recovery_templates = false
       OR v_snapshot_candidate_hidden_recovery_template_projection_version >= v_required_hidden_recovery_template_projection_version
     )
     AND v_existing_session_candidate_projection_version >= v_required_projection_version
     AND (
       v_requires_hidden_recovery_templates = false
       OR v_existing_session_candidate_hidden_recovery_template_projection_version >= v_required_hidden_recovery_template_projection_version
     )
     AND COALESCE(v_existing_session_candidate_last_recomputed_at_utc, '-infinity'::timestamptz) >= COALESCE(v_snapshot_candidate_last_refreshed_at_utc, '-infinity'::timestamptz)
     AND (v_snapshot_has_hidden_recovery_templates = false OR v_session_has_hidden_recovery_templates = true)
     AND v_session_missing_snapshot_hidden_manual_debt_template = false THEN
    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      NULL,
      'NO_OP',
      NULL,
      jsonb_build_object(
        'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
        'source_change_seq', v_source_change_seq,
        'projection_version', v_required_projection_version,
        'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'snapshot_last_refreshed_at_utc', v_snapshot_candidate_last_refreshed_at_utc,
        'reason', p_reason
      ),
      'WORKBENCH_JOB_ENQUEUE',
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL,
      'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', NULL,
      'reason', p_reason,
      'no_op', true,
      'reused', false
    );
  END IF;

  IF UPPER(COALESCE(v_existing_session_candidate_status, '')) = 'PENDING'
     AND v_existing_job_id IS NOT NULL
     AND v_existing_job_session_version >= v_session_version
     AND v_existing_job_source_change_seq >= v_source_change_seq
     AND v_existing_job_projection_version >= v_required_projection_version
     AND (
       v_requires_hidden_recovery_templates = false
       OR v_existing_job_hidden_recovery_template_projection_version >= v_required_hidden_recovery_template_projection_version
     ) THEN
    UPDATE public.banking_pay_workbench_session_candidate_state AS scs
    SET status = 'PENDING',
        effective_candidate_fragment_json = '{}'::jsonb,
        effective_summary_fragment_json = '{}'::jsonb,
        effective_paye_candidate_json = NULL,
        effective_non_paye_payee_json = NULL,
        effective_payees_json = '[]'::jsonb,
        effective_case_resolution_states_json = '[]'::jsonb,
        effective_canonical_preview_lines_json = '[]'::jsonb,
        source_change_seq = GREATEST(COALESCE(scs.source_change_seq, 0), v_source_change_seq),
        session_version = GREATEST(COALESCE(scs.session_version, 0), v_session_version),
        pending_job_id = COALESCE(v_existing_job_id, scs.pending_job_id),
        updated_at_utc = v_now,
        last_recomputed_at_utc = NULL,
        last_error_json = NULL
    WHERE scs.session_id = p_session_id
      AND scs.candidate_id = p_candidate_id;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_existing_job_id::text,
      'REUSED',
      NULL,
      jsonb_build_object(
        'id', v_existing_job_id::text,
        'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
        'status', v_existing_job_status,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
        'source_change_seq', v_source_change_seq,
        'projection_version', v_required_projection_version,
        'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'snapshot_last_refreshed_at_utc', v_snapshot_candidate_last_refreshed_at_utc,
        'reason', p_reason
      ),
      'WORKBENCH_JOB_ENQUEUE',
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_existing_job_id::text,
      'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', NULL,
      'reason', p_reason,
      'no_op', false,
      'reused', true
    );
  END IF;

  v_dedupe_key := 'SESSION_CANDIDATE_RECOMPUTE:' || p_session_id::text || ':' || p_candidate_id::text || ':v' || v_session_version::text || ':s' || v_source_change_seq::text || ':pv' || v_required_projection_version::text || ':ht' || v_required_hidden_recovery_template_projection_version::text;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    'SESSION_CANDIDATE_RECOMPUTE',
    'QUEUED',
    10,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_source_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    COALESCE(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'reason', p_reason,
        'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
        'source_change_seq', v_source_change_seq,
        'projection_version', v_required_projection_version,
        'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
        'snapshot_last_refreshed_at_utc', v_snapshot_candidate_last_refreshed_at_utc,
        'job_type', 'SESSION_CANDIDATE_RECOMPUTE'
      ),
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
      updated_at_utc = v_now
  RETURNING public.banking_pay_workbench_jobs.id, public.banking_pay_workbench_jobs.status, (xmax = 0)
  INTO v_job_id, v_job_status, v_job_was_inserted;

  INSERT INTO public.banking_pay_workbench_session_candidate_state (
    session_id,
    candidate_id,
    status,
    effective_candidate_fragment_json,
    effective_summary_fragment_json,
    effective_paye_candidate_json,
    effective_non_paye_payee_json,
    effective_payees_json,
    effective_case_resolution_states_json,
    effective_canonical_preview_lines_json,
    source_change_seq,
    session_version,
    pending_job_id,
    created_at_utc,
    updated_at_utc,
    last_recomputed_at_utc,
    last_error_json
  )
  VALUES (
    p_session_id,
    p_candidate_id,
    'PENDING',
    '{}'::jsonb,
    '{}'::jsonb,
    NULL,
    NULL,
    '[]'::jsonb,
    '[]'::jsonb,
    '[]'::jsonb,
    v_source_change_seq,
    v_session_version,
    v_job_id,
    v_now,
    v_now,
    NULL,
    NULL
  )
  ON CONFLICT (session_id, candidate_id)
  DO UPDATE
  SET status = 'PENDING',
      effective_candidate_fragment_json = '{}'::jsonb,
      effective_summary_fragment_json = '{}'::jsonb,
      effective_paye_candidate_json = NULL,
      effective_non_paye_payee_json = NULL,
      effective_payees_json = '[]'::jsonb,
      effective_case_resolution_states_json = '[]'::jsonb,
      effective_canonical_preview_lines_json = '[]'::jsonb,
      source_change_seq = GREATEST(public.banking_pay_workbench_session_candidate_state.source_change_seq, EXCLUDED.source_change_seq),
      session_version = GREATEST(public.banking_pay_workbench_session_candidate_state.session_version, EXCLUDED.session_version),
      pending_job_id = v_job_id,
      updated_at_utc = v_now,
      last_recomputed_at_utc = NULL,
      last_error_json = NULL;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
      'status', v_job_status,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'dedupe_key', v_dedupe_key,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'projection_version', v_required_projection_version,
      'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
      'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END
    ),
    'WORKBENCH_JOB_ENQUEUE',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', 'SESSION_CANDIDATE_RECOMPUTE',
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_snapshot_run_id', CASE WHEN v_source_snapshot_run_id IS NULL THEN NULL ELSE v_source_snapshot_run_id::text END,
    'source_change_seq', v_source_change_seq,
    'projection_version', v_required_projection_version,
    'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
    'dedupe_key', v_dedupe_key,
    'reason', p_reason,
    'no_op', false,
    'reused', (NOT v_job_was_inserted)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_refresh_candidate(p_snapshot_run_id uuid, p_candidate_id uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_existing_snapshot_candidate_row public.banking_pay_snapshot_candidate_state%ROWTYPE;
  v_context_json jsonb := '{}'::jsonb;
  v_baseline_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
  v_payees_json jsonb := '[]'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_baseline_component_rows_json jsonb := '[]'::jsonb;
  v_source_change_seq bigint := 0;
  v_last_error_json jsonb := NULL;
  v_payee_needs_readiness boolean := false;
  v_payee_readiness_enqueued boolean := false;
  v_payee_readiness_fingerprint_changed boolean := false;
  v_previous_payees_fingerprint text := '';
  v_current_payees_fingerprint text := '';
  v_audit_after_json jsonb := '{}'::jsonb;
  v_lock_source text := '';
  v_lock_hash_1 integer := 0;
  v_lock_hash_2 integer := 0;
  v_lock_key bigint := 0;
  v_case_state_count integer := 0;
  v_component_count integer := 0;
  v_line_count integer := 0;
  v_session_refresh_count integer := 0;
  v_force_refresh boolean := false;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_existing_projection_version integer := 0;
  v_existing_hidden_recovery_template_projection_version integer := 0;
BEGIN
  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  v_lock_source := 'PAY_WORKBENCH_SNAPSHOT_REFRESH:' || p_snapshot_run_id::text || ':' || p_candidate_id::text;
  v_lock_hash_1 := hashtext(v_lock_source);
  v_lock_hash_2 := hashtext(v_lock_source || ':2');
  v_lock_key := (((v_lock_hash_1::bigint & 4294967295) << 32) | (v_lock_hash_2::bigint & 4294967295));

  PERFORM pg_advisory_xact_lock(v_lock_key);

  SELECT sr.*
  INTO v_snapshot_run_row
  FROM public.banking_pay_snapshot_runs AS sr
  WHERE sr.id = p_snapshot_run_id
  LIMIT 1;

  IF v_snapshot_run_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  PERFORM 1
  FROM public.candidates AS c
  WHERE c.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  SELECT COALESCE(acc.seq, 0)
  INTO v_source_change_seq
  FROM public.app_change_counters AS acc
  WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text
  LIMIT 1;

  SELECT snap.*
  INTO v_existing_snapshot_candidate_row
  FROM public.banking_pay_snapshot_candidate_state AS snap
  WHERE snap.snapshot_run_id = p_snapshot_run_id
    AND snap.candidate_id = p_candidate_id
  LIMIT 1;

  v_previous_payees_fingerprint := md5(COALESCE(v_existing_snapshot_candidate_row.payees_json, '[]'::jsonb)::text);
  v_existing_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_existing_snapshot_candidate_row.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_existing_snapshot_candidate_row.candidate_fragment_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_existing_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_existing_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_existing_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );

  v_force_refresh := (
    COALESCE(NULLIF(UPPER(BTRIM(COALESCE(v_payload_json->>'refresh_scope_kind', ''))), ''), '') IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE')
    OR (
      jsonb_typeof(COALESCE(v_payload_json->'targeted_timesheet_ids', '[]'::jsonb)) = 'array'
      AND jsonb_array_length(COALESCE(v_payload_json->'targeted_timesheet_ids', '[]'::jsonb)) > 0
    )
    OR (
      jsonb_typeof(COALESCE(v_payload_json->'linked_timesheet_ids', '[]'::jsonb)) = 'array'
      AND jsonb_array_length(COALESCE(v_payload_json->'linked_timesheet_ids', '[]'::jsonb)) > 0
    )
  );

  IF NOT v_force_refresh
     AND v_existing_snapshot_candidate_row.id IS NOT NULL
     AND UPPER(COALESCE(v_existing_snapshot_candidate_row.status, '')) = 'READY'
     AND COALESCE(v_existing_snapshot_candidate_row.source_change_seq, 0) >= v_source_change_seq
     AND v_existing_projection_version >= v_required_projection_version
     AND (
       v_requires_hidden_recovery_templates = false
       OR v_existing_hidden_recovery_template_projection_version >= v_required_hidden_recovery_template_projection_version
     ) THEN
    PERFORM public._audit_insert(
      'banking_pay_snapshot_candidate_state',
      p_snapshot_run_id::text || ':' || p_candidate_id::text,
      'SNAPSHOT_CANDIDATE_REFRESH_NO_OP',
      NULL,
      jsonb_build_object(
        'snapshot_run_id', p_snapshot_run_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', v_source_change_seq,
        'existing_status', v_existing_snapshot_candidate_row.status,
        'existing_source_change_seq', COALESCE(v_existing_snapshot_candidate_row.source_change_seq, 0),
        'existing_projection_version', v_existing_projection_version,
        'existing_hidden_recovery_template_projection_version', v_existing_hidden_recovery_template_projection_version,
        'required_projection_version', v_required_projection_version,
        'required_hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'no_op_reason', 'ALREADY_CURRENT'
      ),
      'SNAPSHOT_CANDIDATE_REFRESH',
      NULL::uuid
    );

    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', v_source_change_seq,
      'payee_readiness_enqueued', false,
      'session_refresh_enqueued_count', 0,
      'case_state_count', 0,
      'line_count', 0,
      'component_count', 0,
      'refreshed_at_utc', v_now,
      'no_op', true,
      'reason', 'ALREADY_CURRENT'
    );
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_snapshot_candidate_state',
    p_snapshot_run_id::text || ':' || p_candidate_id::text,
    'SNAPSHOT_CANDIDATE_REFRESH_STARTED',
    NULL,
    jsonb_build_object(
      'snapshot_run_id', p_snapshot_run_id::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', v_source_change_seq,
      'started_at_utc', v_now
    ),
    'SNAPSHOT_CANDIDATE_REFRESH',
    NULL::uuid
  );

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_snapshot_run_row.pay_date,
    p_week_ending_cutoff => v_snapshot_run_row.week_ending_cutoff,
    p_actor_user_id => NULL::uuid,
    p_candidate_id => p_candidate_id,
    p_client_id => NULL::uuid,
    p_preview_decisions_json => v_payload_json
  );

  v_baseline_json := public.pay_preview_build_candidate_baseline(
    p_context_json => v_context_json,
    p_candidate_id => p_candidate_id
  );

  v_baseline_json := jsonb_strip_nulls(
    COALESCE(v_baseline_json, '{}'::jsonb)
    || jsonb_build_object(
      'projection_version', v_required_projection_version,
      'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
      'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates
    )
  );

  v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
    p_context_json => v_context_json,
    p_candidate_effective_json => v_baseline_json
  );

  v_payees_json := CASE
    WHEN jsonb_typeof(v_candidate_rollup_json->'payees') = 'array' THEN COALESCE(v_candidate_rollup_json->'payees', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_case_resolution_states_json := CASE
    WHEN jsonb_typeof(v_candidate_rollup_json->'case_resolution_states') = 'array' THEN COALESCE(v_candidate_rollup_json->'case_resolution_states', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_canonical_preview_lines_json := CASE
    WHEN jsonb_typeof(v_candidate_rollup_json->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_rollup_json->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_baseline_component_rows_json := CASE
    WHEN jsonb_typeof(v_baseline_json->'baseline_component_rows') = 'array' THEN COALESCE(v_baseline_json->'baseline_component_rows', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_current_payees_fingerprint := md5(COALESCE(v_payees_json, '[]'::jsonb)::text);
  v_payee_readiness_fingerprint_changed := (
    v_existing_snapshot_candidate_row.id IS NULL
    OR v_previous_payees_fingerprint <> v_current_payees_fingerprint
  );

  INSERT INTO public.banking_pay_snapshot_candidate_state (
    snapshot_run_id,
    candidate_id,
    status,
    candidate_fragment_json,
    summary_fragment_json,
    paye_candidate_json,
    non_paye_payee_json,
    payees_json,
    case_resolution_states_json,
    canonical_preview_lines_json,
    source_change_seq,
    created_at_utc,
    updated_at_utc,
    last_refreshed_at_utc,
    last_error_json
  )
  VALUES (
    p_snapshot_run_id,
    p_candidate_id,
    'READY',
    COALESCE(v_baseline_json, '{}'::jsonb),
    COALESCE(v_candidate_rollup_json->'summary_fragment', '{}'::jsonb),
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'paye_candidate') = 'object' THEN v_candidate_rollup_json->'paye_candidate' ELSE NULL END,
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'non_paye_payee') = 'object' THEN v_candidate_rollup_json->'non_paye_payee' ELSE NULL END,
    v_payees_json,
    v_case_resolution_states_json,
    v_canonical_preview_lines_json,
    v_source_change_seq,
    v_now,
    v_now,
    v_now,
    NULL
  )
  ON CONFLICT (snapshot_run_id, candidate_id)
  DO UPDATE
  SET status = 'READY',
      candidate_fragment_json = EXCLUDED.candidate_fragment_json,
      summary_fragment_json = EXCLUDED.summary_fragment_json,
      paye_candidate_json = EXCLUDED.paye_candidate_json,
      non_paye_payee_json = EXCLUDED.non_paye_payee_json,
      payees_json = EXCLUDED.payees_json,
      case_resolution_states_json = EXCLUDED.case_resolution_states_json,
      canonical_preview_lines_json = EXCLUDED.canonical_preview_lines_json,
      source_change_seq = EXCLUDED.source_change_seq,
      updated_at_utc = v_now,
      last_refreshed_at_utc = v_now,
      last_error_json = NULL;

  DELETE FROM public.banking_pay_snapshot_case_state AS scs
  WHERE scs.snapshot_run_id = p_snapshot_run_id
    AND scs.candidate_id = p_candidate_id;

  INSERT INTO public.banking_pay_snapshot_case_state (
    snapshot_run_id,
    candidate_id,
    case_key,
    finance_case_id,
    case_state_json,
    is_blocked,
    is_resolved,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_snapshot_run_id,
    p_candidate_id,
    case_state_rows.case_key,
    case_state_rows.finance_case_id,
    case_state_rows.case_state_json,
    case_state_rows.is_blocked,
    case_state_rows.is_resolved,
    v_now,
    v_now
  FROM (
    SELECT
      BTRIM(COALESCE(case_state_element.value->>'case_key', '')) AS case_key,
      CASE
        WHEN BTRIM(COALESCE(case_state_element.value->>'finance_case_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (case_state_element.value->>'finance_case_id')::uuid
        ELSE NULL::uuid
      END AS finance_case_id,
      case_state_element.value AS case_state_json,
      CASE
        WHEN LOWER(BTRIM(COALESCE(case_state_element.value->>'is_blocked', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
        ELSE false
      END AS is_blocked,
      CASE
        WHEN LOWER(BTRIM(COALESCE(case_state_element.value->>'case_resolution_satisfied_now', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
        ELSE false
      END AS is_resolved
    FROM jsonb_array_elements(v_case_resolution_states_json) AS case_state_element(value)
    WHERE jsonb_typeof(case_state_element.value) = 'object'
  ) AS case_state_rows
  WHERE case_state_rows.case_key <> '';

  GET DIAGNOSTICS v_case_state_count = ROW_COUNT;

  DELETE FROM public.banking_pay_snapshot_case_component_state AS scps
  WHERE scps.snapshot_run_id = p_snapshot_run_id
    AND scps.candidate_id = p_candidate_id;

  INSERT INTO public.banking_pay_snapshot_case_component_state (
    snapshot_run_id,
    candidate_id,
    case_key,
    timesheet_id,
    component_fingerprint,
    source_basis_fingerprint,
    source_family_key,
    bucket_code,
    component_key_type,
    component_key_value,
    component_state_json,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_snapshot_run_id,
    p_candidate_id,
    component_rows.case_key,
    component_rows.timesheet_id,
    component_rows.component_fingerprint,
    component_rows.source_basis_fingerprint,
    component_rows.source_family_key,
    component_rows.bucket_code,
    component_rows.component_key_type,
    component_rows.component_key_value,
    component_rows.component_state_json,
    v_now,
    v_now
  FROM (
    SELECT
      BTRIM(COALESCE(component_element.value->>'case_key', '')) AS case_key,
      CASE
        WHEN BTRIM(COALESCE(component_element.value->>'timesheet_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (component_element.value->>'timesheet_id')::uuid
        ELSE NULL::uuid
      END AS timesheet_id,
      BTRIM(COALESCE(component_element.value->>'component_fingerprint', '')) AS component_fingerprint,
      CASE
        WHEN BTRIM(COALESCE(component_element.value->>'source_basis_fingerprint', '')) <> ''
          THEN BTRIM(COALESCE(component_element.value->>'source_basis_fingerprint', ''))
        ELSE md5(COALESCE(component_element.value->'source_basis_json', '{}'::jsonb)::text)
      END AS source_basis_fingerprint,
      NULLIF(BTRIM(COALESCE(component_element.value->>'source_family_key', '')), '') AS source_family_key,
      NULLIF(BTRIM(COALESCE(component_element.value->>'bucket_code', '')), '') AS bucket_code,
      NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_type', '')), '') AS component_key_type,
      NULLIF(BTRIM(COALESCE(component_element.value->>'component_key_value', '')), '') AS component_key_value,
      component_element.value AS component_state_json
    FROM jsonb_array_elements(v_baseline_component_rows_json) AS component_element(value)
    WHERE jsonb_typeof(component_element.value) = 'object'
  ) AS component_rows
  WHERE component_rows.case_key <> ''
    AND component_rows.component_fingerprint <> '';

  GET DIAGNOSTICS v_component_count = ROW_COUNT;

  DELETE FROM public.banking_pay_snapshot_line_state AS sls
  WHERE sls.snapshot_run_id = p_snapshot_run_id
    AND sls.candidate_id = p_candidate_id;

  INSERT INTO public.banking_pay_snapshot_line_state (
    snapshot_run_id,
    candidate_id,
    preview_row_id,
    timesheet_id,
    case_key,
    pay_channel,
    component_key_type,
    component_key_value,
    canonical_line_json,
    created_at_utc,
    updated_at_utc
  )
  SELECT
    p_snapshot_run_id,
    p_candidate_id,
    line_rows.preview_row_id,
    line_rows.timesheet_id,
    line_rows.case_key,
    line_rows.pay_channel,
    line_rows.component_key_type,
    line_rows.component_key_value,
    line_rows.canonical_line_json,
    v_now,
    v_now
  FROM (
    SELECT
      BTRIM(COALESCE(line_element.value->>'preview_row_id', '')) AS preview_row_id,
      CASE
        WHEN BTRIM(COALESCE(line_element.value->>'timesheet_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (line_element.value->>'timesheet_id')::uuid
        ELSE NULL::uuid
      END AS timesheet_id,
      NULLIF(BTRIM(COALESCE(line_element.value->>'case_key', '')), '') AS case_key,
      NULLIF(BTRIM(COALESCE(line_element.value->>'pay_channel', '')), '') AS pay_channel,
      NULLIF(BTRIM(COALESCE(line_element.value->>'component_key_type', '')), '') AS component_key_type,
      NULLIF(BTRIM(COALESCE(line_element.value->>'component_key_value', '')), '') AS component_key_value,
      line_element.value AS canonical_line_json
    FROM jsonb_array_elements(v_canonical_preview_lines_json) AS line_element(value)
    WHERE jsonb_typeof(line_element.value) = 'object'
  ) AS line_rows
  WHERE line_rows.preview_row_id <> '';

  GET DIAGNOSTICS v_line_count = ROW_COUNT;

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_payees_json) AS payee_element(value)
    WHERE jsonb_typeof(payee_element.value) = 'object'
      AND EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(payee_element.value->'blockers') = 'array' THEN COALESCE(payee_element.value->'blockers', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS blocker_element(value)
        WHERE UPPER(BTRIM(blocker_element.value)) IN ('BLOCKED_NAME_CHECK', 'BLOCKED_NO_PAYEE_MAP')
      )
  )
  INTO v_payee_needs_readiness;

  IF v_payee_needs_readiness AND v_payee_readiness_fingerprint_changed THEN
    PERFORM public.pay_workbench_enqueue_payee_readiness_ensure(
      p_candidate_id => p_candidate_id,
      p_payees_json => v_payees_json,
      p_snapshot_run_id => p_snapshot_run_id,
      p_session_id => NULL::uuid,
      p_reason => 'SNAPSHOT_CANDIDATE_REFRESH',
      p_actor_user_id => NULL::uuid,
      p_payload_json => jsonb_build_object(
        'snapshot_run_id', p_snapshot_run_id::text,
        'candidate_id', p_candidate_id::text,
        'source_change_seq', v_source_change_seq,
        'projection_version', v_required_projection_version,
        'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
        'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
        'readiness_fingerprint', v_current_payees_fingerprint
      )
    );
    v_payee_readiness_enqueued := true;
  END IF;

  PERFORM public.pay_workbench_enqueue_session_candidate_refresh(
    p_session_id => ws.id,
    p_candidate_id => p_candidate_id,
    p_reason => 'SNAPSHOT_CANDIDATE_REFRESH',
    p_actor_user_id => NULL::uuid,
    p_payload_json => jsonb_build_object(
      'snapshot_run_id', p_snapshot_run_id::text,
      'candidate_id', p_candidate_id::text,
      'source_change_seq', v_source_change_seq,
      'projection_version', v_required_projection_version,
      'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
      'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
      'snapshot_last_refreshed_at_utc', v_now,
      'refresh_reason', CASE WHEN v_force_refresh THEN 'FORCED_SCOPE_REFRESH' ELSE 'SNAPSHOT_CANDIDATE_REFRESH' END
    )
  )
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.status = 'OPEN'
    AND ws.source_snapshot_run_id = p_snapshot_run_id
    AND ws.scope_candidate_ids @> ARRAY[p_candidate_id]::uuid[];

  GET DIAGNOSTICS v_session_refresh_count = ROW_COUNT;

  v_audit_after_json := jsonb_build_object(
    'snapshot_run_id', p_snapshot_run_id::text,
    'candidate_id', p_candidate_id::text,
    'source_change_seq', v_source_change_seq,
    'summary_fragment_json', COALESCE(v_candidate_rollup_json->'summary_fragment', '{}'::jsonb),
    'paye_candidate_json', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'paye_candidate') = 'object' THEN v_candidate_rollup_json->'paye_candidate' ELSE NULL END,
    'non_paye_payee_json', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'non_paye_payee') = 'object' THEN v_candidate_rollup_json->'non_paye_payee' ELSE NULL END,
    'payees_count', jsonb_array_length(v_payees_json),
    'case_state_count', v_case_state_count,
    'canonical_preview_line_count', v_line_count,
    'baseline_component_row_count', v_component_count,
    'session_refresh_enqueued_count', v_session_refresh_count,
    'payee_readiness_enqueued', v_payee_readiness_enqueued,
    'projection_version', v_required_projection_version,
    'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
    'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
    'last_refreshed_at_utc', v_now
  );

  PERFORM public._audit_insert(
    'banking_pay_snapshot_candidate_state',
    p_snapshot_run_id::text || ':' || p_candidate_id::text,
    'SNAPSHOT_CANDIDATE_REFRESH_SUCCEEDED',
    NULL,
    v_audit_after_json,
    'SNAPSHOT_CANDIDATE_REFRESH',
    NULL::uuid
  );

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', p_snapshot_run_id::text,
    'candidate_id', p_candidate_id::text,
    'source_change_seq', v_source_change_seq,
    'payee_readiness_enqueued', v_payee_readiness_enqueued,
    'session_refresh_enqueued_count', v_session_refresh_count,
    'case_state_count', v_case_state_count,
    'line_count', v_line_count,
    'component_count', v_component_count,
    'refreshed_at_utc', v_now,
    'projection_version', v_required_projection_version,
    'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
    'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
    'no_op', false
  );
EXCEPTION
  WHEN OTHERS THEN
    v_last_error_json := jsonb_build_object(
      'sqlstate', SQLSTATE,
      'message', SQLERRM,
      'snapshot_run_id', CASE WHEN p_snapshot_run_id IS NULL THEN NULL ELSE p_snapshot_run_id::text END,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'failed_at_utc', now()
    );

    IF p_snapshot_run_id IS NOT NULL AND p_candidate_id IS NOT NULL THEN
      INSERT INTO public.banking_pay_snapshot_candidate_state (
        snapshot_run_id,
        candidate_id,
        status,
        candidate_fragment_json,
        summary_fragment_json,
        paye_candidate_json,
        non_paye_payee_json,
        payees_json,
        case_resolution_states_json,
        canonical_preview_lines_json,
        source_change_seq,
        created_at_utc,
        updated_at_utc,
        last_refreshed_at_utc,
        last_error_json
      )
      VALUES (
        p_snapshot_run_id,
        p_candidate_id,
        'FAILED',
        '{}'::jsonb,
        '{}'::jsonb,
        NULL,
        NULL,
        '[]'::jsonb,
        '[]'::jsonb,
        '[]'::jsonb,
        COALESCE(v_source_change_seq, 0),
        now(),
        now(),
        NULL,
        v_last_error_json
      )
      ON CONFLICT (snapshot_run_id, candidate_id)
      DO UPDATE
      SET status = 'FAILED',
          source_change_seq = GREATEST(public.banking_pay_snapshot_candidate_state.source_change_seq, COALESCE(v_source_change_seq, 0)),
          updated_at_utc = now(),
          last_refreshed_at_utc = NULL,
          last_error_json = v_last_error_json;

      PERFORM public._audit_insert(
        'banking_pay_snapshot_candidate_state',
        p_snapshot_run_id::text || ':' || p_candidate_id::text,
        'SNAPSHOT_CANDIDATE_REFRESH_FAILED',
        NULL,
        v_last_error_json,
        'SNAPSHOT_CANDIDATE_REFRESH',
        NULL::uuid
      );
    END IF;

    RAISE;
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_enqueue_payee_readiness_ensure(
  p_candidate_id uuid,
  p_payees_json jsonb,
  p_snapshot_run_id uuid DEFAULT NULL::uuid,
  p_session_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_source_change_seq bigint := 0;
  v_session_version bigint := NULL;
  v_resolved_snapshot_run_id uuid := p_snapshot_run_id;
  v_readiness_fingerprint text := md5(COALESCE(p_payees_json::text, '[]'));
  v_dedupe_key text;
  v_job_id uuid;
  v_job_status text;
  v_job_was_inserted boolean := false;
  v_completed_job_id uuid := NULL;
  v_completed_job_status text := NULL;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  PERFORM 1
  FROM public.candidates AS c
  WHERE c.id = p_candidate_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'candidates row % not found', p_candidate_id;
  END IF;

  IF p_payees_json IS NULL THEN
    RAISE EXCEPTION 'payees_json is required';
  END IF;

  IF jsonb_typeof(p_payees_json) <> 'array' THEN
    RAISE EXCEPTION 'payees_json must be a JSON array';
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT ws.source_snapshot_run_id, ws.version
    INTO v_resolved_snapshot_run_id, v_session_version
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.id = p_session_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
    END IF;
  END IF;

  IF v_resolved_snapshot_run_id IS NOT NULL THEN
    SELECT COALESCE(snap.source_change_seq, 0)
    INTO v_source_change_seq
    FROM public.banking_pay_snapshot_candidate_state AS snap
    WHERE snap.snapshot_run_id = v_resolved_snapshot_run_id
      AND snap.candidate_id = p_candidate_id;
  END IF;

  IF v_source_change_seq = 0 THEN
    SELECT COALESCE(acc.seq, 0)
    INTO v_source_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;
  END IF;

  v_dedupe_key := 'PAYEE_READINESS_ENSURE:'
    || COALESCE(v_resolved_snapshot_run_id::text, 'no-run')
    || ':'
    || COALESCE(p_session_id::text, 'no-session')
    || ':'
    || p_candidate_id::text
    || ':s'
    || v_source_change_seq::text
    || ':'
    || v_readiness_fingerprint;

  SELECT j.id, j.status
  INTO v_completed_job_id, v_completed_job_status
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.job_type = 'PAYEE_READINESS_ENSURE'
    AND j.dedupe_key = v_dedupe_key
    AND j.completed_at_utc IS NOT NULL
    AND j.failed_at_utc IS NULL
  ORDER BY j.completed_at_utc DESC, j.id DESC
  LIMIT 1;

  IF v_completed_job_id IS NOT NULL THEN
    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_completed_job_id::text,
      'NO_OP',
      NULL,
      jsonb_build_object(
        'id', v_completed_job_id::text,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'status', v_completed_job_status,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'candidate_id', p_candidate_id::text,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'dedupe_key', v_dedupe_key,
        'reason', p_reason,
        'readiness_fingerprint', v_readiness_fingerprint
      ),
      'WORKBENCH_JOB_ENQUEUE',
      p_actor_user_id
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_completed_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint,
      'no_op', true,
      'reused', false
    );
  END IF;

  INSERT INTO public.banking_pay_workbench_jobs (
    job_type,
    status,
    priority,
    run_at_utc,
    attempt_count,
    max_attempts,
    dedupe_key,
    snapshot_run_id,
    session_id,
    candidate_id,
    payload_json,
    created_at_utc,
    updated_at_utc,
    started_at_utc,
    completed_at_utc,
    failed_at_utc,
    last_error_json
  )
  VALUES (
    'PAYEE_READINESS_ENSURE',
    'QUEUED',
    100,
    v_now,
    0,
    8,
    v_dedupe_key,
    v_resolved_snapshot_run_id,
    p_session_id,
    p_candidate_id,
    COALESCE(p_payload_json, '{}'::jsonb)
      || jsonb_build_object(
        'reason', p_reason,
        'actor_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'candidate_id', p_candidate_id::text,
        'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
        'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
        'session_version', v_session_version,
        'source_change_seq', v_source_change_seq,
        'payees_json', p_payees_json,
        'job_type', 'PAYEE_READINESS_ENSURE',
        'readiness_fingerprint', v_readiness_fingerprint
      ),
    v_now,
    v_now,
    NULL,
    NULL,
    NULL,
    NULL
  )
  ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
  DO UPDATE
  SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
      run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
      payload_json = COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb) || COALESCE(EXCLUDED.payload_json, '{}'::jsonb),
      updated_at_utc = v_now
  RETURNING public.banking_pay_workbench_jobs.id, public.banking_pay_workbench_jobs.status, (xmax = 0)
  INTO v_job_id, v_job_status, v_job_was_inserted;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    v_job_id::text,
    CASE WHEN v_job_was_inserted THEN 'QUEUED' ELSE 'REUSED' END,
    NULL,
    jsonb_build_object(
      'id', v_job_id::text,
      'job_type', 'PAYEE_READINESS_ENSURE',
      'status', v_job_status,
      'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', p_candidate_id::text,
      'session_version', v_session_version,
      'source_change_seq', v_source_change_seq,
      'dedupe_key', v_dedupe_key,
      'reason', p_reason,
      'readiness_fingerprint', v_readiness_fingerprint
    ),
    'WORKBENCH_JOB_ENQUEUE',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_id::text,
    'job_type', 'PAYEE_READINESS_ENSURE',
    'snapshot_run_id', CASE WHEN v_resolved_snapshot_run_id IS NULL THEN NULL ELSE v_resolved_snapshot_run_id::text END,
    'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
    'candidate_id', p_candidate_id::text,
    'session_version', v_session_version,
    'source_change_seq', v_source_change_seq,
    'dedupe_key', v_dedupe_key,
    'reason', p_reason,
    'readiness_fingerprint', v_readiness_fingerprint,
    'no_op', false,
    'reused', (NOT v_job_was_inserted)
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_claim_due_jobs(
  p_limit integer DEFAULT 25,
  p_now_utc timestamptz DEFAULT NULL::timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_limit integer := GREATEST(1, LEAST(COALESCE(p_limit, 25), 500));
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, v_now);
  v_stale_running_seconds integer := 600;
  v_stale_cutoff timestamptz := COALESCE(p_now_utc, v_now) - make_interval(secs => 600);
  v_recovered_stale jsonb := '[]'::jsonb;
  v_dead_stale jsonb := '[]'::jsonb;
  v_claimed jsonb := '[]'::jsonb;
  v_recovered_stale_count integer := 0;
  v_dead_stale_count integer := 0;
  v_claimed_count integer := 0;
  v_stale_row record;
  v_stale_before_json jsonb := NULL;
  v_stale_after_json jsonb := '{}'::jsonb;
  v_stale_error_json jsonb := NULL;
  v_claimed_row record;
  v_stale_job_source_change_seq bigint := 0;
  v_stale_job_session_version bigint := 0;
  v_stale_live_candidate_change_seq bigint := 0;
  v_stale_snapshot_state_status text := NULL;
  v_stale_snapshot_state_source_change_seq bigint := 0;
  v_stale_session_status text := NULL;
  v_stale_session_version bigint := 0;
  v_stale_session_candidate_status text := NULL;
  v_stale_session_candidate_source_change_seq bigint := 0;
  v_stale_session_candidate_session_version bigint := 0;
  v_stale_other_active_job_id uuid := NULL::uuid;
  v_stale_completed_equivalent_id uuid := NULL::uuid;
  v_stale_obsolete boolean := false;
  v_stale_obsolete_reason text := NULL;
BEGIN
  FOR v_stale_row IN
    WITH stale_candidates AS (
      SELECT
        stale_job.id,
        stale_job.job_type,
        stale_job.status,
        stale_job.priority,
        stale_job.run_at_utc,
        stale_job.attempt_count,
        stale_job.max_attempts,
        stale_job.dedupe_key,
        stale_job.snapshot_run_id,
        stale_job.session_id,
        stale_job.candidate_id,
        stale_job.payload_json,
        stale_job.created_at_utc,
        stale_job.updated_at_utc,
        stale_job.started_at_utc,
        stale_job.completed_at_utc,
        stale_job.failed_at_utc,
        stale_job.last_error_json,
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.created_at_utc,
          stale_job.run_at_utc
        ) AS last_activity_utc
      FROM public.banking_pay_workbench_jobs AS stale_job
      WHERE stale_job.status = 'RUNNING'
        AND stale_job.job_type IN ('SNAPSHOT_CANDIDATE_REFRESH', 'SESSION_CANDIDATE_RECOMPUTE', 'PAYEE_READINESS_ENSURE')
        AND stale_job.completed_at_utc IS NULL
        AND stale_job.failed_at_utc IS NULL
        AND COALESCE(
              stale_job.updated_at_utc,
              stale_job.started_at_utc,
              stale_job.created_at_utc,
              stale_job.run_at_utc
            ) <= v_stale_cutoff
      ORDER BY
        COALESCE(
          stale_job.updated_at_utc,
          stale_job.started_at_utc,
          stale_job.created_at_utc,
          stale_job.run_at_utc
        ) ASC,
        stale_job.priority ASC,
        stale_job.run_at_utc ASC,
        stale_job.created_at_utc ASC,
        stale_job.id ASC
      FOR UPDATE SKIP LOCKED
      LIMIT v_limit
    )
    SELECT
      stale_candidates.id,
      stale_candidates.job_type,
      stale_candidates.status,
      stale_candidates.priority,
      stale_candidates.run_at_utc,
      stale_candidates.attempt_count,
      stale_candidates.max_attempts,
      stale_candidates.dedupe_key,
      stale_candidates.snapshot_run_id,
      stale_candidates.session_id,
      stale_candidates.candidate_id,
      stale_candidates.payload_json,
      stale_candidates.created_at_utc,
      stale_candidates.updated_at_utc,
      stale_candidates.started_at_utc,
      stale_candidates.completed_at_utc,
      stale_candidates.failed_at_utc,
      stale_candidates.last_error_json,
      stale_candidates.last_activity_utc
    FROM stale_candidates
  LOOP
    v_stale_job_source_change_seq := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'source_change_seq')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_job_session_version := COALESCE(
      CASE
        WHEN COALESCE(v_stale_row.payload_json->>'session_version', '') ~ '^[0-9]+$'
          THEN (v_stale_row.payload_json->>'session_version')::bigint
        ELSE 0::bigint
      END,
      0::bigint
    );
    v_stale_live_candidate_change_seq := 0;
    v_stale_snapshot_state_status := NULL;
    v_stale_snapshot_state_source_change_seq := 0;
    v_stale_session_status := NULL;
    v_stale_session_version := 0;
    v_stale_session_candidate_status := NULL;
    v_stale_session_candidate_source_change_seq := 0;
    v_stale_session_candidate_session_version := 0;
    v_stale_other_active_job_id := NULL::uuid;
    v_stale_completed_equivalent_id := NULL::uuid;
    v_stale_obsolete := false;
    v_stale_obsolete_reason := NULL;

    IF v_stale_row.job_type = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
      IF v_stale_row.snapshot_run_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
        INTO v_stale_snapshot_state_status, v_stale_snapshot_state_source_change_seq
        FROM public.banking_pay_snapshot_candidate_state AS snap
        WHERE snap.snapshot_run_id = v_stale_row.snapshot_run_id
          AND snap.candidate_id = v_stale_row.candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_stale_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> v_stale_row.id
          AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
          AND j.snapshot_run_id = v_stale_row.snapshot_run_id
          AND j.candidate_id = v_stale_row.candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        ELSIF v_stale_other_active_job_id IS NOT NULL THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_stale_snapshot_state_status, '')) = 'READY'
              AND v_stale_snapshot_state_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
        END IF;
      END IF;
    ELSIF v_stale_row.job_type = 'SESSION_CANDIDATE_RECOMPUTE' THEN
      IF v_stale_row.session_id IS NULL OR v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_SESSION_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_stale_session_status, v_stale_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_stale_row.session_id
        LIMIT 1;

        IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSE
          SELECT COALESCE(scs.status, NULL),
                 COALESCE(scs.source_change_seq, 0),
                 COALESCE(scs.session_version, 0)
          INTO v_stale_session_candidate_status,
               v_stale_session_candidate_source_change_seq,
               v_stale_session_candidate_session_version
          FROM public.banking_pay_workbench_session_candidate_state AS scs
          WHERE scs.session_id = v_stale_row.session_id
            AND scs.candidate_id = v_stale_row.candidate_id
          LIMIT 1;

          SELECT j.id
          INTO v_stale_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
            AND j.session_id = v_stale_row.session_id
            AND j.candidate_id = v_stale_row.candidate_id
            AND j.status IN ('QUEUED', 'RUNNING')
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'session_version')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= v_stale_session_version
            AND COALESCE(
                  CASE
                    WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                      THEN (j.payload_json->>'source_change_seq')::bigint
                    ELSE 0::bigint
                  END,
                  0::bigint
                ) >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq)
          ORDER BY COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'session_version')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   COALESCE(
                     CASE
                       WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                         THEN (j.payload_json->>'source_change_seq')::bigint
                       ELSE 0::bigint
                     END,
                     0::bigint
                   ) DESC,
                   j.updated_at_utc DESC NULLS LAST,
                   j.created_at_utc DESC NULLS LAST,
                   j.id DESC
          LIMIT 1;

          IF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          ELSIF v_stale_other_active_job_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
          ELSIF UPPER(COALESCE(v_stale_session_candidate_status, '')) = 'READY'
                AND v_stale_session_candidate_session_version >= v_stale_session_version
                AND v_stale_session_candidate_source_change_seq >= GREATEST(v_stale_job_source_change_seq, v_stale_live_candidate_change_seq) THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_ALREADY_CURRENT';
          END IF;
        END IF;
      END IF;
    ELSIF v_stale_row.job_type = 'PAYEE_READINESS_ENSURE' THEN
      IF v_stale_row.candidate_id IS NULL THEN
        v_stale_obsolete := true;
        v_stale_obsolete_reason := 'INVALID_READINESS_CONTEXT';
      ELSE
        SELECT COALESCE(acc.seq, 0)
        INTO v_stale_live_candidate_change_seq
        FROM public.app_change_counters AS acc
        WHERE acc.entity_key = 'pay_candidate:' || v_stale_row.candidate_id::text;

        IF v_stale_row.session_id IS NOT NULL THEN
          SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
          INTO v_stale_session_status, v_stale_session_version
          FROM public.banking_pay_workbench_sessions AS ws
          WHERE ws.id = v_stale_row.session_id
          LIMIT 1;

          IF v_stale_session_status IS NULL OR UPPER(COALESCE(v_stale_session_status, '')) <> 'OPEN' THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SESSION_NOT_OPEN';
          ELSIF v_stale_session_version > v_stale_job_session_version THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
          END IF;
        END IF;

        IF NOT v_stale_obsolete AND v_stale_live_candidate_change_seq > v_stale_job_source_change_seq THEN
          v_stale_obsolete := true;
          v_stale_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
        END IF;

        IF NOT v_stale_obsolete THEN
          SELECT j.id
          INTO v_stale_completed_equivalent_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> v_stale_row.id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_stale_row.dedupe_key
            AND j.completed_at_utc IS NOT NULL
            AND j.failed_at_utc IS NULL
          ORDER BY j.completed_at_utc DESC, j.id DESC
          LIMIT 1;

          IF v_stale_completed_equivalent_id IS NOT NULL THEN
            v_stale_obsolete := true;
            v_stale_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
          ELSE
            SELECT j.id
            INTO v_stale_other_active_job_id
            FROM public.banking_pay_workbench_jobs AS j
            WHERE j.id <> v_stale_row.id
              AND j.job_type = 'PAYEE_READINESS_ENSURE'
              AND j.dedupe_key = v_stale_row.dedupe_key
              AND j.status IN ('QUEUED', 'RUNNING')
            ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
            LIMIT 1;

            IF v_stale_other_active_job_id IS NOT NULL THEN
              v_stale_obsolete := true;
              v_stale_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
            END IF;
          END IF;
        END IF;
      END IF;
    END IF;

    v_stale_before_json := jsonb_build_object(
      'id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'status', v_stale_row.status,
      'priority', v_stale_row.priority,
      'run_at_utc', v_stale_row.run_at_utc,
      'attempt_count', v_stale_row.attempt_count,
      'max_attempts', v_stale_row.max_attempts,
      'dedupe_key', v_stale_row.dedupe_key,
      'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
      'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
      'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
      'payload_json', v_stale_row.payload_json,
      'created_at_utc', v_stale_row.created_at_utc,
      'updated_at_utc', v_stale_row.updated_at_utc,
      'started_at_utc', v_stale_row.started_at_utc,
      'completed_at_utc', v_stale_row.completed_at_utc,
      'failed_at_utc', v_stale_row.failed_at_utc,
      'last_error_json', v_stale_row.last_error_json,
      'last_activity_utc', v_stale_row.last_activity_utc
    );

    v_stale_error_json := jsonb_build_object(
      'code', CASE WHEN v_stale_obsolete THEN 'STALE_RUNNING_OBSOLETE' ELSE 'STALE_RUNNING_RECOVERY' END,
      'message', CASE WHEN v_stale_obsolete THEN 'Dead-lettered stale RUNNING workbench job because its context is already obsolete.' ELSE 'Recovered stale RUNNING workbench job during due-job claim cycle.' END,
      'job_id', v_stale_row.id::text,
      'job_type', v_stale_row.job_type,
      'previous_status', v_stale_row.status,
      'attempt_count', COALESCE(v_stale_row.attempt_count, 0),
      'max_attempts', COALESCE(v_stale_row.max_attempts, 8),
      'last_activity_utc', v_stale_row.last_activity_utc,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'recovered_at_utc', v_now,
      'obsolete', v_stale_obsolete,
      'obsolete_reason', v_stale_obsolete_reason,
      'source_change_seq', v_stale_job_source_change_seq,
      'session_version', v_stale_job_session_version,
      'live_candidate_change_seq', CASE WHEN v_stale_live_candidate_change_seq = 0 THEN NULL ELSE v_stale_live_candidate_change_seq END,
      'snapshot_state_status', v_stale_snapshot_state_status,
      'snapshot_state_source_change_seq', CASE WHEN v_stale_snapshot_state_source_change_seq = 0 THEN NULL ELSE v_stale_snapshot_state_source_change_seq END,
      'session_status', v_stale_session_status,
      'current_session_version', CASE WHEN v_stale_session_version = 0 THEN NULL ELSE v_stale_session_version END,
      'session_candidate_status', v_stale_session_candidate_status,
      'session_candidate_source_change_seq', CASE WHEN v_stale_session_candidate_source_change_seq = 0 THEN NULL ELSE v_stale_session_candidate_source_change_seq END,
      'session_candidate_session_version', CASE WHEN v_stale_session_candidate_session_version = 0 THEN NULL ELSE v_stale_session_candidate_session_version END,
      'other_active_job_id', CASE WHEN v_stale_other_active_job_id IS NULL THEN NULL ELSE v_stale_other_active_job_id::text END,
      'completed_equivalent_job_id', CASE WHEN v_stale_completed_equivalent_id IS NULL THEN NULL ELSE v_stale_completed_equivalent_id::text END
    );

    IF v_stale_obsolete OR COALESCE(v_stale_row.attempt_count, 0) >= COALESCE(v_stale_row.max_attempts, 8) THEN
      UPDATE public.banking_pay_workbench_jobs AS dead_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_stale_error_json,
          payload_json = COALESCE(dead_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_stale_error_json)
      WHERE dead_job.id = v_stale_row.id
      RETURNING
        dead_job.id,
        dead_job.job_type,
        dead_job.status,
        dead_job.priority,
        dead_job.run_at_utc,
        dead_job.attempt_count,
        dead_job.max_attempts,
        dead_job.dedupe_key,
        dead_job.snapshot_run_id,
        dead_job.session_id,
        dead_job.candidate_id,
        dead_job.payload_json,
        dead_job.created_at_utc,
        dead_job.updated_at_utc,
        dead_job.started_at_utc,
        dead_job.completed_at_utc,
        dead_job.failed_at_utc,
        dead_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.created_at_utc,
          v_stale_row.run_at_utc
        ),
        'stale_recovery', true,
        'dead_lettered', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', v_stale_obsolete,
        'obsolete_reason', v_stale_obsolete_reason
      );

      v_dead_stale := v_dead_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'failed_at_utc', v_stale_row.failed_at_utc,
          'last_error_json', v_stale_row.last_error_json,
          'obsolete', v_stale_obsolete,
          'obsolete_reason', v_stale_obsolete_reason
        )
      );

      v_dead_stale_count := v_dead_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'DEAD',
        v_stale_before_json,
        v_stale_after_json,
        'WORKBENCH_JOB_STALE_RUNNER_DEAD',
        NULL
      );
    ELSE
      UPDATE public.banking_pay_workbench_jobs AS requeue_job
      SET status = 'QUEUED',
          run_at_utc = v_cutoff,
          updated_at_utc = v_now,
          started_at_utc = NULL,
          completed_at_utc = NULL,
          failed_at_utc = NULL,
          last_error_json = v_stale_error_json
      WHERE requeue_job.id = v_stale_row.id
      RETURNING
        requeue_job.id,
        requeue_job.job_type,
        requeue_job.status,
        requeue_job.priority,
        requeue_job.run_at_utc,
        requeue_job.attempt_count,
        requeue_job.max_attempts,
        requeue_job.dedupe_key,
        requeue_job.snapshot_run_id,
        requeue_job.session_id,
        requeue_job.candidate_id,
        requeue_job.payload_json,
        requeue_job.created_at_utc,
        requeue_job.updated_at_utc,
        requeue_job.started_at_utc,
        requeue_job.completed_at_utc,
        requeue_job.failed_at_utc,
        requeue_job.last_error_json
      INTO
        v_stale_row.id,
        v_stale_row.job_type,
        v_stale_row.status,
        v_stale_row.priority,
        v_stale_row.run_at_utc,
        v_stale_row.attempt_count,
        v_stale_row.max_attempts,
        v_stale_row.dedupe_key,
        v_stale_row.snapshot_run_id,
        v_stale_row.session_id,
        v_stale_row.candidate_id,
        v_stale_row.payload_json,
        v_stale_row.created_at_utc,
        v_stale_row.updated_at_utc,
        v_stale_row.started_at_utc,
        v_stale_row.completed_at_utc,
        v_stale_row.failed_at_utc,
        v_stale_row.last_error_json;

      v_stale_after_json := jsonb_build_object(
        'id', v_stale_row.id::text,
        'job_type', v_stale_row.job_type,
        'status', v_stale_row.status,
        'priority', v_stale_row.priority,
        'run_at_utc', v_stale_row.run_at_utc,
        'attempt_count', v_stale_row.attempt_count,
        'max_attempts', v_stale_row.max_attempts,
        'dedupe_key', v_stale_row.dedupe_key,
        'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
        'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
        'payload_json', v_stale_row.payload_json,
        'created_at_utc', v_stale_row.created_at_utc,
        'updated_at_utc', v_stale_row.updated_at_utc,
        'started_at_utc', v_stale_row.started_at_utc,
        'completed_at_utc', v_stale_row.completed_at_utc,
        'failed_at_utc', v_stale_row.failed_at_utc,
        'last_error_json', v_stale_row.last_error_json,
        'last_activity_utc', COALESCE(
          v_stale_row.updated_at_utc,
          v_stale_row.started_at_utc,
          v_stale_row.created_at_utc,
          v_stale_row.run_at_utc
        ),
        'stale_recovery', true,
        'requeued', true,
        'stale_cutoff_utc', v_stale_cutoff,
        'stale_running_seconds', v_stale_running_seconds,
        'obsolete', false,
        'obsolete_reason', NULL
      );

      v_recovered_stale := v_recovered_stale || jsonb_build_array(
        jsonb_build_object(
          'job_id', v_stale_row.id::text,
          'job_type', v_stale_row.job_type,
          'priority', v_stale_row.priority,
          'run_at_utc', v_stale_row.run_at_utc,
          'attempt_count', v_stale_row.attempt_count,
          'max_attempts', v_stale_row.max_attempts,
          'snapshot_run_id', CASE WHEN v_stale_row.snapshot_run_id IS NULL THEN NULL ELSE v_stale_row.snapshot_run_id::text END,
          'session_id', CASE WHEN v_stale_row.session_id IS NULL THEN NULL ELSE v_stale_row.session_id::text END,
          'candidate_id', CASE WHEN v_stale_row.candidate_id IS NULL THEN NULL ELSE v_stale_row.candidate_id::text END,
          'payload_json', v_stale_row.payload_json,
          'updated_at_utc', v_stale_row.updated_at_utc,
          'last_error_json', v_stale_row.last_error_json
        )
      );

      v_recovered_stale_count := v_recovered_stale_count + 1;

      PERFORM public._audit_insert(
        'banking_pay_workbench_job',
        v_stale_row.id::text,
        'REQUEUED',
        v_stale_before_json,
        v_stale_after_json,
        'WORKBENCH_JOB_STALE_RUNNER_REQUEUED',
        NULL
      );
    END IF;
  END LOOP;

  FOR v_claimed_row IN
    WITH claim AS (
      SELECT
        claim_job.id,
        claim_job.job_type,
        claim_job.priority,
        claim_job.run_at_utc,
        claim_job.attempt_count,
        claim_job.max_attempts,
        claim_job.snapshot_run_id,
        claim_job.session_id,
        claim_job.candidate_id,
        claim_job.payload_json,
        claim_job.created_at_utc
      FROM public.banking_pay_workbench_jobs AS claim_job
      WHERE claim_job.status = 'QUEUED'
        AND claim_job.run_at_utc <= v_cutoff
      ORDER BY claim_job.priority ASC, claim_job.run_at_utc ASC, claim_job.created_at_utc ASC, claim_job.id ASC
      FOR UPDATE SKIP LOCKED
      LIMIT v_limit
    ),
    upd AS (
      UPDATE public.banking_pay_workbench_jobs AS upd_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(upd_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(upd_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          last_error_json = NULL
      FROM claim AS claim_row
      WHERE upd_job.id = claim_row.id
      RETURNING
        upd_job.id,
        upd_job.job_type,
        upd_job.priority,
        upd_job.run_at_utc,
        upd_job.attempt_count,
        upd_job.max_attempts,
        upd_job.snapshot_run_id,
        upd_job.session_id,
        upd_job.candidate_id,
        upd_job.payload_json,
        upd_job.started_at_utc,
        upd_job.created_at_utc
    )
    SELECT
      upd.id,
      upd.job_type,
      upd.priority,
      upd.run_at_utc,
      upd.attempt_count,
      upd.max_attempts,
      upd.snapshot_run_id,
      upd.session_id,
      upd.candidate_id,
      upd.payload_json,
      upd.started_at_utc,
      upd.created_at_utc
    FROM upd
    ORDER BY upd.priority ASC, upd.run_at_utc ASC, upd.created_at_utc ASC, upd.id ASC
  LOOP
    v_claimed := v_claimed || jsonb_build_array(
      jsonb_build_object(
        'job_id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'priority', v_claimed_row.priority,
        'run_at_utc', v_claimed_row.run_at_utc,
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END,
        'payload_json', v_claimed_row.payload_json,
        'started_at_utc', v_claimed_row.started_at_utc,
        'created_at_utc', v_claimed_row.created_at_utc
      )
    );

    v_claimed_count := v_claimed_count + 1;

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_claimed_row.id::text,
      'RUNNING',
      NULL,
      jsonb_build_object(
        'id', v_claimed_row.id::text,
        'job_type', v_claimed_row.job_type,
        'status', 'RUNNING',
        'attempt_count', v_claimed_row.attempt_count,
        'max_attempts', v_claimed_row.max_attempts,
        'run_at_utc', v_claimed_row.run_at_utc,
        'started_at_utc', v_claimed_row.started_at_utc,
        'snapshot_run_id', CASE WHEN v_claimed_row.snapshot_run_id IS NULL THEN NULL ELSE v_claimed_row.snapshot_run_id::text END,
        'session_id', CASE WHEN v_claimed_row.session_id IS NULL THEN NULL ELSE v_claimed_row.session_id::text END,
        'candidate_id', CASE WHEN v_claimed_row.candidate_id IS NULL THEN NULL ELSE v_claimed_row.candidate_id::text END
      ),
      'WORKBENCH_JOB_CLAIMED',
      NULL
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'limit', v_limit,
    'recovered_stale_count', v_recovered_stale_count,
    'dead_stale_count', v_dead_stale_count,
    'claimed_count', v_claimed_count,
    'recovered_stale', v_recovered_stale,
    'dead_stale', v_dead_stale,
    'claimed', v_claimed
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_workbench_complete_job(
  p_job_id uuid,
  p_result_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_status text;
  v_job_type text;
  v_snapshot_run_id uuid;
  v_session_id uuid;
  v_candidate_id uuid;
  v_attempt_count integer;
  v_completed_at_utc timestamptz;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  UPDATE public.banking_pay_workbench_jobs j
  SET status = 'SUCCEEDED',
      updated_at_utc = v_now,
      completed_at_utc = v_now,
      failed_at_utc = NULL,
      last_error_json = NULL,
      payload_json = COALESCE(j.payload_json, '{}'::jsonb) || jsonb_build_object('result_json', COALESCE(p_result_json, '{}'::jsonb))
  WHERE j.id = p_job_id
  RETURNING j.status, j.job_type, j.snapshot_run_id, j.session_id, j.candidate_id, j.attempt_count, j.completed_at_utc
  INTO v_status, v_job_type, v_snapshot_run_id, v_session_id, v_candidate_id, v_attempt_count, v_completed_at_utc;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    'SUCCEEDED',
    NULL,
    jsonb_build_object(
      'id', p_job_id::text,
      'job_type', v_job_type,
      'status', v_status,
      'snapshot_run_id', CASE WHEN v_snapshot_run_id IS NULL THEN NULL ELSE v_snapshot_run_id::text END,
      'session_id', CASE WHEN v_session_id IS NULL THEN NULL ELSE v_session_id::text END,
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'attempt_count', v_attempt_count,
      'completed_at_utc', v_completed_at_utc,
      'result_json', COALESCE(p_result_json, '{}'::jsonb)
    ),
    'WORKBENCH_JOB_COMPLETED',
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', 'SUCCEEDED',
    'completed_at_utc', v_now,
    'result_json', COALESCE(p_result_json, '{}'::jsonb)
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_fail_job(
  p_job_id uuid,
  p_error_json jsonb,
  p_retry_after_seconds integer DEFAULT NULL::integer
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_job_type text;
  v_attempt_count integer;
  v_max_attempts integer;
  v_retry_after_seconds integer;
  v_next_run_at_utc timestamptz;
  v_new_status text;
  v_failed_at_utc timestamptz;
  v_job_snapshot_run_id uuid := NULL::uuid;
  v_job_session_id uuid := NULL::uuid;
  v_job_candidate_id uuid := NULL::uuid;
  v_job_dedupe_key text := NULL;
  v_job_payload_json jsonb := '{}'::jsonb;
  v_job_source_change_seq bigint := 0;
  v_job_session_version bigint := 0;
  v_live_candidate_change_seq bigint := 0;
  v_snapshot_state_status text := NULL;
  v_snapshot_state_source_change_seq bigint := 0;
  v_current_session_status text := NULL;
  v_current_session_version bigint := 0;
  v_session_candidate_status text := NULL;
  v_session_candidate_source_change_seq bigint := 0;
  v_session_candidate_session_version bigint := 0;
  v_other_active_job_id uuid := NULL::uuid;
  v_completed_equivalent_job_id uuid := NULL::uuid;
  v_is_obsolete boolean := false;
  v_obsolete_reason text := NULL;
  v_error_code text := UPPER(COALESCE(p_error_json->>'code', ''));
  v_error_message text := UPPER(COALESCE(p_error_json->>'message', ''));
  v_is_statement_timeout boolean := false;
  v_is_no_change_loop boolean := false;
BEGIN
  IF p_job_id IS NULL THEN
    RAISE EXCEPTION 'job_id is required';
  END IF;

  IF p_error_json IS NULL THEN
    RAISE EXCEPTION 'error_json is required';
  END IF;

  SELECT j.job_type,
         j.attempt_count,
         j.max_attempts,
         j.snapshot_run_id,
         j.session_id,
         j.candidate_id,
         j.dedupe_key,
         COALESCE(j.payload_json, '{}'::jsonb)
  INTO v_job_type,
       v_attempt_count,
       v_max_attempts,
       v_job_snapshot_run_id,
       v_job_session_id,
       v_job_candidate_id,
       v_job_dedupe_key,
       v_job_payload_json
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.id = p_job_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found', p_job_id;
  END IF;

  v_job_source_change_seq := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'source_change_seq')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );
  v_job_session_version := COALESCE(
    CASE
      WHEN COALESCE(v_job_payload_json->>'session_version', '') ~ '^[0-9]+$'
        THEN (v_job_payload_json->>'session_version')::bigint
      ELSE 0::bigint
    END,
    0::bigint
  );

  v_is_statement_timeout := (
    v_error_code = '57014'
    OR v_error_message LIKE '%STATEMENT TIMEOUT%'
    OR v_error_message LIKE '%CANCELING STATEMENT DUE TO STATEMENT TIMEOUT%'
  );

  v_is_no_change_loop := (
    v_error_code IN ('SNAPSHOT_ALREADY_CURRENT', 'ALREADY_CURRENT', 'NO_EFFECTIVE_CHANGE', 'PAYEE_READINESS_NO_EFFECTIVE_CHANGE', 'STALE_SESSION_VERSION', 'SESSION_DISCARDED')
    OR v_error_message LIKE '%ALREADY CURRENT%'
    OR v_error_message LIKE '%NO EFFECTIVE CHANGE%'
    OR v_error_message LIKE '%STALE SESSION VERSION%'
    OR v_error_message LIKE '%SESSION DISCARDED%'
  );

  IF v_job_type = 'SNAPSHOT_CANDIDATE_REFRESH' THEN
    IF v_job_snapshot_run_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SNAPSHOT_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(snap.status, NULL), COALESCE(snap.source_change_seq, 0)
      INTO v_snapshot_state_status, v_snapshot_state_source_change_seq
      FROM public.banking_pay_snapshot_candidate_state AS snap
      WHERE snap.snapshot_run_id = v_job_snapshot_run_id
        AND snap.candidate_id = v_job_candidate_id
      LIMIT 1;

      SELECT j.id
      INTO v_other_active_job_id
      FROM public.banking_pay_workbench_jobs AS j
      WHERE j.id <> p_job_id
        AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
        AND j.snapshot_run_id = v_job_snapshot_run_id
        AND j.candidate_id = v_job_candidate_id
        AND j.status IN ('QUEUED', 'RUNNING')
        AND COALESCE(
              CASE
                WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                  THEN (j.payload_json->>'source_change_seq')::bigint
                ELSE 0::bigint
              END,
              0::bigint
            ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
      ORDER BY COALESCE(
                 CASE
                   WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                     THEN (j.payload_json->>'source_change_seq')::bigint
                   ELSE 0::bigint
                 END,
                 0::bigint
               ) DESC,
               j.updated_at_utc DESC NULLS LAST,
               j.created_at_utc DESC NULLS LAST,
               j.id DESC
      LIMIT 1;

      IF v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      ELSIF v_other_active_job_id IS NOT NULL THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'MATCHING_ACTIVE_SNAPSHOT_JOB_EXISTS';
      ELSIF UPPER(COALESCE(v_snapshot_state_status, '')) = 'READY'
            AND v_snapshot_state_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SNAPSHOT_ALREADY_CURRENT';
      END IF;
    END IF;
  ELSIF v_job_type = 'SESSION_CANDIDATE_RECOMPUTE' THEN
    IF v_job_session_id IS NULL OR v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_SESSION_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
      INTO v_current_session_status, v_current_session_version
      FROM public.banking_pay_workbench_sessions AS ws
      WHERE ws.id = v_job_session_id
      LIMIT 1;

      IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SESSION_NOT_OPEN';
      ELSE
        SELECT COALESCE(scs.status, NULL),
               COALESCE(scs.source_change_seq, 0),
               COALESCE(scs.session_version, 0)
        INTO v_session_candidate_status,
             v_session_candidate_source_change_seq,
             v_session_candidate_session_version
        FROM public.banking_pay_workbench_session_candidate_state AS scs
        WHERE scs.session_id = v_job_session_id
          AND scs.candidate_id = v_job_candidate_id
        LIMIT 1;

        SELECT j.id
        INTO v_other_active_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
          AND j.session_id = v_job_session_id
          AND j.candidate_id = v_job_candidate_id
          AND j.status IN ('QUEUED', 'RUNNING')
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'session_version')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= v_current_session_version
          AND COALESCE(
                CASE
                  WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                    THEN (j.payload_json->>'source_change_seq')::bigint
                  ELSE 0::bigint
                END,
                0::bigint
              ) >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq)
        ORDER BY COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'session_version')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 COALESCE(
                   CASE
                     WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                       THEN (j.payload_json->>'source_change_seq')::bigint
                     ELSE 0::bigint
                   END,
                   0::bigint
                 ) DESC,
                 j.updated_at_utc DESC NULLS LAST,
                 j.created_at_utc DESC NULLS LAST,
                 j.id DESC
        LIMIT 1;

        IF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        ELSIF v_other_active_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'MATCHING_ACTIVE_SESSION_JOB_EXISTS';
        ELSIF UPPER(COALESCE(v_session_candidate_status, '')) = 'READY'
              AND v_session_candidate_session_version >= v_current_session_version
              AND v_session_candidate_source_change_seq >= GREATEST(v_job_source_change_seq, v_live_candidate_change_seq) THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_ALREADY_CURRENT';
        END IF;
      END IF;
    END IF;
  ELSIF v_job_type = 'PAYEE_READINESS_ENSURE' THEN
    IF v_job_candidate_id IS NULL THEN
      v_is_obsolete := true;
      v_obsolete_reason := 'INVALID_READINESS_CONTEXT';
    ELSE
      SELECT COALESCE(acc.seq, 0)
      INTO v_live_candidate_change_seq
      FROM public.app_change_counters AS acc
      WHERE acc.entity_key = 'pay_candidate:' || v_job_candidate_id::text;

      IF v_job_session_id IS NOT NULL THEN
        SELECT COALESCE(ws.status, NULL), COALESCE(ws.version, 0)
        INTO v_current_session_status, v_current_session_version
        FROM public.banking_pay_workbench_sessions AS ws
        WHERE ws.id = v_job_session_id
        LIMIT 1;

        IF v_current_session_status IS NULL OR UPPER(COALESCE(v_current_session_status, '')) <> 'OPEN' THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SESSION_NOT_OPEN';
        ELSIF v_current_session_version > v_job_session_version THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'SUPERSEDED_BY_NEWER_SESSION_VERSION';
        END IF;
      END IF;

      IF NOT v_is_obsolete AND v_live_candidate_change_seq > v_job_source_change_seq THEN
        v_is_obsolete := true;
        v_obsolete_reason := 'SUPERSEDED_BY_LIVE_CHANGE_SEQ';
      END IF;

      IF NOT v_is_obsolete THEN
        SELECT j.id
        INTO v_completed_equivalent_job_id
        FROM public.banking_pay_workbench_jobs AS j
        WHERE j.id <> p_job_id
          AND j.job_type = 'PAYEE_READINESS_ENSURE'
          AND j.dedupe_key = v_job_dedupe_key
          AND j.completed_at_utc IS NOT NULL
          AND j.failed_at_utc IS NULL
        ORDER BY j.completed_at_utc DESC, j.id DESC
        LIMIT 1;

        IF v_completed_equivalent_job_id IS NOT NULL THEN
          v_is_obsolete := true;
          v_obsolete_reason := 'COMPLETED_EQUIVALENT_EXISTS';
        ELSE
          SELECT j.id
          INTO v_other_active_job_id
          FROM public.banking_pay_workbench_jobs AS j
          WHERE j.id <> p_job_id
            AND j.job_type = 'PAYEE_READINESS_ENSURE'
            AND j.dedupe_key = v_job_dedupe_key
            AND j.status IN ('QUEUED', 'RUNNING')
          ORDER BY j.updated_at_utc DESC NULLS LAST, j.created_at_utc DESC NULLS LAST, j.id DESC
          LIMIT 1;

          IF v_other_active_job_id IS NOT NULL THEN
            v_is_obsolete := true;
            v_obsolete_reason := 'MATCHING_ACTIVE_READINESS_JOB_EXISTS';
          END IF;
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_is_statement_timeout THEN
    v_retry_after_seconds := GREATEST(
      300,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(COALESCE(v_attempt_count, 1), 1) * 300),
        14400
      )
    );
  ELSE
    v_retry_after_seconds := GREATEST(
      5,
      LEAST(
        COALESCE(p_retry_after_seconds, GREATEST(30, LEAST(COALESCE(v_attempt_count, 1) * 60, 3600))),
        86400
      )
    );
  END IF;

  IF v_is_obsolete OR v_is_no_change_loop OR COALESCE(v_attempt_count, 0) >= COALESCE(v_max_attempts, 8) THEN
    v_new_status := 'DEAD';
    v_next_run_at_utc := NULL;
  ELSE
    v_new_status := 'QUEUED';
    v_next_run_at_utc := v_now + make_interval(secs => v_retry_after_seconds);
  END IF;

  UPDATE public.banking_pay_workbench_jobs AS j
  SET status = v_new_status,
      run_at_utc = COALESCE(v_next_run_at_utc, j.run_at_utc),
      updated_at_utc = v_now,
      started_at_utc = CASE WHEN v_new_status = 'QUEUED' THEN NULL ELSE j.started_at_utc END,
      completed_at_utc = NULL,
      failed_at_utc = v_now,
      last_error_json = p_error_json,
      payload_json = COALESCE(j.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', p_error_json)
  WHERE j.id = p_job_id
  RETURNING j.failed_at_utc
  INTO v_failed_at_utc;

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    CASE WHEN v_new_status = 'QUEUED' THEN 'REQUEUED' ELSE 'DEAD' END,
    NULL,
    jsonb_build_object(
      'id', p_job_id::text,
      'job_type', v_job_type,
      'status', v_new_status,
      'attempt_count', v_attempt_count,
      'max_attempts', v_max_attempts,
      'run_at_utc', v_next_run_at_utc,
      'failed_at_utc', v_failed_at_utc,
      'last_error_json', p_error_json,
      'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
      'obsolete', v_is_obsolete,
      'obsolete_reason', v_obsolete_reason,
      'statement_timeout', v_is_statement_timeout,
      'deterministic_no_change_loop', v_is_no_change_loop
    ),
    CASE WHEN v_new_status = 'QUEUED' THEN 'WORKBENCH_JOB_REQUEUED' ELSE 'WORKBENCH_JOB_DEAD' END,
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', p_job_id::text,
    'status', v_new_status,
    'attempt_count', v_attempt_count,
    'max_attempts', v_max_attempts,
    'retry_after_seconds', CASE WHEN v_new_status = 'QUEUED' THEN v_retry_after_seconds ELSE NULL END,
    'next_run_at_utc', v_next_run_at_utc,
    'failed_at_utc', v_now,
    'error_json', p_error_json,
    'obsolete', v_is_obsolete,
    'obsolete_reason', v_obsolete_reason,
    'statement_timeout', v_is_statement_timeout,
    'deterministic_no_change_loop', v_is_no_change_loop
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_enqueue_scope(p_snapshot_run_id uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_payload_json jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run_pay_date date;
  v_run_week_ending_cutoff date;
  v_run_pay_week_start date;
  v_run_eligibility_from_date date;
  v_run_eligibility_to_date date;
  v_run_status text := NULL;
  v_run_failed_at_utc timestamptz := NULL;
  v_candidate_id_value uuid;
  v_enqueued_count integer := 0;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_payload_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_scope_payload_json jsonb := '{}'::jsonb;
  v_scope_context_json jsonb := '{}'::jsonb;
BEGIN
  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  SELECT sr.pay_date,
         sr.week_ending_cutoff,
         sr.pay_week_start,
         sr.eligibility_from_date,
         sr.eligibility_to_date,
         sr.status,
         sr.failed_at_utc
  INTO v_run_pay_date,
       v_run_week_ending_cutoff,
       v_run_pay_week_start,
       v_run_eligibility_from_date,
       v_run_eligibility_to_date,
       v_run_status,
       v_run_failed_at_utc
  FROM public.banking_pay_snapshot_runs AS sr
  WHERE sr.id = p_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  IF p_candidate_id IS NULL AND p_client_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'pay_date', v_run_pay_date::text,
      'week_ending_cutoff', v_run_week_ending_cutoff::text,
      'pay_week_start', v_run_pay_week_start::text,
      'eligibility_from_date', v_run_eligibility_from_date::text,
      'eligibility_to_date', v_run_eligibility_to_date::text,
      'candidate_filter_id', NULL,
      'client_filter_id', NULL,
      'enqueued_count', 0,
      'candidate_ids', '[]'::jsonb,
      'no_op', true,
      'reason', 'FULL_SCOPE_FORBIDDEN',
      'run_status', v_run_status,
      'run_failed_at_utc', v_run_failed_at_utc,
      'force_seed', false
    );
  END IF;

  v_scope_payload_json := public._pay_workbench_merge_targeted_scope_payload(
    v_payload_json,
    jsonb_build_object(
      'scope_pay_date', v_run_pay_date::text,
      'scope_week_ending_cutoff', v_run_week_ending_cutoff::text,
      'scope_candidate_filter_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'scope_client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END
    )
  );

  IF p_candidate_id IS NOT NULL THEN
    PERFORM public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => p_snapshot_run_id,
      p_candidate_id => p_candidate_id,
      p_reason => 'SNAPSHOT_SCOPE_WARMUP',
      p_actor_user_id => p_actor_user_id,
      p_payload_json => v_scope_payload_json
    );

    v_enqueued_count := 1;
    v_candidate_ids := jsonb_build_array(p_candidate_id::text);

    RETURN jsonb_build_object(
      'ok', true,
      'snapshot_run_id', p_snapshot_run_id::text,
      'pay_date', v_run_pay_date::text,
      'week_ending_cutoff', v_run_week_ending_cutoff::text,
      'pay_week_start', v_run_pay_week_start::text,
      'eligibility_from_date', v_run_eligibility_from_date::text,
      'eligibility_to_date', v_run_eligibility_to_date::text,
      'candidate_filter_id', p_candidate_id::text,
      'client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'enqueued_count', v_enqueued_count,
      'candidate_ids', v_candidate_ids,
      'no_op', false,
      'force_seed', false
    );
  END IF;

  v_scope_context_json := public.pay_preview_build_context(
    p_pay_date => v_run_pay_date,
    p_week_ending_cutoff => v_run_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => NULL::uuid,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_scope_payload_json
  );

  FOR v_candidate_id_value IN
    SELECT DISTINCT NULLIF(BTRIM(scope_candidate_id.value), '')::uuid AS candidate_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_scope_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_scope_context_json->'scope_candidate_ids', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS scope_candidate_id(value)
    WHERE NULLIF(BTRIM(scope_candidate_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ORDER BY candidate_id
  LOOP
    PERFORM public.pay_workbench_enqueue_candidate_refresh(
      p_snapshot_run_id => p_snapshot_run_id,
      p_candidate_id => v_candidate_id_value,
      p_reason => 'SNAPSHOT_SCOPE_WARMUP',
      p_actor_user_id => p_actor_user_id,
      p_payload_json => v_scope_payload_json
    );

    v_enqueued_count := v_enqueued_count + 1;
    v_candidate_ids := v_candidate_ids || jsonb_build_array(v_candidate_id_value::text);
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', p_snapshot_run_id::text,
    'pay_date', v_run_pay_date::text,
    'week_ending_cutoff', v_run_week_ending_cutoff::text,
    'pay_week_start', v_run_pay_week_start::text,
    'eligibility_from_date', v_run_eligibility_from_date::text,
    'eligibility_to_date', v_run_eligibility_to_date::text,
    'candidate_filter_id', NULL,
    'client_filter_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
    'enqueued_count', v_enqueued_count,
    'candidate_ids', v_candidate_ids,
    'no_op', false,
    'force_seed', false
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_preview_build_context(p_pay_date date, p_week_ending_cutoff date, p_actor_user_id uuid DEFAULT NULL::uuid, p_candidate_id uuid DEFAULT NULL::uuid, p_client_id uuid DEFAULT NULL::uuid, p_preview_decisions_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
  v_effective_week_ending_cutoff date := DATE '9999-12-31';
  v_pay_week_start date;
  v_pay_eligibility_months_back integer := 6;
  v_pay_eligibility_weeks_ahead integer := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean;
  v_rail_supports_name_check boolean;
  v_rail_supports_auto_execute boolean;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_scope_candidate_count integer := 0;
  v_preview_decisions_root jsonb := '{}'::jsonb;
  v_preview_case_resolutions jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  IF to_regclass('public.settings_finance_windows') IS NULL THEN
    RAISE EXCEPTION 'settings_finance_windows missing';
  END IF;

  v_pay_week_start := public._pay_week_start_monday(p_pay_date);

  SELECT
    public.settings_finance_windows.vat_rate_pct,
    public.settings_finance_windows.erni_pct
  INTO
    v_vat_rate_pct,
    v_erni_pct
  FROM public.settings_finance_windows
  WHERE p_pay_date >= public.settings_finance_windows.date_from
    AND p_pay_date <= COALESCE(public.settings_finance_windows.date_to, 'infinity'::date)
  ORDER BY public.settings_finance_windows.date_from DESC, public.settings_finance_windows.id DESC
  LIMIT 1;

  IF v_vat_rate_pct IS NULL OR v_erni_pct IS NULL THEN
    RAISE EXCEPTION 'No finance window found for pay_date %', p_pay_date;
  END IF;

  SELECT
    public.settings_defaults.rail_provider_default,
    public.settings_defaults.rail_env_default,
    public.settings_defaults.rail_supports_scheduling,
    public.settings_defaults.rail_supports_name_check,
    public.settings_defaults.rail_supports_auto_execute,
    public.settings_defaults.default_schedule_umbrella_local,
    public.settings_defaults.default_schedule_paye_local,
    public.settings_defaults.funds_warning_hours_json,
    public.settings_defaults.pay_eligibility_months_back,
    public.settings_defaults.pay_eligibility_weeks_ahead
  INTO
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id ASC
  LIMIT 1;

  IF v_rail_provider_default IS NULL OR v_rail_env_default IS NULL THEN
    RAISE EXCEPTION 'settings_defaults missing or not populated';
  END IF;

  v_pay_eligibility_months_back := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_months_back, 6), 120));
  v_pay_eligibility_weeks_ahead := GREATEST(0, LEAST(COALESCE(v_pay_eligibility_weeks_ahead, 2), 52));

  v_eligibility_from_date := (v_today_uk - (v_pay_eligibility_months_back::text || ' months')::interval)::date;
  v_eligibility_to_date := (v_today_uk + (v_pay_eligibility_weeks_ahead::text || ' weeks')::interval)::date;

  v_need_name_check := (COALESCE(v_rail_supports_name_check, false) = true)
                       AND (UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV');
  v_requires_payee_map := (UPPER(BTRIM(COALESCE(v_rail_provider_default, ''))) <> 'CSV');

  v_preview_decisions_root := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object'
      THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_preview_case_resolutions := CASE
    WHEN jsonb_typeof(v_preview_decisions_root->'case_resolutions') = 'object'
      THEN COALESCE(v_preview_decisions_root->'case_resolutions', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_preview_decisions_root->>'refresh_scope_kind', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') AS targeted_timesheet_id
    FROM (
      SELECT targeted_scope_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'array' THEN v_preview_decisions_root->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_preview_decisions_root->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'targeted_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_array(value)
    ) AS targeted_scope_values
    WHERE NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') AS linked_timesheet_id
    FROM (
      SELECT linked_scope_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'array' THEN v_preview_decisions_root->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_preview_decisions_root->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_preview_decisions_root->>'linked_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_array(value)
    ) AS linked_scope_values
    WHERE NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') IS NOT NULL
  ) AS linked_scope_ids;

  v_paye_guardrails := public.pay_paye_guardrails(
    p_pay_date => p_pay_date,
    p_ignore_pay_batch_id => NULL::uuid,
    p_actor_user_id => p_actor_user_id
  );

  IF p_candidate_id IS NOT NULL THEN
    SELECT
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.candidates AS c
          WHERE c.id = p_candidate_id
        ) THEN jsonb_build_array(p_candidate_id::text)
        ELSE '[]'::jsonb
      END,
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.candidates AS c
          WHERE c.id = p_candidate_id
        ) THEN 1
        ELSE 0
      END
    INTO
      v_scope_candidate_ids,
      v_scope_candidate_count;
  ELSE
    IF p_client_id IS NOT NULL THEN
      WITH force_include AS (
        SELECT DISTINCT
          public.timesheet_payment_overrides.timesheet_id
        FROM public.timesheet_payment_overrides
        WHERE public.timesheet_payment_overrides.cleared_at_utc IS NULL
          AND public.timesheet_payment_overrides.consumed_at_utc IS NULL
          AND public.timesheet_payment_overrides.consumed_by_pay_batch_id IS NULL
          AND UPPER(COALESCE(public.timesheet_payment_overrides.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
          AND public.timesheet_payment_overrides.timesheet_id IS NOT NULL
      ),
      timesheet_scope AS (
        SELECT DISTINCT
          public.timesheets_financials.candidate_id
        FROM public.timesheets_financials
        JOIN public.timesheets
          ON public.timesheets.timesheet_id = public.timesheets_financials.timesheet_id
        JOIN public.candidates
          ON public.candidates.id = public.timesheets_financials.candidate_id
        LEFT JOIN public.timesheet_pay_state
          ON public.timesheet_pay_state.timesheet_id = public.timesheets_financials.timesheet_id
        LEFT JOIN force_include
          ON force_include.timesheet_id = public.timesheets_financials.timesheet_id
        WHERE public.timesheets_financials.is_current = true
          AND COALESCE(public.timesheets_financials.pay_on_hold, false) = false
          AND COALESCE(public.timesheets_financials.has_rate_issue, false) = false
          AND COALESCE(public.timesheets_financials.has_pay_channel_issue, false) = false
          AND UPPER(COALESCE(public.timesheets_financials.processing_status::text, '')) NOT IN ('UNASSIGNED', 'CLIENT_UNRESOLVED', 'RATE_MISSING', 'PAY_CHANNEL_MISSING')
          AND UPPER(COALESCE(public.candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
          AND (
            (
              public.timesheets.authorised_at_server IS NOT NULL
              AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) >= v_eligibility_from_date
              AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_eligibility_to_date
              AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_effective_week_ending_cutoff
            )
            OR force_include.timesheet_id IS NOT NULL
            OR (
              public.timesheet_pay_state.last_settled_snapshot_json IS NOT NULL
              AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) >= v_eligibility_from_date
              AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_effective_week_ending_cutoff
            )
          )
          AND public.timesheets_financials.client_id = p_client_id
      ),
      finance_scope AS (
        SELECT DISTINCT
          public.v_finance_cases_register.candidate_id
        FROM public.v_finance_cases_register
        JOIN public.candidates
          ON public.candidates.id = public.v_finance_cases_register.candidate_id
        WHERE public.v_finance_cases_register.case_type IN (
            'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
            'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
          AND UPPER(COALESCE(public.v_finance_cases_register.status::text, '')) = 'ACTIVE'
          AND COALESCE(public.v_finance_cases_register.outstanding_amount, 0) > 0
          AND UPPER(COALESCE(public.candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
          AND NOT (
            public.v_finance_cases_register.active_snooze_id IS NOT NULL
            AND public.v_finance_cases_register.active_snooze_until_date IS NULL
          )
          AND (
            (
              public.v_finance_cases_register.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
              AND (
                UPPER(COALESCE(public.v_finance_cases_register.payout_status::text, '')) <> 'PAID'
                OR public.v_finance_cases_register.next_due_week_start IS NULL
                OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
              )
            )
            OR (
              public.v_finance_cases_register.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              AND (
                public.v_finance_cases_register.next_due_week_start IS NULL
                OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
              )
            )
            OR (
              public.v_finance_cases_register.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
              AND (
                public.v_finance_cases_register.next_due_week_start IS NULL
                OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
              )
            )
            OR public.v_finance_cases_register.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
          AND public.v_finance_cases_register.client_id = p_client_id
      ),
      scope_candidates AS (
        SELECT timesheet_scope.candidate_id
        FROM timesheet_scope
        UNION
        SELECT finance_scope.candidate_id
        FROM finance_scope
      )
      SELECT
        COALESCE(jsonb_agg(to_jsonb(scope_candidates.candidate_id::text) ORDER BY scope_candidates.candidate_id), '[]'::jsonb),
        COUNT(*)::integer
      INTO
        v_scope_candidate_ids,
        v_scope_candidate_count
      FROM scope_candidates;
    ELSE
      IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
         OR jsonb_array_length(COALESCE(v_targeted_timesheet_ids, '[]'::jsonb)) > 0
         OR jsonb_array_length(COALESCE(v_linked_timesheet_ids, '[]'::jsonb)) > 0 THEN
        WITH targeted_scope_timesheet_ids AS (
          SELECT DISTINCT NULLIF(BTRIM(scope_timesheet_ids.scope_timesheet_id_raw), '')::uuid AS timesheet_id
          FROM (
            SELECT jsonb_array_elements_text(COALESCE(v_targeted_timesheet_ids, '[]'::jsonb)) AS scope_timesheet_id_raw
            UNION ALL
            SELECT jsonb_array_elements_text(COALESCE(v_linked_timesheet_ids, '[]'::jsonb)) AS scope_timesheet_id_raw
          ) AS scope_timesheet_ids
          WHERE NULLIF(BTRIM(scope_timesheet_ids.scope_timesheet_id_raw), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        ),
        scope_candidates AS (
          SELECT DISTINCT COALESCE(public.timesheets_financials.candidate_id, public.contracts.candidate_id) AS candidate_id
          FROM targeted_scope_timesheet_ids
          JOIN public.timesheets
            ON public.timesheets.timesheet_id = targeted_scope_timesheet_ids.timesheet_id
          LEFT JOIN public.timesheets_financials
            ON public.timesheets_financials.timesheet_id = public.timesheets.timesheet_id
           AND public.timesheets_financials.is_current = true
          LEFT JOIN public.contracts
            ON public.contracts.id = public.timesheets.contract_id
          WHERE COALESCE(public.timesheets_financials.candidate_id, public.contracts.candidate_id) IS NOT NULL
        )
        SELECT
          COALESCE(jsonb_agg(to_jsonb(scope_candidates.candidate_id::text) ORDER BY scope_candidates.candidate_id), '[]'::jsonb),
          COUNT(*)::integer
        INTO
          v_scope_candidate_ids,
          v_scope_candidate_count
        FROM scope_candidates;
      ELSE
        WITH force_include AS (
          SELECT DISTINCT
            public.timesheet_payment_overrides.timesheet_id
          FROM public.timesheet_payment_overrides
          WHERE public.timesheet_payment_overrides.cleared_at_utc IS NULL
            AND public.timesheet_payment_overrides.consumed_at_utc IS NULL
            AND public.timesheet_payment_overrides.consumed_by_pay_batch_id IS NULL
            AND UPPER(COALESCE(public.timesheet_payment_overrides.override_type, '')) = 'ADVANCE_THIS_PAYMENT'
            AND public.timesheet_payment_overrides.timesheet_id IS NOT NULL
        ),
        timesheet_scope AS (
          SELECT DISTINCT
            public.timesheets_financials.candidate_id
          FROM public.timesheets_financials
          JOIN public.timesheets
            ON public.timesheets.timesheet_id = public.timesheets_financials.timesheet_id
          JOIN public.candidates
            ON public.candidates.id = public.timesheets_financials.candidate_id
          LEFT JOIN public.timesheet_pay_state
            ON public.timesheet_pay_state.timesheet_id = public.timesheets_financials.timesheet_id
          LEFT JOIN force_include
            ON force_include.timesheet_id = public.timesheets_financials.timesheet_id
          WHERE public.timesheets_financials.is_current = true
            AND COALESCE(public.timesheets_financials.pay_on_hold, false) = false
            AND COALESCE(public.timesheets_financials.has_rate_issue, false) = false
            AND COALESCE(public.timesheets_financials.has_pay_channel_issue, false) = false
            AND UPPER(COALESCE(public.timesheets_financials.processing_status::text, '')) NOT IN ('UNASSIGNED', 'CLIENT_UNRESOLVED', 'RATE_MISSING', 'PAY_CHANNEL_MISSING')
            AND UPPER(COALESCE(public.candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
            AND (
              (
                public.timesheets.authorised_at_server IS NOT NULL
                AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) >= v_eligibility_from_date
                AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_eligibility_to_date
                AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_effective_week_ending_cutoff
              )
              OR force_include.timesheet_id IS NOT NULL
              OR (
                public.timesheet_pay_state.last_settled_snapshot_json IS NOT NULL
                AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) >= v_eligibility_from_date
                AND COALESCE(
                CASE
                  WHEN UPPER(COALESCE(public.timesheets.sheet_scope::text, '')) = 'DAILY'
                   AND public.timesheets.worked_start_iso IS NOT NULL
                    THEN (public.timesheets.worked_start_iso AT TIME ZONE 'Europe/London')::date
                  ELSE NULL::date
                END,
                public.timesheets.week_ending_date::date
              ) <= v_effective_week_ending_cutoff
              )
            )
        ),
        finance_scope AS (
          SELECT DISTINCT
            public.v_finance_cases_register.candidate_id
          FROM public.v_finance_cases_register
          JOIN public.candidates
            ON public.candidates.id = public.v_finance_cases_register.candidate_id
          WHERE public.v_finance_cases_register.case_type IN (
              'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
              'OVERPAYMENT'::public.pay_finance_case_type_enum,
              'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
              'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
            )
            AND UPPER(COALESCE(public.v_finance_cases_register.status::text, '')) = 'ACTIVE'
            AND COALESCE(public.v_finance_cases_register.outstanding_amount, 0) > 0
            AND UPPER(COALESCE(public.candidates.pay_method, '')) IN ('PAYE', 'UMBRELLA')
            AND NOT (
              public.v_finance_cases_register.active_snooze_id IS NOT NULL
              AND public.v_finance_cases_register.active_snooze_until_date IS NULL
            )
            AND (
              (
                public.v_finance_cases_register.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
                AND (
                  UPPER(COALESCE(public.v_finance_cases_register.payout_status::text, '')) <> 'PAID'
                  OR public.v_finance_cases_register.next_due_week_start IS NULL
                  OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
                )
              )
              OR (
                public.v_finance_cases_register.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
                AND (
                  public.v_finance_cases_register.next_due_week_start IS NULL
                  OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
                )
              )
              OR (
                public.v_finance_cases_register.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
                AND (
                  public.v_finance_cases_register.next_due_week_start IS NULL
                  OR public.v_finance_cases_register.next_due_week_start <= v_pay_week_start
                )
              )
              OR public.v_finance_cases_register.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
            )
        ),
        scope_candidates AS (
          SELECT timesheet_scope.candidate_id
          FROM timesheet_scope
          UNION
          SELECT finance_scope.candidate_id
          FROM finance_scope
        )
        SELECT
          COALESCE(jsonb_agg(to_jsonb(scope_candidates.candidate_id::text) ORDER BY scope_candidates.candidate_id), '[]'::jsonb),
          COUNT(*)::integer
        INTO
          v_scope_candidate_ids,
          v_scope_candidate_count
        FROM scope_candidates;
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'pay_date', p_pay_date::text,
    'pay_week_start', v_pay_week_start::text,
    'week_ending_cutoff_date', v_effective_week_ending_cutoff::text,
    'eligibility', jsonb_build_object(
      'today_uk', v_today_uk::text,
      'from_date', v_eligibility_from_date::text,
      'to_date', v_eligibility_to_date::text,
      'months_back', v_pay_eligibility_months_back,
      'weeks_ahead', v_pay_eligibility_weeks_ahead
    ),
    'filters', jsonb_build_object(
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END
    ),
    'finance', jsonb_build_object(
      'vat_rate_pct', v_vat_rate_pct,
      'erni_pct', v_erni_pct
    ),
    'settings', jsonb_build_object(
      'rail', jsonb_build_object(
        'provider_default', v_rail_provider_default,
        'env_default', v_rail_env_default,
        'supports_scheduling', v_rail_supports_scheduling,
        'supports_name_check', v_rail_supports_name_check,
        'supports_auto_execute', v_rail_supports_auto_execute,
        'need_name_check', v_need_name_check,
        'requires_payee_map', v_requires_payee_map
      ),
      'schedule_defaults', jsonb_build_object(
        'umbrella_local', v_default_schedule_umbrella_local,
        'paye_local', v_default_schedule_paye_local
      ),
      'funds_warning_hours_json', COALESCE(v_funds_warning_hours_json, '[]'::jsonb)
    ),
    'paye_guardrails', COALESCE(v_paye_guardrails, '{}'::jsonb),
    'scope_candidate_ids', COALESCE(v_scope_candidate_ids, '[]'::jsonb),
    'scope_candidate_count', v_scope_candidate_count,
    'preview_decisions_json', v_preview_decisions_root,
    'preview_case_resolutions', v_preview_case_resolutions,
    'refresh_scope_kind', v_refresh_scope_kind,
    'targeted_timesheet_ids', COALESCE(v_targeted_timesheet_ids, '[]'::jsonb),
    'linked_timesheet_ids', COALESCE(v_linked_timesheet_ids, '[]'::jsonb)
  );
END;
$function$;







CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_rollup(
  p_context_json jsonb,
  p_candidate_effective_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_effective_root jsonb := COALESCE(p_candidate_effective_json, '{}'::jsonb);
  v_candidate_row_source jsonb := '{}'::jsonb;
  v_candidate_id text := '';
  v_display_name text := '';
  v_tms_ref text := '';
  v_current_pay_method text := '';
  v_case_states_input jsonb := '[]'::jsonb;
  v_lines_input jsonb := '[]'::jsonb;
  v_payees_input jsonb := '[]'::jsonb;
  v_itemisation_input jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines_input jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_hidden_recovery_template_line_count integer := 0;
  v_timesheet_snapshots_input jsonb := '[]'::jsonb;
  v_explicit_blocked_input jsonb := '[]'::jsonb;
  v_explicit_do_not_pay_input jsonb := '[]'::jsonb;
  v_explicit_snoozed_input jsonb := '[]'::jsonb;
  v_normalized_case_states jsonb := '[]'::jsonb;
  v_normalized_lines jsonb := '[]'::jsonb;
  v_normalized_payees jsonb := '[]'::jsonb;
  v_normalized_itemisation jsonb := '[]'::jsonb;
  v_timesheet_snapshots_json jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_do_not_pay_items jsonb := '[]'::jsonb;
  v_snoozed_items jsonb := '[]'::jsonb;
  v_first_payee_json jsonb := NULL;
  v_primary_payee_json jsonb := NULL;
  v_primary_line_json jsonb := NULL;
  v_primary_payee_entity_kind text := '';
  v_primary_payee_entity_id text := '';
  v_primary_bank_details_hash text := '';
  v_primary_payee_bank_hash text := '';
  v_primary_bank_details_hash_snapshot text := '';
  v_primary_snapshot_bank_details_hash text := '';
  v_primary_name_check_status text := '';
  v_primary_name_check_has_override boolean := false;
  v_primary_payee_map_present boolean := false;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_candidate_blockers jsonb := '[]'::jsonb;
  v_has_blocked_case boolean := false;
  v_case_resolution_state_count integer := 0;
  v_blocked_case_state_count integer := 0;
  v_canonical_preview_line_count integer := 0;
  v_ready_preview_line_count integer := 0;
  v_blocked_preview_line_count integer := 0;
  v_do_not_pay_line_count integer := 0;
  v_snoozed_line_count integer := 0;
  v_payees_count integer := 0;
  v_total_amount_ex_vat numeric := 0;
  v_total_amount_vat numeric := 0;
  v_total_amount_inc_vat numeric := 0;
  v_draftable_amount_ex_vat numeric := 0;
  v_draftable_amount_vat numeric := 0;
  v_draftable_amount_inc_vat numeric := 0;
  v_has_any_delta boolean := false;
  v_has_review_required_blocker boolean := false;
  v_is_ready_for_draft boolean := false;
  v_is_review_required boolean := false;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_candidate_row_base jsonb := '{}'::jsonb;
  v_candidate_row jsonb := '{}'::jsonb;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_effective_root) <> 'object' THEN
    RAISE EXCEPTION 'p_candidate_effective_json must be a JSON object';
  END IF;

  v_candidate_row_source := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'candidate_row') = 'object'
      THEN COALESCE(v_candidate_effective_root->'candidate_row', '{}'::jsonb)
    ELSE v_candidate_effective_root
  END;

  v_candidate_id := BTRIM(COALESCE(
    v_candidate_row_source->>'candidate_id',
    v_candidate_effective_root->>'candidate_id',
    ''
  ));

  IF v_candidate_id = '' THEN
    RAISE EXCEPTION 'candidate_id is required on p_candidate_effective_json';
  END IF;

  v_display_name := BTRIM(COALESCE(
    v_candidate_row_source->>'display_name',
    v_candidate_row_source->>'candidate_name',
    v_candidate_row_source->>'candidate_display_name',
    v_candidate_effective_root->>'display_name',
    v_candidate_effective_root->>'candidate_name',
    v_candidate_effective_root->>'candidate_display_name',
    ''
  ));

  v_tms_ref := BTRIM(COALESCE(
    v_candidate_row_source->>'tms_ref',
    v_candidate_row_source->>'candidate_tms_ref',
    v_candidate_effective_root->>'tms_ref',
    v_candidate_effective_root->>'candidate_tms_ref',
    ''
  ));

  v_case_states_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'case_resolution_states') = 'array'
      THEN COALESCE(v_candidate_effective_root->'case_resolution_states', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'case_resolution_states') = 'array'
      THEN COALESCE(v_candidate_row_source->'case_resolution_states', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_lines_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'canonical_preview_lines') = 'array'
      THEN COALESCE(v_candidate_effective_root->'canonical_preview_lines', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'canonical_preview_lines') = 'array'
      THEN COALESCE(v_candidate_row_source->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_payees_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'payees') = 'array'
      THEN COALESCE(v_candidate_effective_root->'payees', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'payees') = 'array'
      THEN COALESCE(v_candidate_row_source->'payees', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_itemisation_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'itemisation') = 'array'
      THEN COALESCE(v_candidate_effective_root->'itemisation', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'itemisation') = 'array'
      THEN COALESCE(v_candidate_row_source->'itemisation', '[]'::jsonb)
    ELSE v_lines_input
  END;

  v_explicit_blocked_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'blocked_items') = 'array'
      THEN COALESCE(v_candidate_effective_root->'blocked_items', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'blocked_items') = 'array'
      THEN COALESCE(v_candidate_row_source->'blocked_items', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_explicit_do_not_pay_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'do_not_pay_items') = 'array'
      THEN COALESCE(v_candidate_effective_root->'do_not_pay_items', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'do_not_pay_items') = 'array'
      THEN COALESCE(v_candidate_row_source->'do_not_pay_items', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_explicit_snoozed_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'snoozed_items') = 'array'
      THEN COALESCE(v_candidate_effective_root->'snoozed_items', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'snoozed_items') = 'array'
      THEN COALESCE(v_candidate_row_source->'snoozed_items', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_baseline_component_rows := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'baseline_component_rows') = 'array'
      THEN COALESCE(v_candidate_effective_root->'baseline_component_rows', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_timesheet_snapshots_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'timesheet_snapshots_json') = 'array'
      THEN COALESCE(v_candidate_effective_root->'timesheet_snapshots_json', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'timesheet_snapshots_json') = 'array'
      THEN COALESCE(v_candidate_row_source->'timesheet_snapshots_json', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_hidden_recovery_template_lines_input := CASE
    WHEN jsonb_typeof(v_candidate_effective_root->'hidden_recovery_template_lines') = 'array'
      THEN COALESCE(v_candidate_effective_root->'hidden_recovery_template_lines', '[]'::jsonb)
    WHEN jsonb_typeof(v_candidate_row_source->'hidden_recovery_template_lines') = 'array'
      THEN COALESCE(v_candidate_row_source->'hidden_recovery_template_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_normalized_case_states
  FROM jsonb_array_elements(v_case_states_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_normalized_lines
  FROM jsonb_array_elements(v_lines_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_normalized_payees
  FROM jsonb_array_elements(v_payees_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_normalized_itemisation
  FROM jsonb_array_elements(v_itemisation_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_timesheet_snapshots_json
  FROM jsonb_array_elements(v_timesheet_snapshots_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        CASE
          WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
            THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
          ELSE elem.value
        END
        ORDER BY elem.ord
      ),
      '[]'::jsonb
    )
  INTO v_hidden_recovery_template_lines
  FROM jsonb_array_elements(v_hidden_recovery_template_lines_input) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object';

  v_hidden_recovery_template_line_count := jsonb_array_length(v_hidden_recovery_template_lines);

  IF jsonb_typeof(v_explicit_blocked_input) = 'array' AND jsonb_array_length(v_explicit_blocked_input) > 0 THEN
    SELECT
      COALESCE(
        jsonb_agg(
          CASE
            WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
              THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
            ELSE elem.value
          END
          ORDER BY elem.ord
        ),
        '[]'::jsonb
      )
    INTO v_blocked_items
    FROM jsonb_array_elements(v_explicit_blocked_input) WITH ORDINALITY AS elem(value, ord)
    WHERE jsonb_typeof(elem.value) = 'object';
  ELSE
    SELECT
      COALESCE(
        jsonb_agg(elem.value ORDER BY elem.ord),
        '[]'::jsonb
      )
    INTO v_blocked_items
    FROM jsonb_array_elements(v_normalized_lines) WITH ORDINALITY AS elem(value, ord)
    WHERE (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
    );
  END IF;

  IF jsonb_typeof(v_explicit_do_not_pay_input) = 'array' AND jsonb_array_length(v_explicit_do_not_pay_input) > 0 THEN
    SELECT
      COALESCE(
        jsonb_agg(
          CASE
            WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
              THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
            ELSE elem.value
          END
          ORDER BY elem.ord
        ),
        '[]'::jsonb
      )
    INTO v_do_not_pay_items
    FROM jsonb_array_elements(v_explicit_do_not_pay_input) WITH ORDINALITY AS elem(value, ord)
    WHERE jsonb_typeof(elem.value) = 'object';
  ELSE
    SELECT
      COALESCE(
        jsonb_agg(elem.value ORDER BY elem.ord),
        '[]'::jsonb
      )
    INTO v_do_not_pay_items
    FROM jsonb_array_elements(v_normalized_lines) WITH ORDINALITY AS elem(value, ord)
    WHERE (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_do_not_pay', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
    );
  END IF;

  IF jsonb_typeof(v_explicit_snoozed_input) = 'array' AND jsonb_array_length(v_explicit_snoozed_input) > 0 THEN
    SELECT
      COALESCE(
        jsonb_agg(
          CASE
            WHEN jsonb_typeof(elem.value) = 'object' AND COALESCE(NULLIF(BTRIM(COALESCE(elem.value->>'candidate_id', '')), ''), '') = ''
              THEN elem.value || jsonb_build_object('candidate_id', v_candidate_id)
            ELSE elem.value
          END
          ORDER BY elem.ord
        ),
        '[]'::jsonb
      )
    INTO v_snoozed_items
    FROM jsonb_array_elements(v_explicit_snoozed_input) WITH ORDINALITY AS elem(value, ord)
    WHERE jsonb_typeof(elem.value) = 'object';
  ELSE
    SELECT
      COALESCE(
        jsonb_agg(elem.value ORDER BY elem.ord),
        '[]'::jsonb
      )
    INTO v_snoozed_items
    FROM jsonb_array_elements(v_normalized_lines) WITH ORDINALITY AS elem(value, ord)
    WHERE (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_snoozed', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'SNOOZED'
    );
  END IF;

  SELECT elem.value
  INTO v_first_payee_json
  FROM jsonb_array_elements(v_normalized_payees) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object'
  ORDER BY elem.ord ASC
  LIMIT 1;

  SELECT elem.value
  INTO v_primary_line_json
  FROM jsonb_array_elements(v_normalized_lines) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object'
  ORDER BY elem.ord ASC
  LIMIT 1;

  v_current_pay_method := UPPER(BTRIM(COALESCE(
    v_candidate_row_source->>'current_pay_method',
    v_candidate_row_source->>'pay_method',
    v_candidate_row_source->>'pay_channel',
    v_candidate_effective_root->>'current_pay_method',
    v_candidate_effective_root->>'pay_method',
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'pay_channel' END,
    CASE WHEN v_first_payee_json IS NULL THEN NULL ELSE v_first_payee_json->>'current_pay_method' END,
    CASE WHEN v_first_payee_json IS NULL THEN NULL ELSE v_first_payee_json->>'pay_method' END,
    CASE WHEN v_first_payee_json IS NULL THEN NULL ELSE v_first_payee_json->>'pay_channel' END,
    ''
  )));

  SELECT elem.value
  INTO v_primary_payee_json
  FROM jsonb_array_elements(v_normalized_payees) WITH ORDINALITY AS elem(value, ord)
  WHERE jsonb_typeof(elem.value) = 'object'
  ORDER BY
    CASE
      WHEN v_current_pay_method = 'PAYE'
        AND UPPER(BTRIM(COALESCE(elem.value->>'payee_entity_kind', elem.value->>'entity_kind', ''))) = 'CANDIDATE'
        THEN 0
      WHEN v_current_pay_method <> ''
        AND v_current_pay_method <> 'PAYE'
        AND UPPER(BTRIM(COALESCE(elem.value->>'payee_entity_kind', elem.value->>'entity_kind', ''))) = 'UMBRELLA'
        THEN 0
      WHEN UPPER(BTRIM(COALESCE(v_candidate_row_source->>'payee_entity_kind', ''))) <> ''
        AND UPPER(BTRIM(COALESCE(elem.value->>'payee_entity_kind', elem.value->>'entity_kind', ''))) = UPPER(BTRIM(COALESCE(v_candidate_row_source->>'payee_entity_kind', '')))
        THEN 1
      WHEN v_current_pay_method <> ''
        AND UPPER(BTRIM(COALESCE(elem.value->>'current_pay_method', elem.value->>'pay_method', elem.value->>'pay_channel', ''))) = v_current_pay_method
        THEN 2
      ELSE 10
    END,
    elem.ord ASC
  LIMIT 1;

  IF v_primary_payee_json IS NULL THEN
    v_primary_payee_json := v_first_payee_json;
  END IF;

  IF v_display_name = '' THEN
    v_display_name := BTRIM(COALESCE(
      CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'display_name' END,
      CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'candidate_name' END,
      CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'display_name' END,
      CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'candidate_name' END,
      ''
    ));
  END IF;

  IF v_tms_ref = '' THEN
    v_tms_ref := BTRIM(COALESCE(
      CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'tms_ref' END,
      CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'candidate_tms_ref' END,
      CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'tms_ref' END,
      CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'candidate_tms_ref' END,
      ''
    ));
  END IF;

  v_primary_payee_entity_kind := UPPER(BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'payee_entity_kind' END,
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'entity_kind' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'payee_entity_kind' END,
    v_candidate_row_source->>'payee_entity_kind',
    ''
  )));

  v_primary_payee_entity_id := BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'payee_entity_id' END,
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'entity_id' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'payee_entity_id' END,
    v_candidate_row_source->>'payee_entity_id',
    ''
  ));

  v_primary_bank_details_hash := BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'bank_details_hash' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'bank_details_hash' END,
    v_candidate_row_source->>'bank_details_hash',
    ''
  ));

  v_primary_payee_bank_hash := BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'payee_bank_hash' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'payee_bank_hash' END,
    v_candidate_row_source->>'payee_bank_hash',
    v_primary_bank_details_hash,
    ''
  ));

  v_primary_bank_details_hash_snapshot := BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'bank_details_hash_snapshot' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'bank_details_hash_snapshot' END,
    v_candidate_row_source->>'bank_details_hash_snapshot',
    ''
  ));

  v_primary_snapshot_bank_details_hash := BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'snapshot_bank_details_hash' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'snapshot_bank_details_hash' END,
    v_candidate_row_source->>'snapshot_bank_details_hash',
    v_primary_bank_details_hash_snapshot,
    ''
  ));

  v_primary_name_check_status := UPPER(BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'name_check_status' END,
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json #>> '{name_check,status}' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'name_check_status' END,
    v_candidate_row_source->>'name_check_status',
    ''
  )));

  v_primary_name_check_has_override := COALESCE(LOWER(BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'name_check_has_override' END,
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json #>> '{name_check,has_override}' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'name_check_has_override' END,
    v_candidate_row_source->>'name_check_has_override',
    'false'
  ))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  v_primary_payee_map_present := COALESCE(LOWER(BTRIM(COALESCE(
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json->>'payee_map_present' END,
    CASE WHEN v_primary_payee_json IS NULL THEN NULL ELSE v_primary_payee_json #>> '{payee_map,present}' END,
    CASE WHEN v_primary_line_json IS NULL THEN NULL ELSE v_primary_line_json->>'payee_map_present' END,
    v_candidate_row_source->>'payee_map_present',
    'false'
  ))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  v_need_name_check := COALESCE(LOWER(BTRIM(COALESCE(v_context_json #>> '{settings,rail,need_name_check}', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');
  v_requires_payee_map := COALESCE(LOWER(BTRIM(COALESCE(v_context_json #>> '{settings,rail,requires_payee_map}', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_normalized_case_states) AS elem(value)
    WHERE COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
  )
  INTO v_has_blocked_case;

  SELECT
    COALESCE(jsonb_agg(to_jsonb(blocker_distinct.code) ORDER BY blocker_distinct.code), '[]'::jsonb)
  INTO v_candidate_blockers
  FROM (
    SELECT DISTINCT blocker_codes.code
    FROM (
      SELECT UPPER(BTRIM(explicit_code.value)) AS code
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_candidate_row_source->'blockers') = 'array' THEN COALESCE(v_candidate_row_source->'blockers', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS explicit_code(value)
      WHERE UPPER(BTRIM(explicit_code.value)) NOT IN ('BLOCKED_BANK_DETAILS', 'BLOCKED_NO_PAYEE_MAP', 'BLOCKED_NAME_CHECK')

      UNION ALL

      SELECT UPPER(BTRIM(line_code.value)) AS code
      FROM jsonb_array_elements(v_normalized_lines) AS line_elem(value)
      CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(line_elem.value->'blockers') = 'array' THEN COALESCE(line_elem.value->'blockers', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS line_code(value)

      UNION ALL

      SELECT UPPER(BTRIM(payee_code.value)) AS code
      FROM jsonb_array_elements_text(
        CASE
          WHEN v_primary_payee_json IS NOT NULL AND jsonb_typeof(v_primary_payee_json->'blockers') = 'array'
            THEN COALESCE(v_primary_payee_json->'blockers', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS payee_code(value)

      UNION ALL

      SELECT 'BLOCKED_FINANCE_CASE' AS code
      WHERE v_has_blocked_case = true

      UNION ALL

      SELECT 'BLOCKED_BANK_DETAILS' AS code
      WHERE v_current_pay_method <> ''
        AND COALESCE(v_primary_bank_details_hash, '') = ''
        AND (COALESCE(v_primary_payee_entity_kind, '') <> '' OR COALESCE(v_primary_payee_entity_id, '') <> '')

      UNION ALL

      SELECT 'BLOCKED_NO_PAYEE_MAP' AS code
      WHERE v_requires_payee_map = true
        AND v_current_pay_method <> ''
        AND COALESCE(v_primary_bank_details_hash, '') <> ''
        AND v_primary_payee_map_present = false

      UNION ALL

      SELECT 'BLOCKED_NAME_CHECK' AS code
      WHERE v_need_name_check = true
        AND v_current_pay_method <> ''
        AND COALESCE(v_primary_bank_details_hash, '') <> ''
        AND v_primary_name_check_has_override = false
        AND COALESCE(v_primary_name_check_status, '') <> 'PASS'
    ) AS blocker_codes
    WHERE COALESCE(blocker_codes.code, '') <> ''
  ) AS blocker_distinct;

  SELECT COUNT(*)::integer
  INTO v_case_resolution_state_count
  FROM jsonb_array_elements(v_normalized_case_states) AS elem(value);

  SELECT COUNT(*)::integer
  INTO v_blocked_case_state_count
  FROM jsonb_array_elements(v_normalized_case_states) AS elem(value)
  WHERE COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COUNT(*)::integer
  INTO v_canonical_preview_line_count
  FROM jsonb_array_elements(v_normalized_lines) AS elem(value);

  SELECT COUNT(*)::integer
  INTO v_ready_preview_line_count
  FROM jsonb_array_elements(v_normalized_lines) AS elem(value)
  WHERE NOT (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_do_not_pay', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'CASES_RESOLUTIONS'
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_snoozed', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'SNOOZED'
    );

  v_blocked_preview_line_count := jsonb_array_length(v_blocked_items);
  v_do_not_pay_line_count := jsonb_array_length(v_do_not_pay_items);
  v_snoozed_line_count := jsonb_array_length(v_snoozed_items);

  SELECT COUNT(*)::integer
  INTO v_payees_count
  FROM jsonb_array_elements(v_normalized_payees) AS elem(value);

  SELECT
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_ex_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_inc_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_inc_vat')::numeric ELSE 0 END), 0)
  INTO
    v_total_amount_ex_vat,
    v_total_amount_vat,
    v_total_amount_inc_vat
  FROM jsonb_array_elements(v_normalized_lines) AS elem(value);

  SELECT
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_ex_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_inc_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_inc_vat')::numeric ELSE 0 END), 0)
  INTO
    v_draftable_amount_ex_vat,
    v_draftable_amount_vat,
    v_draftable_amount_inc_vat
  FROM jsonb_array_elements(v_normalized_lines) AS elem(value)
  WHERE NOT (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_do_not_pay', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'CASES_RESOLUTIONS'
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_snoozed', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'SNOOZED'
    );

  v_has_any_delta := (v_canonical_preview_line_count > 0) OR (v_case_resolution_state_count > 0) OR (jsonb_array_length(v_normalized_itemisation) > 0);
  v_has_review_required_blocker := (jsonb_array_length(v_candidate_blockers) > 0)
                                   OR (v_blocked_case_state_count > 0)
                                   OR (v_blocked_preview_line_count > 0)
                                   OR (v_do_not_pay_line_count > 0);
  v_is_ready_for_draft := v_has_any_delta AND (v_ready_preview_line_count > 0) AND NOT v_has_review_required_blocker;
  v_is_review_required := v_has_any_delta AND v_has_review_required_blocker;

  v_summary_fragment := COALESCE(
    CASE
      WHEN jsonb_typeof(v_candidate_effective_root->'summary_fragment') = 'object' THEN v_candidate_effective_root->'summary_fragment'
      WHEN jsonb_typeof(v_candidate_row_source->'summary_fragment') = 'object' THEN v_candidate_row_source->'summary_fragment'
      ELSE '{}'::jsonb
    END,
    '{}'::jsonb
  ) || jsonb_build_object(
    'candidate_count', 1,
    'paye_candidates_count', CASE WHEN v_current_pay_method = 'PAYE' THEN 1 ELSE 0 END,
    'non_paye_payees_count', CASE WHEN v_current_pay_method = 'PAYE' THEN 0 ELSE 1 END,
    'ready_candidates_count', CASE WHEN v_is_ready_for_draft THEN 1 ELSE 0 END,
    'blocked_candidates_count', CASE WHEN v_is_review_required THEN 1 ELSE 0 END,
    'case_resolution_state_count', v_case_resolution_state_count,
    'blocked_case_state_count', v_blocked_case_state_count,
    'canonical_preview_line_count', v_canonical_preview_line_count,
    'ready_preview_line_count', v_ready_preview_line_count,
    'blocked_preview_line_count', v_blocked_preview_line_count,
    'do_not_pay_line_count', v_do_not_pay_line_count,
    'snoozed_line_count', v_snoozed_line_count,
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'payees_count', v_payees_count,
    'total_amount_ex_vat', v_total_amount_ex_vat,
    'total_amount_vat', v_total_amount_vat,
    'total_amount_inc_vat', v_total_amount_inc_vat,
    'draftable_amount_ex_vat', v_draftable_amount_ex_vat,
    'draftable_amount_vat', v_draftable_amount_vat,
    'draftable_amount_inc_vat', v_draftable_amount_inc_vat,
    'has_any_delta', v_has_any_delta,
    'has_review_required_blocker', v_has_review_required_blocker,
    'is_ready_for_draft', v_is_ready_for_draft,
    'is_review_required', v_is_review_required
  );

  v_candidate_row_base := (v_candidate_row_source
    - 'case_resolution_states'
    - 'canonical_preview_lines'
    - 'payees'
    - 'itemisation'
    - 'blocked_items'
    - 'do_not_pay_items'
    - 'snoozed_items'
    - 'hidden_recovery_template_lines'
    - 'hidden_recovery_template_line_count'
    - 'summary_fragment'
    - 'paye_candidate'
    - 'non_paye_payee');

  v_candidate_row := v_candidate_row_base || jsonb_build_object(
    'candidate_id', v_candidate_id,
    'display_name', v_display_name,
    'candidate_name', v_display_name,
    'tms_ref', v_tms_ref,
    'current_pay_method', v_current_pay_method,
    'is_ready_for_draft', v_is_ready_for_draft,
    'is_review_required', v_is_review_required,
    'ready_to_pay', v_is_ready_for_draft,
    'blockers', v_candidate_blockers,
    'payee_entity_kind', NULLIF(v_primary_payee_entity_kind, ''),
    'payee_entity_id', NULLIF(v_primary_payee_entity_id, ''),
    'bank_details_hash', NULLIF(v_primary_bank_details_hash, ''),
    'payee_bank_hash', NULLIF(v_primary_payee_bank_hash, ''),
    'bank_details_hash_snapshot', NULLIF(v_primary_bank_details_hash_snapshot, ''),
    'snapshot_bank_details_hash', NULLIF(v_primary_snapshot_bank_details_hash, ''),
    'name_check_status', NULLIF(v_primary_name_check_status, ''),
    'name_check_has_override', v_primary_name_check_has_override,
    'payee_map_present', v_primary_payee_map_present,
    'case_resolution_states', v_normalized_case_states,
    'case_resolution_state_count', v_case_resolution_state_count,
    'blocked_case_state_count', v_blocked_case_state_count,
    'canonical_preview_line_count', v_canonical_preview_line_count,
    'ready_preview_line_count', v_ready_preview_line_count,
    'blocked_preview_line_count', v_blocked_preview_line_count,
    'do_not_pay_line_count', v_do_not_pay_line_count,
    'snoozed_line_count', v_snoozed_line_count,
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'payees_count', v_payees_count,
    'total_amount_ex_vat', v_total_amount_ex_vat,
    'total_amount_vat', v_total_amount_vat,
    'total_amount_inc_vat', v_total_amount_inc_vat,
    'draftable_amount_ex_vat', v_draftable_amount_ex_vat,
    'draftable_amount_vat', v_draftable_amount_vat,
    'draftable_amount_inc_vat', v_draftable_amount_inc_vat,
    'itemisation', v_normalized_itemisation
  );

  RETURN jsonb_build_object(
    'candidate_id', v_candidate_id,
    'current_pay_method', v_current_pay_method,
    'summary_fragment', v_summary_fragment,
    'case_resolution_states', v_normalized_case_states,
    'canonical_preview_lines', v_normalized_lines,
    'payees', v_normalized_payees,
    'itemisation', v_normalized_itemisation,
    'timesheet_snapshots_json', v_timesheet_snapshots_json,
    'hidden_recovery_template_lines', v_hidden_recovery_template_lines,
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'blocked_items', v_blocked_items,
    'do_not_pay_items', v_do_not_pay_items,
    'snoozed_items', v_snoozed_items,
    'baseline_component_rows', v_baseline_component_rows,
    'paye_candidate', CASE WHEN v_current_pay_method = 'PAYE' THEN v_candidate_row ELSE NULL END,
    'non_paye_payee', CASE WHEN v_current_pay_method = 'PAYE' THEN NULL ELSE v_candidate_row END
  );
END;
$function$;







CREATE OR REPLACE FUNCTION public.pay_preview_build_candidate_baseline(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_payload jsonb := '{}'::jsonb;
  v_canonical_payload jsonb := '{}'::jsonb;
  v_timesheet_snapshot_payload jsonb := '{}'::jsonb;
  v_payload_canonical_preview_lines jsonb := '[]'::jsonb;
  v_canonical_preview_lines jsonb := '[]'::jsonb;
  v_selected_canonical_preview_lines jsonb := '[]'::jsonb;
  v_payload_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_canonical_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_result_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_result_canonical_preview_lines jsonb := '[]'::jsonb;
begin
  perform public.pay_preview_candidate_collect_scope(p_context_json, p_candidate_id);
  perform public.pay_preview_candidate_build_entitlement_rows(p_context_json, p_candidate_id);
  perform public.pay_preview_candidate_build_case_component_rows(p_context_json, p_candidate_id);
  perform public.pay_preview_candidate_build_payee_baseline(p_context_json, p_candidate_id);
  perform public.pay_preview_candidate_build_finance_case_baseline(p_context_json, p_candidate_id);
  v_canonical_payload := public.pay_preview_candidate_build_canonical_lines(p_context_json, p_candidate_id);
  v_timesheet_snapshot_payload := public.pay_preview_candidate_build_timesheet_snapshots(p_context_json, p_candidate_id);
  v_payload := public.pay_preview_candidate_build_summary_fragment(p_context_json, p_candidate_id);

  v_payload_canonical_preview_lines := CASE
    WHEN jsonb_typeof(v_payload->'canonical_preview_lines') = 'array' THEN COALESCE(v_payload->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_canonical_preview_lines := CASE
    WHEN jsonb_typeof(v_canonical_payload->'canonical_preview_lines') = 'array' THEN COALESCE(v_canonical_payload->'canonical_preview_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_selected_canonical_preview_lines := CASE
    WHEN jsonb_typeof(v_payload->'canonical_preview_lines') = 'array' THEN v_payload_canonical_preview_lines
    WHEN jsonb_typeof(v_canonical_payload->'canonical_preview_lines') = 'array' THEN v_canonical_preview_lines
    ELSE '[]'::jsonb
  END;

  v_payload_hidden_recovery_template_lines := CASE
    WHEN jsonb_typeof(v_payload->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_payload->'hidden_recovery_template_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_canonical_hidden_recovery_template_lines := CASE
    WHEN jsonb_typeof(v_canonical_payload->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_canonical_payload->'hidden_recovery_template_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  with all_hidden_template_lines as (
    select
      0 as source_rank,
      coalesce(nullif(btrim(coalesce(hidden_canonical.hidden_line->>'candidate_id', '')), ''), p_candidate_id::text) as candidate_id_text,
      coalesce(nullif(btrim(coalesce(hidden_canonical.hidden_line->>'finance_case_id', '')), ''), '') as finance_case_id_text,
      coalesce(nullif(btrim(coalesce(hidden_canonical.hidden_line->>'finance_component_id', '')), ''), '') as finance_component_id_text,
      upper(coalesce(hidden_canonical.hidden_line->>'recovery_family', '')) as recovery_family_text,
      coalesce(nullif(btrim(coalesce(hidden_canonical.hidden_line->>'source_ref', '')), ''), '') as source_ref_text,
      upper(coalesce(nullif(btrim(coalesce(hidden_canonical.hidden_line->>'pay_channel', '')), ''), 'PAYE')) as pay_channel_text,
      hidden_canonical.hidden_line as hidden_line
    from jsonb_array_elements(v_canonical_hidden_recovery_template_lines) as hidden_canonical(hidden_line)
    where jsonb_typeof(hidden_canonical.hidden_line) = 'object'

    union all

    select
      1 as source_rank,
      coalesce(nullif(btrim(coalesce(hidden_payload.hidden_line->>'candidate_id', '')), ''), p_candidate_id::text) as candidate_id_text,
      coalesce(nullif(btrim(coalesce(hidden_payload.hidden_line->>'finance_case_id', '')), ''), '') as finance_case_id_text,
      coalesce(nullif(btrim(coalesce(hidden_payload.hidden_line->>'finance_component_id', '')), ''), '') as finance_component_id_text,
      upper(coalesce(hidden_payload.hidden_line->>'recovery_family', '')) as recovery_family_text,
      coalesce(nullif(btrim(coalesce(hidden_payload.hidden_line->>'source_ref', '')), ''), '') as source_ref_text,
      upper(coalesce(nullif(btrim(coalesce(hidden_payload.hidden_line->>'pay_channel', '')), ''), 'PAYE')) as pay_channel_text,
      hidden_payload.hidden_line as hidden_line
    from jsonb_array_elements(v_payload_hidden_recovery_template_lines) as hidden_payload(hidden_line)
    where jsonb_typeof(hidden_payload.hidden_line) = 'object'
  ),
  dedup_hidden_template_lines as (
    select distinct on (
      all_hidden_template_lines.candidate_id_text,
      all_hidden_template_lines.finance_case_id_text,
      all_hidden_template_lines.finance_component_id_text,
      all_hidden_template_lines.recovery_family_text,
      all_hidden_template_lines.source_ref_text,
      all_hidden_template_lines.pay_channel_text
    )
      all_hidden_template_lines.source_rank,
      all_hidden_template_lines.candidate_id_text,
      all_hidden_template_lines.finance_case_id_text,
      all_hidden_template_lines.finance_component_id_text,
      all_hidden_template_lines.recovery_family_text,
      all_hidden_template_lines.source_ref_text,
      all_hidden_template_lines.pay_channel_text,
      all_hidden_template_lines.hidden_line
    from all_hidden_template_lines
    order by
      all_hidden_template_lines.candidate_id_text,
      all_hidden_template_lines.finance_case_id_text,
      all_hidden_template_lines.finance_component_id_text,
      all_hidden_template_lines.recovery_family_text,
      all_hidden_template_lines.source_ref_text,
      all_hidden_template_lines.pay_channel_text,
      all_hidden_template_lines.source_rank
  )
  select coalesce(
           jsonb_agg(
             dedup_hidden_template_lines.hidden_line
             order by
               dedup_hidden_template_lines.source_rank,
               dedup_hidden_template_lines.finance_case_id_text,
               dedup_hidden_template_lines.finance_component_id_text,
               dedup_hidden_template_lines.source_ref_text
           ),
           '[]'::jsonb
         )
  into v_result_hidden_recovery_template_lines
  from dedup_hidden_template_lines;

  with raw_selected_canonical_lines as (
    select
      row_number() over () as line_sort_key,
      raw_line.line_value as line_value
    from jsonb_array_elements(v_selected_canonical_preview_lines) as raw_line(line_value)
    where jsonb_typeof(raw_line.line_value) = 'object'
  )
  select coalesce(
           jsonb_agg(filtered_selected_canonical_lines.line_value order by filtered_selected_canonical_lines.line_sort_key),
           '[]'::jsonb
         )
  into v_result_canonical_preview_lines
  from (
    select
      raw_selected_canonical_lines.line_sort_key,
      raw_selected_canonical_lines.line_value
    from raw_selected_canonical_lines
    where (
      upper(coalesce(raw_selected_canonical_lines.line_value->>'line_type', '')) <> 'MANUAL_DEBT_RECOVERY'
      or upper(coalesce(raw_selected_canonical_lines.line_value->>'pay_channel', '')) <> 'PAYE'
      or upper(coalesce(raw_selected_canonical_lines.line_value->>'paye_treatment', '')) <> 'NET_DEDUCT'
      or coalesce(nullif(btrim(coalesce(raw_selected_canonical_lines.line_value->>'finance_case_id', '')), ''), '') = ''
      or exists (
        select 1
        from jsonb_array_elements(v_result_hidden_recovery_template_lines) as hidden_template_line(hidden_value)
        where jsonb_typeof(hidden_template_line.hidden_value) = 'object'
          and upper(coalesce(hidden_template_line.hidden_value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
          and upper(coalesce(nullif(btrim(coalesce(hidden_template_line.hidden_value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
          and coalesce(nullif(btrim(coalesce(hidden_template_line.hidden_value->>'finance_case_id', '')), ''), '') =
              coalesce(nullif(btrim(coalesce(raw_selected_canonical_lines.line_value->>'finance_case_id', '')), ''), '')
      )
    )
  ) as filtered_selected_canonical_lines;

  return jsonb_build_object(
    'candidate_id', coalesce(v_payload->>'candidate_id', p_candidate_id::text),
    'candidate_row', coalesce(v_payload->'candidate_row', '{}'::jsonb),
    'summary_fragment', coalesce(v_payload->'summary_fragment', '{}'::jsonb),
    'case_resolution_states', coalesce(v_payload->'case_resolution_states', '[]'::jsonb),
    'canonical_preview_lines', v_result_canonical_preview_lines,
    'hidden_recovery_template_lines', v_result_hidden_recovery_template_lines,
    'hidden_recovery_template_line_count', jsonb_array_length(v_result_hidden_recovery_template_lines),
    'payees', coalesce(v_payload->'payees', '[]'::jsonb),
    'itemisation', coalesce(v_payload->'itemisation', '[]'::jsonb),
    'blocked_items', coalesce(v_payload->'blocked_items', '[]'::jsonb),
    'do_not_pay_items', coalesce(v_payload->'do_not_pay_items', '[]'::jsonb),
    'snoozed_items', coalesce(v_payload->'snoozed_items', '[]'::jsonb),
    'baseline_component_rows', coalesce(v_payload->'baseline_component_rows', '[]'::jsonb),
    'timesheet_snapshots_json', coalesce(v_timesheet_snapshot_payload->'timesheet_snapshots_json', '[]'::jsonb)
  );
end;
$function$;



CREATE OR REPLACE FUNCTION public.pay_preview_assemble_payload(p_context_json jsonb,
  p_candidate_rollups_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_context_json jsonb := COALESCE(p_context_json, '{}'::jsonb);
  v_candidate_rollups_root jsonb := COALESCE(p_candidate_rollups_json, '[]'::jsonb);
  v_rollup jsonb;
  v_paye_candidates_raw jsonb := '[]'::jsonb;
  v_non_paye_payees_raw jsonb := '[]'::jsonb;
  v_case_resolution_states_raw jsonb := '[]'::jsonb;
  v_canonical_preview_lines_raw jsonb := '[]'::jsonb;
  v_payees_raw jsonb := '[]'::jsonb;
  v_itemisation_raw jsonb := '[]'::jsonb;
  v_blocked_items_raw jsonb := '[]'::jsonb;
  v_do_not_pay_items_raw jsonb := '[]'::jsonb;
  v_snoozed_items_raw jsonb := '[]'::jsonb;
  v_baseline_component_rows_raw jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines_raw jsonb := '[]'::jsonb;
  v_timesheet_snapshots_raw jsonb := '[]'::jsonb;
  v_paye_candidates jsonb := '[]'::jsonb;
  v_non_paye_payees jsonb := '[]'::jsonb;
  v_case_resolution_states jsonb := '[]'::jsonb;
  v_canonical_preview_lines jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_do_not_pay_items jsonb := '[]'::jsonb;
  v_snoozed_items jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_hidden_recovery_template_line_count integer := 0;
  v_timesheet_snapshots_json jsonb := '[]'::jsonb;
  v_paye_summary_breakdown jsonb := '{}'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_candidate_count integer := 0;
  v_paye_candidates_count integer := 0;
  v_non_paye_payees_count integer := 0;
  v_ready_candidates_count integer := 0;
  v_blocked_candidates_count integer := 0;
  v_case_resolution_state_count integer := 0;
  v_blocked_case_state_count integer := 0;
  v_canonical_preview_line_count integer := 0;
  v_ready_preview_line_count integer := 0;
  v_blocked_preview_line_count integer := 0;
  v_do_not_pay_line_count integer := 0;
  v_snoozed_line_count integer := 0;
  v_payees_count integer := 0;
  v_total_amount_ex_vat numeric := 0;
  v_total_amount_vat numeric := 0;
  v_total_amount_inc_vat numeric := 0;
  v_draftable_amount_ex_vat numeric := 0;
  v_draftable_amount_vat numeric := 0;
  v_draftable_amount_inc_vat numeric := 0;
  v_gross_side_additions_ex_vat numeric := 0;
  v_gross_side_deductions_ex_vat numeric := 0;
  v_net_side_additions_ex_vat numeric := 0;
  v_net_side_deductions_ex_vat numeric := 0;
  v_payees_need_name_check integer := 0;
  v_payees_need_payee_map integer := 0;
  v_payees_missing_bank_details integer := 0;
BEGIN
  IF jsonb_typeof(v_context_json) <> 'object' THEN
    RAISE EXCEPTION 'p_context_json must be a JSON object';
  END IF;

  IF jsonb_typeof(v_candidate_rollups_root) <> 'array' THEN
    RAISE EXCEPTION 'p_candidate_rollups_json must be a JSON array';
  END IF;

  FOR v_rollup IN
    SELECT elem.value
    FROM jsonb_array_elements(v_candidate_rollups_root) AS elem(value)
    WHERE jsonb_typeof(elem.value) = 'object'
  LOOP
    IF jsonb_typeof(v_rollup->'paye_candidate') = 'object' THEN
      v_paye_candidates_raw := v_paye_candidates_raw || jsonb_build_array(v_rollup->'paye_candidate');
    END IF;

    IF jsonb_typeof(v_rollup->'non_paye_payee') = 'object' THEN
      v_non_paye_payees_raw := v_non_paye_payees_raw || jsonb_build_array(v_rollup->'non_paye_payee');
    END IF;

    IF jsonb_typeof(v_rollup->'case_resolution_states') = 'array' THEN
      v_case_resolution_states_raw := v_case_resolution_states_raw || COALESCE(v_rollup->'case_resolution_states', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'canonical_preview_lines') = 'array' THEN
      v_canonical_preview_lines_raw := v_canonical_preview_lines_raw || COALESCE(v_rollup->'canonical_preview_lines', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'payees') = 'array' THEN
      v_payees_raw := v_payees_raw || COALESCE(v_rollup->'payees', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'itemisation') = 'array' THEN
      v_itemisation_raw := v_itemisation_raw || COALESCE(v_rollup->'itemisation', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'blocked_items') = 'array' THEN
      v_blocked_items_raw := v_blocked_items_raw || COALESCE(v_rollup->'blocked_items', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'do_not_pay_items') = 'array' THEN
      v_do_not_pay_items_raw := v_do_not_pay_items_raw || COALESCE(v_rollup->'do_not_pay_items', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'snoozed_items') = 'array' THEN
      v_snoozed_items_raw := v_snoozed_items_raw || COALESCE(v_rollup->'snoozed_items', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'baseline_component_rows') = 'array' THEN
      v_baseline_component_rows_raw := v_baseline_component_rows_raw || COALESCE(v_rollup->'baseline_component_rows', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'timesheet_snapshots_json') = 'array' THEN
      v_timesheet_snapshots_raw := v_timesheet_snapshots_raw || COALESCE(v_rollup->'timesheet_snapshots_json', '[]'::jsonb);
    END IF;

    IF jsonb_typeof(v_rollup->'hidden_recovery_template_lines') = 'array' THEN
      v_hidden_recovery_template_lines_raw := v_hidden_recovery_template_lines_raw || COALESCE(v_rollup->'hidden_recovery_template_lines', '[]'::jsonb);
    END IF;
  END LOOP;

  SELECT
    COALESCE(
      jsonb_agg(elem.value ORDER BY BTRIM(COALESCE(elem.value->>'display_name', elem.value->>'candidate_name', '')), BTRIM(COALESCE(elem.value->>'tms_ref', '')), BTRIM(COALESCE(elem.value->>'candidate_id', ''))),
      '[]'::jsonb
    )
  INTO v_paye_candidates
  FROM jsonb_array_elements(v_paye_candidates_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(elem.value ORDER BY BTRIM(COALESCE(elem.value->>'display_name', elem.value->>'candidate_name', '')), BTRIM(COALESCE(elem.value->>'tms_ref', '')), BTRIM(COALESCE(elem.value->>'candidate_id', ''))),
      '[]'::jsonb
    )
  INTO v_non_paye_payees
  FROM jsonb_array_elements(v_non_paye_payees_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(elem.value ORDER BY BTRIM(COALESCE(elem.value->>'candidate_id', '')), BTRIM(COALESCE(elem.value->>'case_key', '')), BTRIM(COALESCE(elem.value->>'finance_case_id', '')), BTRIM(COALESCE(elem.value->>'timesheet_id', ''))),
      '[]'::jsonb
    )
  INTO v_case_resolution_states
  FROM jsonb_array_elements(v_case_resolution_states_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(elem.value ORDER BY BTRIM(COALESCE(elem.value->>'candidate_id', '')), BTRIM(COALESCE(elem.value->>'display_name', '')), BTRIM(COALESCE(elem.value->>'line_type', '')), BTRIM(COALESCE(elem.value->>'preview_row_id', elem.value->>'line_id', elem.value->>'row_id', elem.value->>'id', ''))),
      '[]'::jsonb
    )
  INTO v_canonical_preview_lines
  FROM jsonb_array_elements(v_canonical_preview_lines_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'timesheet_id', '')),
          BTRIM(COALESCE(elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'segment_id', elem.value->>'segment_stable_key', '')),
          BTRIM(COALESCE(elem.value->>'line_id', elem.value->>'preview_row_id', elem.value->>'row_id', elem.value->>'id', '')),
          BTRIM(COALESCE(elem.value->>'line_type', elem.value->>'item_type', elem.value->>'category', elem.value->>'component_kind', elem.value->>'component_type', ''))
      ),
      '[]'::jsonb
    )
  INTO v_itemisation
  FROM jsonb_array_elements(v_itemisation_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'timesheet_id', elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'segment_id', elem.value->>'segment_stable_key', elem.value->>'line_id', elem.value->>'preview_row_id', elem.value->>'row_id', elem.value->>'id', '')),
          BTRIM(COALESCE(elem.value->>'line_type', elem.value->>'category', elem.value->>'component_kind', elem.value->>'component_type', ''))
      ),
      '[]'::jsonb
    )
  INTO v_blocked_items
  FROM jsonb_array_elements(v_blocked_items_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'timesheet_id', elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'segment_id', elem.value->>'segment_stable_key', elem.value->>'line_id', elem.value->>'preview_row_id', elem.value->>'row_id', elem.value->>'id', '')),
          BTRIM(COALESCE(elem.value->>'line_type', elem.value->>'category', elem.value->>'component_kind', elem.value->>'component_type', ''))
      ),
      '[]'::jsonb
    )
  INTO v_do_not_pay_items
  FROM jsonb_array_elements(v_do_not_pay_items_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'timesheet_id', elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'segment_id', elem.value->>'segment_stable_key', elem.value->>'line_id', elem.value->>'preview_row_id', elem.value->>'row_id', elem.value->>'id', '')),
          BTRIM(COALESCE(elem.value->>'line_type', elem.value->>'category', elem.value->>'component_kind', elem.value->>'component_type', ''))
      ),
      '[]'::jsonb
    )
  INTO v_snoozed_items
  FROM jsonb_array_elements(v_snoozed_items_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'case_key', '')),
          BTRIM(COALESCE(elem.value->>'timesheet_id', '')),
          BTRIM(COALESCE(elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'finance_component_id', '')),
          BTRIM(COALESCE(elem.value->>'component_scope', '')),
          BTRIM(COALESCE(elem.value->>'source_family_key', '')),
          BTRIM(COALESCE(elem.value->>'component_key_type', '')),
          BTRIM(COALESCE(elem.value->>'component_key_value', '')),
          BTRIM(COALESCE(elem.value->>'component_fingerprint', '')),
          BTRIM(COALESCE(elem.value->>'source_basis_fingerprint', ''))
      ),
      '[]'::jsonb
    )
  INTO v_baseline_component_rows
  FROM jsonb_array_elements(v_baseline_component_rows_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(
      jsonb_agg(
        elem.value
        ORDER BY
          BTRIM(COALESCE(elem.value->>'candidate_id', '')),
          BTRIM(COALESCE(elem.value->>'finance_case_id', '')),
          BTRIM(COALESCE(elem.value->>'recovery_family', '')),
          BTRIM(COALESCE(elem.value->>'finance_component_id', '')),
          BTRIM(COALESCE(elem.value->>'source_ref', '')),
          BTRIM(COALESCE(elem.value->>'sort_order', ''))
      ),
      '[]'::jsonb
    )
  INTO v_hidden_recovery_template_lines
  FROM jsonb_array_elements(v_hidden_recovery_template_lines_raw) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  v_hidden_recovery_template_line_count := jsonb_array_length(v_hidden_recovery_template_lines);

  WITH timesheet_snapshot_elements AS (
    SELECT
      elem.value AS snapshot_json,
      elem.ordinality AS snapshot_ordinality,
      BTRIM(COALESCE(elem.value->>'candidate_id', '')) AS candidate_id_text,
      BTRIM(COALESCE(elem.value->>'timesheet_id', '')) AS timesheet_id_text
    FROM jsonb_array_elements(v_timesheet_snapshots_raw) WITH ORDINALITY AS elem(value, ordinality)
    WHERE jsonb_typeof(elem.value) = 'object'
  ), timesheet_snapshot_ranked AS (
    SELECT
      timesheet_snapshot_elements.snapshot_json,
      timesheet_snapshot_elements.snapshot_ordinality,
      timesheet_snapshot_elements.candidate_id_text,
      timesheet_snapshot_elements.timesheet_id_text,
      row_number() OVER (
        PARTITION BY timesheet_snapshot_elements.candidate_id_text, timesheet_snapshot_elements.timesheet_id_text
        ORDER BY timesheet_snapshot_elements.snapshot_ordinality ASC
      ) AS rn
    FROM timesheet_snapshot_elements
  )
  SELECT
    COALESCE(
      jsonb_agg(
        timesheet_snapshot_ranked.snapshot_json
        ORDER BY timesheet_snapshot_ranked.candidate_id_text, timesheet_snapshot_ranked.timesheet_id_text, timesheet_snapshot_ranked.snapshot_ordinality
      ),
      '[]'::jsonb
    )
  INTO v_timesheet_snapshots_json
  FROM timesheet_snapshot_ranked
  WHERE timesheet_snapshot_ranked.rn = 1;

  WITH payee_elements AS (
    SELECT
      elem.value AS payee_json,
      elem.ordinality AS payee_ordinality,
      UPPER(BTRIM(COALESCE(elem.value->>'payee_entity_kind', elem.value->>'entity_kind', ''))) AS payee_entity_kind,
      BTRIM(COALESCE(elem.value->>'payee_entity_id', elem.value->>'entity_id', '')) AS payee_entity_id,
      BTRIM(COALESCE(elem.value->>'bank_details_hash', '')) AS bank_details_hash
    FROM jsonb_array_elements(v_payees_raw) WITH ORDINALITY AS elem(value, ordinality)
    WHERE jsonb_typeof(elem.value) = 'object'
  ), payee_ranked AS (
    SELECT
      payee_elements.payee_json,
      payee_elements.payee_ordinality,
      payee_elements.payee_entity_kind,
      payee_elements.payee_entity_id,
      payee_elements.bank_details_hash,
      row_number() OVER (
        PARTITION BY payee_elements.payee_entity_kind, payee_elements.payee_entity_id, payee_elements.bank_details_hash
        ORDER BY payee_elements.payee_ordinality ASC
      ) AS rn
    FROM payee_elements
  )
  SELECT
    COALESCE(
      jsonb_agg(payee_ranked.payee_json ORDER BY payee_ranked.payee_entity_kind, payee_ranked.payee_entity_id, payee_ranked.bank_details_hash, payee_ranked.payee_ordinality),
      '[]'::jsonb
    )
  INTO v_payees
  FROM payee_ranked
  WHERE payee_ranked.rn = 1;

  SELECT COUNT(*)::integer
  INTO v_paye_candidates_count
  FROM jsonb_array_elements(v_paye_candidates) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT COUNT(*)::integer
  INTO v_non_paye_payees_count
  FROM jsonb_array_elements(v_non_paye_payees) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  v_candidate_count := v_paye_candidates_count + v_non_paye_payees_count;

  SELECT COUNT(*)::integer
  INTO v_ready_candidates_count
  FROM (
    SELECT elem.value
    FROM jsonb_array_elements(v_paye_candidates) AS elem(value)
    WHERE jsonb_typeof(elem.value) = 'object'
    UNION ALL
    SELECT elem.value
    FROM jsonb_array_elements(v_non_paye_payees) AS elem(value)
    WHERE jsonb_typeof(elem.value) = 'object'
  ) AS candidate_rows(value)
  WHERE COALESCE(LOWER(BTRIM(COALESCE(candidate_rows.value->>'is_ready_for_draft', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COUNT(*)::integer
  INTO v_blocked_candidates_count
  FROM (
    SELECT elem.value
    FROM jsonb_array_elements(v_paye_candidates) AS elem(value)
    WHERE jsonb_typeof(elem.value) = 'object'
    UNION ALL
    SELECT elem.value
    FROM jsonb_array_elements(v_non_paye_payees) AS elem(value)
    WHERE jsonb_typeof(elem.value) = 'object'
  ) AS candidate_rows(value)
  WHERE COALESCE(LOWER(BTRIM(COALESCE(candidate_rows.value->>'is_review_required', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COUNT(*)::integer
  INTO v_case_resolution_state_count
  FROM jsonb_array_elements(v_case_resolution_states) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT COUNT(*)::integer
  INTO v_blocked_case_state_count
  FROM jsonb_array_elements(v_case_resolution_states) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on');

  SELECT COUNT(*)::integer
  INTO v_canonical_preview_line_count
  FROM jsonb_array_elements(v_canonical_preview_lines) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT COUNT(*)::integer
  INTO v_ready_preview_line_count
  FROM jsonb_array_elements(v_canonical_preview_lines) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND NOT (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_do_not_pay', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'CASES_RESOLUTIONS'
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_snoozed', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'SNOOZED'
    );

  v_blocked_preview_line_count := jsonb_array_length(v_blocked_items);
  v_do_not_pay_line_count := jsonb_array_length(v_do_not_pay_items);
  v_snoozed_line_count := jsonb_array_length(v_snoozed_items);

  SELECT COUNT(*)::integer
  INTO v_payees_count
  FROM jsonb_array_elements(v_payees) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_ex_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_inc_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_inc_vat')::numeric ELSE 0 END), 0)
  INTO
    v_total_amount_ex_vat,
    v_total_amount_vat,
    v_total_amount_inc_vat
  FROM jsonb_array_elements(v_canonical_preview_lines) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  SELECT
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_ex_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_vat')::numeric ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN BTRIM(COALESCE(elem.value->>'amount_inc_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (elem.value->>'amount_inc_vat')::numeric ELSE 0 END), 0)
  INTO
    v_draftable_amount_ex_vat,
    v_draftable_amount_vat,
    v_draftable_amount_inc_vat
  FROM jsonb_array_elements(v_canonical_preview_lines) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND NOT (
      COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_blocked', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) IN ('BLOCKED', 'BLOCKED_FOR_PAY')
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_do_not_pay', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'CASES_RESOLUTIONS'
      OR COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_snoozed', 'false'))), 'false') IN ('true', 't', '1', 'yes', 'y', 'on')
      OR UPPER(BTRIM(COALESCE(elem.value->>'presentation_section', ''))) = 'SNOOZED'
    );

  SELECT COUNT(*)::integer
  INTO v_payees_need_name_check
  FROM jsonb_array_elements(v_payees) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND (
      EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(elem.value->'blockers') = 'array' THEN COALESCE(elem.value->'blockers', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS blocker(value)
        WHERE UPPER(BTRIM(blocker.value)) = 'BLOCKED_NAME_CHECK'
      )
    );

  SELECT COUNT(*)::integer
  INTO v_payees_need_payee_map
  FROM jsonb_array_elements(v_payees) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND (
      EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(elem.value->'blockers') = 'array' THEN COALESCE(elem.value->'blockers', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS blocker(value)
        WHERE UPPER(BTRIM(blocker.value)) = 'BLOCKED_NO_PAYEE_MAP'
      )
    );

  SELECT COUNT(*)::integer
  INTO v_payees_missing_bank_details
  FROM jsonb_array_elements(v_payees) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object'
    AND (
      COALESCE(BTRIM(COALESCE(elem.value->>'bank_details_hash', '')), '') = ''
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(
          CASE
            WHEN jsonb_typeof(elem.value->'blockers') = 'array' THEN COALESCE(elem.value->'blockers', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS blocker(value)
        WHERE UPPER(BTRIM(blocker.value)) = 'BLOCKED_BANK_DETAILS'
      )
    );

  SELECT
    ROUND(COALESCE(SUM(
      CASE
        WHEN UPPER(BTRIM(COALESCE(elem.value->>'pay_channel', ''))) = 'PAYE'
          AND UPPER(BTRIM(COALESCE(elem.value->>'paye_treatment', ''))) = 'GROSS_ADD'
          AND COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((elem.value->>'amount_ex_vat')::numeric, 0)
        ELSE 0
      END
    ), 0), 2),
    ROUND(COALESCE(SUM(
      CASE
        WHEN UPPER(BTRIM(COALESCE(elem.value->>'pay_channel', ''))) = 'PAYE'
          AND UPPER(BTRIM(COALESCE(elem.value->>'paye_treatment', ''))) = 'GROSS_DEDUCT'
          AND COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ABS((elem.value->>'amount_ex_vat')::numeric)
        ELSE 0
      END
    ), 0), 2),
    ROUND(COALESCE(SUM(
      CASE
        WHEN UPPER(BTRIM(COALESCE(elem.value->>'pay_channel', ''))) = 'PAYE'
          AND UPPER(BTRIM(COALESCE(elem.value->>'paye_treatment', ''))) = 'NET_ADD'
          AND COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN GREATEST((elem.value->>'amount_ex_vat')::numeric, 0)
        ELSE 0
      END
    ), 0), 2),
    ROUND(COALESCE(SUM(
      CASE
        WHEN UPPER(BTRIM(COALESCE(elem.value->>'pay_channel', ''))) = 'PAYE'
          AND UPPER(BTRIM(COALESCE(elem.value->>'paye_treatment', ''))) = 'NET_DEDUCT'
          AND COALESCE(LOWER(BTRIM(COALESCE(elem.value->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND BTRIM(COALESCE(elem.value->>'amount_ex_vat', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ABS((elem.value->>'amount_ex_vat')::numeric)
        ELSE 0
      END
    ), 0), 2)
  INTO
    v_gross_side_additions_ex_vat,
    v_gross_side_deductions_ex_vat,
    v_net_side_additions_ex_vat,
    v_net_side_deductions_ex_vat
  FROM jsonb_array_elements(v_canonical_preview_lines) AS elem(value)
  WHERE jsonb_typeof(elem.value) = 'object';

  v_paye_summary_breakdown := jsonb_build_object(
    'gross_side_additions_ex_vat', v_gross_side_additions_ex_vat,
    'gross_side_deductions_ex_vat', v_gross_side_deductions_ex_vat,
    'net_side_additions_ex_vat', v_net_side_additions_ex_vat,
    'net_side_deductions_ex_vat', v_net_side_deductions_ex_vat
  );

  v_summary := jsonb_build_object(
    'readiness', jsonb_build_object(
      'payees_total', v_payees_count,
      'payees_need_name_check', v_payees_need_name_check,
      'payees_need_payee_map', v_payees_need_payee_map,
      'payees_missing_bank_details', v_payees_missing_bank_details
    ),
    'candidates', jsonb_build_object(
      'ready_count', v_ready_candidates_count,
      'review_required_count', v_blocked_candidates_count,
      'total_candidates', v_candidate_count
    ),
    'candidate_count', v_candidate_count,
    'paye_candidates_count', v_paye_candidates_count,
    'non_paye_payees_count', v_non_paye_payees_count,
    'ready_candidates_count', v_ready_candidates_count,
    'blocked_candidates_count', v_blocked_candidates_count,
    'case_resolution_state_count', v_case_resolution_state_count,
    'blocked_case_state_count', v_blocked_case_state_count,
    'canonical_preview_line_count', v_canonical_preview_line_count,
    'ready_preview_line_count', v_ready_preview_line_count,
    'blocked_preview_line_count', v_blocked_preview_line_count,
    'do_not_pay_line_count', v_do_not_pay_line_count,
    'snoozed_line_count', v_snoozed_line_count,
    'payees_count', v_payees_count,
    'total_amount_ex_vat', v_total_amount_ex_vat,
    'total_amount_vat', v_total_amount_vat,
    'total_amount_inc_vat', v_total_amount_inc_vat,
    'draftable_amount_ex_vat', v_draftable_amount_ex_vat,
    'draftable_amount_vat', v_draftable_amount_vat,
    'draftable_amount_inc_vat', v_draftable_amount_inc_vat,
    'paye_breakdown', v_paye_summary_breakdown
  );

  RETURN jsonb_build_object(
    'pay_date', v_context_json->'pay_date',
    'pay_week_start', v_context_json->'pay_week_start',
    'week_ending_cutoff_date', v_context_json->'week_ending_cutoff_date',
    'eligibility', COALESCE(v_context_json->'eligibility', '{}'::jsonb),
    'filters', COALESCE(v_context_json->'filters', '{}'::jsonb),
    'finance', COALESCE(v_context_json->'finance', '{}'::jsonb),
    'settings', COALESCE(v_context_json->'settings', '{}'::jsonb),
    'summary', v_summary,
    'paye_guardrails', COALESCE(v_context_json->'paye_guardrails', '{}'::jsonb),
    'paye_summary_breakdown', v_paye_summary_breakdown,
    'payees', v_payees,
    'canonical_preview_lines', v_canonical_preview_lines,
    'case_resolution_states', v_case_resolution_states,
    'itemisation', v_itemisation,
    'paye_candidates', v_paye_candidates,
    'non_paye_payees', v_non_paye_payees,
    'blocked_items', v_blocked_items,
    'do_not_pay_items', v_do_not_pay_items,
    'snoozed_items', v_snoozed_items,
    'baseline_component_rows', v_baseline_component_rows,
    'hidden_recovery_template_lines', v_hidden_recovery_template_lines,
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'timesheet_snapshots_json', v_timesheet_snapshots_json
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_preview_apply_candidate_overlay(
  p_candidate_baseline_json jsonb,
  p_case_resolutions_json jsonb DEFAULT NULL::jsonb,
  p_overrides_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_candidate_baseline_root jsonb := coalesce(p_candidate_baseline_json, '{}'::jsonb);
  v_case_resolutions_input jsonb := coalesce(p_case_resolutions_json, '{}'::jsonb);
  v_overrides_input jsonb := coalesce(p_overrides_json, '{}'::jsonb);
  v_candidate_id text := '';
  v_candidate_row jsonb := '{}'::jsonb;
  v_summary_fragment jsonb := '{}'::jsonb;
  v_case_states jsonb := '[]'::jsonb;
  v_lines jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_blocked_items jsonb := '[]'::jsonb;
  v_do_not_pay_items jsonb := '[]'::jsonb;
  v_snoozed_items jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_timesheet_snapshots_json jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines_input jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_hidden_recovery_template_line_count integer := 0;
  v_case_resolutions jsonb := '{}'::jsonb;
  v_exclude_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_map jsonb := '{}'::jsonb;
  v_bucket_applied_component_rows jsonb := '[]'::jsonb;
  v_final_component_rows jsonb := '[]'::jsonb;
  v_updated_case_states jsonb := '[]'::jsonb;
  v_case_state_map jsonb := '{}'::jsonb;
  v_updated_lines jsonb := '[]'::jsonb;
  v_updated_itemisation jsonb := '[]'::jsonb;
  v_case_resolution_entry record;
  v_case_resolution_json jsonb := '{}'::jsonb;
  v_resolution_case_key text := '';
  v_resolution_family text := '';
  v_resolve_all_linked_timesheets boolean := false;
  v_component_row jsonb := '{}'::jsonb;
  v_updated_component_row jsonb := '{}'::jsonb;
  v_component_scope text := '';
  v_component_case_key text := '';
  v_component_timesheet_id text := '';
  v_component_source_family_key text := '';
  v_component_key_type text := '';
  v_component_key_value text := '';
  v_component_bucket_code text := '';
  v_component_source_basis_fingerprint text := '';
  v_component_fingerprint text := '';
  v_component_source_units numeric := null::numeric;
  v_component_source_rate numeric := null::numeric;
  v_component_source_charge_rate numeric := null::numeric;
  v_case_state jsonb := '{}'::jsonb;
  v_line jsonb := '{}'::jsonb;
  v_case_state_case_key text := '';
  v_case_state_case_scope text := '';
  v_case_state_timesheet_id text := '';
  v_case_state_components jsonb := '[]'::jsonb;
  v_case_state_updated_components jsonb := '[]'::jsonb;
  v_case_state_updated jsonb := '{}'::jsonb;
  v_case_state_updated_components_count integer := 0;
  v_case_state_open_taxable_count integer := 0;
  v_case_state_open_reimbursement_count integer := 0;
  v_case_state_unresolved_taxable_count integer := 0;
  v_case_state_needs_resolution boolean := false;
  v_case_state_satisfied_now boolean := true;
  v_case_state_existing_blocked_reasons_count integer := 0;
  v_case_state_total_preview_amount_ex_vat numeric := 0;
  v_case_state_safe_amount_ex_vat numeric := 0;
  v_case_state_blocked_amount_ex_vat numeric := 0;
  v_case_state_unresolved_taxable_amount_ex_vat numeric := 0;
  v_case_state_taxable_manual_debt_resolution jsonb := null::jsonb;
  v_case_state_summary jsonb := '{}'::jsonb;
  v_case_state_resolved_detail_rows jsonb := '[]'::jsonb;
  v_template_base_line jsonb := null::jsonb;
  v_template_ready_line jsonb := null::jsonb;
  v_template_blocked_line jsonb := null::jsonb;
  v_template_do_not_pay_line jsonb := null::jsonb;
  v_case_ready_amount_ex_vat numeric := 0;
  v_case_blocked_amount_ex_vat numeric := 0;
  v_case_total_amount_ex_vat numeric := 0;
  v_case_is_excluded boolean := false;
  v_new_line jsonb := '{}'::jsonb;
  v_line_id_base text := '';
  v_line_preview_row_id text := '';
  v_item jsonb := '{}'::jsonb;
  v_component_match_found boolean := false;
  v_component_case_applies boolean := false;
  v_component_direct_case_match boolean := false;
  v_component_linked_case_match boolean := false;
  v_component_linked_ids jsonb := '[]'::jsonb;
  v_bucket_resolution_json jsonb := '{}'::jsonb;
  v_bucket_source_family_key text := '';
  v_bucket_component_key_type text := '';
  v_bucket_component_key_value text := '';
  v_bucket_source_basis_fingerprint text := '';
  v_bucket_bucket_code text := '';
  v_bucket_resolution_mode text := '';
  v_bucket_target_rate numeric := null::numeric;
  v_bucket_source_units numeric := null::numeric;
  v_bucket_source_rate numeric := null::numeric;
  v_bucket_source_charge_rate numeric := null::numeric;
  v_bucket_target_pay_ex_vat numeric := null::numeric;
  v_bucket_target_charge_ex_vat numeric := null::numeric;
  v_bucket_target_margin_ex_vat numeric := null::numeric;
  v_bucket_margin_delta_ex_vat numeric := null::numeric;
  v_nonbucket_resolution_entry record;
  v_nonbucket_resolution_mode text := '';
  v_nonbucket_target_amount_ex_vat numeric := null::numeric;
  v_nonbucket_case_row_count integer := 0;
  v_nonbucket_case_total_basis numeric := 0;
  v_nonbucket_case_allocated_so_far numeric := 0;
  v_nonbucket_case_row_index integer := 0;
  v_nonbucket_case_row_basis numeric := 0;
  v_nonbucket_case_row_target_amount_ex_vat numeric := 0;
  v_nonbucket_case_row_key text := '';
  v_nonbucket_case_row_match_key text := '';
  v_nonbucket_allocations jsonb := '{}'::jsonb;
  v_nonbucket_case_payload jsonb := '{}'::jsonb;
  v_nonbucket_case_row_allocations jsonb := '{}'::jsonb;
  v_component_lookup_key text := '';
  v_component_source_charge_ex_vat numeric := null::numeric;
  v_component_source_pay_ex_vat numeric := null::numeric;
  v_component_target_pay_ex_vat numeric := null::numeric;
  v_component_target_charge_ex_vat numeric := null::numeric;
  v_component_target_margin_ex_vat numeric := null::numeric;
  v_component_margin_delta_ex_vat numeric := null::numeric;
  v_component_preview_amount_ex_vat numeric := null::numeric;
  v_component_ready_preview_amount_ex_vat numeric := null::numeric;
  v_component_blocked_preview_amount_ex_vat numeric := null::numeric;
  v_component_requires_resolution boolean := false;
  v_component_is_actionable_resolution_row boolean := false;
  v_line_case_key text := '';
  v_line_case_scope text := '';
  v_line_timesheet_id text := '';
  v_line_presentation_section text := '';
  v_line_existing_blocked_reason_codes jsonb := '[]'::jsonb;
  v_line_existing_preview_row_id text := '';
  v_line_existing_line_id text := '';
  v_line_existing_presentation_parent_line_id text := '';
  v_excluded_timesheet_entry jsonb;
  v_excluded_timesheet_id text := '';
  v_case_state_component jsonb := '{}'::jsonb;
  v_component_requires_resolution_text text := '';
  v_component_preview_amount_text text := '';
  v_component_ready_amount_text text := '';
  v_component_blocked_amount_text text := '';
  v_case_state_exists boolean := false;
  v_case_state_from_map jsonb := '{}'::jsonb;
  v_case_state_summary_source jsonb := '{}'::jsonb;
  v_case_state_existing_due_amount_ex_vat numeric := 0;
  v_line_amount_ex_vat numeric := 0;
  v_do_not_pay_reason_codes jsonb := '[]'::jsonb;
  v_case_line_count integer := 0;
  v_case_ready_line_present boolean := false;
  v_case_blocked_line_present boolean := false;
  v_case_first_line jsonb := null::jsonb;
  v_case_component_row jsonb := '{}'::jsonb;
  v_component_order integer := 0;
  v_case_component_order integer := 0;
  v_component_sort_key text := '';
  v_case_scope_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_is_component_match boolean := false;
  v_line_blocked_reason_codes jsonb := '[]'::jsonb;
  v_existing_case_state_summary jsonb := '{}'::jsonb;
  v_nonbucket_resolution_applied boolean := false;
  v_nonbucket_case_allowed boolean := false;
  v_bucket_resolution_applied boolean := false;
  v_case_state_is_timesheet_scope boolean := false;
  v_itemisation_match_found boolean := false;
  v_itemisation_append_json jsonb := '{}'::jsonb;
  v_selected_case_line jsonb := null::jsonb;
begin
  if jsonb_typeof(v_candidate_baseline_root) <> 'object' then
    raise exception 'p_candidate_baseline_json must be a JSON object';
  end if;

  if jsonb_typeof(v_case_resolutions_input) <> 'object' then
    v_case_resolutions_input := '{}'::jsonb;
  end if;

  if jsonb_typeof(v_overrides_input) <> 'object' then
    v_overrides_input := '{}'::jsonb;
  end if;

  v_candidate_id := btrim(coalesce(
    v_candidate_baseline_root->>'candidate_id',
    v_candidate_baseline_root #>> '{candidate_row,candidate_id}',
    ''
  ));

  if v_candidate_id = '' then
    raise exception 'candidate_id is required on p_candidate_baseline_json';
  end if;

  v_candidate_row := case when jsonb_typeof(v_candidate_baseline_root->'candidate_row') = 'object' then coalesce(v_candidate_baseline_root->'candidate_row', '{}'::jsonb) else '{}'::jsonb end;
  v_summary_fragment := case when jsonb_typeof(v_candidate_baseline_root->'summary_fragment') = 'object' then coalesce(v_candidate_baseline_root->'summary_fragment', '{}'::jsonb) else '{}'::jsonb end;
  v_case_states := case when jsonb_typeof(v_candidate_baseline_root->'case_resolution_states') = 'array' then coalesce(v_candidate_baseline_root->'case_resolution_states', '[]'::jsonb) else '[]'::jsonb end;
  v_lines := case when jsonb_typeof(v_candidate_baseline_root->'canonical_preview_lines') = 'array' then coalesce(v_candidate_baseline_root->'canonical_preview_lines', '[]'::jsonb) else '[]'::jsonb end;
  v_payees := case when jsonb_typeof(v_candidate_baseline_root->'payees') = 'array' then coalesce(v_candidate_baseline_root->'payees', '[]'::jsonb) else '[]'::jsonb end;
  v_itemisation := case when jsonb_typeof(v_candidate_baseline_root->'itemisation') = 'array' then coalesce(v_candidate_baseline_root->'itemisation', '[]'::jsonb) else '[]'::jsonb end;
  v_blocked_items := case when jsonb_typeof(v_candidate_baseline_root->'blocked_items') = 'array' then coalesce(v_candidate_baseline_root->'blocked_items', '[]'::jsonb) else '[]'::jsonb end;
  v_do_not_pay_items := case when jsonb_typeof(v_candidate_baseline_root->'do_not_pay_items') = 'array' then coalesce(v_candidate_baseline_root->'do_not_pay_items', '[]'::jsonb) else '[]'::jsonb end;
  v_snoozed_items := case when jsonb_typeof(v_candidate_baseline_root->'snoozed_items') = 'array' then coalesce(v_candidate_baseline_root->'snoozed_items', '[]'::jsonb) else '[]'::jsonb end;
  v_baseline_component_rows := case when jsonb_typeof(v_candidate_baseline_root->'baseline_component_rows') = 'array' then coalesce(v_candidate_baseline_root->'baseline_component_rows', '[]'::jsonb) else '[]'::jsonb end;
  v_timesheet_snapshots_json := case when jsonb_typeof(v_candidate_baseline_root->'timesheet_snapshots_json') = 'array' then coalesce(v_candidate_baseline_root->'timesheet_snapshots_json', '[]'::jsonb) else '[]'::jsonb end;
  v_hidden_recovery_template_lines_input := case
    when jsonb_typeof(v_candidate_baseline_root->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_baseline_root->'hidden_recovery_template_lines', '[]'::jsonb)
    when jsonb_typeof(v_candidate_row->'hidden_recovery_template_lines') = 'array' then coalesce(v_candidate_row->'hidden_recovery_template_lines', '[]'::jsonb)
    else '[]'::jsonb
  end;

  select coalesce(jsonb_agg(elem.value order by elem.ord), '[]'::jsonb)
  into v_hidden_recovery_template_lines
  from jsonb_array_elements(v_hidden_recovery_template_lines_input) with ordinality as elem(value, ord)
  where jsonb_typeof(elem.value) = 'object';

  v_hidden_recovery_template_line_count := jsonb_array_length(v_hidden_recovery_template_lines);

  v_case_resolutions := case
    when jsonb_typeof(v_case_resolutions_input->'case_resolutions') = 'object' then coalesce(v_case_resolutions_input->'case_resolutions', '{}'::jsonb)
    when jsonb_typeof(v_case_resolutions_input) = 'object' then coalesce(v_case_resolutions_input, '{}'::jsonb)
    else '{}'::jsonb
  end;

  v_exclude_timesheet_ids := case
    when jsonb_typeof(v_overrides_input->'exclude_timesheet_ids') = 'array' then coalesce(v_overrides_input->'exclude_timesheet_ids', '[]'::jsonb)
    when jsonb_typeof(v_overrides_input->'timesheet_exclusions') = 'array' then coalesce(v_overrides_input->'timesheet_exclusions', '[]'::jsonb)
    else '[]'::jsonb
  end;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    if upper(btrim(coalesce(v_case_state->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
      v_case_scope_linked_timesheet_ids := case
        when jsonb_typeof(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}') = 'array'
          then coalesce(v_case_state #> '{linked_resolution_scope_json,linked_timesheet_ids}', '[]'::jsonb)
        when nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), '') is not null
          then jsonb_build_array(v_case_state->>'timesheet_id')
        else '[]'::jsonb
      end;

      v_linked_timesheet_map := v_linked_timesheet_map || jsonb_build_object(v_case_state_case_key, v_case_scope_linked_timesheet_ids);
    end if;
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_baseline_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_bucket_resolution_applied := false;

    v_component_scope := upper(btrim(coalesce(v_component_row->>'component_scope', '')));
    v_component_case_key := btrim(coalesce(v_component_row->>'case_key', ''));
    v_component_timesheet_id := btrim(coalesce(v_component_row->>'timesheet_id', ''));
    v_component_source_family_key := btrim(coalesce(v_component_row->>'source_family_key', ''));
    v_component_key_type := upper(btrim(coalesce(v_component_row->>'component_key_type', '')));
    v_component_key_value := btrim(coalesce(v_component_row->>'component_key_value', ''));
    v_component_bucket_code := upper(btrim(coalesce(v_component_row->>'bucket_code', '')));
    v_component_source_basis_fingerprint := btrim(coalesce(v_component_row->>'source_basis_fingerprint', ''));
    v_component_fingerprint := btrim(coalesce(v_component_row->>'component_fingerprint', ''));

    v_component_source_units := case when coalesce(v_component_row->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_units')::numeric, 6) else null::numeric end;
    v_component_source_rate := case when coalesce(v_component_row->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_rate := case when coalesce(v_component_row->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_rate')::numeric, 6) else null::numeric end;
    v_component_source_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
    v_component_source_pay_ex_vat := case
      when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_entitlement_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_reservation_amount_ex_vat')::numeric, 2)
      when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
      else null::numeric
    end;

    for v_case_resolution_entry in
      select preview_resolution.key as case_key, preview_resolution.value as resolution_json
      from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
      where jsonb_typeof(preview_resolution.value) = 'object'
    loop
      v_case_resolution_json := v_case_resolution_entry.resolution_json;
      v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_case_resolution_entry.case_key, ''));
      v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));
      v_resolve_all_linked_timesheets := coalesce((v_case_resolution_json->>'resolve_all_linked_timesheets')::boolean, false);

      if v_resolution_family <> 'BUCKETED' then
        continue;
      end if;

      v_component_direct_case_match := (v_resolution_case_key <> '' and v_resolution_case_key = v_component_case_key);
      v_component_linked_case_match := false;

      if v_component_direct_case_match = false and v_resolve_all_linked_timesheets = true and v_component_scope = 'TIMESHEET' and v_component_timesheet_id <> '' then
        v_component_linked_ids := coalesce(v_linked_timesheet_map->v_resolution_case_key, '[]'::jsonb);
        if exists (
          select 1
          from jsonb_array_elements_text(v_component_linked_ids) as linked_id(value)
          where btrim(linked_id.value) = v_component_timesheet_id
        ) then
          v_component_linked_case_match := true;
        end if;
      end if;

      v_component_case_applies := (v_component_direct_case_match or v_component_linked_case_match);

      if v_component_case_applies = false then
        continue;
      end if;

      for v_bucket_resolution_json in
        select bucket_elem.value
        from jsonb_array_elements(coalesce(v_case_resolution_json->'bucket_resolutions', '[]'::jsonb)) as bucket_elem(value)
        where jsonb_typeof(bucket_elem.value) = 'object'
      loop
        v_bucket_source_family_key := btrim(coalesce(v_bucket_resolution_json->>'source_family_key', ''));
        v_bucket_component_key_type := upper(btrim(coalesce(v_bucket_resolution_json->>'component_key_type', '')));
        v_bucket_component_key_value := btrim(coalesce(v_bucket_resolution_json->>'component_key_value', ''));
        v_bucket_source_basis_fingerprint := btrim(coalesce(v_bucket_resolution_json->>'source_basis_fingerprint', ''));
        v_bucket_bucket_code := upper(btrim(coalesce(v_bucket_resolution_json->>'bucket_code', '')));
        v_bucket_resolution_mode := upper(btrim(coalesce(v_bucket_resolution_json->>'resolution_mode', '')));
        v_bucket_target_rate := case when coalesce(v_bucket_resolution_json->>'target_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'target_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_units := case when coalesce(v_bucket_resolution_json->>'source_units', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_units')::numeric, 6) else null::numeric end;
        v_bucket_source_rate := case when coalesce(v_bucket_resolution_json->>'source_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_rate')::numeric, 6) else null::numeric end;
        v_bucket_source_charge_rate := case when coalesce(v_bucket_resolution_json->>'source_charge_rate', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_bucket_resolution_json->>'source_charge_rate')::numeric, 6) else null::numeric end;

        v_is_component_match := false;

        if v_bucket_source_family_key = v_component_source_family_key
           and v_bucket_component_key_type = v_component_key_type
           and v_bucket_component_key_value = v_component_key_value then
          if v_bucket_source_basis_fingerprint <> '' then
            v_is_component_match := (v_bucket_source_basis_fingerprint = v_component_source_basis_fingerprint);
          else
            v_is_component_match := true;

            if v_bucket_bucket_code <> '' then
              v_is_component_match := v_is_component_match and (v_bucket_bucket_code = v_component_bucket_code);
            end if;

            if v_bucket_source_units is not null then
              v_is_component_match := v_is_component_match and (v_component_source_units is not null and round(v_component_source_units, 6) = v_bucket_source_units);
            end if;

            if v_bucket_source_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_rate is not null and round(v_component_source_rate, 6) = v_bucket_source_rate);
            end if;

            if v_bucket_source_charge_rate is not null then
              v_is_component_match := v_is_component_match and (v_component_source_charge_rate is not null and round(v_component_source_charge_rate, 6) = v_bucket_source_charge_rate);
            end if;
          end if;
        end if;

        if v_is_component_match = false then
          continue;
        end if;

        if v_component_key_type = 'TS_DAY' and not (v_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key for resolved component: %', v_component_key_value;
        end if;

        if v_bucket_component_key_type = 'TS_DAY' and not (v_bucket_component_key_value ~ '^\d{4}-\d{2}-\d{2}$') then
          raise exception 'Invalid TS_DAY economic key in bucket resolution: %', v_bucket_component_key_value;
        end if;

        if v_bucket_target_rate is null or v_component_source_units is null or v_component_source_units = 0 then
          continue;
        end if;

        v_bucket_target_pay_ex_vat := round(v_bucket_target_rate * v_component_source_units, 2);
        v_bucket_target_charge_ex_vat := v_component_source_charge_ex_vat;
        v_bucket_target_margin_ex_vat := case when v_bucket_target_charge_ex_vat is null then null::numeric else round(v_bucket_target_charge_ex_vat - v_bucket_target_pay_ex_vat, 2) end;
        v_bucket_margin_delta_ex_vat := case when v_component_source_pay_ex_vat is null then null::numeric else round(v_component_source_pay_ex_vat - v_bucket_target_pay_ex_vat, 2) end;

        v_updated_component_row := (v_updated_component_row
          - 'approved_resolution_mode'
          - 'approved_target_rate'
          - 'requires_resolution'
          - 'case_resolution_satisfied_now_component'
          - 'suggestion_provenance'
          - 'is_fresh_suggested_resolution'
          - 'preview_component_amount_ex_vat'
          - 'ready_preview_amount_ex_vat'
          - 'blocked_preview_amount_ex_vat'
          - 'target_pay_ex_vat'
          - 'target_charge_ex_vat'
          - 'target_margin_ex_vat'
          - 'margin_delta_ex_vat'
          - 'resolution_state'
          - 'target_rate')
          || jsonb_build_object(
            'approved_resolution_mode', v_bucket_resolution_mode,
            'approved_target_rate', round(v_bucket_target_rate, 6),
            'requires_resolution', false,
            'case_resolution_satisfied_now_component', true,
            'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
            'is_fresh_suggested_resolution', false,
            'preview_component_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'ready_preview_amount_ex_vat', v_bucket_target_pay_ex_vat,
            'blocked_preview_amount_ex_vat', 0,
            'source_pay_ex_vat', v_component_source_pay_ex_vat,
            'source_entitlement_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_reservation_amount_ex_vat', v_component_source_pay_ex_vat,
            'source_units', v_component_source_units,
            'source_rate', v_component_source_rate,
            'source_charge_rate', v_component_source_charge_rate,
            'source_charge_ex_vat', v_component_source_charge_ex_vat,
            'target_units', v_component_source_units,
            'target_pay_ex_vat', v_bucket_target_pay_ex_vat,
            'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
            'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
            'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat,
            'resolution_state', 'RESOLVED',
            'target_rate', round(v_bucket_target_rate, 6),
            'resolution_mode', v_bucket_resolution_mode,
            'resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            )),
            'suggested_resolution_payload_json', jsonb_strip_nulls(jsonb_build_object(
              'resolution_family', 'BUCKETED',
              'source_family_key', v_component_source_family_key,
              'component_key_type', v_component_key_type,
              'component_key_value', v_component_key_value,
              'source_basis_fingerprint', v_component_source_basis_fingerprint,
              'bucket_code', v_component_bucket_code,
              'source_units', v_component_source_units,
              'source_rate', v_component_source_rate,
              'source_charge_rate', v_component_source_charge_rate,
              'resolution_mode', v_bucket_resolution_mode,
              'target_rate', round(v_bucket_target_rate, 6)
            )),
            'suggested_resolution_result_json', jsonb_strip_nulls(jsonb_build_object(
              'target_amount_ex_vat', v_bucket_target_pay_ex_vat,
              'target_amount_vat', 0,
              'target_amount_inc_vat', v_bucket_target_pay_ex_vat,
              'target_units', v_component_source_units,
              'target_rate', round(v_bucket_target_rate, 6),
              'target_charge_ex_vat', v_bucket_target_charge_ex_vat,
              'target_margin_ex_vat', v_bucket_target_margin_ex_vat,
              'margin_delta_ex_vat', v_bucket_margin_delta_ex_vat
            ))
          );

        v_bucket_resolution_applied := true;
        exit;
      end loop;

      if v_bucket_resolution_applied = true then
        exit;
      end if;
    end loop;

    v_bucket_applied_component_rows := v_bucket_applied_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_nonbucket_allocations := '{}'::jsonb;

  for v_nonbucket_resolution_entry in
    select preview_resolution.key as case_key, preview_resolution.value as resolution_json
    from jsonb_each(v_case_resolutions) as preview_resolution(key, value)
    where jsonb_typeof(preview_resolution.value) = 'object'
  loop
    v_case_resolution_json := v_nonbucket_resolution_entry.resolution_json;
    v_resolution_case_key := btrim(coalesce(v_case_resolution_json->>'case_key', v_nonbucket_resolution_entry.case_key, ''));
    v_resolution_family := upper(btrim(coalesce(v_case_resolution_json->>'resolution_family', '')));

    if v_resolution_family <> 'NON_BUCKET' or v_resolution_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(v_case_states) as case_state_elem(value)
      where jsonb_typeof(case_state_elem.value) = 'object'
        and btrim(coalesce(case_state_elem.value->>'case_key', '')) = v_resolution_case_key
        and upper(btrim(coalesce(case_state_elem.value->>'case_scope', ''))) = 'FINANCE_CASE'
        and upper(btrim(coalesce(case_state_elem.value->>'case_type', ''))) = 'MANUAL_DEBT_ADJUSTMENT'
    ) into v_nonbucket_case_allowed;

    if v_nonbucket_case_allowed = false then
      continue;
    end if;

    v_nonbucket_resolution_mode := upper(btrim(coalesce(v_case_resolution_json->>'resolution_mode', '')));
    v_nonbucket_target_amount_ex_vat := case when coalesce(v_case_resolution_json->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_resolution_json->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

    if v_nonbucket_target_amount_ex_vat is null then
      continue;
    end if;

    v_nonbucket_case_row_count := 0;
    v_nonbucket_case_total_basis := 0;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_count := v_nonbucket_case_row_count + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;
        v_nonbucket_case_total_basis := v_nonbucket_case_total_basis + greatest(v_nonbucket_case_row_basis, 0);
      end if;
    end loop;

    if v_nonbucket_case_row_count <= 0 then
      continue;
    end if;

    v_nonbucket_case_row_index := 0;
    v_nonbucket_case_allocated_so_far := 0;
    v_nonbucket_case_row_allocations := '{}'::jsonb;

    for v_component_row in
      select elem.value
      from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_component_row->>'case_key', '')) = v_resolution_case_key
         and upper(btrim(coalesce(v_component_row->>'component_scope', ''))) = 'FINANCE_CASE'
         and upper(btrim(coalesce(v_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
        v_nonbucket_case_row_index := v_nonbucket_case_row_index + 1;
        v_nonbucket_case_row_basis := case
          when coalesce(v_component_row->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'remaining_source_amount')::numeric, 2)
          when coalesce(v_component_row->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_amount')::numeric, 2)
          when coalesce(v_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'component_amount_ex_vat')::numeric, 2)
          else 0::numeric
        end;

        if v_nonbucket_case_row_index < v_nonbucket_case_row_count and v_nonbucket_case_total_basis > 0 then
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat * (greatest(v_nonbucket_case_row_basis, 0) / v_nonbucket_case_total_basis), 2);
        elsif v_nonbucket_case_row_index < v_nonbucket_case_row_count then
          v_nonbucket_case_row_target_amount_ex_vat := 0;
        else
          v_nonbucket_case_row_target_amount_ex_vat := round(v_nonbucket_target_amount_ex_vat - v_nonbucket_case_allocated_so_far, 2);
        end if;

        v_nonbucket_case_allocated_so_far := v_nonbucket_case_allocated_so_far + v_nonbucket_case_row_target_amount_ex_vat;
        v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
        end if;
        if v_nonbucket_case_row_key = '' then
          v_nonbucket_case_row_key := btrim(coalesce(v_component_row->>'component_key_type', '')) || '|' || btrim(coalesce(v_component_row->>'component_key_value', '')) || '|' || v_nonbucket_case_row_index::text;
        end if;

        v_nonbucket_case_row_allocations := v_nonbucket_case_row_allocations || jsonb_build_object(v_nonbucket_case_row_key, jsonb_build_object(
          'resolution_mode', v_nonbucket_resolution_mode,
          'target_amount_ex_vat', v_nonbucket_case_row_target_amount_ex_vat
        ));
      end if;
    end loop;

    v_nonbucket_allocations := v_nonbucket_allocations || jsonb_build_object(v_resolution_case_key, v_nonbucket_case_row_allocations);
  end loop;

  for v_component_row in
    select elem.value
    from jsonb_array_elements(v_bucket_applied_component_rows) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_updated_component_row := v_component_row;
    v_nonbucket_resolution_applied := false;
    v_resolution_case_key := btrim(coalesce(v_component_row->>'case_key', ''));

    if jsonb_typeof(v_nonbucket_allocations->v_resolution_case_key) = 'object' then
      v_component_lookup_key := btrim(coalesce(v_component_row->>'component_fingerprint', ''));
      if v_component_lookup_key = '' then
        v_component_lookup_key := btrim(coalesce(v_component_row->>'finance_component_id', ''));
      end if;

      if v_component_lookup_key <> '' and jsonb_typeof((v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key) = 'object' then
        v_nonbucket_case_payload := (v_nonbucket_allocations->v_resolution_case_key)->v_component_lookup_key;
        v_nonbucket_resolution_mode := upper(btrim(coalesce(v_nonbucket_case_payload->>'resolution_mode', '')));
        v_nonbucket_target_amount_ex_vat := case when coalesce(v_nonbucket_case_payload->>'target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_nonbucket_case_payload->>'target_amount_ex_vat')::numeric, 2) else null::numeric end;

        if v_nonbucket_target_amount_ex_vat is not null then
          v_component_target_charge_ex_vat := case when coalesce(v_component_row->>'source_charge_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_charge_ex_vat')::numeric, 2) else null::numeric end;
          v_component_target_margin_ex_vat := case when v_component_target_charge_ex_vat is null then null::numeric else round(v_component_target_charge_ex_vat - v_nonbucket_target_amount_ex_vat, 2) end;
          v_component_margin_delta_ex_vat := case when coalesce(v_component_row->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_component_row->>'source_pay_ex_vat')::numeric - v_nonbucket_target_amount_ex_vat, 2) else null::numeric end;

          v_updated_component_row := (v_updated_component_row
            - 'approved_nonbucket_resolution_mode'
            - 'approved_nonbucket_target_amount_ex_vat'
            - 'requires_resolution'
            - 'case_resolution_satisfied_now_component'
            - 'suggestion_provenance'
            - 'is_fresh_suggested_resolution'
            - 'preview_component_amount_ex_vat'
            - 'ready_preview_amount_ex_vat'
            - 'blocked_preview_amount_ex_vat'
            - 'target_pay_ex_vat'
            - 'target_charge_ex_vat'
            - 'target_margin_ex_vat'
            - 'margin_delta_ex_vat'
            - 'resolution_state')
            || jsonb_build_object(
              'approved_nonbucket_resolution_mode', v_nonbucket_resolution_mode,
              'approved_nonbucket_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'requires_resolution', false,
              'case_resolution_satisfied_now_component', true,
              'suggestion_provenance', 'PREVIEW_CASE_RESOLUTION',
              'is_fresh_suggested_resolution', false,
              'preview_component_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'ready_preview_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
              'blocked_preview_amount_ex_vat', 0,
              'target_pay_ex_vat', v_nonbucket_target_amount_ex_vat,
              'target_charge_ex_vat', v_component_target_charge_ex_vat,
              'target_margin_ex_vat', v_component_target_margin_ex_vat,
              'margin_delta_ex_vat', v_component_margin_delta_ex_vat,
              'resolution_state', 'RESOLVED'
            );

          v_nonbucket_resolution_applied := true;
        end if;
      end if;
    end if;

    v_final_component_rows := v_final_component_rows || jsonb_build_array(v_updated_component_row);
  end loop;

  v_updated_case_states := '[]'::jsonb;
  v_case_state_map := '{}'::jsonb;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_updated_components := '[]'::jsonb;
    v_case_state_updated_components_count := 0;
    v_case_state_open_taxable_count := 0;
    v_case_state_open_reimbursement_count := 0;
    v_case_state_unresolved_taxable_count := 0;
    v_case_state_total_preview_amount_ex_vat := 0;
    v_case_state_safe_amount_ex_vat := 0;
    v_case_state_blocked_amount_ex_vat := 0;
    v_case_state_unresolved_taxable_amount_ex_vat := 0;

    for v_case_component_row in
      select elem.value
      from jsonb_array_elements(v_final_component_rows) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_case_component_row->>'case_key', '')) = v_case_state_case_key then
        v_case_state_updated_components := v_case_state_updated_components || jsonb_build_array(v_case_component_row);
        v_case_state_updated_components_count := v_case_state_updated_components_count + 1;

        if upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' then
          v_case_state_open_taxable_count := v_case_state_open_taxable_count + 1;
        elsif upper(btrim(coalesce(v_case_component_row->>'classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' then
          v_case_state_open_reimbursement_count := v_case_state_open_reimbursement_count + 1;
        end if;

        if coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_total_preview_amount_ex_vat := v_case_state_total_preview_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        if coalesce(v_case_component_row->>'ready_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'ready_preview_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
        elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_case_state_safe_amount_ex_vat := v_case_state_safe_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
        end if;

        v_component_requires_resolution := coalesce((v_case_component_row->>'requires_resolution')::boolean, false);
        if v_component_requires_resolution then
          v_case_state_unresolved_taxable_count := v_case_state_unresolved_taxable_count + 1;
          if coalesce(v_case_component_row->>'blocked_preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'blocked_preview_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'preview_component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'preview_component_amount_ex_vat')::numeric, 2);
          elsif coalesce(v_case_component_row->>'component_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_case_state_unresolved_taxable_amount_ex_vat := v_case_state_unresolved_taxable_amount_ex_vat + round((v_case_component_row->>'component_amount_ex_vat')::numeric, 2);
          end if;
        end if;
      end if;
    end loop;

    v_case_state_needs_resolution := (v_case_state_unresolved_taxable_count > 0);
    v_case_state_satisfied_now := not v_case_state_needs_resolution;
    if v_case_state_needs_resolution then
      v_case_state_blocked_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
      v_case_state_safe_amount_ex_vat := 0;
    else
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_safe_amount_ex_vat, 2);
    end if;

    v_case_is_excluded := false;
    if v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT') and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    if v_case_is_excluded then
      v_case_state_needs_resolution := false;
      v_case_state_satisfied_now := true;
      v_case_state_unresolved_taxable_count := 0;
      v_case_state_unresolved_taxable_amount_ex_vat := 0;
      v_case_state_blocked_amount_ex_vat := 0;
      v_case_state_safe_amount_ex_vat := round(v_case_state_total_preview_amount_ex_vat, 2);
    end if;

    select count(*)::int
    into v_case_state_existing_blocked_reasons_count
    from jsonb_array_elements_text(
      case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end
    ) as blocker(value);

    v_existing_case_state_summary := case when jsonb_typeof(v_case_state->'case_resolution_summary') = 'object' then coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb) else '{}'::jsonb end;

    v_case_state_summary := (v_existing_case_state_summary
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'is_blocked'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'excluded_from_pay', v_case_is_excluded
      );

    v_case_state_taxable_manual_debt_resolution := case when jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then coalesce(v_case_state->'taxable_manual_debt_resolution', '{}'::jsonb) else null::jsonb end;
    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      if exists (
        select 1
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
      ) then
        select upper(btrim(coalesce(comp.value->>'approved_nonbucket_resolution_mode', ''))),
               case when coalesce(comp.value->>'approved_nonbucket_target_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((comp.value->>'approved_nonbucket_target_amount_ex_vat')::numeric, 2) else null::numeric end
        into v_nonbucket_resolution_mode, v_nonbucket_target_amount_ex_vat
        from jsonb_array_elements(v_case_state_updated_components) as comp(value)
        where jsonb_typeof(comp.value) = 'object'
          and coalesce(comp.value->>'approved_nonbucket_resolution_mode', '') <> ''
        limit 1;

        v_case_state_taxable_manual_debt_resolution := v_case_state_taxable_manual_debt_resolution
          || jsonb_build_object(
            'approved_resolution_mode', v_nonbucket_resolution_mode,
            'approved_target_amount_ex_vat', v_nonbucket_target_amount_ex_vat,
            'case_resolution_satisfied_now', v_case_state_satisfied_now
          );
      end if;
    end if;

    v_case_state_updated := (v_case_state
      - 'components'
      - 'case_needs_resolution'
      - 'case_resolution_satisfied_now'
      - 'is_blocked'
      - 'open_taxable_count'
      - 'open_reimbursement_count'
      - 'unresolved_taxable_count'
      - 'safe_amount_ex_vat'
      - 'blocked_case_amount_ex_vat'
      - 'unresolved_taxable_amount_ex_vat'
      - 'case_resolution_summary'
      - 'taxable_manual_debt_resolution'
      - 'excluded_from_pay')
      || jsonb_build_object(
        'components', coalesce(v_case_state_updated_components, '[]'::jsonb),
        'case_needs_resolution', v_case_state_needs_resolution,
        'case_resolution_satisfied_now', v_case_state_satisfied_now,
        'is_blocked', (case when v_case_is_excluded then false else (v_case_state_needs_resolution or v_case_state_existing_blocked_reasons_count > 0) end),
        'open_taxable_count', v_case_state_open_taxable_count,
        'open_reimbursement_count', v_case_state_open_reimbursement_count,
        'unresolved_taxable_count', v_case_state_unresolved_taxable_count,
        'safe_amount_ex_vat', round(v_case_state_safe_amount_ex_vat, 2),
        'blocked_case_amount_ex_vat', round(v_case_state_blocked_amount_ex_vat, 2),
        'unresolved_taxable_amount_ex_vat', round(v_case_state_unresolved_taxable_amount_ex_vat, 2),
        'case_resolution_summary', v_case_state_summary,
        'excluded_from_pay', v_case_is_excluded
      );

    if v_case_state_taxable_manual_debt_resolution is not null and jsonb_typeof(v_case_state_taxable_manual_debt_resolution) = 'object' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_taxable_manual_debt_resolution);
    end if;

    if coalesce(v_case_state_updated->>'due_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('due_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    if coalesce(v_case_state_updated->>'payment_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then
      v_case_state_updated := v_case_state_updated || jsonb_build_object('payment_amount_ex_vat', round(v_case_state_total_preview_amount_ex_vat, 2));
    end if;

    v_updated_case_states := v_updated_case_states || jsonb_build_array(v_case_state_updated);
    if v_case_state_case_key <> '' then
      v_case_state_map := v_case_state_map || jsonb_build_object(v_case_state_case_key, v_case_state_updated);
    end if;
  end loop;

  v_updated_lines := '[]'::jsonb;

  for v_line in
    select elem.value
    from jsonb_array_elements(v_lines) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));
    if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
      continue;
    end if;
    v_updated_lines := v_updated_lines || jsonb_build_array(v_line);
  end loop;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    v_case_state_case_scope := upper(btrim(coalesce(v_case_state->>'case_scope', '')));
    v_case_state_timesheet_id := btrim(coalesce(v_case_state->>'timesheet_id', ''));
    v_case_state_needs_resolution := coalesce(nullif(v_case_state->>'case_needs_resolution', '')::boolean, false);
    v_case_state_is_timesheet_scope := (v_case_state_case_scope in ('TIMESHEET', 'TIMESHEET_PAYMENT'));
    v_case_ready_amount_ex_vat := case when coalesce(v_case_state->>'safe_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'safe_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_blocked_amount_ex_vat := case when coalesce(v_case_state->>'blocked_case_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_case_state->>'blocked_case_amount_ex_vat')::numeric, 2) else 0::numeric end;
    v_case_total_amount_ex_vat := round(v_case_ready_amount_ex_vat + v_case_blocked_amount_ex_vat, 2);

    select coalesce(jsonb_agg(detail_component.value order by coalesce(detail_component.value->>'component_key_type', ''), coalesce(detail_component.value->>'component_key_value', ''), coalesce(detail_component.value->>'bucket_code', '')), '[]'::jsonb)
    into v_case_state_resolved_detail_rows
    from jsonb_array_elements(coalesce(v_case_state->'components', '[]'::jsonb)) as detail_component(value)
    where jsonb_typeof(detail_component.value) = 'object'
      and coalesce(detail_component.value->>'case_resolution_satisfied_now_component', '') in ('true', 'TRUE')
      and upper(btrim(coalesce(detail_component.value->>'component_key_type', ''))) in ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'ADJUSTMENT_CODE', 'EXPENSE_CODE');

    if v_case_state_resolved_detail_rows is null then
      v_case_state_resolved_detail_rows := '[]'::jsonb;
    end if;

    v_case_is_excluded := false;
    if v_case_state_is_timesheet_scope = true and v_case_state_timesheet_id <> '' then
      if exists (
        select 1
        from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
        where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
      ) then
        v_case_is_excluded := true;
      end if;
    end if;

    v_template_base_line := null::jsonb;
    v_template_ready_line := null::jsonb;
    v_template_blocked_line := null::jsonb;
    v_template_do_not_pay_line := null::jsonb;

    for v_line in
      select elem.value
      from jsonb_array_elements(v_lines) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      if btrim(coalesce(v_line->>'case_key', '')) = v_case_state_case_key then
        if v_template_base_line is null then
          v_template_base_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'READY_TO_PAY' and v_template_ready_line is null then
          v_template_ready_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY' and v_template_blocked_line is null then
          v_template_blocked_line := v_line;
        end if;

        if upper(btrim(coalesce(v_line->>'presentation_section', ''))) = 'DO_NOT_PAY' and v_template_do_not_pay_line is null then
          v_template_do_not_pay_line := v_line;
        end if;
      end if;
    end loop;

    if v_template_base_line is null and v_case_state_is_timesheet_scope = true then
      v_template_base_line := jsonb_build_object(
        'candidate_id', v_candidate_id,
        'tms_ref', nullif(btrim(coalesce(v_candidate_row->>'tms_ref', '')), ''),
        'display_name', nullif(btrim(coalesce(v_candidate_row->>'display_name', v_candidate_row->>'candidate_name', '')), ''),
        'line_type', 'TIMESHEET_PAYMENT',
        'finance_case_id', null,
        'case_key', v_case_state_case_key,
        'case_type', coalesce(nullif(btrim(coalesce(v_case_state->>'case_type', '')), ''), 'TIMESHEET_PAYMENT')
      )
      || jsonb_build_object(
        'case_is_blocked', true,
        'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
        'case_components', coalesce(v_case_state->'components', '[]'::jsonb),
        'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
        'booking_id', null,
        'client_id', nullif(btrim(coalesce(v_case_state->>'client_id', '')), ''),
        'client_name', nullif(btrim(coalesce(v_case_state->>'client_name', '')), ''),
        'week_ending_date', nullif(btrim(coalesce(v_case_state->>'week_ending_date', '')), ''))
      || jsonb_build_object(
        'role', null,
        'band', null,
        'linked_shift_date', null,
        'pay_channel', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', '')), ''),
        'paye_treatment', case when upper(btrim(coalesce(v_case_state->>'candidate_pay_method', ''))) = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
        'route_type', 'NORMAL_PAYMENT',
        'adjustment_comment', null
      )
      || jsonb_build_object(
        'has_active_timesheet_snooze', false,
        'has_active_segment_snoozes', false,
        'active_segment_snooze_count', 0,
        'active_segment_dated_snooze_count', 0,
        'active_segment_indefinite_snooze_count', 0,
        'whole_timesheet_snooze_action_blocked', false,
        'whole_timesheet_snooze_action_block_reason', null,
        'segment_snooze_action_blocked', false,
        'segment_snooze_action_block_reason', null
      )
      || jsonb_build_object(
        'snooze_identity', jsonb_build_object(
          'identity_type', 'TIMESHEET',
          'timesheet_id', nullif(btrim(coalesce(v_case_state->>'timesheet_id', '')), ''),
          'booking_id', null,
          'segment_id', null,
          'segment_stable_key', null,
          'source_ref', null
        ),
        'snooze_state', jsonb_build_object('state', 'NONE')
      );
    end if;

    if v_template_base_line is null then
      continue;
    end if;

    if v_template_ready_line is null then
      v_template_ready_line := v_template_base_line;
    end if;
    if v_template_blocked_line is null then
      v_template_blocked_line := v_template_base_line;
    end if;
    if v_template_do_not_pay_line is null then
      v_template_do_not_pay_line := v_template_base_line;
    end if;

    if v_case_is_excluded = true and round(v_case_total_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_do_not_pay_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;
      if right(v_line_existing_line_id, 11) <> ':do_not_pay' then
        v_line_existing_line_id := v_line_existing_line_id || ':do_not_pay';
      end if;

      v_do_not_pay_reason_codes := case
        when jsonb_typeof(v_template_do_not_pay_line->'blocked_reason_codes') = 'array' then coalesce(v_template_do_not_pay_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_do_not_pay_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'DO_NOT_PAY'
      ) then
        v_do_not_pay_reason_codes := v_do_not_pay_reason_codes || jsonb_build_array('DO_NOT_PAY');
      end if;

      v_new_line := (v_template_do_not_pay_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_section', 'DO_NOT_PAY',
          'presentation_reason', 'SESSION_TIMESHEET_EXCLUSION',
          'readiness_state', 'DO_NOT_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', true,
          'is_excluded_from_allocation', true,
          'blocked_reason_codes', v_do_not_pay_reason_codes,
          'amount_ex_vat', round(v_case_total_amount_ex_vat, 2),
          'amount_display', round(v_case_total_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = true and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := nullif(btrim(coalesce(v_case_state_timesheet_id, '')), '');
      if v_line_existing_line_id is not null then
        v_line_existing_line_id := v_line_existing_line_id || ':03:case';
      else
        v_line_existing_line_id := btrim(coalesce(v_template_base_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := 'case_resolution_required';
        end if;
        if right(v_line_existing_line_id, 8) <> ':03:case' then
          v_line_existing_line_id := v_line_existing_line_id || ':03:case';
        end if;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_case_state #> '{case_resolution_summary,blocked_reason_codes}') = 'array' then coalesce(v_case_state #> '{case_resolution_summary,blocked_reason_codes}', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;
      if not exists (
        select 1
        from jsonb_array_elements_text(v_line_blocked_reason_codes) as blocker(value)
        where upper(btrim(blocker.value)) = 'RESOLUTION_REQUIRED'
      ) then
        v_line_blocked_reason_codes := v_line_blocked_reason_codes || jsonb_build_array('RESOLUTION_REQUIRED');
      end if;

      v_new_line := (v_template_base_line
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'segment_rows'
        - 'segment_count'
        - 'section_amount_ex_vat'
        - 'section_amount_display'
        - 'section_segment_rows'
        - 'section_segment_count'
        - 'section_non_segment_amount_ex_vat'
        - 'presentation_advisory_text'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', v_line_existing_line_id,
          'line_id', v_line_existing_line_id,
          'presentation_line_id', v_line_existing_line_id,
          'presentation_parent_line_id', coalesce(nullif(v_case_state_timesheet_id, ''), v_line_existing_line_id),
          'real_business_timesheet_id', nullif(v_case_state_timesheet_id, ''),
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'is_excluded_from_allocation', false,
          'is_ready_for_draft', false,
          'draftable', false
        )
        || jsonb_build_object(
          'segment_rows', '[]'::jsonb,
          'segment_count', 0,
          'presentation_section', 'CASES_RESOLUTIONS',
          'presentation_role', 'PARENT',
          'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
          'presentation_advisory_text', 'Resolve this case before draft',
          'readiness_state', 'CASES_RESOLUTIONS'
        )
        || jsonb_build_object(
          'section_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'section_amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'section_segment_rows', '[]'::jsonb,
          'section_segment_count', 0,
          'section_non_segment_amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    elsif v_case_state_is_timesheet_scope = false and v_case_state_needs_resolution = true and round(v_case_blocked_amount_ex_vat, 2) <> 0 then
      v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_template_base_line->>'line_id', v_case_state_case_key));
      if v_line_existing_line_id = '' then
        v_line_existing_line_id := v_case_state_case_key;
      end if;

      v_line_blocked_reason_codes := case
        when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
        when jsonb_typeof(v_template_base_line->'blocked_reason_codes') = 'array' then coalesce(v_template_base_line->'blocked_reason_codes', '[]'::jsonb)
        else '[]'::jsonb
      end;

      v_new_line := ((coalesce(v_template_blocked_line, v_template_base_line))
        - 'preview_row_id'
        - 'line_id'
        - 'presentation_line_id'
        - 'presentation_section'
        - 'presentation_reason'
        - 'readiness_state'
        - 'draftable'
        - 'is_ready_for_draft'
        - 'is_do_not_pay'
        - 'is_excluded_from_allocation'
        - 'blocked_reason_codes'
        - 'amount_ex_vat'
        - 'amount_display'
        - 'case_resolution_summary'
        - 'case_components'
        - 'taxable_manual_debt_resolution')
        || jsonb_build_object(
          'preview_row_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'preview_row_id', '')), ''), v_line_existing_line_id),
          'line_id', v_line_existing_line_id,
          'presentation_line_id', coalesce(nullif(btrim(coalesce((coalesce(v_template_blocked_line, v_template_base_line))->>'presentation_line_id', '')), ''), v_line_existing_line_id),
          'presentation_section', 'BLOCKED_FOR_PAY',
          'presentation_reason', 'CASE_BLOCKED',
          'readiness_state', 'BLOCKED_FOR_PAY',
          'draftable', false,
          'is_ready_for_draft', false,
          'is_do_not_pay', false,
          'is_excluded_from_allocation', false,
          'blocked_reason_codes', v_line_blocked_reason_codes,
          'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
          'amount_display', round(v_case_blocked_amount_ex_vat, 2),
          'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
          'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
        );

      if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
        v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
      end if;

      v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
    else
      if round(v_case_ready_amount_ex_vat, 2) <> 0 then
        v_line_existing_line_id := btrim(coalesce(v_template_ready_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key;
        end if;

        v_new_line := (v_template_ready_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'segment_rows'
          - 'segment_count'
          - 'section_amount_ex_vat'
          - 'section_amount_display'
          - 'section_segment_rows'
          - 'section_segment_count'
          - 'section_non_segment_amount_ex_vat'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'READY_TO_PAY',
            'presentation_reason', 'READY_TO_PAY',
            'readiness_state', 'READY_TO_PAY',
            'draftable', true,
            'is_ready_for_draft', true,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', '[]'::jsonb,
            'amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'amount_display', round(v_case_ready_amount_ex_vat, 2),
            'payment_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'source_pay_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_entitlement_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'source_reservation_amount_ex_vat', (
              select round(coalesce(sum(case when coalesce(detail_component.value->>'source_reservation_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_reservation_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_entitlement_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_entitlement_amount_ex_vat')::numeric when coalesce(detail_component.value->>'source_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (detail_component.value->>'source_pay_ex_vat')::numeric else 0::numeric end), 0), 2)
              from jsonb_array_elements(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)) as detail_component(value)
            ),
            'segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_amount_ex_vat', round(v_case_ready_amount_ex_vat, 2),
            'section_amount_display', round(v_case_ready_amount_ex_vat, 2),
            'section_segment_rows', coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb),
            'section_segment_count', jsonb_array_length(coalesce(v_case_state_resolved_detail_rows, '[]'::jsonb)),
            'section_non_segment_amount_ex_vat', 0,
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;

      if round(v_case_blocked_amount_ex_vat, 2) <> 0 and v_case_state_needs_resolution = false then
        v_line_existing_line_id := btrim(coalesce(v_template_blocked_line->>'line_id', v_case_state_case_key));
        if v_line_existing_line_id = '' then
          v_line_existing_line_id := v_case_state_case_key || ':blocked';
        end if;
        if v_line_existing_line_id = btrim(coalesce(v_template_ready_line->>'line_id', '')) then
          v_line_existing_line_id := v_line_existing_line_id || ':blocked';
        end if;

        v_line_blocked_reason_codes := case
          when jsonb_typeof(v_template_blocked_line->'blocked_reason_codes') = 'array' then coalesce(v_template_blocked_line->'blocked_reason_codes', '[]'::jsonb)
          when jsonb_typeof(v_case_state->'blocked_reason_codes') = 'array' then coalesce(v_case_state->'blocked_reason_codes', '[]'::jsonb)
          else '[]'::jsonb
        end;

        v_new_line := (v_template_blocked_line
          - 'preview_row_id'
          - 'line_id'
          - 'presentation_line_id'
          - 'presentation_section'
          - 'presentation_reason'
          - 'readiness_state'
          - 'draftable'
          - 'is_ready_for_draft'
          - 'is_do_not_pay'
          - 'is_excluded_from_allocation'
          - 'blocked_reason_codes'
          - 'amount_ex_vat'
          - 'amount_display'
          - 'case_resolution_summary'
          - 'case_components'
          - 'taxable_manual_debt_resolution')
          || jsonb_build_object(
            'preview_row_id', v_line_existing_line_id,
            'line_id', v_line_existing_line_id,
            'presentation_line_id', v_line_existing_line_id,
            'presentation_section', 'BLOCKED_FOR_PAY',
            'presentation_reason', 'CASE_BLOCKED',
            'readiness_state', 'BLOCKED_FOR_PAY',
            'draftable', false,
            'is_ready_for_draft', false,
            'is_do_not_pay', false,
            'is_excluded_from_allocation', false,
            'blocked_reason_codes', v_line_blocked_reason_codes,
            'amount_ex_vat', round(v_case_blocked_amount_ex_vat, 2),
            'amount_display', round(v_case_blocked_amount_ex_vat, 2),
            'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
            'case_components', coalesce(v_case_state->'components', '[]'::jsonb)
          );

        if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
          v_new_line := v_new_line || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
        end if;

        v_updated_lines := v_updated_lines || jsonb_build_array(v_new_line);
      end if;
    end if;
  end loop;

  for v_line in
    select baseline_line.value
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
  loop
    v_line_case_key := btrim(coalesce(v_line->>'case_key', ''));

    if v_line_case_key <> '' then
      if not exists (
        select 1
        from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
        where jsonb_typeof(rebuilt_line.value) = 'object'
          and btrim(coalesce(rebuilt_line.value->>'case_key', '')) = v_line_case_key
      ) then
        v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
      end if;
    elsif not exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as rebuilt_line(value)
      where jsonb_typeof(rebuilt_line.value) = 'object'
        and btrim(coalesce(rebuilt_line.value->>'line_id', '')) = btrim(coalesce(v_line->>'line_id', ''))
    ) then
      v_updated_lines := coalesce(v_updated_lines, '[]'::jsonb) || jsonb_build_array(v_line);
    end if;
  end loop;

  if jsonb_array_length(v_itemisation) > 0 then
    for v_item in
      select elem.value
      from jsonb_array_elements(v_itemisation) as elem(value)
      where jsonb_typeof(elem.value) = 'object'
    loop
      v_line_case_key := btrim(coalesce(v_item->>'case_key', ''));
      if v_line_case_key <> '' and jsonb_typeof(v_case_state_map->v_line_case_key) = 'object' then
        v_case_state_from_map := v_case_state_map->v_line_case_key;
        v_selected_case_line := null::jsonb;

        select line_choice.value
        into v_selected_case_line
        from (
          select
            line_elem.value,
            case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
              when 'CASES_RESOLUTIONS' then 0
              when 'READY_TO_PAY' then 1
              when 'BLOCKED_FOR_PAY' then 2
              when 'DO_NOT_PAY' then 3
              else 9
            end as sort_ord
          from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
          where jsonb_typeof(line_elem.value) = 'object'
            and btrim(coalesce(line_elem.value->>'case_key', '')) = v_line_case_key
        ) line_choice
        order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
        limit 1;

        if v_selected_case_line is not null then
          v_line_presentation_section := upper(btrim(coalesce(v_selected_case_line->>'presentation_section', '')));
          v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

          v_item := (v_item
            - 'preview_row_id'
            - 'line_id'
            - 'timesheet_id'
            - 'week_ending_date'
            - 'client_id'
            - 'client_name'
            - 'payment_amount_ex_vat'
            - 'payment_amount_inc_vat'
            - 'payment_amount'
            - 'source_pay_method'
            - 'candidate_pay_method'
            - 'segment_deltas'
            - 'presentation_section'
            - 'presentation_role'
            - 'total_segment_count'
            - 'ready_segment_count'
            - 'blocked_visible_segment_count'
            - 'hidden_indefinite_segment_count'
            - 'is_partially_ready'
            - 'is_partially_blocked'
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution'
            - 'excluded_from_pay'
            - 'is_do_not_pay')
            || jsonb_build_object(
              'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
              'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
              'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state_from_map->>'timesheet_id', '')), ''),
              'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state_from_map->>'week_ending_date', '')), ''),
              'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state_from_map->>'client_id', '')), ''),
              'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state_from_map->>'client_name', '')), ''),
              'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
              'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
              'source_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
              'candidate_pay_method', nullif(btrim(coalesce(v_case_state_from_map->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
              'segment_deltas', case
                when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
                when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            )
            || jsonb_build_object(
              'presentation_section', coalesce(v_selected_case_line->>'presentation_section', v_item->>'presentation_section'),
              'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
              'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
              'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
              'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
              'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
              'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
              'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false),
              'excluded_from_pay', (v_line_presentation_section = 'DO_NOT_PAY'),
              'is_do_not_pay', (v_line_presentation_section = 'DO_NOT_PAY')
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        else
          v_item := (v_item
            - 'case_resolution_summary'
            - 'components'
            - 'taxable_manual_debt_resolution')
            || jsonb_build_object(
              'case_resolution_summary', coalesce(v_case_state_from_map->'case_resolution_summary', '{}'::jsonb),
              'components', coalesce(v_case_state_from_map->'components', '[]'::jsonb)
            );

          if jsonb_typeof(v_case_state_from_map->'taxable_manual_debt_resolution') = 'object' then
            v_item := v_item || jsonb_build_object('taxable_manual_debt_resolution', v_case_state_from_map->'taxable_manual_debt_resolution');
          end if;
        end if;

        if upper(btrim(coalesce(v_case_state_from_map->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT') then
          v_case_state_timesheet_id := btrim(coalesce(v_case_state_from_map->>'timesheet_id', ''));
          if v_case_state_timesheet_id <> '' and exists (
            select 1
            from jsonb_array_elements(v_exclude_timesheet_ids) as excluded(value)
            where btrim(trim(both '"' from excluded.value::text)) = v_case_state_timesheet_id
          ) then
            v_item := v_item || jsonb_build_object('excluded_from_pay', true, 'is_do_not_pay', true);
          end if;
        end if;
      end if;
      v_updated_itemisation := v_updated_itemisation || jsonb_build_array(v_item);
    end loop;
  else
    v_updated_itemisation := v_itemisation;
  end if;

  for v_case_state in
    select elem.value
    from jsonb_array_elements(v_updated_case_states) as elem(value)
    where jsonb_typeof(elem.value) = 'object'
      and upper(btrim(coalesce(elem.value->>'case_scope', ''))) in ('TIMESHEET', 'TIMESHEET_PAYMENT')
  loop
    v_case_state_case_key := btrim(coalesce(v_case_state->>'case_key', ''));
    if v_case_state_case_key = '' then
      continue;
    end if;

    select exists (
      select 1
      from jsonb_array_elements(coalesce(v_updated_itemisation, '[]'::jsonb)) as item_elem(value)
      where jsonb_typeof(item_elem.value) = 'object'
        and btrim(coalesce(item_elem.value->>'case_key', '')) = v_case_state_case_key
    ) into v_itemisation_match_found;

    if v_itemisation_match_found then
      continue;
    end if;

    select line_choice.value
    into v_selected_case_line
    from (
      select
        line_elem.value,
        case upper(btrim(coalesce(line_elem.value->>'presentation_section', '')))
          when 'CASES_RESOLUTIONS' then 0
          when 'READY_TO_PAY' then 1
          when 'BLOCKED_FOR_PAY' then 2
          when 'DO_NOT_PAY' then 3
          else 9
        end as sort_ord
      from jsonb_array_elements(coalesce(v_updated_lines, '[]'::jsonb)) as line_elem(value)
      where jsonb_typeof(line_elem.value) = 'object'
        and btrim(coalesce(line_elem.value->>'case_key', '')) = v_case_state_case_key
    ) line_choice
    order by line_choice.sort_ord, coalesce(line_choice.value->>'line_id', '')
    limit 1;

    if v_selected_case_line is null then
      continue;
    end if;

    v_line_amount_ex_vat := case when coalesce(v_selected_case_line->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_ex_vat')::numeric, 2) else 0::numeric end;

    v_itemisation_append_json := jsonb_build_object(
      'preview_row_id', nullif(btrim(coalesce(v_selected_case_line->>'preview_row_id', '')), ''),
      'line_id', nullif(btrim(coalesce(v_selected_case_line->>'line_id', '')), ''),
      'timesheet_id', nullif(btrim(coalesce(v_selected_case_line->>'timesheet_id', v_case_state->>'timesheet_id', '')), ''),
      'week_ending_date', nullif(btrim(coalesce(v_selected_case_line->>'week_ending_date', v_case_state->>'week_ending_date', '')), ''),
      'client_id', nullif(btrim(coalesce(v_selected_case_line->>'client_id', v_case_state->>'client_id', '')), ''),
      'client_name', nullif(btrim(coalesce(v_selected_case_line->>'client_name', v_case_state->>'client_name', '')), ''),
      'payment_amount_ex_vat', round(v_line_amount_ex_vat, 2),
      'payment_amount_inc_vat', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'payment_amount', case when coalesce(v_selected_case_line->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then round((v_selected_case_line->>'amount_display')::numeric, 2) else round(v_line_amount_ex_vat, 2) end,
      'source_pay_method', nullif(btrim(coalesce(v_case_state->>'source_pay_method', v_selected_case_line->>'source_pay_method', '')), ''),
      'candidate_pay_method', nullif(btrim(coalesce(v_case_state->>'candidate_pay_method', v_selected_case_line->>'pay_channel', '')), ''),
      'segment_deltas', case
        when jsonb_typeof(v_selected_case_line->'section_segment_rows') = 'array' then coalesce(v_selected_case_line->'section_segment_rows', '[]'::jsonb)
        when jsonb_typeof(v_selected_case_line->'segment_rows') = 'array' then coalesce(v_selected_case_line->'segment_rows', '[]'::jsonb)
        else '[]'::jsonb
      end,
      'adjustment_deltas', '[]'::jsonb,
      'delta_additional_pay_ex_vat', 0,
      'additional_unit_deltas', '[]'::jsonb,
      'reservation_overrun_detected', false,
      'delta_expenses_pay_ex_vat', 0,
      'delta_travel_pay_ex_vat', 0,
      'delta_accommodation_pay_ex_vat', 0,
      'delta_other_pay_ex_vat', 0,
      'delta_mileage_pay_ex_vat', 0,
      'case_key', v_case_state_case_key,
      'case_resolution_summary', coalesce(v_case_state->'case_resolution_summary', '{}'::jsonb),
      'components', coalesce(v_case_state->'components', '[]'::jsonb),
      'presentation_section', coalesce(v_selected_case_line->>'presentation_section', 'CASES_RESOLUTIONS'),
      'presentation_role', coalesce(v_selected_case_line->>'presentation_role', 'PARENT'),
      'total_segment_count', case when coalesce(v_selected_case_line->>'total_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'total_segment_count')::int else 0 end,
      'ready_segment_count', case when coalesce(v_selected_case_line->>'ready_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'ready_segment_count')::int else 0 end,
      'blocked_visible_segment_count', case when coalesce(v_selected_case_line->>'blocked_visible_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'blocked_visible_segment_count')::int else 0 end,
      'hidden_indefinite_segment_count', case when coalesce(v_selected_case_line->>'hidden_indefinite_segment_count', '') ~ '^[0-9]+$' then (v_selected_case_line->>'hidden_indefinite_segment_count')::int else 0 end,
      'is_partially_ready', coalesce(nullif(v_selected_case_line->>'is_partially_ready', '')::boolean, false),
      'is_partially_blocked', coalesce(nullif(v_selected_case_line->>'is_partially_blocked', '')::boolean, false)
    );

    if jsonb_typeof(v_case_state->'taxable_manual_debt_resolution') = 'object' then
      v_itemisation_append_json := v_itemisation_append_json || jsonb_build_object('taxable_manual_debt_resolution', v_case_state->'taxable_manual_debt_resolution');
    end if;

    v_updated_itemisation := coalesce(v_updated_itemisation, '[]'::jsonb) || jsonb_build_array(v_itemisation_append_json);
  end loop;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'display_name', ''), coalesce(elem.value->>'line_type', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_updated_lines
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      (coalesce(elem.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((elem.value->>'amount_ex_vat')::numeric, 2) <> 0)
      or upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
    );


  if jsonb_array_length(coalesce(v_updated_lines, '[]'::jsonb)) = 0 and jsonb_array_length(coalesce(v_lines, '[]'::jsonb)) > 0 then
    select coalesce(jsonb_agg(baseline_line.value order by coalesce(baseline_line.value->>'candidate_id', ''), coalesce(baseline_line.value->>'display_name', ''), coalesce(baseline_line.value->>'line_type', ''), coalesce(baseline_line.value->>'line_id', '')), '[]'::jsonb)
    into v_updated_lines
    from jsonb_array_elements(v_lines) as baseline_line(value)
    where jsonb_typeof(baseline_line.value) = 'object'
      and (
        (coalesce(baseline_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' and round((baseline_line.value->>'amount_ex_vat')::numeric, 2) <> 0)
        or upper(btrim(coalesce(baseline_line.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      );
  end if;

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_blocked_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'BLOCKED_FOR_PAY';

  select coalesce(jsonb_agg(elem.value order by coalesce(elem.value->>'candidate_id', ''), coalesce(elem.value->>'timesheet_id', ''), coalesce(elem.value->>'line_id', '')), '[]'::jsonb)
  into v_do_not_pay_items
  from jsonb_array_elements(v_updated_lines) as elem(value)
  where jsonb_typeof(elem.value) = 'object'
    and (
      upper(btrim(coalesce(elem.value->>'presentation_section', ''))) = 'DO_NOT_PAY'
      or coalesce((elem.value->>'is_do_not_pay')::boolean, false) = true
    );

  v_candidate_row := (coalesce(v_candidate_row, '{}'::jsonb)
    - 'case_resolution_states'
    - 'canonical_preview_lines'
    - 'itemisation'
    - 'blocked_items'
    - 'do_not_pay_items'
    - 'snoozed_items'
    - 'hidden_recovery_template_lines'
    - 'hidden_recovery_template_line_count')
    || jsonb_build_object(
      'candidate_id', v_candidate_id,
      'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
      'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
      'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
      'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
      'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
      'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
      'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count
    );

  return jsonb_build_object(
    'candidate_id', v_candidate_id,
    'candidate_row', coalesce(v_candidate_row, '{}'::jsonb),
    'summary_fragment', coalesce(v_summary_fragment, '{}'::jsonb),
    'case_resolution_states', coalesce(v_updated_case_states, '[]'::jsonb),
    'canonical_preview_lines', coalesce(v_updated_lines, '[]'::jsonb),
    'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
    'hidden_recovery_template_line_count', v_hidden_recovery_template_line_count,
    'payees', coalesce(v_payees, '[]'::jsonb),
    'itemisation', coalesce(v_updated_itemisation, '[]'::jsonb),
    'blocked_items', coalesce(v_blocked_items, '[]'::jsonb),
    'do_not_pay_items', coalesce(v_do_not_pay_items, '[]'::jsonb),
    'snoozed_items', coalesce(v_snoozed_items, '[]'::jsonb),
    'baseline_component_rows', coalesce(v_final_component_rows, '[]'::jsonb),
    'timesheet_snapshots_json', coalesce(v_timesheet_snapshots_json, '[]'::jsonb)
  );
end;
$function$;






CREATE OR REPLACE FUNCTION public.pay_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_preview_decisions_json jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_scope_candidate_id_text text := '';
  v_candidate_baseline_json jsonb := '{}'::jsonb;
  v_candidate_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
begin
  v_context_json := public.pay_preview_build_context(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => p_preview_decisions_json
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'pay_preview_build_context(...) must return a JSON object';
  end if;

  v_scope_candidate_ids := case
    when jsonb_typeof(v_context_json->'scope_candidate_ids') = 'array' then coalesce(v_context_json->'scope_candidate_ids', '[]'::jsonb)
    else '[]'::jsonb
  end;

  for v_scope_candidate_id_text in
    select btrim(scope_candidate.value)
    from jsonb_array_elements_text(v_scope_candidate_ids) as scope_candidate(value)
    where btrim(scope_candidate.value) <> ''
    order by btrim(scope_candidate.value)
  loop
    v_candidate_baseline_json := public.pay_preview_build_candidate_baseline(
      p_context_json => v_context_json,
      p_candidate_id => v_scope_candidate_id_text::uuid
    );

    v_candidate_effective_json := public.pay_preview_apply_candidate_overlay(
      p_candidate_baseline_json => v_candidate_baseline_json,
      p_case_resolutions_json => coalesce(v_context_json->'preview_case_resolutions', '{}'::jsonb),
      p_overrides_json => coalesce(v_context_json->'preview_decisions_json', '{}'::jsonb)
    );

    v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
      p_context_json => v_context_json,
      p_candidate_effective_json => v_candidate_effective_json
    );

    v_candidate_rollups_json := v_candidate_rollups_json || jsonb_build_array(v_candidate_rollup_json);
  end loop;

  return public.pay_preview_assemble_payload(
    p_context_json => v_context_json,
    p_candidate_rollups_json => v_candidate_rollups_json
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_canonical_lines(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.finance_case_resolution_rollup') is null then
    perform public.pay_preview_candidate_build_finance_case_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.hidden_recovery_template_lines, pg_temp.manual_adjustment_carry_forward_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup;

  create temporary table canonical_timesheet_lines on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tb.ts_booking_id as booking_id,
          tb.ts_role,
          tb.ts_band,
          tcr.client_id,
          tcr.ts_client_name as client_name,
          tcr.ts_week_ending_date as week_ending_date,
          tcr.ts_pay_method as source_pay_method,
          tcr.umb_vat_chargeable,
          cp.cand_pay_method as candidate_pay_method,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          (cp.is_ready_for_draft and coalesce(tcr.is_blocked, false) = false) as is_ready_for_draft,
          ato.override_id,
          ato.override_reason,
          ats.snooze_id,
          ats.snooze_until_date,
          ats.note as snooze_note,
          round(coalesce(tcr.payment_amount_ex_vat,0),2) as amount_ex_vat,
          round(coalesce(tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, 0),2) as amount_display,
          coalesce(tcr.is_blocked, false) as case_is_blocked,
          coalesce(tcr.case_resolution_summary_json, '{}'::jsonb) as case_resolution_summary_json,
          coalesce(tcr.case_components_json, '[]'::jsonb) as case_components_json,
          coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                'segment_key', nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                'segment_stable_key', coalesce(
                  nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                  nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                ),
                'date', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')),
                'client_name', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'client_name','')), ''), tcr.ts_client_name),
                'role', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'role','')), ''), tb.ts_role),
                'band', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'band','')), ''), tb.ts_band),
                'start', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')),
                'finish', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'end_hhmm','')), '')),
                'start_utc', nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), ''),
                'end_utc', nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), ''),
                'break_start', nullif(btrim(coalesce(cur_seg.seg->>'break_start','')), ''),
                'break_end', nullif(btrim(coalesce(cur_seg.seg->>'break_end','')), ''),
                'break_mins', coalesce(nullif(cur_seg.seg->>'break_mins','')::numeric, nullif(cur_seg.seg->>'break_minutes','')::numeric),
                'breaks', coalesce(cur_seg.seg->'breaks', '[]'::jsonb),
                'ref_num', coalesce(nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')),
                'pay_amount_ex_vat', round(coalesce(nullif(delta_seg.seg->>'delta_pay_ex_vat','')::numeric,0),2),
                'snooze_identity', jsonb_build_object(
                  'identity_type', 'TIMESHEET_SEGMENT',
                  'timesheet_id', tcr.timesheet_id::text,
                  'booking_id', tb.ts_booking_id,
                  'segment_id', nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                    nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
                  ),
                  'source_ref', null
                ),
                'snooze_state', case
                  when ass.snooze_id is null then jsonb_build_object('state','NONE')
                  when ass.snooze_until_date is null then jsonb_build_object(
                    'state', 'INDEFINITE_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', null,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                  else jsonb_build_object(
                    'state', 'DATED_SNOOZED',
                    'snooze_id', ass.snooze_id::text,
                    'snooze_until_date', ass.snooze_until_date::text,
                    'note', ass.note,
                    'snooze_kind', ass.snooze_kind
                  )
                end
              )
              order by
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''), nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(cur_seg.seg->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'start_hhmm','')), '')) nulls last,
                coalesce(nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''), nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), '')) nulls last,
                nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') nulls last
            )
            from jsonb_array_elements(coalesce(tcr.segment_deltas_json, '[]'::jsonb)) as delta_seg(seg)
            left join lateral (
              select seg.value as seg
              from jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) as seg(value)
              where coalesce(
                      nullif(btrim(coalesce(seg.value->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_id','')), ''),
                      nullif(btrim(coalesce(seg.value->>'segment_key','')), ''),
                      nullif(btrim(coalesce(seg.value->>'date','')), ''),
                      nullif(btrim(coalesce(seg.value->>'ref_num','')), '')
                    ) is not distinct from coalesce(
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_id','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'segment_key','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'work_date','')), ''),
                      nullif(btrim(coalesce(delta_seg.seg->>'ref_num','')), '')
                    )
              order by 1
              limit 1
            ) cur_seg on true
            left join active_segment_snoozes ass
              on ass.candidate_id = tcr.candidate_id
             and (
               (ass.booking_id is not null and ass.booking_id = tb.ts_booking_id and ass.segment_stable_key is not distinct from coalesce(
                 nullif(btrim(coalesce(delta_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
                 nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
               ))
               or (ass.booking_id is null and ass.timesheet_id = tcr.timesheet_id and ass.segment_id is not distinct from nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''))
             )
          ), '[]'::jsonb) as segment_rows_json
        from timesheet_case_rollup_effective tcr
        join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
        join ts_baseline tb
          on tb.timesheet_id = tcr.timesheet_id
         and tb.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_overrides ato
          on ato.timesheet_id = tcr.timesheet_id
         and ato.candidate_id = tcr.candidate_id
        left join active_timesheet_payment_snoozes ats
          on ats.candidate_id = tcr.candidate_id
         and (
           (ats.booking_id is not null and ats.booking_id = tb.ts_booking_id)
           or (ats.booking_id is null and ats.timesheet_id = tcr.timesheet_id)
         )
        where round(coalesce(tcr.payment_amount_ex_vat,0),2) <> 0
          and not (ats.snooze_id is not null and ats.snooze_until_date is null)
  
  ;

  create temporary table timesheet_active_segment_snooze_meta on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          count(*)::int as active_segment_snooze_count,
          count(*) filter (where ass.snooze_until_date is not null)::int as active_segment_dated_snooze_count,
          count(*) filter (where ass.snooze_until_date is null)::int as active_segment_indefinite_snooze_count
        from canonical_timesheet_lines ctl
        join active_segment_snoozes ass
          on ass.candidate_id = ctl.candidate_id
         and (
           (ass.booking_id is not null and ctl.booking_id is not null and ass.booking_id = ctl.booking_id)
           or (ass.booking_id is null and ass.timesheet_id = ctl.timesheet_id)
         )
        group by ctl.candidate_id, ctl.timesheet_id, ctl.booking_id
  
  ;

  create temporary table canonical_timesheet_segment_rows on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          cur_seg_norm.seg_ord,
          cur_seg_norm.segment_id,
          cur_seg_norm.segment_key,
          cur_seg_norm.segment_stable_key,
          cur_seg_norm.segment_date,
          cur_seg_norm.client_name,
          cur_seg_norm.role,
          cur_seg_norm.band,
          cur_seg_norm.start_hhmm,
          cur_seg_norm.finish_hhmm,
          cur_seg_norm.start_utc,
          cur_seg_norm.end_utc,
          cur_seg_norm.break_start,
          cur_seg_norm.break_end,
          cur_seg_norm.break_mins,
          cur_seg_norm.breaks,
          coalesce(cur_seg_norm.ref_num, ss_match.ref_num) as ref_num,
          round(
            case
              when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
              when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
              else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
            end,
            2
          ) as presentation_amount_ex_vat,
          round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) as raw_delta_ex_vat,
          round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) as effective_delta_ex_vat,
          coalesce(ss_match.is_blocked, false) as status_is_blocked,
          coalesce(ss_match.is_do_not_pay, false) as status_is_do_not_pay,
          ass_match.snooze_id as segment_snooze_id,
          ass_match.snooze_until_date as segment_snooze_until_date,
          ass_match.note as segment_snooze_note,
          ass_match.snooze_kind as segment_snooze_kind,
          case
            when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
            when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
            when coalesce(ss_match.is_blocked, false) = true
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'BLOCKED_VISIBLE'
            when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
             and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
            then 'READY'
            else 'IGNORED'
          end as presentation_segment_state,
          jsonb_build_object(
            'timesheet_id', ctl.timesheet_id::text,
            'booking_id', ctl.booking_id,
            'segment_id', cur_seg_norm.segment_id,
            'segment_key', cur_seg_norm.segment_key,
            'segment_stable_key', cur_seg_norm.segment_stable_key,
            'date', cur_seg_norm.segment_date,
            'client_name', cur_seg_norm.client_name,
            'role', cur_seg_norm.role,
            'band', cur_seg_norm.band,
            'start', cur_seg_norm.start_hhmm,
            'finish', cur_seg_norm.finish_hhmm,
            'start_utc', cur_seg_norm.start_utc,
            'end_utc', cur_seg_norm.end_utc,
            'break_start', cur_seg_norm.break_start,
            'break_end', cur_seg_norm.break_end,
            'break_mins', cur_seg_norm.break_mins,
            'breaks', cur_seg_norm.breaks,
            'ref_num', coalesce(cur_seg_norm.ref_num, ss_match.ref_num),
            'pay_amount_ex_vat', round(
              case
                when ass_match.snooze_id is not null then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, ss_match.eff_delta_ex, 0)
                when coalesce(ss_match.is_blocked, false) = true or coalesce(ss_match.is_do_not_pay, false) = true then coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0)
                else coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0)
              end,
              2
            ),
            'raw_delta_ex_vat', round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2),
            'effective_delta_ex_vat', round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2),
            'is_blocked', coalesce(ss_match.is_blocked, false),
            'is_do_not_pay', coalesce(ss_match.is_do_not_pay, false),
            'presentation_segment_state', case
              when ass_match.snooze_id is not null and ass_match.snooze_until_date is null then 'HIDDEN_INDEFINITE'
              when ass_match.snooze_id is not null then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_do_not_pay, false) = true then 'BLOCKED_VISIBLE'
              when coalesce(ss_match.is_blocked, false) = true
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'BLOCKED_VISIBLE'
              when round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
               and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              then 'READY'
              else 'IGNORED'
            end,
            'is_ready_segment', (
              ass_match.snooze_id is null
              and coalesce(ss_match.is_blocked, false) = false
              and coalesce(ss_match.is_do_not_pay, false) = false
              and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              and round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
            ),
            'is_blocked_visible_segment', (
              (ass_match.snooze_id is not null and ass_match.snooze_until_date is not null)
              or (
                coalesce(ss_match.is_blocked, false) = true
                and not (coalesce(ttre_match.requires_resolution, false) = true and coalesce(ttre_match.is_actionable_resolution_row, false) = true)
              )
              or coalesce(ss_match.is_do_not_pay, false) = true
            ),
            'is_hidden_indefinite_segment', (ass_match.snooze_id is not null and ass_match.snooze_until_date is null),
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', ctl.timesheet_id::text,
              'booking_id', ctl.booking_id,
              'segment_id', cur_seg_norm.segment_id,
              'segment_stable_key', cur_seg_norm.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', case
              when ass_match.snooze_id is null then jsonb_build_object('state', 'NONE')
              when ass_match.snooze_until_date is null then jsonb_build_object(
                'state', 'INDEFINITE_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', null,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
              else jsonb_build_object(
                'state', 'DATED_SNOOZED',
                'snooze_id', ass_match.snooze_id::text,
                'snooze_until_date', ass_match.snooze_until_date::text,
                'note', ass_match.note,
                'snooze_kind', ass_match.snooze_kind
              )
            end
          ) as segment_base_json
        from canonical_timesheet_lines ctl
        join ts_baseline tb
          on tb.timesheet_id = ctl.timesheet_id
         and tb.candidate_id = ctl.candidate_id
        cross join lateral jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg_json, seg_ord)
        cross join lateral (
          select
            cur_seg.seg_ord,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), '') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), '') as segment_key,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_stable_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_id','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), ''),
              nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '')
            ) as segment_stable_key,
            nullif(btrim(coalesce(cur_seg.seg_json->>'date','')), '') as segment_date,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'client_name','')), ''), ctl.client_name) as client_name,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'role','')), ''), ctl.ts_role) as role,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'band','')), ''), ctl.ts_band) as band,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'start','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'start_hhmm','')), '')) as start_hhmm,
            coalesce(nullif(btrim(coalesce(cur_seg.seg_json->>'end','')), ''), nullif(btrim(coalesce(cur_seg.seg_json->>'end_hhmm','')), '')) as finish_hhmm,
            nullif(btrim(coalesce(cur_seg.seg_json->>'start_utc','')), '') as start_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'end_utc','')), '') as end_utc,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_start','')), '') as break_start,
            nullif(btrim(coalesce(cur_seg.seg_json->>'break_end','')), '') as break_end,
            coalesce(nullif(cur_seg.seg_json->>'break_mins','')::numeric, nullif(cur_seg.seg_json->>'break_minutes','')::numeric) as break_mins,
            case when jsonb_typeof(cur_seg.seg_json->'breaks') = 'array' then cur_seg.seg_json->'breaks' else '[]'::jsonb end as breaks,
            nullif(btrim(coalesce(cur_seg.seg_json->>'ref_num','')), '') as ref_num
        ) cur_seg_norm
        left join lateral (
          select
            ss.segment_id,
            ss.segment_stable_key,
            ss.ref_num,
            ss.work_date,
            ss.delta_pay_ex_vat,
            ss.eff_delta_ex,
            ss.is_blocked,
            ss.is_do_not_pay
          from segment_status ss
          where ss.candidate_id = ctl.candidate_id
            and ss.timesheet_id = ctl.timesheet_id
            and (
              (cur_seg_norm.segment_stable_key is not null and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and ss.segment_id is not distinct from cur_seg_norm.segment_id
              )
            )
          order by
            case
              when cur_seg_norm.segment_stable_key is not null
               and ss.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key
              then 0 else 1
            end,
            case
              when cur_seg_norm.segment_id is not null
               and ss.segment_id is not distinct from cur_seg_norm.segment_id
              then 0 else 1
            end,
            ss.segment_stable_key nulls last,
            ss.segment_id nulls last
          limit 1
        ) ss_match on true
        left join lateral (
          select
            round(sum(coalesce(ttre.preview_component_amount_ex_vat, 0)), 2) as preview_component_amount_ex_vat,
            round(sum(coalesce(ttre.ready_preview_amount_ex_vat, ttre.preview_component_amount_ex_vat, 0)), 2) as ready_preview_amount_ex_vat,
            bool_or(coalesce(ttre.requires_resolution, false)) as requires_resolution,
            bool_or(coalesce(ttre.is_actionable_resolution_row, false)) as is_actionable_resolution_row
          from transient_timesheet_component_review_rows_effective ttre
          where ttre.candidate_id = ctl.candidate_id
            and ttre.timesheet_id = ctl.timesheet_id
            and ttre.component_key_type in ('TS_DAY','TS_TOTAL')
            and (
              (
                cur_seg_norm.segment_stable_key is not null
                and coalesce(
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_stable_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'segment_key','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'work_date','')), ''),
                  nullif(btrim(coalesce(ttre.source_basis_json->>'ref_num','')), '')
                ) is not distinct from cur_seg_norm.segment_stable_key
              )
              or (
                cur_seg_norm.segment_stable_key is null
                and cur_seg_norm.segment_id is not null
                and nullif(btrim(coalesce(ttre.source_basis_json->>'segment_id','')), '') is not distinct from cur_seg_norm.segment_id
              )
            )
        ) ttre_match on true
        left join lateral (
          select
            ass.snooze_id,
            ass.snooze_until_date,
            ass.note,
            ass.snooze_kind,
            ass.segment_id,
            ass.segment_stable_key
          from active_segment_snoozes ass
          where ass.candidate_id = ctl.candidate_id
            and (
              (
                ass.booking_id is not null
                and ctl.booking_id is not null
                and ass.booking_id = ctl.booking_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
              or (
                ass.booking_id is null
                and ass.timesheet_id = ctl.timesheet_id
                and (
                  (cur_seg_norm.segment_stable_key is not null and ass.segment_stable_key is not distinct from cur_seg_norm.segment_stable_key)
                  or (
                    cur_seg_norm.segment_stable_key is null
                    and cur_seg_norm.segment_id is not null
                    and ass.segment_id is not distinct from cur_seg_norm.segment_id
                  )
                )
              )
            )
          order by
            case when ass.segment_stable_key is not null then 0 else 1 end,
            ass.snooze_id
          limit 1
        ) ass_match on true
        where (
          ass_match.snooze_id is not null
          or coalesce(ss_match.is_blocked, false) = true
          or coalesce(ss_match.is_do_not_pay, false) = true
          or round(coalesce(ttre_match.ready_preview_amount_ex_vat, ttre_match.preview_component_amount_ex_vat, ss_match.eff_delta_ex, 0), 2) <> 0
          or round(coalesce(ttre_match.preview_component_amount_ex_vat, ss_match.delta_pay_ex_vat, 0), 2) <> 0
        )
  
  ;

  create temporary table canonical_timesheet_segment_rollup on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          coalesce(tasm.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(tasm.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(tasm.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          count(*) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE', 'HIDDEN_INDEFINITE'))::int as total_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'READY')::int as ready_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE')::int as blocked_visible_segment_count,
          count(*) filter (where ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE')::int as hidden_indefinite_segment_count,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'READY' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as ready_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'BLOCKED_VISIBLE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as blocked_visible_segment_amount_ex_vat,
          round(coalesce(sum(case when ctsr.presentation_segment_state = 'HIDDEN_INDEFINITE' then ctsr.presentation_amount_ex_vat else 0 end), 0), 2) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'READY'),
            '[]'::jsonb
          ) as ready_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state = 'BLOCKED_VISIBLE'),
            '[]'::jsonb
          ) as blocked_visible_segment_rows_json,
          coalesce(
            jsonb_agg(
              ctsr.segment_base_json || jsonb_build_object(
                'presentation_section', 'BLOCKED_FOR_PAY',
                'presentation_role', 'CHILD',
                'presentation_parent_line_id', ctl.timesheet_id::text,
                'has_active_timesheet_snooze', (ctl.snooze_id is not null),
                'has_active_segment_snoozes', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'active_segment_snooze_count', coalesce(tasm.active_segment_snooze_count, 0),
                'active_segment_dated_snooze_count', coalesce(tasm.active_segment_dated_snooze_count, 0),
                'active_segment_indefinite_snooze_count', coalesce(tasm.active_segment_indefinite_snooze_count, 0),
                'whole_timesheet_snooze_action_blocked', (coalesce(tasm.active_segment_snooze_count, 0) > 0),
                'whole_timesheet_snooze_action_block_reason', case when coalesce(tasm.active_segment_snooze_count, 0) > 0 then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
                'segment_snooze_action_blocked', (ctl.snooze_id is not null),
                'segment_snooze_action_block_reason', case when ctl.snooze_id is not null then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end
              )
              order by ctsr.seg_ord
            ) filter (where ctsr.presentation_segment_state in ('READY', 'BLOCKED_VISIBLE')),
            '[]'::jsonb
          ) as visible_segment_rows_json
        from canonical_timesheet_lines ctl
        left join timesheet_active_segment_snooze_meta tasm
          on tasm.candidate_id = ctl.candidate_id
         and tasm.timesheet_id = ctl.timesheet_id
         and tasm.booking_id is not distinct from ctl.booking_id
        left join canonical_timesheet_segment_rows ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
        group by
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.snooze_id,
          tasm.active_segment_snooze_count,
          tasm.active_segment_dated_snooze_count,
          tasm.active_segment_indefinite_snooze_count
  
  ;

  create temporary table canonical_timesheet_presentation_seed on commit drop as
        select
          ctl.candidate_id,
          ctl.timesheet_id,
          ctl.booking_id,
          ctl.ts_role,
          ctl.ts_band,
          ctl.client_id,
          ctl.client_name,
          ctl.week_ending_date,
          ctl.source_pay_method,
          ctl.umb_vat_chargeable,
          ctl.candidate_pay_method,
          ctl.cand_tms_ref,
          ctl.cand_display_name,
          ctl.payee_entity_kind,
          ctl.payee_entity_id,
          ctl.is_ready_for_draft,
          ctl.override_id,
          ctl.override_reason,
          ctl.snooze_id,
          ctl.snooze_until_date,
          ctl.snooze_note,
          ctl.amount_ex_vat,
          ctl.amount_display,
          ctl.case_is_blocked,
          ctl.case_resolution_summary_json,
          ctl.case_components_json,
          coalesce(ctsr.total_segment_count, 0) as total_segment_count,
          coalesce(ctsr.ready_segment_count, 0) as ready_segment_count,
          coalesce(ctsr.blocked_visible_segment_count, 0) as blocked_visible_segment_count,
          coalesce(ctsr.hidden_indefinite_segment_count, 0) as hidden_indefinite_segment_count,
          coalesce(ctsr.active_segment_snooze_count, 0) as active_segment_snooze_count,
          coalesce(ctsr.active_segment_dated_snooze_count, 0) as active_segment_dated_snooze_count,
          coalesce(ctsr.active_segment_indefinite_snooze_count, 0) as active_segment_indefinite_snooze_count,
          coalesce(ctsr.ready_segment_amount_ex_vat, 0) as ready_segment_amount_ex_vat,
          coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0) as blocked_visible_segment_amount_ex_vat,
          coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0) as hidden_indefinite_segment_amount_ex_vat,
          coalesce(ctsr.ready_segment_rows_json, '[]'::jsonb) as ready_segment_rows_json,
          coalesce(ctsr.blocked_visible_segment_rows_json, '[]'::jsonb) as blocked_visible_segment_rows_json,
          coalesce(ctsr.visible_segment_rows_json, '[]'::jsonb) as visible_segment_rows_json,
          round(
            coalesce(ctl.amount_ex_vat, 0)
            - coalesce(ctsr.ready_segment_amount_ex_vat, 0)
            - coalesce(ctsr.blocked_visible_segment_amount_ex_vat, 0)
            - coalesce(ctsr.hidden_indefinite_segment_amount_ex_vat, 0),
            2
          ) as non_segment_amount_ex_vat,
          (ctl.snooze_id is not null) as has_active_timesheet_snooze,
          (coalesce(ctsr.active_segment_snooze_count, 0) > 0) as has_active_segment_snoozes
        from canonical_timesheet_lines ctl
        left join canonical_timesheet_segment_rollup ctsr
          on ctsr.candidate_id = ctl.candidate_id
         and ctsr.timesheet_id = ctl.timesheet_id
         and ctsr.booking_id is not distinct from ctl.booking_id
  
  ;

  create temporary table canonical_timesheet_presentation_state on commit drop as
        select
          ctps.*,
          coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) as case_needs_resolution,
          exists (
            select 1
            from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as case_component(value)
            where coalesce(nullif(case_component.value->>'requires_resolution','')::boolean, false) = true
              and coalesce(nullif(case_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
          ) as has_actionable_resolution_component,
          round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) as ready_section_amount_ex_vat,
          round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0), 2) as blocked_section_amount_ex_vat,
          round(
            coalesce(
              nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
              nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
              0::numeric
            ),
            2
          ) as case_resolution_section_amount_ex_vat,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2),
                  v_vat_rate_pct,
                  ctps.umb_vat_chargeable
                )->>'inc')::numeric
              else round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2)
            end,
            2
          ) as ready_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0), 2), v_vat_rate_pct, ctps.umb_vat_chargeable)->>'inc')::numeric
              else round(coalesce(ctps.blocked_visible_segment_amount_ex_vat, 0), 2)
            end,
            2
          ) as blocked_section_amount_display,
          round(
            case
              when ctps.source_pay_method = 'UMBRELLA' then (public._pay_umbrella_vat_calc(
                round(
                  coalesce(
                    nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                    nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                    0::numeric
                  ),
                  2
                ),
                v_vat_rate_pct,
                ctps.umb_vat_chargeable
              )->>'inc')::numeric
              else round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              )
            end,
            2
          ) as case_resolution_section_amount_display,
          (
            round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
            or coalesce(ctps.ready_segment_count, 0) > 0
          ) as has_ready_presentation,
          (
            ctps.case_is_blocked = false
            and ctps.has_active_timesheet_snooze = false
            and ctps.is_ready_for_draft = false
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
          ) as has_non_resolution_readiness_block,
          (
            ctps.has_active_timesheet_snooze = true
            or coalesce(ctps.blocked_visible_segment_count, 0) > 0
            or (
              ctps.case_is_blocked = false
              and ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_blocked_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = true
            and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = true
            and (
              round(
                coalesce(
                  nullif(ctps.case_resolution_summary_json->>'blocked_case_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'unresolved_taxable_amount_ex_vat', '')::numeric,
                  nullif(ctps.case_resolution_summary_json->>'safe_amount_ex_vat', '')::numeric,
                  0::numeric
                ),
                2
              ) <> 0
              or exists (
                select 1
                from jsonb_array_elements(coalesce(ctps.case_components_json, '[]'::jsonb)) as actionable_component(value)
                where coalesce(nullif(actionable_component.value->>'requires_resolution','')::boolean, false) = true
                  and coalesce(nullif(actionable_component.value->>'is_actionable_resolution_row','')::boolean, false) = true
              )
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) = 0
            and not (
              ctps.case_is_blocked = false
              and ctps.has_active_timesheet_snooze = false
              and ctps.is_ready_for_draft = false
              and coalesce(nullif(ctps.case_resolution_summary_json->>'case_needs_resolution','')::boolean, false) = false
              and (
                round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
                or coalesce(ctps.ready_segment_count, 0) > 0
              )
            )
          ) as has_case_resolution_presentation,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) > 0
          ) as is_partially_ready,
          (
            ctps.has_active_timesheet_snooze = false
            and ctps.case_is_blocked = false
            and (
              round(coalesce(ctps.ready_segment_amount_ex_vat, 0) + coalesce(ctps.non_segment_amount_ex_vat, 0), 2) <> 0
              or coalesce(ctps.ready_segment_count, 0) > 0
            )
            and coalesce(ctps.blocked_visible_segment_count, 0) > 0
          ) as is_partially_blocked
        from canonical_timesheet_presentation_seed ctps

  ;

  create temporary table canonical_timesheet_presentation_rows on commit drop as
        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'amount_display', ctpp.ready_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', ctpp.is_ready_for_draft,
              'segment_rows', ctpp.ready_segment_rows_json,
              'segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb))
            )
            || jsonb_build_object(
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.is_partially_ready then (ctpp.timesheet_id::text || ':01:ready')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', ctpp.ready_section_amount_ex_vat,
              'section_amount_display', ctpp.ready_section_amount_display,
              'section_segment_rows', ctpp.ready_segment_rows_json,
              'section_segment_count', jsonb_array_length(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)),
              'section_non_segment_amount_ex_vat', ctpp.non_segment_amount_ex_vat
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.is_partially_ready then 'PARTIAL_READY_TO_PAY'
                when ctpp.hidden_indefinite_segment_count > 0 then 'READY_WITH_HIDDEN_INDEFINITE_SEGMENTS'
                else 'READY_TO_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_ready then 'Some segments are blocked'
                when ctpp.hidden_indefinite_segment_count > 0 then 'Some segments are snoozed indefinitely'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.ready_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_active_timesheet_snooze = false
          and ctpp.case_is_blocked = false
          and ctpp.has_ready_presentation = true
          and ctpp.is_ready_for_draft = true
        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', (ctpp.timesheet_id::text || ':03:case'),
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'amount_display', ctpp.case_resolution_section_amount_display,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', case
                when jsonb_typeof(ctpp.case_resolution_summary_json->'blocked_reason_codes') = 'array'
                then coalesce(ctpp.case_resolution_summary_json->'blocked_reason_codes', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'is_excluded_from_allocation', false,
              'is_ready_for_draft', false,
              'segment_rows', '[]'::jsonb,
              'segment_count', 0
            )
            || jsonb_build_object(
              'presentation_section', 'CASES_RESOLUTIONS',
              'presentation_role', 'PARENT',
              'presentation_line_id', (ctpp.timesheet_id::text || ':03:case'),
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', false,
              'is_partially_blocked', false,
              'section_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat,
              'section_amount_display', ctpp.case_resolution_section_amount_display,
              'section_segment_rows', '[]'::jsonb,
              'section_segment_count', 0,
              'section_non_segment_amount_ex_vat', ctpp.case_resolution_section_amount_ex_vat
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', 'CASE_RESOLUTION_REQUIRED',
              'presentation_advisory_text', 'Resolve this case before draft'
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          ctpp.case_resolution_section_amount_ex_vat as amount_ex_vat,
          false as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_case_resolution_presentation = true


        union all

        select
          ctpp.candidate_id,
          (
            jsonb_build_object(
              'line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'candidate_id', ctpp.candidate_id::text,
              'tms_ref', ctpp.cand_tms_ref,
              'display_name', ctpp.cand_display_name,
              'line_type', 'TIMESHEET_PAYMENT',
              'finance_case_id', null,
              'case_key', ('timesheet:' || ctpp.timesheet_id::text),
              'case_type', 'TIMESHEET_PAYMENT',
              'case_is_blocked', ctpp.case_is_blocked,
              'case_resolution_summary', ctpp.case_resolution_summary_json,
              'case_components', ctpp.case_components_json,
              'timesheet_id', ctpp.timesheet_id::text,
              'booking_id', ctpp.booking_id,
              'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
              'client_name', ctpp.client_name,
              'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
              'role', ctpp.ts_role,
              'band', ctpp.ts_band,
              'linked_shift_date', null,
              'pay_channel', ctpp.candidate_pay_method,
              'paye_treatment', case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
              'route_type', 'NORMAL_PAYMENT',
              'adjustment_comment', null
            )
            || jsonb_build_object(
              'amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'is_advanced', (ctpp.override_id is not null),
              'advanced_override_id', case when ctpp.override_id is null then null else ctpp.override_id::text end,
              'advanced_reason', ctpp.override_reason,
              'blocked_reason_codes', (
                (case
                  when ctpp.has_active_timesheet_snooze = true then jsonb_build_array('BLOCKED_DATED_SNOOZE')
                  else '[]'::jsonb
                end)
              ),
              'is_excluded_from_allocation', (ctpp.has_active_timesheet_snooze = true),
              'is_ready_for_draft', case
                when ctpp.has_active_timesheet_snooze = true then ctpp.is_ready_for_draft
                else false
              end,
              'segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end
            )
            || jsonb_build_object(
              'presentation_section', 'BLOCKED_FOR_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', case
                when ctpp.has_active_timesheet_snooze = false
                 and ctpp.case_is_blocked = false
                 and ctpp.has_ready_presentation = true
                 and ctpp.blocked_visible_segment_count > 0
                then (ctpp.timesheet_id::text || ':02:blocked')
                else ctpp.timesheet_id::text
              end,
              'presentation_parent_line_id', ctpp.timesheet_id::text,
              'real_business_timesheet_id', ctpp.timesheet_id::text,
              'total_segment_count', ctpp.total_segment_count,
              'ready_segment_count', ctpp.ready_segment_count,
              'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
              'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
              'is_partially_ready', ctpp.is_partially_ready,
              'is_partially_blocked', ctpp.is_partially_blocked,
              'section_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
                else ctpp.blocked_section_amount_ex_vat
              end,
              'section_amount_display', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_display
                else ctpp.blocked_section_amount_display
              end,
              'section_segment_rows', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.visible_segment_rows_json
                else ctpp.blocked_visible_segment_rows_json
              end,
              'section_segment_count', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then jsonb_array_length(coalesce(ctpp.visible_segment_rows_json, '[]'::jsonb))
                else jsonb_array_length(coalesce(ctpp.blocked_visible_segment_rows_json, '[]'::jsonb))
              end,
              'section_non_segment_amount_ex_vat', case
                when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.non_segment_amount_ex_vat
                else 0
              end
            )
            || jsonb_build_object(
              'has_active_timesheet_snooze', ctpp.has_active_timesheet_snooze,
              'has_active_segment_snoozes', ctpp.has_active_segment_snoozes,
              'active_segment_snooze_count', ctpp.active_segment_snooze_count,
              'active_segment_dated_snooze_count', ctpp.active_segment_dated_snooze_count,
              'active_segment_indefinite_snooze_count', ctpp.active_segment_indefinite_snooze_count,
              'whole_timesheet_snooze_action_blocked', ctpp.has_active_segment_snoozes,
              'whole_timesheet_snooze_action_block_reason', case when ctpp.has_active_segment_snoozes then 'ACTIVE_SEGMENT_SNOOZES_EXIST' else null end,
              'segment_snooze_action_blocked', ctpp.has_active_timesheet_snooze,
              'segment_snooze_action_block_reason', case when ctpp.has_active_timesheet_snooze then 'WHOLE_TIMESHEET_SNOOZE_ACTIVE' else null end,
              'presentation_reason', case
                when ctpp.has_active_timesheet_snooze = true then 'WHOLE_TIMESHEET_SNOOZED'
                when ctpp.is_partially_blocked then 'PARTIAL_BLOCKED_FOR_PAY'
                else 'BLOCKED_FOR_PAY'
              end,
              'presentation_advisory_text', case
                when ctpp.is_partially_blocked then 'Some segments are ready to pay'
                else null
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'TIMESHEET',
                'timesheet_id', ctpp.timesheet_id::text,
                'booking_id', ctpp.booking_id,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', null
              ),
              'snooze_state', case
                when ctpp.snooze_id is null then jsonb_build_object('state', 'NONE')
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', ctpp.snooze_id::text,
                  'snooze_until_date', ctpp.snooze_until_date::text,
                  'note', ctpp.snooze_note
                )
              end
            )
          ) as line_json,
          ctpp.candidate_pay_method as pay_channel,
          case when ctpp.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end as paye_treatment,
          case
            when ctpp.has_active_timesheet_snooze = true or ctpp.has_non_resolution_readiness_block = true then ctpp.amount_ex_vat
            else ctpp.blocked_section_amount_ex_vat
          end as amount_ex_vat,
          (ctpp.has_active_timesheet_snooze = true) as is_excluded_from_allocation
        from canonical_timesheet_presentation_state ctpp
        where ctpp.has_blocked_presentation = true
          and (
            ctpp.has_active_timesheet_snooze = true
            or ctpp.has_non_resolution_readiness_block = true
            or ctpp.blocked_visible_segment_count > 0
          )
  
  ;

  create temporary table finance_case_lines on commit drop as
        select
          fcrr.candidate_id,
          fcrr.finance_case_id,
          fcrr.client_id,
          fcrr.client_name,
          fcrr.candidate_pay_method,
          fcrr.cand_tms_ref,
          fcrr.cand_display_name,
          fcrr.payee_entity_kind,
          fcrr.payee_entity_id,
          fcrr.candidate_ready_for_draft,
          fcrr.case_type,
          fcrr.taxability,
          fcrr.routing_kind,
          fcrr.destination_label,
          fcrr.beneficiary_name,
          fcrr.masked_bank_account,
          fcrr.payee_bank_hash,
          fcrr.adjustment_comment,
          fcrr.linked_timesheet_id,
          fcrr.linked_shift_date,
          fcrr.next_due_week_start,
          fcrr.active_snooze_id,
          fcrr.active_snooze_kind,
          fcrr.active_snooze_until_date,
          fcrr.active_snooze_note,
          fcrr.due_amount_ex_vat,
          fcrr.is_blocked as case_is_blocked,
          (
            coalesce(fcrr.blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then jsonb_build_array('BLOCKED_DATED_SNOOZE')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          fcrr.case_resolution_summary_json,
          fcrr.taxable_manual_debt_resolution_json,
          fcrr.case_components_json,
          fcrr.oneoff_bank_details_present,
          fcrr.is_candidate_directed_oneoff_payout,
          fcrr.appears_on_umbrella_remittance,
          fcrr.generates_candidate_payment_advice,
          fcrr.snooze_allowed,
          fcrr.lifecycle_status_display,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'LOAN_PAYOUT'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'PAYMENT_ADVANCE_REPAYMENT'
            when fcrr.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrr.case_type::text
          end as line_type,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'Loan payment'
            when fcrr.case_type = 'PAYMENT_ADVANCE' then 'Loan repayment'
            when fcrr.case_type = 'OVERPAYMENT' then 'Overpayment recovery'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual credit adjustment payment'
            when fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            else replace(fcrr.case_type::text, '_', ' ')
          end as item_type_label,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then 'PAYMENT'
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'PAYMENT'
            else 'DEDUCTION'
          end as item_direction,
          case
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
             and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID'
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'PAYMENT_ADVANCE'
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'OVERPAYMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_ADD'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
            then 'GROSS_DEDUCT'
            when fcrr.candidate_pay_method = 'PAYE'
             and fcrr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
             and fcrr.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
            then 'NET_DEDUCT'
            else 'NONE'
          end as paye_treatment,
          case
            when fcrr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcrr.lifecycle_status_display,'')) <> 'PAID' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            when fcrr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then round(coalesce(fcrr.due_amount_ex_vat,0),2)
            else round(-coalesce(fcrr.due_amount_ex_vat,0),2)
          end as signed_amount_ex_vat,
          case
            when fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null then 'BLOCKED_FOR_PAY'
            when fcrr.is_blocked then 'BLOCKED_FOR_PAY'
            else 'READY_TO_PAY'
          end as readiness_state,
          (
            fcrr.is_blocked = false
            and not (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
            and round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
          ) as draftable
        from finance_case_resolution_rollup fcrr
        where round(coalesce(fcrr.due_amount_ex_vat,0),2) > 0
  

  ;

  create temporary table hidden_recovery_template_lines on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          case
            when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
            when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
            when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
            else fcrrb.case_type::text
          end as recovery_family,
          ('advance:' || fcrrb.finance_case_id::text) as source_ref,
          row_number() over (
            partition by fcrrb.candidate_id,
                         case
                           when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                           when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                           when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                           else fcrrb.case_type::text
                         end
            order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
          )::integer as sort_order,
          jsonb_strip_nulls(
            jsonb_build_object(
              'template_state', 'HIDDEN_ZERO_TAKE',
              'candidate_id', fcrrb.candidate_id::text,
              'finance_case_id', fcrrb.finance_case_id::text,
              'recovery_family', case
                when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                else fcrrb.case_type::text
              end,
              'case_type', fcrrb.case_type::text,
              'source_ref', ('advance:' || fcrrb.finance_case_id::text),
              'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'umbrella_id', case when c.umbrella_id is null then null else c.umbrella_id::text end,
              'paye_treatment', case
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'PAYMENT_ADVANCE'
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'OVERPAYMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'TAXABLE'::public.pay_finance_taxability_enum
                then 'GROSS_DEDUCT'
                when upper(coalesce(fcrrb.candidate_pay_method, '')) = 'PAYE'
                 and fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                 and fcbs.taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
                then 'NET_DEDUCT'
                else 'NONE'
              end,
              'finance_component_id', null,
              'frozen_component_key_type', 'CASE_TOTAL',
              'frozen_component_key_value', 'TOTAL',
              'frozen_component_classification', null,
              'frozen_component_snapshot_json', null,
              'frozen_source_basis_json', jsonb_strip_nulls(
                jsonb_build_object(
                  'case_type', fcrrb.case_type::text,
                  'recovery_family', case
                    when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                    when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                    when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                    else fcrrb.case_type::text
                  end,
                  'pay_channel', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
                  'taxability', case when fcbs.taxability is null then null else fcbs.taxability::text end,
                  'routing_kind', case when fcbs.routing_kind is null then null else fcbs.routing_kind::text end,
                  'nominal_due_amount_ex_vat', round(coalesce(fcrrb.nominal_due_amount, 0), 2),
                  'current_due_amount_ex_vat', round(coalesce(fcrr.due_amount_ex_vat, 0), 2),
                  'outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
                  'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
                  'active_reserved_amount', round(coalesce(fcbs.active_reserved_amount, 0), 2),
                  'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
                  'take_home_floor_override', fcrrb.take_home_floor_override,
                  'default_take_home_floor', fcrrb.default_take_home_floor,
                  'run_earnings_headroom_ex', round(coalesce(fcrrb.run_earnings_headroom_ex, 0), 2),
                  'run_take_home_before', round(coalesce(fcrrb.run_take_home_before, 0), 2),
                  'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
                  'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
                  'sort_order', row_number() over (
                    partition by fcrrb.candidate_id,
                                 case
                                   when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                                   when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                                   when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                                   else fcrrb.case_type::text
                                 end
                    order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
                  )
                )
              ),
              'frozen_source_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_target_pay_method', upper(coalesce(fcrrb.candidate_pay_method, '')),
              'frozen_source_amount', round(coalesce(fcbs.outstanding_amount, fcrrb.nominal_due_amount, 0), 2),
              'frozen_outstanding_amount', round(coalesce(fcbs.outstanding_amount, 0), 2),
              'weekly_due', round(coalesce(fcbs.weekly_due, 0), 2),
              'minimum_earnings_threshold', fcrrb.minimum_earnings_threshold,
              'take_home_floor_override', fcrrb.take_home_floor_override,
              'default_take_home_floor', fcrrb.default_take_home_floor,
              'payout_status', case when fcrrb.payout_status is null then null else fcrrb.payout_status::text end,
              'next_due_week_start', case when fcbs.next_due_week_start is null then null else fcbs.next_due_week_start::text end,
              'sort_order', row_number() over (
                partition by fcrrb.candidate_id,
                             case
                               when fcrrb.case_type = 'PAYMENT_ADVANCE' then 'LOAN_REPAYMENT'
                               when fcrrb.case_type = 'OVERPAYMENT' then 'OVERPAYMENT_RECOVERY'
                               when fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                               else fcrrb.case_type::text
                             end
                order by coalesce(fcbs.created_at, fcrrb.created_at), fcrrb.finance_case_id
              ),
              'frozen_resolution_mode', coalesce(
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.taxable_manual_debt_resolution_json->>'mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'resolution_mode', '')), ''),
                nullif(btrim(coalesce(fcrr.case_resolution_summary_json->'non_bucket_resolution'->>'mode', '')), '')
              ),
              'frozen_resolution_payload_json', case
                when fcrr.taxable_manual_debt_resolution_json is not null then fcrr.taxable_manual_debt_resolution_json
                when jsonb_typeof(fcrr.case_resolution_summary_json->'non_bucket_resolution') = 'object' then fcrr.case_resolution_summary_json->'non_bucket_resolution'
                else null
              end,
              'frozen_resolution_result_json', fcrr.case_resolution_summary_json,
              'case_components_json', coalesce(fcrr.case_components_json, '[]'::jsonb),
              'case_resolution_summary_json', coalesce(fcrr.case_resolution_summary_json, '{}'::jsonb),
              'taxable_manual_debt_resolution_json', fcrr.taxable_manual_debt_resolution_json,
              'eligibility_state', jsonb_build_object(
                'candidate_ready_for_draft', coalesce(fcrr.candidate_ready_for_draft, false),
                'case_is_blocked', coalesce(fcrr.is_blocked, false),
                'has_active_dated_snooze', (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
              )
            )
          ) as template_json
        from finance_case_recovery_rows_base fcrrb
        join finance_case_baseline_scope fcbs
          on fcbs.finance_case_id = fcrrb.finance_case_id
        join finance_case_resolution_rollup fcrr
          on fcrr.finance_case_id = fcrrb.finance_case_id
        left join public.candidates c
          on c.id = fcrrb.candidate_id
        where fcrrb.case_type in (
            'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
          and round(coalesce(fcrrb.nominal_due_amount, 0), 2) > 0
          and round(coalesce(fcrr.due_amount_ex_vat, 0), 2) = 0
          and coalesce(fcrr.candidate_ready_for_draft, false) = true
          and coalesce(fcrr.is_blocked, false) = false
          and not (fcrr.active_snooze_id is not null and fcrr.active_snooze_until_date is not null)
          and (
            fcrrb.case_type <> 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
            or upper(coalesce(fcrr.lifecycle_status_display, '')) = 'PAID'
          )
  ;



  CREATE TEMPORARY TABLE IF NOT EXISTS manual_adjustment_carry_forward_scope (
    id uuid,
    source_pay_batch_id uuid,
    source_pay_batch_item_id uuid,
    source_pay_bank_transfer_id uuid,
    source_pay_batch_candidate_id uuid,
    source_correction_request_id uuid,
    source_correction_work_item_id uuid,
    candidate_id uuid,
    umbrella_id uuid,
    client_id uuid,
    timesheet_id uuid,
    pay_channel text,
    adjustment_direction text,
    amount_ex_vat numeric,
    amount_vat numeric,
    amount_inc_vat numeric,
    amount_basis text,
    paye_treatment text,
    tax_treatment_json jsonb,
    description text,
    reason text,
    source_ref text,
    source_operation_source_key text,
    source_snapshot_json jsonb,
    status text,
    target_pay_batch_id uuid,
    target_pay_batch_item_id uuid,
    target_operation_source_key text,
    created_at_utc timestamptz,
    updated_at_utc timestamptz,
    reserved_at_utc timestamptz,
    consumed_at_utc timestamptz,
    released_at_utc timestamptz,
    cancelled_at_utc timestamptz,
    status_reason text,
    source_batch_ref text
  ) ON COMMIT DROP;

  create temporary table manual_adjustment_carry_forward_lines on commit drop as
        select
          carry_forward_scope.candidate_id,
          cp.cand_tms_ref,
          cp.cand_display_name,
          cp.payee_entity_kind,
          cp.payee_entity_id,
          carry_forward_scope.id as manual_adjustment_carry_forward_id,
          carry_forward_scope.source_pay_batch_id,
          carry_forward_scope.source_pay_batch_item_id,
          carry_forward_scope.source_pay_bank_transfer_id,
          carry_forward_scope.source_pay_batch_candidate_id,
          carry_forward_scope.source_correction_request_id,
          carry_forward_scope.source_correction_work_item_id,
          carry_forward_scope.umbrella_id,
          carry_forward_scope.client_id,
          carry_forward_scope.timesheet_id,
          upper(btrim(coalesce(carry_forward_scope.pay_channel, ''))) as pay_channel,
          carry_forward_scope.adjustment_direction,
          round(coalesce(carry_forward_scope.amount_ex_vat, 0), 2)::numeric as amount_ex_vat,
          round(coalesce(carry_forward_scope.amount_vat, 0), 2)::numeric as amount_vat,
          round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2)::numeric as amount_inc_vat,
          carry_forward_scope.amount_basis,
          carry_forward_scope.paye_treatment,
          coalesce(carry_forward_scope.tax_treatment_json, '{}'::jsonb) as tax_treatment_json,
          nullif(btrim(coalesce(carry_forward_scope.description, '')), '') as original_description,
          carry_forward_scope.reason,
          carry_forward_scope.source_ref,
          carry_forward_scope.source_operation_source_key,
          coalesce(carry_forward_scope.source_snapshot_json, '{}'::jsonb) as source_snapshot_json,
          carry_forward_scope.status,
          carry_forward_scope.target_pay_batch_id,
          carry_forward_scope.target_pay_batch_item_id,
          carry_forward_scope.target_operation_source_key,
          coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text) as source_batch_ref,
          ('carry_forward:' || carry_forward_scope.id::text) as preview_row_id,
          ('carry_forward:' || carry_forward_scope.id::text) as operation_source_key,
          ('Carried forward from cancelled payment '
            || coalesce(nullif(btrim(carry_forward_scope.source_batch_ref), ''), carry_forward_scope.source_pay_batch_id::text)
            || ': '
            || coalesce(nullif(btrim(carry_forward_scope.description), ''), nullif(btrim(carry_forward_scope.reason), ''), 'Manual adjustment')
          ) as display_description
        from manual_adjustment_carry_forward_scope as carry_forward_scope
        join cand_payee cp
          on cp.candidate_id = carry_forward_scope.candidate_id
        where carry_forward_scope.candidate_id = p_candidate_id
          and upper(btrim(coalesce(carry_forward_scope.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and round(coalesce(carry_forward_scope.amount_inc_vat, 0), 2) <> 0
  ;

  create temporary table timesheet_canonical_preview_lines on commit drop as
        select
          ctpr.candidate_id,
          (
            ctpr.line_json
            || jsonb_build_object(
              'preview_row_id', coalesce(nullif(btrim(coalesce(ctpr.line_json->>'line_id','')), ''), md5(ctpr.line_json::text)),
              'readiness_state', case
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'CASES_RESOLUTIONS'
                then 'CASES_RESOLUTIONS'
                when upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
                  or coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = false
                then 'BLOCKED_FOR_PAY'
                else 'READY_TO_PAY'
              end,
              'draftable', (
                upper(coalesce(ctpr.line_json->>'presentation_section','')) = 'READY_TO_PAY'
                and coalesce(nullif(ctpr.line_json->>'is_excluded_from_allocation','')::boolean, false) = false
                and coalesce(nullif(ctpr.line_json->>'is_ready_for_draft','')::boolean, false) = true
              )
            )
          ) as line_json,
          ctpr.pay_channel,
          ctpr.paye_treatment,
          ctpr.amount_ex_vat,
          ctpr.is_excluded_from_allocation
        from canonical_timesheet_presentation_rows ctpr

  ;

  create temporary table canonical_preview_lines on commit drop as
        select
          tcpl.candidate_id,
          tcpl.line_json,
          tcpl.pay_channel,
          tcpl.paye_treatment,
          tcpl.amount_ex_vat,
          tcpl.is_excluded_from_allocation
        from timesheet_canonical_preview_lines tcpl

        union all

        select
          fcl.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'candidate_id', fcl.candidate_id::text,
              'tms_ref', fcl.cand_tms_ref,
              'display_name', fcl.cand_display_name,
              'line_type', fcl.line_type,
              'item_type_label', fcl.item_type_label,
              'item_direction', fcl.item_direction,
              'finance_case_id', fcl.finance_case_id::text,
              'case_key', ('finance:' || fcl.finance_case_id::text),
              'case_type', fcl.case_type::text,
              'case_is_blocked', fcl.case_is_blocked
            )
            || jsonb_build_object(
              'case_resolution_summary', fcl.case_resolution_summary_json,
              'case_components', fcl.case_components_json,
              'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
              'client_id', case when fcl.client_id is null then null else fcl.client_id::text end,
              'client_name', fcl.client_name,
              'week_ending_date', null,
              'linked_shift_date', case when fcl.linked_shift_date is null then null else fcl.linked_shift_date::text end,
              'pay_channel', fcl.candidate_pay_method,
              'paye_treatment', fcl.paye_treatment,
              'route_type', case when fcl.routing_kind is null then 'NORMAL_PAYMENT' else fcl.routing_kind::text end,
              'routing_kind', case when fcl.routing_kind is null then null else fcl.routing_kind::text end,
              'destination_label', fcl.destination_label,
              'taxability', case when fcl.taxability is null then null else fcl.taxability::text end
            )
            || jsonb_strip_nulls(
              jsonb_build_object(
                'taxable_manual_debt_resolution', fcl.taxable_manual_debt_resolution_json
              )
            )
            || jsonb_build_object(
              'beneficiary_name', fcl.beneficiary_name,
              'masked_bank_account', fcl.masked_bank_account,
              'bank_details_hash', fcl.payee_bank_hash,
              'blocked_reason_codes', fcl.blocked_reason_codes,
              'readiness_state', fcl.readiness_state,
              'draftable', fcl.draftable,
              'snooze_allowed', fcl.snooze_allowed,
              'oneoff_bank_details_present', fcl.oneoff_bank_details_present,
              'is_candidate_directed_oneoff_payout', fcl.is_candidate_directed_oneoff_payout,
              'appears_on_umbrella_remittance', fcl.appears_on_umbrella_remittance,
              'generates_candidate_payment_advice', fcl.generates_candidate_payment_advice,
              'adjustment_comment', fcl.adjustment_comment,
              'amount_ex_vat', fcl.signed_amount_ex_vat,
              'amount_display', fcl.signed_amount_ex_vat,
              'is_advanced', false,
              'advanced_override_id', null,
              'advanced_reason', null
            )
            || jsonb_build_object(
              'is_excluded_from_allocation', (fcl.active_snooze_id is not null and fcl.active_snooze_until_date is not null),
              'is_ready_for_draft', fcl.draftable,
              'presentation_section', case
                when fcl.active_snooze_id is not null and fcl.active_snooze_until_date is not null then 'BLOCKED_FOR_PAY'
                when fcl.case_is_blocked then 'BLOCKED_FOR_PAY'
                else 'READY_TO_PAY'
              end,
              'presentation_role', 'PARENT',
              'presentation_line_id', ('finance:' || fcl.finance_case_id::text || ':' || lower(fcl.line_type)),
              'presentation_parent_line_id', ('finance:' || fcl.finance_case_id::text),
              'presentation_reason', case
                when fcl.active_snooze_id is not null and fcl.active_snooze_until_date is not null then 'DATED_SNOOZE'
                when fcl.case_is_blocked then 'CASE_BLOCKED'
                else 'READY_TO_PAY'
              end,
              'source_ref', ('advance:' || fcl.finance_case_id::text),
              'snooze_kind', case
                when fcl.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(fcl.lifecycle_status_display,'')) = 'PAID' then 'PAYMENT_ADVANCE_REPAYMENT'
                when fcl.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_RECOVERY'
                else ''
              end
            )
            || jsonb_build_object(
              'snooze_identity', jsonb_build_object(
                'identity_type', 'FINANCE_CASE',
                'timesheet_id', null,
                'booking_id', null,
                'segment_id', null,
                'segment_stable_key', null,
                'source_ref', ('advance:' || fcl.finance_case_id::text)
              ),
              'snooze_state', case
                when fcl.active_snooze_id is null then jsonb_build_object('state','NONE')
                when fcl.active_snooze_until_date is null then jsonb_build_object(
                  'state', 'INDEFINITE_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', null,
                  'note', fcl.active_snooze_note
                )
                else jsonb_build_object(
                  'state', 'DATED_SNOOZED',
                  'snooze_id', fcl.active_snooze_id::text,
                  'snooze_until_date', fcl.active_snooze_until_date::text,
                  'note', fcl.active_snooze_note
                )
              end
            )
          ) as line_json,
          fcl.candidate_pay_method as pay_channel,
          fcl.paye_treatment,
          fcl.signed_amount_ex_vat as amount_ex_vat,
          (fcl.active_snooze_id is not null and fcl.active_snooze_until_date is not null) as is_excluded_from_allocation
        from finance_case_lines fcl

        union all

        select
          cf_lines.candidate_id,
          (
            jsonb_build_object(
              'preview_row_id', cf_lines.preview_row_id,
              'line_id', cf_lines.preview_row_id,
              'candidate_id', cf_lines.candidate_id::text,
              'tms_ref', cf_lines.cand_tms_ref,
              'display_name', cf_lines.cand_display_name,
              'payee_entity_kind', cf_lines.payee_entity_kind,
              'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
              'payee_context', jsonb_build_object(
                'payee_entity_kind', cf_lines.payee_entity_kind,
                'payee_entity_id', CASE WHEN cf_lines.payee_entity_id IS NULL THEN NULL ELSE cf_lines.payee_entity_id::text END,
                'pay_channel', cf_lines.pay_channel,
                'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END
              ),
              'line_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_key', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'case_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'case_is_blocked', false,
              'case_resolution_summary', '{}'::jsonb,
              'case_components', '[]'::jsonb,
              'item_type_label', 'Manual adjustment carry-forward',
              'item_direction', CASE WHEN coalesce(cf_lines.amount_inc_vat, 0) < 0 THEN 'DEBIT' ELSE 'CREDIT' END,
              'manual_adjustment_carry_forward_id', cf_lines.manual_adjustment_carry_forward_id::text,
              'source_ref', ('carry_forward:' || cf_lines.manual_adjustment_carry_forward_id::text),
              'operation_source_key', cf_lines.operation_source_key,
              'source_operation_source_key', cf_lines.source_operation_source_key,
              'description', cf_lines.display_description,
              'adjustment_comment', cf_lines.display_description,
              'original_description', cf_lines.original_description,
              'reason', cf_lines.reason,
              'source_pay_batch_id', CASE WHEN cf_lines.source_pay_batch_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_id::text END,
              'source_pay_batch_item_id', CASE WHEN cf_lines.source_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_item_id::text END,
              'source_pay_bank_transfer_id', CASE WHEN cf_lines.source_pay_bank_transfer_id IS NULL THEN NULL ELSE cf_lines.source_pay_bank_transfer_id::text END,
              'source_pay_batch_candidate_id', CASE WHEN cf_lines.source_pay_batch_candidate_id IS NULL THEN NULL ELSE cf_lines.source_pay_batch_candidate_id::text END,
              'source_correction_request_id', CASE WHEN cf_lines.source_correction_request_id IS NULL THEN NULL ELSE cf_lines.source_correction_request_id::text END,
              'source_correction_work_item_id', CASE WHEN cf_lines.source_correction_work_item_id IS NULL THEN NULL ELSE cf_lines.source_correction_work_item_id::text END,
              'source_batch_ref', cf_lines.source_batch_ref,
              'umbrella_id', CASE WHEN cf_lines.umbrella_id IS NULL THEN NULL ELSE cf_lines.umbrella_id::text END,
              'client_id', CASE WHEN cf_lines.client_id IS NULL THEN NULL ELSE cf_lines.client_id::text END,
              'timesheet_id', CASE WHEN cf_lines.timesheet_id IS NULL THEN NULL ELSE cf_lines.timesheet_id::text END,
              'pay_channel', cf_lines.pay_channel,
              'candidate_pay_method', cf_lines.pay_channel,
              'paye_treatment', cf_lines.paye_treatment,
              'tax_treatment_json', cf_lines.tax_treatment_json,
              'taxability', cf_lines.tax_treatment_json->>'taxability',
              'amount_basis', cf_lines.amount_basis,
              'adjustment_direction', cf_lines.adjustment_direction,
              'amount_ex_vat', cf_lines.amount_ex_vat,
              'amount_vat', cf_lines.amount_vat,
              'amount_inc_vat', cf_lines.amount_inc_vat,
              'amount_display', cf_lines.amount_inc_vat,
              'payment_amount_ex_vat', cf_lines.amount_ex_vat,
              'payment_amount_vat', cf_lines.amount_vat,
              'payment_amount_inc_vat', cf_lines.amount_inc_vat,
              'payment_amount', cf_lines.amount_inc_vat,
              'source_snapshot_json', cf_lines.source_snapshot_json,
              'manual_adjustment_carry_forward_status', cf_lines.status,
              'target_pay_batch_id', CASE WHEN cf_lines.target_pay_batch_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_id::text END,
              'target_pay_batch_item_id', CASE WHEN cf_lines.target_pay_batch_item_id IS NULL THEN NULL ELSE cf_lines.target_pay_batch_item_id::text END,
              'target_operation_source_key', cf_lines.target_operation_source_key,
              'readiness_state', 'READY_TO_PAY',
              'draftable', true,
              'is_ready_for_draft', true,
              'is_excluded_from_allocation', false,
              'presentation_section', 'READY_TO_PAY',
              'presentation_role', 'PARENT',
              'presentation_line_id', cf_lines.preview_row_id,
              'presentation_parent_line_id', cf_lines.preview_row_id,
              'presentation_reason', 'READY_TO_PAY',
              'route_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'routing_kind', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
              'appears_on_umbrella_remittance', (cf_lines.pay_channel = 'UMBRELLA'),
              'generates_candidate_payment_advice', true
            )
          ) as line_json,
          cf_lines.pay_channel,
          cf_lines.paye_treatment,
          cf_lines.amount_ex_vat,
          false as is_excluded_from_allocation
        from manual_adjustment_carry_forward_lines cf_lines
  
  ;

  create temporary table candidate_preview_line_rollup on commit drop as
        select
          cpl.candidate_id,
          count(*) filter (
            where coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          )::int as ready_preview_line_count,
          count(*) filter (
            where upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY'
          )::int as blocked_preview_line_count,
          bool_or(
            coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true
          ) as has_ready_preview_line
        from canonical_preview_lines cpl
        group by cpl.candidate_id
  
  ;

  create temporary table candidate_preview_timesheet_rollup on commit drop as
        select
          ctpp.candidate_id,
          round(
            coalesce(sum(case when ctpp.has_active_timesheet_snooze = false and ctpp.case_is_blocked = false and ctpp.has_ready_presentation = true and ctpp.is_ready_for_draft = true then ctpp.ready_section_amount_ex_vat else 0 end), 0),
            2
          ) as ready_timesheet_total_ex_vat,
          count(*) filter (
            where ctpp.has_blocked_presentation = true
          )::int as blocked_timesheet_preview_count,
          count(*) filter (
            where ctpp.has_active_timesheet_snooze = false
              and ctpp.case_is_blocked = false
              and ctpp.has_ready_presentation = true
              and ctpp.is_ready_for_draft = true
          )::int as ready_timesheet_preview_count,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'timesheet_id', ctpp.timesheet_id::text,
                'week_ending_date', case when ctpp.week_ending_date is null then null else ctpp.week_ending_date::text end,
                'client_id', case when ctpp.client_id is null then null else ctpp.client_id::text end,
                'client_name', ctpp.client_name,
                'payment_amount_ex_vat', ctpp.ready_section_amount_ex_vat,
                'payment_amount_inc_vat', ctpp.ready_section_amount_display,
                'payment_amount', ctpp.ready_section_amount_display,
                'source_pay_method', ctpp.source_pay_method,
                'candidate_pay_method', ctpp.candidate_pay_method,
                'segment_deltas', (
                  select coalesce(
                    jsonb_agg(
                      jsonb_build_object(
                        'segment_id', rs->>'segment_id',
                        'segment_key', rs->>'segment_key',
                        'segment_stable_key', rs->>'segment_stable_key',
                        'work_date', rs->>'date',
                        'ref_num', rs->>'ref_num',
                        'delta_pay_ex_vat', round(coalesce(nullif(rs->>'pay_amount_ex_vat','')::numeric, 0), 2),
                        'raw_delta_ex_vat', round(coalesce(nullif(rs->>'raw_delta_ex_vat','')::numeric, 0), 2),
                        'effective_delta_ex_vat', round(coalesce(nullif(rs->>'effective_delta_ex_vat','')::numeric, 0), 2)
                      )
                      order by
                        nullif(btrim(coalesce(rs->>'date','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'start','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_stable_key','')), '') nulls last,
                        nullif(btrim(coalesce(rs->>'segment_id','')), '') nulls last
                    ),
                    '[]'::jsonb
                  )
                  from jsonb_array_elements(coalesce(ctpp.ready_segment_rows_json, '[]'::jsonb)) rs
                ),
                'adjustment_deltas', coalesce(tcr.adjustment_deltas_json, '[]'::jsonb),
                'delta_additional_pay_ex_vat', coalesce(tcr.delta_additional_pay_ex_vat, 0),
                'additional_unit_deltas', coalesce(tcr.additional_unit_deltas_json, '[]'::jsonb),
                'reservation_overrun_detected', coalesce(tcr.reservation_overrun_detected, false),
                'delta_expenses_pay_ex_vat', coalesce(tcr.delta_expenses_pay_ex_vat, 0),
                'delta_travel_pay_ex_vat', coalesce(tcr.delta_travel_pay_ex_vat, 0),
                'delta_accommodation_pay_ex_vat', coalesce(tcr.delta_accommodation_pay_ex_vat, 0),
                'delta_other_pay_ex_vat', coalesce(tcr.delta_other_pay_ex_vat, 0),
                'delta_mileage_pay_ex_vat', coalesce(tcr.delta_mileage_pay_ex_vat, 0),
                'case_key', ('timesheet:' || ctpp.timesheet_id::text),
                'case_resolution_summary', coalesce(ctpp.case_resolution_summary_json, '{}'::jsonb),
                'components', coalesce(ctpp.case_components_json, '[]'::jsonb),
                'presentation_section', 'READY_TO_PAY',
                'presentation_role', 'PARENT',
                'total_segment_count', ctpp.total_segment_count,
                'ready_segment_count', ctpp.ready_segment_count,
                'blocked_visible_segment_count', ctpp.blocked_visible_segment_count,
                'hidden_indefinite_segment_count', ctpp.hidden_indefinite_segment_count,
                'is_partially_ready', ctpp.is_partially_ready,
                'is_partially_blocked', ctpp.is_partially_blocked
              )
              order by ctpp.week_ending_date, ctpp.client_name, ctpp.timesheet_id
            ) filter (where ctpp.has_active_timesheet_snooze = false and ctpp.case_is_blocked = false and ctpp.has_ready_presentation = true and ctpp.is_ready_for_draft = true and round(coalesce(ctpp.ready_section_amount_ex_vat,0),2) <> 0),
            '[]'::jsonb
          ) as ready_timesheets_itemisation
        from canonical_timesheet_presentation_state ctpp
        left join timesheet_case_rollup_effective tcr
          on tcr.timesheet_id = ctpp.timesheet_id
         and tcr.candidate_id = ctpp.candidate_id
        group by ctpp.candidate_id
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'canonical_preview_line_count', (select count(*)::int from canonical_preview_lines),
    'ready_preview_line_count', coalesce((select sum(case when coalesce(nullif(cpl.line_json->>'draftable','')::boolean, false) = true then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'blocked_preview_line_count', coalesce((select sum(case when upper(coalesce(cpl.line_json->>'presentation_section','')) = 'BLOCKED_FOR_PAY' then 1 else 0 end)::int from canonical_preview_lines cpl), 0),
    'hidden_recovery_template_line_count', (select count(*)::int from hidden_recovery_template_lines),
    'manual_adjustment_carry_forward_line_count', (select count(*)::int from manual_adjustment_carry_forward_lines),
    'hidden_recovery_template_lines', coalesce(
      (
        select jsonb_agg(
                 hrtl.template_json
                 order by hrtl.candidate_id, hrtl.recovery_family, hrtl.sort_order, hrtl.finance_case_id
               )
        from hidden_recovery_template_lines hrtl
      ),
      '[]'::jsonb
    )
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_case_component_rows(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.ts_itemised') is null then
    perform public.pay_preview_candidate_build_entitlement_rows(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.worked_time_current_segment_rows, pg_temp.worked_time_baseline_segment_rows, pg_temp.worked_time_current_ranked, pg_temp.worked_time_baseline_ranked, pg_temp.worked_time_bucket_ids, pg_temp.worked_time_bucket_agg, pg_temp.worked_time_bucket_calc, pg_temp.worked_time_bucket_alloc, pg_temp.worked_time_bucket_effective, pg_temp.worked_time_bucket_component_rows, pg_temp.worked_time_key_totals, pg_temp.worked_time_bucket_component_sums, pg_temp.worked_time_amount_fallback_rows, pg_temp.timesheet_component_rows, pg_temp.timesheet_component_match_rows, pg_temp.transient_timesheet_component_rows, pg_temp.transient_timesheet_component_review_rows, pg_temp.timesheet_case_actionable_basis, pg_temp.timesheet_live_scope, pg_temp.timesheet_linked_scope_counts, pg_temp.transient_timesheet_component_review_rows_effective, pg_temp.timesheet_case_rollup;

  create temporary table worked_time_current_segment_rows on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          cur_seg.seg_ord as segment_sort_ord,
          nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), '') as segment_id,
          nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), '') as segment_key,
          coalesce(
            nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'date','')), ''),
            nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '')
          ) as segment_stable_key,
          nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') as work_date,
          nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')), '') as ref_num,
          case
            when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null
              then nullif(btrim(coalesce(cur_seg.seg->>'date','')), '')
            else 'TOTAL'
          end as component_key_value,
          bucket.bucket_code,
          bucket.bucket_sort_ord,
          round(bucket.source_units, 6) as source_units,
          case bucket.bucket_code
            when 'DAY' then b.cur_pay_day
            when 'NIGHT' then b.cur_pay_night
            when 'SAT' then b.cur_pay_sat
            when 'SUN' then b.cur_pay_sun
            when 'BH' then b.cur_pay_bh
            else null::numeric
          end as source_rate,
          case bucket.bucket_code
            when 'DAY' then b.cur_charge_day
            when 'NIGHT' then b.cur_charge_night
            when 'SAT' then b.cur_charge_sat
            when 'SUN' then b.cur_charge_sun
            when 'BH' then b.cur_charge_bh
            else null::numeric
          end as source_charge_rate
        from ts_baseline b
        join lateral jsonb_array_elements(coalesce(b.current_segments_json, '[]'::jsonb)) with ordinality as cur_seg(seg, seg_ord) on true
        join lateral (
          values
            ('DAY'::text, 1::int, coalesce(nullif(cur_seg.seg->>'hours_day','')::numeric, 0)),
            ('NIGHT'::text, 2::int, coalesce(nullif(cur_seg.seg->>'hours_night','')::numeric, 0)),
            ('SAT'::text, 3::int, coalesce(nullif(cur_seg.seg->>'hours_sat','')::numeric, 0)),
            ('SUN'::text, 4::int, coalesce(nullif(cur_seg.seg->>'hours_sun','')::numeric, 0)),
            ('BH'::text, 5::int, coalesce(nullif(cur_seg.seg->>'hours_bh','')::numeric, 0))
        ) as bucket(bucket_code, bucket_sort_ord, source_units) on true
        where cur_seg.seg is not null
          and jsonb_typeof(cur_seg.seg) = 'object'
          and coalesce(bucket.source_units, 0) <> 0
  
  ;

  create temporary table worked_time_baseline_segment_rows on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          bas_seg.seg_ord as segment_sort_ord,
          nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')), '') as segment_id,
          nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')), '') as segment_key,
          coalesce(
            nullif(btrim(coalesce(bas_seg.seg->>'segment_stable_key','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'date','')), ''),
            nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')), '')
          ) as segment_stable_key,
          nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') as work_date,
          nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')), '') as ref_num,
          case
            when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null
              then nullif(btrim(coalesce(bas_seg.seg->>'date','')), '')
            else 'TOTAL'
          end as component_key_value,
          bucket.bucket_code,
          bucket.bucket_sort_ord,
          round(bucket.source_units, 6) as source_units,
          case bucket.bucket_code
            when 'DAY' then b.bas_pay_day
            when 'NIGHT' then b.bas_pay_night
            when 'SAT' then b.bas_pay_sat
            when 'SUN' then b.bas_pay_sun
            when 'BH' then b.bas_pay_bh
            else null::numeric
          end as source_rate,
          case bucket.bucket_code
            when 'DAY' then b.bas_charge_day
            when 'NIGHT' then b.bas_charge_night
            when 'SAT' then b.bas_charge_sat
            when 'SUN' then b.bas_charge_sun
            when 'BH' then b.bas_charge_bh
            else null::numeric
          end as source_charge_rate
        from ts_baseline b
        join lateral jsonb_array_elements(
          case
            when jsonb_typeof(b.base_json->'segments') = 'array'
             and jsonb_array_length(coalesce(b.base_json->'segments', '[]'::jsonb)) > 0
              then coalesce(b.base_json->'segments', '[]'::jsonb)
            else jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || b.timesheet_id::text),
                'segment_key', ('ts:' || b.timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(b.ts_booking_id, b.timesheet_id::text)),
                'date', null,
                'ref_num', null,
                'hours_day', b.bas_hours_day,
                'hours_night', b.bas_hours_night,
                'hours_sat', b.bas_hours_sat,
                'hours_sun', b.bas_hours_sun,
                'hours_bh', b.bas_hours_bh
              )
            )
          end
        ) with ordinality as bas_seg(seg, seg_ord) on true
        join lateral (
          values
            ('DAY'::text, 1::int, coalesce(nullif(bas_seg.seg->>'hours_day','')::numeric, 0)),
            ('NIGHT'::text, 2::int, coalesce(nullif(bas_seg.seg->>'hours_night','')::numeric, 0)),
            ('SAT'::text, 3::int, coalesce(nullif(bas_seg.seg->>'hours_sat','')::numeric, 0)),
            ('SUN'::text, 4::int, coalesce(nullif(bas_seg.seg->>'hours_sun','')::numeric, 0)),
            ('BH'::text, 5::int, coalesce(nullif(bas_seg.seg->>'hours_bh','')::numeric, 0))
        ) as bucket(bucket_code, bucket_sort_ord, source_units) on true
        where bas_seg.seg is not null
          and jsonb_typeof(bas_seg.seg) = 'object'
          and coalesce(bucket.source_units, 0) <> 0
  
  ;

  create temporary table worked_time_current_ranked on commit drop as
        select
          wcsr.*,
          row_number() over (
            partition by wcsr.timesheet_id, wcsr.candidate_id, wcsr.component_key_type, wcsr.component_key_value, wcsr.bucket_code
            order by wcsr.segment_sort_ord nulls last, wcsr.segment_id nulls last, wcsr.ref_num nulls last
          ) as bucket_row_ord
        from worked_time_current_segment_rows wcsr
  
  ;

  create temporary table worked_time_baseline_ranked on commit drop as
        select
          wbsr.*,
          row_number() over (
            partition by wbsr.timesheet_id, wbsr.candidate_id, wbsr.component_key_type, wbsr.component_key_value, wbsr.bucket_code
            order by wbsr.segment_sort_ord nulls last, wbsr.segment_id nulls last, wbsr.ref_num nulls last
          ) as bucket_row_ord
        from worked_time_baseline_segment_rows wbsr
  
  ;

  create temporary table worked_time_bucket_ids on commit drop as
        select distinct
          wcr.timesheet_id,
          wcr.candidate_id,
          wcr.component_key_type,
          wcr.component_key_value,
          wcr.bucket_code,
          wcr.bucket_sort_ord,
          wcr.bucket_row_ord
        from worked_time_current_ranked wcr
        union
        select distinct
          wbr.timesheet_id,
          wbr.candidate_id,
          wbr.component_key_type,
          wbr.component_key_value,
          wbr.bucket_code,
          wbr.bucket_sort_ord,
          wbr.bucket_row_ord
        from worked_time_baseline_ranked wbr
  
  ;

  create temporary table worked_time_bucket_agg on commit drop as
        select
          wbi.timesheet_id,
          wbi.candidate_id,
          wbi.component_key_type,
          wbi.component_key_value,
          wbi.bucket_code,
          max(wbi.bucket_sort_ord) as bucket_sort_ord,
          wbi.bucket_row_ord,
          max(wcr.segment_id) as cur_segment_id,
          max(wbr.segment_id) as bas_segment_id,
          max(coalesce(wcr.segment_key, wbr.segment_key)) as segment_key,
          max(coalesce(wcr.segment_stable_key, wbr.segment_stable_key)) as segment_stable_key,
          max(coalesce(wcr.ref_num, wbr.ref_num)) as ref_num,
          max(coalesce(wcr.work_date, wbr.work_date)) as work_date,
          max(wcr.segment_sort_ord) as cur_segment_sort_ord,
          max(wbr.segment_sort_ord) as bas_segment_sort_ord,
          max(wcr.source_rate) as cur_source_rate,
          max(wcr.source_charge_rate) as cur_source_charge_rate,
          round(sum(case when wcr.bucket_row_ord = wbi.bucket_row_ord then coalesce(wcr.source_units,0) else 0 end), 6) as cur_source_units,
          round(sum(case when wbr.bucket_row_ord = wbi.bucket_row_ord then coalesce(wbr.source_units,0) else 0 end), 6) as bas_source_units,
          round(sum(
            case
              when wcr.bucket_row_ord = wbi.bucket_row_ord and wcr.source_rate is not null
                then coalesce(wcr.source_units,0) * wcr.source_rate
              else 0
            end
          ), 2) as cur_pay_amount_ex_vat,
          round(sum(
            case
              when wbr.bucket_row_ord = wbi.bucket_row_ord and wbr.source_rate is not null
                then coalesce(wbr.source_units,0) * wbr.source_rate
              else 0
            end
          ), 2) as bas_pay_amount_ex_vat,
          round(sum(
            case
              when wcr.bucket_row_ord = wbi.bucket_row_ord and wcr.source_charge_rate is not null
                then coalesce(wcr.source_units,0) * wcr.source_charge_rate
              else 0
            end
          ), 2) as cur_charge_amount_ex_vat,
          round(sum(
            case
              when wbr.bucket_row_ord = wbi.bucket_row_ord and wbr.source_charge_rate is not null
                then coalesce(wbr.source_units,0) * wbr.source_charge_rate
              else 0
            end
          ), 2) as bas_charge_amount_ex_vat
        from worked_time_bucket_ids wbi
        left join worked_time_current_ranked wcr
          on wcr.timesheet_id = wbi.timesheet_id
         and wcr.candidate_id = wbi.candidate_id
         and wcr.component_key_type = wbi.component_key_type
         and wcr.component_key_value = wbi.component_key_value
         and wcr.bucket_code = wbi.bucket_code
         and wcr.bucket_row_ord = wbi.bucket_row_ord
        left join worked_time_baseline_ranked wbr
          on wbr.timesheet_id = wbi.timesheet_id
         and wbr.candidate_id = wbi.candidate_id
         and wbr.component_key_type = wbi.component_key_type
         and wbr.component_key_value = wbi.component_key_value
         and wbr.bucket_code = wbi.bucket_code
         and wbr.bucket_row_ord = wbi.bucket_row_ord
        group by
          wbi.timesheet_id,
          wbi.candidate_id,
          wbi.component_key_type,
          wbi.component_key_value,
          wbi.bucket_code,
          wbi.bucket_row_ord
  
  ;

  create temporary table worked_time_bucket_calc on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,
          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,
          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,
          b.umb_enabled,
          b.umb_vat_chargeable,
          b.cand_bank_hash,
          b.umb_bank_hash,
          b.ts_booking_id as booking_id,
          coalesce(wba.cur_segment_id, wba.bas_segment_id) as segment_id,
          coalesce(wba.segment_key, coalesce(wba.cur_segment_id, wba.bas_segment_id)) as segment_key,
          wba.segment_stable_key,
          wba.component_key_type,
          wba.component_key_value,
          wba.bucket_code,
          wba.bucket_sort_ord,
          wba.bucket_row_ord,
          coalesce(wba.cur_segment_sort_ord, wba.bas_segment_sort_ord) as segment_sort_ord,
          wba.work_date,
          wba.ref_num,
          wba.cur_source_rate as source_rate,
          wba.cur_source_charge_rate as source_charge_rate,
          round(coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0), 6) as raw_delta_source_units,
          coalesce(b.has_active_overpayment_case,false) as has_active_overpayment_case,
          b.require_reference_to_pay,
          coalesce(b.is_forced_advance,false) as is_forced_advance,
          round(
            case
              when wba.cur_source_rate is null then 0
              else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
            end,
            2
          ) as raw_delta_before_reservation_ex,
          round(
            case
              when wba.cur_source_charge_rate is null then 0
              else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_charge_rate, 2)
            end,
            2
          ) as raw_delta_charge_ex_vat,
          round(
            case
              when coalesce(b.has_active_overpayment_case,false) = true
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) < 0
                then 0
              when b.require_reference_to_pay = true
               and coalesce(b.is_forced_advance,false) = false
               and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) > 0
                then 0
              else round(
                case
                  when wba.cur_source_rate is null then 0
                  else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                end,
                2
              )
            end,
            2
          ) as preview_base_eff_delta_ex,
          round(
            case
              when coalesce(b.has_active_overpayment_case,false) = true
               and round(
                 case
                   when wba.cur_source_rate is null then 0
                   else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                 end,
                 2
               ) < 0
                then 0
              when round(
                case
                  when wba.cur_source_rate is null then 0
                  else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                end,
                2
              ) > 0
                then round(
                  case
                    when wba.cur_source_rate is null then 0
                    else round((coalesce(wba.cur_source_units,0) - coalesce(wba.bas_source_units,0)) * wba.cur_source_rate, 2)
                  end,
                  2
                )
              else 0
            end,
            2
          ) as allocatable_delta_ex,
          coalesce(rss.reserved_amount_ex_vat, 0) as reserved_key_amount_ex_vat
        from ts_baseline b
        join worked_time_bucket_agg wba
          on wba.timesheet_id = b.timesheet_id
         and wba.candidate_id = b.candidate_id
        left join reserved_segment_sums rss
          on rss.timesheet_id = b.timesheet_id
         and rss.component_key_type = wba.component_key_type
         and rss.component_key_value = wba.component_key_value
  
  ;

  create temporary table worked_time_bucket_alloc on commit drop as
        select
          wbc.*,
          round(
            case
              when coalesce(wbc.allocatable_delta_ex,0) <= 0 then 0
              else greatest(
                least(
                  coalesce(wbc.reserved_key_amount_ex_vat,0)
                  - coalesce(
                      sum(coalesce(wbc.allocatable_delta_ex,0)) over (
                        partition by wbc.timesheet_id, wbc.component_key_type, wbc.component_key_value
                        order by wbc.segment_sort_ord nulls last, wbc.bucket_sort_ord, wbc.bucket_row_ord, wbc.segment_id nulls last
                        rows between unbounded preceding and 1 preceding
                      ),
                      0
                    ),
                  wbc.allocatable_delta_ex
                ),
                0
              )
            end,
            2
          ) as allocated_reserved_amount_ex_vat
        from worked_time_bucket_calc wbc
  
  ;

  create temporary table worked_time_bucket_effective on commit drop as
        select
          wba.candidate_id,
          wba.timesheet_id,
          wba.client_id,
          wba.ts_week_ending_date,
          wba.ts_client_name,
          wba.ts_pay_method,
          wba.cand_pay_method,
          wba.cand_tms_ref,
          wba.cand_display_name,
          wba.cand_umbrella_id,
          wba.umb_enabled,
          wba.umb_vat_chargeable,
          wba.cand_bank_hash,
          wba.umb_bank_hash,
          wba.booking_id,
          wba.segment_id,
          wba.segment_key,
          wba.segment_stable_key,
          wba.component_key_type,
          wba.component_key_value,
          wba.bucket_code,
          wba.bucket_sort_ord,
          wba.bucket_row_ord,
          wba.segment_sort_ord,
          wba.work_date,
          wba.ref_num,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when round(
              round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
              2
            ) <> round(
              case
                when wba.has_active_overpayment_case = true
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                  then 0
                when wba.require_reference_to_pay = true
                 and wba.is_forced_advance = false
                 and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                  then 0
                else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
              end,
              2
            ) then null::numeric
            else wba.source_rate
          end as source_rate,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when wba.source_charge_rate is not null then wba.source_charge_rate
            when round(coalesce(wba.raw_delta_charge_ex_vat,0), 2) = 0 then null::numeric
            else round(
              round(coalesce(wba.raw_delta_charge_ex_vat,0), 2)
              / nullif(round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6), 0),
              6
            )
          end as source_charge_rate,
          round(
            case
              when wba.has_active_overpayment_case = true
               and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                then 0
              when wba.require_reference_to_pay = true
               and wba.is_forced_advance = false
               and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
               and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                then 0
              else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
            end,
            2
          ) as component_amount_ex_vat,
          round(
            case
              when wba.source_charge_rate is not null
               and wba.source_rate is not null
               and wba.source_rate <> 0
               and round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) > 0
               and round(
                 round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
                 2
               ) = round(
                 case
                   when wba.has_active_overpayment_case = true
                    and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                     then 0
                   when wba.require_reference_to_pay = true
                    and wba.is_forced_advance = false
                    and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                    and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                     then 0
                   else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
                 end,
                 2
               )
                then round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_charge_rate, 2)
              when round(coalesce(wba.raw_delta_before_reservation_ex,0), 2) = 0 then round(coalesce(wba.raw_delta_charge_ex_vat,0), 2)
              else round(
                coalesce(wba.raw_delta_charge_ex_vat,0)
                * (
                    (
                      case
                        when wba.has_active_overpayment_case = true
                         and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                          then 0
                        when wba.require_reference_to_pay = true
                         and wba.is_forced_advance = false
                         and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                         and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                          then 0
                        else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
                      end
                    ) / nullif(round(coalesce(wba.raw_delta_before_reservation_ex,0), 2), 0)
                  ),
                2
              )
            end,
            2
          ) as source_charge_ex_vat,
          case
            when wba.source_rate is null or wba.source_rate = 0 then null::numeric
            when round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6) <= 0 then null::numeric
            when round(
              round(greatest(coalesce(wba.raw_delta_source_units,0), 0) * wba.source_rate, 2),
              2
            ) <> round(
              case
                when wba.has_active_overpayment_case = true
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) < 0
                  then 0
                when wba.require_reference_to_pay = true
                 and wba.is_forced_advance = false
                 and (wba.ref_num is null or btrim(coalesce(wba.ref_num,'')) = '')
                 and round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2) > 0
                  then 0
                else round(coalesce(wba.raw_delta_before_reservation_ex,0) - coalesce(wba.allocated_reserved_amount_ex_vat,0), 2)
              end,
              2
            ) then null::numeric
            else round(greatest(coalesce(wba.raw_delta_source_units,0), 0), 6)
          end as source_units
        from worked_time_bucket_alloc wba
  
  ;

  create temporary table worked_time_bucket_component_rows on commit drop as
        select
          wtbe.candidate_id,
          wtbe.timesheet_id,
          wtbe.client_id,
          wtbe.ts_week_ending_date,
          wtbe.ts_client_name,
          wtbe.ts_pay_method,
          wtbe.cand_pay_method,
          wtbe.cand_tms_ref,
          wtbe.cand_display_name,
          wtbe.cand_umbrella_id,
          wtbe.umb_enabled,
          wtbe.umb_vat_chargeable,
          wtbe.cand_bank_hash,
          wtbe.umb_bank_hash,
          ('timesheet:' || wtbe.timesheet_id::text) as source_family_key,
          wtbe.component_key_type,
          wtbe.component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(wtbe.component_amount_ex_vat,0), 2) as component_amount_ex_vat,
          round(coalesce(wtbe.source_charge_ex_vat,0), 2) as source_charge_ex_vat,
          case when wtbe.source_units is null then null else round(wtbe.source_units, 6) end as source_units,
          case when wtbe.source_rate is null then null else round(wtbe.source_rate, 6) end as source_rate,
          case when wtbe.source_charge_rate is null then null else round(wtbe.source_charge_rate, 6) end as source_charge_rate,
          upper(coalesce(wtbe.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(wtbe.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', wtbe.timesheet_id::text,
              'segment_id', wtbe.segment_id,
              'segment_key', wtbe.segment_key,
              'segment_stable_key', wtbe.segment_stable_key,
              'work_date', wtbe.work_date,
              'ref_num', wtbe.ref_num,
              'bucket_code', wtbe.bucket_code,
              'source_units', case when wtbe.source_units is null then null else round(wtbe.source_units, 6) end,
              'source_rate', case when wtbe.source_rate is null then null else round(wtbe.source_rate, 6) end,
              'source_charge_rate', case when wtbe.source_charge_rate is null then null else round(wtbe.source_charge_rate, 6) end,
              'source_charge_ex_vat', round(coalesce(wtbe.source_charge_ex_vat,0), 2),
              'source_pay_ex_vat', round(coalesce(wtbe.component_amount_ex_vat,0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || wtbe.timesheet_id::text),
            wtbe.component_key_type,
            wtbe.component_key_value,
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(wtbe.ts_pay_method, '')),
            upper(coalesce(wtbe.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', wtbe.timesheet_id::text,
                'segment_id', wtbe.segment_id,
                'segment_key', wtbe.segment_key,
                'segment_stable_key', wtbe.segment_stable_key,
                'work_date', wtbe.work_date,
                'ref_num', wtbe.ref_num,
                'bucket_code', wtbe.bucket_code
              )
            ),
            round(coalesce(wtbe.component_amount_ex_vat,0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(wtbe.cand_pay_method, '')))
          ) as component_fingerprint
        from worked_time_bucket_effective wtbe
        where round(coalesce(wtbe.component_amount_ex_vat,0), 2) <> 0
  
  ;

  create temporary table worked_time_key_totals on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end as component_key_type,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null
              then nullif(btrim(coalesce(seg->>'work_date','')), '')
            else 'TOTAL'
          end as component_key_value,
          round(sum(coalesce(nullif(seg->>'delta_pay_ex_vat','')::numeric, 0)), 2) as total_pay_ex_vat,
          round(sum(coalesce(nullif(seg->>'delta_charge_ex_vat','')::numeric, 0)), 2) as total_charge_ex_vat
        from ts_itemised d
        cross join lateral jsonb_array_elements(coalesce(d.segment_deltas_json, '[]'::jsonb)) seg
        group by
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null then 'TS_DAY'::text
            else 'TS_TOTAL'::text
          end,
          case
            when nullif(btrim(coalesce(seg->>'work_date','')), '') is not null
              then nullif(btrim(coalesce(seg->>'work_date','')), '')
            else 'TOTAL'
          end
        having round(sum(coalesce(nullif(seg->>'delta_pay_ex_vat','')::numeric, 0)), 2) <> 0
  
  ;

  create temporary table worked_time_bucket_component_sums on commit drop as
        select
          wtcr.candidate_id,
          wtcr.timesheet_id,
          wtcr.component_key_type,
          wtcr.component_key_value,
          round(sum(coalesce(wtcr.component_amount_ex_vat,0)), 2) as total_bucket_pay_ex_vat,
          round(sum(coalesce(wtcr.source_charge_ex_vat,0)), 2) as total_bucket_charge_ex_vat
        from worked_time_bucket_component_rows wtcr
        group by
          wtcr.candidate_id,
          wtcr.timesheet_id,
          wtcr.component_key_type,
          wtcr.component_key_value
  
  ;

  create temporary table worked_time_amount_fallback_rows on commit drop as
        select
          wkt.candidate_id,
          wkt.timesheet_id,
          wkt.client_id,
          wkt.ts_week_ending_date,
          wkt.ts_client_name,
          wkt.ts_pay_method,
          wkt.cand_pay_method,
          wkt.cand_tms_ref,
          wkt.cand_display_name,
          wkt.cand_umbrella_id,
          wkt.umb_enabled,
          wkt.umb_vat_chargeable,
          wkt.cand_bank_hash,
          wkt.umb_bank_hash,
          ('timesheet:' || wkt.timesheet_id::text) as source_family_key,
          wkt.component_key_type,
          wkt.component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2) as component_amount_ex_vat,
          round(coalesce(wkt.total_charge_ex_vat,0) - coalesce(wbcs.total_bucket_charge_ex_vat,0), 2) as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(wkt.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(wkt.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', wkt.timesheet_id::text,
              'work_date', case when wkt.component_key_type = 'TS_DAY' then wkt.component_key_value else null end,
              'component_fallback', 'WORKED_TIME_AMOUNT',
              'source_charge_ex_vat', round(coalesce(wkt.total_charge_ex_vat,0) - coalesce(wbcs.total_bucket_charge_ex_vat,0), 2),
              'source_pay_ex_vat', round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || wkt.timesheet_id::text),
            wkt.component_key_type,
            wkt.component_key_value,
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(wkt.ts_pay_method, '')),
            upper(coalesce(wkt.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', wkt.timesheet_id::text,
                'work_date', case when wkt.component_key_type = 'TS_DAY' then wkt.component_key_value else null end,
                'component_fallback', 'WORKED_TIME_AMOUNT'
              )
            ),
            round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(wkt.cand_pay_method, '')))
          ) as component_fingerprint
        from worked_time_key_totals wkt
        left join worked_time_bucket_component_sums wbcs
          on wbcs.candidate_id = wkt.candidate_id
         and wbcs.timesheet_id = wkt.timesheet_id
         and wbcs.component_key_type = wkt.component_key_type
         and wbcs.component_key_value = wkt.component_key_value
        where round(coalesce(wkt.total_pay_ex_vat,0) - coalesce(wbcs.total_bucket_pay_ex_vat,0), 2) <> 0
  
  ;

  create temporary table timesheet_component_rows on commit drop as
        select
          wt.candidate_id,
          wt.timesheet_id,
          wt.client_id,
          wt.ts_week_ending_date,
          wt.ts_client_name,
          wt.ts_pay_method,
          wt.cand_pay_method,
          wt.cand_tms_ref,
          wt.cand_display_name,
          wt.cand_umbrella_id,
          wt.umb_enabled,
          wt.umb_vat_chargeable,
          wt.cand_bank_hash,
          wt.umb_bank_hash,
          wt.source_family_key,
          wt.component_key_type,
          wt.component_key_value,
          wt.classification,
          wt.component_amount_ex_vat,
          wt.source_charge_ex_vat,
          wt.source_units,
          wt.source_rate,
          wt.source_charge_rate,
          wt.source_pay_method,
          wt.current_target_pay_method,
          wt.source_basis_json,
          wt.component_fingerprint
        from worked_time_bucket_component_rows wt

        union all

        select
          wf.candidate_id,
          wf.timesheet_id,
          wf.client_id,
          wf.ts_week_ending_date,
          wf.ts_client_name,
          wf.ts_pay_method,
          wf.cand_pay_method,
          wf.cand_tms_ref,
          wf.cand_display_name,
          wf.cand_umbrella_id,
          wf.umb_enabled,
          wf.umb_vat_chargeable,
          wf.cand_bank_hash,
          wf.umb_bank_hash,
          wf.source_family_key,
          wf.component_key_type,
          wf.component_key_value,
          wf.classification,
          wf.component_amount_ex_vat,
          wf.source_charge_ex_vat,
          wf.source_units,
          wf.source_rate,
          wf.source_charge_rate,
          wf.source_pay_method,
          wf.current_target_pay_method,
          wf.source_basis_json,
          wf.component_fingerprint
        from worked_time_amount_fallback_rows wf
        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'ADDITIONAL_CODE'::text as component_key_type,
          coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL') as component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2) as component_amount_ex_vat,
          round(coalesce(nullif(au->>'delta_charge_ex_vat','')::numeric, 0), 2) as source_charge_ex_vat,
          nullif(au->>'source_units','')::numeric as source_units,
          nullif(au->>'source_rate','')::numeric as source_rate,
          nullif(au->>'source_charge_rate','')::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'additional_code', coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL'),
              'source_units', nullif(au->>'source_units','')::numeric,
              'source_rate', nullif(au->>'source_rate','')::numeric,
              'source_charge_rate', nullif(au->>'source_charge_rate','')::numeric,
              'source_charge_ex_vat', round(coalesce(nullif(au->>'delta_charge_ex_vat','')::numeric, 0), 2),
              'source_pay_ex_vat', round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'ADDITIONAL_CODE',
            coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL'),
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'additional_code', coalesce(nullif(btrim(coalesce(au->>'code','')), ''), 'TOTAL')
              )
            ),
            round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral jsonb_array_elements(
          case
            when jsonb_array_length(coalesce(d.additional_unit_deltas_json, '[]'::jsonb)) > 0 then coalesce(d.additional_unit_deltas_json, '[]'::jsonb)
            when round(coalesce(d.delta_additional_pay_ex_vat, 0), 2) <> 0 then jsonb_build_array(jsonb_build_object('code', 'TOTAL', 'delta_pay_ex_vat', d.delta_additional_pay_ex_vat))
            else '[]'::jsonb
          end
        ) au
        where round(coalesce(nullif(au->>'delta_pay_ex_vat','')::numeric, 0), 2) <> 0

        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'ADJUSTMENT_CODE'::text as component_key_type,
          coalesce(nullif(btrim(coalesce(adj->>'adj_id','')), ''), 'TOTAL') as component_key_value,
          'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum as classification,
          round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2) as component_amount_ex_vat,
          null::numeric as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'adjustment_id', nullif(btrim(coalesce(adj->>'adj_id','')), ''),
              'source_pay_ex_vat', round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2)
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'ADJUSTMENT_CODE',
            coalesce(nullif(btrim(coalesce(adj->>'adj_id','')), ''), 'TOTAL'),
            'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'adjustment_id', nullif(btrim(coalesce(adj->>'adj_id','')), '')
              )
            ),
            round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2),
            v_erni_pct,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral jsonb_array_elements(coalesce(d.adjustment_deltas_json, '[]'::jsonb)) adj
        where round(coalesce(nullif(adj->>'delta_pay_ex_vat','')::numeric, 0), 2) <> 0

        union all

        select
          d.candidate_id,
          d.timesheet_id,
          d.client_id,
          d.ts_week_ending_date,
          d.ts_client_name,
          d.ts_pay_method,
          d.cand_pay_method,
          d.cand_tms_ref,
          d.cand_display_name,
          d.cand_umbrella_id,
          d.umb_enabled,
          d.umb_vat_chargeable,
          d.cand_bank_hash,
          d.umb_bank_hash,
          ('timesheet:' || d.timesheet_id::text) as source_family_key,
          'EXPENSE_CODE'::text as component_key_type,
          x.component_key_value,
          'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum as classification,
          x.component_amount_ex_vat,
          case x.component_key_value
            when 'EXPENSES' then round(coalesce(d.delta_expenses_charge_ex_vat,0),2)
            when 'TRAVEL' then round(coalesce(d.delta_travel_charge_ex_vat,0),2)
            when 'ACCOMMODATION' then round(coalesce(d.delta_accommodation_charge_ex_vat,0),2)
            when 'OTHER' then round(coalesce(d.delta_other_charge_ex_vat,0),2)
            when 'MILEAGE' then round(coalesce(d.delta_mileage_charge_ex_vat,0),2)
            else null::numeric
          end as source_charge_ex_vat,
          null::numeric as source_units,
          null::numeric as source_rate,
          null::numeric as source_charge_rate,
          upper(coalesce(d.ts_pay_method, '')) as source_pay_method,
          upper(coalesce(d.cand_pay_method, '')) as current_target_pay_method,
          jsonb_strip_nulls(
            jsonb_build_object(
              'timesheet_id', d.timesheet_id::text,
              'expense_code', x.component_key_value,
              'source_charge_ex_vat', case x.component_key_value
                when 'EXPENSES' then round(coalesce(d.delta_expenses_charge_ex_vat,0),2)
                when 'TRAVEL' then round(coalesce(d.delta_travel_charge_ex_vat,0),2)
                when 'ACCOMMODATION' then round(coalesce(d.delta_accommodation_charge_ex_vat,0),2)
                when 'OTHER' then round(coalesce(d.delta_other_charge_ex_vat,0),2)
                when 'MILEAGE' then round(coalesce(d.delta_mileage_charge_ex_vat,0),2)
                else null::numeric
              end,
              'source_pay_ex_vat', x.component_amount_ex_vat
            )
          ) as source_basis_json,
          public.pay_finance_component_fingerprint(
            ('timesheet:' || d.timesheet_id::text),
            'EXPENSE_CODE',
            x.component_key_value,
            'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
            upper(coalesce(d.ts_pay_method, '')),
            upper(coalesce(d.cand_pay_method, '')),
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', d.timesheet_id::text,
                'expense_code', x.component_key_value
              )
            ),
            x.component_amount_ex_vat,
            NULL::numeric,
            jsonb_build_object('candidate_pay_method', upper(coalesce(d.cand_pay_method, '')))
          ) as component_fingerprint
        from ts_itemised d
        cross join lateral (
          values
            (
              'EXPENSES',
              case
                when round(coalesce(d.delta_travel_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_accommodation_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_other_pay_ex_vat, 0), 2) <> 0
                  or round(coalesce(d.delta_mileage_pay_ex_vat, 0), 2) <> 0
                then 0::numeric
                else round(coalesce(d.delta_expenses_pay_ex_vat, 0), 2)
              end
            ),
            ('TRAVEL', round(coalesce(d.delta_travel_pay_ex_vat, 0), 2)),
            ('ACCOMMODATION', round(coalesce(d.delta_accommodation_pay_ex_vat, 0), 2)),
            ('OTHER', round(coalesce(d.delta_other_pay_ex_vat, 0), 2)),
            ('MILEAGE', round(coalesce(d.delta_mileage_pay_ex_vat, 0), 2))
        ) as x(component_key_value, component_amount_ex_vat)
        where x.component_amount_ex_vat <> 0
  
  ;

  create temporary table timesheet_component_match_rows on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tcr.client_id,
          tcr.ts_week_ending_date,
          tcr.ts_client_name,
          tcr.ts_pay_method,
          tcr.cand_pay_method,
          tcr.cand_tms_ref,
          tcr.cand_display_name,
          tcr.cand_umbrella_id,
          tcr.umb_enabled,
          tcr.umb_vat_chargeable,
          tcr.cand_bank_hash,
          tcr.umb_bank_hash,
          tcr.source_family_key,
          tcr.component_key_type,
          tcr.component_key_value,
          tcr.classification,
          tcr.component_amount_ex_vat,
          tcr.source_charge_ex_vat,
          tcr.source_units,
          tcr.source_rate,
          tcr.source_charge_rate,
          tcr.source_pay_method,
          tcr.current_target_pay_method,
          tcr.source_basis_json,
          tcr.component_fingerprint,
          mdc.finance_case_id as matched_finance_case_id,
          mdc.finance_component_id as matched_finance_component_id,
          mdc.saved_target_pay_method as matched_saved_target_pay_method,
          mdc.saved_resolution_mode as matched_saved_resolution_mode,
          mdc.saved_resolution_payload_json as matched_saved_resolution_payload_json,
          mdc.saved_resolution_result_json as matched_saved_resolution_result_json,
          mdc.resolution_fingerprint as matched_resolution_fingerprint,
          mdc.is_resolution_stale as matched_is_resolution_stale,
          mdc.stale_reason as matched_stale_reason
        from timesheet_component_rows tcr
        left join lateral (
          select
            pfc.finance_case_id,
            pfc.id as finance_component_id,
            pfc.saved_target_pay_method,
            pfc.saved_resolution_mode,
            pfc.saved_resolution_payload_json,
            pfc.saved_resolution_result_json,
            pfc.resolution_fingerprint,
            pfc.is_resolution_stale,
            pfc.stale_reason
          from public.pay_finance_case_components pfc
          join finance_case_baseline_scope vfcr_m
            on vfcr_m.finance_case_id = pfc.finance_case_id
           and vfcr_m.candidate_id = tcr.candidate_id
           and vfcr_m.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
          where pfc.closed_at_utc is null
            and coalesce(pfc.remaining_source_amount, 0) > 0
            and pfc.candidate_id = tcr.candidate_id
            and pfc.linked_timesheet_id = tcr.timesheet_id
            and pfc.source_family_key = tcr.source_family_key
            and pfc.component_key_type = tcr.component_key_type
            and pfc.component_key_value = tcr.component_key_value
            and pfc.classification = tcr.classification
            and coalesce(pfc.source_basis_json, '{}'::jsonb) = coalesce(tcr.source_basis_json, '{}'::jsonb)
          order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
          limit 1
        ) mdc on true
  
  ;

  create temporary table transient_timesheet_component_rows on commit drop as
        select
          tmr.candidate_id,
          tmr.timesheet_id,
          tmr.client_id,
          tmr.ts_week_ending_date,
          tmr.ts_client_name,
          tmr.ts_pay_method,
          tmr.cand_pay_method,
          tmr.cand_tms_ref,
          tmr.cand_display_name,
          tmr.cand_umbrella_id,
          tmr.umb_enabled,
          tmr.umb_vat_chargeable,
          tmr.cand_bank_hash,
          tmr.umb_bank_hash,
          tmr.source_family_key,
          tmr.component_key_type,
          tmr.component_key_value,
          tmr.classification,
          tmr.component_amount_ex_vat,
          tmr.source_charge_ex_vat,
          tmr.source_units,
          tmr.source_rate,
          tmr.source_charge_rate,
          tmr.source_pay_method,
          tmr.current_target_pay_method,
          tmr.source_basis_json,
          tmr.component_fingerprint
        from timesheet_component_match_rows tmr
        where tmr.matched_finance_component_id is null
  
  ;

  create temporary table transient_timesheet_component_review_rows on commit drop as
        select
          ttr.candidate_id,
          ttr.timesheet_id,
          ttr.client_id,
          ttr.ts_week_ending_date,
          ttr.ts_client_name,
          ttr.ts_pay_method,
          ttr.cand_pay_method,
          ttr.cand_tms_ref,
          ttr.cand_display_name,
          ttr.cand_umbrella_id,
          ttr.umb_enabled,
          ttr.umb_vat_chargeable,
          ttr.cand_bank_hash,
          ttr.umb_bank_hash,
          ttr.source_family_key,
          ttr.component_key_type,
          ttr.component_key_value,
          ttr.classification,
          ttr.component_amount_ex_vat,
          ttr.source_charge_ex_vat,
          ttr.source_units,
          ttr.source_rate,
          ttr.source_charge_rate,
          ttr.source_pay_method,
          ttr.current_target_pay_method,
          ttr.source_basis_json,
          ttr.component_fingerprint,
          (
            ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and ttr.source_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method <> ''
            and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
          ) as has_suggested_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and ttr.source_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
            and ttr.current_target_pay_method <> ''
            and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
          ) as is_fresh_suggested_resolution,
          false as is_reusable_saved_resolution,
          false as is_stale_saved_resolution,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', ttr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'suggested_target_rate', case when ttr.source_units is not null and ttr.source_units <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.source_units, 2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else null::jsonb
          end as suggested_resolution_payload_json,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', ttr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2),
                'target_amount_vat', round(coalesce((ttrs.target_amounts_json->>'vat')::numeric,0),2),
                'target_amount_inc_vat', round(coalesce((ttrs.target_amounts_json->>'inc')::numeric,0),2),
                'basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'replacement_rate', case when ttr.source_units is not null and ttr.source_units <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.source_units, 2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'vat')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(round(coalesce((ttrs.target_amounts_json->>'inc')::numeric,0),2) / ttr.component_amount_ex_vat, 10) else null end,
                'target_units_per_source_ex_vat', case when ttr.source_units is not null and coalesce(ttr.component_amount_ex_vat,0) <> 0 then round(ttr.source_units / ttr.component_amount_ex_vat, 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'source_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2),
                'target_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'target_margin_ex_vat', case when ttr.source_charge_ex_vat is null or ttrs.target_amounts_json is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'margin_delta_ex_vat', case when ttr.source_charge_ex_vat is null or ttrs.target_amounts_json is null then null else 0::numeric end
              )
            )
            else null::jsonb
          end as suggested_resolution_result_json,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end as source_charge_component_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end as source_margin_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttrs.target_amounts_json is not null then round(coalesce((ttrs.target_amounts_json->>'ex')::numeric,0),2) else null end as target_pay_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null then round(ttr.source_charge_ex_vat,2) else null end as target_charge_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null and ttrs.target_amounts_json is not null then round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) else null end as target_margin_ex_vat,
          case when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,'')) and ttr.source_charge_ex_vat is not null and ttrs.target_amounts_json is not null then 0::numeric else null end as margin_delta_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
          end as suggestion_explanation_text
        from transient_timesheet_component_rows ttr
        left join lateral (
          select
            case
              when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when ttr.source_pay_method = 'PAYE' and ttr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(ttr.component_amount_ex_vat, v_erni_pct, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              when ttr.source_pay_method = 'UMBRELLA' and ttr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(ttr.component_amount_ex_vat, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(ttr.component_amount_ex_vat, v_erni_pct))
              when ttr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(ttr.component_amount_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(ttr.component_amount_ex_vat,0),2))
              when ttr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(ttr.component_amount_ex_vat, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) ttrs on true
  
  ;

  create temporary table timesheet_case_actionable_basis on commit drop as
        select distinct
          ttrr.timesheet_id,
          case
            when ttrr.component_key_type in ('TS_DAY','TS_TOTAL')
              then ('SEGMENT_BUCKET:' || coalesce(nullif(btrim(coalesce(ttrr.source_basis_json->>'bucket_code','')), ''), 'UNSPECIFIED'))
            when ttrr.component_key_type = 'ADDITIONAL_CODE' then ('ADDITIONAL_CODE:' || coalesce(ttrr.component_key_value,''))
            else (coalesce(ttrr.component_key_type,'') || ':' || coalesce(ttrr.component_key_value,''))
          end as basis_family_key,
          upper(coalesce(ttrr.source_pay_method,'')) as source_pay_method,
          round(coalesce(ttrr.source_rate,0),6) as source_rate,
          round(coalesce(ttrr.source_charge_rate,0),6) as source_charge_rate
        from transient_timesheet_component_review_rows ttrr
        where ttrr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          and upper(coalesce(ttrr.source_pay_method,'')) is distinct from upper(coalesce(ttrr.current_target_pay_method,''))
          and ttrr.source_units is not null
          and coalesce(ttrr.source_units,0) <> 0
          and ttrr.source_rate is not null
          and ttrr.source_charge_rate is not null
          and ttrr.component_key_type <> 'ADJUSTMENT_CODE'
  
  ;

  create temporary table timesheet_live_scope on commit drop as
        select
          tb.candidate_id,
          tb.timesheet_id,
          tb.client_id,
          public.timesheets.contract_id,
          case
            when public.timesheets.contract_id is not null then 'CONTRACT'
            else 'DAILY_SAME_BASIS'
          end as linked_scope_type,
          md5(
            coalesce(
              (
                select jsonb_agg(
                  jsonb_build_object(
                    'basis_family_key', tcab.basis_family_key,
                    'source_pay_method', tcab.source_pay_method,
                    'source_rate', tcab.source_rate,
                    'source_charge_rate', tcab.source_charge_rate
                  )
                  order by tcab.basis_family_key, tcab.source_pay_method, tcab.source_rate, tcab.source_charge_rate
                )::text
                from timesheet_case_actionable_basis tcab
                where tcab.timesheet_id = tb.timesheet_id
              ),
              '[]'
            )
          ) as actionable_basis_signature
        from ts_baseline tb
        join public.timesheets
          on public.timesheets.timesheet_id = tb.timesheet_id
  
  ;

  create temporary table timesheet_linked_scope_counts on commit drop as
        select
          seed_scope.timesheet_id as seed_timesheet_id,
          count(*)::int as linked_timesheet_count,
          coalesce(jsonb_agg(target_scope.timesheet_id::text order by target_scope.timesheet_id::text), '[]'::jsonb) as linked_timesheet_ids_json
        from timesheet_live_scope seed_scope
        join timesheet_live_scope target_scope
          on target_scope.candidate_id = seed_scope.candidate_id
         and (
           (
             seed_scope.contract_id is not null
             and target_scope.contract_id is not distinct from seed_scope.contract_id
           )
           or (
             seed_scope.contract_id is null
             and target_scope.contract_id is null
             and target_scope.client_id is not distinct from seed_scope.client_id
             and target_scope.actionable_basis_signature is not distinct from seed_scope.actionable_basis_signature
           )
         )
        group by seed_scope.timesheet_id
  
  ;

  create temporary table transient_timesheet_component_review_rows_effective on commit drop as
        select
          ttr.candidate_id,
          ttr.timesheet_id,
          ttr.client_id,
          ttr.ts_week_ending_date,
          ttr.ts_client_name,
          ttr.ts_pay_method,
          ttr.cand_pay_method,
          ttr.cand_tms_ref,
          ttr.cand_display_name,
          ttr.cand_umbrella_id,
          ttr.umb_enabled,
          ttr.umb_vat_chargeable,
          ttr.cand_bank_hash,
          ttr.umb_bank_hash,
          ttr.source_family_key,
          ttr.component_key_type,
          ttr.component_key_value,
          ttr.classification,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as component_amount_ex_vat,
          round(coalesce(ttr.source_charge_ex_vat,0),2) as source_charge_ex_vat,
          ttr.source_units,
          ttr.source_rate,
          ttr.source_charge_rate,
          ttr.source_pay_method,
          ttr.current_target_pay_method,
          ttr.source_basis_json,
          ttr.component_fingerprint,
          ttrx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          ttrx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then false
            when ttrx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then true
            when ttrx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
             and ttr.source_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
             and ttr.current_target_pay_method <> ''
             and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
            then true
            else false
          end as has_suggested_resolution,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when ttrx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (ttrx.is_actionable_bucket_resolution = true) as is_fresh_suggested_resolution,
          false as is_reusable_saved_resolution,
          false as is_stale_saved_resolution,
          case
            when ttrx.is_actionable_bucket_resolution = true then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', ttr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'suggested_target_rate', case when tts.suggested_target_rate is null then null else round(tts.suggested_target_rate,2) end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else null::jsonb
          end as suggested_resolution_payload_json,
          case
            when ttrx.is_actionable_bucket_resolution = true then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', ttr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'inc','')::numeric, coalesce(tts.suggested_target_pay_ex_vat,0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(ttr.umb_vat_chargeable,false),
                'target_units', case when ttr.source_units is not null then round(ttr.source_units,6) else null end,
                'replacement_rate', case when tts.suggested_target_rate is null then null else round(tts.suggested_target_rate,2) end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(ttam.suggested_target_amounts_json->>'inc','')::numeric, coalesce(tts.suggested_target_pay_ex_vat,0), 0),2) / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when ttr.source_units is not null and round(coalesce(ttr.component_amount_ex_vat,0),2) <> 0 then round(ttr.source_units / round(coalesce(ttr.component_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(ttr.component_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'source_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(nullif(ttam.suggested_target_amounts_json->>'ex','')::numeric, tts.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end,
                'target_margin_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end,
                'margin_delta_ex_vat', case when ttr.source_charge_ex_vat is null then null else 0::numeric end
              )
            )
            else null::jsonb
          end as suggested_resolution_result_json,
          round(coalesce(ttr.component_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat,2) end as source_charge_component_ex_vat,
          case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null then round(ttr.source_charge_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null
              then round(ttr.source_charge_ex_vat - ttr.component_amount_ex_vat, 2)
            else null::numeric
          end as target_margin_ex_vat,
          case
            when ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and ttr.source_charge_ex_vat is not null
              then 0::numeric
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when ttrx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when ttrx.is_actionable_bucket_resolution = true then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as preview_component_amount_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
            when ttrx.is_actionable_bucket_resolution = true then 0::numeric
            else round(coalesce(tts.suggested_target_pay_ex_vat, ttr.component_amount_ex_vat, 0),2)
          end as ready_preview_amount_ex_vat,
          case
            when ttrx.is_actionable_bucket_resolution = true then round(coalesce(ttr.component_amount_ex_vat,0),2)
            else 0::numeric
          end as blocked_preview_amount_ex_vat,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'FIXED'
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then 'NOT_REQUIRED'
            when ttrx.is_actionable_bucket_resolution = true then 'REQUIRED'
            else 'FIXED'
          end as resolution_state,
          case
            when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::numeric
            when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then null::numeric
            when ttrx.is_actionable_bucket_resolution = true then round(tts.suggested_target_rate,2)
            else null::numeric
          end as target_rate
        from transient_timesheet_component_review_rows ttr
        left join lateral (
          select
            (
              ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and ttr.source_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method <> ''
              and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
              and round(coalesce(ttr.component_amount_ex_vat,0),2) > 0
              and ttr.source_units is not null
              and coalesce(ttr.source_units,0) <> 0
              and ttr.source_rate is not null
              and ttr.source_charge_rate is not null
              and ttr.component_key_type <> 'ADJUSTMENT_CODE'
            ) as is_actionable_bucket_resolution,
            (
              ttr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and ttr.source_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method in ('PAYE','UMBRELLA')
              and ttr.current_target_pay_method <> ''
              and upper(coalesce(ttr.source_pay_method,'')) is distinct from upper(coalesce(ttr.current_target_pay_method,''))
              and not (
                ttr.source_units is not null
                and coalesce(ttr.source_units,0) <> 0
                and ttr.source_rate is not null
                and ttr.source_charge_rate is not null
                and ttr.component_key_type <> 'ADJUSTMENT_CODE'
              )
            ) as is_fixed_taxable_conversion
        ) ttrx on true
        left join lateral (
          select
            case
              when ttr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(ttr.component_amount_ex_vat,0),2)
              when upper(coalesce(ttr.source_pay_method,'')) is not distinct from upper(coalesce(ttr.current_target_pay_method,'')) then round(coalesce(ttr.component_amount_ex_vat,0),2)
              when ttr.source_pay_method = 'PAYE' and ttr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(ttr.component_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when ttr.source_pay_method = 'UMBRELLA' and ttr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(ttr.component_amount_ex_vat,0),2), v_erni_pct),2)
              when ttr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(ttr.component_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(ttr.component_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) ttb on true
        left join lateral (
          select
            case
              when ttrx.is_actionable_bucket_resolution = true and ttr.source_units is not null and ttr.source_units <> 0
                then round(ttb.target_ex_before_rate / ttr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when ttrx.is_actionable_bucket_resolution = true and ttr.source_units is not null and ttr.source_units <> 0
                then round(round(ttb.target_ex_before_rate / ttr.source_units, 2) * ttr.source_units, 2)
              else round(ttb.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) tts on true
        left join lateral (
          select
            case
              when tts.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(ttr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(tts.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(ttr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(tts.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(tts.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) ttam on true
  
  ;

  create temporary table timesheet_case_rollup on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          max(tcr.client_id::text)::uuid as client_id,
          max(tcr.ts_week_ending_date) as ts_week_ending_date,
          max(tcr.ts_client_name) as ts_client_name,
          max(tcr.ts_pay_method) as ts_pay_method,
          max(tcr.cand_pay_method) as cand_pay_method,
          max(tcr.cand_tms_ref) as cand_tms_ref,
          max(tcr.cand_display_name) as cand_display_name,
          max(tcr.cand_umbrella_id::text)::uuid as cand_umbrella_id,
          bool_or(tcr.umb_enabled) as umb_enabled,
          bool_or(tcr.umb_vat_chargeable) as umb_vat_chargeable,
          bool_or(tcr.cand_bank_hash is not null and btrim(tcr.cand_bank_hash) <> '') as candidate_has_bank_details,
          max(tcr.cand_bank_hash) as candidate_bank_hash,
          bool_or(tcr.umb_bank_hash is not null and btrim(tcr.umb_bank_hash) <> '') as umbrella_has_bank_details,
          max(tcr.umb_bank_hash) as umbrella_bank_hash,
          'BUCKETED'::text as resolution_family,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) as case_needs_resolution,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) = 0) as case_resolution_satisfied_now,
          'Suggested Rate'::text as resolution_action_label,
          jsonb_strip_nulls(
            jsonb_build_object(
              'resolve_all_linked_timesheets_default', true,
              'linked_scope_type', coalesce(max(tls.linked_scope_type), 'SELF_ONLY'),
              'linked_timesheet_count', coalesce(max(tslc.linked_timesheet_count), 1),
              'linked_timesheet_ids', coalesce(min(tslc.linked_timesheet_ids_json::text)::jsonb, jsonb_build_array(tcr.timesheet_id::text)),
              'contract_id', case when max(tls.contract_id::text) is null then null else max(tls.contract_id::text) end,
              'client_id', case when max(tls.client_id::text) is null then null else max(tls.client_id::text) end,
              'seed_timesheet_id', tcr.timesheet_id::text,
              'confirmation_text', (
                'This will resolve ' || coalesce(max(tslc.linked_timesheet_count), 1)::text || ' timesheets for this candidate. Are you sure you wish to continue?'
              )
            )
          ) as linked_resolution_scope_json,
          round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) as case_total_amount_ex,
          round(
            case
              when count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0 then 0::numeric
              else sum(coalesce(tcr.ready_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0))
            end,
            2
          ) as safe_amount_ex,
          round(sum(case when coalesce(tcr.requires_resolution, false) = true then coalesce(tcr.blocked_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2) as unresolved_taxable_amount_ex,
          count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) as open_taxable_count,
          count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) as open_reimbursement_count,
          count(*) filter (where coalesce(tcr.requires_resolution, false) = true) as unresolved_taxable_count,
          0::integer as stale_count,
          (count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) > 0 and count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) > 0) as is_mixed_case,
          (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) as is_blocked,
          round(sum(case when tcr.component_key_type in ('TS_DAY','TS_TOTAL') then coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2) as segments_total_ex,
          max(coalesce(td.delta_additional_pay_ex_vat, 0)) as delta_additional_pay_ex_vat,
          max(coalesce(td.delta_expenses_pay_ex_vat, 0)) as delta_expenses_pay_ex_vat,
          max(coalesce(td.delta_travel_pay_ex_vat, 0)) as delta_travel_pay_ex_vat,
          max(coalesce(td.delta_accommodation_pay_ex_vat, 0)) as delta_accommodation_pay_ex_vat,
          max(coalesce(td.delta_other_pay_ex_vat, 0)) as delta_other_pay_ex_vat,
          max(coalesce(td.delta_mileage_pay_ex_vat, 0)) as delta_mileage_pay_ex_vat,
          coalesce(min(td.segment_deltas_json::text)::jsonb, '[]'::jsonb) as segment_deltas_json,
          coalesce(min(td.adjustment_deltas_json::text)::jsonb, '[]'::jsonb) as adjustment_deltas_json,
          coalesce(min(td.additional_unit_deltas_json::text)::jsonb, '[]'::jsonb) as additional_unit_deltas_json,
          bool_or(coalesce(td.reservation_overrun_detected,false)) as reservation_overrun_detected,
          round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2) as payment_amount_ex_vat,
          round(
            case
              when max(tcr.cand_pay_method) = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2),
                  v_vat_rate_pct,
                  bool_or(tcr.umb_vat_chargeable)
                )->>'inc')::numeric
              else round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2)
            end,
            2
          ) as payment_amount_inc_vat,
          round(
            case
              when max(tcr.cand_pay_method) = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(
                  round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2),
                  v_vat_rate_pct,
                  bool_or(tcr.umb_vat_chargeable)
                )->>'inc')::numeric
              else round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)),2)
            end,
            2
          ) as payment_amount,
          jsonb_build_object(
            'case_key', ('timesheet:' || max(tcr.timesheet_id::text)),
            'case_type', 'TIMESHEET_PAYMENT',
            'resolution_family', 'BUCKETED',
            'case_needs_resolution', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0),
            'case_resolution_satisfied_now', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) = 0),
            'resolution_action_label', 'Suggested Rate',
            'linked_resolution_scope_json', jsonb_strip_nulls(
              jsonb_build_object(
                'resolve_all_linked_timesheets_default', true,
                'linked_scope_type', coalesce(max(tls.linked_scope_type), 'SELF_ONLY'),
                'linked_timesheet_count', coalesce(max(tslc.linked_timesheet_count), 1),
                'linked_timesheet_ids', coalesce(min(tslc.linked_timesheet_ids_json::text)::jsonb, jsonb_build_array(tcr.timesheet_id::text)),
                'contract_id', case when max(tls.contract_id::text) is null then null else max(tls.contract_id::text) end,
                'client_id', case when max(tls.client_id::text) is null then null else max(tls.client_id::text) end,
                'seed_timesheet_id', tcr.timesheet_id::text,
                'confirmation_text', ('This will resolve ' || coalesce(max(tslc.linked_timesheet_count), 1)::text || ' timesheets for this candidate. Are you sure you wish to continue?')
              )
            ),
            'is_mixed_case', (count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) > 0 and count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) > 0),
            'open_taxable_count', count(*) filter (where tcr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),
            'open_reimbursement_count', count(*) filter (where tcr.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum),
            'unresolved_taxable_count', count(*) filter (where coalesce(tcr.requires_resolution, false) = true),
            'stale_count', 0,
            'is_blocked', (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0),
            'safe_amount_ex_vat', case when (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) then 0::numeric else round(sum(coalesce(tcr.ready_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) end,
            'blocked_case_amount_ex_vat', case when (count(*) filter (where coalesce(tcr.requires_resolution, false) = true) > 0) then round(sum(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0)), 2) else 0::numeric end,
            'unresolved_taxable_amount_ex_vat', round(sum(case when coalesce(tcr.requires_resolution, false) = true then coalesce(tcr.blocked_preview_amount_ex_vat, tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0) else 0 end), 2)
          ) as case_resolution_summary_json,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'finance_component_id', null,
                'source_family_key', tcr.source_family_key,
                'component_key_type', tcr.component_key_type,
                'component_key_value', tcr.component_key_value,
                'label',
                  case
                    when tcr.component_key_type in ('TS_DAY','TS_TOTAL')
                      then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''), tcr.component_key_value, tcr.component_key_type)
                    when tcr.component_key_type = 'ADDITIONAL_CODE'
                      then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'additional_code','')), ''), tcr.component_key_value)
                    when tcr.component_key_type = 'ADJUSTMENT_CODE'
                      then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'adjustment_id','')), ''), tcr.component_key_value)
                    when tcr.component_key_type = 'EXPENSE_CODE'
                      then coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'expense_code','')), ''), tcr.component_key_value)
                    else tcr.component_key_value
                  end,
                'bucket_code', nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''),
                'source_basis_fingerprint', md5(coalesce(tcr.source_basis_json::text, '{}'::text)),
                'is_rate_bearing',
                  (
                    tcr.source_units is not null
                    and coalesce(tcr.source_units,0) <> 0
                    and tcr.source_rate is not null
                    and tcer.effective_source_charge_rate is not null
                    and tcr.component_key_type <> 'ADJUSTMENT_CODE'
                  ),
                'classification', tcr.classification::text,
                'source_pay_method', tcr.source_pay_method,
                'current_target_pay_method', tcr.current_target_pay_method,
                'component_amount_ex_vat', round(coalesce(tcr.component_amount_ex_vat,0),2),
                'preview_component_amount_ex_vat', round(coalesce(tcr.preview_component_amount_ex_vat, tcr.component_amount_ex_vat, 0),2),
                'ready_preview_amount_ex_vat', round(coalesce(tcr.ready_preview_amount_ex_vat, 0),2),
                'blocked_preview_amount_ex_vat', round(coalesce(tcr.blocked_preview_amount_ex_vat, 0),2),
                'source_basis_json', jsonb_strip_nulls(
                  tcr.source_basis_json
                  || jsonb_build_object(
                    'source_rate', case when tcr.source_rate is null then null else round(tcr.source_rate,2) end,
                    'source_charge_rate',
                      case
                        when tcer.effective_source_charge_rate is null then null
                        else round(tcer.effective_source_charge_rate, 2)
                      end
                  )
                ),
                'saved_target_pay_method', null,
                'saved_resolution_mode', case when tcr.approved_resolution_mode is null then null else tcr.approved_resolution_mode end,
                'saved_resolution_payload_json', null,
                'saved_resolution_result_json', null,
                'has_suggested_resolution', tcr.has_suggested_resolution,
                'suggestion_provenance', tcr.suggestion_provenance,
                'is_fresh_suggested_resolution', tcr.is_fresh_suggested_resolution,
                'is_reusable_saved_resolution', tcr.is_reusable_saved_resolution,
                'is_stale_saved_resolution', tcr.is_stale_saved_resolution,
                'suggested_resolution_payload_json', tcr.suggested_resolution_payload_json,
                'suggested_resolution_result_json', tcr.suggested_resolution_result_json,
                'source_units', tcr.source_units,
                'target_units', case when ttrg.target_units is null then tcr.source_units else ttrg.target_units end,
                'source_rate', case when tcr.source_rate is null then null else round(tcr.source_rate,2) end,
                'source_charge_rate',
                  case
                    when tcer.effective_source_charge_rate is null then null
                    else round(tcer.effective_source_charge_rate, 2)
                  end,
                'target_rate', case when tcr.target_rate is null then null else round(tcr.target_rate,2) end,
                'source_pay_ex_vat', tcr.source_pay_ex_vat,
                'source_charge_ex_vat', tcr.source_charge_component_ex_vat,
                'source_margin_ex_vat', tcr.source_margin_ex_vat,
                'target_pay_ex_vat', tcr.target_pay_ex_vat,
                'target_charge_ex_vat', tcr.target_charge_ex_vat,
                'target_margin_ex_vat', tcr.target_margin_ex_vat,
                'margin_delta_ex_vat', tcr.margin_delta_ex_vat,
                'suggestion_explanation_text', tcr.suggestion_explanation_text,
                'component_fingerprint', tcr.component_fingerprint,
                'is_resolution_stale', false,
                'stale_reason', null,
                'requires_resolution', coalesce(tcr.requires_resolution, false),
                'resolution_state', tcr.resolution_state,
                'is_actionable_resolution_row', coalesce(tcr.is_actionable_resolution_row, false),
                'is_fixed_no_action_taxable_row', coalesce(tcr.is_fixed_no_action_taxable_row, false)
              )
              order by
                case
                  when tcr.component_key_type in ('TS_DAY','TS_TOTAL') then 1
                  when tcr.component_key_type = 'ADDITIONAL_CODE' then 2
                  when tcr.component_key_type = 'ADJUSTMENT_CODE' then 3
                  when tcr.component_key_type = 'EXPENSE_CODE' then 4
                  else 9
                end,
                tcr.component_key_value,
                coalesce(nullif(btrim(coalesce(tcr.source_basis_json->>'bucket_code','')), ''), '')
            ),
            '[]'::jsonb
          ) as case_components_json
        from transient_timesheet_component_review_rows_effective tcr
        left join ts_deltas td
          on td.timesheet_id = tcr.timesheet_id
         and td.candidate_id = tcr.candidate_id
        left join timesheet_live_scope tls
          on tls.timesheet_id = tcr.timesheet_id
        left join timesheet_linked_scope_counts tslc
          on tslc.seed_timesheet_id = tcr.timesheet_id
        left join lateral (
          select
            case
              when tcr.source_charge_rate is not null then tcr.source_charge_rate
              when coalesce(tcr.source_basis_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$'
                then (tcr.source_basis_json->>'source_charge_rate')::numeric
              when coalesce(tcr.source_units,0) <> 0 and tcr.source_charge_component_ex_vat is not null
                then (tcr.source_charge_component_ex_vat / tcr.source_units)
              else null::numeric
            end as effective_source_charge_rate
        ) tcer on true
        left join lateral (
          select
            case
              when tcr.target_rate is not null and tcr.source_units is not null then round(tcr.source_units,6)
              else tcr.source_units
            end as target_units
        ) ttrg on true
        group by tcr.candidate_id, tcr.timesheet_id
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'timesheet_component_count', (select count(*)::int from timesheet_component_rows),
    'transient_review_component_count', (select count(*)::int from transient_timesheet_component_review_rows_effective),
    'timesheet_case_rollup_count', (select count(*)::int from timesheet_case_rollup)
  );
end;
$function$;





CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_entitlement_rows(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.ts_baseline') is null then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.segment_status, pg_temp.blocked_items_all, pg_temp.blocked_items, pg_temp.blocked_items_snoozed, pg_temp.do_not_pay_all, pg_temp.do_not_pay_items, pg_temp.do_not_pay_items_snoozed, pg_temp.ts_deltas, pg_temp.ts_itemised;

  create temporary table segment_status on commit drop as
        -- Economic-key segment reconciliation:
        -- segment identity is retained only for UI continuity and snooze matching.
        -- Outstanding and reservation subtraction stay in the economic entitlement keyspace
        -- (TS_DAY => work_date, TS_TOTAL => TOTAL).
        with
        cur_segments as (
          select
            b.timesheet_id,
            b.candidate_id,
            cur_seg.seg_ord as source_seg_ord,
            nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')),'') as segment_id,
            nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')),'') as ref_num,
            nullif(btrim(coalesce(cur_seg.seg->>'date','')),'') as work_date,
            coalesce(nullif(cur_seg.seg->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
            round(coalesce(nullif(cur_seg.seg->>'pay_amount','')::numeric,0),2) as pay_amount_ex_vat,
            round(coalesce(nullif(cur_seg.seg->>'charge_amount','')::numeric, nullif(cur_seg.seg->>'charge_ex_vat','')::numeric,0),2) as charge_amount_ex_vat,
            case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end as source_units,
            null::numeric as source_rate,
            case
              when nullif(cur_seg.seg->>'charge_rate','') is not null then round(nullif(cur_seg.seg->>'charge_rate','')::numeric, 6)
              when nullif(cur_seg.seg->>'charge_unit_rate','') is not null then round(nullif(cur_seg.seg->>'charge_unit_rate','')::numeric, 6)
              when (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) is not null
               and (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) <> 0
              then round(
                round(coalesce(nullif(cur_seg.seg->>'charge_amount','')::numeric, nullif(cur_seg.seg->>'charge_ex_vat','')::numeric,0),2) / (case
              when nullif(cur_seg.seg->>'units','') is not null then nullif(cur_seg.seg->>'units','')::numeric
              when nullif(cur_seg.seg->>'hours','') is not null then nullif(cur_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(cur_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (cur_seg.seg->>'end_utc')::timestamptz
                        - (cur_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(cur_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(cur_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(cur_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(cur_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(cur_seg.seg->>'break_mins','')::numeric,
                        nullif(cur_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end),
                6
              )
              else null::numeric
            end as source_charge_rate,
            coalesce(
              nullif(btrim(coalesce(cur_seg.seg->>'segment_stable_key','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'segment_id','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'segment_key','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'date','')),''),
              nullif(btrim(coalesce(cur_seg.seg->>'ref_num','')),'')
            ) as segment_stable_key,
            case
              when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
              else 'TS_TOTAL'::text
            end as component_key_type,
            case
              when nullif(btrim(coalesce(cur_seg.seg->>'date','')), '') is not null
                then nullif(btrim(coalesce(cur_seg.seg->>'date','')), '')
              else 'TOTAL'
            end as component_key_value
          from ts_baseline b
          join lateral jsonb_array_elements(coalesce(b.current_segments_json,'[]'::jsonb)) with ordinality as cur_seg(seg, seg_ord) on true
          where cur_seg.seg is not null
            and jsonb_typeof(cur_seg.seg) = 'object'
        ),
        bas_segments as (
          select
            b.timesheet_id,
            b.candidate_id,
            bas_seg.seg_ord as source_seg_ord,
            nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')),'') as segment_id,
            nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')),'') as ref_num,
            nullif(btrim(coalesce(bas_seg.seg->>'date','')),'') as work_date,
            coalesce(nullif(bas_seg.seg->>'exclude_from_pay','')::boolean,false) as exclude_from_pay,
            round(coalesce(nullif(bas_seg.seg->>'pay_amount','')::numeric,0),2) as pay_amount_ex_vat,
            round(coalesce(nullif(bas_seg.seg->>'charge_amount','')::numeric, nullif(bas_seg.seg->>'charge_ex_vat','')::numeric,0),2) as charge_amount_ex_vat,
            case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end as source_units,
            null::numeric as source_rate,
            case
              when nullif(bas_seg.seg->>'charge_rate','') is not null then round(nullif(bas_seg.seg->>'charge_rate','')::numeric, 6)
              when nullif(bas_seg.seg->>'charge_unit_rate','') is not null then round(nullif(bas_seg.seg->>'charge_unit_rate','')::numeric, 6)
              when (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) is not null
               and (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end) <> 0
              then round(
                round(coalesce(nullif(bas_seg.seg->>'charge_amount','')::numeric, nullif(bas_seg.seg->>'charge_ex_vat','')::numeric,0),2) / (case
              when nullif(bas_seg.seg->>'units','') is not null then nullif(bas_seg.seg->>'units','')::numeric
              when nullif(bas_seg.seg->>'hours','') is not null then nullif(bas_seg.seg->>'hours','')::numeric
              when nullif(btrim(coalesce(bas_seg.seg->>'start_utc','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end_utc','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (bas_seg.seg->>'end_utc')::timestamptz
                        - (bas_seg.seg->>'start_utc')::timestamptz
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              when nullif(btrim(coalesce(bas_seg.seg->>'start','')), '') is not null
               and nullif(btrim(coalesce(bas_seg.seg->>'end','')), '') is not null
              then round(
                greatest(
                  (
                    extract(
                      epoch from (
                        (
                          timestamp '2000-01-01'
                          + nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time
                          + case
                              when nullif(btrim(coalesce(bas_seg.seg->>'end','')), '')::time < nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                              then interval '1 day'
                              else interval '0 day'
                            end
                        )
                        - (
                            timestamp '2000-01-01'
                            + nullif(btrim(coalesce(bas_seg.seg->>'start','')), '')::time
                          )
                      )
                    ) / 3600.0
                  )
                  - (
                      coalesce(
                        nullif(bas_seg.seg->>'break_mins','')::numeric,
                        nullif(bas_seg.seg->>'break_minutes','')::numeric,
                        0
                      ) / 60.0
                    ),
                  0
                ),
                6
              )
              else null::numeric
            end),
                6
              )
              else null::numeric
            end as source_charge_rate,
            coalesce(
              nullif(btrim(coalesce(bas_seg.seg->>'segment_stable_key','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'segment_id','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'segment_key','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'date','')),''),
              nullif(btrim(coalesce(bas_seg.seg->>'ref_num','')),'')
            ) as segment_stable_key,
            case
              when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null then 'TS_DAY'::text
              else 'TS_TOTAL'::text
            end as component_key_type,
            case
              when nullif(btrim(coalesce(bas_seg.seg->>'date','')), '') is not null
                then nullif(btrim(coalesce(bas_seg.seg->>'date','')), '')
              else 'TOTAL'
            end as component_key_value
          from ts_baseline b
          join lateral jsonb_array_elements(coalesce(b.base_json->'segments','[]'::jsonb)) with ordinality as bas_seg(seg, seg_ord) on true
          where bas_seg.seg is not null
            and jsonb_typeof(bas_seg.seg) = 'object'
        ),
        active_settled_key_baselines as (
          select
            ts_base.timesheet_id,
            ts_base.candidate_id,
            upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')) as component_key_type,
            nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '') as component_key_value,
            round(
              coalesce(
                sum(
                  coalesce(
                    nullif(btrim(coalesce(active_component.component_json->>'amount_ex_vat','')), '')::numeric,
                    0
                  )
                ),
                0
              ),
              2
            ) as baseline_amount_ex_vat,
            round(
              coalesce(
                sum(
                  coalesce(
                    nullif(btrim(coalesce(active_component.component_json->>'amount_inc_vat','')), '')::numeric,
                    0
                  )
                ),
                0
              ),
              2
            ) as baseline_amount_inc_vat
          from ts_baseline ts_base
          join lateral jsonb_array_elements(
            case
              when coalesce(ts_base.has_active_settled_artifact_baseline, false) = true
               and jsonb_typeof(coalesce(ts_base.active_settled_artifact_components_json, '[]'::jsonb)) = 'array'
              then coalesce(ts_base.active_settled_artifact_components_json, '[]'::jsonb)
              else '[]'::jsonb
            end
          ) as active_component(component_json) on true
          where active_component.component_json is not null
            and jsonb_typeof(active_component.component_json) = 'object'
            and upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')) is not null
            and nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '') is not null
          group by
            ts_base.timesheet_id,
            ts_base.candidate_id,
            upper(nullif(btrim(coalesce(active_component.component_json->>'key_type','')), '')),
            nullif(btrim(coalesce(active_component.component_json->>'key_value','')), '')
        ),
        cur_ranked as (
          select
            cs.timesheet_id,
            cs.candidate_id,
            cs.source_seg_ord,
            cs.segment_id,
            cs.ref_num,
            cs.work_date,
            cs.exclude_from_pay,
            cs.pay_amount_ex_vat,
            cs.charge_amount_ex_vat,
            cs.source_units,
            cs.source_rate,
            cs.source_charge_rate,
            cs.segment_stable_key,
            cs.component_key_type,
            cs.component_key_value,
            row_number() over (
              partition by cs.timesheet_id, cs.candidate_id, cs.component_key_type, cs.component_key_value
              order by cs.source_seg_ord nulls last, cs.segment_id nulls last, cs.ref_num nulls last
            ) as bucket_row_ord
          from cur_segments cs
        ),
        bas_ranked as (
          select
            bs.timesheet_id,
            bs.candidate_id,
            bs.source_seg_ord,
            bs.segment_id,
            bs.ref_num,
            bs.work_date,
            bs.exclude_from_pay,
            bs.pay_amount_ex_vat,
            bs.charge_amount_ex_vat,
            bs.source_units,
            bs.source_rate,
            bs.source_charge_rate,
            bs.segment_stable_key,
            bs.component_key_type,
            bs.component_key_value,
            row_number() over (
              partition by bs.timesheet_id, bs.candidate_id, bs.component_key_type, bs.component_key_value
              order by bs.source_seg_ord nulls last, bs.segment_id nulls last, bs.ref_num nulls last
            ) as bucket_row_ord
          from bas_segments bs
        ),
        ids as (
          select distinct
            cr.timesheet_id,
            cr.candidate_id,
            cr.component_key_type,
            cr.component_key_value,
            cr.bucket_row_ord
          from cur_ranked cr
          union
          select distinct
            br.timesheet_id,
            br.candidate_id,
            br.component_key_type,
            br.component_key_value,
            br.bucket_row_ord
          from bas_ranked br
        ),
        agg as (
          select
            i.timesheet_id,
            i.candidate_id,
            i.component_key_type,
            i.component_key_value,
            i.bucket_row_ord,
            max(cr.segment_id) as cur_segment_id,
            max(br.segment_id) as bas_segment_id,
            max(coalesce(cr.ref_num, br.ref_num)) as ref_num,
            max(coalesce(cr.work_date, br.work_date)) as work_date,
            max(coalesce(cr.segment_stable_key, br.segment_stable_key)) as segment_stable_key,
            max(cr.source_seg_ord) as cur_source_seg_ord,
            max(br.source_seg_ord) as bas_source_seg_ord,
            bool_or(coalesce(cr.exclude_from_pay,false)) as cur_excluded,
            max(cr.source_units) as cur_source_units,
            max(cr.source_rate) as cur_source_rate,
            max(cr.source_charge_rate) as cur_source_charge_rate,
            round(sum(case when cr.bucket_row_ord = i.bucket_row_ord then (case when coalesce(cr.exclude_from_pay,false) then 0 else coalesce(cr.pay_amount_ex_vat,0) end) else 0 end), 2) as cur_payable_ex_vat,
            round(sum(case when br.bucket_row_ord = i.bucket_row_ord then (case when coalesce(br.exclude_from_pay,false) then 0 else coalesce(br.pay_amount_ex_vat,0) end) else 0 end), 2) as bas_payable_ex_vat,
            round(sum(case when cr.bucket_row_ord = i.bucket_row_ord then (case when coalesce(cr.exclude_from_pay,false) then 0 else coalesce(cr.charge_amount_ex_vat,0) end) else 0 end), 2) as cur_charge_ex_vat,
            round(sum(case when br.bucket_row_ord = i.bucket_row_ord then (case when coalesce(br.exclude_from_pay,false) then 0 else coalesce(br.charge_amount_ex_vat,0) end) else 0 end), 2) as bas_charge_ex_vat
          from ids i
          left join cur_ranked cr
            on cr.timesheet_id = i.timesheet_id
           and cr.candidate_id = i.candidate_id
           and cr.component_key_type = i.component_key_type
           and cr.component_key_value = i.component_key_value
           and cr.bucket_row_ord = i.bucket_row_ord
          left join bas_ranked br
            on br.timesheet_id = i.timesheet_id
           and br.candidate_id = i.candidate_id
           and br.component_key_type = i.component_key_type
           and br.component_key_value = i.component_key_value
           and br.bucket_row_ord = i.bucket_row_ord
          group by i.timesheet_id, i.candidate_id, i.component_key_type, i.component_key_value, i.bucket_row_ord
        ),
        agg_active_baseline as (
          select
            agg_rows.timesheet_id,
            agg_rows.candidate_id,
            agg_rows.component_key_type,
            agg_rows.component_key_value,
            agg_rows.bucket_row_ord,
            agg_rows.cur_segment_id,
            agg_rows.bas_segment_id,
            agg_rows.ref_num,
            agg_rows.work_date,
            agg_rows.segment_stable_key,
            agg_rows.cur_source_seg_ord,
            agg_rows.bas_source_seg_ord,
            agg_rows.cur_excluded,
            agg_rows.cur_source_units,
            agg_rows.cur_source_rate,
            agg_rows.cur_source_charge_rate,
            agg_rows.cur_payable_ex_vat,
            agg_rows.bas_payable_ex_vat,
            agg_rows.cur_charge_ex_vat,
            agg_rows.bas_charge_ex_vat,
            active_key_baseline.baseline_amount_ex_vat as active_settled_key_baseline_ex_vat,
            active_key_baseline.baseline_amount_inc_vat as active_settled_key_baseline_inc_vat,
            round(
              case
                when active_key_baseline.baseline_amount_ex_vat is null then 0
                when coalesce(agg_rows.cur_payable_ex_vat, 0) <= 0 then 0
                else greatest(
                  least(
                    coalesce(agg_rows.cur_payable_ex_vat, 0),
                    greatest(
                      coalesce(active_key_baseline.baseline_amount_ex_vat, 0)
                      - coalesce(
                          sum(coalesce(agg_rows.cur_payable_ex_vat, 0)) over (
                            partition by agg_rows.timesheet_id, agg_rows.candidate_id, agg_rows.component_key_type, agg_rows.component_key_value
                            order by agg_rows.bucket_row_ord
                            rows between unbounded preceding and 1 preceding
                          ),
                          0
                        ),
                      0
                    )
                  ),
                  0
                )
              end,
              2
            ) as active_settled_allocated_baseline_ex_vat
          from agg agg_rows
          left join active_settled_key_baselines active_key_baseline
            on active_key_baseline.timesheet_id = agg_rows.timesheet_id
           and active_key_baseline.candidate_id = agg_rows.candidate_id
           and active_key_baseline.component_key_type = agg_rows.component_key_type
           and active_key_baseline.component_key_value = agg_rows.component_key_value
        ),
        agg_effective_baseline as (
          select
            active_rows.timesheet_id,
            active_rows.candidate_id,
            active_rows.component_key_type,
            active_rows.component_key_value,
            active_rows.bucket_row_ord,
            active_rows.cur_segment_id,
            active_rows.bas_segment_id,
            active_rows.ref_num,
            active_rows.work_date,
            active_rows.segment_stable_key,
            active_rows.cur_source_seg_ord,
            active_rows.bas_source_seg_ord,
            active_rows.cur_excluded,
            active_rows.cur_source_units,
            active_rows.cur_source_rate,
            active_rows.cur_source_charge_rate,
            active_rows.cur_payable_ex_vat,
            active_rows.bas_payable_ex_vat,
            active_rows.cur_charge_ex_vat,
            active_rows.bas_charge_ex_vat,
            active_rows.active_settled_key_baseline_ex_vat,
            active_rows.active_settled_key_baseline_inc_vat,
            active_rows.active_settled_allocated_baseline_ex_vat,
            round(
              case
                when active_rows.active_settled_key_baseline_ex_vat is not null
                then coalesce(active_rows.active_settled_allocated_baseline_ex_vat, 0)
                else coalesce(active_rows.bas_payable_ex_vat, 0)
              end,
              2
            ) as effective_bas_payable_ex_vat,
            round(
              case
                when active_rows.active_settled_key_baseline_ex_vat is not null then
                  case
                    when coalesce(active_rows.cur_payable_ex_vat, 0) <= 0 then 0
                    else round(
                      coalesce(active_rows.cur_charge_ex_vat, 0)
                      * (coalesce(active_rows.active_settled_allocated_baseline_ex_vat, 0) / nullif(coalesce(active_rows.cur_payable_ex_vat, 0), 0)),
                      2
                    )
                  end
                else coalesce(active_rows.bas_charge_ex_vat, 0)
              end,
              2
            ) as effective_bas_charge_ex_vat
          from agg_active_baseline active_rows
        ),
        calc as (
          select
            b.candidate_id,
            b.timesheet_id,
            b.ts_booking_id as booking_id,
            coalesce(a.cur_segment_id, a.bas_segment_id) as segment_id,
            coalesce(a.cur_segment_id, a.bas_segment_id) as segment_key,
            a.segment_stable_key,
            a.component_key_type,
            a.component_key_value,
            a.bucket_row_ord,
            coalesce(a.cur_source_seg_ord, a.bas_source_seg_ord) as segment_sort_ord,
            a.work_date,
            a.ref_num,
            a.cur_source_units as source_units,
            a.cur_source_rate as source_rate,
            a.cur_source_charge_rate as source_charge_rate,
            a.cur_excluded,
            coalesce(b.has_active_overpayment_case,false) as has_active_overpayment_case,
            b.require_reference_to_pay,
            coalesce(b.is_forced_advance,false) as is_forced_advance,
            round(
              coalesce(a.cur_payable_ex_vat,0)
              - coalesce(a.effective_bas_payable_ex_vat,0),
              2
            ) as raw_delta_before_reservation_ex,
            round(
              coalesce(a.cur_charge_ex_vat,0)
              - coalesce(a.effective_bas_charge_ex_vat,0),
              2
            ) as raw_delta_charge_ex_vat,
            round(
              case
                when (
                  coalesce(b.has_active_overpayment_case,false) = true
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) < 0
                )
                then 0
                when (
                  b.require_reference_to_pay = true
                  and coalesce(b.is_forced_advance,false) = false
                  and a.cur_excluded = false
                  and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) > 0
                )
                then 0
                else round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                )
              end,
              2
            ) as preview_base_eff_delta_ex,
            round(
              case
                when (
                  coalesce(b.has_active_overpayment_case,false) = true
                  and round(
                    coalesce(a.cur_payable_ex_vat,0)
                    - coalesce(a.effective_bas_payable_ex_vat,0),
                    2
                  ) < 0
                )
                then 0
                when round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                ) > 0
                then round(
                  coalesce(a.cur_payable_ex_vat,0)
                  - coalesce(a.effective_bas_payable_ex_vat,0),
                  2
                )
                else 0
              end,
              2
            ) as allocatable_delta_ex,
            coalesce(rss.reserved_amount_ex_vat,0) as reserved_bucket_amount_ex_vat
          from ts_baseline b
          join agg_effective_baseline a
            on a.timesheet_id = b.timesheet_id
           and a.candidate_id = b.candidate_id
          left join reserved_segment_sums rss
            on rss.timesheet_id = b.timesheet_id
           and rss.component_key_type = a.component_key_type
           and rss.component_key_value = a.component_key_value
        ),
        alloc as (
          select
            c.candidate_id,
            c.timesheet_id,
            c.booking_id,
            c.segment_id,
            c.segment_key,
            c.segment_stable_key,
            c.component_key_type,
            c.component_key_value,
            c.bucket_row_ord,
            c.segment_sort_ord,
            c.work_date,
            c.ref_num,
            c.source_units,
            c.source_rate,
            c.source_charge_rate,
            c.cur_excluded,
            c.has_active_overpayment_case,
            c.require_reference_to_pay,
            c.is_forced_advance,
            c.raw_delta_before_reservation_ex,
            c.raw_delta_charge_ex_vat,
            c.preview_base_eff_delta_ex,
            c.reserved_bucket_amount_ex_vat,
            round(
              case
                when coalesce(c.allocatable_delta_ex,0) <= 0 then 0
                else greatest(
                  least(
                    coalesce(c.reserved_bucket_amount_ex_vat,0)
                    - coalesce(
                        sum(coalesce(c.allocatable_delta_ex,0)) over (
                          partition by c.timesheet_id, c.component_key_type, c.component_key_value
                          order by c.segment_sort_ord nulls last, c.bucket_row_ord, c.segment_id nulls last
                          rows between unbounded preceding and 1 preceding
                        ),
                        0
                      ),
                    c.allocatable_delta_ex
                  ),
                  0
                )
              end,
              2
            ) as allocated_reserved_amount_ex_vat
          from calc c
        )
        select
          a.candidate_id,
          a.timesheet_id,
          a.booking_id,
          a.segment_id,
          a.segment_key,
          a.segment_stable_key,
          a.component_key_type,
          a.component_key_value,
          a.bucket_row_ord,
          a.segment_sort_ord,
          a.work_date,
          a.ref_num,
          a.source_units,
          a.source_rate,
          a.source_charge_rate,
          a.raw_delta_before_reservation_ex,
          a.raw_delta_charge_ex_vat,
          a.preview_base_eff_delta_ex,
          round(
            case
              when (
                a.has_active_overpayment_case = true
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) < 0
              )
              then 0
              else round(
                a.raw_delta_before_reservation_ex
                - a.allocated_reserved_amount_ex_vat,
                2
              )
            end,
            2
          ) as delta_pay_ex_vat,
          round(
            case
              when (
                a.has_active_overpayment_case = true
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) < 0
              )
              then 0
              when (
                a.require_reference_to_pay = true
                and a.is_forced_advance = false
                and a.cur_excluded = false
                and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                and round(
                  a.raw_delta_before_reservation_ex
                  - a.allocated_reserved_amount_ex_vat,
                  2
                ) > 0
              )
              then 0
              else round(
                a.raw_delta_before_reservation_ex
                - a.allocated_reserved_amount_ex_vat,
                2
              )
            end,
            2
          ) as eff_delta_ex,
          case
            when round(a.raw_delta_before_reservation_ex, 2) = 0 then round(a.raw_delta_charge_ex_vat, 2)
            else round(
              a.raw_delta_charge_ex_vat
              * (
                  (
                    case
                      when (
                        a.has_active_overpayment_case = true
                        and round(
                          a.raw_delta_before_reservation_ex
                          - a.allocated_reserved_amount_ex_vat,
                          2
                        ) < 0
                      )
                      then 0
                      when (
                        a.require_reference_to_pay = true
                        and a.is_forced_advance = false
                        and a.cur_excluded = false
                        and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
                        and round(
                          a.raw_delta_before_reservation_ex
                          - a.allocated_reserved_amount_ex_vat,
                          2
                        ) > 0
                      )
                      then 0
                      else round(
                        a.raw_delta_before_reservation_ex
                        - a.allocated_reserved_amount_ex_vat,
                        2
                      )
                    end
                  ) / nullif(round(a.raw_delta_before_reservation_ex, 2),0)
                ),
              2
            )
          end as eff_delta_charge_ex_vat,
          (
            coalesce(a.cur_excluded,false) = true
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) <> 0
          ) as is_do_not_pay,
          (
            a.require_reference_to_pay = true
            and a.is_forced_advance = false
            and a.cur_excluded = false
            and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) > 0
          ) as is_ref_missing,
          (
            a.require_reference_to_pay = true
            and a.is_forced_advance = false
            and a.cur_excluded = false
            and (a.ref_num is null or btrim(coalesce(a.ref_num,'')) = '')
            and round(
              a.raw_delta_before_reservation_ex
              - a.allocated_reserved_amount_ex_vat,
              2
            ) > 0
          ) as is_blocked,
          null::uuid as snooze_id,
          null::date as snooze_until_date,
          null::text as note
        from alloc a
  
  ;

  create temporary table blocked_items_all on commit drop as
        select
          ss.candidate_id,
          ss.timesheet_id,
          ss.booking_id,
          ss.segment_id,
          ss.segment_stable_key,
          ss.ref_num,
          ss.delta_pay_ex_vat as blocked_delta_ex,
          sn.snooze_id,
          sn.snooze_until_date,
          sn.note
        from segment_status ss
        left join active_segment_snoozes sn
          on sn.candidate_id = ss.candidate_id
         and sn.snooze_kind = 'BLOCKED_TIMESHEET'
         and (
           (sn.booking_id is not null and ss.booking_id is not null and sn.booking_id = ss.booking_id and sn.segment_stable_key is not distinct from ss.segment_stable_key)
           or (sn.booking_id is null and sn.timesheet_id is not distinct from ss.timesheet_id and sn.segment_id is not distinct from ss.segment_id)
         )
        where ss.is_blocked = true
  
  ;

  create temporary table blocked_items on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.booking_id,
          b.segment_id,
          b.segment_stable_key,
          b.ref_num,
          b.blocked_delta_ex,
          b.snooze_id
        from blocked_items_all b
        where b.snooze_id is null
  
  ;

  create temporary table blocked_items_snoozed on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.booking_id,
          b.segment_id,
          b.segment_stable_key,
          b.ref_num,
          b.blocked_delta_ex,
          b.snooze_id,
          b.snooze_until_date,
          b.note
        from blocked_items_all b
        where b.snooze_id is not null
          and b.snooze_until_date is not null
  
  ;

  create temporary table do_not_pay_all on commit drop as
        select
          ss.candidate_id,
          ss.timesheet_id,
          ss.booking_id,
          ss.segment_id,
          ss.segment_stable_key,
          ss.ref_num as ref_num,
          ss.delta_pay_ex_vat as raw_delta_ex,
          sn.snooze_id,
          sn.snooze_until_date,
          sn.note
        from segment_status ss
        left join active_segment_snoozes sn
          on sn.candidate_id = ss.candidate_id
         and sn.snooze_kind = 'DO_NOT_PAY'
         and (
           (sn.booking_id is not null and ss.booking_id is not null and sn.booking_id = ss.booking_id and sn.segment_stable_key is not distinct from ss.segment_stable_key)
           or (sn.booking_id is null and sn.timesheet_id is not distinct from ss.timesheet_id and sn.segment_id is not distinct from ss.segment_id)
         )
        where ss.is_do_not_pay = true
  
  ;

  create temporary table do_not_pay_items on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.booking_id,
          d.segment_id,
          d.segment_stable_key,
          d.ref_num,
          d.raw_delta_ex,
          d.snooze_id
        from do_not_pay_all d
        where d.snooze_id is null
           or coalesce(d.raw_delta_ex,0) <> 0
  
  ;

  create temporary table do_not_pay_items_snoozed on commit drop as
        select
          d.candidate_id,
          d.timesheet_id,
          d.booking_id,
          d.segment_id,
          d.segment_stable_key,
          d.ref_num,
          d.raw_delta_ex,
          d.snooze_id,
          d.snooze_until_date,
          d.note
        from do_not_pay_all d
        where d.snooze_id is not null
          and d.snooze_until_date is not null
          and coalesce(d.raw_delta_ex,0) = 0
  
  ;

  create temporary table ts_deltas on commit drop as
        select
          b.candidate_id,
          b.timesheet_id,
          b.client_id,

          b.ts_week_ending_date,
          b.ts_client_name,
          b.ts_pay_method,
          b.cand_pay_method,

          b.cand_tms_ref,
          b.cand_display_name,
          b.cand_umbrella_id,

          b.umb_enabled,
          b.umb_vat_chargeable,

          b.cand_bank_hash,
          b.umb_bank_hash,

          -- SEGMENTS: reservation math stays in the economic entitlement keyspace,
          -- while stable identifiers are retained only for UI continuity.
          -- Ordinality must be based on the original preview rows (before preview-row reservation subtraction),
          -- otherwise preview_seg:<timesheet_id>:<ord> draft rows will not line up with the rows they reserved.
          coalesce((
            with ss_rows as (
              select
                ss.segment_id,
                ss.segment_key,
                ss.segment_stable_key,
                ss.component_key_type,
                ss.component_key_value,
                ss.work_date,
                ss.ref_num,
                ss.preview_base_eff_delta_ex,
                ss.eff_delta_ex,
                ss.eff_delta_charge_ex_vat,
                ss.source_units,
                ss.source_rate,
                ss.source_charge_rate,
                ss.bucket_row_ord,
                ss.segment_sort_ord,
                row_number() over (
                  partition by ss.timesheet_id
                  order by ss.segment_sort_ord nulls last, ss.bucket_row_ord, ss.component_key_type, ss.component_key_value, ss.segment_id nulls last
                ) as seg_ord
              from segment_status ss
              where ss.timesheet_id = b.timesheet_id
                and ss.preview_base_eff_delta_ex <> 0
            ),
            ss_effective as (
              select
                ssr.segment_id,
                ssr.segment_key,
                ssr.segment_stable_key,
                ssr.component_key_type,
                ssr.component_key_value,
                ssr.work_date,
                ssr.ref_num,
                ssr.eff_delta_charge_ex_vat,
                ssr.source_units,
                ssr.source_rate,
                ssr.source_charge_rate,
                ssr.bucket_row_ord,
                ssr.segment_sort_ord,
                round(
                  ssr.eff_delta_ex - coalesce(rpso.reserved_amount_ex_vat,0),
                  2
                ) as eff_delta_ex_after_reserved
              from ss_rows ssr
              left join reserved_preview_segment_ords rpso
                on rpso.timesheet_id = b.timesheet_id
               and rpso.preview_seg_ord = ssr.seg_ord
            )
            select jsonb_agg(
              jsonb_build_object(
                'segment_id', sse.segment_id,
                'segment_key', sse.segment_key,
                'segment_stable_key', sse.segment_stable_key,
                'component_key_type', sse.component_key_type,
                'component_key_value', sse.component_key_value,
                'work_date', sse.work_date,
                'ref_num', sse.ref_num,
                'delta_pay_ex_vat', sse.eff_delta_ex_after_reserved,
                'delta_charge_ex_vat', sse.eff_delta_charge_ex_vat,
                'source_units', sse.source_units
              )
              order by sse.segment_sort_ord nulls last, sse.bucket_row_ord, sse.component_key_type, sse.component_key_value, sse.segment_id nulls last
            )
            from ss_effective sse
            where sse.eff_delta_ex_after_reserved <> 0
          ), '[]'::jsonb) as segment_deltas_json,

          -- ADDITIONAL (total): outstanding = current - baseline - reserved
          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_additional_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'additional'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_additional_pay_ex_vat,0)
                - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'additional'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_additional_pay_ex_vat,
          round(coalesce(b.current_additional_charge_ex_vat,0) - coalesce(nullif(b.base_json->>'additional_charge_ex_vat','')::numeric,0),2) as delta_additional_charge_ex_vat,

          -- ADDITIONAL (per code): best-effort from additional_units_json + baseline snapshot + reserved breakdowns
          coalesce((
            with
            cur as (
              select
                nullif(btrim(coalesce(e.key,'')), '') as code,
                round(
                  coalesce(
                    nullif(e.value->>'pay_ex_vat','')::numeric,
                    nullif(e.value->>'amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0)
                      * coalesce(nullif(e.value->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(e.value->>'charge_ex_vat','')::numeric, nullif(e.value->>'charge_amount_ex_vat','')::numeric, nullif(e.value->>'charge_amount','')::numeric, (coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0) * coalesce(nullif(e.value->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric) as source_units,
                coalesce(nullif(e.value->>'rate','')::numeric, nullif(e.value->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(e.value->>'charge_rate','')::numeric, nullif(e.value->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_each(case when jsonb_typeof(b.current_additional_units_json) = 'object' then b.current_additional_units_json else '{}'::jsonb end) e
              where jsonb_typeof(coalesce(b.current_additional_units_json,'{}'::jsonb)) = 'object'
                and nullif(btrim(coalesce(e.key,'')), '') is not null
            ),
            cur_arr as (
              select
                nullif(btrim(coalesce(elem->>'code','')),'') as code,
                round(
                  coalesce(
                    nullif(elem->>'pay_ex_vat','')::numeric,
                    nullif(elem->>'amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0)
                      * coalesce(nullif(elem->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(elem->>'charge_ex_vat','')::numeric, nullif(elem->>'charge_amount_ex_vat','')::numeric, nullif(elem->>'charge_amount','')::numeric, (coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0) * coalesce(nullif(elem->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric) as source_units,
                coalesce(nullif(elem->>'rate','')::numeric, nullif(elem->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(elem->>'charge_rate','')::numeric, nullif(elem->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_array_elements(case when jsonb_typeof(b.current_additional_units_json) = 'array' then b.current_additional_units_json else '[]'::jsonb end) elem
              where jsonb_typeof(coalesce(b.current_additional_units_json,'[]'::jsonb)) = 'array'
                and nullif(btrim(coalesce(elem->>'code','')),'') is not null
            ),
            cur_all as (
              select * from cur
              union all
              select * from cur_arr
            ),
            bas as (
              select
                nullif(btrim(coalesce(e.key,'')), '') as code,
                round(
                  coalesce(
                    nullif(e.value->>'pay_ex_vat','')::numeric,
                    nullif(e.value->>'amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount_ex_vat','')::numeric,
                    nullif(e.value->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0)
                      * coalesce(nullif(e.value->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(e.value->>'charge_ex_vat','')::numeric, nullif(e.value->>'charge_amount_ex_vat','')::numeric, nullif(e.value->>'charge_amount','')::numeric, (coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric, 0) * coalesce(nullif(e.value->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(e.value->>'units','')::numeric, nullif(e.value->>'units_week','')::numeric) as source_units,
                coalesce(nullif(e.value->>'rate','')::numeric, nullif(e.value->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(e.value->>'charge_rate','')::numeric, nullif(e.value->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_each(case when jsonb_typeof(b.base_json->'additional_units_json') = 'object' then b.base_json->'additional_units_json' else '{}'::jsonb end) e
              where jsonb_typeof(coalesce(b.base_json->'additional_units_json','{}'::jsonb)) = 'object'
                and nullif(btrim(coalesce(e.key,'')), '') is not null
            ),
            bas_arr as (
              select
                nullif(btrim(coalesce(elem->>'code','')),'') as code,
                round(
                  coalesce(
                    nullif(elem->>'pay_ex_vat','')::numeric,
                    nullif(elem->>'amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount_ex_vat','')::numeric,
                    nullif(elem->>'pay_amount','')::numeric,
                    (
                      coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0)
                      * coalesce(nullif(elem->>'rate','')::numeric, 0)
                    ),
                    0
                  ),
                  2
                ) as amount_ex_vat,
                round(coalesce(nullif(elem->>'charge_ex_vat','')::numeric, nullif(elem->>'charge_amount_ex_vat','')::numeric, nullif(elem->>'charge_amount','')::numeric, (coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric, 0) * coalesce(nullif(elem->>'charge_rate','')::numeric, 0)), 0),2) as charge_amount_ex_vat,
                coalesce(nullif(elem->>'units','')::numeric, nullif(elem->>'units_week','')::numeric) as source_units,
                coalesce(nullif(elem->>'rate','')::numeric, nullif(elem->>'pay_rate','')::numeric) as source_rate,
                coalesce(nullif(elem->>'charge_rate','')::numeric, nullif(elem->>'charge_unit_rate','')::numeric) as source_charge_rate
              from jsonb_array_elements(case when jsonb_typeof(b.base_json->'additional_units_json') = 'array' then b.base_json->'additional_units_json' else '[]'::jsonb end) elem
              where jsonb_typeof(coalesce(b.base_json->'additional_units_json','[]'::jsonb)) = 'array'
                and nullif(btrim(coalesce(elem->>'code','')),'') is not null
            ),
            bas_all as (
              select * from bas
              union all
              select * from bas_arr
            ),
            ids as (
              select distinct
                x.code
              from (
                select code from cur_all where code is not null
                union
                select code from bas_all where code is not null
                union
                select rab.code from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code is not null
              ) x
            ),
            rows as (
              select
                i.code,
                round(
                  coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                  - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0),
                  2
                ) as raw_delta_amount_ex_vat,
                round(
                  coalesce((select sum(ca.charge_amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                  - coalesce((select sum(ba.charge_amount_ex_vat) from bas_all ba where ba.code = i.code),0),
                  2
                ) as raw_delta_charge_ex_vat,
                coalesce((select max(ca.source_units) from cur_all ca where ca.code = i.code),(select max(ba.source_units) from bas_all ba where ba.code = i.code)) as source_units,
                coalesce((select max(ca.source_rate) from cur_all ca where ca.code = i.code),(select max(ba.source_rate) from bas_all ba where ba.code = i.code)) as source_rate,
                coalesce((select max(ca.source_charge_rate) from cur_all ca where ca.code = i.code),(select max(ba.source_charge_rate) from bas_all ba where ba.code = i.code)) as source_charge_rate,
                case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                      - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0)
                      - coalesce((select rab.reserved_amount_ex_vat from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code = i.code limit 1),0),
                      2
                    ) < 0
                  )
                  then 0::numeric
                  else round(
                    coalesce((select sum(ca.amount_ex_vat) from cur_all ca where ca.code = i.code),0)
                    - coalesce((select sum(ba.amount_ex_vat) from bas_all ba where ba.code = i.code),0)
                    - coalesce((select rab.reserved_amount_ex_vat from reserved_additional_by_code rab where rab.timesheet_id = b.timesheet_id and rab.code = i.code limit 1),0),
                    2
                  )
                end as delta_amount_ex_vat
              from ids i
            )
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'code', r.code,
                  'delta_pay_ex_vat', r.delta_amount_ex_vat,
                  'delta_charge_ex_vat', case when coalesce(r.raw_delta_amount_ex_vat,0) = 0 then r.raw_delta_charge_ex_vat else round(r.raw_delta_charge_ex_vat * (r.delta_amount_ex_vat / nullif(r.raw_delta_amount_ex_vat,0)), 2) end,
                  'source_units', r.source_units,
                  'source_rate', r.source_rate,
                  'source_charge_rate', r.source_charge_rate
                )
                order by r.code
              ) filter (where r.delta_amount_ex_vat <> 0),
              '[]'::jsonb
            )
            from rows r
          ), '[]'::jsonb) as additional_unit_deltas_json,

          -- EXPENSES/TRAVEL/etc (outstanding = current - baseline - reserved)
          -- EXPENSES is an aggregate fallback only. If any specific expense bucket
          -- exists in current, baseline, or reserved state, the specific buckets are
          -- the canonical payable components and the aggregate must not also pay out.
          round(
            case
              when (
                coalesce(b.current_travel_pay_ex_vat,0) <> 0
                or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                or coalesce(b.current_other_pay_ex_vat,0) <> 0
                or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                or exists (
                  select 1
                  from reserved_by_source_ref r_specific_expense
                  where r_specific_expense.timesheet_id = b.timesheet_id
                    and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                    and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                )
              )
              then 0
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_expenses_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'expenses'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_expenses_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'expenses'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_expenses_pay_ex_vat,
          round(
            case
              when (
                coalesce(b.current_travel_pay_ex_vat,0) <> 0
                or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                or coalesce(b.current_other_pay_ex_vat,0) <> 0
                or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                or exists (
                  select 1
                  from reserved_by_source_ref r_specific_expense
                  where r_specific_expense.timesheet_id = b.timesheet_id
                    and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                    and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                )
              )
              then 0
              else coalesce(b.current_expenses_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,expenses_charge_ex_vat}','')::numeric,0)
            end,
            2
          ) as delta_expenses_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_travel_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'travel'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_travel_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'travel'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_travel_pay_ex_vat,
          round(coalesce(b.current_travel_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,travel_charge_ex_vat}','')::numeric,0),2) as delta_travel_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_accommodation_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'accommodation'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_accommodation_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'accommodation'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_accommodation_pay_ex_vat,
          round(coalesce(b.current_accommodation_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,accommodation_charge_ex_vat}','')::numeric,0),2) as delta_accommodation_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_other_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'other'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_other_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'other'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_other_pay_ex_vat,
          round(coalesce(b.current_other_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,other_charge_ex_vat}','')::numeric,0),2) as delta_other_charge_ex_vat,

          round(
            case
              when (
                coalesce(b.has_active_overpayment_case,false) = true
                and round(
                  coalesce(b.current_mileage_pay_ex_vat,0)
                  - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = 'mileage'
                      limit 1
                    ), 0),
                  2
                ) < 0
              )
              then 0
              else round(
                coalesce(b.current_mileage_pay_ex_vat,0)
                - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0)
                - coalesce((
                    select r.reserved_amount_ex_vat
                    from reserved_by_source_ref r
                    where r.timesheet_id = b.timesheet_id
                      and r.source_ref = 'mileage'
                    limit 1
                  ), 0),
                2
              )
            end,
            2
          ) as delta_mileage_pay_ex_vat,
          round(coalesce(b.current_mileage_charge_ex_vat,0) - coalesce(nullif(b.base_json #>> '{expenses,mileage_charge_ex_vat}','')::numeric,0),2) as delta_mileage_charge_ex_vat,

          -- ADJUSTMENTS: outstanding = current - baseline - reserved (source_ref='adj:<id>')
          coalesce((
            with
            cur as (
              select
                a.adj_id,
                round(coalesce(a.delta_pay_ex_vat,0),2) as amt
              from adj a
              where a.timesheet_id = b.timesheet_id
            ),
            bas as (
              select
                nullif(btrim(coalesce(x->>'adj_id','')),'')::uuid as adj_id,
                round(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0),2) as amt
              from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
              where nullif(btrim(coalesce(x->>'adj_id','')),'') is not null
            ),
            ids as (
              select distinct adj_id from cur
              union
              select distinct adj_id from bas
            ),
            rows_base as (
              select
                i.adj_id,
                round(
                  coalesce((select c.amt from cur c where c.adj_id = i.adj_id limit 1),0)
                  - coalesce((select x.amt from bas x where x.adj_id = i.adj_id limit 1),0)
                  - coalesce((
                      select r.reserved_amount_ex_vat
                      from reserved_by_source_ref r
                      where r.timesheet_id = b.timesheet_id
                        and r.source_ref = ('adj:'||i.adj_id::text)
                      limit 1
                    ), 0),
                  2
                ) as delta_amt
              from ids i
            ),
            preview_reserved_total as (
              select
                round(
                  coalesce(sum(abs(rpso.reserved_amount_ex_vat)),0),
                  2
                ) as reserved_abs
              from reserved_preview_segment_ords rpso
              where rpso.timesheet_id = b.timesheet_id
                and coalesce(rpso.reserved_amount_ex_vat,0) < 0
            ),
            rows_negative as (
              select
                rb.adj_id,
                rb.delta_amt,
                row_number() over (order by rb.adj_id::text) as neg_ord,
                coalesce(
                  sum(abs(rb.delta_amt)) over (
                    order by rb.adj_id::text
                    rows between unbounded preceding and 1 preceding
                  ),
                  0
                ) as prev_neg_abs
              from rows_base rb
              where rb.delta_amt < 0
            ),
            rows_negative_applied as (
              select
                rn.adj_id,
                round(
                  rn.delta_amt
                  + greatest(
                      least(
                        coalesce(prt.reserved_abs,0) - rn.prev_neg_abs,
                        abs(rn.delta_amt)
                      ),
                      0
                    ),
                  2
                ) as delta_amt
              from rows_negative rn
              cross join preview_reserved_total prt
            ),
            rows as (
              select
                rb.adj_id,
                case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and coalesce(rna.delta_amt, rb.delta_amt) < 0
                  )
                  then 0::numeric
                  else coalesce(rna.delta_amt, rb.delta_amt)
                end as delta_amt
              from rows_base rb
              left join rows_negative_applied rna
                on rna.adj_id = rb.adj_id
            )
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'adj_id', r.adj_id,
                  'delta_pay_ex_vat', r.delta_amt
                )
                order by r.adj_id::text
              ) filter (where r.delta_amt <> 0),
              '[]'::jsonb
            )
            from rows r
          ), '[]'::jsonb) as adjustment_deltas_json,

          -- Reservation integrity (preview-only signal): reserved > remaining previewable truth
          (
            coalesce((
              select rtb.reserved_total_ex_vat
              from reserved_total_by_timesheet rtb
              where rtb.timesheet_id = b.timesheet_id
              limit 1
            ), 0)
            >
            (
              coalesce((
                select round(
                  sum(
                    case
                      when coalesce(ss.raw_delta_before_reservation_ex,0) < 0
                           and coalesce(b.has_active_overpayment_case,false) = true
                        then 0
                      else coalesce(ss.raw_delta_before_reservation_ex,0)
                    end
                  ),
                  2
                )
                from segment_status ss
                where ss.timesheet_id = b.timesheet_id
              ), 0)
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_additional_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_additional_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json->>'additional_pay_ex_vat','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.current_travel_pay_ex_vat,0) <> 0
                    or coalesce(b.current_accommodation_pay_ex_vat,0) <> 0
                    or coalesce(b.current_other_pay_ex_vat,0) <> 0
                    or coalesce(b.current_mileage_pay_ex_vat,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0) <> 0
                    or coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0) <> 0
                    or exists (
                      select 1
                      from reserved_by_source_ref r_specific_expense
                      where r_specific_expense.timesheet_id = b.timesheet_id
                        and r_specific_expense.source_ref in ('travel','accommodation','other','mileage')
                        and coalesce(r_specific_expense.reserved_amount_ex_vat,0) <> 0
                    )
                  )
                  then 0
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_expenses_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_expenses_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_travel_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_travel_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_accommodation_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_accommodation_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_other_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_other_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce(b.current_mileage_pay_ex_vat,0)
                      - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce(b.current_mileage_pay_ex_vat,0)
                    - coalesce(nullif(b.base_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),
                    2
                  )
                end
              + case
                  when (
                    coalesce(b.has_active_overpayment_case,false) = true
                    and round(
                      coalesce((
                        select round(sum(coalesce(a.delta_pay_ex_vat,0)),2)
                        from adj a
                        where a.timesheet_id = b.timesheet_id
                      ),0)
                      - coalesce((
                        select round(sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)),2)
                        from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
                      ),0),
                      2
                    ) < 0
                  )
                  then 0
                  else round(
                    coalesce((
                      select round(sum(coalesce(a.delta_pay_ex_vat,0)),2)
                      from adj a
                      where a.timesheet_id = b.timesheet_id
                    ),0)
                    - coalesce((
                      select round(sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)),2)
                      from jsonb_array_elements(coalesce(b.base_json->'adjustments','[]'::jsonb)) x
                    ),0),
                    2
                  )
                end
            ) + 0.01
          ) as reservation_overrun_detected
        from ts_baseline b
  
  ;

  create temporary table ts_itemised on commit drop as
        select
          d2.*,
          d2.total_ex as payment_amount_ex_vat,
          round(
            case
              when d2.ts_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(d2.total_ex, v_vat_rate_pct, d2.umb_vat_chargeable)->>'inc')::numeric
              else d2.total_ex
            end,
            2
          ) as payment_amount_inc_vat,
          round(
            case
              when d2.ts_pay_method = 'UMBRELLA' then
                (public._pay_umbrella_vat_calc(d2.total_ex, v_vat_rate_pct, d2.umb_vat_chargeable)->>'inc')::numeric
              else d2.total_ex
            end,
            2
          ) as payment_amount
        from (
          select
            d_calc.*,
            round(coalesce(d_calc.taxable_total_ex,0) + coalesce(d_calc.reimbursement_total_ex,0), 2) as total_ex
          from (
            select
              d1.*,
              round(
                coalesce((select sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)) from jsonb_array_elements(d1.segment_deltas_json) x),0)
                + coalesce(d1.delta_additional_pay_ex_vat,0)
                + coalesce((select sum(coalesce(nullif(x->>'delta_pay_ex_vat','')::numeric,0)) from jsonb_array_elements(d1.adjustment_deltas_json) x),0),
                2
              ) as taxable_total_ex,
              round(
                coalesce(d1.delta_expenses_pay_ex_vat,0)
                + coalesce(d1.delta_travel_pay_ex_vat,0)
                + coalesce(d1.delta_accommodation_pay_ex_vat,0)
                + coalesce(d1.delta_other_pay_ex_vat,0)
                + coalesce(d1.delta_mileage_pay_ex_vat,0),
                2
              ) as reimbursement_total_ex
            from ts_deltas d1
          ) d_calc
        ) d2
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'segment_status_count', (select count(*)::int from segment_status),
    'blocked_item_count', (select count(*)::int from blocked_items),
    'do_not_pay_item_count', (select count(*)::int from do_not_pay_items),
    'timesheet_delta_count', (select count(*)::int from ts_deltas),
    'timesheet_itemised_count', (select count(*)::int from ts_itemised)
  );
end;
$function$;







CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_finance_case_baseline(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_START',
    jsonb_build_object(
      'candidate_id', p_candidate_id,
      'context_pay_date', p_context_json->>'pay_date',
      'context_pay_week_start', p_context_json->>'pay_week_start'
    ),
    'pay_preview_finance',
    COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.cand_payee') is null then
    perform public.pay_preview_candidate_build_payee_baseline(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_taxable_channel_restructure_resolution, pg_temp.finance_case_resolution_rollup;

  create temporary table finance_case_repaid_wtd on commit drop as
        select
          nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid as finance_case_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as repaid_wtd_ex
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        left join public.pay_bank_transfers pbt
          on pbt.id = pbi.pay_bank_transfer_id
        where coalesce(pbi.is_voided, false) = false
          and pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
          and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
          and pbi.repayment_week_start = v_week_start
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
          and not exists (
            select 1
            from public.pay_payment_correction_items pci_repaid_wtd
            where pci_repaid_wtd.pay_batch_item_id = pbi.id
              and pci_repaid_wtd.status = 'APPLIED'
              and pci_repaid_wtd.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
            or upper(btrim(coalesce(pbt.status, ''))) = 'COMPLETED'
            or pbt.completed_at_utc is not null
            or exists (
              select 1
              from public.pay_advance_reservations par_repaid_wtd
              where par_repaid_wtd.pay_batch_item_id = pbi.id
                and (
                  upper(btrim(coalesce(par_repaid_wtd.status, ''))) = 'SETTLED'
                  or par_repaid_wtd.settled_at_utc is not null
                )
            )
          )
        group by nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid

  ;


create temporary table finance_case_recovery_rows_base on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          upper(coalesce(cr.cand_pay_method,'')) as candidate_pay_method,
          round(greatest(coalesce(cr.non_mismatch_total_ex,0),0),2)::numeric(12,2) as run_earnings_headroom_ex,
          round(
            greatest(
              coalesce(pwb.paid_wtd_before,0)
              + greatest(coalesce(cr.non_mismatch_total_ex,0),0),
              0
            ),
            2
          )::numeric(12,2) as run_take_home_before,
          round(greatest(coalesce(c.min_take_home_wtd,0),0),2)::numeric(12,2) as default_take_home_floor,
          vfcr.payout_status,
          vfcr.created_at,
          case
            when vfcr.minimum_earnings_threshold is null then null::numeric(12,2)
            else round(greatest(vfcr.minimum_earnings_threshold,0),2)::numeric(12,2)
          end as minimum_earnings_threshold,
          case
            when vfcr.take_home_floor_override is null then null::numeric(12,2)
            else round(greatest(vfcr.take_home_floor_override,0),2)::numeric(12,2)
          end as take_home_floor_override,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE'
                 and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
                then least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                     - coalesce(fcrw.repaid_wtd_ex,0)
                     - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                when vfcr.case_type = 'OVERPAYMENT'
                then greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                else 0::numeric
              end,
              0::numeric
            ),
            2
          )::numeric(12,2) as nominal_due_amount
        from finance_case_baseline_scope vfcr
        join candidate_rollup cr
          on cr.candidate_id = vfcr.candidate_id
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join paid_wtd_before pwb
          on pwb.candidate_id = vfcr.candidate_id
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        where vfcr.case_type in ('PAYMENT_ADVANCE','MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          and (
            (vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID')
            or vfcr.case_type in ('MANUAL_DEBT_ADJUSTMENT','OVERPAYMENT')
          )
  
  ;

  create temporary table manual_debt_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'MANUAL_DEBT_ADJUSTMENT'
          and fcrrb.nominal_due_amount > 0
  
  ;

  create temporary table manual_debt_recovery_allocations on commit drop as
        select
          mdra.candidate_id,
          mdra_alloc.finance_case_id,
          round(coalesce(mdra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            mdrr.candidate_id,
            max(mdrr.run_earnings_headroom_ex) as run_earnings_headroom_ex,
            max(mdrr.run_take_home_before) as run_take_home_before,
            max(mdrr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', mdrr.sort_order,
                'finance_case_id', mdrr.finance_case_id::text,
                'case_type', mdrr.case_type::text,
                'payout_status', case when mdrr.payout_status is null then null else mdrr.payout_status::text end,
                'nominal_due_amount', mdrr.nominal_due_amount,
                'minimum_earnings_threshold', mdrr.minimum_earnings_threshold,
                'take_home_floor_override', mdrr.take_home_floor_override
              )
              order by mdrr.sort_order, mdrr.finance_case_id
            ) as recovery_rows_json
          from manual_debt_recovery_rows mdrr
          group by mdrr.candidate_id
        ) mdra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => mdra.recovery_rows_json,
          p_run_earnings_headroom => mdra.run_earnings_headroom_ex,
          p_run_take_home_headroom => mdra.run_take_home_before,
          p_default_take_home_floor => mdra.default_take_home_floor
        ) mdra_alloc
  
  ;

  create temporary table manual_debt_recovery_totals on commit drop as
        select
          mdra.candidate_id,
          round(sum(mdra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from manual_debt_recovery_allocations mdra
        group by mdra.candidate_id
  
  ;

  create temporary table overpayment_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          fcrrb.default_take_home_floor,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'OVERPAYMENT'
          and fcrrb.nominal_due_amount > 0
  
  ;

  create temporary table overpayment_recovery_allocations on commit drop as
        select
          opra.candidate_id,
          opra_alloc.finance_case_id,
          round(coalesce(opra_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            oprr.candidate_id,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when oprr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      oprr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else oprr.run_take_home_before
              end
            ) as run_take_home_before,
            max(oprr.default_take_home_floor) as default_take_home_floor,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', oprr.sort_order,
                'finance_case_id', oprr.finance_case_id::text,
                'case_type', 'MANUAL_DEBT_ADJUSTMENT',
                'payout_status', null,
                'nominal_due_amount', oprr.nominal_due_amount,
                'minimum_earnings_threshold', oprr.minimum_earnings_threshold,
                'take_home_floor_override', oprr.take_home_floor_override
              )
              order by oprr.sort_order, oprr.finance_case_id
            ) as recovery_rows_json
          from overpayment_recovery_rows oprr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = oprr.candidate_id
          group by oprr.candidate_id
        ) opra
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => opra.recovery_rows_json,
          p_run_earnings_headroom => opra.run_earnings_headroom_ex,
          p_run_take_home_headroom => opra.run_take_home_before,
          p_default_take_home_floor => opra.default_take_home_floor
        ) opra_alloc
  
  ;

  create temporary table overpayment_recovery_totals on commit drop as
        select
          opra.candidate_id,
          round(sum(opra.protected_recoverable_amount),2)::numeric(12,2) as protected_recoverable_total
        from overpayment_recovery_allocations opra
        group by opra.candidate_id
  
  ;

  create temporary table payment_advance_recovery_rows on commit drop as
        select
          fcrrb.candidate_id,
          fcrrb.candidate_pay_method,
          fcrrb.finance_case_id,
          fcrrb.case_type,
          fcrrb.payout_status,
          fcrrb.nominal_due_amount,
          fcrrb.minimum_earnings_threshold,
          fcrrb.take_home_floor_override,
          fcrrb.run_earnings_headroom_ex,
          fcrrb.run_take_home_before,
          row_number() over (
            partition by fcrrb.candidate_id
            order by fcrrb.created_at, fcrrb.finance_case_id
          )::integer as sort_order
        from finance_case_recovery_rows_base fcrrb
        where fcrrb.case_type = 'PAYMENT_ADVANCE'
          and upper(coalesce(fcrrb.payout_status::text,'')) = 'PAID'
          and fcrrb.nominal_due_amount > 0
  
  ;

  create temporary table payment_advance_recovery_allocations on commit drop as
        select
          para.candidate_id,
          para_alloc.finance_case_id,
          round(coalesce(para_alloc.protected_recoverable_amount,0),2)::numeric(12,2) as protected_recoverable_amount
        from (
          select
            parr.candidate_id,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_earnings_headroom_ex - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_earnings_headroom_ex
              end
            ) as run_earnings_headroom_ex,
            max(
              case
                when parr.candidate_pay_method = 'UMBRELLA'
                  then round(
                    greatest(
                      parr.run_take_home_before - coalesce(mdrt.protected_recoverable_total,0) - coalesce(oprt.protected_recoverable_total,0),
                      0
                    ),
                    2
                  )::numeric(12,2)
                else parr.run_take_home_before
              end
            ) as run_take_home_before,
            jsonb_agg(
              jsonb_build_object(
                'sort_order', parr.sort_order,
                'finance_case_id', parr.finance_case_id::text,
                'case_type', parr.case_type::text,
                'payout_status', case when parr.payout_status is null then null else parr.payout_status::text end,
                'nominal_due_amount', parr.nominal_due_amount,
                'minimum_earnings_threshold', parr.minimum_earnings_threshold,
                'take_home_floor_override', parr.take_home_floor_override
              )
              order by parr.sort_order, parr.finance_case_id
            ) as recovery_rows_json
          from payment_advance_recovery_rows parr
          left join manual_debt_recovery_totals mdrt
            on mdrt.candidate_id = parr.candidate_id
          left join overpayment_recovery_totals oprt
            on oprt.candidate_id = parr.candidate_id
          group by parr.candidate_id
        ) para
        cross join lateral public._pay_finance_protected_recovery_allocate(
          p_recovery_rows => para.recovery_rows_json,
          p_run_earnings_headroom => para.run_earnings_headroom_ex,
          p_run_take_home_headroom => para.run_take_home_before,
          p_default_take_home_floor => null::numeric
        ) para_alloc
  
  ;

  create temporary table finance_case_protected_allocations on commit drop as
        select
          mdra.finance_case_id,
          mdra.protected_recoverable_amount
        from manual_debt_recovery_allocations mdra

        union all

        select
          opra.finance_case_id,
          opra.protected_recoverable_amount
        from overpayment_recovery_allocations opra

        union all

        select
          para.finance_case_id,
          para.protected_recoverable_amount
        from payment_advance_recovery_allocations para
  
  ;

  create temporary table finance_case_payee_readiness on commit drop as
        select
          f0.finance_case_id,
          f0.payee_entity_kind,
          f0.payee_entity_id,
          f0.bank_details_hash,
          f0.beneficiary_name,
          f0.sort_code,
          f0.account_number,
          case
            when f0.account_number is null or btrim(coalesce(f0.account_number,'')) = '' then null
            else lpad(right(f0.account_number, 4), greatest(length(f0.account_number), 4), '*')
          end as masked_bank_account,
          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash) as name_check_has_override,
          (bpm.payee_id is not null) as payee_map_present,
          (
            f0.payee_entity_id is null
            or f0.bank_details_hash is null
            or btrim(coalesce(f0.bank_details_hash,'')) = ''
            or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
            or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
            or nullif(btrim(coalesce(f0.account_number,'')), '') is null
          ) as is_missing_bank_details,
          (
            v_need_name_check = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
          ) as is_name_check_blocked,
          (
            v_requires_payee_map = true
            and not (
              f0.payee_entity_id is null
              or f0.bank_details_hash is null
              or btrim(coalesce(f0.bank_details_hash,'')) = ''
              or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
              or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
              or nullif(btrim(coalesce(f0.account_number,'')), '') is null
            )
            and bpm.payee_id is null
          ) as is_payee_map_blocked,
          (
            (case
              when (
                f0.payee_entity_id is null
                or f0.bank_details_hash is null
                or btrim(coalesce(f0.bank_details_hash,'')) = ''
                or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                or nullif(btrim(coalesce(f0.account_number,'')), '') is null
              )
              then jsonb_build_array('BLOCKED_BANK_DETAILS')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_need_name_check = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
                and not (bnc.override_reason is not null and bnc.override_hash = f0.bank_details_hash)
              )
              then jsonb_build_array('BLOCKED_NAME_CHECK')
              else '[]'::jsonb
            end)
            ||
            (case
              when (
                v_requires_payee_map = true
                and not (
                  f0.payee_entity_id is null
                  or f0.bank_details_hash is null
                  or btrim(coalesce(f0.bank_details_hash,'')) = ''
                  or nullif(btrim(coalesce(f0.beneficiary_name,'')), '') is null
                  or nullif(btrim(coalesce(f0.sort_code,'')), '') is null
                  or nullif(btrim(coalesce(f0.account_number,'')), '') is null
                )
                and bpm.payee_id is null
              )
              then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes
        from (
          select
            vfcr.finance_case_id,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
              else 'CANDIDATE'
            end as payee_entity_kind,
            case
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c.umbrella_id
              else vfcr.candidate_id
            end as payee_entity_id,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.bank_details_hash
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.bank_details_hash
              else c.bank_details_hash
            end as bank_details_hash,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.beneficiary_name
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.name
              else coalesce(c.account_holder, c.display_name)
            end as beneficiary_name,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.sort_code
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.sort_code
              else c.sort_code
            end as sort_code,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then obd.account_number
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then u.account_number
              else c.account_number
            end as account_number
          from finance_case_baseline_scope vfcr
          join public.candidates c
            on c.id = vfcr.candidate_id
          left join public.umbrellas u
            on u.id = c.umbrella_id
          left join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
        ) f0
        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = f0.payee_entity_kind
         and bnc.entity_id = f0.payee_entity_id
         and bnc.bank_details_hash is not distinct from f0.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = f0.payee_entity_kind
         and bpm.entity_id = f0.payee_entity_id
         and bpm.bank_details_hash is not distinct from f0.bank_details_hash
  
  ;

  create temporary table finance_case_component_rows on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          vfcr.taxability,
          pfc.id as finance_component_id,
          pfc.source_family_key,
          pfc.component_key_type,
          pfc.component_key_value,
          pfc.classification,
          upper(coalesce(pfc.source_pay_method, '')) as source_pay_method,
          upper(coalesce(cp.cand_pay_method, '')) as current_target_pay_method,
          cp.umb_vat_chargeable,
          pfc.source_basis_json,
          round(coalesce(pfc.source_amount, 0), 2) as source_amount,
          round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_source_amount,
          pfc.saved_target_pay_method,
          pfc.saved_resolution_mode,
          pfc.saved_resolution_payload_json,
          pfc.saved_resolution_result_json,
          pfc.resolution_fingerprint,
          pfc.is_resolution_stale,
          pfc.stale_reason,
          public.pay_finance_component_fingerprint(
            pfc.source_family_key,
            pfc.component_key_type,
            pfc.component_key_value,
            pfc.classification,
            upper(coalesce(pfc.source_pay_method, '')),
            upper(coalesce(cp.cand_pay_method, '')),
            coalesce(pfc.source_basis_json, '{}'::jsonb),
            round(coalesce(pfc.source_amount, 0), 2),
            case
              when coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
                then coalesce(pfc.saved_resolution_payload_json->>'relevant_erni_pct', pfc.saved_resolution_result_json->>'relevant_erni_pct')::numeric
              else v_erni_pct
            end,
            coalesce(pfc.saved_resolution_payload_json, pfc.saved_resolution_result_json, '{}'::jsonb)
          ) as current_component_fingerprint
        from finance_case_baseline_scope vfcr
        join cand_payee cp
          on cp.candidate_id = vfcr.candidate_id
        join public.pay_finance_case_components pfc
          on pfc.finance_case_id = vfcr.finance_case_id
         and pfc.closed_at_utc is null
         and coalesce(pfc.remaining_source_amount, 0) > 0
  
  ;

  create temporary table finance_case_component_review_rows on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          nullif(fccr.source_basis_json->>'source_units','')::numeric as source_units,
          nullif(fccr.source_basis_json->>'source_rate','')::numeric as source_rate,
          nullif(fccr.source_basis_json->>'source_charge_rate','')::numeric as source_charge_rate,
          coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) as source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'REUSABLE_SAVED_RESOLUTION'
            when fccr.saved_resolution_mode is not null then 'STALE_SAVED_RESOLUTION'
            else 'FRESH_SUGGESTION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
            and fccr.saved_resolution_mode is null
          ) as is_fresh_suggested_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and coalesce(fccr.is_resolution_stale,false) = false
            and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,''))
            and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
          ) as is_reusable_saved_resolution,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.saved_resolution_mode is not null
            and (
              coalesce(fccr.is_resolution_stale,false) = true
              or upper(coalesce(fccr.saved_target_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              or (fccr.resolution_fingerprint is not null and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint)
            )
          ) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_payload_json
            else jsonb_strip_nulls(jsonb_build_object(
              'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
              'target_pay_method', fccr.current_target_pay_method,
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'suggested_target_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
            ))
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint)
              then fccr.saved_resolution_result_json
            else jsonb_strip_nulls(jsonb_build_object(
              'target_pay_method', fccr.current_target_pay_method,
              'target_amount_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_amount_vat', round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2),
              'target_amount_inc_vat', round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2),
              'basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'applied_basis_source_amount_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'relevant_erni_pct', round(v_erni_pct,6),
              'vat_rate_pct', round(v_vat_rate_pct,6),
              'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
              'target_units', case when nullif(fccr.source_basis_json->>'source_units','') is not null then round(nullif(fccr.source_basis_json->>'source_units','')::numeric,6) else null end,
              'replacement_rate', case when nullif(fccr.source_basis_json->>'source_units','') is not null and nullif(fccr.source_basis_json->>'source_units','')::numeric <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / (nullif(fccr.source_basis_json->>'source_units','')::numeric), 2) else null end,
              'target_amount_ex_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'vat')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_amount_inc_vat_per_source_ex_vat', case when coalesce(fccr.source_amount,0) <> 0 then round(round(coalesce((fcsr.target_amounts_json->>'inc')::numeric,0),2) / fccr.source_amount, 10) else null end,
              'target_units_per_source_ex_vat', case when nullif(fccr.source_basis_json->>'source_units','') is not null and coalesce(fccr.source_amount,0) <> 0 then round((nullif(fccr.source_basis_json->>'source_units','')::numeric) / fccr.source_amount, 10) else null end,
              'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
              'source_pay_ex_vat', round(coalesce(fccr.source_amount,0),2),
              'source_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'source_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - fccr.source_amount,2) end,
              'target_pay_ex_vat', round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),
              'target_charge_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric),2) end,
              'target_margin_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end,
              'margin_delta_ex_vat', case when coalesce(nullif(fccr.source_basis_json->>'source_charge_ex_vat','')::numeric, nullif(fccr.saved_resolution_result_json->>'source_charge_ex_vat','')::numeric) is null or fcsr.target_amounts_json is null then null else round(fccr.source_amount - round(coalesce((fcsr.target_amounts_json->>'ex')::numeric,0),2),2) end
            ))
          end as suggested_resolution_result_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when fccr.saved_resolution_mode is not null and coalesce(fccr.is_resolution_stale,false) = false and upper(coalesce(fccr.saved_target_pay_method,'')) = upper(coalesce(fccr.current_target_pay_method,'')) and (fccr.resolution_fingerprint is null or fccr.resolution_fingerprint is not distinct from fccr.current_component_fingerprint) then 'This component already has a reusable saved resolution for the current target pay method.'
            when fccr.saved_resolution_mode is not null then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.source_pay_method <> fccr.current_target_pay_method then 'This suggestion converts the taxable component to a target-side equivalent while leaving fixed reimbursements unchanged.'
            else 'This suggestion preserves equivalent basis using the current target pay method.'
          end as suggestion_explanation_text
        from finance_case_component_rows fccr
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then public._pay_convert_paye_to_umbrella(fccr.source_amount, v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct), 'vat', 0, 'inc', public._pay_convert_umbrella_to_paye_ex(fccr.source_amount, v_erni_pct))
              when fccr.current_target_pay_method = 'PAYE' then jsonb_build_object('ex', round(coalesce(fccr.source_amount,0),2), 'vat', 0, 'inc', round(coalesce(fccr.source_amount,0),2))
              when fccr.current_target_pay_method = 'UMBRELLA' then public._pay_umbrella_vat_calc(fccr.source_amount, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else null::jsonb
            end as target_amounts_json
        ) fcsr on true
  
  ;

  create temporary table finance_case_component_review_rows_effective on commit drop as
        select
          fccr.finance_case_id,
          fccr.candidate_id,
          fccr.case_type,
          fccr.taxability,
          fccr.finance_component_id,
          fccr.source_family_key,
          fccr.component_key_type,
          fccr.component_key_value,
          fccr.classification,
          fccr.source_pay_method,
          fccr.current_target_pay_method,
          fccr.umb_vat_chargeable,
          fccr.source_basis_json,
          fccr.source_amount,
          fccr.remaining_source_amount,
          fccr.source_units,
          fccr.source_rate,
          fccr.source_charge_rate,
          fccr.source_charge_ex_vat,
          fccr.saved_target_pay_method,
          fccr.saved_resolution_mode,
          fccr.saved_resolution_payload_json,
          fccr.saved_resolution_result_json,
          fccr.resolution_fingerprint,
          fccr.is_resolution_stale,
          fccr.stale_reason,
          fccr.current_component_fingerprint,
          fctx.is_actionable_bucket_resolution as is_actionable_resolution_row,
          fctx.is_fixed_taxable_conversion as is_fixed_no_action_taxable_row,
          null::text as approved_resolution_mode,
          null::numeric as approved_target_rate,
          null::text as approved_nonbucket_resolution_mode,
          null::numeric as approved_nonbucket_target_amount_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then false
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then false
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then not (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then false
            when fctx.is_actionable_bucket_resolution = true then true
            else false
          end as requires_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then true
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then true
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then (coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false)
            when fctx.is_actionable_bucket_resolution = true and coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then true
            when fctx.is_actionable_bucket_resolution = true then false
            else true
          end as case_resolution_satisfied_now_component,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and fccr.source_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
            and fccr.current_target_pay_method <> ''
          ) as has_suggested_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'NO_SUGGESTION_AVAILABLE'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'NO_SUGGESTION_AVAILABLE'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'REUSABLE_SAVED_RESOLUTION'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'STALE_SAVED_RESOLUTION'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'FRESH_SUGGESTION'
            when fctx.is_actionable_bucket_resolution = true then 'FRESH_SUGGESTION'
            else 'NO_ACTION_FIXED_CONVERSION'
          end as suggestion_provenance,
          (
            fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
            and coalesce(fccr.is_reusable_saved_resolution,false) = false
            and coalesce(fccr.is_stale_saved_resolution,false) = false
            and (
              fctx.is_actionable_bucket_resolution = true
              or fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT'
            )
          ) as is_fresh_suggested_resolution,
          coalesce(fccr.is_reusable_saved_resolution,false) as is_reusable_saved_resolution,
          coalesce(fccr.is_stale_saved_resolution,false) as is_stale_saved_resolution,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_payload_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'resolution_mode', 'SUGGESTED_EQUIVALENT_BASIS',
                'target_pay_method', fccr.current_target_pay_method,
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'suggested_target_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
              )
            )
            else fccr.suggested_resolution_payload_json
          end as suggested_resolution_payload_json,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then null::jsonb
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then fccr.saved_resolution_result_json
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            when fctx.is_actionable_bucket_resolution = true or fctx.is_fixed_taxable_conversion = true or upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,'')) then jsonb_strip_nulls(
              jsonb_build_object(
                'target_pay_method', fccr.current_target_pay_method,
                'target_amount_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_amount_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric, 0),2),
                'target_amount_inc_vat', round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2),
                'basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'applied_basis_source_amount_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'relevant_erni_pct', round(v_erni_pct,6),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'umbrella_vat_chargeable', coalesce(fccr.umb_vat_chargeable,false),
                'target_units', case when fccr.source_units is not null then round(fccr.source_units,6) else null end,
                'replacement_rate', case when fctx.is_actionable_bucket_resolution = true and fbase.suggested_target_rate is not null then round(fbase.suggested_target_rate,2) else null end,
                'target_amount_ex_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'vat','')::numeric,0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_amount_inc_vat_per_source_ex_vat', case when round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(round(coalesce(nullif(fbase_amounts.suggested_target_amounts_json->>'inc','')::numeric, coalesce(fbase.suggested_target_pay_ex_vat, 0), 0),2) / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'target_units_per_source_ex_vat', case when fccr.source_units is not null and round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) <> 0 then round(fccr.source_units / round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), 10) else null end,
                'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT',
                'source_pay_ex_vat', round(coalesce(fbasis.basis_source_amount_ex_vat,0),2),
                'source_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'source_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end,
                'target_pay_ex_vat', round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),
                'target_charge_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end,
                'target_margin_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end,
                'margin_delta_ex_vat', case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.basis_source_amount_ex_vat - round(coalesce(fbase.suggested_target_pay_ex_vat, 0),2),2) end
              )
            )
            else fccr.suggested_resolution_result_json
          end as suggested_resolution_result_json,
          round(coalesce(fbasis.basis_source_amount_ex_vat,0),2) as source_pay_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat,2) end as source_charge_component_ex_vat,
          case when fbasis.source_charge_basis_ex_vat is null then null else round(fbasis.source_charge_basis_ex_vat - fbasis.basis_source_amount_ex_vat,2) end as source_margin_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
            else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
          end as target_pay_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null then round(fbasis.source_charge_basis_ex_vat,2)
            else null::numeric
          end as target_charge_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.source_charge_basis_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as target_margin_ex_vat,
          case
            when fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and fbasis.source_charge_basis_ex_vat is not null
              then round(
                fbasis.basis_source_amount_ex_vat - case
                  when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
                  when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false and fsaved.reusable_saved_target_pay_ex_vat is not null then round(fsaved.reusable_saved_target_pay_ex_vat,2)
                  else round(coalesce(fbase.suggested_target_pay_ex_vat, fbasis.basis_source_amount_ex_vat, 0),2)
                end,
                2
              )
            else null::numeric
          end as margin_delta_ex_vat,
          case
            when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Fixed reimbursements are not channel-converted and do not participate in suggested-rates review.'
            when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then 'No suggested rates are required because this taxable component already aligns with the current target pay method.'
            when coalesce(fccr.is_reusable_saved_resolution,false) = true and coalesce(fccr.is_stale_saved_resolution,false) = false then 'This component already has a reusable saved resolution for the current target pay method.'
            when coalesce(fccr.is_stale_saved_resolution,false) = true then 'A stale saved resolution exists for this component. The suggested rates below reflect the current target pay method.'
            when fccr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'This non-bucket finance case resolves as one suggested/editable gross total. The total remaining source amount is converted onto the current target pay method.'
            when fctx.is_fixed_taxable_conversion = true then 'This taxable row does not expose a per-unit rate edit. It remains visible as a fixed no-action row and is converted deterministically onto the current target pay method.'
            else 'This suggestion converts the taxable component to a target-side equivalent while keeping units fixed, charge fixed, and margin constant except for unavoidable penny balancing.'
          end as suggestion_explanation_text
        from finance_case_component_review_rows fccr
        left join lateral (
          select
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and fccr.source_units is not null
              and coalesce(fccr.source_units,0) <> 0
              and fccr.source_rate is not null
              and fccr.source_charge_rate is not null
              and fccr.component_key_type <> 'ADJUSTMENT_CODE'
    and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
            ) as is_actionable_bucket_resolution,
            (
              fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and fccr.source_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method in ('PAYE','UMBRELLA')
              and fccr.current_target_pay_method <> ''
              and upper(coalesce(fccr.source_pay_method,'')) is distinct from upper(coalesce(fccr.current_target_pay_method,''))
              and not (
                fccr.source_units is not null
                and coalesce(fccr.source_units,0) <> 0
                and fccr.source_rate is not null
                and fccr.source_charge_rate is not null
                and fccr.component_key_type <> 'ADJUSTMENT_CODE'
                and fccr.case_type <> 'MANUAL_DEBT_ADJUSTMENT'
              )
            ) as is_fixed_taxable_conversion
        ) fctx on true
        left join lateral (
          select
            round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0), 2) as basis_source_amount_ex_vat,
            case
              when fccr.source_charge_ex_vat is null then null::numeric
              when round(coalesce(fccr.source_amount,0),2) = 0 then round(coalesce(fccr.source_charge_ex_vat,0),2)
              else round(round(coalesce(fccr.source_charge_ex_vat,0),2) * (round(coalesce(fccr.remaining_source_amount, fccr.source_amount, 0),2) / nullif(round(coalesce(fccr.source_amount,0),2),0)), 2)
            end as source_charge_basis_ex_vat
        ) fbasis on true
        left join lateral (
          select
            case
              when fccr.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when upper(coalesce(fccr.source_pay_method,'')) is not distinct from upper(coalesce(fccr.current_target_pay_method,'')) then round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
              when fccr.source_pay_method = 'PAYE' and fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_convert_paye_to_umbrella(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct, v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              when fccr.source_pay_method = 'UMBRELLA' and fccr.current_target_pay_method = 'PAYE' then round(public._pay_convert_umbrella_to_paye_ex(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_erni_pct),2)
              when fccr.current_target_pay_method = 'UMBRELLA' then round((public._pay_umbrella_vat_calc(round(coalesce(fbasis.basis_source_amount_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))->>'ex')::numeric,2)
              else round(coalesce(fbasis.basis_source_amount_ex_vat,0),2)
            end as target_ex_before_rate
        ) fbase_pre on true
        left join lateral (
          select
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(fbase_pre.target_ex_before_rate / fccr.source_units, 2)
              else null::numeric
            end as suggested_target_rate,
            case
              when fctx.is_actionable_bucket_resolution = true and fccr.source_units is not null and fccr.source_units <> 0
                then round(round(fbase_pre.target_ex_before_rate / fccr.source_units, 2) * fccr.source_units, 2)
              else round(fbase_pre.target_ex_before_rate, 2)
            end as suggested_target_pay_ex_vat
        ) fbase on true
        left join lateral (
          select
            case
              when fbase.suggested_target_pay_ex_vat is null then null::jsonb
              when upper(coalesce(fccr.current_target_pay_method,'')) = 'UMBRELLA' then public._pay_umbrella_vat_calc(round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), v_vat_rate_pct, coalesce(fccr.umb_vat_chargeable,false))
              else jsonb_build_object('ex', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2), 'vat', 0, 'inc', round(coalesce(fbase.suggested_target_pay_ex_vat,0),2))
            end as suggested_target_amounts_json
        ) fbase_amounts on true
        left join lateral (
          select
            case
              when coalesce(fccr.is_reusable_saved_resolution,false) = true
               and coalesce(fccr.is_stale_saved_resolution,false) = false
               and coalesce(fccr.saved_resolution_result_json->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
              then round((fccr.saved_resolution_result_json->>'target_amount_ex_vat')::numeric, 2)
              else null::numeric
            end as reusable_saved_target_pay_ex_vat
        ) fsaved on true
  
  ;

  create temporary table finance_case_due_source_amounts on commit drop as
        select
          vfcr.finance_case_id,
          vfcr.candidate_id,
          vfcr.case_type,
          round(
            greatest(
              case
                when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'PAYMENT_ADVANCE' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                when vfcr.case_type = 'OVERPAYMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  greatest(coalesce(vfcr.outstanding_amount,0) - coalesce(vfcr.active_reserved_amount,0), 0)
                )
                when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(
                  fcpa.protected_recoverable_amount,
                  least(coalesce(vfcr.weekly_due,0), coalesce(vfcr.outstanding_amount,0))
                  - coalesce(fcrw.repaid_wtd_ex,0)
                  - greatest(coalesce(vfcr.active_reserved_amount,0) - coalesce(fcrw.repaid_wtd_ex,0), 0)
                )
                when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then case
                  when vfcr.lifecycle_status_display in ('Paid','Cancelled') then 0::numeric
                  else coalesce(vfcr.original_amount,0) - coalesce(vfcr.active_reserved_amount,0)
                end
                else 0::numeric
              end,
              0::numeric
            ),
            2
          ) as due_source_amount_ex_vat
        from finance_case_baseline_scope vfcr
        left join finance_case_repaid_wtd fcrw
          on fcrw.finance_case_id = vfcr.finance_case_id
        left join finance_case_protected_allocations fcpa
          on fcpa.finance_case_id = vfcr.finance_case_id
        where vfcr.finance_case_id is not null
  
  ;

  create temporary table finance_case_component_due_source_base on commit drop as
        select
          fce.finance_case_id,
          fce.candidate_id,
          fce.case_type,
          fce.taxability,
          fce.finance_component_id,
          round(coalesce(fce.remaining_source_amount,0),2) as remaining_source_amount,
          round(coalesce(fcds.due_source_amount_ex_vat,0),2) as due_source_amount_ex_vat,
          round(sum(coalesce(fce.remaining_source_amount,0)) over (partition by fce.finance_case_id),2) as total_remaining_source_amount,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count
        from finance_case_component_review_rows_effective fce
        join finance_case_due_source_amounts fcds
          on fcds.finance_case_id = fce.finance_case_id
  
  ;

  create temporary table finance_case_component_due_source_shares on commit drop as
        select
          fcdsb.*,
          round(
            case
              when coalesce(fcdsb.due_source_amount_ex_vat,0) = 0 then 0::numeric
              when coalesce(fcdsb.total_remaining_source_amount,0) = 0 then 0::numeric
              when fcdsb.component_count = 1 then fcdsb.due_source_amount_ex_vat
              when fcdsb.component_ord < fcdsb.component_count then (fcdsb.due_source_amount_ex_vat * fcdsb.remaining_source_amount / nullif(fcdsb.total_remaining_source_amount,0))
              else 0::numeric
            end,
            2
          ) as preliminary_source_due_amount_ex_vat
        from finance_case_component_due_source_base fcdsb
  
  ;

  create temporary table finance_case_component_due_source_allocations on commit drop as
        select
          fcdss.finance_case_id,
          fcdss.finance_component_id,
          round(
            case
              when fcdss.component_count = 1 then fcdss.due_source_amount_ex_vat
              when fcdss.component_ord < fcdss.component_count then fcdss.preliminary_source_due_amount_ex_vat
              else fcdss.due_source_amount_ex_vat - coalesce(sum(fcdss.preliminary_source_due_amount_ex_vat) over (partition by fcdss.finance_case_id order by fcdss.component_ord rows between unbounded preceding and 1 preceding), 0)
            end,
            2
          ) as allocated_source_due_amount_ex_vat
        from finance_case_component_due_source_shares fcdss
  
  ;

  create temporary table finance_case_component_due_preview_base on commit drop as
        select
          fce.finance_case_id,
          fce.finance_component_id,
          fcda.allocated_source_due_amount_ex_vat,
          row_number() over (partition by fce.finance_case_id order by fce.finance_component_id) as component_ord,
          count(*) over (partition by fce.finance_case_id) as component_count,
          round(
            case
              when coalesce(fcda.allocated_source_due_amount_ex_vat,0) = 0 then 0::numeric
              when fce.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fce.approved_nonbucket_target_amount_ex_vat,0) <> 0 and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when fce.case_type = 'OVERPAYMENT' and round(coalesce(fce.remaining_source_amount,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              when round(coalesce(fce.remaining_source_amount,0),2) <> 0 and round(coalesce(fce.target_pay_ex_vat,0),2) <> 0 then fcda.allocated_source_due_amount_ex_vat * (round(coalesce(fce.target_pay_ex_vat,0),2) / nullif(round(coalesce(fce.remaining_source_amount,0),2),0))
              else fcda.allocated_source_due_amount_ex_vat
            end,
            2
          ) as preliminary_preview_due_amount_ex_vat
        from finance_case_component_review_rows_effective fce
        join finance_case_component_due_source_allocations fcda
          on fcda.finance_case_id = fce.finance_case_id
         and fcda.finance_component_id = fce.finance_component_id
  
  ;

  create temporary table finance_case_component_due_preview_allocations on commit drop as
        select
          fcdpb.finance_case_id,
          fcdpb.finance_component_id,
          round(fcdpb.preliminary_preview_due_amount_ex_vat, 2) as allocated_preview_due_amount_ex_vat
        from finance_case_component_due_preview_base fcdpb
  
  ;

  create temporary table finance_case_taxable_channel_restructure_resolution on commit drop as
        with component_base as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.candidate_id,
            vfcr.client_id,
            vfcr.next_due_week_start,
            vfcr.weekly_due,
            vfcr.weeks_total,
            vfcr.outstanding_amount,
            vfcr.schedule_json,
            cp.cand_pay_method as target_pay_method,
            fccr.finance_component_id,
            fccr.source_family_key,
            fccr.component_key_type,
            fccr.component_key_value,
            fccr.classification,
            fccr.source_pay_method,
            fccr.current_target_pay_method,
            fccr.umb_vat_chargeable,
            fccr.source_basis_json,
            fccr.source_amount,
            fccr.remaining_source_amount,
            fccr.source_units,
            fccr.source_rate,
            fccr.source_charge_rate,
            fccr.source_charge_ex_vat,
            fccr.saved_target_pay_method,
            fccr.saved_resolution_mode,
            fccr.saved_resolution_payload_json,
            fccr.saved_resolution_result_json,
            fccr.resolution_fingerprint,
            fccr.current_component_fingerprint,
            fccr.is_stale_saved_resolution,
            fccr.is_reusable_saved_resolution,
            fccr.stale_reason,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
            ) as has_taxable_channel_mismatch,
            (
              fccr.finance_component_id is not null
              and fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              and upper(coalesce(fccr.source_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.current_target_pay_method,'')) in ('PAYE','UMBRELLA')
              and upper(coalesce(fccr.source_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
              and round(coalesce(fccr.remaining_source_amount,0),2) > 0
              and (
                coalesce(fccr.is_stale_saved_resolution,false) = true
                or nullif(btrim(coalesce(fccr.saved_target_pay_method,'')), '') is null
                or upper(coalesce(fccr.saved_target_pay_method,'')) <> upper(coalesce(fccr.current_target_pay_method,''))
                or (
                  fccr.resolution_fingerprint is not null
                  and fccr.current_component_fingerprint is not null
                  and fccr.resolution_fingerprint is distinct from fccr.current_component_fingerprint
                )
              )
            ) as requires_component_restructure
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          where vfcr.case_type in (
            'OVERPAYMENT'::public.pay_finance_case_type_enum,
            'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
            'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
          )
            and fccr.finance_component_id is not null
            and round(coalesce(fccr.remaining_source_amount,0),2) > 0
        ),
        component_projected as (
          select
            cb.*,
            round(
              case
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'UMBRELLA'
                 and cb.current_target_pay_method = 'PAYE'
                  then public._pay_convert_umbrella_to_paye_ex(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct)
                when cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                 and cb.source_pay_method = 'PAYE'
                 and cb.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_convert_paye_to_umbrella(round(coalesce(cb.remaining_source_amount,0),2), v_erni_pct, v_vat_rate_pct, coalesce(cb.umb_vat_chargeable,false))->>'ex')::numeric, 0)
                else round(coalesce(cb.remaining_source_amount,0),2)
              end,
              2
            ) as target_remaining_ex
          from component_base cb
        ),
        component_projected_vat as (
          select
            cpj.*,
            round(
              case
                when cpj.current_target_pay_method = 'UMBRELLA'
                  then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                else 0
              end,
              2
            ) as target_remaining_vat,
            round(
              coalesce(cpj.target_remaining_ex,0)
              + case
                  when cpj.current_target_pay_method = 'UMBRELLA'
                    then coalesce((public._pay_umbrella_vat_calc(round(coalesce(cpj.target_remaining_ex,0),2), v_vat_rate_pct, coalesce(cpj.umb_vat_chargeable,false))->>'vat')::numeric, 0)
                  else 0
                end,
              2
            ) as target_remaining_inc
          from component_projected cpj
        ),
        case_shape as (
          select
            cpv.finance_case_id,
            (array_agg(cpv.case_type))[1] as case_type,
            (array_remove(array_agg(cpv.candidate_id), null::uuid))[1] as candidate_id,
            (array_remove(array_agg(cpv.client_id), null::uuid))[1] as client_id,
            max(cpv.next_due_week_start) as next_due_week_start,
            max(cpv.weekly_due) as weekly_due,
            max(cpv.weeks_total) as weeks_total,
            max(cpv.outstanding_amount) as outstanding_amount,
            coalesce((jsonb_agg(cpv.schedule_json order by cpv.finance_component_id) filter (where cpv.schedule_json is not null))->0, '[]'::jsonb) as schedule_json,
            max(cpv.target_pay_method) as target_pay_method,
            count(*)::int as open_component_count,
            count(*) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum)::int as open_taxable_count,
            count(*) filter (where cpv.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum))::int as open_fixed_count,
            bool_or(cpv.has_taxable_channel_mismatch) as has_taxable_channel_mismatch,
            bool_or(cpv.requires_component_restructure) as requires_restructure,
            bool_or(coalesce(cpv.is_reusable_saved_resolution,false)) as is_reusable_saved_resolution,
            bool_or(coalesce(cpv.is_stale_saved_resolution,false)) as is_stale_saved_resolution,
            round(coalesce(sum(cpv.remaining_source_amount),0),2) as existing_source_total_ex,
            round(coalesce(sum(cpv.remaining_source_amount) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as existing_taxable_source_total_ex,
            round(coalesce(sum(cpv.target_remaining_ex),0),2) as suggested_target_total_ex,
            round(coalesce(sum(cpv.target_remaining_vat),0),2) as suggested_target_total_vat,
            round(coalesce(sum(cpv.target_remaining_inc),0),2) as suggested_target_total_inc,
            round(coalesce(sum(cpv.target_remaining_ex) filter (where cpv.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum),0),2) as suggested_taxable_target_total_ex,
            bool_or(coalesce(cpv.umb_vat_chargeable,false)) as umbrella_vat_chargeable,
            coalesce(
              jsonb_agg(
                jsonb_strip_nulls(jsonb_build_object(
                  'finance_component_id', cpv.finance_component_id::text,
                  'source_family_key', cpv.source_family_key,
                  'component_key_type', cpv.component_key_type,
                  'component_key_value', cpv.component_key_value,
                  'classification', cpv.classification::text,
                  'source_pay_method', cpv.source_pay_method,
                  'target_pay_method', cpv.current_target_pay_method,
                  'source_remaining_amount_ex_vat', round(coalesce(cpv.remaining_source_amount,0),2),
                  'target_remaining_amount_ex_vat', round(coalesce(cpv.target_remaining_ex,0),2),
                  'target_remaining_amount_vat', round(coalesce(cpv.target_remaining_vat,0),2),
                  'target_remaining_amount_inc_vat', round(coalesce(cpv.target_remaining_inc,0),2),
                  'requires_component_conversion', cpv.has_taxable_channel_mismatch,
                  'requires_restructure', cpv.requires_component_restructure,
                  'source_units', cpv.source_units,
                  'source_rate', cpv.source_rate,
                  'source_charge_rate', cpv.source_charge_rate,
                  'source_charge_ex_vat', cpv.source_charge_ex_vat,
                  'saved_target_pay_method', cpv.saved_target_pay_method,
                  'saved_resolution_mode', case when cpv.saved_resolution_mode is null then null else cpv.saved_resolution_mode::text end,
                  'is_reusable_saved_resolution', cpv.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', cpv.is_stale_saved_resolution,
                  'stale_reason', cpv.stale_reason
                ))
                order by cpv.classification::text, cpv.component_key_type, cpv.component_key_value, cpv.finance_component_id
              ),
              '[]'::jsonb
            ) as component_breakdown_json
          from component_projected_vat cpv
          group by cpv.finance_case_id
        ),
        case_with_schedule as (
          select
            cs.*,
            coalesce(cs.next_due_week_start, v_week_start) as restructure_start_week_start,
            coalesce(
              (
                select count(*)::integer
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched(schedule_entry)
                where jsonb_typeof(sched.schedule_entry) = 'object'
                  and coalesce(sched.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched.schedule_entry->>'amount')::numeric) > 0
              ),
              case
                when coalesce(cs.weekly_due,0) > 0 and coalesce(cs.existing_source_total_ex,0) > 0 then greatest(ceil(cs.existing_source_total_ex / cs.weekly_due)::integer, 1)
                when coalesce(cs.weeks_total,0) > 0 then cs.weeks_total
                else 1
              end
            ) as existing_weeks_remaining,
            coalesce(
              nullif(round(coalesce(cs.weekly_due,0),2),0),
              (
                select round(abs((sched2.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched2(schedule_entry)
                where jsonb_typeof(sched2.schedule_entry) = 'object'
                  and coalesce(sched2.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched2.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched2.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched2.schedule_entry->>'amount')::numeric) > 0
                order by (sched2.schedule_entry->>'week_start')::date asc
                limit 1
              ),
              round(ceil((cs.existing_source_total_ex / greatest(coalesce(cs.weeks_total,1),1)) * 100) / 100, 2)
            ) as existing_weekly_due,
            coalesce(
              (
                select round(abs((sched3.schedule_entry->>'amount')::numeric),2)
                from jsonb_array_elements(coalesce(cs.schedule_json,'[]'::jsonb)) sched3(schedule_entry)
                where jsonb_typeof(sched3.schedule_entry) = 'object'
                  and coalesce(sched3.schedule_entry->>'week_start','') ~ '^\d{4}-\d{2}-\d{2}$'
                  and (cs.next_due_week_start is null or (sched3.schedule_entry->>'week_start')::date >= cs.next_due_week_start)
                  and coalesce(sched3.schedule_entry->>'amount','') ~ '^-?\d+(\.\d+)?$'
                  and abs((sched3.schedule_entry->>'amount')::numeric) > 0
                order by (sched3.schedule_entry->>'week_start')::date desc
                limit 1
              ),
              0::numeric
            ) as existing_final_week_amount
          from case_shape cs
        ),
        open_batch as (
          select
            cws.finance_case_id,
            exists (
              select 1
              from public.pay_batch_items pbi_open
              join public.pay_batch_candidates pbc_open
                on pbc_open.id = pbi_open.pay_batch_candidate_id
              join public.pay_batches pb_open
                on pb_open.id = pbc_open.pay_batch_id
              where coalesce(pbi_open.is_voided,false) = false
                and pb_open.cancelled_at_utc is null
                and upper(coalesce(pb_open.status::text,'')) not in ('CANCELLED','COMPLETED','SETTLED')
                and (
                  pbi_open.finance_case_id = cws.finance_case_id
                  or exists (
                    select 1
                    from public.pay_finance_case_components pfc_open
                    where pfc_open.finance_case_id = cws.finance_case_id
                      and pfc_open.closed_at_utc is null
                      and pfc_open.id = pbi_open.finance_component_id
                  )
                )
            ) as has_open_batch_item
          from case_with_schedule cws
        )
        select
          cws.finance_case_id,
          coalesce(cws.requires_restructure,false) as has_dedicated_resolution_payload,
          coalesce(cws.requires_restructure,false) as use_dedicated_blocker,
          case
            when coalesce(cws.requires_restructure,false) = true then jsonb_strip_nulls(jsonb_build_object(
              'resolution_kind', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
              'resolution_action_label', 'Suggested Restructure',
              'modal_title', 'Finance Restructure',
              'finance_case_id', cws.finance_case_id::text,
              'case_type', cws.case_type::text,
              'source_method', (
                select coalesce(jsonb_agg(distinct cb.source_pay_method), '[]'::jsonb)
                from component_base cb
                where cb.finance_case_id = cws.finance_case_id
                  and cb.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              ),
              'target_method', cws.target_pay_method,
              'can_apply', coalesce(ob.has_open_batch_item,false) = false,
              'open_batch_blocked_reason', case when coalesce(ob.has_open_batch_item,false) = true then 'CASE_ALREADY_IN_OPEN_BATCH' else null end,
              'existing_arrangement', jsonb_build_object(
                'source_remaining_balance_ex_vat', cws.existing_source_total_ex,
                'taxable_source_remaining_balance_ex_vat', cws.existing_taxable_source_total_ex,
                'weekly_due', round(coalesce(cws.existing_weekly_due,0),2),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', case
                  when coalesce(cws.existing_final_week_amount,0) > 0 then round(cws.existing_final_week_amount,2)
                  else round(least(round(coalesce(cws.existing_weekly_due,0),2), greatest(cws.existing_source_total_ex - (round(coalesce(cws.existing_weekly_due,0),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),0)),2)
                end,
                'start_week_start', cws.restructure_start_week_start::text,
                'schedule_json', coalesce(cws.schedule_json,'[]'::jsonb)
              ),
              'suggested_arrangement', jsonb_build_object(
                'target_remaining_balance_ex_vat', cws.suggested_target_total_ex,
                'target_remaining_balance_vat', cws.suggested_target_total_vat,
                'target_remaining_balance_inc_vat', cws.suggested_target_total_inc,
                'taxable_target_remaining_balance_ex_vat', cws.suggested_taxable_target_total_ex,
                'weekly_due', round(
                  greatest(
                    round(coalesce(cws.existing_weekly_due,0),2)
                    * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end,
                    0.01
                  ),
                  2
                ),
                'weeks_remaining', greatest(coalesce(cws.existing_weeks_remaining,1),1),
                'final_week_amount', round(
                  least(
                    greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),
                    greatest(
                      cws.suggested_target_total_ex
                      - (round(greatest(round(coalesce(cws.existing_weekly_due,0),2) * case when cws.existing_source_total_ex > 0 then cws.suggested_target_total_ex / cws.existing_source_total_ex else 1 end, 0.01),2) * greatest(coalesce(cws.existing_weeks_remaining,1) - 1,0)),
                      0
                    )
                  ),
                  2
                ),
                'erni_rate_pct', round(v_erni_pct,6),
                'erni_component_ex_vat', round(abs(cws.existing_taxable_source_total_ex - cws.suggested_taxable_target_total_ex),2),
                'vat_rate_pct', round(v_vat_rate_pct,6),
                'vat_amount', cws.suggested_target_total_vat,
                'umbrella_vat_chargeable', coalesce(cws.umbrella_vat_chargeable,false)
              ),
              'component_breakdown', cws.component_breakdown_json,
              'suggestion_explanation_text', 'This taxable finance case must be durably restructured onto the current pay method before it can move to Ready to Pay.'
            ))
            else null::jsonb
          end as taxable_channel_restructure_resolution_json
        from case_with_schedule cws
        left join open_batch ob
          on ob.finance_case_id = cws.finance_case_id

  ;
  create temporary table finance_case_resolution_rollup on commit drop as
        with grouped as (
          select
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method as candidate_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            fpr.bank_details_hash as payee_bank_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then true
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then true
              else false
            end as is_recovery_case,
            case
              when vfcr.case_type in ('OVERPAYMENT','MANUAL_DEBT_ADJUSTMENT') then '[]'::jsonb
              when vfcr.case_type = 'PAYMENT_ADVANCE' and upper(coalesce(vfcr.payout_status::text,'')) = 'PAID' then '[]'::jsonb
              else coalesce(fpr.blocked_reason_codes, '[]'::jsonb)
            end as payee_blocked_reason_codes,
            case
              when vfcr.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then 'one-off specified bank account'
              when vfcr.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'umbrella company'
              else 'normal PAYE route'
            end as destination_label,
            round(coalesce(max(fcds.due_source_amount_ex_vat),0),2) as due_source_amount_ex_vat,
            round(coalesce(sum(fcdpa.allocated_preview_due_amount_ex_vat), max(fcds.due_source_amount_ex_vat), 0),2) as due_amount_ex_vat,
            coalesce(fctcr.has_dedicated_resolution_payload,false) as has_taxable_channel_restructure_payload,
            coalesce(fctcr.use_dedicated_blocker,false) as use_taxable_channel_restructure_blocker,
            fctcr.taxable_channel_restructure_resolution_json as taxable_channel_restructure_resolution_json,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'TAXABLE_CHANNEL_RESTRUCTURE'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'NON_BUCKET'::text
              else 'BUCKETED'::text
            end as resolution_family,
            case
              when coalesce(fctcr.use_dedicated_blocker,false) = true then 'Suggested Restructure'::text
              when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Suggested Gross Total'::text
              else 'Suggested Rate'::text
            end as resolution_action_label,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0)::int as open_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0)::int as open_reimbursement_count,
            (coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true), 0)
              + case when coalesce(fctcr.use_dedicated_blocker,false) = true then 1 else 0 end)::int as unresolved_taxable_count,
            coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.is_stale_saved_resolution,false) = true), 0)::int as stale_count,
            (coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
            ), 0) > 0
             and
             coalesce(count(fccr.finance_component_id) filter (
              where fccr.classification in (
                'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
                'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
              )
            ), 0) > 0) as is_mixed_case,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = true
              or coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) > 0
            ) as case_needs_resolution,
            (
              coalesce(fctcr.use_dedicated_blocker,false) = false
              and coalesce(count(fccr.finance_component_id) filter (where coalesce(fccr.requires_resolution,false) = true),0) = 0
            ) as case_resolution_satisfied_now,
            case when coalesce(fctcr.use_dedicated_blocker,false) = true then null::jsonb else coalesce(
              (jsonb_agg(
                jsonb_build_object(
                  'resolution_kind', 'NON_BUCKET_GROSS_TOTAL',
                  'resolution_family', 'NON_BUCKET',
                  'resolution_action_label', 'Suggested Gross Total',
                  'source_amount_ex_vat', round(coalesce(fccr.remaining_source_amount,0),2),
                  'suggested_target_amount_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'approved_target_amount_ex_vat', case when fccr.approved_nonbucket_target_amount_ex_vat is null then null else round(fccr.approved_nonbucket_target_amount_ex_vat,2) end,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text
                )
              ) filter (where vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fccr.finance_component_id is not null))->0,
              null::jsonb
            ) end as non_bucket_resolution_json,
            coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'finance_component_id', fccr.finance_component_id::text,
                  'source_family_key', fccr.source_family_key,
                  'component_key_type', fccr.component_key_type,
                  'component_key_value', fccr.component_key_value,
                  'classification', fccr.classification::text,
                  'source_pay_method', fccr.source_pay_method,
                  'current_target_pay_method', fccr.current_target_pay_method,
                  'source_amount', round(coalesce(fccr.source_amount,0),2),
                  'remaining_source_amount', round(coalesce(fccr.remaining_source_amount,0),2),
                  'source_basis_json', jsonb_strip_nulls(fccr.source_basis_json || jsonb_build_object('source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end, 'source_charge_rate', case when fccr.source_charge_rate is null then null else round(fccr.source_charge_rate,2) end)),
                  'saved_target_pay_method', fccr.saved_target_pay_method,
                  'saved_resolution_mode', case when fccr.saved_resolution_mode is null then null else fccr.saved_resolution_mode::text end,
                  'saved_resolution_payload_json', fccr.saved_resolution_payload_json,
                  'saved_resolution_result_json', fccr.saved_resolution_result_json,
                  'has_suggested_resolution', fccr.has_suggested_resolution,
                  'suggestion_provenance', fccr.suggestion_provenance,
                  'is_fresh_suggested_resolution', fccr.is_fresh_suggested_resolution,
                  'is_reusable_saved_resolution', fccr.is_reusable_saved_resolution,
                  'is_stale_saved_resolution', fccr.is_stale_saved_resolution,
                  'suggested_resolution_payload_json', fccr.suggested_resolution_payload_json,
                  'suggested_resolution_result_json', fccr.suggested_resolution_result_json,
                  'source_units', fccr.source_units,
                  'target_units', case when nullif(fccr.suggested_resolution_result_json->>'target_units','') is not null then (fccr.suggested_resolution_result_json->>'target_units')::numeric else fccr.source_units end,
                  'source_rate', case when fccr.source_rate is null then null else round(fccr.source_rate,2) end,
                  'target_rate', case when nullif(fccr.suggested_resolution_result_json->>'replacement_rate','') is not null then round((fccr.suggested_resolution_result_json->>'replacement_rate')::numeric,2) when nullif(fccr.suggested_resolution_payload_json->>'suggested_target_rate','') is not null then round((fccr.suggested_resolution_payload_json->>'suggested_target_rate')::numeric,2) else null end,
                  'source_pay_ex_vat', round(coalesce(fccr.source_pay_ex_vat,0),2),
                  'source_charge_ex_vat', fccr.source_charge_component_ex_vat,
                  'source_margin_ex_vat', fccr.source_margin_ex_vat,
                  'target_pay_ex_vat', round(coalesce(fccr.target_pay_ex_vat,0),2),
                  'target_charge_ex_vat', fccr.target_charge_ex_vat,
                  'target_margin_ex_vat', fccr.target_margin_ex_vat,
                  'margin_delta_ex_vat', fccr.margin_delta_ex_vat,
                  'suggestion_explanation_text', fccr.suggestion_explanation_text,
                  'component_fingerprint', fccr.current_component_fingerprint,
                  'is_resolution_stale', coalesce(fccr.is_stale_saved_resolution,false),
                  'stale_reason', fccr.stale_reason,
                  'requires_resolution', coalesce(fccr.requires_resolution,false),
                  'resolution_state', case
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and coalesce(fccr.requires_resolution,false) = true then 'REQUIRED'
                    when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'RESOLVED'
                    else case when fccr.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'FIXED' when coalesce(fccr.requires_resolution,false) = true then 'REQUIRED' else 'RESOLVED' end
                  end,
                  'is_actionable_resolution_row', coalesce(fccr.is_actionable_resolution_row,false),
                  'is_fixed_no_action_taxable_row', coalesce(fccr.is_fixed_no_action_taxable_row,false),
                  'allocated_source_due_amount_ex_vat', round(coalesce(fcda.allocated_source_due_amount_ex_vat,0),2),
                  'preview_due_amount_ex_vat', round(coalesce(fcdpa.allocated_preview_due_amount_ex_vat, coalesce(fcda.allocated_source_due_amount_ex_vat,0)),2)
                )
                order by fccr.classification::text, fccr.component_key_type, fccr.component_key_value
              ) filter (where fccr.finance_component_id is not null),
              '[]'::jsonb
            ) as case_components_json
          from finance_case_baseline_scope vfcr
          join cand_payee cp
            on cp.candidate_id = vfcr.candidate_id
          left join finance_case_component_review_rows_effective fccr
            on fccr.finance_case_id = vfcr.finance_case_id
          left join finance_case_payee_readiness fpr
            on fpr.finance_case_id = vfcr.finance_case_id
          left join finance_case_due_source_amounts fcds
            on fcds.finance_case_id = vfcr.finance_case_id
          left join finance_case_component_due_source_allocations fcda
            on fcda.finance_case_id = fccr.finance_case_id
           and fcda.finance_component_id = fccr.finance_component_id
          left join finance_case_component_due_preview_allocations fcdpa
            on fcdpa.finance_case_id = fccr.finance_case_id
           and fcdpa.finance_component_id = fccr.finance_component_id
          left join finance_case_taxable_channel_restructure_resolution fctcr
            on fctcr.finance_case_id = vfcr.finance_case_id
          where vfcr.finance_case_id is not null
          group by
            vfcr.finance_case_id,
            vfcr.case_type,
            vfcr.advance_kind,
            vfcr.reason,
            vfcr.candidate_id,
            cp.cand_tms_ref,
            cp.cand_display_name,
            cp.cand_pay_method,
            fpr.payee_entity_kind,
            fpr.payee_entity_id,
            fpr.bank_details_hash,
            fpr.beneficiary_name,
            fpr.masked_bank_account,
            fpr.blocked_reason_codes,
            vfcr.client_id,
            vfcr.client_name,
            vfcr.linked_timesheet_id,
            vfcr.linked_shift_date,
            vfcr.adjustment_comment,
            vfcr.next_due_week_start,
            vfcr.active_snooze_id,
            vfcr.active_snooze_kind,
            vfcr.active_snooze_until_date,
            vfcr.active_snooze_note,
            vfcr.taxability,
            vfcr.routing_kind,
            vfcr.oneoff_bank_details_present,
            vfcr.oneoff_bank_details_required,
            vfcr.is_candidate_directed_oneoff_payout,
            vfcr.appears_on_umbrella_remittance,
            vfcr.generates_candidate_payment_advice,
            vfcr.snooze_allowed,
            vfcr.lifecycle_status_display,
            vfcr.payout_status,
            fctcr.has_dedicated_resolution_payload,
            fctcr.use_dedicated_blocker,
            fctcr.taxable_channel_restructure_resolution_json
        )
        select
          g.finance_case_id,
          g.case_type,
          g.advance_kind,
          g.reason,
          g.candidate_id,
          g.cand_tms_ref,
          g.cand_display_name,
          g.candidate_pay_method,
          g.payee_entity_kind,
          g.payee_entity_id,
          (jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) = 0) as candidate_ready_for_draft,
          g.client_id,
          g.client_name,
          g.linked_timesheet_id,
          g.linked_shift_date,
          g.adjustment_comment,
          g.next_due_week_start,
          g.active_snooze_id,
          g.active_snooze_kind,
          g.active_snooze_until_date,
          g.active_snooze_note,
          g.taxability,
          g.routing_kind,
          g.oneoff_bank_details_present,
          g.oneoff_bank_details_required,
          g.is_candidate_directed_oneoff_payout,
          g.appears_on_umbrella_remittance,
          g.generates_candidate_payment_advice,
          g.snooze_allowed,
          g.lifecycle_status_display,
          g.payee_bank_hash,
          g.beneficiary_name,
          g.masked_bank_account,
          g.destination_label,
          g.due_amount_ex_vat,
          g.open_taxable_count,
          g.open_reimbursement_count,
          g.unresolved_taxable_count,
          g.stale_count,
          g.is_mixed_case,
          g.resolution_family,
          g.case_needs_resolution,
          g.case_resolution_satisfied_now,
          g.resolution_action_label,
          g.taxable_channel_restructure_resolution_json,
          null::jsonb as linked_resolution_scope_json,
          (
            g.case_needs_resolution = true
            or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
          ) as is_blocked,
          (
            coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
            ||
            (case
              when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
              when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
              when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
              else '[]'::jsonb
            end)
          ) as blocked_reason_codes,
          jsonb_strip_nulls(
            jsonb_build_object(
              'case_key', ('finance:' || g.finance_case_id::text),
              'case_type', g.case_type::text,
              'resolution_family', g.resolution_family,
              'case_needs_resolution', g.case_needs_resolution,
              'case_resolution_satisfied_now', g.case_resolution_satisfied_now,
              'resolution_action_label', g.resolution_action_label,
              'linked_resolution_scope_json', null,
              'taxability', case when g.taxability is null then null else g.taxability::text end,
              'routing_kind', case when g.routing_kind is null then null else g.routing_kind::text end,
              'destination_label', g.destination_label,
              'is_mixed_case', g.is_mixed_case,
              'open_taxable_count', g.open_taxable_count,
              'open_reimbursement_count', g.open_reimbursement_count,
              'unresolved_taxable_count', g.unresolved_taxable_count,
              'stale_count', g.stale_count,
              'is_blocked', (
                g.case_needs_resolution = true
                or jsonb_array_length(coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)) > 0
              ),
              'due_amount_ex_vat', g.due_amount_ex_vat,
              'blocked_reason_codes', (
                coalesce(g.payee_blocked_reason_codes, '[]'::jsonb)
                ||
                (case
                  when g.resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_CHANNEL_RESTRUCTURE')
                  when g.resolution_family = 'NON_BUCKET' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_NON_BUCKET_RESOLUTION')
                  when g.resolution_family = 'BUCKETED' and g.case_needs_resolution = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                  else '[]'::jsonb
                end)
              ),
              'non_bucket_resolution', g.non_bucket_resolution_json,
              'taxable_channel_restructure', g.taxable_channel_restructure_resolution_json,
              'taxable_channel_restructure_resolution', g.taxable_channel_restructure_resolution_json
            )
          ) as case_resolution_summary_json,
          case
            when g.resolution_family = 'NON_BUCKET'
              and jsonb_typeof(g.non_bucket_resolution_json) = 'object'
            then g.non_bucket_resolution_json
            else null::jsonb
          end as taxable_manual_debt_resolution_json,
          g.case_components_json
        from grouped g
  
  ;

  PERFORM public._imp_debug_audit(
    v_actor_user_id,
    'PAY_PREVIEW_FINANCE_CASE_BASELINE_RESULT',
    jsonb_build_object(
      'candidate_id', v_candidate_id,
      'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
      'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup),
      'finance_case_repaid_wtd_count', (select count(*)::int from finance_case_repaid_wtd)
    ),
    'pay_preview_finance',
    COALESCE(v_candidate_id::text, 'NO_CANDIDATE_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'finance_case_component_count', (select count(*)::int from finance_case_component_review_rows_effective),
    'finance_case_resolution_count', (select count(*)::int from finance_case_resolution_rollup)
  );

exception
  when others then
    PERFORM public._imp_debug_audit(
      v_actor_user_id,
      'PAY_PREVIEW_FINANCE_CASE_BASELINE_ERROR',
      jsonb_build_object(
        'candidate_id', p_candidate_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_preview_finance',
      COALESCE(p_candidate_id::text, 'NO_CANDIDATE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;






CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_payee_baseline(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.timesheet_case_rollup') is null then
    perform public.pay_preview_candidate_build_case_component_rows(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.finance_candidate_seed, pg_temp.candidate_base, pg_temp.timesheet_candidate_rollup, pg_temp.candidate_rollup, pg_temp.blocked_counts, pg_temp.do_not_pay_counts, pg_temp.loan_due, pg_temp.overpayment_balances, pg_temp.loan_due_this_week, pg_temp.loan_repaid_wtd, pg_temp.paid_wtd_before, pg_temp.cand_enriched, pg_temp.payee_baseline_rows, pg_temp.payees_src, pg_temp.payees, pg_temp.payees_enriched, pg_temp.payees_json, pg_temp.cand_payee0, pg_temp.cand_payee, pg_temp.timesheet_case_rollup_payable, pg_temp.timesheet_case_rollup_effective;

  create temporary table finance_candidate_seed on commit drop as
        select
          vfcr.candidate_id,
          c.tms_ref as cand_tms_ref,
          c.display_name as cand_display_name,
          upper(coalesce(c.pay_method,'')) as cand_pay_method,
          c.umbrella_id as cand_umbrella_id,
          coalesce(u.enabled,false) as umb_enabled,
          coalesce(u.vat_chargeable,false) as umb_vat_chargeable,
          (c.bank_details_hash is not null and btrim(c.bank_details_hash) <> '') as candidate_has_bank_details,
          c.bank_details_hash as candidate_bank_hash,
          (u.bank_details_hash is not null and btrim(u.bank_details_hash) <> '') as umbrella_has_bank_details,
          u.bank_details_hash as umbrella_bank_hash
        from finance_case_baseline_scope vfcr
        join public.candidates c
          on c.id = vfcr.candidate_id
        left join public.umbrellas u
          on u.id = c.umbrella_id
  
  ;

  create temporary table candidate_base on commit drop as
        select
          x.candidate_id,
          max(x.cand_tms_ref) as cand_tms_ref,
          max(x.cand_display_name) as cand_display_name,
          max(x.cand_pay_method) as cand_pay_method,
          max(x.cand_umbrella_id::text)::uuid as cand_umbrella_id,
          bool_or(x.umb_enabled) as umb_enabled,
          bool_or(x.umb_vat_chargeable) as umb_vat_chargeable,
          bool_or(x.candidate_has_bank_details) as candidate_has_bank_details,
          max(x.candidate_bank_hash) as candidate_bank_hash,
          bool_or(x.umbrella_has_bank_details) as umbrella_has_bank_details,
          max(x.umbrella_bank_hash) as umbrella_bank_hash
        from (
          select
            d.candidate_id,
            d.cand_tms_ref,
            d.cand_display_name,
            d.cand_pay_method,
            d.cand_umbrella_id,
            d.umb_enabled,
            d.umb_vat_chargeable,
            (d.cand_bank_hash is not null and btrim(d.cand_bank_hash) <> '') as candidate_has_bank_details,
            d.cand_bank_hash as candidate_bank_hash,
            (d.umb_bank_hash is not null and btrim(d.umb_bank_hash) <> '') as umbrella_has_bank_details,
            d.umb_bank_hash as umbrella_bank_hash
          from ts_deltas d
          union all
          select
            fcs.candidate_id,
            fcs.cand_tms_ref,
            fcs.cand_display_name,
            fcs.cand_pay_method,
            fcs.cand_umbrella_id,
            fcs.umb_enabled,
            fcs.umb_vat_chargeable,
            fcs.candidate_has_bank_details,
            fcs.candidate_bank_hash,
            fcs.umbrella_has_bank_details,
            fcs.umbrella_bank_hash
          from finance_candidate_seed fcs
        ) x
        group by x.candidate_id
  
  ;

  create temporary table timesheet_case_rollup_payable on commit drop as
        with normalized_timesheet_rollup as (
          select
            tcr.candidate_id,
            tcr.timesheet_id,
            tcr.client_id,
            tcr.ts_week_ending_date,
            tcr.ts_client_name,
            tcr.ts_pay_method,
            tcr.cand_pay_method,
            tcr.cand_tms_ref,
            tcr.cand_display_name,
            tcr.cand_umbrella_id,
            tcr.umb_enabled,
            tcr.umb_vat_chargeable,
            tcr.candidate_has_bank_details,
            tcr.candidate_bank_hash,
            tcr.umbrella_has_bank_details,
            tcr.umbrella_bank_hash,
            tcr.resolution_family,
            round(coalesce(ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount_ex_vat,
            round(coalesce(ti.payment_amount_inc_vat, ti.payment_amount, ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount_inc_vat, tcr.payment_amount, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount_inc_vat,
            round(coalesce(ti.payment_amount, ti.payment_amount_inc_vat, ti.payment_amount_ex_vat, ti.total_ex, tcr.payment_amount, tcr.payment_amount_inc_vat, tcr.payment_amount_ex_vat, tcr.case_total_amount_ex, 0), 2) as effective_payment_amount,
            round(coalesce(case when ti.timesheet_id is not null then ti_segment_totals.segment_total_ex else null::numeric end, tcr.segments_total_ex, 0), 2) as effective_segments_total_ex,
            coalesce(ti.segment_deltas_json, tcr.segment_deltas_json, '[]'::jsonb) as effective_segment_deltas_json,
            coalesce(ti.adjustment_deltas_json, tcr.adjustment_deltas_json, '[]'::jsonb) as effective_adjustment_deltas_json,
            coalesce(ti.additional_unit_deltas_json, tcr.additional_unit_deltas_json, '[]'::jsonb) as effective_additional_unit_deltas_json,
            round(coalesce(ti.delta_additional_pay_ex_vat, tcr.delta_additional_pay_ex_vat, 0), 2) as effective_delta_additional_pay_ex_vat,
            round(coalesce(ti.delta_expenses_pay_ex_vat, tcr.delta_expenses_pay_ex_vat, 0), 2) as effective_delta_expenses_pay_ex_vat,
            round(coalesce(ti.delta_travel_pay_ex_vat, tcr.delta_travel_pay_ex_vat, 0), 2) as effective_delta_travel_pay_ex_vat,
            round(coalesce(ti.delta_accommodation_pay_ex_vat, tcr.delta_accommodation_pay_ex_vat, 0), 2) as effective_delta_accommodation_pay_ex_vat,
            round(coalesce(ti.delta_other_pay_ex_vat, tcr.delta_other_pay_ex_vat, 0), 2) as effective_delta_other_pay_ex_vat,
            round(coalesce(ti.delta_mileage_pay_ex_vat, tcr.delta_mileage_pay_ex_vat, 0), 2) as effective_delta_mileage_pay_ex_vat,
            coalesce(ti.reservation_overrun_detected, tcr.reservation_overrun_detected, false) as effective_reservation_overrun_detected,
            tcr.case_components_json,
            tcr.case_resolution_summary_json,
            tcr.case_needs_resolution,
            tcr.case_resolution_satisfied_now,
            tcr.resolution_action_label,
            tcr.linked_resolution_scope_json,
            tcr.unresolved_taxable_amount_ex,
            tcr.open_taxable_count,
            tcr.open_reimbursement_count,
            tcr.unresolved_taxable_count,
            tcr.stale_count,
            tcr.is_mixed_case,
            tcr.is_blocked
          from timesheet_case_rollup tcr
          left join ts_itemised ti
            on ti.timesheet_id = tcr.timesheet_id
           and ti.candidate_id = tcr.candidate_id
          left join lateral (
            select round(
                     coalesce(
                       sum(
                         case
                           when coalesce(segment_delta.value->>'delta_pay_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                             then (segment_delta.value->>'delta_pay_ex_vat')::numeric
                           else 0::numeric
                         end
                       ),
                       0::numeric
                     ),
                     2
                   ) as segment_total_ex
            from jsonb_array_elements(
              case
                when jsonb_typeof(coalesce(ti.segment_deltas_json, '[]'::jsonb)) = 'array'
                  then coalesce(ti.segment_deltas_json, '[]'::jsonb)
                else '[]'::jsonb
              end
            ) as segment_delta(value)
          ) ti_segment_totals on true
        )
        select
          normalized_timesheet_rollup.candidate_id,
          normalized_timesheet_rollup.timesheet_id,
          normalized_timesheet_rollup.client_id,
          normalized_timesheet_rollup.ts_week_ending_date,
          normalized_timesheet_rollup.ts_client_name,
          normalized_timesheet_rollup.ts_pay_method,
          normalized_timesheet_rollup.cand_pay_method,
          normalized_timesheet_rollup.cand_tms_ref,
          normalized_timesheet_rollup.cand_display_name,
          normalized_timesheet_rollup.cand_umbrella_id,
          normalized_timesheet_rollup.umb_enabled,
          normalized_timesheet_rollup.umb_vat_chargeable,
          normalized_timesheet_rollup.candidate_has_bank_details,
          normalized_timesheet_rollup.candidate_bank_hash,
          normalized_timesheet_rollup.umbrella_has_bank_details,
          normalized_timesheet_rollup.umbrella_bank_hash,
          normalized_timesheet_rollup.resolution_family,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
            else normalized_timesheet_rollup.case_needs_resolution
          end as case_needs_resolution,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then true
            else normalized_timesheet_rollup.case_resolution_satisfied_now
          end as case_resolution_satisfied_now,
          normalized_timesheet_rollup.resolution_action_label,
          normalized_timesheet_rollup.linked_resolution_scope_json,
          normalized_timesheet_rollup.effective_payment_amount_ex_vat as case_total_amount_ex,
          case
            when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then 0::numeric
            else normalized_timesheet_rollup.effective_payment_amount_ex_vat
          end as safe_amount_ex,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0::numeric
            else normalized_timesheet_rollup.unresolved_taxable_amount_ex
          end as unresolved_taxable_amount_ex,
          normalized_timesheet_rollup.open_taxable_count,
          normalized_timesheet_rollup.open_reimbursement_count,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0
            else normalized_timesheet_rollup.unresolved_taxable_count
          end as unresolved_taxable_count,
          normalized_timesheet_rollup.stale_count,
          normalized_timesheet_rollup.is_mixed_case,
          case
            when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
            else normalized_timesheet_rollup.is_blocked
          end as is_blocked,
          normalized_timesheet_rollup.effective_segments_total_ex as segments_total_ex,
          normalized_timesheet_rollup.effective_delta_additional_pay_ex_vat as delta_additional_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_expenses_pay_ex_vat as delta_expenses_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_travel_pay_ex_vat as delta_travel_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_accommodation_pay_ex_vat as delta_accommodation_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_other_pay_ex_vat as delta_other_pay_ex_vat,
          normalized_timesheet_rollup.effective_delta_mileage_pay_ex_vat as delta_mileage_pay_ex_vat,
          normalized_timesheet_rollup.effective_segment_deltas_json as segment_deltas_json,
          normalized_timesheet_rollup.effective_adjustment_deltas_json as adjustment_deltas_json,
          normalized_timesheet_rollup.effective_additional_unit_deltas_json as additional_unit_deltas_json,
          normalized_timesheet_rollup.effective_reservation_overrun_detected as reservation_overrun_detected,
          normalized_timesheet_rollup.effective_payment_amount_ex_vat as payment_amount_ex_vat,
          normalized_timesheet_rollup.effective_payment_amount_inc_vat as payment_amount_inc_vat,
          normalized_timesheet_rollup.effective_payment_amount as payment_amount,
          (
            coalesce(normalized_timesheet_rollup.case_resolution_summary_json, '{}'::jsonb)
            || jsonb_build_object(
              'case_needs_resolution', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then false
                else normalized_timesheet_rollup.case_needs_resolution
              end,
              'case_resolution_satisfied_now', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then true
                else normalized_timesheet_rollup.case_resolution_satisfied_now
              end,
              'safe_amount_ex_vat', case
                when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then 0::numeric
                else normalized_timesheet_rollup.effective_payment_amount_ex_vat
              end,
              'blocked_case_amount_ex_vat', case
                when coalesce(normalized_timesheet_rollup.is_blocked, false) = true then normalized_timesheet_rollup.effective_payment_amount_ex_vat
                else 0::numeric
              end,
              'unresolved_taxable_amount_ex_vat', case
                when normalized_timesheet_rollup.effective_payment_amount_ex_vat = 0 then 0::numeric
                else normalized_timesheet_rollup.unresolved_taxable_amount_ex
              end
            )
          ) as case_resolution_summary_json,
          normalized_timesheet_rollup.case_components_json
        from normalized_timesheet_rollup

  ;

  create temporary table timesheet_candidate_rollup on commit drop as
        select
          tcr.candidate_id,
          bool_or(coalesce(tcr.unresolved_taxable_count, 0) > 0) as has_mismatch,
          round(sum(case when coalesce(tcr.is_blocked, false) = false then coalesce(tcr.case_total_amount_ex, 0) else 0 end), 2) as non_mismatch_total_ex,
          round(sum(case when coalesce(tcr.unresolved_taxable_count, 0) > 0 and tcr.ts_pay_method = 'PAYE' then coalesce(tcr.unresolved_taxable_amount_ex, 0) else 0 end), 2) as mismatch_source_paye_ex,
          round(sum(case when coalesce(tcr.unresolved_taxable_count, 0) > 0 and tcr.ts_pay_method = 'UMBRELLA' then coalesce(tcr.unresolved_taxable_amount_ex, 0) else 0 end), 2) as mismatch_source_umbrella_ex,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'timesheet_id', tcr.timesheet_id::text,
                'week_ending_date', case when tcr.ts_week_ending_date is null then null else tcr.ts_week_ending_date::text end,
                'client_id', case when tcr.client_id is null then null else tcr.client_id::text end,
                'client_name', tcr.ts_client_name,
                'payment_amount_ex_vat', tcr.payment_amount_ex_vat,
                'payment_amount_inc_vat', tcr.payment_amount_inc_vat,
                'payment_amount', tcr.payment_amount,
                'source_pay_method', tcr.ts_pay_method,
                'candidate_pay_method', tcr.cand_pay_method,
                'segment_deltas', tcr.segment_deltas_json,
                'adjustment_deltas', tcr.adjustment_deltas_json,
                'delta_additional_pay_ex_vat', tcr.delta_additional_pay_ex_vat,
                'additional_unit_deltas', tcr.additional_unit_deltas_json,
                'reservation_overrun_detected', tcr.reservation_overrun_detected,
                'delta_expenses_pay_ex_vat', tcr.delta_expenses_pay_ex_vat,
                'delta_travel_pay_ex_vat', tcr.delta_travel_pay_ex_vat,
                'delta_accommodation_pay_ex_vat', tcr.delta_accommodation_pay_ex_vat,
                'delta_other_pay_ex_vat', tcr.delta_other_pay_ex_vat,
                'delta_mileage_pay_ex_vat', tcr.delta_mileage_pay_ex_vat,
                'case_key', ('timesheet:' || tcr.timesheet_id::text),
                'case_resolution_summary', coalesce(tcr.case_resolution_summary_json, '{}'::jsonb),
                'components', coalesce(tcr.case_components_json, '[]'::jsonb)
              )
              order by tcr.ts_week_ending_date, tcr.ts_client_name, tcr.timesheet_id
            ) filter (where round(coalesce(tcr.case_total_amount_ex,0),2) <> 0),
            '[]'::jsonb
          ) as timesheets_itemisation
        from timesheet_case_rollup_payable tcr
        group by tcr.candidate_id
  
  ;

  create temporary table candidate_rollup on commit drop as
        select
          cb.candidate_id,
          cb.cand_tms_ref,
          cb.cand_display_name,
          cb.cand_pay_method,
          cb.cand_umbrella_id,
          cb.umb_enabled,
          cb.umb_vat_chargeable,
          cb.candidate_has_bank_details,
          cb.candidate_bank_hash,
          cb.umbrella_has_bank_details,
          cb.umbrella_bank_hash,
          coalesce(tcrr.has_mismatch, false) as has_mismatch,
          coalesce(tcrr.non_mismatch_total_ex, 0) as non_mismatch_total_ex,
          coalesce(tcrr.mismatch_source_paye_ex, 0) as mismatch_source_paye_ex,
          coalesce(tcrr.mismatch_source_umbrella_ex, 0) as mismatch_source_umbrella_ex,
          coalesce(tcrr.timesheets_itemisation, '[]'::jsonb) as timesheets_itemisation
        from candidate_base cb
        left join timesheet_candidate_rollup tcrr
          on tcrr.candidate_id = cb.candidate_id
  
  ;

  create temporary table blocked_counts on commit drop as
        select bi.candidate_id, count(*)::int as blocked_count
        from blocked_items bi
        group by bi.candidate_id
  
  ;

  create temporary table do_not_pay_counts on commit drop as
        select di.candidate_id, count(*)::int as do_not_pay_count
        from do_not_pay_items di
        group by di.candidate_id
  
  ;

  create temporary table loan_due on commit drop as
        select
          pa.candidate_id,
          round(
            sum(
              abs(coalesce(nullif(e->>'amount','')::numeric,0))
            ),
            2
          ) as loan_due_total,
          jsonb_agg(
            jsonb_build_object(
              'advance_id', pa.id::text,
              'week_start', (nullif(e->>'week_start','')::date)::text,
              'due_amount', round(abs(coalesce(nullif(e->>'amount','')::numeric,0)),2),
              'reason', pa.reason::text,
              -- legacy alias (kept to avoid breaking any existing consumer)
              'scheduled_amount', round(abs(coalesce(nullif(e->>'amount','')::numeric,0)),2)
            )
            order by (nullif(e->>'week_start','')::date) asc nulls last, pa.created_at asc, pa.id
          ) as loan_due_entries
        from public.pay_advances pa
        join lateral jsonb_array_elements(coalesce(pa.schedule_json,'[]'::jsonb)) e on true
        where pa.status::text = 'ACTIVE'
          and nullif(e->>'week_start','') is not null
          and (nullif(e->>'week_start','')::date) <= v_week_start
          and coalesce(nullif(e->>'amount','')::numeric,0) < 0
        group by pa.candidate_id
  
  ;

  create temporary table overpayment_balances on commit drop as
        select
          pa.candidate_id,
          round(sum(coalesce(pa.outstanding_amount,0)),2) as overpayment_balance_remaining
        from public.pay_advances pa
        where upper(coalesce(pa.advance_kind::text,'')) = 'OVERPAYMENT'
          and upper(coalesce(pa.status::text,'')) = 'ACTIVE'
        group by pa.candidate_id
  
  ;

  create temporary table loan_due_this_week on commit drop as
        select
          pa.candidate_id,
          round(sum(
            case
              when upper(coalesce(pa.advance_kind::text,'')) = 'LOAN'
                and upper(coalesce(pa.status::text,'')) = 'ACTIVE'
                and upper(coalesce(pa.payout_status::text,'')) = 'PAID'
                and coalesce(pa.outstanding_amount,0) > 0
                and (pa.start_week_start is null or pa.start_week_start <= v_week_start)
              then least(coalesce(pa.weekly_due,0), coalesce(pa.outstanding_amount,0))
              else 0
            end
          ),2) as loan_due_this_week
        from public.pay_advances pa
        group by pa.candidate_id
  
  ;

  create temporary table loan_repaid_wtd on commit drop as
        select
          pbc.candidate_id,
          round(sum(abs(coalesce(pbi.amount_ex_vat,0))),2) as loan_repaid_wtd
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc
          on pbc.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb
          on pb.id = pbc.pay_batch_id
        where pbi.item_type = 'LOAN_REPAYMENT'
          and pb.pay_date::date >= v_week_start
          and pb.pay_date::date < v_pay_date
          and upper(coalesce(pb.status::text,'')) <> 'CANCELLED'
        group by pbc.candidate_id
  
  ;

  create temporary table paid_wtd_before on commit drop as
        select
          cr.candidate_id,
          public._pay_candidate_arranged_pay_wtd_before(
            p_candidate_id => cr.candidate_id,
            p_week_start => v_week_start,
            p_pay_date => v_pay_date,
            p_before_created_at_utc => null::timestamptz,
            p_before_pay_batch_id => null::uuid
          )::numeric(12,2) as paid_wtd_before
        from candidate_rollup cr
  
  ;

  create temporary table cand_enriched on commit drop as
        select
          cr.candidate_id,
          cr.cand_tms_ref,
          cr.cand_display_name,
          cr.cand_pay_method,
          cr.cand_umbrella_id,
          cr.umb_enabled,
          cr.umb_vat_chargeable,
          cr.has_mismatch,
          cr.non_mismatch_total_ex,
          cr.mismatch_source_paye_ex,
          cr.mismatch_source_umbrella_ex,
          cr.timesheets_itemisation,
          coalesce(bc.blocked_count,0) as blocked_count,
          coalesce(dpc.do_not_pay_count,0) as do_not_pay_count,

          -- ✅ bank readiness
          cr.candidate_has_bank_details,
          cr.candidate_bank_hash,
          cr.umbrella_has_bank_details,
          cr.umbrella_bank_hash,

          -- ✅ loan catch-up (legacy schedule)
          coalesce(ld.loan_due_total,0) as loan_due_total,
          coalesce(ld.loan_due_entries,'[]'::jsonb) as loan_due_entries,

          -- ✅ Policy B: overpayment + loan state (week-to-date)
          coalesce(ob.overpayment_balance_remaining,0) as overpayment_balance_remaining,
          coalesce(ldtw.loan_due_this_week,0) as loan_due_this_week,
          coalesce(lrw.loan_repaid_wtd,0) as loan_repaid_wtd,
          coalesce(cand.min_take_home_wtd,0) as min_take_home_wtd,
          round(
            case
              when cr.cand_pay_method = 'UMBRELLA' then
                least(
                  greatest(coalesce(ldtw.loan_due_this_week,0) - coalesce(lrw.loan_repaid_wtd,0),0),
                  greatest(
                    least(
                      -- earnings_after_recovery
                      (greatest(cr.non_mismatch_total_ex,0) - least(coalesce(ob.overpayment_balance_remaining,0), greatest(cr.non_mismatch_total_ex,0))),
                      -- above-floor cap
                      (coalesce(pwb.paid_wtd_before,0) + (greatest(cr.non_mismatch_total_ex,0) - least(coalesce(ob.overpayment_balance_remaining,0), greatest(cr.non_mismatch_total_ex,0)))) - coalesce(cand.min_take_home_wtd,0)
                    ),
                    0
                  )
                )
              else null
            end,
            2
          ) as max_possible_loan_take_this_run,
          case when cr.cand_pay_method = 'PAYE' then 'NET_REQUIRED' else 'NOT_REQUIRED' end as paye_net_status
        from candidate_rollup cr
        left join blocked_counts bc on bc.candidate_id = cr.candidate_id
        left join do_not_pay_counts dpc on dpc.candidate_id = cr.candidate_id
        left join loan_due ld on ld.candidate_id = cr.candidate_id
        left join overpayment_balances ob on ob.candidate_id = cr.candidate_id
        left join loan_due_this_week ldtw on ldtw.candidate_id = cr.candidate_id
        left join loan_repaid_wtd lrw on lrw.candidate_id = cr.candidate_id
        left join paid_wtd_before pwb on pwb.candidate_id = cr.candidate_id
        left join public.candidates cand on cand.id = cr.candidate_id
  
  ;

  create temporary table payee_baseline_rows on commit drop as
        select
          'CANDIDATE'::text as payee_entity_kind,
          ce.candidate_id as payee_entity_id,
          nullif(btrim(coalesce(ce.candidate_bank_hash,'')), '') as bank_details_hash
        from cand_enriched ce
        union all
        select
          'UMBRELLA'::text as payee_entity_kind,
          ce.cand_umbrella_id as payee_entity_id,
          nullif(btrim(coalesce(ce.umbrella_bank_hash,'')), '') as bank_details_hash
        from cand_enriched ce
        where ce.cand_umbrella_id is not null
        union all
        select
          'CANDIDATE'::text as payee_entity_kind,
          fcb.candidate_id as payee_entity_id,
          nullif(btrim(coalesce(obd.bank_details_hash,'')), '') as bank_details_hash
        from finance_case_baseline_scope fcb
        join public.pay_finance_case_oneoff_payout_bank_details obd
          on obd.finance_case_id = fcb.finance_case_id
        where fcb.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
        union all
        select
          case
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then 'UMBRELLA'
            else 'CANDIDATE'
          end as payee_entity_kind,
          case
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then c_fc.umbrella_id
            else fcb.candidate_id
          end as payee_entity_id,
          case
            when fcb.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then nullif(btrim(coalesce(obd.bank_details_hash,'')), '')
            when fcb.routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then nullif(btrim(coalesce(u_fc.bank_details_hash,'')), '')
            else nullif(btrim(coalesce(c_fc.bank_details_hash,'')), '')
          end as bank_details_hash
        from finance_case_baseline_scope fcb
        join public.candidates c_fc
          on c_fc.id = fcb.candidate_id
        left join public.umbrellas u_fc
          on u_fc.id = c_fc.umbrella_id
        left join public.pay_finance_case_oneoff_payout_bank_details obd
          on obd.finance_case_id = fcb.finance_case_id
  
  ;

  create temporary table payees_src on commit drop as
        select
          pbr.payee_entity_kind,
          pbr.payee_entity_id,
          pbr.bank_details_hash
        from payee_baseline_rows pbr
        where pbr.payee_entity_id is not null
  
  ;

  create temporary table payees on commit drop as
        select
          upper(btrim(coalesce(ps.payee_entity_kind,''))) as payee_entity_kind,
          ps.payee_entity_id as payee_entity_id,
          ps.bank_details_hash as bank_details_hash
        from payees_src ps
        where ps.payee_entity_id is not null
        group by 1,2,3
  
  ;

  create temporary table payees_enriched on commit drop as
        select
          p.payee_entity_kind,
          p.payee_entity_id,
          p.bank_details_hash,

          b.payee_name,
          b.account_holder,
          b.bank_name,
          b.sort_code,
          b.account_number,
          b.account_type,

          coalesce(bnc.status, 'UNVERIFIED') as name_check_status,
          bnc.checked_at_utc as name_check_checked_at_utc,
          bnc.override_reason as name_check_override_reason,
          bnc.override_by_user_id as name_check_override_by_user_id,
          bnc.override_at_utc as name_check_override_at_utc,
          bnc.override_hash as name_check_override_hash,
          (bnc.override_reason is not null and bnc.override_hash = p.bank_details_hash) as name_check_has_override,

          bpm.payee_id as payee_map_payee_id,
          bpm.payee_account_id as payee_map_payee_account_id,
          bpm.meta_json as payee_map_meta_json,
          (bpm.payee_id is not null) as payee_map_present,

          b.is_missing_bank_details as is_missing_bank_details,
          (p.payee_entity_kind = 'UMBRELLA' and coalesce(u_pay.enabled, false) = false) as is_umbrella_inactive,

          (
            v_need_name_check = true
            and b.is_missing_bank_details = false
            and coalesce(bnc.status, 'UNVERIFIED') <> 'PASS'
            and not (bnc.override_reason is not null and bnc.override_hash = p.bank_details_hash)
          ) as is_name_check_blocked,

          (
            v_requires_payee_map = true
            and b.is_missing_bank_details = false
            and (bpm.payee_id is null)
          ) as is_payee_map_blocked
        from payees p
        left join public.candidates c_pay
          on p.payee_entity_kind = 'CANDIDATE'
         and c_pay.id = p.payee_entity_id
        left join public.umbrellas u_pay
          on p.payee_entity_kind = 'UMBRELLA'
         and u_pay.id = p.payee_entity_id
        left join lateral (
          select
            vfcr_oneoff.finance_case_id,
            obd.beneficiary_name,
            obd.sort_code,
            obd.account_number,
            obd.bank_details_hash
          from finance_case_baseline_scope vfcr_oneoff
          join public.pay_finance_case_oneoff_payout_bank_details obd
            on obd.finance_case_id = vfcr_oneoff.finance_case_id
          where p.payee_entity_kind = 'CANDIDATE'
            and vfcr_oneoff.candidate_id = p.payee_entity_id
            and vfcr_oneoff.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
            and obd.bank_details_hash is not distinct from p.bank_details_hash
          order by vfcr_oneoff.finance_case_id
          limit 1
        ) obd_pay on true

        left join lateral (
          select
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
              when p.payee_entity_kind = 'CANDIDATE' then c_pay.display_name
              else u_pay.name
            end as payee_name,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
              when p.payee_entity_kind = 'CANDIDATE' then c_pay.account_holder
              else u_pay.name
            end as account_holder,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then null::text
              else coalesce(c_pay.bank_name, u_pay.bank_name)
            end as bank_name,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.sort_code
              else coalesce(c_pay.sort_code, u_pay.sort_code)
            end as sort_code,
            case
              when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.account_number
              else coalesce(c_pay.account_number, u_pay.account_number)
            end as account_number,
            case
              when p.payee_entity_kind = 'CANDIDATE' then 'personal'
              else 'business'
            end as account_type,
            (
              p.bank_details_hash is null
              or btrim(p.bank_details_hash) = ''
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.beneficiary_name
                      when p.payee_entity_kind = 'CANDIDATE' then c_pay.account_holder
                      else u_pay.name
                    end,
                    ''
                  )), '') is null
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.sort_code
                      else coalesce(c_pay.sort_code, u_pay.sort_code)
                    end,
                    ''
                  )), '') is null
              or nullif(btrim(coalesce(
                    case
                      when p.payee_entity_kind = 'CANDIDATE' and obd_pay.finance_case_id is not null then obd_pay.account_number
                      else coalesce(c_pay.account_number, u_pay.account_number)
                    end,
                    ''
                  )), '') is null
            ) as is_missing_bank_details
        ) b on true

        left join public.bank_name_checks bnc
          on bnc.rail_provider = v_rail_provider_default
         and bnc.rail_env = v_rail_env_default
         and bnc.entity_kind = p.payee_entity_kind
         and bnc.entity_id = p.payee_entity_id
         and bnc.bank_details_hash is not distinct from p.bank_details_hash
        left join public.bank_payee_map bpm
          on bpm.rail_provider = v_rail_provider_default
         and bpm.rail_env = v_rail_env_default
         and bpm.entity_kind = p.payee_entity_kind
         and bpm.entity_id = p.payee_entity_id
         and bpm.bank_details_hash is not distinct from p.bank_details_hash
  
  ;

  create temporary table payees_json on commit drop as
        select
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'payee_entity_kind', pe.payee_entity_kind,
                'payee_entity_id', pe.payee_entity_id::text,
                'bank_details_hash', pe.bank_details_hash,

                -- ✅ Bank fields required to call the rail
                'payee_name', pe.payee_name,
                'account_holder', pe.account_holder,
                'bank_name', pe.bank_name,
                'sort_code', pe.sort_code,
                'account_number', pe.account_number,
                'account_type', pe.account_type,

                -- ✅ Name-check details (status + timestamps + override metadata)
                'name_check', jsonb_build_object(
                  'status', pe.name_check_status,
                  'checked_at_utc', pe.name_check_checked_at_utc,
                  'has_override', (pe.name_check_has_override = true),
                  'override_reason', pe.name_check_override_reason,
                  'override_by_user_id', case when pe.name_check_override_by_user_id is null then null else pe.name_check_override_by_user_id::text end,
                  'override_at_utc', pe.name_check_override_at_utc,
                  'override_hash', pe.name_check_override_hash
                ),

                -- ✅ Payee map details (presence + IDs)
                'payee_map', jsonb_build_object(
                  'present', (pe.payee_map_present = true),
                  'payee_id', pe.payee_map_payee_id,
                  'payee_account_id', pe.payee_map_payee_account_id
                ),

                'blockers',
                  (
                    (case when pe.is_missing_bank_details then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
                    ||
                    (case when pe.is_umbrella_inactive then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE') else '[]'::jsonb end)
                    ||
                    (case when pe.is_name_check_blocked then jsonb_build_array('BLOCKED_NAME_CHECK') else '[]'::jsonb end)
                    ||
                    (case when pe.is_payee_map_blocked then jsonb_build_array('BLOCKED_NO_PAYEE_MAP') else '[]'::jsonb end)
                  )
              )
              order by pe.payee_entity_kind, pe.payee_entity_id::text
            ),
            '[]'::jsonb
          ) as payees
        from payees_enriched pe
  
  ;

  create temporary table cand_payee0 on commit drop as
        select
          ce.*,
          case when ce.cand_pay_method = 'PAYE' then 'CANDIDATE' else 'UMBRELLA' end as payee_entity_kind,
          case when ce.cand_pay_method = 'PAYE' then ce.candidate_id else ce.cand_umbrella_id end as payee_entity_id,
          case when ce.cand_pay_method = 'PAYE' then nullif(btrim(coalesce(ce.candidate_bank_hash,'')), '') else nullif(btrim(coalesce(ce.umbrella_bank_hash,'')), '') end as payee_bank_hash
        from cand_enriched ce
  
  ;

  create temporary table cand_payee on commit drop as
        select
          cp.*,

          coalesce(pe.name_check_status, 'UNVERIFIED') as payee_name_check_status,
          coalesce(pe.name_check_has_override, false) as payee_name_check_has_override,
          coalesce(pe.payee_map_present, false) as payee_map_present,

          (
            (case when (cp.payee_entity_id is null or cp.payee_bank_hash is null or btrim(cp.payee_bank_hash) = '') then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
            ||
            (case
               when (cp.payee_entity_kind = 'UMBRELLA' and coalesce(cp.umb_enabled, false) = false)
               then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE')
               else '[]'::jsonb
             end)
            ||
            (case
               when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_need_name_check = true and coalesce(pe.name_check_status,'UNVERIFIED') <> 'PASS' and not coalesce(pe.name_check_has_override,false))
               then jsonb_build_array('BLOCKED_NAME_CHECK')
               else '[]'::jsonb
             end)
            ||
            (case
               when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_requires_payee_map = true and not coalesce(pe.payee_map_present,false))
               then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
               else '[]'::jsonb
             end)
          ) as blockers,

          (
            jsonb_array_length(
              (
                (case when (cp.payee_entity_id is null or cp.payee_bank_hash is null or btrim(cp.payee_bank_hash) = '') then jsonb_build_array('BLOCKED_BANK_DETAILS') else '[]'::jsonb end)
                ||
                (case
                   when (cp.payee_entity_kind = 'UMBRELLA' and coalesce(cp.umb_enabled, false) = false)
                   then jsonb_build_array('BLOCKED_UMBRELLA_INACTIVE')
                   else '[]'::jsonb
                 end)
                ||
                (case
                   when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_need_name_check = true and coalesce(pe.name_check_status,'UNVERIFIED') <> 'PASS' and not coalesce(pe.name_check_has_override,false))
                   then jsonb_build_array('BLOCKED_NAME_CHECK')
                   else '[]'::jsonb
                 end)
                ||
                (case
                   when (cp.payee_entity_id is not null and cp.payee_bank_hash is not null and v_requires_payee_map = true and not coalesce(pe.payee_map_present,false))
                   then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
                   else '[]'::jsonb
                 end)
              )
            ) = 0
          ) as is_ready_for_draft
        from cand_payee0 cp
        left join payees_enriched pe
          on pe.payee_entity_kind = cp.payee_entity_kind
         and pe.payee_entity_id = cp.payee_entity_id
         and pe.bank_details_hash is not distinct from cp.payee_bank_hash
  
  ;

  create temporary table timesheet_case_rollup_effective on commit drop as
        select
          tcr.candidate_id,
          tcr.timesheet_id,
          tcr.client_id,
          tcr.ts_week_ending_date,
          tcr.ts_client_name,
          tcr.ts_pay_method,
          tcr.cand_pay_method,
          tcr.cand_tms_ref,
          tcr.cand_display_name,
          tcr.cand_umbrella_id,
          tcr.umb_enabled,
          tcr.umb_vat_chargeable,
          tcr.candidate_has_bank_details,
          tcr.candidate_bank_hash,
          tcr.umbrella_has_bank_details,
          tcr.umbrella_bank_hash,
          tcr.resolution_family,
          tcr.case_needs_resolution,
          tcr.case_resolution_satisfied_now,
          tcr.resolution_action_label,
          tcr.linked_resolution_scope_json,
          tcr.case_total_amount_ex,
          case
            when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
            then 0::numeric
            else tcr.safe_amount_ex
          end as safe_amount_ex,
          tcr.unresolved_taxable_amount_ex,
          tcr.open_taxable_count,
          tcr.open_reimbursement_count,
          tcr.unresolved_taxable_count,
          tcr.stale_count,
          tcr.is_mixed_case,
          (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false)) as is_blocked,
          tcr.segments_total_ex,
          tcr.delta_additional_pay_ex_vat,
          tcr.delta_expenses_pay_ex_vat,
          tcr.delta_travel_pay_ex_vat,
          tcr.delta_accommodation_pay_ex_vat,
          tcr.delta_other_pay_ex_vat,
          tcr.delta_mileage_pay_ex_vat,
          tcr.segment_deltas_json,
          tcr.adjustment_deltas_json,
          tcr.additional_unit_deltas_json,
          tcr.reservation_overrun_detected,
          tcr.payment_amount_ex_vat,
          tcr.payment_amount_inc_vat,
          tcr.payment_amount,
          (
            coalesce(tcr.case_resolution_summary_json, '{}'::jsonb)
            || jsonb_build_object(
              'is_blocked', (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false)),
              'resolution_family', tcr.resolution_family,
              'case_needs_resolution', tcr.case_needs_resolution,
              'case_resolution_satisfied_now', (tcr.case_resolution_satisfied_now and coalesce(cp.is_ready_for_draft, false)),
              'resolution_action_label', tcr.resolution_action_label,
              'linked_resolution_scope_json', tcr.linked_resolution_scope_json,
              'safe_amount_ex_vat', case
                when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
                then 0::numeric
                else coalesce(tcr.case_total_amount_ex, 0)
              end,
              'blocked_case_amount_ex_vat', case
                when (coalesce(tcr.is_blocked, false) or not coalesce(cp.is_ready_for_draft, false))
                then coalesce(tcr.case_total_amount_ex, 0)
                else 0::numeric
              end,
              'blocked_reason_codes', case
                when coalesce(tcr.is_blocked, false) = true then jsonb_build_array('BLOCKED_TAXABLE_RESOLUTION')
                else '[]'::jsonb
              end
            )
          ) as case_resolution_summary_json,
          tcr.case_components_json
        from timesheet_case_rollup_payable tcr
        left join cand_payee cp
          on cp.candidate_id = tcr.candidate_id
  
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'candidate_rollup_count', (select count(*)::int from candidate_rollup),
    'payee_count', (select count(*)::int from payees_enriched),
    'candidate_payee_count', (select count(*)::int from cand_payee),
    'timesheet_case_rollup_effective_count', (select count(*)::int from timesheet_case_rollup_effective)
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_summary_fragment(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_paye jsonb := '[]'::jsonb;
  v_nonpaye jsonb := '[]'::jsonb;
  v_blocked jsonb := '[]'::jsonb;
  v_do_not_pay jsonb := '[]'::jsonb;
  v_snoozed jsonb := '[]'::jsonb;
  v_payees jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_canonical_preview_lines jsonb := '[]'::jsonb;
  v_paye_summary_breakdown jsonb := '{}'::jsonb;
  v_case_resolution_states jsonb := '[]'::jsonb;
  v_candidate_row jsonb := '{}'::jsonb;
  v_itemisation jsonb := '[]'::jsonb;
  v_baseline_component_rows jsonb := '[]'::jsonb;
  v_hidden_recovery_template_lines jsonb := '[]'::jsonb;
  v_filtered_canonical_preview_lines jsonb := '[]'::jsonb;
  v_carry_forward_itemisation jsonb := '[]'::jsonb;
  v_carry_forward_total_ex_vat numeric := 0;
  v_carry_forward_total_vat numeric := 0;
  v_carry_forward_total_inc_vat numeric := 0;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (ctx.candidate_id is not distinct from v_candidate_id and ctx.context_json = v_context_json)
    into v_context_matches
    from pg_temp.pay_preview_candidate_context ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.canonical_preview_lines') is null then
    perform public.pay_preview_candidate_build_canonical_lines(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk,
    ctx.pay_eligibility_months_back,
    ctx.pay_eligibility_weeks_ahead,
    ctx.eligibility_from_date,
    ctx.eligibility_to_date,
    ctx.vat_rate_pct,
    ctx.erni_pct,
    ctx.rail_provider_default,
    ctx.rail_env_default,
    ctx.rail_supports_scheduling,
    ctx.rail_supports_name_check,
    ctx.rail_supports_auto_execute,
    ctx.default_schedule_umbrella_local,
    ctx.default_schedule_paye_local,
    ctx.funds_warning_hours_json,
    ctx.need_name_check,
    ctx.requires_payee_map,
    ctx.paye_guardrails
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk,
    v_pay_eligibility_months_back,
    v_pay_eligibility_weeks_ahead,
    v_eligibility_from_date,
    v_eligibility_to_date,
    v_vat_rate_pct,
    v_erni_pct,
    v_rail_provider_default,
    v_rail_env_default,
    v_rail_supports_scheduling,
    v_rail_supports_name_check,
    v_rail_supports_auto_execute,
    v_default_schedule_umbrella_local,
    v_default_schedule_paye_local,
    v_funds_warning_hours_json,
    v_need_name_check,
    v_requires_payee_map,
    v_paye_guardrails
  from pg_temp.pay_preview_candidate_context ctx
  limit 1;

  drop table if exists pg_temp.summary_json, pg_temp.timesheet_case_states_flat, pg_temp.finance_case_states_flat, pg_temp.candidate_case_states_flat, pg_temp.candidate_case_states, pg_temp.case_resolution_states_json, pg_temp.finance_candidate_totals, pg_temp.candidate_finance_itemisation, pg_temp.candidate_timesheet_itemisation_merged, pg_temp.paye_summary_breakdown_json, pg_temp.timesheet_baseline_component_rows, pg_temp.finance_baseline_component_rows, pg_temp.baseline_component_rows_json;

  create temporary table summary_json on commit drop as
        select
          jsonb_build_object(
            'readiness', jsonb_build_object(
              'payees_total', pr.payees_total,
              'payees_need_name_check', pr.payees_need_name_check,
              'payees_need_payee_map', pr.payees_need_payee_map,
              'payees_missing_bank_details', pr.payees_missing_bank_details
            ),
            'candidates', jsonb_build_object(
              'ready_count', cr.ready_count,
              'review_required_count', cr.review_required_count,
              'total_candidates', cr.total_candidates
            )
          ) as summary
        from (
          select
            count(*)::int as payees_total,
            sum(case when pe.is_missing_bank_details then 1 else 0 end)::int as payees_missing_bank_details,
            sum(case when pe.is_name_check_blocked then 1 else 0 end)::int as payees_need_name_check,
            sum(case when pe.is_payee_map_blocked then 1 else 0 end)::int as payees_need_payee_map
          from payees_enriched pe
        ) pr
        cross join (
          select
            count(*)::int as total_candidates,
            sum(
              case when
                (
                  (coalesce(cp.non_mismatch_total_ex,0) <> 0
                   or coalesce(cp.mismatch_source_paye_ex,0) <> 0
                   or coalesce(cp.mismatch_source_umbrella_ex,0) <> 0)
                  and cp.is_ready_for_draft = true
                  and coalesce(cp.blocked_count,0) = 0
                  and coalesce(cp.do_not_pay_count,0) = 0
                  and cp.has_mismatch = false
                )
              then 1 else 0 end
            )::int as ready_count,
            sum(
              case when
                (
                  (coalesce(cp.non_mismatch_total_ex,0) <> 0
                   or coalesce(cp.mismatch_source_paye_ex,0) <> 0
                   or coalesce(cp.mismatch_source_umbrella_ex,0) <> 0)
                  and (
                    cp.has_mismatch = true
                    or jsonb_array_length(cp.blockers) > 0
                    or coalesce(cp.blocked_count,0) > 0
                    or coalesce(cp.do_not_pay_count,0) > 0
                  )
                )
              then 1 else 0 end
            )::int as review_required_count
          from cand_payee cp
        ) cr
  
  ;

  create temporary table timesheet_case_states_flat on commit drop as
        select
          tcr.candidate_id,
          tcr.cand_display_name as sort_candidate_display,
          tcr.cand_tms_ref as sort_candidate_tms_ref,
          1 as sort_case_order,
          ('timesheet:' || tcr.timesheet_id::text) as case_key,
          true as is_blocked,
          jsonb_build_object(
            'case_key', ('timesheet:' || tcr.timesheet_id::text),
            'case_scope', 'TIMESHEET_PAYMENT',
            'finance_case_id', null,
            'case_type', 'TIMESHEET_PAYMENT',
            'timesheet_id', tcr.timesheet_id::text,
            'candidate_id', tcr.candidate_id::text,
            'client_id', case when tcr.client_id is null then null else tcr.client_id::text end,
            'client_name', tcr.ts_client_name,
            'week_ending_date', case when tcr.ts_week_ending_date is null then null else tcr.ts_week_ending_date::text end,
            'source_pay_method', tcr.ts_pay_method,
            'candidate_pay_method', tcr.cand_pay_method,
            'resolution_family', tcr.resolution_family,
            'case_needs_resolution', tcr.case_needs_resolution,
            'case_resolution_satisfied_now', tcr.case_resolution_satisfied_now,
            'resolution_action_label', tcr.resolution_action_label,
            'linked_resolution_scope_json', tcr.linked_resolution_scope_json,
            'is_blocked', true,
            'is_mixed_case', tcr.is_mixed_case,
            'open_taxable_count', tcr.open_taxable_count,
            'open_reimbursement_count', tcr.open_reimbursement_count,
            'unresolved_taxable_count', tcr.unresolved_taxable_count,
            'stale_count', tcr.stale_count,
            'safe_amount_ex_vat', tcr.safe_amount_ex,
            'unresolved_taxable_amount_ex_vat', tcr.unresolved_taxable_amount_ex,
            'case_resolution_summary', tcr.case_resolution_summary_json,
            'components', tcr.case_components_json
          ) as case_json
        from timesheet_case_rollup_effective tcr
        where coalesce(tcr.case_needs_resolution, false) = true
          and coalesce(tcr.case_resolution_satisfied_now, false) = false
  
  ;

  create temporary table finance_case_states_flat on commit drop as
        select
          fcrr.candidate_id,
          fcrr.cand_display_name as sort_candidate_display,
          fcrr.cand_tms_ref as sort_candidate_tms_ref,
          2 as sort_case_order,
          ('finance:' || fcrr.finance_case_id::text) as case_key,
          true as is_blocked,
          jsonb_build_object(
            'case_key', ('finance:' || fcrr.finance_case_id::text),
            'case_scope', 'FINANCE_CASE',
            'finance_case_id', fcrr.finance_case_id::text,
            'timesheet_id', case when fcrr.linked_timesheet_id is null then null else fcrr.linked_timesheet_id::text end,
            'candidate_id', fcrr.candidate_id::text,
            'client_id', case when fcrr.client_id is null then null else fcrr.client_id::text end,
            'client_name', fcrr.client_name,
            'linked_shift_date', case when fcrr.linked_shift_date is null then null else fcrr.linked_shift_date::text end,
            'next_due_week_start', case when fcrr.next_due_week_start is null then null else fcrr.next_due_week_start::text end,
            'case_type', fcrr.case_type::text,
            'candidate_pay_method', fcrr.candidate_pay_method,
            'taxability', case when fcrr.taxability is null then null else fcrr.taxability::text end,
            'routing_kind', case when fcrr.routing_kind is null then null else fcrr.routing_kind::text end,
            'destination_label', fcrr.destination_label,
            'resolution_family', fcrr.resolution_family,
            'case_needs_resolution', fcrr.case_needs_resolution,
            'case_resolution_satisfied_now', fcrr.case_resolution_satisfied_now,
            'resolution_action_label', fcrr.resolution_action_label,
            'linked_resolution_scope_json', fcrr.linked_resolution_scope_json,
            'blocked_reason_codes', fcrr.blocked_reason_codes,
            'snooze_allowed', fcrr.snooze_allowed,
            'is_blocked', true,
            'is_mixed_case', fcrr.is_mixed_case,
            'open_taxable_count', fcrr.open_taxable_count,
            'open_reimbursement_count', fcrr.open_reimbursement_count,
            'unresolved_taxable_count', fcrr.unresolved_taxable_count,
            'stale_count', fcrr.stale_count,
            'due_amount_ex_vat', fcrr.due_amount_ex_vat,
            'case_resolution_summary', fcrr.case_resolution_summary_json,
            'components', fcrr.case_components_json
          ) || jsonb_strip_nulls(
            jsonb_build_object(
              'taxable_manual_debt_resolution', fcrr.taxable_manual_debt_resolution_json
            )
          ) as case_json
        from finance_case_resolution_rollup fcrr
        where fcrr.due_amount_ex_vat > 0
          and coalesce(fcrr.case_needs_resolution, false) = true
          and coalesce(fcrr.case_resolution_satisfied_now, false) = false
  
  ;

  create temporary table candidate_case_states_flat on commit drop as
        select
          tcsf.candidate_id,
          tcsf.sort_candidate_display,
          tcsf.sort_candidate_tms_ref,
          tcsf.sort_case_order,
          tcsf.case_key,
          tcsf.is_blocked,
          tcsf.case_json
        from timesheet_case_states_flat tcsf

        union all

        select
          fcsf.candidate_id,
          fcsf.sort_candidate_display,
          fcsf.sort_candidate_tms_ref,
          fcsf.sort_case_order,
          fcsf.case_key,
          fcsf.is_blocked,
          fcsf.case_json
        from finance_case_states_flat fcsf
  
  ;

  create temporary table candidate_case_states on commit drop as
        select
          ccsf.candidate_id,
          count(*)::int as total_case_count,
          sum(case when ccsf.is_blocked then 1 else 0 end)::int as blocked_case_count,
          sum(case when ccsf.is_blocked then 0 else 1 end)::int as safe_case_count,
          coalesce(jsonb_agg(ccsf.case_json order by ccsf.sort_case_order, ccsf.case_key), '[]'::jsonb) as case_resolution_states
        from candidate_case_states_flat ccsf
        group by ccsf.candidate_id
  
  ;

  create temporary table case_resolution_states_json on commit drop as
        select coalesce(jsonb_agg(ccsf.case_json order by ccsf.sort_candidate_display nulls last, ccsf.sort_candidate_tms_ref nulls last, ccsf.sort_case_order, ccsf.case_key), '[]'::jsonb) as payload
        from candidate_case_states_flat ccsf
  
  ;

  create temporary table finance_candidate_totals on commit drop as
        select
          fcrr.candidate_id,
          round(sum(case when fcrr.due_amount_ex_vat > 0 then fcrr.due_amount_ex_vat else 0 end), 2) as finance_due_total_ex_vat,
          round(sum(case when fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = false then fcrr.due_amount_ex_vat else 0 end), 2) as finance_safe_due_total_ex_vat,
          round(sum(case when fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = true then fcrr.due_amount_ex_vat else 0 end), 2) as finance_blocked_due_total_ex_vat,
          count(*) filter (where fcrr.due_amount_ex_vat > 0) as finance_due_case_count,
          count(*) filter (where fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = false) as finance_safe_case_count,
          count(*) filter (where fcrr.due_amount_ex_vat > 0 and fcrr.is_blocked = true) as finance_blocked_case_count
        from finance_case_resolution_rollup fcrr
        where fcrr.due_amount_ex_vat > 0
        group by fcrr.candidate_id
  
  ;

  create temporary table candidate_finance_itemisation on commit drop as
        select
          fcl.candidate_id,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'finance_case_id', fcl.finance_case_id::text,
                'case_key', ('finance:' || fcl.finance_case_id::text),
                'case_type', fcl.case_type::text,
                'line_type', fcl.line_type,
                'item_type_label', fcl.item_type_label,
                'item_direction', fcl.item_direction,
                'client_id', case when fcl.client_id is null then null else fcl.client_id::text end,
                'client_name', fcl.client_name,
                'linked_shift_date', case when fcl.linked_shift_date is null then null else fcl.linked_shift_date::text end,
                'next_due_week_start', case when fcl.next_due_week_start is null then null else fcl.next_due_week_start::text end,
                'taxability', case when fcl.taxability is null then null else fcl.taxability::text end,
                'routing_kind', case when fcl.routing_kind is null then null else fcl.routing_kind::text end,
                'destination_label', fcl.destination_label,
                'amount_ex_vat', fcl.signed_amount_ex_vat,
                'amount_display', fcl.signed_amount_ex_vat,
                'paye_treatment', fcl.paye_treatment,
                'presentation_section', fcl.readiness_state,
                'case_resolution_summary', fcl.case_resolution_summary_json,
                'components', fcl.case_components_json
              ) || jsonb_strip_nulls(
                jsonb_build_object(
                  'taxable_manual_debt_resolution', fcl.taxable_manual_debt_resolution_json
                )
              )
              order by fcl.case_type::text, fcl.finance_case_id
            ),
            '[]'::jsonb
          ) as finance_itemisation
        from finance_case_lines fcl
        group by fcl.candidate_id
  
  ;

  create temporary table candidate_timesheet_itemisation_merged on commit drop as
        select
          ce.candidate_id,
          (
            coalesce(
              (
                select
                  jsonb_agg(
                    case
                      when ready_match.ready_item is null then base_items.base_item
                      else (base_items.base_item || ready_match.ready_item)
                    end
                    order by base_items.base_ord
                  )
                from (
                  select
                    base_entry.base_ord,
                    base_entry.base_item,
                    coalesce(
                      nullif(btrim(coalesce(base_entry.base_item->>'case_key', '')), ''),
                      case
                        when nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), '') is null then null
                        else ('timesheet:' || nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), ''))
                      end
                    ) as match_key
                  from jsonb_array_elements(coalesce(ce.timesheets_itemisation, '[]'::jsonb)) with ordinality as base_entry(base_item, base_ord)
                ) base_items
                left join lateral (
                  select
                    ready_items.ready_item
                  from (
                    select
                      ready_entry.ready_item,
                      ready_entry.ready_ord,
                      coalesce(
                        nullif(btrim(coalesce(ready_entry.ready_item->>'case_key', '')), ''),
                        case
                          when nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), '') is null then null
                          else ('timesheet:' || nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), ''))
                        end
                      ) as match_key
                    from jsonb_array_elements(coalesce(cptr.ready_timesheets_itemisation, '[]'::jsonb)) with ordinality as ready_entry(ready_item, ready_ord)
                  ) ready_items
                  where ready_items.match_key is not null
                    and ready_items.match_key = base_items.match_key
                  order by ready_items.ready_ord
                  limit 1
                ) ready_match on true
              ),
              '[]'::jsonb
            )
            ||
            coalesce(
              (
                select
                  jsonb_agg(ready_items.ready_item order by ready_items.ready_ord)
                from (
                  select
                    ready_entry.ready_item,
                    ready_entry.ready_ord,
                    coalesce(
                      nullif(btrim(coalesce(ready_entry.ready_item->>'case_key', '')), ''),
                      case
                        when nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), '') is null then null
                        else ('timesheet:' || nullif(btrim(coalesce(ready_entry.ready_item->>'timesheet_id', '')), ''))
                      end
                    ) as match_key
                  from jsonb_array_elements(coalesce(cptr.ready_timesheets_itemisation, '[]'::jsonb)) with ordinality as ready_entry(ready_item, ready_ord)
                ) ready_items
                where not exists (
                  select 1
                  from (
                    select
                      coalesce(
                        nullif(btrim(coalesce(base_entry.base_item->>'case_key', '')), ''),
                        case
                          when nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), '') is null then null
                          else ('timesheet:' || nullif(btrim(coalesce(base_entry.base_item->>'timesheet_id', '')), ''))
                        end
                      ) as match_key
                    from jsonb_array_elements(coalesce(ce.timesheets_itemisation, '[]'::jsonb)) with ordinality as base_entry(base_item, base_ord)
                  ) base_keys
                  where base_keys.match_key is not null
                    and base_keys.match_key = ready_items.match_key
                )
              ),
              '[]'::jsonb
            )
          ) as merged_timesheets_itemisation
        from cand_payee ce
        left join candidate_preview_timesheet_rollup cptr
          on cptr.candidate_id = ce.candidate_id

  ;

  create temporary table paye_summary_breakdown_json on commit drop as
        select jsonb_build_object(
          'gross_side_additions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'GROSS_ADD' and cpl.is_excluded_from_allocation = false then greatest(cpl.amount_ex_vat,0) else 0 end),0),2),
          'gross_side_deductions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'GROSS_DEDUCT' and cpl.is_excluded_from_allocation = false then abs(cpl.amount_ex_vat) else 0 end),0),2),
          'net_side_additions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'NET_ADD' and cpl.is_excluded_from_allocation = false then greatest(cpl.amount_ex_vat,0) else 0 end),0),2),
          'net_side_deductions_ex_vat', round(coalesce(sum(case when cpl.pay_channel = 'PAYE' and cpl.paye_treatment = 'NET_DEDUCT' and cpl.is_excluded_from_allocation = false then abs(cpl.amount_ex_vat) else 0 end),0),2)
        ) as payload
        from canonical_preview_lines cpl
  
  ;

  create temporary table timesheet_baseline_component_rows on commit drop as
        select
          1 as sort_scope,
          ('timesheet:' || ttr.timesheet_id::text) as sort_case_key,
          coalesce(ttr.component_fingerprint, '') as sort_component_fingerprint,
          coalesce(ttr.component_key_type, '') as sort_component_key_type,
          coalesce(ttr.component_key_value, '') as sort_component_key_value,
          jsonb_strip_nulls(
            jsonb_build_object(
              'component_scope', 'TIMESHEET',
              'candidate_id', ttr.candidate_id::text,
              'case_key', ('timesheet:' || ttr.timesheet_id::text),
              'timesheet_id', ttr.timesheet_id::text,
              'finance_case_id', null,
              'finance_component_id', null,
              'source_family_key', ttr.source_family_key,
              'component_key_type', ttr.component_key_type,
              'component_key_value', ttr.component_key_value,
              'bucket_code', nullif(btrim(coalesce(ttr.source_basis_json->>'bucket_code', '')), ''),
              'source_basis_json', coalesce(ttr.source_basis_json, '{}'::jsonb),
              'source_basis_fingerprint', case when coalesce(ttr.source_basis_json, '{}'::jsonb) <> '{}'::jsonb then md5(ttr.source_basis_json::text) else null::text end,
              'component_fingerprint', ttr.component_fingerprint,
              'classification', ttr.classification::text,
              'source_pay_method', ttr.source_pay_method,
              'current_target_pay_method', ttr.current_target_pay_method,
              'source_units', case when ttr.source_units is null then null else round(ttr.source_units, 6) end,
              'source_rate', case when ttr.source_rate is null then null else round(ttr.source_rate, 6) end,
              'source_charge_rate', case when ttr.source_charge_rate is null then null else round(ttr.source_charge_rate, 6) end,
              'component_amount_ex_vat', round(coalesce(ttr.component_amount_ex_vat, 0), 2),
              'source_charge_ex_vat', case when ttr.source_charge_ex_vat is null then null else round(ttr.source_charge_ex_vat, 2) end,
              'source_pay_ex_vat', case when ttr.source_pay_ex_vat is null then null else round(ttr.source_pay_ex_vat, 2) end,
              'source_margin_ex_vat', case when ttr.source_margin_ex_vat is null then null else round(ttr.source_margin_ex_vat, 2) end,
              'target_pay_ex_vat', case when ttr.target_pay_ex_vat is null then null else round(ttr.target_pay_ex_vat, 2) end,
              'target_charge_ex_vat', case when ttr.target_charge_ex_vat is null then null else round(ttr.target_charge_ex_vat, 2) end,
              'target_margin_ex_vat', case when ttr.target_margin_ex_vat is null then null else round(ttr.target_margin_ex_vat, 2) end,
              'requires_resolution', coalesce(ttr.requires_resolution, false),
              'case_resolution_satisfied_now_component', coalesce(ttr.case_resolution_satisfied_now_component, false),
              'has_suggested_resolution', coalesce(ttr.has_suggested_resolution, false),
              'suggestion_provenance', ttr.suggestion_provenance,
              'approved_resolution_mode', case when ttr.approved_resolution_mode is null then null else ttr.approved_resolution_mode::text end,
              'approved_target_rate', case when ttr.approved_target_rate is null then null else round(ttr.approved_target_rate, 6) end,
              'suggested_resolution_payload_json', ttr.suggested_resolution_payload_json,
              'suggested_resolution_result_json', ttr.suggested_resolution_result_json,
              'is_actionable_resolution_row', coalesce(ttr.is_actionable_resolution_row, false),
              'is_fixed_no_action_taxable_row', coalesce(ttr.is_fixed_no_action_taxable_row, false)
            )
          ) as row_json
        from transient_timesheet_component_review_rows_effective ttr
        where ttr.candidate_id = v_candidate_id
  
  ;

  create temporary table finance_baseline_component_rows on commit drop as
        select
          2 as sort_scope,
          ('finance:' || fcr.finance_case_id::text) as sort_case_key,
          coalesce(fcr.current_component_fingerprint, '') as sort_component_fingerprint,
          coalesce(fcr.component_key_type, '') as sort_component_key_type,
          coalesce(fcr.component_key_value, '') as sort_component_key_value,
          jsonb_strip_nulls(
            jsonb_build_object(
              'component_scope', 'FINANCE_CASE',
              'candidate_id', fcr.candidate_id::text,
              'case_key', ('finance:' || fcr.finance_case_id::text),
              'timesheet_id', null,
              'finance_case_id', fcr.finance_case_id::text,
              'finance_component_id', case when fcr.finance_component_id is null then null else fcr.finance_component_id::text end,
              'case_type', fcr.case_type::text,
              'taxability', case when fcr.taxability is null then null else fcr.taxability::text end,
              'source_family_key', fcr.source_family_key,
              'component_key_type', fcr.component_key_type,
              'component_key_value', fcr.component_key_value,
              'bucket_code', nullif(btrim(coalesce(fcr.source_basis_json->>'bucket_code', '')), ''),
              'source_basis_json', coalesce(fcr.source_basis_json, '{}'::jsonb),
              'source_basis_fingerprint', case when coalesce(fcr.source_basis_json, '{}'::jsonb) <> '{}'::jsonb then md5(fcr.source_basis_json::text) else null::text end,
              'component_fingerprint', fcr.current_component_fingerprint,
              'classification', fcr.classification::text,
              'source_pay_method', fcr.source_pay_method,
              'current_target_pay_method', fcr.current_target_pay_method,
              'saved_target_pay_method', fcr.saved_target_pay_method,
              'source_amount', round(coalesce(fcr.source_amount, 0), 2),
              'remaining_source_amount', round(coalesce(fcr.remaining_source_amount, 0), 2),
              'source_units', case when fcr.source_units is null then null else round(fcr.source_units, 6) end,
              'source_rate', case when fcr.source_rate is null then null else round(fcr.source_rate, 6) end,
              'source_charge_rate', case when fcr.source_charge_rate is null then null else round(fcr.source_charge_rate, 6) end,
              'source_charge_ex_vat', case when fcr.source_charge_component_ex_vat is null then null else round(fcr.source_charge_component_ex_vat, 2) end,
              'source_pay_ex_vat', case when fcr.source_pay_ex_vat is null then null else round(fcr.source_pay_ex_vat, 2) end,
              'source_margin_ex_vat', case when fcr.source_margin_ex_vat is null then null else round(fcr.source_margin_ex_vat, 2) end,
              'target_pay_ex_vat', case when fcr.target_pay_ex_vat is null then null else round(fcr.target_pay_ex_vat, 2) end,
              'target_charge_ex_vat', case when fcr.target_charge_ex_vat is null then null else round(fcr.target_charge_ex_vat, 2) end,
              'target_margin_ex_vat', case when fcr.target_margin_ex_vat is null then null else round(fcr.target_margin_ex_vat, 2) end,
              'approved_resolution_mode', case when fcr.approved_resolution_mode is null then null else fcr.approved_resolution_mode::text end,
              'approved_target_rate', case when fcr.approved_target_rate is null then null else round(fcr.approved_target_rate, 6) end,
              'approved_nonbucket_resolution_mode', case when fcr.approved_nonbucket_resolution_mode is null then null else fcr.approved_nonbucket_resolution_mode::text end,
              'approved_nonbucket_target_amount_ex_vat', case when fcr.approved_nonbucket_target_amount_ex_vat is null then null else round(fcr.approved_nonbucket_target_amount_ex_vat, 2) end,
              'saved_resolution_mode', case when fcr.saved_resolution_mode is null then null else fcr.saved_resolution_mode::text end,
              'saved_resolution_payload_json', fcr.saved_resolution_payload_json,
              'saved_resolution_result_json', fcr.saved_resolution_result_json,
              'resolution_fingerprint', fcr.resolution_fingerprint,
              'is_resolution_stale', coalesce(fcr.is_resolution_stale, false),
              'stale_reason', fcr.stale_reason,
              'requires_resolution', coalesce(fcr.requires_resolution, false),
              'case_resolution_satisfied_now_component', coalesce(fcr.case_resolution_satisfied_now_component, false),
              'suggested_resolution_payload_json', fcr.suggested_resolution_payload_json,
              'suggested_resolution_result_json', fcr.suggested_resolution_result_json,
              'is_actionable_resolution_row', coalesce(fcr.is_actionable_resolution_row, false),
              'is_fixed_no_action_taxable_row', coalesce(fcr.is_fixed_no_action_taxable_row, false)
            )
          ) as row_json
        from finance_case_component_review_rows_effective fcr
        where fcr.candidate_id = v_candidate_id
  
  ;

  create temporary table baseline_component_rows_json on commit drop as
        select
          coalesce(
            jsonb_agg(u.row_json order by u.sort_scope, u.sort_case_key, u.sort_component_fingerprint, u.sort_component_key_type, u.sort_component_key_value),
            '[]'::jsonb
          ) as payload
        from (
          select * from timesheet_baseline_component_rows
          union all
          select * from finance_baseline_component_rows
        ) u
  
  ;

  select
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'candidate_id', ce.candidate_id::text,
            'tms_ref', ce.cand_tms_ref,
            'display_name', ce.cand_display_name,
            'current_pay_method', ce.cand_pay_method,
            'umbrella_id', case when ce.cand_umbrella_id is null then null else ce.cand_umbrella_id::text end,
            'umbrella_enabled', ce.umb_enabled,
            'umbrella_vat_chargeable', ce.umb_vat_chargeable,

            'candidate_has_bank_details', ce.candidate_has_bank_details,
            'candidate_bank_hash', ce.candidate_bank_hash,
            'umbrella_has_bank_details', null,
            'umbrella_bank_hash', null,

            'payee_entity_kind', ce.payee_entity_kind,
            'payee_entity_id', case when ce.payee_entity_id is null then null else ce.payee_entity_id::text end,
            'payee_bank_hash', ce.payee_bank_hash,
            'payee_map_present', ce.payee_map_present,
            'name_check_status', ce.payee_name_check_status,
            'name_check_has_override', ce.payee_name_check_has_override,
            'blockers', ce.blockers,

            'blocked_count', ce.blocked_count,
            'do_not_pay_count', ce.do_not_pay_count,
            'blocked_case_count', coalesce(ccs.blocked_case_count, 0),
            'safe_case_count', coalesce(ccs.safe_case_count, 0),
            'preview_blocked_timesheet_count', coalesce(cptr.blocked_timesheet_preview_count, 0),
            'preview_ready_timesheet_count', coalesce(cptr.ready_timesheet_preview_count, 0),
            'case_resolution_states', coalesce(ccs.case_resolution_states, '[]'::jsonb),
            'gross_preview_ex_vat_non_mismatch', coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),
            'finance_due_total_ex_vat', coalesce(fct.finance_due_total_ex_vat,0),
            'finance_safe_due_total_ex_vat', coalesce(fct.finance_safe_due_total_ex_vat,0),
            'finance_blocked_due_total_ex_vat', coalesce(fct.finance_blocked_due_total_ex_vat,0),
            'mismatch', jsonb_build_object(
              'has_mismatch', ce.has_mismatch,
              'source_paye_ex_vat', ce.mismatch_source_paye_ex,
              'source_umbrella_ex_vat', ce.mismatch_source_umbrella_ex,
              'if_settle_via_paye_ex_vat',
                round(
                  ce.mismatch_source_paye_ex
                  + public._pay_convert_umbrella_to_paye_ex(ce.mismatch_source_umbrella_ex, v_erni_pct),
                  2
                ),
              'if_settle_via_umbrella',
                public._pay_convert_paye_to_umbrella(ce.mismatch_source_paye_ex, v_erni_pct, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
                ||
                public._pay_umbrella_vat_calc(ce.mismatch_source_umbrella_ex, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
            ),
            'overpayment_balance_remaining', ce.overpayment_balance_remaining,
            'loan_due_this_week', ce.loan_due_this_week,
            'loan_repaid_wtd', ce.loan_repaid_wtd,
            'min_take_home_wtd', ce.min_take_home_wtd,
            'max_possible_loan_take_this_run',
              round(
                case
                  when ce.cand_pay_method = 'UMBRELLA' then
                    least(
                      greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                      greatest(
                        least(
                          (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                          (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                        ),
                        0
                      )
                    )
                  else null
                end,
                2
              ),
            'paye_net_status', ce.paye_net_status,
            'loan', jsonb_build_object(
              'pay_week_start', v_week_start::text,
              'loan_due_total', ce.loan_due_total,
              'loan_due_entries', ce.loan_due_entries,
              'loan_due_this_week', ce.loan_due_this_week,
              'loan_repaid_wtd', ce.loan_repaid_wtd,
              'min_take_home_wtd', ce.min_take_home_wtd,
              'max_possible_loan_take_this_run',
                round(
                  case
                    when ce.cand_pay_method = 'UMBRELLA' then
                      least(
                        greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                        greatest(
                          least(
                            (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                            (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                          ),
                          0
                        )
                      )
                    else null
                  end,
                  2
                ),
              'paye_net_status', ce.paye_net_status,
              'cap_fields', jsonb_build_object(
                'min_take_home', ce.min_take_home_wtd,
                'max_deduction',
                  round(
                    case
                      when ce.cand_pay_method = 'UMBRELLA' then
                        least(
                          greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                          greatest(
                            least(
                              (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                              (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                            ),
                            0
                          )
                        )
                      else null
                    end,
                    2
                  )
              )
            ),
            'computed_net_bank_amount_non_mismatch', null,
            'itemisation', (coalesce(ctim.merged_timesheets_itemisation, ce.timesheets_itemisation, '[]'::jsonb) || coalesce(cfi.finance_itemisation, '[]'::jsonb))
          )
          order by ce.cand_display_name nulls last, ce.cand_tms_ref nulls last, ce.candidate_id
        )
        from cand_payee ce
        left join candidate_case_states ccs
          on ccs.candidate_id = ce.candidate_id
        left join finance_candidate_totals fct
          on fct.candidate_id = ce.candidate_id
        left join candidate_preview_timesheet_rollup cptr
          on cptr.candidate_id = ce.candidate_id
        left join candidate_finance_itemisation cfi
          on cfi.candidate_id = ce.candidate_id
        left join candidate_timesheet_itemisation_merged ctim
          on ctim.candidate_id = ce.candidate_id
        left join candidate_preview_line_rollup cplr
          on cplr.candidate_id = ce.candidate_id
        where ce.cand_pay_method = 'PAYE'
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'candidate_id', ce.candidate_id::text,
            'tms_ref', ce.cand_tms_ref,
            'display_name', ce.cand_display_name,
            'current_pay_method', ce.cand_pay_method,
            'umbrella_id', case when ce.cand_umbrella_id is null then null else ce.cand_umbrella_id::text end,
            'umbrella_enabled', ce.umb_enabled,
            'umbrella_vat_chargeable', ce.umb_vat_chargeable,

            'candidate_has_bank_details', ce.candidate_has_bank_details,
            'candidate_bank_hash', ce.candidate_bank_hash,
            'umbrella_has_bank_details', case when ce.cand_pay_method <> 'PAYE' then ce.umbrella_has_bank_details else null end,
            'umbrella_bank_hash', case when ce.cand_pay_method <> 'PAYE' then ce.umbrella_bank_hash else null end,

            'payee_entity_kind', ce.payee_entity_kind,
            'payee_entity_id', case when ce.payee_entity_id is null then null else ce.payee_entity_id::text end,
            'payee_bank_hash', ce.payee_bank_hash,
            'payee_map_present', ce.payee_map_present,
            'name_check_status', ce.payee_name_check_status,
            'name_check_has_override', ce.payee_name_check_has_override,
            'blockers', ce.blockers,

            'blocked_count', ce.blocked_count,
            'do_not_pay_count', ce.do_not_pay_count,
            'blocked_case_count', coalesce(ccs.blocked_case_count, 0),
            'safe_case_count', coalesce(ccs.safe_case_count, 0),
            'preview_blocked_timesheet_count', coalesce(cptr.blocked_timesheet_preview_count, 0),
            'preview_ready_timesheet_count', coalesce(cptr.ready_timesheet_preview_count, 0),
            'case_resolution_states', coalesce(ccs.case_resolution_states, '[]'::jsonb),
            'gross_preview_ex_vat_non_mismatch', coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),
            'finance_due_total_ex_vat', coalesce(fct.finance_due_total_ex_vat,0),
            'finance_safe_due_total_ex_vat', coalesce(fct.finance_safe_due_total_ex_vat,0),
            'finance_blocked_due_total_ex_vat', coalesce(fct.finance_blocked_due_total_ex_vat,0),
            'mismatch', jsonb_build_object(
              'has_mismatch', ce.has_mismatch,
              'source_paye_ex_vat', ce.mismatch_source_paye_ex,
              'source_umbrella_ex_vat', ce.mismatch_source_umbrella_ex,
              'if_settle_via_paye_ex_vat',
                round(
                  ce.mismatch_source_paye_ex
                  + public._pay_convert_umbrella_to_paye_ex(ce.mismatch_source_umbrella_ex, v_erni_pct),
                  2
                ),
              'if_settle_via_umbrella',
                public._pay_convert_paye_to_umbrella(ce.mismatch_source_paye_ex, v_erni_pct, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
                ||
                public._pay_umbrella_vat_calc(ce.mismatch_source_umbrella_ex, v_vat_rate_pct, ce.umb_vat_chargeable)::jsonb
            ),
            'overpayment_balance_remaining', ce.overpayment_balance_remaining,
            'loan_due_this_week', ce.loan_due_this_week,
            'loan_repaid_wtd', ce.loan_repaid_wtd,
            'min_take_home_wtd', ce.min_take_home_wtd,
            'max_possible_loan_take_this_run',
              round(
                case
                  when ce.cand_pay_method = 'UMBRELLA' then
                    least(
                      greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                      greatest(
                        least(
                          (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                          (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                        ),
                        0
                      )
                    )
                  else null
                end,
                2
              ),
            'paye_net_status', ce.paye_net_status,
            'loan', jsonb_build_object(
              'pay_week_start', v_week_start::text,
              'loan_due_total', ce.loan_due_total,
              'loan_due_entries', ce.loan_due_entries,
              'loan_due_this_week', ce.loan_due_this_week,
              'loan_repaid_wtd', ce.loan_repaid_wtd,
              'min_take_home_wtd', ce.min_take_home_wtd,
              'max_possible_loan_take_this_run',
                round(
                  case
                    when ce.cand_pay_method = 'UMBRELLA' then
                      least(
                        greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                        greatest(
                          least(
                            (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                            (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                          ),
                          0
                        )
                      )
                    else null
                  end,
                  2
                ),
              'paye_net_status', ce.paye_net_status,
              'cap_fields', jsonb_build_object(
                'min_take_home', ce.min_take_home_wtd,
                'max_deduction',
                  round(
                    case
                      when ce.cand_pay_method = 'UMBRELLA' then
                        least(
                          greatest(coalesce(ce.loan_due_this_week,0) - coalesce(ce.loan_repaid_wtd,0),0),
                          greatest(
                            least(
                              (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0))),
                              (coalesce((select pwb.paid_wtd_before from paid_wtd_before pwb where pwb.candidate_id = ce.candidate_id limit 1),0) + (greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0) - least(coalesce(ce.overpayment_balance_remaining,0), greatest(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0),0)))) - coalesce(ce.min_take_home_wtd,0)
                            ),
                            0
                          )
                        )
                      else null
                    end,
                    2
                  )
              )
            ),
            'computed_net_bank_amount_non_mismatch',
              (public._pay_umbrella_vat_calc(coalesce(cptr.ready_timesheet_total_ex_vat, ce.non_mismatch_total_ex, 0), v_vat_rate_pct, ce.umb_vat_chargeable)->>'inc')::numeric,
            'itemisation', (coalesce(ctim.merged_timesheets_itemisation, ce.timesheets_itemisation, '[]'::jsonb) || coalesce(cfi.finance_itemisation, '[]'::jsonb))
          )
          order by ce.cand_display_name nulls last, ce.cand_tms_ref nulls last, ce.candidate_id
        )
        from cand_payee ce
        left join candidate_case_states ccs
          on ccs.candidate_id = ce.candidate_id
        left join finance_candidate_totals fct
          on fct.candidate_id = ce.candidate_id
        left join candidate_preview_timesheet_rollup cptr
          on cptr.candidate_id = ce.candidate_id
        left join candidate_finance_itemisation cfi
          on cfi.candidate_id = ce.candidate_id
        left join candidate_timesheet_itemisation_merged ctim
          on ctim.candidate_id = ce.candidate_id
        left join candidate_preview_line_rollup cplr
          on cplr.candidate_id = ce.candidate_id
        where ce.cand_pay_method <> 'PAYE'
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'candidate_id', bi.candidate_id::text,
            'timesheet_id', bi.timesheet_id::text,
            'segment_id', bi.segment_id,
            'ref_num', bi.ref_num,
            'reason', 'MISSING_REF_NUM',
            'blocked_delta_ex_vat', bi.blocked_delta_ex,
            'line_type', 'BLOCKED_TIMESHEET',
            'finance_case_id', null,
            'paye_treatment', null,
            'route_type', 'NORMAL_PAYMENT',
            'adjustment_comment', null,
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', bi.timesheet_id::text,
              'booking_id', bi.booking_id,
              'segment_id', bi.segment_id,
              'segment_stable_key', bi.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', jsonb_build_object('state','NONE')
          )
          order by bi.candidate_id, bi.timesheet_id, bi.segment_id
        )
        from blocked_items bi
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'candidate_id', di.candidate_id::text,
            'timesheet_id', di.timesheet_id::text,
            'segment_id', di.segment_id,
            'ref_num', di.ref_num,
            'raw_delta_ex_vat', di.raw_delta_ex,
            'line_type', 'DO_NOT_PAY',
            'finance_case_id', null,
            'paye_treatment', null,
            'route_type', 'NORMAL_PAYMENT',
            'adjustment_comment', null,
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', di.timesheet_id::text,
              'booking_id', di.booking_id,
              'segment_id', di.segment_id,
              'segment_stable_key', di.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', jsonb_build_object('state','NONE')
          )
          order by di.candidate_id, di.timesheet_id, di.segment_id
        )
        from do_not_pay_items di
      ),
      '[]'::jsonb
    ),
    coalesce(
      (
        select jsonb_agg(x order by x->>'candidate_id', coalesce(x->>'timesheet_id',''), coalesce(x->>'finance_case_id',''), coalesce(x->>'segment_id',''))
        from (
          select jsonb_build_object(
            'kind', case when ctsr.segment_snooze_kind = 'DO_NOT_PAY' then 'DO_NOT_PAY' else 'BLOCKED' end,
            'candidate_id', ctsr.candidate_id::text,
            'timesheet_id', ctsr.timesheet_id::text,
            'segment_id', ctsr.segment_id,
            'ref_num', ctsr.ref_num,
            'amount_ex_vat', ctsr.presentation_amount_ex_vat,
            'raw_delta_ex_vat', ctsr.raw_delta_ex_vat,
            'effective_delta_ex_vat', ctsr.effective_delta_ex_vat,
            'blocked_delta_ex_vat', ctsr.presentation_amount_ex_vat,
            'line_type', case when ctsr.segment_snooze_kind = 'DO_NOT_PAY' then 'DO_NOT_PAY' else 'BLOCKED_TIMESHEET' end,
            'finance_case_id', null,
            'paye_treatment', null,
            'route_type', 'NORMAL_PAYMENT',
            'adjustment_comment', null,
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET_SEGMENT',
              'timesheet_id', ctsr.timesheet_id::text,
              'booking_id', ctsr.booking_id,
              'segment_id', ctsr.segment_id,
              'segment_stable_key', ctsr.segment_stable_key,
              'source_ref', null
            ),
            'snooze_state', jsonb_build_object(
              'state', 'DATED_SNOOZED',
              'snooze_id', ctsr.segment_snooze_id::text,
              'snooze_until_date', ctsr.segment_snooze_until_date::text,
              'note', ctsr.segment_snooze_note,
              'snooze_kind', ctsr.segment_snooze_kind
            ),
            'snooze_id', ctsr.segment_snooze_id::text,
            'snooze_until_date', ctsr.segment_snooze_until_date::text,
            'note', ctsr.segment_snooze_note
          ) as x
          from canonical_timesheet_segment_rows ctsr
          where ctsr.segment_snooze_id is not null
            and ctsr.segment_snooze_until_date is not null

          union all

          select jsonb_build_object(
            'kind', 'TIMESHEET_PAYMENT',
            'candidate_id', ctl.candidate_id::text,
            'timesheet_id', ctl.timesheet_id::text,
            'segment_id', null,
            'ref_num', null,
            'amount_ex_vat', ctl.amount_ex_vat,
            'raw_delta_ex_vat', ctl.amount_ex_vat,
            'effective_delta_ex_vat', ctl.amount_ex_vat,
            'blocked_delta_ex_vat', ctl.amount_ex_vat,
            'line_type', 'TIMESHEET_PAYMENT',
            'finance_case_id', null,
            'paye_treatment', case when ctl.candidate_pay_method = 'PAYE' then 'GROSS_ADD' else 'NONE' end,
            'route_type', 'NORMAL_PAYMENT',
            'adjustment_comment', null,
            'snooze_identity', jsonb_build_object(
              'identity_type', 'TIMESHEET',
              'timesheet_id', ctl.timesheet_id::text,
              'booking_id', ctl.booking_id,
              'segment_id', null,
              'segment_stable_key', null,
              'source_ref', null
            ),
            'snooze_state', jsonb_build_object(
              'state', 'DATED_SNOOZED',
              'snooze_id', ctl.snooze_id::text,
              'snooze_until_date', ctl.snooze_until_date::text,
              'note', ctl.snooze_note
            ),
            'snooze_id', ctl.snooze_id::text,
            'snooze_until_date', ctl.snooze_until_date::text,
            'note', ctl.snooze_note
          ) as x
          from canonical_timesheet_lines ctl
          where ctl.snooze_id is not null
            and ctl.snooze_until_date is not null

          union all

          select jsonb_build_object(
            'kind', fcl.case_type::text,
            'candidate_id', fcl.candidate_id::text,
            'timesheet_id', case when fcl.linked_timesheet_id is null then null else fcl.linked_timesheet_id::text end,
            'segment_id', null,
            'ref_num', null,
            'amount_ex_vat', fcl.signed_amount_ex_vat,
            'raw_delta_ex_vat', fcl.signed_amount_ex_vat,
            'effective_delta_ex_vat', fcl.signed_amount_ex_vat,
            'blocked_delta_ex_vat', fcl.signed_amount_ex_vat,
            'line_type', fcl.line_type,
            'finance_case_id', fcl.finance_case_id::text,
            'paye_treatment', fcl.paye_treatment,
            'route_type', 'NORMAL_PAYMENT',
            'adjustment_comment', fcl.adjustment_comment,
            'snooze_identity', jsonb_build_object(
              'identity_type', 'FINANCE_CASE',
              'timesheet_id', null,
              'booking_id', null,
              'segment_id', null,
              'segment_stable_key', null,
              'source_ref', ('advance:' || fcl.finance_case_id::text)
            ),
            'snooze_state', jsonb_build_object(
              'state', 'DATED_SNOOZED',
              'snooze_id', fcl.active_snooze_id::text,
              'snooze_until_date', fcl.active_snooze_until_date::text,
              'note', fcl.active_snooze_note
            ),
            'snooze_id', fcl.active_snooze_id::text,
            'snooze_until_date', fcl.active_snooze_until_date::text,
            'note', fcl.active_snooze_note
          ) as x
          from finance_case_lines fcl
          where fcl.active_snooze_id is not null
            and fcl.active_snooze_until_date is not null
            and fcl.due_amount_ex_vat > 0
        ) u
      ),
      '[]'::jsonb
    ),
    coalesce((select pj.payees from payees_json pj), '[]'::jsonb),
    '{}'::jsonb,
    coalesce((select jsonb_agg(cpl.line_json order by cpl.candidate_id, cpl.line_json->>'display_name', cpl.line_json->>'line_type', cpl.line_json->>'line_id') from canonical_preview_lines cpl), '[]'::jsonb),
    coalesce((select psbj.payload from paye_summary_breakdown_json psbj), '{}'::jsonb),
    coalesce((select crsj.payload from case_resolution_states_json crsj), '[]'::jsonb),
    coalesce((select bcrj.payload from baseline_component_rows_json bcrj), '[]'::jsonb)
  into v_paye, v_nonpaye, v_blocked, v_do_not_pay, v_snoozed, v_payees, v_summary, v_canonical_preview_lines, v_paye_summary_breakdown, v_case_resolution_states, v_baseline_component_rows;

  with raw_visible_manual_debt_lines as (
    select
      row_number() over () as line_sort_key,
      visible_line.value as line_value
    from jsonb_array_elements(coalesce(v_canonical_preview_lines, '[]'::jsonb)) as visible_line(value)
    where jsonb_typeof(visible_line.value) = 'object'
      and upper(coalesce(visible_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
      and upper(coalesce(visible_line.value->>'pay_channel', '')) = 'PAYE'
      and upper(coalesce(visible_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
      and coalesce(nullif(btrim(coalesce(visible_line.value->>'finance_case_id', '')), ''), '') <> ''
  ),
  visible_manual_debt_components as (
    select
      raw_visible_manual_debt_lines.line_sort_key,
      raw_visible_manual_debt_lines.line_value,
      case
        when jsonb_typeof(raw_visible_manual_debt_lines.line_value->'case_components') = 'array'
             and jsonb_array_length(coalesce(raw_visible_manual_debt_lines.line_value->'case_components', '[]'::jsonb)) > 0
          then raw_visible_manual_debt_lines.line_value->'case_components'->0
        else '{}'::jsonb
      end as component_value
    from raw_visible_manual_debt_lines
  ),
  built_hidden_template_lines as (
    select
      visible_manual_debt_components.line_sort_key,
      coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'candidate_id', '')), ''), v_candidate_id::text) as candidate_id_text,
      coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'finance_case_id', '')), ''), '') as finance_case_id_text,
      coalesce(nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'finance_component_id', '')), ''), '') as finance_component_id_text,
      coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'source_ref', '')), ''), '') as source_ref_text,
      jsonb_strip_nulls(
        jsonb_build_object(
          'candidate_id', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'candidate_id', '')), ''), v_candidate_id::text),
          'finance_case_id', nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'finance_case_id', '')), ''),
          'finance_component_id', nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'finance_component_id', '')), ''),
          'recovery_family', 'MANUAL_DEBT_RECOVERY',
          'source_ref', coalesce(
            nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'source_ref', '')), ''),
            case
              when coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'finance_case_id', '')), ''), '') = '' then null
              else 'advance:' || nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'finance_case_id', '')), '')
            end
          ),
          'pay_channel', 'PAYE',
          'paye_treatment', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'paye_treatment', '')), ''), 'NET_DEDUCT'),
          'frozen_component_key_type', nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'component_key_type', '')), ''),
          'frozen_component_key_value', nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'component_key_value', '')), ''),
          'frozen_component_classification', nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'classification', '')), ''),
          'frozen_component_snapshot_json', jsonb_strip_nulls(
            jsonb_build_object(
              'finance_case_id', nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'finance_case_id', '')), ''),
              'case_components', case
                when jsonb_typeof(visible_manual_debt_components.line_value->'case_components') = 'array' then coalesce(visible_manual_debt_components.line_value->'case_components', '[]'::jsonb)
                else '[]'::jsonb
              end,
              'case_resolution_summary', case
                when jsonb_typeof(visible_manual_debt_components.line_value->'case_resolution_summary') = 'object' then visible_manual_debt_components.line_value->'case_resolution_summary'
                else null::jsonb
              end
            )
          ),
          'frozen_source_basis_json', jsonb_strip_nulls(
            coalesce(
              case
                when jsonb_typeof(visible_manual_debt_components.component_value->'source_basis_json') = 'object' then visible_manual_debt_components.component_value->'source_basis_json'
                else '{}'::jsonb
              end,
              '{}'::jsonb
            )
            || jsonb_build_object(
              'recovery_family', 'MANUAL_DEBT_RECOVERY',
              'pay_channel', 'PAYE',
              'frozen_source_pay_method', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'source_pay_method', '')), ''), 'PAYE'),
              'frozen_target_pay_method', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'current_target_pay_method', '')), ''), 'PAYE'),
              'outstanding_amount', to_jsonb(coalesce(
                case when coalesce(visible_manual_debt_components.component_value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->>'remaining_source_amount')::numeric else null::numeric end,
                case when coalesce(visible_manual_debt_components.component_value->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->>'source_amount')::numeric else null::numeric end
              )),
              'nominal_due_amount_ex_vat', to_jsonb(abs(coalesce(case when coalesce(visible_manual_debt_components.line_value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.line_value->>'amount_ex_vat')::numeric else 0::numeric end, 0::numeric))),
              'current_due_amount_ex_vat', to_jsonb(abs(coalesce(case when coalesce(visible_manual_debt_components.line_value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.line_value->>'amount_ex_vat')::numeric else 0::numeric end, 0::numeric))),
              'next_due_week_start', coalesce(
                nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'next_due_week_start', '')), ''),
                nullif(btrim(coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'next_due_week_start', '')), '')
              ),
              'sort_order', visible_manual_debt_components.line_sort_key
            )
          ),
          'frozen_source_pay_method', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'source_pay_method', '')), ''), 'PAYE'),
          'frozen_target_pay_method', coalesce(nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'current_target_pay_method', '')), ''), 'PAYE'),
          'frozen_resolution_mode', coalesce(
            nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'saved_resolution_mode', '')), ''),
            nullif(btrim(coalesce(visible_manual_debt_components.component_value->>'resolution_mode', '')), '')
          ),
          'frozen_resolution_payload_json', case
            when jsonb_typeof(visible_manual_debt_components.line_value->'case_resolution_summary') = 'object'
                 and jsonb_typeof(visible_manual_debt_components.line_value->'case_resolution_summary'->'non_bucket_resolution') = 'object'
              then visible_manual_debt_components.line_value->'case_resolution_summary'->'non_bucket_resolution'
            when jsonb_typeof(visible_manual_debt_components.component_value->'saved_resolution_payload_json') = 'object'
              then visible_manual_debt_components.component_value->'saved_resolution_payload_json'
            when jsonb_typeof(visible_manual_debt_components.component_value->'suggested_resolution_payload_json') = 'object'
              then visible_manual_debt_components.component_value->'suggested_resolution_payload_json'
            else null::jsonb
          end,
          'frozen_resolution_result_json', case
            when jsonb_typeof(visible_manual_debt_components.line_value->'case_resolution_summary') = 'object'
              then visible_manual_debt_components.line_value->'case_resolution_summary'
            when jsonb_typeof(visible_manual_debt_components.component_value->'saved_resolution_result_json') = 'object'
              then visible_manual_debt_components.component_value->'saved_resolution_result_json'
            when jsonb_typeof(visible_manual_debt_components.component_value->'suggested_resolution_result_json') = 'object'
              then visible_manual_debt_components.component_value->'suggested_resolution_result_json'
            else null::jsonb
          end,
          'frozen_source_amount', round(coalesce(
            case when coalesce(visible_manual_debt_components.component_value->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->>'source_amount')::numeric else null::numeric end,
            0::numeric
          ), 2),
          'frozen_outstanding_amount', round(coalesce(
            case when coalesce(visible_manual_debt_components.component_value->>'remaining_source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->>'remaining_source_amount')::numeric else null::numeric end,
            case when coalesce(visible_manual_debt_components.component_value->>'source_amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->>'source_amount')::numeric else null::numeric end,
            0::numeric
          ), 2),
          'weekly_due', round(coalesce(
            case when coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'weekly_due', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->'source_basis_json'->>'weekly_due')::numeric else null::numeric end,
            abs(coalesce(case when coalesce(visible_manual_debt_components.line_value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.line_value->>'amount_ex_vat')::numeric else 0::numeric end, 0::numeric)),
            0::numeric
          ), 2),
          'minimum_earnings_threshold', case when coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'minimum_earnings_threshold', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->'source_basis_json'->>'minimum_earnings_threshold')::numeric else null::numeric end,
          'take_home_floor_override', case when coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'take_home_floor_override', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->'source_basis_json'->>'take_home_floor_override')::numeric else null::numeric end,
          'default_take_home_floor', coalesce(
            case when coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'default_take_home_floor', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (visible_manual_debt_components.component_value->'source_basis_json'->>'default_take_home_floor')::numeric else null::numeric end,
            0::numeric
          ),
          'next_due_week_start', coalesce(
            nullif(btrim(coalesce(visible_manual_debt_components.line_value->>'next_due_week_start', '')), ''),
            nullif(btrim(coalesce(visible_manual_debt_components.component_value->'source_basis_json'->>'next_due_week_start', '')), '')
          ),
          'sort_order', visible_manual_debt_components.line_sort_key
        )
      ) as hidden_line
    from visible_manual_debt_components
  ),
  dedup_hidden_template_lines as (
    select distinct on (
      built_hidden_template_lines.candidate_id_text,
      built_hidden_template_lines.finance_case_id_text,
      built_hidden_template_lines.finance_component_id_text,
      built_hidden_template_lines.source_ref_text
    )
      built_hidden_template_lines.line_sort_key,
      built_hidden_template_lines.hidden_line
    from built_hidden_template_lines
    order by
      built_hidden_template_lines.candidate_id_text,
      built_hidden_template_lines.finance_case_id_text,
      built_hidden_template_lines.finance_component_id_text,
      built_hidden_template_lines.source_ref_text,
      built_hidden_template_lines.line_sort_key
  )
  select coalesce(
           jsonb_agg(dedup_hidden_template_lines.hidden_line order by dedup_hidden_template_lines.line_sort_key),
           '[]'::jsonb
         )
  into v_hidden_recovery_template_lines
  from dedup_hidden_template_lines;

  with raw_canonical_preview_lines as (
    select
      row_number() over () as line_sort_key,
      raw_line.value as line_value
    from jsonb_array_elements(coalesce(v_canonical_preview_lines, '[]'::jsonb)) as raw_line(value)
    where jsonb_typeof(raw_line.value) = 'object'
  )
  select coalesce(
           jsonb_agg(filtered_canonical_preview_lines.line_value order by filtered_canonical_preview_lines.line_sort_key),
           '[]'::jsonb
         )
  into v_filtered_canonical_preview_lines
  from (
    select
      raw_canonical_preview_lines.line_sort_key,
      raw_canonical_preview_lines.line_value
    from raw_canonical_preview_lines
    where (
      upper(coalesce(raw_canonical_preview_lines.line_value->>'line_type', '')) <> 'MANUAL_DEBT_RECOVERY'
      or upper(coalesce(raw_canonical_preview_lines.line_value->>'pay_channel', '')) <> 'PAYE'
      or upper(coalesce(raw_canonical_preview_lines.line_value->>'paye_treatment', '')) <> 'NET_DEDUCT'
      or coalesce(nullif(btrim(coalesce(raw_canonical_preview_lines.line_value->>'finance_case_id', '')), ''), '') = ''
      or exists (
        select 1
        from jsonb_array_elements(coalesce(v_hidden_recovery_template_lines, '[]'::jsonb)) as hidden_template_line(hidden_value)
        where jsonb_typeof(hidden_template_line.hidden_value) = 'object'
          and upper(coalesce(hidden_template_line.hidden_value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
          and upper(coalesce(nullif(btrim(coalesce(hidden_template_line.hidden_value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
          and coalesce(nullif(btrim(coalesce(hidden_template_line.hidden_value->>'finance_case_id', '')), ''), '') =
              coalesce(nullif(btrim(coalesce(raw_canonical_preview_lines.line_value->>'finance_case_id', '')), ''), '')
      )
    )
  ) as filtered_canonical_preview_lines;

  v_canonical_preview_lines := coalesce(v_filtered_canonical_preview_lines, '[]'::jsonb);

  if jsonb_typeof(v_paye) = 'array'
 and jsonb_array_length(v_paye) > 0 then
    v_candidate_row := coalesce(v_paye->0, '{}'::jsonb);
  elsif jsonb_typeof(v_nonpaye) = 'array' and jsonb_array_length(v_nonpaye) > 0 then
    v_candidate_row := coalesce(v_nonpaye->0, '{}'::jsonb);
  else
    v_candidate_row := jsonb_build_object(
      'candidate_id', v_candidate_id::text,
      'display_name', null,
      'tms_ref', null,
      'current_pay_method', null,
      'case_resolution_states', coalesce(v_case_resolution_states, '[]'::jsonb),
      'itemisation', '[]'::jsonb
    );
  end if;

  v_itemisation := case
    when jsonb_typeof(v_candidate_row->'itemisation') = 'array' then coalesce(v_candidate_row->'itemisation', '[]'::jsonb)
    else '[]'::jsonb
  end;

  select
    coalesce(
      jsonb_agg(
        jsonb_strip_nulls(
          jsonb_build_object(
            'kind', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
            'candidate_id', coalesce(nullif(btrim(coalesce(carry_forward_line.value->>'candidate_id', '')), ''), v_candidate_id::text),
            'manual_adjustment_carry_forward_id', nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), ''),
            'source_ref', coalesce(
              nullif(btrim(coalesce(carry_forward_line.value->>'source_ref', '')), ''),
              case
                when nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), '') is null then null
                else 'carry_forward:' || nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), '')
              end
            ),
            'operation_source_key', coalesce(
              nullif(btrim(coalesce(carry_forward_line.value->>'operation_source_key', '')), ''),
              case
                when nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), '') is null then null
                else 'carry_forward:' || nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), '')
              end
            ),
            'line_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
            'description', coalesce(
              nullif(btrim(coalesce(carry_forward_line.value->>'description', '')), ''),
              nullif(btrim(coalesce(carry_forward_line.value->>'adjustment_comment', '')), ''),
              'Manual adjustment carry-forward'
            ),
            'adjustment_comment', coalesce(
              nullif(btrim(coalesce(carry_forward_line.value->>'adjustment_comment', '')), ''),
              nullif(btrim(coalesce(carry_forward_line.value->>'description', '')), ''),
              'Manual adjustment carry-forward'
            ),
            'payment_amount_ex_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat')::numeric, 2)
              else 0::numeric
            end,
            'payment_amount_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat')::numeric, 2)
              else 0::numeric
            end,
            'payment_amount_inc_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display')::numeric, 2)
              else 0::numeric
            end,
            'amount_ex_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat')::numeric, 2)
              else 0::numeric
            end,
            'amount_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat')::numeric, 2)
              else 0::numeric
            end,
            'amount_inc_vat', case
              when coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display')::numeric, 2)
              else 0::numeric
            end,
            'amount_display', case
              when coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
                then round(coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display')::numeric, 2)
              else 0::numeric
            end,
            'pay_channel', upper(btrim(coalesce(carry_forward_line.value->>'pay_channel', ''))),
            'paye_treatment', nullif(btrim(coalesce(carry_forward_line.value->>'paye_treatment', '')), ''),
            'tax_treatment_json', case
              when jsonb_typeof(carry_forward_line.value->'tax_treatment_json') = 'object' then carry_forward_line.value->'tax_treatment_json'
              else '{}'::jsonb
            end,
            'taxability', nullif(btrim(coalesce(carry_forward_line.value->>'taxability', carry_forward_line.value#>>'{tax_treatment_json,taxability}', '')), ''),
            'adjustment_direction', nullif(btrim(coalesce(carry_forward_line.value->>'adjustment_direction', '')), ''),
            'source_snapshot_json', case
              when jsonb_typeof(carry_forward_line.value->'source_snapshot_json') = 'object' then carry_forward_line.value->'source_snapshot_json'
              else '{}'::jsonb
            end
          )
        )
        order by coalesce(carry_forward_line.value->>'preview_row_id', carry_forward_line.value->>'manual_adjustment_carry_forward_id')
      ),
      '[]'::jsonb
    ),
    coalesce(sum(
      case
        when coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          then round(coalesce(carry_forward_line.value->>'payment_amount_ex_vat', carry_forward_line.value->>'amount_ex_vat')::numeric, 2)
        else 0::numeric
      end
    ), 0::numeric),
    coalesce(sum(
      case
        when coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          then round(coalesce(carry_forward_line.value->>'payment_amount_vat', carry_forward_line.value->>'amount_vat')::numeric, 2)
        else 0::numeric
      end
    ), 0::numeric),
    coalesce(sum(
      case
        when coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          then round(coalesce(carry_forward_line.value->>'payment_amount_inc_vat', carry_forward_line.value->>'amount_inc_vat', carry_forward_line.value->>'amount_display')::numeric, 2)
        else 0::numeric
      end
    ), 0::numeric)
  into
    v_carry_forward_itemisation,
    v_carry_forward_total_ex_vat,
    v_carry_forward_total_vat,
    v_carry_forward_total_inc_vat
  from jsonb_array_elements(coalesce(v_canonical_preview_lines, '[]'::jsonb)) as carry_forward_line(value)
  where jsonb_typeof(carry_forward_line.value) = 'object'
    and upper(coalesce(carry_forward_line.value->>'line_type', '')) = 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
    and not exists (
      select 1
      from jsonb_array_elements(coalesce(v_itemisation, '[]'::jsonb)) as existing_item(value)
      where nullif(btrim(coalesce(existing_item.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
        and nullif(btrim(coalesce(existing_item.value->>'manual_adjustment_carry_forward_id', '')), '') =
            nullif(btrim(coalesce(carry_forward_line.value->>'manual_adjustment_carry_forward_id', '')), '')
    );

  v_itemisation := coalesce(v_itemisation, '[]'::jsonb) || coalesce(v_carry_forward_itemisation, '[]'::jsonb);

  v_candidate_row := coalesce(v_candidate_row, '{}'::jsonb)
    || jsonb_build_object(
      'itemisation', coalesce(v_itemisation, '[]'::jsonb),
      'manual_adjustment_carry_forward_total_ex_vat', round(coalesce(v_carry_forward_total_ex_vat, 0), 2),
      'manual_adjustment_carry_forward_total_vat', round(coalesce(v_carry_forward_total_vat, 0), 2),
      'manual_adjustment_carry_forward_total_inc_vat', round(coalesce(v_carry_forward_total_inc_vat, 0), 2)
    )
    || case
      when coalesce(v_candidate_row->>'gross_preview_ex_vat_non_mismatch', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        then jsonb_build_object(
          'gross_preview_ex_vat_non_mismatch',
          round((v_candidate_row->>'gross_preview_ex_vat_non_mismatch')::numeric + coalesce(v_carry_forward_total_ex_vat, 0), 2)
        )
      else '{}'::jsonb
    end
    || case
      when coalesce(v_candidate_row->>'computed_net_bank_amount_non_mismatch', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
        then jsonb_build_object(
          'computed_net_bank_amount_non_mismatch',
          round((v_candidate_row->>'computed_net_bank_amount_non_mismatch')::numeric + coalesce(v_carry_forward_total_inc_vat, 0), 2)
        )
      else '{}'::jsonb
    end;

  IF upper(coalesce(v_candidate_row->>'current_pay_method', '')) = 'PAYE' THEN
    SELECT coalesce(
             jsonb_agg(
               CASE
                 WHEN coalesce(candidate_row.value->>'candidate_id', '') = v_candidate_id::text THEN v_candidate_row
                 ELSE candidate_row.value
               END
               ORDER BY candidate_row.ord
             ),
             '[]'::jsonb
           )
    INTO v_paye
    FROM jsonb_array_elements(coalesce(v_paye, '[]'::jsonb)) WITH ORDINALITY AS candidate_row(value, ord);

    IF NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(coalesce(v_paye, '[]'::jsonb)) AS candidate_row(value)
      WHERE coalesce(candidate_row.value->>'candidate_id', '') = v_candidate_id::text
    ) THEN
      v_paye := coalesce(v_paye, '[]'::jsonb) || jsonb_build_array(v_candidate_row);
    END IF;
  ELSE
    SELECT coalesce(
             jsonb_agg(
               CASE
                 WHEN coalesce(candidate_row.value->>'candidate_id', '') = v_candidate_id::text THEN v_candidate_row
                 ELSE candidate_row.value
               END
               ORDER BY candidate_row.ord
             ),
             '[]'::jsonb
           )
    INTO v_nonpaye
    FROM jsonb_array_elements(coalesce(v_nonpaye, '[]'::jsonb)) WITH ORDINALITY AS candidate_row(value, ord);

    IF NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(coalesce(v_nonpaye, '[]'::jsonb)) AS candidate_row(value)
      WHERE coalesce(candidate_row.value->>'candidate_id', '') = v_candidate_id::text
    ) THEN
      v_nonpaye := coalesce(v_nonpaye, '[]'::jsonb) || jsonb_build_array(v_candidate_row);
    END IF;
  END IF;

  select jsonb_build_object(
    'candidate_count', 1,
    'case_resolution_state_count', case when jsonb_typeof(coalesce(v_case_resolution_states, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_case_resolution_states, '[]'::jsonb)) else 0 end,
    'canonical_preview_line_count', case when jsonb_typeof(coalesce(v_canonical_preview_lines, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_canonical_preview_lines, '[]'::jsonb)) else 0 end,
    'manual_adjustment_carry_forward_line_count', case when jsonb_typeof(coalesce(v_carry_forward_itemisation, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_carry_forward_itemisation, '[]'::jsonb)) else 0 end,
    'manual_adjustment_carry_forward_total_ex_vat', round(coalesce(v_carry_forward_total_ex_vat, 0), 2),
    'manual_adjustment_carry_forward_total_vat', round(coalesce(v_carry_forward_total_vat, 0), 2),
    'manual_adjustment_carry_forward_total_inc_vat', round(coalesce(v_carry_forward_total_inc_vat, 0), 2),
    'blocked_preview_line_count', case when jsonb_typeof(coalesce(v_blocked, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_blocked, '[]'::jsonb)) else 0 end,
    'do_not_pay_line_count', case when jsonb_typeof(coalesce(v_do_not_pay, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_do_not_pay, '[]'::jsonb)) else 0 end,
    'snoozed_line_count', case when jsonb_typeof(coalesce(v_snoozed, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_snoozed, '[]'::jsonb)) else 0 end,
    'payees_count', case when jsonb_typeof(coalesce(v_payees, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_payees, '[]'::jsonb)) else 0 end,
    'itemisation_count', case when jsonb_typeof(coalesce(v_itemisation, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_itemisation, '[]'::jsonb)) else 0 end,
    'baseline_component_row_count', case when jsonb_typeof(coalesce(v_baseline_component_rows, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_baseline_component_rows, '[]'::jsonb)) else 0 end,
    'total_amount_ex_vat', coalesce((select round(sum(case when coalesce(elem.value->>'amount_ex_vat','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (elem.value->>'amount_ex_vat')::numeric else 0::numeric end), 2) from jsonb_array_elements(coalesce(v_canonical_preview_lines, '[]'::jsonb)) as elem(value)), 0::numeric),
    'total_amount_display', coalesce((select round(sum(case when coalesce(elem.value->>'amount_display','') ~ '^-?[0-9]+(\.[0-9]+)?$' then (elem.value->>'amount_display')::numeric else 0::numeric end), 2) from jsonb_array_elements(coalesce(v_canonical_preview_lines, '[]'::jsonb)) as elem(value)), 0::numeric),
    'paye_breakdown', coalesce(v_paye_summary_breakdown, '{}'::jsonb)
  )
  into v_summary;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'candidate_row', coalesce(v_candidate_row, '{}'::jsonb),
    'summary_fragment', coalesce(v_summary, '{}'::jsonb),
    'case_resolution_states', coalesce(v_case_resolution_states, '[]'::jsonb),
    'canonical_preview_lines', coalesce(v_canonical_preview_lines, '[]'::jsonb),
    'hidden_recovery_template_lines', coalesce(v_hidden_recovery_template_lines, '[]'::jsonb),
    'manual_adjustment_carry_forward_itemisation', coalesce(v_carry_forward_itemisation, '[]'::jsonb),
    'manual_adjustment_carry_forward_line_count', case when jsonb_typeof(coalesce(v_carry_forward_itemisation, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_carry_forward_itemisation, '[]'::jsonb)) else 0 end,
    'manual_adjustment_carry_forward_total_ex_vat', round(coalesce(v_carry_forward_total_ex_vat, 0), 2),
    'manual_adjustment_carry_forward_total_vat', round(coalesce(v_carry_forward_total_vat, 0), 2),
    'manual_adjustment_carry_forward_total_inc_vat', round(coalesce(v_carry_forward_total_inc_vat, 0), 2),
    'hidden_recovery_template_line_count', case when jsonb_typeof(coalesce(v_hidden_recovery_template_lines, '[]'::jsonb)) = 'array' then jsonb_array_length(coalesce(v_hidden_recovery_template_lines, '[]'::jsonb)) else 0 end,
    'payees', coalesce(v_payees, '[]'::jsonb),
    'itemisation', coalesce(v_itemisation, '[]'::jsonb),
    'blocked_items', coalesce(v_blocked, '[]'::jsonb),
    'do_not_pay_items', coalesce(v_do_not_pay, '[]'::jsonb),
    'snoozed_items', coalesce(v_snoozed, '[]'::jsonb),
    'baseline_component_rows', coalesce(v_baseline_component_rows, '[]'::jsonb),
    'paye_candidates', coalesce(v_paye, '[]'::jsonb),
    'non_paye_candidates', coalesce(v_nonpaye, '[]'::jsonb),
    'paye_summary_breakdown', coalesce(v_paye_summary_breakdown, '{}'::jsonb)
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_preview_candidate_collect_scope(p_context_json jsonb, p_candidate_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_pay_eligibility_months_back int := 6;
  v_pay_eligibility_weeks_ahead int := 2;
  v_eligibility_from_date date;
  v_eligibility_to_date date;
  v_vat_rate_pct numeric;
  v_erni_pct numeric;
  v_rail_provider_default text;
  v_rail_env_default text;
  v_rail_supports_scheduling boolean := false;
  v_rail_supports_name_check boolean := false;
  v_rail_supports_auto_execute boolean := false;
  v_default_schedule_umbrella_local text;
  v_default_schedule_paye_local text;
  v_funds_warning_hours_json jsonb := '[]'::jsonb;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_refresh_scope_kind text := NULL;
  v_effective_refresh_scope_kind text := 'CANDIDATE_FULL_LIVE';
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_pay_channel_scope text := 'ALL';
  v_candidate_pay_method text := NULL::text;
  v_target_pay_batch_id_raw text := NULL::text;
  v_target_pay_batch_id uuid := NULL::uuid;
  v_target_operation_source_key text := NULL::text;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  v_pay_date := nullif(btrim(coalesce(v_context_json->>'pay_date', '')), '')::date;
  v_week_ending_cutoff := DATE '9999-12-31';
  v_client_id := nullif(btrim(coalesce(v_context_json #>> '{filters,client_id}', '')), '')::uuid;
  v_week_start := nullif(btrim(coalesce(v_context_json->>'pay_week_start', '')), '')::date;
  v_today_uk := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,today_uk}', '')), '')::date, (now() at time zone 'Europe/London')::date);
  v_eligibility_from_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,from_date}', '')), '')::date;
  v_eligibility_to_date := nullif(btrim(coalesce(v_context_json #>> '{eligibility,to_date}', '')), '')::date;
  v_pay_eligibility_months_back := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,months_back}', '')), '')::int, 6);
  v_pay_eligibility_weeks_ahead := coalesce(nullif(btrim(coalesce(v_context_json #>> '{eligibility,weeks_ahead}', '')), '')::int, 2);
  v_vat_rate_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,vat_rate_pct}', '')), '')::numeric;
  v_erni_pct := nullif(btrim(coalesce(v_context_json #>> '{finance,erni_pct}', '')), '')::numeric;
  v_rail_provider_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,provider_default}', '')), '');
  v_rail_env_default := nullif(btrim(coalesce(v_context_json #>> '{settings,rail,env_default}', '')), '');
  v_rail_supports_scheduling := coalesce((v_context_json #>> '{settings,rail,supports_scheduling}')::boolean, false);
  v_rail_supports_name_check := coalesce((v_context_json #>> '{settings,rail,supports_name_check}')::boolean, false);
  v_rail_supports_auto_execute := coalesce((v_context_json #>> '{settings,rail,supports_auto_execute}')::boolean, false);
  v_default_schedule_umbrella_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,umbrella_local}', '')), '');
  v_default_schedule_paye_local := nullif(btrim(coalesce(v_context_json #>> '{settings,schedule_defaults,paye_local}', '')), '');
  v_funds_warning_hours_json := case when jsonb_typeof(v_context_json #> '{settings,funds_warning_hours_json}') = 'array' then coalesce(v_context_json #> '{settings,funds_warning_hours_json}', '[]'::jsonb) else '[]'::jsonb end;
  v_need_name_check := coalesce((v_context_json #>> '{settings,rail,need_name_check}')::boolean, false);
  v_requires_payee_map := coalesce((v_context_json #>> '{settings,rail,requires_payee_map}')::boolean, false);
  v_paye_guardrails := case when jsonb_typeof(v_context_json->'paye_guardrails') = 'object' then coalesce(v_context_json->'paye_guardrails', '{}'::jsonb) else '{}'::jsonb end;

  v_pay_channel_scope := NULLIF(UPPER(BTRIM(COALESCE(
    v_context_json->>'pay_channel_scope',
    v_context_json #>> '{filters,pay_channel_scope}',
    v_context_json #>> '{preview_decisions_json,pay_channel_scope}',
    'ALL'
  ))), '');
  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    v_pay_channel_scope := 'ALL';
  END IF;

  v_target_pay_batch_id_raw := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_pay_batch_id',
    v_context_json->>'pay_batch_id',
    v_context_json->>'draft_pay_batch_id',
    v_context_json #>> '{preview_decisions_json,target_pay_batch_id}',
    v_context_json #>> '{preview_decisions_json,pay_batch_id}',
    ''
  )), '');
  IF v_target_pay_batch_id_raw ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_target_pay_batch_id := v_target_pay_batch_id_raw::uuid;
  END IF;

  v_target_operation_source_key := NULLIF(BTRIM(COALESCE(
    v_context_json->>'target_operation_source_key',
    v_context_json #>> '{preview_decisions_json,target_operation_source_key}',
    ''
  )), '');

  SELECT UPPER(NULLIF(BTRIM(COALESCE(public.candidates.pay_method, '')), ''))
  INTO v_candidate_pay_method
  FROM public.candidates
  WHERE public.candidates.id = v_candidate_id;

  v_refresh_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_context_json->>'refresh_scope_kind', v_context_json #>> '{preview_decisions_json,refresh_scope_kind}', ''))), '');
  IF v_refresh_scope_kind NOT IN ('TARGETED_TIMESHEETS', 'CANDIDATE_FULL_LIVE') THEN
    v_refresh_scope_kind := NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') AS targeted_timesheet_id
    FROM (
      SELECT targeted_scope_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'array' THEN v_context_json->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'targeted_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,targeted_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,targeted_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_array(value)
    ) AS targeted_scope_values
    WHERE NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') AS linked_timesheet_id
    FROM (
      SELECT linked_scope_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'array' THEN v_context_json->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_context_json->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_context_json->>'linked_timesheet_ids')
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'array' THEN v_context_json #> '{preview_decisions_json,linked_timesheet_ids}'
          WHEN jsonb_typeof(v_context_json #> '{preview_decisions_json,linked_timesheet_ids}') = 'string' THEN jsonb_build_array(v_context_json #>> '{preview_decisions_json,linked_timesheet_ids}')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_array(value)
    ) AS linked_scope_values
    WHERE NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') IS NOT NULL
  ) AS linked_scope_ids;

  IF v_refresh_scope_kind = 'TARGETED_TIMESHEETS'
     AND jsonb_array_length(v_targeted_timesheet_ids_json) = 0
     AND jsonb_array_length(v_linked_timesheet_ids_json) = 0 THEN
    v_effective_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
  ELSE
    v_effective_refresh_scope_kind := COALESCE(v_refresh_scope_kind, 'CANDIDATE_FULL_LIVE');
  END IF;

  if v_pay_date is null then
    raise exception 'pay_date missing from p_context_json';
  end if;

  if v_week_start is null then
    raise exception 'pay_week_start missing from p_context_json';
  end if;

  if v_eligibility_from_date is null or v_eligibility_to_date is null then
    raise exception 'eligibility window missing from p_context_json';
  end if;

  if v_vat_rate_pct is null or v_erni_pct is null then
    raise exception 'finance window values missing from p_context_json';
  end if;

  if v_rail_provider_default is null or v_rail_env_default is null then
    raise exception 'rail defaults missing from p_context_json';
  end if;

  drop table if exists pg_temp.pay_preview_candidate_context, pg_temp.targeted_refresh_timesheet_ids, pg_temp.linked_refresh_timesheet_ids, pg_temp.targeted_refresh_all_timesheet_ids, pg_temp.active_snoozes, pg_temp.active_timesheet_payment_snoozes, pg_temp.active_segment_snoozes, pg_temp.active_timesheet_payment_overrides, pg_temp.force_include, pg_temp.reserved_batch_items, pg_temp.reserved_by_source_ref, pg_temp.reserved_total_by_timesheet, pg_temp.reserved_segment_key_map, pg_temp.reserved_segment_sums, pg_temp.reserved_preview_segment_ords, pg_temp.reserved_additional_by_code, pg_temp.eligible_tsfin, pg_temp.debted_overpayment_cases, pg_temp.umb_map, pg_temp.adj, pg_temp.ts_current, pg_temp.targeted_baseline_only_ts_current, pg_temp.active_settled_artifact_components, pg_temp.active_settled_artifact_baseline_by_timesheet, pg_temp.ts_baseline, pg_temp.finance_case_baseline_scope, pg_temp.manual_adjustment_carry_forward_scope, pg_temp.segment_status, pg_temp.blocked_items_all, pg_temp.blocked_items, pg_temp.blocked_items_snoozed, pg_temp.do_not_pay_all, pg_temp.do_not_pay_items, pg_temp.do_not_pay_items_snoozed, pg_temp.ts_deltas, pg_temp.ts_itemised, pg_temp.worked_time_current_segment_rows, pg_temp.worked_time_baseline_segment_rows, pg_temp.worked_time_current_ranked, pg_temp.worked_time_baseline_ranked, pg_temp.worked_time_bucket_ids, pg_temp.worked_time_bucket_agg, pg_temp.worked_time_bucket_calc, pg_temp.worked_time_bucket_alloc, pg_temp.worked_time_bucket_effective, pg_temp.worked_time_bucket_component_rows, pg_temp.worked_time_key_totals, pg_temp.worked_time_bucket_component_sums, pg_temp.worked_time_amount_fallback_rows, pg_temp.timesheet_component_rows, pg_temp.timesheet_component_match_rows, pg_temp.transient_timesheet_component_rows, pg_temp.transient_timesheet_component_review_rows, pg_temp.timesheet_case_actionable_basis, pg_temp.timesheet_live_scope, pg_temp.timesheet_linked_scope_counts, pg_temp.transient_timesheet_component_review_rows_effective, pg_temp.timesheet_case_rollup, pg_temp.finance_candidate_seed, pg_temp.candidate_base, pg_temp.timesheet_candidate_rollup, pg_temp.candidate_rollup, pg_temp.blocked_counts, pg_temp.do_not_pay_counts, pg_temp.loan_due, pg_temp.overpayment_balances, pg_temp.loan_due_this_week, pg_temp.loan_repaid_wtd, pg_temp.paid_wtd_before, pg_temp.cand_enriched, pg_temp.payee_baseline_rows, pg_temp.payees_src, pg_temp.payees, pg_temp.payees_enriched, pg_temp.payees_json, pg_temp.cand_payee0, pg_temp.cand_payee, pg_temp.timesheet_case_rollup_effective, pg_temp.finance_case_repaid_wtd, pg_temp.finance_case_recovery_rows_base, pg_temp.manual_debt_recovery_rows, pg_temp.manual_debt_recovery_allocations, pg_temp.manual_debt_recovery_totals, pg_temp.overpayment_recovery_rows, pg_temp.overpayment_recovery_allocations, pg_temp.overpayment_recovery_totals, pg_temp.payment_advance_recovery_rows, pg_temp.payment_advance_recovery_allocations, pg_temp.finance_case_protected_allocations, pg_temp.finance_case_payee_readiness, pg_temp.finance_case_component_rows, pg_temp.finance_case_component_review_rows, pg_temp.finance_case_component_review_rows_effective, pg_temp.finance_case_due_source_amounts, pg_temp.finance_case_component_due_source_base, pg_temp.finance_case_component_due_source_shares, pg_temp.finance_case_component_due_source_allocations, pg_temp.finance_case_component_due_preview_base, pg_temp.finance_case_component_due_preview_allocations, pg_temp.finance_case_taxable_manual_debt_resolution, pg_temp.finance_case_resolution_rollup, pg_temp.canonical_timesheet_lines, pg_temp.timesheet_active_segment_snooze_meta, pg_temp.canonical_timesheet_segment_rows, pg_temp.canonical_timesheet_segment_rollup, pg_temp.canonical_timesheet_presentation_seed, pg_temp.canonical_timesheet_presentation_state, pg_temp.canonical_timesheet_presentation_rows, pg_temp.finance_case_lines, pg_temp.timesheet_canonical_preview_lines, pg_temp.canonical_preview_lines, pg_temp.candidate_preview_line_rollup, pg_temp.candidate_preview_timesheet_rollup, pg_temp.summary_json, pg_temp.timesheet_case_states_flat, pg_temp.finance_case_states_flat, pg_temp.candidate_case_states_flat, pg_temp.candidate_case_states, pg_temp.case_resolution_states_json, pg_temp.finance_candidate_totals, pg_temp.candidate_finance_itemisation, pg_temp.paye_summary_breakdown_json, pg_temp.timesheet_baseline_component_rows, pg_temp.finance_baseline_component_rows, pg_temp.baseline_component_rows_json;

  create temporary table pay_preview_candidate_context on commit drop as
    select
      v_context_json as context_json,
      v_candidate_id as candidate_id,
      v_pay_date as pay_date,
      v_week_ending_cutoff as week_ending_cutoff,
      v_client_id as client_id,
      v_actor_user_id as actor_user_id,
      v_week_start as week_start,
      v_today_uk as today_uk,
      v_pay_eligibility_months_back as pay_eligibility_months_back,
      v_pay_eligibility_weeks_ahead as pay_eligibility_weeks_ahead,
      v_eligibility_from_date as eligibility_from_date,
      v_eligibility_to_date as eligibility_to_date,
      v_vat_rate_pct as vat_rate_pct,
      v_erni_pct as erni_pct,
      v_rail_provider_default as rail_provider_default,
      v_rail_env_default as rail_env_default,
      v_rail_supports_scheduling as rail_supports_scheduling,
      v_rail_supports_name_check as rail_supports_name_check,
      v_rail_supports_auto_execute as rail_supports_auto_execute,
      v_default_schedule_umbrella_local as default_schedule_umbrella_local,
      v_default_schedule_paye_local as default_schedule_paye_local,
      v_funds_warning_hours_json as funds_warning_hours_json,
      v_need_name_check as need_name_check,
      v_requires_payee_map as requires_payee_map,
      v_paye_guardrails as paye_guardrails,
      v_effective_refresh_scope_kind as refresh_scope_kind,
      v_targeted_timesheet_ids_json as targeted_timesheet_ids_json,
      v_linked_timesheet_ids_json as linked_timesheet_ids_json
  ;

  create temporary table targeted_refresh_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(targeted_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(v_targeted_timesheet_ids_json) as targeted_scope_array(value)
    where nullif(btrim(targeted_scope_array.value), '') is not null
  ;

  create temporary table linked_refresh_timesheet_ids on commit drop as
    select distinct
      nullif(btrim(linked_scope_array.value), '')::uuid as timesheet_id
    from jsonb_array_elements_text(v_linked_timesheet_ids_json) as linked_scope_array(value)
    where nullif(btrim(linked_scope_array.value), '') is not null
  ;

  create temporary table targeted_refresh_all_timesheet_ids on commit drop as
    select distinct x.timesheet_id
    from (
      select trti.timesheet_id
      from targeted_refresh_timesheet_ids trti
      union
      select lrti.timesheet_id
      from linked_refresh_timesheet_ids lrti
    ) as x
    where x.timesheet_id is not null
  ;
  create temporary table active_snoozes on commit drop as
        select
          s.id as snooze_id,
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          s.segment_stable_key,
          s.source_ref,
          upper(coalesce(s.snooze_kind,'')) as snooze_kind,
          s.snooze_until_date,
          s.note
        from public.pay_item_snoozes s
        where s.cleared_at_utc is null
          and s.candidate_id = v_candidate_id
          and (
            s.snooze_until_date is null
            or s.snooze_until_date >= v_pay_date
          )
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or s.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or s.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
            or (
              s.booking_id is not null
              and exists (
                select 1
                from public.timesheets ts_scope
                where ts_scope.booking_id = s.booking_id
                  and (
                    ts_scope.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                    or ts_scope.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                  )
              )
            )
            or (s.timesheet_id is null and s.booking_id is null)
          )
  
  ;

  create temporary table active_timesheet_payment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and s.segment_id is null
          and s.segment_stable_key is null
          and s.snooze_kind = 'TIMESHEET_PAYMENT'
  
  ;

  create temporary table active_segment_snoozes on commit drop as
        select
          s.candidate_id,
          s.timesheet_id,
          s.booking_id,
          s.segment_id,
          coalesce(s.segment_stable_key, s.segment_id) as segment_stable_key,
          s.snooze_kind,
          s.snooze_id,
          s.snooze_until_date,
          s.note
        from active_snoozes s
        where s.source_ref is null
          and (s.segment_stable_key is not null or s.segment_id is not null)
          and s.snooze_kind in ('DO_NOT_PAY','BLOCKED_TIMESHEET')
  
  ;

  create temporary table active_timesheet_payment_overrides on commit drop as
        select
          tpo.timesheet_id,
          tpo.candidate_id,
          tpo.id as override_id,
          tpo.reason as override_reason,
          tpo.created_at_utc
        from public.timesheet_payment_overrides tpo
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
          )
  
  ;

  create temporary table force_include on commit drop as
        select distinct
          tpo.timesheet_id
        from public.timesheet_payment_overrides tpo
        where tpo.cleared_at_utc is null
          and tpo.consumed_at_utc is null
          and tpo.consumed_by_pay_batch_id is null
          and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
          and tpo.timesheet_id is not null
          and tpo.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or tpo.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or tpo.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
          )
  
  ;

  create temporary table reserved_batch_items on commit drop as
        -- Items are considered "reserved" if they belong to an ACTIVE (non-cancelled, non-settled) batch.
        -- Policy X/source-target rule: entitlement reservations must subtract the positive ORIGINAL SOURCE
        -- entitlement amount, not the resolved target payout amount. Finance bookkeeping item types are excluded.
        select
          pbi.id as pay_batch_item_id,
          pbc_r.pay_batch_id as pay_batch_id,
          pbi.timesheet_id as timesheet_id,
          pbi.segment_key as segment_key,
          -- Normalise segment_id (some legacy items store it in source_ref 'seg:<id>')
          nullif(
            btrim(coalesce(
              case
                when nullif(btrim(coalesce(pbi.segment_key,'')), '') is not null then pbi.segment_key
                when nullif(btrim(coalesce(pbi.source_ref,'')), '') like 'seg:%' then split_part(pbi.source_ref, ':', 2)
                else null
              end,
              ''
            )),
            ''
          ) as segment_id_norm,
          pbi.source_ref as source_ref,
          pbi.item_type as item_type,
          ecomp.key_type as component_key_type,
          ecomp.key_value as component_key_value,
          ecomp.key_resolution_source as key_resolution_source,
          ecomp.key_resolution_failure_reason as key_resolution_failure_reason,
          round(public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id), 2) as amount_ex_vat
        from public.pay_batch_items pbi
        join public.pay_batch_candidates pbc_r
          on pbc_r.id = pbi.pay_batch_candidate_id
        join public.pay_batches pb_r
          on pb_r.id = pbc_r.pay_batch_id
        left join lateral public._pay_batch_item_economic_components(null::uuid, array[pbi.id]::uuid[]) as ecomp
          on ecomp.pay_batch_item_id = pbi.id
        where pbi.timesheet_id is not null
          and upper(coalesce(pbi.pay_channel,'')) in ('PAYE','UMBRELLA')
          and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
          and public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id) is not null
          and coalesce(pbi.is_voided, false) = false
          and not exists (
            select 1
            from public.pay_payment_correction_items applied_corrections
            where applied_corrections.pay_batch_item_id = pbi.id
              and applied_corrections.status = 'APPLIED'
              and applied_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
          )
          and not (
            upper(btrim(coalesce(pbc_r.settlement_status, ''))) = 'SETTLED'
            or pbc_r.settled_at_utc is not null
            or exists (
              select 1
              from public.pay_bank_transfers completed_transfer_check
              where completed_transfer_check.id = pbi.pay_bank_transfer_id
                and (
                  upper(btrim(coalesce(completed_transfer_check.status, ''))) = 'COMPLETED'
                  or completed_transfer_check.completed_at_utc is not null
                )
            )
          )
          and (
            public._pay_batch_status_is_active_reservation(pb_r.status)
            or exists (
              select 1
              from public.pay_payment_correction_requests open_correction_requests
              join lateral public._pay_payment_correction_selected_items(
                open_correction_requests.pay_batch_id,
                case
                  when jsonb_typeof(open_correction_requests.plan_json->'selected_pay_batch_item_ids') = 'array' then
                    coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                    || jsonb_build_object(
                      'pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids',
                      'expected_pay_batch_item_ids', open_correction_requests.plan_json->'selected_pay_batch_item_ids'
                    )
                  when jsonb_typeof(open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}') = 'array' then
                    coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                    || jsonb_build_object(
                      'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}',
                      'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}'
                    )
                  when jsonb_typeof(open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}') = 'array' then
                    coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                    || jsonb_build_object(
                      'pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}',
                      'expected_pay_batch_item_ids', open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}'
                    )
                  else
                    coalesce(open_correction_requests.selection_json, '{}'::jsonb)
                end,
                false
              ) open_correction_selected_items
                on open_correction_selected_items.pay_batch_id = open_correction_requests.pay_batch_id
              where open_correction_requests.pay_batch_id = pbc_r.pay_batch_id
                and open_correction_requests.status in ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED')
                and open_correction_requests.correction_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
                and open_correction_selected_items.pay_batch_item_id = pbi.id
            )
            or exists (
              select 1
              from public.pay_bank_transfer_events unresolved_terminal_failure_events
              where unresolved_terminal_failure_events.pay_batch_id = pbc_r.pay_batch_id
                and unresolved_terminal_failure_events.pay_bank_transfer_id = pbi.pay_bank_transfer_id
                and unresolved_terminal_failure_events.mapping_status = 'MATCHED'
                and unresolved_terminal_failure_events.normalised_state in ('FAILED','DECLINED','REJECTED','CANCELLED')
                and not exists (
                  select 1
                  from public.pay_payment_correction_items applied_failure_corrections
                  where applied_failure_corrections.pay_batch_item_id = pbi.id
                    and applied_failure_corrections.status = 'APPLIED'
                    and applied_failure_corrections.correction_item_kind in ('NO_MONEY_UNWIND','PRE_BANK_CANCEL','SETTLED_REVERSAL')
                )
            )
          )
  
  ;

  create temporary table reserved_by_source_ref on commit drop as
        select
          rbi.timesheet_id,
          rbi.source_ref,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) <> ''
        group by rbi.timesheet_id, rbi.source_ref
  
  ;

  create temporary table reserved_total_by_timesheet on commit drop as
        select
          rbi.timesheet_id,
          round(sum(rbi.amount_ex_vat),2) as reserved_total_ex_vat
        from reserved_batch_items rbi
        group by rbi.timesheet_id
  
  ;

  create temporary table reserved_segment_key_map on commit drop as
        select
          rbi.timesheet_id,
          rbi.segment_id_norm as segment_id_norm,
          rbi.component_key_type as component_key_type,
          rbi.component_key_value as component_key_value
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
  
  ;

  create temporary table reserved_segment_sums on commit drop as
        select
          rbi.timesheet_id,
          rbi.component_key_type,
          rbi.component_key_value,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'SEGMENT_DELTA'
          and rbi.component_key_type in ('TS_DAY','TS_TOTAL')
          and rbi.component_key_value is not null
          and btrim(coalesce(rbi.component_key_value,'')) <> ''
          and (rbi.component_key_type <> 'TS_DAY' or rbi.component_key_value ~ '^\d{4}-\d{2}-\d{2}$')
        group by rbi.timesheet_id, rbi.component_key_type, rbi.component_key_value
  
  ;

  create temporary table reserved_preview_segment_ords on commit drop as
        select
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end as preview_seg_ord,
          round(sum(rbi.amount_ex_vat),2) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        where rbi.item_type = 'ADJUSTMENT_DELTA'
          and rbi.source_ref is not null
          and btrim(coalesce(rbi.source_ref,'')) like 'preview_seg:%'
        group by
          rbi.timesheet_id,
          case
            when coalesce(split_part(coalesce(rbi.source_ref,''), ':', 3), '') ~ '^\d+$'
              then split_part(rbi.source_ref, ':', 3)::int
            else null
          end
  
  ;

  create temporary table reserved_additional_by_code on commit drop as
        select
          rbi.timesheet_id,
          nullif(btrim(coalesce(bd.bucket_code,'')), '') as code,
          round(
            sum(
              case
                when nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_amount_ex_vat','')), ''))::numeric)
                when nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$'
                  then abs((nullif(btrim(coalesce(bd.meta_json->>'source_pay_ex_vat','')), ''))::numeric)
                else abs(coalesce(bd.amount_ex_vat,0))
              end
            ),
            2
          ) as reserved_amount_ex_vat
        from reserved_batch_items rbi
        join public.pay_batch_item_breakdowns bd
          on bd.pay_batch_item_id = rbi.pay_batch_item_id
        where rbi.item_type in ('ADJUSTMENT_DELTA','SEGMENT_DELTA')
          and bd.line_kind = 'ADDITIONAL_UNIT'
          and bd.bucket_code is not null
          and btrim(coalesce(bd.bucket_code,'')) <> ''
        group by rbi.timesheet_id, nullif(btrim(coalesce(bd.bucket_code,'')), '')
  
  ;

  create temporary table eligible_tsfin on commit drop as
        select
          tf.id as tsfin_id,
          tf.timesheet_id,
          tf.candidate_id,
          tf.client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf.band, con.band, ts.band) as ts_band,

          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,

          upper(coalesce(tf.pay_method,'')) as ts_pay_method,
          upper(coalesce(c.pay_method,'')) as cand_pay_method,

          c.tms_ref as cand_tms_ref,
          c.display_name as cand_display_name,

          c.umbrella_id as cand_umbrella_id,

          -- ✅ Bank readiness (candidate)
          c.bank_details_hash as cand_bank_hash,

          ts.reference_number,
          case when coalesce(con.overrideclientsettings,false) = true then coalesce(con.require_reference_to_pay,false) else coalesce(cs.pay_reference_required,false) end as require_reference_to_pay,

          -- Timesheet advance: force-include even if unauthorised/outside window
          (fi.timesheet_id is not null) as is_forced_advance,

          tf.invoice_breakdown_json,

          ts.sheet_scope as ts_sheet_scope,
          ts.worked_start_iso as ts_worked_start_iso,
          ts.worked_end_iso as ts_worked_end_iso,
          ts.break_start_iso as ts_break_start_iso,
          ts.break_end_iso as ts_break_end_iso,
          ts.break_minutes as ts_break_minutes,
          ts.actual_schedule_json as ts_actual_schedule_json,
          tf.worked_start_iso as tf_worked_start_iso,
          tf.worked_end_iso as tf_worked_end_iso,
          tf.break_start_iso as tf_break_start_iso,
          tf.break_end_iso as tf_break_end_iso,
          tf.break_minutes as tf_break_minutes,
          tf.actual_schedule_json as tf_actual_schedule_json,
          coalesce(tf.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
          coalesce(tf.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
          coalesce(tf.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
          coalesce(tf.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
          coalesce(tf.break_minutes, ts.break_minutes) as effective_break_minutes,
          case
            when jsonb_typeof(tf.actual_schedule_json) = 'object' then tf.actual_schedule_json
            when jsonb_typeof(tf.actual_schedule_json) = 'array' then (
              select tf_sched_item.value
              from jsonb_array_elements(tf.actual_schedule_json) as tf_sched_item(value)
              where tf_sched_item.value is not null
                and jsonb_typeof(tf_sched_item.value) = 'object'
              limit 1
            )
            when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
            when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
              select ts_sched_item.value
              from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
              where ts_sched_item.value is not null
                and jsonb_typeof(ts_sched_item.value) = 'object'
              limit 1
            )
            else null::jsonb
          end as effective_daily_schedule_json,

          tf.total_hours,
          tf.total_pay_ex_vat,
          tf.total_charge_ex_vat,

          tf.hours_day,
          tf.hours_night,
          tf.hours_sat,
          tf.hours_sun,
          tf.hours_bh,
          tf.pay_day,
          tf.pay_night,
          tf.pay_sat,
          tf.pay_sun,
          tf.pay_bh,
          tf.charge_day,
          tf.charge_night,
          tf.charge_sat,
          tf.charge_sun,
          tf.charge_bh,

          -- ✅ Use TSFIN canonical totals for additional units
          tf.additional_pay_ex_vat,
          tf.additional_charge_ex_vat,
          tf.additional_units_json,

          tf.expenses_pay_ex_vat,
          tf.expenses_charge_ex_vat,
          tf.travel_pay_ex_vat,
          tf.travel_charge_ex_vat,
          tf.accommodation_pay_ex_vat,
          tf.accommodation_charge_ex_vat,
          tf.other_pay_ex_vat,
          tf.other_charge_ex_vat,
          tf.mileage_pay_ex_vat,
          tf.mileage_charge_ex_vat,

          -- Baseline snapshot (settled)
          tps.last_settled_snapshot_json,
          tps.last_settled_signature,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as effective_last_settled_signature,

          ts.authorised_at_server,
          tf.pay_on_hold,
          tf.has_rate_issue,
          tf.has_pay_channel_issue,
          tf.processing_status
        from public.timesheets_financials tf
        join public.timesheets ts
          on ts.timesheet_id = tf.timesheet_id
        join public.clients cl
          on cl.id = tf.client_id
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf.client_id
        join public.candidates c
          on c.id = tf.candidate_id
        left join public.timesheet_pay_state tps
          on tps.timesheet_id = tf.timesheet_id
        left join force_include fi
          on fi.timesheet_id = tf.timesheet_id
        where tf.is_current = true
          and coalesce(tf.pay_on_hold,false) = false
          and coalesce(tf.has_rate_issue,false) = false
          and coalesce(tf.has_pay_channel_issue,false) = false
          and upper(coalesce(tf.processing_status::text,'')) not in ('UNASSIGNED','CLIENT_UNRESOLVED','RATE_MISSING','PAY_CHANNEL_MISSING')
          and upper(coalesce(c.pay_method,'')) in ('PAYE','UMBRELLA')

          -- ✅ Eligibility: targeted rows only for TARGETED_TIMESHEETS; current live authorised rows / force include for CANDIDATE_FULL_LIVE
          and (
            (
              v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
              and (
                (
                  tf.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
                  or tf.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
                )
                and (
                  (
                    ts.authorised_at_server is not null
                    and ts.revoked_at is null
                  )
                  or fi.timesheet_id is not null
                )
              )
            )
            or (
              v_effective_refresh_scope_kind = 'CANDIDATE_FULL_LIVE'
              and (
                (
                  ts.authorised_at_server is not null
                  and ts.revoked_at is null
                )
                or fi.timesheet_id is not null
              )
            )
          )

          -- ✅ Optional filters (default ALL/ALL when NULL)
          and (v_candidate_id is null or tf.candidate_id = v_candidate_id)
          and (v_client_id is null or tf.client_id = v_client_id)
  
  ;

  create temporary table debted_overpayment_cases on commit drop as
        select
          pa.candidate_id,
          pa.linked_timesheet_id as timesheet_id,
          pa.baseline_signature
        from public.pay_advances pa
        where pa.advance_kind = 'OVERPAYMENT'::public.pay_advance_kind_enum
          and pa.status in ('ACTIVE'::public.pay_advance_status_enum, 'PAID_OFF'::public.pay_advance_status_enum)
          and pa.candidate_id = v_candidate_id
          and pa.linked_timesheet_id is not null
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or pa.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or pa.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
          )
        group by
          pa.candidate_id,
          pa.linked_timesheet_id,
          pa.baseline_signature
  
  ;

  create temporary table umb_map on commit drop as
        select
          u.id as umbrella_id,
          coalesce(u.enabled,false) as umb_enabled,
          coalesce(u.vat_chargeable,false) as vat_chargeable,
          -- ✅ Bank readiness (umbrella)
          u.bank_details_hash as umb_bank_hash
        from public.umbrellas u
  
  ;

  create temporary table adj on commit drop as
        select
          a.id as adj_id,
          a.timesheet_id,
          a.candidate_id,
          round(coalesce(a.delta_pay_ex_vat,0),2) as delta_pay_ex_vat
        from public.ts_pay_adjustments a
        where a.as_advance = false
          and a.timesheet_id is not null
          and a.candidate_id = v_candidate_id
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or a.timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or a.timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
          )
  
  ;

  create temporary table ts_current on commit drop as
        select
          e.candidate_id,
          e.timesheet_id,
          e.tsfin_id,
          e.client_id,
          e.ts_booking_id,
          e.ts_role,
          e.ts_band,
          e.ts_week_ending_date,
          e.ts_client_name,
          e.ts_pay_method,
          e.cand_pay_method,
          e.cand_tms_ref,
          e.cand_display_name,
          e.cand_umbrella_id,
          e.cand_bank_hash,
          e.reference_number,
          e.require_reference_to_pay,
          coalesce(e.is_forced_advance,false) as is_forced_advance,

          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,

          -- ✅ segments retain stable segment identity for preview/snooze matching
          case
            when e.invoice_breakdown_json is not null
             and jsonb_typeof(e.invoice_breakdown_json) = 'object'
             and upper(coalesce(e.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
             and jsonb_typeof(e.invoice_breakdown_json->'segments') = 'array'
            then (
              select coalesce(jsonb_agg(
                jsonb_build_object(
                  'segment_id', nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                  'pay_amount', round(coalesce(nullif(seg->>'pay_amount','')::numeric,0),2),
                  'charge_amount', round(coalesce(nullif(seg->>'charge_amount','')::numeric, nullif(seg->>'charge_ex_vat','')::numeric,0),2),
                  'units', coalesce(nullif(seg->>'units','')::numeric, nullif(seg->>'hours','')::numeric),
                  'hours', coalesce(nullif(seg->>'hours','')::numeric, nullif(seg->>'units','')::numeric),
                  'hours_day', coalesce(nullif(seg->>'hours_day','')::numeric, 0),
                  'hours_night', coalesce(nullif(seg->>'hours_night','')::numeric, 0),
                  'hours_sat', coalesce(nullif(seg->>'hours_sat','')::numeric, 0),
                  'hours_sun', coalesce(nullif(seg->>'hours_sun','')::numeric, 0),
                  'hours_bh', coalesce(nullif(seg->>'hours_bh','')::numeric, 0),
                  'exclude_from_pay', coalesce(nullif(seg->>'exclude_from_pay','')::boolean, false),
                  'ref_num', nullif(btrim(coalesce(seg->>'ref_num','')), ''),
                  'date', nullif(btrim(coalesce(seg->>'date','')), ''),
                  'segment_key', nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                  'segment_stable_key', coalesce(
                    nullif(btrim(coalesce(seg->>'segment_stable_key','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_id','')), ''),
                    nullif(btrim(coalesce(seg->>'segment_key','')), ''),
                    nullif(btrim(coalesce(seg->>'date','')), ''),
                    nullif(btrim(coalesce(seg->>'ref_num','')), '')
                  ),
                  'start_utc', nullif(btrim(coalesce(seg->>'start_utc','')), ''),
                  'end_utc', nullif(btrim(coalesce(seg->>'end_utc','')), ''),
                  'start', case
                    when nullif(btrim(coalesce(seg->>'start','')), '') is not null then nullif(btrim(coalesce(seg->>'start','')), '')
                    when nullif(btrim(coalesce(seg->>'start_utc','')), '') is not null then to_char(((seg->>'start_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'end', case
                    when nullif(btrim(coalesce(seg->>'end','')), '') is not null then nullif(btrim(coalesce(seg->>'end','')), '')
                    when nullif(btrim(coalesce(seg->>'end_utc','')), '') is not null then to_char(((seg->>'end_utc')::timestamptz at time zone 'Europe/London'), 'HH24:MI')
                    else null
                  end,
                  'break_start', nullif(btrim(coalesce(seg->>'break_start','')), ''),
                  'break_end', nullif(btrim(coalesce(seg->>'break_end','')), ''),
                  'break_mins', coalesce(nullif(seg->>'break_mins','')::numeric, nullif(seg->>'break_minutes','')::numeric),
                  'breaks', case when jsonb_typeof(seg->'breaks') = 'array' then seg->'breaks' else '[]'::jsonb end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              ), '[]'::jsonb)
              from jsonb_array_elements(e.invoice_breakdown_json->'segments') seg
              where seg is not null and jsonb_typeof(seg)='object'
            )
            else case
              when upper(coalesce(e.ts_sheet_scope::text,'')) = 'DAILY'
              then jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', case
                    when e.effective_worked_start_iso is not null then ((e.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'work_date','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'ymd','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'date_ymd','')), '')
                    )
                  end,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', case
                    when e.effective_worked_start_iso is not null then e.effective_worked_start_iso::text
                    else null
                  end,
                  'end_utc', case
                    when e.effective_worked_end_iso is not null then e.effective_worked_end_iso::text
                    else null
                  end,
                  'start', case
                    when e.effective_worked_start_iso is not null then to_char((e.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'start','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_start','')), '')
                    )
                  end,
                  'end', case
                    when e.effective_worked_end_iso is not null then to_char((e.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else coalesce(
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'end','')), ''),
                      nullif(btrim(coalesce(e.effective_daily_schedule_json->>'worked_end','')), '')
                    )
                  end,
                  'break_start', case
                    when e.effective_break_start_iso is not null then to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '')
                  end,
                  'break_end', case
                    when e.effective_break_end_iso is not null then to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                    else nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '')
                  end,
                  'break_mins', coalesce(
                    e.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                    case
                      when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  ),
                  'breaks', case
                    when jsonb_typeof(e.effective_daily_schedule_json->'breaks') = 'array' then e.effective_daily_schedule_json->'breaks'
                    when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', to_char((e.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'end', to_char((e.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            case
                              when e.effective_break_start_iso is not null and e.effective_break_end_iso is not null
                                then greatest(
                                  0::numeric,
                                  round((extract(epoch from (e.effective_break_end_iso - e.effective_break_start_iso)) / 60.0)::numeric, 0)
                                )
                              else null::numeric
                            end
                          )
                        )
                      )
                    when nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), '') is not null
                     and nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), '') is not null
                      then jsonb_build_array(
                        jsonb_build_object(
                          'start', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_start','')), ''),
                          'end', nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_end','')), ''),
                          'break_mins', coalesce(
                            e.effective_break_minutes::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                            nullif(btrim(coalesce(e.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                          )
                        )
                      )
                    else '[]'::jsonb
                  end,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
              else jsonb_build_array(
                jsonb_build_object(
                  'segment_id', ('ts:' || e.timesheet_id::text),
                  'pay_amount', round(coalesce(e.total_pay_ex_vat,0),2),
                  'charge_amount', round(coalesce(e.total_charge_ex_vat,0),2),
                  'units', e.total_hours,
                  'hours', e.total_hours,
                  'hours_day', coalesce(e.hours_day, 0),
                  'hours_night', coalesce(e.hours_night, 0),
                  'hours_sat', coalesce(e.hours_sat, 0),
                  'hours_sun', coalesce(e.hours_sun, 0),
                  'hours_bh', coalesce(e.hours_bh, 0),
                  'exclude_from_pay', false,
                  'ref_num', nullif(btrim(coalesce(e.reference_number,'')), ''),
                  'date', null,
                  'segment_key', ('ts:' || e.timesheet_id::text),
                  'segment_stable_key', ('timesheet:' || coalesce(e.ts_booking_id, e.timesheet_id::text)),
                  'start_utc', null,
                  'end_utc', null,
                  'start', null,
                  'end', null,
                  'break_start', null,
                  'break_end', null,
                  'break_mins', null,
                  'breaks', '[]'::jsonb,
                  'client_name', e.ts_client_name,
                  'role', e.ts_role,
                  'band', e.ts_band
                )
              )
            end
          end as current_segments_json,

          round(coalesce(e.total_hours,0),2) as total_hours,
          round(coalesce(e.total_pay_ex_vat,0),2) as total_pay_ex_vat,
          round(coalesce(e.total_charge_ex_vat,0),2) as total_charge_ex_vat,
          round(coalesce(e.hours_day,0),6) as hours_day,
          round(coalesce(e.hours_night,0),6) as hours_night,
          round(coalesce(e.hours_sat,0),6) as hours_sat,
          round(coalesce(e.hours_sun,0),6) as hours_sun,
          round(coalesce(e.hours_bh,0),6) as hours_bh,
          case when e.pay_day is null then null else round(e.pay_day,6) end as pay_day,
          case when e.pay_night is null then null else round(e.pay_night,6) end as pay_night,
          case when e.pay_sat is null then null else round(e.pay_sat,6) end as pay_sat,
          case when e.pay_sun is null then null else round(e.pay_sun,6) end as pay_sun,
          case when e.pay_bh is null then null else round(e.pay_bh,6) end as pay_bh,
          case when e.charge_day is null then null else round(e.charge_day,6) end as charge_day,
          case when e.charge_night is null then null else round(e.charge_night,6) end as charge_night,
          case when e.charge_sat is null then null else round(e.charge_sat,6) end as charge_sat,
          case when e.charge_sun is null then null else round(e.charge_sun,6) end as charge_sun,
          case when e.charge_bh is null then null else round(e.charge_bh,6) end as charge_bh,
          coalesce(e.additional_units_json, '{}'::jsonb) as current_additional_units_json,

          -- Canonical additional truth is the TSFIN top-level additional bucket plus
          -- additional_units_json. SEGMENTS invoice_breakdown_json.additional is not a
          -- Banking Pay entitlement source: in expense-only manual rows it can be a
          -- catch-all presentation artefact for non-segment totals.
          round(coalesce(e.additional_pay_ex_vat,0),2) as current_additional_pay_ex_vat,
          round(coalesce(e.additional_charge_ex_vat,0),2) as current_additional_charge_ex_vat,
          round(coalesce(e.expenses_pay_ex_vat,0),2) as current_expenses_pay_ex_vat,
          round(coalesce(e.expenses_charge_ex_vat,0),2) as current_expenses_charge_ex_vat,
          round(coalesce(e.travel_pay_ex_vat,0),2) as current_travel_pay_ex_vat,
          round(coalesce(e.travel_charge_ex_vat,0),2) as current_travel_charge_ex_vat,
          round(coalesce(e.accommodation_pay_ex_vat,0),2) as current_accommodation_pay_ex_vat,
          round(coalesce(e.accommodation_charge_ex_vat,0),2) as current_accommodation_charge_ex_vat,
          round(coalesce(e.other_pay_ex_vat,0),2) as current_other_pay_ex_vat,
          round(coalesce(e.other_charge_ex_vat,0),2) as current_other_charge_ex_vat,
          round(coalesce(e.mileage_pay_ex_vat,0),2) as current_mileage_pay_ex_vat,
          round(coalesce(e.mileage_charge_ex_vat,0),2) as current_mileage_charge_ex_vat,

          coalesce(
            (
              select jsonb_agg(
                jsonb_build_object(
                  'id', a.adj_id::text,
                  'delta_pay_ex_vat', a.delta_pay_ex_vat
                )
              )
              from adj a
              where a.timesheet_id = e.timesheet_id
            ),
            '[]'::jsonb
          ) as current_adjustments_json,

          e.last_settled_snapshot_json,
          e.effective_last_settled_signature as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from eligible_tsfin e
        left join umb_map um
          on um.umbrella_id = e.cand_umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = e.candidate_id
         and doc.timesheet_id = e.timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(e.effective_last_settled_signature, '')
  
  ;

  create temporary table targeted_baseline_only_ts_current on commit drop as
        select
          coalesce(tf_any.candidate_id, v_candidate_id) as candidate_id,
          tri.timesheet_id,
          tf_any.id as tsfin_id,
          tf_any.client_id as client_id,
          ts.booking_id as ts_booking_id,
          coalesce(tf_any.role, con.role, ts.job_title_norm) as ts_role,
          coalesce(tf_any.band, con.band, ts.band) as ts_band,
          ts.week_ending_date as ts_week_ending_date,
          cl.name as ts_client_name,
          upper(coalesce(tf_any.pay_method, cand.pay_method, '')) as ts_pay_method,
          upper(coalesce(cand.pay_method, '')) as cand_pay_method,
          cand.tms_ref as cand_tms_ref,
          cand.display_name as cand_display_name,
          cand.umbrella_id as cand_umbrella_id,
          cand.bank_details_hash as cand_bank_hash,
          ts.reference_number,
          case when coalesce(con.overrideclientsettings,false) = true then coalesce(con.require_reference_to_pay,false) else coalesce(cs.pay_reference_required,false) end as require_reference_to_pay,
          false as is_forced_advance,
          coalesce(um.vat_chargeable,false) as umb_vat_chargeable,
          coalesce(um.umb_enabled,false) as umb_enabled,
          um.umb_bank_hash,
          case
            when upper(coalesce(ts.sheet_scope::text,'')) = 'DAILY'
            then jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', case
                  when daily_sched.effective_worked_start_iso is not null then ((daily_sched.effective_worked_start_iso at time zone 'Europe/London')::date)::text
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'work_date','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'ymd','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'date_ymd','')), '')
                  )
                end,
                'segment_key', ('ts:' || tri.timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.timesheet_id::text)),
                'start_utc', case
                  when daily_sched.effective_worked_start_iso is not null then daily_sched.effective_worked_start_iso::text
                  else null
                end,
                'end_utc', case
                  when daily_sched.effective_worked_end_iso is not null then daily_sched.effective_worked_end_iso::text
                  else null
                end,
                'start', case
                  when daily_sched.effective_worked_start_iso is not null then to_char((daily_sched.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'start','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_start','')), '')
                  )
                end,
                'end', case
                  when daily_sched.effective_worked_end_iso is not null then to_char((daily_sched.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else coalesce(
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'end','')), ''),
                    nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'worked_end','')), '')
                  )
                end,
                'break_start', case
                  when daily_sched.effective_break_start_iso is not null then to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '')
                end,
                'break_end', case
                  when daily_sched.effective_break_end_iso is not null then to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
                  else nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '')
                end,
                'break_mins', coalesce(
                  daily_sched.effective_break_minutes::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                  nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
                  case
                    when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                      then greatest(
                        0::numeric,
                        round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                      )
                    else null::numeric
                  end
                ),
                'breaks', case
                  when jsonb_typeof(daily_sched.effective_daily_schedule_json->'breaks') = 'array' then daily_sched.effective_daily_schedule_json->'breaks'
                  when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', to_char((daily_sched.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'end', to_char((daily_sched.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          case
                            when daily_sched.effective_break_start_iso is not null and daily_sched.effective_break_end_iso is not null
                              then greatest(
                                0::numeric,
                                round((extract(epoch from (daily_sched.effective_break_end_iso - daily_sched.effective_break_start_iso)) / 60.0)::numeric, 0)
                              )
                            else null::numeric
                          end
                        )
                      )
                    )
                  when nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), '') is not null
                   and nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), '') is not null
                    then jsonb_build_array(
                      jsonb_build_object(
                        'start', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_start','')), ''),
                        'end', nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_end','')), ''),
                        'break_mins', coalesce(
                          daily_sched.effective_break_minutes::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                          nullif(btrim(coalesce(daily_sched.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                        )
                      )
                    )
                  else '[]'::jsonb
                end,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
            else jsonb_build_array(
              jsonb_build_object(
                'segment_id', ('ts:' || tri.timesheet_id::text),
                'pay_amount', 0,
                'charge_amount', 0,
                'units', 0,
                'hours', 0,
                'hours_day', 0,
                'hours_night', 0,
                'hours_sat', 0,
                'hours_sun', 0,
                'hours_bh', 0,
                'exclude_from_pay', false,
                'ref_num', nullif(btrim(coalesce(ts.reference_number,'')), ''),
                'date', null,
                'segment_key', ('ts:' || tri.timesheet_id::text),
                'segment_stable_key', ('timesheet:' || coalesce(ts.booking_id, tri.timesheet_id::text)),
                'start_utc', null,
                'end_utc', null,
                'start', null,
                'end', null,
                'break_start', null,
                'break_end', null,
                'break_mins', null,
                'breaks', '[]'::jsonb,
                'client_name', cl.name,
                'role', coalesce(tf_any.role, con.role, ts.job_title_norm),
                'band', coalesce(tf_any.band, con.band, ts.band)
              )
            )
          end as current_segments_json,
          0::numeric as total_hours,
          0::numeric as total_pay_ex_vat,
          0::numeric as total_charge_ex_vat,
          0::numeric as hours_day,
          0::numeric as hours_night,
          0::numeric as hours_sat,
          0::numeric as hours_sun,
          0::numeric as hours_bh,
          null::numeric as pay_day,
          null::numeric as pay_night,
          null::numeric as pay_sat,
          null::numeric as pay_sun,
          null::numeric as pay_bh,
          null::numeric as charge_day,
          null::numeric as charge_night,
          null::numeric as charge_sat,
          null::numeric as charge_sun,
          null::numeric as charge_bh,
          '{}'::jsonb as current_additional_units_json,
          0::numeric as current_additional_pay_ex_vat,
          0::numeric as current_additional_charge_ex_vat,
          0::numeric as current_expenses_pay_ex_vat,
          0::numeric as current_expenses_charge_ex_vat,
          0::numeric as current_travel_pay_ex_vat,
          0::numeric as current_travel_charge_ex_vat,
          0::numeric as current_accommodation_pay_ex_vat,
          0::numeric as current_accommodation_charge_ex_vat,
          0::numeric as current_other_pay_ex_vat,
          0::numeric as current_other_charge_ex_vat,
          0::numeric as current_mileage_pay_ex_vat,
          0::numeric as current_mileage_charge_ex_vat,
          '[]'::jsonb as current_adjustments_json,
          tps.last_settled_snapshot_json,
          coalesce(
            tps.last_settled_signature,
            md5(coalesce(tps.last_settled_snapshot_json::text, '{}'))
          ) as baseline_signature,
          (doc.timesheet_id is not null) as has_active_overpayment_case
        from targeted_refresh_all_timesheet_ids tri
        join public.timesheet_pay_state tps
          on tps.timesheet_id = tri.timesheet_id
        left join lateral (
          select tf.*
          from public.timesheets_financials tf
          where tf.timesheet_id = tri.timesheet_id
          order by tf.is_current desc, tf.computed_at_utc desc nulls last, tf.id desc
          limit 1
        ) tf_any on true
        join public.candidates cand
          on cand.id = coalesce(tf_any.candidate_id, v_candidate_id)
        left join public.timesheets ts
          on ts.timesheet_id = tri.timesheet_id
        left join lateral (
          select
            coalesce(tf_any.worked_start_iso, ts.worked_start_iso) as effective_worked_start_iso,
            coalesce(tf_any.worked_end_iso, ts.worked_end_iso) as effective_worked_end_iso,
            coalesce(tf_any.break_start_iso, ts.break_start_iso) as effective_break_start_iso,
            coalesce(tf_any.break_end_iso, ts.break_end_iso) as effective_break_end_iso,
            coalesce(tf_any.break_minutes, ts.break_minutes) as effective_break_minutes,
            case
              when jsonb_typeof(tf_any.actual_schedule_json) = 'object' then tf_any.actual_schedule_json
              when jsonb_typeof(tf_any.actual_schedule_json) = 'array' then (
                select tf_sched_item.value
                from jsonb_array_elements(tf_any.actual_schedule_json) as tf_sched_item(value)
                where tf_sched_item.value is not null
                  and jsonb_typeof(tf_sched_item.value) = 'object'
                limit 1
              )
              when jsonb_typeof(ts.actual_schedule_json) = 'object' then ts.actual_schedule_json
              when jsonb_typeof(ts.actual_schedule_json) = 'array' then (
                select ts_sched_item.value
                from jsonb_array_elements(ts.actual_schedule_json) as ts_sched_item(value)
                where ts_sched_item.value is not null
                  and jsonb_typeof(ts_sched_item.value) = 'object'
                limit 1
              )
              else null::jsonb
            end as effective_daily_schedule_json
        ) daily_sched on true
        left join public.contracts con
          on con.id = ts.contract_id
        left join public.client_settings cs
          on cs.client_id = tf_any.client_id
        left join public.clients cl
          on cl.id = tf_any.client_id
        left join umb_map um
          on um.umbrella_id = cand.umbrella_id
        left join debted_overpayment_cases doc
          on doc.candidate_id = coalesce(tf_any.candidate_id, v_candidate_id)
         and doc.timesheet_id = tri.timesheet_id
         and coalesce(doc.baseline_signature, '') = coalesce(tps.last_settled_signature, md5(coalesce(tps.last_settled_snapshot_json::text, '{}')))
        where v_effective_refresh_scope_kind = 'TARGETED_TIMESHEETS'
          and (
            tps.last_settled_snapshot_json is not null
            or tps.last_settled_signature is not null
            or tps.last_settled_pay_batch_id is not null
            or tps.last_settled_at_utc is not null
          )
          and not exists (
            select 1
            from ts_current cur
            where cur.timesheet_id = tri.timesheet_id
          )
  ;

  create temporary table active_settled_artifact_components on commit drop as
        select
          active_settled_components.timesheet_id,
          active_settled_components.key_type,
          active_settled_components.key_value,
          active_settled_components.amount_ex_vat,
          active_settled_components.amount_inc_vat
        from public._pay_active_settled_components(
          ARRAY(
            select distinct active_baseline_scope.timesheet_id
            from (
              select ts_current.timesheet_id
              from ts_current
              where ts_current.timesheet_id is not null
              union
              select targeted_baseline_only_ts_current.timesheet_id
              from targeted_baseline_only_ts_current
              where targeted_baseline_only_ts_current.timesheet_id is not null
            ) as active_baseline_scope
          )
        ) as active_settled_components
        where active_settled_components.timesheet_id is not null
          and active_settled_components.key_type is not null
          and active_settled_components.key_value is not null
  ;

  create temporary table active_settled_artifact_baseline_by_timesheet on commit drop as
        select
          active_settled_artifact_components.timesheet_id,
          coalesce(
            jsonb_agg(
              jsonb_build_object(
                'key_type', active_settled_artifact_components.key_type,
                'key_value', active_settled_artifact_components.key_value,
                'amount_ex_vat', active_settled_artifact_components.amount_ex_vat,
                'amount_inc_vat', active_settled_artifact_components.amount_inc_vat,
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT'
              )
              order by active_settled_artifact_components.key_type, active_settled_artifact_components.key_value
            ),
            '[]'::jsonb
          ) as active_settled_components_json,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_ex_vat, 0)), 0), 2)::numeric as active_settled_amount_ex_vat,
          round(coalesce(sum(coalesce(active_settled_artifact_components.amount_inc_vat, 0)), 0), 2)::numeric as active_settled_amount_inc_vat,
          count(*)::int as active_settled_component_count
        from active_settled_artifact_components
        group by active_settled_artifact_components.timesheet_id
  ;

  create temporary table ts_baseline on commit drop as
        select
          t.candidate_id,
          t.timesheet_id,
          t.client_id,
          t.ts_booking_id,
          t.ts_role,
          t.ts_band,
          t.ts_week_ending_date,
          t.ts_client_name,
          t.ts_pay_method,
          t.cand_pay_method,
          t.cand_tms_ref,
          t.cand_display_name,
          t.cand_umbrella_id,
          t.umb_enabled,
          t.umb_vat_chargeable,
          t.require_reference_to_pay,
          t.is_forced_advance,

          -- ✅ bank readiness propagation
          t.cand_bank_hash,
          t.umb_bank_hash,

          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then
              jsonb_build_object(
                'baseline_source', 'ACTIVE_SETTLED_ARTIFACT',
                'active_settled_artifact_components', coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb),
                'active_settled_amount_ex_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0),
                'active_settled_amount_inc_vat', coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0),
                'legacy_timesheet_pay_state_snapshot_json', coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
              )
            else coalesce(t.last_settled_snapshot_json, '{}'::jsonb)
          end as base_json,
          coalesce(active_settled_artifact_baseline.active_settled_components_json, '[]'::jsonb) as active_settled_artifact_components_json,
          coalesce(active_settled_artifact_baseline.active_settled_component_count, 0)::int as active_settled_artifact_component_count,
          coalesce(active_settled_artifact_baseline.active_settled_amount_ex_vat, 0)::numeric as active_settled_artifact_amount_ex_vat,
          coalesce(active_settled_artifact_baseline.active_settled_amount_inc_vat, 0)::numeric as active_settled_artifact_amount_inc_vat,
          (coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0) as has_active_settled_artifact_baseline,
          t.baseline_signature,
          coalesce(t.has_active_overpayment_case,false) as has_active_overpayment_case,

          coalesce(t.current_segments_json, '[]'::jsonb) as current_segments_json,
          coalesce(t.current_adjustments_json, '[]'::jsonb) as current_adjustments_json,

          t.total_hours,
          t.total_pay_ex_vat,
          t.total_charge_ex_vat,
          t.hours_day,
          t.hours_night,
          t.hours_sat,
          t.hours_sun,
          t.hours_bh,
          t.pay_day,
          t.pay_night,
          t.pay_sat,
          t.pay_sun,
          t.pay_bh,
          t.charge_day,
          t.charge_night,
          t.charge_sat,
          t.charge_sun,
          t.charge_bh,
          t.hours_day as cur_hours_day,
          t.hours_night as cur_hours_night,
          t.hours_sat as cur_hours_sat,
          t.hours_sun as cur_hours_sun,
          t.hours_bh as cur_hours_bh,
          t.pay_day as cur_pay_day,
          t.pay_night as cur_pay_night,
          t.pay_sat as cur_pay_sat,
          t.pay_sun as cur_pay_sun,
          t.pay_bh as cur_pay_bh,
          t.charge_day as cur_charge_day,
          t.charge_night as cur_charge_night,
          t.charge_sat as cur_charge_sat,
          t.charge_sun as cur_charge_sun,
          t.charge_bh as cur_charge_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,day}')::numeric), 6)
            else 0::numeric
          end as bas_hours_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,night}')::numeric), 6)
            else 0::numeric
          end as bas_hours_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sat}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,sun}')::numeric), 6)
            else 0::numeric
          end as bas_hours_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then 0::numeric
            when coalesce(t.last_settled_snapshot_json->>'hours_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'hours_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,bh}')::numeric), 6)
            else 0::numeric
          end as bas_hours_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_pay_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_pay_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_pay_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_pay_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'pay_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'pay_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,pay_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_pay_bh,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_day', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_day')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,day}')::numeric), 6)
            else null::numeric
          end as bas_charge_day,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_night', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_night')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,night}')::numeric), 6)
            else null::numeric
          end as bas_charge_night,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sat', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sat')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sat}')::numeric), 6)
            else null::numeric
          end as bas_charge_sat,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_sun', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_sun')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,sun}')::numeric), 6)
            else null::numeric
          end as bas_charge_sun,
          case
            when coalesce(active_settled_artifact_baseline.active_settled_component_count, 0) > 0 then null::numeric
            when coalesce(t.last_settled_snapshot_json->>'charge_bh', t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}', '') ~ '^-?\d+(\.\d+)?$'
              then round(coalesce((t.last_settled_snapshot_json->>'charge_bh')::numeric, (t.last_settled_snapshot_json #>> '{invoice_breakdown_json,base_hours,charge_rates,bh}')::numeric), 6)
            else null::numeric
          end as bas_charge_bh,
          t.current_additional_pay_ex_vat,
          t.current_additional_charge_ex_vat,
          t.current_additional_units_json,
          t.current_expenses_pay_ex_vat,
          t.current_expenses_charge_ex_vat,
          t.current_travel_pay_ex_vat,
          t.current_travel_charge_ex_vat,
          t.current_accommodation_pay_ex_vat,
          t.current_accommodation_charge_ex_vat,
          t.current_other_pay_ex_vat,
          t.current_other_charge_ex_vat,
          t.current_mileage_pay_ex_vat,
          t.current_mileage_charge_ex_vat
        from (
          select * from ts_current
          union all
          select * from targeted_baseline_only_ts_current
        ) t
        left join active_settled_artifact_baseline_by_timesheet as active_settled_artifact_baseline
          on active_settled_artifact_baseline.timesheet_id = t.timesheet_id
  
  ;

  create temporary table finance_case_baseline_scope on commit drop as
        select
          vfcr.*
        from public.v_finance_cases_register vfcr
        where vfcr.case_type in (
          'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
          'OVERPAYMENT'::public.pay_finance_case_type_enum,
          'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
          'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
        )
          and upper(coalesce(vfcr.status::text,'')) = 'ACTIVE'
          and coalesce(vfcr.outstanding_amount,0) > 0
          and not (vfcr.active_snooze_id is not null and vfcr.active_snooze_until_date is null)
          and (
            (
              vfcr.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
              and (
                upper(coalesce(vfcr.payout_status::text,'')) <> 'PAID'
                or vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
              and (
                vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
              and (
                vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              and (
                upper(coalesce(vfcr.payout_status::text,'')) <> 'PAID'
                or vfcr.next_due_week_start is null
                or vfcr.next_due_week_start <= v_week_start
              )
            )
            or (
              vfcr.case_type in (
                'OVERPAYMENT'::public.pay_finance_case_type_enum,
                'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
                'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
              )
              and exists (
                select 1
                from public.pay_finance_case_components as pfc_restructure_scope
                join public.candidates as c_restructure_scope
                  on c_restructure_scope.id = pfc_restructure_scope.candidate_id
                where pfc_restructure_scope.finance_case_id = vfcr.finance_case_id
                  and pfc_restructure_scope.closed_at_utc is null
                  and pfc_restructure_scope.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
                  and round(coalesce(pfc_restructure_scope.remaining_source_amount, 0), 2) > 0
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(c_restructure_scope.pay_method, '')) in ('PAYE', 'UMBRELLA')
                  and upper(coalesce(pfc_restructure_scope.source_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  and (
                    coalesce(pfc_restructure_scope.is_resolution_stale, false) = true
                    or nullif(btrim(coalesce(pfc_restructure_scope.saved_target_pay_method, '')), '') is null
                    or upper(coalesce(pfc_restructure_scope.saved_target_pay_method, '')) <> upper(coalesce(c_restructure_scope.pay_method, ''))
                  )
              )
            )
          )
          and (v_candidate_id is null or vfcr.candidate_id = v_candidate_id)
          and (v_client_id is null or vfcr.client_id = v_client_id)
          and (
            v_effective_refresh_scope_kind <> 'TARGETED_TIMESHEETS'
            or vfcr.linked_timesheet_id is null
            or vfcr.linked_timesheet_id in (select trti.timesheet_id from targeted_refresh_timesheet_ids trti)
            or vfcr.linked_timesheet_id in (select lrti.timesheet_id from linked_refresh_timesheet_ids lrti)
          )
  
  ;



  create temporary table manual_adjustment_carry_forward_scope on commit drop as
        select
          carry_forward_rows.id,
          carry_forward_rows.source_pay_batch_id,
          carry_forward_rows.source_pay_batch_item_id,
          carry_forward_rows.source_pay_bank_transfer_id,
          carry_forward_rows.source_pay_batch_candidate_id,
          carry_forward_rows.source_correction_request_id,
          carry_forward_rows.source_correction_work_item_id,
          carry_forward_rows.candidate_id,
          carry_forward_rows.umbrella_id,
          carry_forward_rows.client_id,
          carry_forward_rows.timesheet_id,
          carry_forward_rows.pay_channel,
          carry_forward_rows.adjustment_direction,
          carry_forward_rows.amount_ex_vat,
          carry_forward_rows.amount_vat,
          carry_forward_rows.amount_inc_vat,
          carry_forward_rows.amount_basis,
          carry_forward_rows.paye_treatment,
          carry_forward_rows.tax_treatment_json,
          carry_forward_rows.description,
          carry_forward_rows.reason,
          carry_forward_rows.source_ref,
          carry_forward_rows.source_operation_source_key,
          carry_forward_rows.source_snapshot_json,
          carry_forward_rows.status,
          carry_forward_rows.target_pay_batch_id,
          carry_forward_rows.target_pay_batch_item_id,
          carry_forward_rows.target_operation_source_key,
          carry_forward_rows.created_at_utc,
          carry_forward_rows.updated_at_utc,
          carry_forward_rows.reserved_at_utc,
          carry_forward_rows.consumed_at_utc,
          carry_forward_rows.released_at_utc,
          carry_forward_rows.cancelled_at_utc,
          carry_forward_rows.status_reason,
          COALESCE(source_batch_rows.execution_commit_ref, carry_forward_rows.source_pay_batch_id::text) AS source_batch_ref
        from public.pay_manual_adjustment_carry_forwards as carry_forward_rows
        left join public.pay_batches as source_batch_rows
          on source_batch_rows.id = carry_forward_rows.source_pay_batch_id
        where carry_forward_rows.candidate_id = v_candidate_id
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) in ('PENDING_CARRY_FORWARD', 'RESERVED_IN_DRAFT')
          and upper(btrim(coalesce(carry_forward_rows.status, ''))) not in ('CONSUMED_IN_BATCH', 'CANCELLED', 'SUPERSEDED', 'NEEDS_REVIEW')
          and (
            (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'PENDING_CARRY_FORWARD'
              and carry_forward_rows.target_pay_batch_id is null
              and carry_forward_rows.target_pay_batch_item_id is null
              and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') is null
            )
            or (
              upper(btrim(coalesce(carry_forward_rows.status, ''))) = 'RESERVED_IN_DRAFT'
              and (
                (v_target_pay_batch_id is not null and carry_forward_rows.target_pay_batch_id = v_target_pay_batch_id)
                or (
                  v_target_operation_source_key is not null
                  and nullif(btrim(coalesce(carry_forward_rows.target_operation_source_key, '')), '') = v_target_operation_source_key
                )
              )
            )
          )
          and (
            (
              v_pay_channel_scope = 'ALL'
              and (
                v_candidate_pay_method is null
                or upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_candidate_pay_method
              )
            )
            or (
              v_pay_channel_scope <> 'ALL'
              and upper(btrim(coalesce(carry_forward_rows.pay_channel, ''))) = v_pay_channel_scope
            )
          )
  ;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'refresh_scope_kind', v_effective_refresh_scope_kind,
    'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
    'linked_timesheet_ids', v_linked_timesheet_ids_json,
    'ts_baseline_count', (select count(*)::int from ts_baseline),
    'finance_case_scope_count', (select count(*)::int from finance_case_baseline_scope),
    'manual_adjustment_carry_forward_count', (select count(*)::int from manual_adjustment_carry_forward_scope),
    'active_snooze_count', (select count(*)::int from active_snoozes)
  );
end;
$function$;









DROP FUNCTION IF EXISTS public.pay_workbench_session_open(uuid, date, date, jsonb, text);

DROP FUNCTION IF EXISTS public.pay_workbench_session_open(uuid, date, date, jsonb, text);




CREATE OR REPLACE FUNCTION public.pay_workbench_session_open(
  p_actor_user_id uuid,
  p_pay_date date,
  p_week_ending_cutoff date,
  p_filters_json jsonb,
  p_session_signature text,
  p_force_new_session boolean DEFAULT false,
  p_discard_source_session boolean DEFAULT false,
  p_source_session_id uuid DEFAULT NULL::uuid,
  p_obsolete_session_ids jsonb DEFAULT '[]'::jsonb,
  p_mutation_context text DEFAULT NULL::text,
  p_created_pay_batch_ids jsonb DEFAULT '[]'::jsonb,
  p_dirty_candidate_ids jsonb DEFAULT '[]'::jsonb,
  p_refresh_job_ids jsonb DEFAULT '[]'::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_filters_json jsonb := CASE WHEN jsonb_typeof(COALESCE(p_filters_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_filters_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_session_signature text := BTRIM(COALESCE(p_session_signature, ''));
  v_snapshot_info_json jsonb := '{}'::jsonb;
  v_snapshot_run_id uuid := NULL::uuid;
  v_effective_week_ending_cutoff date := DATE '9999-12-31';
  v_context_json jsonb := '{}'::jsonb;
  v_scope_resolution_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_scope_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_existing_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_open_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_session_id uuid := NULL::uuid;
  v_scope_candidate_id uuid := NULL::uuid;
  v_snapshot_candidate_row public.banking_pay_snapshot_candidate_state%ROWTYPE;
  v_action text := '';
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_filter_candidate_id uuid := NULL::uuid;
  v_filter_client_id uuid := NULL::uuid;
  v_session_version bigint := 0;
  v_server_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_server_selected_preview_row_ids_provided boolean := false;
  v_enqueue_candidate_refresh_json jsonb := '{}'::jsonb;
  v_pending_job_id uuid := NULL::uuid;
  v_scope_live_change_seq bigint := 0;
  v_existing_snapshot_job_id uuid := NULL::uuid;
  v_existing_snapshot_job_source_change_seq bigint := 0;
  v_current_workbench_signature_version integer := 3;
  v_current_workbench_signature_kind text := 'BANKING_PAY_WORKBENCH';
  v_legacy_redesign_boundary_utc timestamptz := TIMESTAMPTZ '2026-04-15T00:00:00.000Z';
  v_legacy_session_row record;
  v_legacy_signature_json jsonb := NULL;
  v_legacy_signature_version integer := NULL;
  v_legacy_signature_kind text := NULL;
  v_requested_pay_date date := p_pay_date;
  v_effective_pay_date date := p_pay_date;
  v_current_london_pay_date date := timezone('Europe/London', v_now)::date;
  v_is_unfiltered boolean := false;
  v_requested_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_current_ready_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_next_ready_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_nearest_ready_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_requested_run_has_ready boolean := false;
  v_signature_source_json jsonb := '{}'::jsonb;
  v_signature_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_signature_filters_json jsonb := '{}'::jsonb;
  v_signature_filter_entry record;
  v_candidate_filter_id_text text := '';
  v_client_filter_id_text text := '';
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_snapshot_projection_version integer := 0;
  v_snapshot_hidden_recovery_template_projection_version integer := 0;
  v_snapshot_has_visible_paye_manual_debt_net_deduct boolean := false;
  v_snapshot_has_matching_hidden_paye_manual_debt_template boolean := false;
  v_open_progress_json jsonb := '{}'::jsonb;
  v_open_ready_flag boolean := false;
  v_open_total_count integer := 0;
  v_open_completed_count integer := 0;
  v_open_pending_count integer := 0;
  v_open_failed_count integer := 0;
  v_open_ready_empty boolean := false;
  v_force_new_session boolean := false;
  v_discard_source_session boolean := false;
  v_source_session_id uuid := NULL::uuid;
  v_obsolete_session_ids uuid[] := ARRAY[]::uuid[];
  v_obsolete_session_ids_jsonb jsonb := '[]'::jsonb;
  v_mutation_context text := NULL::text;
  v_previous_session_id uuid := NULL::uuid;
  v_source_session_discarded boolean := false;
  v_source_session_discard_json jsonb := NULL::jsonb;
  v_dirty_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_dirty_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_created_pay_batch_ids_jsonb jsonb := '[]'::jsonb;
  v_refresh_job_ids uuid[] := ARRAY[]::uuid[];
  v_refresh_job_ids_jsonb jsonb := '[]'::jsonb;
  v_post_mutation_requires_refresh boolean := false;
  v_mutation_refresh_reason text := 'SESSION_OPEN_WARMUP';
  v_candidate_is_dirty boolean := false;
  v_candidate_refresh_reason text := 'SESSION_OPEN_WARMUP';
  v_pending_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_pending_dirty_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_pending_dirty_candidate_count integer := 0;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  IF v_session_signature = '' THEN
    RAISE EXCEPTION 'session_signature is required';
  END IF;

  PERFORM 1
  FROM public.tms_users AS tu
  WHERE tu.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  v_force_new_session := COALESCE(p_force_new_session, false) OR COALESCE(p_discard_source_session, false);
  v_discard_source_session := COALESCE(p_discard_source_session, false) OR v_force_new_session;
  v_source_session_id := p_source_session_id;
  v_mutation_context := NULLIF(BTRIM(COALESCE(p_mutation_context, '')), '');

  SELECT
    COALESCE(array_agg(DISTINCT obsolete_input.obsolete_session_id ORDER BY obsolete_input.obsolete_session_id), ARRAY[]::uuid[]),
    COALESCE(jsonb_agg(to_jsonb(obsolete_input.obsolete_session_id::text) ORDER BY obsolete_input.obsolete_session_id::text), '[]'::jsonb)
  INTO v_obsolete_session_ids, v_obsolete_session_ids_jsonb
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(obsolete_element.value), '')::uuid AS obsolete_session_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(p_obsolete_session_ids, '[]'::jsonb)) = 'array' THEN COALESCE(p_obsolete_session_ids, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS obsolete_element(value)
    WHERE NULLIF(BTRIM(obsolete_element.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION
    SELECT v_source_session_id
    WHERE v_source_session_id IS NOT NULL
  ) AS obsolete_input;

  SELECT
    COALESCE(array_agg(DISTINCT dirty_input.dirty_candidate_id ORDER BY dirty_input.dirty_candidate_id), ARRAY[]::uuid[]),
    COALESCE(jsonb_agg(to_jsonb(dirty_input.dirty_candidate_id::text) ORDER BY dirty_input.dirty_candidate_id::text), '[]'::jsonb)
  INTO v_dirty_candidate_ids, v_dirty_candidate_ids_jsonb
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(dirty_element.value), '')::uuid AS dirty_candidate_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(p_dirty_candidate_ids, '[]'::jsonb)) = 'array' THEN COALESCE(p_dirty_candidate_ids, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS dirty_element(value)
    WHERE NULLIF(BTRIM(dirty_element.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS dirty_input;

  SELECT COALESCE(jsonb_agg(to_jsonb(created_batch_input.created_pay_batch_id::text) ORDER BY created_batch_input.created_pay_batch_id::text), '[]'::jsonb)
  INTO v_created_pay_batch_ids_jsonb
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(created_batch_element.value), '')::uuid AS created_pay_batch_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(p_created_pay_batch_ids, '[]'::jsonb)) = 'array' THEN COALESCE(p_created_pay_batch_ids, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS created_batch_element(value)
    WHERE NULLIF(BTRIM(created_batch_element.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS created_batch_input;

  SELECT
    COALESCE(array_agg(DISTINCT refresh_job_input.refresh_job_id ORDER BY refresh_job_input.refresh_job_id), ARRAY[]::uuid[]),
    COALESCE(jsonb_agg(to_jsonb(refresh_job_input.refresh_job_id::text) ORDER BY refresh_job_input.refresh_job_id::text), '[]'::jsonb)
  INTO v_refresh_job_ids, v_refresh_job_ids_jsonb
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(refresh_job_element.value), '')::uuid AS refresh_job_id
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(p_refresh_job_ids, '[]'::jsonb)) = 'array' THEN COALESCE(p_refresh_job_ids, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS refresh_job_element(value)
    WHERE NULLIF(BTRIM(refresh_job_element.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS refresh_job_input;

  v_post_mutation_requires_refresh := (
    v_mutation_context IS NOT NULL
    OR COALESCE(array_length(v_dirty_candidate_ids, 1), 0) > 0
    OR COALESCE(jsonb_array_length(v_created_pay_batch_ids_jsonb), 0) > 0
    OR COALESCE(array_length(v_refresh_job_ids, 1), 0) > 0
  );

  v_mutation_refresh_reason := CASE
    WHEN UPPER(COALESCE(v_mutation_context, '')) IN ('CREATE_DRAFT_SUCCESS', 'POST_DRAFT_CREATE_PREVIEW_REFRESH', 'POST_DRAFT_CREATE_DISCARD_AND_REOPEN', 'DRAFT_CREATED')
      OR COALESCE(jsonb_array_length(v_created_pay_batch_ids_jsonb), 0) > 0
      THEN 'DRAFT_CREATED'
    WHEN UPPER(COALESCE(v_mutation_context, '')) IN ('CANCEL_DELETE_DRAFT_SUCCESS', 'POST_DRAFT_CANCEL_PREVIEW_REFRESH', 'POST_DRAFT_CANCEL_DISCARD_AND_REOPEN', 'DRAFT_CANCELLED', 'DRAFT_CANCELED')
      THEN 'DRAFT_CANCELLED'
    WHEN UPPER(COALESCE(v_mutation_context, '')) IN ('PAY_BATCH_CANCELLED', 'PAY_BATCH_CANCELED', 'BATCH_CANCELLED', 'BATCH_CANCELED')
      OR UPPER(COALESCE(v_mutation_context, '')) LIKE '%PAY_BATCH_CANCEL%'
      THEN 'PAY_BATCH_CANCELLED'
    WHEN v_post_mutation_requires_refresh THEN 'SESSION_OPEN_POST_MUTATION'
    ELSE 'SESSION_OPEN_WARMUP'
  END;

  IF v_post_mutation_requires_refresh THEN
    v_force_new_session := true;
    v_discard_source_session := true;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  PERFORM pg_advisory_xact_lock(hashtext('public.pay_workbench_session_open.single_open'));

  v_effective_week_ending_cutoff := COALESCE(p_week_ending_cutoff, DATE '9999-12-31');

  IF BTRIM(COALESCE(v_filters_json->>'candidate_id', v_filters_json->>'candidateId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(v_filters_json->>'candidate_id', v_filters_json->>'candidateId')::uuid;
  END IF;

  IF BTRIM(COALESCE(v_filters_json->>'client_id', v_filters_json->>'clientId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(v_filters_json->>'client_id', v_filters_json->>'clientId')::uuid;
  END IF;

  v_is_unfiltered := v_filter_candidate_id IS NULL AND v_filter_client_id IS NULL;


  IF v_is_unfiltered THEN
    SELECT sr.*
    INTO v_requested_snapshot_run_row
    FROM public.banking_pay_snapshot_runs AS sr
    WHERE sr.pay_date = v_requested_pay_date
      AND sr.week_ending_cutoff = v_effective_week_ending_cutoff
      AND COALESCE(sr.is_active, false) = true
      AND UPPER(COALESCE(sr.status, '')) = 'READY'
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_snapshot_candidate_state AS scs
        WHERE scs.snapshot_run_id = sr.id
          AND scs.candidate_id IS NOT NULL
          AND UPPER(COALESCE(scs.status, '')) = 'READY'
      )
    ORDER BY sr.created_at_utc DESC, sr.id DESC
    LIMIT 1;

    v_requested_run_has_ready := v_requested_snapshot_run_row.id IS NOT NULL;

    IF v_requested_run_has_ready THEN
      v_snapshot_run_id := v_requested_snapshot_run_row.id;
      v_effective_pay_date := v_requested_pay_date;
      v_snapshot_info_json := jsonb_build_object(
        'ok', true,
        'snapshot_run_id', v_snapshot_run_id::text,
        'pay_date', v_effective_pay_date::text,
        'week_ending_cutoff', v_effective_week_ending_cutoff::text,
        'status', v_requested_snapshot_run_row.status,
        'is_active', v_requested_snapshot_run_row.is_active,
        'actor_user_id', p_actor_user_id::text,
        'created_or_reused_at_utc', v_now,
        'requested_pay_date_honoured', true
      );
    END IF;
  END IF;


  IF v_snapshot_run_id IS NULL THEN
    v_snapshot_info_json := public.pay_workbench_snapshot_ensure_run(
      p_pay_date => v_requested_pay_date,
      p_week_ending_cutoff => v_effective_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id
    );

    IF BTRIM(COALESCE(v_snapshot_info_json->>'snapshot_run_id', '')) !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'pay_workbench_snapshot_ensure_run did not return a valid snapshot_run_id';
    END IF;

    IF BTRIM(COALESCE(v_snapshot_info_json->>'pay_date', '')) <> ''
       AND (v_snapshot_info_json->>'pay_date')::date IS DISTINCT FROM v_requested_pay_date THEN
      RAISE EXCEPTION 'pay_workbench_snapshot_ensure_run returned pay_date %, but requested pay_date %',
        v_snapshot_info_json->>'pay_date',
        v_requested_pay_date;
    END IF;

    v_snapshot_run_id := (v_snapshot_info_json->>'snapshot_run_id')::uuid;
    v_effective_pay_date := v_requested_pay_date;
  END IF;

  IF v_effective_pay_date IS DISTINCT FROM v_requested_pay_date THEN
    RAISE EXCEPTION 'pay_workbench_session_open resolved pay_date %, but requested pay_date %',
      v_effective_pay_date,
      v_requested_pay_date;
  END IF;


  BEGIN
    IF BTRIM(COALESCE(p_session_signature, '')) <> '' THEN
      v_signature_source_json := p_session_signature::jsonb;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      v_signature_source_json := '{}'::jsonb;
  END;

  IF jsonb_typeof(COALESCE(v_signature_source_json, '{}'::jsonb)) <> 'object' THEN
    v_signature_source_json := '{}'::jsonb;
  END IF;

  SELECT COALESCE(
           jsonb_agg(to_jsonb(candidate_id_rows.candidate_id_value) ORDER BY candidate_id_rows.candidate_id_value),
           '[]'::jsonb
         )
  INTO v_signature_candidate_ids_jsonb
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(candidate_id_element.value), '') AS candidate_id_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_signature_source_json->'candidate_ids') = 'array' THEN COALESCE(v_signature_source_json->'candidate_ids', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS candidate_id_element(value)
    WHERE NULLIF(BTRIM(candidate_id_element.value), '') IS NOT NULL
  ) AS candidate_id_rows;

  v_signature_filters_json := '{}'::jsonb;

  FOR v_signature_filter_entry IN
    SELECT filter_entries.key AS key_name,
           filter_entries.value AS key_value
    FROM jsonb_each(v_filters_json) AS filter_entries(key, value)
  LOOP
    IF v_signature_filter_entry.key_name NOT IN (
      'pay_date',
      'payDate',
      'selectedPayDate',
      'week_ending_cutoff_date',
      'weekEndingCutoffDate',
      'week_ending_cutoff',
      'weekEndingCutoff',
      'week_ending_cutoff_raw',
      'weekEndingCutoffRaw',
      'candidate_filter_id',
      'candidateFilterId',
      'candidate_id',
      'candidateId',
      'client_filter_id',
      'clientFilterId',
      'client_id',
      'clientId',
      'selected_preview_row_ids',
      'selectedPreviewRowIds',
      'case_resolutions',
      'caseResolutions',
      'component_resolutions',
      'componentResolutions',
      'exclude_timesheet_ids',
      'excludeTimesheetIds',
      'case_resolution_states',
      'blocked_case_states',
      'safe_case_states',
      'reusable_component_resolutions',
      'stale_component_resolutions',
      'draftable_now',
      'blocked_now',
      'ready_to_pay_now',
      'blocked_for_pay_now',
      'hidden_indefinite_snoozes',
      'preview_request_seq',
      'preview_epoch',
      'tab_epoch',
      'modal_epoch',
      'dirty_reason',
      'pay_context_dirty',
      'modal_valid',
      'active_modal_epoch',
      'same_week_paye_override_reason',
      'sameWeekPayeOverrideReason',
      'same_week_paye_override_continue',
      'sameWeekPayeOverrideContinue',
      'same_week_paye_override_verified',
      'sameWeekPayeOverrideVerified',
      'same_week_paye_override_verified_by_user_id',
      'sameWeekPayeOverrideVerifiedByUserId',
      'same_week_paye_override_verified_at_utc',
      'sameWeekPayeOverrideVerifiedAtUtc',
      'session_signature',
      'sessionSignature',
      'session_id',
      'sessionId'
    ) THEN
      v_signature_filters_json := v_signature_filters_json || jsonb_build_object(v_signature_filter_entry.key_name, v_signature_filter_entry.key_value);
    END IF;
  END LOOP;

  v_candidate_filter_id_text := CASE
    WHEN v_filter_candidate_id IS NOT NULL THEN v_filter_candidate_id::text
    ELSE ''
  END;

  v_client_filter_id_text := CASE
    WHEN v_filter_client_id IS NOT NULL THEN v_filter_client_id::text
    ELSE ''
  END;

  v_signature_candidate_ids_jsonb := '[]'::jsonb;

  v_signature_source_json := jsonb_build_object(
    'candidate_filter_id', v_candidate_filter_id_text,
    'candidate_ids', v_signature_candidate_ids_jsonb,
    'client_filter_id', v_client_filter_id_text,
    'kind', v_current_workbench_signature_kind,
    'pay_date', v_effective_pay_date::text,
    'signature_version', v_current_workbench_signature_version
  );

  IF v_signature_filters_json <> '{}'::jsonb THEN
    v_signature_source_json := v_signature_source_json || jsonb_build_object('filters_json', v_signature_filters_json);
  END IF;

  v_session_signature := v_signature_source_json::text;

  IF v_filter_candidate_id IS NOT NULL THEN
    SELECT
      CASE
        WHEN EXISTS (
          SELECT 1
          FROM public.candidates AS c
          WHERE c.id = v_filter_candidate_id
        ) THEN ARRAY[v_filter_candidate_id]::uuid[]
        ELSE ARRAY[]::uuid[]
      END
    INTO v_scope_candidate_ids;
  ELSIF v_filter_client_id IS NOT NULL THEN
    v_scope_resolution_context_json := public.pay_preview_build_context(
      p_pay_date => v_effective_pay_date,
      p_week_ending_cutoff => v_effective_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => v_filter_client_id,
      p_preview_decisions_json => NULL::jsonb
    );

    SELECT COALESCE(array_agg(scope_rows.candidate_id ORDER BY scope_rows.candidate_id), ARRAY[]::uuid[])
    INTO v_scope_candidate_ids
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(scope_candidate_id.value), '')::uuid AS candidate_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_scope_resolution_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_scope_resolution_context_json->'scope_candidate_ids', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS scope_candidate_id(value)
      WHERE NULLIF(BTRIM(scope_candidate_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS scope_rows;
  ELSE
    v_context_json := public.pay_preview_build_context(
      p_pay_date => v_effective_pay_date,
      p_week_ending_cutoff => v_effective_week_ending_cutoff,
      p_actor_user_id => p_actor_user_id,
      p_candidate_id => NULL::uuid,
      p_client_id => NULL::uuid,
      p_preview_decisions_json => NULL::jsonb
    );

    SELECT COALESCE(array_agg(scope_rows.candidate_id ORDER BY scope_rows.candidate_id), ARRAY[]::uuid[])
    INTO v_scope_candidate_ids
    FROM (
      SELECT DISTINCT NULLIF(BTRIM(scope_candidate_id.value), '')::uuid AS candidate_id
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_context_json->'scope_candidate_ids', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS scope_candidate_id(value)
      WHERE NULLIF(BTRIM(scope_candidate_id.value), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS scope_rows;
  END IF;

  v_scope_candidate_ids_jsonb := to_jsonb(COALESCE(v_scope_candidate_ids, ARRAY[]::uuid[]));

  FOR v_open_session_row IN
    SELECT ws.*
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.status = 'OPEN'
      AND ws.discarded_at_utc IS NULL
    ORDER BY ws.updated_at_utc DESC NULLS LAST,
             ws.created_at_utc DESC NULLS LAST,
             ws.id DESC
    FOR UPDATE OF ws
  LOOP
    IF v_force_new_session THEN
      IF v_previous_session_id IS NULL
         AND (
           v_open_session_row.id = v_source_session_id
           OR v_open_session_row.id = ANY(COALESCE(v_obsolete_session_ids, ARRAY[]::uuid[]))
           OR (
             v_open_session_row.session_signature = v_session_signature
             AND v_open_session_row.week_ending_cutoff IS NOT DISTINCT FROM v_effective_week_ending_cutoff
             AND v_open_session_row.pay_date IS NOT DISTINCT FROM v_effective_pay_date
           )
         ) THEN
        v_previous_session_id := v_open_session_row.id;
      END IF;

      v_source_session_discard_json := public.pay_workbench_session_discard(
        p_session_id => v_open_session_row.id,
        p_actor_user_id => p_actor_user_id
      );

      IF v_open_session_row.id = v_source_session_id OR v_open_session_row.id = ANY(COALESCE(v_obsolete_session_ids, ARRAY[]::uuid[])) THEN
        v_source_session_discarded := true;
      END IF;
    ELSIF v_existing_session_row.id IS NULL
       AND v_open_session_row.session_signature = v_session_signature
       AND v_open_session_row.week_ending_cutoff IS NOT DISTINCT FROM v_effective_week_ending_cutoff
       AND v_open_session_row.pay_date IS NOT DISTINCT FROM v_effective_pay_date THEN
      v_existing_session_row := v_open_session_row;
    ELSE
      PERFORM public.pay_workbench_session_discard(
        p_session_id => v_open_session_row.id,
        p_actor_user_id => p_actor_user_id
      );
    END IF;
  END LOOP;

  IF v_existing_session_row.id IS NULL THEN
    INSERT INTO public.banking_pay_workbench_sessions (
      actor_user_id,
      pay_date,
      week_ending_cutoff,
      filters_json,
      scope_candidate_ids,
      session_signature,
      source_snapshot_run_id,
      status,
      version,
      server_selected_preview_row_ids,
      server_selected_preview_row_ids_provided,
      created_at_utc,
      updated_at_utc,
      discarded_at_utc
    )
    VALUES (
      p_actor_user_id,
      v_effective_pay_date,
      v_effective_week_ending_cutoff,
      v_filters_json,
      v_scope_candidate_ids,
      v_session_signature,
      v_snapshot_run_id,
      'OPEN',
      1,
      '[]'::jsonb,
      false,
      v_now,
      v_now,
      NULL
    )
    RETURNING public.banking_pay_workbench_sessions.id
    INTO v_session_id;

    v_action := 'WORKBENCH_SESSION_CREATED';
  ELSE
    UPDATE public.banking_pay_workbench_sessions AS ws
    SET actor_user_id = p_actor_user_id,
        pay_date = v_effective_pay_date,
        week_ending_cutoff = v_effective_week_ending_cutoff,
        filters_json = v_filters_json,
        scope_candidate_ids = v_scope_candidate_ids,
        source_snapshot_run_id = v_snapshot_run_id,
        server_selected_preview_row_ids = '[]'::jsonb,
        server_selected_preview_row_ids_provided = false,
        version = CASE
          WHEN ws.pay_date IS DISTINCT FROM v_effective_pay_date
            OR ws.week_ending_cutoff IS DISTINCT FROM v_effective_week_ending_cutoff
            OR ws.filters_json IS DISTINCT FROM v_filters_json
            OR ws.scope_candidate_ids IS DISTINCT FROM v_scope_candidate_ids
            OR ws.source_snapshot_run_id IS DISTINCT FROM v_snapshot_run_id
          THEN ws.version + 1
          ELSE ws.version
        END,
        updated_at_utc = v_now
    WHERE ws.id = v_existing_session_row.id;

    v_session_id := v_existing_session_row.id;
    v_action := 'WORKBENCH_SESSION_RESUMED';
    v_audit_before_json := jsonb_build_object(
      'id', v_existing_session_row.id::text,
      'actor_user_id', v_existing_session_row.actor_user_id::text,
      'pay_date', v_existing_session_row.pay_date::text,
      'week_ending_cutoff', v_existing_session_row.week_ending_cutoff::text,
      'session_signature', v_existing_session_row.session_signature,
      'source_snapshot_run_id', CASE WHEN v_existing_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_existing_session_row.source_snapshot_run_id::text END,
      'status', v_existing_session_row.status,
      'version', v_existing_session_row.version,
      'server_selected_preview_row_ids', COALESCE(v_existing_session_row.server_selected_preview_row_ids, '[]'::jsonb),
      'server_selected_preview_row_ids_provided', COALESCE(v_existing_session_row.server_selected_preview_row_ids_provided, false)
    );
  END IF;

  DELETE FROM public.banking_pay_workbench_session_candidate_state AS ws_candidate
  WHERE ws_candidate.session_id = v_session_id
    AND NOT (ws_candidate.candidate_id = ANY(COALESCE(v_scope_candidate_ids, ARRAY[]::uuid[])));

  SELECT ws.version,
         COALESCE(ws.server_selected_preview_row_ids, '[]'::jsonb),
         COALESCE(ws.server_selected_preview_row_ids_provided, false)
  INTO v_session_version,
       v_server_selected_preview_row_ids,
       v_server_selected_preview_row_ids_provided
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = v_session_id;

  FOREACH v_scope_candidate_id IN ARRAY v_scope_candidate_ids
  LOOP
    v_pending_job_id := NULL::uuid;
    v_existing_snapshot_job_id := NULL::uuid;
    v_existing_snapshot_job_source_change_seq := 0;
    v_candidate_is_dirty := v_scope_candidate_id = ANY(COALESCE(v_dirty_candidate_ids, ARRAY[]::uuid[]));
    v_candidate_refresh_reason := CASE
      WHEN v_candidate_is_dirty AND v_post_mutation_requires_refresh THEN v_mutation_refresh_reason
      ELSE 'SESSION_OPEN_WARMUP'
    END;

    SELECT COALESCE(acc.seq, 0)
    INTO v_scope_live_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || v_scope_candidate_id::text;

    SELECT snap.*
    INTO v_snapshot_candidate_row
    FROM public.banking_pay_snapshot_candidate_state AS snap
    WHERE snap.snapshot_run_id = v_snapshot_run_id
      AND snap.candidate_id = v_scope_candidate_id
    LIMIT 1;

    v_snapshot_projection_version := COALESCE(
      CASE
        WHEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
          THEN (v_snapshot_candidate_row.candidate_fragment_json->>'projection_version')::integer
        ELSE NULL::integer
      END,
      0
    );
    v_snapshot_hidden_recovery_template_projection_version := COALESCE(
      CASE
        WHEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
          THEN (v_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
        ELSE NULL::integer
      END,
      0
    );

    SELECT EXISTS (
             SELECT 1
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(v_snapshot_candidate_row.canonical_preview_lines_json) = 'array' THEN COALESCE(v_snapshot_candidate_row.canonical_preview_lines_json, '[]'::jsonb)
                 ELSE '[]'::jsonb
               END
             ) AS snap_line(value)
             WHERE jsonb_typeof(snap_line.value) = 'object'
               AND UPPER(COALESCE(snap_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
               AND UPPER(COALESCE(snap_line.value->>'pay_channel', '')) = 'PAYE'
               AND UPPER(COALESCE(snap_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
           )
    INTO v_snapshot_has_visible_paye_manual_debt_net_deduct;

    SELECT NOT EXISTS (
             SELECT 1
             FROM jsonb_array_elements(
               CASE
                 WHEN jsonb_typeof(v_snapshot_candidate_row.canonical_preview_lines_json) = 'array' THEN COALESCE(v_snapshot_candidate_row.canonical_preview_lines_json, '[]'::jsonb)
                 ELSE '[]'::jsonb
               END
             ) AS snap_line(value)
             WHERE jsonb_typeof(snap_line.value) = 'object'
               AND UPPER(COALESCE(snap_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
               AND UPPER(COALESCE(snap_line.value->>'pay_channel', '')) = 'PAYE'
               AND UPPER(COALESCE(snap_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
               AND NULLIF(BTRIM(COALESCE(snap_line.value->>'finance_case_id', '')), '') IS NOT NULL
               AND NOT EXISTS (
                 SELECT 1
                 FROM jsonb_array_elements(
                   CASE
                     WHEN jsonb_typeof(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
                     ELSE '[]'::jsonb
                   END
                 ) AS snap_tpl(value)
                 WHERE jsonb_typeof(snap_tpl.value) = 'object'
                   AND UPPER(COALESCE(snap_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                   AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
                   AND COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(snap_line.value->>'finance_case_id', '')), ''), '')
               )
           )
    INTO v_snapshot_has_matching_hidden_paye_manual_debt_template;

    IF v_candidate_is_dirty = false
       AND v_snapshot_candidate_row.id IS NOT NULL
       AND UPPER(COALESCE(v_snapshot_candidate_row.status, '')) = 'READY'
       AND COALESCE(v_snapshot_candidate_row.source_change_seq, 0) >= v_scope_live_change_seq
       AND v_snapshot_projection_version >= v_required_projection_version
       AND (
         v_requires_hidden_recovery_templates = false
         OR v_snapshot_hidden_recovery_template_projection_version >= v_required_hidden_recovery_template_projection_version
       )
       AND (
         v_snapshot_has_visible_paye_manual_debt_net_deduct = false
         OR v_snapshot_has_matching_hidden_paye_manual_debt_template = true
       ) THEN
      INSERT INTO public.banking_pay_workbench_session_candidate_state (
        session_id,
        candidate_id,
        status,
        effective_candidate_fragment_json,
        effective_summary_fragment_json,
        effective_paye_candidate_json,
        effective_non_paye_payee_json,
        effective_payees_json,
        effective_case_resolution_states_json,
        effective_canonical_preview_lines_json,
        source_change_seq,
        session_version,
        pending_job_id,
        created_at_utc,
        updated_at_utc,
        last_recomputed_at_utc,
        last_error_json
      )
      VALUES (
        v_session_id,
        v_scope_candidate_id,
        'READY',
        COALESCE(v_snapshot_candidate_row.candidate_fragment_json, '{}'::jsonb),
        COALESCE(v_snapshot_candidate_row.summary_fragment_json, '{}'::jsonb),
        v_snapshot_candidate_row.paye_candidate_json,
        v_snapshot_candidate_row.non_paye_payee_json,
        COALESCE(v_snapshot_candidate_row.payees_json, '[]'::jsonb),
        COALESCE(v_snapshot_candidate_row.case_resolution_states_json, '[]'::jsonb),
        COALESCE(v_snapshot_candidate_row.canonical_preview_lines_json, '[]'::jsonb),
        COALESCE(v_snapshot_candidate_row.source_change_seq, 0),
        v_session_version,
        NULL::uuid,
        v_now,
        v_now,
        v_now,
        NULL
      )
      ON CONFLICT (session_id, candidate_id)
      DO UPDATE
      SET status = 'READY',
          effective_candidate_fragment_json = EXCLUDED.effective_candidate_fragment_json,
          effective_summary_fragment_json = EXCLUDED.effective_summary_fragment_json,
          effective_paye_candidate_json = EXCLUDED.effective_paye_candidate_json,
          effective_non_paye_payee_json = EXCLUDED.effective_non_paye_payee_json,
          effective_payees_json = EXCLUDED.effective_payees_json,
          effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
          effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
          source_change_seq = EXCLUDED.source_change_seq,
          session_version = EXCLUDED.session_version,
          pending_job_id = NULL::uuid,
          updated_at_utc = v_now,
          last_recomputed_at_utc = v_now,
          last_error_json = NULL;
    ELSE
      v_enqueue_candidate_refresh_json := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_snapshot_run_id,
        p_candidate_id => v_scope_candidate_id,
        p_reason => v_candidate_refresh_reason,
        p_actor_user_id => p_actor_user_id,
        p_payload_json => jsonb_build_object(
          'session_id', v_session_id::text,
          'session_signature', v_session_signature,
          'pay_date', v_effective_pay_date::text,
          'week_ending_cutoff', v_effective_week_ending_cutoff::text,
          'projection_version', v_required_projection_version,
          'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
          'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
          'mutation_context', v_mutation_context,
          'created_pay_batch_ids', v_created_pay_batch_ids_jsonb,
          'dirty_candidate_ids', v_dirty_candidate_ids_jsonb,
          'input_refresh_job_ids', v_refresh_job_ids_jsonb,
          'post_mutation_candidate_dirty', v_candidate_is_dirty,
          'refresh_reason', CASE
            WHEN v_candidate_is_dirty AND v_post_mutation_requires_refresh THEN v_candidate_refresh_reason
            WHEN v_snapshot_candidate_row.id IS NULL THEN 'SNAPSHOT_CANDIDATE_MISSING'
            WHEN UPPER(COALESCE(v_snapshot_candidate_row.status, '')) <> 'READY' THEN 'SNAPSHOT_CANDIDATE_NOT_READY'
            WHEN COALESCE(v_snapshot_candidate_row.source_change_seq, 0) < v_scope_live_change_seq THEN 'SOURCE_CHANGE_STALE'
            WHEN v_snapshot_projection_version < v_required_projection_version THEN 'PROJECTION_VERSION_STALE'
            WHEN v_requires_hidden_recovery_templates = true AND v_snapshot_hidden_recovery_template_projection_version < v_required_hidden_recovery_template_projection_version THEN 'HIDDEN_TEMPLATE_PROJECTION_VERSION_STALE'
            WHEN v_snapshot_has_visible_paye_manual_debt_net_deduct = true AND v_snapshot_has_matching_hidden_paye_manual_debt_template = false THEN 'MISSING_HIDDEN_MANUAL_DEBT_TEMPLATE'
            ELSE 'SESSION_OPEN_WARMUP'
          END
        )
      );

      IF BTRIM(COALESCE(v_enqueue_candidate_refresh_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_pending_job_id := (v_enqueue_candidate_refresh_json->>'job_id')::uuid;
      END IF;

      INSERT INTO public.banking_pay_workbench_session_candidate_state (
        session_id,
        candidate_id,
        status,
        effective_candidate_fragment_json,
        effective_summary_fragment_json,
        effective_paye_candidate_json,
        effective_non_paye_payee_json,
        effective_payees_json,
        effective_case_resolution_states_json,
        effective_canonical_preview_lines_json,
        source_change_seq,
        session_version,
        pending_job_id,
        created_at_utc,
        updated_at_utc,
        last_recomputed_at_utc,
        last_error_json
      )
      VALUES (
        v_session_id,
        v_scope_candidate_id,
        'PENDING',
        '{}'::jsonb,
        '{}'::jsonb,
        NULL,
        NULL,
        '[]'::jsonb,
        '[]'::jsonb,
        '[]'::jsonb,
        GREATEST(v_scope_live_change_seq, COALESCE(v_snapshot_candidate_row.source_change_seq, 0)),
        v_session_version,
        v_pending_job_id,
        v_now,
        v_now,
        NULL,
        NULL
      )
      ON CONFLICT (session_id, candidate_id)
      DO UPDATE
      SET status = 'PENDING',
          effective_candidate_fragment_json = '{}'::jsonb,
          effective_summary_fragment_json = '{}'::jsonb,
          effective_paye_candidate_json = NULL,
          effective_non_paye_payee_json = NULL,
          effective_payees_json = '[]'::jsonb,
          effective_case_resolution_states_json = '[]'::jsonb,
          effective_canonical_preview_lines_json = '[]'::jsonb,
          source_change_seq = GREATEST(public.banking_pay_workbench_session_candidate_state.source_change_seq, GREATEST(v_scope_live_change_seq, COALESCE(v_snapshot_candidate_row.source_change_seq, 0))),
          session_version = GREATEST(public.banking_pay_workbench_session_candidate_state.session_version, v_session_version),
          pending_job_id = COALESCE(v_pending_job_id, public.banking_pay_workbench_session_candidate_state.pending_job_id),
          updated_at_utc = v_now,
          last_recomputed_at_utc = NULL,
          last_error_json = NULL;
    END IF;
  END LOOP;

  SELECT COALESCE(jsonb_agg(to_jsonb(pending_state.candidate_id::text) ORDER BY pending_state.candidate_id::text), '[]'::jsonb)
  INTO v_pending_candidate_ids_jsonb
  FROM (
    SELECT session_candidate_state.candidate_id AS candidate_id
    FROM public.banking_pay_workbench_session_candidate_state AS session_candidate_state
    WHERE session_candidate_state.session_id = v_session_id
      AND UPPER(COALESCE(session_candidate_state.status, '')) = 'PENDING'
      AND session_candidate_state.candidate_id IS NOT NULL
  ) AS pending_state;

  SELECT
    COALESCE(jsonb_agg(to_jsonb(pending_dirty_state.candidate_id::text) ORDER BY pending_dirty_state.candidate_id::text), '[]'::jsonb),
    COALESCE(count(*)::integer, 0)
  INTO v_pending_dirty_candidate_ids_jsonb,
       v_pending_dirty_candidate_count
  FROM (
    SELECT session_candidate_state.candidate_id AS candidate_id
    FROM public.banking_pay_workbench_session_candidate_state AS session_candidate_state
    WHERE session_candidate_state.session_id = v_session_id
      AND UPPER(COALESCE(session_candidate_state.status, '')) = 'PENDING'
      AND session_candidate_state.candidate_id = ANY(COALESCE(v_dirty_candidate_ids, ARRAY[]::uuid[]))
      AND session_candidate_state.candidate_id IS NOT NULL
  ) AS pending_dirty_state;

  v_audit_after_json := jsonb_build_object(
    'id', v_session_id::text,
    'actor_user_id', p_actor_user_id::text,
    'pay_date', v_effective_pay_date::text,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'filters_json', v_filters_json,
    'scope_candidate_ids', to_jsonb(COALESCE(v_scope_candidate_ids, ARRAY[]::uuid[])),
    'session_signature', v_session_signature,
    'source_snapshot_run_id', v_snapshot_run_id::text,
    'status', 'OPEN',
    'version', v_session_version,
    'mutation_context', v_mutation_context,
    'post_mutation_requires_refresh', v_post_mutation_requires_refresh,
    'post_mutation_refresh_reason', v_mutation_refresh_reason,
    'created_pay_batch_ids', v_created_pay_batch_ids_jsonb,
    'dirty_candidate_ids', v_dirty_candidate_ids_jsonb,
    'pending_candidate_ids', v_pending_candidate_ids_jsonb,
    'pending_dirty_candidate_ids', v_pending_dirty_candidate_ids_jsonb,
    'input_refresh_job_ids', v_refresh_job_ids_jsonb,
    'server_selected_preview_row_ids', v_server_selected_preview_row_ids,
    'server_selected_preview_row_ids_provided', v_server_selected_preview_row_ids_provided
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    v_session_id::text,
    v_action,
    v_audit_before_json,
    v_audit_after_json,
    'SESSION_OPEN',
    p_actor_user_id
  );


  v_open_progress_json := public.pay_workbench_session_get_progress(v_session_id);

  v_open_ready_flag := CASE
    WHEN lower(COALESCE(v_open_progress_json->>'ready_flag', '')) IN ('true', 'false') THEN (v_open_progress_json->>'ready_flag')::boolean
    ELSE false
  END;

  v_open_total_count := COALESCE(
    CASE WHEN COALESCE(v_open_progress_json->>'total_count', '') ~ '^[0-9]+$' THEN (v_open_progress_json->>'total_count')::integer ELSE NULL::integer END,
    COALESCE(array_length(v_scope_candidate_ids, 1), 0)
  );

  v_open_completed_count := COALESCE(
    CASE WHEN COALESCE(v_open_progress_json->>'completed_count', '') ~ '^[0-9]+$' THEN (v_open_progress_json->>'completed_count')::integer ELSE NULL::integer END,
    0
  );

  v_open_pending_count := COALESCE(
    CASE WHEN COALESCE(v_open_progress_json->>'pending_count', '') ~ '^[0-9]+$' THEN (v_open_progress_json->>'pending_count')::integer ELSE NULL::integer END,
    0
  );

  v_open_failed_count := COALESCE(
    CASE WHEN COALESCE(v_open_progress_json->>'failed_count', '') ~ '^[0-9]+$' THEN (v_open_progress_json->>'failed_count')::integer ELSE NULL::integer END,
    0
  );

  v_open_ready_empty := CASE
    WHEN lower(COALESCE(v_open_progress_json->>'ready_empty', '')) IN ('true', 'false') THEN (v_open_progress_json->>'ready_empty')::boolean
    ELSE (v_open_ready_flag = true AND COALESCE(v_open_total_count, 0) = 0)
  END;

  IF v_post_mutation_requires_refresh = true
     AND COALESCE(array_length(v_scope_candidate_ids, 1), 0) = 0 THEN
    v_open_ready_flag := true;
    v_open_ready_empty := true;
    v_open_total_count := 0;
    v_open_completed_count := 0;
    v_open_pending_count := 0;
    v_open_failed_count := 0;
    v_open_progress_json := COALESCE(v_open_progress_json, '{}'::jsonb) || jsonb_build_object(
      'ready', true,
      'ready_flag', true,
      'ready_empty', true,
      'total_count', 0,
      'total_candidates', 0,
      'completed_count', 0,
      'completed_candidates', 0,
      'ready_count', 0,
      'ready_candidates', 0,
      'pending_count', 0,
      'pending_candidates', 0,
      'failed_count', 0,
      'failed_candidates', 0,
      'phase', 'READY_EMPTY',
      'status_text', 'Payment preview is ready. No eligible payment candidates remain for this scope.'
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', v_session_id::text,
    'previous_session_id', CASE WHEN v_previous_session_id IS NULL THEN NULL ELSE v_previous_session_id::text END,
    'source_session_id', CASE WHEN v_source_session_id IS NULL THEN NULL ELSE v_source_session_id::text END,
    'source_session_discarded', v_source_session_discarded,
    'source_session_discard', COALESCE(v_source_session_discard_json, '{}'::jsonb),
    'force_new_session', v_force_new_session,
    'requires_new_session', false,
    'obsolete_session_ids', COALESCE(v_obsolete_session_ids_jsonb, '[]'::jsonb),
    'mutation_context', v_mutation_context,
    'post_mutation_requires_refresh', v_post_mutation_requires_refresh,
    'post_mutation_refresh_reason', v_mutation_refresh_reason,
    'created_pay_batch_ids', v_created_pay_batch_ids_jsonb,
    'dirty_candidate_ids', v_dirty_candidate_ids_jsonb,
    'input_refresh_job_ids', v_refresh_job_ids_jsonb,
    'snapshot_run_id', v_snapshot_run_id::text,
    'session_signature', v_session_signature,
    'pay_date', v_effective_pay_date::text,
    'scope_candidate_ids', to_jsonb(COALESCE(v_scope_candidate_ids, ARRAY[]::uuid[])),
    'scope_candidate_count', COALESCE(array_length(v_scope_candidate_ids, 1), 0),
    'ready', v_open_ready_flag,
    'ready_flag', v_open_ready_flag,
    'ready_empty', v_open_ready_empty,
    'total_count', v_open_total_count,
    'completed_count', v_open_completed_count,
    'pending_count', v_open_pending_count,
    'failed_count', v_open_failed_count,
    'pending_candidate_ids', v_pending_candidate_ids_jsonb,
    'pending_dirty_candidate_ids', v_pending_dirty_candidate_ids_jsonb,
    'pending_dirty_candidate_count', v_pending_dirty_candidate_count,
    'candidate_counts', jsonb_build_object(
      'total', v_open_total_count,
      'ready', COALESCE(CASE WHEN COALESCE(v_open_progress_json->>'ready_count', '') ~ '^[0-9]+$' THEN (v_open_progress_json->>'ready_count')::integer ELSE NULL::integer END, 0),
      'pending', v_open_pending_count,
      'failed', v_open_failed_count
    ),
    'job_counts', jsonb_build_object(
      'pending', COALESCE(jsonb_array_length(CASE WHEN jsonb_typeof(COALESCE(v_open_progress_json->'pending_job_ids', '[]'::jsonb)) = 'array' THEN COALESCE(v_open_progress_json->'pending_job_ids', '[]'::jsonb) ELSE '[]'::jsonb END), 0)
    ),
    'progress_summary', jsonb_build_object(
      'phase', COALESCE(v_open_progress_json->>'phase', CASE WHEN v_open_ready_flag THEN 'READY' ELSE 'REFRESHING_CANDIDATES' END),
      'status_text', COALESCE(v_open_progress_json->>'status_text', CASE WHEN v_open_ready_flag THEN 'Payment preview is ready.' ELSE 'Preparing payment preview.' END),
      'ready_flag', v_open_ready_flag,
      'ready_empty', v_open_ready_empty,
      'total_count', v_open_total_count,
      'completed_count', v_open_completed_count,
      'pending_count', v_open_pending_count,
      'failed_count', v_open_failed_count
    ),
    'progress', v_open_progress_json,
    'action', v_action,
    'session_version', v_session_version,
    'week_ending_cutoff', v_effective_week_ending_cutoff::text,
    'server_selected_preview_row_ids', v_server_selected_preview_row_ids,
    'server_selected_preview_row_ids_provided', v_server_selected_preview_row_ids_provided,
    'opened_at_utc', v_now
  );
END;
$function$;






DROP FUNCTION IF EXISTS public.pay_workbench_session_get_preview(uuid);


CREATE OR REPLACE FUNCTION public.pay_workbench_session_get_preview(
  p_session_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_context_json jsonb := '{}'::jsonb;
  v_filter_candidate_id uuid := NULL::uuid;
  v_filter_client_id uuid := NULL::uuid;
  v_paye_candidates_json jsonb := '[]'::jsonb;
  v_non_paye_payees_json jsonb := '[]'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_payees_json jsonb := '[]'::jsonb;
  v_itemisation_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_do_not_pay_items_json jsonb := '[]'::jsonb;
  v_snoozed_items_json jsonb := '[]'::jsonb;
  v_baseline_component_rows_json jsonb := '[]'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_pending_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_failed_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_progress_json jsonb := '{}'::jsonb;
  v_progress_ready_flag boolean := false;
  v_preview_page_size integer := 100;
  v_safe_full_preview_line_threshold integer := 2000;
  v_bootstrap_preview_line_count integer := 0;
  v_bootstrap_candidate_count integer := 0;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id;

  IF v_session_row.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'WORKBENCH_SESSION_NOT_FOUND',
      'code', 'WORKBENCH_SESSION_NOT_FOUND',
      'rebase_required', true,
      'requires_new_session', true,
      'session_id', p_session_id::text,
      'ready', false,
      'ready_flag', false,
      'progress_only', true,
      'phase', 'REBASE_REQUIRED',
      'status_text', 'Payment preview needs refreshing.',
      'pending_candidate_ids', '[]'::jsonb,
      'failed_candidate_ids', '[]'::jsonb
    );
  END IF;

  IF UPPER(COALESCE(v_session_row.status, '')) <> 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'OBSOLETE_SESSION',
      'code', 'OBSOLETE_SESSION',
      'rebase_required', true,
      'requires_new_session', true,
      'session_id', p_session_id::text,
      'status', v_session_row.status,
      'session_status', v_session_row.status,
      'discarded_at_utc', v_session_row.discarded_at_utc,
      'ready', false,
      'ready_flag', false,
      'progress_only', true,
      'phase', 'REBASE_REQUIRED',
      'status_text', 'Payment preview needs refreshing.',
      'pending_candidate_ids', '[]'::jsonb,
      'failed_candidate_ids', '[]'::jsonb
    );
  END IF;

  SELECT public.banking_pay_snapshot_runs.*
  INTO v_snapshot_run_row
  FROM public.banking_pay_snapshot_runs
  WHERE public.banking_pay_snapshot_runs.id = v_session_row.source_snapshot_run_id;

  IF v_snapshot_run_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found for session %', p_session_id, p_session_id;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  IF BTRIM(COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId')::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId')::uuid;
  END IF;

  v_progress_json := public.pay_workbench_session_get_progress(p_session_id);

  IF lower(COALESCE(v_progress_json->>'rebase_required', 'false')) = 'true'
     OR lower(COALESCE(v_progress_json->>'requires_new_session', 'false')) = 'true'
     OR (v_progress_json->>'error_code') IN ('OBSOLETE_SESSION', 'STALE_SESSION', 'REBASE_REQUIRED', 'WORKBENCH_SESSION_NOT_OPEN', 'WORKBENCH_SESSION_DISCARDED', 'WORKBENCH_SESSION_NOT_FOUND', 'WORKBENCH_SESSION_INVALID')
     OR (v_progress_json->>'code') IN ('OBSOLETE_SESSION', 'STALE_SESSION', 'REBASE_REQUIRED', 'WORKBENCH_SESSION_NOT_OPEN', 'WORKBENCH_SESSION_DISCARDED', 'WORKBENCH_SESSION_NOT_FOUND', 'WORKBENCH_SESSION_INVALID') THEN
    RETURN v_progress_json || jsonb_build_object(
      'progress_only', true,
      'ready', false,
      'ready_flag', false,
      'session_id', p_session_id::text,
      'pending_candidate_ids', COALESCE(v_progress_json->'pending_candidate_ids', '[]'::jsonb),
      'failed_candidate_ids', COALESCE(v_progress_json->'failed_candidate_ids', '[]'::jsonb)
    );
  END IF;

  v_progress_ready_flag := CASE
    WHEN lower(COALESCE(v_progress_json->>'ready_flag', '')) IN ('true', 'false') THEN (v_progress_json->>'ready_flag')::boolean
    ELSE false
  END;

  IF v_progress_ready_flag IS NOT TRUE THEN
    RETURN jsonb_build_object(
      'ok', true,
      'progress_only', true,
      'ready', false,
      'ready_flag', false,
      'session_id', p_session_id::text,
      'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'progress', v_progress_json,
      'phase', COALESCE(v_progress_json->>'phase', 'REFRESHING_CANDIDATES'),
      'status_text', COALESCE(v_progress_json->>'status_text', 'Preparing payment preview candidates.'),
      'total_count', COALESCE(CASE WHEN COALESCE(v_progress_json->>'total_count', '') ~ '^[0-9]+$' THEN (v_progress_json->>'total_count')::integer ELSE NULL::integer END, 0),
      'completed_count', COALESCE(CASE WHEN COALESCE(v_progress_json->>'completed_count', '') ~ '^[0-9]+$' THEN (v_progress_json->>'completed_count')::integer ELSE NULL::integer END, 0),
      'pending_count', COALESCE(CASE WHEN COALESCE(v_progress_json->>'pending_count', '') ~ '^[0-9]+$' THEN (v_progress_json->>'pending_count')::integer ELSE NULL::integer END, 0),
      'failed_count', COALESCE(CASE WHEN COALESCE(v_progress_json->>'failed_count', '') ~ '^[0-9]+$' THEN (v_progress_json->>'failed_count')::integer ELSE NULL::integer END, 0),
      'pending_candidate_ids', COALESCE(v_progress_json->'pending_candidate_ids', '[]'::jsonb),
      'failed_candidate_ids', COALESCE(v_progress_json->'failed_candidate_ids', '[]'::jsonb),
      'session', jsonb_build_object(
        'id', v_session_row.id::text,
        'session_id', v_session_row.id::text,
        'pay_date', v_session_row.pay_date::text,
        'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'session_version', v_session_row.version,
        'session_signature', v_session_row.session_signature,
        'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
        'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
      ),
      'workbench', jsonb_build_object(
        'session_id', v_session_row.id::text,
        'pay_date', v_session_row.pay_date::text,
        'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'session_version', v_session_row.version,
        'session_signature', v_session_row.session_signature,
        'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
        'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
      )
    );
  END IF;

  SELECT COALESCE(config_row.default_chunk_size, 100)
  INTO v_preview_page_size
  FROM public.banking_pay_operation_config AS config_row
  WHERE config_row.enabled = true
    AND config_row.chunk_type = 'PREVIEW_PAGE'
    AND config_row.operation_type IN ('PREVIEW_REFRESH', 'ALL')
  ORDER BY
    CASE WHEN config_row.operation_type = 'PREVIEW_REFRESH' THEN 0 ELSE 1 END,
    CASE WHEN config_row.phase = 'PAGE' THEN 0 WHEN config_row.phase = 'ALL' THEN 1 ELSE 2 END,
    config_row.updated_at_utc DESC
  LIMIT 1;

  v_preview_page_size := COALESCE(v_preview_page_size, 100);
  v_safe_full_preview_line_threshold := GREATEST(v_preview_page_size * 20, 1000);

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_session_row.pay_date,
    p_week_ending_cutoff => v_session_row.week_ending_cutoff,
    p_actor_user_id => NULL::uuid,
    p_candidate_id => v_filter_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => NULL::jsonb
  );

  DROP TABLE IF EXISTS pg_temp.selected_workbench_candidate_state;
  CREATE TEMPORARY TABLE selected_workbench_candidate_state ON COMMIT DROP AS
  SELECT
    scope_candidate.scope_candidate_id_value AS candidate_id,
    COALESCE(session_ready.effective_candidate_fragment_json, '{}'::jsonb) AS candidate_fragment_json,
    COALESCE(session_ready.effective_summary_fragment_json, '{}'::jsonb) AS summary_fragment_json,
    session_ready.status AS session_status,
    CASE WHEN jsonb_typeof(session_ready.effective_paye_candidate_json) = 'object' THEN session_ready.effective_paye_candidate_json ELSE NULL END AS paye_candidate_json,
    CASE WHEN jsonb_typeof(session_ready.effective_non_paye_payee_json) = 'object' THEN session_ready.effective_non_paye_payee_json ELSE NULL END AS non_paye_payee_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_payees_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_payees_json, '[]'::jsonb) ELSE '[]'::jsonb END AS payees_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_case_resolution_states_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_case_resolution_states_json, '[]'::jsonb) ELSE '[]'::jsonb END AS case_resolution_states_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb) ELSE '[]'::jsonb END AS canonical_preview_lines_json
  FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scope_candidate(scope_candidate_id_value)
  LEFT JOIN LATERAL (
    SELECT public.banking_pay_workbench_session_candidate_state.*
    FROM public.banking_pay_workbench_session_candidate_state
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
      AND public.banking_pay_workbench_session_candidate_state.candidate_id = scope_candidate.scope_candidate_id_value
      AND public.banking_pay_workbench_session_candidate_state.status = 'READY'
    ORDER BY public.banking_pay_workbench_session_candidate_state.updated_at_utc DESC, public.banking_pay_workbench_session_candidate_state.id DESC
    LIMIT 1
  ) AS session_ready ON true
  LEFT JOIN public.banking_pay_snapshot_candidate_state AS snapshot_ready
    ON snapshot_ready.snapshot_run_id = v_session_row.source_snapshot_run_id
   AND snapshot_ready.candidate_id = scope_candidate.scope_candidate_id_value
  WHERE session_ready.id IS NOT NULL
    AND UPPER(COALESCE(snapshot_ready.status, '')) = 'READY'
    AND COALESCE(
          CASE
            WHEN COALESCE(session_ready.effective_candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
              THEN (session_ready.effective_candidate_fragment_json->>'projection_version')::integer
            ELSE NULL::integer
          END,
          0
        ) >= v_required_projection_version
    AND COALESCE(
          CASE
            WHEN COALESCE(snapshot_ready.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
              THEN (snapshot_ready.candidate_fragment_json->>'projection_version')::integer
            ELSE NULL::integer
          END,
          0
        ) >= v_required_projection_version
    AND (
      v_requires_hidden_recovery_templates = false
      OR COALESCE(
           CASE
             WHEN COALESCE(session_ready.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
               THEN (session_ready.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
             ELSE NULL::integer
           END,
           0
         ) >= v_required_hidden_recovery_template_projection_version
    )
    AND (
      v_requires_hidden_recovery_templates = false
      OR COALESCE(
           CASE
             WHEN COALESCE(snapshot_ready.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
               THEN (snapshot_ready.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
             ELSE NULL::integer
           END,
           0
         ) >= v_required_hidden_recovery_template_projection_version
    )
    AND COALESCE(session_ready.last_recomputed_at_utc, '-infinity'::timestamptz) >= COALESCE(snapshot_ready.last_refreshed_at_utc, '-infinity'::timestamptz)
    AND (
      EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS preview_line(value)
        WHERE jsonb_typeof(preview_line.value) = 'object'
          AND UPPER(COALESCE(preview_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
          AND UPPER(COALESCE(preview_line.value->>'pay_channel', '')) = 'PAYE'
          AND UPPER(COALESCE(preview_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
      ) = false
      OR NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS preview_line_missing(value)
        WHERE jsonb_typeof(preview_line_missing.value) = 'object'
          AND UPPER(COALESCE(preview_line_missing.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
          AND UPPER(COALESCE(preview_line_missing.value->>'pay_channel', '')) = 'PAYE'
          AND UPPER(COALESCE(preview_line_missing.value->>'paye_treatment', '')) = 'NET_DEDUCT'
          AND NULLIF(BTRIM(COALESCE(preview_line_missing.value->>'finance_case_id', '')), '') IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(COALESCE(session_ready.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS hidden_tpl(value)
            WHERE jsonb_typeof(hidden_tpl.value) = 'object'
              AND UPPER(COALESCE(hidden_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
              AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
              AND COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(preview_line_missing.value->>'finance_case_id', '')), ''), '')
          )
      )
    );

  SELECT
    COALESCE(count(*), 0)::integer,
    COALESCE(sum(
      CASE
        WHEN jsonb_typeof(selected_workbench_candidate_state.canonical_preview_lines_json) = 'array'
          THEN jsonb_array_length(selected_workbench_candidate_state.canonical_preview_lines_json)
        ELSE 0
      END
    ), 0)::integer
  INTO v_bootstrap_candidate_count, v_bootstrap_preview_line_count
  FROM selected_workbench_candidate_state;

  IF v_bootstrap_preview_line_count > v_safe_full_preview_line_threshold THEN
    RETURN jsonb_build_object(
      'ok', true,
      'ready', true,
      'ready_flag', true,
      'progress_only', false,
      'bootstrap_only', true,
      'requires_paging', true,
      'preview_page_rpc', 'pay_workbench_session_get_preview_page',
      'session_id', p_session_id::text,
      'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'candidate_count', v_bootstrap_candidate_count,
      'canonical_preview_line_count', v_bootstrap_preview_line_count,
      'safe_full_preview_line_threshold', v_safe_full_preview_line_threshold,
      'page_size', v_preview_page_size,
      'page_count', CEIL(v_bootstrap_preview_line_count::numeric / GREATEST(v_preview_page_size, 1)::numeric)::integer,
      'progress', v_progress_json,
      'summary', jsonb_build_object(
        'candidate_count', v_bootstrap_candidate_count,
        'canonical_preview_line_count', v_bootstrap_preview_line_count,
        'requires_paging', true
      ),
      'session', jsonb_build_object(
        'id', v_session_row.id::text,
        'session_id', v_session_row.id::text,
        'pay_date', v_session_row.pay_date::text,
        'pay_week_start', v_context_json->>'pay_week_start',
        'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'session_version', v_session_row.version,
        'session_signature', v_session_row.session_signature,
        'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
        'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
      ),
      'workbench', jsonb_build_object(
        'session_id', v_session_row.id::text,
        'pay_date', v_session_row.pay_date::text,
        'pay_week_start', v_context_json->>'pay_week_start',
        'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
        'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
        'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
        'session_version', v_session_row.version,
        'session_signature', v_session_row.session_signature,
        'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
        'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
      ),
      'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
      'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false),
      'paye_candidates', '[]'::jsonb,
      'non_paye_payees', '[]'::jsonb,
      'canonical_preview_lines', '[]'::jsonb,
      'case_resolution_states', '[]'::jsonb,
      'payees', '[]'::jsonb,
      'itemisation', '[]'::jsonb,
      'blocked_items', '[]'::jsonb,
      'do_not_pay_items', '[]'::jsonb,
      'snoozed_items', '[]'::jsonb,
      'baseline_component_rows', '[]'::jsonb
    );
  END IF;

  SELECT COALESCE(
           jsonb_agg(selected_workbench_candidate_state.paye_candidate_json ORDER BY BTRIM(COALESCE(selected_workbench_candidate_state.paye_candidate_json->>'display_name', selected_workbench_candidate_state.paye_candidate_json->>'candidate_name', '')), BTRIM(COALESCE(selected_workbench_candidate_state.paye_candidate_json->>'tms_ref', '')), BTRIM(COALESCE(selected_workbench_candidate_state.paye_candidate_json->>'candidate_id', ''))),
           '[]'::jsonb
         )
  INTO v_paye_candidates_json
  FROM selected_workbench_candidate_state
  WHERE selected_workbench_candidate_state.paye_candidate_json IS NOT NULL;

  SELECT COALESCE(
           jsonb_agg(selected_workbench_candidate_state.non_paye_payee_json ORDER BY BTRIM(COALESCE(selected_workbench_candidate_state.non_paye_payee_json->>'display_name', selected_workbench_candidate_state.non_paye_payee_json->>'candidate_name', '')), BTRIM(COALESCE(selected_workbench_candidate_state.non_paye_payee_json->>'tms_ref', '')), BTRIM(COALESCE(selected_workbench_candidate_state.non_paye_payee_json->>'candidate_id', ''))),
           '[]'::jsonb
         )
  INTO v_non_paye_payees_json
  FROM selected_workbench_candidate_state
  WHERE selected_workbench_candidate_state.non_paye_payee_json IS NOT NULL;

  SELECT COALESCE(
           jsonb_agg(case_state_rows.case_state_json ORDER BY BTRIM(COALESCE(case_state_rows.case_state_json->>'candidate_id', '')), BTRIM(COALESCE(case_state_rows.case_state_json->>'case_key', '')), BTRIM(COALESCE(case_state_rows.case_state_json->>'finance_case_id', '')), BTRIM(COALESCE(case_state_rows.case_state_json->>'timesheet_id', ''))),
           '[]'::jsonb
         )
  INTO v_case_resolution_states_json
  FROM (
    SELECT case_state_element.value AS case_state_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(selected_workbench_candidate_state.case_resolution_states_json) AS case_state_element(value)
    WHERE jsonb_typeof(case_state_element.value) = 'object'
  ) AS case_state_rows;

  SELECT COALESCE(
           jsonb_agg(line_rows.line_json ORDER BY BTRIM(COALESCE(line_rows.line_json->>'candidate_id', '')), BTRIM(COALESCE(line_rows.line_json->>'display_name', '')), BTRIM(COALESCE(line_rows.line_json->>'line_type', '')), BTRIM(COALESCE(line_rows.line_json->>'preview_row_id', line_rows.line_json->>'line_id', line_rows.line_json->>'row_id', line_rows.line_json->>'id', ''))),
           '[]'::jsonb
         )
  INTO v_canonical_preview_lines_json
  FROM (
    SELECT line_element.value AS line_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(selected_workbench_candidate_state.canonical_preview_lines_json) AS line_element(value)
    WHERE jsonb_typeof(line_element.value) = 'object'
  ) AS line_rows;

  SELECT COALESCE(
           jsonb_agg(payee_ranked.payee_json ORDER BY payee_ranked.payee_entity_kind, payee_ranked.payee_entity_id, payee_ranked.bank_details_hash, payee_ranked.row_ord),
           '[]'::jsonb
         )
  INTO v_payees_json
  FROM (
    SELECT
      payee_rows.payee_json,
      payee_rows.row_ord,
      payee_rows.payee_entity_kind,
      payee_rows.payee_entity_id,
      payee_rows.bank_details_hash,
      ROW_NUMBER() OVER (
        PARTITION BY payee_rows.payee_entity_kind, payee_rows.payee_entity_id, payee_rows.bank_details_hash
        ORDER BY payee_rows.row_ord ASC
      ) AS row_num
    FROM (
      SELECT
        payee_element.value AS payee_json,
        payee_element.ordinality AS row_ord,
        UPPER(BTRIM(COALESCE(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', ''))) AS payee_entity_kind,
        BTRIM(COALESCE(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', '')) AS payee_entity_id,
        BTRIM(COALESCE(payee_element.value->>'bank_details_hash', '')) AS bank_details_hash
      FROM selected_workbench_candidate_state
      CROSS JOIN LATERAL jsonb_array_elements(selected_workbench_candidate_state.payees_json) WITH ORDINALITY AS payee_element(value, ordinality)
      WHERE jsonb_typeof(payee_element.value) = 'object'
    ) AS payee_rows
  ) AS payee_ranked
  WHERE payee_ranked.row_num = 1;

  SELECT COALESCE(
           jsonb_agg(item_rows.item_json ORDER BY BTRIM(COALESCE(item_rows.item_json->>'candidate_id', '')), BTRIM(COALESCE(item_rows.item_json->>'timesheet_id', '')), BTRIM(COALESCE(item_rows.item_json->>'finance_case_id', '')), BTRIM(COALESCE(item_rows.item_json->>'segment_id', item_rows.item_json->>'segment_stable_key', '')), BTRIM(COALESCE(item_rows.item_json->>'line_id', item_rows.item_json->>'preview_row_id', item_rows.item_json->>'row_id', item_rows.item_json->>'id', '')), BTRIM(COALESCE(item_rows.item_json->>'line_type', item_rows.item_json->>'item_type', item_rows.item_json->>'category', item_rows.item_json->>'component_kind', item_rows.item_json->>'component_type', ''))),
           '[]'::jsonb
         )
  INTO v_itemisation_json
  FROM (
    SELECT item_element.value AS item_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(selected_workbench_candidate_state.candidate_fragment_json->'itemisation') = 'array' THEN COALESCE(selected_workbench_candidate_state.candidate_fragment_json->'itemisation', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS item_element(value)
    WHERE jsonb_typeof(item_element.value) = 'object'
  ) AS item_rows;

  SELECT COALESCE(
           jsonb_agg(blocked_rows.blocked_json ORDER BY BTRIM(COALESCE(blocked_rows.blocked_json->>'candidate_id', '')), BTRIM(COALESCE(blocked_rows.blocked_json->>'timesheet_id', blocked_rows.blocked_json->>'finance_case_id', '')), BTRIM(COALESCE(blocked_rows.blocked_json->>'segment_id', blocked_rows.blocked_json->>'segment_stable_key', blocked_rows.blocked_json->>'line_id', blocked_rows.blocked_json->>'preview_row_id', blocked_rows.blocked_json->>'row_id', blocked_rows.blocked_json->>'id', '')), BTRIM(COALESCE(blocked_rows.blocked_json->>'line_type', blocked_rows.blocked_json->>'category', blocked_rows.blocked_json->>'component_kind', blocked_rows.blocked_json->>'component_type', ''))),
           '[]'::jsonb
         )
  INTO v_blocked_items_json
  FROM (
    SELECT blocked_element.value AS blocked_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(selected_workbench_candidate_state.candidate_fragment_json->'blocked_items') = 'array' THEN COALESCE(selected_workbench_candidate_state.candidate_fragment_json->'blocked_items', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS blocked_element(value)
    WHERE jsonb_typeof(blocked_element.value) = 'object'
  ) AS blocked_rows;

  SELECT COALESCE(
           jsonb_agg(do_not_pay_rows.do_not_pay_json ORDER BY BTRIM(COALESCE(do_not_pay_rows.do_not_pay_json->>'candidate_id', '')), BTRIM(COALESCE(do_not_pay_rows.do_not_pay_json->>'timesheet_id', do_not_pay_rows.do_not_pay_json->>'finance_case_id', '')), BTRIM(COALESCE(do_not_pay_rows.do_not_pay_json->>'segment_id', do_not_pay_rows.do_not_pay_json->>'segment_stable_key', do_not_pay_rows.do_not_pay_json->>'line_id', do_not_pay_rows.do_not_pay_json->>'preview_row_id', do_not_pay_rows.do_not_pay_json->>'row_id', do_not_pay_rows.do_not_pay_json->>'id', '')), BTRIM(COALESCE(do_not_pay_rows.do_not_pay_json->>'line_type', do_not_pay_rows.do_not_pay_json->>'category', do_not_pay_rows.do_not_pay_json->>'component_kind', do_not_pay_rows.do_not_pay_json->>'component_type', ''))),
           '[]'::jsonb
         )
  INTO v_do_not_pay_items_json
  FROM (
    SELECT do_not_pay_element.value AS do_not_pay_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(selected_workbench_candidate_state.candidate_fragment_json->'do_not_pay_items') = 'array' THEN COALESCE(selected_workbench_candidate_state.candidate_fragment_json->'do_not_pay_items', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS do_not_pay_element(value)
    WHERE jsonb_typeof(do_not_pay_element.value) = 'object'
  ) AS do_not_pay_rows;

  SELECT COALESCE(
           jsonb_agg(snoozed_rows.snoozed_json ORDER BY BTRIM(COALESCE(snoozed_rows.snoozed_json->>'candidate_id', '')), BTRIM(COALESCE(snoozed_rows.snoozed_json->>'timesheet_id', snoozed_rows.snoozed_json->>'finance_case_id', '')), BTRIM(COALESCE(snoozed_rows.snoozed_json->>'segment_id', snoozed_rows.snoozed_json->>'segment_stable_key', snoozed_rows.snoozed_json->>'line_id', snoozed_rows.snoozed_json->>'preview_row_id', snoozed_rows.snoozed_json->>'row_id', snoozed_rows.snoozed_json->>'id', '')), BTRIM(COALESCE(snoozed_rows.snoozed_json->>'line_type', snoozed_rows.snoozed_json->>'category', snoozed_rows.snoozed_json->>'component_kind', snoozed_rows.snoozed_json->>'component_type', ''))),
           '[]'::jsonb
         )
  INTO v_snoozed_items_json
  FROM (
    SELECT snoozed_element.value AS snoozed_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(selected_workbench_candidate_state.candidate_fragment_json->'snoozed_items') = 'array' THEN COALESCE(selected_workbench_candidate_state.candidate_fragment_json->'snoozed_items', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS snoozed_element(value)
    WHERE jsonb_typeof(snoozed_element.value) = 'object'
  ) AS snoozed_rows;

  SELECT COALESCE(
           jsonb_agg(component_rows.component_json ORDER BY BTRIM(COALESCE(component_rows.component_json->>'candidate_id', '')), BTRIM(COALESCE(component_rows.component_json->>'case_key', '')), BTRIM(COALESCE(component_rows.component_json->>'timesheet_id', '')), BTRIM(COALESCE(component_rows.component_json->>'finance_case_id', '')), BTRIM(COALESCE(component_rows.component_json->>'finance_component_id', '')), BTRIM(COALESCE(component_rows.component_json->>'component_scope', '')), BTRIM(COALESCE(component_rows.component_json->>'source_family_key', '')), BTRIM(COALESCE(component_rows.component_json->>'component_key_type', '')), BTRIM(COALESCE(component_rows.component_json->>'component_key_value', '')), BTRIM(COALESCE(component_rows.component_json->>'component_fingerprint', '')), BTRIM(COALESCE(component_rows.component_json->>'source_basis_fingerprint', ''))),
           '[]'::jsonb
         )
  INTO v_baseline_component_rows_json
  FROM (
    SELECT component_element.value AS component_json
    FROM selected_workbench_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE WHEN jsonb_typeof(selected_workbench_candidate_state.candidate_fragment_json->'baseline_component_rows') = 'array' THEN COALESCE(selected_workbench_candidate_state.candidate_fragment_json->'baseline_component_rows', '[]'::jsonb) ELSE '[]'::jsonb END
    ) AS component_element(value)
    WHERE jsonb_typeof(component_element.value) = 'object'
  ) AS component_rows;

  WITH summary_totals AS (
    SELECT
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'candidate_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'candidate_count')::integer ELSE 0 END), 0) AS candidate_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'paye_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'paye_candidates_count')::integer ELSE 0 END), 0) AS paye_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'non_paye_payees_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'non_paye_payees_count')::integer ELSE 0 END), 0) AS non_paye_payees_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'ready_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'ready_candidates_count')::integer ELSE 0 END), 0) AS ready_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_candidates_count')::integer ELSE 0 END), 0) AS blocked_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'case_resolution_state_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'case_resolution_state_count')::integer ELSE 0 END), 0) AS case_resolution_state_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_case_state_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_case_state_count')::integer ELSE 0 END), 0) AS blocked_case_state_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'canonical_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'canonical_preview_line_count')::integer ELSE 0 END), 0) AS canonical_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'ready_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'ready_preview_line_count')::integer ELSE 0 END), 0) AS ready_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_preview_line_count')::integer ELSE 0 END), 0) AS blocked_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'do_not_pay_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'do_not_pay_line_count')::integer ELSE 0 END), 0) AS do_not_pay_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'snoozed_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'snoozed_line_count')::integer ELSE 0 END), 0) AS snoozed_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'payees_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'payees_count')::integer ELSE 0 END), 0) AS payees_count,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_ex_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_inc_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_inc_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_ex_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_inc_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_inc_vat
    FROM selected_workbench_candidate_state
  ),
  readiness_totals AS (
    SELECT
      COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE WHEN jsonb_typeof(payee_rows.payee_json->'blockers') = 'array' THEN COALESCE(payee_rows.payee_json->'blockers', '[]'::jsonb) ELSE '[]'::jsonb END
          ) AS blocker_element(value)
          WHERE UPPER(BTRIM(blocker_element.value)) = 'BLOCKED_NAME_CHECK'
        )
      ) AS payees_need_name_check,
      COUNT(*) FILTER (
        WHERE EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE WHEN jsonb_typeof(payee_rows.payee_json->'blockers') = 'array' THEN COALESCE(payee_rows.payee_json->'blockers', '[]'::jsonb) ELSE '[]'::jsonb END
          ) AS blocker_element(value)
          WHERE UPPER(BTRIM(blocker_element.value)) = 'BLOCKED_NO_PAYEE_MAP'
        )
      ) AS payees_need_payee_map,
      COUNT(*) FILTER (
        WHERE BTRIM(COALESCE(payee_rows.payee_json->>'bank_details_hash', '')) = ''
           OR EXISTS (
                SELECT 1
                FROM jsonb_array_elements_text(
                  CASE WHEN jsonb_typeof(payee_rows.payee_json->'blockers') = 'array' THEN COALESCE(payee_rows.payee_json->'blockers', '[]'::jsonb) ELSE '[]'::jsonb END
                ) AS blocker_element(value)
                WHERE UPPER(BTRIM(blocker_element.value)) = 'BLOCKED_BANK_DETAILS'
              )
      ) AS payees_missing_bank_details
    FROM (
      SELECT
        payee_ranked.payee_json
      FROM (
        SELECT
          payee_rows.payee_json,
          payee_rows.row_ord,
          payee_rows.payee_entity_kind,
          payee_rows.payee_entity_id,
          payee_rows.bank_details_hash,
          ROW_NUMBER() OVER (
            PARTITION BY payee_rows.payee_entity_kind, payee_rows.payee_entity_id, payee_rows.bank_details_hash
            ORDER BY payee_rows.row_ord ASC
          ) AS row_num
        FROM (
          SELECT
            payee_element.value AS payee_json,
            payee_element.ordinality AS row_ord,
            UPPER(BTRIM(COALESCE(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', ''))) AS payee_entity_kind,
            BTRIM(COALESCE(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', '')) AS payee_entity_id,
            BTRIM(COALESCE(payee_element.value->>'bank_details_hash', '')) AS bank_details_hash
          FROM selected_workbench_candidate_state
          CROSS JOIN LATERAL jsonb_array_elements(selected_workbench_candidate_state.payees_json) WITH ORDINALITY AS payee_element(value, ordinality)
          WHERE jsonb_typeof(payee_element.value) = 'object'
        ) AS payee_rows
      ) AS payee_ranked
      WHERE payee_ranked.row_num = 1
    ) AS payee_rows
  ),
  paye_breakdown_totals AS (
    SELECT
      ROUND(COALESCE(SUM(
        CASE
          WHEN UPPER(BTRIM(COALESCE(line_rows.line_json->>'pay_channel', ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(line_rows.line_json->>'paye_treatment', ''))) = 'GROSS_ADD'
            AND COALESCE(LOWER(BTRIM(COALESCE(line_rows.line_json->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND COALESCE(line_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((line_rows.line_json->>'amount_ex_vat')::numeric, 0::numeric)
          ELSE 0::numeric
        END
      ), 0::numeric), 2) AS gross_side_additions_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN UPPER(BTRIM(COALESCE(line_rows.line_json->>'pay_channel', ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(line_rows.line_json->>'paye_treatment', ''))) = 'GROSS_DEDUCT'
            AND COALESCE(LOWER(BTRIM(COALESCE(line_rows.line_json->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND COALESCE(line_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN ABS((line_rows.line_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 0::numeric), 2) AS gross_side_deductions_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN UPPER(BTRIM(COALESCE(line_rows.line_json->>'pay_channel', ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(line_rows.line_json->>'paye_treatment', ''))) = 'NET_ADD'
            AND COALESCE(LOWER(BTRIM(COALESCE(line_rows.line_json->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND COALESCE(line_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN GREATEST((line_rows.line_json->>'amount_ex_vat')::numeric, 0::numeric)
          ELSE 0::numeric
        END
      ), 0::numeric), 2) AS net_side_additions_ex_vat,
      ROUND(COALESCE(SUM(
        CASE
          WHEN UPPER(BTRIM(COALESCE(line_rows.line_json->>'pay_channel', ''))) = 'PAYE'
            AND UPPER(BTRIM(COALESCE(line_rows.line_json->>'paye_treatment', ''))) = 'NET_DEDUCT'
            AND COALESCE(LOWER(BTRIM(COALESCE(line_rows.line_json->>'is_excluded_from_allocation', 'false'))), 'false') NOT IN ('true', 't', '1', 'yes', 'y', 'on')
            AND COALESCE(line_rows.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN ABS((line_rows.line_json->>'amount_ex_vat')::numeric)
          ELSE 0::numeric
        END
      ), 0::numeric), 2) AS net_side_deductions_ex_vat
    FROM (
      SELECT line_element.value AS line_json
      FROM selected_workbench_candidate_state
      CROSS JOIN LATERAL jsonb_array_elements(selected_workbench_candidate_state.canonical_preview_lines_json) AS line_element(value)
      WHERE jsonb_typeof(line_element.value) = 'object'
    ) AS line_rows
  )
  SELECT jsonb_build_object(
    'readiness', jsonb_build_object(
      'payees_total', COALESCE(summary_totals.payees_count, 0),
      'payees_need_name_check', COALESCE(readiness_totals.payees_need_name_check, 0),
      'payees_need_payee_map', COALESCE(readiness_totals.payees_need_payee_map, 0),
      'payees_missing_bank_details', COALESCE(readiness_totals.payees_missing_bank_details, 0)
    ),
    'candidates', jsonb_build_object(
      'ready_count', COALESCE(summary_totals.ready_candidates_count, 0),
      'review_required_count', COALESCE(summary_totals.blocked_candidates_count, 0),
      'total_candidates', COALESCE(summary_totals.candidate_count, 0)
    ),
    'candidate_count', COALESCE(summary_totals.candidate_count, 0),
    'paye_candidates_count', COALESCE(summary_totals.paye_candidates_count, 0),
    'non_paye_payees_count', COALESCE(summary_totals.non_paye_payees_count, 0),
    'ready_candidates_count', COALESCE(summary_totals.ready_candidates_count, 0),
    'blocked_candidates_count', COALESCE(summary_totals.blocked_candidates_count, 0),
    'case_resolution_state_count', COALESCE(summary_totals.case_resolution_state_count, 0),
    'blocked_case_state_count', COALESCE(summary_totals.blocked_case_state_count, 0),
    'canonical_preview_line_count', COALESCE(summary_totals.canonical_preview_line_count, 0),
    'ready_preview_line_count', COALESCE(summary_totals.ready_preview_line_count, 0),
    'blocked_preview_line_count', COALESCE(summary_totals.blocked_preview_line_count, 0),
    'do_not_pay_line_count', COALESCE(summary_totals.do_not_pay_line_count, 0),
    'snoozed_line_count', COALESCE(summary_totals.snoozed_line_count, 0),
    'payees_count', COALESCE(summary_totals.payees_count, 0),
    'total_amount_ex_vat', COALESCE(summary_totals.total_amount_ex_vat, 0::numeric),
    'total_amount_vat', COALESCE(summary_totals.total_amount_vat, 0::numeric),
    'total_amount_inc_vat', COALESCE(summary_totals.total_amount_inc_vat, 0::numeric),
    'draftable_amount_ex_vat', COALESCE(summary_totals.draftable_amount_ex_vat, 0::numeric),
    'draftable_amount_vat', COALESCE(summary_totals.draftable_amount_vat, 0::numeric),
    'draftable_amount_inc_vat', COALESCE(summary_totals.draftable_amount_inc_vat, 0::numeric),
    'paye_breakdown', jsonb_build_object(
      'gross_side_additions_ex_vat', COALESCE(paye_breakdown_totals.gross_side_additions_ex_vat, 0::numeric),
      'gross_side_deductions_ex_vat', COALESCE(paye_breakdown_totals.gross_side_deductions_ex_vat, 0::numeric),
      'net_side_additions_ex_vat', COALESCE(paye_breakdown_totals.net_side_additions_ex_vat, 0::numeric),
      'net_side_deductions_ex_vat', COALESCE(paye_breakdown_totals.net_side_deductions_ex_vat, 0::numeric)
    )
  )
  INTO v_summary_json
  FROM summary_totals
  CROSS JOIN readiness_totals
  CROSS JOIN paye_breakdown_totals;

  WITH scoped_candidates AS (
    SELECT scope_candidate.scope_candidate_id_value AS candidate_id
    FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scope_candidate(scope_candidate_id_value)
  ),
  latest_session_candidate_state AS (
    SELECT
      scoped_candidates.candidate_id,
      CASE
        WHEN latest_state.id IS NULL THEN 'PENDING'
        WHEN UPPER(COALESCE(latest_state.status, '')) = 'FAILED' THEN 'FAILED'
        WHEN UPPER(COALESCE(latest_state.status, '')) = 'READY'
             AND UPPER(COALESCE(snapshot_state.status, '')) = 'READY'
             AND COALESCE(latest_state.session_version, 0) >= COALESCE(v_session_row.version, 0)
             AND COALESCE(latest_state.source_change_seq, 0) >= COALESCE(snapshot_state.source_change_seq, 0)
             AND COALESCE(
                   CASE
                     WHEN COALESCE(latest_state.effective_candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
                       THEN (latest_state.effective_candidate_fragment_json->>'projection_version')::integer
                     ELSE NULL::integer
                   END,
                   0
                 ) >= v_required_projection_version
             AND COALESCE(
                   CASE
                     WHEN COALESCE(snapshot_state.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
                       THEN (snapshot_state.candidate_fragment_json->>'projection_version')::integer
                     ELSE NULL::integer
                   END,
                   0
                 ) >= v_required_projection_version
             AND (
               v_requires_hidden_recovery_templates = false
               OR COALESCE(
                    CASE
                      WHEN COALESCE(latest_state.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
                        THEN (latest_state.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
                      ELSE NULL::integer
                    END,
                    0
                  ) >= v_required_hidden_recovery_template_projection_version
             )
             AND (
               v_requires_hidden_recovery_templates = false
               OR COALESCE(
                    CASE
                      WHEN COALESCE(snapshot_state.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
                        THEN (snapshot_state.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
                      ELSE NULL::integer
                    END,
                    0
                  ) >= v_required_hidden_recovery_template_projection_version
             )
             AND COALESCE(latest_state.last_recomputed_at_utc, '-infinity'::timestamptz) >= COALESCE(snapshot_state.last_refreshed_at_utc, '-infinity'::timestamptz)
             AND (
               EXISTS (
                 SELECT 1
                 FROM jsonb_array_elements(
                   CASE
                     WHEN jsonb_typeof(COALESCE(latest_state.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(latest_state.effective_canonical_preview_lines_json, '[]'::jsonb)
                     ELSE '[]'::jsonb
                   END
                 ) AS preview_line(value)
                 WHERE jsonb_typeof(preview_line.value) = 'object'
                   AND UPPER(COALESCE(preview_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
                   AND UPPER(COALESCE(preview_line.value->>'pay_channel', '')) = 'PAYE'
                   AND UPPER(COALESCE(preview_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
               ) = false
               OR NOT EXISTS (
                 SELECT 1
                 FROM jsonb_array_elements(
                   CASE
                     WHEN jsonb_typeof(COALESCE(latest_state.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(latest_state.effective_canonical_preview_lines_json, '[]'::jsonb)
                     ELSE '[]'::jsonb
                   END
                 ) AS preview_line_missing(value)
                 WHERE jsonb_typeof(preview_line_missing.value) = 'object'
                   AND UPPER(COALESCE(preview_line_missing.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
                   AND UPPER(COALESCE(preview_line_missing.value->>'pay_channel', '')) = 'PAYE'
                   AND UPPER(COALESCE(preview_line_missing.value->>'paye_treatment', '')) = 'NET_DEDUCT'
                   AND NULLIF(BTRIM(COALESCE(preview_line_missing.value->>'finance_case_id', '')), '') IS NOT NULL
                   AND NOT EXISTS (
                     SELECT 1
                     FROM jsonb_array_elements(
                       CASE
                         WHEN jsonb_typeof(COALESCE(latest_state.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)) = 'array' THEN COALESCE(latest_state.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
                         ELSE '[]'::jsonb
                       END
                     ) AS hidden_tpl(value)
                     WHERE jsonb_typeof(hidden_tpl.value) = 'object'
                       AND UPPER(COALESCE(hidden_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                       AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
                       AND COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(preview_line_missing.value->>'finance_case_id', '')), ''), '')
                   )
               )
             )
          THEN 'READY'
        ELSE 'PENDING'
      END AS effective_status
    FROM scoped_candidates
    LEFT JOIN LATERAL (
      SELECT public.banking_pay_workbench_session_candidate_state.*
      FROM public.banking_pay_workbench_session_candidate_state
      WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
        AND public.banking_pay_workbench_session_candidate_state.candidate_id = scoped_candidates.candidate_id
      ORDER BY public.banking_pay_workbench_session_candidate_state.updated_at_utc DESC, public.banking_pay_workbench_session_candidate_state.id DESC
      LIMIT 1
    ) AS latest_state ON true
    LEFT JOIN public.banking_pay_snapshot_candidate_state AS snapshot_state
      ON snapshot_state.snapshot_run_id = v_session_row.source_snapshot_run_id
     AND snapshot_state.candidate_id = scoped_candidates.candidate_id
  )
  SELECT
    COALESCE(
      jsonb_agg(latest_session_candidate_state.candidate_id::text ORDER BY latest_session_candidate_state.candidate_id)
        FILTER (WHERE latest_session_candidate_state.effective_status = 'PENDING'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(latest_session_candidate_state.candidate_id::text ORDER BY latest_session_candidate_state.candidate_id)
        FILTER (WHERE latest_session_candidate_state.effective_status = 'FAILED'),
      '[]'::jsonb
    )
  INTO
    v_pending_candidate_ids_jsonb,
    v_failed_candidate_ids_jsonb
  FROM latest_session_candidate_state;

  RETURN jsonb_build_object(
    'ok', true,
    'ready', true,
    'ready_flag', true,
    'progress_only', false,
    'bootstrap_only', false,
    'requires_paging', false,
    'progress', v_progress_json,
    'pay_date', v_context_json->'pay_date',
    'pay_week_start', v_context_json->'pay_week_start',
    'week_ending_cutoff_date', v_context_json->'week_ending_cutoff_date',
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'eligibility', COALESCE(v_context_json->'eligibility', '{}'::jsonb),
    'filters', COALESCE(v_context_json->'filters', '{}'::jsonb),
    'finance', COALESCE(v_context_json->'finance', '{}'::jsonb),
    'settings', COALESCE(v_context_json->'settings', '{}'::jsonb),
    'summary', v_summary_json,
    'paye_candidates', v_paye_candidates_json,
    'non_paye_payees', v_non_paye_payees_json,
    'case_resolution_states', v_case_resolution_states_json,
    'canonical_preview_lines', v_canonical_preview_lines_json,
    'payees', v_payees_json,
    'itemisation', v_itemisation_json,
    'blocked_items', v_blocked_items_json,
    'do_not_pay_items', v_do_not_pay_items_json,
    'snoozed_items', v_snoozed_items_json,
    'baseline_component_rows', v_baseline_component_rows_json,
    'paye_guardrails', COALESCE(v_snapshot_run_row.paye_guardrails_json, '{}'::jsonb),
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_version', v_session_row.version,
    'session_signature', v_session_row.session_signature,
    'session', jsonb_build_object(
      'id', v_session_row.id::text,
      'session_id', v_session_row.id::text,
      'pay_date', v_session_row.pay_date::text,
      'pay_week_start', v_context_json->>'pay_week_start',
      'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
      'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
      'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
      'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
    ),
    'workbench', jsonb_build_object(
      'session_id', v_session_row.id::text,
      'pay_date', v_session_row.pay_date::text,
      'pay_week_start', v_context_json->>'pay_week_start',
      'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
      'week_ending_cutoff_date', v_session_row.week_ending_cutoff::text,
      'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'session_version', v_session_row.version,
      'session_signature', v_session_row.session_signature,
      'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
      'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
    ),
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false),
    'pending_candidate_ids', v_pending_candidate_ids_jsonb,
    'failed_candidate_ids', v_failed_candidate_ids_jsonb
  );
END;
$function$;








CREATE OR REPLACE FUNCTION public.pay_workbench_session_get_candidate_preview(
  p_session_id uuid,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_candidate_fragment_json jsonb := NULL;
  v_summary_fragment_json jsonb := '{}'::jsonb;
  v_paye_candidate_json jsonb := NULL;
  v_non_paye_payee_json jsonb := NULL;
  v_payees_json jsonb := '[]'::jsonb;
  v_case_resolution_states_json jsonb := '[]'::jsonb;
  v_canonical_preview_lines_json jsonb := '[]'::jsonb;
  v_itemisation_json jsonb := '[]'::jsonb;
  v_blocked_items_json jsonb := '[]'::jsonb;
  v_do_not_pay_items_json jsonb := '[]'::jsonb;
  v_snoozed_items_json jsonb := '[]'::jsonb;
  v_baseline_component_rows_json jsonb := '[]'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_pending_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_failed_candidate_ids_jsonb jsonb := '[]'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[p_candidate_id]::uuid[]) THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
  END IF;

  SELECT public.banking_pay_snapshot_runs.*
  INTO v_snapshot_run_row
  FROM public.banking_pay_snapshot_runs
  WHERE public.banking_pay_snapshot_runs.id = v_session_row.source_snapshot_run_id;

  IF v_snapshot_run_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found for session %', v_session_row.source_snapshot_run_id, p_session_id;
  END IF;

  DROP TABLE IF EXISTS pg_temp.selected_workbench_candidate_state;
  CREATE TEMPORARY TABLE selected_workbench_candidate_state ON COMMIT DROP AS
  SELECT
    scope_candidate.scope_candidate_id_value AS candidate_id,
    COALESCE(session_ready.effective_candidate_fragment_json, '{}'::jsonb) AS candidate_fragment_json,
    COALESCE(session_ready.effective_summary_fragment_json, '{}'::jsonb) AS summary_fragment_json,
    CASE WHEN jsonb_typeof(session_ready.effective_paye_candidate_json) = 'object' THEN session_ready.effective_paye_candidate_json ELSE NULL END AS paye_candidate_json,
    CASE WHEN jsonb_typeof(session_ready.effective_non_paye_payee_json) = 'object' THEN session_ready.effective_non_paye_payee_json ELSE NULL END AS non_paye_payee_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_payees_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_payees_json, '[]'::jsonb) ELSE '[]'::jsonb END AS payees_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_case_resolution_states_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_case_resolution_states_json, '[]'::jsonb) ELSE '[]'::jsonb END AS case_resolution_states_json,
    CASE WHEN jsonb_typeof(COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_ready.effective_canonical_preview_lines_json, '[]'::jsonb) ELSE '[]'::jsonb END AS canonical_preview_lines_json
  FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scope_candidate(scope_candidate_id_value)
  LEFT JOIN LATERAL (
    SELECT public.banking_pay_workbench_session_candidate_state.*
    FROM public.banking_pay_workbench_session_candidate_state
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
      AND public.banking_pay_workbench_session_candidate_state.candidate_id = scope_candidate.scope_candidate_id_value
      AND public.banking_pay_workbench_session_candidate_state.status = 'READY'
    ORDER BY public.banking_pay_workbench_session_candidate_state.updated_at_utc DESC, public.banking_pay_workbench_session_candidate_state.id DESC
    LIMIT 1
  ) AS session_ready ON true
  WHERE session_ready.id IS NOT NULL;

  SELECT
    selected_workbench_candidate_state.candidate_fragment_json,
    selected_workbench_candidate_state.summary_fragment_json,
    selected_workbench_candidate_state.paye_candidate_json,
    selected_workbench_candidate_state.non_paye_payee_json,
    selected_workbench_candidate_state.payees_json,
    selected_workbench_candidate_state.case_resolution_states_json,
    selected_workbench_candidate_state.canonical_preview_lines_json
  INTO
    v_candidate_fragment_json,
    v_summary_fragment_json,
    v_paye_candidate_json,
    v_non_paye_payee_json,
    v_payees_json,
    v_case_resolution_states_json,
    v_canonical_preview_lines_json
  FROM selected_workbench_candidate_state
  WHERE selected_workbench_candidate_state.candidate_id = p_candidate_id;

  IF v_candidate_fragment_json IS NULL THEN
    v_candidate_fragment_json := '{}'::jsonb;
    v_summary_fragment_json := '{}'::jsonb;
    v_payees_json := '[]'::jsonb;
    v_case_resolution_states_json := '[]'::jsonb;
    v_canonical_preview_lines_json := '[]'::jsonb;
  END IF;

  v_itemisation_json := CASE WHEN jsonb_typeof(v_candidate_fragment_json->'itemisation') = 'array' THEN COALESCE(v_candidate_fragment_json->'itemisation', '[]'::jsonb) ELSE '[]'::jsonb END;
  v_blocked_items_json := CASE WHEN jsonb_typeof(v_candidate_fragment_json->'blocked_items') = 'array' THEN COALESCE(v_candidate_fragment_json->'blocked_items', '[]'::jsonb) ELSE '[]'::jsonb END;
  v_do_not_pay_items_json := CASE WHEN jsonb_typeof(v_candidate_fragment_json->'do_not_pay_items') = 'array' THEN COALESCE(v_candidate_fragment_json->'do_not_pay_items', '[]'::jsonb) ELSE '[]'::jsonb END;
  v_snoozed_items_json := CASE WHEN jsonb_typeof(v_candidate_fragment_json->'snoozed_items') = 'array' THEN COALESCE(v_candidate_fragment_json->'snoozed_items', '[]'::jsonb) ELSE '[]'::jsonb END;
  v_baseline_component_rows_json := CASE WHEN jsonb_typeof(v_candidate_fragment_json->'baseline_component_rows') = 'array' THEN COALESCE(v_candidate_fragment_json->'baseline_component_rows', '[]'::jsonb) ELSE '[]'::jsonb END;

  v_candidate_rollup_json := jsonb_build_object(
    'candidate_id', p_candidate_id::text,
    'summary_fragment', COALESCE(v_summary_fragment_json, '{}'::jsonb),
    'case_resolution_states', COALESCE(v_case_resolution_states_json, '[]'::jsonb),
    'canonical_preview_lines', COALESCE(v_canonical_preview_lines_json, '[]'::jsonb),
    'payees', COALESCE(v_payees_json, '[]'::jsonb),
    'itemisation', COALESCE(v_itemisation_json, '[]'::jsonb),
    'blocked_items', COALESCE(v_blocked_items_json, '[]'::jsonb),
    'do_not_pay_items', COALESCE(v_do_not_pay_items_json, '[]'::jsonb),
    'snoozed_items', COALESCE(v_snoozed_items_json, '[]'::jsonb),
    'baseline_component_rows', COALESCE(v_baseline_component_rows_json, '[]'::jsonb),
    'paye_candidate', v_paye_candidate_json,
    'non_paye_payee', v_non_paye_payee_json
  );

  WITH summary_totals AS (
    SELECT
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'candidate_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'candidate_count')::integer ELSE 0 END), 0) AS candidate_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'paye_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'paye_candidates_count')::integer ELSE 0 END), 0) AS paye_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'non_paye_payees_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'non_paye_payees_count')::integer ELSE 0 END), 0) AS non_paye_payees_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'ready_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'ready_candidates_count')::integer ELSE 0 END), 0) AS ready_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_candidates_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_candidates_count')::integer ELSE 0 END), 0) AS blocked_candidates_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'case_resolution_state_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'case_resolution_state_count')::integer ELSE 0 END), 0) AS case_resolution_state_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_case_state_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_case_state_count')::integer ELSE 0 END), 0) AS blocked_case_state_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'canonical_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'canonical_preview_line_count')::integer ELSE 0 END), 0) AS canonical_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'ready_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'ready_preview_line_count')::integer ELSE 0 END), 0) AS ready_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'blocked_preview_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'blocked_preview_line_count')::integer ELSE 0 END), 0) AS blocked_preview_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'do_not_pay_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'do_not_pay_line_count')::integer ELSE 0 END), 0) AS do_not_pay_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'snoozed_line_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'snoozed_line_count')::integer ELSE 0 END), 0) AS snoozed_line_count,
      COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'payees_count', '') ~ '^-?[0-9]+$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'payees_count')::integer ELSE 0 END), 0) AS payees_count,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_ex_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'total_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'total_amount_inc_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS total_amount_inc_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_ex_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_ex_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_vat,
      ROUND(COALESCE(SUM(CASE WHEN COALESCE(selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_inc_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_workbench_candidate_state.summary_fragment_json->>'draftable_amount_inc_vat')::numeric ELSE 0::numeric END), 0::numeric), 2) AS draftable_amount_inc_vat
    FROM selected_workbench_candidate_state
  )
  SELECT jsonb_build_object(
    'candidates', jsonb_build_object(
      'ready_count', COALESCE(summary_totals.ready_candidates_count, 0),
      'review_required_count', COALESCE(summary_totals.blocked_candidates_count, 0),
      'total_candidates', COALESCE(summary_totals.candidate_count, 0)
    ),
    'candidate_count', COALESCE(summary_totals.candidate_count, 0),
    'paye_candidates_count', COALESCE(summary_totals.paye_candidates_count, 0),
    'non_paye_payees_count', COALESCE(summary_totals.non_paye_payees_count, 0),
    'ready_candidates_count', COALESCE(summary_totals.ready_candidates_count, 0),
    'blocked_candidates_count', COALESCE(summary_totals.blocked_candidates_count, 0),
    'case_resolution_state_count', COALESCE(summary_totals.case_resolution_state_count, 0),
    'blocked_case_state_count', COALESCE(summary_totals.blocked_case_state_count, 0),
    'canonical_preview_line_count', COALESCE(summary_totals.canonical_preview_line_count, 0),
    'ready_preview_line_count', COALESCE(summary_totals.ready_preview_line_count, 0),
    'blocked_preview_line_count', COALESCE(summary_totals.blocked_preview_line_count, 0),
    'do_not_pay_line_count', COALESCE(summary_totals.do_not_pay_line_count, 0),
    'snoozed_line_count', COALESCE(summary_totals.snoozed_line_count, 0),
    'payees_count', COALESCE(summary_totals.payees_count, 0),
    'total_amount_ex_vat', COALESCE(summary_totals.total_amount_ex_vat, 0::numeric),
    'total_amount_vat', COALESCE(summary_totals.total_amount_vat, 0::numeric),
    'total_amount_inc_vat', COALESCE(summary_totals.total_amount_inc_vat, 0::numeric),
    'draftable_amount_ex_vat', COALESCE(summary_totals.draftable_amount_ex_vat, 0::numeric),
    'draftable_amount_vat', COALESCE(summary_totals.draftable_amount_vat, 0::numeric),
    'draftable_amount_inc_vat', COALESCE(summary_totals.draftable_amount_inc_vat, 0::numeric)
  )
  INTO v_summary_json
  FROM summary_totals;

  WITH scoped_candidates AS (
    SELECT scope_candidate.scope_candidate_id_value AS candidate_id
    FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scope_candidate(scope_candidate_id_value)
  ),
  latest_session_candidate_state AS (
    SELECT
      scoped_candidates.candidate_id,
      CASE
        WHEN latest_state.id IS NULL THEN 'PENDING'
        WHEN UPPER(COALESCE(latest_state.status, '')) = 'FAILED' THEN 'FAILED'
        WHEN UPPER(COALESCE(latest_state.status, '')) = 'READY' THEN 'READY'
        ELSE 'PENDING'
      END AS effective_status
    FROM scoped_candidates
    LEFT JOIN LATERAL (
      SELECT public.banking_pay_workbench_session_candidate_state.*
      FROM public.banking_pay_workbench_session_candidate_state
      WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
        AND public.banking_pay_workbench_session_candidate_state.candidate_id = scoped_candidates.candidate_id
      ORDER BY public.banking_pay_workbench_session_candidate_state.updated_at_utc DESC, public.banking_pay_workbench_session_candidate_state.id DESC
      LIMIT 1
    ) AS latest_state ON true
  )
  SELECT
    COALESCE(
      jsonb_agg(latest_session_candidate_state.candidate_id::text ORDER BY latest_session_candidate_state.candidate_id)
        FILTER (WHERE latest_session_candidate_state.effective_status = 'PENDING'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(latest_session_candidate_state.candidate_id::text ORDER BY latest_session_candidate_state.candidate_id)
        FILTER (WHERE latest_session_candidate_state.effective_status = 'FAILED'),
      '[]'::jsonb
    )
  INTO
    v_pending_candidate_ids_jsonb,
    v_failed_candidate_ids_jsonb
  FROM latest_session_candidate_state;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_version', v_session_row.version,
    'candidate_id', p_candidate_id::text,
    'candidate_fragment_json', COALESCE(v_candidate_fragment_json, '{}'::jsonb),
    'candidate_rollup_json', v_candidate_rollup_json,
    'summary', v_summary_json,
    'paye_guardrails', COALESCE(v_snapshot_run_row.paye_guardrails_json, '{}'::jsonb),
    'paye_candidate', v_paye_candidate_json,
    'non_paye_payee', v_non_paye_payee_json,
    'payees', COALESCE(v_payees_json, '[]'::jsonb),
    'case_resolution_states', COALESCE(v_case_resolution_states_json, '[]'::jsonb),
    'canonical_preview_lines', COALESCE(v_canonical_preview_lines_json, '[]'::jsonb),
    'itemisation', COALESCE(v_itemisation_json, '[]'::jsonb),
    'blocked_items', COALESCE(v_blocked_items_json, '[]'::jsonb),
    'do_not_pay_items', COALESCE(v_do_not_pay_items_json, '[]'::jsonb),
    'snoozed_items', COALESCE(v_snoozed_items_json, '[]'::jsonb),
    'baseline_component_rows', COALESCE(v_baseline_component_rows_json, '[]'::jsonb),
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false),
    'pending_candidate_ids', v_pending_candidate_ids_jsonb,
    'failed_candidate_ids', v_failed_candidate_ids_jsonb
  );
END;
$function$;





CREATE OR REPLACE FUNCTION public.pay_workbench_session_clear_case_resolution(
  p_session_id uuid,
  p_actor_user_id uuid,
  p_resolution_payload_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_resolution_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_resolution_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_resolution_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_candidate_id uuid := NULL::uuid;
  v_candidate_id_text text := '';
  v_case_key text := '';
  v_linked_timesheet_id uuid := NULL::uuid;
  v_linked_timesheet_id_text text := '';
  v_finance_case_id_text text := '';
  v_matching_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_matching_candidate_count integer := 0;
  v_new_session_version bigint := 0;
  v_job_json jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_case_resolution_ids jsonb := '[]'::jsonb;
  v_resolution_identity_keys jsonb := '[]'::jsonb;
  v_case_resolution_id_text text := null;
  v_deleted_count integer := 0;
  v_existing_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  PERFORM 1
  FROM public.tms_users
  WHERE public.tms_users.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  v_candidate_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'candidate_id',
    v_resolution_payload_json #>> '{case,candidate_id}',
    ''
  ));
  IF v_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_candidate_id := v_candidate_id_text::uuid;
  END IF;

  v_case_key := BTRIM(COALESCE(
    v_resolution_payload_json->>'case_key',
    v_resolution_payload_json #>> '{case,case_key}',
    ''
  ));
  IF v_case_key = '' THEN
    RAISE EXCEPTION 'case_key is required';
  END IF;

  v_linked_timesheet_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'linked_timesheet_id',
    v_resolution_payload_json->>'timesheet_id',
    ''
  ));
  IF v_linked_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_linked_timesheet_id := v_linked_timesheet_id_text::uuid;
  END IF;

  v_finance_case_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'finance_case_id',
    v_resolution_payload_json #>> '{case,finance_case_id}',
    ''
  ));

  create temp table if not exists _tmp_bpay_session_case_resolution_existing
  as
  select *
  from public.banking_pay_workbench_session_case_resolutions
  with no data;

  truncate table _tmp_bpay_session_case_resolution_existing;

  IF v_candidate_id IS NULL THEN
    SELECT COALESCE(array_agg(DISTINCT existing_resolution.candidate_id ORDER BY existing_resolution.candidate_id), ARRAY[]::uuid[])
    INTO v_matching_candidate_ids
    FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
    WHERE existing_resolution.session_id = p_session_id
      AND existing_resolution.case_key = v_case_key
      AND (
        v_linked_timesheet_id IS NULL
        OR existing_resolution.timesheet_id = v_linked_timesheet_id
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'linked_timesheet_id', '')), '') = v_linked_timesheet_id::text
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'timesheet_id', '')), '') = v_linked_timesheet_id::text
      )
      AND (
        v_finance_case_id_text = ''
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') = v_finance_case_id_text
      );

    v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);

    IF v_matching_candidate_count = 0 THEN
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', null,
        'session_version', v_session_row.version,
        'job_id', null,
        'case_resolution_id', null,
        'case_resolution_ids', '[]'::jsonb,
        'resolution_identity_keys', '[]'::jsonb,
        'deleted_count', 0,
        'cleared', false,
        'state_changed', false
      );
    ELSIF v_matching_candidate_count > 1 THEN
      RAISE EXCEPTION 'Ambiguous session case resolution clear target for case_key % in session %', v_case_key, p_session_id;
    END IF;

    v_candidate_id := v_matching_candidate_ids[1];
  END IF;

  INSERT INTO _tmp_bpay_session_case_resolution_existing
  SELECT existing_resolution.*
  FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
  WHERE existing_resolution.session_id = p_session_id
    AND existing_resolution.candidate_id = v_candidate_id
    AND existing_resolution.case_key = v_case_key
    AND (
      v_linked_timesheet_id IS NULL
      OR existing_resolution.timesheet_id = v_linked_timesheet_id
      OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'linked_timesheet_id', '')), '') = v_linked_timesheet_id::text
      OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'timesheet_id', '')), '') = v_linked_timesheet_id::text
    )
    AND (
      v_finance_case_id_text = ''
      OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') IS NULL
      OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') = v_finance_case_id_text
    );

  SELECT COUNT(*)::integer
  INTO v_deleted_count
  FROM _tmp_bpay_session_case_resolution_existing;

  IF v_deleted_count = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', CASE WHEN v_candidate_id IS NULL THEN NULL ELSE v_candidate_id::text END,
      'session_version', v_session_row.version,
      'job_id', null,
      'case_resolution_id', null,
      'case_resolution_ids', '[]'::jsonb,
      'resolution_identity_keys', '[]'::jsonb,
      'deleted_count', 0,
      'cleared', false,
      'state_changed', false
    );
  END IF;

  IF NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[v_candidate_id]::uuid[]) THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', v_candidate_id, p_session_id;
  END IF;

  SELECT COALESCE(jsonb_agg(temp_existing.id::text ORDER BY temp_existing.id::text), '[]'::jsonb),
         COALESCE(jsonb_agg(temp_existing.resolution_identity_key ORDER BY temp_existing.resolution_identity_key), '[]'::jsonb)
  INTO v_case_resolution_ids, v_resolution_identity_keys
  FROM _tmp_bpay_session_case_resolution_existing AS temp_existing;

  SELECT temp_existing.id::text
  INTO v_case_resolution_id_text
  FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
  ORDER BY temp_existing.id
  LIMIT 1;

  DELETE FROM public.banking_pay_workbench_session_case_resolutions AS delete_resolution
  WHERE delete_resolution.id IN (
    SELECT temp_existing.id
    FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
  );

  UPDATE public.banking_pay_workbench_sessions
  SET version = public.banking_pay_workbench_sessions.version + 1,
      updated_at_utc = v_now
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  RETURNING public.banking_pay_workbench_sessions.version
  INTO v_new_session_version;

  v_job_json := public.pay_workbench_enqueue_session_candidate_refresh(
    p_session_id => p_session_id,
    p_candidate_id => v_candidate_id,
    p_reason => 'SESSION_CASE_RESOLUTION_CLEARED',
    p_actor_user_id => p_actor_user_id,
    p_payload_json => jsonb_build_object(
      'case_key', v_case_key,
      'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
      'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
      'resolution_identity_keys', v_resolution_identity_keys
    )
  );

  IF BTRIM(COALESCE(v_job_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_job_id := (v_job_json->>'job_id')::uuid;
  END IF;

  FOR v_existing_row IN
    SELECT temp_existing.*
    FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
    ORDER BY temp_existing.resolution_family, temp_existing.resolution_identity_key
  LOOP
    v_audit_before_json := jsonb_build_object(
      'id', v_existing_row.id::text,
      'session_id', v_existing_row.session_id::text,
      'candidate_id', v_existing_row.candidate_id::text,
      'case_key', v_existing_row.case_key,
      'resolution_family', v_existing_row.resolution_family,
      'resolution_identity_key', v_existing_row.resolution_identity_key,
      'timesheet_id', CASE WHEN v_existing_row.timesheet_id IS NULL THEN NULL ELSE v_existing_row.timesheet_id::text END,
      'source_basis_fingerprint', v_existing_row.source_basis_fingerprint,
      'source_family_key', v_existing_row.source_family_key,
      'bucket_code', v_existing_row.bucket_code,
      'component_key_type', v_existing_row.component_key_type,
      'component_key_value', v_existing_row.component_key_value,
      'payload_json', v_existing_row.payload_json
    );

    v_audit_after_json := jsonb_build_object(
      'id', v_existing_row.id::text,
      'session_id', v_existing_row.session_id::text,
      'candidate_id', v_existing_row.candidate_id::text,
      'case_key', v_existing_row.case_key,
      'resolution_family', v_existing_row.resolution_family,
      'resolution_identity_key', v_existing_row.resolution_identity_key,
      'timesheet_id', CASE WHEN v_existing_row.timesheet_id IS NULL THEN NULL ELSE v_existing_row.timesheet_id::text END,
      'payload_json', v_existing_row.payload_json,
      'session_version', v_new_session_version,
      'pending_job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
      'cleared_at_utc', v_now
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_case_resolution',
      v_existing_row.id::text,
      'SESSION_CASE_RESOLUTION_CLEARED',
      v_audit_before_json,
      v_audit_after_json,
      'SESSION_CASE_RESOLUTION_CLEARED',
      p_actor_user_id
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', v_candidate_id::text,
    'session_version', v_new_session_version,
    'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
    'case_resolution_id', v_case_resolution_id_text,
    'case_resolution_ids', v_case_resolution_ids,
    'resolution_identity_keys', v_resolution_identity_keys,
    'deleted_count', v_deleted_count,
    'cleared', true,
    'state_changed', true
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_session_set_timesheet_exclusion(
  p_session_id uuid,
  p_candidate_id uuid,
  p_timesheet_id uuid,
  p_is_excluded boolean,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_override_identity_key text := '';
  v_existing_row public.banking_pay_workbench_session_overrides%ROWTYPE;
  v_upserted_row public.banking_pay_workbench_session_overrides%ROWTYPE;
  v_new_session_version bigint := 0;
  v_job_json jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_payload_json jsonb := '{}'::jsonb;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_timesheet_in_scope boolean := false;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'timesheet_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  PERFORM 1
  FROM public.tms_users
  WHERE public.tms_users.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  IF NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[p_candidate_id]::uuid[]) THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.banking_pay_workbench_session_candidate_state
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN public.banking_pay_workbench_session_candidate_state.status = 'READY'
         AND jsonb_typeof(public.banking_pay_workbench_session_candidate_state.effective_canonical_preview_lines_json) = 'array'
          THEN COALESCE(public.banking_pay_workbench_session_candidate_state.effective_canonical_preview_lines_json, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS line_element(value)
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
      AND public.banking_pay_workbench_session_candidate_state.candidate_id = p_candidate_id
      AND jsonb_typeof(line_element.value) = 'object'
      AND BTRIM(COALESCE(line_element.value->>'timesheet_id', '')) = p_timesheet_id::text
  )
  INTO v_timesheet_in_scope;

  IF v_timesheet_in_scope = false THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.banking_pay_snapshot_line_state
      WHERE public.banking_pay_snapshot_line_state.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND public.banking_pay_snapshot_line_state.candidate_id = p_candidate_id
        AND public.banking_pay_snapshot_line_state.timesheet_id = p_timesheet_id
    )
    INTO v_timesheet_in_scope;
  END IF;

  IF v_timesheet_in_scope = false THEN
    RAISE EXCEPTION 'timesheet % is not present in current session or snapshot scope for candidate %', p_timesheet_id, p_candidate_id;
  END IF;

  v_override_identity_key := concat_ws('|', 'TIMESHEET_EXCLUSION', p_timesheet_id::text);

  SELECT public.banking_pay_workbench_session_overrides.*
  INTO v_existing_row
  FROM public.banking_pay_workbench_session_overrides
  WHERE public.banking_pay_workbench_session_overrides.session_id = p_session_id
    AND public.banking_pay_workbench_session_overrides.override_identity_key = v_override_identity_key
  LIMIT 1;

  IF v_existing_row.id IS NOT NULL THEN
    v_audit_before_json := jsonb_build_object(
      'id', v_existing_row.id::text,
      'session_id', v_existing_row.session_id::text,
      'candidate_id', v_existing_row.candidate_id::text,
      'override_type', v_existing_row.override_type,
      'override_identity_key', v_existing_row.override_identity_key,
      'timesheet_id', CASE WHEN v_existing_row.timesheet_id IS NULL THEN NULL ELSE v_existing_row.timesheet_id::text END,
      'payload_json', v_existing_row.payload_json
    );
  END IF;

  IF COALESCE(p_is_excluded, false) = true THEN
    v_payload_json := jsonb_build_object(
      'timesheet_id', p_timesheet_id::text,
      'is_excluded', true
    );

    INSERT INTO public.banking_pay_workbench_session_overrides (
      session_id,
      candidate_id,
      override_type,
      override_identity_key,
      timesheet_id,
      payload_json,
      created_at_utc,
      updated_at_utc
    )
    VALUES (
      p_session_id,
      p_candidate_id,
      'TIMESHEET_EXCLUSION',
      v_override_identity_key,
      p_timesheet_id,
      v_payload_json,
      v_now,
      v_now
    )
    ON CONFLICT (session_id, override_identity_key)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        override_type = EXCLUDED.override_type,
        timesheet_id = EXCLUDED.timesheet_id,
        payload_json = EXCLUDED.payload_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_session_overrides.*
    INTO v_upserted_row;
  ELSE
    IF v_existing_row.id IS NULL THEN
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'timesheet_id', p_timesheet_id::text,
        'is_excluded', false,
        'session_version', v_session_row.version,
        'job_id', NULL,
        'override_id', NULL,
        'state_changed', false
      );
    END IF;

    DELETE FROM public.banking_pay_workbench_session_overrides
    WHERE public.banking_pay_workbench_session_overrides.id = v_existing_row.id;

    v_upserted_row := v_existing_row;
  END IF;

  UPDATE public.banking_pay_workbench_sessions
  SET version = public.banking_pay_workbench_sessions.version + 1,
      updated_at_utc = v_now
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  RETURNING public.banking_pay_workbench_sessions.version
  INTO v_new_session_version;

  v_job_json := public.pay_workbench_enqueue_session_candidate_refresh(
    p_session_id => p_session_id,
    p_candidate_id => p_candidate_id,
    p_reason => CASE WHEN COALESCE(p_is_excluded, false) = true THEN 'SESSION_TIMESHEET_EXCLUSION_SET' ELSE 'SESSION_TIMESHEET_EXCLUSION_CLEARED' END,
    p_actor_user_id => p_actor_user_id,
    p_payload_json => jsonb_build_object(
      'override_identity_key', v_override_identity_key,
      'timesheet_id', p_timesheet_id::text,
      'is_excluded', COALESCE(p_is_excluded, false)
    )
  );

  IF BTRIM(COALESCE(v_job_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_job_id := (v_job_json->>'job_id')::uuid;
  END IF;

  v_audit_after_json := jsonb_build_object(
    'id', v_upserted_row.id::text,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'override_type', 'TIMESHEET_EXCLUSION',
    'override_identity_key', v_override_identity_key,
    'timesheet_id', p_timesheet_id::text,
    'payload_json', CASE WHEN COALESCE(p_is_excluded, false) = true THEN v_upserted_row.payload_json ELSE jsonb_build_object('timesheet_id', p_timesheet_id::text, 'is_excluded', false) END,
    'session_version', v_new_session_version,
    'pending_job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session_override',
    v_upserted_row.id::text,
    CASE
      WHEN COALESCE(p_is_excluded, false) = true AND v_existing_row.id IS NULL THEN 'SESSION_TIMESHEET_EXCLUSION_CREATED'
      WHEN COALESCE(p_is_excluded, false) = true THEN 'SESSION_TIMESHEET_EXCLUSION_UPDATED'
      ELSE 'SESSION_TIMESHEET_EXCLUSION_CLEARED'
    END,
    v_audit_before_json,
    v_audit_after_json,
    CASE WHEN COALESCE(p_is_excluded, false) = true THEN 'SESSION_TIMESHEET_EXCLUSION_SET' ELSE 'SESSION_TIMESHEET_EXCLUSION_CLEARED' END,
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'timesheet_id', p_timesheet_id::text,
    'is_excluded', COALESCE(p_is_excluded, false),
    'session_version', v_new_session_version,
    'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
    'override_id', v_upserted_row.id::text,
    'state_changed', true
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_session_set_selected_rows(
  p_session_id uuid,
  p_selected_preview_row_ids jsonb,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_selected_preview_row_ids_input jsonb := COALESCE(p_selected_preview_row_ids, '[]'::jsonb);
  v_selected_preview_row_ids_normalized jsonb := '[]'::jsonb;
  v_missing_preview_row_ids jsonb := '[]'::jsonb;
  v_non_draftable_preview_row_ids jsonb := '[]'::jsonb;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF jsonb_typeof(v_selected_preview_row_ids_input) <> 'array' THEN
    RAISE EXCEPTION 'selected_preview_row_ids must be a JSON array';
  END IF;

  PERFORM 1
  FROM public.tms_users
  WHERE public.tms_users.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  WITH selected_ids_raw AS (
    SELECT BTRIM(selected_id.value) AS preview_row_id,
           selected_id.ordinality AS ordinality
    FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) WITH ORDINALITY AS selected_id(value, ordinality)
    WHERE BTRIM(selected_id.value) <> ''
  ),
  selected_ids_normalized AS (
    SELECT selected_ids_raw.preview_row_id,
           MIN(selected_ids_raw.ordinality) AS first_ordinality
    FROM selected_ids_raw
    GROUP BY selected_ids_raw.preview_row_id
  ),
  session_ready_candidates AS (
    SELECT public.banking_pay_workbench_session_candidate_state.candidate_id,
           COALESCE(public.banking_pay_workbench_session_candidate_state.effective_canonical_preview_lines_json, '[]'::jsonb) AS lines_json
    FROM public.banking_pay_workbench_session_candidate_state
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
      AND public.banking_pay_workbench_session_candidate_state.status = 'READY'
      AND COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[public.banking_pay_workbench_session_candidate_state.candidate_id]::uuid[]
  ),
  snapshot_fallback_candidates AS (
    SELECT public.banking_pay_snapshot_candidate_state.candidate_id,
           COALESCE(public.banking_pay_snapshot_candidate_state.canonical_preview_lines_json, '[]'::jsonb) AS lines_json
    FROM public.banking_pay_snapshot_candidate_state
    WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = v_session_row.source_snapshot_run_id
      AND public.banking_pay_snapshot_candidate_state.status = 'READY'
      AND COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[public.banking_pay_snapshot_candidate_state.candidate_id]::uuid[]
      AND NOT EXISTS (
        SELECT 1
        FROM session_ready_candidates
        WHERE session_ready_candidates.candidate_id = public.banking_pay_snapshot_candidate_state.candidate_id
      )
  ),
  preview_rows_in_scope AS (
    SELECT DISTINCT
           BTRIM(COALESCE(line_element.value->>'preview_row_id', '')) AS preview_row_id,
           CASE
             WHEN LOWER(BTRIM(COALESCE(line_element.value->>'draftable', 'false'))) = 'true'
              AND LOWER(BTRIM(COALESCE(line_element.value->>'is_ready_for_draft', 'false'))) = 'true'
              AND UPPER(BTRIM(COALESCE(
                    line_element.value->>'presentation_section',
                    line_element.value->>'presentationSection',
                    line_element.value->>'readiness_state',
                    line_element.value->>'readinessState',
                    ''
                  ))) = 'READY_TO_PAY'
             THEN true
             ELSE false
           END AS is_draftable_preview_row
    FROM (
      SELECT session_ready_candidates.lines_json AS lines_json
      FROM session_ready_candidates
      UNION ALL
      SELECT snapshot_fallback_candidates.lines_json AS lines_json
      FROM snapshot_fallback_candidates
    ) AS candidate_lines_source
    CROSS JOIN LATERAL jsonb_array_elements(candidate_lines_source.lines_json) AS line_element(value)
    WHERE jsonb_typeof(line_element.value) = 'object'
      AND BTRIM(COALESCE(line_element.value->>'preview_row_id', '')) <> ''
  )
  SELECT
    COALESCE(
      (
        SELECT jsonb_agg(to_jsonb(selected_ids_normalized.preview_row_id) ORDER BY selected_ids_normalized.first_ordinality)
        FROM selected_ids_normalized
        JOIN preview_rows_in_scope
          ON preview_rows_in_scope.preview_row_id = selected_ids_normalized.preview_row_id
         AND preview_rows_in_scope.is_draftable_preview_row = true
      ),
      '[]'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(to_jsonb(selected_ids_normalized.preview_row_id) ORDER BY selected_ids_normalized.first_ordinality)
        FROM selected_ids_normalized
        LEFT JOIN preview_rows_in_scope
          ON preview_rows_in_scope.preview_row_id = selected_ids_normalized.preview_row_id
        WHERE preview_rows_in_scope.preview_row_id IS NULL
      ),
      '[]'::jsonb
    ),
    COALESCE(
      (
        SELECT jsonb_agg(to_jsonb(selected_ids_normalized.preview_row_id) ORDER BY selected_ids_normalized.first_ordinality)
        FROM selected_ids_normalized
        JOIN preview_rows_in_scope
          ON preview_rows_in_scope.preview_row_id = selected_ids_normalized.preview_row_id
         AND preview_rows_in_scope.is_draftable_preview_row = false
      ),
      '[]'::jsonb
    )
  INTO
    v_selected_preview_row_ids_normalized,
    v_missing_preview_row_ids,
    v_non_draftable_preview_row_ids;

  IF jsonb_array_length(v_missing_preview_row_ids) > 0 THEN
    RAISE EXCEPTION 'selected preview row ids are not present in current session or snapshot scope: %', v_missing_preview_row_ids::text;
  END IF;

  v_audit_before_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false),
    'version', v_session_row.version
  );

  UPDATE public.banking_pay_workbench_sessions
  SET server_selected_preview_row_ids = v_selected_preview_row_ids_normalized,
      server_selected_preview_row_ids_provided = true,
      updated_at_utc = v_now
  WHERE public.banking_pay_workbench_sessions.id = p_session_id;

  v_audit_after_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'server_selected_preview_row_ids', v_selected_preview_row_ids_normalized,
    'server_selected_preview_row_ids_provided', true,
    'dropped_non_draftable_preview_row_ids', v_non_draftable_preview_row_ids,
    'version', v_session_row.version,
    'updated_at_utc', v_now
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_session_id::text,
    'SESSION_SELECTED_ROWS_SET',
    v_audit_before_json,
    v_audit_after_json,
    'SESSION_SELECTED_ROWS_SET',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_version', v_session_row.version,
    'selected_preview_row_ids', v_selected_preview_row_ids_normalized,
    'selected_preview_row_ids_provided', true,
    'server_selected_preview_row_ids', v_selected_preview_row_ids_normalized,
    'server_selected_preview_row_ids_provided', true,
    'dropped_non_draftable_preview_row_ids', v_non_draftable_preview_row_ids
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.pay_workbench_session_recompute_candidate(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_workbench_session_recompute_candidate(uuid, uuid, uuid);


CREATE OR REPLACE FUNCTION public.pay_workbench_session_recompute_candidate(
  p_session_id uuid,
  p_candidate_id uuid,
  p_job_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_session_candidate_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_snapshot_candidate_row public.banking_pay_snapshot_candidate_state%ROWTYPE;
  v_recomputed_row public.banking_pay_workbench_session_candidate_state%ROWTYPE;
  v_claimed_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_running_job_count integer := 0;
  v_claimed_job_session_version bigint := 0;
  v_max_inflight_session_version bigint := 0;
  v_context_json jsonb := '{}'::jsonb;
  v_case_resolutions_json jsonb := '{}'::jsonb;
  v_overrides_json jsonb := '{}'::jsonb;
  v_exclude_timesheet_ids_jsonb jsonb := '[]'::jsonb;
  v_effective_json jsonb := '{}'::jsonb;
  v_candidate_rollup_json jsonb := '{}'::jsonb;
  v_filter_candidate_id uuid := NULL::uuid;
  v_filter_client_id uuid := NULL::uuid;
  v_live_change_seq bigint := 0;
  v_snapshot_refresh_json jsonb := '{}'::jsonb;
  v_snapshot_refresh_job_id uuid := NULL::uuid;
  v_existing_snapshot_job_id uuid := NULL::uuid;
  v_existing_snapshot_job_source_change_seq bigint := 0;
  v_last_error_json jsonb := NULL;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_snapshot_refresh_payload_json jsonb := '{}'::jsonb;
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_snapshot_projection_version integer := 0;
  v_snapshot_hidden_recovery_template_projection_version integer := 0;
  v_snapshot_has_hidden_recovery_templates boolean := false;
  v_effective_has_hidden_recovery_templates boolean := false;
  v_effective_missing_snapshot_hidden_manual_debt_template boolean := false;
  v_snapshot_visible_paye_manual_debt_without_hidden_template boolean := false;
  v_rollup_visible_paye_manual_debt_without_hidden_template boolean := false;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'candidate_id is required';
  END IF;

  SELECT ws.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status = 'DISCARDED' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'status', 'DISCARDED',
      'no_op', true,
      'reason', 'SESSION_DISCARDED'
    );
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  IF NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[p_candidate_id]::uuid[]) THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', p_candidate_id, p_session_id;
  END IF;

  SELECT scs.*
  INTO v_session_candidate_row
  FROM public.banking_pay_workbench_session_candidate_state AS scs
  WHERE scs.session_id = p_session_id
    AND scs.candidate_id = p_candidate_id
  LIMIT 1;

  SELECT snap.*
  INTO v_snapshot_candidate_row
  FROM public.banking_pay_snapshot_candidate_state AS snap
  WHERE snap.snapshot_run_id = v_session_row.source_snapshot_run_id
    AND snap.candidate_id = p_candidate_id
  LIMIT 1;

  SELECT COALESCE(acc.seq, 0)
  INTO v_live_change_seq
  FROM public.app_change_counters AS acc
  WHERE acc.entity_key = 'pay_candidate:' || p_candidate_id::text;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  v_snapshot_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_snapshot_candidate_row.candidate_fragment_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_snapshot_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_snapshot_candidate_row.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_snapshot_has_hidden_recovery_templates := COALESCE(
    jsonb_array_length(
      CASE
        WHEN jsonb_typeof(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ),
    0
  ) > 0;

  IF p_job_id IS NOT NULL THEN
    SELECT j.*
    INTO v_claimed_job_row
    FROM public.banking_pay_workbench_jobs AS j
    WHERE j.id = p_job_id
      AND j.session_id = p_session_id
      AND j.candidate_id = p_candidate_id
      AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
    LIMIT 1;

    IF v_claimed_job_row.id IS NULL THEN
      RAISE EXCEPTION 'banking_pay_workbench_jobs row % not found for session % candidate %', p_job_id, p_session_id, p_candidate_id;
    END IF;

    IF v_claimed_job_row.status <> 'RUNNING' THEN
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'job_id', p_job_id::text,
        'status', v_claimed_job_row.status,
        'no_op', true,
        'reason', 'JOB_NOT_RUNNING'
      );
    END IF;
  ELSE
    SELECT COUNT(*)::integer
    INTO v_running_job_count
    FROM public.banking_pay_workbench_jobs AS j
    WHERE j.session_id = p_session_id
      AND j.candidate_id = p_candidate_id
      AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
      AND j.status = 'RUNNING';

    IF v_running_job_count = 1 THEN
      SELECT j.*
      INTO v_claimed_job_row
      FROM public.banking_pay_workbench_jobs AS j
      WHERE j.session_id = p_session_id
        AND j.candidate_id = p_candidate_id
        AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
        AND j.status = 'RUNNING'
      ORDER BY j.started_at_utc DESC NULLS LAST,
               j.updated_at_utc DESC,
               j.id DESC
      LIMIT 1;
    ELSIF v_running_job_count = 0 THEN
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'no_op', true,
        'reason', 'JOB_CONTEXT_REQUIRED'
      );
    ELSE
      RETURN jsonb_build_object(
        'ok', true,
        'session_id', p_session_id::text,
        'candidate_id', p_candidate_id::text,
        'no_op', true,
        'reason', 'AMBIGUOUS_RUNNING_JOB_CONTEXT'
      );
    END IF;
  END IF;

  IF COALESCE(v_claimed_job_row.payload_json->>'session_version', '') !~ '^[0-9]+$' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
      'no_op', true,
      'reason', 'JOB_CONTEXT_VERSION_MISSING'
    );
  END IF;

  v_claimed_job_session_version := (v_claimed_job_row.payload_json->>'session_version')::bigint;

  SELECT COALESCE(
           MAX(
             CASE
               WHEN COALESCE(j.payload_json->>'session_version', '') ~ '^[0-9]+$'
                 THEN (j.payload_json->>'session_version')::bigint
               ELSE NULL::bigint
             END
           ),
           0
         )
  INTO v_max_inflight_session_version
  FROM public.banking_pay_workbench_jobs AS j
  WHERE j.session_id = p_session_id
    AND j.candidate_id = p_candidate_id
    AND j.job_type = 'SESSION_CANDIDATE_RECOMPUTE'
    AND j.status IN ('QUEUED', 'RUNNING');

  IF v_claimed_job_session_version < v_session_row.version
     OR v_claimed_job_session_version < v_max_inflight_session_version THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
      'session_version', v_session_row.version,
      'claimed_job_session_version', v_claimed_job_session_version,
      'max_inflight_session_version', v_max_inflight_session_version,
      'no_op', true,
      'reason', 'STALE_SESSION_VERSION'
    );
  END IF;

  IF v_snapshot_candidate_row.id IS NULL
     OR v_snapshot_candidate_row.status <> 'READY'
     OR COALESCE(v_snapshot_candidate_row.source_change_seq, 0) < v_live_change_seq
     OR v_snapshot_projection_version < v_required_projection_version
     OR (
       v_requires_hidden_recovery_templates = true
       AND v_snapshot_hidden_recovery_template_projection_version < v_required_hidden_recovery_template_projection_version
     ) THEN
    SELECT j.id,
           COALESCE(
             CASE
               WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                 THEN (j.payload_json->>'source_change_seq')::bigint
               ELSE 0::bigint
             END,
             0::bigint
           )
    INTO v_existing_snapshot_job_id, v_existing_snapshot_job_source_change_seq
    FROM public.banking_pay_workbench_jobs AS j
    WHERE j.snapshot_run_id = v_session_row.source_snapshot_run_id
      AND j.candidate_id = p_candidate_id
      AND j.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
      AND j.status IN ('QUEUED', 'RUNNING')
    ORDER BY COALESCE(
               CASE
                 WHEN COALESCE(j.payload_json->>'source_change_seq', '') ~ '^[0-9]+$'
                   THEN (j.payload_json->>'source_change_seq')::bigint
                 ELSE 0::bigint
               END,
               0::bigint
             ) DESC,
             j.updated_at_utc DESC NULLS LAST,
             j.created_at_utc DESC NULLS LAST,
             j.id DESC
    LIMIT 1;

    IF v_existing_snapshot_job_id IS NOT NULL
       AND (
         v_existing_snapshot_job_source_change_seq >= v_live_change_seq
         OR (
           v_snapshot_candidate_row.id IS NOT NULL
           AND UPPER(COALESCE(v_snapshot_candidate_row.status, '')) = 'PENDING'
           AND COALESCE(v_snapshot_candidate_row.source_change_seq, 0) >= v_live_change_seq
         )
       ) THEN
      v_snapshot_refresh_job_id := v_existing_snapshot_job_id;
    ELSE
      v_snapshot_refresh_payload_json := public._pay_workbench_merge_targeted_scope_payload(
        jsonb_build_object(
          'session_id', p_session_id::text,
          'candidate_id', p_candidate_id::text,
          'session_version', v_session_row.version,
          'trigger_job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
          'projection_version', v_required_projection_version,
          'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
          'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates,
          'refresh_reason', 'PROJECTION_VERSION_STALE'
        ),
        CASE
          WHEN jsonb_typeof(COALESCE(v_claimed_job_row.payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(v_claimed_job_row.payload_json, '{}'::jsonb)
          ELSE '{}'::jsonb
        END
      );

      v_snapshot_refresh_json := public.pay_workbench_enqueue_candidate_refresh(
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_candidate_id => p_candidate_id,
        p_reason => 'SESSION_RECOMPUTE_WAITING_FOR_SNAPSHOT',
        p_actor_user_id => NULL::uuid,
        p_payload_json => v_snapshot_refresh_payload_json
      );

      IF BTRIM(COALESCE(v_snapshot_refresh_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_snapshot_refresh_job_id := (v_snapshot_refresh_json->>'job_id')::uuid;
      END IF;
    END IF;

    INSERT INTO public.banking_pay_workbench_session_candidate_state (
      session_id,
      candidate_id,
      status,
      effective_candidate_fragment_json,
      effective_summary_fragment_json,
      effective_paye_candidate_json,
      effective_non_paye_payee_json,
      effective_payees_json,
      effective_case_resolution_states_json,
      effective_canonical_preview_lines_json,
      source_change_seq,
      session_version,
      pending_job_id,
      created_at_utc,
      updated_at_utc,
      last_recomputed_at_utc,
      last_error_json
    )
    VALUES (
      p_session_id,
      p_candidate_id,
      'PENDING',
      '{}'::jsonb,
      '{}'::jsonb,
      NULL,
      NULL,
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb,
      GREATEST(v_live_change_seq, COALESCE(v_snapshot_candidate_row.source_change_seq, 0), COALESCE(v_existing_snapshot_job_source_change_seq, 0)),
      v_session_row.version,
      v_snapshot_refresh_job_id,
      v_now,
      v_now,
      NULL,
      NULL
    )
    ON CONFLICT (session_id, candidate_id)
    DO UPDATE
    SET status = 'PENDING',
        effective_candidate_fragment_json = '{}'::jsonb,
        effective_summary_fragment_json = '{}'::jsonb,
        effective_paye_candidate_json = NULL,
        effective_non_paye_payee_json = NULL,
        effective_payees_json = '[]'::jsonb,
        effective_case_resolution_states_json = '[]'::jsonb,
        effective_canonical_preview_lines_json = '[]'::jsonb,
        source_change_seq = GREATEST(public.banking_pay_workbench_session_candidate_state.source_change_seq, GREATEST(v_live_change_seq, COALESCE(v_snapshot_candidate_row.source_change_seq, 0), COALESCE(v_existing_snapshot_job_source_change_seq, 0))),
        session_version = GREATEST(public.banking_pay_workbench_session_candidate_state.session_version, v_session_row.version),
        pending_job_id = COALESCE(v_snapshot_refresh_job_id, public.banking_pay_workbench_session_candidate_state.pending_job_id),
        updated_at_utc = v_now,
        last_recomputed_at_utc = NULL,
        last_error_json = NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'candidate_id', p_candidate_id::text,
      'job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
      'session_version', v_session_row.version,
      'claimed_job_session_version', v_claimed_job_session_version,
      'source_change_seq', v_live_change_seq,
      'waiting_for_snapshot', true,
      'snapshot_refresh_job_id', CASE WHEN v_snapshot_refresh_job_id IS NULL THEN NULL ELSE v_snapshot_refresh_job_id::text END
    );
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId')::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId')::uuid;
  END IF;

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_session_row.pay_date,
    p_week_ending_cutoff => v_session_row.week_ending_cutoff,
    p_actor_user_id => NULL::uuid,
    p_candidate_id => p_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => NULL::jsonb
  );

  SELECT COALESCE(
           jsonb_object_agg(scr.resolution_identity_key, scr.payload_json),
           '{}'::jsonb
         )
  INTO v_case_resolutions_json
  FROM public.banking_pay_workbench_session_case_resolutions AS scr
  WHERE scr.session_id = p_session_id
    AND scr.candidate_id = p_candidate_id;

  SELECT COALESCE(
           jsonb_agg(sov.timesheet_id::text ORDER BY sov.timesheet_id::text),
           '[]'::jsonb
         )
  INTO v_exclude_timesheet_ids_jsonb
  FROM public.banking_pay_workbench_session_overrides AS sov
  WHERE sov.session_id = p_session_id
    AND sov.candidate_id = p_candidate_id
    AND sov.override_type = 'TIMESHEET_EXCLUSION'
    AND sov.timesheet_id IS NOT NULL;

  v_overrides_json := jsonb_build_object(
    'exclude_timesheet_ids', COALESCE(v_exclude_timesheet_ids_jsonb, '[]'::jsonb)
  );

  v_audit_before_json := CASE
    WHEN v_session_candidate_row.id IS NULL THEN NULL
    ELSE jsonb_build_object(
      'id', v_session_candidate_row.id::text,
      'session_id', v_session_candidate_row.session_id::text,
      'candidate_id', v_session_candidate_row.candidate_id::text,
      'status', v_session_candidate_row.status,
      'source_change_seq', v_session_candidate_row.source_change_seq,
      'session_version', v_session_candidate_row.session_version,
      'pending_job_id', CASE WHEN v_session_candidate_row.pending_job_id IS NULL THEN NULL ELSE v_session_candidate_row.pending_job_id::text END,
      'last_recomputed_at_utc', v_session_candidate_row.last_recomputed_at_utc,
      'last_error_json', v_session_candidate_row.last_error_json
    )
  END;

  v_effective_json := public.pay_preview_apply_candidate_overlay(
    p_candidate_baseline_json => COALESCE(v_snapshot_candidate_row.candidate_fragment_json, '{}'::jsonb),
    p_case_resolutions_json => v_case_resolutions_json,
    p_overrides_json => v_overrides_json
  );

  v_effective_json := jsonb_strip_nulls(
    COALESCE(v_effective_json, '{}'::jsonb)
    || jsonb_build_object(
      'projection_version', v_required_projection_version,
      'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version,
      'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates
    )
  );

  v_effective_has_hidden_recovery_templates := COALESCE(
    jsonb_array_length(
      CASE
        WHEN jsonb_typeof(v_effective_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_effective_json->'hidden_recovery_template_lines', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ),
    0
  ) > 0;

  SELECT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(v_snapshot_candidate_row.canonical_preview_lines_json) = 'array' THEN COALESCE(v_snapshot_candidate_row.canonical_preview_lines_json, '[]'::jsonb)
               ELSE '[]'::jsonb
             END
           ) AS snapshot_preview_line(value)
           WHERE jsonb_typeof(snapshot_preview_line.value) = 'object'
             AND UPPER(COALESCE(snapshot_preview_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
             AND UPPER(COALESCE(snapshot_preview_line.value->>'pay_channel', '')) = 'PAYE'
             AND UPPER(COALESCE(snapshot_preview_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
             AND COALESCE(NULLIF(BTRIM(COALESCE(snapshot_preview_line.value->>'finance_case_id', '')), ''), '') <> ''
             AND NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(
                 CASE
                   WHEN jsonb_typeof(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
                   ELSE '[]'::jsonb
                 END
               ) AS snapshot_hidden_template(value)
               WHERE jsonb_typeof(snapshot_hidden_template.value) = 'object'
                 AND UPPER(COALESCE(snapshot_hidden_template.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                 AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(snapshot_hidden_template.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
                 AND COALESCE(NULLIF(BTRIM(COALESCE(snapshot_hidden_template.value->>'finance_case_id', '')), ''), '') =
                     COALESCE(NULLIF(BTRIM(COALESCE(snapshot_preview_line.value->>'finance_case_id', '')), ''), '')
             )
         )
  INTO v_snapshot_visible_paye_manual_debt_without_hidden_template;

  SELECT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_snapshot_candidate_row.candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
               ELSE '[]'::jsonb
             END
           ) AS snap_tpl(value)
           WHERE jsonb_typeof(snap_tpl.value) = 'object'
             AND UPPER(COALESCE(snap_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
             AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
             AND NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(
                 CASE
                   WHEN jsonb_typeof(v_effective_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_effective_json->'hidden_recovery_template_lines', '[]'::jsonb)
                   ELSE '[]'::jsonb
                 END
               ) AS eff_tpl(value)
               WHERE jsonb_typeof(eff_tpl.value) = 'object'
                 AND UPPER(COALESCE(eff_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                 AND COALESCE(NULLIF(BTRIM(COALESCE(eff_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(snap_tpl.value->>'finance_case_id', '')), ''), '')
             )
         )
  INTO v_effective_missing_snapshot_hidden_manual_debt_template;

  IF v_requires_hidden_recovery_templates
     AND v_snapshot_has_hidden_recovery_templates
     AND (v_effective_has_hidden_recovery_templates = false OR v_effective_missing_snapshot_hidden_manual_debt_template = true) THEN
    RAISE EXCEPTION 'SESSION_EFFECTIVE_FRAGMENT_LOST_HIDDEN_RECOVERY_TEMPLATE';
  END IF;

  v_candidate_rollup_json := public.pay_preview_build_candidate_rollup(
    p_context_json => v_context_json,
    p_candidate_effective_json => v_effective_json
  );

  SELECT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(
             CASE
               WHEN jsonb_typeof(v_candidate_rollup_json->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_rollup_json->'canonical_preview_lines', '[]'::jsonb)
               ELSE '[]'::jsonb
             END
           ) AS rollup_preview_line(value)
           WHERE jsonb_typeof(rollup_preview_line.value) = 'object'
             AND UPPER(COALESCE(rollup_preview_line.value->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
             AND UPPER(COALESCE(rollup_preview_line.value->>'pay_channel', '')) = 'PAYE'
             AND UPPER(COALESCE(rollup_preview_line.value->>'paye_treatment', '')) = 'NET_DEDUCT'
             AND COALESCE(NULLIF(BTRIM(COALESCE(rollup_preview_line.value->>'finance_case_id', '')), ''), '') <> ''
             AND NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(
                 CASE
                   WHEN jsonb_typeof(v_effective_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_effective_json->'hidden_recovery_template_lines', '[]'::jsonb)
                   ELSE '[]'::jsonb
                 END
               ) AS effective_hidden_template(value)
               WHERE jsonb_typeof(effective_hidden_template.value) = 'object'
                 AND UPPER(COALESCE(effective_hidden_template.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
                 AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(effective_hidden_template.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
                 AND COALESCE(NULLIF(BTRIM(COALESCE(effective_hidden_template.value->>'finance_case_id', '')), ''), '') =
                     COALESCE(NULLIF(BTRIM(COALESCE(rollup_preview_line.value->>'finance_case_id', '')), ''), '')
             )
         )
  INTO v_rollup_visible_paye_manual_debt_without_hidden_template;

  IF v_requires_hidden_recovery_templates
     AND (v_snapshot_visible_paye_manual_debt_without_hidden_template OR v_rollup_visible_paye_manual_debt_without_hidden_template) THEN
    RAISE EXCEPTION 'SESSION_EFFECTIVE_FRAGMENT_LOST_HIDDEN_RECOVERY_TEMPLATE';
  END IF;

  INSERT INTO public.banking_pay_workbench_session_candidate_state (
    session_id,
    candidate_id,
    status,
    effective_candidate_fragment_json,
    effective_summary_fragment_json,
    effective_paye_candidate_json,
    effective_non_paye_payee_json,
    effective_payees_json,
    effective_case_resolution_states_json,
    effective_canonical_preview_lines_json,
    source_change_seq,
    session_version,
    pending_job_id,
    created_at_utc,
    updated_at_utc,
    last_recomputed_at_utc,
    last_error_json
  )
  VALUES (
    p_session_id,
    p_candidate_id,
    'READY',
    COALESCE(v_effective_json, '{}'::jsonb),
    COALESCE(v_candidate_rollup_json->'summary_fragment', '{}'::jsonb),
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'paye_candidate') = 'object' THEN v_candidate_rollup_json->'paye_candidate' ELSE NULL END,
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'non_paye_payee') = 'object' THEN v_candidate_rollup_json->'non_paye_payee' ELSE NULL END,
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'payees') = 'array' THEN COALESCE(v_candidate_rollup_json->'payees', '[]'::jsonb) ELSE '[]'::jsonb END,
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'case_resolution_states') = 'array' THEN COALESCE(v_candidate_rollup_json->'case_resolution_states', '[]'::jsonb) ELSE '[]'::jsonb END,
    CASE WHEN jsonb_typeof(v_candidate_rollup_json->'canonical_preview_lines') = 'array' THEN COALESCE(v_candidate_rollup_json->'canonical_preview_lines', '[]'::jsonb) ELSE '[]'::jsonb END,
    v_live_change_seq,
    v_session_row.version,
    NULL::uuid,
    v_now,
    v_now,
    v_now,
    NULL
  )
  ON CONFLICT (session_id, candidate_id)
  DO UPDATE
  SET status = 'READY',
      effective_candidate_fragment_json = EXCLUDED.effective_candidate_fragment_json,
      effective_summary_fragment_json = EXCLUDED.effective_summary_fragment_json,
      effective_paye_candidate_json = EXCLUDED.effective_paye_candidate_json,
      effective_non_paye_payee_json = EXCLUDED.effective_non_paye_payee_json,
      effective_payees_json = EXCLUDED.effective_payees_json,
      effective_case_resolution_states_json = EXCLUDED.effective_case_resolution_states_json,
      effective_canonical_preview_lines_json = EXCLUDED.effective_canonical_preview_lines_json,
      source_change_seq = EXCLUDED.source_change_seq,
      session_version = EXCLUDED.session_version,
      pending_job_id = NULL,
      updated_at_utc = v_now,
      last_recomputed_at_utc = v_now,
      last_error_json = NULL
  RETURNING public.banking_pay_workbench_session_candidate_state.*
  INTO v_recomputed_row;

  v_audit_after_json := jsonb_build_object(
    'id', v_recomputed_row.id::text,
    'session_id', v_recomputed_row.session_id::text,
    'candidate_id', v_recomputed_row.candidate_id::text,
    'status', v_recomputed_row.status,
    'source_change_seq', v_recomputed_row.source_change_seq,
    'session_version', v_recomputed_row.session_version,
    'pending_job_id', CASE WHEN v_recomputed_row.pending_job_id IS NULL THEN NULL ELSE v_recomputed_row.pending_job_id::text END,
    'claimed_job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
    'claimed_job_session_version', v_claimed_job_session_version,
    'last_recomputed_at_utc', v_recomputed_row.last_recomputed_at_utc,
    'summary_fragment_json', COALESCE(v_candidate_rollup_json->'summary_fragment', '{}'::jsonb),
    'paye_candidate_json', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'paye_candidate') = 'object' THEN v_candidate_rollup_json->'paye_candidate' ELSE NULL END,
    'non_paye_payee_json', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'non_paye_payee') = 'object' THEN v_candidate_rollup_json->'non_paye_payee' ELSE NULL END,
    'payees_count', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'payees') = 'array' THEN jsonb_array_length(v_candidate_rollup_json->'payees') ELSE 0 END,
    'case_resolution_state_count', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'case_resolution_states') = 'array' THEN jsonb_array_length(v_candidate_rollup_json->'case_resolution_states') ELSE 0 END,
    'canonical_preview_line_count', CASE WHEN jsonb_typeof(v_candidate_rollup_json->'canonical_preview_lines') = 'array' THEN jsonb_array_length(v_candidate_rollup_json->'canonical_preview_lines') ELSE 0 END,
    'projection_version', v_required_projection_version,
    'hidden_recovery_template_projection_version', v_required_hidden_recovery_template_projection_version
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session_candidate_state',
    v_recomputed_row.id::text,
    'SESSION_CANDIDATE_RECOMPUTE_SUCCEEDED',
    v_audit_before_json,
    v_audit_after_json,
    'SESSION_CANDIDATE_RECOMPUTE',
    NULL::uuid
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', p_candidate_id::text,
    'job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
    'session_version', v_session_row.version,
    'claimed_job_session_version', v_claimed_job_session_version,
    'source_change_seq', v_live_change_seq,
    'last_recomputed_at_utc', v_now,
    'status', 'READY'
  );
EXCEPTION
  WHEN OTHERS THEN
    v_last_error_json := jsonb_build_object(
      'sqlstate', SQLSTATE,
      'message', SQLERRM,
      'session_id', CASE WHEN p_session_id IS NULL THEN NULL ELSE p_session_id::text END,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
      'failed_at_utc', now()
    );

    INSERT INTO public.banking_pay_workbench_session_candidate_state (
      session_id,
      candidate_id,
      status,
      effective_candidate_fragment_json,
      effective_summary_fragment_json,
      effective_paye_candidate_json,
      effective_non_paye_payee_json,
      effective_payees_json,
      effective_case_resolution_states_json,
      effective_canonical_preview_lines_json,
      source_change_seq,
      session_version,
      pending_job_id,
      created_at_utc,
      updated_at_utc,
      last_recomputed_at_utc,
      last_error_json
    )
    VALUES (
      p_session_id,
      p_candidate_id,
      'FAILED',
      '{}'::jsonb,
      '{}'::jsonb,
      NULL,
      NULL,
      '[]'::jsonb,
      '[]'::jsonb,
      '[]'::jsonb,
      COALESCE(v_live_change_seq, 0),
      COALESCE(v_session_row.version, 1),
      NULL::uuid,
      now(),
      now(),
      NULL,
      v_last_error_json
    )
    ON CONFLICT (session_id, candidate_id)
    DO UPDATE
    SET status = 'FAILED',
        source_change_seq = GREATEST(public.banking_pay_workbench_session_candidate_state.source_change_seq, COALESCE(v_live_change_seq, 0)),
        session_version = GREATEST(public.banking_pay_workbench_session_candidate_state.session_version, COALESCE(v_session_row.version, 1)),
        pending_job_id = NULL,
        updated_at_utc = now(),
        last_recomputed_at_utc = NULL,
        last_error_json = v_last_error_json
    RETURNING public.banking_pay_workbench_session_candidate_state.*
    INTO v_recomputed_row;

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_candidate_state',
      v_recomputed_row.id::text,
      'SESSION_CANDIDATE_RECOMPUTE_FAILED',
      v_audit_before_json,
      jsonb_build_object(
        'id', v_recomputed_row.id::text,
        'session_id', v_recomputed_row.session_id::text,
        'candidate_id', v_recomputed_row.candidate_id::text,
        'status', v_recomputed_row.status,
        'source_change_seq', v_recomputed_row.source_change_seq,
        'session_version', v_recomputed_row.session_version,
        'pending_job_id', CASE WHEN v_recomputed_row.pending_job_id IS NULL THEN NULL ELSE v_recomputed_row.pending_job_id::text END,
        'claimed_job_id', CASE WHEN v_claimed_job_row.id IS NULL THEN NULL ELSE v_claimed_job_row.id::text END,
        'last_error_json', v_recomputed_row.last_error_json
      ),
      'SESSION_CANDIDATE_RECOMPUTE',
      NULL::uuid
    );

    RAISE;
END;
$function$;








CREATE OR REPLACE FUNCTION public.pay_workbench_session_discard(
  p_session_id uuid,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_current_london_pay_date date := timezone('Europe/London', v_now)::date;
  v_next_london_pay_date date := (timezone('Europe/London', v_now)::date + 7);
  v_remaining_open_session_count integer := 0;
  v_preserve_snapshot_run boolean := false;
  v_deactivated_snapshot_run_id uuid := NULL::uuid;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  PERFORM 1
  FROM public.tms_users AS tu
  WHERE tu.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT ws.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status = 'DISCARDED' THEN
    RETURN jsonb_build_object(
      'ok', true,
      'session_id', p_session_id::text,
      'status', v_session_row.status,
      'discarded_at_utc', v_session_row.discarded_at_utc,
      'state_changed', false,
      'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
      'run_deactivated', false
    );
  END IF;

  v_audit_before_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'actor_user_id', v_session_row.actor_user_id::text,
    'pay_date', v_session_row.pay_date::text,
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'filters_json', v_session_row.filters_json,
    'scope_candidate_ids', to_jsonb(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])),
    'session_signature', v_session_row.session_signature,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'status', v_session_row.status,
    'version', v_session_row.version,
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'discarded_at_utc', v_session_row.discarded_at_utc
  );

  UPDATE public.banking_pay_workbench_sessions AS ws
  SET status = 'DISCARDED',
      discarded_at_utc = COALESCE(ws.discarded_at_utc, v_now),
      updated_at_utc = v_now
  WHERE ws.id = p_session_id;

  IF v_session_row.source_snapshot_run_id IS NOT NULL THEN
    SELECT COUNT(*)::integer
    INTO v_remaining_open_session_count
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.source_snapshot_run_id = v_session_row.source_snapshot_run_id
      AND ws.status = 'OPEN';

    v_preserve_snapshot_run := COALESCE(v_session_row.pay_date, DATE '1900-01-01') IN (v_current_london_pay_date, v_next_london_pay_date);

    IF v_remaining_open_session_count = 0 AND NOT v_preserve_snapshot_run THEN
      UPDATE public.banking_pay_snapshot_runs AS sr
      SET is_active = false,
          updated_at_utc = v_now
      WHERE sr.id = v_session_row.source_snapshot_run_id
        AND COALESCE(sr.is_active, false) = true
      RETURNING sr.id
      INTO v_deactivated_snapshot_run_id;
    END IF;
  END IF;

  v_audit_after_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'actor_user_id', v_session_row.actor_user_id::text,
    'pay_date', v_session_row.pay_date::text,
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'filters_json', v_session_row.filters_json,
    'scope_candidate_ids', to_jsonb(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])),
    'session_signature', v_session_row.session_signature,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'status', 'DISCARDED',
    'version', v_session_row.version,
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'discarded_at_utc', v_now,
    'remaining_open_session_count_for_run', v_remaining_open_session_count,
    'preserved_current_or_next_run', v_preserve_snapshot_run,
    'run_deactivated', v_deactivated_snapshot_run_id IS NOT NULL
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_session_id::text,
    'WORKBENCH_SESSION_DISCARDED',
    v_audit_before_json,
    v_audit_after_json,
    'SESSION_DISCARD',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'status', 'DISCARDED',
    'discarded_at_utc', v_now,
    'state_changed', true,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'remaining_open_session_count_for_run', v_remaining_open_session_count,
    'preserved_current_or_next_run', v_preserve_snapshot_run,
    'run_deactivated', v_deactivated_snapshot_run_id IS NOT NULL,
    'deactivated_snapshot_run_id', CASE WHEN v_deactivated_snapshot_run_id IS NULL THEN NULL ELSE v_deactivated_snapshot_run_id::text END
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_preview_candidate_build_timesheet_snapshots(
  p_context_json jsonb,
  p_candidate_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_context_matches boolean := false;
  v_context_row_count integer := 0;
  v_context_json jsonb := coalesce(p_context_json, '{}'::jsonb);
  v_candidate_id uuid := p_candidate_id;
  v_pay_date date;
  v_week_ending_cutoff date;
  v_client_id uuid := null::uuid;
  v_actor_user_id uuid := null::uuid;
  v_week_start date;
  v_today_uk date;
  v_snapshot_count integer := 0;
begin
  if jsonb_typeof(v_context_json) <> 'object' then
    raise exception 'p_context_json must be a JSON object';
  end if;

  if v_candidate_id is null then
    raise exception 'candidate_id is required';
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is not null then
    select count(*)::int
    into v_context_row_count
    from pg_temp.pay_preview_candidate_context as ctx;
  else
    v_context_row_count := 0;
  end if;

  if v_context_row_count > 0 then
    select (
      ctx.candidate_id is not distinct from v_candidate_id
      and ctx.context_json = v_context_json
    )
    into v_context_matches
    from pg_temp.pay_preview_candidate_context as ctx
    limit 1;
  else
    v_context_matches := false;
  end if;

  if to_regclass('pg_temp.pay_preview_candidate_context') is null or coalesce(v_context_matches, false) = false then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  if to_regclass('pg_temp.ts_baseline') is null then
    perform public.pay_preview_candidate_collect_scope(v_context_json, v_candidate_id);
  end if;

  select
    ctx.candidate_id,
    ctx.pay_date,
    ctx.week_ending_cutoff,
    ctx.client_id,
    ctx.actor_user_id,
    ctx.week_start,
    ctx.today_uk
  into
    v_candidate_id,
    v_pay_date,
    v_week_ending_cutoff,
    v_client_id,
    v_actor_user_id,
    v_week_start,
    v_today_uk
  from pg_temp.pay_preview_candidate_context as ctx
  limit 1;

  drop table if exists pg_temp.timesheet_snapshot_rows, pg_temp.timesheet_snapshot_rows_json;

  create temporary table timesheet_snapshot_rows on commit drop as
  with tf_live as (
    select
      tf.timesheet_id,
      tf.candidate_id,
      round(coalesce(tf.mileage_units, 0), 2) as mileage_units,
      case
        when tf.mileage_pay_rate is null then null::numeric
        else round(tf.mileage_pay_rate, 6)
      end as mileage_pay_rate
    from public.timesheets_financials as tf
    join pg_temp.ts_baseline as tb
      on tb.timesheet_id = tf.timesheet_id
     and tb.candidate_id = tf.candidate_id
    where tf.is_current = true
      and tb.candidate_id = v_candidate_id
  ),
  target_segments as (
    select
      tb.candidate_id,
      tb.timesheet_id,
      coalesce(
        (
          select jsonb_agg(
            jsonb_strip_nulls(
              jsonb_build_object(
                'segment_id', nullif(btrim(coalesce(seg.seg_json->>'segment_id', '')), ''),
                'segment_key', nullif(btrim(coalesce(seg.seg_json->>'segment_key', '')), ''),
                'segment_stable_key', coalesce(
                  nullif(btrim(coalesce(seg.seg_json->>'segment_stable_key', '')), ''),
                  nullif(btrim(coalesce(seg.seg_json->>'segment_id', '')), ''),
                  nullif(btrim(coalesce(seg.seg_json->>'segment_key', '')), ''),
                  nullif(btrim(coalesce(seg.seg_json->>'date', '')), ''),
                  nullif(btrim(coalesce(seg.seg_json->>'ref_num', '')), '')
                ),
                'date', nullif(btrim(coalesce(seg.seg_json->>'date', '')), ''),
                'start_utc', nullif(btrim(coalesce(seg.seg_json->>'start_utc', '')), ''),
                'end_utc', nullif(btrim(coalesce(seg.seg_json->>'end_utc', '')), ''),
                'start', nullif(btrim(coalesce(seg.seg_json->>'start', '')), ''),
                'end', nullif(btrim(coalesce(seg.seg_json->>'end', '')), ''),
                'break_start', nullif(btrim(coalesce(seg.seg_json->>'break_start', '')), ''),
                'break_end', nullif(btrim(coalesce(seg.seg_json->>'break_end', '')), ''),
                'break_mins', coalesce(
                  nullif(seg.seg_json->>'break_mins', '')::numeric,
                  nullif(seg.seg_json->>'break_minutes', '')::numeric,
                  0::numeric
                ),
                'breaks', case
                  when jsonb_typeof(seg.seg_json->'breaks') = 'array' then seg.seg_json->'breaks'
                  else '[]'::jsonb
                end,
                'hours_day', coalesce(nullif(seg.seg_json->>'hours_day', '')::numeric, 0::numeric),
                'hours_night', coalesce(nullif(seg.seg_json->>'hours_night', '')::numeric, 0::numeric),
                'hours_sat', coalesce(nullif(seg.seg_json->>'hours_sat', '')::numeric, 0::numeric),
                'hours_sun', coalesce(nullif(seg.seg_json->>'hours_sun', '')::numeric, 0::numeric),
                'hours_bh', coalesce(nullif(seg.seg_json->>'hours_bh', '')::numeric, 0::numeric),
                'pay_amount', round(coalesce(nullif(seg.seg_json->>'pay_amount', '')::numeric, 0::numeric), 2),
                'exclude_from_pay', coalesce(nullif(seg.seg_json->>'exclude_from_pay', '')::boolean, false),
                'ref_num', nullif(btrim(coalesce(seg.seg_json->>'ref_num', '')), '')
              )
            )
            order by seg.seg_ord
          )
          from jsonb_array_elements(coalesce(tb.current_segments_json, '[]'::jsonb)) with ordinality as seg(seg_json, seg_ord)
          where seg.seg_json is not null
            and jsonb_typeof(seg.seg_json) = 'object'
        ),
        '[]'::jsonb
      ) as target_segments_json
    from pg_temp.ts_baseline as tb
    where tb.candidate_id = v_candidate_id
  )
  select
    tb.candidate_id,
    tb.timesheet_id,
    tb.client_id,
    tb.ts_week_ending_date as week_ending_date,
    tb.ts_pay_method as source_pay_method,
    tb.cand_pay_method as candidate_pay_method,
    tb.baseline_signature,
    coalesce(tb.base_json, '{}'::jsonb) as base_snapshot_json,
    jsonb_build_object(
      'segments', coalesce(ts.target_segments_json, '[]'::jsonb),
      'additional_pay_ex_vat', round(coalesce(tb.current_additional_pay_ex_vat, 0), 2),
      'additional_units_json', coalesce(tb.current_additional_units_json, '{}'::jsonb),
      'hours_day', round(coalesce(tb.cur_hours_day, 0), 2),
      'hours_night', round(coalesce(tb.cur_hours_night, 0), 2),
      'hours_sat', round(coalesce(tb.cur_hours_sat, 0), 2),
      'hours_sun', round(coalesce(tb.cur_hours_sun, 0), 2),
      'hours_bh', round(coalesce(tb.cur_hours_bh, 0), 2),
      'pay_day', round(coalesce(tb.cur_pay_day, 0), 2),
      'pay_night', round(coalesce(tb.cur_pay_night, 0), 2),
      'pay_sat', round(coalesce(tb.cur_pay_sat, 0), 2),
      'pay_sun', round(coalesce(tb.cur_pay_sun, 0), 2),
      'pay_bh', round(coalesce(tb.cur_pay_bh, 0), 2),
      'mileage_units', round(coalesce(tfl.mileage_units, 0), 2),
      'mileage_pay_rate', case
        when tfl.mileage_pay_rate is null then null::numeric
        else round(tfl.mileage_pay_rate, 6)
      end,
      'expenses', jsonb_build_object(
        'expenses_pay_ex_vat', round(coalesce(tb.current_expenses_pay_ex_vat, 0), 2),
        'travel_pay_ex_vat', round(coalesce(tb.current_travel_pay_ex_vat, 0), 2),
        'accommodation_pay_ex_vat', round(coalesce(tb.current_accommodation_pay_ex_vat, 0), 2),
        'other_pay_ex_vat', round(coalesce(tb.current_other_pay_ex_vat, 0), 2),
        'mileage_pay_ex_vat', round(coalesce(tb.current_mileage_pay_ex_vat, 0), 2)
      ),
      'adjustments', coalesce(tb.current_adjustments_json, '[]'::jsonb),
      'resolved_components', '[]'::jsonb
    ) as target_snapshot_json
  from pg_temp.ts_baseline as tb
  left join target_segments as ts
    on ts.candidate_id = tb.candidate_id
   and ts.timesheet_id = tb.timesheet_id
  left join tf_live as tfl
    on tfl.candidate_id = tb.candidate_id
   and tfl.timesheet_id = tb.timesheet_id
  where tb.candidate_id = v_candidate_id;

  create temporary table timesheet_snapshot_rows_json on commit drop as
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'candidate_id', tsr.candidate_id::text,
          'timesheet_id', tsr.timesheet_id::text,
          'client_id', case when tsr.client_id is null then null else tsr.client_id::text end,
          'week_ending_date', case when tsr.week_ending_date is null then null else tsr.week_ending_date::text end,
          'source_pay_method', tsr.source_pay_method,
          'candidate_pay_method', tsr.candidate_pay_method,
          'baseline_signature', tsr.baseline_signature,
          'base_snapshot_json', tsr.base_snapshot_json,
          'target_snapshot_json', tsr.target_snapshot_json,
          'target_signature', md5(tsr.target_snapshot_json::text)
        )
        order by tsr.week_ending_date nulls last, tsr.timesheet_id::text
      ),
      '[]'::jsonb
    ) as payload
  from pg_temp.timesheet_snapshot_rows as tsr;

  select count(*)::int
  into v_snapshot_count
  from pg_temp.timesheet_snapshot_rows as tsr;

  return jsonb_build_object(
    'candidate_id', v_candidate_id::text,
    'timesheet_snapshot_count', v_snapshot_count,
    'timesheet_snapshots_json', coalesce((select tsrj.payload from pg_temp.timesheet_snapshot_rows_json as tsrj), '[]'::jsonb)
  );
end;
$function$;

DROP FUNCTION IF EXISTS public.pay_batch_insert_candidates_from_preview(uuid, uuid);

CREATE OR REPLACE FUNCTION public.pay_batch_insert_candidates_from_preview(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := NULL;
  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_reused_count integer := 0;
  v_skipped_count integer := 0;
  v_failed_count integer := 0;
  v_existing_count integer := 0;
  v_candidate_ids jsonb := '[]'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_selected_preview_rows temp table is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_candidates_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_candidates_ctx temp table is required';
  END IF;

  SELECT upper(btrim(coalesce(selected_preview_row.pay_channel, '')))
  INTO v_scope
  FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
  WHERE upper(btrim(coalesce(selected_preview_row.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
  GROUP BY upper(btrim(coalesce(selected_preview_row.pay_channel, '')))
  ORDER BY upper(btrim(coalesce(selected_preview_row.pay_channel, '')))
  LIMIT 1;

  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unable to determine pay channel scope from selected preview rows';
  END IF;

  IF (
    SELECT count(*)
    FROM (
      SELECT distinct upper(btrim(coalesce(selected_preview_row.pay_channel, ''))) AS pay_channel_scope
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
      WHERE upper(btrim(coalesce(selected_preview_row.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
    ) AS pay_channel_scope_rows
  ) <> 1 THEN
    RAISE EXCEPTION 'Selected preview rows must belong to exactly one pay channel scope';
  END IF;

  WITH candidate_source AS (
    SELECT DISTINCT
      p_pay_batch_id AS pay_batch_id,
      candidate_context.id AS candidate_id,
      candidate_context.tms_ref AS candidate_tms_ref,
      candidate_context.display_name AS candidate_display_name
    FROM (
      SELECT DISTINCT selected_preview_row.candidate_id
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
    ) AS selected_candidate
    JOIN pg_temp.tmp_pay_build_candidates_ctx AS candidate_context
      ON candidate_context.id = selected_candidate.candidate_id
  )
  SELECT count(*)::integer
  INTO v_existing_count
  FROM candidate_source
  JOIN public.pay_batch_candidates AS existing_candidate
    ON existing_candidate.pay_batch_id = candidate_source.pay_batch_id
   AND existing_candidate.candidate_id = candidate_source.candidate_id;

  WITH candidate_source AS (
    SELECT DISTINCT
      p_pay_batch_id AS pay_batch_id,
      candidate_context.id AS candidate_id,
      candidate_context.tms_ref AS candidate_tms_ref,
      candidate_context.display_name AS candidate_display_name
    FROM (
      SELECT DISTINCT selected_preview_row.candidate_id
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
    ) AS selected_candidate
    JOIN pg_temp.tmp_pay_build_candidates_ctx AS candidate_context
      ON candidate_context.id = selected_candidate.candidate_id
  ),
  updated_candidates AS (
    UPDATE public.pay_batch_candidates AS existing_candidate
    SET
      candidate_tms_ref = candidate_source.candidate_tms_ref,
      candidate_display_name = candidate_source.candidate_display_name,
      updated_at = now()
    FROM candidate_source
    WHERE existing_candidate.pay_batch_id = candidate_source.pay_batch_id
      AND existing_candidate.candidate_id = candidate_source.candidate_id
      AND (
        existing_candidate.candidate_tms_ref IS DISTINCT FROM candidate_source.candidate_tms_ref
        OR existing_candidate.candidate_display_name IS DISTINCT FROM candidate_source.candidate_display_name
      )
    RETURNING existing_candidate.id
  )
  SELECT count(*)::integer
  INTO v_updated_count
  FROM updated_candidates;

  WITH candidate_source AS (
    SELECT DISTINCT
      p_pay_batch_id AS pay_batch_id,
      candidate_context.id AS candidate_id,
      candidate_context.tms_ref AS candidate_tms_ref,
      candidate_context.display_name AS candidate_display_name
    FROM (
      SELECT DISTINCT selected_preview_row.candidate_id
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
    ) AS selected_candidate
    JOIN pg_temp.tmp_pay_build_candidates_ctx AS candidate_context
      ON candidate_context.id = selected_candidate.candidate_id
  ),
  inserted_candidates AS (
    INSERT INTO public.pay_batch_candidates(
      pay_batch_id,
      candidate_id,
      candidate_tms_ref,
      candidate_display_name,
      paye_state,
      mismatch_settlement_choice,
      gross_preview,
      net_bank_amount,
      debt_created,
      loan_repayment_taken,
      overpayment_recovery_taken,
      awaiting_net_amount,
      updated_at
    )
    SELECT
      candidate_source.pay_batch_id,
      candidate_source.candidate_id,
      candidate_source.candidate_tms_ref,
      candidate_source.candidate_display_name,
      CASE WHEN v_scope = 'PAYE' THEN 'PENDING_NET' ELSE NULL END,
      NULL::text,
      NULL::numeric,
      NULL::numeric,
      0::numeric,
      0::numeric,
      0::numeric,
      false,
      now()
    FROM candidate_source
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.pay_batch_candidates AS existing_candidate
      WHERE existing_candidate.pay_batch_id = candidate_source.pay_batch_id
        AND existing_candidate.candidate_id = candidate_source.candidate_id
    )
    RETURNING id
  )
  SELECT count(*)::integer
  INTO v_inserted_count
  FROM inserted_candidates;

  SELECT COALESCE(jsonb_agg(selected_candidate.candidate_id::text ORDER BY selected_candidate.candidate_id::text), '[]'::jsonb)
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT selected_preview_row.candidate_id
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row
  ) AS selected_candidate;

  v_reused_count := coalesce(v_existing_count, 0) - coalesce(v_updated_count, 0);

  IF v_reused_count < 0 THEN
    v_reused_count := 0;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'pay_channel_scope', v_scope,
    'inserted_candidate_rows', v_inserted_count,
    'reused_candidate_rows', v_reused_count,
    'updated_candidate_rows', v_updated_count,
    'skipped_candidate_rows', v_skipped_count,
    'failed_candidate_rows', v_failed_count,
    'candidate_ids', v_candidate_ids
  );
END;
$function$;

DROP FUNCTION IF EXISTS public.pay_batch_insert_items_from_preview(uuid, uuid);


CREATE OR REPLACE FUNCTION public.pay_batch_insert_items_from_preview(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_stage text := NULL;
  v_scope text := NULL;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_exclude_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_client_filter_single uuid := NULL::uuid;
  v_rows_ins_items integer := 0;
  v_vat_rate_pct numeric := NULL::numeric;
  v_week_start date := NULL::date;
  v_rail_provider_default text := NULL;
  v_rail_env_default text := NULL;
  v_operation_reused_count integer := 0;
  v_reservation_skipped_item_rows integer := 0;
  v_reservation_clipped_item_rows integer := 0;
  v_reservation_skipped_preview_row_count integer := 0;
  v_reservation_clipped_preview_row_count integer := 0;
  v_scope_item_rows_after_availability integer := 0;
  v_reservation_availability_preview_rows_json jsonb := '[]'::jsonb;
  v_rows_ins_carry_forward_items integer := 0;
  v_carry_forward_reserve_result jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;


  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_selected_preview_rows temp table is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_preview_candidates') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_preview_candidates temp table is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_timesheet_snapshots_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_timesheet_snapshots_ctx temp table is required';
  END IF;

  SELECT ctx.vat_rate_pct, ctx.pay_week_start, ctx.rail_provider_default, ctx.rail_env_default
  INTO v_vat_rate_pct, v_week_start, v_rail_provider_default, v_rail_env_default
  FROM pg_temp.tmp_pay_build_settings_context ctx
  LIMIT 1;

  IF v_vat_rate_pct IS NULL OR v_week_start IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_settings_context temp table is required';
  END IF;

  SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr;

  SELECT upper(btrim(coalesce(spr.pay_channel, '')))
  INTO v_scope
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr
  WHERE upper(btrim(coalesce(spr.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
  GROUP BY upper(btrim(coalesce(spr.pay_channel, '')))
  ORDER BY upper(btrim(coalesce(spr.pay_channel, '')))
  LIMIT 1;


  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_reservation_availability_report (
    pay_batch_item_id uuid null,
    candidate_id uuid null,
    preview_row_id text null,
    timesheet_id uuid null,
    item_type text null,
    key_type text null,
    key_value text null,
    requested_source_amount_ex_vat numeric(12,2) null,
    allowed_source_amount_ex_vat numeric(12,2) null,
    requested_target_amount_ex_vat numeric(12,2) null,
    allowed_target_amount_ex_vat numeric(12,2) null,
    availability_action text not null,
    message text null,
    created_at_utc timestamptz not null default now()
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_reservation_availability_report;

v_stage := 'STAGE_12_INSERT_PAY_BATCH_ITEMS';

  -- Build pay_batch_items from pay_preview itemisation using case-level safe rows only.
  insert into public.pay_batch_items(
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    operation_source_key
  )
  with all_candidates as (
    select t.cand
    from pg_temp.tmp_pay_build_preview_candidates t
  ),
  candidate_rows as (
    select
      nullif(btrim(coalesce(cand->>'candidate_id','')), '')::uuid as candidate_id,
      upper(btrim(coalesce(cand->>'current_pay_method',''))) as cand_pay_method,
      nullif(btrim(coalesce(cand->>'umbrella_id','')), '')::uuid as umbrella_id,
      coalesce(nullif(cand->>'umbrella_vat_chargeable','')::boolean, false) as umb_vat_chargeable,
      coalesce(nullif(cand->>'is_ready_for_draft','')::boolean, false) as is_ready_for_draft,
      coalesce(cand->'blockers', '[]'::jsonb) as blockers,
      coalesce(cand->'itemisation', '[]'::jsonb) as itemisation
    from all_candidates
    where nullif(btrim(coalesce(cand->>'candidate_id','')), '') is not null
      and (cand->>'candidate_id')::uuid = any(v_candidate_ids)
  ),
  item_rows as (
    select
      cr.candidate_id,
      cr.cand_pay_method,
      cr.umbrella_id,
      cr.umb_vat_chargeable,
      itm as item_json,
      nullif(btrim(coalesce(itm->>'finance_case_id','')), '')::uuid as finance_case_id,
      nullif(btrim(coalesce(itm->>'case_key','')), '') as case_key,
      nullif(btrim(coalesce(itm->>'timesheet_id','')), '')::uuid as timesheet_id,
      nullif(btrim(coalesce(itm->>'client_id','')), '')::uuid as client_id,
      upper(btrim(coalesce(itm->>'source_pay_method',''))) as source_pay_method,
      round(coalesce(nullif(itm->>'payment_amount_ex_vat','')::numeric, 0), 2)::numeric(12,2) as payment_amount_ex_vat,
      coalesce(nullif(itm#>>'{case_resolution_summary,is_blocked}','')::boolean, false) as case_is_blocked,
      coalesce(itm->'components', '[]'::jsonb) as case_components_json
    from candidate_rows cr
    cross join lateral jsonb_array_elements(coalesce(cr.itemisation, '[]'::jsonb)) as itm
  ),
  positive_rows as (
    select
      ir.*
    from item_rows ir
    join pg_temp.tmp_pay_build_selected_preview_rows spr
      on spr.candidate_id = ir.candidate_id
     and spr.draftable = true
     and upper(btrim(coalesce(spr.line_type, ''))) = 'TIMESHEET_PAYMENT'
     and spr.timesheet_id = ir.timesheet_id
     and upper(btrim(coalesce(spr.pay_channel, ''))) = v_scope
     and spr.preview_row_id = coalesce(
       nullif(btrim(coalesce(ir.item_json->>'preview_row_id','')), ''),
       nullif(btrim(coalesce(ir.item_json->>'line_id','')), ''),
       case
         when nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '') is not null then
           case
             when coalesce(nullif(ir.item_json->>'is_partially_ready','')::boolean, false) = true
               then nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '') || ':01:ready'
             else nullif(btrim(coalesce(ir.item_json->>'timesheet_id','')), '')
           end
         when nullif(btrim(coalesce(ir.item_json->>'finance_case_id','')), '') is not null
          and nullif(btrim(coalesce(ir.item_json->>'line_type','')), '') is not null
           then 'finance:' || nullif(btrim(coalesce(ir.item_json->>'finance_case_id','')), '') || ':' || lower(nullif(btrim(coalesce(ir.item_json->>'line_type','')), ''))
         else null
       end
     )
    where ir.timesheet_id is not null
      and not (ir.timesheet_id = any(v_exclude_timesheet_ids))
      and (v_client_filter_single is null or ir.client_id = v_client_filter_single)
      and ir.case_is_blocked = false
      and ir.payment_amount_ex_vat > 0
  ),
  positive_component_rows as (
    select
      pr.candidate_id,
      pr.timesheet_id,
      pr.finance_case_id,
      pr.case_key,
      pr.cand_pay_method,
      pr.umbrella_id,
      pr.umb_vat_chargeable,
      nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '')::uuid as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'source_family_key','')), '') as source_family_key,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), '') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      nullif(btrim(coalesce(comp.comp_json->>'source_basis_fingerprint','')), '') as source_basis_fingerprint,
      nullif(upper(btrim(coalesce(comp.comp_json->>'bucket_code',''))), '') as preview_bucket_code,
      nullif(btrim(coalesce(comp.comp_json->>'label','')), '') as preview_label,
      upper(btrim(coalesce(comp.comp_json->>'component_semantics',''))) as preview_component_semantics,
      coalesce(nullif(comp.comp_json->>'is_rate_bearing','')::boolean, false) as preview_is_rate_bearing,
      coalesce(nullif(comp.comp_json->>'is_amount_led','')::boolean, false) as preview_is_amount_led,
      coalesce(nullif(comp.comp_json->>'is_actionable_resolution_row','')::boolean, false) as preview_is_actionable_resolution_row,
      coalesce(nullif(comp.comp_json->>'is_fixed_no_action_taxable_row','')::boolean, false) as preview_is_fixed_no_action_taxable_row,
      upper(btrim(coalesce(comp.comp_json->>'resolution_state',''))) as preview_resolution_state,
      upper(btrim(coalesce(comp.comp_json->>'saved_target_pay_method',''))) as saved_target_pay_method,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') is not null
          then nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '')::public.pay_finance_component_resolution_mode_enum
        when nullif(btrim(coalesce(comp.comp_json->>'resolution_mode','')), '') is not null
          then nullif(btrim(coalesce(comp.comp_json->>'resolution_mode','')), '')::public.pay_finance_component_resolution_mode_enum
        when nullif(btrim(coalesce(comp.comp_json->>'approved_resolution_mode','')), '') is not null
          then nullif(btrim(coalesce(comp.comp_json->>'approved_resolution_mode','')), '')::public.pay_finance_component_resolution_mode_enum
        when nullif(btrim(coalesce(comp.comp_json->>'approved_nonbucket_resolution_mode','')), '') is not null
          then nullif(btrim(coalesce(comp.comp_json->>'approved_nonbucket_resolution_mode','')), '')::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as saved_resolution_mode,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        when jsonb_typeof(comp.comp_json->'resolution_payload_json') = 'object' then comp.comp_json->'resolution_payload_json'
        else comp.comp_json->'suggested_resolution_payload_json'
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        when jsonb_typeof(comp.comp_json->'resolution_result_json') = 'object' then comp.comp_json->'resolution_result_json'
        else comp.comp_json->'suggested_resolution_result_json'
      end as saved_resolution_result_json,
      comp.comp_json->'suggested_resolution_payload_json' as suggested_resolution_payload_json,
      comp.comp_json->'suggested_resolution_result_json' as suggested_resolution_result_json,
      case
        when coalesce(comp.comp_json->>'source_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_pay_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_entitlement_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_entitlement_amount_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_entitlement_amount_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_reservation_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_reservation_amount_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as source_reservation_amount_ex_vat,
      (
        upper(btrim(coalesce(comp.comp_json->>'resolution_state',''))) = 'RESOLVED'
        or nullif(btrim(coalesce(comp.comp_json->>'approved_resolution_mode','')), '') is not null
        or nullif(btrim(coalesce(comp.comp_json->>'approved_nonbucket_resolution_mode','')), '') is not null
        or coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      ) as is_resolved_source_target_split,
      case
        when coalesce(comp.comp_json->>'preview_component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'preview_component_amount_ex_vat')::numeric, 2)::numeric(12,2)
        when coalesce(comp.comp_json->>'component_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'component_amount_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as preview_component_amount_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_pay_ex_vat')::numeric, 2)::numeric(12,2)
        else null::numeric(12,2)
      end as preview_target_amount_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as preview_target_rate,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as preview_source_units,
      case
        when coalesce(comp.comp_json->>'target_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_units')::numeric, 6)
        else null::numeric
      end as preview_target_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as preview_source_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as preview_source_charge_rate,
      case
        when coalesce(comp.comp_json->>'target_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_rate')::numeric, 2)
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as preview_target_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as preview_margin_delta_ex_vat
    from positive_rows pr
    cross join lateral jsonb_array_elements(coalesce(pr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where comp.comp_json is not null
      and jsonb_typeof(comp.comp_json) = 'object'
  ),
  raw_lines as (
    select
      pcr.candidate_id,
      pcr.finance_case_id,
      pcr.case_key,
      coalesce(nullif(btrim(coalesce(pcr.source_family_key,'')), ''), ('timesheet:' || pcr.timesheet_id::text)) as source_family_key,
      pcr.timesheet_id,
      upper(coalesce(pcr.source_pay_method,'')) as source_pay_method,
      upper(coalesce(pcr.cand_pay_method,'')) as cand_pay_method,
      pcr.umbrella_id,
      coalesce(pcr.umb_vat_chargeable, false) as umb_vat_chargeable,
      upper(coalesce(pcr.cand_pay_method,'')) as pay_channel,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL') then 'SEGMENT_DELTA'::text
        when pcr.component_key_type = 'ADJUSTMENT_CODE' then 'ADJUSTMENT_DELTA'::text
        when pcr.component_key_type = 'EXPENSE_CODE' and upper(coalesce(pcr.component_key_value,'')) = 'MILEAGE' then 'MILEAGE_DELTA'::text
        else 'EXPENSE_DELTA'::text
      end as item_type,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL')
          then coalesce(
            nullif(btrim(coalesce(pcr.source_basis_json->>'segment_key','')), ''),
            nullif(btrim(coalesce(pcr.source_basis_json->>'segment_id','')), '')
          )
        else null::text
      end as segment_key,
      case
        when pcr.component_key_type in ('TS_DAY','TS_TOTAL')
          then (
            'seg:' ||
            coalesce(
              nullif(btrim(coalesce(pcr.source_basis_json->>'segment_key','')), ''),
              nullif(btrim(coalesce(pcr.source_basis_json->>'segment_id','')), ''),
              ('ts:' || pcr.timesheet_id::text)
            ) ||
            ':' ||
            coalesce(nullif(upper(btrim(coalesce(pcr.preview_bucket_code, pcr.source_basis_json->>'bucket_code',''))), ''), 'TOTAL')
          )::text
        when pcr.component_key_type = 'ADDITIONAL_CODE'
          then case
            when upper(coalesce(pcr.component_key_value,'')) = 'TOTAL' then 'additional'::text
            else ('additional:' || upper(coalesce(pcr.component_key_value,'')))::text
          end
        when pcr.component_key_type = 'ADJUSTMENT_CODE'
          then ('adj:' || coalesce(nullif(btrim(coalesce(pcr.source_basis_json->>'adjustment_id','')), ''), coalesce(pcr.component_key_value, 'TOTAL')))::text
        when pcr.component_key_type = 'EXPENSE_CODE'
          then lower(coalesce(pcr.component_key_value, 'expense'))::text
        else coalesce(nullif(btrim(coalesce(pcr.source_basis_json->>'source_ref','')), ''), 'component')::text
      end as source_ref,
      round(
        coalesce(
          case
            when coalesce(pcr.is_resolved_source_target_split, false) = true
              then pcr.preview_target_amount_ex_vat
            else null::numeric
          end,
          pcr.preview_component_amount_ex_vat,
          pcr.preview_target_amount_ex_vat,
          0
        ),
        2
      ) as delta_ex,
      case
        when pcr.source_reservation_amount_ex_vat is not null then abs(round(pcr.source_reservation_amount_ex_vat, 2))::numeric(12,2)
        when pcr.source_entitlement_amount_ex_vat is not null then abs(round(pcr.source_entitlement_amount_ex_vat, 2))::numeric(12,2)
        when pcr.source_pay_ex_vat is not null then abs(round(pcr.source_pay_ex_vat, 2))::numeric(12,2)
        when coalesce(pcr.is_resolved_source_target_split, false) = false then abs(round(coalesce(pcr.preview_component_amount_ex_vat, pcr.preview_target_amount_ex_vat, 0), 2))::numeric(12,2)
        else null::numeric(12,2)
      end as source_entitlement_amount_ex_vat,
      pcr.classification,
      pcr.component_key_type,
      pcr.component_key_value,
      pcr.finance_component_id,
      coalesce(pcr.source_basis_json, '{}'::jsonb) as source_basis_json,
      pcr.source_basis_fingerprint,
      pcr.saved_target_pay_method,
      pcr.saved_resolution_mode,
      pcr.saved_resolution_payload_json,
      pcr.saved_resolution_result_json,
      pcr.suggested_resolution_payload_json,
      pcr.suggested_resolution_result_json,
      pcr.source_pay_ex_vat,
      pcr.source_reservation_amount_ex_vat,
      pcr.is_resolved_source_target_split,
      pcr.preview_component_amount_ex_vat,
      pcr.preview_target_amount_ex_vat,
      pcr.preview_target_rate,
      pcr.preview_source_units,
      pcr.preview_target_units,
      pcr.preview_source_rate,
      pcr.preview_source_charge_rate,
      pcr.preview_target_charge_rate,
      pcr.preview_source_charge_ex_vat,
      pcr.preview_target_charge_ex_vat,
      pcr.preview_target_margin_ex_vat,
      pcr.preview_margin_delta_ex_vat,
      pcr.preview_label,
      pcr.preview_bucket_code,
      pcr.preview_component_semantics,
      pcr.preview_is_rate_bearing,
      pcr.preview_is_amount_led,
      pcr.preview_is_actionable_resolution_row,
      pcr.preview_is_fixed_no_action_taxable_row,
      pcr.preview_resolution_state
    from positive_component_rows pcr
    where round(
      coalesce(
        case
          when coalesce(pcr.is_resolved_source_target_split, false) = true
            then pcr.preview_target_amount_ex_vat
          else null::numeric
        end,
        pcr.preview_component_amount_ex_vat,
        pcr.preview_target_amount_ex_vat,
        0
      ),
      2
    ) <> 0
  ),
  final_items as (
    select
      rl.candidate_id,
      rl.finance_case_id,
      rl.source_family_key,
      rl.timesheet_id,
      rl.segment_key,
      rl.source_ref,
      rl.item_type,
      coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel) as pay_channel,
      (
        rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
      ) as is_mismatch,
      rl.classification,
      rl.component_key_type,
      rl.component_key_value,
      rl.finance_component_id,
      rl.source_basis_json,
      rl.source_basis_fingerprint,
      rl.source_pay_method,
      rl.saved_target_pay_method,
      rl.saved_resolution_mode,
      case
        when jsonb_typeof(rl.saved_resolution_payload_json) = 'object' then rl.saved_resolution_payload_json
        else rl.suggested_resolution_payload_json
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(rl.saved_resolution_result_json) = 'object' then rl.saved_resolution_result_json
        else rl.suggested_resolution_result_json
      end as saved_resolution_result_json,
      rl.source_pay_ex_vat,
      rl.source_entitlement_amount_ex_vat,
      rl.source_reservation_amount_ex_vat,
      rl.is_resolved_source_target_split,
      rl.preview_target_rate,
      rl.preview_source_units,
      rl.preview_target_units,
      rl.preview_source_rate,
      rl.preview_source_charge_rate,
      rl.preview_target_charge_rate,
      rl.preview_source_charge_ex_vat,
      rl.preview_target_charge_ex_vat,
      rl.preview_target_margin_ex_vat,
      rl.preview_margin_delta_ex_vat,
      rl.preview_label,
      rl.preview_bucket_code,
      rl.preview_component_semantics,
      rl.preview_is_rate_bearing,
      rl.preview_is_amount_led,
      rl.preview_is_actionable_resolution_row,
      rl.preview_is_fixed_no_action_taxable_row,
      rl.preview_resolution_state,
      case
        when rl.source_entitlement_amount_ex_vat is not null then abs(round(rl.source_entitlement_amount_ex_vat, 2))::numeric(12,2)
        when coalesce(rl.is_resolved_source_target_split, false) = false then abs(round(coalesce(rl.delta_ex, 0), 2))::numeric(12,2)
        else null::numeric(12,2)
      end as frozen_source_amount,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_ex_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'ex')::numeric, 2)::numeric(12,2)
        else round(coalesce(rl.delta_ex, 0), 2)::numeric(12,2)
      end as amount_ex_vat,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'vat')::numeric, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as amount_vat,
      case
        when rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(rl.source_pay_method,'')) is distinct from upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel))
         and coalesce(coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_inc_vat','') ~ '^-?\d+(\.\d+)?$'
          then round((coalesce(rl.saved_resolution_result_json, rl.suggested_resolution_result_json)->>'target_amount_inc_vat')::numeric, 2)::numeric(12,2)
        when upper(coalesce(nullif(upper(coalesce(rl.saved_target_pay_method,'')), ''), rl.pay_channel)) = 'UMBRELLA'
         and rl.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(coalesce(rl.delta_ex,0),2), v_vat_rate_pct, rl.umb_vat_chargeable)->>'inc')::numeric, 2)::numeric(12,2)
        else round(coalesce(rl.delta_ex, 0), 2)::numeric(12,2)
      end as amount_inc_vat
    from raw_lines rl
  )
  select
    pbc.id,
    fi.item_type,
    fi.timesheet_id,
    fi.segment_key,
    fi.source_ref,
    case
      when fi.item_type = 'SEGMENT_DELTA' then 'Segment delta'
      when fi.item_type = 'MILEAGE_DELTA' then 'Mileage delta'
      when fi.item_type = 'ADJUSTMENT_DELTA' then 'Pay adjustment delta'
      when fi.source_ref = 'additional' or fi.source_ref like 'additional:%' then 'Additional pay delta'
      else 'Expense delta'
    end,
    round(fi.amount_ex_vat, 2),
    round(fi.amount_vat, 2),
    round(fi.amount_inc_vat, 2),
    fi.pay_channel,
    case when fi.pay_channel = 'UMBRELLA' then c.umbrella_id else null end,
    fi.is_mismatch,
    fi.finance_case_id,
    fi.finance_component_id,
    jsonb_build_object(
      'finance_case_id', case when fi.finance_case_id is null then null else fi.finance_case_id::text end,
      'timesheet_id', case when fi.timesheet_id is null then null else fi.timesheet_id::text end,
      'segment_key', fi.segment_key,
      'source_ref', fi.source_ref,
      'source_family_key', fi.source_family_key,
      'component_key_type', fi.component_key_type,
      'component_key_value', fi.component_key_value,
      'classification', fi.classification::text,
      'source_pay_method', fi.source_pay_method,
      'target_pay_method', fi.pay_channel,
      'source_pay_ex_vat', fi.source_pay_ex_vat,
      'source_entitlement_amount_ex_vat', fi.source_entitlement_amount_ex_vat,
      'source_reservation_amount_ex_vat', coalesce(fi.source_reservation_amount_ex_vat, fi.source_entitlement_amount_ex_vat),
      'target_pay_ex_vat', round(fi.amount_ex_vat, 2),
      'source_basis_json', fi.source_basis_json,
      'source_basis_fingerprint', fi.source_basis_fingerprint,
      'label', fi.preview_label,
      'bucket_code', fi.preview_bucket_code,
      'component_semantics', fi.preview_component_semantics,
      'is_rate_bearing', fi.preview_is_rate_bearing,
      'is_amount_led', fi.preview_is_amount_led,
      'is_actionable_resolution_row', fi.preview_is_actionable_resolution_row,
      'is_fixed_no_action_taxable_row', fi.preview_is_fixed_no_action_taxable_row,
      'resolution_state', fi.preview_resolution_state,
      'saved_target_pay_method', fi.saved_target_pay_method,
      'saved_resolution_mode', case when fi.saved_resolution_mode is null then null else fi.saved_resolution_mode::text end,
      'saved_resolution_payload_json', fi.saved_resolution_payload_json,
      'saved_resolution_result_json', fi.saved_resolution_result_json,
      'source_units', fi.preview_source_units,
      'target_units', fi.preview_target_units,
      'source_rate', fi.preview_source_rate,
      'source_charge_rate', fi.preview_source_charge_rate,
      'target_charge_rate', fi.preview_target_charge_rate,
      'target_rate', fi.preview_target_rate,
      'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
      'source_margin_ex_vat', case when fi.preview_source_charge_ex_vat is null or fi.source_pay_ex_vat is null then null else round(fi.preview_source_charge_ex_vat - fi.source_pay_ex_vat, 2) end,
      'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
      'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
      'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat,
      'frozen_source_amount', round(fi.frozen_source_amount, 2),
      'frozen_target_amount_ex_vat', round(fi.amount_ex_vat, 2),
      'frozen_target_amount_vat', round(fi.amount_vat, 2),
      'frozen_target_amount_inc_vat', round(fi.amount_inc_vat, 2)
    ),
    fi.component_key_type,
    fi.component_key_value,
    fi.classification,
    fi.source_basis_json,
    fi.source_pay_method,
    coalesce(fi.saved_target_pay_method, fi.pay_channel),
    coalesce(
      fi.saved_resolution_mode,
      case
        when fi.is_mismatch then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end
    ),
    case
      when jsonb_typeof(fi.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
        fi.saved_resolution_payload_json
        || jsonb_build_object(
          'target_pay_method', fi.pay_channel,
          'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
          'bucket_code', fi.preview_bucket_code,
          'source_basis_fingerprint', fi.source_basis_fingerprint,
          'source_units', fi.preview_source_units,
          'source_rate', fi.preview_source_rate,
          'source_charge_rate', fi.preview_source_charge_rate,
          'target_charge_rate', fi.preview_target_charge_rate,
          'component_semantics', fi.preview_component_semantics,
          'is_rate_bearing_row', fi.preview_is_rate_bearing,
          'is_amount_led_row', fi.preview_is_amount_led,
          'suggested_target_rate', fi.preview_target_rate
        )
      )
      when fi.is_mismatch then jsonb_strip_nulls(jsonb_build_object(
        'target_pay_method', fi.pay_channel,
        'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
        'bucket_code', fi.preview_bucket_code,
        'source_basis_fingerprint', fi.source_basis_fingerprint,
        'source_units', fi.preview_source_units,
        'source_rate', fi.preview_source_rate,
        'source_charge_rate', fi.preview_source_charge_rate,
        'target_charge_rate', fi.preview_target_charge_rate,
        'component_semantics', fi.preview_component_semantics,
        'is_rate_bearing_row', fi.preview_is_rate_bearing,
        'is_amount_led_row', fi.preview_is_amount_led,
        'suggested_target_rate', fi.preview_target_rate
      ))
      else fi.saved_resolution_payload_json
    end,
    case
      when jsonb_typeof(fi.saved_resolution_result_json) = 'object' then jsonb_strip_nulls(
        fi.saved_resolution_result_json
        || jsonb_build_object(
          'target_pay_method', fi.pay_channel,
          'target_amount_ex_vat', round(fi.amount_ex_vat, 2),
          'target_amount_vat', round(fi.amount_vat, 2),
          'target_amount_inc_vat', round(fi.amount_inc_vat, 2),
          'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
          'bucket_code', fi.preview_bucket_code,
          'source_basis_fingerprint', fi.source_basis_fingerprint,
          'component_semantics', fi.preview_component_semantics,
          'is_rate_bearing_row', fi.preview_is_rate_bearing,
          'is_amount_led_row', fi.preview_is_amount_led,
          'replacement_rate', fi.preview_target_rate,
          'source_rate', fi.preview_source_rate,
          'source_charge_rate', fi.preview_source_charge_rate,
          'target_charge_rate', fi.preview_target_charge_rate,
          'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
          'source_margin_ex_vat', case when fi.preview_source_charge_ex_vat is null or fi.source_pay_ex_vat is null then null else round(fi.preview_source_charge_ex_vat - fi.source_pay_ex_vat, 2) end,
          'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
          'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
          'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat
        )
      )
      when fi.is_mismatch then jsonb_strip_nulls(jsonb_build_object(
        'target_pay_method', fi.pay_channel,
        'target_amount_ex_vat', round(fi.amount_ex_vat, 2),
        'target_amount_vat', round(fi.amount_vat, 2),
        'target_amount_inc_vat', round(fi.amount_inc_vat, 2),
        'target_units', coalesce(fi.preview_target_units, fi.preview_source_units),
        'bucket_code', fi.preview_bucket_code,
        'source_basis_fingerprint', fi.source_basis_fingerprint,
        'component_semantics', fi.preview_component_semantics,
        'is_rate_bearing_row', fi.preview_is_rate_bearing,
        'is_amount_led_row', fi.preview_is_amount_led,
        'replacement_rate', fi.preview_target_rate,
        'source_rate', fi.preview_source_rate,
        'source_charge_rate', fi.preview_source_charge_rate,
        'target_charge_rate', fi.preview_target_charge_rate,
        'source_charge_ex_vat', fi.preview_source_charge_ex_vat,
        'source_margin_ex_vat', case when fi.preview_source_charge_ex_vat is null or fi.source_pay_ex_vat is null then null else round(fi.preview_source_charge_ex_vat - fi.source_pay_ex_vat, 2) end,
        'target_charge_ex_vat', fi.preview_target_charge_ex_vat,
        'target_margin_ex_vat', fi.preview_target_margin_ex_vat,
        'margin_delta_ex_vat', fi.preview_margin_delta_ex_vat
      ))
      else fi.saved_resolution_result_json
    end,
    round(fi.frozen_source_amount, 2),
    round(fi.amount_ex_vat, 2),
    round(fi.amount_vat, 2),
    round(fi.amount_inc_vat, 2),
    case
      when p_operation_id is null then null::text
      else p_operation_id::text
        || ':earning:' || v_batch_id::text
        || ':' || coalesce(operation_scope.id::text, 'no_scope')
        || ':' || fi.candidate_id::text
        || ':' || fi.item_type
        || ':' || coalesce(fi.timesheet_id::text, 'no_timesheet')
        || ':' || coalesce(fi.segment_key, 'no_segment')
        || ':' || coalesce(fi.source_ref, 'no_source_ref')
        || ':' || coalesce(fi.finance_component_id::text, 'no_component')
    end as operation_source_key
  from final_items fi
  join public.pay_batch_candidates pbc
    on pbc.pay_batch_id = v_batch_id
   and pbc.candidate_id = fi.candidate_id
  left join public.banking_pay_operation_candidate_scope as operation_scope
    on p_operation_id is not null
   and operation_scope.operation_id = p_operation_id
   and operation_scope.pay_batch_id = v_batch_id
   and operation_scope.candidate_id = fi.candidate_id
   and operation_scope.pay_channel = fi.pay_channel
  join pg_temp.tmp_pay_build_candidates_ctx c
    on c.id = fi.candidate_id
  on conflict (pay_batch_candidate_id, operation_source_key) where operation_source_key is not null do nothing;
  GET DIAGNOSTICS v_rows_ins_items = ROW_COUNT;

  ---------------------------------------------------------------------------
  -- Manual adjustment carry-forward rows are not timesheet entitlement rows.
  -- They are inserted as separate, stable manual adjustment payment/deduction
  -- lines and only then reserved against the source carry-forward record.
  ---------------------------------------------------------------------------
  v_stage := 'STAGE_12_MANUAL_ADJUSTMENT_CARRY_FORWARD_ITEMS';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_build_carry_forward_preview_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_build_carry_forward_preview_rows ON COMMIT DROP AS
  WITH all_candidates AS (
    SELECT t.cand
    FROM pg_temp.tmp_pay_build_preview_candidates AS t
  ),
  candidate_rows AS (
    SELECT
      NULLIF(BTRIM(COALESCE(all_candidates.cand->>'candidate_id','')), '')::uuid AS candidate_id,
      UPPER(BTRIM(COALESCE(all_candidates.cand->>'current_pay_method',''))) AS cand_pay_method,
      NULLIF(BTRIM(COALESCE(all_candidates.cand->>'umbrella_id','')), '')::uuid AS umbrella_id,
      COALESCE(all_candidates.cand->'itemisation', '[]'::jsonb) AS itemisation
    FROM all_candidates
    WHERE NULLIF(BTRIM(COALESCE(all_candidates.cand->>'candidate_id','')), '') IS NOT NULL
      AND (all_candidates.cand->>'candidate_id')::uuid = ANY(v_candidate_ids)
  ),
  item_rows AS (
    SELECT
      candidate_rows.candidate_id,
      candidate_rows.cand_pay_method,
      candidate_rows.umbrella_id AS candidate_umbrella_id,
      item_values.item_json,
      NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '')::uuid AS manual_adjustment_carry_forward_id,
      COALESCE(
        NULLIF(BTRIM(COALESCE(item_values.item_json->>'source_ref', '')), ''),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '') IS NULL THEN NULL
          ELSE 'carry_forward:' || NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '')
        END
      ) AS source_ref,
      COALESCE(
        NULLIF(BTRIM(COALESCE(item_values.item_json->>'operation_source_key', '')), ''),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '') IS NULL THEN NULL
          ELSE 'carry_forward:' || NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '')
        END
      ) AS operation_source_key,
      UPPER(BTRIM(COALESCE(item_values.item_json->>'pay_channel', candidate_rows.cand_pay_method, ''))) AS pay_channel,
      COALESCE(
        NULLIF(BTRIM(COALESCE(item_values.item_json->>'umbrella_id', '')), '')::uuid,
        candidate_rows.umbrella_id
      ) AS umbrella_id,
      NULLIF(BTRIM(COALESCE(item_values.item_json->>'timesheet_id', '')), '')::uuid AS timesheet_id,
      NULLIF(BTRIM(COALESCE(item_values.item_json->>'client_id', '')), '')::uuid AS client_id,
      COALESCE(
        NULLIF(BTRIM(COALESCE(item_values.item_json->>'description', '')), ''),
        NULLIF(BTRIM(COALESCE(item_values.item_json->>'adjustment_comment', '')), ''),
        'Manual adjustment carry-forward'
      ) AS description,
      CASE
        WHEN COALESCE(item_values.item_json->>'payment_amount_ex_vat', item_values.item_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(item_values.item_json->>'payment_amount_ex_vat', item_values.item_json->>'amount_ex_vat')::numeric, 2)::numeric(12,2)
        ELSE 0::numeric(12,2)
      END AS amount_ex_vat,
      CASE
        WHEN COALESCE(item_values.item_json->>'payment_amount_vat', item_values.item_json->>'amount_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(item_values.item_json->>'payment_amount_vat', item_values.item_json->>'amount_vat')::numeric, 2)::numeric(12,2)
        ELSE 0::numeric(12,2)
      END AS amount_vat,
      CASE
        WHEN COALESCE(item_values.item_json->>'payment_amount_inc_vat', item_values.item_json->>'amount_inc_vat', item_values.item_json->>'amount_display', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(item_values.item_json->>'payment_amount_inc_vat', item_values.item_json->>'amount_inc_vat', item_values.item_json->>'amount_display')::numeric, 2)::numeric(12,2)
        ELSE 0::numeric(12,2)
      END AS amount_inc_vat,
      NULLIF(BTRIM(COALESCE(item_values.item_json->>'paye_treatment', '')), '') AS paye_treatment,
      NULLIF(BTRIM(COALESCE(item_values.item_json->>'adjustment_direction', '')), '') AS adjustment_direction,
      CASE
        WHEN jsonb_typeof(item_values.item_json->'tax_treatment_json') = 'object' THEN item_values.item_json->'tax_treatment_json'
        ELSE '{}'::jsonb
      END AS tax_treatment_json,
      CASE
        WHEN jsonb_typeof(item_values.item_json->'source_snapshot_json') = 'object' THEN item_values.item_json->'source_snapshot_json'
        ELSE '{}'::jsonb
      END AS source_snapshot_json
    FROM candidate_rows
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(candidate_rows.itemisation, '[]'::jsonb)) AS item_values(item_json)
    WHERE jsonb_typeof(item_values.item_json) = 'object'
      AND UPPER(COALESCE(item_values.item_json->>'line_type', '')) = 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
      AND NULLIF(BTRIM(COALESCE(item_values.item_json->>'manual_adjustment_carry_forward_id', '')), '') IS NOT NULL
  )
  SELECT
    item_rows.*
  FROM item_rows
  JOIN pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview
    ON selected_preview.candidate_id = item_rows.candidate_id
   AND selected_preview.draftable = true
   AND UPPER(BTRIM(COALESCE(selected_preview.line_type, ''))) = 'MANUAL_ADJUSTMENT_CARRY_FORWARD'
   AND selected_preview.preview_row_id = item_rows.operation_source_key
   AND UPPER(BTRIM(COALESCE(selected_preview.pay_channel, ''))) = item_rows.pay_channel
  WHERE item_rows.manual_adjustment_carry_forward_id IS NOT NULL
    AND item_rows.operation_source_key = 'carry_forward:' || item_rows.manual_adjustment_carry_forward_id::text
    AND item_rows.pay_channel IN ('PAYE', 'UMBRELLA')
    AND item_rows.pay_channel = v_scope
    AND ROUND(COALESCE(item_rows.amount_inc_vat, 0), 2) <> 0;

  INSERT INTO public.pay_batch_items(
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    operation_source_key
  )
  SELECT
    pay_batch_candidate.id AS pay_batch_candidate_id,
    CASE
      WHEN carry_forward_rows.amount_inc_vat < 0 THEN 'MANUAL_DEBT_RECOVERY'
      ELSE 'MANUAL_CREDIT_PAYOUT'
    END AS item_type,
    carry_forward_rows.timesheet_id,
    NULL::text AS segment_key,
    carry_forward_rows.source_ref,
    carry_forward_rows.description,
    carry_forward_rows.amount_ex_vat,
    carry_forward_rows.amount_vat,
    carry_forward_rows.amount_inc_vat,
    carry_forward_rows.pay_channel,
    CASE WHEN carry_forward_rows.pay_channel = 'UMBRELLA' THEN carry_forward_rows.umbrella_id ELSE NULL::uuid END AS umbrella_id,
    false AS is_mismatch,
    NULL::uuid AS finance_case_id,
    NULL::uuid AS finance_component_id,
    jsonb_strip_nulls(
      COALESCE(carry_forward_rows.source_snapshot_json, '{}'::jsonb)
      || jsonb_build_object(
        'manual_adjustment_carry_forward_id', carry_forward_rows.manual_adjustment_carry_forward_id::text,
        'source_ref', carry_forward_rows.source_ref,
        'operation_source_key', carry_forward_rows.operation_source_key,
        'source_operation_source_key', carry_forward_rows.item_json->>'source_operation_source_key',
        'source_pay_batch_id', carry_forward_rows.item_json->>'source_pay_batch_id',
        'source_pay_batch_item_id', carry_forward_rows.item_json->>'source_pay_batch_item_id',
        'source_pay_bank_transfer_id', carry_forward_rows.item_json->>'source_pay_bank_transfer_id',
        'adjustment_direction', carry_forward_rows.adjustment_direction,
        'amount_basis', carry_forward_rows.item_json->>'amount_basis',
        'tax_treatment_json', carry_forward_rows.tax_treatment_json
      )
    ) AS frozen_component_snapshot_json,
    'MANUAL_CARRY_FORWARD' AS frozen_component_key_type,
    carry_forward_rows.manual_adjustment_carry_forward_id::text AS frozen_component_key_value,
    CASE
      WHEN UPPER(COALESCE(carry_forward_rows.paye_treatment, '')) IN ('NET_ADD', 'NET_DEDUCT')
        THEN 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
      WHEN UPPER(COALESCE(carry_forward_rows.tax_treatment_json->>'taxability', carry_forward_rows.item_json->>'taxability', '')) = 'NON_TAXABLE'
        THEN 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
      ELSE 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    END AS frozen_component_classification,
    jsonb_strip_nulls(
      COALESCE(carry_forward_rows.source_snapshot_json, '{}'::jsonb)
      || jsonb_build_object(
        'source_kind', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
        'manual_adjustment_carry_forward_id', carry_forward_rows.manual_adjustment_carry_forward_id::text,
        'source_ref', carry_forward_rows.source_ref,
        'operation_source_key', carry_forward_rows.operation_source_key,
        'source_operation_source_key', carry_forward_rows.item_json->>'source_operation_source_key',
        'pay_channel', carry_forward_rows.pay_channel,
        'paye_treatment', carry_forward_rows.paye_treatment,
        'tax_treatment_json', carry_forward_rows.tax_treatment_json,
        'signed_amount_ex_vat', carry_forward_rows.amount_ex_vat,
        'signed_amount_vat', carry_forward_rows.amount_vat,
        'signed_amount_inc_vat', carry_forward_rows.amount_inc_vat,
        'signed_amount_convention', 'SIGNED_AMOUNTS'
      )
    ) AS frozen_source_basis_json,
    carry_forward_rows.pay_channel AS frozen_source_pay_method,
    carry_forward_rows.pay_channel AS frozen_target_pay_method,
    NULL::public.pay_finance_component_resolution_mode_enum AS frozen_resolution_mode,
    carry_forward_rows.item_json AS frozen_resolution_payload_json,
    jsonb_strip_nulls(jsonb_build_object(
      'resolution_source', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
      'manual_adjustment_carry_forward_id', carry_forward_rows.manual_adjustment_carry_forward_id::text,
      'description', carry_forward_rows.description,
      'signed_amount_ex_vat', carry_forward_rows.amount_ex_vat,
      'signed_amount_vat', carry_forward_rows.amount_vat,
      'signed_amount_inc_vat', carry_forward_rows.amount_inc_vat,
      'signed_amount_convention', 'SIGNED_AMOUNTS'
    )) AS frozen_resolution_result_json,
    carry_forward_rows.amount_ex_vat AS frozen_source_amount,
    carry_forward_rows.amount_ex_vat AS frozen_target_amount_ex_vat,
    carry_forward_rows.amount_vat AS frozen_target_amount_vat,
    carry_forward_rows.amount_inc_vat AS frozen_target_amount_inc_vat,
    carry_forward_rows.operation_source_key
  FROM pg_temp.tmp_pay_build_carry_forward_preview_rows AS carry_forward_rows
  JOIN public.pay_batch_candidates AS pay_batch_candidate
    ON pay_batch_candidate.pay_batch_id = v_batch_id
   AND pay_batch_candidate.candidate_id = carry_forward_rows.candidate_id
  ON CONFLICT (pay_batch_candidate_id, operation_source_key) WHERE operation_source_key IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS v_rows_ins_carry_forward_items = ROW_COUNT;
  v_rows_ins_items := COALESCE(v_rows_ins_items, 0) + COALESCE(v_rows_ins_carry_forward_items, 0);

  FOR v_carry_forward_reserve_result IN
    SELECT public._pay_manual_adjustment_carry_forward_reserve_for_batch_item(
      carry_forward_rows.manual_adjustment_carry_forward_id,
      v_batch_id,
      target_items.id,
      target_items.operation_source_key,
      p_actor_user_id
    )
    FROM pg_temp.tmp_pay_build_carry_forward_preview_rows AS carry_forward_rows
    JOIN public.pay_batch_candidates AS pay_batch_candidate
      ON pay_batch_candidate.pay_batch_id = v_batch_id
     AND pay_batch_candidate.candidate_id = carry_forward_rows.candidate_id
    JOIN public.pay_batch_items AS target_items
      ON target_items.pay_batch_candidate_id = pay_batch_candidate.id
     AND target_items.operation_source_key = carry_forward_rows.operation_source_key
     AND COALESCE(target_items.is_voided, false) = false
  LOOP
    IF COALESCE((v_carry_forward_reserve_result->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'MANUAL_ADJUSTMENT_CARRY_FORWARD_RESERVATION_FAILED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'MANUAL_ADJUSTMENT_CARRY_FORWARD_RESERVATION_FAILED',
                'pay_batch_id', v_batch_id,
                'reserve_result', v_carry_forward_reserve_result
              )::text;
    END IF;
  END LOOP;

  IF p_operation_id IS NOT NULL THEN
    UPDATE public.pay_batch_items AS inserted_item
    SET
      operation_source_key = p_operation_id::text
        || ':earning:' || v_batch_id::text
        || ':' || coalesce((
          select operation_scope.id::text
          from public.banking_pay_operation_candidate_scope as operation_scope
          where operation_scope.operation_id = p_operation_id
            and operation_scope.pay_batch_id = v_batch_id
            and operation_scope.candidate_id = batch_candidate.candidate_id
            and operation_scope.pay_channel = inserted_item.pay_channel
          order by operation_scope.id
          limit 1
        ), 'no_scope')
        || ':' || batch_candidate.candidate_id::text
        || ':' || inserted_item.item_type
        || ':' || coalesce(inserted_item.timesheet_id::text, 'no_timesheet')
        || ':' || coalesce(inserted_item.segment_key, 'no_segment')
        || ':' || coalesce(inserted_item.source_ref, 'no_source_ref')
        || ':' || coalesce(inserted_item.finance_component_id::text, 'no_component'),
      updated_at = now()
    FROM public.pay_batch_candidates AS batch_candidate
    WHERE batch_candidate.id = inserted_item.pay_batch_candidate_id
      AND batch_candidate.pay_batch_id = v_batch_id
      AND batch_candidate.candidate_id = ANY(v_candidate_ids)
      AND inserted_item.operation_source_key IS NULL
      AND inserted_item.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA');
  END IF;

  v_stage := 'STAGE_12B_ENFORCE_ACTIVE_RESERVATION_AVAILABILITY';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_build_reservation_availability_actions;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_build_reservation_availability_actions ON COMMIT DROP AS
  WITH scoped_items AS (
    SELECT
      pbi.id AS pay_batch_item_id,
      pbc.candidate_id,
      pbi.pay_channel,
      spr_match.preview_row_id,
      spr_match.preview_amount_ex_vat,
      pbi.timesheet_id,
      pbi.item_type,
      pbi.amount_ex_vat AS requested_target_amount_ex_vat,
      pbi.amount_vat AS requested_target_amount_vat,
      pbi.amount_inc_vat AS requested_target_amount_inc_vat,
      pbi.frozen_source_amount,
      pbi.created_at,
      upper(nullif(btrim(coalesce(ec.key_type, '')), '')) AS key_type,
      nullif(btrim(coalesce(ec.key_value, '')), '') AS key_value,
      round(abs(coalesce(ec.source_amount_ex_vat, 0)), 2)::numeric(12,2) AS requested_source_amount_ex_vat
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN LATERAL public._pay_batch_item_economic_components(NULL::uuid, ARRAY[pbi.id]::uuid[]) AS ec
      ON true
    LEFT JOIN LATERAL (
      SELECT
        spr.preview_row_id,
        spr.preview_amount_ex_vat
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr
      WHERE spr.candidate_id = pbc.candidate_id
        AND spr.timesheet_id = pbi.timesheet_id
        AND upper(btrim(coalesce(spr.pay_channel, ''))) = upper(btrim(coalesce(pbi.pay_channel, '')))
        AND upper(btrim(coalesce(spr.line_type, ''))) = 'TIMESHEET_PAYMENT'
      ORDER BY spr.preview_row_id
      LIMIT 1
    ) AS spr_match ON true
    WHERE pbc.pay_batch_id = v_batch_id
      AND pbc.candidate_id = ANY(v_candidate_ids)
      AND pbi.timesheet_id IS NOT NULL
      AND coalesce(pbi.is_voided, false) = false
      AND pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
      AND pbi.reservation_id IS NULL
  ),
  valid_scoped_items AS (
    SELECT *
    FROM scoped_items
    WHERE key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
      AND key_value IS NOT NULL
      AND btrim(key_value) <> ''
      AND NOT (key_type = 'TS_DAY' AND key_value !~ '^\d{4}-\d{2}-\d{2}$')
      AND requested_source_amount_ex_vat > 0
  ),
  ts_ids_arr AS (
    SELECT coalesce(array_agg(DISTINCT timesheet_id), ARRAY[]::uuid[]) AS timesheet_ids
    FROM valid_scoped_items
    WHERE timesheet_id IS NOT NULL
  ),
  outstanding_rows AS (
    SELECT
      oc.timesheet_id,
      upper(nullif(btrim(coalesce(oc.key_type, '')), '')) AS key_type,
      nullif(btrim(coalesce(oc.key_value, '')), '') AS key_value,
      round(coalesce(oc.outstanding_ex_vat, 0), 2)::numeric(12,2) AS outstanding_ex_vat
    FROM public._pay_outstanding_components((SELECT timesheet_ids FROM ts_ids_arr)) AS oc
    WHERE oc.timesheet_id IS NOT NULL
      AND oc.key_type IS NOT NULL
      AND oc.key_value IS NOT NULL
  ),
  current_scope_key_totals AS (
    SELECT
      vsi.timesheet_id,
      vsi.key_type,
      vsi.key_value,
      round(sum(coalesce(vsi.requested_source_amount_ex_vat, 0)), 2)::numeric(12,2) AS current_scope_source_amount_ex_vat
    FROM valid_scoped_items AS vsi
    GROUP BY vsi.timesheet_id, vsi.key_type, vsi.key_value
  ),
  allocation_base AS (
    SELECT
      vsi.*,
      round(greatest(coalesce(orow.outstanding_ex_vat, 0) + coalesce(ckt.current_scope_source_amount_ex_vat, 0), 0), 2)::numeric(12,2) AS available_for_scope_ex_vat,
      coalesce(
        sum(vsi.requested_source_amount_ex_vat) OVER (
          PARTITION BY vsi.timesheet_id, vsi.key_type, vsi.key_value
          ORDER BY vsi.created_at NULLS LAST, vsi.pay_batch_item_id
          ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
        ),
        0
      )::numeric(12,2) AS prior_requested_source_amount_ex_vat
    FROM valid_scoped_items AS vsi
    LEFT JOIN current_scope_key_totals AS ckt
      ON ckt.timesheet_id = vsi.timesheet_id
     AND ckt.key_type = vsi.key_type
     AND ckt.key_value = vsi.key_value
    LEFT JOIN outstanding_rows AS orow
      ON orow.timesheet_id = vsi.timesheet_id
     AND orow.key_type = vsi.key_type
     AND orow.key_value = vsi.key_value
  ),
  allocated AS (
    SELECT
      ab.*,
      round(
        least(
          coalesce(ab.requested_source_amount_ex_vat, 0),
          greatest(coalesce(ab.available_for_scope_ex_vat, 0) - coalesce(ab.prior_requested_source_amount_ex_vat, 0), 0)
        ),
        2
      )::numeric(12,2) AS allowed_source_amount_ex_vat
    FROM allocation_base AS ab
  ),
  actions AS (
    SELECT
      allocated.*,
      CASE
        WHEN coalesce(allocated.allowed_source_amount_ex_vat, 0) <= 0.005 THEN 'SKIP_ALREADY_RESERVED'
        ELSE 'CLIP_TO_RESIDUAL'
      END AS availability_action,
      CASE
        WHEN coalesce(allocated.allowed_source_amount_ex_vat, 0) <= 0.005 THEN 'Some payments were not added because they are already reserved in another draft batch.'
        ELSE 'Payment component was reduced to the residual amount available after other active reservations.'
      END AS availability_message,
      CASE
        WHEN coalesce(allocated.requested_source_amount_ex_vat, 0) > 0
          THEN greatest(least(coalesce(allocated.allowed_source_amount_ex_vat, 0) / allocated.requested_source_amount_ex_vat, 1), 0)
        ELSE 0::numeric
      END AS availability_ratio
    FROM allocated
    WHERE round(coalesce(allocated.allowed_source_amount_ex_vat, 0), 2)
            < round(coalesce(allocated.requested_source_amount_ex_vat, 0), 2) - 0.005
  )
  SELECT
    actions.pay_batch_item_id,
    actions.candidate_id,
    actions.preview_row_id,
    actions.timesheet_id,
    actions.item_type,
    actions.key_type,
    actions.key_value,
    actions.requested_source_amount_ex_vat,
    round(greatest(coalesce(actions.allowed_source_amount_ex_vat, 0), 0), 2)::numeric(12,2) AS allowed_source_amount_ex_vat,
    round(coalesce(actions.requested_target_amount_ex_vat, 0), 2)::numeric(12,2) AS requested_target_amount_ex_vat,
    round(coalesce(actions.requested_target_amount_vat, 0), 2)::numeric(12,2) AS requested_target_amount_vat,
    round(coalesce(actions.requested_target_amount_inc_vat, 0), 2)::numeric(12,2) AS requested_target_amount_inc_vat,
    round(coalesce(actions.requested_target_amount_ex_vat, 0) * coalesce(actions.availability_ratio, 0), 2)::numeric(12,2) AS allowed_target_amount_ex_vat,
    round(coalesce(actions.requested_target_amount_vat, 0) * coalesce(actions.availability_ratio, 0), 2)::numeric(12,2) AS allowed_target_amount_vat,
    round(coalesce(actions.requested_target_amount_inc_vat, 0) * coalesce(actions.availability_ratio, 0), 2)::numeric(12,2) AS allowed_target_amount_inc_vat,
    actions.availability_action,
    actions.availability_message
  FROM actions;

  INSERT INTO pg_temp.tmp_pay_build_reservation_availability_report (
    pay_batch_item_id,
    candidate_id,
    preview_row_id,
    timesheet_id,
    item_type,
    key_type,
    key_value,
    requested_source_amount_ex_vat,
    allowed_source_amount_ex_vat,
    requested_target_amount_ex_vat,
    allowed_target_amount_ex_vat,
    availability_action,
    message
  )
  SELECT
    act.pay_batch_item_id,
    act.candidate_id,
    act.preview_row_id,
    act.timesheet_id,
    act.item_type,
    act.key_type,
    act.key_value,
    act.requested_source_amount_ex_vat,
    act.allowed_source_amount_ex_vat,
    act.requested_target_amount_ex_vat,
    act.allowed_target_amount_ex_vat,
    act.availability_action,
    act.availability_message
  FROM pg_temp.tmp_pay_build_reservation_availability_actions AS act;

  SELECT count(*)::integer
  INTO v_reservation_clipped_item_rows
  FROM pg_temp.tmp_pay_build_reservation_availability_actions AS act
  WHERE act.availability_action = 'CLIP_TO_RESIDUAL';

  UPDATE public.pay_batch_items AS pbi_update
  SET
    amount_ex_vat = act.allowed_target_amount_ex_vat,
    amount_vat = act.allowed_target_amount_vat,
    amount_inc_vat = act.allowed_target_amount_inc_vat,
    frozen_source_amount = act.allowed_source_amount_ex_vat,
    frozen_target_amount_ex_vat = act.allowed_target_amount_ex_vat,
    frozen_target_amount_vat = act.allowed_target_amount_vat,
    frozen_target_amount_inc_vat = act.allowed_target_amount_inc_vat,
    frozen_component_snapshot_json = jsonb_strip_nulls(
      coalesce(pbi_update.frozen_component_snapshot_json, '{}'::jsonb)
      || jsonb_build_object(
        'draft_reservation_availability_applied', true,
        'draft_reservation_availability_action', act.availability_action,
        'draft_reservation_original_source_amount_ex_vat', act.requested_source_amount_ex_vat,
        'draft_reservation_allowed_source_amount_ex_vat', act.allowed_source_amount_ex_vat,
        'draft_reservation_original_target_amount_ex_vat', act.requested_target_amount_ex_vat,
        'draft_reservation_allowed_target_amount_ex_vat', act.allowed_target_amount_ex_vat,
        'source_reservation_amount_ex_vat', act.allowed_source_amount_ex_vat,
        'source_entitlement_amount_ex_vat', act.allowed_source_amount_ex_vat,
        'target_pay_ex_vat', act.allowed_target_amount_ex_vat,
        'frozen_source_amount', act.allowed_source_amount_ex_vat,
        'frozen_target_amount_ex_vat', act.allowed_target_amount_ex_vat,
        'frozen_target_amount_vat', act.allowed_target_amount_vat,
        'frozen_target_amount_inc_vat', act.allowed_target_amount_inc_vat
      )
    ),
    frozen_resolution_payload_json = CASE
      WHEN jsonb_typeof(pbi_update.frozen_resolution_payload_json) = 'object'
        THEN jsonb_strip_nulls(pbi_update.frozen_resolution_payload_json || jsonb_build_object('draft_reservation_availability_applied', true, 'draft_reservation_availability_action', act.availability_action))
      ELSE pbi_update.frozen_resolution_payload_json
    END,
    frozen_resolution_result_json = CASE
      WHEN jsonb_typeof(pbi_update.frozen_resolution_result_json) = 'object'
        THEN jsonb_strip_nulls(
          pbi_update.frozen_resolution_result_json
          || jsonb_build_object(
            'draft_reservation_availability_applied', true,
            'draft_reservation_availability_action', act.availability_action,
            'target_amount_ex_vat', act.allowed_target_amount_ex_vat,
            'target_amount_vat', act.allowed_target_amount_vat,
            'target_amount_inc_vat', act.allowed_target_amount_inc_vat
          )
        )
      ELSE pbi_update.frozen_resolution_result_json
    END,
    updated_at = now()
  FROM pg_temp.tmp_pay_build_reservation_availability_actions AS act
  WHERE pbi_update.id = act.pay_batch_item_id
    AND act.availability_action = 'CLIP_TO_RESIDUAL';

  DELETE FROM public.pay_batch_item_breakdowns AS breakdown_delete
  USING pg_temp.tmp_pay_build_reservation_availability_actions AS act
  WHERE breakdown_delete.pay_batch_item_id = act.pay_batch_item_id
    AND act.availability_action = 'SKIP_ALREADY_RESERVED';

  DELETE FROM public.pay_batch_items AS pbi_delete
  USING pg_temp.tmp_pay_build_reservation_availability_actions AS act
  WHERE pbi_delete.id = act.pay_batch_item_id
    AND act.availability_action = 'SKIP_ALREADY_RESERVED';

  GET DIAGNOSTICS v_reservation_skipped_item_rows = ROW_COUNT;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_build_reservation_availability_preview_report;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_build_reservation_availability_preview_report ON COMMIT DROP AS
  WITH scoped_preview_rows AS (
    SELECT
      scope_row.id AS candidate_scope_id,
      spr.preview_row_id,
      spr.candidate_id,
      spr.timesheet_id,
      upper(btrim(coalesce(spr.pay_channel, ''))) AS pay_channel,
      round(coalesce(spr.preview_amount_ex_vat, 0), 2)::numeric(12,2) AS requested_amount_ex_vat
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr
    LEFT JOIN public.banking_pay_operation_candidate_scope AS scope_row
      ON p_operation_id IS NOT NULL
     AND scope_row.operation_id = p_operation_id
     AND scope_row.pay_batch_id = v_batch_id
     AND scope_row.candidate_id = spr.candidate_id
     AND upper(btrim(coalesce(scope_row.pay_channel, ''))) = upper(btrim(coalesce(spr.pay_channel, '')))
    WHERE spr.candidate_id = ANY(v_candidate_ids)
  ),
  actual_by_preview AS (
    SELECT
      spr.candidate_scope_id,
      spr.preview_row_id,
      round(coalesce(sum(pbi.amount_ex_vat), 0), 2)::numeric(12,2) AS effective_amount_ex_vat
    FROM scoped_preview_rows AS spr
    LEFT JOIN public.pay_batch_candidates AS pbc
      ON pbc.pay_batch_id = v_batch_id
     AND pbc.candidate_id = spr.candidate_id
    LEFT JOIN public.pay_batch_items AS pbi
      ON pbi.pay_batch_candidate_id = pbc.id
     AND pbi.timesheet_id = spr.timesheet_id
     AND upper(btrim(coalesce(pbi.pay_channel, ''))) = spr.pay_channel
     AND coalesce(pbi.is_voided, false) = false
     AND pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    GROUP BY spr.candidate_scope_id, spr.preview_row_id
  ),
  report_by_preview AS (
    SELECT
      rep.candidate_id,
      rep.preview_row_id,
      count(*) FILTER (WHERE rep.availability_action = 'SKIP_ALREADY_RESERVED')::integer AS unavailable_item_count,
      count(*) FILTER (WHERE rep.availability_action = 'CLIP_TO_RESIDUAL')::integer AS clipped_item_count,
      coalesce(jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', CASE WHEN rep.pay_batch_item_id IS NULL THEN NULL ELSE rep.pay_batch_item_id::text END,
          'timesheet_id', CASE WHEN rep.timesheet_id IS NULL THEN NULL ELSE rep.timesheet_id::text END,
          'item_type', rep.item_type,
          'key_type', rep.key_type,
          'key_value', rep.key_value,
          'requested_source_amount_ex_vat', rep.requested_source_amount_ex_vat,
          'allowed_source_amount_ex_vat', rep.allowed_source_amount_ex_vat,
          'requested_target_amount_ex_vat', rep.requested_target_amount_ex_vat,
          'allowed_target_amount_ex_vat', rep.allowed_target_amount_ex_vat,
          'availability_action', rep.availability_action,
          'message', rep.message
        )
        order by rep.key_type, rep.key_value, rep.pay_batch_item_id::text
      ), '[]'::jsonb) AS component_reports_json
    FROM pg_temp.tmp_pay_build_reservation_availability_report AS rep
    WHERE rep.preview_row_id IS NOT NULL
    GROUP BY rep.candidate_id, rep.preview_row_id
  )
  SELECT
    spr.candidate_scope_id,
    spr.preview_row_id,
    spr.candidate_id,
    spr.timesheet_id,
    spr.pay_channel,
    spr.requested_amount_ex_vat,
    coalesce(abp.effective_amount_ex_vat, 0)::numeric(12,2) AS effective_amount_ex_vat,
    coalesce(rbp.unavailable_item_count, 0)::integer AS unavailable_item_count,
    coalesce(rbp.clipped_item_count, 0)::integer AS clipped_item_count,
    coalesce(rbp.component_reports_json, '[]'::jsonb) AS component_reports_json,
    (
      coalesce(rbp.unavailable_item_count, 0) > 0
      AND round(coalesce(abp.effective_amount_ex_vat, 0), 2) <= 0.005
    ) AS skipped_due_to_active_reservation,
    (
      (coalesce(rbp.clipped_item_count, 0) > 0 OR coalesce(rbp.unavailable_item_count, 0) > 0)
      AND round(coalesce(abp.effective_amount_ex_vat, 0), 2) < round(coalesce(spr.requested_amount_ex_vat, 0), 2) - 0.005
    ) AS clipped_due_to_active_reservation
  FROM scoped_preview_rows AS spr
  LEFT JOIN actual_by_preview AS abp
    ON abp.candidate_scope_id IS NOT DISTINCT FROM spr.candidate_scope_id
   AND abp.preview_row_id = spr.preview_row_id
  LEFT JOIN report_by_preview AS rbp
    ON rbp.candidate_id = spr.candidate_id
   AND rbp.preview_row_id = spr.preview_row_id;

  SELECT
    count(DISTINCT preview_row_id) FILTER (WHERE skipped_due_to_active_reservation)::integer,
    count(DISTINCT preview_row_id) FILTER (WHERE clipped_due_to_active_reservation)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'preview_row_id', preview_row_id,
          'candidate_id', candidate_id::text,
          'timesheet_id', CASE WHEN timesheet_id IS NULL THEN NULL ELSE timesheet_id::text END,
          'pay_channel', pay_channel,
          'requested_amount_ex_vat', requested_amount_ex_vat,
          'effective_amount_ex_vat', effective_amount_ex_vat,
          'skipped_due_to_active_reservation', skipped_due_to_active_reservation,
          'clipped_due_to_active_reservation', clipped_due_to_active_reservation,
          'unavailable_item_count', unavailable_item_count,
          'clipped_item_count', clipped_item_count,
          'components', component_reports_json
        )
        order by candidate_id::text, preview_row_id
      ) FILTER (WHERE unavailable_item_count > 0 OR clipped_item_count > 0),
      '[]'::jsonb
    )
  INTO
    v_reservation_skipped_preview_row_count,
    v_reservation_clipped_preview_row_count,
    v_reservation_availability_preview_rows_json
  FROM pg_temp.tmp_pay_build_reservation_availability_preview_report;

  IF p_operation_id IS NOT NULL THEN
    WITH payload_by_scope AS (
      SELECT
        pr.candidate_scope_id,
        jsonb_build_object(
          'applied_at_utc', now(),
          'message', CASE
            WHEN count(*) FILTER (WHERE pr.skipped_due_to_active_reservation) = count(*)
              THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
            ELSE 'Some payments were not added because they are already reserved in another draft batch.'
          END,
          'skipped_preview_row_count', count(*) FILTER (WHERE pr.skipped_due_to_active_reservation),
          'clipped_preview_row_count', count(*) FILTER (WHERE pr.clipped_due_to_active_reservation),
          'skipped_item_rows', coalesce(sum(pr.unavailable_item_count), 0),
          'clipped_item_rows', coalesce(sum(pr.clipped_item_count), 0),
          'all_selected_rows_unavailable', bool_and(pr.skipped_due_to_active_reservation),
          'preview_rows', coalesce(jsonb_agg(
            jsonb_build_object(
              'preview_row_id', pr.preview_row_id,
              'candidate_id', pr.candidate_id::text,
              'timesheet_id', CASE WHEN pr.timesheet_id IS NULL THEN NULL ELSE pr.timesheet_id::text END,
              'pay_channel', pr.pay_channel,
              'requested_amount_ex_vat', pr.requested_amount_ex_vat,
              'effective_amount_ex_vat', pr.effective_amount_ex_vat,
              'skipped_due_to_active_reservation', pr.skipped_due_to_active_reservation,
              'clipped_due_to_active_reservation', pr.clipped_due_to_active_reservation,
              'unavailable_item_count', pr.unavailable_item_count,
              'clipped_item_count', pr.clipped_item_count,
              'components', pr.component_reports_json
            )
            order by pr.preview_row_id
          ) FILTER (WHERE pr.unavailable_item_count > 0 OR pr.clipped_item_count > 0), '[]'::jsonb)
        ) AS reservation_availability_json
      FROM pg_temp.tmp_pay_build_reservation_availability_preview_report AS pr
      WHERE pr.candidate_scope_id IS NOT NULL
      GROUP BY pr.candidate_scope_id
      HAVING coalesce(sum(pr.unavailable_item_count + pr.clipped_item_count), 0) > 0
    )
    UPDATE public.banking_pay_operation_candidate_scope AS scope_update
    SET
      allocation_basis_json = jsonb_set(
        coalesce(scope_update.allocation_basis_json, '{}'::jsonb),
        '{reservation_availability}',
        payload_by_scope.reservation_availability_json,
        true
      ),
      updated_at_utc = now()
    FROM payload_by_scope
    WHERE scope_update.id = payload_by_scope.candidate_scope_id
      AND scope_update.operation_id = p_operation_id
      AND scope_update.pay_batch_id = v_batch_id;
  END IF;

  SELECT count(*)::integer
  INTO v_scope_item_rows_after_availability
  FROM public.pay_batch_items AS pbi_after
  JOIN public.pay_batch_candidates AS pbc_after
    ON pbc_after.id = pbi_after.pay_batch_candidate_id
  WHERE pbc_after.pay_batch_id = v_batch_id
    AND pbc_after.candidate_id = ANY(v_candidate_ids)
    AND coalesce(pbi_after.is_voided, false) = false
    AND pbi_after.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA');

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12B_ACTIVE_RESERVATION_AVAILABILITY_ENFORCED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'inserted_item_rows_before_availability', v_rows_ins_items,
        'eligible_item_rows_after_availability', v_scope_item_rows_after_availability,
        'reservation_skipped_item_rows', v_reservation_skipped_item_rows,
        'reservation_clipped_item_rows', v_reservation_clipped_item_rows,
        'reservation_skipped_preview_row_count', v_reservation_skipped_preview_row_count,
        'reservation_clipped_preview_row_count', v_reservation_clipped_preview_row_count,
        'reservation_preview_rows', v_reservation_availability_preview_rows_json
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_12_INSERT_PAY_BATCH_ITEMS';

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_12_ITEMS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'inserted_item_rows', v_rows_ins_items,
        'eligible_item_rows_after_availability', v_scope_item_rows_after_availability,
        'reservation_skipped_item_rows', v_reservation_skipped_item_rows,
        'reservation_clipped_item_rows', v_reservation_clipped_item_rows,
        'reservation_skipped_preview_row_count', v_reservation_skipped_preview_row_count,
        'reservation_clipped_preview_row_count', v_reservation_clipped_preview_row_count
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;


  update public.pay_batch_items as pbi_set
  set payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  from (
    select
      pbi.id as pay_batch_item_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'taxability',
            case
              when pbi.frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
                then 'NON_TAXABLE'
              else 'TAXABLE'
            end,
          'routing_kind',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'NORMAL_PAY_ROUTE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA_COMPANY'
              else null
            end,
          'destination_label',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'normal PAYE route'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'umbrella company'
              else null
            end,
          'pay_channel', upper(coalesce(pbi.pay_channel::text, '')),
          'payee_entity_kind',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'CANDIDATE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA'
              else null
            end,
          'payee_entity_id',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then pbc.candidate_id::text
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and pbi.umbrella_id is not null then pbi.umbrella_id::text
              else null
            end,
          'beneficiary_name',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then nullif(btrim(coalesce(u.name, '')), '')
              else null
            end,
          'sort_code',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
               and length(coalesce(c.sort_code, '')) = 6
                then substr(c.sort_code, 1, 2) || '-' || substr(c.sort_code, 3, 2) || '-' || substr(c.sort_code, 5, 2)
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and length(coalesce(u.sort_code, '')) = 6
                then substr(u.sort_code, 1, 2) || '-' || substr(u.sort_code, 3, 2) || '-' || substr(u.sort_code, 5, 2)
              else null
            end,
          'account_number',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
                then nullif(c.account_number, '')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
                then nullif(u.account_number, '')
              else null
            end,
          'account_type',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then 'Personal'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'Business'
              else null
            end,
          'masked_bank_account',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE'
               and nullif(coalesce(c.account_number, ''), '') is not null
                then lpad(right(c.account_number, 4), length(c.account_number), '*')
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and nullif(coalesce(u.account_number, ''), '') is not null
                then lpad(right(u.account_number, 4), length(u.account_number), '*')
              else null
            end,
          'bank_details_hash',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then c.bank_details_hash
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then u.bank_details_hash
              else null
            end,
          'week_ending_bucket',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
                then case
                       when ts_ctx.week_ending_date is null then (v_week_start + 6)::text
                       else ts_ctx.week_ending_date::text
                     end
              else null
            end,
          'rail_provider', upper(btrim(coalesce(v_rail_provider_default, ''))),
          'rail_env', upper(btrim(coalesce(v_rail_env_default, ''))),
          'payee_id',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then case when c.payee_id is null then null else c.payee_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then case when u.payee_id is null then null else u.payee_id::text end
              else null
            end,
          'payee_account_id',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' then case when c.payee_account_id is null then null else c.payee_account_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then case when u.payee_account_id is null then null else u.payee_account_id::text end
              else null
            end,
          'appears_on_umbrella_remittance',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then true
              else false
            end,
          'generates_candidate_payment_advice', false,
          'is_candidate_directed_oneoff_payout', false
        )
      ) as payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx as c
      on c.id = pbc.candidate_id
    left join pg_temp.tmp_pay_build_umbrellas_ctx as u
      on u.id = pbi.umbrella_id
    left join pg_temp.tmp_pay_build_timesheet_snapshots_ctx as ts_ctx
      on ts_ctx.timesheet_id = pbi.timesheet_id
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.payout_instruction_snapshot_json is null
      and pbi.item_type in ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
  ) as pbi_src
  where pbi_set.id = pbi_src.pay_batch_item_id;


  IF p_operation_id IS NOT NULL THEN
    UPDATE public.pay_batch_items AS inserted_item
    SET
      operation_source_key = p_operation_id::text
        || ':earning:' || v_batch_id::text
        || ':' || coalesce((
          select operation_scope.id::text
          from public.banking_pay_operation_candidate_scope as operation_scope
          where operation_scope.operation_id = p_operation_id
            and operation_scope.pay_batch_id = v_batch_id
            and operation_scope.candidate_id = batch_candidate.candidate_id
            and operation_scope.pay_channel = inserted_item.pay_channel
          order by operation_scope.id
          limit 1
        ), 'no_scope')
        || ':' || batch_candidate.candidate_id::text
        || ':' || inserted_item.item_type
        || ':' || coalesce(inserted_item.timesheet_id::text, 'no_timesheet')
        || ':' || coalesce(inserted_item.segment_key, 'no_segment')
        || ':' || coalesce(inserted_item.source_ref, 'no_source_ref')
        || ':' || coalesce(inserted_item.finance_component_id::text, 'no_component'),
      updated_at = now()
    FROM public.pay_batch_candidates AS batch_candidate
    WHERE batch_candidate.id = inserted_item.pay_batch_candidate_id
      AND batch_candidate.pay_batch_id = v_batch_id
      AND batch_candidate.candidate_id = ANY(v_candidate_ids)
      AND inserted_item.operation_source_key IS NULL
      AND inserted_item.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA');
  END IF;

  PERFORM 1
  FROM public.pay_batch_items pbi
  JOIN public.pay_batch_candidates pbc
    ON pbc.id = pbi.pay_batch_candidate_id
  WHERE pbc.pay_batch_id = v_batch_id
    AND pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    AND (
      pbi.frozen_component_key_type IS NULL OR btrim(coalesce(pbi.frozen_component_key_type, '')) = ''
      OR pbi.frozen_component_key_value IS NULL OR btrim(coalesce(pbi.frozen_component_key_value, '')) = ''
    )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve to deterministic economic keys';
  END IF;

  PERFORM 1
  FROM public.pay_batch_items AS pbi
  JOIN public.pay_batch_candidates AS pbc
    ON pbc.id = pbi.pay_batch_candidate_id
  WHERE pbc.pay_batch_id = v_batch_id
    AND coalesce(pbi.is_voided, false) = false
    AND pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    AND upper(btrim(coalesce(pbi.frozen_component_key_type, ''))) = 'TS_DAY'
    AND NOT (btrim(coalesce(pbi.frozen_component_key_value, '')) ~ '^\d{4}-\d{2}-\d{2}$')
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve TS_DAY economic keys to YYYY-MM-DD date buckets';
  END IF;

  PERFORM 1
  FROM public.pay_batch_items AS pbi
  JOIN public.pay_batch_candidates AS pbc
    ON pbc.id = pbi.pay_batch_candidate_id
  WHERE pbc.pay_batch_id = v_batch_id
    AND coalesce(pbi.is_voided, false) = false
    AND pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    AND public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id) IS NULL
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve to deterministic source entitlement amounts';
  END IF;


  UPDATE public.pay_batch_items AS pbi_set
  SET payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  FROM (
    SELECT
      pbi.id AS pay_batch_item_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'taxability', CASE WHEN pbi.frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum THEN 'NON_TAXABLE' ELSE 'TAXABLE' END,
          'routing_kind', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN 'NORMAL_PAY_ROUTE' WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN 'UMBRELLA_COMPANY' ELSE NULL END,
          'destination_label', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN 'normal PAYE route' WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN 'umbrella company' ELSE NULL END,
          'pay_channel', upper(coalesce(pbi.pay_channel::text, '')),
          'payee_entity_kind', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN 'CANDIDATE' WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN 'UMBRELLA' ELSE NULL END,
          'payee_entity_id', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN pbc.candidate_id::text WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' AND u.id IS NOT NULL THEN u.id::text ELSE NULL END,
          'beneficiary_name', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '') WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN nullif(btrim(coalesce(u.name, '')), '') ELSE NULL END,
          'sort_code', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' AND length(coalesce(c.sort_code, '')) = 6 THEN substr(c.sort_code, 1, 2) || '-' || substr(c.sort_code, 3, 2) || '-' || substr(c.sort_code, 5, 2) WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' AND length(coalesce(u.sort_code, '')) = 6 THEN substr(u.sort_code, 1, 2) || '-' || substr(u.sort_code, 3, 2) || '-' || substr(u.sort_code, 5, 2) ELSE NULL END,
          'account_number', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN nullif(c.account_number, '') WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN nullif(u.account_number, '') ELSE NULL END,
          'account_type', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN 'Personal' WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN 'Business' ELSE NULL END,
          'masked_bank_account', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' AND nullif(coalesce(c.account_number, ''), '') IS NOT NULL THEN lpad(right(c.account_number, 4), length(c.account_number), '*') WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' AND nullif(coalesce(u.account_number, ''), '') IS NOT NULL THEN lpad(right(u.account_number, 4), length(u.account_number), '*') ELSE NULL END,
          'bank_details_hash', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN c.bank_details_hash WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN u.bank_details_hash ELSE NULL END,
          'week_ending_bucket', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN CASE WHEN ts_ctx.week_ending_date IS NULL THEN (v_week_start + 6)::text ELSE ts_ctx.week_ending_date::text END ELSE NULL END,
          'rail_provider', upper(btrim(coalesce(pb.rail_provider_snapshot, ''))),
          'rail_env', upper(btrim(coalesce(pb.rail_env_snapshot, ''))),
          'payee_id', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN CASE WHEN c.payee_id IS NULL THEN NULL ELSE c.payee_id::text END WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN CASE WHEN u.payee_id IS NULL THEN NULL ELSE u.payee_id::text END ELSE NULL END,
          'payee_account_id', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'PAYE' THEN CASE WHEN c.payee_account_id IS NULL THEN NULL ELSE c.payee_account_id::text END WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN CASE WHEN u.payee_account_id IS NULL THEN NULL ELSE u.payee_account_id::text END ELSE NULL END,
          'appears_on_umbrella_remittance', CASE WHEN upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' THEN true ELSE false END,
          'generates_candidate_payment_advice', false,
          'is_candidate_directed_oneoff_payout', false
        )
      ) AS payout_instruction_snapshot_json
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN public.pay_batches pb
      ON pb.id = pbc.pay_batch_id
    JOIN pg_temp.tmp_pay_build_candidates_ctx c
      ON c.id = pbc.candidate_id
    LEFT JOIN pg_temp.tmp_pay_build_umbrellas_ctx u
      ON u.id = c.umbrella_id
    LEFT JOIN pg_temp.tmp_pay_build_timesheet_snapshots_ctx ts_ctx
      ON ts_ctx.timesheet_id = pbi.timesheet_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND coalesce(pbi.is_voided, false) = false
      AND pbi.payout_instruction_snapshot_json IS NULL
      AND (
        pbi.item_type IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
        OR (
          pbi.item_type IN ('MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY')
          AND (
            NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
        )
      )
  ) AS pbi_src
  WHERE pbi_set.id = pbi_src.pay_batch_item_id;


  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_operation_reused_count
    FROM public.pay_batch_items AS existing_item
    JOIN public.pay_batch_candidates AS existing_candidate
      ON existing_candidate.id = existing_item.pay_batch_candidate_id
    WHERE existing_candidate.pay_batch_id = v_batch_id
      AND existing_candidate.candidate_id = ANY(v_candidate_ids)
      AND existing_item.operation_source_key LIKE (p_operation_id::text || ':earning:%');

    v_operation_reused_count := coalesce(v_operation_reused_count, 0) - coalesce(v_rows_ins_items, 0);

    IF v_operation_reused_count < 0 THEN
      v_operation_reused_count := 0;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'inserted_item_rows', v_rows_ins_items,
    'eligible_item_rows_after_availability', coalesce(v_scope_item_rows_after_availability, 0),
    'reused_item_rows', coalesce(v_operation_reused_count, 0),
    'skipped_item_rows', coalesce(v_reservation_skipped_item_rows, 0),
    'failed_item_rows', 0,
    'reservation_skipped_item_rows', coalesce(v_reservation_skipped_item_rows, 0),
    'reservation_clipped_item_rows', coalesce(v_reservation_clipped_item_rows, 0),
    'reservation_skipped_preview_row_count', coalesce(v_reservation_skipped_preview_row_count, 0),
    'reservation_clipped_preview_row_count', coalesce(v_reservation_clipped_preview_row_count, 0),
    'reservation_availability_preview_rows', coalesce(v_reservation_availability_preview_rows_json, '[]'::jsonb),
    'message', CASE
      WHEN coalesce(v_reservation_skipped_preview_row_count, 0) > 0 OR coalesce(v_reservation_clipped_preview_row_count, 0) > 0
        THEN 'Some payments were not added because they are already reserved in another draft batch.'
      ELSE NULL
    END
  );
END;
$function$
;



DROP FUNCTION IF EXISTS public.pay_batch_apply_finance_adjustments(uuid, text, uuid, numeric, date);

CREATE OR REPLACE FUNCTION public.pay_batch_apply_finance_adjustments(
  p_pay_batch_id uuid,
  p_pay_channel_scope text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_vat_rate_pct numeric DEFAULT NULL::numeric,
  p_week_start date DEFAULT NULL::date,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_vat_rate_pct numeric := p_vat_rate_pct;
  v_week_start date := p_week_start;
  v_now_utc timestamptz := now();
  v_stage text := NULL;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_client_filter_single uuid := NULL::uuid;
  v_rows_ins_loan_payout_items integer := 0;
  v_rows_ins_manual_credit_payout_items integer := 0;
  v_rows_ins_overpayment_recovery_items integer := 0;
  v_rows_upd_candidates_overpayment_recovery_taken integer := 0;
  v_rows_ins_debt_items integer := 0;
  v_rows_upd_candidates_debt integer := 0;
  v_rows_ins_loan_items integer := 0;
  v_rows_upd_candidates_loan integer := 0;
  v_rows_staged_recovery_template_rows integer := 0;
  v_rows_staged_manual_debt_template_rows integer := 0;
  v_rows_staged_loan_template_rows integer := 0;
  v_rows_staged_overpayment_template_rows integer := 0;
  v_rows_staged_paye_manual_debt_template_rows integer := 0;
  v_rows_ins_dormant_recovery_template_items integer := 0;
  v_rows_ins_dormant_manual_debt_template_items integer := 0;
  v_rows_ins_dormant_loan_template_items integer := 0;
  v_rows_ins_dormant_overpayment_template_items integer := 0;
  v_rows_skipped_dormant_recovery_template_items integer := 0;
  v_rows_skipped_dormant_manual_debt_template_items integer := 0;
  v_rows_skipped_dormant_loan_template_items integer := 0;
  v_rows_skipped_dormant_overpayment_template_items integer := 0;
  v_missing_materialised_manual_debt_template_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_staged_manual_debt_template_rows_by_candidate jsonb := '{}'::jsonb;
  v_payout_instruction_freeze_rec record;
  v_operation_allocation_total integer := 0;
  v_operation_allocation_done integer := 0;
  v_operation_mismatch_details jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );

    SELECT settings_context.vat_rate_pct, settings_context.pay_week_start
    INTO v_vat_rate_pct, v_week_start
    FROM pg_temp.tmp_pay_build_settings_context AS settings_context
    LIMIT 1;
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;
  IF v_vat_rate_pct IS NULL THEN
    RAISE EXCEPTION 'vat_rate_pct is required';
  END IF;
  IF v_week_start IS NULL THEN
    RAISE EXCEPTION 'week_start is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_finance_case_components_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_finance_case_components_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_oneoff_payout_bank_details_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_timesheet_snapshots_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_timesheet_snapshots_ctx temp table is required';
  END IF;
  IF to_regclass('pg_temp.tmp_pay_build_recovery_template_rows') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_recovery_template_rows temp table is required';
  END IF;
  SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr;

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer,
           count(*) FILTER (WHERE allocation_row.status = 'ITEM_CREATED' AND allocation_row.pay_batch_item_id IS NOT NULL)::integer
    INTO v_operation_allocation_total, v_operation_allocation_done
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_id = ANY(v_candidate_ids)
      AND allocation_row.pay_channel = v_scope;

    IF coalesce(v_operation_allocation_total, 0) > 0
       AND coalesce(v_operation_allocation_total, 0) = coalesce(v_operation_allocation_done, 0) THEN
      RETURN jsonb_build_object(
        'ok', true,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'applied_count', 0,
        'reused_count', v_operation_allocation_done,
        'skipped_count', 0,
        'failed_count', 0,
        'mismatch_details', '{}'::jsonb
      );
    END IF;

    IF coalesce(v_operation_allocation_done, 0) > 0
       AND coalesce(v_operation_allocation_done, 0) < coalesce(v_operation_allocation_total, 0) THEN
      IF EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
        JOIN public.pay_batch_items AS linked_item
          ON linked_item.id = allocation_row.pay_batch_item_id
        WHERE allocation_row.operation_id = p_operation_id
          AND allocation_row.candidate_id = ANY(v_candidate_ids)
          AND allocation_row.pay_channel = v_scope
          AND allocation_row.status = 'ITEM_CREATED'
          AND allocation_row.pay_batch_item_id IS NOT NULL
          AND linked_item.reservation_id IS NOT NULL
        LIMIT 1
      ) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
          'code', 'OPERATION_ALLOCATION_PARTIAL_RETRY_AFTER_RESERVATION',
          'message', 'pay_batch_apply_finance_adjustments cannot safely retry a partially-linked finance chunk after reservations have been created',
          'pay_batch_id', v_batch_id::text,
          'operation_id', p_operation_id::text,
          'pay_channel_scope', v_scope
        )::text;
      END IF;

      DELETE FROM public.pay_batch_items AS linked_item_delete
      USING public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.candidate_id = ANY(v_candidate_ids)
        AND allocation_row.pay_channel = v_scope
        AND allocation_row.status = 'ITEM_CREATED'
        AND allocation_row.pay_batch_item_id = linked_item_delete.id
        AND linked_item_delete.reservation_id IS NULL;

      UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_reset
      SET
        status = 'PENDING',
        pay_batch_item_id = NULL,
        updated_at_utc = now()
      WHERE allocation_reset.operation_id = p_operation_id
        AND allocation_reset.candidate_id = ANY(v_candidate_ids)
        AND allocation_reset.pay_channel = v_scope
        AND allocation_reset.status = 'ITEM_CREATED';

      v_operation_allocation_done := 0;
    END IF;
  END IF;


  IF EXISTS (
    WITH finance_case_draft_scope AS (
      SELECT DISTINCT
        spr.finance_case_id AS finance_case_id,
        spr.candidate_id AS candidate_id,
        upper(coalesce(nullif(spr.pay_channel, ''), v_scope)) AS target_pay_channel,
        spr.line_type AS source_line_type
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr
      WHERE spr.draftable = true
        AND spr.finance_case_id IS NOT NULL
        AND spr.candidate_id = ANY(v_candidate_ids)
        AND (v_client_filter_single IS NULL OR spr.client_id = v_client_filter_single)
        AND spr.line_type IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY',
          'MANUAL_CREDIT_ADJUSTMENT_PAYMENT',
          'MANUAL_CREDIT_PAYOUT'
        )

      UNION

      SELECT DISTINCT
        template_rows.finance_case_id AS finance_case_id,
        template_rows.candidate_id AS candidate_id,
        CASE
          WHEN upper(coalesce(template_rows.pay_channel, '')) IN ('PAYE', 'UMBRELLA') THEN upper(coalesce(template_rows.pay_channel, ''))
          WHEN coalesce(btrim(coalesce(template_rows.pay_channel, '')), '') = '' THEN v_scope
          ELSE upper(coalesce(template_rows.pay_channel, ''))
        END AS target_pay_channel,
        template_rows.recovery_family AS source_line_type
      FROM pg_temp.tmp_pay_build_recovery_template_rows AS template_rows
      WHERE template_rows.finance_case_id IS NOT NULL
        AND template_rows.candidate_id = ANY(v_candidate_ids)
        AND template_rows.recovery_family IN (
          'OVERPAYMENT_RECOVERY',
          'MANUAL_DEBT_RECOVERY'
        )
    )
    SELECT 1
    FROM finance_case_draft_scope AS draft_scope
    JOIN public.pay_advances AS finance_case
      ON finance_case.id = draft_scope.finance_case_id
     AND finance_case.case_type IN (
       'OVERPAYMENT'::public.pay_finance_case_type_enum,
       'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
       'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
     )
     AND finance_case.status = 'ACTIVE'::public.pay_advance_status_enum
    JOIN public.pay_finance_case_components AS finance_component
      ON finance_component.finance_case_id = draft_scope.finance_case_id
     AND finance_component.closed_at_utc IS NULL
    WHERE draft_scope.target_pay_channel IN ('PAYE', 'UMBRELLA')
      AND finance_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      AND round(coalesce(finance_component.remaining_source_amount, 0), 2) > 0
      AND upper(coalesce(finance_component.source_pay_method, '')) IN ('PAYE', 'UMBRELLA')
      AND upper(coalesce(finance_component.source_pay_method, '')) <> draft_scope.target_pay_channel
      AND (
        coalesce(finance_component.is_resolution_stale, false) = true
        OR nullif(btrim(coalesce(finance_component.saved_target_pay_method, '')), '') IS NULL
        OR upper(coalesce(finance_component.saved_target_pay_method, '')) <> draft_scope.target_pay_channel
        OR finance_component.saved_resolution_mode IS NULL
        OR jsonb_typeof(coalesce(finance_component.saved_resolution_payload_json, 'null'::jsonb)) <> 'object'
        OR jsonb_typeof(coalesce(finance_component.saved_resolution_result_json, 'null'::jsonb)) <> 'object'
        OR nullif(btrim(coalesce(finance_component.resolution_fingerprint, '')), '') IS NULL
      )
    LIMIT 1
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
      'code', 'TAXABLE_CHANNEL_RESTRUCTURE_REQUIRED',
      'message', 'pay_batch_apply_finance_adjustments: taxable PAYE/Umbrella channel restructure is required before finance items can be drafted',
      'pay_batch_id', v_batch_id::text,
      'pay_channel_scope', v_scope
    )::text;
  END IF;


v_stage := 'STAGE_12C_APPLY_LOAN_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with safe_case_rows as (
    select
      spr.preview_row_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(spr.pay_channel,'')) as pay_channel,
      upper(coalesce(spr.paye_treatment,'')) as paye_treatment,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      abs(round(coalesce(spr.preview_amount_ex_vat, 0), 2))::numeric(12,2) as payout_total_target_ex
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    where spr.draftable = true
      and spr.line_type = 'LOAN_PAYOUT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
  ),
  candidate_due as (
    select
      pbc.id as pay_batch_candidate_id,
      scr.preview_row_id,
      scr.candidate_id,
      scr.pay_channel,
      case when scr.pay_channel = 'UMBRELLA' then c.umbrella_id else null end as umbrella_id,
      scr.finance_case_id,
      scr.linked_timesheet_id,
      scr.paye_treatment,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.payout_total_target_ex
    from safe_case_rows scr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = scr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = scr.candidate_id
  ),
  case_component_base as (
    select
      cd.pay_batch_candidate_id,
      cd.preview_row_id,
      cd.candidate_id,
      cd.pay_channel,
      cd.umbrella_id,
      cd.finance_case_id,
      cd.linked_timesheet_id,
      cd.paye_treatment,
      cd.routing_kind,
      cd.destination_label,
      cd.taxability,
      cd.beneficiary_name,
      cd.masked_bank_account,
      cd.bank_details_hash,
      cd.is_candidate_directed_oneoff_payout,
      cd.appears_on_umbrella_remittance,
      cd.generates_candidate_payment_advice,
      pfc.id as finance_component_id,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      upper(coalesce(pfc.source_pay_method,'')) as source_pay_method,
      pfc.source_basis_json,
      upper(coalesce(pfc.saved_target_pay_method,'')) as saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      round(greatest(coalesce(pfc.source_amount, pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as source_amount,
      round(greatest(coalesce(pfc.remaining_source_amount, 0), 0), 2)::numeric(12,2) as remaining_source_amount,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order,
      pfc.created_at_utc as finance_component_created_at,
      cd.payout_total_target_ex,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'ex')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_ex_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as remaining_target_amount_vat,
      case
        when cd.pay_channel = 'UMBRELLA'
         and pfc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then round((public._pay_umbrella_vat_calc(round(greatest(coalesce(pfc.remaining_source_amount,0),0),2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric, 2)::numeric(12,2)
        else round(greatest(coalesce(pfc.remaining_source_amount,0),0), 2)::numeric(12,2)
      end as remaining_target_amount_inc_vat,
      obd.created_by_user_id as bank_details_created_by_user_id,
      obd.updated_by_user_id as bank_details_updated_by_user_id,
      obd.note as bank_details_note
    from candidate_due cd
    join pg_temp.tmp_pay_build_finance_case_components_ctx pfc
      on pfc.finance_case_id = cd.finance_case_id
     and coalesce(pfc.remaining_source_amount, 0) > 0
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = cd.umbrella_id
    left join pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx obd
      on obd.finance_case_id = cd.finance_case_id
  ),
  case_component_due as (
    select
      ccb.*,
      sum(ccb.remaining_target_amount_ex_vat) over (
        partition by ccb.finance_case_id
        order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
        rows between unbounded preceding and 1 preceding
      )::numeric(12,2) as cum_before_case_target,
      least(
        ccb.remaining_target_amount_ex_vat,
        greatest(ccb.payout_total_target_ex - coalesce(sum(ccb.remaining_target_amount_ex_vat) over (
          partition by ccb.finance_case_id
          order by ccb.allocation_priority_group, ccb.allocation_priority_order, ccb.finance_component_created_at, ccb.finance_component_id
          rows between unbounded preceding and 1 preceding
        ), 0), 0)
      )::numeric(12,2) as take_target_ex
    from case_component_base ccb
  ),
  alloc as (
    select
      ccd.pay_batch_candidate_id,
      ccd.pay_channel,
      ccd.umbrella_id,
      ccd.finance_case_id,
      ccd.linked_timesheet_id,
      ccd.paye_treatment,
      ccd.routing_kind,
      ccd.destination_label,
      ccd.taxability,
      ccd.beneficiary_name,
      ccd.masked_bank_account,
      ccd.bank_details_hash,
      ccd.is_candidate_directed_oneoff_payout,
      ccd.appears_on_umbrella_remittance,
      ccd.generates_candidate_payment_advice,
      ccd.bank_details_created_by_user_id,
      ccd.bank_details_updated_by_user_id,
      ccd.bank_details_note,
      ccd.finance_component_id,
      ccd.component_key_type,
      ccd.component_key_value,
      ccd.classification,
      ccd.source_pay_method,
      ccd.source_basis_json,
      ccd.saved_target_pay_method,
      ccd.saved_resolution_mode,
      ccd.saved_resolution_payload_json,
      ccd.saved_resolution_result_json,
      ccd.source_amount,
      ccd.remaining_source_amount,
      ccd.remaining_target_amount_ex_vat,
      ccd.remaining_target_amount_vat,
      ccd.remaining_target_amount_inc_vat,
      round(ccd.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then least(
          ccd.remaining_source_amount,
          round(ccd.remaining_source_amount * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)
        )::numeric(12,2)
        else 0::numeric(12,2)
      end as take_source_amount,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_vat,
      case
        when round(coalesce(ccd.remaining_target_amount_ex_vat,0),2) > 0 then round(coalesce(ccd.remaining_target_amount_inc_vat,0) * ccd.take_target_ex / ccd.remaining_target_amount_ex_vat, 2)::numeric(12,2)
        else 0::numeric(12,2)
      end as take_target_inc
    from case_component_due ccd
    where ccd.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    a.pay_batch_candidate_id,
    'LOAN_PAYOUT'::text as item_type,
    a.linked_timesheet_id as timesheet_id,
    null::text as segment_key,
    ('advance:' || a.finance_case_id::text) as source_ref,
    'Payment Advance'::text as description,
    round(a.take_target_ex, 2) as amount_ex_vat,
    round(a.take_target_vat, 2) as amount_vat,
    round(a.take_target_inc, 2) as amount_inc_vat,
    a.pay_channel,
    a.umbrella_id,
    false as is_mismatch,
    a.finance_case_id,
    a.finance_component_id,
    jsonb_build_object(
      'finance_case_id', a.finance_case_id::text,
      'finance_component_id', a.finance_component_id::text,
      'linked_timesheet_id', case when a.linked_timesheet_id is null then null else a.linked_timesheet_id::text end,
      'classification', a.classification::text,
      'source_pay_method', a.source_pay_method,
      'target_pay_method', a.pay_channel,
      'source_basis_json', a.source_basis_json,
      'saved_target_pay_method', a.saved_target_pay_method,
      'saved_resolution_mode', case when a.saved_resolution_mode is null then null else a.saved_resolution_mode::text end,
      'saved_resolution_payload_json', a.saved_resolution_payload_json,
      'saved_resolution_result_json', a.saved_resolution_result_json,
      'reserved_source_amount', round(a.take_source_amount, 2),
      'frozen_target_amount_ex_vat', round(a.take_target_ex, 2),
      'frozen_target_amount_vat', round(a.take_target_vat, 2),
      'frozen_target_amount_inc_vat', round(a.take_target_inc, 2)
    ) as frozen_component_snapshot_json,
    a.component_key_type,
    a.component_key_value,
    a.classification,
    a.source_basis_json,
    a.source_pay_method,
    a.pay_channel,
    a.saved_resolution_mode,
    a.saved_resolution_payload_json,
    a.saved_resolution_result_json,
    round(a.take_source_amount, 2),
    round(a.take_target_ex, 2),
    round(a.take_target_vat, 2),
    round(a.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', a.taxability,
        'routing_kind', a.routing_kind,
        'destination_label', a.destination_label,
        'pay_channel', a.pay_channel,
        'payee_entity_kind', case when a.is_candidate_directed_oneoff_payout then 'CANDIDATE' when a.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', a.beneficiary_name,
        'masked_bank_account', a.masked_bank_account,
        'bank_details_hash', a.bank_details_hash,
        'bank_details_note', a.bank_details_note,
        'bank_details_created_by_user_id', case when a.bank_details_created_by_user_id is null then null else a.bank_details_created_by_user_id::text end,
        'bank_details_updated_by_user_id', case when a.bank_details_updated_by_user_id is null then null else a.bank_details_updated_by_user_id::text end,
        'appears_on_umbrella_remittance', a.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', a.generates_candidate_payment_advice,
        'is_candidate_directed_oneoff_payout', a.is_candidate_directed_oneoff_payout,
        'payee_entity_id', case
          when a.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
          when a.routing_kind = 'UMBRELLA_COMPANY' then case when a.umbrella_id is null then null else a.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = a.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case
      when a.pay_channel <> 'PAYE' then 'NONE'
      when a.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_ADD'
      when a.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'NET_ADD'
      else coalesce(nullif(a.paye_treatment,''), 'NET_ADD')
    end as paye_treatment
  from alloc a
  where a.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_payout_items = row_count;

  
v_stage := 'STAGE_12D_APPLY_MANUAL_CREDIT_PAYOUTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    pay_channel,
    umbrella_id,
    is_mismatch,
    finance_case_id,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json,
    paye_treatment
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      spr.client_id,
      spr.timesheet_id as linked_timesheet_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      nullif(btrim(coalesce(spr.routing_kind,'')), '') as routing_kind,
      nullif(btrim(coalesce(spr.destination_label,'')), '') as destination_label,
      nullif(btrim(coalesce(spr.taxability,'')), '') as taxability,
      nullif(btrim(coalesce(spr.beneficiary_name,'')), '') as beneficiary_name,
      nullif(btrim(coalesce(spr.masked_bank_account,'')), '') as masked_bank_account,
      nullif(btrim(coalesce(spr.bank_details_hash,'')), '') as bank_details_hash,
      coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_CREDIT_ADJUSTMENT_PAYMENT'
      and spr.finance_case_id is not null
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.routing_kind,
      scr.destination_label,
      scr.taxability,
      scr.beneficiary_name,
      scr.masked_bank_account,
      scr.bank_details_hash,
      scr.is_candidate_directed_oneoff_payout,
      scr.appears_on_umbrella_remittance,
      scr.generates_candidate_payment_advice,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      upper(nullif(btrim(coalesce(comp.comp_json->>'saved_target_pay_method','')), '')) as saved_target_pay_method,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.routing_kind,
      n.destination_label,
      n.taxability,
      n.beneficiary_name,
      n.masked_bank_account,
      n.bank_details_hash,
      n.is_candidate_directed_oneoff_payout,
      n.appears_on_umbrella_remittance,
      n.generates_candidate_payment_advice,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', n.saved_resolution_mode_text,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_CREDIT_PAYOUT'::text as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    'Manual credit adjustment payment'::text as description,
    round(fa.take_target_ex, 2) as amount_ex_vat,
    round(fa.take_target_vat, 2) as amount_vat,
    round(fa.take_target_inc, 2) as amount_inc_vat,
    fa.pay_channel,
    fa.umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    fa.finance_case_id,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    round(fa.take_source_amount, 2),
    round(fa.take_target_ex, 2),
    round(fa.take_target_vat, 2),
    round(fa.take_target_inc, 2),
    jsonb_strip_nulls(
      jsonb_build_object(
        'taxability', fa.taxability,
        'routing_kind', fa.routing_kind,
        'destination_label', fa.destination_label,
        'pay_channel', fa.pay_channel,
        'payee_entity_kind', case when fa.is_candidate_directed_oneoff_payout then 'CANDIDATE' when fa.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA' else 'CANDIDATE' end,
        'beneficiary_name', fa.beneficiary_name,
        'masked_bank_account', fa.masked_bank_account,
        'bank_details_hash', fa.bank_details_hash,
        'appears_on_umbrella_remittance', fa.appears_on_umbrella_remittance,
        'generates_candidate_payment_advice', fa.generates_candidate_payment_advice,
        'payee_entity_id', case
          when fa.is_candidate_directed_oneoff_payout then (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
          when fa.routing_kind = 'UMBRELLA_COMPANY' then case when fa.umbrella_id is null then null else fa.umbrella_id::text end
          else (
            select pbc2.candidate_id::text
            from public.pay_batch_candidates pbc2
            where pbc2.id = fa.pay_batch_candidate_id
            limit 1
          )
        end
      )
    ) as payout_instruction_snapshot_json,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_ADD'
      when fa.classification in ('REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum, 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum) then 'NET_ADD'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_ADD')
    end as paye_treatment
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_manual_credit_payout_items = row_count;

  
v_stage := 'STAGE_16AA_APPLY_OVERPAYMENT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'OVERPAYMENT_RECOVERY'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'OVERPAYMENT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_overpayment_recovery_items = row_count;


  update public.pay_batch_candidates pbc
  set
    overpayment_recovery_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_overpayment_recovery_taken = row_count;

  v_rows_ins_debt_items := 0;


v_stage := 'STAGE_16B_APPLY_MANUAL_DEBT_RECOVERY';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      exists (
        select 1
        from public.pay_batch_paye_net_inputs pni_md_exists
        where pni_md_exists.pay_batch_candidate_id = pbc.id
        limit 1
      ) as has_paye_net_input,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'MANUAL_DEBT_RECOVERY'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.has_paye_net_input,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_payload_json') = 'object' then comp.comp_json->'suggested_resolution_payload_json'
        else null::jsonb
      end as preview_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'suggested_resolution_result_json') = 'object' then comp.comp_json->'suggested_resolution_result_json'
        else null::jsonb
      end as preview_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      nullif(btrim(coalesce(comp.comp_json->'suggested_resolution_payload_json'->>'resolution_mode','')), '') as preview_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->'suggested_resolution_result_json'->>'target_amount_ex_vat')::numeric
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.has_paye_net_input,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_resolution_mode_text', n.saved_resolution_mode_text,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'resolution_mode', n.saved_resolution_mode_text,
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'MANUAL_DEBT_RECOVERY' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0
    and not (
      upper(coalesce(fa.pay_channel, '')) = 'PAYE'
      and coalesce(fa.has_paye_net_input, false) = false
      and (
        case
          when fa.pay_channel <> 'PAYE' then 'NONE'
          when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
          when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
          else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
        end
      ) = 'NET_DEDUCT'
    );

  get diagnostics v_rows_ins_debt_items = row_count;

v_stage := 'STAGE_16C_APPLY_PAYMENT_ADVANCE_REPAYMENTS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat
  )
  with selected_case_rows as (
    select distinct on (spr.finance_case_id)
      pbc.id as pay_batch_candidate_id,
      spr.candidate_id,
      spr.finance_case_id,
      upper(coalesce(nullif(spr.pay_channel,''), v_scope)) as pay_channel,
      upper(coalesce(nullif(spr.paye_treatment,''), 'NONE')) as paye_treatment,
      case when upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = 'UMBRELLA' then c.umbrella_id else null::uuid end as umbrella_id,
      round(abs(coalesce(spr.preview_amount_ex_vat, 0)), 2)::numeric(12,2) as due_amount_ex_vat,
      coalesce(spr.case_components_json, '[]'::jsonb) as case_components_json
    from pg_temp.tmp_pay_build_selected_preview_rows spr
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = v_batch_id
     and pbc.candidate_id = spr.candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = spr.candidate_id
    where spr.draftable = true
      and spr.line_type = 'PAYMENT_ADVANCE_REPAYMENT'
      and spr.finance_case_id is not null
      and upper(coalesce(nullif(spr.pay_channel,''), v_scope)) = v_scope
      and spr.candidate_id = any(v_candidate_ids)
      and (v_client_filter_single is null or spr.client_id = v_client_filter_single)
      and abs(coalesce(spr.preview_amount_ex_vat, 0)) > 0
    order by spr.finance_case_id, spr.preview_row_id
  ),
  component_rows as (
    select
      scr.pay_batch_candidate_id,
      scr.candidate_id,
      scr.finance_case_id,
      scr.pay_channel,
      scr.paye_treatment,
      scr.umbrella_id,
      scr.due_amount_ex_vat,
      comp.comp_json,
      case
        when nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), '') is null then null::uuid
        else (comp.comp_json->>'finance_component_id')::uuid
      end as finance_component_id,
      nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), '') as component_key_type,
      coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), 'TOTAL') as component_key_value,
      case
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'TAXABLE_CHANNEL_SENSITIVE' then 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'REIMBURSEMENT_GROSS_FIXED' then 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        when upper(btrim(coalesce(comp.comp_json->>'classification',''))) = 'NET_PAY_FIXED_RECOVERY' then 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        else null::public.pay_finance_component_classification_enum
      end as classification,
      upper(btrim(coalesce(comp.comp_json->>'source_pay_method',''))) as source_pay_method,
      coalesce(comp.comp_json->'source_basis_json', '{}'::jsonb) as source_basis_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_payload_json') = 'object' then comp.comp_json->'saved_resolution_payload_json'
        else null::jsonb
      end as saved_resolution_payload_json,
      case
        when jsonb_typeof(comp.comp_json->'saved_resolution_result_json') = 'object' then comp.comp_json->'saved_resolution_result_json'
        else null::jsonb
      end as saved_resolution_result_json,
      nullif(btrim(coalesce(comp.comp_json->>'saved_resolution_mode','')), '') as saved_resolution_mode_text,
      round(
        case
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'remaining_source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'remaining_source_amount')::numeric
          when coalesce(comp.comp_json->>'source_amount','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'source_amount')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as remaining_source_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'allocated_source_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'allocated_source_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as allocated_source_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as preview_due_amount_ex_vat,
      round(
        case
          when coalesce(comp.comp_json->>'target_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'target_pay_ex_vat')::numeric
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as target_pay_ex_vat,
      case
        when coalesce(comp.comp_json->>'source_units','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_units')::numeric, 6)
        else null::numeric
      end as source_units,
      case
        when coalesce(comp.comp_json->>'source_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_rate')::numeric, 2)
        else null::numeric
      end as source_rate,
      case
        when coalesce(comp.comp_json->>'target_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_rate')::numeric, 2)
        else null::numeric
      end as target_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_rate','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_rate')::numeric, 2)
        else null::numeric
      end as source_charge_rate,
      case
        when coalesce(comp.comp_json->>'source_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'source_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as source_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_charge_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_charge_ex_vat')::numeric, 2)
        else null::numeric
      end as target_charge_ex_vat,
      case
        when coalesce(comp.comp_json->>'target_margin_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'target_margin_ex_vat')::numeric, 2)
        else null::numeric
      end as target_margin_ex_vat,
      case
        when coalesce(comp.comp_json->>'margin_delta_ex_vat','') ~ '^-?\d+(\.\d+)?$' then round((comp.comp_json->>'margin_delta_ex_vat')::numeric, 2)
        else null::numeric
      end as margin_delta_ex_vat,
      row_number() over (
        partition by scr.finance_case_id
        order by
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'finance_component_id','')), ''), md5(comp.comp_json::text)),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_type','')), ''), ''),
          coalesce(nullif(btrim(coalesce(comp.comp_json->>'component_key_value','')), ''), '')
      ) as component_rn,
      count(*) over (partition by scr.finance_case_id) as component_ct,
      round(sum(
        round(
          case
            when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
            else 0
          end,
          2
        )
      ) over (partition by scr.finance_case_id), 2)::numeric(12,2) as component_preview_due_sum
    from selected_case_rows scr
    cross join lateral jsonb_array_elements(coalesce(scr.case_components_json, '[]'::jsonb)) as comp(comp_json)
    where jsonb_typeof(comp.comp_json) = 'object'
      and round(
        case
          when coalesce(comp.comp_json->>'preview_due_amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (comp.comp_json->>'preview_due_amount_ex_vat')::numeric
          else 0
        end,
        2
      ) > 0
  ),
  normalized as (
    select
      cr.*,
      round(
        case
          when cr.component_ct = 1 then cr.due_amount_ex_vat
          when cr.component_rn = 1 then greatest(cr.due_amount_ex_vat - (coalesce(cr.component_preview_due_sum, 0) - coalesce(cr.preview_due_amount_ex_vat, 0)), 0)
          else cr.preview_due_amount_ex_vat
        end,
        2
      )::numeric(12,2) as take_target_ex
    from component_rows cr
  ),
  final_alloc as (
    select
      n.pay_batch_candidate_id,
      n.finance_case_id,
      n.pay_channel,
      n.paye_treatment,
      n.umbrella_id,
      n.finance_component_id,
      n.component_key_type,
      n.component_key_value,
      n.classification,
      n.source_pay_method,
      n.source_basis_json,
      case
        when n.saved_resolution_mode_text is not null then n.saved_resolution_mode_text::public.pay_finance_component_resolution_mode_enum
        when n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and upper(coalesce(n.source_pay_method,'')) <> upper(coalesce(n.pay_channel,''))
        then 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        else null::public.pay_finance_component_resolution_mode_enum
      end as frozen_resolution_mode,
      case
        when jsonb_typeof(n.saved_resolution_payload_json) = 'object' then jsonb_strip_nulls(
          n.saved_resolution_payload_json
          || jsonb_build_object(
            'target_pay_method', n.pay_channel,
            'target_units', n.source_units,
            'suggested_target_rate', n.target_rate,
            'source_rate', n.source_rate,
            'source_charge_rate', n.source_charge_rate
          )
        )
        else jsonb_strip_nulls(jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_units', n.source_units,
          'suggested_target_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate
        ))
      end as frozen_resolution_payload_json,
      round(
        case
          when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
          when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
          else 0
        end,
        2
      )::numeric(12,2) as take_source_amount,
      round(n.take_target_ex, 2)::numeric(12,2) as take_target_ex,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
          else 0
        end,
        2
      )::numeric(12,2) as take_target_vat,
      round(
        case
          when n.pay_channel = 'UMBRELLA'
           and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
          else round(n.take_target_ex, 2)
        end,
        2
      )::numeric(12,2) as take_target_inc,
      jsonb_strip_nulls(
        coalesce(n.comp_json, '{}'::jsonb)
        || jsonb_build_object(
          'frozen_target_pay_method', n.pay_channel,
          'frozen_source_amount', round(
            case
              when n.allocated_source_due_amount_ex_vat > 0 then n.allocated_source_due_amount_ex_vat
              when n.take_target_ex > 0 and n.target_pay_ex_vat > 0 then least(n.remaining_source_amount_ex_vat, round(n.remaining_source_amount_ex_vat * n.take_target_ex / n.target_pay_ex_vat, 2))
              else 0
            end,
            2
          ),
          'frozen_target_amount_ex_vat', round(-n.take_target_ex, 2),
          'frozen_target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'frozen_target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'selected_preview_due_amount_ex_vat', round(n.due_amount_ex_vat, 2),
          'component_preview_due_amount_ex_vat', round(n.take_target_ex, 2)
        )
      ) as frozen_component_snapshot_json,
      jsonb_strip_nulls(
        coalesce(n.saved_resolution_result_json, '{}'::jsonb)
        || jsonb_build_object(
          'target_pay_method', n.pay_channel,
          'target_amount_ex_vat', round(n.take_target_ex, 2),
          'target_amount_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'vat')::numeric
              else 0
            end,
            2
          ),
          'target_amount_inc_vat', round(
            case
              when n.pay_channel = 'UMBRELLA'
               and n.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
              then (public._pay_umbrella_vat_calc(round(n.take_target_ex, 2), v_vat_rate_pct, coalesce(u.vat_chargeable,false))->>'inc')::numeric
              else round(n.take_target_ex, 2)
            end,
            2
          ),
          'replacement_rate', n.target_rate,
          'source_rate', n.source_rate,
          'source_charge_rate', n.source_charge_rate,
          'source_charge_ex_vat', n.source_charge_ex_vat,
          'target_charge_ex_vat', n.target_charge_ex_vat,
          'target_margin_ex_vat', n.target_margin_ex_vat,
          'margin_delta_ex_vat', n.margin_delta_ex_vat
        )
      ) as frozen_resolution_result_json
    from normalized n
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = n.umbrella_id
    where n.take_target_ex > 0
  )
  select
    gen_random_uuid() as id,
    fa.pay_batch_candidate_id,
    'LOAN_REPAYMENT' as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    ('advance:' || fa.finance_case_id::text) as source_ref,
    (-fa.take_target_ex)::numeric(12,2) as amount_ex_vat,
    (-fa.take_target_vat)::numeric(12,2) as amount_vat,
    (-fa.take_target_inc)::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    fa.pay_channel as pay_channel,
    fa.umbrella_id as umbrella_id,
    (fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum and upper(coalesce(fa.source_pay_method,'')) <> upper(coalesce(fa.pay_channel,''))) as is_mismatch,
    false as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    fa.finance_case_id,
    null::uuid as reservation_id,
    case
      when fa.pay_channel <> 'PAYE' then 'NONE'
      when fa.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when fa.classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(nullif(fa.paye_treatment,''), 'NET_DEDUCT')
    end as paye_treatment,
    fa.finance_component_id,
    fa.frozen_component_snapshot_json,
    fa.component_key_type,
    fa.component_key_value,
    fa.classification,
    fa.source_basis_json,
    fa.source_pay_method,
    fa.pay_channel,
    fa.frozen_resolution_mode,
    fa.frozen_resolution_payload_json,
    fa.frozen_resolution_result_json,
    fa.take_source_amount,
    round(-fa.take_target_ex, 2),
    round(-fa.take_target_vat, 2),
    round(-fa.take_target_inc, 2)
  from final_alloc fa
  where fa.take_target_ex > 0;

  get diagnostics v_rows_ins_loan_items = row_count;


  update public.pay_batch_candidates pbc
  set
    loan_repayment_taken = coalesce((
      select round(sum(-pbi.amount_ex_vat), 2)
      from public.pay_batch_items pbi
      where pbi.pay_batch_candidate_id = pbc.id
        and pbi.is_voided = false
        and pbi.item_type = 'LOAN_REPAYMENT'
    ), 0)::numeric(12,2),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id;

  get diagnostics v_rows_upd_candidates_loan = row_count;

v_stage := 'STAGE_16BD_INSERT_DORMANT_RECOVERY_TEMPLATES';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  create temporary table if not exists pg_temp.tmp_pay_build_dormant_recovery_template_stage (
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    finance_case_id uuid not null,
    recovery_family text not null,
    paye_treatment text null,
    normalized_pay_channel text null,
    umbrella_id uuid null,
    source_ref text null,
    finance_component_id uuid null,
    frozen_component_snapshot_json jsonb null,
    frozen_component_key_type text null,
    frozen_component_key_value text null,
    frozen_component_classification public.pay_finance_component_classification_enum null,
    frozen_source_basis_json jsonb null,
    frozen_source_pay_method text null,
    frozen_target_pay_method text null,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
    frozen_resolution_payload_json jsonb null,
    frozen_resolution_result_json jsonb null,
    frozen_source_amount numeric(12,2) null,
    frozen_outstanding_amount numeric(12,2) null,
    weekly_due numeric(12,2) null,
    minimum_earnings_threshold numeric null,
    take_home_floor_override numeric null,
    default_take_home_floor numeric null,
    payout_status text null,
    next_due_week_start date null,
    sort_order integer null,
    duplicate_exists boolean not null
  ) on commit drop;
  truncate table pg_temp.tmp_pay_build_dormant_recovery_template_stage;

  insert into pg_temp.tmp_pay_build_dormant_recovery_template_stage (
    pay_batch_candidate_id,
    candidate_id,
    finance_case_id,
    recovery_family,
    paye_treatment,
    normalized_pay_channel,
    umbrella_id,
    source_ref,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_outstanding_amount,
    weekly_due,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor,
    payout_status,
    next_due_week_start,
    sort_order,
    duplicate_exists
  )
  select
    pbc.id as pay_batch_candidate_id,
    tr.candidate_id,
    tr.finance_case_id,
    tr.recovery_family,
    tr.paye_treatment,
    case
      when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
      when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
      else null::text
    end as normalized_pay_channel,
    tr.umbrella_id,
    coalesce(tr.source_ref, 'advance:' || tr.finance_case_id::text) as source_ref,
    tr.finance_component_id,
    tr.frozen_component_snapshot_json,
    tr.frozen_component_key_type,
    tr.frozen_component_key_value,
    tr.frozen_component_classification,
    tr.frozen_source_basis_json,
    tr.frozen_source_pay_method,
    coalesce(tr.frozen_target_pay_method,
      case
        when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
        when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
        else null::text
      end
    ) as frozen_target_pay_method,
    tr.frozen_resolution_mode,
    tr.frozen_resolution_payload_json,
    tr.frozen_resolution_result_json,
    tr.frozen_source_amount,
    tr.frozen_outstanding_amount,
    tr.weekly_due,
    tr.minimum_earnings_threshold,
    tr.take_home_floor_override,
    tr.default_take_home_floor,
    tr.payout_status,
    tr.next_due_week_start,
    tr.sort_order,
    exists (
      select 1
      from public.pay_batch_items as pbi_existing
      where pbi_existing.pay_batch_candidate_id = pbc.id
        and pbi_existing.finance_case_id = tr.finance_case_id
        and pbi_existing.item_type = tr.recovery_family
        and (
          (pbi_existing.finance_component_id is null and tr.finance_component_id is null)
          or pbi_existing.finance_component_id = tr.finance_component_id
        )
        and coalesce(pbi_existing.source_ref, '') = coalesce(coalesce(tr.source_ref, 'advance:' || tr.finance_case_id::text), '')
        and upper(coalesce(pbi_existing.pay_channel, '')) = upper(coalesce(
          case
            when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
            when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
            else null::text
          end,
          ''
        ))
    ) as duplicate_exists
  from pg_temp.tmp_pay_build_recovery_template_rows as tr
  join public.pay_batch_candidates as pbc
    on pbc.pay_batch_id = v_batch_id
   and pbc.candidate_id = tr.candidate_id
  where tr.candidate_id = any(v_candidate_ids)
    and coalesce(
      case
        when upper(coalesce(tr.pay_channel, '')) in ('PAYE', 'UMBRELLA') then upper(coalesce(tr.pay_channel, ''))
        when coalesce(btrim(coalesce(tr.pay_channel, '')), '') = '' and v_scope = 'PAYE' then 'PAYE'
        else null::text
      end,
      ''
    ) = v_scope;

  select count(*)::integer
  into v_rows_staged_recovery_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows;

  select count(*)::integer
  into v_rows_staged_manual_debt_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_staged_loan_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_staged_overpayment_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  select count(*)::integer
  into v_rows_staged_paye_manual_debt_template_rows
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
    and stage_rows.normalized_pay_channel = 'PAYE';

  select coalesce(
           jsonb_object_agg(stage_counts.candidate_id::text, to_jsonb(stage_counts.template_count) order by stage_counts.candidate_id::text),
           '{}'::jsonb
         )
  into v_staged_manual_debt_template_rows_by_candidate
  from (
    select stage_rows.candidate_id, count(*)::integer as template_count
    from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
    where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
      and stage_rows.normalized_pay_channel = 'PAYE'
    group by stage_rows.candidate_id
  ) as stage_counts;

  select count(*)::integer
  into v_rows_skipped_dormant_recovery_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true;

  select count(*)::integer
  into v_rows_skipped_dormant_manual_debt_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_skipped_dormant_loan_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_skipped_dormant_overpayment_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = true
    and stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  insert into public.pay_batch_items (
    id,
    pay_batch_candidate_id,
    item_type,
    timesheet_id,
    segment_key,
    source_ref,
    description,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    repayment_week_start,
    pay_channel,
    umbrella_id,
    is_mismatch,
    is_voided,
    created_at,
    updated_at,
    finance_case_id,
    reservation_id,
    paye_treatment,
    finance_component_id,
    frozen_component_snapshot_json,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_target_amount_ex_vat,
    frozen_target_amount_vat,
    frozen_target_amount_inc_vat,
    payout_instruction_snapshot_json
  )
  select
    gen_random_uuid() as id,
    stage_rows.pay_batch_candidate_id,
    stage_rows.recovery_family as item_type,
    null::uuid as timesheet_id,
    null::text as segment_key,
    stage_rows.source_ref,
    null::text as description,
    0::numeric(12,2) as amount_ex_vat,
    0::numeric(12,2) as amount_vat,
    0::numeric(12,2) as amount_inc_vat,
    v_week_start as repayment_week_start,
    stage_rows.normalized_pay_channel as pay_channel,
    stage_rows.umbrella_id as umbrella_id,
    (
      stage_rows.frozen_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and upper(coalesce(stage_rows.frozen_source_pay_method, '')) <> upper(coalesce(stage_rows.frozen_target_pay_method, stage_rows.normalized_pay_channel, ''))
    ) as is_mismatch,
    true as is_voided,
    v_now_utc as created_at,
    v_now_utc as updated_at,
    stage_rows.finance_case_id,
    null::uuid as reservation_id,
    case
      when stage_rows.normalized_pay_channel <> 'PAYE' then 'NONE'
      when stage_rows.frozen_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'GROSS_DEDUCT'
      when stage_rows.frozen_component_classification in ('NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum, 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum) then 'NET_DEDUCT'
      else coalesce(stage_rows.paye_treatment, 'NET_DEDUCT')
    end as paye_treatment,
    stage_rows.finance_component_id,
    stage_rows.frozen_component_snapshot_json,
    stage_rows.frozen_component_key_type,
    stage_rows.frozen_component_key_value,
    stage_rows.frozen_component_classification,
    jsonb_strip_nulls(
      coalesce(stage_rows.frozen_source_basis_json, '{}'::jsonb)
      || jsonb_build_object(
        'recovery_family', stage_rows.recovery_family,
        'source_ref', stage_rows.source_ref,
        'pay_channel', stage_rows.normalized_pay_channel,
        'frozen_source_pay_method', stage_rows.frozen_source_pay_method,
        'frozen_target_pay_method', stage_rows.frozen_target_pay_method,
        'frozen_source_amount', stage_rows.frozen_source_amount,
        'frozen_outstanding_amount', stage_rows.frozen_outstanding_amount,
        'weekly_due', stage_rows.weekly_due,
        'minimum_earnings_threshold', stage_rows.minimum_earnings_threshold,
        'take_home_floor_override', stage_rows.take_home_floor_override,
        'default_take_home_floor', stage_rows.default_take_home_floor,
        'payout_status', stage_rows.payout_status,
        'next_due_week_start', case when stage_rows.next_due_week_start is null then null else stage_rows.next_due_week_start::text end,
        'sort_order', stage_rows.sort_order
      )
    ) as frozen_source_basis_json,
    stage_rows.frozen_source_pay_method,
    coalesce(stage_rows.frozen_target_pay_method, stage_rows.normalized_pay_channel) as frozen_target_pay_method,
    stage_rows.frozen_resolution_mode,
    stage_rows.frozen_resolution_payload_json,
    stage_rows.frozen_resolution_result_json,
    coalesce(nullif(stage_rows.frozen_outstanding_amount, 0), stage_rows.frozen_source_amount, 0::numeric(12,2)) as frozen_source_amount,
    null::numeric as frozen_target_amount_ex_vat,
    null::numeric as frozen_target_amount_vat,
    null::numeric as frozen_target_amount_inc_vat,
    null::jsonb as payout_instruction_snapshot_json
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false;

  get diagnostics v_rows_ins_dormant_recovery_template_items = row_count;

  select count(*)::integer
  into v_rows_ins_dormant_manual_debt_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY';

  select count(*)::integer
  into v_rows_ins_dormant_loan_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'LOAN_REPAYMENT';

  select count(*)::integer
  into v_rows_ins_dormant_overpayment_template_items
  from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
  where stage_rows.duplicate_exists = false
    and stage_rows.recovery_family = 'OVERPAYMENT_RECOVERY';

  if v_rows_staged_paye_manual_debt_template_rows > 0 then
    select coalesce(array_agg(missing_rows.candidate_id order by missing_rows.candidate_id), ARRAY[]::uuid[])
    into v_missing_materialised_manual_debt_template_candidate_ids
    from (
      select distinct stage_rows.candidate_id
      from pg_temp.tmp_pay_build_dormant_recovery_template_stage as stage_rows
      where stage_rows.recovery_family = 'MANUAL_DEBT_RECOVERY'
        and stage_rows.normalized_pay_channel = 'PAYE'
    ) as missing_rows
    left join (
      select distinct pbc.candidate_id
      from public.pay_batch_items as pbi_materialised
      join public.pay_batch_candidates as pbc
        on pbc.id = pbi_materialised.pay_batch_candidate_id
      where pbc.pay_batch_id = v_batch_id
        and pbi_materialised.item_type = 'MANUAL_DEBT_RECOVERY'
        and upper(coalesce(pbi_materialised.pay_channel, '')) = 'PAYE'
    ) as materialised_rows
      on materialised_rows.candidate_id = missing_rows.candidate_id
    where materialised_rows.candidate_id is null;

    if coalesce(array_length(v_missing_materialised_manual_debt_template_candidate_ids, 1), 0) > 0 then
      raise exception 'MANUAL_DEBT_TEMPLATE_NOT_MATERIALISED: staged PAYE manual-debt templates did not materialise into pay_batch_items for candidates %',
        array_to_string(v_missing_materialised_manual_debt_template_candidate_ids, ',');
    end if;
  end if;

v_stage := 'STAGE_16C1_FREEZE_ALL_FINANCE_ITEM_PAYOUT_INSTRUCTIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'helper_exists', false,
        'mode', 'STAGED_PREVIEW_FINANCE_PAYOUT_AUTHORITY'
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;


  v_stage := 'STAGE_16C2_ENRICH_FINANCE_PAYOUT_INSTRUCTION_EXEC_FIELDS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;


  update public.pay_batch_items as pbi_set
  set payout_instruction_snapshot_json = pbi_src.payout_instruction_snapshot_json
  from (
    with finance_case_preview_ctx as (
      select distinct on (spr.finance_case_id)
        spr.finance_case_id,
        spr.timesheet_id as linked_timesheet_id,
        upper(coalesce(spr.pay_channel, '')) as preview_pay_channel,
        nullif(btrim(coalesce(spr.routing_kind, '')), '') as routing_kind,
        nullif(btrim(coalesce(spr.destination_label, '')), '') as destination_label,
        nullif(btrim(coalesce(spr.taxability, '')), '') as taxability,
        nullif(btrim(coalesce(spr.beneficiary_name, '')), '') as beneficiary_name,
        nullif(btrim(coalesce(spr.masked_bank_account, '')), '') as masked_bank_account,
        nullif(btrim(coalesce(spr.bank_details_hash, '')), '') as bank_details_hash,
        coalesce(spr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
        coalesce(spr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
        coalesce(spr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice
      from pg_temp.tmp_pay_build_selected_preview_rows spr
      where spr.finance_case_id is not null
      order by spr.finance_case_id, spr.preview_row_id
    )
    select
      pbi.id as pay_batch_item_id,
      jsonb_strip_nulls(
        coalesce(pbi.payout_instruction_snapshot_json, '{}'::jsonb)
        || jsonb_build_object(
          'taxability',
            coalesce(
              nullif(btrim(coalesce(fpc.taxability, '')), ''),
              case when pbi.frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum then 'NON_TAXABLE' else 'TAXABLE' end
            ),
          'routing_kind',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')), ''),
              nullif(btrim(coalesce(fpc.routing_kind, '')), ''),
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'UMBRELLA_COMPANY' else 'NORMAL_PAY_ROUTE' end
            ),
          'destination_label',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'destination_label', '')), ''),
              nullif(btrim(coalesce(fpc.destination_label, '')), ''),
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then 'umbrella company' else 'normal PAYE route' end
            ),
          'pay_channel', upper(coalesce(pbi.pay_channel::text, '')),
          'payee_entity_kind',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then 'UMBRELLA'
              else 'CANDIDATE'
            end,
          'payee_entity_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then pbc.candidate_id::text
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and coalesce(pbi.umbrella_id, c.umbrella_id) is not null then coalesce(pbi.umbrella_id, c.umbrella_id)::text
              else pbc.candidate_id::text
            end,
          'beneficiary_name',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'beneficiary_name', '')), ''),
              nullif(btrim(coalesce(fpc.beneficiary_name, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(btrim(coalesce(obd.beneficiary_name, '')), '')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false
                  then nullif(btrim(coalesce(u.name, '')), '')
                else nullif(btrim(coalesce(c.account_holder, c.display_name, concat_ws(' ', c.first_name, c.last_name))), '')
              end
            ),
          'sort_code',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'sort_code', '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and length(coalesce(obd.sort_code, '')) = 6
                  then substr(obd.sort_code, 1, 2) || '-' || substr(obd.sort_code, 3, 2) || '-' || substr(obd.sort_code, 5, 2)
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and length(coalesce(u.sort_code, '')) = 6
                  then substr(u.sort_code, 1, 2) || '-' || substr(u.sort_code, 3, 2) || '-' || substr(u.sort_code, 5, 2)
                when length(coalesce(c.sort_code, '')) = 6
                  then substr(c.sort_code, 1, 2) || '-' || substr(c.sort_code, 3, 2) || '-' || substr(c.sort_code, 5, 2)
                else null
              end
            ),
          'account_number',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_number', '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                  then nullif(obd.account_number, '')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false
                  then nullif(u.account_number, '')
                else nullif(c.account_number, '')
              end
            ),
          'account_type',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'account_type', '')), ''),
              case
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then 'Business'
                else 'Personal'
              end
            ),
          'masked_bank_account',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'masked_bank_account', '')), ''),
              nullif(btrim(coalesce(fpc.masked_bank_account, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                 and nullif(coalesce(obd.account_number, ''), '') is not null
                  then lpad(right(obd.account_number, 4), length(obd.account_number), '*')
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false and nullif(coalesce(u.account_number, ''), '') is not null
                  then lpad(right(u.account_number, 4), length(u.account_number), '*')
                when nullif(coalesce(c.account_number, ''), '') is not null
                  then lpad(right(c.account_number, 4), length(c.account_number), '*')
                else null
              end
            ),
          'bank_details_hash',
            coalesce(
              nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash', '')), ''),
              nullif(btrim(coalesce(fpc.bank_details_hash, '')), ''),
              case
                when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then obd.bank_details_hash
                when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then u.bank_details_hash
                else c.bank_details_hash
              end
            ),
          'bank_details_note', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_note', '')), ''), obd.note),
          'bank_details_created_by_user_id', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id', '')), ''), case when obd.created_by_user_id is null then null else obd.created_by_user_id::text end),
          'bank_details_updated_by_user_id', coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id', '')), ''), case when obd.updated_by_user_id is null then null else obd.updated_by_user_id::text end),
          'week_ending_bucket',
            case
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA'
               and upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) <> 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
                then coalesce(case when ts_ctx.week_ending_date is null then null else ts_ctx.week_ending_date::text end, (v_week_start + 6)::text)
              else null
            end,
          'rail_provider', upper(btrim(coalesce(pb.rail_provider_snapshot, ''))),
          'rail_env', upper(btrim(coalesce(pb.rail_env_snapshot, ''))),
          'payee_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then case when c.payee_id is null then null else c.payee_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then case when u.payee_id is null then null else u.payee_id::text end
              else case when c.payee_id is null then null else c.payee_id::text end
            end,
          'payee_account_id',
            case
              when upper(coalesce(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', fpc.routing_kind), '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then case when c.payee_account_id is null then null else c.payee_account_id::text end
              when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' and coalesce(fpc.is_candidate_directed_oneoff_payout, false) = false then case when u.payee_account_id is null then null else u.payee_account_id::text end
              else case when c.payee_account_id is null then null else c.payee_account_id::text end
            end,
          'appears_on_umbrella_remittance',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance')::boolean,
              fpc.appears_on_umbrella_remittance,
              case when upper(coalesce(pbi.pay_channel::text, '')) = 'UMBRELLA' then true else false end
            ),
          'generates_candidate_payment_advice',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice')::boolean,
              fpc.generates_candidate_payment_advice,
              false
            ),
          'is_candidate_directed_oneoff_payout',
            coalesce(
              (pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout')::boolean,
              fpc.is_candidate_directed_oneoff_payout,
              false
            )
        )
      ) as payout_instruction_snapshot_json
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    join pg_temp.tmp_pay_build_candidates_ctx as c
      on c.id = pbc.candidate_id
    left join pg_temp.tmp_pay_build_umbrellas_ctx as u
      on u.id = coalesce(pbi.umbrella_id, c.umbrella_id)
    left join finance_case_preview_ctx as fpc
      on fpc.finance_case_id = pbi.finance_case_id
    left join pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx as obd
      on obd.finance_case_id = pbi.finance_case_id
    left join pg_temp.tmp_pay_build_timesheet_snapshots_ctx as ts_ctx
      on ts_ctx.timesheet_id = coalesce(pbi.timesheet_id, fpc.linked_timesheet_id)
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.finance_case_id is not null
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','LOAN_REPAYMENT')
  ) as pbi_src
  where pbi_set.id = pbi_src.pay_batch_item_id;


  IF p_operation_id IS NOT NULL THEN
    WITH allocation_matches AS (
      SELECT DISTINCT ON (allocation_row.id)
        allocation_row.id AS allocation_row_id,
        batch_item.id AS pay_batch_item_id,
        allocation_row.operation_source_key AS operation_source_key
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.pay_batch_id = v_batch_id
       AND batch_candidate.candidate_id = allocation_row.candidate_id
      JOIN public.pay_batch_items AS batch_item
        ON batch_item.pay_batch_candidate_id = batch_candidate.id
       AND batch_item.finance_case_id IS NOT DISTINCT FROM allocation_row.finance_case_id
       AND batch_item.finance_component_id IS NOT DISTINCT FROM allocation_row.finance_component_id
       AND round(abs(coalesce(batch_item.amount_ex_vat, 0)), 2) = round(abs(coalesce(allocation_row.allocated_amount, 0)), 2)
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.candidate_id = ANY(v_candidate_ids)
        AND allocation_row.pay_channel = v_scope
        AND coalesce(batch_item.is_voided, false) = false
      ORDER BY allocation_row.id, batch_item.created_at NULLS LAST, batch_item.id
    ),
    updated_items AS (
      UPDATE public.pay_batch_items AS batch_item_update
      SET
        operation_source_key = allocation_matches.operation_source_key,
        updated_at = now()
      FROM allocation_matches
      WHERE batch_item_update.id = allocation_matches.pay_batch_item_id
        AND batch_item_update.operation_source_key IS DISTINCT FROM allocation_matches.operation_source_key
      RETURNING batch_item_update.id
    )
    UPDATE public.banking_pay_operation_candidate_allocation_rows AS allocation_update
    SET
      status = 'ITEM_CREATED',
      pay_batch_id = v_batch_id,
      pay_batch_item_id = allocation_matches.pay_batch_item_id,
      updated_at_utc = now()
    FROM allocation_matches
    WHERE allocation_update.id = allocation_matches.allocation_row_id
      AND (allocation_update.status <> 'ITEM_CREATED' OR allocation_update.pay_batch_item_id IS DISTINCT FROM allocation_matches.pay_batch_item_id);

    SELECT jsonb_build_object(
             'allocation_rows_total', count(*)::integer,
             'allocation_rows_unlinked', count(*) FILTER (WHERE allocation_row.status <> 'ITEM_CREATED' OR allocation_row.pay_batch_item_id IS NULL)::integer
           )
    INTO v_operation_mismatch_details
    FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
    WHERE allocation_row.operation_id = p_operation_id
      AND allocation_row.candidate_id = ANY(v_candidate_ids)
      AND allocation_row.pay_channel = v_scope;

    IF coalesce((v_operation_mismatch_details->>'allocation_rows_unlinked')::integer, 0) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_APPLY_FINANCE_ADJUSTMENTS',
        'code', 'OPERATION_ALLOCATION_ROWS_NOT_LINKED',
        'message', 'pay_batch_apply_finance_adjustments could not link every operation allocation row to a created pay batch item',
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pay_channel_scope', v_scope,
        'mismatch_details', v_operation_mismatch_details
      )::text;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'pay_channel_scope', v_scope,
    'applied_count', (coalesce(v_rows_ins_loan_payout_items, 0) + coalesce(v_rows_ins_manual_credit_payout_items, 0) + coalesce(v_rows_ins_overpayment_recovery_items, 0) + coalesce(v_rows_ins_debt_items, 0) + coalesce(v_rows_ins_loan_items, 0) + coalesce(v_rows_ins_dormant_recovery_template_items, 0) + coalesce(v_rows_ins_dormant_manual_debt_template_items, 0) + coalesce(v_rows_ins_dormant_loan_template_items, 0) + coalesce(v_rows_ins_dormant_overpayment_template_items, 0)),
    'reused_count', coalesce(v_operation_allocation_done, 0),
    'skipped_count', (coalesce(v_rows_skipped_dormant_recovery_template_items, 0) + coalesce(v_rows_skipped_dormant_manual_debt_template_items, 0) + coalesce(v_rows_skipped_dormant_loan_template_items, 0) + coalesce(v_rows_skipped_dormant_overpayment_template_items, 0)),
    'failed_count', 0,
    'mismatch_details', coalesce(v_operation_mismatch_details, '{}'::jsonb),
    'loan_payout_items_inserted', coalesce(v_rows_ins_loan_payout_items, 0),
    'manual_credit_payout_items_inserted', coalesce(v_rows_ins_manual_credit_payout_items, 0),
    'overpayment_recovery_items_inserted', coalesce(v_rows_ins_overpayment_recovery_items, 0),
    'manual_debt_recovery_items_inserted', coalesce(v_rows_ins_debt_items, 0),
    'loan_repayment_items_inserted', coalesce(v_rows_ins_loan_items, 0),
    'staged_recovery_template_rows', coalesce(v_rows_staged_recovery_template_rows, 0),
    'staged_manual_debt_template_rows', coalesce(v_rows_staged_manual_debt_template_rows, 0),
    'staged_loan_template_rows', coalesce(v_rows_staged_loan_template_rows, 0),
    'staged_overpayment_template_rows', coalesce(v_rows_staged_overpayment_template_rows, 0),
    'staged_paye_manual_debt_template_rows', coalesce(v_rows_staged_paye_manual_debt_template_rows, 0),
    'staged_manual_debt_template_rows_by_candidate', coalesce(v_staged_manual_debt_template_rows_by_candidate, '{}'::jsonb),
    'dormant_recovery_template_items_inserted', coalesce(v_rows_ins_dormant_recovery_template_items, 0),
    'dormant_manual_debt_template_items_inserted', coalesce(v_rows_ins_dormant_manual_debt_template_items, 0),
    'dormant_loan_template_items_inserted', coalesce(v_rows_ins_dormant_loan_template_items, 0),
    'dormant_overpayment_template_items_inserted', coalesce(v_rows_ins_dormant_overpayment_template_items, 0),
    'dormant_recovery_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_recovery_template_items, 0),
    'dormant_manual_debt_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_manual_debt_template_items, 0),
    'dormant_loan_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_loan_template_items, 0),
    'dormant_overpayment_template_items_skipped_as_duplicate', coalesce(v_rows_skipped_dormant_overpayment_template_items, 0)
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_batch_finalize_reservations_and_markers(uuid, text, uuid, date, date);
DROP FUNCTION IF EXISTS public.pay_batch_finalize_reservations_and_markers(uuid, text, uuid, date, date, uuid, jsonb);



CREATE OR REPLACE FUNCTION public.pay_batch_finalize_reservations_and_markers(p_pay_batch_id uuid, p_pay_channel_scope text, p_actor_user_id uuid DEFAULT NULL::uuid, p_pay_date date DEFAULT NULL::date, p_week_start date DEFAULT NULL::date, p_operation_id uuid DEFAULT NULL::uuid, p_candidate_scope_ids jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_week_start date := p_week_start;
  v_now_utc timestamptz := now();
  v_stage text := NULL;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_rows_before_empty_delete integer := 0;
  v_rows_del_candidates integer := 0;
  v_candidate_rows_after_empty_delete integer := 0;
  v_selected_preview_row_ids_present boolean := true;
  v_selected_preview_rows_supplied boolean := true;
  v_selected_preview_rows_mode text := 'PREVIEW_PAYLOAD';
  v_selected_preview_rows_pre_selection_ct integer := 0;
  v_selected_preview_rows_post_selection_ct integer := 0;
  v_reserved jsonb := '[]'::jsonb;
  v_stage_15_reserved_key_count integer := 0;
  v_stage_15_outstanding_key_count integer := 0;
  v_stage_15_current_batch_key_count integer := 0;
  v_stage_15_reserved_keys_sample jsonb := '[]'::jsonb;
  v_stage_15_outstanding_keys_sample jsonb := '[]'::jsonb;
  v_stage_15_current_batch_keys_sample jsonb := '[]'::jsonb;
  v_stage_15_ts_ids_sample jsonb := '[]'::jsonb;
  v_stage_15_current_batch_items_sample jsonb := '[]'::jsonb;
  v_stage_15_current_batch_keyed_sample jsonb := '[]'::jsonb;
  v_stage_15_checks_sample jsonb := '[]'::jsonb;
  v_rows_upd_candidates_paye_awaiting integer := 0;
  v_rows_upd_candidates_debt integer := 0;
  v_rows_ins_debt_items integer := 0;
  v_rows_ins_reservations integer := 0;
  v_rows_reused_reservations integer := 0;
  v_rows_already_linked_reservations integer := 0;
  v_rows_preexisting_unlinked_reservations integer := 0;
  v_rows_mismatched_linked_reservations integer := 0;
  v_failed_count integer := 0;
  v_nothing_payable_due_to_reservation boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;
  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;
  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );

    SELECT settings_context.pay_week_start
    INTO v_week_start
    FROM pg_temp.tmp_pay_build_settings_context AS settings_context
    LIMIT 1;
  END IF;

  IF v_week_start IS NULL THEN
    RAISE EXCEPTION 'week_start is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_selected_preview_rows temp table is required';
  END IF;

  SELECT count(*)::int INTO v_selected_preview_rows_pre_selection_ct FROM pg_temp.tmp_pay_build_selected_preview_rows;
  v_selected_preview_rows_post_selection_ct := v_selected_preview_rows_pre_selection_ct;
  SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr;


v_stage := 'STAGE_13_DELETE_EMPTY_CANDIDATES';

  -- Remove any candidate rows that ended up with no items for this scoped batch
  select count(*)::int
  into v_candidate_rows_before_empty_delete
  from public.pay_batch_candidates pbc_before
  where pbc_before.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc_before.candidate_id = any(v_candidate_ids));

  delete from public.pay_batch_candidates pbc_del
  where pbc_del.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc_del.candidate_id = any(v_candidate_ids))
    and not exists (
      select 1
      from public.pay_batch_items pbi_chk
      where pbi_chk.pay_batch_candidate_id = pbc_del.id
        and pbi_chk.item_type <> 'DEBT_CREATED'
      limit 1
    );

  GET DIAGNOSTICS v_rows_del_candidates = ROW_COUNT;

  select count(*)::int
  into v_candidate_rows_after_empty_delete
  from public.pay_batch_candidates pbc_after
  where pbc_after.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc_after.candidate_id = any(v_candidate_ids));

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_13_EMPTY_CANDIDATES_DELETED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
        'deleted_candidate_rows', v_rows_del_candidates,
        'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  v_stage := 'STAGE_14_ASSERT_ANY_CANDIDATES_REMAIN';

  if not exists (
    select 1
    from public.pay_batch_candidates pbc_any
    where pbc_any.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc_any.candidate_id = any(v_candidate_ids))
    limit 1
  ) then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_NOTHING_TO_PAY_FOR_SCOPE_AFTER_BLOCKERS',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'scope', v_scope,
          'selected_preview_row_ids_present', v_selected_preview_row_ids_present,
          'selected_preview_rows_supplied', v_selected_preview_rows_supplied,
          'selected_preview_rows_mode', v_selected_preview_rows_mode,
          'selected_preview_rows_pre_selection_ct', v_selected_preview_rows_pre_selection_ct,
          'selected_preview_rows_post_selection_ct', v_selected_preview_rows_post_selection_ct,
          'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
          'deleted_candidate_rows', v_rows_del_candidates,
          'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete,
          'error', 'Nothing to pay (no payable items for scope after blockers)'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', true,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'nothing_payable_after_reservation_exclusion', EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_candidate_scope AS scope_row
          WHERE scope_row.operation_id = p_operation_id
            AND scope_row.pay_batch_id = v_batch_id
            AND (jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability}') = 'object')
            AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) IN ('true','t','1','yes','y')
        ),
        'message', CASE
          WHEN EXISTS (
            SELECT 1
            FROM public.banking_pay_operation_candidate_scope AS scope_row
            WHERE scope_row.operation_id = p_operation_id
              AND scope_row.pay_batch_id = v_batch_id
              AND (jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability}') = 'object')
              AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) IN ('true','t','1','yes','y')
          )
            THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
          ELSE 'Nothing to pay (no payable items for scope after blockers)'
        END,
        'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
        'deleted_candidate_rows', v_rows_del_candidates,
        'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete
      );
    END IF;

    IF to_regclass('pg_temp.tmp_pay_build_reservation_availability_report') IS NOT NULL THEN
      EXECUTE 'SELECT EXISTS (SELECT 1 FROM pg_temp.tmp_pay_build_reservation_availability_report WHERE availability_action = ''SKIP_ALREADY_RESERVED'')'
      INTO v_nothing_payable_due_to_reservation;
    END IF;

    IF coalesce(v_nothing_payable_due_to_reservation, false) THEN
      raise exception '%', jsonb_build_object(
        'error', 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED',
        'message', 'No draft was created because all selected payments are already reserved in another active draft batch.',
        'pay_batch_id', v_batch_id::text,
        'scope', v_scope,
        'stage', v_stage
      )::text;
    END IF;

    raise exception 'Nothing to pay (no payable items for scope % after blockers)', v_scope;
  end if;

  v_stage := 'STAGE_15_DOUBLE_PAY_CONFLICT_CHECK';

  with current_batch_item_resolution as (
    select
      pbi.id as pay_batch_item_id,
      pbi.timesheet_id,
      pbi.item_type,
      ec.key_type,
      ec.key_value,
      ec.source_amount_ex_vat,
      ec.key_resolution_failure_reason
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join lateral public._pay_batch_item_economic_components(null::uuid, array[pbi.id]::uuid[]) as ec
      on true
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
      and pbi.timesheet_id is not null
      and coalesce(pbi.is_voided,false) = false
      and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
  ),
  invalid_current_batch_items as (
    select
      cbir.pay_batch_item_id,
      cbir.timesheet_id,
      cbir.item_type,
      cbir.key_type,
      cbir.key_value,
      cbir.source_amount_ex_vat,
      case
        when cbir.key_resolution_failure_reason is not null then cbir.key_resolution_failure_reason
        when cbir.key_type is null or btrim(coalesce(cbir.key_type,'')) = '' then 'MISSING_ECONOMIC_KEY_TYPE'
        when cbir.key_value is null or btrim(coalesce(cbir.key_value,'')) = '' then 'MISSING_ECONOMIC_KEY_VALUE'
        when cbir.key_type = 'TS_DAY' and cbir.key_value !~ '^\d{4}-\d{2}-\d{2}$' then 'INVALID_TS_DAY_KEY_VALUE'
        when cbir.source_amount_ex_vat is null then 'MISSING_SOURCE_RESERVATION_AMOUNT'
        else null
      end as failure_reason
    from current_batch_item_resolution cbir
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'pay_batch_item_id', invalid_current_batch_items.pay_batch_item_id::text,
        'timesheet_id', invalid_current_batch_items.timesheet_id::text,
        'item_type', invalid_current_batch_items.item_type,
        'key_type', invalid_current_batch_items.key_type,
        'key_value', invalid_current_batch_items.key_value,
        'source_amount_ex_vat', invalid_current_batch_items.source_amount_ex_vat,
        'failure_reason', invalid_current_batch_items.failure_reason
      )
      order by invalid_current_batch_items.pay_batch_item_id::text
    ),
    '[]'::jsonb
  )
  into v_reserved
  from invalid_current_batch_items
  where invalid_current_batch_items.failure_reason is not null;

  if jsonb_array_length(v_reserved) > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_ITEM_ECONOMIC_KEY_OR_SOURCE_RESOLUTION_FAILED',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text,
      'items', v_reserved
    )::text;
  end if;

  v_reserved := '[]'::jsonb;

  -- Policy X: numeric reservation overrun check (stable keys).
  -- Validate that THIS draft batch has not introduced or worsened an overrun on any
  -- stable key. Pre-existing stale reservations in other active batches must not block
  -- creation of a new draft; only new/worsened overrun caused by the current draft is an error.
  -- Stable keys come from _pay_outstanding_components / _pay_reserved_components:
  --   key_type: TS_DAY, TS_TOTAL, ADDITIONAL_CODE, ADJUSTMENT_CODE, EXPENSE_CODE
  --   key_value: work_date / TOTAL / adjustment_id / code
  --
  -- tolerance: 0.01 to avoid rounding noise false positives.
  with ts_ids_arr as (
    select
      array_agg(distinct pbi.timesheet_id) as timesheet_ids
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
      and pbi.timesheet_id is not null
  ),
  reserved_raw as (
    select
      to_jsonb(rc) as j
    from public._pay_reserved_components((select t.timesheet_ids from ts_ids_arr t)) rc
  ),
  reserved_rows as (
    select
      nullif(btrim(coalesce(r.j->>'timesheet_id','')), '')::uuid as timesheet_id,
      upper(nullif(btrim(coalesce(r.j->>'key_type','')), '')) as key_type,
      nullif(btrim(coalesce(r.j->>'key_value','')), '') as key_value,
      round(
        coalesce(
          nullif(r.j->>'reserved_ex_vat','')::numeric,
          nullif(r.j->>'reserved_ex','')::numeric,
          nullif(r.j->>'reserved','')::numeric,
          nullif(r.j->>'amount_ex_vat','')::numeric,
          nullif(r.j->>'amount','')::numeric,
          0
        ),
        2
      ) as reserved_ex_vat
    from reserved_raw r
    where nullif(btrim(coalesce(r.j->>'timesheet_id','')), '') is not null
      and nullif(btrim(coalesce(r.j->>'key_type','')), '') is not null
      and nullif(btrim(coalesce(r.j->>'key_value','')), '') is not null
  ),
  reserved_sums as (
    select
      rr.timesheet_id,
      rr.key_type,
      rr.key_value,
      round(sum(coalesce(rr.reserved_ex_vat,0)),2) as reserved_ex_vat
    from reserved_rows rr
    where rr.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    group by rr.timesheet_id, rr.key_type, rr.key_value
  ),
  outstanding_raw as (
    select
      to_jsonb(oc) as j
    from public._pay_outstanding_components((select t.timesheet_ids from ts_ids_arr t)) oc
  ),
  outstanding_rows_raw as (
    select
      nullif(btrim(coalesce(o.j->>'timesheet_id','')), '')::uuid as timesheet_id,
      upper(nullif(btrim(coalesce(o.j->>'key_type','')), '')) as key_type,
      nullif(btrim(coalesce(o.j->>'key_value','')), '') as key_value,
      round(
        coalesce(
          nullif(o.j->>'outstanding_ex_vat','')::numeric,
          nullif(o.j->>'outstanding_ex','')::numeric,
          nullif(o.j->>'outstanding','')::numeric,
          nullif(o.j->>'amount_ex_vat','')::numeric,
          nullif(o.j->>'amount','')::numeric,
          0
        ),
        2
      ) as outstanding_ex_vat
    from outstanding_raw o
    where nullif(btrim(coalesce(o.j->>'timesheet_id','')), '') is not null
      and nullif(btrim(coalesce(o.j->>'key_type','')), '') is not null
      and nullif(btrim(coalesce(o.j->>'key_value','')), '') is not null
  ),
  outstanding_rows as (
    select distinct on (orw_raw.timesheet_id, orw_raw.key_type, orw_raw.key_value)
      orw_raw.timesheet_id,
      orw_raw.key_type,
      orw_raw.key_value,
      round(coalesce(orw_raw.outstanding_ex_vat, 0), 2) as outstanding_ex_vat
    from outstanding_rows_raw orw_raw
    order by
      orw_raw.timesheet_id,
      orw_raw.key_type,
      orw_raw.key_value,
      coalesce(orw_raw.outstanding_ex_vat, 0) desc
  ),
  current_batch_items as (
    select
      pbi.id as pay_batch_item_id,
      pbc.pay_batch_id as pay_batch_id,
      pbi.timesheet_id as timesheet_id,
      pbi.item_type as item_type,
      pbi.segment_key as segment_key,
      pbi.source_ref as source_ref,
      pbi.finance_component_id as finance_component_id,
      pbi.frozen_component_key_type as frozen_component_key_type,
      pbi.frozen_component_key_value as frozen_component_key_value,
      pbi.frozen_component_snapshot_json as frozen_component_snapshot_json,
      pbi.frozen_source_basis_json as frozen_source_basis_json,
      null::text as live_component_key_type,
      null::text as live_component_key_value,
      public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id) as source_reservation_amount_ex_vat
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
      and pbi.timesheet_id is not null
      and coalesce(pbi.is_voided,false) = false
      and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
  ),
  current_batch_keyed as (
    select
      ec.timesheet_id,
      ec.key_type,
      ec.key_value,
      round(coalesce(ec.source_amount_ex_vat, 0), 2) as amount_ex_vat
    from current_batch_items cbi
    join lateral public._pay_batch_item_economic_components(null::uuid, array[cbi.pay_batch_item_id]::uuid[]) as ec
      on true
    where ec.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
      and ec.key_resolution_failure_reason is null
      and ec.source_amount_ex_vat is not null
      and ec.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
      and ec.key_value is not null
      and btrim(ec.key_value) <> ''
      and not (ec.key_type = 'TS_DAY' and ec.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  ),
  current_batch_reserved_sums as (
    select
      c.timesheet_id,
      c.key_type,
      c.key_value,
      round(sum(coalesce(c.amount_ex_vat,0)),2) as current_batch_reserved_ex_vat
    from current_batch_keyed c
    where c.key_value is not null
      and btrim(coalesce(c.key_value,'')) <> ''
      and c.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    group by c.timesheet_id, c.key_type, c.key_value
  ),
  key_union as (
    select rs.timesheet_id, rs.key_type, rs.key_value
    from reserved_sums rs
    union
    select orw.timesheet_id, orw.key_type, orw.key_value
    from outstanding_rows orw
    where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    union
    select cbr.timesheet_id, cbr.key_type, cbr.key_value
    from current_batch_reserved_sums cbr
  ),
  ts_total_day_fallback as (
    select
      orw.timesheet_id,
      round(
        sum(
          case
            when orw.key_type = 'TS_DAY' and coalesce(orw.outstanding_ex_vat,0) > 0
              then coalesce(orw.outstanding_ex_vat,0)
            else 0
          end
        ),
        2
      ) as ts_total_payable_fallback_ex_vat
    from outstanding_rows orw
    group by orw.timesheet_id
  ),
  checks as (
    select
      ku.timesheet_id,
      ku.key_type,
      ku.key_value,
      round(coalesce(rs.reserved_ex_vat,0),2) as reserved_total_ex_vat,
      round(coalesce(cbr.current_batch_reserved_ex_vat,0),2) as current_batch_reserved_ex_vat,
      round(greatest(coalesce(rs.reserved_ex_vat,0) - coalesce(cbr.current_batch_reserved_ex_vat,0), 0),2) as reserved_before_ex_vat,
      case
        when ku.key_type = 'TS_TOTAL'
         and orw.timesheet_id is null
        then round(greatest(coalesce(tdf.ts_total_payable_fallback_ex_vat,0), 0), 2)
        else round(
          greatest(
            coalesce(rs.reserved_ex_vat,0) + coalesce(orw.outstanding_ex_vat,0),
            0
          ),
          2
        )
      end as payable_possible_ex_vat,
      0.01::numeric as tolerance_ex_vat
    from key_union ku
    left join reserved_sums rs
      on rs.timesheet_id = ku.timesheet_id
     and rs.key_type = ku.key_type
     and rs.key_value = ku.key_value
    left join outstanding_rows orw
      on orw.timesheet_id = ku.timesheet_id
     and orw.key_type = ku.key_type
     and orw.key_value = ku.key_value
    left join current_batch_reserved_sums cbr
      on cbr.timesheet_id = ku.timesheet_id
     and cbr.key_type = ku.key_type
     and cbr.key_value = ku.key_value
    left join ts_total_day_fallback tdf
      on tdf.timesheet_id = ku.timesheet_id
  ),
  overruns as (
    select
      c.timesheet_id,
      c.key_type,
      c.key_value,
      c.reserved_total_ex_vat,
      c.current_batch_reserved_ex_vat,
      c.reserved_before_ex_vat,
      c.payable_possible_ex_vat,
      round(greatest(c.reserved_total_ex_vat - c.payable_possible_ex_vat, 0),2) as overrun_after_ex_vat,
      round(greatest(c.reserved_before_ex_vat - c.payable_possible_ex_vat, 0),2) as overrun_before_ex_vat,
      c.tolerance_ex_vat
    from checks c
    where round(greatest(c.reserved_total_ex_vat - c.payable_possible_ex_vat, 0),2)
            > round(greatest(c.reserved_before_ex_vat - c.payable_possible_ex_vat, 0),2) + c.tolerance_ex_vat
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'timesheet_id', overruns.timesheet_id::text,
          'key_type', overruns.key_type,
          'key_value', overruns.key_value,
          'reserved_total_ex_vat', overruns.reserved_total_ex_vat,
          'current_batch_reserved_ex_vat', overruns.current_batch_reserved_ex_vat,
          'reserved_before_ex_vat', overruns.reserved_before_ex_vat,
          'payable_possible_ex_vat', overruns.payable_possible_ex_vat,
          'overrun_before_ex_vat', overruns.overrun_before_ex_vat,
          'overrun_after_ex_vat', overruns.overrun_after_ex_vat,
          'tolerance_ex_vat', overruns.tolerance_ex_vat
        )
        order by overruns.timesheet_id::text, overruns.key_type, overruns.key_value
      ),
      '[]'::jsonb
    ),
    (select count(*)::int from reserved_sums),
    (select count(*)::int from outstanding_rows orw where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')),
    (select count(*)::int from current_batch_reserved_sums),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', rs.timesheet_id::text,
            'key_type', rs.key_type,
            'key_value', rs.key_value,
            'reserved_ex_vat', rs.reserved_ex_vat
          )
          order by rs.timesheet_id::text, rs.key_type, rs.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          rs.timesheet_id,
          rs.key_type,
          rs.key_value,
          rs.reserved_ex_vat
        from reserved_sums rs
        order by rs.timesheet_id::text, rs.key_type, rs.key_value
        limit 50
      ) rs
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', orw.timesheet_id::text,
            'key_type', orw.key_type,
            'key_value', orw.key_value,
            'outstanding_ex_vat', orw.outstanding_ex_vat
          )
          order by orw.timesheet_id::text, orw.key_type, orw.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          orw.timesheet_id,
          orw.key_type,
          orw.key_value,
          orw.outstanding_ex_vat
        from outstanding_rows orw
        where orw.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        order by orw.timesheet_id::text, orw.key_type, orw.key_value
        limit 50
      ) orw
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', cbr.timesheet_id::text,
            'key_type', cbr.key_type,
            'key_value', cbr.key_value,
            'current_batch_reserved_ex_vat', cbr.current_batch_reserved_ex_vat
          )
          order by cbr.timesheet_id::text, cbr.key_type, cbr.key_value
        ),
        '[]'::jsonb
      )
      from (
        select
          cbr.timesheet_id,
          cbr.key_type,
          cbr.key_value,
          cbr.current_batch_reserved_ex_vat
        from current_batch_reserved_sums cbr
        order by cbr.timesheet_id::text, cbr.key_type, cbr.key_value
        limit 50
      ) cbr
    ),
    (
      select coalesce(
        jsonb_agg(x.timesheet_id_text order by x.timesheet_id_text),
        '[]'::jsonb
      )
      from (
        select distinct
          tid::text as timesheet_id_text
        from ts_ids_arr t
        cross join lateral unnest(coalesce(t.timesheet_ids, array[]::uuid[])) as u(tid)
        order by tid::text
        limit 50
      ) x
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'pay_batch_item_id', cbi.pay_batch_item_id::text,
            'timesheet_id', cbi.timesheet_id::text,
            'item_type', cbi.item_type,
            'segment_key', cbi.segment_key,
            'source_ref', cbi.source_ref,
            'finance_component_id', case when cbi.finance_component_id is null then null else cbi.finance_component_id::text end,
            'frozen_component_key_type', cbi.frozen_component_key_type,
            'frozen_component_key_value', cbi.frozen_component_key_value,
            'frozen_snapshot_key_type', nullif(
              btrim(
                coalesce(
                  cbi.frozen_component_snapshot_json->>'component_key_type',
                  cbi.frozen_component_snapshot_json->>'key_type',
                  ''
                )
              ),
              ''
            ),
            'frozen_snapshot_key_value', nullif(
              btrim(
                coalesce(
                  cbi.frozen_component_snapshot_json->>'component_key_value',
                  cbi.frozen_component_snapshot_json->>'key_value',
                  ''
                )
              ),
              ''
            ),
            'frozen_source_basis_work_date', nullif(btrim(coalesce(cbi.frozen_source_basis_json->>'work_date','')), ''),
            'live_component_key_type', cbi.live_component_key_type,
            'live_component_key_value', cbi.live_component_key_value,
            'source_reservation_amount_ex_vat', cbi.source_reservation_amount_ex_vat
          )
          order by cbi.timesheet_id::text, cbi.item_type, coalesce(cbi.segment_key,''), coalesce(cbi.source_ref,''), cbi.pay_batch_item_id::text
        ),
        '[]'::jsonb
      )
      from (
        select *
        from current_batch_items cbi
        order by cbi.timesheet_id::text, cbi.item_type, coalesce(cbi.segment_key,''), coalesce(cbi.source_ref,''), cbi.pay_batch_item_id::text
        limit 50
      ) cbi
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', cbk.timesheet_id::text,
            'key_type', cbk.key_type,
            'key_value', cbk.key_value,
            'amount_ex_vat', cbk.amount_ex_vat
          )
          order by cbk.timesheet_id::text, cbk.key_type, cbk.key_value, cbk.amount_ex_vat
        ),
        '[]'::jsonb
      )
      from (
        select *
        from current_batch_keyed cbk
        order by cbk.timesheet_id::text, cbk.key_type, cbk.key_value, cbk.amount_ex_vat
        limit 50
      ) cbk
    ),
    (
      select coalesce(
        jsonb_agg(
          jsonb_build_object(
            'timesheet_id', chk.timesheet_id::text,
            'key_type', chk.key_type,
            'key_value', chk.key_value,
            'reserved_total_ex_vat', chk.reserved_total_ex_vat,
            'current_batch_reserved_ex_vat', chk.current_batch_reserved_ex_vat,
            'reserved_before_ex_vat', chk.reserved_before_ex_vat,
            'payable_possible_ex_vat', chk.payable_possible_ex_vat,
            'tolerance_ex_vat', chk.tolerance_ex_vat
          )
          order by chk.timesheet_id::text, chk.key_type, chk.key_value
        ),
        '[]'::jsonb
      )
      from (
        select *
        from checks chk
        order by chk.timesheet_id::text, chk.key_type, chk.key_value
        limit 50
      ) chk
    )
  into
    v_reserved,
    v_stage_15_reserved_key_count,
    v_stage_15_outstanding_key_count,
    v_stage_15_current_batch_key_count,
    v_stage_15_reserved_keys_sample,
    v_stage_15_outstanding_keys_sample,
    v_stage_15_current_batch_keys_sample,
    v_stage_15_ts_ids_sample,
    v_stage_15_current_batch_items_sample,
    v_stage_15_current_batch_keyed_sample,
    v_stage_15_checks_sample
  from overruns;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_15_RESERVATION_OVERRUN_CHECK_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'overruns', v_reserved,
        'overrun_count', jsonb_array_length(v_reserved),
        'reserved_key_count', v_stage_15_reserved_key_count,
        'outstanding_key_count', v_stage_15_outstanding_key_count,
        'current_batch_key_count', v_stage_15_current_batch_key_count,
        'reserved_keys_sample', v_stage_15_reserved_keys_sample,
        'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
        'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
        'timesheet_ids_sample', v_stage_15_ts_ids_sample,
        'current_batch_items_sample', v_stage_15_current_batch_items_sample,
        'current_batch_keyed_sample', v_stage_15_current_batch_keyed_sample,
        'checks_sample', v_stage_15_checks_sample
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if jsonb_array_length(v_reserved) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_PAY_BATCH_RESERVATION_OVERRUN',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'overruns', v_reserved,
          'reserved_key_count', v_stage_15_reserved_key_count,
          'outstanding_key_count', v_stage_15_outstanding_key_count,
          'current_batch_key_count', v_stage_15_current_batch_key_count,
          'reserved_keys_sample', v_stage_15_reserved_keys_sample,
          'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
          'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
          'error', 'PAY_BATCH_RESERVATION_OVERRUN'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_RESERVATION_OVERRUN',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text,
      'overruns', v_reserved,
      'reserved_key_count', v_stage_15_reserved_key_count,
      'outstanding_key_count', v_stage_15_outstanding_key_count,
      'current_batch_key_count', v_stage_15_current_batch_key_count,
      'reserved_keys_sample', v_stage_15_reserved_keys_sample,
      'outstanding_keys_sample', v_stage_15_outstanding_keys_sample,
      'current_batch_keys_sample', v_stage_15_current_batch_keys_sample,
      'timesheet_ids_sample', v_stage_15_ts_ids_sample,
      'current_batch_items_sample', v_stage_15_current_batch_items_sample,
      'current_batch_keyed_sample', v_stage_15_current_batch_keyed_sample,
      'checks_sample', v_stage_15_checks_sample
    )::text;
  end if;

  
v_stage := 'STAGE_16A_SET_PAYE_AWAITING_NET_MARKER';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  update public.pay_batch_candidates pbc
  set
    awaiting_net_amount = (
      (v_scope = 'PAYE')
      and not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
      )
    ),
    updated_at = v_now_utc
  where pbc.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids));

  get diagnostics v_rows_upd_candidates_paye_awaiting = row_count;

v_stage := 'STAGE_16D_CREATE_FINANCE_RESERVATIONS';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with scoped_finance_reservation_items as (
    select
      pbi.id as pay_batch_item_id,
      pbi.reservation_id as current_reservation_id,
      (
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 1, 8) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 9, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 13, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 17, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 21, 12)
      )::uuid as deterministic_reservation_id
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
      and pbi.is_voided = false
      and pbi.finance_case_id is not null
  )
  select
    count(*) filter (
      where scoped_item.current_reservation_id is null
        and existing_reservation.id is not null
    )::integer,
    count(*) filter (
      where scoped_item.current_reservation_id is not null
        and scoped_item.current_reservation_id = scoped_item.deterministic_reservation_id
        and linked_reservation.id is not null
    )::integer,
    count(*) filter (
      where scoped_item.current_reservation_id is not null
        and scoped_item.current_reservation_id <> scoped_item.deterministic_reservation_id
    )::integer
  into
    v_rows_preexisting_unlinked_reservations,
    v_rows_already_linked_reservations,
    v_rows_mismatched_linked_reservations
  from scoped_finance_reservation_items as scoped_item
  left join public.pay_advance_reservations as existing_reservation
    on existing_reservation.id = scoped_item.deterministic_reservation_id
  left join public.pay_advance_reservations as linked_reservation
    on linked_reservation.id = scoped_item.current_reservation_id;

  if coalesce(v_rows_mismatched_linked_reservations, 0) > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_RESERVATION_NON_DETERMINISTIC_LINK',
      'stage', v_stage,
      'pay_batch_id', v_batch_id::text,
      'message', 'Finance reservation items must use deterministic reservation ids before finalisation can continue',
      'mismatched_linked_reservation_count', v_rows_mismatched_linked_reservations
    )::text;
  end if;

  v_rows_reused_reservations := coalesce(v_rows_preexisting_unlinked_reservations, 0) + coalesce(v_rows_already_linked_reservations, 0);

  with ins as (
    insert into public.pay_advance_reservations (
      id,
      finance_case_id,
      finance_component_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_batch_item_id,
      reserved_amount,
      repayment_week_start,
      status,
      created_at_utc,
      committed_at_utc,
      settled_at_utc,
      released_at_utc,
      released_reason,
      created_by_user_id,
      updated_by_user_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      reserved_source_amount,
      frozen_rounded_target_amount
    )
    select
      (
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 1, 8) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 9, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 13, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 17, 4) || '-' ||
        substr(md5(v_batch_id::text || ':' || pbi.id::text || ':' || coalesce(pbi.finance_case_id::text, 'no_case') || ':' || coalesce(pbi.finance_component_id::text, 'no_component')), 21, 12)
      )::uuid as id,
      pbi.finance_case_id,
      pbi.finance_component_id,
      v_batch_id as pay_batch_id,
      pbi.pay_batch_candidate_id,
      pbi.id as pay_batch_item_id,
      round(abs(coalesce(pbi.amount_ex_vat, 0)), 2) as reserved_amount,
      pbi.repayment_week_start,
      'RESERVED' as status,
      v_now_utc as created_at_utc,
      null::timestamptz as committed_at_utc,
      null::timestamptz as settled_at_utc,
      null::timestamptz as released_at_utc,
      null::text as released_reason,
      p_actor_user_id as created_by_user_id,
      p_actor_user_id as updated_by_user_id,
      pbi.frozen_component_snapshot_json,
      pbi.frozen_component_key_type,
      pbi.frozen_component_key_value,
      pbi.frozen_component_classification,
      pbi.frozen_source_basis_json,
      pbi.frozen_source_pay_method,
      pbi.frozen_target_pay_method,
      pbi.frozen_resolution_mode,
      pbi.frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json,
      round(abs(coalesce(
        case
          when pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            then public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id)
          else null::numeric
        end,
        pbi.frozen_source_amount,
        pbi.amount_ex_vat,
        0
      )), 2) as reserved_source_amount,
      round(abs(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0)), 2) as frozen_rounded_target_amount
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
      and pbi.is_voided = false
      and pbi.finance_case_id is not null
      and pbi.reservation_id is null
    on conflict (id) do update
    set
      pay_batch_id = excluded.pay_batch_id,
      pay_batch_candidate_id = excluded.pay_batch_candidate_id,
      pay_batch_item_id = excluded.pay_batch_item_id,
      updated_by_user_id = excluded.updated_by_user_id
    returning id, pay_batch_item_id
  )
  update public.pay_batch_items pbi
  set
    reservation_id = ins.id,
    updated_at = v_now_utc
  from ins
  where pbi.id = ins.pay_batch_item_id;

  GET DIAGNOSTICS v_rows_ins_reservations = ROW_COUNT;

  v_rows_ins_reservations := greatest(coalesce(v_rows_ins_reservations, 0) - coalesce(v_rows_preexisting_unlinked_reservations, 0), 0);

  v_stage := 'STAGE_17_CLIP_NEGATIVES_TO_DEBT_CREATED';
  -- Part 1E: legacy DEBT_CREATED / negative clipping stage disabled (NO-OP).
  -- Negative handling is represented via OVERPAYMENT balances and finance recovery deductions.
  -- Preserve v_rows_ins_debt_items because it now represents MANUAL_DEBT_RECOVERY rows inserted in Stage 16B.
  v_rows_upd_candidates_debt := 0;


  

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'reservations_created', coalesce(v_rows_ins_reservations, 0),
    'reservations_reused', coalesce(v_rows_reused_reservations, 0),
    'markers_updated', coalesce(v_rows_upd_candidates_paye_awaiting, 0) + coalesce(v_rows_upd_candidates_debt, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'candidate_rows_before_empty_delete', v_candidate_rows_before_empty_delete,
    'deleted_candidate_rows', v_rows_del_candidates,
    'candidate_rows_after_empty_delete', v_candidate_rows_after_empty_delete,
    'awaiting_net_rows_updated', coalesce(v_rows_upd_candidates_paye_awaiting, 0)
  );
END;
$function$
;



DROP FUNCTION IF EXISTS public.pay_batch_populate_candidate_summaries(uuid, text, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_populate_candidate_summaries(uuid, text, uuid, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.pay_batch_populate_candidate_summaries(
  p_pay_batch_id uuid,
  p_pay_channel_scope text,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_now_utc timestamptz := now();
  v_stage text := NULL;
  v_rows_upd_candidates_summaries integer := 0;
  v_rows_inserted_summaries integer := 0;
  v_rows_failed_summaries integer := 0;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;
  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct selected_preview_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row;
  END IF;


v_stage := 'STAGE_18_POPULATE_CANDIDATE_SUMMARIES';
  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:' || v_stage,
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  with
  sums as (
    select
      pbc.id as pay_batch_candidate_id,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type not in ('OVERPAYMENT_RECOVERY', 'LOAN_REPAYMENT', 'MANUAL_DEBT_RECOVERY', 'MANUAL_CREDIT_PAYOUT', 'LOAN_PAYOUT', 'DEBT_CREATED')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type <> 'DEBT_CREATED'
          then pbi.amount_inc_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as earnings_inc,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('GROSS_ADD','GROSS_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as gross_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and coalesce(pbi.paye_treatment,'NONE') in ('NET_ADD','NET_DEDUCT')
          then pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as net_adjustments_ex_sum,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'OVERPAYMENT_RECOVERY'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as overpayment_recovery_taken_ex,

      round(coalesce(sum(
        case
          when pbi.is_voided = false
           and pbi.item_type = 'LOAN_REPAYMENT'
          then -pbi.amount_ex_vat
          else 0
        end
      ), 0), 2)::numeric(12,2) as loan_repayment_taken_ex

    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    where pbc.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
    group by pbc.id
  ),
  paye_net as (
    select
      pni.pay_batch_candidate_id,
      pni.net_amount::numeric(12,2) as net_amount
    from public.pay_batch_paye_net_inputs pni
  )
  update public.pay_batch_candidates pbc
  set
    awaiting_net_amount = (
      (v_scope = 'PAYE')
      and not exists (
        select 1
        from public.pay_batch_paye_net_inputs pni2
        where pni2.pay_batch_candidate_id = pbc.id
      )
    ),

    gross_preview = case
      when (v_scope = 'PAYE') then round(coalesce(sums.earnings_ex, 0) + coalesce(sums.gross_adjustments_ex_sum, 0), 2)::numeric(12,2)
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    overpayment_recovery_taken = sums.overpayment_recovery_taken_ex,
    loan_repayment_taken = sums.loan_repayment_taken_ex,

    net_bank_amount = case
      when (v_scope = 'PAYE') then
        case
          when (
            (v_scope = 'PAYE')
            and not exists (
              select 1
              from public.pay_batch_paye_net_inputs pni3
              where pni3.pay_batch_candidate_id = pbc.id
            )
          ) then null
          else greatest(
            round(coalesce(pn.net_amount, 0) + coalesce(sums.net_adjustments_ex_sum, 0), 2),
            0
          )::numeric(12,2)
        end
      else greatest(coalesce(sums.earnings_inc, 0), 0)::numeric(12,2)
    end,

    mismatch_settlement_choice = null,
    updated_at = v_now_utc
  from sums
  left join paye_net pn
    on pn.pay_batch_candidate_id = sums.pay_batch_candidate_id
  where pbc.id = sums.pay_batch_candidate_id
    and pbc.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids));

  get diagnostics v_rows_upd_candidates_summaries = row_count;

  

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'summaries_inserted', coalesce(v_rows_inserted_summaries, 0),
    'summaries_updated', coalesce(v_rows_upd_candidates_summaries, 0),
    'failed_count', coalesce(v_rows_failed_summaries, 0),
    'updated_candidate_rows', coalesce(v_rows_upd_candidates_summaries, 0)
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_batch_create_timesheet_snapshots(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_create_timesheet_snapshots(uuid, uuid, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.pay_batch_create_timesheet_snapshots(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_stage text := 'STAGE_19_CREATE_TIMESHEET_SNAPSHOTS';
  v_rows_ins_snapshots integer := 0;
  v_rows_reused_snapshots integer := 0;
  v_rows_updated_snapshots integer := 0;
  v_rows_failed_snapshots integer := 0;
  v_missing_snapshot_count integer := 0;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct selected_preview_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row;
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_timesheet_snapshots_ctx') IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_timesheet_snapshots_ctx temp table is required';
  END IF;

  SELECT count(*)::int
  INTO v_missing_snapshot_count
  FROM (
    SELECT DISTINCT pbi.timesheet_id
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
      AND pbi.timesheet_id IS NOT NULL
  ) AS touched_ts
  LEFT JOIN pg_temp.tmp_pay_build_timesheet_snapshots_ctx ts_ctx
    ON ts_ctx.timesheet_id = touched_ts.timesheet_id
  WHERE ts_ctx.timesheet_id IS NULL;

  IF coalesce(v_missing_snapshot_count, 0) > 0 THEN
    RAISE EXCEPTION 'Missing staged timesheet snapshot rows for % touched timesheets', v_missing_snapshot_count;
  END IF;

  DELETE FROM public.pay_batch_timesheet_snapshots pbs
  WHERE pbs.pay_batch_id = v_batch_id
    AND pbs.timesheet_id IN (
      SELECT DISTINCT pbi.timesheet_id
      FROM public.pay_batch_items pbi
      JOIN public.pay_batch_candidates pbc
        ON pbc.id = pbi.pay_batch_candidate_id
      WHERE pbc.pay_batch_id = v_batch_id
        AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
        AND pbi.timesheet_id IS NOT NULL
    );

  INSERT INTO public.pay_batch_timesheet_snapshots(
    pay_batch_id,
    timesheet_id,
    candidate_id,
    pay_channel,
    base_snapshot_json,
    target_snapshot_json,
    signature,
    created_at_utc
  )
  WITH touched_ts AS (
    SELECT DISTINCT pbi.timesheet_id
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
      AND pbi.timesheet_id IS NOT NULL
  ),
  ts_channel AS (
    SELECT DISTINCT ON (pbi.timesheet_id)
      pbi.timesheet_id,
      pbi.pay_channel AS pay_channel_used
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
      AND pbi.timesheet_id IS NOT NULL
      AND pbi.pay_channel IN ('PAYE', 'UMBRELLA')
    ORDER BY pbi.timesheet_id, pbi.pay_channel DESC, pbi.id DESC
  ),
  resolved_components AS (
    SELECT
      pbi.timesheet_id,
      coalesce(
        jsonb_agg(pbi.frozen_component_snapshot_json ORDER BY pbi.id),
        '[]'::jsonb
      ) AS resolved_components_json
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
      AND pbi.timesheet_id IS NOT NULL
      AND coalesce(pbi.is_voided, false) = false
      AND pbi.frozen_component_snapshot_json IS NOT NULL
    GROUP BY pbi.timesheet_id
  ),
  staged_rows AS (
    SELECT
      ts_ctx.timesheet_id,
      ts_ctx.candidate_id,
      ts_ctx.base_snapshot_json,
      jsonb_set(
        coalesce(ts_ctx.target_snapshot_json, '{}'::jsonb),
        '{resolved_components}',
        coalesce(rc.resolved_components_json, '[]'::jsonb),
        true
      ) AS final_target_snapshot_json
    FROM touched_ts tt
    JOIN pg_temp.tmp_pay_build_timesheet_snapshots_ctx ts_ctx
      ON ts_ctx.timesheet_id = tt.timesheet_id
    LEFT JOIN resolved_components rc
      ON rc.timesheet_id = tt.timesheet_id
  )
  SELECT
    v_batch_id,
    sr.timesheet_id,
    sr.candidate_id,
    tc.pay_channel_used,
    sr.base_snapshot_json,
    sr.final_target_snapshot_json,
    md5(sr.final_target_snapshot_json::text),
    now()
  FROM staged_rows sr
  JOIN ts_channel tc
    ON tc.timesheet_id = sr.timesheet_id;

  GET DIAGNOSTICS v_rows_ins_snapshots = ROW_COUNT;

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_19_SNAPSHOTS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'inserted_snapshot_rows', v_rows_ins_snapshots,
        'missing_snapshot_count', v_missing_snapshot_count
      ),
      'pay_batches',
      v_batch_id::text,
      NULL, NULL, NULL, NULL, NULL
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'inserted_count', coalesce(v_rows_ins_snapshots, 0),
    'reused_count', coalesce(v_rows_reused_snapshots, 0),
    'updated_count', coalesce(v_rows_updated_snapshots, 0),
    'failed_count', coalesce(v_rows_failed_snapshots, 0),
    'inserted_snapshot_rows', coalesce(v_rows_ins_snapshots, 0),
    'missing_snapshot_count', coalesce(v_missing_snapshot_count, 0)
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_batch_build_item_breakdowns(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_build_item_breakdowns(uuid, uuid, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.pay_batch_build_item_breakdowns(
  p_pay_batch_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_stage text := NULL;
  v_rows_ins_breakdowns integer := 0;
  v_rows_reused_breakdowns integer := 0;
  v_rows_failed_breakdowns integer := 0;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF p_operation_id IS NOT NULL OR p_candidate_scope_ids IS NOT NULL THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'p_operation_id is required when p_candidate_scope_ids is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'p_actor_user_id is required when p_operation_id is supplied';
    END IF;

    PERFORM *
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    );

    SELECT COALESCE(array_agg(distinct selected_preview_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_preview_row;
  END IF;

  v_stage := 'STAGE_20_BUILD_ITEM_BREAKDOWNS';

  WITH my_items AS (
    SELECT
      pbi.id AS pay_batch_item_id,
      pbi.item_type,
      pbi.timesheet_id,
      pbi.segment_key,
      pbi.source_ref,
      pbi.description,
      pbi.amount_ex_vat,
      pbi.amount_vat,
      pbi.amount_inc_vat,
      pbi.pay_channel,
      pbi.finance_case_id,
      pbi.finance_component_id,
      pbi.frozen_component_key_type,
      pbi.frozen_component_key_value,
      pbi.frozen_component_snapshot_json,
      pbi.frozen_source_basis_json,
      pbi.frozen_resolution_mode,
      pbi.frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json,
      pbi.frozen_component_classification,
      pbi.frozen_source_amount,
      pbi.frozen_target_amount_ex_vat,
      pbi.frozen_target_amount_vat,
      pbi.frozen_target_amount_inc_vat,
      public._pay_batch_item_source_reservation_amount_ex_vat(pbi.id) AS source_reservation_amount_ex_vat
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE pbc.pay_batch_id = v_batch_id
      AND (p_operation_id IS NULL OR pbc.candidate_id = ANY(v_candidate_ids))
      AND COALESCE(pbi.is_voided, false) = false
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_batch_item_breakdowns AS pbib
        WHERE pbib.pay_batch_item_id = pbi.id
        LIMIT 1
      )
  ),
  exact_component_seed AS (
    SELECT
      mi.pay_batch_item_id,
      mi.item_type,
      mi.source_ref,
      mi.description,
      mi.amount_ex_vat,
      mi.amount_vat,
      mi.amount_inc_vat,
      mi.pay_channel,
      mi.finance_case_id,
      mi.finance_component_id,
      mi.frozen_component_key_type,
      mi.frozen_component_key_value,
      mi.frozen_resolution_mode,
      mi.frozen_resolution_payload_json,
      mi.frozen_resolution_result_json,
      mi.frozen_component_classification,
      mi.frozen_source_amount,
      mi.frozen_target_amount_ex_vat,
      mi.frozen_target_amount_vat,
      mi.frozen_target_amount_inc_vat,
      mi.source_reservation_amount_ex_vat,
      COALESCE(mi.frozen_component_snapshot_json, '{}'::jsonb) AS frozen_component_snapshot_json,
      COALESCE(mi.frozen_source_basis_json, '{}'::jsonb) AS frozen_source_basis_json,
      NULLIF(
        UPPER(
          BTRIM(
            COALESCE(
              mi.frozen_component_snapshot_json->>'bucket_code',
              mi.frozen_source_basis_json->>'bucket_code',
              CASE
                WHEN mi.item_type = 'EXPENSE_DELTA' AND mi.source_ref LIKE 'additional:%' THEN split_part(mi.source_ref, ':', 2)
                WHEN mi.item_type = 'EXPENSE_DELTA' AND mi.source_ref = 'additional' THEN 'TOTAL'
                ELSE NULL
              END,
              ''
            )
          )
        ),
        ''
      ) AS bucket_code,
      NULLIF(BTRIM(COALESCE(mi.frozen_component_snapshot_json->>'label', '')), '') AS preview_label,
      UPPER(COALESCE(mi.frozen_component_snapshot_json->>'component_semantics', '')) AS component_semantics,
      COALESCE(NULLIF(mi.frozen_component_snapshot_json->>'is_rate_bearing','')::boolean, false) AS is_rate_bearing,
      COALESCE(NULLIF(mi.frozen_component_snapshot_json->>'is_amount_led','')::boolean, false) AS is_amount_led,
      NULLIF(
        UPPER(
          BTRIM(
            COALESCE(
              mi.frozen_component_key_type,
              mi.frozen_component_snapshot_json->>'component_key_type',
              mi.frozen_component_snapshot_json->>'key_type',
              ''
            )
          )
        ),
        ''
      ) AS component_key_type,
      NULLIF(
        BTRIM(
          COALESCE(
            mi.frozen_component_key_value,
            mi.frozen_component_snapshot_json->>'component_key_value',
            mi.frozen_component_snapshot_json->>'key_value',
            ''
          )
        ),
        ''
      ) AS component_key_value,
      NULLIF(
        BTRIM(
          COALESCE(
            mi.frozen_component_snapshot_json->>'source_family_key',
            mi.frozen_source_basis_json->>'source_family_key',
            ''
          )
        ),
        ''
      ) AS source_family_key,
      NULLIF(
        BTRIM(
          COALESCE(
            mi.frozen_component_snapshot_json->>'source_basis_fingerprint',
            mi.frozen_source_basis_json->>'source_basis_fingerprint',
            mi.frozen_source_basis_json->>'basis_fingerprint',
            ''
          )
        ),
        ''
      ) AS source_basis_fingerprint,
      CASE
        WHEN COALESCE(
          mi.frozen_component_snapshot_json->>'source_units',
          mi.frozen_source_basis_json->>'source_units',
          mi.frozen_source_basis_json->>'units',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_component_snapshot_json->>'source_units')::numeric,
            (mi.frozen_source_basis_json->>'source_units')::numeric,
            (mi.frozen_source_basis_json->>'units')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS source_units,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'target_units',
          mi.frozen_component_snapshot_json->>'target_units',
          mi.frozen_component_snapshot_json->>'source_units',
          mi.frozen_source_basis_json->>'source_units',
          mi.frozen_source_basis_json->>'units',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'target_units')::numeric,
            (mi.frozen_component_snapshot_json->>'target_units')::numeric,
            (mi.frozen_component_snapshot_json->>'source_units')::numeric,
            (mi.frozen_source_basis_json->>'source_units')::numeric,
            (mi.frozen_source_basis_json->>'units')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS target_units,
      CASE
        WHEN COALESCE(
          mi.frozen_component_snapshot_json->>'source_rate',
          mi.frozen_source_basis_json->>'source_rate',
          mi.frozen_source_basis_json->>'rate',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_component_snapshot_json->>'source_rate')::numeric,
            (mi.frozen_source_basis_json->>'source_rate')::numeric,
            (mi.frozen_source_basis_json->>'rate')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS source_rate,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'target_rate',
          mi.frozen_resolution_result_json->>'replacement_rate',
          mi.frozen_component_snapshot_json->>'target_rate',
          mi.frozen_component_snapshot_json->>'source_rate',
          mi.frozen_source_basis_json->>'source_rate',
          mi.frozen_source_basis_json->>'rate',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'target_rate')::numeric,
            (mi.frozen_resolution_result_json->>'replacement_rate')::numeric,
            (mi.frozen_component_snapshot_json->>'target_rate')::numeric,
            (mi.frozen_component_snapshot_json->>'source_rate')::numeric,
            (mi.frozen_source_basis_json->>'source_rate')::numeric,
            (mi.frozen_source_basis_json->>'rate')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS target_rate,
      CASE
        WHEN COALESCE(
          mi.frozen_component_snapshot_json->>'source_charge_rate',
          mi.frozen_source_basis_json->>'source_charge_rate',
          mi.frozen_source_basis_json->>'charge_rate',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_component_snapshot_json->>'source_charge_rate')::numeric,
            (mi.frozen_source_basis_json->>'source_charge_rate')::numeric,
            (mi.frozen_source_basis_json->>'charge_rate')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS source_charge_rate,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'target_charge_rate',
          mi.frozen_component_snapshot_json->>'target_charge_rate',
          mi.frozen_component_snapshot_json->>'source_charge_rate',
          mi.frozen_source_basis_json->>'source_charge_rate',
          mi.frozen_source_basis_json->>'charge_rate',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'target_charge_rate')::numeric,
            (mi.frozen_component_snapshot_json->>'target_charge_rate')::numeric,
            (mi.frozen_component_snapshot_json->>'source_charge_rate')::numeric,
            (mi.frozen_source_basis_json->>'source_charge_rate')::numeric,
            (mi.frozen_source_basis_json->>'charge_rate')::numeric
          ), 6)
        ELSE NULL::numeric
      END AS target_charge_rate,
      ROUND(ABS(COALESCE(
        mi.source_reservation_amount_ex_vat,
        mi.frozen_source_amount,
        CASE
          WHEN COALESCE(
            mi.frozen_component_snapshot_json->>'source_pay_ex_vat',
            mi.frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat',
            mi.frozen_component_snapshot_json->>'source_amount_ex_vat',
            mi.frozen_source_basis_json->>'source_pay_ex_vat',
            mi.frozen_source_basis_json->>'source_entitlement_amount_ex_vat',
            mi.frozen_source_basis_json->>'source_amount_ex_vat',
            mi.frozen_source_basis_json->>'pay_ex_vat',
            mi.frozen_source_basis_json->>'amount_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(
              (mi.frozen_component_snapshot_json->>'source_pay_ex_vat')::numeric,
              (mi.frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat')::numeric,
              (mi.frozen_component_snapshot_json->>'source_amount_ex_vat')::numeric,
              (mi.frozen_source_basis_json->>'source_pay_ex_vat')::numeric,
              (mi.frozen_source_basis_json->>'source_entitlement_amount_ex_vat')::numeric,
              (mi.frozen_source_basis_json->>'source_amount_ex_vat')::numeric,
              (mi.frozen_source_basis_json->>'pay_ex_vat')::numeric,
              (mi.frozen_source_basis_json->>'amount_ex_vat')::numeric
            )
          ELSE NULL::numeric
        END
      )), 2) AS source_pay_ex_vat,
      ROUND(COALESCE(
        mi.frozen_target_amount_ex_vat,
        CASE
          WHEN COALESCE(
            mi.frozen_resolution_result_json->>'target_pay_ex_vat',
            mi.frozen_resolution_result_json->>'target_amount_ex_vat',
            mi.frozen_component_snapshot_json->>'target_pay_ex_vat',
            mi.frozen_component_snapshot_json->>'target_amount_ex_vat',
            ''
          ) ~ '^-?[0-9]+(\.[0-9]+)?$'
            THEN COALESCE(
              (mi.frozen_resolution_result_json->>'target_pay_ex_vat')::numeric,
              (mi.frozen_resolution_result_json->>'target_amount_ex_vat')::numeric,
              (mi.frozen_component_snapshot_json->>'target_pay_ex_vat')::numeric,
              (mi.frozen_component_snapshot_json->>'target_amount_ex_vat')::numeric
            )
          ELSE NULL::numeric
        END,
        mi.amount_ex_vat,
        0
      ), 2) AS target_pay_ex_vat,
      CASE
        WHEN COALESCE(
          mi.frozen_component_snapshot_json->>'source_charge_ex_vat',
          mi.frozen_source_basis_json->>'source_charge_ex_vat',
          mi.frozen_source_basis_json->>'charge_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_component_snapshot_json->>'source_charge_ex_vat')::numeric,
            (mi.frozen_source_basis_json->>'source_charge_ex_vat')::numeric,
            (mi.frozen_source_basis_json->>'charge_ex_vat')::numeric
          ), 2)
        ELSE NULL::numeric
      END AS source_charge_ex_vat,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'target_charge_ex_vat',
          mi.frozen_component_snapshot_json->>'target_charge_ex_vat',
          mi.frozen_component_snapshot_json->>'source_charge_ex_vat',
          mi.frozen_source_basis_json->>'source_charge_ex_vat',
          mi.frozen_source_basis_json->>'charge_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'target_charge_ex_vat')::numeric,
            (mi.frozen_component_snapshot_json->>'target_charge_ex_vat')::numeric,
            (mi.frozen_component_snapshot_json->>'source_charge_ex_vat')::numeric,
            (mi.frozen_source_basis_json->>'source_charge_ex_vat')::numeric,
            (mi.frozen_source_basis_json->>'charge_ex_vat')::numeric
          ), 2)
        ELSE NULL::numeric
      END AS target_charge_ex_vat,
      CASE
        WHEN COALESCE(
          mi.frozen_component_snapshot_json->>'source_margin_ex_vat',
          mi.frozen_source_basis_json->>'source_margin_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_component_snapshot_json->>'source_margin_ex_vat')::numeric,
            (mi.frozen_source_basis_json->>'source_margin_ex_vat')::numeric
          ), 2)
        ELSE NULL::numeric
      END AS source_margin_ex_vat,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'target_margin_ex_vat',
          mi.frozen_component_snapshot_json->>'target_margin_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'target_margin_ex_vat')::numeric,
            (mi.frozen_component_snapshot_json->>'target_margin_ex_vat')::numeric
          ), 2)
        ELSE NULL::numeric
      END AS target_margin_ex_vat,
      CASE
        WHEN COALESCE(
          mi.frozen_resolution_result_json->>'margin_delta_ex_vat',
          mi.frozen_component_snapshot_json->>'margin_delta_ex_vat',
          ''
        ) ~ '^-?[0-9]+(\.[0-9]+)?$'
          THEN ROUND(COALESCE(
            (mi.frozen_resolution_result_json->>'margin_delta_ex_vat')::numeric,
            (mi.frozen_component_snapshot_json->>'margin_delta_ex_vat')::numeric
          ), 2)
        ELSE NULL::numeric
      END AS margin_delta_ex_vat
    FROM my_items AS mi
    WHERE jsonb_typeof(mi.frozen_component_snapshot_json) = 'object'
      AND (
        mi.item_type = 'SEGMENT_DELTA'
        OR (mi.item_type = 'EXPENSE_DELTA' AND (mi.source_ref = 'additional' OR mi.source_ref LIKE 'additional:%'))
      )
  ),
  exact_component_display_seed AS (
    SELECT
      ecs.*,
      (
        COALESCE(ecs.is_rate_bearing, false)
        OR (
          ecs.item_type = 'SEGMENT_DELTA'
          AND ecs.frozen_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          AND COALESCE(ecs.bucket_code, '') IN ('DAY', 'NIGHT', 'SAT', 'SUN', 'BH')
          AND ecs.target_units IS NOT NULL
          AND ecs.target_units > 0
          AND ecs.target_rate IS NOT NULL
        )
      ) AS effective_is_rate_bearing
    FROM exact_component_seed AS ecs
  ),
  exact_component_lines AS (
    SELECT
      ecs.pay_batch_item_id,
      CASE
        WHEN ecs.item_type = 'SEGMENT_DELTA' THEN 'TS_BUCKET'::text
        ELSE 'ADDITIONAL_UNIT'::text
      END AS line_kind,
      ecs.bucket_code,
      CASE
        WHEN ecs.item_type = 'SEGMENT_DELTA' THEN
          CASE ecs.bucket_code
            WHEN 'DAY' THEN 'Day'::text
            WHEN 'NIGHT' THEN 'Night'::text
            WHEN 'SAT' THEN 'Sat'::text
            WHEN 'SUN' THEN 'Sun'::text
            WHEN 'BH' THEN 'BH'::text
            ELSE COALESCE(ecs.preview_label, 'Bucket')::text
          END
        ELSE COALESCE(
          ecs.preview_label,
          CASE
            WHEN ecs.bucket_code IS NULL OR ecs.bucket_code = 'TOTAL' THEN 'Additional'::text
            ELSE ecs.bucket_code::text
          END
        )
      END AS unit_name,
      CASE WHEN ecs.effective_is_rate_bearing THEN ecs.target_units ELSE NULL::numeric END AS units,
      CASE WHEN ecs.effective_is_rate_bearing THEN ecs.target_rate ELSE NULL::numeric END AS rate,
      ecs.target_pay_ex_vat AS amount_ex_vat,
      ROUND(COALESCE(ecs.frozen_target_amount_vat, 0), 2) AS amount_vat,
      ROUND(COALESCE(ecs.frozen_target_amount_inc_vat, ecs.target_pay_ex_vat + COALESCE(ecs.frozen_target_amount_vat, 0)), 2) AS amount_inc_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'component_semantics', CASE WHEN ecs.effective_is_rate_bearing THEN 'RATE_BEARING' ELSE COALESCE(NULLIF(ecs.component_semantics,''), 'AMOUNT_LED') END,
          'finance_case_id', CASE WHEN ecs.finance_case_id IS NULL THEN NULL ELSE ecs.finance_case_id::text END,
          'finance_component_id', CASE WHEN ecs.finance_component_id IS NULL THEN NULL ELSE ecs.finance_component_id::text END,
          'component_key_type', ecs.component_key_type,
          'component_key_value', ecs.component_key_value,
          'economic_key_type', ecs.component_key_type,
          'economic_key_value', ecs.component_key_value,
          'source_family_key', ecs.source_family_key,
          'source_basis_json', CASE WHEN ecs.frozen_source_basis_json = '{}'::jsonb THEN NULL ELSE ecs.frozen_source_basis_json END,
          'source_basis_fingerprint', ecs.source_basis_fingerprint,
          'frozen_component_snapshot_json', CASE WHEN ecs.frozen_component_snapshot_json = '{}'::jsonb THEN NULL ELSE ecs.frozen_component_snapshot_json END,
          'source_units', ecs.source_units,
          'source_rate', ecs.source_rate,
          'source_charge_rate', ecs.source_charge_rate,
          'source_pay_ex_vat', ecs.source_pay_ex_vat,
          'source_entitlement_amount_ex_vat', ecs.source_pay_ex_vat,
          'source_reservation_amount_ex_vat', ecs.source_reservation_amount_ex_vat,
          'source_charge_ex_vat', ecs.source_charge_ex_vat,
          'source_margin_ex_vat', ecs.source_margin_ex_vat,
          'target_units', ecs.target_units,
          'target_rate', ecs.target_rate,
          'target_charge_rate', ecs.target_charge_rate,
          'target_pay_ex_vat', ecs.target_pay_ex_vat,
          'target_amount_ex_vat', ecs.target_pay_ex_vat,
          'target_charge_ex_vat', ecs.target_charge_ex_vat,
          'target_margin_ex_vat', ecs.target_margin_ex_vat,
          'margin_delta_ex_vat', ecs.margin_delta_ex_vat,
          'resolution_mode', COALESCE(ecs.frozen_resolution_mode::text, ecs.frozen_component_snapshot_json->>'resolution_mode'),
          'resolution_payload_json', CASE WHEN ecs.frozen_resolution_payload_json IS NULL OR ecs.frozen_resolution_payload_json = '{}'::jsonb THEN NULL ELSE ecs.frozen_resolution_payload_json END,
          'resolution_result_json', CASE WHEN ecs.frozen_resolution_result_json IS NULL OR ecs.frozen_resolution_result_json = '{}'::jsonb THEN NULL ELSE ecs.frozen_resolution_result_json END,
          'source_target_display', jsonb_build_object(
            'source_units', ecs.source_units,
            'source_rate', ecs.source_rate,
            'source_amount_ex_vat', ecs.source_pay_ex_vat,
            'target_units', ecs.target_units,
            'target_rate', ecs.target_rate,
            'target_amount_ex_vat', ecs.target_pay_ex_vat,
            'economic_key_type', ecs.component_key_type,
            'economic_key_value', ecs.component_key_value
          )
        )
      ) AS meta_json
    FROM exact_component_display_seed AS ecs
  ),
  exact_component_item_ids AS (
    SELECT DISTINCT ecl.pay_batch_item_id
    FROM exact_component_lines AS ecl
  ),
  simple_lines AS (
    SELECT
      mi.pay_batch_item_id,
      CASE
        WHEN mi.item_type = 'MILEAGE_DELTA' THEN 'MILEAGE'
        WHEN mi.item_type = 'EXPENSE_DELTA' THEN 'EXPENSE'
        WHEN mi.item_type = 'ADJUSTMENT_DELTA' THEN 'ADJUSTMENT'
        WHEN mi.item_type = 'CONVERSION_ADJ' THEN 'CONVERSION_ADJ'
        WHEN mi.item_type = 'OVERPAYMENT_RECOVERY' THEN 'OVERPAYMENT_RECOVERY'
        WHEN mi.item_type = 'LOAN_REPAYMENT' THEN 'LOAN_REPAYMENT'
        WHEN mi.item_type = 'MANUAL_DEBT_RECOVERY' THEN 'MANUAL_DEBT_RECOVERY'
        WHEN mi.item_type = 'DEBT_CREATED' THEN 'DEBT_CREATED'
        WHEN mi.item_type = 'LOAN_PAYOUT' THEN 'LOAN_PAYOUT'
        WHEN mi.item_type = 'MANUAL_CREDIT_PAYOUT' THEN 'MANUAL_CREDIT_PAYOUT'
        ELSE 'ADJUSTMENT'
      END AS line_kind,
      NULL::text AS bucket_code,
      CASE
        WHEN mi.item_type = 'MILEAGE_DELTA' THEN 'Mileage'
        WHEN mi.item_type = 'EXPENSE_DELTA' THEN initcap(COALESCE(mi.source_ref,'Expense'))
        WHEN mi.item_type = 'ADJUSTMENT_DELTA' THEN 'Adjustment'
        WHEN mi.item_type = 'CONVERSION_ADJ' THEN 'Conversion adjustment'
        WHEN mi.item_type = 'OVERPAYMENT_RECOVERY' THEN 'Overpayment recovery'
        WHEN mi.item_type = 'LOAN_REPAYMENT' THEN 'Loan repayment'
        WHEN mi.item_type = 'MANUAL_DEBT_RECOVERY' THEN 'Manual debt recovery'
        WHEN mi.item_type = 'DEBT_CREATED' THEN 'Debt created'
        WHEN mi.item_type = 'LOAN_PAYOUT' THEN 'Loan payout'
        WHEN mi.item_type = 'MANUAL_CREDIT_PAYOUT' THEN 'Manual credit adjustment payment'
        ELSE 'Adjustment'
      END AS unit_name,
      NULL::numeric AS units,
      NULL::numeric AS rate,
      ROUND(COALESCE(mi.amount_ex_vat, 0), 2) AS amount_ex_vat,
      ROUND(COALESCE(mi.amount_vat, 0), 2) AS amount_vat,
      ROUND(COALESCE(mi.amount_inc_vat, 0), 2) AS amount_inc_vat,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', CASE WHEN mi.finance_case_id IS NULL THEN NULL ELSE mi.finance_case_id::text END,
          'finance_component_id', CASE WHEN mi.finance_component_id IS NULL THEN NULL ELSE mi.finance_component_id::text END,
          'component_key_type', NULLIF(UPPER(BTRIM(COALESCE(mi.frozen_component_key_type, mi.frozen_component_snapshot_json->>'component_key_type', mi.frozen_component_snapshot_json->>'key_type', ''))), ''),
          'component_key_value', NULLIF(BTRIM(COALESCE(mi.frozen_component_key_value, mi.frozen_component_snapshot_json->>'component_key_value', mi.frozen_component_snapshot_json->>'key_value', '')), ''),
          'source_basis_json', CASE WHEN COALESCE(mi.frozen_source_basis_json, '{}'::jsonb) = '{}'::jsonb THEN NULL ELSE mi.frozen_source_basis_json END,
          'frozen_component_snapshot_json', CASE WHEN COALESCE(mi.frozen_component_snapshot_json, '{}'::jsonb) = '{}'::jsonb THEN NULL ELSE mi.frozen_component_snapshot_json END,
          'source_reservation_amount_ex_vat', mi.source_reservation_amount_ex_vat,
          'target_amount_ex_vat', COALESCE(mi.frozen_target_amount_ex_vat, mi.amount_ex_vat),
          'resolution_mode', CASE WHEN mi.frozen_resolution_mode IS NULL THEN NULL ELSE mi.frozen_resolution_mode::text END,
          'resolution_payload_json', CASE WHEN mi.frozen_resolution_payload_json IS NULL OR mi.frozen_resolution_payload_json = '{}'::jsonb THEN NULL ELSE mi.frozen_resolution_payload_json END,
          'resolution_result_json', CASE WHEN mi.frozen_resolution_result_json IS NULL OR mi.frozen_resolution_result_json = '{}'::jsonb THEN NULL ELSE mi.frozen_resolution_result_json END
        )
      ) AS meta_json
    FROM my_items AS mi
    WHERE NOT EXISTS (
      SELECT 1
      FROM exact_component_item_ids AS eci
      WHERE eci.pay_batch_item_id = mi.pay_batch_item_id
    )
  ),
  all_lines AS (
    SELECT * FROM exact_component_lines
    UNION ALL
    SELECT * FROM simple_lines
  )
  INSERT INTO public.pay_batch_item_breakdowns(
    pay_batch_item_id,
    line_kind,
    bucket_code,
    unit_name,
    units,
    rate,
    amount_ex_vat,
    amount_vat,
    amount_inc_vat,
    meta_json,
    operation_source_key
  )
  SELECT
    al.pay_batch_item_id,
    al.line_kind,
    al.bucket_code,
    al.unit_name,
    al.units,
    al.rate,
    al.amount_ex_vat,
    al.amount_vat,
    al.amount_inc_vat,
    al.meta_json,
    CASE
      WHEN p_operation_id IS NULL THEN NULL::text
      ELSE p_operation_id::text
        || ':breakdown:' || al.pay_batch_item_id::text
        || ':' || al.line_kind
        || ':' || coalesce(al.bucket_code, 'no_bucket')
        || ':' || coalesce(al.unit_name, 'no_unit')
        || ':' || coalesce(round(coalesce(al.amount_ex_vat, 0), 2)::text, '0')
    END AS operation_source_key
  FROM all_lines AS al
  ON CONFLICT (pay_batch_item_id, operation_source_key) WHERE operation_source_key IS NOT NULL DO NOTHING;

  GET DIAGNOSTICS v_rows_ins_breakdowns = ROW_COUNT;

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_rows_reused_breakdowns
    FROM public.pay_batch_item_breakdowns AS existing_breakdown
    JOIN public.pay_batch_items AS existing_item
      ON existing_item.id = existing_breakdown.pay_batch_item_id
    JOIN public.pay_batch_candidates AS existing_candidate
      ON existing_candidate.id = existing_item.pay_batch_candidate_id
    WHERE existing_candidate.pay_batch_id = v_batch_id
      AND existing_candidate.candidate_id = ANY(v_candidate_ids)
      AND existing_breakdown.operation_source_key LIKE (p_operation_id::text || ':breakdown:%');

    v_rows_reused_breakdowns := coalesce(v_rows_reused_breakdowns, 0) - coalesce(v_rows_ins_breakdowns, 0);

    IF v_rows_reused_breakdowns < 0 THEN
      v_rows_reused_breakdowns := 0;
    END IF;
  END IF;

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_20_BREAKDOWNS_INSERTED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'inserted_breakdown_rows', v_rows_ins_breakdowns
      ),
      'pay_batches',
      v_batch_id::text,
      NULL, NULL, NULL, NULL, NULL
    );
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'inserted_count', COALESCE(v_rows_ins_breakdowns, 0),
    'reused_count', COALESCE(v_rows_reused_breakdowns, 0),
    'failed_count', COALESCE(v_rows_failed_breakdowns, 0),
    'inserted_breakdown_rows', COALESCE(v_rows_ins_breakdowns, 0)
  );
END;
$function$;



DROP FUNCTION IF EXISTS public.pay_batch_assert_integrity(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_assert_integrity(uuid, uuid, uuid);



CREATE OR REPLACE FUNCTION public.pay_batch_assert_integrity(p_pay_batch_id uuid, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid := p_pay_batch_id;
  v_stage text := NULL;
  v_breakdown_missing_ct integer := 0;
  v_breakdown_bad_ct integer := 0;
  v_breakdown_bad jsonb := '[]'::jsonb;
  v_blocked_candidates jsonb := '[]'::jsonb;
  v_rows_upd_timesheet_overrides_consumed integer := 0;
  v_consumed_timesheet_payment_overrides jsonb := '[]'::jsonb;
  v_rail_provider_default text := NULL;
  v_rail_env_default text := NULL;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_now_utc timestamptz := now();
  v_override_consume_rec record;
  v_operation_mismatch_details jsonb := '{}'::jsonb;
  v_operation_affected_candidate_ids jsonb := '[]'::jsonb;
  v_operation_mismatch_count integer := 0;
  v_operation_active_item_count integer := 0;
  v_operation_scope_count integer := 0;
  v_operation_reservation_unavailable_scope_count integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_id is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_settings_context') IS NOT NULL THEN
    SELECT ctx.rail_provider_default, ctx.rail_env_default, ctx.need_name_check, ctx.requires_payee_map
    INTO v_rail_provider_default, v_rail_env_default, v_need_name_check, v_requires_payee_map
    FROM pg_temp.tmp_pay_build_settings_context AS ctx
    LIMIT 1;
  END IF;

  IF (v_rail_provider_default IS NULL OR v_rail_env_default IS NULL) AND p_operation_id IS NOT NULL THEN
    SELECT batch_row.rail_provider_snapshot,
           batch_row.rail_env_snapshot,
           (coalesce(settings_row.rail_supports_name_check, false) = true and upper(btrim(coalesce(batch_row.rail_provider_snapshot, ''))) <> 'CSV') AS need_name_check,
           (upper(btrim(coalesce(batch_row.rail_provider_snapshot, ''))) <> 'CSV') AS requires_payee_map
    INTO v_rail_provider_default, v_rail_env_default, v_need_name_check, v_requires_payee_map
    FROM public.pay_batches AS batch_row
    CROSS JOIN LATERAL (
      SELECT settings_defaults_row.rail_supports_name_check
      FROM public.settings_defaults AS settings_defaults_row
      ORDER BY settings_defaults_row.id ASC
      LIMIT 1
    ) AS settings_row
    WHERE batch_row.id = v_batch_id;
  END IF;

  IF v_rail_provider_default IS NULL OR v_rail_env_default IS NULL THEN
    RAISE EXCEPTION 'tmp_pay_build_settings_context temp table is required';
  END IF;

  IF to_regclass('pg_temp.tmp_pay_build_selected_preview_rows') IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct spr.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM pg_temp.tmp_pay_build_selected_preview_rows AS spr;
  ELSIF p_operation_id IS NOT NULL THEN
    SELECT COALESCE(array_agg(distinct scope_row.candidate_id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = v_batch_id;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_candidates_ctx (
      id uuid PRIMARY KEY,
      tms_ref text,
      display_name text,
      pay_method text,
      umbrella_id uuid,
      first_name text,
      last_name text,
      account_holder text,
      sort_code text,
      account_number text,
      bank_details_hash text,
      payee_id text,
      payee_account_id text,
      umbrella_vat_chargeable boolean
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_build_candidates_ctx (
      id,
      tms_ref,
      display_name,
      pay_method,
      umbrella_id,
      first_name,
      last_name,
      account_holder,
      sort_code,
      account_number,
      bank_details_hash,
      payee_id,
      payee_account_id,
      umbrella_vat_chargeable
    )
    SELECT
      candidate_row.id,
      candidate_row.tms_ref,
      candidate_row.display_name,
      upper(coalesce(candidate_row.pay_method, '')),
      candidate_row.umbrella_id,
      candidate_row.first_name,
      candidate_row.last_name,
      candidate_row.account_holder,
      regexp_replace(coalesce(candidate_row.sort_code, ''), '[^0-9]', '', 'g'),
      nullif(regexp_replace(coalesce(candidate_row.account_number, ''), '[^0-9]', '', 'g'), ''),
      candidate_row.bank_details_hash,
      bank_payee_candidate.payee_id,
      bank_payee_candidate.payee_account_id,
      coalesce(umbrella_row.vat_chargeable, false)
    FROM public.candidates AS candidate_row
    LEFT JOIN public.umbrellas AS umbrella_row
      ON umbrella_row.id = candidate_row.umbrella_id
    LEFT JOIN public.bank_payee_map AS bank_payee_candidate
      ON upper(coalesce(bank_payee_candidate.rail_provider, '')) = upper(btrim(coalesce(v_rail_provider_default, '')))
     AND upper(coalesce(bank_payee_candidate.rail_env, '')) = upper(btrim(coalesce(v_rail_env_default, '')))
     AND upper(coalesce(bank_payee_candidate.entity_kind, '')) = 'CANDIDATE'
     AND bank_payee_candidate.entity_id = candidate_row.id
     AND bank_payee_candidate.bank_details_hash = candidate_row.bank_details_hash
    WHERE candidate_row.id = ANY(v_candidate_ids)
    ON CONFLICT (id) DO NOTHING;

    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_umbrellas_ctx (
      id uuid PRIMARY KEY,
      name text,
      vat_chargeable boolean,
      sort_code text,
      account_number text,
      bank_details_hash text,
      payee_id text,
      payee_account_id text
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_build_umbrellas_ctx (
      id,
      name,
      vat_chargeable,
      sort_code,
      account_number,
      bank_details_hash,
      payee_id,
      payee_account_id
    )
    SELECT
      umbrella_row.id,
      umbrella_row.name,
      coalesce(umbrella_row.vat_chargeable, false),
      regexp_replace(coalesce(umbrella_row.sort_code, ''), '[^0-9]', '', 'g'),
      nullif(regexp_replace(coalesce(umbrella_row.account_number, ''), '[^0-9]', '', 'g'), ''),
      umbrella_row.bank_details_hash,
      bank_payee_umbrella.payee_id,
      bank_payee_umbrella.payee_account_id
    FROM public.umbrellas AS umbrella_row
    JOIN (
      SELECT DISTINCT candidate_ctx.umbrella_id
      FROM pg_temp.tmp_pay_build_candidates_ctx AS candidate_ctx
      WHERE candidate_ctx.umbrella_id IS NOT NULL
    ) AS required_umbrella
      ON required_umbrella.umbrella_id = umbrella_row.id
    LEFT JOIN public.bank_payee_map AS bank_payee_umbrella
      ON upper(coalesce(bank_payee_umbrella.rail_provider, '')) = upper(btrim(coalesce(v_rail_provider_default, '')))
     AND upper(coalesce(bank_payee_umbrella.rail_env, '')) = upper(btrim(coalesce(v_rail_env_default, '')))
     AND upper(coalesce(bank_payee_umbrella.entity_kind, '')) = 'UMBRELLA'
     AND bank_payee_umbrella.entity_id = umbrella_row.id
     AND bank_payee_umbrella.bank_details_hash = umbrella_row.bank_details_hash
    ON CONFLICT (id) DO NOTHING;
  END IF;


v_stage := 'STAGE_21_BREAKDOWN_INTEGRITY_MISSING';

  -- ✅ Integrity checks: every active (non-voided) item must have ≥1 breakdown row; sums must match exactly
  select count(*)
  into v_breakdown_missing_ct
  from public.pay_batch_items pbi_m
  join public.pay_batch_candidates pbc_m
    on pbc_m.id = pbi_m.pay_batch_candidate_id
  where pbc_m.pay_batch_id = v_batch_id
    and (p_operation_id is null or pbc_m.candidate_id = any(v_candidate_ids))
    and coalesce(pbi_m.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_batch_item_breakdowns pbib_m
      where pbib_m.pay_batch_item_id = pbi_m.id
      limit 1
    );

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_21_BREAKDOWN_MISSING_COUNT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_missing_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISSING',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct,0),
          'error', 'PAY_BATCH_BREAKDOWN_MISSING'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', jsonb_build_array(jsonb_build_object(
          'check_code', 'PAY_BATCH_BREAKDOWN_MISSING',
          'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0)
        )),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because one or more active batch items have no breakdown rows.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
      );
    END IF;

    raise exception 'PAY_BATCH_BREAKDOWN_MISSING: % items have no breakdown rows', v_breakdown_missing_ct;
  end if;

  v_stage := 'STAGE_22_BREAKDOWN_INTEGRITY_SUM_MATCH';

  with sums as (
    select
      pbi_s.id as pay_batch_item_id,
      round(pbi_s.amount_ex_vat,2) as item_ex,
      round(pbi_s.amount_vat,2) as item_vat,
      round(pbi_s.amount_inc_vat,2) as item_inc,
      round(coalesce(sum(pbib_s.amount_ex_vat),0),2) as sum_ex,
      round(coalesce(sum(pbib_s.amount_vat),0),2) as sum_vat,
      round(coalesce(sum(pbib_s.amount_inc_vat),0),2) as sum_inc
    from public.pay_batch_items pbi_s
    join public.pay_batch_candidates pbc_s
      on pbc_s.id = pbi_s.pay_batch_candidate_id
    left join public.pay_batch_item_breakdowns pbib_s
      on pbib_s.pay_batch_item_id = pbi_s.id
    where pbc_s.pay_batch_id = v_batch_id
      and (p_operation_id is null or pbc_s.candidate_id = any(v_candidate_ids))
      and coalesce(pbi_s.is_voided, false) = false
    group by pbi_s.id, pbi_s.amount_ex_vat, pbi_s.amount_vat, pbi_s.amount_inc_vat
  ),
  bad as (
    select
      s.pay_batch_item_id,
      s.item_ex, s.sum_ex,
      s.item_vat, s.sum_vat,
      s.item_inc, s.sum_inc
    from sums s
    where s.item_ex <> s.sum_ex
       or s.item_vat <> s.sum_vat
       or s.item_inc <> s.sum_inc
  )
  select
    count(*),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', b.pay_batch_item_id::text,
          'item_ex', b.item_ex, 'sum_ex', b.sum_ex,
          'item_vat', b.item_vat, 'sum_vat', b.sum_vat,
          'item_inc', b.item_inc, 'sum_inc', b.sum_inc
        )
        order by b.pay_batch_item_id::text
      ),
      '[]'::jsonb
    )
  into v_breakdown_bad_ct, v_breakdown_bad
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_22_BREAKDOWN_SUMS_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
        'breakdown_bad_sample', (
          case
            when jsonb_typeof(v_breakdown_bad) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'pay_batch_item_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_breakdown_bad) e
                limit 50
              ) s
            )
            else v_breakdown_bad
          end
        )
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_breakdown_bad_ct,0) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_BREAKDOWN_MISMATCH',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'breakdown_bad_ct', coalesce(v_breakdown_bad_ct,0),
          'breakdown_bad', v_breakdown_bad,
          'error', 'PAY_BATCH_BREAKDOWN_MISMATCH'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', coalesce(v_breakdown_bad, '[]'::jsonb),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because one or more item breakdown totals do not match their batch item totals.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
      );
    END IF;

    raise exception 'PAY_BATCH_BREAKDOWN_MISMATCH %', v_breakdown_bad::text;
  end if;

  v_stage := 'STAGE_23_FINAL_SAFETY_ASSERT_BLOCKERS';

  with destination_items as (
    select
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      upper(coalesce(pbi.pay_channel::text,'')) as pay_channel,
      upper(coalesce(nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind','')), ''), '')) as routing_kind,
      pbi.payout_instruction_snapshot_json,
      pbi.umbrella_id as item_umbrella_id,
      c.umbrella_id as candidate_umbrella_id,
      c.bank_details_hash as candidate_bank_hash,
      u.bank_details_hash as umbrella_bank_hash,
      nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_hash','')), '') as snapshot_bank_hash
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join pg_temp.tmp_pay_build_candidates_ctx c
      on c.id = pbc.candidate_id
    left join pg_temp.tmp_pay_build_umbrellas_ctx u
      on u.id = coalesce(pbi.umbrella_id, c.umbrella_id)
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.item_type <> 'DEBT_CREATED'
      and pbc.candidate_id = any(v_candidate_ids)
  ),
  destinations as (
    select distinct
      di.candidate_id,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'CANDIDATE'
        when di.pay_channel = 'PAYE' then 'CANDIDATE'
        when di.routing_kind = 'UMBRELLA_COMPANY' then 'UMBRELLA'
        when di.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
         and di.pay_channel = 'UMBRELLA' then 'UMBRELLA'
        else 'CANDIDATE'
      end as entity_kind,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then di.candidate_id
        when di.pay_channel = 'PAYE' then di.candidate_id
        when di.routing_kind = 'UMBRELLA_COMPANY' then coalesce(di.item_umbrella_id, di.candidate_umbrella_id)
        when di.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
         and di.pay_channel = 'UMBRELLA' then coalesce(di.item_umbrella_id, di.candidate_umbrella_id)
        else di.candidate_id
      end as entity_id,
      case
        when di.routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then di.snapshot_bank_hash
        when di.pay_channel = 'PAYE' then di.candidate_bank_hash
        when di.routing_kind = 'UMBRELLA_COMPANY' then di.umbrella_bank_hash
        when di.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
         and di.pay_channel = 'UMBRELLA' then di.umbrella_bank_hash
        else di.candidate_bank_hash
      end as bank_hash
    from destination_items di
  ),
  destination_blockers as (

    select
      d.candidate_id,
      d.entity_kind,
      d.entity_id,
      d.bank_hash,
      (
        (case
           when d.entity_id is null or d.bank_hash is null or btrim(d.bank_hash) = '' then jsonb_build_array('BLOCKED_BANK_DETAILS')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_need_name_check = true
            and not exists (
              select 1
              from public.bank_name_checks bnc
              where upper(coalesce(bnc.rail_provider,'')) = upper(btrim(coalesce(v_rail_provider_default,'')))
                and upper(coalesce(bnc.rail_env,'')) = upper(btrim(coalesce(v_rail_env_default,'')))
                and upper(coalesce(bnc.entity_kind,'')) = d.entity_kind
                and bnc.entity_id = d.entity_id
                and bnc.bank_details_hash = d.bank_hash
                and (
                  upper(coalesce(bnc.status,'')) = 'PASS'
                  or (
                    bnc.override_reason is not null
                    and bnc.override_hash is not null
                    and bnc.override_hash = d.bank_hash
                  )
                )
              limit 1
            )
           then jsonb_build_array('BLOCKED_NAME_CHECK')
           else '[]'::jsonb
         end)
        ||
        (case
           when d.entity_id is not null
            and d.bank_hash is not null and btrim(d.bank_hash) <> ''
            and v_requires_payee_map = true
            and not exists (
              select 1
              from public.bank_payee_map bpm
              where upper(coalesce(bpm.rail_provider,'')) = upper(btrim(coalesce(v_rail_provider_default,'')))
                and upper(coalesce(bpm.rail_env,'')) = upper(btrim(coalesce(v_rail_env_default,'')))
                and upper(coalesce(bpm.entity_kind,'')) = d.entity_kind
                and bpm.entity_id = d.entity_id
                and bpm.bank_details_hash = d.bank_hash
              limit 1
            )
           then jsonb_build_array('BLOCKED_NO_PAYEE_MAP')
           else '[]'::jsonb
         end)
      ) as blockers
    from destinations d
  ),
  bad as (
    select
      db.candidate_id,
      db.blockers
    from destination_blockers db
    where jsonb_array_length(db.blockers) > 0
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', b.candidate_id::text,
        'blockers', b.blockers
      )
      order by b.candidate_id::text
    ),
    '[]'::jsonb
  )
  into v_blocked_candidates
  from bad b;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23_BLOCKER_ASSERT_RESULT',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'blocked_candidates', (
          case
            when jsonb_typeof(v_blocked_candidates) = 'array' then (
              select coalesce(jsonb_agg(x order by (x->>'candidate_id')), '[]'::jsonb)
              from (
                select e as x
                from jsonb_array_elements(v_blocked_candidates) e
                limit 50
              ) s
            )
            else v_blocked_candidates
          end
        ),
        'blocked_count', jsonb_array_length(v_blocked_candidates)
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if jsonb_array_length(v_blocked_candidates) > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:ERROR_DRAFT_CONTAINS_BLOCKED_ITEMS',
        jsonb_build_object(
          'stage', v_stage,
          'pay_batch_id', v_batch_id::text,
          'blocked_candidates', v_blocked_candidates,
          'error', 'DRAFT_CONTAINS_BLOCKED_ITEMS'
        ),
        'pay_batches',
        v_batch_id::text,
        null, null, null, null, null
      );
    exception when others then null; end;

    IF p_operation_id IS NOT NULL THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'mismatch_details', coalesce(v_blocked_candidates, '[]'::jsonb),
        'affected_candidate_ids', coalesce((
          SELECT jsonb_agg(DISTINCT blocked_candidate.value->>'candidate_id')
          FROM jsonb_array_elements(coalesce(v_blocked_candidates, '[]'::jsonb)) AS blocked_candidate(value)
          WHERE NULLIF(blocked_candidate.value->>'candidate_id', '') IS NOT NULL
        ), '[]'::jsonb),
        'friendly_error_message', 'Draft integrity failed because the draft contains blocked payment destinations.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
      );
    END IF;

    raise exception 'DRAFT_CONTAINS_BLOCKED_ITEMS %', v_blocked_candidates::text;
  end if;

  v_stage := 'STAGE_23B_CONSUME_TIMESHEET_PAYMENT_OVERRIDES';

  with consumed as (
    update public.timesheet_payment_overrides tpo
    set
      consumed_by_pay_batch_id = v_batch_id,
      consumed_at_utc = v_now_utc
    where tpo.cleared_at_utc is null
      and tpo.consumed_by_pay_batch_id is null
      and tpo.consumed_at_utc is null
      and upper(coalesce(tpo.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
      and tpo.id in (
        select tpo_pick.id
        from (
          select distinct on (tpo2.timesheet_id)
            tpo2.id,
            tpo2.timesheet_id
          from public.timesheet_payment_overrides tpo2
          where tpo2.cleared_at_utc is null
            and tpo2.consumed_by_pay_batch_id is null
            and tpo2.consumed_at_utc is null
            and upper(coalesce(tpo2.override_type,'')) = 'ADVANCE_THIS_PAYMENT'
            and exists (
              select 1
              from public.pay_batch_items pbi
              join public.pay_batch_candidates pbc
                on pbc.id = pbi.pay_batch_candidate_id
              where pbc.pay_batch_id = v_batch_id
                and (p_operation_id is null or pbc.candidate_id = any(v_candidate_ids))
                and pbi.timesheet_id = tpo2.timesheet_id
                and coalesce(pbi.is_voided, false) = false
                and pbi.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
            )
          order by tpo2.timesheet_id, tpo2.created_at_utc desc, tpo2.id desc
        ) tpo_pick
      )
    returning
      tpo.id,
      tpo.timesheet_id,
      tpo.candidate_id,
      tpo.override_type,
      tpo.reason,
      tpo.created_at_utc,
      tpo.created_by_user_id,
      tpo.consumed_by_pay_batch_id,
      tpo.consumed_at_utc
  )
  select
    count(*)::int,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'override_id', consumed.id::text,
          'timesheet_id', consumed.timesheet_id::text,
          'candidate_id', case when consumed.candidate_id is null then null else consumed.candidate_id::text end,
          'override_type', consumed.override_type,
          'reason', consumed.reason,
          'created_at_utc', consumed.created_at_utc,
          'created_by_user_id', case when consumed.created_by_user_id is null then null else consumed.created_by_user_id::text end,
          'consumed_by_pay_batch_id', case when consumed.consumed_by_pay_batch_id is null then null else consumed.consumed_by_pay_batch_id::text end,
          'consumed_at_utc', consumed.consumed_at_utc
        )
        order by consumed.timesheet_id::text, consumed.id::text
      ),
      '[]'::jsonb
    )
  into
    v_rows_upd_timesheet_overrides_consumed,
    v_consumed_timesheet_payment_overrides
  from consumed;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:STAGE_23B_TIMESHEET_OVERRIDES_CONSUMED',
      jsonb_build_object(
        'stage', v_stage,
        'pay_batch_id', v_batch_id::text,
        'consumed_timesheet_payment_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0),
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
      ),
      'pay_batches',
      v_batch_id::text,
      null, null, null, null, null
    );
  exception when others then null; end;

  if coalesce(v_rows_upd_timesheet_overrides_consumed, 0) > 0 then
    for v_override_consume_rec in
      select
        x.override_id::uuid as override_id,
        x.timesheet_id::uuid as timesheet_id,
        case when x.candidate_id is null or btrim(x.candidate_id) = '' then null else x.candidate_id::uuid end as candidate_id,
        x.override_type,
        x.reason,
        case when x.created_by_user_id is null or btrim(x.created_by_user_id) = '' then null else x.created_by_user_id::uuid end as created_by_user_id,
        x.created_at_utc::timestamptz as created_at_utc,
        case when x.consumed_by_pay_batch_id is null or btrim(x.consumed_by_pay_batch_id) = '' then null else x.consumed_by_pay_batch_id::uuid end as consumed_by_pay_batch_id,
        x.consumed_at_utc::timestamptz as consumed_at_utc
      from jsonb_to_recordset(v_consumed_timesheet_payment_overrides) as x(
        override_id text,
        timesheet_id text,
        candidate_id text,
        override_type text,
        reason text,
        created_at_utc text,
        created_by_user_id text,
        consumed_by_pay_batch_id text,
        consumed_at_utc text
      )
    loop
      begin
        perform public._audit_insert(
          'timesheets',
          v_override_consume_rec.timesheet_id::text,
          'TIMESHEET_PAYMENT_OVERRIDE_CONSUMED',
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'override_type', v_override_consume_rec.override_type,
            'reason', v_override_consume_rec.reason,
            'created_at_utc', v_override_consume_rec.created_at_utc,
            'created_by_user_id', case when v_override_consume_rec.created_by_user_id is null then null else v_override_consume_rec.created_by_user_id::text end
          ),
          jsonb_build_object(
            'override_id', v_override_consume_rec.override_id::text,
            'timesheet_id', v_override_consume_rec.timesheet_id::text,
            'candidate_id', case when v_override_consume_rec.candidate_id is null then null else v_override_consume_rec.candidate_id::text end,
            'consumed_by_pay_batch_id', case when v_override_consume_rec.consumed_by_pay_batch_id is null then null else v_override_consume_rec.consumed_by_pay_batch_id::text end,
            'consumed_at_utc', v_override_consume_rec.consumed_at_utc,
            'pay_batch_id', v_batch_id::text
          ),
          'ADVANCE_THIS_PAYMENT',
          p_actor_user_id
        );
      exception when others then
        null;
      end;
    end loop;
  end if;

  


  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer
    INTO v_operation_active_item_count
    FROM public.pay_batch_items AS item_row
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = item_row.pay_batch_candidate_id
    WHERE batch_candidate.pay_batch_id = v_batch_id
      AND coalesce(item_row.is_voided, false) = false;

    SELECT count(*)::integer,
           count(*) FILTER (
             WHERE lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) IN ('true','t','1','yes','y')
           )::integer
    INTO v_operation_scope_count, v_operation_reservation_unavailable_scope_count
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = v_batch_id;

    IF coalesce(v_operation_active_item_count, 0) = 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'error', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
          ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
        END,
        'code', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
          ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
        END,
        'message', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
          ELSE 'No draft was created because no payable items remained after eligibility checks.'
        END,
        'friendly_error_message', CASE
          WHEN coalesce(v_operation_scope_count, 0) > 0
           AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
            THEN 'No draft was created because all selected payments are already reserved in another active draft batch.'
          ELSE 'No draft was created because no payable items remained after eligibility checks.'
        END,
        'mismatch_details', jsonb_build_array(jsonb_build_object(
          'check_code', CASE
            WHEN coalesce(v_operation_scope_count, 0) > 0
             AND coalesce(v_operation_reservation_unavailable_scope_count, 0) = coalesce(v_operation_scope_count, 0)
              THEN 'PAY_DRAFT_ALL_SELECTED_PAYMENTS_ALREADY_RESERVED'
            ELSE 'PAY_DRAFT_NO_PAYABLE_ITEMS_REMAIN'
          END,
          'active_item_count', coalesce(v_operation_active_item_count, 0),
          'operation_scope_count', coalesce(v_operation_scope_count, 0),
          'reservation_unavailable_scope_count', coalesce(v_operation_reservation_unavailable_scope_count, 0)
        )),
        'affected_candidate_ids', coalesce(to_jsonb(v_candidate_ids), '[]'::jsonb),
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
      );
    END IF;

    WITH operation_checks AS (
      SELECT 'MISSING_BATCH_CANDIDATE'::text AS check_code,
             scope_row.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', scope_row.id::text,
               'candidate_id', scope_row.candidate_id::text,
               'pay_channel', scope_row.pay_channel
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_scope AS scope_row
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = v_batch_id
        AND lower(coalesce(scope_row.allocation_basis_json #>> '{reservation_availability,all_selected_rows_unavailable}', 'false')) NOT IN ('true','t','1','yes','y')
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS batch_candidate
          WHERE batch_candidate.pay_batch_id = v_batch_id
            AND batch_candidate.candidate_id = scope_row.candidate_id
        )

      UNION ALL

      SELECT 'UNLINKED_ALLOCATION_ROW'::text AS check_code,
             allocation_row.candidate_id,
             jsonb_build_object(
               'allocation_row_id', allocation_row.id::text,
               'candidate_scope_id', allocation_row.candidate_scope_id::text,
               'candidate_id', allocation_row.candidate_id::text,
               'pay_channel', allocation_row.pay_channel,
               'operation_source_key', allocation_row.operation_source_key
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.pay_batch_id = v_batch_id
        AND (allocation_row.status <> 'ITEM_CREATED' OR allocation_row.pay_batch_item_id IS NULL)

      UNION ALL

      SELECT 'DUPLICATE_BATCH_CANDIDATE'::text AS check_code,
             duplicate_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', duplicate_candidate.candidate_id::text,
               'duplicate_count', duplicate_candidate.duplicate_count
             ) AS detail_json
      FROM (
        SELECT batch_candidate.candidate_id, count(*)::integer AS duplicate_count
        FROM public.pay_batch_candidates AS batch_candidate
        WHERE batch_candidate.pay_batch_id = v_batch_id
          AND batch_candidate.candidate_id = ANY(v_candidate_ids)
        GROUP BY batch_candidate.candidate_id
        HAVING count(*) > 1
      ) AS duplicate_candidate

      UNION ALL

      SELECT 'DUPLICATE_OPERATION_ITEM_KEY'::text AS check_code,
             batch_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', batch_candidate.candidate_id::text,
               'operation_source_key', duplicate_item.operation_source_key,
               'duplicate_count', duplicate_item.duplicate_count
             ) AS detail_json
      FROM (
        SELECT item_row.pay_batch_candidate_id, item_row.operation_source_key, count(*)::integer AS duplicate_count
        FROM public.pay_batch_items AS item_row
        WHERE item_row.operation_source_key IS NOT NULL
          AND item_row.operation_source_key LIKE (p_operation_id::text || ':%')
        GROUP BY item_row.pay_batch_candidate_id, item_row.operation_source_key
        HAVING count(*) > 1
      ) AS duplicate_item
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = duplicate_item.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_batch_id

      UNION ALL

      SELECT 'DUPLICATE_OPERATION_BREAKDOWN_KEY'::text AS check_code,
             batch_candidate.candidate_id,
             jsonb_build_object(
               'candidate_id', batch_candidate.candidate_id::text,
               'operation_source_key', duplicate_breakdown.operation_source_key,
               'duplicate_count', duplicate_breakdown.duplicate_count
             ) AS detail_json
      FROM (
        SELECT breakdown_row.pay_batch_item_id, breakdown_row.operation_source_key, count(*)::integer AS duplicate_count
        FROM public.pay_batch_item_breakdowns AS breakdown_row
        WHERE breakdown_row.operation_source_key IS NOT NULL
          AND breakdown_row.operation_source_key LIKE (p_operation_id::text || ':%')
        GROUP BY breakdown_row.pay_batch_item_id, breakdown_row.operation_source_key
        HAVING count(*) > 1
      ) AS duplicate_breakdown
      JOIN public.pay_batch_items AS item_row
        ON item_row.id = duplicate_breakdown.pay_batch_item_id
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = item_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_batch_id

      UNION ALL

      SELECT 'DUPLICATE_TIMESHEET_SNAPSHOT'::text AS check_code,
             snapshot_duplicate.candidate_id,
             jsonb_build_object(
               'timesheet_id', snapshot_duplicate.timesheet_id::text,
               'candidate_id', snapshot_duplicate.candidate_id::text,
               'pay_channel', snapshot_duplicate.pay_channel,
               'duplicate_count', snapshot_duplicate.duplicate_count
             ) AS detail_json
      FROM (
        SELECT snapshot_row.timesheet_id, snapshot_row.candidate_id, snapshot_row.pay_channel, count(*)::integer AS duplicate_count
        FROM public.pay_batch_timesheet_snapshots AS snapshot_row
        WHERE snapshot_row.pay_batch_id = v_batch_id
          AND snapshot_row.candidate_id = ANY(v_candidate_ids)
        GROUP BY snapshot_row.timesheet_id, snapshot_row.candidate_id, snapshot_row.pay_channel
        HAVING count(*) > 1
      ) AS snapshot_duplicate

      UNION ALL

      SELECT 'MISSING_SELECTED_PREVIEW_ROW_ITEM'::text AS check_code,
             selected_line.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', selected_line.candidate_scope_id::text,
               'candidate_id', selected_line.candidate_id::text,
               'pay_channel', selected_line.pay_channel,
               'preview_row_id', selected_line.preview_row_id,
               'finance_case_id', CASE WHEN selected_line.finance_case_id IS NULL THEN NULL ELSE selected_line.finance_case_id::text END,
               'timesheet_id', CASE WHEN selected_line.timesheet_id IS NULL THEN NULL ELSE selected_line.timesheet_id::text END
             ) AS detail_json
      FROM (
        SELECT
          scope_row.id AS candidate_scope_id,
          scope_row.candidate_id,
          scope_row.pay_channel,
          coalesce(
            nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'id', '')), '')
          ) AS preview_row_id,
          CASE WHEN coalesce(line_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (line_element.value->>'finance_case_id')::uuid ELSE NULL::uuid END AS finance_case_id,
          CASE WHEN coalesce(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN (line_element.value->>'timesheet_id')::uuid ELSE NULL::uuid END AS timesheet_id,
          upper(btrim(coalesce(line_element.value->>'line_type', line_element.value->>'item_type', line_element.value->>'case_type', ''))) AS line_type,
          round(coalesce(
            CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
            CASE WHEN coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
            0::numeric
          ), 2) AS expected_amount_ex_vat,
          coalesce(
            lower(coalesce(reservation_metadata.reservation_json->>'skipped_due_to_active_reservation', 'false')) IN ('true','t','1','yes','y'),
            false
          ) AS skipped_due_to_active_reservation
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        CROSS JOIN LATERAL jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS line_element(value)
        LEFT JOIN LATERAL (
          SELECT reservation_row.value AS reservation_json
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
              ELSE '[]'::jsonb
            END
          ) AS reservation_row(value)
          WHERE reservation_row.value->>'preview_row_id' = coalesce(
            nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
            nullif(btrim(coalesce(line_element.value->>'id', '')), '')
          )
          LIMIT 1
        ) AS reservation_metadata ON true
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = v_batch_id
          AND jsonb_typeof(line_element.value) = 'object'
          AND coalesce(CASE WHEN lower(coalesce(line_element.value->>'draftable', 'true')) IN ('true','false') THEN (line_element.value->>'draftable')::boolean ELSE true END, true) = true
      ) AS selected_line
      WHERE selected_line.preview_row_id IS NOT NULL
        AND coalesce(selected_line.skipped_due_to_active_reservation, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS batch_candidate
          JOIN public.pay_batch_items AS item_row
            ON item_row.pay_batch_candidate_id = batch_candidate.id
          WHERE batch_candidate.pay_batch_id = v_batch_id
            AND batch_candidate.candidate_id = selected_line.candidate_id
            AND coalesce(item_row.is_voided, false) = false
            AND (
              (item_row.operation_source_key IS NOT NULL AND item_row.operation_source_key LIKE (p_operation_id::text || ':%') AND item_row.operation_source_key LIKE ('%' || selected_line.preview_row_id || '%'))
              OR (selected_line.finance_case_id IS NOT NULL AND item_row.finance_case_id = selected_line.finance_case_id)
              OR (selected_line.timesheet_id IS NOT NULL AND item_row.timesheet_id = selected_line.timesheet_id AND item_row.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA'))
            )
          LIMIT 1
        )

      UNION ALL

      SELECT 'CANDIDATE_SCOPE_TOTAL_MISMATCH'::text AS check_code,
             scope_totals.candidate_id,
             jsonb_build_object(
               'candidate_scope_id', scope_totals.candidate_scope_id::text,
               'candidate_id', scope_totals.candidate_id::text,
               'pay_channel', scope_totals.pay_channel,
               'expected_amount_ex_vat', scope_totals.expected_amount_ex_vat,
               'actual_amount_ex_vat', scope_totals.actual_amount_ex_vat
             ) AS detail_json
      FROM (
        SELECT
          scope_row.id AS candidate_scope_id,
          scope_row.candidate_id,
          scope_row.pay_channel,
          round(coalesce((
            SELECT sum(
              round(coalesce(
                CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
                CASE WHEN coalesce(selected_line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
                CASE WHEN coalesce(selected_line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (selected_line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
                0::numeric
              ), 2)
            )
            FROM jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS selected_line_element(value)
            LEFT JOIN LATERAL (
              SELECT reservation_row.value AS reservation_json
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                    THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
                  ELSE '[]'::jsonb
                END
              ) AS reservation_row(value)
              WHERE reservation_row.value->>'preview_row_id' = coalesce(
                nullif(btrim(coalesce(selected_line_element.value->>'preview_row_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'line_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'row_id', '')), ''),
                nullif(btrim(coalesce(selected_line_element.value->>'id', '')), '')
              )
              LIMIT 1
            ) AS reservation_metadata ON true
            WHERE jsonb_typeof(selected_line_element.value) = 'object'
              AND coalesce(CASE WHEN lower(coalesce(selected_line_element.value->>'draftable', 'true')) IN ('true','false') THEN (selected_line_element.value->>'draftable')::boolean ELSE true END, true) = true
          ), 0::numeric), 2) AS expected_amount_ex_vat,
          round(coalesce((
            SELECT sum(coalesce(item_row.amount_ex_vat, 0))
            FROM public.pay_batch_candidates AS batch_candidate
            JOIN public.pay_batch_items AS item_row
              ON item_row.pay_batch_candidate_id = batch_candidate.id
            WHERE batch_candidate.pay_batch_id = v_batch_id
              AND batch_candidate.candidate_id = scope_row.candidate_id
              AND upper(coalesce(item_row.pay_channel, '')) = upper(coalesce(scope_row.pay_channel, ''))
              AND coalesce(item_row.is_voided, false) = false
          ), 0), 2) AS actual_amount_ex_vat
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = v_batch_id
      ) AS scope_totals
      WHERE scope_totals.expected_amount_ex_vat IS NOT NULL
        AND scope_totals.expected_amount_ex_vat <> scope_totals.actual_amount_ex_vat

      UNION ALL

      SELECT 'ALLOCATION_ITEM_AMOUNT_MISMATCH'::text AS check_code,
             allocation_row.candidate_id,
             jsonb_build_object(
               'allocation_row_id', allocation_row.id::text,
               'pay_batch_item_id', CASE WHEN item_row.id IS NULL THEN NULL ELSE item_row.id::text END,
               'candidate_id', allocation_row.candidate_id::text,
               'pay_channel', allocation_row.pay_channel,
               'operation_source_key', allocation_row.operation_source_key,
               'expected_allocated_amount', round(coalesce(allocation_row.allocated_amount, 0), 2),
               'actual_item_amount_ex_vat', CASE WHEN item_row.id IS NULL THEN NULL ELSE round(coalesce(item_row.amount_ex_vat, 0), 2) END
             ) AS detail_json
      FROM public.banking_pay_operation_candidate_allocation_rows AS allocation_row
      LEFT JOIN public.pay_batch_items AS item_row
        ON item_row.id = allocation_row.pay_batch_item_id
       AND coalesce(item_row.is_voided, false) = false
      WHERE allocation_row.operation_id = p_operation_id
        AND allocation_row.pay_batch_id = v_batch_id
        AND allocation_row.status = 'ITEM_CREATED'
        AND (
          item_row.id IS NULL
          OR round(coalesce(item_row.amount_ex_vat, 0), 2) <> round(coalesce(allocation_row.allocated_amount, 0), 2)
        )

      UNION ALL

      SELECT 'PAY_CHANNEL_SCOPE_TOTAL_MISMATCH'::text AS check_code,
             NULL::uuid AS candidate_id,
             jsonb_build_object(
               'pay_channel', channel_totals.pay_channel,
               'expected_amount_ex_vat', channel_totals.expected_amount_ex_vat,
               'actual_amount_ex_vat', channel_totals.actual_amount_ex_vat
             ) AS detail_json
      FROM (
        SELECT
          expected_channel.pay_channel,
          round(sum(expected_channel.expected_amount_ex_vat), 2) AS expected_amount_ex_vat,
          round(coalesce((
            SELECT sum(coalesce(item_row.amount_ex_vat, 0))
            FROM public.pay_batch_items AS item_row
            JOIN public.pay_batch_candidates AS batch_candidate
              ON batch_candidate.id = item_row.pay_batch_candidate_id
            WHERE batch_candidate.pay_batch_id = v_batch_id
              AND upper(coalesce(item_row.pay_channel, '')) = expected_channel.pay_channel
              AND coalesce(item_row.is_voided, false) = false
          ), 0), 2) AS actual_amount_ex_vat
        FROM (
          SELECT
            upper(btrim(coalesce(scope_row.pay_channel, ''))) AS pay_channel,
            round(coalesce(
              CASE WHEN coalesce(reservation_metadata.reservation_json->>'effective_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (reservation_metadata.reservation_json->>'effective_amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN coalesce(line_element.value->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'amount_ex_vat')::numeric ELSE NULL::numeric END,
              CASE WHEN coalesce(line_element.value->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN (line_element.value->>'preview_amount_ex_vat')::numeric ELSE NULL::numeric END,
              0::numeric
            ), 2) AS expected_amount_ex_vat
          FROM public.banking_pay_operation_candidate_scope AS scope_row
          CROSS JOIN LATERAL jsonb_array_elements(coalesce(scope_row.selected_canonical_preview_lines_json, '[]'::jsonb)) AS line_element(value)
          LEFT JOIN LATERAL (
            SELECT reservation_row.value AS reservation_json
            FROM jsonb_array_elements(
              CASE
                WHEN jsonb_typeof(scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}') = 'array'
                  THEN scope_row.allocation_basis_json #> '{reservation_availability,preview_rows}'
                ELSE '[]'::jsonb
              END
            ) AS reservation_row(value)
            WHERE reservation_row.value->>'preview_row_id' = coalesce(
              nullif(btrim(coalesce(line_element.value->>'preview_row_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'line_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'row_id', '')), ''),
              nullif(btrim(coalesce(line_element.value->>'id', '')), '')
            )
            LIMIT 1
          ) AS reservation_metadata ON true
          WHERE scope_row.operation_id = p_operation_id
            AND scope_row.pay_batch_id = v_batch_id
            AND jsonb_typeof(line_element.value) = 'object'
            AND coalesce(CASE WHEN lower(coalesce(line_element.value->>'draftable', 'true')) IN ('true','false') THEN (line_element.value->>'draftable')::boolean ELSE true END, true) = true
        ) AS expected_channel
        WHERE expected_channel.pay_channel IN ('PAYE','UMBRELLA')
        GROUP BY expected_channel.pay_channel
      ) AS channel_totals
      WHERE channel_totals.expected_amount_ex_vat <> channel_totals.actual_amount_ex_vat
    )
    SELECT count(*)::integer,
           coalesce(jsonb_agg(operation_checks.detail_json || jsonb_build_object('check_code', operation_checks.check_code) order by operation_checks.check_code, operation_checks.candidate_id::text), '[]'::jsonb),
           coalesce(jsonb_agg(distinct to_jsonb(operation_checks.candidate_id::text)) filter (where operation_checks.candidate_id is not null), '[]'::jsonb)
    INTO v_operation_mismatch_count, v_operation_mismatch_details, v_operation_affected_candidate_ids
    FROM operation_checks;

    IF coalesce(v_operation_mismatch_count, 0) > 0 THEN
      RETURN jsonb_build_object(
        'ok', false,
        'pay_batch_id', v_batch_id::text,
        'operation_id', p_operation_id::text,
        'pass', false,
        'error', 'DRAFT_INTEGRITY_FAILED',
        'code', 'DRAFT_INTEGRITY_FAILED',
        'mismatch_details', coalesce(v_operation_mismatch_details, '[]'::jsonb),
        'affected_candidate_ids', coalesce(v_operation_affected_candidate_ids, '[]'::jsonb),
        'friendly_error_message', 'Operation draft integrity checks failed. The chunked draft does not exactly match the snapshotted operation scope.',
        'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
        'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
        'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
        'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'pass', true,
    'mismatch_details', coalesce(v_operation_mismatch_details, '{}'::jsonb),
    'affected_candidate_ids', coalesce(v_operation_affected_candidate_ids, '[]'::jsonb),
    'friendly_error_message', null::text,
    'breakdown_missing_ct', coalesce(v_breakdown_missing_ct, 0),
    'breakdown_bad_ct', coalesce(v_breakdown_bad_ct, 0),
    'blocked_count', jsonb_array_length(coalesce(v_blocked_candidates, '[]'::jsonb)),
    'consumed_timesheet_override_count', coalesce(v_rows_upd_timesheet_overrides_consumed, 0)
  );
END;
$function$;






DROP FUNCTION IF EXISTS public.pay_build_batch_artifacts_from_preview(date, date, uuid, jsonb, jsonb, uuid, uuid, bigint);



DROP FUNCTION IF EXISTS public.pay_build_batch_artifacts_from_preview(date, date, uuid, jsonb, jsonb, uuid, uuid, bigint);
DROP FUNCTION IF EXISTS public.pay_build_batch_artifacts_from_preview(date, date, uuid, jsonb, jsonb, uuid, uuid, bigint, uuid, jsonb, uuid, boolean);

CREATE OR REPLACE FUNCTION public.pay_build_batch_artifacts_from_preview(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_preview_payload_json jsonb,
  p_selected_preview_row_ids jsonb DEFAULT '[]'::jsonb,
  p_source_workbench_session_id uuid DEFAULT NULL::uuid,
  p_source_snapshot_run_id uuid DEFAULT NULL::uuid,
  p_source_session_version bigint DEFAULT NULL::bigint,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_candidate_scope_ids jsonb DEFAULT NULL::jsonb,
  p_existing_pay_batch_id uuid DEFAULT NULL::uuid,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_week_start date := public._pay_week_start_monday(p_pay_date);
  v_preview_payload_json jsonb := CASE WHEN jsonb_typeof(coalesce(p_preview_payload_json, '{}'::jsonb)) = 'object' THEN coalesce(p_preview_payload_json, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_selected_preview_row_ids_input jsonb := coalesce(p_selected_preview_row_ids, '[]'::jsonb);
  v_selected_preview_rows_supplied boolean := false;
  v_selected_preview_row_count integer := 0;
  v_pay_batch_id uuid := NULL::uuid;
  v_scope text := NULL;
  v_settings_bank_system text := NULL;
  v_settings_external_paye_system text := NULL;
  v_settings_rail_provider text := NULL;
  v_settings_rail_env text := NULL;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_vat_rate_pct numeric := NULL::numeric;
  v_erni_pct numeric := NULL::numeric;
  v_insert_candidates_json jsonb := '{}'::jsonb;
  v_insert_items_json jsonb := '{}'::jsonb;
  v_finance_json jsonb := '{}'::jsonb;
  v_finalize_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_snapshots_json jsonb := '{}'::jsonb;
  v_breakdowns_json jsonb := '{}'::jsonb;
  v_integrity_json jsonb := '{}'::jsonb;
  v_candidate_ids jsonb := '[]'::jsonb;
  v_hidden_template_input_count integer := 0;
  v_hidden_template_selected_candidate_input_count integer := 0;
  v_hidden_template_staged_count integer := 0;
  v_hidden_template_manual_debt_staged_count integer := 0;
  v_hidden_template_loan_staged_count integer := 0;
  v_hidden_template_overpayment_staged_count integer := 0;
  v_hidden_template_filtered_candidate_count integer := 0;
  v_hidden_template_filtered_pay_channel_count integer := 0;
  v_hidden_template_filtered_required_identifiers_count integer := 0;
  v_hidden_template_blank_pay_channel_paye_fallback_count integer := 0;
  v_hidden_template_input_by_candidate jsonb := '{}'::jsonb;
  v_hidden_template_input_by_family jsonb := '{}'::jsonb;
  v_hidden_template_input_by_pay_channel jsonb := '{}'::jsonb;
  v_hidden_template_staged_manual_debt_by_candidate jsonb := '{}'::jsonb;
  v_missing_manual_debt_template_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_operation_scope_count integer := 0;
  v_operation_stage_context_json jsonb := '{}'::jsonb;
  v_operation_pay_batch public.pay_batches%rowtype;
BEGIN

  IF p_operation_id IS NOT NULL THEN
    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'actor_user_id is required for operation-mode pay_build_batch_artifacts_from_preview';
    END IF;

    IF p_existing_pay_batch_id IS NULL THEN
      RAISE EXCEPTION 'p_existing_pay_batch_id is required when p_operation_id is supplied';
    END IF;

    IF p_candidate_scope_ids IS NULL OR jsonb_typeof(p_candidate_scope_ids) <> 'array' OR jsonb_array_length(p_candidate_scope_ids) = 0 THEN
      RAISE EXCEPTION 'p_candidate_scope_ids must be a non-empty JSON array when p_operation_id is supplied';
    END IF;

    SELECT batch_row.*
    INTO v_operation_pay_batch
    FROM public.pay_batches AS batch_row
    WHERE batch_row.id = p_existing_pay_batch_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview operation-mode pay batch not found: %', p_existing_pay_batch_id;
    END IF;

    IF v_operation_pay_batch.status <> 'DRAFT' THEN
      RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview operation-mode pay batch % is not DRAFT: %', p_existing_pay_batch_id, v_operation_pay_batch.status;
    END IF;

    SELECT upper(btrim(coalesce(scope_row.pay_channel, '')))
    INTO v_scope
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_existing_pay_batch_id
      AND scope_row.id IN (
          SELECT (scope_id.value #>> '{}')::uuid
          FROM jsonb_array_elements(p_candidate_scope_ids) AS scope_id(value)
          WHERE (scope_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      AND upper(btrim(coalesce(scope_row.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
    GROUP BY upper(btrim(coalesce(scope_row.pay_channel, '')))
    ORDER BY upper(btrim(coalesce(scope_row.pay_channel, '')))
    LIMIT 1;

    IF v_scope IS NULL THEN
      RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview operation-mode cannot determine pay channel scope for operation %', p_operation_id;
    END IF;

    IF (
      SELECT count(*)::integer
      FROM (
        SELECT DISTINCT upper(btrim(coalesce(scope_row.pay_channel, ''))) AS pay_channel_scope
        FROM public.banking_pay_operation_candidate_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_existing_pay_batch_id
          AND scope_row.id IN (
              SELECT (scope_id.value #>> '{}')::uuid
              FROM jsonb_array_elements(p_candidate_scope_ids) AS scope_id(value)
              WHERE (scope_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          )
          AND upper(btrim(coalesce(scope_row.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
      ) AS scope_count_rows
    ) <> 1 THEN
      RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview operation-mode candidate scope chunk must contain exactly one pay channel scope';
    END IF;

    SELECT count(*)::integer
    INTO v_operation_scope_count
    FROM public.banking_pay_operation_candidate_scope AS scope_row
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_existing_pay_batch_id
      AND scope_row.id IN (
          SELECT (scope_id.value #>> '{}')::uuid
          FROM jsonb_array_elements(p_candidate_scope_ids) AS scope_id(value)
          WHERE (scope_id.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      );

    IF v_operation_scope_count <> jsonb_array_length(p_candidate_scope_ids) THEN
      RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview operation-mode one or more candidate scope ids do not belong to operation % and batch %', p_operation_id, p_existing_pay_batch_id;
    END IF;

    SELECT to_jsonb(stage_context_row)
    INTO v_operation_stage_context_json
    FROM public.pay_batch_stage_operation_candidate_chunk_context(
      p_operation_id,
      p_existing_pay_batch_id,
      p_candidate_scope_ids,
      p_actor_user_id
    ) AS stage_context_row;

    v_insert_candidates_json := public.pay_batch_insert_candidates_from_preview(
      p_existing_pay_batch_id,
      p_actor_user_id,
      p_operation_id,
      p_candidate_scope_ids
    );

    v_insert_items_json := public.pay_batch_insert_items_from_preview(
      p_existing_pay_batch_id,
      p_actor_user_id,
      p_operation_id,
      p_candidate_scope_ids
    );

    v_finance_json := public.pay_batch_apply_finance_adjustments(
      p_existing_pay_batch_id,
      v_scope,
      p_actor_user_id,
      NULL::numeric,
      NULL::date,
      p_operation_id,
      p_candidate_scope_ids
    );

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'pay_batch_id', p_existing_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'candidate_scope_count', v_operation_scope_count,
      'pay_channel_scope', v_scope,
      'stages', jsonb_build_object(
        'stage_context', coalesce(v_operation_stage_context_json, '{}'::jsonb),
        'insert_candidates', coalesce(v_insert_candidates_json, '{}'::jsonb),
        'insert_items', coalesce(v_insert_items_json, '{}'::jsonb),
        'finance_adjustments', coalesce(v_finance_json, '{}'::jsonb)
      )
    );
  END IF;

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;
  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION 'week_ending_cutoff is required';
  END IF;
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;
  IF jsonb_typeof(v_preview_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'preview_payload_json must be a JSON object';
  END IF;
  IF jsonb_typeof(v_selected_preview_row_ids_input) <> 'array' THEN
    RAISE EXCEPTION 'selected_preview_row_ids must be a JSON array';
  END IF;

  PERFORM 1 FROM public.tms_users WHERE public.tms_users.id = p_actor_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT sd.banking_system, sd.external_paye_system, sd.rail_provider_default, sd.rail_env_default,
         (coalesce(sd.rail_supports_name_check, false) = true and upper(btrim(coalesce(sd.rail_provider_default, ''))) <> 'CSV') as need_name_check,
         (upper(btrim(coalesce(sd.rail_provider_default, ''))) <> 'CSV') as requires_payee_map
  INTO v_settings_bank_system, v_settings_external_paye_system, v_settings_rail_provider, v_settings_rail_env, v_need_name_check, v_requires_payee_map
  FROM public.settings_defaults sd
  ORDER BY sd.id ASC
  LIMIT 1;

  IF v_settings_bank_system IS NULL OR v_settings_external_paye_system IS NULL THEN
    RAISE EXCEPTION 'settings_defaults missing banking_system/external_paye_system';
  END IF;
  IF v_settings_rail_provider IS NULL OR v_settings_rail_env IS NULL THEN
    RAISE EXCEPTION 'settings_defaults missing rail_provider_default/rail_env_default';
  END IF;

  SELECT sfw.vat_rate_pct, sfw.erni_pct
  INTO v_vat_rate_pct, v_erni_pct
  FROM public.settings_finance_windows sfw
  WHERE p_pay_date >= sfw.date_from
    AND p_pay_date <= coalesce(sfw.date_to, 'infinity'::date)
  ORDER BY sfw.date_from DESC
  LIMIT 1;

  IF v_vat_rate_pct IS NULL OR v_erni_pct IS NULL THEN
    RAISE EXCEPTION 'No matching finance window found for pay_date %', p_pay_date;
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_settings_context (
    banking_system text,
    external_paye_system text,
    rail_provider_default text,
    rail_env_default text,
    need_name_check boolean,
    requires_payee_map boolean,
    vat_rate_pct numeric,
    erni_pct numeric,
    pay_week_start date
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_settings_context;
  INSERT INTO pg_temp.tmp_pay_build_settings_context(
    banking_system, external_paye_system, rail_provider_default, rail_env_default, need_name_check, requires_payee_map, vat_rate_pct, erni_pct, pay_week_start
  ) VALUES (
    v_settings_bank_system, v_settings_external_paye_system, v_settings_rail_provider, v_settings_rail_env, v_need_name_check, v_requires_payee_map, v_vat_rate_pct, v_erni_pct, v_week_start
  );

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_preview_candidates (
    cand jsonb NOT NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_preview_candidates;
  INSERT INTO pg_temp.tmp_pay_build_preview_candidates(cand)
  SELECT cand_json
  FROM (
    SELECT cand_json
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'paye_candidates', '[]'::jsonb)) AS cand(cand_json)
    UNION ALL
    SELECT cand_json
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'non_paye_payees', '[]'::jsonb)) AS cand(cand_json)
  ) AS src;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_selected_preview_rows (
    preview_row_id text PRIMARY KEY,
    candidate_id uuid NOT NULL,
    finance_case_id uuid NULL,
    timesheet_id uuid NULL,
    client_id uuid NULL,
    line_type text NULL,
    case_type text NULL,
    pay_channel text NULL,
    paye_treatment text NULL,
    routing_kind text NULL,
    destination_label text NULL,
    taxability text NULL,
    beneficiary_name text NULL,
    masked_bank_account text NULL,
    bank_details_hash text NULL,
    item_direction text NULL,
    item_type_label text NULL,
    source_ref text NULL,
    preview_amount_ex_vat numeric(12,2) NULL,
    draftable boolean NOT NULL,
    snooze_allowed boolean NOT NULL,
    is_candidate_directed_oneoff_payout boolean NOT NULL,
    appears_on_umbrella_remittance boolean NOT NULL,
    generates_candidate_payment_advice boolean NOT NULL,
    case_components_json jsonb NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_selected_preview_rows;

  v_selected_preview_rows_supplied := jsonb_array_length(v_selected_preview_row_ids_input) > 0;

  INSERT INTO pg_temp.tmp_pay_build_selected_preview_rows (
    preview_row_id,
    candidate_id,
    finance_case_id,
    timesheet_id,
    client_id,
    line_type,
    case_type,
    pay_channel,
    paye_treatment,
    routing_kind,
    destination_label,
    taxability,
    beneficiary_name,
    masked_bank_account,
    bank_details_hash,
    item_direction,
    item_type_label,
    source_ref,
    preview_amount_ex_vat,
    draftable,
    snooze_allowed,
    is_candidate_directed_oneoff_payout,
    appears_on_umbrella_remittance,
    generates_candidate_payment_advice,
    case_components_json
  )
  WITH item_rows AS (
    SELECT DISTINCT ON (
      coalesce(
        nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
        nullif(btrim(coalesce(line_json->>'line_id','')), '')
      )
    )
      coalesce(
        nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
        nullif(btrim(coalesce(line_json->>'line_id','')), '')
      ) AS preview_row_id,
      nullif(btrim(coalesce(line_json->>'candidate_id','')), '')::uuid AS candidate_id,
      line_json AS item_json,
      nullif(btrim(coalesce(line_json->>'finance_case_id','')), '')::uuid AS finance_case_id,
      nullif(btrim(coalesce(line_json->>'timesheet_id','')), '')::uuid AS timesheet_id,
      nullif(btrim(coalesce(line_json->>'client_id','')), '')::uuid AS client_id
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'canonical_preview_lines', '[]'::jsonb)) AS line(line_json)
    WHERE nullif(btrim(coalesce(line_json->>'candidate_id','')), '') IS NOT NULL
      AND coalesce(
            nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
            nullif(btrim(coalesce(line_json->>'line_id','')), '')
          ) IS NOT NULL
    ORDER BY coalesce(
              nullif(btrim(coalesce(line_json->>'preview_row_id','')), ''),
              nullif(btrim(coalesce(line_json->>'line_id','')), '')
            )
  )
  SELECT
    ir.preview_row_id,
    ir.candidate_id,
    ir.finance_case_id,
    ir.timesheet_id,
    ir.client_id,
    nullif(btrim(coalesce(ir.item_json->>'line_type','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'case_type','')), ''),
    upper(btrim(coalesce(ir.item_json->>'pay_channel',''))),
    upper(btrim(coalesce(ir.item_json->>'paye_treatment',''))),
    nullif(btrim(coalesce(ir.item_json->>'routing_kind','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'destination_label','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'taxability','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'beneficiary_name','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'masked_bank_account','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'bank_details_hash','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'item_direction','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'item_type_label','')), ''),
    nullif(btrim(coalesce(ir.item_json->>'source_ref','')), ''),
    round(coalesce(nullif(ir.item_json->>'amount_ex_vat','')::numeric, nullif(ir.item_json->>'preview_amount_ex_vat','')::numeric, 0), 2)::numeric(12,2),
    coalesce(nullif(ir.item_json->>'draftable','')::boolean, false),
    coalesce(nullif(ir.item_json->>'snooze_allowed','')::boolean, false),
    coalesce(nullif(ir.item_json->>'is_candidate_directed_oneoff_payout','')::boolean, false),
    coalesce(nullif(ir.item_json->>'appears_on_umbrella_remittance','')::boolean, false),
    coalesce(nullif(ir.item_json->>'generates_candidate_payment_advice','')::boolean, false),
    coalesce(ir.item_json->'case_components', ir.item_json->'components', '[]'::jsonb)
  FROM item_rows ir
  WHERE coalesce(nullif(ir.item_json->>'draftable','')::boolean, false) = true
    AND (
      v_selected_preview_rows_supplied = false
      OR ir.preview_row_id IN (
        SELECT btrim(value)
        FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
        WHERE btrim(value) <> ''
      )
    )
  ORDER BY ir.preview_row_id;

  SELECT count(*)::int INTO v_selected_preview_row_count FROM pg_temp.tmp_pay_build_selected_preview_rows;
  IF v_selected_preview_row_count = 0 THEN
    RAISE EXCEPTION 'Selected preview rows are not valid for the current preview';
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) = false THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview refused legacy unchunked draft creation. Normal draft creation must use the Banking Pay operation draft flow; set p_allow_legacy_unchunked only for explicit small diagnostic/test compatibility.';
  END IF;

  IF v_selected_preview_row_count > 250 THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview refused legacy unchunked draft creation for % selected rows. Use the Banking Pay operation draft flow for large interactive drafts.', v_selected_preview_row_count;
  END IF;

  SELECT upper(btrim(coalesce(spr.pay_channel, '')))
  INTO v_scope
  FROM pg_temp.tmp_pay_build_selected_preview_rows spr
  WHERE upper(btrim(coalesce(spr.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
  GROUP BY upper(btrim(coalesce(spr.pay_channel, '')))
  ORDER BY upper(btrim(coalesce(spr.pay_channel, '')))
  LIMIT 1;

  IF v_scope IS NULL THEN
    RAISE EXCEPTION 'Unable to determine pay channel scope from selected preview rows';
  END IF;
  IF (
    SELECT count(*)
    FROM (
      SELECT DISTINCT upper(btrim(coalesce(spr.pay_channel, ''))) AS pay_channel_scope
      FROM pg_temp.tmp_pay_build_selected_preview_rows spr
      WHERE upper(btrim(coalesce(spr.pay_channel, ''))) IN ('PAYE', 'UMBRELLA')
    ) AS pay_channel_scope_rows
  ) <> 1 THEN
    RAISE EXCEPTION 'Selected preview rows must belong to exactly one pay channel scope';
  END IF;

  SELECT COALESCE(jsonb_agg(sc.candidate_id::text ORDER BY sc.candidate_id::text), '[]'::jsonb)
  INTO v_candidate_ids
  FROM (
    SELECT DISTINCT spr.candidate_id
    FROM pg_temp.tmp_pay_build_selected_preview_rows spr
  ) AS sc;


  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_hidden_template_input_rows (
    candidate_id uuid NULL,
    finance_case_id uuid NULL,
    recovery_family text NULL,
    paye_treatment text NULL,
    raw_pay_channel text NULL,
    normalized_pay_channel text NULL,
    umbrella_id uuid NULL,
    source_ref text NULL,
    finance_component_id uuid NULL,
    frozen_component_key_type text NULL,
    frozen_component_key_value text NULL,
    frozen_component_snapshot_json jsonb NULL,
    frozen_component_classification public.pay_finance_component_classification_enum NULL,
    frozen_source_basis_json jsonb NULL,
    frozen_source_pay_method text NULL,
    frozen_target_pay_method text NULL,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum NULL,
    frozen_resolution_payload_json jsonb NULL,
    frozen_resolution_result_json jsonb NULL,
    frozen_source_amount numeric(12,2) NULL,
    frozen_outstanding_amount numeric(12,2) NULL,
    weekly_due numeric(12,2) NULL,
    minimum_earnings_threshold numeric NULL,
    take_home_floor_override numeric NULL,
    default_take_home_floor numeric NULL,
    payout_status text NULL,
    next_due_week_start date NULL,
    sort_order integer NULL,
    required_identifiers_present boolean NOT NULL,
    candidate_selected boolean NOT NULL,
    pay_channel_matches_scope boolean NOT NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_hidden_template_input_rows;

  INSERT INTO pg_temp.tmp_pay_build_hidden_template_input_rows (
    candidate_id,
    finance_case_id,
    recovery_family,
    paye_treatment,
    raw_pay_channel,
    normalized_pay_channel,
    umbrella_id,
    source_ref,
    finance_component_id,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_snapshot_json,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_outstanding_amount,
    weekly_due,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor,
    payout_status,
    next_due_week_start,
    sort_order,
    required_identifiers_present,
    candidate_selected,
    pay_channel_matches_scope
  )
  SELECT
    parsed_rows.candidate_id,
    parsed_rows.finance_case_id,
    parsed_rows.recovery_family,
    parsed_rows.paye_treatment,
    parsed_rows.raw_pay_channel,
    parsed_rows.normalized_pay_channel,
    parsed_rows.umbrella_id,
    parsed_rows.source_ref,
    parsed_rows.finance_component_id,
    parsed_rows.frozen_component_key_type,
    parsed_rows.frozen_component_key_value,
    parsed_rows.frozen_component_snapshot_json,
    parsed_rows.frozen_component_classification,
    parsed_rows.frozen_source_basis_json,
    parsed_rows.frozen_source_pay_method,
    parsed_rows.frozen_target_pay_method,
    parsed_rows.frozen_resolution_mode,
    parsed_rows.frozen_resolution_payload_json,
    parsed_rows.frozen_resolution_result_json,
    parsed_rows.frozen_source_amount,
    parsed_rows.frozen_outstanding_amount,
    parsed_rows.weekly_due,
    parsed_rows.minimum_earnings_threshold,
    parsed_rows.take_home_floor_override,
    parsed_rows.default_take_home_floor,
    parsed_rows.payout_status,
    parsed_rows.next_due_week_start,
    parsed_rows.sort_order,
    (
      parsed_rows.candidate_id IS NOT NULL
      AND parsed_rows.finance_case_id IS NOT NULL
      AND parsed_rows.recovery_family IN ('MANUAL_DEBT_RECOVERY', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY')
    ) AS required_identifiers_present,
    EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_build_selected_preview_rows AS selected_rows
      WHERE selected_rows.candidate_id = parsed_rows.candidate_id
    ) AS candidate_selected,
    CASE
      WHEN parsed_rows.raw_pay_channel IN ('PAYE', 'UMBRELLA') THEN parsed_rows.raw_pay_channel = v_scope
      WHEN COALESCE(BTRIM(parsed_rows.raw_pay_channel), '') = '' AND v_scope = 'PAYE' THEN true
      ELSE false
    END AS pay_channel_matches_scope
  FROM (
    SELECT
      NULLIF(BTRIM(COALESCE(template_element.value->>'candidate_id', '')), '')::uuid AS candidate_id,
      NULLIF(BTRIM(COALESCE(template_element.value->>'finance_case_id', '')), '')::uuid AS finance_case_id,
      UPPER(BTRIM(COALESCE(template_element.value->>'recovery_family', ''))) AS recovery_family,
      UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'paye_treatment', '')), '')) AS paye_treatment,
      UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'pay_channel', '')), '')) AS raw_pay_channel,
      CASE
        WHEN UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'pay_channel', '')), '')) IN ('PAYE', 'UMBRELLA')
          THEN UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'pay_channel', '')), ''))
        WHEN COALESCE(BTRIM(COALESCE(template_element.value->>'pay_channel', '')), '') = ''
             AND v_scope = 'PAYE'
          THEN 'PAYE'
        ELSE NULL::text
      END AS normalized_pay_channel,
      NULLIF(BTRIM(COALESCE(template_element.value->>'umbrella_id', '')), '')::uuid AS umbrella_id,
      NULLIF(BTRIM(COALESCE(template_element.value->>'source_ref', '')), '') AS source_ref,
      NULLIF(BTRIM(COALESCE(template_element.value->>'finance_component_id', '')), '')::uuid AS finance_component_id,
      NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_component_key_type', '')), '') AS frozen_component_key_type,
      NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_component_key_value', '')), '') AS frozen_component_key_value,
      CASE
        WHEN jsonb_typeof(template_element.value->'frozen_component_snapshot_json') = 'object' THEN template_element.value->'frozen_component_snapshot_json'
        ELSE NULL::jsonb
      END AS frozen_component_snapshot_json,
      CASE
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_component_classification', ''))) = 'TAXABLE_CHANNEL_SENSITIVE' THEN 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_component_classification', ''))) = 'REIMBURSEMENT_GROSS_FIXED' THEN 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_component_classification', ''))) = 'NET_PAY_FIXED_RECOVERY' THEN 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
        ELSE NULL::public.pay_finance_component_classification_enum
      END AS frozen_component_classification,
      CASE
        WHEN jsonb_typeof(template_element.value->'frozen_source_basis_json') = 'object' THEN template_element.value->'frozen_source_basis_json'
        ELSE NULL::jsonb
      END AS frozen_source_basis_json,
      UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_source_pay_method', '')), '')) AS frozen_source_pay_method,
      UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_target_pay_method', '')), '')) AS frozen_target_pay_method,
      CASE
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_resolution_mode', ''))) = 'SUGGESTED_EQUIVALENT_BASIS' THEN 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_REPLACEMENT_RATE' THEN 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum
        WHEN UPPER(BTRIM(COALESCE(template_element.value->>'frozen_resolution_mode', ''))) = 'MANUAL_AMOUNT' THEN 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
        ELSE NULL::public.pay_finance_component_resolution_mode_enum
      END AS frozen_resolution_mode,
      CASE
        WHEN jsonb_typeof(template_element.value->'frozen_resolution_payload_json') = 'object' THEN template_element.value->'frozen_resolution_payload_json'
        ELSE NULL::jsonb
      END AS frozen_resolution_payload_json,
      CASE
        WHEN jsonb_typeof(template_element.value->'frozen_resolution_result_json') = 'object' THEN template_element.value->'frozen_resolution_result_json'
        ELSE NULL::jsonb
      END AS frozen_resolution_result_json,
      ROUND(COALESCE(NULLIF(template_element.value->>'frozen_source_amount', '')::numeric, 0), 2)::numeric(12,2) AS frozen_source_amount,
      ROUND(COALESCE(NULLIF(template_element.value->>'frozen_outstanding_amount', '')::numeric, 0), 2)::numeric(12,2) AS frozen_outstanding_amount,
      ROUND(COALESCE(NULLIF(template_element.value->>'weekly_due', '')::numeric, 0), 2)::numeric(12,2) AS weekly_due,
      NULLIF(template_element.value->>'minimum_earnings_threshold', '')::numeric AS minimum_earnings_threshold,
      NULLIF(template_element.value->>'take_home_floor_override', '')::numeric AS take_home_floor_override,
      NULLIF(template_element.value->>'default_take_home_floor', '')::numeric AS default_take_home_floor,
      NULLIF(BTRIM(COALESCE(template_element.value->>'payout_status', '')), '') AS payout_status,
      NULLIF(template_element.value->>'next_due_week_start', '')::date AS next_due_week_start,
      COALESCE(NULLIF(template_element.value->>'sort_order', '')::integer, 0) AS sort_order
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(v_preview_payload_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(v_preview_payload_json->'hidden_recovery_template_lines', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS template_element(value)
    WHERE jsonb_typeof(template_element.value) = 'object'
  ) AS parsed_rows;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_input_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_selected_candidate_input_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.candidate_selected = true;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_filtered_candidate_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.candidate_selected = false;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_filtered_pay_channel_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.candidate_selected = true
    AND hidden_input.required_identifiers_present = true
    AND hidden_input.pay_channel_matches_scope = false;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_filtered_required_identifiers_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.required_identifiers_present = false;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_blank_pay_channel_paye_fallback_count
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.candidate_selected = true
    AND hidden_input.required_identifiers_present = true
    AND COALESCE(BTRIM(hidden_input.raw_pay_channel), '') = ''
    AND hidden_input.normalized_pay_channel = 'PAYE';

  SELECT COALESCE(
           jsonb_object_agg(candidate_counts.candidate_id::text, to_jsonb(candidate_counts.template_count) ORDER BY candidate_counts.candidate_id::text),
           '{}'::jsonb
         )
  INTO v_hidden_template_input_by_candidate
  FROM (
    SELECT hidden_input.candidate_id, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
    WHERE hidden_input.candidate_id IS NOT NULL
    GROUP BY hidden_input.candidate_id
  ) AS candidate_counts;

  SELECT COALESCE(
           jsonb_object_agg(family_counts.recovery_family_key, to_jsonb(family_counts.template_count) ORDER BY family_counts.recovery_family_key),
           '{}'::jsonb
         )
  INTO v_hidden_template_input_by_family
  FROM (
    SELECT COALESCE(NULLIF(hidden_input.recovery_family, ''), 'UNKNOWN') AS recovery_family_key, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
    GROUP BY COALESCE(NULLIF(hidden_input.recovery_family, ''), 'UNKNOWN')
  ) AS family_counts;

  SELECT COALESCE(
           jsonb_object_agg(pay_channel_counts.pay_channel_key, to_jsonb(pay_channel_counts.template_count) ORDER BY pay_channel_counts.pay_channel_key),
           '{}'::jsonb
         )
  INTO v_hidden_template_input_by_pay_channel
  FROM (
    SELECT COALESCE(NULLIF(hidden_input.raw_pay_channel, ''), '(blank)') AS pay_channel_key, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
    GROUP BY COALESCE(NULLIF(hidden_input.raw_pay_channel, ''), '(blank)')
  ) AS pay_channel_counts;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_recovery_template_rows (
    candidate_id uuid NOT NULL,
    finance_case_id uuid NOT NULL,
    recovery_family text NOT NULL,
    paye_treatment text NULL,
    pay_channel text NULL,
    umbrella_id uuid NULL,
    source_ref text NULL,
    finance_component_id uuid NULL,
    frozen_component_key_type text NULL,
    frozen_component_key_value text NULL,
    frozen_component_snapshot_json jsonb NULL,
    frozen_component_classification public.pay_finance_component_classification_enum NULL,
    frozen_source_basis_json jsonb NULL,
    frozen_source_pay_method text NULL,
    frozen_target_pay_method text NULL,
    frozen_resolution_mode public.pay_finance_component_resolution_mode_enum NULL,
    frozen_resolution_payload_json jsonb NULL,
    frozen_resolution_result_json jsonb NULL,
    frozen_source_amount numeric(12,2) NULL,
    frozen_outstanding_amount numeric(12,2) NULL,
    weekly_due numeric(12,2) NULL,
    minimum_earnings_threshold numeric NULL,
    take_home_floor_override numeric NULL,
    default_take_home_floor numeric NULL,
    payout_status text NULL,
    next_due_week_start date NULL,
    sort_order integer NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_recovery_template_rows;

  INSERT INTO pg_temp.tmp_pay_build_recovery_template_rows (
    candidate_id,
    finance_case_id,
    recovery_family,
    paye_treatment,
    pay_channel,
    umbrella_id,
    source_ref,
    finance_component_id,
    frozen_component_key_type,
    frozen_component_key_value,
    frozen_component_snapshot_json,
    frozen_component_classification,
    frozen_source_basis_json,
    frozen_source_pay_method,
    frozen_target_pay_method,
    frozen_resolution_mode,
    frozen_resolution_payload_json,
    frozen_resolution_result_json,
    frozen_source_amount,
    frozen_outstanding_amount,
    weekly_due,
    minimum_earnings_threshold,
    take_home_floor_override,
    default_take_home_floor,
    payout_status,
    next_due_week_start,
    sort_order
  )
  SELECT DISTINCT ON (
    hidden_input.candidate_id,
    hidden_input.finance_case_id,
    hidden_input.recovery_family,
    COALESCE(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(hidden_input.source_ref, ''),
    COALESCE(hidden_input.normalized_pay_channel, '')
  )
    hidden_input.candidate_id,
    hidden_input.finance_case_id,
    hidden_input.recovery_family,
    hidden_input.paye_treatment,
    hidden_input.normalized_pay_channel,
    hidden_input.umbrella_id,
    hidden_input.source_ref,
    hidden_input.finance_component_id,
    hidden_input.frozen_component_key_type,
    hidden_input.frozen_component_key_value,
    hidden_input.frozen_component_snapshot_json,
    hidden_input.frozen_component_classification,
    hidden_input.frozen_source_basis_json,
    hidden_input.frozen_source_pay_method,
    hidden_input.frozen_target_pay_method,
    hidden_input.frozen_resolution_mode,
    hidden_input.frozen_resolution_payload_json,
    hidden_input.frozen_resolution_result_json,
    hidden_input.frozen_source_amount,
    hidden_input.frozen_outstanding_amount,
    hidden_input.weekly_due,
    hidden_input.minimum_earnings_threshold,
    hidden_input.take_home_floor_override,
    hidden_input.default_take_home_floor,
    hidden_input.payout_status,
    hidden_input.next_due_week_start,
    hidden_input.sort_order
  FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
  WHERE hidden_input.candidate_selected = true
    AND hidden_input.required_identifiers_present = true
    AND hidden_input.pay_channel_matches_scope = true
  ORDER BY
    hidden_input.candidate_id,
    hidden_input.finance_case_id,
    hidden_input.recovery_family,
    COALESCE(hidden_input.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(hidden_input.source_ref, ''),
    COALESCE(hidden_input.normalized_pay_channel, ''),
    hidden_input.sort_order;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_staged_count
  FROM pg_temp.tmp_pay_build_recovery_template_rows;

  SELECT COUNT(*)::integer
  INTO v_hidden_template_manual_debt_staged_count
  FROM pg_temp.tmp_pay_build_recovery_template_rows AS staged_tpl
  WHERE staged_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY';

  SELECT COUNT(*)::integer
  INTO v_hidden_template_loan_staged_count
  FROM pg_temp.tmp_pay_build_recovery_template_rows AS staged_tpl
  WHERE staged_tpl.recovery_family = 'LOAN_REPAYMENT';

  SELECT COUNT(*)::integer
  INTO v_hidden_template_overpayment_staged_count
  FROM pg_temp.tmp_pay_build_recovery_template_rows AS staged_tpl
  WHERE staged_tpl.recovery_family = 'OVERPAYMENT_RECOVERY';

  SELECT COALESCE(
           jsonb_object_agg(candidate_counts.candidate_id::text, to_jsonb(candidate_counts.template_count) ORDER BY candidate_counts.candidate_id::text),
           '{}'::jsonb
         )
  INTO v_hidden_template_staged_manual_debt_by_candidate
  FROM (
    SELECT staged_tpl.candidate_id, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_build_recovery_template_rows AS staged_tpl
    WHERE staged_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
      AND staged_tpl.pay_channel = 'PAYE'
    GROUP BY staged_tpl.candidate_id
  ) AS candidate_counts;

  IF v_scope = 'PAYE' THEN
    SELECT COALESCE(array_agg(missing_candidate.candidate_id ORDER BY missing_candidate.candidate_id), ARRAY[]::uuid[])
    INTO v_missing_manual_debt_template_candidate_ids
    FROM (
      SELECT DISTINCT hidden_input.candidate_id
      FROM pg_temp.tmp_pay_build_hidden_template_input_rows AS hidden_input
      WHERE hidden_input.candidate_selected = true
        AND hidden_input.required_identifiers_present = true
        AND hidden_input.recovery_family = 'MANUAL_DEBT_RECOVERY'
        AND hidden_input.pay_channel_matches_scope = true
        AND hidden_input.normalized_pay_channel = 'PAYE'
    ) AS missing_candidate
    LEFT JOIN (
      SELECT DISTINCT staged_tpl.candidate_id
      FROM pg_temp.tmp_pay_build_recovery_template_rows AS staged_tpl
      WHERE staged_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
        AND staged_tpl.pay_channel = 'PAYE'
    ) AS staged_candidate
      ON staged_candidate.candidate_id = missing_candidate.candidate_id
    WHERE staged_candidate.candidate_id IS NULL;

    IF COALESCE(array_length(v_missing_manual_debt_template_candidate_ids, 1), 0) > 0 THEN
      RAISE EXCEPTION 'MANUAL_DEBT_TEMPLATE_NOT_STAGED_FOR_SELECTED_PAYE_CANDIDATE: hidden manual-debt templates were present in the preview payload but were not staged for candidates %',
        array_to_string(v_missing_manual_debt_template_candidate_ids, ',');
    END IF;
  END IF;
  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_candidates_ctx (
    id uuid PRIMARY KEY,
    tms_ref text,
    display_name text,
    pay_method text,
    umbrella_id uuid,
    first_name text,
    last_name text,
    account_holder text,
    sort_code text,
    account_number text,
    bank_details_hash text,
    payee_id text,
    payee_account_id text,
    umbrella_vat_chargeable boolean
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_candidates_ctx;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_umbrellas_ctx (
    id uuid PRIMARY KEY,
    name text,
    vat_chargeable boolean,
    sort_code text,
    account_number text,
    bank_details_hash text,
    payee_id text,
    payee_account_id text
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_umbrellas_ctx;

  INSERT INTO pg_temp.tmp_pay_build_candidates_ctx (
    id,
    tms_ref,
    display_name,
    pay_method,
    umbrella_id,
    first_name,
    last_name,
    account_holder,
    sort_code,
    account_number,
    bank_details_hash,
    payee_id,
    payee_account_id,
    umbrella_vat_chargeable
  )
  WITH preview_candidate_rows AS (
    SELECT
      nullif(btrim(coalesce(pc.cand->>'candidate_id','')), '')::uuid AS preview_candidate_id,
      nullif(btrim(coalesce(pc.cand->>'tms_ref','')), '') AS preview_tms_ref,
      nullif(btrim(coalesce(pc.cand->>'display_name','')), '') AS preview_display_name,
      upper(nullif(btrim(coalesce(pc.cand->>'current_pay_method','')), '')) AS preview_pay_method,
      nullif(btrim(coalesce(pc.cand->>'umbrella_id','')), '')::uuid AS preview_umbrella_id,
      coalesce(nullif(pc.cand->>'umbrella_vat_chargeable','')::boolean, false) AS preview_umbrella_vat_chargeable,
      nullif(btrim(coalesce(pc.cand->>'candidate_bank_hash','')), '') AS preview_candidate_bank_hash,
      nullif(btrim(coalesce(pc.cand->>'umbrella_bank_hash','')), '') AS preview_umbrella_bank_hash
    FROM pg_temp.tmp_pay_build_preview_candidates AS pc
    WHERE nullif(btrim(coalesce(pc.cand->>'candidate_id','')), '') IS NOT NULL
  )
  SELECT
    c.id,
    coalesce(pcr.preview_tms_ref, c.tms_ref),
    coalesce(pcr.preview_display_name, c.display_name),
    coalesce(pcr.preview_pay_method, upper(coalesce(c.pay_method,''))),
    coalesce(pcr.preview_umbrella_id, c.umbrella_id),
    c.first_name,
    c.last_name,
    c.account_holder,
    regexp_replace(coalesce(c.sort_code,''), '[^0-9]', '', 'g'),
    nullif(regexp_replace(coalesce(c.account_number,''), '[^0-9]', '', 'g'), ''),
    coalesce(pcr.preview_candidate_bank_hash, c.bank_details_hash),
    bpm_candidate.payee_id,
    bpm_candidate.payee_account_id,
    coalesce(pcr.preview_umbrella_vat_chargeable, u.vat_chargeable, false)
  FROM (
    SELECT DISTINCT spr.candidate_id
    FROM pg_temp.tmp_pay_build_selected_preview_rows spr
  ) AS sc
  JOIN public.candidates c
    ON c.id = sc.candidate_id
  LEFT JOIN preview_candidate_rows pcr
    ON pcr.preview_candidate_id = c.id
  LEFT JOIN public.umbrellas u
    ON u.id = coalesce(pcr.preview_umbrella_id, c.umbrella_id)
  LEFT JOIN public.bank_payee_map bpm_candidate
    ON upper(coalesce(bpm_candidate.rail_provider,'')) = upper(btrim(coalesce(v_settings_rail_provider,'')))
   AND upper(coalesce(bpm_candidate.rail_env,'')) = upper(btrim(coalesce(v_settings_rail_env,'')))
   AND upper(coalesce(bpm_candidate.entity_kind,'')) = 'CANDIDATE'
   AND bpm_candidate.entity_id = c.id
   AND bpm_candidate.bank_details_hash = coalesce(pcr.preview_candidate_bank_hash, c.bank_details_hash);

  INSERT INTO pg_temp.tmp_pay_build_umbrellas_ctx (
    id,
    name,
    vat_chargeable,
    sort_code,
    account_number,
    bank_details_hash,
    payee_id,
    payee_account_id
  )
  SELECT
    u.id,
    u.name,
    coalesce(u.vat_chargeable, false),
    regexp_replace(coalesce(u.sort_code,''), '[^0-9]', '', 'g'),
    nullif(regexp_replace(coalesce(u.account_number,''), '[^0-9]', '', 'g'), ''),
    u.bank_details_hash,
    bpm_umbrella.payee_id,
    bpm_umbrella.payee_account_id
  FROM public.umbrellas u
  JOIN (
    SELECT DISTINCT cctx.umbrella_id
    FROM pg_temp.tmp_pay_build_candidates_ctx cctx
    WHERE cctx.umbrella_id IS NOT NULL
  ) AS uu
    ON uu.umbrella_id = u.id
  LEFT JOIN public.bank_payee_map bpm_umbrella
    ON upper(coalesce(bpm_umbrella.rail_provider,'')) = upper(btrim(coalesce(v_settings_rail_provider,'')))
   AND upper(coalesce(bpm_umbrella.rail_env,'')) = upper(btrim(coalesce(v_settings_rail_env,'')))
   AND upper(coalesce(bpm_umbrella.entity_kind,'')) = 'UMBRELLA'
   AND bpm_umbrella.entity_id = u.id
   AND bpm_umbrella.bank_details_hash = u.bank_details_hash;


  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
    timesheet_id uuid PRIMARY KEY,
    candidate_id uuid NOT NULL,
    client_id uuid NULL,
    week_ending_date date NULL,
    source_pay_method text NULL,
    candidate_pay_method text NULL,
    baseline_signature text NULL,
    base_snapshot_json jsonb NOT NULL,
    target_snapshot_json jsonb NOT NULL,
    target_signature text NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_timesheet_snapshots_ctx;

  INSERT INTO pg_temp.tmp_pay_build_timesheet_snapshots_ctx (
    timesheet_id,
    candidate_id,
    client_id,
    week_ending_date,
    source_pay_method,
    candidate_pay_method,
    baseline_signature,
    base_snapshot_json,
    target_snapshot_json,
    target_signature
  )
  SELECT DISTINCT ON (ts_row.timesheet_id)
    ts_row.timesheet_id,
    ts_row.candidate_id,
    ts_row.client_id,
    ts_row.week_ending_date,
    ts_row.source_pay_method,
    ts_row.candidate_pay_method,
    ts_row.baseline_signature,
    ts_row.base_snapshot_json,
    ts_row.target_snapshot_json,
    ts_row.target_signature
  FROM (
    SELECT
      nullif(btrim(coalesce(ts_json->>'timesheet_id', '')), '')::uuid AS timesheet_id,
      nullif(btrim(coalesce(ts_json->>'candidate_id', '')), '')::uuid AS candidate_id,
      nullif(btrim(coalesce(ts_json->>'client_id', '')), '')::uuid AS client_id,
      CASE
        WHEN coalesce(ts_json->>'week_ending_date', '') ~ '^\d{4}-\d{2}-\d{2}$'
          THEN (ts_json->>'week_ending_date')::date
        ELSE NULL::date
      END AS week_ending_date,
      nullif(btrim(coalesce(ts_json->>'source_pay_method', '')), '') AS source_pay_method,
      nullif(btrim(coalesce(ts_json->>'candidate_pay_method', '')), '') AS candidate_pay_method,
      nullif(btrim(coalesce(ts_json->>'baseline_signature', '')), '') AS baseline_signature,
      coalesce(ts_json->'base_snapshot_json', '{}'::jsonb) AS base_snapshot_json,
      coalesce(ts_json->'target_snapshot_json', '{}'::jsonb) AS target_snapshot_json,
      nullif(btrim(coalesce(ts_json->>'target_signature', '')), '') AS target_signature
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'timesheet_snapshots_json', '[]'::jsonb)) AS ts(ts_json)
    WHERE jsonb_typeof(ts.ts_json) = 'object'
      AND nullif(btrim(coalesce(ts.ts_json->>'timesheet_id', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(ts.ts_json->>'candidate_id', '')), '') IS NOT NULL
  ) AS ts_row
  WHERE EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_build_selected_preview_rows spr
    WHERE spr.timesheet_id = ts_row.timesheet_id
      AND spr.candidate_id = ts_row.candidate_id
  )
  ORDER BY ts_row.timesheet_id, ts_row.week_ending_date DESC NULLS LAST;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
    finance_case_id uuid PRIMARY KEY,
    beneficiary_name text,
    sort_code text,
    account_number text,
    bank_details_hash text,
    created_by_user_id uuid,
    updated_by_user_id uuid,
    note text
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx;

  INSERT INTO pg_temp.tmp_pay_build_oneoff_payout_bank_details_ctx (
    finance_case_id,
    beneficiary_name,
    sort_code,
    account_number,
    bank_details_hash,
    created_by_user_id,
    updated_by_user_id,
    note
  )
  SELECT
    obd.finance_case_id,
    obd.beneficiary_name,
    regexp_replace(coalesce(obd.sort_code, ''), '[^0-9]', '', 'g'),
    nullif(regexp_replace(coalesce(obd.account_number, ''), '[^0-9]', '', 'g'), ''),
    obd.bank_details_hash,
    obd.created_by_user_id,
    obd.updated_by_user_id,
    obd.note
  FROM public.pay_finance_case_oneoff_payout_bank_details obd
  WHERE obd.finance_case_id IN (
    SELECT DISTINCT spr.finance_case_id
    FROM pg_temp.tmp_pay_build_selected_preview_rows spr
    WHERE spr.finance_case_id IS NOT NULL
  );

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_pay_build_finance_case_components_ctx (
    id uuid PRIMARY KEY,
    finance_case_id uuid NOT NULL,
    candidate_id uuid NULL,
    linked_timesheet_id uuid NULL,
    component_key_type text NULL,
    component_key_value text NULL,
    classification public.pay_finance_component_classification_enum NULL,
    source_pay_method text NULL,
    source_basis_json jsonb NULL,
    saved_target_pay_method text NULL,
    saved_resolution_mode public.pay_finance_component_resolution_mode_enum NULL,
    saved_resolution_payload_json jsonb NULL,
    saved_resolution_result_json jsonb NULL,
    source_amount numeric(12,2) NULL,
    remaining_source_amount numeric(12,2) NULL,
    allocation_priority_group integer NULL,
    allocation_priority_order integer NULL,
    created_at_utc timestamptz NULL
  ) ON COMMIT DROP;
  TRUNCATE TABLE pg_temp.tmp_pay_build_finance_case_components_ctx;

  INSERT INTO pg_temp.tmp_pay_build_finance_case_components_ctx (
    id,
    finance_case_id,
    candidate_id,
    linked_timesheet_id,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    source_amount,
    remaining_source_amount,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc
  )
  SELECT
    pfc.id,
    pfc.finance_case_id,
    pfc.candidate_id,
    pfc.linked_timesheet_id,
    pfc.component_key_type,
    pfc.component_key_value,
    pfc.classification,
    pfc.source_pay_method,
    pfc.source_basis_json,
    pfc.saved_target_pay_method,
    pfc.saved_resolution_mode,
    pfc.saved_resolution_payload_json,
    pfc.saved_resolution_result_json,
    round(coalesce(pfc.source_amount, 0), 2),
    round(coalesce(pfc.remaining_source_amount, 0), 2),
    pfc.allocation_priority_group,
    pfc.allocation_priority_order,
    pfc.created_at_utc
  FROM public.pay_finance_case_components pfc
  WHERE pfc.finance_case_id IN (
    SELECT DISTINCT spr.finance_case_id
    FROM pg_temp.tmp_pay_build_selected_preview_rows spr
    WHERE spr.finance_case_id IS NOT NULL
  )
    AND pfc.closed_at_utc IS NULL
    AND coalesce(pfc.remaining_source_amount, 0) > 0;

  INSERT INTO public.pay_batches(
    pay_date,
    created_at_utc,
    created_by_user_id,
    status,
    banking_system_snapshot,
    external_paye_system_snapshot,
    rail_provider_snapshot,
    rail_env_snapshot,
    source_workbench_session_id,
    source_snapshot_run_id,
    source_session_version,
    execution_commit_state
  )
  VALUES (
    p_pay_date,
    v_now_utc,
    p_actor_user_id,
    'DRAFT',
    v_settings_bank_system,
    v_settings_external_paye_system,
    v_settings_rail_provider,
    v_settings_rail_env,
    p_source_workbench_session_id,
    p_source_snapshot_run_id,
    p_source_session_version,
    'NOT_SUBMITTED'
  )
  RETURNING public.pay_batches.id
  INTO v_pay_batch_id;

  PERFORM public._audit_insert(
    'pay_batches',
    v_pay_batch_id::text,
    'PAY_BUILD_BATCH_ARTIFACTS_FROM_PREVIEW_CREATED',
    NULL,
    jsonb_build_object(
      'pay_batch_id', v_pay_batch_id::text,
      'pay_date', p_pay_date::text,
      'week_ending_cutoff', p_week_ending_cutoff::text,
      'source_workbench_session_id', CASE WHEN p_source_workbench_session_id IS NULL THEN NULL ELSE p_source_workbench_session_id::text END,
      'source_snapshot_run_id', CASE WHEN p_source_snapshot_run_id IS NULL THEN NULL ELSE p_source_snapshot_run_id::text END,
      'source_session_version', p_source_session_version,
      'execution_commit_state', 'NOT_SUBMITTED',
      'selected_preview_row_count', v_selected_preview_row_count,
      'pay_channel_scope', v_scope
    ),
    'PAY_BUILD_BATCH_ARTIFACTS_FROM_PREVIEW',
    p_actor_user_id
  );

  v_insert_candidates_json := public.pay_batch_insert_candidates_from_preview(v_pay_batch_id, p_actor_user_id);
  v_insert_items_json := public.pay_batch_insert_items_from_preview(v_pay_batch_id, p_actor_user_id);
  v_finance_json := public.pay_batch_apply_finance_adjustments(v_pay_batch_id, v_scope, p_actor_user_id, v_vat_rate_pct, v_week_start);
  v_finalize_json := public.pay_batch_finalize_reservations_and_markers(v_pay_batch_id, v_scope, p_actor_user_id, p_pay_date, v_week_start);
  v_summary_json := public.pay_batch_populate_candidate_summaries(v_pay_batch_id, v_scope, p_actor_user_id);
  v_snapshots_json := public.pay_batch_create_timesheet_snapshots(v_pay_batch_id, p_actor_user_id);
  v_breakdowns_json := public.pay_batch_build_item_breakdowns(v_pay_batch_id, p_actor_user_id);
  v_integrity_json := public.pay_batch_assert_integrity(v_pay_batch_id, p_actor_user_id);

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_pay_batch_id::text,
    'pay_date', p_pay_date::text,
    'pay_week_start', v_week_start::text,
    'week_ending_cutoff_date', p_week_ending_cutoff::text,
    'pay_channel_scope', v_scope,
    'banking_system_snapshot', v_settings_bank_system,
    'external_paye_system_snapshot', v_settings_external_paye_system,
    'rail_provider_snapshot', v_settings_rail_provider,
    'rail_env_snapshot', v_settings_rail_env,
    'source_workbench_session_id', CASE WHEN p_source_workbench_session_id IS NULL THEN NULL ELSE p_source_workbench_session_id::text END,
    'source_snapshot_run_id', CASE WHEN p_source_snapshot_run_id IS NULL THEN NULL ELSE p_source_snapshot_run_id::text END,
    'source_session_version', p_source_session_version,
    'selected_preview_row_count', v_selected_preview_row_count,
    'candidate_ids', v_candidate_ids,
    'stages', jsonb_build_object(
      'insert_candidates', v_insert_candidates_json,
      'insert_items', v_insert_items_json,
      'hidden_recovery_templates', jsonb_build_object(
        'input_count', v_hidden_template_input_count,
        'selected_candidate_input_count', v_hidden_template_selected_candidate_input_count,
        'input_by_candidate', v_hidden_template_input_by_candidate,
        'input_by_family', v_hidden_template_input_by_family,
        'input_by_pay_channel', v_hidden_template_input_by_pay_channel,
        'staged_count', v_hidden_template_staged_count,
        'staged_manual_debt_count', v_hidden_template_manual_debt_staged_count,
        'staged_loan_count', v_hidden_template_loan_staged_count,
        'staged_overpayment_count', v_hidden_template_overpayment_staged_count,
        'staged_manual_debt_by_candidate', v_hidden_template_staged_manual_debt_by_candidate,
        'filtered_candidate_not_selected_count', v_hidden_template_filtered_candidate_count,
        'filtered_pay_channel_mismatch_count', v_hidden_template_filtered_pay_channel_count,
        'filtered_missing_required_identifiers_count', v_hidden_template_filtered_required_identifiers_count,
        'blank_pay_channel_paye_fallback_count', v_hidden_template_blank_pay_channel_paye_fallback_count
      ),
      'finance_adjustments', v_finance_json,
      'finalize', v_finalize_json,
      'candidate_summaries', v_summary_json,
      'timesheet_snapshots', v_snapshots_json,
      'item_breakdowns', v_breakdowns_json,
      'assert_integrity', v_integrity_json
    )
  );
END;
$function$;





DROP FUNCTION IF EXISTS public.pay_create_draft_batch(date, date, text, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum);
DROP FUNCTION IF EXISTS public.pay_create_draft_batch(date, date, text, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum, uuid, boolean);




CREATE OR REPLACE FUNCTION public.pay_create_draft_batch(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_pay_channel_scope text,
  p_actor_user_id uuid,
  p_preview_decisions_json jsonb,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[],
  p_override_reason text DEFAULT NULL::text,
  p_override_mode public.pay_override_mode_enum DEFAULT 'NONE',
  p_operation_id uuid DEFAULT NULL::uuid,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := upper(btrim(coalesce(p_pay_channel_scope, '')));
  v_week_start date := public._pay_week_start_monday(p_pay_date);
  v_preview_decisions_json jsonb := CASE
    WHEN jsonb_typeof(coalesce(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN coalesce(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_preview_payload_json jsonb := '{}'::jsonb;
  v_selected_preview_row_ids_input jsonb := '[]'::jsonb;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_preview_rows_supplied boolean := false;
  v_requested_selected_preview_row_count integer := 0;
  v_selected_preview_row_count integer := 0;
  v_build_result jsonb := '{}'::jsonb;
  v_pay_batch_id uuid := NULL::uuid;
  v_consumed_timesheet_payment_override_count integer := 0;
  v_consumed_timesheet_payment_overrides jsonb := '[]'::jsonb;
  v_legacy_safe_selected_row_threshold integer := 250;
  v_operation_row public.banking_pay_operations%ROWTYPE;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION 'week_ending_cutoff is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be PAYE or UMBRELLA';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_create_draft_batch operation % was not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type <> 'DRAFT_CREATE' THEN
      RAISE EXCEPTION 'pay_create_draft_batch expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation_row.operation_type;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_create_draft_batch operation % belongs to a different actor', p_operation_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'requires_operation_runner', true,
      'operation_id', v_operation_row.id::text,
      'operation_type', v_operation_row.operation_type,
      'status', v_operation_row.status,
      'phase', v_operation_row.phase,
      'pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
      'workbench_session_id', CASE WHEN v_operation_row.workbench_session_id IS NULL THEN NULL ELSE v_operation_row.workbench_session_id::text END,
      'total_units', v_operation_row.total_units,
      'completed_units', v_operation_row.completed_units,
      'failed_units', v_operation_row.failed_units,
      'current_chunk_index', v_operation_row.current_chunk_index,
      'chunk_count', v_operation_row.chunk_count,
      'progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
      'result_json', CASE WHEN v_operation_row.status IN ('COMPLETE', 'REVIEW_REQUIRED') THEN v_operation_row.result_json ELSE NULL END,
      'error_json', CASE WHEN v_operation_row.status IN ('FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN v_operation_row.error_json ELSE NULL END,
      'message', 'Draft creation is running through the scalable Banking Pay operation flow.'
    );
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_OPERATION_REQUIRED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'pay_create_draft_batch refused legacy all-at-once draft creation. Normal draft creation must use the scalable Banking Pay DRAFT_CREATE operation flow; set p_allow_legacy_unchunked only for explicit small diagnostic/test compatibility.',
      'pay_channel_scope', v_scope,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF (p_force_include_timesheet_ids IS NOT NULL AND coalesce(array_length(p_force_include_timesheet_ids, 1), 0) > 0)
     OR p_override_reason IS NOT NULL
     OR p_override_mode IS DISTINCT FROM 'NONE'::public.pay_override_mode_enum THEN
    BEGIN
      PERFORM public._imp_debug_audit(
        p_actor_user_id,
        'PAY_CREATE_DRAFT_BATCH:LEGACY_OVERRIDE_PARAMS_IGNORED',
        jsonb_build_object(
          'pay_date', p_pay_date::text,
          'week_ending_cutoff', p_week_ending_cutoff::text,
          'pay_channel_scope', v_scope,
          'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
          'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
          'force_include_timesheet_ids_count', coalesce(array_length(p_force_include_timesheet_ids, 1), 0),
          'override_reason', p_override_reason,
          'override_mode', p_override_mode::text
        ),
        'pay_batches',
        'legacy-pay-create-draft-batch',
        NULL, NULL, NULL, NULL, NULL
      );
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;
  END IF;

  v_selected_preview_row_ids_input := CASE
    WHEN jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'array' THEN coalesce(v_preview_decisions_json->'selected_preview_row_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_selected_preview_rows_supplied := jsonb_array_length(v_selected_preview_row_ids_input) > 0;

  SELECT count(*)::integer
  INTO v_requested_selected_preview_row_count
  FROM (
    SELECT DISTINCT btrim(sel.value) AS selected_preview_row_id
    FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
    WHERE btrim(sel.value) <> ''
  ) AS requested_rows;

  IF v_selected_preview_rows_supplied = true
     AND COALESCE(v_requested_selected_preview_row_count, 0) > v_legacy_safe_selected_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_LEGACY_SELECTED_SCOPE_TOO_LARGE',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'This draft selection is too large for the legacy all-at-once path. Even explicit legacy/test compatibility is limited to small selections; use the scalable Banking Pay draft operation flow.',
      'selected_preview_row_count', v_requested_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'pay_channel_scope', v_scope,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF v_selected_preview_rows_supplied = false
     AND p_candidate_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_UNBOUNDED_LEGACY_DISABLED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'Unbounded or client-wide legacy draft creation is disabled. Even explicit legacy/test compatibility must supply a small candidate/test scope or selected preview rows.',
      'pay_channel_scope', v_scope,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  v_preview_payload_json := public.pay_preview(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_preview_decisions_json => v_preview_decisions_json
  );

  IF jsonb_typeof(v_preview_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_preview(...) must return a JSON object';
  END IF;

  v_selected_preview_row_ids_input := CASE
    WHEN jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'array' THEN coalesce(v_preview_decisions_json->'selected_preview_row_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  v_selected_preview_rows_supplied := jsonb_array_length(v_selected_preview_row_ids_input) > 0;

  SELECT count(*)::integer
  INTO v_requested_selected_preview_row_count
  FROM (
    SELECT DISTINCT btrim(sel.value) AS selected_preview_row_id
    FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
    WHERE btrim(sel.value) <> ''
  ) AS requested_rows;

  WITH preview_lines AS (
    SELECT
      line.value AS line_json
    FROM jsonb_array_elements(coalesce(v_preview_payload_json->'canonical_preview_lines', '[]'::jsonb)) AS line(value)
    WHERE jsonb_typeof(line.value) = 'object'
  ),
  preview_line_ids AS (
    SELECT
      coalesce(
        nullif(btrim(coalesce(preview_lines.line_json->>'preview_row_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'line_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'row_id', '')), ''),
        nullif(btrim(coalesce(preview_lines.line_json->>'id', '')), '')
      ) AS preview_row_id,
      upper(btrim(coalesce(preview_lines.line_json->>'pay_channel', ''))) AS pay_channel_scope,
      coalesce(nullif(preview_lines.line_json->>'draftable', '')::boolean, false) AS is_draftable
    FROM preview_lines
  ),
  selected_lines AS (
    SELECT DISTINCT
      preview_line_ids.preview_row_id
    FROM preview_line_ids
    WHERE preview_line_ids.preview_row_id IS NOT NULL
      AND preview_line_ids.pay_channel_scope = v_scope
      AND preview_line_ids.is_draftable = true
      AND (
        v_selected_preview_rows_supplied = false
        OR preview_line_ids.preview_row_id IN (
          SELECT btrim(sel.value)
          FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) AS sel(value)
          WHERE btrim(sel.value) <> ''
        )
      )
  )
  SELECT
    coalesce(jsonb_agg(to_jsonb(selected_lines.preview_row_id) ORDER BY selected_lines.preview_row_id), '[]'::jsonb),
    count(*)::integer
  INTO v_selected_preview_row_ids, v_selected_preview_row_count
  FROM selected_lines;

  IF v_selected_preview_row_count = 0 THEN
    RAISE EXCEPTION 'No draftable preview rows found for requested pay channel scope %', v_scope;
  END IF;

  IF v_selected_preview_rows_supplied AND v_selected_preview_row_count <> v_requested_selected_preview_row_count THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve fully within requested pay channel scope %', v_scope;
  END IF;

  IF v_selected_preview_row_count > v_legacy_safe_selected_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCH_LEGACY_UNCHUNKED_TOO_LARGE',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'This draft contains too many payment rows for the legacy all-at-once path. Even explicit legacy/test compatibility is limited to small selections; use the scalable Banking Pay draft operation flow.',
      'selected_preview_row_count', v_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'pay_channel_scope', v_scope,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  v_build_result := public.pay_build_batch_artifacts_from_preview(
    p_pay_date => p_pay_date,
    p_week_ending_cutoff => p_week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_preview_payload_json => v_preview_payload_json,
    p_selected_preview_row_ids => v_selected_preview_row_ids,
    p_source_workbench_session_id => NULL::uuid,
    p_source_snapshot_run_id => NULL::uuid,
    p_source_session_version => NULL::bigint,
    p_operation_id => NULL::uuid,
    p_candidate_scope_ids => NULL::jsonb,
    p_existing_pay_batch_id => NULL::uuid,
    p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
  );

  IF jsonb_typeof(v_build_result) <> 'object' THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview(...) must return a JSON object';
  END IF;

  IF coalesce(nullif(btrim(coalesce(v_build_result->>'pay_batch_id', '')), ''), '') = '' THEN
    RAISE EXCEPTION 'pay_build_batch_artifacts_from_preview(...) did not return pay_batch_id';
  END IF;

  v_pay_batch_id := (v_build_result->>'pay_batch_id')::uuid;

  SELECT
    count(*)::integer,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'override_id', tpo.id::text,
          'timesheet_id', tpo.timesheet_id::text,
          'candidate_id', CASE WHEN tpo.candidate_id IS NULL THEN NULL ELSE tpo.candidate_id::text END,
          'override_type', tpo.override_type,
          'reason', tpo.reason,
          'created_at_utc', tpo.created_at_utc,
          'created_by_user_id', CASE WHEN tpo.created_by_user_id IS NULL THEN NULL ELSE tpo.created_by_user_id::text END,
          'consumed_by_pay_batch_id', CASE WHEN tpo.consumed_by_pay_batch_id IS NULL THEN NULL ELSE tpo.consumed_by_pay_batch_id::text END,
          'consumed_at_utc', tpo.consumed_at_utc
        )
        ORDER BY tpo.timesheet_id::text, tpo.id::text
      ),
      '[]'::jsonb
    )
  INTO
    v_consumed_timesheet_payment_override_count,
    v_consumed_timesheet_payment_overrides
  FROM public.timesheet_payment_overrides tpo
  WHERE tpo.consumed_by_pay_batch_id = v_pay_batch_id
    AND upper(coalesce(tpo.override_type, '')) = 'ADVANCE_THIS_PAYMENT';

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_CREATE_DRAFT_BATCH:LEGACY_ORCHESTRATOR_RETURN',
      jsonb_build_object(
        'pay_batch_id', v_pay_batch_id::text,
        'pay_date', p_pay_date::text,
        'pay_week_start', v_week_start::text,
        'week_ending_cutoff_date', p_week_ending_cutoff::text,
        'pay_channel_scope', v_scope,
        'selected_preview_row_count', v_selected_preview_row_count,
        'consumed_timesheet_payment_override_count', v_consumed_timesheet_payment_override_count,
        'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
      ),
      'pay_batches',
      v_pay_batch_id::text,
      NULL, NULL, NULL, NULL, NULL
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_pay_batch_id::text,
    'pay_date', coalesce(v_build_result->>'pay_date', p_pay_date::text),
    'pay_week_start', coalesce(v_build_result->>'pay_week_start', v_week_start::text),
    'week_ending_cutoff_date', coalesce(v_build_result->>'week_ending_cutoff_date', p_week_ending_cutoff::text),
    'pay_channel_scope', coalesce(v_build_result->>'pay_channel_scope', v_scope),
    'banking_system_snapshot', v_build_result->>'banking_system_snapshot',
    'external_paye_system_snapshot', v_build_result->>'external_paye_system_snapshot',
    'rail_provider_snapshot', v_build_result->>'rail_provider_snapshot',
    'rail_env_snapshot', v_build_result->>'rail_env_snapshot',
    'consumed_timesheet_payment_override_count', coalesce(v_consumed_timesheet_payment_override_count, 0),
    'consumed_timesheet_payment_overrides', v_consumed_timesheet_payment_overrides
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_workbench_session_apply_case_resolution(
  p_session_id uuid,
  p_actor_user_id uuid,
  p_resolution_payload_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_resolution_payload_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_resolution_payload_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_resolution_payload_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_top_source_basis_json jsonb := '{}'::jsonb;
  v_bucket_resolutions_json jsonb := '[]'::jsonb;
  v_candidate_id uuid := NULL::uuid;
  v_candidate_id_text text := '';
  v_case_key text := '';
  v_resolution_family text := '';
  v_default_resolution_mode text := '';
  v_linked_timesheet_id uuid := NULL::uuid;
  v_linked_timesheet_id_text text := '';
  v_finance_case_id_text text := '';
  v_resolve_all_linked_timesheets boolean := false;
  v_resolved_candidate_id uuid := NULL::uuid;
  v_matching_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_matching_candidate_count integer := 0;
  v_target_match_count integer := 0;
  v_bucket_count integer := 0;
  v_existing_deleted_count integer := 0;
  v_new_session_version bigint := 0;
  v_job_json jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_case_resolution_ids jsonb := '[]'::jsonb;
  v_resolution_identity_keys jsonb := '[]'::jsonb;
  v_case_resolution_id_text text := null;
  v_action text := 'SESSION_CASE_RESOLUTION_APPLIED';
  v_target_amount_ex_vat numeric := NULL::numeric;
  v_nonbucket_resolution_mode text := '';
  v_nonbucket_resolution_identity_key text := '';
  v_nonbucket_existing_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_nonbucket_upserted_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_existing_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_upserted_row public.banking_pay_workbench_session_case_resolutions%ROWTYPE;
  v_bucket_row record;
  v_bucket_element record;
  v_bucket_source_basis_json jsonb := '{}'::jsonb;
  v_bucket_source_basis_fingerprint text := '';
  v_bucket_source_family_key text := '';
  v_bucket_bucket_code text := '';
  v_bucket_component_key_type text := '';
  v_bucket_component_key_value text := '';
  v_bucket_resolution_mode text := '';
  v_bucket_timesheet_id uuid := NULL::uuid;
  v_bucket_timesheet_id_text text := '';
  v_bucket_source_units numeric := NULL::numeric;
  v_bucket_source_rate numeric := NULL::numeric;
  v_bucket_source_charge_rate numeric := NULL::numeric;
  v_bucket_target_rate numeric := NULL::numeric;
  v_bucket_resolution_identity_key text := '';
  v_normalized_payload_json jsonb := '{}'::jsonb;
  v_taxable_finance_case_id uuid := NULL::uuid;
  v_taxable_case_candidate_id uuid := NULL::uuid;
  v_taxable_resolution_path text := '';
  v_taxable_schedule_input_mode text := NULL::text;
  v_taxable_weeks_total integer := NULL::integer;
  v_taxable_weekly_due numeric := NULL::numeric;
  v_taxable_manual_total_remaining numeric := NULL::numeric;
  v_taxable_effective_pay_date date := NULL::date;
  v_taxable_note text := NULL::text;
  v_taxable_result_json jsonb := '{}'::jsonb;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users
    WHERE public.tms_users.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
    END IF;
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  v_candidate_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'candidate_id',
    v_resolution_payload_json #>> '{case,candidate_id}',
    ''
  ));
  IF v_candidate_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_candidate_id := v_candidate_id_text::uuid;
  END IF;

  v_case_key := BTRIM(COALESCE(
    v_resolution_payload_json->>'case_key',
    v_resolution_payload_json #>> '{case,case_key}',
    ''
  ));
  IF v_case_key = '' THEN
    RAISE EXCEPTION 'case_key is required';
  END IF;

  v_resolution_family := UPPER(BTRIM(COALESCE(v_resolution_payload_json->>'resolution_family', v_resolution_payload_json->>'resolution_kind', '')));
  v_default_resolution_mode := UPPER(BTRIM(COALESCE(
    v_resolution_payload_json->>'resolution_mode',
    v_resolution_payload_json->>'mode',
    ''
  )));

  v_linked_timesheet_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'linked_timesheet_id',
    v_resolution_payload_json->>'timesheet_id',
    ''
  ));
  IF v_linked_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_linked_timesheet_id := v_linked_timesheet_id_text::uuid;
  END IF;

  v_finance_case_id_text := BTRIM(COALESCE(
    v_resolution_payload_json->>'finance_case_id',
    v_resolution_payload_json #>> '{case,finance_case_id}',
    ''
  ));

  v_resolve_all_linked_timesheets := CASE
    WHEN LOWER(BTRIM(COALESCE(v_resolution_payload_json->>'resolve_all_linked_timesheets', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN true
    ELSE false
  END;

  v_top_source_basis_json := CASE
    WHEN jsonb_typeof(v_resolution_payload_json->'source_basis_json') = 'object' THEN COALESCE(v_resolution_payload_json->'source_basis_json', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_bucket_resolutions_json := CASE
    WHEN jsonb_typeof(v_resolution_payload_json->'bucket_resolutions') = 'array' THEN COALESCE(v_resolution_payload_json->'bucket_resolutions', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  IF v_resolution_family = '' THEN
    IF jsonb_array_length(v_bucket_resolutions_json) > 0 THEN
      v_resolution_family := 'BUCKETED';
    ELSE
      v_resolution_family := 'NON_BUCKET';
    END IF;
  END IF;

  IF v_resolution_family NOT IN ('BUCKETED', 'NON_BUCKET', 'TAXABLE_CHANNEL_RESTRUCTURE') THEN
    RAISE EXCEPTION 'resolution_family must be BUCKETED, NON_BUCKET or TAXABLE_CHANNEL_RESTRUCTURE';
  END IF;

  IF v_candidate_id IS NOT NULL
     AND NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[v_candidate_id]::uuid[]) THEN
    RAISE EXCEPTION 'candidate % is not in workbench session scope %', v_candidate_id, p_session_id;
  END IF;

  create temp table if not exists _tmp_bpay_session_case_resolution_existing
  as
  select *
  from public.banking_pay_workbench_session_case_resolutions
  with no data;

  truncate table _tmp_bpay_session_case_resolution_existing;

  IF v_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' THEN
    IF v_finance_case_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'finance_case_id is required for TAXABLE_CHANNEL_RESTRUCTURE resolution';
    END IF;

    v_taxable_finance_case_id := v_finance_case_id_text::uuid;

    SELECT pa.candidate_id
    INTO v_taxable_case_candidate_id
    FROM public.pay_advances AS pa
    WHERE pa.id = v_taxable_finance_case_id
      AND pa.case_type IN (
        'OVERPAYMENT'::public.pay_finance_case_type_enum,
        'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
        'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      )
      AND pa.status = 'ACTIVE'::public.pay_advance_status_enum
    LIMIT 1;

    IF v_taxable_case_candidate_id IS NULL THEN
      RAISE EXCEPTION 'No active taxable-channel finance case found for finance_case_id %', v_taxable_finance_case_id;
    END IF;

    IF v_candidate_id IS NOT NULL AND v_candidate_id <> v_taxable_case_candidate_id THEN
      RAISE EXCEPTION 'candidate_id % does not match taxable-channel finance case candidate %', v_candidate_id, v_taxable_case_candidate_id;
    END IF;

    IF NOT (COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[v_taxable_case_candidate_id]::uuid[]) THEN
      RAISE EXCEPTION 'finance case candidate % is not in workbench session scope %', v_taxable_case_candidate_id, p_session_id;
    END IF;

    v_resolved_candidate_id := v_taxable_case_candidate_id;

    SELECT COUNT(*)::integer
    INTO v_target_match_count
    FROM public.banking_pay_snapshot_case_state AS snapshot_case
    WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
      AND snapshot_case.candidate_id = v_resolved_candidate_id
      AND snapshot_case.case_key = v_case_key;

    IF v_target_match_count = 0 THEN
      RAISE EXCEPTION 'No matching snapshot baseline case found for TAXABLE_CHANNEL_RESTRUCTURE candidate % in session %', v_resolved_candidate_id, p_session_id;
    ELSIF v_target_match_count > 1 THEN
      RAISE EXCEPTION 'Ambiguous snapshot baseline case found for TAXABLE_CHANNEL_RESTRUCTURE candidate % in session %', v_resolved_candidate_id, p_session_id;
    END IF;

    v_taxable_resolution_path := UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'resolution_path',
      v_resolution_payload_json->>'path',
      'SUGGESTED'
    )));
    IF v_taxable_resolution_path = '' THEN
      v_taxable_resolution_path := 'SUGGESTED';
    END IF;

    IF v_taxable_resolution_path NOT IN ('SUGGESTED', 'MANUAL') THEN
      RAISE EXCEPTION 'resolution_path must be SUGGESTED or MANUAL for TAXABLE_CHANNEL_RESTRUCTURE';
    END IF;

    v_taxable_schedule_input_mode := NULLIF(UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'schedule_input_mode',
      v_resolution_payload_json->>'schedule_mode',
      ''
    ))), '');
    IF v_taxable_schedule_input_mode IS NOT NULL
       AND v_taxable_schedule_input_mode NOT IN ('BY_WEEKS', 'BY_WEEKLY_DUE') THEN
      RAISE EXCEPTION 'schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE for TAXABLE_CHANNEL_RESTRUCTURE';
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'weeks_total', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'weeks_total', '')) !~ '^\d+$' THEN
        RAISE EXCEPTION 'weeks_total must be a positive integer for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_weeks_total := (v_resolution_payload_json->>'weeks_total')::integer;
      IF v_taxable_weeks_total < 1 THEN
        RAISE EXCEPTION 'weeks_total must be >= 1 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'weekly_due', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'weekly_due', '')) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'weekly_due must be numeric for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_weekly_due := round((v_resolution_payload_json->>'weekly_due')::numeric, 2);
      IF v_taxable_weekly_due <= 0 THEN
        RAISE EXCEPTION 'weekly_due must be > 0 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF COALESCE(
      NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), ''),
      NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')
    ) IS NOT NULL THEN
      IF COALESCE(
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), ''),
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'manual_total_remaining must be numeric for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_manual_total_remaining := round(COALESCE(
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'manual_total_remaining', '')), '')::numeric,
        NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'target_remaining_balance_ex_vat', '')), '')::numeric
      ), 2);
      IF v_taxable_manual_total_remaining <= 0 THEN
        RAISE EXCEPTION 'manual_total_remaining must be > 0 for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_resolution_payload_json->>'effective_pay_date', '')), '') IS NOT NULL THEN
      IF BTRIM(COALESCE(v_resolution_payload_json->>'effective_pay_date', '')) !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RAISE EXCEPTION 'effective_pay_date must be YYYY-MM-DD for TAXABLE_CHANNEL_RESTRUCTURE';
      END IF;
      v_taxable_effective_pay_date := (v_resolution_payload_json->>'effective_pay_date')::date;
    END IF;

    v_taxable_note := NULLIF(BTRIM(COALESCE(
      v_resolution_payload_json->>'note',
      v_resolution_payload_json->>'reason',
      ''
    )), '');

    v_taxable_result_json := public.pay_finance_case_apply_taxable_channel_restructure(
      p_finance_case_id => v_taxable_finance_case_id,
      p_actor_user_id => p_actor_user_id,
      p_resolution_path => v_taxable_resolution_path,
      p_schedule_input_mode => v_taxable_schedule_input_mode,
      p_weeks_total => v_taxable_weeks_total,
      p_weekly_due => v_taxable_weekly_due,
      p_manual_total_remaining => v_taxable_manual_total_remaining,
      p_effective_pay_date => v_taxable_effective_pay_date,
      p_note => v_taxable_note
    );

    v_resolution_identity_keys := jsonb_build_array(
      concat_ws('|', 'TAXABLE_CHANNEL_RESTRUCTURE', v_case_key, v_taxable_finance_case_id::text)
    );
    v_case_resolution_ids := '[]'::jsonb;
    v_case_resolution_id_text := NULL;
    v_action := 'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED';

  ELSIF v_resolution_family = 'BUCKETED' THEN
    IF jsonb_typeof(v_bucket_resolutions_json) <> 'array' OR jsonb_array_length(v_bucket_resolutions_json) = 0 THEN
      RAISE EXCEPTION 'bucket_resolutions must be a non-empty JSON array for BUCKETED resolution';
    END IF;

    create temp table if not exists _tmp_bpay_session_bucket_resolution (
      bucket_ordinal integer not null,
      timesheet_id uuid null,
      source_basis_json jsonb not null,
      source_basis_fingerprint text not null,
      source_family_key text not null,
      bucket_code text null,
      component_key_type text not null,
      component_key_value text not null,
      source_units numeric not null,
      source_rate numeric not null,
      source_charge_rate numeric not null,
      resolution_mode text not null,
      target_rate numeric not null,
      resolution_identity_key text not null,
      matched_candidate_id uuid null
    ) on commit drop;

    truncate table _tmp_bpay_session_bucket_resolution;

    FOR v_bucket_element IN
      SELECT bucket_item.ordinality AS bucket_ordinal, bucket_item.value AS bucket_json
      FROM jsonb_array_elements(v_bucket_resolutions_json) WITH ORDINALITY AS bucket_item(value, ordinality)
      WHERE jsonb_typeof(bucket_item.value) = 'object'
      ORDER BY bucket_item.ordinality
    LOOP
      v_bucket_source_basis_json := CASE
        WHEN jsonb_typeof(v_bucket_element.bucket_json->'source_basis_json') = 'object' THEN COALESCE(v_bucket_element.bucket_json->'source_basis_json', '{}'::jsonb)
        WHEN jsonb_typeof(v_resolution_payload_json->'source_basis_json') = 'object' THEN COALESCE(v_resolution_payload_json->'source_basis_json', '{}'::jsonb)
        ELSE '{}'::jsonb
      END;

      v_bucket_source_basis_fingerprint := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'source_basis_fingerprint',
        v_resolution_payload_json->>'source_basis_fingerprint',
        ''
      ));
      IF v_bucket_source_basis_fingerprint = '' AND v_bucket_source_basis_json <> '{}'::jsonb THEN
        v_bucket_source_basis_fingerprint := md5(v_bucket_source_basis_json::text);
      END IF;

      v_bucket_source_family_key := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'source_family_key',
        v_resolution_payload_json->>'source_family_key',
        ''
      ));
      v_bucket_bucket_code := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'bucket_code',
        v_resolution_payload_json->>'bucket_code',
        ''
      )));
      v_bucket_component_key_type := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'component_key_type',
        v_resolution_payload_json->>'component_key_type',
        ''
      )));
      v_bucket_component_key_value := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'component_key_value',
        v_resolution_payload_json->>'component_key_value',
        ''
      ));
      v_bucket_resolution_mode := UPPER(BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'resolution_mode',
        v_default_resolution_mode,
        ''
      )));
      v_bucket_timesheet_id_text := BTRIM(COALESCE(
        v_bucket_element.bucket_json->>'timesheet_id',
        v_resolution_payload_json->>'linked_timesheet_id',
        v_resolution_payload_json->>'timesheet_id',
        ''
      ));
      v_bucket_timesheet_id := NULL::uuid;
      IF v_bucket_timesheet_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_bucket_timesheet_id := v_bucket_timesheet_id_text::uuid;
      END IF;

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_units',
        v_resolution_payload_json->>'source_units',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_units is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_units := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_units', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_units', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_rate',
        v_resolution_payload_json->>'source_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_rate', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'source_charge_rate',
        v_resolution_payload_json->>'source_charge_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'source_charge_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_source_charge_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'source_charge_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'source_charge_rate', '')::numeric
      ), 6);

      IF COALESCE(
        v_bucket_element.bucket_json->>'target_rate',
        v_resolution_payload_json->>'target_rate',
        ''
      ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RAISE EXCEPTION 'target_rate is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;
      v_bucket_target_rate := round(COALESCE(
        NULLIF(v_bucket_element.bucket_json->>'target_rate', '')::numeric,
        NULLIF(v_resolution_payload_json->>'target_rate', '')::numeric
      ), 2);

      IF v_bucket_target_rate < 0 THEN
        RAISE EXCEPTION 'target_rate must be non-negative for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_resolution_mode NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE') THEN
        RAISE EXCEPTION 'BUCKETED resolution_mode must be SUGGESTED_EQUIVALENT_BASIS or MANUAL_REPLACEMENT_RATE for bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_source_family_key = '' THEN
        RAISE EXCEPTION 'source_family_key is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_type = '' THEN
        RAISE EXCEPTION 'component_key_type is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_value = '' THEN
        RAISE EXCEPTION 'component_key_value is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_source_basis_fingerprint = '' THEN
        RAISE EXCEPTION 'source_basis_fingerprint or source_basis_json is required for BUCKETED resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      IF v_bucket_component_key_type IN ('TS_DAY', 'TS_TOTAL') AND v_bucket_bucket_code = '' THEN
        RAISE EXCEPTION 'bucket_code is required for BUCKETED worked-time resolution bucket %', v_bucket_element.bucket_ordinal;
      END IF;

      v_bucket_resolution_identity_key := concat_ws(
        '|',
        'BUCKETED',
        COALESCE(NULLIF(v_case_key, ''), '~'),
        COALESCE(CASE WHEN v_bucket_timesheet_id IS NULL THEN NULL ELSE v_bucket_timesheet_id::text END, '~'),
        COALESCE(NULLIF(v_bucket_source_basis_fingerprint, ''), '~'),
        COALESCE(NULLIF(v_bucket_source_family_key, ''), '~'),
        COALESCE(NULLIF(v_bucket_bucket_code, ''), '~'),
        COALESCE(NULLIF(v_bucket_component_key_type, ''), '~'),
        COALESCE(NULLIF(v_bucket_component_key_value, ''), '~')
      );

      INSERT INTO _tmp_bpay_session_bucket_resolution (
        bucket_ordinal,
        timesheet_id,
        source_basis_json,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        source_units,
        source_rate,
        source_charge_rate,
        resolution_mode,
        target_rate,
        resolution_identity_key,
        matched_candidate_id
      )
      VALUES (
        v_bucket_element.bucket_ordinal,
        v_bucket_timesheet_id,
        v_bucket_source_basis_json,
        v_bucket_source_basis_fingerprint,
        v_bucket_source_family_key,
        NULLIF(v_bucket_bucket_code, ''),
        v_bucket_component_key_type,
        v_bucket_component_key_value,
        v_bucket_source_units,
        v_bucket_source_rate,
        v_bucket_source_charge_rate,
        v_bucket_resolution_mode,
        v_bucket_target_rate,
        v_bucket_resolution_identity_key,
        NULL::uuid
      );
    END LOOP;

    SELECT COUNT(*)::integer
    INTO v_bucket_count
    FROM _tmp_bpay_session_bucket_resolution;

    IF v_bucket_count = 0 THEN
      RAISE EXCEPTION 'bucket_resolutions must contain at least one JSON object for BUCKETED resolution';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM _tmp_bpay_session_bucket_resolution AS tmp_duplicate_bucket
      GROUP BY tmp_duplicate_bucket.resolution_identity_key
      HAVING COUNT(*) > 1
    ) THEN
      RAISE EXCEPTION 'Duplicate bucket resolution identity detected for case_key %', v_case_key;
    END IF;

    FOR v_bucket_row IN
      SELECT *
      FROM _tmp_bpay_session_bucket_resolution
      ORDER BY bucket_ordinal
    LOOP
      IF v_candidate_id IS NULL THEN
        SELECT COALESCE(array_agg(DISTINCT snapshot_component.candidate_id ORDER BY snapshot_component.candidate_id), ARRAY[]::uuid[])
        INTO v_matching_candidate_ids
        FROM public.banking_pay_snapshot_case_component_state AS snapshot_component
        WHERE snapshot_component.snapshot_run_id = v_session_row.source_snapshot_run_id
          AND COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[snapshot_component.candidate_id]::uuid[]
          AND snapshot_component.case_key = v_case_key
          AND COALESCE(snapshot_component.timesheet_id::text, '') = COALESCE(v_bucket_row.timesheet_id::text, '')
          AND COALESCE(snapshot_component.source_basis_fingerprint, '') = v_bucket_row.source_basis_fingerprint
          AND COALESCE(snapshot_component.source_family_key, '') = v_bucket_row.source_family_key
          AND COALESCE(snapshot_component.bucket_code, '') = COALESCE(v_bucket_row.bucket_code, '')
          AND COALESCE(snapshot_component.component_key_type, '') = v_bucket_row.component_key_type
          AND COALESCE(snapshot_component.component_key_value, '') = v_bucket_row.component_key_value;

        v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
        IF v_matching_candidate_count = 0 THEN
          RAISE EXCEPTION 'No snapshot baseline target found for BUCKETED resolution in session % for case_key % bucket %', p_session_id, v_case_key, v_bucket_row.bucket_ordinal;
        ELSIF v_matching_candidate_count > 1 THEN
          RAISE EXCEPTION 'Ambiguous BUCKETED resolution target for case_key % in session % bucket %', v_case_key, p_session_id, v_bucket_row.bucket_ordinal;
        END IF;

        UPDATE _tmp_bpay_session_bucket_resolution
        SET matched_candidate_id = v_matching_candidate_ids[1]
        WHERE _tmp_bpay_session_bucket_resolution.bucket_ordinal = v_bucket_row.bucket_ordinal;
      ELSE
        SELECT COUNT(*)::integer
        INTO v_target_match_count
        FROM public.banking_pay_snapshot_case_component_state AS snapshot_component
        WHERE snapshot_component.snapshot_run_id = v_session_row.source_snapshot_run_id
          AND snapshot_component.candidate_id = v_candidate_id
          AND snapshot_component.case_key = v_case_key
          AND COALESCE(snapshot_component.timesheet_id::text, '') = COALESCE(v_bucket_row.timesheet_id::text, '')
          AND COALESCE(snapshot_component.source_basis_fingerprint, '') = v_bucket_row.source_basis_fingerprint
          AND COALESCE(snapshot_component.source_family_key, '') = v_bucket_row.source_family_key
          AND COALESCE(snapshot_component.bucket_code, '') = COALESCE(v_bucket_row.bucket_code, '')
          AND COALESCE(snapshot_component.component_key_type, '') = v_bucket_row.component_key_type
          AND COALESCE(snapshot_component.component_key_value, '') = v_bucket_row.component_key_value;

        IF v_target_match_count = 0 THEN
          RAISE EXCEPTION 'No matching BUCKETED snapshot baseline target found for candidate % in session % bucket %', v_candidate_id, p_session_id, v_bucket_row.bucket_ordinal;
        ELSIF v_target_match_count > 1 THEN
          RAISE EXCEPTION 'Ambiguous BUCKETED snapshot baseline target found for candidate % in session % bucket %', v_candidate_id, p_session_id, v_bucket_row.bucket_ordinal;
        END IF;

        UPDATE _tmp_bpay_session_bucket_resolution
        SET matched_candidate_id = v_candidate_id
        WHERE _tmp_bpay_session_bucket_resolution.bucket_ordinal = v_bucket_row.bucket_ordinal;
      END IF;
    END LOOP;

    IF v_candidate_id IS NULL THEN
      SELECT COALESCE(array_agg(DISTINCT tmp_bucket.matched_candidate_id ORDER BY tmp_bucket.matched_candidate_id), ARRAY[]::uuid[])
      INTO v_matching_candidate_ids
      FROM _tmp_bpay_session_bucket_resolution AS tmp_bucket
      WHERE tmp_bucket.matched_candidate_id IS NOT NULL;

      v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
      IF v_matching_candidate_count = 0 THEN
        RAISE EXCEPTION 'Unable to resolve candidate_id for BUCKETED resolution in session % case_key %', p_session_id, v_case_key;
      ELSIF v_matching_candidate_count > 1 THEN
        RAISE EXCEPTION 'BUCKETED resolution payload spans multiple candidates for session % case_key %', p_session_id, v_case_key;
      END IF;

      v_resolved_candidate_id := v_matching_candidate_ids[1];
    ELSE
      v_resolved_candidate_id := v_candidate_id;
    END IF;

    INSERT INTO _tmp_bpay_session_case_resolution_existing
    SELECT existing_resolution.*
    FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
    WHERE existing_resolution.session_id = p_session_id
      AND existing_resolution.candidate_id = v_resolved_candidate_id
      AND existing_resolution.case_key = v_case_key
      AND existing_resolution.resolution_family = 'BUCKETED'
      AND (
        v_linked_timesheet_id IS NULL
        OR existing_resolution.timesheet_id = v_linked_timesheet_id
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'linked_timesheet_id', '')), '') = v_linked_timesheet_id::text
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'timesheet_id', '')), '') = v_linked_timesheet_id::text
      )
      AND (
        v_finance_case_id_text = ''
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') = v_finance_case_id_text
      );

    SELECT COUNT(*)::integer
    INTO v_existing_deleted_count
    FROM _tmp_bpay_session_case_resolution_existing;

    IF v_existing_deleted_count > 0 THEN
      DELETE FROM public.banking_pay_workbench_session_case_resolutions AS delete_resolution
      WHERE delete_resolution.id IN (
        SELECT temp_existing.id
        FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
      );
    END IF;

    FOR v_bucket_row IN
      SELECT *
      FROM _tmp_bpay_session_bucket_resolution
      ORDER BY bucket_ordinal
    LOOP
      v_existing_row := NULL;
      SELECT temp_existing.*
      INTO v_existing_row
      FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
      WHERE temp_existing.resolution_identity_key = v_bucket_row.resolution_identity_key
      LIMIT 1;

      v_normalized_payload_json := jsonb_strip_nulls(
        (COALESCE(v_resolution_payload_json, '{}'::jsonb) - 'bucket_resolutions' - 'resolution_mode' - 'mode' - 'candidate_id' - 'case_key' - 'resolution_family' - 'timesheet_id' - 'linked_timesheet_id' - 'target_rate' - 'source_units' - 'source_rate' - 'source_charge_rate')
        || jsonb_build_object(
          'case_key', v_case_key,
          'candidate_id', v_resolved_candidate_id::text,
          'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
          'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
          'timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
          'resolution_family', 'BUCKETED',
          'resolve_all_linked_timesheets', v_resolve_all_linked_timesheets,
          'bucket_resolutions', jsonb_build_array(
            jsonb_strip_nulls(
              jsonb_build_object(
                'timesheet_id', CASE WHEN v_bucket_row.timesheet_id IS NULL THEN NULL ELSE v_bucket_row.timesheet_id::text END,
                'source_basis_json', CASE WHEN v_bucket_row.source_basis_json = '{}'::jsonb THEN NULL ELSE v_bucket_row.source_basis_json END,
                'source_basis_fingerprint', NULLIF(v_bucket_row.source_basis_fingerprint, ''),
                'source_family_key', NULLIF(v_bucket_row.source_family_key, ''),
                'bucket_code', v_bucket_row.bucket_code,
                'component_key_type', NULLIF(v_bucket_row.component_key_type, ''),
                'component_key_value', NULLIF(v_bucket_row.component_key_value, ''),
                'source_units', round(v_bucket_row.source_units, 6),
                'source_rate', round(v_bucket_row.source_rate, 6),
                'source_charge_rate', round(v_bucket_row.source_charge_rate, 6),
                'resolution_mode', v_bucket_row.resolution_mode,
                'target_rate', round(v_bucket_row.target_rate, 2)
              )
            )
          )
        )
      );

      v_audit_before_json := CASE
        WHEN v_existing_row.id IS NULL THEN NULL
        ELSE jsonb_build_object(
          'id', v_existing_row.id::text,
          'session_id', v_existing_row.session_id::text,
          'candidate_id', v_existing_row.candidate_id::text,
          'case_key', v_existing_row.case_key,
          'resolution_family', v_existing_row.resolution_family,
          'resolution_identity_key', v_existing_row.resolution_identity_key,
          'timesheet_id', CASE WHEN v_existing_row.timesheet_id IS NULL THEN NULL ELSE v_existing_row.timesheet_id::text END,
          'source_basis_fingerprint', v_existing_row.source_basis_fingerprint,
          'source_family_key', v_existing_row.source_family_key,
          'bucket_code', v_existing_row.bucket_code,
          'component_key_type', v_existing_row.component_key_type,
          'component_key_value', v_existing_row.component_key_value,
          'payload_json', v_existing_row.payload_json
        )
      END;

      INSERT INTO public.banking_pay_workbench_session_case_resolutions (
        session_id,
        candidate_id,
        case_key,
        resolution_family,
        resolution_identity_key,
        timesheet_id,
        source_basis_fingerprint,
        source_family_key,
        bucket_code,
        component_key_type,
        component_key_value,
        payload_json,
        created_at_utc,
        updated_at_utc
      )
      VALUES (
        p_session_id,
        v_resolved_candidate_id,
        v_case_key,
        'BUCKETED',
        v_bucket_row.resolution_identity_key,
        v_bucket_row.timesheet_id,
        NULLIF(v_bucket_row.source_basis_fingerprint, ''),
        NULLIF(v_bucket_row.source_family_key, ''),
        v_bucket_row.bucket_code,
        NULLIF(v_bucket_row.component_key_type, ''),
        NULLIF(v_bucket_row.component_key_value, ''),
        v_normalized_payload_json,
        v_now,
        v_now
      )
      ON CONFLICT (session_id, resolution_identity_key)
      DO UPDATE
      SET candidate_id = EXCLUDED.candidate_id,
          case_key = EXCLUDED.case_key,
          resolution_family = EXCLUDED.resolution_family,
          timesheet_id = EXCLUDED.timesheet_id,
          source_basis_fingerprint = EXCLUDED.source_basis_fingerprint,
          source_family_key = EXCLUDED.source_family_key,
          bucket_code = EXCLUDED.bucket_code,
          component_key_type = EXCLUDED.component_key_type,
          component_key_value = EXCLUDED.component_key_value,
          payload_json = EXCLUDED.payload_json,
          updated_at_utc = v_now
      RETURNING public.banking_pay_workbench_session_case_resolutions.*
      INTO v_upserted_row;

      v_case_resolution_ids := v_case_resolution_ids || jsonb_build_array(v_upserted_row.id::text);
      v_resolution_identity_keys := v_resolution_identity_keys || jsonb_build_array(v_upserted_row.resolution_identity_key);
      IF v_case_resolution_id_text IS NULL THEN
        v_case_resolution_id_text := v_upserted_row.id::text;
      END IF;

      v_audit_after_json := jsonb_build_object(
        'id', v_upserted_row.id::text,
        'session_id', v_upserted_row.session_id::text,
        'candidate_id', v_upserted_row.candidate_id::text,
        'case_key', v_upserted_row.case_key,
        'resolution_family', v_upserted_row.resolution_family,
        'resolution_identity_key', v_upserted_row.resolution_identity_key,
        'timesheet_id', CASE WHEN v_upserted_row.timesheet_id IS NULL THEN NULL ELSE v_upserted_row.timesheet_id::text END,
        'source_basis_fingerprint', v_upserted_row.source_basis_fingerprint,
        'source_family_key', v_upserted_row.source_family_key,
        'bucket_code', v_upserted_row.bucket_code,
        'component_key_type', v_upserted_row.component_key_type,
        'component_key_value', v_upserted_row.component_key_value,
        'payload_json', v_upserted_row.payload_json
      );

      PERFORM public._audit_insert(
        'banking_pay_workbench_session_case_resolution',
        v_upserted_row.id::text,
        CASE WHEN v_existing_row.id IS NULL THEN 'SESSION_CASE_RESOLUTION_CREATED' ELSE 'SESSION_CASE_RESOLUTION_UPDATED' END,
        v_audit_before_json,
        v_audit_after_json,
        'SESSION_CASE_RESOLUTION_APPLIED',
        p_actor_user_id
      );
    END LOOP;
  ELSE
    v_nonbucket_resolution_mode := UPPER(BTRIM(COALESCE(
      v_resolution_payload_json->>'resolution_mode',
      v_resolution_payload_json->>'mode',
      ''
    )));

    IF v_nonbucket_resolution_mode NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_AMOUNT') THEN
      RAISE EXCEPTION 'NON_BUCKET resolution_mode must be SUGGESTED_EQUIVALENT_BASIS or MANUAL_AMOUNT';
    END IF;

    IF COALESCE(
      v_resolution_payload_json->>'target_amount_ex_vat',
      v_resolution_payload_json->>'target_amount',
      v_resolution_payload_json->>'amount_ex_vat',
      v_resolution_payload_json->>'amount',
      ''
    ) !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
      RAISE EXCEPTION 'target_amount_ex_vat is required for NON_BUCKET resolution';
    END IF;

    v_target_amount_ex_vat := round(COALESCE(
      NULLIF(v_resolution_payload_json->>'target_amount_ex_vat', '')::numeric,
      NULLIF(v_resolution_payload_json->>'target_amount', '')::numeric,
      NULLIF(v_resolution_payload_json->>'amount_ex_vat', '')::numeric,
      NULLIF(v_resolution_payload_json->>'amount', '')::numeric
    ), 2);

    IF v_target_amount_ex_vat < 0 THEN
      RAISE EXCEPTION 'target_amount_ex_vat must be non-negative';
    END IF;

    IF v_candidate_id IS NULL THEN
      SELECT COALESCE(array_agg(DISTINCT snapshot_case.candidate_id ORDER BY snapshot_case.candidate_id), ARRAY[]::uuid[])
      INTO v_matching_candidate_ids
      FROM public.banking_pay_snapshot_case_state AS snapshot_case
      WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]) @> ARRAY[snapshot_case.candidate_id]::uuid[]
        AND snapshot_case.case_key = v_case_key;

      v_matching_candidate_count := COALESCE(array_length(v_matching_candidate_ids, 1), 0);
      IF v_matching_candidate_count = 0 THEN
        RAISE EXCEPTION 'No snapshot baseline case found for NON_BUCKET resolution in session % for case_key %', p_session_id, v_case_key;
      ELSIF v_matching_candidate_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous NON_BUCKET resolution target for case_key % in session %', v_case_key, p_session_id;
      END IF;

      v_resolved_candidate_id := v_matching_candidate_ids[1];
    ELSE
      SELECT COUNT(*)::integer
      INTO v_target_match_count
      FROM public.banking_pay_snapshot_case_state AS snapshot_case
      WHERE snapshot_case.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND snapshot_case.candidate_id = v_candidate_id
        AND snapshot_case.case_key = v_case_key;

      IF v_target_match_count = 0 THEN
        RAISE EXCEPTION 'No matching NON_BUCKET snapshot baseline case found for candidate % in session %', v_candidate_id, p_session_id;
      ELSIF v_target_match_count > 1 THEN
        RAISE EXCEPTION 'Ambiguous NON_BUCKET snapshot baseline case found for candidate % in session %', v_candidate_id, p_session_id;
      END IF;

      v_resolved_candidate_id := v_candidate_id;
    END IF;

    INSERT INTO _tmp_bpay_session_case_resolution_existing
    SELECT existing_resolution.*
    FROM public.banking_pay_workbench_session_case_resolutions AS existing_resolution
    WHERE existing_resolution.session_id = p_session_id
      AND existing_resolution.candidate_id = v_resolved_candidate_id
      AND existing_resolution.case_key = v_case_key
      AND existing_resolution.resolution_family = 'NON_BUCKET'
      AND (
        v_linked_timesheet_id IS NULL
        OR existing_resolution.timesheet_id = v_linked_timesheet_id
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'linked_timesheet_id', '')), '') = v_linked_timesheet_id::text
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'timesheet_id', '')), '') = v_linked_timesheet_id::text
      )
      AND (
        v_finance_case_id_text = ''
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(existing_resolution.payload_json->>'finance_case_id', '')), '') = v_finance_case_id_text
      );

    v_nonbucket_resolution_identity_key := concat_ws(
      '|',
      'NON_BUCKET',
      COALESCE(NULLIF(v_case_key, ''), '~'),
      COALESCE(CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END, '~'),
      '~',
      '~',
      '~',
      '~',
      '~'
    );

    v_nonbucket_existing_row := NULL;
    SELECT temp_existing.*
    INTO v_nonbucket_existing_row
    FROM _tmp_bpay_session_case_resolution_existing AS temp_existing
    WHERE temp_existing.resolution_identity_key = v_nonbucket_resolution_identity_key
    LIMIT 1;

    v_normalized_payload_json := jsonb_strip_nulls(
      (COALESCE(v_resolution_payload_json, '{}'::jsonb) - 'bucket_resolutions' - 'candidate_id' - 'case_key' - 'resolution_family' - 'timesheet_id' - 'linked_timesheet_id')
      || jsonb_build_object(
        'case_key', v_case_key,
        'candidate_id', v_resolved_candidate_id::text,
        'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
        'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
        'timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
        'resolution_family', 'NON_BUCKET',
        'resolution_mode', v_nonbucket_resolution_mode,
        'target_amount_ex_vat', round(v_target_amount_ex_vat, 2)
      )
    );

    v_audit_before_json := CASE
      WHEN v_nonbucket_existing_row.id IS NULL THEN NULL
      ELSE jsonb_build_object(
        'id', v_nonbucket_existing_row.id::text,
        'session_id', v_nonbucket_existing_row.session_id::text,
        'candidate_id', v_nonbucket_existing_row.candidate_id::text,
        'case_key', v_nonbucket_existing_row.case_key,
        'resolution_family', v_nonbucket_existing_row.resolution_family,
        'resolution_identity_key', v_nonbucket_existing_row.resolution_identity_key,
        'timesheet_id', CASE WHEN v_nonbucket_existing_row.timesheet_id IS NULL THEN NULL ELSE v_nonbucket_existing_row.timesheet_id::text END,
        'source_basis_fingerprint', v_nonbucket_existing_row.source_basis_fingerprint,
        'source_family_key', v_nonbucket_existing_row.source_family_key,
        'bucket_code', v_nonbucket_existing_row.bucket_code,
        'component_key_type', v_nonbucket_existing_row.component_key_type,
        'component_key_value', v_nonbucket_existing_row.component_key_value,
        'payload_json', v_nonbucket_existing_row.payload_json
      )
    END;

    INSERT INTO public.banking_pay_workbench_session_case_resolutions (
      session_id,
      candidate_id,
      case_key,
      resolution_family,
      resolution_identity_key,
      timesheet_id,
      source_basis_fingerprint,
      source_family_key,
      bucket_code,
      component_key_type,
      component_key_value,
      payload_json,
      created_at_utc,
      updated_at_utc
    )
    VALUES (
      p_session_id,
      v_resolved_candidate_id,
      v_case_key,
      'NON_BUCKET',
      v_nonbucket_resolution_identity_key,
      v_linked_timesheet_id,
      NULL,
      NULL,
      NULL,
      NULL,
      NULL,
      v_normalized_payload_json,
      v_now,
      v_now
    )
    ON CONFLICT (session_id, resolution_identity_key)
    DO UPDATE
    SET candidate_id = EXCLUDED.candidate_id,
        case_key = EXCLUDED.case_key,
        resolution_family = EXCLUDED.resolution_family,
        timesheet_id = EXCLUDED.timesheet_id,
        payload_json = EXCLUDED.payload_json,
        updated_at_utc = v_now
    RETURNING public.banking_pay_workbench_session_case_resolutions.*
    INTO v_nonbucket_upserted_row;

    v_case_resolution_ids := jsonb_build_array(v_nonbucket_upserted_row.id::text);
    v_resolution_identity_keys := jsonb_build_array(v_nonbucket_upserted_row.resolution_identity_key);
    v_case_resolution_id_text := v_nonbucket_upserted_row.id::text;

    v_audit_after_json := jsonb_build_object(
      'id', v_nonbucket_upserted_row.id::text,
      'session_id', v_nonbucket_upserted_row.session_id::text,
      'candidate_id', v_nonbucket_upserted_row.candidate_id::text,
      'case_key', v_nonbucket_upserted_row.case_key,
      'resolution_family', v_nonbucket_upserted_row.resolution_family,
      'resolution_identity_key', v_nonbucket_upserted_row.resolution_identity_key,
      'timesheet_id', CASE WHEN v_nonbucket_upserted_row.timesheet_id IS NULL THEN NULL ELSE v_nonbucket_upserted_row.timesheet_id::text END,
      'payload_json', v_nonbucket_upserted_row.payload_json
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_session_case_resolution',
      v_nonbucket_upserted_row.id::text,
      CASE WHEN v_nonbucket_existing_row.id IS NULL THEN 'SESSION_CASE_RESOLUTION_CREATED' ELSE 'SESSION_CASE_RESOLUTION_UPDATED' END,
      v_audit_before_json,
      v_audit_after_json,
      'SESSION_CASE_RESOLUTION_APPLIED',
      p_actor_user_id
    );
  END IF;

  UPDATE public.banking_pay_workbench_sessions
  SET version = public.banking_pay_workbench_sessions.version + 1,
      updated_at_utc = v_now
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  RETURNING public.banking_pay_workbench_sessions.version
  INTO v_new_session_version;

  v_job_json := public.pay_workbench_enqueue_session_candidate_refresh(
    p_session_id => p_session_id,
    p_candidate_id => COALESCE(v_resolved_candidate_id, v_candidate_id),
    p_reason => v_action,
    p_actor_user_id => p_actor_user_id,
    p_payload_json => jsonb_build_object(
      'case_key', v_case_key,
      'resolution_family', v_resolution_family,
      'finance_case_id', CASE WHEN v_finance_case_id_text = '' THEN NULL ELSE v_finance_case_id_text END,
      'linked_timesheet_id', CASE WHEN v_linked_timesheet_id IS NULL THEN NULL ELSE v_linked_timesheet_id::text END,
      'resolution_identity_keys', v_resolution_identity_keys
    )
  );

  IF BTRIM(COALESCE(v_job_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_job_id := (v_job_json->>'job_id')::uuid;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'candidate_id', COALESCE(v_resolved_candidate_id, v_candidate_id)::text,
    'session_version', v_new_session_version,
    'job_id', CASE WHEN v_job_id IS NULL THEN NULL ELSE v_job_id::text END,
    'case_resolution_id', v_case_resolution_id_text,
    'case_resolution_ids', v_case_resolution_ids,
    'resolution_identity_keys', v_resolution_identity_keys,
    'case_resolution_count', jsonb_array_length(v_case_resolution_ids),
    'state_changed', true,
    'action', v_action,
    'durable_result', CASE WHEN v_resolution_family = 'TAXABLE_CHANNEL_RESTRUCTURE' THEN v_taxable_result_json ELSE NULL END
  );
END;
$function$;







DROP FUNCTION IF EXISTS public.pay_workbench_session_get_progress(uuid);
CREATE OR REPLACE FUNCTION public.pay_workbench_session_get_progress(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_pending_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_failed_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_candidate_statuses_jsonb jsonb := '[]'::jsonb;
  v_pending_job_ids_jsonb jsonb := '[]'::jsonb;
  v_recent_jobs_jsonb jsonb := '[]'::jsonb;
  v_ready_count integer := 0;
  v_pending_count integer := 0;
  v_failed_count integer := 0;
  v_total_count integer := 0;
  v_completed_count integer := 0;
  v_active_job_count integer := 0;
  v_ready_flag boolean := false;
  v_ready_empty boolean := false;
  v_phase text := 'REFRESHING_CANDIDATES';
  v_status_text text := 'Preparing payment preview.';
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id;

  IF v_session_row.id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'WORKBENCH_SESSION_NOT_FOUND',
      'code', 'WORKBENCH_SESSION_NOT_FOUND',
      'rebase_required', true,
      'requires_new_session', true,
      'session_id', p_session_id::text,
      'status', NULL,
      'ready', false,
      'ready_flag', false,
      'ready_empty', false,
      'phase', 'REBASE_REQUIRED',
      'status_text', 'Payment preview needs refreshing.',
      'pending_candidate_ids', '[]'::jsonb,
      'failed_candidate_ids', '[]'::jsonb,
      'pending_job_ids', '[]'::jsonb,
      'candidate_status_rows', '[]'::jsonb,
      'candidate_statuses', '[]'::jsonb,
      'recent_jobs', '[]'::jsonb
    );
  END IF;

  IF UPPER(COALESCE(v_session_row.status, '')) <> 'OPEN' OR v_session_row.discarded_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'OBSOLETE_SESSION',
      'code', 'OBSOLETE_SESSION',
      'rebase_required', true,
      'requires_new_session', true,
      'session_id', p_session_id::text,
      'status', v_session_row.status,
      'session_status', v_session_row.status,
      'discarded_at_utc', v_session_row.discarded_at_utc,
      'ready', false,
      'ready_flag', false,
      'ready_empty', false,
      'phase', 'REBASE_REQUIRED',
      'status_text', 'Payment preview needs refreshing.',
      'pending_candidate_ids', '[]'::jsonb,
      'failed_candidate_ids', '[]'::jsonb,
      'pending_job_ids', '[]'::jsonb,
      'candidate_status_rows', '[]'::jsonb,
      'candidate_statuses', '[]'::jsonb,
      'recent_jobs', '[]'::jsonb
    );
  END IF;

  WITH scoped_candidates AS (
    SELECT scoped_candidate.scoped_candidate_id AS candidate_id
    FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS scoped_candidate(scoped_candidate_id)
  ),
  candidate_status_rows AS (
    SELECT
      scoped_candidates.candidate_id,
      CASE
        WHEN latest_session_state.id IS NOT NULL
             AND UPPER(COALESCE(latest_session_state.status, '')) = 'READY'
             AND COALESCE(latest_session_state.session_version, 0) >= v_session_row.version
             AND COALESCE(latest_session_state.source_change_seq, 0) >= COALESCE(live_change_counter.seq, 0)
          THEN 'READY'
        WHEN latest_session_state.id IS NOT NULL
             AND UPPER(COALESCE(latest_session_state.status, '')) = 'FAILED'
             AND COALESCE(latest_session_state.session_version, 0) >= v_session_row.version
             AND COALESCE(latest_session_state.source_change_seq, 0) >= COALESCE(live_change_counter.seq, 0)
             AND selected_pending_job.id IS NULL
          THEN 'FAILED'
        ELSE 'PENDING'
      END AS status,
      COALESCE(latest_session_state.source_change_seq, COALESCE(live_change_counter.seq, 0)) AS source_change_seq,
      COALESCE(latest_session_state.session_version, v_session_row.version) AS session_version,
      COALESCE(live_change_counter.seq, 0) AS required_source_change_seq,
      v_session_row.version AS required_session_version,
      selected_pending_job.id AS pending_job_id,
      latest_session_state.last_recomputed_at_utc,
      COALESCE(latest_session_state.last_error_json, selected_latest_job.last_error_json) AS last_error_json,
      selected_latest_job.id AS latest_job_id,
      selected_latest_job.job_type AS latest_job_type,
      selected_latest_job.status AS latest_job_status,
      selected_latest_job.attempt_count AS latest_job_attempt_count,
      selected_latest_job.max_attempts AS latest_job_max_attempts,
      selected_latest_job.last_error_json AS latest_job_last_error_json
    FROM scoped_candidates
    LEFT JOIN public.app_change_counters AS live_change_counter
      ON live_change_counter.entity_key = 'pay_candidate:' || scoped_candidates.candidate_id::text
    LEFT JOIN LATERAL (
      SELECT public.banking_pay_workbench_session_candidate_state.*
      FROM public.banking_pay_workbench_session_candidate_state
      WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
        AND public.banking_pay_workbench_session_candidate_state.candidate_id = scoped_candidates.candidate_id
      ORDER BY public.banking_pay_workbench_session_candidate_state.updated_at_utc DESC, public.banking_pay_workbench_session_candidate_state.id DESC
      LIMIT 1
    ) AS latest_session_state ON true
    LEFT JOIN LATERAL (
      SELECT
        public.banking_pay_workbench_jobs.id,
        public.banking_pay_workbench_jobs.job_type,
        public.banking_pay_workbench_jobs.status,
        public.banking_pay_workbench_jobs.attempt_count,
        public.banking_pay_workbench_jobs.max_attempts,
        public.banking_pay_workbench_jobs.last_error_json,
        public.banking_pay_workbench_jobs.updated_at_utc,
        public.banking_pay_workbench_jobs.created_at_utc,
        CASE
          WHEN latest_session_state.pending_job_id IS NOT NULL
               AND public.banking_pay_workbench_jobs.id = latest_session_state.pending_job_id THEN 1
          WHEN public.banking_pay_workbench_jobs.payload_json->>'session_id' = p_session_id::text THEN 2
          WHEN public.banking_pay_workbench_jobs.session_id = p_session_id THEN 3
          WHEN public.banking_pay_workbench_jobs.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
               AND public.banking_pay_workbench_jobs.snapshot_run_id = v_session_row.source_snapshot_run_id
               AND public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id THEN 4
          ELSE 99
        END AS match_rank
      FROM public.banking_pay_workbench_jobs
      WHERE public.banking_pay_workbench_jobs.status IN ('QUEUED', 'RUNNING')
        AND public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id
        AND (
          (latest_session_state.pending_job_id IS NOT NULL AND public.banking_pay_workbench_jobs.id = latest_session_state.pending_job_id)
          OR public.banking_pay_workbench_jobs.payload_json->>'session_id' = p_session_id::text
          OR public.banking_pay_workbench_jobs.session_id = p_session_id
          OR (
            public.banking_pay_workbench_jobs.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
            AND public.banking_pay_workbench_jobs.snapshot_run_id = v_session_row.source_snapshot_run_id
            AND public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id
          )
        )
      ORDER BY
        match_rank ASC,
        public.banking_pay_workbench_jobs.updated_at_utc DESC,
        public.banking_pay_workbench_jobs.created_at_utc DESC,
        public.banking_pay_workbench_jobs.id DESC
      LIMIT 1
    ) AS selected_pending_job ON true
    LEFT JOIN LATERAL (
      SELECT
        public.banking_pay_workbench_jobs.id,
        public.banking_pay_workbench_jobs.job_type,
        public.banking_pay_workbench_jobs.status,
        public.banking_pay_workbench_jobs.attempt_count,
        public.banking_pay_workbench_jobs.max_attempts,
        public.banking_pay_workbench_jobs.last_error_json,
        public.banking_pay_workbench_jobs.updated_at_utc,
        public.banking_pay_workbench_jobs.created_at_utc,
        CASE
          WHEN selected_pending_job.id IS NOT NULL
               AND public.banking_pay_workbench_jobs.id = selected_pending_job.id THEN 1
          WHEN latest_session_state.pending_job_id IS NOT NULL
               AND public.banking_pay_workbench_jobs.id = latest_session_state.pending_job_id THEN 2
          WHEN public.banking_pay_workbench_jobs.payload_json->>'session_id' = p_session_id::text THEN 3
          WHEN public.banking_pay_workbench_jobs.session_id = p_session_id THEN 4
          WHEN public.banking_pay_workbench_jobs.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
               AND public.banking_pay_workbench_jobs.snapshot_run_id = v_session_row.source_snapshot_run_id
               AND public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id THEN 5
          ELSE 99
        END AS match_rank
      FROM public.banking_pay_workbench_jobs
      WHERE public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id
        AND (
          (selected_pending_job.id IS NOT NULL AND public.banking_pay_workbench_jobs.id = selected_pending_job.id)
          OR (latest_session_state.pending_job_id IS NOT NULL AND public.banking_pay_workbench_jobs.id = latest_session_state.pending_job_id)
          OR public.banking_pay_workbench_jobs.payload_json->>'session_id' = p_session_id::text
          OR public.banking_pay_workbench_jobs.session_id = p_session_id
          OR (
            public.banking_pay_workbench_jobs.job_type = 'SNAPSHOT_CANDIDATE_REFRESH'
            AND public.banking_pay_workbench_jobs.snapshot_run_id = v_session_row.source_snapshot_run_id
            AND public.banking_pay_workbench_jobs.candidate_id = scoped_candidates.candidate_id
          )
        )
      ORDER BY
        match_rank ASC,
        public.banking_pay_workbench_jobs.updated_at_utc DESC,
        public.banking_pay_workbench_jobs.created_at_utc DESC,
        public.banking_pay_workbench_jobs.id DESC
      LIMIT 1
    ) AS selected_latest_job ON true
  )
  SELECT
    COALESCE(
      jsonb_agg(candidate_status_rows.candidate_id::text ORDER BY candidate_status_rows.candidate_id)
        FILTER (WHERE candidate_status_rows.status = 'PENDING'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(candidate_status_rows.candidate_id::text ORDER BY candidate_status_rows.candidate_id)
        FILTER (WHERE candidate_status_rows.status = 'FAILED'),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'candidate_id', candidate_status_rows.candidate_id::text,
          'status', candidate_status_rows.status,
          'source_change_seq', candidate_status_rows.source_change_seq,
          'session_version', candidate_status_rows.session_version,
          'required_source_change_seq', candidate_status_rows.required_source_change_seq,
          'required_session_version', candidate_status_rows.required_session_version,
          'pending_job_id', CASE WHEN candidate_status_rows.pending_job_id IS NULL THEN NULL ELSE candidate_status_rows.pending_job_id::text END,
          'latest_job_id', CASE WHEN candidate_status_rows.latest_job_id IS NULL THEN NULL ELSE candidate_status_rows.latest_job_id::text END,
          'latest_job_type', candidate_status_rows.latest_job_type,
          'latest_job_status', candidate_status_rows.latest_job_status,
          'latest_job_attempt_count', candidate_status_rows.latest_job_attempt_count,
          'latest_job_max_attempts', candidate_status_rows.latest_job_max_attempts,
          'last_recomputed_at_utc', candidate_status_rows.last_recomputed_at_utc,
          'last_error_json', COALESCE(candidate_status_rows.last_error_json, candidate_status_rows.latest_job_last_error_json),
          'latest_job_last_error_json', candidate_status_rows.latest_job_last_error_json
        )
        ORDER BY candidate_status_rows.candidate_id
      ),
      '[]'::jsonb
    ),
    COALESCE(
      jsonb_agg(candidate_status_rows.pending_job_id::text ORDER BY candidate_status_rows.pending_job_id)
        FILTER (WHERE candidate_status_rows.pending_job_id IS NOT NULL AND candidate_status_rows.status = 'PENDING'),
      '[]'::jsonb
    ),
    COUNT(*) FILTER (WHERE candidate_status_rows.status = 'READY')::integer,
    COUNT(*) FILTER (WHERE candidate_status_rows.status = 'PENDING')::integer,
    COUNT(*) FILTER (WHERE candidate_status_rows.status = 'FAILED')::integer
  INTO
    v_pending_candidate_ids_jsonb,
    v_failed_candidate_ids_jsonb,
    v_candidate_statuses_jsonb,
    v_pending_job_ids_jsonb,
    v_ready_count,
    v_pending_count,
    v_failed_count
  FROM candidate_status_rows;

  SELECT COALESCE(
           jsonb_agg(
             jsonb_build_object(
               'job_id', recent_jobs.id::text,
               'job_type', recent_jobs.job_type,
               'status', recent_jobs.status,
               'priority', recent_jobs.priority,
               'run_at_utc', recent_jobs.run_at_utc,
               'attempt_count', recent_jobs.attempt_count,
               'max_attempts', recent_jobs.max_attempts,
               'snapshot_run_id', CASE WHEN recent_jobs.snapshot_run_id IS NULL THEN NULL ELSE recent_jobs.snapshot_run_id::text END,
               'session_id', CASE WHEN recent_jobs.session_id IS NULL THEN NULL ELSE recent_jobs.session_id::text END,
               'payload_session_id', NULLIF(recent_jobs.payload_json->>'session_id', ''),
               'candidate_id', CASE WHEN recent_jobs.candidate_id IS NULL THEN NULL ELSE recent_jobs.candidate_id::text END,
               'started_at_utc', recent_jobs.started_at_utc,
               'completed_at_utc', recent_jobs.completed_at_utc,
               'failed_at_utc', recent_jobs.failed_at_utc,
               'last_error_json', recent_jobs.last_error_json
             )
             ORDER BY recent_jobs.updated_at_utc DESC, recent_jobs.id DESC
           ),
           '[]'::jsonb
         )
  INTO v_recent_jobs_jsonb
  FROM (
    SELECT public.banking_pay_workbench_jobs.*
    FROM public.banking_pay_workbench_jobs
    WHERE public.banking_pay_workbench_jobs.session_id = p_session_id
       OR public.banking_pay_workbench_jobs.payload_json->>'session_id' = p_session_id::text
       OR public.banking_pay_workbench_jobs.id IN (
            SELECT public.banking_pay_workbench_session_candidate_state.pending_job_id
            FROM public.banking_pay_workbench_session_candidate_state
            WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
              AND public.banking_pay_workbench_session_candidate_state.pending_job_id IS NOT NULL
          )
       OR (
            public.banking_pay_workbench_jobs.snapshot_run_id = v_session_row.source_snapshot_run_id
            AND public.banking_pay_workbench_jobs.candidate_id = ANY(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]))
          )
    ORDER BY public.banking_pay_workbench_jobs.updated_at_utc DESC, public.banking_pay_workbench_jobs.id DESC
    LIMIT 50
  ) AS recent_jobs;

  SELECT COALESCE(count(*), 0)::integer
  INTO v_active_job_count
  FROM public.banking_pay_workbench_jobs AS active_workbench_job
  WHERE active_workbench_job.status IN ('QUEUED', 'RUNNING')
    AND (
      active_workbench_job.session_id = p_session_id
      OR active_workbench_job.payload_json->>'session_id' = p_session_id::text
      OR active_workbench_job.id IN (
        SELECT session_candidate_state.pending_job_id
        FROM public.banking_pay_workbench_session_candidate_state AS session_candidate_state
        WHERE session_candidate_state.session_id = p_session_id
          AND session_candidate_state.pending_job_id IS NOT NULL
      )
      OR (
        active_workbench_job.snapshot_run_id = v_session_row.source_snapshot_run_id
        AND active_workbench_job.candidate_id = ANY(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]))
      )
    );

  v_total_count := coalesce(v_ready_count, 0) + coalesce(v_pending_count, 0) + coalesce(v_failed_count, 0);
  v_completed_count := coalesce(v_ready_count, 0) + coalesce(v_failed_count, 0);
  v_ready_flag := (coalesce(v_pending_count, 0) = 0 AND coalesce(v_failed_count, 0) = 0 AND COALESCE(v_active_job_count, 0) = 0);
  v_ready_empty := (v_ready_flag = true AND coalesce(v_total_count, 0) = 0);

  v_phase := CASE
    WHEN v_ready_flag THEN 'READY'
    WHEN coalesce(v_failed_count, 0) > 0 AND coalesce(v_pending_count, 0) = 0 THEN 'FAILED'
    WHEN coalesce(v_ready_count, 0) > 0 THEN 'PARTIAL_READY'
    ELSE 'REFRESHING_CANDIDATES'
  END;

  v_status_text := CASE
    WHEN v_ready_flag THEN 'Payment preview is ready.'
    WHEN coalesce(v_failed_count, 0) > 0 AND coalesce(v_pending_count, 0) = 0 THEN 'Payment preview could not be prepared for every candidate.'
    WHEN coalesce(v_pending_count, 0) > 0 THEN 'Preparing payment preview candidates.'
    ELSE 'Preparing payment preview.'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'session_status', v_session_row.status,
    'session_version', v_session_row.version,
    'ready_flag', v_ready_flag,
    'ready', v_ready_flag,
    'ready_empty', v_ready_empty,
    'total_count', v_total_count,
    'completed_count', v_completed_count,
    'ready_count', v_ready_count,
    'pending_count', v_pending_count,
    'failed_count', v_failed_count,
    'active_job_count', COALESCE(v_active_job_count, 0),
    'phase', v_phase,
    'status_text', v_status_text,
    'pending_candidate_ids', v_pending_candidate_ids_jsonb,
    'failed_candidate_ids', v_failed_candidate_ids_jsonb,
    'pending_job_ids', v_pending_job_ids_jsonb,
    'candidate_status_rows', v_candidate_statuses_jsonb,
    'candidate_statuses', v_candidate_statuses_jsonb,
    'recent_jobs', v_recent_jobs_jsonb
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_workbench_snapshot_rebuild_summary(
  p_snapshot_run_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_snapshot_run_row public.banking_pay_snapshot_runs%ROWTYPE;
  v_context_json jsonb := '{}'::jsonb;
  v_scope_candidate_ids_jsonb jsonb := '[]'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_payload_json jsonb := '{}'::jsonb;
  v_intended_scope_count integer := 0;
  v_state_row_count integer := 0;
  v_ready_count integer := 0;
  v_pending_count integer := 0;
  v_failed_count integer := 0;
  v_summary_json jsonb := '{}'::jsonb;
  v_paye_guardrails_json jsonb := '{}'::jsonb;
  v_last_error_json jsonb := NULL;
  v_status text := 'OPEN';
  v_audit_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'snapshot_run_id is required';
  END IF;

  SELECT public.banking_pay_snapshot_runs.*
  INTO v_snapshot_run_row
  FROM public.banking_pay_snapshot_runs
  WHERE public.banking_pay_snapshot_runs.id = p_snapshot_run_id
  FOR UPDATE;

  IF v_snapshot_run_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found', p_snapshot_run_id;
  END IF;

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_snapshot_run_row.pay_date,
    p_week_ending_cutoff => v_snapshot_run_row.week_ending_cutoff,
    p_actor_user_id => NULL::uuid,
    p_candidate_id => NULL::uuid,
    p_client_id => NULL::uuid,
    p_preview_decisions_json => NULL::jsonb
  );

  v_scope_candidate_ids_jsonb := CASE
    WHEN jsonb_typeof(v_context_json->'scope_candidate_ids') = 'array' THEN COALESCE(v_context_json->'scope_candidate_ids', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;
  v_intended_scope_count := jsonb_array_length(v_scope_candidate_ids_jsonb);

  SELECT COUNT(*)::integer
  INTO v_state_row_count
  FROM public.banking_pay_snapshot_candidate_state
  WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id;

  SELECT COUNT(*)::integer
  INTO v_ready_count
  FROM public.banking_pay_snapshot_candidate_state
  WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
    AND public.banking_pay_snapshot_candidate_state.status = 'READY';

  SELECT COUNT(*)::integer
  INTO v_pending_count
  FROM public.banking_pay_snapshot_candidate_state
  WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
    AND public.banking_pay_snapshot_candidate_state.status = 'PENDING';

  SELECT COUNT(*)::integer
  INTO v_failed_count
  FROM public.banking_pay_snapshot_candidate_state
  WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
    AND public.banking_pay_snapshot_candidate_state.status = 'FAILED';

  SELECT COALESCE(
           jsonb_agg(
             public.pay_preview_build_candidate_rollup(
               p_context_json => v_context_json,
               p_candidate_effective_json => COALESCE(public.banking_pay_snapshot_candidate_state.candidate_fragment_json, '{}'::jsonb)
             )
             ORDER BY public.banking_pay_snapshot_candidate_state.candidate_id
           ),
           '[]'::jsonb
         )
  INTO v_candidate_rollups_json
  FROM public.banking_pay_snapshot_candidate_state
  WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
    AND public.banking_pay_snapshot_candidate_state.status = 'READY';

  v_payload_json := public.pay_preview_assemble_payload(
    p_context_json => v_context_json,
    p_candidate_rollups_json => v_candidate_rollups_json
  );

  v_summary_json := CASE
    WHEN jsonb_typeof(v_payload_json->'summary') = 'object' THEN COALESCE(v_payload_json->'summary', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  v_paye_guardrails_json := CASE
    WHEN jsonb_typeof(v_payload_json->'paye_guardrails') = 'object' THEN COALESCE(v_payload_json->'paye_guardrails', '{}'::jsonb)
    ELSE '{}'::jsonb
  END;

  IF v_failed_count > 0 THEN
    SELECT jsonb_build_object(
      'failed_candidate_ids', COALESCE(
        (
          SELECT jsonb_agg(public.banking_pay_snapshot_candidate_state.candidate_id::text ORDER BY public.banking_pay_snapshot_candidate_state.candidate_id)
          FROM public.banking_pay_snapshot_candidate_state
          WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
            AND public.banking_pay_snapshot_candidate_state.status = 'FAILED'
        ),
        '[]'::jsonb
      ),
      'errors', COALESCE(
        (
          SELECT jsonb_agg(
            jsonb_build_object(
              'candidate_id', public.banking_pay_snapshot_candidate_state.candidate_id::text,
              'last_error_json', public.banking_pay_snapshot_candidate_state.last_error_json
            )
            ORDER BY public.banking_pay_snapshot_candidate_state.candidate_id
          )
          FROM public.banking_pay_snapshot_candidate_state
          WHERE public.banking_pay_snapshot_candidate_state.snapshot_run_id = p_snapshot_run_id
            AND public.banking_pay_snapshot_candidate_state.status = 'FAILED'
        ),
        '[]'::jsonb
      )
    )
    INTO v_last_error_json;

    v_status := 'FAILED';

    UPDATE public.banking_pay_snapshot_runs
    SET summary_json = v_summary_json,
        paye_guardrails_json = v_paye_guardrails_json,
        status = v_status,
        updated_at_utc = v_now,
        ready_at_utc = NULL,
        failed_at_utc = v_now,
        last_error_json = v_last_error_json
    WHERE public.banking_pay_snapshot_runs.id = p_snapshot_run_id;
  ELSIF v_pending_count = 0 AND v_state_row_count >= v_intended_scope_count THEN
    v_status := 'READY';

    UPDATE public.banking_pay_snapshot_runs
    SET summary_json = v_summary_json,
        paye_guardrails_json = v_paye_guardrails_json,
        status = v_status,
        updated_at_utc = v_now,
        ready_at_utc = v_now,
        failed_at_utc = NULL,
        last_error_json = NULL
    WHERE public.banking_pay_snapshot_runs.id = p_snapshot_run_id;
  ELSE
    v_status := 'OPEN';

    UPDATE public.banking_pay_snapshot_runs
    SET summary_json = v_summary_json,
        paye_guardrails_json = v_paye_guardrails_json,
        status = v_status,
        updated_at_utc = v_now,
        ready_at_utc = NULL,
        failed_at_utc = NULL,
        last_error_json = NULL
    WHERE public.banking_pay_snapshot_runs.id = p_snapshot_run_id;
  END IF;

  v_audit_after_json := jsonb_build_object(
    'snapshot_run_id', p_snapshot_run_id::text,
    'status', v_status,
    'intended_scope_count', v_intended_scope_count,
    'state_row_count', v_state_row_count,
    'ready_count', v_ready_count,
    'pending_count', v_pending_count,
    'failed_count', v_failed_count,
    'summary_json', v_summary_json,
    'paye_guardrails_json', v_paye_guardrails_json,
    'last_error_json', v_last_error_json
  );

  PERFORM public._audit_insert(
    'banking_pay_snapshot_run',
    p_snapshot_run_id::text,
    CASE WHEN v_status = 'FAILED' THEN 'SNAPSHOT_RUN_FAILED' WHEN v_status = 'READY' THEN 'SNAPSHOT_RUN_READY' ELSE 'SNAPSHOT_RUN_REBUILT' END,
    NULL,
    v_audit_after_json,
    'SNAPSHOT_REBUILD_SUMMARY',
    NULL::uuid
  );

  RETURN jsonb_build_object(
    'ok', true,
    'snapshot_run_id', p_snapshot_run_id::text,
    'status', v_status,
    'intended_scope_count', v_intended_scope_count,
    'state_row_count', v_state_row_count,
    'ready_count', v_ready_count,
    'pending_count', v_pending_count,
    'failed_count', v_failed_count,
    'summary', v_summary_json,
    'paye_guardrails', v_paye_guardrails_json,
    'last_error_json', v_last_error_json,
    'rebuilt_at_utc', v_now
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.pay_workbench_prepare_draft(uuid, uuid, jsonb, text, text, boolean, boolean, uuid, timestamptz);
DROP FUNCTION IF EXISTS public.pay_workbench_prepare_draft(uuid, uuid, jsonb, text, text, boolean, boolean, uuid, timestamptz, uuid, boolean, boolean);


DROP FUNCTION IF EXISTS public.pay_workbench_prepare_draft(uuid, uuid, jsonb, text, text, boolean, boolean, uuid, timestamptz);
DROP FUNCTION IF EXISTS public.pay_workbench_prepare_draft(uuid, uuid, jsonb, text, text, boolean, boolean, uuid, timestamptz, uuid, boolean, boolean);









CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft(
  p_session_id uuid,
  p_actor_user_id uuid,
  p_selected_preview_row_ids jsonb DEFAULT NULL::jsonb,
  p_pay_channel_scope text DEFAULT NULL::text,
  p_override_reason text DEFAULT NULL::text,
  p_override_continue boolean DEFAULT false,
  p_override_verified boolean DEFAULT false,
  p_override_verified_by_user_id uuid DEFAULT NULL::uuid,
  p_override_verified_at_utc timestamptz DEFAULT NULL::timestamptz,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_operation_mode boolean DEFAULT false,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_now timestamptz := now();
  v_scope_filter text := UPPER(BTRIM(COALESCE(p_pay_channel_scope, 'ALL')));
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_mode boolean := false;
  v_legacy_selected_preview_row_threshold integer := 250;
  v_selected_preview_row_ids_input jsonb := NULL;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_preview_row_count integer := 0;
  v_touched_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_touched_candidate_count integer := 0;
  v_pending_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_failed_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_stale_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_unresolved_selected_preview_row_count integer := 0;
  v_payee_blocked_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_payee_blocked_route_details_json jsonb := '[]'::jsonb;
  v_filter_candidate_id uuid := NULL::uuid;
  v_filter_client_id uuid := NULL::uuid;
  v_context_json jsonb := '{}'::jsonb;
  v_candidate_rollups_json jsonb := '[]'::jsonb;
  v_preview_payload_json jsonb := '{}'::jsonb;
  v_umbrella_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_paye_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_umbrella_selected_preview_row_count integer := 0;
  v_paye_selected_preview_row_count integer := 0;
  v_umbrella_build_result jsonb := '{}'::jsonb;
  v_paye_build_result jsonb := '{}'::jsonb;
  v_umbrella_pay_batch_id uuid := NULL::uuid;
  v_paye_pay_batch_id uuid := NULL::uuid;
  v_umbrella_status text := 'NOT_RUN';
  v_paye_status text := 'NOT_RUN';
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_paye_scope_blocked boolean := false;
  v_paye_block_reason_code text := NULL;
  v_paye_block_message text := NULL;
  v_paye_override_required boolean := false;
  v_paye_create_blocked boolean := false;
  v_has_any_scope_outcome boolean := false;
  v_enqueue_json jsonb := '{}'::jsonb;
  v_audit_after_json jsonb := '{}'::jsonb;
  v_hidden_recovery_templates_assembled_json jsonb := '[]'::jsonb;
  v_hidden_recovery_templates_passed_json jsonb := '[]'::jsonb;
  v_hidden_recovery_templates_source_count integer := 0;
  v_hidden_recovery_templates_assembled_count integer := 0;
  v_hidden_recovery_templates_passed_count integer := 0;
  v_hidden_manual_debt_source_by_candidate jsonb := '{}'::jsonb;
  v_hidden_manual_debt_passed_by_candidate jsonb := '{}'::jsonb;
  v_hidden_template_diagnostics jsonb := '{}'::jsonb;
  v_missing_manual_debt_template_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_projection_contract_json jsonb := '{}'::jsonb;
  v_required_projection_version integer := 0;
  v_required_hidden_recovery_template_projection_version integer := 0;
  v_requires_hidden_recovery_templates boolean := false;
  v_projection_stale_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_missing_manual_debt_template_source_candidate_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF v_scope_filter NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION 'pay_channel_scope must be ALL, PAYE, or UMBRELLA';
  END IF;

  PERFORM 1
  FROM public.tms_users
  WHERE public.tms_users.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT public.banking_pay_workbench_sessions.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions
  WHERE public.banking_pay_workbench_sessions.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  IF v_session_row.source_snapshot_run_id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is missing source_snapshot_run_id', p_session_id;
  END IF;

  PERFORM 1
  FROM public.banking_pay_snapshot_runs
  WHERE public.banking_pay_snapshot_runs.id = v_session_row.source_snapshot_run_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'banking_pay_snapshot_runs row % not found for session %', v_session_row.source_snapshot_run_id, p_session_id;
  END IF;

  v_operation_mode := (COALESCE(p_operation_mode, false) = true OR p_operation_id IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_ID_REQUIRED',
        'message', 'pay_workbench_prepare_draft operation mode requires p_operation_id.',
        'session_id', p_session_id::text
      )::text;
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_NOT_FOUND',
        'message', 'pay_workbench_prepare_draft operation mode could not find the supplied operation.',
        'session_id', p_session_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    IF v_operation_row.operation_type <> 'DRAFT_CREATE' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_TYPE_INVALID',
        'message', 'pay_workbench_prepare_draft operation mode requires a DRAFT_CREATE operation.',
        'session_id', p_session_id::text,
        'operation_id', p_operation_id::text,
        'operation_type', v_operation_row.operation_type
      )::text;
    END IF;

    IF v_operation_row.workbench_session_id IS NOT NULL AND v_operation_row.workbench_session_id <> p_session_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_SESSION_MISMATCH',
        'message', 'pay_workbench_prepare_draft operation belongs to a different workbench session.',
        'session_id', p_session_id::text,
        'operation_id', p_operation_id::text,
        'operation_workbench_session_id', v_operation_row.workbench_session_id::text
      )::text;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_ACTOR_MISMATCH',
        'message', 'pay_workbench_prepare_draft operation belongs to a different actor.',
        'session_id', p_session_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    UPDATE public.banking_pay_operations AS operation_update
    SET workbench_session_id = p_session_id,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id
      AND operation_update.workbench_session_id IS NULL;
  END IF;

  v_projection_contract_json := public._pay_workbench_candidate_projection_contract();
  v_required_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_required_hidden_recovery_template_projection_version := COALESCE(
    CASE
      WHEN COALESCE(v_projection_contract_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
        THEN (v_projection_contract_json->>'hidden_recovery_template_projection_version')::integer
      ELSE NULL::integer
    END,
    0
  );
  v_requires_hidden_recovery_templates := COALESCE(
    CASE
      WHEN lower(COALESCE(v_projection_contract_json->>'requires_hidden_recovery_templates', '')) IN ('true', 'false')
        THEN (v_projection_contract_json->>'requires_hidden_recovery_templates')::boolean
      ELSE NULL::boolean
    END,
    false
  );

  IF p_selected_preview_row_ids IS NOT NULL THEN
    IF jsonb_typeof(p_selected_preview_row_ids) <> 'array' THEN
      RAISE EXCEPTION 'selected_preview_row_ids must be a JSON array when supplied';
    END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
    INTO v_selected_preview_row_ids, v_selected_preview_row_count
    FROM (
      SELECT DISTINCT ON (raw_rows.preview_row_id)
        raw_rows.preview_row_id,
        raw_rows.ord
      FROM (
        SELECT BTRIM(selected_element.value) AS preview_row_id, selected_element.ord
        FROM jsonb_array_elements_text(p_selected_preview_row_ids) WITH ORDINALITY AS selected_element(value, ord)
        WHERE BTRIM(selected_element.value) <> ''
      ) AS raw_rows
      ORDER BY raw_rows.preview_row_id, raw_rows.ord
    ) AS selected_rows;

    IF v_selected_preview_row_count = 0 THEN
      RAISE EXCEPTION 'selected_preview_row_ids must contain at least one non-blank preview row id';
    END IF;

    UPDATE public.banking_pay_workbench_sessions
    SET server_selected_preview_row_ids = v_selected_preview_row_ids,
        server_selected_preview_row_ids_provided = true,
        updated_at_utc = v_now
    WHERE public.banking_pay_workbench_sessions.id = p_session_id;
  ELSE
    v_selected_preview_row_ids_input := CASE
      WHEN COALESCE(v_session_row.server_selected_preview_row_ids_provided, false)
           AND jsonb_typeof(COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
        THEN COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb)
      ELSE '[]'::jsonb
    END;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
    INTO v_selected_preview_row_ids, v_selected_preview_row_count
    FROM (
      SELECT DISTINCT ON (raw_rows.preview_row_id)
        raw_rows.preview_row_id,
        raw_rows.ord
      FROM (
        SELECT BTRIM(selected_element.value) AS preview_row_id, selected_element.ord
        FROM jsonb_array_elements_text(v_selected_preview_row_ids_input) WITH ORDINALITY AS selected_element(value, ord)
        WHERE BTRIM(selected_element.value) <> ''
      ) AS raw_rows
      ORDER BY raw_rows.preview_row_id, raw_rows.ord
    ) AS selected_rows;
  END IF;

  IF v_selected_preview_row_count = 0 THEN
    RAISE EXCEPTION 'No server-selected preview rows are available for session %', p_session_id;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_requested_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_requested_rows (
    preview_row_id text PRIMARY KEY,
    ord bigint NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_workbench_prepare_requested_rows(preview_row_id, ord)
  SELECT requested_rows.preview_row_id, requested_rows.ord
  FROM (
    SELECT DISTINCT ON (raw_rows.preview_row_id)
      raw_rows.preview_row_id,
      raw_rows.ord
    FROM (
      SELECT BTRIM(selected_element.value) AS preview_row_id, selected_element.ord
      FROM jsonb_array_elements_text(v_selected_preview_row_ids) WITH ORDINALITY AS selected_element(value, ord)
      WHERE BTRIM(selected_element.value) <> ''
    ) AS raw_rows
    ORDER BY raw_rows.preview_row_id, raw_rows.ord
  ) AS requested_rows;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state AS
  WITH session_candidate_rows AS (
    SELECT
      public.banking_pay_workbench_session_candidate_state.candidate_id,
      public.banking_pay_workbench_session_candidate_state.status,
      public.banking_pay_workbench_session_candidate_state.effective_canonical_preview_lines_json
    FROM public.banking_pay_workbench_session_candidate_state
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
  ),
  exploded_lines AS (
    SELECT
      session_candidate_rows.candidate_id,
      session_candidate_rows.status,
      BTRIM(COALESCE(
        line_element.value->>'preview_row_id',
        line_element.value->>'line_id',
        line_element.value->>'row_id',
        line_element.value->>'id',
        ''
      )) AS preview_row_id,
      UPPER(BTRIM(COALESCE(line_element.value->>'pay_channel', ''))) AS pay_channel
    FROM session_candidate_rows
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(session_candidate_rows.effective_canonical_preview_lines_json) = 'array' THEN COALESCE(session_candidate_rows.effective_canonical_preview_lines_json, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS line_element(value)
    WHERE jsonb_typeof(line_element.value) = 'object'
  )
  SELECT
    exploded_lines.preview_row_id,
    exploded_lines.candidate_id,
    exploded_lines.status,
    exploded_lines.pay_channel,
    requested_rows.ord
  FROM exploded_lines
  JOIN pg_temp.tmp_pay_workbench_prepare_requested_rows requested_rows
    ON requested_rows.preview_row_id = exploded_lines.preview_row_id
  WHERE exploded_lines.preview_row_id <> ''
    AND exploded_lines.pay_channel IN ('PAYE', 'UMBRELLA');

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_selected_rows;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_selected_rows AS
  WITH ready_candidate_rows AS (
    SELECT
      public.banking_pay_workbench_session_candidate_state.candidate_id,
      public.banking_pay_workbench_session_candidate_state.effective_canonical_preview_lines_json,
      public.banking_pay_workbench_session_candidate_state.effective_payees_json,
      public.banking_pay_workbench_session_candidate_state.source_change_seq
    FROM public.banking_pay_workbench_session_candidate_state
    WHERE public.banking_pay_workbench_session_candidate_state.session_id = p_session_id
      AND public.banking_pay_workbench_session_candidate_state.status = 'READY'
  ),
  exploded_lines AS (
    SELECT
      ready_candidate_rows.candidate_id,
      ready_candidate_rows.source_change_seq,
      line_element.value AS line_json,
      BTRIM(COALESCE(
        line_element.value->>'preview_row_id',
        line_element.value->>'line_id',
        line_element.value->>'row_id',
        line_element.value->>'id',
        ''
      )) AS preview_row_id,
      UPPER(BTRIM(COALESCE(line_element.value->>'pay_channel', ''))) AS pay_channel
    FROM ready_candidate_rows
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(ready_candidate_rows.effective_canonical_preview_lines_json) = 'array' THEN COALESCE(ready_candidate_rows.effective_canonical_preview_lines_json, '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS line_element(value)
    WHERE jsonb_typeof(line_element.value) = 'object'
  )
  SELECT
    exploded_lines.preview_row_id,
    exploded_lines.candidate_id,
    exploded_lines.pay_channel,
    exploded_lines.line_json,
    requested_rows.ord,
    exploded_lines.source_change_seq
  FROM exploded_lines
  JOIN pg_temp.tmp_pay_workbench_prepare_requested_rows requested_rows
    ON requested_rows.preview_row_id = exploded_lines.preview_row_id
  WHERE exploded_lines.preview_row_id <> ''
    AND exploded_lines.pay_channel IN ('PAYE', 'UMBRELLA')
    AND (v_scope_filter = 'ALL' OR exploded_lines.pay_channel = v_scope_filter);

  SELECT COUNT(*)::integer
  INTO v_unresolved_selected_preview_row_count
  FROM pg_temp.tmp_pay_workbench_prepare_requested_rows AS requested_rows
  LEFT JOIN (
    SELECT DISTINCT pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.preview_row_id
    FROM pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state
  ) AS resolved_rows
    ON resolved_rows.preview_row_id = requested_rows.preview_row_id
  WHERE resolved_rows.preview_row_id IS NULL;

  IF v_unresolved_selected_preview_row_count > 0 THEN
    RAISE EXCEPTION 'Selected preview rows did not resolve against session state for session %', p_session_id;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.candidate_id ORDER BY pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.candidate_id), ARRAY[]::uuid[])
  INTO v_pending_candidate_ids
  FROM pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state
  WHERE pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.status = 'PENDING'
    AND (v_scope_filter = 'ALL' OR pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.pay_channel = v_scope_filter);

  IF COALESCE(array_length(v_pending_candidate_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'Cannot prepare draft while touched candidates are pending: %', array_to_string(v_pending_candidate_ids, ',');
  END IF;

  SELECT COALESCE(array_agg(DISTINCT pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.candidate_id ORDER BY pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.candidate_id), ARRAY[]::uuid[])
  INTO v_failed_candidate_ids
  FROM pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state
  WHERE pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.status = 'FAILED'
    AND (v_scope_filter = 'ALL' OR pg_temp.tmp_pay_workbench_prepare_requested_rows_any_state.pay_channel = v_scope_filter);

  IF COALESCE(array_length(v_failed_candidate_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'Cannot prepare draft while touched candidates are failed: %', array_to_string(v_failed_candidate_ids, ',');
  END IF;

  IF (SELECT COUNT(*)::integer FROM pg_temp.tmp_pay_workbench_prepare_selected_rows) = 0 THEN
    RAISE EXCEPTION 'No selected preview rows are available in READY session state for session % and scope %', p_session_id, v_scope_filter;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT pg_temp.tmp_pay_workbench_prepare_selected_rows.candidate_id ORDER BY pg_temp.tmp_pay_workbench_prepare_selected_rows.candidate_id), ARRAY[]::uuid[])
  INTO v_touched_candidate_ids
  FROM pg_temp.tmp_pay_workbench_prepare_selected_rows;

  v_touched_candidate_count := COALESCE(array_length(v_touched_candidate_ids, 1), 0);

  IF v_touched_candidate_count = 0 THEN
    RAISE EXCEPTION 'No touched candidates resolved from selected preview rows for session %', p_session_id;
  END IF;

  SELECT COALESCE(array_agg(stale_rows.candidate_id ORDER BY stale_rows.candidate_id), ARRAY[]::uuid[])
  INTO v_stale_candidate_ids
  FROM (
    SELECT DISTINCT session_candidate.candidate_id
    FROM public.banking_pay_workbench_session_candidate_state AS session_candidate
    LEFT JOIN public.app_change_counters AS app_counter
      ON app_counter.entity_key = 'pay_candidate:' || session_candidate.candidate_id::text
    WHERE session_candidate.session_id = p_session_id
      AND session_candidate.candidate_id = ANY(v_touched_candidate_ids)
      AND session_candidate.status = 'READY'
      AND COALESCE(session_candidate.source_change_seq, 0) <> COALESCE(app_counter.seq, 0)
  ) AS stale_rows;

  SELECT COALESCE(array_agg(projection_stale_rows.candidate_id ORDER BY projection_stale_rows.candidate_id), ARRAY[]::uuid[])
  INTO v_projection_stale_candidate_ids
  FROM (
    SELECT DISTINCT session_candidate.candidate_id
    FROM public.banking_pay_workbench_session_candidate_state AS session_candidate
    JOIN public.banking_pay_snapshot_candidate_state AS snapshot_candidate
      ON snapshot_candidate.snapshot_run_id = v_session_row.source_snapshot_run_id
     AND snapshot_candidate.candidate_id = session_candidate.candidate_id
    WHERE session_candidate.session_id = p_session_id
      AND session_candidate.candidate_id = ANY(v_touched_candidate_ids)
      AND session_candidate.status = 'READY'
      AND (
        COALESCE(
          CASE
            WHEN COALESCE(session_candidate.effective_candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
              THEN (session_candidate.effective_candidate_fragment_json->>'projection_version')::integer
            ELSE NULL::integer
          END,
          0
        ) < v_required_projection_version
        OR COALESCE(
             CASE
               WHEN COALESCE(snapshot_candidate.candidate_fragment_json->>'projection_version', '') ~ '^[0-9]+$'
                 THEN (snapshot_candidate.candidate_fragment_json->>'projection_version')::integer
               ELSE NULL::integer
             END,
             0
           ) < v_required_projection_version
        OR (
          v_requires_hidden_recovery_templates = true
          AND COALESCE(
                CASE
                  WHEN COALESCE(session_candidate.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
                    THEN (session_candidate.effective_candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
                  ELSE NULL::integer
                END,
                0
              ) < v_required_hidden_recovery_template_projection_version
        )
        OR (
          v_requires_hidden_recovery_templates = true
          AND COALESCE(
                CASE
                  WHEN COALESCE(snapshot_candidate.candidate_fragment_json->>'hidden_recovery_template_projection_version', '') ~ '^[0-9]+$'
                    THEN (snapshot_candidate.candidate_fragment_json->>'hidden_recovery_template_projection_version')::integer
                  ELSE NULL::integer
                END,
                0
              ) < v_required_hidden_recovery_template_projection_version
        )
        OR COALESCE(session_candidate.last_recomputed_at_utc, '-infinity'::timestamptz) < COALESCE(snapshot_candidate.last_refreshed_at_utc, '-infinity'::timestamptz)
      )
  ) AS projection_stale_rows;

  IF COALESCE(array_length(v_stale_candidate_ids, 1), 0) > 0 OR COALESCE(array_length(v_projection_stale_candidate_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'WORKBENCH_SESSION_CANDIDATE_PROJECTION_STALE: touched candidate session state must be refreshed before draft creation: %',
      array_to_string(
        ARRAY(
          SELECT DISTINCT stale_candidate_id
          FROM unnest(COALESCE(v_stale_candidate_ids, ARRAY[]::uuid[]) || COALESCE(v_projection_stale_candidate_ids, ARRAY[]::uuid[])) AS stale_candidate_id
          ORDER BY stale_candidate_id
        ),
        ','
      );
  END IF;

  SELECT COALESCE(array_agg(missing_rows.candidate_id ORDER BY missing_rows.candidate_id), ARRAY[]::uuid[])
  INTO v_missing_manual_debt_template_source_candidate_ids
  FROM (
    SELECT DISTINCT selected_rows.candidate_id
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_rows
    JOIN public.banking_pay_workbench_session_candidate_state AS session_candidate
      ON session_candidate.session_id = p_session_id
     AND session_candidate.candidate_id = selected_rows.candidate_id
    WHERE selected_rows.pay_channel = 'PAYE'
      AND UPPER(COALESCE(selected_rows.line_json->>'line_type', '')) = 'MANUAL_DEBT_RECOVERY'
      AND UPPER(COALESCE(selected_rows.line_json->>'paye_treatment', '')) = 'NET_DEDUCT'
      AND NULLIF(BTRIM(COALESCE(selected_rows.line_json->>'finance_case_id', '')), '') IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(
          CASE
            WHEN jsonb_typeof(session_candidate.effective_candidate_fragment_json->'hidden_recovery_template_lines') = 'array' THEN COALESCE(session_candidate.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        ) AS hidden_tpl(value)
        WHERE jsonb_typeof(hidden_tpl.value) = 'object'
          AND UPPER(COALESCE(hidden_tpl.value->>'recovery_family', '')) = 'MANUAL_DEBT_RECOVERY'
          AND UPPER(COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'pay_channel', '')), ''), 'PAYE')) = 'PAYE'
          AND COALESCE(NULLIF(BTRIM(COALESCE(hidden_tpl.value->>'finance_case_id', '')), ''), '') = COALESCE(NULLIF(BTRIM(COALESCE(selected_rows.line_json->>'finance_case_id', '')), ''), '')
      )
  ) AS missing_rows;

  IF COALESCE(array_length(v_missing_manual_debt_template_source_candidate_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'MANUAL_DEBT_TEMPLATE_SOURCE_MISSING_FOR_SELECTED_PAYE_CANDIDATE: selected PAYE manual-debt rows are missing hidden template source for candidates %',
      array_to_string(v_missing_manual_debt_template_source_candidate_ids, ',');
  END IF;

  WITH required_payee_routes AS (
    SELECT DISTINCT
      selected_rows.candidate_id,
      selected_rows.pay_channel,
      CASE
        WHEN selected_rows.pay_channel = 'PAYE' THEN 'CANDIDATE'
        WHEN selected_rows.pay_channel = 'UMBRELLA' THEN 'UMBRELLA'
        ELSE NULL::text
      END AS required_payee_entity_kind,
      CASE
        WHEN selected_rows.pay_channel = 'PAYE' THEN selected_rows.candidate_id
        WHEN selected_rows.pay_channel = 'UMBRELLA' THEN route_candidate.umbrella_id
        ELSE NULL::uuid
      END AS required_payee_entity_id
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_rows
    JOIN public.candidates AS route_candidate
      ON route_candidate.id = selected_rows.candidate_id
    JOIN public.banking_pay_workbench_session_candidate_state AS session_candidate
      ON session_candidate.session_id = p_session_id
     AND session_candidate.candidate_id = selected_rows.candidate_id
     AND session_candidate.status = 'READY'
    WHERE selected_rows.pay_channel IN ('PAYE', 'UMBRELLA')
  ),
  route_payee_matches AS (
    SELECT
      required_routes.candidate_id,
      required_routes.pay_channel,
      required_routes.required_payee_entity_kind,
      required_routes.required_payee_entity_id,
      matched_payee.payee_json
    FROM required_payee_routes AS required_routes
    JOIN public.banking_pay_workbench_session_candidate_state AS session_candidate
      ON session_candidate.session_id = p_session_id
     AND session_candidate.candidate_id = required_routes.candidate_id
     AND session_candidate.status = 'READY'
    LEFT JOIN LATERAL (
      SELECT payee_element.value AS payee_json
      FROM jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(session_candidate.effective_payees_json) = 'array' THEN COALESCE(session_candidate.effective_payees_json, '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS payee_element(value)
      WHERE jsonb_typeof(payee_element.value) = 'object'
        AND UPPER(BTRIM(COALESCE(payee_element.value->>'payee_entity_kind', ''))) = required_routes.required_payee_entity_kind
        AND (
          CASE
            WHEN BTRIM(COALESCE(payee_element.value->>'payee_entity_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN BTRIM(COALESCE(payee_element.value->>'payee_entity_id', ''))::uuid
            ELSE NULL::uuid
          END
        ) IS NOT DISTINCT FROM required_routes.required_payee_entity_id
      ORDER BY
        CASE
          WHEN EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE
                WHEN jsonb_typeof(payee_element.value->'blockers') = 'array' THEN COALESCE(payee_element.value->'blockers', '[]'::jsonb)
                ELSE '[]'::jsonb
              END
            ) AS blocker_element(value)
            WHERE UPPER(BTRIM(blocker_element.value)) IN ('BLOCKED_NAME_CHECK', 'BLOCKED_NO_PAYEE_MAP', 'BLOCKED_BANK_DETAILS', 'BLOCKED_UMBRELLA_INACTIVE')
          ) THEN 1
          ELSE 0
        END,
        BTRIM(COALESCE(payee_element.value->>'payee_name', '')),
        BTRIM(COALESCE(payee_element.value->>'payee_entity_id', ''))
      LIMIT 1
    ) AS matched_payee
      ON true
  ),
  failed_payee_routes AS (
    SELECT
      route_matches.candidate_id,
      route_matches.pay_channel,
      route_matches.required_payee_entity_kind,
      route_matches.required_payee_entity_id,
      route_matches.payee_json,
      CASE
        WHEN route_matches.required_payee_entity_kind IS NULL THEN 'REQUIRED_PAYEE_ROUTE_KIND_MISSING'
        WHEN route_matches.required_payee_entity_id IS NULL THEN 'REQUIRED_PAYEE_ROUTE_ID_MISSING'
        WHEN route_matches.payee_json IS NULL THEN 'REQUIRED_PAYEE_ROUTE_NOT_FOUND'
        WHEN EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(
            CASE
              WHEN jsonb_typeof(route_matches.payee_json->'blockers') = 'array' THEN COALESCE(route_matches.payee_json->'blockers', '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          ) AS blocker_element(value)
          WHERE UPPER(BTRIM(blocker_element.value)) IN ('BLOCKED_NAME_CHECK', 'BLOCKED_NO_PAYEE_MAP', 'BLOCKED_BANK_DETAILS', 'BLOCKED_UMBRELLA_INACTIVE')
        ) THEN 'REQUIRED_PAYEE_ROUTE_BLOCKED'
        ELSE NULL::text
      END AS failure_reason
    FROM route_payee_matches AS route_matches
  )
  SELECT
    COALESCE(array_agg(DISTINCT failed_routes.candidate_id ORDER BY failed_routes.candidate_id), ARRAY[]::uuid[]),
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'candidate_id', failed_routes.candidate_id::text,
          'selected_pay_channel', failed_routes.pay_channel,
          'required_payee_entity_kind', failed_routes.required_payee_entity_kind,
          'required_payee_entity_id', CASE WHEN failed_routes.required_payee_entity_id IS NULL THEN NULL ELSE failed_routes.required_payee_entity_id::text END,
          'failure_reason', failed_routes.failure_reason,
          'matched_payee_entity_kind', CASE WHEN failed_routes.payee_json IS NULL THEN NULL ELSE failed_routes.payee_json->>'payee_entity_kind' END,
          'matched_payee_entity_id', CASE WHEN failed_routes.payee_json IS NULL THEN NULL ELSE failed_routes.payee_json->>'payee_entity_id' END,
          'matched_payee_name', CASE WHEN failed_routes.payee_json IS NULL THEN NULL ELSE failed_routes.payee_json->>'payee_name' END,
          'matched_blockers', CASE
            WHEN failed_routes.payee_json IS NULL THEN '[]'::jsonb
            WHEN jsonb_typeof(failed_routes.payee_json->'blockers') = 'array' THEN COALESCE(failed_routes.payee_json->'blockers', '[]'::jsonb)
            ELSE '[]'::jsonb
          END
        )
        ORDER BY
          failed_routes.candidate_id,
          failed_routes.pay_channel,
          failed_routes.required_payee_entity_kind,
          failed_routes.required_payee_entity_id::text
      ),
      '[]'::jsonb
    )
  INTO v_payee_blocked_candidate_ids, v_payee_blocked_route_details_json
  FROM failed_payee_routes AS failed_routes
  WHERE failed_routes.failure_reason IS NOT NULL;

  IF COALESCE(array_length(v_payee_blocked_candidate_ids, 1), 0) > 0 THEN
    FOR v_filter_candidate_id IN
      SELECT blocked_candidate_id
      FROM unnest(v_payee_blocked_candidate_ids) AS blocked_candidate_id
    LOOP
      SELECT public.pay_workbench_enqueue_payee_readiness_ensure(
        p_candidate_id => v_filter_candidate_id,
        p_payees_json => COALESCE((
          SELECT jsonb_agg(payee_element.value ORDER BY payee_element.ord)
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(COALESCE(session_candidate.effective_payees_json, '[]'::jsonb)) = 'array' THEN COALESCE(session_candidate.effective_payees_json, '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          ) WITH ORDINALITY AS payee_element(value, ord)
          WHERE jsonb_typeof(payee_element.value) = 'object'
            AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(
                CASE
                  WHEN jsonb_typeof(COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)) = 'array' THEN COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)
                  ELSE '[]'::jsonb
                END
              ) AS blocked_route(route_json)
              WHERE jsonb_typeof(blocked_route.route_json) = 'object'
                AND NOT EXISTS (
                  SELECT 1
                  FROM jsonb_array_elements_text(
                    CASE
                      WHEN jsonb_typeof(blocked_route.route_json->'matched_blockers') = 'array' THEN COALESCE(blocked_route.route_json->'matched_blockers', '[]'::jsonb)
                      ELSE '[]'::jsonb
                    END
                  ) AS inactive_blocker_element(value)
                  WHERE UPPER(BTRIM(inactive_blocker_element.value)) = 'BLOCKED_UMBRELLA_INACTIVE'
                )
                AND blocked_route.route_json->>'candidate_id' = v_filter_candidate_id::text
                AND (
                  CASE
                    WHEN UPPER(BTRIM(COALESCE(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', ''))) = 'UMBRELLA_COMPANY' THEN 'UMBRELLA'
                    ELSE UPPER(BTRIM(COALESCE(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', '')))
                  END
                ) = UPPER(BTRIM(COALESCE(blocked_route.route_json->>'required_payee_entity_kind', '')))
                AND (
                  NULLIF(BTRIM(COALESCE(blocked_route.route_json->>'required_payee_entity_id', '')), '') IS NULL
                  OR (
                    BTRIM(COALESCE(blocked_route.route_json->>'required_payee_entity_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    AND BTRIM(COALESCE(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    AND BTRIM(COALESCE(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', ''))::uuid = BTRIM(COALESCE(blocked_route.route_json->>'required_payee_entity_id', ''))::uuid
                  )
                )
            )
        ), '[]'::jsonb),
        p_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_session_id => p_session_id,
        p_reason => 'WORKBENCH_PREPARE_DRAFT',
        p_actor_user_id => p_actor_user_id,
        p_payload_json => jsonb_build_object(
          'session_id', p_session_id::text,
          'candidate_id', v_filter_candidate_id::text,
          'requested_scope', v_scope_filter,
          'selected_route_failures', COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)
        )
      )
      INTO v_enqueue_json
      FROM public.banking_pay_workbench_session_candidate_state AS session_candidate
      WHERE session_candidate.session_id = p_session_id
        AND session_candidate.candidate_id = v_filter_candidate_id
        AND EXISTS (
          SELECT 1
          FROM jsonb_array_elements(
            CASE
              WHEN jsonb_typeof(COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)) = 'array' THEN COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)
              ELSE '[]'::jsonb
            END
          ) AS blocked_route(route_json)
          WHERE jsonb_typeof(blocked_route.route_json) = 'object'
            AND blocked_route.route_json->>'candidate_id' = v_filter_candidate_id::text
            AND NOT EXISTS (
              SELECT 1
              FROM jsonb_array_elements_text(
                CASE
                  WHEN jsonb_typeof(blocked_route.route_json->'matched_blockers') = 'array' THEN COALESCE(blocked_route.route_json->'matched_blockers', '[]'::jsonb)
                  ELSE '[]'::jsonb
                END
              ) AS inactive_blocker_element(value)
              WHERE UPPER(BTRIM(inactive_blocker_element.value)) = 'BLOCKED_UMBRELLA_INACTIVE'
            )
        )
      LIMIT 1;
    END LOOP;

    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT',
      'code', 'SELECTED_PAYEE_ROUTE_NOT_READY',
      'message', 'Selected payment routes are not payee-ready and must be refreshed before draft creation.',
      'session_id', p_session_id::text,
      'requested_scope', v_scope_filter,
      'candidate_ids', to_jsonb(COALESCE(v_payee_blocked_candidate_ids, ARRAY[]::uuid[])),
      'route_failures', COALESCE(v_payee_blocked_route_details_json, '[]'::jsonb)
    )::text;
  END IF;


  SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
  INTO v_umbrella_selected_preview_row_ids, v_umbrella_selected_preview_row_count
  FROM (
    SELECT DISTINCT ON (pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id)
      pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id,
      pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows
    WHERE pg_temp.tmp_pay_workbench_prepare_selected_rows.pay_channel = 'UMBRELLA'
    ORDER BY pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id, pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
  ) AS selected_rows;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
  INTO v_paye_selected_preview_row_ids, v_paye_selected_preview_row_count
  FROM (
    SELECT DISTINCT ON (pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id)
      pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id,
      pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows
    WHERE pg_temp.tmp_pay_workbench_prepare_selected_rows.pay_channel = 'PAYE'
    ORDER BY pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id, pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
  ) AS selected_rows;

  IF v_scope_filter IN ('ALL', 'PAYE') AND v_paye_selected_preview_row_count > 0 THEN
    PERFORM pg_advisory_xact_lock(94201, 1);

    v_paye_guardrails := public.pay_paye_guardrails(
      p_pay_date => v_session_row.pay_date,
      p_ignore_pay_batch_id => NULL::uuid,
      p_actor_user_id => p_actor_user_id
    );

    v_paye_create_blocked := COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false);
    v_paye_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

    IF v_paye_create_blocked THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_EXISTING_PAYE_DRAFT';
      v_paye_block_reason_code := 'PAYE_DRAFT_ALREADY_EXISTS';
      v_paye_block_message := COALESCE(
        v_paye_guardrails #>> '{ui,existing_draft_block,message}',
        'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.'
      );
    ELSIF v_paye_override_required THEN
      IF NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NULL THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_REASON_REQUIRED';
        v_paye_block_message := 'A same-week PAYE override reason is required before creating another PAYE batch in the same Monday-based payroll week.';
      ELSIF COALESCE(p_override_continue, false) = false THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_CONTINUE_REQUIRED';
        v_paye_block_message := 'Explicit continuation is required before creating another PAYE batch in the same Monday-based payroll week.';
      ELSIF COALESCE(p_override_verified, false) = false THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFICATION_REQUIRED';
        v_paye_block_message := 'Valid password reauthentication and 2FA verification are required before creating another PAYE batch in the same Monday-based payroll week.';
      ELSIF p_override_verified_by_user_id IS NULL THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_REQUIRED';
        v_paye_block_message := 'The verified override user id is required for same-week PAYE override.';
      ELSIF p_override_verified_by_user_id <> p_actor_user_id THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_MISMATCH';
        v_paye_block_message := 'The same-week PAYE override verification must belong to the current actor user.';
      ELSIF p_override_verified_at_utc IS NULL THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
        v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_AT_REQUIRED';
        v_paye_block_message := 'The verification timestamp is required for same-week PAYE override.';
      END IF;
    END IF;
  END IF;

  IF v_operation_mode THEN
    IF v_scope_filter IN ('ALL', 'UMBRELLA') THEN
      IF v_umbrella_selected_preview_row_count > 0 THEN
        v_umbrella_status := 'VALIDATED_READY';
      ELSE
        v_umbrella_status := 'NOTHING_RELEVANT';
      END IF;
    ELSE
      v_umbrella_status := 'NOT_RUN';
    END IF;

    IF v_scope_filter IN ('ALL', 'PAYE') THEN
      IF v_paye_selected_preview_row_count > 0 THEN
        IF v_paye_scope_blocked = false THEN
          v_paye_status := 'VALIDATED_READY';
        END IF;
      ELSE
        v_paye_status := 'NOTHING_RELEVANT';
      END IF;
    ELSE
      v_paye_status := 'NOT_RUN';
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'session_id', p_session_id::text,
      'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
      'session_version', v_session_row.version,
      'pay_date', CASE WHEN v_session_row.pay_date IS NULL THEN NULL ELSE v_session_row.pay_date::text END,
      'week_ending_cutoff', CASE WHEN v_session_row.week_ending_cutoff IS NULL THEN NULL ELSE v_session_row.week_ending_cutoff::text END,
      'pay_channel_scope', v_scope_filter,
      'selected_preview_row_count', v_selected_preview_row_count,
      'selected_preview_row_ids', v_selected_preview_row_ids,
      'touched_candidate_count', v_touched_candidate_count,
      'touched_candidate_ids', COALESCE(to_jsonb(v_touched_candidate_ids), '[]'::jsonb),
      'candidate_ready_count', v_touched_candidate_count,
      'unresolved_selected_preview_row_count', v_unresolved_selected_preview_row_count,
      'payee_readiness', jsonb_build_object(
        'blocked_candidate_count', COALESCE(array_length(v_payee_blocked_candidate_ids, 1), 0),
        'blocked_candidate_ids', COALESCE(to_jsonb(v_payee_blocked_candidate_ids), '[]'::jsonb),
        'route_details', v_payee_blocked_route_details_json
      ),
      'same_week_paye_override', jsonb_build_object(
        'guardrails', COALESCE(v_paye_guardrails, '{}'::jsonb),
        'create_blocked', v_paye_create_blocked,
        'override_required', v_paye_override_required,
        'scope_blocked', v_paye_scope_blocked,
        'block_reason_code', v_paye_block_reason_code,
        'block_message', v_paye_block_message,
        'override_reason_present', (NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NOT NULL),
        'override_continue', COALESCE(p_override_continue, false),
        'override_verified', COALESCE(p_override_verified, false),
        'override_verified_by_user_id', CASE WHEN p_override_verified_by_user_id IS NULL THEN NULL ELSE p_override_verified_by_user_id::text END,
        'override_verified_at_utc', CASE WHEN p_override_verified_at_utc IS NULL THEN NULL ELSE p_override_verified_at_utc::text END
      ),
      'scopes', jsonb_build_object(
        'umbrella', jsonb_build_object(
          'status', v_umbrella_status,
          'selected_preview_row_count', v_umbrella_selected_preview_row_count,
          'selected_preview_row_ids', v_umbrella_selected_preview_row_ids
        ),
        'paye', jsonb_build_object(
          'status', v_paye_status,
          'selected_preview_row_count', v_paye_selected_preview_row_count,
          'selected_preview_row_ids', v_paye_selected_preview_row_ids,
          'blocked', v_paye_scope_blocked,
          'block_reason_code', v_paye_block_reason_code,
          'block_message', v_paye_block_message
        )
      ),
      'next_phase', CASE WHEN v_paye_scope_blocked THEN 'AWAIT_SAME_WEEK_PAYE_OVERRIDE' ELSE 'SEED_CANDIDATE_SCOPE' END,
      'message', CASE WHEN v_paye_scope_blocked THEN v_paye_block_message ELSE 'Workbench draft validation passed. Continue with operation-scoped draft creation.' END
    );
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) = false THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_REQUIRED',
      'message', 'pay_workbench_prepare_draft refused legacy all-at-once draft creation. Normal draft creation must use the scalable DRAFT_CREATE operation flow; set p_allow_legacy_unchunked only for explicit small diagnostic/test compatibility.',
      'session_id', p_session_id::text,
      'selected_preview_row_count', v_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_selected_preview_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF v_selected_preview_row_count > v_legacy_selected_preview_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_WORKBENCH_PREPARE_DRAFT_OPERATION_REQUIRED',
      'message', 'pay_workbench_prepare_draft refused legacy all-at-once draft creation for a large selection. Use the scalable DRAFT_CREATE operation flow.',
      'session_id', p_session_id::text,
      'selected_preview_row_count', v_selected_preview_row_count,
      'safe_legacy_threshold', v_legacy_selected_preview_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_candidate_id := COALESCE(v_session_row.filters_json->>'candidate_id', v_session_row.filters_json->>'candidateId')::uuid;
  ELSE
    v_filter_candidate_id := NULL::uuid;
  END IF;

  IF BTRIM(COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
    v_filter_client_id := COALESCE(v_session_row.filters_json->>'client_id', v_session_row.filters_json->>'clientId')::uuid;
  ELSE
    v_filter_client_id := NULL::uuid;
  END IF;

  v_context_json := public.pay_preview_build_context(
    p_pay_date => v_session_row.pay_date,
    p_week_ending_cutoff => v_session_row.week_ending_cutoff,
    p_actor_user_id => p_actor_user_id,
    p_candidate_id => v_filter_candidate_id,
    p_client_id => v_filter_client_id,
    p_preview_decisions_json => NULL::jsonb
  );

  SELECT COALESCE(
           jsonb_agg(
             public.pay_preview_build_candidate_rollup(
               p_context_json => v_context_json,
               p_candidate_effective_json => COALESCE(session_candidate.effective_candidate_fragment_json, '{}'::jsonb)
             )
             ORDER BY session_candidate.candidate_id
           ),
           '[]'::jsonb
         )
  INTO v_candidate_rollups_json
  FROM public.banking_pay_workbench_session_candidate_state AS session_candidate
  WHERE session_candidate.session_id = p_session_id
    AND session_candidate.candidate_id = ANY(v_touched_candidate_ids)
    AND session_candidate.status = 'READY';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_hidden_templates_source;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_hidden_templates_source (
    candidate_id uuid NOT NULL,
    finance_case_id uuid NOT NULL,
    recovery_family text NOT NULL,
    finance_component_id uuid NULL,
    source_ref text NULL,
    pay_channel text NULL,
    sort_order integer NOT NULL,
    template_json jsonb NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_workbench_prepare_hidden_templates_source (
    candidate_id,
    finance_case_id,
    recovery_family,
    finance_component_id,
    source_ref,
    pay_channel,
    sort_order,
    template_json
  )
  SELECT DISTINCT ON (
    source_rows.candidate_id,
    source_rows.recovery_family,
    source_rows.finance_case_id,
    COALESCE(source_rows.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(source_rows.source_ref, ''),
    COALESCE(source_rows.pay_channel, '')
  )
    source_rows.candidate_id,
    source_rows.finance_case_id,
    source_rows.recovery_family,
    source_rows.finance_component_id,
    source_rows.source_ref,
    source_rows.pay_channel,
    source_rows.sort_order,
    source_rows.template_json
  FROM (
    SELECT
      parsed_rows.candidate_id,
      parsed_rows.finance_case_id,
      parsed_rows.recovery_family,
      parsed_rows.finance_component_id,
      parsed_rows.source_ref,
      parsed_rows.pay_channel,
      parsed_rows.sort_order,
      jsonb_build_object(
        'candidate_id', parsed_rows.candidate_id::text,
        'finance_case_id', parsed_rows.finance_case_id::text,
        'finance_component_id', CASE WHEN parsed_rows.finance_component_id IS NULL THEN NULL ELSE parsed_rows.finance_component_id::text END,
        'recovery_family', parsed_rows.recovery_family,
        'source_ref', parsed_rows.source_ref,
        'pay_channel', parsed_rows.pay_channel,
        'umbrella_id', CASE WHEN parsed_rows.umbrella_id IS NULL THEN NULL ELSE parsed_rows.umbrella_id::text END,
        'paye_treatment', parsed_rows.paye_treatment,
        'frozen_component_key_type', parsed_rows.frozen_component_key_type,
        'frozen_component_key_value', parsed_rows.frozen_component_key_value,
        'frozen_component_classification', parsed_rows.frozen_component_classification,
        'frozen_component_snapshot_json', parsed_rows.frozen_component_snapshot_json,
        'frozen_source_basis_json', parsed_rows.frozen_source_basis_json,
        'frozen_source_pay_method', parsed_rows.frozen_source_pay_method,
        'frozen_target_pay_method', parsed_rows.frozen_target_pay_method,
        'frozen_resolution_mode', parsed_rows.frozen_resolution_mode,
        'frozen_resolution_payload_json', parsed_rows.frozen_resolution_payload_json,
        'frozen_resolution_result_json', parsed_rows.frozen_resolution_result_json,
        'frozen_source_amount', parsed_rows.frozen_source_amount,
        'frozen_outstanding_amount', parsed_rows.frozen_outstanding_amount,
        'weekly_due', parsed_rows.weekly_due,
        'minimum_earnings_threshold', parsed_rows.minimum_earnings_threshold,
        'take_home_floor_override', parsed_rows.take_home_floor_override,
        'default_take_home_floor', parsed_rows.default_take_home_floor,
        'payout_status', parsed_rows.payout_status,
        'next_due_week_start', CASE WHEN parsed_rows.next_due_week_start IS NULL THEN NULL ELSE parsed_rows.next_due_week_start::text END,
        'sort_order', parsed_rows.sort_order
      ) AS template_json
    FROM (
      SELECT
        NULLIF(BTRIM(COALESCE(template_element.value->>'candidate_id', '')), '')::uuid AS candidate_id,
        NULLIF(BTRIM(COALESCE(template_element.value->>'finance_case_id', '')), '')::uuid AS finance_case_id,
        UPPER(BTRIM(COALESCE(template_element.value->>'recovery_family', ''))) AS recovery_family,
        NULLIF(BTRIM(COALESCE(template_element.value->>'finance_component_id', '')), '')::uuid AS finance_component_id,
        NULLIF(BTRIM(COALESCE(template_element.value->>'source_ref', '')), '') AS source_ref,
        UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'pay_channel', '')), '')) AS pay_channel,
        NULLIF(BTRIM(COALESCE(template_element.value->>'umbrella_id', '')), '')::uuid AS umbrella_id,
        UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'paye_treatment', '')), '')) AS paye_treatment,
        NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_component_key_type', '')), '') AS frozen_component_key_type,
        NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_component_key_value', '')), '') AS frozen_component_key_value,
        NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_component_classification', '')), '') AS frozen_component_classification,
        CASE
          WHEN jsonb_typeof(template_element.value->'frozen_component_snapshot_json') = 'object' THEN template_element.value->'frozen_component_snapshot_json'
          ELSE NULL::jsonb
        END AS frozen_component_snapshot_json,
        CASE
          WHEN jsonb_typeof(template_element.value->'frozen_source_basis_json') = 'object' THEN template_element.value->'frozen_source_basis_json'
          ELSE NULL::jsonb
        END AS frozen_source_basis_json,
        UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_source_pay_method', '')), '')) AS frozen_source_pay_method,
        UPPER(NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_target_pay_method', '')), '')) AS frozen_target_pay_method,
        NULLIF(BTRIM(COALESCE(template_element.value->>'frozen_resolution_mode', '')), '') AS frozen_resolution_mode,
        CASE
          WHEN jsonb_typeof(template_element.value->'frozen_resolution_payload_json') = 'object' THEN template_element.value->'frozen_resolution_payload_json'
          ELSE NULL::jsonb
        END AS frozen_resolution_payload_json,
        CASE
          WHEN jsonb_typeof(template_element.value->'frozen_resolution_result_json') = 'object' THEN template_element.value->'frozen_resolution_result_json'
          ELSE NULL::jsonb
        END AS frozen_resolution_result_json,
        ROUND(COALESCE(NULLIF(template_element.value->>'frozen_source_amount', '')::numeric, 0), 2)::numeric(12,2) AS frozen_source_amount,
        ROUND(COALESCE(NULLIF(template_element.value->>'frozen_outstanding_amount', '')::numeric, 0), 2)::numeric(12,2) AS frozen_outstanding_amount,
        ROUND(COALESCE(NULLIF(template_element.value->>'weekly_due', '')::numeric, 0), 2)::numeric(12,2) AS weekly_due,
        NULLIF(template_element.value->>'minimum_earnings_threshold', '')::numeric AS minimum_earnings_threshold,
        NULLIF(template_element.value->>'take_home_floor_override', '')::numeric AS take_home_floor_override,
        NULLIF(template_element.value->>'default_take_home_floor', '')::numeric AS default_take_home_floor,
        NULLIF(BTRIM(COALESCE(template_element.value->>'payout_status', '')), '') AS payout_status,
        NULLIF(template_element.value->>'next_due_week_start', '')::date AS next_due_week_start,
        COALESCE(NULLIF(template_element.value->>'sort_order', '')::integer, 0) AS sort_order
      FROM jsonb_array_elements(v_candidate_rollups_json) AS rollup_element(value)
      CROSS JOIN LATERAL jsonb_array_elements(
        CASE
          WHEN jsonb_typeof(rollup_element.value->'hidden_recovery_template_lines') = 'array' THEN COALESCE(rollup_element.value->'hidden_recovery_template_lines', '[]'::jsonb)
          ELSE '[]'::jsonb
        END
      ) AS template_element(value)
      WHERE jsonb_typeof(rollup_element.value) = 'object'
        AND jsonb_typeof(template_element.value) = 'object'
    ) AS parsed_rows
    WHERE parsed_rows.candidate_id = ANY(v_touched_candidate_ids)
      AND parsed_rows.finance_case_id IS NOT NULL
      AND parsed_rows.recovery_family IN ('MANUAL_DEBT_RECOVERY', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY')
  ) AS source_rows
  ORDER BY
    source_rows.candidate_id,
    source_rows.recovery_family,
    source_rows.finance_case_id,
    COALESCE(source_rows.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(source_rows.source_ref, ''),
    COALESCE(source_rows.pay_channel, ''),
    source_rows.sort_order;

  SELECT COUNT(*)::integer
  INTO v_hidden_recovery_templates_source_count
  FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_source;

  v_preview_payload_json := public.pay_preview_assemble_payload(
    p_context_json => v_context_json,
    p_candidate_rollups_json => v_candidate_rollups_json
  );

  IF jsonb_typeof(v_preview_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_preview_assemble_payload(...) must return a JSON object';
  END IF;

  v_hidden_recovery_templates_assembled_json := CASE
    WHEN jsonb_typeof(v_preview_payload_json->'hidden_recovery_template_lines') = 'array'
      THEN COALESCE(v_preview_payload_json->'hidden_recovery_template_lines', '[]'::jsonb)
    ELSE '[]'::jsonb
  END;

  SELECT COUNT(*)::integer
  INTO v_hidden_recovery_templates_assembled_count
  FROM jsonb_array_elements(v_hidden_recovery_templates_assembled_json) AS assembled_template(value)
  WHERE jsonb_typeof(assembled_template.value) = 'object';

  DROP TABLE IF EXISTS pg_temp.tmp_pay_workbench_prepare_hidden_templates_final;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_workbench_prepare_hidden_templates_final (
    candidate_id uuid NOT NULL,
    finance_case_id uuid NOT NULL,
    recovery_family text NOT NULL,
    finance_component_id uuid NULL,
    source_ref text NULL,
    pay_channel text NULL,
    sort_order integer NOT NULL,
    template_json jsonb NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_workbench_prepare_hidden_templates_final (
    candidate_id,
    finance_case_id,
    recovery_family,
    finance_component_id,
    source_ref,
    pay_channel,
    sort_order,
    template_json
  )
  SELECT DISTINCT ON (
    merged_rows.candidate_id,
    merged_rows.recovery_family,
    merged_rows.finance_case_id,
    COALESCE(merged_rows.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(merged_rows.source_ref, ''),
    COALESCE(merged_rows.pay_channel, '')
  )
    merged_rows.candidate_id,
    merged_rows.finance_case_id,
    merged_rows.recovery_family,
    merged_rows.finance_component_id,
    merged_rows.source_ref,
    merged_rows.pay_channel,
    merged_rows.sort_order,
    merged_rows.template_json
  FROM (
    SELECT
      source_tpl.candidate_id,
      source_tpl.finance_case_id,
      source_tpl.recovery_family,
      source_tpl.finance_component_id,
      source_tpl.source_ref,
      source_tpl.pay_channel,
      source_tpl.sort_order,
      source_tpl.template_json,
      1 AS source_priority
    FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_source AS source_tpl

    UNION ALL

    SELECT
      assembled_rows.candidate_id,
      assembled_rows.finance_case_id,
      assembled_rows.recovery_family,
      assembled_rows.finance_component_id,
      assembled_rows.source_ref,
      assembled_rows.pay_channel,
      assembled_rows.sort_order,
      assembled_rows.template_json,
      2 AS source_priority
    FROM (
      SELECT
        NULLIF(BTRIM(COALESCE(assembled_template.value->>'candidate_id', '')), '')::uuid AS candidate_id,
        NULLIF(BTRIM(COALESCE(assembled_template.value->>'finance_case_id', '')), '')::uuid AS finance_case_id,
        UPPER(BTRIM(COALESCE(assembled_template.value->>'recovery_family', ''))) AS recovery_family,
        NULLIF(BTRIM(COALESCE(assembled_template.value->>'finance_component_id', '')), '')::uuid AS finance_component_id,
        NULLIF(BTRIM(COALESCE(assembled_template.value->>'source_ref', '')), '') AS source_ref,
        UPPER(NULLIF(BTRIM(COALESCE(assembled_template.value->>'pay_channel', '')), '')) AS pay_channel,
        COALESCE(NULLIF(assembled_template.value->>'sort_order', '')::integer, 0) AS sort_order,
        assembled_template.value AS template_json
      FROM jsonb_array_elements(v_hidden_recovery_templates_assembled_json) AS assembled_template(value)
      WHERE jsonb_typeof(assembled_template.value) = 'object'
    ) AS assembled_rows
    WHERE assembled_rows.candidate_id IS NOT NULL
      AND assembled_rows.finance_case_id IS NOT NULL
      AND assembled_rows.recovery_family IN ('MANUAL_DEBT_RECOVERY', 'LOAN_REPAYMENT', 'OVERPAYMENT_RECOVERY')
  ) AS merged_rows
  ORDER BY
    merged_rows.candidate_id,
    merged_rows.recovery_family,
    merged_rows.finance_case_id,
    COALESCE(merged_rows.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(merged_rows.source_ref, ''),
    COALESCE(merged_rows.pay_channel, ''),
    merged_rows.source_priority,
    merged_rows.sort_order;

  SELECT
    COALESCE(
      jsonb_agg(
        final_tpl.template_json
        ORDER BY
          final_tpl.candidate_id,
          final_tpl.recovery_family,
          final_tpl.finance_case_id,
          COALESCE(final_tpl.finance_component_id, '00000000-0000-0000-0000-000000000000'::uuid),
          final_tpl.sort_order
      ),
      '[]'::jsonb
    ),
    COUNT(*)::integer
  INTO v_hidden_recovery_templates_passed_json, v_hidden_recovery_templates_passed_count
  FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_final AS final_tpl;

  v_preview_payload_json := jsonb_set(
    jsonb_set(
      v_preview_payload_json,
      '{hidden_recovery_template_lines}',
      COALESCE(v_hidden_recovery_templates_passed_json, '[]'::jsonb),
      true
    ),
    '{hidden_recovery_template_line_count}',
    to_jsonb(v_hidden_recovery_templates_passed_count),
    true
  );

  SELECT COALESCE(
           jsonb_object_agg(candidate_counts.candidate_id::text, to_jsonb(candidate_counts.template_count) ORDER BY candidate_counts.candidate_id::text),
           '{}'::jsonb
         )
  INTO v_hidden_manual_debt_source_by_candidate
  FROM (
    SELECT source_tpl.candidate_id, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_source AS source_tpl
    WHERE source_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
      AND (
        source_tpl.pay_channel = 'PAYE'
        OR (
          COALESCE(BTRIM(source_tpl.pay_channel), '') = ''
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_pay_rows
            WHERE selected_pay_rows.candidate_id = source_tpl.candidate_id
              AND selected_pay_rows.pay_channel = 'PAYE'
          )
        )
      )
    GROUP BY source_tpl.candidate_id
  ) AS candidate_counts;

  SELECT COALESCE(
           jsonb_object_agg(candidate_counts.candidate_id::text, to_jsonb(candidate_counts.template_count) ORDER BY candidate_counts.candidate_id::text),
           '{}'::jsonb
         )
  INTO v_hidden_manual_debt_passed_by_candidate
  FROM (
    SELECT final_tpl.candidate_id, COUNT(*)::integer AS template_count
    FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_final AS final_tpl
    WHERE final_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
      AND (
        final_tpl.pay_channel = 'PAYE'
        OR (
          COALESCE(BTRIM(final_tpl.pay_channel), '') = ''
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_pay_rows
            WHERE selected_pay_rows.candidate_id = final_tpl.candidate_id
              AND selected_pay_rows.pay_channel = 'PAYE'
          )
        )
      )
    GROUP BY final_tpl.candidate_id
  ) AS candidate_counts;

  SELECT COALESCE(array_agg(missing_candidate.candidate_id ORDER BY missing_candidate.candidate_id), ARRAY[]::uuid[])
  INTO v_missing_manual_debt_template_candidate_ids
  FROM (
    SELECT DISTINCT source_tpl.candidate_id
    FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_source AS source_tpl
    WHERE source_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
      AND (
        source_tpl.pay_channel = 'PAYE'
        OR (
          COALESCE(BTRIM(source_tpl.pay_channel), '') = ''
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_pay_rows
            WHERE selected_pay_rows.candidate_id = source_tpl.candidate_id
              AND selected_pay_rows.pay_channel = 'PAYE'
          )
        )
      )
  ) AS missing_candidate
  LEFT JOIN (
    SELECT DISTINCT final_tpl.candidate_id
    FROM pg_temp.tmp_pay_workbench_prepare_hidden_templates_final AS final_tpl
    WHERE final_tpl.recovery_family = 'MANUAL_DEBT_RECOVERY'
      AND (
        final_tpl.pay_channel = 'PAYE'
        OR (
          COALESCE(BTRIM(final_tpl.pay_channel), '') = ''
          AND EXISTS (
            SELECT 1
            FROM pg_temp.tmp_pay_workbench_prepare_selected_rows AS selected_pay_rows
            WHERE selected_pay_rows.candidate_id = final_tpl.candidate_id
              AND selected_pay_rows.pay_channel = 'PAYE'
          )
        )
      )
  ) AS passed_candidate
    ON passed_candidate.candidate_id = missing_candidate.candidate_id
  WHERE passed_candidate.candidate_id IS NULL;

  IF COALESCE(array_length(v_missing_manual_debt_template_candidate_ids, 1), 0) > 0 THEN
    RAISE EXCEPTION 'MANUAL_DEBT_TEMPLATE_NOT_CARRIED_TO_BATCH_BUILD: selected PAYE candidate hidden manual-debt templates were lost before batch build for candidates %',
      array_to_string(v_missing_manual_debt_template_candidate_ids, ',');
  END IF;

  v_hidden_template_diagnostics := jsonb_build_object(
    'selected_candidate_source_hidden_template_count', v_hidden_recovery_templates_source_count,
    'assembled_hidden_template_count_before_merge', v_hidden_recovery_templates_assembled_count,
    'hidden_template_count_passed_to_batch_build', v_hidden_recovery_templates_passed_count,
    'manual_debt_hidden_template_source_count_by_candidate', v_hidden_manual_debt_source_by_candidate,
    'manual_debt_hidden_template_passed_count_by_candidate', v_hidden_manual_debt_passed_by_candidate
  );

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
  INTO v_umbrella_selected_preview_row_ids, v_umbrella_selected_preview_row_count
  FROM (
    SELECT DISTINCT ON (pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id)
      pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id,
      pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows
    WHERE pg_temp.tmp_pay_workbench_prepare_selected_rows.pay_channel = 'UMBRELLA'
    ORDER BY pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id, pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
  ) AS selected_rows;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_rows.preview_row_id) ORDER BY selected_rows.ord), '[]'::jsonb), COUNT(*)::integer
  INTO v_paye_selected_preview_row_ids, v_paye_selected_preview_row_count
  FROM (
    SELECT DISTINCT ON (pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id)
      pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id,
      pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
    FROM pg_temp.tmp_pay_workbench_prepare_selected_rows
    WHERE pg_temp.tmp_pay_workbench_prepare_selected_rows.pay_channel = 'PAYE'
    ORDER BY pg_temp.tmp_pay_workbench_prepare_selected_rows.preview_row_id, pg_temp.tmp_pay_workbench_prepare_selected_rows.ord
  ) AS selected_rows;

  IF v_scope_filter IN ('ALL', 'UMBRELLA') THEN
    IF v_umbrella_selected_preview_row_count > 0 THEN
      v_umbrella_build_result := public.pay_build_batch_artifacts_from_preview(
        p_pay_date => v_session_row.pay_date,
        p_week_ending_cutoff => v_session_row.week_ending_cutoff,
        p_actor_user_id => p_actor_user_id,
        p_preview_payload_json => v_preview_payload_json,
        p_selected_preview_row_ids => v_umbrella_selected_preview_row_ids,
        p_source_workbench_session_id => p_session_id,
        p_source_snapshot_run_id => v_session_row.source_snapshot_run_id,
        p_source_session_version => v_session_row.version,
        p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
      );

      IF NULLIF(BTRIM(COALESCE(v_umbrella_build_result->>'pay_batch_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_umbrella_pay_batch_id := (v_umbrella_build_result->>'pay_batch_id')::uuid;
        v_umbrella_status := 'BATCH_CREATED';
      ELSE
        v_umbrella_status := 'NOTHING_RELEVANT';
      END IF;
    ELSE
      v_umbrella_status := 'NOTHING_RELEVANT';
    END IF;
  ELSE
    v_umbrella_status := 'NOT_RUN';
  END IF;

  IF v_scope_filter IN ('ALL', 'PAYE') THEN
    IF v_paye_selected_preview_row_count > 0 THEN
      PERFORM pg_advisory_xact_lock(94201, 1);

      v_paye_guardrails := public.pay_paye_guardrails(
        p_pay_date => v_session_row.pay_date,
        p_ignore_pay_batch_id => NULL::uuid,
        p_actor_user_id => p_actor_user_id
      );

      v_paye_create_blocked := COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false);
      v_paye_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

      IF v_paye_create_blocked THEN
        v_paye_scope_blocked := true;
        v_paye_status := 'BLOCKED_EXISTING_PAYE_DRAFT';
        v_paye_block_reason_code := 'PAYE_DRAFT_ALREADY_EXISTS';
        v_paye_block_message := COALESCE(
          v_paye_guardrails #>> '{ui,existing_draft_block,message}',
          'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.'
        );
      ELSIF v_paye_override_required THEN
        IF NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NULL THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_REASON_REQUIRED';
          v_paye_block_message := 'A same-week PAYE override reason is required before creating another PAYE batch in the same Monday-based payroll week.';
        ELSIF COALESCE(p_override_continue, false) = false THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_CONTINUE_REQUIRED';
          v_paye_block_message := 'Explicit continuation is required before creating another PAYE batch in the same Monday-based payroll week.';
        ELSIF COALESCE(p_override_verified, false) = false THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFICATION_REQUIRED';
          v_paye_block_message := 'Valid password reauthentication and 2FA verification are required before creating another PAYE batch in the same Monday-based payroll week.';
        ELSIF p_override_verified_by_user_id IS NULL THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_REQUIRED';
          v_paye_block_message := 'The verified override user id is required for same-week PAYE override.';
        ELSIF p_override_verified_by_user_id <> p_actor_user_id THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_MISMATCH';
          v_paye_block_message := 'The same-week PAYE override verification must belong to the current actor user.';
        ELSIF p_override_verified_at_utc IS NULL THEN
          v_paye_scope_blocked := true;
          v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
          v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_AT_REQUIRED';
          v_paye_block_message := 'The verification timestamp is required for same-week PAYE override.';
        END IF;
      END IF;

      IF v_paye_scope_blocked = false THEN
        v_paye_build_result := public.pay_build_batch_artifacts_from_preview(
          p_pay_date => v_session_row.pay_date,
          p_week_ending_cutoff => v_session_row.week_ending_cutoff,
          p_actor_user_id => p_actor_user_id,
          p_preview_payload_json => v_preview_payload_json,
          p_selected_preview_row_ids => v_paye_selected_preview_row_ids,
          p_source_workbench_session_id => p_session_id,
          p_source_snapshot_run_id => v_session_row.source_snapshot_run_id,
          p_source_session_version => v_session_row.version,
        p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
        );

        IF NULLIF(BTRIM(COALESCE(v_paye_build_result->>'pay_batch_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          v_paye_pay_batch_id := (v_paye_build_result->>'pay_batch_id')::uuid;
          v_paye_status := 'BATCH_CREATED';
        ELSE
          v_paye_status := 'NOTHING_RELEVANT';
        END IF;
      END IF;
    ELSE
      v_paye_status := 'NOTHING_RELEVANT';
    END IF;
  ELSE
    v_paye_status := 'NOT_RUN';
  END IF;

  v_has_any_scope_outcome :=
       v_umbrella_pay_batch_id IS NOT NULL
    OR v_paye_pay_batch_id IS NOT NULL
    OR v_paye_scope_blocked;

  IF v_has_any_scope_outcome = false THEN
    RAISE EXCEPTION 'Nothing to pay (no payable items remain in touched session scope after validation and readiness checks)';
  END IF;

  v_audit_after_json := jsonb_build_object(
    'session_id', p_session_id::text,
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'source_session_version', v_session_row.version,
    'pay_date', v_session_row.pay_date::text,
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'pay_channel_scope', v_scope_filter,
    'touched_candidate_ids', to_jsonb(COALESCE(v_touched_candidate_ids, ARRAY[]::uuid[])),
    'selected_preview_row_ids', v_selected_preview_row_ids,
    'umbrella_pay_batch_id', CASE WHEN v_umbrella_pay_batch_id IS NULL THEN NULL ELSE v_umbrella_pay_batch_id::text END,
    'paye_pay_batch_id', CASE WHEN v_paye_pay_batch_id IS NULL THEN NULL ELSE v_paye_pay_batch_id::text END,
    'umbrella_status', v_umbrella_status,
    'paye_status', v_paye_status,
    'paye_scope_blocked', v_paye_scope_blocked,
    'paye_block_reason_code', v_paye_block_reason_code,
    'paye_guardrails', v_paye_guardrails,
    'hidden_template_diagnostics', v_hidden_template_diagnostics
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_session_id::text,
    'WORKBENCH_PREPARE_DRAFT',
    NULL,
    v_audit_after_json,
    'WORKBENCH_PREPARE_DRAFT',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'source_snapshot_run_id', v_session_row.source_snapshot_run_id::text,
    'source_session_version', v_session_row.version,
    'touched_candidate_ids', to_jsonb(COALESCE(v_touched_candidate_ids, ARRAY[]::uuid[])),
    'touched_candidate_count', v_touched_candidate_count,
    'selected_preview_row_ids', v_selected_preview_row_ids,
    'selected_preview_row_count', v_selected_preview_row_count,
    'umbrella_pay_batch_id', CASE WHEN v_umbrella_pay_batch_id IS NULL THEN NULL ELSE v_umbrella_pay_batch_id::text END,
    'paye_pay_batch_id', CASE WHEN v_paye_pay_batch_id IS NULL THEN NULL ELSE v_paye_pay_batch_id::text END,
    'umbrella_status', v_umbrella_status,
    'paye_status', v_paye_status,
    'paye_guardrails', v_paye_guardrails,
    'hidden_template_diagnostics', v_hidden_template_diagnostics,
    'scope_results', jsonb_build_object(
      'UMBRELLA', jsonb_build_object(
        'status', v_umbrella_status,
        'created', (v_umbrella_pay_batch_id IS NOT NULL),
        'blocked', false,
        'block_reason_code', NULL,
        'block_message', NULL,
        'pay_batch_id', CASE WHEN v_umbrella_pay_batch_id IS NULL THEN NULL ELSE v_umbrella_pay_batch_id::text END
      ),
      'PAYE', jsonb_build_object(
        'status', v_paye_status,
        'created', (v_paye_pay_batch_id IS NOT NULL),
        'blocked', v_paye_scope_blocked,
        'block_reason_code', v_paye_block_reason_code,
        'block_message', v_paye_block_message,
        'pay_batch_id', CASE WHEN v_paye_pay_batch_id IS NULL THEN NULL ELSE v_paye_pay_batch_id::text END,
        'guardrails', v_paye_guardrails,
        'override_required', v_paye_override_required,
        'override_reason_present', (NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NOT NULL),
        'override_continue', COALESCE(p_override_continue, false),
        'override_verified', COALESCE(p_override_verified, false),
        'override_verified_by_user_id', CASE WHEN p_override_verified_by_user_id IS NULL THEN NULL ELSE p_override_verified_by_user_id::text END,
        'override_verified_at_utc', p_override_verified_at_utc
      )
    ),
    'prepared_at_utc', v_now
  );
END;
$$;





CREATE OR REPLACE FUNCTION public.pay_workbench_claim_job_now(p_job_id uuid, p_now_utc timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, v_now);
  v_stale_running_seconds integer := 600;
  v_stale_cutoff timestamptz := NULL;
  v_requested_job_id_text text := CASE WHEN p_job_id IS NULL THEN NULL ELSE p_job_id::text END;
  v_job_row public.banking_pay_workbench_jobs%ROWTYPE;
  v_before_json jsonb := NULL;
  v_after_json jsonb := '{}'::jsonb;
  v_claimed boolean := false;
  v_reclaimed_stale boolean := false;
  v_no_op boolean := false;
  v_terminalized boolean := false;
  v_reason text := NULL;
  v_audit_action text := NULL;
  v_audit_reason text := NULL;
  v_last_activity_utc timestamptz := NULL;
  v_supported_job_type boolean := false;
  v_due_now boolean := false;
  v_stale_now boolean := false;
  v_attempt_count_after integer := 0;
  v_max_attempts integer := 0;
  v_attempts_exhausted boolean := false;
  v_terminal_error_json jsonb := NULL;
BEGIN
  v_stale_cutoff := v_cutoff - make_interval(secs => v_stale_running_seconds);

  IF p_job_id IS NULL THEN
    v_no_op := true;
    v_reason := 'INVALID_JOB_ID';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_INVALID_JOB_ID';

    v_after_json := jsonb_build_object(
      'id', NULL,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'dedupe_key', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'created_at_utc', NULL,
      'updated_at_utc', NULL,
      'started_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_requested_job_id_text,
      v_audit_action,
      v_before_json,
      v_after_json,
      v_audit_reason,
      NULL
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', NULL,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'started_at_utc', NULL,
      'updated_at_utc', NULL,
      'created_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );
  END IF;

  SELECT public.banking_pay_workbench_jobs.*
  INTO v_job_row
  FROM public.banking_pay_workbench_jobs
  WHERE public.banking_pay_workbench_jobs.id = p_job_id
  FOR UPDATE;

  IF NOT FOUND THEN
    v_no_op := true;
    v_reason := 'JOB_NOT_FOUND';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_NOT_FOUND';

    v_after_json := jsonb_build_object(
      'id', v_requested_job_id_text,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'dedupe_key', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'created_at_utc', NULL,
      'updated_at_utc', NULL,
      'started_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );

    PERFORM public._audit_insert(
      'banking_pay_workbench_job',
      v_requested_job_id_text,
      v_audit_action,
      v_before_json,
      v_after_json,
      v_audit_reason,
      NULL
    );

    RETURN jsonb_build_object(
      'ok', true,
      'job_id', v_requested_job_id_text,
      'job_type', NULL,
      'status', NULL,
      'priority', NULL,
      'run_at_utc', NULL,
      'attempt_count', NULL,
      'max_attempts', NULL,
      'snapshot_run_id', NULL,
      'session_id', NULL,
      'candidate_id', NULL,
      'payload_json', NULL,
      'started_at_utc', NULL,
      'updated_at_utc', NULL,
      'created_at_utc', NULL,
      'completed_at_utc', NULL,
      'failed_at_utc', NULL,
      'last_error_json', NULL,
      'claimed', v_claimed,
      'reclaimed_stale', v_reclaimed_stale,
      'no_op', v_no_op,
      'terminalized', v_terminalized,
      'reason', v_reason,
      'cutoff_utc', v_cutoff,
      'stale_cutoff_utc', v_stale_cutoff,
      'stale_running_seconds', v_stale_running_seconds,
      'last_activity_utc', NULL,
      'supported_job_type', v_supported_job_type
    );
  END IF;

  v_last_activity_utc := COALESCE(
    v_job_row.updated_at_utc,
    v_job_row.started_at_utc,
    v_job_row.created_at_utc,
    v_job_row.run_at_utc
  );

  v_supported_job_type := COALESCE(v_job_row.job_type, '') IN ('SESSION_CANDIDATE_RECOMPUTE', 'SNAPSHOT_CANDIDATE_REFRESH');
  v_due_now := COALESCE(v_job_row.status, '') = 'QUEUED'
               AND v_job_row.run_at_utc IS NOT NULL
               AND v_job_row.run_at_utc <= v_cutoff;
  v_stale_now := COALESCE(v_job_row.status, '') = 'RUNNING'
                 AND v_last_activity_utc IS NOT NULL
                 AND v_last_activity_utc <= v_stale_cutoff;
  v_max_attempts := COALESCE(v_job_row.max_attempts, 8);
  v_attempts_exhausted := COALESCE(v_job_row.attempt_count, 0) >= v_max_attempts;

  v_before_json := jsonb_build_object(
    'id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_job_row.attempt_count,
    'max_attempts', v_job_row.max_attempts,
    'dedupe_key', v_job_row.dedupe_key,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'created_at_utc', v_job_row.created_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'started_at_utc', v_job_row.started_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json
  );

  IF NOT v_supported_job_type THEN
    v_no_op := true;
    v_reason := 'UNSUPPORTED_JOB_TYPE';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_UNSUPPORTED';
  ELSIF COALESCE(v_job_row.status, '') IN ('SUCCEEDED', 'DEAD') THEN
    v_no_op := true;
    v_reason := 'TERMINAL_STATUS';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_TERMINAL';
  ELSIF COALESCE(v_job_row.status, '') = 'RUNNING' AND NOT v_stale_now THEN
    v_no_op := true;
    v_reason := 'FRESH_RUNNING';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_FRESH_RUNNING';
  ELSIF v_due_now THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_claimed := true;
      v_reason := 'CLAIMED_QUEUED_JOB';
      v_audit_action := 'RUNNING';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIMED';

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(update_job.attempt_count, 0) + 1,
          started_at_utc = COALESCE(update_job.started_at_utc, v_now),
          updated_at_utc = v_now,
          last_error_json = NULL
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    END IF;
  ELSIF v_stale_now THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_claimed := true;
      v_reclaimed_stale := true;
      v_reason := 'RECLAIMED_STALE_RUNNING_JOB';
      v_audit_action := 'RUNNING';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_STALE_RECLAIMED';

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'RUNNING',
          attempt_count = COALESCE(update_job.attempt_count, 0) + 1,
          started_at_utc = v_now,
          updated_at_utc = v_now,
          last_error_json = NULL
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    END IF;
  ELSIF COALESCE(v_job_row.status, '') = 'QUEUED' THEN
    IF v_attempts_exhausted THEN
      v_terminalized := true;
      v_reason := 'MAX_ATTEMPTS_EXHAUSTED';
      v_audit_action := 'DEAD';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_MAX_ATTEMPTS_DEAD';
      v_terminal_error_json := jsonb_build_object(
        'code', 'MAX_ATTEMPTS_EXHAUSTED',
        'message', 'Targeted workbench job claim refused because max_attempts has been reached.',
        'job_id', v_job_row.id::text,
        'job_type', v_job_row.job_type,
        'status', v_job_row.status,
        'attempt_count', COALESCE(v_job_row.attempt_count, 0),
        'max_attempts', v_max_attempts,
        'targeted_claim_at_utc', v_now
      );

      UPDATE public.banking_pay_workbench_jobs AS update_job
      SET status = 'DEAD',
          updated_at_utc = v_now,
          completed_at_utc = NULL,
          failed_at_utc = v_now,
          last_error_json = v_terminal_error_json,
          payload_json = COALESCE(update_job.payload_json, '{}'::jsonb) || jsonb_build_object('last_failure_json', v_terminal_error_json)
      WHERE update_job.id = p_job_id
      RETURNING update_job.*
      INTO v_job_row;
    ELSE
      v_no_op := true;
      v_reason := 'JOB_NOT_DUE_YET';
      v_audit_action := 'CLAIM_DENIED';
      v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_NOT_DUE';
    END IF;
  ELSE
    v_no_op := true;
    v_reason := 'STATUS_NOT_CLAIMABLE';
    v_audit_action := 'CLAIM_DENIED';
    v_audit_reason := 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_STATUS';
  END IF;

  v_last_activity_utc := COALESCE(
    v_job_row.updated_at_utc,
    v_job_row.started_at_utc,
    v_job_row.created_at_utc,
    v_job_row.run_at_utc
  );
  v_attempt_count_after := COALESCE(v_job_row.attempt_count, 0);

  v_after_json := jsonb_build_object(
    'id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_job_row.attempt_count,
    'max_attempts', v_job_row.max_attempts,
    'dedupe_key', v_job_row.dedupe_key,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'created_at_utc', v_job_row.created_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'started_at_utc', v_job_row.started_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json,
    'claimed', v_claimed,
    'reclaimed_stale', v_reclaimed_stale,
    'no_op', v_no_op,
    'terminalized', v_terminalized,
    'reason', v_reason,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'last_activity_utc', v_last_activity_utc,
    'supported_job_type', v_supported_job_type
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_job',
    p_job_id::text,
    COALESCE(v_audit_action, 'CLAIM_DENIED'),
    v_before_json,
    v_after_json,
    COALESCE(v_audit_reason, 'WORKBENCH_JOB_TARGET_CLAIM_DENIED_STATUS'),
    NULL
  );

  RETURN jsonb_build_object(
    'ok', true,
    'job_id', v_job_row.id::text,
    'job_type', v_job_row.job_type,
    'status', v_job_row.status,
    'priority', v_job_row.priority,
    'run_at_utc', v_job_row.run_at_utc,
    'attempt_count', v_attempt_count_after,
    'max_attempts', v_max_attempts,
    'snapshot_run_id', CASE WHEN v_job_row.snapshot_run_id IS NULL THEN NULL ELSE v_job_row.snapshot_run_id::text END,
    'session_id', CASE WHEN v_job_row.session_id IS NULL THEN NULL ELSE v_job_row.session_id::text END,
    'candidate_id', CASE WHEN v_job_row.candidate_id IS NULL THEN NULL ELSE v_job_row.candidate_id::text END,
    'payload_json', v_job_row.payload_json,
    'started_at_utc', v_job_row.started_at_utc,
    'updated_at_utc', v_job_row.updated_at_utc,
    'created_at_utc', v_job_row.created_at_utc,
    'completed_at_utc', v_job_row.completed_at_utc,
    'failed_at_utc', v_job_row.failed_at_utc,
    'last_error_json', v_job_row.last_error_json,
    'claimed', v_claimed,
    'reclaimed_stale', v_reclaimed_stale,
    'no_op', v_no_op,
    'terminalized', v_terminalized,
    'reason', v_reason,
    'cutoff_utc', v_cutoff,
    'stale_cutoff_utc', v_stale_cutoff,
    'stale_running_seconds', v_stale_running_seconds,
    'last_activity_utc', v_last_activity_utc,
    'supported_job_type', v_supported_job_type
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public._pay_workbench_merge_targeted_scope_payload(p_existing jsonb, p_incoming jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_existing jsonb := CASE WHEN jsonb_typeof(COALESCE(p_existing, '{}'::jsonb)) = 'object' THEN COALESCE(p_existing, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_incoming jsonb := CASE WHEN jsonb_typeof(COALESCE(p_incoming, '{}'::jsonb)) = 'object' THEN COALESCE(p_incoming, '{}'::jsonb) ELSE '{}'::jsonb END;
  v_result jsonb := '{}'::jsonb;
  v_targeted_timesheet_ids jsonb := '[]'::jsonb;
  v_linked_timesheet_ids jsonb := '[]'::jsonb;
  v_reasons_json jsonb := '[]'::jsonb;
  v_existing_scope_kind text := NULL;
  v_incoming_scope_kind text := NULL;
  v_effective_scope_kind text := NULL;
  v_existing_candidate_id text := NULL;
  v_incoming_candidate_id text := NULL;
  v_effective_candidate_id text := NULL;
  v_existing_reason text := NULL;
  v_incoming_reason text := NULL;
  v_effective_reason text := NULL;
  v_existing_source_change_seq_text text := NULL;
  v_incoming_source_change_seq_text text := NULL;
  v_existing_source_change_seq bigint := NULL;
  v_incoming_source_change_seq bigint := NULL;
  v_effective_source_change_seq_text text := NULL;
BEGIN
  v_result := v_existing || v_incoming;

  v_existing_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_existing->>'refresh_scope_kind', ''))), '');
  v_incoming_scope_kind := NULLIF(UPPER(BTRIM(COALESCE(v_incoming->>'refresh_scope_kind', ''))), '');

  v_effective_scope_kind := CASE
    WHEN v_existing_scope_kind = 'CANDIDATE_FULL_LIVE' OR v_incoming_scope_kind = 'CANDIDATE_FULL_LIVE' THEN 'CANDIDATE_FULL_LIVE'
    WHEN v_existing_scope_kind = 'TARGETED_TIMESHEETS' OR v_incoming_scope_kind = 'TARGETED_TIMESHEETS' THEN 'TARGETED_TIMESHEETS'
    WHEN v_incoming_scope_kind IS NOT NULL THEN v_incoming_scope_kind
    ELSE v_existing_scope_kind
  END;

  v_existing_candidate_id := NULLIF(BTRIM(COALESCE(v_existing->>'candidate_id', '')), '');
  v_incoming_candidate_id := NULLIF(BTRIM(COALESCE(v_incoming->>'candidate_id', '')), '');
  v_effective_candidate_id := COALESCE(v_existing_candidate_id, v_incoming_candidate_id);

  v_existing_reason := NULLIF(BTRIM(COALESCE(v_existing->>'reason', '')), '');
  v_incoming_reason := NULLIF(BTRIM(COALESCE(v_incoming->>'reason', '')), '');
  v_effective_reason := COALESCE(v_incoming_reason, v_existing_reason);

  v_existing_source_change_seq_text := NULLIF(BTRIM(COALESCE(v_existing->>'source_change_seq', '')), '');
  v_incoming_source_change_seq_text := NULLIF(BTRIM(COALESCE(v_incoming->>'source_change_seq', '')), '');

  IF v_existing_source_change_seq_text ~ '^-?[0-9]+$' THEN
    v_existing_source_change_seq := v_existing_source_change_seq_text::bigint;
  END IF;

  IF v_incoming_source_change_seq_text ~ '^-?[0-9]+$' THEN
    v_incoming_source_change_seq := v_incoming_source_change_seq_text::bigint;
  END IF;

  v_effective_source_change_seq_text := CASE
    WHEN v_existing_source_change_seq IS NOT NULL AND v_incoming_source_change_seq IS NOT NULL THEN GREATEST(v_existing_source_change_seq, v_incoming_source_change_seq)::text
    WHEN v_incoming_source_change_seq IS NOT NULL THEN v_incoming_source_change_seq::text
    WHEN v_existing_source_change_seq IS NOT NULL THEN v_existing_source_change_seq::text
    WHEN v_incoming_source_change_seq_text IS NOT NULL THEN v_incoming_source_change_seq_text
    ELSE v_existing_source_change_seq_text
  END;

  SELECT COALESCE(jsonb_agg(targeted_scope_ids.targeted_timesheet_id ORDER BY targeted_scope_ids.targeted_timesheet_id), '[]'::jsonb)
  INTO v_targeted_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') AS targeted_timesheet_id
    FROM (
      SELECT targeted_scope_existing_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_existing->'targeted_timesheet_ids') = 'array' THEN v_existing->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_existing->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_existing->>'targeted_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_existing_array(value)

      UNION ALL

      SELECT targeted_scope_incoming_array.value AS targeted_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_incoming->'targeted_timesheet_ids') = 'array' THEN v_incoming->'targeted_timesheet_ids'
          WHEN jsonb_typeof(v_incoming->'targeted_timesheet_ids') = 'string' THEN jsonb_build_array(v_incoming->>'targeted_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS targeted_scope_incoming_array(value)
    ) AS targeted_scope_values
    WHERE NULLIF(BTRIM(targeted_scope_values.targeted_timesheet_id_raw), '') IS NOT NULL
  ) AS targeted_scope_ids;

  SELECT COALESCE(jsonb_agg(linked_scope_ids.linked_timesheet_id ORDER BY linked_scope_ids.linked_timesheet_id), '[]'::jsonb)
  INTO v_linked_timesheet_ids
  FROM (
    SELECT DISTINCT NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') AS linked_timesheet_id
    FROM (
      SELECT linked_scope_existing_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_existing->'linked_timesheet_ids') = 'array' THEN v_existing->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_existing->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_existing->>'linked_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_existing_array(value)

      UNION ALL

      SELECT linked_scope_incoming_array.value AS linked_timesheet_id_raw
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_incoming->'linked_timesheet_ids') = 'array' THEN v_incoming->'linked_timesheet_ids'
          WHEN jsonb_typeof(v_incoming->'linked_timesheet_ids') = 'string' THEN jsonb_build_array(v_incoming->>'linked_timesheet_ids')
          ELSE '[]'::jsonb
        END
      ) AS linked_scope_incoming_array(value)
    ) AS linked_scope_values
    WHERE NULLIF(BTRIM(linked_scope_values.linked_timesheet_id_raw), '') IS NOT NULL
  ) AS linked_scope_ids;

  SELECT COALESCE(jsonb_agg(reason_values.reason_value ORDER BY reason_values.reason_ord), '[]'::jsonb)
  INTO v_reasons_json
  FROM (
    SELECT deduped_reasons.reason_value, MIN(deduped_reasons.reason_ord) AS reason_ord
    FROM (
      SELECT NULLIF(BTRIM(COALESCE(v_existing->>'reason', '')), '') AS reason_value,
             1::bigint AS reason_ord

      UNION ALL

      SELECT NULLIF(BTRIM(existing_reason_array.value), '') AS reason_value,
             1000::bigint + existing_reason_array.ordinality AS reason_ord
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_existing->'reasons') = 'array' THEN v_existing->'reasons'
          WHEN jsonb_typeof(v_existing->'reasons') = 'string' THEN jsonb_build_array(v_existing->>'reasons')
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS existing_reason_array(value, ordinality)

      UNION ALL

      SELECT NULLIF(BTRIM(COALESCE(v_incoming->>'reason', '')), '') AS reason_value,
             1000000::bigint AS reason_ord

      UNION ALL

      SELECT NULLIF(BTRIM(incoming_reason_array.value), '') AS reason_value,
             1001000::bigint + incoming_reason_array.ordinality AS reason_ord
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(v_incoming->'reasons') = 'array' THEN v_incoming->'reasons'
          WHEN jsonb_typeof(v_incoming->'reasons') = 'string' THEN jsonb_build_array(v_incoming->>'reasons')
          ELSE '[]'::jsonb
        END
      ) WITH ORDINALITY AS incoming_reason_array(value, ordinality)
    ) AS deduped_reasons
    WHERE deduped_reasons.reason_value IS NOT NULL
    GROUP BY deduped_reasons.reason_value
  ) AS reason_values;

  IF v_effective_scope_kind IS NOT NULL THEN
    v_result := v_result || jsonb_build_object('refresh_scope_kind', v_effective_scope_kind);
  ELSE
    v_result := v_result - 'refresh_scope_kind';
  END IF;

  v_result := v_result || jsonb_build_object('targeted_timesheet_ids', v_targeted_timesheet_ids);
  v_result := v_result || jsonb_build_object('linked_timesheet_ids', v_linked_timesheet_ids);

  IF v_effective_candidate_id IS NOT NULL THEN
    v_result := v_result || jsonb_build_object('candidate_id', v_effective_candidate_id);
  ELSE
    v_result := v_result - 'candidate_id';
  END IF;

  IF v_effective_reason IS NOT NULL THEN
    v_result := v_result || jsonb_build_object('reason', v_effective_reason);
  ELSE
    v_result := v_result - 'reason';
  END IF;

  IF jsonb_array_length(v_reasons_json) > 0 THEN
    v_result := v_result || jsonb_build_object('reasons', v_reasons_json);
  ELSE
    v_result := v_result - 'reasons';
  END IF;

  IF v_effective_source_change_seq_text IS NOT NULL THEN
    IF v_effective_source_change_seq_text ~ '^-?[0-9]+$' THEN
      v_result := v_result || jsonb_build_object('source_change_seq', v_effective_source_change_seq_text::bigint);
    ELSE
      v_result := v_result || jsonb_build_object('source_change_seq', v_effective_source_change_seq_text);
    END IF;
  ELSE
    v_result := v_result - 'source_change_seq';
  END IF;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_mark_candidate_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_trigger_table text := lower(TG_TABLE_NAME);
  v_new_row jsonb := '{}'::jsonb;
  v_old_row jsonb := '{}'::jsonb;
  v_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_candidate_id uuid;
  v_live_change_seq bigint := 0;
  v_reason text;
  v_payload_json jsonb;
  v_dedupe_key text;
  v_old_timesheet_id uuid := NULL::uuid;
  v_new_timesheet_id uuid := NULL::uuid;
  v_old_contract_id uuid := NULL::uuid;
  v_new_contract_id uuid := NULL::uuid;
  v_old_booking_id text := NULL::text;
  v_new_booking_id text := NULL::text;
  v_refresh_scope_kind text := NULL;
  v_targeted_timesheet_uuid_ids uuid[] := ARRAY[]::uuid[];
  v_linked_timesheet_uuid_ids uuid[] := ARRAY[]::uuid[];
  v_targeted_timesheet_ids_json jsonb := '[]'::jsonb;
  v_linked_timesheet_ids_json jsonb := '[]'::jsonb;
  v_should_dirty boolean := false;
  v_old_authorised boolean := false;
  v_new_authorised boolean := false;
  v_old_has_settled boolean := false;
  v_new_has_settled boolean := false;
  v_old_has_linked_banking_effect boolean := false;
  v_new_has_linked_banking_effect boolean := false;
  v_tsfin_gate_changed boolean := false;
BEGIN
  IF TG_OP <> 'DELETE' THEN
    v_new_row := to_jsonb(NEW);
  END IF;

  IF TG_OP <> 'INSERT' THEN
    v_old_row := to_jsonb(OLD);
  END IF;

  IF v_trigger_table = 'timesheets' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;
    v_old_contract_id := NULLIF(BTRIM(COALESCE(v_old_row->>'contract_id', '')), '')::uuid;
    v_new_contract_id := NULLIF(BTRIM(COALESCE(v_new_row->>'contract_id', '')), '')::uuid;
    v_old_booking_id := NULLIF(BTRIM(COALESCE(v_old_row->>'booking_id', '')), '');
    v_new_booking_id := NULLIF(BTRIM(COALESCE(v_new_row->>'booking_id', '')), '');

    SELECT array_cat(
             array_cat(
               ARRAY[
                 (
                   SELECT ct.candidate_id
                   FROM public.contracts AS ct
                   WHERE ct.id = v_old_contract_id
                   LIMIT 1
                 ),
                 (
                   SELECT ct.candidate_id
                   FROM public.contracts AS ct
                   WHERE ct.id = v_new_contract_id
                   LIMIT 1
                 )
               ]::uuid[],
               ARRAY[
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_old_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 ),
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_new_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 )
               ]::uuid[]
             ),
             ARRAY[]::uuid[]
           )
    INTO v_candidate_ids;

    v_old_authorised := (NULLIF(BTRIM(COALESCE(v_old_row->>'authorised_at_server', '')), '') IS NOT NULL)
                        AND (NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL);
    v_new_authorised := (NULLIF(BTRIM(COALESCE(v_new_row->>'authorised_at_server', '')), '') IS NOT NULL)
                        AND (NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL);

    SELECT EXISTS (
      SELECT 1
      FROM public.timesheet_pay_state AS tps
      WHERE tps.timesheet_id = v_old_timesheet_id
        AND (
          tps.last_settled_snapshot_json IS NOT NULL
          OR tps.last_settled_signature IS NOT NULL
          OR tps.last_settled_pay_batch_id IS NOT NULL
          OR tps.last_settled_at_utc IS NOT NULL
        )
    )
    INTO v_old_has_settled;

    SELECT EXISTS (
      SELECT 1
      FROM public.timesheet_pay_state AS tps
      WHERE tps.timesheet_id = v_new_timesheet_id
        AND (
          tps.last_settled_snapshot_json IS NOT NULL
          OR tps.last_settled_signature IS NOT NULL
          OR tps.last_settled_pay_batch_id IS NOT NULL
          OR tps.last_settled_at_utc IS NOT NULL
        )
    )
    INTO v_new_has_settled;

    SELECT EXISTS (
      SELECT 1
      FROM public.timesheet_payment_overrides AS tpo
      WHERE tpo.timesheet_id = v_old_timesheet_id
        AND tpo.cleared_at_utc IS NULL
        AND tpo.consumed_at_utc IS NULL
        AND tpo.consumed_by_pay_batch_id IS NULL
    )
    OR EXISTS (
      SELECT 1
      FROM public.pay_item_snoozes AS pis
      WHERE pis.cleared_at_utc IS NULL
        AND (
          pis.timesheet_id = v_old_timesheet_id
          OR (v_old_booking_id IS NOT NULL AND pis.booking_id = v_old_booking_id)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.pay_advances AS pa
      WHERE pa.linked_timesheet_id = v_old_timesheet_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.ts_pay_adjustments AS tpa
      WHERE tpa.timesheet_id = v_old_timesheet_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.timesheets_financials AS tf
      WHERE tf.timesheet_id = v_old_timesheet_id
        AND tf.is_current = true
        AND (
          tf.locked_by_invoice_id IS NOT NULL
          OR tf.paid_at_utc IS NOT NULL
          OR tf.locked_at_utc IS NOT NULL
        )
    )
    INTO v_old_has_linked_banking_effect;

    SELECT EXISTS (
      SELECT 1
      FROM public.timesheet_payment_overrides AS tpo
      WHERE tpo.timesheet_id = v_new_timesheet_id
        AND tpo.cleared_at_utc IS NULL
        AND tpo.consumed_at_utc IS NULL
        AND tpo.consumed_by_pay_batch_id IS NULL
    )
    OR EXISTS (
      SELECT 1
      FROM public.pay_item_snoozes AS pis
      WHERE pis.cleared_at_utc IS NULL
        AND (
          pis.timesheet_id = v_new_timesheet_id
          OR (v_new_booking_id IS NOT NULL AND pis.booking_id = v_new_booking_id)
        )
    )
    OR EXISTS (
      SELECT 1
      FROM public.pay_advances AS pa
      WHERE pa.linked_timesheet_id = v_new_timesheet_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.ts_pay_adjustments AS tpa
      WHERE tpa.timesheet_id = v_new_timesheet_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.timesheets_financials AS tf
      WHERE tf.timesheet_id = v_new_timesheet_id
        AND tf.is_current = true
        AND (
          tf.locked_by_invoice_id IS NOT NULL
          OR tf.paid_at_utc IS NOT NULL
          OR tf.locked_at_utc IS NOT NULL
        )
    )
    INTO v_new_has_linked_banking_effect;

    IF TG_OP = 'DELETE' THEN
      IF v_old_authorised OR v_old_has_settled OR v_old_has_linked_banking_effect THEN
        v_should_dirty := true;
      END IF;
    ELSE
      IF (v_old_authorised IS DISTINCT FROM v_new_authorised)
         OR ((NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL) IS DISTINCT FROM (NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL)) THEN
        v_should_dirty := true;
      END IF;
    END IF;

    IF v_should_dirty THEN
      IF TG_OP <> 'DELETE'
         AND (
           (v_old_authorised IS DISTINCT FROM v_new_authorised)
           OR ((NULLIF(BTRIM(COALESCE(v_old_row->>'revoked_at', '')), '') IS NULL) IS DISTINCT FROM (NULLIF(BTRIM(COALESCE(v_new_row->>'revoked_at', '')), '') IS NULL))
         ) THEN
        v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
      ELSE
        v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      END IF;
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    END IF;

  ELSIF v_trigger_table = 'timesheets_financials' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;

    v_candidate_ids := array_cat(
      v_candidate_ids,
      ARRAY[
        NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid,
        NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
      ]::uuid[]
    );

    v_tsfin_gate_changed :=
      COALESCE(v_old_row->>'pay_on_hold', '') IS DISTINCT FROM COALESCE(v_new_row->>'pay_on_hold', '')
      OR COALESCE(v_old_row->>'has_rate_issue', '') IS DISTINCT FROM COALESCE(v_new_row->>'has_rate_issue', '')
      OR COALESCE(v_old_row->>'has_pay_channel_issue', '') IS DISTINCT FROM COALESCE(v_new_row->>'has_pay_channel_issue', '')
      OR COALESCE(v_old_row->>'processing_status', '') IS DISTINCT FROM COALESCE(v_new_row->>'processing_status', '')
      OR COALESCE(v_old_row->>'candidate_id', '') IS DISTINCT FROM COALESCE(v_new_row->>'candidate_id', '')
      OR COALESCE(v_old_row->>'client_id', '') IS DISTINCT FROM COALESCE(v_new_row->>'client_id', '')
      OR COALESCE(v_old_row->>'pay_method', '') IS DISTINCT FROM COALESCE(v_new_row->>'pay_method', '')
      OR COALESCE(v_old_row->>'is_current', '') IS DISTINCT FROM COALESCE(v_new_row->>'is_current', '');

    SELECT EXISTS (
      SELECT 1
      FROM public.timesheets AS ts
      WHERE ts.timesheet_id = COALESCE(v_new_timesheet_id, v_old_timesheet_id)
        AND (
          (ts.authorised_at_server IS NOT NULL AND ts.revoked_at IS NULL)
          OR EXISTS (
            SELECT 1
            FROM public.timesheet_pay_state AS tps
            WHERE tps.timesheet_id = ts.timesheet_id
              AND (
                tps.last_settled_snapshot_json IS NOT NULL
                OR tps.last_settled_signature IS NOT NULL
                OR tps.last_settled_pay_batch_id IS NOT NULL
                OR tps.last_settled_at_utc IS NOT NULL
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.timesheet_payment_overrides AS tpo
            WHERE tpo.timesheet_id = ts.timesheet_id
              AND tpo.cleared_at_utc IS NULL
              AND tpo.consumed_at_utc IS NULL
              AND tpo.consumed_by_pay_batch_id IS NULL
          )
        )
    )
    INTO v_should_dirty;

    v_should_dirty := v_should_dirty AND v_tsfin_gate_changed;

    IF v_should_dirty THEN
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    END IF;

  ELSIF v_trigger_table = 'timesheet_pay_state' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;

    SELECT array_cat(
             array_cat(
               ARRAY[
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_old_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 ),
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_new_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 )
               ]::uuid[],
               ARRAY[
                 (
                   SELECT ct.candidate_id
                   FROM public.timesheets AS ts
                   JOIN public.contracts AS ct
                     ON ct.id = ts.contract_id
                   WHERE ts.timesheet_id = v_old_timesheet_id
                   LIMIT 1
                 ),
                 (
                   SELECT ct.candidate_id
                   FROM public.timesheets AS ts
                   JOIN public.contracts AS ct
                     ON ct.id = ts.contract_id
                   WHERE ts.timesheet_id = v_new_timesheet_id
                   LIMIT 1
                 )
               ]::uuid[]
             ),
             ARRAY[]::uuid[]
           )
    INTO v_candidate_ids;

    v_old_has_settled :=
      (NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_snapshot_json', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_signature', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_pay_batch_id', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_old_row->>'last_settled_at_utc', '')), '') IS NOT NULL);

    v_new_has_settled :=
      (NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_snapshot_json', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_signature', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_pay_batch_id', '')), '') IS NOT NULL)
      OR (NULLIF(BTRIM(COALESCE(v_new_row->>'last_settled_at_utc', '')), '') IS NOT NULL);

    IF v_old_has_settled AND NOT v_new_has_settled THEN
      v_should_dirty := true;
      v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      v_targeted_timesheet_uuid_ids := array_cat(
        v_targeted_timesheet_uuid_ids,
        ARRAY[COALESCE(v_new_timesheet_id, v_old_timesheet_id)]::uuid[]
      );
    END IF;

  ELSIF v_trigger_table = 'timesheet_payment_overrides' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;

    SELECT array_cat(
             array_cat(
               ARRAY[
                 NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid,
                 NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
               ]::uuid[],
               ARRAY[
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_old_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 ),
                 (
                   SELECT tf.candidate_id
                   FROM public.timesheets_financials AS tf
                   WHERE tf.timesheet_id = v_new_timesheet_id
                     AND tf.is_current = true
                   ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                   LIMIT 1
                 )
               ]::uuid[]
             ),
             ARRAY[]::uuid[]
           )
    INTO v_candidate_ids;

    v_should_dirty := true;
    IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
      v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    ELSE
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;

  ELSIF v_trigger_table = 'pay_item_snoozes' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;
    v_old_booking_id := NULLIF(BTRIM(COALESCE(v_old_row->>'booking_id', '')), '');
    v_new_booking_id := NULLIF(BTRIM(COALESCE(v_new_row->>'booking_id', '')), '');

    SELECT array_cat(
             array_cat(
               array_cat(
                 ARRAY[
                   NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid,
                   NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
                 ]::uuid[],
                 ARRAY[
                   (
                     SELECT tf.candidate_id
                     FROM public.timesheets_financials AS tf
                     WHERE tf.timesheet_id = v_old_timesheet_id
                       AND tf.is_current = true
                     ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                     LIMIT 1
                   ),
                   (
                     SELECT tf.candidate_id
                     FROM public.timesheets_financials AS tf
                     WHERE tf.timesheet_id = v_new_timesheet_id
                       AND tf.is_current = true
                     ORDER BY tf.computed_at_utc DESC NULLS LAST, tf.id DESC
                     LIMIT 1
                   )
                 ]::uuid[]
               ),
               ARRAY[
                 (
                   SELECT COALESCE(tf.candidate_id, ct.candidate_id)
                   FROM public.timesheets AS ts
                   LEFT JOIN public.timesheets_financials AS tf
                     ON tf.timesheet_id = ts.timesheet_id
                    AND tf.is_current = true
                   LEFT JOIN public.contracts AS ct
                     ON ct.id = ts.contract_id
                   WHERE ts.booking_id = v_old_booking_id
                   ORDER BY ts.updated_at DESC NULLS LAST, ts.timesheet_id DESC
                   LIMIT 1
                 ),
                 (
                   SELECT COALESCE(tf.candidate_id, ct.candidate_id)
                   FROM public.timesheets AS ts
                   LEFT JOIN public.timesheets_financials AS tf
                     ON tf.timesheet_id = ts.timesheet_id
                    AND tf.is_current = true
                   LEFT JOIN public.contracts AS ct
                     ON ct.id = ts.contract_id
                   WHERE ts.booking_id = v_new_booking_id
                   ORDER BY ts.updated_at DESC NULLS LAST, ts.timesheet_id DESC
                   LIMIT 1
                 )
               ]::uuid[]
             ),
             ARRAY[]::uuid[]
           )
    INTO v_candidate_ids;

    SELECT COALESCE(array_agg(DISTINCT ts.timesheet_id), ARRAY[]::uuid[])
    INTO v_linked_timesheet_uuid_ids
    FROM public.timesheets AS ts
    WHERE (v_old_booking_id IS NOT NULL AND ts.booking_id = v_old_booking_id)
       OR (v_new_booking_id IS NOT NULL AND ts.booking_id = v_new_booking_id);

    v_should_dirty := true;
    IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL OR COALESCE(array_length(v_linked_timesheet_uuid_ids, 1), 0) > 0 THEN
      v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    ELSE
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;

  ELSIF v_trigger_table = 'ts_pay_adjustments' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'timesheet_id', '')), '')::uuid;

    v_candidate_ids := array_cat(
      v_candidate_ids,
      ARRAY[
        NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid,
        NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
      ]::uuid[]
    );

    v_should_dirty := true;
    IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
      v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    ELSE
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;

  ELSIF v_trigger_table = 'pay_advances' THEN
    v_old_timesheet_id := NULLIF(BTRIM(COALESCE(v_old_row->>'linked_timesheet_id', '')), '')::uuid;
    v_new_timesheet_id := NULLIF(BTRIM(COALESCE(v_new_row->>'linked_timesheet_id', '')), '')::uuid;

    v_candidate_ids := array_cat(
      v_candidate_ids,
      ARRAY[
        NULLIF(BTRIM(COALESCE(v_old_row->>'candidate_id', '')), '')::uuid,
        NULLIF(BTRIM(COALESCE(v_new_row->>'candidate_id', '')), '')::uuid
      ]::uuid[]
    );

    v_should_dirty := true;
    IF v_old_timesheet_id IS NOT NULL OR v_new_timesheet_id IS NOT NULL THEN
      v_refresh_scope_kind := 'TARGETED_TIMESHEETS';
      v_targeted_timesheet_uuid_ids := array_cat(v_targeted_timesheet_uuid_ids, ARRAY[v_old_timesheet_id, v_new_timesheet_id]::uuid[]);
    ELSE
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;

  ELSIF v_trigger_table IN ('bank_name_checks', 'bank_payee_map') THEN
    SELECT array_cat(
             CASE
               WHEN upper(COALESCE(v_old_row->>'entity_kind', '')) = 'CANDIDATE'
                 THEN ARRAY[NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid]
               WHEN upper(COALESCE(v_old_row->>'entity_kind', '')) = 'UMBRELLA'
                 THEN COALESCE(
                   (
                     SELECT array_agg(DISTINCT c.id)
                     FROM public.candidates AS c
                     WHERE c.umbrella_id = NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), '')::uuid
                   ),
                   ARRAY[]::uuid[]
                 )
               ELSE ARRAY[]::uuid[]
             END,
             CASE
               WHEN upper(COALESCE(v_new_row->>'entity_kind', '')) = 'CANDIDATE'
                 THEN ARRAY[NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid]
               WHEN upper(COALESCE(v_new_row->>'entity_kind', '')) = 'UMBRELLA'
                 THEN COALESCE(
                   (
                     SELECT array_agg(DISTINCT c.id)
                     FROM public.candidates AS c
                     WHERE c.umbrella_id = NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')::uuid
                   ),
                   ARRAY[]::uuid[]
                 )
               ELSE ARRAY[]::uuid[]
             END
           )
    INTO v_candidate_ids;

    v_should_dirty := true;
    v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';

  ELSIF v_trigger_table = 'candidates' THEN
    v_candidate_ids := array_cat(
      v_candidate_ids,
      ARRAY[
        NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid,
        NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
      ]::uuid[]
    );

    IF COALESCE(v_old_row->>'pay_method', '') IS DISTINCT FROM COALESCE(v_new_row->>'pay_method', '')
       OR COALESCE(v_old_row->>'umbrella_id', '') IS DISTINCT FROM COALESCE(v_new_row->>'umbrella_id', '')
       OR COALESCE(v_old_row->>'bank_details_hash', '') IS DISTINCT FROM COALESCE(v_new_row->>'bank_details_hash', '')
       OR COALESCE(v_old_row->>'account_holder', '') IS DISTINCT FROM COALESCE(v_new_row->>'account_holder', '')
       OR COALESCE(v_old_row->>'bank_name', '') IS DISTINCT FROM COALESCE(v_new_row->>'bank_name', '')
       OR COALESCE(v_old_row->>'sort_code', '') IS DISTINCT FROM COALESCE(v_new_row->>'sort_code', '')
       OR COALESCE(v_old_row->>'account_number', '') IS DISTINCT FROM COALESCE(v_new_row->>'account_number', '')
       OR COALESCE(v_old_row->>'min_take_home_wtd', '') IS DISTINCT FROM COALESCE(v_new_row->>'min_take_home_wtd', '') THEN
      v_should_dirty := true;
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;

  ELSIF v_trigger_table = 'umbrellas' THEN
    SELECT COALESCE(array_agg(DISTINCT c.id), ARRAY[]::uuid[])
    INTO v_candidate_ids
    FROM public.candidates AS c
    WHERE c.umbrella_id IN (
      NULLIF(BTRIM(COALESCE(v_old_row->>'id', '')), '')::uuid,
      NULLIF(BTRIM(COALESCE(v_new_row->>'id', '')), '')::uuid
    );

    IF TG_OP IN ('INSERT', 'DELETE')
       OR COALESCE(v_old_row->>'enabled', '') IS DISTINCT FROM COALESCE(v_new_row->>'enabled', '')
       OR COALESCE(v_old_row->>'vat_chargeable', '') IS DISTINCT FROM COALESCE(v_new_row->>'vat_chargeable', '')
       OR COALESCE(v_old_row->>'bank_details_hash', '') IS DISTINCT FROM COALESCE(v_new_row->>'bank_details_hash', '')
       OR COALESCE(v_old_row->>'bank_name', '') IS DISTINCT FROM COALESCE(v_new_row->>'bank_name', '')
       OR COALESCE(v_old_row->>'sort_code', '') IS DISTINCT FROM COALESCE(v_new_row->>'sort_code', '')
       OR COALESCE(v_old_row->>'account_number', '') IS DISTINCT FROM COALESCE(v_new_row->>'account_number', '') THEN
      v_should_dirty := true;
      v_refresh_scope_kind := 'CANDIDATE_FULL_LIVE';
    END IF;
  END IF;

  SELECT COALESCE(array_agg(DISTINCT x.candidate_id), ARRAY[]::uuid[])
  INTO v_candidate_ids
  FROM unnest(COALESCE(v_candidate_ids, ARRAY[]::uuid[])) AS x(candidate_id)
  WHERE x.candidate_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT x.timesheet_id), ARRAY[]::uuid[])
  INTO v_targeted_timesheet_uuid_ids
  FROM unnest(COALESCE(v_targeted_timesheet_uuid_ids, ARRAY[]::uuid[])) AS x(timesheet_id)
  WHERE x.timesheet_id IS NOT NULL;

  SELECT COALESCE(array_agg(DISTINCT x.timesheet_id), ARRAY[]::uuid[])
  INTO v_linked_timesheet_uuid_ids
  FROM unnest(COALESCE(v_linked_timesheet_uuid_ids, ARRAY[]::uuid[])) AS x(timesheet_id)
  WHERE x.timesheet_id IS NOT NULL;

  SELECT COALESCE(jsonb_agg(to_jsonb(x.timesheet_id::text) ORDER BY x.timesheet_id::text), '[]'::jsonb)
  INTO v_targeted_timesheet_ids_json
  FROM unnest(COALESCE(v_targeted_timesheet_uuid_ids, ARRAY[]::uuid[])) AS x(timesheet_id);

  SELECT COALESCE(jsonb_agg(to_jsonb(x.timesheet_id::text) ORDER BY x.timesheet_id::text), '[]'::jsonb)
  INTO v_linked_timesheet_ids_json
  FROM unnest(COALESCE(v_linked_timesheet_uuid_ids, ARRAY[]::uuid[])) AS x(timesheet_id);

  IF COALESCE(array_length(v_candidate_ids, 1), 0) = 0 OR v_should_dirty = false THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  FOREACH v_candidate_id IN ARRAY v_candidate_ids
  LOOP
    PERFORM public._change_bump('pay_candidate:' || v_candidate_id::text);

    SELECT COALESCE(acc.seq, 0)
    INTO v_live_change_seq
    FROM public.app_change_counters AS acc
    WHERE acc.entity_key = 'pay_candidate:' || v_candidate_id::text;

    v_reason := 'DIRTY_TRIGGER:' || upper(v_trigger_table) || ':' || TG_OP;
    v_payload_json := jsonb_build_object(
      'trigger_table', v_trigger_table,
      'trigger_op', TG_OP,
      'scope_kind', 'CANDIDATE',
      'scope_id', v_candidate_id::text,
      'candidate_id', v_candidate_id::text,
      'reason', v_reason,
      'source_change_seq', v_live_change_seq,
      'refresh_scope_kind', v_refresh_scope_kind,
      'targeted_timesheet_ids', v_targeted_timesheet_ids_json,
      'linked_timesheet_ids', v_linked_timesheet_ids_json,
      'old_timesheet_id', CASE WHEN v_old_timesheet_id IS NULL THEN NULL ELSE v_old_timesheet_id::text END,
      'new_timesheet_id', CASE WHEN v_new_timesheet_id IS NULL THEN NULL ELSE v_new_timesheet_id::text END,
      'old_contract_id', CASE WHEN v_old_contract_id IS NULL THEN NULL ELSE v_old_contract_id::text END,
      'new_contract_id', CASE WHEN v_new_contract_id IS NULL THEN NULL ELSE v_new_contract_id::text END,
      'old_booking_id', CASE WHEN v_old_booking_id IS NULL THEN NULL ELSE v_old_booking_id::text END,
      'new_booking_id', CASE WHEN v_new_booking_id IS NULL THEN NULL ELSE v_new_booking_id::text END,
      'old_entity_kind', NULLIF(BTRIM(COALESCE(v_old_row->>'entity_kind', '')), ''),
      'new_entity_kind', NULLIF(BTRIM(COALESCE(v_new_row->>'entity_kind', '')), ''),
      'old_entity_id', NULLIF(BTRIM(COALESCE(v_old_row->>'entity_id', '')), ''),
      'new_entity_id', NULLIF(BTRIM(COALESCE(v_new_row->>'entity_id', '')), '')
    );
    v_dedupe_key := 'CONTRACT_CLIENT_DIRTY_FANOUT:CANDIDATE:' || v_candidate_id::text;

    INSERT INTO public.banking_pay_workbench_jobs (
      job_type,
      status,
      priority,
      run_at_utc,
      attempt_count,
      max_attempts,
      dedupe_key,
      snapshot_run_id,
      session_id,
      candidate_id,
      payload_json,
      created_at_utc,
      updated_at_utc,
      started_at_utc,
      completed_at_utc,
      failed_at_utc,
      last_error_json
    )
    VALUES (
      'CONTRACT_CLIENT_DIRTY_FANOUT',
      'QUEUED',
      200,
      v_now,
      0,
      8,
      v_dedupe_key,
      NULL,
      NULL,
      v_candidate_id,
      v_payload_json,
      v_now,
      v_now,
      NULL,
      NULL,
      NULL,
      NULL
    )
    ON CONFLICT (dedupe_key) WHERE status IN ('QUEUED', 'RUNNING')
    DO UPDATE
    SET priority = LEAST(public.banking_pay_workbench_jobs.priority, EXCLUDED.priority),
        run_at_utc = LEAST(public.banking_pay_workbench_jobs.run_at_utc, EXCLUDED.run_at_utc),
        candidate_id = COALESCE(public.banking_pay_workbench_jobs.candidate_id, EXCLUDED.candidate_id),
        payload_json = public._pay_workbench_merge_targeted_scope_payload(
          COALESCE(public.banking_pay_workbench_jobs.payload_json, '{}'::jsonb),
          COALESCE(EXCLUDED.payload_json, '{}'::jsonb)
        ),
        updated_at_utc = v_now;

    UPDATE public.banking_pay_workbench_session_candidate_state AS scs
    SET status = 'PENDING',
        effective_candidate_fragment_json = '{}'::jsonb,
        effective_summary_fragment_json = '{}'::jsonb,
        effective_paye_candidate_json = NULL,
        effective_non_paye_payee_json = NULL,
        effective_payees_json = '[]'::jsonb,
        effective_case_resolution_states_json = '[]'::jsonb,
        effective_canonical_preview_lines_json = '[]'::jsonb,
        source_change_seq = GREATEST(COALESCE(scs.source_change_seq, 0), v_live_change_seq),
        pending_job_id = NULL,
        updated_at_utc = v_now,
        last_recomputed_at_utc = NULL,
        last_error_json = NULL
    FROM public.banking_pay_workbench_sessions AS ws
    WHERE ws.id = scs.session_id
      AND ws.status = 'OPEN'
      AND ws.discarded_at_utc IS NULL
      AND ws.week_ending_cutoff = DATE '9999-12-31'
      AND scs.candidate_id = v_candidate_id
      AND ws.scope_candidate_ids @> ARRAY[v_candidate_id]::uuid[];
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_workbench_session_clear_all_decisions(p_session_id uuid, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_session_row public.banking_pay_workbench_sessions%ROWTYPE;
  v_scope_candidate_id uuid := NULL::uuid;
  v_deleted_case_resolution_count integer := 0;
  v_deleted_override_count integer := 0;
  v_selected_preview_row_count integer := 0;
  v_cleared_session_candidate_state_count integer := 0;
  v_new_session_version bigint := 0;
  v_job_json jsonb := '{}'::jsonb;
  v_job_id uuid := NULL::uuid;
  v_requeue_candidate_count integer := 0;
  v_requeue_job_count integer := 0;
  v_deleted_case_resolution_ids jsonb := '[]'::jsonb;
  v_deleted_override_ids jsonb := '[]'::jsonb;
  v_requeue_candidate_ids jsonb := '[]'::jsonb;
  v_requeue_job_ids jsonb := '[]'::jsonb;
  v_audit_before_json jsonb := NULL;
  v_audit_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'session_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  PERFORM 1
  FROM public.tms_users AS tu
  WHERE tu.id = p_actor_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
  END IF;

  SELECT ws.*
  INTO v_session_row
  FROM public.banking_pay_workbench_sessions AS ws
  WHERE ws.id = p_session_id
  FOR UPDATE;

  IF v_session_row.id IS NULL THEN
    RAISE EXCEPTION 'banking_pay_workbench_sessions row % not found', p_session_id;
  END IF;

  IF v_session_row.status <> 'OPEN' THEN
    RAISE EXCEPTION 'banking_pay_workbench_session % is not OPEN', p_session_id;
  END IF;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(case_resolution_row.id::text ORDER BY case_resolution_row.id::text), '[]'::jsonb)
  INTO v_deleted_case_resolution_count,
       v_deleted_case_resolution_ids
  FROM public.banking_pay_workbench_session_case_resolutions AS case_resolution_row
  WHERE case_resolution_row.session_id = p_session_id;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(override_row.id::text ORDER BY override_row.id::text), '[]'::jsonb)
  INTO v_deleted_override_count,
       v_deleted_override_ids
  FROM public.banking_pay_workbench_session_overrides AS override_row
  WHERE override_row.session_id = p_session_id;

  v_selected_preview_row_count := CASE
    WHEN jsonb_typeof(COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb)) = 'array'
      THEN jsonb_array_length(COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb))
    ELSE 0
  END;

  v_audit_before_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'actor_user_id', v_session_row.actor_user_id::text,
    'pay_date', v_session_row.pay_date::text,
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'filters_json', v_session_row.filters_json,
    'scope_candidate_ids', to_jsonb(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])),
    'session_signature', v_session_row.session_signature,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'status', v_session_row.status,
    'version', v_session_row.version,
    'server_selected_preview_row_ids', COALESCE(v_session_row.server_selected_preview_row_ids, '[]'::jsonb),
    'server_selected_preview_row_ids_provided', COALESCE(v_session_row.server_selected_preview_row_ids_provided, false),
    'case_resolution_count', v_deleted_case_resolution_count,
    'case_resolution_ids', v_deleted_case_resolution_ids,
    'override_count', v_deleted_override_count,
    'override_ids', v_deleted_override_ids,
    'selected_preview_row_count', v_selected_preview_row_count
  );

  DELETE FROM public.banking_pay_workbench_session_case_resolutions AS case_resolution_delete
  WHERE case_resolution_delete.session_id = p_session_id;

  DELETE FROM public.banking_pay_workbench_session_overrides AS override_delete
  WHERE override_delete.session_id = p_session_id;

  UPDATE public.banking_pay_workbench_sessions AS ws
  SET actor_user_id = p_actor_user_id,
      server_selected_preview_row_ids = '[]'::jsonb,
      server_selected_preview_row_ids_provided = false,
      version = ws.version + 1,
      updated_at_utc = v_now
  WHERE ws.id = p_session_id
  RETURNING ws.version
  INTO v_new_session_version;

  UPDATE public.banking_pay_workbench_session_candidate_state AS scs
  SET status = 'PENDING',
      effective_candidate_fragment_json = '{}'::jsonb,
      effective_summary_fragment_json = '{}'::jsonb,
      effective_paye_candidate_json = NULL,
      effective_non_paye_payee_json = NULL,
      effective_payees_json = '[]'::jsonb,
      effective_case_resolution_states_json = '[]'::jsonb,
      effective_canonical_preview_lines_json = '[]'::jsonb,
      session_version = GREATEST(COALESCE(scs.session_version, 0), v_new_session_version),
      pending_job_id = NULL::uuid,
      updated_at_utc = v_now,
      last_recomputed_at_utc = NULL,
      last_error_json = NULL
  WHERE scs.session_id = p_session_id
    AND scs.candidate_id = ANY(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[]));

  GET DIAGNOSTICS v_cleared_session_candidate_state_count = ROW_COUNT;

  FOR v_scope_candidate_id IN
    SELECT DISTINCT session_scope_candidate_ids.candidate_id
    FROM unnest(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])) AS session_scope_candidate_ids(candidate_id)
    WHERE session_scope_candidate_ids.candidate_id IS NOT NULL
    ORDER BY session_scope_candidate_ids.candidate_id
  LOOP
    v_job_json := public.pay_workbench_enqueue_session_candidate_refresh(
      p_session_id => p_session_id,
      p_candidate_id => v_scope_candidate_id,
      p_reason => 'SESSION_DECISIONS_CLEARED',
      p_actor_user_id => p_actor_user_id,
      p_payload_json => jsonb_build_object(
        'clear_all_decisions', true,
        'cleared_case_resolution_count', v_deleted_case_resolution_count,
        'cleared_override_count', v_deleted_override_count,
        'cleared_selected_preview_row_count', v_selected_preview_row_count
      )
    );

    v_requeue_candidate_ids := v_requeue_candidate_ids || jsonb_build_array(v_scope_candidate_id::text);
    v_requeue_candidate_count := v_requeue_candidate_count + 1;

    v_job_id := NULL::uuid;
    IF BTRIM(COALESCE(v_job_json->>'job_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_job_id := (v_job_json->>'job_id')::uuid;
      v_requeue_job_ids := v_requeue_job_ids || jsonb_build_array(v_job_id::text);
      v_requeue_job_count := v_requeue_job_count + 1;
    END IF;
  END LOOP;

  v_audit_after_json := jsonb_build_object(
    'id', v_session_row.id::text,
    'actor_user_id', p_actor_user_id::text,
    'pay_date', v_session_row.pay_date::text,
    'week_ending_cutoff', v_session_row.week_ending_cutoff::text,
    'filters_json', v_session_row.filters_json,
    'scope_candidate_ids', to_jsonb(COALESCE(v_session_row.scope_candidate_ids, ARRAY[]::uuid[])),
    'session_signature', v_session_row.session_signature,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'status', v_session_row.status,
    'version', v_new_session_version,
    'server_selected_preview_row_ids', '[]'::jsonb,
    'server_selected_preview_row_ids_provided', false,
    'cleared_case_resolution_count', v_deleted_case_resolution_count,
    'cleared_case_resolution_ids', v_deleted_case_resolution_ids,
    'cleared_override_count', v_deleted_override_count,
    'cleared_override_ids', v_deleted_override_ids,
    'cleared_selected_preview_row_count', v_selected_preview_row_count,
    'cleared_session_candidate_state_count', v_cleared_session_candidate_state_count,
    'requeue_candidate_count', v_requeue_candidate_count,
    'requeue_candidate_ids', v_requeue_candidate_ids,
    'requeue_job_count', v_requeue_job_count,
    'requeue_job_ids', v_requeue_job_ids,
    'shared_snapshot_truth_touched', false,
    'snapshot_run_deactivated', false,
    'session_deleted', false,
    'decisions_cleared_at_utc', v_now
  );

  PERFORM public._audit_insert(
    'banking_pay_workbench_session',
    p_session_id::text,
    'WORKBENCH_SESSION_DECISIONS_CLEARED',
    v_audit_before_json,
    v_audit_after_json,
    'SESSION_DECISIONS_CLEARED',
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'session_id', p_session_id::text,
    'source_snapshot_run_id', CASE WHEN v_session_row.source_snapshot_run_id IS NULL THEN NULL ELSE v_session_row.source_snapshot_run_id::text END,
    'status', v_session_row.status,
    'session_version', v_new_session_version,
    'server_selected_preview_row_ids', '[]'::jsonb,
    'server_selected_preview_row_ids_provided', false,
    'cleared_case_resolution_count', v_deleted_case_resolution_count,
    'cleared_override_count', v_deleted_override_count,
    'cleared_selected_preview_row_count', v_selected_preview_row_count,
    'cleared_session_candidate_state_count', v_cleared_session_candidate_state_count,
    'requeue_candidate_count', v_requeue_candidate_count,
    'requeue_candidate_ids', v_requeue_candidate_ids,
    'requeue_job_count', v_requeue_job_count,
    'requeue_job_ids', v_requeue_job_ids,
    'state_changed', true
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public._pay_workbench_candidate_projection_contract()
RETURNS jsonb
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_projection_version integer := 4;
  v_hidden_recovery_template_projection_version integer := 1;
  v_requires_hidden_recovery_templates boolean := true;
BEGIN
  RETURN jsonb_build_object(
    'projection_version', v_projection_version,
    'hidden_recovery_template_projection_version', v_hidden_recovery_template_projection_version,
    'requires_hidden_recovery_templates', v_requires_hidden_recovery_templates
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public._pay_batch_item_source_reservation_amount_ex_vat(p_pay_batch_item_id uuid)
RETURNS numeric(12,2)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_item_type text;
  v_finance_case_id uuid;
  v_finance_component_id uuid;
  v_amount_ex_vat numeric;
  v_frozen_source_amount numeric;
  v_frozen_target_amount_ex_vat numeric;
  v_frozen_resolution_mode public.pay_finance_component_resolution_mode_enum;
  v_frozen_resolution_payload_json jsonb;
  v_frozen_resolution_result_json jsonb;
  v_frozen_component_snapshot_json jsonb;
  v_frozen_source_basis_json jsonb;
  v_source_text text;
  v_has_source_target_split boolean;
BEGIN
  IF p_pay_batch_item_id IS NULL THEN
    RETURN NULL::numeric(12,2);
  END IF;

  SELECT
    upper(nullif(btrim(coalesce(pbi.item_type, '')), '')),
    pbi.finance_case_id,
    pbi.finance_component_id,
    pbi.amount_ex_vat,
    pbi.frozen_source_amount,
    pbi.frozen_target_amount_ex_vat,
    pbi.frozen_resolution_mode,
    pbi.frozen_resolution_payload_json,
    pbi.frozen_resolution_result_json,
    coalesce(pbi.frozen_component_snapshot_json, '{}'::jsonb),
    coalesce(pbi.frozen_source_basis_json, '{}'::jsonb)
  INTO
    v_item_type,
    v_finance_case_id,
    v_finance_component_id,
    v_amount_ex_vat,
    v_frozen_source_amount,
    v_frozen_target_amount_ex_vat,
    v_frozen_resolution_mode,
    v_frozen_resolution_payload_json,
    v_frozen_resolution_result_json,
    v_frozen_component_snapshot_json,
    v_frozen_source_basis_json
  FROM public.pay_batch_items AS pbi
  WHERE pbi.id = p_pay_batch_item_id;

  IF NOT FOUND THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_item_type NOT IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA') THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_frozen_source_amount IS NOT NULL THEN
    RETURN round(abs(v_frozen_source_amount), 2)::numeric(12,2);
  END IF;

  SELECT source_candidates.source_text_value
  INTO v_source_text
  FROM (
    VALUES
      (v_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_ex_vat'),
      (v_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
      (v_frozen_component_snapshot_json->>'reserved_source_amount'),
      (v_frozen_component_snapshot_json->>'frozen_source_amount'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,basis_source_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,pay_amount_ex_vat}'),
      (v_frozen_component_snapshot_json#>>'{source_basis_json,amount_ex_vat}'),
      (v_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_ex_vat'),
      (v_frozen_source_basis_json->>'source_pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'basis_source_amount_ex_vat'),
      (v_frozen_source_basis_json->>'reserved_source_amount'),
      (v_frozen_source_basis_json->>'frozen_source_amount'),
      (v_frozen_source_basis_json->>'pay_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount_ex_vat'),
      (v_frozen_source_basis_json->>'amount_ex_vat'),
      (v_frozen_source_basis_json->>'pay_amount')
  ) AS source_candidates(source_text_value)
  WHERE source_candidates.source_text_value IS NOT NULL
    AND btrim(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
  LIMIT 1;

  IF v_source_text IS NOT NULL THEN
    RETURN round(abs(v_source_text::numeric), 2)::numeric(12,2);
  END IF;

  v_has_source_target_split :=
       v_finance_case_id IS NOT NULL
    OR v_finance_component_id IS NOT NULL
    OR v_frozen_target_amount_ex_vat IS NOT NULL
    OR v_frozen_resolution_mode IS NOT NULL
    OR v_frozen_resolution_payload_json IS NOT NULL
    OR v_frozen_resolution_result_json IS NOT NULL
    OR v_frozen_component_snapshot_json ? 'target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_pay_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'frozen_target_amount_ex_vat'
    OR v_frozen_component_snapshot_json ? 'target_rate'
    OR v_frozen_component_snapshot_json ? 'target_units'
    OR v_frozen_component_snapshot_json ? 'resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_mode'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_payload_json'
    OR v_frozen_component_snapshot_json ? 'saved_resolution_result_json';

  IF v_has_source_target_split THEN
    RETURN NULL::numeric(12,2);
  END IF;

  IF v_amount_ex_vat IS NOT NULL THEN
    RETURN round(abs(v_amount_ex_vat), 2)::numeric(12,2);
  END IF;

  RETURN NULL::numeric(12,2);
END;
$function$;
create or replace function public.pay_finance_case_taxable_channel_restructure_suggestion(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_effective_pay_date date default null::date,
  p_resolution_path text default 'SUGGESTED'::text,
  p_schedule_input_mode text default null::text,
  p_weeks_total integer default null::integer,
  p_weekly_due numeric default null::numeric,
  p_manual_total_remaining numeric default null::numeric,
  p_note text default null::text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_candidate record;
  v_finance_settings record;
  v_target_umbrella_vat_chargeable boolean := false;

  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));
  v_candidate_pay_method text := null;

  v_open_component_count integer := 0;
  v_source_total_ex numeric(12,2) := 0;
  v_taxable_source_total_ex numeric(12,2) := 0;
  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_taxable_target_total_ex numeric(12,2) := 0;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_requires_restructure boolean := false;
  v_has_open_batch_item boolean := false;
  v_blocked_reason text := null;

  v_restructure_start_week_start date := null;
  v_existing_weeks_remaining integer := null;
  v_selected_weeks_total integer := null;
  v_existing_weekly_due numeric(12,2) := null;
  v_selected_weekly_due numeric(12,2) := null;
  v_existing_final_week_amount numeric(12,2) := null;
  v_suggested_weekly_due numeric(12,2) := null;
  v_suggested_final_week_amount numeric(12,2) := null;
  v_selected_final_week_amount numeric(12,2) := null;
  v_schedule_sign integer := -1;

  v_manual_total_remaining_ex numeric(12,2) := null;
  v_ratio numeric := 1;
  v_delta numeric(12,2) := 0;
  v_adjust_component_id uuid := null;

  v_component_breakdown jsonb := '[]'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  if v_schedule_input_mode_norm is null then
    v_schedule_input_mode_norm := 'BY_WEEKS';
  end if;

  if v_schedule_input_mode_norm not in ('BY_WEEKS', 'BY_WEEKLY_DUE') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'SCHEDULE_INPUT_MODE_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE',
      'schedule_input_mode', p_schedule_input_mode
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKS' and p_weekly_due is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKLY_DUE_NOT_ALLOWED_WITH_BY_WEEKS',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must not be supplied when schedule_input_mode is BY_WEEKS'
    )::text;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKLY_DUE' and p_weeks_total is not null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'WEEKS_TOTAL_NOT_ALLOWED_WITH_BY_WEEKLY_DUE',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must not be supplied when schedule_input_mode is BY_WEEKLY_DUE'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  limit 1;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'CASE_TYPE_NOT_SUPPORTED'
    );
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'reason_code', 'CASE_NOT_ACTIVE'
    );
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method,
    c.umbrella_id as umbrella_id,
    u.id as target_umbrella_id,
    coalesce(u.vat_chargeable, false) as target_umbrella_vat_chargeable
  into v_candidate
  from public.candidates as c
  left join public.umbrellas as u
    on u.id = c.umbrella_id
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_candidate_pay_method = 'UMBRELLA' and v_candidate.target_umbrella_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'TARGET_UMBRELLA_CONTEXT_REQUIRED',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: candidate is currently UMBRELLA but no target umbrella company is configured for VAT/routing context',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_target_umbrella_vat_chargeable := case
    when v_candidate_pay_method = 'UMBRELLA' then coalesce(v_candidate.target_umbrella_vat_chargeable, false)
    else false
  end;

  select
    sfp.vat_rate_pct,
    sfp.erni_pct
  into v_finance_settings
  from public.settings_finance_pick(v_effective_pay_date) as sfp
  limit 1;

  if v_finance_settings.vat_rate_pct is null or v_finance_settings.erni_pct is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: finance settings missing vat_rate_pct and/or erni_pct',
      'effective_pay_date', v_effective_pay_date::text
    )::text;
  end if;

  v_relevant_erni_pct := round(v_finance_settings.erni_pct, 6);
  v_vat_rate_pct := round(v_finance_settings.vat_rate_pct, 6);

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where pbc.pay_batch_id = pb.id
      and coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    v_blocked_reason := 'CASE_ALREADY_IN_OPEN_BATCH';
  end if;

  drop table if exists pg_temp._tmp_taxable_channel_restructure_components;

  create temp table _tmp_taxable_channel_restructure_components on commit drop as
  select
    pfc.id as finance_component_id,
    pfc.finance_case_id as finance_case_id,
    pfc.candidate_id as candidate_id,
    pfc.client_id as client_id,
    pfc.linked_timesheet_id as linked_timesheet_id,
    pfc.source_family_key as source_family_key,
    pfc.component_key_type as component_key_type,
    pfc.component_key_value as component_key_value,
    pfc.classification as classification,
    upper(nullif(btrim(coalesce(pfc.source_pay_method, '')), '')) as source_pay_method,
    coalesce(pfc.source_basis_json, '{}'::jsonb) as source_basis_json,
    round(coalesce(pfc.source_amount, 0), 2)::numeric(12,2) as source_amount,
    round(coalesce(pfc.remaining_source_amount, 0), 2)::numeric(12,2) as remaining_source_amount,
    pfc.saved_target_pay_method as saved_target_pay_method,
    pfc.saved_resolution_mode as saved_resolution_mode,
    pfc.saved_resolution_payload_json as saved_resolution_payload_json,
    pfc.saved_resolution_result_json as saved_resolution_result_json,
    coalesce(pfc.is_resolution_stale, false) as is_resolution_stale,
    pfc.stale_reason as stale_reason,
    false::boolean as requires_component_conversion,
    0::numeric(12,2) as target_remaining_ex,
    0::numeric(12,2) as target_remaining_vat,
    0::numeric(12,2) as target_remaining_inc
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and round(coalesce(pfc.remaining_source_amount, 0), 2) > 0;

  select count(*)::integer
  into v_open_component_count
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'reason_code', 'NO_OPEN_REMAINING_COMPONENTS'
    );
  end if;

  select coalesce(
    bool_or(
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    false
  )
  into v_requires_restructure
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_requires_restructure is distinct from true then
    return jsonb_build_object(
      'ok', true,
      'requires_restructure', false,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'candidate_pay_method', v_candidate_pay_method,
      'reason_code', 'NO_TAXABLE_CHANNEL_MISMATCH'
    );
  end if;

  v_umbrella_vat_chargeable := v_target_umbrella_vat_chargeable;

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set
    requires_component_conversion = (
      trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and trc.source_pay_method in ('PAYE', 'UMBRELLA')
      and trc.source_pay_method <> v_candidate_pay_method
      and trc.remaining_source_amount > 0
    ),
    target_remaining_ex = round(
      case
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'UMBRELLA'
         and v_candidate_pay_method = 'PAYE'
          then public._pay_convert_umbrella_to_paye_ex(trc.remaining_source_amount, v_relevant_erni_pct)
        when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         and trc.source_pay_method = 'PAYE'
         and v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0)
        else trc.remaining_source_amount
      end,
      2
    ),
    target_remaining_vat = round(
      case
        when v_candidate_pay_method = 'UMBRELLA'
          then coalesce((public._pay_umbrella_vat_calc(
            case
              when trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
               and trc.source_pay_method = 'PAYE'
               and v_candidate_pay_method = 'UMBRELLA'
                then coalesce((public._pay_convert_paye_to_umbrella(trc.remaining_source_amount, v_relevant_erni_pct, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'ex')::numeric, 0)
              else trc.remaining_source_amount
            end,
            v_vat_rate_pct,
            v_umbrella_vat_chargeable
          )->>'vat')::numeric, 0)
        else 0
      end,
      2
    );

  update pg_temp._tmp_taxable_channel_restructure_components as trc
  set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2);

  select
    round(coalesce(sum(trc.remaining_source_amount), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.remaining_source_amount) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
    round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2)
  into
    v_source_total_ex,
    v_taxable_source_total_ex,
    v_target_total_ex,
    v_target_total_vat,
    v_target_total_inc,
    v_taxable_target_total_ex
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then
    v_manual_total_remaining_ex := round(p_manual_total_remaining, 2);
    if v_manual_total_remaining_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'MANUAL_TOTAL_REMAINING_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: manual_total_remaining must be > 0 when supplied',
        'manual_total_remaining', p_manual_total_remaining
      )::text;
    end if;

    if v_target_total_ex <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'TARGET_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: target total must be > 0 before manual allocation'
      )::text;
    end if;

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set
      target_remaining_ex = round((trc.target_remaining_ex / v_target_total_ex) * v_manual_total_remaining_ex, 2),
      target_remaining_vat = case
        when v_candidate_pay_method = 'UMBRELLA'
          then round(coalesce((public._pay_umbrella_vat_calc(round((trc.target_remaining_ex / v_target_total_ex) * v_manual_total_remaining_ex, 2), v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
        else 0
      end;

    update pg_temp._tmp_taxable_channel_restructure_components as trc
    set target_remaining_inc = round(coalesce(trc.target_remaining_ex, 0) + coalesce(trc.target_remaining_vat, 0), 2);

    select trc.finance_component_id
    into v_adjust_component_id
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    order by trc.target_remaining_ex desc, trc.finance_component_id desc
    limit 1;

    select round(v_manual_total_remaining_ex - coalesce(sum(trc.target_remaining_ex), 0), 2)
    into v_delta
    from pg_temp._tmp_taxable_channel_restructure_components as trc;

    if v_adjust_component_id is not null and v_delta <> 0 then
      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set target_remaining_ex = round(trc.target_remaining_ex + v_delta, 2)
      where trc.finance_component_id = v_adjust_component_id;

      update pg_temp._tmp_taxable_channel_restructure_components as trc
      set
        target_remaining_vat = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else 0
        end,
        target_remaining_inc = case
          when v_candidate_pay_method = 'UMBRELLA'
            then round(trc.target_remaining_ex + coalesce((public._pay_umbrella_vat_calc(trc.target_remaining_ex, v_vat_rate_pct, v_umbrella_vat_chargeable)->>'vat')::numeric, 0), 2)
          else trc.target_remaining_ex
        end
      where trc.finance_component_id = v_adjust_component_id;
    end if;

    select
      round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_vat), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_inc), 0), 2)::numeric(12,2),
      round(coalesce(sum(trc.target_remaining_ex) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum), 0), 2)::numeric(12,2)
    into
      v_target_total_ex,
      v_target_total_vat,
      v_target_total_inc,
      v_taxable_target_total_ex
    from pg_temp._tmp_taxable_channel_restructure_components as trc;
  end if;

  if v_source_total_ex <= 0 or v_target_total_ex <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
      'code', 'REMAINING_TOTAL_INVALID',
      'message', 'pay_finance_case_taxable_channel_restructure_suggestion: source and target totals must be > 0',
      'source_total_ex', v_source_total_ex,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  v_restructure_start_week_start := coalesce(v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));
  if public._pay_week_start_monday(v_restructure_start_week_start) <> v_restructure_start_week_start then
    v_restructure_start_week_start := public._pay_week_start_monday(v_restructure_start_week_start);
  end if;

  v_schedule_sign := case
    when v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then 1
    else -1
  end;

  select count(*)::integer
  into v_existing_weeks_remaining
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and abs(coalesce(
      case
        when coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
          then round((sched.schedule_row->>'amount')::numeric, 2)
        else null::numeric
      end,
      0::numeric
    )) > 0;

  if v_existing_weeks_remaining is null or v_existing_weeks_remaining < 1 then
    if round(coalesce(v_case.weekly_due, 0), 2) > 0 then
      v_existing_weeks_remaining := greatest(ceil(v_source_total_ex / round(coalesce(v_case.weekly_due, 0), 2))::integer, 1);
    elsif coalesce(v_case.weeks_total, 0) > 0 then
      v_existing_weeks_remaining := v_case.weeks_total;
    else
      v_existing_weeks_remaining := 1;
    end if;
  end if;

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_weekly_due
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date asc
  limit 1;

  v_existing_weekly_due := coalesce(nullif(round(coalesce(v_case.weekly_due, 0), 2), 0), v_existing_weekly_due, round((ceil((v_source_total_ex / greatest(v_existing_weeks_remaining, 1)) * 100) / 100), 2));

  select round(abs(coalesce((sched.schedule_row->>'amount')::numeric, 0)), 2)
  into v_existing_final_week_amount
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
    and abs((sched.schedule_row->>'amount')::numeric) > 0
  order by (sched.schedule_row->>'week_start')::date desc
  limit 1;

  if v_existing_final_week_amount is null then
    v_existing_final_week_amount := round(least(v_existing_weekly_due, greatest(v_source_total_ex - (v_existing_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);
  end if;

  v_ratio := case when v_source_total_ex > 0 then v_target_total_ex / v_source_total_ex else 1 end;
  v_suggested_weekly_due := greatest(round(v_existing_weekly_due * v_ratio, 2), 0.01);
  v_suggested_final_week_amount := round(least(v_suggested_weekly_due, greatest(v_target_total_ex - (v_suggested_weekly_due * greatest(v_existing_weeks_remaining - 1, 0)), 0)), 2);

  if v_schedule_input_mode_norm = 'BY_WEEKS' then
    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weeks_total must be >= 1',
        'weeks_total', p_weeks_total
      )::text;
    end if;

    v_selected_weeks_total := coalesce(p_weeks_total, v_existing_weeks_remaining);
    v_selected_weekly_due := case
      when p_weeks_total is null then v_suggested_weekly_due
      else round((ceil((v_target_total_ex / p_weeks_total) * 100) / 100), 2)
    end;
  else
    if p_weekly_due is null or round(p_weekly_due, 2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_TAXABLE_CHANNEL_RESTRUCTURE_SUGGESTION',
        'code', 'WEEKLY_DUE_REQUIRED',
        'message', 'pay_finance_case_taxable_channel_restructure_suggestion: weekly_due must be > 0 when schedule_input_mode is BY_WEEKLY_DUE',
        'weekly_due', p_weekly_due
      )::text;
    end if;

    v_selected_weekly_due := round(p_weekly_due, 2);
    v_selected_weeks_total := greatest(ceil(v_target_total_ex / v_selected_weekly_due)::integer, 1);
  end if;

  v_selected_final_week_amount := round(least(v_selected_weekly_due, greatest(v_target_total_ex - (v_selected_weekly_due * greatest(v_selected_weeks_total - 1, 0)), 0)), 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', trc.finance_component_id::text,
          'linked_timesheet_id', case when trc.linked_timesheet_id is null then null else trc.linked_timesheet_id::text end,
          'source_family_key', trc.source_family_key,
          'component_key_type', trc.component_key_type,
          'component_key_value', trc.component_key_value,
          'classification', trc.classification::text,
          'source_pay_method', trc.source_pay_method,
          'target_pay_method', v_candidate_pay_method,
          'source_remaining_amount_ex_vat', trc.remaining_source_amount,
          'target_remaining_amount_ex_vat', trc.target_remaining_ex,
          'target_remaining_amount_vat', trc.target_remaining_vat,
          'target_remaining_amount_inc_vat', trc.target_remaining_inc,
          'requires_component_conversion', trc.requires_component_conversion,
          'saved_target_pay_method', trc.saved_target_pay_method,
          'saved_resolution_mode', case when trc.saved_resolution_mode is null then null else trc.saved_resolution_mode::text end,
          'is_resolution_stale', trc.is_resolution_stale,
          'stale_reason', trc.stale_reason
        )
      )
      order by trc.allocation_priority_group nulls last, trc.allocation_priority_order nulls last, trc.finance_component_id
    ),
    '[]'::jsonb
  )
  into v_component_breakdown
  from (
    select
      trc.*,
      pfc.allocation_priority_group,
      pfc.allocation_priority_order
    from pg_temp._tmp_taxable_channel_restructure_components as trc
    join public.pay_finance_case_components as pfc
      on pfc.id = trc.finance_component_id
  ) as trc;

  return jsonb_build_object(
    'ok', true,
    'requires_restructure', true,
    'can_apply', (v_has_open_batch_item is distinct from true),
    'blocked_reason', v_blocked_reason,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'source_pay_methods', (
      select coalesce(jsonb_agg(distinct trc.source_pay_method), '[]'::jsonb)
      from pg_temp._tmp_taxable_channel_restructure_components as trc
      where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
    ),
    'target_pay_method', v_candidate_pay_method,
    'effective_pay_date', v_effective_pay_date::text,
    'resolution_path', v_resolution_path_norm,
    'schedule_input_mode', v_schedule_input_mode_norm,
    'existing', jsonb_build_object(
      'source_remaining_balance_ex_vat', v_source_total_ex,
      'taxable_source_remaining_balance_ex_vat', v_taxable_source_total_ex,
      'weekly_due', v_existing_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_existing_final_week_amount,
      'start_week_start', v_restructure_start_week_start::text,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb)
    ),
    'suggested', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'target_remaining_balance_vat', v_target_total_vat,
      'target_remaining_balance_inc_vat', v_target_total_inc,
      'taxable_target_remaining_balance_ex_vat', v_taxable_target_total_ex,
      'weekly_due', v_suggested_weekly_due,
      'weeks_remaining', v_existing_weeks_remaining,
      'final_week_amount', v_suggested_final_week_amount,
      'erni_rate_pct', v_relevant_erni_pct,
      'erni_component_ex_vat', round(abs(v_taxable_source_total_ex - v_taxable_target_total_ex), 2),
      'vat_rate_pct', v_vat_rate_pct,
      'vat_amount', v_target_total_vat,
      'umbrella_vat_chargeable', v_umbrella_vat_chargeable
    ),
    'selected', jsonb_build_object(
      'target_remaining_balance_ex_vat', v_target_total_ex,
      'weekly_due', v_selected_weekly_due,
      'weeks_total', v_selected_weeks_total,
      'final_week_amount', v_selected_final_week_amount,
      'schedule_sign', v_schedule_sign,
      'start_week_start', v_restructure_start_week_start::text
    ),
    'component_breakdown', v_component_breakdown,
    'generated_at_utc', v_now_utc::text,
    'note', p_note
  );
end;
$function$;


create or replace function public.pay_finance_case_apply_taxable_channel_restructure(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_resolution_path text default 'SUGGESTED'::text,
  p_schedule_input_mode text default null::text,
  p_weeks_total integer default null::integer,
  p_weekly_due numeric default null::numeric,
  p_manual_total_remaining numeric default null::numeric,
  p_effective_pay_date date default null::date,
  p_note text default null::text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_now_utc timestamptz := now();
  v_effective_pay_date date := p_effective_pay_date;

  v_case public.pay_advances%rowtype;
  v_updated_case public.pay_advances%rowtype;
  v_candidate record;

  v_suggestion jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_component_before_json jsonb := '[]'::jsonb;
  v_component_after_json jsonb := '[]'::jsonb;
  v_schedule_json jsonb := '[]'::jsonb;

  v_candidate_pay_method text := null;
  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));

  v_target_total_ex numeric(12,2) := 0;
  v_target_total_vat numeric(12,2) := 0;
  v_target_total_inc numeric(12,2) := 0;
  v_weekly_due numeric(12,2) := 0;
  v_weeks_total integer := 0;
  v_final_week_amount numeric(12,2) := 0;
  v_schedule_sign integer := -1;
  v_start_week_start date := null;
  v_next_due_week_start date := null;
  v_recovered_or_paid_so_far_ex numeric(12,2) := 0;
  v_rebased_original_amount numeric(12,2) := 0;

  v_open_component_count integer := 0;
  v_new_component_remaining_total numeric(12,2) := 0;
  v_has_open_batch_item boolean := false;
  v_resolution_mode public.pay_finance_component_resolution_mode_enum := 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum;
  v_event_note text := null;
  v_case_taxability public.pay_finance_taxability_enum := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_resolution_path_norm is null then
    v_resolution_path_norm := 'SUGGESTED';
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type not in (
    'OVERPAYMENT'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_TYPE_NOT_SUPPORTED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case type is not supported for taxable channel restructure',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_NOT_ACTIVE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case must be ACTIVE',
      'finance_case_id', p_finance_case_id::text,
      'status', v_case.status::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount, 0), 2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'NO_OUTSTANDING_BALANCE',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text,
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2)
    )::text;
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method
  into v_candidate
  from public.candidates as c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  perform 1
  from public.pay_finance_case_components as pfc_lock
  where pfc_lock.finance_case_id = p_finance_case_id
    and pfc_lock.closed_at_utc is null
  for update;

  select exists (
    select 1
    from public.pay_batch_items as pbi
    join public.pay_batch_candidates as pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches as pb
      on pb.id = pbc.pay_batch_id
    where coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
      and (
        pbi.finance_case_id = p_finance_case_id
        or exists (
          select 1
          from public.pay_finance_case_components as pfc_open_for_batch
          where pfc_open_for_batch.finance_case_id = p_finance_case_id
            and pfc_open_for_batch.closed_at_utc is null
            and pfc_open_for_batch.id = pbi.finance_component_id
        )
      )
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'CASE_ALREADY_IN_OPEN_BATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: cannot restructure while the case is already included in an open pay batch',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_suggestion := public.pay_finance_case_taxable_channel_restructure_suggestion(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_effective_pay_date => v_effective_pay_date,
    p_resolution_path => v_resolution_path_norm,
    p_schedule_input_mode => v_schedule_input_mode_norm,
    p_weeks_total => p_weeks_total,
    p_weekly_due => p_weekly_due,
    p_manual_total_remaining => p_manual_total_remaining,
    p_note => p_note
  );

  if coalesce((v_suggestion->>'requires_restructure')::boolean, false) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'RESTRUCTURE_NOT_REQUIRED',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: taxable channel restructure is not required',
      'finance_case_id', p_finance_case_id::text,
      'suggestion', v_suggestion
    )::text;
  end if;

  if coalesce((v_suggestion->>'can_apply')::boolean, true) is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', coalesce(nullif(v_suggestion->>'blocked_reason', ''), 'RESTRUCTURE_BLOCKED'),
      'message', 'pay_finance_case_apply_taxable_channel_restructure: restructure is currently blocked',
      'finance_case_id', p_finance_case_id::text,
      'blocked_reason', v_suggestion->>'blocked_reason'
    )::text;
  end if;

  if to_regclass('pg_temp._tmp_taxable_channel_restructure_components') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SUGGESTION_COMPONENT_TABLE_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: suggestion component table was not available'
    )::text;
  end if;

  select
    count(*)::integer,
    round(coalesce(sum(trc.target_remaining_ex), 0), 2)::numeric(12,2)
  into
    v_open_component_count,
    v_new_component_remaining_total
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  if v_open_component_count < 1 or v_new_component_remaining_total <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'COMPONENT_TARGET_TOTAL_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: target component total must be > 0',
      'open_component_count', v_open_component_count,
      'target_total_ex', v_new_component_remaining_total
    )::text;
  end if;

  v_target_total_ex := round(coalesce((v_suggestion->'selected'->>'target_remaining_balance_ex_vat')::numeric, v_new_component_remaining_total), 2);
  v_weekly_due := round(coalesce((v_suggestion->'selected'->>'weekly_due')::numeric, 0), 2);
  v_weeks_total := coalesce((v_suggestion->'selected'->>'weeks_total')::integer, 0);
  v_final_week_amount := round(coalesce((v_suggestion->'selected'->>'final_week_amount')::numeric, 0), 2);
  v_schedule_sign := coalesce((v_suggestion->'selected'->>'schedule_sign')::integer, case when v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then 1 else -1 end);
  v_start_week_start := coalesce((v_suggestion->'selected'->>'start_week_start')::date, v_case.next_due_week_start, v_case.start_week_start, public._pay_week_start_monday(v_effective_pay_date));

  if v_target_total_ex <= 0 or v_weekly_due <= 0 or v_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'SELECTED_SCHEDULE_INVALID',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: selected target total, weekly_due and weeks_total must be valid',
      'target_total_ex', v_target_total_ex,
      'weekly_due', v_weekly_due,
      'weeks_total', v_weeks_total
    )::text;
  end if;

  if public._pay_week_start_monday(v_start_week_start) <> v_start_week_start then
    v_start_week_start := public._pay_week_start_monday(v_start_week_start);
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_start_week_start + (gs.i * 7))::date,
        'amount', round(
          v_schedule_sign * least(
            v_weekly_due,
            greatest(v_target_total_ex - (v_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due_week_start
  from (
    select
      (v_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        v_schedule_sign * least(
          v_weekly_due,
          greatest(v_target_total_ex - (v_weekly_due * gs2.i), 0)
        ),
        2
      ) as amount
    from generate_series(0, greatest(v_weeks_total, 1) - 1) as gs2(i)
  ) as x
  where abs(coalesce(x.amount, 0)) > 0;

  v_recovered_or_paid_so_far_ex := round(greatest(coalesce(v_case.original_amount, 0) - coalesce(v_case.outstanding_amount, 0), 0), 2);
  v_rebased_original_amount := round(v_recovered_or_paid_so_far_ex + v_target_total_ex, 2);

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_before_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_before_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
      'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
      'original_amount', round(coalesce(v_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_case.weekly_due, 0), 2),
      'weeks_total', v_case.weeks_total,
      'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_case.schedule_json, '[]'::jsonb),
      'components', v_component_before_json
    )
  );

  v_resolution_mode := case
    when v_resolution_path_norm = 'MANUAL' and p_manual_total_remaining is not null then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
    else 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum
  end;

  update public.pay_finance_case_components as pfc
  set
    source_amount = round(greatest(coalesce(pfc.source_amount, 0) - coalesce(trc.remaining_source_amount, 0), 0) + coalesce(trc.target_remaining_ex, 0), 2),
    remaining_source_amount = round(coalesce(trc.target_remaining_ex, 0), 2),
    source_pay_method = v_candidate_pay_method,
    source_basis_json = coalesce(pfc.source_basis_json, '{}'::jsonb) || jsonb_build_object(
      'taxable_channel_restructure_applied_at_utc', v_now_utc::text,
      'taxable_channel_restructure_effective_pay_date', v_effective_pay_date::text,
      'previous_source_pay_method', trc.source_pay_method,
      'target_pay_method', v_candidate_pay_method,
      'source_remaining_amount_before', trc.remaining_source_amount,
      'target_remaining_amount_ex_vat', trc.target_remaining_ex,
      'target_remaining_amount_vat', trc.target_remaining_vat,
      'target_remaining_amount_inc_vat', trc.target_remaining_inc
    ),
    saved_target_pay_method = v_candidate_pay_method,
    saved_resolution_mode = v_resolution_mode,
    saved_resolution_payload_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_path', v_resolution_path_norm,
        'schedule_input_mode', coalesce(v_schedule_input_mode_norm, 'BY_WEEKS'),
        'effective_pay_date', v_effective_pay_date::text,
        'source_pay_method', trc.source_pay_method,
        'target_pay_method', v_candidate_pay_method,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'relevant_erni_pct', v_suggestion->'suggested'->'erni_rate_pct',
        'vat_rate_pct', v_suggestion->'suggested'->'vat_rate_pct',
        'umbrella_vat_chargeable', v_suggestion->'suggested'->'umbrella_vat_chargeable',
        'weekly_due', v_weekly_due,
        'weeks_total', v_weeks_total,
        'final_week_amount', v_final_week_amount,
        'note', nullif(btrim(coalesce(p_note, '')), '')
      )
    ),
    saved_resolution_result_json = jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
        'resolution_mode', v_resolution_mode::text,
        'applied_at_utc', v_now_utc::text,
        'actor_user_id', p_actor_user_id::text,
        'source_remaining_amount_ex_vat', trc.remaining_source_amount,
        'target_remaining_amount_ex_vat', trc.target_remaining_ex,
        'target_remaining_amount_vat', trc.target_remaining_vat,
        'target_remaining_amount_inc_vat', trc.target_remaining_inc,
        'source_pay_method_before', trc.source_pay_method,
        'source_pay_method_after', v_candidate_pay_method,
        'case_target_remaining_amount_ex_vat', v_target_total_ex,
        'case_weekly_due', v_weekly_due,
        'case_weeks_total', v_weeks_total
      )
    ),
    resolution_fingerprint = md5(jsonb_build_object(
      'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
      'finance_component_id', pfc.id::text,
      'target_pay_method', v_candidate_pay_method,
      'target_remaining_amount_ex_vat', round(coalesce(trc.target_remaining_ex, 0), 2),
      'classification', pfc.classification::text,
      'component_key_type', pfc.component_key_type,
      'component_key_value', pfc.component_key_value,
      'effective_pay_date', v_effective_pay_date::text,
      'resolution_mode', v_resolution_mode::text
    )::text),
    is_resolution_stale = false,
    stale_reason = null,
    resolved_at_utc = v_now_utc,
    updated_at_utc = v_now_utc
  from pg_temp._tmp_taxable_channel_restructure_components as trc
  where pfc.id = trc.finance_component_id
    and pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  select
    case
      when count(*) filter (where trc.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum) = count(*)
        then 'TAXABLE'::public.pay_finance_taxability_enum
      when count(*) filter (where trc.classification in (
        'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
        'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
      )) = count(*)
        then 'NON_TAXABLE'::public.pay_finance_taxability_enum
      else null::public.pay_finance_taxability_enum
    end
  into v_case_taxability
  from pg_temp._tmp_taxable_channel_restructure_components as trc;

  update public.pay_advances as pa
  set
    original_amount = v_rebased_original_amount,
    outstanding_amount = v_target_total_ex,
    schedule_json = coalesce(v_schedule_json, '[]'::jsonb),
    weekly_due = v_weekly_due,
    weeks_total = v_weeks_total,
    start_week_start = v_start_week_start,
    next_due_week_start = v_next_due_week_start,
    taxability = v_case_taxability,
    routing_kind = case
      when v_candidate_pay_method = 'PAYE' then 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
      else 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
    end,
    notes = coalesce(nullif(btrim(coalesce(p_note, '')), ''), pa.notes),
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select
    round(coalesce(sum(pfc.remaining_source_amount), 0), 2)::numeric(12,2),
    count(*)::integer
  into
    v_new_component_remaining_total,
    v_open_component_count
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  if v_open_component_count < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENTS_MISSING',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: no open components remained after update',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_new_component_remaining_total <> v_target_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_COMPONENT_TOTAL_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated component remaining total must match selected target total',
      'finance_case_id', p_finance_case_id::text,
      'component_remaining_total', v_new_component_remaining_total,
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select pa.*
  into v_updated_case
  from public.pay_advances as pa
  where pa.id = p_finance_case_id;

  if v_updated_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_NOT_FOUND',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case could not be reloaded',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if round(coalesce(v_updated_case.outstanding_amount, 0), 2) <> v_target_total_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_APPLY_TAXABLE_CHANNEL_RESTRUCTURE',
      'code', 'UPDATED_CASE_OUTSTANDING_MISMATCH',
      'message', 'pay_finance_case_apply_taxable_channel_restructure: updated finance case outstanding_amount must match selected target total',
      'finance_case_id', p_finance_case_id::text,
      'updated_outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'target_total_ex', v_target_total_ex
    )::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
          'saved_resolution_result_json', pfc.saved_resolution_result_json,
          'resolution_fingerprint', pfc.resolution_fingerprint,
          'is_resolution_stale', coalesce(pfc.is_resolution_stale, false),
          'stale_reason', pfc.stale_reason
        )
      )
      order by pfc.allocation_priority_group nulls last, pfc.allocation_priority_order nulls last, pfc.id
    ),
    '[]'::jsonb
  )
  into v_component_after_json
  from public.pay_finance_case_components as pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_after_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_updated_case.candidate_id::text,
      'client_id', case when v_updated_case.client_id is null then null else v_updated_case.client_id::text end,
      'case_type', v_updated_case.case_type::text,
      'status', v_updated_case.status::text,
      'taxability', case when v_updated_case.taxability is null then null else v_updated_case.taxability::text end,
      'routing_kind', case when v_updated_case.routing_kind is null then null else v_updated_case.routing_kind::text end,
      'original_amount', round(coalesce(v_updated_case.original_amount, 0), 2),
      'outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'weekly_due', round(coalesce(v_updated_case.weekly_due, 0), 2),
      'weeks_total', v_updated_case.weeks_total,
      'start_week_start', case when v_updated_case.start_week_start is null then null else v_updated_case.start_week_start::text end,
      'next_due_week_start', case when v_updated_case.next_due_week_start is null then null else v_updated_case.next_due_week_start::text end,
      'schedule_json', coalesce(v_updated_case.schedule_json, '[]'::jsonb),
      'components', v_component_after_json
    )
  );

  v_event_note := coalesce(
    nullif(btrim(coalesce(p_note, '')), ''),
    'Taxable finance channel restructure applied'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::uuid,
    v_before_json,
    v_after_json,
    'TAXABLE_CHANNEL_RESTRUCTURE',
    v_event_note
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_updated_case.candidate_id::text,
    'case_type', v_updated_case.case_type::text,
    'resolution_family', 'TAXABLE_CHANNEL_RESTRUCTURE',
    'resolution_path', v_resolution_path_norm,
    'resolution_mode', v_resolution_mode::text,
    'effective_pay_date', v_effective_pay_date::text,
    'target_pay_method', v_candidate_pay_method,
    'before', v_before_json,
    'after', v_after_json,
    'suggestion', v_suggestion
  );
end;
$function$;

drop function if exists public.pay_manual_debt_adjustment_resolve_taxable_channel_change(uuid, uuid, text, text, integer, numeric, numeric, text);

create or replace function public.pay_manual_debt_adjustment_resolve_taxable_channel_change(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_resolution_path text,
  p_schedule_input_mode text default null::text,
  p_weeks_total integer default null::integer,
  p_weekly_due numeric default null::numeric,
  p_manual_total_remaining numeric default null::numeric,
  p_effective_pay_date date default null::date,
  p_note text default null::text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: actor_user_id is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if p_effective_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'EFFECTIVE_PAY_DATE_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: effective_pay_date is required and must be supplied by the caller',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  return public.pay_finance_case_apply_taxable_channel_restructure(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_resolution_path => p_resolution_path,
    p_schedule_input_mode => p_schedule_input_mode,
    p_weeks_total => p_weeks_total,
    p_weekly_due => p_weekly_due,
    p_manual_total_remaining => p_manual_total_remaining,
    p_effective_pay_date => p_effective_pay_date,
    p_note => p_note
  );
end;
$function$;



CREATE OR REPLACE FUNCTION public._pay_batch_status_is_active_reservation(p_status text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT upper(btrim(coalesce(p_status, ''))) IN (
    'DRAFT',
    'DRAFT_CREATED',
    'READY',
    'WAITING_BANK_CONFIRM',
    'PARTIAL',
    'BLOCKED_FUNDS',
    'SCHEDULED',
    'EXECUTING',
    'AWAITING_AUTHORISATION',
    'AUTHORISED_FOR_PAYMENT'
  );
$function$;


CREATE OR REPLACE FUNCTION public._pay_current_timesheet_entitlement_components(p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with
inp as (
  select coalesce(
    (
      select array_agg(distinct t_input.x)
      from unnest(coalesce(p_timesheet_ids, array[]::uuid[])) as t_input(x)
      where t_input.x is not null
    ),
    array[]::uuid[]
  ) as ts_ids
),
tf as (
  select
    tfin.timesheet_id,
    tfin.total_pay_ex_vat,
    tfin.invoice_breakdown_json,
    tfin.additional_units_json,
    tfin.expenses_pay_ex_vat,
    tfin.travel_pay_ex_vat,
    tfin.accommodation_pay_ex_vat,
    tfin.other_pay_ex_vat,
    tfin.mileage_pay_ex_vat,
    ts.booking_id,
    upper(coalesce(ts.sheet_scope::text,'')) as sheet_scope,
    ts.reference_number,
    ts.worked_start_iso as ts_worked_start_iso,
    ts.worked_end_iso as ts_worked_end_iso,
    ts.break_start_iso as ts_break_start_iso,
    ts.break_end_iso as ts_break_end_iso,
    ts.break_minutes as ts_break_minutes,
    ts.actual_schedule_json as ts_actual_schedule_json,
    tfin.worked_start_iso as tf_worked_start_iso,
    tfin.worked_end_iso as tf_worked_end_iso,
    tfin.break_start_iso as tf_break_start_iso,
    tfin.break_end_iso as tf_break_end_iso,
    tfin.break_minutes as tf_break_minutes,
    tfin.actual_schedule_json as tf_actual_schedule_json
  from inp i
  left join public.timesheets_financials tfin
    on tfin.is_current = true
   and tfin.timesheet_id = any(i.ts_ids)
  left join public.timesheets ts
    on ts.timesheet_id = tfin.timesheet_id
   and ts.is_current = true
),
truth_enriched as (
  select
    tf0.timesheet_id,
    tf0.total_pay_ex_vat,
    tf0.invoice_breakdown_json,
    tf0.additional_units_json,
    tf0.expenses_pay_ex_vat,
    tf0.travel_pay_ex_vat,
    tf0.accommodation_pay_ex_vat,
    tf0.other_pay_ex_vat,
    tf0.mileage_pay_ex_vat,
    tf0.booking_id,
    tf0.sheet_scope,
    tf0.reference_number,
    coalesce(tf0.tf_worked_start_iso, tf0.ts_worked_start_iso) as effective_worked_start_iso,
    coalesce(tf0.tf_worked_end_iso, tf0.ts_worked_end_iso) as effective_worked_end_iso,
    coalesce(tf0.tf_break_start_iso, tf0.ts_break_start_iso) as effective_break_start_iso,
    coalesce(tf0.tf_break_end_iso, tf0.ts_break_end_iso) as effective_break_end_iso,
    coalesce(tf0.tf_break_minutes, tf0.ts_break_minutes) as effective_break_minutes,
    case
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'object' then tf0.tf_actual_schedule_json
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'array' then (
        select tf_sched_item.value
        from jsonb_array_elements(tf0.tf_actual_schedule_json) as tf_sched_item(value)
        where tf_sched_item.value is not null
          and jsonb_typeof(tf_sched_item.value) = 'object'
        limit 1
      )
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'object' then tf0.ts_actual_schedule_json
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'array' then (
        select ts_sched_item.value
        from jsonb_array_elements(tf0.ts_actual_schedule_json) as ts_sched_item(value)
        where ts_sched_item.value is not null
          and jsonb_typeof(ts_sched_item.value) = 'object'
        limit 1
      )
      else null::jsonb
    end as effective_daily_schedule_json
  from tf tf0
),
truth_segments as (
  select
    te.timesheet_id,
    case
      when te.invoice_breakdown_json is not null
       and jsonb_typeof(te.invoice_breakdown_json) = 'object'
       and upper(coalesce(te.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
       and jsonb_typeof(te.invoice_breakdown_json->'segments') = 'array'
      then (
        select coalesce(
          jsonb_agg(seg.value),
          '[]'::jsonb
        )
        from jsonb_array_elements(te.invoice_breakdown_json->'segments') as seg(value)
        where seg.value is not null
          and jsonb_typeof(seg.value) = 'object'
      )
      when te.sheet_scope = 'DAILY'
      then jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false,
          'date', case
            when te.effective_worked_start_iso is not null then ((te.effective_worked_start_iso at time zone 'Europe/London')::date)::text
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'work_date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'ymd','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date_ymd','')), '')
            )
          end,
          'segment_key', ('ts:' || te.timesheet_id::text),
          'segment_stable_key', ('timesheet:' || coalesce(te.booking_id, te.timesheet_id::text)),
          'ref_num', nullif(btrim(coalesce(te.reference_number,'')), ''),
          'start_utc', case
            when te.effective_worked_start_iso is not null then te.effective_worked_start_iso::text
            else null
          end,
          'end_utc', case
            when te.effective_worked_end_iso is not null then te.effective_worked_end_iso::text
            else null
          end,
          'start', case
            when te.effective_worked_start_iso is not null then to_char((te.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'start','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_start','')), '')
            )
          end,
          'end', case
            when te.effective_worked_end_iso is not null then to_char((te.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'end','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_end','')), '')
            )
          end,
          'break_start', case
            when te.effective_break_start_iso is not null then to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '')
          end,
          'break_end', case
            when te.effective_break_end_iso is not null then to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '')
          end,
          'break_mins', coalesce(
            te.effective_break_minutes::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
            case
              when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                then greatest(
                  0::numeric,
                  round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                )
              else null::numeric
            end
          ),
          'breaks', case
            when jsonb_typeof(te.effective_daily_schedule_json->'breaks') = 'array' then te.effective_daily_schedule_json->'breaks'
            when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'end', to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    case
                      when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  )
                )
              )
            when nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '') is not null
             and nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '') is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), ''),
                  'end', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), ''),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                  )
                )
              )
            else '[]'::jsonb
          end
        )
      )
      else jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false
        )
      )
    end as segments_json
  from truth_enriched te
),
truth_snapshot_like as (
  select
    ts.timesheet_id,
    jsonb_build_object(
      'segments', ts.segments_json,
      'additional_units_json', coalesce(tf1.additional_units_json,'{}'::jsonb),
      'additional_pay_ex_vat', 0,
      'expenses', jsonb_build_object(
        'expenses_pay_ex_vat', round(coalesce(tf1.expenses_pay_ex_vat,0),2),
        'travel_pay_ex_vat', round(coalesce(tf1.travel_pay_ex_vat,0),2),
        'accommodation_pay_ex_vat', round(coalesce(tf1.accommodation_pay_ex_vat,0),2),
        'other_pay_ex_vat', round(coalesce(tf1.other_pay_ex_vat,0),2),
        'mileage_pay_ex_vat', round(coalesce(tf1.mileage_pay_ex_vat,0),2)
      ),
      'adjustments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', a.id::text,
            'delta_pay_ex_vat', round(coalesce(a.delta_pay_ex_vat,0),2)
          )
          order by a.created_at nulls last, a.id
        )
        from public.ts_pay_adjustments a
        where a.as_advance = false
          and a.timesheet_id = ts.timesheet_id
      ), '[]'::jsonb)
    ) as snap_json
  from truth_segments ts
  join tf tf1
    on tf1.timesheet_id = ts.timesheet_id
),
truth_components as (
  select
    tsl.timesheet_id,
    tc.key_type,
    tc.key_value,
    tc.amount_ex_vat,
    tc.amount_inc_vat
  from truth_snapshot_like tsl
  join lateral public._pay_timesheet_components(tsl.snap_json) as tc
    on true
),
active_settled_components as (
  select
    active_rows.timesheet_id,
    active_rows.key_type,
    active_rows.key_value,
    active_rows.amount_ex_vat,
    active_rows.amount_inc_vat
  from public._pay_active_settled_components((select inp.ts_ids from inp)) as active_rows
),
legacy_baseline_timesheets as (
  select distinct
    tps.timesheet_id
  from inp i
  join public.timesheet_pay_state tps
    on tps.timesheet_id = any(i.ts_ids)
  where not exists (
    select 1
    from active_settled_components active_check
    where active_check.timesheet_id = tps.timesheet_id
  )
),
legacy_baseline_components as (
  select
    tps.timesheet_id,
    bc.key_type,
    bc.key_value,
    bc.amount_ex_vat,
    bc.amount_inc_vat
  from legacy_baseline_timesheets lbt
  join public.timesheet_pay_state tps
    on tps.timesheet_id = lbt.timesheet_id
  join lateral public._pay_timesheet_components(coalesce(tps.last_settled_snapshot_json,'{}'::jsonb)) as bc
    on true
),
baseline_components as (
  select
    active_settled_components.timesheet_id,
    active_settled_components.key_type,
    active_settled_components.key_value,
    active_settled_components.amount_ex_vat,
    active_settled_components.amount_inc_vat
  from active_settled_components
  union all
  select
    legacy_baseline_components.timesheet_id,
    legacy_baseline_components.key_type,
    legacy_baseline_components.key_value,
    legacy_baseline_components.amount_ex_vat,
    legacy_baseline_components.amount_inc_vat
  from legacy_baseline_components
),

truth_grouped as (
  select
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(truth_components.key_value, '')), '') as key_value,
    round(sum(coalesce(truth_components.amount_ex_vat, 0)), 2) as truth_ex_vat,
    round(sum(coalesce(truth_components.amount_inc_vat, 0)), 2) as truth_inc_vat
  from truth_components
  where truth_components.timesheet_id is not null
    and truth_components.key_type is not null
    and btrim(truth_components.key_type) <> ''
    and truth_components.key_value is not null
    and btrim(truth_components.key_value) <> ''
    and truth_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (truth_components.key_type = 'TS_DAY' and truth_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    truth_components.timesheet_id,
    upper(nullif(btrim(coalesce(truth_components.key_type, '')), '')),
    nullif(btrim(coalesce(truth_components.key_value, '')), '')
),
baseline_grouped as (
  select
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')) as key_type,
    nullif(btrim(coalesce(baseline_components.key_value, '')), '') as key_value,
    round(sum(coalesce(baseline_components.amount_ex_vat, 0)), 2) as baseline_ex_vat,
    round(sum(coalesce(baseline_components.amount_inc_vat, 0)), 2) as baseline_inc_vat
  from baseline_components
  where baseline_components.timesheet_id is not null
    and baseline_components.key_type is not null
    and btrim(baseline_components.key_type) <> ''
    and baseline_components.key_value is not null
    and btrim(baseline_components.key_value) <> ''
    and baseline_components.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
    and not (baseline_components.key_type = 'TS_DAY' and baseline_components.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  group by
    baseline_components.timesheet_id,
    upper(nullif(btrim(coalesce(baseline_components.key_type, '')), '')),
    nullif(btrim(coalesce(baseline_components.key_value, '')), '')
),
all_keys as (
  select
    truth_grouped.timesheet_id,
    truth_grouped.key_type,
    truth_grouped.key_value
  from truth_grouped

  union

  select
    baseline_grouped.timesheet_id,
    baseline_grouped.key_type,
    baseline_grouped.key_value
  from baseline_grouped
)
select
  all_keys.timesheet_id,
  all_keys.key_type,
  all_keys.key_value,
  round(coalesce(truth_grouped.truth_ex_vat, 0), 2) as truth_ex_vat,
  round(coalesce(baseline_grouped.baseline_ex_vat, 0), 2) as baseline_ex_vat,
  round(coalesce(truth_grouped.truth_inc_vat, 0), 2) as truth_inc_vat,
  round(coalesce(baseline_grouped.baseline_inc_vat, 0), 2) as baseline_inc_vat
from all_keys
left join truth_grouped
  on truth_grouped.timesheet_id = all_keys.timesheet_id
 and truth_grouped.key_type = all_keys.key_type
 and truth_grouped.key_value = all_keys.key_value
left join baseline_grouped
  on baseline_grouped.timesheet_id = all_keys.timesheet_id
 and baseline_grouped.key_type = all_keys.key_type
 and baseline_grouped.key_value = all_keys.key_value
where all_keys.timesheet_id is not null
  and all_keys.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
  and all_keys.key_value is not null
  and btrim(all_keys.key_value) <> ''
  and not (all_keys.key_type = 'TS_DAY' and all_keys.key_value !~ '^\d{4}-\d{2}-\d{2}$')
order by
  all_keys.timesheet_id,
  all_keys.key_type,
  all_keys.key_value;
$function$;




create or replace function public.pay_manual_credit_adjustment_create(
  p_candidate_id uuid,
  p_amount numeric,
  p_actor_user_id uuid,
  p_adjustment_comment text,
  p_note text default null,
  p_taxability text default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_pay_date date := (now() at time zone 'Europe/London')::date;

  v_settings record;
  v_candidate record;

  v_finance_case_id uuid := null;
  v_finance_component_id uuid := null;

  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_resolution_fingerprint text := null;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;

  v_warnings jsonb := '[]'::jsonb;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;

  v_pay_channel text := null;
  v_paye_treatment text := 'NONE';
  v_paye_net_effect text := null;

  v_taxability public.pay_finance_taxability_enum := null;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;
  v_component_classification public.pay_finance_component_classification_enum := null;

  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;

  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: actor_user_id is required'
    )::text;
  end if;

  if p_amount is null or round(p_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_credit_adjustment_create: amount must be > 0'
    )::text;
  end if;

  if nullif(btrim(coalesce(p_adjustment_comment,'')), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: adjustment_comment is required'
    )::text;
  end if;

  if nullif(upper(btrim(coalesce(p_taxability,''))), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_REQUIRED',
      'message', 'pay_manual_credit_adjustment_create: taxability is required and must be TAXABLE or NON_TAXABLE'
    )::text;
  end if;

  if upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_credit_adjustment_create: taxability must be TAXABLE or NON_TAXABLE',
      'taxability', p_taxability
    )::text;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_manual_credit_adjustment_create: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    upper(coalesce(c.pay_method,'')) as pay_method,
    c.umbrella_id
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_manual_credit_adjustment_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_credit_adjustment_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  v_pay_channel := v_candidate.pay_method;

  if v_pay_channel = 'PAYE' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_ADD';
    v_paye_net_effect := null;
  elsif v_pay_channel = 'PAYE' and v_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := 'NET_ADD';
  elsif v_pay_channel = 'UMBRELLA' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  end if;

  if v_oneoff_required = false then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED',
        'message', 'pay_manual_credit_adjustment_create: one-off bank fields are only allowed for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text,
        'pay_method', v_pay_channel,
        'taxability', v_taxability::text
      )::text;
    end if;
  else
    v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
    v_sort_code_norm := case
      when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
      else null
    end;
    v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');

    if v_beneficiary_name_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'BENEFICIARY_NAME_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: beneficiary_name is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_sort_code_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'SORT_CODE_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: valid sort_code is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_account_number_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'ACCOUNT_NUMBER_REQUIRED',
        'message', 'pay_manual_credit_adjustment_create: valid account_number is required for umbrella non-taxable manual credits',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
    if v_oneoff_bank_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_CREATE',
        'code', 'BANK_DETAILS_HASH_FAILED',
        'message', 'pay_manual_credit_adjustment_create: unable to derive bank_details_hash for umbrella non-taxable manual credit bank details',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id,
    taxability,
    routing_kind,
    oneoff_bank_details_required
  )
  values (
    p_candidate_id,
    null::uuid,
    'MANUAL_ADVANCE'::public.pay_advance_reason_enum,
    round(p_amount,2),
    round(p_amount,2),
    null::date,
    '[]'::jsonb,
    null::date,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LEGACY_ADVANCE'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    'PENDING'::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    null::numeric,
    null::int,
    null::date,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
    null::numeric,
    null::numeric,
    null::numeric,
    null::numeric,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid,
    v_taxability,
    v_routing_kind,
    v_oneoff_required
  )
  returning id into v_finance_case_id;

  if v_oneoff_required then
    insert into public.pay_finance_case_oneoff_payout_bank_details(
      finance_case_id,
      candidate_id,
      beneficiary_name,
      sort_code,
      account_number,
      bank_details_hash,
      note,
      created_at_utc,
      created_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    values (
      v_finance_case_id,
      p_candidate_id,
      v_beneficiary_name_norm,
      v_sort_code_norm,
      v_account_number_norm,
      v_oneoff_bank_hash,
      nullif(btrim(coalesce(p_bank_details_note,'')), ''),
      v_now_utc,
      p_actor_user_id,
      v_now_utc,
      p_actor_user_id
    );

    v_oneoff_after := jsonb_build_object(
      'finance_case_id', v_finance_case_id::text,
      'candidate_id', p_candidate_id::text,
      'beneficiary_name', v_beneficiary_name_norm,
      'sort_code_masked', case when v_sort_code_norm is null then null else 'XX-XX-' || right(v_sort_code_norm, 2) end,
      'account_number_masked', case when v_account_number_norm is null then null else lpad(right(v_account_number_norm, 4), length(v_account_number_norm), '*') end,
      'bank_details_hash', v_oneoff_bank_hash,
      'note', nullif(btrim(coalesce(p_bank_details_note,'')), '')
    );

    perform public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'ONEOFF_BANK_DETAILS_CREATED',
      v_oneoff_before,
      v_oneoff_after,
      'ONE_OFF_PAYOUT_BANK_DETAILS',
      p_actor_user_id
    );
  end if;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'amount', round(p_amount,2),
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'paye_treatment', v_paye_treatment,
      'paye_net_effect', v_paye_net_effect,
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
    v_component_resolution_payload_json := jsonb_build_object(
      'same_channel', true,
      'target_amount', round(p_amount,2),
      'target_pay_method', v_pay_channel
    );

    v_component_resolution_result_json := jsonb_build_object(
      'target_amount', round(p_amount,2),
      'target_amount_ex_vat', round(p_amount,2),
      'target_amount_vat', 0,
      'target_amount_inc_vat', round(p_amount,2),
      'target_pay_method', v_pay_channel
    );

    v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => 'case:' || v_finance_case_id::text,
      p_component_key_type        => 'CASE_TOTAL',
      p_component_key_value       => 'TOTAL',
      p_classification            => v_component_classification,
      p_source_pay_method         => v_pay_channel,
      p_current_target_pay_method => v_pay_channel,
      p_source_basis_json         => v_component_source_basis_json,
      p_source_amount             => round(p_amount,2),
      p_relevant_erni_pct         => null::numeric,
      p_target_basis_json         => jsonb_build_object('same_channel', true)
    );
  end if;

  insert into public.pay_finance_case_components(
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    'case:' || v_finance_case_id::text,
    'CASE_TOTAL',
    'TOTAL',
    v_component_classification,
    v_pay_channel,
    v_component_source_basis_json,
    round(p_amount,2),
    round(p_amount,2),
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_pay_channel else null end,
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum else null end,
    v_component_resolution_payload_json,
    v_component_resolution_result_json,
    v_component_resolution_fingerprint,
    false,
    null::text,
    0,
    0,
    v_now_utc,
    v_now_utc,
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_now_utc else null end,
    null::timestamptz
  )
  returning id into v_finance_component_id;

  v_component_snapshot_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', 'case:' || v_finance_case_id::text,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', v_component_classification::text,
    'source_pay_method', v_pay_channel,
    'source_basis_json', v_component_source_basis_json,
    'source_amount', round(p_amount,2),
    'remaining_source_amount', round(p_amount,2),
    'saved_target_pay_method', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_pay_channel else null end,
    'saved_resolution_mode', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT' else null end,
    'saved_resolution_payload_json', v_component_resolution_payload_json,
    'saved_resolution_result_json', v_component_resolution_result_json,
    'resolution_fingerprint', v_component_resolution_fingerprint,
    'is_resolution_stale', false
  );

  v_component_summary_json := v_component_snapshot_json;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null::uuid,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'amount', round(p_amount,2),
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'payout_pay_batch_id', null,
      'payout_status', 'PENDING',
      'paye_treatment', v_paye_treatment,
      'paye_net_effect', v_paye_net_effect,
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'oneoff_bank_details_required', v_oneoff_required,
      'component_summary', v_component_summary_json
    ),
    null::text,
    'Manual credit adjustment created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    v_component_summary_json,
    'MANUAL_CREDIT_ADJUSTMENT_CREATE',
    case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
         then 'Created taxable total component for manual credit adjustment'
         else 'Created non-taxable fixed component for manual credit adjustment'
    end
  );

  if v_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := v_oneoff_bank_hash;
    v_readiness_payee_name := v_beneficiary_name_norm;
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  if v_routing_kind in ('NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum, 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum) then
    if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'BLOCKED_BANK_DETAILS',
          'message', case when v_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
                          then 'Bank details are missing; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.'
                          else 'One-off payout bank details are missing or incomplete; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.' end,
          'candidate_id', p_candidate_id::text
        )
      );
    else
      if v_need_name_check = true then
        select
          coalesce(bnc.status, 'UNVERIFIED') as status,
          (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
        into
          v_bnc_status,
          v_bnc_has_override
        from public.bank_name_checks bnc
        where bnc.rail_provider = v_settings.rail_provider_default
          and bnc.rail_env = v_settings.rail_env_default
          and bnc.entity_kind = v_readiness_entity_kind
          and bnc.entity_id = p_candidate_id
          and bnc.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NAME_CHECK',
              'message', 'Name check has not passed (or override missing) for the payout destination; the manual credit adjustment will appear as Blocked for Pay until resolved.',
              'candidate_id', p_candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;

      if v_requires_payee_map = true then
        select (bpm.payee_id is not null) as present
        into v_bpm_present
        from public.bank_payee_map bpm
        where bpm.rail_provider = v_settings.rail_provider_default
          and bpm.rail_env = v_settings.rail_env_default
          and bpm.entity_kind = v_readiness_entity_kind
          and bpm.entity_id = p_candidate_id
          and bpm.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bpm_present,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NO_PAYEE_MAP',
              'message', 'Payee map is missing for the payout destination on this rail; the manual credit adjustment will appear as Blocked for Pay until payee mapping exists.',
              'candidate_id', p_candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'finance_component_id', v_finance_component_id::text,
    'pay_batch_id', null,
    'pay_date', v_pay_date::text,
    'batch_kind_fixed', null,
    'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
    'worker_label', 'Manual credit adjustment',
    'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'oneoff_bank_details_required', v_oneoff_required,
    'oneoff_bank_details_present', v_oneoff_required,
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_oneoff_required then v_beneficiary_name_norm else null end,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;


create or replace function public.pay_manual_credit_adjustment_update(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_amount numeric default null,
  p_adjustment_comment text default null,
  p_note text default null,
  p_taxability text default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null,
  p_remove_oneoff_bank_details boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_batch public.pay_batches%rowtype;
  v_has_batch boolean := false;
  v_is_committed boolean := false;
  v_has_newflow_draft_item boolean := false;
  v_can_edit_pre_draft boolean := false;

  v_new_amount numeric(12,2);
  v_new_comment text;
  v_new_notes text;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_batch_item_id uuid := null;
  v_pay_batch_candidate_id uuid := null;

  v_component public.pay_finance_case_components%rowtype;
  v_component_before_json jsonb := null;
  v_component_after_json jsonb := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_resolution_fingerprint text := null;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
  v_component_changed boolean := false;
  v_component_classification public.pay_finance_component_classification_enum := null;

  v_candidate record;
  v_candidate_pay_method text := null;
  v_current_taxability public.pay_finance_taxability_enum := null;
  v_requested_taxability public.pay_finance_taxability_enum := null;
  v_current_routing_kind public.pay_finance_routing_kind_enum := null;
  v_requested_routing_kind public.pay_finance_routing_kind_enum := null;
  v_current_oneoff_required boolean := false;
  v_requested_oneoff_required boolean := false;

  v_paye_treatment text := 'NONE';
  v_paye_net_effect text := null;
  v_oneoff_change_requested boolean := false;
  v_existing_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;
  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;

  v_settings record;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;
  v_warnings jsonb := '[]'::jsonb;
  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;

  v_taxability_changed boolean := false;
  v_routing_changed boolean := false;
  v_amount_changed boolean := false;
  v_comment_changed boolean := false;
  v_effective_taxability_text text := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: Manual credit adjustment not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    upper(coalesce(c.pay_method,'')) as pay_method,
    c.umbrella_id
  into v_candidate
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := v_candidate.pay_method;
  if v_candidate_pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_credit_adjustment_update: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_case.payout_pay_batch_id is not null then
    select pb.*
    into v_batch
    from public.pay_batches pb
    where pb.id = v_case.payout_pay_batch_id
    limit 1;
    v_has_batch := v_batch.id is not null;
  end if;

  if v_has_batch then
    v_is_committed := (
      coalesce(v_batch.authoritative_payment_date is not null, false)
      or upper(coalesce(v_batch.status,'')) in ('SCHEDULED','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT','EXECUTING','SETTLED','COMPLETED','PARTIAL')
    );
  else
    v_is_committed := false;
  end if;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'MANUAL_CREDIT_PAYOUT'
      and pbi.is_voided = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status,'')) <> 'CANCELLED'
  ) into v_has_newflow_draft_item;

  if v_has_batch then
    v_can_edit_pre_draft := false;
  else
    v_can_edit_pre_draft := (v_has_newflow_draft_item = false);
  end if;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
    and pfc.closed_at_utc is null
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  if v_component.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_COMPONENT_NOT_FOUND',
      'message', 'pay_manual_credit_adjustment_update: linked total finance component not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select *
  into v_existing_oneoff
  from public.pay_finance_case_oneoff_payout_bank_details d
  where d.finance_case_id = p_finance_case_id
  for update;

  v_current_taxability := coalesce(
    v_case.taxability,
    case when v_component.classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum
         then 'NON_TAXABLE'::public.pay_finance_taxability_enum
         else 'TAXABLE'::public.pay_finance_taxability_enum
    end
  );

  if p_taxability is null then
    v_requested_taxability := v_current_taxability;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_requested_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_requested_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_credit_adjustment_update: taxability must be TAXABLE or NON_TAXABLE when provided',
      'taxability', p_taxability
    )::text;
  end if;

  if v_case.routing_kind is not null then
    v_current_routing_kind := v_case.routing_kind;
  elsif v_candidate_pay_method = 'UMBRELLA' and v_current_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_current_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
  elsif v_candidate_pay_method = 'UMBRELLA' and v_current_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_current_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
  else
    v_current_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
  end if;

  if v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_ADD';
    v_paye_net_effect := null;
  elsif v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := 'NET_ADD';
  elsif v_candidate_pay_method = 'UMBRELLA' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := false;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  else
    v_requested_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_requested_oneoff_required := true;
    v_component_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
    v_paye_net_effect := null;
  end if;

  v_new_amount := coalesce(round(p_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_comment := case when p_adjustment_comment is null then v_case.adjustment_comment else nullif(btrim(p_adjustment_comment), '') end;
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;

  if p_amount is not null and v_new_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_credit_adjustment_update: amount must be > 0'
    )::text;
  end if;

  if p_adjustment_comment is not null and v_new_comment is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_credit_adjustment_update: adjustment_comment is required'
    )::text;
  end if;

  v_amount_changed := round(coalesce(v_case.original_amount,0),2) is distinct from v_new_amount;
  v_comment_changed := coalesce(v_case.adjustment_comment,'') is distinct from coalesce(v_new_comment,'');
  v_taxability_changed := v_current_taxability is distinct from v_requested_taxability;
  v_routing_changed := v_current_routing_kind is distinct from v_requested_routing_kind;
  v_oneoff_change_requested := (
    nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
    or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
    or nullif(btrim(coalesce(p_account_number,'')), '') is not null
    or p_bank_details_note is not null
    or coalesce(p_remove_oneoff_bank_details,false) = true
  );

  if not v_can_edit_pre_draft then
    if v_amount_changed or v_comment_changed or v_taxability_changed or v_routing_changed or v_oneoff_change_requested then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'PAYOUT_ALREADY_DRAFTED_OR_COMMITTED',
        'message', 'pay_manual_credit_adjustment_update: amount, adjustment_comment, taxability, destination and one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;
  end if;

  v_before_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'taxability', case when v_current_taxability is null then null else v_current_taxability::text end,
    'routing_kind', case when v_current_routing_kind is null then null else v_current_routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required, false),
    'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end
  );

  v_component_before_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'resolution_fingerprint', v_component.resolution_fingerprint,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  if v_candidate_pay_method = 'PAYE' then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_manual_credit_adjustment_update: one-off bank fields are not allowed for PAYE manual credits',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null and v_can_edit_pre_draft = true then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'PAY_METHOD_NOW_PAYE',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_requested_routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum then
    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_UMBRELLA_TAXABLE',
        'message', 'pay_manual_credit_adjustment_update: one-off bank fields are only allowed for umbrella non-taxable manual credits',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null and v_can_edit_pre_draft = true then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'ROUTING_CHANGED_TO_UMBRELLA_COMPANY',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  else
    if v_oneoff_change_requested and not v_can_edit_pre_draft then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_LOCKED',
        'message', 'pay_manual_credit_adjustment_update: one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if coalesce(p_remove_oneoff_bank_details,false) = true then
      if v_existing_oneoff.finance_case_id is not null then
        v_oneoff_before := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        delete from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          'ONEOFF_BANK_DETAILS_REMOVED',
          v_oneoff_before,
          null::jsonb,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := null;
      v_readiness_payee_name := null;
    else
      if v_existing_oneoff.finance_case_id is not null then
        v_beneficiary_name_norm := coalesce(
          nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), ''),
          v_existing_oneoff.beneficiary_name
        );
        v_sort_code_norm := coalesce(
          case
            when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
            else null
          end,
          v_existing_oneoff.sort_code
        );
        v_account_number_norm := coalesce(
          nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), ''),
          v_existing_oneoff.account_number
        );
      else
        v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
        v_sort_code_norm := case
          when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
          else null
        end;
        v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');
      end if;

      if v_beneficiary_name_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'BENEFICIARY_NAME_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: beneficiary_name is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_sort_code_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'SORT_CODE_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: valid sort_code is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_account_number_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'ACCOUNT_NUMBER_REQUIRED',
          'message', 'pay_manual_credit_adjustment_update: valid account_number is required for umbrella non-taxable manual credits',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
      if v_oneoff_bank_hash is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_MANUAL_CREDIT_ADJUSTMENT_UPDATE',
          'code', 'BANK_DETAILS_HASH_FAILED',
          'message', 'pay_manual_credit_adjustment_update: unable to derive bank_details_hash for umbrella non-taxable manual credit bank details',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_can_edit_pre_draft then
        v_oneoff_before := case
          when v_existing_oneoff.finance_case_id is null then null
          else jsonb_build_object(
            'finance_case_id', p_finance_case_id::text,
            'candidate_id', v_case.candidate_id::text,
            'beneficiary_name', v_existing_oneoff.beneficiary_name,
            'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
            'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
            'bank_details_hash', v_existing_oneoff.bank_details_hash,
            'note', v_existing_oneoff.note
          )
        end;

        insert into public.pay_finance_case_oneoff_payout_bank_details(
          finance_case_id,
          candidate_id,
          beneficiary_name,
          sort_code,
          account_number,
          bank_details_hash,
          note,
          created_at_utc,
          created_by_user_id,
          updated_at_utc,
          updated_by_user_id
        )
        values (
          p_finance_case_id,
          v_case.candidate_id,
          v_beneficiary_name_norm,
          v_sort_code_norm,
          v_account_number_norm,
          v_oneoff_bank_hash,
          case when p_bank_details_note is null then coalesce(v_existing_oneoff.note, null) else nullif(btrim(coalesce(p_bank_details_note,'')), '') end,
          v_now_utc,
          p_actor_user_id,
          v_now_utc,
          p_actor_user_id
        )
        on conflict (finance_case_id) do update
        set candidate_id = excluded.candidate_id,
            beneficiary_name = excluded.beneficiary_name,
            sort_code = excluded.sort_code,
            account_number = excluded.account_number,
            bank_details_hash = excluded.bank_details_hash,
            note = excluded.note,
            updated_at_utc = excluded.updated_at_utc,
            updated_by_user_id = excluded.updated_by_user_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        v_oneoff_after := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          case when v_oneoff_before is null then 'ONEOFF_BANK_DETAILS_CREATED' else 'ONEOFF_BANK_DETAILS_UPDATED' end,
          v_oneoff_before,
          v_oneoff_after,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := v_oneoff_bank_hash;
      v_readiness_payee_name := v_beneficiary_name_norm;
    end if;
  end if;

  if v_can_edit_pre_draft then
    v_component_source_basis_json := jsonb_strip_nulls(
      jsonb_build_object(
        'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
        'amount', v_new_amount,
        'taxability', v_requested_taxability::text,
        'routing_kind', v_requested_routing_kind::text,
        'paye_treatment', v_paye_treatment,
        'paye_net_effect', v_paye_net_effect,
        'adjustment_comment', v_new_comment,
        'note', v_new_notes
      )
    );

    if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
      v_component_resolution_payload_json := jsonb_build_object(
        'same_channel', true,
        'target_amount', v_new_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_result_json := jsonb_build_object(
        'target_amount', v_new_amount,
        'target_amount_ex_vat', v_new_amount,
        'target_amount_vat', 0,
        'target_amount_inc_vat', v_new_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
        p_source_family_key         => v_component.source_family_key,
        p_component_key_type        => v_component.component_key_type,
        p_component_key_value       => v_component.component_key_value,
        p_classification            => v_component_classification,
        p_source_pay_method         => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json         => v_component_source_basis_json,
        p_source_amount             => v_new_amount,
        p_relevant_erni_pct         => null::numeric,
        p_target_basis_json         => jsonb_build_object('same_channel', true)
      );
    else
      v_component_resolution_payload_json := null;
      v_component_resolution_result_json := null;
      v_component_resolution_fingerprint := null;
    end if;

    v_component_changed := (
      round(coalesce(v_component.source_amount,0),2) is distinct from v_new_amount
      or coalesce(v_case.adjustment_comment,'') is distinct from coalesce(v_new_comment,'')
      or v_current_taxability is distinct from v_requested_taxability
      or v_current_routing_kind is distinct from v_requested_routing_kind
      or v_component.classification is distinct from v_component_classification
      or v_component.source_basis_json is distinct from v_component_source_basis_json
    );

    update public.pay_advances pa
    set original_amount = v_new_amount,
        outstanding_amount = v_new_amount,
        adjustment_comment = v_new_comment,
        notes = v_new_notes,
        updated_at = v_now_utc,
        taxability = v_requested_taxability,
        routing_kind = v_requested_routing_kind,
        oneoff_bank_details_required = v_requested_oneoff_required
    where pa.id = p_finance_case_id;

    update public.pay_finance_case_components pfc
    set classification = v_component_classification,
        source_pay_method = v_candidate_pay_method,
        source_basis_json = v_component_source_basis_json,
        source_amount = v_new_amount,
        remaining_source_amount = v_new_amount,
        saved_target_pay_method = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_candidate_pay_method else null end,
        saved_resolution_mode = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum else null end,
        saved_resolution_payload_json = v_component_resolution_payload_json,
        saved_resolution_result_json = v_component_resolution_result_json,
        resolution_fingerprint = v_component_resolution_fingerprint,
        is_resolution_stale = false,
        stale_reason = null::text,
        updated_at_utc = v_now_utc,
        resolved_at_utc = case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_now_utc else null end
    where pfc.id = v_component.id
    returning pfc.* into v_component;

    if v_has_batch then
      select pbc.id
      into v_pay_batch_candidate_id
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = v_batch.id
        and pbc.candidate_id = v_case.candidate_id
      limit 1;

      select pbi.id
      into v_batch_item_id
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc2
        on pbc2.id = pbi.pay_batch_candidate_id
      where pbc2.pay_batch_id = v_batch.id
        and pbc2.candidate_id = v_case.candidate_id
        and pbi.source_ref = ('advance:' || p_finance_case_id::text)
        and pbi.item_type = 'MANUAL_CREDIT_PAYOUT'
        and pbi.is_voided = false
      limit 1;

      if v_pay_batch_candidate_id is not null then
        update public.pay_batch_candidates pbc
        set gross_preview = v_new_amount,
            net_bank_amount = v_new_amount,
            updated_at = v_now_utc
        where pbc.id = v_pay_batch_candidate_id;
      end if;

      if v_batch_item_id is not null then
        v_component_snapshot_json := jsonb_build_object(
          'finance_component_id', v_component.id::text,
          'source_family_key', v_component.source_family_key,
          'component_key_type', v_component.component_key_type,
          'component_key_value', v_component.component_key_value,
          'classification', v_component.classification::text,
          'source_pay_method', v_component.source_pay_method,
          'source_basis_json', v_component.source_basis_json,
          'source_amount', round(coalesce(v_component.source_amount,0),2),
          'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
          'saved_target_pay_method', v_component.saved_target_pay_method,
          'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
          'saved_resolution_payload_json', v_component.saved_resolution_payload_json,
          'saved_resolution_result_json', v_component.saved_resolution_result_json,
          'resolution_fingerprint', v_component.resolution_fingerprint,
          'is_resolution_stale', v_component.is_resolution_stale
        );

        update public.pay_batch_items pbi
        set description = 'Manual credit adjustment',
            amount_ex_vat = v_new_amount,
            amount_vat = 0,
            amount_inc_vat = v_new_amount,
            updated_at = v_now_utc,
            finance_case_id = p_finance_case_id,
            reservation_id = null,
            paye_treatment = v_paye_treatment,
            finance_component_id = v_component.id,
            frozen_component_snapshot_json = v_component_snapshot_json,
            frozen_component_key_type = v_component.component_key_type,
            frozen_component_key_value = v_component.component_key_value,
            frozen_component_classification = v_component.classification,
            frozen_source_basis_json = v_component.source_basis_json,
            frozen_source_pay_method = v_component.source_pay_method,
            frozen_target_pay_method = v_component.saved_target_pay_method,
            frozen_resolution_mode = v_component.saved_resolution_mode,
            frozen_resolution_payload_json = v_component.saved_resolution_payload_json,
            frozen_resolution_result_json = v_component.saved_resolution_result_json,
            frozen_source_amount = v_component.source_amount,
            frozen_target_amount_ex_vat = v_new_amount,
            frozen_target_amount_vat = 0,
            frozen_target_amount_inc_vat = v_new_amount,
            payout_instruction_snapshot_json = case
              when v_requested_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum and v_existing_oneoff.finance_case_id is not null then
                jsonb_build_object(
                  'taxability', v_requested_taxability::text,
                  'routing_kind', v_requested_routing_kind::text,
                  'destination_label', 'one-off specified bank account',
                  'pay_channel', 'UMBRELLA',
                  'payee_entity_kind', 'CANDIDATE',
                  'payee_entity_id', v_case.candidate_id::text,
                  'beneficiary_name', v_existing_oneoff.beneficiary_name,
                  'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
                  'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
                  'bank_details_hash', v_existing_oneoff.bank_details_hash,
                  'bank_details_note', v_existing_oneoff.note,
                  'appears_on_umbrella_remittance', false,
                  'generates_candidate_payment_advice', true
                )
              else null
            end,
            pay_channel = v_candidate_pay_method,
            umbrella_id = case when v_candidate_pay_method = 'UMBRELLA' then v_candidate.umbrella_id else null::uuid end
        where pbi.id = v_batch_item_id;

        update public.pay_batch_item_breakdowns pbib
        set unit_name = 'Manual credit adjustment',
            amount_ex_vat = v_new_amount,
            amount_vat = 0,
            amount_inc_vat = v_new_amount,
            meta_json = jsonb_build_object(
              'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
              'worker_label', 'Manual credit adjustment',
              'adjustment_comment', v_new_comment,
              'finance_component_id', v_component.id::text,
              'taxability', v_requested_taxability::text,
              'routing_kind', v_requested_routing_kind::text,
              'paye_treatment', v_paye_treatment,
              'paye_net_effect', v_paye_net_effect
            )
        where pbib.pay_batch_item_id = v_batch_item_id;
      end if;
    end if;
  else
    update public.pay_advances pa
    set notes = v_new_notes,
        updated_at = v_now_utc
    where pa.id = p_finance_case_id;

    select pa.*
    into v_case
    from public.pay_advances pa
    where pa.id = p_finance_case_id;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  if v_requested_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
  elsif v_requested_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum and v_existing_oneoff.finance_case_id is not null then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_existing_oneoff.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_existing_oneoff.beneficiary_name,'')), '');
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  if v_requested_routing_kind in ('NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum, 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum) then
    if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
      v_warnings := v_warnings || jsonb_build_array(
        jsonb_build_object(
          'code', 'BLOCKED_BANK_DETAILS',
          'message', case when v_requested_routing_kind = 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum
                          then 'Bank details are missing; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.'
                          else 'One-off payout bank details are missing or incomplete; the manual credit adjustment will appear as Blocked for Pay until valid bank details are present.' end,
          'candidate_id', v_case.candidate_id::text
        )
      );
    else
      if v_need_name_check = true then
        select
          coalesce(bnc.status, 'UNVERIFIED') as status,
          (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
        into
          v_bnc_status,
          v_bnc_has_override
        from public.bank_name_checks bnc
        where bnc.rail_provider = v_settings.rail_provider_default
          and bnc.rail_env = v_settings.rail_env_default
          and bnc.entity_kind = v_readiness_entity_kind
          and bnc.entity_id = v_case.candidate_id
          and bnc.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NAME_CHECK',
              'message', 'Name check has not passed (or override missing) for the payout destination; the manual credit adjustment will appear as Blocked for Pay until resolved.',
              'candidate_id', v_case.candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;

      if v_requires_payee_map = true then
        select (bpm.payee_id is not null) as present
        into v_bpm_present
        from public.bank_payee_map bpm
        where bpm.rail_provider = v_settings.rail_provider_default
          and bpm.rail_env = v_settings.rail_env_default
          and bpm.entity_kind = v_readiness_entity_kind
          and bpm.entity_id = v_case.candidate_id
          and bpm.bank_details_hash = v_readiness_bank_hash
        limit 1;

        if coalesce(v_bpm_present,false) = false then
          v_warnings := v_warnings || jsonb_build_array(
            jsonb_build_object(
              'code', 'BLOCKED_NO_PAYEE_MAP',
              'message', 'Payee map is missing for the payout destination on this rail; the manual credit adjustment will appear as Blocked for Pay until payee mapping exists.',
              'candidate_id', v_case.candidate_id::text,
              'rail_provider', v_settings.rail_provider_default,
              'rail_env', v_settings.rail_env_default
            )
          );
        end if;
      end if;
    end if;
  end if;

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required,false),
    'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end
  );

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'resolution_fingerprint', v_component.resolution_fingerprint,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_before_json,
    v_after_json,
    null::text,
    case when v_can_edit_pre_draft then 'Manual credit adjustment updated while Not processed yet' else 'Manual credit adjustment notes updated after draft/commit' end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_component.id,
    'COMPONENT_UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_component_before_json,
    v_component_after_json,
    case when v_component_changed then 'COMPONENT_BASIS_CHANGED' else null::text end,
    case
      when v_can_edit_pre_draft = false then 'Manual credit adjustment draft or later; component basis preserved'
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'Manual credit adjustment taxable component updated before draft'
      else 'Manual credit adjustment non-taxable fixed component updated before draft'
    end
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'source_family_key', v_component.source_family_key,
    'component_key_type', v_component.component_key_type,
    'component_key_value', v_component.component_key_value,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'finance_component_id', v_component.id::text,
    'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end,
    'case_type', 'MANUAL_CREDIT_ADJUSTMENT',
    'worker_label', 'Manual credit adjustment',
    'payout_editable', v_can_edit_pre_draft,
    'paye_treatment', v_paye_treatment,
    'paye_net_effect', v_paye_net_effect,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', coalesce(v_case.oneoff_bank_details_required,false),
    'oneoff_bank_details_present', exists(
      select 1
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id
    ),
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_existing_oneoff.finance_case_id is null then null else v_existing_oneoff.beneficiary_name end,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;



CREATE OR REPLACE FUNCTION public.banking_alert_fingerprint(
  p_alert_kind text,
  p_entity_kind text,
  p_entity_id uuid,
  p_payload jsonb DEFAULT '{}'::jsonb
)
RETURNS text
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_kind text;
  v_entity_kind text;
  v_payload jsonb;
  v_stable_key text := NULL::text;
  v_payload_stable_key text := NULL::text;
  v_payload_dedupe_key text := NULL::text;
  v_pay_batch_id text := NULL::text;
  v_issue_key text := NULL::text;
  v_provider_key text := NULL::text;
  v_rail_env text := NULL::text;
  v_retry_operation_id text := NULL::text;
  v_outage_window text := NULL::text;
  v_correction_request_id text := NULL::text;
  v_cancellation_operation_id text := NULL::text;
  v_transfer_id text := NULL::text;
  v_manual_blocker_key text := NULL::text;
  v_provider_event_key text := NULL::text;
  v_issue_window text := NULL::text;
  v_terminal_failure_group_key text := NULL::text;
BEGIN
  v_alert_kind := UPPER(NULLIF(BTRIM(COALESCE(p_alert_kind, '')), ''));
  v_entity_kind := LOWER(NULLIF(BTRIM(COALESCE(p_entity_kind, '')), ''));

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_KIND_REQUIRED')::text;
  END IF;

  IF v_entity_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_ENTITY_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_ENTITY_KIND_REQUIRED')::text;
  END IF;

  IF p_entity_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_ENTITY_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_FINGERPRINT_ENTITY_ID_REQUIRED')::text;
  END IF;

  IF p_payload IS NOT NULL AND COALESCE(jsonb_typeof(p_payload), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANKING_ALERT_FINGERPRINT_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_FINGERPRINT_PAYLOAD_MUST_BE_OBJECT',
              'alert_kind', v_alert_kind,
              'entity_kind', v_entity_kind,
              'entity_id', p_entity_id::text
            )::text;
  END IF;

  v_payload := COALESCE(p_payload, '{}'::jsonb);

  v_payload_stable_key := NULLIF(BTRIM(COALESCE(v_payload->>'stable_issue_key', '')), '');
  v_payload_dedupe_key := NULLIF(BTRIM(COALESCE(v_payload->>'dedupe_key', '')), '');

  v_pay_batch_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'pay_batch_id'), ''),
    CASE WHEN v_entity_kind IN ('pay_batch', 'pay_batches') THEN p_entity_id::text ELSE NULL END
  );

  v_provider_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'provider'), ''),
    NULLIF(BTRIM(v_payload->>'rail'), ''),
    NULLIF(BTRIM(v_payload->>'rail_provider'), ''),
    NULLIF(BTRIM(v_payload->>'provider_key'), ''),
    'UNKNOWN_PROVIDER'
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_payload->>'rail_env'), ''),
    NULLIF(BTRIM(v_payload->>'provider_env'), ''),
    NULLIF(BTRIM(v_payload->>'environment'), ''),
    'UNKNOWN_ENV'
  );

  v_retry_operation_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'retry_operation_id'), ''),
    NULLIF(BTRIM(v_payload->>'retry_operation_key'), '')
  );

  v_outage_window := COALESCE(
    NULLIF(BTRIM(v_payload->>'outage_window'), ''),
    NULLIF(BTRIM(v_payload->>'retry_window'), ''),
    NULLIF(BTRIM(v_payload->>'provider_outage_window'), '')
  );

  v_correction_request_id := NULLIF(BTRIM(COALESCE(v_payload->>'correction_request_id', '')), '');
  v_cancellation_operation_id := COALESCE(
    NULLIF(BTRIM(v_payload->>'cancellation_operation_id'), ''),
    NULLIF(BTRIM(v_payload->>'correction_request_id'), '')
  );
  v_transfer_id := NULLIF(BTRIM(COALESCE(v_payload->>'pay_bank_transfer_id', '')), '');
  v_manual_blocker_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'carry_forward_id'), ''),
    NULLIF(BTRIM(v_payload->>'source_pay_batch_item_id'), '')
  );

  v_provider_event_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'provider_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_webhook_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_transaction_id'), ''),
    NULLIF(BTRIM(v_payload->>'provider_request_id'), '')
  );

  v_issue_window := COALESCE(
    NULLIF(BTRIM(v_payload->>'issue_window'), ''),
    NULLIF(BTRIM(v_payload->>'outcome_unknown_window'), ''),
    NULLIF(BTRIM(v_payload->>'outage_window'), ''),
    NULLIF(BTRIM(v_payload->>'retry_window'), '')
  );

  v_terminal_failure_group_key := COALESCE(
    NULLIF(BTRIM(v_payload->>'terminal_failure_group_key'), ''),
    NULLIF(BTRIM(v_payload->>'provider_failure_reason_group'), ''),
    NULLIF(BTRIM(v_payload->>'failure_reason_group'), ''),
    NULLIF(BTRIM(v_payload->>'provider_event_key'), ''),
    NULLIF(BTRIM(v_payload->>'dedupe_key'), '')
  );

  v_issue_key := CASE
    WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      v_provider_key,
      v_rail_env,
      COALESCE(v_retry_operation_id, v_outage_window, v_issue_window, 'NO_WINDOW')
    )
    WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      v_provider_key,
      COALESCE(v_issue_window, 'NO_WINDOW')
    )
    WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, 'NO_BATCH'),
      v_alert_kind,
      v_provider_key,
      COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
    )
    WHEN v_alert_kind = 'AUTO_UNWIND_PROGRESS'
      AND v_correction_request_id IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_correction_request_id
      )
    WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
      AND v_cancellation_operation_id IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_cancellation_operation_id
      )
    WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN CONCAT_WS(
      ':',
      COALESCE(v_pay_batch_id, p_entity_id::text),
      v_alert_kind,
      COALESCE(v_correction_request_id, v_terminal_failure_group_key, v_transfer_id, 'NO_TERMINAL_FAILURE_KEY')
    )
    WHEN v_alert_kind IN (
      'PAID_SETTLED_RECOVERY_REQUIRED',
      'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
    )
      AND COALESCE(v_transfer_id, v_correction_request_id, v_terminal_failure_group_key) IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        COALESCE(v_transfer_id, v_correction_request_id, v_terminal_failure_group_key)
      )
    WHEN v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
      AND v_manual_blocker_key IS NOT NULL THEN CONCAT_WS(
        ':',
        COALESCE(v_pay_batch_id, p_entity_id::text),
        v_alert_kind,
        v_manual_blocker_key
      )
    ELSE NULL::text
  END;

  v_stable_key := COALESCE(
    v_payload_stable_key,
    v_payload_dedupe_key,
    v_issue_key,
    CONCAT_WS(':', COALESCE(v_pay_batch_id, p_entity_id::text), v_alert_kind)
  );

  RETURN 'banking_alert:v2:' || MD5(CONCAT_WS(':', v_entity_kind, v_stable_key));
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_alerts_active_for_user(
  p_actor_user_id uuid,
  p_entity_kind text DEFAULT NULL::text,
  p_entity_id uuid DEFAULT NULL::uuid,
  p_include_acknowledged boolean DEFAULT false,
  p_limit integer DEFAULT 100
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_entity_kind text := LOWER(NULLIF(BTRIM(COALESCE(p_entity_kind, '')), ''));
  v_limit integer := NULL::integer;
  v_result jsonb := '{}'::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERTS_ACTIVE_FOR_USER_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERTS_ACTIVE_FOR_USER_ACTOR_REQUIRED')::text;
  END IF;

  IF p_limit IS NULL THEN
    v_limit := 100;
  ELSIF p_limit = 0 THEN
    v_limit := 100;
  ELSE
    v_limit := LEAST(GREATEST(p_limit, 1), 500);
  END IF;

  WITH blocked_funds_base AS (
    SELECT
      blocked_funds_pay_batches.id AS pay_batch_id,
      blocked_funds_pay_batches.status AS batch_status,
      blocked_funds_pay_batches.execution_commit_state AS execution_commit_state,
      blocked_funds_pay_batches.execution_commit_ref AS execution_commit_ref,
      blocked_funds_pay_batches.execution_committed_at_utc AS execution_committed_at_utc,
      blocked_funds_pay_batches.last_funds_check_at_utc AS last_funds_check_at_utc,
      blocked_funds_pay_batches.last_funds_check_json AS last_funds_check_json,
      blocked_funds_pay_batches.funding_account_ref AS funding_account_ref,
      blocked_funds_pay_batches.rail_provider_snapshot AS rail_provider_snapshot,
      blocked_funds_pay_batches.rail_env_snapshot AS rail_env_snapshot,
      COALESCE(
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{required_gbp}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{required}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{required_amount_gbp}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{required_amount}'), '')
      ) AS required_gbp_text,
      COALESCE(
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{available_gbp}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{available}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{available_amount_gbp}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{available_amount}'), '')
      ) AS available_gbp_text,
      COALESCE(
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{funding_account_ref}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{account_ref}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{funding_account_id}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.funding_account_ref), '')
      ) AS resolved_funding_account_ref,
      COALESCE(
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{rail_provider}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{provider}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.rail_provider_snapshot), '')
      ) AS resolved_rail_provider,
      COALESCE(
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{rail_env}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.last_funds_check_json #>> '{env}'), ''),
        NULLIF(BTRIM(blocked_funds_pay_batches.rail_env_snapshot), '')
      ) AS resolved_rail_env
    FROM public.pay_batches AS blocked_funds_pay_batches
    WHERE UPPER(BTRIM(COALESCE(blocked_funds_pay_batches.status, ''))) = 'BLOCKED_FUNDS'
      AND UPPER(BTRIM(COALESCE(blocked_funds_pay_batches.execution_commit_state, 'NOT_SUBMITTED'))) = 'NOT_SUBMITTED'
      AND NULLIF(BTRIM(COALESCE(blocked_funds_pay_batches.execution_commit_ref, '')), '') IS NULL
      AND blocked_funds_pay_batches.execution_committed_at_utc IS NULL
      AND blocked_funds_pay_batches.cancelled_at_utc IS NULL
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_candidates AS blocked_funds_candidate_exists
        JOIN public.pay_batch_items AS blocked_funds_item_exists
          ON blocked_funds_item_exists.pay_batch_candidate_id = blocked_funds_candidate_exists.id
        WHERE blocked_funds_candidate_exists.pay_batch_id = blocked_funds_pay_batches.id
          AND COALESCE(blocked_funds_item_exists.is_voided, false) = false
      )
  ),
  blocked_funds_alerts AS MATERIALIZED (
    SELECT
      'PROVIDER_OUTAGE_RETRY_LATER'::text AS alert_kind,
      'critical'::text AS severity,
      100::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      blocked_funds_base.pay_batch_id AS entity_id,
      blocked_funds_base.pay_batch_id AS pay_batch_id,
      NULL::text AS payload_source_kind,
      NULL::uuid AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'pay_batch',
        'fingerprint_source_id', blocked_funds_base.pay_batch_id::text,
        'issue_kind', 'PROVIDER_OUTAGE_RETRY_LATER',
        'pay_batch_id', blocked_funds_base.pay_batch_id::text,
        'batch_status', UPPER(BTRIM(COALESCE(blocked_funds_base.batch_status, ''))),
        'execution_commit_state', UPPER(BTRIM(COALESCE(blocked_funds_base.execution_commit_state, 'NOT_SUBMITTED'))),
        'execution_commit_ref', NULLIF(BTRIM(COALESCE(blocked_funds_base.execution_commit_ref, '')), ''),
        'execution_committed_at_utc', CASE
          WHEN blocked_funds_base.execution_committed_at_utc IS NULL THEN NULL::text
          ELSE TO_CHAR(blocked_funds_base.execution_committed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'last_funds_check_at_utc', CASE
          WHEN blocked_funds_base.last_funds_check_at_utc IS NULL THEN NULL::text
          ELSE TO_CHAR(blocked_funds_base.last_funds_check_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'required_gbp', CASE
          WHEN blocked_funds_base.required_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN blocked_funds_base.required_gbp_text::numeric
          ELSE NULL::numeric
        END,
        'available_gbp', CASE
          WHEN blocked_funds_base.available_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN blocked_funds_base.available_gbp_text::numeric
          ELSE NULL::numeric
        END,
        'funding_account_ref', blocked_funds_base.resolved_funding_account_ref,
        'rail_provider', blocked_funds_base.resolved_rail_provider,
        'rail_env', blocked_funds_base.resolved_rail_env
      )) AS fingerprint_payload_json,
      'Bank unavailable — unsent payments can be retried'::text AS label,
      'Bank unavailable — unsent payments can be retried'::text AS title,
      ('Bank unavailable — required '
        || COALESCE(NULLIF(BTRIM(blocked_funds_base.required_gbp_text), ''), '—')
        || ', available '
        || COALESCE(NULLIF(BTRIM(blocked_funds_base.available_gbp_text), ''), '—')
        || '. Payments were not sent to the bank/provider and can be retried from Overview.')::text AS description,
      'Open Banking Pay Overview and retry unsent payments.'::text AS action_guidance,
      blocked_funds_base.last_funds_check_at_utc AS sort_at_utc
    FROM blocked_funds_base
  ),
  bank_event_base AS MATERIALIZED (
    SELECT
      CASE
        WHEN (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_failure_reason_group, ''))) = 'WEBHOOK_UNMATCHED'
            OR (
              UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.mapping_status, ''))) IN ('UNMATCHED','NO_MATCH')
              AND UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_event_transport, public.pay_bank_transfer_events.event_source, ''))) IN ('PROVIDER_WEBHOOK','FAILED_WEBHOOK_REPLAY','WEBHOOK')
            )
          )
          THEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.mapping_status, ''))) IN ('AMBIGUOUS','UNMATCHED','NO_MATCH','MULTIPLE_MATCHES')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) IN ('AMBIGUOUS','ACTION_REQUIRED')
          THEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) = 'FAILED'
          THEN 'PAYMENT_CORRECTION_FAILED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) = 'BLOCKED'
          THEN 'PAYMENT_CORRECTION_BLOCKED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('RETURNED','REVERTED')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('RETURNED','REVERTED')
          THEN 'BANK_RETURNED_PAYMENT'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED')
          THEN 'BANK_REJECTED_PAYMENT'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) LIKE 'CREATE_ERROR%'
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) LIKE 'CREATE_ERROR%'
          THEN 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
        ELSE NULL::text
      END AS alert_kind,
      public.pay_bank_transfer_events.pay_batch_id AS pay_batch_id,
      public.pay_bank_transfer_events.id AS source_id,
      public.pay_bank_transfer_events.normalised_state AS normalised_state,
      public.pay_bank_transfer_events.provider_state AS provider_state,
      public.pay_bank_transfer_events.mapping_status AS mapping_status,
      public.pay_bank_transfer_events.correction_disposition AS correction_disposition,
      public.pay_bank_transfer_events.event_time_utc AS event_time_utc,
      public.pay_bank_transfer_events.received_at_utc AS received_at_utc,
      public.pay_bank_transfer_events.created_at_utc AS created_at_utc,
      COALESCE(NULLIF(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_key, '')), ''), NULLIF(BTRIM(COALESCE(bank_event_batches.rail_provider_snapshot, '')), ''), 'UNKNOWN_PROVIDER') AS provider_key,
      COALESCE(NULLIF(BTRIM(COALESCE(public.pay_bank_transfer_events.rail_env, '')), ''), NULLIF(BTRIM(COALESCE(bank_event_batches.rail_env_snapshot, '')), ''), 'PROD') AS rail_env,
      NULLIF(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_event_key, '')), '') AS provider_event_key,
      NULLIF(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_failure_reason_code, '')), '') AS provider_failure_reason_code,
      NULLIF(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_failure_reason_group, '')), '') AS provider_failure_reason_group,
      public.pay_bank_transfer_events.provider_webhook_receipt_id AS provider_webhook_receipt_id,
      COALESCE(public.pay_bank_transfer_events.event_time_utc, public.pay_bank_transfer_events.received_at_utc, public.pay_bank_transfer_events.created_at_utc) AS sort_at_utc
    FROM public.pay_bank_transfer_events
    JOIN public.pay_batches AS bank_event_batches
      ON bank_event_batches.id = public.pay_bank_transfer_events.pay_batch_id
    WHERE UPPER(BTRIM(COALESCE(bank_event_batches.status, ''))) NOT IN ('CANCELLED','CANCELED')
      AND (
        UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) LIKE 'CREATE_ERROR%'
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) LIKE 'CREATE_ERROR%'
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.mapping_status, ''))) IN ('AMBIGUOUS','UNMATCHED','NO_MATCH','MULTIPLE_MATCHES')
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) IN ('AMBIGUOUS','ACTION_REQUIRED','BLOCKED','FAILED')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_requests AS resolved_event_corrections
        WHERE resolved_event_corrections.source_bank_event_id = public.pay_bank_transfer_events.id
          AND UPPER(BTRIM(COALESCE(resolved_event_corrections.status, ''))) IN ('APPLIED','RESOLVED')
      )
  ),
  bank_event_alerts AS MATERIALIZED (
    SELECT
      bank_event_base.alert_kind,
      'critical'::text AS severity,
      CASE bank_event_base.alert_kind
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 96
        WHEN 'BANK_RETURNED_PAYMENT' THEN 95
        WHEN 'BANK_REJECTED_PAYMENT' THEN 94
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 90
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 88
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 87
        ELSE 80
      END::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      bank_event_base.pay_batch_id AS entity_id,
      bank_event_base.pay_batch_id AS pay_batch_id,
      'pay_bank_transfer_event'::text AS payload_source_kind,
      bank_event_base.source_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'pay_bank_transfer_event',
        'fingerprint_source_id', bank_event_base.source_id::text,
        'issue_kind', bank_event_base.alert_kind,
        'alert_kind', bank_event_base.alert_kind,
        'pay_batch_id', bank_event_base.pay_batch_id::text,
        'provider_key', bank_event_base.provider_key,
        'rail_provider', bank_event_base.provider_key,
        'rail_env', bank_event_base.rail_env,
        'provider_event_key', bank_event_base.provider_event_key,
        'provider_webhook_receipt_id', CASE WHEN bank_event_base.provider_webhook_receipt_id IS NULL THEN NULL ELSE bank_event_base.provider_webhook_receipt_id::text END,
        'provider_failure_reason_code', bank_event_base.provider_failure_reason_code,
        'provider_failure_reason_group', CASE WHEN bank_event_base.alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(bank_event_base.provider_failure_reason_group, 'WEBHOOK_UNMATCHED') ELSE bank_event_base.provider_failure_reason_group END,
        'normalised_state', NULLIF(BTRIM(COALESCE(bank_event_base.normalised_state, '')), ''),
        'provider_state', NULLIF(BTRIM(COALESCE(bank_event_base.provider_state, '')), ''),
        'mapping_status', NULLIF(BTRIM(COALESCE(bank_event_base.mapping_status, '')), ''),
        'correction_disposition', NULLIF(BTRIM(COALESCE(bank_event_base.correction_disposition, '')), ''),
        'event_time_utc', CASE WHEN bank_event_base.event_time_utc IS NULL THEN NULL::text ELSE TO_CHAR(bank_event_base.event_time_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
        'received_at_utc', CASE WHEN bank_event_base.received_at_utc IS NULL THEN NULL::text ELSE TO_CHAR(bank_event_base.received_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END
      )) AS fingerprint_payload_json,
      CASE bank_event_base.alert_kind
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched bank webhook'
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider outcome unknown — check provider'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'Failed payments — Rewind financials available'
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'Payment needs review'
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'Payment correction blocked'
        ELSE 'Rail submission needs review'
      END::text AS label,
      CASE bank_event_base.alert_kind
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched provider webhook needs review'
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider outcome unknown — check provider'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'Failed payments — Rewind financials available'
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'Payment event needs review'
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'Payment correction blocked'
        ELSE 'Rail submission needs review'
      END::text AS title,
      CASE bank_event_base.alert_kind
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'A verified provider webhook could not be matched safely and needs review.'
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider returned/reverted status requires checking before any financial correction.'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'The provider/bank outcome indicates no money moved. Open Current Payment Status and rewind financials where safe.'
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'A bank payment event could not be matched safely and needs review.'
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'CloudTMS could not complete a payment correction automatically.'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'A payment correction is blocked and needs review.'
        ELSE 'CloudTMS could not confirm the final bank submission state.'
      END::text AS description,
      CASE bank_event_base.alert_kind
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Review the unmatched provider webhook.'
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Open Current Payment Status and review the payment status.'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'Open Current Payment Status and rewind financials where no money moved.'
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'Review and resolve the ambiguous bank event.'
        ELSE 'Open Current Payment Status.'
      END::text AS action_guidance,
      bank_event_base.sort_at_utc
    FROM bank_event_base
    WHERE bank_event_base.alert_kind IS NOT NULL
  ),
  transfer_base AS MATERIALIZED (
    SELECT
      CASE
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('RETURNED','REVERTED')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('RETURNED','REVERTED') THEN 'BANK_RETURNED_PAYMENT'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT')
          OR NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL THEN 'BANK_REJECTED_PAYMENT'
        WHEN UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) LIKE 'CREATE_ERROR%'
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) LIKE 'CREATE_ERROR%' THEN 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
        ELSE NULL::text
      END AS alert_kind,
      public.pay_bank_transfers.pay_batch_id AS pay_batch_id,
      public.pay_bank_transfers.id AS source_id,
      public.pay_bank_transfers.status AS transfer_status,
      public.pay_bank_transfers.rail_state AS rail_state,
      public.pay_bank_transfers.failed_reason AS failed_reason,
      public.pay_bank_transfers.completed_at_utc AS completed_at_utc,
      public.pay_bank_transfers.created_at_utc AS created_at_utc,
      COALESCE(public.pay_bank_transfers.completed_at_utc, public.pay_bank_transfers.created_at_utc) AS sort_at_utc
    FROM public.pay_bank_transfers
    JOIN public.pay_batches AS transfer_batches
      ON transfer_batches.id = public.pay_bank_transfers.pay_batch_id
    WHERE UPPER(BTRIM(COALESCE(transfer_batches.status, ''))) NOT IN ('CANCELLED','CANCELED')
      AND (
        UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) LIKE 'CREATE_ERROR%'
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
        OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) LIKE 'CREATE_ERROR%'
        OR NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS transfer_resolution_events
        WHERE transfer_resolution_events.pay_bank_transfer_id = public.pay_bank_transfers.id
          AND UPPER(BTRIM(COALESCE(transfer_resolution_events.correction_disposition, ''))) IN ('NO_CORRECTION_REQUIRED','AUTO_APPLIED','APPLIED','RESOLVED')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS transfer_resolved_work_items
        JOIN public.pay_payment_correction_requests AS transfer_resolved_requests
          ON transfer_resolved_requests.id = transfer_resolved_work_items.correction_request_id
        WHERE transfer_resolved_work_items.pay_bank_transfer_id = public.pay_bank_transfers.id
          AND UPPER(BTRIM(COALESCE(transfer_resolved_requests.status, ''))) IN ('APPLIED','RESOLVED')
      )
  ),
  transfer_alerts AS MATERIALIZED (
    SELECT
      transfer_base.alert_kind,
      'critical'::text AS severity,
      CASE transfer_base.alert_kind
        WHEN 'BANK_RETURNED_PAYMENT' THEN 93
        WHEN 'BANK_REJECTED_PAYMENT' THEN 92
        ELSE 79
      END::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      transfer_base.pay_batch_id AS entity_id,
      transfer_base.pay_batch_id AS pay_batch_id,
      'pay_bank_transfer'::text AS payload_source_kind,
      transfer_base.source_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'pay_bank_transfer',
        'fingerprint_source_id', transfer_base.source_id::text,
        'issue_kind', transfer_base.alert_kind,
        'pay_batch_id', transfer_base.pay_batch_id::text,
        'status', NULLIF(BTRIM(COALESCE(transfer_base.transfer_status, '')), ''),
        'rail_state', NULLIF(BTRIM(COALESCE(transfer_base.rail_state, '')), ''),
        'failed_reason_hash', CASE WHEN NULLIF(BTRIM(COALESCE(transfer_base.failed_reason, '')), '') IS NULL THEN NULL::text ELSE MD5(transfer_base.failed_reason) END,
        'completed_at_utc', CASE WHEN transfer_base.completed_at_utc IS NULL THEN NULL::text ELSE TO_CHAR(transfer_base.completed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
        'created_at_utc', CASE WHEN transfer_base.created_at_utc IS NULL THEN NULL::text ELSE TO_CHAR(transfer_base.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END
      )) AS fingerprint_payload_json,
      CASE transfer_base.alert_kind
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider outcome unknown — check provider'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'Failed payments — Rewind financials available'
        ELSE 'Rail submission needs review'
      END::text AS label,
      CASE transfer_base.alert_kind
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider outcome unknown — check provider'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'Failed payments — Rewind financials available'
        ELSE 'Rail submission needs review'
      END::text AS title,
      CASE transfer_base.alert_kind
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Provider returned/reverted status requires checking before any financial correction.'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'The bank rejected a payment transfer.'
        ELSE 'CloudTMS could not confirm the final bank submission state.'
      END::text AS description,
      CASE transfer_base.alert_kind
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'Open Current Payment Status and review the payment status.'
        ELSE 'Open Current Payment Status.'
      END::text AS action_guidance,
      transfer_base.sort_at_utc
    FROM transfer_base
    WHERE transfer_base.alert_kind IS NOT NULL
  ),
  correction_request_base AS MATERIALIZED (
    SELECT
      CASE
        WHEN UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('FAILED','FAILED_RETRYABLE','FAILED_FINAL') THEN 'PAYMENT_CORRECTION_FAILED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('BLOCKED','APPLIED_WITH_BLOCKERS') THEN 'PAYMENT_CORRECTION_BLOCKED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('REQUESTED','AWAITING_AUTHORISATION','AWAITING_AUTHORIZATION','PENDING_APPROVAL') THEN 'PAYMENT_CORRECTION_AWAITING_APPROVAL'
        ELSE NULL::text
      END AS alert_kind,
      public.pay_payment_correction_requests.pay_batch_id AS pay_batch_id,
      public.pay_payment_correction_requests.id AS source_id,
      public.pay_payment_correction_requests.status AS request_status,
      public.pay_payment_correction_requests.correction_kind AS correction_kind,
      public.pay_payment_correction_requests.selection_hash AS selection_hash,
      public.pay_payment_correction_requests.updated_at_utc AS updated_at_utc,
      public.pay_payment_correction_requests.created_at_utc AS created_at_utc,
      public.pay_payment_correction_requests.requested_at_utc AS requested_at_utc,
      COALESCE(public.pay_payment_correction_requests.updated_at_utc, public.pay_payment_correction_requests.created_at_utc, public.pay_payment_correction_requests.requested_at_utc) AS sort_at_utc
    FROM public.pay_payment_correction_requests
    JOIN public.pay_batches AS correction_request_batches
      ON correction_request_batches.id = public.pay_payment_correction_requests.pay_batch_id
    WHERE UPPER(BTRIM(COALESCE(correction_request_batches.status, ''))) NOT IN ('CANCELLED','CANCELED')
      AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('FAILED','FAILED_RETRYABLE','FAILED_FINAL','BLOCKED','APPLIED_WITH_BLOCKERS','REQUESTED','AWAITING_AUTHORISATION','AWAITING_AUTHORIZATION','PENDING_APPROVAL')
  ),
  correction_request_alerts AS MATERIALIZED (
    SELECT
      correction_request_base.alert_kind,
      'critical'::text AS severity,
      CASE correction_request_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 88
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 87
        ELSE 75
      END::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      correction_request_base.pay_batch_id AS entity_id,
      correction_request_base.pay_batch_id AS pay_batch_id,
      'pay_payment_correction_request'::text AS payload_source_kind,
      correction_request_base.source_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'pay_payment_correction_request',
        'fingerprint_source_id', correction_request_base.source_id::text,
        'issue_kind', correction_request_base.alert_kind,
        'pay_batch_id', correction_request_base.pay_batch_id::text,
        'status', NULLIF(BTRIM(COALESCE(correction_request_base.request_status, '')), ''),
        'correction_kind', NULLIF(BTRIM(COALESCE(correction_request_base.correction_kind, '')), ''),
        'selection_hash', NULLIF(BTRIM(COALESCE(correction_request_base.selection_hash, '')), '')
      )) AS fingerprint_payload_json,
      CASE correction_request_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'Payment correction blocked'
        ELSE 'Payment correction awaiting approval'
      END::text AS label,
      CASE correction_request_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'Payment correction blocked'
        ELSE 'Payment correction awaiting approval'
      END::text AS title,
      CASE correction_request_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'CloudTMS could not complete a payment correction automatically.'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'A payment correction is blocked and needs review.'
        ELSE 'A payment correction is awaiting approval.'
      END::text AS description,
      CASE correction_request_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_AWAITING_APPROVAL' THEN 'Review and approve or reject the correction request.'
        ELSE 'Open Current Payment Status.'
      END::text AS action_guidance,
      correction_request_base.sort_at_utc
    FROM correction_request_base
    WHERE correction_request_base.alert_kind IS NOT NULL
  ),
  correction_work_base AS MATERIALIZED (
    SELECT
      CASE
        WHEN UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('FAILED','FAILED_RETRYABLE','FAILED_FINAL') THEN 'PAYMENT_CORRECTION_FAILED'
        WHEN UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('BLOCKED','APPLIED_WITH_BLOCKERS') THEN 'PAYMENT_CORRECTION_BLOCKED'
        ELSE NULL::text
      END AS alert_kind,
      public.pay_payment_correction_work_items.pay_batch_id AS pay_batch_id,
      public.pay_payment_correction_work_items.id AS source_id,
      public.pay_payment_correction_work_items.status AS work_status,
      public.pay_payment_correction_work_items.work_kind AS work_kind,
      public.pay_payment_correction_work_items.selection_hash AS selection_hash,
      public.pay_payment_correction_work_items.processed_at_utc AS processed_at_utc,
      public.pay_payment_correction_work_items.created_at_utc AS created_at_utc,
      COALESCE(public.pay_payment_correction_work_items.processed_at_utc, public.pay_payment_correction_work_items.created_at_utc) AS sort_at_utc
    FROM public.pay_payment_correction_work_items
    JOIN public.pay_batches AS correction_work_batches
      ON correction_work_batches.id = public.pay_payment_correction_work_items.pay_batch_id
    WHERE UPPER(BTRIM(COALESCE(correction_work_batches.status, ''))) NOT IN ('CANCELLED','CANCELED')
      AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('FAILED','FAILED_RETRYABLE','FAILED_FINAL','BLOCKED','APPLIED_WITH_BLOCKERS')
  ),
  correction_work_alerts AS MATERIALIZED (
    SELECT
      correction_work_base.alert_kind,
      'critical'::text AS severity,
      CASE correction_work_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 86
        ELSE 85
      END::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      correction_work_base.pay_batch_id AS entity_id,
      correction_work_base.pay_batch_id AS pay_batch_id,
      'pay_payment_correction_work_item'::text AS payload_source_kind,
      correction_work_base.source_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'pay_payment_correction_work_item',
        'fingerprint_source_id', correction_work_base.source_id::text,
        'issue_kind', correction_work_base.alert_kind,
        'pay_batch_id', correction_work_base.pay_batch_id::text,
        'status', NULLIF(BTRIM(COALESCE(correction_work_base.work_status, '')), ''),
        'work_kind', NULLIF(BTRIM(COALESCE(correction_work_base.work_kind, '')), ''),
        'selection_hash', NULLIF(BTRIM(COALESCE(correction_work_base.selection_hash, '')), '')
      )) AS fingerprint_payload_json,
      CASE correction_work_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        ELSE 'Payment correction blocked'
      END::text AS label,
      CASE correction_work_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'Payment correction failed'
        ELSE 'Payment correction blocked'
      END::text AS title,
      CASE correction_work_base.alert_kind
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'CloudTMS could not complete a payment correction work item automatically.'
        ELSE 'A payment correction work item is blocked and needs review.'
      END::text AS description,
      'Open Current Payment Status.'::text AS action_guidance,
      correction_work_base.sort_at_utc
    FROM correction_work_base
    WHERE correction_work_base.alert_kind IS NOT NULL
  ),
  remittance_base AS MATERIALIZED (
    SELECT
      public.mail_outbox.context_id AS pay_batch_id,
      public.mail_outbox.id AS source_id,
      public.mail_outbox.reference AS reference,
      public.mail_outbox.failed_at AS failed_at,
      public.mail_outbox.created_at_utc AS created_at_utc,
      COALESCE(public.mail_outbox.failed_at, public.mail_outbox.created_at_utc) AS sort_at_utc
    FROM public.mail_outbox
    JOIN public.pay_batches AS remittance_batches
      ON remittance_batches.id = public.mail_outbox.context_id
    WHERE UPPER(BTRIM(COALESCE(remittance_batches.status, ''))) NOT IN ('CANCELLED','CANCELED')
      AND UPPER(BTRIM(COALESCE(public.mail_outbox.type, ''))) = 'REMITTANCE'
      AND LOWER(BTRIM(COALESCE(public.mail_outbox.context_kind, ''))) = 'pay_batches'
      AND public.mail_outbox.context_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(public.mail_outbox.status::text, ''))) = 'FAILED'
      AND NOT EXISTS (
        SELECT 1
        FROM public.mail_outbox AS remittance_success_outbox
        WHERE UPPER(BTRIM(COALESCE(remittance_success_outbox.type, ''))) = 'REMITTANCE'
          AND LOWER(BTRIM(COALESCE(remittance_success_outbox.context_kind, ''))) = 'pay_batches'
          AND remittance_success_outbox.context_id = public.mail_outbox.context_id
          AND COALESCE(NULLIF(BTRIM(remittance_success_outbox.reference), ''), remittance_success_outbox.id::text) = COALESCE(NULLIF(BTRIM(public.mail_outbox.reference), ''), public.mail_outbox.id::text)
          AND UPPER(BTRIM(COALESCE(remittance_success_outbox.status::text, ''))) = 'SENT'
          AND COALESCE(remittance_success_outbox.sent_at, remittance_success_outbox.created_at_utc) >= COALESCE(public.mail_outbox.failed_at, public.mail_outbox.created_at_utc)
      )
  ),
  remittance_alerts AS MATERIALIZED (
    SELECT
      'REMITTANCE_SEND_FAILED'::text AS alert_kind,
      'critical'::text AS severity,
      60::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      remittance_base.pay_batch_id AS entity_id,
      remittance_base.pay_batch_id AS pay_batch_id,
      'mail_outbox'::text AS payload_source_kind,
      remittance_base.source_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'fingerprint_source_kind', 'mail_outbox',
        'fingerprint_source_id', remittance_base.source_id::text,
        'issue_kind', 'REMITTANCE_SEND_FAILED',
        'pay_batch_id', remittance_base.pay_batch_id::text,
        'reference', NULLIF(BTRIM(COALESCE(remittance_base.reference, '')), ''),
        'failed_at_utc', CASE WHEN remittance_base.failed_at IS NULL THEN NULL::text ELSE TO_CHAR(remittance_base.failed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END
      )) AS fingerprint_payload_json,
      'Remittance failed'::text AS label,
      'Remittance send failed'::text AS title,
      'A remittance email failed to send and requires review.'::text AS description,
      'Review or resend the remittance from the batch.'::text AS action_guidance,
      remittance_base.sort_at_utc
    FROM remittance_base
  ),

  provider_submit_review_scope AS MATERIALIZED (
    SELECT DISTINCT
      provider_operation.id AS operation_id,
      provider_operation.pay_batch_id AS pay_batch_id,
      provider_operation.status AS operation_status,
      provider_operation.phase AS operation_phase,
      COALESCE(provider_operation.updated_at_utc, provider_operation.created_at_utc, now()) AS sort_at_utc
    FROM public.banking_pay_operations AS provider_operation
    JOIN public.pay_batches AS provider_batch
      ON provider_batch.id = provider_operation.pay_batch_id
    WHERE provider_operation.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
      AND provider_operation.pay_batch_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(provider_batch.status, ''))) NOT IN ('CANCELLED', 'CANCELED')
      AND (
        UPPER(BTRIM(COALESCE(provider_operation.status, ''))) IN ('REVIEW_REQUIRED', 'FAILED')
        OR jsonb_typeof(provider_operation.progress_json->'provider_submit_diagnostic') = 'object'
        OR jsonb_typeof(provider_operation.result_json->'provider_submit_diagnostic') = 'object'
        OR jsonb_typeof(provider_operation.error_json->'provider_submit_diagnostic') = 'object'
      )
      AND (
        UPPER(BTRIM(COALESCE(provider_operation.phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'COMPLETE')
        OR jsonb_typeof(provider_operation.progress_json->'provider_submit_diagnostic') = 'object'
        OR jsonb_typeof(provider_operation.result_json->'provider_submit_diagnostic') = 'object'
        OR jsonb_typeof(provider_operation.error_json->'provider_submit_diagnostic') = 'object'
      )
  ),
  provider_submit_review_base AS MATERIALIZED (
    SELECT
      provider_submit_review_scope.pay_batch_id,
      provider_submit_review_scope.operation_id,
      provider_submit_review_scope.operation_status,
      provider_submit_review_scope.operation_phase,
      provider_submit_review_scope.sort_at_utc,
      provider_diagnostic.diagnostic_json AS diagnostic_result,
      COALESCE(provider_diagnostic.diagnostic_json->'provider_submit_diagnostic', '{}'::jsonb) AS provider_submit_diagnostic,
      UPPER(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'provider_submission_status', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) AS provider_submission_status,
      COALESCE(NULLIF(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'review_reason_code', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,review_reason_code}', '')), ''), 'PAYMENT_PROVIDER_SUBMIT_REVIEW') AS review_reason_code,
      NULLIF(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,chunk_id}', '')), '') AS chunk_id_text,
      NULLIF(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,transfer_id}', '')), '') AS transfer_id_text,
      NULLIF(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,transfer_scope_id}', '')), '') AS transfer_scope_id_text,
      NULLIF(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,auth_request_id}', '')), '') AS auth_request_id_text,
      lower(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'manual_resolution_required', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,manual_resolution_required}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS manual_resolution_required,
      lower(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'safe_retry_available', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,safe_retry_available}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS safe_retry_available,
      lower(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS provider_acceptance_evidence_present,
      lower(BTRIM(COALESCE(provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_response_present}', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS provider_response_present
    FROM provider_submit_review_scope
    CROSS JOIN LATERAL public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := provider_submit_review_scope.pay_batch_id,
      p_operation_id := provider_submit_review_scope.operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := NULL::uuid,
      p_counts_only := false
    ) AS provider_diagnostic(diagnostic_json)
    WHERE (
        (
          UPPER(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'provider_submission_status', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN (
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
            'PROVIDER_SUBMISSION_REJECTED'
          )
          AND UPPER(BTRIM(COALESCE(provider_submit_review_scope.operation_status, ''))) IN ('REVIEW_REQUIRED', 'FAILED')
        )
        OR (
          UPPER(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'provider_submission_status', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
          AND UPPER(BTRIM(COALESCE(provider_submit_review_scope.operation_status, ''))) IN ('REVIEW_REQUIRED', 'FAILED')
        )
        OR (
          UPPER(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'provider_submission_status', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) = 'PROVIDER_SUBMISSION_ACCEPTED'
          AND UPPER(BTRIM(COALESCE(provider_submit_review_scope.operation_status, ''))) = 'REVIEW_REQUIRED'
        )
      )
      AND UPPER(BTRIM(COALESCE(provider_diagnostic.diagnostic_json->>'provider_submission_status', provider_diagnostic.diagnostic_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
  ),
  provider_submit_review_alerts AS MATERIALIZED (
    SELECT
      'PAYMENT_PROVIDER_SUBMIT_REVIEW'::text AS alert_kind,
      'critical'::text AS severity,
      91::integer AS severity_rank,
      'pay_batch'::text AS entity_kind,
      provider_submit_review_base.pay_batch_id AS entity_id,
      provider_submit_review_base.pay_batch_id AS pay_batch_id,
      'banking_pay_operation'::text AS payload_source_kind,
      provider_submit_review_base.operation_id AS payload_source_id,
      jsonb_strip_nulls(jsonb_build_object(
        'alert_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
        'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
        'pay_batch_id', provider_submit_review_base.pay_batch_id::text,
        'operation_id', provider_submit_review_base.operation_id::text,
        'chunk_id', provider_submit_review_base.chunk_id_text,
        'review_reason_code', provider_submit_review_base.review_reason_code,
        'provider_submission_status', provider_submit_review_base.provider_submission_status
      )) AS fingerprint_payload_json,
      CASE provider_submit_review_base.provider_submission_status
        WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Provider submission outcome unknown'
        WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
        WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider response unusable'
        WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider acceptance evidence missing'
        WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider submission failed'
        WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
        WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
        ELSE 'Provider submission needs review'
      END::text AS label,
      CASE provider_submit_review_base.provider_submission_status
        WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Provider submission outcome unknown'
        WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
        WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider response unusable'
        WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider acceptance evidence missing'
        WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider submission failed'
        WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
        WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
        ELSE 'Provider submission needs review'
      END::text AS title,
      CASE provider_submit_review_base.provider_submission_status
        WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Submit chunk became stale with no provider response, transfer event, rail transaction ID, or rail state.'
        WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'A provider request may have been sent, but no usable provider response was recorded.'
        WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Manual reconciliation is required before retry.'
        WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider response/status was recorded, but no usable external provider transaction/reference was stored.'
        WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected the payment submission.'
        WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission failed before the provider payment request was sent.'
        WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists and retry is unsafe until reconciliation is complete.'
        ELSE 'Provider submission requires review before retry.'
      END::text AS description,
      COALESCE(NULLIF(BTRIM(provider_submit_review_base.provider_submit_diagnostic->>'recommended_action'), ''), 'Check Revolut/bank before retry. If no payment was made, record manual no-payment confirmation.')::text AS action_guidance,
      provider_submit_review_base.sort_at_utc
    FROM provider_submit_review_base
    WHERE NOT EXISTS (
        SELECT 1 FROM blocked_funds_alerts AS stronger_blocked
        WHERE stronger_blocked.pay_batch_id = provider_submit_review_base.pay_batch_id
      )
      AND NOT EXISTS (
        SELECT 1 FROM bank_event_alerts AS stronger_bank_event
        WHERE stronger_bank_event.pay_batch_id = provider_submit_review_base.pay_batch_id
          AND stronger_bank_event.alert_kind IN ('BANK_REJECTED_PAYMENT', 'BANK_RETURNED_PAYMENT', 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT')
      )
      AND NOT EXISTS (
        SELECT 1 FROM transfer_alerts AS stronger_transfer
        WHERE stronger_transfer.pay_batch_id = provider_submit_review_base.pay_batch_id
          AND stronger_transfer.alert_kind IN ('BANK_REJECTED_PAYMENT', 'BANK_RETURNED_PAYMENT', 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT')
      )
  ),

  grouped_banking_pay_diagnostic_pay_batch_scope AS MATERIALIZED (
    SELECT DISTINCT candidate_scope.pay_batch_id
    FROM (
      SELECT scoped_specific_batch.id AS pay_batch_id
      FROM public.pay_batches AS scoped_specific_batch
      WHERE p_entity_id IS NOT NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND scoped_specific_batch.id = p_entity_id

      UNION

      SELECT blocked_candidate_batch.id AS pay_batch_id
      FROM public.pay_batches AS blocked_candidate_batch
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND UPPER(BTRIM(COALESCE(blocked_candidate_batch.status, ''))) = 'BLOCKED_FUNDS'
        AND UPPER(BTRIM(COALESCE(blocked_candidate_batch.execution_commit_state, 'NOT_SUBMITTED'))) = 'NOT_SUBMITTED'
        AND blocked_candidate_batch.cancelled_at_utc IS NULL

      UNION

      SELECT event_candidate.pay_batch_id
      FROM public.pay_bank_transfer_events AS event_candidate
      JOIN public.pay_batches AS event_candidate_batch
        ON event_candidate_batch.id = event_candidate.pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND event_candidate.pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(event_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND (
          UPPER(BTRIM(COALESCE(event_candidate.normalised_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(event_candidate.normalised_state, ''))) LIKE 'CREATE_ERROR%'
          OR UPPER(BTRIM(COALESCE(event_candidate.provider_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(event_candidate.provider_state, ''))) LIKE 'CREATE_ERROR%'
          OR UPPER(BTRIM(COALESCE(event_candidate.mapping_status, ''))) IN ('AMBIGUOUS','UNMATCHED','NO_MATCH','MULTIPLE_MATCHES')
          OR UPPER(BTRIM(COALESCE(event_candidate.correction_disposition, ''))) IN ('AMBIGUOUS','ACTION_REQUIRED','BLOCKED','FAILED')
          OR NULLIF(BTRIM(COALESCE(event_candidate.provider_failure_reason_group, '')), '') IS NOT NULL
        )

      UNION

      SELECT transfer_candidate.pay_batch_id
      FROM public.pay_bank_transfers AS transfer_candidate
      JOIN public.pay_batches AS transfer_candidate_batch
        ON transfer_candidate_batch.id = transfer_candidate.pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND transfer_candidate.pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(transfer_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND (
          UPPER(BTRIM(COALESCE(transfer_candidate.status, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(transfer_candidate.status, ''))) LIKE 'CREATE_ERROR%'
          OR UPPER(BTRIM(COALESCE(transfer_candidate.rail_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','SUBMISSION_FAILED','FAILED_BEFORE_COMMIT','RETURNED','REVERTED','UNKNOWN','TIMEOUT','TIMED_OUT','PENDING_REVIEW')
          OR UPPER(BTRIM(COALESCE(transfer_candidate.rail_state, ''))) LIKE 'CREATE_ERROR%'
          OR NULLIF(BTRIM(COALESCE(transfer_candidate.failed_reason, '')), '') IS NOT NULL
        )

      UNION

      SELECT correction_request_candidate.pay_batch_id
      FROM public.pay_payment_correction_requests AS correction_request_candidate
      JOIN public.pay_batches AS correction_request_candidate_batch
        ON correction_request_candidate_batch.id = correction_request_candidate.pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND correction_request_candidate.pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(correction_request_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND UPPER(BTRIM(COALESCE(correction_request_candidate.status, ''))) NOT IN ('APPLIED','RESOLVED','COMPLETE','COMPLETED','CANCELLED','CANCELED')

      UNION

      SELECT correction_work_candidate.pay_batch_id
      FROM public.pay_payment_correction_work_items AS correction_work_candidate
      JOIN public.pay_batches AS correction_work_candidate_batch
        ON correction_work_candidate_batch.id = correction_work_candidate.pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND correction_work_candidate.pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(correction_work_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND UPPER(BTRIM(COALESCE(correction_work_candidate.status, ''))) IN ('PENDING','PROCESSING','BLOCKED','FAILED','FAILED_RETRYABLE','FAILED_FINAL','APPLIED_WITH_BLOCKERS')

      UNION

      SELECT operation_candidate.pay_batch_id
      FROM public.banking_pay_operations AS operation_candidate
      JOIN public.pay_batches AS operation_candidate_batch
        ON operation_candidate_batch.id = operation_candidate.pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND operation_candidate.pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(operation_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND (
          UPPER(BTRIM(COALESCE(operation_candidate.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
          OR UPPER(BTRIM(COALESCE(operation_candidate.status, ''))) IN ('REVIEW_REQUIRED','FAILED')
          OR jsonb_typeof(operation_candidate.progress_json->'provider_submit_diagnostic') = 'object'
          OR jsonb_typeof(operation_candidate.result_json->'provider_submit_diagnostic') = 'object'
          OR jsonb_typeof(operation_candidate.error_json->'provider_submit_diagnostic') = 'object'
        )

      UNION

      SELECT remittance_candidate.context_id AS pay_batch_id
      FROM public.mail_outbox AS remittance_candidate
      JOIN public.pay_batches AS remittance_candidate_batch
        ON remittance_candidate_batch.id = remittance_candidate.context_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND remittance_candidate.context_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(remittance_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND UPPER(BTRIM(COALESCE(remittance_candidate.type, ''))) = 'REMITTANCE'
        AND LOWER(BTRIM(COALESCE(remittance_candidate.context_kind, ''))) = 'pay_batches'
        AND UPPER(BTRIM(COALESCE(remittance_candidate.status::text, ''))) = 'FAILED'

      UNION

      SELECT carry_forward_candidate.source_pay_batch_id AS pay_batch_id
      FROM public.pay_manual_adjustment_carry_forwards AS carry_forward_candidate
      JOIN public.pay_batches AS carry_forward_candidate_batch
        ON carry_forward_candidate_batch.id = carry_forward_candidate.source_pay_batch_id
      WHERE p_entity_id IS NULL
        AND (v_entity_kind IS NULL OR v_entity_kind IN ('pay_batch', 'pay_batches'))
        AND carry_forward_candidate.source_pay_batch_id IS NOT NULL
        AND UPPER(BTRIM(COALESCE(carry_forward_candidate_batch.status, ''))) NOT IN ('CANCELLED','CANCELED')
        AND UPPER(BTRIM(COALESCE(carry_forward_candidate.status, ''))) = 'PENDING_CARRY_FORWARD'
    ) AS candidate_scope
    WHERE candidate_scope.pay_batch_id IS NOT NULL
  ),
  grouped_banking_pay_diagnostic_scope AS MATERIALIZED (
    SELECT
      scoped_pay_batches.id AS pay_batch_id,
      scoped_pay_batches.status AS batch_status,
      scoped_pay_batches.rail_provider_snapshot,
      scoped_pay_batches.rail_env_snapshot,
      GREATEST(
        COALESCE(scoped_pay_batches.last_status_checked_at_utc, '-infinity'::timestamptz),
        COALESCE(scoped_pay_batches.last_funds_check_at_utc, '-infinity'::timestamptz),
        COALESCE(scoped_pay_batches.execution_committed_at_utc, '-infinity'::timestamptz),
        COALESCE(scoped_pay_batches.created_at_utc, '-infinity'::timestamptz)
      ) AS sort_at_utc,
      COALESCE(
        public.pay_payment_cancelability_diagnostic(
          scoped_pay_batches.id,
          jsonb_build_object('scope_type', 'BATCH'),
          p_actor_user_id
        ),
        '{}'::jsonb
      ) AS diagnostic_json
    FROM grouped_banking_pay_diagnostic_pay_batch_scope AS diagnostic_scope
    JOIN public.pay_batches AS scoped_pay_batches
      ON scoped_pay_batches.id = diagnostic_scope.pay_batch_id
  ),
  grouped_banking_pay_correction_scope AS MATERIALIZED (
    SELECT
      public.pay_payment_correction_requests.pay_batch_id,
      public.pay_payment_correction_requests.id AS correction_request_id,
      UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.correction_kind, ''))) AS correction_kind,
      UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) AS correction_status,
      public.pay_payment_correction_requests.updated_at_utc,
      public.pay_payment_correction_requests.created_at_utc,
      COUNT(public.pay_payment_correction_work_items.id)::integer AS work_total,
      COUNT(public.pay_payment_correction_work_items.id) FILTER (
        WHERE UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED')
      )::integer AS work_completed
    FROM public.pay_payment_correction_requests
    LEFT JOIN public.pay_payment_correction_work_items
      ON public.pay_payment_correction_work_items.correction_request_id = public.pay_payment_correction_requests.id
    WHERE EXISTS (
      SELECT 1
      FROM grouped_banking_pay_diagnostic_scope
      WHERE grouped_banking_pay_diagnostic_scope.pay_batch_id = public.pay_payment_correction_requests.pay_batch_id
    )
      AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) NOT IN ('APPLIED','COMPLETE','COMPLETED','CANCELLED','CANCELED')
    GROUP BY
      public.pay_payment_correction_requests.pay_batch_id,
      public.pay_payment_correction_requests.id,
      public.pay_payment_correction_requests.correction_kind,
      public.pay_payment_correction_requests.status,
      public.pay_payment_correction_requests.updated_at_utc,
      public.pay_payment_correction_requests.created_at_utc
  ),
  grouped_banking_pay_carry_forward_scope AS MATERIALIZED (
    SELECT
      public.pay_manual_adjustment_carry_forwards.source_pay_batch_id AS pay_batch_id,
      COUNT(*)::integer AS carry_forward_count,
      MAX(grouped_banking_pay_diagnostic_scope.sort_at_utc) AS sort_at_utc
    FROM public.pay_manual_adjustment_carry_forwards
    JOIN grouped_banking_pay_diagnostic_scope
      ON grouped_banking_pay_diagnostic_scope.pay_batch_id = public.pay_manual_adjustment_carry_forwards.source_pay_batch_id
    WHERE public.pay_manual_adjustment_carry_forwards.source_pay_batch_id IS NOT NULL
      AND UPPER(BTRIM(COALESCE(public.pay_manual_adjustment_carry_forwards.status, ''))) = 'PENDING_CARRY_FORWARD'
    GROUP BY public.pay_manual_adjustment_carry_forwards.source_pay_batch_id
  ),
  grouped_banking_pay_alert_seeds AS MATERIALIZED (
    SELECT
      'PROVIDER_OUTAGE_RETRY_LATER'::text AS alert_kind,
      92::integer AS severity_rank,
      'ACTION_REQUIRED'::text AS severity,
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text AS payload_source_kind,
      NULL::uuid AS payload_source_id,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'payment_lifecycle_state'), ''), '') = 'PROVIDER_OUTAGE_RETRY_LATER'
       OR COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'recommended_action'), ''), '') = 'RETRY_PROVIDER_LATER'
       OR LOWER(BTRIM(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'requires_retry_later', 'false'))) IN ('true','t','1','yes','y','on')

    UNION ALL
    SELECT
      'PROVIDER_OUTAGE_RETRY_LATER'::text AS alert_kind,
      92::integer AS severity_rank,
      'PROGRESS'::text AS severity,
      retry_operation.pay_batch_id,
      'banking_pay_operation'::text AS payload_source_kind,
      retry_operation.id AS payload_source_id,
      COALESCE(retry_operation.updated_at_utc, retry_operation.created_at_utc, now()) AS sort_at_utc
    FROM public.banking_pay_operations AS retry_operation
    WHERE UPPER(BTRIM(COALESCE(retry_operation.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND UPPER(BTRIM(COALESCE(retry_operation.status, ''))) NOT IN ('COMPLETE','COMPLETED','SUCCEEDED','SUCCESS','FAILED','FAILED_FINAL','CANCELLED','CANCELED')
      AND EXISTS (
        SELECT 1
        FROM grouped_banking_pay_diagnostic_scope
        WHERE grouped_banking_pay_diagnostic_scope.pay_batch_id = retry_operation.pay_batch_id
      )

    UNION ALL
    SELECT
      'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
      94,
      'ACTION_REQUIRED',
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'payment_lifecycle_state'), ''), '') = 'PROVIDER_OUTCOME_UNKNOWN'
       OR COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'recommended_action'), ''), '') = 'CHECK_PROVIDER_STATUS'
       OR LOWER(BTRIM(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'requires_bank_check', 'false'))) IN ('true','t','1','yes','y','on')

    UNION ALL
    SELECT
      'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
      93,
      'ACTION_REQUIRED',
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'payment_lifecycle_state'), ''), '') IN ('PROVIDER_CANCELLED_NO_MONEY','PROVIDER_FAILED_NO_MONEY')
      AND LOWER(BTRIM(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','t','1','yes','y','on')
      AND NOT EXISTS (
        SELECT 1
        FROM grouped_banking_pay_correction_scope
        WHERE grouped_banking_pay_correction_scope.pay_batch_id = grouped_banking_pay_diagnostic_scope.pay_batch_id
          AND grouped_banking_pay_correction_scope.correction_kind IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
      )

    UNION ALL
    SELECT
      'PAID_SETTLED_RECOVERY_REQUIRED',
      94,
      'ACTION_REQUIRED',
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE COALESCE(NULLIF(BTRIM(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'recommended_action'), ''), '') = 'AMEND_AND_RECOVER_OVERPAYMENT'
       OR LOWER(BTRIM(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','t','1','yes','y','on')

    UNION ALL
    SELECT
      'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
      94,
      'ACTION_REQUIRED',
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'blockers', '[]'::jsonb)::text LIKE '%CANCELLATION_RACED_WITH_PROVIDER_SUBMIT%'
       OR COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'blockers', '[]'::jsonb)::text LIKE '%PROVIDER_SUBMISSION_ALREADY_CLAIMED%'
       OR COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'blockers', '[]'::jsonb)::text LIKE '%PROVIDER_SUBMISSION_IN_PROGRESS%'

    UNION ALL
    SELECT
      'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
      91,
      'ACTION_REQUIRED',
      grouped_banking_pay_diagnostic_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_diagnostic_scope.sort_at_utc
    FROM grouped_banking_pay_diagnostic_scope
    WHERE CASE
      WHEN jsonb_typeof(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'carry_forward_blockers', '[]'::jsonb)) = 'array'
        THEN jsonb_array_length(COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'carry_forward_blockers', '[]'::jsonb))
      ELSE 0
    END > 0
       OR COALESCE(grouped_banking_pay_diagnostic_scope.diagnostic_json->'blockers', '[]'::jsonb)::text LIKE '%SOURCE_LESS_MANUAL_ADJUSTMENT_AMBIGUOUS%'

    UNION ALL
    SELECT
      'AUTO_UNWIND_PROGRESS',
      85,
      'PROGRESS',
      grouped_banking_pay_correction_scope.pay_batch_id,
      'pay_payment_correction_request',
      grouped_banking_pay_correction_scope.correction_request_id,
      COALESCE(grouped_banking_pay_correction_scope.updated_at_utc, grouped_banking_pay_correction_scope.created_at_utc)
    FROM grouped_banking_pay_correction_scope
    WHERE grouped_banking_pay_correction_scope.correction_kind IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')

    UNION ALL
    SELECT
      'WHOLE_BATCH_CANCELLATION_PROGRESS',
      85,
      'PROGRESS',
      grouped_banking_pay_correction_scope.pay_batch_id,
      'pay_payment_correction_request',
      grouped_banking_pay_correction_scope.correction_request_id,
      COALESCE(grouped_banking_pay_correction_scope.updated_at_utc, grouped_banking_pay_correction_scope.created_at_utc)
    FROM grouped_banking_pay_correction_scope
    WHERE grouped_banking_pay_correction_scope.correction_kind = 'PRE_BANK_CANCEL'

    UNION ALL
    SELECT
      'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
      70,
      'INFO',
      grouped_banking_pay_carry_forward_scope.pay_batch_id,
      NULL::text,
      NULL::uuid,
      grouped_banking_pay_carry_forward_scope.sort_at_utc
    FROM grouped_banking_pay_carry_forward_scope
    WHERE COALESCE(grouped_banking_pay_carry_forward_scope.carry_forward_count, 0) > 0
  ),
  grouped_banking_pay_alerts AS MATERIALIZED (
    SELECT
      grouped_banking_pay_alert_seeds.alert_kind,
      grouped_banking_pay_alert_seeds.severity,
      grouped_banking_pay_alert_seeds.severity_rank,
      'pay_batch'::text AS entity_kind,
      grouped_banking_pay_alert_seeds.pay_batch_id AS entity_id,
      grouped_banking_pay_alert_seeds.pay_batch_id,
      grouped_banking_pay_alert_seeds.payload_source_kind,
      grouped_banking_pay_alert_seeds.payload_source_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'payload_is_grouped', true,
          'alert_kind', grouped_banking_pay_alert_seeds.alert_kind,
          'issue_kind', grouped_banking_pay_alert_seeds.alert_kind,
          'legacy_alert_kind', grouped_banking_pay_alert_seeds.alert_kind,
          'pay_batch_id', grouped_banking_pay_alert_seeds.pay_batch_id::text,
          'link_target', 'banking_pay_batch',
          'link_tab', CASE
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'overview'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'overview'
            ELSE 'current_payment_status'
          END,
          'alert_severity', grouped_banking_pay_alert_seeds.severity,
          'severity', grouped_banking_pay_alert_seeds.severity
        )
        || jsonb_build_object(
          'stable_issue_key', CONCAT_WS(
            ':',
            grouped_banking_pay_alert_seeds.pay_batch_id::text,
            grouped_banking_pay_alert_seeds.alert_kind,
            CASE
              WHEN grouped_banking_pay_alert_seeds.alert_kind IN (
                'PROVIDER_OUTAGE_RETRY_LATER',
                'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
                'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
                'PAID_SETTLED_RECOVERY_REQUIRED',
                'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
                'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
                'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              ) THEN 'GROUPED'
              ELSE COALESCE(NULLIF(BTRIM(grouped_banking_pay_alert_seeds.payload_source_kind), ''), 'BATCH')
            END,
            CASE
              WHEN grouped_banking_pay_alert_seeds.alert_kind IN (
                'PROVIDER_OUTAGE_RETRY_LATER',
                'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
                'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
                'PAID_SETTLED_RECOVERY_REQUIRED',
                'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
                'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
                'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              ) THEN 'ACTIVE'
              ELSE COALESCE(grouped_banking_pay_alert_seeds.payload_source_id::text, 'NO_SOURCE')
            END
          ),
          'dedupe_key', CONCAT_WS(
            ':',
            grouped_banking_pay_alert_seeds.pay_batch_id::text,
            grouped_banking_pay_alert_seeds.alert_kind,
            CASE
              WHEN grouped_banking_pay_alert_seeds.alert_kind IN (
                'PROVIDER_OUTAGE_RETRY_LATER',
                'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
                'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
                'PAID_SETTLED_RECOVERY_REQUIRED',
                'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
                'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
                'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              ) THEN 'GROUPED'
              ELSE COALESCE(grouped_banking_pay_alert_seeds.payload_source_id::text, 'NO_SOURCE')
            END
          ),
          'payload_source_kind', NULLIF(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.payload_source_kind, '')), ''),
          'payload_source_id', CASE WHEN grouped_banking_pay_alert_seeds.payload_source_id IS NULL THEN NULL::text ELSE grouped_banking_pay_alert_seeds.payload_source_id::text END
        )
        || jsonb_build_object(
          'user_label', CASE
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
              THEN 'Retrying unsent payments'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              THEN 'Bank unavailable — unsent payments can be retried'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
              THEN 'Provider outcome unknown — check provider'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
              THEN 'Failed payments — Rewind financials available'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
              THEN 'Rewinding failed payments'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
              THEN 'Cancelling scheduled batch'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              THEN 'Manual adjustments carried forward'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
              THEN 'Manual adjustment blockers — review required'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
              THEN 'Paid — recovery required'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
              THEN 'Cancellation conflict — provider submission already started'
            ELSE INITCAP(REPLACE(LOWER(grouped_banking_pay_alert_seeds.alert_kind), '_', ' '))
          END,
          'user_description', CASE
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
              THEN 'Retrying unsent payments is in progress. You can continue using CloudTMS while this runs.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              THEN 'The bank/provider was unavailable before the payment request was sent. Retry unsent payments from Banking Pay Overview.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
              THEN 'A provider request may have been sent, but the outcome is not confirmed. Open Current Payment Status and check the provider outcome.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
              THEN 'The provider/bank outcome indicates no money moved. Open Current Payment Status and rewind financials where safe.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
              THEN 'Automatic no-money unwind is running and this alert updates grouped progress.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
              THEN 'Scheduled local cancellation is running in chunks and this alert updates grouped progress.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              THEN 'Safe source-less manual adjustments were carried forward and will be included in the next pay run.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
              THEN 'One or more manual adjustments cannot be safely carried forward automatically.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
              THEN 'Money appears to have moved. Amend the timesheet and recover the overpayment in the next pay run rather than unwinding the payment.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
              THEN 'Cancellation could not proceed because provider submission had already started.'
            ELSE 'Open Banking Pay for details.'
          END,
          'required_user_action', CASE
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
              THEN 'Monitor retry progress from Banking Pay Overview.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
              THEN 'Retry unsent payments from Banking Pay Overview.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
              THEN 'Open Current Payment Status and check the provider outcome.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
              THEN 'Open Current Payment Status and rewind financials where no money moved.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
              THEN 'Monitor rewind progress.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
              THEN 'Monitor cancellation progress in Banking Pay Overview.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
              THEN 'Review carried-forward manual adjustments in the next pay run.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
              THEN 'Open Current Payment Status and review ambiguous manual adjustment blockers.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
              THEN 'Open Current Payment Status and recover overpayment in next pay run.'
            WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
              THEN 'Open Current Payment Status and check provider submission before continuing.'
            ELSE 'Open Banking Pay.'
          END
        )
      ) AS fingerprint_payload_json,
      CASE
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
          THEN 'Retrying unsent payments'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          THEN 'Bank unavailable — unsent payments can be retried'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          THEN 'Provider outcome unknown — check provider'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
          THEN 'Failed payments — Rewind financials available'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
          THEN 'Rewinding failed payments'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
          THEN 'Cancelling scheduled batch'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
          THEN 'Manual adjustments carried forward'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
          THEN 'Manual adjustment blockers — review required'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
          THEN 'Paid — recovery required'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
          THEN 'Cancellation conflict — provider submission already started'
        ELSE INITCAP(REPLACE(LOWER(grouped_banking_pay_alert_seeds.alert_kind), '_', ' '))
      END::text AS label,
      CASE
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
          THEN 'Retrying unsent payments'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          THEN 'Bank unavailable — unsent payments can be retried'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          THEN 'Provider outcome unknown — check provider'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
          THEN 'Failed payments — Rewind financials available'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
          THEN 'Rewinding failed payments'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
          THEN 'Cancelling scheduled batch'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
          THEN 'Manual adjustments carried forward'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
          THEN 'Manual adjustment blockers — review required'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
          THEN 'Paid — recovery required'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
          THEN 'Cancellation conflict — provider submission already started'
        ELSE INITCAP(REPLACE(LOWER(grouped_banking_pay_alert_seeds.alert_kind), '_', ' '))
      END::text AS title,
      CASE
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
          THEN 'Retrying unsent payments is in progress. You can continue using CloudTMS while this runs.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          THEN 'The bank/provider was unavailable before the payment request was sent. Retry unsent payments from Banking Pay Overview.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          THEN 'A provider request may have been sent, but the outcome is not confirmed. Open Current Payment Status and check the provider outcome.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
          THEN 'The provider/bank outcome indicates no money moved. Open Current Payment Status and rewind financials where safe.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
          THEN 'Automatic no-money unwind is running and this alert updates grouped progress.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
          THEN 'Scheduled local cancellation is running in chunks and this alert updates grouped progress.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
          THEN 'Safe source-less manual adjustments were carried forward and will be included in the next pay run.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
          THEN 'One or more manual adjustments cannot be safely carried forward automatically.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
          THEN 'Money appears to have moved. Amend the timesheet and recover the overpayment in the next pay run rather than unwinding the payment.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
          THEN 'Cancellation could not proceed because provider submission had already started.'
        ELSE 'Open Banking Pay for details.'
      END::text AS description,
      CASE
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          AND UPPER(BTRIM(COALESCE(grouped_banking_pay_alert_seeds.severity, ''))) = 'PROGRESS'
          THEN 'Monitor retry progress from Banking Pay Overview.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER'
          THEN 'Retry unsent payments from Banking Pay Overview.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          THEN 'Open Current Payment Status and check the provider outcome.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
          THEN 'Open Current Payment Status and rewind financials where no money moved.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'AUTO_UNWIND_PROGRESS'
          THEN 'Monitor rewind progress.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS'
          THEN 'Monitor cancellation progress in Banking Pay Overview.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD'
          THEN 'Review carried-forward manual adjustments in the next pay run.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
          THEN 'Open Current Payment Status and review ambiguous manual adjustment blockers.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'PAID_SETTLED_RECOVERY_REQUIRED'
          THEN 'Open Current Payment Status and recover overpayment in next pay run.'
        WHEN grouped_banking_pay_alert_seeds.alert_kind = 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
          THEN 'Open Current Payment Status and check provider submission before continuing.'
        ELSE 'Open Banking Pay.'
      END::text AS action_guidance,
      grouped_banking_pay_alert_seeds.sort_at_utc
    FROM grouped_banking_pay_alert_seeds
  ),
  raw_current_alerts AS MATERIALIZED (
    SELECT * FROM blocked_funds_alerts
    UNION ALL
    SELECT bank_event_alerts.*
    FROM bank_event_alerts
    WHERE NOT EXISTS (
      SELECT 1
      FROM grouped_banking_pay_alerts AS grouped_replacement_alerts
      WHERE grouped_replacement_alerts.pay_batch_id = bank_event_alerts.pay_batch_id
        AND (
          (
            bank_event_alerts.alert_kind IN ('BANK_REJECTED_PAYMENT')
            AND grouped_replacement_alerts.alert_kind IN (
              'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
              'AUTO_UNWIND_PROGRESS'
            )
          )
          OR (
            bank_event_alerts.alert_kind IN ('BANK_RETURNED_PAYMENT')
            AND grouped_replacement_alerts.alert_kind IN (
              'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
              'AUTO_UNWIND_PROGRESS',
              'PAID_SETTLED_RECOVERY_REQUIRED'
            )
          )
          OR (
            bank_event_alerts.alert_kind IN ('RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT')
            AND grouped_replacement_alerts.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          )
          OR (
            bank_event_alerts.alert_kind IN ('AMBIGUOUS_PAYMENT_REVIEW_REQUIRED')
            AND grouped_replacement_alerts.alert_kind IN (
              'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
              'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
            )
          )
          OR (
            bank_event_alerts.alert_kind IN ('PAYMENT_CORRECTION_FAILED','PAYMENT_CORRECTION_BLOCKED')
            AND grouped_replacement_alerts.alert_kind IN (
              'AUTO_UNWIND_PROGRESS',
              'WHOLE_BATCH_CANCELLATION_PROGRESS',
              'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
              'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
              'PAID_SETTLED_RECOVERY_REQUIRED'
            )
          )
        )
    )
    UNION ALL
    SELECT transfer_alerts.*
    FROM transfer_alerts
    WHERE NOT EXISTS (
      SELECT 1
      FROM grouped_banking_pay_alerts AS grouped_replacement_alerts
      WHERE grouped_replacement_alerts.pay_batch_id = transfer_alerts.pay_batch_id
        AND (
          (
            transfer_alerts.alert_kind IN ('BANK_REJECTED_PAYMENT')
            AND grouped_replacement_alerts.alert_kind IN (
              'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
              'AUTO_UNWIND_PROGRESS'
            )
          )
          OR (
            transfer_alerts.alert_kind IN ('BANK_RETURNED_PAYMENT')
            AND grouped_replacement_alerts.alert_kind IN (
              'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
              'AUTO_UNWIND_PROGRESS',
              'PAID_SETTLED_RECOVERY_REQUIRED'
            )
          )
          OR (
            transfer_alerts.alert_kind IN ('RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT')
            AND grouped_replacement_alerts.alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
          )
        )
    )
    UNION ALL
    SELECT correction_request_alerts.*
    FROM correction_request_alerts
    WHERE NOT EXISTS (
      SELECT 1
      FROM grouped_banking_pay_alerts AS grouped_replacement_alerts
      WHERE grouped_replacement_alerts.pay_batch_id = correction_request_alerts.pay_batch_id
        AND grouped_replacement_alerts.payload_source_kind = 'pay_payment_correction_request'
        AND grouped_replacement_alerts.payload_source_id = correction_request_alerts.payload_source_id
        AND grouped_replacement_alerts.alert_kind IN (
          'AUTO_UNWIND_PROGRESS',
          'WHOLE_BATCH_CANCELLATION_PROGRESS'
        )
    )
    UNION ALL
    SELECT correction_work_alerts.*
    FROM correction_work_alerts
    WHERE NOT EXISTS (
      SELECT 1
      FROM grouped_banking_pay_alerts AS grouped_replacement_alerts
      JOIN public.pay_payment_correction_work_items AS correction_work_group_lookup
        ON correction_work_group_lookup.id = correction_work_alerts.payload_source_id
       AND correction_work_group_lookup.correction_request_id = grouped_replacement_alerts.payload_source_id
      WHERE grouped_replacement_alerts.pay_batch_id = correction_work_alerts.pay_batch_id
        AND grouped_replacement_alerts.payload_source_kind = 'pay_payment_correction_request'
        AND grouped_replacement_alerts.alert_kind IN (
          'AUTO_UNWIND_PROGRESS',
          'WHOLE_BATCH_CANCELLATION_PROGRESS'
        )
    )
    UNION ALL
    SELECT * FROM remittance_alerts
    UNION ALL
    SELECT provider_submit_review_alerts.*
    FROM provider_submit_review_alerts
    WHERE NOT EXISTS (
      SELECT 1
      FROM grouped_banking_pay_alerts AS grouped_replacement_alerts
      WHERE grouped_replacement_alerts.pay_batch_id = provider_submit_review_alerts.pay_batch_id
        AND grouped_replacement_alerts.alert_kind IN (
          'PROVIDER_OUTAGE_RETRY_LATER',
          'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
          'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
        )
    )
    UNION ALL
    SELECT * FROM grouped_banking_pay_alerts
  ),
  normalised_current_alerts AS MATERIALIZED (
    SELECT
      mapped_alerts.mapped_alert_kind AS alert_kind,
      raw_current_alerts.severity,
      raw_current_alerts.severity_rank,
      raw_current_alerts.entity_kind,
      raw_current_alerts.entity_id,
      raw_current_alerts.pay_batch_id,
      raw_current_alerts.payload_source_kind,
      raw_current_alerts.payload_source_id,
      COALESCE(raw_current_alerts.fingerprint_payload_json, '{}'::jsonb) || jsonb_build_object(
        'legacy_alert_kind', raw_current_alerts.alert_kind,
        'alert_kind', mapped_alerts.mapped_alert_kind
      ) AS fingerprint_payload_json,
      CASE mapped_alerts.mapped_alert_kind
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Provider outcome unknown — check provider'
        WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Failed payments — Rewind financials available'
        WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Rewinding failed payments'
        WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Cancelling scheduled batch'
        WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Manual adjustments carried forward'
        WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Manual adjustment blockers — review required'
        WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Paid — recovery required'
        WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation conflict — provider submission already started'
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched bank webhook — review required'
        ELSE raw_current_alerts.label
      END AS label,
      CASE mapped_alerts.mapped_alert_kind
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — unsent payments can be retried'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Provider outcome unknown — check provider'
        WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Failed payments — Rewind financials available'
        WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Rewinding failed payments'
        WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Cancelling scheduled batch'
        WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Manual adjustments carried forward'
        WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Manual adjustment blockers — review required'
        WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Paid — recovery required'
        WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation conflict — provider submission already started'
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched bank webhook — review required'
        ELSE raw_current_alerts.title
      END AS title,
      CASE mapped_alerts.mapped_alert_kind
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'The bank/provider was unavailable before the payment request was sent. Retry unsent payments from Banking Pay Overview.'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'A provider request may have been sent, but the outcome is not confirmed. Open Current Payment Status and check the provider outcome.'
        WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'The provider/bank outcome indicates no money moved. Open Current Payment Status and rewind financials where safe.'
        WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Automatic no-money unwind is running and this alert updates grouped progress.'
        WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Scheduled local cancellation is running in chunks and this alert updates grouped progress.'
        WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Safe source-less manual adjustments were carried forward and will be included in the next pay run.'
        WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'One or more manual adjustments cannot be safely carried forward automatically.'
        WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Money appears to have moved. Amend the timesheet and recover the overpayment in the next pay run rather than unwinding the payment.'
        WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation could not proceed because provider submission had already started.'
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'A verified provider webhook was received but could not be matched safely to a payment.'
        ELSE raw_current_alerts.description
      END AS description,
      CASE mapped_alerts.mapped_alert_kind
        WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Open Banking Pay Overview and retry unsent payments.'
        WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Open Current Payment Status and check the provider outcome.'
        WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Open Current Payment Status and rewind financials where no money moved.'
        WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Monitor rewind progress.'
        WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Monitor cancellation progress in Banking Pay Overview.'
        WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Review carried-forward manual adjustments in the next pay run.'
        WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Open Current Payment Status and review ambiguous manual adjustment blockers.'
        WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Open Current Payment Status and recover overpayment in next pay run.'
        WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Open Current Payment Status and check provider submission before continuing.'
        WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Open Current Payment Status and review the unmatched provider webhook.'
        ELSE replace(COALESCE(raw_current_alerts.action_guidance, 'Open Banking Pay.'), 'Payment Issues', 'Current Payment Status')
      END AS action_guidance,
      raw_current_alerts.sort_at_utc
    FROM raw_current_alerts
    CROSS JOIN LATERAL (
      SELECT CASE raw_current_alerts.alert_kind
        WHEN 'BLOCKED_FUNDS' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
        WHEN 'BANK_REJECTED_PAYMENT' THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
        WHEN 'BANK_RETURNED_PAYMENT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN 'PAYMENT_PROVIDER_SUBMIT_REVIEW' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
        WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
        WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
        WHEN 'PAYMENT_CORRECTION_AWAITING_APPROVAL' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
        ELSE raw_current_alerts.alert_kind
      END AS mapped_alert_kind
    ) AS mapped_alerts
  ),
  current_alert_identities AS MATERIALIZED (
    SELECT
      normalised_current_alerts.alert_kind,
      normalised_current_alerts.severity,
      normalised_current_alerts.severity_rank,
      normalised_current_alerts.entity_kind,
      normalised_current_alerts.entity_id,
      normalised_current_alerts.pay_batch_id,
      normalised_current_alerts.payload_source_kind,
      normalised_current_alerts.payload_source_id,
      normalised_current_alerts.fingerprint_payload_json,
      public.banking_alert_fingerprint(
        normalised_current_alerts.alert_kind,
        normalised_current_alerts.entity_kind,
        normalised_current_alerts.entity_id,
        normalised_current_alerts.fingerprint_payload_json
      ) AS alert_fingerprint,
      normalised_current_alerts.label,
      normalised_current_alerts.title,
      normalised_current_alerts.description,
      normalised_current_alerts.action_guidance,
      normalised_current_alerts.sort_at_utc
    FROM normalised_current_alerts
    WHERE normalised_current_alerts.alert_kind IS NOT NULL
      AND normalised_current_alerts.entity_id IS NOT NULL
  ),
  filtered_current_alert_identities AS MATERIALIZED (
    SELECT current_alert_identities.*
    FROM current_alert_identities
    WHERE (v_entity_kind IS NULL OR current_alert_identities.entity_kind = v_entity_kind)
      AND (p_entity_id IS NULL OR current_alert_identities.entity_id = p_entity_id)
      AND public._banking_alert_user_filter_allows(
        p_actor_user_id,
        jsonb_strip_nulls(
          COALESCE(current_alert_identities.fingerprint_payload_json, '{}'::jsonb)
          || jsonb_build_object(
            'alert_kind', current_alert_identities.alert_kind,
            'alert_severity', current_alert_identities.severity,
            'severity', current_alert_identities.severity,
            'entity_kind', current_alert_identities.entity_kind,
            'entity_id', current_alert_identities.entity_id::text,
            'pay_batch_id', current_alert_identities.pay_batch_id::text,
            'alert_fingerprint', current_alert_identities.alert_fingerprint,
            'user_label', current_alert_identities.label,
            'user_description', current_alert_identities.description,
            'required_user_action', current_alert_identities.action_guidance
          )
        )
      )
  ),
  deduped_alerts AS MATERIALIZED (
    SELECT DISTINCT ON (filtered_current_alert_identities.alert_fingerprint)
      filtered_current_alert_identities.alert_kind,
      filtered_current_alert_identities.severity,
      filtered_current_alert_identities.severity_rank,
      filtered_current_alert_identities.entity_kind,
      filtered_current_alert_identities.entity_id,
      filtered_current_alert_identities.pay_batch_id,
      filtered_current_alert_identities.payload_source_kind,
      filtered_current_alert_identities.payload_source_id,
      filtered_current_alert_identities.fingerprint_payload_json,
      filtered_current_alert_identities.alert_fingerprint,
      filtered_current_alert_identities.label,
      filtered_current_alert_identities.title,
      filtered_current_alert_identities.description,
      filtered_current_alert_identities.action_guidance,
      filtered_current_alert_identities.sort_at_utc
    FROM filtered_current_alert_identities
    WHERE filtered_current_alert_identities.alert_fingerprint IS NOT NULL
    ORDER BY filtered_current_alert_identities.alert_fingerprint ASC,
             filtered_current_alert_identities.severity_rank DESC,
             filtered_current_alert_identities.sort_at_utc DESC NULLS LAST
  ),
  alert_rows AS MATERIALIZED (
    SELECT
      deduped_alerts.alert_kind,
      deduped_alerts.severity,
      deduped_alerts.severity_rank,
      deduped_alerts.entity_kind,
      deduped_alerts.entity_id,
      deduped_alerts.pay_batch_id,
      deduped_alerts.payload_source_kind,
      deduped_alerts.payload_source_id,
      deduped_alerts.fingerprint_payload_json,
      deduped_alerts.alert_fingerprint,
      deduped_alerts.label,
      deduped_alerts.title,
      deduped_alerts.description,
      deduped_alerts.action_guidance,
      deduped_alerts.sort_at_utc,
      alert_acknowledgements.id IS NOT NULL AS acknowledged_for_current_user,
      alert_acknowledgements.acknowledged_at_utc
    FROM deduped_alerts
    LEFT JOIN public.banking_alert_acknowledgements AS alert_acknowledgements
      ON alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
     AND UPPER(BTRIM(COALESCE(alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
     AND (
       alert_acknowledgements.alert_fingerprint = deduped_alerts.alert_fingerprint
       OR (
         UPPER(BTRIM(COALESCE(alert_acknowledgements.alert_kind, ''))) = UPPER(BTRIM(COALESCE(deduped_alerts.alert_kind, '')))
         AND LOWER(BTRIM(COALESCE(alert_acknowledgements.entity_kind, ''))) = LOWER(BTRIM(COALESCE(deduped_alerts.entity_kind, '')))
         AND alert_acknowledgements.entity_id = deduped_alerts.entity_id
         AND alert_acknowledgements.acknowledged_at_utc >= COALESCE(deduped_alerts.sort_at_utc, '-infinity'::timestamptz)
       )
     )
    WHERE COALESCE(p_include_acknowledged, false) = true
       OR alert_acknowledgements.id IS NULL
  ),
  counted_alerts AS MATERIALIZED (
    SELECT
      alert_rows.*,
      (COUNT(*) OVER ())::integer AS filtered_count,
      (COUNT(*) FILTER (WHERE alert_rows.acknowledged_for_current_user = false) OVER ())::integer AS unacknowledged_count
    FROM alert_rows
  ),
  limited_alerts AS MATERIALIZED (
    SELECT counted_alerts.*
    FROM counted_alerts
    ORDER BY counted_alerts.severity_rank DESC,
             counted_alerts.sort_at_utc DESC NULLS LAST,
             counted_alerts.alert_fingerprint ASC
    LIMIT v_limit
  ),
  detailed_alerts AS MATERIALIZED (
    SELECT
      limited_alerts.alert_kind,
      limited_alerts.severity,
      limited_alerts.severity_rank,
      limited_alerts.entity_kind,
      limited_alerts.entity_id,
      limited_alerts.pay_batch_id,
      limited_alerts.fingerprint_payload_json,
      limited_alerts.alert_fingerprint,
      limited_alerts.label,
      limited_alerts.title,
      limited_alerts.description,
      limited_alerts.action_guidance,
      limited_alerts.sort_at_utc,
      limited_alerts.acknowledged_for_current_user,
      limited_alerts.acknowledged_at_utc,
      limited_alerts.filtered_count,
      limited_alerts.unacknowledged_count,
      jsonb_strip_nulls(
        COALESCE(limited_alerts.fingerprint_payload_json, '{}'::jsonb)
        || jsonb_build_object(
          'alert_kind', limited_alerts.alert_kind,
          'issue_kind', limited_alerts.alert_kind,
          'pay_batch_id', limited_alerts.pay_batch_id::text,
          'entity_kind', limited_alerts.entity_kind,
          'entity_id', limited_alerts.entity_id::text,
          'alert_fingerprint', limited_alerts.alert_fingerprint,
          'user_label', limited_alerts.label,
          'user_description', limited_alerts.description,
          'required_user_action', limited_alerts.action_guidance,
          'link_target', 'banking_pay_batch',
          'link_tab', CASE
            WHEN limited_alerts.alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'overview'
            WHEN limited_alerts.alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'overview'
            ELSE 'current_payment_status'
          END
        )
      ) AS payload_json
    FROM limited_alerts
  ),
  signal_aggregate AS MATERIALIZED (
    SELECT
      (COUNT(*) FILTER (WHERE alert_rows.acknowledged_for_current_user = false))::integer AS unacknowledged_count,
      (ARRAY_AGG(alert_rows.severity ORDER BY alert_rows.severity_rank DESC, alert_rows.sort_at_utc DESC NULLS LAST, alert_rows.alert_fingerprint ASC) FILTER (WHERE alert_rows.acknowledged_for_current_user = false))[1] AS highest_severity,
      (ARRAY_AGG(alert_rows.label ORDER BY alert_rows.severity_rank DESC, alert_rows.sort_at_utc DESC NULLS LAST, alert_rows.alert_fingerprint ASC) FILTER (WHERE alert_rows.acknowledged_for_current_user = false))[1] AS highest_label,
      'banking_alert_signal:v3:' || MD5(COALESCE(STRING_AGG(
        CONCAT_WS('|',
          alert_rows.alert_fingerprint,
          alert_rows.alert_kind,
          alert_rows.entity_kind,
          alert_rows.entity_id::text,
          alert_rows.severity
        ),
        CHR(10)
        ORDER BY alert_rows.alert_fingerprint ASC
      ) FILTER (WHERE alert_rows.acknowledged_for_current_user = false), '')) AS alert_hash,
      'banking_alert_summary:v3:' || MD5(COALESCE(STRING_AGG(
        alert_rows.alert_fingerprint,
        CHR(10)
        ORDER BY alert_rows.alert_fingerprint ASC
      ) FILTER (WHERE alert_rows.acknowledged_for_current_user = false), '')) AS summary_signature
    FROM alert_rows
  ),
  aggregate_result AS MATERIALIZED (
    SELECT
      COALESCE(JSONB_AGG(
        jsonb_build_object(
          'alert_kind', detailed_alerts.alert_kind,
          'severity', detailed_alerts.severity,
          'severity_rank', detailed_alerts.severity_rank,
          'entity_kind', detailed_alerts.entity_kind,
          'entity_id', detailed_alerts.entity_id::text,
          'pay_batch_id', detailed_alerts.pay_batch_id::text,
          'alert_fingerprint', detailed_alerts.alert_fingerprint,
          'label', detailed_alerts.label,
          'title', detailed_alerts.title,
          'description', detailed_alerts.description,
          'action_guidance', detailed_alerts.action_guidance,
          'acknowledged_for_current_user', detailed_alerts.acknowledged_for_current_user,
          'requires_attention_for_current_user', NOT detailed_alerts.acknowledged_for_current_user,
          'acknowledged_at_utc', CASE WHEN detailed_alerts.acknowledged_at_utc IS NULL THEN NULL::text ELSE detailed_alerts.acknowledged_at_utc::text END,
          'sort_at_utc', CASE WHEN detailed_alerts.sort_at_utc IS NULL THEN NULL::text ELSE detailed_alerts.sort_at_utc::text END,
          'payload_json', detailed_alerts.payload_json
        )
        ORDER BY detailed_alerts.severity_rank DESC,
                 detailed_alerts.sort_at_utc DESC NULLS LAST,
                 detailed_alerts.alert_fingerprint ASC
      ), '[]'::jsonb) AS alerts_json,
      COALESCE(MAX(detailed_alerts.filtered_count), 0)::integer AS filtered_count,
      (ARRAY_AGG(detailed_alerts.severity ORDER BY detailed_alerts.severity_rank DESC, detailed_alerts.sort_at_utc DESC NULLS LAST, detailed_alerts.alert_fingerprint ASC))[1] AS highest_severity,
      (ARRAY_AGG(detailed_alerts.label ORDER BY detailed_alerts.severity_rank DESC, detailed_alerts.sort_at_utc DESC NULLS LAST, detailed_alerts.alert_fingerprint ASC))[1] AS highest_label
    FROM detailed_alerts
  )
  SELECT jsonb_build_object(
    'ok', true,
    'generated_at_utc', now()::text,
    'actor_user_id', p_actor_user_id::text,
    'include_acknowledged', COALESCE(p_include_acknowledged, false),
    'limit', COALESCE(v_limit, 0),
    'alerts', aggregate_result.alerts_json,
    'banking_alert_hash', COALESCE(signal_aggregate.alert_hash, 'banking_alert_signal:v3:' || MD5('')),
    'banking_alert_summary_signature', COALESCE(signal_aggregate.summary_signature, 'banking_alert_summary:v3:' || MD5('')),
    'banking_unacknowledged_alert_count', COALESCE(signal_aggregate.unacknowledged_count, 0),
    'banking_highest_alert_severity', CASE WHEN COALESCE(signal_aggregate.unacknowledged_count, 0) > 0 THEN COALESCE(signal_aggregate.highest_severity, '') ELSE '' END,
    'banking_highest_alert_label', CASE WHEN COALESCE(signal_aggregate.unacknowledged_count, 0) > 0 THEN COALESCE(signal_aggregate.highest_label, '') ELSE '' END,
    'unacknowledged_count', COALESCE(signal_aggregate.unacknowledged_count, 0),
    'filtered_count', COALESCE(aggregate_result.filtered_count, 0),
    'highest_severity', CASE WHEN COALESCE(aggregate_result.filtered_count, 0) > 0 THEN aggregate_result.highest_severity ELSE NULL::text END,
    'highest_label', CASE WHEN COALESCE(aggregate_result.filtered_count, 0) > 0 THEN aggregate_result.highest_label ELSE NULL::text END
  )
  INTO v_result
  FROM aggregate_result
  CROSS JOIN signal_aggregate;

  RETURN COALESCE(v_result, jsonb_build_object(
    'ok', true,
    'generated_at_utc', now()::text,
    'actor_user_id', p_actor_user_id::text,
    'include_acknowledged', COALESCE(p_include_acknowledged, false),
    'limit', COALESCE(v_limit, 0),
    'alerts', '[]'::jsonb,
    'banking_alert_hash', 'banking_alert_signal:v3:' || MD5(''),
    'banking_alert_summary_signature', 'banking_alert_summary:v3:' || MD5(''),
    'banking_unacknowledged_alert_count', 0,
    'banking_highest_alert_severity', '',
    'banking_highest_alert_label', '',
    'unacknowledged_count', 0,
    'filtered_count', 0,
    'highest_severity', NULL::text,
    'highest_label', NULL::text
  ));
END;
$function$;


CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge(
  p_alert_fingerprint text,
  p_alert_kind text,
  p_entity_kind text,
  p_entity_id uuid,
  p_actor_user_id uuid,
  p_note text DEFAULT NULL::text,
  p_alert_payload_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_fingerprint text := nullif(btrim(coalesce(p_alert_fingerprint, '')), '');
  v_alert_kind text := upper(nullif(btrim(coalesce(p_alert_kind, '')), ''));
  v_entity_kind text := lower(nullif(btrim(coalesce(p_entity_kind, '')), ''));
  v_alert_payload_json jsonb := '{}'::jsonb;
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_active_alert_json jsonb := NULL::jsonb;
  v_current_alert_fingerprint text := NULL::text;
  v_existing_id uuid := NULL::uuid;
  v_existing_alert_kind text := NULL::text;
  v_existing_entity_kind text := NULL::text;
  v_existing_entity_id uuid := NULL::uuid;
  v_existing_alert_payload_json jsonb := '{}'::jsonb;
  v_ack_id uuid;
  v_ack_alert_fingerprint text;
  v_ack_alert_kind text;
  v_ack_entity_kind text;
  v_ack_entity_id uuid;
  v_acknowledged_by_user_id uuid;
  v_acknowledged_at_utc timestamptz;
  v_acknowledge_scope text;
  v_ack_note text;
  v_ack_alert_payload_json jsonb;
  v_ack_resolved_at_ack boolean;
  v_created boolean := false;
  v_upsert_inserted boolean := false;
  v_remaining_count integer := 0;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF v_alert_fingerprint IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_FINGERPRINT_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_FINGERPRINT_REQUIRED')::text;
  END IF;

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_KIND_REQUIRED')::text;
  END IF;

  IF v_entity_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_KIND_REQUIRED')::text;
  END IF;

  IF p_entity_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ENTITY_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ACTOR_REQUIRED')::text;
  END IF;

  IF p_alert_payload_json IS NOT NULL AND coalesce(jsonb_typeof(p_alert_payload_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_PAYLOAD_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_ACKNOWLEDGE_PAYLOAD_MUST_BE_OBJECT',
              'alert_fingerprint', v_alert_fingerprint
            )::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge:' || v_alert_fingerprint),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  v_alert_payload_json := coalesce(p_alert_payload_json, '{}'::jsonb);

  SELECT
    public.banking_alert_acknowledgements.id,
    public.banking_alert_acknowledgements.alert_kind,
    public.banking_alert_acknowledgements.entity_kind,
    public.banking_alert_acknowledgements.entity_id,
    COALESCE(public.banking_alert_acknowledgements.alert_payload_json, '{}'::jsonb)
  INTO
    v_existing_id,
    v_existing_alert_kind,
    v_existing_entity_kind,
    v_existing_entity_id,
    v_existing_alert_payload_json
  FROM public.banking_alert_acknowledgements
  WHERE public.banking_alert_acknowledgements.alert_fingerprint = v_alert_fingerprint
    AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
    AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
  ORDER BY public.banking_alert_acknowledgements.acknowledged_at_utc ASC, public.banking_alert_acknowledgements.id ASC
  LIMIT 1
  FOR UPDATE;

  IF v_existing_id IS NOT NULL THEN
    IF v_alert_payload_json = '{}'::jsonb THEN
      v_alert_payload_json := COALESCE(v_existing_alert_payload_json, '{}'::jsonb);
    END IF;
  ELSE
    v_active_json := public.banking_alerts_active_for_user(
      p_actor_user_id,
      v_entity_kind,
      p_entity_id,
      false,
      0
    );

    SELECT active_alert.alert_json
    INTO v_active_alert_json
    FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
    WHERE active_alert.alert_json ->> 'alert_fingerprint' = v_alert_fingerprint
      AND upper(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', ''))) = v_alert_kind
      AND lower(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', ''))) = v_entity_kind
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
      AND (active_alert.alert_json ->> 'entity_id')::uuid = p_entity_id
    LIMIT 1;

    IF v_active_alert_json IS NULL THEN
      SELECT
        public.banking_alert_acknowledgements.id,
        public.banking_alert_acknowledgements.alert_kind,
        public.banking_alert_acknowledgements.entity_kind,
        public.banking_alert_acknowledgements.entity_id,
        COALESCE(public.banking_alert_acknowledgements.alert_payload_json, '{}'::jsonb)
      INTO
        v_existing_id,
        v_existing_alert_kind,
        v_existing_entity_kind,
        v_existing_entity_id,
        v_existing_alert_payload_json
      FROM public.banking_alert_acknowledgements
      WHERE public.banking_alert_acknowledgements.alert_fingerprint = v_alert_fingerprint
        AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
        AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
      ORDER BY public.banking_alert_acknowledgements.acknowledged_at_utc ASC, public.banking_alert_acknowledgements.id ASC
      LIMIT 1;

      IF v_existing_id IS NOT NULL THEN
        IF v_alert_payload_json = '{}'::jsonb THEN
          v_alert_payload_json := COALESCE(v_existing_alert_payload_json, '{}'::jsonb);
        END IF;
      ELSE
        SELECT active_alert.alert_json ->> 'alert_fingerprint'
        INTO v_current_alert_fingerprint
        FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
        WHERE upper(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', ''))) = v_alert_kind
          AND lower(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', ''))) = v_entity_kind
          AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
          AND (active_alert.alert_json ->> 'entity_id')::uuid = p_entity_id
        ORDER BY active_alert.alert_json ->> 'alert_fingerprint'
        LIMIT 1;

        v_remaining_json := public.banking_alerts_active_for_user(
          p_actor_user_id,
          NULL::text,
          NULL::uuid,
          false,
          25
        );

        v_signal_json := public.banking_alert_signal_for_user(
          p_actor_user_id,
          NULL::text
        );

        v_remaining_json := v_remaining_json || jsonb_build_object(
          'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
          'banking_unacknowledged_alert_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
          'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
          'unacknowledged_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
          'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
        );

        RETURN jsonb_build_object(
          'ok', true,
          'created', false,
          'already_acknowledged', false,
          'acknowledged', false,
          'ignored', true,
          'ignored_count', 1,
          'reason', 'ALERT_NOT_CURRENT',
          'code', 'BANKING_ALERT_ACKNOWLEDGE_ALERT_NOT_ACTIVE',
          'alert_fingerprint', v_alert_fingerprint,
          'alert_kind', v_alert_kind,
          'entity_kind', v_entity_kind,
          'entity_id', p_entity_id::text,
          'current_alert_fingerprint', v_current_alert_fingerprint,
          'entity_alert_summary', v_active_json,
          'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
          'banking_unacknowledged_alert_count', COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0),
          'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
          'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
          'remaining_alert_summary', v_remaining_json,
          'alert_summary', v_remaining_json
        );
      END IF;
    END IF;

    IF v_existing_id IS NULL AND v_alert_payload_json = '{}'::jsonb THEN
      v_alert_payload_json := coalesce(v_active_alert_json -> 'payload_json', '{}'::jsonb);
    END IF;
  END IF;

  INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
    alert_fingerprint,
    alert_kind,
    entity_kind,
    entity_id,
    acknowledged_by_user_id,
    acknowledged_at_utc,
    acknowledge_scope,
    note,
    alert_payload_json,
    resolved_at_ack
  )
  VALUES (
    v_alert_fingerprint,
    v_alert_kind,
    v_entity_kind,
    p_entity_id,
    p_actor_user_id,
    now(),
    'USER',
    nullif(btrim(coalesce(p_note, '')), ''),
    v_alert_payload_json,
    false
  )
  ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
  SET
    note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
    alert_payload_json = CASE
      WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
      ELSE EXCLUDED.alert_payload_json
    END
  RETURNING
    banking_alert_acknowledgement_upsert.id,
    banking_alert_acknowledgement_upsert.alert_fingerprint,
    banking_alert_acknowledgement_upsert.alert_kind,
    banking_alert_acknowledgement_upsert.entity_kind,
    banking_alert_acknowledgement_upsert.entity_id,
    banking_alert_acknowledgement_upsert.acknowledged_by_user_id,
    banking_alert_acknowledgement_upsert.acknowledged_at_utc,
    banking_alert_acknowledgement_upsert.acknowledge_scope,
    banking_alert_acknowledgement_upsert.note,
    banking_alert_acknowledgement_upsert.alert_payload_json,
    banking_alert_acknowledgement_upsert.resolved_at_ack,
    (banking_alert_acknowledgement_upsert.xmax = 0)
  INTO
    v_ack_id,
    v_ack_alert_fingerprint,
    v_ack_alert_kind,
    v_ack_entity_kind,
    v_ack_entity_id,
    v_acknowledged_by_user_id,
    v_acknowledged_at_utc,
    v_acknowledge_scope,
    v_ack_note,
    v_ack_alert_payload_json,
    v_ack_resolved_at_ack,
    v_upsert_inserted;

  v_created := coalesce(v_upsert_inserted, false);

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'created', v_created,
    'already_acknowledged', NOT v_created,
    'acknowledged', true,
    'ignored', false,
    'ignored_count', 0,
    'remaining_unacknowledged_count', v_remaining_count,
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json,
    'acknowledgement', jsonb_build_object(
      'id', v_ack_id::text,
      'alert_fingerprint', v_ack_alert_fingerprint,
      'alert_kind', v_ack_alert_kind,
      'entity_kind', v_ack_entity_kind,
      'entity_id', v_ack_entity_id::text,
      'acknowledged_by_user_id', v_acknowledged_by_user_id::text,
      'acknowledged_at_utc', v_acknowledged_at_utc::text,
      'acknowledge_scope', v_acknowledge_scope,
      'note', v_ack_note,
      'alert_payload_json', v_ack_alert_payload_json,
      'resolved_at_ack', v_ack_resolved_at_ack
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge_many(
  p_actor_user_id uuid,
  p_alerts_json jsonb,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_requested_count integer := 0;
  v_created_count integer := 0;
  v_already_acknowledged_count integer := 0;
  v_acknowledged_count integer := 0;
  v_ignored_count integer := 0;
  v_remaining_count integer := 0;
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_acknowledged_alerts jsonb := '[]'::jsonb;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_MANY_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_MANY_ACTOR_REQUIRED')::text;
  END IF;

  IF p_alerts_json IS NULL OR coalesce(jsonb_typeof(p_alerts_json), 'null') <> 'array' THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_MANY_ALERTS_ARRAY_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_MANY_ALERTS_ARRAY_REQUIRED')::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge_many'),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  WITH requested_fingerprints_for_count AS (
    SELECT DISTINCT
      nullif(btrim(coalesce(
        CASE
          WHEN jsonb_typeof(requested_alerts_for_count.requested_alert_json) = 'string'
            THEN trim(both '"' from requested_alerts_for_count.requested_alert_json::text)
          WHEN jsonb_typeof(requested_alerts_for_count.requested_alert_json) = 'object'
            THEN COALESCE(
              requested_alerts_for_count.requested_alert_json ->> 'alert_fingerprint',
              requested_alerts_for_count.requested_alert_json ->> 'fingerprint'
            )
          ELSE NULL::text
        END,
        ''
      )), '') AS alert_fingerprint
    FROM jsonb_array_elements(p_alerts_json) AS requested_alerts_for_count(requested_alert_json)
  )
  SELECT count(*)::integer
  INTO v_requested_count
  FROM requested_fingerprints_for_count
  WHERE requested_fingerprints_for_count.alert_fingerprint IS NOT NULL;

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    0
  );

  WITH requested_fingerprints AS (
    SELECT DISTINCT
      nullif(btrim(coalesce(
        CASE
          WHEN jsonb_typeof(requested_alerts.requested_alert_json) = 'string'
            THEN trim(both '"' from requested_alerts.requested_alert_json::text)
          WHEN jsonb_typeof(requested_alerts.requested_alert_json) = 'object'
            THEN COALESCE(
              requested_alerts.requested_alert_json ->> 'alert_fingerprint',
              requested_alerts.requested_alert_json ->> 'fingerprint'
            )
          ELSE NULL::text
        END,
        ''
      )), '') AS alert_fingerprint
    FROM jsonb_array_elements(p_alerts_json) AS requested_alerts(requested_alert_json)
  ),
  active_alerts AS (
    SELECT
      active_alert.alert_json ->> 'alert_fingerprint' AS alert_fingerprint,
      active_alert.alert_json ->> 'alert_kind' AS alert_kind,
      active_alert.alert_json ->> 'entity_kind' AS entity_kind,
      (active_alert.alert_json ->> 'entity_id')::uuid AS entity_id,
      active_alert.alert_json AS alert_json,
      coalesce(active_alert.alert_json -> 'payload_json', '{}'::jsonb) AS payload_json
    FROM jsonb_array_elements(coalesce(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert(alert_json)
    WHERE nullif(btrim(coalesce(active_alert.alert_json ->> 'alert_fingerprint', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'alert_kind', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_kind', '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(active_alert.alert_json ->> 'entity_id', '')), '') IS NOT NULL
  ),
  matched_active_alerts AS (
    SELECT DISTINCT ON (active_alerts.alert_fingerprint)
      active_alerts.alert_fingerprint,
      upper(btrim(active_alerts.alert_kind)) AS alert_kind,
      lower(btrim(active_alerts.entity_kind)) AS entity_kind,
      active_alerts.entity_id,
      active_alerts.alert_json,
      coalesce(active_alerts.payload_json, '{}'::jsonb) AS payload_json
    FROM active_alerts
    JOIN requested_fingerprints
      ON requested_fingerprints.alert_fingerprint = active_alerts.alert_fingerprint
    WHERE requested_fingerprints.alert_fingerprint IS NOT NULL
    ORDER BY active_alerts.alert_fingerprint ASC
  ),
  upserted_acknowledgements AS (
    INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
      alert_fingerprint,
      alert_kind,
      entity_kind,
      entity_id,
      acknowledged_by_user_id,
      acknowledged_at_utc,
      acknowledge_scope,
      note,
      alert_payload_json,
      resolved_at_ack
    )
    SELECT
      matched_active_alerts.alert_fingerprint,
      matched_active_alerts.alert_kind,
      matched_active_alerts.entity_kind,
      matched_active_alerts.entity_id,
      p_actor_user_id,
      now(),
      'USER',
      nullif(btrim(coalesce(p_note, '')), ''),
      matched_active_alerts.payload_json,
      false
    FROM matched_active_alerts
    WHERE true
    ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
    SET
      note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
      alert_payload_json = CASE
        WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
        ELSE EXCLUDED.alert_payload_json
      END
    RETURNING
      banking_alert_acknowledgement_upsert.alert_fingerprint,
      banking_alert_acknowledgement_upsert.alert_kind,
      banking_alert_acknowledgement_upsert.entity_kind,
      banking_alert_acknowledgement_upsert.entity_id,
      banking_alert_acknowledgement_upsert.acknowledged_at_utc,
      (banking_alert_acknowledgement_upsert.xmax = 0) AS created
  ),
  already_existing_requested_acknowledgements AS (
    SELECT DISTINCT ON (public.banking_alert_acknowledgements.alert_fingerprint)
      public.banking_alert_acknowledgements.alert_fingerprint,
      public.banking_alert_acknowledgements.alert_kind,
      public.banking_alert_acknowledgements.entity_kind,
      public.banking_alert_acknowledgements.entity_id,
      public.banking_alert_acknowledgements.acknowledged_at_utc,
      false AS created
    FROM public.banking_alert_acknowledgements
    JOIN requested_fingerprints
      ON requested_fingerprints.alert_fingerprint = public.banking_alert_acknowledgements.alert_fingerprint
    LEFT JOIN upserted_acknowledgements
      ON upserted_acknowledgements.alert_fingerprint = public.banking_alert_acknowledgements.alert_fingerprint
    WHERE requested_fingerprints.alert_fingerprint IS NOT NULL
      AND upserted_acknowledgements.alert_fingerprint IS NULL
      AND public.banking_alert_acknowledgements.acknowledged_by_user_id = p_actor_user_id
      AND upper(btrim(coalesce(public.banking_alert_acknowledgements.acknowledge_scope, 'USER'))) = 'USER'
    ORDER BY public.banking_alert_acknowledgements.alert_fingerprint ASC,
             public.banking_alert_acknowledgements.acknowledged_at_utc ASC,
             public.banking_alert_acknowledgements.id ASC
  ),
  changed_acknowledgements AS (
    SELECT
      upserted_acknowledgements.alert_fingerprint,
      upserted_acknowledgements.alert_kind,
      upserted_acknowledgements.entity_kind,
      upserted_acknowledgements.entity_id,
      upserted_acknowledgements.acknowledged_at_utc,
      upserted_acknowledgements.created
    FROM upserted_acknowledgements

    UNION ALL

    SELECT
      already_existing_requested_acknowledgements.alert_fingerprint,
      already_existing_requested_acknowledgements.alert_kind,
      already_existing_requested_acknowledgements.entity_kind,
      already_existing_requested_acknowledgements.entity_id,
      already_existing_requested_acknowledgements.acknowledged_at_utc,
      already_existing_requested_acknowledgements.created
    FROM already_existing_requested_acknowledgements
  )
  SELECT
    coalesce(count(*) FILTER (WHERE changed_acknowledgements.created = true), 0)::integer,
    coalesce(count(*) FILTER (WHERE changed_acknowledgements.created = false), 0)::integer,
    coalesce(count(*), 0)::integer,
    coalesce(jsonb_agg(jsonb_build_object(
      'alert_fingerprint', changed_acknowledgements.alert_fingerprint,
      'alert_kind', changed_acknowledgements.alert_kind,
      'entity_kind', changed_acknowledgements.entity_kind,
      'entity_id', changed_acknowledgements.entity_id::text,
      'acknowledged_at_utc', changed_acknowledgements.acknowledged_at_utc::text,
      'created', changed_acknowledgements.created,
      'already_acknowledged', NOT changed_acknowledgements.created
    ) ORDER BY changed_acknowledgements.acknowledged_at_utc DESC, changed_acknowledgements.alert_fingerprint ASC), '[]'::jsonb)
  INTO
    v_created_count,
    v_already_acknowledged_count,
    v_acknowledged_count,
    v_acknowledged_alerts
  FROM changed_acknowledgements;

  v_ignored_count := greatest(coalesce(v_requested_count, 0) - coalesce(v_acknowledged_count, 0), 0);

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'requested_count', coalesce(v_requested_count, 0),
    'created_count', coalesce(v_created_count, 0),
    'already_acknowledged_count', coalesce(v_already_acknowledged_count, 0),
    'acknowledged_count', coalesce(v_acknowledged_count, 0),
    'remaining_unacknowledged_count', coalesce(v_remaining_count, 0),
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', coalesce(v_remaining_count, 0),
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'ignored_count', coalesce(v_ignored_count, 0),
    'acknowledged_alerts', coalesce(v_acknowledged_alerts, '[]'::jsonb),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json
  );
END;
$function$;


DROP FUNCTION IF EXISTS public.banking_alert_payload_for_pay_batch(text, uuid);

CREATE OR REPLACE FUNCTION public.banking_alert_payload_for_pay_batch(
  p_alert_kind text,
  p_pay_batch_id uuid,
  p_source_kind text DEFAULT NULL::text,
  p_source_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_alert_kind text;
  v_source_kind text;
  v_batch record;
  v_funds_check_json jsonb := '{}'::jsonb;
  v_required_gbp_text text := NULL;
  v_available_gbp_text text := NULL;
  v_required_gbp numeric := NULL;
  v_available_gbp numeric := NULL;
  v_sufficient_text text := NULL;
  v_sufficient boolean := NULL;
  v_funding_account_ref text := NULL;
  v_rail_provider text := NULL;
  v_rail_env text := NULL;
  v_funds_check_checked_at_utc text := NULL;
  v_last_funds_check_at_utc_text text := NULL;
  v_execution_committed_at_utc_text text := NULL;
  v_last_status_checked_at_utc_text text := NULL;
  v_latest_transfer jsonb := NULL;
  v_latest_transfer_event jsonb := NULL;
  v_latest_correction_request jsonb := NULL;
  v_latest_correction_work_item jsonb := NULL;
  v_latest_remittance_failure jsonb := NULL;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL;
  v_review_reason_code text := NULL;
  v_provider_operation_id uuid := NULL::uuid;
  v_provider_title text := NULL;
  v_provider_description text := NULL;
  v_provider_action_label text := NULL;
  v_grouped_alert_payload jsonb := '{}'::jsonb;
  v_provider_failure_reason_code text := NULL::text;
  v_provider_failure_reason_group text := NULL::text;
  v_provider_failure_reason_label text := NULL::text;
  v_provider_event_key text := NULL::text;
  v_webhook_receipt_id uuid := NULL::uuid;
BEGIN
  v_alert_kind := UPPER(NULLIF(BTRIM(COALESCE(p_alert_kind, '')), ''));
  v_source_kind := lower(nullif(btrim(coalesce(p_source_kind, '')), ''));

  IF v_alert_kind IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_KIND_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PAYLOAD_KIND_REQUIRED')::text;
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_PAYLOAD_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  v_alert_kind := CASE v_alert_kind
    WHEN 'BLOCKED_FUNDS' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
    WHEN 'BANK_REJECTED_PAYMENT' THEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE'
    WHEN 'BANK_RETURNED_PAYMENT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'PAYMENT_PROVIDER_SUBMIT_REVIEW' THEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER'
    WHEN 'PAYMENT_CORRECTION_FAILED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    WHEN 'PAYMENT_CORRECTION_BLOCKED' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    WHEN 'PAYMENT_CORRECTION_AWAITING_APPROVAL' THEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS'
    ELSE v_alert_kind
  END;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.bulk_reference,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.funding_account_ref,
    public.pay_batches.last_funds_check_at_utc,
    public.pay_batches.last_funds_check_json,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.last_status_checked_at_utc,
    public.pay_batches.cancelled_at_utc,
    public.pay_batches.completed_at_utc
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'BANKING_ALERT_PAYLOAD_PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  v_funds_check_json := COALESCE(v_batch.last_funds_check_json, '{}'::jsonb);

  v_required_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{required_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount}'), '')
  );

  IF v_required_gbp_text IS NOT NULL AND v_required_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_required_gbp := v_required_gbp_text::numeric;
  END IF;

  v_available_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{available_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount}'), '')
  );

  IF v_available_gbp_text IS NOT NULL AND v_available_gbp_text ~ '^-?[0-9]+(\.[0-9]+)?$' THEN
    v_available_gbp := v_available_gbp_text::numeric;
  END IF;

  v_sufficient_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{sufficient}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{is_sufficient}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{funds_sufficient}'), '')
  );

  IF v_sufficient_text IS NOT NULL THEN
    IF LOWER(v_sufficient_text) IN ('true', 't', '1', 'yes', 'y', 'on') THEN
      v_sufficient := true;
    ELSIF LOWER(v_sufficient_text) IN ('false', 'f', '0', 'no', 'n', 'off') THEN
      v_sufficient := false;
    END IF;
  END IF;

  v_funding_account_ref := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_id}'), ''),
    NULLIF(BTRIM(v_batch.funding_account_ref), '')
  );

  v_rail_provider := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_provider}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{provider}'), ''),
    NULLIF(BTRIM(v_batch.rail_provider_snapshot), '')
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_env}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{env}'), ''),
    NULLIF(BTRIM(v_batch.rail_env_snapshot), '')
  );

  v_last_funds_check_at_utc_text := CASE
    WHEN v_batch.last_funds_check_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.last_funds_check_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_execution_committed_at_utc_text := CASE
    WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.execution_committed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_last_status_checked_at_utc_text := CASE
    WHEN v_batch.last_status_checked_at_utc IS NULL THEN NULL
    ELSE TO_CHAR(v_batch.last_status_checked_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  END;

  v_funds_check_checked_at_utc := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{checked_at_utc}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{checked_at}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{created_at_utc}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{timestamp_utc}'), ''),
    v_last_funds_check_at_utc_text
  );

  SELECT
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_code, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), ''),
    NULLIF(BTRIM(COALESCE(provider_failure_event.provider_event_key, '')), ''),
    provider_failure_event.provider_webhook_receipt_id
  INTO
    v_provider_failure_reason_code,
    v_provider_failure_reason_group,
    v_provider_failure_reason_label,
    v_provider_event_key,
    v_webhook_receipt_id
  FROM public.pay_bank_transfer_events AS provider_failure_event
  WHERE provider_failure_event.pay_batch_id = p_pay_batch_id
    AND (
      v_source_kind IS DISTINCT FROM 'pay_bank_transfer_event'
      OR p_source_id IS NULL
      OR provider_failure_event.id = p_source_id
    )
    AND (
      NULLIF(BTRIM(COALESCE(provider_failure_event.provider_failure_reason_group, '')), '') IS NOT NULL
      OR NULLIF(BTRIM(COALESCE(provider_failure_event.provider_event_key, '')), '') IS NOT NULL
      OR provider_failure_event.provider_webhook_receipt_id IS NOT NULL
      OR UPPER(BTRIM(COALESCE(provider_failure_event.mapping_status, ''))) IN ('UNMATCHED','NO_MATCH','MULTIPLE_MATCHES')
    )
  ORDER BY COALESCE(provider_failure_event.event_time_utc, provider_failure_event.received_at_utc, provider_failure_event.created_at_utc) DESC NULLS LAST,
           provider_failure_event.id DESC
  LIMIT 1;

  IF v_provider_failure_reason_group IS NOT NULL THEN
    v_provider_failure_reason_label := initcap(replace(lower(v_provider_failure_reason_group), '_', ' '));
  END IF;

  IF v_alert_kind IN (
    'PROVIDER_OUTAGE_RETRY_LATER',
    'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER',
    'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
    'AUTO_UNWIND_PROGRESS',
    'WHOLE_BATCH_CANCELLATION_PROGRESS',
    'MANUAL_ADJUSTMENTS_CARRIED_FORWARD',
    'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS',
    'PAID_SETTLED_RECOVERY_REQUIRED',
    'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT',
    'WEBHOOK_UNMATCHED_REVIEW_REQUIRED'
  ) THEN
    WITH retry_plan_scope AS (
      SELECT COALESCE(public.pay_payment_correction_plan(
        p_pay_batch_id,
        jsonb_build_object(
          'scope_type', 'BATCH',
          'source_context', 'BANKING_ALERT_PAYLOAD',
          'requested_action', 'RETRY_PROVIDER_LATER'
        ),
        NULL::uuid
      ), '{}'::jsonb) AS retry_plan_json
    ),
    retry_operation_scope AS (
      SELECT
        retry_operation.id AS retry_operation_id,
        retry_operation.status AS retry_operation_status
      FROM public.banking_pay_operations AS retry_operation
      WHERE retry_operation.pay_batch_id = p_pay_batch_id
        AND UPPER(BTRIM(COALESCE(retry_operation.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
        AND UPPER(BTRIM(COALESCE(retry_operation.status, ''))) NOT IN ('COMPLETE','COMPLETED','SUCCEEDED','SUCCESS','FAILED','FAILED_FINAL','CANCELLED','CANCELED')
      ORDER BY COALESCE(retry_operation.updated_at_utc, retry_operation.created_at_utc) DESC NULLS LAST,
               retry_operation.created_at_utc DESC NULLS LAST,
               retry_operation.id DESC
      LIMIT 1
    ),
    retry_plan_counts AS (
      SELECT
        CASE
          WHEN COALESCE(retry_plan_scope.retry_plan_json->>'retry_eligible_count', '') ~ '^\d+$' THEN (retry_plan_scope.retry_plan_json->>'retry_eligible_count')::integer
          ELSE 0
        END AS retry_eligible_count,
        CASE
          WHEN COALESCE(retry_plan_scope.retry_plan_json->>'retry_ineligible_count', '') ~ '^\d+$' THEN (retry_plan_scope.retry_plan_json->>'retry_ineligible_count')::integer
          ELSE 0
        END AS retry_ineligible_count
      FROM retry_plan_scope
    ),
    item_counts AS (
      SELECT
        COUNT(DISTINCT pbi.id)::integer AS affected_payment_count,
        COUNT(DISTINCT pbc.candidate_id)::integer AS affected_candidate_count,
        COUNT(DISTINCT pbi.pay_bank_transfer_id) FILTER (WHERE pbi.pay_bank_transfer_id IS NOT NULL)::integer AS affected_transfer_count,
        COUNT(DISTINCT pbi.timesheet_id) FILTER (WHERE pbi.timesheet_id IS NOT NULL)::integer AS affected_timesheet_count,
        ROUND(COALESCE(SUM(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0)), 0), 2)::numeric AS amount_affected
      FROM public.pay_batch_candidates AS pbc
      JOIN public.pay_batch_items AS pbi
        ON pbi.pay_batch_candidate_id = pbc.id
      WHERE pbc.pay_batch_id = p_pay_batch_id
        AND COALESCE(pbi.is_voided, false) = false
        AND pbi.item_type <> 'DEBT_CREATED'
    ),
    correction_scope AS (
      SELECT
        (array_agg(ppcr.id ORDER BY ppcr.updated_at_utc DESC NULLS LAST, ppcr.created_at_utc DESC, ppcr.id DESC))[1] AS correction_request_id,
        COUNT(ppwi.id) FILTER (WHERE ppwi.status IN ('APPLIED','DONE','COMPLETE','COMPLETED'))::integer AS progress_completed,
        COUNT(ppwi.id)::integer AS progress_total,
        bool_or(ppcr.status IN ('AUTHORISED','EXPANDED','PROCESSING')) AS correction_running
      FROM public.pay_payment_correction_requests AS ppcr
      LEFT JOIN public.pay_payment_correction_work_items AS ppwi
        ON ppwi.correction_request_id = ppcr.id
      WHERE ppcr.pay_batch_id = p_pay_batch_id
        AND (
          (v_alert_kind = 'AUTO_UNWIND_PROGRESS' AND ppcr.correction_kind IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY'))
          OR (v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' AND ppcr.correction_kind = 'PRE_BANK_CANCEL')
          OR v_alert_kind NOT IN ('AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS')
        )
    ),
    carry_forward_scope AS (
      SELECT
        COUNT(*)::integer AS carry_forward_count,
        (array_agg(cf.id ORDER BY cf.id DESC))[1] AS carry_forward_id,
        (array_agg(cf.source_pay_batch_item_id ORDER BY cf.id DESC))[1] AS source_pay_batch_item_id
      FROM public.pay_manual_adjustment_carry_forwards AS cf
      WHERE cf.source_pay_batch_id = p_pay_batch_id
         OR cf.target_pay_batch_id = p_pay_batch_id
    ),
    single_transfer_scope AS (
      SELECT pbt.id AS pay_bank_transfer_id
      FROM public.pay_bank_transfers AS pbt
      WHERE pbt.pay_batch_id = p_pay_batch_id
        AND v_source_kind = 'pay_bank_transfer'
        AND pbt.id = p_source_id
      LIMIT 1
    )
    SELECT jsonb_strip_nulls(
      jsonb_build_object(
        'stable_issue_key', CASE
          WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text, (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros), 'NO_WINDOW')
          WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_execution_committed_at_utc_text, 'NO_WINDOW')
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(p_pay_batch_id::text, 'NO_BATCH') || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
          WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_failure_reason_group, v_provider_event_key, 'NO_TERMINAL_FAILURE_KEY')
          WHEN v_alert_kind = 'AUTO_UNWIND_PROGRESS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), 'NO_CORRECTION_REQUEST')
          WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), 'NO_CORRECTION_REQUEST')
          WHEN v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs), (SELECT cfs.source_pay_batch_item_id::text FROM carry_forward_scope AS cfs), 'NO_BLOCKER_KEY')
          WHEN v_alert_kind IN ('PAID_SETTLED_RECOVERY_REQUIRED','CANCELLATION_RACED_WITH_PROVIDER_SUBMIT') THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts), (SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_event_key, 'NO_SCOPE_KEY')
          ELSE p_pay_batch_id::text || ':' || v_alert_kind
        END,
        'dedupe_key', CASE
          WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text, (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros), 'NO_WINDOW')
          WHEN v_alert_kind = 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_last_status_checked_at_utc_text, v_execution_committed_at_utc_text, 'NO_WINDOW')
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(p_pay_batch_id::text, 'NO_BATCH') || ':' || v_alert_kind || ':' || COALESCE(v_rail_provider, 'UNKNOWN') || ':' || COALESCE(v_rail_env, 'UNKNOWN') || ':' || COALESCE(v_provider_event_key, 'NO_PROVIDER_EVENT_KEY')
          WHEN v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || COALESCE((SELECT cs.correction_request_id::text FROM correction_scope AS cs), v_provider_failure_reason_group, v_provider_event_key, 'NO_TERMINAL_FAILURE_KEY')
          WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NOT NULL THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT cs.correction_request_id::text FROM correction_scope AS cs)
          WHEN (SELECT sts.pay_bank_transfer_id FROM single_transfer_scope AS sts) IS NOT NULL THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts)
          WHEN (SELECT cfs.carry_forward_id FROM carry_forward_scope AS cfs) IS NOT NULL AND v_alert_kind = 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN p_pay_batch_id::text || ':' || v_alert_kind || ':' || (SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs)
          ELSE p_pay_batch_id::text || ':' || v_alert_kind
        END,
        'alert_kind', v_alert_kind,
        'issue_kind', v_alert_kind,
        'alert_severity', CASE
          WHEN v_alert_kind IN ('AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS') THEN 'PROGRESS'
          WHEN v_alert_kind = 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'INFO'
          ELSE 'ACTION_REQUIRED'
        END,
        'provider_failure_reason_code', v_provider_failure_reason_code,
        'provider_failure_reason_group', CASE WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(v_provider_failure_reason_group, 'WEBHOOK_UNMATCHED') ELSE v_provider_failure_reason_group END,
        'provider_failure_reason_label', CASE WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN COALESCE(v_provider_failure_reason_label, 'Webhook unmatched') ELSE v_provider_failure_reason_label END,
        'provider_event_key', v_provider_event_key,
        'provider_webhook_receipt_id', CASE WHEN v_webhook_receipt_id IS NULL THEN NULL ELSE v_webhook_receipt_id::text END,
        'pay_batch_id', p_pay_batch_id::text,
        'provider', v_rail_provider,
        'rail', v_rail_provider,
        'rail_env', v_rail_env,
        'outage_window', CASE WHEN v_alert_kind = 'PROVIDER_OUTAGE_RETRY_LATER' THEN COALESCE(v_last_status_checked_at_utc_text, v_last_funds_check_at_utc_text, v_execution_committed_at_utc_text) ELSE NULL END
      )
      || jsonb_build_object(
        'retry_operation_id', CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NULL THEN NULL ELSE (SELECT ros.retry_operation_id::text FROM retry_operation_scope AS ros) END,
        'retry_operation_status', (SELECT ros.retry_operation_status FROM retry_operation_scope AS ros),
        'retry_eligible_count', COALESCE((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0),
        'retry_ineligible_count', COALESCE((SELECT rpc.retry_ineligible_count FROM retry_plan_counts AS rpc), 0),
        'correction_request_id', CASE WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NULL THEN NULL ELSE (SELECT cs.correction_request_id::text FROM correction_scope AS cs) END,
        'cancellation_operation_id', CASE WHEN v_alert_kind = 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN CASE WHEN (SELECT cs.correction_request_id FROM correction_scope AS cs) IS NULL THEN NULL ELSE (SELECT cs.correction_request_id::text FROM correction_scope AS cs) END ELSE NULL END,
        'pay_bank_transfer_id', CASE WHEN (SELECT sts.pay_bank_transfer_id FROM single_transfer_scope AS sts) IS NULL THEN NULL ELSE (SELECT sts.pay_bank_transfer_id::text FROM single_transfer_scope AS sts) END,
        'carry_forward_id', CASE WHEN (SELECT cfs.carry_forward_id FROM carry_forward_scope AS cfs) IS NULL THEN NULL ELSE (SELECT cfs.carry_forward_id::text FROM carry_forward_scope AS cfs) END,
        'source_pay_batch_item_id', CASE WHEN (SELECT cfs.source_pay_batch_item_id FROM carry_forward_scope AS cfs) IS NULL THEN NULL ELSE (SELECT cfs.source_pay_batch_item_id::text FROM carry_forward_scope AS cfs) END,
        'affected_payment_count', COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0),
        'affected_candidate_count', COALESCE((SELECT ic.affected_candidate_count FROM item_counts AS ic), 0),
        'affected_transfer_count', COALESCE((SELECT ic.affected_transfer_count FROM item_counts AS ic), 0),
        'affected_timesheet_count', COALESCE((SELECT ic.affected_timesheet_count FROM item_counts AS ic), 0),
        'amount_affected', COALESCE((SELECT ic.amount_affected FROM item_counts AS ic), 0),
        'current_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
        'required_user_action', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Retry unsent payments from Banking Pay Overview.'
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Open Current Payment Status and check the provider outcome.'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Open Current Payment Status and rewind financials where no money moved.'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Monitor rewind progress.'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Monitor cancellation progress in Banking Pay Overview.'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Review carried-forward manual adjustments in the next pay run.'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Open Current Payment Status and review ambiguous manual adjustment blockers.'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Open Current Payment Status and recover overpayment in next pay run.'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Open Current Payment Status and check provider submission before continuing.'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Review the unmatched provider webhook and link it to the correct payment if safe.'
          ELSE 'Open Banking Pay.'
        END,
        'auto_unwind_running', v_alert_kind = 'AUTO_UNWIND_PROGRESS' AND COALESCE((SELECT cs.correction_running FROM correction_scope AS cs), false),
        'manual_rewind_required', v_alert_kind = 'TERMINAL_NO_MONEY_REWIND_AVAILABLE',
        'progress_completed', COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0),
        'progress_total', COALESCE((SELECT cs.progress_total FROM correction_scope AS cs), 0)
      )
      || jsonb_build_object(
        'link_target', 'banking_pay_batch',
        'link_tab', CASE
          WHEN v_alert_kind IN ('PROVIDER_OUTAGE_RETRY_LATER','AUTO_UNWIND_PROGRESS','WHOLE_BATCH_CANCELLATION_PROGRESS') THEN 'overview'
          WHEN v_alert_kind = 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'current_payment_status'
          ELSE 'current_payment_status'
        END,
        'user_label', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NOT NULL THEN 'Retrying unsent payments — ' || COALESCE(NULLIF((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' payments in progress' ELSE 'Bank unavailable — ' || COALESCE(NULLIF((SELECT rpc.retry_eligible_count FROM retry_plan_counts AS rpc), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' unsent payments can be retried' END
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'Provider outcome unknown — ' || COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0)::text || ' payments need checking'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'Failed payments — Rewind financials available for ' || COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0)::text || ' payments'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Rewinding failed payments — ' || COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0)::text || ' of ' || COALESCE(NULLIF((SELECT cs.progress_total FROM correction_scope AS cs), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' complete'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Cancelling scheduled batch — ' || COALESCE((SELECT cs.progress_completed FROM correction_scope AS cs), 0)::text || ' of ' || COALESCE(NULLIF((SELECT cs.progress_total FROM correction_scope AS cs), 0), COALESCE((SELECT ic.affected_payment_count FROM item_counts AS ic), 0))::text || ' payment scopes complete'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Manual adjustments carried forward — ' || COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0)::text || ' adjustments will appear in the next pay run'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'Manual adjustment blockers — review required'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Paid — recovery required'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation conflict — provider submission already started'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'Unmatched bank webhook — review required'
          ELSE initcap(replace(lower(v_alert_kind), '_', ' '))
        END,
        'user_description', CASE v_alert_kind
          WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN CASE WHEN (SELECT ros.retry_operation_id FROM retry_operation_scope AS ros) IS NOT NULL THEN 'CloudTMS is retrying payments confirmed as not sent. You can continue using CloudTMS while this runs.' ELSE 'The bank/provider was unavailable before the payment request was sent. Retry unsent payments from Banking Pay Overview.' END
          WHEN 'PROVIDER_OUTCOME_UNKNOWN_CHECK_PROVIDER' THEN 'A provider request may have been sent, but the outcome is not confirmed. Check provider state before retrying or unwinding.'
          WHEN 'TERMINAL_NO_MONEY_REWIND_AVAILABLE' THEN 'The provider/bank outcome indicates no money moved. Financials can be rewound from Current Payment Status.'
          WHEN 'AUTO_UNWIND_PROGRESS' THEN 'Automatic no-money unwind is running and this alert updates progress instead of creating per-payment alerts.'
          WHEN 'WHOLE_BATCH_CANCELLATION_PROGRESS' THEN 'Scheduled local cancellation is running in chunks and this alert updates progress.'
          WHEN 'MANUAL_ADJUSTMENTS_CARRIED_FORWARD' THEN 'Safe source-less manual adjustments were carried forward and will be included in the next pay run.'
          WHEN 'MANUAL_ADJUSTMENT_AMBIGUOUS_BLOCKERS' THEN 'One or more manual adjustments cannot be safely carried forward automatically.'
          WHEN 'PAID_SETTLED_RECOVERY_REQUIRED' THEN 'Money appears to have moved. Amend the timesheet and recover the overpayment in the next pay run rather than unwinding the payment.'
          WHEN 'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT' THEN 'Cancellation could not proceed because provider submission had already started.'
          WHEN 'WEBHOOK_UNMATCHED_REVIEW_REQUIRED' THEN 'A verified provider webhook was received but could not be matched safely to a payment.'
          ELSE 'Open Banking Pay for details.'
        END,
        'manual_adjustments_carried_forward_count', COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0),
        'carry_forward_count', COALESCE((SELECT cfs.carry_forward_count FROM carry_forward_scope AS cfs), 0),
        'remittance_already_sent', EXISTS (
          SELECT 1
          FROM public.pay_batch_candidates AS remittance_candidate
          WHERE remittance_candidate.pay_batch_id = p_pay_batch_id
            AND remittance_candidate.remittance_sent_at_utc IS NOT NULL
        ),
        'payload_is_grouped', true
      )
    )
    INTO v_grouped_alert_payload;

    RETURN v_grouped_alert_payload;
  END IF;

  IF v_alert_kind = 'BLOCKED_FUNDS' THEN
    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', 'BLOCKED_FUNDS',
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'execution_commit_state', UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))),
      'execution_commit_ref', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), ''),
      'execution_committed_at_utc', v_execution_committed_at_utc_text,
      'last_funds_check_at_utc', v_last_funds_check_at_utc_text,
      'funds_check_checked_at_utc', v_funds_check_checked_at_utc,
      'required_gbp', v_required_gbp,
      'available_gbp', v_available_gbp,
      'sufficient', v_sufficient,
      'funding_account_ref', v_funding_account_ref,
      'rail_provider', v_rail_provider,
      'rail_env', v_rail_env
    ));
  END IF;

  IF v_alert_kind IN ('BANK_REJECTED_PAYMENT', 'BANK_RETURNED_PAYMENT', 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED', 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT') THEN
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'pay_bank_transfer_id', public.pay_bank_transfers.id::text,
      'candidate_id', CASE WHEN public.pay_bank_transfers.candidate_id IS NULL THEN NULL ELSE public.pay_bank_transfers.candidate_id::text END,
      'umbrella_id', CASE WHEN public.pay_bank_transfers.umbrella_id IS NULL THEN NULL ELSE public.pay_bank_transfers.umbrella_id::text END,
      'transfer_group_key', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.transfer_group_key, '')), ''),
      'amount', public.pay_bank_transfers.amount,
      'currency', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.currency, '')), ''),
      'status', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.status, '')), ''),
      'rail_state', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, '')), ''),
      'rail_provider', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_provider, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_env, '')), ''),
      'request_id', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.request_id, '')), ''),
      'rail_tx_id', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.rail_tx_id, '')), ''),
      'payment_reference', NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.payment_reference, '')), ''),
      'completed_at_utc', CASE
        WHEN public.pay_bank_transfers.completed_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfers.completed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'created_at_utc', CASE
        WHEN public.pay_bank_transfers.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfers.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'failed_reason_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NULL THEN NULL
        ELSE MD5(public.pay_bank_transfers.failed_reason)
      END,
      'provider_submission_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_submission_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{submission_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{rail_submission_id}'), '')
      ),
      'provider_payment_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_payment_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{payment,id}'), '')
      ),
      'provider_transfer_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_transfer_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transfer,id}'), '')
      ),
      'provider_transaction_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{external_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{revolut_transaction_id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{transaction,id}'), '')
      ),
      'provider_response_id', COALESCE(
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{provider,response,id}'), ''),
        NULLIF(BTRIM(public.pay_bank_transfers.rail_meta_json #>> '{response,id}'), '')
      )
    ))
    INTO v_latest_transfer
    FROM public.pay_bank_transfers
    WHERE public.pay_bank_transfers.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_bank_transfer'
        OR public.pay_bank_transfers.id = p_source_id
      )
      AND (
        (v_alert_kind = 'BANK_REJECTED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR NULLIF(BTRIM(COALESCE(public.pay_bank_transfers.failed_reason, '')), '') IS NOT NULL
          ))
        OR (v_alert_kind = 'BANK_RETURNED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('RETURNED', 'REVERTED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('RETURNED', 'REVERTED')
          ))
        OR (v_alert_kind = 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.status, ''))) LIKE 'CREATE_ERROR%'
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfers.rail_state, ''))) LIKE 'CREATE_ERROR%'
          ))
        OR (v_alert_kind = 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED')
      )
    ORDER BY COALESCE(public.pay_bank_transfers.completed_at_utc, public.pay_bank_transfers.created_at_utc) DESC NULLS LAST,
             public.pay_bank_transfers.id DESC
    LIMIT 1;
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'pay_bank_transfer_event_id', public.pay_bank_transfer_events.id::text,
      'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
      'provider_key', public.pay_bank_transfer_events.provider_key,
      'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
      'provider_reference', public.pay_bank_transfer_events.provider_reference,
      'provider_state', public.pay_bank_transfer_events.provider_state,
      'normalised_state', public.pay_bank_transfer_events.normalised_state,
      'mapping_status', public.pay_bank_transfer_events.mapping_status,
      'movement_classification', public.pay_bank_transfer_events.movement_classification,
      'correction_disposition', public.pay_bank_transfer_events.correction_disposition,
      'event_source', public.pay_bank_transfer_events.event_source,
      'event_time_utc', CASE
        WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfer_events.event_time_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'received_at_utc', CASE
        WHEN public.pay_bank_transfer_events.received_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_bank_transfer_events.received_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_transfer_event
    FROM public.pay_bank_transfer_events
    WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_bank_transfer_event'
        OR public.pay_bank_transfer_events.id = p_source_id
      )
      AND (
        (v_alert_kind = 'BANK_REJECTED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'CANCELED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.movement_classification, ''))) IN ('NO_MONEY_UNWIND', 'PRE_BANK_CANCEL')
          ))
        OR (v_alert_kind = 'BANK_RETURNED_PAYMENT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('RETURNED', 'REVERTED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('RETURNED', 'REVERTED')
          ))
        OR (v_alert_kind = 'AMBIGUOUS_PAYMENT_REVIEW_REQUIRED'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.mapping_status, ''))) IN ('AMBIGUOUS', 'UNMATCHED', 'NO_MATCH', 'MULTIPLE_MATCHES')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.correction_disposition, ''))) IN ('AMBIGUOUS', 'ACTION_REQUIRED')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.movement_classification, ''))) IN ('AMBIGUOUS_REVIEW_REQUIRED')
          ))
        OR (v_alert_kind = 'RAIL_SUBMISSION_UNKNOWN_OR_TIMEOUT'
          AND (
            UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.normalised_state, ''))) LIKE 'CREATE_ERROR%'
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) IN ('UNKNOWN', 'TIMEOUT', 'TIMED_OUT', 'PENDING_REVIEW')
            OR UPPER(BTRIM(COALESCE(public.pay_bank_transfer_events.provider_state, ''))) LIKE 'CREATE_ERROR%'
          ))
      )
    ORDER BY COALESCE(public.pay_bank_transfer_events.event_time_utc, public.pay_bank_transfer_events.received_at_utc, public.pay_bank_transfer_events.created_at_utc) DESC NULLS LAST,
             public.pay_bank_transfer_events.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', v_alert_kind,
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'execution_commit_state', UPPER(BTRIM(COALESCE(v_batch.execution_commit_state, 'NOT_SUBMITTED'))),
      'execution_commit_ref', NULLIF(BTRIM(COALESCE(v_batch.execution_commit_ref, '')), ''),
      'execution_committed_at_utc', v_execution_committed_at_utc_text,
      'last_status_checked_at_utc', v_last_status_checked_at_utc_text,
      'latest_transfer', v_latest_transfer,
      'latest_transfer_event', v_latest_transfer_event
    ));
  END IF;

  IF v_alert_kind IN ('PAYMENT_CORRECTION_FAILED', 'PAYMENT_CORRECTION_BLOCKED', 'PAYMENT_CORRECTION_AWAITING_APPROVAL') THEN
    IF v_source_kind = 'pay_bank_transfer_event' AND p_source_id IS NOT NULL THEN
      SELECT jsonb_strip_nulls(jsonb_build_object(
        'pay_bank_transfer_event_id', public.pay_bank_transfer_events.id::text,
        'pay_bank_transfer_id', CASE WHEN public.pay_bank_transfer_events.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_bank_transfer_events.pay_bank_transfer_id::text END,
        'provider_key', public.pay_bank_transfer_events.provider_key,
        'provider_event_id', public.pay_bank_transfer_events.provider_event_id,
        'provider_reference', public.pay_bank_transfer_events.provider_reference,
        'provider_state', public.pay_bank_transfer_events.provider_state,
        'normalised_state', public.pay_bank_transfer_events.normalised_state,
        'mapping_status', public.pay_bank_transfer_events.mapping_status,
        'movement_classification', public.pay_bank_transfer_events.movement_classification,
        'correction_disposition', public.pay_bank_transfer_events.correction_disposition,
        'event_source', public.pay_bank_transfer_events.event_source,
        'event_time_utc', CASE
          WHEN public.pay_bank_transfer_events.event_time_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.event_time_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'received_at_utc', CASE
          WHEN public.pay_bank_transfer_events.received_at_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.received_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END,
        'created_at_utc', CASE
          WHEN public.pay_bank_transfer_events.created_at_utc IS NULL THEN NULL
          ELSE TO_CHAR(public.pay_bank_transfer_events.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
        END
      ))
      INTO v_latest_transfer_event
      FROM public.pay_bank_transfer_events
      WHERE public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id
        AND public.pay_bank_transfer_events.id = p_source_id
      LIMIT 1;
    END IF;

    SELECT jsonb_strip_nulls(jsonb_build_object(
      'correction_request_id', public.pay_payment_correction_requests.id::text,
      'correction_kind', public.pay_payment_correction_requests.correction_kind,
      'status', public.pay_payment_correction_requests.status,
      'source_bank_event_id', CASE WHEN public.pay_payment_correction_requests.source_bank_event_id IS NULL THEN NULL ELSE public.pay_payment_correction_requests.source_bank_event_id::text END,
      'requested_at_utc', CASE
        WHEN public.pay_payment_correction_requests.requested_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.requested_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'updated_at_utc', CASE
        WHEN public.pay_payment_correction_requests.updated_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.updated_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'authorised_at_utc', CASE
        WHEN public.pay_payment_correction_requests.authorised_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.authorised_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'applied_at_utc', CASE
        WHEN public.pay_payment_correction_requests.applied_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.applied_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'cancelled_at_utc', CASE
        WHEN public.pay_payment_correction_requests.cancelled_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_requests.cancelled_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_correction_request
    FROM public.pay_payment_correction_requests
    WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_payment_correction_request'
        OR public.pay_payment_correction_requests.id = p_source_id
      )
      AND (
        (v_alert_kind = 'PAYMENT_CORRECTION_FAILED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('FAILED', 'FAILED_RETRYABLE', 'FAILED_FINAL'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_BLOCKED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_AWAITING_APPROVAL'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_requests.status, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'PENDING_APPROVAL'))
      )
    ORDER BY COALESCE(public.pay_payment_correction_requests.updated_at_utc, public.pay_payment_correction_requests.requested_at_utc, public.pay_payment_correction_requests.created_at_utc) DESC NULLS LAST,
             public.pay_payment_correction_requests.id DESC
    LIMIT 1;

    SELECT jsonb_strip_nulls(jsonb_build_object(
      'correction_work_item_id', public.pay_payment_correction_work_items.id::text,
      'correction_request_id', public.pay_payment_correction_work_items.correction_request_id::text,
      'pay_bank_transfer_id', CASE WHEN public.pay_payment_correction_work_items.pay_bank_transfer_id IS NULL THEN NULL ELSE public.pay_payment_correction_work_items.pay_bank_transfer_id::text END,
      'work_kind', public.pay_payment_correction_work_items.work_kind,
      'status', public.pay_payment_correction_work_items.status,
      'attempt_count', public.pay_payment_correction_work_items.attempt_count,
      'last_error_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.pay_payment_correction_work_items.last_error, '')), '') IS NULL THEN NULL
        ELSE MD5(public.pay_payment_correction_work_items.last_error)
      END,
      'created_at_utc', CASE
        WHEN public.pay_payment_correction_work_items.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_work_items.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'processed_at_utc', CASE
        WHEN public.pay_payment_correction_work_items.processed_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.pay_payment_correction_work_items.processed_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_correction_work_item
    FROM public.pay_payment_correction_work_items
    WHERE public.pay_payment_correction_work_items.pay_batch_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'pay_payment_correction_work_item'
        OR public.pay_payment_correction_work_items.id = p_source_id
      )
      AND (
        (v_alert_kind = 'PAYMENT_CORRECTION_FAILED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('FAILED', 'FAILED_RETRYABLE', 'FAILED_FINAL'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_BLOCKED'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('BLOCKED', 'APPLIED_WITH_BLOCKERS'))
        OR (v_alert_kind = 'PAYMENT_CORRECTION_AWAITING_APPROVAL'
          AND UPPER(BTRIM(COALESCE(public.pay_payment_correction_work_items.status, ''))) IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AWAITING_AUTHORIZATION', 'PENDING_APPROVAL'))
      )
    ORDER BY COALESCE(public.pay_payment_correction_work_items.processed_at_utc, public.pay_payment_correction_work_items.created_at_utc) DESC NULLS LAST,
             public.pay_payment_correction_work_items.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', v_alert_kind,
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'latest_correction_request', v_latest_correction_request,
      'latest_correction_work_item', v_latest_correction_work_item,
      'latest_transfer_event', v_latest_transfer_event
    ));
  END IF;


  IF v_alert_kind = 'PAYMENT_PROVIDER_SUBMIT_REVIEW' THEN
    IF v_source_kind = 'banking_pay_operation' AND p_source_id IS NOT NULL THEN
      v_provider_operation_id := p_source_id;
    ELSE
      v_provider_operation_id := NULL::uuid;
    END IF;

    v_provider_submit_diagnostic_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := p_pay_batch_id,
      p_operation_id := v_provider_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := NULL::uuid,
      p_counts_only := false
    );
    v_provider_submit_diagnostic := COALESCE(v_provider_submit_diagnostic_result->'provider_submit_diagnostic', '{}'::jsonb);
    v_provider_submission_status := UPPER(BTRIM(COALESCE(v_provider_submit_diagnostic_result->>'provider_submission_status', v_provider_submit_diagnostic->>'provider_submission_status', '')));
    v_review_reason_code := COALESCE(NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic_result->>'review_reason_code', v_provider_submit_diagnostic->>'review_reason_code', '')), ''), 'PAYMENT_PROVIDER_SUBMIT_REVIEW');

    v_provider_title := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Provider submission outcome unknown'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider response missing'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider response unusable'
      WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider acceptance evidence missing'
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider outcome needs review'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence present'
      ELSE 'Provider submission needs review'
    END;

    v_provider_description := CASE v_provider_submission_status
      WHEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Submit chunk became stale with no provider response, transfer event, rail transaction ID, or rail state.'
      WHEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'A provider request may have been sent, but no usable provider response was recorded.'
      WHEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Manual reconciliation is required before retry.'
      WHEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'Provider response/status was recorded, but no usable external provider transaction/reference was stored.'
      WHEN 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected the payment submission.'
      WHEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission failed before the provider payment request was sent.'
      WHEN 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists and retry is unsafe until reconciliation is complete.'
      ELSE 'Provider submission requires review before retry.'
    END;

    v_provider_action_label := COALESCE(NULLIF(BTRIM(v_provider_submit_diagnostic->>'recommended_action'), ''), 'Check Revolut/bank before retry. If no payment was made, record manual no-payment confirmation.');

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'alert_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'issue_kind', 'PAYMENT_PROVIDER_SUBMIT_REVIEW',
      'title', v_provider_title,
      'description', v_provider_description,
      'action_label', v_provider_action_label,
      'recommended_action', v_provider_action_label,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_review_reason_code,
      'manual_resolution_required', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'manual_resolution_required', v_provider_submit_diagnostic_result->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'safe_retry_available', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'safe_retry_available', v_provider_submit_diagnostic_result->>'safe_retry_available', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_response_present', lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_response_present', v_provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'pay_batch_id', v_batch.id::text,
      'operation_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'operation_id', CASE WHEN v_provider_operation_id IS NULL THEN NULL ELSE v_provider_operation_id::text END, '')), ''),
      'chunk_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'chunk_id', '')), ''),
      'transfer_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'transfer_id', '')), ''),
      'transfer_scope_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'transfer_scope_id', '')), ''),
      'auth_request_id', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'auth_request_id', '')), ''),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'rail_provider', v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'rail_env', v_batch.rail_env_snapshot, '')), ''),
      'provider_submit_diagnostic', v_provider_submit_diagnostic - 'provider_response_redacted' - 'provider_error_redacted' - 'raw_payload' - 'provider_raw_response' - 'raw_provider_response' - 'provider_raw_error' - 'raw_provider_error'
    ));
  END IF;

  IF v_alert_kind = 'REMITTANCE_SEND_FAILED' THEN
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'mail_outbox_id', public.mail_outbox.id::text,
      'type', public.mail_outbox.type,
      'status', public.mail_outbox.status::text,
      'reference', public.mail_outbox.reference,
      'recipient_kind', public.mail_outbox.recipient_kind,
      'recipient_id', CASE WHEN public.mail_outbox.recipient_id IS NULL THEN NULL ELSE public.mail_outbox.recipient_id::text END,
      'last_error_hash', CASE
        WHEN NULLIF(BTRIM(COALESCE(public.mail_outbox.last_error, '')), '') IS NULL THEN NULL
        ELSE MD5(public.mail_outbox.last_error)
      END,
      'created_at_utc', CASE
        WHEN public.mail_outbox.created_at_utc IS NULL THEN NULL
        ELSE TO_CHAR(public.mail_outbox.created_at_utc AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END,
      'failed_at', CASE
        WHEN public.mail_outbox.failed_at IS NULL THEN NULL
        ELSE TO_CHAR(public.mail_outbox.failed_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
      END
    ))
    INTO v_latest_remittance_failure
    FROM public.mail_outbox
    WHERE public.mail_outbox.context_kind = 'pay_batches'
      AND public.mail_outbox.context_id = p_pay_batch_id
      AND (
        v_source_kind IS DISTINCT FROM 'mail_outbox'
        OR public.mail_outbox.id = p_source_id
      )
      AND UPPER(BTRIM(COALESCE(public.mail_outbox.type, ''))) = 'REMITTANCE'
      AND (
        UPPER(BTRIM(COALESCE(public.mail_outbox.status::text, ''))) = 'FAILED'
        OR public.mail_outbox.failed_at IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(public.mail_outbox.last_error, '')), '') IS NOT NULL
      )
    ORDER BY COALESCE(public.mail_outbox.failed_at, public.mail_outbox.created_at_utc) DESC NULLS LAST,
             public.mail_outbox.id DESC
    LIMIT 1;

    RETURN jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_id', v_batch.id::text,
      'source_kind', v_source_kind,
      'source_id', CASE WHEN p_source_id IS NULL THEN NULL ELSE p_source_id::text END,
      'issue_kind', 'REMITTANCE_SEND_FAILED',
      'batch_status', UPPER(BTRIM(COALESCE(v_batch.status, ''))),
      'rail_provider', NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''),
      'rail_env', NULLIF(BTRIM(COALESCE(v_batch.rail_env_snapshot, '')), ''),
      'latest_remittance_failure', v_latest_remittance_failure
    ));
  END IF;

  RAISE EXCEPTION 'BANKING_ALERT_PAYLOAD_KIND_NOT_SUPPORTED'
    USING ERRCODE = 'P0001',
          DETAIL = jsonb_build_object(
            'code', 'BANKING_ALERT_PAYLOAD_KIND_NOT_SUPPORTED',
            'alert_kind', v_alert_kind,
            'pay_batch_id', p_pay_batch_id::text
          )::text;
END;
$function$;




DROP FUNCTION IF EXISTS public.pay_batch_submission_evidence(uuid);
CREATE OR REPLACE FUNCTION public.pay_batch_submission_evidence(
  p_pay_batch_id uuid,
  p_counts_only boolean DEFAULT false,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_chunk_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_transfer_count integer := 0;
  v_transfer_event_count integer := 0;
  v_provider_submitted_count integer := 0;
  v_local_only_count integer := 0;
  v_pending_count integer := 0;
  v_failed_count integer := 0;
  v_ambiguous_count integer := 0;
  v_committed_count integer := 0;
  v_attempted_but_unproven_count integer := 0;
  v_provider_attempt_without_external_id_count integer := 0;
  v_requires_provider_poll_count integer := 0;
  v_remaining_submit_attempt_required integer := 0;
  v_remaining_unattempted_submit_required integer := 0;
  v_remaining_evidence_unresolved_count integer := 0;
  v_remaining_provider_evidence_required integer := 0;
  v_remaining_provider_submission_required integer := 0;
  v_can_mark_submitted boolean := false;
  v_can_mark_committed boolean := false;
  v_has_rail_tx_id boolean := false;
  v_has_external_submission_evidence boolean := false;
  v_has_local_generated_request_identity boolean := false;
  v_transfer_statuses jsonb := '[]'::jsonb;
  v_transfer_rail_states jsonb := '[]'::jsonb;
  v_event_normalised_states jsonb := '[]'::jsonb;
  v_event_provider_states jsonb := '[]'::jsonb;
  v_evidence_sample jsonb := '[]'::jsonb;
  v_execution_classification_sample jsonb := '[]'::jsonb;
  v_active_operation_id uuid := NULL::uuid;
  v_active_operation_pay_channel_scope text := 'ALL';
  v_authorisation_ready_count integer := 0;
  v_authorisation_ready_transfer_count integer := 0;
  v_unattempted_submit_eligible_count integer := 0;
  v_provider_submit_ready_count integer := 0;
  v_provider_submit_ready_transfer_count integer := 0;
  v_authorised_without_provider_submission_count integer := 0;
  v_authorised_but_not_submit_ready_count integer := 0;
  v_provider_submit_blocked_count integer := 0;
  v_same_operation_authorised_auth_request_count integer := 0;
  v_provider_submit_phase_active boolean := false;
  v_authorisation_phase_active boolean := false;
  v_remaining_submit_attempt_required_phase text := 'NOT_PROVIDER_SUBMIT_PHASE';
  v_safe_local_cleanup_count integer := 0;
  v_provider_attempt_or_evidence_count integer := 0;
  v_provider_or_ambiguous_evidence_count integer := 0;
  v_cancellable_local_auth_request_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_same_operation_active_auth_request_count integer := 0;
  v_other_operation_active_auth_request_count integer := 0;
  v_auth_request_provider_risk_count integer := 0;
  v_auth_request_retry_blocker_count integer := 0;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_provider_submit_review_reason_code text := NULL::text;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_stale_unresolved_submit_chunk_count integer := 0;
  v_stale_empty_submit_chunk_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_accepted_count integer := 0;
  v_provider_submission_blocked_pre_call_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_provider_manual_resolution_required boolean := false;
  v_provider_safe_retry_available boolean := false;
  v_provider_recommended_action text := NULL::text;
  v_provider_submit_review_active boolean := false;
  v_provider_external_evidence_count integer := 0;
  v_provider_acceptance_evidence_present boolean := false;
  v_provider_boundary_crossed boolean := false;
  v_raw_batch_status text := NULL::text;
  v_raw_execution_commit_state text := NULL::text;
  v_local_finalisation_required boolean := false;
  v_safe_to_retry_provider boolean := false;
  v_safe_to_execute boolean := false;
  v_recommended_action_code text := NULL::text;
  v_local_prepared_not_sent_count integer := 0;
  v_scheduled_local_not_sent_count integer := 0;
  v_provider_submitted_pending_count integer := 0;
  v_provider_outage_retry_later_count integer := 0;
  v_provider_outcome_unknown_count integer := 0;
  v_provider_terminal_no_money_count integer := 0;
  v_provider_final_paid_count integer := 0;
  v_cancelled_before_bank_submission_count integer := 0;
  v_financials_rewound_count integer := 0;
  v_external_provider_evidence_count integer := 0;
  v_unknown_count integer := 0;
  v_provider_webhook_evidence_count integer := 0;
  v_provider_poll_evidence_count integer := 0;
  v_provider_failure_reason_groups_json jsonb := '[]'::jsonb;
  v_success_only_count integer := 0;
  v_alert_candidate_count integer := 0;
  v_all_local_not_sent boolean := false;
  v_has_external_provider_submission boolean := false;
  v_has_pending_provider_outcome boolean := false;
  v_has_unknown_provider_outcome boolean := false;
  v_has_terminal_no_money boolean := false;
  v_has_final_paid_or_settled boolean := false;
  v_whole_batch_cancel_safe boolean := false;
  v_partial_batch_cancel_state text := NULL::text;
  v_retry_same_batch_safe boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  SELECT upper(BTRIM(COALESCE(batch_check.status, ''))),
         upper(BTRIM(COALESCE(batch_check.execution_commit_state, 'NOT_SUBMITTED')))
  INTO v_raw_batch_status,
       v_raw_execution_commit_state
  FROM public.pay_batches AS batch_check
  WHERE batch_check.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_SUBMISSION_EVIDENCE_PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.id,
           upper(btrim(coalesce(
             nullif(btrim(coalesce(operation_row.input_json->>'pay_channel_scope', '')), ''),
             nullif(btrim(coalesce(operation_row.input_json->>'payChannelScope', '')), ''),
             nullif(btrim(coalesce(operation_row.config_json->>'pay_channel_scope', '')), ''),
             nullif(btrim(coalesce(operation_row.config_json->>'payChannelScope', '')), ''),
             'ALL'
           )))
    INTO v_active_operation_id,
         v_active_operation_pay_channel_scope
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
      AND operation_row.pay_batch_id = p_pay_batch_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_BATCH_SUBMISSION_EVIDENCE_OPERATION_NOT_FOUND_FOR_BATCH',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text
              )::text;
    END IF;
  ELSE
    SELECT operation_row.id,
         upper(btrim(coalesce(
           nullif(btrim(coalesce(operation_row.input_json->>'pay_channel_scope', '')), ''),
           nullif(btrim(coalesce(operation_row.input_json->>'payChannelScope', '')), ''),
           nullif(btrim(coalesce(operation_row.config_json->>'pay_channel_scope', '')), ''),
           nullif(btrim(coalesce(operation_row.config_json->>'payChannelScope', '')), ''),
           'ALL'
         )))
  INTO v_active_operation_id,
       v_active_operation_pay_channel_scope
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.pay_batch_id = p_pay_batch_id
    AND operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND operation_row.status NOT IN ('COMPLETE', 'FAILED', 'CANCELLED', 'CANCELED', 'REVIEW_REQUIRED')
  ORDER BY operation_row.updated_at_utc DESC NULLS LAST,
           operation_row.created_at_utc DESC NULLS LAST,
           operation_row.id DESC
  LIMIT 1;
  END IF;

  IF v_active_operation_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'LOANS', 'ALL', 'ANY', '*') THEN
    v_active_operation_pay_channel_scope := 'ALL';
  END IF;

  BEGIN
    v_provider_submit_diagnostic_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := p_pay_batch_id,
      p_operation_id := v_active_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := p_chunk_id,
      p_counts_only := true
    );
  EXCEPTION
    WHEN undefined_function THEN
      v_provider_submit_diagnostic_result := '{}'::jsonb;
    WHEN OTHERS THEN
      v_provider_submit_diagnostic_result := '{}'::jsonb;
  END;

  v_provider_submit_diagnostic := COALESCE(v_provider_submit_diagnostic_result->'provider_submit_diagnostic', '{}'::jsonb);
  v_provider_submission_status := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_submission_status', v_provider_submit_diagnostic_result->>'provider_submission_status', '')), '');
  v_provider_submit_review_reason_code := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'review_reason_code', v_provider_submit_diagnostic_result->>'review_reason_code', '')), '');
  v_provider_recommended_action := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'recommended_action', v_provider_submit_diagnostic_result->>'recommended_action', '')), '');
  v_provider_manual_resolution_required := lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'manual_resolution_required', v_provider_submit_diagnostic_result->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_safe_retry_available := lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'safe_retry_available', v_provider_submit_diagnostic_result->>'safe_retry_available', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
    v_provider_acceptance_evidence_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}', '') ~ '^[0-9]+$' THEN
    v_provider_response_present_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}', '') ~ '^[0-9]+$' THEN
    v_provider_request_sent_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_unknown_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
    v_stale_unresolved_submit_chunk_count := COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
    v_stale_empty_submit_chunk_count := (v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}')::integer;
  ELSE
    v_stale_empty_submit_chunk_count := COALESCE(v_stale_unresolved_submit_chunk_count, 0);
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
    v_unfinalised_submit_chunk_count := (v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_rejected_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_accepted_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_accepted_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_accepted_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_blocked_pre_call_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_blocked_pre_call_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_blocked_pre_call_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_malformed_response_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}')::integer;
  END IF;

  v_provider_submit_review_active := COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
    OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
    OR COALESCE(v_provider_submission_rejected_count, 0) > 0
    OR COALESCE(v_provider_submission_accepted_count, 0) > 0
    OR COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
    OR COALESCE(v_provider_submission_status, '') NOT IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED');

  IF COALESCE(p_counts_only, false) IS TRUE THEN
  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_provider_submit_ready,
      classification_row.provider_submit_unsafe_reason,
      classification_row.has_provider_submit_blocker,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.auth_request_id,
      classification_row.auth_request_state,
      classification_row.auth_request_operation_id,
      classification_row.has_same_operation_active_auth_request,
      classification_row.has_same_operation_authorised_auth_request,
      classification_row.has_other_operation_active_auth_request,
      classification_row.has_pending_authorisation_auth_request,
      classification_row.has_cancellable_local_auth_request,
      classification_row.has_non_cancellable_auth_request,
      classification_row.has_authorised_auth_without_provider_submission,
      classification_row.has_auth_request_provider_risk,
      classification_row.auth_request_unsafe_reason,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      COALESCE(v_active_operation_pay_channel_scope, 'ALL')::text,
      v_active_operation_id,
      true
    ) AS classification_row
  )
  SELECT
    count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('PROVIDER_SUBMITTED_PENDING','PROVIDER_OUTCOME_UNKNOWN','PROVIDER_FAILED_NO_MONEY','PROVIDER_CANCELLED_NO_MONEY','PAID_OR_SETTLED'))::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('LOCAL_PREPARED_NOT_SENT','SCHEDULED_LOCAL_NOT_SENT'))::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification = 'PROVIDER_SUBMITTED_PENDING')::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('PROVIDER_FAILED_NO_MONEY','PROVIDER_CANCELLED_NO_MONEY') OR classified_rows.is_failed_or_blocked IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification = 'PROVIDER_OUTCOME_UNKNOWN' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_rows.evidence_classification = 'PROVIDER_OUTCOME_UNKNOWN'
         OR classified_rows.has_ambiguous_external_evidence IS TRUE
         OR classified_rows.has_provider_attempt_without_external_id IS TRUE
    )::integer,
    count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer,
    bool_or(
      EXISTS (
        SELECT 1
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
          AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
      )
    ),
    bool_or(classified_rows.has_local_prepare_identity IS TRUE),
    bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE),
    count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_provider_submit_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_provider_submit_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_authorised_auth_without_provider_submission IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_authorised_auth_without_provider_submission IS TRUE AND classified_rows.is_provider_submit_ready IS NOT TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_provider_submit_blocker IS TRUE)::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_same_operation_authorised_auth_request IS TRUE
    )::integer,
    count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_rows.has_provider_submission_evidence IS TRUE
         OR classified_rows.has_provider_event_evidence IS TRUE
         OR classified_rows.has_provider_attempt_without_external_id IS TRUE
    )::integer,
    count(*) FILTER (
      WHERE classified_rows.has_provider_submission_evidence IS TRUE
         OR classified_rows.has_provider_event_evidence IS TRUE
         OR classified_rows.has_ambiguous_external_evidence IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_cancellable_local_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_non_cancellable_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_same_operation_active_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_other_operation_active_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_auth_request_provider_risk IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND (
          classified_rows.has_non_cancellable_auth_request IS TRUE
          OR classified_rows.has_auth_request_provider_risk IS TRUE
          OR classified_rows.has_other_operation_active_auth_request IS TRUE
        )
    )::integer
  INTO
    v_transfer_count,
    v_provider_submitted_count,
    v_local_only_count,
    v_pending_count,
    v_failed_count,
    v_ambiguous_count,
    v_attempted_but_unproven_count,
    v_provider_attempt_without_external_id_count,
    v_requires_provider_poll_count,
    v_committed_count,
    v_has_rail_tx_id,
    v_has_local_generated_request_identity,
    v_has_external_submission_evidence,
    v_authorisation_ready_count,
    v_authorisation_ready_transfer_count,
    v_unattempted_submit_eligible_count,
    v_provider_submit_ready_count,
    v_provider_submit_ready_transfer_count,
    v_authorised_without_provider_submission_count,
    v_authorised_but_not_submit_ready_count,
    v_provider_submit_blocked_count,
    v_same_operation_authorised_auth_request_count,
    v_safe_local_cleanup_count,
    v_provider_attempt_or_evidence_count,
    v_provider_or_ambiguous_evidence_count,
    v_cancellable_local_auth_request_count,
    v_non_cancellable_auth_request_count,
    v_same_operation_active_auth_request_count,
    v_other_operation_active_auth_request_count,
    v_auth_request_provider_risk_count,
    v_auth_request_retry_blocker_count
  FROM classified_rows AS classified_rows;

  v_provider_submitted_count := GREATEST(COALESCE(v_provider_submitted_count, 0), COALESCE(v_provider_acceptance_evidence_count, 0));
  v_provider_attempt_or_evidence_count := COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0);
  v_attempted_but_unproven_count := GREATEST(COALESCE(v_attempted_but_unproven_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_provider_attempt_without_external_id_count := GREATEST(COALESCE(v_provider_attempt_without_external_id_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_ambiguous_count := GREATEST(
    COALESCE(v_ambiguous_count, 0),
    COALESCE(v_provider_submission_unknown_count, 0)
      + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
      + COALESCE(v_provider_submission_malformed_response_count, 0)
  );
  v_requires_provider_poll_count := GREATEST(COALESCE(v_requires_provider_poll_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_provider_or_ambiguous_evidence_count := COALESCE(v_provider_acceptance_evidence_count, 0)
    + COALESCE(v_provider_response_present_count, 0)
    + COALESCE(v_provider_submission_unknown_count, 0)
    + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
    + COALESCE(v_provider_submission_malformed_response_count, 0);
  v_has_external_submission_evidence := COALESCE(v_provider_acceptance_evidence_count, 0) > 0;
  v_has_rail_tx_id := COALESCE(v_has_rail_tx_id, false) OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0;

  SELECT count(*)::integer
  INTO v_transfer_event_count
  FROM public.pay_bank_transfer_events AS event_row
  WHERE event_row.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.provider_event_transport, event_row.event_source, ''))) IN ('PROVIDER_WEBHOOK','WEBHOOK'))::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.provider_event_transport, event_row.event_source, ''))) IN ('PROVIDER_POLL','POLL'))::integer,
    COALESCE(jsonb_agg(DISTINCT to_jsonb(event_row.provider_failure_reason_group) ORDER BY to_jsonb(event_row.provider_failure_reason_group)) FILTER (WHERE event_row.provider_failure_reason_group IS NOT NULL), '[]'::jsonb),
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.normalised_state, event_row.provider_state, ''))) IN ('COMPLETED','PAID','SETTLED','SUCCESS','SUCCEEDED'))::integer,
    COUNT(*) FILTER (
      WHERE event_row.provider_failure_reason_group IS NOT NULL
         OR UPPER(BTRIM(COALESCE(event_row.normalised_state, event_row.provider_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','UNKNOWN')
         OR UPPER(BTRIM(COALESCE(event_row.correction_disposition, ''))) IN ('ACTION_REQUIRED','AMBIGUOUS','BLOCKED','FAILED','AUTO_PROCESSING')
    )::integer
  INTO
    v_provider_webhook_evidence_count,
    v_provider_poll_evidence_count,
    v_provider_failure_reason_groups_json,
    v_success_only_count,
    v_alert_candidate_count
  FROM public.pay_bank_transfer_events AS event_row
  WHERE event_row.pay_batch_id = p_pay_batch_id;

  WITH transfer_lifecycle AS (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      UPPER(BTRIM(COALESCE(transfer_row.status, ''))) AS transfer_status_upper,
      UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS rail_state_upper,
      COALESCE(money_classification.cash_state, 'UNKNOWN') AS cash_state,
      COALESCE(money_classification.is_final_money_moved, false) AS is_final_money_moved,
      COALESCE(money_classification.is_terminal_no_money, false) AS is_terminal_no_money,
      COALESCE(money_classification.is_pending_non_final, false) AS is_pending_non_final,
      (
        NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_external_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS provider_event
          WHERE provider_event.pay_bank_transfer_id = transfer_row.id
            AND UPPER(BTRIM(COALESCE(provider_event.event_source, ''))) IN (
              'PROVIDER_RESPONSE',
              'PROVIDER_POLL',
              'PROVIDER_WEBHOOK',
              'WEBHOOK',
              'POLL',
              'RAIL_PROVIDER',
              'PROVIDER',
              'PROVIDER_SETTLEMENT'
            )
        )
      ) AS has_external_provider_signal,
      (
        LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true','t','1','yes','y','on')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN (
          'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
          'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
          'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
          'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
        )
      ) AS has_provider_unknown_signal
    FROM public.pay_bank_transfers AS transfer_row
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      p_transfer_status := transfer_row.status,
      p_rail_state := transfer_row.rail_state,
      p_event_payload_json := COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      p_provider_meta_json := COALESCE(transfer_row.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb)
    ) AS money_classification ON TRUE
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  ),
  lifecycle_counts AS (
    SELECT
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS NOT TRUE
          AND transfer_lifecycle.transfer_status_upper NOT IN ('CANCELLED','CANCELED')
          AND transfer_lifecycle.rail_state_upper NOT IN ('CANCELLED','CANCELED')
          AND transfer_lifecycle.is_final_money_moved IS NOT TRUE
          AND transfer_lifecycle.is_terminal_no_money IS NOT TRUE
      )::integer AS local_not_sent_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS NOT TRUE
          AND (
            transfer_lifecycle.transfer_status_upper IN ('CANCELLED','CANCELED')
            OR transfer_lifecycle.rail_state_upper IN ('CANCELLED','CANCELED')
          )
      )::integer AS cancelled_before_bank_submission_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_pending_non_final IS TRUE
      )::integer AS provider_submitted_pending_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_terminal_no_money IS TRUE
      )::integer AS provider_terminal_no_money_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_final_money_moved IS TRUE
      )::integer AS provider_final_paid_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
      )::integer AS external_provider_evidence_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_provider_unknown_signal IS TRUE
          OR (
            transfer_lifecycle.has_external_provider_signal IS TRUE
            AND transfer_lifecycle.is_pending_non_final IS NOT TRUE
            AND transfer_lifecycle.is_terminal_no_money IS NOT TRUE
            AND transfer_lifecycle.is_final_money_moved IS NOT TRUE
          )
      )::integer AS provider_outcome_unknown_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.cash_state = 'UNKNOWN'
      )::integer AS unknown_count
    FROM transfer_lifecycle
  )
  SELECT
    CASE WHEN COALESCE(v_raw_batch_status, '') = 'SCHEDULED' THEN 0 ELSE COALESCE(lifecycle_counts.local_not_sent_count, 0) END,
    CASE WHEN COALESCE(v_raw_batch_status, '') = 'SCHEDULED' THEN COALESCE(lifecycle_counts.local_not_sent_count, 0) ELSE 0 END,
    COALESCE(lifecycle_counts.provider_submitted_pending_count, 0),
    CASE
      WHEN COALESCE(v_provider_safe_retry_available, false) IS TRUE
        AND COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
        THEN COALESCE(v_provider_submission_blocked_pre_call_count, 0)
      ELSE 0
    END,
    GREATEST(COALESCE(lifecycle_counts.provider_outcome_unknown_count, 0), COALESCE(v_provider_submission_unknown_count, 0), COALESCE(v_stale_unresolved_submit_chunk_count, 0), COALESCE(v_provider_submission_malformed_response_count, 0)),
    GREATEST(COALESCE(lifecycle_counts.provider_terminal_no_money_count, 0), COALESCE(v_provider_submission_rejected_count, 0)),
    COALESCE(lifecycle_counts.provider_final_paid_count, 0),
    COALESCE(lifecycle_counts.cancelled_before_bank_submission_count, 0),
    COALESCE(lifecycle_counts.external_provider_evidence_count, 0),
    COALESCE(lifecycle_counts.unknown_count, 0)
  INTO
    v_local_prepared_not_sent_count,
    v_scheduled_local_not_sent_count,
    v_provider_submitted_pending_count,
    v_provider_outage_retry_later_count,
    v_provider_outcome_unknown_count,
    v_provider_terminal_no_money_count,
    v_provider_final_paid_count,
    v_cancelled_before_bank_submission_count,
    v_external_provider_evidence_count,
    v_unknown_count
  FROM lifecycle_counts;

  SELECT COUNT(*)::integer
  INTO v_financials_rewound_count
  FROM public.pay_payment_correction_work_items AS rewind_work_item
  JOIN public.pay_payment_correction_requests AS rewind_request
    ON rewind_request.id = rewind_work_item.correction_request_id
  WHERE rewind_request.pay_batch_id = p_pay_batch_id
    AND UPPER(BTRIM(COALESCE(rewind_request.correction_kind, ''))) IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
    AND UPPER(BTRIM(COALESCE(rewind_work_item.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED');

  v_all_local_not_sent := COALESCE(v_transfer_count, 0) > 0
    AND COALESCE(v_external_provider_evidence_count, 0) = 0
    AND COALESCE(v_provider_submitted_pending_count, 0) = 0
    AND COALESCE(v_provider_outcome_unknown_count, 0) = 0
    AND COALESCE(v_provider_terminal_no_money_count, 0) = 0
    AND COALESCE(v_provider_final_paid_count, 0) = 0
    AND (COALESCE(v_local_prepared_not_sent_count, 0) + COALESCE(v_scheduled_local_not_sent_count, 0) + COALESCE(v_cancelled_before_bank_submission_count, 0)) = COALESCE(v_transfer_count, 0);

  v_has_external_provider_submission := COALESCE(v_external_provider_evidence_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0;
  v_has_pending_provider_outcome := COALESCE(v_provider_submitted_pending_count, 0) > 0;
  v_has_unknown_provider_outcome := COALESCE(v_provider_outcome_unknown_count, 0) > 0;
  v_has_terminal_no_money := COALESCE(v_provider_terminal_no_money_count, 0) > 0;
  v_has_final_paid_or_settled := COALESCE(v_provider_final_paid_count, 0) > 0;

  v_provider_submit_phase_active := (
    COALESCE(v_same_operation_authorised_auth_request_count, 0) > 0
    OR COALESCE(v_provider_submit_ready_count, 0) > 0
    OR COALESCE(v_authorised_without_provider_submission_count, 0) > 0
    OR COALESCE(v_authorised_but_not_submit_ready_count, 0) > 0
  );
  v_authorisation_phase_active := (
    COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE
    AND COALESCE(v_authorisation_ready_count, 0) > 0
  );

  v_whole_batch_cancel_safe := COALESCE(v_transfer_count, 0) > 0
    AND COALESCE(v_has_external_provider_submission, false) IS NOT TRUE
    AND COALESCE(v_has_pending_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_unknown_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_terminal_no_money, false) IS NOT TRUE
    AND COALESCE(v_has_final_paid_or_settled, false) IS NOT TRUE
    AND COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE;

  v_partial_batch_cancel_state := CASE
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_cancelled_before_bank_submission_count, 0) < COALESCE(v_transfer_count, 0)
      THEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION'
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_cancelled_before_bank_submission_count, 0) >= COALESCE(v_transfer_count, 0)
      THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
    ELSE NULL::text
  END;

  v_retry_same_batch_safe := COALESCE(v_provider_outage_retry_later_count, 0) > 0
    AND COALESCE(v_has_external_provider_submission, false) IS NOT TRUE
    AND COALESCE(v_has_unknown_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_terminal_no_money, false) IS NOT TRUE
    AND COALESCE(v_has_final_paid_or_settled, false) IS NOT TRUE;

  v_provider_submit_phase_active := (
    COALESCE(v_same_operation_authorised_auth_request_count, 0) > 0
    OR COALESCE(v_provider_submit_ready_count, 0) > 0
    OR COALESCE(v_authorised_without_provider_submission_count, 0) > 0
    OR COALESCE(v_authorised_but_not_submit_ready_count, 0) > 0
  );
  v_authorisation_phase_active := (
    COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE
    AND COALESCE(v_authorisation_ready_count, 0) > 0
  );

  IF COALESCE(v_provider_submit_phase_active, false) IS TRUE THEN
    v_remaining_unattempted_submit_required := coalesce(v_provider_submit_ready_count, 0);
    v_remaining_submit_attempt_required := v_remaining_unattempted_submit_required;
    v_remaining_provider_submission_required := v_remaining_unattempted_submit_required;
    v_remaining_submit_attempt_required_phase := 'PROVIDER_SUBMIT';
  ELSE
    v_remaining_unattempted_submit_required := 0;
    v_remaining_submit_attempt_required := 0;
    v_remaining_provider_submission_required := 0;
    v_remaining_submit_attempt_required_phase := CASE
      WHEN COALESCE(v_authorisation_phase_active, false) THEN 'AUTHORISATION'
      ELSE 'NOT_PROVIDER_SUBMIT_PHASE'
    END;
  END IF;

  v_remaining_evidence_unresolved_count := coalesce(v_pending_count, 0) + coalesce(v_local_only_count, 0);
  v_remaining_provider_evidence_required := coalesce(v_remaining_evidence_unresolved_count, 0)
    + coalesce(v_ambiguous_count, 0)
    + coalesce(v_attempted_but_unproven_count, 0);

  v_can_mark_submitted := coalesce(v_transfer_count, 0) > 0
    AND coalesce(v_provider_submitted_count, 0) = coalesce(v_transfer_count, 0)
    AND coalesce(v_failed_count, 0) = 0
    AND coalesce(v_ambiguous_count, 0) = 0
    AND coalesce(v_local_only_count, 0) = 0
    AND coalesce(v_pending_count, 0) = 0
    AND coalesce(v_attempted_but_unproven_count, 0) = 0;
  v_can_mark_committed := v_can_mark_submitted
    AND coalesce(v_committed_count, 0) = coalesce(v_transfer_count, 0);

  v_provider_external_evidence_count := GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(v_provider_submitted_count, 0), COALESCE(v_provider_submission_accepted_count, 0));
  v_provider_acceptance_evidence_present := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_submitted_count, 0) > 0
    OR COALESCE(v_provider_submission_accepted_count, 0) > 0
    OR upper(BTRIM(COALESCE(v_provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_ACCEPTED';
  v_provider_boundary_crossed := COALESCE(v_provider_acceptance_evidence_present, false) IS TRUE
    AND COALESCE(v_provider_external_evidence_count, 0) > 0
    AND COALESCE(v_failed_count, 0) = 0
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_provider_submission_rejected_count, 0) = 0;
  v_local_finalisation_required := COALESCE(v_provider_acceptance_evidence_present, false) IS TRUE
    AND (
      COALESCE(v_raw_batch_status, '') = 'DRAFT'
      OR COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') = 'NOT_SUBMITTED'
    );
  v_safe_to_retry_provider := COALESCE(v_provider_acceptance_evidence_present, false) IS NOT TRUE
    AND COALESCE(v_provider_boundary_crossed, false) IS NOT TRUE
    AND COALESCE(v_provider_manual_resolution_required, false) IS NOT TRUE
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_attempted_but_unproven_count, 0) = 0
    AND COALESCE(v_provider_attempt_without_external_id_count, 0) = 0
    AND COALESCE(v_provider_submission_rejected_count, 0) = 0
    AND COALESCE(v_failed_count, 0) = 0;
  v_safe_to_execute := COALESCE(v_provider_acceptance_evidence_present, false) IS NOT TRUE
    AND COALESCE(v_provider_boundary_crossed, false) IS NOT TRUE
    AND COALESCE(v_local_finalisation_required, false) IS NOT TRUE
    AND COALESCE(v_provider_manual_resolution_required, false) IS NOT TRUE
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_attempted_but_unproven_count, 0) = 0
    AND COALESCE(v_provider_attempt_without_external_id_count, 0) = 0
    AND COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') NOT IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED')
    AND COALESCE(v_raw_batch_status, '') NOT IN ('WAITING_BANK_CONFIRM', 'SETTLED', 'CANCELLED', 'CANCELED', 'FAILED', 'BLOCKED_FUNDS');
  v_recommended_action_code := CASE
    WHEN COALESCE(v_local_finalisation_required, false) IS TRUE THEN 'PROVIDER_EVIDENCE_RECONCILIATION_REQUIRED'
    WHEN COALESCE(v_provider_manual_resolution_required, false) IS TRUE OR COALESCE(v_ambiguous_count, 0) > 0 OR COALESCE(v_attempted_but_unproven_count, 0) > 0 THEN 'PROVIDER_OUTCOME_REVIEW_REQUIRED'
    WHEN COALESCE(v_failed_count, 0) > 0 OR COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN 'PROVIDER_REJECTION_OR_PAYMENT_FAILURE_REVIEW_REQUIRED'
    WHEN COALESCE(v_provider_boundary_crossed, false) IS TRUE THEN 'PENDING_BANK_CONFIRMATION'
    WHEN COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN 'ALREADY_SUBMITTED'
    WHEN COALESCE(v_safe_to_execute, false) IS TRUE THEN 'EXECUTE_AVAILABLE'
    ELSE COALESCE(NULLIF(v_provider_recommended_action, ''), 'NO_ACTION_REQUIRED')
  END;

  RETURN (
  jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'counts_only', true,
    'transfer_count', coalesce(v_transfer_count, 0),
    'transfer_event_count', coalesce(v_transfer_event_count, 0),
    'has_transfer_events', coalesce(v_transfer_event_count, 0) > 0,
    'provider_submitted_count', coalesce(v_provider_submitted_count, 0),
    'provider_evidence_present_count', coalesce(v_provider_acceptance_evidence_count, 0),
    'local_idempotency_only_count', coalesce(v_local_only_count, 0),
    'local_only_count', coalesce(v_local_only_count, 0),
    'local_only_evidence_count', coalesce(v_local_only_count, 0),
    'pending_count', coalesce(v_pending_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'ambiguous_count', coalesce(v_ambiguous_count, 0),
    'attempted_but_unproven_count', coalesce(v_attempted_but_unproven_count, 0),
    'provider_attempt_without_external_id_count', coalesce(v_provider_attempt_without_external_id_count, 0),
    'requires_provider_poll_count', coalesce(v_requires_provider_poll_count, 0),
    'authorisation_ready_count', coalesce(v_authorisation_ready_count, 0),
    'authorisation_ready_transfer_count', coalesce(v_authorisation_ready_transfer_count, 0),
    'unattempted_submit_eligible_count', coalesce(v_unattempted_submit_eligible_count, 0),
    'provider_submit_ready_count', coalesce(v_provider_submit_ready_count, 0),
    'provider_submit_ready_transfer_count', coalesce(v_provider_submit_ready_transfer_count, 0),
    'authorised_without_provider_submission_count', coalesce(v_authorised_without_provider_submission_count, 0),
    'authorised_but_not_submit_ready_count', coalesce(v_authorised_but_not_submit_ready_count, 0),
    'provider_submit_blocked_count', coalesce(v_provider_submit_blocked_count, 0),
    'same_operation_authorised_auth_request_count', coalesce(v_same_operation_authorised_auth_request_count, 0),
    'provider_submit_phase_active', coalesce(v_provider_submit_phase_active, false),
    'authorisation_phase_active', coalesce(v_authorisation_phase_active, false),
    'safe_local_cleanup_count', coalesce(v_safe_local_cleanup_count, 0),
    'provider_attempt_or_evidence_count', coalesce(v_provider_attempt_or_evidence_count, 0),
    'provider_or_ambiguous_evidence_count', coalesce(v_provider_or_ambiguous_evidence_count, 0),
    'cancellable_local_auth_request_count', coalesce(v_cancellable_local_auth_request_count, 0)
  )
  ||
  jsonb_build_object(
    'non_cancellable_auth_request_count', coalesce(v_non_cancellable_auth_request_count, 0),
    'same_operation_active_auth_request_count', coalesce(v_same_operation_active_auth_request_count, 0),
    'other_operation_active_auth_request_count', coalesce(v_other_operation_active_auth_request_count, 0),
    'auth_request_provider_risk_count', coalesce(v_auth_request_provider_risk_count, 0),
    'auth_request_retry_blocker_count', coalesce(v_auth_request_retry_blocker_count, 0),
    'remaining_submit_attempt_required', coalesce(v_remaining_submit_attempt_required, 0),
    'remaining_unattempted_submit_required', coalesce(v_remaining_unattempted_submit_required, 0),
    'remaining_evidence_unresolved_count', coalesce(v_remaining_evidence_unresolved_count, 0),
    'remaining_submit_attempt_required_definition', 'phase_dependent_provider_submit_ready_count',
    'remaining_submit_attempt_required_phase', v_remaining_submit_attempt_required_phase,
    'remaining_provider_evidence_required', coalesce(v_remaining_provider_evidence_required, 0),
    'remaining_provider_submission_required', coalesce(v_remaining_provider_submission_required, 0),
    'submission_count_semantics', jsonb_build_object(
        'remaining_submit_attempt_required', 'phase-dependent count: provider-submit-ready authorised transfers only when provider-submit phase is active',
        'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
        'pending_count', 'evidence-level pending classification, not authorisation or submit eligibility'
      ),
    'batch_can_be_marked_submitted', coalesce(v_can_mark_submitted, false),
    'can_mark_submitted', coalesce(v_can_mark_submitted, false),
    'can_mark_committed', coalesce(v_can_mark_committed, false),
    'has_rail_tx_id', coalesce(v_has_rail_tx_id, false),
    'has_local_generated_request_identity', coalesce(v_has_local_generated_request_identity, false),
    'has_external_submission_evidence', coalesce(v_has_external_submission_evidence, false),
    'no_submission_evidence', coalesce(v_has_external_submission_evidence, false) = false,
    'evidence_sample', '[]'::jsonb,
    'execution_classification_sample', '[]'::jsonb,
    'has_possible_provider_attempt_evidence', coalesce(v_has_external_submission_evidence, false) OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_provider_attempt_request_or_idempotency_reference', coalesce(v_provider_submitted_count, 0) > 0 OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_request_or_idempotency_reference', coalesce(v_local_only_count, 0) > 0 OR coalesce(v_provider_submitted_count, 0) > 0 OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_submitted_state', coalesce(v_provider_submitted_count, 0) > 0,
    'has_failed_or_rejected_provider_state', coalesce(v_failed_count, 0) > 0,
    'has_unknown_or_timeout_state', coalesce(v_ambiguous_count, 0) > 0,
    'provider_submit_diagnostic', CASE WHEN v_provider_submit_review_active THEN COALESCE(v_provider_submit_diagnostic, '{}'::jsonb) ELSE '{}'::jsonb END,
    'provider_submission_status', v_provider_submission_status,
    'review_reason_code', v_provider_submit_review_reason_code,
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
    'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
    'safe_retry_available', COALESCE(v_provider_safe_retry_available, false),
    'recommended_action', v_provider_recommended_action,
    'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
    'provider_acceptance_evidence_present', COALESCE(v_provider_acceptance_evidence_present, false),
    'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
    'local_finalisation_required', COALESCE(v_local_finalisation_required, false)
  )
  ||
  jsonb_build_object(
    'raw_batch_status', v_raw_batch_status,
    'raw_execution_commit_state', v_raw_execution_commit_state,
    'safe_to_retry_provider', COALESCE(v_safe_to_retry_provider, false),
    'safe_to_execute', COALESCE(v_safe_to_execute, false),
    'recommended_action_code', v_recommended_action_code,
    'requires_provider_poll', coalesce(v_requires_provider_poll_count, 0) > 0,
    'requires_review', COALESCE(v_provider_manual_resolution_required, false) OR coalesce(v_ambiguous_count, 0) > 0 OR (coalesce(v_attempted_but_unproven_count, 0) > 0 AND coalesce(v_requires_provider_poll_count, 0) = 0)
  )
  ||
  jsonb_build_object(
    'local_prepared_not_sent_count', COALESCE(v_local_prepared_not_sent_count, 0),
    'scheduled_local_not_sent_count', COALESCE(v_scheduled_local_not_sent_count, 0),
    'provider_submitted_pending_count', COALESCE(v_provider_submitted_pending_count, 0),
    'provider_outage_retry_later_count', COALESCE(v_provider_outage_retry_later_count, 0),
    'provider_outcome_unknown_count', COALESCE(v_provider_outcome_unknown_count, 0),
    'provider_terminal_no_money_count', COALESCE(v_provider_terminal_no_money_count, 0),
    'provider_final_paid_count', COALESCE(v_provider_final_paid_count, 0),
    'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
    'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
    'external_provider_evidence_count', COALESCE(v_external_provider_evidence_count, 0),
    'unknown_count', COALESCE(v_unknown_count, 0),
    'provider_webhook_evidence_count', COALESCE(v_provider_webhook_evidence_count, 0),
    'provider_poll_evidence_count', COALESCE(v_provider_poll_evidence_count, 0),
    'provider_failure_reason_groups_json', COALESCE(v_provider_failure_reason_groups_json, '[]'::jsonb),
    'success_only_count', COALESCE(v_success_only_count, 0),
    'alert_candidate_count', COALESCE(v_alert_candidate_count, 0),
    'all_local_not_sent' , COALESCE(v_all_local_not_sent, false),
    'has_external_provider_submission', COALESCE(v_has_external_provider_submission, false),
    'has_pending_provider_outcome', COALESCE(v_has_pending_provider_outcome, false),
    'has_unknown_provider_outcome', COALESCE(v_has_unknown_provider_outcome, false),
    'has_terminal_no_money', COALESCE(v_has_terminal_no_money, false),
    'has_final_paid_or_settled', COALESCE(v_has_final_paid_or_settled, false),
    'whole_batch_cancel_safe', COALESCE(v_whole_batch_cancel_safe, false),
    'partial_batch_cancel_state', v_partial_batch_cancel_state,
    'retry_same_batch_safe', COALESCE(v_retry_same_batch_safe, false)
  )
  );
  END IF;

  WITH classified_rows AS (
    SELECT
      classification_row.pay_bank_transfer_id,
      classification_row.pay_batch_id,
      classification_row.pay_channel,
      classification_row.transfer_group_key,
      classification_row.scope_id,
      classification_row.scope_operation_id,
      classification_row.scope_status,
      classification_row.scope_request_id,
      classification_row.status_upper,
      classification_row.rail_state_upper,
      classification_row.amount,
      classification_row.currency,
      classification_row.has_route_ready,
      classification_row.has_local_prepare_identity,
      classification_row.has_provider_submission_evidence,
      classification_row.has_provider_event_evidence,
      classification_row.has_provider_attempt_without_external_id,
      classification_row.has_operation_submit_attempt,
      classification_row.has_ambiguous_external_evidence,
      classification_row.is_failed_or_blocked,
      classification_row.is_terminal_or_completed,
      classification_row.evidence_classification,
      classification_row.is_authorisation_ready,
      classification_row.is_unattempted_submit_eligible,
      classification_row.is_provider_submit_ready,
      classification_row.provider_submit_unsafe_reason,
      classification_row.has_provider_submit_blocker,
      classification_row.is_safe_local_cleanup,
      classification_row.is_canonical_pending_status,
      classification_row.has_auth_prepared_scope,
      classification_row.has_different_operation_scope,
      classification_row.has_stale_auth_request_evidence,
      classification_row.auth_request_id,
      classification_row.auth_request_state,
      classification_row.auth_request_operation_id,
      classification_row.has_same_operation_active_auth_request,
      classification_row.has_same_operation_authorised_auth_request,
      classification_row.has_other_operation_active_auth_request,
      classification_row.has_pending_authorisation_auth_request,
      classification_row.has_cancellable_local_auth_request,
      classification_row.has_non_cancellable_auth_request,
      classification_row.has_authorised_auth_without_provider_submission,
      classification_row.has_auth_request_provider_risk,
      classification_row.auth_request_unsafe_reason,
      classification_row.unsafe_reason
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id,
      COALESCE(v_active_operation_pay_channel_scope, 'ALL')::text,
      v_active_operation_id,
      true
    ) AS classification_row
  ), classified_rows_with_sample AS (
    SELECT
      classified_rows.*,
      row_number() OVER (
        ORDER BY
          CASE
            WHEN classified_rows.evidence_classification IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'PROVIDER_SUBMITTED_PENDING') THEN 0
            ELSE 1
          END,
          classified_rows.pay_bank_transfer_id NULLS LAST,
          classified_rows.scope_id NULLS LAST
      ) AS evidence_sample_ordinality
    FROM classified_rows
  )
  SELECT
    count(*) FILTER (WHERE classified_rows.pay_bank_transfer_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('PROVIDER_SUBMITTED_PENDING','PROVIDER_OUTCOME_UNKNOWN','PROVIDER_FAILED_NO_MONEY','PROVIDER_CANCELLED_NO_MONEY','PAID_OR_SETTLED'))::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('LOCAL_PREPARED_NOT_SENT','SCHEDULED_LOCAL_NOT_SENT'))::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification = 'PROVIDER_SUBMITTED_PENDING')::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification IN ('PROVIDER_FAILED_NO_MONEY','PROVIDER_CANCELLED_NO_MONEY') OR classified_rows.is_failed_or_blocked IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.evidence_classification = 'PROVIDER_OUTCOME_UNKNOWN' OR classified_rows.has_ambiguous_external_evidence IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE
    )::integer,
    count(*) FILTER (WHERE classified_rows.has_provider_attempt_without_external_id IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_rows.evidence_classification = 'PROVIDER_OUTCOME_UNKNOWN'
         OR classified_rows.has_ambiguous_external_evidence IS TRUE
         OR classified_rows.has_provider_attempt_without_external_id IS TRUE
    )::integer,
    count(*) FILTER (WHERE classified_rows.is_terminal_or_completed IS TRUE)::integer,
    bool_or(
      EXISTS (
        SELECT 1
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.id = classified_rows.pay_bank_transfer_id
          AND nullif(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
      )
    ),
    bool_or(classified_rows.has_local_prepare_identity IS TRUE),
    bool_or(classified_rows.has_provider_submission_evidence IS TRUE OR classified_rows.has_provider_event_evidence IS TRUE),
    count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_authorisation_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_unattempted_submit_eligible IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_provider_submit_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.is_provider_submit_ready IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_authorised_auth_without_provider_submission IS TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_authorised_auth_without_provider_submission IS TRUE AND classified_rows.is_provider_submit_ready IS NOT TRUE)::integer,
    count(*) FILTER (WHERE classified_rows.has_provider_submit_blocker IS TRUE)::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_same_operation_authorised_auth_request IS TRUE
    )::integer,
    count(*) FILTER (WHERE classified_rows.is_safe_local_cleanup IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_rows.has_provider_submission_evidence IS TRUE
         OR classified_rows.has_provider_event_evidence IS TRUE
         OR classified_rows.has_provider_attempt_without_external_id IS TRUE
    )::integer,
    count(*) FILTER (
      WHERE classified_rows.has_provider_submission_evidence IS TRUE
         OR classified_rows.has_provider_event_evidence IS TRUE
         OR classified_rows.has_ambiguous_external_evidence IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_cancellable_local_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_non_cancellable_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_same_operation_active_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_other_operation_active_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND classified_rows.has_auth_request_provider_risk IS TRUE
    )::integer,
    count(DISTINCT classified_rows.auth_request_id) FILTER (
      WHERE classified_rows.auth_request_id IS NOT NULL
        AND (
          classified_rows.has_non_cancellable_auth_request IS TRUE
          OR classified_rows.has_auth_request_provider_risk IS TRUE
          OR classified_rows.has_other_operation_active_auth_request IS TRUE
        )
    )::integer,
    coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
        'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
        'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
        'pay_channel', classified_rows.pay_channel,
        'classification', classified_rows.evidence_classification,
        'status', classified_rows.status_upper,
        'rail_state', classified_rows.rail_state_upper,
        'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
        'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
        'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
        'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
        'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
        'is_authorisation_ready', classified_rows.is_authorisation_ready,
        'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
        'is_provider_submit_ready', classified_rows.is_provider_submit_ready,
        'provider_submit_unsafe_reason', classified_rows.provider_submit_unsafe_reason,
        'has_provider_submit_blocker', classified_rows.has_provider_submit_blocker,
        'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
        'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
        'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
        'has_different_operation_scope', classified_rows.has_different_operation_scope,
        'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
        'auth_request_id', CASE WHEN classified_rows.auth_request_id IS NULL THEN NULL ELSE classified_rows.auth_request_id::text END,
        'auth_request_state', classified_rows.auth_request_state,
        'auth_request_operation_id', CASE WHEN classified_rows.auth_request_operation_id IS NULL THEN NULL ELSE classified_rows.auth_request_operation_id::text END,
        'has_same_operation_active_auth_request', classified_rows.has_same_operation_active_auth_request,
        'has_same_operation_authorised_auth_request', classified_rows.has_same_operation_authorised_auth_request,
        'has_other_operation_active_auth_request', classified_rows.has_other_operation_active_auth_request,
        'has_pending_authorisation_auth_request', classified_rows.has_pending_authorisation_auth_request,
        'has_cancellable_local_auth_request', classified_rows.has_cancellable_local_auth_request,
        'has_non_cancellable_auth_request', classified_rows.has_non_cancellable_auth_request,
        'has_authorised_auth_without_provider_submission', classified_rows.has_authorised_auth_without_provider_submission,
        'has_auth_request_provider_risk', classified_rows.has_auth_request_provider_risk,
        'auth_request_unsafe_reason', classified_rows.auth_request_unsafe_reason,
        'unsafe_reason', classified_rows.unsafe_reason
      ))
      ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
    ) FILTER (
      WHERE classified_rows.evidence_sample_ordinality <= 50
        AND coalesce(p_counts_only, false) IS NOT TRUE
    ), '[]'::jsonb),
    coalesce(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'pay_bank_transfer_id', CASE WHEN classified_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE classified_rows.pay_bank_transfer_id::text END,
        'scope_id', CASE WHEN classified_rows.scope_id IS NULL THEN NULL ELSE classified_rows.scope_id::text END,
        'scope_operation_id', CASE WHEN classified_rows.scope_operation_id IS NULL THEN NULL ELSE classified_rows.scope_operation_id::text END,
        'pay_channel', classified_rows.pay_channel,
        'evidence_classification', classified_rows.evidence_classification,
        'status', classified_rows.status_upper,
        'rail_state', classified_rows.rail_state_upper,
        'has_route_ready', classified_rows.has_route_ready,
        'has_local_prepare_identity', classified_rows.has_local_prepare_identity,
        'has_provider_submission_evidence', classified_rows.has_provider_submission_evidence,
        'has_provider_event_evidence', classified_rows.has_provider_event_evidence,
        'has_provider_attempt_without_external_id', classified_rows.has_provider_attempt_without_external_id,
        'has_operation_submit_attempt', classified_rows.has_operation_submit_attempt,
        'has_ambiguous_external_evidence', classified_rows.has_ambiguous_external_evidence,
        'is_failed_or_blocked', classified_rows.is_failed_or_blocked,
        'is_terminal_or_completed', classified_rows.is_terminal_or_completed,
        'is_authorisation_ready', classified_rows.is_authorisation_ready,
        'is_unattempted_submit_eligible', classified_rows.is_unattempted_submit_eligible,
        'is_provider_submit_ready', classified_rows.is_provider_submit_ready,
        'provider_submit_unsafe_reason', classified_rows.provider_submit_unsafe_reason,
        'has_provider_submit_blocker', classified_rows.has_provider_submit_blocker,
        'is_safe_local_cleanup', classified_rows.is_safe_local_cleanup,
        'is_canonical_pending_status', classified_rows.is_canonical_pending_status,
        'has_auth_prepared_scope', classified_rows.has_auth_prepared_scope,
        'has_different_operation_scope', classified_rows.has_different_operation_scope,
        'has_stale_auth_request_evidence', classified_rows.has_stale_auth_request_evidence,
        'auth_request_id', CASE WHEN classified_rows.auth_request_id IS NULL THEN NULL ELSE classified_rows.auth_request_id::text END,
        'auth_request_state', classified_rows.auth_request_state,
        'auth_request_operation_id', CASE WHEN classified_rows.auth_request_operation_id IS NULL THEN NULL ELSE classified_rows.auth_request_operation_id::text END,
        'has_same_operation_active_auth_request', classified_rows.has_same_operation_active_auth_request,
        'has_same_operation_authorised_auth_request', classified_rows.has_same_operation_authorised_auth_request,
        'has_other_operation_active_auth_request', classified_rows.has_other_operation_active_auth_request,
        'has_pending_authorisation_auth_request', classified_rows.has_pending_authorisation_auth_request,
        'has_cancellable_local_auth_request', classified_rows.has_cancellable_local_auth_request,
        'has_non_cancellable_auth_request', classified_rows.has_non_cancellable_auth_request,
        'has_authorised_auth_without_provider_submission', classified_rows.has_authorised_auth_without_provider_submission,
        'has_auth_request_provider_risk', classified_rows.has_auth_request_provider_risk,
        'auth_request_unsafe_reason', classified_rows.auth_request_unsafe_reason,
        'unsafe_reason', classified_rows.unsafe_reason
      ))
      ORDER BY classified_rows.pay_bank_transfer_id NULLS LAST, classified_rows.scope_id NULLS LAST
    ) FILTER (
      WHERE classified_rows.evidence_sample_ordinality <= 50
        AND coalesce(p_counts_only, false) IS NOT TRUE
    ), '[]'::jsonb)
  INTO
    v_transfer_count,
    v_provider_submitted_count,
    v_local_only_count,
    v_pending_count,
    v_failed_count,
    v_ambiguous_count,
    v_attempted_but_unproven_count,
    v_provider_attempt_without_external_id_count,
    v_requires_provider_poll_count,
    v_committed_count,
    v_has_rail_tx_id,
    v_has_local_generated_request_identity,
    v_has_external_submission_evidence,
    v_authorisation_ready_count,
    v_authorisation_ready_transfer_count,
    v_unattempted_submit_eligible_count,
    v_provider_submit_ready_count,
    v_provider_submit_ready_transfer_count,
    v_authorised_without_provider_submission_count,
    v_authorised_but_not_submit_ready_count,
    v_provider_submit_blocked_count,
    v_same_operation_authorised_auth_request_count,
    v_safe_local_cleanup_count,
    v_provider_attempt_or_evidence_count,
    v_provider_or_ambiguous_evidence_count,
    v_cancellable_local_auth_request_count,
    v_non_cancellable_auth_request_count,
    v_same_operation_active_auth_request_count,
    v_other_operation_active_auth_request_count,
    v_auth_request_provider_risk_count,
    v_auth_request_retry_blocker_count,
    v_evidence_sample,
    v_execution_classification_sample
  FROM classified_rows_with_sample AS classified_rows;

  v_provider_submitted_count := GREATEST(COALESCE(v_provider_submitted_count, 0), COALESCE(v_provider_acceptance_evidence_count, 0));
  v_provider_attempt_or_evidence_count := COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0);
  v_attempted_but_unproven_count := GREATEST(COALESCE(v_attempted_but_unproven_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_provider_attempt_without_external_id_count := GREATEST(COALESCE(v_provider_attempt_without_external_id_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_ambiguous_count := GREATEST(
    COALESCE(v_ambiguous_count, 0),
    COALESCE(v_provider_submission_unknown_count, 0)
      + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
      + COALESCE(v_provider_submission_malformed_response_count, 0)
  );
  v_requires_provider_poll_count := GREATEST(COALESCE(v_requires_provider_poll_count, 0), COALESCE(v_provider_submission_unknown_count, 0));
  v_provider_or_ambiguous_evidence_count := COALESCE(v_provider_acceptance_evidence_count, 0)
    + COALESCE(v_provider_response_present_count, 0)
    + COALESCE(v_provider_submission_unknown_count, 0)
    + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
    + COALESCE(v_provider_submission_malformed_response_count, 0);
  v_has_external_submission_evidence := COALESCE(v_provider_acceptance_evidence_count, 0) > 0;
  v_has_rail_tx_id := COALESCE(v_has_rail_tx_id, false) OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0;

  SELECT count(*)::integer
  INTO v_transfer_event_count
  FROM public.pay_bank_transfer_events AS event_row
  WHERE event_row.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.provider_event_transport, event_row.event_source, ''))) IN ('PROVIDER_WEBHOOK','WEBHOOK'))::integer,
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.provider_event_transport, event_row.event_source, ''))) IN ('PROVIDER_POLL','POLL'))::integer,
    COALESCE(jsonb_agg(DISTINCT to_jsonb(event_row.provider_failure_reason_group) ORDER BY to_jsonb(event_row.provider_failure_reason_group)) FILTER (WHERE event_row.provider_failure_reason_group IS NOT NULL), '[]'::jsonb),
    COUNT(*) FILTER (WHERE UPPER(BTRIM(COALESCE(event_row.normalised_state, event_row.provider_state, ''))) IN ('COMPLETED','PAID','SETTLED','SUCCESS','SUCCEEDED'))::integer,
    COUNT(*) FILTER (
      WHERE event_row.provider_failure_reason_group IS NOT NULL
         OR UPPER(BTRIM(COALESCE(event_row.normalised_state, event_row.provider_state, ''))) IN ('FAILED','DECLINED','REJECTED','CANCELLED','CANCELED','UNKNOWN')
         OR UPPER(BTRIM(COALESCE(event_row.correction_disposition, ''))) IN ('ACTION_REQUIRED','AMBIGUOUS','BLOCKED','FAILED','AUTO_PROCESSING')
    )::integer
  INTO
    v_provider_webhook_evidence_count,
    v_provider_poll_evidence_count,
    v_provider_failure_reason_groups_json,
    v_success_only_count,
    v_alert_candidate_count
  FROM public.pay_bank_transfer_events AS event_row
  WHERE event_row.pay_batch_id = p_pay_batch_id;

  WITH transfer_lifecycle AS (
    SELECT
      transfer_row.id AS pay_bank_transfer_id,
      UPPER(BTRIM(COALESCE(transfer_row.status, ''))) AS transfer_status_upper,
      UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) AS rail_state_upper,
      COALESCE(money_classification.cash_state, 'UNKNOWN') AS cash_state,
      COALESCE(money_classification.is_final_money_moved, false) AS is_final_money_moved,
      COALESCE(money_classification.is_terminal_no_money, false) AS is_terminal_no_money,
      COALESCE(money_classification.is_pending_non_final, false) AS is_pending_non_final,
      (
        NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_external_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true','t','1','yes','y','on')
        OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS provider_event
          WHERE provider_event.pay_bank_transfer_id = transfer_row.id
            AND UPPER(BTRIM(COALESCE(provider_event.event_source, ''))) IN (
              'PROVIDER_RESPONSE',
              'PROVIDER_POLL',
              'PROVIDER_WEBHOOK',
              'WEBHOOK',
              'POLL',
              'RAIL_PROVIDER',
              'PROVIDER',
              'PROVIDER_SETTLEMENT'
            )
        )
      ) AS has_external_provider_signal,
      (
        LOWER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true','t','1','yes','y','on')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN (
          'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
          'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
          'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
          'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
        )
      ) AS has_provider_unknown_signal
    FROM public.pay_bank_transfers AS transfer_row
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      p_transfer_status := transfer_row.status,
      p_rail_state := transfer_row.rail_state,
      p_event_payload_json := COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
      p_provider_meta_json := COALESCE(transfer_row.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb)
    ) AS money_classification ON TRUE
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
  ),
  lifecycle_counts AS (
    SELECT
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS NOT TRUE
          AND transfer_lifecycle.transfer_status_upper NOT IN ('CANCELLED','CANCELED')
          AND transfer_lifecycle.rail_state_upper NOT IN ('CANCELLED','CANCELED')
          AND transfer_lifecycle.is_final_money_moved IS NOT TRUE
          AND transfer_lifecycle.is_terminal_no_money IS NOT TRUE
      )::integer AS local_not_sent_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS NOT TRUE
          AND (
            transfer_lifecycle.transfer_status_upper IN ('CANCELLED','CANCELED')
            OR transfer_lifecycle.rail_state_upper IN ('CANCELLED','CANCELED')
          )
      )::integer AS cancelled_before_bank_submission_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_pending_non_final IS TRUE
      )::integer AS provider_submitted_pending_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_terminal_no_money IS TRUE
      )::integer AS provider_terminal_no_money_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
          AND transfer_lifecycle.is_final_money_moved IS TRUE
      )::integer AS provider_final_paid_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_external_provider_signal IS TRUE
      )::integer AS external_provider_evidence_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.has_provider_unknown_signal IS TRUE
          OR (
            transfer_lifecycle.has_external_provider_signal IS TRUE
            AND transfer_lifecycle.is_pending_non_final IS NOT TRUE
            AND transfer_lifecycle.is_terminal_no_money IS NOT TRUE
            AND transfer_lifecycle.is_final_money_moved IS NOT TRUE
          )
      )::integer AS provider_outcome_unknown_count,
      COUNT(*) FILTER (
        WHERE transfer_lifecycle.cash_state = 'UNKNOWN'
      )::integer AS unknown_count
    FROM transfer_lifecycle
  )
  SELECT
    CASE WHEN COALESCE(v_raw_batch_status, '') = 'SCHEDULED' THEN 0 ELSE COALESCE(lifecycle_counts.local_not_sent_count, 0) END,
    CASE WHEN COALESCE(v_raw_batch_status, '') = 'SCHEDULED' THEN COALESCE(lifecycle_counts.local_not_sent_count, 0) ELSE 0 END,
    COALESCE(lifecycle_counts.provider_submitted_pending_count, 0),
    CASE
      WHEN COALESCE(v_provider_safe_retry_available, false) IS TRUE
        AND COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
        THEN COALESCE(v_provider_submission_blocked_pre_call_count, 0)
      ELSE 0
    END,
    GREATEST(COALESCE(lifecycle_counts.provider_outcome_unknown_count, 0), COALESCE(v_provider_submission_unknown_count, 0), COALESCE(v_stale_unresolved_submit_chunk_count, 0), COALESCE(v_provider_submission_malformed_response_count, 0)),
    GREATEST(COALESCE(lifecycle_counts.provider_terminal_no_money_count, 0), COALESCE(v_provider_submission_rejected_count, 0)),
    COALESCE(lifecycle_counts.provider_final_paid_count, 0),
    COALESCE(lifecycle_counts.cancelled_before_bank_submission_count, 0),
    COALESCE(lifecycle_counts.external_provider_evidence_count, 0),
    COALESCE(lifecycle_counts.unknown_count, 0)
  INTO
    v_local_prepared_not_sent_count,
    v_scheduled_local_not_sent_count,
    v_provider_submitted_pending_count,
    v_provider_outage_retry_later_count,
    v_provider_outcome_unknown_count,
    v_provider_terminal_no_money_count,
    v_provider_final_paid_count,
    v_cancelled_before_bank_submission_count,
    v_external_provider_evidence_count,
    v_unknown_count
  FROM lifecycle_counts;

  SELECT COUNT(*)::integer
  INTO v_financials_rewound_count
  FROM public.pay_payment_correction_work_items AS rewind_work_item
  JOIN public.pay_payment_correction_requests AS rewind_request
    ON rewind_request.id = rewind_work_item.correction_request_id
  WHERE rewind_request.pay_batch_id = p_pay_batch_id
    AND UPPER(BTRIM(COALESCE(rewind_request.correction_kind, ''))) IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
    AND UPPER(BTRIM(COALESCE(rewind_work_item.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED');

  v_all_local_not_sent := COALESCE(v_transfer_count, 0) > 0
    AND COALESCE(v_external_provider_evidence_count, 0) = 0
    AND COALESCE(v_provider_submitted_pending_count, 0) = 0
    AND COALESCE(v_provider_outcome_unknown_count, 0) = 0
    AND COALESCE(v_provider_terminal_no_money_count, 0) = 0
    AND COALESCE(v_provider_final_paid_count, 0) = 0
    AND (COALESCE(v_local_prepared_not_sent_count, 0) + COALESCE(v_scheduled_local_not_sent_count, 0) + COALESCE(v_cancelled_before_bank_submission_count, 0)) = COALESCE(v_transfer_count, 0);

  v_has_external_provider_submission := COALESCE(v_external_provider_evidence_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0;
  v_has_pending_provider_outcome := COALESCE(v_provider_submitted_pending_count, 0) > 0;
  v_has_unknown_provider_outcome := COALESCE(v_provider_outcome_unknown_count, 0) > 0;
  v_has_terminal_no_money := COALESCE(v_provider_terminal_no_money_count, 0) > 0;
  v_has_final_paid_or_settled := COALESCE(v_provider_final_paid_count, 0) > 0;

  v_provider_submit_phase_active := (
    COALESCE(v_same_operation_authorised_auth_request_count, 0) > 0
    OR COALESCE(v_provider_submit_ready_count, 0) > 0
    OR COALESCE(v_authorised_without_provider_submission_count, 0) > 0
    OR COALESCE(v_authorised_but_not_submit_ready_count, 0) > 0
  );
  v_authorisation_phase_active := (
    COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE
    AND COALESCE(v_authorisation_ready_count, 0) > 0
  );

  v_whole_batch_cancel_safe := COALESCE(v_transfer_count, 0) > 0
    AND COALESCE(v_has_external_provider_submission, false) IS NOT TRUE
    AND COALESCE(v_has_pending_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_unknown_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_terminal_no_money, false) IS NOT TRUE
    AND COALESCE(v_has_final_paid_or_settled, false) IS NOT TRUE
    AND COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE;

  v_partial_batch_cancel_state := CASE
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_cancelled_before_bank_submission_count, 0) < COALESCE(v_transfer_count, 0)
      THEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION'
    WHEN COALESCE(v_cancelled_before_bank_submission_count, 0) > 0
     AND COALESCE(v_cancelled_before_bank_submission_count, 0) >= COALESCE(v_transfer_count, 0)
      THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
    ELSE NULL::text
  END;

  v_retry_same_batch_safe := COALESCE(v_provider_outage_retry_later_count, 0) > 0
    AND COALESCE(v_has_external_provider_submission, false) IS NOT TRUE
    AND COALESCE(v_has_unknown_provider_outcome, false) IS NOT TRUE
    AND COALESCE(v_has_terminal_no_money, false) IS NOT TRUE
    AND COALESCE(v_has_final_paid_or_settled, false) IS NOT TRUE;

  v_provider_submit_phase_active := (
    COALESCE(v_same_operation_authorised_auth_request_count, 0) > 0
    OR COALESCE(v_provider_submit_ready_count, 0) > 0
    OR COALESCE(v_authorised_without_provider_submission_count, 0) > 0
    OR COALESCE(v_authorised_but_not_submit_ready_count, 0) > 0
  );
  v_authorisation_phase_active := (
    COALESCE(v_provider_submit_phase_active, false) IS NOT TRUE
    AND COALESCE(v_authorisation_ready_count, 0) > 0
  );

  IF COALESCE(v_provider_submit_phase_active, false) IS TRUE THEN
    v_remaining_unattempted_submit_required := coalesce(v_provider_submit_ready_count, 0);
    v_remaining_submit_attempt_required := v_remaining_unattempted_submit_required;
    v_remaining_provider_submission_required := v_remaining_unattempted_submit_required;
    v_remaining_submit_attempt_required_phase := 'PROVIDER_SUBMIT';
  ELSE
    v_remaining_unattempted_submit_required := 0;
    v_remaining_submit_attempt_required := 0;
    v_remaining_provider_submission_required := 0;
    v_remaining_submit_attempt_required_phase := CASE
      WHEN COALESCE(v_authorisation_phase_active, false) THEN 'AUTHORISATION'
      ELSE 'NOT_PROVIDER_SUBMIT_PHASE'
    END;
  END IF;

  v_remaining_evidence_unresolved_count := coalesce(v_pending_count, 0) + coalesce(v_local_only_count, 0);
  v_remaining_provider_evidence_required := coalesce(v_remaining_evidence_unresolved_count, 0)
    + coalesce(v_ambiguous_count, 0)
    + coalesce(v_attempted_but_unproven_count, 0);

  v_can_mark_submitted := coalesce(v_transfer_count, 0) > 0
    AND coalesce(v_provider_submitted_count, 0) = coalesce(v_transfer_count, 0)
    AND coalesce(v_failed_count, 0) = 0
    AND coalesce(v_ambiguous_count, 0) = 0
    AND coalesce(v_local_only_count, 0) = 0
    AND coalesce(v_pending_count, 0) = 0
    AND coalesce(v_attempted_but_unproven_count, 0) = 0;
  v_can_mark_committed := v_can_mark_submitted
    AND coalesce(v_committed_count, 0) = coalesce(v_transfer_count, 0);

  v_provider_external_evidence_count := GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(v_provider_submitted_count, 0), COALESCE(v_provider_submission_accepted_count, 0));
  v_provider_acceptance_evidence_present := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_submitted_count, 0) > 0
    OR COALESCE(v_provider_submission_accepted_count, 0) > 0
    OR upper(BTRIM(COALESCE(v_provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_ACCEPTED';
  v_provider_boundary_crossed := COALESCE(v_provider_acceptance_evidence_present, false) IS TRUE
    AND COALESCE(v_provider_external_evidence_count, 0) > 0
    AND COALESCE(v_failed_count, 0) = 0
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_provider_submission_rejected_count, 0) = 0;
  v_local_finalisation_required := COALESCE(v_provider_acceptance_evidence_present, false) IS TRUE
    AND (
      COALESCE(v_raw_batch_status, '') = 'DRAFT'
      OR COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') = 'NOT_SUBMITTED'
    );
  v_safe_to_retry_provider := COALESCE(v_provider_acceptance_evidence_present, false) IS NOT TRUE
    AND COALESCE(v_provider_boundary_crossed, false) IS NOT TRUE
    AND COALESCE(v_provider_manual_resolution_required, false) IS NOT TRUE
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_attempted_but_unproven_count, 0) = 0
    AND COALESCE(v_provider_attempt_without_external_id_count, 0) = 0
    AND COALESCE(v_provider_submission_rejected_count, 0) = 0
    AND COALESCE(v_failed_count, 0) = 0;
  v_safe_to_execute := COALESCE(v_provider_acceptance_evidence_present, false) IS NOT TRUE
    AND COALESCE(v_provider_boundary_crossed, false) IS NOT TRUE
    AND COALESCE(v_local_finalisation_required, false) IS NOT TRUE
    AND COALESCE(v_provider_manual_resolution_required, false) IS NOT TRUE
    AND COALESCE(v_ambiguous_count, 0) = 0
    AND COALESCE(v_attempted_but_unproven_count, 0) = 0
    AND COALESCE(v_provider_attempt_without_external_id_count, 0) = 0
    AND COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') NOT IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED')
    AND COALESCE(v_raw_batch_status, '') NOT IN ('WAITING_BANK_CONFIRM', 'SETTLED', 'CANCELLED', 'CANCELED', 'FAILED', 'BLOCKED_FUNDS');
  v_recommended_action_code := CASE
    WHEN COALESCE(v_local_finalisation_required, false) IS TRUE THEN 'PROVIDER_EVIDENCE_RECONCILIATION_REQUIRED'
    WHEN COALESCE(v_provider_manual_resolution_required, false) IS TRUE OR COALESCE(v_ambiguous_count, 0) > 0 OR COALESCE(v_attempted_but_unproven_count, 0) > 0 THEN 'PROVIDER_OUTCOME_REVIEW_REQUIRED'
    WHEN COALESCE(v_failed_count, 0) > 0 OR COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN 'PROVIDER_REJECTION_OR_PAYMENT_FAILURE_REVIEW_REQUIRED'
    WHEN COALESCE(v_provider_boundary_crossed, false) IS TRUE THEN 'PENDING_BANK_CONFIRMATION'
    WHEN COALESCE(v_raw_execution_commit_state, 'NOT_SUBMITTED') IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN 'ALREADY_SUBMITTED'
    WHEN COALESCE(v_safe_to_execute, false) IS TRUE THEN 'EXECUTE_AVAILABLE'
    ELSE COALESCE(NULLIF(v_provider_recommended_action, ''), 'NO_ACTION_REQUIRED')
  END;

  SELECT coalesce(jsonb_agg(status_item.status_value ORDER BY status_item.status_value), '[]'::jsonb)
  INTO v_transfer_statuses
  FROM (
    SELECT DISTINCT upper(btrim(coalesce(transfer_row.status, ''))) AS status_value
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND nullif(btrim(coalesce(transfer_row.status, '')), '') IS NOT NULL
  ) AS status_item;

  SELECT coalesce(jsonb_agg(rail_state_item.rail_state_value ORDER BY rail_state_item.rail_state_value), '[]'::jsonb)
  INTO v_transfer_rail_states
  FROM (
    SELECT DISTINCT upper(btrim(coalesce(transfer_row.rail_state, ''))) AS rail_state_value
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND nullif(btrim(coalesce(transfer_row.rail_state, '')), '') IS NOT NULL
  ) AS rail_state_item;

  SELECT coalesce(jsonb_agg(event_state_item.normalised_state_value ORDER BY event_state_item.normalised_state_value), '[]'::jsonb)
  INTO v_event_normalised_states
  FROM (
    SELECT DISTINCT upper(btrim(coalesce(event_row.normalised_state, ''))) AS normalised_state_value
    FROM public.pay_bank_transfer_events AS event_row
    WHERE event_row.pay_batch_id = p_pay_batch_id
      AND nullif(btrim(coalesce(event_row.normalised_state, '')), '') IS NOT NULL
  ) AS event_state_item;

  SELECT coalesce(jsonb_agg(provider_state_item.provider_state_value ORDER BY provider_state_item.provider_state_value), '[]'::jsonb)
  INTO v_event_provider_states
  FROM (
    SELECT DISTINCT upper(btrim(coalesce(event_row.provider_state, ''))) AS provider_state_value
    FROM public.pay_bank_transfer_events AS event_row
    WHERE event_row.pay_batch_id = p_pay_batch_id
      AND nullif(btrim(coalesce(event_row.provider_state, '')), '') IS NOT NULL
  ) AS provider_state_item;

  RETURN (
  jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'transfer_count', coalesce(v_transfer_count, 0),
    'transfer_event_count', coalesce(v_transfer_event_count, 0),
    'has_transfer_events', coalesce(v_transfer_event_count, 0) > 0,
    'provider_submitted_count', coalesce(v_provider_submitted_count, 0),
    'provider_evidence_present_count', coalesce(v_provider_acceptance_evidence_count, 0),
    'local_idempotency_only_count', coalesce(v_local_only_count, 0),
    'local_only_count', coalesce(v_local_only_count, 0),
    'local_only_evidence_count', coalesce(v_local_only_count, 0),
    'pending_count', coalesce(v_pending_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'ambiguous_count', coalesce(v_ambiguous_count, 0),
    'attempted_but_unproven_count', coalesce(v_attempted_but_unproven_count, 0),
    'provider_attempt_without_external_id_count', coalesce(v_provider_attempt_without_external_id_count, 0),
    'requires_provider_poll_count', coalesce(v_requires_provider_poll_count, 0),
    'authorisation_ready_count', coalesce(v_authorisation_ready_count, 0),
    'authorisation_ready_transfer_count', coalesce(v_authorisation_ready_transfer_count, 0),
    'unattempted_submit_eligible_count', coalesce(v_unattempted_submit_eligible_count, 0),
    'provider_submit_ready_count', coalesce(v_provider_submit_ready_count, 0),
    'provider_submit_ready_transfer_count', coalesce(v_provider_submit_ready_transfer_count, 0),
    'authorised_without_provider_submission_count', coalesce(v_authorised_without_provider_submission_count, 0),
    'authorised_but_not_submit_ready_count', coalesce(v_authorised_but_not_submit_ready_count, 0),
    'provider_submit_blocked_count', coalesce(v_provider_submit_blocked_count, 0),
    'same_operation_authorised_auth_request_count', coalesce(v_same_operation_authorised_auth_request_count, 0),
    'provider_submit_phase_active', coalesce(v_provider_submit_phase_active, false),
    'authorisation_phase_active', coalesce(v_authorisation_phase_active, false),
    'safe_local_cleanup_count', coalesce(v_safe_local_cleanup_count, 0),
    'provider_attempt_or_evidence_count', coalesce(v_provider_attempt_or_evidence_count, 0),
    'provider_or_ambiguous_evidence_count', coalesce(v_provider_or_ambiguous_evidence_count, 0),
    'cancellable_local_auth_request_count', coalesce(v_cancellable_local_auth_request_count, 0),
    'non_cancellable_auth_request_count', coalesce(v_non_cancellable_auth_request_count, 0)
  )
  ||
  jsonb_build_object(
    'same_operation_active_auth_request_count', coalesce(v_same_operation_active_auth_request_count, 0),
    'other_operation_active_auth_request_count', coalesce(v_other_operation_active_auth_request_count, 0),
    'auth_request_provider_risk_count', coalesce(v_auth_request_provider_risk_count, 0),
    'auth_request_retry_blocker_count', coalesce(v_auth_request_retry_blocker_count, 0),
    'remaining_submit_attempt_required', coalesce(v_remaining_submit_attempt_required, 0),
    'remaining_unattempted_submit_required', coalesce(v_remaining_unattempted_submit_required, 0),
    'remaining_evidence_unresolved_count', coalesce(v_remaining_evidence_unresolved_count, 0),
    'remaining_submit_attempt_required_definition', 'phase_dependent_provider_submit_ready_count',
    'remaining_submit_attempt_required_phase', v_remaining_submit_attempt_required_phase,
    'remaining_provider_evidence_required', coalesce(v_remaining_provider_evidence_required, 0),
    'remaining_provider_submission_required', coalesce(v_remaining_provider_submission_required, 0),
    'submission_count_semantics', jsonb_build_object(
      'remaining_submit_attempt_required', 'phase-dependent count: provider-submit-ready authorised transfers only when provider-submit phase is active',
      'remaining_evidence_unresolved_count', 'legacy evidence-pending plus local-only count kept separate from submit eligibility',
      'pending_count', 'evidence-level pending classification, not authorisation or submit eligibility'
    ),
    'batch_can_be_marked_submitted', coalesce(v_can_mark_submitted, false),
    'can_mark_submitted', coalesce(v_can_mark_submitted, false),
    'can_mark_committed', coalesce(v_can_mark_committed, false),
    'has_rail_tx_id', coalesce(v_has_rail_tx_id, false),
    'has_local_generated_request_identity', coalesce(v_has_local_generated_request_identity, false),
    'has_external_submission_evidence', coalesce(v_has_external_submission_evidence, false),
    'no_submission_evidence', coalesce(v_has_external_submission_evidence, false) = false,
    'transfer_statuses', coalesce(v_transfer_statuses, '[]'::jsonb),
    'transfer_rail_states', coalesce(v_transfer_rail_states, '[]'::jsonb),
    'event_normalised_states', coalesce(v_event_normalised_states, '[]'::jsonb),
    'event_provider_states', coalesce(v_event_provider_states, '[]'::jsonb),
    'evidence_sample', coalesce(v_evidence_sample, '[]'::jsonb),
    'execution_classification_sample', coalesce(v_execution_classification_sample, '[]'::jsonb),
    'has_possible_provider_attempt_evidence', coalesce(v_has_external_submission_evidence, false) OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_provider_attempt_request_or_idempotency_reference', coalesce(v_provider_submitted_count, 0) > 0 OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_request_or_idempotency_reference', coalesce(v_local_only_count, 0) > 0 OR coalesce(v_provider_submitted_count, 0) > 0 OR coalesce(v_attempted_but_unproven_count, 0) > 0,
    'has_submitted_state', coalesce(v_provider_submitted_count, 0) > 0,
    'has_processing_state', coalesce(v_transfer_rail_states, '[]'::jsonb) ?| array['PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION'],
    'has_completed_state', coalesce(v_committed_count, 0) > 0,
    'has_failed_or_rejected_provider_state', coalesce(v_failed_count, 0) > 0
  )
  ||
  jsonb_build_object(
    'has_unknown_or_timeout_state', coalesce(v_ambiguous_count, 0) > 0,
    'provider_submit_diagnostic', CASE WHEN v_provider_submit_review_active THEN COALESCE(v_provider_submit_diagnostic, '{}'::jsonb) ELSE '{}'::jsonb END,
    'provider_submission_status', v_provider_submission_status,
    'review_reason_code', v_provider_submit_review_reason_code,
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
    'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
    'safe_retry_available', COALESCE(v_provider_safe_retry_available, false),
    'recommended_action', v_provider_recommended_action,
    'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
    'provider_acceptance_evidence_present', COALESCE(v_provider_acceptance_evidence_present, false),
    'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
    'local_finalisation_required', COALESCE(v_local_finalisation_required, false),
    'raw_batch_status', v_raw_batch_status,
    'raw_execution_commit_state', v_raw_execution_commit_state,
    'safe_to_retry_provider', COALESCE(v_safe_to_retry_provider, false),
    'safe_to_execute', COALESCE(v_safe_to_execute, false),
    'recommended_action_code', v_recommended_action_code,
    'requires_provider_poll', coalesce(v_requires_provider_poll_count, 0) > 0,
    'requires_review', COALESCE(v_provider_manual_resolution_required, false) OR coalesce(v_ambiguous_count, 0) > 0 OR (coalesce(v_attempted_but_unproven_count, 0) > 0 AND coalesce(v_requires_provider_poll_count, 0) = 0)
  )
  ||
  jsonb_build_object(
    'local_prepared_not_sent_count', COALESCE(v_local_prepared_not_sent_count, 0),
    'scheduled_local_not_sent_count', COALESCE(v_scheduled_local_not_sent_count, 0),
    'provider_submitted_pending_count', COALESCE(v_provider_submitted_pending_count, 0),
    'provider_outage_retry_later_count', COALESCE(v_provider_outage_retry_later_count, 0),
    'provider_outcome_unknown_count', COALESCE(v_provider_outcome_unknown_count, 0),
    'provider_terminal_no_money_count', COALESCE(v_provider_terminal_no_money_count, 0),
    'provider_final_paid_count', COALESCE(v_provider_final_paid_count, 0),
    'cancelled_before_bank_submission_count', COALESCE(v_cancelled_before_bank_submission_count, 0),
    'financials_rewound_count', COALESCE(v_financials_rewound_count, 0),
    'external_provider_evidence_count', COALESCE(v_external_provider_evidence_count, 0),
    'unknown_count', COALESCE(v_unknown_count, 0),
    'provider_webhook_evidence_count', COALESCE(v_provider_webhook_evidence_count, 0),
    'provider_poll_evidence_count', COALESCE(v_provider_poll_evidence_count, 0),
    'provider_failure_reason_groups_json', COALESCE(v_provider_failure_reason_groups_json, '[]'::jsonb),
    'success_only_count', COALESCE(v_success_only_count, 0),
    'alert_candidate_count', COALESCE(v_alert_candidate_count, 0),
    'all_local_not_sent' , COALESCE(v_all_local_not_sent, false),
    'has_external_provider_submission', COALESCE(v_has_external_provider_submission, false),
    'has_pending_provider_outcome', COALESCE(v_has_pending_provider_outcome, false),
    'has_unknown_provider_outcome', COALESCE(v_has_unknown_provider_outcome, false),
    'has_terminal_no_money', COALESCE(v_has_terminal_no_money, false),
    'has_final_paid_or_settled', COALESCE(v_has_final_paid_or_settled, false),
    'whole_batch_cancel_safe', COALESCE(v_whole_batch_cancel_safe, false),
    'partial_batch_cancel_state', v_partial_batch_cancel_state,
    'retry_same_batch_safe', COALESCE(v_retry_same_batch_safe, false)
  )
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.banking_alert_acknowledge_all_current(
  p_actor_user_id uuid,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_active_json jsonb := '{}'::jsonb;
  v_remaining_json jsonb := '{}'::jsonb;
  v_active_count integer := 0;
  v_created_count integer := 0;
  v_already_acknowledged_count integer := 0;
  v_acknowledged_count integer := 0;
  v_remaining_count integer := 0;
  v_acknowledged_alerts jsonb := '[]'::jsonb;
  v_signal_json jsonb := '{}'::jsonb;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_ACKNOWLEDGE_ALL_CURRENT_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_ACKNOWLEDGE_ALL_CURRENT_ACTOR_REQUIRED')::text;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtext('banking_alert_acknowledge_all_current'),
    pg_catalog.hashtext(p_actor_user_id::text || ':USER')
  );

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    0
  );

  WITH active_alert_rows AS (
    SELECT
      active_alert_element.alert_json ->> 'alert_fingerprint' AS active_alert_fingerprint,
      active_alert_element.alert_json ->> 'alert_kind' AS active_alert_kind,
      active_alert_element.alert_json ->> 'entity_kind' AS active_entity_kind,
      (active_alert_element.alert_json ->> 'entity_id')::uuid AS active_entity_id,
      COALESCE(active_alert_element.alert_json -> 'payload_json', '{}'::jsonb) AS active_payload_json
    FROM jsonb_array_elements(COALESCE(v_active_json -> 'alerts', '[]'::jsonb)) AS active_alert_element(alert_json)
    WHERE NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'alert_fingerprint', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'alert_kind', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'entity_kind', '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(active_alert_element.alert_json ->> 'entity_id', '')), '') IS NOT NULL
      AND COALESCE((active_alert_element.alert_json ->> 'acknowledged_for_current_user')::boolean, false) = false
  ),
  deduped_active_alert_rows AS (
    SELECT DISTINCT ON (active_alert_rows.active_alert_fingerprint)
      active_alert_rows.active_alert_fingerprint,
      upper(btrim(active_alert_rows.active_alert_kind)) AS active_alert_kind,
      lower(btrim(active_alert_rows.active_entity_kind)) AS active_entity_kind,
      active_alert_rows.active_entity_id,
      COALESCE(active_alert_rows.active_payload_json, '{}'::jsonb) AS active_payload_json
    FROM active_alert_rows
    ORDER BY active_alert_rows.active_alert_fingerprint ASC
  ),
  upserted_acknowledgements AS (
    INSERT INTO public.banking_alert_acknowledgements AS banking_alert_acknowledgement_upsert (
      alert_fingerprint,
      alert_kind,
      entity_kind,
      entity_id,
      acknowledged_by_user_id,
      acknowledged_at_utc,
      acknowledge_scope,
      note,
      alert_payload_json,
      resolved_at_ack
    )
    SELECT
      deduped_active_alert_rows.active_alert_fingerprint,
      deduped_active_alert_rows.active_alert_kind,
      deduped_active_alert_rows.active_entity_kind,
      deduped_active_alert_rows.active_entity_id,
      p_actor_user_id,
      now(),
      'USER',
      NULLIF(BTRIM(COALESCE(p_note, '')), ''),
      deduped_active_alert_rows.active_payload_json,
      false
    FROM deduped_active_alert_rows
    WHERE true
    ON CONFLICT (alert_fingerprint, acknowledged_by_user_id, acknowledge_scope) DO UPDATE
    SET
      note = COALESCE(EXCLUDED.note, banking_alert_acknowledgement_upsert.note),
      alert_payload_json = CASE
        WHEN EXCLUDED.alert_payload_json = '{}'::jsonb THEN banking_alert_acknowledgement_upsert.alert_payload_json
        ELSE EXCLUDED.alert_payload_json
      END
    RETURNING
      banking_alert_acknowledgement_upsert.alert_fingerprint,
      banking_alert_acknowledgement_upsert.alert_kind,
      banking_alert_acknowledgement_upsert.entity_kind,
      banking_alert_acknowledgement_upsert.entity_id,
      banking_alert_acknowledgement_upsert.acknowledged_at_utc,
      (banking_alert_acknowledgement_upsert.xmax = 0) AS created
  ),
  acknowledgement_summary AS (
    SELECT
      COALESCE(count(*) FILTER (WHERE upserted_acknowledgements.created = true), 0)::integer AS created_alert_count,
      COALESCE(count(*) FILTER (WHERE upserted_acknowledgements.created = false), 0)::integer AS already_acknowledged_alert_count,
      COALESCE(count(*), 0)::integer AS acknowledged_alert_count,
      COALESCE(jsonb_agg(jsonb_build_object(
        'alert_fingerprint', upserted_acknowledgements.alert_fingerprint,
        'alert_kind', upserted_acknowledgements.alert_kind,
        'entity_kind', upserted_acknowledgements.entity_kind,
        'entity_id', upserted_acknowledgements.entity_id::text,
        'acknowledged_at_utc', upserted_acknowledgements.acknowledged_at_utc::text,
        'created', upserted_acknowledgements.created,
        'already_acknowledged', NOT upserted_acknowledgements.created
      ) ORDER BY upserted_acknowledgements.acknowledged_at_utc DESC, upserted_acknowledgements.alert_fingerprint ASC), '[]'::jsonb) AS acknowledged_alerts_json
    FROM upserted_acknowledgements
  ),
  counted_active_alerts AS (
    SELECT COUNT(*)::integer AS active_alert_count
    FROM deduped_active_alert_rows
  )
  SELECT
    COALESCE(counted_active_alerts.active_alert_count, 0),
    COALESCE(acknowledgement_summary.created_alert_count, 0),
    COALESCE(acknowledgement_summary.already_acknowledged_alert_count, 0),
    COALESCE(acknowledgement_summary.acknowledged_alert_count, 0),
    COALESCE(acknowledgement_summary.acknowledged_alerts_json, '[]'::jsonb)
  INTO
    v_active_count,
    v_created_count,
    v_already_acknowledged_count,
    v_acknowledged_count,
    v_acknowledged_alerts
  FROM counted_active_alerts
  CROSS JOIN acknowledgement_summary;

  v_remaining_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    25
  );

  v_signal_json := public.banking_alert_signal_for_user(
    p_actor_user_id,
    NULL::text
  );

  v_remaining_count := COALESCE((v_signal_json ->> 'banking_unacknowledged_alert_count')::integer, 0);

  v_remaining_json := v_remaining_json || jsonb_build_object(
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', v_remaining_count,
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'unacknowledged_count', v_remaining_count,
    'highest_severity', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''), ''),
    'highest_label', NULLIF(COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''), '')
  );

  RETURN jsonb_build_object(
    'ok', true,
    'mode', 'clear_all',
    'active_count_before_acknowledge', COALESCE(v_active_count, 0),
    'requested_count', COALESCE(v_active_count, 0),
    'created_count', COALESCE(v_created_count, 0),
    'already_acknowledged_count', COALESCE(v_already_acknowledged_count, 0),
    'acknowledged_count', COALESCE(v_acknowledged_count, 0),
    'remaining_unacknowledged_count', COALESCE(v_remaining_count, 0),
    'banking_alert_hash', COALESCE(v_signal_json ->> 'banking_alert_hash', 'banking_alert_signal:v2:' || MD5('')),
    'banking_unacknowledged_alert_count', COALESCE(v_remaining_count, 0),
    'banking_highest_alert_severity', COALESCE(v_signal_json ->> 'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_signal_json ->> 'banking_highest_alert_label', ''),
    'ignored_count', GREATEST(COALESCE(v_active_count, 0) - COALESCE(v_acknowledged_count, 0), 0),
    'acknowledged_alerts', COALESCE(v_acknowledged_alerts, '[]'::jsonb),
    'remaining_alert_summary', v_remaining_json,
    'alert_summary', v_remaining_json
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.banking_alert_signal_for_user(
  p_actor_user_id uuid,
  p_last_alert_hash text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_last_alert_hash text := NULLIF(BTRIM(COALESCE(p_last_alert_hash, '')), '');
  v_active_json jsonb := '{}'::jsonb;
  v_alert_hash text := NULL::text;
  v_summary_signature text := NULL::text;
BEGIN
  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'BANKING_ALERT_SIGNAL_FOR_USER_ACTOR_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'BANKING_ALERT_SIGNAL_FOR_USER_ACTOR_REQUIRED')::text;
  END IF;

  v_active_json := public.banking_alerts_active_for_user(
    p_actor_user_id,
    NULL::text,
    NULL::uuid,
    false,
    0
  );

  v_alert_hash := COALESCE(v_active_json->>'banking_alert_hash', 'banking_alert_signal:v3:' || MD5(''));
  v_summary_signature := COALESCE(v_active_json->>'banking_alert_summary_signature', 'banking_alert_summary:v3:' || MD5(''));

  RETURN jsonb_build_object(
    'ok', true,
    'generated_at_utc', now()::text,
    'actor_user_id', p_actor_user_id::text,
    'banking_alert_hash', v_alert_hash,
    'banking_alert_summary_signature', v_summary_signature,
    'banking_alert_summary_changed', COALESCE(v_last_alert_hash IS DISTINCT FROM v_alert_hash, true),
    'banking_unacknowledged_alert_count', COALESCE((v_active_json->>'banking_unacknowledged_alert_count')::integer, 0),
    'grouped_banking_unacknowledged_alert_count', COALESCE((v_active_json->>'banking_unacknowledged_alert_count')::integer, 0),
    'banking_highest_alert_severity', COALESCE(v_active_json->>'banking_highest_alert_severity', ''),
    'banking_highest_alert_label', COALESCE(v_active_json->>'banking_highest_alert_label', ''),
    'highest_severity', COALESCE(v_active_json->>'banking_highest_alert_severity', ''),
    'highest_label', COALESCE(v_active_json->>'banking_highest_alert_label', ''),
    'alerts', COALESCE(v_active_json->'alerts', '[]'::jsonb),
    'summary_is_grouped', true
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.rpc_changes_ping(p_last_seen jsonb DEFAULT '{}'::jsonb)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
AS $function$
DECLARE
  v_last_seen jsonb := COALESCE(p_last_seen, '{}'::jsonb);
  v_seqs jsonb := '{}'::jsonb;
  v_changed text[] := array[]::text[];
  v_prev bigint;
  v_cur bigint;
  v_counter_record record;
  v_actor_user_id uuid := NULL::uuid;
  v_banking_alert_hash text := NULL::text;
  v_banking_alert_signal jsonb := NULL::jsonb;
  v_result jsonb := '{}'::jsonb;
  v_watched_batch_ids jsonb := '[]'::jsonb;
  v_watched_batch_signals jsonb := '[]'::jsonb;
BEGIN
  IF COALESCE(jsonb_typeof(v_last_seen), 'null') <> 'object' THEN
    v_last_seen := '{}'::jsonb;
  END IF;

  BEGIN
    v_actor_user_id := NULLIF(BTRIM(COALESCE(v_last_seen ->> '__banking_actor_user_id', '')), '')::uuid;
  EXCEPTION WHEN OTHERS THEN
    v_actor_user_id := NULL::uuid;
  END;

  v_banking_alert_hash := NULLIF(BTRIM(COALESCE(
    v_last_seen ->> '__banking_alert_hash',
    v_last_seen ->> 'banking_alert_hash',
    ''
  )), '');

  IF jsonb_typeof(v_last_seen -> '__watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> '__watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_pay_batch_ids') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_pay_batch_ids';
  ELSIF jsonb_typeof(v_last_seen -> 'watched_batches') = 'array' THEN
    v_watched_batch_ids := v_last_seen -> 'watched_batches';
  ELSE
    v_watched_batch_ids := '[]'::jsonb;
  END IF;

  FOR v_counter_record IN
    SELECT public.app_change_counters.entity_key, public.app_change_counters.seq
    FROM public.app_change_counters
    ORDER BY public.app_change_counters.entity_key
  LOOP
    v_cur := COALESCE(v_counter_record.seq, 0);
    v_prev := 0;

    BEGIN
      v_prev := COALESCE((v_last_seen ->> v_counter_record.entity_key)::bigint, 0);
    EXCEPTION WHEN OTHERS THEN
      v_prev := 0;
    END;

    v_seqs := v_seqs || jsonb_build_object(v_counter_record.entity_key, v_cur);

    IF v_cur > v_prev THEN
      v_changed := array_append(v_changed, v_counter_record.entity_key);
    END IF;
  END LOOP;

  v_result := jsonb_build_object(
    'server_utc', now(),
    'seqs', v_seqs,
    'changed', to_jsonb(v_changed)
  );

  IF v_actor_user_id IS NOT NULL THEN
    v_banking_alert_signal := public.banking_alert_signal_for_user(
      v_actor_user_id,
      v_banking_alert_hash
    );

    v_result := v_result || jsonb_build_object(
      'banking_alert_hash', COALESCE(v_banking_alert_signal ->> 'banking_alert_hash', 'banking_alert_signal:v3:' || MD5('')),
      'banking_alert_summary_signature', COALESCE(v_banking_alert_signal ->> 'banking_alert_summary_signature', 'banking_alert_summary:v3:' || MD5('')),
      'banking_alert_summary_changed', COALESCE((v_banking_alert_signal ->> 'banking_alert_summary_changed')::boolean, false),
      'banking_unacknowledged_alert_count', COALESCE((v_banking_alert_signal ->> 'banking_unacknowledged_alert_count')::integer, 0),
      'grouped_banking_unacknowledged_alert_count', COALESCE((v_banking_alert_signal ->> 'grouped_banking_unacknowledged_alert_count')::integer, COALESCE((v_banking_alert_signal ->> 'banking_unacknowledged_alert_count')::integer, 0)),
      'banking_highest_alert_severity', COALESCE(v_banking_alert_signal ->> 'banking_highest_alert_severity', ''),
      'banking_highest_alert_label', COALESCE(v_banking_alert_signal ->> 'banking_highest_alert_label', ''),
      'banking_alert_summary_included', COALESCE((v_banking_alert_signal ->> 'banking_alert_summary_changed')::boolean, false),
      'banking_alert_summary', CASE
        WHEN COALESCE((v_banking_alert_signal ->> 'banking_alert_summary_changed')::boolean, false)
          THEN jsonb_build_object(
            'ok', true,
            'alerts', COALESCE(v_banking_alert_signal -> 'alerts', '[]'::jsonb),
            'unacknowledged_count', COALESCE((v_banking_alert_signal ->> 'banking_unacknowledged_alert_count')::integer, 0),
            'highest_severity', COALESCE(v_banking_alert_signal ->> 'banking_highest_alert_severity', ''),
            'highest_label', COALESCE(v_banking_alert_signal ->> 'banking_highest_alert_label', ''),
            'banking_alert_hash', COALESCE(v_banking_alert_signal ->> 'banking_alert_hash', 'banking_alert_signal:v3:' || MD5('')),
            'banking_alert_summary_signature', COALESCE(v_banking_alert_signal ->> 'banking_alert_summary_signature', 'banking_alert_summary:v3:' || MD5('')),
            'summary_is_grouped', true
          )
        ELSE NULL::jsonb
      END
    );
  END IF;

  IF jsonb_array_length(COALESCE(v_watched_batch_ids, '[]'::jsonb)) > 0 THEN
    WITH requested_watched_batches AS (
      SELECT DISTINCT
        CASE
          WHEN jsonb_typeof(watched_batch.value) = 'string'
           AND trim(both '"' from watched_batch.value::text) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN trim(both '"' from watched_batch.value::text)::uuid
          WHEN jsonb_typeof(watched_batch.value) = 'object'
           AND COALESCE(watched_batch.value->>'pay_batch_id', watched_batch.value->>'id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN COALESCE(watched_batch.value->>'pay_batch_id', watched_batch.value->>'id')::uuid
          ELSE NULL::uuid
        END AS pay_batch_id,
        CASE
          WHEN jsonb_typeof(watched_batch.value) = 'object'
           AND COALESCE(watched_batch.value->>'known_version', watched_batch.value->>'live_signal_version', '') ~ '^[0-9]+$'
            THEN COALESCE(watched_batch.value->>'known_version', watched_batch.value->>'live_signal_version')::bigint
          ELSE NULL::bigint
        END AS known_version
      FROM jsonb_array_elements(COALESCE(v_watched_batch_ids, '[]'::jsonb)) AS watched_batch(value)
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'pay_batch_id', requested_watched_batches.pay_batch_id::text,
      'known_version', requested_watched_batches.known_version,
      'live_signal_version', COALESCE(batch_signal.version, 0),
      'payment_status_version', COALESCE(batch_signal.payment_status_version, 0),
      'correction_progress_version', COALESCE(batch_signal.correction_progress_version, 0),
      'alert_version', COALESCE(batch_signal.alert_version, 0),
      'overview_version', COALESCE(batch_signal.overview_version, 0),
      'last_status_hash', batch_signal.last_status_hash,
      'last_alert_hash', batch_signal.last_alert_hash,
      'changed_since_version', requested_watched_batches.known_version IS NOT NULL AND COALESCE(batch_signal.version, 0) > requested_watched_batches.known_version
    ) ORDER BY requested_watched_batches.pay_batch_id::text), '[]'::jsonb)
    INTO v_watched_batch_signals
    FROM requested_watched_batches
    LEFT JOIN public.banking_pay_batch_change_signals AS batch_signal
      ON batch_signal.pay_batch_id = requested_watched_batches.pay_batch_id
    WHERE requested_watched_batches.pay_batch_id IS NOT NULL;

    v_result := v_result || jsonb_build_object(
      'watched_batch_signals', COALESCE(v_watched_batch_signals, '[]'::jsonb),
      'watched_batch_signal_hash', 'watched_batch_signals:v1:' || md5(COALESCE(v_watched_batch_signals::text, '[]'))
    );
  END IF;

  RETURN v_result;
END;
$function$;






create or replace function public.banking_pay_operation_config_get(
    p_operation_type text,
    p_phase text,
    p_chunk_type text
)
returns table (
    chunk_size integer,
    min_chunk_size integer,
    max_chunk_size integer,
    max_advance_ms integer,
    lock_seconds integer
)
language plpgsql
security definer
stable
set search_path = public, pg_temp
as $$
declare
    v_operation_type text;
    v_phase text;
    v_chunk_type text;
    v_default_chunk_size integer;
    v_default_min_chunk_size integer;
    v_default_max_chunk_size integer;
    v_default_max_advance_ms integer;
    v_default_lock_seconds integer;
begin
    v_operation_type := coalesce(nullif(btrim(p_operation_type), ''), 'ALL');
    v_phase := coalesce(nullif(btrim(p_phase), ''), 'ALL');
    v_chunk_type := coalesce(nullif(btrim(p_chunk_type), ''), 'CANDIDATE_SCOPE');

    if v_chunk_type in ('TRANSFER_SUBMIT', 'PAYEE_READINESS', 'FRESHNESS_VALIDATE') then
        v_default_chunk_size := 50;
        v_default_min_chunk_size := 1;
        v_default_max_chunk_size := 250;
    else
        v_default_chunk_size := 100;
        v_default_min_chunk_size := 1;
        v_default_max_chunk_size := 500;
    end if;

    v_default_max_advance_ms := 15000;
    v_default_lock_seconds := 60;

    return query
    with candidate_config as (
        select
            config_exact.default_chunk_size,
            config_exact.min_chunk_size,
            config_exact.max_chunk_size,
            config_exact.max_advance_ms,
            config_exact.lock_seconds,
            1 as priority_order
        from public.banking_pay_operation_config as config_exact
        where config_exact.enabled is true
          and config_exact.operation_type = v_operation_type
          and config_exact.phase = v_phase
          and config_exact.chunk_type = v_chunk_type

        union all

        select
            config_operation_default.default_chunk_size,
            config_operation_default.min_chunk_size,
            config_operation_default.max_chunk_size,
            config_operation_default.max_advance_ms,
            config_operation_default.lock_seconds,
            2 as priority_order
        from public.banking_pay_operation_config as config_operation_default
        where config_operation_default.enabled is true
          and config_operation_default.operation_type = v_operation_type
          and config_operation_default.phase = 'ALL'
          and config_operation_default.chunk_type = v_chunk_type

        union all

        select
            config_global_default.default_chunk_size,
            config_global_default.min_chunk_size,
            config_global_default.max_chunk_size,
            config_global_default.max_advance_ms,
            config_global_default.lock_seconds,
            3 as priority_order
        from public.banking_pay_operation_config as config_global_default
        where config_global_default.enabled is true
          and config_global_default.operation_type = 'ALL'
          and config_global_default.phase = 'ALL'
          and config_global_default.chunk_type = v_chunk_type
    )
    select
        selected_config.default_chunk_size,
        selected_config.min_chunk_size,
        selected_config.max_chunk_size,
        selected_config.max_advance_ms,
        selected_config.lock_seconds
    from candidate_config as selected_config
    order by selected_config.priority_order asc
    limit 1;

    if found then
        return;
    end if;

    return query
    select
        v_default_chunk_size,
        v_default_min_chunk_size,
        v_default_max_chunk_size,
        v_default_max_advance_ms,
        v_default_lock_seconds;
end;
$$;


-- ============================================================
-- 3. banking_pay_operation_get
-- ============================================================

create or replace function public.banking_pay_operation_get(
    p_operation_id uuid,
    p_actor_user_id uuid default null
)
returns table (
    operation_id uuid,
    operation_type text,
    status text,
    phase text,
    actor_user_id uuid,
    workbench_session_id uuid,
    pay_batch_id uuid,
    root_operation_id uuid,
    idempotency_key text,
    input_json jsonb,
    config_json jsonb,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    total_units integer,
    completed_units integer,
    failed_units integer,
    current_chunk_index integer,
    chunk_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    updated_at_utc timestamptz,
    completed_at_utc timestamptz,
    failed_at_utc timestamptz,
    terminal boolean
)
language plpgsql
security definer
stable
set search_path = public, pg_temp
as $$
begin
    return query
    select
        operation_row.id,
        operation_row.operation_type,
        operation_row.status,
        operation_row.phase,
        operation_row.actor_user_id,
        operation_row.workbench_session_id,
        operation_row.pay_batch_id,
        operation_row.root_operation_id,
        operation_row.idempotency_key,
        operation_row.input_json,
        operation_row.config_json,
        operation_row.progress_json,
        operation_row.result_json,
        operation_row.error_json,
        operation_row.total_units,
        operation_row.completed_units,
        operation_row.failed_units,
        operation_row.current_chunk_index,
        operation_row.chunk_count,
        operation_row.locked_by,
        operation_row.lock_expires_at_utc,
        operation_row.created_at_utc,
        operation_row.started_at_utc,
        operation_row.updated_at_utc,
        operation_row.completed_at_utc,
        operation_row.failed_at_utc,
        operation_row.status in ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED')
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
      and (
          p_actor_user_id is null
          or operation_row.actor_user_id is null
          or operation_row.actor_user_id = p_actor_user_id
      );
end;
$$;


-- ============================================================
-- 4. banking_pay_operation_claim_next
-- ============================================================

create or replace function public.banking_pay_operation_claim_next(
    p_operation_id uuid,
    p_actor_user_id uuid,
    p_lock_owner text,
    p_lock_seconds integer default 60
)
returns table (
    claimed boolean,
    not_claimed_reason text,
    operation_id uuid,
    operation_type text,
    status text,
    phase text,
    actor_user_id uuid,
    workbench_session_id uuid,
    pay_batch_id uuid,
    root_operation_id uuid,
    idempotency_key text,
    input_json jsonb,
    config_json jsonb,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    total_units integer,
    completed_units integer,
    failed_units integer,
    current_chunk_index integer,
    chunk_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    updated_at_utc timestamptz,
    completed_at_utc timestamptz,
    failed_at_utc timestamptz
)
language plpgsql
security definer
volatile
set search_path = public, pg_temp
as $$
declare
    v_operation public.banking_pay_operations%rowtype;
    v_visible_operation public.banking_pay_operations%rowtype;
    v_lock_owner text;
    v_lock_seconds integer;
begin
    v_lock_owner := coalesce(nullif(btrim(p_lock_owner), ''), 'unknown');
    v_lock_seconds := coalesce(p_lock_seconds, 60);

    if v_lock_seconds < 5 then
        v_lock_seconds := 5;
    elsif v_lock_seconds > 3600 then
        v_lock_seconds := 3600;
    end if;

    select operation_row.*
    into v_operation
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
      and (
          p_actor_user_id is null
          or operation_row.actor_user_id is null
          or operation_row.actor_user_id = p_actor_user_id
      )
    for update skip locked;

    if not found then
        select visible_operation_row.*
        into v_visible_operation
        from public.banking_pay_operations as visible_operation_row
        where visible_operation_row.id = p_operation_id
          and (
              p_actor_user_id is null
              or visible_operation_row.actor_user_id is null
              or visible_operation_row.actor_user_id = p_actor_user_id
          );

        if found then
            return query
            select
                false,
                'ROW_LOCKED_OR_UNAVAILABLE'::text,
                v_visible_operation.id,
                v_visible_operation.operation_type,
                v_visible_operation.status,
                v_visible_operation.phase,
                v_visible_operation.actor_user_id,
                v_visible_operation.workbench_session_id,
                v_visible_operation.pay_batch_id,
                v_visible_operation.root_operation_id,
                v_visible_operation.idempotency_key,
                v_visible_operation.input_json,
                v_visible_operation.config_json,
                v_visible_operation.progress_json,
                v_visible_operation.result_json,
                v_visible_operation.error_json,
                v_visible_operation.total_units,
                v_visible_operation.completed_units,
                v_visible_operation.failed_units,
                v_visible_operation.current_chunk_index,
                v_visible_operation.chunk_count,
                v_visible_operation.locked_by,
                v_visible_operation.lock_expires_at_utc,
                v_visible_operation.created_at_utc,
                v_visible_operation.started_at_utc,
                v_visible_operation.updated_at_utc,
                v_visible_operation.completed_at_utc,
                v_visible_operation.failed_at_utc;
            return;
        end if;

        return query
        select
            false,
            'NOT_FOUND_OR_NOT_AUTHORISED'::text,
            p_operation_id,
            null::text,
            null::text,
            null::text,
            null::uuid,
            null::uuid,
            null::uuid,
            null::uuid,
            null::text,
            null::jsonb,
            null::jsonb,
            null::jsonb,
            null::jsonb,
            null::jsonb,
            null::integer,
            null::integer,
            null::integer,
            null::integer,
            null::integer,
            null::text,
            null::timestamptz,
            null::timestamptz,
            null::timestamptz,
            null::timestamptz,
            null::timestamptz,
            null::timestamptz;
        return;
    end if;

    if v_operation.status in ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') then
        return query
        select
            false,
            'TERMINAL'::text,
            v_operation.id,
            v_operation.operation_type,
            v_operation.status,
            v_operation.phase,
            v_operation.actor_user_id,
            v_operation.workbench_session_id,
            v_operation.pay_batch_id,
            v_operation.root_operation_id,
            v_operation.idempotency_key,
            v_operation.input_json,
            v_operation.config_json,
            v_operation.progress_json,
            v_operation.result_json,
            v_operation.error_json,
            v_operation.total_units,
            v_operation.completed_units,
            v_operation.failed_units,
            v_operation.current_chunk_index,
            v_operation.chunk_count,
            v_operation.locked_by,
            v_operation.lock_expires_at_utc,
            v_operation.created_at_utc,
            v_operation.started_at_utc,
            v_operation.updated_at_utc,
            v_operation.completed_at_utc,
            v_operation.failed_at_utc;
        return;
    end if;

    if v_operation.status not in ('QUEUED', 'RUNNING', 'WAITING') then
        return query
        select
            false,
            'NOT_CLAIMABLE_STATUS'::text,
            v_operation.id,
            v_operation.operation_type,
            v_operation.status,
            v_operation.phase,
            v_operation.actor_user_id,
            v_operation.workbench_session_id,
            v_operation.pay_batch_id,
            v_operation.root_operation_id,
            v_operation.idempotency_key,
            v_operation.input_json,
            v_operation.config_json,
            v_operation.progress_json,
            v_operation.result_json,
            v_operation.error_json,
            v_operation.total_units,
            v_operation.completed_units,
            v_operation.failed_units,
            v_operation.current_chunk_index,
            v_operation.chunk_count,
            v_operation.locked_by,
            v_operation.lock_expires_at_utc,
            v_operation.created_at_utc,
            v_operation.started_at_utc,
            v_operation.updated_at_utc,
            v_operation.completed_at_utc,
            v_operation.failed_at_utc;
        return;
    end if;

    if v_operation.locked_by is not null
       and v_operation.lock_expires_at_utc is not null
       and v_operation.lock_expires_at_utc > now() then
        return query
        select
            false,
            'LOCK_ACTIVE'::text,
            v_operation.id,
            v_operation.operation_type,
            v_operation.status,
            v_operation.phase,
            v_operation.actor_user_id,
            v_operation.workbench_session_id,
            v_operation.pay_batch_id,
            v_operation.root_operation_id,
            v_operation.idempotency_key,
            v_operation.input_json,
            v_operation.config_json,
            v_operation.progress_json,
            v_operation.result_json,
            v_operation.error_json,
            v_operation.total_units,
            v_operation.completed_units,
            v_operation.failed_units,
            v_operation.current_chunk_index,
            v_operation.chunk_count,
            v_operation.locked_by,
            v_operation.lock_expires_at_utc,
            v_operation.created_at_utc,
            v_operation.started_at_utc,
            v_operation.updated_at_utc,
            v_operation.completed_at_utc,
            v_operation.failed_at_utc;
        return;
    end if;

    update public.banking_pay_operations as operation_update
    set
        status = 'RUNNING',
        locked_by = v_lock_owner,
        lock_expires_at_utc = now() + make_interval(secs => v_lock_seconds),
        started_at_utc = coalesce(operation_update.started_at_utc, now()),
        updated_at_utc = now()
    where operation_update.id = v_operation.id
    returning operation_update.* into v_operation;

    return query
    select
        true,
        null::text,
        v_operation.id,
        v_operation.operation_type,
        v_operation.status,
        v_operation.phase,
        v_operation.actor_user_id,
