      join public.pay_batch_candidates as pay_batch_candidate_for_breakdown_page
        on pay_batch_candidate_for_breakdown_page.id = pay_batch_item_for_breakdown_page.pay_batch_candidate_id
      where pay_batch_candidate_for_breakdown_page.pay_batch_id = p_pay_batch_id
        and (v_cursor_id is null or pay_batch_breakdown_page.id > v_cursor_id)
      order by pay_batch_breakdown_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(
        jsonb_build_object(
          'id', page_rows.id::text,
          'pay_batch_item_id', page_rows.pay_batch_item_id::text,
          'pay_batch_candidate_id', page_rows.pay_batch_candidate_id::text,
          'candidate_id', page_rows.candidate_id::text,
          'line_kind', page_rows.line_kind,
          'bucket_code', page_rows.bucket_code,
          'unit_name', page_rows.unit_name,
          'units', page_rows.units,
          'rate', page_rows.rate,
          'amount_ex_vat', page_rows.amount_ex_vat,
          'amount_vat', page_rows.amount_vat,
          'amount_inc_vat', page_rows.amount_inc_vat,
          'meta_json', coalesce(page_rows.meta_json, '{}'::jsonb),
          'operation_source_key', page_rows.operation_source_key,
          'created_at_utc', page_rows.created_at_utc,
          'payment_lifecycle_state', breakdown_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state',
          'payment_lifecycle_label', CASE COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', '')
            WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
            WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
            WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
            WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
            WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check provider'
            WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Failed — not paid'
            WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Failed — not paid'
            WHEN 'PAID_OR_SETTLED' THEN CASE
              WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
              ELSE 'Paid'
            END
            WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
            WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
            WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
            ELSE COALESCE(NULLIF(breakdown_payment_diagnostic.diagnostic_json->>'payment_lifecycle_label', ''), initcap(replace(lower(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', 'unknown')), '_', ' ')))
          END,
          'recommended_action', breakdown_payment_diagnostic.diagnostic_json->>'recommended_action',
          'row_action', CASE
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
            ELSE breakdown_payment_diagnostic.diagnostic_json->>'recommended_action'
          END,
          'row_action_label', CASE
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
            ELSE 'View details'
          END,
          'selectable', CASE
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' IN (
              'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
              'NO_MONEY_UNWIND_AND_RECALCULATE',
              'CHECK_PROVIDER_STATUS',
              'AMEND_AND_RECOVER_OVERPAYMENT'
            ) THEN true
            ELSE false
          END,
          'selection_disabled_reason', CASE
            WHEN breakdown_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Use Overview to retry unsent payments.'
            WHEN NULLIF(BTRIM(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'recommended_action', '')), '') IS NULL THEN 'No row action available.'
            ELSE NULL::text
          END,
          'row_cancel_available', lower(btrim(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
          'can_no_money_unwind', lower(btrim(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
          'can_recover_overpayment', lower(btrim(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustment_carry_forward_required', lower(btrim(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustments_to_carry_forward', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
          'manual_adjustments_carried_forward', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
          'carry_forward_blockers', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
          'blocking_paid_evidence_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
          'terminal_no_money_evidence_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
          'pending_provider_evidence_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
          'resolved_full_payment_scope_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
          'finance_scope_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
          'provider_failure_reason_group', NULLIF(BTRIM(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
          'provider_failure_reason_label', NULLIF(BTRIM(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), ''),
          'status_update_signature', NULLIF(BTRIM(COALESCE(breakdown_payment_diagnostic.diagnostic_json->>'status_update_signature', breakdown_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
          'provider_outcome_unknown_evidence_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
          'provider_webhook_evidence_json', COALESCE(breakdown_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
          'stable_scope_key', 'item_breakdown:' || page_rows.id::text,
          'selection_scope_key', 'item_breakdown:' || page_rows.id::text
        )
        order by page_rows.id asc
      ), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows
    left join lateral (
      select public.pay_payment_cancelability_diagnostic(
        p_pay_batch_id,
        jsonb_strip_nulls(jsonb_build_object(
          'scope_type', 'ITEMS',
          'pay_batch_item_ids', jsonb_build_array(page_rows.pay_batch_item_id::text),
          'pay_batch_candidate_ids', jsonb_build_array(page_rows.pay_batch_candidate_id::text),
          'candidate_ids', jsonb_build_array(page_rows.candidate_id::text),
          'timesheet_ids', CASE WHEN page_rows.timesheet_id IS NULL THEN NULL ELSE jsonb_build_array(page_rows.timesheet_id::text) END,
          'pay_bank_transfer_ids', CASE WHEN page_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE jsonb_build_array(page_rows.pay_bank_transfer_id::text) END,
          'finance_case_ids', CASE WHEN page_rows.finance_case_id IS NULL THEN NULL ELSE jsonb_build_array(page_rows.finance_case_id::text) END,
          'finance_component_ids', CASE WHEN page_rows.finance_component_id IS NULL THEN NULL ELSE jsonb_build_array(page_rows.finance_component_id::text) END
        )),
        p_actor_user_id
      ) as diagnostic_json
    ) as breakdown_payment_diagnostic on true;

  elsif v_section in ('transfers', 'current_payment_status') then
    v_known_total_count := null;

    with page_rows as (
      select
        transfer_page.id,
        transfer_page.pay_batch_id,
        transfer_page.candidate_id,
        transfer_page.umbrella_id,
        transfer_page.pay_channel,
        transfer_page.amount,
        transfer_page.currency,
        transfer_page.status,
        transfer_page.payment_reference,
        transfer_page.payee_name,
        transfer_page.sort_code,
        transfer_page.account_number,
        transfer_page.account_type,
        transfer_page.created_at_utc,
        transfer_page.completed_at_utc,
        transfer_page.failed_reason,
        transfer_page.rail_provider,
        transfer_page.rail_env,
        transfer_page.request_id,
        transfer_page.rail_tx_id,
        transfer_page.rail_state,
        transfer_page.rail_meta_json,
        transfer_page.bank_details_hash_snapshot,
        transfer_page.payee_entity_kind,
        transfer_page.payee_entity_id,
        transfer_page.transfer_group_key,
        transfer_page.grouping_mode_used,
        transfer_page.week_ending_bucket,
        (
          (
            lower(btrim(coalesce(transfer_page.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) in ('true', 't', '1', 'yes', 'y', 'on')
            and exists (
              select 1
              from (values
                (transfer_page.rail_tx_id),
                (transfer_page.rail_meta_json #>> '{provider_event_id}'),
                (transfer_page.rail_meta_json #>> '{provider_reference}'),
                (transfer_page.rail_meta_json #>> '{provider_submission_id}'),
                (transfer_page.rail_meta_json #>> '{submission_id}'),
                (transfer_page.rail_meta_json #>> '{rail_submission_id}'),
                (transfer_page.rail_meta_json #>> '{provider_payment_id}'),
                (transfer_page.rail_meta_json #>> '{payment_id}'),
                (transfer_page.rail_meta_json #>> '{external_payment_id}'),
                (transfer_page.rail_meta_json #>> '{revolut_payment_id}'),
                (transfer_page.rail_meta_json #>> '{provider_transfer_id}'),
                (transfer_page.rail_meta_json #>> '{transfer_id}'),
                (transfer_page.rail_meta_json #>> '{external_transfer_id}'),
                (transfer_page.rail_meta_json #>> '{provider_transaction_id}'),
                (transfer_page.rail_meta_json #>> '{transaction_id}')
              ) as transfer_identifier(identifier_value)
              where nullif(btrim(coalesce(transfer_identifier.identifier_value, '')), '') is not null
                and not (
                  nullif(btrim(coalesce(transfer_identifier.identifier_value, '')), '') = any(
                    array_remove(array[
                      transfer_page.id::text,
                      nullif(btrim(coalesce(transfer_page.request_id, '')), ''),
                      nullif(btrim(coalesce(transfer_page.payment_reference, '')), ''),
                      nullif(btrim(coalesce(transfer_page.transfer_group_key, '')), ''),
                      nullif(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                      nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{request_id}', '')), ''),
                      nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{payment_reference}', '')), ''),
                      nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{bulk_reference}', '')), '')
                    ]::text[], null::text)
                  )
                )
            )
          )
          or exists (
            select 1
            from public.pay_bank_transfer_events as provider_event_page
            where provider_event_page.pay_batch_id = p_pay_batch_id
              and provider_event_page.pay_bank_transfer_id = transfer_page.id
              and upper(btrim(coalesce(provider_event_page.event_source, ''))) in ('PROVIDER_RESPONSE','PROVIDER_POLL','PROVIDER_WEBHOOK','WEBHOOK','POLL','RAIL_PROVIDER','PROVIDER','PROVIDER_SETTLEMENT')
              and exists (
                select 1
                from (values
                  (provider_event_page.provider_event_id),
                  (provider_event_page.provider_reference),
                  (provider_event_page.raw_payload #>> '{provider_event_id}'),
                  (provider_event_page.raw_payload #>> '{provider_reference}'),
                  (provider_event_page.raw_payload #>> '{provider_submission_id}'),
                  (provider_event_page.raw_payload #>> '{submission_id}'),
                  (provider_event_page.raw_payload #>> '{rail_submission_id}'),
                  (provider_event_page.raw_payload #>> '{provider_payment_id}'),
                  (provider_event_page.raw_payload #>> '{payment_id}'),
                  (provider_event_page.raw_payload #>> '{external_payment_id}'),
                  (provider_event_page.raw_payload #>> '{revolut_payment_id}'),
                  (provider_event_page.raw_payload #>> '{provider_transfer_id}'),
                  (provider_event_page.raw_payload #>> '{transfer_id}'),
                  (provider_event_page.raw_payload #>> '{external_transfer_id}'),
                  (provider_event_page.raw_payload #>> '{provider_transaction_id}'),
                  (provider_event_page.raw_payload #>> '{transaction_id}')
                ) as provider_identifier(identifier_value)
                where nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') is not null
                  and not (
                    nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') = any(
                      array_remove(array[
                        transfer_page.id::text,
                        nullif(btrim(coalesce(transfer_page.request_id, '')), ''),
                        nullif(btrim(coalesce(transfer_page.payment_reference, '')), ''),
                        nullif(btrim(coalesce(transfer_page.transfer_group_key, '')), ''),
                        nullif(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                        nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{request_id}', '')), ''),
                        nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{idempotency_key}', '')), ''),
                        nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{payment_reference}', '')), ''),
                        nullif(btrim(coalesce(transfer_page.rail_meta_json #>> '{bulk_reference}', '')), '')
                      ]::text[], null::text)
                    )
                  )
              )
          )
        ) as has_provider_evidence
      from public.pay_bank_transfers as transfer_page
      where transfer_page.pay_batch_id = p_pay_batch_id
        and (v_cursor_id is null or transfer_page.id > v_cursor_id)
      order by transfer_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(
        jsonb_build_object(
          'id', page_rows.id::text,
          'pay_batch_id', page_rows.pay_batch_id::text,
          'candidate_id', case when page_rows.candidate_id is null then null else page_rows.candidate_id::text end,
          'umbrella_id', case when page_rows.umbrella_id is null then null else page_rows.umbrella_id::text end,
          'pay_channel', page_rows.pay_channel,
          'amount', page_rows.amount,
          'currency', page_rows.currency,
          'status', page_rows.status,
          'payment_reference', page_rows.payment_reference,
          'payee_name', page_rows.payee_name,
          'sort_code', page_rows.sort_code,
          'account_number', page_rows.account_number,
          'account_type', page_rows.account_type,
          'created_at_utc', page_rows.created_at_utc,
          'completed_at_utc', page_rows.completed_at_utc,
          'failed_reason', page_rows.failed_reason,
          'rail_provider', page_rows.rail_provider,
          'rail_env', page_rows.rail_env,
          'request_id', page_rows.request_id,
          'rail_tx_id', page_rows.rail_tx_id,
          'rail_state', page_rows.rail_state,
          'rail_meta_json', coalesce(page_rows.rail_meta_json, '{}'::jsonb),
          'bank_details_hash_snapshot', page_rows.bank_details_hash_snapshot,
          'payee_entity_kind', page_rows.payee_entity_kind,
          'payee_entity_id', case when page_rows.payee_entity_id is null then null else page_rows.payee_entity_id::text end,
          'transfer_group_key', page_rows.transfer_group_key,
          'grouping_mode_used', page_rows.grouping_mode_used,
          'week_ending_bucket', case when page_rows.week_ending_bucket is null then null else page_rows.week_ending_bucket::text end,
          'has_provider_evidence', page_rows.has_provider_evidence
        ) || jsonb_build_object(
          'payment_lifecycle_state', transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state',
          'payment_lifecycle_label', CASE COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', '')
            WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
            WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'Scheduled — not sent to bank yet'
            WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'Sent to bank — pending outcome'
            WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'Bank unavailable — retry available'
            WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown — check provider'
            WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'Failed — not paid'
            WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'Failed — not paid'
            WHEN 'PAID_OR_SETTLED' THEN CASE
              WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
              ELSE 'Paid'
            END
            WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Cancelled before bank submission'
            WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'Partially cancelled before bank submission'
            WHEN 'FINANCIALS_REWOUND' THEN 'Financials rewound'
            ELSE COALESCE(NULLIF(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_label', ''), initcap(replace(lower(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'payment_lifecycle_state', 'unknown')), '_', ' ')))
          END,
          'recommended_action', transfer_payment_diagnostic.diagnostic_json->>'recommended_action',
          'row_action', CASE
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'OPEN_RETRY_SUMMARY'
            ELSE transfer_payment_diagnostic.diagnostic_json->>'recommended_action'
          END,
          'row_action_label', CASE
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Open retry summary'
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN 'Recover overpayment in next pay run'
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'Rewind financials'
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'CHECK_PROVIDER_STATUS' THEN 'Check provider status'
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'Cancel this payment and recalculate'
            ELSE 'View details'
          END,
          'selectable', CASE
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' IN (
              'PRE_PROVIDER_CANCEL_AND_RECALCULATE',
              'NO_MONEY_UNWIND_AND_RECALCULATE',
              'CHECK_PROVIDER_STATUS',
              'AMEND_AND_RECOVER_OVERPAYMENT'
            ) THEN true
            ELSE false
          END,
          'selection_disabled_reason', CASE
            WHEN transfer_payment_diagnostic.diagnostic_json->>'recommended_action' = 'RETRY_PROVIDER_LATER' THEN 'Use Overview to retry unsent payments.'
            WHEN NULLIF(BTRIM(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'recommended_action', '')), '') IS NULL THEN 'No row action available.'
            ELSE NULL::text
          END,
          'row_cancel_available', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'row_cancel_available', 'false'))) IN ('true','1','yes','y','on'),
          'can_no_money_unwind', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_no_money_unwind', 'false'))) IN ('true','1','yes','y','on'),
          'can_recover_overpayment', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'can_recover_overpayment', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustment_carry_forward_required', lower(btrim(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'manual_adjustment_carry_forward_required', 'false'))) IN ('true','1','yes','y','on'),
          'manual_adjustments_to_carry_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
          'manual_adjustments_carried_forward', COALESCE(transfer_payment_diagnostic.diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
          'carry_forward_blockers', COALESCE(transfer_payment_diagnostic.diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
          'blocking_paid_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
          'terminal_no_money_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
          'pending_provider_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
          'resolved_full_payment_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
          'finance_scope_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'finance_scope_json', '{}'::jsonb),
          'provider_failure_reason_group', NULLIF(BTRIM(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_group', '')), ''),
          'provider_failure_reason_label', NULLIF(BTRIM(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'provider_failure_reason_label', '')), ''),
          'status_update_signature', NULLIF(BTRIM(COALESCE(transfer_payment_diagnostic.diagnostic_json->>'status_update_signature', transfer_payment_diagnostic.diagnostic_json->>'live_status_signature', '')), ''),
          'provider_outcome_unknown_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
          'provider_webhook_evidence_json', COALESCE(transfer_payment_diagnostic.diagnostic_json->'provider_webhook_evidence_json', '{}'::jsonb),
          'stable_scope_key', 'transfer:' || page_rows.id::text,
          'selection_scope_key', 'transfer:' || page_rows.id::text
        )
        order by page_rows.id asc
      ), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows
    left join lateral (
      select public.pay_payment_cancelability_diagnostic(
        p_pay_batch_id,
        jsonb_build_object(
          'scope_type', 'TRANSFER',
          'pay_bank_transfer_ids', jsonb_build_array(page_rows.id::text)
        ),
        p_actor_user_id
      ) as diagnostic_json
    ) as transfer_payment_diagnostic on true;

  elsif v_section = 'finance_case_groups' then
    v_known_total_count := null;

    with page_group_keys as (
      select finance_group_keys.group_id
      from (
        select coalesce(pay_batch_item_key.finance_case_id, pay_batch_item_key.finance_component_id) as group_id
        from public.pay_batch_items as pay_batch_item_key
        join public.pay_batch_candidates as pay_batch_candidate_key
          on pay_batch_candidate_key.id = pay_batch_item_key.pay_batch_candidate_id
        where pay_batch_candidate_key.pay_batch_id = p_pay_batch_id
          and (pay_batch_item_key.finance_case_id is not null or pay_batch_item_key.finance_component_id is not null)
        group by coalesce(pay_batch_item_key.finance_case_id, pay_batch_item_key.finance_component_id)
      ) as finance_group_keys
      where v_cursor_id is null or finance_group_keys.group_id > v_cursor_id
      order by finance_group_keys.group_id asc
      limit (v_limit + 1)
    ),
    page_rows as (
      select
        page_group_keys.group_id,
        (array_agg(pay_batch_item_finance_page.finance_case_id ORDER BY pay_batch_item_finance_page.finance_case_id::text) FILTER (WHERE pay_batch_item_finance_page.finance_case_id IS NOT NULL))[1] AS finance_case_id,
        (array_agg(pay_batch_item_finance_page.finance_component_id ORDER BY pay_batch_item_finance_page.finance_component_id::text) FILTER (WHERE pay_batch_item_finance_page.finance_component_id IS NOT NULL))[1] AS finance_component_id,
        count(*)::integer as item_count,
        round(sum(coalesce(pay_batch_item_finance_page.amount_ex_vat, 0)), 2)::numeric as total_amount_ex_vat,
        coalesce(jsonb_agg(distinct pay_batch_item_finance_page.item_type) filter (where pay_batch_item_finance_page.item_type is not null), '[]'::jsonb) as item_types,
        coalesce(jsonb_agg(distinct pay_batch_candidate_finance_page.candidate_id::text) filter (where pay_batch_candidate_finance_page.candidate_id is not null), '[]'::jsonb) as candidate_ids
      from page_group_keys
      join public.pay_batch_items as pay_batch_item_finance_page
        on coalesce(pay_batch_item_finance_page.finance_case_id, pay_batch_item_finance_page.finance_component_id) = page_group_keys.group_id
      join public.pay_batch_candidates as pay_batch_candidate_finance_page
        on pay_batch_candidate_finance_page.id = pay_batch_item_finance_page.pay_batch_candidate_id
      where pay_batch_candidate_finance_page.pay_batch_id = p_pay_batch_id
      group by page_group_keys.group_id
    )
    select
      coalesce(jsonb_agg(
        jsonb_build_object(
          'group_id', page_rows.group_id::text,
          'finance_case_id', case when page_rows.finance_case_id is null then null else page_rows.finance_case_id::text end,
          'finance_component_id', case when page_rows.finance_component_id is null then null else page_rows.finance_component_id::text end,
          'item_count', page_rows.item_count,
          'total_amount_ex_vat', page_rows.total_amount_ex_vat,
          'item_types', page_rows.item_types,
          'candidate_ids', page_rows.candidate_ids
        )
        order by page_rows.group_id asc
      ), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.group_id order by page_rows.group_id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows;

  elsif v_section = 'remittances' then
    v_known_total_count := null;

    with page_rows as (
      select
        mail_outbox_page.id,
        mail_outbox_page.type,
        mail_outbox_page.to,
        mail_outbox_page.cc,
        mail_outbox_page.bcc,
        mail_outbox_page.subject,
        mail_outbox_page.status,
        mail_outbox_page.provider_status,
        mail_outbox_page.recipient_kind,
        mail_outbox_page.recipient_id,
        mail_outbox_page.context_kind,
        mail_outbox_page.context_id,
        mail_outbox_page.reference,
        mail_outbox_page.created_at_utc,
        mail_outbox_page.sent_at,
        mail_outbox_page.failed_at,
        mail_outbox_page.last_error,
        mail_outbox_page.deterministic_outbox_key
      from public.mail_outbox as mail_outbox_page
      where (
           mail_outbox_page.payment_scope_json->>'pay_batch_id' = p_pay_batch_id::text
        or (lower(coalesce(mail_outbox_page.context_kind, '')) in ('pay_batch', 'pay_batches') and mail_outbox_page.context_id = p_pay_batch_id)
        or mail_outbox_page.reference = p_pay_batch_id::text
      )
        and (v_cursor_id is null or mail_outbox_page.id > v_cursor_id)
      order by mail_outbox_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(to_jsonb(page_rows) order by page_rows.id asc), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows;

  elsif v_section = 'communications' then
    v_known_total_count := null;

    with page_rows as (
      select
        comms_outbox_page.id,
        comms_outbox_page.channel,
        comms_outbox_page.status,
        comms_outbox_page.to_address,
        comms_outbox_page.provider_key,
        comms_outbox_page.provider_message_id,
        comms_outbox_page.recipient_kind,
        comms_outbox_page.recipient_id,
        comms_outbox_page.context_kind,
        comms_outbox_page.context_id,
        comms_outbox_page.created_at_utc,
        comms_outbox_page.sent_at,
        comms_outbox_page.delivered_at,
        comms_outbox_page.read_at,
        comms_outbox_page.failed_at,
        comms_outbox_page.last_error,
        comms_outbox_page.deterministic_outbox_key
      from public.comms_outbox as comms_outbox_page
      where (
           (lower(coalesce(comms_outbox_page.context_kind, '')) in ('pay_batch', 'pay_batches') and comms_outbox_page.context_id = p_pay_batch_id)
        or comms_outbox_page.provider_payload_json->>'pay_batch_id' = p_pay_batch_id::text
        or comms_outbox_page.provider_response_json->>'pay_batch_id' = p_pay_batch_id::text
      )
        and (v_cursor_id is null or comms_outbox_page.id > v_cursor_id)
      order by comms_outbox_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(to_jsonb(page_rows) order by page_rows.id asc), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows;

  elsif v_section = 'auth_history' then
    v_known_total_count := null;

    with page_rows as (
      select
        auth_request_page.id,
        auth_request_page.pay_batch_id,
        auth_request_page.requested_by_user_id,
        auth_request_page.required_quantity,
        auth_request_page.schedule_kind,
        auth_request_page.scheduled_at_utc,
        auth_request_page.funding_account_ref,
        auth_request_page.state,
        auth_request_page.golden_key_used,
        auth_request_page.golden_key_user_id,
        auth_request_page.created_at_utc,
        auth_request_page.finalised_at_utc,
        auth_request_page.finalised_by_user_id,
        auth_request_page.execution_intent_json
      from public.pay_batch_auth_requests as auth_request_page
      where auth_request_page.pay_batch_id = p_pay_batch_id
        and (v_cursor_id is null or auth_request_page.id > v_cursor_id)
      order by auth_request_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(to_jsonb(page_rows) order by page_rows.id asc), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows;

  elsif v_section = 'events' then
    v_known_total_count := null;

    with page_rows as (
      select
        transfer_event_page.id,
        transfer_event_page.pay_batch_id,
        transfer_event_page.pay_bank_transfer_id,
        transfer_event_page.candidate_id,
        transfer_event_page.umbrella_id,
        transfer_event_page.provider_key,
        transfer_event_page.provider_event_id,
        transfer_event_page.provider_reference,
        transfer_event_page.provider_state,
        transfer_event_page.normalised_state,
        transfer_event_page.event_source,
        transfer_event_page.event_time_utc,
        transfer_event_page.received_at_utc,
        transfer_event_page.amount,
        transfer_event_page.currency,
        transfer_event_page.mapping_status,
        transfer_event_page.movement_classification,
        transfer_event_page.correction_disposition,
        transfer_event_page.mapping_method,
        transfer_event_page.created_at_utc
      from public.pay_bank_transfer_events as transfer_event_page
      where transfer_event_page.pay_batch_id = p_pay_batch_id
        and (v_cursor_id is null or transfer_event_page.id > v_cursor_id)
      order by transfer_event_page.id asc
      limit (v_limit + 1)
    )
    select
      coalesce(jsonb_agg(to_jsonb(page_rows) order by page_rows.id asc), '[]'::jsonb),
      count(*)::integer,
      (array_agg(page_rows.id order by page_rows.id desc))[1]
    into v_items, v_returned_count, v_last_id
    from page_rows;
  end if;

  if coalesce(v_returned_count, 0) > v_limit then
    v_next_cursor := jsonb_build_object(
      'last_id',
      coalesce(
        v_items -> (v_limit - 1) ->> 'id',
        v_items -> (v_limit - 1) ->> 'group_id'
      )
    );

    select coalesce(jsonb_agg(trimmed_items.value order by trimmed_items.ordinality), '[]'::jsonb)
    into v_items
    from jsonb_array_elements(coalesce(v_items, '[]'::jsonb)) with ordinality as trimmed_items(value, ordinality)
    where trimmed_items.ordinality <= v_limit;

    v_returned_count := v_limit;
  else
    v_next_cursor := null;
    v_returned_count := coalesce(v_returned_count, 0);
  end if;

  v_section_page_signature := 'pay_batch_section_page:v1:' || md5(
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'section', v_section,
      'items', COALESCE(v_items, '[]'::jsonb),
      'next_cursor', v_next_cursor,
      'live_signal_version', COALESCE(v_live_signal_version, 0),
      'payment_status_version', COALESCE(v_payment_status_version, 0),
      'correction_progress_version', COALESCE(v_correction_progress_version, 0),
      'overview_version', COALESCE(v_overview_version, 0)
    )::text
  );

  return jsonb_build_object(
    'section', v_section,
    'items', coalesce(v_items, '[]'::jsonb),
    'next_cursor', v_next_cursor,
    'returned_count', coalesce(v_returned_count, 0),
    'known_total_count', v_known_total_count,
    'pay_batch_id', p_pay_batch_id::text,
    'server_time_utc', v_server_time_utc::text,
    'section_page_signature', v_section_page_signature,
    'live_signal_version', COALESCE(v_live_signal_version, 0),
    'payment_status_version', COALESCE(v_payment_status_version, 0),
    'correction_progress_version', COALESCE(v_correction_progress_version, 0),
    'alert_version', COALESCE(v_alert_version, 0),
    'overview_version', COALESCE(v_overview_version, 0),
    'last_status_hash', v_last_status_hash,
    'last_alert_hash', v_last_alert_hash,
    'known_live_signal_version', v_known_live_signal_version,
    'changed_since_version', COALESCE(v_changed_since_version, false),
    'batch_status', v_batch_status,
    'execution_commit_state', v_execution_commit_state,
    'freshness', v_freshness_summary,
    'limit', v_limit
  );
end;
$$;



create or replace function public.pay_batch_freshness_result_get(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_actor_user_id uuid default null::uuid
)
returns jsonb
language plpgsql
security definer
volatile
set search_path = public, pg_temp
as $$
declare
  v_operation public.banking_pay_operations%rowtype;
  v_batch public.pay_batches%rowtype;
  v_actor_is_valid boolean := true;
  v_total_chunk_count integer := 0;
  v_pending_chunk_count integer := 0;
  v_running_chunk_count integer := 0;
  v_failed_chunk_count integer := 0;
  v_complete_chunk_count integer := 0;
  v_validation_complete boolean := false;
  v_is_stale boolean := false;
  v_checked_count integer := 0;
  v_stale_count integer := 0;
  v_failed_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_stale_reason_counts jsonb := '{}'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_checked_at_utc timestamptz := now();
  v_scope_hash text := null;
  v_result_hash text := null;
  v_status text := 'PENDING';
  v_result jsonb := '{}'::jsonb;
  v_hash_basis jsonb := '{}'::jsonb;
  v_chunk_result_hashes jsonb := '[]'::jsonb;
  v_failed_sample jsonb := '[]'::jsonb;
begin
  if p_operation_id is null then
    raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_ID_REQUIRED')::text;
  end if;

  if p_pay_batch_id is null then
    raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object('code', 'PAY_BATCH_FRESHNESS_RESULT_GET_PAY_BATCH_ID_REQUIRED')::text;
  end if;

  select operation_row.*
  into v_operation
  from public.banking_pay_operations as operation_row
  where operation_row.id = p_operation_id
  for update;

  if not found then
    raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_NOT_FOUND',
              'operation_id', p_operation_id::text
            )::text;
  end if;

  if v_operation.pay_batch_id is not null and v_operation.pay_batch_id <> p_pay_batch_id then
    raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_OPERATION_BATCH_MISMATCH',
              'operation_id', p_operation_id::text,
              'operation_pay_batch_id', v_operation.pay_batch_id::text,
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  end if;

  select pay_batch_row.*
  into v_batch
  from public.pay_batches as pay_batch_row
  where pay_batch_row.id = p_pay_batch_id
  for update;

  if not found then
    raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id::text
            )::text;
  end if;

  if p_actor_user_id is not null then
    select exists (
      select 1
      from public.tms_users as actor_user
      where actor_user.id = p_actor_user_id
        and coalesce(actor_user.is_active, false) = true
    )
    into v_actor_is_valid;

    if coalesce(v_actor_is_valid, false) is not true then
      raise exception 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED'
        using errcode = 'P0001',
              detail = jsonb_build_object(
                'code', 'PAY_BATCH_FRESHNESS_RESULT_GET_ACTOR_NOT_ALLOWED',
                'actor_user_id', p_actor_user_id::text
              )::text;
    end if;
  end if;

  select
    count(*)::integer,
    count(*) filter (where chunk_row.status = 'PENDING')::integer,
    count(*) filter (where chunk_row.status = 'RUNNING')::integer,
    count(*) filter (where chunk_row.status = 'FAILED')::integer,
    count(*) filter (where chunk_row.status = 'COMPLETE')::integer
  into
    v_total_chunk_count,
    v_pending_chunk_count,
    v_running_chunk_count,
    v_failed_chunk_count,
    v_complete_chunk_count
  from public.banking_pay_operation_chunks as chunk_row
  where chunk_row.operation_id = p_operation_id
    and chunk_row.phase = 'VALIDATE_FRESHNESS'
    and chunk_row.chunk_type = 'FRESHNESS_VALIDATE';

  if coalesce(v_total_chunk_count, 0) = 0 then
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'reason', 'NO_FRESHNESS_CHUNKS',
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text
    );

    return v_result;
  end if;

  v_validation_complete := coalesce(v_pending_chunk_count, 0) = 0
    and coalesce(v_running_chunk_count, 0) = 0;

  v_scope_hash := nullif(btrim(coalesce(v_operation.progress_json->>'freshness_scope_hash', v_batch.freshness_scope_hash, '')), '');

  if v_validation_complete is not true then
    v_result := jsonb_build_object(
      'validation_complete', false,
      'is_stale', false,
      'status', 'PENDING',
      'pending_count', coalesce(v_pending_chunk_count, 0),
      'running_count', coalesce(v_running_chunk_count, 0),
      'complete_count', coalesce(v_complete_chunk_count, 0),
      'failed_count', coalesce(v_failed_chunk_count, 0),
      'checked_count', 0,
      'stale_count', 0,
      'key_resolution_failure_count', 0,
      'diff_sample', '[]'::jsonb,
      'freshness_checked_at_utc', null,
      'freshness_result_hash', null,
      'freshness_scope_hash', v_scope_hash,
      'operation_id', p_operation_id::text
    );

    return v_result;
  end if;

  with chunk_results as (
    select
      chunk_row.id,
      chunk_row.status,
      coalesce(chunk_row.result_json, '{}'::jsonb) as result_json,
      coalesce(chunk_row.error_json, '{}'::jsonb) as error_json
    from public.banking_pay_operation_chunks as chunk_row
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
  ),
  counts as (
    select
      sum(coalesce((chunk_results.result_json->>'checked_count')::integer, 0))::integer as checked_count,
      sum(coalesce((chunk_results.result_json->>'stale_count')::integer, 0))::integer as stale_count,
      sum(coalesce((chunk_results.result_json->>'key_resolution_failure_count')::integer, 0))::integer as key_resolution_failure_count,
      count(*) filter (where chunk_results.status = 'FAILED')::integer as failed_count,
      bool_or(coalesce((chunk_results.result_json->>'is_stale')::boolean, false)) as any_stale,
      bool_or(chunk_results.status = 'FAILED') as any_failed
    from chunk_results
  )
  select
    coalesce(counts.checked_count, 0),
    coalesce(counts.stale_count, 0),
    coalesce(counts.key_resolution_failure_count, 0),
    coalesce(counts.failed_count, 0),
    coalesce(counts.any_stale, false) or coalesce(counts.any_failed, false) or coalesce(counts.key_resolution_failure_count, 0) > 0
  into
    v_checked_count,
    v_stale_count,
    v_key_resolution_failure_count,
    v_failed_count,
    v_is_stale
  from counts;

  with reason_values as (
    select distinct reason_text.reason_value
    from public.banking_pay_operation_chunks as chunk_row
    cross join lateral jsonb_array_elements_text(coalesce(chunk_row.result_json->'stale_reasons', '[]'::jsonb)) as reason_text(reason_value)
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      and chunk_row.result_json is not null
  )
  select coalesce(jsonb_agg(reason_values.reason_value order by reason_values.reason_value), '[]'::jsonb)
  into v_stale_reasons
  from reason_values;

  with reason_pairs as (
    select
      reason_entry.key as reason_key,
      sum(coalesce(reason_entry.value::text::integer, 0))::integer as reason_count
    from public.banking_pay_operation_chunks as chunk_row
    cross join lateral jsonb_each(coalesce(chunk_row.result_json->'stale_reason_counts', '{}'::jsonb)) as reason_entry(key, value)
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      and chunk_row.result_json is not null
    group by reason_entry.key
  )
  select coalesce(jsonb_object_agg(reason_pairs.reason_key, reason_pairs.reason_count order by reason_pairs.reason_key), '{}'::jsonb)
  into v_stale_reason_counts
  from reason_pairs;

  with diff_items as (
    select
      chunk_row.sequence_no,
      diff_item.diff_value
    from public.banking_pay_operation_chunks as chunk_row
    cross join lateral jsonb_array_elements(coalesce(chunk_row.result_json->'diff_sample', '[]'::jsonb)) as diff_item(diff_value)
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      and chunk_row.result_json is not null
    order by chunk_row.sequence_no, diff_item.diff_value::text
    limit 50
  )
  select coalesce(jsonb_agg(diff_items.diff_value order by diff_items.sequence_no, diff_items.diff_value::text), '[]'::jsonb)
  into v_diff_sample
  from diff_items;

  with chunk_hash_rows as (
    select
      chunk_row.sequence_no,
      nullif(btrim(coalesce(chunk_row.result_json->>'chunk_result_hash', '')), '') as chunk_result_hash
    from public.banking_pay_operation_chunks as chunk_row
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      and nullif(btrim(coalesce(chunk_row.result_json->>'chunk_result_hash', '')), '') is not null
    order by chunk_row.sequence_no
  )
  select coalesce(jsonb_agg(chunk_hash_rows.chunk_result_hash order by chunk_hash_rows.sequence_no), '[]'::jsonb)
  into v_chunk_result_hashes
  from chunk_hash_rows;

  with failed_rows as (
    select
      chunk_row.sequence_no,
      jsonb_build_object(
        'chunk_id', chunk_row.id::text,
        'sequence_no', chunk_row.sequence_no,
        'error', coalesce(chunk_row.error_json, '{}'::jsonb)
      ) as failed_json
    from public.banking_pay_operation_chunks as chunk_row
    where chunk_row.operation_id = p_operation_id
      and chunk_row.phase = 'VALIDATE_FRESHNESS'
      and chunk_row.chunk_type = 'FRESHNESS_VALIDATE'
      and chunk_row.status = 'FAILED'
    order by chunk_row.sequence_no
    limit 20
  )
  select coalesce(jsonb_agg(failed_rows.failed_json order by failed_rows.sequence_no), '[]'::jsonb)
  into v_failed_sample
  from failed_rows;

  if coalesce(v_failed_count, 0) > 0 and not (coalesce(v_stale_reasons, '[]'::jsonb) ? 'CHUNK_FAILED') then
    v_stale_reasons := coalesce(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('CHUNK_FAILED');
    v_stale_reason_counts := coalesce(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('CHUNK_FAILED', coalesce(v_failed_count, 0));
  end if;

  if coalesce(v_key_resolution_failure_count, 0) > 0 and not (coalesce(v_stale_reasons, '[]'::jsonb) ? 'KEY_RESOLUTION_FAILED') then
    v_stale_reasons := coalesce(v_stale_reasons, '[]'::jsonb) || jsonb_build_array('KEY_RESOLUTION_FAILED');
    v_stale_reason_counts := coalesce(v_stale_reason_counts, '{}'::jsonb) || jsonb_build_object('KEY_RESOLUTION_FAILED', coalesce(v_key_resolution_failure_count, 0));
  end if;

  if coalesce(v_failed_count, 0) > 0 then
    v_status := 'FAILED';
  elsif v_is_stale then
    v_status := 'STALE';
  else
    v_status := 'PASSED';
  end if;

  v_hash_basis := jsonb_build_object(
    'validation_complete', true,
    'is_stale', v_is_stale,
    'status', v_status,
    'stale_reasons', coalesce(v_stale_reasons, '[]'::jsonb),
    'stale_reason_counts', coalesce(v_stale_reason_counts, '{}'::jsonb),
    'checked_count', coalesce(v_checked_count, 0),
    'stale_count', coalesce(v_stale_count, 0),
    'failed_count', coalesce(v_failed_count, 0),
    'key_resolution_failure_count', coalesce(v_key_resolution_failure_count, 0),
    'diff_sample', coalesce(v_diff_sample, '[]'::jsonb),
    'failed_sample', coalesce(v_failed_sample, '[]'::jsonb),
    'freshness_scope_hash', v_scope_hash,
    'chunk_count', coalesce(v_total_chunk_count, 0),
    'complete_chunk_count', coalesce(v_complete_chunk_count, 0),
    'chunk_result_hashes', coalesce(v_chunk_result_hashes, '[]'::jsonb)
  );

  v_result_hash := md5(v_hash_basis::text);

  if v_batch.freshness_operation_id = p_operation_id
     and nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '') = v_result_hash
     and v_batch.freshness_checked_at_utc is not null then
    v_checked_at_utc := v_batch.freshness_checked_at_utc;
  end if;

  v_result := v_hash_basis || jsonb_build_object(
    'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
    'freshness_result_hash', v_result_hash,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text
  );

  update public.pay_batches as pay_batch_update
  set freshness_operation_id = p_operation_id,
      freshness_validation_status = v_status,
      freshness_checked_at_utc = v_checked_at_utc,
      freshness_result_hash = v_result_hash,
      freshness_scope_hash = v_scope_hash,
      freshness_result_json = jsonb_build_object(
        'validation_complete', true,
        'is_stale', v_is_stale,
        'status', v_status,
        'stale_reasons', coalesce(v_stale_reasons, '[]'::jsonb),
        'stale_reason_counts', coalesce(v_stale_reason_counts, '{}'::jsonb),
        'checked_count', coalesce(v_checked_count, 0),
        'stale_count', coalesce(v_stale_count, 0),
        'failed_count', coalesce(v_failed_count, 0),
        'key_resolution_failure_count', coalesce(v_key_resolution_failure_count, 0),
        'diff_sample', coalesce(v_diff_sample, '[]'::jsonb),
        'failed_sample', coalesce(v_failed_sample, '[]'::jsonb),
        'freshness_result_hash', v_result_hash,
        'freshness_scope_hash', v_scope_hash,
        'freshness_checked_at_utc', to_jsonb(v_checked_at_utc)
      )
  where pay_batch_update.id = p_pay_batch_id;

  update public.banking_pay_operations as operation_update
  set progress_json = coalesce(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'freshness_validation_status', v_status,
          'freshness_result_hash', v_result_hash,
          'freshness_scope_hash', v_scope_hash,
          'freshness_checked_at_utc', to_jsonb(v_checked_at_utc),
          'freshness_is_stale', v_is_stale
        ),
      result_json = coalesce(operation_update.result_json, '{}'::jsonb)
        || jsonb_build_object('freshness', v_result),
      updated_at_utc = now()
  where operation_update.id = p_operation_id;

  return v_result;
end;
$$;

CREATE OR REPLACE FUNCTION public.pay_bank_csv_export_summary_get(
    p_pay_batch_id uuid,
    p_scope text DEFAULT 'ALL'::text,
    p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
    v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
    v_batch_row public.pay_batches%ROWTYPE;
    v_batch_status_upper text := NULL;
    v_execution_commit_state text := 'NOT_SUBMITTED';
    v_execution_commit_ref text := NULL;
    v_execution_committed_at_utc timestamptz := NULL;
    v_pre_execution_export boolean := false;

    v_row_count integer := 0;
    v_total_amount numeric := 0;
    v_current_transfer_hash text := NULL;
    v_current_transfer_hash_basis text := NULL;

    v_pending_row_count integer := 0;
    v_pending_total_amount numeric := 0;
    v_pending_transfer_hash text := NULL;

    v_stable_row_count integer := 0;
    v_stable_total_amount numeric := 0;
    v_stable_transfer_hash text := NULL;

    v_blocked_row_count integer := 0;
    v_all_transfer_count integer := 0;
    v_pay_channels_included jsonb := '[]'::jsonb;
    v_status_counts jsonb := '{}'::jsonb;
    v_provider_counts jsonb := '{}'::jsonb;
    v_rail_env_counts jsonb := '{}'::jsonb;
    v_exportable_status_filter text := NULL;
    v_bank_csv_export_hash text := NULL;
BEGIN
    IF p_pay_batch_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_ID_REQUIRED',
            'message', 'pay_bank_csv_export_summary_get: pay_batch_id is required'
        )::text;
    END IF;

    IF v_scope NOT IN ('ALL', 'PAYE', 'UMBRELLA') THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'INVALID_SCOPE',
            'message', 'pay_bank_csv_export_summary_get: scope must be ALL, PAYE, or UMBRELLA',
            'scope', p_scope
        )::text;
    END IF;

    IF p_actor_user_id IS NOT NULL THEN
        PERFORM 1
        FROM public.tms_users AS actor_user
        WHERE actor_user.id = p_actor_user_id;

        IF NOT FOUND THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
                'code', 'ACTOR_USER_NOT_FOUND',
                'message', 'pay_bank_csv_export_summary_get: actor user was not found',
                'actor_user_id', p_actor_user_id::text,
                'pay_batch_id', p_pay_batch_id::text
            )::text;
        END IF;
    END IF;

    SELECT pay_batch.*
    INTO v_batch_row
    FROM public.pay_batches AS pay_batch
    WHERE pay_batch.id = p_pay_batch_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_BANK_CSV_EXPORT_SUMMARY_GET',
            'code', 'PAY_BATCH_NOT_FOUND',
            'message', 'pay_bank_csv_export_summary_get: pay batch was not found',
            'pay_batch_id', p_pay_batch_id::text
        )::text;
    END IF;

    v_batch_status_upper := upper(btrim(coalesce(v_batch_row.status, '')));
    v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));

    IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
        v_execution_commit_state := 'NOT_SUBMITTED';
    END IF;

    v_execution_commit_ref := nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '');
    v_execution_committed_at_utc := v_batch_row.execution_committed_at_utc;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_batch_row.bank_csv_export_json->>'transfer_hash', '')), '');

    v_pre_execution_export := (
        v_batch_row.cancelled_at_utc IS NULL
        AND v_batch_status_upper NOT IN ('CANCELLED', 'CANCELED')
        AND v_execution_commit_state = 'NOT_SUBMITTED'
        AND v_execution_commit_ref IS NULL
        AND v_execution_committed_at_utc IS NULL
    );

    SELECT
        count(*)::integer,
        round(coalesce(sum(CASE WHEN upper(coalesce(pending_transfer.status, '')) = 'PENDING' THEN pending_transfer.amount ELSE 0 END), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', pending_transfer.id,
                'candidate_id', pending_transfer.candidate_id,
                'umbrella_id', pending_transfer.umbrella_id,
                'pay_channel', pending_transfer.pay_channel,
                'amount', pending_transfer.amount,
                'currency', pending_transfer.currency,
                'payment_reference', pending_transfer.payment_reference,
                'payee_name', pending_transfer.payee_name,
                'sort_code_digits', pending_transfer.sort_code_digits,
                'account_number_digits', pending_transfer.account_number_digits,
                'account_type', pending_transfer.account_type,
                'bank_details_hash_snapshot', pending_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', pending_transfer.payee_entity_kind,
                'payee_entity_id', pending_transfer.payee_entity_id,
                'transfer_group_key', pending_transfer.transfer_group_key
            )
            ORDER BY pending_transfer.id
        )::text, '[]'))
    INTO
        v_pending_row_count,
        v_pending_total_amount,
        v_pending_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key,
            transfer_row.status AS status
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) = 'PENDING'
        ORDER BY transfer_row.id
    ) AS pending_transfer;

    SELECT
        count(*)::integer,
        round(coalesce(sum(stable_transfer.amount), 0), 2),
        md5(coalesce(jsonb_agg(
            jsonb_build_object(
                'id', stable_transfer.id,
                'candidate_id', stable_transfer.candidate_id,
                'umbrella_id', stable_transfer.umbrella_id,
                'pay_channel', stable_transfer.pay_channel,
                'amount', stable_transfer.amount,
                'currency', stable_transfer.currency,
                'payment_reference', stable_transfer.payment_reference,
                'payee_name', stable_transfer.payee_name,
                'sort_code_digits', stable_transfer.sort_code_digits,
                'account_number_digits', stable_transfer.account_number_digits,
                'account_type', stable_transfer.account_type,
                'bank_details_hash_snapshot', stable_transfer.bank_details_hash_snapshot,
                'payee_entity_kind', stable_transfer.payee_entity_kind,
                'payee_entity_id', stable_transfer.payee_entity_id,
                'transfer_group_key', stable_transfer.transfer_group_key
            )
            ORDER BY stable_transfer.id
        )::text, '[]'))
    INTO
        v_stable_row_count,
        v_stable_total_amount,
        v_stable_transfer_hash
    FROM (
        SELECT
            transfer_row.id::text AS id,
            CASE WHEN transfer_row.candidate_id IS NULL THEN NULL ELSE transfer_row.candidate_id::text END AS candidate_id,
            CASE WHEN transfer_row.umbrella_id IS NULL THEN NULL ELSE transfer_row.umbrella_id::text END AS umbrella_id,
            transfer_row.pay_channel AS pay_channel,
            round(transfer_row.amount, 2) AS amount,
            transfer_row.currency AS currency,
            transfer_row.payment_reference AS payment_reference,
            transfer_row.payee_name AS payee_name,
            regexp_replace(coalesce(transfer_row.sort_code, ''), '[^0-9]', '', 'g') AS sort_code_digits,
            regexp_replace(coalesce(transfer_row.account_number, ''), '[^0-9]', '', 'g') AS account_number_digits,
            transfer_row.account_type AS account_type,
            transfer_row.bank_details_hash_snapshot AS bank_details_hash_snapshot,
            transfer_row.payee_entity_kind AS payee_entity_kind,
            CASE WHEN transfer_row.payee_entity_id IS NULL THEN NULL ELSE transfer_row.payee_entity_id::text END AS payee_entity_id,
            transfer_row.transfer_group_key AS transfer_group_key
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED'
        ORDER BY transfer_row.id
    ) AS stable_transfer;

    IF v_pre_execution_export THEN
        v_row_count := coalesce(v_pending_row_count, 0);
        v_total_amount := coalesce(v_pending_total_amount, 0);
        v_current_transfer_hash := v_pending_transfer_hash;
        v_current_transfer_hash_basis := 'PENDING_TRANSFER_HASH';
        v_exportable_status_filter := 'PENDING';
    ELSE
        v_row_count := coalesce(v_stable_row_count, 0);
        v_total_amount := coalesce(v_stable_total_amount, 0);
        v_current_transfer_hash := v_stable_transfer_hash;
        v_current_transfer_hash_basis := 'STABLE_ALL_NON_BLOCKED_TRANSFER_HASH';
        v_exportable_status_filter := 'ALL_NON_BLOCKED';
    END IF;

    SELECT count(*)::integer
    INTO v_all_transfer_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope);

    SELECT count(*)::integer
    INTO v_blocked_row_count
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
      AND upper(coalesce(transfer_row.status, '')) = 'BLOCKED';

    SELECT coalesce(jsonb_agg(to_jsonb(pay_channel_values.pay_channel) ORDER BY pay_channel_values.pay_channel), '[]'::jsonb)
    INTO v_pay_channels_included
    FROM (
        SELECT DISTINCT upper(coalesce(transfer_row.pay_channel, '')) AS pay_channel
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
    ) AS pay_channel_values
    WHERE pay_channel_values.pay_channel <> '';

    SELECT coalesce(jsonb_object_agg(status_counts.status_key, status_counts.status_count ORDER BY status_counts.status_key), '{}'::jsonb)
    INTO v_status_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.status, '')) AS status_key,
            count(*)::integer AS status_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
        GROUP BY upper(coalesce(transfer_row.status, ''))
    ) AS status_counts
    WHERE status_counts.status_key <> '';

    SELECT coalesce(jsonb_object_agg(provider_counts.provider_key, provider_counts.provider_count ORDER BY provider_counts.provider_key), '{}'::jsonb)
    INTO v_provider_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_provider, '')) AS provider_key,
            count(*)::integer AS provider_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_provider, ''))
    ) AS provider_counts
    WHERE provider_counts.provider_key <> '';

    SELECT coalesce(jsonb_object_agg(env_counts.env_key, env_counts.env_count ORDER BY env_counts.env_key), '{}'::jsonb)
    INTO v_rail_env_counts
    FROM (
        SELECT
            upper(coalesce(transfer_row.rail_env, '')) AS env_key,
            count(*)::integer AS env_count
        FROM public.pay_bank_transfers AS transfer_row
        WHERE transfer_row.pay_batch_id = p_pay_batch_id
          AND (v_scope = 'ALL' OR upper(coalesce(transfer_row.pay_channel, '')) = v_scope)
          AND (
              (v_pre_execution_export = true AND upper(coalesce(transfer_row.status, '')) = 'PENDING')
              OR (v_pre_execution_export = false AND upper(coalesce(transfer_row.status, '')) <> 'BLOCKED')
          )
        GROUP BY upper(coalesce(transfer_row.rail_env, ''))
    ) AS env_counts
    WHERE env_counts.env_key <> '';

    RETURN jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', v_scope,
        'pay_channel_scope', v_scope,
        'pre_execution_export', v_pre_execution_export,
        'exportable_status_filter', v_exportable_status_filter,
        'row_count', coalesce(v_row_count, 0),
        'total_amount', coalesce(v_total_amount, 0),
        'transfer_hash', v_current_transfer_hash,
        'current_transfer_hash', v_current_transfer_hash,
        'current_transfer_hash_basis', v_current_transfer_hash_basis,
        'pending_transfer_hash', v_pending_transfer_hash,
        'stable_transfer_hash', v_stable_transfer_hash,
        'provider_snapshot', nullif(btrim(coalesce(v_batch_row.rail_provider_snapshot, '')), ''),
        'rail_env_snapshot', nullif(btrim(coalesce(v_batch_row.rail_env_snapshot, '')), ''),
        'freshness_validation_status', nullif(upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))), ''),
        'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END,
        'freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), ''),
        'freshness_scope_hash', nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'bank_csv_export_hash', v_bank_csv_export_hash,
        'csv_export_matches_current_transfers', CASE WHEN v_bank_csv_export_hash IS NULL OR v_current_transfer_hash IS NULL THEN NULL ELSE v_bank_csv_export_hash = v_current_transfer_hash END,
        'pending_row_count', coalesce(v_pending_row_count, 0),
        'pending_total_amount', coalesce(v_pending_total_amount, 0),
        'stable_row_count', coalesce(v_stable_row_count, 0),
        'stable_total_amount', coalesce(v_stable_total_amount, 0),
        'blocked_row_count', coalesce(v_blocked_row_count, 0),
        'all_transfer_count', coalesce(v_all_transfer_count, 0),
        'pay_channels_included', coalesce(v_pay_channels_included, '[]'::jsonb),
        'status_counts', coalesce(v_status_counts, '{}'::jsonb),
        'provider_counts', coalesce(v_provider_counts, '{}'::jsonb),
        'rail_env_counts', coalesce(v_rail_env_counts, '{}'::jsonb),
        'summary_source', 'pay_bank_transfers',
        'policy_x_authority', 'FROZEN_MATERIALISED_TRANSFER_ROWS',
        'generated_at_utc', now()::text
    ));
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_workbench_prepare_draft_scope_seed(p_operation_id uuid, p_workbench_session_id uuid, p_actor_user_id uuid, p_selected_preview_row_ids jsonb DEFAULT NULL::jsonb, p_pay_channel_scope text DEFAULT NULL::text, p_same_week_paye_override_json jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(candidate_scope_count integer, selected_row_count integer, timesheet_count integer, finance_case_count integer, pay_channel_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
    v_operation public.banking_pay_operations%rowtype;
    v_session public.banking_pay_workbench_sessions%rowtype;
    v_scope_filter text;
    v_selected_input jsonb;
    v_selected_row_count integer;
    v_existing_mismatch_count integer;
    v_same_week_paye_override_json jsonb;
    v_candidate_scope_count integer;
    v_selected_count integer;
    v_timesheet_count integer;
    v_finance_case_count integer;
    v_pay_channel_count integer;
begin
    v_scope_filter := upper(coalesce(nullif(btrim(p_pay_channel_scope), ''), 'ALL'));
    v_same_week_paye_override_json := coalesce(p_same_week_paye_override_json, '{}'::jsonb);

    if v_scope_filter not in ('ALL', 'PAYE', 'UMBRELLA') then
        raise exception 'pay_workbench_prepare_draft_scope_seed unsupported pay channel scope: %', v_scope_filter;
    end if;

    if jsonb_typeof(v_same_week_paye_override_json) <> 'object' then
        raise exception 'pay_workbench_prepare_draft_scope_seed requires p_same_week_paye_override_json to be a JSON object';
    end if;

    select operation_row.*
    into v_operation
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
    for update;

    if not found then
        raise exception 'pay_workbench_prepare_draft_scope_seed operation not found: %', p_operation_id;
    end if;

    if v_operation.operation_type <> 'DRAFT_CREATE' then
        raise exception 'pay_workbench_prepare_draft_scope_seed expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation.operation_type;
    end if;

    if v_operation.status in ('COMPLETE', 'FAILED', 'CANCELLED', 'REVIEW_REQUIRED') then
        raise exception 'pay_workbench_prepare_draft_scope_seed cannot seed terminal operation % with status %', p_operation_id, v_operation.status;
    end if;

    if v_operation.workbench_session_id is not null and v_operation.workbench_session_id <> p_workbench_session_id then
        raise exception 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different workbench session', p_operation_id;
    end if;

    if p_actor_user_id is not null and v_operation.actor_user_id is not null and v_operation.actor_user_id <> p_actor_user_id then
        raise exception 'pay_workbench_prepare_draft_scope_seed operation % belongs to a different actor', p_operation_id;
    end if;

    select session_row.*
    into v_session
    from public.banking_pay_workbench_sessions as session_row
    where session_row.id = p_workbench_session_id
    for update;

    if not found then
        raise exception 'pay_workbench_prepare_draft_scope_seed workbench session not found: %', p_workbench_session_id;
    end if;

    if v_session.status <> 'OPEN' then
        raise exception 'pay_workbench_prepare_draft_scope_seed workbench session % is not OPEN: %', p_workbench_session_id, v_session.status;
    end if;

    if v_session.discarded_at_utc is not null then
        raise exception 'pay_workbench_prepare_draft_scope_seed workbench session % has been discarded', p_workbench_session_id;
    end if;

    if p_actor_user_id is not null and v_session.actor_user_id <> p_actor_user_id then
        raise exception 'pay_workbench_prepare_draft_scope_seed workbench session % belongs to a different actor', p_workbench_session_id;
    end if;

    if p_selected_preview_row_ids is not null then
        if jsonb_typeof(p_selected_preview_row_ids) <> 'array' then
            raise exception 'pay_workbench_prepare_draft_scope_seed requires p_selected_preview_row_ids to be null or a JSON array';
        end if;

        select coalesce(jsonb_agg(to_jsonb(normalized_selection.preview_row_id) order by normalized_selection.ord), '[]'::jsonb), count(*)::integer
        into v_selected_input, v_selected_row_count
        from (
            select distinct on (raw_selection.preview_row_id)
                raw_selection.preview_row_id,
                raw_selection.ord
            from (
                select btrim(selection_element.value) as preview_row_id,
                       selection_element.ord
                from jsonb_array_elements_text(p_selected_preview_row_ids) with ordinality as selection_element(value, ord)
                where btrim(selection_element.value) <> ''
            ) as raw_selection
            order by raw_selection.preview_row_id, raw_selection.ord
        ) as normalized_selection;
    else
        if coalesce(v_session.server_selected_preview_row_ids_provided, false) is not true then
            raise exception 'pay_workbench_prepare_draft_scope_seed requires server-selected preview rows for session %', p_workbench_session_id;
        end if;

        if jsonb_typeof(coalesce(v_session.server_selected_preview_row_ids, '[]'::jsonb)) <> 'array' then
            raise exception 'pay_workbench_prepare_draft_scope_seed session % has invalid server_selected_preview_row_ids', p_workbench_session_id;
        end if;

        select coalesce(jsonb_agg(to_jsonb(normalized_selection.preview_row_id) order by normalized_selection.ord), '[]'::jsonb), count(*)::integer
        into v_selected_input, v_selected_row_count
        from (
            select distinct on (raw_selection.preview_row_id)
                raw_selection.preview_row_id,
                raw_selection.ord
            from (
                select btrim(selection_element.value) as preview_row_id,
                       selection_element.ord
                from jsonb_array_elements_text(coalesce(v_session.server_selected_preview_row_ids, '[]'::jsonb)) with ordinality as selection_element(value, ord)
                where btrim(selection_element.value) <> ''
            ) as raw_selection
            order by raw_selection.preview_row_id, raw_selection.ord
        ) as normalized_selection;
    end if;

    if coalesce(v_selected_row_count, 0) = 0 then
        raise exception 'pay_workbench_prepare_draft_scope_seed requires at least one selected preview row';
    end if;

    if coalesce(v_session.server_selected_preview_row_ids_provided, false) is not true then
        raise exception 'pay_workbench_prepare_draft_scope_seed session % does not have persisted server-selected preview rows', p_workbench_session_id;
    end if;

    if v_selected_input is distinct from coalesce(v_session.server_selected_preview_row_ids, '[]'::jsonb) then
        raise exception 'pay_workbench_prepare_draft_scope_seed supplied selected preview rows do not match session server-selected preview rows for session %', p_workbench_session_id;
    end if;

    drop table if exists pg_temp.tmp_pay_workbench_scope_seed_requested_rows;
    create temporary table pg_temp.tmp_pay_workbench_scope_seed_requested_rows (
        preview_row_id text primary key,
        ord bigint not null
    ) on commit drop;

    insert into pg_temp.tmp_pay_workbench_scope_seed_requested_rows(preview_row_id, ord)
    select normalized_selection.preview_row_id,
           normalized_selection.ord
    from (
        select distinct on (raw_selection.preview_row_id)
            raw_selection.preview_row_id,
            raw_selection.ord
        from (
            select btrim(selection_element.value) as preview_row_id,
                   selection_element.ord
            from jsonb_array_elements_text(v_selected_input) with ordinality as selection_element(value, ord)
            where btrim(selection_element.value) <> ''
        ) as raw_selection
        order by raw_selection.preview_row_id, raw_selection.ord
    ) as normalized_selection;

    drop table if exists pg_temp.tmp_pay_workbench_scope_seed_ready_state;
    create temporary table pg_temp.tmp_pay_workbench_scope_seed_ready_state as
    select distinct on (state_row.candidate_id)
        state_row.id as candidate_state_id,
        state_row.session_id,
        state_row.candidate_id,
        state_row.status,
        state_row.effective_candidate_fragment_json,
        state_row.effective_summary_fragment_json,
        state_row.effective_paye_candidate_json,
        state_row.effective_non_paye_payee_json,
        state_row.effective_payees_json,
        state_row.effective_case_resolution_states_json,
        state_row.effective_canonical_preview_lines_json,
        state_row.session_version,
        state_row.updated_at_utc
    from public.banking_pay_workbench_session_candidate_state as state_row
    where state_row.session_id = p_workbench_session_id
      and state_row.status = 'READY'
    order by state_row.candidate_id, state_row.updated_at_utc desc, state_row.id desc;

    drop table if exists pg_temp.tmp_pay_workbench_scope_seed_selected_lines;
    create temporary table pg_temp.tmp_pay_workbench_scope_seed_selected_lines as
    select
        ready_state.candidate_state_id,
        ready_state.candidate_id,
        upper(btrim(coalesce(line_element.value->>'pay_channel', ''))) as pay_channel,
        btrim(coalesce(
            line_element.value->>'preview_row_id',
            line_element.value->>'line_id',
            line_element.value->>'row_id',
            line_element.value->>'id',
            ''
        )) as preview_row_id,
        requested_rows.ord,
        line_element.value as line_json,
        ready_state.effective_candidate_fragment_json,
        ready_state.effective_summary_fragment_json,
        ready_state.effective_paye_candidate_json,
        ready_state.effective_non_paye_payee_json,
        ready_state.effective_payees_json,
        ready_state.effective_case_resolution_states_json,
        ready_state.effective_canonical_preview_lines_json,
        ready_state.session_version
    from pg_temp.tmp_pay_workbench_scope_seed_ready_state as ready_state
    cross join lateral jsonb_array_elements(
        case
            when jsonb_typeof(coalesce(ready_state.effective_canonical_preview_lines_json, '[]'::jsonb)) = 'array' then coalesce(ready_state.effective_canonical_preview_lines_json, '[]'::jsonb)
            else '[]'::jsonb
        end
    ) as line_element(value)
    join pg_temp.tmp_pay_workbench_scope_seed_requested_rows as requested_rows
      on requested_rows.preview_row_id = btrim(coalesce(
             line_element.value->>'preview_row_id',
             line_element.value->>'line_id',
             line_element.value->>'row_id',
             line_element.value->>'id',
             ''
         ))
    where jsonb_typeof(line_element.value) = 'object'
      and btrim(coalesce(
             line_element.value->>'preview_row_id',
             line_element.value->>'line_id',
             line_element.value->>'row_id',
             line_element.value->>'id',
             ''
         )) <> ''
      and upper(btrim(coalesce(line_element.value->>'pay_channel', ''))) in ('PAYE', 'UMBRELLA')
      and (v_scope_filter = 'ALL' or upper(btrim(coalesce(line_element.value->>'pay_channel', ''))) = v_scope_filter);

    select count(*)::integer
    into v_selected_count
    from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line;

    if coalesce(v_selected_count, 0) = 0 then
        raise exception 'pay_workbench_prepare_draft_scope_seed found no READY selected rows for session %, scope %', p_workbench_session_id, v_scope_filter;
    end if;

    select count(*)::integer
    into v_existing_mismatch_count
    from (
        select requested_rows.preview_row_id
        from pg_temp.tmp_pay_workbench_scope_seed_requested_rows as requested_rows
        where not exists (
            select 1
            from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line
            where selected_line.preview_row_id = requested_rows.preview_row_id
        )
    ) as unresolved_rows
    where v_scope_filter = 'ALL';

    if coalesce(v_existing_mismatch_count, 0) > 0 then
        raise exception 'pay_workbench_prepare_draft_scope_seed selected rows did not resolve against READY session state for session %', p_workbench_session_id;
    end if;

    drop table if exists pg_temp.tmp_pay_workbench_scope_seed_scopes;
    create temporary table pg_temp.tmp_pay_workbench_scope_seed_scopes as
    select
        p_operation_id as operation_id,
        p_workbench_session_id as workbench_session_id,
        v_session.source_snapshot_run_id as source_snapshot_run_id,
        v_session.version as source_session_version,
        grouped_lines.candidate_state_id,
        grouped_lines.candidate_id,
        grouped_lines.pay_channel,
        coalesce(jsonb_agg(to_jsonb(grouped_lines.preview_row_id) order by grouped_lines.ord), '[]'::jsonb) as selected_preview_row_ids_json,
        coalesce(jsonb_agg(distinct to_jsonb(grouped_lines.timesheet_id_text)) filter (where grouped_lines.timesheet_id_text is not null), '[]'::jsonb) as selected_timesheet_ids_json,
        coalesce(jsonb_agg(distinct to_jsonb(grouped_lines.finance_case_id_text)) filter (where grouped_lines.finance_case_id_text is not null), '[]'::jsonb) as selected_finance_case_ids_json,
        grouped_lines.effective_candidate_fragment_json,
        grouped_lines.effective_summary_fragment_json,
        grouped_lines.effective_paye_candidate_json,
        grouped_lines.effective_non_paye_payee_json,
        grouped_lines.effective_payees_json,
        grouped_lines.effective_case_resolution_states_json,
        grouped_lines.effective_canonical_preview_lines_json,
        coalesce(jsonb_agg(grouped_lines.line_json order by grouped_lines.ord), '[]'::jsonb) as selected_canonical_preview_lines_json,
        case
            when jsonb_typeof(grouped_lines.effective_candidate_fragment_json->'baseline_component_rows') = 'array' then coalesce(grouped_lines.effective_candidate_fragment_json->'baseline_component_rows', '[]'::jsonb)
            else '[]'::jsonb
        end as baseline_component_rows_json,
        case
            when jsonb_typeof(grouped_lines.effective_candidate_fragment_json->'hidden_recovery_template_lines') = 'array' then coalesce(grouped_lines.effective_candidate_fragment_json->'hidden_recovery_template_lines', '[]'::jsonb)
            else '[]'::jsonb
        end as hidden_recovery_template_lines_json,
        jsonb_build_object(
            'selected_preview_row_count', count(*)::integer,
            'selected_timesheet_count', count(distinct grouped_lines.timesheet_id_text) filter (where grouped_lines.timesheet_id_text is not null),
            'selected_finance_case_count', count(distinct grouped_lines.finance_case_id_text) filter (where grouped_lines.finance_case_id_text is not null),
            'selected_amount_ex_vat', round(coalesce(sum(grouped_lines.amount_ex_vat), 0), 2),
            'pay_channel', grouped_lines.pay_channel
        ) as candidate_totals_json,
        jsonb_build_object(
            'source', 'banking_pay_workbench_session_candidate_state',
            'same_week_paye_override', v_same_week_paye_override_json,
            'pay_channel_scope', v_scope_filter,
            'session_signature', v_session.session_signature,
            'session_version', v_session.version
        ) as allocation_basis_json
    from (
        select
            selected_line.candidate_state_id,
            selected_line.candidate_id,
            selected_line.pay_channel,
            selected_line.preview_row_id,
            selected_line.ord,
            selected_line.line_json,
            selected_line.effective_candidate_fragment_json,
            selected_line.effective_summary_fragment_json,
            case when jsonb_typeof(selected_line.effective_paye_candidate_json) = 'object' then selected_line.effective_paye_candidate_json else '{}'::jsonb end as effective_paye_candidate_json,
            case when jsonb_typeof(selected_line.effective_non_paye_payee_json) = 'object' then selected_line.effective_non_paye_payee_json else '{}'::jsonb end as effective_non_paye_payee_json,
            case when jsonb_typeof(selected_line.effective_payees_json) = 'array' then selected_line.effective_payees_json else '[]'::jsonb end as effective_payees_json,
            case
                when jsonb_typeof(selected_line.effective_case_resolution_states_json) = 'array' then jsonb_build_object('rows', selected_line.effective_case_resolution_states_json)
                when jsonb_typeof(selected_line.effective_case_resolution_states_json) = 'object' then selected_line.effective_case_resolution_states_json
                else jsonb_build_object('rows', '[]'::jsonb)
            end as effective_case_resolution_states_json,
            case when jsonb_typeof(selected_line.effective_canonical_preview_lines_json) = 'array' then selected_line.effective_canonical_preview_lines_json else '[]'::jsonb end as effective_canonical_preview_lines_json,
            case
                when coalesce(selected_line.line_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then selected_line.line_json->>'timesheet_id'
                else null::text
            end as timesheet_id_text,
            case
                when coalesce(selected_line.line_json->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then selected_line.line_json->>'finance_case_id'
                else null::text
            end as finance_case_id_text,
            case
                when coalesce(selected_line.line_json->>'amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (selected_line.line_json->>'amount_ex_vat')::numeric
                when coalesce(selected_line.line_json->>'preview_amount_ex_vat', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (selected_line.line_json->>'preview_amount_ex_vat')::numeric
                when coalesce(selected_line.line_json->>'amount', '') ~ '^-?[0-9]+(\.[0-9]+)?$' then (selected_line.line_json->>'amount')::numeric
                else 0::numeric
            end as amount_ex_vat
        from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line
    ) as grouped_lines
    group by
        grouped_lines.candidate_state_id,
        grouped_lines.candidate_id,
        grouped_lines.pay_channel,
        grouped_lines.effective_candidate_fragment_json,
        grouped_lines.effective_summary_fragment_json,
        grouped_lines.effective_paye_candidate_json,
        grouped_lines.effective_non_paye_payee_json,
        grouped_lines.effective_payees_json,
        grouped_lines.effective_case_resolution_states_json,
        grouped_lines.effective_canonical_preview_lines_json;

    drop table if exists pg_temp.tmp_pay_workbench_scope_seed_required_payees;
    create temporary table pg_temp.tmp_pay_workbench_scope_seed_required_payees as
    with selected_line_routes as (
        select
            proposed_scope.operation_id,
            proposed_scope.workbench_session_id,
            proposed_scope.candidate_id,
            proposed_scope.pay_channel,
            selected_line_element.ord as line_ord,
            selected_line_element.value as line_json,
            case
                when upper(btrim(coalesce(selected_line_element.value->>'payee_entity_kind', selected_line_element.value->>'line_payee_entity_kind', selected_line_element.value->>'entity_kind', ''))) = 'UMBRELLA_COMPANY' then 'UMBRELLA'
                else upper(btrim(coalesce(selected_line_element.value->>'payee_entity_kind', selected_line_element.value->>'line_payee_entity_kind', selected_line_element.value->>'entity_kind', '')))
            end as line_payee_entity_kind,
            case
                when btrim(coalesce(selected_line_element.value->>'payee_entity_id', selected_line_element.value->>'line_payee_entity_id', selected_line_element.value->>'entity_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    then btrim(coalesce(selected_line_element.value->>'payee_entity_id', selected_line_element.value->>'line_payee_entity_id', selected_line_element.value->>'entity_id', ''))::uuid
                else null::uuid
            end as line_payee_entity_id,
            case
                when btrim(coalesce(proposed_scope.effective_non_paye_payee_json->>'payee_entity_id', proposed_scope.effective_non_paye_payee_json->>'umbrella_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    then btrim(coalesce(proposed_scope.effective_non_paye_payee_json->>'payee_entity_id', proposed_scope.effective_non_paye_payee_json->>'umbrella_id', ''))::uuid
                else null::uuid
            end as non_paye_payee_entity_id
        from pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope
        cross join lateral jsonb_array_elements(
            case
                when jsonb_typeof(coalesce(proposed_scope.selected_canonical_preview_lines_json, '[]'::jsonb)) = 'array' then coalesce(proposed_scope.selected_canonical_preview_lines_json, '[]'::jsonb)
                else '[]'::jsonb
            end
        ) with ordinality as selected_line_element(value, ord)
        where proposed_scope.operation_id = p_operation_id
          and proposed_scope.workbench_session_id = p_workbench_session_id
          and jsonb_typeof(selected_line_element.value) = 'object'
    ),
    selected_required_routes as (
        select
            selected_line_routes.operation_id,
            selected_line_routes.workbench_session_id,
            selected_line_routes.candidate_id,
            selected_line_routes.pay_channel,
            selected_line_routes.line_ord,
            case
                when selected_line_routes.line_payee_entity_kind in ('CANDIDATE', 'UMBRELLA') then selected_line_routes.line_payee_entity_kind
                when lower(btrim(coalesce(selected_line_routes.line_json->>'is_candidate_directed_oneoff_payout', ''))) in ('true', 't', '1', 'yes', 'y') then 'CANDIDATE'
                when upper(btrim(coalesce(selected_line_routes.line_json->>'routing_kind', selected_line_routes.line_json->>'route_type', ''))) in ('CANDIDATE', 'CANDIDATE_DIRECT', 'CANDIDATE_DIRECTED', 'CANDIDATE_ONEOFF', 'CANDIDATE_ONE_OFF') then 'CANDIDATE'
                when selected_line_routes.pay_channel = 'PAYE' then 'CANDIDATE'
                when selected_line_routes.pay_channel = 'UMBRELLA' then 'UMBRELLA'
                else null::text
            end as required_payee_entity_kind,
            case
                when selected_line_routes.line_payee_entity_kind = 'CANDIDATE' then coalesce(selected_line_routes.line_payee_entity_id, selected_line_routes.candidate_id)
                when selected_line_routes.line_payee_entity_kind = 'UMBRELLA' then coalesce(selected_line_routes.line_payee_entity_id, selected_line_routes.non_paye_payee_entity_id)
                when lower(btrim(coalesce(selected_line_routes.line_json->>'is_candidate_directed_oneoff_payout', ''))) in ('true', 't', '1', 'yes', 'y') then selected_line_routes.candidate_id
                when upper(btrim(coalesce(selected_line_routes.line_json->>'routing_kind', selected_line_routes.line_json->>'route_type', ''))) in ('CANDIDATE', 'CANDIDATE_DIRECT', 'CANDIDATE_DIRECTED', 'CANDIDATE_ONEOFF', 'CANDIDATE_ONE_OFF') then selected_line_routes.candidate_id
                when selected_line_routes.pay_channel = 'PAYE' then selected_line_routes.candidate_id
                when selected_line_routes.pay_channel = 'UMBRELLA' then selected_line_routes.non_paye_payee_entity_id
                else null::uuid
            end as required_payee_entity_id
        from selected_line_routes
    )
    select distinct
        selected_required_routes.operation_id,
        selected_required_routes.workbench_session_id,
        selected_required_routes.candidate_id,
        selected_required_routes.pay_channel,
        selected_required_routes.required_payee_entity_kind,
        selected_required_routes.required_payee_entity_id
    from selected_required_routes
    where selected_required_routes.required_payee_entity_kind in ('CANDIDATE', 'UMBRELLA');

    update pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope_update
    set effective_payees_json = coalesce((
        select jsonb_agg(payee_element.value order by payee_element.ord)
        from jsonb_array_elements(
            case
                when jsonb_typeof(coalesce(proposed_scope_update.effective_payees_json, '[]'::jsonb)) = 'array' then coalesce(proposed_scope_update.effective_payees_json, '[]'::jsonb)
                else '[]'::jsonb
            end
        ) with ordinality as payee_element(value, ord)
        where jsonb_typeof(payee_element.value) = 'object'
          and exists (
              select 1
              from pg_temp.tmp_pay_workbench_scope_seed_required_payees as required_payee
              where required_payee.operation_id = proposed_scope_update.operation_id
                and required_payee.workbench_session_id = proposed_scope_update.workbench_session_id
                and required_payee.candidate_id = proposed_scope_update.candidate_id
                and required_payee.pay_channel = proposed_scope_update.pay_channel
                and required_payee.required_payee_entity_kind = case
                    when upper(btrim(coalesce(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', ''))) = 'UMBRELLA_COMPANY' then 'UMBRELLA'
                    else upper(btrim(coalesce(payee_element.value->>'payee_entity_kind', payee_element.value->>'entity_kind', '')))
                end
                and (
                    required_payee.required_payee_entity_id is null
                    or (
                        btrim(coalesce(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', '')) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                        and btrim(coalesce(payee_element.value->>'payee_entity_id', payee_element.value->>'entity_id', ''))::uuid = required_payee.required_payee_entity_id
                    )
                )
          )
    ), '[]'::jsonb)
    where proposed_scope_update.operation_id = p_operation_id
      and proposed_scope_update.workbench_session_id = p_workbench_session_id
      and exists (
          select 1
          from pg_temp.tmp_pay_workbench_scope_seed_required_payees as required_payee
          where required_payee.operation_id = proposed_scope_update.operation_id
            and required_payee.workbench_session_id = proposed_scope_update.workbench_session_id
            and required_payee.candidate_id = proposed_scope_update.candidate_id
            and required_payee.pay_channel = proposed_scope_update.pay_channel
      );

    update pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope_update
    set
        selected_timesheet_ids_json = (
            select coalesce(jsonb_agg(to_jsonb(timesheet_ids.timesheet_id_text) order by timesheet_ids.timesheet_id_text), '[]'::jsonb)
            from (
                select distinct line_element.value->>'timesheet_id' as timesheet_id_text
                from jsonb_array_elements(proposed_scope_update.selected_canonical_preview_lines_json) as line_element(value)
                where coalesce(line_element.value->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) as timesheet_ids
        ),
        selected_finance_case_ids_json = (
            select coalesce(jsonb_agg(to_jsonb(finance_case_ids.finance_case_id_text) order by finance_case_ids.finance_case_id_text), '[]'::jsonb)
            from (
                select distinct line_element.value->>'finance_case_id' as finance_case_id_text
                from jsonb_array_elements(proposed_scope_update.selected_canonical_preview_lines_json) as line_element(value)
                where coalesce(line_element.value->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            ) as finance_case_ids
        )
    where proposed_scope_update.operation_id = p_operation_id
      and proposed_scope_update.workbench_session_id = p_workbench_session_id;

    if exists (
        select 1
        from pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope
        join public.banking_pay_operation_candidate_scope as existing_scope
          on existing_scope.operation_id = proposed_scope.operation_id
         and existing_scope.candidate_id = proposed_scope.candidate_id
         and existing_scope.pay_channel = proposed_scope.pay_channel
        where existing_scope.scope_hash is distinct from encode(extensions.digest(convert_to(jsonb_build_object(
            'operation_id', proposed_scope.operation_id::text,
            'workbench_session_id', proposed_scope.workbench_session_id::text,
            'source_snapshot_run_id', case when proposed_scope.source_snapshot_run_id is null then null else proposed_scope.source_snapshot_run_id::text end,
            'source_session_version', proposed_scope.source_session_version,
            'candidate_state_id', case when proposed_scope.candidate_state_id is null then null else proposed_scope.candidate_state_id::text end,
            'candidate_id', proposed_scope.candidate_id::text,
            'pay_channel', proposed_scope.pay_channel,
            'selected_preview_row_ids_json', proposed_scope.selected_preview_row_ids_json,
            'selected_timesheet_ids_json', proposed_scope.selected_timesheet_ids_json,
            'selected_finance_case_ids_json', proposed_scope.selected_finance_case_ids_json,
            'selected_canonical_preview_lines_json', proposed_scope.selected_canonical_preview_lines_json,
            'candidate_totals_json', proposed_scope.candidate_totals_json,
            'allocation_basis_json', proposed_scope.allocation_basis_json
        )::text, 'UTF8'), 'sha256'::text), 'hex')
    ) then
        raise exception 'pay_workbench_prepare_draft_scope_seed found existing candidate scope rows with a different scope hash for operation %', p_operation_id;
    end if;

    insert into public.banking_pay_operation_candidate_scope (
        operation_id,
        workbench_session_id,
        source_snapshot_run_id,
        source_session_version,
        candidate_state_id,
        candidate_id,
        pay_channel,
        selected_preview_row_ids_json,
        selected_timesheet_ids_json,
        selected_finance_case_ids_json,
        effective_candidate_fragment_json,
        effective_summary_fragment_json,
        effective_paye_candidate_json,
        effective_non_paye_payee_json,
        effective_payees_json,
        effective_case_resolution_states_json,
        effective_canonical_preview_lines_json,
        selected_canonical_preview_lines_json,
        baseline_component_rows_json,
        hidden_recovery_template_lines_json,
        candidate_totals_json,
        allocation_basis_json,
        scope_hash,
        chunk_sequence,
        status
    )
    select
        proposed_scope.operation_id,
        proposed_scope.workbench_session_id,
        proposed_scope.source_snapshot_run_id,
        proposed_scope.source_session_version,
        proposed_scope.candidate_state_id,
        proposed_scope.candidate_id,
        proposed_scope.pay_channel,
        proposed_scope.selected_preview_row_ids_json,
        proposed_scope.selected_timesheet_ids_json,
        proposed_scope.selected_finance_case_ids_json,
        proposed_scope.effective_candidate_fragment_json,
        proposed_scope.effective_summary_fragment_json,
        proposed_scope.effective_paye_candidate_json,
        proposed_scope.effective_non_paye_payee_json,
        proposed_scope.effective_payees_json,
        proposed_scope.effective_case_resolution_states_json,
        proposed_scope.effective_canonical_preview_lines_json,
        proposed_scope.selected_canonical_preview_lines_json,
        proposed_scope.baseline_component_rows_json,
        proposed_scope.hidden_recovery_template_lines_json,
        proposed_scope.candidate_totals_json,
        proposed_scope.allocation_basis_json,
        encode(extensions.digest(convert_to(jsonb_build_object(
            'operation_id', proposed_scope.operation_id::text,
            'workbench_session_id', proposed_scope.workbench_session_id::text,
            'source_snapshot_run_id', case when proposed_scope.source_snapshot_run_id is null then null else proposed_scope.source_snapshot_run_id::text end,
            'source_session_version', proposed_scope.source_session_version,
            'candidate_state_id', case when proposed_scope.candidate_state_id is null then null else proposed_scope.candidate_state_id::text end,
            'candidate_id', proposed_scope.candidate_id::text,
            'pay_channel', proposed_scope.pay_channel,
            'selected_preview_row_ids_json', proposed_scope.selected_preview_row_ids_json,
            'selected_timesheet_ids_json', proposed_scope.selected_timesheet_ids_json,
            'selected_finance_case_ids_json', proposed_scope.selected_finance_case_ids_json,
            'selected_canonical_preview_lines_json', proposed_scope.selected_canonical_preview_lines_json,
            'candidate_totals_json', proposed_scope.candidate_totals_json,
            'allocation_basis_json', proposed_scope.allocation_basis_json
        )::text, 'UTF8'), 'sha256'::text), 'hex'),
        row_number() over (order by proposed_scope.pay_channel, proposed_scope.candidate_id),
        'SCOPED'
    from pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope
    on conflict (operation_id, candidate_id, pay_channel) do update
    set
        selected_preview_row_ids_json = excluded.selected_preview_row_ids_json,
        selected_timesheet_ids_json = excluded.selected_timesheet_ids_json,
        selected_finance_case_ids_json = excluded.selected_finance_case_ids_json,
        effective_candidate_fragment_json = excluded.effective_candidate_fragment_json,
        effective_summary_fragment_json = excluded.effective_summary_fragment_json,
        effective_paye_candidate_json = excluded.effective_paye_candidate_json,
        effective_non_paye_payee_json = excluded.effective_non_paye_payee_json,
        effective_payees_json = excluded.effective_payees_json,
        effective_case_resolution_states_json = excluded.effective_case_resolution_states_json,
        effective_canonical_preview_lines_json = excluded.effective_canonical_preview_lines_json,
        selected_canonical_preview_lines_json = excluded.selected_canonical_preview_lines_json,
        baseline_component_rows_json = excluded.baseline_component_rows_json,
        hidden_recovery_template_lines_json = excluded.hidden_recovery_template_lines_json,
        candidate_totals_json = excluded.candidate_totals_json,
        allocation_basis_json = excluded.allocation_basis_json,
        scope_hash = excluded.scope_hash,
        chunk_sequence = excluded.chunk_sequence,
        status = case
            when public.banking_pay_operation_candidate_scope.status = 'PENDING' then 'SCOPED'
            else public.banking_pay_operation_candidate_scope.status
        end,
        updated_at_utc = now();

    select count(*)::integer
    into v_candidate_scope_count
    from public.banking_pay_operation_candidate_scope as scope_row
    where scope_row.operation_id = p_operation_id
      and exists (
          select 1
          from pg_temp.tmp_pay_workbench_scope_seed_scopes as proposed_scope
          where proposed_scope.candidate_id = scope_row.candidate_id
            and proposed_scope.pay_channel = scope_row.pay_channel
      );

    select count(distinct selected_line.preview_row_id)::integer
    into v_selected_count
    from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line;

    select count(distinct selected_line.line_json->>'timesheet_id')::integer
    into v_timesheet_count
    from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line
    where coalesce(selected_line.line_json->>'timesheet_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    select count(distinct selected_line.line_json->>'finance_case_id')::integer
    into v_finance_case_count
    from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line
    where coalesce(selected_line.line_json->>'finance_case_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

    select count(distinct selected_line.pay_channel)::integer
    into v_pay_channel_count
    from pg_temp.tmp_pay_workbench_scope_seed_selected_lines as selected_line;

    return query
    select
        coalesce(v_candidate_scope_count, 0),
        coalesce(v_selected_count, 0),
        coalesce(v_timesheet_count, 0),
        coalesce(v_finance_case_count, 0),
        coalesce(v_pay_channel_count, 0);
end;
$function$;


DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);

DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);



DROP FUNCTION IF EXISTS public.pay_bank_transfer_execution_classify(uuid, text, uuid, boolean);

CREATE OR REPLACE FUNCTION public.pay_bank_transfer_execution_classify(p_pay_batch_id uuid, p_pay_channel_scope text DEFAULT 'ALL'::text, p_operation_id uuid DEFAULT NULL::uuid, p_include_unscoped_transfers boolean DEFAULT true)
 RETURNS TABLE(pay_bank_transfer_id uuid, pay_batch_id uuid, pay_channel text, transfer_group_key text, scope_id uuid, scope_operation_id uuid, scope_status text, scope_request_id text, status_upper text, rail_state_upper text, amount numeric, currency text, has_route_ready boolean, has_local_prepare_identity boolean, has_provider_submission_evidence boolean, has_provider_event_evidence boolean, has_provider_attempt_without_external_id boolean, has_operation_submit_attempt boolean, has_ambiguous_external_evidence boolean, is_failed_or_blocked boolean, is_terminal_or_completed boolean, evidence_classification text, is_authorisation_ready boolean, is_unattempted_submit_eligible boolean, is_safe_local_cleanup boolean, is_canonical_pending_status boolean, has_auth_prepared_scope boolean, has_different_operation_scope boolean, has_stale_auth_request_evidence boolean, auth_request_id uuid, auth_request_state text, auth_request_operation_id uuid, has_same_operation_active_auth_request boolean, has_other_operation_active_auth_request boolean, has_cancellable_local_auth_request boolean, has_non_cancellable_auth_request boolean, has_authorised_auth_without_provider_submission boolean, has_auth_request_provider_risk boolean, auth_request_unsafe_reason text, unsafe_reason text, has_same_operation_authorised_auth_request boolean, has_pending_authorisation_auth_request boolean, is_provider_submit_ready boolean, provider_submit_unsafe_reason text, has_provider_submit_blocker boolean, provider_failure_reason_code text, provider_failure_reason_group text, provider_failure_reason_label text, is_success_only boolean, should_touch_payment_status boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_scope text := 'ALL';
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  v_scope := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  IF v_scope = '' THEN
    v_scope := 'ALL';
  END IF;

  RETURN QUERY
  WITH batch_context AS (
    SELECT
      batch_rows.id AS pay_batch_id,
      batch_rows.status AS batch_status,
      batch_rows.schedule_kind AS batch_schedule_kind,
      batch_rows.scheduled_at_utc AS batch_scheduled_at_utc,
      batch_rows.cancelled_at_utc AS batch_cancelled_at_utc,
      batch_rows.execution_commit_state AS batch_execution_commit_state
    FROM public.pay_batches AS batch_rows
    WHERE batch_rows.id = p_pay_batch_id
  ), latest_auth_request AS (
    SELECT
      auth_request_rows.id AS auth_request_id,
      auth_request_rows.state AS auth_request_state,
      CASE
        WHEN NULLIF(btrim(COALESCE(auth_request_rows.execution_intent_json->>'operation_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN (auth_request_rows.execution_intent_json->>'operation_id')::uuid
        ELSE NULL::uuid
      END AS auth_request_operation_id,
      ROW_NUMBER() OVER (ORDER BY auth_request_rows.created_at_utc DESC NULLS LAST, auth_request_rows.id DESC) AS auth_request_ordinal
    FROM public.pay_batch_auth_requests AS auth_request_rows
    WHERE auth_request_rows.pay_batch_id = p_pay_batch_id
      AND upper(btrim(COALESCE(auth_request_rows.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION', 'AUTHORISED', 'AUTHORIZED')
  ), transfer_rows AS (
    SELECT
      transfer_source_rows.id AS pay_bank_transfer_id,
      transfer_source_rows.pay_batch_id,
      transfer_source_rows.pay_channel,
      transfer_source_rows.transfer_group_key,
      latest_scope_rows.scope_id,
      latest_scope_rows.scope_operation_id,
      latest_scope_rows.scope_status,
      latest_scope_rows.scope_request_id,
      upper(btrim(COALESCE(transfer_source_rows.status, ''))) AS status_upper,
      upper(btrim(COALESCE(transfer_source_rows.rail_state, ''))) AS rail_state_upper,
      transfer_source_rows.amount,
      transfer_source_rows.currency,
      transfer_source_rows.request_id,
      transfer_source_rows.payment_reference,
      transfer_source_rows.rail_tx_id,
      COALESCE(transfer_source_rows.rail_meta_json, '{}'::jsonb) AS rail_meta_json,
      transfer_source_rows.completed_at_utc,
      transfer_source_rows.failed_reason,
      transfer_source_rows.payee_name,
      transfer_source_rows.sort_code,
      transfer_source_rows.account_number,
      transfer_source_rows.account_type
    FROM public.pay_bank_transfers AS transfer_source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = transfer_source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT
        scope_rows.id AS scope_id,
        scope_rows.operation_id AS scope_operation_id,
        scope_rows.status AS scope_status,
        scope_rows.request_id AS scope_request_id
      FROM public.banking_pay_operation_transfer_scope AS scope_rows
      WHERE scope_rows.pay_batch_id = transfer_source_rows.pay_batch_id
        AND scope_rows.pay_channel = transfer_source_rows.pay_channel
        AND (
          scope_rows.pay_bank_transfer_id = transfer_source_rows.id
          OR (
            scope_rows.pay_bank_transfer_id IS NULL
            AND NULLIF(btrim(COALESCE(scope_rows.transfer_group_key, '')), '') IS NOT NULL
            AND scope_rows.transfer_group_key = transfer_source_rows.transfer_group_key
          )
        )
        AND (p_operation_id IS NULL OR scope_rows.operation_id = p_operation_id)
      ORDER BY scope_rows.updated_at_utc DESC NULLS LAST, scope_rows.created_at_utc DESC NULLS LAST, scope_rows.id DESC
      LIMIT 1
    ) AS latest_scope_rows ON true
    WHERE transfer_source_rows.pay_batch_id = p_pay_batch_id
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(transfer_source_rows.pay_channel, ''))) = v_scope)
      AND (
        COALESCE(p_include_unscoped_transfers, true)
        OR p_operation_id IS NULL
        OR latest_scope_rows.scope_operation_id = p_operation_id
      )
  ), scope_without_transfer_rows AS (
    SELECT
      NULL::uuid AS pay_bank_transfer_id,
      scope_source_rows.pay_batch_id,
      scope_source_rows.pay_channel,
      scope_source_rows.transfer_group_key,
      scope_source_rows.id AS scope_id,
      scope_source_rows.operation_id AS scope_operation_id,
      scope_source_rows.status AS scope_status,
      scope_source_rows.request_id AS scope_request_id,
      upper(btrim(COALESCE(scope_source_rows.status, ''))) AS status_upper,
      NULL::text AS rail_state_upper,
      scope_source_rows.amount,
      scope_source_rows.currency,
      scope_source_rows.request_id,
      scope_source_rows.payment_reference,
      NULL::text AS rail_tx_id,
      jsonb_build_object(
        'scope_id', scope_source_rows.id::text,
        'operation_id', scope_source_rows.operation_id::text,
        'scope_status', scope_source_rows.status,
        'local_scope_row', true
      ) AS rail_meta_json,
      NULL::timestamptz AS completed_at_utc,
      NULL::text AS failed_reason,
      scope_source_rows.payee_name,
      scope_source_rows.sort_code,
      scope_source_rows.account_number,
      scope_source_rows.account_type
    FROM public.banking_pay_operation_transfer_scope AS scope_source_rows
    WHERE scope_source_rows.pay_batch_id = p_pay_batch_id
      AND scope_source_rows.pay_bank_transfer_id IS NULL
      AND (v_scope IN ('ALL', 'ANY', '*') OR upper(btrim(COALESCE(scope_source_rows.pay_channel, ''))) = v_scope)
      AND (p_operation_id IS NULL OR scope_source_rows.operation_id = p_operation_id)
  ), source_rows AS (
    SELECT * FROM transfer_rows
    UNION ALL
    SELECT * FROM scope_without_transfer_rows
  ), classified_rows AS (
    SELECT
      source_rows.*,
      batch_context_rows.batch_status,
      batch_context_rows.batch_schedule_kind,
      batch_context_rows.batch_scheduled_at_utc,
      batch_context_rows.batch_cancelled_at_utc,
      COALESCE(provider_evidence_rows.evidence_class, 'LOCAL_PREPARED_ONLY') AS provider_evidence_class,
      COALESCE(provider_evidence_rows.provider_submitted, false) AS provider_submitted,
      COALESCE(provider_evidence_rows.provider_request_sent, false) AS provider_request_sent,
      COALESCE(provider_evidence_rows.provider_response_present, false) AS provider_response_present,
      COALESCE(provider_evidence_rows.provider_event_present, false) AS provider_event_present,
      COALESCE(provider_evidence_rows.provider_external_id_present, false) AS provider_external_id_present,
      COALESCE(provider_evidence_rows.local_prepared_only, source_rows.pay_bank_transfer_id IS NOT NULL OR source_rows.scope_id IS NOT NULL) AS local_prepared_only,
      COALESCE(provider_evidence_rows.cash_state, 'NO_TRANSFER_EVIDENCE') AS provider_cash_state,
      provider_evidence_rows.blocker_code AS provider_blocker_code,
      COALESCE(provider_evidence_rows.support_details_json, '{}'::jsonb) AS provider_support_details_json,
      COALESCE(rail_classification_rows.cash_state, 'UNKNOWN') AS rail_cash_state,
      COALESCE(rail_classification_rows.is_final_money_moved, false) AS rail_is_final_money_moved,
      COALESCE(rail_classification_rows.is_terminal_no_money, false) AS rail_is_terminal_no_money,
      COALESCE(rail_classification_rows.is_pending_non_final, false) AS rail_is_pending_non_final,
      auth_rows.auth_request_id,
      auth_rows.auth_request_state,
      auth_rows.auth_request_operation_id
    FROM source_rows
    JOIN batch_context AS batch_context_rows
      ON batch_context_rows.pay_batch_id = source_rows.pay_batch_id
    LEFT JOIN LATERAL (
      SELECT evidence_rows.*
      FROM public._pay_bank_transfer_provider_evidence_classify(
        source_rows.pay_batch_id,
        source_rows.pay_bank_transfer_id,
        CASE
          WHEN source_rows.pay_bank_transfer_id IS NOT NULL THEN jsonb_build_object('scope_type', 'TRANSFER', 'pay_bank_transfer_id', source_rows.pay_bank_transfer_id::text)
          ELSE jsonb_build_object('scope_type', 'BATCH')
        END,
        p_operation_id
      ) AS evidence_rows
      WHERE source_rows.pay_bank_transfer_id IS NOT NULL
      LIMIT 1
    ) AS provider_evidence_rows ON true
    LEFT JOIN LATERAL public._pay_rail_state_money_movement_classify(
      source_rows.status_upper,
      source_rows.rail_state_upper,
      source_rows.rail_meta_json,
      source_rows.rail_meta_json
    ) AS rail_classification_rows ON true
    LEFT JOIN LATERAL (
      SELECT latest_auth_request.auth_request_id, latest_auth_request.auth_request_state, latest_auth_request.auth_request_operation_id
      FROM latest_auth_request
      WHERE latest_auth_request.auth_request_ordinal = 1
      LIMIT 1
    ) AS auth_rows ON true
  ), lifecycle_rows AS (
    SELECT
      classified_rows.*,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS correction_item_rows
        WHERE correction_item_rows.pay_batch_id = classified_rows.pay_batch_id
          AND correction_item_rows.correction_item_kind = 'PRE_BANK_CANCEL'
          AND upper(btrim(COALESCE(correction_item_rows.status, ''))) = 'APPLIED'
          AND (
            correction_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS item_rows
              WHERE item_rows.pay_batch_candidate_id = correction_item_rows.pay_batch_candidate_id
                AND item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_pre_bank_cancel,
      EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_work_items AS unwind_work_item_rows
        JOIN public.pay_payment_correction_requests AS unwind_request_rows
          ON unwind_request_rows.id = unwind_work_item_rows.correction_request_id
        WHERE unwind_request_rows.pay_batch_id = classified_rows.pay_batch_id
          AND upper(btrim(COALESCE(unwind_request_rows.correction_kind, ''))) IN ('NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
          AND upper(btrim(COALESCE(unwind_work_item_rows.status, ''))) IN ('APPLIED','DONE','COMPLETE','COMPLETED')
          AND (
            unwind_work_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            OR EXISTS (
              SELECT 1
              FROM public.pay_batch_items AS unwind_item_rows
              WHERE unwind_item_rows.pay_batch_candidate_id = unwind_work_item_rows.pay_batch_candidate_id
                AND unwind_item_rows.pay_bank_transfer_id = classified_rows.pay_bank_transfer_id
            )
          )
      ) AS has_applied_no_money_unwind,
      EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS operation_rows
        WHERE operation_rows.pay_batch_id = classified_rows.pay_batch_id
          AND (
            upper(btrim(COALESCE(operation_rows.status, ''))) = 'RETRY_LATER'
            OR upper(btrim(COALESCE(operation_rows.phase, ''))) = 'RETRY_LATER'
            OR upper(NULLIF(btrim(COALESCE(operation_rows.error_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.result_json->>'code', '')), '')) IN ('PROVIDER_OUTAGE_RETRY_LATER', 'BANK_UNAVAILABLE', 'PROVIDER_UNAVAILABLE', 'RETRY_LATER')
            OR upper(NULLIF(btrim(COALESCE(operation_rows.progress_json->>'retry_state', '')), '')) = 'RETRY_LATER'
          )
      ) AS has_retry_later_state
    FROM classified_rows
  ), final_rows AS (
    SELECT
      lifecycle_rows.*,
      CASE
        WHEN lifecycle_rows.provider_cash_state = 'FINAL_PAID' OR lifecycle_rows.rail_is_final_money_moved THEN 'PAID_OR_SETTLED'
        WHEN lifecycle_rows.provider_evidence_class = 'PROVIDER_OUTCOME_UNKNOWN'
          OR (lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'UNKNOWN')
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.rail_cash_state = 'UNKNOWN'
            AND (
              lifecycle_rows.status_upper IN ('COMMITTED', 'EXECUTED')
              OR lifecycle_rows.rail_state_upper IN ('COMMITTED', 'EXECUTED')
            )
          ) THEN 'PROVIDER_OUTCOME_UNKNOWN'
        WHEN lifecycle_rows.provider_submitted AND lifecycle_rows.provider_cash_state = 'PENDING_NON_FINAL' THEN 'PROVIDER_SUBMITTED_PENDING'
        WHEN lifecycle_rows.has_applied_pre_bank_cancel
          OR (
            NOT lifecycle_rows.provider_submitted
            AND (
              upper(COALESCE(lifecycle_rows.batch_status, '')) IN ('CANCELLED', 'CANCELED')
              OR lifecycle_rows.batch_cancelled_at_utc IS NOT NULL
            )
          )
          OR (
            NOT lifecycle_rows.provider_submitted
            AND lifecycle_rows.status_upper IN (
              'CANCELLED',
              'CANCELED',
              'CANCELLED_BEFORE_BANK_SUBMISSION',
              'CANCELED_BEFORE_BANK_SUBMISSION',
              'LOCALLY_CANCELLED',
              'LOCAL_CANCELLED',
              'VOIDED'
            )
          ) THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
        WHEN lifecycle_rows.has_applied_no_money_unwind THEN 'FINANCIALS_REWOUND'
        WHEN lifecycle_rows.provider_submitted
          AND (
            lifecycle_rows.provider_cash_state = 'TERMINAL_NO_MONEY'
            OR lifecycle_rows.rail_is_terminal_no_money
          ) THEN
          CASE WHEN lifecycle_rows.status_upper IN ('CANCELLED', 'CANCELED') OR lifecycle_rows.rail_state_upper IN ('CANCELLED', 'CANCELED', 'CANCELLED_BEFORE_RELEASE', 'CANCELED_BEFORE_RELEASE') THEN 'PROVIDER_CANCELLED_NO_MONEY' ELSE 'PROVIDER_FAILED_NO_MONEY' END
        WHEN lifecycle_rows.has_retry_later_state AND NOT lifecycle_rows.provider_submitted THEN 'PROVIDER_OUTAGE_RETRY_LATER'
        WHEN upper(COALESCE(lifecycle_rows.batch_status, '')) = 'SCHEDULED' OR lifecycle_rows.batch_scheduled_at_utc IS NOT NULL OR lifecycle_rows.status_upper = 'SCHEDULED' THEN 'SCHEDULED_LOCAL_NOT_SENT'
        ELSE 'LOCAL_PREPARED_NOT_SENT'
      END AS derived_lifecycle_state
    FROM lifecycle_rows
  )
  SELECT
    final_rows.pay_bank_transfer_id,
    final_rows.pay_batch_id,
    final_rows.pay_channel,
    final_rows.transfer_group_key,
    final_rows.scope_id,
    final_rows.scope_operation_id,
    final_rows.scope_status,
    final_rows.scope_request_id,
    final_rows.status_upper,
    final_rows.rail_state_upper,
    final_rows.amount,
    final_rows.currency,
    (
      COALESCE(final_rows.amount, 0) > 0
      AND NULLIF(btrim(COALESCE(final_rows.currency, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.payee_name, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.sort_code, '')), '') IS NOT NULL
      AND NULLIF(btrim(COALESCE(final_rows.account_number, '')), '') IS NOT NULL
    ) AS has_route_ready,
    final_rows.local_prepared_only,
    final_rows.provider_submitted,
    final_rows.provider_event_present,
    (final_rows.provider_request_sent AND NOT final_rows.provider_external_id_present) AS has_provider_attempt_without_external_id,
    COALESCE(NULLIF(final_rows.provider_support_details_json->>'operation_submit_attempt_count', '')::integer, 0) > 0 AS has_operation_submit_attempt,
    final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' AS has_ambiguous_external_evidence,
    final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') AS is_failed_or_blocked,
    final_rows.derived_lifecycle_state IN ('PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND') AS is_terminal_or_completed,
    final_rows.derived_lifecycle_state AS evidence_classification,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT')
    ) AS is_authorisation_ready,
    (
      final_rows.auth_request_state IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
    ) AS is_unattempted_submit_eligible,
    (NOT final_rows.provider_submitted AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')) AS is_safe_local_cleanup,
    final_rows.status_upper IN ('', 'PENDING', 'PREPARED', 'READY', 'SCHEDULED', 'QUEUED', 'SUBMITTED', 'SENT', 'PROCESSING', 'ACCEPTED') AS is_canonical_pending_status,
    final_rows.auth_request_id IS NOT NULL AS has_auth_prepared_scope,
    (final_rows.auth_request_operation_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_different_operation_scope,
    false AS has_stale_auth_request_evidence,
    final_rows.auth_request_id,
    final_rows.auth_request_state,
    final_rows.auth_request_operation_id,
    (final_rows.auth_request_id IS NOT NULL AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND p_operation_id IS NOT NULL AND final_rows.auth_request_operation_id IS NOT NULL AND final_rows.auth_request_operation_id <> p_operation_id) AS has_other_operation_active_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND NOT final_rows.provider_submitted) AS has_cancellable_local_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND final_rows.provider_submitted) AS has_non_cancellable_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND NOT final_rows.provider_submitted) AS has_authorised_auth_without_provider_submission,
    final_rows.provider_submitted AS has_auth_request_provider_risk,
    CASE WHEN final_rows.provider_submitted THEN 'Provider evidence exists; local authorisation cleanup must not treat this as not sent.' ELSE NULL::text END AS auth_request_unsafe_reason,
    CASE
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'Provider outcome unknown; check provider before retry, cancel, or unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_SUBMITTED_PENDING' THEN 'Provider submission is pending; provider state must be checked before unwind.'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'Payment is paid/settled; use recovery workflow rather than no-money unwind.'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'Payment financials have already been rewound; do not submit, cancel, or unwind again.'
      ELSE NULL::text
    END AS unsafe_reason,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED') AND (p_operation_id IS NULL OR final_rows.auth_request_operation_id IS NULL OR final_rows.auth_request_operation_id = p_operation_id)) AS has_same_operation_authorised_auth_request,
    (final_rows.auth_request_id IS NOT NULL AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'PENDING_AUTHORIZATION')) AS has_pending_authorisation_auth_request,
    (
      final_rows.auth_request_id IS NOT NULL
      AND upper(btrim(COALESCE(final_rows.auth_request_state, ''))) IN ('AUTHORISED', 'AUTHORIZED')
      AND NOT final_rows.provider_submitted
      AND final_rows.derived_lifecycle_state IN ('LOCAL_PREPARED_NOT_SENT', 'SCHEDULED_LOCAL_NOT_SENT', 'PROVIDER_OUTAGE_RETRY_LATER')
      AND COALESCE(final_rows.amount, 0) > 0
    ) AS is_provider_submit_ready,
    CASE
      WHEN final_rows.provider_submitted THEN 'PROVIDER_SUBMISSION_ALREADY_EXISTS'
      WHEN final_rows.derived_lifecycle_state = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER'
      WHEN final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED' THEN 'PAYMENT_ALREADY_PAID_OR_SETTLED'
      WHEN final_rows.derived_lifecycle_state IN ('PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY') THEN 'TERMINAL_NO_MONEY_REWIND_REQUIRED'
      WHEN final_rows.derived_lifecycle_state = 'FINANCIALS_REWOUND' THEN 'FINANCIALS_ALREADY_REWOUND'
      WHEN final_rows.auth_request_id IS NULL THEN 'NO_AUTHORISED_PAYMENT_AUTH_REQUEST'
      WHEN upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED') THEN 'PAYMENT_AUTHORISATION_NOT_COMPLETE'
      ELSE NULL::text
    END AS provider_submit_unsafe_reason,
    (
      final_rows.provider_submitted
      OR final_rows.derived_lifecycle_state IN ('PROVIDER_OUTCOME_UNKNOWN', 'PAID_OR_SETTLED', 'PROVIDER_FAILED_NO_MONEY', 'PROVIDER_CANCELLED_NO_MONEY', 'CANCELLED_BEFORE_BANK_SUBMISSION', 'FINANCIALS_REWOUND')
      OR final_rows.auth_request_id IS NULL
      OR upper(btrim(COALESCE(final_rows.auth_request_state, ''))) NOT IN ('AUTHORISED', 'AUTHORIZED')
    ) AS has_provider_submit_blocker,
    (
      SELECT latest_event.provider_failure_reason_code
      FROM public.pay_bank_transfer_events AS latest_event
      WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        AND latest_event.provider_failure_reason_code IS NOT NULL
      ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
      LIMIT 1
    ) AS provider_failure_reason_code,
    COALESCE(
      (
        SELECT latest_event.provider_failure_reason_group
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
          AND latest_event.provider_failure_reason_group IS NOT NULL
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_group'
    ) AS provider_failure_reason_group,
    COALESCE(
      (
        SELECT public._banking_provider_failure_reason_normalise(
          latest_event.provider_key,
          COALESCE(latest_event.provider_state, latest_event.normalised_state),
          latest_event.provider_failure_reason_code,
          COALESCE(latest_event.raw_payload->>'provider_failure_reason_text', latest_event.raw_payload->>'failure_reason', latest_event.raw_payload->>'reason', latest_event.raw_payload->>'message'),
          COALESCE(latest_event.raw_payload, '{}'::jsonb)
        )->>'failure_reason_label'
        FROM public.pay_bank_transfer_events AS latest_event
        WHERE latest_event.pay_bank_transfer_id = final_rows.pay_bank_transfer_id
        ORDER BY latest_event.received_at_utc DESC NULLS LAST, latest_event.id DESC
        LIMIT 1
      ),
      public._banking_provider_failure_reason_normalise(
        COALESCE(final_rows.rail_meta_json->>'provider_key', final_rows.rail_meta_json->>'rail_provider', NULL::text),
        COALESCE(final_rows.rail_state_upper, final_rows.status_upper),
        COALESCE(final_rows.failed_reason, final_rows.provider_support_details_json->>'provider_error_code'),
        COALESCE(final_rows.provider_support_details_json->>'provider_error_message_redacted', final_rows.failed_reason),
        COALESCE(final_rows.rail_meta_json, '{}'::jsonb)
      )->>'failure_reason_label'
    ) AS provider_failure_reason_label,
    (final_rows.derived_lifecycle_state = 'PAID_OR_SETTLED') AS is_success_only,
    (final_rows.pay_bank_transfer_id IS NOT NULL OR final_rows.scope_id IS NOT NULL) AS should_touch_payment_status
  FROM final_rows
  ORDER BY final_rows.pay_channel, final_rows.transfer_group_key NULLS LAST, final_rows.pay_bank_transfer_id NULLS LAST, final_rows.scope_id NULLS LAST;
END;
$function$;






CREATE OR REPLACE FUNCTION public.pay_execute_operation_cleanup_failed_local_artifacts(
  p_operation_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_failure_phase text DEFAULT NULL::text,
  p_failure_error_json jsonb DEFAULT '{}'::jsonb,
  p_dry_run boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_type_upper text := NULL::text;
  v_operation_type_cleanup_mode text := NULL::text;
  v_retry_blocked_reason text := NULL::text;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_failure_phase text := NULL::text;
  v_failure_error_json jsonb := '{}'::jsonb;
  v_batch_execution_boundary_crossed boolean := false;
  v_active_auth_request_count integer := 0;
  v_initial_active_auth_request_count integer := 0;
  v_operation_active_auth_request_count integer := 0;
  v_active_auth_request_ids jsonb := '[]'::jsonb;
  v_auth_requests_cancelled integer := 0;
  v_awaiting_auth_requests_cancelled integer := 0;
  v_authorised_auth_requests_cancelled integer := 0;
  v_auth_tokens_voided integer := 0;
  v_batch_execution_intent_cleared integer := 0;
  v_active_auth_request_blocker_count integer := 0;
  v_authorised_auth_request_review_count integer := 0;
  v_cancellable_auth_request_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_cancelled_auth_request_ids jsonb := '[]'::jsonb;
  v_provider_submit_chunk_attempt_count integer := 0;
  v_stale_empty_provider_submit_chunk_count integer := 0;
  v_provider_submit_unknown_chunk_count integer := 0;
  v_deletion_allowed boolean := false;
  v_scope_rows_considered integer := 0;
  v_transfer_rows_considered integer := 0;
  v_safe_scope_candidate_count integer := 0;
  v_safe_transfer_candidate_count integer := 0;
  v_scope_rows_deleted integer := 0;
  v_transfer_rows_deleted integer := 0;
  v_item_links_cleared integer := 0;
  v_bank_references_cleared integer := 0;
  v_chunks_marked_failed integer := 0;
  v_chunks_marked_skipped integer := 0;
  v_locks_released integer := 0;
  v_provider_evidence_count integer := 0;
  v_provider_review_risk_count integer := 0;
  v_unsafe_transfer_count integer := 0;
  v_unsafe_scope_count integer := 0;
  v_remaining_operation_scope_count integer := 0;
  v_remaining_operation_transfer_count integer := 0;
  v_retry_blocked boolean := false;
  v_safe_to_retry boolean := false;
  v_review_required boolean := false;
  v_cleanup_mode text := 'NOTHING_TO_CLEAN';
  v_safe_scope_ids jsonb := '[]'::jsonb;
  v_safe_transfer_ids jsonb := '[]'::jsonb;
  v_deleted_scope_ids jsonb := '[]'::jsonb;
  v_deleted_transfer_ids jsonb := '[]'::jsonb;
  v_unsafe_transfer_ids jsonb := '[]'::jsonb;
  v_unsafe_reasons jsonb := '[]'::jsonb;
  v_result jsonb := '{}'::jsonb;
  v_provider_submit_finalise_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_provider_submit_review_reason_code text := NULL::text;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_stale_unresolved_submit_chunk_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_provider_manual_resolution_required boolean := false;
  v_provider_safe_retry_available boolean := false;
  v_provider_recommended_action text := NULL::text;
  v_provider_submit_requires_manual_review boolean := false;
  v_provider_submit_allows_local_cleanup boolean := false;
  v_pre_provider_fast_cleanup_phase boolean := false;
  v_fast_provider_submit_chunk_count integer := 0;
  v_fast_transfer_event_count integer := 0;
  v_fast_external_transfer_marker_count integer := 0;
  v_fast_provider_request_marker_count integer := 0;
  v_fast_other_operation_scope_count integer := 0;
  v_fast_payment_correction_reference_count integer := 0;
  v_fast_same_operation_cancellable_auth_count integer := 0;
  v_fast_same_operation_pending_auth_count integer := 0;
  v_fast_other_active_auth_count integer := 0;
  v_fast_cleanup_allowed boolean := false;
  v_fast_cleanup_blocker_reasons jsonb := '[]'::jsonb;
  v_fast_provider_outcome_candidate boolean := false;
  v_fast_provider_outcome_evidence_detected boolean := false;
  v_fast_provider_outcome_status text := NULL::text;
  v_fast_provider_outcome_cleanup_mode text := NULL::text;
  v_fast_provider_failure_error_marker_count integer := 0;
  v_fast_provider_marker_count integer := 0;
  v_fast_provider_chunk_marker_count integer := 0;
  v_fast_provider_transfer_meta_marker_count integer := 0;
  v_fast_provider_exact_event_count integer := 0;
  v_fast_provider_rejected_count integer := 0;
  v_fast_provider_accepted_count integer := 0;
  v_fast_provider_unknown_count integer := 0;
  v_fast_provider_malformed_count integer := 0;
  v_fast_provider_blocked_pre_call_count integer := 0;
  v_fast_provider_request_sent_count integer := 0;
  v_fast_provider_response_present_count integer := 0;
  v_fast_provider_unfinalised_count integer := 0;
  v_fast_provider_auth_request_count integer := 0;
  v_fast_provider_chunk_ids jsonb := '[]'::jsonb;
  v_fast_provider_transfer_ids jsonb := '[]'::jsonb;
  v_fast_provider_auth_request_ids jsonb := '[]'::jsonb;
  v_fast_provider_review_reasons jsonb := '[]'::jsonb;
  v_bounded_provider_finalise_chunk_id uuid := NULL::uuid;
  v_bounded_provider_finalise_chunk_ids jsonb := '[]'::jsonb;
  v_bounded_provider_finalise_transfer_ids jsonb := '[]'::jsonb;
  v_bounded_provider_finalise_chunk_count integer := 0;
  v_bounded_provider_finalise_transfer_count integer := 0;
  v_bounded_provider_finalise_unfinalised_count integer := 0;
  v_bounded_provider_finalise_allowed boolean := false;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: operation_id is required'
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_failure_phase := NULLIF(BTRIM(COALESCE(p_failure_phase, '')), '');

  IF p_failure_error_json IS NOT NULL AND jsonb_typeof(p_failure_error_json) = 'object' THEN
    v_failure_error_json := p_failure_error_json;
  ELSE
    v_failure_error_json := '{}'::jsonb;
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF v_operation_row.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_NOT_FOUND',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: operation not found',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id);

  IF v_effective_actor_user_id IS NOT NULL
     AND NOT EXISTS (
       SELECT 1
       FROM public.tms_users AS actor_user
       WHERE actor_user.id = v_effective_actor_user_id
     ) THEN
    v_effective_actor_user_id := NULL::uuid;
  END IF;

  v_operation_type_upper := upper(BTRIM(COALESCE(v_operation_row.operation_type, '')));
  v_operation_type_cleanup_mode := CASE
    WHEN v_operation_type_upper = 'PAYMENT_EXECUTE' THEN 'STANDARD_PAYMENT_EXECUTE_LOCAL_ARTIFACT_CLEANUP'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS' THEN 'CONDITIONAL_BLOCKED_FUNDS_RETRY_LOCAL_ARTIFACT_CLEANUP'
    ELSE 'UNSUPPORTED_OPERATION_TYPE'
  END;

  IF v_operation_type_upper NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'OPERATION_TYPE_NOT_SUPPORTED',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: only PAYMENT_EXECUTE and proven local PAYMENT_RETRY_BLOCKED_FUNDS operations are supported',
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type,
      'operation_types_supported', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF upper(BTRIM(COALESCE(v_operation_row.status, ''))) = 'COMPLETE' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'COMPLETE_OPERATION_CANNOT_BE_CLEANED',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: completed payment execution operations cannot be cleaned as failed local artefacts',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: operation has no pay_batch_id',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_failure_phase IS NULL THEN
    v_failure_phase := NULLIF(BTRIM(COALESCE(v_operation_row.phase, '')), '');
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = v_operation_row.pay_batch_id
  FOR UPDATE;

  IF v_batch_row.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_OPERATION_CLEANUP_FAILED_LOCAL_ARTIFACTS',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_execute_operation_cleanup_failed_local_artifacts: pay batch not found',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation_row.pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_batch_execution_boundary_crossed := (
    upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED'
    OR NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
    OR v_batch_row.execution_committed_at_utc IS NOT NULL
  );


  v_pre_provider_fast_cleanup_phase := upper(BTRIM(COALESCE(v_failure_phase, ''))) IN (
    'PREPARE_TRANSFER_SCOPE',
    'SEED_TRANSFER_CHUNKS',
    'PREPARE_TRANSFER_CHUNKS',
    'PREPARE_BATCH',
    'START_AUTHORISATION',
    'WAIT_FOR_AUTHORISATION',
    'SCHEDULE_OR_SUBMIT'
  );

  IF v_pre_provider_fast_cleanup_phase IS TRUE THEN
    DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_cleanup_scope_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_cleanup_scope_ids (
      scope_id uuid PRIMARY KEY,
      pay_bank_transfer_id uuid,
      pay_channel text,
      transfer_group_key text,
      scope_status text
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids (
      pay_bank_transfer_id uuid PRIMARY KEY,
      pay_channel text,
      transfer_group_key text,
      transfer_status text,
      request_id text,
      payment_reference text,
      rail_tx_id text,
      rail_state text,
      completed_at_utc timestamptz,
      failed_reason text,
      rail_meta_json jsonb
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_pay_execute_fast_cleanup_scope_ids (
      scope_id,
      pay_bank_transfer_id,
      pay_channel,
      transfer_group_key,
      scope_status
    )
    SELECT operation_scope.id,
           operation_scope.pay_bank_transfer_id,
           operation_scope.pay_channel,
           operation_scope.transfer_group_key,
           operation_scope.status
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND operation_scope.pay_batch_id = v_operation_row.pay_batch_id;

    INSERT INTO pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids (
      pay_bank_transfer_id,
      pay_channel,
      transfer_group_key,
      transfer_status,
      request_id,
      payment_reference,
      rail_tx_id,
      rail_state,
      completed_at_utc,
      failed_reason,
      rail_meta_json
    )
    SELECT DISTINCT transfer_row.id,
           transfer_row.pay_channel,
           transfer_row.transfer_group_key,
           transfer_row.status,
           transfer_row.request_id,
           transfer_row.payment_reference,
           transfer_row.rail_tx_id,
           transfer_row.rail_state,
           transfer_row.completed_at_utc,
           transfer_row.failed_reason,
           COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = v_operation_row.pay_batch_id
      AND (
        EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_execute_fast_cleanup_scope_ids AS fast_scope
          WHERE fast_scope.pay_bank_transfer_id = transfer_row.id
        )
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{created_by_operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_execute_operation_id}', '')) = p_operation_id::text
        OR transfer_row.request_id LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')) LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      );

    SELECT COUNT(*)::integer
    INTO v_scope_rows_considered
    FROM pg_temp.tmp_pay_execute_fast_cleanup_scope_ids AS fast_scope_count;

    SELECT COUNT(*)::integer
    INTO v_transfer_rows_considered
    FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer_count;

    SELECT COUNT(*)::integer
    INTO v_fast_provider_submit_chunk_count
    FROM public.banking_pay_operation_chunks AS provider_submit_chunk
    WHERE provider_submit_chunk.operation_id = p_operation_id
      AND (
        provider_submit_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
        OR provider_submit_chunk.chunk_type = 'TRANSFER_SUBMIT'
      );

    SELECT COUNT(*)::integer
    INTO v_fast_transfer_event_count
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE transfer_event.pay_batch_id = v_operation_row.pay_batch_id
      AND (
        EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
          WHERE fast_transfer.pay_bank_transfer_id = transfer_event.pay_bank_transfer_id
        )
        OR POSITION(lower(p_operation_id::text) IN lower(COALESCE(transfer_event.raw_payload::text, ''))) > 0
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
          WHERE transfer_event.pay_bank_transfer_id IS NULL
            AND (
              NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                fast_transfer.pay_bank_transfer_id::text,
                NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.payment_reference, '')), '')
              ]::text[], NULL::text))
              OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                fast_transfer.pay_bank_transfer_id::text,
                NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.payment_reference, '')), '')
              ]::text[], NULL::text))
              OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                fast_transfer.pay_bank_transfer_id::text,
                NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(fast_transfer.payment_reference, '')), '')
              ]::text[], NULL::text))
              OR EXISTS (
                SELECT 1
                FROM (VALUES
                  (fast_transfer.pay_bank_transfer_id::text),
                  (NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), '')),
                  (NULLIF(BTRIM(COALESCE(fast_transfer.request_id, '')), '')),
                  (NULLIF(BTRIM(COALESCE(fast_transfer.payment_reference, '')), ''))
                ) AS fast_transfer_identity(identity_value)
                WHERE LENGTH(NULLIF(BTRIM(COALESCE(fast_transfer_identity.identity_value, '')), '')) >= 8
                  AND POSITION(lower(NULLIF(BTRIM(COALESCE(fast_transfer_identity.identity_value, '')), '')) IN lower(COALESCE(transfer_event.raw_payload::text, ''))) > 0
              )
            )
        )
      );

    SELECT COUNT(*)::integer
    INTO v_fast_other_operation_scope_count
    FROM public.banking_pay_operation_transfer_scope AS other_operation_scope
    WHERE other_operation_scope.operation_id <> p_operation_id
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
        WHERE fast_transfer.pay_bank_transfer_id = other_operation_scope.pay_bank_transfer_id
      );

    SELECT COUNT(*)::integer
    INTO v_fast_payment_correction_reference_count
    FROM (
      SELECT correction_item.pay_bank_transfer_id
      FROM public.pay_payment_correction_items AS correction_item
      WHERE EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
        WHERE fast_transfer.pay_bank_transfer_id = correction_item.pay_bank_transfer_id
      )
      UNION ALL
      SELECT correction_work_item.pay_bank_transfer_id
      FROM public.pay_payment_correction_work_items AS correction_work_item
      WHERE EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
        WHERE fast_transfer.pay_bank_transfer_id = correction_work_item.pay_bank_transfer_id
      )
    ) AS payment_correction_reference;

    SELECT COUNT(*)::integer
    INTO v_fast_external_transfer_marker_count
    FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
    WHERE upper(BTRIM(COALESCE(fast_transfer.transfer_status, ''))) <> 'PENDING'
       OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), '') IS NOT NULL
       OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_state, '')), '') IS NOT NULL
       OR fast_transfer.completed_at_utc IS NOT NULL
       OR NULLIF(BTRIM(COALESCE(fast_transfer.failed_reason, '')), '') IS NOT NULL
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'CLAIMED_NOT_PROVIDER_CALLED_YET', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL');

    SELECT COUNT(*)::integer
    INTO v_fast_provider_request_marker_count
    FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
    WHERE lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
       OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL;

    SELECT COUNT(*) FILTER (
             WHERE nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
               AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'AUTHORISED')
           )::integer,
           COUNT(*) FILTER (
             WHERE nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
               AND upper(BTRIM(COALESCE(auth_request.state, ''))) = 'PENDING_AUTHORISATION'
           )::integer,
           COUNT(*) FILTER (
             WHERE COALESCE(nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), ''), '') <> p_operation_id::text
           )::integer,
           COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb)
    INTO v_fast_same_operation_cancellable_auth_count,
         v_fast_same_operation_pending_auth_count,
         v_fast_other_active_auth_count,
         v_active_auth_request_count,
         v_active_auth_request_ids
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

    v_initial_active_auth_request_count := COALESCE(v_active_auth_request_count, 0);
    v_operation_active_auth_request_count := COALESCE(v_fast_same_operation_cancellable_auth_count, 0) + COALESCE(v_fast_same_operation_pending_auth_count, 0);
    v_cancellable_auth_request_count := COALESCE(v_fast_same_operation_cancellable_auth_count, 0);
    v_non_cancellable_auth_request_count := COALESCE(v_fast_same_operation_pending_auth_count, 0) + COALESCE(v_fast_other_active_auth_count, 0);
    v_active_auth_request_blocker_count := COALESCE(v_non_cancellable_auth_request_count, 0);
    v_provider_submit_chunk_attempt_count := COALESCE(v_fast_provider_submit_chunk_count, 0);
    v_provider_response_present_count := COALESCE(v_fast_transfer_event_count, 0);
    v_provider_request_sent_count := COALESCE(v_fast_provider_request_marker_count, 0);
    v_provider_submission_unknown_count := CASE WHEN COALESCE(v_fast_provider_submit_chunk_count, 0) > 0 OR COALESCE(v_fast_transfer_event_count, 0) > 0 OR COALESCE(v_fast_external_transfer_marker_count, 0) > 0 THEN 1 ELSE 0 END;
    v_provider_evidence_count := COALESCE(v_fast_transfer_event_count, 0);
    v_provider_review_risk_count := COALESCE(v_fast_provider_submit_chunk_count, 0) + COALESCE(v_fast_transfer_event_count, 0) + COALESCE(v_fast_external_transfer_marker_count, 0);
    v_stale_empty_provider_submit_chunk_count := 0;
    v_provider_submit_unknown_chunk_count := v_provider_submission_unknown_count;

    v_fast_cleanup_blocker_reasons := '[]'::jsonb;

    IF v_batch_execution_boundary_crossed IS TRUE THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'BATCH_EXECUTION_BOUNDARY_CROSSED'));
    END IF;

    IF COALESCE(v_fast_provider_submit_chunk_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'PROVIDER_SUBMIT_CHUNK_PRESENT', 'count', v_fast_provider_submit_chunk_count));
    END IF;

    IF COALESCE(v_fast_transfer_event_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'TRANSFER_EVENT_PRESENT', 'count', v_fast_transfer_event_count));
    END IF;

    IF COALESCE(v_fast_external_transfer_marker_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'TRANSFER_EXTERNAL_OR_PROVIDER_MARKER_PRESENT', 'count', v_fast_external_transfer_marker_count));
    END IF;

    IF COALESCE(v_fast_other_operation_scope_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'TRANSFER_HELD_BY_OTHER_OPERATION_SCOPE', 'count', v_fast_other_operation_scope_count));
    END IF;

    IF COALESCE(v_fast_payment_correction_reference_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'PAYMENT_CORRECTION_REFERENCE_PRESENT', 'count', v_fast_payment_correction_reference_count));
    END IF;

    IF COALESCE(v_fast_same_operation_pending_auth_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'SAME_OPERATION_PENDING_AUTHORISATION_PRESENT', 'count', v_fast_same_operation_pending_auth_count));
    END IF;

    IF COALESCE(v_fast_other_active_auth_count, 0) > 0 THEN
      v_fast_cleanup_blocker_reasons := v_fast_cleanup_blocker_reasons || jsonb_build_array(jsonb_build_object('reason', 'OTHER_ACTIVE_AUTH_REQUEST_PRESENT', 'count', v_fast_other_active_auth_count));
    END IF;

    v_fast_cleanup_allowed := jsonb_array_length(COALESCE(v_fast_cleanup_blocker_reasons, '[]'::jsonb)) = 0;
    v_deletion_allowed := v_fast_cleanup_allowed;
    v_provider_submission_status := CASE WHEN COALESCE(v_provider_submission_unknown_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' ELSE 'NO_PROVIDER_SUBMISSION_ATTEMPTED' END;
    v_provider_submit_review_reason_code := CASE WHEN COALESCE(v_provider_submission_unknown_count, 0) > 0 THEN 'PROVIDER_EVIDENCE_OR_SUBMIT_CHUNK_PRESENT' ELSE 'NO_PROVIDER_SUBMIT_ATTEMPT' END;
    v_provider_recommended_action := CASE WHEN COALESCE(v_provider_submission_unknown_count, 0) > 0 THEN 'Provider/submission evidence exists, so automatic local cleanup was refused. Review the payment issue before retrying.' ELSE 'No provider submission attempt has been recorded for this pre-provider failure scope.' END;
    v_provider_manual_resolution_required := COALESCE(v_provider_submission_unknown_count, 0) > 0;
    v_provider_submit_diagnostic := jsonb_strip_nulls(jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'FAST_PRE_PROVIDER_CLEANUP',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation_row.pay_batch_id::text,
      'failure_phase', v_failure_phase,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'recommended_action', v_provider_recommended_action,
      'manual_resolution_required', v_provider_manual_resolution_required,
      'provider_request_sent', COALESCE(v_fast_provider_request_marker_count, 0) > 0,
      'provider_response_present', COALESCE(v_fast_transfer_event_count, 0) > 0,
      'provider_acceptance_evidence_present', false,
      'provider_submit_chunk_count', COALESCE(v_fast_provider_submit_chunk_count, 0),
      'provider_request_marker_count', COALESCE(v_fast_provider_request_marker_count, 0),
      'transfer_event_count', COALESCE(v_fast_transfer_event_count, 0),
      'external_transfer_marker_count', COALESCE(v_fast_external_transfer_marker_count, 0),
      'other_operation_scope_count', COALESCE(v_fast_other_operation_scope_count, 0),
      'payment_correction_reference_count', COALESCE(v_fast_payment_correction_reference_count, 0),
      'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
      'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
      'cleanup_allowed', v_fast_cleanup_allowed,
      'blocker_reasons', COALESCE(v_fast_cleanup_blocker_reasons, '[]'::jsonb),
      'generated_at_utc', v_now::text
    ));

    IF v_fast_cleanup_allowed IS TRUE THEN
      v_safe_scope_candidate_count := COALESCE(v_scope_rows_considered, 0);
      v_safe_transfer_candidate_count := COALESCE(v_transfer_rows_considered, 0);
      v_safe_scope_ids := COALESCE((
        SELECT jsonb_agg(to_jsonb(fast_scope.scope_id::text) ORDER BY fast_scope.scope_id)
        FROM pg_temp.tmp_pay_execute_fast_cleanup_scope_ids AS fast_scope
      ), '[]'::jsonb);
      v_safe_transfer_ids := COALESCE((
        SELECT jsonb_agg(to_jsonb(fast_transfer.pay_bank_transfer_id::text) ORDER BY fast_transfer.pay_bank_transfer_id)
        FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
      ), '[]'::jsonb);
    ELSE
      v_safe_scope_candidate_count := 0;
      v_safe_transfer_candidate_count := 0;
      v_unsafe_scope_count := CASE WHEN COALESCE(v_scope_rows_considered, 0) > 0 THEN COALESCE(v_scope_rows_considered, 0) ELSE 0 END;
      v_unsafe_transfer_count := CASE WHEN COALESCE(v_transfer_rows_considered, 0) > 0 THEN COALESCE(v_transfer_rows_considered, 0) ELSE 0 END;
      v_unsafe_reasons := COALESCE(v_fast_cleanup_blocker_reasons, '[]'::jsonb);
      v_unsafe_transfer_ids := COALESCE((
        SELECT jsonb_agg(to_jsonb(fast_transfer.pay_bank_transfer_id::text) ORDER BY fast_transfer.pay_bank_transfer_id)
        FROM pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS fast_transfer
      ), '[]'::jsonb);
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (
      auth_request_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states;
    CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states (
      auth_request_id uuid PRIMARY KEY,
      previous_state text NOT NULL
    ) ON COMMIT DROP;

    IF COALESCE(p_dry_run, false) IS TRUE THEN
      IF v_fast_cleanup_allowed IS TRUE THEN
        INSERT INTO pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states (
          auth_request_id,
          previous_state
        )
        SELECT auth_request.id,
               upper(BTRIM(COALESCE(auth_request.state, ''))) AS previous_state
        FROM public.pay_batch_auth_requests AS auth_request
        WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
          AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'AUTHORISED')
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
        ON CONFLICT DO NOTHING;

        INSERT INTO pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (auth_request_id)
        SELECT cancelled_auth_state.auth_request_id
        FROM pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states AS cancelled_auth_state
        ON CONFLICT DO NOTHING;

        SELECT COUNT(*)::integer,
               COALESCE(jsonb_agg(to_jsonb(cancelled_auth_request.auth_request_id::text) ORDER BY cancelled_auth_request.auth_request_id), '[]'::jsonb)
        INTO v_auth_requests_cancelled,
             v_cancelled_auth_request_ids
        FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request;

        SELECT COUNT(*) FILTER (WHERE cancelled_auth_state.previous_state = 'AWAITING')::integer,
               COUNT(*) FILTER (WHERE cancelled_auth_state.previous_state = 'AUTHORISED')::integer
        INTO v_awaiting_auth_requests_cancelled,
             v_authorised_auth_requests_cancelled
        FROM pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states AS cancelled_auth_state;

        SELECT COUNT(*)::integer,
               COALESCE((COUNT(*) FILTER (
                 WHERE item_row.bank_reference = transfer_row.payment_reference
                   AND NULLIF(BTRIM(COALESCE(item_row.bank_reference, '')), '') IS NOT NULL
               )), 0)::integer
        INTO v_item_links_cleared,
             v_bank_references_cleared
        FROM public.pay_batch_items AS item_row
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id = item_row.pay_batch_candidate_id
         AND batch_candidate.pay_batch_id = v_operation_row.pay_batch_id
        JOIN pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS safe_transfer
          ON safe_transfer.pay_bank_transfer_id = item_row.pay_bank_transfer_id
        JOIN public.pay_bank_transfers AS transfer_row
          ON transfer_row.id = safe_transfer.pay_bank_transfer_id;

        SELECT COALESCE((COUNT(*) FILTER (WHERE operation_chunk.status = 'RUNNING')), 0)::integer,
               COALESCE((COUNT(*) FILTER (WHERE operation_chunk.status = 'PENDING')), 0)::integer,
               COALESCE((COUNT(*) FILTER (WHERE operation_chunk.locked_by IS NOT NULL OR operation_chunk.lock_expires_at_utc IS NOT NULL)), 0)::integer
        INTO v_chunks_marked_failed,
             v_chunks_marked_skipped,
             v_locks_released
        FROM public.banking_pay_operation_chunks AS operation_chunk
        WHERE operation_chunk.operation_id = p_operation_id
          AND operation_chunk.status IN ('PENDING', 'RUNNING')
          AND NOT (
            operation_chunk.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'APPLY_SETTLEMENT_CHUNKS', 'QUEUE_REMITTANCE_CHUNKS', 'QUEUE_PAYOUT_NOTICE_CHUNKS')
            OR operation_chunk.chunk_type IN ('TRANSFER_SUBMIT', 'RAIL_UPDATE', 'SETTLEMENT_APPLY', 'REMITTANCE_QUEUE', 'PAYOUT_NOTICE_QUEUE')
          );

        v_scope_rows_deleted := COALESCE(v_safe_scope_candidate_count, 0);
        v_transfer_rows_deleted := COALESCE(v_safe_transfer_candidate_count, 0);
      END IF;
    ELSIF v_fast_cleanup_allowed IS TRUE THEN
      WITH same_operation_auth_requests AS (
        SELECT auth_request.id,
               upper(BTRIM(COALESCE(auth_request.state, ''))) AS auth_state
        FROM public.pay_batch_auth_requests AS auth_request
        WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
          AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'AUTHORISED')
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
      ), cancelled_auth_requests AS (
        UPDATE public.pay_batch_auth_requests AS auth_request_update
        SET state = 'CANCELLED',
            finalised_at_utc = COALESCE(auth_request_update.finalised_at_utc, v_now),
            finalised_by_user_id = COALESCE(auth_request_update.finalised_by_user_id, v_effective_actor_user_id),
            execution_intent_json = jsonb_strip_nulls(
              COALESCE(auth_request_update.execution_intent_json, '{}'::jsonb)
              || jsonb_build_object(
                'cancelled_by_fast_pre_provider_cleanup', true,
                'cleanup_operation_id', p_operation_id::text,
                'cleanup_at_utc', v_now::text,
                'failure_phase', v_failure_phase
              )
            )
        FROM same_operation_auth_requests
        WHERE auth_request_update.id = same_operation_auth_requests.id
        RETURNING auth_request_update.id, same_operation_auth_requests.auth_state
      )
      INSERT INTO pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states (
        auth_request_id,
        previous_state
      )
      SELECT cancelled_auth_requests.id,
             cancelled_auth_requests.auth_state
      FROM cancelled_auth_requests
      ON CONFLICT DO NOTHING;

      INSERT INTO pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (auth_request_id)
      SELECT cancelled_auth_state.auth_request_id
      FROM pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states AS cancelled_auth_state
      ON CONFLICT DO NOTHING;

      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(cancelled_auth_request.auth_request_id::text) ORDER BY cancelled_auth_request.auth_request_id), '[]'::jsonb)
      INTO v_auth_requests_cancelled,
           v_cancelled_auth_request_ids
      FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request;

      SELECT COUNT(*) FILTER (WHERE cancelled_auth_state.previous_state = 'AWAITING')::integer,
             COUNT(*) FILTER (WHERE cancelled_auth_state.previous_state = 'AUTHORISED')::integer
      INTO v_awaiting_auth_requests_cancelled,
           v_authorised_auth_requests_cancelled
      FROM pg_temp.tmp_pay_execute_fast_cleanup_cancelled_auth_request_states AS cancelled_auth_state;

      WITH voided_tokens AS (
        UPDATE public.pay_batch_auth_tokens AS auth_token_update
        SET used_at_utc = COALESCE(auth_token_update.used_at_utc, v_now),
            expires_at_utc = CASE
              WHEN auth_token_update.expires_at_utc > v_now THEN v_now
              ELSE auth_token_update.expires_at_utc
            END
        FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request
        WHERE auth_token_update.auth_request_id = cancelled_auth_request.auth_request_id
          AND (auth_token_update.used_at_utc IS NULL OR auth_token_update.expires_at_utc > v_now)
        RETURNING auth_token_update.token
      )
      SELECT COUNT(*)::integer
      INTO v_auth_tokens_voided
      FROM voided_tokens;

      WITH cleared_batch_intent AS (
        UPDATE public.pay_batches AS batch_update
        SET schedule_kind = NULL::text,
            scheduled_at_utc = NULL::timestamptz,
            scheduled_by_user_id = NULL::uuid,
            funding_account_ref = NULL::text,
            funds_warning_hours_json = NULL::jsonb,
            execution_intent_json = NULL::jsonb
        WHERE batch_update.id = v_operation_row.pay_batch_id
          AND v_batch_execution_boundary_crossed IS NOT TRUE
          AND (
            NULLIF(BTRIM(COALESCE(batch_update.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
            OR EXISTS (
              SELECT 1
              FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request
              WHERE NULLIF(BTRIM(COALESCE(batch_update.execution_intent_json->>'auth_request_id', '')), '') = cancelled_auth_request.auth_request_id::text
            )
          )
        RETURNING batch_update.id
      )
      SELECT COUNT(*)::integer
      INTO v_batch_execution_intent_cleared
      FROM cleared_batch_intent;

      WITH item_rows_to_clear AS (
        SELECT item_row.id AS pay_batch_item_id,
               item_row.bank_reference AS previous_bank_reference,
               transfer_row.payment_reference AS transfer_payment_reference
        FROM public.pay_batch_items AS item_row
        JOIN public.pay_batch_candidates AS batch_candidate
          ON batch_candidate.id = item_row.pay_batch_candidate_id
         AND batch_candidate.pay_batch_id = v_operation_row.pay_batch_id
        JOIN pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS safe_transfer
          ON safe_transfer.pay_bank_transfer_id = item_row.pay_bank_transfer_id
        JOIN public.pay_bank_transfers AS transfer_row
          ON transfer_row.id = safe_transfer.pay_bank_transfer_id
      ), cleared_item_links AS (
        UPDATE public.pay_batch_items AS item_update
        SET pay_bank_transfer_id = NULL,
            bank_reference = CASE
              WHEN item_update.bank_reference = item_rows_to_clear.transfer_payment_reference THEN NULL
              ELSE item_update.bank_reference
            END,
            updated_at = v_now
        FROM item_rows_to_clear
        WHERE item_update.id = item_rows_to_clear.pay_batch_item_id
        RETURNING item_update.id,
                  item_rows_to_clear.previous_bank_reference,
                  item_rows_to_clear.transfer_payment_reference
      )
      SELECT COUNT(*)::integer,
             COALESCE((COUNT(*) FILTER (
               WHERE cleared_item_links.previous_bank_reference = cleared_item_links.transfer_payment_reference
                 AND NULLIF(BTRIM(COALESCE(cleared_item_links.previous_bank_reference, '')), '') IS NOT NULL
             )), 0)::integer
      INTO v_item_links_cleared,
           v_bank_references_cleared
      FROM cleared_item_links;

      WITH deleted_scope_rows AS (
        DELETE FROM public.banking_pay_operation_transfer_scope AS scope_delete
        USING pg_temp.tmp_pay_execute_fast_cleanup_scope_ids AS safe_scope
        WHERE scope_delete.id = safe_scope.scope_id
          AND scope_delete.operation_id = p_operation_id
          AND scope_delete.pay_batch_id = v_operation_row.pay_batch_id
        RETURNING scope_delete.id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(deleted_scope_rows.id::text) ORDER BY deleted_scope_rows.id), '[]'::jsonb)
      INTO v_scope_rows_deleted,
           v_deleted_scope_ids
      FROM deleted_scope_rows;

      WITH deleted_transfer_rows AS (
        DELETE FROM public.pay_bank_transfers AS transfer_delete
        USING pg_temp.tmp_pay_execute_fast_cleanup_transfer_ids AS safe_transfer
        WHERE transfer_delete.id = safe_transfer.pay_bank_transfer_id
          AND transfer_delete.pay_batch_id = v_operation_row.pay_batch_id
          AND NOT EXISTS (
            SELECT 1
            FROM public.banking_pay_operation_transfer_scope AS remaining_scope
            WHERE remaining_scope.pay_bank_transfer_id = transfer_delete.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_batch_items AS remaining_item
            WHERE remaining_item.pay_bank_transfer_id = transfer_delete.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_bank_transfer_events AS transfer_event
            WHERE transfer_event.pay_bank_transfer_id = transfer_delete.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_items AS correction_item
            WHERE correction_item.pay_bank_transfer_id = transfer_delete.id
          )
          AND NOT EXISTS (
            SELECT 1
            FROM public.pay_payment_correction_work_items AS correction_work_item
            WHERE correction_work_item.pay_bank_transfer_id = transfer_delete.id
          )
        RETURNING transfer_delete.id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(deleted_transfer_rows.id::text) ORDER BY deleted_transfer_rows.id), '[]'::jsonb)
      INTO v_transfer_rows_deleted,
           v_deleted_transfer_ids
      FROM deleted_transfer_rows;

      WITH chunks_to_mutate AS (
        SELECT operation_chunk.id AS operation_chunk_id,
               operation_chunk.status AS previous_status,
               (operation_chunk.locked_by IS NOT NULL OR operation_chunk.lock_expires_at_utc IS NOT NULL) AS had_lock
        FROM public.banking_pay_operation_chunks AS operation_chunk
        WHERE operation_chunk.operation_id = p_operation_id
          AND operation_chunk.status IN ('PENDING', 'RUNNING')
          AND NOT (
            operation_chunk.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'APPLY_SETTLEMENT_CHUNKS', 'QUEUE_REMITTANCE_CHUNKS', 'QUEUE_PAYOUT_NOTICE_CHUNKS')
            OR operation_chunk.chunk_type IN ('TRANSFER_SUBMIT', 'RAIL_UPDATE', 'SETTLEMENT_APPLY', 'REMITTANCE_QUEUE', 'PAYOUT_NOTICE_QUEUE')
          )
      ), mutated_chunks AS (
        UPDATE public.banking_pay_operation_chunks AS operation_chunk_update
        SET status = CASE WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN 'FAILED' ELSE 'SKIPPED' END,
            result_json = CASE
              WHEN chunks_to_mutate.previous_status = 'PENDING' THEN jsonb_strip_nulls(
                COALESCE(operation_chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
                  'skipped_by_fast_pre_provider_cleanup', true,
                  'cleanup_operation_id', p_operation_id::text,
                  'cleanup_at_utc', v_now::text,
                  'failure_phase', v_failure_phase
                )
              )
              ELSE operation_chunk_update.result_json
            END,
            error_json = CASE
              WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN jsonb_strip_nulls(jsonb_build_object(
                'code', 'PAYMENT_EXECUTE_FAST_PRE_PROVIDER_CLEANUP',
                'message', 'Chunk was still running when fast pre-provider cleanup ran.',
                'operation_id', p_operation_id::text,
                'failure_phase', v_failure_phase,
                'cleanup_at_utc', v_now::text,
                'failure_code', NULLIF(BTRIM(COALESCE(v_failure_error_json->>'code', v_failure_error_json->>'error', '')), '')
              ))
              ELSE operation_chunk_update.error_json
            END,
            failed_count = CASE
              WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN
                CASE
                  WHEN COALESCE(operation_chunk_update.unit_count, 0) > 0 THEN GREATEST(COALESCE(operation_chunk_update.failed_count, 0), COALESCE(operation_chunk_update.unit_count, 0) - COALESCE(operation_chunk_update.completed_count, 0))
                  ELSE GREATEST(COALESCE(operation_chunk_update.failed_count, 0), 1)
                END
              ELSE operation_chunk_update.failed_count
            END,
            locked_by = NULL::text,
            lock_expires_at_utc = NULL::timestamptz,
            completed_at_utc = COALESCE(operation_chunk_update.completed_at_utc, v_now),
            updated_at_utc = v_now
        FROM chunks_to_mutate
        WHERE operation_chunk_update.id = chunks_to_mutate.operation_chunk_id
        RETURNING chunks_to_mutate.previous_status,
                  chunks_to_mutate.had_lock
      )
      SELECT COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'RUNNING')), 0)::integer,
             COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'PENDING')), 0)::integer,
             COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.had_lock)), 0)::integer
      INTO v_chunks_marked_failed,
           v_chunks_marked_skipped,
           v_locks_released
      FROM mutated_chunks;

      WITH terminal_lock_release AS (
        UPDATE public.banking_pay_operation_chunks AS terminal_chunk_update
        SET locked_by = NULL::text,
            lock_expires_at_utc = NULL::timestamptz,
            updated_at_utc = v_now
        WHERE terminal_chunk_update.operation_id = p_operation_id
          AND terminal_chunk_update.status IN ('COMPLETE', 'FAILED', 'SKIPPED')
          AND (terminal_chunk_update.locked_by IS NOT NULL OR terminal_chunk_update.lock_expires_at_utc IS NOT NULL)
          AND NOT (
            terminal_chunk_update.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'APPLY_SETTLEMENT_CHUNKS', 'QUEUE_REMITTANCE_CHUNKS', 'QUEUE_PAYOUT_NOTICE_CHUNKS')
            OR terminal_chunk_update.chunk_type IN ('TRANSFER_SUBMIT', 'RAIL_UPDATE', 'SETTLEMENT_APPLY', 'REMITTANCE_QUEUE', 'PAYOUT_NOTICE_QUEUE')
          )
        RETURNING terminal_chunk_update.id
      )
      SELECT COALESCE(v_locks_released, 0) + COUNT(*)::integer
      INTO v_locks_released
      FROM terminal_lock_release;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_remaining_operation_scope_count
    FROM public.banking_pay_operation_transfer_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = v_operation_row.pay_batch_id;

    SELECT COUNT(*)::integer
    INTO v_remaining_operation_transfer_count
    FROM public.pay_bank_transfers AS remaining_transfer
    WHERE remaining_transfer.pay_batch_id = v_operation_row.pay_batch_id
      AND (
        EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope AS remaining_scope
          WHERE remaining_scope.operation_id = p_operation_id
            AND remaining_scope.pay_batch_id = v_operation_row.pay_batch_id
            AND remaining_scope.pay_bank_transfer_id = remaining_transfer.id
        )
        OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{created_by_operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{payment_execute_operation_id}', '')) = p_operation_id::text
        OR remaining_transfer.request_id LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{request_id}', '')) LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{idempotency_key}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      );

    IF COALESCE(p_dry_run, false) IS TRUE THEN
      v_retry_blocked := v_fast_cleanup_allowed IS NOT TRUE;
    ELSE
      v_retry_blocked := (
        v_fast_cleanup_allowed IS NOT TRUE
        OR COALESCE(v_remaining_operation_scope_count, 0) > 0
        OR COALESCE(v_remaining_operation_transfer_count, 0) > 0
      );
    END IF;

    v_review_required := v_retry_blocked;
    v_safe_to_retry := (v_retry_blocked IS NOT TRUE);

    v_cleanup_mode := CASE
      WHEN COALESCE(p_dry_run, false) IS TRUE AND v_fast_cleanup_allowed IS TRUE THEN 'DRY_RUN_FAST_PRE_PROVIDER_LOCAL_CLEANUP'
      WHEN COALESCE(p_dry_run, false) IS TRUE THEN 'DRY_RUN_FAST_PRE_PROVIDER_REVIEW_REQUIRED'
      WHEN v_batch_execution_boundary_crossed THEN 'REVIEW_REQUIRED_BATCH_EXECUTION_BOUNDARY'
      WHEN COALESCE(v_fast_provider_submit_chunk_count, 0) > 0 THEN 'REVIEW_REQUIRED_PROVIDER_SUBMIT_CHUNK_PRESENT'
      WHEN COALESCE(v_fast_transfer_event_count, 0) > 0 THEN 'REVIEW_REQUIRED_TRANSFER_EVENT_PRESENT'
      WHEN COALESCE(v_fast_external_transfer_marker_count, 0) > 0 THEN 'REVIEW_REQUIRED_TRANSFER_EXTERNAL_OR_PROVIDER_MARKER_PRESENT'
      WHEN COALESCE(v_fast_other_operation_scope_count, 0) > 0 THEN 'REVIEW_REQUIRED_TRANSFER_HELD_BY_OTHER_OPERATION_SCOPE'
      WHEN COALESCE(v_fast_payment_correction_reference_count, 0) > 0 THEN 'REVIEW_REQUIRED_PAYMENT_CORRECTION_REFERENCE_PRESENT'
      WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'REVIEW_REQUIRED_ACTIVE_AUTH_REQUEST'
      WHEN COALESCE(v_remaining_operation_scope_count, 0) > 0 OR COALESCE(v_remaining_operation_transfer_count, 0) > 0 THEN 'REVIEW_REQUIRED_RETRY_BLOCKER_REMAINS'
      WHEN COALESCE(v_scope_rows_deleted, 0) > 0 OR COALESCE(v_transfer_rows_deleted, 0) > 0 OR COALESCE(v_item_links_cleared, 0) > 0 OR COALESCE(v_chunks_marked_failed, 0) > 0 OR COALESCE(v_chunks_marked_skipped, 0) > 0 OR COALESCE(v_auth_requests_cancelled, 0) > 0 THEN 'CLEANED_FAST_PRE_PROVIDER_LOCAL_ARTIFACTS'
      ELSE 'NO_LOCAL_ARTIFACTS_TO_CLEAN'
    END;

    v_retry_blocked_reason := CASE
      WHEN v_retry_blocked IS NOT TRUE THEN NULL::text
      WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED'
      WHEN COALESCE(v_fast_provider_submit_chunk_count, 0) > 0 THEN 'PROVIDER_SUBMIT_CHUNK_PRESENT'
      WHEN COALESCE(v_fast_transfer_event_count, 0) > 0 THEN 'TRANSFER_EVENT_PRESENT'
      WHEN COALESCE(v_fast_external_transfer_marker_count, 0) > 0 THEN 'TRANSFER_EXTERNAL_OR_PROVIDER_MARKER_PRESENT'
      WHEN COALESCE(v_fast_other_operation_scope_count, 0) > 0 THEN 'TRANSFER_HELD_BY_OTHER_OPERATION_SCOPE'
      WHEN COALESCE(v_fast_payment_correction_reference_count, 0) > 0 THEN 'PAYMENT_CORRECTION_REFERENCE_PRESENT'
      WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'ACTIVE_AUTH_REQUEST_PRESENT'
      WHEN COALESCE(v_remaining_operation_scope_count, 0) > 0 OR COALESCE(v_remaining_operation_transfer_count, 0) > 0 THEN 'RETRY_BLOCKER_REMAINS'
      ELSE 'FAST_PRE_PROVIDER_RETRY_BLOCKED'
    END;

    v_result := jsonb_strip_nulls(
      jsonb_build_object(
        'ok', true,
        'dry_run', COALESCE(p_dry_run, false),
        'dry_run_counts_are_prospective', COALESCE(p_dry_run, false),
        'fast_pre_provider_cleanup_path', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_operation_row.pay_batch_id::text,
        'failure_phase', v_failure_phase,
        'cleanup_mode', v_cleanup_mode,
        'operation_types_supported', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
        'operation_type_cleanup_mode', v_operation_type_cleanup_mode,
        'retry_blocked_reason', v_retry_blocked_reason,
        'safe_to_retry', v_safe_to_retry,
        'retry_blocked', v_retry_blocked,
        'review_required', v_review_required,
        'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
        'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
        'safe_scope_candidate_count', COALESCE(v_safe_scope_candidate_count, 0),
        'safe_transfer_candidate_count', COALESCE(v_safe_transfer_candidate_count, 0),
        'safe_local_transfer_count', COALESCE(v_safe_transfer_candidate_count, 0),
        'scope_rows_deleted', COALESCE(v_scope_rows_deleted, 0),
        'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
        'item_links_cleared', COALESCE(v_item_links_cleared, 0),
        'bank_references_cleared', COALESCE(v_bank_references_cleared, 0),
        'chunks_marked_failed', COALESCE(v_chunks_marked_failed, 0),
        'chunks_marked_skipped', COALESCE(v_chunks_marked_skipped, 0),
        'locks_released', COALESCE(v_locks_released, 0),
        'provider_evidence_count', COALESCE(v_provider_evidence_count, 0),
        'provider_review_risk_count', COALESCE(v_provider_review_risk_count, 0),
        'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
        'provider_submit_diagnostic_finalise_result', COALESCE(v_provider_submit_finalise_result, '{}'::jsonb),
        'provider_submission_status', v_provider_submission_status,
        'review_reason_code', v_provider_submit_review_reason_code,
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
        'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
        'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
        'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
        'recommended_action', v_provider_recommended_action,
        'safe_retry_available', COALESCE(v_safe_to_retry, false),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'unsafe_scope_count', COALESCE(v_unsafe_scope_count, 0),
        'unsafe_transfer_ids', COALESCE(v_unsafe_transfer_ids, '[]'::jsonb),
        'unsafe_reasons', COALESCE(v_unsafe_reasons, '[]'::jsonb)
      )
      ||
      jsonb_build_object(
        'safe_scope_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_scope_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_scope_ids, '[]'::jsonb) END,
        'safe_transfer_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_transfer_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_transfer_ids, '[]'::jsonb) END,
        'initial_active_auth_request_count', COALESCE(v_initial_active_auth_request_count, 0),
        'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
        'operation_active_auth_request_count', COALESCE(v_operation_active_auth_request_count, 0),
        'active_auth_request_ids', COALESCE(v_active_auth_request_ids, '[]'::jsonb),
        'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
        'awaiting_auth_requests_cancelled', COALESCE(v_awaiting_auth_requests_cancelled, 0),
        'authorised_auth_requests_cancelled', COALESCE(v_authorised_auth_requests_cancelled, 0),
        'auth_request_cleanup_mode', CASE WHEN COALESCE(v_auth_requests_cancelled, 0) > 0 THEN 'CANCELLED_SAFE_LOCAL_AUTH_REQUESTS' WHEN COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN 'AUTH_REQUEST_REVIEW_REQUIRED' ELSE 'NO_AUTH_REQUEST_CLEANUP_REQUIRED' END,
        'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
        'batch_execution_intent_cleared', COALESCE(v_batch_execution_intent_cleared, 0),
        'active_auth_request_blocker_count', COALESCE(v_active_auth_request_blocker_count, 0),
        'authorised_auth_request_review_count', COALESCE(v_authorised_auth_request_review_count, 0),
        'cancellable_auth_request_count', COALESCE(v_cancellable_auth_request_count, 0),
        'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
        'cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb),
        'provider_submit_chunk_attempt_count', COALESCE(v_provider_submit_chunk_attempt_count, 0),
        'stale_empty_provider_submit_chunk_count', COALESCE(v_stale_empty_provider_submit_chunk_count, 0),
        'provider_submit_unknown_chunk_count', COALESCE(v_provider_submit_unknown_chunk_count, 0),
        'other_operation_scope_count', COALESCE(v_fast_other_operation_scope_count, 0),
        'payment_correction_reference_count', COALESCE(v_fast_payment_correction_reference_count, 0),
        'batch_execution_boundary_crossed', v_batch_execution_boundary_crossed,
        'execution_commit_state', upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))),
        'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
        'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL,
        'remaining_operation_scope_count', COALESCE(v_remaining_operation_scope_count, 0),
        'remaining_operation_transfer_count', COALESCE(v_remaining_operation_transfer_count, 0)
      )
    );

    IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
      BEGIN
        PERFORM public._audit_insert(
          'banking_pay_operations',
          p_operation_id::text,
          'PAYMENT_EXECUTE_FAST_PRE_PROVIDER_LOCAL_ARTIFACT_CLEANUP',
          NULL::jsonb,
          v_result,
          'payment_execute_fast_pre_provider_local_artifact_cleanup',
          v_effective_actor_user_id
        );
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    RETURN v_result;
  END IF;


  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_provider_review_scope_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_provider_review_scope_ids (
    scope_id uuid PRIMARY KEY,
    pay_bank_transfer_id uuid,
    pay_channel text,
    transfer_group_key text,
    scope_status text
  ) ON COMMIT DROP;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids (
    pay_bank_transfer_id uuid PRIMARY KEY,
    pay_channel text,
    transfer_group_key text,
    transfer_status text,
    request_id text,
    payment_reference text,
    rail_tx_id text,
    rail_state text,
    completed_at_utc timestamptz,
    failed_reason text,
    rail_meta_json jsonb
  ) ON COMMIT DROP;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_fast_provider_review_markers;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_fast_provider_review_markers (
    source_kind text NOT NULL,
    source_id text,
    provider_submission_status text,
    review_reason_code text,
    provider_request_sent boolean NOT NULL DEFAULT false,
    provider_response_present boolean NOT NULL DEFAULT false,
    provider_response_received boolean NOT NULL DEFAULT false,
    provider_accepted boolean NOT NULL DEFAULT false,
    provider_rejected boolean NOT NULL DEFAULT false,
    provider_unknown boolean NOT NULL DEFAULT false,
    provider_malformed boolean NOT NULL DEFAULT false,
    provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    unfinalised_submit_chunk boolean NOT NULL DEFAULT false,
    marker_json jsonb NOT NULL DEFAULT '{}'::jsonb
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_scope_ids (
    scope_id,
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    scope_status
  )
  SELECT operation_scope.id,
         operation_scope.pay_bank_transfer_id,
         operation_scope.pay_channel,
         operation_scope.transfer_group_key,
         operation_scope.status
  FROM public.banking_pay_operation_transfer_scope AS operation_scope
  WHERE operation_scope.operation_id = p_operation_id
    AND operation_scope.pay_batch_id = v_operation_row.pay_batch_id;

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids (
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    transfer_status,
    request_id,
    payment_reference,
    rail_tx_id,
    rail_state,
    completed_at_utc,
    failed_reason,
    rail_meta_json
  )
  SELECT DISTINCT transfer_row.id,
         transfer_row.pay_channel,
         transfer_row.transfer_group_key,
         transfer_row.status,
         transfer_row.request_id,
         transfer_row.payment_reference,
         transfer_row.rail_tx_id,
         transfer_row.rail_state,
         transfer_row.completed_at_utc,
         transfer_row.failed_reason,
         COALESCE(transfer_row.rail_meta_json, '{}'::jsonb)
  FROM public.pay_bank_transfers AS transfer_row
  WHERE transfer_row.pay_batch_id = v_operation_row.pay_batch_id
    AND (
      EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_execute_fast_provider_review_scope_ids AS provider_scope
        WHERE provider_scope.pay_bank_transfer_id = transfer_row.id
      )
      OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{operation_id}', '')) = p_operation_id::text
      OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{created_by_operation_id}', '')) = p_operation_id::text
      OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_execute_operation_id}', '')) = p_operation_id::text
      OR transfer_row.request_id LIKE ('op:' || p_operation_id::text || ':%')
      OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')) LIKE ('op:' || p_operation_id::text || ':%')
    );

  SELECT COUNT(*)::integer
  INTO v_scope_rows_considered
  FROM pg_temp.tmp_pay_execute_fast_provider_review_scope_ids AS provider_scope_count;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(provider_transfer_count.pay_bank_transfer_id::text) ORDER BY provider_transfer_count.pay_bank_transfer_id), '[]'::jsonb)
  INTO v_transfer_rows_considered,
       v_fast_provider_transfer_ids
  FROM pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids AS provider_transfer_count;

  SELECT COUNT(*)::integer
  INTO v_fast_provider_submit_chunk_count
  FROM public.banking_pay_operation_chunks AS provider_chunk_count
  WHERE provider_chunk_count.operation_id = p_operation_id
    AND (
      provider_chunk_count.phase = 'SUBMIT_PROVIDER_TRANSFERS'
      OR provider_chunk_count.chunk_type = 'TRANSFER_SUBMIT'
    );

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_markers (
    source_kind,
    source_id,
    provider_submission_status,
    review_reason_code,
    provider_request_sent,
    provider_response_present,
    provider_response_received,
    provider_accepted,
    provider_rejected,
    provider_unknown,
    provider_malformed,
    provider_blocked_pre_call,
    unfinalised_submit_chunk,
    marker_json
  )
  SELECT 'failure_error'::text,
         p_operation_id::text,
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, ''))),
         upper(BTRIM(COALESCE(failure_diag.review_reason_code_value, ''))),
         lower(BTRIM(COALESCE(failure_diag.provider_request_sent_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(failure_diag.provider_response_present_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(failure_diag.provider_response_received_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
           OR lower(BTRIM(COALESCE(failure_diag.provider_submission_accepted_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR lower(BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_present_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_count_value, '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
           OR lower(BTRIM(COALESCE(failure_diag.provider_submission_rejected_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_rejection_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_rejection_count_value, '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
           OR lower(BTRIM(COALESCE(failure_diag.provider_submission_unknown_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_unknown_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_unknown_count_value, '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
         upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
         false,
         jsonb_strip_nulls(v_failure_error_json)
  FROM (
    SELECT
      COALESCE(
        v_failure_error_json->>'provider_submission_status',
        v_failure_error_json->>'providerSubmissionStatus',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_status',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionStatus',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_status',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionStatus',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_status',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionStatus',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_status',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionStatus',
        ''
      ) AS provider_submission_status_value,
      COALESCE(
        v_failure_error_json->>'provider_submit_review_reason_code',
        v_failure_error_json->>'providerSubmitReviewReasonCode',
        v_failure_error_json->>'review_reason_code',
        v_failure_error_json->>'reviewReasonCode',
        v_failure_error_json->'provider_submit_diagnostic'->>'review_reason_code',
        v_failure_error_json->'provider_submit_diagnostic'->>'reviewReasonCode',
        v_failure_error_json->'providerSubmitDiagnostic'->>'review_reason_code',
        v_failure_error_json->'providerSubmitDiagnostic'->>'reviewReasonCode',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'review_reason_code',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'reviewReasonCode',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'review_reason_code',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'reviewReasonCode',
        ''
      ) AS review_reason_code_value,
      COALESCE(
        v_failure_error_json->>'provider_request_sent',
        v_failure_error_json->>'providerRequestSent',
        v_failure_error_json->>'provider_request_sent_confirmed',
        v_failure_error_json->>'providerRequestSentConfirmed',
        v_failure_error_json->>'provider_called',
        v_failure_error_json->>'providerCalled',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_request_sent',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerRequestSent',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_request_sent_confirmed',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerRequestSentConfirmed',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_called',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerCalled',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_request_sent',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerRequestSent',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_request_sent_confirmed',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerRequestSentConfirmed',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_called',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerCalled',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_request_sent',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerRequestSent',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_request_sent_confirmed',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerRequestSentConfirmed',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_called',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerCalled',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_request_sent',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerRequestSent',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_request_sent_confirmed',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerRequestSentConfirmed',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_called',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerCalled',
        'false'
      ) AS provider_request_sent_value,
      COALESCE(
        v_failure_error_json->>'provider_response_present',
        v_failure_error_json->>'providerResponsePresent',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_response_present',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerResponsePresent',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_response_present',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerResponsePresent',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_response_present',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerResponsePresent',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_response_present',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerResponsePresent',
        'false'
      ) AS provider_response_present_value,
      COALESCE(
        v_failure_error_json->>'provider_response_received',
        v_failure_error_json->>'providerResponseReceived',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_response_received',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerResponseReceived',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_response_received',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerResponseReceived',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_response_received',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerResponseReceived',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_response_received',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerResponseReceived',
        'false'
      ) AS provider_response_received_value,
      COALESCE(
        v_failure_error_json->>'provider_submission_accepted',
        v_failure_error_json->>'providerSubmissionAccepted',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_accepted',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionAccepted',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_accepted',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionAccepted',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_accepted',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionAccepted',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_accepted',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionAccepted',
        'false'
      ) AS provider_submission_accepted_value,
      COALESCE(
        v_failure_error_json->>'provider_submission_rejected',
        v_failure_error_json->>'providerSubmissionRejected',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_rejected',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionRejected',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_rejected',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionRejected',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_rejected',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionRejected',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_rejected',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionRejected',
        'false'
      ) AS provider_submission_rejected_value,
      COALESCE(
        v_failure_error_json->>'provider_submission_unknown',
        v_failure_error_json->>'providerSubmissionUnknown',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_unknown',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionUnknown',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_unknown',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionUnknown',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_unknown',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionUnknown',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_unknown',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionUnknown',
        'false'
      ) AS provider_submission_unknown_value,
      COALESCE(
        v_failure_error_json->>'provider_acceptance_evidence_present',
        v_failure_error_json->>'providerAcceptanceEvidencePresent',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_acceptance_evidence_present',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerAcceptanceEvidencePresent',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_acceptance_evidence_present',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerAcceptanceEvidencePresent',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_acceptance_evidence_present',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerAcceptanceEvidencePresent',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_acceptance_evidence_present',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerAcceptanceEvidencePresent',
        'false'
      ) AS provider_acceptance_evidence_present_value,
      COALESCE(
        v_failure_error_json->>'provider_acceptance_evidence_count',
        v_failure_error_json->>'providerAcceptanceEvidenceCount',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_acceptance_evidence_count',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerAcceptanceEvidenceCount',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_acceptance_evidence_count',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerAcceptanceEvidenceCount',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_acceptance_evidence_count',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerAcceptanceEvidenceCount',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_acceptance_evidence_count',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerAcceptanceEvidenceCount',
        '0'
      ) AS provider_acceptance_evidence_count_value,
      COALESCE(
        v_failure_error_json->>'provider_rejection_count',
        v_failure_error_json->>'providerRejectionCount',
        v_failure_error_json->>'provider_submission_rejected_count',
        v_failure_error_json->>'providerSubmissionRejectedCount',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_rejection_count',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerRejectionCount',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_rejected_count',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionRejectedCount',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_rejection_count',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerRejectionCount',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_rejected_count',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionRejectedCount',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_rejection_count',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerRejectionCount',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_rejected_count',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionRejectedCount',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_rejection_count',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerRejectionCount',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_rejected_count',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionRejectedCount',
        '0'
      ) AS provider_rejection_count_value,
      COALESCE(
        v_failure_error_json->>'provider_unknown_count',
        v_failure_error_json->>'providerUnknownCount',
        v_failure_error_json->>'provider_submission_unknown_count',
        v_failure_error_json->>'providerSubmissionUnknownCount',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_unknown_count',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerUnknownCount',
        v_failure_error_json->'provider_submit_diagnostic'->>'provider_submission_unknown_count',
        v_failure_error_json->'provider_submit_diagnostic'->>'providerSubmissionUnknownCount',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_unknown_count',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerUnknownCount',
        v_failure_error_json->'providerSubmitDiagnostic'->>'provider_submission_unknown_count',
        v_failure_error_json->'providerSubmitDiagnostic'->>'providerSubmissionUnknownCount',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_unknown_count',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerUnknownCount',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'provider_submission_unknown_count',
        v_failure_error_json->'provider_submit_claim_diagnostic'->>'providerSubmissionUnknownCount',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_unknown_count',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerUnknownCount',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'provider_submission_unknown_count',
        v_failure_error_json->'providerSubmitClaimDiagnostic'->>'providerSubmissionUnknownCount',
        '0'
      ) AS provider_unknown_count_value,
      COALESCE(v_failure_error_json->'provider_submit_diagnostic', v_failure_error_json->'providerSubmitDiagnostic', '{}'::jsonb) AS provider_diag_json,
      COALESCE(v_failure_error_json->'provider_submit_claim_diagnostic', v_failure_error_json->'providerSubmitClaimDiagnostic', '{}'::jsonb) AS provider_claim_diag_json
  ) AS failure_diag
  WHERE upper(BTRIM(COALESCE(failure_diag.provider_submission_status_value, failure_diag.review_reason_code_value, ''))) NOT IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'CLAIMED_NOT_PROVIDER_CALLED_YET')
     OR lower(BTRIM(COALESCE(failure_diag.provider_request_sent_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR lower(BTRIM(COALESCE(failure_diag.provider_response_present_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR lower(BTRIM(COALESCE(failure_diag.provider_response_received_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR lower(BTRIM(COALESCE(failure_diag.provider_submission_accepted_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR lower(BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_present_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_acceptance_evidence_count_value, '0'))::integer ELSE 0 END > 0
     OR lower(BTRIM(COALESCE(failure_diag.provider_submission_rejected_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_rejection_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_rejection_count_value, '0'))::integer ELSE 0 END > 0
     OR lower(BTRIM(COALESCE(failure_diag.provider_submission_unknown_value, 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
     OR CASE WHEN BTRIM(COALESCE(failure_diag.provider_unknown_count_value, '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(failure_diag.provider_unknown_count_value, '0'))::integer ELSE 0 END > 0
     OR COALESCE(failure_diag.provider_diag_json, '{}'::jsonb) <> '{}'::jsonb
     OR COALESCE(failure_diag.provider_claim_diag_json, '{}'::jsonb) <> '{}'::jsonb;

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_markers (
    source_kind,
    source_id,
    provider_submission_status,
    review_reason_code,
    provider_request_sent,
    provider_response_present,
    provider_response_received,
    provider_accepted,
    provider_rejected,
    provider_unknown,
    provider_malformed,
    provider_blocked_pre_call,
    unfinalised_submit_chunk,
    marker_json
  )
  SELECT 'provider_chunk'::text,
         provider_chunk.id::text,
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', ''))),
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))),
         lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_request_sent', provider_chunk_diag.provider_submit_diagnostic->>'provider_request_sent_confirmed', provider_chunk_diag.provider_submit_diagnostic->>'provider_called', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_request_dispatched_at_utc', provider_chunk_diag.provider_submit_diagnostic->>'request_sent_at_utc', '')), '') IS NOT NULL,
         lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_response_present', provider_chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', provider_chunk_diag.provider_submit_diagnostic->>'provider_http_status', provider_chunk_diag.provider_submit_diagnostic->>'provider_error_code', '')), '') IS NOT NULL,
         lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', '')), '') IS NOT NULL,
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', provider_chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
           OR lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', provider_chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', provider_chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0'))::integer ELSE 0 END > 0
           OR NULLIF(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'rail_tx_id', provider_chunk_diag.provider_submit_diagnostic->>'provider_transaction_id', provider_chunk_diag.provider_submit_diagnostic->>'provider_payment_id', provider_chunk_diag.provider_submit_diagnostic->>'provider_reference', '')), '') IS NOT NULL,
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', provider_chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
           OR lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', provider_chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', provider_chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', provider_chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', provider_chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
           OR lower(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', provider_chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', provider_chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', provider_chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', provider_chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', provider_chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
         upper(BTRIM(COALESCE(provider_chunk_diag.provider_submit_diagnostic->>'provider_submission_status', provider_chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
         upper(BTRIM(COALESCE(provider_chunk.status, ''))) = 'RUNNING'
           AND (provider_chunk.lock_expires_at_utc IS NULL OR provider_chunk.lock_expires_at_utc <= v_now),
         jsonb_strip_nulls(COALESCE(provider_chunk_diag.provider_submit_diagnostic, '{}'::jsonb) || jsonb_build_object(
           'chunk_id', provider_chunk.id::text,
           'chunk_status', provider_chunk.status,
           'chunk_phase', provider_chunk.phase,
           'chunk_type', provider_chunk.chunk_type
         ))
  FROM public.banking_pay_operation_chunks AS provider_chunk
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      CASE WHEN jsonb_typeof(provider_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN provider_chunk.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(provider_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN provider_chunk.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(provider_chunk.payload_json->'provider_submit_diagnostic') = 'object' THEN provider_chunk.payload_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      '{}'::jsonb
    ) AS provider_submit_diagnostic
  ) AS provider_chunk_diag
  WHERE provider_chunk.operation_id = p_operation_id
    AND (
      provider_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
      OR provider_chunk.chunk_type = 'TRANSFER_SUBMIT'
    )
    AND (
      COALESCE(provider_chunk_diag.provider_submit_diagnostic, '{}'::jsonb) <> '{}'::jsonb
      OR upper(BTRIM(COALESCE(provider_chunk.status, ''))) IN ('RUNNING', 'COMPLETE', 'FAILED')
      OR provider_chunk.started_at_utc IS NOT NULL
    );

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_markers (
    source_kind,
    source_id,
    provider_submission_status,
    review_reason_code,
    provider_request_sent,
    provider_response_present,
    provider_response_received,
    provider_accepted,
    provider_rejected,
    provider_unknown,
    provider_malformed,
    provider_blocked_pre_call,
    unfinalised_submit_chunk,
    marker_json
  )
  SELECT 'transfer_meta'::text,
         fast_transfer.pay_bank_transfer_id::text,
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))),
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))),
         lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL,
         lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') IS NOT NULL,
         lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', '')), '') IS NOT NULL,
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
           OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0
           OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL,
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
           OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
           OR lower(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
         upper(BTRIM(COALESCE(fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', fast_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
         false,
         jsonb_strip_nulls(COALESCE(fast_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object(
           'pay_bank_transfer_id', fast_transfer.pay_bank_transfer_id::text,
           'rail_tx_id', fast_transfer.rail_tx_id,
           'rail_state', fast_transfer.rail_state,
           'transfer_status', fast_transfer.transfer_status
         ))
  FROM pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids AS fast_transfer
  WHERE COALESCE(fast_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) <> '{}'::jsonb
     OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_tx_id, '')), '') IS NOT NULL
     OR NULLIF(BTRIM(COALESCE(fast_transfer.rail_state, '')), '') IS NOT NULL
     OR fast_transfer.completed_at_utc IS NOT NULL
     OR NULLIF(BTRIM(COALESCE(fast_transfer.failed_reason, '')), '') IS NOT NULL;

  INSERT INTO pg_temp.tmp_pay_execute_fast_provider_review_markers (
    source_kind,
    source_id,
    provider_submission_status,
    review_reason_code,
    provider_request_sent,
    provider_response_present,
    provider_response_received,
    provider_accepted,
    provider_rejected,
    provider_unknown,
    provider_malformed,
    provider_blocked_pre_call,
    unfinalised_submit_chunk,
    marker_json
  )
  SELECT 'transfer_event'::text,
         transfer_event.id::text,
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))),
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))),
         true,
         true,
         true,
         (
             upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_accepted}', transfer_event.raw_payload #>> '{provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0
             OR (
               upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'SUBMITTED', 'SENT', 'PROCESSING', 'PENDING', 'COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
               AND EXISTS (
                 SELECT 1
                 FROM (VALUES
                   (transfer_event.provider_event_id),
                   (transfer_event.provider_reference),
                   (transfer_event.raw_payload #>> '{provider_event_id}'),
                   (transfer_event.raw_payload #>> '{provider_reference}'),
                   (transfer_event.raw_payload #>> '{provider_transaction_id}'),
                   (transfer_event.raw_payload #>> '{provider_payment_id}'),
                   (transfer_event.raw_payload #>> '{rail_tx_id}'),
                   (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                   (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                   (transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                   (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
                 ) AS event_identifier(identifier_value)
                 WHERE NULLIF(BTRIM(COALESCE(event_identifier.identifier_value, '')), '') IS NOT NULL
               )
             )
           ),
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED', 'FAILED', 'ERROR')
           OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected}', transfer_event.raw_payload #>> '{provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submission_rejected_count}', transfer_event.raw_payload #>> '{providerSubmissionRejectedCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submission_rejected_count}', transfer_event.raw_payload #>> '{providerSubmissionRejectedCount}', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
           OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown}', transfer_event.raw_payload #>> '{provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
           OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submission_unknown_count}', transfer_event.raw_payload #>> '{providerSubmissionUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submission_unknown_count}', transfer_event.raw_payload #>> '{providerSubmissionUnknownCount}', '0'))::integer ELSE 0 END > 0,
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
         upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
         false,
         jsonb_strip_nulls(COALESCE(transfer_event.raw_payload, '{}'::jsonb) || jsonb_build_object(
           'pay_bank_transfer_event_id', transfer_event.id::text,
           'pay_bank_transfer_id', transfer_event.pay_bank_transfer_id::text,
           'event_source', transfer_event.event_source,
           'normalised_state', transfer_event.normalised_state,
           'provider_state', transfer_event.provider_state
         ))
  FROM public.pay_bank_transfer_events AS transfer_event
  WHERE transfer_event.pay_batch_id = v_operation_row.pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_execute_fast_provider_review_transfer_ids AS fast_transfer
      WHERE fast_transfer.pay_bank_transfer_id = transfer_event.pay_bank_transfer_id
    );

  SELECT COUNT(*) FILTER (WHERE provider_marker.source_kind = 'failure_error')::integer,
         COUNT(*)::integer,
         COUNT(*) FILTER (WHERE provider_marker.source_kind = 'provider_chunk')::integer,
         COUNT(*) FILTER (WHERE provider_marker.source_kind = 'transfer_meta')::integer,
         COUNT(*) FILTER (WHERE provider_marker.source_kind = 'transfer_event')::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_rejected)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_accepted)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_unknown)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_malformed)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_blocked_pre_call)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_request_sent)::integer,
         COUNT(*) FILTER (WHERE provider_marker.provider_response_present OR provider_marker.provider_response_received)::integer,
         COUNT(*) FILTER (WHERE provider_marker.unfinalised_submit_chunk)::integer,
         COALESCE(jsonb_agg(to_jsonb(provider_marker.source_id) ORDER BY provider_marker.source_id) FILTER (WHERE provider_marker.source_kind = 'provider_chunk' AND provider_marker.source_id IS NOT NULL), '[]'::jsonb)
  INTO v_fast_provider_failure_error_marker_count,
       v_fast_provider_marker_count,
       v_fast_provider_chunk_marker_count,
       v_fast_provider_transfer_meta_marker_count,
       v_fast_provider_exact_event_count,
       v_fast_provider_rejected_count,
       v_fast_provider_accepted_count,
       v_fast_provider_unknown_count,
       v_fast_provider_malformed_count,
       v_fast_provider_blocked_pre_call_count,
       v_fast_provider_request_sent_count,
       v_fast_provider_response_present_count,
       v_fast_provider_unfinalised_count,
       v_fast_provider_chunk_ids
  FROM pg_temp.tmp_pay_execute_fast_provider_review_markers AS provider_marker;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb)
  INTO v_fast_provider_auth_request_count,
       v_fast_provider_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
    AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
    AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text;

  v_fast_provider_outcome_candidate := upper(BTRIM(COALESCE(v_failure_phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES')
    OR COALESCE(v_fast_provider_marker_count, 0) > 0;

  v_fast_provider_outcome_evidence_detected := COALESCE(v_fast_provider_marker_count, 0) > 0
    OR COALESCE(v_fast_provider_request_sent_count, 0) > 0
    OR COALESCE(v_fast_provider_response_present_count, 0) > 0
    OR COALESCE(v_fast_provider_unfinalised_count, 0) > 0;

  IF v_fast_provider_outcome_candidate IS TRUE
     AND v_fast_provider_outcome_evidence_detected IS TRUE THEN
    v_unfinalised_submit_chunk_count := GREATEST(COALESCE(v_unfinalised_submit_chunk_count, 0), COALESCE(v_fast_provider_unfinalised_count, 0));
    v_fast_provider_outcome_status := CASE
      WHEN COALESCE(v_fast_provider_accepted_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_ACCEPTED'
      WHEN COALESCE(v_fast_provider_rejected_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_REJECTED'
      WHEN COALESCE(v_fast_provider_malformed_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
      WHEN COALESCE(v_fast_provider_unknown_count, 0) > 0 OR COALESCE(v_fast_provider_unfinalised_count, 0) > 0 OR COALESCE(v_fast_provider_request_sent_count, 0) > 0 OR COALESCE(v_fast_provider_response_present_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
      WHEN COALESCE(v_fast_provider_blocked_pre_call_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      ELSE 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    END;

    v_provider_submission_status := v_fast_provider_outcome_status;
    v_provider_submit_review_reason_code := CASE
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_REJECTED_PAYMENT'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_RESPONSE_MALFORMED'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
      ELSE 'PROVIDER_REQUEST_SENT_NO_RESPONSE'
    END;
    v_fast_provider_outcome_cleanup_mode := CASE
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'REVIEW_REQUIRED_PROVIDER_ACCEPTANCE_EVIDENCE'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'REVIEW_REQUIRED_PROVIDER_REJECTED'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'REVIEW_REQUIRED_PROVIDER_MALFORMED_RESPONSE'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'REVIEW_REQUIRED_PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      ELSE 'REVIEW_REQUIRED_UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    END;
    v_cleanup_mode := v_fast_provider_outcome_cleanup_mode;
    v_retry_blocked_reason := CASE
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_SUBMISSION_REJECTED'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      ELSE 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    END;
    v_provider_recommended_action := CASE
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'The provider rejected the payment submission. Review the provider response before retrying.'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists. Do not retry unless reconciled.'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider submission returned an unusable response. Check the bank account before retrying.'
      WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission appears to have been blocked before the provider call, but evidence markers exist. Review before retrying.'
      ELSE 'Provider request may have been sent or a provider response may exist. Check the bank account before retrying.'
    END;

    v_provider_acceptance_evidence_count := CASE WHEN v_fast_provider_outcome_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN GREATEST(1, COALESCE(v_fast_provider_accepted_count, 0)) ELSE COALESCE(v_fast_provider_accepted_count, 0) END;
    v_provider_response_present_count := GREATEST(COALESCE(v_provider_response_present_count, 0), COALESCE(v_fast_provider_response_present_count, 0), COALESCE(v_fast_provider_exact_event_count, 0));
    v_provider_request_sent_count := GREATEST(COALESCE(v_provider_request_sent_count, 0), COALESCE(v_fast_provider_request_sent_count, 0));
    v_provider_submission_unknown_count := CASE WHEN v_fast_provider_outcome_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE') THEN GREATEST(1, COALESCE(v_fast_provider_unknown_count, 0)) ELSE COALESCE(v_fast_provider_unknown_count, 0) END;
    v_stale_unresolved_submit_chunk_count := GREATEST(COALESCE(v_stale_unresolved_submit_chunk_count, 0), COALESCE(v_unfinalised_submit_chunk_count, 0));
    v_provider_evidence_count := GREATEST(COALESCE(v_provider_evidence_count, 0), COALESCE(v_fast_provider_exact_event_count, 0), COALESCE(v_fast_provider_transfer_meta_marker_count, 0), COALESCE(v_fast_provider_chunk_marker_count, 0));
    v_provider_review_risk_count := COALESCE(v_provider_evidence_count, 0) + COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_submission_unknown_count, 0) + COALESCE(v_unfinalised_submit_chunk_count, 0);
    v_provider_manual_resolution_required := v_fast_provider_outcome_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');
    v_provider_safe_retry_available := false;
    v_retry_blocked := true;
    v_review_required := true;
    v_safe_to_retry := false;
    v_scope_rows_deleted := 0;
    v_transfer_rows_deleted := 0;
    v_item_links_cleared := 0;
    v_bank_references_cleared := 0;
    v_auth_requests_cancelled := 0;
    v_auth_tokens_voided := 0;
    v_batch_execution_intent_cleared := 0;

    v_fast_provider_review_reasons := jsonb_strip_nulls(jsonb_build_array(jsonb_build_object(
      'reason', v_retry_blocked_reason,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'failure_error_marker_count', COALESCE(v_fast_provider_failure_error_marker_count, 0),
      'provider_chunk_marker_count', COALESCE(v_fast_provider_chunk_marker_count, 0),
      'transfer_meta_marker_count', COALESCE(v_fast_provider_transfer_meta_marker_count, 0),
      'exact_transfer_event_count', COALESCE(v_fast_provider_exact_event_count, 0)
    )));
    v_unsafe_reasons := v_fast_provider_review_reasons;
    v_unsafe_transfer_count := COALESCE(v_transfer_rows_considered, 0);
    v_unsafe_scope_count := COALESCE(v_scope_rows_considered, 0);
    v_unsafe_transfer_ids := COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb);
    v_active_auth_request_count := COALESCE(v_fast_provider_auth_request_count, 0);
    v_operation_active_auth_request_count := COALESCE(v_fast_provider_auth_request_count, 0);
    v_active_auth_request_ids := COALESCE(v_fast_provider_auth_request_ids, '[]'::jsonb);
    v_initial_active_auth_request_count := COALESCE(v_fast_provider_auth_request_count, 0);
    v_active_auth_request_blocker_count := 0;
    v_non_cancellable_auth_request_count := 0;
    v_cancellable_auth_request_count := 0;
    v_provider_submit_chunk_attempt_count := COALESCE(v_fast_provider_submit_chunk_count, 0);
    v_provider_submit_unknown_chunk_count := COALESCE(v_provider_submission_unknown_count, 0);


    v_bounded_provider_finalise_chunk_id := NULL::uuid;
    v_bounded_provider_finalise_chunk_ids := '[]'::jsonb;
    v_bounded_provider_finalise_transfer_ids := '[]'::jsonb;
    v_bounded_provider_finalise_chunk_count := 0;
    v_bounded_provider_finalise_transfer_count := 0;
    v_bounded_provider_finalise_unfinalised_count := 0;
    v_bounded_provider_finalise_allowed := false;
    v_provider_submit_finalise_result := '{}'::jsonb;
    v_provider_submit_diagnostic_result := '{}'::jsonb;

    WITH failure_chunk_candidates AS (
      SELECT failure_chunk_value.chunk_id_text::uuid AS chunk_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'chunk_ids') = 'array' THEN v_failure_error_json->'chunk_ids' ELSE '[]'::jsonb END) AS failure_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_chunk_value.chunk_id_text::uuid AS chunk_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'chunkIds') = 'array' THEN v_failure_error_json->'chunkIds' ELSE '[]'::jsonb END) AS failure_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_chunk_value.chunk_id_text::uuid AS chunk_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic'->'chunk_ids') = 'array' THEN v_failure_error_json->'provider_submit_diagnostic'->'chunk_ids' ELSE '[]'::jsonb END) AS failure_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_chunk_value.chunk_id_text::uuid AS chunk_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'providerSubmitDiagnostic'->'chunkIds') = 'array' THEN v_failure_error_json->'providerSubmitDiagnostic'->'chunkIds' ELSE '[]'::jsonb END) AS failure_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_chunk_value.chunk_id_text::uuid AS chunk_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_claim_diagnostic'->'chunk_ids') = 'array' THEN v_failure_error_json->'provider_submit_claim_diagnostic'->'chunk_ids' ELSE '[]'::jsonb END) AS failure_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), bounded_chunk_candidates AS (
      SELECT DISTINCT operation_chunk.id AS chunk_id
      FROM failure_chunk_candidates AS failure_chunk_candidate
      JOIN public.banking_pay_operation_chunks AS operation_chunk
        ON operation_chunk.id = failure_chunk_candidate.chunk_id
       AND operation_chunk.operation_id = p_operation_id
       AND (
         operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
         OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
       )
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(bounded_chunk_candidates.chunk_id::text) ORDER BY bounded_chunk_candidates.chunk_id), '[]'::jsonb)
    INTO v_bounded_provider_finalise_chunk_count,
         v_bounded_provider_finalise_chunk_ids
    FROM bounded_chunk_candidates;

    IF COALESCE(v_bounded_provider_finalise_chunk_count, 0) = 1 THEN
      SELECT bounded_chunk_value.chunk_id_text::uuid
      INTO v_bounded_provider_finalise_chunk_id
      FROM jsonb_array_elements_text(v_bounded_provider_finalise_chunk_ids) AS bounded_chunk_value(chunk_id_text)
      WHERE NULLIF(BTRIM(COALESCE(bounded_chunk_value.chunk_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY bounded_chunk_value.chunk_id_text::uuid
      LIMIT 1;
    END IF;

    SELECT COUNT(*)::integer
    INTO v_bounded_provider_finalise_unfinalised_count
    FROM public.banking_pay_operation_chunks AS bounded_operation_chunk
    WHERE bounded_operation_chunk.id = v_bounded_provider_finalise_chunk_id
      AND bounded_operation_chunk.operation_id = p_operation_id
      AND (
        bounded_operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
        OR bounded_operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
      )
      AND upper(BTRIM(COALESCE(bounded_operation_chunk.status, ''))) = 'RUNNING'
      AND (bounded_operation_chunk.lock_expires_at_utc IS NULL OR bounded_operation_chunk.lock_expires_at_utc <= v_now);

    WITH selected_bounded_chunk AS (
      SELECT bounded_operation_chunk.id AS chunk_id,
             COALESCE(bounded_operation_chunk.payload_json, '{}'::jsonb) AS payload_json
      FROM public.banking_pay_operation_chunks AS bounded_operation_chunk
      WHERE bounded_operation_chunk.id = v_bounded_provider_finalise_chunk_id
        AND bounded_operation_chunk.operation_id = p_operation_id
        AND (
          bounded_operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
          OR bounded_operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
        )
    ), raw_transfer_candidates AS (
      SELECT failure_transfer_value.transfer_id_text::uuid AS transfer_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'transfer_ids') = 'array' THEN v_failure_error_json->'transfer_ids' ELSE '[]'::jsonb END) AS failure_transfer_value(transfer_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_transfer_value.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_transfer_value.transfer_id_text::uuid AS transfer_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'transferIds') = 'array' THEN v_failure_error_json->'transferIds' ELSE '[]'::jsonb END) AS failure_transfer_value(transfer_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_transfer_value.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_transfer_value.transfer_id_text::uuid AS transfer_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids') = 'array' THEN v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids' ELSE '[]'::jsonb END) AS failure_transfer_value(transfer_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_transfer_value.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT failure_transfer_value.transfer_id_text::uuid AS transfer_id
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'providerSubmitDiagnostic'->'transferIds') = 'array' THEN v_failure_error_json->'providerSubmitDiagnostic'->'transferIds' ELSE '[]'::jsonb END) AS failure_transfer_value(transfer_id_text)
      WHERE NULLIF(BTRIM(COALESCE(failure_transfer_value.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT chunk_transfer_value.transfer_id_text::uuid AS transfer_id
      FROM selected_bounded_chunk AS selected_chunk
      CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS chunk_transfer_value(transfer_id_text)
      WHERE NULLIF(BTRIM(COALESCE(chunk_transfer_value.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT chunk_transfer_object.transfer_id_text::uuid AS transfer_id
      FROM selected_bounded_chunk AS selected_chunk
      CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS chunk_transfer_payload(value)
      CROSS JOIN LATERAL (
        SELECT COALESCE(
          NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
          NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'transfer_id', '')), ''),
          NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'id', '')), '')
        ) AS transfer_id_text
      ) AS chunk_transfer_object
      WHERE NULLIF(BTRIM(COALESCE(chunk_transfer_object.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), bounded_transfer_candidates AS (
      SELECT DISTINCT raw_transfer_candidate.transfer_id
      FROM raw_transfer_candidates AS raw_transfer_candidate
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = raw_transfer_candidate.transfer_id
       AND transfer_row.pay_batch_id = v_operation_row.pay_batch_id
      WHERE EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
        WHERE operation_scope_check.operation_id = p_operation_id
          AND operation_scope_check.pay_batch_id = v_operation_row.pay_batch_id
          AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
      )
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(bounded_transfer_candidates.transfer_id::text) ORDER BY bounded_transfer_candidates.transfer_id), '[]'::jsonb)
    INTO v_bounded_provider_finalise_transfer_count,
         v_bounded_provider_finalise_transfer_ids
    FROM bounded_transfer_candidates;

    v_bounded_provider_finalise_allowed := (
      COALESCE(p_dry_run, false) IS NOT TRUE
      AND upper(BTRIM(COALESCE(v_failure_phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'COMPLETE')
      AND COALESCE(v_bounded_provider_finalise_chunk_count, 0) = 1
      AND COALESCE(v_bounded_provider_finalise_unfinalised_count, 0) = 1
      AND v_bounded_provider_finalise_chunk_id IS NOT NULL
      AND COALESCE(v_bounded_provider_finalise_transfer_count, 0) > 0
    );

    IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
      IF v_bounded_provider_finalise_allowed IS TRUE THEN
        BEGIN
          v_provider_submit_finalise_result := public.pay_provider_submit_chunk_diagnostic_finalise(
            p_operation_id := p_operation_id,
            p_pay_batch_id := v_operation_row.pay_batch_id,
            p_chunk_id := v_bounded_provider_finalise_chunk_id,
            p_actor_user_id := v_effective_actor_user_id,
            p_reason_code := 'FAILED_EXECUTION_CLEANUP_FAST_PROVIDER_REVIEW_FINALISE',
            p_failure_error_json := jsonb_strip_nulls(
              COALESCE(v_failure_error_json, '{}'::jsonb)
              || jsonb_build_object(
                'bounded_provider_finalise', true,
                'chunk_ids', COALESCE(v_bounded_provider_finalise_chunk_ids, '[]'::jsonb),
                'transfer_ids', COALESCE(v_bounded_provider_finalise_transfer_ids, '[]'::jsonb)
              )
            )
          );
        EXCEPTION
          WHEN undefined_function THEN
            v_provider_submit_finalise_result := '{}'::jsonb;
          WHEN OTHERS THEN
            v_provider_submit_finalise_result := jsonb_build_object(
              'ok', false,
              'error', SQLERRM,
              'reason', 'PROVIDER_SUBMIT_DIAGNOSTIC_FINALISE_FAILED'
            );
        END;
      ELSE
        v_provider_submit_finalise_result := jsonb_strip_nulls(jsonb_build_object(
          'ok', true,
          'skipped', true,
          'reason', 'BOUNDED_PROVIDER_FINALISE_NOT_RUN',
          'operation_id', p_operation_id::text,
          'pay_batch_id', v_operation_row.pay_batch_id::text,
          'failure_phase', v_failure_phase,
          'candidate_chunk_count', COALESCE(v_bounded_provider_finalise_chunk_count, 0),
          'candidate_unfinalised_chunk_count', COALESCE(v_bounded_provider_finalise_unfinalised_count, 0),
          'candidate_transfer_count', COALESCE(v_bounded_provider_finalise_transfer_count, 0),
          'requires_exactly_one_chunk', true,
          'requires_unfinalised_chunk', true
        ));
      END IF;
    END IF;

    BEGIN
      v_provider_submit_diagnostic_result := public.pay_provider_submit_diagnostic_get(
        p_pay_batch_id := v_operation_row.pay_batch_id,
        p_operation_id := p_operation_id,
        p_transfer_id := NULL::uuid,
        p_chunk_id := CASE WHEN v_bounded_provider_finalise_chunk_id IS NOT NULL THEN v_bounded_provider_finalise_chunk_id ELSE NULL::uuid END,
        p_counts_only := true
      );
    EXCEPTION
      WHEN undefined_function THEN
        v_provider_submit_diagnostic_result := '{}'::jsonb;
      WHEN OTHERS THEN
        v_provider_submit_diagnostic_result := jsonb_build_object(
          'ok', false,
          'error', SQLERRM,
          'reason', 'PROVIDER_SUBMIT_DIAGNOSTIC_GET_FAILED'
        );
    END;

    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
      v_provider_acceptance_evidence_count := GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}', '') ~ '^[0-9]+$' THEN
      v_provider_response_present_count := GREATEST(COALESCE(v_provider_response_present_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}', '') ~ '^[0-9]+$' THEN
      v_provider_request_sent_count := GREATEST(COALESCE(v_provider_request_sent_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '') ~ '^[0-9]+$' THEN
      v_provider_submission_unknown_count := GREATEST(COALESCE(v_provider_submission_unknown_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}', '') ~ '^[0-9]+$' THEN
      v_fast_provider_rejected_count := GREATEST(COALESCE(v_fast_provider_rejected_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}', '') ~ '^[0-9]+$' THEN
      v_fast_provider_malformed_count := GREATEST(COALESCE(v_fast_provider_malformed_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
      v_unfinalised_submit_chunk_count := GREATEST(COALESCE(v_unfinalised_submit_chunk_count, 0), (v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}')::integer);
    END IF;
    IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
      v_stale_unresolved_submit_chunk_count := GREATEST(
        COALESCE(v_stale_unresolved_submit_chunk_count, 0),
        COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}')::integer
      );
    END IF;

    v_provider_submit_diagnostic := jsonb_strip_nulls(jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'FAST_PROVIDER_OUTCOME_REVIEW',
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation_row.pay_batch_id::text,
      'failure_phase', v_failure_phase,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'recommended_action', v_provider_recommended_action,
      'manual_resolution_required', v_provider_manual_resolution_required,
      'safe_retry_available', false,
      'provider_request_sent', COALESCE(v_provider_request_sent_count, 0) > 0,
      'provider_response_present', COALESCE(v_provider_response_present_count, 0) > 0,
      'provider_response_received', COALESCE(v_provider_response_present_count, 0) > 0,
      'provider_acceptance_evidence_present', COALESCE(v_provider_acceptance_evidence_count, 0) > 0,
      'provider_submit_chunk_count', COALESCE(v_fast_provider_submit_chunk_count, 0),
      'provider_chunk_marker_count', COALESCE(v_fast_provider_chunk_marker_count, 0),
      'transfer_meta_marker_count', COALESCE(v_fast_provider_transfer_meta_marker_count, 0),
      'exact_transfer_event_count', COALESCE(v_fast_provider_exact_event_count, 0),
      'provider_rejection_count', COALESCE(v_fast_provider_rejected_count, 0),
      'provider_unknown_count', COALESCE(v_fast_provider_unknown_count, 0),
      'provider_malformed_count', COALESCE(v_fast_provider_malformed_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
      'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
      'transfer_ids', COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb),
      'chunk_ids', COALESCE(v_fast_provider_chunk_ids, '[]'::jsonb),
      'auth_request_ids', COALESCE(v_fast_provider_auth_request_ids, '[]'::jsonb),
      'failure_error_provider_submit_diagnostic', CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic') = 'object' THEN v_failure_error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      'generated_at_utc', v_now::text
    ));

    v_result := jsonb_strip_nulls(
      jsonb_build_object(
        'ok', true,
        'dry_run', COALESCE(p_dry_run, false),
        'dry_run_counts_are_prospective', COALESCE(p_dry_run, false),
        'fast_provider_outcome_review_path', true,
        'fast_pre_provider_cleanup_path', false,
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_operation_row.pay_batch_id::text,
        'failure_phase', v_failure_phase,
        'cleanup_mode', v_cleanup_mode,
        'operation_types_supported', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
        'operation_type_cleanup_mode', v_operation_type_cleanup_mode,
        'retry_blocked_reason', v_retry_blocked_reason,
        'safe_to_retry', v_safe_to_retry,
        'retry_blocked', v_retry_blocked,
        'review_required', v_review_required,
        'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
        'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
        'safe_scope_candidate_count', 0,
        'safe_transfer_candidate_count', 0,
        'safe_local_transfer_count', 0,
        'scope_rows_deleted', 0,
        'transfer_rows_deleted', 0,
        'item_links_cleared', 0,
        'bank_references_cleared', 0,
        'chunks_marked_failed', 0,
        'chunks_marked_skipped', 0,
        'locks_released', 0,
        'provider_evidence_count', COALESCE(v_provider_evidence_count, 0),
        'provider_review_risk_count', COALESCE(v_provider_review_risk_count, 0),
        'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
        'provider_submit_diagnostic_finalise_result', COALESCE(v_provider_submit_finalise_result, '{}'::jsonb),
        'provider_submission_status', v_provider_submission_status,
        'review_reason_code', v_provider_submit_review_reason_code,
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
        'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
        'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
        'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
        'recommended_action', v_provider_recommended_action,
        'safe_retry_available', false,
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'unsafe_scope_count', COALESCE(v_unsafe_scope_count, 0),
        'unsafe_transfer_ids', COALESCE(v_unsafe_transfer_ids, '[]'::jsonb),
        'unsafe_reasons', COALESCE(v_unsafe_reasons, '[]'::jsonb)
      )
      ||
      jsonb_build_object(
        'safe_scope_ids', '[]'::jsonb,
        'safe_transfer_ids', '[]'::jsonb,
        'initial_active_auth_request_count', COALESCE(v_initial_active_auth_request_count, 0),
        'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
        'operation_active_auth_request_count', COALESCE(v_operation_active_auth_request_count, 0),
        'active_auth_request_ids', COALESCE(v_active_auth_request_ids, '[]'::jsonb),
        'auth_requests_cancelled', 0,
        'awaiting_auth_requests_cancelled', 0,
        'authorised_auth_requests_cancelled', 0,
        'auth_request_cleanup_mode', 'NO_AUTH_REQUEST_CLEANUP_PROVIDER_OUTCOME_REVIEW',
        'auth_tokens_voided', 0,
        'batch_execution_intent_cleared', 0,
        'active_auth_request_blocker_count', COALESCE(v_active_auth_request_blocker_count, 0),
        'authorised_auth_request_review_count', 0,
        'cancellable_auth_request_count', 0,
        'non_cancellable_auth_request_count', 0,
        'cancelled_auth_request_ids', '[]'::jsonb,
        'provider_submit_chunk_attempt_count', COALESCE(v_provider_submit_chunk_attempt_count, 0),
        'stale_empty_provider_submit_chunk_count', COALESCE(v_stale_empty_provider_submit_chunk_count, 0),
        'provider_submit_unknown_chunk_count', COALESCE(v_provider_submit_unknown_chunk_count, 0),
        'batch_execution_boundary_crossed', v_batch_execution_boundary_crossed,
        'execution_commit_state', upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))),
        'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
        'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL,
        'remaining_operation_scope_count', COALESCE(v_scope_rows_considered, 0),
        'remaining_operation_transfer_count', COALESCE(v_transfer_rows_considered, 0),
        'provider_chunk_ids', COALESCE(v_fast_provider_chunk_ids, '[]'::jsonb),
        'provider_transfer_ids', COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb)
      )
    );

    IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
      BEGIN
        PERFORM public._audit_insert(
          'banking_pay_operations',
          p_operation_id::text,
          'PAYMENT_EXECUTE_FAST_PROVIDER_OUTCOME_REVIEW',
          NULL::jsonb,
          v_result,
          'payment_execute_fast_provider_outcome_review',
          v_effective_actor_user_id
        );
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    RETURN v_result;
  END IF;

  WITH bounded_chunk_candidates AS (
    SELECT DISTINCT chunk_candidate.chunk_id
    FROM (
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'chunk_ids') = 'array' THEN v_failure_error_json->'chunk_ids' ELSE '[]'::jsonb END) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'chunkIds') = 'array' THEN v_failure_error_json->'chunkIds' ELSE '[]'::jsonb END) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic'->'chunk_ids') = 'array' THEN v_failure_error_json->'provider_submit_diagnostic'->'chunk_ids' ELSE '[]'::jsonb END) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'providerSubmitDiagnostic'->'chunkIds') = 'array' THEN v_failure_error_json->'providerSubmitDiagnostic'->'chunkIds' ELSE '[]'::jsonb END) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      UNION ALL
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_claim_diagnostic'->'chunk_ids') = 'array' THEN v_failure_error_json->'provider_submit_claim_diagnostic'->'chunk_ids' ELSE '[]'::jsonb END) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) AS chunk_candidate
    JOIN public.banking_pay_operation_chunks AS operation_chunk
      ON operation_chunk.id = chunk_candidate.chunk_id
     AND operation_chunk.operation_id = p_operation_id
     AND (
       operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
       OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
     )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(bounded_chunk_candidates.chunk_id::text) ORDER BY bounded_chunk_candidates.chunk_id), '[]'::jsonb)
  INTO v_bounded_provider_finalise_chunk_count,
       v_bounded_provider_finalise_chunk_ids
  FROM bounded_chunk_candidates;

  IF COALESCE(v_bounded_provider_finalise_chunk_count, 0) = 1 THEN
    SELECT bounded_chunk_value.chunk_id
    INTO v_bounded_provider_finalise_chunk_id
    FROM (
      SELECT (chunk_value.value #>> '{}')::uuid AS chunk_id
      FROM jsonb_array_elements(v_bounded_provider_finalise_chunk_ids) AS chunk_value(value)
      WHERE (chunk_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ORDER BY (chunk_value.value #>> '{}')::uuid
      LIMIT 1
    ) AS bounded_chunk_value;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_bounded_provider_finalise_unfinalised_count
  FROM public.banking_pay_operation_chunks AS bounded_operation_chunk
  WHERE bounded_operation_chunk.id = v_bounded_provider_finalise_chunk_id
    AND bounded_operation_chunk.operation_id = p_operation_id
    AND (
      bounded_operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
      OR bounded_operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
    )
    AND upper(BTRIM(COALESCE(bounded_operation_chunk.status, ''))) = 'RUNNING'
    AND (bounded_operation_chunk.lock_expires_at_utc IS NULL OR bounded_operation_chunk.lock_expires_at_utc <= v_now);

  WITH selected_bounded_chunk AS (
    SELECT bounded_operation_chunk.id AS chunk_id,
           COALESCE(bounded_operation_chunk.payload_json, '{}'::jsonb) AS payload_json
    FROM public.banking_pay_operation_chunks AS bounded_operation_chunk
    WHERE bounded_operation_chunk.id = v_bounded_provider_finalise_chunk_id
      AND bounded_operation_chunk.operation_id = p_operation_id
      AND (
        bounded_operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
        OR bounded_operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
      )
  ), raw_transfer_candidates AS (
    SELECT (transfer_value.value #>> '{}')::uuid AS transfer_id
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'transfer_ids') = 'array' THEN v_failure_error_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_value(value)
    WHERE (transfer_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION ALL
    SELECT (transfer_value.value #>> '{}')::uuid AS transfer_id
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'transferIds') = 'array' THEN v_failure_error_json->'transferIds' ELSE '[]'::jsonb END) AS transfer_value(value)
    WHERE (transfer_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION ALL
    SELECT (transfer_value.value #>> '{}')::uuid AS transfer_id
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids') = 'array' THEN v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_value(value)
    WHERE (transfer_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION ALL
    SELECT (transfer_value.value #>> '{}')::uuid AS transfer_id
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_failure_error_json->'providerSubmitDiagnostic'->'transferIds') = 'array' THEN v_failure_error_json->'providerSubmitDiagnostic'->'transferIds' ELSE '[]'::jsonb END) AS transfer_value(value)
    WHERE (transfer_value.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION ALL
    SELECT chunk_transfer_value.value::uuid AS transfer_id
    FROM selected_bounded_chunk AS selected_chunk
    CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS chunk_transfer_value(value)
    WHERE chunk_transfer_value.value ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    UNION ALL
    SELECT chunk_transfer_text.transfer_id_text::uuid AS transfer_id
    FROM selected_bounded_chunk AS selected_chunk
    CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS chunk_transfer_payload(value)
    CROSS JOIN LATERAL (
      SELECT COALESCE(
        NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
        NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'transfer_id', '')), ''),
        NULLIF(BTRIM(COALESCE(chunk_transfer_payload.value->>'id', '')), '')
      ) AS transfer_id_text
    ) AS chunk_transfer_text
    WHERE NULLIF(BTRIM(COALESCE(chunk_transfer_text.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ), bounded_transfer_candidates AS (
    SELECT DISTINCT raw_transfer_candidate.transfer_id
    FROM raw_transfer_candidates AS raw_transfer_candidate
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = raw_transfer_candidate.transfer_id
     AND transfer_row.pay_batch_id = v_operation_row.pay_batch_id
    WHERE EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
      WHERE operation_scope_check.operation_id = p_operation_id
        AND operation_scope_check.pay_batch_id = v_operation_row.pay_batch_id
        AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
    )
  )
  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(bounded_transfer_candidates.transfer_id::text) ORDER BY bounded_transfer_candidates.transfer_id), '[]'::jsonb)
  INTO v_bounded_provider_finalise_transfer_count,
       v_bounded_provider_finalise_transfer_ids
  FROM bounded_transfer_candidates;

  v_bounded_provider_finalise_allowed := (
    COALESCE(p_dry_run, false) IS NOT TRUE
    AND upper(BTRIM(COALESCE(v_failure_phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'COMPLETE')
    AND COALESCE(v_bounded_provider_finalise_chunk_count, 0) = 1
    AND COALESCE(v_bounded_provider_finalise_unfinalised_count, 0) = 1
    AND v_bounded_provider_finalise_chunk_id IS NOT NULL
    AND COALESCE(v_bounded_provider_finalise_transfer_count, 0) > 0
  );

  IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
    IF v_bounded_provider_finalise_allowed IS TRUE THEN
      BEGIN
        v_provider_submit_finalise_result := public.pay_provider_submit_chunk_diagnostic_finalise(
          p_operation_id := p_operation_id,
          p_pay_batch_id := v_operation_row.pay_batch_id,
          p_chunk_id := v_bounded_provider_finalise_chunk_id,
          p_actor_user_id := v_effective_actor_user_id,
          p_reason_code := 'FAILED_EXECUTION_CLEANUP_PROVIDER_SUBMIT_DIAGNOSTIC',
          p_failure_error_json := jsonb_strip_nulls(
            COALESCE(v_failure_error_json, '{}'::jsonb)
            || jsonb_build_object(
              'bounded_provider_finalise', true,
              'chunk_ids', COALESCE(v_bounded_provider_finalise_chunk_ids, '[]'::jsonb),
              'transfer_ids', COALESCE(v_bounded_provider_finalise_transfer_ids, '[]'::jsonb)
            )
          )
        );
      EXCEPTION
        WHEN undefined_function THEN
          v_provider_submit_finalise_result := '{}'::jsonb;
        WHEN OTHERS THEN
          v_provider_submit_finalise_result := jsonb_build_object(
            'ok', false,
            'error', SQLERRM,
            'reason', 'PROVIDER_SUBMIT_DIAGNOSTIC_FINALISE_FAILED'
          );
      END;
    ELSE
      v_provider_submit_finalise_result := jsonb_strip_nulls(jsonb_build_object(
        'ok', true,
        'skipped', true,
        'reason', 'BOUNDED_PROVIDER_FINALISE_NOT_RUN',
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_operation_row.pay_batch_id::text,
        'failure_phase', v_failure_phase,
        'candidate_chunk_count', COALESCE(v_bounded_provider_finalise_chunk_count, 0),
        'candidate_unfinalised_chunk_count', COALESCE(v_bounded_provider_finalise_unfinalised_count, 0),
        'candidate_transfer_count', COALESCE(v_bounded_provider_finalise_transfer_count, 0),
        'requires_exactly_one_chunk', true,
        'requires_unfinalised_chunk', true
      ));
    END IF;
  END IF;

  BEGIN
    v_provider_submit_diagnostic_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := v_operation_row.pay_batch_id,
      p_operation_id := p_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := CASE WHEN v_bounded_provider_finalise_chunk_id IS NOT NULL THEN v_bounded_provider_finalise_chunk_id ELSE NULL::uuid END,
      p_counts_only := true
    );
  EXCEPTION
    WHEN undefined_function THEN
      v_provider_submit_diagnostic_result := '{}'::jsonb;
    WHEN OTHERS THEN
      v_provider_submit_diagnostic_result := jsonb_build_object(
        'ok', false,
        'error', SQLERRM,
        'reason', 'PROVIDER_SUBMIT_DIAGNOSTIC_GET_FAILED'
      );
  END;

  v_provider_submit_diagnostic := COALESCE(v_provider_submit_diagnostic_result->'provider_submit_diagnostic', '{}'::jsonb);
  v_provider_submission_status := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'provider_submission_status', v_provider_submit_diagnostic_result->>'provider_submission_status', '')), '');
  v_provider_submit_review_reason_code := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'review_reason_code', v_provider_submit_diagnostic_result->>'review_reason_code', '')), '');
  v_provider_recommended_action := NULLIF(BTRIM(COALESCE(v_provider_submit_diagnostic->>'recommended_action', v_provider_submit_diagnostic_result->>'recommended_action', '')), '');
  v_provider_manual_resolution_required := lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'manual_resolution_required', v_provider_submit_diagnostic_result->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_safe_retry_available := lower(BTRIM(COALESCE(v_provider_submit_diagnostic->>'safe_retry_available', v_provider_submit_diagnostic_result->>'safe_retry_available', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
    v_provider_acceptance_evidence_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}', '') ~ '^[0-9]+$' THEN
    v_provider_response_present_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_response_present_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}', '') ~ '^[0-9]+$' THEN
    v_provider_request_sent_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_request_sent_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_unknown_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_unknown_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
    v_stale_unresolved_submit_chunk_count := COALESCE(v_provider_submit_diagnostic_result #>> '{counts,stale_unresolved_submit_chunk_count}', v_provider_submit_diagnostic_result #>> '{counts,stale_empty_submit_chunk_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}', '') ~ '^[0-9]+$' THEN
    v_unfinalised_submit_chunk_count := (v_provider_submit_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}')::integer;
  END IF;

  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_rejected_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_rejected_count}')::integer;
  END IF;
  IF COALESCE(v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}', '') ~ '^[0-9]+$' THEN
    v_provider_submission_malformed_response_count := (v_provider_submit_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}')::integer;
  END IF;

  v_provider_submit_requires_manual_review := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_submission_rejected_count, 0) > 0
    OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
    OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_status, '') IN (
      'PROVIDER_SUBMISSION_ACCEPTED',
      'PROVIDER_SUBMISSION_REJECTED',
      'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
      'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
      'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
      'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
    );

  v_provider_submit_allows_local_cleanup := COALESCE(v_provider_acceptance_evidence_count, 0) = 0
    AND COALESCE(v_provider_request_sent_count, 0) = 0
    AND COALESCE(v_provider_response_present_count, 0) = 0
    AND COALESCE(v_provider_submission_unknown_count, 0) = 0
    AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0
    AND COALESCE(v_unfinalised_submit_chunk_count, 0) = 0
    AND COALESCE(v_provider_submission_status, 'NO_PROVIDER_SUBMISSION_ATTEMPTED') IN ('', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'MANUAL_RESOLVED_NO_PAYMENT_MADE');

  IF upper(BTRIM(COALESCE(v_failure_phase, ''))) IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES')
     AND COALESCE(v_provider_submit_requires_manual_review, false) IS TRUE
     AND COALESCE(v_provider_submit_allows_local_cleanup, false) IS NOT TRUE THEN
    IF NULLIF(BTRIM(COALESCE(v_provider_submission_status, '')), '') IS NULL
       OR upper(BTRIM(COALESCE(v_provider_submission_status, ''))) = 'NO_PROVIDER_SUBMISSION_ATTEMPTED' THEN
      v_provider_submission_status := CASE
        WHEN COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_ACCEPTED'
        WHEN COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_REJECTED'
        WHEN COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
        WHEN COALESCE(v_provider_submission_unknown_count, 0) > 0
          OR COALESCE(v_provider_request_sent_count, 0) > 0
          OR COALESCE(v_provider_response_present_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
        WHEN COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
          OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
        ELSE 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
      END;
    END IF;

    IF NULLIF(BTRIM(COALESCE(v_provider_submit_review_reason_code, '')), '') IS NULL
       OR upper(BTRIM(COALESCE(v_provider_submit_review_reason_code, ''))) = 'NO_PROVIDER_SUBMIT_ATTEMPT' THEN
      v_provider_submit_review_reason_code := CASE
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_REJECTED_PAYMENT'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_RESPONSE_MALFORMED'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK'
        ELSE 'PROVIDER_REQUEST_SENT_NO_RESPONSE'
      END;
    END IF;

    v_cleanup_mode := CASE
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'REVIEW_REQUIRED_PROVIDER_ACCEPTANCE_EVIDENCE'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'REVIEW_REQUIRED_PROVIDER_REJECTED'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'REVIEW_REQUIRED_PROVIDER_MALFORMED_RESPONSE'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'REVIEW_REQUIRED_STALE_PROVIDER_SUBMIT_CHUNK'
      ELSE 'REVIEW_REQUIRED_UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    END;

    v_retry_blocked_reason := CASE
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_SUBMISSION_REJECTED'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
      WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
      ELSE 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    END;

    v_provider_recommended_action := COALESCE(
      NULLIF(BTRIM(COALESCE(v_provider_recommended_action, '')), ''),
      CASE
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'The provider rejected the payment submission. Review the provider response before retrying.'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists. Do not retry unless reconciled.'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider submission returned an unusable response. Check the bank account before retrying.'
        ELSE 'Provider request may have been sent or a provider response may exist. Check the bank account before retrying.'
      END
    );

    v_provider_manual_resolution_required := COALESCE(v_provider_manual_resolution_required, false)
      OR v_provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');
    v_provider_safe_retry_available := false;
    v_retry_blocked := true;
    v_review_required := true;
    v_safe_to_retry := false;
    v_scope_rows_deleted := 0;
    v_transfer_rows_deleted := 0;
    v_item_links_cleared := 0;
    v_bank_references_cleared := 0;
    v_auth_requests_cancelled := 0;
    v_auth_tokens_voided := 0;
    v_batch_execution_intent_cleared := 0;
    v_safe_scope_candidate_count := 0;
    v_safe_transfer_candidate_count := 0;
    v_safe_scope_ids := '[]'::jsonb;
    v_safe_transfer_ids := '[]'::jsonb;
    v_deleted_scope_ids := '[]'::jsonb;
    v_deleted_transfer_ids := '[]'::jsonb;
    v_provider_evidence_count := GREATEST(
      COALESCE(v_provider_evidence_count, 0),
      COALESCE(v_provider_acceptance_evidence_count, 0),
      COALESCE(v_provider_response_present_count, 0)
    );
    v_provider_review_risk_count := GREATEST(
      COALESCE(v_provider_review_risk_count, 0),
      COALESCE(v_provider_acceptance_evidence_count, 0)
      + COALESCE(v_provider_response_present_count, 0)
      + COALESCE(v_provider_request_sent_count, 0)
      + COALESCE(v_provider_submission_rejected_count, 0)
      + COALESCE(v_provider_submission_unknown_count, 0)
      + COALESCE(v_provider_submission_malformed_response_count, 0)
      + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
      + COALESCE(v_unfinalised_submit_chunk_count, 0)
    );

    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb)
    INTO v_active_auth_request_count,
         v_active_auth_request_ids
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND NULLIF(BTRIM(COALESCE(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text;

    v_initial_active_auth_request_count := COALESCE(v_active_auth_request_count, 0);
    v_operation_active_auth_request_count := COALESCE(v_active_auth_request_count, 0);
    v_active_auth_request_blocker_count := 0;
    v_cancellable_auth_request_count := 0;
    v_non_cancellable_auth_request_count := 0;
    v_unsafe_transfer_count := COALESCE(v_transfer_rows_considered, 0);
    v_unsafe_scope_count := COALESCE(v_scope_rows_considered, 0);
    v_unsafe_transfer_ids := COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb);
    v_unsafe_reasons := jsonb_strip_nulls(jsonb_build_array(jsonb_build_object(
      'reason', v_retry_blocked_reason,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0)
    )));

    v_provider_submit_diagnostic := jsonb_strip_nulls(
      COALESCE(v_provider_submit_diagnostic, '{}'::jsonb)
      || jsonb_build_object(
        'diagnostic_version', 1,
        'diagnostic_source', 'FAST_PROVIDER_OUTCOME_REVIEW',
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_operation_row.pay_batch_id::text,
        'failure_phase', v_failure_phase,
        'provider_submission_status', v_provider_submission_status,
        'review_reason_code', v_provider_submit_review_reason_code,
        'recommended_action', v_provider_recommended_action,
        'manual_resolution_required', v_provider_manual_resolution_required,
        'safe_retry_available', false,
        'provider_request_sent', COALESCE(v_provider_request_sent_count, 0) > 0,
        'provider_response_present', COALESCE(v_provider_response_present_count, 0) > 0,
        'provider_response_received', COALESCE(v_provider_response_present_count, 0) > 0,
        'provider_acceptance_evidence_present', COALESCE(v_provider_acceptance_evidence_count, 0) > 0,
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
        'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
        'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
        'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
        'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
        'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
        'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
        'transfer_ids', COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb),
        'chunk_ids', COALESCE(v_bounded_provider_finalise_chunk_ids, '[]'::jsonb),
        'auth_request_ids', COALESCE(v_active_auth_request_ids, '[]'::jsonb),
        'provider_submit_diagnostic_finalise_result', COALESCE(v_provider_submit_finalise_result, '{}'::jsonb),
        'generated_at_utc', v_now::text
      )
    );

    v_result := jsonb_strip_nulls(
      jsonb_build_object(
        'ok', true,
        'dry_run', COALESCE(p_dry_run, false),
        'dry_run_counts_are_prospective', COALESCE(p_dry_run, false),
        'fast_provider_outcome_review_path', true,
        'fast_pre_provider_cleanup_path', false,
        'operation_id', p_operation_id::text,
        'pay_batch_id', v_operation_row.pay_batch_id::text,
        'failure_phase', v_failure_phase,
        'cleanup_mode', v_cleanup_mode,
        'operation_types_supported', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
        'operation_type_cleanup_mode', v_operation_type_cleanup_mode,
        'retry_blocked_reason', v_retry_blocked_reason,
        'safe_to_retry', false,
        'retry_blocked', true,
        'review_required', true,
        'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
        'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
        'safe_scope_candidate_count', 0,
        'safe_transfer_candidate_count', 0,
        'safe_local_transfer_count', 0,
        'scope_rows_deleted', 0,
        'transfer_rows_deleted', 0,
        'item_links_cleared', 0,
        'bank_references_cleared', 0,
        'chunks_marked_failed', 0,
        'chunks_marked_skipped', 0,
        'locks_released', 0,
        'provider_evidence_count', COALESCE(v_provider_evidence_count, 0),
        'provider_review_risk_count', COALESCE(v_provider_review_risk_count, 0),
        'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
        'provider_submit_diagnostic_finalise_result', COALESCE(v_provider_submit_finalise_result, '{}'::jsonb),
        'provider_submission_status', v_provider_submission_status,
        'review_reason_code', v_provider_submit_review_reason_code,
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
        'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
        'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
        'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
        'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
        'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
        'recommended_action', v_provider_recommended_action,
        'safe_retry_available', false,
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'unsafe_scope_count', COALESCE(v_unsafe_scope_count, 0),
        'unsafe_transfer_ids', COALESCE(v_unsafe_transfer_ids, '[]'::jsonb),
        'unsafe_reasons', COALESCE(v_unsafe_reasons, '[]'::jsonb)
      )
      ||
      jsonb_build_object(
        'safe_scope_ids', '[]'::jsonb,
        'safe_transfer_ids', '[]'::jsonb,
        'initial_active_auth_request_count', COALESCE(v_initial_active_auth_request_count, 0),
        'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
        'operation_active_auth_request_count', COALESCE(v_operation_active_auth_request_count, 0),
        'active_auth_request_ids', COALESCE(v_active_auth_request_ids, '[]'::jsonb),
        'auth_requests_cancelled', 0,
        'awaiting_auth_requests_cancelled', 0,
        'authorised_auth_requests_cancelled', 0,
        'auth_request_cleanup_mode', 'NO_AUTH_REQUEST_CLEANUP_PROVIDER_OUTCOME_REVIEW',
        'auth_tokens_voided', 0,
        'batch_execution_intent_cleared', 0,
        'active_auth_request_blocker_count', COALESCE(v_active_auth_request_blocker_count, 0),
        'authorised_auth_request_review_count', 0,
        'cancellable_auth_request_count', 0,
        'non_cancellable_auth_request_count', 0,
        'cancelled_auth_request_ids', '[]'::jsonb,
        'provider_submit_chunk_attempt_count', COALESCE(v_provider_submit_chunk_attempt_count, 0),
        'stale_empty_provider_submit_chunk_count', COALESCE(v_stale_empty_provider_submit_chunk_count, 0),
        'provider_submit_unknown_chunk_count', COALESCE(v_provider_submit_unknown_chunk_count, 0),
        'batch_execution_boundary_crossed', v_batch_execution_boundary_crossed,
        'execution_commit_state', upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))),
        'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
        'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL,
        'remaining_operation_scope_count', COALESCE(v_scope_rows_considered, 0),
        'remaining_operation_transfer_count', COALESCE(v_transfer_rows_considered, 0),
        'provider_chunk_ids', COALESCE(v_bounded_provider_finalise_chunk_ids, '[]'::jsonb),
        'provider_transfer_ids', COALESCE(v_fast_provider_transfer_ids, '[]'::jsonb)
      )
    );

    IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
      BEGIN
        PERFORM public._audit_insert(
          'banking_pay_operations',
          p_operation_id::text,
          'PAYMENT_EXECUTE_FAST_PROVIDER_OUTCOME_REVIEW',
          NULL::jsonb,
          v_result,
          'payment_execute_fast_provider_outcome_review',
          v_effective_actor_user_id
        );
      EXCEPTION
        WHEN OTHERS THEN
          NULL;
      END;
    END IF;

    RETURN v_result;
  END IF;

  SELECT COUNT(*)::integer,
         (COUNT(*) FILTER (WHERE auth_request.execution_intent_json->>'operation_id' = p_operation_id::text))::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb)
  INTO v_active_auth_request_count,
       v_operation_active_auth_request_count,
       v_active_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
    AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

  v_initial_active_auth_request_count := COALESCE(v_active_auth_request_count, 0);

  SELECT COUNT(*) FILTER (
           WHERE lower(BTRIM(COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(BTRIM(COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(BTRIM(COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR lower(BTRIM(COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_status', '') IN (
                'PROVIDER_SUBMISSION_ACCEPTED',
                'PROVIDER_SUBMISSION_REJECTED',
                'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
                'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
              )
         )::integer,
         COUNT(*) FILTER (
           WHERE upper(BTRIM(COALESCE(provider_submit_chunk.status, ''))) = 'RUNNING'
             AND (provider_submit_chunk.lock_expires_at_utc IS NULL OR provider_submit_chunk.lock_expires_at_utc <= v_now)
             AND COALESCE(provider_submit_chunk.result_json, '{}'::jsonb) = '{}'::jsonb
             AND COALESCE(provider_submit_chunk.error_json, '{}'::jsonb) = '{}'::jsonb
         )::integer,
         COUNT(*) FILTER (
           WHERE COALESCE(provider_submit_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_status', '') IN (
             'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
             'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
             'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
           )
           OR (
             upper(BTRIM(COALESCE(provider_submit_chunk.status, ''))) = 'RUNNING'
             AND (provider_submit_chunk.lock_expires_at_utc IS NULL OR provider_submit_chunk.lock_expires_at_utc <= v_now)
             AND COALESCE(provider_submit_chunk.result_json, '{}'::jsonb) = '{}'::jsonb
             AND COALESCE(provider_submit_chunk.error_json, '{}'::jsonb) = '{}'::jsonb
           )
         )::integer
  INTO v_provider_submit_chunk_attempt_count,
       v_stale_empty_provider_submit_chunk_count,
       v_provider_submit_unknown_chunk_count
  FROM public.banking_pay_operation_chunks AS provider_submit_chunk
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      CASE WHEN jsonb_typeof(provider_submit_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN provider_submit_chunk.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(provider_submit_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN provider_submit_chunk.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      '{}'::jsonb
    ) AS provider_submit_diagnostic
  ) AS provider_submit_chunk_diagnostic
  WHERE provider_submit_chunk.operation_id = p_operation_id
    AND (
      provider_submit_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
      OR provider_submit_chunk.chunk_type = 'TRANSFER_SUBMIT'
    )
    AND (
      provider_submit_chunk.status IN ('RUNNING', 'COMPLETE', 'FAILED')
      OR provider_submit_chunk.started_at_utc IS NOT NULL
      OR (provider_submit_chunk.result_json IS NOT NULL AND provider_submit_chunk.result_json <> '{}'::jsonb)
      OR (provider_submit_chunk.error_json IS NOT NULL AND provider_submit_chunk.error_json <> '{}'::jsonb)
    );

  v_provider_submit_chunk_attempt_count := COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0);
  v_stale_empty_provider_submit_chunk_count := COALESCE(v_stale_unresolved_submit_chunk_count, 0);
  v_provider_submit_unknown_chunk_count := COALESCE(v_provider_submission_unknown_count, 0);

  v_deletion_allowed := false;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_scope_classified;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_scope_classified (
    scope_id uuid PRIMARY KEY,
    pay_bank_transfer_id uuid,
    pay_channel text NOT NULL,
    transfer_group_key text NOT NULL,
    scope_status text,
    scope_request_id text,
    scope_payment_reference text,
    classifier_found boolean NOT NULL DEFAULT false,
    classifier_is_safe_local_cleanup boolean NOT NULL DEFAULT false,
    has_provider_submission_evidence boolean NOT NULL DEFAULT false,
    has_provider_event_evidence boolean NOT NULL DEFAULT false,
    has_provider_attempt_without_external_id boolean NOT NULL DEFAULT false,
    has_operation_submit_attempt boolean NOT NULL DEFAULT false,
    has_ambiguous_external_evidence boolean NOT NULL DEFAULT false,
    is_failed_or_blocked boolean NOT NULL DEFAULT false,
    is_terminal_or_completed boolean NOT NULL DEFAULT false,
    evidence_classification text,
    unsafe_reason text
  ) ON COMMIT DROP;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_transfer_classified;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_transfer_classified (
    pay_bank_transfer_id uuid PRIMARY KEY,
    pay_channel text NOT NULL,
    transfer_group_key text,
    payment_reference text,
    request_id text,
    classifier_found boolean NOT NULL DEFAULT false,
    is_safe_local_cleanup boolean NOT NULL DEFAULT false,
    has_provider_submission_evidence boolean NOT NULL DEFAULT false,
    has_provider_event_evidence boolean NOT NULL DEFAULT false,
    has_provider_attempt_without_external_id boolean NOT NULL DEFAULT false,
    has_operation_submit_attempt boolean NOT NULL DEFAULT false,
    has_ambiguous_external_evidence boolean NOT NULL DEFAULT false,
    is_failed_or_blocked boolean NOT NULL DEFAULT false,
    is_terminal_or_completed boolean NOT NULL DEFAULT false,
    evidence_classification text,
    unsafe_reason text
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_scope_classified (
    scope_id,
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    scope_status,
    scope_request_id,
    scope_payment_reference,
    classifier_found,
    classifier_is_safe_local_cleanup,
    has_provider_submission_evidence,
    has_provider_event_evidence,
    has_provider_attempt_without_external_id,
    has_operation_submit_attempt,
    has_ambiguous_external_evidence,
    is_failed_or_blocked,
    is_terminal_or_completed,
    evidence_classification,
    unsafe_reason
  )
  SELECT scope_row.id,
         scope_row.pay_bank_transfer_id,
         scope_row.pay_channel,
         scope_row.transfer_group_key,
         scope_row.status,
         scope_row.request_id,
         scope_row.payment_reference,
         (classifier_row.pay_bank_transfer_id IS NOT NULL OR classifier_row.scope_id IS NOT NULL),
         COALESCE(classifier_row.is_safe_local_cleanup, false),
         COALESCE(classifier_row.has_provider_submission_evidence, false),
         COALESCE(classifier_row.has_provider_event_evidence, false),
         COALESCE(classifier_row.has_provider_attempt_without_external_id, false),
         COALESCE(classifier_row.has_operation_submit_attempt, false),
         COALESCE(classifier_row.has_ambiguous_external_evidence, false),
         COALESCE(classifier_row.is_failed_or_blocked, false),
         COALESCE(classifier_row.is_terminal_or_completed, false),
         classifier_row.evidence_classification,
         CASE
           WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED'
           WHEN scope_row.pay_bank_transfer_id IS NULL THEN NULL::text
           ELSE classifier_row.unsafe_reason
         END
  FROM public.banking_pay_operation_transfer_scope AS scope_row
  LEFT JOIN LATERAL (
    SELECT classifier_inner.*
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id => v_operation_row.pay_batch_id,
      p_pay_channel_scope => scope_row.pay_channel,
      p_operation_id => p_operation_id,
      p_include_unscoped_transfers => true
    ) AS classifier_inner
    WHERE classifier_inner.scope_id = scope_row.id
       OR (
         scope_row.pay_bank_transfer_id IS NOT NULL
         AND classifier_inner.pay_bank_transfer_id = scope_row.pay_bank_transfer_id
       )
    ORDER BY
      CASE WHEN classifier_inner.scope_id = scope_row.id THEN 0 ELSE 1 END,
      CASE WHEN classifier_inner.pay_bank_transfer_id = scope_row.pay_bank_transfer_id THEN 0 ELSE 1 END,
      classifier_inner.pay_bank_transfer_id NULLS LAST,
      classifier_inner.scope_id NULLS LAST
    LIMIT 1
  ) AS classifier_row ON true
  WHERE scope_row.operation_id = p_operation_id
    AND scope_row.pay_batch_id = v_operation_row.pay_batch_id;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_transfer_classified (
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    payment_reference,
    request_id,
    classifier_found,
    is_safe_local_cleanup,
    has_provider_submission_evidence,
    has_provider_event_evidence,
    has_provider_attempt_without_external_id,
    has_operation_submit_attempt,
    has_ambiguous_external_evidence,
    is_failed_or_blocked,
    is_terminal_or_completed,
    evidence_classification,
    unsafe_reason
  )
  SELECT transfer_candidate.pay_bank_transfer_id,
         transfer_candidate.pay_channel,
         transfer_candidate.transfer_group_key,
         transfer_candidate.payment_reference,
         transfer_candidate.request_id,
         (classifier_row.pay_bank_transfer_id IS NOT NULL),
         COALESCE(classifier_row.is_safe_local_cleanup, false),
         COALESCE(classifier_row.has_provider_submission_evidence, false),
         COALESCE(classifier_row.has_provider_event_evidence, false),
         COALESCE(classifier_row.has_provider_attempt_without_external_id, false),
         COALESCE(classifier_row.has_operation_submit_attempt, false),
         COALESCE(classifier_row.has_ambiguous_external_evidence, false),
         COALESCE(classifier_row.is_failed_or_blocked, false),
         COALESCE(classifier_row.is_terminal_or_completed, false),
         classifier_row.evidence_classification,
         CASE
           WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED'
           WHEN classifier_row.pay_bank_transfer_id IS NULL THEN 'TRANSFER_CLASSIFICATION_MISSING'
           ELSE classifier_row.unsafe_reason
         END
  FROM (
    SELECT DISTINCT transfer_row.id AS pay_bank_transfer_id,
           transfer_row.pay_channel AS pay_channel,
           transfer_row.transfer_group_key AS transfer_group_key,
           transfer_row.payment_reference AS payment_reference,
           transfer_row.request_id AS request_id
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.pay_batch_id = v_operation_row.pay_batch_id
      AND (
        EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope AS linked_scope
          WHERE linked_scope.operation_id = p_operation_id
            AND linked_scope.pay_batch_id = v_operation_row.pay_batch_id
            AND linked_scope.pay_bank_transfer_id = transfer_row.id
        )
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{created_by_operation_id}', '')) = p_operation_id::text
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_execute_operation_id}', '')) = p_operation_id::text
        OR transfer_row.request_id LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')) LIKE ('op:' || p_operation_id::text || ':%')
        OR BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      )
  ) AS transfer_candidate
  LEFT JOIN LATERAL (
    SELECT classifier_inner.*
    FROM public.pay_bank_transfer_execution_classify(
      p_pay_batch_id => v_operation_row.pay_batch_id,
      p_pay_channel_scope => transfer_candidate.pay_channel,
      p_operation_id => p_operation_id,
      p_include_unscoped_transfers => true
    ) AS classifier_inner
    WHERE classifier_inner.pay_bank_transfer_id = transfer_candidate.pay_bank_transfer_id
    ORDER BY
      CASE WHEN classifier_inner.scope_operation_id = p_operation_id THEN 0 ELSE 1 END,
      classifier_inner.scope_id NULLS LAST,
      classifier_inner.pay_bank_transfer_id
    LIMIT 1
  ) AS classifier_row ON true;

  UPDATE pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer_update
  SET has_provider_event_evidence = true,
      is_safe_local_cleanup = false,
      evidence_classification = CASE
        WHEN NULLIF(BTRIM(COALESCE(classified_transfer_update.evidence_classification, '')), '') IS NULL
          OR classified_transfer_update.evidence_classification IN ('local_only_evidence', 'pending', 'unclassified_local') THEN 'provider_evidence_present'
        ELSE classified_transfer_update.evidence_classification
      END,
      unsafe_reason = CASE
        WHEN NULLIF(BTRIM(COALESCE(classified_transfer_update.unsafe_reason, '')), '') IS NULL
          OR classified_transfer_update.unsafe_reason = 'TRANSFER_CLASSIFICATION_MISSING' THEN 'UNLINKED_PROVIDER_EVENT_EVIDENCE_PRESENT'
        ELSE classified_transfer_update.unsafe_reason
      END
  FROM public.pay_bank_transfers AS transfer_row
  WHERE transfer_row.id = classified_transfer_update.pay_bank_transfer_id
    AND transfer_row.pay_batch_id = v_operation_row.pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS transfer_event
      WHERE transfer_event.pay_batch_id = v_operation_row.pay_batch_id
        AND upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN (
          'PROVIDER_RESPONSE',
          'PROVIDER_POLL',
          'PROVIDER_WEBHOOK',
          'WEBHOOK',
          'POLL',
          'RAIL_PROVIDER',
          'PROVIDER',
          'PROVIDER_SETTLEMENT',
          'RAIL_PROVIDER_SETTLEMENT'
        )
        AND EXISTS (
          SELECT 1
          FROM (VALUES
            (transfer_event.provider_event_id),
            (transfer_event.provider_reference),
            (transfer_event.raw_payload #>> '{provider_event_id}'),
            (transfer_event.raw_payload #>> '{provider_reference}'),
            (transfer_event.raw_payload #>> '{provider_submission_id}'),
            (transfer_event.raw_payload #>> '{submission_id}'),
            (transfer_event.raw_payload #>> '{rail_submission_id}'),
            (transfer_event.raw_payload #>> '{provider_payment_id}'),
            (transfer_event.raw_payload #>> '{payment_id}'),
            (transfer_event.raw_payload #>> '{external_payment_id}'),
            (transfer_event.raw_payload #>> '{revolut_payment_id}'),
            (transfer_event.raw_payload #>> '{provider_transfer_id}'),
            (transfer_event.raw_payload #>> '{transfer_id}'),
            (transfer_event.raw_payload #>> '{external_transfer_id}'),
            (transfer_event.raw_payload #>> '{provider_transaction_id}'),
            (transfer_event.raw_payload #>> '{transaction_id}')
          ) AS provider_event_identifier(identifier_value)
          WHERE NULLIF(BTRIM(COALESCE(provider_event_identifier.identifier_value, '')), '') IS NOT NULL
            AND NOT (
              NULLIF(BTRIM(COALESCE(provider_event_identifier.identifier_value, '')), '') = ANY(
                ARRAY_REMOVE(ARRAY[
                  transfer_row.id::text,
                  NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{local_provider_request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '')
                ]::text[], NULL::text)
              )
            )
            AND (
              transfer_event.pay_bank_transfer_id = transfer_row.id
              OR NULLIF(BTRIM(COALESCE(provider_event_identifier.identifier_value, '')), '') = ANY(
                ARRAY_REMOVE(ARRAY[
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_event_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submission_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{submission_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{rail_submission_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_payment_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{external_payment_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{revolut_payment_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_transfer_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{external_transfer_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_transaction_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{transaction_id}', '')), '')
                ]::text[], NULL::text)
              )
            )
        )
    );

  SELECT COUNT(*)::integer
  INTO v_scope_rows_considered
  FROM pg_temp.tmp_pay_execute_cleanup_scope_classified AS classified_scope;

  SELECT COUNT(*)::integer
  INTO v_transfer_rows_considered
  FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer;

  SELECT COUNT(*)::integer
  INTO v_provider_evidence_count
  FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer
  WHERE classified_transfer.has_provider_submission_evidence
     OR classified_transfer.has_provider_event_evidence;

  SELECT COUNT(*)::integer
  INTO v_provider_review_risk_count
  FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer
  WHERE classified_transfer.has_provider_submission_evidence
     OR classified_transfer.has_provider_event_evidence
     OR classified_transfer.has_provider_attempt_without_external_id
     OR classified_transfer.has_ambiguous_external_evidence;

  v_provider_evidence_count := COALESCE(v_provider_acceptance_evidence_count, 0);
  v_provider_review_risk_count := CASE
    WHEN COALESCE(v_provider_submit_requires_manual_review, false) IS TRUE THEN
      COALESCE(v_provider_acceptance_evidence_count, 0)
      + COALESCE(v_provider_response_present_count, 0)
      + COALESCE(v_provider_request_sent_count, 0)
      + COALESCE(v_provider_submission_unknown_count, 0)
      + COALESCE(v_stale_unresolved_submit_chunk_count, 0)
      + COALESCE(v_unfinalised_submit_chunk_count, 0)
    ELSE 0
  END;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_auth_requests;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_auth_requests (
    auth_request_id uuid PRIMARY KEY,
    auth_request_state text NOT NULL,
    auth_request_operation_id uuid,
    owner_operation_status text,
    is_same_operation boolean NOT NULL DEFAULT false,
    is_other_operation boolean NOT NULL DEFAULT false,
    has_auth_request_provider_risk boolean NOT NULL DEFAULT false,
    is_cancellable_local_auth_request boolean NOT NULL DEFAULT false,
    is_non_cancellable_auth_request boolean NOT NULL DEFAULT false,
    unsafe_reason text
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_auth_requests (
    auth_request_id,
    auth_request_state,
    auth_request_operation_id,
    owner_operation_status,
    is_same_operation,
    is_other_operation,
    has_auth_request_provider_risk,
    is_cancellable_local_auth_request,
    is_non_cancellable_auth_request,
    unsafe_reason
  )
  SELECT auth_request.id,
         upper(btrim(coalesce(auth_request.state, ''))) AS auth_request_state,
         CASE
           WHEN auth_intent.auth_operation_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
             THEN auth_intent.auth_operation_id_text::uuid
           ELSE NULL::uuid
         END AS auth_request_operation_id,
         upper(btrim(coalesce(owner_operation.status, ''))) AS owner_operation_status,
         (
           auth_intent.auth_operation_id_text = p_operation_id::text
         ) AS is_same_operation,
         (
           auth_intent.auth_operation_id_text IS NULL
           OR auth_intent.auth_operation_id_text <> p_operation_id::text
         ) AS is_other_operation,
         (
           v_batch_execution_boundary_crossed IS TRUE
           OR COALESCE(v_provider_review_risk_count, 0) > 0
         ) AS has_auth_request_provider_risk,
         COALESCE((
           upper(btrim(coalesce(auth_request.state, ''))) IN ('AWAITING', 'AUTHORISED')
           AND v_batch_execution_boundary_crossed IS NOT TRUE
           AND COALESCE(v_provider_review_risk_count, 0) = 0
           AND (
             auth_intent.auth_operation_id_text = p_operation_id::text
             OR (
               auth_intent.auth_operation_id_text IS NOT NULL
               AND auth_intent.auth_operation_id_text <> p_operation_id::text
               AND upper(btrim(coalesce(owner_operation.status, ''))) IN ('FAILED', 'CANCELLED', 'CANCELED')
             )
           )
         ), false) AS is_cancellable_local_auth_request,
         NOT COALESCE((
           upper(btrim(coalesce(auth_request.state, ''))) IN ('AWAITING', 'AUTHORISED')
           AND v_batch_execution_boundary_crossed IS NOT TRUE
           AND COALESCE(v_provider_review_risk_count, 0) = 0
           AND (
             auth_intent.auth_operation_id_text = p_operation_id::text
             OR (
               auth_intent.auth_operation_id_text IS NOT NULL
               AND auth_intent.auth_operation_id_text <> p_operation_id::text
               AND upper(btrim(coalesce(owner_operation.status, ''))) IN ('FAILED', 'CANCELLED', 'CANCELED')
             )
           )
         ), false) AS is_non_cancellable_auth_request,
         CASE
           WHEN v_batch_execution_boundary_crossed THEN 'AUTH_REQUEST_BATCH_EXECUTION_BOUNDARY_CROSSED'
           WHEN COALESCE(v_provider_evidence_count, 0) > 0 THEN 'AUTH_REQUEST_PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
           WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0 THEN 'AUTH_REQUEST_PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
           WHEN COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0 THEN 'AUTH_REQUEST_PROVIDER_SUBMISSION_UNKNOWN'
           WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'AUTH_REQUEST_PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
           WHEN upper(btrim(coalesce(auth_request.state, ''))) = 'PENDING_AUTHORISATION' THEN 'AUTH_REQUEST_PENDING_AUTHORISATION'
           WHEN auth_intent.auth_operation_id_text IS NULL THEN 'AUTH_REQUEST_OPERATION_ID_MISSING'
           WHEN auth_intent.auth_operation_id_text <> p_operation_id::text
             AND upper(btrim(coalesce(owner_operation.status, ''))) IN ('FAILED', 'CANCELLED', 'CANCELED') THEN NULL::text
           WHEN auth_intent.auth_operation_id_text <> p_operation_id::text THEN 'AUTH_REQUEST_OWNED_BY_DIFFERENT_OPERATION'
           ELSE NULL::text
         END AS unsafe_reason
  FROM public.pay_batch_auth_requests AS auth_request
  LEFT JOIN LATERAL (
    SELECT nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') AS auth_operation_id_text
  ) AS auth_intent ON true
  LEFT JOIN public.banking_pay_operations AS owner_operation
    ON owner_operation.id = CASE
      WHEN auth_intent.auth_operation_id_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN auth_intent.auth_operation_id_text::uuid
      ELSE NULL::uuid
    END
  WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
    AND upper(btrim(coalesce(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

  SELECT COUNT(*) FILTER (WHERE auth_classification.is_cancellable_local_auth_request)::integer,
         COUNT(*) FILTER (WHERE auth_classification.is_non_cancellable_auth_request)::integer,
         COUNT(*) FILTER (WHERE auth_classification.auth_request_state = 'AUTHORISED' AND auth_classification.is_non_cancellable_auth_request)::integer
  INTO v_cancellable_auth_request_count,
       v_non_cancellable_auth_request_count,
       v_authorised_auth_request_review_count
  FROM pg_temp.tmp_pay_execute_cleanup_auth_requests AS auth_classification;

  SELECT COUNT(*) FILTER (WHERE auth_classification.is_cancellable_local_auth_request AND auth_classification.auth_request_state = 'AWAITING')::integer,
         COUNT(*) FILTER (WHERE auth_classification.is_cancellable_local_auth_request AND auth_classification.auth_request_state = 'AUTHORISED')::integer
  INTO v_awaiting_auth_requests_cancelled,
       v_authorised_auth_requests_cancelled
  FROM pg_temp.tmp_pay_execute_cleanup_auth_requests AS auth_classification;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (
    auth_request_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  IF COALESCE(p_dry_run, false) IS TRUE THEN
    INSERT INTO pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (auth_request_id)
    SELECT auth_classification.auth_request_id
    FROM pg_temp.tmp_pay_execute_cleanup_auth_requests AS auth_classification
    WHERE auth_classification.is_cancellable_local_auth_request IS TRUE
    ON CONFLICT DO NOTHING;

    v_auth_requests_cancelled := COALESCE(v_cancellable_auth_request_count, 0);
  ELSE
    WITH cancellable_auth_requests AS (
      SELECT auth_classification.auth_request_id
      FROM pg_temp.tmp_pay_execute_cleanup_auth_requests AS auth_classification
      WHERE auth_classification.is_cancellable_local_auth_request IS TRUE
    ), cancelled_auth_requests AS (
      UPDATE public.pay_batch_auth_requests AS auth_request_update
      SET state = 'CANCELLED',
          finalised_at_utc = COALESCE(auth_request_update.finalised_at_utc, v_now),
          finalised_by_user_id = COALESCE(auth_request_update.finalised_by_user_id, v_effective_actor_user_id),
          execution_intent_json = jsonb_strip_nulls(
            COALESCE(auth_request_update.execution_intent_json, '{}'::jsonb)
            || jsonb_build_object(
              'cancelled_by_failed_execution_cleanup', true,
              'cleanup_operation_id', p_operation_id::text,
              'cleanup_at_utc', v_now::text,
              'failure_phase', v_failure_phase
            )
          )
      FROM cancellable_auth_requests
      WHERE auth_request_update.id = cancellable_auth_requests.auth_request_id
        AND auth_request_update.pay_batch_id = v_operation_row.pay_batch_id
        AND upper(btrim(coalesce(auth_request_update.state, ''))) IN ('AWAITING', 'AUTHORISED')
      RETURNING auth_request_update.id
    ), inserted_cancelled AS (
      INSERT INTO pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids (auth_request_id)
      SELECT cancelled_auth_requests.id
      FROM cancelled_auth_requests
      ON CONFLICT DO NOTHING
      RETURNING auth_request_id
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(inserted_cancelled.auth_request_id::text) ORDER BY inserted_cancelled.auth_request_id), '[]'::jsonb)
    INTO v_auth_requests_cancelled,
         v_cancelled_auth_request_ids
    FROM inserted_cancelled;

    WITH voided_tokens AS (
      UPDATE public.pay_batch_auth_tokens AS auth_token_update
      SET used_at_utc = COALESCE(auth_token_update.used_at_utc, v_now),
          expires_at_utc = CASE
            WHEN auth_token_update.expires_at_utc > v_now THEN v_now
            ELSE auth_token_update.expires_at_utc
          END
      FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request
      WHERE auth_token_update.auth_request_id = cancelled_auth_request.auth_request_id
        AND (auth_token_update.used_at_utc IS NULL OR auth_token_update.expires_at_utc > v_now)
      RETURNING auth_token_update.token
    )
    SELECT COUNT(*)::integer
    INTO v_auth_tokens_voided
    FROM voided_tokens;

    WITH cleared_batch_intent AS (
      UPDATE public.pay_batches AS batch_update
      SET schedule_kind = NULL::text,
          scheduled_at_utc = NULL::timestamptz,
          scheduled_by_user_id = NULL::uuid,
          funding_account_ref = NULL::text,
          funds_warning_hours_json = NULL::jsonb,
          execution_intent_json = NULL::jsonb
      WHERE batch_update.id = v_operation_row.pay_batch_id
        AND v_batch_execution_boundary_crossed IS NOT TRUE
        AND COALESCE(v_provider_review_risk_count, 0) = 0
        AND (
          NULLIF(BTRIM(COALESCE(batch_update.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
          OR EXISTS (
            SELECT 1
            FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request
            WHERE NULLIF(BTRIM(COALESCE(batch_update.execution_intent_json->>'auth_request_id', '')), '') = cancelled_auth_request.auth_request_id::text
          )
        )
      RETURNING batch_update.id
    )
    SELECT COUNT(*)::integer
    INTO v_batch_execution_intent_cleared
    FROM cleared_batch_intent;
  END IF;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(cancelled_auth_request.auth_request_id::text) ORDER BY cancelled_auth_request.auth_request_id), '[]'::jsonb)
  INTO v_auth_requests_cancelled,
       v_cancelled_auth_request_ids
  FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request;

  SELECT COUNT(*) FILTER (WHERE auth_classification.auth_request_state = 'AWAITING')::integer,
         COUNT(*) FILTER (WHERE auth_classification.auth_request_state = 'AUTHORISED')::integer
  INTO v_awaiting_auth_requests_cancelled,
       v_authorised_auth_requests_cancelled
  FROM pg_temp.tmp_pay_execute_cleanup_cancelled_auth_request_ids AS cancelled_auth_request
  JOIN pg_temp.tmp_pay_execute_cleanup_auth_requests AS auth_classification
    ON auth_classification.auth_request_id = cancelled_auth_request.auth_request_id;

  SELECT COUNT(*)::integer,
         (COUNT(*) FILTER (WHERE auth_request.execution_intent_json->>'operation_id' = p_operation_id::text))::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb)
  INTO v_active_auth_request_count,
       v_operation_active_auth_request_count,
       v_active_auth_request_ids
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = v_operation_row.pay_batch_id
    AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED');

  IF COALESCE(p_dry_run, false) IS TRUE THEN
    v_active_auth_request_blocker_count := COALESCE(v_non_cancellable_auth_request_count, 0);
  ELSE
    v_active_auth_request_blocker_count := COALESCE(v_active_auth_request_count, 0);
  END IF;

  v_deletion_allowed := (
    v_batch_execution_boundary_crossed IS NOT TRUE
    AND COALESCE(v_provider_review_risk_count, 0) = 0
    AND COALESCE(v_active_auth_request_blocker_count, 0) = 0
  );

  IF v_deletion_allowed IS TRUE THEN
    UPDATE pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer_update
    SET is_safe_local_cleanup = true,
        unsafe_reason = NULL::text
    WHERE classified_transfer_update.has_provider_submission_evidence IS NOT TRUE
      AND classified_transfer_update.has_provider_event_evidence IS NOT TRUE
      AND classified_transfer_update.has_provider_attempt_without_external_id IS NOT TRUE
      AND classified_transfer_update.has_ambiguous_external_evidence IS NOT TRUE
      AND classified_transfer_update.is_failed_or_blocked IS NOT TRUE
      AND classified_transfer_update.is_terminal_or_completed IS NOT TRUE;

    UPDATE pg_temp.tmp_pay_execute_cleanup_scope_classified AS classified_scope_update
    SET classifier_is_safe_local_cleanup = true,
        unsafe_reason = NULL::text
    WHERE (
        classified_scope_update.pay_bank_transfer_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer
          WHERE classified_transfer.pay_bank_transfer_id = classified_scope_update.pay_bank_transfer_id
            AND classified_transfer.is_safe_local_cleanup IS TRUE
        )
      )
      AND classified_scope_update.has_provider_submission_evidence IS NOT TRUE
      AND classified_scope_update.has_provider_event_evidence IS NOT TRUE
      AND classified_scope_update.has_provider_attempt_without_external_id IS NOT TRUE
      AND classified_scope_update.has_ambiguous_external_evidence IS NOT TRUE
      AND classified_scope_update.is_failed_or_blocked IS NOT TRUE
      AND classified_scope_update.is_terminal_or_completed IS NOT TRUE;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids (
    pay_bank_transfer_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids (pay_bank_transfer_id)
  SELECT classified_transfer.pay_bank_transfer_id
  FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = classified_transfer.pay_bank_transfer_id
   AND transfer_row.pay_batch_id = v_operation_row.pay_batch_id
  WHERE v_deletion_allowed IS TRUE
    AND classified_transfer.is_safe_local_cleanup IS TRUE
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS transfer_event
      WHERE transfer_event.pay_batch_id = v_operation_row.pay_batch_id
        AND (
          transfer_event.pay_bank_transfer_id = transfer_row.id
          OR (
            transfer_event.pay_bank_transfer_id IS NULL
            AND (
              NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                transfer_row.id::text,
                NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_reference}', '')), '')
              ]::text[], NULL::text))
              OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                transfer_row.id::text,
                NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_reference}', '')), '')
              ]::text[], NULL::text))
              OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                transfer_row.id::text,
                NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_reference}', '')), '')
              ]::text[], NULL::text))
            )
          )
          OR EXISTS (
            SELECT 1
            FROM (VALUES
              (transfer_row.id::text),
              (NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '')),
              (NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), '')),
              (NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), '')),
              (NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{request_id}', '')), '')),
              (NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), '')),
              (NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{payment_reference}', '')), ''))
            ) AS provider_event_identity(identity_value)
            WHERE LENGTH(NULLIF(BTRIM(COALESCE(provider_event_identity.identity_value, '')), '')) >= 8
              AND POSITION(lower(NULLIF(BTRIM(COALESCE(provider_event_identity.identity_value, '')), '')) IN lower(COALESCE(transfer_event.raw_payload::text, ''))) > 0
          )
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_chunks AS operation_chunk
      JOIN public.banking_pay_operations AS chunk_operation
        ON chunk_operation.id = operation_chunk.operation_id
      CROSS JOIN LATERAL (
        SELECT COALESCE(
          CASE
            WHEN jsonb_typeof(operation_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN operation_chunk.error_json->'provider_submit_diagnostic'
            ELSE NULL::jsonb
          END,
          CASE
            WHEN jsonb_typeof(operation_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN operation_chunk.result_json->'provider_submit_diagnostic'
            ELSE NULL::jsonb
          END,
          '{}'::jsonb
        ) AS provider_submit_diagnostic
      ) AS operation_chunk_diagnostic
      WHERE chunk_operation.pay_batch_id = v_operation_row.pay_batch_id
        AND (
          operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
          OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
        )
        AND (
          operation_chunk.status IN ('RUNNING', 'COMPLETE', 'FAILED')
          OR operation_chunk.started_at_utc IS NOT NULL
          OR (operation_chunk.result_json IS NOT NULL AND operation_chunk.result_json <> '{}'::jsonb)
          OR (operation_chunk.error_json IS NOT NULL AND operation_chunk.error_json <> '{}'::jsonb)
        )
        AND POSITION(lower(transfer_row.id::text) IN lower(COALESCE(operation_chunk.payload_json::text, '') || COALESCE(operation_chunk.result_json::text, '') || COALESCE(operation_chunk.error_json::text, ''))) > 0
        AND NOT (
          operation_chunk.operation_id = p_operation_id
          AND upper(BTRIM(COALESCE(operation_chunk.status, ''))) IN ('COMPLETE', 'FAILED', 'SKIPPED')
          AND upper(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_status', ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_attempted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_called', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_sent', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_received', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_external_evidence_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
          AND NULLIF(BTRIM(COALESCE(
            operation_chunk_diagnostic.provider_submit_diagnostic->>'rail_tx_id',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_transaction_id',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_payment_id',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_reference',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_dispatched_at_utc',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'request_sent_at_utc',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'response_received_at_utc',
            operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_http_status',
            ''
          )), '') IS NULL
        )
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS other_scope
      WHERE other_scope.pay_bank_transfer_id = transfer_row.id
        AND other_scope.operation_id <> p_operation_id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS correction_item
      WHERE correction_item.pay_bank_transfer_id = transfer_row.id
    )
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_work_items AS correction_work_item
      WHERE correction_work_item.pay_bank_transfer_id = transfer_row.id
    );

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_safe_scope_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_safe_scope_ids (
    scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_safe_scope_ids (scope_id)
  SELECT classified_scope.scope_id
  FROM pg_temp.tmp_pay_execute_cleanup_scope_classified AS classified_scope
  WHERE v_deletion_allowed IS TRUE
    AND (
      classified_scope.pay_bank_transfer_id IS NULL
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer
        WHERE safe_transfer.pay_bank_transfer_id = classified_scope.pay_bank_transfer_id
      )
    );

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(safe_scope.scope_id::text) ORDER BY safe_scope.scope_id), '[]'::jsonb)
  INTO v_safe_scope_candidate_count,
       v_safe_scope_ids
  FROM pg_temp.tmp_pay_execute_cleanup_safe_scope_ids AS safe_scope;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(safe_transfer.pay_bank_transfer_id::text) ORDER BY safe_transfer.pay_bank_transfer_id), '[]'::jsonb)
  INTO v_safe_transfer_candidate_count,
       v_safe_transfer_ids
  FROM pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts;
  CREATE TEMPORARY TABLE pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts (
    scope_id uuid,
    pay_bank_transfer_id uuid,
    pay_channel text,
    transfer_group_key text,
    unsafe_reason text
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts (
    scope_id,
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    unsafe_reason
  )
  SELECT classified_scope.scope_id,
         classified_scope.pay_bank_transfer_id,
         classified_scope.pay_channel,
         classified_scope.transfer_group_key,
         COALESCE(
           CASE WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED' ELSE NULL::text END,
           CASE
             WHEN COALESCE(v_provider_evidence_count, 0) > 0 THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
             WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
             WHEN COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
             WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
             ELSE NULL::text
           END,
           CASE WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'ACTIVE_AUTH_REQUEST_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_scope.has_provider_event_evidence THEN 'PROVIDER_EVENT_EVIDENCE_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_scope.has_provider_submission_evidence THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_scope.has_provider_attempt_without_external_id THEN 'PROVIDER_ATTEMPT_WITHOUT_EXTERNAL_ID' ELSE NULL::text END,
           CASE WHEN classified_scope.has_ambiguous_external_evidence THEN COALESCE(NULLIF(BTRIM(COALESCE(classified_scope.unsafe_reason, '')), ''), 'PROVIDER_SUBMISSION_UNKNOWN') ELSE NULL::text END,
           CASE WHEN classified_scope.is_terminal_or_completed THEN 'TERMINAL_OR_COMPLETED_TRANSFER_STATE' ELSE NULL::text END,
           CASE WHEN classified_scope.is_failed_or_blocked THEN 'FAILED_OR_BLOCKED_TRANSFER_STATE' ELSE NULL::text END,
           classified_scope.unsafe_reason,
           'UNSAFE_LOCAL_SCOPE_CLEANUP_NOT_CONFIRMED'
         )
  FROM pg_temp.tmp_pay_execute_cleanup_scope_classified AS classified_scope
  WHERE NOT EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_execute_cleanup_safe_scope_ids AS safe_scope
    WHERE safe_scope.scope_id = classified_scope.scope_id
  );

  INSERT INTO pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts (
    scope_id,
    pay_bank_transfer_id,
    pay_channel,
    transfer_group_key,
    unsafe_reason
  )
  SELECT NULL::uuid,
         classified_transfer.pay_bank_transfer_id,
         classified_transfer.pay_channel,
         classified_transfer.transfer_group_key,
         COALESCE(
           CASE WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED' ELSE NULL::text END,
           CASE
             WHEN COALESCE(v_provider_evidence_count, 0) > 0 THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
             WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
             WHEN COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
             WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
             ELSE NULL::text
           END,
           CASE WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'ACTIVE_AUTH_REQUEST_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_transfer.has_provider_event_evidence THEN 'PROVIDER_EVENT_EVIDENCE_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_transfer.has_provider_submission_evidence THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' ELSE NULL::text END,
           CASE WHEN classified_transfer.has_provider_attempt_without_external_id THEN 'PROVIDER_ATTEMPT_WITHOUT_EXTERNAL_ID' ELSE NULL::text END,
           CASE WHEN classified_transfer.has_ambiguous_external_evidence THEN COALESCE(NULLIF(BTRIM(COALESCE(classified_transfer.unsafe_reason, '')), ''), 'PROVIDER_SUBMISSION_UNKNOWN') ELSE NULL::text END,
           CASE WHEN classified_transfer.is_terminal_or_completed THEN 'TERMINAL_OR_COMPLETED_TRANSFER_STATE' ELSE NULL::text END,
           CASE WHEN classified_transfer.is_failed_or_blocked THEN 'FAILED_OR_BLOCKED_TRANSFER_STATE' ELSE NULL::text END,
           CASE
             WHEN EXISTS (
               SELECT 1
               FROM public.pay_payment_correction_items AS correction_item
               WHERE correction_item.pay_bank_transfer_id = classified_transfer.pay_bank_transfer_id
             ) THEN 'PAYMENT_CORRECTION_REFERENCE_PRESENT'
             ELSE NULL::text
           END,
           CASE
             WHEN EXISTS (
               SELECT 1
               FROM public.pay_payment_correction_work_items AS correction_work_item
               WHERE correction_work_item.pay_bank_transfer_id = classified_transfer.pay_bank_transfer_id
             ) THEN 'PAYMENT_CORRECTION_WORK_REFERENCE_PRESENT'
             ELSE NULL::text
           END,
           classified_transfer.unsafe_reason,
           'UNSAFE_LOCAL_TRANSFER_CLEANUP_NOT_CONFIRMED'
         )
  FROM pg_temp.tmp_pay_execute_cleanup_transfer_classified AS classified_transfer
  WHERE NOT EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer
    WHERE safe_transfer.pay_bank_transfer_id = classified_transfer.pay_bank_transfer_id
  );

  SELECT COALESCE((COUNT(DISTINCT unsafe_artifact.pay_bank_transfer_id) FILTER (WHERE unsafe_artifact.pay_bank_transfer_id IS NOT NULL)), 0)::integer,
         COALESCE((COUNT(DISTINCT unsafe_artifact.scope_id) FILTER (WHERE unsafe_artifact.pay_bank_transfer_id IS NULL)), 0)::integer
  INTO v_unsafe_transfer_count,
       v_unsafe_scope_count
  FROM pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts AS unsafe_artifact;

  SELECT COALESCE(jsonb_agg(to_jsonb(unsafe_transfer_ids.pay_bank_transfer_id::text) ORDER BY unsafe_transfer_ids.pay_bank_transfer_id), '[]'::jsonb)
  INTO v_unsafe_transfer_ids
  FROM (
    SELECT DISTINCT unsafe_artifact.pay_bank_transfer_id
    FROM pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts AS unsafe_artifact
    WHERE unsafe_artifact.pay_bank_transfer_id IS NOT NULL
  ) AS unsafe_transfer_ids;

  SELECT COALESCE(jsonb_agg(
           jsonb_strip_nulls(jsonb_build_object(
             'scope_id', CASE WHEN unsafe_artifact.scope_id IS NULL THEN NULL ELSE unsafe_artifact.scope_id::text END,
             'pay_bank_transfer_id', CASE WHEN unsafe_artifact.pay_bank_transfer_id IS NULL THEN NULL ELSE unsafe_artifact.pay_bank_transfer_id::text END,
             'pay_channel', unsafe_artifact.pay_channel,
             'transfer_group_key', unsafe_artifact.transfer_group_key,
             'reason', unsafe_artifact.unsafe_reason
           ))
           ORDER BY unsafe_artifact.pay_channel NULLS LAST,
                    unsafe_artifact.transfer_group_key NULLS LAST,
                    unsafe_artifact.pay_bank_transfer_id NULLS LAST,
                    unsafe_artifact.scope_id NULLS LAST
         ), '[]'::jsonb)
  INTO v_unsafe_reasons
  FROM pg_temp.tmp_pay_execute_cleanup_unsafe_artifacts AS unsafe_artifact;

  IF COALESCE(p_dry_run, false) IS TRUE THEN
    SELECT COUNT(*)::integer,
           COALESCE((COUNT(*) FILTER (
             WHERE item_row.bank_reference = transfer_row.payment_reference
               AND NULLIF(BTRIM(COALESCE(item_row.bank_reference, '')), '') IS NOT NULL
           )), 0)::integer
    INTO v_item_links_cleared,
         v_bank_references_cleared
    FROM public.pay_batch_items AS item_row
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = item_row.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = v_operation_row.pay_batch_id
    JOIN pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer
      ON safe_transfer.pay_bank_transfer_id = item_row.pay_bank_transfer_id
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = safe_transfer.pay_bank_transfer_id;

    SELECT COALESCE((COUNT(*) FILTER (WHERE operation_chunk.status = 'RUNNING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE operation_chunk.status = 'PENDING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE operation_chunk.locked_by IS NOT NULL OR operation_chunk.lock_expires_at_utc IS NOT NULL)), 0)::integer
    INTO v_chunks_marked_failed,
         v_chunks_marked_skipped,
         v_locks_released
    FROM public.banking_pay_operation_chunks AS operation_chunk
    WHERE operation_chunk.operation_id = p_operation_id
      AND operation_chunk.status IN ('PENDING', 'RUNNING')
      AND NOT (
        operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
        OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
      );

    v_scope_rows_deleted := v_safe_scope_candidate_count;
    v_transfer_rows_deleted := v_safe_transfer_candidate_count;
  ELSE
    WITH item_rows_to_clear AS (
      SELECT item_row.id AS pay_batch_item_id,
             item_row.bank_reference AS previous_bank_reference,
             transfer_row.payment_reference AS transfer_payment_reference
      FROM public.pay_batch_items AS item_row
      JOIN public.pay_batch_candidates AS batch_candidate
        ON batch_candidate.id = item_row.pay_batch_candidate_id
       AND batch_candidate.pay_batch_id = v_operation_row.pay_batch_id
      JOIN pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer
        ON safe_transfer.pay_bank_transfer_id = item_row.pay_bank_transfer_id
      JOIN public.pay_bank_transfers AS transfer_row
        ON transfer_row.id = safe_transfer.pay_bank_transfer_id
    ), cleared_item_links AS (
      UPDATE public.pay_batch_items AS item_update
      SET pay_bank_transfer_id = NULL,
          bank_reference = CASE
            WHEN item_update.bank_reference = item_rows_to_clear.transfer_payment_reference THEN NULL
            ELSE item_update.bank_reference
          END,
          updated_at = v_now
      FROM item_rows_to_clear
      WHERE item_update.id = item_rows_to_clear.pay_batch_item_id
      RETURNING item_update.id,
                item_rows_to_clear.previous_bank_reference,
                item_rows_to_clear.transfer_payment_reference
    )
    SELECT COUNT(*)::integer,
           COALESCE((COUNT(*) FILTER (
             WHERE cleared_item_links.previous_bank_reference = cleared_item_links.transfer_payment_reference
               AND NULLIF(BTRIM(COALESCE(cleared_item_links.previous_bank_reference, '')), '') IS NOT NULL
           )), 0)::integer
    INTO v_item_links_cleared,
         v_bank_references_cleared
    FROM cleared_item_links;

    WITH deleted_scope_rows AS (
      DELETE FROM public.banking_pay_operation_transfer_scope AS scope_delete
      USING pg_temp.tmp_pay_execute_cleanup_safe_scope_ids AS safe_scope
      WHERE scope_delete.id = safe_scope.scope_id
        AND scope_delete.operation_id = p_operation_id
        AND scope_delete.pay_batch_id = v_operation_row.pay_batch_id
      RETURNING scope_delete.id
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(deleted_scope_rows.id::text) ORDER BY deleted_scope_rows.id), '[]'::jsonb)
    INTO v_scope_rows_deleted,
         v_deleted_scope_ids
    FROM deleted_scope_rows;

    WITH deleted_transfer_rows AS (
      DELETE FROM public.pay_bank_transfers AS transfer_delete
      USING pg_temp.tmp_pay_execute_cleanup_safe_transfer_ids AS safe_transfer
      WHERE transfer_delete.id = safe_transfer.pay_bank_transfer_id
        AND transfer_delete.pay_batch_id = v_operation_row.pay_batch_id
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_transfer_scope AS remaining_scope
          WHERE remaining_scope.pay_bank_transfer_id = transfer_delete.id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_batch_items AS remaining_item
          WHERE remaining_item.pay_bank_transfer_id = transfer_delete.id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS transfer_event
          WHERE transfer_event.pay_bank_transfer_id = transfer_delete.id
             OR (
               transfer_event.pay_batch_id = v_operation_row.pay_batch_id
               AND transfer_event.pay_bank_transfer_id IS NULL
               AND (
                 NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                   transfer_delete.id::text,
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_tx_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.request_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.payment_reference, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{request_id}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{idempotency_key}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{payment_reference}', '')), '')
                 ]::text[], NULL::text))
                 OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                   transfer_delete.id::text,
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_tx_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.request_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.payment_reference, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{request_id}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{idempotency_key}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{payment_reference}', '')), '')
                 ]::text[], NULL::text))
                 OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                   transfer_delete.id::text,
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_tx_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.request_id, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.payment_reference, '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{request_id}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{idempotency_key}', '')), ''),
                   NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{payment_reference}', '')), '')
                 ]::text[], NULL::text))
               )
             )
             OR (
               transfer_event.pay_batch_id = v_operation_row.pay_batch_id
               AND EXISTS (
                 SELECT 1
                 FROM (VALUES
                   (transfer_delete.id::text),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.rail_tx_id, '')), '')),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.request_id, '')), '')),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.payment_reference, '')), '')),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{request_id}', '')), '')),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{idempotency_key}', '')), '')),
                   (NULLIF(BTRIM(COALESCE(transfer_delete.rail_meta_json #>> '{payment_reference}', '')), ''))
                 ) AS provider_event_identity(identity_value)
                 WHERE LENGTH(NULLIF(BTRIM(COALESCE(provider_event_identity.identity_value, '')), '')) >= 8
                   AND POSITION(lower(NULLIF(BTRIM(COALESCE(provider_event_identity.identity_value, '')), '')) IN lower(COALESCE(transfer_event.raw_payload::text, ''))) > 0
               )
             )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_chunks AS operation_chunk
          JOIN public.banking_pay_operations AS chunk_operation
            ON chunk_operation.id = operation_chunk.operation_id
          CROSS JOIN LATERAL (
            SELECT COALESCE(
              CASE
                WHEN jsonb_typeof(operation_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN operation_chunk.error_json->'provider_submit_diagnostic'
                ELSE NULL::jsonb
              END,
              CASE
                WHEN jsonb_typeof(operation_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN operation_chunk.result_json->'provider_submit_diagnostic'
                ELSE NULL::jsonb
              END,
              '{}'::jsonb
            ) AS provider_submit_diagnostic
          ) AS operation_chunk_diagnostic
          WHERE chunk_operation.pay_batch_id = v_operation_row.pay_batch_id
            AND (
              operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
              OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
            )
            AND (
              operation_chunk.status IN ('RUNNING', 'COMPLETE', 'FAILED')
              OR operation_chunk.started_at_utc IS NOT NULL
              OR (operation_chunk.result_json IS NOT NULL AND operation_chunk.result_json <> '{}'::jsonb)
              OR (operation_chunk.error_json IS NOT NULL AND operation_chunk.error_json <> '{}'::jsonb)
            )
            AND POSITION(lower(transfer_delete.id::text) IN lower(COALESCE(operation_chunk.payload_json::text, '') || COALESCE(operation_chunk.result_json::text, '') || COALESCE(operation_chunk.error_json::text, ''))) > 0
            AND NOT (
              operation_chunk.operation_id = p_operation_id
              AND upper(BTRIM(COALESCE(operation_chunk.status, ''))) IN ('COMPLETE', 'FAILED', 'SKIPPED')
              AND upper(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_status', ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_attempted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_called', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_sent', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_received', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_response_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND lower(BTRIM(COALESCE(operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_external_evidence_present', 'false'))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
              AND NULLIF(BTRIM(COALESCE(
                operation_chunk_diagnostic.provider_submit_diagnostic->>'rail_tx_id',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_transaction_id',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_payment_id',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_reference',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_request_dispatched_at_utc',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'request_sent_at_utc',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'response_received_at_utc',
                operation_chunk_diagnostic.provider_submit_diagnostic->>'provider_http_status',
                ''
              )), '') IS NULL
            )
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS correction_item
          WHERE correction_item.pay_bank_transfer_id = transfer_delete.id
        )
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_work_items AS correction_work_item
          WHERE correction_work_item.pay_bank_transfer_id = transfer_delete.id
        )
      RETURNING transfer_delete.id
    )
    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(deleted_transfer_rows.id::text) ORDER BY deleted_transfer_rows.id), '[]'::jsonb)
    INTO v_transfer_rows_deleted,
         v_deleted_transfer_ids
    FROM deleted_transfer_rows;

    WITH chunks_to_mutate AS (
      SELECT operation_chunk.id AS operation_chunk_id,
             operation_chunk.status AS previous_status,
             (operation_chunk.locked_by IS NOT NULL OR operation_chunk.lock_expires_at_utc IS NOT NULL) AS had_lock
      FROM public.banking_pay_operation_chunks AS operation_chunk
      WHERE operation_chunk.operation_id = p_operation_id
        AND operation_chunk.status IN ('PENDING', 'RUNNING')
        AND NOT (
          operation_chunk.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'APPLY_SETTLEMENT_CHUNKS', 'QUEUE_REMITTANCE_CHUNKS', 'QUEUE_PAYOUT_NOTICE_CHUNKS')
          OR operation_chunk.chunk_type IN ('TRANSFER_SUBMIT', 'RAIL_UPDATE', 'SETTLEMENT_APPLY', 'REMITTANCE_QUEUE', 'PAYOUT_NOTICE_QUEUE')
        )
    ), mutated_chunks AS (
      UPDATE public.banking_pay_operation_chunks AS operation_chunk_update
      SET status = CASE WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN 'FAILED' ELSE 'SKIPPED' END,
          result_json = CASE
            WHEN chunks_to_mutate.previous_status = 'PENDING' THEN jsonb_strip_nulls(
              COALESCE(operation_chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
                'skipped_by_failed_execution_cleanup', true,
                'cleanup_operation_id', p_operation_id::text,
                'cleanup_at_utc', v_now::text,
                'failure_phase', v_failure_phase
              )
            )
            ELSE operation_chunk_update.result_json
          END,
          error_json = CASE
            WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN jsonb_strip_nulls(jsonb_build_object(
              'code', 'PAYMENT_EXECUTE_FAILED_LOCAL_ARTIFACT_CLEANUP',
              'message', 'Chunk was still running when failed payment execution cleanup ran.',
              'operation_id', p_operation_id::text,
              'failure_phase', v_failure_phase,
              'cleanup_at_utc', v_now::text,
              'failure_code', NULLIF(BTRIM(COALESCE(v_failure_error_json->>'code', v_failure_error_json->>'error', '')), '')
            ))
            ELSE operation_chunk_update.error_json
          END,
          failed_count = CASE
            WHEN chunks_to_mutate.previous_status = 'RUNNING' THEN
              CASE
                WHEN COALESCE(operation_chunk_update.unit_count, 0) > 0 THEN GREATEST(COALESCE(operation_chunk_update.failed_count, 0), COALESCE(operation_chunk_update.unit_count, 0) - COALESCE(operation_chunk_update.completed_count, 0))
                ELSE GREATEST(COALESCE(operation_chunk_update.failed_count, 0), 1)
              END
            ELSE operation_chunk_update.failed_count
          END,
          locked_by = NULL::text,
          lock_expires_at_utc = NULL::timestamptz,
          completed_at_utc = COALESCE(operation_chunk_update.completed_at_utc, v_now),
          updated_at_utc = v_now
      FROM chunks_to_mutate
      WHERE operation_chunk_update.id = chunks_to_mutate.operation_chunk_id
      RETURNING chunks_to_mutate.previous_status,
                chunks_to_mutate.had_lock
    )
    SELECT COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'RUNNING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.previous_status = 'PENDING')), 0)::integer,
           COALESCE((COUNT(*) FILTER (WHERE mutated_chunks.had_lock)), 0)::integer
    INTO v_chunks_marked_failed,
         v_chunks_marked_skipped,
         v_locks_released
    FROM mutated_chunks;

    WITH terminal_lock_release AS (
      UPDATE public.banking_pay_operation_chunks AS terminal_chunk_update
      SET locked_by = NULL::text,
          lock_expires_at_utc = NULL::timestamptz,
          updated_at_utc = v_now
      WHERE terminal_chunk_update.operation_id = p_operation_id
        AND terminal_chunk_update.status IN ('COMPLETE', 'FAILED', 'SKIPPED')
        AND (terminal_chunk_update.locked_by IS NOT NULL OR terminal_chunk_update.lock_expires_at_utc IS NOT NULL)
        AND NOT (
          terminal_chunk_update.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'APPLY_SETTLEMENT_CHUNKS', 'QUEUE_REMITTANCE_CHUNKS', 'QUEUE_PAYOUT_NOTICE_CHUNKS')
          OR terminal_chunk_update.chunk_type IN ('TRANSFER_SUBMIT', 'RAIL_UPDATE', 'SETTLEMENT_APPLY', 'REMITTANCE_QUEUE', 'PAYOUT_NOTICE_QUEUE')
        )
      RETURNING terminal_chunk_update.id
    )
    SELECT COALESCE(v_locks_released, 0) + COUNT(*)::integer
    INTO v_locks_released
    FROM terminal_lock_release;
  END IF;

  SELECT COUNT(*)::integer
  INTO v_remaining_operation_scope_count
  FROM public.banking_pay_operation_transfer_scope AS remaining_scope
  WHERE remaining_scope.operation_id = p_operation_id
    AND remaining_scope.pay_batch_id = v_operation_row.pay_batch_id;

  SELECT COUNT(*)::integer
  INTO v_remaining_operation_transfer_count
  FROM public.pay_bank_transfers AS remaining_transfer
  WHERE remaining_transfer.pay_batch_id = v_operation_row.pay_batch_id
    AND (
      BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{operation_id}', '')) = p_operation_id::text
      OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{created_by_operation_id}', '')) = p_operation_id::text
      OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{payment_execute_operation_id}', '')) = p_operation_id::text
      OR remaining_transfer.request_id LIKE ('op:' || p_operation_id::text || ':%')
      OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{request_id}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      OR BTRIM(COALESCE(remaining_transfer.rail_meta_json #>> '{idempotency_key}', '')) LIKE ('op:' || p_operation_id::text || ':%')
      OR EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS remaining_scope
        WHERE remaining_scope.operation_id = p_operation_id
          AND remaining_scope.pay_batch_id = v_operation_row.pay_batch_id
          AND remaining_scope.pay_bank_transfer_id = remaining_transfer.id
      )
    );

  IF COALESCE(p_dry_run, false) IS TRUE THEN
    v_retry_blocked := (
      v_batch_execution_boundary_crossed IS TRUE
      OR COALESCE(v_active_auth_request_blocker_count, 0) > 0
      OR COALESCE(v_provider_review_risk_count, 0) > 0
      OR COALESCE(v_unsafe_transfer_count, 0) > 0
      OR COALESCE(v_unsafe_scope_count, 0) > 0
    );
  ELSE
    v_retry_blocked := (
      v_batch_execution_boundary_crossed IS TRUE
      OR COALESCE(v_active_auth_request_blocker_count, 0) > 0
      OR COALESCE(v_provider_review_risk_count, 0) > 0
      OR COALESCE(v_unsafe_transfer_count, 0) > 0
      OR COALESCE(v_unsafe_scope_count, 0) > 0
      OR COALESCE(v_remaining_operation_scope_count, 0) > 0
      OR COALESCE(v_remaining_operation_transfer_count, 0) > 0
    );
  END IF;

  v_review_required := v_retry_blocked;
  v_safe_to_retry := (v_retry_blocked IS NOT TRUE);

  v_cleanup_mode := CASE
    WHEN COALESCE(p_dry_run, false) IS TRUE THEN 'DRY_RUN'
    WHEN v_batch_execution_boundary_crossed THEN 'REVIEW_REQUIRED_BATCH_EXECUTION_BOUNDARY'
    WHEN COALESCE(v_provider_evidence_count, 0) > 0 THEN 'REVIEW_REQUIRED_PROVIDER_ACCEPTANCE_EVIDENCE'
    WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0 THEN 'REVIEW_REQUIRED_STALE_PROVIDER_SUBMIT_CHUNK'
    WHEN COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0 THEN 'REVIEW_REQUIRED_UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'REVIEW_REQUIRED_PROVIDER_MALFORMED_RESPONSE'
    WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'REVIEW_REQUIRED_ACTIVE_AUTH_REQUEST'
    WHEN COALESCE(v_provider_review_risk_count, 0) > 0 THEN 'REVIEW_REQUIRED_PROVIDER_SUBMISSION_REVIEW'
    WHEN COALESCE(v_unsafe_transfer_count, 0) > 0 OR COALESCE(v_unsafe_scope_count, 0) > 0 THEN 'REVIEW_REQUIRED_UNSAFE_LOCAL_ARTIFACTS'
    WHEN COALESCE(v_remaining_operation_scope_count, 0) > 0 OR COALESCE(v_remaining_operation_transfer_count, 0) > 0 THEN 'REVIEW_REQUIRED_RETRY_BLOCKER_REMAINS'
    WHEN COALESCE(v_scope_rows_deleted, 0) > 0 OR COALESCE(v_transfer_rows_deleted, 0) > 0 OR COALESCE(v_item_links_cleared, 0) > 0 OR COALESCE(v_chunks_marked_failed, 0) > 0 OR COALESCE(v_chunks_marked_skipped, 0) > 0 THEN CASE
      WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'CLEANED_LOCAL_ARTIFACTS_PROVIDER_BLOCKED_PRE_CALL'
      ELSE 'CLEANED_LOCAL_ARTIFACTS_NO_PROVIDER_CALL'
    END
    ELSE 'NO_LOCAL_ARTIFACTS_TO_CLEAN'
  END;

  v_retry_blocked_reason := CASE
    WHEN v_retry_blocked IS NOT TRUE THEN NULL::text
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND COALESCE(v_provider_evidence_count, 0) > 0 THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_PROVIDER_ACCEPTANCE_EVIDENCE'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND (COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0) THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND (COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0) THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_PROVIDER_SUBMISSION_UNKNOWN'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND COALESCE(v_unsafe_transfer_count, 0) > 0 THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_UNSAFE_TRANSFER'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS'
      AND COALESCE(v_unsafe_scope_count, 0) > 0 THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE_UNSAFE_SCOPE'
    WHEN v_operation_type_upper = 'PAYMENT_RETRY_BLOCKED_FUNDS' THEN 'PAYMENT_RETRY_BLOCKED_FUNDS_CLEANUP_NOT_SAFE'
    WHEN v_batch_execution_boundary_crossed THEN 'BATCH_EXECUTION_BOUNDARY_CROSSED'
    WHEN COALESCE(v_provider_evidence_count, 0) > 0 THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
    WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' OR COALESCE(v_stale_empty_provider_submit_chunk_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
    WHEN COALESCE(v_provider_submission_status, '') = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' OR COALESCE(v_provider_submit_unknown_chunk_count, 0) > 0 THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    WHEN COALESCE(v_provider_submission_status, '') = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
    WHEN COALESCE(v_active_auth_request_blocker_count, 0) > 0 THEN 'ACTIVE_AUTH_REQUEST_PRESENT'
    WHEN COALESCE(v_provider_review_risk_count, 0) > 0 THEN 'PROVIDER_SUBMISSION_REVIEW_REQUIRED'
    WHEN COALESCE(v_unsafe_transfer_count, 0) > 0 OR COALESCE(v_unsafe_scope_count, 0) > 0 THEN 'UNSAFE_LOCAL_ARTIFACTS_REMAIN'
    WHEN COALESCE(v_remaining_operation_scope_count, 0) > 0 OR COALESCE(v_remaining_operation_transfer_count, 0) > 0 THEN 'RETRY_BLOCKER_REMAINS'
    ELSE 'RETRY_BLOCKED'
  END;

  v_result := jsonb_strip_nulls(
    jsonb_build_object(
      'ok', true,
      'dry_run', COALESCE(p_dry_run, false),
      'dry_run_counts_are_prospective', COALESCE(p_dry_run, false),
      'operation_id', p_operation_id::text,
      'pay_batch_id', v_operation_row.pay_batch_id::text,
      'failure_phase', v_failure_phase,
      'cleanup_mode', v_cleanup_mode,
      'operation_types_supported', jsonb_build_array('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS'),
      'operation_type_cleanup_mode', v_operation_type_cleanup_mode,
      'retry_blocked_reason', v_retry_blocked_reason,
      'safe_to_retry', v_safe_to_retry,
      'retry_blocked', v_retry_blocked,
      'review_required', v_review_required,
      'scope_rows_considered', COALESCE(v_scope_rows_considered, 0),
      'transfer_rows_considered', COALESCE(v_transfer_rows_considered, 0),
      'safe_scope_candidate_count', COALESCE(v_safe_scope_candidate_count, 0),
      'safe_transfer_candidate_count', COALESCE(v_safe_transfer_candidate_count, 0),
      'safe_local_transfer_count', COALESCE(v_safe_transfer_candidate_count, 0),
      'scope_rows_deleted', COALESCE(v_scope_rows_deleted, 0),
      'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
      'item_links_cleared', COALESCE(v_item_links_cleared, 0),
      'bank_references_cleared', COALESCE(v_bank_references_cleared, 0),
      'chunks_marked_failed', COALESCE(v_chunks_marked_failed, 0),
      'chunks_marked_skipped', COALESCE(v_chunks_marked_skipped, 0),
      'locks_released', COALESCE(v_locks_released, 0),
      'provider_evidence_count', COALESCE(v_provider_evidence_count, 0),
      'provider_review_risk_count', COALESCE(v_provider_review_risk_count, 0),
      'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
      'provider_submit_diagnostic_finalise_result', COALESCE(v_provider_submit_finalise_result, '{}'::jsonb),
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_provider_submit_review_reason_code,
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'manual_resolution_required', COALESCE(v_provider_manual_resolution_required, false),
      'recommended_action', v_provider_recommended_action,
      'safe_retry_available', COALESCE(v_safe_to_retry, false),
      'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
      'unsafe_scope_count', COALESCE(v_unsafe_scope_count, 0),
      'unsafe_transfer_ids', COALESCE(v_unsafe_transfer_ids, '[]'::jsonb),
      'unsafe_reasons', COALESCE(v_unsafe_reasons, '[]'::jsonb)
    )
    ||
    jsonb_build_object(
      'safe_scope_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_scope_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_scope_ids, '[]'::jsonb) END,
      'safe_transfer_ids', CASE WHEN COALESCE(p_dry_run, false) THEN COALESCE(v_safe_transfer_ids, '[]'::jsonb) ELSE COALESCE(v_deleted_transfer_ids, '[]'::jsonb) END,
      'initial_active_auth_request_count', COALESCE(v_initial_active_auth_request_count, 0),
      'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
      'operation_active_auth_request_count', COALESCE(v_operation_active_auth_request_count, 0),
      'active_auth_request_ids', COALESCE(v_active_auth_request_ids, '[]'::jsonb),
      'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
      'awaiting_auth_requests_cancelled', COALESCE(v_awaiting_auth_requests_cancelled, 0),
      'authorised_auth_requests_cancelled', COALESCE(v_authorised_auth_requests_cancelled, 0),
      'auth_request_cleanup_mode', CASE WHEN COALESCE(v_auth_requests_cancelled, 0) > 0 THEN 'CANCELLED_SAFE_LOCAL_AUTH_REQUESTS' WHEN COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN 'AUTH_REQUEST_REVIEW_REQUIRED' ELSE 'NO_AUTH_REQUEST_CLEANUP_REQUIRED' END,
      'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
      'batch_execution_intent_cleared', COALESCE(v_batch_execution_intent_cleared, 0),
      'active_auth_request_blocker_count', COALESCE(v_active_auth_request_blocker_count, 0),
      'authorised_auth_request_review_count', COALESCE(v_authorised_auth_request_review_count, 0),
      'cancellable_auth_request_count', COALESCE(v_cancellable_auth_request_count, 0),
      'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
      'cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb),
      'provider_submit_chunk_attempt_count', COALESCE(v_provider_submit_chunk_attempt_count, 0),
      'stale_empty_provider_submit_chunk_count', COALESCE(v_stale_empty_provider_submit_chunk_count, 0),
      'provider_submit_unknown_chunk_count', COALESCE(v_provider_submit_unknown_chunk_count, 0),
      'batch_execution_boundary_crossed', v_batch_execution_boundary_crossed,
      'execution_commit_state', upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))),
      'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
      'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL,
      'remaining_operation_scope_count', COALESCE(v_remaining_operation_scope_count, 0),
      'remaining_operation_transfer_count', COALESCE(v_remaining_operation_transfer_count, 0)
    )
  );

  IF COALESCE(p_dry_run, false) IS NOT TRUE THEN
    BEGIN
      PERFORM public._audit_insert(
        'banking_pay_operations',
        p_operation_id::text,
        'PAYMENT_EXECUTE_FAILED_LOCAL_ARTIFACT_CLEANUP',
        NULL::jsonb,
        v_result,
        'payment_execute_failed_local_artifact_cleanup',
        v_effective_actor_user_id
      );
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;

  RETURN v_result;
END;
$function$;






















CREATE OR REPLACE FUNCTION public.pay_provider_submit_diagnostic_get(
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_transfer_id uuid DEFAULT NULL::uuid,
  p_chunk_id uuid DEFAULT NULL::uuid,
  p_counts_only boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_effective_pay_batch_id uuid := p_pay_batch_id;
  v_batch_id_from_scope uuid := NULL::uuid;
  v_operation_count integer := 0;
  v_chunk_count integer := 0;
  v_transfer_count integer := 0;
  v_active_auth_request_count integer := 0;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_stale_empty_submit_chunk_count integer := 0;
  v_stale_unresolved_submit_chunk_count integer := 0;
  v_request_sent_no_response_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_accepted_count integer := 0;
  v_provider_submission_blocked_pre_call_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_mixed_provider_submit_outcome boolean := false;
  v_payment_provider_review_required boolean := false;
  v_provider_submit_actual_context boolean := false;
  v_operation_review_required boolean := false;
  v_provider_submission_status text := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
  v_review_reason_code text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_call_stage text := 'NO_PROVIDER_SUBMIT_ATTEMPT';
  v_provider_submission_attempted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_response_received boolean := false;
  v_provider_response_present boolean := false;
  v_provider_submission_accepted boolean := false;
  v_provider_submission_rejected boolean := false;
  v_provider_submission_failed boolean := false;
  v_provider_submission_unknown boolean := false;
  v_provider_acceptance_evidence_present boolean := false;
  v_stale_submit_chunk boolean := false;
  v_unfinalised_submit_chunk boolean := false;
  v_chunk_lock_expired boolean := false;
  v_manual_resolution_required boolean := false;
  v_safe_retry_available boolean := false;
  v_automatic_retry_blocked boolean := false;
  v_retry_blocked_reason text := NULL::text;
  v_recommended_action text := 'No provider submission attempt has been recorded for this scope.';
  v_operation_ids jsonb := '[]'::jsonb;
  v_current_operation_ids jsonb := '[]'::jsonb;
  v_related_operation_ids jsonb := '[]'::jsonb;
  v_diagnostic_operation_id text := NULL::text;
  v_chunk_ids jsonb := '[]'::jsonb;
  v_transfer_ids jsonb := '[]'::jsonb;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_primary_operation_id text := NULL::text;
  v_primary_chunk_id text := NULL::text;
  v_primary_transfer_id text := NULL::text;
  v_primary_transfer_scope_id text := NULL::text;
  v_primary_auth_request_id text := NULL::text;
  v_primary_rail_provider text := NULL::text;
  v_primary_rail_env text := NULL::text;
  v_primary_rail_tx_id text := NULL::text;
  v_primary_rail_state text := NULL::text;
  v_primary_provider_transaction_id text := NULL::text;
  v_primary_provider_reference text := NULL::text;
  v_primary_provider_state text := NULL::text;
  v_primary_request_id text := NULL::text;
  v_primary_idempotency_key text := NULL::text;
  v_primary_local_provider_request_id text := NULL::text;
  v_primary_provider_http_status text := NULL::text;
  v_primary_provider_error_code text := NULL::text;
  v_primary_provider_error_message_redacted text := NULL::text;
  v_primary_provider_response_redacted jsonb := NULL::jsonb;
  v_primary_provider_error_redacted jsonb := NULL::jsonb;
  v_chunk_started_at_utc text := NULL::text;
  v_chunk_completed_at_utc text := NULL::text;
  v_chunk_lock_expires_at_utc text := NULL::text;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_counts jsonb := '{}'::jsonb;
  v_ids jsonb := '{}'::jsonb;
  v_batch_level_cleaned_local_blocked_pre_call_neutralised boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL AND p_operation_id IS NULL AND p_transfer_id IS NULL AND p_chunk_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
      'code', 'IDENTIFIER_REQUIRED',
      'message', 'pay_provider_submit_diagnostic_get: at least one identifier is required'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_pay_batch_id IS NOT NULL THEN
    PERFORM 1 FROM public.pay_batches AS batch_check WHERE batch_check.id = p_pay_batch_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'PAY_BATCH_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: pay batch not found',
        'pay_batch_id', p_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: operation not found',
        'operation_id', p_operation_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: operation does not belong to supplied pay batch',
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_transfer_id IS NOT NULL THEN
    SELECT transfer_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.pay_bank_transfers AS transfer_row
    WHERE transfer_row.id = p_transfer_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: transfer not found',
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to supplied pay batch',
        'transfer_id', p_transfer_id::text,
        'transfer_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT operation_row.pay_batch_id
    INTO v_batch_id_from_scope
    FROM public.banking_pay_operation_chunks AS chunk_row
    JOIN public.banking_pay_operations AS operation_row
      ON operation_row.id = chunk_row.operation_id
    WHERE chunk_row.id = p_chunk_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND',
        'message', 'pay_provider_submit_diagnostic_get: chunk not found',
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
    IF v_effective_pay_batch_id IS NULL THEN
      v_effective_pay_batch_id := v_batch_id_from_scope;
    ELSIF v_batch_id_from_scope IS NOT NULL AND v_effective_pay_batch_id <> v_batch_id_from_scope THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_BATCH_MISMATCH',
        'message', 'pay_provider_submit_diagnostic_get: chunk operation does not belong to supplied pay batch',
        'chunk_id', p_chunk_id::text,
        'chunk_pay_batch_id', v_batch_id_from_scope::text,
        'pay_batch_id', v_effective_pay_batch_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;



  PERFORM set_config('lock_timeout', '3s', true);

  IF p_operation_id IS NOT NULL AND COALESCE(p_counts_only, false) IS TRUE THEN
    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_chunks;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id uuid PRIMARY KEY,
      operation_id uuid NOT NULL,
      pay_batch_id uuid,
      phase text,
      chunk_type text,
      sequence_no integer,
      status text,
      payload_json jsonb,
      result_json jsonb,
      error_json jsonb,
      unit_count integer,
      completed_count integer,
      failed_count integer,
      locked_by text,
      lock_expires_at_utc timestamptz,
      started_at_utc timestamptz,
      completed_at_utc timestamptz,
      created_at_utc timestamptz,
      updated_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_chunks (
      chunk_id,
      operation_id,
      pay_batch_id,
      phase,
      chunk_type,
      sequence_no,
      status,
      payload_json,
      result_json,
      error_json,
      unit_count,
      completed_count,
      failed_count,
      locked_by,
      lock_expires_at_utc,
      started_at_utc,
      completed_at_utc,
      created_at_utc,
      updated_at_utc
    )
    SELECT chunk_row.id,
           chunk_row.operation_id,
           v_effective_pay_batch_id,
           chunk_row.phase,
           chunk_row.chunk_type,
           chunk_row.sequence_no,
           chunk_row.status,
           COALESCE(chunk_row.payload_json, '{}'::jsonb),
           chunk_row.result_json,
           chunk_row.error_json,
           chunk_row.unit_count,
           chunk_row.completed_count,
           chunk_row.failed_count,
           chunk_row.locked_by,
           chunk_row.lock_expires_at_utc,
           chunk_row.started_at_utc,
           chunk_row.completed_at_utc,
           chunk_row.created_at_utc,
           chunk_row.updated_at_utc
    FROM public.banking_pay_operation_chunks AS chunk_row
    WHERE chunk_row.operation_id = p_operation_id
      AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
      AND (p_chunk_id IS NULL OR chunk_row.id = p_chunk_id)
    ORDER BY chunk_row.sequence_no, chunk_row.created_at_utc NULLS FIRST, chunk_row.id
    ON CONFLICT (chunk_id) DO NOTHING;

    IF p_chunk_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_chunks AS exact_chunk_check
      WHERE exact_chunk_check.chunk_id = p_chunk_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'CHUNK_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: chunk does not belong to supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfer_ids;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfer_ids (
      transfer_id uuid PRIMARY KEY
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT operation_scope.pay_bank_transfer_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE p_chunk_id IS NULL
      AND operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND operation_scope.pay_bank_transfer_id IS NOT NULL
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT transfer_row.id
    FROM public.pay_bank_transfers AS transfer_row
    WHERE p_chunk_id IS NOT NULL
      AND p_transfer_id IS NOT NULL
      AND transfer_row.id = p_transfer_id
      AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
      AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
        WHERE operation_scope_check.operation_id = p_operation_id
          AND (v_effective_pay_batch_id IS NULL OR operation_scope_check.pay_batch_id = v_effective_pay_batch_id)
          AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
      )
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfer_ids (transfer_id)
    SELECT DISTINCT transfer_uuid.transfer_id
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    CROSS JOIN LATERAL (
      SELECT transfer_id_element.value AS transfer_id_text
      FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_id_element(value)
      UNION ALL
      SELECT COALESCE(transfer_payload.value->>'pay_bank_transfer_id', transfer_payload.value->>'transfer_id', transfer_payload.value->>'id') AS transfer_id_text
      FROM jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_payload(value)
    ) AS transfer_text
    CROSS JOIN LATERAL (
      SELECT transfer_text.transfer_id_text::uuid AS transfer_id
      WHERE NULLIF(BTRIM(COALESCE(transfer_text.transfer_id_text, '')), '') ~* v_uuid_regex
    ) AS transfer_uuid
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = transfer_uuid.transfer_id
     AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
    WHERE p_transfer_id IS NULL OR transfer_uuid.transfer_id = p_transfer_id
    ON CONFLICT DO NOTHING;

    IF p_transfer_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_check
      WHERE exact_transfer_check.transfer_id = p_transfer_id
    ) THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_PROVIDER_SUBMIT_DIAGNOSTIC_GET',
        'code', 'TRANSFER_NOT_FOUND_FOR_OPERATION',
        'message', 'pay_provider_submit_diagnostic_get: transfer does not belong to the supplied operation/provider-submit scope',
        'operation_id', p_operation_id::text,
        'transfer_id', p_transfer_id::text
      )::text USING ERRCODE = 'P0001';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_transfers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id uuid PRIMARY KEY,
      pay_batch_id uuid NOT NULL,
      status text,
      rail_provider text,
      rail_env text,
      request_id text,
      rail_tx_id text,
      rail_state text,
      rail_meta_json jsonb,
      payment_reference text,
      created_at_utc timestamptz
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_transfers (
      transfer_id,
      pay_batch_id,
      status,
      rail_provider,
      rail_env,
      request_id,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      payment_reference,
      created_at_utc
    )
    SELECT transfer_row.id,
           transfer_row.pay_batch_id,
           transfer_row.status,
           transfer_row.rail_provider,
           transfer_row.rail_env,
           transfer_row.request_id,
           transfer_row.rail_tx_id,
           transfer_row.rail_state,
           COALESCE(transfer_row.rail_meta_json, '{}'::jsonb),
           transfer_row.payment_reference,
           transfer_row.created_at_utc
    FROM public.pay_bank_transfers AS transfer_row
    JOIN pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_id
      ON exact_transfer_id.transfer_id = transfer_row.id
    WHERE v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id
    ON CONFLICT (transfer_id) DO NOTHING;

    DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_exact_markers;
    CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_exact_markers (
      source_kind text NOT NULL,
      source_id text,
      chunk_id uuid,
      transfer_id uuid,
      provider_submission_status text,
      review_reason_code text,
      provider_request_sent boolean NOT NULL DEFAULT false,
      provider_response_present boolean NOT NULL DEFAULT false,
      provider_response_received boolean NOT NULL DEFAULT false,
      provider_accepted boolean NOT NULL DEFAULT false,
      provider_rejected boolean NOT NULL DEFAULT false,
      provider_unknown boolean NOT NULL DEFAULT false,
      provider_malformed boolean NOT NULL DEFAULT false,
      provider_blocked_pre_call boolean NOT NULL DEFAULT false,
      unfinalised_submit_chunk boolean NOT NULL DEFAULT false,
      marker_json jsonb NOT NULL DEFAULT '{}'::jsonb
    ) ON COMMIT DROP;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'chunk_diagnostic'::text,
           selected_chunk.chunk_id::text,
           selected_chunk.chunk_id,
           exact_chunk_transfer.transfer_id,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'outcome_code', ''))),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))),
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_called', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_request_dispatched_at_utc', chunk_diag.provider_submit_diagnostic->>'request_sent_at_utc', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', chunk_diag.provider_submit_diagnostic->>'provider_http_status', chunk_diag.provider_submit_diagnostic->>'provider_error_code', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'response_received_at_utc', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_acceptance_evidence_count', chunk_diag.provider_submit_diagnostic->>'providerAcceptanceEvidenceCount', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'rail_tx_id', chunk_diag.provider_submit_diagnostic->>'provider_transaction_id', chunk_diag.provider_submit_diagnostic->>'provider_payment_id', chunk_diag.provider_submit_diagnostic->>'provider_reference', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_rejection_count', chunk_diag.provider_submit_diagnostic->>'providerRejectionCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_rejected_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionRejectedCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerUnknownCount', chunk_diag.provider_submit_diagnostic->>'provider_submission_unknown_count', chunk_diag.provider_submit_diagnostic->>'providerSubmissionUnknownCount', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(chunk_diag.provider_submit_diagnostic->>'provider_submission_status', chunk_diag.provider_submit_diagnostic->>'review_reason_code', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc <= v_now),
           jsonb_strip_nulls(COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) || jsonb_build_object('chunk_id', selected_chunk.chunk_id::text))
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk
    LEFT JOIN LATERAL (
      SELECT COALESCE(
        CASE WHEN jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        CASE WHEN jsonb_typeof(selected_chunk.payload_json->'provider_submit_diagnostic') = 'object' THEN selected_chunk.payload_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
        '{}'::jsonb
      ) AS provider_submit_diagnostic
    ) AS chunk_diag ON true
    LEFT JOIN LATERAL (
      SELECT exact_transfer.transfer_id
      FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer
      ORDER BY exact_transfer.transfer_id
      LIMIT 1
    ) AS exact_chunk_transfer ON true
    WHERE COALESCE(chunk_diag.provider_submit_diagnostic, '{}'::jsonb) <> '{}'::jsonb
       OR upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING';

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_meta'::text,
           selected_transfer.transfer_id::text,
           NULL::uuid,
           selected_transfer.transfer_id,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))),
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,request_sent_at_utc}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') IS NOT NULL,
           lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0
             OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_rejection_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerRejectionCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerUnknownCount}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) || jsonb_build_object('transfer_id', selected_transfer.transfer_id::text))
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
    WHERE COALESCE(selected_transfer.rail_meta_json->'provider_submit_diagnostic', '{}'::jsonb) <> '{}'::jsonb
       OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, selected_transfer.rail_state, '')), '') IS NOT NULL;

    INSERT INTO pg_temp.tmp_provider_submit_exact_markers (
      source_kind,
      source_id,
      chunk_id,
      transfer_id,
      provider_submission_status,
      review_reason_code,
      provider_request_sent,
      provider_response_present,
      provider_response_received,
      provider_accepted,
      provider_rejected,
      provider_unknown,
      provider_malformed,
      provider_blocked_pre_call,
      unfinalised_submit_chunk,
      marker_json
    )
    SELECT 'transfer_event'::text,
           transfer_event.id::text,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))),
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent}', transfer_event.raw_payload #>> '{provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', transfer_event.raw_payload #>> '{provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_called}', transfer_event.raw_payload #>> '{provider_called}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_request_dispatched_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_sent_at_utc}', transfer_event.raw_payload #>> '{request_sent_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_present}', transfer_event.raw_payload #>> '{provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_http_status}', transfer_event.raw_payload #>> '{provider_http_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_error_code}', transfer_event.raw_payload #>> '{provider_error_code}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_response_received}', transfer_event.raw_payload #>> '{provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,response_received_at_utc}', transfer_event.raw_payload #>> '{response_received_at_utc}', '')), '') IS NOT NULL,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT', 'SUBMITTED', 'SENT', 'PROCESSING', 'PENDING', 'COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_accepted}', transfer_event.raw_payload #>> '{provider_submission_accepted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerAcceptanceEvidenceCount}', transfer_event.raw_payload #>> '{provider_acceptance_evidence_count}', transfer_event.raw_payload #>> '{providerAcceptanceEvidenceCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED', 'FAILED', 'ERROR')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected}', transfer_event.raw_payload #>> '{provider_submission_rejected}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_rejection_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerRejectionCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_rejected_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionRejectedCount}', transfer_event.raw_payload #>> '{provider_rejection_count}', transfer_event.raw_payload #>> '{providerRejectionCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_REQUEST_SENT_NO_RESPONSE')
             OR lower(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown}', transfer_event.raw_payload #>> '{provider_submission_unknown}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
             OR CASE WHEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0')) ~ '^[0-9]+$' THEN BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerUnknownCount}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_unknown_count}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,providerSubmissionUnknownCount}', transfer_event.raw_payload #>> '{provider_unknown_count}', transfer_event.raw_payload #>> '{providerUnknownCount}', '0'))::integer ELSE 0 END > 0,
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED'),
           upper(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,review_reason_code}', transfer_event.raw_payload #>> '{review_reason_code}', ''))) IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'),
           false,
           jsonb_strip_nulls(COALESCE(transfer_event.raw_payload, '{}'::jsonb) || jsonb_build_object(
             'pay_bank_transfer_event_id', transfer_event.id::text,
             'event_source', transfer_event.event_source,
             'normalised_state', transfer_event.normalised_state,
             'provider_state', transfer_event.provider_state
           ))
    FROM public.pay_bank_transfer_events AS transfer_event
    JOIN pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer
      ON selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
    WHERE transfer_event.pay_bank_transfer_id IS NOT NULL;

    SELECT COUNT(*)::integer INTO v_operation_count FROM public.banking_pay_operations AS exact_operation WHERE exact_operation.id = p_operation_id;
    SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;
    SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_accepted)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_request_sent OR marker.provider_response_present OR marker.provider_response_received)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_unknown)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_rejected)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_blocked_pre_call)::integer,
           COUNT(DISTINCT COALESCE(marker.transfer_id::text, marker.chunk_id::text, marker.source_id)) FILTER (WHERE marker.provider_malformed)::integer,
           COUNT(DISTINCT marker.chunk_id) FILTER (WHERE marker.unfinalised_submit_chunk)::integer,
           COALESCE(BOOL_OR(marker.unfinalised_submit_chunk), false)
    INTO v_provider_acceptance_evidence_count,
         v_provider_response_present_count,
         v_provider_request_sent_count,
         v_provider_submission_unknown_count,
         v_provider_submission_rejected_count,
         v_provider_submission_blocked_pre_call_count,
         v_provider_submission_malformed_response_count,
         v_unfinalised_submit_chunk_count,
         v_chunk_lock_expired
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker;

    v_provider_submission_accepted_count := COALESCE(v_provider_acceptance_evidence_count, 0);
    v_stale_unresolved_submit_chunk_count := CASE
      WHEN COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_unfinalised_submit_chunk_count
      ELSE 0
    END;
    v_stale_empty_submit_chunk_count := v_stale_unresolved_submit_chunk_count;
    v_request_sent_no_response_count := CASE
      WHEN COALESCE(v_provider_request_sent_count, 0) > 0
        AND COALESCE(v_provider_response_present_count, 0) = 0
        AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 THEN v_provider_request_sent_count
      ELSE 0
    END;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.sequence_no NULLS LAST, selected_chunk.created_at_utc NULLS FIRST, selected_chunk.chunk_id), '[]'::jsonb),
           MIN(selected_chunk.chunk_id::text),
           MIN(selected_chunk.started_at_utc)::text,
           MIN(selected_chunk.completed_at_utc)::text,
           MIN(selected_chunk.lock_expires_at_utc)::text
    INTO v_chunk_ids,
         v_primary_chunk_id,
         v_chunk_started_at_utc,
         v_chunk_completed_at_utc,
         v_chunk_lock_expires_at_utc
    FROM pg_temp.tmp_provider_submit_exact_chunks AS selected_chunk;

    SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
           MIN(selected_transfer.transfer_id::text),
           MIN(selected_transfer.rail_provider),
           MIN(selected_transfer.rail_env),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
           MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
    INTO v_transfer_ids,
         v_primary_transfer_id,
         v_primary_rail_provider,
         v_primary_rail_env,
         v_primary_rail_tx_id,
         v_primary_rail_state,
         v_primary_request_id
    FROM pg_temp.tmp_provider_submit_exact_transfers AS selected_transfer;

    SELECT COALESCE(jsonb_agg(to_jsonb(operation_scope.id::text) ORDER BY operation_scope.id), '[]'::jsonb),
           MIN(operation_scope.id::text)
    INTO v_transfer_scope_ids,
         v_primary_transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.operation_id = p_operation_id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
      AND (p_transfer_id IS NULL OR operation_scope.pay_bank_transfer_id = p_transfer_id)
      AND (
        p_chunk_id IS NULL
        OR EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_exact_transfer_ids AS exact_transfer_scope
          WHERE exact_transfer_scope.transfer_id = operation_scope.pay_bank_transfer_id
        )
      );

    SELECT COUNT(*)::integer,
           COALESCE(jsonb_agg(to_jsonb(auth_request.id::text) ORDER BY auth_request.created_at_utc NULLS LAST, auth_request.id), '[]'::jsonb),
           MIN(auth_request.id::text)
    INTO v_active_auth_request_count,
         v_auth_request_ids,
         v_primary_auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text;

    v_diagnostic_operation_id := p_operation_id::text;
    v_primary_operation_id := p_operation_id::text;
    v_current_operation_ids := jsonb_build_array(p_operation_id::text);
    v_related_operation_ids := '[]'::jsonb;
    v_operation_ids := jsonb_build_array(p_operation_id::text);

    SELECT marker.marker_json->>'provider_transaction_id',
           marker.marker_json->>'provider_reference',
           marker.marker_json->>'provider_state',
           COALESCE(marker.marker_json->>'request_id', v_primary_request_id),
           COALESCE(marker.marker_json->>'idempotency_key', v_primary_request_id),
           marker.marker_json->>'local_provider_request_id',
           marker.marker_json->>'provider_http_status',
           marker.marker_json->>'provider_error_code',
           marker.marker_json->>'provider_error_message_redacted',
           marker.marker_json->'provider_response_redacted',
           marker.marker_json->'provider_error_redacted'
    INTO v_primary_provider_transaction_id,
         v_primary_provider_reference,
         v_primary_provider_state,
         v_primary_request_id,
         v_primary_idempotency_key,
         v_primary_local_provider_request_id,
         v_primary_provider_http_status,
         v_primary_provider_error_code,
         v_primary_provider_error_message_redacted,
         v_primary_provider_response_redacted,
         v_primary_provider_error_redacted
    FROM pg_temp.tmp_provider_submit_exact_markers AS marker
    WHERE marker.provider_accepted OR marker.provider_rejected OR marker.provider_response_present OR marker.provider_request_sent
    ORDER BY CASE WHEN marker.provider_accepted THEN 0 WHEN marker.provider_rejected THEN 1 WHEN marker.provider_response_present THEN 2 ELSE 3 END,
             marker.source_kind,
             marker.source_id
    LIMIT 1;

    v_provider_submit_actual_context := COALESCE(v_chunk_count, 0) > 0
      OR COALESCE(v_transfer_count, 0) > 0
      OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      OR COALESCE(v_provider_response_present_count, 0) > 0
      OR COALESCE(v_provider_request_sent_count, 0) > 0
      OR COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;

    v_mixed_provider_submit_outcome := COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      AND (
        COALESCE(v_provider_submission_rejected_count, 0) > 0
        OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
        OR COALESCE(v_provider_submission_unknown_count, 0) > 0
        OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        OR COALESCE(v_request_sent_no_response_count, 0) > 0
        OR COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
      );

    IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
      v_review_reason_code := CASE WHEN v_mixed_provider_submit_outcome THEN 'MIXED_PROVIDER_SUBMIT_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_accepted := true;
      v_provider_acceptance_evidence_present := true;
      v_manual_resolution_required := COALESCE(v_mixed_provider_submit_outcome, false);
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := CASE WHEN v_mixed_provider_submit_outcome THEN 'PROVIDER_SUBMISSION_MIXED_OUTCOME' ELSE 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT' END;
      v_recommended_action := CASE WHEN v_mixed_provider_submit_outcome THEN 'Provider acceptance evidence exists for at least one transfer, but not all outcomes are resolved. Reconcile before retry.' ELSE 'Provider acceptance evidence exists. Do not retry unless reconciled.' END;
    ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
      v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
      v_provider_call_stage := 'PROVIDER_RESPONSE_RECEIVED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_rejected := true;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_REJECTED';
      v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
    ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
      v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := true;
      v_provider_response_present := true;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
      v_recommended_action := 'Provider returned an unusable response. Check bank records before retry.';
    ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0 OR COALESCE(v_request_sent_no_response_count, 0) > 0 OR (COALESCE(v_provider_request_sent_count, 0) > 0 AND COALESCE(v_provider_response_present_count, 0) = 0) THEN
      v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
      v_provider_submission_attempted := true;
      v_provider_request_sent := true;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_unknown := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check bank records before retry.';
    ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_call_stage := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
      v_provider_submission_unknown := true;
      v_stale_submit_chunk := true;
      v_unfinalised_submit_chunk := true;
      v_manual_resolution_required := true;
      v_safe_retry_available := false;
      v_automatic_retry_blocked := true;
      v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
      v_recommended_action := 'Check bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
    ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
      v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_provider_submission_failed := true;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_retry_blocked_reason := NULL::text;
      v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
    ELSE
      v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
      v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
      v_provider_submission_attempted := false;
      v_provider_request_sent := false;
      v_provider_response_received := false;
      v_provider_response_present := false;
      v_manual_resolution_required := false;
      v_safe_retry_available := true;
      v_recommended_action := 'No provider submission attempt has been recorded for this scope.';
    END IF;

    v_payment_provider_review_required := COALESCE(v_provider_submit_actual_context, false) IS TRUE
      AND v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_ACCEPTED',
        'PROVIDER_SUBMISSION_REJECTED',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
      );

    v_counts := jsonb_build_object(
      'operation_count', COALESCE(v_operation_count, 0),
      'chunk_count', COALESCE(v_chunk_count, 0),
      'transfer_count', COALESCE(v_transfer_count, 0),
      'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
      'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
    );

    v_ids := jsonb_build_object(
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
      'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
    );

    v_provider_submit_diagnostic := jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'EXACT_OPERATION_COUNTS_ONLY',
      'generated_at_utc', v_now::text,
      'review_reason_code', v_review_reason_code,
      'provider_submission_status', v_provider_submission_status,
      'provider_call_stage', v_provider_call_stage,
      'provider_submission_attempted', v_provider_submission_attempted,
      'provider_request_sent', v_provider_request_sent,
      'provider_response_received', v_provider_response_received,
      'provider_response_present', v_provider_response_present,
      'provider_submission_accepted', v_provider_submission_accepted,
      'provider_submission_rejected', v_provider_submission_rejected,
      'provider_submission_failed', v_provider_submission_failed,
      'provider_submission_unknown', v_provider_submission_unknown,
      'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'stale_submit_chunk', v_stale_submit_chunk,
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
      'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
      'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
      'chunk_started_at_utc', v_chunk_started_at_utc,
      'chunk_completed_at_utc', v_chunk_completed_at_utc,
      'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'automatic_retry_blocked', v_automatic_retry_blocked,
      'retry_blocked_reason', v_retry_blocked_reason,
      'recommended_action', v_recommended_action
    )
    || jsonb_build_object(
      'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
      'operation_id', v_diagnostic_operation_id,
      'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
      'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
      'chunk_id', v_primary_chunk_id,
      'chunk_ids', v_chunk_ids,
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', v_transfer_ids,
      'transfer_scope_id', v_primary_transfer_scope_id,
      'transfer_scope_ids', v_transfer_scope_ids,
      'auth_request_id', v_primary_auth_request_id,
      'auth_request_ids', v_auth_request_ids,
      'rail_provider', v_primary_rail_provider,
      'rail_env', v_primary_rail_env,
      'rail_tx_id', v_primary_rail_tx_id,
      'rail_state', v_primary_rail_state,
      'provider_transaction_id', v_primary_provider_transaction_id,
      'provider_reference', v_primary_provider_reference,
      'provider_state', v_primary_provider_state,
      'request_id', v_primary_request_id,
      'idempotency_key', v_primary_idempotency_key,
      'local_provider_request_id', v_primary_local_provider_request_id,
      'provider_http_status', v_primary_provider_http_status,
      'provider_error_code', v_primary_provider_error_code,
      'provider_error_message_redacted', v_primary_provider_error_message_redacted,
      'provider_response_redacted', v_primary_provider_response_redacted,
      'provider_error_redacted', v_primary_provider_error_redacted
    );
    RETURN jsonb_build_object(
      'ok', true,
      'provider_submit_diagnostic', v_provider_submit_diagnostic,
      'provider_submission_status', v_provider_submission_status,
      'review_reason_code', v_review_reason_code,
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
      'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
      'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
      'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available,
      'recommended_action', v_recommended_action,
      'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
      'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
      'counts', v_counts,
      'ids', v_ids,
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
      'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
      'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
      'counts_only', true,
      'exact_scope_mode', true
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_operations;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunks;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfers;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_sources;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_transfer_flags;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_diagnostic_chunk_flags;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id uuid PRIMARY KEY,
    pay_batch_id uuid,
    operation_status text,
    operation_phase text,
    progress_json jsonb,
    result_json jsonb,
    error_json jsonb,
    created_at_utc timestamptz,
    updated_at_utc timestamptz
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_operations (
    operation_id,
    pay_batch_id,
    operation_status,
    operation_phase,
    progress_json,
    result_json,
    error_json,
    created_at_utc,
    updated_at_utc
  )
  SELECT operation_row.id,
         operation_row.pay_batch_id,
         operation_row.status,
         operation_row.phase,
         COALESCE(operation_row.progress_json, '{}'::jsonb),
         operation_row.result_json,
         operation_row.error_json,
         operation_row.created_at_utc,
         operation_row.updated_at_utc
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (
      (p_operation_id IS NOT NULL AND operation_row.id = p_operation_id)
      OR (v_effective_pay_batch_id IS NOT NULL AND operation_row.pay_batch_id = v_effective_pay_batch_id)
      OR (p_chunk_id IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_chunks AS chunk_filter
        WHERE chunk_filter.id = p_chunk_id
          AND chunk_filter.operation_id = operation_row.id
      ))
    )
  ON CONFLICT (operation_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id uuid PRIMARY KEY,
    operation_id uuid NOT NULL,
    pay_batch_id uuid,
    phase text NOT NULL,
    chunk_type text NOT NULL,
    sequence_no integer NOT NULL,
    status text NOT NULL,
    payload_json jsonb NOT NULL,
    result_json jsonb,
    error_json jsonb,
    unit_count integer NOT NULL,
    completed_count integer NOT NULL,
    failed_count integer NOT NULL,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz NOT NULL,
    started_at_utc timestamptz,
    completed_at_utc timestamptz,
    updated_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunks (
    chunk_id,
    operation_id,
    pay_batch_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  SELECT chunk_row.id,
         chunk_row.operation_id,
         operation_row.pay_batch_id,
         chunk_row.phase,
         chunk_row.chunk_type,
         chunk_row.sequence_no,
         chunk_row.status,
         COALESCE(chunk_row.payload_json, '{}'::jsonb),
         chunk_row.result_json,
         chunk_row.error_json,
         chunk_row.unit_count,
         chunk_row.completed_count,
         chunk_row.failed_count,
         chunk_row.locked_by,
         chunk_row.lock_expires_at_utc,
         chunk_row.created_at_utc,
         chunk_row.started_at_utc,
         chunk_row.completed_at_utc,
         chunk_row.updated_at_utc
  FROM public.banking_pay_operation_chunks AS chunk_row
  JOIN public.banking_pay_operations AS operation_row
    ON operation_row.id = chunk_row.operation_id
  WHERE operation_row.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
    AND (chunk_row.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR chunk_row.chunk_type = 'TRANSFER_SUBMIT')
    AND (
      (p_chunk_id IS NOT NULL AND chunk_row.id = p_chunk_id)
      OR (p_operation_id IS NOT NULL AND chunk_row.operation_id = p_operation_id)
      OR EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
        WHERE selected_operation.operation_id = chunk_row.operation_id
      )
    )
  ON CONFLICT (chunk_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (
    chunk_id uuid NOT NULL,
    transfer_id uuid NOT NULL,
    PRIMARY KEY (chunk_id, transfer_id)
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids'
      ELSE '[]'::jsonb
    END
  ) AS transfer_id_text(value)
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_id_text.value::uuid
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers'
      ELSE '[]'::jsonb
    END
  ) AS transfer_payload(value)
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
      NULLIF(BTRIM(COALESCE(transfer_payload.value->>'transfer_id', '')), '')
    ) AS value
  ) AS transfer_id_text
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id uuid PRIMARY KEY,
    pay_batch_id uuid NOT NULL,
    status text NOT NULL,
    rail_provider text NOT NULL,
    rail_env text NOT NULL,
    request_id text,
    rail_tx_id text,
    rail_state text,
    rail_meta_json jsonb,
    payment_reference text,
    created_at_utc timestamptz NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfers (
    transfer_id,
    pay_batch_id,
    status,
    rail_provider,
    rail_env,
    request_id,
    rail_tx_id,
    rail_state,
    rail_meta_json,
    payment_reference,
    created_at_utc
  )
  SELECT transfer_row.id,
         transfer_row.pay_batch_id,
         transfer_row.status,
         transfer_row.rail_provider,
         transfer_row.rail_env,
         transfer_row.request_id,
         transfer_row.rail_tx_id,
         transfer_row.rail_state,
         transfer_row.rail_meta_json,
         transfer_row.payment_reference,
         transfer_row.created_at_utc
  FROM public.pay_bank_transfers AS transfer_row
  WHERE (p_transfer_id IS NOT NULL AND transfer_row.id = p_transfer_id)
     OR EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
       WHERE selected_chunk_transfer.transfer_id = transfer_row.id
     )
     OR (
       p_transfer_id IS NULL
       AND p_chunk_id IS NULL
       AND v_effective_pay_batch_id IS NOT NULL
       AND transfer_row.pay_batch_id = v_effective_pay_batch_id
     )
  ON CONFLICT (transfer_id) DO NOTHING;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type text NOT NULL,
    operation_id uuid,
    chunk_id uuid,
    transfer_id uuid,
    event_id uuid,
    diagnostic jsonb NOT NULL,
    provider_submission_status text,
    review_reason_code text,
    provider_call_stage text,
    provider_submission_attempted boolean NOT NULL DEFAULT false,
    provider_request_sent boolean NOT NULL DEFAULT false,
    provider_response_received boolean NOT NULL DEFAULT false,
    provider_response_present boolean NOT NULL DEFAULT false,
    provider_submission_accepted boolean NOT NULL DEFAULT false,
    provider_submission_rejected boolean NOT NULL DEFAULT false,
    provider_submission_failed boolean NOT NULL DEFAULT false,
    provider_submission_unknown boolean NOT NULL DEFAULT false,
    provider_acceptance_evidence_present boolean NOT NULL DEFAULT false,
    manual_resolution_required boolean NOT NULL DEFAULT false,
    safe_retry_available boolean NOT NULL DEFAULT false,
    provider_http_status text,
    provider_error_code text,
    provider_error_message_redacted text,
    provider_transaction_id text,
    provider_reference text,
    provider_state text,
    rail_tx_id text,
    rail_state text,
    request_id text,
    idempotency_key text,
    local_provider_request_id text,
    provider_response_redacted jsonb,
    provider_error_redacted jsonb
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_sources (
    source_type,
    operation_id,
    chunk_id,
    transfer_id,
    event_id,
    diagnostic,
    provider_submission_status,
    review_reason_code,
    provider_call_stage,
    provider_submission_attempted,
    provider_request_sent,
    provider_response_received,
    provider_response_present,
    provider_submission_accepted,
    provider_submission_rejected,
    provider_submission_failed,
    provider_submission_unknown,
    provider_acceptance_evidence_present,
    manual_resolution_required,
    safe_retry_available,
    provider_http_status,
    provider_error_code,
    provider_error_message_redacted,
    provider_transaction_id,
    provider_reference,
    provider_state,
    rail_tx_id,
    rail_state,
    request_id,
    idempotency_key,
    local_provider_request_id,
    provider_response_redacted,
    provider_error_redacted
  )
  WITH raw_diagnostics AS (
    SELECT 'operation_progress'::text AS source_type,
           selected_operation.operation_id,
           NULL::uuid AS chunk_id,
           NULL::uuid AS transfer_id,
           NULL::uuid AS event_id,
           selected_operation.progress_json->'provider_submit_diagnostic' AS diagnostic
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.progress_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_result'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'operation_error'::text,
           selected_operation.operation_id,
           NULL::uuid,
           NULL::uuid,
           NULL::uuid,
           selected_operation.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
    WHERE jsonb_typeof(selected_operation.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_result'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.result_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.result_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'chunk_error'::text,
           selected_chunk.operation_id,
           selected_chunk.chunk_id,
           selected_chunk_transfer.transfer_id,
           NULL::uuid,
           selected_chunk.error_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    WHERE jsonb_typeof(selected_chunk.error_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_meta'::text,
           NULL::uuid,
           NULL::uuid,
           selected_transfer.transfer_id,
           NULL::uuid,
           selected_transfer.rail_meta_json->'provider_submit_diagnostic'
    FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
    WHERE jsonb_typeof(selected_transfer.rail_meta_json->'provider_submit_diagnostic') = 'object'
    UNION ALL
    SELECT 'transfer_event'::text,
           NULL::uuid,
           NULL::uuid,
           transfer_event.pay_bank_transfer_id,
           transfer_event.id,
           transfer_event.raw_payload->'provider_submit_diagnostic'
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE jsonb_typeof(transfer_event.raw_payload->'provider_submit_diagnostic') = 'object'
      AND EXISTS (
        SELECT 1
        FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
        WHERE selected_transfer.transfer_id = transfer_event.pay_bank_transfer_id
      )
  )
  SELECT raw_diagnostics.source_type,
         raw_diagnostics.operation_id,
         raw_diagnostics.chunk_id,
         raw_diagnostics.transfer_id,
         raw_diagnostics.event_id,
         raw_diagnostics.diagnostic,
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_status', raw_diagnostics.diagnostic->>'outcome_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'review_reason_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_call_stage', '')), ''),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_attempted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_response_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_accepted', raw_diagnostics.diagnostic->>'provider_accepted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_rejected', raw_diagnostics.diagnostic->>'provider_rejected', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_failed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_submission_unknown', raw_diagnostics.diagnostic->>'provider_unknown', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         lower(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'safe_retry_available', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_http_status', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_code', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_error_message_redacted', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_transaction_id', raw_diagnostics.diagnostic->>'provider_payment_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_reference', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'provider_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_tx_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'rail_state', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'request_id', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'idempotency_key', '')), ''),
         NULLIF(BTRIM(COALESCE(raw_diagnostics.diagnostic->>'local_provider_request_id', '')), ''),
         raw_diagnostics.diagnostic->'provider_response_redacted',
         raw_diagnostics.diagnostic->'provider_error_redacted'
  FROM raw_diagnostics
  WHERE jsonb_typeof(raw_diagnostics.diagnostic) = 'object'
    AND raw_diagnostics.diagnostic <> '{}'::jsonb;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_transfer_flags (
    transfer_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response
  )
  SELECT selected_transfer.transfer_id,
         (
           (
             NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
             AND UPPER(BTRIM(COALESCE(selected_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
           )
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> selected_transfer.transfer_id::text
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
             AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             AND selected_source.provider_submission_rejected IS NOT TRUE
             AND selected_source.provider_submission_failed IS NOT TRUE
             AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
           ), false)
           OR COALESCE(BOOL_OR(
                upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
                AND upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
                AND EXISTS (
                  SELECT 1
                  FROM (VALUES
                    (transfer_event.provider_event_id),
                    (transfer_event.provider_reference),
                    (transfer_event.raw_payload #>> '{provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{payment_id}'),
                    (transfer_event.raw_payload #>> '{external_payment_id}'),
                    (transfer_event.raw_payload #>> '{revolut_payment_id}'),
                    (transfer_event.raw_payload #>> '{rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                    (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
                  ) AS provider_identifier(identifier_value)
                  WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> selected_transfer.transfer_id::text
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''), '__NO_REQUEST_ID__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_transfer.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
                    AND NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), ''), '__NO_EVENT_IDEMPOTENCY_KEY__')
                )
              ), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
         ),
         (
           COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
           OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME')), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false)
           OR NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '') IS NOT NULL
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
           OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')), false)
           OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
           OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           OR COALESCE(BOOL_OR(
             upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'NO_PROVIDER_SUBMISSION_ATTEMPTED'
             AND selected_source.provider_submission_attempted IS FALSE
             AND selected_source.provider_request_sent IS FALSE
             AND selected_source.provider_response_received IS FALSE
             AND selected_source.provider_response_present IS FALSE
           ), false)
         ),
         (
           COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
         )
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
    ON selected_source.transfer_id = selected_transfer.transfer_id
  LEFT JOIN public.pay_bank_transfer_events AS transfer_event
    ON transfer_event.pay_bank_transfer_id = selected_transfer.transfer_id
  GROUP BY selected_transfer.transfer_id,
           selected_transfer.request_id,
           selected_transfer.payment_reference,
           selected_transfer.rail_tx_id
  ON CONFLICT (transfer_id) DO NOTHING;

  UPDATE pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag_update
  SET has_provider_unknown = true
  WHERE transfer_flag_update.has_provider_request_sent IS TRUE
    AND transfer_flag_update.has_provider_response IS NOT TRUE
    AND transfer_flag_update.has_provider_acceptance_evidence IS NOT TRUE;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id uuid PRIMARY KEY,
    has_provider_acceptance_evidence boolean NOT NULL DEFAULT false,
    has_provider_response boolean NOT NULL DEFAULT false,
    has_provider_request_sent boolean NOT NULL DEFAULT false,
    has_provider_rejection boolean NOT NULL DEFAULT false,
    has_provider_unknown boolean NOT NULL DEFAULT false,
    has_provider_blocked_pre_call boolean NOT NULL DEFAULT false,
    has_provider_malformed_response boolean NOT NULL DEFAULT false,
    has_durable_provider_request_impossible boolean NOT NULL DEFAULT false,
    is_stale_unresolved boolean NOT NULL DEFAULT false,
    is_stale_request_sent_no_response boolean NOT NULL DEFAULT false,
    is_stale_claim_or_pre_call_only boolean NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_diagnostic_chunk_flags (
    chunk_id,
    has_provider_acceptance_evidence,
    has_provider_response,
    has_provider_request_sent,
    has_provider_rejection,
    has_provider_unknown,
    has_provider_blocked_pre_call,
    has_provider_malformed_response,
    has_durable_provider_request_impossible,
    is_stale_unresolved,
    is_stale_request_sent_no_response,
    is_stale_claim_or_pre_call_only
  )
  SELECT chunk_eval.chunk_id,
         chunk_eval.has_provider_acceptance_evidence,
         chunk_eval.has_provider_response,
         chunk_eval.has_provider_request_sent,
         chunk_eval.has_provider_rejection,
         chunk_eval.has_provider_unknown OR (chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent),
         chunk_eval.has_provider_blocked_pre_call,
         chunk_eval.has_provider_malformed_response,
         chunk_eval.has_durable_provider_request_impossible,
         chunk_eval.is_stale_unresolved,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent,
         chunk_eval.is_stale_unresolved AND chunk_eval.has_provider_request_sent IS NOT TRUE
  FROM (
    SELECT selected_chunk.chunk_id,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
             OR COALESCE(BOOL_OR(
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.chunk_id IS NULL THEN NULL::text ELSE selected_source.chunk_id::text END, '__NO_SOURCE_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ), false)
           ) AS has_provider_acceptance_evidence,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
           ) AS has_provider_response,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_request_sent), false)
             OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE')), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_call_stage, ''))) IN ('PROVIDER_PAYMENT_CREATE_REQUEST_SENT', 'PROVIDER_PAYMENT_CREATE_RESPONSE_RECEIVED', 'PROVIDER_PAYMENT_CREATE_ACCEPTED', 'PROVIDER_PAYMENT_CREATE_REJECTED', 'PROVIDER_PAYMENT_CREATE_UNKNOWN', 'PROVIDER_PAYMENT_CREATE_MALFORMED', 'RAIL_UPDATE_APPLY_STARTED', 'RAIL_UPDATE_APPLY_FAILED')), false)
           ) AS has_provider_request_sent,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_rejection), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_rejected
             OR (
               selected_source.provider_submission_failed
               AND NOT (
                 upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                 AND selected_source.provider_submission_attempted IS NOT TRUE
                 AND selected_source.provider_request_sent IS NOT TRUE
                 AND selected_source.provider_response_received IS NOT TRUE
                 AND selected_source.provider_response_present IS NOT TRUE
                 AND selected_source.provider_submission_accepted IS NOT TRUE
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_unknown IS NOT TRUE
                 AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
                 AND NULLIF(BTRIM(COALESCE(
                   selected_source.provider_transaction_id,
                   selected_source.rail_tx_id,
                   selected_source.provider_reference,
                   selected_source.provider_state,
                   selected_source.provider_http_status,
                   ''
                 )), '') IS NULL
                 AND (
                   NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                   OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                     'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                     'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                   )
                 )
               )
             )), false)
             OR COALESCE(BOOL_OR(CASE WHEN NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, '')), '') ~ '^[0-9]+$' THEN selected_source.provider_http_status::integer >= 400 ELSE false END), false)
           ) AS has_provider_rejection,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_unknown), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
             OR COALESCE(BOOL_OR(selected_source.provider_submission_unknown), false)
           ) AS has_provider_unknown,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_blocked_pre_call), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'), false)
           ) AS has_provider_blocked_pre_call,
           (
             COALESCE(BOOL_OR(transfer_flag.has_provider_malformed_response), false)
             OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'), false)
           ) AS has_provider_malformed_response,
           COALESCE(BOOL_OR(
             lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
           ), false) AS has_durable_provider_request_impossible,
           (
             upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'
             AND upper(BTRIM(COALESCE(selected_chunk.chunk_type, ''))) = 'TRANSFER_SUBMIT'
             AND selected_chunk.completed_at_utc IS NULL
             AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_acceptance_evidence), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
               OR COALESCE(BOOL_OR(
                 NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(selected_source.chunk_id::text, '__NO_CHUNK_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN selected_source.operation_id IS NULL THEN NULL::text ELSE selected_source.operation_id::text END, '__NO_SOURCE_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID_PARAM__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
                 AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                 AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
                 AND selected_source.provider_submission_rejected IS NOT TRUE
                 AND selected_source.provider_submission_failed IS NOT TRUE
               ), false)
             )
             AND NOT (
               COALESCE(BOOL_OR(transfer_flag.has_provider_response), false)
               OR COALESCE(BOOL_OR(selected_source.provider_response_received OR selected_source.provider_response_present), false)
               OR COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')), false)
               OR COALESCE(BOOL_OR(
             NULLIF(BTRIM(COALESCE(selected_source.provider_http_status, selected_source.provider_error_code, '')), '') IS NOT NULL
             AND NOT (
               UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
               AND selected_source.provider_submission_attempted IS NOT TRUE
               AND selected_source.provider_request_sent IS NOT TRUE
               AND selected_source.provider_response_received IS NOT TRUE
               AND selected_source.provider_response_present IS NOT TRUE
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, selected_source.provider_reference, '')), '') IS NULL
               AND UPPER(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN ('PROVIDER_SUBMIT_STAGE_RECORD_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL')
             )
           ), false)
             )
             AND COALESCE(BOOL_OR(
               lower(BTRIM(COALESCE(selected_source.diagnostic->>'provider_request_impossible', selected_source.diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
             ), false) IS NOT TRUE
           ) AS is_stale_unresolved
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_transfer_ids AS selected_chunk_transfer
      ON selected_chunk_transfer.chunk_id = selected_chunk.chunk_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag
      ON transfer_flag.transfer_id = selected_chunk_transfer.transfer_id
    LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
      ON selected_source.chunk_id = selected_chunk.chunk_id
    GROUP BY selected_chunk.chunk_id,
             selected_chunk.status,
             selected_chunk.chunk_type,
             selected_chunk.completed_at_utc,
             selected_chunk.lock_expires_at_utc
  ) AS chunk_eval
  ON CONFLICT (chunk_id) DO NOTHING;

  SELECT COUNT(*)::integer INTO v_operation_count FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;
  SELECT COUNT(*)::integer INTO v_chunk_count FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;
  SELECT COUNT(*)::integer INTO v_transfer_count FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_response)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_request_sent)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_unknown)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_rejection)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_acceptance_evidence)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_blocked_pre_call)::integer,
         COUNT(*) FILTER (WHERE transfer_flag.has_provider_malformed_response)::integer
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count
  FROM pg_temp.tmp_provider_submit_diagnostic_transfer_flags AS transfer_flag;

  SELECT GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_response_present_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_response), 0))::integer,
         GREATEST(COALESCE(v_provider_request_sent_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_request_sent), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_unknown_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_unknown OR chunk_flag.is_stale_unresolved), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_rejected_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_rejection), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_accepted_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_acceptance_evidence), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_blocked_pre_call_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_blocked_pre_call), 0))::integer,
         GREATEST(COALESCE(v_provider_submission_malformed_response_count, 0), COALESCE(COUNT(*) FILTER (WHERE chunk_flag.has_provider_malformed_response), 0))::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_unresolved), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE chunk_flag.is_stale_request_sent_no_response), 0)::integer,
         COALESCE(COUNT(*) FILTER (WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING'), 0)::integer,
         COALESCE(BOOL_OR(upper(BTRIM(COALESCE(selected_chunk.status, ''))) = 'RUNNING' AND (selected_chunk.lock_expires_at_utc IS NULL OR selected_chunk.lock_expires_at_utc < v_now)), false)
  INTO v_provider_acceptance_evidence_count,
       v_provider_response_present_count,
       v_provider_request_sent_count,
       v_provider_submission_unknown_count,
       v_provider_submission_rejected_count,
       v_provider_submission_accepted_count,
       v_provider_submission_blocked_pre_call_count,
       v_provider_submission_malformed_response_count,
       v_stale_unresolved_submit_chunk_count,
       v_request_sent_no_response_count,
       v_unfinalised_submit_chunk_count,
       v_chunk_lock_expired
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
  LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS chunk_flag
    ON chunk_flag.chunk_id = selected_chunk.chunk_id;

  v_stale_empty_submit_chunk_count := COALESCE(v_stale_unresolved_submit_chunk_count, 0);

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_operation.operation_id::text) ORDER BY selected_operation.operation_id), '[]'::jsonb),
         MIN(selected_operation.operation_id::text)
  INTO v_operation_ids,
       v_primary_operation_id
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  IF p_operation_id IS NOT NULL THEN
    v_diagnostic_operation_id := p_operation_id::text;
  ELSIF p_chunk_id IS NOT NULL THEN
    SELECT selected_chunk.operation_id::text
    INTO v_diagnostic_operation_id
    FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
    WHERE selected_chunk.chunk_id = p_chunk_id
    LIMIT 1;
  ELSE
    v_diagnostic_operation_id := NULL::text;
  END IF;

  IF v_diagnostic_operation_id IS NOT NULL THEN
    v_primary_operation_id := v_diagnostic_operation_id;
    v_current_operation_ids := jsonb_build_array(v_diagnostic_operation_id);

    SELECT COALESCE(jsonb_agg(to_jsonb(related_operation.value) ORDER BY related_operation.value), '[]'::jsonb)
    INTO v_related_operation_ids
    FROM (
      SELECT DISTINCT selected_operation.operation_id::text AS value
      FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
      WHERE selected_operation.operation_id::text <> v_diagnostic_operation_id
    ) AS related_operation;
  ELSE
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := COALESCE(v_operation_ids, '[]'::jsonb);
  END IF;

  SELECT COALESCE(BOOL_OR(UPPER(BTRIM(COALESCE(selected_operation.operation_status, ''))) = 'REVIEW_REQUIRED'), false)
  INTO v_operation_review_required
  FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.chunk_id), '[]'::jsonb),
         MIN(selected_chunk.chunk_id::text),
         MIN(selected_chunk.started_at_utc)::text,
         MIN(selected_chunk.completed_at_utc)::text,
         MIN(selected_chunk.lock_expires_at_utc)::text
  INTO v_chunk_ids,
       v_primary_chunk_id,
       v_chunk_started_at_utc,
       v_chunk_completed_at_utc,
       v_chunk_lock_expires_at_utc
  FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id), '[]'::jsonb),
         MIN(selected_transfer.transfer_id::text),
         MIN(selected_transfer.rail_provider),
         MIN(selected_transfer.rail_env),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_tx_id, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.rail_state, '')), '')),
         MIN(NULLIF(BTRIM(COALESCE(selected_transfer.request_id, '')), ''))
  INTO v_transfer_ids,
       v_primary_transfer_id,
       v_primary_rail_provider,
       v_primary_rail_env,
       v_primary_rail_tx_id,
       v_primary_rail_state,
       v_primary_request_id
  FROM pg_temp.tmp_provider_submit_diagnostic_transfers AS selected_transfer;

  SELECT selected_source.provider_transaction_id,
         selected_source.provider_reference,
         selected_source.provider_state,
         COALESCE(selected_source.request_id, v_primary_request_id),
         COALESCE(selected_source.idempotency_key, v_primary_request_id),
         selected_source.local_provider_request_id,
         selected_source.provider_http_status,
         selected_source.provider_error_code,
         selected_source.provider_error_message_redacted,
         selected_source.provider_response_redacted,
         selected_source.provider_error_redacted,
         COALESCE(selected_source.provider_call_stage, v_provider_call_stage)
  INTO v_primary_provider_transaction_id,
       v_primary_provider_reference,
       v_primary_provider_state,
       v_primary_request_id,
       v_primary_idempotency_key,
       v_primary_local_provider_request_id,
       v_primary_provider_http_status,
       v_primary_provider_error_code,
       v_primary_provider_error_message_redacted,
       v_primary_provider_response_redacted,
       v_primary_provider_error_redacted,
       v_provider_call_stage
  FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
  WHERE NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.provider_reference, selected_source.provider_state, selected_source.provider_error_code, selected_source.request_id, selected_source.idempotency_key, selected_source.provider_call_stage, '')), '') IS NOT NULL
  ORDER BY CASE
             WHEN (
               NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_transaction_id, selected_source.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) OR (
               NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
               AND NULLIF(BTRIM(COALESCE(selected_source.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(selected_source.local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
               AND UPPER(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               AND selected_source.provider_submission_rejected IS NOT TRUE
               AND selected_source.provider_submission_failed IS NOT TRUE
             ) THEN 0
             WHEN selected_source.provider_response_present OR selected_source.provider_response_received THEN 1
             WHEN selected_source.provider_request_sent THEN 2
             ELSE 3
           END,
           selected_source.source_type
  LIMIT 1;

  IF v_primary_idempotency_key IS NULL THEN
    v_primary_idempotency_key := v_primary_request_id;
  END IF;

  IF v_primary_provider_reference IS NOT NULL
     AND v_primary_provider_reference IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_reference := NULL::text;
  END IF;

  IF v_primary_provider_transaction_id IS NOT NULL
     AND v_primary_provider_transaction_id IN (
       COALESCE(v_primary_request_id, '__NO_REQUEST_ID__'),
       COALESCE(CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END, '__NO_OPERATION_ID__'),
       COALESCE(CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END, '__NO_CHUNK_ID__'),
       COALESCE(v_primary_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_primary_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
     ) THEN
    v_primary_provider_transaction_id := NULL::text;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(scope_values.transfer_scope_id::text) ORDER BY scope_values.transfer_scope_id), '[]'::jsonb),
         MIN(scope_values.transfer_scope_id::text)
  INTO v_transfer_scope_ids,
       v_primary_transfer_scope_id
  FROM (
    SELECT DISTINCT transfer_scope.id AS transfer_scope_id
    FROM public.banking_pay_operation_transfer_scope AS transfer_scope
    WHERE (
        EXISTS (
          SELECT 1
          FROM pg_temp.tmp_provider_submit_diagnostic_operations AS selected_operation
          WHERE selected_operation.operation_id = transfer_scope.operation_id
        )
        OR (v_effective_pay_batch_id IS NOT NULL AND transfer_scope.pay_batch_id = v_effective_pay_batch_id)
      )
      AND (p_transfer_id IS NULL OR transfer_scope.pay_bank_transfer_id = p_transfer_id)
  ) AS scope_values;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(auth_values.auth_request_id::text) ORDER BY auth_values.auth_request_id), '[]'::jsonb),
         MIN(auth_values.auth_request_id::text)
  INTO v_active_auth_request_count,
       v_auth_request_ids,
       v_primary_auth_request_id
  FROM (
    SELECT DISTINCT auth_request.id AS auth_request_id
    FROM public.pay_batch_auth_requests AS auth_request
    WHERE v_effective_pay_batch_id IS NOT NULL
      AND auth_request.pay_batch_id = v_effective_pay_batch_id
      AND upper(BTRIM(COALESCE(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND (p_operation_id IS NULL OR auth_request.execution_intent_json->>'operation_id' = p_operation_id::text)
  ) AS auth_values;

  IF p_operation_id IS NULL
     AND p_transfer_id IS NULL
     AND p_chunk_id IS NULL
     AND v_effective_pay_batch_id IS NOT NULL
     AND COALESCE(v_transfer_count, 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_ids), 0) = 0
     AND COALESCE(jsonb_array_length(v_transfer_scope_ids), 0) = 0
     AND COALESCE(v_active_auth_request_count, 0) = 0
     AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     AND COALESCE(v_provider_response_present_count, 0) = 0
     AND COALESCE(v_provider_request_sent_count, 0) = 0
     AND COALESCE(v_provider_submission_unknown_count, 0) = 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0
     AND COALESCE(v_unfinalised_submit_chunk_count, 0) = 0
     AND COALESCE(v_provider_submission_rejected_count, 0) = 0
     AND COALESCE(v_provider_submission_malformed_response_count, 0) = 0
     AND COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0
     AND NOT EXISTS (
       SELECT 1
       FROM public.pay_bank_transfer_events AS batch_provider_event
       WHERE batch_provider_event.pay_batch_id = v_effective_pay_batch_id
         AND upper(BTRIM(COALESCE(batch_provider_event.event_source, ''))) IN (
           'PROVIDER_RESPONSE',
           'PROVIDER_POLL',
           'PROVIDER_WEBHOOK',
           'WEBHOOK',
           'POLL',
           'RAIL_PROVIDER',
           'PROVIDER',
           'PROVIDER_SETTLEMENT',
           'RAIL_PROVIDER_SETTLEMENT'
         )
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_chunks AS selected_chunk
       LEFT JOIN pg_temp.tmp_provider_submit_diagnostic_chunk_flags AS selected_chunk_flag
         ON selected_chunk_flag.chunk_id = selected_chunk.chunk_id
       WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) NOT IN ('COMPLETE', 'FAILED', 'SKIPPED', 'CANCELLED', 'CANCELED')
          OR COALESCE(selected_chunk_flag.has_provider_blocked_pre_call, false) IS NOT TRUE
          OR COALESCE(selected_chunk_flag.has_provider_acceptance_evidence, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_request_sent, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_rejection, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_unknown, false) IS TRUE
          OR COALESCE(selected_chunk_flag.has_provider_malformed_response, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_unresolved, false) IS TRUE
          OR COALESCE(selected_chunk_flag.is_stale_request_sent_no_response, false) IS TRUE
     )
     AND NOT EXISTS (
       SELECT 1
       FROM pg_temp.tmp_provider_submit_diagnostic_sources AS selected_source
       WHERE selected_source.provider_submission_attempted IS TRUE
          OR selected_source.provider_request_sent IS TRUE
          OR selected_source.provider_response_received IS TRUE
          OR selected_source.provider_response_present IS TRUE
          OR selected_source.provider_submission_accepted IS TRUE
          OR selected_source.provider_submission_rejected IS TRUE
          OR (
            selected_source.provider_submission_failed IS TRUE
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND selected_source.provider_submission_attempted IS NOT TRUE
              AND selected_source.provider_request_sent IS NOT TRUE
              AND selected_source.provider_response_received IS NOT TRUE
              AND selected_source.provider_response_present IS NOT TRUE
              AND selected_source.provider_submission_accepted IS NOT TRUE
              AND selected_source.provider_submission_rejected IS NOT TRUE
              AND selected_source.provider_submission_unknown IS NOT TRUE
              AND selected_source.provider_acceptance_evidence_present IS NOT TRUE
              AND NULLIF(BTRIM(COALESCE(
                selected_source.provider_transaction_id,
                selected_source.rail_tx_id,
                selected_source.provider_reference,
                selected_source.provider_state,
                selected_source.provider_http_status,
                ''
              )), '') IS NULL
              AND (
                NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NULL
                OR upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                  'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                  'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
                )
              )
            )
          )
          OR selected_source.provider_submission_unknown IS TRUE
          OR selected_source.provider_acceptance_evidence_present IS TRUE
          OR upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) IN (
            'PROVIDER_SUBMISSION_ACCEPTED',
            'PROVIDER_SUBMISSION_REJECTED',
            'PROVIDER_SUBMISSION_FAILED',
            'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
            'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
            'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
            'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
          )
          OR NULLIF(BTRIM(COALESCE(
            selected_source.provider_transaction_id,
            selected_source.rail_tx_id,
            selected_source.provider_reference,
            selected_source.provider_state,
            selected_source.provider_http_status,
            ''
          )), '') IS NOT NULL
          OR (
            NULLIF(BTRIM(COALESCE(selected_source.provider_error_code, '')), '') IS NOT NULL
            AND NOT (
              upper(BTRIM(COALESCE(selected_source.provider_submission_status, ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
              AND upper(BTRIM(COALESCE(selected_source.provider_error_code, ''))) IN (
                'PROVIDER_SUBMIT_STAGE_RECORD_FAILED',
                'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
              )
            )
          )
     ) THEN
    v_batch_level_cleaned_local_blocked_pre_call_neutralised := true;

    v_operation_count := 0;
    v_chunk_count := 0;
    v_provider_submission_blocked_pre_call_count := 0;
    v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
    v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_call_stage := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_accepted := false;
    v_provider_submission_rejected := false;
    v_provider_submission_failed := false;
    v_provider_submission_unknown := false;
    v_provider_acceptance_evidence_present := false;
    v_stale_submit_chunk := false;
    v_unfinalised_submit_chunk := false;
    v_chunk_lock_expired := false;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := false;
    v_retry_blocked_reason := NULL::text;
    v_recommended_action := 'No provider submission attempt has been recorded for this scope.';

    v_operation_ids := '[]'::jsonb;
    v_current_operation_ids := '[]'::jsonb;
    v_related_operation_ids := '[]'::jsonb;
    v_diagnostic_operation_id := NULL::text;
    v_chunk_ids := '[]'::jsonb;
    v_primary_operation_id := NULL::text;
    v_primary_chunk_id := NULL::text;
    v_primary_request_id := NULL::text;
    v_primary_idempotency_key := NULL::text;
    v_primary_local_provider_request_id := NULL::text;
    v_primary_provider_http_status := NULL::text;
    v_primary_provider_error_code := NULL::text;
    v_primary_provider_error_message_redacted := NULL::text;
    v_primary_provider_response_redacted := NULL::jsonb;
    v_primary_provider_error_redacted := NULL::jsonb;
    v_chunk_started_at_utc := NULL::text;
    v_chunk_completed_at_utc := NULL::text;
    v_chunk_lock_expires_at_utc := NULL::text;
  END IF;

  v_provider_submit_actual_context := (
    COALESCE(v_operation_count, 0) > 0
    OR COALESCE(v_chunk_count, 0) > 0
    OR COALESCE(v_transfer_count, 0) > 0
    OR COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    OR COALESCE(v_provider_response_present_count, 0) > 0
    OR COALESCE(v_provider_request_sent_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
    OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
    OR COALESCE(v_provider_submission_rejected_count, 0) > 0
    OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
  );

  v_mixed_provider_submit_outcome := (
    COALESCE(v_provider_acceptance_evidence_count, 0) > 0
    AND (
      COALESCE(v_provider_submission_unknown_count, 0) > 0
      OR COALESCE(v_provider_submission_rejected_count, 0) > 0
      OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
      OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
      OR COALESCE(v_request_sent_no_response_count, 0) > 0
      OR (
        COALESCE(v_unfinalised_submit_chunk_count, 0) > 0
        AND (COALESCE(v_operation_review_required, false) IS TRUE OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0)
      )
      OR (
        COALESCE(v_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
        AND (
          COALESCE(v_operation_review_required, false) IS TRUE
          OR COALESCE(v_provider_submission_unknown_count, 0) > 0
          OR COALESCE(v_provider_submission_rejected_count, 0) > 0
          OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
          OR COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0
        )
      )
    )
  );

  IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
    v_review_reason_code := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'PROVIDER_RESPONSE_RECEIVED');
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_accepted := true;
    v_provider_acceptance_evidence_present := true;
    v_stale_submit_chunk := COALESCE(v_stale_empty_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_recommended_action := 'Provider acceptance evidence exists. Do not retry unless reconciled.';
  ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
    v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_RESPONSE_MALFORMED';
    v_recommended_action := 'Provider returned an unusable response. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0
     AND COALESCE(v_stale_unresolved_submit_chunk_count, 0) = 0 THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_request_sent_no_response_count, 0) > 0
     OR (
       COALESCE(v_provider_request_sent_count, 0) > 0
       AND COALESCE(v_provider_response_present_count, 0) = 0
       AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0
     ) THEN
    v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0;
    v_unfinalised_submit_chunk := COALESCE(v_unfinalised_submit_chunk_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_recommended_action := 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.';
  ELSIF COALESCE(v_stale_unresolved_submit_chunk_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_review_reason_code := 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK';
    v_provider_call_stage := COALESCE(v_provider_call_stage, 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK');
    v_provider_submission_attempted := NULL::boolean;
    v_provider_request_sent := NULL::boolean;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_unknown := true;
    v_stale_submit_chunk := true;
    v_unfinalised_submit_chunk := true;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_recommended_action := 'Check Revolut/bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.';
  ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
    v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
    v_provider_submission_attempted := true;
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_submission_rejected := true;
    v_provider_submission_failed := true;
    v_manual_resolution_required := false;
    v_safe_retry_available := false;
    v_recommended_action := 'Review the provider rejection/error and retry only after correction.';
  ELSIF COALESCE(v_provider_submission_blocked_pre_call_count, 0) > 0 THEN
    v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
    v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
    v_provider_submission_attempted := false;
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
    v_provider_submission_failed := true;
    v_recommended_action := 'Provider was not called. Fix the local blocker and retry if cleanup allows.';
  END IF;

  IF COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE THEN
    v_review_reason_code := 'MIXED_PROVIDER_SUBMIT_OUTCOME';
    v_provider_submission_unknown := true;
    v_provider_submission_rejected := COALESCE(v_provider_submission_rejected_count, 0) > 0;
    v_provider_submission_failed := COALESCE(v_provider_submission_rejected_count, 0) > 0 OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0;
    v_manual_resolution_required := true;
    v_safe_retry_available := false;
    v_automatic_retry_blocked := true;
    v_retry_blocked_reason := 'PROVIDER_SUBMISSION_MIXED_OUTCOME';
    v_recommended_action := 'Provider acceptance evidence exists for at least one transfer, but not all provider-submit outcomes are resolved. Reconcile accepted provider transfer(s) and unresolved/rejected/malformed transfer(s) before retry.';
  END IF;

  v_payment_provider_review_required := (
    COALESCE(v_provider_submit_actual_context, false) IS TRUE
    AND v_provider_submission_status <> 'MANUAL_RESOLVED_NO_PAYMENT_MADE'
    AND (
      COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE
      OR v_provider_submission_status IN (
        'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
        'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
        'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
        'PROVIDER_SUBMISSION_REJECTED',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      )
      OR (
        v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
        AND COALESCE(v_operation_review_required, false) IS TRUE
      )
    )
  );

  v_counts := jsonb_build_object(
    'operation_count', COALESCE(v_operation_count, 0),
    'chunk_count', COALESCE(v_chunk_count, 0),
    'transfer_count', COALESCE(v_transfer_count, 0),
    'active_auth_request_count', COALESCE(v_active_auth_request_count, 0),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_accepted_count', COALESCE(v_provider_submission_accepted_count, 0),
    'provider_submission_blocked_pre_call_count', COALESCE(v_provider_submission_blocked_pre_call_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'operation_review_required', COALESCE(v_operation_review_required, false),
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0)
  );

  v_ids := jsonb_build_object(
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
    'transfer_ids', COALESCE(v_transfer_ids, '[]'::jsonb),
    'transfer_scope_ids', COALESCE(v_transfer_scope_ids, '[]'::jsonb),
    'auth_request_ids', COALESCE(v_auth_request_ids, '[]'::jsonb)
  );

  v_provider_submit_diagnostic := jsonb_build_object(
    'diagnostic_version', 1,
    'generated_at_utc', v_now::text,
    'review_reason_code', v_review_reason_code,
    'provider_submission_status', v_provider_submission_status,
    'provider_call_stage', v_provider_call_stage,
    'provider_submission_attempted', v_provider_submission_attempted,
    'provider_request_sent', v_provider_request_sent,
    'provider_response_received', v_provider_response_received,
    'provider_response_present', v_provider_response_present,
    'provider_submission_accepted', v_provider_submission_accepted,
    'provider_submission_rejected', v_provider_submission_rejected,
    'provider_submission_failed', v_provider_submission_failed,
    'provider_submission_unknown', v_provider_submission_unknown,
    'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'stale_submit_chunk', v_stale_submit_chunk,
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'request_sent_no_response_count', COALESCE(v_request_sent_no_response_count, 0),
    'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
    'chunk_lock_expired', COALESCE(v_chunk_lock_expired, false),
    'chunk_started_at_utc', v_chunk_started_at_utc,
    'chunk_completed_at_utc', v_chunk_completed_at_utc
  )
  || jsonb_build_object(
    'chunk_lock_expires_at_utc', v_chunk_lock_expires_at_utc,
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'automatic_retry_blocked', v_automatic_retry_blocked,
    'retry_blocked_reason', v_retry_blocked_reason,
    'recommended_action', v_recommended_action,
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'operation_id', v_diagnostic_operation_id,
    'operation_ids', COALESCE(v_current_operation_ids, '[]'::jsonb),
    'related_operation_ids', COALESCE(v_related_operation_ids, '[]'::jsonb),
    'chunk_id', v_primary_chunk_id,
    'chunk_ids', v_chunk_ids,
    'transfer_id', v_primary_transfer_id,
    'transfer_ids', v_transfer_ids,
    'transfer_scope_id', v_primary_transfer_scope_id,
    'transfer_scope_ids', v_transfer_scope_ids,
    'auth_request_id', v_primary_auth_request_id,
    'auth_request_ids', v_auth_request_ids,
    'rail_provider', v_primary_rail_provider,
    'rail_env', v_primary_rail_env,
    'rail_tx_id', v_primary_rail_tx_id,
    'rail_state', v_primary_rail_state,
    'provider_transaction_id', v_primary_provider_transaction_id,
    'provider_reference', v_primary_provider_reference,
    'provider_state', v_primary_provider_state,
    'request_id', v_primary_request_id,
    'idempotency_key', v_primary_idempotency_key,
    'local_provider_request_id', v_primary_local_provider_request_id,
    'provider_http_status', v_primary_provider_http_status,
    'provider_error_code', v_primary_provider_error_code,
    'provider_error_message_redacted', v_primary_provider_error_message_redacted,
    'provider_response_redacted', v_primary_provider_response_redacted,
    'provider_error_redacted', v_primary_provider_error_redacted
  );

  RETURN jsonb_build_object(
    'ok', true,
    'provider_submit_diagnostic', v_provider_submit_diagnostic,
    'provider_submission_status', v_provider_submission_status,
    'review_reason_code', v_review_reason_code,
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
    'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
    'stale_unresolved_submit_chunk_count', COALESCE(v_stale_unresolved_submit_chunk_count, 0),
    'stale_empty_submit_chunk_count', COALESCE(v_stale_empty_submit_chunk_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
    'manual_resolution_required', v_manual_resolution_required,
    'safe_retry_available', v_safe_retry_available,
    'recommended_action', v_recommended_action,
    'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
    'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
    'counts', v_counts,
    'ids', v_ids,
    'provider_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_attempt_or_evidence_count', COALESCE(v_provider_request_sent_count, 0) + COALESCE(v_provider_response_present_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0),
    'attempted_but_unproven_count', COALESCE(v_provider_submission_unknown_count, 0),
    'counts_only', COALESCE(p_counts_only, false)
  );

END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_diagnostic_finalise(
  p_operation_id uuid,
  p_pay_batch_id uuid DEFAULT NULL::uuid,
  p_chunk_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_reason_code text DEFAULT NULL::text,
  p_failure_error_json jsonb DEFAULT '{}'::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_effective_pay_batch_id uuid := NULL::uuid;
  v_effective_actor_user_id uuid := NULL::uuid;
  v_reason_code text := NULL::text;
  v_failure_error_json jsonb := '{}'::jsonb;
  v_target_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_after_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_chunk_existing_diagnostic jsonb := '{}'::jsonb;
  v_chunk_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_chunk_diagnostic_result jsonb := '{}'::jsonb;
  v_chunk_transfer_ids jsonb := '[]'::jsonb;
  v_chunk_ids jsonb := '[]'::jsonb;
  v_all_transfer_ids jsonb := '[]'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_review_reason_code text := NULL::text;
  v_finish_status text := 'FAILED';
  v_completed_count integer := 0;
  v_failed_count integer := 0;
  v_affected_transfer_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_submission_rejected_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_provider_submission_malformed_response_count integer := 0;
  v_unfinalised_submit_chunk_count integer := 0;
  v_manual_resolution_required boolean := false;
  v_safe_retry_available boolean := false;
  v_payment_provider_review_required boolean := false;
  v_mixed_provider_submit_outcome boolean := false;
  v_message text := NULL::text;
  v_result_json jsonb := NULL::jsonb;
  v_error_json jsonb := NULL::jsonb;
  v_finished boolean := false;
  v_not_finished_reason text := NULL::text;
  v_finalised_chunk_count integer := 0;
  v_already_terminal_chunk_count integer := 0;
  v_finalised_chunk_ids jsonb := '[]'::jsonb;
  v_already_terminal_chunk_ids jsonb := '[]'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_overall_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_overall_provider_submission_status text := NULL::text;
  v_overall_review_reason_code text := NULL::text;
  v_total_provider_request_sent_count integer := 0;
  v_total_provider_response_present_count integer := 0;
  v_total_provider_acceptance_evidence_count integer := 0;
  v_total_provider_submission_rejected_count integer := 0;
  v_total_provider_submission_unknown_count integer := 0;
  v_total_provider_submission_malformed_response_count integer := 0;
  v_total_unfinalised_submit_chunk_count integer := 0;
  v_total_affected_transfer_count integer := 0;
  v_manual_resolution_required_any boolean := false;
  v_safe_retry_available_any boolean := false;
  v_diagnostic_was_existing boolean := false;
  v_diagnostic_usable boolean := false;
  v_status_candidate text := NULL::text;
  v_reason_candidate text := NULL::text;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISE',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_provider_submit_chunk_diagnostic_finalise requires p_operation_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_failure_error_json IS NOT NULL AND jsonb_typeof(p_failure_error_json) = 'object' THEN
    v_failure_error_json := p_failure_error_json;
  ELSE
    v_failure_error_json := '{}'::jsonb;
  END IF;

  v_reason_code := COALESCE(NULLIF(BTRIM(COALESCE(p_reason_code, '')), ''), 'PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISE');

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISE',
      'code', 'OPERATION_NOT_FOUND',
      'message', 'pay_provider_submit_chunk_diagnostic_finalise: operation not found',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_effective_pay_batch_id := COALESCE(p_pay_batch_id, v_operation_row.pay_batch_id);
  v_effective_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id);

  IF p_pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id IS NOT NULL AND p_pay_batch_id <> v_operation_row.pay_batch_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISE',
      'code', 'OPERATION_BATCH_MISMATCH',
      'message', 'pay_provider_submit_chunk_diagnostic_finalise: operation belongs to a different pay batch',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', v_operation_row.pay_batch_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RETURN jsonb_build_object(
      'ok', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
      'finalised_chunk_count', 0,
      'finalised_chunk_ids', '[]'::jsonb,
      'already_terminal_chunk_count', 0,
      'already_terminal_chunk_ids', '[]'::jsonb,
      'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED',
      'review_reason_code', 'NOT_PROVIDER_SUBMIT_OPERATION',
      'reason', 'NOT_PROVIDER_SUBMIT_OPERATION',
      'operation_type', v_operation_row.operation_type
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_finalise_chunks;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_finalise_chunks (
    chunk_id uuid PRIMARY KEY,
    operation_id uuid NOT NULL,
    pay_batch_id uuid,
    phase text,
    chunk_type text,
    sequence_no integer,
    status text,
    payload_json jsonb,
    result_json jsonb,
    error_json jsonb,
    unit_count integer,
    completed_count integer,
    failed_count integer,
    locked_by text,
    lock_expires_at_utc timestamptz,
    created_at_utc timestamptz,
    started_at_utc timestamptz,
    completed_at_utc timestamptz,
    updated_at_utc timestamptz
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_finalise_chunks (
    chunk_id,
    operation_id,
    pay_batch_id,
    phase,
    chunk_type,
    sequence_no,
    status,
    payload_json,
    result_json,
    error_json,
    unit_count,
    completed_count,
    failed_count,
    locked_by,
    lock_expires_at_utc,
    created_at_utc,
    started_at_utc,
    completed_at_utc,
    updated_at_utc
  )
  SELECT operation_chunk.id,
         operation_chunk.operation_id,
         v_effective_pay_batch_id,
         operation_chunk.phase,
         operation_chunk.chunk_type,
         operation_chunk.sequence_no,
         operation_chunk.status,
         COALESCE(operation_chunk.payload_json, '{}'::jsonb),
         operation_chunk.result_json,
         operation_chunk.error_json,
         operation_chunk.unit_count,
         operation_chunk.completed_count,
         operation_chunk.failed_count,
         operation_chunk.locked_by,
         operation_chunk.lock_expires_at_utc,
         operation_chunk.created_at_utc,
         operation_chunk.started_at_utc,
         operation_chunk.completed_at_utc,
         operation_chunk.updated_at_utc
  FROM public.banking_pay_operation_chunks AS operation_chunk
  WHERE operation_chunk.operation_id = p_operation_id
    AND (operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT')
    AND (p_chunk_id IS NULL OR operation_chunk.id = p_chunk_id)
  ORDER BY operation_chunk.sequence_no, operation_chunk.created_at_utc NULLS FIRST, operation_chunk.id
  FOR UPDATE;

  IF p_chunk_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM pg_temp.tmp_provider_submit_finalise_chunks AS exact_chunk_check
    WHERE exact_chunk_check.chunk_id = p_chunk_id
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISE',
      'code', 'CHUNK_NOT_FOUND_FOR_OPERATION',
      'message', 'pay_provider_submit_chunk_diagnostic_finalise: chunk was not found for this operation/provider-submit scope',
      'operation_id', p_operation_id::text,
      'chunk_id', p_chunk_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.sequence_no NULLS LAST, selected_chunk.created_at_utc NULLS FIRST, selected_chunk.chunk_id), '[]'::jsonb)
  INTO v_chunk_ids
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_finalise_transfer_ids;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_finalise_transfer_ids (
    chunk_id uuid,
    transfer_id uuid NOT NULL,
    PRIMARY KEY (chunk_id, transfer_id)
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_finalise_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  transfer_text.transfer_id_text::uuid
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
  CROSS JOIN LATERAL (
    SELECT transfer_id_element.value AS transfer_id_text
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfer_ids') = 'array' THEN selected_chunk.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_id_element(value)
    UNION ALL
    SELECT COALESCE(transfer_payload.value->>'pay_bank_transfer_id', transfer_payload.value->>'transfer_id', transfer_payload.value->>'id') AS transfer_id_text
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(selected_chunk.payload_json->'transfers') = 'array' THEN selected_chunk.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_payload(value)
  ) AS transfer_text
  WHERE NULLIF(BTRIM(COALESCE(transfer_text.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_finalise_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  operation_scope.pay_bank_transfer_id
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
  JOIN public.banking_pay_operation_transfer_scope AS operation_scope
    ON operation_scope.operation_id = selected_chunk.operation_id
   AND (v_effective_pay_batch_id IS NULL OR operation_scope.pay_batch_id = v_effective_pay_batch_id)
   AND operation_scope.pay_bank_transfer_id IS NOT NULL
  WHERE p_chunk_id IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_finalise_transfer_ids AS existing_transfer
      WHERE existing_transfer.chunk_id = selected_chunk.chunk_id
    )
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_finalise_transfer_ids (chunk_id, transfer_id)
  SELECT DISTINCT selected_chunk.chunk_id,
                  failure_transfer_uuid.transfer_id
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
  CROSS JOIN LATERAL (
    SELECT transfer_value.value AS transfer_id_text
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'transfer_ids') = 'array' THEN v_failure_error_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_value(value)
    UNION ALL
    SELECT transfer_value.value AS transfer_id_text
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'transferIds') = 'array' THEN v_failure_error_json->'transferIds' ELSE '[]'::jsonb END) AS transfer_value(value)
    UNION ALL
    SELECT transfer_value.value AS transfer_id_text
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids') = 'array' THEN v_failure_error_json->'provider_submit_diagnostic'->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_value(value)
    UNION ALL
    SELECT transfer_value.value AS transfer_id_text
    FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(v_failure_error_json->'providerSubmitDiagnostic'->'transferIds') = 'array' THEN v_failure_error_json->'providerSubmitDiagnostic'->'transferIds' ELSE '[]'::jsonb END) AS transfer_value(value)
  ) AS failure_transfer
  CROSS JOIN LATERAL (
    SELECT failure_transfer.transfer_id_text::uuid AS transfer_id
    WHERE NULLIF(BTRIM(COALESCE(failure_transfer.transfer_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS failure_transfer_uuid
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = failure_transfer_uuid.transfer_id
   AND (v_effective_pay_batch_id IS NULL OR transfer_row.pay_batch_id = v_effective_pay_batch_id)
  WHERE EXISTS (
    SELECT 1
    FROM public.banking_pay_operation_transfer_scope AS operation_scope_check
    WHERE operation_scope_check.operation_id = p_operation_id
      AND operation_scope_check.pay_bank_transfer_id = transfer_row.id
      AND (v_effective_pay_batch_id IS NULL OR operation_scope_check.pay_batch_id = v_effective_pay_batch_id)
  )
  ON CONFLICT DO NOTHING;

  SELECT COALESCE(jsonb_agg(DISTINCT to_jsonb(all_transfer.transfer_id::text)), '[]'::jsonb)
  INTO v_all_transfer_ids
  FROM pg_temp.tmp_provider_submit_finalise_transfer_ids AS all_transfer;

  SELECT COUNT(*)::integer
  INTO v_already_terminal_chunk_count
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
  WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) IN ('COMPLETE', 'FAILED', 'SKIPPED', 'CANCELLED', 'CANCELED');

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.sequence_no NULLS LAST, selected_chunk.created_at_utc NULLS FIRST, selected_chunk.chunk_id), '[]'::jsonb)
  INTO v_already_terminal_chunk_ids
  FROM pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
  WHERE upper(BTRIM(COALESCE(selected_chunk.status, ''))) IN ('COMPLETE', 'FAILED', 'SKIPPED', 'CANCELLED', 'CANCELED');

  FOR v_target_chunk_row IN
    SELECT operation_chunk.*
    FROM public.banking_pay_operation_chunks AS operation_chunk
    JOIN pg_temp.tmp_provider_submit_finalise_chunks AS selected_chunk
      ON selected_chunk.chunk_id = operation_chunk.id
    WHERE operation_chunk.operation_id = p_operation_id
      AND upper(BTRIM(COALESCE(operation_chunk.status, ''))) = 'RUNNING'
    ORDER BY operation_chunk.sequence_no, operation_chunk.created_at_utc NULLS FIRST, operation_chunk.id
    FOR UPDATE OF operation_chunk
  LOOP
    v_before_json := to_jsonb(v_target_chunk_row);
    v_chunk_existing_diagnostic := COALESCE(
      CASE WHEN jsonb_typeof(v_target_chunk_row.error_json->'provider_submit_diagnostic') = 'object' THEN v_target_chunk_row.error_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(v_target_chunk_row.result_json->'provider_submit_diagnostic') = 'object' THEN v_target_chunk_row.result_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(v_target_chunk_row.payload_json->'provider_submit_diagnostic') = 'object' THEN v_target_chunk_row.payload_json->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      '{}'::jsonb
    );

    IF jsonb_typeof(v_failure_error_json->'provider_submit_diagnostic') = 'object' THEN
      v_chunk_existing_diagnostic := jsonb_strip_nulls(v_chunk_existing_diagnostic || (v_failure_error_json->'provider_submit_diagnostic'));
    END IF;

    v_chunk_existing_diagnostic := jsonb_strip_nulls(COALESCE(v_chunk_existing_diagnostic, '{}'::jsonb))
      || jsonb_strip_nulls(jsonb_build_object(
        'provider_submission_status', COALESCE(v_failure_error_json->>'provider_submission_status', v_failure_error_json->>'providerSubmissionStatus'),
        'review_reason_code', COALESCE(v_failure_error_json->>'provider_submit_review_reason_code', v_failure_error_json->>'providerSubmitReviewReasonCode', v_failure_error_json->>'review_reason_code', v_failure_error_json->>'reviewReasonCode'),
        'provider_request_sent', COALESCE(v_failure_error_json->>'provider_request_sent', v_failure_error_json->>'providerRequestSent'),
        'provider_request_sent_confirmed', COALESCE(v_failure_error_json->>'provider_request_sent_confirmed', v_failure_error_json->>'providerRequestSentConfirmed'),
        'provider_called', COALESCE(v_failure_error_json->>'provider_called', v_failure_error_json->>'providerCalled'),
        'provider_response_present', COALESCE(v_failure_error_json->>'provider_response_present', v_failure_error_json->>'providerResponsePresent'),
        'provider_response_received', COALESCE(v_failure_error_json->>'provider_response_received', v_failure_error_json->>'providerResponseReceived'),
        'provider_submission_accepted', COALESCE(v_failure_error_json->>'provider_submission_accepted', v_failure_error_json->>'providerSubmissionAccepted'),
        'provider_submission_rejected', COALESCE(v_failure_error_json->>'provider_submission_rejected', v_failure_error_json->>'providerSubmissionRejected'),
        'provider_submission_unknown', COALESCE(v_failure_error_json->>'provider_submission_unknown', v_failure_error_json->>'providerSubmissionUnknown'),
        'provider_acceptance_evidence_present', COALESCE(v_failure_error_json->>'provider_acceptance_evidence_present', v_failure_error_json->>'providerAcceptanceEvidencePresent'),
        'provider_acceptance_evidence_count', COALESCE(v_failure_error_json->>'provider_acceptance_evidence_count', v_failure_error_json->>'providerAcceptanceEvidenceCount'),
        'provider_rejection_count', COALESCE(v_failure_error_json->>'provider_rejection_count', v_failure_error_json->>'providerRejectionCount'),
        'provider_submission_rejected_count', COALESCE(v_failure_error_json->>'provider_submission_rejected_count', v_failure_error_json->>'providerSubmissionRejectedCount'),
        'provider_unknown_count', COALESCE(v_failure_error_json->>'provider_unknown_count', v_failure_error_json->>'providerUnknownCount'),
        'provider_submission_unknown_count', COALESCE(v_failure_error_json->>'provider_submission_unknown_count', v_failure_error_json->>'providerSubmissionUnknownCount'),
        'provider_http_status', COALESCE(v_failure_error_json->>'provider_http_status', v_failure_error_json->>'providerHttpStatus'),
        'provider_error_code', COALESCE(v_failure_error_json->>'provider_error_code', v_failure_error_json->>'providerErrorCode')
      ));

    v_diagnostic_usable := (
      COALESCE(v_chunk_existing_diagnostic, '{}'::jsonb) <> '{}'::jsonb
      AND (
        NULLIF(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_submission_status', v_chunk_existing_diagnostic->>'review_reason_code', v_chunk_existing_diagnostic->>'provider_call_stage', '')), '') IS NOT NULL
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR NULLIF(BTRIM(COALESCE(v_chunk_existing_diagnostic->>'provider_http_status', v_chunk_existing_diagnostic->>'provider_error_code', v_chunk_existing_diagnostic->>'rail_tx_id', v_chunk_existing_diagnostic->>'provider_transaction_id', v_chunk_existing_diagnostic->>'provider_payment_id', v_chunk_existing_diagnostic->>'provider_reference', '')), '') IS NOT NULL
        OR COALESCE(v_chunk_existing_diagnostic->>'provider_acceptance_evidence_count', v_chunk_existing_diagnostic->>'provider_response_present_count', v_chunk_existing_diagnostic->>'provider_request_sent_count', v_chunk_existing_diagnostic->>'provider_submission_rejected_count', v_chunk_existing_diagnostic->>'provider_submission_unknown_count', '') ~ '^[0-9]+$'
      )
    );

    v_diagnostic_was_existing := v_diagnostic_usable;

    IF v_diagnostic_usable IS TRUE THEN
      v_chunk_diagnostic_result := '{}'::jsonb;
      v_chunk_provider_submit_diagnostic := v_chunk_existing_diagnostic;
    ELSE
      v_chunk_diagnostic_result := public.pay_provider_submit_diagnostic_get(
        p_pay_batch_id := v_effective_pay_batch_id,
        p_operation_id := p_operation_id,
        p_transfer_id := NULL::uuid,
        p_chunk_id := v_target_chunk_row.id,
        p_counts_only := true
      );
      v_chunk_provider_submit_diagnostic := COALESCE(v_chunk_diagnostic_result->'provider_submit_diagnostic', '{}'::jsonb);
    END IF;

    SELECT COALESCE(jsonb_agg(to_jsonb(chunk_transfer.transfer_id::text) ORDER BY chunk_transfer.transfer_id), '[]'::jsonb),
           COUNT(*)::integer
    INTO v_chunk_transfer_ids,
         v_affected_transfer_count
    FROM pg_temp.tmp_provider_submit_finalise_transfer_ids AS chunk_transfer
    WHERE chunk_transfer.chunk_id = v_target_chunk_row.id;

    v_affected_transfer_count := GREATEST(COALESCE(v_affected_transfer_count, 0), COALESCE(NULLIF(v_target_chunk_row.unit_count, 0), 0));

    v_status_candidate := upper(BTRIM(COALESCE(
      v_chunk_provider_submit_diagnostic->>'provider_submission_status',
      v_chunk_provider_submit_diagnostic->>'outcome_code',
      v_chunk_diagnostic_result->>'provider_submission_status',
      ''
    )));
    v_reason_candidate := upper(BTRIM(COALESCE(
      v_chunk_provider_submit_diagnostic->>'review_reason_code',
      v_chunk_diagnostic_result->>'review_reason_code',
      ''
    )));

    v_provider_request_sent_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_request_sent_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_request_sent_count}')::integer
      WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_request_sent_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_request_sent_count')::integer
      WHEN lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_request_sent', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_called', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR NULLIF(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_request_dispatched_at_utc', v_chunk_provider_submit_diagnostic->>'request_sent_at_utc', '')), '') IS NOT NULL THEN 1
      ELSE 0
    END;

    v_provider_response_present_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_response_present_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_response_present_count}')::integer
      WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_response_present_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_response_present_count')::integer
      WHEN lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR NULLIF(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'response_received_at_utc', v_chunk_provider_submit_diagnostic->>'provider_http_status', v_chunk_provider_submit_diagnostic->>'provider_error_code', '')), '') IS NOT NULL THEN 1
      ELSE 0
    END;

    v_provider_acceptance_evidence_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_acceptance_evidence_count}')::integer
      WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_acceptance_evidence_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_acceptance_evidence_count')::integer
      WHEN v_status_candidate IN ('PROVIDER_SUBMISSION_ACCEPTED', 'ACCEPTED', 'PROVIDER_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
        OR v_reason_candidate IN ('PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT', 'PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_ACCEPTED_PAYMENT')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_accepted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR NULLIF(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'rail_tx_id', v_chunk_provider_submit_diagnostic->>'provider_transaction_id', v_chunk_provider_submit_diagnostic->>'provider_payment_id', v_chunk_provider_submit_diagnostic->>'provider_reference', '')), '') IS NOT NULL THEN GREATEST(1, COALESCE(v_affected_transfer_count, 0))
      ELSE 0
    END;

    v_provider_submission_rejected_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_submission_rejected_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_submission_rejected_count}')::integer
      WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_rejected_count', '') ~ '^[0-9]+$'
        OR COALESCE(v_chunk_provider_submit_diagnostic->>'provider_rejection_count', '') ~ '^[0-9]+$' THEN GREATEST(
          CASE WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_rejected_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_submission_rejected_count')::integer ELSE 0 END,
          CASE WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_rejection_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_rejection_count')::integer ELSE 0 END
        )
      WHEN v_status_candidate IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_REJECTED_PAYMENT', 'REJECTED', 'DECLINED')
        OR v_reason_candidate IN ('PROVIDER_REJECTED_PAYMENT', 'PROVIDER_SUBMISSION_REJECTED', 'REJECTED', 'DECLINED')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_rejected', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN GREATEST(1, COALESCE(v_affected_transfer_count, 0))
      ELSE 0
    END;

    v_provider_submission_malformed_response_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_submission_malformed_response_count}')::integer
      WHEN v_status_candidate IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'MALFORMED', 'MALFORMED_RESPONSE', 'PROVIDER_RESPONSE_MALFORMED')
        OR v_reason_candidate IN ('PROVIDER_RESPONSE_MALFORMED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE') THEN GREATEST(1, COALESCE(v_affected_transfer_count, 0))
      ELSE 0
    END;

    v_unfinalised_submit_chunk_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,unfinalised_submit_chunk_count}')::integer
      WHEN upper(BTRIM(COALESCE(v_target_chunk_row.status, ''))) = 'RUNNING' THEN 1
      ELSE 0
    END;

    v_provider_submission_unknown_count := CASE
      WHEN COALESCE(v_chunk_diagnostic_result #>> '{counts,provider_submission_unknown_count}', '') ~ '^[0-9]+$' THEN (v_chunk_diagnostic_result #>> '{counts,provider_submission_unknown_count}')::integer
      WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_unknown_count', '') ~ '^[0-9]+$'
        OR COALESCE(v_chunk_provider_submit_diagnostic->>'provider_unknown_count', '') ~ '^[0-9]+$' THEN GREATEST(
          CASE WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_unknown_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_submission_unknown_count')::integer ELSE 0 END,
          CASE WHEN COALESCE(v_chunk_provider_submit_diagnostic->>'provider_unknown_count', '') ~ '^[0-9]+$' THEN (v_chunk_provider_submit_diagnostic->>'provider_unknown_count')::integer ELSE 0 END
        )
      WHEN v_status_candidate IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
        OR v_reason_candidate IN ('PROVIDER_REQUEST_SENT_NO_RESPONSE', 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME')
        OR lower(BTRIM(COALESCE(v_chunk_provider_submit_diagnostic->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
        OR (COALESCE(v_provider_request_sent_count, 0) > 0 AND COALESCE(v_provider_response_present_count, 0) = 0 AND COALESCE(v_provider_acceptance_evidence_count, 0) = 0 AND COALESCE(v_provider_submission_rejected_count, 0) = 0) THEN GREATEST(1, COALESCE(v_affected_transfer_count, 0))
      ELSE 0
    END;

    IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_ACCEPTED';
      v_review_reason_code := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    ELSIF COALESCE(v_provider_submission_rejected_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_REJECTED';
      v_review_reason_code := 'PROVIDER_REJECTED_PAYMENT';
    ELSIF COALESCE(v_provider_submission_malformed_response_count, 0) > 0 THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
      v_review_reason_code := 'PROVIDER_RESPONSE_MALFORMED';
    ELSIF v_status_candidate IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL') OR v_reason_candidate IN ('PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL') THEN
      v_provider_submission_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
      v_review_reason_code := 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL';
    ELSIF COALESCE(v_provider_submission_unknown_count, 0) > 0 OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 0 OR COALESCE(v_provider_request_sent_count, 0) > 0 OR COALESCE(v_provider_response_present_count, 0) > 0 THEN
      v_provider_submission_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
      v_review_reason_code := 'PROVIDER_REQUEST_SENT_NO_RESPONSE';
    ELSE
      v_provider_submission_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
      v_review_reason_code := 'NO_PROVIDER_SUBMIT_ATTEMPT';
    END IF;

    IF COALESCE(v_provider_acceptance_evidence_count, 0) > 0
       AND (
         COALESCE(v_provider_submission_rejected_count, 0) > 0
         OR COALESCE(v_provider_submission_malformed_response_count, 0) > 0
         OR COALESCE(v_provider_submission_unknown_count, 0) > 0
         OR COALESCE(v_unfinalised_submit_chunk_count, 0) > 1
         OR COALESCE(v_affected_transfer_count, 0) > COALESCE(v_provider_acceptance_evidence_count, 0)
       ) THEN
      v_mixed_provider_submit_outcome := true;
      v_review_reason_code := 'MIXED_PROVIDER_SUBMIT_OUTCOME';
      v_manual_resolution_required := true;
    ELSE
      v_mixed_provider_submit_outcome := false;
      v_manual_resolution_required := v_provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');
    END IF;

    v_payment_provider_review_required := v_provider_submission_status IN (
      'PROVIDER_SUBMISSION_REJECTED',
      'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
      'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
      'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
    ) OR COALESCE(v_mixed_provider_submit_outcome, false) IS TRUE;
    v_safe_retry_available := false;

    v_chunk_provider_submit_diagnostic := jsonb_strip_nulls(
      COALESCE(v_chunk_provider_submit_diagnostic, '{}'::jsonb)
      || jsonb_build_object(
        'diagnostic_version', 1,
        'diagnostic_source', CASE WHEN v_diagnostic_was_existing THEN 'EXISTING_CHUNK_DIAGNOSTIC' ELSE 'EXACT_SCOPE_DIAGNOSTIC_GET' END,
        'generated_at_utc', v_now::text,
        'operation_id', p_operation_id::text,
        'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
        'chunk_id', v_target_chunk_row.id::text,
        'chunk_ids', jsonb_build_array(v_target_chunk_row.id::text),
        'transfer_ids', COALESCE(v_chunk_transfer_ids, '[]'::jsonb),
        'provider_submission_status', v_provider_submission_status,
        'review_reason_code', v_review_reason_code,
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_submission_rejected_count', COALESCE(v_provider_submission_rejected_count, 0),
        'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
        'provider_submission_malformed_response_count', COALESCE(v_provider_submission_malformed_response_count, 0),
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'unfinalised_submit_chunk_count', COALESCE(v_unfinalised_submit_chunk_count, 0),
        'manual_resolution_required', COALESCE(v_manual_resolution_required, false),
        'safe_retry_available', COALESCE(v_safe_retry_available, false),
        'payment_provider_review_required', COALESCE(v_payment_provider_review_required, false),
        'mixed_provider_submit_outcome', COALESCE(v_mixed_provider_submit_outcome, false),
        'recommended_action', CASE
          WHEN COALESCE(v_mixed_provider_submit_outcome, false) THEN 'Provider acceptance evidence exists for part of this chunk, but one or more outcomes remain unresolved. Reconcile before retry.'
          WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists. Do not retry unless reconciled.'
          WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected the payment submission. Review the provider response before retrying.'
          WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Check bank records before retrying.'
          WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission was blocked before the provider request was sent.'
          ELSE 'Provider request may have been sent, but no usable provider response was recorded. Check bank records before retrying.'
        END
      )
    );

    IF v_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED'
       AND COALESCE(v_mixed_provider_submit_outcome, false) IS NOT TRUE
       AND COALESCE(v_affected_transfer_count, 0) > 0
       AND COALESCE(v_provider_acceptance_evidence_count, 0) >= COALESCE(v_affected_transfer_count, 0) THEN
      v_finish_status := 'COMPLETE';
      v_completed_count := COALESCE(NULLIF(v_target_chunk_row.completed_count, 0), NULLIF(v_affected_transfer_count, 0), NULLIF(v_target_chunk_row.unit_count, 0), 0);
      v_failed_count := 0;
      v_message := 'Provider acceptance evidence was found while finalising the provider-submit chunk diagnostic.';
      v_result_json := jsonb_strip_nulls(
        COALESCE(v_target_chunk_row.result_json, '{}'::jsonb)
        || jsonb_build_object(
          'code', v_provider_submission_status,
          'message', v_message,
          'provider_submit_diagnostic', v_chunk_provider_submit_diagnostic,
          'diagnostic_finalised_at_utc', v_now::text,
          'diagnostic_finalise_reason_code', v_reason_code
        )
      );
      v_error_json := v_target_chunk_row.error_json;
    ELSE
      v_finish_status := 'FAILED';
      v_completed_count := COALESCE(v_target_chunk_row.completed_count, 0);
      v_failed_count := GREATEST(COALESCE(v_target_chunk_row.failed_count, 0), COALESCE(v_affected_transfer_count, 0), COALESCE(v_target_chunk_row.unit_count, 0), 1);
      v_message := CASE
        WHEN COALESCE(v_mixed_provider_submit_outcome, false) THEN 'Provider acceptance evidence exists for part of this provider-submit chunk, but one or more outcomes remain unresolved/rejected/malformed. Manual reconciliation is required before retry.'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'Provider rejected the payment submission.'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Manual reconciliation is required before retry.'
        WHEN v_provider_submission_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider submission was blocked before the provider payment request was sent.'
        ELSE 'Provider request may have been sent, but no usable provider response was recorded.'
      END;
      v_result_json := v_target_chunk_row.result_json;
      v_error_json := jsonb_strip_nulls(
        COALESCE(v_target_chunk_row.error_json, '{}'::jsonb)
        || jsonb_build_object(
          'code', COALESCE(v_review_reason_code, v_provider_submission_status),
          'provider_submission_status', v_provider_submission_status,
          'message', v_message,
          'provider_submit_diagnostic', v_chunk_provider_submit_diagnostic,
          'payment_provider_review_required', COALESCE(v_payment_provider_review_required, true),
          'manual_resolution_required', COALESCE(v_manual_resolution_required, false),
          'safe_retry_available', COALESCE(v_safe_retry_available, false),
          'failure_error_json', v_failure_error_json,
          'diagnostic_finalised_at_utc', v_now::text,
          'diagnostic_finalise_reason_code', v_reason_code
        )
      );
    END IF;

    SELECT finish_result.finished,
           finish_result.not_finished_reason
    INTO v_finished,
         v_not_finished_reason
    FROM public.banking_pay_operation_finish_chunk(
      p_chunk_id := v_target_chunk_row.id,
      p_status := v_finish_status,
      p_completed_count := v_completed_count,
      p_failed_count := v_failed_count,
      p_result_json := v_result_json,
      p_error_json := v_error_json
    ) AS finish_result
    LIMIT 1;

    SELECT operation_chunk_after.*
    INTO v_after_chunk_row
    FROM public.banking_pay_operation_chunks AS operation_chunk_after
    WHERE operation_chunk_after.id = v_target_chunk_row.id;

    v_after_json := to_jsonb(v_after_chunk_row);

    IF COALESCE(v_finished, false) IS TRUE THEN
      v_finalised_chunk_count := COALESCE(v_finalised_chunk_count, 0) + 1;
      v_finalised_chunk_ids := COALESCE(v_finalised_chunk_ids, '[]'::jsonb) || jsonb_build_array(v_target_chunk_row.id::text);
    ELSIF COALESCE(v_not_finished_reason, '') = 'ALREADY_TERMINAL' THEN
      v_already_terminal_chunk_count := COALESCE(v_already_terminal_chunk_count, 0) + 1;
      v_already_terminal_chunk_ids := COALESCE(v_already_terminal_chunk_ids, '[]'::jsonb) || jsonb_build_array(v_target_chunk_row.id::text);
    END IF;

    v_total_provider_request_sent_count := COALESCE(v_total_provider_request_sent_count, 0) + COALESCE(v_provider_request_sent_count, 0);
    v_total_provider_response_present_count := COALESCE(v_total_provider_response_present_count, 0) + COALESCE(v_provider_response_present_count, 0);
    v_total_provider_acceptance_evidence_count := COALESCE(v_total_provider_acceptance_evidence_count, 0) + COALESCE(v_provider_acceptance_evidence_count, 0);
    v_total_provider_submission_rejected_count := COALESCE(v_total_provider_submission_rejected_count, 0) + COALESCE(v_provider_submission_rejected_count, 0);
    v_total_provider_submission_unknown_count := COALESCE(v_total_provider_submission_unknown_count, 0) + COALESCE(v_provider_submission_unknown_count, 0);
    v_total_provider_submission_malformed_response_count := COALESCE(v_total_provider_submission_malformed_response_count, 0) + COALESCE(v_provider_submission_malformed_response_count, 0);
    v_total_unfinalised_submit_chunk_count := COALESCE(v_total_unfinalised_submit_chunk_count, 0) + COALESCE(v_unfinalised_submit_chunk_count, 0);
    v_total_affected_transfer_count := COALESCE(v_total_affected_transfer_count, 0) + COALESCE(v_affected_transfer_count, 0);
    v_manual_resolution_required_any := COALESCE(v_manual_resolution_required_any, false) OR COALESCE(v_manual_resolution_required, false);
    v_safe_retry_available_any := COALESCE(v_safe_retry_available_any, false) OR COALESCE(v_safe_retry_available, false);
    v_overall_provider_submit_diagnostic := jsonb_strip_nulls(v_overall_provider_submit_diagnostic || v_chunk_provider_submit_diagnostic);
    v_overall_provider_submission_status := COALESCE(v_provider_submission_status, v_overall_provider_submission_status);
    v_overall_review_reason_code := COALESCE(v_review_reason_code, v_overall_review_reason_code);

    BEGIN
      PERFORM public._audit_insert(
        'banking_pay_operation_chunks',
        v_target_chunk_row.id::text,
        'PAYMENT_PROVIDER_SUBMIT_CHUNK_DIAGNOSTIC_FINALISED',
        v_before_json,
        jsonb_build_object(
          'chunk', v_after_json,
          'previous_chunk_status', v_target_chunk_row.status,
          'new_chunk_status', CASE WHEN v_after_chunk_row.id IS NULL THEN NULL ELSE v_after_chunk_row.status END,
          'provider_submit_diagnostic', v_chunk_provider_submit_diagnostic,
          'provider_submission_status', v_provider_submission_status,
          'review_reason_code', v_review_reason_code,
          'finish_status', v_finish_status,
          'used_existing_chunk_diagnostic', v_diagnostic_was_existing,
          'reason_code', v_reason_code
        ),
        'payment_provider_submit_chunk_diagnostic_finalised',
        v_effective_actor_user_id
      );
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END LOOP;

  IF v_overall_provider_submit_diagnostic = '{}'::jsonb THEN
    v_overall_provider_submit_diagnostic := jsonb_strip_nulls(jsonb_build_object(
      'diagnostic_version', 1,
      'diagnostic_source', 'BOUNDED_PROVIDER_SUBMIT_CHUNK_FINALISE',
      'generated_at_utc', v_now::text,
      'operation_id', p_operation_id::text,
      'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
      'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
      'transfer_ids', COALESCE(v_all_transfer_ids, '[]'::jsonb),
      'provider_submission_status', COALESCE(v_overall_provider_submission_status, 'NO_PROVIDER_SUBMISSION_ATTEMPTED'),
      'review_reason_code', COALESCE(v_overall_review_reason_code, 'NO_PROVIDER_SUBMIT_ATTEMPT')
    ));
  END IF;

  v_overall_provider_submission_status := COALESCE(v_overall_provider_submission_status, v_overall_provider_submit_diagnostic->>'provider_submission_status', 'NO_PROVIDER_SUBMISSION_ATTEMPTED');
  v_overall_review_reason_code := COALESCE(v_overall_review_reason_code, v_overall_provider_submit_diagnostic->>'review_reason_code', 'NO_PROVIDER_SUBMIT_ATTEMPT');

  IF COALESCE(v_finalised_chunk_count, 0) > 0 THEN
    UPDATE public.banking_pay_operations AS operation_update
    SET progress_json = jsonb_strip_nulls(
          COALESCE(operation_update.progress_json, '{}'::jsonb)
          || jsonb_build_object(
            'provider_submit_diagnostic', v_overall_provider_submit_diagnostic,
            'provider_submission_status', v_overall_provider_submission_status,
            'provider_submit_diagnostic_finalised_at_utc', v_now::text,
            'provider_submit_diagnostic_finalise_reason_code', v_reason_code
          )
        ),
        result_json = CASE
          WHEN v_overall_provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN jsonb_strip_nulls(
            COALESCE(operation_update.result_json, '{}'::jsonb)
            || jsonb_build_object(
              'provider_submit_diagnostic', v_overall_provider_submit_diagnostic,
              'provider_submission_status', v_overall_provider_submission_status,
              'provider_submit_diagnostic_finalised_at_utc', v_now::text
            )
          )
          ELSE operation_update.result_json
        END,
        error_json = CASE
          WHEN v_overall_provider_submission_status <> 'PROVIDER_SUBMISSION_ACCEPTED' THEN jsonb_strip_nulls(
            COALESCE(operation_update.error_json, '{}'::jsonb)
            || jsonb_build_object(
              'provider_submit_diagnostic', v_overall_provider_submit_diagnostic,
              'provider_submission_status', v_overall_provider_submission_status,
              'review_reason_code', v_overall_review_reason_code,
              'provider_submit_diagnostic_finalised_at_utc', v_now::text,
              'provider_submit_diagnostic_finalise_reason_code', v_reason_code
            )
          )
          ELSE operation_update.error_json
        END,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id;

    BEGIN
      PERFORM public._audit_insert(
        'banking_pay_operations',
        p_operation_id::text,
        'PAYMENT_PROVIDER_SUBMIT_DIAGNOSTIC_FINALISED',
        NULL::jsonb,
        jsonb_build_object(
          'operation_id', p_operation_id::text,
          'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
          'finalised_chunk_count', COALESCE(v_finalised_chunk_count, 0),
          'finalised_chunk_ids', COALESCE(v_finalised_chunk_ids, '[]'::jsonb),
          'provider_submit_diagnostic', v_overall_provider_submit_diagnostic,
          'provider_submission_status', v_overall_provider_submission_status,
          'review_reason_code', v_overall_review_reason_code,
          'reason_code', v_reason_code
        ),
        'payment_provider_submit_diagnostic_finalised',
        v_effective_actor_user_id
      );
    EXCEPTION
      WHEN OTHERS THEN
        NULL;
    END;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'operation_id', p_operation_id::text,
    'pay_batch_id', CASE WHEN v_effective_pay_batch_id IS NULL THEN NULL ELSE v_effective_pay_batch_id::text END,
    'finalised_chunk_count', COALESCE(v_finalised_chunk_count, 0),
    'finalised_chunk_ids', COALESCE(v_finalised_chunk_ids, '[]'::jsonb),
    'already_terminal_chunk_count', COALESCE(v_already_terminal_chunk_count, 0),
    'already_terminal_chunk_ids', COALESCE(v_already_terminal_chunk_ids, '[]'::jsonb),
    'provider_submit_diagnostic', v_overall_provider_submit_diagnostic,
    'provider_submission_status', v_overall_provider_submission_status,
    'review_reason_code', v_overall_review_reason_code,
    'provider_request_sent_count', COALESCE(v_total_provider_request_sent_count, 0),
    'provider_response_present_count', COALESCE(v_total_provider_response_present_count, 0),
    'provider_submission_rejected_count', COALESCE(v_total_provider_submission_rejected_count, 0),
    'provider_submission_unknown_count', COALESCE(v_total_provider_submission_unknown_count, 0),
    'provider_submission_malformed_response_count', COALESCE(v_total_provider_submission_malformed_response_count, 0),
    'provider_acceptance_evidence_count', COALESCE(v_total_provider_acceptance_evidence_count, 0),
    'unfinalised_submit_chunk_count', COALESCE(v_total_unfinalised_submit_chunk_count, 0),
    'manual_resolution_required', COALESCE(v_manual_resolution_required_any, false),
    'safe_retry_available', COALESCE(v_safe_retry_available_any, false),
    'chunk_ids', COALESCE(v_chunk_ids, '[]'::jsonb),
    'transfer_ids', COALESCE(v_all_transfer_ids, '[]'::jsonb),
    'affected_transfer_count', COALESCE(v_total_affected_transfer_count, 0),
    'reason_code', v_reason_code,
    'message', CASE
      WHEN COALESCE(v_finalised_chunk_count, 0) > 0 THEN 'Provider-submit chunk diagnostic finalisation completed.'
      ELSE 'No running provider-submit chunks required diagnostic finalisation.'
    END
  );
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_execute_provider_submit_review_resolve(
  p_pay_batch_id uuid,
  p_operation_id uuid,
  p_resolution_action text,
  p_confirmation_json jsonb,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_resolution_action text := NULL::text;
  v_confirmation_json jsonb := '{}'::jsonb;
  v_checked_provider_or_bank boolean := false;
  v_confirmed_no_payment_made boolean := false;
  v_provider_checked text := NULL::text;
  v_checked_at_text text := NULL::text;
  v_checked_at_utc timestamptz := NULL::timestamptz;
  v_notes text := NULL::text;
  v_confirmation_redacted jsonb := '{}'::jsonb;
  v_operation_type text := NULL::text;
  v_operation_status text := NULL::text;
  v_operation_phase text := NULL::text;
  v_batch_execution_commit_state text := NULL::text;
  v_diagnostic_before_result jsonb := '{}'::jsonb;
  v_diagnostic_after_finalise_result jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic_before jsonb := '{}'::jsonb;
  v_provider_submit_diagnostic_after_finalise jsonb := '{}'::jsonb;
  v_manual_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_finalise_result jsonb := '{}'::jsonb;
  v_provider_submission_status text := NULL::text;
  v_manual_resolution_required boolean := false;
  v_provider_acceptance_evidence_count integer := 0;
  v_direct_provider_acceptance_evidence_count integer := 0;
  v_after_provider_acceptance_evidence_count integer := 0;
  v_chunk_ids jsonb := '[]'::jsonb;
  v_transfer_ids jsonb := '[]'::jsonb;
  v_transfer_scope_ids jsonb := '[]'::jsonb;
  v_auth_request_ids jsonb := '[]'::jsonb;
  v_resolved_chunk_ids jsonb := '[]'::jsonb;
  v_resolved_transfer_ids jsonb := '[]'::jsonb;
  v_resolved_transfer_scope_ids jsonb := '[]'::jsonb;
  v_cancelled_auth_request_ids jsonb := '[]'::jsonb;
  v_cleared_pay_batch_item_ids jsonb := '[]'::jsonb;
  v_manual_event_ids jsonb := '[]'::jsonb;
  v_auth_tokens_voided integer := 0;
  v_batch_rows_updated integer := 0;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_result jsonb := '{}'::jsonb;
  v_resolution_scope text := 'WHOLE_BATCH';
  v_requested_transfer_ids jsonb := '[]'::jsonb;
  v_requested_transfer_count integer := 0;
  v_selected_transfer_scope boolean := false;
  v_missing_requested_transfer_ids jsonb := '[]'::jsonb;
  v_unsafe_selected_transfer_ids jsonb := '[]'::jsonb;
  v_unsafe_selected_transfer_count integer := 0;
  v_effective_provider_acceptance_evidence_count integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_pay_batch_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_operation_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_execute_provider_submit_review_resolve requires p_actor_user_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_resolution_action := upper(btrim(coalesce(p_resolution_action, '')));
  IF v_resolution_action <> 'CONFIRM_NO_PAYMENT_MADE_AND_RESET_FOR_RETRY' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'UNSUPPORTED_RESOLUTION_ACTION',
      'message', 'Unsupported provider-submit review resolution action',
      'resolution_action', coalesce(p_resolution_action, '')
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_confirmation_json IS NULL OR jsonb_typeof(p_confirmation_json) <> 'object' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'CONFIRMATION_JSON_REQUIRED',
      'message', 'p_confirmation_json must be a JSON object'
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_confirmation_json := p_confirmation_json;
  v_checked_provider_or_bank := lower(btrim(coalesce(v_confirmation_json->>'checked_provider_or_bank', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_confirmed_no_payment_made := lower(btrim(coalesce(v_confirmation_json->>'confirmed_no_payment_made', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_checked := upper(btrim(coalesce(v_confirmation_json->>'provider_checked', '')));
  v_checked_at_text := NULLIF(btrim(coalesce(v_confirmation_json->>'checked_at_utc', '')), '');
  v_notes := NULLIF(btrim(coalesce(v_confirmation_json->>'notes', '')), '');
  v_resolution_scope := upper(btrim(coalesce(v_confirmation_json->>'resolution_scope', v_confirmation_json->>'scope', 'WHOLE_BATCH')));

  IF v_resolution_scope IN ('SINGLE', 'SINGLE_PAYMENT', 'PAYMENT') THEN
    v_resolution_scope := 'SINGLE_PAYMENT';
  ELSIF v_resolution_scope IN ('SELECTED', 'SELECTED_PAYMENT', 'SELECTED_PAYMENTS', 'MULTIPLE_PAYMENTS') THEN
    v_resolution_scope := 'SELECTED_PAYMENTS';
  ELSIF v_resolution_scope IN ('BATCH', 'WHOLE_BATCH', 'ALL') THEN
    v_resolution_scope := 'WHOLE_BATCH';
  ELSE
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'RESOLUTION_SCOPE_INVALID',
      'message', 'resolution_scope must be SINGLE_PAYMENT, SELECTED_PAYMENTS, or WHOLE_BATCH',
      'resolution_scope', COALESCE(v_confirmation_json->>'resolution_scope', v_confirmation_json->>'scope', '')
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(requested_transfer.transfer_id_text) ORDER BY requested_transfer.transfer_id_text), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_requested_transfer_ids, v_requested_transfer_count
  FROM (
    SELECT DISTINCT btrim(requested_transfer_text.value) AS transfer_id_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(COALESCE(v_confirmation_json->'pay_bank_transfer_ids', v_confirmation_json->'transfer_ids', v_confirmation_json->'selected_transfer_ids', '[]'::jsonb)) = 'array'
          THEN COALESCE(v_confirmation_json->'pay_bank_transfer_ids', v_confirmation_json->'transfer_ids', v_confirmation_json->'selected_transfer_ids', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS requested_transfer_text(value)
    WHERE btrim(requested_transfer_text.value) ~* v_uuid_regex
  ) AS requested_transfer;

  v_selected_transfer_scope := COALESCE(v_requested_transfer_count, 0) > 0 OR v_resolution_scope IN ('SINGLE_PAYMENT', 'SELECTED_PAYMENTS');

  IF v_selected_transfer_scope AND COALESCE(v_requested_transfer_count, 0) = 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'SELECTED_TRANSFER_IDS_REQUIRED',
      'message', 'Selected payment recovery requires pay_bank_transfer_ids in p_confirmation_json.',
      'resolution_scope', v_resolution_scope
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_resolution_scope = 'SINGLE_PAYMENT' AND COALESCE(v_requested_transfer_count, 0) <> 1 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'SINGLE_PAYMENT_REQUIRES_ONE_TRANSFER',
      'message', 'SINGLE_PAYMENT recovery requires exactly one pay_bank_transfer_id.',
      'selected_transfer_count', COALESCE(v_requested_transfer_count, 0)
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_checked_provider_or_bank IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'CHECKED_PROVIDER_OR_BANK_REQUIRED',
      'message', 'checked_provider_or_bank must be true'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_confirmed_no_payment_made IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'CONFIRMED_NO_PAYMENT_MADE_REQUIRED',
      'message', 'confirmed_no_payment_made must be true'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_provider_checked NOT IN ('REVOLUT', 'BANK', 'BOTH') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PROVIDER_CHECKED_INVALID',
      'message', 'provider_checked must be REVOLUT, BANK, or BOTH',
      'provider_checked', v_provider_checked
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_checked_at_text IS NULL THEN
    v_checked_at_utc := v_now;
  ELSE
    BEGIN
      v_checked_at_utc := v_checked_at_text::timestamptz;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
          'code', 'CHECKED_AT_UTC_INVALID',
          'message', 'checked_at_utc must be a valid timestamp when supplied',
          'checked_at_utc', v_checked_at_text
        )::text USING ERRCODE = 'P0001';
    END;
  END IF;

  v_confirmation_redacted := jsonb_strip_nulls(jsonb_build_object(
    'checked_provider_or_bank', true,
    'confirmed_no_payment_made', true,
    'provider_checked', v_provider_checked,
    'checked_at_utc', v_checked_at_utc::text,
    'notes_present', v_notes IS NOT NULL,
    'notes_length', CASE WHEN v_notes IS NULL THEN NULL ELSE char_length(v_notes) END,
    'resolution_scope', v_resolution_scope,
    'selected_transfer_ids', v_requested_transfer_ids,
    'recorded_at_utc', v_now::text,
    'recorded_by_user_id', p_actor_user_id::text
  ));

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'Pay batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_NOT_FOUND',
      'message', 'Operation not found',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NULL OR v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_BATCH_MISMATCH',
      'message', 'Operation does not belong to supplied pay batch',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_operation_type := upper(btrim(coalesce(v_operation_row.operation_type, '')));
  v_operation_status := upper(btrim(coalesce(v_operation_row.status, '')));
  v_operation_phase := upper(btrim(coalesce(v_operation_row.phase, '')));

  IF v_operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_TYPE_NOT_SUPPORTED',
      'message', 'Operation is not a payment execution operation',
      'operation_type', v_operation_row.operation_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_status <> 'REVIEW_REQUIRED' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_NOT_REVIEW_REQUIRED',
      'message', 'Operation must be REVIEW_REQUIRED before manual no-payment resolution',
      'operation_status', v_operation_row.status
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_phase NOT IN ('SUBMIT_PROVIDER_TRANSFERS', 'APPLY_RAIL_UPDATES', 'COMPLETE') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
      'code', 'OPERATION_PHASE_NOT_PROVIDER_SUBMIT_REVIEW',
      'message', 'Operation phase is not a provider-submit review phase',
      'operation_phase', v_operation_row.phase
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_batch_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_batch_execution_commit_state <> 'NOT_SUBMITTED'
     OR NULLIF(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'resolved', false,
      'reason', 'BATCH_EXECUTION_BOUNDARY_CROSSED',
      'safe_retry_available', false,
      'manual_resolution_recorded', false,
      'message', 'Batch execution boundary has been crossed. Manual reconciliation is required before retry.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text
    );
  END IF;

  v_diagnostic_before_result := public.pay_provider_submit_diagnostic_get(
    p_pay_batch_id := p_pay_batch_id,
    p_operation_id := p_operation_id,
    p_transfer_id := NULL::uuid,
    p_chunk_id := NULL::uuid,
    p_counts_only := false
  );

  v_provider_submit_diagnostic_before := COALESCE(v_diagnostic_before_result->'provider_submit_diagnostic', '{}'::jsonb);
  v_provider_submission_status := upper(btrim(coalesce(v_provider_submit_diagnostic_before->>'provider_submission_status', v_diagnostic_before_result->>'provider_submission_status', '')));
  v_manual_resolution_required := lower(btrim(coalesce(v_provider_submit_diagnostic_before->>'manual_resolution_required', v_diagnostic_before_result->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF COALESCE(v_diagnostic_before_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
    v_provider_acceptance_evidence_count := (v_diagnostic_before_result #>> '{counts,provider_acceptance_evidence_count}')::integer;
  ELSIF COALESCE(v_diagnostic_before_result->>'provider_evidence_count', '') ~ '^[0-9]+$' THEN
    v_provider_acceptance_evidence_count := (v_diagnostic_before_result->>'provider_evidence_count')::integer;
  ELSE
    v_provider_acceptance_evidence_count := 0;
  END IF;

  IF v_selected_transfer_scope IS NOT TRUE
     AND (
       (
         v_manual_resolution_required IS NOT TRUE
         AND v_provider_submission_status <> 'PROVIDER_SUBMISSION_REJECTED'
       )
       OR v_provider_submission_status NOT IN (
         'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
         'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
         'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
         'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
         'PROVIDER_SUBMISSION_REJECTED'
       )
     ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'resolved', false,
      'reason', 'PROVIDER_SUBMIT_REVIEW_STATE_NOT_ELIGIBLE',
      'safe_retry_available', false,
      'manual_resolution_recorded', false,
      'provider_submit_diagnostic', v_provider_submit_diagnostic_before,
      'provider_submission_status', v_provider_submission_status,
      'manual_resolution_required', v_manual_resolution_required,
      'message', 'Provider-submit review state is not eligible for no-payment manual resolution.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text
    );
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_review_chunks;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_review_transfers;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_review_scopes;
  DROP TABLE IF EXISTS pg_temp.tmp_provider_submit_review_auth_requests;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_review_chunks (
    chunk_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_review_transfers (
    transfer_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_review_scopes (
    scope_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  CREATE TEMPORARY TABLE pg_temp.tmp_provider_submit_review_auth_requests (
    auth_request_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_submit_review_chunks (chunk_id)
  SELECT operation_chunk.id
  FROM public.banking_pay_operation_chunks AS operation_chunk
  WHERE operation_chunk.operation_id = p_operation_id
    AND (operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS' OR operation_chunk.chunk_type = 'TRANSFER_SUBMIT')
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_transfers (transfer_id)
  SELECT DISTINCT transfer_id_text.value::uuid
  FROM public.banking_pay_operation_chunks AS operation_chunk
  JOIN pg_temp.tmp_provider_submit_review_chunks AS selected_chunk
    ON selected_chunk.chunk_id = operation_chunk.id
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(COALESCE(operation_chunk.payload_json, '{}'::jsonb)->'transfer_ids') = 'array' THEN COALESCE(operation_chunk.payload_json, '{}'::jsonb)->'transfer_ids'
      ELSE '[]'::jsonb
    END
  ) AS transfer_id_text(value)
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_transfers (transfer_id)
  SELECT DISTINCT transfer_id_text.value::uuid
  FROM public.banking_pay_operation_chunks AS operation_chunk
  JOIN pg_temp.tmp_provider_submit_review_chunks AS selected_chunk
    ON selected_chunk.chunk_id = operation_chunk.id
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(COALESCE(operation_chunk.payload_json, '{}'::jsonb)->'transfers') = 'array' THEN COALESCE(operation_chunk.payload_json, '{}'::jsonb)->'transfers'
      ELSE '[]'::jsonb
    END
  ) AS transfer_payload(value)
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      NULLIF(btrim(coalesce(transfer_payload.value->>'pay_bank_transfer_id', '')), ''),
      NULLIF(btrim(coalesce(transfer_payload.value->>'transfer_id', '')), '')
    ) AS value
  ) AS transfer_id_text
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_transfers (transfer_id)
  SELECT DISTINCT transfer_scope.pay_bank_transfer_id
  FROM public.banking_pay_operation_transfer_scope AS transfer_scope
  WHERE transfer_scope.operation_id = p_operation_id
    AND transfer_scope.pay_batch_id = p_pay_batch_id
    AND transfer_scope.pay_bank_transfer_id IS NOT NULL
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_transfers (transfer_id)
  SELECT DISTINCT transfer_id_text.value::uuid
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_provider_submit_diagnostic_before->'transfer_ids') = 'array' THEN v_provider_submit_diagnostic_before->'transfer_ids'
      ELSE '[]'::jsonb
    END
  ) AS transfer_id_text(value)
  WHERE transfer_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  IF v_selected_transfer_scope THEN
    SELECT COALESCE(jsonb_agg(to_jsonb(requested_transfer.transfer_id_text) ORDER BY requested_transfer.transfer_id_text), '[]'::jsonb)
    INTO v_missing_requested_transfer_ids
    FROM jsonb_array_elements_text(v_requested_transfer_ids) AS requested_transfer(transfer_id_text)
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
      WHERE selected_transfer.transfer_id = requested_transfer.transfer_id_text::uuid
    );

    IF jsonb_array_length(COALESCE(v_missing_requested_transfer_ids, '[]'::jsonb)) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_EXECUTE_PROVIDER_SUBMIT_REVIEW_RESOLVE',
        'code', 'SELECTED_TRANSFERS_NOT_IN_OPERATION_SCOPE',
        'message', 'Selected transfer ids are not part of the provider-submit review operation scope.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'selected_transfer_ids', v_requested_transfer_ids,
        'missing_transfer_ids', v_missing_requested_transfer_ids
      )::text USING ERRCODE = 'P0001';
    END IF;

    DELETE FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements_text(v_requested_transfer_ids) AS requested_transfer(transfer_id_text)
      WHERE requested_transfer.transfer_id_text::uuid = selected_transfer.transfer_id
    );
  END IF;

  INSERT INTO pg_temp.tmp_provider_submit_review_scopes (scope_id)
  SELECT transfer_scope.id
  FROM public.banking_pay_operation_transfer_scope AS transfer_scope
  WHERE transfer_scope.operation_id = p_operation_id
    AND transfer_scope.pay_batch_id = p_pay_batch_id
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_scopes (scope_id)
  SELECT DISTINCT scope_id_text.value::uuid
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_provider_submit_diagnostic_before->'transfer_scope_ids') = 'array' THEN v_provider_submit_diagnostic_before->'transfer_scope_ids'
      ELSE '[]'::jsonb
    END
  ) AS scope_id_text(value)
  WHERE scope_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  IF v_selected_transfer_scope THEN
    DELETE FROM pg_temp.tmp_provider_submit_review_scopes AS selected_scope
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS transfer_scope
      JOIN pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
        ON selected_transfer.transfer_id = transfer_scope.pay_bank_transfer_id
      WHERE transfer_scope.id = selected_scope.scope_id
        AND transfer_scope.operation_id = p_operation_id
        AND transfer_scope.pay_batch_id = p_pay_batch_id
    );
  END IF;

  INSERT INTO pg_temp.tmp_provider_submit_review_auth_requests (auth_request_id)
  SELECT auth_request.id
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND upper(btrim(coalesce(auth_request.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
    AND auth_request.execution_intent_json->>'operation_id' = p_operation_id::text
  ON CONFLICT DO NOTHING;

  INSERT INTO pg_temp.tmp_provider_submit_review_auth_requests (auth_request_id)
  SELECT DISTINCT auth_id_text.value::uuid
  FROM jsonb_array_elements_text(
    CASE
      WHEN jsonb_typeof(v_provider_submit_diagnostic_before->'auth_request_ids') = 'array' THEN v_provider_submit_diagnostic_before->'auth_request_ids'
      ELSE '[]'::jsonb
    END
  ) AS auth_id_text(value)
  WHERE auth_id_text.value ~* v_uuid_regex
  ON CONFLICT DO NOTHING;

  IF v_selected_transfer_scope THEN
    DELETE FROM pg_temp.tmp_provider_submit_review_auth_requests;
    DELETE FROM pg_temp.tmp_provider_submit_review_chunks;
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id::text), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_requested_transfer_ids, v_requested_transfer_count
  FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer;

  SELECT COUNT(*)::integer
  INTO v_direct_provider_acceptance_evidence_count
  FROM public.pay_bank_transfers AS transfer_row
  WHERE transfer_row.pay_batch_id = p_pay_batch_id
    AND EXISTS (
      SELECT 1
      FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
      WHERE selected_transfer.transfer_id = transfer_row.id
    )
    AND (
      (
        NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') IS NOT NULL
        AND NOT (
          NULLIF(btrim(coalesce(transfer_row.rail_tx_id, '')), '') = ANY(
            ARRAY_REMOVE(ARRAY[
              transfer_row.id::text,
              NULLIF(btrim(coalesce(transfer_row.request_id, '')), ''),
              NULLIF(btrim(coalesce(transfer_row.payment_reference, '')), ''),
              NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{payment_reference}', '')), ''),
              NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{bulk_reference}', '')), '')
            ]::text[], NULL::text)
          )
        )
        AND upper(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
      )
      OR (
        (
          (
            NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') IS NOT NULL
            AND NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') NOT IN (
              COALESCE(transfer_row.id::text, '__NO_TRANSFER_ID__'),
              COALESCE(NULLIF(btrim(coalesce(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__'),
              COALESCE(NULLIF(btrim(coalesce(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__'),
              COALESCE(NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''), '__NO_BULK_REFERENCE__')
            )
          )
          OR (
            NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL
            AND NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') NOT IN (
              COALESCE(transfer_row.id::text, '__NO_TRANSFER_ID__'),
              COALESCE(NULLIF(btrim(coalesce(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__'),
              COALESCE(NULLIF(btrim(coalesce(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__'),
              COALESCE(NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''), '__NO_BULK_REFERENCE__')
            )
          )
        )
        AND upper(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
      )
      OR EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS transfer_event
        WHERE transfer_event.pay_batch_id = p_pay_batch_id
          AND transfer_event.pay_bank_transfer_id = transfer_row.id
          AND upper(btrim(coalesce(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
          AND upper(btrim(coalesce(transfer_event.normalised_state, transfer_event.provider_state, transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
          AND upper(btrim(coalesce(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
          AND (
            EXISTS (
              SELECT 1
              FROM (VALUES
                (transfer_event.provider_event_id),
                (transfer_event.provider_reference),
                (transfer_event.raw_payload #>> '{provider_event_id}'),
                (transfer_event.raw_payload #>> '{provider_reference}'),
                (transfer_event.raw_payload #>> '{provider_submission_id}'),
                (transfer_event.raw_payload #>> '{submission_id}'),
                (transfer_event.raw_payload #>> '{rail_submission_id}'),
                (transfer_event.raw_payload #>> '{provider_payment_id}'),
                (transfer_event.raw_payload #>> '{payment_id}'),
                (transfer_event.raw_payload #>> '{external_payment_id}'),
                (transfer_event.raw_payload #>> '{revolut_payment_id}'),
                (transfer_event.raw_payload #>> '{provider_transfer_id}'),
                (transfer_event.raw_payload #>> '{external_transfer_id}'),
                (transfer_event.raw_payload #>> '{provider_transaction_id}'),
                (transfer_event.raw_payload #>> '{transaction_id}'),
                (transfer_event.raw_payload #>> '{rail_tx_id}'),
                (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                (transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                (transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
              ) AS provider_identifier(identifier_value)
              WHERE NULLIF(btrim(coalesce(provider_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (
                  NULLIF(btrim(coalesce(provider_identifier.identifier_value, '')), '') = ANY(
                    ARRAY_REMOVE(ARRAY[
                      transfer_row.id::text,
                      NULLIF(btrim(coalesce(transfer_row.request_id, '')), ''),
                      NULLIF(btrim(coalesce(transfer_row.payment_reference, '')), ''),
                      NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''),
                      NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_event.idempotency_key, '')), '')
                    ]::text[], NULL::text)
                  )
                )
            )
          )
      )
    );

  v_effective_provider_acceptance_evidence_count := CASE
    WHEN v_selected_transfer_scope THEN COALESCE(v_direct_provider_acceptance_evidence_count, 0)
    ELSE GREATEST(COALESCE(v_provider_acceptance_evidence_count, 0), COALESCE(v_direct_provider_acceptance_evidence_count, 0))
  END;

  IF COALESCE(v_effective_provider_acceptance_evidence_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'resolved', false,
      'reason', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT',
      'safe_retry_available', false,
      'manual_resolution_recorded', false,
      'message', 'Provider acceptance evidence exists. Manual reconciliation is required before retry.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'provider_submit_diagnostic', v_provider_submit_diagnostic_before,
      'provider_acceptance_evidence_count', COALESCE(v_effective_provider_acceptance_evidence_count, 0)
    );
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(unsafe_transfer.transfer_id::text) ORDER BY unsafe_transfer.transfer_id::text), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_unsafe_selected_transfer_ids, v_unsafe_selected_transfer_count
  FROM (
    SELECT transfer_row.id AS transfer_id
    FROM public.pay_bank_transfers AS transfer_row
    JOIN pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
      ON selected_transfer.transfer_id = transfer_row.id
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
      AND NOT (
        UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED', 'CANCELLED', 'RETURNED')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_state, ''))) IN ('FAILED', 'REJECTED', 'DECLINED', 'ERROR', 'CANCELLED', 'CANCELED', 'RETURNED', 'REVERTED', 'UNKNOWN')
        OR UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN (
          'PROVIDER_SUBMISSION_REJECTED',
          'PROVIDER_SUBMISSION_FAILED',
          'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
          'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
          'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
          'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
        )
      )
  ) AS unsafe_transfer;

  IF COALESCE(v_unsafe_selected_transfer_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'resolved', false,
      'reason', 'SELECTED_TRANSFERS_NOT_NO_PAYMENT_ELIGIBLE',
      'safe_retry_available', false,
      'manual_resolution_recorded', false,
      'message', 'One or more selected transfers are not failed, rejected, returned, or provider-review eligible.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'selected_transfer_ids', v_requested_transfer_ids,
      'unsafe_transfer_ids', v_unsafe_selected_transfer_ids
    );
  END IF;

  v_before_json := jsonb_build_object(
    'pay_batch', to_jsonb(v_batch_row),
    'operation', to_jsonb(v_operation_row),
    'chunks', COALESCE((
      SELECT jsonb_agg(to_jsonb(chunk_before) ORDER BY chunk_before.id::text)
      FROM public.banking_pay_operation_chunks AS chunk_before
      JOIN pg_temp.tmp_provider_submit_review_chunks AS selected_chunk
        ON selected_chunk.chunk_id = chunk_before.id
    ), '[]'::jsonb),
    'transfers', COALESCE((
      SELECT jsonb_agg(to_jsonb(transfer_before) ORDER BY transfer_before.id::text)
      FROM public.pay_bank_transfers AS transfer_before
      JOIN pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
        ON selected_transfer.transfer_id = transfer_before.id
    ), '[]'::jsonb),
    'transfer_scopes', COALESCE((
      SELECT jsonb_agg(to_jsonb(scope_before) ORDER BY scope_before.id::text)
      FROM public.banking_pay_operation_transfer_scope AS scope_before
      JOIN pg_temp.tmp_provider_submit_review_scopes AS selected_scope
        ON selected_scope.scope_id = scope_before.id
    ), '[]'::jsonb),
    'auth_requests', COALESCE((
      SELECT jsonb_agg(to_jsonb(auth_before) ORDER BY auth_before.id::text)
      FROM public.pay_batch_auth_requests AS auth_before
      JOIN pg_temp.tmp_provider_submit_review_auth_requests AS selected_auth
        ON selected_auth.auth_request_id = auth_before.id
    ), '[]'::jsonb),
    'provider_submit_diagnostic_before', v_provider_submit_diagnostic_before,
    'operator_confirmation', v_confirmation_redacted
  );

  IF v_selected_transfer_scope THEN
    v_finalise_result := jsonb_build_object(
      'ok', true,
      'skipped_for_selected_transfer_scope', true,
      'message', 'Selected-transfer recovery does not finalise whole provider-submit chunks.'
    );
    v_diagnostic_after_finalise_result := v_diagnostic_before_result;
    v_provider_submit_diagnostic_after_finalise := COALESCE(v_provider_submit_diagnostic_before, '{}'::jsonb);
    v_after_provider_acceptance_evidence_count := 0;
  ELSE
    v_finalise_result := public.pay_provider_submit_chunk_diagnostic_finalise(
      p_operation_id := p_operation_id,
      p_pay_batch_id := p_pay_batch_id,
      p_chunk_id := NULL::uuid,
      p_actor_user_id := p_actor_user_id,
      p_reason_code := 'MANUAL_NO_PAYMENT_RESOLUTION_FINALISE_PROVIDER_SUBMIT_CHUNKS',
      p_failure_error_json := jsonb_build_object(
        'provider_submit_diagnostic', v_provider_submit_diagnostic_before,
        'manual_resolution_action', v_resolution_action,
        'operator_confirmation', v_confirmation_redacted
      )
    );

    v_diagnostic_after_finalise_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := p_pay_batch_id,
      p_operation_id := p_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := NULL::uuid,
      p_counts_only := false
    );

    v_provider_submit_diagnostic_after_finalise := COALESCE(v_diagnostic_after_finalise_result->'provider_submit_diagnostic', v_provider_submit_diagnostic_before, '{}'::jsonb);

    IF COALESCE(v_diagnostic_after_finalise_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
      v_after_provider_acceptance_evidence_count := (v_diagnostic_after_finalise_result #>> '{counts,provider_acceptance_evidence_count}')::integer;
    ELSIF COALESCE(v_diagnostic_after_finalise_result->>'provider_evidence_count', '') ~ '^[0-9]+$' THEN
      v_after_provider_acceptance_evidence_count := (v_diagnostic_after_finalise_result->>'provider_evidence_count')::integer;
    ELSE
      v_after_provider_acceptance_evidence_count := 0;
    END IF;
  END IF;

  IF v_selected_transfer_scope IS NOT TRUE AND COALESCE(v_after_provider_acceptance_evidence_count, 0) > 0 THEN
    RETURN jsonb_build_object(
      'ok', false,
      'resolved', false,
      'reason', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT',
      'safe_retry_available', false,
      'manual_resolution_recorded', false,
      'message', 'Provider acceptance evidence exists. Manual reconciliation is required before retry.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'provider_submit_diagnostic', v_provider_submit_diagnostic_after_finalise,
      'provider_acceptance_evidence_count', v_after_provider_acceptance_evidence_count
    );
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_chunk.chunk_id::text) ORDER BY selected_chunk.chunk_id::text), '[]'::jsonb)
  INTO v_chunk_ids
  FROM pg_temp.tmp_provider_submit_review_chunks AS selected_chunk;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_transfer.transfer_id::text) ORDER BY selected_transfer.transfer_id::text), '[]'::jsonb)
  INTO v_transfer_ids
  FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_scope.scope_id::text) ORDER BY selected_scope.scope_id::text), '[]'::jsonb)
  INTO v_transfer_scope_ids
  FROM pg_temp.tmp_provider_submit_review_scopes AS selected_scope;

  SELECT COALESCE(jsonb_agg(to_jsonb(selected_auth.auth_request_id::text) ORDER BY selected_auth.auth_request_id::text), '[]'::jsonb)
  INTO v_auth_request_ids
  FROM pg_temp.tmp_provider_submit_review_auth_requests AS selected_auth;

  v_manual_provider_submit_diagnostic := jsonb_strip_nulls(
    COALESCE(v_provider_submit_diagnostic_after_finalise, '{}'::jsonb)
    || jsonb_build_object(
      'diagnostic_version', 1,
      'generated_at_utc', v_now::text,
      'review_reason_code', 'MANUAL_NO_PAYMENT_CONFIRMATION_RECORDED',
      'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
      'provider_submission_unknown', false,
      'provider_acceptance_evidence_present', false,
      'manual_resolution_required', false,
      'safe_retry_available', true,
      'automatic_retry_blocked', false,
      'retry_blocked_reason', NULL::text,
      'recommended_action', 'Manual no-payment confirmation recorded. The batch can now be retried using the existing frozen batch artefacts.',
      'manual_resolution_recorded', true,
      'resolved_at_utc', v_now::text,
      'resolved_by_user_id', p_actor_user_id::text,
      'operator_confirmation', v_confirmation_redacted,
      'resolution_scope', v_resolution_scope,
      'selected_transfer_scope', v_selected_transfer_scope,
      'selected_transfer_count', COALESCE(v_requested_transfer_count, 0),
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'chunk_ids', v_chunk_ids,
      'transfer_ids', v_transfer_ids,
      'transfer_scope_ids', v_transfer_scope_ids,
      'auth_request_ids', v_auth_request_ids
    )
  );

  WITH updated_chunks AS (
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET result_json = jsonb_strip_nulls(
          COALESCE(chunk_update.result_json, '{}'::jsonb)
          || jsonb_build_object(
            'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
            'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
            'manual_resolution_recorded', true,
            'manual_resolution_recorded_at_utc', v_now::text
          )
        ),
        error_json = jsonb_strip_nulls(
          COALESCE(chunk_update.error_json, '{}'::jsonb)
          || jsonb_build_object(
            'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
            'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
            'review_reason_code', 'MANUAL_NO_PAYMENT_CONFIRMATION_RECORDED',
            'manual_resolution_required', false,
            'safe_retry_available', true,
            'manual_resolution_recorded_at_utc', v_now::text
          )
        ),
        locked_by = NULL::text,
        lock_expires_at_utc = NULL::timestamptz,
        updated_at_utc = v_now
    FROM pg_temp.tmp_provider_submit_review_chunks AS selected_chunk
    WHERE chunk_update.id = selected_chunk.chunk_id
      AND chunk_update.operation_id = p_operation_id
    RETURNING chunk_update.id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(updated_chunks.id::text) ORDER BY updated_chunks.id::text), '[]'::jsonb)
  INTO v_resolved_chunk_ids
  FROM updated_chunks;

  WITH updated_transfers AS (
    UPDATE public.pay_bank_transfers AS transfer_update
    SET status = 'CANCELLED',
        failed_reason = 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
        rail_meta_json = jsonb_strip_nulls(
          COALESCE(transfer_update.rail_meta_json, '{}'::jsonb)
          || jsonb_build_object(
            'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
            'manual_resolution_recorded', true,
            'manual_resolution_recorded_at_utc', v_now::text,
            'manual_resolution_operation_id', p_operation_id::text,
            'operator_confirmation', v_confirmation_redacted
          )
        )
    FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
    WHERE transfer_update.id = selected_transfer.transfer_id
      AND transfer_update.pay_batch_id = p_pay_batch_id
      AND NOT (
        (
          NULLIF(btrim(coalesce(transfer_update.rail_tx_id, '')), '') IS NOT NULL
          AND NOT (
            NULLIF(btrim(coalesce(transfer_update.rail_tx_id, '')), '') = ANY(
              ARRAY_REMOVE(ARRAY[
                transfer_update.id::text,
                NULLIF(btrim(coalesce(transfer_update.request_id, '')), ''),
                NULLIF(btrim(coalesce(transfer_update.payment_reference, '')), ''),
                NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{request_id}', '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{idempotency_key}', '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{payment_reference}', '')), ''),
                NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{bulk_reference}', '')), '')
              ]::text[], NULL::text)
            )
          )
          AND upper(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
        )
        OR (
          (
            (
              NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') IS NOT NULL
              AND NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__NO_TRANSFER_ID__'),
                COALESCE(NULLIF(btrim(coalesce(transfer_update.request_id, '')), ''), '__NO_REQUEST_ID__'),
                COALESCE(NULLIF(btrim(coalesce(transfer_update.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__'),
                COALESCE(NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''), '__NO_BULK_REFERENCE__')
              )
            )
            OR (
              NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL
              AND NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__NO_TRANSFER_ID__'),
                COALESCE(NULLIF(btrim(coalesce(transfer_update.request_id, '')), ''), '__NO_REQUEST_ID__'),
                COALESCE(NULLIF(btrim(coalesce(transfer_update.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__'),
                COALESCE(NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''), '__NO_BULK_REFERENCE__')
              )
            )
          )
          AND upper(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
        )
        OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS manual_resolution_event_evidence
          WHERE manual_resolution_event_evidence.pay_batch_id = p_pay_batch_id
            AND manual_resolution_event_evidence.pay_bank_transfer_id = transfer_update.id
            AND upper(btrim(coalesce(manual_resolution_event_evidence.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
            AND upper(btrim(coalesce(manual_resolution_event_evidence.normalised_state, manual_resolution_event_evidence.provider_state, manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
            AND upper(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID', 'MANUAL_RESOLVED_NO_PAYMENT_MADE')
            AND EXISTS (
              SELECT 1
              FROM (VALUES
                (manual_resolution_event_evidence.provider_event_id),
                (manual_resolution_event_evidence.provider_reference),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_event_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_reference}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_submission_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{submission_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{rail_submission_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_payment_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{payment_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{external_payment_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{revolut_payment_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_transfer_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{external_transfer_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_transaction_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{transaction_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{rail_tx_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
                (manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_reference}')
              ) AS manual_resolution_event_identifier(identifier_value)
              WHERE NULLIF(btrim(coalesce(manual_resolution_event_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (
                  NULLIF(btrim(coalesce(manual_resolution_event_identifier.identifier_value, '')), '') = ANY(
                    ARRAY_REMOVE(ARRAY[
                      transfer_update.id::text,
                      NULLIF(btrim(coalesce(transfer_update.request_id, '')), ''),
                      NULLIF(btrim(coalesce(transfer_update.payment_reference, '')), ''),
                      NULLIF(btrim(coalesce(v_batch_row.bulk_reference, '')), ''),
                      NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{request_id}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,request_id}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,idempotency_key}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(btrim(coalesce(manual_resolution_event_evidence.idempotency_key, '')), '')
                    ]::text[], NULL::text)
                  )
                )
            )
        )
      )
    RETURNING transfer_update.id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(updated_transfers.id::text) ORDER BY updated_transfers.id::text), '[]'::jsonb)
  INTO v_resolved_transfer_ids
  FROM updated_transfers;

  WITH inserted_events AS (
    INSERT INTO public.pay_bank_transfer_events (
      pay_batch_id,
      pay_bank_transfer_id,
      candidate_id,
      umbrella_id,
      provider_key,
      provider_event_id,
      provider_reference,
      provider_state,
      normalised_state,
      event_source,
      event_time_utc,
      amount,
      currency,
      mapping_status,
      movement_classification,
      correction_disposition,
      raw_payload,
      idempotency_key,
      mapping_method
    )
    SELECT p_pay_batch_id,
           transfer_row.id,
           transfer_row.candidate_id,
           transfer_row.umbrella_id,
           transfer_row.rail_provider,
           NULL::text,
           NULL::text,
           'MANUAL_RESOLVED_NO_PAYMENT_MADE',
           'CANCELLED',
           'MANUAL_CONFIRM',
           v_now,
           transfer_row.amount,
           COALESCE(NULLIF(btrim(coalesce(transfer_row.currency, '')), ''), 'GBP'),
           'MATCHED',
           'PRE_BANK_CANCEL',
           'NO_CORRECTION_REQUIRED',
           jsonb_strip_nulls(jsonb_build_object(
             'event_kind', 'PROVIDER_SUBMIT_MANUAL_NO_PAYMENT_RESOLUTION',
             'confirmation_reason', 'NO_PAYMENT_MADE_CONFIRMED',
             'manual_event_source', 'MANUAL_CONFIRM',
             'manual_mapping_status', 'MATCHED',
             'manual_movement_classification', 'PRE_BANK_CANCEL',
             'manual_correction_disposition', 'NO_CORRECTION_REQUIRED',
             'manual_mapping_method', 'MANUAL_TRANSFER_SELECTION',
             'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
             'operator_confirmation', v_confirmation_redacted,
             'operation_id', p_operation_id::text,
             'resolved_at_utc', v_now::text,
             'resolved_by_user_id', p_actor_user_id::text
           )),
           'MANUAL_NO_PAYMENT_RESOLUTION|' || p_operation_id::text || '|' || transfer_row.id::text,
           'MANUAL_TRANSFER_SELECTION'
    FROM public.pay_bank_transfers AS transfer_row
    JOIN pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
      ON selected_transfer.transfer_id = transfer_row.id
    WHERE transfer_row.pay_batch_id = p_pay_batch_id
    ON CONFLICT (idempotency_key) DO NOTHING
    RETURNING id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(inserted_events.id::text) ORDER BY inserted_events.id::text), '[]'::jsonb)
  INTO v_manual_event_ids
  FROM inserted_events;

  WITH updated_scopes AS (
    UPDATE public.banking_pay_operation_transfer_scope AS scope_update
    SET status = 'SKIPPED',
        updated_at_utc = v_now
    FROM pg_temp.tmp_provider_submit_review_scopes AS selected_scope
    WHERE scope_update.id = selected_scope.scope_id
      AND scope_update.pay_batch_id = p_pay_batch_id
      AND scope_update.operation_id = p_operation_id
    RETURNING scope_update.id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(updated_scopes.id::text) ORDER BY updated_scopes.id::text), '[]'::jsonb)
  INTO v_resolved_transfer_scope_ids
  FROM updated_scopes;

  WITH cleared_items AS (
    UPDATE public.pay_batch_items AS item_update
    SET pay_bank_transfer_id = NULL::uuid,
        bank_reference = NULL::text,
        updated_at = v_now
    FROM pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.pay_batch_id = p_pay_batch_id
    WHERE item_update.pay_batch_candidate_id = batch_candidate.id
      AND item_update.pay_bank_transfer_id = selected_transfer.transfer_id
      AND COALESCE(item_update.is_voided, false) IS NOT TRUE
    RETURNING item_update.id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(cleared_items.id::text) ORDER BY cleared_items.id::text), '[]'::jsonb)
  INTO v_cleared_pay_batch_item_ids
  FROM cleared_items;

  WITH cancelled_auth_requests AS (
    UPDATE public.pay_batch_auth_requests AS auth_request_update
    SET state = 'CANCELLED',
        finalised_at_utc = COALESCE(auth_request_update.finalised_at_utc, v_now),
        finalised_by_user_id = COALESCE(auth_request_update.finalised_by_user_id, p_actor_user_id),
        execution_intent_json = jsonb_strip_nulls(
          COALESCE(auth_request_update.execution_intent_json, '{}'::jsonb)
          || jsonb_build_object(
            'manual_provider_submit_review_resolution', true,
            'manual_resolution_action', v_resolution_action,
            'manual_resolution_operation_id', p_operation_id::text,
            'manual_resolution_at_utc', v_now::text,
            'manual_resolution_by_user_id', p_actor_user_id::text,
            'operator_confirmation', v_confirmation_redacted,
            'provider_submit_diagnostic', v_manual_provider_submit_diagnostic
          )
        )
    FROM pg_temp.tmp_provider_submit_review_auth_requests AS selected_auth
    WHERE auth_request_update.id = selected_auth.auth_request_id
      AND auth_request_update.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(auth_request_update.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
    RETURNING auth_request_update.id
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(cancelled_auth_requests.id::text) ORDER BY cancelled_auth_requests.id::text), '[]'::jsonb)
  INTO v_cancelled_auth_request_ids
  FROM cancelled_auth_requests;

  WITH voided_auth_tokens AS (
    UPDATE public.pay_batch_auth_tokens AS auth_token_update
    SET used_at_utc = COALESCE(auth_token_update.used_at_utc, v_now),
        expires_at_utc = CASE
          WHEN auth_token_update.expires_at_utc > v_now THEN v_now
          ELSE auth_token_update.expires_at_utc
        END
    FROM pg_temp.tmp_provider_submit_review_auth_requests AS selected_auth
    WHERE auth_token_update.auth_request_id = selected_auth.auth_request_id
      AND (auth_token_update.used_at_utc IS NULL OR auth_token_update.expires_at_utc > v_now)
    RETURNING auth_token_update.token
  )
  SELECT COUNT(*)::integer
  INTO v_auth_tokens_voided
  FROM voided_auth_tokens;

  UPDATE public.pay_batches AS batch_update
  SET execution_intent_json = jsonb_strip_nulls(
        (
          CASE
            WHEN batch_update.execution_intent_json IS NOT NULL
             AND jsonb_typeof(batch_update.execution_intent_json) = 'object'
            THEN batch_update.execution_intent_json
            ELSE '{}'::jsonb
          END
        )
        || jsonb_build_object(
          'manual_provider_submit_review_resolution', true,
          'manual_resolution_action', v_resolution_action,
          'manual_resolution_operation_id', p_operation_id::text,
          'manual_resolution_at_utc', v_now::text,
          'manual_resolution_by_user_id', p_actor_user_id::text,
          'operator_confirmation', v_confirmation_redacted,
          'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
          'manual_resolution_preserved_schedule_kind', batch_update.schedule_kind,
          'manual_resolution_preserved_scheduled_at_utc', CASE WHEN batch_update.scheduled_at_utc IS NULL THEN NULL ELSE batch_update.scheduled_at_utc::text END,
          'manual_resolution_preserved_scheduled_by_user_id', CASE WHEN batch_update.scheduled_by_user_id IS NULL THEN NULL ELSE batch_update.scheduled_by_user_id::text END,
          'manual_resolution_preserved_funding_account_ref', batch_update.funding_account_ref,
          'manual_resolution_preserved_funds_warning_hours_json', batch_update.funds_warning_hours_json
        )
      )
  WHERE batch_update.id = p_pay_batch_id;

  GET DIAGNOSTICS v_batch_rows_updated = ROW_COUNT;

  UPDATE public.banking_pay_operations AS operation_update
  SET status = 'FAILED',
      progress_json = jsonb_strip_nulls(
        COALESCE(operation_update.progress_json, '{}'::jsonb)
        || jsonb_build_object(
          'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
          'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
          'manual_resolution_recorded', true,
          'manual_resolution_recorded_at_utc', v_now::text,
          'manual_resolution_by_user_id', p_actor_user_id::text
        )
      ),
      result_json = jsonb_strip_nulls(
        COALESCE(operation_update.result_json, '{}'::jsonb)
        || jsonb_build_object(
          'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
          'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
          'manual_provider_submit_review_resolution', true,
          'manual_resolution_recorded_at_utc', v_now::text,
          'manual_resolution_by_user_id', p_actor_user_id::text,
          'safe_retry_available', true
        )
      ),
      error_json = jsonb_strip_nulls(
        COALESCE(operation_update.error_json, '{}'::jsonb)
        || jsonb_build_object(
          'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
          'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
          'review_reason_code', 'MANUAL_NO_PAYMENT_CONFIRMATION_RECORDED',
          'manual_resolution_recorded', true,
          'manual_resolution_recorded_at_utc', v_now::text,
          'manual_resolution_by_user_id', p_actor_user_id::text,
          'safe_retry_available', true
        )
      ),
      failed_at_utc = COALESCE(operation_update.failed_at_utc, v_now),
      completed_at_utc = COALESCE(operation_update.completed_at_utc, v_now),
      locked_by = NULL::text,
      lock_expires_at_utc = NULL::timestamptz,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  SELECT jsonb_build_object(
    'pay_batch', (SELECT to_jsonb(batch_after) FROM public.pay_batches AS batch_after WHERE batch_after.id = p_pay_batch_id),
    'operation', (SELECT to_jsonb(operation_after) FROM public.banking_pay_operations AS operation_after WHERE operation_after.id = p_operation_id),
    'chunks', COALESCE((
      SELECT jsonb_agg(to_jsonb(chunk_after) ORDER BY chunk_after.id::text)
      FROM public.banking_pay_operation_chunks AS chunk_after
      JOIN pg_temp.tmp_provider_submit_review_chunks AS selected_chunk
        ON selected_chunk.chunk_id = chunk_after.id
    ), '[]'::jsonb),
    'transfers', COALESCE((
      SELECT jsonb_agg(to_jsonb(transfer_after) ORDER BY transfer_after.id::text)
      FROM public.pay_bank_transfers AS transfer_after
      JOIN pg_temp.tmp_provider_submit_review_transfers AS selected_transfer
        ON selected_transfer.transfer_id = transfer_after.id
    ), '[]'::jsonb),
    'transfer_scopes', COALESCE((
      SELECT jsonb_agg(to_jsonb(scope_after) ORDER BY scope_after.id::text)
      FROM public.banking_pay_operation_transfer_scope AS scope_after
      JOIN pg_temp.tmp_provider_submit_review_scopes AS selected_scope
        ON selected_scope.scope_id = scope_after.id
    ), '[]'::jsonb),
    'auth_requests', COALESCE((
      SELECT jsonb_agg(to_jsonb(auth_after) ORDER BY auth_after.id::text)
      FROM public.pay_batch_auth_requests AS auth_after
      JOIN pg_temp.tmp_provider_submit_review_auth_requests AS selected_auth
        ON selected_auth.auth_request_id = auth_after.id
    ), '[]'::jsonb),
    'manual_provider_submit_diagnostic', v_manual_provider_submit_diagnostic
  )
  INTO v_after_json;

  v_result := jsonb_build_object(
    'ok', true,
    'resolved', true,
    'resolution_status', 'COMPLETE',
    'manual_resolution_recorded', true,
    'safe_retry_available', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', p_operation_id::text,
    'provider_submit_diagnostic', v_manual_provider_submit_diagnostic,
    'provider_submission_status', 'MANUAL_RESOLVED_NO_PAYMENT_MADE',
    'review_reason_code', 'MANUAL_NO_PAYMENT_CONFIRMATION_RECORDED',
    'resolution_scope', v_resolution_scope,
    'selected_transfer_scope', v_selected_transfer_scope,
    'selected_transfer_count', COALESCE(v_requested_transfer_count, 0),
    'resolved_transfer_count', jsonb_array_length(COALESCE(v_resolved_transfer_ids, '[]'::jsonb)),
    'skipped_transfer_count', GREATEST(
      COALESCE(v_requested_transfer_count, 0)
      - jsonb_array_length(COALESCE(v_resolved_transfer_ids, '[]'::jsonb))
      - COALESCE(v_unsafe_selected_transfer_count, 0),
      0
    ),
    'unsafe_transfer_count', COALESCE(v_unsafe_selected_transfer_count, 0),
    'rejected_unsafe_transfer_count', COALESCE(v_unsafe_selected_transfer_count, 0),
    'affected_item_count', jsonb_array_length(COALESCE(v_cleared_pay_batch_item_ids, '[]'::jsonb)),
    'batch_remains_open', true,
    'batch_cancelled_or_released', false,
    'resolved_chunk_ids', COALESCE(v_resolved_chunk_ids, '[]'::jsonb),
    'resolved_transfer_ids', COALESCE(v_resolved_transfer_ids, '[]'::jsonb),
    'resolved_transfer_scope_ids', COALESCE(v_resolved_transfer_scope_ids, '[]'::jsonb),
    'cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb),
    'cleared_pay_batch_item_ids', COALESCE(v_cleared_pay_batch_item_ids, '[]'::jsonb),
    'manual_resolution_event_ids', COALESCE(v_manual_event_ids, '[]'::jsonb),
    'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
    'batch_rows_updated', COALESCE(v_batch_rows_updated, 0),
    'provider_submit_finalise_result', COALESCE(v_finalise_result, '{}'::jsonb),
    'message', 'Manual no-payment confirmation recorded. The batch can now be retried.'
  );

  BEGIN
    PERFORM public._audit_insert(
      'banking_pay_operations',
      p_operation_id::text,
      'PAYMENT_PROVIDER_SUBMIT_REVIEW_RESOLVED_NO_PAYMENT_MADE',
      v_before_json,
      v_after_json || jsonb_build_object('result', v_result),
      'payment_provider_submit_review_resolved_no_payment_made',
      p_actor_user_id
    );
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN v_result;
END;
$function$;







CREATE OR REPLACE FUNCTION public.pay_provider_submit_chunk_stage_record(
  p_operation_id uuid,
  p_pay_batch_id uuid,
  p_chunk_id uuid,
  p_transfer_ids jsonb DEFAULT '[]'::jsonb,
  p_stage text DEFAULT NULL::text,
  p_provider_submit_diagnostic jsonb DEFAULT '{}'::jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_uuid_regex text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';

  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_chunk_row public.banking_pay_operation_chunks%ROWTYPE;
  v_after_chunk_row public.banking_pay_operation_chunks%ROWTYPE;

  v_actor_user_id uuid := NULL::uuid;
  v_stage text := NULL::text;
  v_stage_upper text := NULL::text;
  v_input_diagnostic jsonb := '{}'::jsonb;
  v_helper_result jsonb := '{}'::jsonb;

  v_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_transfer_ids_json jsonb := '[]'::jsonb;
  v_transfer_count integer := 0;
  v_invalid_transfer_text_count integer := 0;
  v_missing_transfer_count integer := 0;

  v_primary_transfer_id text := NULL::text;
  v_primary_rail_provider text := NULL::text;
  v_primary_rail_env text := NULL::text;
  v_primary_rail_tx_id text := NULL::text;
  v_primary_rail_state text := NULL::text;
  v_primary_request_id text := NULL::text;
  v_primary_payment_reference text := NULL::text;
  v_batch_bulk_reference text := NULL::text;

  v_direct_acceptance_evidence_count integer := 0;
  v_direct_response_present_count integer := 0;
  v_direct_request_sent_count integer := 0;
  v_direct_rejection_count integer := 0;

  v_helper_acceptance_evidence_count integer := 0;
  v_helper_response_present_count integer := 0;
  v_helper_request_sent_count integer := 0;
  v_helper_unknown_count integer := 0;
  v_helper_rejected_count integer := 0;
  v_helper_malformed_count integer := 0;
  v_helper_blocked_pre_call_count integer := 0;

  v_provider_acceptance_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_rejection_count integer := 0;
  v_provider_unknown_count integer := 0;
  v_provider_malformed_count integer := 0;
  v_provider_blocked_pre_call_count integer := 0;

  v_existing_diagnostic jsonb := '{}'::jsonb;
  v_existing_diagnostic_source text := NULL::text;
  v_existing_status text := NULL::text;
  v_existing_review_reason_code text := NULL::text;
  v_existing_rank integer := 0;

  v_incoming_status text := NULL::text;
  v_incoming_review_reason_code text := NULL::text;
  v_incoming_rank integer := 0;
  v_incoming_diagnostic jsonb := '{}'::jsonb;

  v_final_status text := NULL::text;
  v_final_review_reason_code text := NULL::text;
  v_final_rank integer := 0;
  v_final_diagnostic jsonb := '{}'::jsonb;

  v_provider_call_stage text := NULL::text;
  v_provider_submission_attempted boolean := false;
  v_provider_request_sent boolean := false;
  v_provider_request_sent_confirmed boolean := false;
  v_provider_request_dispatched_at_utc text := NULL::text;
  v_provider_response_received boolean := false;
  v_provider_response_present boolean := false;
  v_provider_submission_accepted boolean := false;
  v_provider_submission_rejected boolean := false;
  v_provider_submission_failed boolean := false;
  v_provider_submission_unknown boolean := false;
  v_provider_acceptance_evidence_present boolean := false;
  v_provider_external_evidence_present boolean := false;
  v_manual_resolution_required boolean := false;
  v_safe_retry_available boolean := false;
  v_automatic_retry_blocked boolean := false;
  v_provider_request_impossible boolean := false;
  v_retry_blocked_reason text := NULL::text;
  v_recommended_action text := NULL::text;
  v_crash_safety_status_if_lock_expires text := NULL::text;

  v_provider_transaction_id text := NULL::text;
  v_provider_reference text := NULL::text;
  v_provider_state text := NULL::text;
  v_rail_tx_id text := NULL::text;
  v_rail_state text := NULL::text;
  v_request_id text := NULL::text;
  v_idempotency_key text := NULL::text;
  v_local_provider_request_id text := NULL::text;
  v_provider_http_status text := NULL::text;
  v_provider_error_code text := NULL::text;
  v_provider_error_message_redacted text := NULL::text;
  v_provider_response_redacted jsonb := NULL::jsonb;
  v_provider_error_redacted jsonb := NULL::jsonb;

  v_chunk_lock_expired boolean := false;
  v_unfinalised_submit_chunk boolean := false;
  v_apply_incoming boolean := true;
  v_preserved_stronger_provider_evidence boolean := false;

  v_chunk_result_before jsonb := '{}'::jsonb;
  v_chunk_result_after jsonb := '{}'::jsonb;
  v_operation_progress_after jsonb := '{}'::jsonb;
  v_stage_history jsonb := '[]'::jsonb;
  v_stage_history_entry jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
BEGIN
  IF p_operation_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'OPERATION_ID_REQUIRED',
      'message', 'pay_provider_submit_chunk_stage_record requires p_operation_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_provider_submit_chunk_stage_record requires p_pay_batch_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_chunk_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'CHUNK_ID_REQUIRED',
      'message', 'pay_provider_submit_chunk_stage_record requires p_chunk_id'
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF p_provider_submit_diagnostic IS NULL THEN
    v_input_diagnostic := '{}'::jsonb;
  ELSIF jsonb_typeof(p_provider_submit_diagnostic) = 'object' THEN
    v_input_diagnostic := p_provider_submit_diagnostic;
  ELSE
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'PROVIDER_SUBMIT_DIAGNOSTIC_MUST_BE_OBJECT',
      'message', 'pay_provider_submit_chunk_stage_record requires p_provider_submit_diagnostic to be a JSON object when supplied',
      'json_type', jsonb_typeof(p_provider_submit_diagnostic)
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_input_diagnostic := v_input_diagnostic
    - 'access_token'
    - 'authorization'
    - 'Authorization'
    - 'bearer_token'
    - 'token'
    - 'account_number'
    - 'sort_code'
    - 'iban'
    - 'source_account_number'
    - 'beneficiary_account_number';

  v_stage := NULLIF(BTRIM(COALESCE(p_stage, v_input_diagnostic->>'provider_call_stage', v_input_diagnostic->>'stage', '')), '');
  IF v_stage IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'STAGE_REQUIRED',
      'message', 'pay_provider_submit_chunk_stage_record requires p_stage or provider_submit_diagnostic.provider_call_stage'
    )::text USING ERRCODE = 'P0001';
  END IF;
  v_stage_upper := UPPER(v_stage);

  SELECT operation_row.*
  INTO v_operation_row
  FROM public.banking_pay_operations AS operation_row
  WHERE operation_row.id = p_operation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'OPERATION_NOT_FOUND',
      'message', 'pay_provider_submit_chunk_stage_record: operation not found',
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.operation_type NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'NOT_PROVIDER_SUBMIT_OPERATION',
      'message', 'pay_provider_submit_chunk_stage_record can only be used for payment execution provider-submit operations',
      'operation_id', p_operation_id::text,
      'operation_type', v_operation_row.operation_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_operation_row.pay_batch_id IS NULL OR v_operation_row.pay_batch_id <> p_pay_batch_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'OPERATION_BATCH_MISMATCH',
      'message', 'pay_provider_submit_chunk_stage_record: operation does not belong to supplied pay batch',
      'operation_id', p_operation_id::text,
      'operation_pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT NULLIF(BTRIM(COALESCE(batch_row.bulk_reference, '')), '')
  INTO v_batch_bulk_reference
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_provider_submit_chunk_stage_record: pay batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT chunk_row.*
  INTO v_chunk_row
  FROM public.banking_pay_operation_chunks AS chunk_row
  WHERE chunk_row.id = p_chunk_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'CHUNK_NOT_FOUND',
      'message', 'pay_provider_submit_chunk_stage_record: chunk not found',
      'chunk_id', p_chunk_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF v_chunk_row.operation_id <> p_operation_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'CHUNK_OPERATION_MISMATCH',
      'message', 'pay_provider_submit_chunk_stage_record: chunk does not belong to supplied operation',
      'chunk_id', p_chunk_id::text,
      'chunk_operation_id', v_chunk_row.operation_id::text,
      'operation_id', p_operation_id::text
    )::text USING ERRCODE = 'P0001';
  END IF;

  IF NOT (UPPER(BTRIM(COALESCE(v_chunk_row.phase, ''))) = 'SUBMIT_PROVIDER_TRANSFERS' OR UPPER(BTRIM(COALESCE(v_chunk_row.chunk_type, ''))) = 'TRANSFER_SUBMIT') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'NOT_PROVIDER_SUBMIT_CHUNK',
      'message', 'pay_provider_submit_chunk_stage_record: chunk is not a provider-submit transfer chunk',
      'chunk_id', p_chunk_id::text,
      'phase', v_chunk_row.phase,
      'chunk_type', v_chunk_row.chunk_type
    )::text USING ERRCODE = 'P0001';
  END IF;

  v_actor_user_id := COALESCE(p_actor_user_id, v_operation_row.actor_user_id);
  v_chunk_lock_expired := UPPER(BTRIM(COALESCE(v_chunk_row.status, ''))) = 'RUNNING'
    AND v_chunk_row.completed_at_utc IS NULL
    AND (v_chunk_row.lock_expires_at_utc IS NULL OR v_chunk_row.lock_expires_at_utc < v_now);
  v_unfinalised_submit_chunk := UPPER(BTRIM(COALESCE(v_chunk_row.status, ''))) = 'RUNNING'
    AND v_chunk_row.completed_at_utc IS NULL;

  WITH raw_items AS (
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN p_transfer_ids IS NOT NULL AND jsonb_typeof(p_transfer_ids) = 'array' THEN p_transfer_ids ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_input_diagnostic->'transfer_ids') = 'array' THEN v_input_diagnostic->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT to_jsonb(v_input_diagnostic->>'transfer_id') AS item
    WHERE NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'transfer_id', '')), '') IS NOT NULL
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfer_ids') = 'array' THEN v_chunk_row.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfers') = 'array' THEN v_chunk_row.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_element(value)
  ), raw_texts AS (
    SELECT NULLIF(BTRIM(COALESCE(
      CASE
        WHEN jsonb_typeof(raw_items.item) = 'string' THEN raw_items.item #>> '{}'
        WHEN jsonb_typeof(raw_items.item) = 'object' THEN COALESCE(
          raw_items.item->>'pay_bank_transfer_id',
          raw_items.item->>'transfer_id',
          raw_items.item->>'id'
        )
        ELSE NULL::text
      END,
      ''
    )), '') AS transfer_id_text
    FROM raw_items
  ), valid_ids AS (
    SELECT DISTINCT raw_texts.transfer_id_text::uuid AS transfer_id
    FROM raw_texts
    WHERE raw_texts.transfer_id_text ~* v_uuid_regex
  )
  SELECT COALESCE(array_agg(valid_ids.transfer_id ORDER BY valid_ids.transfer_id), ARRAY[]::uuid[]),
         COALESCE(jsonb_agg(to_jsonb(valid_ids.transfer_id::text) ORDER BY valid_ids.transfer_id), '[]'::jsonb),
         COUNT(*)::integer
  INTO v_transfer_ids,
       v_transfer_ids_json,
       v_transfer_count
  FROM valid_ids;

  WITH raw_items AS (
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN p_transfer_ids IS NOT NULL AND jsonb_typeof(p_transfer_ids) = 'array' THEN p_transfer_ids ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_input_diagnostic->'transfer_ids') = 'array' THEN v_input_diagnostic->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT to_jsonb(v_input_diagnostic->>'transfer_id') AS item
    WHERE NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'transfer_id', '')), '') IS NOT NULL
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfer_ids') = 'array' THEN v_chunk_row.payload_json->'transfer_ids' ELSE '[]'::jsonb END) AS transfer_element(value)
    UNION ALL
    SELECT transfer_element.value AS item
    FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_chunk_row.payload_json->'transfers') = 'array' THEN v_chunk_row.payload_json->'transfers' ELSE '[]'::jsonb END) AS transfer_element(value)
  ), raw_texts AS (
    SELECT NULLIF(BTRIM(COALESCE(
      CASE
        WHEN jsonb_typeof(raw_items.item) = 'string' THEN raw_items.item #>> '{}'
        WHEN jsonb_typeof(raw_items.item) = 'object' THEN COALESCE(
          raw_items.item->>'pay_bank_transfer_id',
          raw_items.item->>'transfer_id',
          raw_items.item->>'id'
        )
        ELSE NULL::text
      END,
      ''
    )), '') AS transfer_id_text
    FROM raw_items
  )
  SELECT COUNT(*)::integer
  INTO v_invalid_transfer_text_count
  FROM raw_texts
  WHERE raw_texts.transfer_id_text IS NOT NULL
    AND raw_texts.transfer_id_text !~* v_uuid_regex;

  IF COALESCE(v_invalid_transfer_text_count, 0) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'INVALID_TRANSFER_ID',
      'message', 'pay_provider_submit_chunk_stage_record: one or more supplied transfer IDs are not UUIDs',
      'invalid_transfer_id_count', v_invalid_transfer_text_count
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT COUNT(*)::integer
  INTO v_missing_transfer_count
  FROM unnest(v_transfer_ids) AS selected_transfer(transfer_id)
  LEFT JOIN public.pay_bank_transfers AS transfer_check
    ON transfer_check.id = selected_transfer.transfer_id
   AND transfer_check.pay_batch_id = p_pay_batch_id
  WHERE transfer_check.id IS NULL;

  IF COALESCE(v_missing_transfer_count, 0) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_PROVIDER_SUBMIT_CHUNK_STAGE_RECORD',
      'code', 'TRANSFER_BATCH_MISMATCH_OR_NOT_FOUND',
      'message', 'pay_provider_submit_chunk_stage_record: one or more transfer IDs do not exist or do not belong to the supplied pay batch',
      'pay_batch_id', p_pay_batch_id::text,
      'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
      'missing_or_wrong_batch_transfer_count', v_missing_transfer_count
    )::text USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    v_helper_result := public.pay_provider_submit_diagnostic_get(
      p_pay_batch_id := p_pay_batch_id,
      p_operation_id := p_operation_id,
      p_transfer_id := NULL::uuid,
      p_chunk_id := p_chunk_id,
      p_counts_only := true
    );
  EXCEPTION
    WHEN undefined_function THEN
      v_helper_result := '{}'::jsonb;
    WHEN OTHERS THEN
      v_helper_result := '{}'::jsonb;
  END;

  IF COALESCE(v_helper_result #>> '{counts,provider_acceptance_evidence_count}', '') ~ '^[0-9]+$' THEN
    v_helper_acceptance_evidence_count := (v_helper_result #>> '{counts,provider_acceptance_evidence_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_response_present_count}', '') ~ '^[0-9]+$' THEN
    v_helper_response_present_count := (v_helper_result #>> '{counts,provider_response_present_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_request_sent_count}', '') ~ '^[0-9]+$' THEN
    v_helper_request_sent_count := (v_helper_result #>> '{counts,provider_request_sent_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_submission_unknown_count}', '') ~ '^[0-9]+$' THEN
    v_helper_unknown_count := (v_helper_result #>> '{counts,provider_submission_unknown_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_submission_rejected_count}', '') ~ '^[0-9]+$' THEN
    v_helper_rejected_count := (v_helper_result #>> '{counts,provider_submission_rejected_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_submission_malformed_response_count}', '') ~ '^[0-9]+$' THEN
    v_helper_malformed_count := (v_helper_result #>> '{counts,provider_submission_malformed_response_count}')::integer;
  END IF;
  IF COALESCE(v_helper_result #>> '{counts,provider_submission_blocked_pre_call_count}', '') ~ '^[0-9]+$' THEN
    v_helper_blocked_pre_call_count := (v_helper_result #>> '{counts,provider_submission_blocked_pre_call_count}')::integer;
  END IF;

  SELECT COUNT(DISTINCT transfer_row.id) FILTER (
          WHERE (
               NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') <> transfer_row.id::text
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
               AND UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             )
             OR (
               NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') <> transfer_row.id::text
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
               AND UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             )
             OR (
               NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') <> transfer_row.id::text
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
               AND NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
               AND UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
             )
             OR COALESCE(event_flags.has_provider_acceptance_evidence, false) IS TRUE
        )::integer,
        COUNT(DISTINCT transfer_row.id) FILTER (
           WHERE lower(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') IS NOT NULL
              OR COALESCE(event_flags.has_provider_response, false) IS TRUE
         )::integer,
         COUNT(DISTINCT transfer_row.id) FILTER (
           WHERE lower(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
              OR COALESCE(event_flags.has_provider_response, false) IS TRUE
              OR NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), '') IS NOT NULL
         )::integer,
         COUNT(DISTINCT transfer_row.id) FILTER (
           WHERE UPPER(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')
              OR COALESCE(event_flags.has_provider_rejection, false) IS TRUE
              OR CASE WHEN NULLIF(BTRIM(COALESCE(transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}', '')), '') ~ '^[0-9]+$' THEN (transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_http_status}')::integer >= 400 ELSE false END
         )::integer
  INTO v_direct_acceptance_evidence_count,
       v_direct_response_present_count,
       v_direct_request_sent_count,
       v_direct_rejection_count
  FROM public.pay_bank_transfers AS transfer_row
  JOIN unnest(v_transfer_ids) AS selected_transfer(transfer_id)
    ON selected_transfer.transfer_id = transfer_row.id
  LEFT JOIN LATERAL (
    SELECT COALESCE(BOOL_OR(UPPER(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')), false) AS has_provider_response,
           COALESCE(BOOL_OR(
             UPPER(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             AND (
               (
                 NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
               )
               OR (
                 NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
               )
               OR (
                 NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}', transfer_event.raw_payload #>> '{provider_transaction_id}', transfer_event.raw_payload #>> '{provider_payment_id}', transfer_event.raw_payload #>> '{payment_id}', transfer_event.raw_payload #>> '{external_payment_id}', transfer_event.raw_payload #>> '{revolut_payment_id}', transfer_event.raw_payload #>> '{provider_reference}', transfer_event.raw_payload #>> '{rail_tx_id}', '')), '') IS NOT NULL
                 AND NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}', transfer_event.raw_payload #>> '{provider_transaction_id}', transfer_event.raw_payload #>> '{provider_payment_id}', transfer_event.raw_payload #>> '{payment_id}', transfer_event.raw_payload #>> '{external_payment_id}', transfer_event.raw_payload #>> '{revolut_payment_id}', transfer_event.raw_payload #>> '{provider_reference}', transfer_event.raw_payload #>> '{rail_tx_id}', '')), '') <> transfer_row.id::text
                 AND NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}', transfer_event.raw_payload #>> '{provider_transaction_id}', transfer_event.raw_payload #>> '{provider_payment_id}', transfer_event.raw_payload #>> '{payment_id}', transfer_event.raw_payload #>> '{external_payment_id}', transfer_event.raw_payload #>> '{revolut_payment_id}', transfer_event.raw_payload #>> '{provider_reference}', transfer_event.raw_payload #>> '{rail_tx_id}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''), '__NO_REQUEST_ID__')
                 AND NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}', transfer_event.raw_payload #>> '{provider_transaction_id}', transfer_event.raw_payload #>> '{provider_payment_id}', transfer_event.raw_payload #>> '{payment_id}', transfer_event.raw_payload #>> '{external_payment_id}', transfer_event.raw_payload #>> '{revolut_payment_id}', transfer_event.raw_payload #>> '{provider_reference}', transfer_event.raw_payload #>> '{rail_tx_id}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
                 AND NULLIF(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}', transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_reference}', transfer_event.raw_payload #>> '{provider_transaction_id}', transfer_event.raw_payload #>> '{provider_payment_id}', transfer_event.raw_payload #>> '{payment_id}', transfer_event.raw_payload #>> '{external_payment_id}', transfer_event.raw_payload #>> '{revolut_payment_id}', transfer_event.raw_payload #>> '{provider_reference}', transfer_event.raw_payload #>> '{rail_tx_id}', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), ''), '__NO_EVENT_IDEMPOTENCY_KEY__')
               )
             )
             AND UPPER(BTRIM(COALESCE(transfer_event.normalised_state, transfer_event.provider_state, ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')
           ), false) AS has_provider_acceptance_evidence,
           COALESCE(BOOL_OR(
             UPPER(BTRIM(COALESCE(transfer_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK')
             AND (
               UPPER(BTRIM(COALESCE(transfer_event.normalised_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')
               OR UPPER(BTRIM(COALESCE(transfer_event.provider_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED')
               OR UPPER(BTRIM(COALESCE(transfer_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')
             )
           ), false) AS has_provider_rejection
    FROM public.pay_bank_transfer_events AS transfer_event
    WHERE transfer_event.pay_bank_transfer_id = transfer_row.id
  ) AS event_flags ON true;

  v_provider_acceptance_evidence_count := GREATEST(COALESCE(v_helper_acceptance_evidence_count, 0), COALESCE(v_direct_acceptance_evidence_count, 0));
  v_provider_response_present_count := GREATEST(COALESCE(v_helper_response_present_count, 0), COALESCE(v_direct_response_present_count, 0));
  v_provider_request_sent_count := GREATEST(COALESCE(v_helper_request_sent_count, 0), COALESCE(v_direct_request_sent_count, 0));
  v_provider_rejection_count := GREATEST(COALESCE(v_helper_rejected_count, 0), COALESCE(v_direct_rejection_count, 0));
  v_provider_unknown_count := COALESCE(v_helper_unknown_count, 0);
  v_provider_malformed_count := COALESCE(v_helper_malformed_count, 0);
  v_provider_blocked_pre_call_count := COALESCE(v_helper_blocked_pre_call_count, 0);

  SELECT transfer_row.id::text,
         transfer_row.rail_provider,
         transfer_row.rail_env,
         NULLIF(BTRIM(COALESCE(transfer_row.rail_tx_id, '')), ''),
         NULLIF(BTRIM(COALESCE(transfer_row.rail_state, '')), ''),
         NULLIF(BTRIM(COALESCE(transfer_row.request_id, '')), ''),
         NULLIF(BTRIM(COALESCE(transfer_row.payment_reference, '')), '')
  INTO v_primary_transfer_id,
       v_primary_rail_provider,
       v_primary_rail_env,
       v_primary_rail_tx_id,
       v_primary_rail_state,
       v_primary_request_id,
       v_primary_payment_reference
  FROM public.pay_bank_transfers AS transfer_row
  JOIN unnest(v_transfer_ids) AS selected_transfer(transfer_id)
    ON selected_transfer.transfer_id = transfer_row.id
  ORDER BY transfer_row.created_at_utc NULLS FIRST, transfer_row.id
  LIMIT 1;

  SELECT candidate_ranked.diagnostic,
         candidate_ranked.source_name,
         candidate_ranked.precedence_rank,
         NULLIF(UPPER(BTRIM(COALESCE(candidate_ranked.diagnostic->>'provider_submission_status', ''))), ''),
         NULLIF(BTRIM(COALESCE(candidate_ranked.diagnostic->>'review_reason_code', '')), '')
  INTO v_existing_diagnostic,
       v_existing_diagnostic_source,
       v_existing_rank,
       v_existing_status,
       v_existing_review_reason_code
  FROM (
    SELECT candidate_source.source_name,
           candidate_source.source_order,
           candidate_source.diagnostic,
           CASE
             WHEN (
                NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_transaction_id', candidate_source.diagnostic->>'provider_payment_id', candidate_source.diagnostic->>'rail_tx_id', '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_transaction_id', candidate_source.diagnostic->>'provider_payment_id', candidate_source.diagnostic->>'rail_tx_id', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'request_id', '')), ''), '__NO_REQUEST_ID__')
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_transaction_id', candidate_source.diagnostic->>'provider_payment_id', candidate_source.diagnostic->>'rail_tx_id', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'idempotency_key', '')), ''), '__NO_IDEMPOTENCY_KEY__')
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_transaction_id', candidate_source.diagnostic->>'provider_payment_id', candidate_source.diagnostic->>'rail_tx_id', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'local_provider_request_id', '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                AND UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
              )
              OR (
                NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_reference', '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_reference', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'request_id', '')), ''), '__NO_REQUEST_ID__')
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_reference', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'idempotency_key', '')), ''), '__NO_IDEMPOTENCY_KEY__')
                AND NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_reference', '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'local_provider_request_id', '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
                AND UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
              ) THEN 500
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) = 'MANUAL_RESOLVED_NO_PAYMENT_MADE' THEN 450
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')
               OR lower(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_rejected', candidate_source.diagnostic->>'provider_rejected', candidate_source.diagnostic->>'provider_submission_failed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR CASE WHEN NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_http_status', '')), '') ~ '^[0-9]+$' THEN (candidate_source.diagnostic->>'provider_http_status')::integer >= 400 ELSE false END THEN 420
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
               OR lower(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_response_present', candidate_source.diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
               OR NULLIF(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_error_code', '')), '') IS NOT NULL THEN 400
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK')
               OR lower(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') THEN 300
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 200
             WHEN UPPER(BTRIM(COALESCE(candidate_source.diagnostic->>'provider_submission_status', ''))) = 'NO_PROVIDER_SUBMISSION_ATTEMPTED' THEN 100
             ELSE 0
           END AS precedence_rank
    FROM (
      SELECT 'chunk_result'::text AS source_name,
             1 AS source_order,
             CASE WHEN jsonb_typeof(v_chunk_row.result_json->'provider_submit_diagnostic') = 'object' THEN v_chunk_row.result_json->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
      UNION ALL
      SELECT 'chunk_error'::text AS source_name,
             2 AS source_order,
             CASE WHEN jsonb_typeof(v_chunk_row.error_json->'provider_submit_diagnostic') = 'object' THEN v_chunk_row.error_json->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
      UNION ALL
      SELECT 'operation_progress'::text AS source_name,
             3 AS source_order,
             CASE WHEN jsonb_typeof(v_operation_row.progress_json->'provider_submit_diagnostic') = 'object' THEN v_operation_row.progress_json->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
      UNION ALL
      SELECT 'operation_result'::text AS source_name,
             4 AS source_order,
             CASE WHEN jsonb_typeof(v_operation_row.result_json->'provider_submit_diagnostic') = 'object' THEN v_operation_row.result_json->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
      UNION ALL
      SELECT 'operation_error'::text AS source_name,
             5 AS source_order,
             CASE WHEN jsonb_typeof(v_operation_row.error_json->'provider_submit_diagnostic') = 'object' THEN v_operation_row.error_json->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
      UNION ALL
      SELECT 'diagnostic_helper'::text AS source_name,
             6 AS source_order,
             CASE WHEN jsonb_typeof(v_helper_result->'provider_submit_diagnostic') = 'object' THEN v_helper_result->'provider_submit_diagnostic' ELSE '{}'::jsonb END AS diagnostic
    ) AS candidate_source
    WHERE candidate_source.diagnostic <> '{}'::jsonb
  ) AS candidate_ranked
  ORDER BY candidate_ranked.precedence_rank DESC, candidate_ranked.source_order ASC
  LIMIT 1;

  IF v_existing_diagnostic IS NULL THEN
    v_existing_diagnostic := '{}'::jsonb;
    v_existing_diagnostic_source := NULL::text;
    v_existing_rank := 0;
    v_existing_status := NULL::text;
    v_existing_review_reason_code := NULL::text;
  END IF;

  IF v_provider_acceptance_evidence_count > 0 AND COALESCE(v_existing_rank, 0) < 500 THEN
    v_existing_diagnostic := jsonb_build_object(
      'diagnostic_version', 1,
      'generated_at_utc', v_now::text,
      'provider_submission_status', 'PROVIDER_SUBMISSION_ACCEPTED',
      'review_reason_code', 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT',
      'provider_submission_attempted', true,
      'provider_request_sent', true,
      'provider_request_sent_confirmed', true,
      'provider_response_received', true,
      'provider_response_present', true,
      'provider_submission_accepted', true,
      'provider_external_evidence_present', true,
      'provider_acceptance_evidence_present', true,
      'manual_resolution_required', false,
      'safe_retry_available', false,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'chunk_id', p_chunk_id::text,
      'chunk_ids', jsonb_build_array(p_chunk_id::text),
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
      'rail_tx_id', v_primary_rail_tx_id,
      'rail_state', v_primary_rail_state,
      'provider_acceptance_evidence_count', v_provider_acceptance_evidence_count
    );
    v_existing_diagnostic_source := 'direct_provider_acceptance_evidence';
    v_existing_status := 'PROVIDER_SUBMISSION_ACCEPTED';
    v_existing_review_reason_code := 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT';
    v_existing_rank := 500;
  END IF;

  v_provider_call_stage := v_stage_upper;
  v_incoming_status := NULLIF(UPPER(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_status', v_input_diagnostic->>'provider_status', ''))), '');
  v_provider_transaction_id := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_transaction_id', v_input_diagnostic->>'provider_payment_id', '')), '');
  v_provider_reference := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_reference', '')), '');
  v_provider_state := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_state', '')), '');
  v_rail_tx_id := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'rail_tx_id', '')), '');
  v_rail_state := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'rail_state', '')), '');
  v_request_id := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'request_id', v_primary_request_id, '')), '');
  v_idempotency_key := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'idempotency_key', '')), '');
  v_local_provider_request_id := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'local_provider_request_id', v_request_id, '')), '');
  v_provider_http_status := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_http_status', '')), '');
  v_provider_error_code := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_error_code', '')), '');
  v_provider_error_message_redacted := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_error_message_redacted', '')), '');
  v_provider_response_redacted := v_input_diagnostic->'provider_response_redacted';
  v_provider_error_redacted := v_input_diagnostic->'provider_error_redacted';

  IF v_idempotency_key IS NULL THEN
    v_idempotency_key := NULLIF(BTRIM(COALESCE(v_request_id, '')), '');
  END IF;

  IF v_provider_reference IS NOT NULL
     AND v_provider_reference IN (
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__'),
       p_operation_id::text,
       p_chunk_id::text,
       COALESCE(v_request_id, '__NO_REQUEST_ID__'),
       COALESCE(v_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_payment_reference, '__NO_PAYMENT_REFERENCE__'),
       COALESCE(v_batch_bulk_reference, '__NO_BATCH_BULK_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'reference', '')), ''), '__NO_INPUT_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'referenceId', '')), ''), '__NO_INPUT_REFERENCE_ID__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'local_reference', '')), ''), '__NO_INPUT_LOCAL_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_reference', '')), ''), '__NO_INPUT_PROVIDER_REQUEST_REFERENCE__')
     ) THEN
    v_provider_reference := NULL::text;
  END IF;

  IF v_provider_transaction_id IS NOT NULL
     AND v_provider_transaction_id IN (
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__'),
       p_operation_id::text,
       p_chunk_id::text,
       COALESCE(v_request_id, '__NO_REQUEST_ID__'),
       COALESCE(v_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_payment_reference, '__NO_PAYMENT_REFERENCE__'),
       COALESCE(v_batch_bulk_reference, '__NO_BATCH_BULK_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'reference', '')), ''), '__NO_INPUT_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'referenceId', '')), ''), '__NO_INPUT_REFERENCE_ID__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'local_reference', '')), ''), '__NO_INPUT_LOCAL_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_reference', '')), ''), '__NO_INPUT_PROVIDER_REQUEST_REFERENCE__')
     ) THEN
    v_provider_transaction_id := NULL::text;
  END IF;

  IF v_rail_tx_id IS NOT NULL
     AND v_rail_tx_id IN (
       COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__'),
       p_operation_id::text,
       p_chunk_id::text,
       COALESCE(v_request_id, '__NO_REQUEST_ID__'),
       COALESCE(v_idempotency_key, '__NO_IDEMPOTENCY_KEY__'),
       COALESCE(v_local_provider_request_id, '__NO_LOCAL_PROVIDER_REQUEST_ID__'),
       COALESCE(v_primary_payment_reference, '__NO_PAYMENT_REFERENCE__'),
       COALESCE(v_batch_bulk_reference, '__NO_BATCH_BULK_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'reference', '')), ''), '__NO_INPUT_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'referenceId', '')), ''), '__NO_INPUT_REFERENCE_ID__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'local_reference', '')), ''), '__NO_INPUT_LOCAL_REFERENCE__'),
       COALESCE(NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_reference', '')), ''), '__NO_INPUT_PROVIDER_REQUEST_REFERENCE__')
     ) THEN
    v_rail_tx_id := NULL::text;
  END IF;

  v_provider_request_sent_confirmed := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_provider_request_dispatched_at_utc := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_dispatched_at_utc', v_input_diagnostic->>'request_sent_at_utc', '')), '');
  v_provider_request_sent := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_provider_request_sent_confirmed IS TRUE
    OR v_stage_upper IN ('PROVIDER_PAYMENT_CREATE_REQUEST_SENT', 'PROVIDER_PAYMENT_CREATE_RESPONSE_RECEIVED', 'PROVIDER_PAYMENT_CREATE_ACCEPTED', 'PROVIDER_PAYMENT_CREATE_REJECTED', 'PROVIDER_PAYMENT_CREATE_UNKNOWN', 'PROVIDER_PAYMENT_CREATE_MALFORMED')
    OR v_stage_upper LIKE '%REQUEST_SENT%';

  v_provider_response_received := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_stage_upper IN ('PROVIDER_PAYMENT_CREATE_RESPONSE_RECEIVED', 'PROVIDER_PAYMENT_CREATE_ACCEPTED', 'PROVIDER_PAYMENT_CREATE_REJECTED', 'PROVIDER_PAYMENT_CREATE_MALFORMED');

  v_provider_response_present := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_response_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_provider_response_received IS TRUE
    OR NULLIF(BTRIM(COALESCE(v_provider_http_status, v_provider_error_code, '')), '') IS NOT NULL;

  v_provider_submission_accepted := (
    lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_accepted', v_input_diagnostic->>'provider_accepted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_incoming_status = 'PROVIDER_SUBMISSION_ACCEPTED'
    OR v_stage_upper = 'PROVIDER_PAYMENT_CREATE_ACCEPTED'
  )
  AND (
    (
      NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') <> COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_request_id, '')), ''), '__NO_REQUEST_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
      AND NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_primary_payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
    )
    OR (
      NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') IS NOT NULL
      AND NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') <> COALESCE(v_primary_transfer_id, '__NO_TRANSFER_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_request_id, '')), ''), '__NO_REQUEST_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_idempotency_key, '')), ''), '__NO_IDEMPOTENCY_KEY__')
      AND NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_local_provider_request_id, '')), ''), '__NO_LOCAL_PROVIDER_REQUEST_ID__')
      AND NULLIF(BTRIM(COALESCE(v_provider_reference, '')), '') <> COALESCE(NULLIF(BTRIM(COALESCE(v_primary_payment_reference, '')), ''), '__NO_PAYMENT_REFERENCE__')
    )
  );

  v_provider_external_evidence_present := NULLIF(BTRIM(COALESCE(v_provider_transaction_id, v_rail_tx_id, v_provider_reference, '')), '') IS NOT NULL;

  v_provider_submission_rejected := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_rejected', v_input_diagnostic->>'provider_rejected', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_incoming_status IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED')
    OR v_stage_upper = 'PROVIDER_PAYMENT_CREATE_REJECTED'
    OR CASE WHEN COALESCE(v_provider_http_status, '') ~ '^[0-9]+$' THEN v_provider_http_status::integer >= 400 ELSE false END;

  v_provider_request_impossible := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_request_impossible', v_input_diagnostic->>'durable_provider_request_impossible', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_incoming_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
    OR v_stage_upper IN ('PROVIDER_PRECALL_VALIDATION_FAILED', 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL', 'FUNDING_ACCOUNT_MISSING', 'FUNDING_CHECK_FAILED', 'COUNTERPARTY_MAPPING_FAILED', 'RAIL_ENV_MISMATCH', 'PROVIDER_PAYMENT_CREATE_BLOCKED_PRE_CALL');

  IF v_incoming_status = 'PROVIDER_SUBMISSION_ACCEPTED' AND v_provider_submission_accepted IS NOT TRUE THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID';
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_request_sent := true;
  END IF;

  IF v_provider_submission_accepted IS TRUE THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_ACCEPTED';
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
    v_provider_acceptance_evidence_present := true;
  ELSIF v_provider_submission_rejected IS TRUE THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_REJECTED';
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
  ELSIF v_incoming_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' OR v_stage_upper = 'PROVIDER_PAYMENT_CREATE_MALFORMED' THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE';
    v_provider_request_sent := true;
    v_provider_response_received := true;
    v_provider_response_present := true;
  ELSIF v_provider_request_sent IS TRUE AND v_provider_response_present IS NOT TRUE AND v_provider_response_received IS NOT TRUE THEN
    v_incoming_status := 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME';
    v_provider_response_received := false;
    v_provider_response_present := false;
  ELSIF v_provider_response_present IS TRUE AND v_provider_submission_accepted IS NOT TRUE AND v_provider_submission_rejected IS NOT TRUE THEN
    v_incoming_status := COALESCE(NULLIF(v_incoming_status, ''), 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');
    IF v_incoming_status NOT IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID') THEN
      v_incoming_status := 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID';
    END IF;
    v_provider_request_sent := true;
    v_provider_response_received := true;
  ELSIF v_provider_request_impossible IS TRUE THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL';
    v_provider_request_sent := false;
    v_provider_response_received := false;
    v_provider_response_present := false;
  ELSIF v_incoming_status IS NULL THEN
    v_incoming_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
  END IF;

  IF v_chunk_lock_expired IS TRUE
     AND v_provider_request_impossible IS NOT TRUE
     AND v_provider_acceptance_evidence_count = 0
     AND v_provider_response_present_count = 0
     AND v_incoming_status IN ('NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL') THEN
    v_incoming_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
  END IF;

  v_provider_submission_attempted := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_attempted', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_provider_request_sent IS TRUE
    OR v_provider_response_present IS TRUE
    OR v_provider_submission_accepted IS TRUE
    OR v_provider_submission_rejected IS TRUE;

  v_provider_submission_unknown := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_unknown', v_input_diagnostic->>'provider_unknown', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_incoming_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');

  v_provider_acceptance_evidence_present := (v_provider_submission_accepted IS TRUE AND v_provider_external_evidence_present IS TRUE)
    OR v_provider_acceptance_evidence_count > 0;

  v_provider_submission_failed := lower(BTRIM(COALESCE(v_input_diagnostic->>'provider_submission_failed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_provider_submission_rejected IS TRUE;

  v_manual_resolution_required := lower(BTRIM(COALESCE(v_input_diagnostic->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    OR v_incoming_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');

  v_safe_retry_available := lower(BTRIM(COALESCE(v_input_diagnostic->>'safe_retry_available', ''))) IN ('true', 't', '1', 'yes', 'y', 'on')
    AND v_incoming_status NOT IN ('PROVIDER_SUBMISSION_ACCEPTED', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');

  v_automatic_retry_blocked := v_incoming_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID');
  v_retry_blocked_reason := CASE WHEN v_automatic_retry_blocked IS TRUE THEN v_incoming_status ELSE NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'retry_blocked_reason', '')), '') END;

  v_incoming_review_reason_code := NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'review_reason_code', '')), '');
  IF v_incoming_review_reason_code IS NULL THEN
    v_incoming_review_reason_code := CASE
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_REJECTED_PAYMENT'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_RESPONSE_MALFORMED'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'PROVIDER_RESPONSE_PRESENT_NO_EXTERNAL_ID'
      WHEN v_incoming_status = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'PROVIDER_REQUEST_SENT_NO_RESPONSE'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
      ELSE 'NO_PROVIDER_SUBMIT_ATTEMPT'
    END;
  END IF;

  v_crash_safety_status_if_lock_expires := CASE
    WHEN v_provider_request_sent IS TRUE THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
    WHEN v_provider_request_impossible IS TRUE THEN 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
    ELSE 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
  END;

  v_recommended_action := COALESCE(
    NULLIF(BTRIM(COALESCE(v_input_diagnostic->>'recommended_action', '')), ''),
    CASE
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'Provider acceptance evidence exists. Do not retry unless reconciled.'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'Review the provider rejection/error and retry only after correction.'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'Provider returned an unusable response. Check Revolut/bank records before retry.'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'A provider response was recorded, but no external transaction ID was captured. Check Revolut/bank records before retry.'
      WHEN v_incoming_status = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'Provider request may have been sent, but no usable response was recorded. Check Revolut/bank records before retry.'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'Check Revolut/bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.'
      WHEN v_incoming_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'Provider was not called. Fix the local blocker and retry if cleanup allows.'
      ELSE 'Provider-submit stage recorded before the provider request boundary.'
    END
  );

  v_incoming_rank := CASE
    WHEN v_provider_submission_accepted IS TRUE THEN 500
    WHEN v_incoming_status = 'MANUAL_RESOLVED_NO_PAYMENT_MADE' THEN 450
    WHEN v_provider_submission_rejected IS TRUE OR v_provider_submission_failed IS TRUE OR v_incoming_status IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED') THEN 420
    WHEN v_provider_response_present IS TRUE OR v_provider_response_received IS TRUE OR v_incoming_status IN ('PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID') THEN 400
    WHEN v_provider_request_sent IS TRUE OR v_incoming_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK') THEN 300
    WHEN v_incoming_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 200
    WHEN v_incoming_status = 'NO_PROVIDER_SUBMISSION_ATTEMPTED' THEN 100
    ELSE 0
  END;

  v_incoming_diagnostic := jsonb_strip_nulls(
    v_input_diagnostic
    || jsonb_build_object(
      'diagnostic_version', 1,
      'generated_at_utc', v_now::text,
      'stage_recorded_at_utc', v_now::text,
      'stage_recorded_by_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
      'provider_call_stage', v_provider_call_stage,
      'provider_stage_recorded', v_stage,
      'provider_submission_status', v_incoming_status,
      'review_reason_code', v_incoming_review_reason_code,
      'provider_submission_attempted', v_provider_submission_attempted,
      'provider_request_sent', v_provider_request_sent,
      'provider_request_sent_confirmed', v_provider_request_sent_confirmed,
      'provider_request_dispatched_at_utc', v_provider_request_dispatched_at_utc,
      'provider_response_received', v_provider_response_received,
      'provider_response_present', v_provider_response_present,
      'provider_submission_accepted', v_provider_submission_accepted,
      'provider_submission_rejected', v_provider_submission_rejected,
      'provider_submission_failed', v_provider_submission_failed,
      'provider_submission_unknown', v_provider_submission_unknown,
      'provider_external_evidence_present', v_provider_external_evidence_present,
      'provider_acceptance_evidence_present', v_provider_acceptance_evidence_present,
      'manual_resolution_required', v_manual_resolution_required,
      'safe_retry_available', v_safe_retry_available
    )
    || jsonb_build_object(
      'automatic_retry_blocked', v_automatic_retry_blocked,
      'retry_blocked_reason', v_retry_blocked_reason,
      'recommended_action', v_recommended_action,
      'crash_safety_status_if_lock_expires', v_crash_safety_status_if_lock_expires,
      'provider_request_impossible', v_provider_request_impossible,
      'durable_provider_request_impossible', v_provider_request_impossible,
      'stage_precedence_rank', v_incoming_rank,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'chunk_id', p_chunk_id::text,
      'chunk_ids', jsonb_build_array(p_chunk_id::text),
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
      'rail_provider', v_primary_rail_provider,
      'rail_env', v_primary_rail_env,
      'rail_tx_id', CASE WHEN v_provider_acceptance_evidence_present IS TRUE THEN v_rail_tx_id ELSE NULL::text END,
      'rail_state', v_rail_state,
      'provider_transaction_id', v_provider_transaction_id,
      'provider_reference', v_provider_reference,
      'provider_state', v_provider_state,
      'request_id', v_request_id,
      'idempotency_key', v_idempotency_key
    )
    || jsonb_build_object(
      'local_provider_request_id', v_local_provider_request_id,
      'provider_http_status', v_provider_http_status,
      'provider_error_code', v_provider_error_code,
      'provider_error_message_redacted', v_provider_error_message_redacted,
      'provider_response_redacted', v_provider_response_redacted,
      'provider_error_redacted', v_provider_error_redacted,
      'chunk_status', v_chunk_row.status,
      'chunk_started_at_utc', CASE WHEN v_chunk_row.started_at_utc IS NULL THEN NULL ELSE v_chunk_row.started_at_utc::text END,
      'chunk_completed_at_utc', CASE WHEN v_chunk_row.completed_at_utc IS NULL THEN NULL ELSE v_chunk_row.completed_at_utc::text END,
      'chunk_lock_expires_at_utc', CASE WHEN v_chunk_row.lock_expires_at_utc IS NULL THEN NULL ELSE v_chunk_row.lock_expires_at_utc::text END,
      'chunk_lock_expired', v_chunk_lock_expired,
      'unfinalised_submit_chunk', v_unfinalised_submit_chunk,
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_rejection_count', COALESCE(v_provider_rejection_count, 0),
      'provider_unknown_count', COALESCE(v_provider_unknown_count, 0),
      'provider_malformed_count', COALESCE(v_provider_malformed_count, 0),
      'local_correlation_only_fields', jsonb_build_array('request_id', 'idempotency_key', 'payment_reference', 'chunk_id', 'operation_id')
    )
  );

  IF COALESCE(v_existing_rank, 0) > v_incoming_rank THEN
    v_apply_incoming := false;
    v_preserved_stronger_provider_evidence := true;
    v_final_rank := v_existing_rank;
    v_final_diagnostic := jsonb_strip_nulls(
      v_existing_diagnostic
      || jsonb_build_object(
        'stage_recorded_at_utc', v_now::text,
        'stage_recorded_by_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
        'last_stage_recorded', v_stage,
        'last_stage_recorded_status', v_incoming_status,
        'ignored_weaker_stage_record', true,
        'ignored_weaker_stage', v_stage,
        'ignored_weaker_stage_status', v_incoming_status,
        'ignored_weaker_stage_rank', v_incoming_rank,
        'protected_by_existing_provider_evidence', true,
        'existing_provider_submit_diagnostic_source', v_existing_diagnostic_source,
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'chunk_id', p_chunk_id::text,
        'chunk_ids', jsonb_build_array(p_chunk_id::text),
        'transfer_id', v_primary_transfer_id,
        'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
        'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
        'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_existing_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_provider_request_sent_confirmed,
        'provider_request_dispatched_at_utc', COALESCE(NULLIF(BTRIM(COALESCE(v_existing_diagnostic->>'provider_request_dispatched_at_utc', v_existing_diagnostic->>'request_sent_at_utc', '')), ''), v_provider_request_dispatched_at_utc),
        'provider_external_evidence_present', lower(BTRIM(COALESCE(v_existing_diagnostic->>'provider_external_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_provider_external_evidence_present,
        'provider_rejection_count', COALESCE(v_provider_rejection_count, 0)
      )
    );
  ELSE
    v_apply_incoming := true;
    v_preserved_stronger_provider_evidence := false;
    v_final_rank := v_incoming_rank;
    v_final_diagnostic := jsonb_strip_nulls(COALESCE(v_existing_diagnostic, '{}'::jsonb) || v_incoming_diagnostic);
  END IF;

  v_final_status := NULLIF(UPPER(BTRIM(COALESCE(v_final_diagnostic->>'provider_submission_status', ''))), '');
  IF v_final_status IS NULL THEN
    v_final_status := 'NO_PROVIDER_SUBMISSION_ATTEMPTED';
  END IF;

  IF v_final_status = 'PROVIDER_SUBMISSION_ACCEPTED'
     AND NOT (
       COALESCE(v_provider_acceptance_evidence_count, 0) > 0
       OR v_provider_external_evidence_present IS TRUE
     ) THEN
    v_final_status := 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID';
    v_final_rank := GREATEST(v_final_rank, 400);
    v_final_diagnostic := jsonb_strip_nulls(
      v_final_diagnostic || jsonb_build_object(
        'provider_submission_status', v_final_status,
        'review_reason_code', 'PROVIDER_RESPONSE_PRESENT_NO_EXTERNAL_ID',
        'provider_submission_accepted', false,
        'provider_submission_unknown', true,
        'provider_external_evidence_present', false,
        'provider_acceptance_evidence_present', false,
        'provider_response_present', true,
        'manual_resolution_required', true,
        'safe_retry_available', false,
        'automatic_retry_blocked', true,
        'retry_blocked_reason', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID',
        'recommended_action', 'Provider response/status was recorded, but no usable external provider transaction or reference was stored. Check Revolut/bank records before retry.'
      )
    );
  END IF;

  IF v_chunk_lock_expired IS TRUE
     AND v_provider_acceptance_evidence_count = 0
     AND v_provider_response_present_count = 0
     AND lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_impossible', v_final_diagnostic->>'durable_provider_request_impossible', ''))) NOT IN ('true', 't', '1', 'yes', 'y', 'on')
     AND v_final_status IN ('NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL') THEN
    v_final_status := 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK';
    v_final_rank := GREATEST(v_final_rank, 300);
    v_final_diagnostic := jsonb_strip_nulls(
      v_final_diagnostic || jsonb_build_object(
        'provider_submission_status', v_final_status,
        'review_reason_code', 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK',
        'provider_submission_unknown', true,
        'provider_external_evidence_present', false,
        'provider_acceptance_evidence_present', false,
        'stale_submit_chunk', true,
        'manual_resolution_required', true,
        'safe_retry_available', false,
        'automatic_retry_blocked', true,
        'retry_blocked_reason', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
        'recommended_action', 'Check Revolut/bank records before retry. If no payment was made, record manual no-payment confirmation and reset for retry.'
      )
    );
  END IF;

  v_final_review_reason_code := NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'review_reason_code', '')), '');
  IF v_final_review_reason_code IS NULL THEN
    v_final_review_reason_code := CASE
      WHEN v_final_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_ACCEPTANCE_EVIDENCE_PRESENT'
      WHEN v_final_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'PROVIDER_REJECTED_PAYMENT'
      WHEN v_final_status = 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE' THEN 'PROVIDER_RESPONSE_MALFORMED'
      WHEN v_final_status = 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID' THEN 'PROVIDER_RESPONSE_PRESENT_NO_EXTERNAL_ID'
      WHEN v_final_status = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME' THEN 'PROVIDER_REQUEST_SENT_NO_RESPONSE'
      WHEN v_final_status = 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK' THEN 'STALE_RUNNING_PROVIDER_SUBMIT_CHUNK'
      WHEN v_final_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
      ELSE 'NO_PROVIDER_SUBMIT_ATTEMPT'
    END;
  END IF;

  v_final_diagnostic := jsonb_strip_nulls(
    v_final_diagnostic
    || jsonb_build_object(
      'diagnostic_version', 1,
      'generated_at_utc', v_now::text,
      'provider_submission_status', v_final_status,
      'review_reason_code', v_final_review_reason_code,
      'stage_precedence_rank', v_final_rank,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', p_operation_id::text,
      'chunk_id', p_chunk_id::text,
      'chunk_ids', jsonb_build_array(p_chunk_id::text),
      'transfer_id', v_primary_transfer_id,
      'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on') OR v_provider_request_sent_confirmed,
      'provider_request_dispatched_at_utc', COALESCE(NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_dispatched_at_utc', v_final_diagnostic->>'request_sent_at_utc', '')), ''), v_provider_request_dispatched_at_utc),
      'provider_external_evidence_present', COALESCE(v_provider_acceptance_evidence_count, 0) > 0 OR v_provider_external_evidence_present,
      'provider_acceptance_evidence_present', v_final_status = 'PROVIDER_SUBMISSION_ACCEPTED' AND (COALESCE(v_provider_acceptance_evidence_count, 0) > 0 OR v_provider_external_evidence_present),
      'rail_tx_id', CASE WHEN v_final_status = 'PROVIDER_SUBMISSION_ACCEPTED' AND (COALESCE(v_provider_acceptance_evidence_count, 0) > 0 OR v_provider_external_evidence_present) THEN COALESCE(NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'rail_tx_id', '')), ''), v_rail_tx_id, v_provider_transaction_id) ELSE NULL::text END,
      'provider_rejection_count', COALESCE(v_provider_rejection_count, 0),
      'preserved_stronger_provider_evidence', v_preserved_stronger_provider_evidence
    )
  );

  v_chunk_result_before := COALESCE(v_chunk_row.result_json, '{}'::jsonb);
  v_stage_history := CASE WHEN jsonb_typeof(v_chunk_result_before->'provider_submit_stage_history') = 'array' THEN v_chunk_result_before->'provider_submit_stage_history' ELSE '[]'::jsonb END;
  v_stage_history_entry := jsonb_strip_nulls(jsonb_build_object(
    'stage', v_stage,
    'recorded_at_utc', v_now::text,
    'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
    'incoming_provider_submission_status', v_incoming_status,
    'provider_submission_status', v_final_status,
    'review_reason_code', v_final_review_reason_code,
    'incoming_precedence_rank', v_incoming_rank,
    'existing_precedence_rank', v_existing_rank,
    'final_precedence_rank', v_final_rank,
    'incoming_applied', v_apply_incoming,
    'protected_by_existing_provider_evidence', v_preserved_stronger_provider_evidence,
    'provider_request_sent', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_response_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_response_present', v_final_diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_external_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_external_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'crash_safety_status_if_lock_expires', COALESCE(v_final_diagnostic->>'crash_safety_status_if_lock_expires', v_crash_safety_status_if_lock_expires)
  ));

  v_before_json := jsonb_build_object(
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_status', v_operation_row.status,
    'operation_phase', v_operation_row.phase,
    'operation_progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
    'chunk', to_jsonb(v_chunk_row)
  );

  v_chunk_result_after := jsonb_strip_nulls(
    v_chunk_result_before
    || jsonb_build_object(
      'provider_submit_diagnostic', v_final_diagnostic,
      'provider_submission_status', v_final_status,
      'review_reason_code', v_final_review_reason_code,
      'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_request_dispatched_at_utc', NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_dispatched_at_utc', '')), ''),
      'provider_external_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_external_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_call_stage', COALESCE(v_final_diagnostic->>'provider_call_stage', v_provider_call_stage),
      'provider_submit_stage_last_recorded', v_stage,
      'provider_submit_stage_last_recorded_at_utc', v_now::text,
      'provider_submit_stage_history', v_stage_history || jsonb_build_array(v_stage_history_entry),
      'provider_submit_stage_incoming_applied', v_apply_incoming,
      'provider_submit_stage_protected_by_existing_evidence', v_preserved_stronger_provider_evidence
    )
  );

  UPDATE public.banking_pay_operation_chunks AS chunk_update
  SET result_json = v_chunk_result_after,
      updated_at_utc = v_now
  WHERE chunk_update.id = p_chunk_id
    AND chunk_update.operation_id = p_operation_id
  RETURNING chunk_update.*
  INTO v_after_chunk_row;

  v_operation_progress_after := jsonb_strip_nulls(
    COALESCE(v_operation_row.progress_json, '{}'::jsonb)
    || jsonb_build_object(
      'provider_submit_diagnostic', v_final_diagnostic,
      'provider_submission_status', v_final_status,
      'review_reason_code', v_final_review_reason_code,
      'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_request_dispatched_at_utc', NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_dispatched_at_utc', '')), ''),
      'provider_external_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_external_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
      'provider_call_stage', COALESCE(v_final_diagnostic->>'provider_call_stage', v_provider_call_stage),
      'provider_submit_stage_last_recorded', v_stage,
      'provider_submit_stage_last_recorded_at_utc', v_now::text,
      'provider_submit_stage_incoming_applied', v_apply_incoming,
      'provider_submit_stage_protected_by_existing_evidence', v_preserved_stronger_provider_evidence,
      'last_provider_submit_chunk_id', p_chunk_id::text
    )
  );

  UPDATE public.banking_pay_operations AS operation_update
  SET progress_json = v_operation_progress_after,
      updated_at_utc = v_now
  WHERE operation_update.id = p_operation_id;

  v_after_json := jsonb_build_object(
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'stage', v_stage,
    'provider_submit_diagnostic', v_final_diagnostic,
    'provider_submission_status', v_final_status,
    'review_reason_code', v_final_review_reason_code,
    'incoming_applied', v_apply_incoming,
    'protected_by_existing_provider_evidence', v_preserved_stronger_provider_evidence,
    'existing_provider_submit_diagnostic_source', v_existing_diagnostic_source,
    'existing_precedence_rank', v_existing_rank,
    'incoming_precedence_rank', v_incoming_rank,
    'final_precedence_rank', v_final_rank,
    'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
    'chunk', to_jsonb(v_after_chunk_row),
    'operation_progress_json', v_operation_progress_after
  );

  BEGIN
    PERFORM public._audit_insert(
      'banking_pay_operation_chunks',
      p_chunk_id::text,
      'PAYMENT_PROVIDER_SUBMIT_CHUNK_STAGE_RECORDED',
      v_before_json,
      v_after_json,
      'payment_provider_submit_chunk_stage_recorded',
      v_actor_user_id
    );
  EXCEPTION
    WHEN OTHERS THEN
      NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'recorded', true,
    'incoming_applied', v_apply_incoming,
    'protected_by_existing_provider_evidence', v_preserved_stronger_provider_evidence,
    'operation_id', p_operation_id::text,
    'pay_batch_id', p_pay_batch_id::text,
    'chunk_id', p_chunk_id::text,
    'stage', v_stage,
    'transfer_ids', COALESCE(v_transfer_ids_json, '[]'::jsonb),
    'provider_submit_diagnostic', v_final_diagnostic,
    'provider_submission_status', v_final_status,
    'review_reason_code', v_final_review_reason_code,
    'manual_resolution_required', lower(BTRIM(COALESCE(v_final_diagnostic->>'manual_resolution_required', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'safe_retry_available', lower(BTRIM(COALESCE(v_final_diagnostic->>'safe_retry_available', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_request_sent_confirmed', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_sent_confirmed', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_request_dispatched_at_utc', NULLIF(BTRIM(COALESCE(v_final_diagnostic->>'provider_request_dispatched_at_utc', '')), ''),
    'provider_external_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_external_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_acceptance_evidence_present', lower(BTRIM(COALESCE(v_final_diagnostic->>'provider_acceptance_evidence_present', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
    'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
    'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
    'provider_rejection_count', COALESCE(v_provider_rejection_count, 0),
    'existing_precedence_rank', v_existing_rank,
    'incoming_precedence_rank', v_incoming_rank,
    'final_precedence_rank', v_final_rank,
    'recorded_at_utc', v_now::text
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_batch_item_economic_components(
  p_pay_batch_id uuid DEFAULT NULL,
  p_pay_batch_item_ids uuid[] DEFAULT NULL
)
RETURNS TABLE(
  pay_batch_id uuid,
  pay_batch_item_id uuid,
  timesheet_id uuid,
  item_type text,
  key_type text,
  key_value text,
  source_amount_ex_vat numeric,
  source_amount_inc_vat numeric,
  target_amount_ex_vat numeric,
  key_resolution_source text,
  key_resolution_failure_reason text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_pay_batch_id IS NULL
     AND coalesce(array_length(p_pay_batch_item_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION '_pay_batch_item_economic_components requires p_pay_batch_id or p_pay_batch_item_ids';
  END IF;

  RETURN QUERY
  WITH input_item_ids AS (
    SELECT DISTINCT input_ids.item_id
    FROM unnest(coalesce(p_pay_batch_item_ids, array[]::uuid[])) AS input_ids(item_id)
    WHERE input_ids.item_id IS NOT NULL
  ),
  base_items AS (
    SELECT
      pbc.pay_batch_id AS batch_id,
      pbi.id AS batch_item_id,
      pbi.timesheet_id AS item_timesheet_id,
      upper(nullif(btrim(coalesce(pbi.item_type, '')), '')) AS item_type_norm,
      pbi.item_type AS item_type_raw,
      pbi.segment_key AS item_segment_key,
      pbi.source_ref AS item_source_ref,
      pbi.amount_ex_vat AS item_amount_ex_vat,
      pbi.amount_inc_vat AS item_amount_inc_vat,
      pbi.finance_case_id AS item_finance_case_id,
      pbi.finance_component_id AS item_finance_component_id,
      pbi.frozen_target_amount_ex_vat AS item_frozen_target_amount_ex_vat,
      pbi.frozen_source_amount AS item_frozen_source_amount,
      pbi.frozen_resolution_mode AS item_frozen_resolution_mode,
      pbi.frozen_resolution_payload_json AS item_frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json AS item_frozen_resolution_result_json,
      pbi.frozen_component_key_type AS item_frozen_key_type,
      pbi.frozen_component_key_value AS item_frozen_key_value,
      coalesce(pbi.frozen_component_snapshot_json, '{}'::jsonb) AS item_frozen_component_snapshot_json,
      coalesce(pbi.frozen_source_basis_json, '{}'::jsonb) AS item_frozen_source_basis_json
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    WHERE (p_pay_batch_id IS NULL OR pbc.pay_batch_id = p_pay_batch_id)
      AND (
        coalesce(array_length(p_pay_batch_item_ids, 1), 0) = 0
        OR EXISTS (
          SELECT 1
          FROM input_item_ids AS input_filter
          WHERE input_filter.item_id = pbi.id
        )
      )
  ),
  single_breakdown_meta AS (
    SELECT
      pbb.pay_batch_item_id AS batch_item_id,
      count(*)::integer AS breakdown_count,
      (array_agg(pbb.meta_json ORDER BY pbb.id))[1] AS single_meta_json
    FROM public.pay_batch_item_breakdowns AS pbb
    JOIN base_items AS bi_for_breakdown
      ON bi_for_breakdown.batch_item_id = pbb.pay_batch_item_id
    GROUP BY pbb.pay_batch_item_id
  ),
  snapshot_choice AS (
    SELECT
      distinct_items.batch_id,
      distinct_items.item_timesheet_id,
      (
        SELECT pbs.target_snapshot_json
        FROM public.pay_batch_timesheet_snapshots AS pbs
        WHERE pbs.pay_batch_id = distinct_items.batch_id
          AND pbs.timesheet_id = distinct_items.item_timesheet_id
        ORDER BY pbs.created_at_utc DESC, pbs.id DESC
        LIMIT 1
      ) AS target_snapshot_json
    FROM (
      SELECT DISTINCT
        bi.batch_id,
        bi.item_timesheet_id
      FROM base_items AS bi
      WHERE bi.item_timesheet_id IS NOT NULL
    ) AS distinct_items
  ),
  prepared_items AS (
    SELECT
      bi.batch_id,
      bi.batch_item_id,
      bi.item_timesheet_id,
      bi.item_type_norm,
      bi.item_type_raw,
      bi.item_segment_key,
      bi.item_source_ref,
      bi.item_amount_ex_vat,
      bi.item_amount_inc_vat,
      bi.item_finance_case_id,
      bi.item_finance_component_id,
      bi.item_frozen_target_amount_ex_vat,
      bi.item_frozen_source_amount,
      bi.item_frozen_resolution_mode,
      bi.item_frozen_resolution_payload_json,
      bi.item_frozen_resolution_result_json,
      bi.item_frozen_key_type,
      bi.item_frozen_key_value,
      bi.item_frozen_component_snapshot_json,
      bi.item_frozen_source_basis_json,
      coalesce(sbm.breakdown_count, 0) AS breakdown_count,
      CASE
        WHEN coalesce(sbm.breakdown_count, 0) = 1 THEN coalesce(sbm.single_meta_json, '{}'::jsonb)
        ELSE '{}'::jsonb
      END AS item_single_breakdown_meta_json,
      coalesce(sc.target_snapshot_json, '{}'::jsonb) AS target_snapshot_json
    FROM base_items AS bi
    LEFT JOIN single_breakdown_meta AS sbm
      ON sbm.batch_item_id = bi.batch_item_id
    LEFT JOIN snapshot_choice AS sc
      ON sc.batch_id = bi.batch_id
     AND sc.item_timesheet_id = bi.item_timesheet_id
  ),
  raw_key_candidates AS (
    SELECT
      pi.batch_id,
      pi.batch_item_id,
      pi.item_timesheet_id,
      pi.item_type_norm,
      pi.item_type_raw,
      pi.item_segment_key,
      pi.item_source_ref,
      pi.item_amount_ex_vat,
      pi.item_amount_inc_vat,
      pi.item_finance_case_id,
      pi.item_finance_component_id,
      pi.item_frozen_target_amount_ex_vat,
      pi.item_frozen_source_amount,
      pi.item_frozen_resolution_mode,
      pi.item_frozen_resolution_payload_json,
      pi.item_frozen_resolution_result_json,
      pi.item_frozen_component_snapshot_json,
      pi.item_frozen_source_basis_json,
      pi.item_single_breakdown_meta_json,
      pi.target_snapshot_json,
      (
           pi.item_finance_case_id IS NOT NULL
        OR pi.item_finance_component_id IS NOT NULL
        OR pi.item_frozen_target_amount_ex_vat IS NOT NULL
        OR pi.item_frozen_resolution_mode IS NOT NULL
        OR pi.item_frozen_resolution_payload_json IS NOT NULL
        OR pi.item_frozen_resolution_result_json IS NOT NULL
        OR pi.item_frozen_component_snapshot_json ? 'target_amount_ex_vat'
        OR pi.item_frozen_component_snapshot_json ? 'target_pay_ex_vat'
        OR pi.item_frozen_component_snapshot_json ? 'target_pay_amount_ex_vat'
        OR pi.item_frozen_component_snapshot_json ? 'frozen_target_amount_ex_vat'
        OR pi.item_frozen_component_snapshot_json ? 'target_rate'
        OR pi.item_frozen_component_snapshot_json ? 'target_units'
        OR pi.item_frozen_component_snapshot_json ? 'resolution_mode'
        OR pi.item_frozen_component_snapshot_json ? 'saved_resolution_mode'
        OR pi.item_frozen_component_snapshot_json ? 'saved_resolution_payload_json'
        OR pi.item_frozen_component_snapshot_json ? 'saved_resolution_result_json'
        OR pi.item_single_breakdown_meta_json ? 'target_amount_ex_vat'
        OR pi.item_single_breakdown_meta_json ? 'target_pay_ex_vat'
        OR pi.item_single_breakdown_meta_json ? 'target_rate'
        OR pi.item_single_breakdown_meta_json ? 'resolution_mode'
      ) AS item_has_source_target_split,
      upper(nullif(btrim(coalesce(pi.item_frozen_key_type, '')), '')) AS direct_key_type,
      nullif(btrim(coalesce(pi.item_frozen_key_value, '')), '') AS direct_key_value,
      upper(nullif(btrim(coalesce(
        pi.item_frozen_component_snapshot_json->>'component_key_type',
        pi.item_frozen_component_snapshot_json->>'key_type',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,component_key_type}',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,key_type}',
        pi.item_frozen_source_basis_json->>'component_key_type',
        pi.item_frozen_source_basis_json->>'key_type',
        pi.item_single_breakdown_meta_json->>'component_key_type',
        pi.item_single_breakdown_meta_json->>'key_type',
        ''
      )), '')) AS snapshot_key_type,
      nullif(btrim(coalesce(
        pi.item_frozen_component_snapshot_json->>'component_key_value',
        pi.item_frozen_component_snapshot_json->>'key_value',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,component_key_value}',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,key_value}',
        pi.item_frozen_source_basis_json->>'component_key_value',
        pi.item_frozen_source_basis_json->>'key_value',
        pi.item_single_breakdown_meta_json->>'component_key_value',
        pi.item_single_breakdown_meta_json->>'key_value',
        ''
      )), '') AS snapshot_key_value,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'work_date',
        pi.item_frozen_source_basis_json->>'date',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,work_date}',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,date}',
        pi.item_frozen_component_snapshot_json->>'work_date',
        pi.item_frozen_component_snapshot_json->>'date',
        pi.item_single_breakdown_meta_json->>'work_date',
        pi.item_single_breakdown_meta_json->>'date',
        ''
      )), '') AS basis_work_date_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'segment_id',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,segment_id}',
        pi.item_frozen_component_snapshot_json->>'segment_id',
        pi.item_single_breakdown_meta_json->>'segment_id',
        pi.item_segment_key,
        CASE
          WHEN pi.item_source_ref IS NOT NULL AND btrim(pi.item_source_ref) LIKE 'seg:%'
            THEN split_part(pi.item_source_ref, ':', 2)
          ELSE NULL
        END,
        ''
      )), '') AS basis_segment_id_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'segment_key',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,segment_key}',
        pi.item_frozen_component_snapshot_json->>'segment_key',
        pi.item_single_breakdown_meta_json->>'segment_key',
        ''
      )), '') AS basis_segment_key_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'ref_num',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,ref_num}',
        pi.item_frozen_component_snapshot_json->>'ref_num',
        pi.item_single_breakdown_meta_json->>'ref_num',
        ''
      )), '') AS basis_ref_num_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'adjustment_id',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,adjustment_id}',
        pi.item_frozen_component_snapshot_json->>'adjustment_id',
        pi.item_single_breakdown_meta_json->>'adjustment_id',
        ''
      )), '') AS basis_adjustment_id_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'expense_code',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,expense_code}',
        pi.item_frozen_component_snapshot_json->>'expense_code',
        pi.item_single_breakdown_meta_json->>'expense_code',
        ''
      )), '') AS basis_expense_code_raw,
      nullif(btrim(coalesce(
        pi.item_frozen_source_basis_json->>'additional_code',
        pi.item_frozen_component_snapshot_json#>>'{source_basis_json,additional_code}',
        pi.item_frozen_component_snapshot_json->>'additional_code',
        pi.item_single_breakdown_meta_json->>'additional_code',
        ''
      )), '') AS basis_additional_code_raw
    FROM prepared_items AS pi
  ),
  segment_date_candidates AS (
    SELECT
      rkc.batch_id,
      rkc.batch_item_id,
      nullif(btrim(coalesce(segment_element.segment_json->>'date', '')), '') AS segment_date_raw,
      row_number() OVER (
        PARTITION BY rkc.batch_item_id
        ORDER BY
          CASE
            WHEN rkc.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
             AND nullif(btrim(coalesce(segment_element.segment_json->>'date', '')), '') = rkc.basis_work_date_raw
              THEN 0
            WHEN rkc.basis_ref_num_raw IS NOT NULL
             AND nullif(btrim(coalesce(segment_element.segment_json->>'ref_num', '')), '') = rkc.basis_ref_num_raw
              THEN 1
            WHEN rkc.basis_segment_id_raw IS NOT NULL
             AND nullif(btrim(coalesce(segment_element.segment_json->>'segment_id', '')), '') = rkc.basis_segment_id_raw
              THEN 2
            WHEN rkc.basis_segment_key_raw IS NOT NULL
             AND nullif(btrim(coalesce(segment_element.segment_json->>'segment_id', '')), '') = rkc.basis_segment_key_raw
              THEN 3
            ELSE 9
          END,
          nullif(btrim(coalesce(segment_element.segment_json->>'segment_id', '')), '')
      ) AS segment_match_rank
    FROM raw_key_candidates AS rkc
    JOIN LATERAL jsonb_array_elements(coalesce(rkc.target_snapshot_json->'segments', '[]'::jsonb)) AS segment_element(segment_json)
      ON true
    WHERE rkc.item_type_norm = 'SEGMENT_DELTA'
      AND segment_element.segment_json IS NOT NULL
      AND jsonb_typeof(segment_element.segment_json) = 'object'
      AND (
        (
          rkc.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          AND nullif(btrim(coalesce(segment_element.segment_json->>'date', '')), '') = rkc.basis_work_date_raw
        )
        OR (
          rkc.basis_ref_num_raw IS NOT NULL
          AND nullif(btrim(coalesce(segment_element.segment_json->>'ref_num', '')), '') = rkc.basis_ref_num_raw
        )
        OR (
          rkc.basis_segment_id_raw IS NOT NULL
          AND nullif(btrim(coalesce(segment_element.segment_json->>'segment_id', '')), '') = rkc.basis_segment_id_raw
        )
        OR (
          rkc.basis_segment_key_raw IS NOT NULL
          AND nullif(btrim(coalesce(segment_element.segment_json->>'segment_id', '')), '') = rkc.basis_segment_key_raw
        )
      )
  ),
  segment_date_pick AS (
    SELECT
      sdc.batch_id,
      sdc.batch_item_id,
      sdc.segment_date_raw
    FROM segment_date_candidates AS sdc
    WHERE sdc.segment_match_rank = 1
  ),
  amount_candidates AS (
    SELECT
      rkc.batch_id,
      rkc.batch_item_id,
      rkc.item_timesheet_id,
      rkc.item_type_norm,
      rkc.item_type_raw,
      rkc.item_source_ref,
      rkc.item_amount_ex_vat,
      rkc.item_amount_inc_vat,
      rkc.item_frozen_target_amount_ex_vat,
      rkc.item_frozen_source_amount,
      rkc.item_has_source_target_split,
      rkc.direct_key_type,
      rkc.direct_key_value,
      rkc.snapshot_key_type,
      rkc.snapshot_key_value,
      rkc.basis_work_date_raw,
      rkc.basis_adjustment_id_raw,
      rkc.basis_expense_code_raw,
      rkc.basis_additional_code_raw,
      sdp.segment_date_raw,
      public._pay_batch_item_source_reservation_amount_ex_vat(rkc.batch_item_id) AS entitlement_source_amount_ex_vat,
      (
        SELECT target_candidates.target_text_value::numeric
        FROM (
          VALUES
            (rkc.item_frozen_target_amount_ex_vat::text),
            (rkc.item_amount_ex_vat::text),
            (rkc.item_frozen_component_snapshot_json->>'frozen_target_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'target_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'target_pay_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'target_pay_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'target_amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'target_pay_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'amount_ex_vat')
        ) AS target_candidates(target_text_value)
        WHERE target_candidates.target_text_value IS NOT NULL
          AND btrim(target_candidates.target_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_target_amount_ex_vat,
      (
        SELECT source_candidates.source_text_value::numeric
        FROM (
          VALUES
            (rkc.item_frozen_source_amount::text),
            (rkc.item_frozen_component_snapshot_json->>'source_reservation_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_entitlement_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_pay_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_pay_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'basis_source_amount_ex_vat'),
            (rkc.item_frozen_component_snapshot_json->>'reserved_source_amount'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_ex_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_ex_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_ex_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_ex_vat}'),
            (rkc.item_frozen_source_basis_json->>'source_reservation_amount_ex_vat'),
            (rkc.item_frozen_source_basis_json->>'source_entitlement_amount_ex_vat'),
            (rkc.item_frozen_source_basis_json->>'source_amount_ex_vat'),
            (rkc.item_frozen_source_basis_json->>'source_pay_ex_vat'),
            (rkc.item_frozen_source_basis_json->>'pay_ex_vat'),
            (rkc.item_frozen_source_basis_json->>'amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_reservation_amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_entitlement_amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_amount_ex_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_pay_ex_vat')
        ) AS source_candidates(source_text_value)
        WHERE source_candidates.source_text_value IS NOT NULL
          AND btrim(source_candidates.source_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_artifact_source_amount_ex_vat,
      (
        SELECT source_inc_candidates.source_inc_text_value::numeric
        FROM (
          VALUES
            (rkc.item_frozen_source_basis_json->>'source_amount_inc_vat'),
            (rkc.item_frozen_source_basis_json->>'source_pay_inc_vat'),
            (rkc.item_frozen_source_basis_json->>'source_entitlement_amount_inc_vat'),
            (rkc.item_frozen_source_basis_json->>'source_reservation_amount_inc_vat'),
            (rkc.item_frozen_source_basis_json->>'pay_inc_vat'),
            (rkc.item_frozen_source_basis_json->>'amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_pay_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_entitlement_amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'source_reservation_amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'basis_source_amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json->>'reserved_source_amount_inc_vat'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_amount_inc_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_pay_inc_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_entitlement_amount_inc_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,source_reservation_amount_inc_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,pay_inc_vat}'),
            (rkc.item_frozen_component_snapshot_json#>>'{source_basis_json,amount_inc_vat}'),
            (rkc.item_frozen_resolution_payload_json->>'source_amount_inc_vat'),
            (rkc.item_frozen_resolution_payload_json->>'source_pay_inc_vat'),
            (rkc.item_frozen_resolution_payload_json->>'source_entitlement_amount_inc_vat'),
            (rkc.item_frozen_resolution_payload_json->>'source_reservation_amount_inc_vat'),
            (rkc.item_frozen_resolution_result_json->>'source_amount_inc_vat'),
            (rkc.item_frozen_resolution_result_json->>'source_pay_inc_vat'),
            (rkc.item_frozen_resolution_result_json->>'source_entitlement_amount_inc_vat'),
            (rkc.item_frozen_resolution_result_json->>'source_reservation_amount_inc_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_amount_inc_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_pay_inc_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_entitlement_amount_inc_vat'),
            (rkc.item_single_breakdown_meta_json->>'source_reservation_amount_inc_vat')
        ) AS source_inc_candidates(source_inc_text_value)
        WHERE source_inc_candidates.source_inc_text_value IS NOT NULL
          AND btrim(source_inc_candidates.source_inc_text_value) ~ '^-?[0-9]+(\.[0-9]+)?$'
        LIMIT 1
      ) AS raw_artifact_source_amount_inc_vat
    FROM raw_key_candidates AS rkc
    LEFT JOIN segment_date_pick AS sdp
      ON sdp.batch_item_id = rkc.batch_item_id
  ),
  resolved_rows AS (
    SELECT
      ac.batch_id,
      ac.batch_item_id,
      ac.item_timesheet_id,
      ac.item_type_norm,
      ac.item_type_raw,
      ac.item_source_ref,
      ac.direct_key_type,
      ac.direct_key_value,
      ac.snapshot_key_type,
      ac.snapshot_key_value,
      ac.basis_work_date_raw,
      ac.basis_adjustment_id_raw,
      ac.basis_expense_code_raw,
      ac.basis_additional_code_raw,
      ac.segment_date_raw,
      round(abs(
        CASE
          WHEN ac.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN coalesce(
              ac.entitlement_source_amount_ex_vat,
              ac.raw_artifact_source_amount_ex_vat,
              CASE
                WHEN ac.item_has_source_target_split THEN NULL
                ELSE coalesce(ac.raw_target_amount_ex_vat, ac.item_amount_ex_vat)
              END
            )
          ELSE coalesce(ac.raw_artifact_source_amount_ex_vat, ac.raw_target_amount_ex_vat, ac.item_amount_ex_vat)
        END
      ), 2)::numeric AS final_source_amount_ex_vat,
      round(abs(coalesce(
        ac.raw_artifact_source_amount_inc_vat,
        CASE
          WHEN ac.item_has_source_target_split THEN NULL
          ELSE ac.item_amount_inc_vat
        END,
        CASE
          WHEN ac.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN coalesce(
              ac.entitlement_source_amount_ex_vat,
              ac.raw_artifact_source_amount_ex_vat,
              CASE
                WHEN ac.item_has_source_target_split THEN NULL
                ELSE coalesce(ac.raw_target_amount_ex_vat, ac.item_amount_ex_vat)
              END
            )
          ELSE coalesce(ac.raw_artifact_source_amount_ex_vat, ac.raw_target_amount_ex_vat, ac.item_amount_ex_vat)
        END
      )), 2)::numeric AS final_source_amount_inc_vat,
      round(abs(coalesce(
        ac.raw_target_amount_ex_vat,
        ac.item_amount_ex_vat,
        CASE
          WHEN ac.item_type_norm IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
            THEN coalesce(ac.entitlement_source_amount_ex_vat, ac.raw_artifact_source_amount_ex_vat)
          ELSE ac.raw_artifact_source_amount_ex_vat
        END
      )), 2)::numeric AS final_target_amount_ex_vat,
      CASE
        WHEN ac.direct_key_type IS NOT NULL
         AND ac.direct_key_value IS NOT NULL
         AND (ac.direct_key_type <> 'TS_DAY' OR ac.direct_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN ac.direct_key_type
        WHEN ac.snapshot_key_type IS NOT NULL
         AND ac.snapshot_key_value IS NOT NULL
         AND (ac.snapshot_key_type <> 'TS_DAY' OR ac.snapshot_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN ac.snapshot_key_type
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'TS_DAY'
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.segment_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'TS_DAY'
        WHEN ac.item_type_norm = 'ADJUSTMENT_DELTA'
         AND ac.basis_adjustment_id_raw IS NOT NULL
          THEN 'ADJUSTMENT_CODE'
        WHEN ac.item_type_norm = 'EXPENSE_DELTA'
         AND ac.basis_additional_code_raw IS NOT NULL
          THEN 'ADDITIONAL_CODE'
        WHEN ac.item_type_norm IN ('EXPENSE_DELTA', 'MILEAGE_DELTA')
         AND ac.basis_expense_code_raw IS NOT NULL
          THEN 'EXPENSE_CODE'
        ELSE NULL
      END AS resolved_key_type,
      CASE
        WHEN ac.direct_key_type IS NOT NULL
         AND ac.direct_key_value IS NOT NULL
         AND (ac.direct_key_type <> 'TS_DAY' OR ac.direct_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN ac.direct_key_value
        WHEN ac.snapshot_key_type IS NOT NULL
         AND ac.snapshot_key_value IS NOT NULL
         AND (ac.snapshot_key_type <> 'TS_DAY' OR ac.snapshot_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN ac.snapshot_key_value
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN ac.basis_work_date_raw
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.segment_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN ac.segment_date_raw
        WHEN ac.item_type_norm = 'ADJUSTMENT_DELTA'
         AND ac.basis_adjustment_id_raw IS NOT NULL
          THEN ac.basis_adjustment_id_raw
        WHEN ac.item_type_norm = 'EXPENSE_DELTA'
         AND ac.basis_additional_code_raw IS NOT NULL
          THEN upper(ac.basis_additional_code_raw)
        WHEN ac.item_type_norm IN ('EXPENSE_DELTA', 'MILEAGE_DELTA')
         AND ac.basis_expense_code_raw IS NOT NULL
          THEN upper(ac.basis_expense_code_raw)
        ELSE NULL
      END AS resolved_key_value,
      CASE
        WHEN ac.direct_key_type IS NOT NULL
         AND ac.direct_key_value IS NOT NULL
         AND (ac.direct_key_type <> 'TS_DAY' OR ac.direct_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN 'FROZEN_ITEM_KEY'
        WHEN ac.snapshot_key_type IS NOT NULL
         AND ac.snapshot_key_value IS NOT NULL
         AND (ac.snapshot_key_type <> 'TS_DAY' OR ac.snapshot_key_value ~ '^\d{4}-\d{2}-\d{2}$')
          THEN 'FROZEN_COMPONENT_OR_BASIS_KEY'
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'FROZEN_SOURCE_BASIS_DATE'
        WHEN ac.item_type_norm = 'SEGMENT_DELTA'
         AND ac.segment_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
          THEN 'FROZEN_TIMESHEET_SNAPSHOT'
        WHEN ac.item_type_norm IN ('ADJUSTMENT_DELTA', 'EXPENSE_DELTA', 'MILEAGE_DELTA')
         AND (
              ac.basis_adjustment_id_raw IS NOT NULL
           OR ac.basis_additional_code_raw IS NOT NULL
           OR ac.basis_expense_code_raw IS NOT NULL
         )
          THEN 'FROZEN_SOURCE_BASIS_KEY'
        ELSE NULL
      END AS resolved_key_source,
      CASE
        WHEN ac.direct_key_type = 'TS_DAY'
         AND ac.direct_key_value IS NOT NULL
         AND ac.direct_key_value !~ '^\d{4}-\d{2}-\d{2}$'
         AND NOT (
           ac.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
           OR ac.segment_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
         )
          THEN 'TS_DAY_FROZEN_ITEM_KEY_VALUE_NOT_DATE'
        WHEN ac.snapshot_key_type = 'TS_DAY'
         AND ac.snapshot_key_value IS NOT NULL
         AND ac.snapshot_key_value !~ '^\d{4}-\d{2}-\d{2}$'
         AND NOT (
           ac.basis_work_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
           OR ac.segment_date_raw ~ '^\d{4}-\d{2}-\d{2}$'
         )
          THEN 'TS_DAY_FROZEN_SNAPSHOT_KEY_VALUE_NOT_DATE'
        ELSE NULL
      END AS preliminary_failure_reason
    FROM amount_candidates AS ac
  ),
  final_rows AS (
    SELECT
      rr.batch_id,
      rr.batch_item_id,
      rr.item_timesheet_id,
      rr.item_type_raw,
      rr.resolved_key_type,
      rr.resolved_key_value,
      rr.final_source_amount_ex_vat,
      rr.final_source_amount_inc_vat,
      rr.final_target_amount_ex_vat,
      rr.resolved_key_source,
      CASE
        WHEN rr.preliminary_failure_reason IS NOT NULL THEN rr.preliminary_failure_reason
        WHEN rr.resolved_key_type IS NULL OR btrim(coalesce(rr.resolved_key_type, '')) = '' THEN 'KEY_TYPE_NOT_RESOLVED'
        WHEN rr.resolved_key_value IS NULL OR btrim(coalesce(rr.resolved_key_value, '')) = '' THEN 'KEY_VALUE_NOT_RESOLVED'
        WHEN rr.resolved_key_type = 'TS_DAY' AND rr.resolved_key_value !~ '^\d{4}-\d{2}-\d{2}$' THEN 'TS_DAY_KEY_VALUE_NOT_DATE'
        WHEN rr.final_source_amount_ex_vat IS NULL THEN 'SOURCE_AMOUNT_NOT_RESOLVED'
        WHEN rr.final_target_amount_ex_vat IS NULL THEN 'TARGET_AMOUNT_NOT_RESOLVED'
        ELSE NULL
      END AS final_failure_reason
    FROM resolved_rows AS rr
  )
  SELECT
    fr.batch_id AS pay_batch_id,
    fr.batch_item_id AS pay_batch_item_id,
    fr.item_timesheet_id AS timesheet_id,
    fr.item_type_raw AS item_type,
    CASE WHEN fr.final_failure_reason IS NULL THEN fr.resolved_key_type ELSE NULL END AS key_type,
    CASE WHEN fr.final_failure_reason IS NULL THEN fr.resolved_key_value ELSE NULL END AS key_value,
    CASE WHEN fr.final_source_amount_ex_vat IS NULL THEN NULL ELSE round(fr.final_source_amount_ex_vat, 2)::numeric END AS source_amount_ex_vat,
    CASE WHEN fr.final_source_amount_inc_vat IS NULL THEN NULL ELSE round(fr.final_source_amount_inc_vat, 2)::numeric END AS source_amount_inc_vat,
    CASE WHEN fr.final_target_amount_ex_vat IS NULL THEN NULL ELSE round(fr.final_target_amount_ex_vat, 2)::numeric END AS target_amount_ex_vat,
    CASE WHEN fr.final_failure_reason IS NULL THEN fr.resolved_key_source ELSE 'KEY_RESOLUTION_FAILED' END AS key_resolution_source,
    fr.final_failure_reason AS key_resolution_failure_reason
  FROM final_rows AS fr
  ORDER BY fr.batch_id, fr.batch_item_id;
END;
$function$;





CREATE OR REPLACE FUNCTION public.banking_get_capabilities()

  
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text;
  v_env text;

  v_supports_scheduling boolean;
  v_supports_name_check boolean;
  v_supports_auto_execute boolean;

  v_supports_csv_confirm boolean;

  -- ✅ C: include default funding account in capabilities output
  v_rail_default_funding_account_ref text;

  -- ✅ NEW: payroll testing flag (simulate payments; no real bank payments)
  v_payroll_testing boolean;

  -- ✅ NEW: PAYE remittances gate
  v_paye_remittances_enabled boolean;
begin
  -- settings_defaults is expected to have a single row; do not assume an id column.
  select
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_scheduling,
    sd.rail_supports_name_check,
    sd.rail_supports_auto_execute,
    sd.rail_default_funding_account_ref,
    sd.payroll_testing,
    sd.paye_remittances_enabled
  into
    v_provider,
    v_env,
    v_supports_scheduling,
    v_supports_name_check,
    v_supports_auto_execute,
    v_rail_default_funding_account_ref,
    v_payroll_testing,
    v_paye_remittances_enabled
  from public.settings_defaults sd
  limit 1;

  v_provider := upper(btrim(coalesce(v_provider, 'CSV')));
  v_env := upper(btrim(coalesce(v_env, 'PROD')));

  v_supports_scheduling := coalesce(v_supports_scheduling, false);
  v_supports_name_check := coalesce(v_supports_name_check, false);
  v_supports_auto_execute := coalesce(v_supports_auto_execute, false);

  v_payroll_testing := coalesce(v_payroll_testing, false);
  v_paye_remittances_enabled := coalesce(v_paye_remittances_enabled, false);

  -- CSV rail implies manual bank confirmation (upload + confirm).
  v_supports_csv_confirm := (v_provider = 'CSV');

  return jsonb_build_object(
    'rail_provider', v_provider,
    'rail_env', v_env,
    'supports_scheduling', v_supports_scheduling,
    'supports_name_check', v_supports_name_check,
    'supports_auto_execute', v_supports_auto_execute,
    'supports_csv_confirm', v_supports_csv_confirm,
    'requires_manual_bank_confirm', v_supports_csv_confirm,

    -- ✅ NEW: surface test-mode switch for UI/backend consistency
    'payroll_testing', v_payroll_testing,

    -- ✅ NEW: PAYE remittance gate (UI can block PAYE remittance send)
    'paye_remittances_enabled', v_paye_remittances_enabled,

    -- ✅ C: surface saved default so UI can preselect consistently
    'rail_default_funding_account_ref', v_rail_default_funding_account_ref
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_timesheet_components(p_snapshot_json jsonb)
RETURNS TABLE (
  key_type text,
  key_value text,
  amount_ex_vat numeric,
  amount_inc_vat numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
with
seg_raw as (
  select
    nullif(btrim(coalesce(seg->>'segment_id','')), '') as segment_id,
    nullif(btrim(coalesce(seg->>'date','')), '') as seg_date_raw,
    coalesce(nullif(seg->>'exclude_from_pay','')::boolean, false) as exclude_from_pay,
    case
      when coalesce(seg->>'pay_amount','') ~ '^-?\d+(\.\d+)?$' then (seg->>'pay_amount')::numeric
      else 0::numeric
    end as pay_amount_ex
  from jsonb_array_elements(coalesce(p_snapshot_json->'segments','[]'::jsonb)) as seg
  where seg is not null and jsonb_typeof(seg) = 'object'
),
seg_norm as (
  select
    case
      when sr.seg_date_raw ~ '^\d{4}-\d{2}-\d{2}$' then 'TS_DAY'
      else 'TS_TOTAL'
    end as key_type,
    case
      when sr.seg_date_raw ~ '^\d{4}-\d{2}-\d{2}$' then sr.seg_date_raw
      else 'TOTAL'
    end as key_value,
    round(
      sum(
        case
          when sr.exclude_from_pay then 0::numeric
          else coalesce(sr.pay_amount_ex,0)
        end
      ),
      2
    ) as amount_ex_vat
  from seg_raw sr
  where sr.segment_id is not null
  group by 1,2
),
add_kv as (
  select
    upper(btrim(e.key)) as code,
    e.value as obj
  from jsonb_each(coalesce(p_snapshot_json->'additional_units_json','{}'::jsonb)) as e
  where e.key is not null
    and btrim(e.key) <> ''
    and e.value is not null
    and jsonb_typeof(e.value) = 'object'
),
add_by_code as (
  select
    'ADDITIONAL_CODE'::text as key_type,
    ak.code as key_value,
    round(
      coalesce(
        case when coalesce(ak.obj->>'pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'pay_ex_vat')::numeric end,
        case when coalesce(ak.obj->>'amount_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'amount_ex_vat')::numeric end,
        (
          coalesce(
            case when coalesce(ak.obj->>'unit_count','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'unit_count')::numeric end,
            case when coalesce(ak.obj->>'units_week','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'units_week')::numeric end,
            0::numeric
          )
          *
          coalesce(
            case when coalesce(ak.obj->>'pay_rate','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'pay_rate')::numeric end,
            case when coalesce(ak.obj->>'rate','') ~ '^-?\d+(\.\d+)?$' then (ak.obj->>'rate')::numeric end,
            0::numeric
          )
        ),
        0::numeric
      ),
      2
    ) as amount_ex_vat
  from add_kv ak
),
add_sum as (
  select
    round(coalesce(sum(abc.amount_ex_vat),0),2) as sum_ex
  from add_by_code abc
),
add_total_fallback as (
  select
    'ADDITIONAL_CODE'::text as key_type,
    'TOTAL'::text as key_value,
    round(
      case
        when coalesce(p_snapshot_json->>'additional_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (p_snapshot_json->>'additional_pay_ex_vat')::numeric
        else 0::numeric
      end,
      2
    ) as amount_ex_vat
  where (select coalesce(a.sum_ex,0) from add_sum a) = 0
    and (
      coalesce(p_snapshot_json->>'additional_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      and (p_snapshot_json->>'additional_pay_ex_vat')::numeric <> 0
    )
),
exp_vals as (
  select
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,travel_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,travel_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as travel_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as accom_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,other_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,other_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as other_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,mileage_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as mileage_ex,
    round(
      case when coalesce(p_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','') ~ '^-?\d+(\.\d+)?$'
           then (p_snapshot_json #>> '{expenses,expenses_pay_ex_vat}')::numeric else 0::numeric end, 2
    ) as expenses_rollup_ex
),
exp_has_cats as (
  select
    (coalesce(ev.travel_ex,0) <> 0)
    or (coalesce(ev.accom_ex,0) <> 0)
    or (coalesce(ev.other_ex,0) <> 0)
    or (coalesce(ev.mileage_ex,0) <> 0) as has_any_cat
  from exp_vals ev
),
exp_components as (
  select 'EXPENSE_CODE'::text as key_type, 'TRAVEL'::text as key_value, ev.travel_ex as amount_ex_vat
  from exp_vals ev
  where coalesce(ev.travel_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'ACCOMMODATION'::text, ev.accom_ex
  from exp_vals ev
  where coalesce(ev.accom_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'OTHER'::text, ev.other_ex
  from exp_vals ev
  where coalesce(ev.other_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'MILEAGE'::text, ev.mileage_ex
  from exp_vals ev
  where coalesce(ev.mileage_ex,0) <> 0
  union all
  select 'EXPENSE_CODE'::text, 'EXPENSES'::text, ev.expenses_rollup_ex
  from exp_vals ev
  where (select eh.has_any_cat from exp_has_cats eh) = false
    and coalesce(ev.expenses_rollup_ex,0) <> 0
),
adj_components as (
  select
    'ADJUSTMENT_CODE'::text as key_type,
    nullif(btrim(coalesce(adj->>'id','')), '') as key_value,
    round(
      case
        when coalesce(adj->>'delta_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$' then (adj->>'delta_pay_ex_vat')::numeric
        else 0::numeric
      end,
      2
    ) as amount_ex_vat
  from jsonb_array_elements(coalesce(p_snapshot_json->'adjustments','[]'::jsonb)) as adj
  where adj is not null
    and jsonb_typeof(adj)='object'
    and nullif(btrim(coalesce(adj->>'id','')), '') is not null
    and (
      coalesce(adj->>'delta_pay_ex_vat','') ~ '^-?\d+(\.\d+)?$'
      and (adj->>'delta_pay_ex_vat')::numeric <> 0
    )
)
select
  s.key_type,
  s.key_value,
  s.amount_ex_vat,
  s.amount_ex_vat as amount_inc_vat
from seg_norm s

union all
select
  abc.key_type,
  abc.key_value,
  abc.amount_ex_vat,
  abc.amount_ex_vat
from add_by_code abc
where abc.amount_ex_vat <> 0

union all
select
  atf.key_type,
  atf.key_value,
  atf.amount_ex_vat,
  atf.amount_ex_vat
from add_total_fallback atf

union all
select
  ec.key_type,
  ec.key_value,
  ec.amount_ex_vat,
  ec.amount_ex_vat
from exp_components ec

union all
select
  ac.key_type,
  ac.key_value,
  ac.amount_ex_vat,
  ac.amount_ex_vat
from adj_components ac;
$$;










CREATE OR REPLACE FUNCTION public._pay_reserved_components(p_timesheet_ids uuid[])
RETURNS TABLE (
  timesheet_id uuid,
  key_type text,
  key_value text,
  amount_ex_vat numeric,
  amount_inc_vat numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
WITH
inp AS (
  SELECT COALESCE(
    (
      SELECT array_agg(DISTINCT input_values.timesheet_id_value)
      FROM unnest(COALESCE(p_timesheet_ids, ARRAY[]::uuid[])) AS input_values(timesheet_id_value)
      WHERE input_values.timesheet_id_value IS NOT NULL
    ),
    ARRAY[]::uuid[]
  ) AS ts_ids
),
active_batch_item_ids AS (
  SELECT
    public.pay_batch_items.id AS pay_batch_item_id
  FROM inp AS input_scope
  JOIN public.pay_batch_items
    ON public.pay_batch_items.timesheet_id = ANY(input_scope.ts_ids)
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
  JOIN public.pay_batches
    ON public.pay_batches.id = public.pay_batch_candidates.pay_batch_id
  LEFT JOIN public.pay_bank_transfers
    ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
  WHERE public.pay_batch_items.timesheet_id IS NOT NULL
    AND COALESCE(public.pay_batch_items.is_voided, false) = false
    AND upper(coalesce(public.pay_batch_items.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND public._pay_batch_status_is_active_reservation(public.pay_batches.status)
    AND public.pay_batch_items.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id) IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_corrections
      WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
        AND applied_corrections.status = 'APPLIED'
        AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
      OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
      OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
    )
),
open_correction_exact_item_ids AS (
  SELECT DISTINCT
    open_correction_requests.id AS correction_request_id,
    open_correction_requests.pay_batch_id AS pay_batch_id,
    parsed_exact_item_ids.pay_batch_item_id AS pay_batch_item_id
  FROM public.pay_payment_correction_requests AS open_correction_requests
  JOIN LATERAL (
    SELECT DISTINCT
      exact_item_text_values.item_id_text::uuid AS pay_batch_item_id
    FROM (
      SELECT item_array_values.item_id_text
      FROM jsonb_array_elements_text(
        CASE
          WHEN jsonb_typeof(open_correction_requests.plan_json->'selected_pay_batch_item_ids') = 'array'
            THEN open_correction_requests.plan_json->'selected_pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}') = 'array'
            THEN open_correction_requests.plan_json#>'{selection,selected_pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}') = 'array'
            THEN open_correction_requests.plan_json#>'{selection,pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_requests.plan_json#>'{work_expansion_plan,selected_pay_batch_item_ids}') = 'array'
            THEN open_correction_requests.plan_json#>'{work_expansion_plan,selected_pay_batch_item_ids}'
          WHEN jsonb_typeof(open_correction_requests.selection_json->'selected_pay_batch_item_ids') = 'array'
            THEN open_correction_requests.selection_json->'selected_pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_requests.selection_json->'pay_batch_item_ids') = 'array'
            THEN open_correction_requests.selection_json->'pay_batch_item_ids'
          WHEN jsonb_typeof(open_correction_requests.selection_json->'expected_pay_batch_item_ids') = 'array'
            THEN open_correction_requests.selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_array_values(item_id_text)

      UNION ALL

      SELECT open_correction_requests.selection_json->>'pay_batch_item_id'
      WHERE open_correction_requests.selection_json ? 'pay_batch_item_id'

      UNION ALL

      SELECT open_correction_requests.selection_json->>'expected_pay_batch_item_id'
      WHERE open_correction_requests.selection_json ? 'expected_pay_batch_item_id'
    ) AS exact_item_text_values
    WHERE nullif(btrim(coalesce(exact_item_text_values.item_id_text, '')), '') IS NOT NULL
      AND nullif(btrim(coalesce(exact_item_text_values.item_id_text, '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  ) AS parsed_exact_item_ids
    ON true
  JOIN public.pay_batch_items AS exact_pay_batch_items
    ON exact_pay_batch_items.id = parsed_exact_item_ids.pay_batch_item_id
  JOIN public.pay_batch_candidates AS exact_pay_batch_candidates
    ON exact_pay_batch_candidates.id = exact_pay_batch_items.pay_batch_candidate_id
   AND exact_pay_batch_candidates.pay_batch_id = open_correction_requests.pay_batch_id
  WHERE open_correction_requests.status IN ('REQUESTED','AWAITING_AUTHORISATION','AUTHORISED','EXPANDED','PROCESSING','BLOCKED')
    AND open_correction_requests.correction_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','MANUAL_EVIDENCE_NO_MONEY')
),
open_correction_hold_item_ids AS (
  SELECT DISTINCT
    open_correction_exact_item_ids.pay_batch_item_id AS pay_batch_item_id
  FROM inp AS input_scope
  JOIN open_correction_exact_item_ids
    ON true
  JOIN public.pay_batch_items AS selected_pay_batch_items
    ON selected_pay_batch_items.id = open_correction_exact_item_ids.pay_batch_item_id
  JOIN public.pay_batch_candidates AS selected_pay_batch_candidates
    ON selected_pay_batch_candidates.id = selected_pay_batch_items.pay_batch_candidate_id
   AND selected_pay_batch_candidates.pay_batch_id = open_correction_exact_item_ids.pay_batch_id
  LEFT JOIN public.pay_bank_transfers AS selected_pay_bank_transfers
    ON selected_pay_bank_transfers.id = selected_pay_batch_items.pay_bank_transfer_id
  WHERE selected_pay_batch_items.timesheet_id = ANY(input_scope.ts_ids)
    AND selected_pay_batch_items.timesheet_id IS NOT NULL
    AND COALESCE(selected_pay_batch_items.is_voided, false) = false
    AND upper(coalesce(selected_pay_batch_items.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND selected_pay_batch_items.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND public._pay_batch_item_source_reservation_amount_ex_vat(selected_pay_batch_items.id) IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_corrections
      WHERE applied_corrections.pay_batch_item_id = selected_pay_batch_items.id
        AND applied_corrections.status = 'APPLIED'
        AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(selected_pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
      OR selected_pay_batch_candidates.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(selected_pay_bank_transfers.status, ''))) = 'COMPLETED'
      OR selected_pay_bank_transfers.completed_at_utc IS NOT NULL
    )
),
unresolved_terminal_failure_hold_item_ids AS (
  SELECT DISTINCT
    public.pay_batch_items.id AS pay_batch_item_id
  FROM inp AS input_scope
  JOIN public.pay_batch_items
    ON public.pay_batch_items.timesheet_id = ANY(input_scope.ts_ids)
  JOIN public.pay_batch_candidates
    ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
  JOIN public.pay_bank_transfer_events
    ON public.pay_bank_transfer_events.pay_batch_id = public.pay_batch_candidates.pay_batch_id
   AND public.pay_bank_transfer_events.pay_bank_transfer_id = public.pay_batch_items.pay_bank_transfer_id
   AND public.pay_bank_transfer_events.mapping_status = 'MATCHED'
   AND public.pay_bank_transfer_events.normalised_state IN ('FAILED','DECLINED','REJECTED','CANCELLED')
  LEFT JOIN public.pay_bank_transfers
    ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
  WHERE public.pay_batch_items.timesheet_id IS NOT NULL
    AND COALESCE(public.pay_batch_items.is_voided, false) = false
    AND upper(coalesce(public.pay_batch_items.pay_channel, '')) IN ('PAYE','UMBRELLA')
    AND public.pay_batch_items.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id) IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS applied_corrections
      WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
        AND applied_corrections.status = 'APPLIED'
        AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND NOT (
      upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
      OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
      OR upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
      OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
    )
),
active_item_ids AS (
  SELECT active_batch_item_ids.pay_batch_item_id
  FROM active_batch_item_ids
  UNION
  SELECT open_correction_hold_item_ids.pay_batch_item_id
  FROM open_correction_hold_item_ids
  UNION
  SELECT unresolved_terminal_failure_hold_item_ids.pay_batch_item_id
  FROM unresolved_terminal_failure_hold_item_ids
),
reserved_keyed AS (
  SELECT
    economic_components.timesheet_id,
    UPPER(NULLIF(BTRIM(COALESCE(economic_components.key_type, '')), '')) AS key_type,
    NULLIF(BTRIM(COALESCE(economic_components.key_value, '')), '') AS key_value,
    ROUND(COALESCE(economic_components.source_amount_ex_vat, 0), 2) AS amount_ex_vat,
    ROUND(COALESCE(economic_components.source_amount_inc_vat, 0), 2) AS amount_inc_vat
  FROM active_item_ids AS active_items
  JOIN LATERAL public._pay_batch_item_economic_components(
    p_pay_batch_item_ids => ARRAY[active_items.pay_batch_item_id]::uuid[]
  ) AS economic_components
    ON true
  WHERE economic_components.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    AND economic_components.key_resolution_failure_reason IS NULL
    AND economic_components.source_amount_ex_vat IS NOT NULL
    AND economic_components.key_type IN ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
),
reserved_components AS (
  SELECT
    reserved_keyed.timesheet_id,
    reserved_keyed.key_type,
    reserved_keyed.key_value,
    ROUND(SUM(COALESCE(reserved_keyed.amount_ex_vat, 0)), 2) AS amount_ex_vat,
    ROUND(SUM(COALESCE(reserved_keyed.amount_inc_vat, 0)), 2) AS amount_inc_vat
  FROM reserved_keyed
  WHERE reserved_keyed.timesheet_id IS NOT NULL
    AND reserved_keyed.key_type IS NOT NULL
    AND BTRIM(reserved_keyed.key_type) <> ''
    AND reserved_keyed.key_value IS NOT NULL
    AND BTRIM(reserved_keyed.key_value) <> ''
    AND NOT (reserved_keyed.key_type = 'TS_DAY' AND reserved_keyed.key_value !~ '^\d{4}-\d{2}-\d{2}$')
  GROUP BY
    reserved_keyed.timesheet_id,
    reserved_keyed.key_type,
    reserved_keyed.key_value
)
SELECT
  reserved_components.timesheet_id,
  reserved_components.key_type,
  reserved_components.key_value,
  reserved_components.amount_ex_vat,
  reserved_components.amount_inc_vat
FROM reserved_components;
$$;









CREATE OR REPLACE FUNCTION public._pay_outstanding_components(p_timesheet_ids uuid[])
 RETURNS TABLE(timesheet_id uuid, key_type text, key_value text, truth_ex_vat numeric, baseline_ex_vat numeric, reserved_ex_vat numeric, outstanding_ex_vat numeric, truth_inc_vat numeric, baseline_inc_vat numeric, reserved_inc_vat numeric, outstanding_inc_vat numeric, reservation_overrun_detected boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
with
inp as (
  select coalesce(
    (
      select array_agg(distinct t_input.x)
      from unnest(coalesce(p_timesheet_ids, array[]::uuid[])) as t_input(x)
      where t_input.x is not null
    ),
    array[]::uuid[]
  ) as ts_ids
),
tf as (
  select
    tfin.timesheet_id,
    tfin.total_pay_ex_vat,
    tfin.invoice_breakdown_json,
    tfin.additional_units_json,
    tfin.expenses_pay_ex_vat,
    tfin.travel_pay_ex_vat,
    tfin.accommodation_pay_ex_vat,
    tfin.other_pay_ex_vat,
    tfin.mileage_pay_ex_vat,
    ts.booking_id,
    upper(coalesce(ts.sheet_scope::text,'')) as sheet_scope,
    ts.reference_number,
    ts.worked_start_iso as ts_worked_start_iso,
    ts.worked_end_iso as ts_worked_end_iso,
    ts.break_start_iso as ts_break_start_iso,
    ts.break_end_iso as ts_break_end_iso,
    ts.break_minutes as ts_break_minutes,
    ts.actual_schedule_json as ts_actual_schedule_json,
    tfin.worked_start_iso as tf_worked_start_iso,
    tfin.worked_end_iso as tf_worked_end_iso,
    tfin.break_start_iso as tf_break_start_iso,
    tfin.break_end_iso as tf_break_end_iso,
    tfin.break_minutes as tf_break_minutes,
    tfin.actual_schedule_json as tf_actual_schedule_json
  from inp i
  left join public.timesheets_financials tfin
    on tfin.is_current = true
   and tfin.timesheet_id = any(i.ts_ids)
  left join public.timesheets ts
    on ts.timesheet_id = tfin.timesheet_id
   and ts.is_current = true
),
truth_enriched as (
  select
    tf0.timesheet_id,
    tf0.total_pay_ex_vat,
    tf0.invoice_breakdown_json,
    tf0.additional_units_json,
    tf0.expenses_pay_ex_vat,
    tf0.travel_pay_ex_vat,
    tf0.accommodation_pay_ex_vat,
    tf0.other_pay_ex_vat,
    tf0.mileage_pay_ex_vat,
    tf0.booking_id,
    tf0.sheet_scope,
    tf0.reference_number,
    coalesce(tf0.tf_worked_start_iso, tf0.ts_worked_start_iso) as effective_worked_start_iso,
    coalesce(tf0.tf_worked_end_iso, tf0.ts_worked_end_iso) as effective_worked_end_iso,
    coalesce(tf0.tf_break_start_iso, tf0.ts_break_start_iso) as effective_break_start_iso,
    coalesce(tf0.tf_break_end_iso, tf0.ts_break_end_iso) as effective_break_end_iso,
    coalesce(tf0.tf_break_minutes, tf0.ts_break_minutes) as effective_break_minutes,
    case
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'object' then tf0.tf_actual_schedule_json
      when jsonb_typeof(tf0.tf_actual_schedule_json) = 'array' then (
        select tf_sched_item.value
        from jsonb_array_elements(tf0.tf_actual_schedule_json) as tf_sched_item(value)
        where tf_sched_item.value is not null
          and jsonb_typeof(tf_sched_item.value) = 'object'
        limit 1
      )
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'object' then tf0.ts_actual_schedule_json
      when jsonb_typeof(tf0.ts_actual_schedule_json) = 'array' then (
        select ts_sched_item.value
        from jsonb_array_elements(tf0.ts_actual_schedule_json) as ts_sched_item(value)
        where ts_sched_item.value is not null
          and jsonb_typeof(ts_sched_item.value) = 'object'
        limit 1
      )
      else null::jsonb
    end as effective_daily_schedule_json
  from tf tf0
),
truth_segments as (
  select
    te.timesheet_id,
    case
      when te.invoice_breakdown_json is not null
       and jsonb_typeof(te.invoice_breakdown_json) = 'object'
       and upper(coalesce(te.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
       and jsonb_typeof(te.invoice_breakdown_json->'segments') = 'array'
      then (
        select coalesce(
          jsonb_agg(seg.value),
          '[]'::jsonb
        )
        from jsonb_array_elements(te.invoice_breakdown_json->'segments') as seg(value)
        where seg.value is not null
          and jsonb_typeof(seg.value) = 'object'
      )
      when te.sheet_scope = 'DAILY'
      then jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false,
          'date', case
            when te.effective_worked_start_iso is not null then ((te.effective_worked_start_iso at time zone 'Europe/London')::date)::text
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'work_date','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'ymd','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'date_ymd','')), '')
            )
          end,
          'segment_key', ('ts:' || te.timesheet_id::text),
          'segment_stable_key', ('timesheet:' || coalesce(te.booking_id, te.timesheet_id::text)),
          'ref_num', nullif(btrim(coalesce(te.reference_number,'')), ''),
          'start_utc', case
            when te.effective_worked_start_iso is not null then te.effective_worked_start_iso::text
            else null
          end,
          'end_utc', case
            when te.effective_worked_end_iso is not null then te.effective_worked_end_iso::text
            else null
          end,
          'start', case
            when te.effective_worked_start_iso is not null then to_char((te.effective_worked_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'start','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_start','')), '')
            )
          end,
          'end', case
            when te.effective_worked_end_iso is not null then to_char((te.effective_worked_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else coalesce(
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'end','')), ''),
              nullif(btrim(coalesce(te.effective_daily_schedule_json->>'worked_end','')), '')
            )
          end,
          'break_start', case
            when te.effective_break_start_iso is not null then to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '')
          end,
          'break_end', case
            when te.effective_break_end_iso is not null then to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI')
            else nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '')
          end,
          'break_mins', coalesce(
            te.effective_break_minutes::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
            nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
            case
              when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                then greatest(
                  0::numeric,
                  round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                )
              else null::numeric
            end
          ),
          'breaks', case
            when jsonb_typeof(te.effective_daily_schedule_json->'breaks') = 'array' then te.effective_daily_schedule_json->'breaks'
            when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', to_char((te.effective_break_start_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'end', to_char((te.effective_break_end_iso at time zone 'Europe/London'), 'HH24:MI'),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    case
                      when te.effective_break_start_iso is not null and te.effective_break_end_iso is not null
                        then greatest(
                          0::numeric,
                          round((extract(epoch from (te.effective_break_end_iso - te.effective_break_start_iso)) / 60.0)::numeric, 0)
                        )
                      else null::numeric
                    end
                  )
                )
              )
            when nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), '') is not null
             and nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), '') is not null
              then jsonb_build_array(
                jsonb_build_object(
                  'start', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_start','')), ''),
                  'end', nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_end','')), ''),
                  'break_mins', coalesce(
                    te.effective_break_minutes::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                    nullif(btrim(coalesce(te.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                  )
                )
              )
            else '[]'::jsonb
          end
        )
      )
      else jsonb_build_array(
        jsonb_build_object(
          'segment_id', ('ts:' || te.timesheet_id::text),
          'pay_amount', round(coalesce(te.total_pay_ex_vat,0),2),
          'exclude_from_pay', false
        )
      )
    end as segments_json
  from truth_enriched te
),
truth_snapshot_like as (
  select
    ts.timesheet_id,
    jsonb_build_object(
      'segments', ts.segments_json,
      'additional_units_json', coalesce(tf1.additional_units_json,'{}'::jsonb),
      'additional_pay_ex_vat', 0,
      'expenses', jsonb_build_object(
        'expenses_pay_ex_vat', round(coalesce(tf1.expenses_pay_ex_vat,0),2),
        'travel_pay_ex_vat', round(coalesce(tf1.travel_pay_ex_vat,0),2),
        'accommodation_pay_ex_vat', round(coalesce(tf1.accommodation_pay_ex_vat,0),2),
        'other_pay_ex_vat', round(coalesce(tf1.other_pay_ex_vat,0),2),
        'mileage_pay_ex_vat', round(coalesce(tf1.mileage_pay_ex_vat,0),2)
      ),
      'adjustments', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'id', a.id::text,
            'delta_pay_ex_vat', round(coalesce(a.delta_pay_ex_vat,0),2)
          )
          order by a.created_at nulls last, a.id
        )
        from public.ts_pay_adjustments a
        where a.as_advance = false
          and a.timesheet_id = ts.timesheet_id
      ), '[]'::jsonb)
    ) as snap_json
  from truth_segments ts
  join tf tf1
    on tf1.timesheet_id = ts.timesheet_id
),
truth_components as (
  select
    tsl.timesheet_id,
    tc.key_type,
    tc.key_value,
    tc.amount_ex_vat,
    tc.amount_inc_vat
  from truth_snapshot_like tsl
  join lateral public._pay_timesheet_components(tsl.snap_json) as tc
    on true
),
active_settled_components as (
  select
    active_rows.timesheet_id,
    active_rows.key_type,
    active_rows.key_value,
    active_rows.amount_ex_vat,
    active_rows.amount_inc_vat
  from public._pay_active_settled_components((select inp.ts_ids from inp)) as active_rows
),
legacy_baseline_timesheets as (
  select distinct
    tps.timesheet_id
  from inp i
  join public.timesheet_pay_state tps
    on tps.timesheet_id = any(i.ts_ids)
  where not exists (
    select 1
    from active_settled_components active_check
    where active_check.timesheet_id = tps.timesheet_id
  )
),
legacy_baseline_components as (
  select
    tps.timesheet_id,
    bc.key_type,
    bc.key_value,
    bc.amount_ex_vat,
    bc.amount_inc_vat
  from legacy_baseline_timesheets lbt
  join public.timesheet_pay_state tps
    on tps.timesheet_id = lbt.timesheet_id
  join lateral public._pay_timesheet_components(coalesce(tps.last_settled_snapshot_json,'{}'::jsonb)) as bc
    on true
),
baseline_components as (
  select
    active_settled_components.timesheet_id,
    active_settled_components.key_type,
    active_settled_components.key_value,
    active_settled_components.amount_ex_vat,
    active_settled_components.amount_inc_vat
  from active_settled_components
  union all
  select
    legacy_baseline_components.timesheet_id,
    legacy_baseline_components.key_type,
    legacy_baseline_components.key_value,
    legacy_baseline_components.amount_ex_vat,
    legacy_baseline_components.amount_inc_vat
  from legacy_baseline_components
),

reserved_components as (
  select
    rc.timesheet_id,
    rc.key_type,
    rc.key_value,
    rc.amount_ex_vat,
    rc.amount_inc_vat
  from public._pay_reserved_components((select i.ts_ids from inp i)) rc
),
component_truth_raw as (
  select
    pfc.linked_timesheet_id as timesheet_id,
    upper(nullif(btrim(coalesce(pfc.component_key_type,'')), '')) as raw_key_type,
    nullif(btrim(coalesce(pfc.component_key_value,'')), '') as raw_key_value,
    coalesce(pfc.source_basis_json, '{}'::jsonb) as source_basis_json,
    round(
      case
        when pa.case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum
          then coalesce(pfc.remaining_source_amount,0) * -1
        when pa.case_type = 'UNDERPAYMENT'::public.pay_finance_case_type_enum
          then coalesce(pfc.remaining_source_amount,0)
        else 0
      end,
      2
    ) as signed_amount
  from inp i
  join public.pay_finance_case_components pfc
    on pfc.linked_timesheet_id = any(i.ts_ids)
  join public.pay_advances pa
    on pa.id = pfc.finance_case_id
  where pfc.linked_timesheet_id is not null
    and pfc.closed_at_utc is null
    and coalesce(pfc.remaining_source_amount,0) > 0
    and pa.case_type in (
      'OVERPAYMENT'::public.pay_finance_case_type_enum,
      'UNDERPAYMENT'::public.pay_finance_case_type_enum
    )
),
component_truth_canonical_fallback as (
  select
    ctr.timesheet_id,
    ctr.source_basis_json,
    ctr.signed_amount,
    case
      when ctr.raw_key_type = 'TS_DAY'
       and coalesce(ctr.raw_key_value, '') ~ '^\d{4}-\d{2}-\d{2}$'
        then 'TS_DAY'
      when ctr.raw_key_type in ('TS_TOTAL', 'CASE_TOTAL')
       and upper(coalesce(ctr.raw_key_value, 'TOTAL')) = 'TOTAL'
        then 'TS_TOTAL'
      when ctr.raw_key_type = 'ADJUSTMENT_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then 'ADJUSTMENT_CODE'
      when ctr.raw_key_type = 'ADDITIONAL_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then 'ADDITIONAL_CODE'
      when ctr.raw_key_type = 'EXPENSE_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then 'EXPENSE_CODE'
      else null
    end as fallback_key_type,
    case
      when ctr.raw_key_type = 'TS_DAY'
       and coalesce(ctr.raw_key_value, '') ~ '^\d{4}-\d{2}-\d{2}$'
        then ctr.raw_key_value
      when ctr.raw_key_type in ('TS_TOTAL', 'CASE_TOTAL')
       and upper(coalesce(ctr.raw_key_value, 'TOTAL')) = 'TOTAL'
        then 'TOTAL'
      when ctr.raw_key_type = 'ADJUSTMENT_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then nullif(btrim(coalesce(ctr.raw_key_value, '')), '')
      when ctr.raw_key_type = 'ADDITIONAL_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then upper(nullif(btrim(coalesce(ctr.raw_key_value, '')), ''))
      when ctr.raw_key_type = 'EXPENSE_CODE'
       and nullif(btrim(coalesce(ctr.raw_key_value, '')), '') is not null
        then upper(nullif(btrim(coalesce(ctr.raw_key_value, '')), ''))
      else null
    end as fallback_key_value
  from component_truth_raw ctr
),
component_truth_keyed as (
  select
    ctf.timesheet_id,
    case
      when nullif(btrim(coalesce(ctf.source_basis_json->>'work_date','')), '') ~ '^\d{4}-\d{2}-\d{2}$' then 'TS_DAY'
      when nullif(btrim(coalesce(ctf.source_basis_json->>'adjustment_id','')), '') is not null then 'ADJUSTMENT_CODE'
      when nullif(btrim(coalesce(ctf.source_basis_json->>'additional_code','')), '') is not null then 'ADDITIONAL_CODE'
      when nullif(btrim(coalesce(ctf.source_basis_json->>'expense_code','')), '') is not null then 'EXPENSE_CODE'
      else ctf.fallback_key_type
    end as key_type,
    case
      when nullif(btrim(coalesce(ctf.source_basis_json->>'work_date','')), '') ~ '^\d{4}-\d{2}-\d{2}$'
        then nullif(btrim(coalesce(ctf.source_basis_json->>'work_date','')), '')
      when nullif(btrim(coalesce(ctf.source_basis_json->>'adjustment_id','')), '') is not null
        then nullif(btrim(coalesce(ctf.source_basis_json->>'adjustment_id','')), '')
      when nullif(btrim(coalesce(ctf.source_basis_json->>'additional_code','')), '') is not null
        then upper(nullif(btrim(coalesce(ctf.source_basis_json->>'additional_code','')), ''))
      when nullif(btrim(coalesce(ctf.source_basis_json->>'expense_code','')), '') is not null
        then upper(nullif(btrim(coalesce(ctf.source_basis_json->>'expense_code','')), ''))
      else ctf.fallback_key_value
    end as key_value,
    ctf.signed_amount
  from component_truth_canonical_fallback ctf
),
component_truth as (
  select
    ctk.timesheet_id,
    ctk.key_type,
    ctk.key_value,
    round(sum(ctk.signed_amount), 2) as truth_ex_vat,
    round(sum(ctk.signed_amount), 2) as truth_inc_vat
  from component_truth_keyed ctk
  where ctk.key_type is not null
    and btrim(ctk.key_type) <> ''
    and ctk.key_value is not null
    and btrim(ctk.key_value) <> ''
  group by
    ctk.timesheet_id,
    ctk.key_type,
    ctk.key_value
),
component_keys as (
  select distinct
    component_truth_keys.timesheet_id,
    component_truth_keys.key_type,
    component_truth_keys.key_value
  from component_truth component_truth_keys
),
component_joined as (
  select
    ck.timesheet_id,
    ck.key_type,
    ck.key_value,
    coalesce(ct.truth_ex_vat,0) as truth_ex_vat,
    0::numeric as baseline_ex_vat,
    coalesce(rc.amount_ex_vat,0) as reserved_ex_vat,
    coalesce(ct.truth_inc_vat,0) as truth_inc_vat,
    0::numeric as baseline_inc_vat,
    coalesce(rc.amount_inc_vat,0) as reserved_inc_vat
  from component_keys ck
  left join component_truth ct
    on ct.timesheet_id = ck.timesheet_id
   and ct.key_type = ck.key_type
   and ct.key_value = ck.key_value
  left join reserved_components rc
    on rc.timesheet_id = ck.timesheet_id
   and rc.key_type = ck.key_type
   and rc.key_value = ck.key_value
),
all_legacy_keys as (
  select distinct
    x.timesheet_id,
    x.key_type,
    x.key_value
  from (
    select tc.timesheet_id, tc.key_type, tc.key_value from truth_components tc
    union all
    select bc.timesheet_id, bc.key_type, bc.key_value from baseline_components bc
    union all
    select rc.timesheet_id, rc.key_type, rc.key_value from reserved_components rc
  ) x
),
legacy_joined as (
  select
    ak.timesheet_id,
    ak.key_type,
    ak.key_value,
    coalesce(tc.amount_ex_vat,0) as truth_ex_vat,
    coalesce(bc.amount_ex_vat,0) as baseline_ex_vat,
    coalesce(rc.amount_ex_vat,0) as reserved_ex_vat,
    coalesce(tc.amount_inc_vat,0) as truth_inc_vat,
    coalesce(bc.amount_inc_vat,0) as baseline_inc_vat,
    coalesce(rc.amount_inc_vat,0) as reserved_inc_vat
  from all_legacy_keys ak
  left join truth_components tc
    on tc.timesheet_id = ak.timesheet_id
   and tc.key_type = ak.key_type
   and tc.key_value = ak.key_value
  left join baseline_components bc
    on bc.timesheet_id = ak.timesheet_id
   and bc.key_type = ak.key_type
   and bc.key_value = ak.key_value
  left join reserved_components rc
    on rc.timesheet_id = ak.timesheet_id
   and rc.key_type = ak.key_type
   and rc.key_value = ak.key_value
),
final_rows as (
  select
    cj.timesheet_id,
    cj.key_type,
    cj.key_value,
    cj.truth_ex_vat,
    cj.baseline_ex_vat,
    cj.reserved_ex_vat,
    cj.truth_inc_vat,
    cj.baseline_inc_vat,
    cj.reserved_inc_vat
  from component_joined cj

  union all

  select
    lj.timesheet_id,
    lj.key_type,
    lj.key_value,
    lj.truth_ex_vat,
    lj.baseline_ex_vat,
    lj.reserved_ex_vat,
    lj.truth_inc_vat,
    lj.baseline_inc_vat,
    lj.reserved_inc_vat
  from legacy_joined lj
  where not exists (
    select 1
    from component_truth ct
    where ct.timesheet_id = lj.timesheet_id
      and ct.key_type = lj.key_type
      and ct.key_value = lj.key_value
  )
)
select
  fr.timesheet_id,
  fr.key_type,
  fr.key_value,
  round(fr.truth_ex_vat,2) as truth_ex_vat,
  round(fr.baseline_ex_vat,2) as baseline_ex_vat,
  round(fr.reserved_ex_vat,2) as reserved_ex_vat,
  round(fr.truth_ex_vat - fr.baseline_ex_vat - fr.reserved_ex_vat,2) as outstanding_ex_vat,
  round(fr.truth_inc_vat,2) as truth_inc_vat,
  round(fr.baseline_inc_vat,2) as baseline_inc_vat,
  round(fr.reserved_inc_vat,2) as reserved_inc_vat,
  round(fr.truth_inc_vat - fr.baseline_inc_vat - fr.reserved_inc_vat,2) as outstanding_inc_vat,
  (
    round(abs(fr.reserved_ex_vat),2) >
    round(abs(greatest(fr.truth_ex_vat - fr.baseline_ex_vat, 0)),2)
  ) as reservation_overrun_detected
from final_rows fr
where fr.timesheet_id is not null
  and fr.key_type is not null
  and fr.key_value is not null;
$function$;




CREATE OR REPLACE FUNCTION public._pay_candidate_week_totals(p_candidate_ids uuid[], p_week_start date)
RETURNS TABLE (
  candidate_id uuid,
  week_start date,
  paid_wtd numeric,
  loan_repaid_wtd numeric,
  overpay_recovered_wtd numeric
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAY_CANDIDATE_WEEK_TOTALS_START',
    jsonb_build_object(
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'week_start', p_week_start
    ),
    'pay_candidate_week_totals',
    COALESCE(p_week_start::text, 'NO_WEEK_START'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN QUERY
  WITH
  inp AS (
    SELECT
      COALESCE(
        (
          SELECT array_agg(DISTINCT input_candidate_ids.candidate_id_value)
          FROM unnest(COALESCE(p_candidate_ids, ARRAY[]::uuid[])) AS input_candidate_ids(candidate_id_value)
          WHERE input_candidate_ids.candidate_id_value IS NOT NULL
        ),
        ARRAY[]::uuid[]
      ) AS cand_ids,
      p_week_start AS week_start,
      (p_week_start + INTERVAL '6 days')::date AS week_end
  ),
  eligible_batches AS (
    SELECT
      public.pay_batches.id AS pay_batch_id
    FROM inp
    JOIN public.pay_batches
      ON public.pay_batches.pay_date >= inp.week_start
     AND public.pay_batches.pay_date <= inp.week_end
    WHERE public.pay_batches.cancelled_at_utc IS NULL
      AND upper(coalesce(public.pay_batches.batch_kind_fixed,'')) <> 'LOANS'
  ),
  settled_candidate_rows AS (
    SELECT
      public.pay_batch_candidates.id AS pay_batch_candidate_id,
      public.pay_batch_candidates.candidate_id,
      public.pay_batch_candidates.pay_batch_id,
      COALESCE(public.pay_batch_candidates.net_bank_amount,0)::numeric AS net_bank_amount
    FROM inp
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.candidate_id = ANY(inp.cand_ids)
    JOIN eligible_batches
      ON eligible_batches.pay_batch_id = public.pay_batch_candidates.pay_batch_id
    WHERE public.pay_batch_candidates.settled_at_utc IS NOT NULL
      AND upper(coalesce(public.pay_batch_candidates.settlement_status,'')) = 'SETTLED'
  ),
  corrected_candidate_item_amounts AS (
    SELECT
      settled_candidate_rows.pay_batch_candidate_id,
      round(
        COALESCE(
          sum(COALESCE(public.pay_batch_items.amount_inc_vat, public.pay_batch_items.amount_ex_vat, 0)),
          0
        ),
        2
      ) AS corrected_amount_inc_vat
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    JOIN public.pay_payment_correction_items
      ON public.pay_payment_correction_items.pay_batch_item_id = public.pay_batch_items.id
     AND public.pay_payment_correction_items.status = 'APPLIED'
     AND public.pay_payment_correction_items.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    GROUP BY settled_candidate_rows.pay_batch_candidate_id
  ),
  paid AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(
        COALESCE(
          sum(
            COALESCE(settled_candidate_rows.net_bank_amount,0)
            - COALESCE(corrected_candidate_item_amounts.corrected_amount_inc_vat,0)
          ),
          0
        ),
        2
      ) AS paid_wtd
    FROM settled_candidate_rows
    LEFT JOIN corrected_candidate_item_amounts
      ON corrected_candidate_item_amounts.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    GROUP BY settled_candidate_rows.candidate_id
  ),
  loan_rep AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(sum(abs(coalesce(public.pay_batch_items.amount_ex_vat, public.pay_batch_items.amount_inc_vat, 0))),2) AS loan_repaid_wtd
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    WHERE COALESCE(public.pay_batch_items.is_voided, false) = false
      AND public.pay_batch_items.item_type = 'LOAN_REPAYMENT'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    GROUP BY settled_candidate_rows.candidate_id
  ),
  overpay_rec AS (
    SELECT
      settled_candidate_rows.candidate_id,
      round(sum(abs(coalesce(public.pay_batch_items.amount_ex_vat, public.pay_batch_items.amount_inc_vat, 0))),2) AS overpay_recovered_wtd
    FROM settled_candidate_rows
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = settled_candidate_rows.pay_batch_candidate_id
    WHERE COALESCE(public.pay_batch_items.is_voided, false) = false
      AND public.pay_batch_items.item_type = 'OVERPAYMENT_RECOVERY'
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    GROUP BY settled_candidate_rows.candidate_id
  )
  SELECT
    public.candidates.id AS candidate_id,
    (SELECT inp.week_start FROM inp) AS week_start,
    COALESCE(paid.paid_wtd,0) AS paid_wtd,
    COALESCE(loan_rep.loan_repaid_wtd,0) AS loan_repaid_wtd,
    COALESCE(overpay_rec.overpay_recovered_wtd,0) AS overpay_recovered_wtd
  FROM inp
  JOIN public.candidates
    ON public.candidates.id = ANY(inp.cand_ids)
  LEFT JOIN paid
    ON paid.candidate_id = public.candidates.id
  LEFT JOIN loan_rep
    ON loan_rep.candidate_id = public.candidates.id
  LEFT JOIN overpay_rec
    ON overpay_rec.candidate_id = public.candidates.id;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAY_CANDIDATE_WEEK_TOTALS_RESULT',
    jsonb_build_object(
      'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
      'week_start', p_week_start
    ),
    'pay_candidate_week_totals',
    COALESCE(p_week_start::text, 'NO_WEEK_START'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      NULL::uuid,
      'PAY_CANDIDATE_WEEK_TOTALS_ERROR',
      jsonb_build_object(
        'candidate_count', COALESCE(array_length(p_candidate_ids, 1), 0),
        'week_start', p_week_start,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_candidate_week_totals',
      COALESCE(p_week_start::text, 'NO_WEEK_START'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
END;
$function$;


DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(
  date,
  date,
  uuid,
  jsonb,
  uuid,
  uuid,
  uuid[],
  text,
  public.pay_override_mode_enum
);




DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(date, date, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum, boolean, boolean, uuid, timestamptz);
DROP FUNCTION IF EXISTS public.pay_create_draft_batches_split(date, date, uuid, jsonb, uuid, uuid, uuid[], text, public.pay_override_mode_enum, boolean, boolean, uuid, timestamptz, uuid, boolean);



CREATE OR REPLACE FUNCTION public.pay_create_draft_batches_split(
  p_pay_date date,
  p_week_ending_cutoff date,
  p_actor_user_id uuid,
  p_preview_decisions_json jsonb,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_force_include_timesheet_ids uuid[] DEFAULT NULL::uuid[],
  p_override_reason text DEFAULT NULL,
  p_override_mode public.pay_override_mode_enum DEFAULT 'NONE'::public.pay_override_mode_enum,
  p_override_continue boolean DEFAULT false,
  p_override_verified boolean DEFAULT false,
  p_override_verified_by_user_id uuid DEFAULT NULL::uuid,
  p_override_verified_at_utc timestamptz DEFAULT NULL::timestamptz,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_allow_legacy_unchunked boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_preview_decisions_json jsonb := CASE
    WHEN jsonb_typeof(COALESCE(p_preview_decisions_json, '{}'::jsonb)) = 'object' THEN COALESCE(p_preview_decisions_json, '{}'::jsonb)
    ELSE '{}'::jsonb
  END;
  v_case_resolutions jsonb := '{}'::jsonb;
  v_case_resolutions_supplied boolean := false;
  v_umbrella_case_resolutions jsonb := '{}'::jsonb;
  v_paye_case_resolutions jsonb := '{}'::jsonb;
  v_umbrella_case_resolution_count integer := 0;
  v_paye_case_resolution_count integer := 0;
  v_case_resolution_states jsonb := '[]'::jsonb;
  v_blocked_case_states jsonb := '[]'::jsonb;
  v_safe_case_states jsonb := '[]'::jsonb;
  v_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_selected_preview_row_ids_supplied boolean := false;
  v_selected_preview_row_ids_sanitized_count integer := 0;
  v_umbrella_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_paye_selected_preview_row_ids jsonb := '[]'::jsonb;
  v_umbrella_selected_preview_row_count integer := 0;
  v_paye_selected_preview_row_count integer := 0;
  v_umbrella_preview_decisions_json jsonb := '{}'::jsonb;
  v_paye_preview_decisions_json jsonb := '{}'::jsonb;
  v_umbrella_res jsonb := '{}'::jsonb;
  v_paye_res jsonb := '{}'::jsonb;
  v_umbrella_pay_batch_id uuid := NULL::uuid;
  v_paye_pay_batch_id uuid := NULL::uuid;
  v_umbrella_overpayment_sync_only boolean := false;
  v_paye_overpayment_sync_only boolean := false;
  v_umbrella_overpayment_sync jsonb := '{}'::jsonb;
  v_paye_overpayment_sync jsonb := '{}'::jsonb;
  v_umbrella_status text := 'NOT_RUN';
  v_paye_status text := 'NOT_RUN';
  v_paye_guardrails jsonb := '{}'::jsonb;
  v_paye_scope_blocked boolean := false;
  v_paye_block_reason_code text := NULL;
  v_paye_block_message text := NULL;
  v_paye_override_required boolean := false;
  v_paye_create_blocked boolean := false;
  v_has_any_scope_outcome boolean := false;
  v_err text := '';
  v_legacy_safe_selected_row_threshold integer := 250;
  v_operation_row public.banking_pay_operations%ROWTYPE;
BEGIN
  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'pay_date is required';
  END IF;

  IF p_week_ending_cutoff IS NULL THEN
    RAISE EXCEPTION 'week_ending_cutoff is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id is required';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_create_draft_batches_split operation % was not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type <> 'DRAFT_CREATE' THEN
      RAISE EXCEPTION 'pay_create_draft_batches_split expected DRAFT_CREATE operation %, got %', p_operation_id, v_operation_row.operation_type;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_create_draft_batches_split operation % belongs to a different actor', p_operation_id;
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'requires_operation_runner', true,
      'operation_id', v_operation_row.id::text,
      'operation_type', v_operation_row.operation_type,
      'status', v_operation_row.status,
      'phase', v_operation_row.phase,
      'pay_batch_id', CASE WHEN v_operation_row.pay_batch_id IS NULL THEN NULL ELSE v_operation_row.pay_batch_id::text END,
      'workbench_session_id', CASE WHEN v_operation_row.workbench_session_id IS NULL THEN NULL ELSE v_operation_row.workbench_session_id::text END,
      'total_units', v_operation_row.total_units,
      'completed_units', v_operation_row.completed_units,
      'failed_units', v_operation_row.failed_units,
      'current_chunk_index', v_operation_row.current_chunk_index,
      'chunk_count', v_operation_row.chunk_count,
      'progress_json', COALESCE(v_operation_row.progress_json, '{}'::jsonb),
      'result_json', CASE WHEN v_operation_row.status IN ('COMPLETE', 'REVIEW_REQUIRED') THEN v_operation_row.result_json ELSE NULL END,
      'error_json', CASE WHEN v_operation_row.status IN ('FAILED', 'CANCELLED', 'REVIEW_REQUIRED') THEN v_operation_row.error_json ELSE NULL END,
      'message', 'Draft creation is running through the scalable Banking Pay operation flow.'
    );
  END IF;

  IF COALESCE(p_allow_legacy_unchunked, false) IS NOT TRUE THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCHES_SPLIT_OPERATION_REQUIRED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'pay_create_draft_batches_split refused legacy split all-at-once draft creation. Normal frontend draft creation must use the scalable Banking Pay DRAFT_CREATE operation flow; set p_allow_legacy_unchunked only for explicit small diagnostic/test compatibility.',
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF COALESCE(p_override_mode, 'NONE'::public.pay_override_mode_enum) = 'TIMESHEET_ADVANCE'::public.pay_override_mode_enum THEN
    RAISE EXCEPTION 'TIMESHEET_ADVANCE is no longer supported by pay_create_draft_batches_split';
  END IF;

  IF jsonb_typeof(v_preview_decisions_json) <> 'object' THEN
    RAISE EXCEPTION 'preview_decisions_json must be a jsonb object';
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_preview_decisions_json->>'session_id', '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'Session-backed draft creation must use public.pay_workbench_prepare_draft(...)';
  END IF;

  IF jsonb_typeof(COALESCE(v_preview_decisions_json->'case_resolution_states', '[]'::jsonb)) = 'array' THEN
    v_case_resolution_states := COALESCE(v_preview_decisions_json->'case_resolution_states', '[]'::jsonb);
  ELSE
    v_case_resolution_states := '[]'::jsonb;
  END IF;

  IF jsonb_typeof(COALESCE(v_preview_decisions_json->'blocked_case_states', '[]'::jsonb)) = 'array' THEN
    v_blocked_case_states := COALESCE(v_preview_decisions_json->'blocked_case_states', '[]'::jsonb);
  ELSE
    v_blocked_case_states := '[]'::jsonb;
  END IF;

  IF jsonb_typeof(COALESCE(v_preview_decisions_json->'safe_case_states', '[]'::jsonb)) = 'array' THEN
    v_safe_case_states := COALESCE(v_preview_decisions_json->'safe_case_states', '[]'::jsonb);
  ELSE
    v_safe_case_states := '[]'::jsonb;
  END IF;

  IF v_preview_decisions_json ? 'case_resolutions' THEN
    IF v_preview_decisions_json->'case_resolutions' IS NULL
       OR jsonb_typeof(v_preview_decisions_json->'case_resolutions') = 'null' THEN
      v_case_resolutions := '{}'::jsonb;
      v_case_resolutions_supplied := false;
    ELSIF jsonb_typeof(v_preview_decisions_json->'case_resolutions') = 'object' THEN
      SELECT COALESCE(jsonb_object_agg(case_entry.key, case_entry.value), '{}'::jsonb)
      INTO v_case_resolutions
      FROM jsonb_each(COALESCE(v_preview_decisions_json->'case_resolutions', '{}'::jsonb)) AS case_entry(key, value)
      WHERE NULLIF(BTRIM(case_entry.key), '') IS NOT NULL
        AND jsonb_typeof(case_entry.value) = 'object'
        AND (
          case_entry.key ~ '^timesheet:[0-9a-fA-F-]{36}$'
          OR case_entry.key ~ '^finance:[0-9a-fA-F-]{36}$'
        );

      v_case_resolutions_supplied := EXISTS (
        SELECT 1
        FROM jsonb_each(v_case_resolutions) AS normalized_case_entry(key, value)
        LIMIT 1
      );
    ELSE
      RAISE EXCEPTION 'preview_decisions_json.case_resolutions must be an object when supplied';
    END IF;
  END IF;

  IF v_preview_decisions_json ? 'selected_preview_row_ids' THEN
    IF v_preview_decisions_json->'selected_preview_row_ids' IS NULL
       OR jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'null' THEN
      v_selected_preview_row_ids := '[]'::jsonb;
      v_selected_preview_row_ids_supplied := false;
      v_selected_preview_row_ids_sanitized_count := 0;
    ELSIF jsonb_typeof(v_preview_decisions_json->'selected_preview_row_ids') = 'array' THEN
      SELECT
        COALESCE(jsonb_agg(to_jsonb(selected_row.row_id) ORDER BY selected_row.ord), '[]'::jsonb),
        COUNT(*)::integer
      INTO
        v_selected_preview_row_ids,
        v_selected_preview_row_ids_sanitized_count
      FROM (
        SELECT DISTINCT ON (raw_row.row_id)
          raw_row.ord,
          raw_row.row_id
        FROM (
          SELECT
            selected_element.ord,
            BTRIM(selected_element.value) AS row_id
          FROM jsonb_array_elements_text(COALESCE(v_preview_decisions_json->'selected_preview_row_ids', '[]'::jsonb)) WITH ORDINALITY AS selected_element(value, ord)
        ) AS raw_row
        WHERE raw_row.row_id <> ''
        ORDER BY raw_row.row_id, raw_row.ord
      ) AS selected_row;

      IF COALESCE(v_selected_preview_row_ids_sanitized_count, 0) = 0 THEN
        RAISE EXCEPTION 'preview_decisions_json.selected_preview_row_ids must contain at least one non-blank preview row id when supplied';
      END IF;

      v_selected_preview_row_ids_supplied := true;
    ELSE
      RAISE EXCEPTION 'preview_decisions_json.selected_preview_row_ids must be an array when supplied';
    END IF;
  END IF;

  IF v_selected_preview_row_ids_supplied = true
     AND COALESCE(v_selected_preview_row_ids_sanitized_count, 0) > v_legacy_safe_selected_row_threshold THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCHES_SPLIT_LEGACY_UNCHUNKED_TOO_LARGE',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'This draft selection is too large for the legacy split all-at-once path. Even explicit legacy/test compatibility is limited to small selections; use the scalable Banking Pay draft operation flow.',
      'selected_preview_row_count', v_selected_preview_row_ids_sanitized_count,
      'safe_legacy_threshold', v_legacy_safe_selected_row_threshold,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  IF v_selected_preview_row_ids_supplied = false
     AND p_candidate_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_CREATE_DRAFT_BATCHES_SPLIT_UNBOUNDED_LEGACY_DISABLED',
      'code', 'DRAFT_CREATE_OPERATION_REQUIRED',
      'message', 'Unbounded or client-wide legacy split draft creation is disabled. Even explicit legacy/test compatibility must supply a small candidate/test scope or selected preview rows.',
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'allow_legacy_unchunked', COALESCE(p_allow_legacy_unchunked, false)
    )::text;
  END IF;

  v_preview_decisions_json := (v_preview_decisions_json - 'case_resolutions' - 'selected_preview_row_ids')
    || jsonb_build_object(
      'case_resolution_states', v_case_resolution_states,
      'blocked_case_states', v_blocked_case_states,
      'safe_case_states', v_safe_case_states
    );

  v_umbrella_preview_decisions_json := v_preview_decisions_json;
  v_paye_preview_decisions_json := v_preview_decisions_json;

  IF v_selected_preview_row_ids_supplied THEN
    WITH selected_rows AS (
      SELECT DISTINCT ON (selected_row.preview_row_id)
        selected_row.preview_row_id,
        selected_row.ord
      FROM (
        SELECT
          BTRIM(selected_element.value) AS preview_row_id,
          selected_element.ord
        FROM jsonb_array_elements_text(v_selected_preview_row_ids) WITH ORDINALITY AS selected_element(value, ord)
        WHERE BTRIM(selected_element.value) <> ''
      ) AS selected_row
      ORDER BY selected_row.preview_row_id, selected_row.ord
    ),
    selected_keys AS (
      SELECT
        selected_rows.preview_row_id,
        selected_rows.ord,
        CASE
          WHEN selected_rows.preview_row_id ~ '^finance:[0-9a-fA-F-]{36}:' THEN NULLIF(BTRIM(split_part(selected_rows.preview_row_id, ':', 2)), '')::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        CASE
          WHEN selected_rows.preview_row_id ~ '^[0-9a-fA-F-]{36}($|:)' THEN substring(selected_rows.preview_row_id from '^[0-9a-fA-F-]{36}')::uuid
          ELSE NULL::uuid
        END AS timesheet_id
      FROM selected_rows
    ),
    scoped_rows AS (
      SELECT DISTINCT ON (scope_row.preview_row_id, scope_row.pay_channel)
        scope_row.preview_row_id,
        scope_row.ord,
        scope_row.pay_channel
      FROM (
        SELECT
          selected_keys.preview_row_id,
          selected_keys.ord,
          UPPER(BTRIM(COALESCE(candidates_payee.pay_method, ''))) AS pay_channel
        FROM selected_keys
        JOIN public.v_finance_cases_register AS finance_case_register
          ON finance_case_register.finance_case_id = selected_keys.finance_case_id
        JOIN public.candidates AS candidates_payee
          ON candidates_payee.id = finance_case_register.candidate_id
        WHERE selected_keys.finance_case_id IS NOT NULL

        UNION ALL

        SELECT
          selected_keys.preview_row_id,
          selected_keys.ord,
          UPPER(BTRIM(COALESCE(candidates_timesheet.pay_method, ''))) AS pay_channel
        FROM selected_keys
        JOIN public.timesheets_financials AS timesheets_financials_current
          ON timesheets_financials_current.timesheet_id = selected_keys.timesheet_id
         AND timesheets_financials_current.is_current = true
        JOIN public.candidates AS candidates_timesheet
          ON candidates_timesheet.id = timesheets_financials_current.candidate_id
        WHERE selected_keys.finance_case_id IS NULL
          AND selected_keys.timesheet_id IS NOT NULL
      ) AS scope_row
      WHERE scope_row.pay_channel IN ('UMBRELLA', 'PAYE')
      ORDER BY scope_row.preview_row_id, scope_row.pay_channel, scope_row.ord
    )
    SELECT
      COALESCE(
        jsonb_agg(to_jsonb(scoped_rows.preview_row_id) ORDER BY scoped_rows.ord) FILTER (WHERE scoped_rows.pay_channel = 'UMBRELLA'),
        '[]'::jsonb
      ),
      COALESCE(COUNT(*) FILTER (WHERE scoped_rows.pay_channel = 'UMBRELLA'), 0)::integer,
      COALESCE(
        jsonb_agg(to_jsonb(scoped_rows.preview_row_id) ORDER BY scoped_rows.ord) FILTER (WHERE scoped_rows.pay_channel = 'PAYE'),
        '[]'::jsonb
      ),
      COALESCE(COUNT(*) FILTER (WHERE scoped_rows.pay_channel = 'PAYE'), 0)::integer
    INTO
      v_umbrella_selected_preview_row_ids,
      v_umbrella_selected_preview_row_count,
      v_paye_selected_preview_row_ids,
      v_paye_selected_preview_row_count
    FROM scoped_rows;

    IF COALESCE(v_umbrella_selected_preview_row_count, 0) = 0
       AND COALESCE(v_paye_selected_preview_row_count, 0) = 0 THEN
      RAISE EXCEPTION 'Selected preview rows are not valid for the current preview';
    END IF;

    IF COALESCE(v_umbrella_selected_preview_row_count, 0) > 0 THEN
      v_umbrella_preview_decisions_json := v_umbrella_preview_decisions_json || jsonb_build_object('selected_preview_row_ids', v_umbrella_selected_preview_row_ids);
    END IF;

    IF COALESCE(v_paye_selected_preview_row_count, 0) > 0 THEN
      v_paye_preview_decisions_json := v_paye_preview_decisions_json || jsonb_build_object('selected_preview_row_ids', v_paye_selected_preview_row_ids);
    END IF;
  END IF;

  IF v_case_resolutions_supplied THEN
    WITH case_entries AS (
      SELECT
        case_entry.key AS case_key,
        case_entry.value AS resolution_json,
        CASE
          WHEN case_entry.key ~ '^finance:[0-9a-fA-F-]{36}$' THEN substring(case_entry.key from 9)::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        CASE
          WHEN case_entry.key ~ '^timesheet:[0-9a-fA-F-]{36}$' THEN substring(case_entry.key from 11)::uuid
          ELSE NULL::uuid
        END AS timesheet_id
      FROM jsonb_each(v_case_resolutions) AS case_entry(key, value)
      WHERE NULLIF(BTRIM(case_entry.key), '') IS NOT NULL
        AND jsonb_typeof(case_entry.value) = 'object'
    ),
    selected_rows AS (
      SELECT DISTINCT ON (selected_row.preview_row_id)
        selected_row.preview_row_id,
        selected_row.ord
      FROM (
        SELECT
          BTRIM(selected_element.value) AS preview_row_id,
          selected_element.ord
        FROM jsonb_array_elements_text(COALESCE(v_selected_preview_row_ids, '[]'::jsonb)) WITH ORDINALITY AS selected_element(value, ord)
        WHERE BTRIM(selected_element.value) <> ''
      ) AS selected_row
      ORDER BY selected_row.preview_row_id, selected_row.ord
    ),
    selected_keys AS (
      SELECT
        selected_rows.preview_row_id,
        selected_rows.ord,
        CASE
          WHEN selected_rows.preview_row_id ~ '^finance:[0-9a-fA-F-]{36}:' THEN NULLIF(BTRIM(split_part(selected_rows.preview_row_id, ':', 2)), '')::uuid
          ELSE NULL::uuid
        END AS finance_case_id,
        CASE
          WHEN selected_rows.preview_row_id ~ '^[0-9a-fA-F-]{36}($|:)' THEN substring(selected_rows.preview_row_id from '^[0-9a-fA-F-]{36}')::uuid
          ELSE NULL::uuid
        END AS timesheet_id
      FROM selected_rows
    ),
    snapshot_case_rows AS (
      SELECT case_json.value AS case_json
      FROM jsonb_array_elements(COALESCE(v_case_resolution_states, '[]'::jsonb)) AS case_json(value)
      UNION ALL
      SELECT case_json.value AS case_json
      FROM jsonb_array_elements(COALESCE(v_blocked_case_states, '[]'::jsonb)) AS case_json(value)
      UNION ALL
      SELECT case_json.value AS case_json
      FROM jsonb_array_elements(COALESCE(v_safe_case_states, '[]'::jsonb)) AS case_json(value)
    ),
    snapshot_timesheet_case_links AS (
      SELECT DISTINCT
        NULLIF(BTRIM(COALESCE(snapshot_case_rows.case_json->>'case_key', '')), '') AS case_key,
        CASE
          WHEN NULLIF(BTRIM(COALESCE(snapshot_case_rows.case_json->>'case_key', '')), '') ~ '^timesheet:[0-9a-fA-F-]{36}$'
            THEN substring(snapshot_case_rows.case_json->>'case_key' from 11)::uuid
          ELSE NULL::uuid
        END AS seed_timesheet_id,
        linked_timesheet_id.value::uuid AS linked_timesheet_id
      FROM snapshot_case_rows
      CROSS JOIN LATERAL jsonb_array_elements_text(
        COALESCE(snapshot_case_rows.case_json->'linked_resolution_scope_json'->'linked_timesheet_ids', '[]'::jsonb)
      ) AS linked_timesheet_id(value)
      WHERE jsonb_typeof(snapshot_case_rows.case_json) = 'object'
        AND NULLIF(BTRIM(COALESCE(snapshot_case_rows.case_json->>'case_key', '')), '') ~ '^timesheet:[0-9a-fA-F-]{36}$'
        AND linked_timesheet_id.value ~ '^[0-9a-fA-F-]{36}$'
    ),
    selected_case_keys AS (
      SELECT
        case_key_rows.case_key,
        MIN(case_key_rows.ord)::integer AS ord
      FROM (
        SELECT
          ('finance:' || selected_keys.finance_case_id::text) AS case_key,
          selected_keys.ord
        FROM selected_keys
        WHERE selected_keys.finance_case_id IS NOT NULL

        UNION ALL

        SELECT
          ('timesheet:' || selected_keys.timesheet_id::text) AS case_key,
          selected_keys.ord
        FROM selected_keys
        WHERE selected_keys.finance_case_id IS NULL
          AND selected_keys.timesheet_id IS NOT NULL

        UNION ALL

        SELECT
          snapshot_timesheet_case_links.case_key,
          selected_keys.ord
        FROM selected_keys
        JOIN snapshot_timesheet_case_links
          ON snapshot_timesheet_case_links.linked_timesheet_id = selected_keys.timesheet_id
        WHERE selected_keys.finance_case_id IS NULL
          AND selected_keys.timesheet_id IS NOT NULL
          AND snapshot_timesheet_case_links.case_key IS NOT NULL
      ) AS case_key_rows
      GROUP BY case_key_rows.case_key
    ),
    selected_scope_rows AS (
      SELECT DISTINCT ON (scope_row.case_key, scope_row.pay_channel)
        scope_row.case_key,
        scope_row.pay_channel,
        scope_row.ord
      FROM (
        SELECT
          selected_case_keys.case_key,
          UPPER(BTRIM(COALESCE(candidates_case.pay_method, ''))) AS pay_channel,
          selected_case_keys.ord
        FROM selected_case_keys
        JOIN case_entries
          ON case_entries.case_key = selected_case_keys.case_key
        LEFT JOIN public.v_finance_cases_register AS finance_case_register
          ON finance_case_register.finance_case_id = case_entries.finance_case_id
        LEFT JOIN public.timesheets_financials AS timesheets_financials_current
          ON timesheets_financials_current.timesheet_id = case_entries.timesheet_id
         AND timesheets_financials_current.is_current = true
        JOIN public.candidates AS candidates_case
          ON candidates_case.id = COALESCE(finance_case_register.candidate_id, timesheets_financials_current.candidate_id)
      ) AS scope_row
      WHERE v_selected_preview_row_ids_supplied = true
        AND scope_row.pay_channel IN ('UMBRELLA', 'PAYE')
      ORDER BY scope_row.case_key, scope_row.pay_channel, scope_row.ord
    ),
    live_scope_rows AS (
      SELECT DISTINCT ON (scope_row.case_key, scope_row.pay_channel)
        scope_row.case_key,
        scope_row.pay_channel,
        1 AS ord
      FROM (
        SELECT
          case_entries.case_key,
          UPPER(BTRIM(COALESCE(candidates_finance.pay_method, ''))) AS pay_channel
        FROM case_entries
        JOIN public.v_finance_cases_register AS finance_case_register
          ON finance_case_register.finance_case_id = case_entries.finance_case_id
        JOIN public.candidates AS candidates_finance
          ON candidates_finance.id = finance_case_register.candidate_id
        WHERE case_entries.finance_case_id IS NOT NULL

        UNION ALL

        SELECT
          case_entries.case_key,
          UPPER(BTRIM(COALESCE(candidates_timesheet.pay_method, ''))) AS pay_channel
        FROM case_entries
        JOIN public.timesheets_financials AS timesheets_financials_current
          ON timesheets_financials_current.timesheet_id = case_entries.timesheet_id
         AND timesheets_financials_current.is_current = true
        JOIN public.candidates AS candidates_timesheet
          ON candidates_timesheet.id = timesheets_financials_current.candidate_id
        WHERE case_entries.finance_case_id IS NULL
          AND case_entries.timesheet_id IS NOT NULL
      ) AS scope_row
      WHERE v_selected_preview_row_ids_supplied = false
        AND scope_row.pay_channel IN ('UMBRELLA', 'PAYE')
      ORDER BY scope_row.case_key, scope_row.pay_channel, ord
    ),
    scope_rows AS (
      SELECT selected_scope_rows.case_key, selected_scope_rows.pay_channel, selected_scope_rows.ord
      FROM selected_scope_rows
      UNION ALL
      SELECT live_scope_rows.case_key, live_scope_rows.pay_channel, live_scope_rows.ord
      FROM live_scope_rows
    )
    SELECT
      COALESCE(jsonb_object_agg(case_entries.case_key, case_entries.resolution_json) FILTER (WHERE scope_rows.pay_channel = 'UMBRELLA'), '{}'::jsonb),
      COALESCE(COUNT(*) FILTER (WHERE scope_rows.pay_channel = 'UMBRELLA'), 0)::integer,
      COALESCE(jsonb_object_agg(case_entries.case_key, case_entries.resolution_json) FILTER (WHERE scope_rows.pay_channel = 'PAYE'), '{}'::jsonb),
      COALESCE(COUNT(*) FILTER (WHERE scope_rows.pay_channel = 'PAYE'), 0)::integer
    INTO
      v_umbrella_case_resolutions,
      v_umbrella_case_resolution_count,
      v_paye_case_resolutions,
      v_paye_case_resolution_count
    FROM case_entries
    JOIN scope_rows
      ON scope_rows.case_key = case_entries.case_key;

    IF COALESCE(v_umbrella_case_resolution_count, 0) > 0 THEN
      v_umbrella_preview_decisions_json := v_umbrella_preview_decisions_json || jsonb_build_object('case_resolutions', v_umbrella_case_resolutions);
    END IF;

    IF COALESCE(v_paye_case_resolution_count, 0) > 0 THEN
      v_paye_preview_decisions_json := v_paye_preview_decisions_json || jsonb_build_object('case_resolutions', v_paye_case_resolutions);
    END IF;
  END IF;

  IF v_selected_preview_row_ids_supplied AND COALESCE(v_umbrella_selected_preview_row_count, 0) = 0 THEN
    v_umbrella_pay_batch_id := NULL::uuid;
    v_umbrella_overpayment_sync_only := false;
    v_umbrella_overpayment_sync := '{}'::jsonb;
    v_umbrella_status := 'NOTHING_RELEVANT';
  ELSE
    BEGIN
      v_umbrella_res := public.pay_create_draft_batch(
        p_pay_date => p_pay_date,
        p_week_ending_cutoff => p_week_ending_cutoff,
        p_pay_channel_scope => 'UMBRELLA',
        p_actor_user_id => p_actor_user_id,
        p_preview_decisions_json => v_umbrella_preview_decisions_json,
        p_candidate_id => p_candidate_id,
        p_client_id => p_client_id,
        p_force_include_timesheet_ids => p_force_include_timesheet_ids,
        p_override_reason => p_override_reason,
        p_override_mode => p_override_mode,
        p_operation_id => NULL::uuid,
        p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
      );

      IF NULLIF(BTRIM(COALESCE(v_umbrella_res->>'pay_batch_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        v_umbrella_pay_batch_id := (v_umbrella_res->>'pay_batch_id')::uuid;
      END IF;

      v_umbrella_overpayment_sync_only := COALESCE(NULLIF(v_umbrella_res->>'overpayment_sync_only', '')::boolean, false);
      v_umbrella_overpayment_sync := COALESCE(v_umbrella_res->'overpayment_sync', '{}'::jsonb);

      IF v_umbrella_pay_batch_id IS NOT NULL THEN
        v_umbrella_status := 'BATCH_CREATED';
      ELSIF v_umbrella_overpayment_sync_only THEN
        v_umbrella_status := 'DEBT_SYNCED_NO_BATCH';
      ELSE
        v_umbrella_status := 'NOTHING_RELEVANT';
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_err := COALESCE(SQLERRM, '');
        IF position('Nothing to pay' in v_err) = 1 THEN
          v_umbrella_pay_batch_id := NULL::uuid;
          v_umbrella_overpayment_sync_only := false;
          v_umbrella_overpayment_sync := '{}'::jsonb;
          v_umbrella_status := 'NOTHING_RELEVANT';
        ELSE
          RAISE;
        END IF;
    END;
  END IF;

  PERFORM pg_advisory_xact_lock(94201, 1);

  v_paye_guardrails := public.pay_paye_guardrails(
    p_pay_date => p_pay_date,
    p_ignore_pay_batch_id => NULL::uuid,
    p_actor_user_id => p_actor_user_id
  );

  v_paye_create_blocked := COALESCE((v_paye_guardrails->>'create_paye_blocked')::boolean, false);
  v_paye_override_required := COALESCE((v_paye_guardrails->>'override_required')::boolean, false);

  IF v_paye_create_blocked THEN
    v_paye_scope_blocked := true;
    v_paye_status := 'BLOCKED_EXISTING_PAYE_DRAFT';
    v_paye_block_reason_code := 'PAYE_DRAFT_ALREADY_EXISTS';
    v_paye_block_message := COALESCE(
      v_paye_guardrails #>> '{ui,existing_draft_block,message}',
      'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.'
    );
  ELSIF v_paye_override_required THEN
    IF NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NULL THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_REASON_REQUIRED';
      v_paye_block_message := 'A same-week PAYE override reason is required before creating another PAYE batch in the same Monday-based payroll week.';
    ELSIF COALESCE(p_override_continue, false) = false THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_CONTINUE_REQUIRED';
      v_paye_block_message := 'Explicit continuation is required before creating another PAYE batch in the same Monday-based payroll week.';
    ELSIF COALESCE(p_override_verified, false) = false THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFICATION_REQUIRED';
      v_paye_block_message := 'Valid password reauthentication and 2FA verification are required before creating another PAYE batch in the same Monday-based payroll week.';
    ELSIF p_override_verified_by_user_id IS NULL THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_REQUIRED';
      v_paye_block_message := 'The verified override user id is required for same-week PAYE override.';
    ELSIF p_override_verified_by_user_id <> p_actor_user_id THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_BY_MISMATCH';
      v_paye_block_message := 'The same-week PAYE override verification must belong to the current actor user.';
    ELSIF p_override_verified_at_utc IS NULL THEN
      v_paye_scope_blocked := true;
      v_paye_status := 'BLOCKED_SAME_WEEK_OVERRIDE_REQUIRED';
      v_paye_block_reason_code := 'SAME_WEEK_OVERRIDE_VERIFIED_AT_REQUIRED';
      v_paye_block_message := 'The verification timestamp is required for same-week PAYE override.';
    END IF;
  END IF;

  IF v_paye_scope_blocked = false THEN
    IF v_selected_preview_row_ids_supplied AND COALESCE(v_paye_selected_preview_row_count, 0) = 0 THEN
      v_paye_pay_batch_id := NULL::uuid;
      v_paye_overpayment_sync_only := false;
      v_paye_overpayment_sync := '{}'::jsonb;
      v_paye_status := 'NOTHING_RELEVANT';
    ELSE
      BEGIN
        v_paye_res := public.pay_create_draft_batch(
          p_pay_date => p_pay_date,
          p_week_ending_cutoff => p_week_ending_cutoff,
          p_pay_channel_scope => 'PAYE',
          p_actor_user_id => p_actor_user_id,
          p_preview_decisions_json => v_paye_preview_decisions_json,
          p_candidate_id => p_candidate_id,
          p_client_id => p_client_id,
          p_force_include_timesheet_ids => p_force_include_timesheet_ids,
          p_override_reason => p_override_reason,
          p_override_mode => p_override_mode,
          p_operation_id => NULL::uuid,
          p_allow_legacy_unchunked => COALESCE(p_allow_legacy_unchunked, false)
        );

        IF NULLIF(BTRIM(COALESCE(v_paye_res->>'pay_batch_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          v_paye_pay_batch_id := (v_paye_res->>'pay_batch_id')::uuid;
        END IF;

        v_paye_overpayment_sync_only := COALESCE(NULLIF(v_paye_res->>'overpayment_sync_only', '')::boolean, false);
        v_paye_overpayment_sync := COALESCE(v_paye_res->'overpayment_sync', '{}'::jsonb);

        IF v_paye_pay_batch_id IS NOT NULL THEN
          v_paye_status := 'BATCH_CREATED';
        ELSIF v_paye_overpayment_sync_only THEN
          v_paye_status := 'DEBT_SYNCED_NO_BATCH';
        ELSE
          v_paye_status := 'NOTHING_RELEVANT';
        END IF;
      EXCEPTION
        WHEN OTHERS THEN
          v_err := COALESCE(SQLERRM, '');
          IF position('Nothing to pay' in v_err) = 1 THEN
            v_paye_pay_batch_id := NULL::uuid;
            v_paye_overpayment_sync_only := false;
            v_paye_overpayment_sync := '{}'::jsonb;
            v_paye_status := 'NOTHING_RELEVANT';
          ELSE
            RAISE;
          END IF;
      END;
    END IF;
  END IF;

  v_has_any_scope_outcome :=
       v_umbrella_pay_batch_id IS NOT NULL
    OR v_paye_pay_batch_id IS NOT NULL
    OR v_umbrella_overpayment_sync_only
    OR v_paye_overpayment_sync_only
    OR v_paye_scope_blocked;

  IF v_has_any_scope_outcome = false THEN
    RAISE EXCEPTION 'Nothing to pay (no payable items for UMBRELLA or PAYE after readiness blockers)';
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'umbrella_pay_batch_id', CASE WHEN v_umbrella_pay_batch_id IS NULL THEN NULL ELSE v_umbrella_pay_batch_id::text END,
    'paye_pay_batch_id', CASE WHEN v_paye_pay_batch_id IS NULL THEN NULL ELSE v_paye_pay_batch_id::text END,
    'umbrella_status', v_umbrella_status,
    'paye_status', v_paye_status,
    'umbrella_overpayment_sync_only', v_umbrella_overpayment_sync_only,
    'paye_overpayment_sync_only', v_paye_overpayment_sync_only,
    'umbrella_overpayment_sync', CASE WHEN v_umbrella_overpayment_sync_only THEN v_umbrella_overpayment_sync ELSE NULL END,
    'paye_overpayment_sync', CASE WHEN v_paye_overpayment_sync_only THEN v_paye_overpayment_sync ELSE NULL END,
    'paye_guardrails', v_paye_guardrails,
    'blocked_case_states', v_blocked_case_states,
    'blocked_case_count', COALESCE(jsonb_array_length(v_blocked_case_states), 0),
    'safe_case_states', v_safe_case_states,
    'safe_case_count', COALESCE(jsonb_array_length(v_safe_case_states), 0),
    'case_resolution_states', v_case_resolution_states,
    'case_resolution_state_count', COALESCE(jsonb_array_length(v_case_resolution_states), 0),
    'scope_results', jsonb_build_object(
      'UMBRELLA', jsonb_build_object(
        'status', v_umbrella_status,
        'created', (v_umbrella_pay_batch_id IS NOT NULL),
        'blocked', false,
        'block_reason_code', NULL,
        'block_message', NULL,
        'pay_batch_id', CASE WHEN v_umbrella_pay_batch_id IS NULL THEN NULL ELSE v_umbrella_pay_batch_id::text END,
        'overpayment_sync_only', v_umbrella_overpayment_sync_only,
        'overpayment_sync', CASE WHEN v_umbrella_overpayment_sync_only THEN v_umbrella_overpayment_sync ELSE NULL END,
        'guardrails', NULL,
        'blocked_case_states', v_blocked_case_states,
        'blocked_case_count', COALESCE(jsonb_array_length(v_blocked_case_states), 0),
        'safe_case_states', v_safe_case_states,
        'safe_case_count', COALESCE(jsonb_array_length(v_safe_case_states), 0)
      ),
      'PAYE', jsonb_build_object(
        'status', v_paye_status,
        'created', (v_paye_pay_batch_id IS NOT NULL),
        'blocked', v_paye_scope_blocked,
        'block_reason_code', v_paye_block_reason_code,
        'block_message', v_paye_block_message,
        'pay_batch_id', CASE WHEN v_paye_pay_batch_id IS NULL THEN NULL ELSE v_paye_pay_batch_id::text END,
        'overpayment_sync_only', v_paye_overpayment_sync_only,
        'overpayment_sync', CASE WHEN v_paye_overpayment_sync_only THEN v_paye_overpayment_sync ELSE NULL END,
        'guardrails', v_paye_guardrails,
        'override_required', v_paye_override_required,
        'override_reason_present', (NULLIF(BTRIM(COALESCE(p_override_reason, '')), '') IS NOT NULL),
        'override_continue', COALESCE(p_override_continue, false),
        'override_verified', COALESCE(p_override_verified, false),
        'override_verified_by_user_id', CASE WHEN p_override_verified_by_user_id IS NULL THEN NULL ELSE p_override_verified_by_user_id::text END,
        'override_verified_at_utc', p_override_verified_at_utc,
        'blocked_case_states', v_blocked_case_states,
        'blocked_case_count', COALESCE(jsonb_array_length(v_blocked_case_states), 0),
        'safe_case_states', v_safe_case_states,
        'safe_case_count', COALESCE(jsonb_array_length(v_safe_case_states), 0)
      )
    )
  );
END;
$$;



CREATE OR REPLACE FUNCTION public.bank_name_check_record_result(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_bank_details_hash text,
  p_status text,
  p_result_json jsonb,
  p_checked_at_utc timestamptz,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_provided_hash text := btrim(coalesce(p_bank_details_hash, ''));

  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_hash_is_valid boolean := false;
  v_now timestamptz := now();

  v_inserted boolean := false;
  v_action text := null;
  v_row_json jsonb;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;
  if v_status not in ('UNVERIFIED', 'PASS', 'NEAR_MATCH', 'FAIL', 'UNAVAILABLE') then
    raise exception '%', jsonb_build_object('error', 'INVALID_STATUS')::text;
  end if;
  if v_provided_hash = '' then
    raise exception '%', jsonb_build_object('error', 'BANK_DETAILS_HASH_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  v_hash_is_valid := (v_current_hash is not null and v_current_hash = v_provided_hash);

  if not v_hash_is_valid and v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_provided_hash
    )
    into v_hash_is_valid;
  end if;

  if not v_hash_is_valid then
    return jsonb_build_object(
      'ok', true,
      'action', 'ignored_stale_hash',
      'ignored', true,
      'reason', 'STALE_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'current_bank_details_hash', v_current_hash,
      'provided_bank_details_hash', v_provided_hash
    );
  end if;

  with upserted as (
    insert into public.bank_name_checks (
      rail_provider,
      rail_env,
      entity_kind,
      entity_id,
      bank_details_hash,
      status,
      checked_at_utc,
      result_json,
      created_at_utc,
      updated_at_utc,
      override_reason,
      override_by_user_id,
      override_at_utc,
      override_hash
    )
    values (
      v_provider,
      v_env,
      v_kind,
      p_entity_id,
      v_provided_hash,
      v_status,
      coalesce(p_checked_at_utc, v_now),
      p_result_json,
      v_now,
      v_now,
      null::text,
      null::uuid,
      null::timestamptz,
      null::text
    )
    on conflict (rail_provider, rail_env, entity_kind, entity_id, bank_details_hash)
    do update set
      status = excluded.status,
      checked_at_utc = excluded.checked_at_utc,
      result_json = excluded.result_json,
      updated_at_utc = v_now,
      override_reason = case
        when excluded.status = 'PASS' then null::text
        else public.bank_name_checks.override_reason
      end,
      override_by_user_id = case
        when excluded.status = 'PASS' then null::uuid
        else public.bank_name_checks.override_by_user_id
      end,
      override_at_utc = case
        when excluded.status = 'PASS' then null::timestamptz
        else public.bank_name_checks.override_at_utc
      end,
      override_hash = case
        when excluded.status = 'PASS' then null::text
        else public.bank_name_checks.override_hash
      end
    returning
      public.bank_name_checks.*,
      (xmax = 0) as inserted_flag
  )
  select
    u.inserted_flag,
    jsonb_build_object(
      'id', u.id::text,
      'rail_provider', u.rail_provider,
      'rail_env', u.rail_env,
      'entity_kind', u.entity_kind,
      'entity_id', u.entity_id::text,
      'bank_details_hash', u.bank_details_hash,
      'status', u.status,
      'checked_at_utc', u.checked_at_utc,
      'result_json', u.result_json,
      'override_reason', u.override_reason,
      'override_by_user_id', case when u.override_by_user_id is null then null else u.override_by_user_id::text end,
      'override_at_utc', u.override_at_utc,
      'override_hash', u.override_hash,
      'created_at_utc', u.created_at_utc,
      'updated_at_utc', u.updated_at_utc
    )
  into
    v_inserted,
    v_row_json
  from upserted u
  limit 1;

  v_action := case when v_inserted then 'inserted' else 'updated' end;

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'ignored', false,
    'row', v_row_json
  );
end;
$function$;



DROP FUNCTION IF EXISTS public.bank_name_check_set_override(text, text, text, uuid, text, uuid);

CREATE OR REPLACE FUNCTION public.bank_name_check_set_override(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_reason text,
  p_actor_user_id uuid,
  p_bank_details_hash text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_requested_hash text := nullif(btrim(coalesce(p_bank_details_hash, '')), '');
  v_now timestamptz := now();

  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_target_hash text := null;
  v_target_is_valid_oneoff boolean := false;

  v_before public.bank_name_checks%rowtype;
  v_row public.bank_name_checks%rowtype;

  v_before_json jsonb := null;
  v_after_json jsonb := null;

  v_inserted boolean := false;
  v_action text := null;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;
  if v_reason is null then
    raise exception '%', jsonb_build_object('error', 'REASON_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  if v_requested_hash is null then
    v_target_hash := v_current_hash;
  elsif v_current_hash is not null and v_current_hash = v_requested_hash then
    v_target_hash := v_current_hash;
  elsif v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_requested_hash
    )
    into v_target_is_valid_oneoff;

    if v_target_is_valid_oneoff then
      v_target_hash := v_requested_hash;
    end if;
  end if;

  if v_target_hash is null then
    if v_requested_hash is null then
      raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'INVALID_TARGET_BANK_DETAILS_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'bank_details_hash', v_requested_hash
    )::text;
  end if;

  select bnc.*
  into v_before
  from public.bank_name_checks bnc
  where bnc.rail_provider = v_provider
    and bnc.rail_env = v_env
    and bnc.entity_kind = v_kind
    and bnc.entity_id = p_entity_id
    and bnc.bank_details_hash = v_target_hash
  limit 1;

  if v_before.id is not null then
    v_before_json := jsonb_build_object(
      'id', v_before.id::text,
      'rail_provider', v_before.rail_provider,
      'rail_env', v_before.rail_env,
      'entity_kind', v_before.entity_kind,
      'entity_id', v_before.entity_id::text,
      'bank_details_hash', v_before.bank_details_hash,
      'status', v_before.status,
      'checked_at_utc', v_before.checked_at_utc,
      'result_json', v_before.result_json,
      'override_reason', v_before.override_reason,
      'override_by_user_id', case when v_before.override_by_user_id is null then null else v_before.override_by_user_id::text end,
      'override_at_utc', v_before.override_at_utc,
      'override_hash', v_before.override_hash,
      'created_at_utc', v_before.created_at_utc,
      'updated_at_utc', v_before.updated_at_utc
    );
  end if;

  with upserted as (
    insert into public.bank_name_checks (
      rail_provider,
      rail_env,
      entity_kind,
      entity_id,
      bank_details_hash,
      status,
      checked_at_utc,
      result_json,
      override_reason,
      override_by_user_id,
      override_at_utc,
      override_hash,
      created_at_utc,
      updated_at_utc
    )
    values (
      v_provider,
      v_env,
      v_kind,
      p_entity_id,
      v_target_hash,
      'UNVERIFIED',
      null,
      null,
      v_reason,
      p_actor_user_id,
      v_now,
      v_target_hash,
      v_now,
      v_now
    )
    on conflict (rail_provider, rail_env, entity_kind, entity_id, bank_details_hash)
    do update set
      override_reason = excluded.override_reason,
      override_by_user_id = excluded.override_by_user_id,
      override_at_utc = excluded.override_at_utc,
      override_hash = excluded.override_hash,
      updated_at_utc = v_now
    returning public.bank_name_checks.*
  )
  select u.*
  into v_row
  from upserted u
  limit 1;

  v_inserted := (v_row.created_at_utc is not null and v_row.updated_at_utc is not null and v_row.created_at_utc = v_row.updated_at_utc);
  v_action := case when v_inserted then 'inserted' else 'updated' end;

  v_after_json := jsonb_build_object(
    'id', v_row.id::text,
    'rail_provider', v_row.rail_provider,
    'rail_env', v_row.rail_env,
    'entity_kind', v_row.entity_kind,
    'entity_id', v_row.entity_id::text,
    'bank_details_hash', v_row.bank_details_hash,
    'status', v_row.status,
    'checked_at_utc', v_row.checked_at_utc,
    'result_json', v_row.result_json,
    'override_reason', v_row.override_reason,
    'override_by_user_id', case when v_row.override_by_user_id is null then null else v_row.override_by_user_id::text end,
    'override_at_utc', v_row.override_at_utc,
    'override_hash', v_row.override_hash,
    'created_at_utc', v_row.created_at_utc,
    'updated_at_utc', v_row.updated_at_utc
  );

  perform public._audit_insert(
    'bank_name_checks',
    v_row.id::text,
    'BANK_NAME_CHECK_OVERRIDE_SET',
    v_before_json,
    v_after_json,
    v_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'row', v_after_json
  );
end;
$function$;

DROP FUNCTION IF EXISTS public.bank_name_check_clear_override(text, text, text, uuid, uuid);

CREATE OR REPLACE FUNCTION public.bank_name_check_clear_override(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_actor_user_id uuid,
  p_bank_details_hash text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider, '')));
  v_env text := upper(btrim(coalesce(p_env, '')));
  v_kind text := upper(btrim(coalesce(p_entity_kind, '')));
  v_requested_hash text := nullif(btrim(coalesce(p_bank_details_hash, '')), '');

  v_now timestamptz := now();
  v_entity_exists boolean := false;
  v_current_hash text := null;
  v_target_hash text := null;
  v_target_is_valid_oneoff boolean := false;

  v_updated integer := 0;
  v_row public.bank_name_checks%rowtype;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error', 'PROVIDER_REQUIRED')::text;
  end if;
  if v_env = '' then
    raise exception '%', jsonb_build_object('error', 'ENV_REQUIRED')::text;
  end if;
  if v_kind not in ('CANDIDATE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object('error', 'INVALID_ENTITY_KIND', 'expected', 'CANDIDATE|UMBRELLA')::text;
  end if;
  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error', 'ENTITY_ID_REQUIRED')::text;
  end if;

  if v_kind = 'CANDIDATE' then
    perform 1
    from public.candidates c
    where c.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select c.bank_details_hash
      into v_current_hash
      from public.candidates c
      where c.id = p_entity_id
      limit 1;
    end if;
  else
    perform 1
    from public.umbrellas u
    where u.id = p_entity_id;

    v_entity_exists := found;

    if v_entity_exists then
      select u.bank_details_hash
      into v_current_hash
      from public.umbrellas u
      where u.id = p_entity_id
      limit 1;
    end if;
  end if;

  if not v_entity_exists then
    raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
  end if;

  if v_requested_hash is null then
    v_target_hash := v_current_hash;
  elsif v_current_hash is not null and v_current_hash = v_requested_hash then
    v_target_hash := v_current_hash;
  elsif v_kind = 'CANDIDATE' then
    select exists (
      select 1
      from public.v_finance_cases_register vfcr
      where vfcr.candidate_id = p_entity_id
        and vfcr.routing_kind::text = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
        and coalesce(vfcr.edit_bank_details_allowed, false) = true
        and coalesce(vfcr.oneoff_bank_details_present, false) = true
        and vfcr.oneoff_bank_details_hash = v_requested_hash
    )
    into v_target_is_valid_oneoff;

    if v_target_is_valid_oneoff then
      v_target_hash := v_requested_hash;
    end if;
  end if;

  if v_target_hash is null then
    if v_requested_hash is null then
      raise exception '%', jsonb_build_object('error', 'ENTITY_NOT_FOUND_OR_NO_HASH', 'entity_kind', v_kind)::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'INVALID_TARGET_BANK_DETAILS_HASH',
      'entity_kind', v_kind,
      'entity_id', p_entity_id::text,
      'bank_details_hash', v_requested_hash
    )::text;
  end if;

  update public.bank_name_checks bnc
  set
    override_reason = null,
    override_by_user_id = null,
    override_at_utc = null,
    override_hash = null,
    updated_at_utc = v_now
  where bnc.rail_provider = v_provider
    and bnc.rail_env = v_env
    and bnc.entity_kind = v_kind
    and bnc.entity_id = p_entity_id
    and bnc.bank_details_hash = v_target_hash;

  get diagnostics v_updated = row_count;

  if v_updated = 0 then
    return jsonb_build_object(
      'ok', true,
      'did_update', false,
      'row', null
    );
  end if;

  select bnc2.*
  into v_row
  from public.bank_name_checks bnc2
  where bnc2.rail_provider = v_provider
    and bnc2.rail_env = v_env
    and bnc2.entity_kind = v_kind
    and bnc2.entity_id = p_entity_id
    and bnc2.bank_details_hash = v_target_hash
  limit 1;

  return jsonb_build_object(
    'ok', true,
    'did_update', true,
    'row', jsonb_build_object(
      'rail_provider', v_row.rail_provider,
      'rail_env', v_row.rail_env,
      'entity_kind', v_row.entity_kind,
      'entity_id', v_row.entity_id::text,
      'bank_details_hash', v_row.bank_details_hash,
      'status', v_row.status,
      'checked_at_utc', v_row.checked_at_utc,
      'result_json', v_row.result_json,
      'override_reason', v_row.override_reason,
      'override_by_user_id', case when v_row.override_by_user_id is null then null else v_row.override_by_user_id::text end,
      'override_at_utc', v_row.override_at_utc,
      'override_hash', v_row.override_hash,
      'created_at_utc', v_row.created_at_utc,
      'updated_at_utc', v_row.updated_at_utc
    )
  );
end;
$function$;






CREATE OR REPLACE FUNCTION public.bank_payee_map_upsert(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_bank_details_hash text,
  p_payee_id text,
  p_payee_account_id text,
  p_meta_json jsonb,
  p_actor_user_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text := upper(btrim(coalesce(p_provider,'')));
  v_env text := upper(btrim(coalesce(p_env,'')));
  v_kind text := upper(btrim(coalesce(p_entity_kind,'')));

  v_hash text := nullif(btrim(coalesce(p_bank_details_hash,'')), '');
  v_payee_id text := nullif(btrim(coalesce(p_payee_id,'')), '');
  v_payee_account_id text := nullif(btrim(coalesce(p_payee_account_id,'')), '');

  v_now timestamptz := now();

  v_inserted boolean := false;
  v_action text := null;

  v_row_json jsonb;
  v_out_payee_id text;
  v_out_payee_account_id text;
begin
  if v_provider = '' then
    raise exception '%', jsonb_build_object('error','PROVIDER_REQUIRED')::text;
  end if;

  if v_env = '' then
    raise exception '%', jsonb_build_object('error','ENV_REQUIRED')::text;
  end if;

  if v_kind not in ('CANDIDATE','UMBRELLA') then
    raise exception '%', jsonb_build_object('error','INVALID_ENTITY_KIND','expected','CANDIDATE|UMBRELLA')::text;
  end if;

  if p_entity_id is null then
    raise exception '%', jsonb_build_object('error','ENTITY_ID_REQUIRED')::text;
  end if;

  if v_hash is null then
    raise exception '%', jsonb_build_object('error','BANK_DETAILS_HASH_REQUIRED')::text;
  end if;

  if v_payee_id is null then
    raise exception '%', jsonb_build_object('error','PAYEE_ID_REQUIRED')::text;
  end if;

  -- ✅ Approach A: single statement consumes the CTE and captures inserted_flag + output fields.
  with upserted as (
    insert into public.bank_payee_map (
      rail_provider,
      rail_env,
      entity_kind,
      entity_id,
      bank_details_hash,
      payee_id,
      payee_account_id,
      meta_json,
      created_at_utc,
      updated_at_utc
    )
    values (
      v_provider,
      v_env,
      v_kind,
      p_entity_id,
      v_hash,
      v_payee_id,
      v_payee_account_id,
      p_meta_json,
      v_now,
      v_now
    )
    on conflict (rail_provider, rail_env, entity_kind, entity_id, bank_details_hash)
    do update set
      payee_id = excluded.payee_id,
      payee_account_id = excluded.payee_account_id,
      meta_json = excluded.meta_json,
      updated_at_utc = v_now
    returning
      public.bank_payee_map.*,
      (xmax = 0) as inserted_flag
  )
  select
    u.inserted_flag,
    u.payee_id,
    u.payee_account_id,
    jsonb_build_object(
      'rail_provider', u.rail_provider,
      'rail_env', u.rail_env,
      'entity_kind', u.entity_kind,
      'entity_id', u.entity_id::text,
      'bank_details_hash', u.bank_details_hash,
      'payee_id', u.payee_id,
      'payee_account_id', u.payee_account_id,
      'meta_json', u.meta_json,
      'created_at_utc', u.created_at_utc,
      'updated_at_utc', u.updated_at_utc
    )
  into
    v_inserted,
    v_out_payee_id,
    v_out_payee_account_id,
    v_row_json
  from upserted u
  limit 1;

  v_action := case when v_inserted then 'inserted' else 'updated' end;

  return jsonb_build_object(
    'ok', true,
    'action', v_action,
    'payee_id', v_out_payee_id,
    'payee_account_id', v_out_payee_account_id,
    'row', v_row_json
  );
end;
$function$;



DROP FUNCTION IF EXISTS public.pay_batch_schedule(uuid, text, timestamptz, text, jsonb, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_schedule(uuid, text, timestamptz, text, jsonb, uuid, uuid, text);


create or replace function public.pay_batch_schedule(
  p_pay_batch_id uuid,
  p_schedule_kind text,
  p_scheduled_at_utc timestamptz,
  p_funding_account_ref text,
  p_warning_hours_json jsonb,
  p_actor_user_id uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_freshness_result_hash text DEFAULT NULL::text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_kind text := upper(btrim(coalesce(p_schedule_kind,'')));
  v_batch record;
  v_cfg record;

  v_provider text := null;

  v_sched_at timestamptz;
  v_warn jsonb;
  v_authoritative_payment_date date;
  v_commit_ts timestamptz := now();

  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_funding text := nullif(btrim(coalesce(p_funding_account_ref,'')), '');

  v_missing_bank int := 0;
  v_blocked_name int := 0;
  v_missing_map int := 0;
  v_pending_transfers int := 0;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_batch_kind_fixed text := null;
  v_bad_loans_payee_ct int := 0;

  v_reservations_committed_count int := 0;
  v_reservations_committed_amount numeric := 0;

  v_worker_communications jsonb := '{}'::jsonb;
  v_comm_result jsonb := '{}'::jsonb;
  v_comm_error text := null;
  v_comm_trigger_status text := null;
  v_comm_message_kind text := null;

  v_payout_notice_result jsonb := '{}'::jsonb;
  v_payout_notice_trigger_status text := null;
  v_payout_notice_error text := null;
  v_payout_notice_dispatch_required boolean := false;
  v_payout_notice_targeted_count int := 0;

  v_remittance_result jsonb := '{}'::jsonb;
  v_remittance_trigger_status text := null;
  v_remittance_error text := null;
  v_remittance_dispatch_required boolean := false;
  v_remittance_targeted_count int := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;

  v_execution_intent_json jsonb := '{}'::jsonb;
  v_execution_mode text := 'STANDARD_BANK';
  v_suppress_remittances boolean := false;
  v_has_external_submission_evidence boolean := false;
  v_submission_evidence_json jsonb := '{}'::jsonb;
  v_intent_payment_date date := null;
  v_batch_status_upper text := null;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_operation_mode boolean := false;
  v_expected_freshness_hash text := null;
  v_expected_freshness_scope_hash text := null;
  v_stored_freshness_status text := null;
  v_stored_freshness_hash text := null;
  v_stored_freshness_scope_hash text := null;
  v_timing_setting_if_known text := null;
begin
  if p_pay_batch_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_schedule: pay_batch_id is required'
    )::text;
  end if;
  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_schedule: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_kind not in ('IMMEDIATE','SCHEDULED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'INVALID_SCHEDULE_KIND',
      'message', 'pay_batch_schedule: invalid schedule_kind (IMMEDIATE|SCHEDULED)',
      'schedule_kind', v_kind,
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.schedule_kind,
    pb.scheduled_at_utc,
    pb.scheduled_by_user_id,
    pb.funding_account_ref,
    pb.funds_warning_hours_json,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_schedule: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if v_execution_commit_state <> 'NOT_SUBMITTED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_batch_schedule: batch has already crossed the execution submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_batch_kind_fixed := upper(btrim(coalesce(v_batch.batch_kind_fixed,'')));
  v_batch_status_upper := upper(btrim(coalesce(v_batch.status, '')));

  if v_batch_status_upper in ('COMMITTED','PAID','SETTLED','CANCELLED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'BATCH_NOT_SCHEDULABLE',
      'message', 'pay_batch_schedule: batch status cannot be scheduled or authorised',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    select pbar_intent.execution_intent_json
    into v_execution_intent_json
    from public.pay_batch_auth_requests pbar_intent
    where pbar_intent.pay_batch_id = p_pay_batch_id
      and pbar_intent.state in ('AWAITING','AUTHORISED')
      and pbar_intent.execution_intent_json is not null
    order by pbar_intent.created_at_utc desc, pbar_intent.id desc
    limit 1;

    if v_execution_intent_json is null or jsonb_typeof(v_execution_intent_json) <> 'object' then
      v_execution_intent_json := '{}'::jsonb;
    end if;
  end if;

  v_execution_mode := upper(btrim(coalesce(v_execution_intent_json->>'execution_mode', 'STANDARD_BANK')));
  if v_execution_mode = '' then
    v_execution_mode := 'STANDARD_BANK';
  end if;
  if v_execution_mode not in ('STANDARD_BANK','CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'INVALID_EXECUTION_MODE',
      'message', 'pay_batch_schedule: invalid frozen execution_mode',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_mode', v_execution_mode
    )::text;
  end if;

  v_suppress_remittances := lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) in ('true','1','yes','y','on');

  if nullif(btrim(coalesce(v_execution_intent_json->>'payment_date', '')), '') ~ '^\d{4}-\d{2}-\d{2}$' then
    v_intent_payment_date := (v_execution_intent_json->>'payment_date')::date;
  else
    v_intent_payment_date := null;
  end if;

  v_operation_mode := p_operation_id IS NOT NULL OR nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL;

  SELECT COALESCE(NULLIF(btrim(public.settings_defaults.payment_remittance_send_timing), ''), 'ON_EXECUTION')
  INTO v_timing_setting_if_known
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_timing_setting_if_known := upper(coalesce(nullif(btrim(v_timing_setting_if_known), ''), 'ON_EXECUTION'));

  IF v_timing_setting_if_known NOT IN ('ON_EXECUTION','ON_PAYMENT_CONFIRMED') THEN
    v_timing_setting_if_known := 'ON_EXECUTION';
  END IF;

  v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_stored_freshness_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');

  if p_operation_id is not null then
    select operation_row.*
    into v_operation_row
    from public.banking_pay_operations as operation_row
    where operation_row.id = p_operation_id
    for update;

    if not found then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_batch_schedule: operation was not found',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    end if;

    if v_operation_row.pay_batch_id is not null and v_operation_row.pay_batch_id <> p_pay_batch_id then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_batch_schedule: operation belongs to another batch',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_operation_row.pay_batch_id::text
      )::text;
    end if;

    if v_operation_row.actor_user_id is not null and v_operation_row.actor_user_id <> p_actor_user_id then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_ACTOR_MISMATCH',
        'message', 'pay_batch_schedule: operation belongs to another actor',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    end if;

    v_expected_freshness_hash := coalesce(
      nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_result_hash}', '')), '')
    );
    v_expected_freshness_scope_hash := coalesce(
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_scope_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_scope_hash}', '')), '')
    );
  else
    v_expected_freshness_hash := nullif(btrim(coalesce(p_freshness_result_hash, '')), '');
  end if;

  if v_operation_mode then
    if v_stored_freshness_status <> 'PASSED' then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_NOT_PASSED',
        'message', 'pay_batch_schedule: completed passing chunked freshness is required before scheduling',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;

    if p_operation_id is not null and v_expected_freshness_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'pay_batch_schedule: operation mode requires the operation to carry the completed freshness result hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_stored_freshness_status,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;

    if v_expected_freshness_hash is not null and v_stored_freshness_hash is distinct from v_expected_freshness_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'pay_batch_schedule: operation freshness hash does not match stored batch freshness hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_stored_freshness_hash
      )::text;
    end if;

    if v_expected_freshness_scope_hash is not null and v_stored_freshness_scope_hash is distinct from v_expected_freshness_scope_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'pay_batch_schedule: operation freshness scope hash does not match stored batch freshness scope hash',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_stored_freshness_scope_hash
      )::text;
    end if;
  else
    v_fresh := public.pay_batch_validate_freshness(
      p_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id,
      p_allow_large_full_scan => false
    );
    v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
    v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

    if v_is_stale = true then
      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
        into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      begin
        perform public._imp_debug_audit(
          p_actor_user_id,
          'PAY_BATCH_SCHEDULE:STALE',
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'stale_reasons', v_stale_reasons,
            'diff_sample', v_diff_sample
          ),
          'pay_batches',
          p_pay_batch_id::text
        );
      exception when others then
        null;
      end;

      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
        'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_batch_schedule: chunked freshness validation is required before proceeding' else 'pay_batch_schedule: batch is stale; regenerate draft before proceeding' end,
        'pay_batch_id', p_pay_batch_id::text,
        'stale_reasons', v_stale_reasons,
        'diff', v_diff_sample
      )::text;
    end if;
  end if;

  v_provider := upper(btrim(coalesce(v_batch.rail_provider_snapshot,'')));
  if v_provider = 'REV' then
    v_provider := 'REVOLUT';
  end if;
  if v_provider = '' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'RAIL_PROVIDER_MISSING_ON_BATCH',
      'message', 'pay_batch_schedule: rail_provider_snapshot missing on batch; blank provider is not treated as CSV',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_provider not in ('REVOLUT','CSV') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'UNKNOWN_RAIL_PROVIDER',
      'message', 'pay_batch_schedule: unsupported rail_provider_snapshot',
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select
    sd.funds_warning_hours_json,
    sd.rail_supports_name_check,
    sd.rail_supports_scheduling,
    sd.rail_default_funding_account_ref
  into v_cfg
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cfg.funds_warning_hours_json is null
     and v_cfg.rail_supports_name_check is null
     and v_cfg.rail_supports_scheduling is null
     and v_cfg.rail_default_funding_account_ref is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_batch_schedule: settings_defaults missing (id=1)',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  if v_execution_mode <> 'STANDARD_BANK' then
    v_warn := coalesce(p_warning_hours_json, coalesce(v_cfg.funds_warning_hours_json, '[]'::jsonb));
    if v_warn is not null and jsonb_typeof(v_warn) <> 'array' then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'WARNING_HOURS_JSON_INVALID',
        'message', 'pay_batch_schedule: warning_hours_json must be a JSON array',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode
      )::text;
    end if;

    if v_kind = 'IMMEDIATE' then
      v_sched_at := now();
    else
      if p_scheduled_at_utc is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_SCHEDULE',
          'code', 'SCHEDULED_AT_REQUIRED',
          'message', 'pay_batch_schedule: scheduled_at_utc is required when schedule_kind=SCHEDULED',
          'pay_batch_id', p_pay_batch_id::text,
          'schedule_kind', v_kind,
          'execution_mode', v_execution_mode
        )::text;
      end if;
      v_sched_at := p_scheduled_at_utc;
    end if;

    v_authoritative_payment_date := coalesce(
      v_intent_payment_date,
      (v_sched_at at time zone 'Europe/London')::date,
      v_batch.authoritative_payment_date,
      v_batch.pay_date
    );

    select count(*)::int
    into v_pending_transfers
    from public.pay_bank_transfers pbt_non_native_pending
    where pbt_non_native_pending.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt_non_native_pending.status,'')) = 'PENDING';

    if v_pending_transfers = 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'NO_PENDING_TRANSFERS',
        'message', 'pay_batch_schedule: no PENDING transfers exist for this batch (execute-bank required first)',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode,
        'ui_hint', 'RERUN_PREVIEW_OR_EXECUTE_BANK'
      )::text;
    end if;

    if v_batch_kind_fixed = 'LOANS' then
      select count(*)::int
      into v_bad_loans_payee_ct
      from public.pay_bank_transfers pbt_non_native_loans
      where pbt_non_native_loans.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt_non_native_loans.status,'')) = 'PENDING'
        and upper(
          coalesce(
            pbt_non_native_loans.payee_entity_kind,
            case
              when upper(coalesce(pbt_non_native_loans.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA'
              else 'CANDIDATE'
            end
          )
        ) <> 'CANDIDATE';

      if v_bad_loans_payee_ct > 0 then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
          'code', 'LOANS_PAYEE_MUST_BE_CANDIDATE',
          'message', 'pay_batch_schedule: LOANS batches must pay candidates (not umbrellas)',
          'pay_batch_id', p_pay_batch_id::text,
          'bad_transfer_count', v_bad_loans_payee_ct,
          'execution_mode', v_execution_mode,
          'ui_hint', 'REGENERATE_TRANSFERS_AS_CANDIDATE_PAYEES'
        )::text;
      end if;
    end if;

    v_submission_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id);
    v_has_external_submission_evidence := coalesce((v_submission_evidence_json->>'has_external_submission_evidence')::boolean, false);

    if v_has_external_submission_evidence = true then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'EXTERNAL_SUBMISSION_EXISTS',
        'message', 'pay_batch_schedule: CSV/external settlement cannot be scheduled after native rail submission evidence exists',
        'pay_batch_id', p_pay_batch_id::text,
        'execution_mode', v_execution_mode
      )::text;
    end if;

    update public.pay_batches pb_non_native
    set
      schedule_kind = v_kind,
      scheduled_at_utc = v_sched_at,
      scheduled_by_user_id = p_actor_user_id,
      funding_account_ref = v_funding,
      funds_warning_hours_json = v_warn,
      authoritative_payment_date = v_authoritative_payment_date,
      authoritative_payment_date_source = 'EXECUTION_INTENT_PAYMENT_DATE',
      execution_intent_json = coalesce(v_execution_intent_json, '{}'::jsonb) || jsonb_build_object(
        'execution_mode', v_execution_mode,
        'payment_date', v_authoritative_payment_date::text,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'suppress_remittances', v_suppress_remittances,
        'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
        'freshness_result_hash', v_stored_freshness_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash
      ),
      execution_commit_state = coalesce(nullif(btrim(coalesce(pb_non_native.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    where pb_non_native.id = p_pay_batch_id;

    begin
      v_comm_result := public.pay_remittance_maybe_queue_for_trigger(
        p_pay_batch_id => p_pay_batch_id,
        p_trigger => 'ON_EXECUTION',
        p_scope => 'ALL',
        p_actor_user_id => p_actor_user_id,
        p_only_confirmed => false,
        p_root_operation_id => CASE WHEN v_operation_mode THEN p_operation_id ELSE NULL::uuid END,
        p_operation_mode => v_operation_mode
      );

      if coalesce((v_comm_result->>'ok')::boolean, true) = false then
        raise exception '%', coalesce(
          nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
          nullif(btrim(coalesce(v_comm_result #>> '{queue_result,error}','')), ''),
          'pay_batch_schedule: remittance/payout notice queue timing gate failed'
        );
      end if;

      v_comm_message_kind := coalesce(
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,message_kind}', '')), ''),
        case when v_batch_kind_fixed in ('LOANS','LOAN','FINANCE_PAYOUTS','PAYOUTS') then 'PAYOUT_NOTICE' else 'REMITTANCE' end
      );

      v_comm_trigger_status := coalesce(
        nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,trigger_status}', '')), ''),
        case
          when lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_DEFERRED_BY_TIMING'
          when lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on') then 'SUPPRESSED_BY_EXECUTION_INTENT'
          when lower(btrim(coalesce(v_comm_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on') then 'QUEUE_STAGE_BUILD_READY'
          else 'NO_QUEUEABLE_REMITTANCE_OR_PAYOUT_NOTICE_JOB'
        end
      );

      v_comm_error := coalesce(
        nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
        nullif(btrim(coalesce(v_comm_result #>> '{queue_result,error}','')), '')
      );

      if upper(coalesce(v_comm_message_kind, '')) = 'PAYOUT_NOTICE' then
        v_payout_notice_result := coalesce(v_comm_result->'queue_result', v_comm_result);
        v_remittance_result := jsonb_build_object(
          'ok', true,
          'trigger_status', 'NOT_APPLICABLE_FOR_FINANCE_PAYOUT_BATCH',
          'message_kind', 'REMITTANCE',
          'automatic_commit_stage', true,
          'dispatch_required', false,
          'pay_batch_id', p_pay_batch_id::text,
          'scope', 'ALL'
        );
        v_payout_notice_trigger_status := v_comm_trigger_status;
        v_payout_notice_error := v_comm_error;
        v_payout_notice_dispatch_required := lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_payout_notice_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on');
        v_remittance_trigger_status := 'NOT_APPLICABLE_FOR_FINANCE_PAYOUT_BATCH';
        v_remittance_error := null;
        v_remittance_dispatch_required := false;
        if btrim(coalesce(v_payout_notice_result->>'candidate_count_targeted', '')) ~ '^[0-9]+$' then
          v_payout_notice_targeted_count := (v_payout_notice_result->>'candidate_count_targeted')::int;
        else
          v_payout_notice_targeted_count := 0;
        end if;
        v_remittance_targeted_count := 0;
      else
        v_remittance_result := coalesce(v_comm_result->'queue_result', v_comm_result);
        v_payout_notice_result := jsonb_build_object(
          'ok', true,
          'trigger_status', 'NOT_APPLICABLE_FOR_STANDARD_PAY_BATCH',
          'message_kind', 'PAYOUT_NOTICE',
          'automatic_commit_stage', true,
          'dispatch_required', false,
          'pay_batch_id', p_pay_batch_id::text
        );
        v_remittance_trigger_status := v_comm_trigger_status;
        v_remittance_error := v_comm_error;
        v_remittance_dispatch_required := lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_remittance_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on');
        v_payout_notice_trigger_status := 'NOT_APPLICABLE_FOR_STANDARD_PAY_BATCH';
        v_payout_notice_error := null;
        v_payout_notice_dispatch_required := false;
        if btrim(coalesce(v_remittance_result->>'candidate_count_targeted', '')) ~ '^[0-9]+$' then
          v_remittance_targeted_count := (v_remittance_result->>'candidate_count_targeted')::int;
        else
          v_remittance_targeted_count := 0;
        end if;
        v_payout_notice_targeted_count := 0;
      end if;
    exception when others then
      v_comm_trigger_status := 'COMMIT_STAGE_QUEUE_TIMING_GATE_ERROR';
      v_comm_error := left(coalesce(SQLERRM, 'UNKNOWN_COMMS_ERROR'), 1000);
      v_comm_message_kind := coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE');
      v_payout_notice_result := jsonb_build_object(
        'ok', false,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', 'PAYOUT_NOTICE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id::text
      );
      v_remittance_result := jsonb_build_object(
        'ok', false,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', 'REMITTANCE',
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'pay_batch_id', p_pay_batch_id::text,
        'scope', 'ALL'
      );
      v_payout_notice_dispatch_required := false;
      v_remittance_dispatch_required := false;
      v_payout_notice_targeted_count := 0;
      v_remittance_targeted_count := 0;
      v_comm_result := jsonb_build_object(
        'ok', false,
        'trigger', 'ON_EXECUTION',
        'configured_timing', v_timing_setting_if_known,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'message_kind', v_comm_message_kind,
        'automatic_commit_stage', true,
        'dispatch_required', false,
        'operation_id', NULL::text,
        'deferred', false,
        'suppressed', false,
        'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
        'remittance', coalesce(v_remittance_result, '{}'::jsonb),
        'queue_result', jsonb_build_object(
          'ok', false,
          'trigger', 'ON_EXECUTION',
          'configured_timing', v_timing_setting_if_known,
          'trigger_status', v_comm_trigger_status,
          'error', v_comm_error,
          'operation_id', NULL::text,
          'deferred', false,
          'suppressed', false
        ),
        'execution_mode', v_execution_mode
      );
    end;

    v_comm_result := coalesce(v_comm_result, '{}'::jsonb) || jsonb_build_object(
      'trigger', coalesce(nullif(btrim(coalesce(v_comm_result->>'trigger', '')), ''), 'ON_EXECUTION'),
      'configured_timing', coalesce(nullif(btrim(coalesce(v_comm_result->>'configured_timing', '')), ''), nullif(btrim(coalesce(v_comm_result#>>'{queue_result,configured_timing}', '')), ''), v_timing_setting_if_known),
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb)
    );

    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', true,
      'message_kind', coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'dispatch_required', (v_payout_notice_dispatch_required = true or v_remittance_dispatch_required = true),
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
      'result', coalesce(v_comm_result, '{}'::jsonb),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances
    );

    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:NON_NATIVE_MODE_OK',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'execution_mode', v_execution_mode,
          'schedule_kind', v_kind,
          'scheduled_at_utc', v_sched_at::text,
          'authoritative_payment_date', v_authoritative_payment_date::text,
          'pending_transfers', v_pending_transfers,
          'worker_communications', v_worker_communications
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    return jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'status', (select pb_non_native_ret.status from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'schedule_kind', v_kind,
      'scheduled_at_utc', v_sched_at::text,
      'authoritative_payment_date', v_authoritative_payment_date::text,
      'authoritative_payment_date_source', 'EXECUTION_INTENT_PAYMENT_DATE',
      'funding_account_ref', v_funding,
      'funds_warning_hours_json', v_warn,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot,
      'rail_env_snapshot', v_batch.rail_env_snapshot,
      'execution_mode', v_execution_mode,
      'execution_intent_json', (select pb_non_native_ret.execution_intent_json from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_commit_state', (select pb_non_native_ret.execution_commit_state from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_commit_ref', (select pb_non_native_ret.execution_commit_ref from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb_non_native_ret.execution_committed_at_utc is null then null else pb_non_native_ret.execution_committed_at_utc::text end from public.pay_batches pb_non_native_ret where pb_non_native_ret.id = p_pay_batch_id),
      'finance_reservations', jsonb_build_object(
        'committed_count', 0,
        'committed_amount', 0
      ),
      'remittance_trigger', 'ON_EXECUTION',
      'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
      'remittance_deferred', lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on'),
      'remittance_suppressed', lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on'),
      'remittance_operation_queued', lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on'),
      'remittance_child_operation_id', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'operation_id', '')), ''),
        nullif(btrim(coalesce(v_comm_result#>>'{queue_result,operation_id}', '')), '')
      ),
      'remittance_trigger_status', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
        nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}', '')), ''),
        v_comm_trigger_status
      ),
      'remittance_message_kind', v_comm_message_kind,
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb)
    );
  end if;

  if v_provider = 'CSV' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SCHEDULING_NOT_SUPPORTED_FOR_MANUAL_RAIL',
      'message', format('pay_batch_schedule: scheduling is not supported for manual rail_provider_snapshot=%s', v_batch.rail_provider_snapshot),
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  if coalesce(v_cfg.rail_supports_scheduling,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'SCHEDULING_DISABLED_IN_SETTINGS',
      'message', 'pay_batch_schedule: scheduling is not enabled in settings_defaults (rail_supports_scheduling=false)',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_need_name_check := (coalesce(v_cfg.rail_supports_name_check,false) = true);
  v_requires_payee_map := true;

  v_warn := coalesce(p_warning_hours_json, v_cfg.funds_warning_hours_json);
  if v_warn is not null and jsonb_typeof(v_warn) <> 'array' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'WARNING_HOURS_JSON_INVALID',
      'message', 'pay_batch_schedule: warning_hours_json must be a JSON array',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  if v_kind = 'IMMEDIATE' then
    v_sched_at := now();
  else
    if p_scheduled_at_utc is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE',
        'code', 'SCHEDULED_AT_REQUIRED',
        'message', 'pay_batch_schedule: scheduled_at_utc is required when schedule_kind=SCHEDULED',
        'pay_batch_id', p_pay_batch_id::text,
        'schedule_kind', v_kind
      )::text;
    end if;
    v_sched_at := p_scheduled_at_utc;
  end if;

  v_authoritative_payment_date := (v_sched_at at time zone 'Europe/London')::date;

  if v_funding is null then
    v_funding := nullif(btrim(coalesce(v_cfg.rail_default_funding_account_ref,'')), '');
  end if;
  if v_funding is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'FUNDING_ACCOUNT_REQUIRED',
      'message', format('pay_batch_schedule: funding_account_ref is required for this rail (provider=%s)', v_batch.rail_provider_snapshot),
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select count(*)::int
  into v_pending_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) = 'PENDING';

  if v_pending_transfers = 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE',
      'code', 'NO_PENDING_TRANSFERS',
      'message', 'pay_batch_schedule: no PENDING transfers exist for this batch (execute-bank required first)',
      'pay_batch_id', p_pay_batch_id::text,
      'ui_hint', 'RERUN_PREVIEW_OR_EXECUTE_BANK'
    )::text;
  end if;

  if v_batch_kind_fixed = 'LOANS' then
    select count(*)::int
    into v_bad_loans_payee_ct
    from public.pay_bank_transfers pbt2
    where pbt2.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt2.status,'')) = 'PENDING'
      and upper(
        coalesce(
          pbt2.payee_entity_kind,
          case
            when upper(coalesce(pbt2.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA'
            else 'CANDIDATE'
          end
        )
      ) <> 'CANDIDATE';

    if v_bad_loans_payee_ct > 0 then
      begin
        perform public._imp_debug_audit(
          p_actor_user_id,
          'PAY_BATCH_SCHEDULE:BLOCKED_LOANS_PAYEE_KIND',
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'bad_transfer_count', v_bad_loans_payee_ct
          ),
          'pay_batches',
          p_pay_batch_id::text
        );
      exception when others then
        null;
      end;

      raise exception '%', jsonb_build_object(
        'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
        'code', 'LOANS_PAYEE_MUST_BE_CANDIDATE',
        'message', 'pay_batch_schedule: LOANS batches must pay candidates (not umbrellas)',
        'pay_batch_id', p_pay_batch_id::text,
        'bad_transfer_count', v_bad_loans_payee_ct,
        'ui_hint', 'REGENERATE_TRANSFERS_AS_CANDIDATE_PAYEES'
      )::text;
    end if;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(case when t.bank_hash is null or btrim(t.bank_hash) = '' then 1 else 0 end)::int
  into v_missing_bank
  from t;

  if v_missing_bank > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_BANK_DETAILS',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_missing_bank
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_BANK_DETAILS',
      'message', format('pay_batch_schedule: BLOCKED_BANK_DETAILS for %s payee(s)', v_missing_bank::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_missing_bank,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(
      case
        when v_need_name_check = true then
          case
            when coalesce(bnc.status,'UNVERIFIED') = 'PASS' then 0
            when (bnc.override_reason is not null and bnc.override_hash = t.bank_hash) then 0
            else 1
          end
        else 0
      end
    )::int
  into v_blocked_name
  from t
  left join public.bank_name_checks bnc
    on bnc.rail_provider = v_batch.rail_provider_snapshot
   and bnc.rail_env = v_batch.rail_env_snapshot
   and bnc.entity_kind = t.payee_kind
   and bnc.entity_id = t.payee_id
   and bnc.bank_details_hash = t.bank_hash;

  if v_blocked_name > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_NAME_CHECK',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_blocked_name
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_NAME_CHECK',
      'message', format('pay_batch_schedule: BLOCKED_NAME_CHECK for %s payee(s)', v_blocked_name::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_blocked_name,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  with t as (
    select
      upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) as payee_kind,
      coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else pbt.candidate_id end
      ) as payee_id,
      nullif(btrim(coalesce(pbt.bank_details_hash_snapshot,'')), '') as bank_hash
    from public.pay_bank_transfers pbt
    left join public.candidates c
      on c.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then null else pbt.candidate_id end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'CANDIDATE'
    left join public.umbrellas u
      on u.id = coalesce(
        pbt.payee_entity_id,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then pbt.umbrella_id else null end
      )
     and upper(coalesce(pbt.payee_entity_kind,
        case when upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA' then 'UMBRELLA' else 'CANDIDATE' end
      )) = 'UMBRELLA'
    where pbt.pay_batch_id = p_pay_batch_id
      and upper(coalesce(pbt.status,'')) = 'PENDING'
    group by 1,2,3
  )
  select
    sum(
      case
        when v_requires_payee_map = true then
          case when bpm.payee_id is null then 1 else 0 end
        else 0
      end
    )::int
  into v_missing_map
  from t
  left join public.bank_payee_map bpm
    on bpm.rail_provider = v_batch.rail_provider_snapshot
   and bpm.rail_env = v_batch.rail_env_snapshot
   and bpm.entity_kind = t.payee_kind
   and bpm.entity_id = t.payee_id
   and bpm.bank_details_hash = t.bank_hash;

  if v_missing_map > 0 then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_BATCH_SCHEDULE:BLOCKED_NO_PAYEE_MAP',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'count', v_missing_map
        ),
        'pay_batches',
        p_pay_batch_id::text
      );
    exception when others then
      null;
    end;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_SCHEDULE_BLOCKED',
      'code', 'BLOCKED_NO_PAYEE_MAP',
      'message', format('pay_batch_schedule: BLOCKED_NO_PAYEE_MAP for %s payee(s)', v_missing_map::text),
      'pay_batch_id', p_pay_batch_id::text,
      'count', v_missing_map,
      'ui_hint', 'RERUN_PREVIEW'
    )::text;
  end if;

  update public.pay_batches pb
  set
    schedule_kind = v_kind,
    scheduled_at_utc = v_sched_at,
    scheduled_by_user_id = p_actor_user_id,
    funding_account_ref = v_funding,
    funds_warning_hours_json = v_warn,
    authoritative_payment_date = v_authoritative_payment_date,
    authoritative_payment_date_source = 'SCHEDULED_AT_UTC',
    pay_date = v_authoritative_payment_date,
    status = 'SCHEDULED',
    execution_commit_state = v_execution_commit_state,
    execution_commit_ref = v_execution_commit_ref,
    execution_committed_at_utc = v_execution_committed_at_utc,
    execution_intent_json = coalesce(v_execution_intent_json, '{}'::jsonb) || jsonb_build_object(
      'execution_mode', v_execution_mode,
      'payment_date', v_authoritative_payment_date::text,
      'schedule_kind', v_kind,
      'scheduled_at_utc', case when v_sched_at is null then null else v_sched_at::text end,
      'operation_id', case when p_operation_id is null then null else p_operation_id::text end,
      'freshness_result_hash', v_stored_freshness_hash,
      'freshness_scope_hash', v_stored_freshness_scope_hash
    )
  where pb.id = p_pay_batch_id;

  update public.pay_advance_reservations par
  set
    status = 'COMMITTED',
    committed_at_utc = coalesce(par.committed_at_utc, v_commit_ts),
    updated_by_user_id = p_actor_user_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'RESERVED';

  get diagnostics v_reservations_committed_count = row_count;

  select round(coalesce(sum(par.reserved_amount),0),2)
  into v_reservations_committed_amount
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED';

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    'RESERVATION_COMMITTED',
    v_commit_ts,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'RESERVED'),
    jsonb_build_object(
      'reservation_status', 'COMMITTED',
      'authoritative_payment_date', v_authoritative_payment_date::text,
      'schedule_kind', v_kind,
      'scheduled_at_utc', v_sched_at::text
    ),
    'schedule_commit',
    null
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and par.committed_at_utc = v_commit_ts;

  begin
    v_comm_result := public.pay_remittance_maybe_queue_for_trigger(
      p_pay_batch_id => p_pay_batch_id,
      p_trigger => 'ON_EXECUTION',
      p_scope => 'ALL',
      p_actor_user_id => p_actor_user_id,
      p_only_confirmed => false,
      p_root_operation_id => CASE WHEN v_operation_mode THEN p_operation_id ELSE NULL::uuid END,
      p_operation_mode => v_operation_mode
    );

    if coalesce((v_comm_result->>'ok')::boolean, true) = false then
      raise exception '%', coalesce(
        nullif(btrim(coalesce(v_comm_result->>'error','')), ''),
        'pay_batch_schedule: remittance timing queue stage failed'
      );
    end if;

    v_comm_trigger_status := coalesce(
      nullif(btrim(coalesce(v_comm_result->>'trigger_status','')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}','')), ''),
      case
        when lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_DEFERRED_BY_TIMING'
        when lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on') then 'SUPPRESSED_BY_EXECUTION_INTENT'
        when lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on') then 'REMITTANCE_QUEUE_OPERATION_READY'
        when lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on') then 'QUEUE_STAGE_BUILD_READY'
        else 'ON_EXECUTION_QUEUE_GATE_PROCESSED'
      end
    );
    v_comm_message_kind := coalesce(
      nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''),
      case when v_batch_kind_fixed = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end
    );
    v_comm_error := nullif(btrim(coalesce(v_comm_result->>'error','')), '');

    v_payout_notice_result := case
      when v_batch_kind_fixed = 'LOANS' then coalesce(v_comm_result->'queue_result', v_comm_result)
      else '{}'::jsonb
    end;
    v_remittance_result := case
      when v_batch_kind_fixed <> 'LOANS' then coalesce(v_comm_result->'queue_result', v_comm_result)
      else '{}'::jsonb
    end;

    v_payout_notice_dispatch_required := (
      v_batch_kind_fixed = 'LOANS'
      and lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on')
    );
    v_remittance_dispatch_required := (
      v_batch_kind_fixed <> 'LOANS'
      and lower(btrim(coalesce(v_comm_result->>'dispatch_required', v_comm_result#>>'{queue_result,dispatch_required}', 'false'))) in ('true','1','yes','y','on')
    );

    if btrim(coalesce(coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}'), '')) ~ '^[0-9]+$' then
      if v_batch_kind_fixed = 'LOANS' then
        v_payout_notice_targeted_count := coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}')::int;
        v_remittance_targeted_count := 0;
      else
        v_remittance_targeted_count := coalesce(v_comm_result->>'candidate_count_targeted', v_comm_result#>>'{queue_result,candidate_count_targeted}')::int;
        v_payout_notice_targeted_count := 0;
      end if;
    else
      v_payout_notice_targeted_count := 0;
      v_remittance_targeted_count := 0;
    end if;

    insert into public.audit_events(
      actor_user_id,
      object_type,
      object_id_text,
      action,
      before_json,
      after_json,
      reason
    )
    values (
      p_actor_user_id,
      'pay_batch',
      p_pay_batch_id::text,
      'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TIMING_GATE',
      null,
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'batch_kind_fixed', v_batch_kind_fixed,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'authoritative_payment_date', v_authoritative_payment_date::text,
        'trigger_status', v_comm_trigger_status,
        'message_kind', v_comm_message_kind,
        'result', coalesce(v_comm_result, '{}'::jsonb),
        'execution_mode', v_execution_mode,
        'suppress_remittances', v_suppress_remittances
      ),
      'commit_stage_communication_timing_gate'
    );
  exception when others then
    v_comm_trigger_status := 'COMMIT_STAGE_QUEUE_TIMING_GATE_ERROR';
    v_comm_error := left(coalesce(SQLERRM,'UNKNOWN_COMMS_ERROR'), 1000);
    v_comm_message_kind := coalesce(v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE');
    v_comm_result := jsonb_build_object(
      'ok', false,
      'trigger', 'ON_EXECUTION',
      'configured_timing', v_timing_setting_if_known,
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'message_kind', v_comm_message_kind,
      'automatic_commit_stage', (v_provider <> 'CSV'),
      'dispatch_required', false,
      'operation_id', NULL::text,
      'deferred', false,
      'suppressed', false,
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'queue_result', jsonb_build_object(
        'ok', false,
        'trigger', 'ON_EXECUTION',
        'configured_timing', v_timing_setting_if_known,
        'trigger_status', v_comm_trigger_status,
        'error', v_comm_error,
        'operation_id', NULL::text,
        'deferred', false,
        'suppressed', false
      )
    );

    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      values (
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
        null,
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'batch_kind_fixed', v_batch_kind_fixed,
          'schedule_kind', v_kind,
          'scheduled_at_utc', v_sched_at::text,
          'authoritative_payment_date', v_authoritative_payment_date::text,
          'trigger_status', v_comm_trigger_status,
          'message_kind', v_comm_message_kind,
          'error', v_comm_error,
          'queue_result', coalesce(v_comm_result, '{}'::jsonb)
        ),
        'commit_stage_communication'
      );
    exception when others then
      null;
    end;

    if v_execution_commit_state = 'NOT_SUBMITTED' then
      begin
        update public.pay_batches as pb_schedule_rollback
        set
          status = v_batch.status,
          schedule_kind = v_batch.schedule_kind,
          scheduled_at_utc = v_batch.scheduled_at_utc,
          scheduled_by_user_id = v_batch.scheduled_by_user_id,
          funding_account_ref = v_batch.funding_account_ref,
          funds_warning_hours_json = v_batch.funds_warning_hours_json,
          pay_date = v_batch.pay_date,
          authoritative_payment_date = v_batch.authoritative_payment_date,
          authoritative_payment_date_source = v_batch.authoritative_payment_date_source,
          execution_commit_state = v_execution_commit_state,
          execution_commit_ref = v_execution_commit_ref,
          execution_committed_at_utc = v_execution_committed_at_utc,
          execution_intent_json = v_batch.execution_intent_json
        where pb_schedule_rollback.id = p_pay_batch_id
          and upper(coalesce(pb_schedule_rollback.execution_commit_state, 'NOT_SUBMITTED')) = 'NOT_SUBMITTED'
          and not exists (
            select 1
            from public.pay_bank_transfer_events as rollback_transfer_event
            where rollback_transfer_event.pay_batch_id = p_pay_batch_id
          )
          and not exists (
            select 1
            from public.pay_bank_transfers as rollback_transfer
            where rollback_transfer.pay_batch_id = p_pay_batch_id
              and (
                nullif(btrim(coalesce(rollback_transfer.rail_tx_id, '')), '') is not null
                or upper(coalesce(rollback_transfer.status, '')) in ('SUBMITTED', 'PROCESSING', 'SENT', 'COMPLETED', 'PAID', 'SETTLED')
              )
          );
      exception when others then
        null;
      end;
    end if;

    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', (v_provider <> 'CSV'),
      'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
      'trigger_status', v_comm_trigger_status,
      'error', v_comm_error,
      'dispatch_required', false,
      'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
      'remittance', coalesce(v_remittance_result, '{}'::jsonb),
      'result', coalesce(v_comm_result, '{}'::jsonb),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances
    );

    return jsonb_build_object(
      'ok', false,
      'error', 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
      'code', 'COMMIT_STAGE_COMMUNICATION_ERROR',
      'message', 'pay_batch_schedule: commit-stage communication failed before provider submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'status', (select pb2.status from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'schedule_kind', (select pb2.schedule_kind from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'scheduled_at_utc', (select case when pb2.scheduled_at_utc is null then null else pb2.scheduled_at_utc::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'authoritative_payment_date', (select case when pb2.authoritative_payment_date is null then null else pb2.authoritative_payment_date::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'authoritative_payment_date_source', (select pb2.authoritative_payment_date_source from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'funding_account_ref', (select pb2.funding_account_ref from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'funds_warning_hours_json', (select pb2.funds_warning_hours_json from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_commit_state', (select pb2.execution_commit_state from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_commit_ref', (select pb2.execution_commit_ref from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb2.execution_committed_at_utc is null then null else pb2.execution_committed_at_utc::text end from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_intent_json', (select pb2.execution_intent_json from public.pay_batches as pb2 where pb2.id = p_pay_batch_id),
      'execution_mode', v_execution_mode,
      'suppress_remittances', v_suppress_remittances,
      'remittance_trigger', 'ON_EXECUTION',
      'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
      'remittance_deferred', false,
      'remittance_suppressed', false,
      'remittance_operation_queued', false,
      'remittance_child_operation_id', null,
      'remittance_trigger_status', v_comm_trigger_status,
      'remittance_message_kind', v_comm_message_kind,
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb)
    );
  end;
  v_worker_communications := jsonb_build_object(
    'automatic_commit_stage', (v_provider <> 'CSV'),
    'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), v_comm_message_kind, 'PAYOUT_NOTICE_AND_REMITTANCE'),
    'trigger_status', v_comm_trigger_status,
    'error', v_comm_error,
    'dispatch_required', (v_payout_notice_dispatch_required = true or v_remittance_dispatch_required = true),
    'payout_notice', coalesce(v_payout_notice_result, '{}'::jsonb),
    'remittance', coalesce(v_remittance_result, '{}'::jsonb),
    'result', coalesce(v_comm_result, '{}'::jsonb),
    'execution_mode', v_execution_mode,
    'suppress_remittances', v_suppress_remittances
  );

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_SCHEDULE:OK',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'schedule_kind', v_kind,
        'scheduled_at_utc', v_sched_at::text,
        'authoritative_payment_date', v_authoritative_payment_date::text,
        'funding_account_ref', v_funding,
        'rail_provider_snapshot', v_batch.rail_provider_snapshot,
        'rail_env_snapshot', v_batch.rail_env_snapshot,
        'execution_mode', v_execution_mode,
        'suppress_remittances', v_suppress_remittances,
        'pending_transfers', v_pending_transfers,
        'reservations_committed_count', v_reservations_committed_count,
        'reservations_committed_amount', v_reservations_committed_amount,
        'worker_communications', v_worker_communications
      ),
      'pay_batches',
      p_pay_batch_id::text
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'status', (select pb2.status from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'schedule_kind', (select pb2.schedule_kind from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'scheduled_at_utc', (select case when pb2.scheduled_at_utc is null then null else pb2.scheduled_at_utc::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'authoritative_payment_date', (select case when pb2.authoritative_payment_date is null then null else pb2.authoritative_payment_date::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'authoritative_payment_date_source', (select pb2.authoritative_payment_date_source from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'funding_account_ref', (select pb2.funding_account_ref from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'funds_warning_hours_json', (select pb2.funds_warning_hours_json from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'rail_provider_snapshot', v_batch.rail_provider_snapshot,
    'rail_env_snapshot', v_batch.rail_env_snapshot,
    'execution_commit_state', (select pb2.execution_commit_state from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_commit_ref', (select pb2.execution_commit_ref from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_committed_at_utc', (select case when pb2.execution_committed_at_utc is null then null else pb2.execution_committed_at_utc::text end from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'execution_mode', v_execution_mode,
    'execution_intent_json', (select pb2.execution_intent_json from public.pay_batches pb2 where pb2.id = p_pay_batch_id),
    'suppress_remittances', v_suppress_remittances,
    'finance_reservations', jsonb_build_object(
      'committed_count', v_reservations_committed_count,
      'committed_amount', v_reservations_committed_amount
    ),
    'remittance_trigger', 'ON_EXECUTION',
    'remittance_configured_timing', coalesce(v_comm_result->>'configured_timing', v_comm_result#>>'{queue_result,configured_timing}'),
    'remittance_deferred', lower(btrim(coalesce(v_comm_result->>'deferred', 'false'))) in ('true','1','yes','y','on'),
    'remittance_suppressed', lower(btrim(coalesce(v_comm_result->>'suppressed', 'false'))) in ('true','1','yes','y','on'),
    'remittance_operation_queued', lower(btrim(coalesce(v_comm_result->>'operation_queued', 'false'))) in ('true','1','yes','y','on'),
    'remittance_child_operation_id', coalesce(
      nullif(btrim(coalesce(v_comm_result->>'operation_id', '')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,operation_id}', '')), '')
    ),
    'remittance_trigger_status', coalesce(
      nullif(btrim(coalesce(v_comm_result->>'trigger_status', '')), ''),
      nullif(btrim(coalesce(v_comm_result#>>'{queue_result,trigger_status}', '')), ''),
      v_comm_trigger_status
    ),
    'remittance_message_kind', v_comm_message_kind,
    'worker_communications', v_worker_communications,
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb)
  );
end;
$$;




DROP FUNCTION IF EXISTS public.pay_batch_prepare(uuid, uuid);


DROP FUNCTION IF EXISTS public.pay_batch_prepare(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_prepare(uuid, uuid, uuid, text);




CREATE OR REPLACE FUNCTION public.pay_batch_prepare(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_freshness_result_hash text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_summary_json jsonb := '{}'::jsonb;
  v_fresh_json jsonb := '{}'::jsonb;
  v_blockers_json jsonb := '[]'::jsonb;
  v_warnings_json jsonb := '[]'::jsonb;
  v_next_required_phase text := 'START_AUTHORISATION';
  v_ready boolean := false;
  v_is_stale boolean := false;
  v_batch_status text := NULL::text;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_mode text := 'STANDARD_BANK';
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_transfer_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_authorisation_ready_transfer_count integer := 0;
  v_unattempted_submit_eligible_transfer_count integer := 0;
  v_remaining_unattempted_submit_required integer := 0;
  v_provider_attempt_or_evidence_transfer_count integer := 0;
  v_provider_or_ambiguous_evidence_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_canonical_pending_status_transfer_count integer := 0;
  v_safe_local_cleanup_transfer_count integer := 0;
  v_unsafe_transfer_count integer := 0;
  v_scoped_failed_or_blocked_transfer_count integer := 0;
  v_scoped_blocked_transfer_count integer := 0;
  v_scoped_operation_scope_count integer := 0;
  v_scoped_scope_prepared_count integer := 0;
  v_scoped_scope_pending_count integer := 0;
  v_scoped_scope_failed_count integer := 0;
  v_scoped_scope_skipped_count integer := 0;
  v_scoped_scope_without_transfer_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_auth_request_retry_blocker_count integer := 0;
  v_all_scoped_operation_scopes_authorisation_ready boolean := false;
  v_pay_channel_scope text := 'ALL';
  v_failed_transfer_count integer := 0;
  v_blocked_transfer_count integer := 0;
  v_submitted_transfer_count integer := 0;
  v_awaiting_net_count integer := 0;
  v_blocker_count integer := 0;
  v_warning_count integer := 0;
  v_diff_sample jsonb := '[]'::jsonb;
  v_operation_mode boolean := false;
  v_expected_freshness_hash text := null;
  v_expected_freshness_scope_hash text := null;
  v_batch_freshness_hash text := null;
  v_batch_freshness_scope_hash text := null;
  v_batch_freshness_status text := null;
  v_batch_freshness_json jsonb := '{}'::jsonb;
  v_large_batch boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_prepare: pay_batch_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_prepare: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  PERFORM 1
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id
    AND coalesce(actor_user.is_active, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'ACTOR_USER_NOT_FOUND',
      'message', 'pay_batch_prepare: actor_user was not found or is inactive',
      'actor_user_id', p_actor_user_id::text,
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_PREPARE',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_prepare: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  END IF;

  v_batch_status := upper(btrim(coalesce(v_batch_row.status, '')));
  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  v_operation_mode := p_operation_id IS NOT NULL OR nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_NOT_FOUND',
        'message', 'pay_batch_prepare: operation was not found',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_BATCH_MISMATCH',
        'message', 'pay_batch_prepare: operation belongs to another batch',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_pay_batch_id', v_operation_row.pay_batch_id::text
      )::text;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_PREPARE',
        'code', 'OPERATION_ACTOR_MISMATCH',
        'message', 'pay_batch_prepare: operation belongs to another actor',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    v_expected_freshness_hash := coalesce(
      nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_result_hash}', '')), '')
    );
    v_expected_freshness_scope_hash := coalesce(
      nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_scope_hash', '')), ''),
      nullif(btrim(coalesce(v_operation_row.result_json #>> '{freshness,freshness_scope_hash}', '')), '')
    );
    v_pay_channel_scope := upper(btrim(coalesce(
      nullif(btrim(coalesce(v_operation_row.input_json->>'pay_channel_scope', '')), ''),
      nullif(btrim(coalesce(v_operation_row.input_json->>'payChannelScope', '')), ''),
      nullif(btrim(coalesce(v_operation_row.config_json->>'pay_channel_scope', '')), ''),
      nullif(btrim(coalesce(v_operation_row.config_json->>'payChannelScope', '')), ''),
      'ALL'
    )));
    IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'LOANS', 'ALL') THEN
      v_pay_channel_scope := 'ALL';
    END IF;
  ELSE
    v_expected_freshness_hash := nullif(btrim(coalesce(p_freshness_result_hash, '')), '');
  END IF;

  v_summary_json := public.pay_batch_execution_summary_get(
    p_pay_batch_id => p_pay_batch_id,
    p_actor_user_id => p_actor_user_id
  );

  v_execution_mode := upper(btrim(coalesce(
    v_summary_json->>'execution_mode',
    v_batch_row.execution_intent_json->>'execution_mode',
    v_batch_row.execution_intent_json->>'mode',
    'STANDARD_BANK'
  )));

  v_candidate_count := coalesce(NULLIF(v_summary_json->>'candidate_count', '')::integer, 0);
  v_item_count := coalesce(NULLIF(v_summary_json->>'item_count', '')::integer, 0);
  v_transfer_count := coalesce(NULLIF(v_summary_json->>'transfer_count', '')::integer, 0);
  v_pending_transfer_count := coalesce(NULLIF(v_summary_json->>'pending_transfer_count', '')::integer, 0);
  v_authorisation_ready_transfer_count := coalesce(NULLIF(v_summary_json->>'authorisation_ready_transfer_count', '')::integer, 0);
  v_unattempted_submit_eligible_transfer_count := coalesce(NULLIF(v_summary_json->>'unattempted_submit_eligible_transfer_count', '')::integer, 0);
  v_remaining_unattempted_submit_required := coalesce(NULLIF(v_summary_json->>'remaining_unattempted_submit_required', '')::integer, v_unattempted_submit_eligible_transfer_count);
  v_provider_attempt_or_evidence_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_attempt_or_evidence_transfer_count', '')::integer, 0);
  v_provider_or_ambiguous_evidence_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_or_ambiguous_evidence_transfer_count', '')::integer, 0);
  v_local_only_transfer_count := coalesce(NULLIF(v_summary_json->>'local_only_transfer_count', '')::integer, 0);
  v_canonical_pending_status_transfer_count := coalesce(NULLIF(v_summary_json->>'canonical_pending_status_transfer_count', '')::integer, 0);
  v_safe_local_cleanup_transfer_count := coalesce(NULLIF(v_summary_json->>'safe_local_cleanup_transfer_count', '')::integer, 0);
  SELECT
    count(*) FILTER (WHERE classified_transfer.is_authorisation_ready)::integer,
    count(*) FILTER (WHERE classified_transfer.is_unattempted_submit_eligible)::integer,
    count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt)::integer,
    count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt OR classified_transfer.has_ambiguous_external_evidence)::integer,
    count(*) FILTER (WHERE classified_transfer.status_upper = 'PENDING')::integer,
    count(*) FILTER (
      WHERE classified_transfer.pay_bank_transfer_id IS NOT NULL
        AND classified_transfer.is_authorisation_ready IS NOT TRUE
        AND (
          classified_transfer.has_provider_submission_evidence
          OR classified_transfer.has_provider_event_evidence
          OR classified_transfer.has_provider_attempt_without_external_id
          OR classified_transfer.has_operation_submit_attempt
          OR classified_transfer.has_ambiguous_external_evidence
          OR classified_transfer.is_failed_or_blocked
          OR classified_transfer.is_terminal_or_completed
          OR classified_transfer.has_different_operation_scope
          OR classified_transfer.has_stale_auth_request_evidence
          OR classified_transfer.has_non_cancellable_auth_request
          OR NULLIF(BTRIM(COALESCE(classified_transfer.unsafe_reason, '')), '') IS NOT NULL
        )
    )::integer,
    count(*) FILTER (WHERE classified_transfer.is_failed_or_blocked IS TRUE)::integer,
    count(*) FILTER (
      WHERE classified_transfer.status_upper = 'BLOCKED'
         OR classified_transfer.rail_state_upper = 'BLOCKED'
    )::integer,
    count(DISTINCT classified_transfer.auth_request_id) FILTER (
      WHERE classified_transfer.auth_request_id IS NOT NULL
        AND classified_transfer.has_non_cancellable_auth_request IS TRUE
    )::integer,
    count(DISTINCT classified_transfer.auth_request_id) FILTER (
      WHERE classified_transfer.auth_request_id IS NOT NULL
        AND (
          classified_transfer.has_non_cancellable_auth_request IS TRUE
          OR classified_transfer.has_auth_request_provider_risk IS TRUE
          OR classified_transfer.has_other_operation_active_auth_request IS TRUE
        )
    )::integer
  INTO v_authorisation_ready_transfer_count,
       v_unattempted_submit_eligible_transfer_count,
       v_provider_attempt_or_evidence_transfer_count,
       v_provider_or_ambiguous_evidence_transfer_count,
       v_canonical_pending_status_transfer_count,
       v_unsafe_transfer_count,
       v_scoped_failed_or_blocked_transfer_count,
       v_scoped_blocked_transfer_count,
       v_non_cancellable_auth_request_count,
       v_auth_request_retry_blocker_count
  FROM public.pay_bank_transfer_execution_classify(
    p_pay_batch_id => p_pay_batch_id,
    p_pay_channel_scope => v_pay_channel_scope,
    p_operation_id => p_operation_id,
    p_include_unscoped_transfers => CASE WHEN p_operation_id IS NULL THEN true ELSE false END
  ) AS classified_transfer
  WHERE (
    p_operation_id IS NULL
    OR EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS scoped_operation_filter
      WHERE scoped_operation_filter.pay_batch_id = p_pay_batch_id
        AND scoped_operation_filter.operation_id = p_operation_id
        AND (
          v_pay_channel_scope IN ('ALL', 'ANY', '*')
          OR upper(btrim(coalesce(scoped_operation_filter.pay_channel, ''))) = v_pay_channel_scope
        )
        AND (
          scoped_operation_filter.id = classified_transfer.scope_id
          OR (
            classified_transfer.pay_bank_transfer_id IS NOT NULL
            AND scoped_operation_filter.pay_bank_transfer_id = classified_transfer.pay_bank_transfer_id
          )
        )
    )
  );

  IF p_operation_id IS NOT NULL THEN
    SELECT count(*)::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PREPARED')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PENDING')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'FAILED')::integer,
           count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'SKIPPED')::integer,
           count(*) FILTER (WHERE operation_scope.pay_bank_transfer_id IS NULL)::integer
    INTO v_scoped_operation_scope_count,
         v_scoped_scope_prepared_count,
         v_scoped_scope_pending_count,
         v_scoped_scope_failed_count,
         v_scoped_scope_skipped_count,
         v_scoped_scope_without_transfer_count
    FROM public.banking_pay_operation_transfer_scope AS operation_scope
    WHERE operation_scope.pay_batch_id = p_pay_batch_id
      AND operation_scope.operation_id = p_operation_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR upper(btrim(coalesce(operation_scope.pay_channel, ''))) = v_pay_channel_scope
      );

    v_all_scoped_operation_scopes_authorisation_ready := (
      COALESCE(v_scoped_operation_scope_count, 0) > 0
      AND COALESCE(v_scoped_scope_prepared_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_scoped_scope_pending_count, 0) = 0
      AND COALESCE(v_scoped_scope_failed_count, 0) = 0
      AND COALESCE(v_scoped_scope_skipped_count, 0) = 0
      AND COALESCE(v_scoped_scope_without_transfer_count, 0) = 0
      AND COALESCE(v_authorisation_ready_transfer_count, 0) = COALESCE(v_scoped_operation_scope_count, 0)
      AND COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) = 0
      AND COALESCE(v_non_cancellable_auth_request_count, 0) = 0
    );
  END IF;
  v_remaining_unattempted_submit_required := COALESCE(v_unattempted_submit_eligible_transfer_count, 0);
  v_failed_transfer_count := coalesce(NULLIF(v_summary_json->>'failed_transfer_count', '')::integer, 0);
  v_blocked_transfer_count := coalesce(NULLIF(v_summary_json->>'blocked_transfer_count', '')::integer, 0);
  v_submitted_transfer_count := coalesce(NULLIF(v_summary_json->>'provider_submitted_transfer_count', '')::integer, coalesce(NULLIF(v_summary_json->>'submitted_transfer_count', '')::integer, 0));

  v_batch_freshness_status := upper(btrim(coalesce(v_batch_row.freshness_validation_status, '')));
  v_batch_freshness_hash := nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '');
  v_batch_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, '')), '');
  v_batch_freshness_json := coalesce(v_batch_row.freshness_result_json, '{}'::jsonb);

  IF v_execution_commit_state <> 'NOT_SUBMITTED'
     OR nullif(btrim(coalesce(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has already crossed the execution boundary and cannot be prepared again.',
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_batch_row.execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_batch_row.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch_row.execution_committed_at_utc::text END
    ));
  ELSIF v_operation_mode THEN
    IF v_batch_freshness_status <> 'PASSED' THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', CASE WHEN v_batch_freshness_status = 'STALE' THEN 'BATCH_STALE' ELSE 'FRESHNESS_REQUIRED' END,
        'message', 'Chunked freshness must pass before this payment batch can be prepared.',
        'freshness_validation_status', nullif(v_batch_freshness_status, ''),
        'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash,
        'stale_reasons', coalesce(v_batch_freshness_json->'stale_reasons', '[]'::jsonb),
        'diff_sample', coalesce(v_batch_freshness_json->'diff_sample', '[]'::jsonb)
      ));
    ELSIF p_operation_id IS NOT NULL AND v_expected_freshness_hash IS NULL THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'OPERATION_FRESHNESS_RESULT_HASH_MISSING',
        'message', 'The payment operation does not carry a completed freshness result hash.',
        'freshness_validation_status', nullif(v_batch_freshness_status, ''),
        'freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_expected_freshness_hash IS NOT NULL AND v_batch_freshness_hash IS DISTINCT FROM v_expected_freshness_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'The stored freshness result does not match the operation freshness result.',
        'expected_freshness_result_hash', v_expected_freshness_hash,
        'actual_freshness_result_hash', v_batch_freshness_hash,
        'freshness_scope_hash', v_batch_freshness_scope_hash
      ));
    ELSIF v_expected_freshness_scope_hash IS NOT NULL AND v_batch_freshness_scope_hash IS DISTINCT FROM v_expected_freshness_scope_hash THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_SCOPE_HASH_MISMATCH',
        'message', 'The stored freshness scope does not match the operation freshness scope.',
        'expected_freshness_scope_hash', v_expected_freshness_scope_hash,
        'actual_freshness_scope_hash', v_batch_freshness_scope_hash,
        'freshness_result_hash', v_batch_freshness_hash
      ));
    END IF;
  ELSE
    v_large_batch := coalesce(v_candidate_count, 0) > 100 OR coalesce(v_item_count, 0) > 250 OR coalesce(v_transfer_count, 0) > 100;

    IF v_large_batch THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION',
        'message', 'This batch must use chunked freshness validation before payment can continue.',
        'candidate_count', v_candidate_count,
        'item_count', v_item_count,
        'transfer_count', v_transfer_count
      ));
    ELSE
      v_fresh_json := public.pay_batch_validate_freshness(
        p_pay_batch_id => p_pay_batch_id,
        p_actor_user_id => p_actor_user_id,
        p_allow_large_full_scan => false
      );
      v_is_stale := coalesce((v_fresh_json->>'is_stale')::boolean, false);

      IF v_is_stale THEN
        SELECT coalesce(jsonb_agg(diff_row.elem), '[]'::jsonb)
        INTO v_diff_sample
        FROM (
          SELECT diff_elem.elem
          FROM jsonb_array_elements(coalesce(v_fresh_json->'diff', '[]'::jsonb)) AS diff_elem(elem)
          LIMIT 20
        ) AS diff_row;

        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', CASE WHEN coalesce((v_fresh_json->>'requires_chunked_freshness')::boolean, false) THEN 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' ELSE 'BATCH_STALE' END,
          'message', CASE WHEN coalesce((v_fresh_json->>'requires_chunked_freshness')::boolean, false) THEN 'This batch must use chunked freshness validation before payment can continue.' ELSE 'The payment batch is no longer up to date and must be regenerated before payment can continue.' END,
          'stale_reasons', coalesce(v_fresh_json->'stale_reasons', '[]'::jsonb),
          'diff_sample', v_diff_sample
        ));
      END IF;
    END IF;
  END IF;

  IF v_batch_status IN ('CANCELLED', 'CANCELED') THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'BATCH_CANCELLED',
      'message', 'The payment batch has been cancelled.'
    ));
  END IF;

  IF v_candidate_count <= 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'NO_CANDIDATES',
      'message', 'The payment batch has no candidates.'
    ));
  END IF;

  IF v_item_count <= 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'NO_PAYMENT_ITEMS',
      'message', 'The payment batch has no payment items.'
    ));
  END IF;

  SELECT count(*)::integer
  INTO v_awaiting_net_count
  FROM public.pay_batch_candidates AS batch_candidate
  WHERE batch_candidate.pay_batch_id = p_pay_batch_id
    AND coalesce(batch_candidate.awaiting_net_amount, false) = true;

  IF v_awaiting_net_count > 0 THEN
    v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
      'code', 'PAYE_NET_REQUIRED',
      'message', 'PAYE net amounts are required before this batch can proceed.',
      'candidate_count', v_awaiting_net_count
    ));
  END IF;

  IF v_execution_mode NOT IN ('CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN
    IF v_transfer_count <= 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BANK_TRANSFERS_NOT_PREPARED',
        'message', 'Bank transfer groups must be prepared before payment authorisation can start.'
      ));
    END IF;

    IF p_operation_id IS NULL THEN
      IF v_blocked_transfer_count > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BLOCKED_TRANSFERS',
          'message', 'One or more bank transfers are blocked and must be corrected before submission.',
          'blocked_transfer_count', v_blocked_transfer_count
        ));
      END IF;

      IF v_failed_transfer_count > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'FAILED_TRANSFERS',
          'message', 'One or more bank transfers are failed and must be corrected before submission.',
          'failed_transfer_count', v_failed_transfer_count
        ));
      END IF;
    ELSE
      IF COALESCE(v_scoped_blocked_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BLOCKED_TRANSFERS',
          'message', 'One or more scoped bank transfers are blocked and must be corrected before submission.',
          'operation_id', p_operation_id::text,
          'blocked_transfer_count', COALESCE(v_scoped_blocked_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_failed_or_blocked_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'FAILED_TRANSFERS',
          'message', 'One or more scoped bank transfers are failed or blocked and must be corrected before submission.',
          'operation_id', p_operation_id::text,
          'failed_transfer_count', COALESCE(v_scoped_failed_or_blocked_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;
    END IF;

    IF p_operation_id IS NOT NULL THEN
      IF COALESCE(v_scoped_operation_scope_count, 0) <= 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'OPERATION_TRANSFER_SCOPE_NOT_PREPARED',
          'message', 'No operation-scoped bank transfer groups are prepared for this payment execution attempt.',
          'operation_id', p_operation_id::text,
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         OR COALESCE(v_scoped_scope_pending_count, 0) > 0
         OR COALESCE(v_scoped_scope_failed_count, 0) > 0
         OR COALESCE(v_scoped_scope_skipped_count, 0) > 0
         OR COALESCE(v_scoped_scope_without_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'OPERATION_TRANSFER_SCOPE_NOT_FULLY_PREPARED',
          'message', 'Every scoped transfer group must be prepared and linked to a safe local bank transfer before authorisation can start.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
          'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
          'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
          'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
          'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
          'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment execution attempt.',
          'operation_id', p_operation_id::text,
          'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
          'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED',
          'message', 'One or more scoped bank transfers have provider submission evidence or ambiguous provider state and must be reviewed before this batch can be authorised again.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
          'batch_submitted_transfer_count', COALESCE(v_submitted_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;

      IF COALESCE(v_scoped_operation_scope_count, 0) > 0
         AND COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         AND COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) = 0 THEN
        v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
          'code', 'NO_AUTHORISATION_READY_TRANSFERS',
          'message', 'All scoped bank transfer groups must be authorisation-ready before authorisation can start.',
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'safe_local_cleanup_transfer_count', COALESCE(v_safe_local_cleanup_transfer_count, 0),
          'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
          'pay_channel_scope', v_pay_channel_scope
        ));
      END IF;
    END IF;

    IF p_operation_id IS NULL AND COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
        'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment batch.',
        'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
        'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    END IF;

    IF p_operation_id IS NULL AND v_provider_or_ambiguous_evidence_transfer_count > 0 AND v_transfer_count > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED',
        'message', 'One or more bank transfers have provider submission evidence or ambiguous provider state and must be reviewed before this batch can be authorised again.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
        'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'submitted_transfer_count', COALESCE(v_submitted_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    ELSIF p_operation_id IS NULL AND v_authorisation_ready_transfer_count <= 0 AND v_transfer_count > 0 THEN
      v_blockers_json := v_blockers_json || jsonb_build_array(jsonb_build_object(
        'code', 'NO_AUTHORISATION_READY_TRANSFERS',
        'message', 'No safe locally prepared bank transfers are available for authorisation.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
        'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
        'safe_local_cleanup_transfer_count', COALESCE(v_safe_local_cleanup_transfer_count, 0),
        'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    ELSIF v_pending_transfer_count <= 0 AND v_authorisation_ready_transfer_count > 0 THEN
      v_warnings_json := v_warnings_json || jsonb_build_array(jsonb_build_object(
        'code', 'EVIDENCE_PENDING_COUNT_ZERO_AUTHORISATION_READY_PRESENT',
        'message', 'Evidence pending count is zero, but safe local transfers are ready for authorisation.',
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'evidence_pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
        'pay_channel_scope', v_pay_channel_scope
      ));
    END IF;
  END IF;

  v_blocker_count := jsonb_array_length(v_blockers_json);
  v_warning_count := jsonb_array_length(v_warnings_json);
  v_ready := v_blocker_count = 0;

  v_next_required_phase := CASE
    WHEN v_execution_commit_state <> 'NOT_SUBMITTED' THEN 'STOP_EXECUTION_BOUNDARY_CROSSED'
    WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_blockers_json) AS blocker(elem) WHERE blocker.elem->>'code' IN ('BATCH_STALE','FRESHNESS_REQUIRED','FRESHNESS_REQUIRES_CHUNKED_VALIDATION','FRESHNESS_RESULT_HASH_MISMATCH')) THEN 'VALIDATE_FRESHNESS'
    WHEN v_batch_status IN ('CANCELLED', 'CANCELED') THEN 'STOP_CANCELLED'
    WHEN v_execution_mode IN ('CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') AND v_ready THEN 'SETTLEMENT'
    WHEN v_transfer_count <= 0 THEN 'PREPARE_TRANSFER_SCOPE'
    WHEN v_blocker_count > 0 THEN 'RESOLVE_BLOCKERS'
    WHEN v_execution_mode IN ('STANDARD_BANK', 'BANK') AND p_operation_id IS NOT NULL AND COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false) IS NOT TRUE THEN 'RESOLVE_BLOCKERS'
    WHEN v_execution_mode IN ('STANDARD_BANK', 'BANK') AND v_authorisation_ready_transfer_count <= 0 THEN 'RESOLVE_BLOCKERS'
    ELSE 'START_AUTHORISATION'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'ready', v_ready,
    'ready_flag', v_ready,
    'blocker_count', v_blocker_count,
    'warning_count', v_warning_count,
    'blockers', v_blockers_json,
    'warnings', v_warnings_json,
    'next_required_phase', v_next_required_phase,
    'execution_summary', v_summary_json,
    'batch_status', v_batch_row.status,
    'execution_commit_state', v_execution_commit_state,
    'execution_mode', v_execution_mode,
    'pay_channel_scope', v_pay_channel_scope,
    'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
    'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
    'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
    'scoped_scope_pending_count', COALESCE(v_scoped_scope_pending_count, 0),
    'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
    'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
    'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
    'all_scoped_operation_scopes_authorisation_ready', COALESCE(v_all_scoped_operation_scopes_authorisation_ready, false),
    'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
    'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
    'unattempted_submit_eligible_transfer_count', COALESCE(v_unattempted_submit_eligible_transfer_count, 0),
    'remaining_unattempted_submit_required', COALESCE(v_remaining_unattempted_submit_required, 0),
    'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
    'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
    'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
    'unsafe_transfer_count', COALESCE(v_unsafe_transfer_count, 0),
    'scoped_failed_or_blocked_transfer_count', COALESCE(v_scoped_failed_or_blocked_transfer_count, 0),
    'scoped_blocked_transfer_count', COALESCE(v_scoped_blocked_transfer_count, 0),
    'evidence_pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
    'freshness', jsonb_build_object(
      'freshness_validation_status', v_batch_freshness_status,
      'freshness_result_hash', v_batch_freshness_hash,
      'freshness_scope_hash', v_batch_freshness_scope_hash,
      'freshness_operation_id', CASE WHEN v_batch_row.freshness_operation_id IS NULL THEN NULL ELSE v_batch_row.freshness_operation_id::text END,
      'expected_freshness_result_hash', v_expected_freshness_hash,
      'freshness_result_json', v_batch_freshness_json
    ),
    'schedule_state', coalesce(v_summary_json->'schedule_state', '{}'::jsonb),
    'authorisation_state', coalesce(v_summary_json->'authorisation_state', '{}'::jsonb),
    'blocked_funds_state', coalesce(v_summary_json->'blocked_funds_state', '{}'::jsonb),
    'settlement_state', coalesce(v_summary_json->'settlement_state', '{}'::jsonb),
    'remittance_state', coalesce(v_summary_json->'remittance_state', '{}'::jsonb),
    'server_utc', v_now
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_batch_mark_blocked_funds(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_funds_check_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch record;
  v_now timestamptz := now();
  v_funds_check_json jsonb := '{}'::jsonb;
  v_submission_evidence jsonb := '{}'::jsonb;
  v_reservation_status_summary jsonb := '[]'::jsonb;
  v_authoritative_payment_date date := NULL::date;
  v_authoritative_payment_date_source text := NULL::text;
  v_active_item_count integer := 0;
  v_required_gbp_text text := NULL::text;
  v_available_gbp_text text := NULL::text;
  v_funding_account_ref text := NULL::text;
  v_rail_provider text := NULL::text;
  v_rail_env text := NULL::text;
  v_alert_payload jsonb := '{}'::jsonb;
  v_alert_fingerprint text := NULL::text;
  v_notice_result jsonb := '{}'::jsonb;
  v_current_operation_id_text text := NULL::text;
  v_current_operation_id uuid := NULL::uuid;
  v_cancelled_auth_request_ids jsonb := '[]'::jsonb;
  v_auth_requests_cancelled integer := 0;
  v_auth_tokens_voided integer := 0;
  v_transfer_scope_rows_skipped integer := 0;
  v_item_links_cleared integer := 0;
  v_transfer_rows_deleted integer := 0;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: actor_user_id is required';
  END IF;

  IF p_funds_check_json IS NOT NULL AND COALESCE(jsonb_typeof(p_funds_check_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: funds_check_json must be a JSON object';
  END IF;

  v_funds_check_json := COALESCE(p_funds_check_json, '{}'::jsonb);

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.authoritative_payment_date,
    public.pay_batches.authoritative_payment_date_source,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref,
    public.pay_batches.execution_committed_at_utc,
    public.pay_batches.rail_provider_snapshot,
    public.pay_batches.rail_env_snapshot,
    public.pay_batches.funding_account_ref,
    public.pay_batches.pay_date,
    public.pay_batches.bulk_reference,
    public.pay_batches.execution_intent_json
  INTO v_batch
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id
  FOR UPDATE;

  IF v_batch.id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_batch not found';
  END IF;

  IF upper(btrim(coalesce(v_batch.status, ''))) NOT IN ('DRAFT', 'READY', 'SCHEDULED', 'EXECUTING', 'AUTHORISED_FOR_PAYMENT', 'BLOCKED_FUNDS') THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch status must be DRAFT, READY, SCHEDULED, EXECUTING, AUTHORISED_FOR_PAYMENT or BLOCKED_FUNDS (current=%)', v_batch.status;
  END IF;

  IF upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED'))) <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has already crossed execution commit boundary (execution_commit_state=%)', v_batch.execution_commit_state;
  END IF;

  IF nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '') IS NOT NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has execution_commit_ref and cannot be marked blocked funds safely';
  END IF;

  IF v_batch.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: batch has execution_committed_at_utc and cannot be marked blocked funds safely';
  END IF;

  v_current_operation_id_text := NULLIF(BTRIM(COALESCE(v_batch.execution_intent_json ->> 'operation_id', '')), '');

  IF v_current_operation_id_text IS NOT NULL THEN
    IF v_current_operation_id_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'pay_batch_mark_blocked_funds: execution_intent_json.operation_id is not a valid uuid';
    END IF;

    v_current_operation_id := v_current_operation_id_text::uuid;
  END IF;

  v_submission_evidence := public.pay_batch_submission_evidence(p_pay_batch_id);

  IF COALESCE((v_submission_evidence ->> 'transfer_event_count')::integer, 0) <> 0 THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: pay_bank_transfer_events exist for this batch and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_provider_attempt_request_or_idempotency_reference')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: provider-attempt request or idempotency evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_possible_provider_attempt_evidence')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: possible provider-attempt evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'has_external_submission_evidence')::boolean, false) <> false THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: transfer/provider evidence exists and the blocked-funds pre-submission path is unsafe';
  END IF;

  IF COALESCE((v_submission_evidence ->> 'no_submission_evidence')::boolean, false) <> true THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: no-submission evidence check failed and the blocked-funds pre-submission path is unsafe';
  END IF;

  SELECT count(*)::integer
  INTO v_active_item_count
  FROM public.pay_batch_candidates
  JOIN public.pay_batch_items
    ON public.pay_batch_items.pay_batch_candidate_id = public.pay_batch_candidates.id
  WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
    AND COALESCE(public.pay_batch_items.is_voided, false) = false;

  IF COALESCE(v_active_item_count, 0) <= 0 THEN
    RAISE EXCEPTION 'pay_batch_mark_blocked_funds: no active frozen batch items exist for this batch';
  END IF;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_mark_blocked_cancelled_auth_requests (
    auth_request_id uuid PRIMARY KEY
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_mark_blocked_cancelled_auth_requests;

  WITH cancelled_auth_requests AS (
    UPDATE public.pay_batch_auth_requests AS auth_request_to_cancel
    SET
      state = 'CANCELLED',
      finalised_at_utc = COALESCE(auth_request_to_cancel.finalised_at_utc, v_now),
      finalised_by_user_id = COALESCE(auth_request_to_cancel.finalised_by_user_id, p_actor_user_id),
      execution_intent_json = jsonb_strip_nulls(
        COALESCE(auth_request_to_cancel.execution_intent_json, '{}'::jsonb)
        || jsonb_build_object(
          'cancelled_by_blocked_funds', true,
          'blocked_funds_at_utc', v_now::text,
          'blocked_funds_by_user_id', p_actor_user_id::text,
          'blocked_funds_operation_id', CASE WHEN v_current_operation_id IS NULL THEN NULL ELSE v_current_operation_id::text END
        )
      )
    WHERE auth_request_to_cancel.pay_batch_id = p_pay_batch_id
      AND upper(btrim(coalesce(auth_request_to_cancel.state, ''))) IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
      AND (
        v_current_operation_id IS NULL
        OR NULLIF(BTRIM(COALESCE(auth_request_to_cancel.execution_intent_json ->> 'operation_id', '')), '') IS NULL
        OR NULLIF(BTRIM(COALESCE(auth_request_to_cancel.execution_intent_json ->> 'operation_id', '')), '') = v_current_operation_id::text
      )
    RETURNING auth_request_to_cancel.id
  )
  INSERT INTO pg_temp.tmp_mark_blocked_cancelled_auth_requests (auth_request_id)
  SELECT cancelled_auth_requests.id
  FROM cancelled_auth_requests
  ON CONFLICT DO NOTHING;

  SELECT COUNT(*)::integer,
         COALESCE(jsonb_agg(to_jsonb(cancelled_auth_request.auth_request_id::text) ORDER BY cancelled_auth_request.auth_request_id), '[]'::jsonb)
  INTO v_auth_requests_cancelled,
       v_cancelled_auth_request_ids
  FROM pg_temp.tmp_mark_blocked_cancelled_auth_requests AS cancelled_auth_request;

  WITH voided_tokens AS (
    UPDATE public.pay_batch_auth_tokens AS auth_token_to_void
    SET
      used_at_utc = COALESCE(auth_token_to_void.used_at_utc, v_now),
      expires_at_utc = CASE
        WHEN auth_token_to_void.expires_at_utc IS NULL THEN v_now
        WHEN auth_token_to_void.expires_at_utc > v_now THEN v_now
        ELSE auth_token_to_void.expires_at_utc
      END
    FROM pg_temp.tmp_mark_blocked_cancelled_auth_requests AS cancelled_auth_request
    WHERE auth_token_to_void.auth_request_id = cancelled_auth_request.auth_request_id
      AND (
        auth_token_to_void.used_at_utc IS NULL
        OR auth_token_to_void.expires_at_utc IS NULL
        OR auth_token_to_void.expires_at_utc > v_now
      )
    RETURNING auth_token_to_void.token
  )
  SELECT COUNT(*)::integer
  INTO v_auth_tokens_voided
  FROM voided_tokens;

  v_authoritative_payment_date := v_batch.authoritative_payment_date;
  v_authoritative_payment_date_source := v_batch.authoritative_payment_date_source;

  v_required_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{required_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{required_amount}'), '')
  );

  v_available_gbp_text := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{available_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount_gbp}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{available_amount}'), '')
  );

  v_funding_account_ref := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{funding_account_ref}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{account_ref}'), ''),
    NULLIF(BTRIM(v_batch.funding_account_ref), '')
  );

  v_rail_provider := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_provider}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{provider}'), ''),
    NULLIF(BTRIM(v_batch.rail_provider_snapshot), '')
  );

  v_rail_env := COALESCE(
    NULLIF(BTRIM(v_funds_check_json #>> '{rail_env}'), ''),
    NULLIF(BTRIM(v_funds_check_json #>> '{env}'), ''),
    NULLIF(BTRIM(v_batch.rail_env_snapshot), '')
  );

  IF v_current_operation_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_transfer_scope AS scope_to_skip
    SET
      status = 'SKIPPED',
      pay_bank_transfer_id = NULL,
      updated_at_utc = v_now
    WHERE scope_to_skip.pay_batch_id = p_pay_batch_id
      AND scope_to_skip.operation_id = v_current_operation_id
      AND upper(btrim(coalesce(scope_to_skip.status, ''))) IN ('PENDING', 'PREPARED')
      AND scope_to_skip.pay_bank_transfer_id IS NOT NULL;

    GET DIAGNOSTICS v_transfer_scope_rows_skipped = ROW_COUNT;
  END IF;

  UPDATE public.pay_batch_items AS batch_item_to_unlink
  SET pay_bank_transfer_id = NULL
  FROM public.pay_batch_candidates AS batch_candidate_to_unlink
  WHERE batch_candidate_to_unlink.id = batch_item_to_unlink.pay_batch_candidate_id
    AND batch_candidate_to_unlink.pay_batch_id = p_pay_batch_id
    AND batch_item_to_unlink.pay_bank_transfer_id IS NOT NULL;

  GET DIAGNOSTICS v_item_links_cleared = ROW_COUNT;

  DELETE FROM public.pay_bank_transfers AS transfer_to_delete
  WHERE transfer_to_delete.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_transfer_rows_deleted = ROW_COUNT;

  CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_mark_blocked_rewound_reservations (
    reservation_id uuid NOT NULL,
    finance_case_id uuid NOT NULL,
    finance_component_id uuid NULL,
    previous_status text NOT NULL,
    previous_committed_at_utc timestamptz NULL,
    reserved_amount numeric NULL,
    repayment_week_start date NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_mark_blocked_rewound_reservations;

  INSERT INTO pg_temp.tmp_mark_blocked_rewound_reservations (
    reservation_id,
    finance_case_id,
    finance_component_id,
    previous_status,
    previous_committed_at_utc,
    reserved_amount,
    repayment_week_start
  )
  SELECT
    public.pay_advance_reservations.id,
    public.pay_advance_reservations.finance_case_id,
    public.pay_advance_reservations.finance_component_id,
    upper(coalesce(public.pay_advance_reservations.status, '')),
    public.pay_advance_reservations.committed_at_utc,
    public.pay_advance_reservations.reserved_amount,
    public.pay_advance_reservations.repayment_week_start
  FROM public.pay_advance_reservations
  WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(public.pay_advance_reservations.status, '')) = 'COMMITTED'
    AND public.pay_advance_reservations.settled_at_utc IS NULL
    AND public.pay_advance_reservations.released_at_utc IS NULL;

  UPDATE public.pay_advance_reservations AS reservation_to_rewind
  SET
    status = 'RESERVED',
    committed_at_utc = NULL,
    updated_by_user_id = p_actor_user_id
  WHERE reservation_to_rewind.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(reservation_to_rewind.status, '')) = 'COMMITTED'
    AND reservation_to_rewind.settled_at_utc IS NULL
    AND reservation_to_rewind.released_at_utc IS NULL;

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    finance_component_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    rewound_reservation.finance_case_id,
    'RESERVATION_REWOUND_TO_RESERVED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    rewound_reservation.reservation_id,
    rewound_reservation.finance_component_id,
    jsonb_build_object(
      'reservation_status', rewound_reservation.previous_status,
      'committed_at_utc', rewound_reservation.previous_committed_at_utc,
      'reserved_amount', rewound_reservation.reserved_amount,
      'repayment_week_start', rewound_reservation.repayment_week_start,
      'batch_status', v_batch.status,
      'execution_commit_state', v_batch.execution_commit_state
    ),
    jsonb_build_object(
      'reservation_status', 'RESERVED',
      'committed_at_utc', NULL,
      'reserved_amount', rewound_reservation.reserved_amount,
      'repayment_week_start', rewound_reservation.repayment_week_start,
      'batch_status', 'BLOCKED_FUNDS',
      'execution_commit_state', 'NOT_SUBMITTED',
      'repair_reason', 'blocked_funds_pre_submission_reservation_rewind'
    ),
    'blocked_funds_pre_submission_reservation_rewind',
    'Blocked funds before provider submission: local finance reservation rewound from COMMITTED to RESERVED.'
  FROM pg_temp.tmp_mark_blocked_rewound_reservations AS rewound_reservation;

  UPDATE public.pay_batches AS blocked_batch
  SET
    status = 'BLOCKED_FUNDS',
    last_funds_check_at_utc = v_now,
    last_funds_check_json = v_funds_check_json,
    schedule_kind = NULL,
    scheduled_at_utc = NULL,
    scheduled_by_user_id = NULL,
    execution_intent_json = jsonb_strip_nulls(
      COALESCE(blocked_batch.execution_intent_json, '{}'::jsonb)
      || jsonb_build_object(
        'blocked_funds', true,
        'blocked_funds_at_utc', v_now::text,
        'blocked_funds_by_user_id', p_actor_user_id::text,
        'blocked_funds_operation_id', CASE WHEN v_current_operation_id IS NULL THEN NULL ELSE v_current_operation_id::text END,
        'blocked_funds_auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
        'blocked_funds_cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb)
      )
    )
  WHERE blocked_batch.id = p_pay_batch_id;

  v_alert_payload := public.banking_alert_payload_for_pay_batch('BLOCKED_FUNDS', p_pay_batch_id);

  v_alert_fingerprint := public.banking_alert_fingerprint(
    'BLOCKED_FUNDS',
    'pay_batch',
    p_pay_batch_id,
    v_alert_payload
  );

  v_alert_payload := v_alert_payload || jsonb_build_object('alert_fingerprint', v_alert_fingerprint);

  v_notice_result := public.pay_payment_return_admin_notice_queue(
    'BLOCKED_FUNDS',
    p_pay_batch_id,
    v_rail_provider,
    NULL::text,
    v_alert_payload || jsonb_build_object(
      'pay_date', CASE WHEN v_batch.pay_date IS NULL THEN NULL ELSE v_batch.pay_date::text END,
      'bulk_reference', v_batch.bulk_reference,
      'status', 'BLOCKED_FUNDS'
    )
  );

  INSERT INTO public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  SELECT
    public.pay_advance_reservations.finance_case_id,
    'FUNDS_BLOCKED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    public.pay_advance_reservations.id,
    jsonb_build_object(
      'reservation_status', public.pay_advance_reservations.status,
      'authoritative_payment_date', v_authoritative_payment_date,
      'authoritative_payment_date_source', v_authoritative_payment_date_source
    ),
    jsonb_build_object(
      'reservation_status', public.pay_advance_reservations.status,
      'batch_status', 'BLOCKED_FUNDS',
      'authoritative_payment_date', v_authoritative_payment_date,
      'authoritative_payment_date_source', v_authoritative_payment_date_source,
      'banking_alert_fingerprint', v_alert_fingerprint
    ),
    'funds_blocked',
    NULL::text
  FROM public.pay_advance_reservations
  WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
    AND upper(coalesce(public.pay_advance_reservations.status, '')) IN ('RESERVED', 'COMMITTED');

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'status', reservation_summary.reservation_status,
        'count', reservation_summary.reservation_count,
        'amount', reservation_summary.reservation_amount
      )
      ORDER BY reservation_summary.reservation_status
    ),
    '[]'::jsonb
  )
  INTO v_reservation_status_summary
  FROM (
    SELECT
      upper(coalesce(public.pay_advance_reservations.status, '')) AS reservation_status,
      count(*)::integer AS reservation_count,
      round(coalesce(sum(public.pay_advance_reservations.reserved_amount), 0), 2) AS reservation_amount
    FROM public.pay_advance_reservations
    WHERE public.pay_advance_reservations.pay_batch_id = p_pay_batch_id
      AND upper(coalesce(public.pay_advance_reservations.status, '')) IN ('RESERVED', 'COMMITTED')
    GROUP BY upper(coalesce(public.pay_advance_reservations.status, ''))
  ) AS reservation_summary;

  BEGIN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_MARK_BLOCKED_FUNDS:OK',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'status', 'BLOCKED_FUNDS',
        'authoritative_payment_date', v_authoritative_payment_date,
        'authoritative_payment_date_source', v_authoritative_payment_date_source,
        'reservation_status_summary', v_reservation_status_summary,
        'funds_check_json', v_funds_check_json,
        'submission_evidence', v_submission_evidence,
        'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
        'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
        'transfer_scope_rows_skipped', COALESCE(v_transfer_scope_rows_skipped, 0),
        'item_links_cleared', COALESCE(v_item_links_cleared, 0),
        'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
        'banking_alert_fingerprint', v_alert_fingerprint,
        'admin_notice_result', v_notice_result
      ),
      'pay_batches',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'status', 'BLOCKED_FUNDS',
    'last_funds_check_at_utc', v_now::text,
    'last_funds_check_json', v_funds_check_json,
    'authoritative_payment_date', CASE WHEN v_authoritative_payment_date IS NULL THEN NULL ELSE v_authoritative_payment_date::text END,
    'authoritative_payment_date_source', v_authoritative_payment_date_source,
    'reservation_status_summary', v_reservation_status_summary,
    'submission_evidence', v_submission_evidence,
    'auth_requests_cancelled', COALESCE(v_auth_requests_cancelled, 0),
    'cancelled_auth_request_ids', COALESCE(v_cancelled_auth_request_ids, '[]'::jsonb),
    'auth_tokens_voided', COALESCE(v_auth_tokens_voided, 0),
    'transfer_scope_rows_skipped', COALESCE(v_transfer_scope_rows_skipped, 0),
    'item_links_cleared', COALESCE(v_item_links_cleared, 0),
    'transfer_rows_deleted', COALESCE(v_transfer_rows_deleted, 0),
    'banking_alert_kind', 'BLOCKED_FUNDS',
    'banking_alert_fingerprint', v_alert_fingerprint,
    'banking_alert_payload', v_alert_payload,
    'blocked_funds_required_gbp', v_required_gbp_text,
    'blocked_funds_available_gbp', v_available_gbp_text,
    'blocked_funds_provider', v_rail_provider,
    'blocked_funds_env', v_rail_env,
    'blocked_funds_account_ref', v_funding_account_ref,
    'admin_notice_result', v_notice_result
  );
END;
$function$;









create or replace function public.pay_export_bank_csv(
  p_pay_batch_id uuid,
  p_scope text default 'ALL'
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));

  v_default_cols jsonb := '["payment_reference","payee_name","sort_code","account_number","account_type","amount"]'::jsonb;
  v_cols_json jsonb;
  v_cols text[];
  v_col text;

  v_allowed_cols text[] := array[
    'transfer_id',
    'payment_reference',
    'payee_name',
    'sort_code',
    'account_number',
    'account_type',
    'amount',
    'currency',
    'pay_channel',
    'rail_provider',
    'rail_env',
    'request_id',
    'transfer_group_key',
    'grouping_mode_used',
    'week_ending_bucket',
    'candidate_id',
    'umbrella_id',
    'payee_entity_kind',
    'payee_entity_id',
    'bank_details_hash_snapshot'
  ];

  v_format_json jsonb := '{}'::jsonb;
  v_headers_json jsonb := '{}'::jsonb;
  v_include_header boolean := true;
  v_delimiter text := ',';
  v_line_ending text := E'\n';
  v_line_ending_key text := 'LF';
  v_quote_mode text := 'MINIMAL';
  v_bom boolean := false;
  v_sort_code_format text := 'AS_STORED';
  v_account_number_format text := 'AS_STORED';
  v_amount_decimals int := 2;
  v_empty_value text := '';

  v_header text := '';
  v_body text := '';
  v_csv text := '';

  v_missing_count int := 0;
  v_row_count int := 0;

  v_hdr_part text;
  v_hdr_override text;
  v_val text;
  v_line text;
  v_digits text;

  v_batch_created_by_user_id uuid := null;
  v_batch_status text := null;
  v_cancelled_at_utc timestamptz := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;
  v_pre_execution_export boolean := false;
  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  r record;
begin
  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_export_bank_csv: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  select
    pb.created_by_user_id,
    upper(btrim(coalesce(pb.status, ''))),
    pb.cancelled_at_utc,
    upper(btrim(coalesce(pb.execution_commit_state, 'NOT_SUBMITTED'))),
    nullif(btrim(coalesce(pb.execution_commit_ref, '')), ''),
    pb.execution_committed_at_utc,
    upper(btrim(coalesce(pb.freshness_validation_status, ''))),
    nullif(btrim(coalesce(pb.freshness_result_hash, '')), ''),
    nullif(btrim(coalesce(pb.freshness_scope_hash, '')), ''),
    coalesce(pb.freshness_result_json, '{}'::jsonb)
  into
    v_batch_created_by_user_id,
    v_batch_status,
    v_cancelled_at_utc,
    v_execution_commit_state,
    v_execution_commit_ref,
    v_execution_committed_at_utc,
    v_freshness_validation_status,
    v_freshness_result_hash,
    v_freshness_scope_hash,
    v_freshness_result_json
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if not found then
    raise exception 'pay_export_bank_csv: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;

  v_pre_execution_export := (
    v_cancelled_at_utc is null
    and v_batch_status not in ('CANCELLED', 'CANCELED')
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id,
        coalesce(v_batch_created_by_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
        false
      );
      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_EXPORT_BANK_CSV',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_export_bank_csv: chunked freshness validation is required before payment-initiation export' else 'pay_export_bank_csv: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  -- Load configured CSV column order and formatting.
  -- Column inclusion/order remains controlled by pay_export_csv_columns_json.
  -- Formatting/header behaviour is controlled by pay_export_csv_format_json.
  select
    sd.pay_export_csv_columns_json,
    coalesce(sd.pay_export_csv_format_json, '{}'::jsonb)
  into
    v_cols_json,
    v_format_json
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_cols_json is null or jsonb_typeof(v_cols_json) <> 'array' or jsonb_array_length(v_cols_json) = 0 then
    v_cols_json := v_default_cols;
  end if;

  if v_format_json is null or jsonb_typeof(v_format_json) <> 'object' then
    v_format_json := '{}'::jsonb;
  end if;

  if (v_format_json ? 'headers') and jsonb_typeof(v_format_json->'headers') = 'object' then
    v_headers_json := v_format_json->'headers';
  else
    v_headers_json := '{}'::jsonb;
  end if;

  if v_format_json ? 'include_header' then
    begin
      v_include_header := coalesce((v_format_json->>'include_header')::boolean, true);
    exception when others then
      v_include_header := true;
    end;
  end if;

  if v_format_json ? 'bom' then
    begin
      v_bom := coalesce((v_format_json->>'bom')::boolean, false);
    exception when others then
      v_bom := false;
    end;
  end if;

  v_delimiter := coalesce(nullif(v_format_json->>'delimiter', ''), ',');
  if upper(v_delimiter) = 'TAB' then
    v_delimiter := E'\t';
  elsif v_delimiter = '\\t' then
    v_delimiter := E'\t';
  elsif v_delimiter not in (',',';','|',E'\t') then
    v_delimiter := ',';
  end if;

  v_line_ending_key := upper(coalesce(nullif(v_format_json->>'line_ending', ''), 'LF'));
  if v_line_ending_key = 'CRLF' then
    v_line_ending := E'\r\n';
  else
    v_line_ending := E'\n';
  end if;

  v_quote_mode := upper(coalesce(nullif(v_format_json->>'quote_mode', ''), 'MINIMAL'));
  if v_quote_mode not in ('MINIMAL','ALL') then
    v_quote_mode := 'MINIMAL';
  end if;

  v_sort_code_format := upper(coalesce(nullif(v_format_json->>'sort_code_format', ''), 'AS_STORED'));
  if v_sort_code_format not in ('AS_STORED','DIGITS','HYPHENATED') then
    v_sort_code_format := 'AS_STORED';
  end if;

  v_account_number_format := upper(coalesce(nullif(v_format_json->>'account_number_format', ''), 'AS_STORED'));
  if v_account_number_format not in ('AS_STORED','DIGITS') then
    v_account_number_format := 'AS_STORED';
  end if;

  if v_format_json ? 'amount_decimals' then
    begin
      v_amount_decimals := greatest(0, least(4, (v_format_json->>'amount_decimals')::int));
    exception when others then
      v_amount_decimals := 2;
    end;
  end if;

  v_empty_value := coalesce(v_format_json->>'empty_value', '');

  select coalesce(array_agg(t.col order by t.ord), array[]::text[])
  into v_cols
  from jsonb_array_elements_text(v_cols_json) with ordinality as t(col, ord);

  if array_length(v_cols, 1) is null or array_length(v_cols, 1) = 0 then
    v_cols := array['payment_reference','payee_name','sort_code','account_number','account_type','amount']::text[];
  end if;

  -- Validate column keys: must be from allowed set.
  foreach v_col in array v_cols loop
    if v_col is null or btrim(v_col) = '' then
      raise exception 'pay_export_bank_csv: export columns contain an empty key';
    end if;

    if not (v_col = any(v_allowed_cols)) then
      raise exception 'pay_export_bank_csv: invalid export column "%". Allowed=%', v_col, array_to_string(v_allowed_cols, ',');
    end if;
  end loop;

  -- Reject duplicates (deterministic export).
  if (
    select count(*)::int
    from unnest(v_cols) x
  ) <> (
    select count(distinct x)::int
    from unnest(v_cols) x
  ) then
    raise exception 'pay_export_bank_csv: duplicate column keys in pay_export_csv_columns_json';
  end if;

  -- Ensure required snapshot fields exist for all exportable transfers in scope, but only for fields actually exported.
  -- Pre-execution payment-initiation export is limited to PENDING transfers.
  -- Post-execution/cancelled historical re-download uses materialised frozen transfer rows and does not block on current freshness.
  select count(*)::int
  into v_missing_count
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or pbt.pay_channel = v_scope)
    and (
      (v_pre_execution_export = true and upper(coalesce(pbt.status,'')) = 'PENDING')
      or (v_pre_execution_export = false and upper(coalesce(pbt.status,'')) <> 'BLOCKED')
    )
    and (
      (array_position(v_cols,'payment_reference') is not null and pbt.payment_reference is null)
      or (array_position(v_cols,'payee_name') is not null and pbt.payee_name is null)
      or (array_position(v_cols,'sort_code') is not null and pbt.sort_code is null)
      or (array_position(v_cols,'account_number') is not null and pbt.account_number is null)
      or (array_position(v_cols,'account_type') is not null and pbt.account_type is null)
      or (array_position(v_cols,'amount') is not null and pbt.amount is null)
      or (array_position(v_cols,'currency') is not null and pbt.currency is null)
      or (array_position(v_cols,'pay_channel') is not null and pbt.pay_channel is null)
      or (array_position(v_cols,'rail_provider') is not null and pbt.rail_provider is null)
      or (array_position(v_cols,'rail_env') is not null and pbt.rail_env is null)
      or (array_position(v_cols,'request_id') is not null and pbt.request_id is null)
      or (array_position(v_cols,'transfer_group_key') is not null and pbt.transfer_group_key is null)
      or (array_position(v_cols,'grouping_mode_used') is not null and pbt.grouping_mode_used is null)
      or (array_position(v_cols,'week_ending_bucket') is not null and pbt.week_ending_bucket is null)
      or (array_position(v_cols,'candidate_id') is not null and pbt.candidate_id is null)
      or (array_position(v_cols,'umbrella_id') is not null and pbt.umbrella_id is null)
      or (array_position(v_cols,'payee_entity_kind') is not null and pbt.payee_entity_kind is null)
      or (array_position(v_cols,'payee_entity_id') is not null and pbt.payee_entity_id is null)
      or (array_position(v_cols,'bank_details_hash_snapshot') is not null and pbt.bank_details_hash_snapshot is null)
    );

  if v_missing_count > 0 then
    raise exception 'pay_export_bank_csv: % exportable transfer(s) missing one or more required fields for the configured export. Execute-bank must populate these first.', v_missing_count;
  end if;

  -- If no rows, raise to avoid silent empty file.
  select count(*)::int
  into v_row_count
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or pbt.pay_channel = v_scope)
    and (
      (v_pre_execution_export = true and upper(coalesce(pbt.status,'')) = 'PENDING')
      or (v_pre_execution_export = false and upper(coalesce(pbt.status,'')) <> 'BLOCKED')
    );

  if v_row_count = 0 then
    raise exception 'pay_export_bank_csv: no exportable transfers found for batch % (scope=%).', p_pay_batch_id, v_scope;
  end if;

  -- Build header from configured columns and optional user overrides.
  v_header := '';
  if v_include_header = true then
    foreach v_col in array v_cols loop
      v_hdr_part := case v_col
        when 'transfer_id' then 'Transfer id'
        when 'payment_reference' then 'Payment reference'
        when 'payee_name' then 'Payee name'
        when 'sort_code' then 'Sort code'
        when 'account_number' then 'Bank account number'
        when 'account_type' then 'Bank account type'
        when 'amount' then 'Amount'
        when 'currency' then 'Currency'
        when 'pay_channel' then 'Channel'
        when 'rail_provider' then 'Rail provider'
        when 'rail_env' then 'Rail env'
        when 'request_id' then 'Request id'
        when 'transfer_group_key' then 'Transfer group key'
        when 'grouping_mode_used' then 'Grouping mode'
        when 'week_ending_bucket' then 'Week ending'
        when 'candidate_id' then 'Candidate id'
        when 'umbrella_id' then 'Umbrella id'
        when 'payee_entity_kind' then 'Payee entity kind'
        when 'payee_entity_id' then 'Payee entity id'
        when 'bank_details_hash_snapshot' then 'Bank details hash'
        else initcap(replace(v_col, '_', ' '))
      end;

      v_hdr_override := nullif(btrim(coalesce(v_headers_json->>v_col, '')), '');
      if v_hdr_override is not null then
        v_hdr_part := v_hdr_override;
      end if;

      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_hdr_part) > 0
        or position('"' in v_hdr_part) > 0
        or position(E'\r' in v_hdr_part) > 0
        or position(E'\n' in v_hdr_part) > 0
      then
        v_hdr_part := '"' || replace(v_hdr_part, '"', '""') || '"';
      end if;

      if v_header = '' then
        v_header := v_hdr_part;
      else
        v_header := v_header || v_delimiter || v_hdr_part;
      end if;
    end loop;
  end if;

  -- Build rows.
  v_body := '';
  for r in
    select
      pbt.id as transfer_id,
      pbt.payment_reference,
      pbt.payee_name,
      pbt.sort_code,
      pbt.account_number,
      pbt.account_type,
      pbt.amount,
      pbt.currency,
      pbt.pay_channel,
      pbt.rail_provider,
      pbt.rail_env,
      pbt.request_id,
      pbt.transfer_group_key,
      pbt.grouping_mode_used,
      pbt.week_ending_bucket,
      pbt.candidate_id,
      pbt.umbrella_id,
      pbt.payee_entity_kind,
      pbt.payee_entity_id,
      pbt.bank_details_hash_snapshot
    from public.pay_bank_transfers pbt
    where pbt.pay_batch_id = p_pay_batch_id
      and (v_scope = 'ALL' or pbt.pay_channel = v_scope)
      and (
        (v_pre_execution_export = true and upper(coalesce(pbt.status,'')) = 'PENDING')
        or (v_pre_execution_export = false and upper(coalesce(pbt.status,'')) <> 'BLOCKED')
      )
    order by pbt.id
  loop
    v_line := '';

    foreach v_col in array v_cols loop
      v_val := null;

      if v_col = 'transfer_id' then
        v_val := r.transfer_id::text;
      elsif v_col = 'payment_reference' then
        v_val := r.payment_reference;
      elsif v_col = 'payee_name' then
        v_val := r.payee_name;
      elsif v_col = 'sort_code' then
        if v_sort_code_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
        elsif v_sort_code_format = 'HYPHENATED' then
          v_digits := regexp_replace(coalesce(r.sort_code, ''), '[^0-9]', '', 'g');
          if length(v_digits) = 6 then
            v_val := substr(v_digits, 1, 2) || '-' || substr(v_digits, 3, 2) || '-' || substr(v_digits, 5, 2);
          else
            v_val := v_digits;
          end if;
        else
          v_val := r.sort_code;
        end if;
      elsif v_col = 'account_number' then
        if v_account_number_format = 'DIGITS' then
          v_val := regexp_replace(coalesce(r.account_number, ''), '[^0-9]', '', 'g');
        else
          v_val := r.account_number;
        end if;
      elsif v_col = 'account_type' then
        v_val := r.account_type;
      elsif v_col = 'amount' then
        v_val := case v_amount_decimals
          when 0 then to_char(round(r.amount, 0), 'FM9999999990')
          when 1 then to_char(round(r.amount, 1), 'FM9999999990.0')
          when 2 then to_char(round(r.amount, 2), 'FM9999999990.00')
          when 3 then to_char(round(r.amount, 3), 'FM9999999990.000')
          when 4 then to_char(round(r.amount, 4), 'FM9999999990.0000')
          else to_char(round(r.amount, 2), 'FM9999999990.00')
        end;
      elsif v_col = 'currency' then
        v_val := r.currency;
      elsif v_col = 'pay_channel' then
        v_val := r.pay_channel;
      elsif v_col = 'rail_provider' then
        v_val := r.rail_provider;
      elsif v_col = 'rail_env' then
        v_val := r.rail_env;
      elsif v_col = 'request_id' then
        v_val := r.request_id;
      elsif v_col = 'transfer_group_key' then
        v_val := r.transfer_group_key;
      elsif v_col = 'grouping_mode_used' then
        v_val := r.grouping_mode_used;
      elsif v_col = 'week_ending_bucket' then
        v_val := case when r.week_ending_bucket is null then null else r.week_ending_bucket::text end;
      elsif v_col = 'candidate_id' then
        v_val := case when r.candidate_id is null then null else r.candidate_id::text end;
      elsif v_col = 'umbrella_id' then
        v_val := case when r.umbrella_id is null then null else r.umbrella_id::text end;
      elsif v_col = 'payee_entity_kind' then
        v_val := r.payee_entity_kind;
      elsif v_col = 'payee_entity_id' then
        v_val := case when r.payee_entity_id is null then null else r.payee_entity_id::text end;
      elsif v_col = 'bank_details_hash_snapshot' then
        v_val := r.bank_details_hash_snapshot;
      else
        v_val := null;
      end if;

      v_val := coalesce(v_val, v_empty_value);

      -- CSV escaping: quote according to configured quote mode or when field contains delimiter/quote/newline.
      if v_quote_mode = 'ALL'
        or position(v_delimiter in v_val) > 0
        or position('"' in v_val) > 0
        or position(E'\r' in v_val) > 0
        or position(E'\n' in v_val) > 0
      then
        v_val := '"' || replace(v_val, '"', '""') || '"';
      end if;

      if v_line = '' then
        v_line := v_val;
      else
        v_line := v_line || v_delimiter || v_val;
      end if;
    end loop;

    if v_body = '' then
      v_body := v_line;
    else
      v_body := v_body || v_line_ending || v_line;
    end if;
  end loop;

  if v_include_header = true then
    v_csv := v_header || v_line_ending || coalesce(v_body, '');
  else
    v_csv := coalesce(v_body, '');
  end if;

  if v_bom = true then
    v_csv := chr(65279) || v_csv;
  end if;

  return v_csv;
end;
$$;




drop function if exists public.pay_settle_manual_confirm(uuid, text, text, date, uuid);


DROP FUNCTION IF EXISTS public.pay_settle_manual_confirm(uuid, text, text, date, uuid);
DROP FUNCTION IF EXISTS public.pay_settle_manual_confirm(uuid, text, text, date, uuid, text, uuid, boolean, text, boolean);
DROP FUNCTION IF EXISTS public.pay_settle_manual_confirm(uuid, text, text, date, uuid, text, uuid, boolean, text, boolean, uuid, jsonb);

create or replace function public.pay_settle_manual_confirm(
  p_pay_batch_id uuid,
  p_scope text,
  p_bank_confirm_ref text,
  p_payment_date date,
  p_actor_user_id uuid,
  p_settlement_mode text default 'CSV_SETTLEMENT',
  p_auth_request_id uuid default null,
  p_csv_uploaded_confirmed boolean default false,
  p_external_settlement_comment text default null,
  p_suppress_remittances boolean default false,
  p_operation_id uuid default null,
  p_settlement_scope_ids jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(btrim(coalesce(p_scope,'ALL')));
  v_batch record;
  v_auth record;

  v_now timestamptz := now();
  v_settlement_mode text := upper(btrim(coalesce(p_settlement_mode, 'CSV_SETTLEMENT')));
  v_provider text := null;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_bank_confirm_ref text := nullif(btrim(coalesce(p_bank_confirm_ref, '')), '');
  v_external_settlement_comment text := nullif(btrim(coalesce(p_external_settlement_comment, '')), '');

  v_auth_intent jsonb := '{}'::jsonb;
  v_intent_mode text := null;
  v_intent_suppress_remittances boolean := false;
  v_intent_csv_uploaded_confirmed boolean := false;
  v_intent_bank_confirm_ref text := null;
  v_intent_external_comment text := null;
  v_intent_payment_date date := null;
  v_intent_payment_date_raw text := null;
  v_bank_csv_export_json jsonb := null;
  v_bank_csv_export_hash text := null;
  v_current_transfer_hash text := null;

  v_pending_count int := 0;
  v_external_submission_count int := 0;
  v_reservations_committed_count int := 0;
  v_reservations_committed_amount numeric := 0;
  v_settlement_json jsonb := '[]'::jsonb;
  v_settle_result jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_worker_communications jsonb := '{}'::jsonb;
  v_remittance_queue_stage_result jsonb := '{}'::jsonb;
  v_manual_event_ingest_results jsonb := '[]'::jsonb;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_settled_this_chunk integer := 0;
  v_reused_this_chunk integer := 0;
  v_failed_this_chunk integer := 0;
  v_remaining_scope_count integer := 0;
  v_has_more boolean := false;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_settle_manual_confirm: pay_batch_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_settle_manual_confirm: actor_user_id is required';
  end if;
  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_settle_manual_confirm: invalid scope (ALL|PAYE|UMBRELLA)';
  end if;
  if v_settlement_mode not in ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'INVALID_SETTLEMENT_MODE',
      'message', 'pay_settle_manual_confirm: settlement_mode must be CSV_SETTLEMENT or EXTERNAL_SETTLEMENT',
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;
  if p_payment_date is null then
    raise exception 'pay_settle_manual_confirm: payment_date is required';
  end if;

  v_operation_mode := (p_operation_id IS NOT NULL OR p_settlement_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm operation mode requires p_operation_id';
    END IF;
    IF p_settlement_scope_ids IS NULL OR jsonb_typeof(p_settlement_scope_ids) <> 'array' OR jsonb_array_length(p_settlement_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm operation mode requires non-empty p_settlement_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
      RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;

    SELECT pb.*
    INTO v_batch
    FROM public.pay_batches AS pb
    WHERE pb.id = p_pay_batch_id
    FOR UPDATE;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_manual_confirm: pay_batch not found';
    END IF;

    IF v_settlement_mode = 'CSV_SETTLEMENT' AND v_bank_confirm_ref IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_BANK_CONFIRM_REF_REQUIRED',
        'message', 'pay_settle_manual_confirm operation mode requires a bank confirmation reference for CSV settlement.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    IF v_settlement_mode = 'EXTERNAL_SETTLEMENT' AND v_external_settlement_comment IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_REQUIRED',
        'message', 'pay_settle_manual_confirm operation mode requires an external settlement comment.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text
      )::text;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT count(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_settlement_scope_ids) THEN
      RAISE EXCEPTION 'p_settlement_scope_ids contains invalid or duplicate uuid values';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT count(*)::integer,
           count(*) FILTER (WHERE selected_scope.status = 'SETTLED')::integer,
           count(*) FILTER (WHERE selected_scope.status IN ('FAILED', 'SKIPPED'))::integer
    INTO v_matched_scope_count,
         v_reused_this_chunk,
         v_failed_this_chunk
    FROM selected_scope;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'one or more settlement scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), pending_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'PENDING'
      FOR UPDATE OF scope_row
    ), payload_transfer AS (
      SELECT pending_scope.id AS settlement_scope_id,
             CASE
               WHEN COALESCE(pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN (pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
               ELSE NULL::uuid
             END AS pay_bank_transfer_id
      FROM pending_scope
    ), payload_item_ids AS (
      SELECT pending_scope.id AS settlement_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM pending_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pending_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfers AS (
      SELECT DISTINCT pending_scope.id AS settlement_scope_id,
             COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM pending_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = pending_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = pending_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), inserted_events AS (
      INSERT INTO public.pay_bank_transfer_events (
        pay_batch_id,
        pay_bank_transfer_id,
        candidate_id,
        umbrella_id,
        provider_key,
        provider_event_id,
        provider_reference,
        provider_state,
        normalised_state,
        event_source,
        event_time_utc,
        received_at_utc,
        amount,
        currency,
        mapping_status,
        movement_classification,
        correction_disposition,
        raw_payload,
        idempotency_key,
        mapping_method
      )
      SELECT
        p_pay_batch_id,
        scope_transfers.pay_bank_transfer_id,
        bank_transfer.candidate_id,
        bank_transfer.umbrella_id,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.rail_provider, '')), ''), v_settlement_mode),
        'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text,
        COALESCE(v_bank_confirm_ref, 'manual-settlement:' || p_operation_id::text, bank_transfer.payment_reference, bank_transfer.request_id),
        CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_MANUAL_CONFIRM' ELSE 'EXTERNAL_SETTLEMENT_CONFIRM' END,
        'COMPLETED',
        'MANUAL_CONFIRM',
        v_now,
        v_now,
        bank_transfer.amount,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.currency, '')), ''), 'GBP'),
        'MATCHED',
        NULL::text,
        NULL::text,
        jsonb_strip_nulls(jsonb_build_object(
          'source_rpc', 'pay_settle_manual_confirm',
          'operation_id', p_operation_id::text,
          'settlement_scope_id', scope_transfers.settlement_scope_id::text,
          'settlement_mode', v_settlement_mode,
          'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL END,
          'external_settlement_comment', CASE WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL END,
          'payment_date', p_payment_date::text,
          'suppress_remittances', COALESCE(p_suppress_remittances, false)
        )),
        'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text,
        'TRANSFER_ID'
      FROM scope_transfers
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = scope_transfers.pay_bank_transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS existing_event
        WHERE existing_event.pay_batch_id = p_pay_batch_id
          AND existing_event.idempotency_key = 'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text
      )
      RETURNING public.pay_bank_transfer_events.id,
                public.pay_bank_transfer_events.pay_bank_transfer_id,
                public.pay_bank_transfer_events.idempotency_key
    ), existing_events AS (
      SELECT scope_transfers.settlement_scope_id,
             existing_event.id AS event_id
      FROM scope_transfers
      JOIN public.pay_bank_transfer_events AS existing_event
        ON existing_event.pay_batch_id = p_pay_batch_id
       AND existing_event.idempotency_key = 'manual-settlement:' || p_operation_id::text || ':' || scope_transfers.settlement_scope_id::text || ':' || scope_transfers.pay_bank_transfer_id::text
    ), transfer_updates AS (
      UPDATE public.pay_bank_transfers AS transfer_update
      SET status = 'COMPLETED',
          rail_state = CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN 'CSV_MANUAL_CONFIRM' ELSE 'EXTERNAL_SETTLEMENT_CONFIRM' END,
          rail_meta_json = jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
            'settlement_mode', v_settlement_mode,
            'manual_settlement_operation_id', p_operation_id::text,
            'bank_confirm_ref', CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE NULL END,
            'external_settlement_comment', CASE WHEN v_settlement_mode = 'EXTERNAL_SETTLEMENT' THEN v_external_settlement_comment ELSE NULL END,
            'payment_date', p_payment_date::text,
            'settled_at_utc', v_now::text,
            'settled_by_user_id', p_actor_user_id::text
          )),
          completed_at_utc = COALESCE(transfer_update.completed_at_utc, v_now),
          failed_reason = NULL::text
      FROM scope_transfers
      WHERE transfer_update.id = scope_transfers.pay_bank_transfer_id
        AND transfer_update.pay_batch_id = p_pay_batch_id
        AND upper(COALESCE(transfer_update.status, '')) NOT IN ('COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED')
      RETURNING transfer_update.id
    ), event_by_scope AS (
      SELECT existing_events.settlement_scope_id,
             (array_agg(existing_events.event_id ORDER BY existing_events.event_id))[1] AS event_id
      FROM existing_events
      GROUP BY existing_events.settlement_scope_id
    ), failed_scope_no_transfer AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'FAILED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'settlement_failure_code', 'NO_PAY_BANK_TRANSFER_FOR_SCOPE',
            'settlement_failure_message', 'Settlement scope could not be settled because it does not resolve to a frozen pay_bank_transfer row.',
            'failed_at_utc', v_now::text
          )),
          updated_at_utc = v_now
      FROM pending_scope
      WHERE scope_update.id = pending_scope.id
        AND NOT EXISTS (
          SELECT 1
          FROM scope_transfers
          WHERE scope_transfers.settlement_scope_id = pending_scope.id
        )
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id
    ), settled_scope AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'SETTLED',
          settlement_event_id = COALESCE(scope_update.settlement_event_id, event_by_scope.event_id),
          updated_at_utc = v_now
      FROM pending_scope
      JOIN scope_transfers
        ON scope_transfers.settlement_scope_id = pending_scope.id
      LEFT JOIN event_by_scope
        ON event_by_scope.settlement_scope_id = pending_scope.id
      WHERE scope_update.id = pending_scope.id
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id
    ), candidate_complete AS (
      SELECT DISTINCT settled_scope.pay_batch_candidate_id
      FROM settled_scope
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_settlement_scope AS remaining_for_candidate
        WHERE remaining_for_candidate.operation_id = p_operation_id
          AND remaining_for_candidate.pay_batch_id = p_pay_batch_id
          AND remaining_for_candidate.pay_batch_candidate_id = settled_scope.pay_batch_candidate_id
          AND remaining_for_candidate.status NOT IN ('SETTLED', 'SKIPPED')
      )
    ), candidate_updates AS (
      UPDATE public.pay_batch_candidates AS candidate_update
      SET settlement_status = 'SETTLED',
          settled_at_utc = COALESCE(candidate_update.settled_at_utc, v_now),
          settled_via = v_settlement_mode,
          settled_note = COALESCE(candidate_update.settled_note, CASE WHEN v_settlement_mode = 'CSV_SETTLEMENT' THEN v_bank_confirm_ref ELSE v_external_settlement_comment END)
      FROM candidate_complete
      WHERE candidate_update.id = candidate_complete.pay_batch_candidate_id
      RETURNING candidate_update.id
    )
    SELECT
      (SELECT COUNT(*)::integer FROM settled_scope),
      COALESCE(v_failed_this_chunk, 0) + (SELECT COUNT(*)::integer FROM failed_scope_no_transfer)
    INTO v_settled_this_chunk,
         v_failed_this_chunk;

    SELECT COUNT(*)::integer
    INTO v_remaining_scope_count
    FROM public.banking_pay_operation_settlement_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    v_has_more := COALESCE(v_remaining_scope_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
      'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
      'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
      'remaining', COALESCE(v_remaining_scope_count, 0),
      'has_more', v_has_more,
      'remittance_queued', false,
      'message', 'Manual settlement chunk processed; remittance queueing is handled by a separate operation.'
    );
  END IF;

  if p_auth_request_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised auth_request_id is required; use the Execute modal settlement flow',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_MANUAL_CONFIRM_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id,
      'payment_date', p_payment_date::text,
      'suppress_remittances', coalesce(p_suppress_remittances, false)
    ),
    'pay_batches',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.pay_date,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.bank_csv_export_json,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_settle_manual_confirm: pay_batch not found';
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state,
    pbar.execution_intent_json
  into v_auth
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_auth.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_NOT_FOUND',
      'message', 'pay_settle_manual_confirm: auth_request not found',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text
    )::text;
  end if;
  if v_auth.pay_batch_id is distinct from p_pay_batch_id then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_BATCH_MISMATCH',
      'message', 'pay_settle_manual_confirm: auth_request does not belong to this pay batch',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text
    )::text;
  end if;
  if upper(coalesce(v_auth.state,'')) <> 'AUTHORISED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_REQUEST_NOT_AUTHORISED',
      'message', 'pay_settle_manual_confirm: auth_request must be AUTHORISED before settlement can complete',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'auth_state', v_auth.state
    )::text;
  end if;

  if v_auth.execution_intent_json is not null and jsonb_typeof(v_auth.execution_intent_json) = 'object' then
    v_auth_intent := v_auth.execution_intent_json;
  elsif v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_auth_intent := v_batch.execution_intent_json;
  else
    v_auth_intent := '{}'::jsonb;
  end if;

  v_intent_mode := upper(btrim(coalesce(v_auth_intent->>'execution_mode', '')));
  if v_intent_mode <> v_settlement_mode then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_MODE_MISMATCH',
      'message', 'pay_settle_manual_confirm: supplied settlement_mode does not match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_execution_mode', v_intent_mode,
      'requested_settlement_mode', v_settlement_mode
    )::text;
  end if;

  v_intent_payment_date_raw := nullif(btrim(coalesce(v_auth_intent->>'payment_date', '')), '');
  if v_intent_payment_date_raw is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised frozen execution intent must contain a valid payment_date',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', null,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;

  begin
    v_intent_payment_date := v_intent_payment_date_raw::date;
  exception when others then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_REQUIRED',
      'message', 'pay_settle_manual_confirm: authorised frozen execution intent must contain a valid payment_date',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', null,
      'authorised_payment_date_raw', v_intent_payment_date_raw,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end;

  if p_payment_date is distinct from v_intent_payment_date then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'AUTH_INTENT_PAYMENT_DATE_MISMATCH',
      'message', 'pay_settle_manual_confirm: supplied payment_date does not match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_payment_date', v_intent_payment_date::text,
      'requested_payment_date', case when p_payment_date is null then null else p_payment_date::text end,
      'settlement_mode', v_settlement_mode
    )::text;
  end if;

  v_intent_suppress_remittances := lower(btrim(coalesce(v_auth_intent->>'suppress_remittances', 'false'))) in ('true','1','yes','y','on');
  if coalesce(p_suppress_remittances, false) <> v_intent_suppress_remittances then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'SUPPRESS_REMITTANCES_INTENT_MISMATCH',
      'message', 'pay_settle_manual_confirm: suppress_remittances must match the authorised frozen execution intent',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', p_auth_request_id::text,
      'authorised_suppress_remittances', v_intent_suppress_remittances,
      'requested_suppress_remittances', coalesce(p_suppress_remittances, false)
    )::text;
  end if;

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  if upper(coalesce(v_batch.status,'')) in ('COMMITTED','PAID','SETTLED','CANCELLED') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'BATCH_NOT_SETTLEABLE',
      'message', 'pay_settle_manual_confirm: batch status cannot be manually settled',
      'pay_batch_id', p_pay_batch_id::text,
      'status', v_batch.status
    )::text;
  end if;

  if v_execution_commit_state <> 'NOT_SUBMITTED' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'pay_settle_manual_confirm: batch has already crossed the native execution submission boundary',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', v_execution_commit_ref,
      'execution_committed_at_utc', case when v_execution_committed_at_utc is null then null else v_execution_committed_at_utc::text end
    )::text;
  end if;

  v_provider := upper(btrim(coalesce(v_batch.rail_provider_snapshot, '')));
  if v_provider = 'REV' then
    v_provider := 'REVOLUT';
  end if;
  if v_provider = '' then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'MISSING_RAIL_PROVIDER',
      'message', 'pay_settle_manual_confirm: rail_provider_snapshot is required and blank provider is not treated as CSV',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;
  if v_provider not in ('REVOLUT','CSV') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'UNKNOWN_RAIL_PROVIDER',
      'message', 'pay_settle_manual_confirm: unsupported rail_provider_snapshot',
      'pay_batch_id', p_pay_batch_id::text,
      'rail_provider_snapshot', v_batch.rail_provider_snapshot
    )::text;
  end if;

  select count(*)::int
  into v_pending_count
  from public.pay_bank_transfers pbt_pending
  where pbt_pending.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt_pending.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt_pending.status,'')) = 'PENDING';

  if v_pending_count = 0 then
    raise exception 'pay_settle_manual_confirm: no PENDING transfers found for batch % (scope=%)', p_pay_batch_id, v_scope;
  end if;

  select count(*)::int
  into v_external_submission_count
  from public.pay_bank_transfers pbt_ext
  where pbt_ext.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt_ext.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt_ext.status,'')) <> 'BLOCKED'
    and (
      nullif(btrim(coalesce(pbt_ext.rail_tx_id,'')), '') is not null
      or upper(coalesce(pbt_ext.rail_state,'')) in ('SUBMITTED','QUEUED','ACCEPTED','SENT','PROCESSING','IN_FLIGHT','PENDING_SETTLEMENT','PENDING_CONFIRMATION','PENDING_SUBMISSION','COMPLETED','SETTLED','COMMITTED','PAID','EXECUTED')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'submitted','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'queued','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'accepted','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'sent','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'processing','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'completed','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'committed','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'settled','false'))) in ('true','1','yes','y','on')
      or lower(btrim(coalesce(pbt_ext.rail_meta_json->>'paid','false'))) in ('true','1','yes','y','on')
      or coalesce(
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_submission_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'submission_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'external_transfer_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'provider_payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'external_payment_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'transaction_id','')), ''),
        nullif(btrim(coalesce(pbt_ext.rail_meta_json->>'id','')), '')
      ) is not null
    );

  if v_external_submission_count > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_MANUAL_CONFIRM',
      'code', 'EXTERNAL_SUBMISSION_EXISTS',
      'message', 'pay_settle_manual_confirm: non-native settlement cannot complete after native rail submission evidence exists',
      'pay_batch_id', p_pay_batch_id::text,
      'settlement_mode', v_settlement_mode,
      'external_submission_transfer_count', v_external_submission_count
    )::text;
  end if;

  select md5(coalesce(jsonb_agg(
    jsonb_build_object(
      'id', transfer_hash_rows.id,
      'candidate_id', transfer_hash_rows.candidate_id,
      'umbrella_id', transfer_hash_rows.umbrella_id,
      'pay_channel', transfer_hash_rows.pay_channel,
      'amount', transfer_hash_rows.amount,
      'currency', transfer_hash_rows.currency,
      'payment_reference', transfer_hash_rows.payment_reference,
      'payee_name', transfer_hash_rows.payee_name,
      'sort_code_digits', transfer_hash_rows.sort_code_digits,
      'account_number_digits', transfer_hash_rows.account_number_digits,
      'account_type', transfer_hash_rows.account_type,
      'bank_details_hash_snapshot', transfer_hash_rows.bank_details_hash_snapshot,
      'payee_entity_kind', transfer_hash_rows.payee_entity_kind,
      'payee_entity_id', transfer_hash_rows.payee_entity_id,
      'transfer_group_key', transfer_hash_rows.transfer_group_key
    )
    order by transfer_hash_rows.id
  )::text, '[]'))
  into v_current_transfer_hash
  from (
    select
      pbt_hash.id::text as id,
      case when pbt_hash.candidate_id is null then null else pbt_hash.candidate_id::text end as candidate_id,
      case when pbt_hash.umbrella_id is null then null else pbt_hash.umbrella_id::text end as umbrella_id,
      pbt_hash.pay_channel,
      round(pbt_hash.amount, 2) as amount,
      pbt_hash.currency,
      pbt_hash.payment_reference,
      pbt_hash.payee_name,
      regexp_replace(coalesce(pbt_hash.sort_code,''), '[^0-9]', '', 'g') as sort_code_digits,
      regexp_replace(coalesce(pbt_hash.account_number,''), '[^0-9]', '', 'g') as account_number_digits,
      pbt_hash.account_type,
      pbt_hash.bank_details_hash_snapshot,
      pbt_hash.payee_entity_kind,
      case when pbt_hash.payee_entity_id is null then null else pbt_hash.payee_entity_id::text end as payee_entity_id,
      pbt_hash.transfer_group_key
    from public.pay_bank_transfers pbt_hash
    where pbt_hash.pay_batch_id = p_pay_batch_id
      and (v_scope = 'ALL' or upper(coalesce(pbt_hash.pay_channel,'')) = v_scope)
      and upper(coalesce(pbt_hash.status,'')) = 'PENDING'
    order by pbt_hash.id
  ) transfer_hash_rows;

  if v_settlement_mode = 'CSV_SETTLEMENT' then
    v_bank_csv_export_json := v_batch.bank_csv_export_json;
    v_bank_csv_export_hash := nullif(btrim(coalesce(v_bank_csv_export_json->>'transfer_hash', '')), '');
    v_intent_csv_uploaded_confirmed := lower(btrim(coalesce(v_auth_intent->>'csv_uploaded_confirmed', 'false'))) in ('true','1','yes','y','on');
    v_intent_bank_confirm_ref := nullif(btrim(coalesce(v_auth_intent->>'csv_bank_confirm_ref', '')), '');

    if v_bank_csv_export_json is null or jsonb_typeof(v_bank_csv_export_json) <> 'object' or v_bank_csv_export_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_EXPORT_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires a CloudTMS-generated CSV banking file first',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_bank_csv_export_hash <> v_current_transfer_hash then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_REGENERATION_REQUIRED',
        'message', 'pay_settle_manual_confirm: generated CSV evidence does not match current frozen transfer rows',
        'pay_batch_id', p_pay_batch_id::text,
        'csv_export_hash', v_bank_csv_export_hash,
        'current_transfer_hash', v_current_transfer_hash
      )::text;
    end if;
    if coalesce(p_csv_uploaded_confirmed, false) = false or v_intent_csv_uploaded_confirmed = false then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_UPLOAD_CONFIRMATION_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires confirmation that the CloudTMS CSV was uploaded/processed with the bank',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_bank_confirm_ref is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_BANK_CONFIRM_REF_REQUIRED',
        'message', 'pay_settle_manual_confirm: CSV settlement requires a bank confirmation reference',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_intent_bank_confirm_ref is not null and v_bank_confirm_ref <> v_intent_bank_confirm_ref then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'CSV_BANK_CONFIRM_REF_INTENT_MISMATCH',
        'message', 'pay_settle_manual_confirm: supplied bank confirmation reference does not match the authorised frozen intent',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', p_auth_request_id::text
      )::text;
    end if;
  else
    v_intent_external_comment := nullif(btrim(coalesce(v_auth_intent->>'external_settlement_comment', '')), '');
    if v_external_settlement_comment is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_REQUIRED',
        'message', 'pay_settle_manual_confirm: external settlement requires a mandatory comment',
        'pay_batch_id', p_pay_batch_id::text
      )::text;
    end if;
    if v_intent_external_comment is not null and v_external_settlement_comment <> v_intent_external_comment then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_SETTLE_MANUAL_CONFIRM',
        'code', 'EXTERNAL_SETTLEMENT_COMMENT_INTENT_MISMATCH',
        'message', 'pay_settle_manual_confirm: supplied external settlement comment does not match the authorised frozen intent',
        'pay_batch_id', p_pay_batch_id::text,
        'auth_request_id', p_auth_request_id::text
      )::text;
    end if;
  end if;

  v_settlement_confirmation_json := jsonb_strip_nulls(jsonb_build_object(
    'settlement_mode', v_settlement_mode,
    'settled_at_utc', v_now::text,
    'settled_by_user_id', p_actor_user_id::text,
    'payment_date', v_intent_payment_date::text,
    'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
    'external_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
    'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end,
    'suppress_remittances', v_intent_suppress_remittances,
    'remittances_suppressed_at_utc', case when v_intent_suppress_remittances then v_now::text else null end,
    'auth_request_id', p_auth_request_id::text,
    'scope', v_scope,
    'current_transfer_hash', v_current_transfer_hash
  ));

  update public.pay_batches pb2
  set
    authoritative_payment_date = v_intent_payment_date,
    authoritative_payment_date_source = case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_SETTLEMENT_PAYMENT_DATE' else 'EXTERNAL_SETTLEMENT_PAYMENT_DATE' end,
    pay_date = v_intent_payment_date,
    monzo_confirmed_at_utc = v_now,
    monzo_confirmed_by_user_id = p_actor_user_id,
    execution_commit_ref = coalesce(v_bank_confirm_ref, 'external-settlement:' || p_auth_request_id::text, pb2.execution_commit_ref),
    settlement_confirmation_json = coalesce(pb2.settlement_confirmation_json, '{}'::jsonb) || v_settlement_confirmation_json,
    execution_intent_json = coalesce(pb2.execution_intent_json, '{}'::jsonb) || v_auth_intent
  where pb2.id = p_pay_batch_id;

  update public.pay_advance_reservations par
  set
    status = 'COMMITTED',
    committed_at_utc = coalesce(par.committed_at_utc, v_now),
    updated_by_user_id = p_actor_user_id
  from public.pay_batch_items pbi
  where par.pay_batch_id = p_pay_batch_id
    and par.pay_batch_item_id = pbi.id
    and upper(coalesce(par.status,'')) = 'RESERVED'
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  get diagnostics v_reservations_committed_count = row_count;

  select round(coalesce(sum(par.reserved_amount),0),2)
  into v_reservations_committed_amount
  from public.pay_advance_reservations par
  join public.pay_batch_items pbi
    on pbi.id = par.pay_batch_item_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    'RESERVATION_COMMITTED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'RESERVED'),
    jsonb_build_object(
      'reservation_status', 'COMMITTED',
      'authoritative_payment_date', v_intent_payment_date::text,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id::text
    ),
    lower(v_settlement_mode) || '_commit',
    null
  from public.pay_advance_reservations par
  join public.pay_batch_items pbi
    on pbi.id = par.pay_batch_item_id
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'COMMITTED'
    and par.committed_at_utc = v_now
    and (v_scope = 'ALL' or upper(coalesce(pbi.pay_channel,'')) = v_scope);

  if v_bank_confirm_ref is not null then
    update public.pay_batch_items pbi
    set bank_reference = v_bank_confirm_ref
    from public.pay_bank_transfers pbt,
         public.pay_batch_candidates pbc
    where pbt.pay_batch_id = p_pay_batch_id
      and (v_scope = 'ALL' or upper(coalesce(pbt.pay_channel,'')) = v_scope)
      and upper(coalesce(pbt.status,'')) = 'PENDING'
      and pbc.id = pbi.pay_batch_candidate_id
      and pbc.pay_batch_id = p_pay_batch_id
      and pbi.pay_bank_transfer_id = pbt.id;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'transfer_id', pbt.id::text,
        'status', 'COMPLETED',
        'rail_tx_id', null,
        'rail_state', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_MANUAL_CONFIRM' else 'EXTERNAL_SETTLEMENT_CONFIRM' end,
        'rail_meta_json', jsonb_strip_nulls(jsonb_build_object(
          'settlement_mode', v_settlement_mode,
          'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
          'external_settlement_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
          'payment_date', v_intent_payment_date::text,
          'confirmed_at_utc', v_now::text,
          'confirmed_by_user_id', p_actor_user_id::text,
          'auth_request_id', p_auth_request_id::text,
          'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end,
          'suppress_remittances', v_intent_suppress_remittances
        ))
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_settlement_json
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and (v_scope = 'ALL' or upper(coalesce(pbt.pay_channel,'')) = v_scope)
    and upper(coalesce(pbt.status,'')) = 'PENDING';

  v_settle_result := public.pay_settle_rail(p_pay_batch_id, v_settlement_json, p_actor_user_id);

  v_worker_communications := coalesce(v_settle_result->'worker_communications', '{}'::jsonb);
  v_remittance_queue_stage_result := coalesce(
    v_settle_result->'remittance_queue_stage_result',
    v_worker_communications->'remittance_queue_stage_result',
    v_worker_communications->'result',
    '{}'::jsonb
  );
  v_manual_event_ingest_results := coalesce(v_settle_result#>'{bank_event_ingest,results}', '[]'::jsonb);

  IF jsonb_array_length(coalesce(v_manual_event_ingest_results, '[]'::jsonb)) = 0 THEN
    SELECT coalesce(
      jsonb_agg(
        public.pay_bank_event_ingest(
          jsonb_build_object(
            'pay_batch_id', p_pay_batch_id::text,
            'pay_bank_transfer_id', pbt_manual_event.id::text,
            'provider_key', coalesce(nullif(btrim(coalesce(v_provider, '')), ''), 'MANUAL'),
            'provider_event_id', 'manual-confirm:' || p_auth_request_id::text || ':' || pbt_manual_event.id::text,
            'provider_reference', coalesce(v_bank_confirm_ref, 'external-settlement:' || p_auth_request_id::text, pbt_manual_event.payment_reference, pbt_manual_event.request_id, pbt_manual_event.rail_tx_id),
            'provider_state', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_MANUAL_CONFIRM' else 'EXTERNAL_SETTLEMENT_CONFIRM' end,
            'normalised_state', 'COMPLETED',
            'event_source', 'MANUAL_CONFIRM',
            'event_time_utc', v_now::text,
            'amount', pbt_manual_event.amount,
            'currency', coalesce(nullif(btrim(coalesce(pbt_manual_event.currency, '')), ''), 'GBP'),
            'idempotency_key', 'MANUAL_CONFIRM|' || p_pay_batch_id::text || '|' || pbt_manual_event.id::text || '|COMPLETED|' || p_auth_request_id::text,
            'raw_payload', jsonb_strip_nulls(jsonb_build_object(
              'source_rpc', 'pay_settle_manual_confirm',
              'settlement_mode', v_settlement_mode,
              'bank_confirm_ref', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_confirm_ref else null end,
              'external_settlement_comment', case when v_settlement_mode = 'EXTERNAL_SETTLEMENT' then v_external_settlement_comment else null end,
              'payment_date', v_intent_payment_date::text,
              'auth_request_id', p_auth_request_id::text,
              'csv_export_hash', case when v_settlement_mode = 'CSV_SETTLEMENT' then v_bank_csv_export_hash else null end
            ))
          ),
          p_actor_user_id
        )
        order by pbt_manual_event.id
      ),
      '[]'::jsonb
    )
    INTO v_manual_event_ingest_results
    FROM public.pay_bank_transfers AS pbt_manual_event
    WHERE pbt_manual_event.pay_batch_id = p_pay_batch_id
      AND (v_scope = 'ALL' OR upper(coalesce(pbt_manual_event.pay_channel, '')) = v_scope)
      AND (
        upper(coalesce(pbt_manual_event.status, '')) = 'COMPLETED'
        OR pbt_manual_event.completed_at_utc IS NOT NULL
      );
  END IF;

  IF v_remittance_queue_stage_result IS NULL OR v_remittance_queue_stage_result = '{}'::jsonb THEN
    v_remittance_queue_stage_result := public.pay_remittance_maybe_queue_for_trigger(
      p_pay_batch_id => p_pay_batch_id,
      p_trigger => 'ON_PAYMENT_CONFIRMED',
      p_scope => 'ALL',
      p_actor_user_id => p_actor_user_id,
      p_only_confirmed => true
    );
    v_worker_communications := coalesce(v_worker_communications, '{}'::jsonb) || jsonb_build_object(
      'manual_confirm_fallback_queue_trigger_used', true,
      'remittance_queue_stage_result', v_remittance_queue_stage_result,
      'result', v_remittance_queue_stage_result,
      'dispatch_required', lower(btrim(coalesce(v_remittance_queue_stage_result->>'dispatch_required', 'false'))) in ('true','1','yes','y','on')
    );
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_MANUAL_CONFIRM_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'settlement_mode', v_settlement_mode,
      'auth_request_id', p_auth_request_id,
      'settlement_json_count', jsonb_array_length(coalesce(v_settlement_json, '[]'::jsonb)),
      'reservations_committed_count', v_reservations_committed_count,
      'reservations_committed_amount', coalesce(v_reservations_committed_amount, 0),
      'manual_event_ingest_count', jsonb_array_length(coalesce(v_manual_event_ingest_results, '[]'::jsonb)),
      'remittance_queue_stage_result', v_remittance_queue_stage_result
    ),
    'pay_batches',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return coalesce(v_settle_result, '{}'::jsonb)
    || jsonb_build_object(
      'authoritative_payment_date', v_intent_payment_date::text,
      'authoritative_payment_date_source', case when v_settlement_mode = 'CSV_SETTLEMENT' then 'CSV_SETTLEMENT_PAYMENT_DATE' else 'EXTERNAL_SETTLEMENT_PAYMENT_DATE' end,
      'settlement_mode', v_settlement_mode,
      'settlement_confirmation_json', (select pb3.settlement_confirmation_json from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_commit_state', (select pb3.execution_commit_state from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_commit_ref', (select pb3.execution_commit_ref from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'execution_committed_at_utc', (select case when pb3.execution_committed_at_utc is null then null else pb3.execution_committed_at_utc::text end from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', v_remittance_queue_stage_result,
      'manual_event_ingest_results', v_manual_event_ingest_results,
      'bank_event_ingest', coalesce(v_settle_result->'bank_event_ingest', jsonb_build_object('count', jsonb_array_length(v_manual_event_ingest_results), 'results', v_manual_event_ingest_results)),
      'reservations_committed_count', v_reservations_committed_count,
      'reservations_committed_amount', coalesce(v_reservations_committed_amount,0)
    );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_MANUAL_CONFIRM_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'settlement_mode', v_settlement_mode,
        'auth_request_id', p_auth_request_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_batches',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$$;








DROP FUNCTION IF EXISTS public.pay_settle_rail(uuid, jsonb, uuid);
DROP FUNCTION IF EXISTS public.pay_settle_rail(uuid, jsonb, uuid, uuid, jsonb);


create or replace function public.pay_settle_rail(
  p_pay_batch_id uuid,
  p_settlement_json jsonb,
  p_actor_user_id uuid,
  p_operation_id uuid default null,
  p_settlement_scope_ids jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_batch record;

  v_now timestamptz := now();

  v_newly_settled_candidates jsonb := '[]'::jsonb;

  v_pending_transfers jsonb := '[]'::jsonb;
  v_failed_transfers  jsonb := '[]'::jsonb;
  v_returned_transfers jsonb := '[]'::jsonb;
  v_blocked_transfers jsonb := '[]'::jsonb;

  v_batch_status text;

  v_missing_timesheets jsonb := '[]'::jsonb;
  v_ambig_timesheets jsonb := '[]'::jsonb;

  v_adv_id uuid;
  v_old_sched jsonb;
  v_new_sched jsonb;
  v_old_out numeric;
  v_new_out numeric;
  v_old_next date;
  v_new_next date;
  v_total_taken numeric;
  v_case_type public.pay_finance_case_type_enum;
  v_min_earnings_threshold numeric;
  v_take_home_floor_override numeric;
  v_snooze_active boolean;
  v_was_cleared boolean;

  v_linked_transfer_ct int := 0;
  v_has_pos_net boolean := false;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;
  v_stored_freshness_status text := null;
  v_stored_freshness_result_hash text := null;
  v_stored_freshness_scope_hash text := null;
  v_stored_freshness_result_json jsonb := '{}'::jsonb;
  v_stored_freshness_operation_id uuid := null;

  v_overpay_patched_ct int := 0;
  v_payment_advance_recovery_patched_ct int := 0;
  v_manual_debt_patched_ct int := 0;
  v_payout_cases_marked_paid_ct int := 0;
  v_component_settled_count int := 0;
  v_component_settled_amount numeric := 0;
  v_component_reconciliation_bad jsonb := '[]'::jsonb;
  v_component_reconciliation_bad_ct int := 0;
  v_component_reconciliation_checked_ct int := 0;

  v_comm_result jsonb := '{}'::jsonb;
  v_comm_trigger_status text := null;
  v_comm_error text := null;
  v_worker_communications jsonb := '{}'::jsonb;
  v_catchup_needed boolean := false;
  v_changed_channel_audit record;
  v_changed_channel_audit_after_json jsonb := null;
  v_changed_channel_settled_ct int := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_completed_transfer_count int := 0;
  v_detected_execution_commit_ref text := null;
  v_detected_execution_committed_at_utc timestamptz := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;
  v_settlement_mode text := 'STANDARD_BANK';
  v_effective_payment_date date := null;
  v_suppression_audit_json jsonb := '{}'::jsonb;
  v_bank_event_ingest_results jsonb := '[]'::jsonb;
  v_bank_event_ingest_count int := 0;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_settled_this_chunk integer := 0;
  v_reused_this_chunk integer := 0;
  v_failed_this_chunk integer := 0;
  v_pending_this_chunk integer := 0;
  v_remaining_scope_count integer := 0;
  v_existing_failed_scope_count integer := 0;
  v_total_failed_scope_count integer := 0;
  v_duplicate_transfer_ids jsonb := '[]'::jsonb;
  v_out_of_scope_transfer_ids jsonb := '[]'::jsonb;
  v_has_more boolean := false;
  v_carry_forward_mark_result jsonb := '{}'::jsonb;
  v_consumed_carry_forward_count integer := 0;
  v_live_signal_result jsonb := '{}'::jsonb;
begin
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_SETTLE_RAIL_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'actor_user_id', p_actor_user_id,
      'settlement_row_count', CASE WHEN p_settlement_json IS NULL OR jsonb_typeof(p_settlement_json) <> 'array' THEN NULL ELSE jsonb_array_length(p_settlement_json) END
    ),
    'pay_batches',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  if p_pay_batch_id is null then
    raise exception 'pay_settle_rail: pay_batch_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_settle_rail: actor_user_id is required';
  end if;

  if p_settlement_json is null or jsonb_typeof(p_settlement_json) <> 'array' then
    raise exception 'pay_settle_rail: settlement_json must be a JSON array';
  end if;

  v_operation_mode := (p_operation_id IS NOT NULL OR p_settlement_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_rail operation mode requires p_operation_id';
    END IF;
    IF p_settlement_scope_ids IS NULL OR jsonb_typeof(p_settlement_scope_ids) <> 'array' OR jsonb_array_length(p_settlement_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_settle_rail operation mode requires non-empty p_settlement_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('PAYMENT_SETTLEMENT', 'PAYMENT_EXECUTE') THEN
      RAISE EXCEPTION 'operation % is not a settlement-capable operation', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;

    SELECT pb.*
    INTO v_batch
    FROM public.pay_batches AS pb
    WHERE pb.id = p_pay_batch_id
    FOR UPDATE;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_settle_rail: pay_batch not found';
    END IF;

    v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
    v_stored_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
    v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
    v_stored_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
    v_stored_freshness_operation_id := v_batch.freshness_operation_id;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT count(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_settlement_scope_ids) THEN
      RAISE EXCEPTION 'p_settlement_scope_ids contains invalid or duplicate uuid values';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT count(*)::integer,
           count(*) FILTER (WHERE selected_scope.status = 'SETTLED')::integer,
           count(*) FILTER (WHERE selected_scope.status IN ('FAILED', 'SKIPPED'))::integer
    INTO v_matched_scope_count,
         v_reused_this_chunk,
         v_existing_failed_scope_count
    FROM selected_scope;

    v_failed_this_chunk := COALESCE(v_existing_failed_scope_count, 0);

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'one or more settlement scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    CREATE TEMPORARY TABLE IF NOT EXISTS pg_temp.tmp_operation_rail_settlement_updates (
      transfer_id uuid NULL,
      status text NOT NULL,
      rail_tx_id text NULL,
      rail_state text NULL,
      rail_meta_json jsonb NULL,
      provider_reference text NULL,
      provider_state text NULL,
      event_time_utc timestamptz NULL,
      input_json jsonb NOT NULL
    ) ON COMMIT DROP;
    TRUNCATE TABLE pg_temp.tmp_operation_rail_settlement_updates;

    INSERT INTO pg_temp.tmp_operation_rail_settlement_updates (
      transfer_id,
      status,
      rail_tx_id,
      rail_state,
      rail_meta_json,
      provider_reference,
      provider_state,
      event_time_utc,
      input_json
    )
    SELECT
      CASE
        WHEN NULLIF(BTRIM(COALESCE(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          THEN NULLIF(BTRIM(COALESCE(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '')::uuid
        ELSE NULL::uuid
      END,
      CASE
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('SUCCESS', 'SUCCEEDED', 'SETTLED', 'PAID') THEN 'COMPLETED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('CANCELED', 'CANCELLED') THEN 'CANCELLED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('REVERSED', 'REVERTED') THEN 'RETURNED'
        WHEN upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN'))) IN ('SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT', 'DECLINED', 'REJECTED') THEN 'FAILED'
        ELSE upper(BTRIM(COALESCE(update_element.value->>'status', update_element.value->>'normalised_state', update_element.value->>'normalized_state', 'UNKNOWN')))
      END,
      NULLIF(BTRIM(COALESCE(update_element.value->>'rail_tx_id', '')), ''),
      NULLIF(BTRIM(COALESCE(update_element.value->>'rail_state', update_element.value->>'provider_state', '')), ''),
      CASE WHEN update_element.value ? 'rail_meta_json' THEN update_element.value->'rail_meta_json' ELSE '{}'::jsonb END,
      NULLIF(BTRIM(COALESCE(
        update_element.value->>'provider_reference',
        update_element.value->>'provider_event_id',
        update_element.value->>'provider_submission_id',
        update_element.value->>'submission_id',
        update_element.value->>'rail_submission_id',
        update_element.value->>'provider_transfer_id',
        update_element.value->>'provider_payment_id',
        update_element.value->>'payment_id',
        update_element.value->>'external_payment_id',
        update_element.value->>'revolut_payment_id',
        update_element.value->>'external_transfer_id',
        update_element.value->>'provider_transaction_id',
        update_element.value->>'transaction_id',
        update_element.value #>> '{rail_meta_json,provider_reference}',
        update_element.value #>> '{rail_meta_json,provider_event_id}',
        update_element.value #>> '{rail_meta_json,provider_submission_id}',
        update_element.value #>> '{rail_meta_json,submission_id}',
        update_element.value #>> '{rail_meta_json,rail_submission_id}',
        update_element.value #>> '{rail_meta_json,provider_transfer_id}',
        update_element.value #>> '{rail_meta_json,provider_payment_id}',
        update_element.value #>> '{rail_meta_json,payment_id}',
        update_element.value #>> '{rail_meta_json,external_payment_id}',
        update_element.value #>> '{rail_meta_json,revolut_payment_id}',
        update_element.value #>> '{rail_meta_json,external_transfer_id}',
        update_element.value #>> '{rail_meta_json,provider_transaction_id}',
        update_element.value #>> '{rail_meta_json,transaction_id}',
        update_element.value->>'rail_tx_id',
        ''
      )), ''),
      NULLIF(BTRIM(COALESCE(update_element.value->>'provider_state', update_element.value->>'rail_state', update_element.value->>'status', '')), ''),
      CASE WHEN NULLIF(BTRIM(COALESCE(update_element.value->>'event_time_utc', '')), '') IS NOT NULL THEN NULLIF(BTRIM(COALESCE(update_element.value->>'event_time_utc', '')), '')::timestamptz ELSE v_now END,
      update_element.value
    FROM jsonb_array_elements(p_settlement_json) AS update_element(value)
    WHERE jsonb_typeof(update_element.value) = 'object';

    IF EXISTS (SELECT 1 FROM pg_temp.tmp_operation_rail_settlement_updates AS invalid_update WHERE invalid_update.transfer_id IS NULL LIMIT 1) THEN
      RAISE EXCEPTION 'pay_settle_rail: settlement_json contains an invalid or missing transfer_id';
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_rail_settlement_classification;
    CREATE TEMP TABLE tmp_operation_rail_settlement_classification ON COMMIT DROP AS
    SELECT
      update_rows.transfer_id,
      classification_rows.cash_state,
      classification_rows.normalised_transfer_status,
      classification_rows.is_final_money_moved,
      classification_rows.is_terminal_no_money,
      classification_rows.is_pending_non_final,
      classification_rows.completed_at_allowed,
      classification_rows.reason,
      classification_rows.support_details_json
    FROM pg_temp.tmp_operation_rail_settlement_updates AS update_rows
    CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
      update_rows.status,
      COALESCE(update_rows.rail_state, update_rows.provider_state),
      COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || COALESCE(update_rows.input_json, '{}'::jsonb),
      COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'provider_state', update_rows.provider_state,
        'provider_reference', update_rows.provider_reference,
        'settlement_operation_id', p_operation_id::text
      )
    ) AS classification_rows;

    UPDATE pg_temp.tmp_operation_rail_settlement_updates AS update_rows
    SET
      status = CASE
        WHEN classification_rows.is_final_money_moved THEN 'COMPLETED'
        WHEN classification_rows.is_terminal_no_money AND upper(COALESCE(update_rows.status, '')) IN ('CANCELLED','CANCELED') THEN 'CANCELLED'
        WHEN classification_rows.is_terminal_no_money THEN 'FAILED'
        WHEN classification_rows.is_pending_non_final THEN CASE WHEN upper(COALESCE(update_rows.status, '')) IN ('PROCESSING','SUBMITTED','SENT','ACCEPTED') THEN 'PROCESSING' ELSE 'PENDING' END
        ELSE 'UNKNOWN'
      END,
      rail_meta_json = COALESCE(update_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
        'money_movement_classification', jsonb_build_object(
          'cash_state', classification_rows.cash_state,
          'normalised_transfer_status', classification_rows.normalised_transfer_status,
          'is_final_money_moved', classification_rows.is_final_money_moved,
          'is_terminal_no_money', classification_rows.is_terminal_no_money,
          'is_pending_non_final', classification_rows.is_pending_non_final,
          'completed_at_allowed', classification_rows.completed_at_allowed,
          'reason', classification_rows.reason
        ),
        'settlement_final_paid_required', true
      )
    FROM pg_temp.tmp_operation_rail_settlement_classification AS classification_rows
    WHERE classification_rows.transfer_id = update_rows.transfer_id;

    SELECT COALESCE(jsonb_agg(to_jsonb(duplicate_update.transfer_id::text) ORDER BY duplicate_update.transfer_id::text), '[]'::jsonb)
    INTO v_duplicate_transfer_ids
    FROM (
      SELECT duplicate_source.transfer_id
      FROM pg_temp.tmp_operation_rail_settlement_updates AS duplicate_source
      GROUP BY duplicate_source.transfer_id
      HAVING COUNT(*) > 1
    ) AS duplicate_update;

    IF jsonb_array_length(v_duplicate_transfer_ids) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_RAIL_DUPLICATE_TRANSFER_UPDATE',
        'message', 'A rail settlement update chunk cannot contain duplicate transfer IDs.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'duplicate_transfer_ids', v_duplicate_transfer_ids
      )::text;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), payload_transfer AS (
      SELECT selected_scope.id AS settlement_scope_id,
             CASE
               WHEN COALESCE(selected_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN (selected_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
               ELSE NULL::uuid
             END AS pay_bank_transfer_id
      FROM selected_scope
    ), payload_item_ids AS (
      SELECT selected_scope.id AS settlement_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM selected_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(selected_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfers AS (
      SELECT DISTINCT selected_scope.id AS settlement_scope_id,
             COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM selected_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = selected_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = selected_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), out_of_scope_updates AS (
      SELECT DISTINCT update_row.transfer_id
      FROM pg_temp.tmp_operation_rail_settlement_updates AS update_row
      WHERE NOT EXISTS (
        SELECT 1
        FROM scope_transfers
        WHERE scope_transfers.pay_bank_transfer_id = update_row.transfer_id
      )
    )
    SELECT COALESCE(jsonb_agg(to_jsonb(out_of_scope_updates.transfer_id::text) ORDER BY out_of_scope_updates.transfer_id::text), '[]'::jsonb)
    INTO v_out_of_scope_transfer_ids
    FROM out_of_scope_updates;

    IF jsonb_array_length(v_out_of_scope_transfer_ids) > 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_SETTLE_RAIL_OUT_OF_SCOPE_TRANSFER_UPDATE',
        'message', 'A rail settlement update chunk contained transfer IDs that are not part of the supplied settlement scope rows.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'out_of_scope_transfer_ids', v_out_of_scope_transfer_ids
      )::text;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM pg_temp.tmp_operation_rail_settlement_updates AS update_row
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = update_row.transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE update_row.status = 'COMPLETED'
        AND NOT EXISTS (
          SELECT 1
          FROM (VALUES
            (update_row.provider_reference),
            (update_row.rail_tx_id),
            (update_row.rail_meta_json #>> '{provider_reference}'),
            (update_row.rail_meta_json #>> '{provider_event_id}'),
            (update_row.rail_meta_json #>> '{provider_submission_id}'),
            (update_row.rail_meta_json #>> '{submission_id}'),
            (update_row.rail_meta_json #>> '{rail_submission_id}'),
            (update_row.rail_meta_json #>> '{provider_payment_id}'),
            (update_row.rail_meta_json #>> '{payment_id}'),
            (update_row.rail_meta_json #>> '{external_payment_id}'),
            (update_row.rail_meta_json #>> '{revolut_payment_id}'),
            (update_row.rail_meta_json #>> '{provider_transfer_id}'),
            (update_row.rail_meta_json #>> '{transfer_id}'),
            (update_row.rail_meta_json #>> '{external_transfer_id}'),
            (update_row.rail_meta_json #>> '{provider_transaction_id}'),
            (update_row.rail_meta_json #>> '{transaction_id}')
          ) AS provider_identifier(identifier_value)
          WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
            AND NOT (
              NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') = ANY(
                ARRAY_REMOVE(ARRAY[
                  bank_transfer.id::text,
                  NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(bank_transfer.rail_meta_json #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{bulk_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{request_id}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{idempotency_key}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{payment_reference}', '')), ''),
                  NULLIF(BTRIM(COALESCE(update_row.rail_meta_json #>> '{bulk_reference}', '')), '')
                ]::text[], NULL::text)
              )
            )
        )
      LIMIT 1
    ) THEN
      RAISE EXCEPTION 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED',
                'pay_batch_id', p_pay_batch_id::text,
                'operation_id', p_operation_id::text,
                'message', 'STANDARD_BANK rail settlement marked as completed requires genuine provider or bank evidence, not local request/payment references.'
              )::text;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS settlement_scope_id
      FROM jsonb_array_elements(p_settlement_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), pending_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_settlement_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.settlement_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
        AND scope_row.status = 'PENDING'
      FOR UPDATE OF scope_row
    ), payload_transfer AS (
      SELECT pending_scope.id AS settlement_scope_id,
             CASE
               WHEN COALESCE(pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                 THEN (pending_scope.payload_json #>> '{payment_scope_json,pay_bank_transfer_id}')::uuid
               ELSE NULL::uuid
             END AS pay_bank_transfer_id
      FROM pending_scope
    ), payload_item_ids AS (
      SELECT pending_scope.id AS settlement_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM pending_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(pending_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), scope_transfers AS (
      SELECT DISTINCT pending_scope.id AS settlement_scope_id,
             COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) AS pay_bank_transfer_id
      FROM pending_scope
      LEFT JOIN payload_transfer
        ON payload_transfer.settlement_scope_id = pending_scope.id
      LEFT JOIN payload_item_ids
        ON payload_item_ids.settlement_scope_id = pending_scope.id
      LEFT JOIN public.pay_batch_items AS batch_item
        ON batch_item.id = payload_item_ids.pay_batch_item_id
      WHERE COALESCE(payload_transfer.pay_bank_transfer_id, batch_item.pay_bank_transfer_id) IS NOT NULL
    ), failed_scope_no_transfer AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = 'FAILED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'settlement_failure_code', 'NO_PAY_BANK_TRANSFER_FOR_SCOPE',
            'settlement_failure_message', 'Rail/provider settlement scope could not be processed because it does not resolve to a frozen pay_bank_transfer row.',
            'failed_at_utc', v_now::text
          )),
          updated_at_utc = v_now
      FROM pending_scope
      WHERE scope_update.id = pending_scope.id
        AND NOT EXISTS (
          SELECT 1
          FROM scope_transfers
          WHERE scope_transfers.settlement_scope_id = pending_scope.id
        )
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id
    ), matched_updates AS (
      SELECT scope_transfers.settlement_scope_id,
             scope_transfers.pay_bank_transfer_id,
             update_row.status,
             update_row.rail_tx_id,
             update_row.rail_state,
             update_row.rail_meta_json,
             update_row.provider_reference,
             update_row.provider_state,
             update_row.event_time_utc,
             update_row.input_json
      FROM scope_transfers
      JOIN pg_temp.tmp_operation_rail_settlement_updates AS update_row
        ON update_row.transfer_id = scope_transfers.pay_bank_transfer_id
    ), inserted_events AS (
      INSERT INTO public.pay_bank_transfer_events (
        pay_batch_id,
        pay_bank_transfer_id,
        candidate_id,
        umbrella_id,
        provider_key,
        provider_event_id,
        provider_reference,
        provider_state,
        normalised_state,
        event_source,
        event_time_utc,
        received_at_utc,
        amount,
        currency,
        mapping_status,
        movement_classification,
        correction_disposition,
        raw_payload,
        idempotency_key,
        mapping_method
      )
      SELECT
        p_pay_batch_id,
        matched_updates.pay_bank_transfer_id,
        bank_transfer.candidate_id,
        bank_transfer.umbrella_id,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.rail_provider, '')), ''), v_batch.rail_provider_snapshot),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
             COALESCE(bank_transfer.id::text, '__no_transfer_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
             COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
           )
            THEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '')
          WHEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
           AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
             COALESCE(bank_transfer.id::text, '__no_transfer_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
             COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
             COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
           )
            THEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '')
          ELSE NULL::text
        END,
        COALESCE(
          CASE
            WHEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '')
            ELSE NULL::text
          END,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '')
            ELSE NULL::text
          END,
          CASE
            WHEN NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '') IS NOT NULL
             AND NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '') NOT IN (
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
               COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
               COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
             )
              THEN NULLIF(BTRIM(COALESCE(bank_transfer.rail_tx_id, '')), '')
            ELSE NULL::text
          END
        ),
        CASE
          WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(matched_updates.provider_state, matched_updates.rail_state, matched_updates.status)
          WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
          ELSE COALESCE(matched_updates.provider_state, matched_updates.rail_state, matched_updates.status)
        END,
        CASE
          WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN 'COMPLETED'
          WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
          WHEN matched_updates.status IN ('FAILED', 'RETURNED', 'CANCELLED', 'PENDING', 'PROCESSING', 'UNKNOWN') THEN matched_updates.status
          ELSE 'UNKNOWN'
        END,
        'PROVIDER_POLL',
        COALESCE(matched_updates.event_time_utc, v_now),
        v_now,
        bank_transfer.amount,
        COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer.currency, '')), ''), 'GBP'),
        'MATCHED',
        NULL::text,
        NULL::text,
        jsonb_strip_nulls(COALESCE(matched_updates.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'source_rpc', 'pay_settle_rail',
          'settlement_event_source', 'PROVIDER_SETTLEMENT',
          'operation_id', p_operation_id::text,
          'settlement_scope_id', matched_updates.settlement_scope_id::text,
          'input_json', matched_updates.input_json
        )),
        'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
          'status', matched_updates.status,
          'rail_tx_id', matched_updates.rail_tx_id,
          'rail_state', matched_updates.rail_state,
          'provider_reference', matched_updates.provider_reference,
          'provider_state', matched_updates.provider_state,
          'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
        ))::text),
        'TRANSFER_ID'
      FROM matched_updates
      JOIN public.pay_bank_transfers AS bank_transfer
        ON bank_transfer.id = matched_updates.pay_bank_transfer_id
       AND bank_transfer.pay_batch_id = p_pay_batch_id
      WHERE NOT EXISTS (
        SELECT 1
        FROM public.pay_bank_transfer_events AS existing_event
        WHERE existing_event.pay_batch_id = p_pay_batch_id
          AND existing_event.idempotency_key = 'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
            'status', matched_updates.status,
            'rail_tx_id', matched_updates.rail_tx_id,
            'rail_state', matched_updates.rail_state,
            'provider_reference', matched_updates.provider_reference,
            'provider_state', matched_updates.provider_state,
            'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
          ))::text)
      )
      RETURNING public.pay_bank_transfer_events.id,
                public.pay_bank_transfer_events.pay_bank_transfer_id,
                public.pay_bank_transfer_events.idempotency_key
    ), transfer_updates AS (
      UPDATE public.pay_bank_transfers AS transfer_update
      SET status = CASE
            WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN 'COMPLETED'
            WHEN matched_updates.status = 'COMPLETED' THEN 'UNKNOWN'
            WHEN matched_updates.status IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED') THEN matched_updates.status
            WHEN matched_updates.status = 'PROCESSING' THEN 'PROCESSING'
            WHEN matched_updates.status = 'UNKNOWN' THEN 'UNKNOWN'
            ELSE 'PENDING'
          END,
          rail_tx_id = CASE
            WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(matched_updates.rail_tx_id, transfer_update.rail_tx_id)
            WHEN matched_updates.status <> 'COMPLETED' THEN COALESCE(matched_updates.rail_tx_id, transfer_update.rail_tx_id)
            ELSE transfer_update.rail_tx_id
          END,
          rail_state = COALESCE(matched_updates.rail_state, matched_updates.provider_state, transfer_update.rail_state),
          rail_meta_json = jsonb_strip_nulls(COALESCE(transfer_update.rail_meta_json, '{}'::jsonb) || COALESCE(matched_updates.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
            'provider_reference', matched_updates.provider_reference,
            'provider_state', matched_updates.provider_state,
            'settlement_operation_id', p_operation_id::text
          )),
          completed_at_utc = CASE WHEN matched_updates.status = 'COMPLETED' AND ((
              NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.provider_reference, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR (
              NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(matched_updates.rail_tx_id, '')), '') NOT IN (
                COALESCE(transfer_update.id::text, '__no_transfer_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(transfer_update.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
              )
            )
            OR lower(btrim(coalesce(matched_updates.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')) THEN COALESCE(transfer_update.completed_at_utc, matched_updates.event_time_utc, v_now) ELSE transfer_update.completed_at_utc END,
          failed_reason = CASE WHEN matched_updates.status IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED') THEN COALESCE(transfer_update.failed_reason, matched_updates.provider_state, matched_updates.rail_state, matched_updates.status) ELSE transfer_update.failed_reason END
      FROM matched_updates
      WHERE transfer_update.id = matched_updates.pay_bank_transfer_id
        AND transfer_update.pay_batch_id = p_pay_batch_id
      RETURNING transfer_update.id,
                matched_updates.settlement_scope_id,
                transfer_update.status
    ), scope_status AS (
      SELECT pending_scope.id AS settlement_scope_id,
             CASE
               WHEN BOOL_OR(transfer_updates.status IN ('FAILED', 'DECLINED', 'REJECTED', 'CANCELLED', 'RETURNED', 'REVERTED')) THEN 'FAILED'
               WHEN COUNT(transfer_updates.id) = COUNT(scope_transfers.pay_bank_transfer_id)
                AND COUNT(scope_transfers.pay_bank_transfer_id) > 0
                AND BOOL_AND(transfer_updates.status = 'COMPLETED') THEN 'SETTLED'
               ELSE 'PENDING'
             END AS new_scope_status
      FROM pending_scope
      JOIN scope_transfers
        ON scope_transfers.settlement_scope_id = pending_scope.id
      LEFT JOIN transfer_updates
        ON transfer_updates.settlement_scope_id = pending_scope.id
       AND transfer_updates.id = scope_transfers.pay_bank_transfer_id
      GROUP BY pending_scope.id
    ), event_by_scope AS (
      SELECT matched_updates.settlement_scope_id,
             (array_agg(existing_event.id ORDER BY existing_event.id))[1] AS event_id
      FROM matched_updates
      JOIN public.pay_bank_transfer_events AS existing_event
        ON existing_event.pay_batch_id = p_pay_batch_id
       AND existing_event.idempotency_key = 'rail-settle:' || p_operation_id::text || ':' || matched_updates.settlement_scope_id::text || ':' || matched_updates.pay_bank_transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
          'status', matched_updates.status,
          'rail_tx_id', matched_updates.rail_tx_id,
          'rail_state', matched_updates.rail_state,
          'provider_reference', matched_updates.provider_reference,
          'provider_state', matched_updates.provider_state,
          'rail_meta_json', COALESCE(matched_updates.rail_meta_json, '{}'::jsonb)
        ))::text)
      GROUP BY matched_updates.settlement_scope_id
    ), scope_updates AS (
      UPDATE public.banking_pay_operation_settlement_scope AS scope_update
      SET status = scope_status.new_scope_status,
          settlement_event_id = COALESCE(scope_update.settlement_event_id, event_by_scope.event_id),
          updated_at_utc = v_now
      FROM scope_status
      LEFT JOIN event_by_scope
        ON event_by_scope.settlement_scope_id = scope_status.settlement_scope_id
      WHERE scope_update.id = scope_status.settlement_scope_id
      RETURNING scope_update.id,
                scope_update.pay_batch_candidate_id,
                scope_update.status
    ), candidate_complete AS (
      SELECT DISTINCT scope_updates.pay_batch_candidate_id
      FROM scope_updates
      WHERE scope_updates.status = 'SETTLED'
        AND NOT EXISTS (
          SELECT 1
          FROM public.banking_pay_operation_settlement_scope AS remaining_for_candidate
          WHERE remaining_for_candidate.operation_id = p_operation_id
            AND remaining_for_candidate.pay_batch_id = p_pay_batch_id
            AND remaining_for_candidate.pay_batch_candidate_id = scope_updates.pay_batch_candidate_id
            AND remaining_for_candidate.status NOT IN ('SETTLED', 'SKIPPED')
        )
    ), candidate_updates AS (
      UPDATE public.pay_batch_candidates AS candidate_update
      SET settlement_status = 'SETTLED',
          settled_at_utc = COALESCE(candidate_update.settled_at_utc, v_now),
          settled_via = COALESCE(NULLIF(BTRIM(COALESCE(v_batch.rail_provider_snapshot, '')), ''), 'RAIL'),
          settled_note = COALESCE(candidate_update.settled_note, 'Rail/provider settlement confirmed')
      FROM candidate_complete
      WHERE candidate_update.id = candidate_complete.pay_batch_candidate_id
      RETURNING candidate_update.id
    )
    SELECT count(*) FILTER (WHERE scope_updates.status = 'SETTLED')::integer,
           COALESCE(v_failed_this_chunk, 0)
             + COALESCE((SELECT COUNT(*)::integer FROM failed_scope_no_transfer), 0)
             + count(*) FILTER (WHERE scope_updates.status = 'FAILED')::integer,
           count(*) FILTER (WHERE scope_updates.status = 'PENDING')::integer
    INTO v_settled_this_chunk,
         v_failed_this_chunk,
         v_pending_this_chunk
    FROM scope_updates;

    SELECT COUNT(*)::integer
    INTO v_remaining_scope_count
    FROM public.banking_pay_operation_settlement_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    SELECT COUNT(*)::integer
    INTO v_total_failed_scope_count
    FROM public.banking_pay_operation_settlement_scope AS failed_scope
    WHERE failed_scope.operation_id = p_operation_id
      AND failed_scope.pay_batch_id = p_pay_batch_id
      AND failed_scope.status = 'FAILED';

    v_has_more := COALESCE(v_remaining_scope_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = v_now
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    SELECT public._pay_manual_adjustment_carry_forward_mark_consumed(
      p_pay_batch_id,
      NULL::uuid[],
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_bank_transfer_ids', COALESCE((
          SELECT jsonb_agg(DISTINCT completed_transfer_rows.transfer_id::text ORDER BY completed_transfer_rows.transfer_id::text)
          FROM pg_temp.tmp_operation_rail_settlement_updates AS completed_transfer_rows
          WHERE completed_transfer_rows.status = 'COMPLETED'
        ), '[]'::jsonb),
        'pay_batch_item_ids', COALESCE((
          SELECT jsonb_agg(DISTINCT item_rows.id::text ORDER BY item_rows.id::text)
          FROM public.pay_batch_items AS item_rows
          JOIN public.pay_batch_candidates AS candidate_rows
            ON candidate_rows.id = item_rows.pay_batch_candidate_id
          JOIN pg_temp.tmp_operation_rail_settlement_updates AS completed_transfer_rows
            ON completed_transfer_rows.transfer_id = item_rows.pay_bank_transfer_id
          WHERE candidate_rows.pay_batch_id = p_pay_batch_id
            AND completed_transfer_rows.status = 'COMPLETED'
        ), '[]'::jsonb)
      ),
      jsonb_build_object('final_paid', true, 'cash_state', 'FINAL_PAID', 'source', 'pay_settle_rail_operation_mode'),
      p_actor_user_id
    )
    INTO v_carry_forward_mark_result;

    v_consumed_carry_forward_count := v_consumed_carry_forward_count + COALESCE(NULLIF(v_carry_forward_mark_result->>'consumed_count', '')::integer, 0);

    v_live_signal_result := public.banking_pay_batch_signal_touch(
      p_pay_batch_id := p_pay_batch_id,
      p_change_reason := 'PAY_SETTLE_RAIL_OPERATION_CHUNK',
      p_change_source := 'pay_settle_rail',
      p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
        'operation_id', p_operation_id::text,
        'settlement_scope_ids', COALESCE(p_settlement_scope_ids, '[]'::jsonb),
        'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
        'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
        'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
        'pending_this_chunk', COALESCE(v_pending_this_chunk, 0),
        'remaining', COALESCE(v_remaining_scope_count, 0),
        'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0)
      )),
      p_touch_payment_status := true,
      p_touch_correction_progress := true,
      p_touch_alerts := false,
      p_touch_overview := true
    );

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'settled_this_chunk', COALESCE(v_settled_this_chunk, 0),
      'reused_this_chunk', COALESCE(v_reused_this_chunk, 0),
      'failed_this_chunk', COALESCE(v_failed_this_chunk, 0),
      'pending_this_chunk', COALESCE(v_pending_this_chunk, 0),
      'remaining', COALESCE(v_remaining_scope_count, 0),
      'failed_scope_count', COALESCE(v_total_failed_scope_count, 0),
      'has_more', v_has_more,
      'remittance_ready', COALESCE(v_remaining_scope_count, 0) = 0 AND COALESCE(v_total_failed_scope_count, 0) = 0,
      'remittance_queued', false,
      'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
      'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
      'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
      'freshness', jsonb_build_object(
        'freshness_validation_status', nullif(v_stored_freshness_status, ''),
        'freshness_result_hash', v_stored_freshness_result_hash,
        'freshness_scope_hash', v_stored_freshness_scope_hash,
        'freshness_operation_id', case when v_stored_freshness_operation_id is null then null else v_stored_freshness_operation_id::text end,
        'source', 'stored_freshness_metadata_non_blocking'
      ),
      'message', 'Rail settlement chunk processed; remittance queueing is handled by a separate operation.'
    );
  END IF;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot,
    pb.bulk_reference,
    pb.batch_kind_fixed,
    pb.execution_intent_json,
    pb.settlement_confirmation_json,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.freshness_result_json,
    pb.freshness_operation_id
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  for update;

  if v_batch.id is null then
    raise exception 'pay_settle_rail: pay_batch not found';
  end if;

  v_stored_freshness_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_stored_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_stored_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
  v_stored_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
  v_stored_freshness_operation_id := v_batch.freshness_operation_id;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  v_settlement_mode := upper(btrim(coalesce(v_execution_intent_json->>'execution_mode', 'STANDARD_BANK')));
  if v_settlement_mode not in ('STANDARD_BANK','CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then
    v_settlement_mode := 'STANDARD_BANK';
  end if;
  v_suppress_remittances := lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances', 'false'))) in ('true','1','yes','y','on');
  v_effective_payment_date := coalesce(v_batch.authoritative_payment_date, v_batch.pay_date);

  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := v_batch.execution_commit_ref;
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;

  -- Settlement follows bank/provider truth after the execution boundary.
  -- Do not run current/live freshness as a blocking settlement check here.
  -- Stored freshness-at-execution metadata is carried as informational context only.
  v_fresh := jsonb_build_object(
    'is_stale', coalesce(v_stored_freshness_status in ('STALE', 'FAILED'), false),
    'stale_reasons', coalesce(v_stored_freshness_result_json->'stale_reasons', '[]'::jsonb),
    'diff', coalesce(v_stored_freshness_result_json->'diff_sample', '[]'::jsonb),
    'freshness_validation_status', nullif(v_stored_freshness_status, ''),
    'freshness_result_hash', v_stored_freshness_result_hash,
    'freshness_scope_hash', v_stored_freshness_scope_hash,
    'freshness_operation_id', case when v_stored_freshness_operation_id is null then null else v_stored_freshness_operation_id::text end,
    'source', 'stored_freshness_metadata_non_blocking'
  );
  v_is_stale := coalesce(v_stored_freshness_status in ('STALE', 'FAILED'), false);
  v_stale_reasons := coalesce(v_stored_freshness_result_json->'stale_reasons', '[]'::jsonb);
  v_diff_sample := coalesce(v_stored_freshness_result_json->'diff_sample', '[]'::jsonb);

  if v_is_stale = true then
    begin
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_SETTLE_RAIL:STORED_STALE_METADATA_PROCEEDING',
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'freshness_validation_status', v_stored_freshness_status,
          'freshness_result_hash', v_stored_freshness_result_hash,
          'freshness_scope_hash', v_stored_freshness_scope_hash,
          'stale_reasons', v_stale_reasons,
          'diff_sample', v_diff_sample
        ),
        'pay_batches',
        p_pay_batch_id::text,
        null,
        null,
        null,
        null
      );
    exception when others then
      null;
    end;
  end if;

  create temp table if not exists _tmp_settle_in (
    transfer_id uuid null,
    status text not null,
    rail_tx_id text null,
    rail_state text null,
    rail_meta_json jsonb null
  ) on commit drop;

  truncate table _tmp_settle_in;

  insert into _tmp_settle_in(transfer_id, status, rail_tx_id, rail_state, rail_meta_json)
  select
    case
      when nullif(btrim(coalesce(e->>'transfer_id','')),'') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        then nullif(btrim(coalesce(e->>'transfer_id','')),'')::uuid
      else null::uuid
    end as transfer_id,
    upper(btrim(coalesce(e->>'status',''))) as status,
    nullif(btrim(coalesce(e->>'rail_tx_id','')),'') as rail_tx_id,
    nullif(btrim(coalesce(e->>'rail_state','')),'') as rail_state,
    case
      when (e ? 'rail_meta_json') and jsonb_typeof(e->'rail_meta_json') in ('object','array','string','number','boolean','null')
        then e->'rail_meta_json'
      else null
    end as rail_meta_json
  from jsonb_array_elements(p_settlement_json) e
  where e is not null and jsonb_typeof(e) = 'object';

  update _tmp_settle_in AS settle_status_normalise
  set status = case
    when settle_status_normalise.status = 'CANCELED' then 'CANCELLED'
    when settle_status_normalise.status in ('SUCCESS','SUCCEEDED','SETTLED','PAID') then 'COMPLETED'
    when settle_status_normalise.status in ('EXECUTED','COMMITTED') then 'UNKNOWN'
    when settle_status_normalise.status = 'REVERSED' then 'REVERTED'
    when settle_status_normalise.status in ('SUBMISSION_FAILED','FAILED_BEFORE_COMMIT') then 'FAILED'
    else settle_status_normalise.status
  end;

  DROP TABLE IF EXISTS pg_temp._tmp_settle_in_classification;
  CREATE TEMP TABLE _tmp_settle_in_classification ON COMMIT DROP AS
  SELECT
    settle_input_rows.transfer_id,
    classification_rows.cash_state,
    classification_rows.normalised_transfer_status,
    classification_rows.is_final_money_moved,
    classification_rows.is_terminal_no_money,
    classification_rows.is_pending_non_final,
    classification_rows.completed_at_allowed,
    classification_rows.reason,
    classification_rows.support_details_json
  FROM _tmp_settle_in AS settle_input_rows
  CROSS JOIN LATERAL public._pay_rail_state_money_movement_classify(
    settle_input_rows.status,
    settle_input_rows.rail_state,
    COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb),
    COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb)
  ) AS classification_rows;

  UPDATE _tmp_settle_in AS settle_input_rows
  SET
    status = CASE
      WHEN classification_rows.is_final_money_moved THEN 'COMPLETED'
      WHEN classification_rows.is_terminal_no_money AND upper(COALESCE(settle_input_rows.status, '')) IN ('CANCELLED','CANCELED') THEN 'CANCELLED'
      WHEN classification_rows.is_terminal_no_money THEN 'FAILED'
      WHEN classification_rows.is_pending_non_final THEN CASE WHEN upper(COALESCE(settle_input_rows.status, '')) IN ('PROCESSING','SUBMITTED','SENT','ACCEPTED') THEN 'PROCESSING' ELSE 'PENDING' END
      ELSE 'UNKNOWN'
    END,
    rail_meta_json = COALESCE(settle_input_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
      'money_movement_classification', jsonb_build_object(
        'cash_state', classification_rows.cash_state,
        'normalised_transfer_status', classification_rows.normalised_transfer_status,
        'is_final_money_moved', classification_rows.is_final_money_moved,
        'is_terminal_no_money', classification_rows.is_terminal_no_money,
        'is_pending_non_final', classification_rows.is_pending_non_final,
        'completed_at_allowed', classification_rows.completed_at_allowed,
        'reason', classification_rows.reason
      ),
      'settlement_final_paid_required', true
    )
  FROM pg_temp._tmp_settle_in_classification AS classification_rows
  WHERE classification_rows.transfer_id = settle_input_rows.transfer_id;

  if exists (select 1 from _tmp_settle_in t where t.transfer_id is null limit 1) then
    raise exception 'pay_settle_rail: settlement_json contains an invalid or missing transfer_id';
  end if;

  if exists (
    select 1
    from _tmp_settle_in t
    where t.status not in ('PENDING','PROCESSING','UNKNOWN','COMPLETED','FAILED','DECLINED','REJECTED','CANCELLED','RETURNED','REVERTED')
    limit 1
  ) then
    raise exception 'pay_settle_rail: invalid status in settlement_json (allowed: PENDING|PROCESSING|UNKNOWN|COMPLETED|FAILED|DECLINED|REJECTED|CANCELLED|RETURNED|REVERTED)';
  end if;

  if exists (
    select 1
    from _tmp_settle_in t
    left join public.pay_bank_transfers pbt
      on pbt.id = t.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where pbt.id is null
    limit 1
  ) then
    raise exception 'pay_settle_rail: one or more transfer_id values do not belong to the specified pay batch';
  end if;

  if v_settlement_mode = 'STANDARD_BANK' and exists (
    select 1
    from _tmp_settle_in as t
    join public.pay_bank_transfers as pbt
      on pbt.id = t.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    where t.status = 'COMPLETED'
      and not exists (
        select 1
        from (values
          (t.rail_tx_id),
          (t.rail_meta_json #>> '{provider_reference}'),
          (t.rail_meta_json #>> '{provider_event_id}'),
          (t.rail_meta_json #>> '{provider_submission_id}'),
          (t.rail_meta_json #>> '{submission_id}'),
          (t.rail_meta_json #>> '{rail_submission_id}'),
          (t.rail_meta_json #>> '{provider_payment_id}'),
          (t.rail_meta_json #>> '{payment_id}'),
          (t.rail_meta_json #>> '{external_payment_id}'),
          (t.rail_meta_json #>> '{revolut_payment_id}'),
          (t.rail_meta_json #>> '{provider_transfer_id}'),
          (t.rail_meta_json #>> '{transfer_id}'),
          (t.rail_meta_json #>> '{external_transfer_id}'),
          (t.rail_meta_json #>> '{provider_transaction_id}'),
          (t.rail_meta_json #>> '{transaction_id}')
        ) as provider_identifier(identifier_value)
        where nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') is not null
          and not (
            nullif(btrim(coalesce(provider_identifier.identifier_value, '')), '') = any(
              array_remove(array[
                pbt.id::text,
                nullif(btrim(coalesce(pbt.request_id, '')), ''),
                nullif(btrim(coalesce(pbt.payment_reference, '')), ''),
                nullif(btrim(coalesce(v_batch.bulk_reference, '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{request_id}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{idempotency_key}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{payment_reference}', '')), ''),
                nullif(btrim(coalesce(pbt.rail_meta_json #>> '{bulk_reference}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{request_id}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{idempotency_key}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{payment_reference}', '')), ''),
                nullif(btrim(coalesce(t.rail_meta_json #>> '{bulk_reference}', '')), '')
              ]::text[], null::text)
            )
          )
      )
    limit 1
  ) then
    raise exception 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED'
      using errcode = 'P0001',
            detail = jsonb_build_object(
              'code', 'PAY_SETTLE_RAIL_PROVIDER_EVIDENCE_REQUIRED',
              'pay_batch_id', p_pay_batch_id::text,
              'message', 'STANDARD_BANK settlement marked as completed requires genuine provider or bank evidence, not local request/payment references.'
            )::text;
  end if;


  update public.pay_bank_transfers pbt
  set
    status = CASE
      WHEN t.status = 'COMPLETED' THEN 'COMPLETED'
      WHEN t.status IN ('FAILED','DECLINED','REJECTED','CANCELLED','RETURNED','REVERTED') THEN t.status
      WHEN t.status = 'BLOCKED' THEN 'BLOCKED'
      WHEN t.status = 'PROCESSING' THEN 'PROCESSING'
      WHEN t.status = 'UNKNOWN' THEN 'UNKNOWN'
      WHEN t.status = 'PENDING' THEN 'PENDING'
      ELSE 'PENDING'
    END,
    rail_tx_id = coalesce(t.rail_tx_id, pbt.rail_tx_id),
    rail_state = coalesce(t.rail_state, pbt.rail_state),
    rail_meta_json = case
      when t.rail_meta_json is null then pbt.rail_meta_json
      when pbt.rail_meta_json is null then t.rail_meta_json
      else (pbt.rail_meta_json || t.rail_meta_json)
    end,
    completed_at_utc = case
      when t.status = 'COMPLETED' then coalesce(pbt.completed_at_utc, v_now)
      else pbt.completed_at_utc
    end,
    failed_reason = case
      when t.status IN ('FAILED','DECLINED','REJECTED','CANCELLED') then coalesce(pbt.failed_reason, nullif(btrim(coalesce(t.rail_state,'')),''), t.status)
      else pbt.failed_reason
    end
  from _tmp_settle_in t
  where pbt.id = t.transfer_id
    and pbt.pay_batch_id = p_pay_batch_id;

  DROP TABLE IF EXISTS pg_temp._tmp_settle_bank_event_ingest_results;
  CREATE TEMP TABLE _tmp_settle_bank_event_ingest_results ON COMMIT DROP AS
  SELECT
    settle_event_rows.transfer_id,
    settle_event_rows.status,
    public.pay_bank_event_ingest(
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_bank_transfer_id', settle_event_rows.transfer_id::text,
        'provider_key', COALESCE(v_batch.rail_provider_snapshot, 'UNKNOWN'),
        'provider_reference', CASE
          WHEN v_settlement_mode IN ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') THEN COALESCE(settle_event_rows.rail_tx_id, bank_transfer_for_event.rail_tx_id, bank_transfer_for_event.request_id, bank_transfer_for_event.payment_reference)
          ELSE COALESCE(
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_tx_id, '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_reference}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_event_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_submission_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_payment_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transfer_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(settle_event_rows.rail_meta_json #>> '{provider_transaction_id}', '')), '')
              ELSE NULL::text
            END,
            CASE
              WHEN NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '') IS NOT NULL
               AND NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '') NOT IN (
                 COALESCE(bank_transfer_for_event.id::text, '__no_transfer_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.request_id, '')), ''), '__no_request_id__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(bank_transfer_for_event.payment_reference, '')), ''), '__no_payment_reference__'),
                 COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), '__no_bulk_reference__')
               )
                THEN NULLIF(BTRIM(COALESCE(bank_transfer_for_event.rail_tx_id, '')), '')
              ELSE NULL::text
            END
          )
        END,
        'provider_state', COALESCE(settle_event_rows.rail_state, settle_event_rows.status),
        'normalised_state', settle_event_rows.status,
        'event_source', CASE WHEN v_settlement_mode IN ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') THEN 'MANUAL_CONFIRM' ELSE 'PROVIDER_POLL' END,
        'event_time_utc', v_now::text,
        'amount', bank_transfer_for_event.amount,
        'currency', 'GBP',
        'raw_payload', COALESCE(settle_event_rows.rail_meta_json, '{}'::jsonb) || jsonb_build_object(
          'settlement_mode', v_settlement_mode,
          'source_rpc', 'pay_settle_rail'
        )
      ),
      p_actor_user_id
    ) AS ingest_result
  FROM _tmp_settle_in AS settle_event_rows
  JOIN public.pay_bank_transfers AS bank_transfer_for_event
    ON bank_transfer_for_event.id = settle_event_rows.transfer_id;

  SELECT
    COALESCE(jsonb_agg(ingest_rows.ingest_result ORDER BY ingest_rows.transfer_id), '[]'::jsonb),
    count(*)::int
  INTO v_bank_event_ingest_results, v_bank_event_ingest_count
  FROM pg_temp._tmp_settle_bank_event_ingest_results AS ingest_rows;

  DROP TABLE IF EXISTS pg_temp._tmp_settle_external_completed_transfers;
  CREATE TEMP TABLE _tmp_settle_external_completed_transfers ON COMMIT DROP AS
  WITH completed_transfer_base AS (
    SELECT
      completed_transfer.id AS transfer_id,
      completed_transfer.rail_tx_id,
      completed_transfer.completed_at_utc,
      completed_transfer.status,
      completed_transfer.rail_state,
      COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb) AS rail_meta_json,
      lower(btrim(coalesce(completed_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on') AS last_update_was_provider_evidence,
      ARRAY_REMOVE(ARRAY[
        completed_transfer.id::text,
        NULLIF(BTRIM(COALESCE(completed_transfer.request_id, '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.payment_reference, '')), ''),
        NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{request_id}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
        NULLIF(BTRIM(COALESCE(completed_transfer.rail_meta_json #>> '{bulk_reference}', '')), '')
      ]::text[], NULL::text) AS local_identity_values
    FROM public.pay_bank_transfers AS completed_transfer
    WHERE completed_transfer.pay_batch_id = p_pay_batch_id
      AND EXISTS (
        SELECT 1
        FROM public._pay_rail_state_money_movement_classify(
          completed_transfer.status,
          completed_transfer.rail_state,
          COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb),
          COALESCE(completed_transfer.rail_meta_json, '{}'::jsonb)
        ) AS completed_transfer_classifier
        WHERE completed_transfer_classifier.is_final_money_moved = true
      )
  ), externally_supported_completed AS (
    SELECT
      completed_transfer_base.transfer_id,
      completed_transfer_base.rail_tx_id,
      completed_transfer_base.completed_at_utc,
      (
        v_settlement_mode IN ('CSV_SETTLEMENT', 'EXTERNAL_SETTLEMENT')
        OR EXISTS (
          SELECT 1
          FROM public.pay_bank_transfer_events AS completed_event
          WHERE completed_event.pay_bank_transfer_id = completed_transfer_base.transfer_id
            AND upper(btrim(coalesce(completed_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'WEBHOOK', 'POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT')
            AND (
              upper(btrim(coalesce(completed_event.normalised_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED')
              OR upper(btrim(coalesce(completed_event.provider_state, ''))) IN ('COMPLETED', 'SETTLED', 'PAID', 'SUCCESS', 'SUCCEEDED')
            )
            AND EXISTS (
              SELECT 1
              FROM (VALUES
                (completed_event.provider_event_id),
                (completed_event.provider_reference),
                (completed_event.raw_payload #>> '{provider_event_id}'),
                (completed_event.raw_payload #>> '{provider_reference}'),
                (completed_event.raw_payload #>> '{provider_submission_id}'),
                (completed_event.raw_payload #>> '{submission_id}'),
                (completed_event.raw_payload #>> '{rail_submission_id}'),
                (completed_event.raw_payload #>> '{provider_payment_id}'),
                (completed_event.raw_payload #>> '{payment_id}'),
                (completed_event.raw_payload #>> '{external_payment_id}'),
                (completed_event.raw_payload #>> '{revolut_payment_id}'),
                (completed_event.raw_payload #>> '{provider_transfer_id}'),
                (completed_event.raw_payload #>> '{transfer_id}'),
                (completed_event.raw_payload #>> '{external_transfer_id}'),
                (completed_event.raw_payload #>> '{provider_transaction_id}'),
                (completed_event.raw_payload #>> '{transaction_id}')
              ) AS completed_event_identifier(identifier_value)
              WHERE NULLIF(BTRIM(COALESCE(completed_event_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (NULLIF(BTRIM(COALESCE(completed_event_identifier.identifier_value, '')), '') = ANY(completed_transfer_base.local_identity_values))
            )
        )
        OR (
          completed_transfer_base.last_update_was_provider_evidence IS TRUE
          AND EXISTS (
            SELECT 1
            FROM (VALUES
              (completed_transfer_base.rail_tx_id),
              (completed_transfer_base.rail_meta_json #>> '{provider_event_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_reference}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{rail_submission_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{external_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{revolut_payment_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{external_transfer_id}'),
              (completed_transfer_base.rail_meta_json #>> '{provider_transaction_id}'),
              (completed_transfer_base.rail_meta_json #>> '{transaction_id}')
            ) AS completed_transfer_identifier(identifier_value)
            WHERE NULLIF(BTRIM(COALESCE(completed_transfer_identifier.identifier_value, '')), '') IS NOT NULL
              AND NOT (NULLIF(BTRIM(COALESCE(completed_transfer_identifier.identifier_value, '')), '') = ANY(completed_transfer_base.local_identity_values))
          )
        )
      ) AS has_external_completion_evidence
    FROM completed_transfer_base
  )
  SELECT
    externally_supported_completed.transfer_id,
    externally_supported_completed.rail_tx_id,
    externally_supported_completed.completed_at_utc
  FROM externally_supported_completed
  WHERE externally_supported_completed.has_external_completion_evidence IS TRUE;

  select
    count(*)::int,
    (
      select nullif(btrim(coalesce(completed_transfer_ref.rail_tx_id, bank_transfer_ref.rail_tx_id, '')), '')
      from pg_temp._tmp_settle_external_completed_transfers as completed_transfer_ref
      join public.pay_bank_transfers as bank_transfer_ref
        on bank_transfer_ref.id = completed_transfer_ref.transfer_id
       and bank_transfer_ref.pay_batch_id = p_pay_batch_id
      where nullif(btrim(coalesce(completed_transfer_ref.rail_tx_id, bank_transfer_ref.rail_tx_id, '')), '') is not null
      order by coalesce(completed_transfer_ref.completed_at_utc, bank_transfer_ref.completed_at_utc) desc nulls last, bank_transfer_ref.id desc
      limit 1
    ),
    (
      select coalesce(completed_transfer_ts.completed_at_utc, bank_transfer_ts.completed_at_utc)
      from pg_temp._tmp_settle_external_completed_transfers as completed_transfer_ts
      join public.pay_bank_transfers as bank_transfer_ts
        on bank_transfer_ts.id = completed_transfer_ts.transfer_id
       and bank_transfer_ts.pay_batch_id = p_pay_batch_id
      order by coalesce(completed_transfer_ts.completed_at_utc, bank_transfer_ts.completed_at_utc) desc nulls last, bank_transfer_ts.id desc
      limit 1
    )
  into
    v_completed_transfer_count,
    v_detected_execution_commit_ref,
    v_detected_execution_committed_at_utc
  from pg_temp._tmp_settle_external_completed_transfers as completed_transfer_count_row;

  if coalesce(v_completed_transfer_count, 0) > 0 then
    v_execution_commit_state := 'COMMITTED';
    v_execution_commit_ref := coalesce(v_execution_commit_ref, v_detected_execution_commit_ref);
    v_execution_committed_at_utc := coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc, v_now);
  end if;

  select count(distinct pbi_chk.pay_bank_transfer_id)::int
  into v_linked_transfer_ct
  from public.pay_batch_items pbi_chk
  join public.pay_batch_candidates pbc_chk
    on pbc_chk.id = pbi_chk.pay_batch_candidate_id
  where pbc_chk.pay_batch_id = p_pay_batch_id
    and pbi_chk.item_type <> 'DEBT_CREATED'
    and pbi_chk.is_voided = false
    and pbi_chk.pay_bank_transfer_id is not null;

  select exists (
    select 1
    from public.pay_batch_candidates pbc_pos
    where pbc_pos.pay_batch_id = p_pay_batch_id
      and coalesce(pbc_pos.net_bank_amount,0) > 0
    limit 1
  )
  into v_has_pos_net;

  if v_linked_transfer_ct = 0 and v_has_pos_net then
    raise exception 'STATE_INCONSISTENT: positive net_bank_amount but no transfers';
  end if;

  create temp table if not exists _tmp_newly_settled_candidates (
    candidate_id uuid primary key
  ) on commit drop;

  truncate table _tmp_newly_settled_candidates;

  with cand_transfers as (
    select
      pbc.candidate_id as candidate_id,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.is_voided = false
          and pbi.pay_bank_transfer_id is not null
      ) as total_transfers,
      count(distinct pbi.pay_bank_transfer_id) filter (
        where pbi.item_type <> 'DEBT_CREATED'
          and pbi.is_voided = false
          and pbi.pay_bank_transfer_id is not null
          and external_completed_candidate_transfer.transfer_id is not null
      ) as completed_transfers
    from public.pay_batch_candidates pbc
    left join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join pg_temp._tmp_settle_external_completed_transfers as external_completed_candidate_transfer
      on external_completed_candidate_transfer.transfer_id = pbi.pay_bank_transfer_id
    where pbc.pay_batch_id = p_pay_batch_id
    group by pbc.candidate_id
  ),
  eligible as (
    select
      ct.candidate_id
    from cand_transfers ct
    join public.pay_batch_candidates pbc2
      on pbc2.pay_batch_id = p_pay_batch_id
     and pbc2.candidate_id = ct.candidate_id
    where (coalesce(pbc2.settled_at_utc, null) is null)
      and (
        (ct.total_transfers = 0 and coalesce(pbc2.net_bank_amount,0) <= 0)
        or (ct.total_transfers > 0 and ct.total_transfers = ct.completed_transfers)
      )
  )
  insert into _tmp_newly_settled_candidates(candidate_id)
  select e.candidate_id
  from eligible e;

  update public.pay_batch_candidates pbc
  set
    settlement_status = 'SETTLED',
    settled_at_utc = v_now,
    settled_via = upper(coalesce(v_batch.rail_provider_snapshot,'RAIL')),
    settled_note = null
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t);

  select coalesce(jsonb_agg(t.candidate_id::text order by t.candidate_id), '[]'::jsonb)
  into v_newly_settled_candidates
  from _tmp_newly_settled_candidates t;

  SELECT public._pay_manual_adjustment_carry_forward_mark_consumed(
    p_pay_batch_id,
    NULL::uuid[],
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'pay_bank_transfer_ids', COALESCE((
        SELECT jsonb_agg(DISTINCT completed_transfer_rows.transfer_id::text ORDER BY completed_transfer_rows.transfer_id::text)
        FROM pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_rows
      ), '[]'::jsonb),
      'pay_batch_item_ids', COALESCE((
        SELECT jsonb_agg(DISTINCT item_rows.id::text ORDER BY item_rows.id::text)
        FROM public.pay_batch_items AS item_rows
        JOIN public.pay_batch_candidates AS candidate_rows
          ON candidate_rows.id = item_rows.pay_batch_candidate_id
        JOIN pg_temp._tmp_settle_external_completed_transfers AS completed_transfer_rows
          ON completed_transfer_rows.transfer_id = item_rows.pay_bank_transfer_id
        WHERE candidate_rows.pay_batch_id = p_pay_batch_id
      ), '[]'::jsonb)
    ),
    jsonb_build_object('final_paid', true, 'cash_state', 'FINAL_PAID', 'source', 'pay_settle_rail'),
    p_actor_user_id
  )
  INTO v_carry_forward_mark_result;

  v_consumed_carry_forward_count := v_consumed_carry_forward_count + COALESCE(NULLIF(v_carry_forward_mark_result->>'consumed_count', '')::integer, 0);

  with needed_timesheets as (
    select distinct
      pbi.timesheet_id as timesheet_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
      and pbi.timesheet_id is not null
  ),
  have_snap as (
    select distinct
      pbs.timesheet_id as timesheet_id
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
  ),
  missing as (
    select n.timesheet_id
    from needed_timesheets n
    left join have_snap h
      on h.timesheet_id = n.timesheet_id
    where h.timesheet_id is null
  )
  select coalesce(jsonb_agg(m.timesheet_id::text order by m.timesheet_id), '[]'::jsonb)
  into v_missing_timesheets
  from missing m;

  if jsonb_array_length(v_missing_timesheets) > 0 then
    raise exception 'pay_settle_rail: MISSING_FROZEN_SNAPSHOTS for timesheets %', v_missing_timesheets::text;
  end if;

  with snap as (
    select
      pbs.timesheet_id,
      pbs.target_snapshot_json
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
  ),
  ambig as (
    select
      s.timesheet_id
    from snap s
    group by s.timesheet_id
    having count(distinct s.target_snapshot_json) > 1
  )
  select coalesce(jsonb_agg(a.timesheet_id::text order by a.timesheet_id), '[]'::jsonb)
  into v_ambig_timesheets
  from ambig a;

  if jsonb_array_length(v_ambig_timesheets) > 0 then
    raise exception 'pay_settle_rail: AMBIGUOUS_TARGET_SNAPSHOT for timesheets %', v_ambig_timesheets::text;
  end if;

  with chosen as (
    select distinct on (pbs.timesheet_id)
      pbs.timesheet_id,
      pbs.target_snapshot_json,
      pbs.signature
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    order by pbs.timesheet_id, pbs.created_at_utc desc, pbs.id
  )
  insert into public.timesheet_pay_state_history(
    timesheet_id,
    pay_batch_id,
    settled_at_utc,
    snapshot_json,
    signature
  )
  select
    c.timesheet_id,
    p_pay_batch_id,
    v_now,
    c.target_snapshot_json,
    c.signature
  from chosen c;

  with chosen as (
    select distinct on (pbs.timesheet_id)
      pbs.timesheet_id,
      pbs.target_snapshot_json,
      pbs.signature
    from public.pay_batch_timesheet_snapshots pbs
    where pbs.pay_batch_id = p_pay_batch_id
      and pbs.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    order by pbs.timesheet_id, pbs.created_at_utc desc, pbs.id
  )
  insert into public.timesheet_pay_state(
    timesheet_id,
    last_settled_snapshot_json,
    last_settled_signature,
    last_settled_pay_batch_id,
    last_settled_at_utc
  )
  select
    c.timesheet_id,
    c.target_snapshot_json,
    c.signature,
    p_pay_batch_id,
    v_now
  from chosen c
  on conflict (timesheet_id) do update
  set
    last_settled_snapshot_json = excluded.last_settled_snapshot_json,
    last_settled_signature = excluded.last_settled_signature,
    last_settled_pay_batch_id = excluded.last_settled_pay_batch_id,
    last_settled_at_utc = excluded.last_settled_at_utc;

  update public.pay_advance_reservations par
  set
    status = 'SETTLED',
    settled_at_utc = coalesce(par.settled_at_utc, v_now),
    updated_by_user_id = p_actor_user_id
  from public.pay_batch_items pbi,
       public.pay_batch_candidates pbc
  where par.pay_batch_id = p_pay_batch_id
    and par.pay_batch_item_id = pbi.id
    and pbc.id = pbi.pay_batch_candidate_id
    and pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    and upper(coalesce(par.status,'')) = 'COMMITTED';

  create temp table if not exists _tmp_component_settle (
    finance_component_id uuid not null primary key,
    finance_case_id uuid null,
    settled_source_amount numeric not null
  ) on commit drop;

  truncate table _tmp_component_settle;

  with settled_source as (
    select
      coalesce(
        par.finance_component_id,
        pbi.finance_component_id,
        fb.finance_component_id
      ) as finance_component_id,
      coalesce(
        par.finance_case_id,
        pbi.finance_case_id,
        fb.finance_case_id
      ) as finance_case_id,
      round(
        sum(
          coalesce(
            par.reserved_source_amount,
            pbi.frozen_source_amount,
            abs(coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, par.reserved_amount, 0))
          )
        ),
        2
      ) as settled_source_amount
    from public.pay_advance_reservations par
    join public.pay_batch_items pbi
      on pbi.id = par.pay_batch_item_id
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
     and pbc.pay_batch_id = p_pay_batch_id
    left join lateral (
      select
        pfc_fb.id as finance_component_id,
        pfc_fb.finance_case_id as finance_case_id
      from public.pay_finance_case_components pfc_fb
      where pfc_fb.finance_case_id = coalesce(par.finance_case_id, pbi.finance_case_id)
        and pfc_fb.component_key_type = coalesce(
          nullif(
            btrim(
              coalesce(
                par.frozen_component_key_type,
                pbi.frozen_component_key_type,
                par.frozen_component_snapshot_json->>'component_key_type',
                pbi.frozen_component_snapshot_json->>'component_key_type',
                ''
              )
            ),
            ''
          ),
          '§NO_COMPONENT_KEY§'
        )
        and pfc_fb.component_key_value = coalesce(
          nullif(
            btrim(
              coalesce(
                par.frozen_component_key_value,
                pbi.frozen_component_key_value,
                par.frozen_component_snapshot_json->>'component_key_value',
                pbi.frozen_component_snapshot_json->>'component_key_value',
                ''
              )
            ),
            ''
          ),
          '§NO_COMPONENT_VALUE§'
        )
      order by
        pfc_fb.closed_at_utc nulls first,
        pfc_fb.updated_at_utc desc,
        pfc_fb.created_at_utc desc,
        pfc_fb.id desc
      limit 1
    ) fb on coalesce(par.finance_component_id, pbi.finance_component_id) is null
    where par.pay_batch_id = p_pay_batch_id
      and upper(coalesce(par.status,'')) = 'SETTLED'
      and par.settled_at_utc = v_now
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    group by
      coalesce(
        par.finance_component_id,
        pbi.finance_component_id,
        fb.finance_component_id
      ),
      coalesce(
        par.finance_case_id,
        pbi.finance_case_id,
        fb.finance_case_id
      )
    having coalesce(
      coalesce(
        par.finance_component_id,
        pbi.finance_component_id,
        fb.finance_component_id
      ),
      '00000000-0000-0000-0000-000000000000'::uuid
    ) <> '00000000-0000-0000-0000-000000000000'::uuid
  )
  insert into _tmp_component_settle(finance_component_id, finance_case_id, settled_source_amount)
  select
    ss.finance_component_id,
    ss.finance_case_id,
    ss.settled_source_amount
  from settled_source ss
  where ss.finance_component_id is not null
    and ss.settled_source_amount > 0;

  create temp table if not exists _tmp_component_settle_apply (
    finance_component_id uuid not null primary key,
    finance_case_id uuid null,
    classification public.pay_finance_component_classification_enum not null,
    settled_source_amount numeric not null,
    remaining_before numeric not null,
    remaining_after numeric not null
  ) on commit drop;

  truncate table _tmp_component_settle_apply;

  insert into _tmp_component_settle_apply(
    finance_component_id,
    finance_case_id,
    classification,
    settled_source_amount,
    remaining_before,
    remaining_after
  )
  select
    pfc.id,
    pfc.finance_case_id,
    pfc.classification,
    tcs.settled_source_amount,
    round(coalesce(pfc.remaining_source_amount, 0), 2) as remaining_before,
    round(greatest(coalesce(pfc.remaining_source_amount, 0) - coalesce(tcs.settled_source_amount, 0), 0), 2) as remaining_after
  from _tmp_component_settle tcs
  join public.pay_finance_case_components pfc
    on pfc.id = tcs.finance_component_id;

  update public.pay_finance_case_components pfc
  set
    remaining_source_amount = csa.remaining_after,
    resolved_at_utc = case
      when csa.remaining_after <= 0 then coalesce(pfc.resolved_at_utc, v_now)
      else pfc.resolved_at_utc
    end,
    updated_at_utc = v_now
  from _tmp_component_settle_apply csa
  where pfc.id = csa.finance_component_id;

  select
    count(*)::int,
    round(coalesce(sum(csa.settled_source_amount), 0), 2)
  into
    v_component_settled_count,
    v_component_settled_amount
  from _tmp_component_settle_apply csa;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    csa.finance_case_id,
    csa.finance_component_id,
    'COMPONENT_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    null::uuid,
    jsonb_build_object(
      'remaining_source_amount', csa.remaining_before
    ),
    jsonb_build_object(
      'remaining_source_amount', csa.remaining_after,
      'settled_source_amount', csa.settled_source_amount,
      'classification', csa.classification::text
    ),
    'rail_settlement',
    null
  from _tmp_component_settle_apply csa;

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    par.finance_case_id,
    par.finance_component_id,
    'RESERVATION_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    par.id,
    jsonb_build_object('reservation_status', 'COMMITTED'),
    jsonb_build_object('reservation_status', 'SETTLED', 'settled_at_utc', v_now::text),
    'rail_settlement',
    null
  from public.pay_advance_reservations par
  where par.pay_batch_id = p_pay_batch_id
    and upper(coalesce(par.status,'')) = 'SETTLED'
    and par.settled_at_utc = v_now;

  create temp table if not exists _tmp_repay_taken (
    finance_case_id uuid not null,
    repayment_week_start date null,
    item_type text not null,
    taken_amount numeric not null
  ) on commit drop;

  truncate table _tmp_repay_taken;

  insert into _tmp_repay_taken(finance_case_id, repayment_week_start, item_type, taken_amount)
  select
    coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ) as finance_case_id,
    pbi.repayment_week_start,
    pbi.item_type,
    round(sum(abs(coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, 0))),2) as taken_amount
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
    and pbi.is_voided = false
    and pbi.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')
    and coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ) is not null
  group by
    coalesce(
      pbi.finance_case_id,
      nullif(btrim(split_part(coalesce(pbi.source_ref,''), ':', 2)),'')::uuid
    ),
    pbi.repayment_week_start,
    pbi.item_type
  having round(sum(abs(coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, 0))),2) > 0;

  for v_adv_id in
    select distinct trt.finance_case_id
    from _tmp_repay_taken trt
    where trt.finance_case_id is not null
  loop
    select
      pa.schedule_json,
      pa.outstanding_amount,
      pa.next_due_week_start,
      pa.case_type,
      pa.minimum_earnings_threshold,
      pa.take_home_floor_override,
      (pa.cleared_at_utc is not null) as was_cleared
    into
      v_old_sched,
      v_old_out,
      v_old_next,
      v_case_type,
      v_min_earnings_threshold,
      v_take_home_floor_override,
      v_was_cleared
    from public.pay_advances pa
    where pa.id = v_adv_id
    for update;

    if v_old_sched is null then
      v_old_sched := '[]'::jsonb;
    end if;

    select round(coalesce(sum(trt.taken_amount),0),2)
    into v_total_taken
    from _tmp_repay_taken trt
    where trt.finance_case_id = v_adv_id;

    v_new_out := round(greatest(coalesce(v_old_out,0) - coalesce(v_total_taken,0), 0), 2);

    if v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
       or v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      with taken_map as (
        select
          trt.repayment_week_start as week_start,
          round(sum(trt.taken_amount),2) as taken_amount
        from _tmp_repay_taken trt
        where trt.finance_case_id = v_adv_id
        group by trt.repayment_week_start
      ),
      expanded as (
        select
          e.elem as elem,
          nullif(e.elem->>'week_start','')::date as wk,
          coalesce(nullif(e.elem->>'amount','')::numeric,0) as amt
        from jsonb_array_elements(coalesce(v_old_sched,'[]'::jsonb)) e(elem)
      ),
      rewritten as (
        select
          case
            when em.wk is not null
             and tm.week_start is not null
             and em.wk = tm.week_start
             and em.amt < 0
            then jsonb_set(
              em.elem,
              '{amount}',
              to_jsonb(round(em.amt + tm.taken_amount, 2)),
              true
            )
            else em.elem
          end as elem
        from expanded em
        left join taken_map tm
          on tm.week_start = em.wk
      )
      select coalesce(jsonb_agg(r.elem), '[]'::jsonb)
      into v_new_sched
      from rewritten r;

      with expanded2 as (
        select
          nullif(e2.elem->>'week_start','')::date as wk,
          coalesce(nullif(e2.elem->>'amount','')::numeric,0) as amt
        from jsonb_array_elements(coalesce(v_new_sched,'[]'::jsonb)) e2(elem)
      )
      select min(ex2.wk)
      into v_new_next
      from expanded2 ex2
      where ex2.wk is not null
        and ex2.amt < 0;
    else
      v_new_sched := v_old_sched;
      v_new_next := v_old_next;
    end if;

    select exists (
      select 1
      from public.pay_item_snoozes pis
      where pis.cleared_at_utc is null
        and pis.source_ref = ('advance:' || v_adv_id::text)
        and (
          pis.snooze_until_date is null
          or pis.snooze_until_date >= coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)
        )
      limit 1
    )
    into v_snooze_active;

    if v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
       or v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      insert into public.pay_finance_case_events(
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      select
        v_adv_id,
        'RECOVERY_SHORTFALL',
        v_now,
        p_actor_user_id,
        p_pay_batch_id,
        null::uuid,
        jsonb_build_object(
          'week_start', exp.week_start::text,
          'scheduled_due_amount', exp.expected_due,
          'taken_amount', coalesce(tkn.taken_amount,0)
        ),
        jsonb_build_object(
          'week_start', exp.week_start::text,
          'scheduled_due_amount', exp.expected_due,
          'taken_amount', coalesce(tkn.taken_amount,0),
          'remaining_due_amount', round(greatest(exp.expected_due - coalesce(tkn.taken_amount,0),0),2)
        ),
        case
          when v_snooze_active then 'SNOOZED'
          when coalesce(v_take_home_floor_override,0) > 0 then 'MIN_TAKE_HOME_FLOOR'
          when coalesce(v_min_earnings_threshold,0) > 0 then 'INSUFFICIENT_EARNINGS'
          else 'INSUFFICIENT_EARNINGS'
        end,
        null
      from (
        select
          nullif(elem->>'week_start','')::date as week_start,
          abs(coalesce(nullif(elem->>'amount','')::numeric,0)) as expected_due
        from jsonb_array_elements(coalesce(v_old_sched,'[]'::jsonb)) elem
        where nullif(elem->>'week_start','') is not null
          and coalesce(nullif(elem->>'amount','')::numeric,0) < 0
      ) exp
      left join (
        select trt.repayment_week_start as week_start, round(sum(trt.taken_amount),2) as taken_amount
        from _tmp_repay_taken trt
        where trt.finance_case_id = v_adv_id
        group by trt.repayment_week_start
      ) tkn
        on tkn.week_start = exp.week_start
      where round(greatest(exp.expected_due - coalesce(tkn.taken_amount,0),0),2) > 0;
    end if;

    update public.pay_advances pa2
    set
      schedule_json = coalesce(v_new_sched,'[]'::jsonb),
      outstanding_amount = v_new_out,
      next_due_week_start = v_new_next,
      status = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then 'PAID_OFF'::public.pay_advance_status_enum
        else pa2.status
      end,
      cleared_at_utc = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then coalesce(pa2.cleared_at_utc, v_now)
        else pa2.cleared_at_utc
      end,
      cleared_by_user_id = case
        when v_case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum)
             and v_new_out <= 0 then coalesce(pa2.cleared_by_user_id, p_actor_user_id)
        else pa2.cleared_by_user_id
      end,
      updated_at = v_now
    where pa2.id = v_adv_id;

    insert into public.pay_advance_patches(
      advance_id,
      pay_batch_id,
      old_outstanding_amount,
      new_outstanding_amount,
      old_schedule_json,
      new_schedule_json,
      old_next_due_week_start,
      new_next_due_week_start
    )
    values (
      v_adv_id,
      p_pay_batch_id,
      v_old_out,
      v_new_out,
      v_old_sched,
      v_new_sched,
      v_old_next,
      v_new_next
    );

    insert into public.pay_finance_case_events(
      finance_case_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    values (
      v_adv_id,
      'RECOVERY_SETTLED',
      v_now,
      p_actor_user_id,
      p_pay_batch_id,
      null::uuid,
      jsonb_build_object(
        'outstanding_amount', v_old_out,
        'next_due_week_start', case when v_old_next is null then null else v_old_next::text end,
        'schedule_json', v_old_sched
      ),
      jsonb_build_object(
        'outstanding_amount', v_new_out,
        'next_due_week_start', case when v_new_next is null then null else v_new_next::text end,
        'schedule_json', v_new_sched,
        'taken_amount', v_total_taken,
        'case_type', v_case_type::text
      ),
      'rail_settlement',
      null
    );

    if v_new_out <= 0 then
      insert into public.pay_finance_case_events(
        finance_case_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      values (
        v_adv_id,
        'CASE_CLEARED',
        v_now,
        p_actor_user_id,
        p_pay_batch_id,
        null::uuid,
        jsonb_build_object(
          'outstanding_amount', v_old_out,
          'was_cleared', v_was_cleared
        ),
        jsonb_build_object(
          'outstanding_amount', v_new_out,
          'cleared_at_utc', v_now::text,
          'cleared_by_user_id', p_actor_user_id::text
        ),
        'rail_settlement',
        null
      );
    end if;

    if v_case_type = 'OVERPAYMENT'::public.pay_finance_case_type_enum then
      v_overpay_patched_ct := v_overpay_patched_ct + 1;
    elsif v_case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum then
      v_payment_advance_recovery_patched_ct := v_payment_advance_recovery_patched_ct + 1;
    elsif v_case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
      v_manual_debt_patched_ct := v_manual_debt_patched_ct + 1;
    end if;
  end loop;

  with affected_component_cases as (
    select distinct csa.finance_case_id
    from _tmp_component_settle_apply csa
    where csa.finance_case_id is not null
    union
    select distinct trt.finance_case_id
    from _tmp_repay_taken trt
    where trt.finance_case_id is not null
      and exists (
        select 1
        from public.pay_finance_case_components pfc_exists
        where pfc_exists.finance_case_id = trt.finance_case_id
        limit 1
      )
  ),
  reconciled_component_cases as (
    select
      afc.finance_case_id,
      round(coalesce(pa.outstanding_amount, 0), 2) as case_outstanding_amount,
      round(coalesce(sum(coalesce(pfc.remaining_source_amount, 0)), 0), 2) as open_component_remaining_source_amount,
      count(pfc.id)::int as open_component_count
    from affected_component_cases afc
    join public.pay_advances pa
      on pa.id = afc.finance_case_id
    left join public.pay_finance_case_components pfc
      on pfc.finance_case_id = afc.finance_case_id
     and pfc.closed_at_utc is null
    where exists (
      select 1
      from public.pay_finance_case_components pfc_any
      where pfc_any.finance_case_id = afc.finance_case_id
      limit 1
    )
    group by
      afc.finance_case_id,
      pa.outstanding_amount
  ),
  reconciliation_bad as (
    select
      rcc.finance_case_id,
      rcc.case_outstanding_amount,
      rcc.open_component_remaining_source_amount,
      rcc.open_component_count,
      round(rcc.case_outstanding_amount - rcc.open_component_remaining_source_amount, 2) as mismatch_amount
    from reconciled_component_cases rcc
    where abs(round(rcc.case_outstanding_amount - rcc.open_component_remaining_source_amount, 2)) > 0.01
  )
  select
    (select count(*)::int from reconciled_component_cases),
    count(*)::int,
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'finance_case_id', reconciliation_bad.finance_case_id::text,
          'case_outstanding_amount', reconciliation_bad.case_outstanding_amount,
          'open_component_remaining_source_amount', reconciliation_bad.open_component_remaining_source_amount,
          'open_component_count', reconciliation_bad.open_component_count,
          'mismatch_amount', reconciliation_bad.mismatch_amount
        )
        order by reconciliation_bad.finance_case_id::text
      ),
      '[]'::jsonb
    )
  into
    v_component_reconciliation_checked_ct,
    v_component_reconciliation_bad_ct,
    v_component_reconciliation_bad
  from reconciliation_bad;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_RAIL:COMPONENT_RECONCILIATION_RESULT',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
        'mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0),
        'mismatches', v_component_reconciliation_bad
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  if coalesce(v_component_reconciliation_bad_ct, 0) > 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_SETTLE_RAIL_COMPONENT_RECONCILIATION_MISMATCH',
      'pay_batch_id', p_pay_batch_id::text,
      'message', 'Finance case outstanding amount does not reconcile to open component remaining_source_amount after settlement.',
      'mismatches', v_component_reconciliation_bad
    )::text;
  end if;


  with payouts as (
    select distinct
      coalesce(
        pbi.finance_case_id,
        nullif(btrim(replace(coalesce(pbi.source_ref,''), 'advance:', '')),'')::uuid
      ) as finance_case_id,
      pbi.pay_bank_transfer_id as transfer_id,
      pbi.item_type
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    join pg_temp._tmp_settle_external_completed_transfers as external_completed_payout_transfer
      on external_completed_payout_transfer.transfer_id = pbt.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and pbi.is_voided = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT')
      and pbi.pay_bank_transfer_id is not null
      and coalesce(
        pbi.finance_case_id,
        nullif(btrim(replace(coalesce(pbi.source_ref,''), 'advance:', '')),'')::uuid
      ) is not null
  ),
  upd as (
    update public.pay_advances pa
    set
      payout_status = 'PAID'::public.pay_advance_payout_status_enum,
      payout_pay_batch_id = p_pay_batch_id,
      payout_transfer_id = p.transfer_id,
      updated_at = v_now
    from payouts p
    where pa.id = p.finance_case_id
      and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum)
      and coalesce(pa.payout_status::text,'') <> 'PAID'
    returning pa.id, pa.case_type, p.transfer_id, p.item_type
  )
  select count(*)::int
  into v_payout_cases_marked_paid_ct
  from upd;

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    reservation_id,
    before_json,
    after_json,
    reason,
    note
  )
  select
    upd.id,
    'PAYOUT_SETTLED',
    v_now,
    p_actor_user_id,
    p_pay_batch_id,
    null::uuid,
    jsonb_build_object('payout_status', 'PENDING_OR_COMMITTED'),
    jsonb_build_object(
      'payout_status', 'PAID',
      'payout_transfer_id', upd.transfer_id::text,
      'item_type', upd.item_type,
      'case_type', upd.case_type::text
    ),
    'rail_settlement',
    null
  from (
    select distinct
      pa.id,
      pa.case_type,
      pbi.pay_bank_transfer_id as transfer_id,
      pbi.item_type
    from public.pay_advances pa
    join public.pay_batch_items pbi
      on pbi.finance_case_id = pa.id
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_bank_transfers pbt
      on pbt.id = pbi.pay_bank_transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    join pg_temp._tmp_settle_external_completed_transfers as external_completed_payout_event_transfer
      on external_completed_payout_event_transfer.transfer_id = pbt.id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
      and pbi.is_voided = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT')
      and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  ) upd;

  with payable_transfer_ids as (
    select distinct
      pbi.pay_bank_transfer_id as transfer_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
      and pbi.pay_bank_transfer_id is not null
  ),
  stats as (
    select
      count(*)::int as total_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('PENDING','PROCESSING','UNKNOWN') then 1 else 0 end)::int as pending_ct,
      sum(case when external_completed_status_transfer.transfer_id is not null then 1 else 0 end)::int as completed_ct,
      sum(case when external_completed_status_transfer.transfer_id is not null then 1 else 0 end)::int as settled_evidence_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('FAILED','DECLINED','REJECTED','CANCELLED') then 1 else 0 end)::int as failed_ct,
      sum(case when upper(coalesce(pbt.status,'')) in ('RETURNED','REVERTED') then 1 else 0 end)::int as returned_ct,
      sum(case when upper(coalesce(pbt.status,'')) = 'BLOCKED' then 1 else 0 end)::int as blocked_ct
    from payable_transfer_ids pti
    join public.pay_bank_transfers pbt
      on pbt.id = pti.transfer_id
     and pbt.pay_batch_id = p_pay_batch_id
    left join pg_temp._tmp_settle_external_completed_transfers as external_completed_status_transfer
      on external_completed_status_transfer.transfer_id = pbt.id
  )
  select
    case
      when coalesce(s.total_ct, 0) = 0 then 'SETTLED'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) = 0
       and coalesce(s.blocked_ct,0) = 0
       and coalesce(s.returned_ct,0) = 0
       and coalesce(s.settled_evidence_ct,0) >= coalesce(s.total_ct,0)
        then 'SETTLED'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) = 0
       and coalesce(s.blocked_ct,0) = 0
       and coalesce(s.returned_ct,0) > 0
       and coalesce(s.settled_evidence_ct,0) > 0
        then 'SETTLED'
      when coalesce(s.pending_ct,0) = 0
       and coalesce(s.failed_ct,0) > 0
       and coalesce(s.returned_ct,0) = 0
        then 'FAILED'
      else 'PARTIAL'
    end
  into v_batch_status
  from stats s;

  update public.pay_batches pb2
  set
    status = v_batch_status,
    completed_at_utc = case when v_batch_status = 'SETTLED' then coalesce(pb2.completed_at_utc, v_now) else pb2.completed_at_utc end,
    last_status_checked_at_utc = v_now,
    execution_commit_state = case
      when coalesce(v_completed_transfer_count, 0) > 0 then 'COMMITTED'
      else coalesce(nullif(btrim(coalesce(pb2.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    end,
    execution_commit_ref = case
      when coalesce(v_completed_transfer_count, 0) > 0 then coalesce(pb2.execution_commit_ref, v_execution_commit_ref)
      else pb2.execution_commit_ref
    end,
    execution_committed_at_utc = case
      when coalesce(v_completed_transfer_count, 0) > 0 then coalesce(pb2.execution_committed_at_utc, v_execution_committed_at_utc, v_now)
      else pb2.execution_committed_at_utc
    end,
    settlement_confirmation_json = case
      when coalesce(v_completed_transfer_count, 0) > 0 then
        coalesce(pb2.settlement_confirmation_json, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
          'settlement_mode', v_settlement_mode,
          'settled_at_utc', v_now::text,
          'settled_by_user_id', p_actor_user_id::text,
          'payment_date', case when v_effective_payment_date is null then null else v_effective_payment_date::text end,
          'bank_confirm_ref', coalesce(v_execution_commit_ref, pb2.execution_commit_ref),
          'external_comment', nullif(btrim(coalesce(v_execution_intent_json->>'external_settlement_comment', '')), ''),
          'csv_export_hash', nullif(btrim(coalesce(v_execution_intent_json->>'bank_csv_export_hash', '')), ''),
          'suppress_remittances', v_suppress_remittances,
          'remittances_suppressed_at_utc', case when v_suppress_remittances then v_now::text else null end,
          'auth_request_id', nullif(btrim(coalesce(v_execution_intent_json->>'auth_request_id', '')), '')
        ))
      else pb2.settlement_confirmation_json
    end
  where pb2.id = p_pay_batch_id;

  select exists (
    select 1
    from public.pay_batch_candidates pbc_unsent
    where pbc_unsent.pay_batch_id = p_pay_batch_id
      and pbc_unsent.remittance_sent_at_utc is null
    limit 1
  )
  into v_catchup_needed;

  if v_suppress_remittances = true then
    v_comm_trigger_status := 'SUPPRESSED_BY_EXECUTION_INTENT';
    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'execution_mode', v_settlement_mode
    );
    v_suppression_audit_json := jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'batch_kind_fixed', upper(coalesce(v_batch.batch_kind_fixed,'')),
      'settlement_mode', v_settlement_mode,
      'suppress_remittances', true,
      'suppressed_at_utc', v_now::text,
      'auth_request_id', nullif(btrim(coalesce(v_execution_intent_json->>'auth_request_id', '')), '')
    );
    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      values (
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_SETTLEMENT_COMMUNICATION_SUPPRESSED',
        null,
        v_suppression_audit_json,
        'suppressed_by_execution_intent'
      );
    exception when others then
      null;
    end;
  elsif v_catchup_needed then
    v_comm_trigger_status := 'REMITTANCE_READY_DEFERRED_TO_OPERATION';
    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false,
      'dispatch_required', true,
      'remittance_ready', true,
      'remittance_queued', false,
      'deferred_to_operation', true,
      'requires_remittance_operation', true,
      'operation_type', 'REMITTANCE_QUEUE',
      'source_rpc', 'pay_settle_rail',
      'message', 'Settlement is remittance-ready. Queueing is handled by the separate scalable remittance operation.'
    );

    begin
      insert into public.audit_events(
        actor_user_id,
        object_type,
        object_id_text,
        action,
        before_json,
        after_json,
        reason
      )
      values (
        p_actor_user_id,
        'pay_batch',
        p_pay_batch_id::text,
        'PAY_BATCH_SETTLEMENT_REMITTANCE_DEFERRED_TO_OPERATION',
        null,
        jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'batch_kind_fixed', upper(coalesce(v_batch.batch_kind_fixed,'')),
          'trigger_status', v_comm_trigger_status,
          'result', coalesce(v_comm_result, '{}'::jsonb)
        ),
        'settlement_remittance_deferred_to_operation'
      );
    exception when others then
      null;
    end;
  else
    v_comm_trigger_status := 'NO_CATCHUP_NEEDED';
    v_comm_error := null;
    v_comm_result := jsonb_build_object(
      'ok', true,
      'trigger_status', v_comm_trigger_status,
      'message_kind', case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
      'catchup_send', false
    );
  end if;

  v_worker_communications := jsonb_build_object(
    'primary_trigger_stage', 'COMMIT',
    'catchup_attempted_at_settlement', (v_catchup_needed and v_suppress_remittances = false),
    'message_kind', coalesce(nullif(btrim(coalesce(v_comm_result->>'message_kind','')), ''), case when upper(btrim(coalesce(v_batch.batch_kind_fixed,''))) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end),
    'trigger_status', v_comm_trigger_status,
    'error', v_comm_error,
    'result', coalesce(v_comm_result, '{}'::jsonb),
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
    'remittance_ready', (v_catchup_needed and v_suppress_remittances = false),
    'remittance_queued', false,
    'requires_remittance_operation', (v_catchup_needed and v_suppress_remittances = false),
    'execution_mode', v_settlement_mode,
    'suppress_remittances', v_suppress_remittances
  );

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_pending_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('PENDING','PROCESSING','UNKNOWN');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,
        'failed_reason', pbt.failed_reason
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_failed_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('FAILED','DECLINED','REJECTED','CANCELLED');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_tx_id', pbt.rail_tx_id,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json,
        'completed_at_utc', case when pbt.completed_at_utc is null then null else pbt.completed_at_utc::text end
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_returned_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) in ('RETURNED','REVERTED');

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', pbt.id::text,
        'pay_channel', pbt.pay_channel,
        'status', pbt.status,
        'amount', pbt.amount,
        'rail_state', pbt.rail_state,
        'rail_meta_json', pbt.rail_meta_json
      )
      order by pbt.pay_channel, pbt.amount desc, pbt.id
    ),
    '[]'::jsonb
  )
  into v_blocked_transfers
  from public.pay_bank_transfers pbt
  where pbt.pay_batch_id = p_pay_batch_id
    and upper(coalesce(pbt.status,'')) = 'BLOCKED';


  for v_changed_channel_audit in
    with batch_item_portions as (
      select
        pbi.id as pay_batch_item_id,
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id as candidate_id,
        pbi.timesheet_id as timesheet_id,
        ts.booking_id as booking_id,
        pbi.pay_bank_transfer_id as pay_bank_transfer_id,
        pbi.item_type as item_type,
        pbi.segment_key as segment_key,
        pbi.source_ref as source_ref,
        pbi.description as description,
        upper(coalesce(nullif(btrim(coalesce(pbi.frozen_source_pay_method,'')), ''), '')) as source_pay_channel,
        upper(coalesce(nullif(btrim(coalesce(pbi.pay_channel,'')), ''), nullif(btrim(coalesce(pbi.frozen_target_pay_method,'')), ''), '')) as settled_pay_channel,
        case when pbi.frozen_component_key_type is null then null else pbi.frozen_component_key_type end as component_key_type,
        pbi.frozen_component_key_value as component_key_value,
        case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end as component_classification,
        case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end as resolution_mode,
        pbi.frozen_resolution_payload_json as resolution_payload_json,
        pbi.frozen_resolution_result_json as resolution_result_json,
        pbi.frozen_source_basis_json as frozen_source_basis_json,
        round(coalesce(pbi.frozen_source_amount, pbi.amount_ex_vat, 0), 2) as item_source_amount_ex_vat,
        round(coalesce(pbi.frozen_target_amount_ex_vat, pbi.amount_ex_vat, 0), 2) as item_settled_amount_ex_vat,
        pbi.amount_ex_vat as item_amount_ex_vat
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      left join public.timesheets ts
        on ts.timesheet_id = pbi.timesheet_id
      where pbc.pay_batch_id = p_pay_batch_id
        and pbc.candidate_id in (select t.candidate_id from _tmp_newly_settled_candidates t)
        and pbi.timesheet_id is not null
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided, false) = false
    ),
    portion_rows as (
      select
        bip.pay_batch_item_id,
        bip.pay_batch_candidate_id,
        bip.candidate_id,
        bip.timesheet_id,
        bip.booking_id,
        bip.pay_bank_transfer_id,
        bip.source_pay_channel,
        bip.settled_pay_channel,
        bip.component_key_type,
        bip.component_key_value,
        bip.component_classification,
        bip.resolution_mode,
        bip.resolution_payload_json,
        bip.resolution_result_json,
        bip.segment_key,
        bip.source_ref,
        bip.description,
        pbib.id as pay_batch_item_breakdown_id,
        coalesce(
          nullif(btrim(coalesce(pbib.line_kind,'')), ''),
          case
            when bip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
            when bip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
            when bip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
            when bip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
            when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when bip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when bip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            else bip.item_type
          end
        ) as line_kind,
        nullif(btrim(coalesce(pbib.bucket_code, bip.frozen_source_basis_json ->> 'bucket_code', '')), '') as bucket_code,
        coalesce(
          nullif(btrim(coalesce(pbib.unit_name, '')), ''),
          nullif(btrim(coalesce(bip.description, '')), ''),
          case
            when bip.item_type = 'SEGMENT_DELTA' then 'Timesheet portion'
            when bip.item_type = 'EXPENSE_DELTA' then 'Expense'
            when bip.item_type = 'MILEAGE_DELTA' then 'Mileage'
            when bip.item_type = 'ADJUSTMENT_DELTA' then 'Adjustment'
            when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when bip.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt recovery'
            when bip.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit payout'
            else 'Batch item'
          end
        ) as unit_name,
        case
          when pbib.units is not null then round(pbib.units, 4)
          when bip.frozen_source_basis_json ? 'source_units'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
            then round((bip.frozen_source_basis_json ->> 'source_units')::numeric, 4)
          else null::numeric
        end as units,
        case
          when bip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round((bip.frozen_source_basis_json ->> 'source_rate')::numeric, 6)
          else null::numeric
        end as source_rate,
        case
          when pbib.rate is not null then round(pbib.rate, 6)
          else null::numeric
        end as settled_rate,
        case
          when pbib.units is not null
           and bip.frozen_source_basis_json ? 'source_rate'
           and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_rate', '')), '') is not null
            then round(pbib.units * round((bip.frozen_source_basis_json ->> 'source_rate')::numeric, 6), 2)
          else bip.item_source_amount_ex_vat
        end as source_amount_ex_vat,
        round(coalesce(pbib.amount_ex_vat, bip.item_settled_amount_ex_vat), 2) as settled_amount_ex_vat,
        md5(concat_ws('|',
          bip.pay_batch_item_id::text,
          coalesce(
            nullif(btrim(coalesce(pbib.line_kind,'')), ''),
            case
              when bip.item_type = 'SEGMENT_DELTA' then 'SEGMENT_BUCKET'
              when bip.item_type = 'EXPENSE_DELTA' then 'EXPENSE'
              when bip.item_type = 'MILEAGE_DELTA' then 'MILEAGE'
              when bip.item_type = 'ADJUSTMENT_DELTA' then 'ADJUSTMENT'
              when bip.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
              when bip.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
              when bip.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
              when bip.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
              when bip.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
              else bip.item_type
            end
          ),
          coalesce(nullif(btrim(coalesce(pbib.bucket_code, bip.frozen_source_basis_json ->> 'bucket_code', '')), ''), ''),
          coalesce(
            case
              when pbib.units is not null then round(pbib.units, 4)::text
              when bip.frozen_source_basis_json ? 'source_units'
               and nullif(btrim(coalesce(bip.frozen_source_basis_json ->> 'source_units', '')), '') is not null
                then round((bip.frozen_source_basis_json ->> 'source_units')::numeric, 4)::text
              else null::text
            end,
            ''
          ),
          coalesce(case when pbib.rate is not null then round(pbib.rate, 6)::text else null::text end, ''),
          round(coalesce(pbib.amount_ex_vat, bip.item_settled_amount_ex_vat), 2)::text
        )) as portion_identity_key
      from batch_item_portions bip
      left join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = bip.pay_batch_item_id
    )
    select
      pr.pay_batch_item_id,
      pr.pay_batch_item_breakdown_id,
      pr.pay_batch_candidate_id,
      pr.candidate_id,
      pr.timesheet_id,
      pr.booking_id,
      pr.pay_bank_transfer_id,
      pr.source_pay_channel,
      pr.settled_pay_channel,
      pr.component_key_type,
      pr.component_key_value,
      pr.component_classification,
      pr.resolution_mode,
      pr.resolution_payload_json,
      pr.resolution_result_json,
      pr.segment_key,
      pr.source_ref,
      pr.description,
      pr.line_kind,
      pr.bucket_code,
      pr.unit_name,
      pr.units,
      pr.source_rate,
      pr.settled_rate,
      pr.source_amount_ex_vat,
      pr.settled_amount_ex_vat,
      pr.portion_identity_key
    from portion_rows pr
    where pr.source_pay_channel <> ''
      and pr.settled_pay_channel <> ''
      and pr.source_pay_channel <> pr.settled_pay_channel
    order by
      pr.timesheet_id,
      pr.pay_batch_item_id,
      pr.line_kind,
      pr.bucket_code nulls first,
      pr.unit_name,
      pr.settled_amount_ex_vat desc
  loop
    v_changed_channel_audit_after_json := jsonb_build_object(
      'event_kind', 'TIMESHEET_CHANNEL_CHANGE_PORTION',
      'audit_effective_state', 'SETTLED_ACTIVE',
      'channel_changed', true,
      'timesheet_id', v_changed_channel_audit.timesheet_id::text,
      'booking_id', case when v_changed_channel_audit.booking_id is null then null else v_changed_channel_audit.booking_id::text end,
      'candidate_id', case when v_changed_channel_audit.candidate_id is null then null else v_changed_channel_audit.candidate_id::text end,
      'pay_batch_id', p_pay_batch_id::text,
      'pay_batch_candidate_id', case when v_changed_channel_audit.pay_batch_candidate_id is null then null else v_changed_channel_audit.pay_batch_candidate_id::text end,
      'pay_batch_item_id', case when v_changed_channel_audit.pay_batch_item_id is null then null else v_changed_channel_audit.pay_batch_item_id::text end,
      'pay_batch_item_breakdown_id', case when v_changed_channel_audit.pay_batch_item_breakdown_id is null then null else v_changed_channel_audit.pay_batch_item_breakdown_id::text end,
      'portion_identity_key', v_changed_channel_audit.portion_identity_key,
      'source_pay_channel', v_changed_channel_audit.source_pay_channel,
      'settled_pay_channel', v_changed_channel_audit.settled_pay_channel,
      'component_key_type', v_changed_channel_audit.component_key_type,
      'component_key_value', v_changed_channel_audit.component_key_value,
      'component_classification', v_changed_channel_audit.component_classification,
      'line_kind', v_changed_channel_audit.line_kind,
      'bucket_code', v_changed_channel_audit.bucket_code,
      'unit_name', v_changed_channel_audit.unit_name,
      'units', case when v_changed_channel_audit.units is null then null else round(v_changed_channel_audit.units, 4) end,
      'source_rate', case when v_changed_channel_audit.source_rate is null then null else round(v_changed_channel_audit.source_rate, 6) end,
      'settled_rate', case when v_changed_channel_audit.settled_rate is null then null else round(v_changed_channel_audit.settled_rate, 6) end,
      'source_amount_ex_vat', round(coalesce(v_changed_channel_audit.source_amount_ex_vat, 0), 2),
      'settled_amount_ex_vat', round(coalesce(v_changed_channel_audit.settled_amount_ex_vat, 0), 2),
      'resolution_mode', v_changed_channel_audit.resolution_mode,
      'resolution_selection_kind', case
        when v_changed_channel_audit.resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS' then 'SUGGESTED'
        when v_changed_channel_audit.resolution_mode in ('MANUAL_REPLACEMENT_RATE','MANUAL_AMOUNT') then 'MANUAL'
        else null
      end,
      'pay_bank_transfer_id', case when v_changed_channel_audit.pay_bank_transfer_id is null then null else v_changed_channel_audit.pay_bank_transfer_id::text end,
      'segment_key', v_changed_channel_audit.segment_key,
      'source_ref', v_changed_channel_audit.source_ref,
      'description', v_changed_channel_audit.description,
      'settled_at_utc', v_now
    );

    begin
      perform public._audit_insert(
        'timesheets',
        v_changed_channel_audit.timesheet_id::text,
        'TIMESHEET_CHANNEL_CHANGE_PORTION_SETTLED',
        null,
        v_changed_channel_audit_after_json,
        'rail_settlement',
        p_actor_user_id
      );
      v_changed_channel_settled_ct := v_changed_channel_settled_ct + 1;
    exception when others then
      null;
    end;
  end loop;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_SETTLE_RAIL:COUNTS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'is_stale', v_is_stale,
        'stale_reasons', v_stale_reasons,
        'newly_settled_candidates_count', jsonb_array_length(coalesce(v_newly_settled_candidates,'[]'::jsonb)),
        'overpayment_patches_applied', v_overpay_patched_ct,
        'payment_advance_recovery_patches_applied', v_payment_advance_recovery_patched_ct,
        'manual_debt_recovery_patches_applied', v_manual_debt_patched_ct,
        'payout_cases_marked_paid', v_payout_cases_marked_paid_ct,
        'component_settlements_applied', v_component_settled_count,
        'component_settlement_amount', v_component_settled_amount,
        'component_reconciliation_checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
        'component_reconciliation_mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0),
        'component_reconciliation_mismatches', v_component_reconciliation_bad,
        'batch_status', v_batch_status,
        'execution_commit_state', case when coalesce(v_completed_transfer_count, 0) > 0 then 'COMMITTED' else v_execution_commit_state end,
        'execution_commit_ref', coalesce(v_execution_commit_ref, v_detected_execution_commit_ref),
        'execution_committed_at_utc', case when coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc) is null then null else coalesce(v_execution_committed_at_utc, v_detected_execution_committed_at_utc)::text end,
        'worker_communications', v_worker_communications,
        'bank_event_ingest_count', v_bank_event_ingest_count,
        'bank_event_ingest_results', v_bank_event_ingest_results
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  v_live_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id := p_pay_batch_id,
    p_change_reason := 'PAY_SETTLE_RAIL',
    p_change_source := 'pay_settle_rail',
    p_change_scope_json := jsonb_strip_nulls(jsonb_build_object(
      'execution_mode', v_settlement_mode,
      'batch_status', v_batch_status,
      'newly_settled_candidates', COALESCE(v_newly_settled_candidates, '[]'::jsonb),
      'completed_transfer_count', COALESCE(v_completed_transfer_count, 0),
      'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
      'bank_event_ingest_count', COALESCE(v_bank_event_ingest_count, 0)
    )),
    p_touch_payment_status := true,
    p_touch_correction_progress := false,
    p_touch_alerts := false,
    p_touch_overview := true
  );

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'batch_status', (select pb3.status from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_commit_state', (select pb3.execution_commit_state from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_commit_ref', (select pb3.execution_commit_ref from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_committed_at_utc', (select case when pb3.execution_committed_at_utc is null then null else pb3.execution_committed_at_utc::text end from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'settlement_confirmation_json', (select pb3.settlement_confirmation_json from public.pay_batches pb3 where pb3.id = p_pay_batch_id),
    'execution_mode', v_settlement_mode,
    'suppress_remittances', v_suppress_remittances,
    'newly_settled_candidates', v_newly_settled_candidates,
    'still_pending_transfers', v_pending_transfers,
    'failed_transfers', v_failed_transfers,
    'returned_transfers', v_returned_transfers,
    'blocked_transfers', v_blocked_transfers,
    'freshness', jsonb_build_object(
      'is_stale', v_is_stale,
      'stale_reasons', v_stale_reasons,
      'diff_sample', v_diff_sample,
      'freshness_validation_status', nullif(v_stored_freshness_status, ''),
      'freshness_result_hash', v_stored_freshness_result_hash,
      'freshness_scope_hash', v_stored_freshness_scope_hash,
      'freshness_operation_id', case when v_stored_freshness_operation_id is null then null else v_stored_freshness_operation_id::text end,
      'source', coalesce(v_fresh->>'source', 'stored_freshness_metadata_non_blocking')
    ),
    'patch_summary', jsonb_build_object(
      'overpayment_patches_applied', v_overpay_patched_ct,
      'payment_advance_recovery_patches_applied', v_payment_advance_recovery_patched_ct,
      'manual_debt_recovery_patches_applied', v_manual_debt_patched_ct,
      'payout_cases_marked_paid', v_payout_cases_marked_paid_ct,
      'component_settlements_applied', v_component_settled_count,
      'component_settlement_amount', v_component_settled_amount,
      'component_reconciliation_checked_count', coalesce(v_component_reconciliation_checked_ct, 0),
      'component_reconciliation_mismatch_count', coalesce(v_component_reconciliation_bad_ct, 0)
    ),
    'timesheet_channel_change_audit', jsonb_build_object(
      'settled_event_count', v_changed_channel_settled_ct
    ),
    'worker_communications', v_worker_communications,
    'consumed_carry_forward_count', COALESCE(v_consumed_carry_forward_count, 0),
    'carry_forward_mark_consumed_result', COALESCE(v_carry_forward_mark_result, '{}'::jsonb),
    'remittance_ready', (v_catchup_needed and v_suppress_remittances = false),
    'remittance_queued', false,
    'remittance_queue_stage_result', coalesce(v_comm_result, '{}'::jsonb),
    'bank_event_ingest', jsonb_build_object(
      'count', v_bank_event_ingest_count,
      'results', v_bank_event_ingest_results
    ),
    'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
    'policy_x_checked', true
  );
end;
$$;








create or replace function public.pay_remittance_mark_sent(
  p_pay_batch_id uuid,
  p_scope text,
  p_results_json jsonb,
  p_actor_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch_exists boolean := false;
  v_now timestamptz := now();
  v_results jsonb := case
    when p_results_json is null then '{}'::jsonb
    when jsonb_typeof(p_results_json) = 'object' then p_results_json
    else jsonb_build_object('raw', p_results_json)
  end;
  v_input_message_kind text := upper(btrim(coalesce(v_results->>'message_kind', 'REMITTANCE')));
  v_message_kind text := null;
  v_audit_action text := null;
  v_audit_reason text := null;
  v_audit_id uuid;

  v_has_remittance_result boolean := false;
  v_has_payout_notice_result boolean := false;
  v_remittance_result jsonb := '{}'::jsonb;
  v_payout_notice_result jsonb := '{}'::jsonb;
  v_communication_mode text := 'NONE';

  v_item jsonb;
  v_item_payee_kind text;
  v_item_candidate_id_text text;
  v_item_umbrella_id_text text;
  v_item_candidate_id uuid;
  v_item_umbrella_id uuid;
  v_item_trigger_status text;
  v_item_error_text text;
  v_item_has_job boolean;

  v_success_count integer := 0;
  v_failure_count integer := 0;
  v_no_result_count integer := 0;

  v_remittance_success_count integer := 0;
  v_remittance_failure_count integer := 0;
  v_remittance_no_result_count integer := 0;
  v_remittance_unmatched_queued_count integer := 0;
  v_remittance_unmatched_skipped_count integer := 0;

  v_payout_notice_success_count integer := 0;
  v_payout_notice_failure_count integer := 0;
  v_payout_notice_no_result_count integer := 0;
  v_payout_notice_unmatched_queued_count integer := 0;
  v_payout_notice_unmatched_skipped_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_mark_sent: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_remittance_mark_sent: actor_user_id is required';
  end if;

  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_remittance_mark_sent: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  select exists (
    select 1
    from public.pay_batches pb
    where pb.id = p_pay_batch_id
  )
  into v_batch_exists;

  if v_batch_exists is false then
    raise exception 'pay_remittance_mark_sent: pay batch % not found.', p_pay_batch_id;
  end if;

  if jsonb_typeof(v_results->'remittance_result') = 'object' then
    v_has_remittance_result := true;
    v_remittance_result := coalesce(v_results->'remittance_result', '{}'::jsonb);
  end if;

  if jsonb_typeof(v_results->'payout_notice_result') = 'object' then
    v_has_payout_notice_result := true;
    v_payout_notice_result := coalesce(v_results->'payout_notice_result', '{}'::jsonb);
  end if;

  if v_has_remittance_result is false and v_has_payout_notice_result is false then
    if v_input_message_kind = 'PAYOUT_NOTICE' then
      v_has_payout_notice_result := true;
      v_payout_notice_result := v_results;
    else
      v_has_remittance_result := true;
      v_remittance_result := v_results;
    end if;
  end if;

  if v_has_remittance_result and v_has_payout_notice_result then
    v_communication_mode := 'MIXED';
    v_message_kind := 'MIXED';
    v_audit_action := 'PAY_BATCH_COMMUNICATIONS_SENT';
    v_audit_reason := 'communications_mark_sent';
  elsif v_has_payout_notice_result then
    v_communication_mode := 'PAYOUT_NOTICE';
    v_message_kind := 'PAYOUT_NOTICE';
    v_audit_action := 'PAY_PAYOUT_NOTICE_SENT';
    v_audit_reason := 'payout_notice_mark_sent';
  else
    v_communication_mode := 'REMITTANCE';
    v_message_kind := 'REMITTANCE';
    v_audit_action := 'PAY_REMITTANCE_SENT';
    v_audit_reason := 'remittance_mark_sent';
  end if;

  drop table if exists pg_temp._tmp_mark_sent_target_candidates;
  create temporary table pg_temp._tmp_mark_sent_target_candidates (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    target_from_remittance boolean not null default false,
    target_from_payout_notice boolean not null default false
  ) on commit drop;

  if v_has_remittance_result then
    insert into pg_temp._tmp_mark_sent_target_candidates(
      pay_batch_candidate_id,
      candidate_id,
      target_from_remittance,
      target_from_payout_notice
    )
    select
      pbc.id,
      pbc.candidate_id,
      true,
      false
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = p_pay_batch_id
      and exists (
        select 1
        from public.pay_batch_items pbi
        where pbi.pay_batch_candidate_id = pbc.id
          and pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and not (
            pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          )
      )
    on conflict (pay_batch_candidate_id)
    do update set
      target_from_remittance = true;
  end if;

  if v_has_payout_notice_result then
    if jsonb_typeof(v_payout_notice_result->'candidate_results') = 'array' then
      insert into pg_temp._tmp_mark_sent_target_candidates(
        pay_batch_candidate_id,
        candidate_id,
        target_from_remittance,
        target_from_payout_notice
      )
      select
        pbc.id,
        pbc.candidate_id,
        false,
        true
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = p_pay_batch_id
        and exists (
          select 1
          from jsonb_array_elements(v_payout_notice_result->'candidate_results') as cr(value)
          where nullif(btrim(coalesce(cr.value->>'candidate_id', '')), '') = pbc.candidate_id::text
        )
      on conflict (pay_batch_candidate_id)
      do update set
        target_from_payout_notice = true;
    else
      insert into pg_temp._tmp_mark_sent_target_candidates(
        pay_batch_candidate_id,
        candidate_id,
        target_from_remittance,
        target_from_payout_notice
      )
      select
        pbc.id,
        pbc.candidate_id,
        false,
        true
      from public.pay_batch_candidates pbc
      where pbc.pay_batch_id = p_pay_batch_id
        and exists (
          select 1
          from public.pay_batch_items pbi
          where pbi.pay_batch_candidate_id = pbc.id
            and coalesce(pbi.is_voided, false) = false
            and pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and (
              v_scope = 'ALL'
              or upper(coalesce(pbi.pay_channel, '')) = v_scope
            )
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      on conflict (pay_batch_candidate_id)
      do update set
        target_from_payout_notice = true;
    end if;
  end if;

  drop table if exists pg_temp._tmp_mark_sent_events;
  create temporary table pg_temp._tmp_mark_sent_events (
    candidate_id uuid not null,
    comm_kind text not null,
    outcome text not null,
    trigger_status text null,
    error_text text null
  ) on commit drop;

  if v_has_remittance_result and jsonb_typeof(v_remittance_result->'candidate_results') = 'array' then
    for v_item in
      select cr.value
      from jsonb_array_elements(v_remittance_result->'candidate_results') as cr(value)
    loop
      v_item_candidate_id_text := nullif(btrim(coalesce(v_item->>'candidate_id', '')), '');
      v_item_candidate_id := null;
      v_item_has_job := lower(btrim(coalesce(v_item->>'has_job', 'false'))) in ('true', '1', 'yes', 'y', 'on');
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'NO_QUEUEABLE_JOB')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_candidate_id is not null and v_item_has_job is false then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'REMITTANCE',
          'FAILURE',
          v_item_trigger_status,
          left(v_item_trigger_status, 1000)
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_remittance = true;
      end if;
    end loop;
  end if;

  if v_has_payout_notice_result and jsonb_typeof(v_payout_notice_result->'candidate_results') = 'array' then
    for v_item in
      select cr.value
      from jsonb_array_elements(v_payout_notice_result->'candidate_results') as cr(value)
    loop
      v_item_candidate_id_text := nullif(btrim(coalesce(v_item->>'candidate_id', '')), '');
      v_item_candidate_id := null;
      v_item_has_job := lower(btrim(coalesce(v_item->>'has_job', 'false'))) in ('true', '1', 'yes', 'y', 'on');
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'NO_QUEUEABLE_PAYOUT_NOTICE_JOB')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_candidate_id is not null and v_item_has_job is false then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          left(v_item_trigger_status, 1000)
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_payout_notice = true;
      end if;
    end loop;
  end if;

  if v_has_remittance_result and jsonb_typeof(v_remittance_result->'queued') = 'array' then
    for v_item in
      select q.value
      from jsonb_array_elements(v_remittance_result->'queued') as q(value)
    loop
      v_item_payee_kind := upper(btrim(coalesce(v_item->>'payee_entity_kind', '')));
      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'QUEUED_TO_MAIL_OUTBOX')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
          v_item_umbrella_id := v_item_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_item_umbrella_id := null;
        end;
      end if;

      if v_item_candidate_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'REMITTANCE',
          'QUEUED',
          v_item_trigger_status,
          null
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_remittance = true;
      elsif v_item_payee_kind = 'UMBRELLA' and v_item_umbrella_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select distinct
          tc.candidate_id,
          'REMITTANCE',
          'QUEUED',
          v_item_trigger_status,
          null
        from pg_temp._tmp_mark_sent_target_candidates tc
        join public.pay_batch_candidates pbc
          on pbc.id = tc.pay_batch_candidate_id
        join public.pay_batch_items pbi
          on pbi.pay_batch_candidate_id = pbc.id
        where pbc.pay_batch_id = p_pay_batch_id
          and tc.target_from_remittance = true
          and pbi.item_type <> 'DEBT_CREATED'
          and coalesce(pbi.is_voided, false) = false
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and pbi.umbrella_id = v_item_umbrella_id
          and not (
            pbi.finance_case_id is not null
            and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          );
      else
        v_remittance_unmatched_queued_count := v_remittance_unmatched_queued_count + 1;
      end if;
    end loop;
  end if;


  if v_has_remittance_result and (
    jsonb_typeof(v_remittance_result->'sent') = 'array'
    or jsonb_typeof(v_remittance_result->'accepted') = 'array'
  ) then
    for v_item in
      select q.value
      from jsonb_array_elements(
        case when jsonb_typeof(v_remittance_result->'sent') = 'array' then v_remittance_result->'sent' else '[]'::jsonb end
      ) as q(value)
      union all
      select q.value
      from jsonb_array_elements(
        case when jsonb_typeof(v_remittance_result->'accepted') = 'array' then v_remittance_result->'accepted' else '[]'::jsonb end
      ) as q(value)
    loop
      v_item_payee_kind := upper(btrim(coalesce(v_item->>'payee_entity_kind', '')));
      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', 'SENT_VIA_MAIL_OUTBOX')));

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
