            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
            and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          );
      else
        v_payout_notice_unmatched_skipped_count := v_payout_notice_unmatched_skipped_count + 1;
      end if;
    end loop;
  end if;

  if v_has_payout_notice_result and jsonb_typeof(v_payout_notice_result->'skipped') = 'array' then
    for v_item in
      select s.value
      from jsonb_array_elements(v_payout_notice_result->'skipped') as s(value)
    loop
      v_item_payee_kind := upper(btrim(coalesce(v_item->>'payee_entity_kind', 'CANDIDATE')));
      v_item_candidate_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'candidate_id',
            case when v_item_payee_kind = 'CANDIDATE' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_umbrella_id_text := nullif(
        btrim(
          coalesce(
            v_item->>'umbrella_id',
            case when v_item_payee_kind = 'UMBRELLA' then v_item->>'payee_entity_id' else null end
          )
        ),
        ''
      );
      v_item_candidate_id := null;
      v_item_umbrella_id := null;
      v_item_trigger_status := upper(btrim(coalesce(v_item->>'trigger_status', v_item->>'reason', 'SEND_SKIPPED')));
      v_item_error_text := left(coalesce(nullif(btrim(coalesce(v_item->>'error', '')), ''), nullif(btrim(coalesce(v_item->>'reason', '')), ''), 'SEND_SKIPPED'), 1000);

      if v_item_candidate_id_text is not null then
        begin
          v_item_candidate_id := v_item_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_item_candidate_id := null;
        end;
      end if;

      if v_item_umbrella_id_text is not null then
        begin
          v_item_umbrella_id := v_item_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_item_umbrella_id := null;
        end;
      end if;

      if v_item_candidate_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        where tc.candidate_id = v_item_candidate_id
          and tc.target_from_payout_notice = true;
      elsif v_item_payee_kind = 'UMBRELLA' and v_item_umbrella_id is not null then
        insert into pg_temp._tmp_mark_sent_events(candidate_id, comm_kind, outcome, trigger_status, error_text)
        select distinct
          tc.candidate_id,
          'PAYOUT_NOTICE',
          'FAILURE',
          v_item_trigger_status,
          v_item_error_text
        from pg_temp._tmp_mark_sent_target_candidates tc
        join public.pay_batch_candidates pbc
          on pbc.id = tc.pay_batch_candidate_id
        join public.pay_batch_items pbi
          on pbi.pay_batch_candidate_id = pbc.id
        where pbc.pay_batch_id = p_pay_batch_id
          and tc.target_from_payout_notice = true
          and coalesce(pbi.is_voided, false) = false
          and pbi.finance_case_id is not null
          and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and (
            v_scope = 'ALL'
            or upper(coalesce(pbi.pay_channel, '')) = v_scope
          )
          and pbi.umbrella_id = v_item_umbrella_id
          and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on');
      else
        v_payout_notice_unmatched_skipped_count := v_payout_notice_unmatched_skipped_count + 1;
      end if;
    end loop;
  end if;

  drop table if exists pg_temp._tmp_mark_sent_agg;
  create temporary table pg_temp._tmp_mark_sent_agg (
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    target_from_remittance boolean not null,
    target_from_payout_notice boolean not null,
    has_success boolean not null,
    has_success_remittance boolean not null,
    has_success_payout_notice boolean not null,
    success_trigger_status text null,
    failure_trigger_status text null,
    failure_error text null,
    remittance_success_trigger_status text null,
    payout_notice_success_trigger_status text null,
    remittance_failure_trigger_status text null,
    payout_notice_failure_trigger_status text null,
    remittance_failure_error text null,
    payout_notice_failure_error text null
  ) on commit drop;

  insert into pg_temp._tmp_mark_sent_agg(
    pay_batch_candidate_id,
    candidate_id,
    target_from_remittance,
    target_from_payout_notice,
    has_success,
    has_success_remittance,
    has_success_payout_notice,
    success_trigger_status,
    failure_trigger_status,
    failure_error,
    remittance_success_trigger_status,
    payout_notice_success_trigger_status,
    remittance_failure_trigger_status,
    payout_notice_failure_trigger_status,
    remittance_failure_error,
    payout_notice_failure_error
  )
  select
    tc.pay_batch_candidate_id,
    tc.candidate_id,
    tc.target_from_remittance,
    tc.target_from_payout_notice,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.comm_kind = 'REMITTANCE'
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success_remittance,
    (
      exists (
        select 1
        from pg_temp._tmp_mark_sent_events evs
        where evs.candidate_id = tc.candidate_id
          and evs.comm_kind = 'PAYOUT_NOTICE'
          and evs.outcome = 'SUCCESS'
      )
    ) as has_success_payout_notice,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'REMITTANCE'
            and evs.outcome = 'SUCCESS'
        )
      )
       and (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'PAYOUT_NOTICE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then 'REMITTANCE_AND_PAYOUT_NOTICE_SENT'
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'REMITTANCE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then coalesce(
          (
            select evs2.trigger_status
            from pg_temp._tmp_mark_sent_events evs2
            where evs2.candidate_id = tc.candidate_id
              and evs2.comm_kind = 'REMITTANCE'
              and evs2.outcome = 'SUCCESS'
              and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
            order by evs2.trigger_status
            limit 1
          ),
          'SENT_VIA_MAIL_OUTBOX'
        )
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.comm_kind = 'PAYOUT_NOTICE'
            and evs.outcome = 'SUCCESS'
        )
      )
        then coalesce(
          (
            select evs2.trigger_status
            from pg_temp._tmp_mark_sent_events evs2
            where evs2.candidate_id = tc.candidate_id
              and evs2.comm_kind = 'PAYOUT_NOTICE'
              and evs2.outcome = 'SUCCESS'
              and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
            order by evs2.trigger_status
            limit 1
          ),
          'SENT_VIA_MAIL_OUTBOX'
        )
      else null
    end as success_trigger_status,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.outcome = 'SUCCESS'
        )
      )
        then null
      when tc.target_from_remittance and tc.target_from_payout_notice then
        case
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'REMITTANCE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
           and coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'PAYOUT_NOTICE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then 'REMITTANCE_AND_PAYOUT_NOTICE_FAILED'
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'REMITTANCE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then coalesce(
              (
                select evf.trigger_status
                from pg_temp._tmp_mark_sent_events evf
                where evf.candidate_id = tc.candidate_id
                  and evf.comm_kind = 'REMITTANCE'
                  and evf.outcome = 'FAILURE'
                  and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
                order by evf.trigger_status
                limit 1
              ),
              'NO_RESULT_RECORDED'
            )
          when coalesce(
            (
              select evf.trigger_status
              from pg_temp._tmp_mark_sent_events evf
              where evf.candidate_id = tc.candidate_id
                and evf.comm_kind = 'PAYOUT_NOTICE'
                and evf.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
              order by evf.trigger_status
              limit 1
            ),
            'NO_RESULT_RECORDED'
          ) <> 'NO_RESULT_RECORDED'
            then coalesce(
              (
                select evf.trigger_status
                from pg_temp._tmp_mark_sent_events evf
                where evf.candidate_id = tc.candidate_id
                  and evf.comm_kind = 'PAYOUT_NOTICE'
                  and evf.outcome = 'FAILURE'
                  and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
                order by evf.trigger_status
                limit 1
              ),
              'NO_RESULT_RECORDED'
            )
          else 'NO_RESULT_RECORDED'
        end
      when tc.target_from_remittance then
        coalesce(
          (
            select evf.trigger_status
            from pg_temp._tmp_mark_sent_events evf
            where evf.candidate_id = tc.candidate_id
              and evf.comm_kind = 'REMITTANCE'
              and evf.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
            order by evf.trigger_status
            limit 1
          ),
          'NO_RESULT_RECORDED'
        )
      when tc.target_from_payout_notice then
        coalesce(
          (
            select evf.trigger_status
            from pg_temp._tmp_mark_sent_events evf
            where evf.candidate_id = tc.candidate_id
              and evf.comm_kind = 'PAYOUT_NOTICE'
              and evf.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
            order by evf.trigger_status
            limit 1
          ),
          'NO_RESULT_RECORDED'
        )
      else 'NO_RESULT_RECORDED'
    end as failure_trigger_status,
    case
      when (
        exists (
          select 1
          from pg_temp._tmp_mark_sent_events evs
          where evs.candidate_id = tc.candidate_id
            and evs.outcome = 'SUCCESS'
        )
      )
        then null
      else left(
        coalesce(
          (
            select string_agg(errs.err_txt, ' | ')
            from (
              select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
              from pg_temp._tmp_mark_sent_events evf2
              where evf2.candidate_id = tc.candidate_id
                and evf2.outcome = 'FAILURE'
                and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
              order by err_txt
            ) errs
          ),
          'NO_RESULT_RECORDED'
        ),
        1000
      )
    end as failure_error,
    (
      select evs2.trigger_status
      from pg_temp._tmp_mark_sent_events evs2
      where evs2.candidate_id = tc.candidate_id
        and evs2.comm_kind = 'REMITTANCE'
        and evs2.outcome = 'SUCCESS'
        and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
      order by evs2.trigger_status
      limit 1
    ) as remittance_success_trigger_status,
    (
      select evs2.trigger_status
      from pg_temp._tmp_mark_sent_events evs2
      where evs2.candidate_id = tc.candidate_id
        and evs2.comm_kind = 'PAYOUT_NOTICE'
        and evs2.outcome = 'SUCCESS'
        and nullif(btrim(coalesce(evs2.trigger_status, '')), '') is not null
      order by evs2.trigger_status
      limit 1
    ) as payout_notice_success_trigger_status,
    coalesce(
      (
        select evf.trigger_status
        from pg_temp._tmp_mark_sent_events evf
        where evf.candidate_id = tc.candidate_id
          and evf.comm_kind = 'REMITTANCE'
          and evf.outcome = 'FAILURE'
          and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
        order by evf.trigger_status
        limit 1
      ),
      case when tc.target_from_remittance then 'NO_RESULT_RECORDED' else null end
    ) as remittance_failure_trigger_status,
    coalesce(
      (
        select evf.trigger_status
        from pg_temp._tmp_mark_sent_events evf
        where evf.candidate_id = tc.candidate_id
          and evf.comm_kind = 'PAYOUT_NOTICE'
          and evf.outcome = 'FAILURE'
          and nullif(btrim(coalesce(evf.trigger_status, '')), '') is not null
        order by evf.trigger_status
        limit 1
      ),
      case when tc.target_from_payout_notice then 'NO_RESULT_RECORDED' else null end
    ) as payout_notice_failure_trigger_status,
    left(
      coalesce(
        (
          select string_agg(errs.err_txt, ' | ')
          from (
            select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
            from pg_temp._tmp_mark_sent_events evf2
            where evf2.candidate_id = tc.candidate_id
              and evf2.comm_kind = 'REMITTANCE'
              and evf2.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
            order by err_txt
          ) errs
        ),
        case when tc.target_from_remittance then 'NO_RESULT_RECORDED' else null end
      ),
      1000
    ) as remittance_failure_error,
    left(
      coalesce(
        (
          select string_agg(errs.err_txt, ' | ')
          from (
            select distinct nullif(btrim(coalesce(evf2.error_text, '')), '') as err_txt
            from pg_temp._tmp_mark_sent_events evf2
            where evf2.candidate_id = tc.candidate_id
              and evf2.comm_kind = 'PAYOUT_NOTICE'
              and evf2.outcome = 'FAILURE'
              and nullif(btrim(coalesce(evf2.error_text, '')), '') is not null
            order by err_txt
          ) errs
        ),
        case when tc.target_from_payout_notice then 'NO_RESULT_RECORDED' else null end
      ),
      1000
    ) as payout_notice_failure_error
  from pg_temp._tmp_mark_sent_target_candidates tc;

  update public.pay_batch_candidates pbc
  set
    remittance_sent_at_utc = coalesce(pbc.remittance_sent_at_utc, v_now),
    remittance_sent_by_user_id = coalesce(pbc.remittance_sent_by_user_id, p_actor_user_id),
    remittance_trigger_status = agg.remittance_success_trigger_status,
    last_remittance_error = null,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = true;

  update public.pay_batch_candidates pbc
  set
    remittance_trigger_status = agg.remittance_failure_trigger_status,
    last_remittance_error = agg.remittance_failure_error,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status <> 'NO_RESULT_RECORDED';

  update public.pay_batch_candidates pbc
  set
    remittance_trigger_status = coalesce(
      (
        select evq.trigger_status
        from pg_temp._tmp_mark_sent_events evq
        where evq.candidate_id = pbc.candidate_id
          and evq.comm_kind = 'REMITTANCE'
          and evq.outcome = 'QUEUED'
          and nullif(btrim(coalesce(evq.trigger_status, '')), '') is not null
        order by evq.trigger_status
        limit 1
      ),
      pbc.remittance_trigger_status
    ),
    last_remittance_error = null,
    updated_at = v_now
  from pg_temp._tmp_mark_sent_agg agg
  where pbc.id = agg.pay_batch_candidate_id
    and agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status = 'NO_RESULT_RECORDED'
    and exists (
      select 1
      from pg_temp._tmp_mark_sent_events evq2
      where evq2.candidate_id = pbc.candidate_id
        and evq2.comm_kind = 'REMITTANCE'
        and evq2.outcome = 'QUEUED'
    );

  select count(*)::int
  into v_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = true;

  select count(*)::int
  into v_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = false
    and (agg.target_from_remittance = true or agg.target_from_payout_notice = true)
    and agg.failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.has_success = false
    and agg.failure_trigger_status = 'NO_RESULT_RECORDED'
    and not exists (
      select 1
      from pg_temp._tmp_mark_sent_events evq
      where evq.candidate_id = agg.candidate_id
        and evq.outcome = 'QUEUED'
    );

  select count(*)::int
  into v_remittance_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = true;

  select count(*)::int
  into v_remittance_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_remittance_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_remittance = true
    and agg.has_success_remittance = false
    and agg.remittance_failure_trigger_status = 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_payout_notice_success_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = true;

  select count(*)::int
  into v_payout_notice_failure_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = false
    and agg.payout_notice_failure_trigger_status <> 'NO_RESULT_RECORDED';

  select count(*)::int
  into v_payout_notice_no_result_count
  from pg_temp._tmp_mark_sent_agg agg
  where agg.target_from_payout_notice = true
    and agg.has_success_payout_notice = false
    and agg.payout_notice_failure_trigger_status = 'NO_RESULT_RECORDED';

  insert into public.audit_events(
    actor_user_id,
    object_type,
    object_id_text,
    action,
    before_json,
    after_json,
    reason
  )
  values (
    p_actor_user_id,
    'pay_batch',
    p_pay_batch_id::text,
    v_audit_action,
    null,
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'message_kind', v_message_kind,
      'communication_mode', v_communication_mode,
      'success_count', v_success_count,
      'failure_count', v_failure_count,
      'no_result_count', v_no_result_count,
      'remittance_result', jsonb_build_object(
        'included', v_has_remittance_result,
        'success_count', v_remittance_success_count,
        'failure_count', v_remittance_failure_count,
        'no_result_count', v_remittance_no_result_count,
        'unmatched_queued_count', v_remittance_unmatched_queued_count,
        'unmatched_skipped_count', v_remittance_unmatched_skipped_count,
        'results', case when v_has_remittance_result then coalesce(v_remittance_result, '{}'::jsonb) else null end
      ),
      'payout_notice_result', jsonb_build_object(
        'included', v_has_payout_notice_result,
        'success_count', v_payout_notice_success_count,
        'failure_count', v_payout_notice_failure_count,
        'no_result_count', v_payout_notice_no_result_count,
        'unmatched_queued_count', v_payout_notice_unmatched_queued_count,
        'unmatched_skipped_count', v_payout_notice_unmatched_skipped_count,
        'results', case when v_has_payout_notice_result then coalesce(v_payout_notice_result, '{}'::jsonb) else null end
      ),
      'results', coalesce(v_results, '{}'::jsonb)
    ),
    v_audit_reason
  )
  returning id into v_audit_id;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'scope', v_scope,
    'message_kind', v_message_kind,
    'communication_mode', v_communication_mode,
    'success_count', v_success_count,
    'failure_count', v_failure_count,
    'no_result_count', v_no_result_count,
    'remittance_result', jsonb_build_object(
      'included', v_has_remittance_result,
      'success_count', v_remittance_success_count,
      'failure_count', v_remittance_failure_count,
      'no_result_count', v_remittance_no_result_count,
      'unmatched_queued_count', v_remittance_unmatched_queued_count,
      'unmatched_skipped_count', v_remittance_unmatched_skipped_count
    ),
    'payout_notice_result', jsonb_build_object(
      'included', v_has_payout_notice_result,
      'success_count', v_payout_notice_success_count,
      'failure_count', v_payout_notice_failure_count,
      'no_result_count', v_payout_notice_no_result_count,
      'unmatched_queued_count', v_payout_notice_unmatched_queued_count,
      'unmatched_skipped_count', v_payout_notice_unmatched_skipped_count
    ),
    'audit_event_id', v_audit_id::text
  );
end;
$$;







DROP FUNCTION IF EXISTS public.pay_remittance_build(uuid, text);
DROP FUNCTION IF EXISTS public.pay_remittance_build(uuid, text, uuid, jsonb, integer, jsonb);

CREATE OR REPLACE FUNCTION public.pay_remittance_build(
  p_pay_batch_id uuid,
  p_scope text DEFAULT 'ALL'::text,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_remittance_scope_ids jsonb DEFAULT NULL::jsonb,
  p_limit integer DEFAULT NULL::integer,
  p_cursor_json jsonb DEFAULT NULL::jsonb
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch record;

  v_jobs_umb jsonb := '[]'::jsonb;
  v_jobs_paye jsonb := '[]'::jsonb;
  v_jobs_cand_umb_copy jsonb := '[]'::jsonb;

  -- ✅ Remittance settings (single-row settings_defaults)
  v_remittance_includes_json jsonb := null;
  v_remittance_header_message text := null;
  v_remittance_footer_message text := null;

  -- ✅ New defaults
  v_sd_paye_remittances_enabled boolean := false;
  v_sd_remittances_detailed_breakdown boolean := false;
  v_sd_remittance_receive_when_umbrella_paid boolean := false;

  -- ✅ derived defaults for config evaluation
  v_missing_scope text := 'WEEKLY';
  v_unknown_item_type_default boolean := true;
  v_unknown_item_type_default_text text := 'true';

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_limit integer := 100;
  v_cursor_scope_id uuid := null;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_selected_scope_count integer := 0;
  v_known_scope_count integer := 0;
  v_next_cursor_json jsonb := null;
  v_operation_jobs jsonb := '[]'::jsonb;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_build: pay_batch_id is required';
  end if;

  if v_scope not in ('ALL','PAYE','UMBRELLA') then
    raise exception 'pay_remittance_build: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL OR p_limit IS NOT NULL OR p_cursor_json IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_build operation mode requires p_operation_id';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % is not remittance-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_remittance_build: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    SELECT
      pb.id,
      pb.pay_date,
      pb.authoritative_payment_date,
      pb.authoritative_payment_date_source,
      pb.status,
      pb.bulk_reference,
      pb.banking_system_snapshot,
      pb.external_paye_system_snapshot,
      pb.execution_commit_state,
      pb.execution_commit_ref,
      pb.execution_committed_at_utc
    INTO v_batch
    FROM public.pay_batches AS pb
    WHERE pb.id = p_pay_batch_id;

    IF v_batch.id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_build: pay batch % not found.', p_pay_batch_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NULL THEN
      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;
    END IF;

    v_limit := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 1000);

    IF p_cursor_json IS NOT NULL
       AND jsonb_typeof(p_cursor_json) = 'object'
       AND COALESCE(p_cursor_json->>'last_remittance_scope_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      v_cursor_scope_id := (p_cursor_json->>'last_remittance_scope_id')::uuid;
    END IF;

    IF p_remittance_scope_ids IS NOT NULL THEN
      IF jsonb_typeof(p_remittance_scope_ids) <> 'array' THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode requires p_remittance_scope_ids to be a JSON array when supplied';
      END IF;

      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      SELECT COUNT(*)::integer
      INTO v_requested_scope_count
      FROM requested_scope;

      IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode received invalid or duplicate remittance scope ids';
      END IF;

      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), selected_scope AS (
        SELECT scope_row.*
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      ), job_rows AS (
        SELECT
          selected_scope.id,
          selected_scope.status,
          selected_scope.pay_batch_candidate_id,
          selected_scope.candidate_id,
          selected_scope.recipient_kind,
          selected_scope.recipient_id,
          selected_scope.remittance_type,
          selected_scope.deterministic_outbox_key,
          selected_scope.payload_json,
          selected_scope.outbox_id,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
            ELSE NULL::text
          END AS recipient_email,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
            ELSE NULL::text
          END AS recipient_name
        FROM selected_scope
        LEFT JOIN public.candidates AS candidate_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE'
         AND candidate_row.id = selected_scope.recipient_id
        LEFT JOIN public.umbrellas AS umbrella_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA'
         AND umbrella_row.id = selected_scope.recipient_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(job_rows.id::text) ORDER BY job_rows.id::text), '[]'::jsonb),
             COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'job_kind', job_rows.remittance_type,
               'operation_id', p_operation_id::text,
               'pay_batch_id', p_pay_batch_id::text,
               'remittance_scope_id', job_rows.id::text,
               'deterministic_outbox_key', job_rows.deterministic_outbox_key,
               'status', job_rows.status,
               'outbox_id', CASE WHEN job_rows.outbox_id IS NULL THEN NULL ELSE job_rows.outbox_id::text END,
               'recipient', jsonb_strip_nulls(jsonb_build_object(
                 'entity_kind', lower(coalesce(job_rows.recipient_kind, '')),
                 'entity_id', CASE WHEN job_rows.recipient_id IS NULL THEN NULL ELSE job_rows.recipient_id::text END,
                 'candidate_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'CANDIDATE' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'umbrella_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'name', job_rows.recipient_name,
                 'email', job_rows.recipient_email,
                 'remittance_email', job_rows.recipient_email
               )),
               'payment_scope_json', jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               )),
               'payload_json', job_rows.payload_json
             )) ORDER BY job_rows.id::text), '[]'::jsonb)
      INTO v_matched_scope_count,
           v_operation_scope_ids,
           v_operation_jobs
      FROM job_rows;

      IF v_matched_scope_count <> v_requested_scope_count THEN
        RAISE EXCEPTION 'pay_remittance_build operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
      END IF;

      v_selected_scope_count := v_matched_scope_count;
      v_known_scope_count := v_matched_scope_count;
      v_next_cursor_json := NULL::jsonb;
    ELSE
      WITH selected_scope AS (
        SELECT scope_row.*
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
          AND scope_row.status IN ('PENDING', 'FAILED')
          AND (v_cursor_scope_id IS NULL OR scope_row.id::text > v_cursor_scope_id::text)
        ORDER BY scope_row.id::text
        LIMIT v_limit
      ), job_rows AS (
        SELECT
          selected_scope.id,
          selected_scope.status,
          selected_scope.pay_batch_candidate_id,
          selected_scope.candidate_id,
          selected_scope.recipient_kind,
          selected_scope.recipient_id,
          selected_scope.remittance_type,
          selected_scope.deterministic_outbox_key,
          selected_scope.payload_json,
          selected_scope.outbox_id,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
            ELSE NULL::text
          END AS recipient_email,
          CASE
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
            WHEN upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
            ELSE NULL::text
          END AS recipient_name
        FROM selected_scope
        LEFT JOIN public.candidates AS candidate_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'CANDIDATE'
         AND candidate_row.id = selected_scope.recipient_id
        LEFT JOIN public.umbrellas AS umbrella_row
          ON upper(coalesce(selected_scope.recipient_kind, '')) = 'UMBRELLA'
         AND umbrella_row.id = selected_scope.recipient_id
      )
      SELECT COUNT(*)::integer,
             COALESCE(jsonb_agg(to_jsonb(job_rows.id::text) ORDER BY job_rows.id::text), '[]'::jsonb),
             COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
               'job_kind', job_rows.remittance_type,
               'operation_id', p_operation_id::text,
               'pay_batch_id', p_pay_batch_id::text,
               'remittance_scope_id', job_rows.id::text,
               'deterministic_outbox_key', job_rows.deterministic_outbox_key,
               'status', job_rows.status,
               'outbox_id', CASE WHEN job_rows.outbox_id IS NULL THEN NULL ELSE job_rows.outbox_id::text END,
               'recipient', jsonb_strip_nulls(jsonb_build_object(
                 'entity_kind', lower(coalesce(job_rows.recipient_kind, '')),
                 'entity_id', CASE WHEN job_rows.recipient_id IS NULL THEN NULL ELSE job_rows.recipient_id::text END,
                 'candidate_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'CANDIDATE' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'umbrella_id', CASE WHEN upper(coalesce(job_rows.recipient_kind, '')) = 'UMBRELLA' AND job_rows.recipient_id IS NOT NULL THEN job_rows.recipient_id::text ELSE NULL END,
                 'name', job_rows.recipient_name,
                 'email', job_rows.recipient_email,
                 'remittance_email', job_rows.recipient_email
               )),
               'payment_scope_json', jsonb_strip_nulls(COALESCE(job_rows.payload_json, '{}'::jsonb) || jsonb_build_object(
                 'pay_batch_id', p_pay_batch_id::text,
                 'operation_id', p_operation_id::text,
                 'remittance_scope_id', job_rows.id::text,
                 'deterministic_outbox_key', job_rows.deterministic_outbox_key,
                 'remittance_type', job_rows.remittance_type
               )),
               'payload_json', job_rows.payload_json
             )) ORDER BY job_rows.id::text), '[]'::jsonb),
             CASE
               WHEN COUNT(*) = 0 THEN NULL::jsonb
               ELSE jsonb_build_object('last_remittance_scope_id', max(job_rows.id::text))
             END
      INTO v_selected_scope_count,
           v_operation_scope_ids,
           v_operation_jobs,
           v_next_cursor_json
      FROM job_rows;

      SELECT COUNT(*)::integer
      INTO v_known_scope_count
      FROM public.banking_pay_operation_remittance_scope AS scope_count_row
      WHERE scope_count_row.operation_id = p_operation_id
        AND scope_count_row.pay_batch_id = p_pay_batch_id
        AND scope_count_row.status IN ('PENDING', 'FAILED');
    END IF;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'scope', v_scope,
      'pay_date', CASE WHEN COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date) IS NULL THEN NULL ELSE COALESCE(v_batch.authoritative_payment_date, v_batch.pay_date)::text END,
      'authoritative_payment_date', CASE WHEN v_batch.authoritative_payment_date IS NULL THEN NULL ELSE v_batch.authoritative_payment_date::text END,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', CASE WHEN v_batch.execution_committed_at_utc IS NULL THEN NULL ELSE v_batch.execution_committed_at_utc::text END,
      'candidate_count_targeted', v_selected_scope_count,
      'scope_count', v_selected_scope_count,
      'known_count', v_known_scope_count,
      'remittance_scope_ids', v_operation_scope_ids,
      'next_cursor', v_next_cursor_json,
      'jobs', v_operation_jobs
    );
  END IF;

  -- ✅ Load remittance settings + new defaults (single row, id=1 semantics)
  select
    sd.remittance_includes_json,
    sd.remittance_header_message,
    sd.remittance_footer_message,
    coalesce(sd.paye_remittances_enabled,false) as paye_remittances_enabled,
    coalesce(sd.remittances_detailed_breakdown,false) as remittances_detailed_breakdown,
    coalesce(sd.remittance_receive_when_umbrella_paid,false) as remittance_receive_when_umbrella_paid
  into
    v_remittance_includes_json,
    v_remittance_header_message,
    v_remittance_footer_message,
    v_sd_paye_remittances_enabled,
    v_sd_remittances_detailed_breakdown,
    v_sd_remittance_receive_when_umbrella_paid
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  -- ✅ Normalize include config defaults (safe when config is NULL or not an object)
  if v_remittance_includes_json is not null and jsonb_typeof(v_remittance_includes_json) = 'object' then
    v_missing_scope := upper(btrim(coalesce(v_remittance_includes_json->'defaults'->>'missing_scope', 'WEEKLY')));

    v_unknown_item_type_default_text := lower(btrim(coalesce(v_remittance_includes_json->'defaults'->>'unknown_item_type', 'true')));
    v_unknown_item_type_default := (v_unknown_item_type_default_text in ('true','1','yes','y','on'));
  else
    v_missing_scope := 'WEEKLY';
    v_unknown_item_type_default := true;
  end if;

  if v_unknown_item_type_default then
    v_unknown_item_type_default_text := 'true';
  else
    v_unknown_item_type_default_text := 'false';
  end if;

  select
    pb.id,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.status,
    pb.bulk_reference,
    pb.banking_system_snapshot,
    pb.external_paye_system_snapshot,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id;

  if v_batch.id is null then
    raise exception 'pay_remittance_build: pay batch % not found.', p_pay_batch_id;
  end if;

  SELECT COUNT(*)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND legacy_candidate_count.remittance_sent_at_utc IS NULL;

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REMITTANCE_BUILD_OPERATION_REQUIRED',
      'code', 'REMITTANCE_OPERATION_REQUIRED',
      'message', 'pay_remittance_build legacy mode is limited to small batches; use the scalable remittance operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  -- ============================================================
  -- Umbrella remittance jobs (recipient = umbrella)
  -- HARD RULES:
  --  - generate only when umbrella transfers exist AND umbrella remittance_email exists
  --  - detailed_breakdown resolved from umbrella overrides vs settings_defaults
  --  - when detailed_breakdown=true and SEGMENT timesheet: include schedule rows (worked shifts only)
  --  - aggregate timesheets never include schedules
  --  - include canonical breakdown lines via pay_batch_item_breakdowns (no derived rates)
  -- ============================================================
  if v_scope in ('ALL','UMBRELLA') then
    with umb_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.umbrella_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA'
        and pbt.umbrella_id is not null
        and pbt.candidate_id is not null
    ),
    umb_roster as (
      select
        ut.umbrella_id,
        max(u.name) as umbrella_name,
        max(u.remittance_email) as remittance_email,
        bool_or(coalesce(u.remittance_overrides_enabled,false)) as umb_override_enabled,
        bool_or(coalesce(u.remittances_detailed_breakdown,false)) as umb_detail_enabled,
        bool_or(coalesce(ut.is_simulated,false)) as test_mode
      from umb_transfers ut
      join public.umbrellas u
        on u.id = ut.umbrella_id
      group by ut.umbrella_id
      having nullif(btrim(coalesce(max(u.remittance_email),'')),'') is not null
    ),
    umb_job_flags as (
      select
        ur.umbrella_id,
        case
          when ur.umb_override_enabled then ur.umb_detail_enabled
          else v_sd_remittances_detailed_breakdown
        end as detailed_breakdown
      from umb_roster ur
    ),
    umb_candidates as (
      select distinct
        ut.umbrella_id,
        ut.candidate_id
      from umb_transfers ut
    ),
    cand_meta as (
      select
        uc.umbrella_id,
        c.id as candidate_id,
        c.tms_ref as tms_ref,
        c.display_name as display_name,
        c.email as email
      from umb_candidates uc
      join public.candidates c
        on c.id = uc.candidate_id
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        uc.umbrella_id,
        pbc.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel,
        pbi.umbrella_id as item_umbrella_id,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope_norm
      from umb_candidates uc
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = uc.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    candidate_total_items as (
      select
        uc.umbrella_id,
        pbc.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.timesheet_id,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat
      from umb_candidates uc
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = uc.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
    ),
    ts_meta as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by
        ci.umbrella_id, ci.candidate_id, ci.timesheet_id,
        ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.umbrella_id,
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.pay_batch_id,
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.pay_batch_id,
        tss.timesheet_id,
        tss.candidate_id,
        tss.pay_channel,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by
        tss.pay_batch_id,
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.umbrella_id,
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        pbib.bucket_code,
        pbib.unit_name,
        pbib.units,
        pbib.rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.umbrella_id,
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.umbrella_id, br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.umbrella_id,
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.umbrella_id = tc.umbrella_id
       and r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.umbrella_id,
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.umbrella_id, ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.umbrella_id,
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.umbrella_id = x.umbrella_id
       and ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.umbrella_id, ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.umbrella_id,
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ujf.detailed_breakdown,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ujf.detailed_breakdown,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join umb_job_flags ujf
        on ujf.umbrella_id = ts.umbrella_id
      left join ts_schedule_rows_all sr
        on sr.umbrella_id = ts.umbrella_id
       and sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.umbrella_id = ts.umbrella_id
       and sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.umbrella_id, ts.candidate_id
    ),
    candidate_frozen_totals as (
      select
        ci.umbrella_id,
        ci.candidate_id,
        (count(distinct ci.timesheet_id) filter (where ci.timesheet_id is not null))::integer as timesheet_count,
        count(distinct ci.pay_batch_item_id)::integer as item_count,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_ex_vat,0)
          end
        ),0),2) as gross_ex_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_vat,0)
          end
        ),0),2) as gross_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0
            when coalesce(ci.amount_inc_vat,0) < 0 or coalesce(ci.amount_ex_vat,0) < 0 then 0
            else coalesce(ci.amount_inc_vat,0)
          end
        ),0),2) as gross_inc_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_ex_vat,0))
            when coalesce(ci.amount_ex_vat,0) < 0 then abs(coalesce(ci.amount_ex_vat,0))
            else 0
          end
        ),0),2) as deductions_ex_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_vat,0))
            when coalesce(ci.amount_vat,0) < 0 then abs(coalesce(ci.amount_vat,0))
            else 0
          end
        ),0),2) as deductions_vat,
        round(coalesce(sum(
          case
            when ci.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(ci.amount_inc_vat,0))
            when coalesce(ci.amount_inc_vat,0) < 0 then abs(coalesce(ci.amount_inc_vat,0))
            else 0
          end
        ),0),2) as deductions_inc_vat,
        round(coalesce(sum(coalesce(ci.amount_ex_vat,0)),0),2) as net_ex_vat,
        round(coalesce(sum(coalesce(ci.amount_vat,0)),0),2) as net_vat,
        round(coalesce(sum(coalesce(ci.amount_inc_vat,0)),0),2) as net_inc_vat
      from candidate_total_items ci
      group by ci.umbrella_id, ci.candidate_id
    ),
    candidate_payload as (
      select
        cm.umbrella_id,
        cm.candidate_id,
        jsonb_build_object(
          'candidate_id', cm.candidate_id::text,
          'stable_candidate_key', cm.candidate_id::text,
          'tms_ref', cm.tms_ref,
          'candidate_tms_ref', cm.tms_ref,
          'works_number', cm.tms_ref,
          'display_name', cm.display_name,
          'candidate_display_name', cm.display_name,
          'email', cm.email,
          'timesheets', coalesce(ct.timesheets_json,'[]'::jsonb),
          'totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cm.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', jsonb_build_object(
            'timesheet_count', coalesce(cft.timesheet_count, 0),
            'item_count', coalesce(cft.item_count, 0),
            'gross_ex_vat', round(coalesce(cft.gross_ex_vat,0),2),
            'vat', round(coalesce(cft.gross_vat,0),2),
            'gross_vat', round(coalesce(cft.gross_vat,0),2),
            'gross_inc_vat', round(coalesce(cft.gross_inc_vat,0),2),
            'deductions_ex_vat', round(coalesce(cft.deductions_ex_vat,0),2),
            'deductions_vat', round(coalesce(cft.deductions_vat,0),2),
            'deductions_inc_vat', round(coalesce(cft.deductions_inc_vat,0),2),
            'deductions_recoveries_ex_vat', round(coalesce(cft.deductions_ex_vat,0),2),
            'deductions_recoveries_vat', round(coalesce(cft.deductions_vat,0),2),
            'deductions_recoveries_inc_vat', round(coalesce(cft.deductions_inc_vat,0),2),
            'net_ex_vat', round(coalesce(cft.net_ex_vat,0),2),
            'net_vat', round(coalesce(cft.net_vat,0),2),
            'net_inc_vat', round(coalesce(cft.net_inc_vat,0),2),
            'final_payable', round(coalesce(cft.net_inc_vat,0),2)
          ),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cm.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'UMBRELLA'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        ) as candidate_json
      from cand_meta cm
      left join cand_timesheets ct
        on ct.umbrella_id = cm.umbrella_id
       and ct.candidate_id = cm.candidate_id
      left join candidate_frozen_totals cft
        on cft.umbrella_id = cm.umbrella_id
       and cft.candidate_id = cm.candidate_id
    ),
    umbrella_transfer_totals as (
      select
        ut.umbrella_id,
        round(coalesce(sum(coalesce(ut.amount,0)),0),2) as umbrella_total_amount,
        coalesce(max(nullif(btrim(coalesce(ut.currency,'')),'')), 'GBP') as currency,
        bool_or(coalesce(ut.is_simulated,false)) as transfer_test_mode,
        count(distinct ut.transfer_id)::integer as transfer_count,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'transfer_id', ut.transfer_id::text,
              'candidate_id', case when ut.candidate_id is null then null else ut.candidate_id::text end,
              'pay_channel', ut.pay_channel,
              'amount', ut.amount,
              'currency', ut.currency,
              'status', ut.status,
              'payment_reference', ut.payment_reference,
              'completed_at_utc', case when ut.completed_at_utc is null then null else ut.completed_at_utc::text end,
              'rail_tx_id', ut.rail_tx_id,
              'rail_state', ut.rail_state,
              'rail_meta_json', ut.rail_meta_json,
              'failed_reason', ut.failed_reason,
              'is_simulated', coalesce(ut.is_simulated,false)
            )
            order by ut.candidate_id, ut.transfer_id
          ),
          '[]'::jsonb
        ) as transfers_json
      from umb_transfers ut
      group by ut.umbrella_id
    ),
    umbrella_candidate_payloads as (
      select
        cp.umbrella_id,
        count(distinct cp.candidate_id)::integer as candidate_count,
        coalesce(
          jsonb_agg(cp.candidate_json order by (cp.candidate_json->>'display_name') nulls last, (cp.candidate_json->>'tms_ref') nulls last, cp.candidate_id),
          '[]'::jsonb
        ) as candidates_json
      from candidate_payload cp
      group by cp.umbrella_id
    ),
    umbrella_frozen_totals as (
      select
        cft.umbrella_id,
        coalesce(sum(coalesce(cft.timesheet_count,0)),0)::integer as timesheet_count,
        coalesce(sum(coalesce(cft.item_count,0)),0)::integer as item_count,
        round(coalesce(sum(coalesce(cft.gross_ex_vat,0)),0),2) as gross_ex_vat,
        round(coalesce(sum(coalesce(cft.gross_vat,0)),0),2) as gross_vat,
        round(coalesce(sum(coalesce(cft.gross_inc_vat,0)),0),2) as gross_inc_vat,
        round(coalesce(sum(coalesce(cft.deductions_ex_vat,0)),0),2) as deductions_ex_vat,
        round(coalesce(sum(coalesce(cft.deductions_vat,0)),0),2) as deductions_vat,
        round(coalesce(sum(coalesce(cft.deductions_inc_vat,0)),0),2) as deductions_inc_vat,
        round(coalesce(sum(coalesce(cft.net_ex_vat,0)),0),2) as net_ex_vat,
        round(coalesce(sum(coalesce(cft.net_vat,0)),0),2) as net_vat,
        round(coalesce(sum(coalesce(cft.net_inc_vat,0)),0),2) as net_inc_vat
      from candidate_frozen_totals cft
      group by cft.umbrella_id
    ),
    umb_job as (
      select
        ur.umbrella_id,
        ur.umbrella_name,
        ur.remittance_email,
        (coalesce(ur.test_mode,false) or coalesce(utt.transfer_test_mode,false)) as test_mode,
        ujf.detailed_breakdown,
        round(coalesce(utt.umbrella_total_amount,0),2) as umbrella_total_amount,
        coalesce(utt.currency, 'GBP') as currency,
        coalesce(utt.transfer_count,0) as transfer_count,
        coalesce(ucp.candidate_count,0) as candidate_count,
        coalesce(uft.timesheet_count,0) as timesheet_count,
        coalesce(uft.item_count,0) as item_count,
        round(coalesce(uft.gross_ex_vat,0),2) as gross_ex_vat,
        round(coalesce(uft.gross_vat,0),2) as gross_vat,
        round(coalesce(uft.gross_inc_vat,0),2) as gross_inc_vat,
        round(coalesce(uft.deductions_ex_vat,0),2) as deductions_ex_vat,
        round(coalesce(uft.deductions_vat,0),2) as deductions_vat,
        round(coalesce(uft.deductions_inc_vat,0),2) as deductions_inc_vat,
        round(coalesce(uft.net_ex_vat,0),2) as net_ex_vat,
        round(coalesce(uft.net_vat,0),2) as net_vat,
        round(coalesce(uft.net_inc_vat,0),2) as net_inc_vat,
        coalesce(utt.transfers_json,'[]'::jsonb) as transfers_json,
        coalesce(ucp.candidates_json,'[]'::jsonb) as candidates_json
      from umb_roster ur
      join umb_job_flags ujf
        on ujf.umbrella_id = ur.umbrella_id
      left join umbrella_transfer_totals utt
        on utt.umbrella_id = ur.umbrella_id
      left join umbrella_candidate_payloads ucp
        on ucp.umbrella_id = ur.umbrella_id
      left join umbrella_frozen_totals uft
        on uft.umbrella_id = ur.umbrella_id
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'UMBRELLA_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'UMBRELLA',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(uj.test_mode,false),
          'detailed_breakdown', coalesce(uj.detailed_breakdown,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'UMBRELLA',
            'umbrella_id', uj.umbrella_id::text,
            'name', uj.umbrella_name,
            'remittance_email', uj.remittance_email
          ),
          'summary', jsonb_build_object(
            'total_amount', uj.umbrella_total_amount,
            'currency', coalesce(uj.currency, 'GBP'),
            'transfer_count', coalesce(uj.transfer_count,0),
            'candidate_count', coalesce(uj.candidate_count,0),
            'timesheet_count', coalesce(uj.timesheet_count,0),
            'item_count', coalesce(uj.item_count,0),
            'gross_ex_vat', round(coalesce(uj.gross_ex_vat,0),2),
            'vat', round(coalesce(uj.gross_vat,0),2),
            'gross_vat', round(coalesce(uj.gross_vat,0),2),
            'gross_inc_vat', round(coalesce(uj.gross_inc_vat,0),2),
            'deductions_ex_vat', round(coalesce(uj.deductions_ex_vat,0),2),
            'deductions_vat', round(coalesce(uj.deductions_vat,0),2),
            'deductions_inc_vat', round(coalesce(uj.deductions_inc_vat,0),2),
            'deductions_recoveries_ex_vat', round(coalesce(uj.deductions_ex_vat,0),2),
            'deductions_recoveries_vat', round(coalesce(uj.deductions_vat,0),2),
            'deductions_recoveries_inc_vat', round(coalesce(uj.deductions_inc_vat,0),2),
            'net_ex_vat', round(coalesce(uj.net_ex_vat,0),2),
            'net_vat', round(coalesce(uj.net_vat,0),2),
            'net_inc_vat', round(coalesce(uj.net_inc_vat,0),2),
            'final_payable', uj.umbrella_total_amount,
            'frozen_item_net_inc_vat', round(coalesce(uj.net_inc_vat,0),2)
          ),
          'transfers', coalesce(uj.transfers_json,'[]'::jsonb),
          'candidates', coalesce(uj.candidates_json,'[]'::jsonb)
        )
        order by uj.umbrella_name nulls last, uj.umbrella_id
      ),
      '[]'::jsonb
    )
    into v_jobs_umb
    from umb_job uj;
  end if;

  -- ============================================================
  -- Candidate PAYE remittance jobs (recipient = candidate)
  -- LOCKED RULE:
  --  - generated only if effective receive is true:
  --    overrides? candidate.remittance_receive_enabled : settings_defaults.paye_remittances_enabled
  --  - detailed_breakdown resolved from candidate overrides vs settings_defaults
  -- ============================================================
  if v_scope in ('ALL','PAYE') then
    with paye_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'PAYE'
        and pbt.candidate_id is not null
    ),
    cand_cfg as (
      select
        c.id as candidate_id,
        c.tms_ref,
        c.display_name,
        c.email,
        coalesce(c.remittance_overrides_enabled,false) as overrides_enabled,
        coalesce(c.remittance_receive_enabled,false) as paye_receive_enabled,
        coalesce(c.remittances_detailed_breakdown,false) as detailed_enabled
      from public.candidates c
      where c.id in (select distinct pt.candidate_id from paye_transfers pt)
    ),
    cand_effective as (
      select
        cc.*,
        (case when cc.overrides_enabled then cc.paye_receive_enabled else v_sd_paye_remittances_enabled end) as eff_paye_receive,
        (case when cc.overrides_enabled then cc.detailed_enabled else v_sd_remittances_detailed_breakdown end) as eff_detailed
      from cand_cfg cc
    ),
    cand_allowed as (
      select *
      from cand_effective ce
      where ce.eff_paye_receive = true
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'PAYE'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        ca.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel
      from cand_allowed ca
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = ca.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'PAYE'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    ts_meta as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by ci.candidate_id, ci.timesheet_id, ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.timesheet_id,
        tss.candidate_id,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'PAYE'
      order by
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        pbib.bucket_code,
        pbib.unit_name,
        pbib.units,
        pbib.rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join cand_allowed ca
        on ca.candidate_id = ts.candidate_id
      left join ts_schedule_rows_all sr
        on sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.candidate_id
    ),
    cand_job as (
      select
        ca.candidate_id,
        ca.tms_ref,
        ca.display_name,
        ca.email,
        ca.eff_detailed,
        bool_or(coalesce(pt.is_simulated,false)) as test_mode,
        round(coalesce(sum(pt.amount),0),2) as total_amount,
        coalesce(ct.timesheets_json,'[]'::jsonb) as timesheets_json,
        coalesce(jsonb_agg(
          jsonb_build_object(
            'transfer_id', pt.transfer_id::text,
            'completed_at_utc', case when pt.completed_at_utc is null then null else pt.completed_at_utc::text end,
            'transfer', jsonb_build_object(
              'pay_channel', pt.pay_channel,
              'amount', pt.amount,
              'currency', pt.currency,
              'status', pt.status,
              'payment_reference', pt.payment_reference,
              'rail_tx_id', pt.rail_tx_id,
              'rail_state', pt.rail_state,
              'rail_meta_json', pt.rail_meta_json,
              'failed_reason', pt.failed_reason,
              'is_simulated', coalesce(pt.is_simulated,false)
            )
          )
          order by pt.transfer_id
        ), '[]'::jsonb) as transfers_json
      from cand_allowed ca
      join paye_transfers pt
        on pt.candidate_id = ca.candidate_id
      left join cand_timesheets ct
        on ct.candidate_id = ca.candidate_id
      group by ca.candidate_id, ca.tms_ref, ca.display_name, ca.email, ca.eff_detailed, ct.timesheets_json
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'PAYE_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'PAYE',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(cj.test_mode,false),
          'detailed_breakdown', coalesce(cj.eff_detailed,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'CANDIDATE',
            'candidate_id', cj.candidate_id::text,
            'stable_candidate_key', cj.candidate_id::text,
            'tms_ref', cj.tms_ref,
            'candidate_tms_ref', cj.tms_ref,
            'works_number', cj.tms_ref,
            'display_name', cj.display_name,
            'candidate_display_name', cj.display_name,
            'email', cj.email
          ),
          'summary', jsonb_build_object(
            'total_amount', cj.total_amount,
            'currency', 'GBP'
          ),
          'timesheets', coalesce(cj.timesheets_json,'[]'::jsonb),
          'transfers', coalesce(cj.transfers_json,'[]'::jsonb),
          'net_input', coalesce((
            select jsonb_build_object(
              'source', pni.source,
              'net_amount', pni.net_amount,
              'imported_at_utc', case when pni.imported_at_utc is null then null else pni.imported_at_utc::text end,
              'file_name', pni.file_name
            )
            from public.pay_batch_candidates pbc
            join public.pay_batch_paye_net_inputs pni
              on pni.pay_batch_candidate_id = pbc.id
            where pbc.pay_batch_id = p_pay_batch_id
              and pbc.candidate_id = cj.candidate_id
            order by pni.imported_at_utc desc
            limit 1
          ), null),
          'pay_totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cj.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', coalesce((
            select jsonb_build_object(
              'item_count', count(distinct pbi_ft.id)::integer,
              'gross_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_ex_vat,0) end),0),2),
              'vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_inc_vat,0) end),0),2),
              'deductions_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_ex_vat,0)) when coalesce(pbi_ft.amount_ex_vat,0) < 0 then abs(coalesce(pbi_ft.amount_ex_vat,0)) else 0 end),0),2),
              'deductions_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_vat,0)) when coalesce(pbi_ft.amount_vat,0) < 0 then abs(coalesce(pbi_ft.amount_vat,0)) else 0 end),0),2),
              'deductions_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_inc_vat,0)) when coalesce(pbi_ft.amount_inc_vat,0) < 0 then abs(coalesce(pbi_ft.amount_inc_vat,0)) else 0 end),0),2),
              'net_ex_vat', round(coalesce(sum(coalesce(pbi_ft.amount_ex_vat,0)),0),2),
              'net_vat', round(coalesce(sum(coalesce(pbi_ft.amount_vat,0)),0),2),
              'net_inc_vat', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2),
              'final_payable', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2)
            )
            from public.pay_batch_candidates pbc_ft
            join public.pay_batch_items pbi_ft
              on pbi_ft.pay_batch_candidate_id = pbc_ft.id
            where pbc_ft.pay_batch_id = p_pay_batch_id
              and pbc_ft.candidate_id = cj.candidate_id
              and pbi_ft.item_type <> 'DEBT_CREATED'
              and coalesce(pbi_ft.is_voided,false) = false
          ), '{}'::jsonb),
          'paye_net_advisory', coalesce((
            select jsonb_build_object(
              'original_net_input', (
                select pni2.net_amount
                from public.pay_batch_paye_net_inputs pni2
                where pni2.pay_batch_candidate_id = pbc_adv.id
                order by pni2.imported_at_utc desc
                limit 1
              ),
              'payment_advance_repayment_taken', round(coalesce(pbc_adv.loan_repayment_taken,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_adv.overpayment_recovery_taken,0),2),
              'final_net_paid', round(coalesce(pbc_adv.net_bank_amount,0),2)
            )
            from public.pay_batch_candidates pbc_adv
            where pbc_adv.pay_batch_id = p_pay_batch_id
              and pbc_adv.candidate_id = cj.candidate_id
            limit 1
          ), null),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cj.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'PAYE'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        )
        order by cj.display_name nulls last, cj.tms_ref nulls last, cj.candidate_id
      ),
      '[]'::jsonb
    )
    into v_jobs_paye
    from cand_job cj;
  end if;

  -- ============================================================
  -- Candidate umbrella-copy jobs (recipient=candidate; umbrella items only)
  -- LOCKED RULE:
  --  - generated only if effective receive_when_umbrella_paid is true:
  --    overrides? candidate.remittance_receive_when_umbrella_paid : settings_defaults.remittance_receive_when_umbrella_paid
  --  - detailed_breakdown resolved from candidate overrides vs settings_defaults
  -- ============================================================
  if v_scope in ('ALL','UMBRELLA') then
    with umb_transfers as (
      select
        pbt.id as transfer_id,
        pbt.pay_batch_id,
        pbt.candidate_id,
        pbt.umbrella_id,
        pbt.pay_channel,
        pbt.amount,
        pbt.currency,
        pbt.status,
        pbt.payment_reference,
        pbt.completed_at_utc,
        pbt.rail_tx_id,
        pbt.rail_state,
        pbt.rail_meta_json,
        pbt.failed_reason,
        (
          upper(coalesce(pbt.rail_state,'')) = 'PAYROLL_TESTING'
          or (
            pbt.rail_meta_json is not null
            and (pbt.rail_meta_json ? 'simulated')
            and lower(btrim(coalesce(pbt.rail_meta_json->>'simulated',''))) in ('true','1','yes','y','on')
          )
        ) as is_simulated
      from public.pay_bank_transfers pbt
      where pbt.pay_batch_id = p_pay_batch_id
        and upper(coalesce(pbt.pay_channel,'')) = 'UMBRELLA'
        and pbt.umbrella_id is not null
        and pbt.candidate_id is not null
    ),
    cand_cfg as (
      select
        c.id as candidate_id,
        c.tms_ref,
        c.display_name,
        c.email,
        coalesce(c.remittance_overrides_enabled,false) as overrides_enabled,
        coalesce(c.remittances_detailed_breakdown,false) as detailed_enabled,
        coalesce(c.remittance_receive_when_umbrella_paid,false) as umb_copy_enabled
      from public.candidates c
      where c.id in (select distinct ut.candidate_id from umb_transfers ut)
    ),
    cand_effective as (
      select
        cc.*,
        (case when cc.overrides_enabled then cc.umb_copy_enabled else v_sd_remittance_receive_when_umbrella_paid end) as eff_copy,
        (case when cc.overrides_enabled then cc.detailed_enabled else v_sd_remittances_detailed_breakdown end) as eff_detailed
      from cand_cfg cc
    ),
    cand_allowed as (
      select *
      from cand_effective ce
      where ce.eff_copy = true
    ),
    ts_scope_artifact as (
      select distinct on (tss.candidate_id, tss.timesheet_id)
        tss.candidate_id,
        tss.timesheet_id,
        case
          when tss.target_snapshot_json is not null
           and jsonb_typeof(tss.target_snapshot_json) = 'object'
           and jsonb_typeof(tss.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tss.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s) = 'object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'DAILY'
          else 'WEEKLY'
        end as sheet_scope_norm
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by tss.candidate_id, tss.timesheet_id, tss.created_at_utc desc, tss.id desc
    ),
    cand_items as (
      select
        ca.candidate_id,
        pbi.id as pay_batch_item_id,
        pbi.item_type,
        pbi.description,
        pbi.timesheet_id,
        pbi.segment_key,
        pbi.source_ref,
        pbi.amount_ex_vat,
        pbi.amount_vat,
        pbi.amount_inc_vat,
        pbi.pay_channel
      from cand_allowed ca
      join public.pay_batch_candidates pbc
        on pbc.pay_batch_id = p_pay_batch_id
       and pbc.candidate_id = ca.candidate_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = pbc.candidate_id
       and tsa.timesheet_id = pbi.timesheet_id
      where upper(coalesce(pbi.pay_channel,'')) = 'UMBRELLA'
        and pbi.item_type <> 'DEBT_CREATED'
        and coalesce(pbi.is_voided,false) = false
        and (
          case
            when upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) = 'DAILY' then
              (case
                 when lower(coalesce(v_remittance_includes_json->'daily'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
            else
              (case
                 when lower(coalesce(v_remittance_includes_json->'weekly'->'include_item_types'->>pbi.item_type, v_unknown_item_type_default_text)) in ('true','1','yes','y','on')
                 then true else false end)
          end
        )
    ),
    ts_meta as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ts.week_ending_date,
        ts.reference_number,
        ts.contract_id,
        nullif(btrim(coalesce(ts.job_title_norm,'')),'') as job_title_norm,
        nullif(btrim(coalesce(ts.band,'')),'') as band_norm
      from cand_items ci
      left join public.timesheets ts
        on ts.timesheet_id = ci.timesheet_id
       and ts.is_current = true
      where ci.timesheet_id is not null
      group by ci.candidate_id, ci.timesheet_id, ts.week_ending_date, ts.reference_number, ts.contract_id, ts.job_title_norm, ts.band
    ),
    ts_enrich as (
      select
        tm.candidate_id,
        tm.timesheet_id,
        tm.week_ending_date,
        tm.reference_number,
        vs.client_id as client_id,
        vs.client_name as client_name,
        upper(coalesce(tsa.sheet_scope_norm, v_missing_scope)) as sheet_scope,
        nullif(btrim(coalesce(ct.role, tm.job_title_norm)),'') as job_title,
        nullif(btrim(coalesce(ct.band, tm.band_norm)),'') as band
      from ts_meta tm
      left join public.contracts ct
        on ct.id = tm.contract_id
      left join public.v_timesheets_summary vs
        on vs.timesheet_id = tm.timesheet_id
      left join ts_scope_artifact tsa
        on tsa.candidate_id = tm.candidate_id
       and tsa.timesheet_id = tm.timesheet_id
    ),
    ts_snap as (
      select distinct on (
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,''))
      )
        tss.timesheet_id,
        tss.candidate_id,
        tss.base_snapshot_json,
        tss.target_snapshot_json
      from public.pay_batch_timesheet_snapshots tss
      where tss.pay_batch_id = p_pay_batch_id
        and upper(coalesce(tss.pay_channel,'')) = 'UMBRELLA'
      order by
        tss.candidate_id,
        tss.timesheet_id,
        upper(coalesce(tss.pay_channel,'')),
        tss.created_at_utc desc,
        tss.id desc
    ),
    ts_class as (
      select
        te.candidate_id,
        te.timesheet_id,
        te.week_ending_date,
        te.reference_number,
        te.client_id,
        te.client_name,
        te.sheet_scope,
        te.job_title,
        te.band,
        tsn.base_snapshot_json,
        tsn.target_snapshot_json,
        case
          when tsn.target_snapshot_json is not null
           and jsonb_typeof(tsn.target_snapshot_json) = 'object'
           and jsonb_typeof(tsn.target_snapshot_json->'segments') = 'array'
           and exists (
             select 1
             from jsonb_array_elements(tsn.target_snapshot_json->'segments') s
             where s is not null
               and jsonb_typeof(s)='object'
               and nullif(btrim(coalesce(s->>'date','')),'') is not null
           )
          then 'SEGMENT'
          else 'AGGREGATE'
        end as timesheet_render_mode,
        case
          when tsn.base_snapshot_json is null then 'Standard'
          when tsn.base_snapshot_json = '{}'::jsonb then 'Standard'
          when (
            exists (
              select 1
              from jsonb_array_elements(coalesce(tsn.base_snapshot_json->'segments','[]'::jsonb)) s
              where s is not null and jsonb_typeof(s)='object'
                and round(coalesce(nullif(s->>'pay_amount','')::numeric,0),2) <> 0
            )
            or round(coalesce(nullif(tsn.base_snapshot_json->>'additional_pay_ex_vat','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,expenses_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,travel_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,accommodation_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,other_pay_ex_vat}','')::numeric,0),2) <> 0
            or round(coalesce(nullif(tsn.base_snapshot_json #>> '{expenses,mileage_pay_ex_vat}','')::numeric,0),2) <> 0
            or (
              jsonb_typeof(tsn.base_snapshot_json->'adjustments')='array'
              and jsonb_array_length(tsn.base_snapshot_json->'adjustments') > 0
            )
          )
          then 'Adjustment'
          else 'Standard'
        end as timesheet_type
      from ts_enrich te
      left join ts_snap tsn
        on tsn.timesheet_id = te.timesheet_id
       and tsn.candidate_id = te.candidate_id
    ),
    breakdown_raw as (
      select
        ci.candidate_id,
        ci.timesheet_id,
        ci.pay_batch_item_id,
        pbib.id as pay_batch_item_breakdown_id,
        pbib.line_kind,
        pbib.bucket_code,
        pbib.unit_name,
        pbib.units,
        pbib.rate,
        pbib.amount_ex_vat,
        pbib.amount_vat,
        pbib.amount_inc_vat
      from cand_items ci
      join public.pay_batch_item_breakdowns pbib
        on pbib.pay_batch_item_id = ci.pay_batch_item_id
      where ci.timesheet_id is not null
    ),
    ts_unit_rows as (
      select
        br.candidate_id,
        br.timesheet_id,
        array_remove(array_agg(distinct br.pay_batch_item_id::text), NULL::text) as pay_batch_item_ids,
        array_remove(array_agg(distinct br.pay_batch_item_breakdown_id::text), NULL::text) as pay_batch_item_breakdown_ids,
        br.line_kind,
        br.bucket_code,
        br.unit_name,
        br.rate,
        round(sum(coalesce(br.units,0)),2) as quantity,
        round(sum(coalesce(br.amount_ex_vat,0)),2) as total_ex_vat,
        round(sum(coalesce(br.amount_vat,0)),2) as total_vat,
        round(sum(coalesce(br.amount_inc_vat,0)),2) as total_inc_vat
      from breakdown_raw br
      group by br.candidate_id, br.timesheet_id, br.line_kind, br.bucket_code, br.unit_name, br.rate
      having
        round(sum(coalesce(br.units,0)),2) <> 0
        or round(sum(coalesce(br.amount_ex_vat,0)),2) <> 0
        or round(sum(coalesce(br.amount_inc_vat,0)),2) <> 0
    ),
    ts_sections as (
      select
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by
              case upper(coalesce(r.bucket_code,''))
                when 'DAY' then 1
                when 'NIGHT' then 2
                when 'SAT' then 3
                when 'SUN' then 4
                when 'BH' then 5
                else 99
              end,
              coalesce(r.unit_name,'') asc,
              coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'TS_BUCKET'),
          '[]'::jsonb
        ) as unit_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc, coalesce(r.rate,0) asc
          )
          filter (where upper(coalesce(r.line_kind,'')) = 'ADDITIONAL_UNIT'),
          '[]'::jsonb
        ) as additional_units_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('EXPENSE','MILEAGE')),
          '[]'::jsonb
        ) as expenses_rows,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', tc.candidate_id::text,
              'timesheet_id', tc.timesheet_id::text,
              'stable_line_key', md5(concat_ws('|', tc.candidate_id::text, tc.timesheet_id::text, coalesce(r.line_kind,''), coalesce(r.bucket_code,''), coalesce(r.unit_name,''), coalesce(r.rate::text,''), coalesce(r.quantity::text,''), coalesce(r.total_ex_vat::text,''), coalesce(r.total_vat::text,''), coalesce(r.total_inc_vat::text,''))),
              'pay_batch_item_ids', to_jsonb(r.pay_batch_item_ids),
              'pay_batch_item_breakdown_ids', to_jsonb(r.pay_batch_item_breakdown_ids),
              'line_kind_raw', r.line_kind,
              'bucket_code', r.bucket_code,
              'unit', r.unit_name,
              'quantity', r.quantity,
              'rate', r.rate,
              'total_ex_vat', r.total_ex_vat,
              'total_vat', r.total_vat,
              'total_inc_vat', r.total_inc_vat,
              'line_kind', case
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when upper(coalesce(r.line_kind,'')) = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when upper(coalesce(r.line_kind,'')) = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when upper(coalesce(r.line_kind,'')) = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else r.line_kind
                  end
            )
            order by coalesce(r.unit_name,'') asc
          )
          filter (where upper(coalesce(r.line_kind,'')) in ('ADJUSTMENT','CONVERSION_ADJ','LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY','DEBT_CREATED')),
          '[]'::jsonb
        ) as other_rows,
        round(coalesce(sum(r.total_ex_vat),0),2) as totals_ex_vat,
        round(coalesce(sum(r.total_vat),0),2) as totals_vat,
        round(coalesce(sum(r.total_inc_vat),0),2) as totals_inc_vat,
        tc.base_snapshot_json,
        tc.target_snapshot_json
      from ts_class tc
      left join ts_unit_rows r
        on r.candidate_id = tc.candidate_id
       and r.timesheet_id = tc.timesheet_id
      group by
        tc.candidate_id,
        tc.timesheet_id,
        tc.week_ending_date,
        tc.reference_number,
        tc.client_id,
        tc.client_name,
        tc.job_title,
        tc.band,
        tc.timesheet_render_mode,
        tc.timesheet_type,
        tc.base_snapshot_json,
        tc.target_snapshot_json
    ),
    ts_schedule_rows_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', nullif(btrim(coalesce(s->>'segment_id','')),''),
              'date', nullif(btrim(coalesce(s->>'date','')),''),
              'start_utc', nullif(btrim(coalesce(s->>'start_utc','')),''),
              'end_utc', nullif(btrim(coalesce(s->>'end_utc','')),''),
              'break_mins', coalesce(nullif(s->>'break_mins','')::numeric,0),
              'breaks', coalesce(s->'breaks','[]'::jsonb)
            )
            order by
              nullif(btrim(coalesce(s->>'date','')),'') asc,
              nullif(btrim(coalesce(s->>'start_utc','')),'') asc,
              nullif(btrim(coalesce(s->>'segment_id','')),'') asc
          ),
          '[]'::jsonb
        ) as schedule_rows
      from ts_sections ts
      join lateral jsonb_array_elements(coalesce(ts.target_snapshot_json->'segments','[]'::jsonb)) s
        on ts.target_snapshot_json is not null
       and jsonb_typeof(ts.target_snapshot_json)='object'
      where ts.timesheet_render_mode = 'SEGMENT'
        and s is not null
        and jsonb_typeof(s)='object'
        and coalesce(nullif(s->>'exclude_from_pay','')::boolean,false) = false
        and (
          coalesce(nullif(s->>'hours_day','')::numeric,0)
          + coalesce(nullif(s->>'hours_night','')::numeric,0)
          + coalesce(nullif(s->>'hours_sat','')::numeric,0)
          + coalesce(nullif(s->>'hours_sun','')::numeric,0)
          + coalesce(nullif(s->>'hours_bh','')::numeric,0)
        ) > 0
      group by ts.candidate_id, ts.timesheet_id
    ),
    ts_schedule_changes_all as (
      select
        ts.candidate_id,
        ts.timesheet_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'segment_id', x.seg_id,
              'date', coalesce(x.before_seg->>'date', x.after_seg->>'date'),
              'before', jsonb_build_object(
                'start_utc', x.before_seg->>'start_utc',
                'end_utc', x.before_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.before_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false)
              ),
              'after', jsonb_build_object(
                'start_utc', x.after_seg->>'start_utc',
                'end_utc', x.after_seg->>'end_utc',
                'break_mins', coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0),
                'breaks', coalesce(x.after_seg->'breaks','[]'::jsonb),
                'exclude_from_pay', coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
              )
            )
            order by
              coalesce(x.before_seg->>'date', x.after_seg->>'date') asc,
              coalesce(x.before_seg->>'start_utc', x.after_seg->>'start_utc') asc,
              x.seg_id asc
          ),
          '[]'::jsonb
        ) as schedule_changes
      from (
        select
          ts0.candidate_id,
          ts0.timesheet_id,
          nullif(btrim(coalesce(ids.s->>'segment_id','')),'') as seg_id,
          bseg.seg as before_seg,
          aseg.seg as after_seg
        from ts_sections ts0
        join lateral (
          select s
          from (
            select s0 as s from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s0
            union all
            select s1 as s from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s1
          ) u
          where u.s is not null and jsonb_typeof(u.s)='object'
        ) ids
          on ts0.timesheet_render_mode = 'SEGMENT'
         and ts0.timesheet_type = 'Adjustment'
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.base_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) bseg on true
        left join lateral (
          select s as seg
          from jsonb_array_elements(coalesce(ts0.target_snapshot_json->'segments','[]'::jsonb)) s
          where s is not null and jsonb_typeof(s)='object'
            and nullif(btrim(coalesce(s->>'segment_id','')),'') = nullif(btrim(coalesce(ids.s->>'segment_id','')),'')
          limit 1
        ) aseg on true
      ) x
      join ts_sections ts
        on ts.candidate_id = x.candidate_id
       and ts.timesheet_id = x.timesheet_id
      where x.seg_id is not null
        and (
          coalesce(x.before_seg->>'start_utc','') <> coalesce(x.after_seg->>'start_utc','')
          or coalesce(x.before_seg->>'end_utc','') <> coalesce(x.after_seg->>'end_utc','')
          or coalesce(nullif(x.before_seg->>'break_mins','')::numeric,0) <> coalesce(nullif(x.after_seg->>'break_mins','')::numeric,0)
          or coalesce(x.before_seg->'breaks','[]'::jsonb) <> coalesce(x.after_seg->'breaks','[]'::jsonb)
          or coalesce(nullif(x.before_seg->>'exclude_from_pay','')::boolean,false) <> coalesce(nullif(x.after_seg->>'exclude_from_pay','')::boolean,false)
        )
      group by ts.candidate_id, ts.timesheet_id
    ),
    cand_timesheets as (
      select
        ts.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'candidate_id', ts.candidate_id::text,
              'timesheet_id', ts.timesheet_id::text,
              'stable_timesheet_key', concat_ws('|', ts.candidate_id::text, ts.timesheet_id::text, coalesce(ts.week_ending_date::text,''), coalesce(ts.client_id::text,'')),
              'week_ending_date', case when ts.week_ending_date is null then null else ts.week_ending_date::text end,
              'reference_number', ts.reference_number,
              'client_id', case when ts.client_id is null then null else ts.client_id::text end,
              'client_name', ts.client_name,
              'job_title', ts.job_title,
              'band', ts.band,
              'timesheet_render_mode', ts.timesheet_render_mode,
              'timesheet_type', ts.timesheet_type,
              'frozen_gross_ex_vat', ts.totals_ex_vat,
              'frozen_vat', ts.totals_vat,
              'frozen_gross_inc_vat', ts.totals_inc_vat,
              'unit_rows', ts.unit_rows,
              'additional_units_rows', ts.additional_units_rows,
              'expenses_rows', ts.expenses_rows,
              'other_rows', ts.other_rows,
              'totals', jsonb_build_object(
                'total_ex_vat', ts.totals_ex_vat,
                'gross_ex_vat', ts.totals_ex_vat,
                'vat', ts.totals_vat,
                'gross_vat', ts.totals_vat,
                'total_inc_vat', ts.totals_inc_vat,
                'gross_inc_vat', ts.totals_inc_vat
              ),
              'schedule_rows', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT'
                  then coalesce(sr.schedule_rows,'[]'::jsonb)
                else '[]'::jsonb
              end,
              'schedule_changes', case
                when coalesce(ca.eff_detailed,false) = true and ts.timesheet_render_mode = 'SEGMENT' and ts.timesheet_type = 'Adjustment'
                  then coalesce(sc.schedule_changes,'[]'::jsonb)
                else '[]'::jsonb
              end
            )
            order by ts.week_ending_date desc nulls last, ts.client_name nulls last, ts.reference_number nulls last, ts.timesheet_id
          ),
          '[]'::jsonb
        ) as timesheets_json
      from ts_sections ts
      join cand_allowed ca
        on ca.candidate_id = ts.candidate_id
      left join ts_schedule_rows_all sr
        on sr.candidate_id = ts.candidate_id
       and sr.timesheet_id = ts.timesheet_id
      left join ts_schedule_changes_all sc
        on sc.candidate_id = ts.candidate_id
       and sc.timesheet_id = ts.timesheet_id
      group by ts.candidate_id
    ),
    cand_job as (
      select
        ca.candidate_id,
        ca.tms_ref,
        ca.display_name,
        ca.email,
        ca.eff_detailed,
        bool_or(coalesce(ut.is_simulated,false)) as test_mode,
        round(coalesce(sum(ut.amount),0),2) as total_amount,
        coalesce(ct.timesheets_json,'[]'::jsonb) as timesheets_json,
        coalesce(jsonb_agg(
          jsonb_build_object(
            'transfer_id', ut.transfer_id::text,
            'completed_at_utc', case when ut.completed_at_utc is null then null else ut.completed_at_utc::text end,
            'transfer', jsonb_build_object(
              'pay_channel', ut.pay_channel,
              'amount', ut.amount,
              'currency', ut.currency,
              'status', ut.status,
              'payment_reference', ut.payment_reference,
              'rail_tx_id', ut.rail_tx_id,
              'rail_state', ut.rail_state,
              'rail_meta_json', ut.rail_meta_json,
              'failed_reason', ut.failed_reason,
              'is_simulated', coalesce(ut.is_simulated,false)
            )
          )
          order by ut.transfer_id
        ), '[]'::jsonb) as transfers_json
      from cand_allowed ca
      join umb_transfers ut
        on ut.candidate_id = ca.candidate_id
      left join cand_timesheets ct
        on ct.candidate_id = ca.candidate_id
      group by ca.candidate_id, ca.tms_ref, ca.display_name, ca.email, ca.eff_detailed, ct.timesheets_json
    )
    select coalesce(
      jsonb_agg(
        jsonb_build_object(
          'job_kind', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE',
          'pay_batch_id', v_batch.id::text,
          'scope', 'UMBRELLA',
          'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
          'bulk_reference', v_batch.bulk_reference,
          'test_mode', coalesce(cj.test_mode,false),
          'detailed_breakdown', coalesce(cj.eff_detailed,false),
          'recipient', jsonb_build_object(
            'entity_kind', 'CANDIDATE',
            'candidate_id', cj.candidate_id::text,
            'stable_candidate_key', cj.candidate_id::text,
            'tms_ref', cj.tms_ref,
            'candidate_tms_ref', cj.tms_ref,
            'works_number', cj.tms_ref,
            'display_name', cj.display_name,
            'candidate_display_name', cj.display_name,
            'email', cj.email
          ),
          'summary', jsonb_build_object(
            'total_amount', cj.total_amount,
            'currency', 'GBP'
          ),
          'timesheets', coalesce(cj.timesheets_json,'[]'::jsonb),
          'transfers', coalesce(cj.transfers_json,'[]'::jsonb),
          'pay_totals', coalesce((
            select jsonb_build_object(
              'gross_preview', round(coalesce(pbc_tot.gross_preview,0),2),
              'overpayment_recovery_taken', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
              'payment_advance_repayment_taken', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
              'final_paid', round(coalesce(pbc_tot.net_bank_amount,0),2),
              'deductions_summary', jsonb_build_object(
                'gross_positive', round(coalesce(pbc_tot.gross_preview,0),2),
                'overpayment_recovery', round(coalesce(pbc_tot.overpayment_recovery_taken,0),2),
                'payment_advance_repayment', round(coalesce(pbc_tot.loan_repayment_taken,0),2),
                'total_deductions', round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2),
                'final_payable', round(coalesce(pbc_tot.net_bank_amount,0),2),
                'has_deductions', (round(coalesce(pbc_tot.overpayment_recovery_taken,0) + coalesce(pbc_tot.loan_repayment_taken,0),2) > 0)
              )
            )
            from public.pay_batch_candidates pbc_tot
            where pbc_tot.pay_batch_id = p_pay_batch_id
              and pbc_tot.candidate_id = cj.candidate_id
            limit 1
          ), '{}'::jsonb),
          'frozen_totals', coalesce((
            select jsonb_build_object(
              'item_count', count(distinct pbi_ft.id)::integer,
              'gross_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_ex_vat,0) end),0),2),
              'vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_vat,0) end),0),2),
              'gross_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then 0 when coalesce(pbi_ft.amount_inc_vat,0) < 0 or coalesce(pbi_ft.amount_ex_vat,0) < 0 then 0 else coalesce(pbi_ft.amount_inc_vat,0) end),0),2),
              'deductions_ex_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_ex_vat,0)) when coalesce(pbi_ft.amount_ex_vat,0) < 0 then abs(coalesce(pbi_ft.amount_ex_vat,0)) else 0 end),0),2),
              'deductions_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_vat,0)) when coalesce(pbi_ft.amount_vat,0) < 0 then abs(coalesce(pbi_ft.amount_vat,0)) else 0 end),0),2),
              'deductions_inc_vat', round(coalesce(sum(case when pbi_ft.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then abs(coalesce(pbi_ft.amount_inc_vat,0)) when coalesce(pbi_ft.amount_inc_vat,0) < 0 then abs(coalesce(pbi_ft.amount_inc_vat,0)) else 0 end),0),2),
              'net_ex_vat', round(coalesce(sum(coalesce(pbi_ft.amount_ex_vat,0)),0),2),
              'net_vat', round(coalesce(sum(coalesce(pbi_ft.amount_vat,0)),0),2),
              'net_inc_vat', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2),
              'final_payable', round(coalesce(sum(coalesce(pbi_ft.amount_inc_vat,0)),0),2)
            )
            from public.pay_batch_candidates pbc_ft
            join public.pay_batch_items pbi_ft
              on pbi_ft.pay_batch_candidate_id = pbc_ft.id
            where pbc_ft.pay_batch_id = p_pay_batch_id
              and pbc_ft.candidate_id = cj.candidate_id
              and pbi_ft.item_type <> 'DEBT_CREATED'
              and coalesce(pbi_ft.is_voided,false) = false
          ), '{}'::jsonb),
          'non_timesheet_lines', coalesce((
            select coalesce(
              jsonb_agg(
                jsonb_build_object(
                  'pay_batch_item_id', pbi_nt.id::text,
                  'pay_batch_item_breakdown_id', pbib_nt.id::text,
                  'pay_batch_candidate_id', pbc_nt.id::text,
                  'candidate_id', pbc_nt.candidate_id::text,
                  'stable_line_key', concat_ws('|', pbc_nt.candidate_id::text, pbi_nt.id::text, pbib_nt.id::text, coalesce(pbi_nt.item_type,''), coalesce(pbi_nt.source_ref,''), coalesce(pbi_nt.finance_case_id::text,''), coalesce(pbib_nt.line_kind,''), coalesce(pbib_nt.bucket_code,''), coalesce(pbib_nt.unit_name,''), coalesce(pbib_nt.rate::text,''), coalesce(pbib_nt.amount_ex_vat::text,''), coalesce(pbib_nt.amount_vat::text,''), coalesce(pbib_nt.amount_inc_vat::text,'')),
                  'item_type', case
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    else pbi_nt.item_type
                  end,
                  'internal_item_type', pbi_nt.item_type,
                  'description', pbi_nt.description,
                  'line_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'PAYMENT_ADVANCE'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_ADJUSTMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else pbib_nt.line_kind
                  end,
                  'line_label', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment Recovery'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'Payment Advance Repayment'
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
                    when pbi_nt.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual Debt Recovery'
                    when nullif(btrim(coalesce(pa_fc.adjustment_comment,'')), '') is not null then pa_fc.adjustment_comment
                    when nullif(btrim(coalesce(pbib_nt.unit_name,'')), '') is not null then pbib_nt.unit_name
                    when nullif(btrim(coalesce(pbi_nt.description,'')), '') is not null then pbi_nt.description
                    else pbib_nt.line_kind
                  end,
                  'bucket_code', pbib_nt.bucket_code,
                  'unit', pbib_nt.unit_name,
                  'quantity', pbib_nt.units,
                  'rate', pbib_nt.rate,
                  'total_ex_vat', pbib_nt.amount_ex_vat,
                  'total_vat', pbib_nt.amount_vat,
                  'total_inc_vat', pbib_nt.amount_inc_vat,
                  'signed_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'signed_amount_vat', pbib_nt.amount_vat,
                  'signed_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'frozen_amount_ex_vat', pbib_nt.amount_ex_vat,
                  'frozen_amount_vat', pbib_nt.amount_vat,
                  'frozen_amount_inc_vat', pbib_nt.amount_inc_vat,
                  'is_deduction', (pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY')),
                  'deduction_kind', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE_REPAYMENT'
                    when pbi_nt.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
                    else null
                  end,
                  'deduction_amount_ex_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2)
                    else null
                  end,
                  'deduction_amount_inc_vat', case
                    when pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(pbib_nt.amount_inc_vat,0)),2)
                    else null
                  end,
                  'source_ref', pbi_nt.source_ref,
                  'pay_channel', pbi_nt.pay_channel,
                  'routing_kind', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'routing_kind','')), ''),
                  'destination_label', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'payout_destination', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'destination_label','')), ''),
                  'masked_bank_account', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
                  'beneficiary_name', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
                  'bank_details_hash', nullif(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
                  'appears_on_umbrella_remittance', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','false'))) in ('true','1','yes','y','on'),
                  'generates_candidate_payment_advice', lower(btrim(coalesce(pbi_nt.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','false'))) in ('true','1','yes','y','on'),
                  'finance_case_id', case when coalesce(pbi_nt.finance_case_id, pa_fc.id) is null then null else coalesce(pbi_nt.finance_case_id, pa_fc.id)::text end,
                  'finance_case_type', case when pa_fc.case_type is null then null else pa_fc.case_type::text end,
                  'adjustment_comment', pa_fc.adjustment_comment,
                  'lifecycle_state', case when pa_fc.status is null then null else pa_fc.status::text end,
                  'payout_status', case when pa_fc.payout_status is null then null else pa_fc.payout_status::text end,
                  'remaining_amount', round(coalesce(pa_fc.outstanding_amount,0),2),
                  'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
                  'repayment_week_start', case when pbi_nt.repayment_week_start is null then null else pbi_nt.repayment_week_start::text end,
                  'overpayment_context', case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY'
                     and pa_fc.id is not null
                     and upper(coalesce(pa_fc.case_type::text,'')) = 'OVERPAYMENT'
                     and upper(coalesce(pa_fc.status::text,'')) = 'ACTIVE'
                    then jsonb_build_object(
                      'source_timesheet_id', case when pa_fc.linked_timesheet_id is null then null else pa_fc.linked_timesheet_id::text end,
                      'shift_date', case when pa_fc.linked_shift_date is null then null else pa_fc.linked_shift_date::text end,
                      'original_paid_amount', round(coalesce(pa_fc.source_original_paid_amount, pa_fc.original_amount, 0),2),
                      'corrected_paid_amount', round(coalesce(pa_fc.source_corrected_paid_amount, greatest(coalesce(pa_fc.original_amount,0) - coalesce(pa_fc.outstanding_amount,0),0), 0),2),
                      'recovery_this_payment', round(abs(coalesce(pbib_nt.amount_ex_vat,0)),2),
                      'remaining_balance', round(coalesce(pa_fc.outstanding_amount,0),2)
                    )
                    else null
                  end
                )
                order by
                  case
                    when pbi_nt.item_type = 'OVERPAYMENT_RECOVERY' then 1
                    when pbi_nt.item_type = 'LOAN_REPAYMENT' then 2
                    when pbi_nt.item_type = 'LOAN_PAYOUT' then 3
                    else 9
                  end,
                  coalesce(pbib_nt.line_kind,''),
                  coalesce(pbib_nt.unit_name,''),
                  coalesce(pbib_nt.rate,0)
              ),
              '[]'::jsonb
            )
            from public.pay_batch_candidates pbc_nt
            join public.pay_batch_items pbi_nt
              on pbi_nt.pay_batch_candidate_id = pbc_nt.id
            join public.pay_batch_item_breakdowns pbib_nt
              on pbib_nt.pay_batch_item_id = pbi_nt.id
            left join public.pay_advances pa_fc
              on (
                (pbi_nt.finance_case_id is not null and pa_fc.id = pbi_nt.finance_case_id)
                or (
                  pbi_nt.finance_case_id is null
                  and pbi_nt.source_ref is not null
                  and pbi_nt.source_ref = ('advance:' || pa_fc.id::text)
                )
              )
            where pbc_nt.pay_batch_id = p_pay_batch_id
              and pbc_nt.candidate_id = cj.candidate_id
              and upper(coalesce(pbi_nt.pay_channel,'')) = 'UMBRELLA'
              and pbi_nt.is_voided = false
              and pbi_nt.timesheet_id is null
              and pbi_nt.item_type in ('LOAN_REPAYMENT','OVERPAYMENT_RECOVERY','LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
          ), '[]'::jsonb)
        )
        order by cj.display_name nulls last, cj.tms_ref nulls last, cj.candidate_id
      ),
      '[]'::jsonb
    )
    into v_jobs_cand_umb_copy
    from cand_job cj;
  end if;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch.id::text,
    'scope', v_scope,
    'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
          'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'execution_commit_state', v_batch.execution_commit_state,
    'execution_commit_ref', v_batch.execution_commit_ref,
    'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'remittance_header_message', v_remittance_header_message,
    'remittance_footer_message', v_remittance_footer_message,
    'jobs', (coalesce(v_jobs_umb,'[]'::jsonb) || coalesce(v_jobs_paye,'[]'::jsonb) || coalesce(v_jobs_cand_umb_copy,'[]'::jsonb))
  );
end;
$function$;









CREATE OR REPLACE FUNCTION public.pay_reconcile_external_payment(
  p_actor_user_id uuid,
  p_payload_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pay_date date := NULL;
  v_payment_reference text := NULL;
  v_timesheet_ids uuid[] := ARRAY[]::uuid[];
  v_duplicate_timesheet_ids jsonb := '[]'::jsonb;
  v_missing_timesheet_ids jsonb := '[]'::jsonb;
  v_timesheet_count integer := 0;
  v_candidate_count integer := 0;
  v_response jsonb := '{}'::jsonb;
BEGIN
  IF p_payload_json IS NULL OR jsonb_typeof(p_payload_json) <> 'object' THEN
    RAISE EXCEPTION 'pay_reconcile_external_payment: payload_json must be an object';
  END IF;

  IF NULLIF(btrim(coalesce(p_payload_json->>'pay_date', '')), '') IS NOT NULL THEN
    BEGIN
      v_pay_date := (p_payload_json->>'pay_date')::date;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: payload.pay_date is not a valid date (YYYY-MM-DD)';
    END;
  END IF;

  v_payment_reference := NULLIF(
    btrim(
      coalesce(
        p_payload_json->>'payment_reference',
        p_payload_json->>'bulk_reference',
        p_payload_json->>'bank_reference',
        ''
      )
    ),
    ''
  );

  IF p_payload_json ? 'timesheet_ids' THEN
    IF jsonb_typeof(p_payload_json->'timesheet_ids') <> 'array' THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: payload.timesheet_ids must be an array of UUID strings when supplied';
    END IF;

    SELECT coalesce(array_agg((external_reconcile_timesheet_ids.timesheet_id_text)::uuid), ARRAY[]::uuid[])
    INTO v_timesheet_ids
    FROM jsonb_array_elements_text(p_payload_json->'timesheet_ids') AS external_reconcile_timesheet_ids(timesheet_id_text)
    WHERE NULLIF(btrim(external_reconcile_timesheet_ids.timesheet_id_text), '') IS NOT NULL;

    SELECT coalesce(jsonb_agg(duplicate_timesheet_rows.timesheet_id::text ORDER BY duplicate_timesheet_rows.timesheet_id::text), '[]'::jsonb)
    INTO v_duplicate_timesheet_ids
    FROM (
      SELECT supplied_duplicate_timesheet_rows.timesheet_id
      FROM unnest(v_timesheet_ids) AS supplied_duplicate_timesheet_rows(timesheet_id)
      GROUP BY supplied_duplicate_timesheet_rows.timesheet_id
      HAVING count(*) > 1
    ) AS duplicate_timesheet_rows;

    IF jsonb_array_length(v_duplicate_timesheet_ids) > 0 THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: duplicate timesheet_ids %', v_duplicate_timesheet_ids::text;
    END IF;

    SELECT coalesce(jsonb_agg(missing_timesheet_rows.timesheet_id::text ORDER BY missing_timesheet_rows.timesheet_id::text), '[]'::jsonb)
    INTO v_missing_timesheet_ids
    FROM (
      SELECT supplied_timesheet_rows.timesheet_id
      FROM unnest(v_timesheet_ids) AS supplied_timesheet_rows(timesheet_id)
      LEFT JOIN public.timesheets AS current_timesheets
        ON current_timesheets.timesheet_id = supplied_timesheet_rows.timesheet_id
       AND current_timesheets.is_current = true
      WHERE current_timesheets.timesheet_id IS NULL
    ) AS missing_timesheet_rows;

    IF jsonb_array_length(v_missing_timesheet_ids) > 0 THEN
      RAISE EXCEPTION 'pay_reconcile_external_payment: timesheet(s) not found or not current %', v_missing_timesheet_ids::text;
    END IF;

    SELECT count(DISTINCT supplied_timesheet_rows.timesheet_id)::integer
    INTO v_timesheet_count
    FROM unnest(v_timesheet_ids) AS supplied_timesheet_rows(timesheet_id);

    SELECT count(DISTINCT current_financials.candidate_id)::integer
    INTO v_candidate_count
    FROM public.timesheets_financials AS current_financials
    WHERE current_financials.is_current = true
      AND current_financials.timesheet_id = ANY(v_timesheet_ids);
  END IF;

  v_response := jsonb_build_object(
    'ok', false,
    'classification', 'AMBIGUOUS_REVIEW_REQUIRED',
    'recommended_action', 'USE_NORMAL_BATCH_MANUAL_SETTLEMENT',
    'can_apply', false,
    'auto_correction_allowed', false,
    'legacy_no_artifact_batch', true,
    'message', 'USE_PAYMENT_CORRECTION_FLOW: External payment reconciliation must be backfilled into proper Banking Pay batch artifacts, then settled through manual settlement confirmation so pay_bank_event_ingest and pay_settle_rail can preserve frozen correction evidence. Legacy no-artifact reconciliation is AMBIGUOUS_REVIEW_REQUIRED and cannot auto-correct.',
    'pay_date', CASE WHEN v_pay_date IS NULL THEN NULL ELSE v_pay_date::text END,
    'payment_reference', v_payment_reference,
    'timesheet_count', v_timesheet_count,
    'candidate_count', v_candidate_count,
    'hard_blockers', jsonb_build_array(
      jsonb_build_object(
        'code', 'USE_PAYMENT_CORRECTION_FLOW',
        'message', 'Legacy external reconciliation is classified as AMBIGUOUS_REVIEW_REQUIRED. Backfill/create a normal Banking Pay batch and confirm settlement manually so the event/correction artifact path is preserved.'
      )
    )
  );

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_RECONCILE_EXTERNAL_PAYMENT_BLOCKED_LEGACY_NO_ARTIFACT',
    v_response,
    'pay_batch',
    COALESCE(v_payment_reference, 'NO_PAYMENT_REFERENCE'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RAISE EXCEPTION 'USE_PAYMENT_CORRECTION_FLOW: External payment reconciliation must be backfilled into proper Banking Pay batch artifacts before correction can be applied.'
    USING ERRCODE = 'P0001',
          DETAIL = v_response::text;

  RETURN v_response;
END;
$$;


DROP FUNCTION IF EXISTS public.pay_batches_claim_due_scheduled(integer, timestamptz);


CREATE OR REPLACE FUNCTION public.pay_batches_claim_due_scheduled(
  p_limit integer DEFAULT 50,
  p_now_utc timestamptz DEFAULT NULL::timestamptz
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_cutoff timestamptz := COALESCE(p_now_utc, now());
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 500);
  v_batch_record record;
  v_operation_id uuid := NULL::uuid;
  v_operation_created boolean := false;
  v_actor_user_id uuid := NULL::uuid;
  v_idempotency_key text := NULL::text;
  v_input_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_operations_json jsonb := '[]'::jsonb;
  v_claimed_count integer := 0;
  v_operation_config_json jsonb := '{}'::jsonb;
  v_operation_config_snapshot_status text := 'unknown';
BEGIN
  FOR v_batch_record IN
    SELECT
      batch_row.id,
      batch_row.status,
      batch_row.pay_date,
      batch_row.authoritative_payment_date,
      batch_row.schedule_kind,
      batch_row.scheduled_at_utc,
      batch_row.scheduled_by_user_id,
      batch_row.created_by_user_id,
      batch_row.funding_account_ref,
      batch_row.rail_provider_snapshot,
      batch_row.rail_env_snapshot,
      batch_row.execution_intent_json,
      batch_row.execution_commit_state
    FROM public.pay_batches AS batch_row
    CROSS JOIN LATERAL public.pay_batch_submission_evidence(batch_row.id, true) AS submission_evidence(evidence_json)
    WHERE upper(coalesce(batch_row.status, '')) = 'SCHEDULED'
      AND upper(coalesce(batch_row.execution_commit_state, 'NOT_SUBMITTED')) = 'NOT_SUBMITTED'
      AND batch_row.scheduled_at_utc IS NOT NULL
      AND batch_row.scheduled_at_utc <= v_cutoff
      AND batch_row.cancelled_at_utc IS NULL
      AND COALESCE((submission_evidence.evidence_json->>'has_external_provider_submission')::boolean, false) = false
      AND COALESCE((submission_evidence.evidence_json->>'has_pending_provider_outcome')::boolean, false) = false
      AND COALESCE((submission_evidence.evidence_json->>'has_unknown_provider_outcome')::boolean, false) = false
      AND COALESCE((submission_evidence.evidence_json->>'has_terminal_no_money')::boolean, false) = false
      AND COALESCE((submission_evidence.evidence_json->>'has_final_paid_or_settled')::boolean, false) = false
      AND EXISTS (
        SELECT 1
        FROM public.pay_batch_candidates AS active_due_candidates
        JOIN public.pay_batch_items AS active_due_items
          ON active_due_items.pay_batch_candidate_id = active_due_candidates.id
        WHERE active_due_candidates.pay_batch_id = batch_row.id
          AND COALESCE(active_due_items.is_voided, false) = false
          AND active_due_items.item_type <> 'DEBT_CREATED'
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_requests AS open_pre_bank_cancel_requests
        WHERE open_pre_bank_cancel_requests.pay_batch_id = batch_row.id
          AND open_pre_bank_cancel_requests.correction_kind = 'PRE_BANK_CANCEL'
          AND open_pre_bank_cancel_requests.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operations AS provider_submit_operations
        WHERE provider_submit_operations.pay_batch_id = batch_row.id
          AND provider_submit_operations.operation_type IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS')
          AND provider_submit_operations.phase IN ('SUBMIT_PROVIDER_TRANSFERS', 'PROVIDER_SUBMIT', 'CLAIM_PROVIDER_SUBMIT', 'EXECUTE_PROVIDER')
          AND provider_submit_operations.status IN ('QUEUED', 'RUNNING', 'PROCESSING', 'CLAIMED')
      )
    ORDER BY batch_row.scheduled_at_utc ASC, batch_row.id ASC
    FOR UPDATE SKIP LOCKED
    LIMIT v_limit
  LOOP
    v_actor_user_id := COALESCE(v_batch_record.scheduled_by_user_id, v_batch_record.created_by_user_id);
    v_idempotency_key := 'payment-execute:scheduled:batch:' || v_batch_record.id::text || ':scheduled_at:' || COALESCE(v_batch_record.scheduled_at_utc::text, 'none');
    v_input_json := jsonb_strip_nulls(jsonb_build_object(
      'source', 'pay_batches_claim_due_scheduled',
      'pay_batch_id', v_batch_record.id::text,
      'scheduled_at_utc', v_batch_record.scheduled_at_utc::text,
      'schedule_kind', v_batch_record.schedule_kind,
      'execution_mode', COALESCE(v_batch_record.execution_intent_json->>'execution_mode', v_batch_record.execution_intent_json->>'mode', 'STANDARD_BANK'),
      'payment_date', COALESCE(v_batch_record.authoritative_payment_date, v_batch_record.pay_date)::text,
      'funding_account_ref', v_batch_record.funding_account_ref,
      'rail_provider_snapshot', v_batch_record.rail_provider_snapshot,
      'rail_env_snapshot', v_batch_record.rail_env_snapshot,
      'claimed_at_utc', v_now::text
    ));

    WITH operation_config_plan AS (
      SELECT *
      FROM (
        VALUES
          ('validate_freshness', 'PAYMENT_EXECUTE', 'VALIDATE_FRESHNESS', 'FRESHNESS_VALIDATE'),
          ('prepare_transfer_scope', 'PAYMENT_EXECUTE', 'PREPARE_TRANSFER_SCOPE', 'TRANSFER_GROUP'),
          ('prepare_transfer_chunks', 'PAYMENT_EXECUTE', 'PREPARE_TRANSFER_CHUNKS', 'TRANSFER_GROUP'),
          ('submit_provider_transfers', 'PAYMENT_EXECUTE', 'SUBMIT_PROVIDER_TRANSFERS', 'TRANSFER_SUBMIT'),
          ('apply_rail_updates', 'PAYMENT_EXECUTE', 'APPLY_RAIL_UPDATES', 'RAIL_UPDATE'),
          ('settlement_apply_chunks', 'PAYMENT_SETTLEMENT', 'APPLY_SETTLEMENT_CHUNKS', 'SETTLEMENT'),
          ('remittance_queue_chunks', 'REMITTANCE_QUEUE', 'QUEUE_REMITTANCE_CHUNKS', 'REMITTANCE'),
          ('payout_notice_queue_chunks', 'REMITTANCE_QUEUE', 'QUEUE_PAYOUT_NOTICE_CHUNKS', 'PAYOUT_NOTICE')
      ) AS config_plan(config_key, operation_type, phase, chunk_type)
    ), operation_config_rows AS (
      SELECT
        operation_config_plan.config_key,
        operation_config_plan.operation_type,
        operation_config_plan.phase,
        operation_config_plan.chunk_type,
        operation_config_get.chunk_size,
        operation_config_get.min_chunk_size,
        operation_config_get.max_chunk_size,
        operation_config_get.max_advance_ms,
        operation_config_get.lock_seconds
      FROM operation_config_plan
      CROSS JOIN LATERAL public.banking_pay_operation_config_get(
        p_operation_type => operation_config_plan.operation_type,
        p_phase => operation_config_plan.phase,
        p_chunk_type => operation_config_plan.chunk_type
      ) AS operation_config_get
    )
    SELECT jsonb_build_object(
      'source', 'pay_batches_claim_due_scheduled',
      'version', 1,
      'operation_type', 'PAYMENT_EXECUTE',
      'snapshotted_at_utc', v_now::text,
      'lock_seconds', COALESCE(max(operation_config_rows.lock_seconds), 60),
      'max_advance_ms', COALESCE(max(operation_config_rows.max_advance_ms), 15000),
      'chunks', COALESCE(jsonb_object_agg(
        operation_config_rows.config_key,
        jsonb_build_object(
          'operation_type', operation_config_rows.operation_type,
          'phase', operation_config_rows.phase,
          'chunk_type', operation_config_rows.chunk_type,
          'chunk_size', operation_config_rows.chunk_size,
          'min_chunk_size', operation_config_rows.min_chunk_size,
          'max_chunk_size', operation_config_rows.max_chunk_size,
          'max_advance_ms', operation_config_rows.max_advance_ms,
          'lock_seconds', operation_config_rows.lock_seconds
        )
        ORDER BY operation_config_rows.config_key
      ), '{}'::jsonb)
    )
    INTO v_operation_config_json
    FROM operation_config_rows;

    v_operation_config_json := COALESCE(v_operation_config_json, '{}'::jsonb) || jsonb_build_object(
      'freshness_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,validate_freshness,chunk_size}', '')::integer, 50),
      'transfer_scope_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,prepare_transfer_scope,chunk_size}', '')::integer, 100),
      'transfer_prepare_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,prepare_transfer_chunks,chunk_size}', '')::integer, 100),
      'provider_submit_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,submit_provider_transfers,chunk_size}', '')::integer, 50),
      'rail_update_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,apply_rail_updates,chunk_size}', '')::integer, 100),
      'settlement_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,settlement_apply_chunks,chunk_size}', '')::integer, 100),
      'remittance_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,remittance_queue_chunks,chunk_size}', '')::integer, 100),
      'payout_notice_chunk_size', COALESCE(NULLIF(v_operation_config_json #>> '{chunks,payout_notice_queue_chunks,chunk_size}', '')::integer, 100)
    );

    SELECT operation_row.id
    INTO v_operation_id
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.idempotency_key = v_idempotency_key
      AND operation_row.operation_type = 'PAYMENT_EXECUTE'
      AND operation_row.pay_batch_id = v_batch_record.id
    ORDER BY operation_row.created_at_utc DESC NULLS LAST, operation_row.id DESC
    LIMIT 1;

    v_operation_created := false;

    IF v_operation_id IS NULL THEN
      INSERT INTO public.banking_pay_operations (
        id,
        operation_type,
        status,
        phase,
        actor_user_id,
        workbench_session_id,
        pay_batch_id,
        root_operation_id,
        idempotency_key,
        input_json,
        config_json,
        progress_json,
        result_json,
        error_json,
        total_units,
        completed_units,
        failed_units,
        current_chunk_index,
        chunk_count,
        locked_by,
        lock_expires_at_utc,
        created_at_utc,
        started_at_utc,
        updated_at_utc,
        completed_at_utc,
        failed_at_utc
      )
      VALUES (
        gen_random_uuid(),
        'PAYMENT_EXECUTE',
        'QUEUED',
        'VALIDATE_BATCH',
        v_actor_user_id,
        NULL::uuid,
        v_batch_record.id,
        NULL::uuid,
        v_idempotency_key,
        v_input_json,
        v_operation_config_json,
        jsonb_build_object(
          'title', 'Scheduled payment queued',
          'status_text', 'Scheduled payment is ready to continue through the scalable execution operation.',
          'source', 'pay_batches_claim_due_scheduled'
        ),
        NULL::jsonb,
        NULL::jsonb,
        0,
        0,
        0,
        0,
        0,
        NULL::text,
        NULL::timestamptz,
        v_now,
        NULL::timestamptz,
        v_now,
        NULL::timestamptz,
        NULL::timestamptz
      )
      RETURNING id INTO v_operation_id;
      v_operation_created := true;
      v_operation_config_snapshot_status := 'created';
    ELSE
      SELECT CASE
        WHEN operation_existing.config_json IS NULL OR operation_existing.config_json = '{}'::jsonb THEN 'repaired'
        ELSE 'reused'
      END
      INTO v_operation_config_snapshot_status
      FROM public.banking_pay_operations AS operation_existing
      WHERE operation_existing.id = v_operation_id;

      IF v_operation_config_snapshot_status = 'repaired' THEN
        UPDATE public.banking_pay_operations AS operation_update
        SET config_json = v_operation_config_json,
            progress_json = COALESCE(operation_update.progress_json, '{}'::jsonb) || jsonb_build_object(
              'config_snapshot_status', 'repaired',
              'config_snapshot_repaired_at_utc', v_now::text,
              'config_snapshot_source', 'pay_batches_claim_due_scheduled'
            ),
            updated_at_utc = v_now
        WHERE operation_update.id = v_operation_id
          AND (operation_update.config_json IS NULL OR operation_update.config_json = '{}'::jsonb);
      END IF;
    END IF;

    UPDATE public.pay_batches AS batch_update
    SET status = CASE WHEN upper(coalesce(batch_update.status, '')) = 'SCHEDULED' THEN 'EXECUTING' ELSE batch_update.status END,
        executing_started_at_utc = COALESCE(batch_update.executing_started_at_utc, v_now),
        execution_intent_json = jsonb_strip_nulls(COALESCE(batch_update.execution_intent_json, '{}'::jsonb) || jsonb_build_object(
          'active_operation_id', v_operation_id::text,
          'scheduled_claimed_at_utc', v_now::text
        ))
    WHERE batch_update.id = v_batch_record.id
      AND upper(coalesce(batch_update.execution_commit_state, 'NOT_SUBMITTED')) = 'NOT_SUBMITTED';

    v_summary_json := public.pay_batch_execution_summary_get(v_batch_record.id, v_actor_user_id);

    v_operations_json := v_operations_json || jsonb_build_array(jsonb_build_object(
      'pay_batch_id', v_batch_record.id::text,
      'operation_id', v_operation_id::text,
      'operation_created', v_operation_created,
      'operation_config_snapshot_status', v_operation_config_snapshot_status,
      'operation_type', 'PAYMENT_EXECUTE',
      'idempotency_key', v_idempotency_key,
      'scheduled_at_utc', v_batch_record.scheduled_at_utc,
      'actor_user_id', CASE WHEN v_actor_user_id IS NULL THEN NULL ELSE v_actor_user_id::text END,
      'batch_summary', v_summary_json
    ));

    v_claimed_count := v_claimed_count + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'server_utc', v_now,
    'cutoff_utc', v_cutoff,
    'limit', v_limit,
    'claimed_count', v_claimed_count,
    'operations', v_operations_json,
    'claimed', v_operations_json
  );
END;
$function$;




