DROP FUNCTION IF EXISTS public.pay_bank_transfers_apply_rail_updates(uuid, jsonb);
DROP FUNCTION IF EXISTS public.pay_bank_transfers_apply_rail_updates(uuid, jsonb, uuid);
DROP FUNCTION IF EXISTS public.pay_bank_transfers_apply_rail_updates(uuid, jsonb, uuid, uuid, jsonb, uuid);





CREATE OR REPLACE FUNCTION public.pay_bank_transfers_apply_rail_updates(p_pay_batch_id uuid, p_updates jsonb, p_actor_user_id uuid DEFAULT NULL::uuid, p_operation_id uuid DEFAULT NULL::uuid, p_transfer_ids jsonb DEFAULT NULL::jsonb, p_chunk_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_batch_row public.pay_batches%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_input_count integer := 0;
  v_updated_count integer := 0;
  v_event_result_count integer := 0;
  v_missing jsonb := '[]'::jsonb;
  v_duplicates jsonb := '[]'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_submission_evidence_json jsonb := '{}'::jsonb;
  v_provider_submitted_count integer := 0;
  v_local_only_count integer := 0;
  v_failed_count integer := 0;
  v_pending_count integer := 0;
  v_ambiguous_count integer := 0;
  v_attempted_but_unproven_count integer := 0;
  v_provider_attempt_without_external_id_count integer := 0;
  v_remaining_submit_attempt_required integer := 0;
  v_remaining_provider_evidence_required integer := 0;
  v_requires_provider_poll boolean := false;
  v_requires_review boolean := false;
  v_remaining_unsubmitted_count integer := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := NULL::text;
  v_execution_committed_at_utc timestamptz := NULL::timestamptz;
  v_can_mark_submitted boolean := false;
  v_can_mark_committed boolean := false;
  v_chunk_transfer_ids jsonb := NULL::jsonb;
  v_provider_submit_diagnostic jsonb := '{}'::jsonb;
  v_transfer_provider_outcomes jsonb := '[]'::jsonb;
  v_provider_acceptance_evidence_count integer := 0;
  v_provider_external_evidence_count integer := 0;
  v_provider_response_present_count integer := 0;
  v_provider_request_sent_count integer := 0;
  v_provider_submission_unknown_count integer := 0;
  v_is_scoped boolean := false;
  v_counterparty_map_recovery_json jsonb := '[]'::jsonb;
  v_counterparty_map_invalidated_count integer := 0;
  v_counterparty_map_recovery_count integer := 0;
  v_counterparty_map_auto_reverse_setting boolean := false;
  v_counterparty_map_auto_reverse_requested_count integer := 0;
  v_counterparty_map_auto_reverse_applied_count integer := 0;
  v_counterparty_map_manual_recoverable_count integer := 0;
  v_counterparty_map_readiness_enqueue_json jsonb := '[]'::jsonb;
  v_counterparty_recovery_record record;
  v_counterparty_readiness_result jsonb := '{}'::jsonb;
  v_counterparty_auto_request_result jsonb := '{}'::jsonb;
  v_counterparty_auto_expand_result jsonb := '{}'::jsonb;
  v_counterparty_auto_process_result jsonb := '{}'::jsonb;
  v_counterparty_auto_request_id uuid := NULL::uuid;
  v_counterparty_auto_work_applied_count integer := 0;
  v_batch_status_before text := NULL::text;
  v_batch_status_after text := NULL::text;
  v_execution_commit_state_before text := NULL::text;
  v_provider_boundary_crossed boolean := false;
  v_submitted_state_finalisation_attempted boolean := false;
  v_submitted_state_finalised boolean := false;
  v_local_finalisation_error text := NULL::text;
  v_execution_commit_ref_candidate text := NULL::text;
  v_provider_transfer_total numeric := NULL::numeric;
  v_has_completed_provider_evidence boolean := false;
  v_live_signal_result jsonb := '{}'::jsonb;
  v_alert_signal_required boolean := false;
  v_provider_failure_reason_groups_json jsonb := '[]'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '3s', true);
  v_is_scoped := (p_operation_id IS NOT NULL OR p_chunk_id IS NOT NULL OR p_transfer_ids IS NOT NULL);

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: pay_batch_id is required';
  END IF;

  IF p_updates IS NULL OR jsonb_typeof(p_updates) <> 'array' THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: updates must be a JSON array';
  END IF;

  IF p_actor_user_id IS NOT NULL THEN
    PERFORM 1
    FROM public.tms_users AS actor_user
    WHERE actor_user.id = p_actor_user_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'tms_users row % not found', p_actor_user_id;
    END IF;
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: pay_batch % not found', p_pay_batch_id;
  END IF;

  v_batch_status_before := upper(BTRIM(COALESCE(v_batch_row.status, '')));
  v_batch_status_after := v_batch_status_before;
  v_execution_commit_state_before := upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND p_actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    SELECT COALESCE(operation_chunk.payload_json->'transfer_ids', '[]'::jsonb)
    INTO v_chunk_transfer_ids
    FROM public.banking_pay_operation_chunks AS operation_chunk
    WHERE operation_chunk.id = p_chunk_id
      AND operation_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
      AND operation_chunk.chunk_type = 'TRANSFER_SUBMIT'
      AND (p_operation_id IS NULL OR operation_chunk.operation_id = p_operation_id);

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: chunk % was not found for this operation/provider-submit phase', p_chunk_id;
    END IF;
  END IF;

  DROP TABLE IF EXISTS pg_temp.tmp_pay_bank_transfer_updates;

  CREATE TEMPORARY TABLE pg_temp.tmp_pay_bank_transfer_updates (
    row_seq integer NOT NULL,
    transfer_id uuid NULL,
    transfer_status text NOT NULL,
    rail_tx_id text NULL,
    rail_state text NULL,
    rail_meta_json jsonb NULL,
    failed_reason text NULL,
    completed_at_utc timestamptz NULL,
    provider_key text NULL,
    provider_event_id text NULL,
    provider_reference text NULL,
    provider_state text NULL,
    normalised_state text NULL,
    event_source text NULL,
    event_time_utc timestamptz NULL,
    amount numeric NULL,
    currency text NULL,
    raw_payload jsonb NULL,
    idempotency_key text NULL,
    input_json jsonb NOT NULL,
    provider_submit_diagnostic jsonb NOT NULL DEFAULT '{}'::jsonb,
    provider_submission_status text NULL,
    provider_submission_attempted boolean NOT NULL DEFAULT false,
    provider_request_sent boolean NOT NULL DEFAULT false,
    provider_request_sent_confirmed boolean NOT NULL DEFAULT false,
    provider_request_dispatched_at_utc text NULL,
    provider_response_received boolean NOT NULL DEFAULT false,
    provider_response_present boolean NOT NULL DEFAULT false,
    provider_submission_unknown boolean NOT NULL DEFAULT false,
    provider_external_evidence_present boolean NOT NULL DEFAULT false,
    provider_acceptance_evidence_present boolean NOT NULL DEFAULT false,
    manual_resolution_required boolean NOT NULL DEFAULT false,
    safe_retry_available boolean NOT NULL DEFAULT false,
    provider_http_status integer NULL,
    provider_error_code text NULL,
    provider_error_message_redacted text NULL,
    provider_response_redacted jsonb NULL,
    provider_error_redacted jsonb NULL,
    request_id text NULL,
    local_provider_request_id text NULL,
    provider_webhook_receipt_id uuid NULL,
    provider_webhook_id text NULL,
    provider_event_type text NULL,
    provider_transaction_id text NULL,
    provider_request_id text NULL,
    provider_event_key text NULL,
    provider_signature_valid boolean NULL,
    provider_event_transport text NULL,
    adapter_key text NULL,
    adapter_version text NULL,
    rail_env text NULL,
    provider_failure_reason_code text NULL,
    provider_failure_reason_group text NULL,
    mapping_hints_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    is_provider_source boolean NOT NULL DEFAULT false,
    is_provider_external_evidence boolean NOT NULL DEFAULT false,
    is_provider_evidence boolean NOT NULL DEFAULT false,
    is_attempted_but_unproven boolean NOT NULL DEFAULT false,
    money_cash_state text NULL,
    money_normalised_transfer_status text NULL,
    money_is_final_money_moved boolean NOT NULL DEFAULT false,
    money_is_terminal_no_money boolean NOT NULL DEFAULT false,
    money_is_pending_non_final boolean NOT NULL DEFAULT false,
    money_completed_at_allowed boolean NOT NULL DEFAULT false,
    money_reason text NULL,
    money_support_details_json jsonb NOT NULL DEFAULT '{}'::jsonb
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_bank_transfer_updates;

  INSERT INTO pg_temp.tmp_pay_bank_transfer_updates (
    row_seq,
    transfer_id,
    transfer_status,
    rail_tx_id,
    rail_state,
    rail_meta_json,
    failed_reason,
    completed_at_utc,
    provider_key,
    provider_event_id,
    provider_reference,
    provider_state,
    normalised_state,
    event_source,
    event_time_utc,
    amount,
    currency,
    raw_payload,
    idempotency_key,
    input_json,
    provider_submit_diagnostic,
    provider_submission_status,
    provider_submission_attempted,
    provider_request_sent,
    provider_request_sent_confirmed,
    provider_request_dispatched_at_utc,
    provider_response_received,
    provider_response_present,
    provider_submission_unknown,
    provider_external_evidence_present,
    provider_acceptance_evidence_present,
    manual_resolution_required,
    safe_retry_available,
    provider_http_status,
    provider_error_code,
    provider_error_message_redacted,
    provider_response_redacted,
    provider_error_redacted,
    request_id,
    local_provider_request_id,
    provider_webhook_receipt_id,
    provider_webhook_id,
    provider_event_type,
    provider_transaction_id,
    provider_request_id,
    provider_event_key,
    provider_signature_valid,
    provider_event_transport,
    adapter_key,
    adapter_version,
    rail_env,
    provider_failure_reason_code,
    provider_failure_reason_group,
    mapping_hints_json
  )
  SELECT
    update_element.ordinality::integer,
    CASE
      WHEN nullif(btrim(coalesce(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN nullif(btrim(coalesce(update_element.value->>'transfer_id', update_element.value->>'pay_bank_transfer_id', '')), '')::uuid
      ELSE NULL::uuid
    END,
    upper(btrim(coalesce(nullif(update_element.value->>'status', ''), nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), 'UNKNOWN'))),
    nullif(btrim(coalesce(update_element.value->>'rail_tx_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'rail_state', '')), ''),
    CASE WHEN update_element.value ? 'rail_meta_json' THEN update_element.value->'rail_meta_json' ELSE NULL::jsonb END,
    nullif(btrim(coalesce(update_element.value->>'failed_reason', '')), ''),
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'completed_at_utc', '')), '') IS NOT NULL THEN nullif(btrim(coalesce(update_element.value->>'completed_at_utc', '')), '')::timestamptz ELSE NULL::timestamptz END,
    nullif(btrim(coalesce(update_element.value->>'provider_key', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_event_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_reference', update_element.value->>'provider_submission_id', update_element.value->>'provider_transfer_id', update_element.value->>'provider_payment_id', update_element.value->>'rail_tx_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_state', update_element.value->>'rail_state', update_element.value->>'status', '')), ''),
    upper(btrim(coalesce(nullif(update_element.value->>'normalised_state', ''), nullif(update_element.value->>'normalized_state', ''), nullif(update_element.value->>'status', ''), 'UNKNOWN'))),
    upper(btrim(coalesce(nullif(update_element.value->>'event_source', ''), 'LOCAL_STATE'))),
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'event_time_utc', '')), '') IS NOT NULL THEN nullif(btrim(coalesce(update_element.value->>'event_time_utc', '')), '')::timestamptz ELSE v_now END,
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'amount', '')), '') ~ '^-?[0-9]+(\.[0-9]+)?$' THEN nullif(btrim(coalesce(update_element.value->>'amount', '')), '')::numeric ELSE NULL::numeric END,
    upper(btrim(coalesce(nullif(update_element.value->>'currency', ''), 'GBP'))),
    CASE WHEN update_element.value ? 'raw_payload' THEN update_element.value->'raw_payload' ELSE update_element.value END,
    nullif(btrim(coalesce(
      update_element.value->>'idempotency_key',
      update_element.value->'provider_submit_diagnostic'->>'idempotency_key',
      update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'idempotency_key',
      update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'idempotency_key',
      update_element.value->'raw_payload'->>'idempotency_key',
      update_element.value->>'request_id',
      update_element.value->'provider_submit_diagnostic'->>'request_id',
      update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'request_id',
      update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'request_id',
      update_element.value->'raw_payload'->>'request_id',
      ''
    )), ''),
    update_element.value,
    COALESCE(
      CASE WHEN jsonb_typeof(update_element.value->'provider_submit_diagnostic') = 'object' THEN update_element.value->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(update_element.value->'rail_meta_json'->'provider_submit_diagnostic') = 'object' THEN update_element.value->'rail_meta_json'->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(update_element.value->'raw_payload'->'provider_submit_diagnostic') = 'object' THEN update_element.value->'raw_payload'->'provider_submit_diagnostic' ELSE NULL::jsonb END,
      '{}'::jsonb
    ),
    upper(btrim(coalesce(
      nullif(update_element.value->>'provider_submission_status', ''),
      nullif(update_element.value->'provider_submit_diagnostic'->>'provider_submission_status', ''),
      nullif(update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_submission_status', ''),
      nullif(update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_submission_status', ''),
      ''
    ))),
    lower(btrim(coalesce(update_element.value->>'provider_submission_attempted', update_element.value->'provider_submit_diagnostic'->>'provider_submission_attempted', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_submission_attempted', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_submission_attempted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_request_sent', update_element.value->'provider_submit_diagnostic'->>'provider_request_sent', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_request_sent', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_request_sent', update_element.value->>'provider_request_sent_confirmed', update_element.value->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_request_sent_confirmed', update_element.value->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_request_sent_confirmed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    nullif(btrim(coalesce(update_element.value->>'provider_request_dispatched_at_utc', update_element.value->'provider_submit_diagnostic'->>'provider_request_dispatched_at_utc', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_request_dispatched_at_utc', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_request_dispatched_at_utc', update_element.value->>'request_sent_at_utc', update_element.value->'provider_submit_diagnostic'->>'request_sent_at_utc', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'request_sent_at_utc', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'request_sent_at_utc', '')), ''),
    lower(btrim(coalesce(update_element.value->>'provider_response_received', update_element.value->'provider_submit_diagnostic'->>'provider_response_received', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_response_received', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_response_received', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_response_present', update_element.value->'provider_submit_diagnostic'->>'provider_response_present', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_response_present', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_response_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_submission_unknown', update_element.value->'provider_submit_diagnostic'->>'provider_submission_unknown', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_submission_unknown', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_submission_unknown', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_external_evidence_present', update_element.value->'provider_submit_diagnostic'->>'provider_external_evidence_present', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_external_evidence_present', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_external_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'provider_acceptance_evidence_present', update_element.value->'provider_submit_diagnostic'->>'provider_acceptance_evidence_present', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_acceptance_evidence_present', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_acceptance_evidence_present', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'manual_resolution_required', update_element.value->'provider_submit_diagnostic'->>'manual_resolution_required', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'manual_resolution_required', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'manual_resolution_required', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    lower(btrim(coalesce(update_element.value->>'safe_retry_available', update_element.value->'provider_submit_diagnostic'->>'safe_retry_available', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'safe_retry_available', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'safe_retry_available', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on'),
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'provider_http_status', update_element.value->'provider_submit_diagnostic'->>'provider_http_status', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_http_status', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_http_status', '')), '') ~ '^[0-9]+$' THEN nullif(btrim(coalesce(update_element.value->>'provider_http_status', update_element.value->'provider_submit_diagnostic'->>'provider_http_status', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_http_status', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_http_status', '')), '')::integer ELSE NULL::integer END,
    nullif(btrim(coalesce(update_element.value->>'provider_error_code', update_element.value->'provider_submit_diagnostic'->>'provider_error_code', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_error_code', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_error_code', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_error_message_redacted', update_element.value->'provider_submit_diagnostic'->>'provider_error_message_redacted', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_error_message_redacted', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_error_message_redacted', '')), ''),
    COALESCE(update_element.value->'provider_response_redacted', update_element.value->'provider_submit_diagnostic'->'provider_response_redacted', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->'provider_response_redacted', update_element.value->'raw_payload'->'provider_submit_diagnostic'->'provider_response_redacted'),
    COALESCE(update_element.value->'provider_error_redacted', update_element.value->'provider_submit_diagnostic'->'provider_error_redacted', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->'provider_error_redacted', update_element.value->'raw_payload'->'provider_submit_diagnostic'->'provider_error_redacted'),
    nullif(btrim(coalesce(update_element.value->>'request_id', update_element.value->'provider_submit_diagnostic'->>'request_id', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'request_id', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'request_id', update_element.value->'raw_payload'->>'request_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'local_provider_request_id', update_element.value->'provider_submit_diagnostic'->>'local_provider_request_id', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'local_provider_request_id', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'local_provider_request_id', update_element.value->'raw_payload'->>'local_provider_request_id', '')), ''),
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'provider_webhook_receipt_id', update_element.value->>'webhook_receipt_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN nullif(btrim(coalesce(update_element.value->>'provider_webhook_receipt_id', update_element.value->>'webhook_receipt_id', '')), '')::uuid ELSE NULL::uuid END,
    nullif(btrim(coalesce(update_element.value->>'provider_webhook_id', update_element.value->>'webhook_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_event_type', update_element.value->>'event_type', update_element.value->>'event', update_element.value->'raw_payload'->>'event', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_transaction_id', update_element.value->>'transaction_id', update_element.value->>'provider_payment_id', update_element.value->>'payment_id', update_element.value->'raw_payload'->>'provider_transaction_id', update_element.value->'raw_payload'->>'transaction_id', update_element.value->'raw_payload' #>> '{data,id}', update_element.value->'provider_submit_diagnostic'->>'provider_transaction_id', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'provider_transaction_id', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'provider_transaction_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_request_id', update_element.value->>'request_id', update_element.value->'raw_payload'->>'provider_request_id', update_element.value->'raw_payload'->>'request_id', update_element.value->'raw_payload' #>> '{data,request_id}', update_element.value->'provider_submit_diagnostic'->>'request_id', update_element.value->'rail_meta_json'->'provider_submit_diagnostic'->>'request_id', update_element.value->'raw_payload'->'provider_submit_diagnostic'->>'request_id', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'provider_event_key', update_element.value->>'event_key', update_element.value->'raw_payload'->>'provider_event_key', update_element.value->'raw_payload'->>'event_key', '')), ''),
    CASE WHEN nullif(btrim(coalesce(update_element.value->>'provider_signature_valid', update_element.value->>'signature_valid', update_element.value->'raw_payload'->>'provider_signature_valid', update_element.value->'raw_payload'->>'signature_valid', '')), '') IS NULL THEN NULL::boolean ELSE lower(btrim(coalesce(update_element.value->>'provider_signature_valid', update_element.value->>'signature_valid', update_element.value->'raw_payload'->>'provider_signature_valid', update_element.value->'raw_payload'->>'signature_valid', 'false'))) IN ('true','t','1','yes','y','on') END,
    upper(btrim(coalesce(nullif(update_element.value->>'provider_event_transport', ''), nullif(update_element.value->>'event_source', ''), nullif(update_element.value->>'source', ''), 'LOCAL_STATE'))),
    nullif(btrim(coalesce(update_element.value->>'adapter_key', update_element.value->'raw_payload'->>'adapter_key', '')), ''),
    nullif(btrim(coalesce(update_element.value->>'adapter_version', update_element.value->'raw_payload'->>'adapter_version', '')), ''),
    upper(btrim(coalesce(nullif(update_element.value->>'rail_env', ''), nullif(update_element.value->'raw_payload'->>'rail_env', ''), nullif(update_element.value->'rail_meta_json'->>'rail_env', ''), 'PROD'))),
    nullif(btrim(coalesce(update_element.value->>'provider_failure_reason_code', update_element.value->>'failure_reason_code', update_element.value->>'reason_code', update_element.value->>'provider_error_code', update_element.value->'provider_submit_diagnostic'->>'provider_failure_reason_code', update_element.value->'provider_submit_diagnostic'->>'provider_error_code', update_element.value->'raw_payload'->>'provider_failure_reason_code', update_element.value->'raw_payload'->>'failure_reason_code', update_element.value->'raw_payload'->>'reason_code', update_element.value->'raw_payload'->>'error_code', '')), ''),
    upper(nullif(btrim(coalesce(update_element.value->>'provider_failure_reason_group', update_element.value->>'failure_reason_group', update_element.value->'raw_payload'->>'provider_failure_reason_group', update_element.value->'raw_payload'->>'failure_reason_group', '')), '')),
    COALESCE(
      CASE WHEN jsonb_typeof(update_element.value->'mapping_hints_json') = 'object' THEN update_element.value->'mapping_hints_json' ELSE NULL::jsonb END,
      CASE WHEN jsonb_typeof(update_element.value->'mapping_hints') = 'object' THEN update_element.value->'mapping_hints' ELSE NULL::jsonb END,
      '{}'::jsonb
    )
  FROM jsonb_array_elements(p_updates) WITH ORDINALITY AS update_element(value, ordinality)
  WHERE jsonb_typeof(update_element.value) = 'object';

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_source
  SET event_source = CASE
    WHEN update_source.event_source = 'PROVIDER_RESPONSE' THEN 'PROVIDER_POLL'
    WHEN update_source.event_source IN ('PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'LOCAL_STATE') THEN update_source.event_source
    WHEN update_source.event_source IN ('WEBHOOK') THEN 'PROVIDER_WEBHOOK'
    WHEN update_source.event_source IN ('POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT', 'RAIL_PROVIDER_SETTLEMENT') THEN 'PROVIDER_POLL'
    ELSE 'LOCAL_STATE'
  END
  WHERE update_source.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_transport
  SET provider_event_transport = CASE
    WHEN update_transport.provider_event_transport IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'MANUAL_CONFIRM', 'LOCAL_STATE') THEN update_transport.provider_event_transport
    WHEN update_transport.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY') THEN update_transport.event_source
    WHEN update_transport.event_source = 'WEBHOOK' THEN 'PROVIDER_WEBHOOK'
    WHEN update_transport.event_source IN ('POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT') THEN 'PROVIDER_POLL'
    ELSE 'LOCAL_STATE'
  END
  WHERE update_transport.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_source
  SET event_source = CASE
    WHEN update_source.provider_submission_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE')
     AND (
       update_source.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
       OR update_source.provider_response_present IS TRUE
       OR update_source.provider_response_received IS TRUE
       OR update_source.provider_http_status IS NOT NULL
       OR NULLIF(BTRIM(COALESCE(update_source.provider_error_code, '')), '') IS NOT NULL
     ) THEN 'PROVIDER_POLL'
    WHEN update_source.provider_submission_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE') THEN 'LOCAL_STATE'
    WHEN update_source.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL') THEN 'LOCAL_STATE'
    ELSE update_source.event_source
  END
  WHERE update_source.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_source
  SET is_provider_source = update_source.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
  WHERE update_source.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_normalise_provider
  SET provider_submission_status = CASE
        WHEN NULLIF(BTRIM(COALESCE(update_normalise_provider.provider_submission_status, '')), '') IS NOT NULL THEN update_normalise_provider.provider_submission_status
        WHEN update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
         AND update_normalise_provider.normalised_state IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED') THEN 'PROVIDER_SUBMISSION_REJECTED'
        WHEN update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
         AND update_normalise_provider.normalised_state IN ('COMPLETED', 'COMMITTED', 'SETTLED', 'PAID', 'EXECUTED', 'ACCEPTED', 'SUBMITTED', 'SENT', 'PROCESSING', 'PENDING') THEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
        WHEN update_normalise_provider.provider_request_sent IS TRUE
         AND update_normalise_provider.provider_response_present IS NOT TRUE
         AND update_normalise_provider.provider_response_received IS NOT TRUE THEN 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
        ELSE update_normalise_provider.provider_submission_status
      END,
      provider_submission_attempted = update_normalise_provider.provider_submission_attempted
        OR update_normalise_provider.provider_request_sent
        OR update_normalise_provider.provider_request_sent_confirmed
        OR update_normalise_provider.provider_response_received
        OR update_normalise_provider.provider_response_present
        OR update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY'),
      provider_request_sent = update_normalise_provider.provider_request_sent
        OR update_normalise_provider.provider_request_sent_confirmed
        OR update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
        OR update_normalise_provider.provider_submission_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'),
      provider_response_received = update_normalise_provider.provider_response_received
        OR update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
        OR update_normalise_provider.provider_submission_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'),
      provider_response_present = update_normalise_provider.provider_response_present
        OR update_normalise_provider.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
        OR update_normalise_provider.provider_submission_status IN ('PROVIDER_SUBMISSION_ACCEPTED', 'PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE')
        OR update_normalise_provider.provider_http_status IS NOT NULL
        OR NULLIF(BTRIM(COALESCE(update_normalise_provider.provider_error_code, '')), '') IS NOT NULL,
      provider_submission_unknown = update_normalise_provider.provider_submission_unknown
        OR update_normalise_provider.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'),
      manual_resolution_required = update_normalise_provider.manual_resolution_required
        OR update_normalise_provider.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'),
      safe_retry_available = update_normalise_provider.safe_retry_available
        AND update_normalise_provider.provider_submission_status NOT IN ('PROVIDER_SUBMISSION_ACCEPTED', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
  WHERE update_normalise_provider.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_local_identity
  SET provider_reference = CASE
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.provider_reference, '')), '') IS NULL THEN NULL::text
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.provider_reference, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
          transfer_for_local_identity.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.payment_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.idempotency_key, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.local_provider_request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{referenceId}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{local_reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{provider_request_reference}', '')), '')
        ]::text[], NULL::text)) THEN NULL::text
        ELSE update_local_identity.provider_reference
      END,
      provider_event_id = CASE
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.provider_event_id, '')), '') IS NULL THEN NULL::text
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.provider_event_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
          transfer_for_local_identity.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.payment_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.idempotency_key, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.local_provider_request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{referenceId}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{local_reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{provider_request_reference}', '')), '')
        ]::text[], NULL::text)) THEN NULL::text
        ELSE update_local_identity.provider_event_id
      END,
      rail_tx_id = CASE
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.rail_tx_id, '')), '') IS NULL THEN NULL::text
        WHEN NULLIF(BTRIM(COALESCE(update_local_identity.rail_tx_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
          transfer_for_local_identity.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(transfer_for_local_identity.payment_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.idempotency_key, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.local_provider_request_id, '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{referenceId}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{local_reference}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_local_identity.input_json #>> '{provider_request_reference}', '')), '')
        ]::text[], NULL::text)) THEN NULL::text
        ELSE update_local_identity.rail_tx_id
      END
  FROM public.pay_bank_transfers AS transfer_for_local_identity
  WHERE transfer_for_local_identity.id = update_local_identity.transfer_id
    AND transfer_for_local_identity.pay_batch_id = p_pay_batch_id;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_diag
  SET provider_submit_diagnostic = jsonb_strip_nulls(
    COALESCE(update_diag.provider_submit_diagnostic, '{}'::jsonb)
    || jsonb_build_object(
      'diagnostic_version', 1,
      'generated_at_utc', v_now::text,
      'provider_submission_status', NULLIF(update_diag.provider_submission_status, ''),
      'provider_submission_attempted', update_diag.provider_submission_attempted,
      'provider_request_sent', update_diag.provider_request_sent OR update_diag.provider_request_sent_confirmed,
      'provider_request_sent_confirmed', update_diag.provider_request_sent_confirmed,
      'provider_request_dispatched_at_utc', update_diag.provider_request_dispatched_at_utc,
      'provider_response_received', update_diag.provider_response_received,
      'provider_response_present', update_diag.provider_response_present,
      'provider_submission_unknown', update_diag.provider_submission_unknown,
      'provider_external_evidence_present', update_diag.provider_external_evidence_present,
      'provider_acceptance_evidence_present', update_diag.provider_acceptance_evidence_present,
      'manual_resolution_required', update_diag.manual_resolution_required,
      'safe_retry_available', update_diag.safe_retry_available,
      'provider_http_status', update_diag.provider_http_status,
      'provider_error_code', update_diag.provider_error_code,
      'provider_error_message_redacted', update_diag.provider_error_message_redacted,
      'provider_response_redacted', update_diag.provider_response_redacted,
      'provider_error_redacted', update_diag.provider_error_redacted,
      'request_id', update_diag.request_id,
      'idempotency_key', update_diag.idempotency_key,
      'local_provider_request_id', update_diag.local_provider_request_id,
      'rail_tx_id', CASE WHEN update_diag.is_provider_evidence IS TRUE THEN update_diag.rail_tx_id ELSE NULL::text END,
      'rail_state', update_diag.rail_state,
      'provider_reference', update_diag.provider_reference,
      'provider_state', update_diag.provider_state
    )
  )
  WHERE update_diag.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_reason
  SET provider_failure_reason_group = COALESCE(
        update_reason.provider_failure_reason_group,
        public._banking_provider_failure_reason_normalise(
          update_reason.provider_key,
          COALESCE(update_reason.provider_state, update_reason.normalised_state, update_reason.transfer_status),
          COALESCE(update_reason.provider_failure_reason_code, update_reason.provider_error_code),
          COALESCE(update_reason.provider_error_message_redacted, update_reason.failed_reason, update_reason.raw_payload->>'message', update_reason.raw_payload->>'reason'),
          COALESCE(update_reason.raw_payload, update_reason.input_json, '{}'::jsonb)
        )->>'failure_reason_group'
      ),
      provider_failure_reason_code = COALESCE(update_reason.provider_failure_reason_code, update_reason.provider_error_code)
  WHERE update_reason.row_seq IS NOT NULL;

  SELECT count(*)::integer
  INTO v_input_count
  FROM pg_temp.tmp_pay_bank_transfer_updates AS update_count_row;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_bank_transfer_updates AS invalid_update
    WHERE invalid_update.transfer_id IS NULL
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: updates contains an invalid or missing transfer_id';
  END IF;

  IF p_transfer_ids IS NOT NULL THEN
    IF jsonb_typeof(p_transfer_ids) <> 'array' THEN
      RAISE EXCEPTION 'p_transfer_ids must be a JSON array when supplied';
    END IF;

    DELETE FROM pg_temp.tmp_pay_bank_transfer_updates AS update_delete
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_transfer_ids) AS transfer_id_filter(value)
      WHERE (transfer_id_filter.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND (transfer_id_filter.value #>> '{}')::uuid = update_delete.transfer_id
    );
  END IF;

  IF v_chunk_transfer_ids IS NOT NULL THEN
    DELETE FROM pg_temp.tmp_pay_bank_transfer_updates AS update_delete
    WHERE NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(v_chunk_transfer_ids) AS chunk_transfer_id_filter(value)
      WHERE (chunk_transfer_id_filter.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        AND (chunk_transfer_id_filter.value #>> '{}')::uuid = update_delete.transfer_id
    );
  END IF;

  IF p_operation_id IS NOT NULL THEN
    DELETE FROM pg_temp.tmp_pay_bank_transfer_updates AS update_delete
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.banking_pay_operation_transfer_scope AS operation_scope_filter
      WHERE operation_scope_filter.operation_id = p_operation_id
        AND operation_scope_filter.pay_batch_id = p_pay_batch_id
        AND operation_scope_filter.pay_bank_transfer_id = update_delete.transfer_id
    )
      AND NOT EXISTS (
        SELECT 1
        FROM public.banking_pay_operation_chunks AS operation_chunk_filter
        CROSS JOIN LATERAL jsonb_array_elements(COALESCE(operation_chunk_filter.payload_json->'transfer_ids', '[]'::jsonb)) AS operation_chunk_transfer_filter(value)
        WHERE operation_chunk_filter.operation_id = p_operation_id
          AND operation_chunk_filter.phase = 'SUBMIT_PROVIDER_TRANSFERS'
          AND operation_chunk_filter.chunk_type = 'TRANSFER_SUBMIT'
          AND (operation_chunk_transfer_filter.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          AND (operation_chunk_transfer_filter.value #>> '{}')::uuid = update_delete.transfer_id
      );
  END IF;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_normalise
  SET
    transfer_status = CASE
      WHEN update_normalise.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'FAILED'
      WHEN update_normalise.transfer_status IN ('SUCCESS', 'SUCCEEDED', 'SETTLED', 'PAID') THEN 'COMPLETED'
      WHEN update_normalise.transfer_status IN ('CANCELED', 'CANCELLED') THEN 'CANCELLED'
      WHEN update_normalise.transfer_status IN ('REVERSED', 'REVERTED') THEN 'UNKNOWN'
      WHEN update_normalise.transfer_status IN ('SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION') THEN 'PENDING'
      WHEN update_normalise.transfer_status IN ('DECLINED', 'REJECTED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT') THEN 'FAILED'
      ELSE update_normalise.transfer_status
    END,
    normalised_state = CASE
      WHEN update_normalise.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 'FAILED'
      WHEN update_normalise.normalised_state IN ('SUCCESS', 'SUCCEEDED', 'SETTLED', 'PAID') THEN 'COMPLETED'
      WHEN update_normalise.normalised_state IN ('CANCELED', 'CANCELLED') THEN 'FAILED'
      WHEN update_normalise.normalised_state IN ('REVERSED', 'REVERTED') THEN 'UNKNOWN'
      WHEN update_normalise.normalised_state IN ('SUBMITTED', 'QUEUED', 'ACCEPTED', 'SENT', 'PROCESSING', 'IN_FLIGHT', 'PENDING_SETTLEMENT', 'PENDING_CONFIRMATION', 'PENDING_SUBMISSION') THEN update_normalise.normalised_state
      WHEN update_normalise.normalised_state IN ('DECLINED', 'REJECTED', 'SUBMISSION_FAILED', 'FAILED_BEFORE_COMMIT') THEN 'FAILED'
      ELSE update_normalise.normalised_state
    END,
    failed_reason = CASE
      WHEN update_normalise.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
       AND NULLIF(BTRIM(COALESCE(update_normalise.failed_reason, '')), '') IS NULL THEN
        COALESCE(
          NULLIF(BTRIM(COALESCE(update_normalise.provider_error_message_redacted, '')), ''),
          NULLIF(BTRIM(COALESCE(update_normalise.provider_error_code, '')), ''),
          'PROVIDER_SUBMISSION_REJECTED'
        )
      ELSE update_normalise.failed_reason
    END
  WHERE update_normalise.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_evidence
  SET is_provider_evidence = COALESCE((
    SELECT update_evidence.event_source IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
       AND COALESCE(update_evidence.provider_submission_status, '') NOT IN (
         'PROVIDER_SUBMISSION_REJECTED',
         'PROVIDER_SUBMISSION_FAILED',
         'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
         'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
         'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
         'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
         'NO_PROVIDER_SUBMISSION_ATTEMPTED',
         'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
       )
       AND upper(BTRIM(COALESCE(update_evidence.normalised_state, update_evidence.provider_state, ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
       AND EXISTS (
         SELECT 1
         FROM (VALUES
           (update_evidence.provider_event_id),
           (update_evidence.provider_reference),
           (update_evidence.rail_tx_id),
           (update_evidence.raw_payload #>> '{provider_event_id}'),
           (update_evidence.raw_payload #>> '{provider_reference}'),
           (update_evidence.raw_payload #>> '{provider_submission_id}'),
           (update_evidence.raw_payload #>> '{submission_id}'),
           (update_evidence.raw_payload #>> '{rail_submission_id}'),
           (update_evidence.raw_payload #>> '{provider_payment_id}'),
           (update_evidence.raw_payload #>> '{payment_id}'),
           (update_evidence.raw_payload #>> '{external_payment_id}'),
           (update_evidence.raw_payload #>> '{revolut_payment_id}'),
           (update_evidence.raw_payload #>> '{provider_transfer_id}'),
           (update_evidence.raw_payload #>> '{external_transfer_id}'),
           (update_evidence.raw_payload #>> '{provider_transaction_id}'),
           (update_evidence.raw_payload #>> '{transaction_id}'),
           (update_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
           (update_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
           (update_evidence.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
           (update_evidence.raw_payload #>> '{provider_submit_diagnostic,provider_reference}'),
           (update_evidence.rail_meta_json #>> '{provider_event_id}'),
           (update_evidence.rail_meta_json #>> '{provider_reference}'),
           (update_evidence.rail_meta_json #>> '{provider_submission_id}'),
           (update_evidence.rail_meta_json #>> '{submission_id}'),
           (update_evidence.rail_meta_json #>> '{rail_submission_id}'),
           (update_evidence.rail_meta_json #>> '{provider_payment_id}'),
           (update_evidence.rail_meta_json #>> '{payment_id}'),
           (update_evidence.rail_meta_json #>> '{external_payment_id}'),
           (update_evidence.rail_meta_json #>> '{revolut_payment_id}'),
           (update_evidence.rail_meta_json #>> '{provider_transfer_id}'),
           (update_evidence.rail_meta_json #>> '{external_transfer_id}'),
           (update_evidence.rail_meta_json #>> '{provider_transaction_id}'),
           (update_evidence.rail_meta_json #>> '{transaction_id}'),
           (update_evidence.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
           (update_evidence.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
           (update_evidence.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
           (update_evidence.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}'),
           (update_evidence.input_json #>> '{provider_event_id}'),
           (update_evidence.input_json #>> '{provider_reference}'),
           (update_evidence.input_json #>> '{provider_submission_id}'),
           (update_evidence.input_json #>> '{submission_id}'),
           (update_evidence.input_json #>> '{rail_submission_id}'),
           (update_evidence.input_json #>> '{provider_payment_id}'),
           (update_evidence.input_json #>> '{payment_id}'),
           (update_evidence.input_json #>> '{external_payment_id}'),
           (update_evidence.input_json #>> '{revolut_payment_id}'),
           (update_evidence.input_json #>> '{provider_transfer_id}'),
           (update_evidence.input_json #>> '{external_transfer_id}'),
           (update_evidence.input_json #>> '{provider_transaction_id}'),
           (update_evidence.input_json #>> '{transaction_id}'),
           (update_evidence.input_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
           (update_evidence.input_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
           (update_evidence.input_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
           (update_evidence.input_json #>> '{provider_submit_diagnostic,provider_reference}')
         ) AS provider_identifier(identifier_value)
         WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
           AND NOT (
             NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') = ANY(
               ARRAY_REMOVE(ARRAY[
                 transfer_for_evidence.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.request_id, '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.payment_reference, '')), ''),
                 NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{idempotency_key}', '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{payment_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(transfer_for_evidence.rail_meta_json #>> '{bulk_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.request_id, '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.idempotency_key, '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.local_provider_request_id, '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{idempotency_key}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{raw_payload,local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{raw_payload,provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{referenceId}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{local_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{provider_request_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{payment_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.input_json #>> '{bulk_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{idempotency_key}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{referenceId}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{local_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{provider_request_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{payment_reference}', '')), ''),
                 NULLIF(BTRIM(COALESCE(update_evidence.rail_meta_json #>> '{bulk_reference}', '')), '')
               ]::text[], NULL::text)
             )
           )
       )
    FROM public.pay_bank_transfers AS transfer_for_evidence
    WHERE transfer_for_evidence.id = update_evidence.transfer_id
      AND transfer_for_evidence.pay_batch_id = p_pay_batch_id
  ), false)
  WHERE update_evidence.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_external
  SET is_provider_external_evidence = COALESCE((
    SELECT EXISTS (
      SELECT 1
      FROM (VALUES
        (update_external.provider_event_id),
        (update_external.provider_reference),
        (update_external.rail_tx_id),
        (update_external.raw_payload #>> '{provider_event_id}'),
        (update_external.raw_payload #>> '{provider_reference}'),
        (update_external.raw_payload #>> '{provider_submission_id}'),
        (update_external.raw_payload #>> '{submission_id}'),
        (update_external.raw_payload #>> '{rail_submission_id}'),
        (update_external.raw_payload #>> '{provider_payment_id}'),
        (update_external.raw_payload #>> '{payment_id}'),
        (update_external.raw_payload #>> '{external_payment_id}'),
        (update_external.raw_payload #>> '{revolut_payment_id}'),
        (update_external.raw_payload #>> '{provider_transfer_id}'),
        (update_external.raw_payload #>> '{external_transfer_id}'),
        (update_external.raw_payload #>> '{provider_transaction_id}'),
        (update_external.raw_payload #>> '{transaction_id}'),
        (update_external.raw_payload #>> '{provider_submit_diagnostic,provider_transaction_id}'),
        (update_external.raw_payload #>> '{provider_submit_diagnostic,provider_payment_id}'),
        (update_external.raw_payload #>> '{provider_submit_diagnostic,rail_tx_id}'),
        (update_external.raw_payload #>> '{provider_submit_diagnostic,provider_reference}'),
        (update_external.rail_meta_json #>> '{provider_event_id}'),
        (update_external.rail_meta_json #>> '{provider_reference}'),
        (update_external.rail_meta_json #>> '{provider_submission_id}'),
        (update_external.rail_meta_json #>> '{submission_id}'),
        (update_external.rail_meta_json #>> '{rail_submission_id}'),
        (update_external.rail_meta_json #>> '{provider_payment_id}'),
        (update_external.rail_meta_json #>> '{payment_id}'),
        (update_external.rail_meta_json #>> '{external_payment_id}'),
        (update_external.rail_meta_json #>> '{revolut_payment_id}'),
        (update_external.rail_meta_json #>> '{provider_transfer_id}'),
        (update_external.rail_meta_json #>> '{external_transfer_id}'),
        (update_external.rail_meta_json #>> '{provider_transaction_id}'),
        (update_external.rail_meta_json #>> '{transaction_id}'),
        (update_external.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
        (update_external.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
        (update_external.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
        (update_external.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}'),
        (update_external.input_json #>> '{provider_event_id}'),
        (update_external.input_json #>> '{provider_reference}'),
        (update_external.input_json #>> '{provider_submission_id}'),
        (update_external.input_json #>> '{submission_id}'),
        (update_external.input_json #>> '{rail_submission_id}'),
        (update_external.input_json #>> '{provider_payment_id}'),
        (update_external.input_json #>> '{payment_id}'),
        (update_external.input_json #>> '{external_payment_id}'),
        (update_external.input_json #>> '{revolut_payment_id}'),
        (update_external.input_json #>> '{provider_transfer_id}'),
        (update_external.input_json #>> '{external_transfer_id}'),
        (update_external.input_json #>> '{provider_transaction_id}'),
        (update_external.input_json #>> '{transaction_id}'),
        (update_external.input_json #>> '{provider_submit_diagnostic,provider_transaction_id}'),
        (update_external.input_json #>> '{provider_submit_diagnostic,provider_payment_id}'),
        (update_external.input_json #>> '{provider_submit_diagnostic,rail_tx_id}'),
        (update_external.input_json #>> '{provider_submit_diagnostic,provider_reference}')
      ) AS provider_identifier(identifier_value)
      WHERE NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') IS NOT NULL
        AND NOT (
          NULLIF(BTRIM(COALESCE(provider_identifier.identifier_value, '')), '') = ANY(
            ARRAY_REMOVE(ARRAY[
              transfer_for_external_evidence.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
              NULLIF(BTRIM(COALESCE(transfer_for_external_evidence.request_id, '')), ''),
              NULLIF(BTRIM(COALESCE(transfer_for_external_evidence.payment_reference, '')), ''),
              NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.request_id, '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.idempotency_key, '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.local_provider_request_id, '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{request_id}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{idempotency_key}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{local_provider_request_id}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{referenceId}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{local_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{provider_request_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{payment_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.input_json #>> '{bulk_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{request_id}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{idempotency_key}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{referenceId}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{local_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{provider_request_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{payment_reference}', '')), ''),
              NULLIF(BTRIM(COALESCE(update_external.rail_meta_json #>> '{bulk_reference}', '')), '')
            ]::text[], NULL::text)
          )
        )
    )
    FROM public.pay_bank_transfers AS transfer_for_external_evidence
    WHERE transfer_for_external_evidence.id = update_external.transfer_id
      AND transfer_for_external_evidence.pay_batch_id = p_pay_batch_id
  ), false)
  WHERE update_external.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_diag
  SET provider_external_evidence_present = update_diag.is_provider_external_evidence,
      provider_acceptance_evidence_present = update_diag.is_provider_evidence,
      provider_submission_status = CASE
        WHEN update_diag.is_provider_evidence IS TRUE THEN 'PROVIDER_SUBMISSION_ACCEPTED'
        WHEN update_diag.provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
        WHEN NULLIF(BTRIM(COALESCE(update_diag.provider_submission_status, '')), '') IS NOT NULL THEN update_diag.provider_submission_status
        ELSE NULL::text
      END,
      provider_submit_diagnostic = jsonb_strip_nulls(
        COALESCE(update_diag.provider_submit_diagnostic, '{}'::jsonb)
        || jsonb_build_object(
          'provider_external_evidence_present', update_diag.is_provider_external_evidence,
          'provider_acceptance_evidence_present', update_diag.is_provider_evidence,
          'provider_submission_status', CASE
            WHEN update_diag.is_provider_evidence IS TRUE THEN 'PROVIDER_SUBMISSION_ACCEPTED'
            WHEN update_diag.provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' THEN 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
            WHEN NULLIF(BTRIM(COALESCE(update_diag.provider_submission_status, '')), '') IS NOT NULL THEN update_diag.provider_submission_status
            ELSE NULL::text
          END,
          'provider_request_sent', update_diag.provider_request_sent OR update_diag.provider_request_sent_confirmed OR update_diag.is_provider_source OR update_diag.is_provider_evidence,
          'provider_request_sent_confirmed', update_diag.provider_request_sent_confirmed,
          'provider_request_dispatched_at_utc', update_diag.provider_request_dispatched_at_utc,
          'provider_response_received', update_diag.provider_response_received OR update_diag.is_provider_source,
          'provider_response_present', update_diag.provider_response_present OR update_diag.is_provider_source,
          'rail_tx_id', CASE WHEN update_diag.is_provider_evidence IS TRUE THEN update_diag.rail_tx_id ELSE NULL::text END,
          'provider_reference', CASE WHEN update_diag.is_provider_external_evidence IS TRUE THEN update_diag.provider_reference ELSE NULL::text END,
          'provider_event_id', CASE WHEN update_diag.is_provider_external_evidence IS TRUE THEN update_diag.provider_event_id ELSE NULL::text END,
          'manual_resolution_required', update_diag.manual_resolution_required,
          'safe_retry_available', update_diag.safe_retry_available
        )
      )
  WHERE update_diag.row_seq IS NOT NULL;


  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_money
  SET (
    money_cash_state,
    money_normalised_transfer_status,
    money_is_final_money_moved,
    money_is_terminal_no_money,
    money_is_pending_non_final,
    money_completed_at_allowed,
    money_reason,
    money_support_details_json
  ) = (
    SELECT
      money_classification.cash_state,
      money_classification.normalised_transfer_status,
      COALESCE(money_classification.is_final_money_moved, false),
      COALESCE(money_classification.is_terminal_no_money, false),
      COALESCE(money_classification.is_pending_non_final, false),
      COALESCE(money_classification.completed_at_allowed, false),
      money_classification.reason,
      COALESCE(money_classification.support_details_json, '{}'::jsonb)
    FROM public._pay_rail_state_money_movement_classify(
      p_transfer_status := update_money.transfer_status,
      p_rail_state := COALESCE(update_money.rail_state, update_money.normalised_state, update_money.provider_state),
      p_event_payload_json := jsonb_strip_nulls(
        COALESCE(update_money.raw_payload, '{}'::jsonb)
        || COALESCE(update_money.input_json, '{}'::jsonb)
        || jsonb_build_object(
          'status', update_money.transfer_status,
          'normalised_state', update_money.normalised_state,
          'provider_state', update_money.provider_state,
          'event_source', update_money.event_source,
          'provider_error_code', update_money.provider_error_code,
          'provider_error_message_redacted', update_money.provider_error_message_redacted
        )
      ),
      p_provider_meta_json := jsonb_strip_nulls(
        COALESCE(update_money.provider_submit_diagnostic, '{}'::jsonb)
        || jsonb_build_object(
          'provider_submission_status', NULLIF(update_money.provider_submission_status, ''),
          'provider_external_evidence_present', update_money.is_provider_external_evidence,
          'provider_acceptance_evidence_present', update_money.is_provider_evidence,
          'provider_response_present', update_money.provider_response_present,
          'provider_response_received', update_money.provider_response_received,
          'provider_request_sent', update_money.provider_request_sent OR update_money.provider_request_sent_confirmed,
          'rail_tx_id', CASE WHEN update_money.is_provider_evidence IS TRUE THEN update_money.rail_tx_id ELSE NULL::text END,
          'provider_reference', CASE WHEN update_money.is_provider_external_evidence IS TRUE THEN update_money.provider_reference ELSE NULL::text END
        )
      )
    ) AS money_classification
    LIMIT 1
  )
  WHERE update_money.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_classified
  SET
    provider_submission_status = CASE
      WHEN update_classified.money_is_final_money_moved IS TRUE
       AND (
         update_classified.is_provider_source IS TRUE
         OR update_classified.provider_response_present IS TRUE
         OR update_classified.provider_response_received IS TRUE
         OR update_classified.is_provider_external_evidence IS TRUE
         OR update_classified.provider_acceptance_evidence_present IS TRUE
       ) THEN 'PROVIDER_SUBMISSION_ACCEPTED'
      WHEN update_classified.money_is_terminal_no_money IS TRUE
       AND (
         update_classified.is_provider_source IS TRUE
         OR update_classified.provider_response_present IS TRUE
         OR update_classified.provider_response_received IS TRUE
         OR update_classified.is_provider_external_evidence IS TRUE
         OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
       ) THEN 'PROVIDER_SUBMISSION_REJECTED'
      ELSE update_classified.provider_submission_status
    END,
    provider_acceptance_evidence_present = CASE
      WHEN update_classified.money_is_final_money_moved IS TRUE
       AND (
         update_classified.is_provider_source IS TRUE
         OR update_classified.provider_response_present IS TRUE
         OR update_classified.provider_response_received IS TRUE
         OR update_classified.is_provider_external_evidence IS TRUE
         OR update_classified.provider_acceptance_evidence_present IS TRUE
       ) THEN true
      ELSE update_classified.provider_acceptance_evidence_present
    END,
    provider_submission_unknown = CASE
      WHEN (
        update_classified.money_is_final_money_moved IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_acceptance_evidence_present IS TRUE
        )
      )
      OR (
        update_classified.money_is_terminal_no_money IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
        )
      ) THEN false
      ELSE update_classified.provider_submission_unknown
    END,
    manual_resolution_required = CASE
      WHEN (
        update_classified.money_is_final_money_moved IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_acceptance_evidence_present IS TRUE
        )
      )
      OR (
        update_classified.money_is_terminal_no_money IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
        )
      ) THEN false
      ELSE update_classified.manual_resolution_required
    END,
    safe_retry_available = CASE
      WHEN (
        update_classified.money_is_final_money_moved IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_acceptance_evidence_present IS TRUE
        )
      )
      OR (
        update_classified.money_is_terminal_no_money IS TRUE
        AND (
          update_classified.is_provider_source IS TRUE
          OR update_classified.provider_response_present IS TRUE
          OR update_classified.provider_response_received IS TRUE
          OR update_classified.is_provider_external_evidence IS TRUE
          OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
        )
      ) THEN false
      ELSE update_classified.safe_retry_available
    END,
    provider_submit_diagnostic = jsonb_strip_nulls(
      COALESCE(update_classified.provider_submit_diagnostic, '{}'::jsonb)
      || jsonb_build_object(
        'provider_submission_status', CASE
          WHEN update_classified.money_is_final_money_moved IS TRUE
           AND (
             update_classified.is_provider_source IS TRUE
             OR update_classified.provider_response_present IS TRUE
             OR update_classified.provider_response_received IS TRUE
             OR update_classified.is_provider_external_evidence IS TRUE
             OR update_classified.provider_acceptance_evidence_present IS TRUE
           ) THEN 'PROVIDER_SUBMISSION_ACCEPTED'
          WHEN update_classified.money_is_terminal_no_money IS TRUE
           AND (
             update_classified.is_provider_source IS TRUE
             OR update_classified.provider_response_present IS TRUE
             OR update_classified.provider_response_received IS TRUE
             OR update_classified.is_provider_external_evidence IS TRUE
             OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
           ) THEN 'PROVIDER_SUBMISSION_REJECTED'
          ELSE update_classified.provider_submission_status
        END,
        'provider_acceptance_evidence_present', CASE
          WHEN update_classified.money_is_final_money_moved IS TRUE
           AND (
             update_classified.is_provider_source IS TRUE
             OR update_classified.provider_response_present IS TRUE
             OR update_classified.provider_response_received IS TRUE
             OR update_classified.is_provider_external_evidence IS TRUE
             OR update_classified.provider_acceptance_evidence_present IS TRUE
           ) THEN true
          ELSE update_classified.provider_acceptance_evidence_present
        END,
        'provider_submission_unknown', CASE
          WHEN (
            update_classified.money_is_final_money_moved IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_acceptance_evidence_present IS TRUE
            )
          )
          OR (
            update_classified.money_is_terminal_no_money IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
            )
          ) THEN false
          ELSE update_classified.provider_submission_unknown
        END,
        'manual_resolution_required', CASE
          WHEN (
            update_classified.money_is_final_money_moved IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_acceptance_evidence_present IS TRUE
            )
          )
          OR (
            update_classified.money_is_terminal_no_money IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
            )
          ) THEN false
          ELSE update_classified.manual_resolution_required
        END,
        'safe_retry_available', CASE
          WHEN (
            update_classified.money_is_final_money_moved IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_acceptance_evidence_present IS TRUE
            )
          )
          OR (
            update_classified.money_is_terminal_no_money IS TRUE
            AND (
              update_classified.is_provider_source IS TRUE
              OR update_classified.provider_response_present IS TRUE
              OR update_classified.provider_response_received IS TRUE
              OR update_classified.is_provider_external_evidence IS TRUE
              OR update_classified.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
            )
          ) THEN false
          ELSE update_classified.safe_retry_available
        END,
        'money_movement_classification', jsonb_strip_nulls(jsonb_build_object(
          'cash_state', update_classified.money_cash_state,
          'normalised_transfer_status', update_classified.money_normalised_transfer_status,
          'is_final_money_moved', update_classified.money_is_final_money_moved,
          'is_terminal_no_money', update_classified.money_is_terminal_no_money,
          'is_pending_non_final', update_classified.money_is_pending_non_final,
          'completed_at_allowed', update_classified.money_completed_at_allowed,
          'reason', update_classified.money_reason,
          'support_details_json', update_classified.money_support_details_json
        ))
      )
    )
  WHERE update_classified.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_attempt
  SET is_attempted_but_unproven = (
      update_attempt.is_provider_source IS TRUE
      OR update_attempt.provider_request_sent IS TRUE
      OR update_attempt.provider_response_received IS TRUE
      OR update_attempt.provider_response_present IS TRUE
      OR update_attempt.provider_submission_unknown IS TRUE
    )
    AND update_attempt.is_provider_evidence IS NOT TRUE
    AND NOT (
      update_attempt.money_is_final_money_moved IS TRUE
      AND (
        update_attempt.is_provider_source IS TRUE
        OR update_attempt.provider_response_present IS TRUE
        OR update_attempt.provider_response_received IS TRUE
        OR update_attempt.is_provider_external_evidence IS TRUE
        OR update_attempt.provider_acceptance_evidence_present IS TRUE
      )
    )
    AND NOT (
      update_attempt.money_is_terminal_no_money IS TRUE
      AND (
        update_attempt.is_provider_source IS TRUE
        OR update_attempt.provider_response_present IS TRUE
        OR update_attempt.provider_response_received IS TRUE
        OR update_attempt.is_provider_external_evidence IS TRUE
        OR update_attempt.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
      )
    )
  WHERE update_attempt.row_seq IS NOT NULL;

  UPDATE pg_temp.tmp_pay_bank_transfer_updates AS update_key
  SET idempotency_key = COALESCE(
    update_key.idempotency_key,
    NULLIF(btrim(coalesce(update_key.provider_event_key, '')), ''),
    NULLIF(btrim(coalesce(update_key.provider_event_id, '')), ''),
    NULLIF(btrim(coalesce(update_key.provider_transaction_id, '')), ''),
    'rail-update:' || p_pay_batch_id::text || ':' || update_key.transfer_id::text || ':' || md5(jsonb_strip_nulls(jsonb_build_object(
      'provider_reference', NULLIF(btrim(coalesce(update_key.provider_reference, '')), ''),
      'provider_state', NULLIF(btrim(coalesce(update_key.provider_state, '')), ''),
      'normalised_state', NULLIF(btrim(coalesce(update_key.normalised_state, '')), ''),
      'event_source', update_key.event_source,
      'raw_payload', update_key.raw_payload
    ))::text)
  )
  WHERE update_key.row_seq IS NOT NULL;

  SELECT coalesce(jsonb_agg(missing_update.transfer_id::text ORDER BY missing_update.transfer_id), '[]'::jsonb)
  INTO v_missing
  FROM pg_temp.tmp_pay_bank_transfer_updates AS missing_update
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.pay_bank_transfers AS transfer_check
    WHERE transfer_check.id = missing_update.transfer_id
      AND transfer_check.pay_batch_id = p_pay_batch_id
  );

  IF jsonb_array_length(v_missing) > 0 THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: one or more transfer ids do not belong to the batch'
      USING DETAIL = jsonb_build_object('missing_transfer_ids', v_missing)::text;
  END IF;

  SELECT coalesce(jsonb_agg(duplicate_rows.transfer_id::text ORDER BY duplicate_rows.transfer_id), '[]'::jsonb)
  INTO v_duplicates
  FROM (
    SELECT duplicate_update.transfer_id
    FROM pg_temp.tmp_pay_bank_transfer_updates AS duplicate_update
    GROUP BY duplicate_update.transfer_id
    HAVING count(*) > 1
  ) AS duplicate_rows;

  IF jsonb_array_length(COALESCE(v_duplicates, '[]'::jsonb)) > 0 THEN
    RAISE EXCEPTION 'pay_bank_transfers_apply_rail_updates: duplicate transfer ids are not allowed in one update chunk'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES_DUPLICATE_TRANSFER_IDS',
              'pay_batch_id', p_pay_batch_id::text,
              'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
              'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
              'duplicate_transfer_ids', v_duplicates
            )::text;
  END IF;

  WITH inserted_events AS (
    INSERT INTO public.pay_bank_transfer_events (
      pay_batch_id,
      pay_bank_transfer_id,
      candidate_id,
      umbrella_id,
      provider_key,
      provider_event_id,
      provider_reference,
      provider_state,
      normalised_state,
      event_source,
      event_time_utc,
      received_at_utc,
      amount,
      currency,
      mapping_status,
      mapping_method,
      raw_payload,
      idempotency_key,
      provider_webhook_receipt_id,
      provider_event_type,
      provider_transaction_id,
      provider_request_id,
      provider_event_key,
      provider_signature_valid,
      provider_event_transport,
      adapter_key,
      adapter_version,
      rail_env,
      provider_failure_reason_code,
      provider_failure_reason_group,
      mapping_hints_json
    )
    SELECT
      p_pay_batch_id,
      update_row.transfer_id,
      transfer_row.candidate_id,
      transfer_row.umbrella_id,
      update_row.provider_key,
      CASE WHEN update_row.is_provider_source IS TRUE THEN update_row.provider_event_id ELSE NULL::text END,
      CASE WHEN update_row.is_provider_source IS TRUE THEN update_row.provider_reference ELSE NULL::text END,
      update_row.provider_state,
      update_row.normalised_state,
      update_row.event_source,
      COALESCE(update_row.event_time_utc, v_now),
      v_now,
      COALESCE(update_row.amount, transfer_row.amount),
      COALESCE(NULLIF(BTRIM(update_row.currency), ''), transfer_row.currency, 'GBP'),
      'MATCHED'::text,
      'TRANSFER_ID'::text,
      jsonb_strip_nulls((CASE
        WHEN jsonb_typeof(COALESCE(update_row.raw_payload, update_row.input_json)) = 'object'
          THEN COALESCE(update_row.raw_payload, update_row.input_json)
        ELSE jsonb_build_object('payload', COALESCE(update_row.raw_payload, update_row.input_json))
      END) || jsonb_build_object(
        'provider_evidence', update_row.is_provider_evidence,
        'provider_source', update_row.is_provider_source,
        'provider_attempt_without_external_id', update_row.is_attempted_but_unproven,
        'provider_submit_diagnostic', update_row.provider_submit_diagnostic,
        'event_kind', COALESCE(
          NULLIF(BTRIM(COALESCE(update_row.raw_payload #>> '{event_kind}', '')), ''),
          NULLIF(BTRIM(COALESCE(update_row.input_json #>> '{event_kind}', '')), ''),
          CASE
            WHEN update_row.event_source = 'LOCAL_STATE'
             AND update_row.provider_submission_status = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL' THEN 'PROVIDER_SUBMIT_BLOCKED_PRE_CALL'
            WHEN update_row.event_source = 'LOCAL_STATE'
             AND update_row.provider_submission_status = 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME'
             AND (
               lower(BTRIM(COALESCE(update_row.provider_error_code, ''))) LIKE '%timeout%'
               OR lower(BTRIM(COALESCE(update_row.provider_error_message_redacted, ''))) LIKE '%timeout%'
             ) THEN 'PROVIDER_SUBMIT_TIMEOUT'
            WHEN update_row.event_source = 'LOCAL_STATE'
             AND update_row.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK') THEN 'PROVIDER_SUBMIT_UNKNOWN'
            WHEN update_row.event_source = 'LOCAL_STATE' THEN 'LOCAL_STATE'
            ELSE NULL::text
          END
        ),
        'request_id', update_row.request_id,
        'idempotency_key', update_row.idempotency_key,
        'local_provider_request_id', update_row.local_provider_request_id
      )),
      update_row.idempotency_key,
      update_row.provider_webhook_receipt_id,
      update_row.provider_event_type,
      update_row.provider_transaction_id,
      update_row.provider_request_id,
      COALESCE(update_row.provider_event_key, update_row.idempotency_key),
      update_row.provider_signature_valid,
      COALESCE(update_row.provider_event_transport, update_row.event_source),
      update_row.adapter_key,
      update_row.adapter_version,
      update_row.rail_env,
      update_row.provider_failure_reason_code,
      update_row.provider_failure_reason_group,
      update_row.mapping_hints_json
    FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = update_row.transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfer_events AS existing_event
      WHERE existing_event.idempotency_key = update_row.idempotency_key
    )
    ON CONFLICT DO NOTHING
    RETURNING 1
  )
  SELECT count(*)::integer
  INTO v_event_result_count
  FROM inserted_events;

  UPDATE public.pay_bank_transfers AS transfer_update
  SET
    status = CASE
      WHEN update_row.money_is_final_money_moved IS TRUE
       AND (
        update_row.is_provider_evidence IS TRUE
        OR (
          update_row.is_provider_source IS TRUE
          OR update_row.provider_response_present IS TRUE
          OR update_row.provider_response_received IS TRUE
          OR update_row.is_provider_external_evidence IS TRUE
          OR update_row.provider_acceptance_evidence_present IS TRUE
        )
      )
        THEN 'COMPLETED'
      WHEN (
        (
        update_row.is_provider_evidence IS TRUE
        OR (
          update_row.money_is_final_money_moved IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_acceptance_evidence_present IS TRUE
          )
        )
      )
        OR existing_evidence.has_provider_evidence IS NOT TRUE
        OR (
          update_row.money_is_terminal_no_money IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
          )
          AND transfer_update.completed_at_utc IS NULL
          AND UPPER(BTRIM(COALESCE(transfer_update.status, ''))) NOT IN ('COMPLETED', 'SETTLED', 'PAID')
        )
      )
       AND update_row.money_is_terminal_no_money IS TRUE
        THEN CASE
          WHEN update_row.transfer_status IN ('CANCELLED','CANCELED') OR UPPER(BTRIM(COALESCE(update_row.money_normalised_transfer_status, ''))) IN ('CANCELLED','CANCELED') THEN 'CANCELLED'
          WHEN update_row.transfer_status IN ('RETURNED','REVERTED') OR UPPER(BTRIM(COALESCE(update_row.money_normalised_transfer_status, ''))) IN ('RETURNED','REVERTED') THEN 'RETURNED'
          ELSE 'FAILED'
        END
      WHEN (update_row.is_provider_evidence IS TRUE OR existing_evidence.has_provider_evidence IS NOT TRUE)
       AND update_row.money_is_pending_non_final IS TRUE
        THEN 'PENDING'
      WHEN existing_evidence.has_provider_evidence IS NOT TRUE
       AND update_row.transfer_status IN ('FAILED', 'CANCELLED', 'RETURNED', 'PENDING') THEN update_row.transfer_status
      ELSE transfer_update.status
    END,
    rail_tx_id = CASE
      WHEN update_row.is_provider_evidence IS TRUE AND NULLIF(BTRIM(COALESCE(update_row.rail_tx_id, '')), '') IS NOT NULL THEN update_row.rail_tx_id
      ELSE transfer_update.rail_tx_id
    END,
    rail_state = CASE
      WHEN (
        update_row.is_provider_evidence IS TRUE
        OR (
          update_row.money_is_final_money_moved IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_acceptance_evidence_present IS TRUE
          )
        )
      ) THEN
        CASE
          WHEN NULLIF(BTRIM(COALESCE(update_row.rail_state, '')), '') IS NOT NULL THEN upper(BTRIM(update_row.rail_state))
          WHEN update_row.normalised_state IS NOT NULL THEN update_row.normalised_state
          ELSE transfer_update.rail_state
        END
      WHEN (
        existing_evidence.has_provider_evidence IS NOT TRUE
        OR (
          update_row.money_is_terminal_no_money IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
          )
          AND transfer_update.completed_at_utc IS NULL
          AND UPPER(BTRIM(COALESCE(transfer_update.status, ''))) NOT IN ('COMPLETED', 'SETTLED', 'PAID')
        )
      )
       AND update_row.money_is_final_money_moved IS NOT TRUE THEN
        CASE
          WHEN NULLIF(BTRIM(COALESCE(update_row.rail_state, '')), '') IS NOT NULL THEN upper(BTRIM(update_row.rail_state))
          WHEN update_row.normalised_state IS NOT NULL THEN update_row.normalised_state
          ELSE transfer_update.rail_state
        END
      ELSE transfer_update.rail_state
    END,
    rail_meta_json = jsonb_strip_nulls(
      COALESCE(transfer_update.rail_meta_json, '{}'::jsonb)
      || CASE
           WHEN (
        (
        update_row.is_provider_evidence IS TRUE
        OR (
          update_row.money_is_final_money_moved IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_acceptance_evidence_present IS TRUE
          )
        )
      )
        OR existing_evidence.has_provider_evidence IS NOT TRUE
        OR (
          update_row.money_is_terminal_no_money IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
          )
          AND transfer_update.completed_at_utc IS NULL
          AND UPPER(BTRIM(COALESCE(transfer_update.status, ''))) NOT IN ('COMPLETED', 'SETTLED', 'PAID')
        )
      ) THEN COALESCE(update_row.rail_meta_json, '{}'::jsonb)
           ELSE '{}'::jsonb
         END
      || jsonb_build_object(
        'last_update_event_source', update_row.event_source,
        'last_update_at_utc', v_now,
        'last_update_provider_source', update_row.is_provider_source,
        'last_update_provider_evidence', CASE
          WHEN update_row.is_provider_evidence IS TRUE THEN true
          WHEN update_row.money_is_final_money_moved IS TRUE
           AND (
             update_row.is_provider_source IS TRUE
             OR update_row.provider_response_present IS TRUE
             OR update_row.provider_response_received IS TRUE
             OR update_row.is_provider_external_evidence IS TRUE
             OR update_row.provider_acceptance_evidence_present IS TRUE
           ) THEN true
          WHEN existing_evidence.has_provider_evidence IS TRUE THEN true
          ELSE false
        END,
        'provider_attempt_without_external_id', update_row.is_attempted_but_unproven,
        'money_movement_classification', jsonb_strip_nulls(jsonb_build_object(
          'cash_state', update_row.money_cash_state,
          'normalised_transfer_status', update_row.money_normalised_transfer_status,
          'is_final_money_moved', update_row.money_is_final_money_moved,
          'is_terminal_no_money', update_row.money_is_terminal_no_money,
          'is_pending_non_final', update_row.money_is_pending_non_final,
          'completed_at_allowed', update_row.money_completed_at_allowed,
          'reason', update_row.money_reason,
          'support_details_json', update_row.money_support_details_json
        )),
        'provider_submit_diagnostic', CASE
          WHEN COALESCE(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', '') = 'PROVIDER_SUBMISSION_ACCEPTED'
           AND existing_evidence.has_provider_evidence IS TRUE
           AND COALESCE(update_row.provider_submission_status, '') <> 'PROVIDER_SUBMISSION_ACCEPTED'
           AND NOT (
             (
               update_row.money_is_terminal_no_money IS TRUE
               OR update_row.money_is_final_money_moved IS TRUE
             )
             AND (
               update_row.is_provider_source IS TRUE
               OR update_row.provider_response_present IS TRUE
               OR update_row.provider_response_received IS TRUE
               OR update_row.is_provider_external_evidence IS TRUE
               OR update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
             )
             AND transfer_update.completed_at_utc IS NULL
             AND UPPER(BTRIM(COALESCE(transfer_update.status, ''))) NOT IN ('COMPLETED', 'SETTLED', 'PAID')
           ) THEN transfer_update.rail_meta_json->'provider_submit_diagnostic'
          WHEN COALESCE(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', '') = 'PROVIDER_SUBMISSION_REJECTED'
           AND update_row.is_provider_source IS NOT TRUE
           AND COALESCE(update_row.provider_submission_status, '') IN (
             '',
             'NO_PROVIDER_SUBMISSION_ATTEMPTED',
             'CLAIMED_NOT_PROVIDER_CALLED_YET',
             'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL',
             'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
             'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK'
           ) THEN transfer_update.rail_meta_json->'provider_submit_diagnostic'
          WHEN COALESCE(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', '') IN (
             'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
             'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
             'PROVIDER_SUBMISSION_MALFORMED_RESPONSE'
           )
           AND update_row.is_provider_source IS NOT TRUE
           AND COALESCE(update_row.provider_submission_status, '') IN (
             '',
             'NO_PROVIDER_SUBMISSION_ATTEMPTED',
             'CLAIMED_NOT_PROVIDER_CALLED_YET',
             'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
           ) THEN transfer_update.rail_meta_json->'provider_submit_diagnostic'
          WHEN COALESCE(transfer_update.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', '') = 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
           AND update_row.is_provider_source IS NOT TRUE
           AND COALESCE(update_row.provider_submission_status, '') IN (
             '',
             'NO_PROVIDER_SUBMISSION_ATTEMPTED',
             'CLAIMED_NOT_PROVIDER_CALLED_YET'
           ) THEN transfer_update.rail_meta_json->'provider_submit_diagnostic'
          WHEN jsonb_typeof(update_row.provider_submit_diagnostic) = 'object' THEN update_row.provider_submit_diagnostic
          ELSE transfer_update.rail_meta_json->'provider_submit_diagnostic'
        END
      )
      || CASE
           WHEN update_row.is_provider_source IS TRUE THEN jsonb_strip_nulls(jsonb_build_object(
             'provider_event_id', update_row.provider_event_id,
             'provider_reference', update_row.provider_reference,
             'provider_state', update_row.provider_state,
             'normalised_state', update_row.normalised_state,
             'provider_attempt_without_external_id', update_row.is_attempted_but_unproven
           ))
           ELSE '{}'::jsonb
         END
      || CASE
           WHEN update_row.is_provider_evidence IS NOT TRUE AND existing_evidence.has_provider_evidence IS TRUE THEN jsonb_build_object(
             'last_local_state_update_json', jsonb_strip_nulls(jsonb_build_object(
               'status', update_row.transfer_status,
               'rail_state', update_row.rail_state,
               'normalised_state', update_row.normalised_state,
               'event_source', update_row.event_source,
               'event_time_utc', update_row.event_time_utc,
               'received_at_utc', v_now
             ))
           )
           ELSE '{}'::jsonb
         END
    ),
    failed_reason = CASE
      WHEN (
        update_row.is_provider_evidence IS TRUE
        OR existing_evidence.has_provider_evidence IS NOT TRUE
        OR (
          update_row.money_is_terminal_no_money IS TRUE
          AND (
            update_row.is_provider_source IS TRUE
            OR update_row.provider_response_present IS TRUE
            OR update_row.provider_response_received IS TRUE
            OR update_row.is_provider_external_evidence IS TRUE
            OR update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
          )
          AND transfer_update.completed_at_utc IS NULL
          AND UPPER(BTRIM(COALESCE(transfer_update.status, ''))) NOT IN ('COMPLETED', 'SETTLED', 'PAID')
        )
      ) THEN COALESCE(update_row.failed_reason, transfer_update.failed_reason)
      ELSE transfer_update.failed_reason
    END,
    completed_at_utc = CASE
      WHEN update_row.money_is_final_money_moved IS TRUE
       AND update_row.money_completed_at_allowed IS TRUE
       AND (
         update_row.is_provider_evidence IS TRUE
         OR update_row.is_provider_source IS TRUE
         OR update_row.provider_response_present IS TRUE
         OR update_row.provider_response_received IS TRUE
         OR update_row.is_provider_external_evidence IS TRUE
         OR update_row.provider_acceptance_evidence_present IS TRUE
       )
        THEN COALESCE(update_row.completed_at_utc, transfer_update.completed_at_utc, v_now)
      ELSE transfer_update.completed_at_utc
    END
  FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row
  LEFT JOIN LATERAL (
    SELECT EXISTS (
      SELECT 1
      FROM public.pay_bank_transfers AS existing_transfer
      WHERE existing_transfer.id = update_row.transfer_id
        AND existing_transfer.pay_batch_id = p_pay_batch_id
        AND (
          (
            lower(btrim(coalesce(existing_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
            AND EXISTS (
              SELECT 1
              FROM (VALUES
                (existing_transfer.rail_tx_id),
                (existing_transfer.rail_meta_json #>> '{provider_event_id}'),
                (existing_transfer.rail_meta_json #>> '{provider_reference}'),
                (existing_transfer.rail_meta_json #>> '{provider_submission_id}'),
                (existing_transfer.rail_meta_json #>> '{submission_id}'),
                (existing_transfer.rail_meta_json #>> '{rail_submission_id}'),
                (existing_transfer.rail_meta_json #>> '{provider_payment_id}'),
                (existing_transfer.rail_meta_json #>> '{payment_id}'),
                (existing_transfer.rail_meta_json #>> '{external_payment_id}'),
                (existing_transfer.rail_meta_json #>> '{revolut_payment_id}'),
                (existing_transfer.rail_meta_json #>> '{provider_transfer_id}'),
                (existing_transfer.rail_meta_json #>> '{transfer_id}'),
                (existing_transfer.rail_meta_json #>> '{external_transfer_id}'),
                (existing_transfer.rail_meta_json #>> '{provider_transaction_id}'),
                (existing_transfer.rail_meta_json #>> '{transaction_id}')
              ) AS existing_identifier(identifier_value)
              WHERE NULLIF(BTRIM(COALESCE(existing_identifier.identifier_value, '')), '') IS NOT NULL
                AND NOT (
                  NULLIF(BTRIM(COALESCE(existing_identifier.identifier_value, '')), '') = ANY(
                    ARRAY_REMOVE(ARRAY[
                      existing_transfer.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                      NULLIF(BTRIM(COALESCE(existing_transfer.request_id, '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.payment_reference, '')), ''),
                      NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
                      NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{bulk_reference}', '')), '')
                    ]::text[], NULL::text)
                  )
                )
            )
          )
          OR EXISTS (
            SELECT 1
            FROM public.pay_bank_transfer_events AS existing_event
            WHERE existing_event.pay_bank_transfer_id = existing_transfer.id
              AND upper(BTRIM(COALESCE(existing_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'WEBHOOK', 'POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT')
              AND upper(BTRIM(COALESCE(existing_event.normalised_state, existing_event.provider_state, existing_event.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
              AND upper(BTRIM(COALESCE(existing_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
              AND EXISTS (
                SELECT 1
                FROM (VALUES
                  (existing_event.provider_event_id),
                  (existing_event.provider_reference),
                  (existing_event.raw_payload #>> '{provider_event_id}'),
                  (existing_event.raw_payload #>> '{provider_reference}'),
                  (existing_event.raw_payload #>> '{provider_submission_id}'),
                  (existing_event.raw_payload #>> '{submission_id}'),
                  (existing_event.raw_payload #>> '{rail_submission_id}'),
                  (existing_event.raw_payload #>> '{provider_payment_id}'),
                  (existing_event.raw_payload #>> '{payment_id}'),
                  (existing_event.raw_payload #>> '{external_payment_id}'),
                  (existing_event.raw_payload #>> '{revolut_payment_id}'),
                  (existing_event.raw_payload #>> '{provider_transfer_id}'),
                  (existing_event.raw_payload #>> '{transfer_id}'),
                  (existing_event.raw_payload #>> '{external_transfer_id}'),
                  (existing_event.raw_payload #>> '{provider_transaction_id}'),
                  (existing_event.raw_payload #>> '{transaction_id}')
                ) AS existing_event_identifier(identifier_value)
                WHERE NULLIF(BTRIM(COALESCE(existing_event_identifier.identifier_value, '')), '') IS NOT NULL
                  AND NOT (
                    NULLIF(BTRIM(COALESCE(existing_event_identifier.identifier_value, '')), '') = ANY(
                      ARRAY_REMOVE(ARRAY[
                        existing_transfer.id::text,
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                        NULLIF(BTRIM(COALESCE(existing_transfer.request_id, '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_transfer.payment_reference, '')), ''),
                        NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{payment_reference}', '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_transfer.rail_meta_json #>> '{bulk_reference}', '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_event.raw_payload #>> '{local_provider_request_id}', '')), ''),
                        NULLIF(BTRIM(COALESCE(existing_event.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), '')
                      ]::text[], NULL::text)
                    )
                  )
              )
          )
        )
    ) AS has_provider_evidence
  ) AS existing_evidence ON TRUE
  WHERE transfer_update.id = update_row.transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_pay_bank_transfer_updates AS consumed_update
    WHERE (
        consumed_update.is_provider_evidence IS TRUE
        OR (
          consumed_update.money_is_final_money_moved IS TRUE
          AND (
            consumed_update.is_provider_source IS TRUE
            OR consumed_update.provider_response_present IS TRUE
            OR consumed_update.provider_response_received IS TRUE
            OR consumed_update.is_provider_external_evidence IS TRUE
            OR consumed_update.provider_acceptance_evidence_present IS TRUE
          )
        )
      )
      AND consumed_update.money_is_final_money_moved IS TRUE
  ) THEN
    PERFORM public._pay_manual_adjustment_carry_forward_mark_consumed(
      p_target_pay_batch_id := p_pay_batch_id,
      p_target_pay_batch_item_ids := ARRAY(
        SELECT DISTINCT target_item.id
        FROM public.pay_batch_items AS target_item
        WHERE target_item.pay_bank_transfer_id IN (
          SELECT consumed_update.transfer_id
          FROM pg_temp.tmp_pay_bank_transfer_updates AS consumed_update
          WHERE (
            consumed_update.is_provider_evidence IS TRUE
            OR (
              consumed_update.money_is_final_money_moved IS TRUE
              AND (
                consumed_update.is_provider_source IS TRUE
                OR consumed_update.provider_response_present IS TRUE
                OR consumed_update.provider_response_received IS TRUE
                OR consumed_update.is_provider_external_evidence IS TRUE
                OR consumed_update.provider_acceptance_evidence_present IS TRUE
              )
            )
          )
            AND consumed_update.money_is_final_money_moved IS TRUE
        )
      ),
      p_resolved_scope_json := jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_bank_transfer_ids', COALESCE((
          SELECT jsonb_agg(DISTINCT consumed_update.transfer_id::text ORDER BY consumed_update.transfer_id::text)
          FROM pg_temp.tmp_pay_bank_transfer_updates AS consumed_update
          WHERE (
            consumed_update.is_provider_evidence IS TRUE
            OR (
              consumed_update.money_is_final_money_moved IS TRUE
              AND (
                consumed_update.is_provider_source IS TRUE
                OR consumed_update.provider_response_present IS TRUE
                OR consumed_update.provider_response_received IS TRUE
                OR consumed_update.is_provider_external_evidence IS TRUE
                OR consumed_update.provider_acceptance_evidence_present IS TRUE
              )
            )
          )
            AND consumed_update.money_is_final_money_moved IS TRUE
        ), '[]'::jsonb)
      ),
      p_final_paid_evidence_json := jsonb_build_object(
        'source', 'pay_bank_transfers_apply_rail_updates',
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
        'classified_at_utc', v_now::text
      ),
      p_actor_user_id := p_actor_user_id
    );
  END IF;


  DROP TABLE IF EXISTS pg_temp.tmp_provider_counterparty_not_found_recovery;
  CREATE TEMPORARY TABLE pg_temp.tmp_provider_counterparty_not_found_recovery (
    pay_bank_transfer_id uuid PRIMARY KEY,
    pay_batch_id uuid NOT NULL,
    candidate_id uuid NULL,
    umbrella_id uuid NULL,
    payee_entity_kind text NOT NULL,
    payee_entity_id uuid NOT NULL,
    bank_details_hash_snapshot text NOT NULL,
    rail_provider text NOT NULL,
    rail_env text NOT NULL,
    provider_payee_id text NULL,
    provider_payee_account_id text NULL,
    provider_error_code text NULL,
    provider_error_message_redacted text NULL,
    provider_http_status integer NULL,
    provider_submit_diagnostic jsonb NOT NULL DEFAULT '{}'::jsonb,
    source_bank_event_id uuid NULL,
    invalidated_map_ids jsonb NOT NULL DEFAULT '[]'::jsonb,
    invalidated_map_count integer NOT NULL DEFAULT 0,
    readiness_enqueue_result jsonb NULL,
    auto_reverse_setting boolean NOT NULL DEFAULT false,
    auto_reverse_requested boolean NOT NULL DEFAULT false,
    auto_reverse_request_id uuid NULL,
    auto_reverse_result_json jsonb NULL,
    auto_reverse_applied_count integer NOT NULL DEFAULT 0,
    recovery_status text NOT NULL DEFAULT 'MANUAL_RELEASE_REQUIRED',
    recovery_action text NOT NULL DEFAULT 'MANUAL_RELEASE_REQUIRED'
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_provider_counterparty_not_found_recovery (
    pay_bank_transfer_id,
    pay_batch_id,
    candidate_id,
    umbrella_id,
    payee_entity_kind,
    payee_entity_id,
    bank_details_hash_snapshot,
    rail_provider,
    rail_env,
    provider_payee_id,
    provider_payee_account_id,
    provider_error_code,
    provider_error_message_redacted,
    provider_http_status,
    provider_submit_diagnostic
  )
  SELECT DISTINCT ON (transfer_row.id)
    transfer_row.id,
    transfer_row.pay_batch_id,
    COALESCE(transfer_row.candidate_id, readiness_candidate.candidate_id),
    transfer_row.umbrella_id,
    UPPER(BTRIM(COALESCE(transfer_row.payee_entity_kind, ''))) AS payee_entity_kind,
    transfer_row.payee_entity_id,
    NULLIF(BTRIM(COALESCE(transfer_row.bank_details_hash_snapshot, '')), '') AS bank_details_hash_snapshot,
    UPPER(BTRIM(COALESCE(transfer_row.rail_provider, ''))) AS rail_provider,
    UPPER(BTRIM(COALESCE(transfer_row.rail_env, ''))) AS rail_env,
    NULLIF(BTRIM(COALESCE(
      update_row.provider_submit_diagnostic->>'payee_id',
      update_row.provider_submit_diagnostic->>'counterparty_id',
      update_row.provider_submit_diagnostic->>'provider_payee_id',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,payee_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,counterparty_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payee_id}',
      ''
    )), '') AS provider_payee_id,
    NULLIF(BTRIM(COALESCE(
      update_row.provider_submit_diagnostic->>'payee_account_id',
      update_row.provider_submit_diagnostic->>'counterparty_account_id',
      update_row.provider_submit_diagnostic->>'provider_payee_account_id',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,payee_account_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,counterparty_account_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payee_account_id}',
      ''
    )), '') AS provider_payee_account_id,
    NULLIF(BTRIM(COALESCE(update_row.provider_error_code, update_row.provider_submit_diagnostic->>'provider_error_code', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') AS provider_error_code,
    NULLIF(BTRIM(COALESCE(update_row.provider_error_message_redacted, update_row.provider_submit_diagnostic->>'provider_error_message_redacted', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_message_redacted}', update_row.failed_reason, transfer_row.failed_reason, '')), '') AS provider_error_message_redacted,
    update_row.provider_http_status,
    jsonb_strip_nulls(
      COALESCE(update_row.provider_submit_diagnostic, '{}'::jsonb)
      || jsonb_build_object(
        'provider_submission_status', 'PROVIDER_SUBMISSION_REJECTED',
        'review_reason_code', 'PROVIDER_REJECTED_PAYMENT',
        'stale_payee_map_detected', true,
        'stale_payee_map_reason', 'COUNTERPARTY_NOT_FOUND',
        'pay_bank_transfer_id', transfer_row.id::text,
        'pay_batch_id', transfer_row.pay_batch_id::text,
        'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
        'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END
      )
    ) AS provider_submit_diagnostic
  FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row
  JOIN public.pay_bank_transfers AS transfer_row
    ON transfer_row.id = update_row.transfer_id
   AND transfer_row.pay_batch_id = p_pay_batch_id
  LEFT JOIN LATERAL (
    SELECT batch_candidate.candidate_id AS candidate_id
    FROM public.pay_batch_items AS transfer_item
    JOIN public.pay_batch_candidates AS batch_candidate
      ON batch_candidate.id = transfer_item.pay_batch_candidate_id
     AND batch_candidate.pay_batch_id = transfer_row.pay_batch_id
    WHERE transfer_item.pay_bank_transfer_id = transfer_row.id
      AND batch_candidate.candidate_id IS NOT NULL
    ORDER BY batch_candidate.candidate_id
    LIMIT 1
  ) AS readiness_candidate
    ON true
  WHERE update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
    AND (
      NULLIF(BTRIM(COALESCE(update_row.provider_error_code, update_row.provider_submit_diagnostic->>'provider_error_code', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_code}', '')), '') = '2101'
      OR lower(BTRIM(COALESCE(update_row.provider_error_message_redacted, update_row.provider_submit_diagnostic->>'provider_error_message_redacted', transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_error_message_redacted}', update_row.failed_reason, transfer_row.failed_reason, ''))) LIKE '%counterparty not found%'
    )
    AND (update_row.provider_request_sent OR update_row.provider_request_sent_confirmed OR lower(BTRIM(COALESCE(update_row.provider_submit_diagnostic->>'provider_request_sent', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'))
    AND (update_row.provider_response_present OR update_row.provider_response_received OR update_row.is_provider_source OR lower(BTRIM(COALESCE(update_row.provider_submit_diagnostic->>'provider_response_present', update_row.provider_submit_diagnostic->>'provider_response_received', ''))) IN ('true', 't', '1', 'yes', 'y', 'on'))
    AND COALESCE(update_row.provider_acceptance_evidence_present, false) IS NOT TRUE
    AND COALESCE(update_row.is_provider_evidence, false) IS NOT TRUE
    AND NULLIF(BTRIM(COALESCE(update_row.rail_tx_id, transfer_row.rail_tx_id, '')), '') IS NULL
    AND NULLIF(BTRIM(COALESCE(
      update_row.provider_submit_diagnostic->>'provider_transaction_id',
      update_row.provider_submit_diagnostic->>'provider_payment_id',
      update_row.provider_submit_diagnostic->>'rail_tx_id',
      update_row.provider_submit_diagnostic->>'provider_reference',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_transaction_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_payment_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,rail_tx_id}',
      transfer_row.rail_meta_json #>> '{provider_submit_diagnostic,provider_reference}',
      ''
    )), '') IS NULL
    AND (
      update_row.transfer_status = 'FAILED'
      OR UPPER(BTRIM(COALESCE(update_row.rail_state, update_row.provider_state, transfer_row.rail_state, transfer_row.status, ''))) IN ('FAILED', 'REJECTED', 'DECLINED', 'ERROR')
      OR UPPER(BTRIM(COALESCE(transfer_row.status, ''))) IN ('FAILED', 'CANCELLED')
    )
    AND UPPER(BTRIM(COALESCE(transfer_row.payee_entity_kind, ''))) IN ('CANDIDATE', 'UMBRELLA')
    AND transfer_row.payee_entity_id IS NOT NULL
    AND NULLIF(BTRIM(COALESCE(transfer_row.bank_details_hash_snapshot, '')), '') IS NOT NULL
    AND NULLIF(BTRIM(COALESCE(transfer_row.rail_provider, '')), '') IS NOT NULL
    AND NULLIF(BTRIM(COALESCE(transfer_row.rail_env, '')), '') IS NOT NULL
  ORDER BY transfer_row.id, update_row.row_seq;

  UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
  SET source_bank_event_id = (
    SELECT source_event.id
    FROM public.pay_bank_transfer_events AS source_event
    WHERE source_event.pay_batch_id = recovery_update.pay_batch_id
      AND source_event.pay_bank_transfer_id = recovery_update.pay_bank_transfer_id
      AND UPPER(BTRIM(COALESCE(source_event.mapping_status, ''))) = 'MATCHED'
      AND UPPER(BTRIM(COALESCE(source_event.mapping_method, ''))) IN (
        'TRANSFER_ID',
        'PROVIDER_EVENT_ID',
        'PROVIDER_REFERENCE',
        'REQUEST_ID',
        'RAIL_TX_ID',
        'PAYMENT_REFERENCE',
        'MANUAL_TRANSFER_SELECTION'
      )
      AND (
        UPPER(BTRIM(COALESCE(
          source_event.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}',
          source_event.raw_payload->>'provider_submission_status',
          ''
        ))) = 'PROVIDER_SUBMISSION_REJECTED'
        OR NULLIF(BTRIM(COALESCE(
          source_event.raw_payload #>> '{provider_submit_diagnostic,provider_error_code}',
          source_event.raw_payload->>'provider_error_code',
          ''
        )), '') = '2101'
        OR LOWER(BTRIM(COALESCE(
          source_event.raw_payload #>> '{provider_submit_diagnostic,provider_error_message_redacted}',
          source_event.raw_payload->>'provider_error_message_redacted',
          source_event.raw_payload->>'failed_reason',
          ''
        ))) LIKE '%counterparty not found%'
        OR (
          UPPER(BTRIM(COALESCE(source_event.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
          AND UPPER(BTRIM(COALESCE(source_event.normalised_state, source_event.provider_state, ''))) IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED')
        )
      )
    ORDER BY source_event.received_at_utc DESC NULLS LAST,
             source_event.event_time_utc DESC NULLS LAST,
             source_event.id DESC
    LIMIT 1
  )
  WHERE recovery_update.pay_bank_transfer_id IS NOT NULL;

  WITH stale_map_matches AS (
    SELECT
      recovery_row.pay_bank_transfer_id,
      map_row.id AS bank_payee_map_id
    FROM pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_row
    JOIN public.bank_payee_map AS map_row
      ON map_row.rail_provider = recovery_row.rail_provider
     AND map_row.rail_env = recovery_row.rail_env
     AND map_row.entity_kind = recovery_row.payee_entity_kind
     AND map_row.entity_id = recovery_row.payee_entity_id
     AND map_row.bank_details_hash = recovery_row.bank_details_hash_snapshot
     AND (recovery_row.provider_payee_id IS NULL OR map_row.payee_id = recovery_row.provider_payee_id)
     AND (recovery_row.provider_payee_account_id IS NULL OR map_row.payee_account_id IS NOT DISTINCT FROM recovery_row.provider_payee_account_id)
  ),
  deleted_maps AS (
    DELETE FROM public.bank_payee_map AS map_delete
    USING stale_map_matches
    WHERE map_delete.id = stale_map_matches.bank_payee_map_id
    RETURNING stale_map_matches.pay_bank_transfer_id, map_delete.id AS bank_payee_map_id
  )
  UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
  SET invalidated_map_ids = COALESCE((
        SELECT jsonb_agg(to_jsonb(deleted_maps.bank_payee_map_id::text) ORDER BY deleted_maps.bank_payee_map_id::text)
        FROM deleted_maps
        WHERE deleted_maps.pay_bank_transfer_id = recovery_update.pay_bank_transfer_id
      ), '[]'::jsonb),
      invalidated_map_count = COALESCE((
        SELECT COUNT(*)::integer
        FROM deleted_maps
        WHERE deleted_maps.pay_bank_transfer_id = recovery_update.pay_bank_transfer_id
      ), 0)
  WHERE recovery_update.pay_bank_transfer_id IS NOT NULL;

  SELECT COALESCE(public.settings_defaults.banking_pay_auto_unwind_terminal_no_money, false)
  INTO v_counterparty_map_auto_reverse_setting
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  IF NOT FOUND THEN
    v_counterparty_map_auto_reverse_setting := false;
  END IF;

  FOR v_counterparty_recovery_record IN
    SELECT recovery_row.*
    FROM pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_row
    ORDER BY recovery_row.pay_bank_transfer_id
  LOOP
    v_counterparty_readiness_result := '{}'::jsonb;

    IF v_counterparty_recovery_record.candidate_id IS NOT NULL THEN
      SELECT public.pay_workbench_enqueue_payee_readiness_ensure(
        p_candidate_id => v_counterparty_recovery_record.candidate_id,
        p_payees_json => jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'payee_entity_kind', v_counterparty_recovery_record.payee_entity_kind,
          'payee_entity_id', v_counterparty_recovery_record.payee_entity_id::text,
          'entity_kind', v_counterparty_recovery_record.payee_entity_kind,
          'entity_id', v_counterparty_recovery_record.payee_entity_id::text,
          'bank_details_hash', v_counterparty_recovery_record.bank_details_hash_snapshot,
          'rail_provider', v_counterparty_recovery_record.rail_provider,
          'rail_env', v_counterparty_recovery_record.rail_env,
          'pay_bank_transfer_id', v_counterparty_recovery_record.pay_bank_transfer_id::text
        ))),
        p_snapshot_run_id => NULL::uuid,
        p_session_id => NULL::uuid,
        p_reason => 'PROVIDER_COUNTERPARTY_NOT_FOUND_STALE_PAYEE_MAP',
        p_actor_user_id => p_actor_user_id,
        p_payload_json => jsonb_strip_nulls(jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
          'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
          'pay_bank_transfer_id', v_counterparty_recovery_record.pay_bank_transfer_id::text,
          'provider_error_code', v_counterparty_recovery_record.provider_error_code,
          'provider_error_message_redacted', v_counterparty_recovery_record.provider_error_message_redacted,
          'stale_payee_map_invalidated', (v_counterparty_recovery_record.invalidated_map_count > 0),
          'stale_payee_map_invalidated_map_ids', v_counterparty_recovery_record.invalidated_map_ids
        ))
      )
      INTO v_counterparty_readiness_result;
    END IF;

    UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
    SET readiness_enqueue_result = v_counterparty_readiness_result,
        auto_reverse_setting = COALESCE(v_counterparty_map_auto_reverse_setting, false)
    WHERE recovery_update.pay_bank_transfer_id = v_counterparty_recovery_record.pay_bank_transfer_id;

    IF COALESCE(v_counterparty_map_auto_reverse_setting, false) THEN
      v_counterparty_auto_request_result := '{}'::jsonb;
      v_counterparty_auto_expand_result := '{}'::jsonb;
      v_counterparty_auto_process_result := '{}'::jsonb;
      v_counterparty_auto_request_id := NULL::uuid;
      v_counterparty_auto_work_applied_count := 0;

      IF v_counterparty_recovery_record.source_bank_event_id IS NULL THEN
        UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
        SET auto_reverse_requested = false,
            auto_reverse_request_id = NULL::uuid,
            auto_reverse_result_json = jsonb_build_object(
              'ok', false,
              'code', 'AUTO_RELEASE_SOURCE_EVENT_MISSING',
              'message', 'Automatic release was not attempted because no strongly matched provider rejection event was available for the selected transfer.'
            ),
            auto_reverse_applied_count = 0,
            recovery_status = 'AUTO_RELEASE_FAILED_MANUAL_RELEASE_REQUIRED',
            recovery_action = 'MANUAL_RELEASE_REQUIRED'
        WHERE recovery_update.pay_bank_transfer_id = v_counterparty_recovery_record.pay_bank_transfer_id;
      ELSE
      BEGIN
        v_counterparty_auto_request_result := public.pay_payment_correction_request_start(
          p_pay_batch_id => p_pay_batch_id,
          p_selection_json => jsonb_build_object(
            'scope_type', 'TRANSFER',
            'pay_bank_transfer_ids', jsonb_build_array(v_counterparty_recovery_record.pay_bank_transfer_id::text),
            'source_context', 'PROVIDER_COUNTERPARTY_NOT_FOUND',
            'requested_action', 'NO_MONEY_UNWIND_AND_RECALCULATE'
          ),
          p_reason => 'Automatic provider counterparty-not-found no-money unwind',
          p_actor_user_id => NULL::uuid,
          p_source_bank_event_id => v_counterparty_recovery_record.source_bank_event_id,
          p_auto_requested => true,
          p_accepted_resolution_json => jsonb_strip_nulls(jsonb_build_object(
            'provider_submit_diagnostic', v_counterparty_recovery_record.provider_submit_diagnostic,
            'provider_submission_status', 'PROVIDER_SUBMISSION_REJECTED',
            'provider_error_code', v_counterparty_recovery_record.provider_error_code,
            'provider_error_message_redacted', v_counterparty_recovery_record.provider_error_message_redacted,
            'pay_bank_transfer_id', v_counterparty_recovery_record.pay_bank_transfer_id::text,
            'source_bank_event_id', CASE WHEN v_counterparty_recovery_record.source_bank_event_id IS NULL THEN NULL ELSE v_counterparty_recovery_record.source_bank_event_id::text END,
            'auto_reversal_reason', 'PROVIDER_COUNTERPARTY_NOT_FOUND'
          ))
        );

        IF NULLIF(BTRIM(COALESCE(v_counterparty_auto_request_result->>'correction_request_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
          v_counterparty_auto_request_id := (v_counterparty_auto_request_result->>'correction_request_id')::uuid;
          v_counterparty_auto_expand_result := public.pay_payment_correction_expand_work(v_counterparty_auto_request_id, NULL::uuid);
          v_counterparty_auto_process_result := public.pay_payment_correction_process_chunk(v_counterparty_auto_request_id, 50, 'provider-counterparty-not-found');

          SELECT COUNT(*)::integer
          INTO v_counterparty_auto_work_applied_count
          FROM public.pay_payment_correction_work_items AS correction_work_item
          WHERE correction_work_item.correction_request_id = v_counterparty_auto_request_id
            AND correction_work_item.pay_bank_transfer_id = v_counterparty_recovery_record.pay_bank_transfer_id
            AND correction_work_item.status = 'APPLIED';
        END IF;

        UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
        SET auto_reverse_requested = true,
            auto_reverse_request_id = v_counterparty_auto_request_id,
            auto_reverse_result_json = jsonb_strip_nulls(jsonb_build_object(
              'request_start_result', v_counterparty_auto_request_result,
              'expand_result', v_counterparty_auto_expand_result,
              'process_result', v_counterparty_auto_process_result,
              'source_bank_event_id', CASE WHEN v_counterparty_recovery_record.source_bank_event_id IS NULL THEN NULL ELSE v_counterparty_recovery_record.source_bank_event_id::text END,
              'applied_work_item_count', v_counterparty_auto_work_applied_count
            )),
            auto_reverse_applied_count = COALESCE(v_counterparty_auto_work_applied_count, 0),
            recovery_status = CASE WHEN COALESCE(v_counterparty_auto_work_applied_count, 0) > 0 THEN 'AUTO_RELEASED_FOR_NEXT_RUN' ELSE 'AUTO_RELEASE_REQUESTED' END,
            recovery_action = CASE WHEN COALESCE(v_counterparty_auto_work_applied_count, 0) > 0 THEN 'READY_FOR_NEXT_RUN_AFTER_PAYEE_READINESS' ELSE 'AUTO_RELEASE_IN_PROGRESS' END
        WHERE recovery_update.pay_bank_transfer_id = v_counterparty_recovery_record.pay_bank_transfer_id;
      EXCEPTION
        WHEN OTHERS THEN
          UPDATE pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_update
          SET auto_reverse_requested = true,
              auto_reverse_request_id = v_counterparty_auto_request_id,
              auto_reverse_result_json = jsonb_strip_nulls(jsonb_build_object(
                'request_start_result', v_counterparty_auto_request_result,
                'expand_result', v_counterparty_auto_expand_result,
                'process_result', v_counterparty_auto_process_result,
                'source_bank_event_id', CASE WHEN v_counterparty_recovery_record.source_bank_event_id IS NULL THEN NULL ELSE v_counterparty_recovery_record.source_bank_event_id::text END,
                'error', SQLERRM
              )),
              recovery_status = 'AUTO_RELEASE_FAILED_MANUAL_RELEASE_REQUIRED',
              recovery_action = 'MANUAL_RELEASE_REQUIRED'
          WHERE recovery_update.pay_bank_transfer_id = v_counterparty_recovery_record.pay_bank_transfer_id;
      END;
      END IF;
    END IF;
  END LOOP;

  UPDATE public.pay_bank_transfers AS transfer_update
  SET rail_meta_json = jsonb_strip_nulls(
        COALESCE(transfer_update.rail_meta_json, '{}'::jsonb)
        || jsonb_build_object(
          'stale_payee_map_recovery', jsonb_strip_nulls(jsonb_build_object(
            'stale_payee_map_detected', true,
            'stale_payee_map_reason', 'COUNTERPARTY_NOT_FOUND',
            'stale_payee_map_invalidation_attempted', true,
            'stale_payee_map_invalidated', (recovery_row.invalidated_map_count > 0),
            'stale_payee_map_invalidated_map_ids', recovery_row.invalidated_map_ids,
            'stale_payee_map_invalidated_count', recovery_row.invalidated_map_count,
            'payee_route', jsonb_strip_nulls(jsonb_build_object(
              'rail_provider', recovery_row.rail_provider,
              'rail_env', recovery_row.rail_env,
              'payee_entity_kind', recovery_row.payee_entity_kind,
              'payee_entity_id', recovery_row.payee_entity_id::text,
              'bank_details_hash_snapshot', recovery_row.bank_details_hash_snapshot,
              'provider_payee_id', recovery_row.provider_payee_id,
              'provider_payee_account_id', recovery_row.provider_payee_account_id
            )),
            'readiness_enqueue_result', recovery_row.readiness_enqueue_result,
            'source_bank_event_id', CASE WHEN recovery_row.source_bank_event_id IS NULL THEN NULL ELSE recovery_row.source_bank_event_id::text END,
            'auto_reverse_setting', recovery_row.auto_reverse_setting,
            'auto_reverse_requested', recovery_row.auto_reverse_requested,
            'auto_reverse_request_id', CASE WHEN recovery_row.auto_reverse_request_id IS NULL THEN NULL ELSE recovery_row.auto_reverse_request_id::text END,
            'auto_reverse_result', recovery_row.auto_reverse_result_json,
            'auto_reverse_applied_count', recovery_row.auto_reverse_applied_count,
            'recovery_status', recovery_row.recovery_status,
            'recovery_action', recovery_row.recovery_action,
            'manual_recoverable', (recovery_row.recovery_action = 'MANUAL_RELEASE_REQUIRED'),
            'provider_error_code', recovery_row.provider_error_code,
            'provider_error_message_redacted', recovery_row.provider_error_message_redacted,
            'provider_http_status', recovery_row.provider_http_status,
            'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
            'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
            'updated_at_utc', v_now::text
          )),
          'provider_submit_diagnostic', jsonb_strip_nulls(
            COALESCE(transfer_update.rail_meta_json->'provider_submit_diagnostic', recovery_row.provider_submit_diagnostic, '{}'::jsonb)
            || recovery_row.provider_submit_diagnostic
            || jsonb_build_object(
              'stale_payee_map_detected', true,
              'stale_payee_map_reason', 'COUNTERPARTY_NOT_FOUND',
              'stale_payee_map_invalidated', (recovery_row.invalidated_map_count > 0),
              'stale_payee_map_invalidated_map_ids', recovery_row.invalidated_map_ids,
              'readiness_enqueue_result', recovery_row.readiness_enqueue_result,
              'source_bank_event_id', CASE WHEN recovery_row.source_bank_event_id IS NULL THEN NULL ELSE recovery_row.source_bank_event_id::text END,
              'auto_reverse_setting', recovery_row.auto_reverse_setting,
              'auto_reverse_requested', recovery_row.auto_reverse_requested,
              'auto_reverse_request_id', CASE WHEN recovery_row.auto_reverse_request_id IS NULL THEN NULL ELSE recovery_row.auto_reverse_request_id::text END,
              'auto_reverse_applied_count', recovery_row.auto_reverse_applied_count,
              'recovery_status', recovery_row.recovery_status,
              'recovery_action', recovery_row.recovery_action,
              'manual_recoverable', (recovery_row.recovery_action = 'MANUAL_RELEASE_REQUIRED')
            )
          )
        )
      )
  FROM pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_row
  WHERE transfer_update.id = recovery_row.pay_bank_transfer_id
    AND transfer_update.pay_batch_id = p_pay_batch_id;

  SELECT
    COUNT(*)::integer,
    COALESCE(SUM(recovery_row.invalidated_map_count), 0)::integer,
    (COUNT(*) FILTER (WHERE recovery_row.auto_reverse_requested IS TRUE))::integer,
    COALESCE(SUM(recovery_row.auto_reverse_applied_count), 0)::integer,
    (COUNT(*) FILTER (WHERE recovery_row.recovery_action = 'MANUAL_RELEASE_REQUIRED'))::integer,
    COALESCE(jsonb_agg(
      jsonb_strip_nulls(jsonb_build_object(
        'pay_bank_transfer_id', recovery_row.pay_bank_transfer_id::text,
        'pay_batch_id', recovery_row.pay_batch_id::text,
        'candidate_id', CASE WHEN recovery_row.candidate_id IS NULL THEN NULL ELSE recovery_row.candidate_id::text END,
        'umbrella_id', CASE WHEN recovery_row.umbrella_id IS NULL THEN NULL ELSE recovery_row.umbrella_id::text END,
        'payee_entity_kind', recovery_row.payee_entity_kind,
        'payee_entity_id', recovery_row.payee_entity_id::text,
        'bank_details_hash_snapshot', recovery_row.bank_details_hash_snapshot,
        'rail_provider', recovery_row.rail_provider,
        'rail_env', recovery_row.rail_env,
        'provider_payee_id', recovery_row.provider_payee_id,
        'provider_payee_account_id', recovery_row.provider_payee_account_id,
        'provider_error_code', recovery_row.provider_error_code,
        'provider_error_message_redacted', recovery_row.provider_error_message_redacted,
        'provider_http_status', recovery_row.provider_http_status,
        'stale_payee_map_detected', true,
        'stale_payee_map_invalidation_attempted', true,
        'invalidated_map_ids', recovery_row.invalidated_map_ids,
        'invalidated_map_count', recovery_row.invalidated_map_count,
        'readiness_enqueue_result', recovery_row.readiness_enqueue_result,
        'source_bank_event_id', CASE WHEN recovery_row.source_bank_event_id IS NULL THEN NULL ELSE recovery_row.source_bank_event_id::text END,
        'auto_reverse_setting', recovery_row.auto_reverse_setting,
        'auto_reverse_requested', recovery_row.auto_reverse_requested,
        'auto_reverse_request_id', CASE WHEN recovery_row.auto_reverse_request_id IS NULL THEN NULL ELSE recovery_row.auto_reverse_request_id::text END,
        'auto_reverse_result', recovery_row.auto_reverse_result_json,
        'auto_reverse_applied_count', recovery_row.auto_reverse_applied_count,
        'recovery_status', recovery_row.recovery_status,
        'recovery_action', recovery_row.recovery_action,
        'manual_recoverable', (recovery_row.recovery_action = 'MANUAL_RELEASE_REQUIRED')
      ))
      ORDER BY recovery_row.pay_bank_transfer_id::text
    ), '[]'::jsonb)
  INTO
    v_counterparty_map_recovery_count,
    v_counterparty_map_invalidated_count,
    v_counterparty_map_auto_reverse_requested_count,
    v_counterparty_map_auto_reverse_applied_count,
    v_counterparty_map_manual_recoverable_count,
    v_counterparty_map_recovery_json
  FROM pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_row;

  SELECT COALESCE(jsonb_agg(
    jsonb_strip_nulls(jsonb_build_object(
      'pay_bank_transfer_id', recovery_row.pay_bank_transfer_id::text,
      'readiness_enqueue_result', recovery_row.readiness_enqueue_result
    ))
    ORDER BY recovery_row.pay_bank_transfer_id::text
  ), '[]'::jsonb)
  INTO v_counterparty_map_readiness_enqueue_json
  FROM pg_temp.tmp_provider_counterparty_not_found_recovery AS recovery_row;


  IF v_is_scoped THEN
    SELECT
      COUNT(*) FILTER (
        WHERE scoped_row.is_provider_evidence IS TRUE
           OR (
             scoped_row.money_is_final_money_moved IS TRUE
             AND (
               scoped_row.is_provider_source IS TRUE
               OR scoped_row.provider_response_present IS TRUE
               OR scoped_row.provider_response_received IS TRUE
               OR scoped_row.is_provider_external_evidence IS TRUE
               OR scoped_row.provider_acceptance_evidence_present IS TRUE
             )
           )
      )::integer,
      COUNT(*) FILTER (
        WHERE scoped_row.is_provider_source IS NOT TRUE
          AND scoped_row.is_provider_evidence IS NOT TRUE
          AND scoped_row.is_attempted_but_unproven IS NOT TRUE
      )::integer,
      COUNT(*) FILTER (
        WHERE scoped_row.transfer_status = 'FAILED'
           OR scoped_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED'
      )::integer,
      COUNT(*) FILTER (WHERE scoped_row.transfer_status = 'PENDING')::integer,
      COUNT(*) FILTER (
        WHERE scoped_row.provider_submission_unknown IS TRUE
           OR scoped_row.is_attempted_but_unproven IS TRUE
           OR scoped_row.provider_submission_status IN (
             'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
             'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
             'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
             'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
           )
      )::integer,
      COUNT(*) FILTER (WHERE scoped_row.is_attempted_but_unproven IS TRUE)::integer,
      COUNT(*) FILTER (WHERE scoped_row.provider_submission_status = 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')::integer,
      COUNT(*) FILTER (
        WHERE scoped_row.transfer_status = 'PENDING'
          AND scoped_row.is_provider_source IS NOT TRUE
          AND scoped_row.is_provider_evidence IS NOT TRUE
          AND scoped_row.provider_request_sent IS NOT TRUE
          AND scoped_row.provider_response_present IS NOT TRUE
          AND scoped_row.provider_response_received IS NOT TRUE
          AND COALESCE(NULLIF(BTRIM(scoped_row.provider_submission_status), ''), 'NO_PROVIDER_SUBMISSION_ATTEMPTED') IN (
            'NO_PROVIDER_SUBMISSION_ATTEMPTED',
            'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
          )
      )::integer,
      COUNT(*) FILTER (
        WHERE scoped_row.is_attempted_but_unproven IS TRUE
           OR scoped_row.provider_submission_unknown IS TRUE
           OR scoped_row.provider_submission_status IN (
             'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME',
             'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK',
             'PROVIDER_SUBMISSION_MALFORMED_RESPONSE',
             'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'
           )
      )::integer
    INTO v_provider_submitted_count,
         v_local_only_count,
         v_failed_count,
         v_pending_count,
         v_ambiguous_count,
         v_attempted_but_unproven_count,
         v_provider_attempt_without_external_id_count,
         v_remaining_submit_attempt_required,
         v_remaining_provider_evidence_required
    FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row;

    SELECT
      COUNT(*) FILTER (WHERE scoped_row.is_provider_evidence IS TRUE)::integer,
      COUNT(*) FILTER (WHERE scoped_row.is_provider_external_evidence IS TRUE)::integer,
      COUNT(*) FILTER (WHERE scoped_row.provider_response_present IS TRUE OR scoped_row.provider_response_received IS TRUE OR scoped_row.is_provider_source IS TRUE)::integer,
      COUNT(*) FILTER (WHERE scoped_row.provider_request_sent IS TRUE OR scoped_row.provider_request_sent_confirmed IS TRUE OR scoped_row.provider_response_present IS TRUE OR scoped_row.provider_response_received IS TRUE OR scoped_row.is_provider_source IS TRUE OR scoped_row.is_provider_evidence IS TRUE)::integer,
      COUNT(*) FILTER (WHERE scoped_row.provider_submission_unknown IS TRUE OR scoped_row.is_attempted_but_unproven IS TRUE OR scoped_row.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'))::integer,
      COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'transfer_id', scoped_row.transfer_id::text,
        'provider_submission_status', scoped_row.provider_submission_status,
        'provider_request_sent', scoped_row.provider_request_sent OR scoped_row.provider_request_sent_confirmed,
        'provider_request_sent_confirmed', scoped_row.provider_request_sent_confirmed,
        'provider_request_dispatched_at_utc', scoped_row.provider_request_dispatched_at_utc,
        'provider_response_received', scoped_row.provider_response_received,
        'provider_response_present', scoped_row.provider_response_present,
        'provider_external_evidence_present', scoped_row.is_provider_external_evidence,
        'provider_acceptance_evidence_present', (
          scoped_row.is_provider_evidence IS TRUE
          OR (
            scoped_row.money_is_final_money_moved IS TRUE
            AND (
              scoped_row.is_provider_source IS TRUE
              OR scoped_row.provider_response_present IS TRUE
              OR scoped_row.provider_response_received IS TRUE
              OR scoped_row.is_provider_external_evidence IS TRUE
              OR scoped_row.provider_acceptance_evidence_present IS TRUE
            )
          )
        ),
        'rail_tx_id', CASE WHEN scoped_row.is_provider_evidence IS TRUE THEN scoped_row.rail_tx_id ELSE NULL::text END,
        'rail_state', scoped_row.rail_state,
        'provider_http_status', scoped_row.provider_http_status,
        'provider_error_code', scoped_row.provider_error_code,
        'request_id', scoped_row.request_id,
        'idempotency_key', scoped_row.idempotency_key,
        'money_cash_state', scoped_row.money_cash_state,
        'money_normalised_transfer_status', scoped_row.money_normalised_transfer_status,
        'money_is_final_money_moved', scoped_row.money_is_final_money_moved,
        'money_is_terminal_no_money', scoped_row.money_is_terminal_no_money,
        'money_is_pending_non_final', scoped_row.money_is_pending_non_final,
        'money_completed_at_allowed', scoped_row.money_completed_at_allowed,
        'money_reason', scoped_row.money_reason,
        'money_support_details_json', scoped_row.money_support_details_json,
        'payment_lifecycle_state', CASE
          WHEN scoped_row.money_is_final_money_moved IS TRUE THEN 'PAID_OR_SETTLED'
          WHEN scoped_row.money_is_terminal_no_money IS TRUE THEN 'PROVIDER_FAILED_NO_MONEY'
          WHEN scoped_row.money_is_pending_non_final IS TRUE THEN 'PROVIDER_SUBMITTED_PENDING'
          WHEN scoped_row.provider_submission_unknown IS TRUE OR scoped_row.is_attempted_but_unproven IS TRUE THEN 'PROVIDER_OUTCOME_UNKNOWN'
          ELSE NULL::text
        END,
        'manual_resolution_required', scoped_row.manual_resolution_required,
        'safe_retry_available', scoped_row.safe_retry_available
      )) ORDER BY scoped_row.row_seq), '[]'::jsonb)
    INTO v_provider_acceptance_evidence_count,
         v_provider_external_evidence_count,
         v_provider_response_present_count,
         v_provider_request_sent_count,
         v_provider_submission_unknown_count,
         v_transfer_provider_outcomes
    FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row;

    SELECT COALESCE(scoped_row.provider_submit_diagnostic, '{}'::jsonb)
    INTO v_provider_submit_diagnostic
    FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row
    ORDER BY CASE
        WHEN scoped_row.provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' AND scoped_row.is_provider_evidence IS TRUE THEN 0
        WHEN scoped_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 1
        WHEN scoped_row.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID') THEN 2
        ELSE 3
      END,
      scoped_row.row_seq
    LIMIT 1;

    v_remaining_unsubmitted_count := v_remaining_submit_attempt_required;
    v_requires_provider_poll := COALESCE(v_ambiguous_count, 0) > 0;
    v_requires_review := COALESCE(v_failed_count, 0) > 0
      OR COALESCE(v_ambiguous_count, 0) > 0
      OR COALESCE(v_provider_attempt_without_external_id_count, 0) > 0;

    SELECT COALESCE(
             NULLIF(BTRIM(COALESCE(scoped_row.rail_tx_id, '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_reference, '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_event_id, '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'provider_transaction_id', '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'provider_payment_id', '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'rail_tx_id', '')), ''),
             NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'provider_reference', '')), '')
           )
    INTO v_execution_commit_ref_candidate
    FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row
    WHERE scoped_row.is_provider_evidence IS TRUE
    ORDER BY CASE
        WHEN NULLIF(BTRIM(COALESCE(scoped_row.rail_tx_id, '')), '') IS NOT NULL THEN 0
        WHEN NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'provider_transaction_id', '')), '') IS NOT NULL THEN 1
        WHEN NULLIF(BTRIM(COALESCE(scoped_row.provider_submit_diagnostic->>'provider_payment_id', '')), '') IS NOT NULL THEN 2
        WHEN NULLIF(BTRIM(COALESCE(scoped_row.provider_reference, '')), '') IS NOT NULL THEN 3
        WHEN NULLIF(BTRIM(COALESCE(scoped_row.provider_event_id, '')), '') IS NOT NULL THEN 4
        ELSE 5
      END,
      scoped_row.row_seq
    LIMIT 1;

    SELECT COALESCE(SUM(COALESCE(transfer_row.amount, 0)), 0)
    INTO v_provider_transfer_total
    FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row
    JOIN public.pay_bank_transfers AS transfer_row
      ON transfer_row.id = scoped_row.transfer_id
     AND transfer_row.pay_batch_id = p_pay_batch_id
    WHERE scoped_row.is_provider_evidence IS TRUE;

    SELECT EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_bank_transfer_updates AS scoped_row
      WHERE (
          scoped_row.is_provider_evidence IS TRUE
          OR (
            scoped_row.money_is_final_money_moved IS TRUE
            AND (
              scoped_row.is_provider_source IS TRUE
              OR scoped_row.provider_response_present IS TRUE
              OR scoped_row.provider_response_received IS TRUE
              OR scoped_row.is_provider_external_evidence IS TRUE
              OR scoped_row.provider_acceptance_evidence_present IS TRUE
            )
          )
        )
        AND scoped_row.money_is_final_money_moved IS TRUE
        AND scoped_row.money_completed_at_allowed IS TRUE
    )
    INTO v_has_completed_provider_evidence;

    v_provider_boundary_crossed := (
      COALESCE(v_provider_acceptance_evidence_count, 0) > 0
      AND COALESCE(v_provider_external_evidence_count, 0) > 0
      AND COALESCE(v_remaining_submit_attempt_required, 0) = 0
      AND COALESCE(v_failed_count, 0) = 0
      AND COALESCE(v_ambiguous_count, 0) = 0
      AND COALESCE(v_provider_attempt_without_external_id_count, 0) = 0
      AND NULLIF(BTRIM(COALESCE(v_execution_commit_ref_candidate, '')), '') IS NOT NULL
    );

    v_can_mark_committed := COALESCE(v_provider_boundary_crossed, false) IS TRUE
      AND COALESCE(v_has_completed_provider_evidence, false) IS TRUE
      AND COALESCE(v_requires_review, false) IS NOT TRUE;

    v_can_mark_submitted := COALESCE(v_provider_boundary_crossed, false) IS TRUE
      AND COALESCE(v_can_mark_committed, false) IS NOT TRUE
      AND COALESCE(v_requires_review, false) IS NOT TRUE;

    v_submitted_state_finalisation_attempted := COALESCE(v_provider_boundary_crossed, false) IS TRUE
      AND upper(BTRIM(COALESCE(v_batch_row.status, ''))) NOT IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS')
      AND upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED'))) <> 'COMMITTED';

    IF v_can_mark_committed THEN
      v_execution_commit_state := 'COMMITTED';
    ELSIF v_can_mark_submitted THEN
      v_execution_commit_state := 'SUBMITTED_NOT_COMMITTED';
    ELSE
      v_execution_commit_state := upper(BTRIM(COALESCE(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
      IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
        v_execution_commit_state := 'NOT_SUBMITTED';
      END IF;
    END IF;

    v_execution_commit_ref := CASE
      WHEN v_execution_commit_state IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), ''), v_execution_commit_ref_candidate)
      ELSE NULL::text
    END;

    v_execution_committed_at_utc := CASE
      WHEN v_execution_commit_state = 'COMMITTED' THEN COALESCE(v_batch_row.execution_committed_at_utc, v_now)
      ELSE NULL::timestamptz
    END;

    v_submission_evidence_json := jsonb_build_object(
      'scoped', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
      'provider_submitted_count', COALESCE(v_provider_submitted_count, 0),
      'local_idempotency_only_count', COALESCE(v_local_only_count, 0),
      'local_only_count', COALESCE(v_local_only_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'pending_count', COALESCE(v_pending_count, 0),
      'ambiguous_count', COALESCE(v_ambiguous_count, 0),
      'attempted_but_unproven_count', COALESCE(v_attempted_but_unproven_count, 0),
      'provider_attempt_without_external_id_count', COALESCE(v_provider_attempt_without_external_id_count, 0),
      'remaining_submit_attempt_required', COALESCE(v_remaining_submit_attempt_required, 0),
      'remaining_provider_evidence_required', COALESCE(v_remaining_provider_evidence_required, 0),
      'requires_provider_poll', COALESCE(v_requires_provider_poll, false),
      'requires_review', COALESCE(v_requires_review, false),
      'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
      'execution_commit_ref_candidate', v_execution_commit_ref_candidate,
      'provider_transfer_total', v_provider_transfer_total,
      'can_mark_submitted', COALESCE(v_can_mark_submitted, false),
      'can_mark_committed', COALESCE(v_can_mark_committed, false),
      'submitted_state_finalisation_attempted', COALESCE(v_submitted_state_finalisation_attempted, false)
    );

    v_summary_json := jsonb_build_object(
      'scoped', true,
      'summary_scope', 'SCOPED_RAIL_UPDATE',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
      'updated_count', COALESCE(v_updated_count, 0),
      'provider_submitted_count', COALESCE(v_provider_submitted_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'pending_count', COALESCE(v_pending_count, 0),
      'ambiguous_count', COALESCE(v_ambiguous_count, 0),
      'requires_review', COALESCE(v_requires_review, false),
      'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
      'can_mark_submitted', COALESCE(v_can_mark_submitted, false),
      'can_mark_committed', COALESCE(v_can_mark_committed, false),
      'execution_commit_ref_candidate', v_execution_commit_ref_candidate,
      'provider_transfer_total', v_provider_transfer_total,
      'submitted_state_finalisation_attempted', COALESCE(v_submitted_state_finalisation_attempted, false),
      'counterparty_not_found_recovery_count', COALESCE(v_counterparty_map_recovery_count, 0),
      'counterparty_not_found_invalidated_map_count', COALESCE(v_counterparty_map_invalidated_count, 0),
      'counterparty_not_found_auto_reverse_requested_count', COALESCE(v_counterparty_map_auto_reverse_requested_count, 0),
      'counterparty_not_found_auto_reverse_applied_count', COALESCE(v_counterparty_map_auto_reverse_applied_count, 0),
      'counterparty_not_found_manual_recoverable_count', COALESCE(v_counterparty_map_manual_recoverable_count, 0),
      'counterparty_not_found_recoveries', COALESCE(v_counterparty_map_recovery_json, '[]'::jsonb),
      'counterparty_not_found_readiness_enqueue', COALESCE(v_counterparty_map_readiness_enqueue_json, '[]'::jsonb),
      'blocked_funds_state', '{}'::jsonb
    );

    UPDATE public.pay_batches AS batch_update
    SET status = CASE
          WHEN upper(BTRIM(COALESCE(batch_update.status, ''))) IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS') THEN batch_update.status
          WHEN COALESCE(v_can_mark_submitted, false) IS TRUE OR COALESCE(v_can_mark_committed, false) IS TRUE THEN 'WAITING_BANK_CONFIRM'
          ELSE batch_update.status
        END,
        execution_commit_state = CASE
          WHEN upper(BTRIM(COALESCE(batch_update.execution_commit_state, 'NOT_SUBMITTED'))) = 'COMMITTED' THEN batch_update.execution_commit_state
          WHEN upper(BTRIM(COALESCE(batch_update.status, ''))) IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS') THEN batch_update.execution_commit_state
          WHEN COALESCE(v_can_mark_committed, false) IS TRUE THEN 'COMMITTED'
          WHEN COALESCE(v_can_mark_submitted, false) IS TRUE THEN 'SUBMITTED_NOT_COMMITTED'
          ELSE batch_update.execution_commit_state
        END,
        execution_commit_ref = CASE
          WHEN upper(BTRIM(COALESCE(batch_update.status, ''))) IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS') THEN batch_update.execution_commit_ref
          WHEN COALESCE(v_can_mark_submitted, false) IS TRUE OR COALESCE(v_can_mark_committed, false) IS TRUE THEN COALESCE(NULLIF(BTRIM(COALESCE(batch_update.execution_commit_ref, '')), ''), v_execution_commit_ref_candidate)
          ELSE batch_update.execution_commit_ref
        END,
        execution_committed_at_utc = CASE
          WHEN upper(BTRIM(COALESCE(batch_update.execution_commit_state, 'NOT_SUBMITTED'))) = 'COMMITTED' THEN batch_update.execution_committed_at_utc
          WHEN upper(BTRIM(COALESCE(batch_update.status, ''))) IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS') THEN batch_update.execution_committed_at_utc
          WHEN COALESCE(v_can_mark_committed, false) IS TRUE THEN COALESCE(batch_update.execution_committed_at_utc, v_execution_committed_at_utc, v_now)
          WHEN COALESCE(v_can_mark_submitted, false) IS TRUE THEN NULL::timestamptz
          ELSE batch_update.execution_committed_at_utc
        END,
        total_bank_out = CASE
          WHEN (COALESCE(v_can_mark_submitted, false) IS TRUE OR COALESCE(v_can_mark_committed, false) IS TRUE)
           AND batch_update.total_bank_out IS NULL THEN COALESCE(v_provider_transfer_total, batch_update.total_bank_out)
          ELSE batch_update.total_bank_out
        END,
        executing_started_at_utc = CASE
          WHEN COALESCE(v_can_mark_submitted, false) IS TRUE OR COALESCE(v_can_mark_committed, false) IS TRUE THEN COALESCE(batch_update.executing_started_at_utc, v_now)
          ELSE batch_update.executing_started_at_utc
        END,
        last_status_checked_at_utc = v_now
    WHERE batch_update.id = p_pay_batch_id
    RETURNING upper(BTRIM(COALESCE(batch_update.status, ''))),
              upper(BTRIM(COALESCE(batch_update.execution_commit_state, 'NOT_SUBMITTED'))),
              batch_update.execution_commit_ref,
              batch_update.execution_committed_at_utc
    INTO v_batch_status_after,
         v_execution_commit_state,
         v_execution_commit_ref,
         v_execution_committed_at_utc;

    v_submitted_state_finalised := COALESCE(v_provider_boundary_crossed, false) IS TRUE
      AND v_execution_commit_state IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED');

    IF COALESCE(v_provider_boundary_crossed, false) IS TRUE
      AND COALESCE(v_submitted_state_finalised, false) IS NOT TRUE
      AND upper(BTRIM(COALESCE(v_batch_status_after, ''))) NOT IN ('SETTLED', 'CANCELLED', 'FAILED', 'BLOCKED_FUNDS') THEN
      v_local_finalisation_error := 'PROVIDER_ACCEPTED_LOCAL_BATCH_FINALISATION_NOT_APPLIED';
    ELSE
      v_local_finalisation_error := NULL::text;
    END IF;
  ELSE
  v_submission_evidence_json := public.pay_batch_submission_evidence(p_pay_batch_id, false, NULL::uuid, NULL::uuid);
  v_provider_submitted_count := coalesce((v_submission_evidence_json->>'provider_submitted_count')::integer, 0);
  v_local_only_count := coalesce((v_submission_evidence_json->>'local_only_count')::integer, coalesce((v_submission_evidence_json->>'local_idempotency_only_count')::integer, 0));
  v_failed_count := coalesce((v_submission_evidence_json->>'failed_count')::integer, 0);
  v_pending_count := coalesce((v_submission_evidence_json->>'pending_count')::integer, 0);
  v_ambiguous_count := coalesce((v_submission_evidence_json->>'ambiguous_count')::integer, 0);
  v_attempted_but_unproven_count := coalesce((v_submission_evidence_json->>'attempted_but_unproven_count')::integer, 0);
  v_provider_attempt_without_external_id_count := coalesce((v_submission_evidence_json->>'provider_attempt_without_external_id_count')::integer, 0);
  v_remaining_submit_attempt_required := coalesce((v_submission_evidence_json->>'remaining_submit_attempt_required')::integer, 0);
  v_remaining_provider_evidence_required := coalesce((v_submission_evidence_json->>'remaining_provider_evidence_required')::integer, 0);
  v_remaining_unsubmitted_count := v_remaining_submit_attempt_required;
  v_requires_provider_poll := lower(btrim(coalesce(v_submission_evidence_json->>'requires_provider_poll', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_requires_review := lower(btrim(coalesce(v_submission_evidence_json->>'requires_review', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_can_mark_submitted := lower(btrim(coalesce(v_submission_evidence_json->>'can_mark_submitted', v_submission_evidence_json->>'batch_can_be_marked_submitted', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');
  v_can_mark_committed := lower(btrim(coalesce(v_submission_evidence_json->>'can_mark_committed', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on');

  IF v_can_mark_committed THEN
    v_execution_commit_state := 'COMMITTED';
  ELSIF v_can_mark_submitted THEN
    v_execution_commit_state := 'SUBMITTED_NOT_COMMITTED';
  ELSE
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  IF v_execution_commit_state IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    SELECT COALESCE(
             NULLIF(BTRIM(COALESCE(reference_event.provider_event_id, '')), ''),
             NULLIF(BTRIM(COALESCE(reference_event.provider_reference, '')), ''),
             CASE
               WHEN lower(btrim(coalesce(reference_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_tx_id, '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_tx_id, '')), '') <> ALL(ARRAY_REMOVE(ARRAY[
                  COALESCE(reference_transfer.id::text, '__no_transfer_id__'),
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.request_id, '')), ''), '__no_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''), '__no_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_provider_diag_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''), '__no_bulk_reference__')
                ]::text[], NULL::text))
                 THEN NULLIF(BTRIM(COALESCE(reference_transfer.rail_tx_id, '')), '')
               ELSE NULL::text
             END,
             CASE
               WHEN lower(btrim(coalesce(reference_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_event_id', '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_event_id', '')), '') <> ALL(ARRAY_REMOVE(ARRAY[
                  COALESCE(reference_transfer.id::text, '__no_transfer_id__'),
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.request_id, '')), ''), '__no_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''), '__no_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_provider_diag_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''), '__no_bulk_reference__')
                ]::text[], NULL::text))
                 THEN NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_event_id', '')), '')
               ELSE NULL::text
             END,
             CASE
               WHEN lower(btrim(coalesce(reference_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_reference', '')), '') IS NOT NULL
                AND NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_reference', '')), '') <> ALL(ARRAY_REMOVE(ARRAY[
                  COALESCE(reference_transfer.id::text, '__no_transfer_id__'),
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.request_id, '')), ''), '__no_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''), '__no_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_provider_diag_local_provider_request_id__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                  COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''), '__no_bulk_reference__')
                ]::text[], NULL::text))
                 THEN NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json->>'provider_reference', '')), '')
               ELSE NULL::text
             END
           )
    INTO v_execution_commit_ref
    FROM public.pay_bank_transfers AS reference_transfer
    LEFT JOIN LATERAL (
      SELECT event_row.provider_event_id,
             event_row.provider_reference
      FROM public.pay_bank_transfer_events AS event_row
      WHERE event_row.pay_bank_transfer_id = reference_transfer.id
        AND upper(BTRIM(COALESCE(event_row.event_source, ''))) IN ('PROVIDER_RESPONSE', 'PROVIDER_POLL', 'PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY', 'WEBHOOK', 'POLL', 'RAIL_PROVIDER', 'PROVIDER', 'PROVIDER_SETTLEMENT')
        AND upper(BTRIM(COALESCE(event_row.normalised_state, event_row.provider_state, event_row.raw_payload #>> '{provider_submit_diagnostic,provider_state}', ''))) NOT IN ('REJECTED', 'FAILED', 'ERROR', 'DECLINED', 'CANCELLED', 'CANCELED', 'MALFORMED', 'UNKNOWN')
        AND upper(BTRIM(COALESCE(event_row.raw_payload #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN ('PROVIDER_SUBMISSION_REJECTED', 'PROVIDER_SUBMISSION_FAILED', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL', 'NO_PROVIDER_SUBMISSION_ATTEMPTED', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID')
        AND EXISTS (
          SELECT 1
          FROM (VALUES
            (event_row.provider_event_id),
            (event_row.provider_reference),
            (event_row.raw_payload #>> '{provider_event_id}'),
            (event_row.raw_payload #>> '{provider_reference}'),
            (event_row.raw_payload #>> '{provider_submission_id}'),
            (event_row.raw_payload #>> '{submission_id}'),
            (event_row.raw_payload #>> '{rail_submission_id}'),
            (event_row.raw_payload #>> '{provider_payment_id}'),
            (event_row.raw_payload #>> '{payment_id}'),
            (event_row.raw_payload #>> '{external_payment_id}'),
            (event_row.raw_payload #>> '{revolut_payment_id}'),
            (event_row.raw_payload #>> '{provider_transfer_id}'),
            (event_row.raw_payload #>> '{transfer_id}'),
            (event_row.raw_payload #>> '{external_transfer_id}'),
            (event_row.raw_payload #>> '{provider_transaction_id}'),
            (event_row.raw_payload #>> '{transaction_id}')
          ) AS reference_event_identifier(identifier_value)
          WHERE NULLIF(BTRIM(COALESCE(reference_event_identifier.identifier_value, '')), '') IS NOT NULL
            AND NULLIF(BTRIM(COALESCE(reference_event_identifier.identifier_value, '')), '') <> ALL(ARRAY_REMOVE(ARRAY[
              COALESCE(reference_transfer.id::text, '__no_transfer_id__'),
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
              COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.request_id, '')), ''), '__no_request_id__'),
              COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''), '__no_local_provider_request_id__'),
              COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_provider_diag_local_provider_request_id__'),
              COALESCE(NULLIF(BTRIM(COALESCE(event_row.raw_payload #>> '{local_provider_request_id}', '')), ''), '__no_event_local_provider_request_id__'),
              COALESCE(NULLIF(BTRIM(COALESCE(event_row.raw_payload #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_event_provider_diag_local_provider_request_id__'),
              COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
              COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''), '__no_bulk_reference__')
            ]::text[], NULL::text))
        )
      ORDER BY event_row.received_at_utc DESC NULLS LAST, event_row.id DESC
      LIMIT 1
    ) AS reference_event ON TRUE
    WHERE reference_transfer.pay_batch_id = p_pay_batch_id
      AND (
        reference_event.provider_event_id IS NOT NULL
        OR reference_event.provider_reference IS NOT NULL
        OR (
          lower(btrim(coalesce(reference_transfer.rail_meta_json #>> '{last_update_provider_evidence}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
          AND EXISTS (
            SELECT 1
            FROM (VALUES
              (reference_transfer.rail_tx_id),
              (reference_transfer.rail_meta_json->>'provider_event_id'),
              (reference_transfer.rail_meta_json->>'provider_reference')
            ) AS reference_identifier(identifier_value)
            WHERE NULLIF(BTRIM(COALESCE(reference_identifier.identifier_value, '')), '') IS NOT NULL
              AND NULLIF(BTRIM(COALESCE(reference_identifier.identifier_value, '')), '') <> ALL(ARRAY_REMOVE(ARRAY[
                COALESCE(reference_transfer.id::text, '__no_transfer_id__'),
                 CASE WHEN p_operation_id IS NULL THEN NULL::text ELSE p_operation_id::text END,
                 CASE WHEN p_chunk_id IS NULL THEN NULL::text ELSE p_chunk_id::text END,
                COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.request_id, '')), ''), '__no_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{local_provider_request_id}', '')), ''), '__no_local_provider_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.rail_meta_json #>> '{provider_submit_diagnostic,local_provider_request_id}', '')), ''), '__no_provider_diag_local_provider_request_id__'),
                COALESCE(NULLIF(BTRIM(COALESCE(reference_transfer.payment_reference, '')), ''), '__no_payment_reference__'),
                COALESCE(NULLIF(BTRIM(COALESCE(v_batch_row.bulk_reference, '')), ''), '__no_bulk_reference__')
              ]::text[], NULL::text))
          )
        )
      )
    ORDER BY reference_transfer.completed_at_utc DESC NULLS LAST, reference_transfer.id DESC
    LIMIT 1;
  ELSE
    v_execution_commit_ref := NULL::text;
  END IF;

  IF v_execution_commit_state = 'COMMITTED' THEN
    SELECT COALESCE(committed_transfer.completed_at_utc, v_now)
    INTO v_execution_committed_at_utc
    FROM public.pay_bank_transfers AS committed_transfer
    WHERE committed_transfer.pay_batch_id = p_pay_batch_id
      AND (
        upper(COALESCE(committed_transfer.status, '')) IN ('COMPLETED', 'SETTLED', 'PAID')
        OR committed_transfer.completed_at_utc IS NOT NULL
      )
    ORDER BY committed_transfer.completed_at_utc DESC NULLS LAST, committed_transfer.id DESC
    LIMIT 1;
  ELSE
    v_execution_committed_at_utc := NULL::timestamptz;
  END IF;

  UPDATE public.pay_batches AS batch_update
  SET last_status_checked_at_utc = v_now,
      execution_commit_state = v_execution_commit_state,
      execution_commit_ref = CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
      execution_committed_at_utc = CASE WHEN v_execution_commit_state = 'COMMITTED' THEN COALESCE(v_execution_committed_at_utc, v_now) ELSE NULL::timestamptz END
  WHERE batch_update.id = p_pay_batch_id
  RETURNING upper(BTRIM(COALESCE(batch_update.status, ''))),
            upper(BTRIM(COALESCE(batch_update.execution_commit_state, 'NOT_SUBMITTED'))),
            batch_update.execution_commit_ref,
            batch_update.execution_committed_at_utc
  INTO v_batch_status_after,
       v_execution_commit_state,
       v_execution_commit_ref,
       v_execution_committed_at_utc;
  END IF;

  IF v_is_scoped IS NOT TRUE THEN
    SELECT
      COUNT(*) FILTER (
        WHERE update_row.is_provider_evidence IS TRUE
           OR (
             update_row.money_is_final_money_moved IS TRUE
             AND (
               update_row.is_provider_source IS TRUE
               OR update_row.provider_response_present IS TRUE
               OR update_row.provider_response_received IS TRUE
               OR update_row.is_provider_external_evidence IS TRUE
               OR update_row.provider_acceptance_evidence_present IS TRUE
             )
           )
      )::integer,
      COUNT(*) FILTER (WHERE update_row.is_provider_external_evidence IS TRUE)::integer,
      COUNT(*) FILTER (WHERE update_row.provider_response_present IS TRUE OR update_row.provider_response_received IS TRUE OR update_row.is_provider_source IS TRUE)::integer,
      COUNT(*) FILTER (WHERE update_row.provider_request_sent IS TRUE OR update_row.provider_response_present IS TRUE OR update_row.provider_response_received IS TRUE OR update_row.is_provider_source IS TRUE OR update_row.is_provider_evidence IS TRUE)::integer,
      COUNT(*) FILTER (WHERE update_row.provider_submission_unknown IS TRUE OR update_row.is_attempted_but_unproven IS TRUE OR update_row.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID'))::integer,
      COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
        'transfer_id', update_row.transfer_id::text,
        'provider_submission_status', update_row.provider_submission_status,
        'provider_request_sent', update_row.provider_request_sent OR update_row.provider_request_sent_confirmed,
        'provider_request_sent_confirmed', update_row.provider_request_sent_confirmed,
        'provider_request_dispatched_at_utc', update_row.provider_request_dispatched_at_utc,
        'provider_response_received', update_row.provider_response_received,
        'provider_response_present', update_row.provider_response_present,
        'provider_external_evidence_present', update_row.is_provider_external_evidence,
        'provider_acceptance_evidence_present', (
          update_row.is_provider_evidence IS TRUE
          OR (
            update_row.money_is_final_money_moved IS TRUE
            AND (
              update_row.is_provider_source IS TRUE
              OR update_row.provider_response_present IS TRUE
              OR update_row.provider_response_received IS TRUE
              OR update_row.is_provider_external_evidence IS TRUE
              OR update_row.provider_acceptance_evidence_present IS TRUE
            )
          )
        ),
        'rail_tx_id', CASE WHEN update_row.is_provider_evidence IS TRUE THEN update_row.rail_tx_id ELSE NULL::text END,
        'rail_state', update_row.rail_state,
        'provider_http_status', update_row.provider_http_status,
        'provider_error_code', update_row.provider_error_code,
        'request_id', update_row.request_id,
        'idempotency_key', update_row.idempotency_key,
        'money_cash_state', update_row.money_cash_state,
        'money_normalised_transfer_status', update_row.money_normalised_transfer_status,
        'money_is_final_money_moved', update_row.money_is_final_money_moved,
        'money_is_terminal_no_money', update_row.money_is_terminal_no_money,
        'money_is_pending_non_final', update_row.money_is_pending_non_final,
        'money_completed_at_allowed', update_row.money_completed_at_allowed,
        'money_reason', update_row.money_reason,
        'money_support_details_json', update_row.money_support_details_json,
        'payment_lifecycle_state', CASE
          WHEN update_row.money_is_final_money_moved IS TRUE THEN 'PAID_OR_SETTLED'
          WHEN update_row.money_is_terminal_no_money IS TRUE THEN 'PROVIDER_FAILED_NO_MONEY'
          WHEN update_row.money_is_pending_non_final IS TRUE THEN 'PROVIDER_SUBMITTED_PENDING'
          WHEN update_row.provider_submission_unknown IS TRUE OR update_row.is_attempted_but_unproven IS TRUE THEN 'PROVIDER_OUTCOME_UNKNOWN'
          ELSE NULL::text
        END,
        'manual_resolution_required', update_row.manual_resolution_required,
        'safe_retry_available', update_row.safe_retry_available
      )) ORDER BY update_row.row_seq), '[]'::jsonb)
    INTO v_provider_acceptance_evidence_count,
         v_provider_external_evidence_count,
         v_provider_response_present_count,
         v_provider_request_sent_count,
         v_provider_submission_unknown_count,
         v_transfer_provider_outcomes
    FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row;

    SELECT COALESCE(update_row.provider_submit_diagnostic, '{}'::jsonb)
    INTO v_provider_submit_diagnostic
    FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row
    ORDER BY CASE
        WHEN update_row.provider_submission_status = 'PROVIDER_SUBMISSION_ACCEPTED' AND update_row.is_provider_evidence IS TRUE THEN 0
        WHEN update_row.provider_submission_status = 'PROVIDER_SUBMISSION_REJECTED' THEN 1
        WHEN update_row.provider_submission_status IN ('UNKNOWN_PROVIDER_SUBMISSION_OUTCOME', 'PROVIDER_SUBMISSION_UNKNOWN_STALE_CHUNK', 'PROVIDER_SUBMISSION_MALFORMED_RESPONSE', 'PROVIDER_SUBMISSION_ATTEMPTED_NO_EXTERNAL_ID') THEN 2
        ELSE 3
      END,
      update_row.row_seq
    LIMIT 1;

    v_summary_json := public.pay_batch_execution_summary_get(p_pay_batch_id, p_actor_user_id);
  END IF;

  IF p_chunk_id IS NOT NULL THEN
    UPDATE public.banking_pay_operation_chunks AS chunk_update
    SET result_json = jsonb_strip_nulls(COALESCE(chunk_update.result_json, '{}'::jsonb) || jsonb_build_object(
          'updated_count', v_updated_count,
          'provider_submitted_count', v_provider_submitted_count,
          'local_idempotency_only_count', v_local_only_count,
          'local_only_count', v_local_only_count,
          'failed_count', v_failed_count,
          'pending_count', v_pending_count,
          'ambiguous_count', v_ambiguous_count,
          'attempted_but_unproven_count', v_attempted_but_unproven_count,
          'provider_attempt_without_external_id_count', v_provider_attempt_without_external_id_count,
          'remaining_submit_attempt_required', v_remaining_submit_attempt_required,
          'remaining_provider_evidence_required', v_remaining_provider_evidence_required,
          'remaining_unsubmitted_count', v_remaining_unsubmitted_count,
          'requires_provider_poll', v_requires_provider_poll,
          'requires_review', v_requires_review,
          'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
          'transfer_provider_outcomes', COALESCE(v_transfer_provider_outcomes, '[]'::jsonb),
          'provider_submission_status', COALESCE(v_provider_submit_diagnostic->>'provider_submission_status', NULL),
          'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
          'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
          'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
          'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
          'batch_execution_state', jsonb_build_object(
            'submitted_state_finalisation_attempted', COALESCE(v_submitted_state_finalisation_attempted, false),
            'submitted_state_finalised', COALESCE(v_submitted_state_finalised, false),
            'batch_status_before', v_batch_status_before,
            'batch_status_after', v_batch_status_after,
            'execution_commit_state_before', v_execution_commit_state_before,
            'execution_commit_state_after', v_execution_commit_state,
            'execution_commit_ref_selected', CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
            'execution_committed_at_utc', CASE WHEN v_execution_commit_state = 'COMMITTED' THEN COALESCE(v_execution_committed_at_utc, v_now)::text ELSE NULL END,
            'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
            'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
            'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
            'remaining_submit_attempt_required', COALESCE(v_remaining_submit_attempt_required, 0),
            'requires_review', COALESCE(v_requires_review, false),
            'local_finalisation_error', v_local_finalisation_error
          ),
          'counterparty_not_found_recovery_count', COALESCE(v_counterparty_map_recovery_count, 0),
          'counterparty_not_found_invalidated_map_count', COALESCE(v_counterparty_map_invalidated_count, 0),
          'counterparty_not_found_auto_reverse_requested_count', COALESCE(v_counterparty_map_auto_reverse_requested_count, 0),
          'counterparty_not_found_auto_reverse_applied_count', COALESCE(v_counterparty_map_auto_reverse_applied_count, 0),
          'counterparty_not_found_manual_recoverable_count', COALESCE(v_counterparty_map_manual_recoverable_count, 0),
          'counterparty_not_found_recoveries', COALESCE(v_counterparty_map_recovery_json, '[]'::jsonb),
          'counterparty_not_found_readiness_enqueue', COALESCE(v_counterparty_map_readiness_enqueue_json, '[]'::jsonb)
        )),
        updated_at_utc = v_now
    WHERE chunk_update.id = p_chunk_id
      AND (p_operation_id IS NULL OR chunk_update.operation_id = p_operation_id);
  END IF;

  SELECT COALESCE(jsonb_agg(DISTINCT to_jsonb(update_row.provider_failure_reason_group) ORDER BY to_jsonb(update_row.provider_failure_reason_group)) FILTER (WHERE update_row.provider_failure_reason_group IS NOT NULL), '[]'::jsonb)
  INTO v_provider_failure_reason_groups_json
  FROM pg_temp.tmp_pay_bank_transfer_updates AS update_row;

  v_alert_signal_required := COALESCE(v_failed_count, 0) > 0
    OR COALESCE(v_ambiguous_count, 0) > 0
    OR COALESCE(v_provider_submission_unknown_count, 0) > 0
    OR COALESCE(v_counterparty_map_recovery_count, 0) > 0
    OR EXISTS (
      SELECT 1
      FROM pg_temp.tmp_pay_bank_transfer_updates AS alert_update
      WHERE alert_update.money_is_terminal_no_money IS TRUE
         OR alert_update.provider_failure_reason_group IS NOT NULL
    );

  v_live_signal_result := public.banking_pay_batch_signal_touch(
    p_pay_batch_id,
    'PAY_BANK_TRANSFERS_APPLY_RAIL_UPDATES',
    'pay_bank_transfers_apply_rail_updates',
    jsonb_strip_nulls(jsonb_build_object(
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
      'updated_count', COALESCE(v_updated_count, 0),
      'event_result_count', COALESCE(v_event_result_count, 0),
      'provider_failure_reason_groups_json', COALESCE(v_provider_failure_reason_groups_json, '[]'::jsonb),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'pending_count', COALESCE(v_pending_count, 0)
    )),
    true,
    false,
    COALESCE(v_alert_signal_required, false),
    true
  );

  RETURN (
    jsonb_build_object(
      'ok', true,
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'chunk_id', CASE WHEN p_chunk_id IS NULL THEN NULL ELSE p_chunk_id::text END,
      'server_utc', v_now,
      'input_count', v_input_count,
      'updated_count', v_updated_count,
      'event_result_count', v_event_result_count,
      'provider_submitted_count', v_provider_submitted_count,
      'local_idempotency_only_count', v_local_only_count,
      'local_only_count', v_local_only_count,
      'failed_count', v_failed_count,
      'pending_count', v_pending_count,
      'ambiguous_count', v_ambiguous_count,
      'attempted_but_unproven_count', v_attempted_but_unproven_count,
      'provider_attempt_without_external_id_count', v_provider_attempt_without_external_id_count,
      'remaining_submit_attempt_required', v_remaining_submit_attempt_required,
      'remaining_provider_evidence_required', v_remaining_provider_evidence_required,
      'remaining_unsubmitted_count', v_remaining_unsubmitted_count,
      'requires_provider_poll', v_requires_provider_poll,
      'requires_review', v_requires_review
    )
    || jsonb_build_object(
      'provider_submit_diagnostic', COALESCE(v_provider_submit_diagnostic, '{}'::jsonb),
      'transfer_provider_outcomes', COALESCE(v_transfer_provider_outcomes, '[]'::jsonb),
      'provider_submission_status', COALESCE(v_provider_submit_diagnostic->>'provider_submission_status', NULL),
      'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
      'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
      'provider_response_present_count', COALESCE(v_provider_response_present_count, 0),
      'provider_request_sent_count', COALESCE(v_provider_request_sent_count, 0),
      'provider_submission_unknown_count', COALESCE(v_provider_submission_unknown_count, 0),
      'provider_failure_reason_groups_json', COALESCE(v_provider_failure_reason_groups_json, '[]'::jsonb),
      'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
      'submitted_state_finalisation_attempted', COALESCE(v_submitted_state_finalisation_attempted, false),
      'submitted_state_finalised', COALESCE(v_submitted_state_finalised, false),
      'batch_status_before', v_batch_status_before,
      'batch_status_after', v_batch_status_after,
      'execution_commit_state_before', v_execution_commit_state_before,
      'execution_commit_state_after', v_execution_commit_state,
      'execution_commit_ref_selected', CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
      'provider_transfer_total', v_provider_transfer_total,
      'local_finalisation_error', v_local_finalisation_error
    )
    || jsonb_build_object(
      'counterparty_not_found_recovery_count', COALESCE(v_counterparty_map_recovery_count, 0),
      'counterparty_not_found_invalidated_map_count', COALESCE(v_counterparty_map_invalidated_count, 0),
      'counterparty_not_found_auto_reverse_requested_count', COALESCE(v_counterparty_map_auto_reverse_requested_count, 0),
      'counterparty_not_found_auto_reverse_applied_count', COALESCE(v_counterparty_map_auto_reverse_applied_count, 0),
      'counterparty_not_found_manual_recoverable_count', COALESCE(v_counterparty_map_manual_recoverable_count, 0),
      'counterparty_not_found_recoveries', COALESCE(v_counterparty_map_recovery_json, '[]'::jsonb),
      'counterparty_not_found_readiness_enqueue', COALESCE(v_counterparty_map_readiness_enqueue_json, '[]'::jsonb),
      'blocked_funds_state', COALESCE(v_summary_json->'blocked_funds_state', '{}'::jsonb),
      'missing_transfer_ids', v_missing,
      'duplicate_transfer_ids', v_duplicates,
      'live_signal', COALESCE(v_live_signal_result, '{}'::jsonb),
      'alert_signal_required', COALESCE(v_alert_signal_required, false)
    )
    || jsonb_build_object(
      'batch_execution_state', jsonb_build_object(
        'submitted_state_finalisation_attempted', COALESCE(v_submitted_state_finalisation_attempted, false),
        'submitted_state_finalised', COALESCE(v_submitted_state_finalised, false),
        'batch_status_before', v_batch_status_before,
        'batch_status_after', v_batch_status_after,
        'execution_commit_state_before', v_execution_commit_state_before,
        'execution_commit_state_after', v_execution_commit_state,
        'execution_commit_ref_selected', CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
        'provider_boundary_crossed', COALESCE(v_provider_boundary_crossed, false),
        'provider_acceptance_evidence_count', COALESCE(v_provider_acceptance_evidence_count, 0),
        'provider_external_evidence_count', COALESCE(v_provider_external_evidence_count, 0),
        'remaining_submit_attempt_required', COALESCE(v_remaining_submit_attempt_required, 0),
        'requires_review', COALESCE(v_requires_review, false),
        'local_finalisation_error', v_local_finalisation_error,
        'execution_commit_state', v_execution_commit_state,
        'execution_commit_ref', CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
        'execution_committed_at_utc', CASE WHEN v_execution_commit_state = 'COMMITTED' THEN COALESCE(v_execution_committed_at_utc, v_now)::text ELSE NULL END,
        'summary', v_summary_json,
        'submission_evidence', v_submission_evidence_json
      ),
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref', CASE WHEN v_execution_commit_state = 'NOT_SUBMITTED' THEN NULL ELSE v_execution_commit_ref END,
      'execution_committed_at_utc', CASE WHEN v_execution_commit_state = 'COMMITTED' THEN COALESCE(v_execution_committed_at_utc, v_now)::text ELSE NULL END
    )
  );
END;
$function$;






drop function if exists public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text);

DROP FUNCTION IF EXISTS public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text);
DROP FUNCTION IF EXISTS public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text, text, date, text, boolean, boolean, boolean, text, text);
DROP FUNCTION IF EXISTS public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text, text, date, text, boolean, boolean, boolean, text, text, uuid, text);


DROP FUNCTION IF EXISTS public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text, text, date, text, boolean, boolean, boolean, text, text, uuid, text);
DROP FUNCTION IF EXISTS public.pay_batch_auth_start(uuid, text, timestamptz, text, jsonb, uuid, text, text, date, text, boolean, boolean, boolean, text, text, uuid, text, text);





CREATE OR REPLACE FUNCTION public.pay_batch_auth_start(
  p_pay_batch_id uuid,
  p_schedule_kind text,
  p_scheduled_at_utc timestamptz,
  p_funding_account_ref text,
  p_warning_hours_json jsonb,
  p_actor_user_id uuid,
  p_actor_intent text DEFAULT NULL::text,
  p_execution_mode text DEFAULT 'STANDARD_BANK'::text,
  p_payment_date date DEFAULT NULL::date,
  p_pay_channel_scope text DEFAULT 'ALL'::text,
  p_suppress_remittances boolean DEFAULT false,
  p_suppress_remittances_confirmed boolean DEFAULT false,
  p_csv_uploaded_confirmed boolean DEFAULT false,
  p_csv_bank_confirm_ref text DEFAULT NULL::text,
  p_external_settlement_comment text DEFAULT NULL::text,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_idempotency_key text DEFAULT NULL::text,
  p_freshness_result_hash text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now timestamptz := now();
  v_kind text := upper(btrim(coalesce(p_schedule_kind, '')));
  v_intent text := upper(btrim(coalesce(p_actor_intent, '')));
  v_execution_mode text := upper(btrim(coalesce(p_execution_mode, 'STANDARD_BANK')));
  v_pay_channel_scope text := upper(btrim(coalesce(p_pay_channel_scope, 'ALL')));
  v_actor_row record;
  v_batch_row public.pay_batches%ROWTYPE;
  v_cfg_row public.settings_defaults%ROWTYPE;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_prepare_json jsonb := '{}'::jsonb;
  v_summary_json jsonb := '{}'::jsonb;
  v_existing_auth_id uuid := NULL::uuid;
  v_existing_auth_state text := NULL::text;
  v_existing_auth_intent_json jsonb := '{}'::jsonb;
  v_existing_auth_operation_id text := NULL::text;
  v_existing_auth_idempotency_key text := NULL::text;
  v_conflicting_auth_id uuid := NULL::uuid;
  v_conflicting_auth_state text := NULL::text;
  v_conflicting_auth_operation_id text := NULL::text;
  v_conflicting_auth_idempotency_key text := NULL::text;
  v_requested_idempotency_key text := NULL::text;
  v_effective_freshness_result_hash text := NULL::text;
  v_effective_freshness_scope_hash text := NULL::text;
  v_auth_id uuid := NULL::uuid;
  v_auth_state text := 'AWAITING';
  v_required_quantity integer := 1;
  v_use_golden_key boolean := false;
  v_payment_date date := p_payment_date;
  v_scheduled_at_utc timestamptz := NULL::timestamptz;
  v_funding_account_ref text := NULL::text;
  v_warning_hours_json jsonb := '[]'::jsonb;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_next_required_phase text := 'WAIT_FOR_AUTHORISATION';
  v_ready boolean := false;
  v_blocker_count integer := 0;
  v_pending_transfer_count integer := 0;
  v_authorisation_ready_transfer_count integer := 0;
  v_local_only_transfer_count integer := 0;
  v_provider_attempt_or_evidence_transfer_count integer := 0;
  v_provider_or_ambiguous_evidence_transfer_count integer := 0;
  v_blocked_transfer_count integer := 0;
  v_canonical_pending_status_transfer_count integer := 0;
  v_scoped_operation_scope_count integer := 0;
  v_scoped_scope_prepared_count integer := 0;
  v_scoped_scope_failed_count integer := 0;
  v_scoped_scope_skipped_count integer := 0;
  v_scoped_scope_without_transfer_count integer := 0;
  v_non_cancellable_auth_request_count integer := 0;
  v_auth_request_retry_blocker_count integer := 0;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_auth_start_path text := 'FULL_PREPARE_PATH';
  v_used_operation_scope_proof boolean := false;
  v_provider_submit_chunk_risk_count integer := 0;
  v_operation_provider_submit_marker_count integer := 0;
  v_transfer_amount_mismatch_count integer := 0;
  v_transfer_currency_mismatch_count integer := 0;
  v_transfer_status_not_pending_count integer := 0;
  v_transfer_external_state_count integer := 0;
  v_transfer_identity_mismatch_count integer := 0;
  v_auth_freshness_json jsonb := '{}'::jsonb;
  v_auth_carry_forward_freshness_json jsonb := '{}'::jsonb;
  v_auth_carry_forward_blocker_count integer := 0;
  v_auth_freshness_blocker_reasons jsonb := '[]'::jsonb;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: pay_batch_id is required';
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user_id is required';
  END IF;

  IF v_kind NOT IN ('IMMEDIATE', 'SCHEDULED') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid schedule_kind (IMMEDIATE|SCHEDULED)';
  END IF;

  IF v_pay_channel_scope NOT IN ('PAYE', 'UMBRELLA', 'ALL', 'LOANS') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid pay_channel_scope';
  END IF;

  IF v_execution_mode NOT IN ('STANDARD_BANK', 'BANK', 'CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN
    RAISE EXCEPTION 'pay_batch_auth_start: invalid execution_mode';
  END IF;

  v_requested_idempotency_key := nullif(btrim(coalesce(p_idempotency_key, '')), '');

  SELECT actor_user.id,
         actor_user.is_active,
         actor_user.payment_authoriser,
         actor_user.payment_golden_key
  INTO v_actor_row
  FROM public.tms_users AS actor_user
  WHERE actor_user.id = p_actor_user_id;

  IF v_actor_row.id IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user not found';
  END IF;

  IF coalesce(v_actor_row.is_active, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user is not active';
  END IF;

  IF coalesce(v_actor_row.payment_authoriser, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user must be a payment authoriser';
  END IF;

  v_use_golden_key := v_intent = 'USE_GOLDEN_KEY';
  IF v_use_golden_key AND coalesce(v_actor_row.payment_golden_key, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: actor_user does not have payment golden key';
  END IF;

  SELECT batch_row.*
  INTO v_batch_row
  FROM public.pay_batches AS batch_row
  WHERE batch_row.id = p_pay_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_auth_start: pay_batch not found';
  END IF;

  IF p_operation_id IS NOT NULL THEN
    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'banking_pay_operations row % not found', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'operation % belongs to a different actor', p_operation_id;
    END IF;
  END IF;

  v_execution_commit_state := upper(btrim(coalesce(v_batch_row.execution_commit_state, 'NOT_SUBMITTED')));
  IF v_execution_commit_state NOT IN ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') THEN
    v_execution_commit_state := 'NOT_SUBMITTED';
  END IF;

  IF v_execution_commit_state <> 'NOT_SUBMITTED' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has already crossed the execution submission boundary and cannot be authorised again.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state
    )::text;
  END IF;

  IF NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL
     OR v_batch_row.execution_committed_at_utc IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'EXECUTION_STATE_CONFLICT',
      'message', 'This payment batch has provider submission or execution commit evidence and cannot be authorised again.',
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_execution_commit_state,
      'execution_commit_ref_present', NULLIF(BTRIM(COALESCE(v_batch_row.execution_commit_ref, '')), '') IS NOT NULL,
      'execution_committed_at_utc_present', v_batch_row.execution_committed_at_utc IS NOT NULL
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT settings_default.*
  INTO v_cfg_row
  FROM public.settings_defaults AS settings_default
  WHERE settings_default.id = 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'pay_batch_auth_start: settings_defaults missing (id=1)';
  END IF;

  v_required_quantity := GREATEST(1, coalesce(v_cfg_row.payment_authoriser_quantity, 1));
  v_warning_hours_json := CASE WHEN p_warning_hours_json IS NOT NULL THEN p_warning_hours_json ELSE coalesce(v_cfg_row.funds_warning_hours_json, '[]'::jsonb) END;

  IF v_warning_hours_json IS NOT NULL AND jsonb_typeof(v_warning_hours_json) <> 'array' THEN
    RAISE EXCEPTION 'pay_batch_auth_start: warning_hours_json must be a JSON array';
  END IF;

  v_payment_date := coalesce(v_payment_date, v_batch_row.authoritative_payment_date, v_batch_row.pay_date);
  IF v_payment_date IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: payment_date is required';
  END IF;

  IF v_kind = 'SCHEDULED' THEN
    IF p_scheduled_at_utc IS NULL THEN
      RAISE EXCEPTION 'pay_batch_auth_start: scheduled_at_utc is required when schedule_kind=SCHEDULED';
    END IF;
    v_scheduled_at_utc := p_scheduled_at_utc;
  ELSE
    v_scheduled_at_utc := v_now;
  END IF;

  v_funding_account_ref := nullif(btrim(coalesce(p_funding_account_ref, '')), '');
  v_funding_account_ref := coalesce(v_funding_account_ref, nullif(btrim(coalesce(v_batch_row.funding_account_ref, '')), ''), nullif(btrim(coalesce(v_cfg_row.rail_default_funding_account_ref, '')), ''));

  IF v_execution_mode IN ('STANDARD_BANK', 'BANK') AND v_funding_account_ref IS NULL THEN
    RAISE EXCEPTION 'pay_batch_auth_start: funding_account_ref is required for bank execution';
  END IF;

  IF coalesce(p_suppress_remittances, false) AND coalesce(p_suppress_remittances_confirmed, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'pay_batch_auth_start: suppress_remittances requires explicit user confirmation';
  END IF;

  IF p_operation_id IS NOT NULL AND v_execution_mode IN ('STANDARD_BANK', 'BANK') THEN
    v_effective_freshness_result_hash := nullif(btrim(coalesce(p_freshness_result_hash, v_batch_row.freshness_result_hash, v_operation_row.progress_json->>'freshness_result_hash', '')), '');
    v_effective_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, v_operation_row.progress_json->>'freshness_scope_hash', '')), '');

    IF nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch freshness result hash is required before operation-scoped bank authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'batch_freshness_result_hash_present', false
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_TYPE_NOT_SUPPORTED_FOR_AUTH_START_FAST_PATH',
        'message', 'Operation-scoped payment authorisation can only use a payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_type', v_operation_row.operation_type
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_operation_row.status, ''))) NOT IN ('QUEUED', 'RUNNING') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_NOT_ACTIVE_FOR_AUTH_START',
        'message', 'Operation-scoped payment authorisation requires an active payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_status', v_operation_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_batch_row.status, ''))) <> 'DRAFT' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Only a draft payment batch can be authorised for execution.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'batch_status', v_batch_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(p_freshness_result_hash, '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Payment freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'provided_freshness_result_hash', nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Operation freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_freshness_result_hash', nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NULL
       OR upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))) <> 'PASSED'
       OR coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false) IS TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch freshness must be passed and non-stale before authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_batch_row.freshness_validation_status,
        'freshness_result_hash_present', nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NOT NULL,
        'freshness_is_stale', coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false)
      )::text USING ERRCODE = 'P0001';
    END IF;
  END IF;

  ---------------------------------------------------------------------------
  -- Final pre-authorisation freshness gate.
  -- Policy X: this is post-draft validation, so it validates frozen batch
  -- artifacts and carry-forward state only. It must not consume, reserve, or
  -- reinterpret carry-forwards, and it must not use provider evidence to decide
  -- cancellation availability.
  ---------------------------------------------------------------------------
  v_auth_freshness_json := public.pay_batch_validate_freshness(
    p_pay_batch_id,
    p_actor_user_id,
    true
  );

  v_auth_carry_forward_freshness_json := public._pay_manual_adjustment_carry_forward_freshness_check(
    p_pay_batch_id,
    NULL::uuid[],
    NULL::uuid[],
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'surface', 'pay_batch_auth_start',
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'idempotency_key_present', v_requested_idempotency_key IS NOT NULL
    ),
    p_actor_user_id
  );

  v_auth_carry_forward_blocker_count := jsonb_array_length(
    CASE
      WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
        THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
      ELSE '[]'::jsonb
    END
  );

  SELECT COALESCE(jsonb_agg(DISTINCT reason_rows.reason_text ORDER BY reason_rows.reason_text), '[]'::jsonb)
  INTO v_auth_freshness_blocker_reasons
  FROM (
    SELECT stale_reason_values.reason_text
    FROM jsonb_array_elements_text(
      CASE
        WHEN jsonb_typeof(v_auth_freshness_json->'stale_reasons') = 'array'
          THEN COALESCE(v_auth_freshness_json->'stale_reasons', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS stale_reason_values(reason_text)

    UNION ALL

    SELECT CASE
      WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'MANUAL_ADJUSTMENT_CARRY_FORWARD_CONSUMED_ELSEWHERE'
        THEN 'Manual adjustment carry-forward was consumed elsewhere'
      WHEN COALESCE(carry_forward_blockers.blocker_value->>'code', '') = 'SOURCE_PAYMENT_SCOPE_BECAME_PAID_OR_SETTLED'
        THEN 'Source payment scope changed'
      ELSE 'Manual adjustment carry-forward changed'
    END AS reason_text
    FROM jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(v_auth_carry_forward_freshness_json->'blockers') = 'array'
          THEN COALESCE(v_auth_carry_forward_freshness_json->'blockers', '[]'::jsonb)
        ELSE '[]'::jsonb
      END
    ) AS carry_forward_blockers(blocker_value)
  ) AS reason_rows
  WHERE NULLIF(BTRIM(COALESCE(reason_rows.reason_text, '')), '') IS NOT NULL;

  IF LOWER(COALESCE(v_auth_freshness_json->>'is_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
     OR COALESCE(v_auth_carry_forward_blocker_count, 0) > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'PAY_BATCH_STALE',
      'message', 'Payment batch freshness is stale and must be refreshed before authorisation can start.',
      'pay_batch_id', p_pay_batch_id::text,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'stale_reasons', COALESCE(v_auth_freshness_blocker_reasons, '[]'::jsonb),
      'freshness_result', COALESCE(v_auth_freshness_json, '{}'::jsonb),
      'carry_forward_freshness_result', COALESCE(v_auth_carry_forward_freshness_json, '{}'::jsonb)
    )::text USING ERRCODE = 'P0001';
  END IF;

  PERFORM 1
  FROM public.pay_batch_auth_requests AS auth_request_lock
  WHERE auth_request_lock.pay_batch_id = p_pay_batch_id
    AND auth_request_lock.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
  FOR UPDATE OF auth_request_lock;

  SELECT auth_request.id,
         auth_request.state,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') AS existing_operation_id,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') AS existing_idempotency_key
  INTO v_conflicting_auth_id,
       v_conflicting_auth_state,
       v_conflicting_auth_operation_id,
       v_conflicting_auth_idempotency_key
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
    AND (
      auth_request.state = 'PENDING_AUTHORISATION'
      OR NOT (
        (
          p_operation_id IS NOT NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
        )
        OR (
          v_requested_idempotency_key IS NOT NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key
        )
        OR (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') IS NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') IS NULL
        )
      )
    )
  ORDER BY auth_request.created_at_utc DESC NULLS LAST,
           auth_request.id DESC
  LIMIT 1;

  IF v_conflicting_auth_id IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
      'message', 'An active authorisation request already belongs to another payment execution attempt or is in a non-reusable authorisation state. Review or reconcile that authorisation request before retrying.',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', v_conflicting_auth_id::text,
      'auth_request_state', v_conflicting_auth_state,
      'auth_request_operation_id', v_conflicting_auth_operation_id,
      'auth_request_idempotency_key_present', v_conflicting_auth_idempotency_key IS NOT NULL,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'idempotency_key_present', v_requested_idempotency_key IS NOT NULL
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT auth_request.id,
         auth_request.state,
         coalesce(auth_request.execution_intent_json, '{}'::jsonb),
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') AS existing_operation_id,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') AS existing_idempotency_key
  INTO v_existing_auth_id,
       v_existing_auth_state,
       v_existing_auth_intent_json,
       v_existing_auth_operation_id,
       v_existing_auth_idempotency_key
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state IN ('AWAITING', 'AUTHORISED')
    AND (
      (
        p_operation_id IS NOT NULL
        AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
      )
      OR (
        v_requested_idempotency_key IS NOT NULL
        AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key
      )
    )
  ORDER BY
    CASE
      WHEN p_operation_id IS NOT NULL
       AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text THEN 0
      WHEN v_requested_idempotency_key IS NOT NULL
       AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key THEN 1
      ELSE 2
    END,
    auth_request.created_at_utc DESC NULLS LAST,
    auth_request.id DESC
  LIMIT 1;

  IF v_existing_auth_id IS NOT NULL
     AND NOT (p_operation_id IS NOT NULL AND v_execution_mode IN ('STANDARD_BANK', 'BANK')) THEN
    v_execution_intent_json := coalesce(v_existing_auth_intent_json, '{}'::jsonb);
    v_auth_state := v_existing_auth_state;
    v_execution_mode := upper(btrim(coalesce(
      v_execution_intent_json->>'execution_mode',
      v_execution_intent_json->>'mode',
      v_execution_mode
    )));
    IF v_execution_mode NOT IN ('STANDARD_BANK', 'BANK', 'CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN
      v_execution_mode := upper(btrim(coalesce(p_execution_mode, 'STANDARD_BANK')));
    END IF;
    v_kind := upper(btrim(coalesce(v_execution_intent_json->>'schedule_kind', v_kind)));
    IF v_kind NOT IN ('IMMEDIATE', 'SCHEDULED') THEN
      v_kind := upper(btrim(coalesce(p_schedule_kind, '')));
    END IF;
    v_next_required_phase := CASE
      WHEN v_auth_state = 'AUTHORISED' AND v_execution_mode IN ('CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'SETTLEMENT'
      WHEN v_auth_state = 'AUTHORISED' AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
      WHEN v_auth_state = 'AUTHORISED' THEN 'SUBMIT_PROVIDER_TRANSFERS'
      ELSE 'WAIT_FOR_AUTHORISATION'
    END;

    RETURN jsonb_build_object(
      'ok', true,
      'idempotent_reuse', true,
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', v_existing_auth_id::text,
      'auth_state', v_auth_state,
      'operation_id', v_execution_intent_json->>'operation_id',
      'idempotency_key', v_execution_intent_json->>'idempotency_key',
      'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
      'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
      'next_required_phase', v_next_required_phase,
      'execution_mode', v_execution_mode,
      'schedule_kind', v_kind,
      'auth_request_reuse_reason', CASE
        WHEN p_operation_id IS NOT NULL AND v_existing_auth_operation_id = p_operation_id::text THEN 'SAME_OPERATION'
        WHEN v_requested_idempotency_key IS NOT NULL AND v_existing_auth_idempotency_key = v_requested_idempotency_key THEN 'SAME_IDEMPOTENCY_KEY'
        ELSE 'SAFE_AUTH_REQUEST_REUSE'
      END,
      'execution_intent_json', v_execution_intent_json
    );
  END IF;

  v_existing_auth_id := NULL::uuid;
  v_existing_auth_state := NULL::text;
  v_existing_auth_intent_json := '{}'::jsonb;
  v_existing_auth_operation_id := NULL::text;
  v_existing_auth_idempotency_key := NULL::text;

  IF p_operation_id IS NOT NULL AND v_execution_mode IN ('STANDARD_BANK', 'BANK') THEN
    v_auth_start_path := 'OPERATION_SCOPED_FAST_PATH';
    v_used_operation_scope_proof := true;

    IF upper(btrim(coalesce(v_operation_row.operation_type, ''))) NOT IN ('PAYMENT_EXECUTE', 'PAYMENT_RETRY_BLOCKED_FUNDS') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_TYPE_NOT_SUPPORTED_FOR_AUTH_START_FAST_PATH',
        'message', 'Operation-scoped payment authorisation can only use a payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_type', v_operation_row.operation_type
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_operation_row.status, ''))) NOT IN ('QUEUED', 'RUNNING') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'OPERATION_NOT_ACTIVE_FOR_AUTH_START',
        'message', 'Operation-scoped payment authorisation requires an active payment execution operation.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_status', v_operation_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_effective_freshness_result_hash := nullif(btrim(coalesce(p_freshness_result_hash, v_batch_row.freshness_result_hash, v_operation_row.progress_json->>'freshness_result_hash', '')), '');
    v_effective_freshness_scope_hash := nullif(btrim(coalesce(v_batch_row.freshness_scope_hash, v_operation_row.progress_json->>'freshness_scope_hash', '')), '');

    IF nullif(btrim(coalesce(p_freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(p_freshness_result_hash, '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Payment freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'provided_freshness_result_hash', nullif(btrim(coalesce(p_freshness_result_hash, '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') IS NOT NULL
       AND nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), '') <> nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'FRESHNESS_RESULT_HASH_MISMATCH',
        'message', 'Operation freshness proof does not match the batch freshness result.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'operation_freshness_result_hash', nullif(btrim(coalesce(v_operation_row.progress_json->>'freshness_result_hash', '')), ''),
        'batch_freshness_result_hash', nullif(btrim(coalesce(v_batch_row.freshness_result_hash, '')), '')
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF upper(btrim(coalesce(v_batch_row.status, ''))) <> 'DRAFT' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Only a draft payment batch can be authorised for execution.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'batch_status', v_batch_row.status
      )::text USING ERRCODE = 'P0001';
    END IF;

    IF nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NULL
       OR upper(btrim(coalesce(v_batch_row.freshness_validation_status, ''))) <> 'PASSED'
       OR coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false) IS TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch freshness must be passed and non-stale before authorisation can start.',
        'pay_batch_id', p_pay_batch_id::text,
        'operation_id', p_operation_id::text,
        'freshness_validation_status', v_batch_row.freshness_validation_status,
        'freshness_result_hash_present', nullif(btrim(coalesce(v_effective_freshness_result_hash, '')), '') IS NOT NULL,
        'freshness_is_stale', coalesce((v_batch_row.freshness_result_json->>'is_stale')::boolean, false)
      )::text USING ERRCODE = 'P0001';
    END IF;

    PERFORM 1
    FROM public.banking_pay_operation_transfer_scope AS operation_scope_lock
    WHERE operation_scope_lock.pay_batch_id = p_pay_batch_id
      AND operation_scope_lock.operation_id = p_operation_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR upper(btrim(coalesce(operation_scope_lock.pay_channel, ''))) = v_pay_channel_scope
      )
    FOR UPDATE OF operation_scope_lock;

    PERFORM 1
    FROM public.banking_pay_operation_transfer_scope AS operation_scope_lock
    JOIN public.pay_bank_transfers AS linked_transfer_lock
      ON linked_transfer_lock.id = operation_scope_lock.pay_bank_transfer_id
     AND linked_transfer_lock.pay_batch_id = operation_scope_lock.pay_batch_id
    WHERE operation_scope_lock.pay_batch_id = p_pay_batch_id
      AND operation_scope_lock.operation_id = p_operation_id
      AND (
        v_pay_channel_scope IN ('ALL', 'ANY', '*')
        OR upper(btrim(coalesce(operation_scope_lock.pay_channel, ''))) = v_pay_channel_scope
      )
    FOR UPDATE OF linked_transfer_lock;

    SELECT
      count(*)::integer,
      count(*) FILTER (WHERE scoped_transfer.scope_status_upper = 'PREPARED')::integer,
      count(*) FILTER (WHERE scoped_transfer.scope_status_upper = 'FAILED')::integer,
      count(*) FILTER (WHERE scoped_transfer.scope_status_upper = 'SKIPPED')::integer,
      count(*) FILTER (
        WHERE scoped_transfer.pay_bank_transfer_id IS NULL
           OR scoped_transfer.linked_transfer_id IS NULL
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.scope_status_upper = 'PREPARED'
          AND scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.transfer_status_upper = 'PENDING'
          AND scoped_transfer.identity_matches IS TRUE
          AND scoped_transfer.amount_matches IS TRUE
          AND scoped_transfer.currency_matches IS TRUE
          AND scoped_transfer.has_external_transfer_state IS NOT TRUE
          AND scoped_transfer.has_provider_attempt_or_evidence IS NOT TRUE
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.scope_status_upper = 'PREPARED'
          AND scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.transfer_status_upper = 'PENDING'
          AND scoped_transfer.identity_matches IS TRUE
          AND scoped_transfer.amount_matches IS TRUE
          AND scoped_transfer.currency_matches IS TRUE
          AND scoped_transfer.has_external_transfer_state IS NOT TRUE
          AND scoped_transfer.has_provider_attempt_or_evidence IS NOT TRUE
      )::integer,
      count(*) FILTER (WHERE scoped_transfer.has_provider_attempt_or_evidence IS TRUE)::integer,
      count(*) FILTER (
        WHERE scoped_transfer.has_provider_attempt_or_evidence IS TRUE
           OR scoped_transfer.has_external_transfer_state IS TRUE
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.transfer_status_upper = 'PENDING'
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.transfer_status_upper <> 'PENDING'
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.identity_matches IS NOT TRUE
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.amount_matches IS NOT TRUE
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.linked_transfer_id IS NOT NULL
          AND scoped_transfer.currency_matches IS NOT TRUE
      )::integer,
      count(*) FILTER (
        WHERE scoped_transfer.has_external_transfer_state IS TRUE
      )::integer
    INTO v_scoped_operation_scope_count,
         v_scoped_scope_prepared_count,
         v_scoped_scope_failed_count,
         v_scoped_scope_skipped_count,
         v_scoped_scope_without_transfer_count,
         v_authorisation_ready_transfer_count,
         v_local_only_transfer_count,
         v_provider_attempt_or_evidence_transfer_count,
         v_provider_or_ambiguous_evidence_transfer_count,
         v_canonical_pending_status_transfer_count,
         v_transfer_status_not_pending_count,
         v_transfer_identity_mismatch_count,
         v_transfer_amount_mismatch_count,
         v_transfer_currency_mismatch_count,
         v_transfer_external_state_count
    FROM (
      SELECT scoped_base.*,
             (
               scoped_base.linked_transfer_id IS NOT NULL
               AND scoped_base.transfer_pay_channel = scoped_base.scope_pay_channel
               AND scoped_base.transfer_group_key = scoped_base.scope_transfer_group_key
               AND scoped_base.transfer_pay_batch_id = scoped_base.scope_pay_batch_id
             ) AS identity_matches,
             (
               scoped_base.linked_transfer_id IS NOT NULL
               AND coalesce(scoped_base.transfer_amount, 0) = coalesce(scoped_base.scope_amount, 0)
             ) AS amount_matches,
             (
               scoped_base.linked_transfer_id IS NOT NULL
               AND upper(btrim(coalesce(scoped_base.transfer_currency, 'GBP'))) = upper(btrim(coalesce(scoped_base.scope_currency, 'GBP')))
             ) AS currency_matches,
             (
               nullif(btrim(coalesce(scoped_base.transfer_rail_tx_id, '')), '') IS NOT NULL
               OR scoped_base.transfer_completed_at_utc IS NOT NULL
               OR nullif(btrim(coalesce(scoped_base.transfer_failed_reason, '')), '') IS NOT NULL
               OR upper(btrim(coalesce(scoped_base.transfer_rail_state, ''))) NOT IN ('', 'LOCAL', 'PENDING')
             ) AS has_external_transfer_state,
             (
               scoped_base.has_transfer_event_evidence IS TRUE
               OR scoped_base.has_provider_submit_marker IS TRUE
             ) AS has_provider_attempt_or_evidence
      FROM (
        SELECT operation_scope.id AS scope_id,
               operation_scope.pay_batch_id AS scope_pay_batch_id,
               operation_scope.operation_id AS scope_operation_id,
               operation_scope.pay_channel AS scope_pay_channel,
               operation_scope.transfer_group_key AS scope_transfer_group_key,
               operation_scope.amount AS scope_amount,
               operation_scope.currency AS scope_currency,
               operation_scope.status AS scope_status,
               upper(btrim(coalesce(operation_scope.status, ''))) AS scope_status_upper,
               operation_scope.pay_bank_transfer_id,
               linked_transfer.id AS linked_transfer_id,
               linked_transfer.pay_batch_id AS transfer_pay_batch_id,
               linked_transfer.pay_channel AS transfer_pay_channel,
               linked_transfer.transfer_group_key AS transfer_group_key,
               linked_transfer.amount AS transfer_amount,
               linked_transfer.currency AS transfer_currency,
               linked_transfer.status AS transfer_status,
               upper(btrim(coalesce(linked_transfer.status, ''))) AS transfer_status_upper,
               linked_transfer.rail_tx_id AS transfer_rail_tx_id,
               linked_transfer.rail_state AS transfer_rail_state,
               linked_transfer.completed_at_utc AS transfer_completed_at_utc,
               linked_transfer.failed_reason AS transfer_failed_reason,
               linked_transfer.rail_meta_json AS transfer_rail_meta_json,
               EXISTS (
                 SELECT 1
                 FROM public.pay_bank_transfer_events AS transfer_event
                 WHERE transfer_event.pay_batch_id = p_pay_batch_id
                   AND (
                     transfer_event.pay_bank_transfer_id = linked_transfer.id
                     OR (
                       transfer_event.pay_bank_transfer_id IS NULL
                       AND linked_transfer.id IS NOT NULL
                       AND (
                         NULLIF(BTRIM(COALESCE(transfer_event.provider_reference, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                           linked_transfer.id::text,
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.payment_reference, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{payment_reference}', '')), '')
                         ]::text[], NULL::text))
                         OR NULLIF(BTRIM(COALESCE(transfer_event.provider_event_id, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                           linked_transfer.id::text,
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.payment_reference, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{payment_reference}', '')), '')
                         ]::text[], NULL::text))
                         OR NULLIF(BTRIM(COALESCE(transfer_event.idempotency_key, '')), '') = ANY(ARRAY_REMOVE(ARRAY[
                           linked_transfer.id::text,
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.payment_reference, '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{request_id}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{idempotency_key}', '')), ''),
                           NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{payment_reference}', '')), '')
                         ]::text[], NULL::text))
                         OR EXISTS (
                           SELECT 1
                           FROM (VALUES
                             (linked_transfer.id::text),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.rail_tx_id, '')), '')),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.request_id, '')), '')),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.payment_reference, '')), '')),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{request_id}', '')), '')),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{idempotency_key}', '')), '')),
                             (NULLIF(BTRIM(COALESCE(linked_transfer.rail_meta_json #>> '{payment_reference}', '')), ''))
                           ) AS transfer_event_identity(identity_value)
                           WHERE LENGTH(NULLIF(BTRIM(COALESCE(transfer_event_identity.identity_value, '')), '')) >= 8
                             AND POSITION(lower(NULLIF(BTRIM(COALESCE(transfer_event_identity.identity_value, '')), '')) IN lower(COALESCE(transfer_event.raw_payload::text, ''))) > 0
                         )
                       )
                     )
                   )
                 LIMIT 1
               ) AS has_transfer_event_evidence,
               (
                 lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_attempted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR lower(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
                 OR nullif(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', '')), '') IS NOT NULL
                    AND upper(btrim(coalesce(linked_transfer.rail_meta_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN (
                      'NO_PROVIDER_SUBMISSION_ATTEMPTED',
                      'CLAIMED_NOT_PROVIDER_CALLED_YET',
                      'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
                    )
               ) AS has_provider_submit_marker
        FROM public.banking_pay_operation_transfer_scope AS operation_scope
        LEFT JOIN public.pay_bank_transfers AS linked_transfer
          ON linked_transfer.id = operation_scope.pay_bank_transfer_id
         AND linked_transfer.pay_batch_id = operation_scope.pay_batch_id
        WHERE operation_scope.pay_batch_id = p_pay_batch_id
          AND operation_scope.operation_id = p_operation_id
          AND (
            v_pay_channel_scope IN ('ALL', 'ANY', '*')
            OR upper(btrim(coalesce(operation_scope.pay_channel, ''))) = v_pay_channel_scope
          )
      ) AS scoped_base
    ) AS scoped_transfer;

    SELECT count(*)::integer
    INTO v_provider_submit_chunk_risk_count
    FROM public.banking_pay_operation_chunks AS provider_submit_chunk
    WHERE provider_submit_chunk.operation_id = p_operation_id
      AND (
        provider_submit_chunk.phase = 'SUBMIT_PROVIDER_TRANSFERS'
        OR provider_submit_chunk.chunk_type = 'TRANSFER_SUBMIT'
      );

    SELECT CASE
      WHEN NULLIF(BTRIM(COALESCE(v_operation_row.progress_json->>'last_provider_submit_chunk_id', '')), '') IS NOT NULL THEN 1
      WHEN jsonb_typeof(v_operation_row.progress_json->'provider_submit_claim_diagnostic') = 'object' THEN 1
      WHEN jsonb_typeof(v_operation_row.progress_json->'provider_submit_diagnostic') = 'object'
       AND (
         lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_request_sent}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_request_sent_confirmed}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_response_received}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_response_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_submission_attempted}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR lower(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_acceptance_evidence_present}', 'false'))) IN ('true', 't', '1', 'yes', 'y', 'on')
         OR upper(BTRIM(COALESCE(v_operation_row.progress_json #>> '{provider_submit_diagnostic,provider_submission_status}', ''))) NOT IN (
           '',
           'NO_PROVIDER_SUBMISSION_ATTEMPTED',
           'CLAIMED_NOT_PROVIDER_CALLED_YET',
           'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
         )
       ) THEN 1
      WHEN jsonb_typeof(v_operation_row.progress_json->'provider_submit_claim_diagnostic_events') = 'array'
       AND jsonb_array_length(v_operation_row.progress_json->'provider_submit_claim_diagnostic_events') > 0 THEN 1
      WHEN upper(BTRIM(COALESCE(v_operation_row.progress_json->>'provider_submission_status', ''))) NOT IN (
        '',
        'NO_PROVIDER_SUBMISSION_ATTEMPTED',
        'CLAIMED_NOT_PROVIDER_CALLED_YET',
        'PROVIDER_SUBMISSION_BLOCKED_PRE_CALL'
      ) THEN 1
      ELSE 0
    END::integer
    INTO v_operation_provider_submit_marker_count;

    v_provider_submit_chunk_risk_count := COALESCE(v_provider_submit_chunk_risk_count, 0) + COALESCE(v_operation_provider_submit_marker_count, 0);

    v_provider_attempt_or_evidence_transfer_count := COALESCE(v_provider_attempt_or_evidence_transfer_count, 0) + COALESCE(v_provider_submit_chunk_risk_count, 0);
    v_provider_or_ambiguous_evidence_transfer_count := COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) + COALESCE(v_provider_submit_chunk_risk_count, 0);
    v_blocked_transfer_count := COALESCE(v_scoped_operation_scope_count, 0) - COALESCE(v_authorisation_ready_transfer_count, 0);

    IF COALESCE(v_scoped_operation_scope_count, 0) <= 0
       OR COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
       OR COALESCE(v_scoped_scope_failed_count, 0) <> 0
       OR COALESCE(v_scoped_scope_skipped_count, 0) <> 0
       OR COALESCE(v_scoped_scope_without_transfer_count, 0) <> 0
       OR COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
       OR COALESCE(v_provider_submit_chunk_risk_count, 0) <> 0
       OR COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) <> 0
       OR COALESCE(v_transfer_status_not_pending_count, 0) <> 0
       OR COALESCE(v_transfer_identity_mismatch_count, 0) <> 0
       OR COALESCE(v_transfer_amount_mismatch_count, 0) <> 0
       OR COALESCE(v_transfer_currency_mismatch_count, 0) <> 0
       OR COALESCE(v_transfer_external_state_count, 0) <> 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'NO_AUTHORISATION_READY_TRANSFERS' END,
        'message', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'One or more scoped transfers have provider submission evidence or ambiguous provider state and must be reviewed before authorisation can continue.' ELSE 'All scoped transfer groups must be prepared, local-only, and authorisation-ready before authorisation can start.' END,
        'pay_batch_id', p_pay_batch_id::text,
        'pay_channel_scope', v_pay_channel_scope,
        'operation_id', p_operation_id::text,
        'auth_start_path', v_auth_start_path,
        'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
        'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
        'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
        'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
        'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
        'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
        'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
        'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
        'provider_submit_chunk_risk_count', COALESCE(v_provider_submit_chunk_risk_count, 0),
        'operation_provider_submit_marker_count', COALESCE(v_operation_provider_submit_marker_count, 0),
        'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0),
        'transfer_status_not_pending_count', COALESCE(v_transfer_status_not_pending_count, 0),
        'transfer_identity_mismatch_count', COALESCE(v_transfer_identity_mismatch_count, 0),
        'transfer_amount_mismatch_count', COALESCE(v_transfer_amount_mismatch_count, 0),
        'transfer_currency_mismatch_count', COALESCE(v_transfer_currency_mismatch_count, 0),
        'transfer_external_state_count', COALESCE(v_transfer_external_state_count, 0)
      )::text USING ERRCODE = 'P0001';
    END IF;

    v_ready := true;
    v_blocker_count := 0;
    v_pending_transfer_count := COALESCE(v_authorisation_ready_transfer_count, 0);
    v_prepare_json := jsonb_build_object(
      'ready', true,
      'ready_flag', true,
      'blocker_count', 0,
      'blockers', '[]'::jsonb,
      'auth_start_path', v_auth_start_path,
      'pay_batch_prepare_skipped', true,
      'used_operation_scope_proof', true,
      'freshness', jsonb_strip_nulls(jsonb_build_object(
        'status', v_batch_row.freshness_validation_status,
        'is_stale', false,
        'freshness_result_hash', v_effective_freshness_result_hash,
        'freshness_scope_hash', v_effective_freshness_scope_hash,
        'freshness_checked_at_utc', CASE WHEN v_batch_row.freshness_checked_at_utc IS NULL THEN NULL ELSE v_batch_row.freshness_checked_at_utc::text END
      )),
      'execution_summary', jsonb_build_object(
        'pending_transfer_count', COALESCE(v_pending_transfer_count, 0),
        'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
        'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
        'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
        'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0)
      )
    );
  ELSE
    v_prepare_json := public.pay_batch_prepare(
      p_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id,
      p_operation_id => p_operation_id,
      p_freshness_result_hash => p_freshness_result_hash
    );
    v_ready := coalesce((v_prepare_json->>'ready')::boolean, false);
    v_blocker_count := coalesce(NULLIF(v_prepare_json->>'blocker_count', '')::integer, 0);
    v_effective_freshness_result_hash := nullif(btrim(coalesce(p_freshness_result_hash, v_prepare_json #>> '{freshness,freshness_result_hash}', '')), '');
    v_effective_freshness_scope_hash := nullif(btrim(coalesce(v_prepare_json #>> '{freshness,freshness_scope_hash}', '')), '');

    IF v_ready IS NOT TRUE THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_BATCH_AUTH_START',
        'code', 'PAY_BATCH_NOT_READY',
        'message', 'Payment batch is not ready for authorisation.',
        'pay_batch_id', p_pay_batch_id::text,
        'blocker_count', v_blocker_count,
        'blockers', coalesce(v_prepare_json->'blockers', '[]'::jsonb)
      )::text;
    END IF;

    v_summary_json := coalesce(v_prepare_json->'execution_summary', public.pay_batch_execution_summary_get(p_pay_batch_id, p_actor_user_id));
    v_pending_transfer_count := coalesce(NULLIF(v_summary_json->>'pending_transfer_count', '')::integer, 0);

    IF v_execution_mode IN ('STANDARD_BANK', 'BANK') THEN
      SELECT
        count(*) FILTER (WHERE classified_transfer.is_authorisation_ready)::integer,
        count(*) FILTER (WHERE classified_transfer.evidence_classification = 'local_only_evidence')::integer,
        count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt)::integer,
        count(*) FILTER (WHERE classified_transfer.has_provider_submission_evidence OR classified_transfer.has_provider_event_evidence OR classified_transfer.has_provider_attempt_without_external_id OR classified_transfer.has_operation_submit_attempt OR classified_transfer.has_ambiguous_external_evidence)::integer,
        count(*) FILTER (WHERE classified_transfer.is_failed_or_blocked)::integer,
        count(*) FILTER (WHERE classified_transfer.status_upper = 'PENDING')::integer,
        count(DISTINCT classified_transfer.auth_request_id) FILTER (
          WHERE classified_transfer.auth_request_id IS NOT NULL
            AND classified_transfer.has_non_cancellable_auth_request IS TRUE
        )::integer,
        count(DISTINCT classified_transfer.auth_request_id) FILTER (
          WHERE classified_transfer.auth_request_id IS NOT NULL
            AND (
              classified_transfer.has_non_cancellable_auth_request IS TRUE
              OR classified_transfer.has_auth_request_provider_risk IS TRUE
              OR classified_transfer.has_other_operation_active_auth_request IS TRUE
            )
        )::integer
      INTO v_authorisation_ready_transfer_count,
           v_local_only_transfer_count,
           v_provider_attempt_or_evidence_transfer_count,
           v_provider_or_ambiguous_evidence_transfer_count,
           v_blocked_transfer_count,
           v_canonical_pending_status_transfer_count,
           v_non_cancellable_auth_request_count,
           v_auth_request_retry_blocker_count
      FROM public.pay_bank_transfer_execution_classify(
        p_pay_batch_id => p_pay_batch_id,
        p_pay_channel_scope => v_pay_channel_scope,
        p_operation_id => p_operation_id,
        p_include_unscoped_transfers => CASE WHEN p_operation_id IS NULL THEN true ELSE false END
      ) AS classified_transfer;

      IF p_operation_id IS NOT NULL THEN
        SELECT count(*)::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'PREPARED')::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'FAILED')::integer,
               count(*) FILTER (WHERE upper(btrim(coalesce(operation_scope.status, ''))) = 'SKIPPED')::integer,
               count(*) FILTER (WHERE operation_scope.pay_bank_transfer_id IS NULL)::integer
        INTO v_scoped_operation_scope_count,
             v_scoped_scope_prepared_count,
             v_scoped_scope_failed_count,
             v_scoped_scope_skipped_count,
             v_scoped_scope_without_transfer_count
        FROM public.banking_pay_operation_transfer_scope AS operation_scope
        WHERE operation_scope.pay_batch_id = p_pay_batch_id
          AND operation_scope.operation_id = p_operation_id
          AND (
            v_pay_channel_scope IN ('ALL', 'ANY', '*')
            OR upper(btrim(coalesce(operation_scope.pay_channel, ''))) = v_pay_channel_scope
          );
      END IF;

      IF COALESCE(v_non_cancellable_auth_request_count, 0) > 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
          'message', 'An active authorisation request is not safe to reuse or cancel automatically for this payment execution attempt.',
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
          'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
          'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF p_operation_id IS NOT NULL
         AND (
           COALESCE(v_scoped_operation_scope_count, 0) <= 0
           OR COALESCE(v_scoped_scope_prepared_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
           OR COALESCE(v_scoped_scope_failed_count, 0) <> 0
           OR COALESCE(v_scoped_scope_skipped_count, 0) <> 0
           OR COALESCE(v_scoped_scope_without_transfer_count, 0) <> 0
           OR COALESCE(v_authorisation_ready_transfer_count, 0) <> COALESCE(v_scoped_operation_scope_count, 0)
         ) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'NO_AUTHORISATION_READY_TRANSFERS' END,
          'message', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'One or more scoped transfers have provider submission evidence or ambiguous provider state and must be reviewed before authorisation can continue.' ELSE 'All scoped transfer groups must be prepared and authorisation-ready before authorisation can start.' END,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'operation_id', p_operation_id::text,
          'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
          'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
          'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
          'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
          'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;

      IF p_operation_id IS NULL AND COALESCE(v_authorisation_ready_transfer_count, 0) <= 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_BATCH_AUTH_START',
          'code', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'BANK_TRANSFER_PROVIDER_REVIEW_REQUIRED' ELSE 'NO_AUTHORISATION_READY_TRANSFERS' END,
          'message', CASE WHEN COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0) > 0 THEN 'One or more transfers have provider submission evidence or ambiguous provider state and must be reviewed before authorisation can continue.' ELSE 'No safe locally prepared transfers are available for authorisation.' END,
          'pay_batch_id', p_pay_batch_id::text,
          'pay_channel_scope', v_pay_channel_scope,
          'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
          'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
          'local_only_transfer_count', COALESCE(v_local_only_transfer_count, 0),
          'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
          'provider_or_ambiguous_evidence_transfer_count', COALESCE(v_provider_or_ambiguous_evidence_transfer_count, 0),
          'blocked_transfer_count', COALESCE(v_blocked_transfer_count, 0)
        )::text USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;

  v_execution_intent_json := jsonb_strip_nulls(jsonb_build_object(
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'idempotency_key', v_requested_idempotency_key,
    'freshness_result_hash', v_effective_freshness_result_hash,
    'freshness_scope_hash', v_effective_freshness_scope_hash,
    'execution_mode', v_execution_mode,
    'payment_date', v_payment_date::text,
    'pay_channel_scope', v_pay_channel_scope,
    'schedule_kind', v_kind,
    'scheduled_at_utc', CASE WHEN v_scheduled_at_utc IS NULL THEN NULL ELSE v_scheduled_at_utc::text END,
    'funding_account_ref', v_funding_account_ref,
    'suppress_remittances', coalesce(p_suppress_remittances, false),
    'suppress_remittances_confirmed', coalesce(p_suppress_remittances_confirmed, false),
    'csv_uploaded_confirmed', coalesce(p_csv_uploaded_confirmed, false),
    'csv_bank_confirm_ref', nullif(btrim(coalesce(p_csv_bank_confirm_ref, '')), ''),
    'external_settlement_comment', nullif(btrim(coalesce(p_external_settlement_comment, '')), ''),
    'auth_start_path', v_auth_start_path,
    'pay_batch_prepare_skipped', v_used_operation_scope_proof,
    'used_operation_scope_proof', v_used_operation_scope_proof
  ));

  SELECT auth_request.id,
         auth_request.state,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') AS existing_operation_id,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') AS existing_idempotency_key
  INTO v_conflicting_auth_id,
       v_conflicting_auth_state,
       v_conflicting_auth_operation_id,
       v_conflicting_auth_idempotency_key
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state IN ('AWAITING', 'PENDING_AUTHORISATION', 'AUTHORISED')
    AND (
      auth_request.state = 'PENDING_AUTHORISATION'
      OR NOT (
        (
          p_operation_id IS NOT NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
        )
        OR (
          v_requested_idempotency_key IS NOT NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key
        )
        OR (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') IS NULL
          AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') IS NULL
          AND upper(btrim(coalesce(auth_request.schedule_kind, ''))) = v_kind
          AND (
            v_kind <> 'SCHEDULED'
            OR auth_request.scheduled_at_utc = v_scheduled_at_utc
          )
          AND (
            (v_execution_mode NOT IN ('STANDARD_BANK', 'BANK') AND nullif(btrim(coalesce(auth_request.funding_account_ref, '')), '') IS NULL)
            OR nullif(btrim(coalesce(auth_request.funding_account_ref, '')), '') = v_funding_account_ref
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'execution_mode', auth_request.execution_intent_json->>'mode', '')), '') IS NULL
            OR upper(btrim(coalesce(auth_request.execution_intent_json->>'execution_mode', auth_request.execution_intent_json->>'mode', ''))) = v_execution_mode
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'pay_channel_scope', auth_request.execution_intent_json->>'payChannelScope', '')), '') IS NULL
            OR upper(btrim(coalesce(auth_request.execution_intent_json->>'pay_channel_scope', auth_request.execution_intent_json->>'payChannelScope', ''))) = v_pay_channel_scope
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'schedule_kind', '')), '') IS NULL
            OR upper(btrim(coalesce(auth_request.execution_intent_json->>'schedule_kind', ''))) = v_kind
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'payment_date', '')), '') IS NULL
            OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'payment_date', '')), '') = v_payment_date::text
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'funding_account_ref', '')), '') IS NULL
            OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'funding_account_ref', '')), '') = v_funding_account_ref
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_result_hash', '')), '') IS NULL
            OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_result_hash', '')), '') = v_effective_freshness_result_hash
          )
          AND (
            nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_scope_hash', '')), '') IS NULL
            OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_scope_hash', '')), '') = v_effective_freshness_scope_hash
          )
        )
      )
    )
  ORDER BY auth_request.created_at_utc DESC NULLS LAST,
           auth_request.id DESC
  LIMIT 1;

  IF v_conflicting_auth_id IS NOT NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_BATCH_AUTH_START',
      'code', 'AUTH_REQUEST_HELD_BY_PREVIOUS_OPERATION',
      'message', 'An active authorisation request already belongs to another payment execution attempt, is in a non-reusable authorisation state, or has execution intent that is not safe to attach to this attempt. Review or reconcile that authorisation request before retrying.',
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', v_conflicting_auth_id::text,
      'auth_request_state', v_conflicting_auth_state,
      'auth_request_operation_id', v_conflicting_auth_operation_id,
      'auth_request_idempotency_key_present', v_conflicting_auth_idempotency_key IS NOT NULL,
      'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
      'idempotency_key_present', v_requested_idempotency_key IS NOT NULL
    )::text USING ERRCODE = 'P0001';
  END IF;

  SELECT auth_request.id,
         auth_request.state,
         coalesce(auth_request.execution_intent_json, '{}'::jsonb),
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') AS existing_operation_id,
         nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') AS existing_idempotency_key
  INTO v_existing_auth_id,
       v_existing_auth_state,
       v_existing_auth_intent_json,
       v_existing_auth_operation_id,
       v_existing_auth_idempotency_key
  FROM public.pay_batch_auth_requests AS auth_request
  WHERE auth_request.pay_batch_id = p_pay_batch_id
    AND auth_request.state IN ('AWAITING', 'AUTHORISED')
    AND (
      (
        p_operation_id IS NOT NULL
        AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text
      )
      OR (
        v_requested_idempotency_key IS NOT NULL
        AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key
      )
      OR (
        nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') IS NULL
        AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') IS NULL
        AND upper(btrim(coalesce(auth_request.schedule_kind, ''))) = v_kind
        AND (
          v_kind <> 'SCHEDULED'
          OR auth_request.scheduled_at_utc = v_scheduled_at_utc
        )
        AND (
          (v_execution_mode NOT IN ('STANDARD_BANK', 'BANK') AND nullif(btrim(coalesce(auth_request.funding_account_ref, '')), '') IS NULL)
          OR nullif(btrim(coalesce(auth_request.funding_account_ref, '')), '') = v_funding_account_ref
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'execution_mode', auth_request.execution_intent_json->>'mode', '')), '') IS NULL
          OR upper(btrim(coalesce(auth_request.execution_intent_json->>'execution_mode', auth_request.execution_intent_json->>'mode', ''))) = v_execution_mode
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'pay_channel_scope', auth_request.execution_intent_json->>'payChannelScope', '')), '') IS NULL
          OR upper(btrim(coalesce(auth_request.execution_intent_json->>'pay_channel_scope', auth_request.execution_intent_json->>'payChannelScope', ''))) = v_pay_channel_scope
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'schedule_kind', '')), '') IS NULL
          OR upper(btrim(coalesce(auth_request.execution_intent_json->>'schedule_kind', ''))) = v_kind
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'payment_date', '')), '') IS NULL
          OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'payment_date', '')), '') = v_payment_date::text
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'funding_account_ref', '')), '') IS NULL
          OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'funding_account_ref', '')), '') = v_funding_account_ref
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_result_hash', '')), '') IS NULL
          OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_result_hash', '')), '') = v_effective_freshness_result_hash
        )
        AND (
          nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_scope_hash', '')), '') IS NULL
          OR nullif(btrim(coalesce(auth_request.execution_intent_json->>'freshness_scope_hash', '')), '') = v_effective_freshness_scope_hash
        )
      )
    )
  ORDER BY
    CASE
      WHEN p_operation_id IS NOT NULL
       AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'operation_id', '')), '') = p_operation_id::text THEN 0
      WHEN v_requested_idempotency_key IS NOT NULL
       AND nullif(btrim(coalesce(auth_request.execution_intent_json->>'idempotency_key', '')), '') = v_requested_idempotency_key THEN 1
      ELSE 2
    END,
    auth_request.created_at_utc DESC NULLS LAST,
    auth_request.id DESC
  LIMIT 1;

  IF v_existing_auth_id IS NOT NULL THEN
    UPDATE public.pay_batch_auth_requests AS auth_request_update
    SET required_quantity = CASE
          WHEN v_existing_auth_operation_id IS NULL
           AND v_existing_auth_idempotency_key IS NULL
           AND auth_request_update.state = 'AWAITING' THEN v_required_quantity
          ELSE auth_request_update.required_quantity
        END,
        schedule_kind = CASE
          WHEN v_existing_auth_operation_id IS NULL
           AND v_existing_auth_idempotency_key IS NULL THEN v_kind
          ELSE auth_request_update.schedule_kind
        END,
        scheduled_at_utc = CASE
          WHEN v_existing_auth_operation_id IS NULL
           AND v_existing_auth_idempotency_key IS NULL THEN v_scheduled_at_utc
          ELSE auth_request_update.scheduled_at_utc
        END,
        funding_account_ref = CASE
          WHEN v_existing_auth_operation_id IS NULL
           AND v_existing_auth_idempotency_key IS NULL THEN v_funding_account_ref
          ELSE auth_request_update.funding_account_ref
        END,
        funds_warning_hours_json = CASE
          WHEN v_existing_auth_operation_id IS NULL
           AND v_existing_auth_idempotency_key IS NULL THEN v_warning_hours_json
          ELSE auth_request_update.funds_warning_hours_json
        END,
        execution_intent_json = CASE
          WHEN v_existing_auth_operation_id IS NULL AND v_existing_auth_idempotency_key IS NULL THEN
            jsonb_strip_nulls(coalesce(auth_request_update.execution_intent_json, '{}'::jsonb) || v_execution_intent_json)
          ELSE
            jsonb_strip_nulls(
              coalesce(auth_request_update.execution_intent_json, '{}'::jsonb)
              || CASE
                   WHEN p_operation_id IS NOT NULL
                    AND nullif(btrim(coalesce(auth_request_update.execution_intent_json->>'operation_id', '')), '') IS NULL
                     THEN jsonb_build_object('operation_id', p_operation_id::text)
                   ELSE '{}'::jsonb
                 END
              || CASE
                   WHEN v_requested_idempotency_key IS NOT NULL
                    AND nullif(btrim(coalesce(auth_request_update.execution_intent_json->>'idempotency_key', '')), '') IS NULL
                     THEN jsonb_build_object('idempotency_key', v_requested_idempotency_key)
                   ELSE '{}'::jsonb
                 END
              || CASE
                   WHEN v_effective_freshness_result_hash IS NOT NULL
                     THEN jsonb_build_object(
                       'freshness_result_hash', v_effective_freshness_result_hash,
                       'freshness_scope_hash', v_effective_freshness_scope_hash
                     )
                   ELSE '{}'::jsonb
                 END
            )
        END
    WHERE auth_request_update.id = v_existing_auth_id
    RETURNING auth_request_update.state,
              auth_request_update.execution_intent_json
    INTO v_auth_state,
         v_execution_intent_json;

    IF v_existing_auth_operation_id IS NULL AND v_existing_auth_idempotency_key IS NULL THEN
      UPDATE public.pay_batches AS batch_existing_auth_update
      SET schedule_kind = v_kind,
          scheduled_at_utc = CASE WHEN v_kind = 'SCHEDULED' THEN v_scheduled_at_utc ELSE NULL END,
          scheduled_by_user_id = CASE WHEN v_kind = 'SCHEDULED' THEN p_actor_user_id ELSE NULL END,
          funding_account_ref = v_funding_account_ref,
          funds_warning_hours_json = v_warning_hours_json,
          authoritative_payment_date = v_payment_date,
          authoritative_payment_date_source = 'PAY_BATCH_AUTH_START',
          execution_intent_json = v_execution_intent_json
      WHERE batch_existing_auth_update.id = p_pay_batch_id;
    ELSE
      UPDATE public.pay_batches AS batch_existing_auth_update
      SET execution_intent_json = v_execution_intent_json
      WHERE batch_existing_auth_update.id = p_pay_batch_id;
    END IF;

    v_execution_mode := upper(btrim(coalesce(
      v_execution_intent_json->>'execution_mode',
      v_execution_intent_json->>'mode',
      v_execution_mode
    )));

    IF v_execution_mode NOT IN ('STANDARD_BANK', 'BANK', 'CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN
      v_execution_mode := upper(btrim(coalesce(p_execution_mode, 'STANDARD_BANK')));
    END IF;

    v_kind := upper(btrim(coalesce(v_execution_intent_json->>'schedule_kind', v_kind)));

    IF v_kind NOT IN ('IMMEDIATE', 'SCHEDULED') THEN
      v_kind := upper(btrim(coalesce(p_schedule_kind, '')));
    END IF;

    v_next_required_phase := CASE
      WHEN v_auth_state = 'AUTHORISED' AND v_execution_mode IN ('CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'SETTLEMENT'
      WHEN v_auth_state = 'AUTHORISED' AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
      WHEN v_auth_state = 'AUTHORISED' THEN 'SUBMIT_PROVIDER_TRANSFERS'
      ELSE 'WAIT_FOR_AUTHORISATION'
    END;

    RETURN jsonb_build_object(
      'ok', true,
      'idempotent_reuse', true,
      'pay_batch_id', p_pay_batch_id::text,
      'auth_request_id', v_existing_auth_id::text,
      'auth_state', v_auth_state,
      'operation_id', v_execution_intent_json->>'operation_id',
      'idempotency_key', v_execution_intent_json->>'idempotency_key',
      'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
      'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
      'next_required_phase', v_next_required_phase,
      'execution_mode', v_execution_mode,
      'schedule_kind', v_kind,
      'auth_request_reuse_reason', CASE
        WHEN p_operation_id IS NOT NULL AND v_existing_auth_operation_id = p_operation_id::text THEN 'SAME_OPERATION'
        WHEN v_requested_idempotency_key IS NOT NULL AND v_existing_auth_idempotency_key = v_requested_idempotency_key THEN 'SAME_IDEMPOTENCY_KEY'
        WHEN v_existing_auth_operation_id IS NULL AND v_existing_auth_idempotency_key IS NULL THEN 'UNOWNED_AUTH_REQUEST_ATTACHED'
        ELSE 'SAFE_AUTH_REQUEST_REUSE'
      END,
      'execution_intent_json', v_execution_intent_json
    );
  END IF;

  UPDATE public.pay_batches AS batch_update
  SET schedule_kind = v_kind,
      scheduled_at_utc = CASE WHEN v_kind = 'SCHEDULED' THEN v_scheduled_at_utc ELSE NULL END,
      scheduled_by_user_id = CASE WHEN v_kind = 'SCHEDULED' THEN p_actor_user_id ELSE NULL END,
      funding_account_ref = v_funding_account_ref,
      funds_warning_hours_json = v_warning_hours_json,
      authoritative_payment_date = v_payment_date,
      authoritative_payment_date_source = 'PAY_BATCH_AUTH_START',
      execution_intent_json = v_execution_intent_json
  WHERE batch_update.id = p_pay_batch_id;

  INSERT INTO public.pay_batch_auth_requests (
    pay_batch_id,
    requested_by_user_id,
    required_quantity,
    schedule_kind,
    scheduled_at_utc,
    funding_account_ref,
    funds_warning_hours_json,
    execution_intent_json,
    state,
    golden_key_used,
    golden_key_user_id,
    created_at_utc
  )
  VALUES (
    p_pay_batch_id,
    p_actor_user_id,
    v_required_quantity,
    v_kind,
    v_scheduled_at_utc,
    v_funding_account_ref,
    v_warning_hours_json,
    v_execution_intent_json,
    'AWAITING',
    false,
    NULL::uuid,
    v_now
  )
  RETURNING id INTO v_auth_id;

  v_execution_intent_json := jsonb_set(v_execution_intent_json, '{auth_request_id}', to_jsonb(v_auth_id::text), true);

  UPDATE public.pay_batch_auth_requests AS auth_request_update
  SET execution_intent_json = v_execution_intent_json
  WHERE auth_request_update.id = v_auth_id;

  UPDATE public.pay_batches AS batch_intent_update
  SET execution_intent_json = v_execution_intent_json
  WHERE batch_intent_update.id = p_pay_batch_id;

  INSERT INTO public.pay_batch_auth_actions (
    auth_request_id,
    pay_batch_id,
    actor_user_id,
    action,
    action_at_utc,
    note
  )
  VALUES (
    v_auth_id,
    p_pay_batch_id,
    p_actor_user_id,
    CASE WHEN v_use_golden_key THEN 'USE_GOLDEN_KEY' ELSE 'AUTHORISE' END,
    v_now,
    NULL::text
  )
  ON CONFLICT (auth_request_id, actor_user_id) DO NOTHING;

  IF v_use_golden_key OR v_required_quantity <= 1 THEN
    UPDATE public.pay_batch_auth_requests AS auth_request_finalise
    SET state = 'AUTHORISED',
        golden_key_used = v_use_golden_key,
        golden_key_user_id = CASE WHEN v_use_golden_key THEN p_actor_user_id ELSE NULL::uuid END,
        finalised_at_utc = v_now,
        finalised_by_user_id = p_actor_user_id,
        execution_intent_json = v_execution_intent_json
    WHERE auth_request_finalise.id = v_auth_id;

    v_auth_state := 'AUTHORISED';
  ELSE
    v_auth_state := 'AWAITING';
  END IF;

  v_next_required_phase := CASE
    WHEN v_auth_state = 'AUTHORISED' AND v_execution_mode IN ('CSV', 'CSV_SETTLEMENT', 'EXTERNAL', 'EXTERNAL_SETTLEMENT', 'MANUAL_SETTLEMENT') THEN 'SETTLEMENT'
    WHEN v_auth_state = 'AUTHORISED' AND v_kind = 'SCHEDULED' THEN 'WAIT_FOR_SCHEDULE'
    WHEN v_auth_state = 'AUTHORISED' THEN 'SUBMIT_PROVIDER_TRANSFERS'
    ELSE 'WAIT_FOR_AUTHORISATION'
  END;

  RETURN jsonb_build_object(
    'ok', true,
    'idempotent_reuse', false,
    'pay_batch_id', p_pay_batch_id::text,
    'auth_request_id', v_auth_id::text,
    'auth_state', v_auth_state,
    'operation_id', CASE WHEN p_operation_id IS NULL THEN NULL ELSE p_operation_id::text END,
    'idempotency_key', v_requested_idempotency_key,
    'freshness_result_hash', v_execution_intent_json->>'freshness_result_hash',
    'freshness_scope_hash', v_execution_intent_json->>'freshness_scope_hash',
    'next_required_phase', v_next_required_phase,
    'execution_mode', v_execution_mode,
    'schedule_kind', v_kind,
    'scheduled_at_utc', CASE WHEN v_scheduled_at_utc IS NULL THEN NULL ELSE v_scheduled_at_utc::text END,
    'funding_account_ref', v_funding_account_ref,
    'authorisation_ready_transfer_count', COALESCE(v_authorisation_ready_transfer_count, 0),
    'provider_attempt_or_evidence_transfer_count', COALESCE(v_provider_attempt_or_evidence_transfer_count, 0),
    'canonical_pending_status_transfer_count', COALESCE(v_canonical_pending_status_transfer_count, 0),
    'scoped_operation_scope_count', COALESCE(v_scoped_operation_scope_count, 0),
    'scoped_scope_prepared_count', COALESCE(v_scoped_scope_prepared_count, 0),
    'scoped_scope_failed_count', COALESCE(v_scoped_scope_failed_count, 0),
    'scoped_scope_skipped_count', COALESCE(v_scoped_scope_skipped_count, 0),
    'scoped_scope_without_transfer_count', COALESCE(v_scoped_scope_without_transfer_count, 0),
    'non_cancellable_auth_request_count', COALESCE(v_non_cancellable_auth_request_count, 0),
    'auth_request_retry_blocker_count', COALESCE(v_auth_request_retry_blocker_count, 0),
    'payment_date', v_payment_date::text,
    'required_quantity', v_required_quantity,
    'auth_start_path', v_auth_start_path,
    'pay_batch_prepare_skipped', v_used_operation_scope_proof,
    'used_operation_scope_proof', v_used_operation_scope_proof,
    'provider_submit_chunk_risk_count', COALESCE(v_provider_submit_chunk_risk_count, 0),
    'operation_provider_submit_marker_count', COALESCE(v_operation_provider_submit_marker_count, 0),
    'transfer_identity_mismatch_count', COALESCE(v_transfer_identity_mismatch_count, 0),
    'transfer_amount_mismatch_count', COALESCE(v_transfer_amount_mismatch_count, 0),
    'transfer_currency_mismatch_count', COALESCE(v_transfer_currency_mismatch_count, 0),
    'transfer_external_state_count', COALESCE(v_transfer_external_state_count, 0),
    'execution_intent_json', v_execution_intent_json
  );
END;
$function$;







create or replace function public.pay_batch_auth_apply_action(
  p_auth_request_id uuid,
  p_actor_user_id uuid,
  p_action text,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_action text := upper(btrim(coalesce(p_action,'')));

  v_req record;
  v_user record;

  v_inserted_id uuid := null;
  v_approved_count int := 0;

  v_became_authorised boolean := false;
  v_new_auth_state text := null;
  v_new_batch_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;

  v_schedule_kind text := null;
  v_scheduled_at_utc timestamptz := null;
  v_funding_account_ref text := null;
  v_funds_warning_hours_json jsonb := null;
  v_schedule_result jsonb := '{}'::jsonb;
  v_worker_communications jsonb := '{}'::jsonb;
  v_remittance_queue_stage_result jsonb := '{}'::jsonb;
  v_remittance_send_timing text := 'ON_EXECUTION';
begin
  if p_auth_request_id is null then
    raise exception 'pay_batch_auth_apply_action: auth_request_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user_id is required';
  end if;

  if v_action not in ('AUTHORISE','USE_GOLDEN_KEY','REJECT') then
    raise exception 'pay_batch_auth_apply_action: invalid action (AUTHORISE|USE_GOLDEN_KEY|REJECT)';
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state,
    pbar.required_quantity,
    pbar.schedule_kind,
    pbar.scheduled_at_utc,
    pbar.funding_account_ref,
    pbar.funds_warning_hours_json,
    pbar.execution_intent_json
  into v_req
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_req.id is null then
    raise exception 'pay_batch_auth_apply_action: auth_request not found';
  end if;

  if v_req.state <> 'AWAITING' then
    raise exception 'pay_batch_auth_apply_action: auth_request must be AWAITING (current=%)', v_req.state;
  end if;

  if v_req.execution_intent_json is not null and jsonb_typeof(v_req.execution_intent_json) = 'object' then
    v_execution_intent_json := v_req.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  select coalesce(nullif(btrim(coalesce(sd.payment_remittance_send_timing, '')), ''), 'ON_EXECUTION')
  into v_remittance_send_timing
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  v_remittance_send_timing := coalesce(nullif(btrim(coalesce(v_remittance_send_timing, '')), ''), 'ON_EXECUTION');
  if v_remittance_send_timing not in ('ON_EXECUTION', 'ON_PAYMENT_CONFIRMED') then
    v_remittance_send_timing := 'ON_EXECUTION';
  end if;

  select
    tu.id,
    tu.is_active,
    tu.payment_authoriser,
    tu.payment_golden_key
  into v_user
  from public.tms_users tu
  where tu.id = p_actor_user_id
  limit 1;

  if v_user.id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user not found';
  end if;

  if coalesce(v_user.is_active,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user is not active';
  end if;

  if coalesce(v_user.payment_authoriser,false) = false and coalesce(v_user.payment_golden_key,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user is not an authoriser';
  end if;

  if v_action = 'USE_GOLDEN_KEY' and coalesce(v_user.payment_golden_key,false) = false then
    raise exception 'pay_batch_auth_apply_action: actor_user does not have payment golden key';
  end if;

  perform public._imp_debug_audit(
    p_actor_user_id,
    'PAY_BATCH_AUTH_APPLY_ACTION_START',
    jsonb_build_object(
      'auth_request_id', p_auth_request_id::text,
      'pay_batch_id', v_req.pay_batch_id::text,
      'action', v_action,
      'required_quantity', v_req.required_quantity,
      'payment_remittance_send_timing', v_remittance_send_timing
    ),
    'pay_batch_auth_requests',
    p_auth_request_id::text,
    null::jsonb,
    null::text,
    null::text,
    null::text
  );

  insert into public.pay_batch_auth_actions(
    auth_request_id,
    pay_batch_id,
    actor_user_id,
    action,
    action_at_utc,
    note
  )
  values (
    p_auth_request_id,
    v_req.pay_batch_id,
    p_actor_user_id,
    v_action,
    v_now,
    p_note
  )
  on conflict on constraint ux_pay_batch_auth_actions_one_per_user
  do nothing
  returning id into v_inserted_id;

  if v_inserted_id is null then
    raise exception 'pay_batch_auth_apply_action: actor_user has already acted on this request';
  end if;

  if v_action = 'REJECT' then
    update public.pay_batch_auth_requests pbar2
    set
      state = 'REJECTED',
      finalised_at_utc = v_now,
      finalised_by_user_id = p_actor_user_id,
      golden_key_used = false,
      golden_key_user_id = null
    where pbar2.id = p_auth_request_id;

    update public.pay_batch_auth_tokens pbat2
    set used_at_utc = v_now
    where pbat2.auth_request_id = p_auth_request_id
      and pbat2.used_at_utc is null;

    update public.pay_batches pb2
    set
      status = 'READY',
      schedule_kind = null,
      scheduled_at_utc = null,
      scheduled_by_user_id = null,
      funding_account_ref = null,
      funds_warning_hours_json = null,
      execution_intent_json = null
    where pb2.id = v_req.pay_batch_id;

    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', false,
      'message_kind', 'NONE',
      'trigger_status', 'AUTH_REJECTED_NO_QUEUE',
      'dispatch_required', false,
      'error', null,
      'result', jsonb_build_object(
        'ok', true,
        'queued', false,
        'deferred', false,
        'dispatch_required', false,
        'trigger_status', 'AUTH_REJECTED_NO_QUEUE',
        'configured_timing', v_remittance_send_timing
      )
    );
    v_remittance_queue_stage_result := v_worker_communications->'result';

    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_AUTH_APPLY_ACTION_REJECTED',
      jsonb_build_object(
        'auth_request_id', p_auth_request_id::text,
        'pay_batch_id', v_req.pay_batch_id::text,
        'worker_communications', v_worker_communications
      ),
      'pay_batch_auth_requests',
      p_auth_request_id::text,
      null::jsonb,
      null::text,
      null::text,
      null::text
    );

    return jsonb_build_object(
      'ok', true,
      'pay_batch_id', v_req.pay_batch_id::text,
      'status', (select pb3.status from public.pay_batches pb3 where pb3.id = v_req.pay_batch_id),
      'auth_request_id', p_auth_request_id::text,
      'auth_state', 'REJECTED',
      'required_quantity', v_req.required_quantity,
      'approved_count', 0,
      'became_authorised', false,
      'payment_remittance_send_timing', v_remittance_send_timing,
      'execution_intent_json', v_execution_intent_json,
      'execution_mode', v_execution_intent_json->>'execution_mode',
      'suppress_remittances', lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on'),
      'worker_communications', v_worker_communications,
      'remittance_queue_stage_result', v_remittance_queue_stage_result
    );
  end if;

  select count(*)::int
  into v_approved_count
  from public.pay_batch_auth_actions pbaa0
  where pbaa0.auth_request_id = p_auth_request_id
    and pbaa0.action in ('AUTHORISE','USE_GOLDEN_KEY');

  if v_action = 'USE_GOLDEN_KEY' or v_approved_count >= greatest(1, coalesce(v_req.required_quantity,1)) then
    v_became_authorised := true;

    v_schedule_kind := upper(btrim(coalesce(
      nullif(v_req.schedule_kind, ''),
      nullif(v_execution_intent_json->>'schedule_kind', ''),
      'IMMEDIATE'
    )));
    if v_schedule_kind not in ('IMMEDIATE','SCHEDULED') then
      raise exception 'pay_batch_auth_apply_action: invalid stored schedule_kind %', v_schedule_kind;
    end if;

    v_scheduled_at_utc := v_req.scheduled_at_utc;
    if v_scheduled_at_utc is null and nullif(btrim(coalesce(v_execution_intent_json->>'scheduled_at_utc', '')), '') is not null then
      v_scheduled_at_utc := (v_execution_intent_json->>'scheduled_at_utc')::timestamptz;
    end if;
    if v_schedule_kind = 'SCHEDULED' and v_scheduled_at_utc is null then
      raise exception 'pay_batch_auth_apply_action: stored scheduled_at_utc is required for SCHEDULED authorisation';
    end if;

    v_funding_account_ref := v_req.funding_account_ref;
    v_funds_warning_hours_json := v_req.funds_warning_hours_json;

    update public.pay_batch_auth_requests pbar3
    set
      state = 'AUTHORISED',
      finalised_at_utc = v_now,
      finalised_by_user_id = p_actor_user_id,
      golden_key_used = case when v_action = 'USE_GOLDEN_KEY' then true else coalesce(pbar3.golden_key_used,false) end,
      golden_key_user_id = case when v_action = 'USE_GOLDEN_KEY' then p_actor_user_id else pbar3.golden_key_user_id end,
      execution_intent_json = v_execution_intent_json
    where pbar3.id = p_auth_request_id;

    update public.pay_batch_auth_tokens pbat3
    set used_at_utc = v_now
    where pbat3.auth_request_id = p_auth_request_id
      and pbat3.used_at_utc is null;

    update public.pay_batches pb_before_schedule
    set
      execution_intent_json = v_execution_intent_json,
      execution_commit_state = coalesce(nullif(btrim(coalesce(pb_before_schedule.execution_commit_state, '')), ''), 'NOT_SUBMITTED')
    where pb_before_schedule.id = v_req.pay_batch_id;

    v_schedule_result := public.pay_batch_schedule(
      v_req.pay_batch_id,
      v_schedule_kind,
      v_scheduled_at_utc,
      v_funding_account_ref,
      v_funds_warning_hours_json,
      p_actor_user_id
    );

    update public.pay_batches pb4
    set
      status = 'AUTHORISED_FOR_PAYMENT',
      execution_intent_json = v_execution_intent_json,
      authoritative_payment_date = coalesce(
        pb4.authoritative_payment_date,
        (pb4.scheduled_at_utc at time zone 'Europe/London')::date,
        pb4.pay_date
      ),
      authoritative_payment_date_source = coalesce(pb4.authoritative_payment_date_source, 'AUTH_APPLY_SCHEDULED_AT_UTC')
    where pb4.id = v_req.pay_batch_id;

    v_worker_communications := coalesce(v_schedule_result->'worker_communications', '{}'::jsonb);
    v_remittance_queue_stage_result := coalesce(
      v_schedule_result->'remittance_queue_stage_result',
      v_worker_communications->'remittance_queue_stage_result',
      v_worker_communications->'result',
      '{}'::jsonb
    );

    v_new_auth_state := 'AUTHORISED';
    v_new_batch_status := 'AUTHORISED_FOR_PAYMENT';
  else
    v_became_authorised := false;
    v_new_auth_state := 'AWAITING';

    update public.pay_batches pb5
    set
      status = 'AWAITING_AUTHORISATION',
      execution_intent_json = v_execution_intent_json
    where pb5.id = v_req.pay_batch_id;

    v_new_batch_status := 'AWAITING_AUTHORISATION';
    v_worker_communications := jsonb_build_object(
      'automatic_commit_stage', false,
      'message_kind', case when upper(btrim(coalesce(v_execution_intent_json->>'execution_mode', 'STANDARD_BANK'))) in ('CSV_SETTLEMENT','EXTERNAL_SETTLEMENT') then 'PAYOUT_NOTICE_AND_REMITTANCE' else 'REMITTANCE' end,
      'trigger_status', 'AWAITING_AUTHORISATION',
      'dispatch_required', false,
      'error', null,
      'result', jsonb_build_object(
        'ok', true,
        'queued', false,
        'deferred', true,
        'dispatch_required', false,
        'trigger_status', 'AWAITING_AUTHORISATION',
        'configured_timing', v_remittance_send_timing
      )
    );
    v_remittance_queue_stage_result := v_worker_communications->'result';
  end if;

  perform public._imp_debug_audit(
    p_actor_user_id,
    'PAY_BATCH_AUTH_APPLY_ACTION_RESULT',
    jsonb_build_object(
      'auth_request_id', p_auth_request_id::text,
      'pay_batch_id', v_req.pay_batch_id::text,
      'action', v_action,
      'approved_count', v_approved_count,
      'became_authorised', v_became_authorised,
      'auth_state', v_new_auth_state,
      'batch_status', v_new_batch_status,
      'schedule_result', v_schedule_result,
      'worker_communications', v_worker_communications
    ),
    'pay_batch_auth_requests',
    p_auth_request_id::text,
    null::jsonb,
    null::text,
    null::text,
    null::text
  );

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_req.pay_batch_id::text,
    'status', (select pb6.status from public.pay_batches pb6 where pb6.id = v_req.pay_batch_id),
    'auth_request_id', p_auth_request_id::text,
    'auth_state', v_new_auth_state,
    'required_quantity', v_req.required_quantity,
    'approved_count', v_approved_count,
    'became_authorised', v_became_authorised,
    'payment_remittance_send_timing', v_remittance_send_timing,
    'execution_intent_json', v_execution_intent_json,
    'execution_mode', v_execution_intent_json->>'execution_mode',
    'suppress_remittances', lower(btrim(coalesce(v_execution_intent_json->>'suppress_remittances','false'))) in ('true','1','yes','y','on'),
    'schedule_result', v_schedule_result,
    'worker_communications', v_worker_communications,
    'remittance_queue_stage_result', v_remittance_queue_stage_result
  );
exception
  when others then
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_AUTH_APPLY_ACTION_ERROR',
      jsonb_build_object(
        'auth_request_id', p_auth_request_id::text,
        'action', v_action,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_batch_auth_requests',
      coalesce(p_auth_request_id::text, 'NO_AUTH_REQUEST_ID'),
      null::jsonb,
      null::text,
      null::text,
      null::text
    );
    raise;
end;
$$;




create or replace function public.pay_batch_auth_invites_upsert(
  p_auth_request_id uuid,
  p_actor_user_id uuid,
  p_target_user_ids uuid[] default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_req record;
  v_now timestamptz := now();
  v_expires timestamptz := (now() + interval '7 days');

  v_target_count int := 0;
  v_inserted_count int := 0;
  v_tokens jsonb := '[]'::jsonb;
begin
  if p_auth_request_id is null then
    raise exception 'pay_batch_auth_invites_upsert: auth_request_id is required';
  end if;
  if p_actor_user_id is null then
    raise exception 'pay_batch_auth_invites_upsert: actor_user_id is required';
  end if;

  select
    pbar.id,
    pbar.pay_batch_id,
    pbar.state
  into v_req
  from public.pay_batch_auth_requests pbar
  where pbar.id = p_auth_request_id
  for update;

  if v_req.id is null then
    raise exception 'pay_batch_auth_invites_upsert: auth_request not found';
  end if;

  if v_req.state <> 'AWAITING' then
    raise exception 'pay_batch_auth_invites_upsert: auth_request must be AWAITING (current=%)', v_req.state;
  end if;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  select count(*)::int
  into v_target_count
  from targets;

  if v_target_count = 0 then
    raise exception 'pay_batch_auth_invites_upsert: no eligible target users resolved';
  end if;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  insert into public.pay_batch_auth_tokens(
    token,
    auth_request_id,
    target_user_id,
    expires_at_utc,
    used_at_utc,
    created_at_utc
  )
  select
    encode(gen_random_bytes(24), 'hex'),
    p_auth_request_id,
    t.user_id,
    v_expires,
    null,
    v_now
  from targets t
  on conflict on constraint ux_pay_batch_auth_tokens_one_per_target
  do nothing;

  get diagnostics v_inserted_count = row_count;

  with targets as (
    select
      tu.id as user_id
    from public.tms_users tu
    where tu.is_active = true
      and (coalesce(tu.payment_authoriser,false) = true or coalesce(tu.payment_golden_key,false) = true)
      and (
        p_target_user_ids is null
        or coalesce(array_length(p_target_user_ids,1),0) = 0
        or tu.id = any(p_target_user_ids)
      )
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'target_user_id', pbat.target_user_id::text,
        'token', pbat.token,
        'expires_at_utc', pbat.expires_at_utc,
        'used_at_utc', pbat.used_at_utc,
        'created_at_utc', pbat.created_at_utc
      )
      order by pbat.created_at_utc asc nulls last, pbat.token asc
    ),
    '[]'::jsonb
  )
  into v_tokens
  from public.pay_batch_auth_tokens pbat
  join targets t
    on t.user_id = pbat.target_user_id
  where pbat.auth_request_id = p_auth_request_id;

  return jsonb_build_object(
    'ok', true,
    'auth_request_id', p_auth_request_id::text,
    'pay_batch_id', v_req.pay_batch_id::text,
    'resolved_target_count', v_target_count,
    'inserted_count', v_inserted_count,
    'expires_at_utc', v_expires,
    'tokens', v_tokens
  );
end;
$$;

create or replace function public._bank_hash(
  p_sort_code text,
  p_account_number text,
  p_account_holder text
) returns text
language plpgsql
as $$
declare
  v_sort text;
  v_acct text;
  v_name text;
  v_raw  text;
begin
  v_sort := regexp_replace(coalesce(p_sort_code,''), '[^0-9]+', '', 'g');
  v_acct := regexp_replace(coalesce(p_account_number,''), '[^0-9]+', '', 'g');
  v_name := upper(regexp_replace(btrim(coalesce(p_account_holder,'')), '\s+', ' ', 'g'));

  if v_sort = '' or v_acct = '' then
    return null;
  end if;

  v_raw := v_sort || '|' || v_acct || '|' || v_name;

  -- md5() is built-in (no pgcrypto dependency) and returns a stable hex string.
  return md5(v_raw);
end $$;


CREATE OR REPLACE FUNCTION public.bank_readiness_lock(
  p_provider text,
  p_env text,
  p_entity_kind text,
  p_entity_id uuid,
  p_bank_details_hash text,
  p_lock_kind text DEFAULT 'READINESS'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_provider text;
  v_env text;
  v_entity_kind text;
  v_bank_hash text;
  v_lock_kind text;
  v_key text;

  v_h1 int;
  v_h2 int;
  v_lock_key bigint;
begin
  v_provider := upper(btrim(coalesce(p_provider,'')));
  v_env := upper(btrim(coalesce(p_env,'')));
  v_entity_kind := upper(btrim(coalesce(p_entity_kind,'')));
  v_bank_hash := btrim(coalesce(p_bank_details_hash,''));
  v_lock_kind := upper(btrim(coalesce(p_lock_kind,'READINESS')));

  if v_provider = '' then
    raise exception 'provider is required';
  end if;

  if v_env = '' then
    raise exception 'env is required';
  end if;

  if v_entity_kind = '' then
    raise exception 'entity_kind is required';
  end if;

  if p_entity_id is null then
    raise exception 'entity_id is required';
  end if;

  if v_bank_hash = '' then
    raise exception 'bank_details_hash is required';
  end if;

  if v_lock_kind = '' then
    raise exception 'lock_kind is required';
  end if;

  v_key := v_lock_kind
           || '|' || v_provider
           || '|' || v_env
           || '|' || v_entity_kind
           || '|' || p_entity_id::text
           || '|' || v_bank_hash;

  -- Build a stable 64-bit advisory lock key from two 32-bit hashes.
  v_h1 := hashtext(v_key);
  v_h2 := hashtext(v_key || '|2');

  v_lock_key :=
    (( (v_h1::bigint & 4294967295) << 32 )
      | (v_h2::bigint & 4294967295));

  perform pg_advisory_xact_lock(v_lock_key);

  return jsonb_build_object(
    'ok', true
  );
end;
$function$;


DROP FUNCTION IF EXISTS public.pay_batch_validate_freshness(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_batch_validate_freshness(uuid, uuid, boolean);

CREATE OR REPLACE FUNCTION public.pay_batch_validate_freshness(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_allow_large_full_scan boolean DEFAULT false
)
returns jsonb
language plpgsql
security definer
set search_path to 'public'
as $function$
declare
  v_now_utc timestamptz := now();

  v_pay_date date;
  v_week_start date;
  v_batch_kind_fixed text;
  v_scope text;

  v_ts_ids uuid[] := array[]::uuid[];

  v_is_stale boolean := false;
  v_reasons text[] := array[]::text[];

  v_diffs jsonb := '[]'::jsonb;

  v_ts_changed_ct int := 0;
  v_key_diff_ct int := 0;
  v_finance_reservation_diff_ct int := 0;
  v_snooze_diff_ct int := 0;
  v_restructure_diff_ct int := 0;
  v_writeoff_diff_ct int := 0;
  v_timesheet_override_diff_ct int := 0;
  v_paye_guardrail_diff_ct int := 0;
  v_overpay_ded_diff_ct int := 0;
  v_manual_debt_ded_diff_ct int := 0;
  v_loan_ded_diff_ct int := 0;
  v_ded_diff_ct int := 0;
  v_paye_net_diff_ct int := 0;

  v_batch_created_at_utc timestamptz;
  v_batch_status text;
  v_batch_is_active_reservation boolean := false;
  v_finance_reservation_expected_status text := 'RESERVED';
  v_same_week_paye_override_used boolean := false;
  v_paye_guardrails jsonb := '{}'::jsonb;

  v_diff_limit int := 500;

  -- Scalable execution guard. Normal execute operation flow must use the
  -- chunked freshness RPCs. This legacy/full validator remains available for
  -- small/manual diagnostics, or explicit admin diagnostics when
  -- p_allow_large_full_scan = true. Counts are derived only from frozen
  -- batch/payment artifacts, never live TSFIN.
  v_allow_large_full_scan boolean := false;
  v_candidate_count integer := 0;
  v_item_count integer := 0;
  v_item_breakdown_count integer := 0;
  v_transfer_count integer := 0;
  v_large_batch boolean := false;
  v_large_batch_reasons jsonb := '[]'::jsonb;
  v_chunked_required_diff jsonb := '[]'::jsonb;
begin
  v_allow_large_full_scan := coalesce(p_allow_large_full_scan, false);

  if p_pay_batch_id is null then
    raise exception 'pay_batch_validate_freshness: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_batch_validate_freshness: actor_user_id is required';
  end if;

  select
    pb.pay_date,
    pb.batch_kind_fixed,
    pb.created_at_utc,
    upper(coalesce(pb.status, '')),
    coalesce(pb.same_week_paye_override_used, false)
  into
    v_pay_date,
    v_batch_kind_fixed,
    v_batch_created_at_utc,
    v_batch_status,
    v_same_week_paye_override_used
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_pay_date is null then
    raise exception 'pay_batch_validate_freshness: pay_batch_id not found (%).', p_pay_batch_id::text;
  end if;

  select count(*)::integer
  into v_candidate_count
  from public.pay_batch_candidates as guard_candidate_count
  where guard_candidate_count.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_item_count
  from public.pay_batch_items as guard_item_count
  join public.pay_batch_candidates as guard_item_candidate
    on guard_item_candidate.id = guard_item_count.pay_batch_candidate_id
  where guard_item_candidate.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_item_breakdown_count
  from public.pay_batch_item_breakdowns as guard_breakdown_count
  join public.pay_batch_items as guard_breakdown_item
    on guard_breakdown_item.id = guard_breakdown_count.pay_batch_item_id
  join public.pay_batch_candidates as guard_breakdown_candidate
    on guard_breakdown_candidate.id = guard_breakdown_item.pay_batch_candidate_id
  where guard_breakdown_candidate.pay_batch_id = p_pay_batch_id;

  select count(*)::integer
  into v_transfer_count
  from public.pay_bank_transfers as guard_transfer_count
  where guard_transfer_count.pay_batch_id = p_pay_batch_id;

  v_large_batch := (
    coalesce(v_candidate_count, 0) > 100
    or coalesce(v_item_count, 0) > 250
    or coalesce(v_transfer_count, 0) > 100
    or coalesce(v_item_breakdown_count, 0) > 500
  );

  select coalesce(jsonb_agg(guard_reason.reason_json order by guard_reason.reason_key), '[]'::jsonb)
  into v_large_batch_reasons
  from (
    select
      'candidate_count'::text as reason_key,
      jsonb_build_object('metric', 'candidate_count', 'count', coalesce(v_candidate_count, 0), 'threshold', 100) as reason_json
    where coalesce(v_candidate_count, 0) > 100

    union all

    select
      'item_count'::text as reason_key,
      jsonb_build_object('metric', 'item_count', 'count', coalesce(v_item_count, 0), 'threshold', 250) as reason_json
    where coalesce(v_item_count, 0) > 250

    union all

    select
      'transfer_count'::text as reason_key,
      jsonb_build_object('metric', 'transfer_count', 'count', coalesce(v_transfer_count, 0), 'threshold', 100) as reason_json
    where coalesce(v_transfer_count, 0) > 100

    union all

    select
      'item_breakdown_count'::text as reason_key,
      jsonb_build_object('metric', 'item_breakdown_count', 'count', coalesce(v_item_breakdown_count, 0), 'threshold', 500) as reason_json
    where coalesce(v_item_breakdown_count, 0) > 500
  ) as guard_reason;

  if v_large_batch and v_allow_large_full_scan is not true then
    v_chunked_required_diff := jsonb_build_array(
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', 'FRESHNESS_MODE',
        'key_value', 'FULL_BATCH_SCAN_GUARD',
        'expected', jsonb_build_object(
          'required_path', 'chunked_freshness',
          'seed_rpc', 'pay_batch_freshness_scope_seed',
          'chunk_rpc', 'pay_batch_validate_freshness_chunk',
          'aggregate_rpc', 'pay_batch_freshness_result_get'
        ),
        'actual', jsonb_build_object(
          'requested_path', 'pay_batch_validate_freshness_full_scan',
          'p_allow_large_full_scan', v_allow_large_full_scan,
          'candidate_count', coalesce(v_candidate_count, 0),
          'item_count', coalesce(v_item_count, 0),
          'transfer_count', coalesce(v_transfer_count, 0),
          'item_breakdown_count', coalesce(v_item_breakdown_count, 0),
          'large_batch_reasons', coalesce(v_large_batch_reasons, '[]'::jsonb)
        )
      )
    );

    return jsonb_build_object(
      'is_stale', true,
      'stale_reasons', jsonb_build_array('FULL_BATCH_FRESHNESS_REQUIRES_CHUNKED_VALIDATION'),
      'diff', v_chunked_required_diff,
      'requires_chunked_freshness', true,
      'code', 'FULL_BATCH_FRESHNESS_REQUIRES_CHUNKED_VALIDATION',
      'message', 'This batch is too large for the legacy full-batch freshness validator. Use the chunked freshness operation path.',
      'pay_batch_id', p_pay_batch_id::text,
      'counts', jsonb_build_object(
        'candidate_count', coalesce(v_candidate_count, 0),
        'item_count', coalesce(v_item_count, 0),
        'transfer_count', coalesce(v_transfer_count, 0),
        'item_breakdown_count', coalesce(v_item_breakdown_count, 0)
      ),
      'thresholds', jsonb_build_object(
        'candidate_count', 100,
        'item_count', 250,
        'transfer_count', 100,
        'item_breakdown_count', 500
      ),
      'large_batch_reasons', coalesce(v_large_batch_reasons, '[]'::jsonb)
    );
  end if;

  v_batch_is_active_reservation := public._pay_batch_status_is_active_reservation(v_batch_status);

  if v_batch_status in ('AUTHORISED_FOR_PAYMENT','SCHEDULED','EXECUTING') then
    v_finance_reservation_expected_status := 'COMMITTED';
  else
    v_finance_reservation_expected_status := 'RESERVED';
  end if;

  v_week_start := public._pay_week_start_monday(v_pay_date);

  select
    max(pbi.pay_channel)
  into
    v_scope
  from public.pay_batch_items pbi
  join public.pay_batch_candidates pbc
    on pbc.id = pbi.pay_batch_candidate_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
    and pbi.pay_channel in ('PAYE','UMBRELLA');

  v_scope := upper(btrim(coalesce(v_scope,'')));
  if v_scope not in ('PAYE','UMBRELLA') then
    v_scope := null;
  end if;

  select
    coalesce(
      (
        select array_agg(distinct t1.timesheet_id)
        from (
          select pbts.timesheet_id
          from public.pay_batch_timesheet_snapshots pbts
          where pbts.pay_batch_id = p_pay_batch_id
            and pbts.timesheet_id is not null

          union all

          select pbi2.timesheet_id
          from public.pay_batch_items pbi2
          join public.pay_batch_candidates pbc2
            on pbc2.id = pbi2.pay_batch_candidate_id
          where pbc2.pay_batch_id = p_pay_batch_id
            and coalesce(pbi2.is_voided, false) = false
            and not exists (
              select 1
              from public.pay_payment_correction_items as ppc_pbi2_fresh_exclusion
              where ppc_pbi2_fresh_exclusion.pay_batch_item_id = pbi2.id
                and ppc_pbi2_fresh_exclusion.status = 'APPLIED'
                and ppc_pbi2_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
            )
            and pbi2.timesheet_id is not null
        ) t1
      ),
      array[]::uuid[]
    )
  into v_ts_ids;

  create temporary table if not exists pg_temp.tmp_fresh_ts_diffs (
    timesheet_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_text text null,
    actual_text text null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_key_diffs (
    timesheet_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_candidate_earnings (
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    awaiting_net_amount boolean not null,
    earnings_before_loan_ex numeric(12,2) not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_overpay_alloc (
    candidate_id uuid not null,
    advance_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_candidate_expected_overpay (
    candidate_id uuid not null,
    expected_overpayment_recovery_ex numeric(12,2) not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_loan_alloc (
    candidate_id uuid not null,
    loan_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_deduction_diffs (
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_paye_net_diffs (
    candidate_id uuid not null,
    key_type text not null,
    key_value text not null,
    expected_ex numeric(12,2) null,
    actual_ex numeric(12,2) null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_expected_manual_debt_alloc (
    candidate_id uuid not null,
    finance_case_id uuid not null,
    take_ex numeric(12,2) not null,
    ord int not null
  ) on commit drop;

  create temporary table if not exists pg_temp.tmp_fresh_state_diffs (
    timesheet_id uuid null,
    candidate_id uuid null,
    key_type text not null,
    key_value text not null,
    expected_text text null,
    actual_text text null,
    ord int not null
  ) on commit drop;

  truncate table pg_temp.tmp_fresh_ts_diffs;
  truncate table pg_temp.tmp_fresh_key_diffs;
  truncate table pg_temp.tmp_fresh_candidate_earnings;
  truncate table pg_temp.tmp_fresh_expected_overpay_alloc;
  truncate table pg_temp.tmp_fresh_candidate_expected_overpay;
  truncate table pg_temp.tmp_fresh_expected_loan_alloc;
  truncate table pg_temp.tmp_fresh_expected_manual_debt_alloc;
  truncate table pg_temp.tmp_fresh_deduction_diffs;
  truncate table pg_temp.tmp_fresh_paye_net_diffs;
  truncate table pg_temp.tmp_fresh_state_diffs;

  ---------------------------------------------------------------------------
  -- TIMESHEET_CHANGED: Policy X keeps blocking freshness checks in the
  -- economic entitlement keyspace. The legacy whole-snapshot signature
  -- comparison is intentionally disabled as a blocking stale gate here.
  ---------------------------------------------------------------------------
  v_ts_changed_ct := 0;

  ---------------------------------------------------------------------------
  -- RESERVATION_CHANGED: compare this batch's frozen source entitlement
  -- against the current entitlement available before this batch.
  --
  -- Policy X (post-draft): the batch side is resolved only from frozen
  -- batch artifacts via _pay_batch_item_economic_components. Current
  -- live truth is comparison-only via _pay_current_timesheet_entitlement_components.
  -- This section must not call the broad outstanding helper, must not
  -- remap batch items from live TSFIN, and must not validate resolved rows
  -- against target payout amounts.
  ---------------------------------------------------------------------------
  if v_batch_is_active_reservation then
    insert into pg_temp.tmp_fresh_key_diffs (
      timesheet_id,
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with
    this_components_raw as (
      select
        pbec.pay_batch_item_id,
        pbec.timesheet_id,
        upper(nullif(btrim(coalesce(pbec.item_type, '')), '')) as item_type,
        upper(nullif(btrim(coalesce(pbec.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(pbec.key_value, '')), '') as key_value,
        pbec.source_amount_ex_vat as source_amount_ex_vat_raw,
        pbec.target_amount_ex_vat as target_amount_ex_vat_raw,
        nullif(btrim(coalesce(pbec.key_resolution_failure_reason, '')), '') as key_resolution_failure_reason
      from public._pay_batch_item_economic_components(
        p_pay_batch_id => p_pay_batch_id,
        p_pay_batch_item_ids => null::uuid[]
      ) as pbec
      join public.pay_batch_items as pbi_this_fresh
        on pbi_this_fresh.id = pbec.pay_batch_item_id
      join public.pay_batch_candidates as pbc_this_fresh
        on pbc_this_fresh.id = pbi_this_fresh.pay_batch_candidate_id
      where pbc_this_fresh.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_this_fresh.is_voided, false) = false
        and not exists (
          select 1
          from public.pay_payment_correction_items as ppc_this_fresh_exclusion
          where ppc_this_fresh_exclusion.pay_batch_item_id = pbi_this_fresh.id
            and ppc_this_fresh_exclusion.status = 'APPLIED'
            and ppc_this_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
        )
        and upper(nullif(btrim(coalesce(pbec.item_type, '')), '')) in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
    ),
    this_component_resolution_failures as (
      select
        tcr.timesheet_id,
        case
          when tcr.key_resolution_failure_reason is not null then tcr.key_resolution_failure_reason
          when tcr.key_type is null or tcr.key_value is null then 'KEY_RESOLUTION_FAILURE'
          when tcr.key_type not in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE') then 'KEY_RESOLUTION_FAILURE'
          when tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$' then 'TS_DAY_KEY_VALUE_NOT_DATE'
          when tcr.source_amount_ex_vat_raw is null then 'SOURCE_RESOLUTION_FAILURE'
          else 'SOURCE_RESOLUTION_FAILURE'
        end as key_type,
        coalesce(tcr.pay_batch_item_id::text, 'UNKNOWN_PAY_BATCH_ITEM') as key_value,
        0::numeric(12,2) as expected_ex,
        1::numeric(12,2) as actual_ex,
        2 as ord
      from this_components_raw as tcr
      where tcr.key_resolution_failure_reason is not null
         or tcr.key_type is null
         or tcr.key_value is null
         or tcr.key_type not in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
         or (tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
         or tcr.source_amount_ex_vat_raw is null
    ),
    this_components as (
      select
        tcr.timesheet_id,
        tcr.key_type,
        tcr.key_value,
        round(sum(round(coalesce(tcr.source_amount_ex_vat_raw, 0), 2)), 2)::numeric(12,2) as current_source_ex_vat
      from this_components_raw as tcr
      where tcr.timesheet_id is not null
        and tcr.key_type is not null
        and tcr.key_value is not null
        and tcr.key_type in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (tcr.key_type = 'TS_DAY' and tcr.key_value !~ '^\d{4}-\d{2}-\d{2}$')
        and tcr.key_resolution_failure_reason is null
        and tcr.source_amount_ex_vat_raw is not null
      group by
        tcr.timesheet_id,
        tcr.key_type,
        tcr.key_value
    ),
    current_truth_baseline as (
      select
        ctec.timesheet_id,
        upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(ctec.key_value, '')), '') as key_value,
        round(sum(coalesce(ctec.truth_ex_vat, 0)), 2)::numeric(12,2) as truth_ex_vat,
        round(sum(coalesce(ctec.baseline_ex_vat, 0)), 2)::numeric(12,2) as baseline_ex_vat
      from public._pay_current_timesheet_entitlement_components(v_ts_ids) as ctec
      where ctec.timesheet_id is not null
        and ctec.key_type is not null
        and btrim(ctec.key_type) <> ''
        and ctec.key_value is not null
        and btrim(ctec.key_value) <> ''
        and upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (
          upper(nullif(btrim(coalesce(ctec.key_type, '')), '')) = 'TS_DAY'
          and nullif(btrim(coalesce(ctec.key_value, '')), '') !~ '^\d{4}-\d{2}-\d{2}$'
        )
      group by
        ctec.timesheet_id,
        upper(nullif(btrim(coalesce(ctec.key_type, '')), '')),
        nullif(btrim(coalesce(ctec.key_value, '')), '')
    ),
    all_reserved as (
      select
        rc.timesheet_id,
        upper(nullif(btrim(coalesce(rc.key_type, '')), '')) as key_type,
        nullif(btrim(coalesce(rc.key_value, '')), '') as key_value,
        round(sum(coalesce(rc.amount_ex_vat, 0)), 2)::numeric(12,2) as all_reserved_ex_vat
      from public._pay_reserved_components(v_ts_ids) as rc
      where rc.timesheet_id is not null
        and rc.key_type is not null
        and btrim(rc.key_type) <> ''
        and rc.key_value is not null
        and btrim(rc.key_value) <> ''
        and upper(nullif(btrim(coalesce(rc.key_type, '')), '')) in ('TS_DAY','TS_TOTAL','ADDITIONAL_CODE','ADJUSTMENT_CODE','EXPENSE_CODE')
        and not (
          upper(nullif(btrim(coalesce(rc.key_type, '')), '')) = 'TS_DAY'
          and nullif(btrim(coalesce(rc.key_value, '')), '') !~ '^\d{4}-\d{2}-\d{2}$'
        )
      group by
        rc.timesheet_id,
        upper(nullif(btrim(coalesce(rc.key_type, '')), '')),
        nullif(btrim(coalesce(rc.key_value, '')), '')
    ),
    reservation_comparison as (
      select
        tc.timesheet_id,
        tc.key_type,
        tc.key_value,
        tc.current_source_ex_vat as expected_ex,
        round(
          coalesce(ctb.truth_ex_vat, 0)
          - coalesce(ctb.baseline_ex_vat, 0)
          - (
              coalesce(ar.all_reserved_ex_vat, 0)
              - coalesce(tc.current_source_ex_vat, 0)
            ),
          2
        )::numeric(12,2) as actual_ex,
        2 as ord
      from this_components as tc
      left join current_truth_baseline as ctb
        on ctb.timesheet_id = tc.timesheet_id
       and ctb.key_type = tc.key_type
       and ctb.key_value = tc.key_value
      left join all_reserved as ar
        on ar.timesheet_id = tc.timesheet_id
       and ar.key_type = tc.key_type
       and ar.key_value = tc.key_value
    ),
    reservation_mismatches as (
      select
        rc.timesheet_id,
        rc.key_type,
        rc.key_value,
        rc.expected_ex,
        rc.actual_ex,
        rc.ord
      from reservation_comparison as rc
      where abs(round(coalesce(rc.actual_ex, 0), 2) - round(coalesce(rc.expected_ex, 0), 2)) > 0.01
    )
    select
      tcrf.timesheet_id,
      tcrf.key_type,
      tcrf.key_value,
      tcrf.expected_ex,
      tcrf.actual_ex,
      tcrf.ord
    from this_component_resolution_failures as tcrf

    union all

    select
      rm.timesheet_id,
      rm.key_type,
      rm.key_value,
      rm.expected_ex,
      rm.actual_ex,
      rm.ord
    from reservation_mismatches as rm;
  end if;

  select count(*)::int
  into v_key_diff_ct
  from pg_temp.tmp_fresh_key_diffs;

  if v_key_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'RESERVATION_CHANGED');
  end if;

  ---------------------------------------------------------------------------
  -- STATE_CHANGED: finance reservation rows, snoozes, restructure/write-off,
  -- timesheet-payment-override changes, and PAYE guardrail changes.
  ---------------------------------------------------------------------------
  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_finance_items as (
    select
      pbi.timesheet_id,
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.finance_case_id,
      pbi.reservation_id,
      pbi.item_type,
      pbi.repayment_week_start,
      round(abs(coalesce(pbi.frozen_source_amount, case when pbi.frozen_target_amount_ex_vat is null and pbi.frozen_resolution_mode is null and pbi.frozen_resolution_result_json is null then pbi.amount_ex_vat else null end, 0)), 2)::numeric(12,2) as reserved_amount_ex
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
      and pbi.finance_case_id is not null
  ),
  reservation_rows as (
    select
      par.id as reservation_id,
      par.finance_case_id,
      par.pay_batch_id,
      par.pay_batch_candidate_id,
      par.pay_batch_item_id,
      round(coalesce(par.reserved_amount, 0), 2)::numeric(12,2) as reserved_amount_ex,
      par.repayment_week_start,
      upper(coalesce(par.status, '')) as reservation_status
    from public.pay_advance_reservations par
    where par.pay_batch_id = p_pay_batch_id
  )
  select
    bfi.timesheet_id,
    bfi.candidate_id,
    'FINANCE_RESERVATION' as key_type,
    bfi.pay_batch_item_id::text as key_value,
    jsonb_build_object(
      'finance_case_id', bfi.finance_case_id::text,
      'reservation_id', case when bfi.reservation_id is null then null else bfi.reservation_id::text end,
      'reserved_amount_ex', bfi.reserved_amount_ex,
      'repayment_week_start', case when bfi.repayment_week_start is null then null else bfi.repayment_week_start::text end,
      'status', v_finance_reservation_expected_status
    )::text as expected_text,
    case
      when rr.reservation_id is null then null
      else jsonb_build_object(
        'reservation_id', rr.reservation_id::text,
        'finance_case_id', rr.finance_case_id::text,
        'reserved_amount_ex', rr.reserved_amount_ex,
        'repayment_week_start', case when rr.repayment_week_start is null then null else rr.repayment_week_start::text end,
        'status', rr.reservation_status
      )::text
    end as actual_text,
    33 as ord
  from batch_finance_items bfi
  left join reservation_rows rr
    on rr.pay_batch_item_id = bfi.pay_batch_item_id
  where rr.reservation_id is null
     or rr.finance_case_id is distinct from bfi.finance_case_id
     or round(coalesce(rr.reserved_amount_ex, 0), 2) <> round(coalesce(bfi.reserved_amount_ex, 0), 2)
     or rr.repayment_week_start is distinct from bfi.repayment_week_start
     or rr.reservation_status <> v_finance_reservation_expected_status
     or (bfi.reservation_id is not null and rr.reservation_id is distinct from bfi.reservation_id);

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_items as (
    select
      pbi.timesheet_id,
      pbc.candidate_id,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      pbi.source_ref,
      pbi.finance_case_id,
      case
        when nullif(btrim(coalesce(pbi.segment_key, '')), '') is not null then pbi.segment_key
        when pbi.source_ref is not null and btrim(pbi.source_ref) like 'seg:%' then substring(btrim(pbi.source_ref) from 5)
        else null
      end as seg_identity
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
  ),
  active_snoozes as (
    select
      pis.id as snooze_id,
      pis.candidate_id,
      pis.timesheet_id,
      pis.segment_id,
      pis.source_ref,
      pis.snooze_until_date,
      pis.note,
      pis.updated_at_utc,
      pis.created_at_utc,
      upper(coalesce(pis.snooze_kind, '')) as snooze_kind
    from public.pay_item_snoozes pis
    where pis.cleared_at_utc is null
      and (pis.snooze_until_date is null or pis.snooze_until_date >= v_pay_date)
  ),
  matched_snoozes as (
    select distinct
      bi.timesheet_id,
      bi.candidate_id,
      bi.pay_batch_item_id,
      asn.snooze_id,
      asn.snooze_kind,
      asn.snooze_until_date,
      asn.note
    from batch_items bi
    join active_snoozes asn
      on (
           bi.finance_case_id is not null
           and asn.source_ref = coalesce(bi.source_ref, ('advance:' || bi.finance_case_id::text))
         )
        or (
           bi.timesheet_id is not null
           and asn.timesheet_id = bi.timesheet_id
           and asn.segment_id is not distinct from bi.seg_identity
         )
  )
  select
    ms.timesheet_id,
    ms.candidate_id,
    'SNOOZE' as key_type,
    ms.pay_batch_item_id::text as key_value,
    'NO_ACTIVE_SNOOZE' as expected_text,
    jsonb_build_object(
      'snooze_id', ms.snooze_id::text,
      'snooze_kind', ms.snooze_kind,
      'snooze_until_date', case when ms.snooze_until_date is null then null else ms.snooze_until_date::text end,
      'note', ms.note
    )::text as actual_text,
    34 as ord
  from matched_snoozes ms;

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with referenced_finance_cases as (
    select distinct
      pbc.candidate_id,
      coalesce(
        pbi.finance_case_id,
        case
          when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
          else null
        end
      ) as finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and (
        pbi.finance_case_id is not null
        or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
      )
  )
  select
    null::uuid as timesheet_id,
    rfc.candidate_id,
    'RESTRUCTURE' as key_type,
    rfc.finance_case_id::text as key_value,
    'NO_RESTRUCTURE_AFTER_BATCH_CREATED' as expected_text,
    jsonb_build_object(
      'finance_case_id', rfc.finance_case_id::text,
      'event_type', pfce.event_type,
      'event_at_utc', pfce.event_at_utc
    )::text as actual_text,
    35 as ord
  from referenced_finance_cases rfc
  join public.pay_finance_case_events pfce
    on pfce.finance_case_id = rfc.finance_case_id
  where pfce.event_at_utc >= coalesce(v_batch_created_at_utc, v_now_utc)
    and upper(coalesce(pfce.event_type, '')) like '%RESTRUCTURE%';

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with referenced_finance_cases as (
    select distinct
      pbc.candidate_id,
      coalesce(
        pbi.finance_case_id,
        case
          when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
          else null
        end
      ) as finance_case_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and (
        pbi.finance_case_id is not null
        or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
      )
  )
  select
    null::uuid as timesheet_id,
    rfc.candidate_id,
    'WRITE_OFF' as key_type,
    rfc.finance_case_id::text as key_value,
    'NOT_WRITTEN_OFF' as expected_text,
    jsonb_build_object(
      'finance_case_id', pa.id::text,
      'written_off_at_utc', pa.written_off_at_utc,
      'status', pa.status::text
    )::text as actual_text,
    36 as ord
  from referenced_finance_cases rfc
  join public.pay_advances pa
    on pa.id = rfc.finance_case_id
  where pa.written_off_at_utc is not null
    and pa.written_off_at_utc >= coalesce(v_batch_created_at_utc, v_now_utc);

  insert into pg_temp.tmp_fresh_state_diffs (
    timesheet_id,
    candidate_id,
    key_type,
    key_value,
    expected_text,
    actual_text,
    ord
  )
  with batch_ts as (
    select distinct
      pbi.timesheet_id,
      pbc.candidate_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi.timesheet_id is not null
  )
  select
    bt.timesheet_id,
    bt.candidate_id,
    'TIMESHEET_ADVANCE_OVERRIDE' as key_type,
    bt.timesheet_id::text as key_value,
    'NO_OVERRIDE_CHANGE_AFTER_BATCH_CREATED' as expected_text,
    jsonb_build_object(
      'override_id', tpo.id::text,
      'override_type', tpo.override_type,
      'created_at_utc', tpo.created_at_utc,
      'consumed_at_utc', tpo.consumed_at_utc,
      'cleared_at_utc', tpo.cleared_at_utc
    )::text as actual_text,
    37 as ord
  from batch_ts bt
  join public.timesheet_payment_overrides tpo
    on tpo.timesheet_id = bt.timesheet_id
  where greatest(
          coalesce(tpo.created_at_utc, '-infinity'::timestamptz),
          coalesce(tpo.consumed_at_utc, '-infinity'::timestamptz),
          coalesce(tpo.cleared_at_utc, '-infinity'::timestamptz)
        ) >= coalesce(v_batch_created_at_utc, v_now_utc);

  select count(*)::int
  into v_finance_reservation_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'FINANCE_RESERVATION';

  if v_finance_reservation_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'FINANCE_RESERVATION_CHANGED');
  end if;

  select count(*)::int
  into v_snooze_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'SNOOZE';

  if v_snooze_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'SNOOZE_CHANGED');
  end if;

  select count(*)::int
  into v_restructure_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'RESTRUCTURE';

  if v_restructure_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'RESTRUCTURE_CHANGED');
  end if;

  select count(*)::int
  into v_writeoff_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'WRITE_OFF';

  if v_writeoff_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'WRITE_OFF_CHANGED');
  end if;

  select count(*)::int
  into v_timesheet_override_diff_ct
  from pg_temp.tmp_fresh_state_diffs tsd
  where tsd.key_type = 'TIMESHEET_ADVANCE_OVERRIDE';

  if v_timesheet_override_diff_ct > 0 then
    v_is_stale := true;
    v_reasons := array_append(v_reasons, 'TIMESHEET_PAYMENT_OVERRIDE_CHANGED');
  end if;

  if v_scope = 'PAYE' and coalesce(v_batch_kind_fixed, '') <> 'LOANS' then
    v_paye_guardrails := public.pay_paye_guardrails(
      p_pay_date => v_pay_date,
      p_ignore_pay_batch_id => p_pay_batch_id,
      p_actor_user_id => p_actor_user_id
    );

    if coalesce((v_paye_guardrails->>'create_paye_blocked')::boolean, false) = true
       or (
            coalesce((v_paye_guardrails->>'override_required')::boolean, false) = true
            and coalesce(v_same_week_paye_override_used, false) = false
          )
    then
      insert into pg_temp.tmp_fresh_state_diffs (
        timesheet_id,
        candidate_id,
        key_type,
        key_value,
        expected_text,
        actual_text,
        ord
      )
      values (
        null,
        null,
        'PAYE_GUARDRAILS',
        p_pay_batch_id::text,
        jsonb_build_object(
          'same_week_paye_override_used', coalesce(v_same_week_paye_override_used, false)
        )::text,
        v_paye_guardrails::text,
        38
      );

      select count(*)::int
      into v_paye_guardrail_diff_ct
      from pg_temp.tmp_fresh_state_diffs tsd
      where tsd.key_type = 'PAYE_GUARDRAILS';

      if v_paye_guardrail_diff_ct > 0 then
        v_is_stale := true;
        v_reasons := array_append(v_reasons, 'PAYE_GUARDRAILS_CHANGED');
      end if;
    end if;
  end if;


  ---------------------------------------------------------------------------
  -- DEDUCTION_CHANGED: recompute expected OVERPAYMENT_RECOVERY,
  -- MANUAL_DEBT_RECOVERY, and LOAN_REPAYMENT from frozen batch-local
  -- deduction templates only. No live finance register / pay_advances
  -- authority is permitted in this post-draft branch.
  ---------------------------------------------------------------------------
  if v_scope in ('PAYE','UMBRELLA') then
    create temporary table if not exists pg_temp.tmp_fresh_recovery_templates (
      item_type text not null,
      pay_batch_candidate_id uuid not null,
      candidate_id uuid not null,
      finance_case_id uuid null,
      source_ref text null,
      pay_channel text null,
      umbrella_id uuid null,
      is_mismatch boolean null,
      paye_treatment text null,
      finance_component_id uuid null,
      frozen_component_snapshot_json jsonb null,
      frozen_component_key_type text null,
      frozen_component_key_value text null,
      frozen_component_classification public.pay_finance_component_classification_enum null,
      frozen_source_basis_json jsonb null,
      frozen_source_pay_method text null,
      frozen_target_pay_method text null,
      frozen_resolution_mode public.pay_finance_component_resolution_mode_enum null,
      frozen_resolution_payload_json jsonb null,
      frozen_resolution_result_json jsonb null,
      frozen_source_amount numeric(12,2) null,
      frozen_target_amount_ex_vat numeric(12,2) null,
      frozen_target_amount_vat numeric(12,2) null,
      frozen_target_amount_inc_vat numeric(12,2) null,
      payout_instruction_snapshot_json jsonb null,
      template_sort_at timestamptz null,
      sort_order integer not null,
      frozen_case_type text null,
      frozen_payout_status text null,
      frozen_remaining_source_amount numeric(12,2) not null,
      frozen_weekly_due_amount numeric(12,2) not null,
      frozen_next_due_week_start date null,
      minimum_earnings_threshold numeric(12,2) null,
      take_home_floor_override numeric(12,2) null,
      default_take_home_floor numeric(12,2) null
    ) on commit drop;

    truncate table pg_temp.tmp_fresh_recovery_templates;

    insert into pg_temp.tmp_fresh_recovery_templates (
      item_type,
      pay_batch_candidate_id,
      candidate_id,
      finance_case_id,
      source_ref,
      pay_channel,
      umbrella_id,
      is_mismatch,
      paye_treatment,
      finance_component_id,
      frozen_component_snapshot_json,
      frozen_component_key_type,
      frozen_component_key_value,
      frozen_component_classification,
      frozen_source_basis_json,
      frozen_source_pay_method,
      frozen_target_pay_method,
      frozen_resolution_mode,
      frozen_resolution_payload_json,
      frozen_resolution_result_json,
      frozen_source_amount,
      frozen_target_amount_ex_vat,
      frozen_target_amount_vat,
      frozen_target_amount_inc_vat,
      payout_instruction_snapshot_json,
      template_sort_at,
      sort_order,
      frozen_case_type,
      frozen_payout_status,
      frozen_remaining_source_amount,
      frozen_weekly_due_amount,
      frozen_next_due_week_start,
      minimum_earnings_threshold,
      take_home_floor_override,
      default_take_home_floor
    )
    select distinct on (
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      coalesce(
        coalesce(
          pbi_rt.finance_case_id,
          case
            when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
            else null::uuid
          end
        )::text,
        ''
      ),
      coalesce(pbi_rt.finance_component_id::text, ''),
      coalesce(pbi_rt.source_ref, '')
    )
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      pbc_rt.candidate_id,
      coalesce(
        pbi_rt.finance_case_id,
        case
          when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
          else null::uuid
        end
      ) as finance_case_id,
      pbi_rt.source_ref,
      pbi_rt.pay_channel,
      pbi_rt.umbrella_id,
      pbi_rt.is_mismatch,
      pbi_rt.paye_treatment,
      pbi_rt.finance_component_id,
      pbi_rt.frozen_component_snapshot_json,
      pbi_rt.frozen_component_key_type,
      pbi_rt.frozen_component_key_value,
      pbi_rt.frozen_component_classification,
      pbi_rt.frozen_source_basis_json,
      pbi_rt.frozen_source_pay_method,
      pbi_rt.frozen_target_pay_method,
      pbi_rt.frozen_resolution_mode,
      pbi_rt.frozen_resolution_payload_json,
      pbi_rt.frozen_resolution_result_json,
      round(coalesce(pbi_rt.frozen_source_amount, 0), 2)::numeric(12,2) as frozen_source_amount,
      round(coalesce(pbi_rt.frozen_target_amount_ex_vat, 0), 2)::numeric(12,2) as frozen_target_amount_ex_vat,
      round(coalesce(pbi_rt.frozen_target_amount_vat, 0), 2)::numeric(12,2) as frozen_target_amount_vat,
      round(coalesce(pbi_rt.frozen_target_amount_inc_vat, 0), 2)::numeric(12,2) as frozen_target_amount_inc_vat,
      pbi_rt.payout_instruction_snapshot_json,
      coalesce(pbi_rt.created_at, pbi_rt.updated_at, now()) as template_sort_at,
      case
        when nullif(btrim(coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order')), '') ~ '^-?[0-9]+$'
          then (coalesce(pbi_rt.frozen_source_basis_json->>'allocation_priority_order', pbi_rt.frozen_source_basis_json->>'sort_order', pbi_rt.frozen_resolution_payload_json->>'sort_order'))::integer
        else 2147483647
      end as sort_order,
      upper(coalesce(
        nullif(btrim(pbi_rt.frozen_source_basis_json->>'case_type'), ''),
        case pbi_rt.item_type
          when 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT'
          when 'LOAN_REPAYMENT' then 'PAYMENT_ADVANCE'
          when 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_ADJUSTMENT'
          else null
        end
      )) as frozen_case_type,
      upper(nullif(btrim(pbi_rt.frozen_source_basis_json->>'payout_status'), '')) as frozen_payout_status,
      round(greatest(
        coalesce(
          case
            when nullif(btrim(pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_component_snapshot_json->>'remaining_source_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'remaining_source_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'remaining_source_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'outstanding_amount'), '') is not null then (pbi_rt.frozen_source_basis_json->>'outstanding_amount')::numeric
            when nullif(btrim(pbi_rt.frozen_source_basis_json->>'amount'), '') is not null then abs((pbi_rt.frozen_source_basis_json->>'amount')::numeric)
            when pbi_rt.frozen_source_amount is not null then abs(pbi_rt.frozen_source_amount)
            else 0::numeric
          end,
          0::numeric
        ),
        0::numeric
      ), 2)::numeric(12,2) as frozen_remaining_source_amount,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'weekly_due'), '') is null then 0::numeric(12,2)
        else round(greatest(abs((pbi_rt.frozen_source_basis_json->>'weekly_due')::numeric), 0), 2)::numeric(12,2)
      end as frozen_weekly_due_amount,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'next_due_week_start'), '') is null then null::date
        else (pbi_rt.frozen_source_basis_json->>'next_due_week_start')::date
      end as frozen_next_due_week_start,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'minimum_earnings_threshold')::numeric, 0), 2)::numeric(12,2)
      end as minimum_earnings_threshold,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'take_home_floor_override'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'take_home_floor_override')::numeric, 0), 2)::numeric(12,2)
      end as take_home_floor_override,
      case
        when nullif(btrim(pbi_rt.frozen_source_basis_json->>'default_take_home_floor'), '') is null then null::numeric(12,2)
        else round(greatest((pbi_rt.frozen_source_basis_json->>'default_take_home_floor')::numeric, 0), 2)::numeric(12,2)
      end as default_take_home_floor
    from public.pay_batch_items pbi_rt
    join public.pay_batch_candidates pbc_rt
      on pbc_rt.id = pbi_rt.pay_batch_candidate_id
    where pbc_rt.pay_batch_id = p_pay_batch_id
      and coalesce(pbi_rt.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_rt_fresh_exclusion
        where ppc_pbi_rt_fresh_exclusion.pay_batch_item_id = pbi_rt.id
          and ppc_pbi_rt_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_rt_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi_rt.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
    order by
      pbi_rt.item_type,
      pbi_rt.pay_batch_candidate_id,
      coalesce(
        coalesce(
          pbi_rt.finance_case_id,
          case
            when pbi_rt.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_rt.source_ref, 'advance:', '')::uuid
            else null::uuid
          end
        )::text,
        ''
      ),
      coalesce(pbi_rt.finance_component_id::text, ''),
      coalesce(pbi_rt.source_ref, ''),
      pbi_rt.is_voided desc,
      coalesce(pbi_rt.updated_at, pbi_rt.created_at) desc,
      pbi_rt.id desc;

    insert into pg_temp.tmp_fresh_state_diffs (
      timesheet_id,
      candidate_id,
      key_type,
      key_value,
      expected_text,
      actual_text,
      ord
    )
    select
      null::uuid as timesheet_id,
      pbc_bad.candidate_id,
      'DEDUCTION_TEMPLATE' as key_type,
      pbi_bad.id::text as key_value,
      'FROZEN_TEMPLATE_WITH_FINANCE_CASE_ID' as expected_text,
      jsonb_build_object(
        'pay_batch_item_id', pbi_bad.id::text,
        'item_type', pbi_bad.item_type,
        'source_ref', pbi_bad.source_ref,
        'finance_case_id', pbi_bad.finance_case_id::text
      )::text as actual_text,
      30 as ord
    from public.pay_batch_items pbi_bad
    join public.pay_batch_candidates pbc_bad
      on pbc_bad.id = pbi_bad.pay_batch_candidate_id
    where pbc_bad.pay_batch_id = p_pay_batch_id
      and coalesce(pbi_bad.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_bad_fresh_exclusion
        where ppc_pbi_bad_fresh_exclusion.pay_batch_item_id = pbi_bad.id
          and ppc_pbi_bad_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_bad_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
      and pbi_bad.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY')
      and pbi_bad.finance_case_id is null;

    insert into pg_temp.tmp_fresh_expected_overpay_alloc (
      candidate_id,
      advance_id,
      take_ex,
      ord
    )
    with candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        greatest(
          coalesce(
            case
              when v_scope = 'PAYE' then pni.net_amount
              else (
                select sum(pbi_pos.amount_ex_vat)
                from public.pay_batch_items pbi_pos
                where pbi_pos.pay_batch_candidate_id = pbc.id
                  and coalesce(pbi_pos.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_pos_fresh_exclusion
        where ppc_pbi_pos_fresh_exclusion.pay_batch_item_id = pbi_pos.id
          and ppc_pbi_pos_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_pos_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
                  and pbi_pos.amount_ex_vat > 0
                  and pbi_pos.item_type in ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
              )
            end,
            0
          ),
          0
        )::numeric(12,2) as earnings_pool_ex
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'OVERPAYMENT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    alloc_base as (
      select
        cb.candidate_id,
        ct.finance_case_id,
        ct.frozen_remaining_source_amount,
        ct.sort_order,
        ct.template_sort_at,
        cb.earnings_pool_ex,
        sum(ct.frozen_remaining_source_amount) over (
          partition by cb.candidate_id
          order by ct.sort_order, ct.template_sort_at, ct.finance_case_id, ct.finance_component_id, coalesce(ct.source_ref, '')
          rows between unbounded preceding and 1 preceding
        )::numeric(12,2) as cum_before_ex
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      where (v_scope <> 'PAYE' or cb.awaiting_net_amount = false)
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'OVERPAYMENT')) = 'OVERPAYMENT'
    )
    select
      ab.candidate_id,
      ab.finance_case_id as advance_id,
      round(
        least(
          ab.frozen_remaining_source_amount,
          greatest(ab.earnings_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
        ),
        2
      )::numeric(12,2) as take_ex,
      31 as ord
    from alloc_base ab
    where round(
      least(
        ab.frozen_remaining_source_amount,
        greatest(ab.earnings_pool_ex - coalesce(ab.cum_before_ex, 0), 0)
      ),
      2
    ) > 0;

    insert into pg_temp.tmp_fresh_candidate_expected_overpay (
      candidate_id,
      expected_overpayment_recovery_ex
    )
    select
      teo.candidate_id,
      round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpayment_recovery_ex
    from pg_temp.tmp_fresh_expected_overpay_alloc teo
    group by teo.candidate_id;

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_overpay as (
      select
        coalesce(
          pbi.finance_case_id,
          case
            when pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi.amount_ex_vat, pbi.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi
      join public.pay_batch_candidates pbc
        on pbc.id = pbi.pay_batch_candidate_id
      where pbc.pay_batch_id = p_pay_batch_id
        and coalesce(pbi.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_fresh_exclusion
        where ppc_pbi_fresh_exclusion.pay_batch_item_id = pbi.id
          and ppc_pbi_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi.item_type = 'OVERPAYMENT_RECOVERY'
        and pbi.repayment_week_start = v_week_start
      group by 1
    ),
    actual_overpay as (
      select
        teo.advance_id as finance_case_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.advance_id
    ),
    union_keys as (
      select beo.finance_case_id from batch_expected_overpay beo
      union
      select ao.finance_case_id from actual_overpay ao
    )
    select
      'OVERPAYMENT_RECOVERY' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(beo.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(ao.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      31 as ord
    from union_keys uk
    left join batch_expected_overpay beo
      on beo.finance_case_id = uk.finance_case_id
    left join actual_overpay ao
      on ao.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(beo.expected_ex, 0), 2) <> round(coalesce(ao.actual_ex, 0), 2);

    insert into pg_temp.tmp_fresh_expected_loan_alloc (
      candidate_id,
      loan_id,
      take_ex,
      ord
    )
    with batch_expected_overpay_by_candidate as (
      select
        teo.candidate_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpay_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.candidate_id
    ),
    candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        greatest(coalesce(pni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'LOAN_REPAYMENT'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    loan_seed as (
      select
        cb.pay_batch_candidate_id,
        cb.candidate_id,
        ct.finance_case_id,
        ct.template_sort_at,
        ct.sort_order,
        round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        round(greatest(cb.paye_net_amount - coalesce(beo.expected_overpay_ex, 0), 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        round(greatest(cb.paye_net_amount - coalesce(beo.expected_overpay_ex, 0), 0), 2)::numeric(12,2) as run_take_home_before_ex
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      left join batch_expected_overpay_by_candidate beo
        on beo.candidate_id = cb.candidate_id
      where cb.awaiting_net_amount = false
        and ct.frozen_remaining_source_amount > 0
        and upper(coalesce(ct.frozen_case_type, 'PAYMENT_ADVANCE')) = 'PAYMENT_ADVANCE'
        and upper(coalesce(ct.frozen_payout_status, 'PAID')) = 'PAID'
        and (ct.frozen_next_due_week_start is null or ct.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(ct.frozen_weekly_due_amount, ct.frozen_remaining_source_amount, 0::numeric(12,2)), ct.frozen_remaining_source_amount), 0), 2) > 0
    ),
    loan_inputs as (
      select
        ls.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ls.sort_order,
              'finance_case_id', ls.finance_case_id::text,
              'case_type', 'PAYMENT_ADVANCE',
              'payout_status', 'PAID',
              'nominal_due_amount', ls.nominal_due_amount,
              'minimum_earnings_threshold', ls.minimum_earnings_threshold,
              'take_home_floor_override', ls.take_home_floor_override
            )
            order by ls.sort_order, ls.template_sort_at, ls.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ls.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ls.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex
      from loan_seed ls
      group by ls.candidate_id
    ),
    loan_alloc as (
      select
        li.candidate_id,
        lra.finance_case_id,
        round(coalesce(lra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from loan_inputs li
      cross join lateral public._pay_finance_protected_recovery_allocate(
        li.recovery_rows_json,
        li.run_earnings_headroom_ex,
        li.run_take_home_before_ex,
        null::numeric
      ) lra
    )
    select
      la.candidate_id,
      la.finance_case_id as loan_id,
      la.take_ex,
      33 as ord
    from loan_alloc la
    where round(coalesce(la.take_ex, 0), 2) > 0;

    insert into pg_temp.tmp_fresh_expected_manual_debt_alloc (
      candidate_id,
      finance_case_id,
      take_ex,
      ord
    )
    with batch_expected_overpay_by_candidate as (
      select
        teo.candidate_id,
        round(sum(teo.take_ex), 2)::numeric(12,2) as expected_overpay_ex
      from pg_temp.tmp_fresh_expected_overpay_alloc teo
      group by teo.candidate_id
    ),
    batch_expected_loan_by_candidate as (
      select
        tel.candidate_id,
        round(sum(tel.take_ex), 2)::numeric(12,2) as expected_loan_ex
      from pg_temp.tmp_fresh_expected_loan_alloc tel
      group by tel.candidate_id
    ),
    candidate_basis as (
      select
        pbc.id as pay_batch_candidate_id,
        pbc.candidate_id,
        coalesce(pbc.awaiting_net_amount, false) as awaiting_net_amount,
        round(greatest(coalesce(pbc.gross_preview, 0), 0), 2)::numeric(12,2) as gross_preview_ex,
        greatest(coalesce(pni.net_amount, 0), 0)::numeric(12,2) as paye_net_amount,
        case
          when v_scope = 'PAYE' then round(greatest(coalesce(pni.net_amount, 0), 0), 2)::numeric(12,2)
          else null::numeric(12,2)
        end as run_take_home_base_ex
      from public.pay_batch_candidates pbc
      left join lateral (
        select pni_inner.net_amount
        from public.pay_batch_paye_net_inputs pni_inner
        where pni_inner.pay_batch_candidate_id = pbc.id
        order by pni_inner.imported_at_utc desc
        limit 1
      ) pni on true
      where pbc.pay_batch_id = p_pay_batch_id
    ),
    case_templates as (
      select distinct on (rt.pay_batch_candidate_id, rt.finance_case_id, coalesce(rt.finance_component_id::text, ''), coalesce(rt.source_ref, ''))
        rt.*
      from pg_temp.tmp_fresh_recovery_templates rt
      where rt.item_type = 'MANUAL_DEBT_RECOVERY'
        and rt.finance_case_id is not null
      order by
        rt.pay_batch_candidate_id,
        rt.finance_case_id,
        coalesce(rt.finance_component_id::text, ''),
        coalesce(rt.source_ref, ''),
        rt.sort_order,
        rt.template_sort_at,
        rt.finance_component_id nulls last,
        rt.source_ref nulls last
    ),
    manual_template_values as (
      select
        cb.pay_batch_candidate_id,
        cb.candidate_id,
        ct.finance_case_id,
        ct.template_sort_at,
        ct.sort_order,
        ct.frozen_case_type,
        ct.frozen_next_due_week_start,
        ct.minimum_earnings_threshold,
        ct.take_home_floor_override,
        ct.frozen_weekly_due_amount,
        ct.frozen_remaining_source_amount,
        nullif(ct.default_take_home_floor, 0)::numeric(12,2) as default_take_home_floor,
        round(greatest(cb.gross_preview_ex, 0), 2)::numeric(12,2) as run_earnings_headroom_ex,
        case
          when v_scope = 'PAYE' then round(greatest(coalesce(cb.run_take_home_base_ex, 0) - coalesce(beo.expected_overpay_ex, 0) - coalesce(bl.expected_loan_ex, 0), 0), 2)::numeric(12,2)
          else null::numeric(12,2)
        end as run_take_home_before_ex,
        sched_md.scheduled_due_amount
      from candidate_basis cb
      join case_templates ct
        on ct.pay_batch_candidate_id = cb.pay_batch_candidate_id
      left join batch_expected_overpay_by_candidate beo
        on beo.candidate_id = cb.candidate_id
      left join batch_expected_loan_by_candidate bl
        on bl.candidate_id = cb.candidate_id
      left join lateral (
        select
          round(greatest(abs((sched_item.value->>'amount')::numeric), 0), 2)::numeric(12,2) as scheduled_due_amount
        from jsonb_array_elements(
          case
            when jsonb_typeof(coalesce(ct.frozen_source_basis_json->'schedule_json', '[]'::jsonb)) = 'array'
              then coalesce(ct.frozen_source_basis_json->'schedule_json', '[]'::jsonb)
            else '[]'::jsonb
          end
        ) as sched_item(value)
        where nullif(btrim(sched_item.value->>'week_start'), '') is not null
          and (sched_item.value->>'week_start')::date = v_week_start
        limit 1
      ) sched_md on true
      where (v_scope <> 'PAYE' or cb.awaiting_net_amount = false)
    ),
    manual_seed as (
      select
        mtv.candidate_id,
        mtv.finance_case_id,
        mtv.template_sort_at,
        mtv.sort_order,
        round(greatest(least(coalesce(mtv.scheduled_due_amount, mtv.frozen_weekly_due_amount, 0::numeric(12,2)), mtv.frozen_remaining_source_amount), 0), 2)::numeric(12,2) as nominal_due_amount,
        mtv.minimum_earnings_threshold,
        mtv.take_home_floor_override,
        mtv.run_earnings_headroom_ex,
        mtv.run_take_home_before_ex,
        mtv.default_take_home_floor
      from manual_template_values mtv
      where upper(coalesce(mtv.frozen_case_type, 'MANUAL_DEBT_ADJUSTMENT')) = 'MANUAL_DEBT_ADJUSTMENT'
        and mtv.frozen_remaining_source_amount > 0
        and (mtv.frozen_next_due_week_start is null or mtv.frozen_next_due_week_start <= v_week_start)
        and round(greatest(least(coalesce(mtv.scheduled_due_amount, mtv.frozen_weekly_due_amount, 0::numeric(12,2)), mtv.frozen_remaining_source_amount), 0), 2) > 0
    ),
    manual_inputs as (
      select
        ms.candidate_id,
        coalesce(
          jsonb_agg(
            jsonb_build_object(
              'sort_order', ms.sort_order,
              'finance_case_id', ms.finance_case_id::text,
              'case_type', 'MANUAL_DEBT_ADJUSTMENT',
              'payout_status', null,
              'nominal_due_amount', ms.nominal_due_amount,
              'minimum_earnings_threshold', ms.minimum_earnings_threshold,
              'take_home_floor_override', ms.take_home_floor_override
            )
            order by ms.sort_order, ms.template_sort_at, ms.finance_case_id
          ),
          '[]'::jsonb
        ) as recovery_rows_json,
        max(ms.run_earnings_headroom_ex)::numeric(12,2) as run_earnings_headroom_ex,
        max(ms.run_take_home_before_ex)::numeric(12,2) as run_take_home_before_ex,
        nullif(max(ms.default_take_home_floor), 0)::numeric(12,2) as default_take_home_floor
      from manual_seed ms
      group by ms.candidate_id
    ),
    manual_alloc as (
      select
        mi.candidate_id,
        mdra.finance_case_id,
        round(coalesce(mdra.protected_recoverable_amount, 0), 2)::numeric(12,2) as take_ex
      from manual_inputs mi
      cross join lateral public._pay_finance_protected_recovery_allocate(
        mi.recovery_rows_json,
        mi.run_earnings_headroom_ex,
        mi.run_take_home_before_ex,
        mi.default_take_home_floor
      ) mdra
    )
    select
      ma.candidate_id,
      ma.finance_case_id,
      ma.take_ex,
      32 as ord
    from manual_alloc ma
    where round(coalesce(ma.take_ex, 0), 2) > 0;

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_manual as (
      select
        coalesce(
          pbi_md.finance_case_id,
          case
            when pbi_md.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_md.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi_md.amount_ex_vat, pbi_md.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi_md
      join public.pay_batch_candidates pbc_md
        on pbc_md.id = pbi_md.pay_batch_candidate_id
      where pbc_md.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_md.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_md_fresh_exclusion
        where ppc_pbi_md_fresh_exclusion.pay_batch_item_id = pbi_md.id
          and ppc_pbi_md_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_md_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi_md.item_type = 'MANUAL_DEBT_RECOVERY'
        and pbi_md.repayment_week_start = v_week_start
      group by 1
    ),
    actual_manual as (
      select
        temd.finance_case_id,
        round(sum(temd.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_manual_debt_alloc temd
      group by temd.finance_case_id
    ),
    union_keys as (
      select bem.finance_case_id from batch_expected_manual bem
      union
      select am.finance_case_id from actual_manual am
    )
    select
      'MANUAL_DEBT_RECOVERY' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(bem.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(am.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      32 as ord
    from union_keys uk
    left join batch_expected_manual bem
      on bem.finance_case_id = uk.finance_case_id
    left join actual_manual am
      on am.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(bem.expected_ex, 0), 2) <> round(coalesce(am.actual_ex, 0), 2);

    insert into pg_temp.tmp_fresh_deduction_diffs (
      key_type,
      key_value,
      expected_ex,
      actual_ex,
      ord
    )
    with batch_expected_loans as (
      select
        coalesce(
          pbi_ln.finance_case_id,
          case
            when pbi_ln.source_ref ~ '^advance:[0-9a-fA-F-]{36}$' then replace(pbi_ln.source_ref, 'advance:', '')::uuid
            else null
          end
        ) as finance_case_id,
        round(sum(-coalesce(pbi_ln.amount_ex_vat, pbi_ln.amount_inc_vat, 0)), 2)::numeric(12,2) as expected_ex
      from public.pay_batch_items pbi_ln
      join public.pay_batch_candidates pbc_ln
        on pbc_ln.id = pbi_ln.pay_batch_candidate_id
      where pbc_ln.pay_batch_id = p_pay_batch_id
        and coalesce(pbi_ln.is_voided, false) = false
      and not exists (
        select 1
        from public.pay_payment_correction_items as ppc_pbi_ln_fresh_exclusion
        where ppc_pbi_ln_fresh_exclusion.pay_batch_item_id = pbi_ln.id
          and ppc_pbi_ln_fresh_exclusion.status = 'APPLIED'
          and ppc_pbi_ln_fresh_exclusion.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
      )
        and pbi_ln.item_type = 'LOAN_REPAYMENT'
        and pbi_ln.repayment_week_start = v_week_start
      group by 1
    ),
    actual_loans as (
      select
        tel.loan_id as finance_case_id,
        round(sum(tel.take_ex), 2)::numeric(12,2) as actual_ex
      from pg_temp.tmp_fresh_expected_loan_alloc tel
      group by tel.loan_id
    ),
    union_keys as (
      select bel.finance_case_id from batch_expected_loans bel
      union
      select al.finance_case_id from actual_loans al
    )
    select
      'LOAN_REPAYMENT' as key_type,
      uk.finance_case_id::text as key_value,
      round(coalesce(bel.expected_ex, 0), 2)::numeric(12,2) as expected_ex,
      round(coalesce(al.actual_ex, 0), 2)::numeric(12,2) as actual_ex,
      33 as ord
    from union_keys uk
    left join batch_expected_loans bel
      on bel.finance_case_id = uk.finance_case_id
    left join actual_loans al
      on al.finance_case_id = uk.finance_case_id
    where uk.finance_case_id is not null
      and round(coalesce(bel.expected_ex, 0), 2) <> round(coalesce(al.actual_ex, 0), 2);

    select count(*)::int
    into v_overpay_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'OVERPAYMENT_RECOVERY';

    select count(*)::int
    into v_manual_debt_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'MANUAL_DEBT_RECOVERY';

    select count(*)::int
    into v_loan_ded_diff_ct
    from pg_temp.tmp_fresh_deduction_diffs tdd
    where tdd.key_type = 'LOAN_REPAYMENT';

    v_ded_diff_ct := coalesce(v_overpay_ded_diff_ct, 0)
                     + coalesce(v_manual_debt_ded_diff_ct, 0)
                     + coalesce(v_loan_ded_diff_ct, 0);

    if exists (
      select 1
      from pg_temp.tmp_fresh_state_diffs tsd
      where tsd.key_type = 'DEDUCTION_TEMPLATE'
    ) then
      v_is_stale := true;
      v_reasons := array_append(v_reasons, 'DEDUCTION_TEMPLATE_MISSING');
    end if;

    if v_ded_diff_ct > 0 then
      v_is_stale := true;
      v_reasons := array_append(v_reasons, 'DEDUCTION_CHANGED');
    end if;
  end if;
  ---------------------------------------------------------------------------
  -- PAYE_NET_CHANGED:
  -- PAYE net entry and PAYE net edits are draft-owned mutable batch data,
  -- not live-truth freshness drift. Users must be able to enter, save,
  -- revisit, and amend PAYE net values on an existing draft without making
  -- the batch stale.
  --
  -- Real live-truth drift for the batch remains covered by the economic-key,
  -- reservation, deduction, snooze, override, restructuring, writeoff, and
  -- guardrail checks above. PAYE_NET is therefore intentionally excluded from
  -- stale detection here.
  ---------------------------------------------------------------------------
  if v_scope = 'PAYE' and coalesce(v_batch_kind_fixed,'') <> 'LOANS' then
    v_paye_net_diff_ct := 0;
  end if;

  ---------------------------------------------------------------------------
  -- Build final diff array from the temp diff tables.
  ---------------------------------------------------------------------------
  with diff_rows as (
    select
      t.ord,
      coalesce(t.timesheet_id::text, '') as sort1,
      t.key_type as sort2,
      t.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', t.timesheet_id::text,
        'key_type', t.key_type,
        'key_value', t.key_value,
        'expected', t.expected_text,
        'actual', t.actual_text
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_ts_diffs t0
      order by coalesce(t0.timesheet_id::text, ''), t0.key_type, t0.key_value
      limit v_diff_limit
    ) t

    union all

    select
      k.ord,
      coalesce(k.timesheet_id::text, '') as sort1,
      k.key_type as sort2,
      k.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', k.timesheet_id::text,
        'key_type', k.key_type,
        'key_value', k.key_value,
        'expected', k.expected_ex,
        'actual', k.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_key_diffs k0
      order by coalesce(k0.timesheet_id::text, ''), k0.key_type, k0.key_value
      limit v_diff_limit
    ) k

    union all

    select
      d.ord,
      '' as sort1,
      d.key_type as sort2,
      d.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', d.key_type,
        'key_value', d.key_value,
        'expected', d.expected_ex,
        'actual', d.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_deduction_diffs d0
      order by d0.ord, d0.key_type, d0.key_value
      limit v_diff_limit
    ) d

    union all

    select
      p.ord,
      p.candidate_id::text as sort1,
      p.key_type as sort2,
      p.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', p.key_type,
        'key_value', p.key_value,
        'expected', p.expected_ex,
        'actual', p.actual_ex
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_paye_net_diffs p0
      order by p0.candidate_id::text, p0.key_type, p0.key_value
      limit v_diff_limit
    ) p

    union all

    select
      s.ord,
      coalesce(s.candidate_id::text, coalesce(s.timesheet_id::text, '')) as sort1,
      s.key_type as sort2,
      s.key_value as sort3,
      jsonb_build_object(
        'timesheet_id', s.timesheet_id::text,
        'key_type', s.key_type,
        'key_value', s.key_value,
        'expected', s.expected_text,
        'actual', s.actual_text
      ) as diff_json
    from (
      select *
      from pg_temp.tmp_fresh_state_diffs s0
      order by coalesce(s0.candidate_id::text, coalesce(s0.timesheet_id::text, '')), s0.key_type, s0.key_value
      limit v_diff_limit
    ) s

    union all

    select
      99 as ord,
      '' as sort1,
      'INFO' as sort2,
      'COUNTS' as sort3,
      jsonb_build_object(
        'timesheet_id', null,
        'key_type', 'INFO',
        'key_value', 'COUNTS',
        'expected', jsonb_build_object(
          'ts_changed', v_ts_changed_ct,
          'key_diffs', v_key_diff_ct,
          'finance_reservation_diffs', v_finance_reservation_diff_ct,
          'snooze_diffs', v_snooze_diff_ct,
          'restructure_diffs', v_restructure_diff_ct,
          'writeoff_diffs', v_writeoff_diff_ct,
          'timesheet_override_diffs', v_timesheet_override_diff_ct,
          'paye_guardrail_diffs', v_paye_guardrail_diff_ct,
          'ded_diffs', v_ded_diff_ct,
          'overpayment_ded_diffs', v_overpay_ded_diff_ct,
          'manual_debt_ded_diffs', v_manual_debt_ded_diff_ct,
          'loan_ded_diffs', v_loan_ded_diff_ct,
          'paye_net_diffs', v_paye_net_diff_ct
        ),
        'actual', null
      ) as diff_json
  )
  select
    coalesce(
      jsonb_agg(dr.diff_json order by dr.ord, dr.sort1, dr.sort2, dr.sort3),
      '[]'::jsonb
    )
  into v_diffs
  from diff_rows dr;

  if array_length(v_reasons,1) is not null then
    select coalesce(array_agg(distinct r order by r), array[]::text[])
    into v_reasons
    from unnest(v_reasons) r;
  end if;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_VALIDATE_FRESHNESS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'pay_date', v_pay_date::text,
        'week_start', v_week_start::text,
        'batch_kind_fixed', coalesce(v_batch_kind_fixed, null),
        'scope', coalesce(v_scope, null),
        'is_stale', v_is_stale,
        'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
        'counts', jsonb_build_object(
          'timesheet_changed', v_ts_changed_ct,
          'stable_key_diffs', v_key_diff_ct,
          'finance_reservation_diffs', v_finance_reservation_diff_ct,
          'snooze_diffs', v_snooze_diff_ct,
          'restructure_diffs', v_restructure_diff_ct,
          'writeoff_diffs', v_writeoff_diff_ct,
          'timesheet_override_diffs', v_timesheet_override_diff_ct,
          'paye_guardrail_diffs', v_paye_guardrail_diff_ct,
          'deduction_diffs', v_ded_diff_ct,
          'overpayment_deduction_diffs', v_overpay_ded_diff_ct,
          'manual_debt_deduction_diffs', v_manual_debt_ded_diff_ct,
          'loan_deduction_diffs', v_loan_ded_diff_ct,
          'paye_net_diffs', v_paye_net_diff_ct
        )
      ),
      'pay_batches',
      p_pay_batch_id::text
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'is_stale', v_is_stale,
    'stale_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
    'diff', coalesce(v_diffs, '[]'::jsonb)
  );
end;
$function$;




create or replace function public.pay_batch_export_csv_rows(
  p_pay_batch_id uuid,
  p_actor_user_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();

  v_batch record;
  v_batch_kind text := null;
  v_channels text[] := null;

  v_is_cancelled boolean := false;
  v_execution_commit_state text := 'NOT_SUBMITTED';
  v_execution_commit_ref text := null;
  v_execution_committed_at_utc timestamptz := null;
  v_pre_execution_export boolean := false;
  v_freshness_validation_status text := null;
  v_freshness_result_hash text := null;
  v_freshness_scope_hash text := null;
  v_freshness_result_json jsonb := '{}'::jsonb;

  v_fresh jsonb := null;
  v_is_stale boolean := false;
  v_stale_reasons jsonb := '[]'::jsonb;
  v_diff_sample jsonb := '[]'::jsonb;

  v_rows jsonb := '[]'::jsonb;
  v_row_count int := 0;
  v_kind_counts jsonb := '{}'::jsonb;
begin
  if p_pay_batch_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: pay_batch_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_batch_export_csv_rows: actor_user_id is required',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  select
    pb.id,
    pb.status,
    pb.pay_date,
    pb.cancelled_at_utc,
    pb.batch_kind_fixed,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.freshness_validation_status,
    pb.freshness_result_hash,
    pb.freshness_scope_hash,
    pb.freshness_result_json,
    pb.freshness_operation_id
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
      'code', 'PAY_BATCH_NOT_FOUND',
      'message', 'pay_batch_export_csv_rows: pay_batch not found',
      'pay_batch_id', p_pay_batch_id::text
    )::text;
  end if;

  v_is_cancelled := (
    v_batch.cancelled_at_utc is not null
    or upper(btrim(coalesce(v_batch.status, ''))) in ('CANCELLED', 'CANCELED')
  );
  v_execution_commit_state := upper(btrim(coalesce(v_batch.execution_commit_state, 'NOT_SUBMITTED')));
  if v_execution_commit_state not in ('NOT_SUBMITTED', 'SUBMITTED_NOT_COMMITTED', 'COMMITTED') then
    v_execution_commit_state := 'NOT_SUBMITTED';
  end if;
  v_execution_commit_ref := nullif(btrim(coalesce(v_batch.execution_commit_ref, '')), '');
  v_execution_committed_at_utc := v_batch.execution_committed_at_utc;
  v_freshness_validation_status := upper(btrim(coalesce(v_batch.freshness_validation_status, '')));
  v_freshness_result_hash := nullif(btrim(coalesce(v_batch.freshness_result_hash, '')), '');
  v_freshness_scope_hash := nullif(btrim(coalesce(v_batch.freshness_scope_hash, '')), '');
  v_freshness_result_json := coalesce(v_batch.freshness_result_json, '{}'::jsonb);
  v_pre_execution_export := (
    v_is_cancelled = false
    and v_execution_commit_state = 'NOT_SUBMITTED'
    and v_execution_commit_ref is null
    and v_execution_committed_at_utc is null
  );

  select ch.channels
  into v_channels
  from (
    select
      array_agg(distinct upper(coalesce(pbi.pay_channel,'')) order by upper(coalesce(pbi.pay_channel,'')))
        filter (where upper(coalesce(pbi.pay_channel,'')) in ('PAYE','UMBRELLA')) as channels
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbc.pay_batch_id = p_pay_batch_id
      and pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ) ch;

  v_batch_kind := case
    when v_channels is null then null
    when array_position(v_channels,'PAYE') is not null and array_position(v_channels,'UMBRELLA') is not null then 'MIXED'
    when array_position(v_channels,'PAYE') is not null then 'PAYE'
    when array_position(v_channels,'UMBRELLA') is not null then 'UMBRELLA'
    else null
  end;

  if upper(coalesce(v_batch.batch_kind_fixed,'')) = 'LOANS' then
    v_batch_kind := 'LOANS';
  end if;

  if v_pre_execution_export then
    if v_freshness_validation_status = 'PASSED' and v_freshness_result_hash is not null then
      v_fresh := jsonb_build_object(
        'is_stale', false,
        'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
        'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
        'freshness_validation_status', v_freshness_validation_status,
        'freshness_result_hash', v_freshness_result_hash,
        'freshness_scope_hash', v_freshness_scope_hash,
        'source', 'stored_chunked_freshness'
      );
      v_is_stale := false;
      v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
      v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
    else
      v_fresh := public.pay_batch_validate_freshness(
        p_pay_batch_id => p_pay_batch_id,
        p_actor_user_id => p_actor_user_id,
        p_allow_large_full_scan => false
      );

      v_is_stale := coalesce((v_fresh->>'is_stale')::boolean, false);
      v_stale_reasons := coalesce(v_fresh->'stale_reasons', '[]'::jsonb);

      select coalesce(jsonb_agg(x.elem), '[]'::jsonb)
      into v_diff_sample
      from (
        select elem
        from jsonb_array_elements(coalesce(v_fresh->'diff','[]'::jsonb)) as elem
        limit 50
      ) x;

      if v_is_stale = true then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_BATCH_EXPORT_CSV_ROWS',
          'code', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'FRESHNESS_REQUIRES_CHUNKED_VALIDATION' else 'BATCH_STALE' end,
          'message', case when coalesce((v_fresh->>'requires_chunked_freshness')::boolean, false) then 'pay_batch_export_csv_rows: chunked freshness validation is required before payment-initiation export' else 'pay_batch_export_csv_rows: batch is stale; regenerate draft before exporting' end,
          'pay_batch_id', p_pay_batch_id::text,
          'stale_reasons', v_stale_reasons,
          'diff', v_diff_sample,
          'freshness_validation_status', v_freshness_validation_status,
          'freshness_result_hash', v_freshness_result_hash,
          'freshness_scope_hash', v_freshness_scope_hash
        )::text;
      end if;
    end if;
  else
    v_fresh := jsonb_build_object(
      'is_stale', coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false),
      'stale_reasons', coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb),
      'diff', coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb),
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'source', 'stored_freshness_metadata_non_blocking'
    );
    v_is_stale := coalesce(v_freshness_validation_status in ('STALE', 'FAILED'), false);
    v_stale_reasons := coalesce(v_freshness_result_json->'stale_reasons', '[]'::jsonb);
    v_diff_sample := coalesce(v_freshness_result_json->'diff_sample', '[]'::jsonb);
  end if;

  create temp table if not exists _tmp_pay_export_rows (
    sort_surname text not null,
    sort_group int not null,
    sort_work_date date null,
    sort_timesheet_id uuid null,
    sort_line_rank int not null,
    sort_bucket_code text null,
    sort_unit_name text null,
    line_kind text not null,
    row_json jsonb not null
  ) on commit drop;

  truncate table _tmp_pay_export_rows;

  insert into _tmp_pay_export_rows(
    sort_surname,
    sort_group,
    sort_work_date,
    sort_timesheet_id,
    sort_line_rank,
    sort_bucket_code,
    sort_unit_name,
    line_kind,
    row_json
  )
  with
  net_latest as (
    select
      pbc.id as pay_batch_candidate_id,
      (
        select pni.net_amount
        from public.pay_batch_paye_net_inputs pni
        where pni.pay_batch_candidate_id = pbc.id
        order by pni.imported_at_utc desc
        limit 1
      ) as paye_net_amount
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = p_pay_batch_id
  ),
  base as (
    select
      pbc.candidate_id as candidate_id,
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_tms_ref as candidate_tms_ref_snap,
      pbc.candidate_display_name as candidate_display_name_snap,

      c.first_name as cand_first_name,
      c.last_name as cand_last_name,
      c.tms_ref as cand_tms_ref_live,

      pbi.id as pay_batch_item_id,
      pbi.item_type as item_type,
      pbi.timesheet_id as timesheet_id,
      pbi.segment_key as segment_key,
      pbi.source_ref as source_ref,
      pbi.description as item_description,
      pbi.pay_channel as pay_channel,
      pbi.repayment_week_start as repayment_week_start,
      pbi.finance_case_id as finance_case_id,
      pbi.finance_component_id as finance_component_id,
      pbi.paye_treatment as paye_treatment,
      pbi.payout_instruction_snapshot_json as payout_instruction_snapshot_json,
      coalesce(pbi.frozen_component_snapshot_json, '{}'::jsonb) as frozen_component_snapshot_json,
      coalesce(pbi.frozen_source_basis_json, '{}'::jsonb) as frozen_source_basis_json,
      pbi.frozen_resolution_mode as frozen_resolution_mode,
      pbi.frozen_resolution_payload_json as frozen_resolution_payload_json,
      pbi.frozen_resolution_result_json as frozen_resolution_result_json,
      pbi.frozen_source_amount as frozen_source_amount,
      pbi.frozen_target_amount_ex_vat as frozen_target_amount_ex_vat,

      pbib.line_kind as line_kind,
      pbib.bucket_code as bucket_code,
      pbib.unit_name as unit_name,
      pbib.units as units,
      pbib.rate as rate,
      pbib.amount_ex_vat as amount_ex_vat,
      pbib.amount_vat as amount_vat,
      pbib.amount_inc_vat as amount_inc_vat,
      coalesce(pbib.meta_json, '{}'::jsonb) as breakdown_meta_json,

      ecomp.key_type as economic_key_type,
      ecomp.key_value as economic_key_value,
      ecomp.source_amount_ex_vat as economic_source_amount_ex_vat,
      ecomp.target_amount_ex_vat as economic_target_amount_ex_vat,
      ecomp.key_resolution_source as economic_key_resolution_source,
      ecomp.key_resolution_failure_reason as economic_key_resolution_failure_reason,

      ts.week_ending_date as week_ending_date,
      ts.reference_number as reference_number,
      cl.id as client_id,
      cl.name as client_name,

      nl.paye_net_amount as paye_net_amount,

      segd.work_date as seg_work_date,

      vfcr.case_type as finance_case_type,
      vfcr.taxability as finance_taxability,
      vfcr.routing_kind as finance_routing_kind,
      vfcr.management_group as finance_management_group,
      vfcr.lifecycle_status_display as finance_lifecycle_status_display,
      vfcr.status as finance_status,
      vfcr.payout_status as finance_payout_status,
      vfcr.adjustment_comment as finance_adjustment_comment,
      vfcr.notes as finance_notes,
      vfcr.is_candidate_directed_oneoff_payout as is_candidate_directed_oneoff_payout,
      vfcr.appears_on_umbrella_remittance as appears_on_umbrella_remittance,
      vfcr.generates_candidate_payment_advice as generates_candidate_payment_advice,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_created_by_user_id,

      case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end as bank_details_updated_by_user_id,

      tuc.display_name as bank_details_created_by_display_name,
      tuc.email as bank_details_created_by_email,
      tuu.display_name as bank_details_updated_by_display_name,
      tuu.email as bank_details_updated_by_email,

      case
        when coalesce(ecomp.key_type,'') = 'TS_DAY' and coalesce(ecomp.key_value,'') ~ '^\d{4}-\d{2}-\d{2}$' then ecomp.key_value::date
        else null::date
      end as economic_work_date,

      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_units','')), ''))::numeric
        else pbib.units
      end as source_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_units','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_units','')), ''))::numeric
        else pbib.units
      end as target_units,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_source_basis_json->>'source_rate','')), ''))::numeric
        else pbib.rate
      end as source_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_rate','')), ''))::numeric
        else pbib.rate
      end as target_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_pay_ex_vat','')), ''))::numeric
        else ecomp.source_amount_ex_vat
      end as source_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_amount_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_pay_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_pay_ex_vat','')), ''))::numeric
        else coalesce(ecomp.target_amount_ex_vat, pbib.amount_ex_vat)
      end as target_amount_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_rate','')), ''))::numeric
        else null::numeric
      end as source_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_rate','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_rate','')), ''))::numeric
        else null::numeric
      end as target_charge_rate,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'source_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'source_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as source_charge_ex_vat,
      case
        when nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbib.meta_json->>'target_charge_ex_vat','')), ''))::numeric
        when nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), '') ~ '^-?\d+(\.\d+)?$' then (nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'target_charge_ex_vat','')), ''))::numeric
        else null::numeric
      end as target_charge_ex_vat,
      coalesce(
        nullif(btrim(coalesce(pbib.meta_json->>'resolution_mode','')), ''),
        nullif(btrim(coalesce(pbi.frozen_resolution_mode::text,'')), ''),
        nullif(btrim(coalesce(pbi.frozen_component_snapshot_json->>'resolution_mode','')), '')
      ) as resolution_mode,
      coalesce(
        nullif(pbib.meta_json->'resolution_payload_json', 'null'::jsonb),
        pbi.frozen_resolution_payload_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_payload_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_payload_json', 'null'::jsonb)
      ) as resolution_payload_json,
      coalesce(
        nullif(pbib.meta_json->'resolution_result_json', 'null'::jsonb),
        pbi.frozen_resolution_result_json,
        nullif(pbi.frozen_component_snapshot_json->'resolution_result_json', 'null'::jsonb),
        nullif(pbi.frozen_component_snapshot_json->'saved_resolution_result_json', 'null'::jsonb)
      ) as resolution_result_json
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
     and pbc.pay_batch_id = p_pay_batch_id
    join public.pay_batch_item_breakdowns pbib
      on pbib.pay_batch_item_id = pbi.id
    left join public._pay_batch_item_economic_components(p_pay_batch_id, null::uuid[]) ecomp
      on ecomp.pay_batch_item_id = pbi.id
    left join public.candidates c
      on c.id = pbc.candidate_id
    left join public.timesheets ts
      on ts.timesheet_id = pbi.timesheet_id
     and ts.is_current = true
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cl
      on cl.id = ct.client_id
    left join net_latest nl
      on nl.pay_batch_candidate_id = pbc.id
    left join public.pay_batch_timesheet_snapshots pbts
      on pbts.pay_batch_id = p_pay_batch_id
     and pbts.timesheet_id = pbi.timesheet_id
     and pbts.candidate_id = pbc.candidate_id
     and upper(coalesce(pbts.pay_channel,'')) = upper(coalesce(pbi.pay_channel,''))
    left join lateral (
      select
        nullif(btrim(coalesce(seg->>'date','')),'')::date as work_date
      from jsonb_array_elements(coalesce(pbts.target_snapshot_json->'segments','[]'::jsonb)) seg
      where pbi.item_type = 'SEGMENT_DELTA'
        and seg is not null
        and jsonb_typeof(seg) = 'object'
        and nullif(btrim(coalesce(seg->>'segment_id','')),'') = coalesce(
          nullif(btrim(coalesce(pbi.segment_key,'')), ''),
          case
            when pbi.source_ref is not null and btrim(coalesce(pbi.source_ref,'')) like 'seg:%'
              then nullif(btrim(split_part(pbi.source_ref,':',2)),'')
            else null
          end
        )
        and nullif(btrim(coalesce(seg->>'date','')),'') ~ '^\d{4}-\d{2}-\d{2}$'
      limit 1
    ) segd on true
    left join public.v_finance_cases_register vfcr
      on vfcr.finance_case_id = pbi.finance_case_id
    left join public.tms_users tuc
      on tuc.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_created_by_user_id','')), ''))::uuid
        else null::uuid
      end
    left join public.tms_users tuu
      on tuu.id = case
        when nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
          then (nullif(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'bank_details_updated_by_user_id','')), ''))::uuid
        else null::uuid
      end
    where pbi.item_type <> 'DEBT_CREATED'
      and pbi.is_voided = false
  ),
  rows0 as (
    select
      coalesce(
        nullif(btrim(coalesce(b.cand_last_name,'')), ''),
        nullif(btrim(regexp_replace(coalesce(b.candidate_display_name_snap,''), '^.*\s', '')), ''),
        nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
        b.candidate_id::text
      ) as sort_surname,

      case
        when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 3
        when b.timesheet_id is null then 2
        else 1
      end as sort_group,

      coalesce(b.economic_work_date, b.seg_work_date, b.week_ending_date, b.repayment_week_start) as sort_work_date,

      b.timesheet_id as sort_timesheet_id,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 900
        when b.item_type = 'LOAN_REPAYMENT' then 910
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 915
        when b.item_type = 'LOAN_PAYOUT' then 920
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 930
        else case upper(coalesce(b.line_kind,''))
          when 'TS_BUCKET' then 100
          when 'ADDITIONAL_UNIT' then 200
          when 'MILEAGE' then 300
          when 'EXPENSE' then 400
          when 'ADJUSTMENT' then 500
          when 'CONVERSION_ADJ' then 600
          when 'DEBT_CREATED' then 950
          else 800
        end
      end as sort_line_rank,

      upper(nullif(btrim(coalesce(b.bucket_code,'')),'')) as sort_bucket_code,
      nullif(btrim(coalesce(b.unit_name,'')),'') as sort_unit_name,

      case
        when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
        when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
        when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
        when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
        when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
        else upper(coalesce(b.line_kind,''))
      end as line_kind,

      jsonb_strip_nulls(
        jsonb_build_object(
          'candidate_id', b.candidate_id::text,
          'candidate_tms_ref', coalesce(
            nullif(btrim(coalesce(b.candidate_tms_ref_snap,'')), ''),
            nullif(btrim(coalesce(b.cand_tms_ref_live,'')), ''),
            null
          ),
          'candidate_first_name', nullif(btrim(coalesce(b.cand_first_name,'')), ''),
          'candidate_last_name', nullif(btrim(coalesce(b.cand_last_name,'')), ''),
          'candidate_display_name', nullif(btrim(coalesce(b.candidate_display_name_snap,'')), ''),
          'client_id', case when b.client_id is null then null else b.client_id::text end,
          'client_name', b.client_name,
          'timesheet_id', case when b.timesheet_id is null then null else b.timesheet_id::text end,
          'week_ending_date', case when b.week_ending_date is null then null else b.week_ending_date::text end,
          'work_date', case
            when b.economic_work_date is not null then b.economic_work_date::text
            when b.seg_work_date is not null then b.seg_work_date::text
            when b.week_ending_date is not null then b.week_ending_date::text
            when b.repayment_week_start is not null then b.repayment_week_start::text
            else null
          end,
          'reference_number', b.reference_number,
          'pay_channel', upper(coalesce(b.pay_channel,'')),
          'pay_method', upper(coalesce(b.pay_channel,'')),
          'item_type', b.item_type,
          'item_type_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            else null
          end,
          'payment_or_deduction', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT') then 'PAYMENT'
            when coalesce(b.amount_ex_vat, 0) < 0 then 'DEDUCTION'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'PAYMENT'
            else 'ZERO'
          end,
          'finance_case_id', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_case_reference', case when b.finance_case_id is null then null else b.finance_case_id::text end,
          'finance_component_id', case when b.finance_component_id is null then null else b.finance_component_id::text end,
          'finance_case_type', case when b.finance_case_type is null then null else b.finance_case_type::text end,
          'finance_management_group', b.finance_management_group,
          'lifecycle_status', b.finance_lifecycle_status_display,
          'finance_status', case when b.finance_status is null then null else b.finance_status::text end,
          'finance_payout_status', case when b.finance_payout_status is null then null else b.finance_payout_status::text end,
          'taxability', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'taxability','')), ''),
          'routing_kind', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '')
        )
        || jsonb_build_object(
          'payout_destination', coalesce(
            nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'destination_label','')), ''),
            case
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' then 'one-off specified bank account'
              when nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), '') = 'UMBRELLA_COMPANY' then 'umbrella company'
              when upper(coalesce(b.pay_channel,'')) = 'PAYE' then 'normal PAYE route'
              when upper(coalesce(b.pay_channel,'')) = 'UMBRELLA' then 'umbrella company'
              else null
            end
          ),
          'sort_code', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''),
          'account_number', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''),
          'destination_group_key', concat_ws(
            '|',
            upper(coalesce(b.pay_channel,'')),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'routing_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_kind','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'payee_entity_id','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'sort_code','')), ''), ''),
            coalesce(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'account_number','')), ''), '')
          ),
          'masked_bank_account', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'masked_bank_account_paid_to', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'masked_bank_account','')), ''),
          'beneficiary_name', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'beneficiary_name','')), ''),
          'bank_details_hash', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_hash','')), ''),
          'bank_details_note', nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'bank_details_note','')), ''),
          'bank_details_created_by_user_id', case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end,
          'bank_details_created_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_created_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_created_by_email,'')), ''),
            case when b.bank_details_created_by_user_id is null then null else b.bank_details_created_by_user_id::text end
          ),
          'bank_details_updated_by_user_id', case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end,
          'bank_details_updated_by', coalesce(
            nullif(btrim(coalesce(b.bank_details_updated_by_display_name,'')), ''),
            nullif(btrim(coalesce(b.bank_details_updated_by_email,'')), ''),
            case when b.bank_details_updated_by_user_id is null then null else b.bank_details_updated_by_user_id::text end
          ),
          'appears_on_umbrella_remittance', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'appears_on_umbrella_remittance','')), '')) in ('true','t','1','yes','y')), false),
          'generates_candidate_payment_advice', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'generates_candidate_payment_advice','')), '')) in ('true','t','1','yes','y')), false),
          'is_candidate_directed_oneoff_payout', coalesce((lower(nullif(btrim(coalesce(b.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout','')), '')) in ('true','t','1','yes','y')), false),
          'line_kind', case
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.item_type = 'LOAN_PAYOUT' then 'LOAN_PAYOUT'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'MANUAL_CREDIT_PAYOUT'
            else b.line_kind
          end,
          'line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'friendly_line_label', case
            when b.item_type = 'LOAN_PAYOUT' then 'Loan payout'
            when b.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual credit adjustment payment'
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual debt adjustment deduction'
            when b.finance_case_type = 'OVERPAYMENT' and b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when b.item_type = 'LOAN_REPAYMENT' then 'Loan repayment'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'Overpayment recovery'
            when upper(coalesce(b.line_kind,'')) = 'TS_BUCKET' then case upper(coalesce(b.bucket_code,''))
              when 'DAY' then 'Day'
              when 'NIGHT' then 'Night'
              when 'SAT' then 'Sat'
              when 'SUN' then 'Sun'
              when 'BH' then 'BH'
              else coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Hours')
            end
            when upper(coalesce(b.line_kind,'')) = 'ADDITIONAL_UNIT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Additional unit')
            when upper(coalesce(b.line_kind,'')) = 'MILEAGE' then 'Mileage'
            when upper(coalesce(b.line_kind,'')) = 'EXPENSE' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Expense')
            when upper(coalesce(b.line_kind,'')) = 'ADJUSTMENT' then coalesce(nullif(btrim(coalesce(b.unit_name,'')), ''), 'Adjustment')
            when upper(coalesce(b.line_kind,'')) = 'CONVERSION_ADJ' then 'Conversion adjustment'
            when nullif(btrim(coalesce(b.unit_name,'')), '') is not null then b.unit_name
            when nullif(btrim(coalesce(b.line_kind,'')), '') is not null then b.line_kind
            else b.item_type
          end,
          'row_group', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then 'DEDUCTION'
            when b.timesheet_id is null then 'NON_TIMESHEET'
            else 'TIMESHEET'
          end,
          'is_non_timesheet_line', (b.timesheet_id is null),
          'bucket_code', b.bucket_code,
          'unit_name', b.unit_name,
          'units', b.units,
          'rate', b.rate,
          'amount_ex_vat', b.amount_ex_vat,
          'amount_vat', b.amount_vat
        )
        || jsonb_build_object(
          'amount_inc_vat', b.amount_inc_vat,
          'economic_key_type', b.economic_key_type,
          'economic_key_value', b.economic_key_value,
          'key_type', b.economic_key_type,
          'key_value', b.economic_key_value,
          'key_resolution_source', b.economic_key_resolution_source,
          'key_resolution_failure_reason', b.economic_key_resolution_failure_reason,
          'source_units', b.source_units,
          'target_units', b.target_units,
          'source_rate', b.source_rate,
          'target_rate', b.target_rate,
          'source_amount_ex_vat', b.source_amount_ex_vat,
          'target_amount_ex_vat', b.target_amount_ex_vat,
          'target_amount_paid_ex_vat', b.target_amount_ex_vat,
          'source_charge_rate', b.source_charge_rate,
          'target_charge_rate', b.target_charge_rate,
          'source_charge_ex_vat', b.source_charge_ex_vat,
          'target_charge_ex_vat', b.target_charge_ex_vat,
          'resolution_mode', b.resolution_mode,
          'resolution_payload_json', b.resolution_payload_json,
          'resolution_result_json', b.resolution_result_json,
          'source_target_detail', jsonb_strip_nulls(jsonb_build_object(
            'source_units', b.source_units,
            'target_units', b.target_units,
            'source_rate', b.source_rate,
            'target_rate', b.target_rate,
            'source_amount_ex_vat', b.source_amount_ex_vat,
            'target_amount_ex_vat', b.target_amount_ex_vat,
            'source_charge_rate', b.source_charge_rate,
            'target_charge_rate', b.target_charge_rate,
            'source_charge_ex_vat', b.source_charge_ex_vat,
            'target_charge_ex_vat', b.target_charge_ex_vat,
            'economic_key_type', b.economic_key_type,
            'economic_key_value', b.economic_key_value,
            'resolution_mode', b.resolution_mode
          )),
          'signed_amount_ex_vat', b.amount_ex_vat,
          'signed_amount_inc_vat', b.amount_inc_vat,
          'amount_sign', case
            when coalesce(b.amount_ex_vat, 0) < 0 then 'NEGATIVE'
            when coalesce(b.amount_ex_vat, 0) > 0 then 'POSITIVE'
            else 'ZERO'
          end,
          'is_overpayment_recovery', (b.item_type = 'OVERPAYMENT_RECOVERY'),
          'is_loan_repayment', (b.item_type = 'LOAN_REPAYMENT'),
          'is_manual_debt_recovery', (b.item_type = 'MANUAL_DEBT_RECOVERY'),
          'deduction_kind', case
            when b.item_type = 'MANUAL_DEBT_RECOVERY' then 'MANUAL_DEBT_RECOVERY'
            when b.finance_case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_ADJUSTMENT'
            when b.item_type = 'OVERPAYMENT_RECOVERY' then 'OVERPAYMENT_RECOVERY'
            when b.item_type = 'LOAN_REPAYMENT' then 'LOAN_REPAYMENT'
            else null
          end,
          'deduction_amount_ex_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_ex_vat,0)),2)
            else null
          end,
          'deduction_amount_inc_vat', case
            when b.item_type in ('OVERPAYMENT_RECOVERY','LOAN_REPAYMENT','MANUAL_DEBT_RECOVERY') then round(abs(coalesce(b.amount_inc_vat,0)),2)
            else null
          end,
          'paye_net_amount', case
            when upper(coalesce(b.pay_channel,'')) = 'PAYE' then b.paye_net_amount
            else null
          end,
          'paye_treatment', b.paye_treatment,
          'adjustment_comment', b.finance_adjustment_comment,
          'note', coalesce(b.finance_notes, b.item_description),
          'comment_or_note', coalesce(b.finance_adjustment_comment, b.finance_notes, b.item_description),
          'description', b.item_description,
          'source_ref', b.source_ref,
          'repayment_week_start', case when b.repayment_week_start is null then null else b.repayment_week_start::text end
        )
      ) as row_json
    from base b
  )
  select
    r.sort_surname,
    r.sort_group,
    r.sort_work_date,
    r.sort_timesheet_id,
    r.sort_line_rank,
    r.sort_bucket_code,
    r.sort_unit_name,
    r.line_kind,
    r.row_json
  from rows0 r;

  select count(*)::int
  into v_row_count
  from _tmp_pay_export_rows;

  select coalesce(
    jsonb_object_agg(t.lk, t.ct),
    '{}'::jsonb
  )
  into v_kind_counts
  from (
    select
      coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN') as lk,
      count(*)::int as ct
    from _tmp_pay_export_rows per
    group by coalesce(nullif(btrim(coalesce(per.line_kind,'')),'') , 'UNKNOWN')
  ) t;

  select coalesce(
    jsonb_agg(
      per.row_json
      order by
        per.sort_surname asc,
        per.sort_group asc,
        per.sort_work_date asc nulls last,
        per.sort_timesheet_id asc nulls last,
        per.sort_line_rank asc,
        per.sort_bucket_code asc nulls last,
        per.sort_unit_name asc nulls last
    ),
    '[]'::jsonb
  )
  into v_rows
  from _tmp_pay_export_rows per;

  begin
    perform public._imp_debug_audit(
      p_actor_user_id,
      'PAY_BATCH_EXPORT_CSV_ROWS',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'row_count', v_row_count,
        'line_kind_counts', v_kind_counts,
        'is_cancelled', v_is_cancelled,
        'is_stale', v_is_stale,
        'stale_reasons', v_stale_reasons
      ),
      'pay_batches',
      p_pay_batch_id::text,
      null,
      null,
      null,
      null
    );
  exception when others then
    null;
  end;

  return jsonb_build_object(
    'ok', true,
    'batch', jsonb_build_object(
      'id', v_batch.id::text,
      'status', v_batch.status,
      'pay_date', case when v_batch.pay_date is null then null else v_batch.pay_date::text end,
      'batch_kind', v_batch_kind,
      'batch_kind_fixed', case when v_batch.batch_kind_fixed is null then null else v_batch.batch_kind_fixed end,
      'is_cancelled', v_is_cancelled,
      'generated_at_utc', v_now_utc::text
    ),
    'freshness', jsonb_build_object(
      'is_stale', v_is_stale,
      'stale_reasons', v_stale_reasons,
      'diff_sample', v_diff_sample,
      'freshness_validation_status', nullif(v_freshness_validation_status, ''),
      'freshness_result_hash', v_freshness_result_hash,
      'freshness_scope_hash', v_freshness_scope_hash,
      'freshness_operation_id', case when v_batch.freshness_operation_id is null then null else v_batch.freshness_operation_id::text end,
      'source', coalesce(v_fresh->>'source', case when v_pre_execution_export then 'legacy_or_stored_pre_execution' else 'stored_freshness_metadata_non_blocking' end)
    ),
    'summary', jsonb_build_object(
      'row_count', v_row_count,
      'line_kind_counts', v_kind_counts
    ),
    'rows', v_rows
  );
end;
$$;






CREATE OR REPLACE FUNCTION public.timesheet_pay_state(
  p_timesheet_id uuid,
  p_actor_user_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_out jsonb;
  v_has_tsfin boolean := false;
  v_today_uk date := (now() AT TIME ZONE 'Europe/London')::date;
BEGIN
  IF p_timesheet_id IS NULL THEN
    RAISE EXCEPTION 'timesheet_pay_state: timesheet_id is required';
  END IF;

  WITH
  tf AS (
    SELECT
      tf.timesheet_id,
      tf.candidate_id,
      ts.booking_id,
      tf.pay_on_hold,
      tf.invoice_breakdown_json,
      ts.sheet_scope,
      ts.reference_number,
      ts.worked_start_iso AS ts_worked_start_iso,
      ts.worked_end_iso AS ts_worked_end_iso,
      ts.break_start_iso AS ts_break_start_iso,
      ts.break_end_iso AS ts_break_end_iso,
      ts.break_minutes AS ts_break_minutes,
      ts.actual_schedule_json AS ts_actual_schedule_json,
      tf.worked_start_iso AS tf_worked_start_iso,
      tf.worked_end_iso AS tf_worked_end_iso,
      tf.break_start_iso AS tf_break_start_iso,
      tf.break_end_iso AS tf_break_end_iso,
      tf.break_minutes AS tf_break_minutes,
      tf.actual_schedule_json AS tf_actual_schedule_json
    FROM public.timesheets_financials tf
    LEFT JOIN public.timesheets ts
      ON ts.timesheet_id = tf.timesheet_id
     AND ts.is_current = true
    WHERE tf.timesheet_id = p_timesheet_id
      AND tf.is_current = true
    LIMIT 1
  ),
  tf_norm AS (
    SELECT
      t.timesheet_id,
      t.candidate_id,
      t.booking_id,
      COALESCE(t.pay_on_hold, false) AS pay_on_hold,
      CASE
        WHEN t.invoice_breakdown_json IS NOT NULL AND jsonb_typeof(t.invoice_breakdown_json) = 'object'
          THEN t.invoice_breakdown_json
        ELSE NULL
      END AS invoice_breakdown_json,
      upper(coalesce(t.sheet_scope::text, '')) AS sheet_scope,
      nullif(btrim(coalesce(t.reference_number, '')), '') AS reference_number,
      coalesce(t.tf_worked_start_iso, t.ts_worked_start_iso) AS effective_worked_start_iso,
      coalesce(t.tf_worked_end_iso, t.ts_worked_end_iso) AS effective_worked_end_iso,
      coalesce(t.tf_break_start_iso, t.ts_break_start_iso) AS effective_break_start_iso,
      coalesce(t.tf_break_end_iso, t.ts_break_end_iso) AS effective_break_end_iso,
      coalesce(t.tf_break_minutes, t.ts_break_minutes) AS effective_break_minutes,
      CASE
        WHEN jsonb_typeof(t.tf_actual_schedule_json) = 'object' THEN t.tf_actual_schedule_json
        WHEN jsonb_typeof(t.tf_actual_schedule_json) = 'array' THEN (
          SELECT tf_sched_item.value
          FROM jsonb_array_elements(t.tf_actual_schedule_json) AS tf_sched_item(value)
          WHERE tf_sched_item.value IS NOT NULL
            AND jsonb_typeof(tf_sched_item.value) = 'object'
          LIMIT 1
        )
        WHEN jsonb_typeof(t.ts_actual_schedule_json) = 'object' THEN t.ts_actual_schedule_json
        WHEN jsonb_typeof(t.ts_actual_schedule_json) = 'array' THEN (
          SELECT ts_sched_item.value
          FROM jsonb_array_elements(t.ts_actual_schedule_json) AS ts_sched_item(value)
          WHERE ts_sched_item.value IS NOT NULL
            AND jsonb_typeof(ts_sched_item.value) = 'object'
          LIMIT 1
        )
        ELSE NULL::jsonb
      END AS effective_daily_schedule_json
    FROM tf t
  ),
  mode_flags AS (
    SELECT
      tn.timesheet_id,
      tn.candidate_id,
      tn.booking_id,
      tn.pay_on_hold,
      tn.invoice_breakdown_json,
      tn.sheet_scope,
      tn.reference_number,
      tn.effective_worked_start_iso,
      tn.effective_worked_end_iso,
      tn.effective_break_start_iso,
      tn.effective_break_end_iso,
      tn.effective_break_minutes,
      tn.effective_daily_schedule_json,
      CASE
        WHEN tn.invoice_breakdown_json IS NOT NULL
         AND upper(coalesce(tn.invoice_breakdown_json->>'mode','')) = 'SEGMENTS'
         AND jsonb_typeof(tn.invoice_breakdown_json->'segments') = 'array'
          THEN true
        ELSE false
      END AS actual_segments_mode,
      CASE
        WHEN tn.sheet_scope = 'DAILY'
         AND coalesce(
           CASE
             WHEN tn.effective_worked_start_iso IS NOT NULL THEN ((tn.effective_worked_start_iso AT TIME ZONE 'Europe/London')::date)::text
             ELSE coalesce(
               nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'date','')), ''),
               nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'work_date','')), ''),
               nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'ymd','')), ''),
               nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'date_ymd','')), '')
             )
           END,
           ''
         ) <> ''
          THEN true
        ELSE false
      END AS synthetic_daily_mode,
      CASE
        WHEN tn.effective_worked_start_iso IS NOT NULL THEN ((tn.effective_worked_start_iso AT TIME ZONE 'Europe/London')::date)::text
        ELSE coalesce(
          nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'date','')), ''),
          nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'work_date','')), ''),
          nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'ymd','')), ''),
          nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'date_ymd','')), '')
        )
      END AS synthetic_component_date,
      jsonb_strip_nulls(
        case
          when jsonb_typeof(tn.effective_daily_schedule_json->'breaks') = 'array' then tn.effective_daily_schedule_json->'breaks'
          when tn.effective_break_start_iso is not null and tn.effective_break_end_iso is not null then
            jsonb_build_array(
              jsonb_build_object(
                'start', to_char((tn.effective_break_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI'),
                'end', to_char((tn.effective_break_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI'),
                'break_mins', coalesce(
                  tn.effective_break_minutes::numeric,
                  case
                    when tn.effective_break_start_iso is not null and tn.effective_break_end_iso is not null
                      then greatest(
                        0::numeric,
                        round((extract(epoch from (tn.effective_break_end_iso - tn.effective_break_start_iso)) / 60.0)::numeric, 0)
                      )
                    else null::numeric
                  end
                )
              )
            )
          when nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_start','')), '') is not null
           and nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_end','')), '') is not null then
            jsonb_build_array(
              jsonb_build_object(
                'start', nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_start','')), ''),
                'end', nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_end','')), ''),
                'break_mins', coalesce(
                  tn.effective_break_minutes::numeric,
                  nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
                  nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
                  nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
                  nullif(btrim(coalesce(tn.effective_daily_schedule_json->>'breakMin','')), '')::numeric
                )
              )
            )
          else '[]'::jsonb
        end
      ) AS synthetic_component_breaks
    FROM tf_norm tn
  ),
  segment_components AS (
    SELECT
      nullif(btrim(COALESCE(seg.value->>'segment_id','')), '') AS component_id,
      nullif(btrim(COALESCE(seg.value->>'date','')), '') AS component_date,
      coalesce(
        nullif(btrim(COALESCE(seg.value->>'segment_stable_key','')), ''),
        nullif(btrim(COALESCE(seg.value->>'segment_id','')), ''),
        nullif(btrim(COALESCE(seg.value->>'segment_key','')), ''),
        nullif(btrim(COALESCE(seg.value->>'ref_num','')), ''),
        nullif(btrim(COALESCE(seg.value->>'date','')), '')
      ) AS component_stable_key,
      nullif(btrim(COALESCE(seg.value->>'ref_num','')), '') AS component_ref_num,
      COALESCE(NULLIF(seg.value->>'exclude_from_pay','')::boolean, false) AS is_on_hold,
      nullif(btrim(COALESCE(seg.value->>'start_utc','')), '') AS component_start_utc,
      nullif(btrim(COALESCE(seg.value->>'end_utc','')), '') AS component_end_utc,
      case
        when nullif(btrim(COALESCE(seg.value->>'start','')), '') is not null then nullif(btrim(COALESCE(seg.value->>'start','')), '')
        when nullif(btrim(COALESCE(seg.value->>'start_utc','')), '') is not null then to_char(((seg.value->>'start_utc')::timestamptz AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else null
      end AS component_start,
      case
        when nullif(btrim(COALESCE(seg.value->>'end','')), '') is not null then nullif(btrim(COALESCE(seg.value->>'end','')), '')
        when nullif(btrim(COALESCE(seg.value->>'end_utc','')), '') is not null then to_char(((seg.value->>'end_utc')::timestamptz AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else null
      end AS component_end,
      nullif(btrim(COALESCE(seg.value->>'break_start','')), '') AS component_break_start,
      nullif(btrim(COALESCE(seg.value->>'break_end','')), '') AS component_break_end,
      coalesce(
        nullif(seg.value->>'break_mins','')::numeric,
        nullif(seg.value->>'break_minutes','')::numeric
      ) AS component_break_mins,
      case
        when jsonb_typeof(seg.value->'breaks') = 'array' then seg.value->'breaks'
        else '[]'::jsonb
      end AS component_breaks
    FROM mode_flags mf
    JOIN LATERAL jsonb_array_elements(COALESCE(mf.invoice_breakdown_json->'segments','[]'::jsonb)) AS seg(value)
      ON true
    WHERE mf.actual_segments_mode = true
      AND seg.value IS NOT NULL
      AND jsonb_typeof(seg.value) = 'object'
      AND nullif(btrim(COALESCE(seg.value->>'segment_id','')), '') IS NOT NULL

    UNION ALL

    SELECT
      ('ts:' || mf.timesheet_id::text) AS component_id,
      mf.synthetic_component_date AS component_date,
      ('timesheet:' || COALESCE(mf.booking_id, mf.timesheet_id::text)) AS component_stable_key,
      coalesce(
        mf.reference_number,
        nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'ref_num','')), '')
      ) AS component_ref_num,
      mf.pay_on_hold AS is_on_hold,
      CASE
        WHEN mf.effective_worked_start_iso IS NULL THEN NULL
        ELSE mf.effective_worked_start_iso::text
      END AS component_start_utc,
      CASE
        WHEN mf.effective_worked_end_iso IS NULL THEN NULL
        ELSE mf.effective_worked_end_iso::text
      END AS component_end_utc,
      case
        when mf.effective_worked_start_iso is not null then to_char((mf.effective_worked_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else coalesce(
          nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'start','')), ''),
          nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'worked_start','')), '')
        )
      end AS component_start,
      case
        when mf.effective_worked_end_iso is not null then to_char((mf.effective_worked_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else coalesce(
          nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'end','')), ''),
          nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'worked_end','')), '')
        )
      end AS component_end,
      case
        when mf.effective_break_start_iso is not null then to_char((mf.effective_break_start_iso AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'break_start','')), '')
      end AS component_break_start,
      case
        when mf.effective_break_end_iso is not null then to_char((mf.effective_break_end_iso AT TIME ZONE 'Europe/London'), 'HH24:MI')
        else nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'break_end','')), '')
      end AS component_break_end,
      coalesce(
        mf.effective_break_minutes::numeric,
        nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'break_minutes','')), '')::numeric,
        nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'break_mins','')), '')::numeric,
        nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'breakMinutes','')), '')::numeric,
        nullif(btrim(coalesce(mf.effective_daily_schedule_json->>'breakMin','')), '')::numeric,
        case
          when mf.effective_break_start_iso is not null and mf.effective_break_end_iso is not null
            then greatest(
              0::numeric,
              round((extract(epoch from (mf.effective_break_end_iso - mf.effective_break_start_iso)) / 60.0)::numeric, 0)
            )
          else null::numeric
        end
      ) AS component_break_mins,
      coalesce(mf.synthetic_component_breaks, '[]'::jsonb) AS component_breaks
    FROM mode_flags mf
    WHERE mf.actual_segments_mode = false
      AND mf.synthetic_daily_mode = true
  ),
  components AS (
    SELECT
      sc.component_id,
      sc.component_date,
      sc.component_stable_key,
      sc.component_ref_num,
      sc.is_on_hold,
      sc.component_start_utc,
      sc.component_end_utc,
      sc.component_start,
      sc.component_end,
      sc.component_break_start,
      sc.component_break_end,
      sc.component_break_mins,
      sc.component_breaks
    FROM segment_components sc

    UNION ALL

    SELECT
      'TOTAL'::text AS component_id,
      NULL::text AS component_date,
      ('timesheet:' || COALESCE(mf.booking_id, mf.timesheet_id::text))::text AS component_stable_key,
      NULL::text AS component_ref_num,
      mf.pay_on_hold AS is_on_hold,
      NULL::text AS component_start_utc,
      NULL::text AS component_end_utc,
      NULL::text AS component_start,
      NULL::text AS component_end,
      NULL::text AS component_break_start,
      NULL::text AS component_break_end,
      NULL::numeric AS component_break_mins,
      '[]'::jsonb AS component_breaks
    FROM mode_flags mf
    WHERE mf.actual_segments_mode = false
      AND mf.synthetic_daily_mode = false
  ),
  active_override AS (
    SELECT
      tpo.id AS override_id,
      tpo.timesheet_id,
      tpo.reason,
      tpo.created_at_utc,
      tpo.consumed_at_utc,
      CASE
        WHEN pb.id IS NOT NULL AND upper(COALESCE(pb.status::text,'')) <> 'CANCELLED'
          THEN pb.id
        ELSE NULL
      END AS consumed_by_batch_id,
      CASE
        WHEN pb.id IS NOT NULL AND upper(COALESCE(pb.status::text,'')) <> 'CANCELLED'
          THEN upper(COALESCE(pb.status::text,''))
        ELSE NULL
      END AS consumed_batch_status,
      CASE
        WHEN pb.id IS NOT NULL AND upper(COALESCE(pb.status::text,'')) <> 'CANCELLED'
          THEN false
        ELSE true
      END AS can_unadvance
    FROM public.timesheet_payment_overrides tpo
    LEFT JOIN public.pay_batches pb
      ON pb.id = tpo.consumed_by_pay_batch_id
    WHERE tpo.timesheet_id = p_timesheet_id
      AND tpo.cleared_at_utc IS NULL
    ORDER BY tpo.created_at_utc DESC, tpo.id DESC
    LIMIT 1
  ),
  active_payment_snooze AS (
    SELECT
      s.id AS snooze_id,
      s.snooze_until_date,
      s.note
    FROM tf_norm tn
    JOIN public.pay_item_snoozes s
      ON s.candidate_id = tn.candidate_id
     AND s.source_ref IS NULL
     AND s.segment_id IS NULL
     AND s.segment_stable_key IS NULL
     AND s.cleared_at_utc IS NULL
     AND upper(COALESCE(s.snooze_kind,'')) = 'TIMESHEET_PAYMENT'
     AND (s.snooze_until_date IS NULL OR s.snooze_until_date >= v_today_uk)
     AND (
       (tn.booking_id IS NOT NULL AND s.booking_id IS NOT DISTINCT FROM tn.booking_id)
       OR
       (s.booking_id IS NULL AND s.timesheet_id = p_timesheet_id)
     )
    ORDER BY s.updated_at_utc DESC NULLS LAST, s.created_at_utc DESC, s.id DESC
    LIMIT 1
  ),
  active_segment_snoozes_source AS (
    SELECT
      s.id AS snooze_id,
      s.candidate_id,
      s.timesheet_id,
      s.booking_id,
      s.segment_id,
      coalesce(
        nullif(btrim(COALESCE(s.segment_stable_key,'')), ''),
        nullif(btrim(COALESCE(s.segment_id,'')), '')
      ) AS segment_stable_key,
      upper(COALESCE(s.snooze_kind,'')) AS snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.updated_at_utc
    FROM tf_norm tn
    JOIN public.pay_item_snoozes s
      ON s.candidate_id = tn.candidate_id
     AND s.source_ref IS NULL
     AND s.cleared_at_utc IS NULL
     AND upper(COALESCE(s.snooze_kind,'')) IN ('DO_NOT_PAY', 'BLOCKED_TIMESHEET')
     AND (s.snooze_until_date IS NULL OR s.snooze_until_date >= v_today_uk)
     AND coalesce(
           nullif(btrim(COALESCE(s.segment_stable_key,'')), ''),
           nullif(btrim(COALESCE(s.segment_id,'')), '')
         ) IS NOT NULL
     AND (
       (tn.booking_id IS NOT NULL AND s.booking_id IS NOT DISTINCT FROM tn.booking_id)
       OR
       (s.booking_id IS NULL AND s.timesheet_id = p_timesheet_id)
     )
  ),
  active_segment_snooze_matches AS (
    SELECT
      sc.component_id,
      sc.component_date,
      sc.component_stable_key,
      sc.component_ref_num,
      sc.component_start_utc,
      sc.component_end_utc,
      sc.component_start,
      sc.component_end,
      sc.component_break_start,
      sc.component_break_end,
      sc.component_break_mins,
      sc.component_breaks,
      ass.snooze_id,
      ass.candidate_id,
      ass.timesheet_id,
      ass.booking_id,
      ass.segment_id,
      ass.segment_stable_key,
      ass.snooze_kind,
      ass.snooze_until_date,
      ass.note,
      ass.created_at_utc,
      ass.updated_at_utc,
      row_number() OVER (
        PARTITION BY sc.component_id
        ORDER BY ass.updated_at_utc DESC NULLS LAST, ass.created_at_utc DESC, ass.snooze_id DESC
      ) AS rn
    FROM segment_components sc
    JOIN active_segment_snoozes_source ass
      ON (
        (
          ass.booking_id IS NOT NULL
          AND (
            ass.segment_stable_key IS NOT DISTINCT FROM sc.component_stable_key
            OR ass.segment_id IS NOT DISTINCT FROM sc.component_id
          )
        )
        OR
        (
          ass.booking_id IS NULL
          AND ass.timesheet_id IS NOT DISTINCT FROM p_timesheet_id
          AND (
            ass.segment_id IS NOT DISTINCT FROM sc.component_id
            OR ass.segment_stable_key IS NOT DISTINCT FROM sc.component_stable_key
          )
        )
      )
  ),
  active_segment_snoozes AS (
    SELECT
      asm.component_id,
      asm.component_date,
      asm.component_stable_key,
      asm.component_ref_num,
      asm.component_start_utc,
      asm.component_end_utc,
      asm.component_start,
      asm.component_end,
      asm.component_break_start,
      asm.component_break_end,
      asm.component_break_mins,
      asm.component_breaks,
      asm.snooze_id,
      asm.candidate_id,
      asm.timesheet_id,
      asm.booking_id,
      asm.segment_id,
      asm.segment_stable_key,
      asm.snooze_kind,
      asm.snooze_until_date,
      asm.note,
      asm.created_at_utc,
      asm.updated_at_utc
    FROM active_segment_snooze_matches asm
    WHERE asm.rn = 1
  ),
  pay_items AS (
    SELECT
      CASE
        WHEN nullif(btrim(COALESCE(pbi.segment_key,'')), '') IS NOT NULL
          THEN nullif(btrim(COALESCE(pbi.segment_key,'')), '')
        WHEN pbi.source_ref IS NOT NULL AND btrim(COALESCE(pbi.source_ref,'')) LIKE 'seg:%'
          THEN nullif(btrim(split_part(btrim(pbi.source_ref), ':', 2)), '')
        ELSE 'TOTAL'
      END AS component_id,
      pb.status AS batch_status,
      pb.completed_at_utc AS completed_at_utc
    FROM public.pay_batch_items pbi
    JOIN public.pay_batch_candidates pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN public.pay_batches pb
      ON pb.id = pbc.pay_batch_id
    WHERE pbi.timesheet_id = p_timesheet_id
      AND pbi.is_voided = false
      AND pbi.item_type IN ('SEGMENT_DELTA','EXPENSE_DELTA','ADJUSTMENT_DELTA','MILEAGE_DELTA')
      AND pb.cancelled_at_utc IS NULL
  ),
  agg AS (
    SELECT
      pi.component_id,
      max(CASE WHEN upper(COALESCE(pi.batch_status::text,'')) = 'SETTLED' THEN 1 ELSE 0 END)::int AS has_settled_norm,
      max(CASE WHEN upper(COALESCE(pi.batch_status::text,'')) = 'SETTLED' THEN pi.completed_at_utc ELSE NULL END) AS settled_at_utc,
      max(CASE WHEN upper(COALESCE(pi.batch_status::text,'')) IN (
                 'DRAFT','DRAFT_CREATED','READY',
                 'WAITING_BANK_CONFIRM','PARTIAL','FAILED','BLOCKED_FUNDS',
                 'SCHEDULED','EXECUTING','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT'
               )
               THEN 1 ELSE 0 END)::int AS has_proc_any
    FROM pay_items pi
    WHERE pi.component_id IS NOT NULL
    GROUP BY pi.component_id
  ),
  comp_state AS (
    SELECT
      c.component_id,
      c.component_date,
      c.component_stable_key,
      c.component_ref_num,
      c.is_on_hold,
      c.component_start_utc,
      c.component_end_utc,
      c.component_start,
      c.component_end,
      c.component_break_start,
      c.component_break_end,
      c.component_break_mins,
      c.component_breaks,
      CASE
        WHEN c.is_on_hold = true THEN 'ON_HOLD'
        WHEN COALESCE(a.has_settled_norm,0) = 1 THEN 'PAID'
        WHEN ao.override_id IS NOT NULL AND COALESCE(a.has_proc_any,0) = 1 THEN 'ADVANCE_PROCESSING'
        WHEN COALESCE(a.has_proc_any,0) = 1 THEN 'PAY_PROCESSING'
        WHEN ao.override_id IS NOT NULL THEN 'ADVANCED'
        ELSE 'UNPAID'
      END AS stage,
      a.settled_at_utc,
      CASE
        WHEN c.component_id = 'TOTAL' THEN 'NONE'
        WHEN ass.snooze_id IS NULL THEN 'NONE'
        WHEN ass.snooze_until_date IS NULL THEN 'INDEFINITE_SNOOZED'
        ELSE 'DATED_SNOOZED'
      END AS snooze_state,
      ass.snooze_id,
      ass.snooze_until_date,
      ass.note AS snooze_note,
      ass.segment_id AS snooze_segment_id,
      ass.segment_stable_key AS snooze_segment_stable_key
    FROM components c
    LEFT JOIN agg a
      ON a.component_id = c.component_id
    LEFT JOIN active_override ao
      ON true
    LEFT JOIN active_segment_snoozes ass
      ON ass.component_id = c.component_id
  ),
  counts AS (
    SELECT
      count(*)::int AS total_components,
      count(*) FILTER (WHERE cs.is_on_hold = true)::int AS on_hold_components,
      count(*) FILTER (WHERE cs.is_on_hold = false)::int AS payable_components,
      count(*) FILTER (WHERE cs.is_on_hold = false AND cs.stage IN ('PAID','ADVANCED'))::int AS paid_components,
      count(*) FILTER (WHERE cs.is_on_hold = false AND cs.stage = 'ADVANCED')::int AS advanced_components,
      count(*) FILTER (WHERE cs.is_on_hold = false AND cs.stage IN ('PAY_PROCESSING','ADVANCE_PROCESSING'))::int AS processing_components,
      count(*) FILTER (WHERE cs.is_on_hold = false AND cs.stage = 'UNPAID')::int AS unpaid_components,
      max(CASE WHEN cs.is_on_hold = false AND cs.stage IN ('PAY_PROCESSING','ADVANCE_PROCESSING') THEN 1 ELSE 0 END)::int AS any_processing,
      max(CASE WHEN cs.is_on_hold = false AND cs.stage = 'ADVANCED' THEN 1 ELSE 0 END)::int AS any_advanced,
      max(CASE WHEN cs.is_on_hold = false AND cs.stage = 'PAID' THEN cs.settled_at_utc ELSE NULL END) AS paid_at_utc
    FROM comp_state cs
  ),
  unpaid_sample AS (
    SELECT
      coalesce(
        jsonb_agg(cs.component_date ORDER BY cs.component_date) FILTER (WHERE cs.component_date IS NOT NULL),
        '[]'::jsonb
      ) AS dates
    FROM (
      SELECT cs.component_date
      FROM comp_state cs
      WHERE cs.is_on_hold = false
        AND cs.stage = 'UNPAID'
        AND cs.component_date IS NOT NULL
      ORDER BY cs.component_date
      LIMIT 3
    ) cs
  ),
  delta AS (
    SELECT
      round(coalesce(sum(coalesce(oc.truth_ex_vat,0) - coalesce(oc.baseline_ex_vat,0)),0),2)::numeric AS net_delta_ex_vat,
      round(coalesce(sum(coalesce(oc.outstanding_ex_vat,0)),0),2)::numeric AS outstanding_ex_vat,
      round(coalesce(sum(coalesce(oc.reserved_ex_vat,0)),0),2)::numeric AS reserved_ex_vat
    FROM public._pay_outstanding_components(ARRAY[p_timesheet_id]) oc
  ),
  mode AS (
    SELECT
      COALESCE((SELECT (mf.actual_segments_mode OR mf.synthetic_daily_mode) FROM mode_flags mf LIMIT 1), false) AS is_segments_mode
  ),
  comp_json AS (
    SELECT
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'component_id', cs.component_id,
            'date', cs.component_date,
            'segment_stable_key', cs.component_stable_key,
            'ref_num', cs.component_ref_num,
            'is_on_hold', cs.is_on_hold,
            'stage', cs.stage,
            'paid_at_utc', cs.settled_at_utc,
            'paid_at_label_uk',
              CASE
                WHEN cs.settled_at_utc IS NULL THEN NULL
                ELSE to_char(cs.settled_at_utc AT TIME ZONE 'Europe/London', 'Dy DD/MM/YYYY HH24:MI') || 'hrs'
              END,
            'snooze_state', cs.snooze_state,
            'snooze_id', CASE WHEN cs.snooze_id IS NULL THEN NULL ELSE cs.snooze_id::text END,
            'snooze_until_date', CASE WHEN cs.snooze_until_date IS NULL THEN NULL ELSE cs.snooze_until_date::text END,
            'snooze_note', cs.snooze_note,
            'snooze_segment_id', cs.snooze_segment_id,
            'snooze_segment_stable_key', cs.snooze_segment_stable_key,
            'start_utc', cs.component_start_utc,
            'end_utc', cs.component_end_utc,
            'start', cs.component_start,
            'end', cs.component_end,
            'break_start', cs.component_break_start,
            'break_end', cs.component_break_end,
            'break_mins', cs.component_break_mins,
            'breaks', coalesce(cs.component_breaks, '[]'::jsonb)
          )
          ORDER BY
            CASE WHEN cs.component_id = 'TOTAL' THEN 0 ELSE 1 END,
            cs.component_date NULLS LAST,
            cs.component_id
        ),
        '[]'::jsonb
      ) AS components
    FROM comp_state cs
  ),
  segment_snoozes_json AS (
    SELECT
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'snooze_id', ass.snooze_id::text,
            'candidate_id', ass.candidate_id::text,
            'timesheet_id', CASE WHEN ass.timesheet_id IS NULL THEN NULL ELSE ass.timesheet_id::text END,
            'booking_id', ass.booking_id,
            'segment_id', ass.segment_id,
            'segment_stable_key', ass.segment_stable_key,
            'snooze_kind', ass.snooze_kind,
            'snooze_until_date', CASE WHEN ass.snooze_until_date IS NULL THEN NULL ELSE ass.snooze_until_date::text END,
            'note', ass.note,
            'snooze_note', ass.note,
            'date', ass.component_date,
            'work_date', ass.component_date,
            'ref_num', ass.component_ref_num,
            'start_utc', ass.component_start_utc,
            'end_utc', ass.component_end_utc,
            'start', ass.component_start,
            'end', ass.component_end,
            'break_start', ass.component_break_start,
            'break_end', ass.component_break_end,
            'break_mins', ass.component_break_mins,
            'breaks', coalesce(ass.component_breaks, '[]'::jsonb),
            'snooze_state',
              CASE
                WHEN ass.snooze_until_date IS NULL THEN 'INDEFINITE_SNOOZED'
                ELSE 'DATED_SNOOZED'
              END
          )
          ORDER BY ass.component_date NULLS LAST, ass.segment_stable_key NULLS LAST, ass.segment_id NULLS LAST
        ),
        '[]'::jsonb
      ) AS segment_snoozes
    FROM active_segment_snoozes ass
  ),
  paid_status AS (
    SELECT
      CASE
        WHEN c.payable_components IS NULL OR c.payable_components = 0 THEN 'UNPAID'
        WHEN c.paid_components = c.payable_components THEN 'PAID'
        WHEN c.paid_components > 0 THEN 'PARTIALLY_PAID'
        WHEN c.processing_components > 0 THEN 'PROCESSING'
        ELSE 'UNPAID'
      END AS paid_status_code,
      CASE
        WHEN c.paid_at_utc IS NULL THEN NULL
        ELSE to_char(c.paid_at_utc AT TIME ZONE 'Europe/London', 'Dy DD/MM/YYYY HH24:MI') || 'hrs'
      END AS paid_at_label_uk
    FROM counts c
  ),
  adjusted AS (
    SELECT
      d.net_delta_ex_vat,
      d.outstanding_ex_vat,
      d.reserved_ex_vat,
      CASE
        WHEN d.net_delta_ex_vat > 0 THEN 'PAY_OUTSTANDING'
        WHEN d.net_delta_ex_vat < 0 THEN 'OVERPAID'
        ELSE 'NONE'
      END AS adjusted_pill,
      CASE
        WHEN d.net_delta_ex_vat > 0 THEN
          'Timesheet adjusted after payment. Additional pay outstanding: £' || to_char(abs(d.net_delta_ex_vat), 'FM999999990D00')
        WHEN d.net_delta_ex_vat < 0 THEN
          'Timesheet adjusted after payment. Overpaid by: £' || to_char(abs(d.net_delta_ex_vat), 'FM999999990D00')
        ELSE NULL
      END AS adjusted_message
    FROM delta d
  ),
  hover AS (
    SELECT
      jsonb_build_object(
        'paid', c.paid_components,
        'processing', c.processing_components,
        'unpaid', c.unpaid_components,
        'on_hold', c.on_hold_components,
        'total', c.total_components,
        'payable', c.payable_components,
        'last_payment_utc', c.paid_at_utc,
        'last_payment_label_uk',
          CASE
            WHEN c.paid_at_utc IS NULL THEN NULL
            ELSE to_char(c.paid_at_utc AT TIME ZONE 'Europe/London', 'Dy DD/MM/YYYY HH24:MI') || 'hrs'
          END,
        'unpaid_sample_dates', us.dates,
        'net_delta_ex_vat', d.net_delta_ex_vat,
        'outstanding_ex_vat', d.outstanding_ex_vat,
        'reserved_ex_vat', d.reserved_ex_vat
      ) AS hover_summary
    FROM counts c
    CROSS JOIN unpaid_sample us
    CROSS JOIN delta d
  ),
  override_json AS (
    SELECT
      COALESCE((SELECT ao.override_id IS NOT NULL FROM active_override ao LIMIT 1), false) AS is_advanced,
      COALESCE((SELECT ao.can_unadvance FROM active_override ao LIMIT 1), false) AS can_unadvance,
      (SELECT ao.consumed_by_batch_id FROM active_override ao LIMIT 1) AS advanced_consumed_by_batch_id,
      (SELECT ao.consumed_at_utc FROM active_override ao LIMIT 1) AS advanced_consumed_at_utc,
      (SELECT ao.consumed_batch_status FROM active_override ao LIMIT 1) AS advanced_batch_status
  ),
  snooze_json AS (
    SELECT
      COALESCE((SELECT aps.snooze_id IS NOT NULL FROM active_payment_snooze aps LIMIT 1), false) AS is_snoozed,
      (SELECT aps.snooze_until_date FROM active_payment_snooze aps LIMIT 1) AS snooze_until_date,
      COALESCE((SELECT aps.snooze_until_date IS NULL FROM active_payment_snooze aps LIMIT 1), false) AS snooze_is_indefinite,
      (SELECT aps.note FROM active_payment_snooze aps LIMIT 1) AS snooze_note
  )
  SELECT
    jsonb_build_object(
      'ok', true,
      'timesheet_id', p_timesheet_id::text,
      'is_segments_mode', m.is_segments_mode,
      'paid_status', ps.paid_status_code,
      'paid_at_utc', c.paid_at_utc,
      'paid_at_label_uk', ps.paid_at_label_uk,
      'advanced_any', (c.any_advanced = 1),
      'processing_any', (c.any_processing = 1),
      'is_advanced', oj.is_advanced,
      'can_unadvance', oj.can_unadvance,
      'advanced_consumed_by_batch_id', CASE WHEN oj.advanced_consumed_by_batch_id IS NULL THEN NULL ELSE oj.advanced_consumed_by_batch_id::text END,
      'advanced_consumed_at_utc', oj.advanced_consumed_at_utc,
      'advanced_batch_status', oj.advanced_batch_status,
      'is_snoozed', sj.is_snoozed,
      'snooze_until_date', CASE WHEN sj.snooze_until_date IS NULL THEN NULL ELSE sj.snooze_until_date::text END,
      'snooze_is_indefinite', sj.snooze_is_indefinite,
      'snooze_note', sj.snooze_note,
      'counts', jsonb_build_object(
        'total_components', c.total_components,
        'payable_components', c.payable_components,
        'on_hold_components', c.on_hold_components,
        'paid_components', c.paid_components,
        'advanced_components', c.advanced_components,
        'processing_components', c.processing_components,
        'unpaid_components', c.unpaid_components
      ),
      'adjusted', jsonb_build_object(
        'net_delta_ex_vat', a.net_delta_ex_vat,
        'pill', a.adjusted_pill,
        'message', a.adjusted_message,
        'outstanding_ex_vat', a.outstanding_ex_vat,
        'reserved_ex_vat', a.reserved_ex_vat
      ),
      'hover', h.hover_summary,
      'components', cj.components,
      'segment_snoozes', ssj.segment_snoozes
    )
  INTO v_out
  FROM counts c
  CROSS JOIN mode m
  CROSS JOIN paid_status ps
  CROSS JOIN adjusted a
  CROSS JOIN hover h
  CROSS JOIN comp_json cj
  CROSS JOIN segment_snoozes_json ssj
  CROSS JOIN override_json oj
  CROSS JOIN snooze_json sj;

  v_has_tsfin := EXISTS (
    SELECT 1
    FROM public.timesheets_financials tf
    WHERE tf.timesheet_id = p_timesheet_id
      AND tf.is_current = true
  );

  IF v_out IS NULL THEN
    v_out := jsonb_build_object(
      'ok', false,
      'timesheet_id', p_timesheet_id::text,
      'error', 'NO_DATA'
    );
  END IF;

  BEGIN
    IF p_actor_user_id IS NOT NULL THEN
      PERFORM public._imp_debug_audit(
        p_actor_user_id,
        'TIMESHEET_PAY_STATE',
        jsonb_build_object(
          'timesheet_id', p_timesheet_id::text,
          'has_tsfin', v_has_tsfin,
          'result', v_out
        ),
        'timesheets',
        p_timesheet_id::text
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN v_out;
END;
$$;



CREATE OR REPLACE FUNCTION public.pay_candidate_advances_report(
  p_candidate_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_week_start date := public._pay_week_start_monday(v_today_uk);
  v_week_end date := (public._pay_week_start_monday(v_today_uk) + 6);

  v_candidate record;
  v_paid_wtd numeric := 0;
  v_rows jsonb := '[]'::jsonb;
  v_payment_advances jsonb := '[]'::jsonb;
  v_overpayments jsonb := '[]'::jsonb;
  v_underpayments jsonb := '[]'::jsonb;
  v_manual_debt_adjustments jsonb := '[]'::jsonb;
  v_manual_credit_adjustments jsonb := '[]'::jsonb;
  v_snoozed_deferred_items jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CANDIDATE_ADVANCES_REPORT',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_candidate_advances_report: candidate_id is required'
    )::text;
  end if;

  select
    c.id,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.active
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_CANDIDATE_ADVANCES_REPORT',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_candidate_advances_report: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  select
    round(
      coalesce(
        sum(
          case
            when pbc.net_bank_amount is not null then pbc.net_bank_amount
            when pbc.gross_preview is not null then pbc.gross_preview
            else 0
          end
        ),
        0
      ),
      2
    )
  into v_paid_wtd
  from public.pay_batch_candidates pbc
  join public.pay_batches pb
    on pb.id = pbc.pay_batch_id
  where pbc.candidate_id = p_candidate_id
    and pb.pay_date >= v_week_start
    and pb.pay_date <= v_week_end
    and upper(coalesce(pb.status::text, '')) <> 'CANCELLED';

  with finance_rows as (
    select
      case
        when vfc.active_snooze_id is not null then 'SNOOZED_DEFERRED'
        else vfc.case_type::text
      end as row_group,
      'FINANCE_CASE'::text as row_kind,
      vfc.finance_case_id,
      vfc.case_type::text as case_type,
      vfc.candidate_id,
      vfc.candidate_tms_ref,
      vfc.candidate_display_name,
      vfc.client_id,
      vfc.client_name,
      vfc.linked_timesheet_id,
      vfc.linked_shift_date,
      vfc.created_at,
      vfc.start_week_start,
      vfc.next_due_week_start,
      round(coalesce(vfc.original_amount, 0), 2)::numeric(12,2) as original_amount,
      round(
        case
          when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 0
          else greatest(coalesce(vfc.original_amount, 0) - coalesce(vfc.outstanding_amount, 0), 0)
        end,
        2
      )::numeric(12,2) as recovered_total,
      round(coalesce(vfc.outstanding_amount, 0), 2)::numeric(12,2) as remaining_outstanding,
      round(
        case
          when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
           and vfc.next_due_week_start is not null
           and vfc.next_due_week_start <= v_week_start
           and coalesce(vfc.written_off_at_utc, null) is null
           and coalesce(vfc.cleared_at_utc, null) is null
           and upper(coalesce(vfc.status, '')) not in ('PAID_OFF', 'CLEARED')
          then least(coalesce(vfc.weekly_due, 0), coalesce(vfc.outstanding_amount, 0))
          else 0
        end,
        2
      )::numeric(12,2) as due_this_week,
      vfc.status,
      vfc.payout_status,
      vfc.reason,
      vfc.notes,
      vfc.adjustment_comment,
      vfc.source_original_paid_amount,
      vfc.source_corrected_paid_amount,
      vfc.minimum_earnings_threshold,
      vfc.take_home_floor_override,
      vfc.active_snooze_id,
      vfc.active_snooze_kind,
      vfc.active_snooze_until_date,
      vfc.active_snooze_note,
      case
        when vfc.active_snooze_id is null then 'NONE'
        when vfc.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      case
        when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
        when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'CLEARED'
        when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RESERVED'
        when coalesce(vfc.committed_amount, 0) > 0 then 'COMMITTED'
        when coalesce(vfc.settled_amount, 0) > 0 then 'SETTLED'
        when vfc.active_snooze_id is not null then 'SNOOZED'
        else upper(coalesce(vfc.status, 'ACTIVE'))
      end as lifecycle_state,
      case
        when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_CREDIT_ADJUSTMENT') then coalesce(pbp.authoritative_payment_date, pbp.pay_date)
        else coalesce(pbr.authoritative_payment_date, pbr.pay_date)
      end as authoritative_payment_date,
      case
        when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfc.payout_status, 'NOT_PAID')
        when vfc.case_type = 'PAYMENT_ADVANCE' then
          case
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) > 0 then 'RECOVERY_ACTIVE'
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            else coalesce(vfc.payout_status, 'NOT_PAID')
          end
        when vfc.case_type in ('OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT') then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RECOVERY_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'RECOVERY_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'RECOVERY_SETTLED'
            else 'RECOVERY_ACTIVE'
          end
        when vfc.case_type = 'UNDERPAYMENT' then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'PAYOUT_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'PAYOUT_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'PAYOUT_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'PAYOUT_SETTLED'
            else 'PAYOUT_ACTIVE'
          end
        else coalesce(vfc.status, 'ACTIVE')
      end as payout_or_recovery_status,
      coalesce(vfc.is_mixed_case, false) as is_mixed_case,
      coalesce(vfc.open_taxable_count, 0) as open_taxable_count,
      coalesce(vfc.open_reimbursement_count, 0) as open_reimbursement_count,
      coalesce(vfc.unresolved_taxable_count, 0) as unresolved_taxable_count,
      coalesce(vfc.stale_count, 0) as stale_count,
      coalesce(vfc.component_resolution_summary_json, '{}'::jsonb) as component_resolution_summary_json
    from public.v_finance_cases_register vfc
    left join public.pay_batches pbp
      on pbp.id = vfc.payout_pay_batch_id
    left join public.pay_batches pbr
      on pbr.id = vfc.latest_recovery_pay_batch_id
    where vfc.candidate_id = p_candidate_id
  ),
  snoozed_timesheet_rows as (
    select
      'SNOOZED_DEFERRED'::text as row_group,
      'TIMESHEET_SNOOZE'::text as row_kind,
      null::uuid as finance_case_id,
      null::text as case_type,
      c.id as candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      cli.id as client_id,
      cli.name as client_name,
      s.timesheet_id as linked_timesheet_id,
      null::date as linked_shift_date,
      s.created_at_utc as created_at,
      null::date as start_week_start,
      null::date as next_due_week_start,
      0::numeric(12,2) as original_amount,
      0::numeric(12,2) as recovered_total,
      0::numeric(12,2) as remaining_outstanding,
      0::numeric(12,2) as due_this_week,
      null::text as status,
      null::text as payout_status,
      null::text as reason,
      null::text as notes,
      null::text as adjustment_comment,
      null::numeric as source_original_paid_amount,
      null::numeric as source_corrected_paid_amount,
      null::numeric as minimum_earnings_threshold,
      null::numeric as take_home_floor_override,
      s.id as active_snooze_id,
      upper(coalesce(s.snooze_kind, '')) as active_snooze_kind,
      s.snooze_until_date as active_snooze_until_date,
      s.note as active_snooze_note,
      case
        when s.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      'SNOOZED'::text as lifecycle_state,
      null::date as authoritative_payment_date,
      'DEFERRED'::text as payout_or_recovery_status,
      false as is_mixed_case,
      0::integer as open_taxable_count,
      0::integer as open_reimbursement_count,
      0::integer as unresolved_taxable_count,
      0::integer as stale_count,
      '{}'::jsonb as component_resolution_summary_json
    from public.pay_item_snoozes s
    join public.timesheets ts
      on ts.timesheet_id = s.timesheet_id
    join public.candidates c
      on c.id = s.candidate_id
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cli
      on cli.id = ct.client_id
    where s.cleared_at_utc is null
      and s.candidate_id = p_candidate_id
      and s.timesheet_id is not null
      and s.source_ref is null
      and (
        upper(coalesce(s.snooze_kind, '')) in ('TIMESHEET_PAYMENT', 'BLOCKED_TIMESHEET', 'DO_NOT_PAY')
        or upper(coalesce(s.snooze_kind, '')) like 'TIMESHEET%'
      )
  ),
  all_rows as (
    select * from finance_rows
    union all
    select * from snoozed_timesheet_rows
  ),
  wtd_recovery_by_case_type as (
    with settled_items as (
      select
        coalesce(pbi.finance_case_id, replace(pbi.source_ref, 'advance:', '')::uuid) as finance_case_id,
        pbi.item_type,
        round(sum(abs(coalesce(pbi.amount_ex_vat, 0))), 2)::numeric(12,2) as recovered_wtd
      from public.pay_batch_candidates pbc
      join public.pay_batches pb
        on pb.id = pbc.pay_batch_id
      join public.pay_batch_items pbi
        on pbi.pay_batch_candidate_id = pbc.id
      where pbc.candidate_id = p_candidate_id
        and pb.pay_date >= v_week_start
        and pb.pay_date <= v_week_end
        and upper(coalesce(pb.status::text, '')) <> 'CANCELLED'
        and pbc.settled_at_utc is not null
        and upper(coalesce(pbc.settlement_status, '')) = 'SETTLED'
        and coalesce(pbi.is_voided, false) = false
        and (
          pbi.finance_case_id is not null
          or pbi.source_ref ~ '^advance:[0-9a-fA-F-]{36}$'
        )
      group by coalesce(pbi.finance_case_id, replace(pbi.source_ref, 'advance:', '')::uuid), pbi.item_type
    )
    select
      ar.finance_case_id,
      round(coalesce(sum(si.recovered_wtd), 0), 2)::numeric(12,2) as recovered_wtd
    from all_rows ar
    left join settled_items si
      on si.finance_case_id = ar.finance_case_id
    where ar.finance_case_id is not null
    group by ar.finance_case_id
  )
  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'row_group', ar.row_group,
          'row_kind', ar.row_kind,
          'finance_case_id', case when ar.finance_case_id is null then null else ar.finance_case_id::text end,
          'case_type', ar.case_type,
          'candidate_id', ar.candidate_id::text,
          'candidate_tms_ref', ar.candidate_tms_ref,
          'candidate_display_name', ar.candidate_display_name,
          'client_id', case when ar.client_id is null then null else ar.client_id::text end,
          'client_name', ar.client_name,
          'linked_timesheet_id', case when ar.linked_timesheet_id is null then null else ar.linked_timesheet_id::text end,
          'created_at', case when ar.created_at is null then null else ar.created_at::text end,
          'start_week_start', case when ar.start_week_start is null then null else ar.start_week_start::text end,
          'next_due_week_start', case when ar.next_due_week_start is null then null else ar.next_due_week_start::text end,
          'original_amount', ar.original_amount,
          'recovered_total', ar.recovered_total,
          'recovered_wtd', coalesce(wr.recovered_wtd, 0),
          'remaining_outstanding', ar.remaining_outstanding,
          'due_this_week', ar.due_this_week,
          'status', ar.status,
          'payout_status', ar.payout_status,
          'reason', ar.reason,
          'notes', ar.notes,
          'adjustment_comment', ar.adjustment_comment,
          'source_original_paid_amount', ar.source_original_paid_amount,
          'source_corrected_paid_amount', ar.source_corrected_paid_amount,
          'minimum_earnings_threshold', ar.minimum_earnings_threshold,
          'take_home_floor_override', ar.take_home_floor_override,
          'active_snooze_id', case when ar.active_snooze_id is null then null else ar.active_snooze_id::text end,
          'active_snooze_kind', ar.active_snooze_kind,
          'active_snooze_until_date', case when ar.active_snooze_until_date is null then null else ar.active_snooze_until_date::text end,
          'active_snooze_note', ar.active_snooze_note,
          'snooze_status', ar.snooze_status,
          'lifecycle_state', ar.lifecycle_state,
          'authoritative_payment_date', case when ar.authoritative_payment_date is null then null else ar.authoritative_payment_date::text end,
          'payout_or_recovery_status', ar.payout_or_recovery_status,
          'is_mixed_case', ar.is_mixed_case,
          'open_taxable_count', ar.open_taxable_count,
          'open_reimbursement_count', ar.open_reimbursement_count,
          'unresolved_taxable_count', ar.unresolved_taxable_count,
          'stale_count', ar.stale_count,
          'component_resolution_summary_json', coalesce(ar.component_resolution_summary_json, '{}'::jsonb)
        )
        order by ar.created_at desc nulls last, ar.finance_case_id asc nulls last, ar.linked_timesheet_id asc nulls last
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'paid_wtd', round(coalesce(v_paid_wtd, 0), 2)::numeric(12,2),
      'counts_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', count(*) filter (where ar.row_group = 'PAYMENT_ADVANCE'),
        'OVERPAYMENT', count(*) filter (where ar.row_group = 'OVERPAYMENT'),
        'UNDERPAYMENT', count(*) filter (where ar.row_group = 'UNDERPAYMENT'),
        'MANUAL_DEBT_ADJUSTMENT', count(*) filter (where ar.row_group = 'MANUAL_DEBT_ADJUSTMENT'),
        'MANUAL_CREDIT_ADJUSTMENT', count(*) filter (where ar.row_group = 'MANUAL_CREDIT_ADJUSTMENT'),
        'SNOOZED_DEFERRED', count(*) filter (where ar.row_group = 'SNOOZED_DEFERRED')
      ),
      'totals_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', round(coalesce(sum(case when ar.row_group = 'PAYMENT_ADVANCE' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'OVERPAYMENT', round(coalesce(sum(case when ar.row_group = 'OVERPAYMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'UNDERPAYMENT', round(coalesce(sum(case when ar.row_group = 'UNDERPAYMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_DEBT_ADJUSTMENT' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_CREDIT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_CREDIT_ADJUSTMENT' then ar.original_amount else 0 end), 0), 2)::numeric(12,2),
        'SNOOZED_DEFERRED', round(coalesce(sum(case when ar.row_group = 'SNOOZED_DEFERRED' then ar.remaining_outstanding else 0 end), 0), 2)::numeric(12,2)
      ),
      'recovered_wtd_by_group', jsonb_build_object(
        'PAYMENT_ADVANCE', round(coalesce(sum(case when ar.row_group = 'PAYMENT_ADVANCE' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'OVERPAYMENT', round(coalesce(sum(case when ar.row_group = 'OVERPAYMENT' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'UNDERPAYMENT', 0::numeric(12,2),
        'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when ar.row_group = 'MANUAL_DEBT_ADJUSTMENT' then coalesce(wr.recovered_wtd, 0) else 0 end), 0), 2)::numeric(12,2),
        'MANUAL_CREDIT_ADJUSTMENT', 0::numeric(12,2),
        'SNOOZED_DEFERRED', 0::numeric(12,2)
      ),
      'component_totals', jsonb_build_object(
        'mixed_case_count', count(*) filter (where ar.is_mixed_case = true),
        'open_taxable_count_total', coalesce(sum(ar.open_taxable_count), 0),
        'open_reimbursement_count_total', coalesce(sum(ar.open_reimbursement_count), 0),
        'unresolved_taxable_count_total', coalesce(sum(ar.unresolved_taxable_count), 0),
        'stale_count_total', coalesce(sum(ar.stale_count), 0)
      )
    )
  into
    v_rows,
    v_summary
  from all_rows ar
  left join wtd_recovery_by_case_type wr
    on wr.finance_case_id = ar.finance_case_id;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'PAYMENT_ADVANCE'),
    '[]'::jsonb
  ) into v_payment_advances;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'OVERPAYMENT'),
    '[]'::jsonb
  ) into v_overpayments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'UNDERPAYMENT'),
    '[]'::jsonb
  ) into v_underpayments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'),
    '[]'::jsonb
  ) into v_manual_debt_adjustments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'),
    '[]'::jsonb
  ) into v_manual_credit_adjustments;

  select coalesce(
    (select jsonb_agg(x.elem) from jsonb_array_elements(v_rows) as x(elem) where x.elem->>'row_group' = 'SNOOZED_DEFERRED'),
    '[]'::jsonb
  ) into v_snoozed_deferred_items;

  return jsonb_build_object(
    'ok', true,
    'candidate', jsonb_build_object(
      'id', v_candidate.id::text,
      'tms_ref', v_candidate.tms_ref,
      'display_name', v_candidate.display_name,
      'first_name', v_candidate.first_name,
      'last_name', v_candidate.last_name,
      'active', v_candidate.active
    ),
    'week_start', v_week_start::text,
    'week_end', v_week_end::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'payment_advances', coalesce(v_payment_advances, '[]'::jsonb),
    'overpayments', coalesce(v_overpayments, '[]'::jsonb),
    'underpayments', coalesce(v_underpayments, '[]'::jsonb),
    'manual_debt_adjustments', coalesce(v_manual_debt_adjustments, '[]'::jsonb),
    'manual_credit_adjustments', coalesce(v_manual_credit_adjustments, '[]'::jsonb),
    'snoozed_deferred_items', coalesce(v_snoozed_deferred_items, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_advances_register(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_search text DEFAULT NULL::text,
  p_type text DEFAULT NULL::text,
  p_status text DEFAULT NULL::text,
  p_client_id uuid DEFAULT NULL::uuid,
  p_outstanding_only boolean DEFAULT true,
  p_due_this_week_only boolean DEFAULT false,
  p_amount_min numeric DEFAULT NULL::numeric,
  p_amount_max numeric DEFAULT NULL::numeric,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text,
  p_limit integer DEFAULT 500,
  p_offset integer DEFAULT 0,
  p_as_of_date date DEFAULT NULL::date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_as_of_date date := coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date);
  v_week_start date := public._pay_week_start_monday(coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date));
  v_week_end date := (public._pay_week_start_monday(coalesce(p_as_of_date, (now() at time zone 'Europe/London')::date)) + 6);

  v_search text := nullif(btrim(coalesce(p_search, '')), '');
  v_type text := upper(btrim(coalesce(p_type, '')));
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_sort_key text := lower(btrim(coalesce(p_sort_key, 'created_at')));
  v_sort_dir text := upper(btrim(coalesce(p_sort_dir, 'DESC')));

  v_limit integer := greatest(1, least(coalesce(p_limit, 500), 10000));
  v_offset integer := greatest(0, coalesce(p_offset, 0));

  v_total_count integer := 0;
  v_summary jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_type_filter text := null;
begin
  if v_sort_dir not in ('ASC', 'DESC') then
    v_sort_dir := 'DESC';
  end if;

  if v_sort_key not in (
    'candidate',
    'client',
    'type',
    'status',
    'created_at',
    'original_amount',
    'recovered_total',
    'remaining_outstanding',
    'due_this_week',
    'start_week_start',
    'next_due_week_start',
    'authoritative_payment_date'
  ) then
    v_sort_key := 'created_at';
  end if;

  if v_type <> '' then
    v_type_filter := case
      when v_type in ('PAYMENT_ADVANCE', 'LOAN', 'ADVANCE', 'MISSING_SHIFT_ADVANCE') then 'PAYMENT_ADVANCE'
      when v_type = 'OVERPAYMENT' then 'OVERPAYMENT'
      when v_type = 'MANUAL_DEBT_ADJUSTMENT' then 'MANUAL_DEBT_ADJUSTMENT'
      when v_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'MANUAL_CREDIT_ADJUSTMENT'
      when v_type in ('SNOOZED', 'DEFERRED', 'SNOOZED_DEFERRED') then 'SNOOZED_DEFERRED'
      else v_type
    end;
  end if;

  with finance_rows as (
    select
      case
        when vfc.active_snooze_id is not null then 'SNOOZED_DEFERRED'
        else vfc.case_type::text
      end as row_group,
      'FINANCE_CASE'::text as row_kind,
      vfc.finance_case_id,
      vfc.case_type::text as case_type,
      vfc.candidate_id,
      vfc.candidate_tms_ref,
      vfc.candidate_display_name,
      vfc.candidate_first_name,
      vfc.candidate_last_name,
      vfc.client_id,
      vfc.client_name,
      vfc.linked_timesheet_id,
      vfc.linked_shift_date,
      vfc.payout_pay_batch_id,
      vfc.payout_transfer_id,
      vfc.latest_recovery_pay_batch_id,
      vfc.created_at,
      vfc.start_week_start,
      vfc.next_due_week_start,
      round(coalesce(vfc.original_amount, 0), 2)::numeric(12,2) as original_amount,
      round(
        case
          when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 0
          else greatest(coalesce(vfc.original_amount, 0) - coalesce(vfc.outstanding_amount, 0), 0)
        end,
        2
      )::numeric(12,2) as recovered_total,
      round(coalesce(vfc.outstanding_amount, 0), 2)::numeric(12,2) as remaining_outstanding,
      round(
        case
          when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
           and coalesce(vfc.written_off_at_utc, null) is null
           and coalesce(vfc.cleared_at_utc, null) is null
           and upper(coalesce(vfc.status, '')) not in ('PAID_OFF', 'CLEARED')
           and vfc.next_due_week_start is not null
           and vfc.next_due_week_start <= v_week_start
          then least(coalesce(vfc.weekly_due, 0), coalesce(vfc.outstanding_amount, 0))
          else 0
        end,
        2
      )::numeric(12,2) as due_this_week,
      vfc.status,
      vfc.payout_status,
      vfc.baseline_signature,
      vfc.reason,
      vfc.notes,
      vfc.adjustment_comment,
      vfc.source_original_paid_amount,
      vfc.source_corrected_paid_amount,
      vfc.minimum_earnings_threshold,
      vfc.take_home_floor_override,
      vfc.active_snooze_id,
      vfc.active_snooze_kind,
      vfc.active_snooze_until_date,
      vfc.active_snooze_note,
      case
        when vfc.active_snooze_id is null then 'NONE'
        when vfc.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      case
        when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
        when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'CLEARED'
        when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RESERVED'
        when coalesce(vfc.committed_amount, 0) > 0 then 'COMMITTED'
        when coalesce(vfc.settled_amount, 0) > 0 then 'SETTLED'
        when vfc.active_snooze_id is not null then 'SNOOZED'
        else upper(coalesce(vfc.status, 'ACTIVE'))
      end as lifecycle_state,
      case
        when vfc.case_type in ('PAYMENT_ADVANCE', 'MANUAL_CREDIT_ADJUSTMENT') then coalesce(pbp.authoritative_payment_date, pbp.pay_date)
        else coalesce(pbr.authoritative_payment_date, pbr.pay_date)
      end as authoritative_payment_date,
      case
        when vfc.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfc.payout_status, 'NOT_PAID')
        when vfc.case_type = 'PAYMENT_ADVANCE' then
          case
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) > 0 then 'RECOVERY_ACTIVE'
            when coalesce(vfc.payout_status, '') = 'PAID' and coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            else coalesce(vfc.payout_status, 'NOT_PAID')
          end
        when vfc.case_type in ('OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT') then
          case
            when vfc.written_off_at_utc is not null then 'WRITTEN_OFF'
            when vfc.cleared_at_utc is not null or upper(coalesce(vfc.status, '')) in ('PAID_OFF', 'CLEARED') or coalesce(vfc.outstanding_amount, 0) <= 0 then 'RECOVERY_CLEARED'
            when coalesce(vfc.active_reserved_amount, 0) > 0 then 'RECOVERY_RESERVED'
            when coalesce(vfc.committed_amount, 0) > 0 then 'RECOVERY_COMMITTED'
            when coalesce(vfc.settled_amount, 0) > 0 then 'RECOVERY_SETTLED'
            else 'RECOVERY_ACTIVE'
          end
        else coalesce(vfc.status, 'ACTIVE')
      end as payout_or_recovery_status,
      null::text as source_booking_id,
      null::date as source_week_ending_date,
      null::text as source_shift_label_norm
    from public.v_finance_cases_register vfc
    left join public.pay_batches pbp
      on pbp.id = vfc.payout_pay_batch_id
    left join public.pay_batches pbr
      on pbr.id = vfc.latest_recovery_pay_batch_id
  ),
  snoozed_timesheet_rows as (
    select
      'SNOOZED_DEFERRED'::text as row_group,
      'TIMESHEET_SNOOZE'::text as row_kind,
      null::uuid as finance_case_id,
      null::text as case_type,
      c.id as candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      c.first_name as candidate_first_name,
      c.last_name as candidate_last_name,
      cli.id as client_id,
      cli.name as client_name,
      s.timesheet_id as linked_timesheet_id,
      null::date as linked_shift_date,
      null::uuid as payout_pay_batch_id,
      null::uuid as payout_transfer_id,
      null::uuid as latest_recovery_pay_batch_id,
      s.created_at_utc as created_at,
      null::date as start_week_start,
      null::date as next_due_week_start,
      0::numeric(12,2) as original_amount,
      0::numeric(12,2) as recovered_total,
      0::numeric(12,2) as remaining_outstanding,
      0::numeric(12,2) as due_this_week,
      null::text as status,
      null::text as payout_status,
      null::text as baseline_signature,
      null::text as reason,
      null::text as notes,
      null::text as adjustment_comment,
      null::numeric as source_original_paid_amount,
      null::numeric as source_corrected_paid_amount,
      null::numeric as minimum_earnings_threshold,
      null::numeric as take_home_floor_override,
      s.id as active_snooze_id,
      upper(coalesce(s.snooze_kind, '')) as active_snooze_kind,
      s.snooze_until_date as active_snooze_until_date,
      s.note as active_snooze_note,
      case
        when s.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_status,
      'SNOOZED'::text as lifecycle_state,
      null::date as authoritative_payment_date,
      'DEFERRED'::text as payout_or_recovery_status,
      ts.booking_id as source_booking_id,
      ts.week_ending_date as source_week_ending_date,
      ts.shift_label_norm as source_shift_label_norm
    from public.pay_item_snoozes s
    join public.timesheets ts
      on ts.timesheet_id = s.timesheet_id
    join public.candidates c
      on c.id = s.candidate_id
    left join public.contracts ct
      on ct.id = ts.contract_id
    left join public.clients cli
      on cli.id = ct.client_id
    where s.cleared_at_utc is null
      and s.timesheet_id is not null
      and s.source_ref is null
      and (
        upper(coalesce(s.snooze_kind, '')) in ('TIMESHEET_PAYMENT', 'BLOCKED_TIMESHEET', 'DO_NOT_PAY')
        or upper(coalesce(s.snooze_kind, '')) like 'TIMESHEET%'
      )
  ),
  base_rows as (
    select * from finance_rows
    union all
    select * from snoozed_timesheet_rows
  ),
  filtered_rows as (
    select
      br.row_group,
      br.row_kind,
      br.finance_case_id,
      br.case_type,
      br.candidate_id,
      br.candidate_tms_ref,
      br.candidate_display_name,
      br.candidate_first_name,
      br.candidate_last_name,
      br.client_id,
      br.client_name,
      br.linked_timesheet_id,
      br.linked_shift_date,
      br.payout_pay_batch_id,
      br.payout_transfer_id,
      br.latest_recovery_pay_batch_id,
      br.created_at,
      br.start_week_start,
      br.next_due_week_start,
      br.original_amount,
      br.recovered_total,
      br.remaining_outstanding,
      br.due_this_week,
      br.status,
      br.payout_status,
      br.baseline_signature,
      br.reason,
      br.notes,
      br.adjustment_comment,
      br.source_original_paid_amount,
      br.source_corrected_paid_amount,
      br.minimum_earnings_threshold,
      br.take_home_floor_override,
      br.active_snooze_id,
      br.active_snooze_kind,
      br.active_snooze_until_date,
      br.active_snooze_note,
      br.snooze_status,
      br.lifecycle_state,
      br.authoritative_payment_date,
      br.payout_or_recovery_status,
      br.source_booking_id,
      br.source_week_ending_date,
      br.source_shift_label_norm
    from base_rows br
    where (v_type_filter is null or br.row_group = v_type_filter)
      and (
        v_status = ''
        or upper(coalesce(br.lifecycle_state, '')) = v_status
        or upper(coalesce(br.status, '')) = v_status
        or upper(coalesce(br.payout_or_recovery_status, '')) = v_status
        or upper(coalesce(br.row_group, '')) = v_status
      )
      and (p_client_id is null or br.client_id is not distinct from p_client_id)
      and (
        coalesce(p_outstanding_only, true) = false
        or br.row_group = 'SNOOZED_DEFERRED'
        or coalesce(br.remaining_outstanding, 0) > 0
      )
      and (
        coalesce(p_due_this_week_only, false) = false
        or coalesce(br.due_this_week, 0) > 0
      )
      and (p_amount_min is null or coalesce(br.remaining_outstanding, 0) >= round(p_amount_min, 2))
      and (p_amount_max is null or coalesce(br.remaining_outstanding, 0) <= round(p_amount_max, 2))
      and (
        p_created_from is null
        or br.created_at is not null
        and (br.created_at at time zone 'Europe/London')::date >= p_created_from
      )
      and (
        p_created_to is null
        or br.created_at is not null
        and (br.created_at at time zone 'Europe/London')::date <= p_created_to
      )
      and (
        v_search is null
        or coalesce(br.candidate_tms_ref, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_display_name, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_first_name, '') ilike '%' || v_search || '%'
        or coalesce(br.candidate_last_name, '') ilike '%' || v_search || '%'
        or coalesce(br.client_name, '') ilike '%' || v_search || '%'
        or coalesce(br.adjustment_comment, '') ilike '%' || v_search || '%'
        or coalesce(br.notes, '') ilike '%' || v_search || '%'
        or coalesce(br.reason, '') ilike '%' || v_search || '%'
      )
  ),
  counted_rows as (
    select count(*)::int as total_count from filtered_rows
  ),
  summary_rows as (
    select
      jsonb_build_object(
        'row_count', count(*)::int,
        'week_start', v_week_start::text,
        'week_end', v_week_end::text,
        'as_of_date', v_as_of_date::text,
        'counts_by_group', jsonb_build_object(
          'PAYMENT_ADVANCE', count(*) filter (where fr.row_group = 'PAYMENT_ADVANCE'),
          'OVERPAYMENT', count(*) filter (where fr.row_group = 'OVERPAYMENT'),
          'MANUAL_DEBT_ADJUSTMENT', count(*) filter (where fr.row_group = 'MANUAL_DEBT_ADJUSTMENT'),
          'MANUAL_CREDIT_ADJUSTMENT', count(*) filter (where fr.row_group = 'MANUAL_CREDIT_ADJUSTMENT'),
          'SNOOZED_DEFERRED', count(*) filter (where fr.row_group = 'SNOOZED_DEFERRED')
        ),
        'totals_by_group', jsonb_build_object(
          'PAYMENT_ADVANCE', round(coalesce(sum(case when fr.row_group = 'PAYMENT_ADVANCE' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'OVERPAYMENT', round(coalesce(sum(case when fr.row_group = 'OVERPAYMENT' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'MANUAL_DEBT_ADJUSTMENT', round(coalesce(sum(case when fr.row_group = 'MANUAL_DEBT_ADJUSTMENT' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2),
          'MANUAL_CREDIT_ADJUSTMENT', round(coalesce(sum(case when fr.row_group = 'MANUAL_CREDIT_ADJUSTMENT' then fr.original_amount else 0 end), 0), 2)::numeric(12,2),
          'SNOOZED_DEFERRED', round(coalesce(sum(case when fr.row_group = 'SNOOZED_DEFERRED' then fr.remaining_outstanding else 0 end), 0), 2)::numeric(12,2)
        ),
        'due_this_week_total', round(coalesce(sum(coalesce(fr.due_this_week, 0)), 0), 2)::numeric(12,2)
      ) as summary_json
    from filtered_rows fr
  ),
  ordered_rows as (
    select
      fr.row_group,
      fr.row_kind,
      fr.finance_case_id,
      fr.case_type,
      fr.candidate_id,
      fr.candidate_tms_ref,
      fr.candidate_display_name,
      fr.candidate_first_name,
      fr.candidate_last_name,
      fr.client_id,
      fr.client_name,
      fr.linked_timesheet_id,
      fr.linked_shift_date,
      fr.payout_pay_batch_id,
      fr.payout_transfer_id,
      fr.latest_recovery_pay_batch_id,
      fr.created_at,
      fr.start_week_start,
      fr.next_due_week_start,
      fr.original_amount,
      fr.recovered_total,
      fr.remaining_outstanding,
      fr.due_this_week,
      fr.status,
      fr.payout_status,
      fr.baseline_signature,
      fr.reason,
      fr.notes,
      fr.adjustment_comment,
      fr.source_original_paid_amount,
      fr.source_corrected_paid_amount,
      fr.minimum_earnings_threshold,
      fr.take_home_floor_override,
      fr.active_snooze_id,
      fr.active_snooze_kind,
      fr.active_snooze_until_date,
      fr.active_snooze_note,
      fr.snooze_status,
      fr.lifecycle_state,
      fr.authoritative_payment_date,
      fr.payout_or_recovery_status,
      fr.source_booking_id,
      fr.source_week_ending_date,
      fr.source_shift_label_norm
    from filtered_rows fr
    order by
      case when v_sort_dir = 'ASC' and v_sort_key = 'candidate' then lower(coalesce(fr.candidate_display_name, fr.candidate_tms_ref, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'candidate' then lower(coalesce(fr.candidate_display_name, fr.candidate_tms_ref, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'client' then lower(coalesce(fr.client_name, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'client' then lower(coalesce(fr.client_name, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'type' then lower(coalesce(fr.row_group, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'type' then lower(coalesce(fr.row_group, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'status' then lower(coalesce(fr.lifecycle_state, fr.status, '')) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'status' then lower(coalesce(fr.lifecycle_state, fr.status, '')) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'created_at' then fr.created_at end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'created_at' then fr.created_at end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'original_amount' then fr.original_amount end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'original_amount' then fr.original_amount end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'recovered_total' then fr.recovered_total end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'recovered_total' then fr.recovered_total end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'remaining_outstanding' then fr.remaining_outstanding end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'remaining_outstanding' then fr.remaining_outstanding end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'due_this_week' then coalesce(fr.due_this_week, 0) end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'due_this_week' then coalesce(fr.due_this_week, 0) end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'start_week_start' then fr.start_week_start end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'start_week_start' then fr.start_week_start end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'next_due_week_start' then fr.next_due_week_start end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'next_due_week_start' then fr.next_due_week_start end desc nulls last,
      case when v_sort_dir = 'ASC' and v_sort_key = 'authoritative_payment_date' then fr.authoritative_payment_date end asc nulls last,
      case when v_sort_dir = 'DESC' and v_sort_key = 'authoritative_payment_date' then fr.authoritative_payment_date end desc nulls last,
      fr.created_at desc nulls last,
      fr.finance_case_id asc nulls last,
      fr.linked_timesheet_id asc nulls last
    limit v_limit
    offset v_offset
  )
  select
    coalesce(cr.total_count, 0),
    coalesce(sr.summary_json, '{}'::jsonb),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'record_type', orw.row_group,
          'row_group', orw.row_group,
          'row_kind', orw.row_kind,
          'finance_case_id', case when orw.finance_case_id is null then null else orw.finance_case_id::text end,
          'case_type', orw.case_type,
          'candidate_id', orw.candidate_id::text,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_display_name', orw.candidate_display_name,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'client_id', case when orw.client_id is null then null else orw.client_id::text end,
          'client_name', orw.client_name,
          'linked_timesheet_id', case when orw.linked_timesheet_id is null then null else orw.linked_timesheet_id::text end,
          'linked_shift_date', case when orw.linked_shift_date is null then null else orw.linked_shift_date::text end,
          'payout_pay_batch_id', case when orw.payout_pay_batch_id is null then null else orw.payout_pay_batch_id::text end,
          'payout_transfer_id', case when orw.payout_transfer_id is null then null else orw.payout_transfer_id::text end,
          'latest_recovery_pay_batch_id', case when orw.latest_recovery_pay_batch_id is null then null else orw.latest_recovery_pay_batch_id::text end,
          'created_at', case when orw.created_at is null then null else orw.created_at::text end,
          'start_week_start', case when orw.start_week_start is null then null else orw.start_week_start::text end,
          'next_due_week_start', case when orw.next_due_week_start is null then null else orw.next_due_week_start::text end,
          'original_amount', orw.original_amount,
          'recovered_total', orw.recovered_total,
          'remaining_outstanding', orw.remaining_outstanding,
          'due_this_week', orw.due_this_week,
          'status', orw.status,
          'payout_status', orw.payout_status,
          'baseline_signature', orw.baseline_signature,
          'reason', orw.reason,
          'notes', orw.notes,
          'adjustment_comment', orw.adjustment_comment,
          'source_original_paid_amount', orw.source_original_paid_amount,
          'source_corrected_paid_amount', orw.source_corrected_paid_amount,
          'minimum_earnings_threshold', orw.minimum_earnings_threshold,
          'take_home_floor_override', orw.take_home_floor_override,
          'active_snooze_id', case when orw.active_snooze_id is null then null else orw.active_snooze_id::text end,
          'active_snooze_kind', orw.active_snooze_kind,
          'active_snooze_until_date', case when orw.active_snooze_until_date is null then null else orw.active_snooze_until_date::text end,
          'active_snooze_note', orw.active_snooze_note,
          'snooze_status', orw.snooze_status,
          'lifecycle_state', orw.lifecycle_state,
          'authoritative_payment_date', case when orw.authoritative_payment_date is null then null else orw.authoritative_payment_date::text end,
          'payout_or_recovery_status', orw.payout_or_recovery_status,
          'source_booking_id', orw.source_booking_id,
          'source_week_ending_date', case when orw.source_week_ending_date is null then null else orw.source_week_ending_date::text end,
          'source_shift_label_norm', orw.source_shift_label_norm
        )
      ),
      '[]'::jsonb
    )
  into
    v_total_count,
    v_summary,
    v_rows
  from ordered_rows orw
  cross join counted_rows cr
  cross join summary_rows sr;

  return jsonb_build_object(
    'ok', true,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb),
    'meta', jsonb_build_object(
      'as_of_date', v_as_of_date::text,
      'today_uk', v_today_uk::text,
      'week_start', v_week_start::text,
      'week_end', v_week_end::text,
      'total_count', v_total_count,
      'limit', v_limit,
      'offset', v_offset,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir,
      'applied_filters', jsonb_build_object(
        'search', v_search,
        'type', case when v_type_filter is null then null else v_type_filter end,
        'status', case when v_status = '' then null else v_status end,
        'client_id', case when p_client_id is null then null else p_client_id::text end,
        'outstanding_only', coalesce(p_outstanding_only, true),
        'due_this_week_only', coalesce(p_due_this_week_only, false),
        'amount_min', p_amount_min,
        'amount_max', p_amount_max,
        'created_from', case when p_created_from is null then null else p_created_from::text end,
        'created_to', case when p_created_to is null then null else p_created_to::text end
      )
    )
  );
end;
$function$;




CREATE OR REPLACE FUNCTION public.pay_advances_register_pdf_payload(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_search text DEFAULT NULL::text,
  p_type text DEFAULT NULL::text,
  p_status text DEFAULT NULL::text,
  p_client_id uuid DEFAULT NULL::uuid,
  p_outstanding_only boolean DEFAULT true,
  p_due_this_week_only boolean DEFAULT false,
  p_amount_min numeric DEFAULT NULL::numeric,
  p_amount_max numeric DEFAULT NULL::numeric,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text,
  p_as_of_date date DEFAULT NULL::date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
begin
  v_base := public.pay_advances_register(
    p_actor_user_id => p_actor_user_id,
    p_search => p_search,
    p_type => p_type,
    p_status => p_status,
    p_client_id => p_client_id,
    p_outstanding_only => p_outstanding_only,
    p_due_this_week_only => p_due_this_week_only,
    p_amount_min => p_amount_min,
    p_amount_max => p_amount_max,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir,
    p_limit => 100000,
    p_offset => 0,
    p_as_of_date => p_as_of_date
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  select jsonb_build_array(
    jsonb_build_object(
      'record_type', 'PAYMENT_ADVANCE',
      'title', 'Payment Advances',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'PAYMENT_ADVANCE'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'OVERPAYMENT',
      'title', 'Overpayments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'OVERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'MANUAL_DEBT_ADJUSTMENT',
      'title', 'Manual Debt Adjustments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'MANUAL_CREDIT_ADJUSTMENT',
      'title', 'Manual Credit Adjustments',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'record_type', 'SNOOZED_DEFERRED',
      'title', 'Snoozed / Deferred items',
      'rows', coalesce((select jsonb_agg(e.elem) from jsonb_array_elements(v_rows) as e(elem) where e.elem->>'row_group' = 'SNOOZED_DEFERRED'), '[]'::jsonb)
    )
  )
  into v_groups;

  return jsonb_build_object(
    'ok', true,
    'title', 'Finance Cases & Snoozes Register',
    'generated_at_utc', now()::text,
    'applied_filters', coalesce(v_base->'meta'->'applied_filters', '{}'::jsonb),
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'rows', v_rows,
    'groups', coalesce(v_groups, '[]'::jsonb)
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.pay_paye_guardrails(
  p_pay_date date,
  p_ignore_pay_batch_id uuid DEFAULT NULL::uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_pay_date date := p_pay_date;
  v_week_start date;
  v_week_end date;

  v_existing_draft_batch_id uuid := null;
  v_existing_draft_status text := null;
  v_existing_draft_pay_date date := null;
  v_existing_draft_authoritative_payment_date date := null;
  v_existing_draft_created_at_utc timestamptz := null;

  v_has_existing_paye_draft boolean := false;
  v_has_same_week_non_draft_paye_batch boolean := false;
  v_override_required boolean := false;
  v_create_paye_blocked boolean := false;

  v_same_week_batches jsonb := '[]'::jsonb;

  v_blocking_copy jsonb := '{}'::jsonb;
  v_override_copy jsonb := '{}'::jsonb;
  v_active_copy jsonb := '{}'::jsonb;

  v_result jsonb := '{}'::jsonb;
begin
  if v_pay_date is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYE_GUARDRAILS',
      'code', 'PAY_DATE_REQUIRED',
      'message', 'pay_paye_guardrails: pay_date is required'
    )::text;
  end if;

  v_week_start := date_trunc('week', v_pay_date::timestamp)::date;
  v_week_end := v_week_start + 6;

  with paye_batches as (
    select distinct
      pb.id,
      upper(coalesce(pb.status, '')) as status_upper,
      pb.status,
      pb.pay_date,
      pb.authoritative_payment_date,
      pb.created_at_utc,
      pb.batch_kind_fixed
    from public.pay_batches pb
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = pb.id
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    where upper(coalesce(pbi.pay_channel, '')) = 'PAYE'
      and upper(coalesce(pb.batch_kind_fixed, '')) <> 'LOANS'
      and (p_ignore_pay_batch_id is null or pb.id <> p_ignore_pay_batch_id)
  ),
  existing_draft as (
    select
      b.id,
      b.status,
      b.pay_date,
      b.authoritative_payment_date,
      b.created_at_utc
    from paye_batches b
    where b.status_upper in ('DRAFT', 'DRAFT_CREATED')
    order by b.created_at_utc asc, b.id asc
    limit 1
  ),
  same_week_non_draft as (
    select
      b.id,
      b.status,
      b.pay_date,
      b.authoritative_payment_date,
      b.created_at_utc
    from paye_batches b
    where b.status_upper not in ('DRAFT', 'DRAFT_CREATED', 'CANCELLED')
      and coalesce(b.authoritative_payment_date, b.pay_date) between v_week_start and v_week_end
    order by coalesce(b.authoritative_payment_date, b.pay_date) asc, b.created_at_utc asc, b.id asc
  )
  select
    ed.id,
    ed.status,
    ed.pay_date,
    ed.authoritative_payment_date,
    ed.created_at_utc,
    coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'pay_batch_id', sw.id::text,
            'status', sw.status,
            'pay_date', case when sw.pay_date is null then null else sw.pay_date::text end,
            'authoritative_payment_date', case when sw.authoritative_payment_date is null then null else sw.authoritative_payment_date::text end,
            'created_at_utc', sw.created_at_utc
          )
          order by coalesce(sw.authoritative_payment_date, sw.pay_date), sw.created_at_utc, sw.id
        )
        from same_week_non_draft sw
      ),
      '[]'::jsonb
    )
  into
    v_existing_draft_batch_id,
    v_existing_draft_status,
    v_existing_draft_pay_date,
    v_existing_draft_authoritative_payment_date,
    v_existing_draft_created_at_utc,
    v_same_week_batches
  from existing_draft ed
  right join (select 1 as keep_row) k
    on true;

  v_has_existing_paye_draft := v_existing_draft_batch_id is not null;
  v_has_same_week_non_draft_paye_batch := jsonb_array_length(coalesce(v_same_week_batches, '[]'::jsonb)) > 0;

  v_create_paye_blocked := v_has_existing_paye_draft;
  v_override_required := (not v_has_existing_paye_draft) and v_has_same_week_non_draft_paye_batch;

  v_blocking_copy := jsonb_build_object(
    'severity', 'BLOCK',
    'code', 'PAYE_DRAFT_ALREADY_EXISTS',
    'title', 'Existing PAYE draft already exists',
    'message', 'A PAYE draft batch already exists. Cancel or delete the existing PAYE draft before creating another PAYE draft.',
    'action_hint', 'CANCEL_EXISTING_PAYE_DRAFT_FIRST',
    'frontend_can_continue', false
  );

  v_override_copy := jsonb_build_object(
    'severity', 'WARNING',
    'code', 'PAYE_SAME_WEEK_OVERRIDE_REQUIRED',
    'title', 'A PAYE batch already exists for this payroll week',
    'message', 'A non-draft PAYE batch already exists in this Monday-based payroll week. Creating another PAYE batch for the same week is override-only. Replacement or cancellation is usually the correct path. Continue only after password reauthentication, 2FA, and explicit confirmation.',
    'action_hint', 'REAUTH_THEN_2FA_THEN_EXPLICIT_CONTINUE',
    'frontend_can_continue', true
  );

  if v_create_paye_blocked then
    v_active_copy := v_blocking_copy;
  elsif v_override_required then
    v_active_copy := v_override_copy;
  else
    v_active_copy := jsonb_build_object(
      'severity', 'INFO',
      'code', 'PAYE_GUARDRAILS_CLEAR',
      'title', 'PAYE guardrails clear',
      'message', 'No existing PAYE draft was found and no same-week PAYE override is required.',
      'action_hint', 'NONE',
      'frontend_can_continue', true
    );
  end if;

  v_result := jsonb_build_object(
    'ok', true,
    'pay_date', v_pay_date::text,
    'pay_week_start', v_week_start::text,
    'pay_week_end', v_week_end::text,
    'has_existing_paye_draft', v_has_existing_paye_draft,
    'existing_paye_draft', case
      when v_existing_draft_batch_id is null then null
      else jsonb_build_object(
        'pay_batch_id', v_existing_draft_batch_id::text,
        'status', v_existing_draft_status,
        'pay_date', case when v_existing_draft_pay_date is null then null else v_existing_draft_pay_date::text end,
        'authoritative_payment_date', case when v_existing_draft_authoritative_payment_date is null then null else v_existing_draft_authoritative_payment_date::text end,
        'created_at_utc', v_existing_draft_created_at_utc
      )
    end,
    'has_same_week_non_draft_paye_batch', v_has_same_week_non_draft_paye_batch,
    'same_week_non_draft_paye_batches', coalesce(v_same_week_batches, '[]'::jsonb),
    'override_required', v_override_required,
    'create_paye_blocked', v_create_paye_blocked,
    'ui', jsonb_build_object(
      'active', v_active_copy,
      'existing_draft_block', v_blocking_copy,
      'same_week_override', v_override_copy
    )
  );

  begin
    if p_actor_user_id is not null then
      perform public._imp_debug_audit(
        p_actor_user_id,
        'PAY_PAYE_GUARDRAILS',
        v_result,
        'pay_batches',
        'pay_date:' || v_pay_date::text,
        null,
        null,
        null,
        null,
        null
      );
    end if;
  exception when others then
    null;
  end;

  return v_result;
end;
$function$;




create or replace function public.pay_finance_case_pause_resume(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_action text,
  p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_target_status public.pay_advance_status_enum;
  v_event_type text;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_action text := upper(btrim(coalesce(p_action,'')));
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_pause_resume: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_pause_resume: actor_user_id is required'
    )::text;
  end if;

  if v_action not in ('PAUSE','RESUME') then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','ACTION_INVALID',
      'message','pay_finance_case_pause_resume: action must be PAUSE or RESUME'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_pause_resume: repayable finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if coalesce(v_case.write_off_reason,'') <> '' or v_case.written_off_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','FINANCE_CASE_WRITTEN_OFF',
      'message','pay_finance_case_pause_resume: written-off finance cases cannot be paused or resumed',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount,0),2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_PAUSE_RESUME',
      'code','NO_OUTSTANDING_BALANCE',
      'message','pay_finance_case_pause_resume: finance case has no outstanding balance',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_action = 'PAUSE' then
    if v_case.status = 'PAUSED'::public.pay_advance_status_enum then
      return jsonb_build_object(
        'ok', true,
        'finance_case_id', p_finance_case_id::text,
        'case_type', v_case.case_type::text,
        'status', v_case.status::text,
        'action', 'PAUSE'
      );
    end if;
    v_target_status := 'PAUSED'::public.pay_advance_status_enum;
    v_event_type := 'PAUSED';
  else
    if v_case.status = 'ACTIVE'::public.pay_advance_status_enum then
      return jsonb_build_object(
        'ok', true,
        'finance_case_id', p_finance_case_id::text,
        'case_type', v_case.case_type::text,
        'status', v_case.status::text,
        'action', 'RESUME'
      );
    end if;
    if v_case.status <> 'PAUSED'::public.pay_advance_status_enum then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_PAUSE_RESUME',
        'code','RESUME_NOT_ALLOWED',
        'message','pay_finance_case_pause_resume: only paused finance cases can be resumed',
        'finance_case_id', p_finance_case_id::text,
        'current_status', v_case.status::text
      )::text;
    end if;
    v_target_status := 'ACTIVE'::public.pay_advance_status_enum;
    v_event_type := 'RESUMED';
  end if;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end
  );

  update public.pay_advances pa
  set status = v_target_status,
      updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_event_type,
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    nullif(btrim(coalesce(p_reason,'')), ''),
    case when v_action = 'PAUSE' then 'Finance case paused' else 'Finance case resumed' end
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'action', v_action
  );
end;
$$;

create or replace function public.pay_finance_case_write_off(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_write_off_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_released_count int := 0;
  v_write_off_reason text := nullif(btrim(coalesce(p_write_off_reason,'')), '');
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_write_off: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_write_off: actor_user_id is required'
    )::text;
  end if;

  if v_write_off_reason is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','WRITE_OFF_REASON_REQUIRED',
      'message','pay_finance_case_write_off: write_off_reason is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'OVERPAYMENT'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_WRITE_OFF',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_write_off: repayable finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.written_off_at_utc is not null or coalesce(v_case.write_off_reason,'') <> '' then
    return jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'written_off_at_utc', v_case.written_off_at_utc,
      'write_off_reason', v_case.write_off_reason
    );
  end if;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'write_off_reason', v_case.write_off_reason
  );

  update public.pay_advance_reservations par
  set status = 'RELEASED',
      released_at_utc = coalesce(par.released_at_utc, v_now_utc),
      released_reason = 'WRITE_OFF',
      updated_by_user_id = p_actor_user_id
  where par.finance_case_id = p_finance_case_id
    and par.status in ('RESERVED','COMMITTED');

  get diagnostics v_released_count = row_count;

  update public.pay_advances pa
  set
    status = 'PAID_OFF'::public.pay_advance_status_enum,
    outstanding_amount = 0,
    next_due_week_start = null::date,
    updated_at = v_now_utc,
    written_off_at_utc = v_now_utc,
    written_off_by_user_id = p_actor_user_id,
    write_off_reason = v_write_off_reason,
    cleared_at_utc = coalesce(pa.cleared_at_utc, v_now_utc),
    cleared_by_user_id = coalesce(pa.cleared_by_user_id, p_actor_user_id)
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'write_off_reason', v_case.write_off_reason,
    'released_reservation_count', v_released_count
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    'WRITTEN_OFF',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    v_write_off_reason,
    'Finance case written off'
  );

  perform public._audit_insert(
    'pay_advances',
    p_finance_case_id::text,
    'FINANCE_CASE_WRITTEN_OFF',
    v_before_json,
    v_after_json,
    v_write_off_reason,
    p_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'write_off_reason', v_case.write_off_reason,
    'written_off_at_utc', case when v_case.written_off_at_utc is null then null else v_case.written_off_at_utc::text end,
    'released_reservation_count', v_released_count
  );
end;
$$;




create or replace function public.pay_loans_snoozes_list(
  p_candidate_id uuid default null::uuid,
  p_client_id uuid default null::uuid,
  p_hide_completed_non_current_items boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_today_uk date := (now() at time zone 'Europe/London')::date;
  v_finance_cases jsonb := '[]'::jsonb;
  v_timesheet_snoozes jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_hide_completed_non_current_items boolean := coalesce(p_hide_completed_non_current_items, true);
begin
  with finance_rows as (
    select
      vfcr.finance_case_id,
      vfcr.case_type,
      vfcr.candidate_id,
      vfcr.candidate_tms_ref,
      vfcr.candidate_display_name,
      vfcr.pay_method,
      vfcr.client_id,
      vfcr.client_name,
      vfcr.status,
      vfcr.payout_status,
      vfcr.payout_pay_batch_id,
      vfcr.payout_transfer_id,
      round(coalesce(vfcr.original_amount, 0), 2) as original_amount,
      round(coalesce(vfcr.outstanding_amount, 0), 2) as outstanding_amount,
      round(coalesce(vfcr.weekly_due, 0), 2) as weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      vfcr.schedule_json,
      vfcr.adjustment_comment,
      vfcr.notes,
      vfcr.linked_timesheet_id,
      vfcr.linked_shift_date,
      vfcr.source_original_paid_amount,
      vfcr.source_corrected_paid_amount,
      vfcr.minimum_earnings_threshold,
      vfcr.take_home_floor_override,
      vfcr.written_off_at_utc,
      vfcr.write_off_reason,
      vfcr.cleared_at_utc,
      vfcr.active_reserved_amount,
      vfcr.reserved_amount,
      vfcr.committed_amount,
      vfcr.settled_amount,
      vfcr.released_amount,
      vfcr.active_reservation_count,
      vfcr.latest_recovery_pay_batch_id,
      vfcr.latest_recovery_pay_date,
      vfcr.latest_remittance_sent_at_utc,
      vfcr.latest_remittance_trigger_status,
      vfcr.last_remittance_error,
      vfcr.active_snooze_id,
      vfcr.active_snooze_kind,
      vfcr.active_snooze_until_date,
      vfcr.active_snooze_note,
      vfcr.active_snooze_created_at_utc,
      vfcr.active_snooze_updated_at_utc,
      case when vfcr.management_group is null then null else vfcr.management_group::text end as management_group,
      vfcr.lifecycle_status_display,
      case when vfcr.taxability is null then null else vfcr.taxability::text end as taxability,
      case when vfcr.routing_kind is null then null else vfcr.routing_kind::text end as routing_kind,
      coalesce(vfcr.oneoff_bank_details_required, false) as oneoff_bank_details_required,
      coalesce(vfcr.is_candidate_directed_oneoff_payout, false) as is_candidate_directed_oneoff_payout,
      coalesce(vfcr.appears_on_umbrella_remittance, false) as appears_on_umbrella_remittance,
      coalesce(vfcr.generates_candidate_payment_advice, false) as generates_candidate_payment_advice,
      coalesce(vfcr.oneoff_bank_details_present, false) as oneoff_bank_details_present,
      coalesce(vfcr.oneoff_bank_details_editable, false) as oneoff_bank_details_editable,
      coalesce(vfcr.snooze_allowed, false) as snooze_allowed,
      coalesce(vfcr.edit_bank_details_allowed, false) as edit_bank_details_allowed,
      vfcr.oneoff_bank_beneficiary_name,
      vfcr.oneoff_bank_sort_code,
      vfcr.oneoff_bank_account_number,
      vfcr.oneoff_bank_note,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then false
        else coalesce(vfcr.is_mixed_case, false)
      end as is_mixed_case,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_taxable_count, 0)
      end as open_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.open_reimbursement_count, 0)
      end as open_reimbursement_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.unresolved_taxable_count, 0)
      end as unresolved_taxable_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 0
        else coalesce(vfcr.stale_count, 0)
      end as stale_count,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then jsonb_build_object(
          'open_taxable_count', 0,
          'open_reimbursement_count', 0,
          'unresolved_taxable_count', 0,
          'stale_count', 0,
          'is_mixed_case', false
        )
        else coalesce(vfcr.component_resolution_summary_json, '{}'::jsonb)
      end as component_resolution_summary_json,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'Payment Advance'
        when vfcr.case_type = 'OVERPAYMENT' then 'Overpayment'
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then 'Manual Debt Adjustment'
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then 'Manual Credit Adjustment'
        when vfcr.case_type = 'UNDERPAYMENT' then 'Underpayment'
        else vfcr.case_type::text
      end as admin_label,
      case
        when vfcr.active_snooze_id is null then 'NOT_SNOOZED'
        when vfcr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
        else 'DATED_SNOOZE'
      end as snooze_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then 'READY'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'BLOCKED_STALE_TAXABLE_COMPONENTS'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'BLOCKED_UNRESOLVED_TAXABLE_COMPONENTS'
        else 'READY'
      end as blocked_state,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then null
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 and coalesce(vfcr.stale_count, 0) > 0 then 'One or more taxable components are stale and must be re-resolved before the case can proceed.'
        when coalesce(vfcr.unresolved_taxable_count, 0) > 0 then 'One or more taxable components are unresolved and must be resolved before the case can proceed.'
        else null
      end as blocked_reason,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_restructure,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'ACTIVE'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_pause,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and vfcr.status = 'PAUSED'
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_resume,
      case
        when vfcr.case_type in ('PAYMENT_ADVANCE', 'OVERPAYMENT', 'MANUAL_DEBT_ADJUSTMENT')
         and round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
         and vfcr.written_off_at_utc is null
        then true else false
      end as can_write_off,
      case
        when vfcr.case_type = 'PAYMENT_ADVANCE' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' then coalesce(vfcr.payout_status, 'PENDING') in ('PENDING', 'CANCELLED')
        when vfcr.case_type = 'MANUAL_DEBT_ADJUSTMENT' then true
        else false
      end as can_edit,
      case when vfcr.active_snooze_id is not null then true else false end as can_unsnooze
    from public.v_finance_cases_register vfcr
    where (p_candidate_id is null or vfcr.candidate_id = p_candidate_id)
      and (p_client_id is null or vfcr.client_id = p_client_id)
      and (
        v_hide_completed_non_current_items = false
        or (
          vfcr.written_off_at_utc is null
          and vfcr.cleared_at_utc is null
          and upper(coalesce(vfcr.status::text, '')) not in ('PAID_OFF', 'PAID', 'CLEARED', 'WRITTEN_OFF', 'CANCELLED', 'SETTLED')
          and (
            upper(coalesce(vfcr.status::text, '')) in ('NOT_PROCESSED_YET', 'DRAFTED_AWAITING_AUTHORISATION', 'ACTIVE', 'PAUSED')
            or round(coalesce(vfcr.outstanding_amount, 0), 2) > 0
            or vfcr.active_snooze_id is not null
          )
        )
      )
  ),
  finance_payload_rows as (
    select
      fr.candidate_display_name,
      fr.admin_label,
      fr.finance_case_id,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_case_id', fr.finance_case_id::text,
          'case_type', fr.case_type::text,
          'admin_label', fr.admin_label,
          'candidate_id', fr.candidate_id::text,
          'candidate_tms_ref', fr.candidate_tms_ref,
          'candidate_display_name', fr.candidate_display_name,
          'pay_method', fr.pay_method,
          'client_id', case when fr.client_id is null then null else fr.client_id::text end,
          'client_name', fr.client_name,
          'status', fr.status::text,
          'finance_status', fr.status::text,
          'payout_status', case when fr.payout_status is null then null else fr.payout_status::text end,
          'finance_payout_status', case when fr.payout_status is null then null else fr.payout_status::text end,
          'management_group', fr.management_group,
          'lifecycle_status_display', fr.lifecycle_status_display,
          'finance_lifecycle_status_display', fr.lifecycle_status_display,
          'taxability', fr.taxability,
          'routing_kind', fr.routing_kind,
          'oneoff_bank_details_required', fr.oneoff_bank_details_required,
          'oneoff_bank_details_present', fr.oneoff_bank_details_present,
          'oneoff_bank_details_editable', fr.oneoff_bank_details_editable,
          'edit_bank_details_allowed', fr.edit_bank_details_allowed,
          'snooze_allowed', fr.snooze_allowed,
          'is_candidate_directed_oneoff_payout', fr.is_candidate_directed_oneoff_payout,
          'appears_on_umbrella_remittance', fr.appears_on_umbrella_remittance,
          'generates_candidate_payment_advice', fr.generates_candidate_payment_advice,
          'blocked_state', fr.blocked_state,
          'blocked_reason', fr.blocked_reason
        )
        ||
        jsonb_build_object(
          'payout_pay_batch_id', case when fr.payout_pay_batch_id is null then null else fr.payout_pay_batch_id::text end,
          'payout_transfer_id', case when fr.payout_transfer_id is null then null else fr.payout_transfer_id::text end,
          'original_amount', fr.original_amount,
          'outstanding_amount', fr.outstanding_amount,
          'weekly_due', fr.weekly_due,
          'weeks_total', fr.weeks_total,
          'start_week_start', case when fr.start_week_start is null then null else fr.start_week_start::text end,
          'next_due_week_start', case when fr.next_due_week_start is null then null else fr.next_due_week_start::text end,
          'schedule_json', coalesce(fr.schedule_json, '[]'::jsonb),
          'adjustment_comment', fr.adjustment_comment,
          'notes', fr.notes,
          'linked_timesheet_id', case when fr.linked_timesheet_id is null then null else fr.linked_timesheet_id::text end,
          'linked_shift_date', case when fr.linked_shift_date is null then null else fr.linked_shift_date::text end,
          'active_snooze_id', case when fr.active_snooze_id is null then null else fr.active_snooze_id::text end,
          'active_snooze_kind', fr.active_snooze_kind,
          'active_snooze_mode', case
            when fr.active_snooze_id is null then 'NOT_SNOOZED'
            when fr.active_snooze_until_date is null then 'INDEFINITE'
            else 'DATED'
          end,
          'active_snooze_until_date', case when fr.active_snooze_until_date is null then null else fr.active_snooze_until_date::text end,
          'active_snooze_note', fr.active_snooze_note,
          'active_snooze_created_at_utc', case when fr.active_snooze_created_at_utc is null then null else fr.active_snooze_created_at_utc::text end,
          'active_snooze_updated_at_utc', case when fr.active_snooze_updated_at_utc is null then null else fr.active_snooze_updated_at_utc::text end,
          'active_snooze_visibility_status', case
            when fr.active_snooze_id is null then 'NOT_SNOOZED'
            when fr.active_snooze_until_date is null then 'INDEFINITE_SNOOZE'
            else 'DATED_SNOOZE'
          end
        )
        ||
        jsonb_build_object(
          'source_original_paid_amount', fr.source_original_paid_amount,
          'source_corrected_paid_amount', fr.source_corrected_paid_amount,
          'minimum_earnings_threshold', fr.minimum_earnings_threshold,
          'take_home_floor_override', fr.take_home_floor_override,
          'written_off_at_utc', case when fr.written_off_at_utc is null then null else fr.written_off_at_utc::text end,
          'write_off_reason', fr.write_off_reason,
          'cleared_at_utc', case when fr.cleared_at_utc is null then null else fr.cleared_at_utc::text end,
          'active_reserved_amount', coalesce(fr.active_reserved_amount, 0),
          'reserved_amount', coalesce(fr.reserved_amount, 0),
          'committed_amount', coalesce(fr.committed_amount, 0),
          'settled_amount', coalesce(fr.settled_amount, 0),
          'released_amount', coalesce(fr.released_amount, 0),
          'active_reservation_count', coalesce(fr.active_reservation_count, 0)
        )
        ||
        jsonb_build_object(
          'latest_recovery_pay_batch_id', case when fr.latest_recovery_pay_batch_id is null then null else fr.latest_recovery_pay_batch_id::text end,
          'latest_recovery_pay_date', case when fr.latest_recovery_pay_date is null then null else fr.latest_recovery_pay_date::text end,
          'latest_remittance_sent_at_utc', case when fr.latest_remittance_sent_at_utc is null then null else fr.latest_remittance_sent_at_utc::text end,
          'latest_remittance_trigger_status', fr.latest_remittance_trigger_status,
          'last_remittance_error', fr.last_remittance_error,
          'is_mixed_case', fr.is_mixed_case,
          'open_taxable_count', fr.open_taxable_count,
          'open_reimbursement_count', fr.open_reimbursement_count,
          'unresolved_taxable_count', fr.unresolved_taxable_count,
          'stale_count', fr.stale_count,
          'component_resolution_summary_json', fr.component_resolution_summary_json,
          'oneoff_bank_beneficiary_name', fr.oneoff_bank_beneficiary_name,
          'oneoff_bank_sort_code', fr.oneoff_bank_sort_code,
          'oneoff_bank_account_number', fr.oneoff_bank_account_number,
          'oneoff_bank_note', fr.oneoff_bank_note,
          'snooze', case
            when fr.active_snooze_id is null then null
            else jsonb_build_object(
              'snooze_id', fr.active_snooze_id::text,
              'snooze_kind', fr.active_snooze_kind,
              'snooze_until_date', case when fr.active_snooze_until_date is null then null else fr.active_snooze_until_date::text end,
              'snooze_note', fr.active_snooze_note,
              'snooze_created_at_utc', case when fr.active_snooze_created_at_utc is null then null else fr.active_snooze_created_at_utc::text end,
              'snooze_updated_at_utc', case when fr.active_snooze_updated_at_utc is null then null else fr.active_snooze_updated_at_utc::text end,
              'snooze_state', fr.snooze_state
            )
          end,
          'action_flags', jsonb_build_object(
            'can_restructure', fr.can_restructure,
            'can_pause', fr.can_pause,
            'can_resume', fr.can_resume,
            'can_write_off', fr.can_write_off,
            'can_edit', fr.can_edit,
            'can_snooze', (fr.snooze_allowed and fr.active_snooze_id is null),
            'can_unsnooze', fr.can_unsnooze,
            'can_clear_snooze', fr.can_unsnooze,
            'can_edit_snooze', fr.can_unsnooze,
            'can_edit_bank_details', fr.edit_bank_details_allowed
          )
        )
      ) as row_json
    from finance_rows fr
  ),
  finance_json as (
    select
      coalesce(
        jsonb_agg(
          fpr.row_json
          order by fpr.candidate_display_name asc, fpr.admin_label asc, fpr.finance_case_id asc
        ),
        '[]'::jsonb
      ) as payload
    from finance_payload_rows fpr
  ),
  pay_item_snooze_source as (
    select
      pis.id as snooze_id,
      pis.candidate_id,
      c.tms_ref as candidate_tms_ref,
      c.display_name as candidate_display_name,
      pis.timesheet_id as stored_timesheet_id,
      coalesce(pis.booking_id, ts_stored.booking_id) as booking_id,
      pis.segment_id as stored_segment_id,
      coalesce(nullif(btrim(coalesce(pis.segment_stable_key, '')), ''), nullif(btrim(coalesce(pis.segment_id, '')), '')) as segment_stable_key,
      upper(coalesce(pis.snooze_kind, '')) as snooze_kind,
      pis.snooze_until_date,
      pis.note,
      pis.created_at_utc,
      pis.updated_at_utc,
      pis.cleared_at_utc,
      pis.created_by_user_id,
      pis.updated_by_user_id
    from public.pay_item_snoozes pis
    join public.candidates c
      on c.id = pis.candidate_id
    left join public.timesheets ts_stored
      on ts_stored.timesheet_id = pis.timesheet_id
    where pis.source_ref is null
      and (p_candidate_id is null or pis.candidate_id = p_candidate_id)
      and (
        coalesce(pis.booking_id, ts_stored.booking_id) is not null
        or pis.timesheet_id is not null
      )
  ),
  current_timesheet_context as (
    select distinct
      pss.booking_id,
      ts_current.timesheet_id as current_timesheet_id,
      tf_current.client_id as client_id,
      cl_current.name as client_name,
      tf_current.role as role,
      tf_current.band as band,
      ts_current.week_ending_date as week_ending_date,
      ts_current.reference_number as reference_number,
      tf_current.invoice_breakdown_json as invoice_breakdown_json,
      round(coalesce(tf_current.total_pay_ex_vat, 0), 2) as total_pay_ex_vat
    from pay_item_snooze_source pss
    join public.timesheets ts_current
      on ts_current.booking_id = pss.booking_id
     and ts_current.is_current = true
    left join public.timesheets_financials tf_current
      on tf_current.timesheet_id = ts_current.timesheet_id
     and tf_current.is_current = true
    left join public.clients cl_current
      on cl_current.id = tf_current.client_id
  ),
  current_timesheet_segments_actual as (
    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), '') as segment_id,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'segment_stable_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_id', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'segment_key', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'date', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '')
      ) as segment_stable_key,
      nullif(btrim(coalesce(seg_item.value->>'date', '')), '') as work_date,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'client_name', '')), ''), ctc.client_name) as client_name,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'role', '')), ''), ctc.role) as role,
      coalesce(nullif(btrim(coalesce(seg_item.value->>'band', '')), ''), ctc.band) as band,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'start', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'start_hhmm', '')), '')
      ) as start_time,
      coalesce(
        nullif(btrim(coalesce(seg_item.value->>'end', '')), ''),
        nullif(btrim(coalesce(seg_item.value->>'end_hhmm', '')), '')
      ) as finish_time,
      nullif(btrim(coalesce(seg_item.value->>'break_start', '')), '') as break_start,
      nullif(btrim(coalesce(seg_item.value->>'break_end', '')), '') as break_end,
      coalesce(
        nullif(seg_item.value->>'break_mins', '')::numeric,
        nullif(seg_item.value->>'break_minutes', '')::numeric
      ) as break_mins,
      round(coalesce(nullif(seg_item.value->>'pay_amount', '')::numeric, 0), 2) as pay_amount_ex_vat,
      nullif(btrim(coalesce(seg_item.value->>'ref_num', '')), '') as ref_num
    from current_timesheet_context ctc
    join lateral jsonb_array_elements(
      case
        when ctc.invoice_breakdown_json is not null
         and jsonb_typeof(ctc.invoice_breakdown_json) = 'object'
         and jsonb_typeof(ctc.invoice_breakdown_json->'segments') = 'array'
        then ctc.invoice_breakdown_json->'segments'
        else '[]'::jsonb
      end
    ) as seg_item(value)
      on true
    where seg_item.value is not null
      and jsonb_typeof(seg_item.value) = 'object'
  ),
  current_timesheet_segments as (
    select
      ctsa.current_timesheet_id,
      ctsa.booking_id,
      ctsa.segment_id,
      ctsa.segment_stable_key,
      ctsa.work_date,
      ctsa.client_name,
      ctsa.role,
      ctsa.band,
      ctsa.start_time,
      ctsa.finish_time,
      ctsa.break_start,
      ctsa.break_end,
      ctsa.break_mins,
      ctsa.pay_amount_ex_vat,
      ctsa.ref_num
    from current_timesheet_segments_actual ctsa

    union all

    select
      ctc.current_timesheet_id,
      ctc.booking_id,
      null::text as segment_id,
      ('timesheet:' || coalesce(ctc.booking_id, ctc.current_timesheet_id::text)) as segment_stable_key,
      null::text as work_date,
      ctc.client_name,
      ctc.role,
      ctc.band,
      null::text as start_time,
      null::text as finish_time,
      null::text as break_start,
      null::text as break_end,
      null::numeric as break_mins,
      round(coalesce(ctc.total_pay_ex_vat, 0), 2) as pay_amount_ex_vat,
      ctc.reference_number as ref_num
    from current_timesheet_context ctc
    where not exists (
      select 1
      from current_timesheet_segments_actual ctsa
      where ctsa.current_timesheet_id = ctc.current_timesheet_id
    )
  ),
  current_timesheet_segment_groups as (
    select
      cts.current_timesheet_id,
      count(*)::int as segment_count,
      round(coalesce(sum(cts.pay_amount_ex_vat), 0), 2) as total_segment_pay_ex_vat,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'segment_id', cts.segment_id,
            'segment_stable_key', cts.segment_stable_key,
            'date', cts.work_date,
            'client_name', cts.client_name,
            'role', cts.role,
            'band', cts.band,
            'start', cts.start_time,
            'finish', cts.finish_time,
            'break_start', cts.break_start,
            'break_end', cts.break_end,
            'break_mins', cts.break_mins,
            'pay_amount_ex_vat', cts.pay_amount_ex_vat,
            'ref_num', cts.ref_num
          )
          order by cts.work_date asc nulls last, cts.start_time asc nulls last, cts.segment_stable_key asc
        ),
        '[]'::jsonb
      ) as segment_rows_json
    from current_timesheet_segments cts
    group by cts.current_timesheet_id
  ),
  timesheet_snooze_rows_raw as (
    select
      pss.snooze_id,
      pss.candidate_id,
      pss.candidate_tms_ref,
      pss.candidate_display_name,
      pss.stored_timesheet_id,
      pss.booking_id,
      pss.stored_segment_id,
      pss.segment_stable_key,
      pss.snooze_kind,
      pss.snooze_until_date,
      pss.note,
      pss.created_at_utc,
      pss.updated_at_utc,
      pss.cleared_at_utc,
      pss.created_by_user_id,
      pss.updated_by_user_id,
      case when pss.segment_stable_key is null then 'WHOLE_TIMESHEET' else 'SEGMENT' end as row_kind,
      ctc.current_timesheet_id,
      ctc.client_id as current_client_id,
      ctc.client_name as current_client_name,
      ctc.role as current_role,
      ctc.band as current_band,
      ctc.week_ending_date as current_week_ending_date,
      ctc.reference_number as current_reference_number,
      cts.segment_id as current_segment_id,
      cts.segment_stable_key as current_segment_stable_key,
      cts.work_date as current_segment_date,
      cts.client_name as current_segment_client_name,
      cts.role as current_segment_role,
      cts.band as current_segment_band,
      cts.start_time as current_segment_start,
      cts.finish_time as current_segment_finish,
      cts.break_start as current_segment_break_start,
      cts.break_end as current_segment_break_end,
      cts.break_mins as current_segment_break_mins,
      cts.pay_amount_ex_vat as current_segment_pay_amount_ex_vat,
      cts.ref_num as current_segment_ref_num,
      ctsg.segment_count,
      ctsg.total_segment_pay_ex_vat,
      ctsg.segment_rows_json
    from pay_item_snooze_source pss
    left join current_timesheet_context ctc
      on ctc.booking_id = pss.booking_id
    left join current_timesheet_segments cts
      on cts.current_timesheet_id = ctc.current_timesheet_id
     and pss.segment_stable_key is not null
     and (
       cts.segment_stable_key = pss.segment_stable_key
       or (
         pss.stored_segment_id is not null
         and cts.segment_id = pss.stored_segment_id
       )
     )
    left join current_timesheet_segment_groups ctsg
      on ctsg.current_timesheet_id = ctc.current_timesheet_id
  ),
  timesheet_snooze_rows_lifecycle as (
    select
      tsrr.*,
      case
        when tsrr.cleared_at_utc is not null then 'CLEARED'
        when tsrr.current_timesheet_id is null then 'CLEARED_DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'CLEARED_DELETED_SEGMENT'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        else 'ACTIVE'
      end as lifecycle_state,
      case
        when tsrr.cleared_at_utc is not null then tsrr.cleared_at_utc
        when tsrr.current_timesheet_id is null then tsrr.updated_at_utc
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then tsrr.updated_at_utc
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then tsrr.updated_at_utc
        else null::timestamptz
      end as effective_cleared_at_utc,
      case
        when tsrr.cleared_at_utc is not null then 'USER_CLEARED'
        when tsrr.current_timesheet_id is null then 'DELETED_TIMESHEET'
        when tsrr.row_kind = 'SEGMENT' and tsrr.current_segment_stable_key is null then 'DELETED_SEGMENT'
        when tsrr.snooze_until_date is not null and tsrr.snooze_until_date < v_today_uk then 'EXPIRED'
        else null::text
      end as clear_reason
    from timesheet_snooze_rows_raw tsrr
  ),
  timesheet_snooze_rows_filtered as (
    select
      tsrl.snooze_id,
      tsrl.candidate_id,
      tsrl.candidate_tms_ref,
      tsrl.candidate_display_name,
      case when tsrl.current_client_id is null then null else tsrl.current_client_id::text end as client_id_text,
      tsrl.current_client_name as client_name,
      coalesce(tsrl.current_timesheet_id, tsrl.stored_timesheet_id) as display_timesheet_id,
      tsrl.current_timesheet_id,
      tsrl.stored_timesheet_id,
      tsrl.booking_id,
      case when tsrl.row_kind = 'SEGMENT' then coalesce(tsrl.current_segment_id, tsrl.stored_segment_id) else null end as display_segment_id,
      tsrl.stored_segment_id,
      tsrl.segment_stable_key,
      tsrl.row_kind,
      tsrl.snooze_kind,
      tsrl.snooze_until_date,
      tsrl.note,
      tsrl.created_at_utc,
      tsrl.updated_at_utc,
      tsrl.effective_cleared_at_utc,
      tsrl.lifecycle_state,
      tsrl.clear_reason,
      case
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is null then 'INDEFINITE_SNOOZE'
        when tsrl.lifecycle_state = 'ACTIVE' and tsrl.snooze_until_date is not null then 'DATED_SNOOZE'
        when tsrl.lifecycle_state = 'EXPIRED' then 'EXPIRED'
        else 'CLEARED'
      end as snooze_state,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then tsrl.current_week_ending_date
        else null::date
      end as week_ending_date,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then tsrl.current_reference_number
        else tsrl.current_segment_ref_num
      end as reference_number,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then round(coalesce(tsrl.total_segment_pay_ex_vat, 0), 2)
        else round(coalesce(tsrl.current_segment_pay_amount_ex_vat, 0), 2)
      end as pay_amount_ex_vat,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_count, 0)
        when tsrl.current_segment_stable_key is not null then 1
        else 0
      end as segment_count,
      case
        when tsrl.row_kind = 'WHOLE_TIMESHEET' then coalesce(tsrl.segment_rows_json, '[]'::jsonb)
        when tsrl.current_segment_stable_key is not null then jsonb_build_array(
          jsonb_build_object(
            'segment_id', tsrl.current_segment_id,
            'segment_stable_key', tsrl.current_segment_stable_key,
            'date', tsrl.current_segment_date,
            'client_name', tsrl.current_segment_client_name,
            'role', tsrl.current_segment_role,
            'band', tsrl.current_segment_band,
            'start', tsrl.current_segment_start,
            'finish', tsrl.current_segment_finish,
            'break_start', tsrl.current_segment_break_start,
            'break_end', tsrl.current_segment_break_end,
            'break_mins', tsrl.current_segment_break_mins,
            'pay_amount_ex_vat', tsrl.current_segment_pay_amount_ex_vat,
            'ref_num', tsrl.current_segment_ref_num
          )
        )
        else '[]'::jsonb
      end as segment_rows_json
    from timesheet_snooze_rows_lifecycle tsrl
    where (p_client_id is null or tsrl.current_client_id = p_client_id)
      and (
        tsrl.lifecycle_state = 'ACTIVE'
        or (v_hide_completed_non_current_items = false and tsrl.lifecycle_state <> 'ACTIVE')
      )
  ),
  timesheet_snoozes_json as (
    select
      coalesce(
        jsonb_agg(
          jsonb_strip_nulls(
            jsonb_build_object(
              'snooze_id', tsf.snooze_id::text,
              'row_kind', tsf.row_kind,
              'lifecycle_state', tsf.lifecycle_state,
              'clear_reason', tsf.clear_reason,
              'candidate_id', tsf.candidate_id::text,
              'candidate_tms_ref', tsf.candidate_tms_ref,
              'candidate_display_name', tsf.candidate_display_name,
              'client_id', tsf.client_id_text,
              'client_name', tsf.client_name,
              'timesheet_id', case when tsf.display_timesheet_id is null then null else tsf.display_timesheet_id::text end,
              'current_timesheet_id', case when tsf.current_timesheet_id is null then null else tsf.current_timesheet_id::text end,
              'original_timesheet_id', case when tsf.stored_timesheet_id is null then null else tsf.stored_timesheet_id::text end,
              'booking_id', tsf.booking_id,
              'segment_id', tsf.display_segment_id,
              'original_segment_id', tsf.stored_segment_id,
              'segment_stable_key', tsf.segment_stable_key,
              'week_ending_date', case when tsf.week_ending_date is null then null else tsf.week_ending_date::text end,
              'reference_number', tsf.reference_number,
              'snooze_kind', tsf.snooze_kind,
              'snooze_until_date', case when tsf.snooze_until_date is null then null else tsf.snooze_until_date::text end,
              'note', tsf.note,
              'created_at_utc', case when tsf.created_at_utc is null then null else tsf.created_at_utc::text end,
              'updated_at_utc', case when tsf.updated_at_utc is null then null else tsf.updated_at_utc::text end,
              'cleared_at_utc', case when tsf.effective_cleared_at_utc is null then null else tsf.effective_cleared_at_utc::text end,
              'snooze_state', tsf.snooze_state,
              'pay_amount_ex_vat', tsf.pay_amount_ex_vat,
              'segment_count', tsf.segment_count,
              'segment_rows', tsf.segment_rows_json,
              'action_flags', jsonb_build_object(
                'can_unsnooze', (tsf.lifecycle_state = 'ACTIVE'),
                'can_change_to_indefinite', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null),
                'can_change_to_dated', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is null),
                'can_amend_date', (tsf.lifecycle_state = 'ACTIVE' and tsf.snooze_until_date is not null)
              )
            )
          )
          order by tsf.candidate_display_name asc, tsf.row_kind asc, tsf.week_ending_date asc nulls last, tsf.display_timesheet_id asc nulls last, tsf.segment_stable_key asc nulls last, tsf.snooze_id asc
        ),
        '[]'::jsonb
      ) as payload
    from timesheet_snooze_rows_filtered tsf
  ),
  summary_data as (
    select
      jsonb_build_object(
        'payment_advances_active_count', count(*) filter (where fr.case_type = 'PAYMENT_ADVANCE' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'overpayments_active_count', count(*) filter (where fr.case_type = 'OVERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'underpayments_active_count', count(*) filter (where fr.case_type = 'UNDERPAYMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_debt_adjustments_active_count', count(*) filter (where fr.case_type = 'MANUAL_DEBT_ADJUSTMENT' and fr.status in ('ACTIVE', 'PAUSED') and fr.outstanding_amount > 0),
        'manual_credit_adjustments_count', count(*) filter (where fr.case_type = 'MANUAL_CREDIT_ADJUSTMENT'),
        'mixed_finance_cases_count', count(*) filter (where fr.is_mixed_case),
        'unresolved_finance_cases_count', count(*) filter (where fr.unresolved_taxable_count > 0),
        'stale_finance_cases_count', count(*) filter (where fr.stale_count > 0),
        'finance_cases_with_active_snooze_count', count(*) filter (where fr.active_snooze_id is not null),
        'timesheet_snoozes_count', (select count(*) from timesheet_snooze_rows_filtered)
      ) as payload
    from finance_rows fr
  )
  select
    coalesce((select fj.payload from finance_json fj), '[]'::jsonb),
    coalesce((select tsj.payload from timesheet_snoozes_json tsj), '[]'::jsonb),
    coalesce((select sd.payload from summary_data sd), '{}'::jsonb)
  into v_finance_cases, v_timesheet_snoozes, v_summary;

  return jsonb_build_object(
    'ok', true,
    'filters', jsonb_build_object(
      'candidate_id', case when p_candidate_id is null then null else p_candidate_id::text end,
      'client_id', case when p_client_id is null then null else p_client_id::text end,
      'hide_completed_non_current_items', v_hide_completed_non_current_items
    ),
    'summary', v_summary,
    'finance_cases', v_finance_cases,
    'timesheet_snoozes', v_timesheet_snoozes
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.pay_finance_payout_notice_build(
  p_pay_batch_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_batch_id uuid := p_pay_batch_id;
  v_batch record;
  v_jobs jsonb := '[]'::jsonb;
begin
  if v_batch_id is null then
    raise exception 'pay_finance_payout_notice_build: pay_batch_id is required';
  end if;

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.authoritative_payment_date,
    pb.pay_date,
    pb.bulk_reference,
    pb.rail_provider_snapshot,
    pb.rail_env_snapshot
  into v_batch
  from public.pay_batches pb
  where pb.id = v_batch_id;

  if v_batch.id is null then
    raise exception 'pay_finance_payout_notice_build: pay batch % not found.', v_batch_id;
  end if;

  with payout_items as (
    select
      pbc.id as pay_batch_candidate_id,
      pbc.candidate_id,
      c.display_name,
      c.first_name,
      c.last_name,
      c.email,
      pbi.id as pay_batch_item_id,
      pbi.item_type,
      pbi.description,
      pbi.amount_ex_vat,
      pbi.amount_vat,
      pbi.amount_inc_vat,
      pbi.finance_case_id,
      pa.case_type,
      pa.adjustment_comment,
      pa.schedule_json,
      pa.weekly_due,
      pa.weeks_total,
      pa.start_week_start,
      pa.next_due_week_start,
      pa.outstanding_amount,
      pa.notes
    from public.pay_batch_candidates pbc
    join public.candidates c
      on c.id = pbc.candidate_id
    join public.pay_batch_items pbi
      on pbi.pay_batch_candidate_id = pbc.id
    left join public.pay_advances pa
      on pa.id = pbi.finance_case_id
    where pbc.pay_batch_id = v_batch_id
      and coalesce(pbi.is_voided, false) = false
      and pbi.item_type in ('LOAN_PAYOUT','MANUAL_CREDIT_PAYOUT')
  ),
  items_grouped as (
    select
      pi.candidate_id,
      max(pi.display_name) as display_name,
      max(pi.first_name) as first_name,
      max(pi.last_name) as last_name,
      max(pi.email) as email,
      jsonb_agg(
        jsonb_build_object(
          'pay_batch_item_id', pi.pay_batch_item_id::text,
          'finance_case_id', case when pi.finance_case_id is null then null else pi.finance_case_id::text end,
          'case_type', case
            when pi.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum then 'PAYMENT_ADVANCE'
            when pi.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then 'MANUAL_CREDIT_ADJUSTMENT'
            else null
          end,
          'label', case
            when pi.item_type = 'LOAN_PAYOUT' then 'Payment Advance'
            when pi.item_type = 'MANUAL_CREDIT_PAYOUT' then 'Manual Credit Adjustment'
            else coalesce(nullif(btrim(pi.description), ''), 'Payment')
          end,
          'amount', round(coalesce(pi.amount_inc_vat, pi.amount_ex_vat, 0), 2),
          'amount_ex_vat', round(coalesce(pi.amount_ex_vat, 0), 2),
          'scheduled_payment_date', coalesce(v_batch.authoritative_payment_date, v_batch.pay_date),
          'repayment_arrangement', case
            when pi.item_type = 'LOAN_PAYOUT' then jsonb_build_object(
              'weekly_due', pi.weekly_due,
              'weeks_total', pi.weeks_total,
              'start_week_start', case when pi.start_week_start is null then null else pi.start_week_start::text end,
              'next_due_week_start', case when pi.next_due_week_start is null then null else pi.next_due_week_start::text end,
              'schedule_json', coalesce(pi.schedule_json, '[]'::jsonb),
              'remaining_outstanding_amount', pi.outstanding_amount
            )
            else null
          end,
          'adjustment_comment', case
            when pi.item_type = 'MANUAL_CREDIT_PAYOUT' then nullif(btrim(coalesce(pi.adjustment_comment, '')), '')
            else null
          end,
          'notes', nullif(btrim(coalesce(pi.notes, '')), '')
        )
        order by pi.pay_batch_item_id
      ) as items_json,
      round(sum(round(coalesce(pi.amount_inc_vat, pi.amount_ex_vat, 0), 2)), 2) as total_amount
    from payout_items pi
    group by pi.candidate_id
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'candidate_id', ig.candidate_id::text,
        'recipient_name', coalesce(nullif(btrim(ig.display_name), ''), nullif(btrim(trim(coalesce(ig.first_name, '') || ' ' || coalesce(ig.last_name, ''))), ''), 'Worker'),
        'recipient_email', ig.email,
        'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
        'subject', case
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Payment Advance' then 'Payment Advance scheduled'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Manual Credit Adjustment' then 'Manual Credit Adjustment scheduled'
          else 'Payment scheduled'
        end,
        'worker_message', case
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Payment Advance' then 'A Payment Advance has been scheduled.'
          when jsonb_array_length(ig.items_json) = 1 and (ig.items_json->0->>'label') = 'Manual Credit Adjustment' then 'A Manual Credit Adjustment has been scheduled.'
          else 'A payment has been scheduled.'
        end,
        'total_amount', ig.total_amount,
        'items', ig.items_json,
        'batch', jsonb_build_object(
          'pay_batch_id', v_batch.id::text,
          'status', v_batch.status,
          'batch_kind_fixed', v_batch.batch_kind_fixed,
          'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
          'bulk_reference', v_batch.bulk_reference,
          'rail_provider_snapshot', v_batch.rail_provider_snapshot,
          'rail_env_snapshot', v_batch.rail_env_snapshot
        )
      )
      order by ig.candidate_id
    ),
    '[]'::jsonb
  )
  into v_jobs
  from items_grouped ig
  where nullif(btrim(coalesce(ig.email, '')), '') is not null;

  return jsonb_build_object(
    'ok', true,
    'pay_batch_id', v_batch.id::text,
    'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'jobs', coalesce(v_jobs, '[]'::jsonb)
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.timesheet_payment_override_set(
  p_timesheet_id uuid,
  p_actor_user_id uuid,
  p_reason text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_timesheet_id uuid := p_timesheet_id;
  v_actor_user_id uuid := p_actor_user_id;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_now timestamptz := now();
  v_candidate_id uuid := null;
  v_existing record;
  v_batch_status text := null;
  v_inserted record;
  v_pay_state jsonb := '{}'::jsonb;
begin
  if v_timesheet_id is null then
    raise exception 'timesheet_payment_override_set: timesheet_id is required';
  end if;

  if v_actor_user_id is null then
    raise exception 'timesheet_payment_override_set: actor_user_id is required';
  end if;

  if v_reason is null then
    raise exception 'timesheet_payment_override_set: reason is required';
  end if;

  perform 1
  from public.timesheets ts
  where ts.timesheet_id = v_timesheet_id
    and ts.is_current = true;

  if not found then
    raise exception 'timesheet_payment_override_set: current timesheet % not found.', v_timesheet_id;
  end if;

  select tf.candidate_id
  into v_candidate_id
  from public.timesheets_financials tf
  where tf.timesheet_id = v_timesheet_id
    and tf.is_current = true
  limit 1;

  if v_candidate_id is null then
    raise exception 'timesheet_payment_override_set: candidate_id not found for timesheet %.', v_timesheet_id;
  end if;

  select
    tpo.id,
    tpo.timesheet_id,
    tpo.candidate_id,
    tpo.override_type,
    tpo.reason,
    tpo.created_at_utc,
    tpo.created_by_user_id,
    tpo.consumed_by_pay_batch_id,
    tpo.consumed_at_utc,
    tpo.cleared_at_utc,
    tpo.cleared_by_user_id,
    tpo.clear_reason
  into v_existing
  from public.timesheet_payment_overrides tpo
  where tpo.timesheet_id = v_timesheet_id
    and tpo.cleared_at_utc is null
  order by tpo.created_at_utc desc, tpo.id desc
  limit 1;

  if v_existing.id is not null then
    if v_existing.consumed_by_pay_batch_id is not null then
      select upper(coalesce(pb.status, ''))
      into v_batch_status
      from public.pay_batches pb
      where pb.id = v_existing.consumed_by_pay_batch_id
      limit 1;

      if coalesce(v_batch_status, '') <> 'CANCELLED' then
        raise exception 'timesheet_payment_override_set: override already consumed by non-cancelled pay batch %.', v_existing.consumed_by_pay_batch_id;
      end if;

      update public.timesheet_payment_overrides tpo_old
      set
        cleared_at_utc = v_now,
        cleared_by_user_id = v_actor_user_id,
        clear_reason = coalesce(tpo_old.clear_reason, 'REPLACED_AFTER_CANCELLED_BATCH')
      where tpo_old.id = v_existing.id;
    else
      v_pay_state := public.timesheet_pay_state(
        p_timesheet_id => v_timesheet_id,
        p_actor_user_id => v_actor_user_id
      );

      return jsonb_build_object(
        'ok', true,
        'timesheet_id', v_timesheet_id::text,
        'candidate_id', v_candidate_id::text,
        'already_exists', true,
        'override', jsonb_build_object(
          'id', v_existing.id::text,
          'override_type', v_existing.override_type,
          'reason', v_existing.reason,
          'created_at_utc', v_existing.created_at_utc,
          'created_by_user_id', case when v_existing.created_by_user_id is null then null else v_existing.created_by_user_id::text end,
          'consumed_by_pay_batch_id', case when v_existing.consumed_by_pay_batch_id is null then null else v_existing.consumed_by_pay_batch_id::text end,
          'consumed_at_utc', v_existing.consumed_at_utc
        ),
        'pay_state', v_pay_state
      );
    end if;
  end if;

  insert into public.timesheet_payment_overrides(
    timesheet_id,
    candidate_id,
    override_type,
    reason,
    created_at_utc,
    created_by_user_id
  )
  values (
    v_timesheet_id,
    v_candidate_id,
    'ADVANCE_THIS_PAYMENT',
    v_reason,
    v_now,
    v_actor_user_id
  )
  returning * into v_inserted;

  v_pay_state := public.timesheet_pay_state(
    p_timesheet_id => v_timesheet_id,
    p_actor_user_id => v_actor_user_id
  );

  perform public._audit_insert(
    'timesheets',
    v_timesheet_id::text,
    'TIMESHEET_PAYMENT_OVERRIDE_SET',
    null,
    jsonb_build_object(
      'override_id', v_inserted.id::text,
      'timesheet_id', v_timesheet_id::text,
      'candidate_id', v_candidate_id::text,
      'override_type', 'ADVANCE_THIS_PAYMENT',
      'reason', v_reason
    ),
    'ADVANCE_THIS_PAYMENT',
    v_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'timesheet_id', v_timesheet_id::text,
    'candidate_id', v_candidate_id::text,
    'already_exists', false,
    'override', jsonb_build_object(
      'id', v_inserted.id::text,
      'override_type', v_inserted.override_type,
      'reason', v_inserted.reason,
      'created_at_utc', v_inserted.created_at_utc,
      'created_by_user_id', case when v_inserted.created_by_user_id is null then null else v_inserted.created_by_user_id::text end,
      'consumed_by_pay_batch_id', case when v_inserted.consumed_by_pay_batch_id is null then null else v_inserted.consumed_by_pay_batch_id::text end,
      'consumed_at_utc', v_inserted.consumed_at_utc
    ),
    'pay_state', v_pay_state
  );
end;
$function$;


CREATE OR REPLACE FUNCTION public.timesheet_payment_override_clear(
  p_timesheet_id uuid,
  p_actor_user_id uuid,
  p_clear_reason text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_timesheet_id uuid := p_timesheet_id;
  v_actor_user_id uuid := p_actor_user_id;
  v_clear_reason text := nullif(btrim(coalesce(p_clear_reason, '')), '');
  v_now timestamptz := now();
  v_existing record;
  v_batch_status text := null;
  v_pay_state jsonb := '{}'::jsonb;
  v_candidate_id uuid := null;
begin
  if v_timesheet_id is null then
    raise exception 'timesheet_payment_override_clear: timesheet_id is required';
  end if;

  if v_actor_user_id is null then
    raise exception 'timesheet_payment_override_clear: actor_user_id is required';
  end if;

  select tf.candidate_id
  into v_candidate_id
  from public.timesheets_financials tf
  where tf.timesheet_id = v_timesheet_id
    and tf.is_current = true
  limit 1;

  select
    tpo.id,
    tpo.timesheet_id,
    tpo.candidate_id,
    tpo.override_type,
    tpo.reason,
    tpo.created_at_utc,
    tpo.created_by_user_id,
    tpo.consumed_by_pay_batch_id,
    tpo.consumed_at_utc,
    tpo.cleared_at_utc,
    tpo.cleared_by_user_id,
    tpo.clear_reason
  into v_existing
  from public.timesheet_payment_overrides tpo
  where tpo.timesheet_id = v_timesheet_id
    and tpo.cleared_at_utc is null
  order by tpo.created_at_utc desc, tpo.id desc
  limit 1;

  if v_existing.id is null then
    v_pay_state := public.timesheet_pay_state(
      p_timesheet_id => v_timesheet_id,
      p_actor_user_id => v_actor_user_id
    );

    return jsonb_build_object(
      'ok', true,
      'timesheet_id', v_timesheet_id::text,
      'candidate_id', case when v_candidate_id is null then null else v_candidate_id::text end,
      'already_cleared', true,
      'pay_state', v_pay_state
    );
  end if;

  if v_existing.consumed_by_pay_batch_id is not null then
    select upper(coalesce(pb.status, ''))
    into v_batch_status
    from public.pay_batches pb
    where pb.id = v_existing.consumed_by_pay_batch_id
    limit 1;

    if coalesce(v_batch_status, '') <> 'CANCELLED' then
      raise exception 'timesheet_payment_override_clear: override already consumed by non-cancelled pay batch %.', v_existing.consumed_by_pay_batch_id;
    end if;
  end if;

  update public.timesheet_payment_overrides tpo
  set
    cleared_at_utc = v_now,
    cleared_by_user_id = v_actor_user_id,
    clear_reason = coalesce(v_clear_reason, 'CLEARED')
  where tpo.id = v_existing.id;

  v_pay_state := public.timesheet_pay_state(
    p_timesheet_id => v_timesheet_id,
    p_actor_user_id => v_actor_user_id
  );

  perform public._audit_insert(
    'timesheets',
    v_timesheet_id::text,
    'TIMESHEET_PAYMENT_OVERRIDE_CLEARED',
    jsonb_build_object(
      'override_id', v_existing.id::text,
      'timesheet_id', v_timesheet_id::text,
      'candidate_id', case when coalesce(v_existing.candidate_id, v_candidate_id) is null then null else coalesce(v_existing.candidate_id, v_candidate_id)::text end,
      'override_type', v_existing.override_type,
      'reason', v_existing.reason,
      'consumed_by_pay_batch_id', case when v_existing.consumed_by_pay_batch_id is null then null else v_existing.consumed_by_pay_batch_id::text end,
      'consumed_at_utc', v_existing.consumed_at_utc
    ),
    jsonb_build_object(
      'override_id', v_existing.id::text,
      'timesheet_id', v_timesheet_id::text,
      'clear_reason', coalesce(v_clear_reason, 'CLEARED')
    ),
    coalesce(v_clear_reason, 'CLEARED'),
    v_actor_user_id
  );

  return jsonb_build_object(
    'ok', true,
    'timesheet_id', v_timesheet_id::text,
    'candidate_id', case when coalesce(v_existing.candidate_id, v_candidate_id) is null then null else coalesce(v_existing.candidate_id, v_candidate_id)::text end,
    'already_cleared', false,
    'cleared_override_id', v_existing.id::text,
    'pay_state', v_pay_state
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.pay_finance_case_audit_feed(
  p_finance_case_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_finance_case_id uuid := p_finance_case_id;
  v_case record;
  v_timeline jsonb := '[]'::jsonb;
  v_current_component_state jsonb := '[]'::jsonb;
begin
  if v_finance_case_id is null then
    raise exception 'pay_finance_case_audit_feed: finance_case_id is required';
  end if;

  select
    vfcr.finance_case_id,
    vfcr.case_type,
    vfcr.candidate_id,
    vfcr.candidate_tms_ref,
    vfcr.candidate_display_name,
    vfcr.client_id,
    vfcr.client_name,
    vfcr.linked_timesheet_id,
    vfcr.linked_shift_date,
    vfcr.status,
    vfcr.payout_status,
    vfcr.original_amount,
    vfcr.outstanding_amount,
    vfcr.weekly_due,
    vfcr.weeks_total,
    vfcr.start_week_start,
    vfcr.next_due_week_start,
    vfcr.adjustment_comment,
    vfcr.source_original_paid_amount,
    vfcr.source_corrected_paid_amount,
    vfcr.minimum_earnings_threshold,
    vfcr.take_home_floor_override,
    vfcr.active_snooze_id,
    vfcr.active_snooze_kind,
    vfcr.active_snooze_until_date,
    vfcr.active_snooze_note,
    vfcr.latest_remittance_sent_at_utc,
    vfcr.latest_remittance_trigger_status,
    vfcr.last_remittance_error,
    vfcr.latest_recovery_pay_batch_id,
    vfcr.latest_recovery_pay_date,
    vfcr.payout_pay_batch_id,
    vfcr.payout_transfer_id,
    vfcr.written_off_at_utc,
    vfcr.write_off_reason,
    vfcr.cleared_at_utc,
    vfcr.baseline_signature,
    vfcr.schedule_json,
    vfcr.notes,
    vfcr.created_at,
    vfcr.updated_at,
    vfcr.is_mixed_case,
    vfcr.open_taxable_count,
    vfcr.open_reimbursement_count,
    vfcr.unresolved_taxable_count,
    vfcr.stale_count,
    vfcr.component_resolution_summary_json
  into v_case
  from public.v_finance_cases_register vfcr
  where vfcr.finance_case_id = v_finance_case_id;

  if v_case.finance_case_id is null then
    raise exception 'pay_finance_case_audit_feed: finance case % not found.', v_finance_case_id;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'finance_component_id', pfc.id::text,
          'candidate_id', pfc.candidate_id::text,
          'client_id', case when pfc.client_id is null then null else pfc.client_id::text end,
          'linked_timesheet_id', case when pfc.linked_timesheet_id is null then null else pfc.linked_timesheet_id::text end,
          'source_family_key', pfc.source_family_key,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_basis_json', pfc.source_basis_json,
          'source_amount', pfc.source_amount,
          'remaining_source_amount', pfc.remaining_source_amount,
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
          'saved_resolution_result_json', pfc.saved_resolution_result_json,
          'resolution_fingerprint', pfc.resolution_fingerprint,
          'is_resolution_stale', pfc.is_resolution_stale,
          'stale_reason', pfc.stale_reason,
          'allocation_priority_group', pfc.allocation_priority_group,
          'allocation_priority_order', pfc.allocation_priority_order,
          'created_at_utc', pfc.created_at_utc,
          'updated_at_utc', pfc.updated_at_utc,
          'resolved_at_utc', pfc.resolved_at_utc,
          'closed_at_utc', pfc.closed_at_utc
        )
        order by
          pfc.source_family_key,
          pfc.allocation_priority_group,
          pfc.allocation_priority_order,
          pfc.component_key_type,
          pfc.component_key_value
      ),
      '[]'::jsonb
    )
  into v_current_component_state
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = v_finance_case_id
    and pfc.closed_at_utc is null;

  with booking_ctx as (
    select ts.booking_id
    from public.timesheets ts
    where ts.timesheet_id = v_case.linked_timesheet_id
    limit 1
  ),
  finance_events as (
    select
      pfce.event_at_utc as at_utc,
      'FINANCE_CASE_EVENT'::text as source,
      pfce.event_type as event_type,
      initcap(replace(lower(coalesce(pfce.event_type, 'EVENT')), '_', ' ')) as title,
      pfce.before_json,
      pfce.after_json,
      pfce.reason,
      pfce.note,
      case when pfce.pay_batch_id is null then null else pfce.pay_batch_id::text end as pay_batch_id_text,
      case when pfce.reservation_id is null then null else pfce.reservation_id::text end as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_strip_nulls(
        jsonb_build_object(
          'finance_component_id', case when pfce.finance_component_id is null then null else pfce.finance_component_id::text end,
          'classification', case when pfc.classification is null then null else pfc.classification::text end,
          'source_pay_method', pfc.source_pay_method,
          'target_pay_method', pfc.saved_target_pay_method,
          'resolution_mode', case when pfc.saved_resolution_mode is null then null else pfc.saved_resolution_mode::text end,
          'resolution_payload_json', pfc.saved_resolution_payload_json,
          'resolution_result_json', pfc.saved_resolution_result_json,
          'stale_reason', pfc.stale_reason,
          'remaining_source_amount', pfc.remaining_source_amount,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'frozen_source_basis_json', par.frozen_source_basis_json,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'frozen_resolution_payload_json', par.frozen_resolution_payload_json,
          'frozen_resolution_result_json', par.frozen_resolution_result_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        )
      ) as meta_json
    from public.pay_finance_case_events pfce
    left join public.pay_finance_case_components pfc
      on pfc.id = pfce.finance_component_id
    left join public.pay_advance_reservations par
      on par.id = pfce.reservation_id
    where pfce.finance_case_id = v_finance_case_id
  ),
  reservation_events as (
    select
      x.at_utc,
      'RESERVATION'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      x.pay_batch_id_text,
      x.reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        par.created_at_utc as at_utc,
        'RESERVED'::text as event_type,
        'Finance reservation created'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'repayment_week_start', case when par.repayment_week_start is null then null else par.repayment_week_start::text end,
          'status', par.status,
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_classification', case when par.frozen_component_classification is null then null else par.frozen_component_classification::text end,
          'frozen_source_basis_json', par.frozen_source_basis_json,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'frozen_resolution_payload_json', par.frozen_resolution_payload_json,
          'frozen_resolution_result_json', par.frozen_resolution_result_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', par.status,
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_classification', case when par.frozen_component_classification is null then null else par.frozen_component_classification::text end,
          'frozen_source_pay_method', par.frozen_source_pay_method,
          'frozen_target_pay_method', par.frozen_target_pay_method,
          'frozen_resolution_mode', case when par.frozen_resolution_mode is null then null else par.frozen_resolution_mode::text end,
          'reserved_source_amount', par.reserved_source_amount
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.created_at_utc is not null

      union all

      select
        par.committed_at_utc as at_utc,
        'COMMITTED'::text as event_type,
        'Finance reservation committed'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'COMMITTED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'COMMITTED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.committed_at_utc is not null

      union all

      select
        par.settled_at_utc as at_utc,
        'SETTLED'::text as event_type,
        'Finance reservation settled'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'SETTLED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        null::text as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'SETTLED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.settled_at_utc is not null

      union all

      select
        par.released_at_utc as at_utc,
        'RELEASED'::text as event_type,
        'Finance reservation released'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'reserved_amount', par.reserved_amount,
          'status', 'RELEASED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end,
          'released_reason', par.released_reason,
          'frozen_component_snapshot_json', par.frozen_component_snapshot_json,
          'reserved_source_amount', par.reserved_source_amount,
          'frozen_rounded_target_amount', par.frozen_rounded_target_amount
        ) as after_json,
        par.released_reason as reason,
        null::text as note,
        par.pay_batch_id::text as pay_batch_id_text,
        par.id::text as reservation_id_text,
        jsonb_build_object(
          'reservation_status', 'RELEASED',
          'finance_component_id', case when par.finance_component_id is null then null else par.finance_component_id::text end
        ) as meta_json
      from public.pay_advance_reservations par
      where par.finance_case_id = v_finance_case_id
        and par.released_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  batch_item_events as (
    select
      pbi.created_at as at_utc,
      'BATCH_ITEM'::text as source,
      coalesce(pbi.item_type, 'BATCH_ITEM_CREATED')::text as event_type,
      'Finance batch item created'::text as title,
      null::jsonb as before_json,
      jsonb_build_object(
        'item_type', pbi.item_type,
        'finance_case_id', case when pbi.finance_case_id is null then null else pbi.finance_case_id::text end,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'frozen_component_classification', case when pbi.frozen_component_classification is null then null else pbi.frozen_component_classification::text end,
        'frozen_source_basis_json', pbi.frozen_source_basis_json,
        'frozen_source_pay_method', pbi.frozen_source_pay_method,
        'frozen_target_pay_method', pbi.frozen_target_pay_method,
        'frozen_resolution_mode', case when pbi.frozen_resolution_mode is null then null else pbi.frozen_resolution_mode::text end,
        'frozen_resolution_payload_json', pbi.frozen_resolution_payload_json,
        'frozen_resolution_result_json', pbi.frozen_resolution_result_json,
        'frozen_source_amount', pbi.frozen_source_amount,
        'frozen_target_amount_ex_vat', pbi.frozen_target_amount_ex_vat,
        'frozen_target_amount_vat', pbi.frozen_target_amount_vat,
        'frozen_target_amount_inc_vat', pbi.frozen_target_amount_inc_vat,
        'frozen_component_snapshot_json', pbi.frozen_component_snapshot_json,
        'is_voided', pbi.is_voided
      ) as after_json,
      null::text as reason,
      null::text as note,
      pbc.pay_batch_id::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'pay_batch_candidate_id', pbi.pay_batch_candidate_id::text,
        'finance_component_id', case when pbi.finance_component_id is null then null else pbi.finance_component_id::text end,
        'is_voided', pbi.is_voided
      ) as meta_json
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    where pbi.created_at is not null
      and (
        pbi.finance_case_id = v_finance_case_id
        or (
          pbi.source_ref is not null
          and pbi.source_ref = ('advance:' || v_finance_case_id::text)
        )
      )
  ),
  patch_events as (
    select
      pap.patched_at_utc as at_utc,
      'PATCH'::text as source,
      'PATCHED'::text as event_type,
      'Finance case patched'::text as title,
      jsonb_build_object(
        'outstanding_amount', pap.old_outstanding_amount,
        'schedule_json', pap.old_schedule_json,
        'next_due_week_start', case when pap.old_next_due_week_start is null then null else pap.old_next_due_week_start::text end
      ) as before_json,
      jsonb_build_object(
        'outstanding_amount', pap.new_outstanding_amount,
        'schedule_json', pap.new_schedule_json,
        'next_due_week_start', case when pap.new_next_due_week_start is null then null else pap.new_next_due_week_start::text end
      ) as after_json,
      null::text as reason,
      null::text as note,
      case when pap.pay_batch_id is null then null else pap.pay_batch_id::text end as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      null::jsonb as meta_json
    from public.pay_advance_patches pap
    where pap.advance_id = v_finance_case_id
  ),
  snooze_events as (
    select
      x.at_utc,
      'SNOOZE'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      case when x.timesheet_id is null then null else x.timesheet_id::text end as timesheet_id_text,
      x.meta_json
    from (
      select
        pis.created_at_utc as at_utc,
        'SNOOZE_APPLIED'::text as event_type,
        'Snooze applied'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'snooze_kind', pis.snooze_kind,
          'snooze_until_date', case when pis.snooze_until_date is null then null else pis.snooze_until_date::text end,
          'note', pis.note,
          'source_ref', pis.source_ref
        ) as after_json,
        null::text as reason,
        pis.note as note,
        pis.timesheet_id,
        jsonb_build_object('snooze_id', pis.id::text) as meta_json
      from public.pay_item_snoozes pis
      where pis.source_ref = ('advance:' || v_finance_case_id::text)
        and pis.created_at_utc is not null

      union all

      select
        pis.cleared_at_utc as at_utc,
        'SNOOZE_CLEARED'::text as event_type,
        'Snooze cleared'::text as title,
        jsonb_build_object(
          'snooze_kind', pis.snooze_kind,
          'snooze_until_date', case when pis.snooze_until_date is null then null else pis.snooze_until_date::text end,
          'note', pis.note,
          'source_ref', pis.source_ref
        ) as before_json,
        null::jsonb as after_json,
        null::text as reason,
        pis.note as note,
        pis.timesheet_id,
        jsonb_build_object('snooze_id', pis.id::text) as meta_json
      from public.pay_item_snoozes pis
      where pis.source_ref = ('advance:' || v_finance_case_id::text)
        and pis.cleared_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  generic_audit_events as (
    select
      ae.ts_utc as at_utc,
      'AUDIT'::text as source,
      ae.action as event_type,
      initcap(replace(lower(coalesce(ae.action, 'EVENT')), '_', ' ')) as title,
      ae.before_json,
      ae.after_json,
      ae.reason,
      null::text as note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'object_type', ae.object_type,
        'object_id_text', ae.object_id_text,
        'actor_user_id', case when ae.actor_user_id is null then null else ae.actor_user_id::text end,
        'actor_display', ae.actor_display,
        'actor_role_at_time', ae.actor_role_at_time,
        'correlation_id', ae.correlation_id
      ) as meta_json
    from public.audit_events ae
    where (
      ae.object_type in ('pay_advances','finance_cases')
      and ae.object_id_text = v_finance_case_id::text
    )
    or (
      v_case.linked_timesheet_id is not null
      and ae.object_type = 'timesheets'
      and ae.object_id_text = v_case.linked_timesheet_id::text
    )
  ),
  batch_refs as (
    select distinct par.pay_batch_id
    from public.pay_advance_reservations par
    where par.finance_case_id = v_finance_case_id
      and par.pay_batch_id is not null
    union
    select distinct pap.pay_batch_id
    from public.pay_advance_patches pap
    where pap.advance_id = v_finance_case_id
      and pap.pay_batch_id is not null
    union
    select v_case.payout_pay_batch_id
    where v_case.payout_pay_batch_id is not null
    union
    select v_case.latest_recovery_pay_batch_id
    where v_case.latest_recovery_pay_batch_id is not null
  ),
  batch_override_events as (
    select
      x.at_utc,
      'PAYE_OVERRIDE'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      x.pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        pb.created_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_REQUESTED'::text as event_type,
        'Same-week PAYE override requested'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_req.display_name, '')), ''), nullif(btrim(coalesce(tu_req.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        'Derived from pay batch creation because no separate requested-at field is stored on pay_batches.'::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_req.display_name, '')), ''), nullif(btrim(coalesce(tu_req.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_req
        on tu_req.id = pb.same_week_paye_override_verified_by_user_id
      where coalesce(pb.same_week_paye_override_used, false) = true

      union all

      select
        pb.same_week_paye_override_verified_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_VERIFIED'::text as event_type,
        'Same-week PAYE override verified'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_ver.display_name, '')), ''), nullif(btrim(coalesce(tu_ver.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        null::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_ver.display_name, '')), ''), nullif(btrim(coalesce(tu_ver.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_ver
        on tu_ver.id = pb.same_week_paye_override_verified_by_user_id
      where pb.same_week_paye_override_verified_at_utc is not null

      union all

      select
        pb.created_at_utc as at_utc,
        'SAME_WEEK_PAYE_OVERRIDE_USED'::text as event_type,
        'Same-week PAYE override used'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_reason', pb.same_week_paye_override_reason,
          'same_week_paye_override_verified_at_utc', case when pb.same_week_paye_override_verified_at_utc is null then null else pb.same_week_paye_override_verified_at_utc::text end,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_used.display_name, '')), ''), nullif(btrim(coalesce(tu_used.email, '')), '')),
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'status', pb.status
        ) as after_json,
        pb.same_week_paye_override_reason as reason,
        null::text as note,
        pb.id::text as pay_batch_id_text,
        jsonb_build_object(
          'same_week_paye_override_used', pb.same_week_paye_override_used,
          'same_week_paye_override_verified_by_user_id', case when pb.same_week_paye_override_verified_by_user_id is null then null else pb.same_week_paye_override_verified_by_user_id::text end,
          'same_week_paye_override_verified_by_display', coalesce(nullif(btrim(coalesce(tu_used.display_name, '')), ''), nullif(btrim(coalesce(tu_used.email, '')), ''))
        ) as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      left join public.tms_users tu_used
        on tu_used.id = pb.same_week_paye_override_verified_by_user_id
      where coalesce(pb.same_week_paye_override_used, false) = true
    ) x
    where x.at_utc is not null
  ),
  batch_candidate_communication_events as (
    select
      pbc.remittance_sent_at_utc as at_utc,
      'COMMUNICATION'::text as source,
      case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'PAYOUT_NOTICE_SENT' else 'REMITTANCE_SENT' end as event_type,
      case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'Worker payout notice sent' else 'Worker remittance sent' end as title,
      null::jsonb as before_json,
      jsonb_build_object(
        'message_kind', case when upper(coalesce(pb.batch_kind_fixed, '')) = 'LOANS' then 'PAYOUT_NOTICE' else 'REMITTANCE' end,
        'candidate_id', case when pbc.candidate_id is null then null else pbc.candidate_id::text end,
        'candidate_display_name', pbc.candidate_display_name,
        'remittance_sent_at_utc', case when pbc.remittance_sent_at_utc is null then null else pbc.remittance_sent_at_utc::text end,
        'trigger_status', pbc.remittance_trigger_status,
        'last_remittance_error', pbc.last_remittance_error,
        'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
        'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end
      ) as after_json,
      null::text as reason,
      pbc.last_remittance_error as note,
      pbc.pay_batch_id::text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'pay_batch_candidate_id', pbc.id::text,
        'candidate_id', case when pbc.candidate_id is null then null else pbc.candidate_id::text end,
        'trigger_status', pbc.remittance_trigger_status
      ) as meta_json
    from batch_refs br
    join public.pay_batch_candidates pbc
      on pbc.pay_batch_id = br.pay_batch_id
     and pbc.candidate_id = v_case.candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbc.remittance_sent_at_utc is not null
  ),
  batch_audit_events as (
    select
      ae.ts_utc as at_utc,
      case
        when ae.action in (
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR',
          'PAY_REMITTANCE_SENT'
        ) then 'COMMUNICATION'::text
        when upper(coalesce(ae.action, '')) like '%SAME_WEEK%'
         and upper(coalesce(ae.action, '')) like '%OVERRIDE%' then 'PAYE_OVERRIDE'::text
        else 'BATCH_AUDIT'::text
      end as source,
      ae.action as event_type,
      case
        when ae.action = 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' then 'Commit-stage worker payout notice triggered' else 'Commit-stage worker remittance triggered' end
        when ae.action = 'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Commit-stage worker payout notice error' else 'Commit-stage worker remittance error' end
        when ae.action = 'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Settlement catch-up payout notice triggered' else 'Settlement catch-up remittance triggered' end
        when ae.action = 'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' or upper(coalesce(ae.after_json->>'trigger_status', '')) like 'PAYOUT_NOTICE%' then 'Settlement catch-up payout notice error' else 'Settlement catch-up remittance error' end
        when ae.action = 'PAY_REMITTANCE_SENT' then
          case when upper(coalesce(ae.after_json->>'message_kind', '')) = 'PAYOUT_NOTICE' then 'Worker payout notice send results recorded' else 'Worker remittance send results recorded' end
        else initcap(replace(lower(coalesce(ae.action, 'EVENT')), '_', ' '))
      end as title,
      ae.before_json,
      ae.after_json,
      ae.reason,
      null::text as note,
      ae.object_id_text as pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      jsonb_build_object(
        'object_type', ae.object_type,
        'object_id_text', ae.object_id_text,
        'actor_user_id', case when ae.actor_user_id is null then null else ae.actor_user_id::text end,
        'actor_display', ae.actor_display,
        'actor_role_at_time', ae.actor_role_at_time,
        'correlation_id', ae.correlation_id
      ) as meta_json
    from public.audit_events ae
    join batch_refs br
      on ae.object_id_text = br.pay_batch_id::text
    where ae.object_type in ('pay_batch', 'pay_batches')
      and (
        ae.action in (
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_COMMIT_STAGE_COMMUNICATION_ERROR',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_TRIGGERED',
          'PAY_BATCH_SETTLEMENT_CATCHUP_COMMUNICATION_ERROR',
          'PAY_REMITTANCE_SENT'
        )
        or (
          upper(coalesce(ae.action, '')) like '%SAME_WEEK%'
          and upper(coalesce(ae.action, '')) like '%OVERRIDE%'
        )
      )
  ),
  batch_events as (
    select
      x.at_utc,
      'BATCH'::text as source,
      x.event_type,
      x.title,
      null::jsonb as before_json,
      x.after_json,
      x.reason,
      null::text as note,
      x.pay_batch_id_text,
      null::text as reservation_id_text,
      null::text as timesheet_id_text,
      x.meta_json
    from (
      select
        pb.created_at_utc as at_utc,
        'BATCH_CREATED'::text as event_type,
        'Pay batch created'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'batch_kind_fixed', pb.batch_kind_fixed,
          'bulk_reference', pb.bulk_reference
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.created_at_utc is not null

      union all

      select
        pb.scheduled_at_utc as at_utc,
        'BATCH_SCHEDULED'::text as event_type,
        'Pay batch scheduled'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'pay_date', case when pb.pay_date is null then null else pb.pay_date::text end,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end,
          'schedule_kind', pb.schedule_kind
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.scheduled_at_utc is not null

      union all

      select
        pb.completed_at_utc as at_utc,
        'BATCH_SETTLED'::text as event_type,
        'Pay batch settled'::text as title,
        jsonb_build_object(
          'status', pb.status,
          'completed_at_utc', pb.completed_at_utc,
          'authoritative_payment_date', case when pb.authoritative_payment_date is null then null else pb.authoritative_payment_date::text end
        ) as after_json,
        null::text as reason,
        pb.id::text as pay_batch_id_text,
        null::jsonb as meta_json
      from batch_refs br
      join public.pay_batches pb
        on pb.id = br.pay_batch_id
      where pb.completed_at_utc is not null

      union all

      select
        pbar.created_at_utc as at_utc,
        'AUTH_REQUEST_CREATED'::text as event_type,
        'Authorisation requested'::text as title,
        jsonb_build_object(
          'state', pbar.state,
          'required_quantity', pbar.required_quantity,
          'schedule_kind', pbar.schedule_kind,
          'scheduled_at_utc', pbar.scheduled_at_utc
        ) as after_json,
        null::text as reason,
        pbar.pay_batch_id::text as pay_batch_id_text,
        jsonb_build_object('auth_request_id', pbar.id::text) as meta_json
      from batch_refs br
      join public.pay_batch_auth_requests pbar
        on pbar.pay_batch_id = br.pay_batch_id
      where pbar.created_at_utc is not null

      union all

      select
        pbaa.action_at_utc as at_utc,
        'AUTH_ACTION'::text as event_type,
        'Authorisation action'::text as title,
        jsonb_build_object('action', pbaa.action, 'note', pbaa.note) as after_json,
        null::text as reason,
        pbaa.pay_batch_id::text as pay_batch_id_text,
        jsonb_build_object('auth_request_id', pbaa.auth_request_id::text, 'auth_action_id', pbaa.id::text) as meta_json
      from batch_refs br
      join public.pay_batch_auth_actions pbaa
        on pbaa.pay_batch_id = br.pay_batch_id
      where pbaa.action_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  timesheet_events as (
    select
      x.at_utc,
      'TIMESHEET'::text as source,
      x.event_type,
      x.title,
      x.before_json,
      x.after_json,
      x.reason,
      x.note,
      null::text as pay_batch_id_text,
      null::text as reservation_id_text,
      x.timesheet_id_text,
      x.meta_json
    from (
      select
        ts.created_at as at_utc,
        'TIMESHEET_VERSION'::text as event_type,
        'Timesheet version captured'::text as title,
        null::jsonb as before_json,
        jsonb_build_object(
          'timesheet_id', ts.timesheet_id::text,
          'version', ts.version,
          'is_current', ts.is_current,
          'status', ts.status,
          'reference_number', ts.reference_number,
          'actual_schedule_json', ts.actual_schedule_json
        ) as after_json,
        null::text as reason,
        null::text as note,
        ts.timesheet_id::text as timesheet_id_text,
        jsonb_build_object('booking_id', ts.booking_id, 'version', ts.version) as meta_json
      from booking_ctx bc
      join public.timesheets ts
        on ts.booking_id = bc.booking_id
      where ts.created_at is not null

      union all

      select
        pbts.created_at_utc as at_utc,
        'FROZEN_SNAPSHOT'::text as event_type,
        'Pay batch timesheet snapshot captured'::text as title,
        jsonb_build_object('base_snapshot_json', pbts.base_snapshot_json) as before_json,
        jsonb_build_object('target_snapshot_json', pbts.target_snapshot_json, 'signature', pbts.signature) as after_json,
        null::text as reason,
        null::text as note,
        pbts.timesheet_id::text as timesheet_id_text,
        jsonb_build_object('pay_batch_id', pbts.pay_batch_id::text, 'pay_channel', pbts.pay_channel) as meta_json
      from public.pay_batch_timesheet_snapshots pbts
      where pbts.timesheet_id = v_case.linked_timesheet_id
        and pbts.created_at_utc is not null
    ) x
    where x.at_utc is not null
  ),
  all_events as (
    select * from finance_events
    union all select * from reservation_events
    union all select * from batch_item_events
    union all select * from patch_events
    union all select * from snooze_events
    union all select * from generic_audit_events
    union all select * from batch_override_events
    union all select * from batch_candidate_communication_events
    union all select * from batch_audit_events
    union all select * from batch_events
    union all select * from timesheet_events
  )
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'at_utc', ae.at_utc,
        'source', ae.source,
        'event_type', ae.event_type,
        'title', ae.title,
        'before_json', ae.before_json,
        'after_json', ae.after_json,
        'reason', ae.reason,
        'note', ae.note,
        'pay_batch_id', ae.pay_batch_id_text,
        'reservation_id', ae.reservation_id_text,
        'timesheet_id', ae.timesheet_id_text,
        'meta', ae.meta_json
      )
      order by ae.at_utc asc, ae.source asc, ae.event_type asc
    ),
    '[]'::jsonb
  )
  into v_timeline
  from all_events ae;

  return jsonb_build_object(
    'ok', true,
    'finance_case', jsonb_build_object(
      'finance_case_id', v_case.finance_case_id::text,
      'case_type', v_case.case_type,
      'candidate_id', case when v_case.candidate_id is null then null else v_case.candidate_id::text end,
      'candidate_tms_ref', v_case.candidate_tms_ref,
      'candidate_display_name', v_case.candidate_display_name,
      'client_id', case when v_case.client_id is null then null else v_case.client_id::text end,
      'client_name', v_case.client_name,
      'linked_timesheet_id', case when v_case.linked_timesheet_id is null then null else v_case.linked_timesheet_id::text end,
      'linked_shift_date', case when v_case.linked_shift_date is null then null else v_case.linked_shift_date::text end,
      'status', v_case.status,
      'payout_status', v_case.payout_status,
      'original_amount', v_case.original_amount,
      'outstanding_amount', v_case.outstanding_amount,
      'weekly_due', v_case.weekly_due,
      'weeks_total', v_case.weeks_total,
      'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'adjustment_comment', v_case.adjustment_comment,
      'source_original_paid_amount', v_case.source_original_paid_amount,
      'source_corrected_paid_amount', v_case.source_corrected_paid_amount,
      'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
      'take_home_floor_override', v_case.take_home_floor_override,
      'latest_remittance_sent_at_utc', v_case.latest_remittance_sent_at_utc,
      'latest_remittance_trigger_status', v_case.latest_remittance_trigger_status,
      'last_remittance_error', v_case.last_remittance_error,
      'latest_recovery_pay_batch_id', case when v_case.latest_recovery_pay_batch_id is null then null else v_case.latest_recovery_pay_batch_id::text end,
      'latest_recovery_pay_date', case when v_case.latest_recovery_pay_date is null then null else v_case.latest_recovery_pay_date::text end,
      'payout_pay_batch_id', case when v_case.payout_pay_batch_id is null then null else v_case.payout_pay_batch_id::text end,
      'payout_transfer_id', case when v_case.payout_transfer_id is null then null else v_case.payout_transfer_id::text end,
      'active_snooze_id', case when v_case.active_snooze_id is null then null else v_case.active_snooze_id::text end,
      'active_snooze_kind', v_case.active_snooze_kind,
      'active_snooze_until_date', case when v_case.active_snooze_until_date is null then null else v_case.active_snooze_until_date::text end,
      'active_snooze_note', v_case.active_snooze_note,
      'written_off_at_utc', v_case.written_off_at_utc,
      'write_off_reason', v_case.write_off_reason,
      'cleared_at_utc', v_case.cleared_at_utc,
      'baseline_signature', v_case.baseline_signature,
      'schedule_json', v_case.schedule_json,
      'notes', v_case.notes,
      'created_at', v_case.created_at,
      'updated_at', v_case.updated_at,
      'is_mixed_case', v_case.is_mixed_case,
      'open_taxable_count', v_case.open_taxable_count,
      'open_reimbursement_count', v_case.open_reimbursement_count,
      'unresolved_taxable_count', v_case.unresolved_taxable_count,
      'stale_count', v_case.stale_count,
      'component_resolution_summary_json', v_case.component_resolution_summary_json
    ),
    'current_component_state', coalesce(v_current_component_state, '[]'::jsonb),
    'timeline', coalesce(v_timeline, '[]'::jsonb)
  );
end;
$function$;

DROP FUNCTION IF EXISTS public.pay_remittance_queue_commit_stage(uuid, text, uuid);




DROP FUNCTION IF EXISTS public.pay_remittance_queue_commit_stage(uuid, text, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_remittance_queue_commit_stage(uuid, text, uuid, boolean, uuid, jsonb);




CREATE OR REPLACE FUNCTION public.pay_remittance_queue_commit_stage(
  p_pay_batch_id uuid,
  p_scope text,
  p_actor_user_id uuid,
  p_only_confirmed boolean DEFAULT false,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_remittance_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_scope text := upper(btrim(coalesce(p_scope, 'ALL')));
  v_batch record;
  v_build_result jsonb := '{}'::jsonb;
  v_build_jobs jsonb := '[]'::jsonb;
  v_filtered_jobs jsonb := '[]'::jsonb;
  v_candidate_results jsonb := '[]'::jsonb;
  v_job_results jsonb := '[]'::jsonb;

  v_job jsonb;
  v_work_job jsonb;
  v_job_kind text;
  v_recipient_kind text;
  v_recipient_email text;
  v_candidate_id_text text;
  v_candidate_id uuid;
  v_umbrella_id_text text;
  v_umbrella_id uuid;

  v_pruned_candidates jsonb := '[]'::jsonb;
  v_candidate_json jsonb;
  v_candidate_work_json jsonb;
  v_pruned_non_timesheet_lines jsonb := '[]'::jsonb;
  v_pruned_transfers jsonb := '[]'::jsonb;
  v_pruned_timesheets jsonb := '[]'::jsonb;
  v_candidate_excluded_transfer_total numeric := 0;
  v_job_excluded_transfer_total numeric := 0;
  v_original_job_total numeric := 0;
  v_pruned_total_amount numeric := 0;
  v_final_paid_amount numeric := 0;

  v_target_candidate_count integer := 0;
  v_ready_candidate_count integer := 0;
  v_job_count integer := 0;
  v_trigger_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;
  v_only_confirmed boolean := coalesce(p_only_confirmed, false);

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_already_queued_count integer := 0;
  v_inserted_outbox_count integer := 0;
  v_reused_outbox_count integer := 0;
  v_skipped_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_count integer := 0;
  v_has_more boolean := false;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_operation_job_results jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_remittance_queue_commit_stage: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_remittance_queue_commit_stage: actor_user_id is required';
  end if;

  if v_scope not in ('ALL', 'PAYE', 'UMBRELLA') then
    raise exception 'pay_remittance_queue_commit_stage: invalid scope "%". Expected ALL|PAYE|UMBRELLA.', v_scope;
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false)
    ),
    'pay_remittance',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.bulk_reference,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception 'pay_remittance_queue_commit_stage: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  if v_batch.settlement_confirmation_json is not null and jsonb_typeof(v_batch.settlement_confirmation_json) = 'object' then
    v_settlement_confirmation_json := v_batch.settlement_confirmation_json;
  else
    v_settlement_confirmation_json := '{}'::jsonb;
  end if;

  v_suppress_remittances := lower(btrim(coalesce(
    v_settlement_confirmation_json->>'suppress_remittances',
    v_execution_intent_json->>'suppress_remittances',
    'false'
  ))) in ('true','1','yes','y','on');

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode requires p_operation_id';
    END IF;
    IF p_remittance_scope_ids IS NULL OR jsonb_typeof(p_remittance_scope_ids) <> 'array' OR jsonb_array_length(p_remittance_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode requires non-empty p_remittance_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % is not remittance-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage: operation % belongs to a different actor', p_operation_id;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode received invalid or duplicate remittance scope ids';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'QUEUED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'FAILED')::integer,
           COALESCE(jsonb_agg(to_jsonb(selected_scope.id::text) ORDER BY selected_scope.id::text), '[]'::jsonb)
    INTO v_matched_scope_count,
         v_already_queued_count,
         v_skipped_count,
         v_failed_count,
         v_operation_scope_ids
    FROM selected_scope;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'pay_remittance_queue_commit_stage operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    IF v_suppress_remittances = true THEN
      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), skipped_scope AS (
        UPDATE public.banking_pay_operation_remittance_scope AS scope_update
        SET status = 'SKIPPED',
            payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
              'skip_reason', 'SUPPRESSED_BY_EXECUTION_INTENT',
              'skipped_at_utc', now()::text
            )),
            updated_at_utc = now()
        FROM requested_scope
        WHERE scope_update.id = requested_scope.remittance_scope_id
          AND scope_update.operation_id = p_operation_id
          AND scope_update.pay_batch_id = p_pay_batch_id
          AND scope_update.status IN ('PENDING', 'FAILED')
        RETURNING scope_update.id
      ), selected_scope_after AS (
        SELECT scope_row.status
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      )
      SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'QUEUED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
      INTO v_already_queued_count,
           v_skipped_count,
           v_failed_count
      FROM selected_scope_after;

      SELECT COUNT(*)::integer
      INTO v_remaining_count
      FROM public.banking_pay_operation_remittance_scope AS remaining_scope
      WHERE remaining_scope.operation_id = p_operation_id
        AND remaining_scope.pay_batch_id = p_pay_batch_id
        AND remaining_scope.status = 'PENDING';

      v_has_more := COALESCE(v_remaining_count, 0) > 0;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;

      RETURN jsonb_build_object(
        'ok', true,
        'operation_mode', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'trigger', coalesce(v_operation_row.input_json->>'trigger', CASE WHEN v_only_confirmed THEN 'ON_PAYMENT_CONFIRMED' ELSE 'ON_EXECUTION' END),
        'configured_timing', v_operation_row.input_json->>'configured_timing',
        'only_confirmed', v_only_confirmed,
        'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
        'message_kind', 'REMITTANCE',
        'queued_count', 0,
        'reused_count', COALESCE(v_already_queued_count, 0),
        'skipped_count', COALESCE(v_skipped_count, 0),
        'failed_count', COALESCE(v_failed_count, 0),
        'remaining', COALESCE(v_remaining_count, 0),
        'has_more', v_has_more,
        'dispatch_required', false
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_remittance_targets;
    CREATE TEMPORARY TABLE pg_temp.tmp_operation_remittance_targets AS
    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT
      scope_row.id AS remittance_scope_id,
      scope_row.status,
      scope_row.pay_batch_candidate_id,
      scope_row.candidate_id,
      scope_row.recipient_kind,
      scope_row.recipient_id,
      scope_row.remittance_type,
      scope_row.deterministic_outbox_key,
      scope_row.payload_json,
      scope_row.outbox_id,
      CASE
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.email
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.remittance_email
        ELSE NULL::text
      END AS recipient_email,
      CASE
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE' THEN candidate_row.display_name
        WHEN upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA' THEN umbrella_row.name
        ELSE NULL::text
      END AS recipient_name
    FROM public.banking_pay_operation_remittance_scope AS scope_row
    JOIN requested_scope
      ON requested_scope.remittance_scope_id = scope_row.id
    LEFT JOIN public.candidates AS candidate_row
      ON upper(coalesce(scope_row.recipient_kind, '')) = 'CANDIDATE'
     AND candidate_row.id = scope_row.recipient_id
    LEFT JOIN public.umbrellas AS umbrella_row
      ON upper(coalesce(scope_row.recipient_kind, '')) = 'UMBRELLA'
     AND umbrella_row.id = scope_row.recipient_id
    WHERE scope_row.operation_id = p_operation_id
      AND scope_row.pay_batch_id = p_pay_batch_id;

    WITH skipped_missing_recipient AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'SKIPPED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'skip_reason', 'MISSING_REMITTANCE_RECIPIENT_EMAIL',
            'skipped_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM pg_temp.tmp_operation_remittance_targets AS target_row
      WHERE scope_update.id = target_row.remittance_scope_id
        AND scope_update.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL
      RETURNING scope_update.id
    )
    SELECT COALESCE(v_skipped_count, 0) + COUNT(*)::integer
    INTO v_skipped_count
    FROM skipped_missing_recipient;

    WITH valid_targets AS (
      SELECT target_row.*
      FROM pg_temp.tmp_operation_remittance_targets AS target_row
      WHERE target_row.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NOT NULL
    ), upserted_outbox AS (
      INSERT INTO public.mail_outbox AS mail_insert (
        type,
        "to",
        cc,
        subject,
        body_html,
        body_text,
        attachments,
        status,
        created_at_utc,
        created_by,
        reference,
        recipient_kind,
        recipient_id,
        context_kind,
        context_id,
        email_type,
        importance,
        scheduled_for_utc,
        next_attempt_at_utc,
        payment_scope_json,
        deterministic_outbox_key
      )
      SELECT
        'REMITTANCE',
        valid_targets.recipient_email,
        NULL::text,
        CASE WHEN upper(coalesce(valid_targets.remittance_type, '')) = 'UMBRELLA_REMITTANCE'
             THEN 'Umbrella remittance - ' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text)
             ELSE 'Payment remittance - ' || COALESCE(NULLIF(BTRIM(COALESCE(v_batch.bulk_reference, '')), ''), p_pay_batch_id::text)
        END,
        '<p>Please find the payment remittance information for this payment batch.</p>',
        'Please find the payment remittance information for this payment batch.',
        '[]'::jsonb,
        'QUEUED'::public.mail_status_enum,
        now(),
        p_actor_user_id,
        valid_targets.deterministic_outbox_key,
        lower(coalesce(valid_targets.recipient_kind, '')),
        valid_targets.recipient_id,
        'pay_batch',
        p_pay_batch_id,
        'html',
        'Normal',
        now(),
        now(),
        jsonb_strip_nulls(COALESCE(valid_targets.payload_json, '{}'::jsonb) || jsonb_build_object(
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'remittance_scope_id', valid_targets.remittance_scope_id::text,
          'deterministic_outbox_key', valid_targets.deterministic_outbox_key,
          'remittance_type', valid_targets.remittance_type,
          'recipient_kind', valid_targets.recipient_kind,
          'recipient_id', CASE WHEN valid_targets.recipient_id IS NULL THEN NULL ELSE valid_targets.recipient_id::text END
        )),
        valid_targets.deterministic_outbox_key
      FROM valid_targets
      ON CONFLICT (deterministic_outbox_key)
      DO UPDATE
      SET status = CASE WHEN mail_insert.status::text = 'FAILED' THEN 'QUEUED'::public.mail_status_enum ELSE mail_insert.status END,
          last_error = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.last_error END,
          failed_at = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.failed_at END,
          next_attempt_at_utc = CASE WHEN mail_insert.status::text = 'FAILED' THEN now() ELSE mail_insert.next_attempt_at_utc END,
          payment_scope_json = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.payment_scope_json ELSE EXCLUDED.payment_scope_json END
      RETURNING mail_insert.id,
                mail_insert.deterministic_outbox_key,
                (xmax = 0) AS was_inserted
    ), updated_scope AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'QUEUED',
          outbox_id = upserted_outbox.id,
          updated_at_utc = now()
      FROM upserted_outbox
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.deterministic_outbox_key = upserted_outbox.deterministic_outbox_key
        AND scope_update.status IN ('PENDING', 'FAILED')
      RETURNING scope_update.id,
                scope_update.deterministic_outbox_key,
                scope_update.outbox_id,
                upserted_outbox.was_inserted
    )
    SELECT COUNT(*) FILTER (WHERE updated_scope.was_inserted)::integer,
           COUNT(*) FILTER (WHERE updated_scope.was_inserted IS NOT TRUE)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'remittance_scope_id', updated_scope.id::text,
             'deterministic_outbox_key', updated_scope.deterministic_outbox_key,
             'outbox_id', updated_scope.outbox_id::text,
             'queued', true,
             'reused', (updated_scope.was_inserted IS NOT TRUE)
           ) ORDER BY updated_scope.id::text), '[]'::jsonb)
    INTO v_inserted_outbox_count,
         v_reused_outbox_count,
         v_operation_job_results
    FROM updated_scope;

    SELECT COUNT(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_remittance_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    SELECT COUNT(*)::integer
    INTO v_failed_count
    FROM public.banking_pay_operation_remittance_scope AS failed_scope
    WHERE failed_scope.operation_id = p_operation_id
      AND failed_scope.pay_batch_id = p_pay_batch_id
      AND failed_scope.id IN (
        SELECT (scope_element.value #>> '{}')::uuid
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
      AND failed_scope.status = 'FAILED';

    v_has_more := COALESCE(v_remaining_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = now()
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'trigger', coalesce(v_operation_row.input_json->>'trigger', CASE WHEN v_only_confirmed THEN 'ON_PAYMENT_CONFIRMED' ELSE 'ON_EXECUTION' END),
      'configured_timing', v_operation_row.input_json->>'configured_timing',
      'only_confirmed', v_only_confirmed,
      'trigger_status', CASE WHEN COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0 THEN 'REMITTANCE_QUEUE_CHUNK_PROCESSED' ELSE 'NO_QUEUEABLE_REMITTANCE_SCOPE' END,
      'message_kind', 'REMITTANCE',
      'queued_count', COALESCE(v_inserted_outbox_count, 0),
      'reused_count', COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0),
      'skipped_count', COALESCE(v_skipped_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'remaining', COALESCE(v_remaining_count, 0),
      'has_more', v_has_more,
      'dispatch_required', (COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0)
    );
  END IF;

  SELECT COUNT(*)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND legacy_candidate_count.remittance_sent_at_utc IS NULL;

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_OPERATION_REQUIRED',
      'code', 'REMITTANCE_OPERATION_REQUIRED',
      'message', 'pay_remittance_queue_commit_stage legacy mode is limited to small batches; use the scalable remittance operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  if v_suppress_remittances = true then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
      'error', null,
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  drop table if exists pg_temp.tmp_commit_stage_excluded_finance_cases;
  create temporary table pg_temp.tmp_commit_stage_excluded_finance_cases(
    candidate_id uuid not null,
    finance_case_id uuid not null,
    primary key (candidate_id, finance_case_id)
  ) on commit drop;

  drop table if exists pg_temp.tmp_commit_stage_excluded_transfers;
  create temporary table pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id uuid primary key,
    candidate_id uuid not null,
    umbrella_id uuid null
  ) on commit drop;

  insert into pg_temp.tmp_commit_stage_excluded_finance_cases(
    candidate_id,
    finance_case_id
  )
  select distinct
    pbc.candidate_id,
    pbi.finance_case_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.remittance_sent_at_utc is null
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_excluded_finance_case_correction
      where ppc_excluded_finance_case_correction.pay_batch_item_id = pbi.id
        and ppc_excluded_finance_case_correction.status = 'APPLIED'
        and ppc_excluded_finance_case_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.finance_case_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on');

  insert into pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id,
    candidate_id,
    umbrella_id
  )
  select distinct
    pbi.pay_bank_transfer_id,
    pbc.candidate_id,
    pbi.umbrella_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  where pbc.pay_batch_id = p_pay_batch_id
    and pbc.remittance_sent_at_utc is null
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_excluded_transfer_correction
      where ppc_excluded_transfer_correction.pay_batch_item_id = pbi.id
        and ppc_excluded_transfer_correction.status = 'APPLIED'
        and ppc_excluded_transfer_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.pay_bank_transfer_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on');

  drop table if exists pg_temp.tmp_commit_stage_target_candidates;
  create temporary table pg_temp.tmp_commit_stage_target_candidates(
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    candidate_display_name text null,
    candidate_tms_ref text null
  ) on commit drop;

  drop table if exists pg_temp.tmp_commit_stage_confirmed_items;
  create temporary table pg_temp.tmp_commit_stage_confirmed_items(
    pay_batch_item_id uuid primary key,
    pay_batch_candidate_id uuid not null,
    candidate_id uuid not null,
    pay_bank_transfer_id uuid null,
    umbrella_id uuid null,
    pay_channel text not null,
    item_type text not null,
    timesheet_id uuid null,
    finance_case_id uuid null,
    manual_adjustment_carry_forward_id uuid null,
    amount_inc_vat numeric null,
    transfer_group_key text null
  ) on commit drop;

  insert into pg_temp.tmp_commit_stage_confirmed_items(
    pay_batch_item_id,
    pay_batch_candidate_id,
    candidate_id,
    pay_bank_transfer_id,
    umbrella_id,
    pay_channel,
    item_type,
    timesheet_id,
    finance_case_id,
    manual_adjustment_carry_forward_id,
    amount_inc_vat,
    transfer_group_key
  )
  select distinct
    pbi.id,
    pbc.id,
    pbc.candidate_id,
    pbi.pay_bank_transfer_id,
    pbi.umbrella_id,
    upper(coalesce(pbi.pay_channel, '')),
    pbi.item_type,
    pbi.timesheet_id,
    pbi.finance_case_id,
    CASE
      WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN split_part(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), ':', 2)::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN split_part(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), ':', 2)::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '')::uuid
      WHEN NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
        THEN NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '')::uuid
      ELSE NULL::uuid
    END AS manual_adjustment_carry_forward_id,
    pbi.amount_inc_vat,
    pbt_confirmed.transfer_group_key
  from public.pay_batch_candidates as pbc
  join public.pay_batch_items as pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers as pbt_confirmed
    on pbt_confirmed.id = pbi.pay_bank_transfer_id
   and pbt_confirmed.pay_batch_id = p_pay_batch_id
  where pbc.pay_batch_id = p_pay_batch_id
    and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
    and coalesce(pbi.is_voided, false) = false
    and pbi.item_type <> 'DEBT_CREATED'
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_confirmed_scope_correction
      where ppc_confirmed_scope_correction.pay_batch_item_id = pbi.id
        and ppc_confirmed_scope_correction.status = 'APPLIED'
        and ppc_confirmed_scope_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      (
        (v_scope = 'ALL' or v_scope = 'UMBRELLA')
        and upper(coalesce(pbi.pay_channel, '')) = 'UMBRELLA'
        and not (
          pbi.finance_case_id is not null
          and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      )
      or (
        (v_scope = 'ALL' or v_scope = 'PAYE')
        and upper(coalesce(pbi.pay_channel, '')) = 'PAYE'
      )
    )
    and (
      v_only_confirmed = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirmed.status,
              pbt_confirmed.rail_state,
              '{}'::jsonb,
              coalesce(pbt_confirmed.rail_meta_json, '{}'::jsonb)
            ) as movement_classification
            where coalesce(movement_classification.is_final_money_moved, false) = true
          )
          and not exists (
            select 1
            from public.mail_outbox as already_scoped_remittance
            where already_scoped_remittance.status::text in ('QUEUED','SENT')
              and coalesce(already_scoped_remittance.payment_scope_json->>'pay_batch_id', '') = p_pay_batch_id::text
              and exists (
                select 1
                from jsonb_array_elements_text(coalesce(already_scoped_remittance.payment_scope_json->'pay_bank_transfer_ids', '[]'::jsonb)) as already_transfer_ids(transfer_id_text)
                where already_transfer_ids.transfer_id_text = pbi.pay_bank_transfer_id::text
              )
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and pbc.remittance_sent_at_utc is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_commit_stage_excluded_transfers(
    transfer_id,
    candidate_id,
    umbrella_id
  )
  select distinct
    pbi_unconfirmed_scope.pay_bank_transfer_id,
    pbc_unconfirmed_scope.candidate_id,
    pbi_unconfirmed_scope.umbrella_id
  from public.pay_batch_candidates as pbc_unconfirmed_scope
  join public.pay_batch_items as pbi_unconfirmed_scope
    on pbi_unconfirmed_scope.pay_batch_candidate_id = pbc_unconfirmed_scope.id
  where pbc_unconfirmed_scope.pay_batch_id = p_pay_batch_id
    and v_only_confirmed
    and pbi_unconfirmed_scope.pay_bank_transfer_id is not null
    and coalesce(pbi_unconfirmed_scope.is_voided, false) = false
    and pbi_unconfirmed_scope.item_type <> 'DEBT_CREATED'
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_unconfirmed_scope_correction
      where ppc_unconfirmed_scope_correction.pay_batch_item_id = pbi_unconfirmed_scope.id
        and ppc_unconfirmed_scope_correction.status = 'APPLIED'
        and ppc_unconfirmed_scope_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      (
        (v_scope = 'ALL' or v_scope = 'UMBRELLA')
        and upper(coalesce(pbi_unconfirmed_scope.pay_channel, '')) = 'UMBRELLA'
        and not (
          pbi_unconfirmed_scope.finance_case_id is not null
          and pbi_unconfirmed_scope.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
          and jsonb_typeof(pbi_unconfirmed_scope.payout_instruction_snapshot_json) = 'object'
          and upper(coalesce(pbi_unconfirmed_scope.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
          and lower(btrim(coalesce(pbi_unconfirmed_scope.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
        )
      )
      or (
        (v_scope = 'ALL' or v_scope = 'PAYE')
        and upper(coalesce(pbi_unconfirmed_scope.pay_channel, '')) = 'PAYE'
      )
    )
    and not exists (
      select 1
      from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
      where confirmed_scope_item.pay_batch_item_id = pbi_unconfirmed_scope.id
    )
  on conflict (transfer_id) do nothing;

  insert into pg_temp.tmp_commit_stage_target_candidates(
    pay_batch_candidate_id,
    candidate_id,
    candidate_display_name,
    candidate_tms_ref
  )
  select distinct
    pbc.id,
    pbc.candidate_id,
    pbc.candidate_display_name,
    pbc.candidate_tms_ref
  from public.pay_batch_candidates as pbc
  where pbc.pay_batch_id = p_pay_batch_id
    and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
    and exists (
      select 1
      from pg_temp.tmp_commit_stage_confirmed_items as confirmed_target_item
      where confirmed_target_item.pay_batch_candidate_id = pbc.id
    );

  select count(*)::int
  into v_target_candidate_count
  from pg_temp.tmp_commit_stage_target_candidates tc;

  if v_target_candidate_count = 0 then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'NO_ELIGIBLE_UNSENT_CANDIDATES',
      'error', null,
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
      'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  begin
    v_build_result := public.pay_remittance_build(p_pay_batch_id, v_scope);
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'REMITTANCE_BUILD_ERROR',
      'error', left(coalesce(SQLERRM, 'pay_remittance_build failed'), 1000),
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end;

  if coalesce((v_build_result->>'ok')::boolean, false) = false then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'REMITTANCE_BUILD_ERROR',
      'error', left(coalesce(nullif(btrim(coalesce(v_build_result->>'error', '')), ''), 'pay_remittance_build returned not ok'), 1000),
      'message_kind', 'REMITTANCE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scope', v_scope,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  v_build_jobs := case
    when jsonb_typeof(v_build_result->'jobs') = 'array' then coalesce(v_build_result->'jobs', '[]'::jsonb)
    else '[]'::jsonb
  end;

  drop table if exists pg_temp.tmp_commit_stage_job_map;
  create temporary table pg_temp.tmp_commit_stage_job_map(
    candidate_id uuid not null,
    job_kind text not null,
    recipient_kind text null,
    recipient_email text null,
    umbrella_id uuid null
  ) on commit drop;

  for v_job in
    select j.value
    from jsonb_array_elements(v_build_jobs) as j(value)
  loop
    v_work_job := v_job;
    v_job_kind := upper(btrim(coalesce(v_job->>'job_kind', '')));
    v_recipient_kind := nullif(btrim(coalesce(v_job #>> '{recipient,entity_kind}', '')), '');
    v_recipient_email := coalesce(
      nullif(btrim(coalesce(v_job #>> '{recipient,email}', '')), ''),
      nullif(btrim(coalesce(v_job #>> '{recipient,remittance_email}', '')), '')
    );

    if v_job_kind = 'UMBRELLA_REMITTANCE' then
      v_umbrella_id_text := nullif(btrim(coalesce(v_job #>> '{recipient,umbrella_id}', '')), '');
      v_umbrella_id := null;

      if v_umbrella_id_text is not null then
        begin
          v_umbrella_id := v_umbrella_id_text::uuid;
        exception when invalid_text_representation then
          v_umbrella_id := null;
        end;
      end if;

      v_pruned_candidates := '[]'::jsonb;
      v_job_excluded_transfer_total := 0;

      for v_candidate_json in
        select ca.value
        from jsonb_array_elements(coalesce(v_job->'candidates', '[]'::jsonb)) as ca(value)
      loop
        v_candidate_id_text := nullif(btrim(coalesce(v_candidate_json->>'candidate_id', '')), '');
        v_candidate_id := null;

        if v_candidate_id_text is not null then
          begin
            v_candidate_id := v_candidate_id_text::uuid;
          exception when invalid_text_representation then
            v_candidate_id := null;
          end;
        end if;

        if v_candidate_id is not null
           and exists (
             select 1
             from pg_temp.tmp_commit_stage_target_candidates tc
             where tc.candidate_id = v_candidate_id
           ) then
          v_candidate_work_json := v_candidate_json;

          select round(coalesce(sum(pbt.amount), 0), 2)
          into v_candidate_excluded_transfer_total
          from pg_temp.tmp_commit_stage_excluded_transfers et
          join public.pay_bank_transfers pbt
            on pbt.id = et.transfer_id
          where et.candidate_id = v_candidate_id
            and (
              v_umbrella_id is null
              or et.umbrella_id is null
              or et.umbrella_id = v_umbrella_id
            );

          v_job_excluded_transfer_total := round(coalesce(v_job_excluded_transfer_total, 0) + coalesce(v_candidate_excluded_transfer_total, 0), 2);

          select coalesce(jsonb_agg(nt.value order by nt.ord), '[]'::jsonb)
          into v_pruned_non_timesheet_lines
          from jsonb_array_elements(coalesce(v_candidate_json->'non_timesheet_lines', '[]'::jsonb)) with ordinality as nt(value, ord)
          where not (
            upper(coalesce(nt.value->>'internal_item_type', '')) in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            and nullif(btrim(coalesce(nt.value->>'finance_case_id', '')), '') is not null
            and exists (
              select 1
              from pg_temp.tmp_commit_stage_excluded_finance_cases ef
              where ef.candidate_id = v_candidate_id
                and ef.finance_case_id::text = btrim(nt.value->>'finance_case_id')
            )
          );

          v_candidate_work_json := jsonb_set(v_candidate_work_json, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

          if v_only_confirmed then
            select coalesce(jsonb_agg(timesheet_rows.value order by timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_timesheets
            from jsonb_array_elements(coalesce(v_candidate_work_json->'timesheets', '[]'::jsonb)) with ordinality as timesheet_rows(value, ord)
            where nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_timesheet_item
                where confirmed_timesheet_item.candidate_id = v_candidate_id
                  and confirmed_timesheet_item.timesheet_id is not null
                  and confirmed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_timesheet_item
                join public.pay_batch_candidates as mixed_timesheet_candidate
                  on mixed_timesheet_candidate.id = mixed_timesheet_item.pay_batch_candidate_id
                where mixed_timesheet_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_timesheet_candidate.candidate_id = v_candidate_id
                  and mixed_timesheet_item.timesheet_id is not null
                  and mixed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
                  and coalesce(mixed_timesheet_item.is_voided, false) = false
                  and mixed_timesheet_item.item_type <> 'DEBT_CREATED'
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_timesheet_correction
                    where mixed_timesheet_correction.pay_batch_item_id = mixed_timesheet_item.id
                      and mixed_timesheet_correction.status = 'APPLIED'
                      and mixed_timesheet_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_timesheet_item
                    where confirmed_mixed_timesheet_item.pay_batch_item_id = mixed_timesheet_item.id
                  )
              );

            v_candidate_work_json := jsonb_set(v_candidate_work_json, '{timesheets}', coalesce(v_pruned_timesheets, '[]'::jsonb), true);

            select coalesce(jsonb_agg(non_timesheet_rows.value order by non_timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_non_timesheet_lines
            from jsonb_array_elements(coalesce(v_candidate_work_json->'non_timesheet_lines', '[]'::jsonb)) with ordinality as non_timesheet_rows(value, ord)
            where (
                (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_finance_item
                    where confirmed_finance_item.candidate_id = v_candidate_id
                      and confirmed_finance_item.finance_case_id is not null
                      and confirmed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                  )
                )
                or (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_carry_forward_item
                    where confirmed_carry_forward_item.candidate_id = v_candidate_id
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id is not null
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                  )
                )
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_finance_item
                join public.pay_batch_candidates as mixed_finance_candidate
                  on mixed_finance_candidate.id = mixed_finance_item.pay_batch_candidate_id
                where mixed_finance_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_finance_candidate.candidate_id = v_candidate_id
                  and coalesce(mixed_finance_item.is_voided, false) = false
                  and mixed_finance_item.item_type <> 'DEBT_CREATED'
                  and (
                    (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                      and mixed_finance_item.finance_case_id is not null
                      and mixed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                    )
                    or (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                      and (
                        mixed_finance_item.source_ref = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.operation_source_key = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.frozen_source_basis_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                        or mixed_finance_item.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                      )
                    )
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_finance_correction
                    where mixed_finance_correction.pay_batch_item_id = mixed_finance_item.id
                      and mixed_finance_correction.status = 'APPLIED'
                      and mixed_finance_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_finance_item
                    where confirmed_mixed_finance_item.pay_batch_item_id = mixed_finance_item.id
                  )
              );

            v_candidate_work_json := jsonb_set(v_candidate_work_json, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

            if jsonb_typeof(v_candidate_work_json->'transfers') = 'array' then
              select coalesce(jsonb_agg(transfer_rows.value order by transfer_rows.ord), '[]'::jsonb)
              into v_pruned_transfers
              from jsonb_array_elements(coalesce(v_candidate_work_json->'transfers', '[]'::jsonb)) with ordinality as transfer_rows(value, ord)
              where nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '') is not null
                and exists (
                  select 1
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer_item
                  where confirmed_transfer_item.candidate_id = v_candidate_id
                    and confirmed_transfer_item.pay_bank_transfer_id is not null
                    and confirmed_transfer_item.pay_bank_transfer_id::text = nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '')
                );

              v_candidate_work_json := jsonb_set(v_candidate_work_json, '{transfers}', coalesce(v_pruned_transfers, '[]'::jsonb), true);
            end if;

            v_candidate_work_json := jsonb_set(
              v_candidate_work_json,
              '{confirmed_only_scope}',
              jsonb_build_object(
                'enabled', true,
                'granularity', 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS',
                'pay_bank_transfer_ids', coalesce((
                  select jsonb_agg(distinct confirmed_scope_transfer.pay_bank_transfer_id::text)
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_transfer
                  where confirmed_scope_transfer.candidate_id = v_candidate_id
                    and confirmed_scope_transfer.pay_bank_transfer_id is not null
                ), '[]'::jsonb),
                'pay_batch_item_ids', coalesce((
                  select jsonb_agg(distinct confirmed_scope_item.pay_batch_item_id::text)
                  from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
                  where confirmed_scope_item.candidate_id = v_candidate_id
                ), '[]'::jsonb)
              ),
              true
            );
          end if;

          if jsonb_typeof(v_candidate_work_json->'totals') = 'object' then
            if btrim(coalesce(v_candidate_work_json #>> '{totals,final_paid}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
              v_final_paid_amount := round(greatest((v_candidate_work_json #>> '{totals,final_paid}')::numeric - coalesce(v_candidate_excluded_transfer_total, 0), 0), 2);
              v_candidate_work_json := jsonb_set(v_candidate_work_json, '{totals,final_paid}', to_jsonb(v_final_paid_amount), true);
              if jsonb_typeof(v_candidate_work_json #> '{totals,deductions_summary}') = 'object' then
                v_candidate_work_json := jsonb_set(v_candidate_work_json, '{totals,deductions_summary,final_payable}', to_jsonb(v_final_paid_amount), true);
              end if;
            end if;
          end if;

          v_pruned_candidates := v_pruned_candidates || jsonb_build_array(v_candidate_work_json);

          insert into pg_temp.tmp_commit_stage_job_map(
            candidate_id,
            job_kind,
            recipient_kind,
            recipient_email,
            umbrella_id
          )
          values (
            v_candidate_id,
            v_job_kind,
            v_recipient_kind,
            v_recipient_email,
            v_umbrella_id
          );
        end if;
      end loop;

      if jsonb_array_length(v_pruned_candidates) > 0 then
        if btrim(coalesce(v_job #>> '{summary,total_amount}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
          v_original_job_total := (v_job #>> '{summary,total_amount}')::numeric;
        else
          v_original_job_total := 0;
        end if;

        v_pruned_total_amount := round(greatest(coalesce(v_original_job_total, 0) - coalesce(v_job_excluded_transfer_total, 0), 0), 2);

        v_work_job := jsonb_set(v_work_job, '{candidates}', v_pruned_candidates, true);
        v_work_job := jsonb_set(v_work_job, '{summary,total_amount}', to_jsonb(coalesce(v_pruned_total_amount, 0)), true);
        v_work_job := jsonb_set(
          v_work_job,
          '{queue_context}',
          jsonb_strip_nulls(jsonb_build_object(
            'context_kind', 'pay_batches',
            'context_id', p_pay_batch_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'only_confirmed', v_only_confirmed,
            'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else null end,
            'job_kind', v_job_kind,
            'recipient_kind', v_recipient_kind,
            'umbrella_id', case when v_umbrella_id is null then null else v_umbrella_id::text end,
            'candidate_ids', coalesce((
              select jsonb_agg(nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), '') order by nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), ''))
              from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as candidate_context(value)
              where nullif(btrim(coalesce(candidate_context.value->>'candidate_id', '')), '') is not null
            ), '[]'::jsonb),
            'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
              'notice_scope', 'UMBRELLA_GROUP',
              'pay_batch_id', p_pay_batch_id::text,
              'pay_batch_candidate_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_target_candidates.pay_batch_candidate_id::text)
                from pg_temp.tmp_commit_stage_target_candidates as umbrella_scope_target_candidates
                where exists (
                  select 1
                  from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                  where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_target_candidates.candidate_id::text
                )
              ), '[]'::jsonb),
              'candidate_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_candidate_ids.candidate_id_text)
                from (
                  select nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') as candidate_id_text
                  from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                  where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') is not null
                ) as umbrella_scope_candidate_ids
              ), '[]'::jsonb),
              'umbrella_ids', case when v_umbrella_id is null then '[]'::jsonb else jsonb_build_array(v_umbrella_id::text) end,
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_items.pay_bank_transfer_id::text)
                from public.pay_batch_items as umbrella_scope_items
                join public.pay_batch_candidates as umbrella_scope_candidates
                  on umbrella_scope_candidates.id = umbrella_scope_items.pay_batch_candidate_id
                where umbrella_scope_candidates.pay_batch_id = p_pay_batch_id
                  and umbrella_scope_items.pay_bank_transfer_id is not null
                  and coalesce(umbrella_scope_items.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_items.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_items.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_candidates.candidate_id::text
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as umbrella_scope_corrections
                    where umbrella_scope_corrections.pay_batch_item_id = umbrella_scope_items.id
                      and umbrella_scope_corrections.status = 'APPLIED'
                      and umbrella_scope_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_confirmed_items
                      where umbrella_scope_confirmed_items.pay_batch_item_id = umbrella_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'transfer_group_keys', coalesce((
                select jsonb_agg(distinct umbrella_scope_transfers.transfer_group_key)
                from public.pay_batch_items as umbrella_scope_transfer_items
                join public.pay_batch_candidates as umbrella_scope_transfer_candidates
                  on umbrella_scope_transfer_candidates.id = umbrella_scope_transfer_items.pay_batch_candidate_id
                join public.pay_bank_transfers as umbrella_scope_transfers
                  on umbrella_scope_transfers.id = umbrella_scope_transfer_items.pay_bank_transfer_id
                where umbrella_scope_transfer_candidates.pay_batch_id = p_pay_batch_id
                  and umbrella_scope_transfers.transfer_group_key is not null
                  and coalesce(umbrella_scope_transfer_items.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_transfer_items.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_transfer_items.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_transfer_candidates.candidate_id::text
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_transfer_confirmed_items
                      where umbrella_scope_transfer_confirmed_items.pay_batch_item_id = umbrella_scope_transfer_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct umbrella_scope_item_ids.id::text)
                from public.pay_batch_items as umbrella_scope_item_ids
                join public.pay_batch_candidates as umbrella_scope_item_candidates
                  on umbrella_scope_item_candidates.id = umbrella_scope_item_ids.pay_batch_candidate_id
                where umbrella_scope_item_candidates.pay_batch_id = p_pay_batch_id
                  and coalesce(umbrella_scope_item_ids.is_voided, false) = false
                  and upper(coalesce(umbrella_scope_item_ids.pay_channel, '')) = 'UMBRELLA'
                  and (v_umbrella_id is null or umbrella_scope_item_ids.umbrella_id = v_umbrella_id)
                  and exists (
                    select 1
                    from jsonb_array_elements(coalesce(v_pruned_candidates, '[]'::jsonb)) as umbrella_scope_candidate_json(value)
                    where nullif(btrim(coalesce(umbrella_scope_candidate_json.value->>'candidate_id', '')), '') = umbrella_scope_item_candidates.candidate_id::text
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as umbrella_scope_item_corrections
                    where umbrella_scope_item_corrections.pay_batch_item_id = umbrella_scope_item_ids.id
                      and umbrella_scope_item_corrections.status = 'APPLIED'
                      and umbrella_scope_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as umbrella_scope_item_confirmed_items
                      where umbrella_scope_item_confirmed_items.pay_batch_item_id = umbrella_scope_item_ids.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_channels', jsonb_build_array('UMBRELLA')
            )),
            'reference', concat('pay_batch:', p_pay_batch_id::text, ':umbrella:', coalesce(v_umbrella_id::text, 'UNKNOWN'))
          )),
          true
        );
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          coalesce(v_work_job #> '{queue_context,payment_scope_json}', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);
      end if;
    elsif v_job_kind in ('PAYE_REMITTANCE', 'CANDIDATE_UMBRELLA_COPY_REMITTANCE') then
      v_candidate_id_text := nullif(btrim(coalesce(v_job #>> '{recipient,candidate_id}', '')), '');
      v_candidate_id := null;

      if v_candidate_id_text is not null then
        begin
          v_candidate_id := v_candidate_id_text::uuid;
        exception when invalid_text_representation then
          v_candidate_id := null;
        end;
      end if;

      if v_candidate_id is not null
         and v_recipient_email is not null
         and exists (
           select 1
           from pg_temp.tmp_commit_stage_target_candidates tc
           where tc.candidate_id = v_candidate_id
         ) then
        if v_only_confirmed then
          select round(coalesce(sum(pbt_excluded_candidate.amount), 0), 2)
          into v_candidate_excluded_transfer_total
          from pg_temp.tmp_commit_stage_excluded_transfers as excluded_candidate_transfer
          join public.pay_bank_transfers as pbt_excluded_candidate
            on pbt_excluded_candidate.id = excluded_candidate_transfer.transfer_id
          where excluded_candidate_transfer.candidate_id = v_candidate_id;

          if jsonb_typeof(v_work_job->'timesheets') = 'array' then
            select coalesce(jsonb_agg(timesheet_rows.value order by timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_timesheets
            from jsonb_array_elements(coalesce(v_work_job->'timesheets', '[]'::jsonb)) with ordinality as timesheet_rows(value, ord)
            where nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_timesheet_item
                where confirmed_timesheet_item.candidate_id = v_candidate_id
                  and confirmed_timesheet_item.timesheet_id is not null
                  and confirmed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_timesheet_item
                join public.pay_batch_candidates as mixed_timesheet_candidate
                  on mixed_timesheet_candidate.id = mixed_timesheet_item.pay_batch_candidate_id
                where mixed_timesheet_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_timesheet_candidate.candidate_id = v_candidate_id
                  and mixed_timesheet_item.timesheet_id is not null
                  and mixed_timesheet_item.timesheet_id::text = nullif(btrim(coalesce(timesheet_rows.value->>'timesheet_id', '')), '')
                  and coalesce(mixed_timesheet_item.is_voided, false) = false
                  and mixed_timesheet_item.item_type <> 'DEBT_CREATED'
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_timesheet_correction
                    where mixed_timesheet_correction.pay_batch_item_id = mixed_timesheet_item.id
                      and mixed_timesheet_correction.status = 'APPLIED'
                      and mixed_timesheet_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_timesheet_item
                    where confirmed_mixed_timesheet_item.pay_batch_item_id = mixed_timesheet_item.id
                  )
              );

            v_work_job := jsonb_set(v_work_job, '{timesheets}', coalesce(v_pruned_timesheets, '[]'::jsonb), true);
          end if;

          if jsonb_typeof(v_work_job->'non_timesheet_lines') = 'array' then
            select coalesce(jsonb_agg(non_timesheet_rows.value order by non_timesheet_rows.ord), '[]'::jsonb)
            into v_pruned_non_timesheet_lines
            from jsonb_array_elements(coalesce(v_work_job->'non_timesheet_lines', '[]'::jsonb)) with ordinality as non_timesheet_rows(value, ord)
            where (
                (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_finance_item
                    where confirmed_finance_item.candidate_id = v_candidate_id
                      and confirmed_finance_item.finance_case_id is not null
                      and confirmed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                  )
                )
                or (
                  nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                  and exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_carry_forward_item
                    where confirmed_carry_forward_item.candidate_id = v_candidate_id
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id is not null
                      and confirmed_carry_forward_item.manual_adjustment_carry_forward_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                  )
                )
              )
              and not exists (
                select 1
                from public.pay_batch_items as mixed_finance_item
                join public.pay_batch_candidates as mixed_finance_candidate
                  on mixed_finance_candidate.id = mixed_finance_item.pay_batch_candidate_id
                where mixed_finance_candidate.pay_batch_id = p_pay_batch_id
                  and mixed_finance_candidate.candidate_id = v_candidate_id
                  and coalesce(mixed_finance_item.is_voided, false) = false
                  and mixed_finance_item.item_type <> 'DEBT_CREATED'
                  and (
                    (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '') is not null
                      and mixed_finance_item.finance_case_id is not null
                      and mixed_finance_item.finance_case_id::text = nullif(btrim(coalesce(non_timesheet_rows.value->>'finance_case_id', '')), '')
                    )
                    or (
                      nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '') is not null
                      and (
                        mixed_finance_item.source_ref = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.operation_source_key = ('carry_forward:' || nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), ''))
                        or mixed_finance_item.frozen_source_basis_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                        or mixed_finance_item.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id' = nullif(btrim(coalesce(non_timesheet_rows.value->>'manual_adjustment_carry_forward_id', '')), '')
                      )
                    )
                  )
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as mixed_finance_correction
                    where mixed_finance_correction.pay_batch_item_id = mixed_finance_item.id
                      and mixed_finance_correction.status = 'APPLIED'
                      and mixed_finance_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and not exists (
                    select 1
                    from pg_temp.tmp_commit_stage_confirmed_items as confirmed_mixed_finance_item
                    where confirmed_mixed_finance_item.pay_batch_item_id = mixed_finance_item.id
                  )
              );

            v_work_job := jsonb_set(v_work_job, '{non_timesheet_lines}', coalesce(v_pruned_non_timesheet_lines, '[]'::jsonb), true);

          end if;

          if jsonb_typeof(v_work_job->'transfers') = 'array' then
            select coalesce(jsonb_agg(transfer_rows.value order by transfer_rows.ord), '[]'::jsonb)
            into v_pruned_transfers
            from jsonb_array_elements(coalesce(v_work_job->'transfers', '[]'::jsonb)) with ordinality as transfer_rows(value, ord)
            where nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '') is not null
              and exists (
                select 1
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer_item
                where confirmed_transfer_item.candidate_id = v_candidate_id
                  and confirmed_transfer_item.pay_bank_transfer_id is not null
                  and confirmed_transfer_item.pay_bank_transfer_id::text = nullif(btrim(coalesce(transfer_rows.value->>'transfer_id', '')), '')
              );

            v_work_job := jsonb_set(v_work_job, '{transfers}', coalesce(v_pruned_transfers, '[]'::jsonb), true);
          end if;

          select round(coalesce(sum(confirmed_transfer_amounts.amount), 0), 2)
          into v_final_paid_amount
          from (
            select distinct
              confirmed_transfer.pay_bank_transfer_id,
              pbt_confirmed_amount.amount
            from pg_temp.tmp_commit_stage_confirmed_items as confirmed_transfer
            join public.pay_bank_transfers as pbt_confirmed_amount
              on pbt_confirmed_amount.id = confirmed_transfer.pay_bank_transfer_id
            where confirmed_transfer.candidate_id = v_candidate_id
              and confirmed_transfer.pay_bank_transfer_id is not null
          ) as confirmed_transfer_amounts;

          if coalesce(v_final_paid_amount, 0) <= 0
             and btrim(coalesce(v_work_job #>> '{summary,total_amount}', '')) ~ '^-?[0-9]+(\.[0-9]+)?$' then
            v_final_paid_amount := round(greatest((v_work_job #>> '{summary,total_amount}')::numeric - coalesce(v_candidate_excluded_transfer_total, 0), 0), 2);
          end if;

          if coalesce(v_final_paid_amount, 0) >= 0 then
            v_work_job := jsonb_set(v_work_job, '{summary,total_amount}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
            if jsonb_typeof(v_work_job->'pay_totals') = 'object' then
              v_work_job := jsonb_set(v_work_job, '{pay_totals,final_paid}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
              if jsonb_typeof(v_work_job #> '{pay_totals,deductions_summary}') = 'object' then
                v_work_job := jsonb_set(v_work_job, '{pay_totals,deductions_summary,final_payable}', to_jsonb(coalesce(v_final_paid_amount, 0)), true);
              end if;
            end if;
          end if;

          v_work_job := jsonb_set(
            v_work_job,
            '{confirmed_only_scope}',
            jsonb_build_object(
              'enabled', true,
              'granularity', 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS',
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct confirmed_scope_transfer.pay_bank_transfer_id::text)
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_transfer
                where confirmed_scope_transfer.candidate_id = v_candidate_id
                  and confirmed_scope_transfer.pay_bank_transfer_id is not null
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct confirmed_scope_item.pay_batch_item_id::text)
                from pg_temp.tmp_commit_stage_confirmed_items as confirmed_scope_item
                where confirmed_scope_item.candidate_id = v_candidate_id
              ), '[]'::jsonb)
            ),
            true
          );
        end if;

        v_work_job := jsonb_set(
          v_work_job,
          '{queue_context}',
          jsonb_strip_nulls(jsonb_build_object(
            'context_kind', 'pay_batches',
            'context_id', p_pay_batch_id::text,
            'pay_batch_id', p_pay_batch_id::text,
            'scope', v_scope,
            'only_confirmed', v_only_confirmed,
            'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else null end,
            'job_kind', v_job_kind,
            'recipient_kind', v_recipient_kind,
            'candidate_id', v_candidate_id::text,
            'pay_batch_candidate_id', (
              select tc.pay_batch_candidate_id::text
              from pg_temp.tmp_commit_stage_target_candidates tc
              where tc.candidate_id = v_candidate_id
              order by tc.pay_batch_candidate_id
              limit 1
            ),
            'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
              'notice_scope', 'CANDIDATE',
              'pay_batch_id', p_pay_batch_id::text,
              'pay_batch_candidate_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_target_candidates.pay_batch_candidate_id::text)
                from pg_temp.tmp_commit_stage_target_candidates as candidate_scope_target_candidates
                where candidate_scope_target_candidates.candidate_id = v_candidate_id
              ), '[]'::jsonb),
              'candidate_ids', jsonb_build_array(v_candidate_id::text),
              'umbrella_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_items.umbrella_id::text)
                from public.pay_batch_items as candidate_scope_items
                join public.pay_batch_candidates as candidate_scope_candidates
                  on candidate_scope_candidates.id = candidate_scope_items.pay_batch_candidate_id
                where candidate_scope_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_candidates.candidate_id = v_candidate_id
                  and candidate_scope_items.umbrella_id is not null
                  and coalesce(candidate_scope_items.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_umbrella_corrections
                    where candidate_scope_umbrella_corrections.pay_batch_item_id = candidate_scope_items.id
                      and candidate_scope_umbrella_corrections.status = 'APPLIED'
                      and candidate_scope_umbrella_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_umbrella_confirmed_items
                      where candidate_scope_umbrella_confirmed_items.pay_batch_item_id = candidate_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_bank_transfer_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_items.pay_bank_transfer_id::text)
                from public.pay_batch_items as candidate_scope_items
                join public.pay_batch_candidates as candidate_scope_candidates
                  on candidate_scope_candidates.id = candidate_scope_items.pay_batch_candidate_id
                where candidate_scope_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_candidates.candidate_id = v_candidate_id
                  and candidate_scope_items.pay_bank_transfer_id is not null
                  and coalesce(candidate_scope_items.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_transfer_corrections
                    where candidate_scope_transfer_corrections.pay_batch_item_id = candidate_scope_items.id
                      and candidate_scope_transfer_corrections.status = 'APPLIED'
                      and candidate_scope_transfer_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_transfer_confirmed_items
                      where candidate_scope_transfer_confirmed_items.pay_batch_item_id = candidate_scope_items.id
                    )
                  )
              ), '[]'::jsonb),
              'transfer_group_keys', coalesce((
                select jsonb_agg(distinct candidate_scope_transfers.transfer_group_key)
                from public.pay_batch_items as candidate_scope_transfer_items
                join public.pay_batch_candidates as candidate_scope_transfer_candidates
                  on candidate_scope_transfer_candidates.id = candidate_scope_transfer_items.pay_batch_candidate_id
                join public.pay_bank_transfers as candidate_scope_transfers
                  on candidate_scope_transfers.id = candidate_scope_transfer_items.pay_bank_transfer_id
                where candidate_scope_transfer_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_transfer_candidates.candidate_id = v_candidate_id
                  and candidate_scope_transfers.transfer_group_key is not null
                  and coalesce(candidate_scope_transfer_items.is_voided, false) = false
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_group_confirmed_items
                      where candidate_scope_group_confirmed_items.pay_batch_item_id = candidate_scope_transfer_items.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_batch_item_ids', coalesce((
                select jsonb_agg(distinct candidate_scope_item_ids.id::text)
                from public.pay_batch_items as candidate_scope_item_ids
                join public.pay_batch_candidates as candidate_scope_item_candidates
                  on candidate_scope_item_candidates.id = candidate_scope_item_ids.pay_batch_candidate_id
                where candidate_scope_item_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_item_candidates.candidate_id = v_candidate_id
                  and coalesce(candidate_scope_item_ids.is_voided, false) = false
                  and not exists (
                    select 1
                    from public.pay_payment_correction_items as candidate_scope_item_corrections
                    where candidate_scope_item_corrections.pay_batch_item_id = candidate_scope_item_ids.id
                      and candidate_scope_item_corrections.status = 'APPLIED'
                      and candidate_scope_item_corrections.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                  )
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_item_confirmed_items
                      where candidate_scope_item_confirmed_items.pay_batch_item_id = candidate_scope_item_ids.id
                    )
                  )
              ), '[]'::jsonb),
              'pay_channels', coalesce((
                select jsonb_agg(distinct upper(coalesce(candidate_scope_channels.pay_channel, '')))
                from public.pay_batch_items as candidate_scope_channels
                join public.pay_batch_candidates as candidate_scope_channel_candidates
                  on candidate_scope_channel_candidates.id = candidate_scope_channels.pay_batch_candidate_id
                where candidate_scope_channel_candidates.pay_batch_id = p_pay_batch_id
                  and candidate_scope_channel_candidates.candidate_id = v_candidate_id
                  and nullif(btrim(coalesce(candidate_scope_channels.pay_channel, '')), '') is not null
                  and (
                    v_only_confirmed = false
                    or exists (
                      select 1
                      from pg_temp.tmp_commit_stage_confirmed_items as candidate_scope_channel_confirmed_items
                      where candidate_scope_channel_confirmed_items.pay_batch_item_id = candidate_scope_channels.id
                    )
                  )
              ), '[]'::jsonb)
            )),
            'reference', concat('pay_batch:', p_pay_batch_id::text, ':candidate:', v_candidate_id::text)
          )),
          true
        );
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          coalesce(v_work_job #> '{queue_context,payment_scope_json}', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_commit_stage_job_map(
          candidate_id,
          job_kind,
          recipient_kind,
          recipient_email,
          umbrella_id
        )
        values (
          v_candidate_id,
          v_job_kind,
          v_recipient_kind,
          v_recipient_email,
          null::uuid
        );
      end if;
    end if;
  end loop;

  select count(distinct jm.candidate_id)::int
  into v_ready_candidate_count
  from pg_temp.tmp_commit_stage_job_map jm;

  select jsonb_array_length(v_filtered_jobs)
  into v_job_count;

  if v_job_count > 0 then
    update public.pay_batch_candidates pbc
    set
      remittance_trigger_status = 'REMITTANCE_BUILD_READY',
      last_remittance_error = null,
      updated_at = now()
    where pbc.pay_batch_id = p_pay_batch_id
      and (pbc.remittance_sent_at_utc is null or v_only_confirmed)
      and exists (
        select 1
        from pg_temp.tmp_commit_stage_job_map jm
        where jm.candidate_id = pbc.candidate_id
      );

    v_trigger_status := 'REMITTANCE_BUILD_READY';
  else
    v_trigger_status := 'NO_QUEUEABLE_REMITTANCE_JOB';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'pay_batch_candidate_id', tc.pay_batch_candidate_id::text,
               'candidate_id', tc.candidate_id::text,
               'candidate_display_name', tc.candidate_display_name,
               'candidate_tms_ref', tc.candidate_tms_ref,
               'has_job', exists (
                 select 1
                 from pg_temp.tmp_commit_stage_job_map jm
                 where jm.candidate_id = tc.candidate_id
               ),
               'job_kinds', coalesce(
                 (
                   select jsonb_agg(to_jsonb(jk.job_kind) order by jk.job_kind)
                   from (
                     select distinct jm2.job_kind
                     from pg_temp.tmp_commit_stage_job_map jm2
                     where jm2.candidate_id = tc.candidate_id
                   ) jk
                 ),
                 '[]'::jsonb
               ),
               'trigger_status',
                 case
                   when exists (
                     select 1
                     from pg_temp.tmp_commit_stage_job_map jm3
                     where jm3.candidate_id = tc.candidate_id
                   )
                   then 'REMITTANCE_BUILD_READY'
                   else 'NO_QUEUEABLE_REMITTANCE_JOB'
                 end
             )
             order by tc.candidate_display_name nulls last, tc.candidate_tms_ref nulls last, tc.candidate_id
           ),
           '[]'::jsonb
         )
  into v_candidate_results
  from pg_temp.tmp_commit_stage_target_candidates tc;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'job_kind', upper(btrim(coalesce(j.job->>'job_kind', ''))),
               'recipient_kind', nullif(btrim(coalesce(j.job #>> '{recipient,entity_kind}', '')), ''),
               'recipient_id',
                 case
                   when upper(btrim(coalesce(j.job #>> '{recipient,entity_kind}', ''))) = 'CANDIDATE'
                     then nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '')
                   when upper(btrim(coalesce(j.job #>> '{recipient,entity_kind}', ''))) = 'UMBRELLA'
                     then nullif(btrim(coalesce(j.job #>> '{recipient,umbrella_id}', '')), '')
                   else null
                 end,
               'recipient_email', coalesce(
                 nullif(btrim(coalesce(j.job #>> '{recipient,email}', '')), ''),
                 nullif(btrim(coalesce(j.job #>> '{recipient,remittance_email}', '')), '')
               ),
               'candidate_ids',
                 case
                   when upper(btrim(coalesce(j.job->>'job_kind', ''))) = 'UMBRELLA_REMITTANCE'
                     then coalesce(
                       (
                         select jsonb_agg(to_jsonb(ci.candidate_id_text) order by ci.candidate_id_text)
                         from (
                           select nullif(btrim(coalesce(ca.value->>'candidate_id', '')), '') as candidate_id_text
                           from jsonb_array_elements(coalesce(j.job->'candidates', '[]'::jsonb)) as ca(value)
                           where nullif(btrim(coalesce(ca.value->>'candidate_id', '')), '') is not null
                         ) ci
                       ),
                       '[]'::jsonb
                     )
                   else
                     case
                       when nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '') is null
                         then '[]'::jsonb
                       else jsonb_build_array(j.job #>> '{recipient,candidate_id}')
                     end
                 end,
               'candidate_count',
                 case
                   when upper(btrim(coalesce(j.job->>'job_kind', ''))) = 'UMBRELLA_REMITTANCE'
                     then jsonb_array_length(coalesce(j.job->'candidates', '[]'::jsonb))
                   when nullif(btrim(coalesce(j.job #>> '{recipient,candidate_id}', '')), '') is null
                     then 0
                   else 1
                 end
             )
             order by j.ord
           ),
           '[]'::jsonb
         )
  into v_job_results
  from jsonb_array_elements(v_filtered_jobs) with ordinality as j(job, ord);

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope', v_scope,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
      'trigger_status', v_trigger_status,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', v_ready_candidate_count,
      'job_count', v_job_count
    ),
    'pay_remittance',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'trigger_status', v_trigger_status,
    'error', null,
    'message_kind', 'REMITTANCE',
    'automatic_commit_stage', true,
    'dispatch_required', (v_job_count > 0),
    'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'scope', v_scope,
    'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
    'pay_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
    'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'candidate_count_targeted', v_target_candidate_count,
    'candidate_count_ready', v_ready_candidate_count,
    'candidate_count_without_jobs', greatest(v_target_candidate_count - v_ready_candidate_count, 0),
    'job_count', v_job_count,
    'candidate_results', coalesce(v_candidate_results, '[]'::jsonb),
    'job_results', coalesce(v_job_results, '[]'::jsonb),
    'jobs', coalesce(v_filtered_jobs, '[]'::jsonb)
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_REMITTANCE_QUEUE_COMMIT_STAGE_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope', v_scope,
        'only_confirmed', COALESCE(p_only_confirmed, false),
      'confirmed_only_granularity', case when v_only_confirmed then 'TRANSFER_PAYMENT_GROUP_CONFIRMED_ITEMS' else 'NOT_APPLICABLE' end,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_remittance',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;









DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid);

DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid, boolean, uuid, jsonb);



DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid);
DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid, boolean);
DROP FUNCTION IF EXISTS public.pay_finance_payout_notice_queue_commit_stage(uuid, uuid, boolean, uuid, jsonb);

CREATE OR REPLACE FUNCTION public.pay_finance_payout_notice_queue_commit_stage(
  p_pay_batch_id uuid,
  p_actor_user_id uuid,
  p_only_confirmed boolean DEFAULT false,
  p_operation_id uuid DEFAULT NULL::uuid,
  p_remittance_scope_ids jsonb DEFAULT NULL::jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_batch record;
  v_build_result jsonb := '{}'::jsonb;
  v_build_jobs jsonb := '[]'::jsonb;
  v_filtered_jobs jsonb := '[]'::jsonb;
  v_candidate_results jsonb := '[]'::jsonb;
  v_job_results jsonb := '[]'::jsonb;

  v_job jsonb;
  v_work_job jsonb;
  v_job_kind text;
  v_recipient_email text;
  v_candidate_id_text text;
  v_candidate_id uuid;

  v_pruned_job_items jsonb := '[]'::jsonb;
  v_pruned_job_total numeric := 0;
  v_pruned_job_item_count integer := 0;
  v_first_label text := null;
  v_subject text := null;
  v_worker_message text := null;
  v_queue_context jsonb := '{}'::jsonb;
  v_queue_reference text := null;

  v_target_candidate_count integer := 0;
  v_ready_candidate_count integer := 0;
  v_job_count integer := 0;
  v_trigger_status text := null;
  v_execution_intent_json jsonb := '{}'::jsonb;
  v_settlement_confirmation_json jsonb := '{}'::jsonb;
  v_suppress_remittances boolean := false;

  v_operation_mode boolean := false;
  v_operation_row public.banking_pay_operations%ROWTYPE;
  v_requested_scope_count integer := 0;
  v_matched_scope_count integer := 0;
  v_already_queued_count integer := 0;
  v_inserted_outbox_count integer := 0;
  v_reused_outbox_count integer := 0;
  v_skipped_count integer := 0;
  v_failed_count integer := 0;
  v_remaining_count integer := 0;
  v_has_more boolean := false;
  v_operation_scope_ids jsonb := '[]'::jsonb;
  v_operation_job_results jsonb := '[]'::jsonb;
  v_legacy_scope_count integer := 0;
begin
  if p_pay_batch_id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: pay_batch_id is required';
  end if;

  if p_actor_user_id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: actor_user_id is required';
  end if;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'only_confirmed', COALESCE(p_only_confirmed, false)
    ),
    'pay_finance_payout_notice',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  select
    pb.id,
    pb.status,
    pb.batch_kind_fixed,
    pb.pay_date,
    pb.authoritative_payment_date,
    pb.authoritative_payment_date_source,
    pb.bulk_reference,
    pb.execution_commit_state,
    pb.execution_commit_ref,
    pb.execution_committed_at_utc,
    pb.execution_intent_json,
    pb.settlement_confirmation_json
  into v_batch
  from public.pay_batches pb
  where pb.id = p_pay_batch_id
  limit 1;

  if v_batch.id is null then
    raise exception 'pay_finance_payout_notice_queue_commit_stage: pay batch % not found.', p_pay_batch_id;
  end if;

  if v_batch.execution_intent_json is not null and jsonb_typeof(v_batch.execution_intent_json) = 'object' then
    v_execution_intent_json := v_batch.execution_intent_json;
  else
    v_execution_intent_json := '{}'::jsonb;
  end if;

  if v_batch.settlement_confirmation_json is not null and jsonb_typeof(v_batch.settlement_confirmation_json) = 'object' then
    v_settlement_confirmation_json := v_batch.settlement_confirmation_json;
  else
    v_settlement_confirmation_json := '{}'::jsonb;
  end if;

  v_suppress_remittances := lower(btrim(coalesce(
    v_settlement_confirmation_json->>'suppress_remittances',
    v_execution_intent_json->>'suppress_remittances',
    'false'
  ))) in ('true','1','yes','y','on');

  v_operation_mode := (p_operation_id IS NOT NULL OR p_remittance_scope_ids IS NOT NULL);

  IF v_operation_mode THEN
    IF p_operation_id IS NULL THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode requires p_operation_id';
    END IF;
    IF p_remittance_scope_ids IS NULL OR jsonb_typeof(p_remittance_scope_ids) <> 'array' OR jsonb_array_length(p_remittance_scope_ids) = 0 THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode requires non-empty p_remittance_scope_ids';
    END IF;

    SELECT operation_row.*
    INTO v_operation_row
    FROM public.banking_pay_operations AS operation_row
    WHERE operation_row.id = p_operation_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % not found', p_operation_id;
    END IF;

    IF v_operation_row.operation_type NOT IN ('REMITTANCE_QUEUE', 'PAYMENT_EXECUTE', 'PAYMENT_SETTLEMENT') THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % is not payout-notice-capable', p_operation_id;
    END IF;

    IF v_operation_row.pay_batch_id IS NOT NULL AND v_operation_row.pay_batch_id <> p_pay_batch_id THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % is for pay batch %, not %', p_operation_id, v_operation_row.pay_batch_id, p_pay_batch_id;
    END IF;

    IF v_operation_row.actor_user_id IS NOT NULL AND v_operation_row.actor_user_id <> p_actor_user_id THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage: operation % belongs to a different actor', p_operation_id;
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    SELECT COUNT(*)::integer
    INTO v_requested_scope_count
    FROM requested_scope;

    IF v_requested_scope_count <> jsonb_array_length(p_remittance_scope_ids) THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode received invalid or duplicate remittance scope ids';
    END IF;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
      FOR UPDATE OF scope_row
    )
    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'QUEUED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope.status = 'FAILED')::integer,
           COALESCE(jsonb_agg(to_jsonb(selected_scope.id::text) ORDER BY selected_scope.id::text), '[]'::jsonb)
    INTO v_matched_scope_count,
         v_already_queued_count,
         v_skipped_count,
         v_failed_count,
         v_operation_scope_ids
    FROM selected_scope;

    IF v_matched_scope_count <> v_requested_scope_count THEN
      RAISE EXCEPTION 'pay_finance_payout_notice_queue_commit_stage operation mode one or more remittance scope ids do not belong to operation % and batch %', p_operation_id, p_pay_batch_id;
    END IF;

    IF v_suppress_remittances = true THEN
      WITH requested_scope AS (
        SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
        FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
        WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      ), skipped_scope AS (
        UPDATE public.banking_pay_operation_remittance_scope AS scope_update
        SET status = 'SKIPPED',
            payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
              'skip_reason', 'SUPPRESSED_BY_EXECUTION_INTENT',
              'skipped_at_utc', now()::text
            )),
            updated_at_utc = now()
        FROM requested_scope
        WHERE scope_update.id = requested_scope.remittance_scope_id
          AND scope_update.operation_id = p_operation_id
          AND scope_update.pay_batch_id = p_pay_batch_id
          AND scope_update.status IN ('PENDING', 'FAILED')
        RETURNING scope_update.id
      ), selected_scope_after AS (
        SELECT scope_row.status
        FROM public.banking_pay_operation_remittance_scope AS scope_row
        JOIN requested_scope
          ON requested_scope.remittance_scope_id = scope_row.id
        WHERE scope_row.operation_id = p_operation_id
          AND scope_row.pay_batch_id = p_pay_batch_id
      )
      SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'QUEUED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
             COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
      INTO v_already_queued_count,
           v_skipped_count,
           v_failed_count
      FROM selected_scope_after;

      SELECT COUNT(*)::integer
      INTO v_remaining_count
      FROM public.banking_pay_operation_remittance_scope AS remaining_scope
      WHERE remaining_scope.operation_id = p_operation_id
        AND remaining_scope.pay_batch_id = p_pay_batch_id
        AND remaining_scope.status = 'PENDING';

      v_has_more := COALESCE(v_remaining_count, 0) > 0;

      UPDATE public.banking_pay_operations AS operation_update
      SET pay_batch_id = p_pay_batch_id,
          updated_at_utc = now()
      WHERE operation_update.id = p_operation_id
        AND operation_update.pay_batch_id IS NULL;

      RETURN jsonb_build_object(
        'ok', true,
        'operation_mode', true,
        'operation_id', p_operation_id::text,
        'pay_batch_id', p_pay_batch_id::text,
        'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
        'message_kind', 'PAYOUT_NOTICE',
        'queued_count', 0,
        'reused_count', COALESCE(v_already_queued_count, 0),
        'skipped_count', COALESCE(v_skipped_count, 0),
        'failed_count', COALESCE(v_failed_count, 0),
        'remaining', COALESCE(v_remaining_count, 0),
        'has_more', v_has_more,
        'dispatch_required', false,
        'remittance_scope_ids', COALESCE(v_operation_scope_ids, '[]'::jsonb),
        'job_results', '[]'::jsonb
      );
    END IF;

    DROP TABLE IF EXISTS pg_temp.tmp_operation_payout_notice_targets;
    CREATE TEMPORARY TABLE pg_temp.tmp_operation_payout_notice_targets AS
    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope AS (
      SELECT scope_row.*
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    ), payload_item_ids AS (
      SELECT selected_scope.id AS remittance_scope_id,
             (item_element.value #>> '{}')::uuid AS pay_batch_item_id
      FROM selected_scope
      CROSS JOIN LATERAL jsonb_array_elements(COALESCE(selected_scope.payload_json->'pay_batch_item_ids', '[]'::jsonb)) AS item_element(value)
      WHERE (item_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), eligible_item_rows AS (
      SELECT
        selected_scope.id AS remittance_scope_id,
        selected_scope.status AS scope_status,
        pbc.id AS pay_batch_candidate_id,
        pbc.candidate_id,
        pbi.id AS pay_batch_item_id,
        pbi.finance_case_id,
        pbi.item_type,
        pbi.description,
        pbi.amount_inc_vat,
        pbi.amount_ex_vat,
        pbi.payout_instruction_snapshot_json,
        pbi.pay_bank_transfer_id,
        pbi.source_ref,
        pbi.operation_source_key,
        COALESCE(
          NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), ''),
          NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), ''),
          CASE
            WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), '^carry_forward:', '', 'i')
            WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), '^carry_forward:', '', 'i')
            ELSE NULL
          END
        ) AS manual_adjustment_carry_forward_id,
        CASE
          WHEN pbi.item_type = 'LOAN_PAYOUT' THEN 'Payment Advance'
          WHEN pbi.item_type = 'MANUAL_CREDIT_PAYOUT' THEN 'Manual Credit Adjustment'
          ELSE COALESCE(NULLIF(BTRIM(COALESCE(pbi.description, '')), ''), 'Payment')
        END AS item_label,
        pa_payout.case_type,
        pa_payout.payout_status,
        pa_payout.payout_pay_batch_id,
        pa_payout.payout_transfer_id,
        pa_payout.adjustment_comment,
        pa_payout.schedule_json,
        pa_payout.weekly_due,
        pa_payout.weeks_total,
        pa_payout.start_week_start,
        pa_payout.next_due_week_start,
        pa_payout.outstanding_amount
      FROM selected_scope
      JOIN payload_item_ids
        ON payload_item_ids.remittance_scope_id = selected_scope.id
      JOIN public.pay_batch_items AS pbi
        ON pbi.id = payload_item_ids.pay_batch_item_id
      JOIN public.pay_batch_candidates AS pbc
        ON pbc.id = pbi.pay_batch_candidate_id
       AND pbc.pay_batch_id = p_pay_batch_id
      LEFT JOIN public.pay_bank_transfers AS pbt_confirm
        ON pbt_confirm.id = pbi.pay_bank_transfer_id
       AND pbt_confirm.pay_batch_id = p_pay_batch_id
      LEFT JOIN public.pay_advances AS pa_payout
        ON pa_payout.id = pbi.finance_case_id
      WHERE COALESCE(pbi.is_voided, false) = false
        AND NOT EXISTS (
          SELECT 1
          FROM public.pay_payment_correction_items AS payout_notice_correction
          WHERE payout_notice_correction.pay_batch_item_id = pbi.id
            AND payout_notice_correction.status = 'APPLIED'
            AND payout_notice_correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
        )
        AND (
          pbi.finance_case_id IS NOT NULL
          OR (
            pbi.item_type IN ('MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
            AND (
              NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            )
          )
        )
        AND pbi.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY')
        AND (
          (
            jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
            AND upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
            AND lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
            AND lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
          )
          OR (
            pbi.item_type IN ('MANUAL_CREDIT_PAYOUT','MANUAL_DEBT_RECOVERY')
            AND (
              NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
              OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            )
          )
        )
        AND (
          COALESCE(p_only_confirmed, false) = false
          OR (
            (
              pbi.pay_bank_transfer_id IS NOT NULL
              AND EXISTS (
                SELECT 1
                FROM public._pay_rail_state_money_movement_classify(
                  pbt_confirm.status,
                  pbt_confirm.rail_state,
                  COALESCE(pbt_confirm.rail_meta_json, '{}'::jsonb),
                  COALESCE(pbt_confirm.rail_meta_json, '{}'::jsonb)
                ) AS final_paid_evidence_check
                WHERE final_paid_evidence_check.is_final_money_moved IS TRUE
              )
            )
            OR (
              pbi.pay_bank_transfer_id IS NULL
              AND (
                upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
                OR pbc.settled_at_utc IS NOT NULL
              )
            )
          )
        )
    ), grouped_targets AS (
      SELECT
        selected_scope.id AS remittance_scope_id,
        selected_scope.status,
        selected_scope.candidate_id,
        candidate_row.email AS recipient_email,
        candidate_row.display_name AS recipient_name,
        'payout_notice:pay_batch:' || p_pay_batch_id::text || ':scope:' || selected_scope.id::text || ':candidate:' || COALESCE(selected_scope.candidate_id::text, 'UNKNOWN') AS deterministic_outbox_key,
        COUNT(eligible_item_rows.pay_batch_item_id)::integer AS eligible_item_count,
        ROUND(COALESCE(SUM(COALESCE(eligible_item_rows.amount_inc_vat, eligible_item_rows.amount_ex_vat, 0)), 0), 2) AS total_amount,
        COALESCE(jsonb_agg(
          jsonb_strip_nulls(jsonb_build_object(
            'pay_batch_item_id', eligible_item_rows.pay_batch_item_id::text,
            'manual_adjustment_carry_forward_id', eligible_item_rows.manual_adjustment_carry_forward_id,
            'finance_case_id', CASE WHEN eligible_item_rows.finance_case_id IS NULL THEN NULL ELSE eligible_item_rows.finance_case_id::text END,
            'source_ref', eligible_item_rows.source_ref,
            'operation_source_key', eligible_item_rows.operation_source_key,
            'item_type', eligible_item_rows.item_type,
            'label', eligible_item_rows.item_label,
            'amount', ROUND(COALESCE(eligible_item_rows.amount_inc_vat, eligible_item_rows.amount_ex_vat, 0), 2),
            'amount_ex_vat', ROUND(COALESCE(eligible_item_rows.amount_ex_vat, 0), 2),
            'pay_bank_transfer_id', CASE WHEN eligible_item_rows.pay_bank_transfer_id IS NULL THEN NULL ELSE eligible_item_rows.pay_bank_transfer_id::text END,
            'case_type', CASE WHEN eligible_item_rows.case_type IS NULL THEN NULL ELSE eligible_item_rows.case_type::text END,
            'adjustment_comment', eligible_item_rows.adjustment_comment,
            'repayment_arrangement', CASE
              WHEN eligible_item_rows.item_type = 'LOAN_PAYOUT' THEN jsonb_build_object(
                'weekly_due', eligible_item_rows.weekly_due,
                'weeks_total', eligible_item_rows.weeks_total,
                'start_week_start', CASE WHEN eligible_item_rows.start_week_start IS NULL THEN NULL ELSE eligible_item_rows.start_week_start::text END,
                'next_due_week_start', CASE WHEN eligible_item_rows.next_due_week_start IS NULL THEN NULL ELSE eligible_item_rows.next_due_week_start::text END,
                'schedule_json', COALESCE(eligible_item_rows.schedule_json, '[]'::jsonb),
                'remaining_outstanding_amount', eligible_item_rows.outstanding_amount
              )
              ELSE NULL
            END
          )) ORDER BY eligible_item_rows.pay_batch_item_id::text
        ) FILTER (WHERE eligible_item_rows.pay_batch_item_id IS NOT NULL), '[]'::jsonb) AS items_json,
        selected_scope.payload_json
      FROM selected_scope
      LEFT JOIN public.candidates AS candidate_row
        ON candidate_row.id = selected_scope.candidate_id
      LEFT JOIN eligible_item_rows
        ON eligible_item_rows.remittance_scope_id = selected_scope.id
      GROUP BY selected_scope.id,
               selected_scope.status,
               selected_scope.candidate_id,
               candidate_row.email,
               candidate_row.display_name,
               selected_scope.payload_json
    )
    SELECT *
    FROM grouped_targets;

    WITH skipped_not_queueable AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'SKIPPED',
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'skip_reason', CASE
              WHEN NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL THEN 'MISSING_PAYOUT_NOTICE_RECIPIENT_EMAIL'
              ELSE 'NO_ELIGIBLE_PAYOUT_NOTICE_ITEMS'
            END,
            'skipped_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM pg_temp.tmp_operation_payout_notice_targets AS target_row
      WHERE scope_update.id = target_row.remittance_scope_id
        AND scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.status IN ('PENDING', 'FAILED')
        AND (
          NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NULL
          OR COALESCE(target_row.eligible_item_count, 0) = 0
        )
      RETURNING scope_update.id
    )
    SELECT COUNT(*)::integer
    INTO v_skipped_count
    FROM skipped_not_queueable;

    WITH valid_targets AS (
      SELECT target_row.*,
             CASE
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Payment Advance' THEN 'Payment Advance scheduled'
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Manual Credit Adjustment' THEN 'Manual Credit Adjustment scheduled'
               ELSE 'Payment scheduled'
             END AS subject_text,
             CASE
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Payment Advance' THEN 'A Payment Advance has been scheduled.'
               WHEN target_row.eligible_item_count = 1
                AND target_row.items_json->0->>'label' = 'Manual Credit Adjustment' THEN 'A Manual Credit Adjustment has been scheduled.'
               ELSE 'A payment has been scheduled.'
             END AS body_intro
      FROM pg_temp.tmp_operation_payout_notice_targets AS target_row
      WHERE target_row.status IN ('PENDING', 'FAILED')
        AND NULLIF(BTRIM(COALESCE(target_row.recipient_email, '')), '') IS NOT NULL
        AND COALESCE(target_row.eligible_item_count, 0) > 0
    ), upserted_outbox AS (
      INSERT INTO public.mail_outbox AS mail_insert (
        type,
        "to",
        cc,
        subject,
        body_html,
        body_text,
        attachments,
        status,
        created_at_utc,
        created_by,
        reference,
        recipient_kind,
        recipient_id,
        context_kind,
        context_id,
        email_type,
        importance,
        scheduled_for_utc,
        next_attempt_at_utc,
        payment_scope_json,
        deterministic_outbox_key
      )
      SELECT
        'REMITTANCE',
        valid_targets.recipient_email,
        NULL::text,
        valid_targets.subject_text,
        '<pre>' || valid_targets.body_intro || E'

Total amount: £' || COALESCE(valid_targets.total_amount::text, '0.00') || E'

This payout notice was generated from frozen CloudTMS payment batch artefacts.</pre>',
        valid_targets.body_intro || E'

Total amount: £' || COALESCE(valid_targets.total_amount::text, '0.00') || E'

This payout notice was generated from frozen CloudTMS payment batch artefacts.',
        '[]'::jsonb,
        'QUEUED'::public.mail_status_enum,
        now(),
        p_actor_user_id,
        valid_targets.deterministic_outbox_key,
        'candidate',
        valid_targets.candidate_id,
        'pay_batches',
        p_pay_batch_id,
        'html',
        'Normal',
        now(),
        now(),
        jsonb_strip_nulls(COALESCE(valid_targets.payload_json, '{}'::jsonb) || jsonb_build_object(
          'notice_scope', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'operation_id', p_operation_id::text,
          'remittance_scope_id', valid_targets.remittance_scope_id::text,
          'candidate_id', CASE WHEN valid_targets.candidate_id IS NULL THEN NULL ELSE valid_targets.candidate_id::text END,
          'deterministic_outbox_key', valid_targets.deterministic_outbox_key,
          'items', valid_targets.items_json,
          'total_amount', valid_targets.total_amount,
          'message_kind', 'PAYOUT_NOTICE'
        )),
        valid_targets.deterministic_outbox_key
      FROM valid_targets
      ON CONFLICT (deterministic_outbox_key)
      DO UPDATE
      SET status = CASE WHEN mail_insert.status::text = 'FAILED' THEN 'QUEUED'::public.mail_status_enum ELSE mail_insert.status END,
          last_error = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.last_error END,
          failed_at = CASE WHEN mail_insert.status::text = 'FAILED' THEN NULL ELSE mail_insert.failed_at END,
          next_attempt_at_utc = CASE WHEN mail_insert.status::text = 'FAILED' THEN now() ELSE mail_insert.next_attempt_at_utc END,
          payment_scope_json = CASE WHEN mail_insert.status::text = 'SENT' THEN mail_insert.payment_scope_json ELSE EXCLUDED.payment_scope_json END
      RETURNING mail_insert.id,
                mail_insert.deterministic_outbox_key,
                (xmax = 0) AS was_inserted
    ), updated_scope AS (
      UPDATE public.banking_pay_operation_remittance_scope AS scope_update
      SET status = 'QUEUED',
          outbox_id = upserted_outbox.id,
          payload_json = jsonb_strip_nulls(COALESCE(scope_update.payload_json, '{}'::jsonb) || jsonb_build_object(
            'payout_notice_outbox_key', upserted_outbox.deterministic_outbox_key,
            'payout_notice_queued_at_utc', now()::text
          )),
          updated_at_utc = now()
      FROM upserted_outbox
      JOIN pg_temp.tmp_operation_payout_notice_targets AS target_row
        ON target_row.deterministic_outbox_key = upserted_outbox.deterministic_outbox_key
      WHERE scope_update.operation_id = p_operation_id
        AND scope_update.pay_batch_id = p_pay_batch_id
        AND scope_update.id = target_row.remittance_scope_id
        AND scope_update.status IN ('PENDING', 'FAILED')
      RETURNING scope_update.id,
                upserted_outbox.id AS outbox_id,
                upserted_outbox.deterministic_outbox_key,
                upserted_outbox.was_inserted
    )
    SELECT COUNT(*) FILTER (WHERE updated_scope.was_inserted)::integer,
           COUNT(*) FILTER (WHERE updated_scope.was_inserted IS NOT TRUE)::integer,
           COALESCE(jsonb_agg(jsonb_build_object(
             'remittance_scope_id', updated_scope.id::text,
             'deterministic_outbox_key', updated_scope.deterministic_outbox_key,
             'outbox_id', updated_scope.outbox_id::text,
             'queued', true,
             'reused', (updated_scope.was_inserted IS NOT TRUE)
           ) ORDER BY updated_scope.id::text), '[]'::jsonb)
    INTO v_inserted_outbox_count,
         v_reused_outbox_count,
         v_operation_job_results
    FROM updated_scope;

    WITH requested_scope AS (
      SELECT DISTINCT (scope_element.value #>> '{}')::uuid AS remittance_scope_id
      FROM jsonb_array_elements(p_remittance_scope_ids) AS scope_element(value)
      WHERE (scope_element.value #>> '{}') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ), selected_scope_after AS (
      SELECT scope_row.status
      FROM public.banking_pay_operation_remittance_scope AS scope_row
      JOIN requested_scope
        ON requested_scope.remittance_scope_id = scope_row.id
      WHERE scope_row.operation_id = p_operation_id
        AND scope_row.pay_batch_id = p_pay_batch_id
    )
    SELECT COUNT(*) FILTER (WHERE selected_scope_after.status = 'SKIPPED')::integer,
           COUNT(*) FILTER (WHERE selected_scope_after.status = 'FAILED')::integer
    INTO v_skipped_count,
         v_failed_count
    FROM selected_scope_after;

    SELECT COUNT(*)::integer
    INTO v_remaining_count
    FROM public.banking_pay_operation_remittance_scope AS remaining_scope
    WHERE remaining_scope.operation_id = p_operation_id
      AND remaining_scope.pay_batch_id = p_pay_batch_id
      AND remaining_scope.status = 'PENDING';

    v_has_more := COALESCE(v_remaining_count, 0) > 0;

    UPDATE public.banking_pay_operations AS operation_update
    SET pay_batch_id = p_pay_batch_id,
        updated_at_utc = now()
    WHERE operation_update.id = p_operation_id
      AND operation_update.pay_batch_id IS NULL;

    RETURN jsonb_build_object(
      'ok', true,
      'operation_mode', true,
      'operation_id', p_operation_id::text,
      'pay_batch_id', p_pay_batch_id::text,
      'trigger_status', CASE WHEN COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0) > 0 THEN 'PAYOUT_NOTICE_QUEUE_CHUNK_PROCESSED' ELSE 'NO_QUEUEABLE_PAYOUT_NOTICE_SCOPE' END,
      'message_kind', 'PAYOUT_NOTICE',
      'queued_count', COALESCE(v_inserted_outbox_count, 0),
      'reused_count', COALESCE(v_reused_outbox_count, 0) + COALESCE(v_already_queued_count, 0),
      'skipped_count', COALESCE(v_skipped_count, 0),
      'failed_count', COALESCE(v_failed_count, 0),
      'remaining', COALESCE(v_remaining_count, 0),
      'has_more', v_has_more,
      'dispatch_required', (COALESCE(v_inserted_outbox_count, 0) + COALESCE(v_reused_outbox_count, 0) > 0),
      'remittance_scope_ids', COALESCE(v_operation_scope_ids, '[]'::jsonb),
      'job_results', COALESCE(v_operation_job_results, '[]'::jsonb)
    );
  END IF;

  if v_suppress_remittances = true then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'SUPPRESSED_BY_EXECUTION_INTENT',
      'error', null,
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'suppressed_by_execution_intent', true,
      'pay_batch_id', p_pay_batch_id::text,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  SELECT COUNT(DISTINCT legacy_candidate_count.candidate_id)::integer
  INTO v_legacy_scope_count
  FROM public.pay_batch_candidates AS legacy_candidate_count
  JOIN public.pay_batch_items AS legacy_payout_item
    ON legacy_payout_item.pay_batch_candidate_id = legacy_candidate_count.id
  LEFT JOIN public.pay_bank_transfers AS legacy_transfer_confirm
    ON legacy_transfer_confirm.id = legacy_payout_item.pay_bank_transfer_id
   AND legacy_transfer_confirm.pay_batch_id = p_pay_batch_id
  LEFT JOIN public.pay_advances AS legacy_payout_case
    ON legacy_payout_case.id = legacy_payout_item.finance_case_id
  WHERE legacy_candidate_count.pay_batch_id = p_pay_batch_id
    AND COALESCE(legacy_payout_item.is_voided, false) = false
    AND legacy_payout_item.finance_case_id IS NOT NULL
    AND legacy_payout_item.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    AND jsonb_typeof(legacy_payout_item.payout_instruction_snapshot_json) = 'object'
    AND upper(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    AND lower(btrim(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
    AND lower(btrim(coalesce(legacy_payout_item.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) IN ('true', '1', 'yes', 'y', 'on')
    AND NOT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_items AS legacy_payout_notice_correction
      WHERE legacy_payout_notice_correction.pay_batch_item_id = legacy_payout_item.id
        AND legacy_payout_notice_correction.status = 'APPLIED'
        AND legacy_payout_notice_correction.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    AND (
      COALESCE(p_only_confirmed, false) = false
      OR (
        (
          legacy_payout_item.pay_bank_transfer_id IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM public._pay_rail_state_money_movement_classify(
              legacy_transfer_confirm.status,
              legacy_transfer_confirm.rail_state,
              COALESCE(legacy_transfer_confirm.rail_meta_json, '{}'::jsonb),
              COALESCE(legacy_transfer_confirm.rail_meta_json, '{}'::jsonb)
            ) AS legacy_final_paid_evidence_check
            WHERE legacy_final_paid_evidence_check.is_final_money_moved IS TRUE
          )
        )
        OR (
          legacy_payout_item.pay_bank_transfer_id IS NULL
          AND (
            upper(btrim(coalesce(legacy_candidate_count.settlement_status, ''))) = 'SETTLED'
            OR legacy_candidate_count.settled_at_utc IS NOT NULL
          )
        )
      )
    );

  IF COALESCE(v_legacy_scope_count, 0) > 250 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_OPERATION_REQUIRED',
      'code', 'PAYOUT_NOTICE_OPERATION_REQUIRED',
      'message', 'pay_finance_payout_notice_queue_commit_stage legacy mode is limited to small batches; use the scalable remittance/payout notice operation for this payment batch.',
      'pay_batch_id', p_pay_batch_id::text,
      'candidate_count', v_legacy_scope_count,
      'legacy_safe_threshold', 250
    )::text;
  END IF;

  drop table if exists pg_temp.tmp_payout_notice_target_candidates;
  create temporary table pg_temp.tmp_payout_notice_target_candidates(
    pay_batch_candidate_id uuid primary key,
    candidate_id uuid not null,
    candidate_display_name text null,
    candidate_tms_ref text null
  ) on commit drop;

  drop table if exists pg_temp.tmp_payout_notice_target_items;
  create temporary table pg_temp.tmp_payout_notice_target_items(
    candidate_id uuid not null,
    finance_case_id uuid not null,
    primary key (candidate_id, finance_case_id)
  ) on commit drop;

  drop table if exists pg_temp.tmp_payout_notice_carry_forward_items;
  create temporary table pg_temp.tmp_payout_notice_carry_forward_items(
    candidate_id uuid not null,
    pay_batch_item_id uuid not null,
    item_json jsonb not null,
    amount_inc_vat numeric not null default 0,
    primary key (candidate_id, pay_batch_item_id)
  ) on commit drop;

  insert into pg_temp.tmp_payout_notice_target_items(
    candidate_id,
    finance_case_id
  )
  select distinct
    pbc.candidate_id,
    pbi.finance_case_id
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers pbt_confirm
    on pbt_confirm.id = pbi.pay_bank_transfer_id
   and pbt_confirm.pay_batch_id = p_pay_batch_id
  left join public.pay_advances pa_payout
    on pa_payout.id = pbi.finance_case_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_payout_notice_correction
      where ppc_payout_notice_correction.pay_batch_item_id = pbi.id
        and ppc_payout_notice_correction.status = 'APPLIED'
        and ppc_payout_notice_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and pbi.finance_case_id is not null
    and pbi.item_type in ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
    and jsonb_typeof(pbi.payout_instruction_snapshot_json) = 'object'
    and upper(coalesce(pbi.payout_instruction_snapshot_json->>'routing_kind', '')) = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'is_candidate_directed_oneoff_payout', 'false'))) in ('true', '1', 'yes', 'y', 'on')
    and lower(btrim(coalesce(pbi.payout_instruction_snapshot_json->>'generates_candidate_payment_advice', 'false'))) in ('true', '1', 'yes', 'y', 'on')
    and (
      coalesce(p_only_confirmed, false) = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirm.status,
              pbt_confirm.rail_state,
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb),
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb)
            ) as final_paid_evidence_check
            where final_paid_evidence_check.is_final_money_moved is true
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_payout_notice_carry_forward_items(
    candidate_id,
    pay_batch_item_id,
    item_json,
    amount_inc_vat
  )
  select distinct
    pbc.candidate_id,
    pbi.id,
    jsonb_strip_nulls(jsonb_build_object(
      'pay_batch_item_id', pbi.id::text,
      'manual_adjustment_carry_forward_id', COALESCE(
        NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), ''),
        NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), ''),
        CASE
          WHEN NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), ''), '^carry_forward:', '', 'i')
          WHEN NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
            THEN regexp_replace(NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), ''), '^carry_forward:', '', 'i')
          ELSE NULL
        END
      ),
      'finance_case_id', CASE WHEN pbi.finance_case_id IS NULL THEN NULL ELSE pbi.finance_case_id::text END,
      'item_type', pbi.item_type,
      'label', COALESCE(NULLIF(BTRIM(COALESCE(pbi.description, '')), ''), 'Manual adjustment carry-forward'),
      'amount', ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2),
      'amount_ex_vat', ROUND(COALESCE(pbi.amount_ex_vat, 0), 2),
      'amount_vat', ROUND(COALESCE(pbi.amount_vat, 0), 2),
      'amount_inc_vat', ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2),
      'pay_bank_transfer_id', CASE WHEN pbi.pay_bank_transfer_id IS NULL THEN NULL ELSE pbi.pay_bank_transfer_id::text END,
      'source_ref', pbi.source_ref,
      'operation_source_key', pbi.operation_source_key,
      'case_type', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
      'adjustment_comment', pbi.description,
      'signed_amount_convention', 'SIGNED_AMOUNTS'
    )),
    ROUND(COALESCE(pbi.amount_inc_vat, pbi.amount_ex_vat, 0), 2)
  from public.pay_batch_candidates pbc
  join public.pay_batch_items pbi
    on pbi.pay_batch_candidate_id = pbc.id
  left join public.pay_bank_transfers pbt_confirm
    on pbt_confirm.id = pbi.pay_bank_transfer_id
   and pbt_confirm.pay_batch_id = p_pay_batch_id
  where pbc.pay_batch_id = p_pay_batch_id
    and coalesce(pbi.is_voided, false) = false
    and pbi.item_type in ('MANUAL_CREDIT_PAYOUT', 'MANUAL_DEBT_RECOVERY')
    and (
      NULLIF(BTRIM(COALESCE(pbi.source_ref, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.operation_source_key, '')), '') ~* '^carry_forward:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.frozen_source_basis_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR NULLIF(BTRIM(COALESCE(pbi.frozen_component_snapshot_json->>'manual_adjustment_carry_forward_id', '')), '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    )
    and not exists (
      select 1
      from public.pay_payment_correction_items as ppc_payout_notice_carry_forward_correction
      where ppc_payout_notice_carry_forward_correction.pay_batch_item_id = pbi.id
        and ppc_payout_notice_carry_forward_correction.status = 'APPLIED'
        and ppc_payout_notice_carry_forward_correction.correction_item_kind in ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
    )
    and (
      coalesce(p_only_confirmed, false) = false
      or (
        (
          pbi.pay_bank_transfer_id is not null
          and exists (
            select 1
            from public._pay_rail_state_money_movement_classify(
              pbt_confirm.status,
              pbt_confirm.rail_state,
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb),
              coalesce(pbt_confirm.rail_meta_json, '{}'::jsonb)
            ) as final_paid_carry_forward_check
            where final_paid_carry_forward_check.is_final_money_moved is true
          )
        )
        or (
          pbi.pay_bank_transfer_id is null
          and (
            upper(btrim(coalesce(pbc.settlement_status, ''))) = 'SETTLED'
            or pbc.settled_at_utc is not null
          )
        )
      )
    );

  insert into pg_temp.tmp_payout_notice_target_candidates(
    pay_batch_candidate_id,
    candidate_id,
    candidate_display_name,
    candidate_tms_ref
  )
  select
    pbc.id,
    pbc.candidate_id,
    pbc.candidate_display_name,
    pbc.candidate_tms_ref
  from public.pay_batch_candidates pbc
  where pbc.pay_batch_id = p_pay_batch_id
    and (
      exists (
        select 1
        from pg_temp.tmp_payout_notice_target_items ti
        where ti.candidate_id = pbc.candidate_id
      )
      or exists (
        select 1
        from pg_temp.tmp_payout_notice_carry_forward_items cfi
        where cfi.candidate_id = pbc.candidate_id
      )
    )
    and not exists (
      select 1
      from public.mail_outbox mo
      where mo.reference = (
        'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || pbc.candidate_id::text
      )
        and upper(coalesce(mo.recipient_kind, '')) = 'CANDIDATE'
        and mo.recipient_id = pbc.candidate_id
        and lower(coalesce(mo.context_kind, '')) = 'pay_batches'
        and mo.context_id = p_pay_batch_id
    );

  select count(*)::int
  into v_target_candidate_count
  from pg_temp.tmp_payout_notice_target_candidates tc;

  if v_target_candidate_count = 0 then
    return jsonb_build_object(
      'ok', true,
      'trigger_status', 'NO_ELIGIBLE_UNSENT_CANDIDATES',
      'error', null,
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
      'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
      'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
      'bulk_reference', v_batch.bulk_reference,
      'candidate_count_targeted', 0,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', 0,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  begin
    v_build_result := public.pay_finance_payout_notice_build(p_pay_batch_id);
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'PAYOUT_NOTICE_BUILD_ERROR',
      'error', left(coalesce(SQLERRM, 'pay_finance_payout_notice_build failed'), 1000),
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end;

  if coalesce((v_build_result->>'ok')::boolean, false) = false then
    return jsonb_build_object(
      'ok', false,
      'trigger_status', 'PAYOUT_NOTICE_BUILD_ERROR',
      'error', left(coalesce(nullif(btrim(coalesce(v_build_result->>'error', '')), ''), 'pay_finance_payout_notice_build returned not ok'), 1000),
      'message_kind', 'PAYOUT_NOTICE',
      'automatic_commit_stage', true,
      'dispatch_required', false,
      'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', 0,
      'candidate_count_without_jobs', v_target_candidate_count,
      'job_count', 0,
      'candidate_results', '[]'::jsonb,
      'job_results', '[]'::jsonb,
      'jobs', '[]'::jsonb
    );
  end if;

  v_build_jobs := case
    when jsonb_typeof(v_build_result->'jobs') = 'array' then coalesce(v_build_result->'jobs', '[]'::jsonb)
    else '[]'::jsonb
  end;

  drop table if exists pg_temp.tmp_payout_notice_job_map;
  create temporary table pg_temp.tmp_payout_notice_job_map(
    candidate_id uuid not null,
    job_kind text not null,
    recipient_email text null
  ) on commit drop;

  for v_job in
    select j.value
    from jsonb_array_elements(v_build_jobs) as j(value)
  loop
    v_job_kind := upper(btrim(coalesce(v_job->>'job_kind', 'PAYOUT_NOTICE')));
    v_candidate_id_text := nullif(btrim(coalesce(v_job->>'candidate_id', '')), '');
    v_candidate_id := null;
    v_recipient_email := nullif(btrim(coalesce(v_job->>'recipient_email', '')), '');

    if v_candidate_id_text is not null then
      begin
        v_candidate_id := v_candidate_id_text::uuid;
      exception when invalid_text_representation then
        v_candidate_id := null;
      end;
    end if;

    if v_candidate_id is not null
       and exists (
         select 1
         from pg_temp.tmp_payout_notice_target_candidates tc
         where tc.candidate_id = v_candidate_id
       ) then
      select
        coalesce(jsonb_agg(it.value order by it.ord), '[]'::jsonb),
        round(
          coalesce(
            sum(
              case
                when btrim(coalesce(it.value->>'amount', '')) ~ '^-?[0-9]+(\.[0-9]+)?$'
                  then (it.value->>'amount')::numeric
                else 0
              end
            ),
            0
          ),
          2
        )
      into
        v_pruned_job_items,
        v_pruned_job_total
      from jsonb_array_elements(coalesce(v_job->'items', '[]'::jsonb)) with ordinality as it(value, ord)
      where nullif(btrim(coalesce(it.value->>'finance_case_id', '')), '') is not null
        and exists (
          select 1
          from pg_temp.tmp_payout_notice_target_items ti
          where ti.candidate_id = v_candidate_id
            and ti.finance_case_id::text = btrim(it.value->>'finance_case_id')
        );

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      select
        coalesce(v_pruned_job_items, '[]'::jsonb)
          || coalesce(jsonb_agg(cfi.item_json order by cfi.pay_batch_item_id::text), '[]'::jsonb),
        round(coalesce(v_pruned_job_total, 0) + coalesce(sum(cfi.amount_inc_vat), 0), 2)
      into
        v_pruned_job_items,
        v_pruned_job_total
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where cfi.candidate_id = v_candidate_id;

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      if v_pruned_job_item_count > 0 then
        v_first_label := nullif(btrim(coalesce(v_pruned_job_items->0->>'label', '')), '');

        v_subject := case
          when v_pruned_job_item_count = 1 and v_first_label = 'Payment Advance' then 'Payment Advance scheduled'
          when v_pruned_job_item_count = 1 and v_first_label = 'Manual Credit Adjustment' then 'Manual Credit Adjustment scheduled'
          else 'Payment scheduled'
        end;

        v_worker_message := case
          when v_pruned_job_item_count = 1 and v_first_label = 'Payment Advance' then 'A Payment Advance has been scheduled.'
          when v_pruned_job_item_count = 1 and v_first_label = 'Manual Credit Adjustment' then 'A Manual Credit Adjustment has been scheduled.'
          else 'A payment has been scheduled.'
        end;

        v_queue_reference := 'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || v_candidate_id::text;

        SELECT jsonb_build_object(
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'scope_kind', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'candidate_id', v_candidate_id::text,
          'pay_batch_candidate_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_candidates.pay_batch_candidate_id::text)
              FROM pg_temp.tmp_payout_notice_target_candidates AS public_tmp_payout_notice_candidates
              WHERE public_tmp_payout_notice_candidates.candidate_id = v_candidate_id
            ),
            '[]'::jsonb
          ),
          'candidate_ids', jsonb_build_array(v_candidate_id::text),
          'finance_case_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_target_items.finance_case_id::text)
              FROM pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_target_items
              WHERE public_tmp_payout_notice_target_items.candidate_id = v_candidate_id
            ),
            '[]'::jsonb
          ),
          'finance_component_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_component_scope.finance_component_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_component_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_component_scope
                ON public_pay_batch_candidates_component_scope.id = public_pay_batch_items_component_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_component_scope
                ON public_tmp_payout_notice_component_scope.candidate_id = public_pay_batch_candidates_component_scope.candidate_id
               AND public_tmp_payout_notice_component_scope.finance_case_id = public_pay_batch_items_component_scope.finance_case_id
              WHERE public_pay_batch_candidates_component_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_component_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_component_scope.finance_component_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_component_scope.is_voided, false) = false
                AND public_pay_batch_items_component_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            ),
            '[]'::jsonb
          ),
          'reservation_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_reservation_scope.reservation_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_reservation_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_reservation_scope
                ON public_pay_batch_candidates_reservation_scope.id = public_pay_batch_items_reservation_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_reservation_scope
                ON public_tmp_payout_notice_reservation_scope.candidate_id = public_pay_batch_candidates_reservation_scope.candidate_id
               AND public_tmp_payout_notice_reservation_scope.finance_case_id = public_pay_batch_items_reservation_scope.finance_case_id
              WHERE public_pay_batch_candidates_reservation_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_reservation_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_reservation_scope.reservation_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_reservation_scope.is_voided, false) = false
                AND public_pay_batch_items_reservation_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
            ),
            '[]'::jsonb
          ),
          'payout_transfer_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_advances_payout_scope.payout_transfer_id::text)
              FROM public.pay_advances AS public_pay_advances_payout_scope
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_payout_scope
                ON public_tmp_payout_notice_payout_scope.finance_case_id = public_pay_advances_payout_scope.id
               AND public_tmp_payout_notice_payout_scope.candidate_id = v_candidate_id
              WHERE public_pay_advances_payout_scope.payout_transfer_id IS NOT NULL
                AND public_pay_advances_payout_scope.payout_pay_batch_id = p_pay_batch_id
            ),
            '[]'::jsonb
          ),
          'pay_batch_item_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_scope.id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_scope
                ON public_pay_batch_candidates_scope.id = public_pay_batch_items_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_items_scope
                ON public_tmp_payout_notice_items_scope.candidate_id = public_pay_batch_candidates_scope.candidate_id
               AND public_tmp_payout_notice_items_scope.finance_case_id = public_pay_batch_items_scope.finance_case_id
              WHERE public_pay_batch_candidates_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_scope.candidate_id = v_candidate_id
                AND COALESCE(public_pay_batch_items_scope.is_voided, false) = false
                AND public_pay_batch_items_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items AS public_pay_payment_correction_items_scope
                  WHERE public_pay_payment_correction_items_scope.pay_batch_item_id = public_pay_batch_items_scope.id
                    AND public_pay_payment_correction_items_scope.status = 'APPLIED'
                    AND public_pay_payment_correction_items_scope.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                )
            ),
            '[]'::jsonb
          ),
          'pay_bank_transfer_ids', COALESCE(
            (
              SELECT jsonb_agg(DISTINCT public_pay_batch_items_transfer_scope.pay_bank_transfer_id::text)
              FROM public.pay_batch_items AS public_pay_batch_items_transfer_scope
              JOIN public.pay_batch_candidates AS public_pay_batch_candidates_transfer_scope
                ON public_pay_batch_candidates_transfer_scope.id = public_pay_batch_items_transfer_scope.pay_batch_candidate_id
              JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_transfer_scope
                ON public_tmp_payout_notice_transfer_scope.candidate_id = public_pay_batch_candidates_transfer_scope.candidate_id
               AND public_tmp_payout_notice_transfer_scope.finance_case_id = public_pay_batch_items_transfer_scope.finance_case_id
              WHERE public_pay_batch_candidates_transfer_scope.pay_batch_id = p_pay_batch_id
                AND public_pay_batch_candidates_transfer_scope.candidate_id = v_candidate_id
                AND public_pay_batch_items_transfer_scope.pay_bank_transfer_id IS NOT NULL
                AND COALESCE(public_pay_batch_items_transfer_scope.is_voided, false) = false
                AND public_pay_batch_items_transfer_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
                AND NOT EXISTS (
                  SELECT 1
                  FROM public.pay_payment_correction_items AS public_pay_payment_correction_transfer_scope
                  WHERE public_pay_payment_correction_transfer_scope.pay_batch_item_id = public_pay_batch_items_transfer_scope.id
                    AND public_pay_payment_correction_transfer_scope.status = 'APPLIED'
                    AND public_pay_payment_correction_transfer_scope.correction_item_kind IN ('PRE_BANK_CANCEL','NO_MONEY_UNWIND','SETTLED_REVERSAL')
                )
            ),
            '[]'::jsonb
          ),
          'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
            'notice_scope', 'FINANCE_PAYOUT',
            'pay_batch_id', p_pay_batch_id::text,
            'pay_batch_candidate_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_candidates.pay_batch_candidate_id::text)
                FROM pg_temp.tmp_payout_notice_target_candidates AS public_tmp_payout_notice_candidates
                WHERE public_tmp_payout_notice_candidates.candidate_id = v_candidate_id
              ),
              '[]'::jsonb
            ),
            'candidate_ids', jsonb_build_array(v_candidate_id::text),
            'finance_case_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_tmp_payout_notice_target_items.finance_case_id::text)
                FROM pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_target_items
                WHERE public_tmp_payout_notice_target_items.candidate_id = v_candidate_id
              ),
              '[]'::jsonb
            ),
            'finance_component_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_component_scope.finance_component_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_component_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_component_scope
                  ON public_pay_batch_candidates_component_scope.id = public_pay_batch_items_component_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_component_scope
                  ON public_tmp_payout_notice_component_scope.candidate_id = public_pay_batch_candidates_component_scope.candidate_id
                 AND public_tmp_payout_notice_component_scope.finance_case_id = public_pay_batch_items_component_scope.finance_case_id
                WHERE public_pay_batch_candidates_component_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_component_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_component_scope.finance_component_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_component_scope.is_voided, false) = false
                  AND public_pay_batch_items_component_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'reservation_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_reservation_scope.reservation_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_reservation_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_reservation_scope
                  ON public_pay_batch_candidates_reservation_scope.id = public_pay_batch_items_reservation_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_reservation_scope
                  ON public_tmp_payout_notice_reservation_scope.candidate_id = public_pay_batch_candidates_reservation_scope.candidate_id
                 AND public_tmp_payout_notice_reservation_scope.finance_case_id = public_pay_batch_items_reservation_scope.finance_case_id
                WHERE public_pay_batch_candidates_reservation_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_reservation_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_reservation_scope.reservation_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_reservation_scope.is_voided, false) = false
                  AND public_pay_batch_items_reservation_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'pay_bank_transfer_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_transfer_scope.pay_bank_transfer_id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_transfer_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_transfer_scope
                  ON public_pay_batch_candidates_transfer_scope.id = public_pay_batch_items_transfer_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_transfer_scope
                  ON public_tmp_payout_notice_transfer_scope.candidate_id = public_pay_batch_candidates_transfer_scope.candidate_id
                 AND public_tmp_payout_notice_transfer_scope.finance_case_id = public_pay_batch_items_transfer_scope.finance_case_id
                WHERE public_pay_batch_candidates_transfer_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_transfer_scope.candidate_id = v_candidate_id
                  AND public_pay_batch_items_transfer_scope.pay_bank_transfer_id IS NOT NULL
                  AND COALESCE(public_pay_batch_items_transfer_scope.is_voided, false) = false
                  AND public_pay_batch_items_transfer_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            ),
            'payout_transfer_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_advances_payout_scope.payout_transfer_id::text)
                FROM public.pay_advances AS public_pay_advances_payout_scope
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_payout_scope
                  ON public_tmp_payout_notice_payout_scope.finance_case_id = public_pay_advances_payout_scope.id
                 AND public_tmp_payout_notice_payout_scope.candidate_id = v_candidate_id
                WHERE public_pay_advances_payout_scope.payout_transfer_id IS NOT NULL
                  AND public_pay_advances_payout_scope.payout_pay_batch_id = p_pay_batch_id
              ),
              '[]'::jsonb
            ),
            'pay_batch_item_ids', COALESCE(
              (
                SELECT jsonb_agg(DISTINCT public_pay_batch_items_scope.id::text)
                FROM public.pay_batch_items AS public_pay_batch_items_scope
                JOIN public.pay_batch_candidates AS public_pay_batch_candidates_scope
                  ON public_pay_batch_candidates_scope.id = public_pay_batch_items_scope.pay_batch_candidate_id
                JOIN pg_temp.tmp_payout_notice_target_items AS public_tmp_payout_notice_items_scope
                  ON public_tmp_payout_notice_items_scope.candidate_id = public_pay_batch_candidates_scope.candidate_id
                 AND public_tmp_payout_notice_items_scope.finance_case_id = public_pay_batch_items_scope.finance_case_id
                WHERE public_pay_batch_candidates_scope.pay_batch_id = p_pay_batch_id
                  AND public_pay_batch_candidates_scope.candidate_id = v_candidate_id
                  AND COALESCE(public_pay_batch_items_scope.is_voided, false) = false
                  AND public_pay_batch_items_scope.item_type IN ('LOAN_PAYOUT', 'MANUAL_CREDIT_PAYOUT')
              ),
              '[]'::jsonb
            )
          ))
        )
        INTO v_queue_context;

        v_work_job := coalesce(v_job, '{}'::jsonb) || jsonb_build_object(
          'job_kind', 'PAYOUT_NOTICE',
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'queue_context', COALESCE(v_queue_context, '{}'::jsonb)
        );
        v_work_job := jsonb_set(v_work_job, '{items}', coalesce(v_pruned_job_items, '[]'::jsonb), true);
        v_work_job := jsonb_set(v_work_job, '{total_amount}', to_jsonb(coalesce(v_pruned_job_total, 0)), true);
        v_work_job := jsonb_set(v_work_job, '{subject}', to_jsonb(v_subject), true);
        v_work_job := jsonb_set(v_work_job, '{worker_message}', to_jsonb(v_worker_message), true);
        v_work_job := jsonb_set(
          v_work_job,
          '{payment_scope_json}',
          COALESCE(v_queue_context->'payment_scope_json', '{}'::jsonb),
          true
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_payout_notice_job_map(
          candidate_id,
          job_kind,
          recipient_email
        )
        values (
          v_candidate_id,
          v_job_kind,
          v_recipient_email
        );
      end if;
    end if;
  end loop;


  for v_candidate_id, v_recipient_email in
    select
      cfi_candidates.candidate_id,
      nullif(btrim(coalesce(candidate_row.email, '')), '') as recipient_email
    from (
      select distinct cfi.candidate_id
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where not exists (
        select 1
        from pg_temp.tmp_payout_notice_job_map jm
        where jm.candidate_id = cfi.candidate_id
      )
    ) cfi_candidates
    left join public.candidates as candidate_row
      on candidate_row.id = cfi_candidates.candidate_id
  loop
    if v_recipient_email is not null then
      select
        coalesce(jsonb_agg(cfi.item_json order by cfi.pay_batch_item_id::text), '[]'::jsonb),
        round(coalesce(sum(cfi.amount_inc_vat), 0), 2)
      into
        v_pruned_job_items,
        v_pruned_job_total
      from pg_temp.tmp_payout_notice_carry_forward_items cfi
      where cfi.candidate_id = v_candidate_id;

      v_pruned_job_item_count := jsonb_array_length(coalesce(v_pruned_job_items, '[]'::jsonb));

      if v_pruned_job_item_count > 0 then
        v_subject := case
          when v_pruned_job_item_count = 1 then 'Manual adjustment carried forward'
          else 'Manual adjustments carried forward'
        end;

        v_worker_message := case
          when v_pruned_job_item_count = 1 then 'A manual adjustment has been carried forward into this payment.'
          else 'Manual adjustments have been carried forward into this payment.'
        end;

        v_queue_reference := 'payout_notice:pay_batch:' || p_pay_batch_id::text || ':PAYOUT_NOTICE:CANDIDATE:' || v_candidate_id::text;

        select jsonb_build_object(
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'scope_kind', 'PAYOUT_NOTICE_CANDIDATE',
          'pay_batch_id', p_pay_batch_id::text,
          'candidate_id', v_candidate_id::text,
          'pay_batch_candidate_ids', COALESCE((
            select jsonb_agg(distinct pbc_scope.id::text)
            from public.pay_batch_candidates pbc_scope
            where pbc_scope.pay_batch_id = p_pay_batch_id
              and pbc_scope.candidate_id = v_candidate_id
          ), '[]'::jsonb),
          'candidate_ids', jsonb_build_array(v_candidate_id::text),
          'finance_case_ids', '[]'::jsonb,
          'finance_component_ids', '[]'::jsonb,
          'reservation_ids', '[]'::jsonb,
          'payout_transfer_ids', '[]'::jsonb,
          'pay_batch_item_ids', COALESCE((
            select jsonb_agg(distinct cfi_scope.pay_batch_item_id::text order by cfi_scope.pay_batch_item_id::text)
            from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
            where cfi_scope.candidate_id = v_candidate_id
          ), '[]'::jsonb),
          'pay_bank_transfer_ids', COALESCE((
            select jsonb_agg(distinct cfi_scope.item_json->>'pay_bank_transfer_id' order by cfi_scope.item_json->>'pay_bank_transfer_id')
            from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
            where cfi_scope.candidate_id = v_candidate_id
              and nullif(btrim(coalesce(cfi_scope.item_json->>'pay_bank_transfer_id', '')), '') is not null
          ), '[]'::jsonb),
          'payment_scope_json', jsonb_strip_nulls(jsonb_build_object(
            'notice_scope', 'MANUAL_ADJUSTMENT_CARRY_FORWARD',
            'pay_batch_id', p_pay_batch_id::text,
            'candidate_ids', jsonb_build_array(v_candidate_id::text),
            'pay_batch_item_ids', COALESCE((
              select jsonb_agg(distinct cfi_scope.pay_batch_item_id::text order by cfi_scope.pay_batch_item_id::text)
              from pg_temp.tmp_payout_notice_carry_forward_items cfi_scope
              where cfi_scope.candidate_id = v_candidate_id
            ), '[]'::jsonb)
          ))
        )
        into v_queue_context;

        v_work_job := jsonb_build_object(
          'job_kind', 'PAYOUT_NOTICE',
          'candidate_id', v_candidate_id::text,
          'recipient_email', v_recipient_email,
          'context_kind', 'pay_batches',
          'context_id', p_pay_batch_id::text,
          'reference', v_queue_reference,
          'recipient_kind', 'CANDIDATE',
          'recipient_id', v_candidate_id::text,
          'queue_context', COALESCE(v_queue_context, '{}'::jsonb),
          'items', coalesce(v_pruned_job_items, '[]'::jsonb),
          'total_amount', coalesce(v_pruned_job_total, 0),
          'subject', v_subject,
          'worker_message', v_worker_message,
          'payment_scope_json', COALESCE(v_queue_context->'payment_scope_json', '{}'::jsonb)
        );

        v_filtered_jobs := v_filtered_jobs || jsonb_build_array(v_work_job);

        insert into pg_temp.tmp_payout_notice_job_map(
          candidate_id,
          job_kind,
          recipient_email
        )
        values (
          v_candidate_id,
          'PAYOUT_NOTICE',
          v_recipient_email
        );
      end if;
    end if;
  end loop;

  select count(distinct jm.candidate_id)::int
  into v_ready_candidate_count
  from pg_temp.tmp_payout_notice_job_map jm;

  select jsonb_array_length(v_filtered_jobs)
  into v_job_count;

  if v_job_count > 0 then
    v_trigger_status := 'PAYOUT_NOTICE_BUILD_READY';
  else
    v_trigger_status := 'NO_QUEUEABLE_PAYOUT_NOTICE_JOB';
  end if;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'pay_batch_candidate_id', tc.pay_batch_candidate_id::text,
               'candidate_id', tc.candidate_id::text,
               'candidate_display_name', tc.candidate_display_name,
               'candidate_tms_ref', tc.candidate_tms_ref,
               'has_job', exists (
                 select 1
                 from pg_temp.tmp_payout_notice_job_map jm
                 where jm.candidate_id = tc.candidate_id
               ),
               'job_kinds', coalesce(
                 (
                   select jsonb_agg(to_jsonb(jk.job_kind) order by jk.job_kind)
                   from (
                     select distinct jm2.job_kind
                     from pg_temp.tmp_payout_notice_job_map jm2
                     where jm2.candidate_id = tc.candidate_id
                   ) jk
                 ),
                 '[]'::jsonb
               ),
               'trigger_status',
                 case
                   when exists (
                     select 1
                     from pg_temp.tmp_payout_notice_job_map jm3
                     where jm3.candidate_id = tc.candidate_id
                   )
                   then 'PAYOUT_NOTICE_BUILD_READY'
                   else 'NO_QUEUEABLE_PAYOUT_NOTICE_JOB'
                 end
             )
             order by tc.candidate_display_name nulls last, tc.candidate_tms_ref nulls last, tc.candidate_id
           ),
           '[]'::jsonb
         )
  into v_candidate_results
  from pg_temp.tmp_payout_notice_target_candidates tc;

  select coalesce(
           jsonb_agg(
             jsonb_build_object(
               'job_kind', upper(btrim(coalesce(j.job->>'job_kind', 'PAYOUT_NOTICE'))),
               'candidate_id', nullif(btrim(coalesce(j.job->>'candidate_id', '')), ''),
               'recipient_email', nullif(btrim(coalesce(j.job->>'recipient_email', '')), ''),
               'scheduled_payment_date', nullif(btrim(coalesce(j.job->>'scheduled_payment_date', '')), ''),
               'subject', nullif(btrim(coalesce(j.job->>'subject', '')), ''),
               'label_set', coalesce(
                 (
                   select jsonb_agg(to_jsonb(li.label_text) order by li.label_text)
                   from (
                     select distinct nullif(btrim(coalesce(it.value->>'label', '')), '') as label_text
                     from jsonb_array_elements(coalesce(j.job->'items', '[]'::jsonb)) as it(value)
                     where nullif(btrim(coalesce(it.value->>'label', '')), '') is not null
                   ) li
                 ),
                 '[]'::jsonb
               )
             )
             order by j.ord
           ),
           '[]'::jsonb
         )
  into v_job_results
  from jsonb_array_elements(v_filtered_jobs) with ordinality as j(job, ord);

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'only_confirmed', COALESCE(p_only_confirmed, false),
      'trigger_status', v_trigger_status,
      'candidate_count_targeted', v_target_candidate_count,
      'candidate_count_ready', v_ready_candidate_count,
      'job_count', v_job_count
    ),
    'pay_finance_payout_notice',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  return jsonb_build_object(
    'ok', true,
    'trigger_status', v_trigger_status,
    'error', null,
    'message_kind', 'PAYOUT_NOTICE',
    'automatic_commit_stage', true,
    'dispatch_required', (v_job_count > 0),
    'pay_batch_id', p_pay_batch_id::text,
      'execution_commit_state', v_batch.execution_commit_state,
      'execution_commit_ref', v_batch.execution_commit_ref,
      'execution_committed_at_utc', case when v_batch.execution_committed_at_utc is null then null else v_batch.execution_committed_at_utc::text end,
    'scheduled_payment_date', case when coalesce(v_batch.authoritative_payment_date, v_batch.pay_date) is null then null else coalesce(v_batch.authoritative_payment_date, v_batch.pay_date)::text end,
    'authoritative_payment_date', case when v_batch.authoritative_payment_date is null then null else v_batch.authoritative_payment_date::text end,
    'authoritative_payment_date_source', v_batch.authoritative_payment_date_source,
    'bulk_reference', v_batch.bulk_reference,
    'candidate_count_targeted', v_target_candidate_count,
    'candidate_count_ready', v_ready_candidate_count,
    'candidate_count_without_jobs', greatest(v_target_candidate_count - v_ready_candidate_count, 0),
    'job_count', v_job_count,
    'candidate_results', coalesce(v_candidate_results, '[]'::jsonb),
    'job_results', coalesce(v_job_results, '[]'::jsonb),
    'jobs', coalesce(v_filtered_jobs, '[]'::jsonb)
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_PAYOUT_NOTICE_QUEUE_COMMIT_STAGE_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'only_confirmed', COALESCE(p_only_confirmed, false),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_finance_payout_notice',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
end;
$function$;


create or replace function public.pay_finance_case_restructure(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_weekly_due numeric,
  p_weeks_total int,
  p_start_week_start date,
  p_minimum_earnings_threshold numeric default null,
  p_take_home_floor_override numeric default null,
  p_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due_week_start date := null;
  v_required_weeks int := 0;
  v_remaining_amount numeric(12,2);
  v_component_remaining_amount numeric(12,2) := 0;
  v_open_component_count integer := 0;
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_note text;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;
  v_candidate_pay_method text := null;
  v_taxable_channel_restructure_required boolean := false;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_ID_REQUIRED',
      'message','pay_finance_case_restructure: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','ACTOR_USER_ID_REQUIRED',
      'message','pay_finance_case_restructure: actor_user_id is required'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','START_WEEK_START_REQUIRED',
      'message','pay_finance_case_restructure: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','START_WEEK_START_NOT_MONDAY',
      'message','pay_finance_case_restructure: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message','pay_finance_case_restructure: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','TAKE_HOME_FLOOR_INVALID',
      'message','pay_finance_case_restructure: take_home_floor_override must be >= 0'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type in ('PAYMENT_ADVANCE'::public.pay_finance_case_type_enum, 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum)
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_NOT_FOUND',
      'message','pay_finance_case_restructure: repayable finance case not found or not eligible for restructure',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if coalesce(v_case.write_off_reason,'') <> '' or v_case.written_off_at_utc is not null then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_WRITTEN_OFF',
      'message','pay_finance_case_restructure: written-off finance cases cannot be restructured',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','FINANCE_CASE_NOT_REPAYABLE',
      'message','pay_finance_case_restructure: manual credit adjustments are not repayable and cannot be restructured',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method, ''))
  into v_candidate_pay_method
  from public.candidates as c
  where c.id = v_case.candidate_id
  limit 1;

  select exists (
    select 1
    from public.pay_finance_case_components as pfc_block
    where pfc_block.finance_case_id = p_finance_case_id
      and pfc_block.closed_at_utc is null
      and pfc_block.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and round(coalesce(pfc_block.remaining_source_amount, 0), 2) > 0
      and upper(coalesce(pfc_block.source_pay_method, '')) in ('PAYE', 'UMBRELLA')
      and v_candidate_pay_method in ('PAYE', 'UMBRELLA')
      and upper(coalesce(pfc_block.source_pay_method, '')) <> v_candidate_pay_method
      and (
        coalesce(pfc_block.is_resolution_stale, false) = true
        or nullif(btrim(coalesce(pfc_block.saved_target_pay_method, '')), '') is null
        or upper(coalesce(pfc_block.saved_target_pay_method, '')) <> v_candidate_pay_method
      )
  )
  into v_taxable_channel_restructure_required;

  if coalesce(v_taxable_channel_restructure_required, false) = true then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','TAXABLE_CHANNEL_RESTRUCTURE_REQUIRED',
      'message','pay_finance_case_restructure: taxable PAYE/Umbrella channel restructure is required before schedule-only restructure can be applied',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'candidate_pay_method', v_candidate_pay_method
    )::text;
  end if;

  select
    round(coalesce(sum(pfc.remaining_source_amount), 0), 2)::numeric(12,2),
    count(*)::integer
  into
    v_component_remaining_amount,
    v_open_component_count
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  v_remaining_amount := case
    when v_open_component_count > 0 then v_component_remaining_amount
    else round(coalesce(v_case.outstanding_amount,0),2)
  end;

  if v_remaining_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','NO_OUTSTANDING_BALANCE',
      'message','pay_finance_case_restructure: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_RESTRUCTURE',
        'code','WEEKLY_DUE_INVALID',
        'message','pay_finance_case_restructure: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error','PAY_FINANCE_CASE_RESTRUCTURE',
        'code','WEEKS_TOTAL_INVALID',
        'message','pay_finance_case_restructure: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','REPAYMENT_INPUT_REQUIRED',
      'message','pay_finance_case_restructure: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_remaining_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_remaining_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKLY_DUE_INVALID',
      'message','pay_finance_case_restructure: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKS_TOTAL_INVALID',
      'message','pay_finance_case_restructure: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_new_start_week_start := p_start_week_start;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;
  v_new_note := case when p_note is null then v_case.notes else nullif(btrim(coalesce(p_note,'')), '') end;

  v_required_weeks := greatest(ceil(v_remaining_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error','PAY_FINANCE_CASE_RESTRUCTURE',
      'code','WEEKS_TOTAL_TOO_SHORT',
      'message','pay_finance_case_restructure: repayment schedule does not cover the remaining outstanding balance',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total,
      'outstanding_amount', v_remaining_amount
    )::text;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'week_start', (v_new_start_week_start + (gs.i * 7))::date,
        'amount', round(
          -least(
            v_new_weekly_due,
            greatest(v_remaining_amount - (v_new_weekly_due * gs.i), 0)
          ),
          2
        )
      )
      order by (v_new_start_week_start + (gs.i * 7))::date asc
    ),
    '[]'::jsonb
  )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due_week_start
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_remaining_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_before_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'notes', v_case.notes
  );

  update public.pay_advances pa
  set
    outstanding_amount = v_remaining_amount,
    schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
    weekly_due = v_new_weekly_due,
    weeks_total = v_new_weeks_total,
    start_week_start = v_new_start_week_start,
    next_due_week_start = v_new_next_due_week_start,
    minimum_earnings_threshold = v_new_minimum_earnings_threshold,
    take_home_floor_override = v_new_take_home_floor_override,
    notes = v_new_note,
    updated_at = v_now_utc
  where pa.id = p_finance_case_id;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'case_type', v_case.case_type::text,
    'status', v_case.status::text,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'notes', v_case.notes,
    'schedule_input_mode', v_schedule_input_mode
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'RESTRUCTURED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    null::text,
    'Finance case repayment terms restructured'
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'schedule_input_mode', v_schedule_input_mode,
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'component_remaining_amount', v_component_remaining_amount,
    'open_component_count', v_open_component_count,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb)
  );
end;
$$;






create or replace function public.pay_payment_advance_create(
  p_candidate_id uuid,
  p_principal_amount numeric,
  p_weekly_due numeric,
  p_weeks_total int,
  p_start_week_start date,
  p_actor_user_id uuid,
  p_note text default null,
  p_minimum_earnings_threshold numeric default null,
  p_take_home_floor_override numeric default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_pay_date date := (now() at time zone 'Europe/London')::date;

  v_settings record;
  v_candidate record;

  v_schedule_json jsonb := '[]'::jsonb;
  v_next_due date := null;

  v_finance_case_id uuid := null;
  v_finance_component_id uuid := null;

  v_warnings jsonb := '[]'::jsonb;

  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;

  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;

  v_required_weeks int := 0;
  v_pay_channel text := null;
  v_paye_treatment text := 'NONE';

  v_principal_amount_norm numeric(12,2) := 0;
  v_weekly_due_norm numeric(12,2) := null;
  v_weeks_total_norm int := null;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_source_family_key text := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;

  v_taxability public.pay_finance_taxability_enum := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;

  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;

  v_readiness_entity_kind text := 'CANDIDATE';
  v_readiness_entity_id uuid := null;
  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;
  v_readiness_sort_code text := null;
  v_readiness_account_number text := null;
  v_readiness_account_type text := null;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_payment_advance_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_create: actor_user_id is required'
    )::text;
  end if;

  if p_principal_amount is null or round(p_principal_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PRINCIPAL_INVALID',
      'message', 'pay_payment_advance_create: principal_amount must be > 0'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_create: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_create: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_create: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_create: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_principal_amount_norm := round(p_principal_amount,2);
  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKLY_DUE_INVALID',
        'message', 'pay_payment_advance_create: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_payment_advance_create: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'REPAYMENT_INPUT_REQUIRED',
      'message', 'pay_payment_advance_create: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_weeks_total_norm := p_weeks_total;
    v_weekly_due_norm := round((ceil((v_principal_amount_norm / v_weeks_total_norm) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  end if;

  if v_weekly_due_norm is null or v_weekly_due_norm <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_create: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_weeks_total_norm is null or v_weeks_total_norm < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_create: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_principal_amount_norm / v_weekly_due_norm)::int, 1);
  if v_weeks_total_norm < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_create: repayment schedule does not cover the principal amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_weeks_total_norm
    )::text;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_payment_advance_create: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    c.first_name,
    c.last_name,
    c.account_holder,
    c.sort_code,
    c.account_number,
    c.bank_details_hash,
    c.umbrella_id,
    upper(coalesce(c.pay_method,'')) as pay_method
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_payment_advance_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_payment_advance_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_payment_advance_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  v_pay_channel := v_candidate.pay_method;

  if v_pay_channel = 'PAYE' then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;

    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_payment_advance_create: one-off bank fields are not allowed for PAYE loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce(v_candidate.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
    v_readiness_sort_code := v_candidate.sort_code;
    v_readiness_account_number := v_candidate.account_number;
    v_readiness_account_type := 'Personal';
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;

    v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
    v_sort_code_norm := case
      when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
        substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
      else null
    end;
    v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');

    if v_beneficiary_name_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'BENEFICIARY_NAME_REQUIRED',
        'message', 'pay_payment_advance_create: beneficiary_name is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_sort_code_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'SORT_CODE_REQUIRED',
        'message', 'pay_payment_advance_create: valid sort_code is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    if v_account_number_norm is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'ACCOUNT_NUMBER_REQUIRED',
        'message', 'pay_payment_advance_create: valid account_number is required for umbrella loan payouts',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
    if v_oneoff_bank_hash is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_CREATE',
        'code', 'BANK_DETAILS_HASH_FAILED',
        'message', 'pay_payment_advance_create: unable to derive bank_details_hash for umbrella loan payout bank details',
        'candidate_id', p_candidate_id::text
      )::text;
    end if;

    v_readiness_bank_hash := v_oneoff_bank_hash;
    v_readiness_payee_name := v_beneficiary_name_norm;
    v_readiness_sort_code := v_sort_code_norm;
    v_readiness_account_number := v_account_number_norm;
    v_readiness_account_type := 'Personal';
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (p_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_weekly_due_norm,
              greatest(v_principal_amount_norm - (v_weekly_due_norm * gs.i), 0)
            ),
            2
          )
        )
        order by (p_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due
  from (
    select
      (p_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_weekly_due_norm,
          greatest(v_principal_amount_norm - (v_weekly_due_norm * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id,
    taxability,
    routing_kind,
    oneoff_bank_details_required
  )
  values (
    p_candidate_id,
    null::uuid,
    'LOAN'::public.pay_advance_reason_enum,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null::date,
    coalesce(v_schedule_json,'[]'::jsonb),
    v_next_due,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LOAN'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    'PENDING'::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    v_weekly_due_norm,
    v_weeks_total_norm,
    p_start_week_start,
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    null::text,
    null::numeric,
    null::numeric,
    case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid,
    v_taxability,
    v_routing_kind,
    v_oneoff_required
  )
  returning id into v_finance_case_id;

  if v_pay_channel = 'UMBRELLA' then
    insert into public.pay_finance_case_oneoff_payout_bank_details(
      finance_case_id,
      candidate_id,
      beneficiary_name,
      sort_code,
      account_number,
      bank_details_hash,
      note,
      created_at_utc,
      created_by_user_id,
      updated_at_utc,
      updated_by_user_id
    )
    values (
      v_finance_case_id,
      p_candidate_id,
      v_beneficiary_name_norm,
      v_sort_code_norm,
      v_account_number_norm,
      v_oneoff_bank_hash,
      nullif(btrim(coalesce(p_bank_details_note,'')), ''),
      v_now_utc,
      p_actor_user_id,
      v_now_utc,
      p_actor_user_id
    );

    v_oneoff_after := jsonb_build_object(
      'finance_case_id', v_finance_case_id::text,
      'candidate_id', p_candidate_id::text,
      'beneficiary_name', v_beneficiary_name_norm,
      'sort_code_masked', case when v_sort_code_norm is null then null else 'XX-XX-' || right(v_sort_code_norm, 2) end,
      'account_number_masked', case when v_account_number_norm is null then null else lpad(right(v_account_number_norm, 4), length(v_account_number_norm), '*') end,
      'bank_details_hash', v_oneoff_bank_hash,
      'note', nullif(btrim(coalesce(p_bank_details_note,'')), '')
    );

    perform public._audit_insert(
      'finance_case',
      v_finance_case_id::text,
      'ONEOFF_BANK_DETAILS_CREATED',
      v_oneoff_before,
      v_oneoff_after,
      'ONE_OFF_PAYOUT_BANK_DETAILS',
      p_actor_user_id
    );
  end if;

  v_source_family_key := 'case:' || v_finance_case_id::text;
  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'schedule_json', coalesce(v_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  insert into public.pay_finance_case_components (
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    v_source_family_key,
    'CASE_TOTAL',
    'TOTAL',
    'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
    v_candidate.pay_method,
    v_component_source_basis_json,
    v_principal_amount_norm,
    v_principal_amount_norm,
    null,
    null,
    null,
    null,
    null,
    false,
    null,
    0,
    0,
    v_now_utc,
    v_now_utc,
    null,
    null
  )
  returning id into v_finance_component_id;

  v_component_snapshot_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'finance_case_id', v_finance_case_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_candidate.pay_method,
    'target_pay_method', v_candidate.pay_method,
    'source_basis_json', v_component_source_basis_json,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'current_component_fingerprint', public.pay_finance_component_fingerprint(
      p_source_family_key => v_source_family_key,
      p_component_key_type => 'CASE_TOTAL',
      p_component_key_value => 'TOTAL',
      p_classification => 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      p_source_pay_method => v_candidate.pay_method,
      p_current_target_pay_method => v_candidate.pay_method,
      p_source_basis_json => v_component_source_basis_json,
      p_source_amount => v_principal_amount_norm,
      p_relevant_erni_pct => null,
      p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate.pay_method)
    )
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'original_amount', v_principal_amount_norm,
      'outstanding_amount', v_principal_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'payout_pay_batch_id', null,
      'payout_status', 'PENDING',
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'oneoff_bank_details_required', v_oneoff_required,
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'schedule_input_mode', v_schedule_input_mode
    ),
    null::text,
    'Payment Advance created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    v_component_snapshot_json,
    'PAYMENT_ADVANCE_COMPONENT_CREATE',
    'Created non-taxable fixed finance component for Payment Advance principal'
  );

  if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'BLOCKED_BANK_DETAILS',
        'message', case when v_pay_channel = 'PAYE'
                        then 'Candidate bank details are missing; the loan payout will appear as Blocked for Pay until bank details are present.'
                        else 'One-off payout bank details are missing or incomplete; the loan payout will appear as Blocked for Pay until valid bank details are present.' end,
        'candidate_id', p_candidate_id::text
      )
    );
  else
    if v_need_name_check = true then
      select
        coalesce(bnc.status, 'UNVERIFIED') as status,
        (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
      into
        v_bnc_status,
        v_bnc_has_override
      from public.bank_name_checks bnc
      where bnc.rail_provider = v_settings.rail_provider_default
        and bnc.rail_env = v_settings.rail_env_default
        and bnc.entity_kind = v_readiness_entity_kind
        and bnc.entity_id = p_candidate_id
        and bnc.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NAME_CHECK',
            'message', 'Name check has not passed (or override missing) for the payout destination; the loan payout will appear as Blocked for Pay until resolved.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;

    if v_requires_payee_map = true then
      select (bpm.payee_id is not null) as present
      into v_bpm_present
      from public.bank_payee_map bpm
      where bpm.rail_provider = v_settings.rail_provider_default
        and bpm.rail_env = v_settings.rail_env_default
        and bpm.entity_kind = v_readiness_entity_kind
        and bpm.entity_id = p_candidate_id
        and bpm.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bpm_present,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NO_PAYEE_MAP',
            'message', 'Payee map is missing for the payout destination on this rail; the loan payout will appear as Blocked for Pay until payee mapping exists.',
            'candidate_id', p_candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;
  end if;

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_candidate.pay_method,
    'source_amount', v_principal_amount_norm,
    'remaining_source_amount', v_principal_amount_norm,
    'saved_target_pay_method', null,
    'saved_resolution_mode', null,
    'is_resolution_stale', false,
    'stale_reason', null,
    'source_basis_json', v_component_source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'advance_id', v_finance_case_id::text,
    'pay_batch_id', null,
    'pay_date', v_pay_date::text,
    'batch_kind_fixed', null,
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', v_principal_amount_norm,
    'weekly_due', v_weekly_due_norm,
    'weeks_total', v_weeks_total_norm,
    'start_week_start', p_start_week_start::text,
    'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
    'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    'schedule_json', coalesce(v_schedule_json,'[]'::jsonb),
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'oneoff_bank_details_required', v_oneoff_required,
    'oneoff_bank_details_present', case when v_pay_channel = 'UMBRELLA' then true else false end,
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_pay_channel = 'UMBRELLA' then v_beneficiary_name_norm else null end,
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;


create or replace function public.pay_payment_advance_update(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_principal_amount numeric default null,
  p_weekly_due numeric default null,
  p_weeks_total int default null,
  p_start_week_start date default null,
  p_note text default null,
  p_minimum_earnings_threshold numeric default null,
  p_take_home_floor_override numeric default null,
  p_beneficiary_name text default null,
  p_sort_code text default null,
  p_account_number text default null,
  p_bank_details_note text default null,
  p_remove_oneoff_bank_details boolean default false
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_batch public.pay_batches%rowtype;
  v_has_batch boolean := false;
  v_is_committed boolean := false;
  v_has_newflow_draft_item boolean := false;

  v_new_principal numeric(12,2);
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_notes text;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due date := null;
  v_required_weeks int := 0;

  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_can_edit_payout_details boolean := false;
  v_has_principal_change boolean := false;
  v_batch_item_id uuid := null;
  v_pay_batch_candidate_id uuid := null;

  v_schedule_base_amount numeric(12,2) := 0;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_component public.pay_finance_case_components%rowtype;
  v_component_after public.pay_finance_case_components%rowtype;
  v_finance_component_id uuid := null;
  v_component_before_json jsonb := '{}'::jsonb;
  v_component_after_json jsonb := '{}'::jsonb;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_snapshot_json jsonb := '{}'::jsonb;
  v_component_summary_json jsonb := '{}'::jsonb;
  v_component_remaining_amount numeric(12,2) := 0;
  v_source_family_key text := null;

  v_candidate_pay_method text := null;
  v_taxability public.pay_finance_taxability_enum := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_oneoff_required boolean := false;

  v_existing_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;
  v_oneoff_before jsonb := null;
  v_oneoff_after jsonb := null;
  v_beneficiary_name_norm text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_oneoff_bank_hash text := null;
  v_oneoff_change_requested boolean := false;

  v_readiness_bank_hash text := null;
  v_readiness_payee_name text := null;

  v_settings record;
  v_provider text := null;
  v_env text := null;
  v_need_name_check boolean := false;
  v_requires_payee_map boolean := false;
  v_bnc_status text := null;
  v_bnc_has_override boolean := false;
  v_bpm_present boolean := false;
  v_warnings jsonb := '[]'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_payment_advance_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_payment_advance_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_payment_advance_update: Payment Advance not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method,''))
  into v_candidate_pay_method
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate_pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_payment_advance_update: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if v_case.payout_pay_batch_id is not null then
    select pb.*
    into v_batch
    from public.pay_batches pb
    where pb.id = v_case.payout_pay_batch_id
    limit 1;

    v_has_batch := v_batch.id is not null;
  end if;

  if v_has_batch then
    v_is_committed := (
      coalesce(v_batch.authoritative_payment_date is not null, false)
      or upper(coalesce(v_batch.status,'')) in ('SCHEDULED','AWAITING_AUTHORISATION','AUTHORISED_FOR_PAYMENT','EXECUTING','SETTLED','COMPLETED','PARTIAL')
    );
  else
    v_is_committed := false;
  end if;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'LOAN_PAYOUT'
      and pbi.is_voided = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status,'')) <> 'CANCELLED'
  ) into v_has_newflow_draft_item;

  if v_has_batch then
    v_can_edit_payout_details := (v_is_committed = false);
  else
    v_can_edit_payout_details := (v_has_newflow_draft_item = false);
  end if;

  select *
  into v_existing_oneoff
  from public.pay_finance_case_oneoff_payout_bank_details d
  where d.finance_case_id = p_finance_case_id
  for update;

  v_before_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', null,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required
  );

  v_new_principal := coalesce(round(p_principal_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;

  if v_new_minimum_earnings_threshold is not null and v_new_minimum_earnings_threshold < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_payment_advance_update: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if v_new_take_home_floor_override is not null and v_new_take_home_floor_override < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_payment_advance_update: take_home_floor_override must be >= 0'
    )::text;
  end if;

  v_has_principal_change := round(v_new_principal,2) <> round(coalesce(v_case.original_amount,0),2);

  if (not v_can_edit_payout_details) and v_has_principal_change then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'PAYOUT_ALREADY_DRAFTED_OR_COMMITTED',
      'message', 'pay_payment_advance_update: payout principal can only be edited while the item is Not processed yet',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_can_edit_payout_details then
    if v_new_principal <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'PRINCIPAL_INVALID',
        'message', 'pay_payment_advance_update: principal_amount must be > 0'
      )::text;
    end if;
    v_schedule_base_amount := v_new_principal;
  else
    v_schedule_base_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  if p_start_week_start is not null and public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if p_weekly_due is not null and round(p_weekly_due,2) <= 0 and not v_has_weeks_total_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: weekly_due must be > 0 when provided'
    )::text;
  end if;

  if p_weeks_total is not null and p_weeks_total < 1 and not v_has_weekly_due_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: weeks_total must be >= 1 when provided'
    )::text;
  end if;

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    v_schedule_input_mode := 'UNCHANGED';
    v_new_weekly_due := round(coalesce(v_case.weekly_due,0),2);
    v_new_weeks_total := v_case.weeks_total;
  elsif v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_schedule_base_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_payment_advance_update: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_payment_advance_update: normalized weeks_total must be >= 1'
    )::text;
  end if;

  if p_start_week_start is not null then
    v_new_start_week_start := p_start_week_start;
  elsif v_case.next_due_week_start is not null then
    v_new_start_week_start := v_case.next_due_week_start;
  else
    v_new_start_week_start := v_case.start_week_start;
  end if;

  if v_new_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_payment_advance_update: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(v_new_start_week_start) <> v_new_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_payment_advance_update: start_week_start must be a Monday (week start)',
      'start_week_start', v_new_start_week_start::text
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_payment_advance_update: repayment schedule does not cover the remaining amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total
    )::text;
  end if;

  if v_candidate_pay_method = 'PAYE' then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := false;

    if nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
       or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
       or nullif(btrim(coalesce(p_account_number,'')), '') is not null
       or nullif(btrim(coalesce(p_bank_details_note,'')), '') is not null
       or coalesce(p_remove_oneoff_bank_details, false) = true then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_NOT_ALLOWED_FOR_PAYE',
        'message', 'pay_payment_advance_update: one-off bank fields are not allowed for PAYE loan payouts',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if v_existing_oneoff.finance_case_id is not null then
      v_oneoff_before := jsonb_build_object(
        'finance_case_id', p_finance_case_id::text,
        'candidate_id', v_case.candidate_id::text,
        'beneficiary_name', v_existing_oneoff.beneficiary_name,
        'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
        'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
        'bank_details_hash', v_existing_oneoff.bank_details_hash,
        'note', v_existing_oneoff.note
      );

      delete from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      select *
      into v_existing_oneoff
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id;

      perform public._audit_insert(
        'finance_case',
        p_finance_case_id::text,
        'ONEOFF_BANK_DETAILS_REMOVED',
        v_oneoff_before,
        null::jsonb,
        'PAY_METHOD_NOW_PAYE',
        p_actor_user_id
      );
    end if;

    v_readiness_bank_hash := nullif(btrim(coalesce((select c.bank_details_hash from public.candidates c where c.id = v_case.candidate_id limit 1), '')), '');
    v_readiness_payee_name := nullif(btrim(coalesce((select c.account_holder from public.candidates c where c.id = v_case.candidate_id limit 1), (select c.display_name from public.candidates c where c.id = v_case.candidate_id limit 1))), '');
  else
    v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
    v_oneoff_required := true;

    v_oneoff_change_requested := (
      nullif(btrim(coalesce(p_beneficiary_name,'')), '') is not null
      or nullif(btrim(coalesce(p_sort_code,'')), '') is not null
      or nullif(btrim(coalesce(p_account_number,'')), '') is not null
      or p_bank_details_note is not null
      or coalesce(p_remove_oneoff_bank_details, false) = true
    );

    if v_oneoff_change_requested and not v_can_edit_payout_details then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
        'code', 'ONEOFF_BANK_DETAILS_LOCKED',
        'message', 'pay_payment_advance_update: one-off bank details can only be edited while the item is Not processed yet',
        'finance_case_id', p_finance_case_id::text
      )::text;
    end if;

    if coalesce(p_remove_oneoff_bank_details, false) = true then
      if v_existing_oneoff.finance_case_id is not null then
        v_oneoff_before := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        delete from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          'ONEOFF_BANK_DETAILS_REMOVED',
          v_oneoff_before,
          null::jsonb,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := null;
      v_readiness_payee_name := null;
    else
      if v_existing_oneoff.finance_case_id is not null then
        v_beneficiary_name_norm := coalesce(
          nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), ''),
          v_existing_oneoff.beneficiary_name
        );
        v_sort_code_norm := coalesce(
          case
            when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
              substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
            else null
          end,
          v_existing_oneoff.sort_code
        );
        v_account_number_norm := coalesce(
          nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), ''),
          v_existing_oneoff.account_number
        );
      else
        v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name,'')), '\s+', ' ', 'g'), '');
        v_sort_code_norm := case
          when length(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g')) = 6 then
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 1, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 3, 2) || '-' ||
            substr(regexp_replace(coalesce(p_sort_code,''), '[^0-9]', '', 'g'), 5, 2)
          else null
        end;
        v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number,''), '[^0-9]', '', 'g'), '');
      end if;

      if v_beneficiary_name_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'BENEFICIARY_NAME_REQUIRED',
          'message', 'pay_payment_advance_update: beneficiary_name is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_sort_code_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'SORT_CODE_REQUIRED',
          'message', 'pay_payment_advance_update: valid sort_code is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_account_number_norm is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'ACCOUNT_NUMBER_REQUIRED',
          'message', 'pay_payment_advance_update: valid account_number is required for umbrella loan payouts',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      v_oneoff_bank_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);
      if v_oneoff_bank_hash is null then
        raise exception '%', jsonb_build_object(
          'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
          'code', 'BANK_DETAILS_HASH_FAILED',
          'message', 'pay_payment_advance_update: unable to derive bank_details_hash for umbrella loan payout bank details',
          'finance_case_id', p_finance_case_id::text
        )::text;
      end if;

      if v_can_edit_payout_details then
        v_oneoff_before := case
          when v_existing_oneoff.finance_case_id is null then null
          else jsonb_build_object(
            'finance_case_id', p_finance_case_id::text,
            'candidate_id', v_case.candidate_id::text,
            'beneficiary_name', v_existing_oneoff.beneficiary_name,
            'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
            'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
            'bank_details_hash', v_existing_oneoff.bank_details_hash,
            'note', v_existing_oneoff.note
          )
        end;

        insert into public.pay_finance_case_oneoff_payout_bank_details(
          finance_case_id,
          candidate_id,
          beneficiary_name,
          sort_code,
          account_number,
          bank_details_hash,
          note,
          created_at_utc,
          created_by_user_id,
          updated_at_utc,
          updated_by_user_id
        )
        values (
          p_finance_case_id,
          v_case.candidate_id,
          v_beneficiary_name_norm,
          v_sort_code_norm,
          v_account_number_norm,
          v_oneoff_bank_hash,
          case when p_bank_details_note is null then coalesce(v_existing_oneoff.note, null) else nullif(btrim(coalesce(p_bank_details_note,'')), '') end,
          v_now_utc,
          p_actor_user_id,
          v_now_utc,
          p_actor_user_id
        )
        on conflict (finance_case_id) do update
        set candidate_id = excluded.candidate_id,
            beneficiary_name = excluded.beneficiary_name,
            sort_code = excluded.sort_code,
            account_number = excluded.account_number,
            bank_details_hash = excluded.bank_details_hash,
            note = excluded.note,
            updated_at_utc = excluded.updated_at_utc,
            updated_by_user_id = excluded.updated_by_user_id;

        select *
        into v_existing_oneoff
        from public.pay_finance_case_oneoff_payout_bank_details d
        where d.finance_case_id = p_finance_case_id;

        v_oneoff_after := jsonb_build_object(
          'finance_case_id', p_finance_case_id::text,
          'candidate_id', v_case.candidate_id::text,
          'beneficiary_name', v_existing_oneoff.beneficiary_name,
          'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
          'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
          'bank_details_hash', v_existing_oneoff.bank_details_hash,
          'note', v_existing_oneoff.note
        );

        perform public._audit_insert(
          'finance_case',
          p_finance_case_id::text,
          case when v_oneoff_before is null then 'ONEOFF_BANK_DETAILS_CREATED' else 'ONEOFF_BANK_DETAILS_UPDATED' end,
          v_oneoff_before,
          v_oneoff_after,
          'ONE_OFF_PAYOUT_BANK_DETAILS',
          p_actor_user_id
        );
      end if;

      v_readiness_bank_hash := v_oneoff_bank_hash;
      v_readiness_payee_name := v_beneficiary_name_norm;
    end if;
  end if;

  select
    sd.banking_system,
    sd.external_paye_system,
    sd.rail_provider_default,
    sd.rail_env_default,
    sd.rail_supports_name_check
  into v_settings
  from public.settings_defaults sd
  where sd.id = 1
  limit 1;

  if v_settings.banking_system is null or v_settings.external_paye_system is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_PAYMENT_ADVANCE_UPDATE',
      'code', 'SETTINGS_DEFAULTS_MISSING',
      'message', 'pay_payment_advance_update: settings_defaults missing required banking defaults (id=1)'
    )::text;
  end if;

  v_provider := upper(btrim(coalesce(v_settings.rail_provider_default,'CSV')));
  v_env := upper(btrim(coalesce(v_settings.rail_env_default,'PROD')));
  v_need_name_check := (coalesce(v_settings.rail_supports_name_check,false) = true) and (v_provider <> 'CSV');
  v_requires_payee_map := (v_provider <> 'CSV');

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_new_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_new_weekly_due,
              greatest(v_schedule_base_amount - (v_new_weekly_due * gs.i), 0)
            ),
            2
          )
        )
        order by (v_new_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_schedule_base_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_source_family_key := 'case:' || p_finance_case_id::text;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.source_family_key = v_source_family_key
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
    and pfc.closed_at_utc is null
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'PAYMENT_ADVANCE',
      'advance_kind', 'LOAN',
      'principal_amount', v_new_principal,
      'weekly_due', v_new_weekly_due,
      'weeks_total', v_new_weeks_total,
      'start_week_start', v_new_start_week_start::text,
      'next_due_week_start', case when v_new_next_due is null then null else v_new_next_due::text end,
      'schedule_json', coalesce(v_new_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', v_new_minimum_earnings_threshold,
      'take_home_floor_override', v_new_take_home_floor_override,
      'note', v_new_notes
    )
  );

  if v_component.id is null then
    insert into public.pay_finance_case_components (
      finance_case_id,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      source_pay_method,
      source_basis_json,
      source_amount,
      remaining_source_amount,
      saved_target_pay_method,
      saved_resolution_mode,
      saved_resolution_payload_json,
      saved_resolution_result_json,
      resolution_fingerprint,
      is_resolution_stale,
      stale_reason,
      allocation_priority_group,
      allocation_priority_order,
      created_at_utc,
      updated_at_utc,
      resolved_at_utc,
      closed_at_utc
    )
    values (
      p_finance_case_id,
      v_case.candidate_id,
      v_case.client_id,
      v_case.linked_timesheet_id,
      v_source_family_key,
      'CASE_TOTAL',
      'TOTAL',
      'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      v_candidate_pay_method,
      v_component_source_basis_json,
      v_new_principal,
      case when v_can_edit_payout_details then v_new_principal else round(coalesce(v_case.outstanding_amount,0),2) end,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      0,
      0,
      v_now_utc,
      v_now_utc,
      null,
      null
    )
    returning * into v_component;
  end if;

  if v_can_edit_payout_details then
    v_component_remaining_amount := v_new_principal;
  else
    v_component_remaining_amount := round(coalesce(v_case.outstanding_amount,0),2);
  end if;

  v_component_before_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  update public.pay_finance_case_components pfc
  set
    candidate_id = v_case.candidate_id,
    client_id = v_case.client_id,
    linked_timesheet_id = v_case.linked_timesheet_id,
    classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
    source_pay_method = v_candidate_pay_method,
    source_basis_json = v_component_source_basis_json,
    source_amount = v_new_principal,
    remaining_source_amount = v_component_remaining_amount,
    saved_target_pay_method = null,
    saved_resolution_mode = null,
    saved_resolution_payload_json = null,
    saved_resolution_result_json = null,
    resolution_fingerprint = null,
    is_resolution_stale = false,
    stale_reason = null,
    allocation_priority_group = 0,
    allocation_priority_order = 0,
    updated_at_utc = v_now_utc
  where pfc.id = v_component.id
  returning * into v_component_after;

  v_finance_component_id := v_component_after.id;

  update public.pay_advances pa
  set
    original_amount = case when v_can_edit_payout_details then v_new_principal else pa.original_amount end,
    outstanding_amount = case when v_can_edit_payout_details then v_new_principal else pa.outstanding_amount end,
    schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
    next_due_week_start = v_new_next_due,
    notes = v_new_notes,
    weekly_due = v_new_weekly_due,
    weeks_total = v_new_weeks_total,
    start_week_start = v_new_start_week_start,
    minimum_earnings_threshold = v_new_minimum_earnings_threshold,
    take_home_floor_override = v_new_take_home_floor_override,
    updated_at = v_now_utc,
    taxability = v_taxability,
    routing_kind = v_routing_kind,
    oneoff_bank_details_required = v_oneoff_required
  where pa.id = p_finance_case_id;

  if v_can_edit_payout_details and v_has_batch then
    select pbc.id
    into v_pay_batch_candidate_id
    from public.pay_batch_candidates pbc
    where pbc.pay_batch_id = v_batch.id
      and pbc.candidate_id = v_case.candidate_id
    limit 1;

    select pbi.id
    into v_batch_item_id
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc2
      on pbc2.id = pbi.pay_batch_candidate_id
    where pbc2.pay_batch_id = v_batch.id
      and pbc2.candidate_id = v_case.candidate_id
      and pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'LOAN_PAYOUT'
      and pbi.is_voided = false
    limit 1;

    if v_pay_batch_candidate_id is not null then
      update public.pay_batch_candidates pbc
      set gross_preview = v_new_principal,
          net_bank_amount = v_new_principal,
          updated_at = v_now_utc
      where pbc.id = v_pay_batch_candidate_id;
    end if;

    v_component_snapshot_json := jsonb_build_object(
      'finance_component_id', v_finance_component_id::text,
      'finance_case_id', p_finance_case_id::text,
      'source_family_key', v_source_family_key,
      'component_key_type', 'CASE_TOTAL',
      'component_key_value', 'TOTAL',
      'classification', 'REIMBURSEMENT_GROSS_FIXED',
      'source_pay_method', v_candidate_pay_method,
      'target_pay_method', v_candidate_pay_method,
      'source_basis_json', v_component_source_basis_json,
      'source_amount', v_new_principal,
      'remaining_source_amount', v_component_remaining_amount,
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
      'saved_resolution_payload_json', v_component_after.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component_after.saved_resolution_result_json,
      'current_component_fingerprint', public.pay_finance_component_fingerprint(
        p_source_family_key => v_source_family_key,
        p_component_key_type => 'CASE_TOTAL',
        p_component_key_value => 'TOTAL',
        p_classification => 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
        p_source_pay_method => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json => v_component_source_basis_json,
        p_source_amount => v_new_principal,
        p_relevant_erni_pct => null,
        p_target_basis_json => jsonb_build_object('current_target_pay_method', v_candidate_pay_method)
      )
    );

    if v_batch_item_id is not null then
      update public.pay_batch_items pbi
      set description = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          updated_at = v_now_utc,
          finance_case_id = p_finance_case_id,
          reservation_id = null,
          paye_treatment = 'NONE',
          finance_component_id = v_finance_component_id,
          frozen_component_snapshot_json = v_component_snapshot_json,
          frozen_component_key_type = 'CASE_TOTAL',
          frozen_component_key_value = 'TOTAL',
          frozen_component_classification = 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
          frozen_source_basis_json = v_component_source_basis_json,
          frozen_source_pay_method = v_candidate_pay_method,
          frozen_target_pay_method = v_candidate_pay_method,
          frozen_resolution_mode = v_component_after.saved_resolution_mode,
          frozen_resolution_payload_json = v_component_after.saved_resolution_payload_json,
          frozen_resolution_result_json = v_component_after.saved_resolution_result_json,
          frozen_source_amount = v_new_principal,
          frozen_target_amount_ex_vat = v_new_principal,
          frozen_target_amount_vat = 0,
          frozen_target_amount_inc_vat = v_new_principal,
          payout_instruction_snapshot_json = case
            when v_candidate_pay_method = 'UMBRELLA' and v_existing_oneoff.finance_case_id is not null then
              jsonb_build_object(
                'taxability', 'NON_TAXABLE',
                'routing_kind', 'ONE_OFF_SPECIFIED_BANK_ACCOUNT',
                'destination_label', 'one-off specified bank account',
                'pay_channel', 'UMBRELLA',
                'payee_entity_kind', 'CANDIDATE',
                'payee_entity_id', v_case.candidate_id::text,
                'beneficiary_name', v_existing_oneoff.beneficiary_name,
                'sort_code_masked', case when v_existing_oneoff.sort_code is null then null else 'XX-XX-' || right(v_existing_oneoff.sort_code, 2) end,
                'account_number_masked', case when v_existing_oneoff.account_number is null then null else lpad(right(v_existing_oneoff.account_number, 4), length(v_existing_oneoff.account_number), '*') end,
                'bank_details_hash', v_existing_oneoff.bank_details_hash,
                'bank_details_note', v_existing_oneoff.note,
                'appears_on_umbrella_remittance', false,
                'generates_candidate_payment_advice', true
              )
            else null
          end
      where pbi.id = v_batch_item_id;

      update public.pay_batch_item_breakdowns pbib
      set unit_name = 'Payment Advance',
          amount_ex_vat = v_new_principal,
          amount_vat = 0,
          amount_inc_vat = v_new_principal,
          meta_json = jsonb_build_object(
            'case_type', 'PAYMENT_ADVANCE',
            'worker_label', 'Payment Advance'
          )
      where pbib.pay_batch_item_id = v_batch_item_id;
    end if;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  if v_candidate_pay_method = 'PAYE' then
    v_readiness_bank_hash := nullif(btrim(coalesce((select c.bank_details_hash from public.candidates c where c.id = v_case.candidate_id limit 1), '')), '');
    v_readiness_payee_name := nullif(btrim(coalesce((select c.account_holder from public.candidates c where c.id = v_case.candidate_id limit 1), (select c.display_name from public.candidates c where c.id = v_case.candidate_id limit 1))), '');
  elsif v_existing_oneoff.finance_case_id is not null then
    v_readiness_bank_hash := nullif(btrim(coalesce(v_existing_oneoff.bank_details_hash,'')), '');
    v_readiness_payee_name := nullif(btrim(coalesce(v_existing_oneoff.beneficiary_name,'')), '');
  else
    v_readiness_bank_hash := null;
    v_readiness_payee_name := null;
  end if;

  if v_readiness_bank_hash is null or btrim(coalesce(v_readiness_bank_hash,'')) = '' then
    v_warnings := v_warnings || jsonb_build_array(
      jsonb_build_object(
        'code', 'BLOCKED_BANK_DETAILS',
        'message', case when v_candidate_pay_method = 'PAYE'
                        then 'Candidate bank details are missing; the loan payout will appear as Blocked for Pay until bank details are present.'
                        else 'One-off payout bank details are missing or incomplete; the loan payout will appear as Blocked for Pay until valid bank details are present.' end,
        'candidate_id', v_case.candidate_id::text
      )
    );
  else
    if v_need_name_check = true then
      select
        coalesce(bnc.status, 'UNVERIFIED') as status,
        (bnc.override_reason is not null and bnc.override_hash = v_readiness_bank_hash) as has_override
      into
        v_bnc_status,
        v_bnc_has_override
      from public.bank_name_checks bnc
      where bnc.rail_provider = v_settings.rail_provider_default
        and bnc.rail_env = v_settings.rail_env_default
        and bnc.entity_kind = 'CANDIDATE'
        and bnc.entity_id = v_case.candidate_id
        and bnc.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bnc_status,'UNVERIFIED') <> 'PASS' and coalesce(v_bnc_has_override,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NAME_CHECK',
            'message', 'Name check has not passed (or override missing) for the payout destination; the loan payout will appear as Blocked for Pay until resolved.',
            'candidate_id', v_case.candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;

    if v_requires_payee_map = true then
      select (bpm.payee_id is not null) as present
      into v_bpm_present
      from public.bank_payee_map bpm
      where bpm.rail_provider = v_settings.rail_provider_default
        and bpm.rail_env = v_settings.rail_env_default
        and bpm.entity_kind = 'CANDIDATE'
        and bpm.entity_id = v_case.candidate_id
        and bpm.bank_details_hash = v_readiness_bank_hash
      limit 1;

      if coalesce(v_bpm_present,false) = false then
        v_warnings := v_warnings || jsonb_build_array(
          jsonb_build_object(
            'code', 'BLOCKED_NO_PAYEE_MAP',
            'message', 'Payee map is missing for the payout destination on this rail; the loan payout will appear as Blocked for Pay until payee mapping exists.',
            'candidate_id', v_case.candidate_id::text,
            'rail_provider', v_settings.rail_provider_default,
            'rail_env', v_settings.rail_env_default
          )
        );
      end if;
    end if;
  end if;

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', v_schedule_input_mode,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required
  );

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component_after.id::text,
    'classification', v_component_after.classification::text,
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_before_json,
    v_after_json,
    null::text,
    case when v_can_edit_payout_details then 'Payment Advance payout details updated while Not processed yet' else 'Payment Advance future repayment terms updated after draft/commit' end
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_finance_component_id,
    'COMPONENT_UPDATED',
    v_now_utc,
    p_actor_user_id,
    case when v_batch.id is null then null else v_batch.id end,
    v_component_before_json,
    v_component_after_json,
    'PAYMENT_ADVANCE_COMPONENT_UPDATED',
    'Updated Payment Advance non-taxable fixed component state'
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', v_source_family_key,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', 'REIMBURSEMENT_GROSS_FIXED',
    'source_pay_method', v_component_after.source_pay_method,
    'source_amount', round(coalesce(v_component_after.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount,0),2),
    'saved_target_pay_method', v_component_after.saved_target_pay_method,
    'saved_resolution_mode', case when v_component_after.saved_resolution_mode is null then null else v_component_after.saved_resolution_mode::text end,
    'is_resolution_stale', v_component_after.is_resolution_stale,
    'stale_reason', v_component_after.stale_reason,
    'source_basis_json', v_component_after.source_basis_json
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'advance_id', p_finance_case_id::text,
    'case_type', 'PAYMENT_ADVANCE',
    'worker_label', 'Payment Advance',
    'repayment_label', 'Payment Advance Repayment',
    'payout_editable', v_can_edit_payout_details,
    'pay_batch_id', case when v_batch.id is null then null else v_batch.id::text end,
    'schedule_input_mode', v_schedule_input_mode,
    'principal_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', v_case.oneoff_bank_details_required,
    'oneoff_bank_details_present', exists(
      select 1
      from public.pay_finance_case_oneoff_payout_bank_details d
      where d.finance_case_id = p_finance_case_id
    ),
    'bank_details_hash', v_readiness_bank_hash,
    'beneficiary_name', case when v_existing_oneoff.finance_case_id is null then null else v_existing_oneoff.beneficiary_name end,
    'finance_component_id', v_finance_component_id::text,
    'component_summary', v_component_summary_json,
    'warnings', v_warnings
  );
end;
$$;


DROP FUNCTION IF EXISTS public.pay_manual_debt_adjustment_create(
  uuid,
  numeric,
  numeric,
  int,
  date,
  uuid,
  text,
  text,
  numeric,
  numeric
);

CREATE OR REPLACE FUNCTION public.pay_manual_debt_adjustment_create(
  p_candidate_id uuid,
  p_amount numeric,
  p_weekly_due numeric,
  p_weeks_total int,
  p_start_week_start date,
  p_actor_user_id uuid,
  p_adjustment_comment text,
  p_note text default null,
  p_minimum_earnings_threshold numeric default null,
  p_take_home_floor_override numeric default null,
  p_taxability text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_candidate record;
  v_finance_case_id uuid := null;
  v_finance_component_id uuid := null;
  v_schedule_json jsonb := '[]'::jsonb;
  v_next_due date := null;
  v_required_weeks int := 0;

  v_amount_norm numeric(12,2) := 0;
  v_weekly_due_norm numeric(12,2) := null;
  v_weeks_total_norm int := null;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;

  v_taxability public.pay_finance_taxability_enum := null;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_component_classification public.pay_finance_component_classification_enum := null;
  v_paye_treatment text := 'NONE';
  v_oneoff_required boolean := false;

  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_resolution_fingerprint text := null;
  v_component_summary_json jsonb := '{}'::jsonb;
begin
  if p_candidate_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: candidate_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: actor_user_id is required'
    )::text;
  end if;

  if p_amount is null or round(p_amount,2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_debt_adjustment_create: amount must be > 0'
    )::text;
  end if;

  if p_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_manual_debt_adjustment_create: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  if nullif(btrim(coalesce(p_adjustment_comment,'')), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: adjustment_comment is required'
    )::text;
  end if;

  if p_minimum_earnings_threshold is not null and round(p_minimum_earnings_threshold,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_manual_debt_adjustment_create: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if p_take_home_floor_override is not null and round(p_take_home_floor_override,2) < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_manual_debt_adjustment_create: take_home_floor_override must be >= 0'
    )::text;
  end if;

  if p_taxability is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: taxability is required'
    )::text;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_debt_adjustment_create: taxability must be TAXABLE or NON_TAXABLE',
      'taxability', p_taxability
    )::text;
  end if;

  v_amount_norm := round(p_amount,2);
  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    if p_weekly_due is not null and round(p_weekly_due,2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
        'code', 'WEEKLY_DUE_INVALID',
        'message', 'pay_manual_debt_adjustment_create: weekly_due must be > 0 when provided'
      )::text;
    end if;

    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_manual_debt_adjustment_create: weeks_total must be >= 1 when provided'
      )::text;
    end if;

    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'REPAYMENT_INPUT_REQUIRED',
      'message', 'pay_manual_debt_adjustment_create: supply either weekly_due or weeks_total'
    )::text;
  end if;

  if v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_weeks_total_norm := p_weeks_total;
    v_weekly_due_norm := round((ceil((v_amount_norm / v_weeks_total_norm) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_weekly_due_norm := round(p_weekly_due,2);
    v_weeks_total_norm := greatest(ceil(v_amount_norm / v_weekly_due_norm)::int, 1);
  end if;

  if v_weekly_due_norm is null or v_weekly_due_norm <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_manual_debt_adjustment_create: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_weeks_total_norm is null or v_weeks_total_norm < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_manual_debt_adjustment_create: normalized weeks_total must be >= 1'
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_amount_norm / v_weekly_due_norm)::int, 1);
  if v_weeks_total_norm < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_manual_debt_adjustment_create: repayment schedule does not cover the debt amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_weeks_total_norm
    )::text;
  end if;

  select
    c.id,
    c.active,
    c.tms_ref,
    c.display_name,
    upper(coalesce(c.pay_method,'')) as pay_method
  into v_candidate
  from public.candidates c
  where c.id = p_candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_create: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if coalesce(v_candidate.active,false) = false then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'CANDIDATE_INACTIVE',
      'message', 'pay_manual_debt_adjustment_create: candidate is not active',
      'candidate_id', p_candidate_id::text
    )::text;
  end if;

  if v_candidate.pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_CREATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_create: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  end if;

  if v_candidate.pay_method = 'PAYE' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_DEDUCT';
  elsif v_candidate.pay_method = 'PAYE' and v_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NET_DEDUCT';
  elsif v_candidate.pay_method = 'UMBRELLA' and v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
  else
    v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (p_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_weekly_due_norm,
              greatest(v_amount_norm - (v_weekly_due_norm * gs.i), 0)
            ),
            2
          )
        )
        order by (p_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_schedule_json
  from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs(i);

  select min(x.week_start)
  into v_next_due
  from (
    select
      (p_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_weekly_due_norm,
          greatest(v_amount_norm - (v_weekly_due_norm * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_weeks_total_norm,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  insert into public.pay_advances(
    candidate_id,
    client_id,
    reason,
    original_amount,
    outstanding_amount,
    linked_shift_date,
    schedule_json,
    next_due_week_start,
    status,
    best_guess_hours,
    notes,
    created_at,
    created_by,
    updated_at,
    advance_kind,
    linked_timesheet_id,
    baseline_signature,
    payout_status,
    payout_pay_batch_id,
    payout_transfer_id,
    weekly_due,
    weeks_total,
    start_week_start,
    case_type,
    adjustment_comment,
    source_original_paid_amount,
    source_corrected_paid_amount,
    minimum_earnings_threshold,
    take_home_floor_override,
    written_off_at_utc,
    written_off_by_user_id,
    write_off_reason,
    cleared_at_utc,
    cleared_by_user_id,
    taxability,
    routing_kind,
    oneoff_bank_details_required
  )
  values (
    p_candidate_id,
    null::uuid,
    'MANUAL_ADVANCE'::public.pay_advance_reason_enum,
    v_amount_norm,
    v_amount_norm,
    null::date,
    coalesce(v_schedule_json,'[]'::jsonb),
    v_next_due,
    'ACTIVE'::public.pay_advance_status_enum,
    null::jsonb,
    nullif(btrim(coalesce(p_note,'')), ''),
    v_now_utc,
    p_actor_user_id,
    v_now_utc,
    'LEGACY_ADVANCE'::public.pay_advance_kind_enum,
    null::uuid,
    null::text,
    null::public.pay_advance_payout_status_enum,
    null::uuid,
    null::uuid,
    v_weekly_due_norm,
    v_weeks_total_norm,
    p_start_week_start,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum,
    nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
    null::numeric,
    null::numeric,
    case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    null::timestamptz,
    null::uuid,
    null::text,
    null::timestamptz,
    null::uuid,
    v_taxability,
    v_routing_kind,
    false
  )
  returning id into v_finance_case_id;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'MANUAL_DEBT_ADJUSTMENT',
      'amount', v_amount_norm,
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'paye_treatment', v_paye_treatment,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'schedule_json', coalesce(v_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'note', nullif(btrim(coalesce(p_note,'')), '')
    )
  );

  if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
    v_component_resolution_payload_json := jsonb_build_object(
      'same_channel', true,
      'target_amount', v_amount_norm,
      'target_pay_method', v_candidate.pay_method
    );

    v_component_resolution_result_json := jsonb_build_object(
      'target_amount', v_amount_norm,
      'target_amount_ex_vat', v_amount_norm,
      'target_amount_vat', 0,
      'target_amount_inc_vat', v_amount_norm,
      'target_pay_method', v_candidate.pay_method
    );

    v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => 'case:' || v_finance_case_id::text,
      p_component_key_type        => 'CASE_TOTAL',
      p_component_key_value       => 'TOTAL',
      p_classification            => 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
      p_source_pay_method         => v_candidate.pay_method,
      p_current_target_pay_method => v_candidate.pay_method,
      p_source_basis_json         => v_component_source_basis_json,
      p_source_amount             => v_amount_norm,
      p_relevant_erni_pct         => null::numeric,
      p_target_basis_json         => jsonb_build_object('same_channel', true)
    );
  else
    v_component_resolution_payload_json := null;
    v_component_resolution_result_json := null;
    v_component_resolution_fingerprint := null;
  end if;

  insert into public.pay_finance_case_components(
    finance_case_id,
    candidate_id,
    client_id,
    linked_timesheet_id,
    source_family_key,
    component_key_type,
    component_key_value,
    classification,
    source_pay_method,
    source_basis_json,
    source_amount,
    remaining_source_amount,
    saved_target_pay_method,
    saved_resolution_mode,
    saved_resolution_payload_json,
    saved_resolution_result_json,
    resolution_fingerprint,
    is_resolution_stale,
    stale_reason,
    allocation_priority_group,
    allocation_priority_order,
    created_at_utc,
    updated_at_utc,
    resolved_at_utc,
    closed_at_utc
  )
  values (
    v_finance_case_id,
    p_candidate_id,
    null::uuid,
    null::uuid,
    'case:' || v_finance_case_id::text,
    'CASE_TOTAL',
    'TOTAL',
    v_component_classification,
    v_candidate.pay_method,
    v_component_source_basis_json,
    v_amount_norm,
    v_amount_norm,
    case
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then v_candidate.pay_method
      else null
    end,
    case
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
      else null
    end,
    v_component_resolution_payload_json,
    v_component_resolution_result_json,
    v_component_resolution_fingerprint,
    false,
    null::text,
    0,
    0,
    v_now_utc,
    v_now_utc,
    case
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then v_now_utc
      else null::timestamptz
    end,
    null::timestamptz
  )
  returning id into v_finance_component_id;

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_finance_component_id::text,
    'source_family_key', 'case:' || v_finance_case_id::text,
    'component_key_type', 'CASE_TOTAL',
    'component_key_value', 'TOTAL',
    'classification', v_component_classification::text,
    'source_pay_method', v_candidate.pay_method,
    'saved_target_pay_method', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then v_candidate.pay_method else null end,
    'saved_resolution_mode', case when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then 'MANUAL_AMOUNT' else null end,
    'source_amount', v_amount_norm,
    'remaining_source_amount', v_amount_norm,
    'is_resolution_stale', false,
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'paye_treatment', v_paye_treatment
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    null::uuid,
    'CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    jsonb_build_object(
      'case_type', 'MANUAL_DEBT_ADJUSTMENT',
      'original_amount', v_amount_norm,
      'outstanding_amount', v_amount_norm,
      'weekly_due', v_weekly_due_norm,
      'weeks_total', v_weeks_total_norm,
      'start_week_start', p_start_week_start::text,
      'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
      'adjustment_comment', nullif(btrim(coalesce(p_adjustment_comment,'')), ''),
      'paye_treatment', v_paye_treatment,
      'taxability', v_taxability::text,
      'routing_kind', v_routing_kind::text,
      'oneoff_bank_details_required', false,
      'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
      'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
      'schedule_input_mode', v_schedule_input_mode,
      'component_summary', v_component_summary_json
    ),
    null::text,
    'Manual debt adjustment created'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    v_finance_case_id,
    v_finance_component_id,
    'COMPONENT_CREATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    null::jsonb,
    v_component_summary_json,
    'MANUAL_DEBT_ADJUSTMENT_CREATE',
    case
      when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then 'Created taxable total component for manual debt adjustment'
      else 'Created non-taxable fixed recovery component for manual debt adjustment'
    end
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', v_finance_case_id::text,
    'finance_component_id', v_finance_component_id::text,
    'case_type', 'MANUAL_DEBT_ADJUSTMENT',
    'worker_label', 'Manual debt adjustment',
    'recovery_label', 'Manual debt adjustment recovery',
    'paye_treatment', v_paye_treatment,
    'schedule_input_mode', v_schedule_input_mode,
    'amount', v_amount_norm,
    'outstanding_amount', v_amount_norm,
    'weekly_due', v_weekly_due_norm,
    'weeks_total', v_weeks_total_norm,
    'start_week_start', p_start_week_start::text,
    'next_due_week_start', case when v_next_due is null then null else v_next_due::text end,
    'minimum_earnings_threshold', case when p_minimum_earnings_threshold is null then null else round(p_minimum_earnings_threshold,2) end,
    'take_home_floor_override', case when p_take_home_floor_override is null then null else round(p_take_home_floor_override,2) end,
    'schedule_json', coalesce(v_schedule_json,'[]'::jsonb),
    'taxability', v_taxability::text,
    'routing_kind', v_routing_kind::text,
    'oneoff_bank_details_required', false,
    'component_summary', v_component_summary_json
  );
end;
$$;

DROP FUNCTION IF EXISTS public.pay_manual_debt_adjustment_update(
  uuid,
  uuid,
  numeric,
  numeric,
  int,
  date,
  text,
  text,
  numeric,
  numeric
);

CREATE OR REPLACE FUNCTION public.pay_manual_debt_adjustment_update(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_amount numeric default null,
  p_weekly_due numeric default null,
  p_weeks_total int default null,
  p_start_week_start date default null,
  p_adjustment_comment text default null,
  p_note text default null,
  p_minimum_earnings_threshold numeric default null,
  p_take_home_floor_override numeric default null,
  p_taxability text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now_utc timestamptz := now();
  v_case public.pay_advances%rowtype;
  v_candidate_pay_method text := null;
  v_component public.pay_finance_case_components%rowtype;
  v_has_component boolean := false;
  v_component_created boolean := false;
  v_component_before_json jsonb := null;
  v_component_after_json jsonb := null;
  v_component_source_basis_json jsonb := '{}'::jsonb;
  v_component_resolution_fingerprint text := null;
  v_component_resolution_payload_json jsonb := null;
  v_component_resolution_result_json jsonb := null;
  v_component_is_resolution_stale boolean := false;
  v_component_stale_reason text := null;
  v_source_basis_changed boolean := false;

  v_current_taxability public.pay_finance_taxability_enum := null;
  v_requested_taxability public.pay_finance_taxability_enum := null;
  v_current_routing_kind public.pay_finance_routing_kind_enum := null;
  v_requested_routing_kind public.pay_finance_routing_kind_enum := null;
  v_component_classification public.pay_finance_component_classification_enum := null;
  v_paye_treatment text := 'NONE';
  v_taxability_changed boolean := false;
  v_has_active_batch_item boolean := false;

  v_new_original_amount numeric(12,2);
  v_new_outstanding_amount numeric(12,2);
  v_new_weekly_due numeric(12,2);
  v_new_weeks_total int;
  v_new_start_week_start date;
  v_new_adjustment_comment text;
  v_new_notes text;
  v_new_minimum_earnings_threshold numeric(12,2);
  v_new_take_home_floor_override numeric(12,2);
  v_new_schedule_json jsonb := '[]'::jsonb;
  v_new_next_due date := null;
  v_recovered_amount numeric(12,2) := 0;
  v_required_weeks int := 0;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;

  v_schedule_base_amount numeric(12,2) := 0;
  v_schedule_input_mode text := null;
  v_has_weekly_due_input boolean := false;
  v_has_weeks_total_input boolean := false;
  v_component_summary_json jsonb := '{}'::jsonb;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_update: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_update: actor_user_id is required'
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
    and pa.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_update: Manual debt adjustment not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select upper(coalesce(c.pay_method, ''))
  into v_candidate_pay_method
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate_pay_method not in ('PAYE','UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_update: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  if p_adjustment_comment is not null and nullif(btrim(coalesce(p_adjustment_comment,'')), '') is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'ADJUSTMENT_COMMENT_REQUIRED',
      'message', 'pay_manual_debt_adjustment_update: adjustment_comment is required'
    )::text;
  end if;

  v_recovered_amount := round(greatest(coalesce(v_case.original_amount,0) - coalesce(v_case.outstanding_amount,0), 0), 2);
  v_new_original_amount := coalesce(round(p_amount,2), round(coalesce(v_case.original_amount,0),2));
  v_new_adjustment_comment := case when p_adjustment_comment is null then v_case.adjustment_comment else nullif(btrim(p_adjustment_comment), '') end;
  v_new_notes := case when p_note is null then v_case.notes else nullif(btrim(p_note), '') end;
  v_new_minimum_earnings_threshold := case when p_minimum_earnings_threshold is null then v_case.minimum_earnings_threshold else round(p_minimum_earnings_threshold,2) end;
  v_new_take_home_floor_override := case when p_take_home_floor_override is null then v_case.take_home_floor_override else round(p_take_home_floor_override,2) end;

  if p_amount is not null and v_new_original_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'AMOUNT_INVALID',
      'message', 'pay_manual_debt_adjustment_update: amount must be > 0'
    )::text;
  end if;

  if p_amount is not null and v_new_original_amount < v_recovered_amount then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'AMOUNT_BELOW_RECOVERED',
      'message', 'pay_manual_debt_adjustment_update: amount cannot be reduced below already recovered total',
      'recovered_amount', v_recovered_amount,
      'requested_amount', v_new_original_amount
    )::text;
  end if;

  if v_new_minimum_earnings_threshold is not null and v_new_minimum_earnings_threshold < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'MINIMUM_EARNINGS_THRESHOLD_INVALID',
      'message', 'pay_manual_debt_adjustment_update: minimum_earnings_threshold must be >= 0'
    )::text;
  end if;

  if v_new_take_home_floor_override is not null and v_new_take_home_floor_override < 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'TAKE_HOME_FLOOR_INVALID',
      'message', 'pay_manual_debt_adjustment_update: take_home_floor_override must be >= 0'
    )::text;
  end if;

  if p_start_week_start is not null and public._pay_week_start_monday(p_start_week_start) <> p_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_manual_debt_adjustment_update: start_week_start must be a Monday (week start)',
      'start_week_start', p_start_week_start::text
    )::text;
  end if;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  v_has_component := (v_component.id is not null);

  v_current_taxability := coalesce(
    v_case.taxability,
    case
      when v_has_component and v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then 'TAXABLE'::public.pay_finance_taxability_enum
      else 'NON_TAXABLE'::public.pay_finance_taxability_enum
    end
  );

  if p_taxability is null then
    v_requested_taxability := v_current_taxability;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'TAXABLE' then
    v_requested_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
  elsif upper(btrim(coalesce(p_taxability,''))) = 'NON_TAXABLE' then
    v_requested_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
  else
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'TAXABILITY_INVALID',
      'message', 'pay_manual_debt_adjustment_update: taxability must be TAXABLE or NON_TAXABLE when provided',
      'taxability', p_taxability
    )::text;
  end if;

  if v_case.routing_kind is not null then
    v_current_routing_kind := v_case.routing_kind;
  elsif v_candidate_pay_method = 'UMBRELLA' then
    v_current_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
  else
    v_current_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
  end if;

  if v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'GROSS_DEDUCT';
  elsif v_candidate_pay_method = 'PAYE' and v_requested_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NET_DEDUCT';
  elsif v_candidate_pay_method = 'UMBRELLA' and v_requested_taxability = 'TAXABLE'::public.pay_finance_taxability_enum then
    v_requested_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
  else
    v_requested_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
    v_component_classification := 'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum;
    v_paye_treatment := 'NONE';
  end if;

  v_taxability_changed := v_current_taxability is distinct from v_requested_taxability;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where pbi.source_ref = ('advance:' || p_finance_case_id::text)
      and pbi.item_type = 'MANUAL_DEBT_RECOVERY'
      and pbi.is_voided = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status,'')) <> 'CANCELLED'
  ) into v_has_active_batch_item;

  if v_taxability_changed and v_has_active_batch_item then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'TAXABILITY_LOCKED_AFTER_DRAFT',
      'message', 'pay_manual_debt_adjustment_update: taxability cannot be changed once a manual debt recovery is drafted or later',
      'finance_case_id', p_finance_case_id::text,
      'current_taxability', v_current_taxability::text,
      'requested_taxability', v_requested_taxability::text
    )::text;
  end if;

  v_new_outstanding_amount := round(v_new_original_amount - v_recovered_amount, 2);
  v_schedule_base_amount := v_new_outstanding_amount;

  v_has_weekly_due_input := (p_weekly_due is not null and round(p_weekly_due,2) > 0);
  v_has_weeks_total_input := (p_weeks_total is not null and p_weeks_total >= 1);

  if p_weekly_due is not null and round(p_weekly_due,2) <= 0 and not v_has_weeks_total_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_manual_debt_adjustment_update: weekly_due must be > 0 when provided'
    )::text;
  end if;

  if p_weeks_total is not null and p_weeks_total < 1 and not v_has_weekly_due_input then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_manual_debt_adjustment_update: weeks_total must be >= 1 when provided'
    )::text;
  end if;

  if not v_has_weekly_due_input and not v_has_weeks_total_input then
    v_schedule_input_mode := 'UNCHANGED';
    v_new_weekly_due := round(coalesce(v_case.weekly_due,0),2);
    v_new_weeks_total := v_case.weeks_total;
  elsif v_has_weekly_due_input and v_has_weeks_total_input then
    v_schedule_input_mode := 'LEGACY_BOTH';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := p_weeks_total;
  elsif v_has_weeks_total_input then
    v_schedule_input_mode := 'BY_WEEKS';
    v_new_weeks_total := p_weeks_total;
    v_new_weekly_due := round((ceil((v_schedule_base_amount / v_new_weeks_total) * 100) / 100), 2);
  else
    v_schedule_input_mode := 'BY_WEEKLY_DUE';
    v_new_weekly_due := round(p_weekly_due,2);
    v_new_weeks_total := greatest(ceil(v_schedule_base_amount / v_new_weekly_due)::int, 1);
  end if;

  if v_new_weekly_due is null or v_new_weekly_due <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'WEEKLY_DUE_INVALID',
      'message', 'pay_manual_debt_adjustment_update: normalized weekly_due must be > 0'
    )::text;
  end if;

  if v_new_weeks_total is null or v_new_weeks_total < 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'WEEKS_TOTAL_INVALID',
      'message', 'pay_manual_debt_adjustment_update: normalized weeks_total must be >= 1'
    )::text;
  end if;

  if p_start_week_start is not null then
    v_new_start_week_start := p_start_week_start;
  elsif v_case.next_due_week_start is not null then
    v_new_start_week_start := v_case.next_due_week_start;
  else
    v_new_start_week_start := v_case.start_week_start;
  end if;

  if v_new_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_manual_debt_adjustment_update: start_week_start is required'
    )::text;
  end if;

  if public._pay_week_start_monday(v_new_start_week_start) <> v_new_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_manual_debt_adjustment_update: start_week_start must be a Monday (week start)',
      'start_week_start', v_new_start_week_start::text
    )::text;
  end if;

  v_required_weeks := greatest(ceil(v_new_outstanding_amount / v_new_weekly_due)::int, 1);
  if v_new_weeks_total < v_required_weeks then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_UPDATE',
      'code', 'WEEKS_TOTAL_TOO_SHORT',
      'message', 'pay_manual_debt_adjustment_update: repayment schedule does not cover the remaining debt amount',
      'required_weeks', v_required_weeks,
      'weeks_total', v_new_weeks_total
    )::text;
  end if;

  select
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_new_start_week_start + (gs.i * 7))::date,
          'amount', round(
            -least(
              v_new_weekly_due,
              greatest(v_new_outstanding_amount - (v_new_weekly_due * gs.i), 0)
            ),
            2
          )
        )
        order by (v_new_start_week_start + (gs.i * 7))::date asc
      ),
      '[]'::jsonb
    )
  into v_new_schedule_json
  from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs(i);

  select min(x.week_start)
  into v_new_next_due
  from (
    select
      (v_new_start_week_start + (gs2.i * 7))::date as week_start,
      round(
        -least(
          v_new_weekly_due,
          greatest(v_new_outstanding_amount - (v_new_weekly_due * gs2.i), 0)
        ),
        2
      )::numeric as amt
    from generate_series(0, greatest(v_new_weeks_total,1) - 1) as gs2(i)
  ) x
  where x.amt < 0;

  v_component_source_basis_json := jsonb_strip_nulls(
    jsonb_build_object(
      'case_type', 'MANUAL_DEBT_ADJUSTMENT',
      'amount', v_new_original_amount,
      'taxability', v_requested_taxability::text,
      'routing_kind', v_requested_routing_kind::text,
      'paye_treatment', v_paye_treatment,
      'weekly_due', v_new_weekly_due,
      'weeks_total', v_new_weeks_total,
      'start_week_start', v_new_start_week_start::text,
      'next_due_week_start', case when v_new_next_due is null then null else v_new_next_due::text end,
      'schedule_json', coalesce(v_new_schedule_json, '[]'::jsonb),
      'minimum_earnings_threshold', v_new_minimum_earnings_threshold,
      'take_home_floor_override', v_new_take_home_floor_override,
      'adjustment_comment', v_new_adjustment_comment,
      'note', v_new_notes
    )
  );

  v_before_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end
  );

  update public.pay_advances pa
  set original_amount = v_new_original_amount,
      outstanding_amount = v_new_outstanding_amount,
      schedule_json = coalesce(v_new_schedule_json,'[]'::jsonb),
      next_due_week_start = v_new_next_due,
      weekly_due = v_new_weekly_due,
      weeks_total = v_new_weeks_total,
      start_week_start = v_new_start_week_start,
      adjustment_comment = v_new_adjustment_comment,
      notes = v_new_notes,
      minimum_earnings_threshold = v_new_minimum_earnings_threshold,
      take_home_floor_override = v_new_take_home_floor_override,
      updated_at = v_now_utc,
      taxability = v_requested_taxability,
      routing_kind = v_requested_routing_kind,
      oneoff_bank_details_required = false
  where pa.id = p_finance_case_id;

  if v_has_component then
    v_component_before_json := jsonb_build_object(
      'finance_component_id', v_component.id::text,
      'classification', v_component.classification::text,
      'source_amount', round(coalesce(v_component.source_amount,0),2),
      'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
      'source_pay_method', v_component.source_pay_method,
      'saved_target_pay_method', v_component.saved_target_pay_method,
      'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
      'resolution_fingerprint', v_component.resolution_fingerprint,
      'is_resolution_stale', v_component.is_resolution_stale,
      'stale_reason', v_component.stale_reason,
      'source_basis_json', v_component.source_basis_json
    );

    v_source_basis_changed := (
      round(coalesce(v_component.source_amount,0),2) is distinct from round(coalesce(v_new_original_amount,0),2)
      or v_component.source_basis_json is distinct from v_component_source_basis_json
      or v_component.classification is distinct from v_component_classification
      or coalesce(v_component.source_pay_method,'') is distinct from coalesce(v_candidate_pay_method,'')
    );

    if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
      v_component_resolution_payload_json := jsonb_build_object(
        'same_channel', true,
        'target_amount', v_new_original_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_result_json := jsonb_build_object(
        'target_amount', v_new_original_amount,
        'target_amount_ex_vat', v_new_original_amount,
        'target_amount_vat', 0,
        'target_amount_inc_vat', v_new_original_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
        p_source_family_key         => 'case:' || p_finance_case_id::text,
        p_component_key_type        => 'CASE_TOTAL',
        p_component_key_value       => 'TOTAL',
        p_classification            => 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
        p_source_pay_method         => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json         => v_component_source_basis_json,
        p_source_amount             => v_new_original_amount,
        p_relevant_erni_pct         => null::numeric,
        p_target_basis_json         => jsonb_build_object('same_channel', true)
      );

      v_component_is_resolution_stale := false;
      v_component_stale_reason := null;
    else
      v_component_resolution_payload_json := null;
      v_component_resolution_result_json := null;
      v_component_resolution_fingerprint := null;
      v_component_is_resolution_stale := false;
      v_component_stale_reason := null;
    end if;

    update public.pay_finance_case_components pfc
    set classification = v_component_classification,
        source_pay_method = v_candidate_pay_method,
        source_basis_json = v_component_source_basis_json,
        source_amount = v_new_original_amount,
        remaining_source_amount = v_new_outstanding_amount,
        saved_target_pay_method = case
          when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then v_candidate_pay_method
          else null
        end,
        saved_resolution_mode = case
          when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
          else null
        end,
        saved_resolution_payload_json = v_component_resolution_payload_json,
        saved_resolution_result_json = v_component_resolution_result_json,
        resolution_fingerprint = v_component_resolution_fingerprint,
        is_resolution_stale = v_component_is_resolution_stale,
        stale_reason = v_component_stale_reason,
        updated_at_utc = v_now_utc,
        resolved_at_utc = case
          when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
          then v_now_utc
          else null::timestamptz
        end
    where pfc.id = v_component.id
    returning pfc.* into v_component;
  else
    if v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
      v_component_resolution_payload_json := jsonb_build_object(
        'same_channel', true,
        'target_amount', v_new_original_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_result_json := jsonb_build_object(
        'target_amount', v_new_original_amount,
        'target_amount_ex_vat', v_new_original_amount,
        'target_amount_vat', 0,
        'target_amount_inc_vat', v_new_original_amount,
        'target_pay_method', v_candidate_pay_method
      );

      v_component_resolution_fingerprint := public.pay_finance_component_fingerprint(
        p_source_family_key         => 'case:' || p_finance_case_id::text,
        p_component_key_type        => 'CASE_TOTAL',
        p_component_key_value       => 'TOTAL',
        p_classification            => 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum,
        p_source_pay_method         => v_candidate_pay_method,
        p_current_target_pay_method => v_candidate_pay_method,
        p_source_basis_json         => v_component_source_basis_json,
        p_source_amount             => v_new_original_amount,
        p_relevant_erni_pct         => null::numeric,
        p_target_basis_json         => jsonb_build_object('same_channel', true)
      );
    else
      v_component_resolution_payload_json := null;
      v_component_resolution_result_json := null;
      v_component_resolution_fingerprint := null;
    end if;

    insert into public.pay_finance_case_components(
      finance_case_id,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      source_pay_method,
      source_basis_json,
      source_amount,
      remaining_source_amount,
      saved_target_pay_method,
      saved_resolution_mode,
      saved_resolution_payload_json,
      saved_resolution_result_json,
      resolution_fingerprint,
      is_resolution_stale,
      stale_reason,
      allocation_priority_group,
      allocation_priority_order,
      created_at_utc,
      updated_at_utc,
      resolved_at_utc,
      closed_at_utc
    )
    values (
      p_finance_case_id,
      v_case.candidate_id,
      v_case.client_id,
      v_case.linked_timesheet_id,
      'case:' || p_finance_case_id::text,
      'CASE_TOTAL',
      'TOTAL',
      v_component_classification,
      v_candidate_pay_method,
      v_component_source_basis_json,
      v_new_original_amount,
      v_new_outstanding_amount,
      case
        when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        then v_candidate_pay_method
        else null
      end,
      case
        when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        then 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum
        else null
      end,
      v_component_resolution_payload_json,
      v_component_resolution_result_json,
      v_component_resolution_fingerprint,
      false,
      null::text,
      0,
      0,
      v_now_utc,
      v_now_utc,
      case
        when v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        then v_now_utc
        else null::timestamptz
      end,
      null::timestamptz
    )
    returning * into v_component;

    v_component_created := true;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  v_component_after_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'classification', v_component.classification::text,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'resolution_fingerprint', v_component.resolution_fingerprint,
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'source_basis_json', v_component.source_basis_json
  );

  v_after_json := jsonb_build_object(
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'adjustment_comment', v_case.adjustment_comment,
    'notes', v_case.notes,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_input_mode', v_schedule_input_mode,
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'component_summary', v_component_after_json
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    null::uuid,
    'UPDATED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    null::text,
    'Manual debt adjustment updated'
  );

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_component.id,
    case when v_component_created then 'COMPONENT_CREATED' else 'COMPONENT_UPDATED' end,
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_component_before_json,
    v_component_after_json,
    case when v_source_basis_changed then 'COMPONENT_BASIS_CHANGED' else null::text end,
    case
      when v_component_created and v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then 'Created taxable total component for manual debt adjustment update'
      when v_component_created
      then 'Created non-taxable fixed recovery component for manual debt adjustment update'
      when v_source_basis_changed and v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      then 'Updated taxable total component for manual debt adjustment'
      when v_source_basis_changed
      then 'Updated non-taxable fixed recovery component for manual debt adjustment'
      else 'Updated manual debt adjustment component'
    end
  );

  v_component_summary_json := jsonb_build_object(
    'finance_component_id', v_component.id::text,
    'source_family_key', v_component.source_family_key,
    'component_key_type', v_component.component_key_type,
    'component_key_value', v_component.component_key_value,
    'classification', v_component.classification::text,
    'source_pay_method', v_component.source_pay_method,
    'saved_target_pay_method', v_component.saved_target_pay_method,
    'saved_resolution_mode', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
    'source_amount', round(coalesce(v_component.source_amount,0),2),
    'remaining_source_amount', round(coalesce(v_component.remaining_source_amount,0),2),
    'is_resolution_stale', v_component.is_resolution_stale,
    'stale_reason', v_component.stale_reason,
    'taxability', v_requested_taxability::text,
    'routing_kind', v_requested_routing_kind::text,
    'paye_treatment', v_paye_treatment
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'finance_component_id', v_component.id::text,
    'case_type', 'MANUAL_DEBT_ADJUSTMENT',
    'worker_label', 'Manual debt adjustment',
    'recovery_label', 'Manual debt adjustment recovery',
    'paye_treatment', v_paye_treatment,
    'schedule_input_mode', v_schedule_input_mode,
    'original_amount', round(coalesce(v_case.original_amount,0),2),
    'outstanding_amount', round(coalesce(v_case.outstanding_amount,0),2),
    'weekly_due', round(coalesce(v_case.weekly_due,0),2),
    'weeks_total', v_case.weeks_total,
    'start_week_start', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
    'next_due_week_start', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
    'minimum_earnings_threshold', v_case.minimum_earnings_threshold,
    'take_home_floor_override', v_case.take_home_floor_override,
    'schedule_json', coalesce(v_case.schedule_json,'[]'::jsonb),
    'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
    'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
    'oneoff_bank_details_required', false,
    'component_summary', v_component_summary_json
  );
end;
$$;



CREATE OR REPLACE FUNCTION public.pay_finance_ledger_export_rows(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_status text DEFAULT 'ALL'::text,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_case_type text DEFAULT NULL::text,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := upper(btrim(coalesce(p_status, 'ALL')));
  v_case_type text := upper(nullif(btrim(coalesce(p_case_type, '')), ''));
  v_sort_key text := lower(coalesce(nullif(btrim(p_sort_key), ''), 'created_at'));
  v_sort_dir text := lower(coalesce(nullif(btrim(p_sort_dir), ''), 'desc'));
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_meta jsonb := '{}'::jsonb;
BEGIN
  IF v_status NOT IN ('ALL', 'OUTSTANDING', 'FULLY_PAID') THEN
    v_status := 'ALL';
  END IF;

  IF v_sort_key NOT IN (
    'created_at',
    'candidate',
    'client',
    'case_type',
    'outstanding_amount',
    'next_due_week_start'
  ) THEN
    v_sort_key := 'created_at';
  END IF;

  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  WITH base_rows AS (
    SELECT
      vfcr.finance_case_id,
      vfcr.case_type,
      CASE vfcr.case_type
        WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance'
        WHEN 'OVERPAYMENT' THEN 'Overpayment'
        WHEN 'UNDERPAYMENT' THEN 'Underpayment'
        WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment'
        WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
        ELSE coalesce(vfcr.case_type::text, 'Finance Case')
      END AS row_label,
      CASE vfcr.case_type
        WHEN 'PAYMENT_ADVANCE' THEN 'PAYMENT_ADVANCE'
        WHEN 'OVERPAYMENT' THEN 'OVERPAYMENT'
        WHEN 'UNDERPAYMENT' THEN 'UNDERPAYMENT'
        WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'MANUAL_DEBT_ADJUSTMENT'
        WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'MANUAL_CREDIT_ADJUSTMENT'
        ELSE 'OTHER'
      END AS row_group,
      cs.tms_ref AS candidate_tms_ref,
      cs.tms_ref_num AS candidate_tms_ref_num,
      cs.first_name AS candidate_first_name,
      cs.last_name AS candidate_last_name,
      coalesce(cs.display_name, vfcr.candidate_display_name) AS candidate_display_name,
      vfcr.pay_method,
      vfcr.client_name,
      ts.booking_id AS linked_timesheet_booking_id,
      ts.week_ending_date AS linked_timesheet_week_ending_date,
      ts.shift_label_norm AS linked_timesheet_shift_label_norm,
      ts.reference_number AS linked_timesheet_reference_number,
      vfcr.linked_shift_date,
      vfcr.created_at,
      vfcr.updated_at,
      coalesce(nullif(btrim(coalesce(u_created.display_name, u_created.email, '')), ''), 'CloudTMS server') AS created_by_display,
      coalesce(vfcr.status::text, '') AS finance_status,
      coalesce(vfcr.payout_status::text, '') AS payout_status,
      CASE
        WHEN vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' THEN
          CASE
            WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'PAID' THEN 'FULLY_PAID'
            WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'CANCELLED' THEN 'CANCELLED'
            ELSE 'OUTSTANDING'
          END
        ELSE
          CASE
            WHEN vfcr.written_off_at_utc IS NOT NULL THEN 'WRITTEN_OFF'
            WHEN round(norm.outstanding_amount_norm, 2) > 0 THEN 'OUTSTANDING'
            ELSE 'FULLY_PAID'
          END
      END AS ledger_status,
      round(norm.original_amount_norm, 2) AS original_amount,
      round(norm.outstanding_amount_norm, 2) AS outstanding_amount,
      round(norm.weekly_due_norm, 2) AS weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      norm.schedule_json_norm AS schedule_json,
      vfcr.adjustment_comment,
      round(norm.source_original_paid_amount_norm, 2) AS source_original_paid_amount,
      round(norm.source_corrected_paid_amount_norm, 2) AS source_corrected_paid_amount,
      round(norm.minimum_earnings_threshold_norm, 2) AS minimum_earnings_threshold,
      round(norm.take_home_floor_override_norm, 2) AS take_home_floor_override,
      vfcr.baseline_signature,
      round(norm.best_guess_hours_norm, 2) AS best_guess_hours,
      vfcr.notes,
      vfcr.written_off_at_utc,
      coalesce(nullif(btrim(coalesce(u_written_off.display_name, u_written_off.email, '')), ''), NULL) AS written_off_by_display,
      vfcr.write_off_reason,
      vfcr.cleared_at_utc,
      coalesce(nullif(btrim(coalesce(u_cleared.display_name, u_cleared.email, '')), ''), NULL) AS cleared_by_display,
      round(norm.active_reserved_amount_norm, 2) AS active_reserved_amount,
      round(norm.reserved_amount_norm, 2) AS reserved_amount,
      round(norm.committed_amount_norm, 2) AS committed_amount,
      round(norm.settled_amount_norm, 2) AS settled_amount,
      round(norm.released_amount_norm, 2) AS released_amount,
      norm.active_reservation_count_norm AS active_reservation_count,
      vfcr.latest_reservation_created_at_utc,
      vfcr.latest_committed_at_utc,
      vfcr.latest_settled_at_utc,
      vfcr.latest_released_at_utc,
      vfcr.latest_recovery_pay_date,
      vfcr.latest_remittance_sent_at_utc,
      vfcr.latest_remittance_trigger_status,
      vfcr.last_remittance_error,
      vfcr.active_snooze_kind,
      CASE
        WHEN vfcr.active_snooze_kind IS NULL THEN NULL
        WHEN vfcr.active_snooze_until_date IS NULL THEN 'INDEFINITE'
        ELSE 'DATED'
      END AS active_snooze_mode,
      vfcr.active_snooze_until_date,
      vfcr.active_snooze_note,
      vfcr.active_snooze_created_at_utc,
      vfcr.active_snooze_updated_at_utc,
      CASE
        WHEN vfcr.active_snooze_kind IS NULL THEN NULL
        WHEN vfcr.active_snooze_until_date IS NULL THEN 'INDEFINITE_DEFERRED'
        ELSE 'ACTIVE'
      END AS active_snooze_visibility_status,
      norm.is_mixed_case_norm AS is_mixed_case,
      norm.open_taxable_count_norm AS open_taxable_count,
      norm.open_reimbursement_count_norm AS open_reimbursement_count,
      norm.unresolved_taxable_count_norm AS unresolved_taxable_count,
      norm.stale_count_norm AS stale_count,
      norm.component_resolution_summary_json_norm AS component_resolution_summary_json
    FROM public.v_finance_cases_register AS vfcr
    LEFT JOIN public.candidates_summary AS cs
      ON cs.id = vfcr.candidate_id
    LEFT JOIN public.timesheets AS ts
      ON ts.timesheet_id = vfcr.linked_timesheet_id
     AND ts.is_current IS TRUE
    LEFT JOIN public.tms_users AS u_created
      ON u_created.id = vfcr.created_by
    LEFT JOIN public.tms_users AS u_written_off
      ON u_written_off.id = vfcr.written_off_by_user_id
    LEFT JOIN public.tms_users AS u_cleared
      ON u_cleared.id = vfcr.cleared_by_user_id
    LEFT JOIN LATERAL (
      WITH normalized AS (
        SELECT
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN false
            WHEN lower(nullif(btrim(vfcr.is_mixed_case::text, '"'), '')) IN ('true', 't', '1', 'yes', 'y') THEN true
            ELSE false
          END AS is_mixed_case_norm,
          CASE
            WHEN nullif(btrim(vfcr.original_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.original_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS original_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.outstanding_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.outstanding_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS outstanding_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.weekly_due::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.weekly_due::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS weekly_due_norm,
          CASE
            WHEN nullif(btrim(vfcr.source_original_paid_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.source_original_paid_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS source_original_paid_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.source_corrected_paid_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.source_corrected_paid_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS source_corrected_paid_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.minimum_earnings_threshold::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.minimum_earnings_threshold::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS minimum_earnings_threshold_norm,
          CASE
            WHEN nullif(btrim(vfcr.take_home_floor_override::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.take_home_floor_override::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS take_home_floor_override_norm,
          CASE
            WHEN nullif(btrim(vfcr.best_guess_hours::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.best_guess_hours::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS best_guess_hours_norm,
          CASE
            WHEN nullif(btrim(vfcr.active_reserved_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.active_reserved_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS active_reserved_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.reserved_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.reserved_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS reserved_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.committed_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.committed_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS committed_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.settled_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.settled_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS settled_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.released_amount::text, '"'), '') ~ '^-?[0-9]+(\.[0-9]+)?$'
              THEN nullif(btrim(vfcr.released_amount::text, '"'), '')::numeric
            ELSE 0::numeric
          END AS released_amount_norm,
          CASE
            WHEN nullif(btrim(vfcr.active_reservation_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.active_reservation_count::text, '"'), '')::integer
            ELSE 0
          END AS active_reservation_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.open_taxable_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.open_taxable_count::text, '"'), '')::integer
            ELSE 0
          END AS open_taxable_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.open_reimbursement_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.open_reimbursement_count::text, '"'), '')::integer
            ELSE 0
          END AS open_reimbursement_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.unresolved_taxable_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.unresolved_taxable_count::text, '"'), '')::integer
            ELSE 0
          END AS unresolved_taxable_count_norm,
          CASE
            WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN 0
            WHEN nullif(btrim(vfcr.stale_count::text, '"'), '') ~ '^-?[0-9]+$'
              THEN nullif(btrim(vfcr.stale_count::text, '"'), '')::integer
            ELSE 0
          END AS stale_count_norm,
          CASE
            WHEN vfcr.schedule_json IS NULL THEN '[]'::jsonb
            WHEN jsonb_typeof(to_jsonb(vfcr.schedule_json)) IN ('object', 'array') THEN to_jsonb(vfcr.schedule_json)
            ELSE '[]'::jsonb
          END AS schedule_json_norm
      )
      SELECT
        normalized.is_mixed_case_norm,
        normalized.original_amount_norm,
        normalized.outstanding_amount_norm,
        normalized.weekly_due_norm,
        normalized.source_original_paid_amount_norm,
        normalized.source_corrected_paid_amount_norm,
        normalized.minimum_earnings_threshold_norm,
        normalized.take_home_floor_override_norm,
        normalized.best_guess_hours_norm,
        normalized.active_reserved_amount_norm,
        normalized.reserved_amount_norm,
        normalized.committed_amount_norm,
        normalized.settled_amount_norm,
        normalized.released_amount_norm,
        normalized.active_reservation_count_norm,
        normalized.open_taxable_count_norm,
        normalized.open_reimbursement_count_norm,
        normalized.unresolved_taxable_count_norm,
        normalized.stale_count_norm,
        normalized.schedule_json_norm,
        CASE
          WHEN vfcr.case_type = 'PAYMENT_ADVANCE' THEN jsonb_build_object(
            'open_taxable_count', 0,
            'open_reimbursement_count', 0,
            'unresolved_taxable_count', 0,
            'stale_count', 0,
            'is_mixed_case', false
          )
          WHEN vfcr.component_resolution_summary_json IS NULL THEN jsonb_build_object(
            'open_taxable_count', normalized.open_taxable_count_norm,
            'open_reimbursement_count', normalized.open_reimbursement_count_norm,
            'unresolved_taxable_count', normalized.unresolved_taxable_count_norm,
            'stale_count', normalized.stale_count_norm,
            'is_mixed_case', normalized.is_mixed_case_norm
          )
          WHEN jsonb_typeof(to_jsonb(vfcr.component_resolution_summary_json)) IN ('object', 'array') THEN to_jsonb(vfcr.component_resolution_summary_json)
          ELSE jsonb_build_object(
            'open_taxable_count', normalized.open_taxable_count_norm,
            'open_reimbursement_count', normalized.open_reimbursement_count_norm,
            'unresolved_taxable_count', normalized.unresolved_taxable_count_norm,
            'stale_count', normalized.stale_count_norm,
            'is_mixed_case', normalized.is_mixed_case_norm
          )
        END AS component_resolution_summary_json_norm
      FROM normalized
    ) AS norm ON TRUE
    WHERE
      (p_created_from IS NULL OR vfcr.created_at::date >= p_created_from)
      AND (p_created_to IS NULL OR vfcr.created_at::date <= p_created_to)
      AND (p_candidate_id IS NULL OR vfcr.candidate_id = p_candidate_id)
      AND (p_client_id IS NULL OR vfcr.client_id = p_client_id)
      AND (v_case_type IS NULL OR upper(coalesce(vfcr.case_type::text, '')) = v_case_type)
  ),
  filtered_rows AS (
    SELECT
      br.*
    FROM base_rows AS br
    WHERE
      v_status = 'ALL'
      OR (v_status = 'OUTSTANDING' AND br.ledger_status = 'OUTSTANDING')
      OR (v_status = 'FULLY_PAID' AND br.ledger_status = 'FULLY_PAID')
  ),
  ordered_rows AS (
    SELECT
      fr.*
    FROM filtered_rows AS fr
    ORDER BY
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'asc' THEN fr.created_at END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'desc' THEN fr.created_at END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.candidate_display_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.candidate_display_name, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.client_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.client_name, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'case_type' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.case_type::text, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'case_type' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.case_type::text, '')) END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'outstanding_amount' AND v_sort_dir = 'asc' THEN fr.outstanding_amount END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'outstanding_amount' AND v_sort_dir = 'desc' THEN fr.outstanding_amount END DESC NULLS LAST,
      CASE WHEN v_sort_key = 'next_due_week_start' AND v_sort_dir = 'asc' THEN fr.next_due_week_start END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'next_due_week_start' AND v_sort_dir = 'desc' THEN fr.next_due_week_start END DESC NULLS LAST,
      fr.created_at DESC,
      lower(coalesce(fr.candidate_display_name, '')) ASC
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'row_group', orw.row_group,
          'case_type', orw.case_type,
          'row_label', orw.row_label,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_tms_ref_num', orw.candidate_tms_ref_num,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'candidate_display_name', orw.candidate_display_name,
          'pay_method', orw.pay_method,
          'client_name', orw.client_name,
          'linked_timesheet_booking_id', orw.linked_timesheet_booking_id,
          'linked_timesheet_week_ending_date', CASE WHEN orw.linked_timesheet_week_ending_date IS NULL THEN NULL ELSE orw.linked_timesheet_week_ending_date::text END,
          'linked_timesheet_shift_label_norm', orw.linked_timesheet_shift_label_norm,
          'linked_timesheet_reference_number', orw.linked_timesheet_reference_number,
          'linked_shift_date', CASE WHEN orw.linked_shift_date IS NULL THEN NULL ELSE orw.linked_shift_date::text END,
          'created_at', CASE WHEN orw.created_at IS NULL THEN NULL ELSE orw.created_at::text END,
          'updated_at', CASE WHEN orw.updated_at IS NULL THEN NULL ELSE orw.updated_at::text END
        )
        || jsonb_build_object(
          'created_by_display', orw.created_by_display,
          'finance_status', orw.finance_status,
          'payout_status', orw.payout_status,
          'ledger_status', orw.ledger_status,
          'original_amount', orw.original_amount,
          'outstanding_amount', orw.outstanding_amount,
          'weekly_due', orw.weekly_due,
          'weeks_total', orw.weeks_total,
          'start_week_start', CASE WHEN orw.start_week_start IS NULL THEN NULL ELSE orw.start_week_start::text END,
          'next_due_week_start', CASE WHEN orw.next_due_week_start IS NULL THEN NULL ELSE orw.next_due_week_start::text END,
          'schedule_json', orw.schedule_json,
          'adjustment_comment', orw.adjustment_comment,
          'source_original_paid_amount', orw.source_original_paid_amount,
          'source_corrected_paid_amount', orw.source_corrected_paid_amount,
          'minimum_earnings_threshold', orw.minimum_earnings_threshold,
          'take_home_floor_override', orw.take_home_floor_override,
          'baseline_signature', orw.baseline_signature,
          'best_guess_hours', orw.best_guess_hours
        )
        || jsonb_build_object(
          'notes', orw.notes,
          'written_off_at_utc', CASE WHEN orw.written_off_at_utc IS NULL THEN NULL ELSE orw.written_off_at_utc::text END,
          'written_off_by_display', orw.written_off_by_display,
          'write_off_reason', orw.write_off_reason,
          'cleared_at_utc', CASE WHEN orw.cleared_at_utc IS NULL THEN NULL ELSE orw.cleared_at_utc::text END,
          'cleared_by_display', orw.cleared_by_display,
          'active_reserved_amount', orw.active_reserved_amount,
          'reserved_amount', orw.reserved_amount,
          'committed_amount', orw.committed_amount,
          'settled_amount', orw.settled_amount,
          'released_amount', orw.released_amount,
          'active_reservation_count', orw.active_reservation_count,
          'latest_reservation_created_at_utc', CASE WHEN orw.latest_reservation_created_at_utc IS NULL THEN NULL ELSE orw.latest_reservation_created_at_utc::text END,
          'latest_committed_at_utc', CASE WHEN orw.latest_committed_at_utc IS NULL THEN NULL ELSE orw.latest_committed_at_utc::text END,
          'latest_settled_at_utc', CASE WHEN orw.latest_settled_at_utc IS NULL THEN NULL ELSE orw.latest_settled_at_utc::text END,
          'latest_released_at_utc', CASE WHEN orw.latest_released_at_utc IS NULL THEN NULL ELSE orw.latest_released_at_utc::text END
        )
        || jsonb_build_object(
          'latest_recovery_pay_date', CASE WHEN orw.latest_recovery_pay_date IS NULL THEN NULL ELSE orw.latest_recovery_pay_date::text END,
          'latest_remittance_sent_at_utc', CASE WHEN orw.latest_remittance_sent_at_utc IS NULL THEN NULL ELSE orw.latest_remittance_sent_at_utc::text END,
          'latest_remittance_trigger_status', orw.latest_remittance_trigger_status,
          'last_remittance_error', orw.last_remittance_error,
          'active_snooze_kind', orw.active_snooze_kind,
          'active_snooze_mode', orw.active_snooze_mode,
          'active_snooze_until_date', CASE WHEN orw.active_snooze_until_date IS NULL THEN NULL ELSE orw.active_snooze_until_date::text END,
          'active_snooze_note', orw.active_snooze_note,
          'active_snooze_created_at_utc', CASE WHEN orw.active_snooze_created_at_utc IS NULL THEN NULL ELSE orw.active_snooze_created_at_utc::text END,
          'active_snooze_updated_at_utc', CASE WHEN orw.active_snooze_updated_at_utc IS NULL THEN NULL ELSE orw.active_snooze_updated_at_utc::text END,
          'active_snooze_visibility_status', orw.active_snooze_visibility_status,
          'is_mixed_case', orw.is_mixed_case,
          'open_taxable_count', orw.open_taxable_count,
          'open_reimbursement_count', orw.open_reimbursement_count,
          'unresolved_taxable_count', orw.unresolved_taxable_count,
          'stale_count', orw.stale_count,
          'component_resolution_summary_json', orw.component_resolution_summary_json
        )
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'total_count', count(*)::int,
      'outstanding_count', count(*) FILTER (WHERE orw.ledger_status = 'OUTSTANDING')::int,
      'fully_paid_count', count(*) FILTER (WHERE orw.ledger_status = 'FULLY_PAID')::int,
      'payment_advance_count', count(*) FILTER (WHERE orw.case_type = 'PAYMENT_ADVANCE')::int,
      'overpayment_count', count(*) FILTER (WHERE orw.case_type = 'OVERPAYMENT')::int,
      'underpayment_count', count(*) FILTER (WHERE orw.case_type = 'UNDERPAYMENT')::int,
      'manual_debt_adjustment_count', count(*) FILTER (WHERE orw.case_type = 'MANUAL_DEBT_ADJUSTMENT')::int,
      'manual_credit_adjustment_count', count(*) FILTER (WHERE orw.case_type = 'MANUAL_CREDIT_ADJUSTMENT')::int,
      'original_amount_total', round(coalesce(sum(orw.original_amount), 0), 2),
      'outstanding_amount_total', round(coalesce(sum(orw.outstanding_amount), 0), 2),
      'active_reserved_amount_total', round(coalesce(sum(orw.active_reserved_amount), 0), 2),
      'mixed_case_count', count(*) FILTER (WHERE orw.is_mixed_case = true)::int,
      'open_taxable_count_total', coalesce(sum(orw.open_taxable_count), 0)::int,
      'open_reimbursement_count_total', coalesce(sum(orw.open_reimbursement_count), 0)::int,
      'unresolved_taxable_count_total', coalesce(sum(orw.unresolved_taxable_count), 0)::int,
      'stale_count_total', coalesce(sum(orw.stale_count), 0)::int
    )
  INTO v_rows, v_summary
  FROM ordered_rows AS orw;

  v_meta := jsonb_build_object(
    'title', 'Finance Ledger',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'applied_filters', jsonb_build_object(
      'created_from', CASE WHEN p_created_from IS NULL THEN NULL ELSE p_created_from::text END,
      'created_to', CASE WHEN p_created_to IS NULL THEN NULL ELSE p_created_to::text END,
      'status', v_status,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'case_type', v_case_type,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Finance Ledger',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'meta', v_meta,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;






CREATE OR REPLACE FUNCTION public.pay_finance_ledger_pdf_payload(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_status text DEFAULT 'ALL'::text,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_case_type text DEFAULT NULL::text,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
BEGIN
  v_base := public.pay_finance_ledger_export_rows(
    p_actor_user_id => p_actor_user_id,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_status => p_status,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_case_type => p_case_type,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  SELECT jsonb_build_array(
    jsonb_build_object(
      'row_group', 'PAYMENT_ADVANCE',
      'title', 'Payment Advances',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'PAYMENT_ADVANCE'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'OVERPAYMENT',
      'title', 'Overpayments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'OVERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'MANUAL_DEBT_ADJUSTMENT',
      'title', 'Manual Debt Adjustments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'MANUAL_DEBT_ADJUSTMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'UNDERPAYMENT',
      'title', 'Underpayments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'UNDERPAYMENT'), '[]'::jsonb)
    ),
    jsonb_build_object(
      'row_group', 'MANUAL_CREDIT_ADJUSTMENT',
      'title', 'Manual Credit Adjustments',
      'rows', coalesce((SELECT jsonb_agg(e.elem) FROM jsonb_array_elements(v_rows) AS e(elem) WHERE e.elem->>'row_group' = 'MANUAL_CREDIT_ADJUSTMENT'), '[]'::jsonb)
    )
  )
  INTO v_groups;

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Finance Ledger',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'groups', coalesce(v_groups, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_snoozes_export_rows(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_status text DEFAULT 'ALL'::text,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_case_type text DEFAULT NULL::text,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_status text := upper(btrim(coalesce(p_status, 'ALL')));
  v_case_type text := upper(nullif(btrim(coalesce(p_case_type, '')), ''));
  v_sort_key text := lower(coalesce(nullif(btrim(p_sort_key), ''), 'created_at'));
  v_sort_dir text := lower(coalesce(nullif(btrim(p_sort_dir), ''), 'desc'));
  v_rows jsonb := '[]'::jsonb;
  v_summary jsonb := '{}'::jsonb;
  v_meta jsonb := '{}'::jsonb;
BEGIN
  IF v_status NOT IN ('ALL', 'OUTSTANDING', 'FULLY_PAID') THEN
    v_status := 'ALL';
  END IF;

  IF v_sort_key NOT IN (
    'created_at',
    'updated_at',
    'candidate',
    'client',
    'snooze_until_date'
  ) THEN
    v_sort_key := 'created_at';
  END IF;

  IF v_sort_dir NOT IN ('asc', 'desc') THEN
    v_sort_dir := 'desc';
  END IF;

  WITH parsed_snoozes AS (
    SELECT
      s.id AS snooze_id,
      s.candidate_id AS snooze_candidate_id,
      s.timesheet_id,
      s.segment_id,
      s.source_ref,
      s.snooze_kind,
      s.snooze_until_date,
      s.note,
      s.created_at_utc,
      s.created_by_user_id,
      s.updated_at_utc,
      s.updated_by_user_id,
      s.cleared_at_utc,
      s.cleared_by_user_id,
      CASE
        WHEN s.source_ref IS NOT NULL
         AND s.source_ref LIKE 'advance:%'
         AND split_part(s.source_ref, ':', 2) ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
        THEN split_part(s.source_ref, ':', 2)::uuid
        ELSE NULL::uuid
      END AS finance_case_id
    FROM public.pay_item_snoozes AS s
    WHERE
      (p_created_from IS NULL OR s.created_at_utc::date >= p_created_from)
      AND (p_created_to IS NULL OR s.created_at_utc::date <= p_created_to)
      AND (
        (s.source_ref IS NOT NULL AND s.source_ref LIKE 'advance:%')
        OR s.timesheet_id IS NOT NULL
      )
  ),
  base_rows AS (
    SELECT
      ps.snooze_id,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN 'FINANCE_CASE'
        ELSE 'TIMESHEET_PAYMENT'
      END AS snooze_scope,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN
          CASE vfcr.case_type
            WHEN 'PAYMENT_ADVANCE' THEN 'Payment Advance'
            WHEN 'OVERPAYMENT' THEN 'Overpayment'
            WHEN 'UNDERPAYMENT' THEN 'Underpayment'
            WHEN 'MANUAL_DEBT_ADJUSTMENT' THEN 'Manual Debt Adjustment'
            WHEN 'MANUAL_CREDIT_ADJUSTMENT' THEN 'Manual Credit Adjustment'
            ELSE coalesce(vfcr.case_type::text, 'Finance Case')
          END
        ELSE 'Timesheet Payment'
      END AS row_label,
      vfcr.case_type,
      cs.tms_ref AS candidate_tms_ref,
      cs.tms_ref_num AS candidate_tms_ref_num,
      cs.first_name AS candidate_first_name,
      cs.last_name AS candidate_last_name,
      coalesce(cs.display_name, vfcr.candidate_display_name, vts.candidate_name) AS candidate_display_name,
      coalesce(vfcr.client_name, vts.client_name) AS client_name,
      ts.booking_id AS linked_timesheet_booking_id,
      ts.week_ending_date AS linked_timesheet_week_ending_date,
      ts.shift_label_norm AS linked_timesheet_shift_label_norm,
      ts.reference_number AS linked_timesheet_reference_number,
      ps.snooze_kind,
      CASE
        WHEN ps.snooze_until_date IS NULL THEN 'INDEFINITE'
        ELSE 'DATED'
      END AS snooze_mode,
      ps.snooze_until_date,
      ps.note,
      ps.created_at_utc,
      coalesce(nullif(btrim(coalesce(u_created.display_name, u_created.email, '')), ''), 'CloudTMS server') AS created_by_display,
      ps.updated_at_utc,
      coalesce(nullif(btrim(coalesce(u_updated.display_name, u_updated.email, '')), ''), NULL) AS updated_by_display,
      ps.cleared_at_utc,
      coalesce(nullif(btrim(coalesce(u_cleared.display_name, u_cleared.email, '')), ''), NULL) AS cleared_by_display,
      CASE
        WHEN ps.cleared_at_utc IS NOT NULL THEN 'HISTORY'
        WHEN ps.snooze_until_date IS NULL THEN 'INDEFINITE_DEFERRED'
        ELSE 'ACTIVE'
      END AS current_visibility_status,
      CASE
        WHEN ps.cleared_at_utc IS NOT NULL THEN 'CLEARED'
        ELSE 'ACTIVE'
      END AS snooze_lifecycle_status,
      CASE
        WHEN ps.finance_case_id IS NOT NULL THEN
          CASE
            WHEN vfcr.case_type = 'MANUAL_CREDIT_ADJUSTMENT' THEN
              CASE
                WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'PAID' THEN 'FULLY_PAID'
                WHEN upper(coalesce(vfcr.payout_status::text, '')) = 'CANCELLED' THEN 'CANCELLED'
                ELSE 'OUTSTANDING'
              END
            ELSE
              CASE
                WHEN vfcr.written_off_at_utc IS NOT NULL THEN 'WRITTEN_OFF'
                WHEN round(coalesce(vfcr.outstanding_amount, 0), 2) > 0 THEN 'OUTSTANDING'
                ELSE 'FULLY_PAID'
              END
          END
        ELSE
          CASE
            WHEN ps.cleared_at_utc IS NOT NULL THEN 'FULLY_PAID'
            ELSE 'OUTSTANDING'
          END
      END AS linked_case_status,
      round(coalesce(vfcr.original_amount, 0), 2) AS original_amount,
      round(coalesce(vfcr.outstanding_amount, 0), 2) AS outstanding_amount,
      round(coalesce(vfcr.weekly_due, 0), 2) AS weekly_due,
      vfcr.weeks_total,
      vfcr.start_week_start,
      vfcr.next_due_week_start,
      vfcr.schedule_json,
      vfcr.adjustment_comment,
      CASE
        WHEN ps.finance_case_id IS NULL THEN NULL::text
        WHEN coalesce(vfcr.is_mixed_case, false) THEN 'MIXED_CASE'
        WHEN coalesce(vfcr.open_taxable_count, 0) > 0 AND coalesce(vfcr.open_reimbursement_count, 0) = 0 THEN 'TAXABLE_RECOVERY'
        WHEN coalesce(vfcr.open_reimbursement_count, 0) > 0 AND coalesce(vfcr.open_taxable_count, 0) = 0 THEN 'REIMBURSEMENT_CARRY_FORWARD'
        ELSE 'UNCLASSIFIED'
      END AS snooze_component_scope,
      CASE
        WHEN ps.finance_case_id IS NULL THEN NULL::text
        WHEN coalesce(vfcr.is_mixed_case, false) THEN 'Mixed Case'
        WHEN coalesce(vfcr.open_taxable_count, 0) > 0 AND coalesce(vfcr.open_reimbursement_count, 0) = 0 THEN 'Taxable Recovery'
        WHEN coalesce(vfcr.open_reimbursement_count, 0) > 0 AND coalesce(vfcr.open_taxable_count, 0) = 0 THEN 'Reimbursement Carry-forward'
        ELSE 'Unclassified'
      END AS snooze_component_scope_label,
      coalesce(vfcr.is_mixed_case, false) AS is_mixed_case,
      coalesce(vfcr.open_taxable_count, 0) AS open_taxable_count,
      coalesce(vfcr.open_reimbursement_count, 0) AS open_reimbursement_count,
      coalesce(vfcr.unresolved_taxable_count, 0) AS unresolved_taxable_count,
      coalesce(vfcr.stale_count, 0) AS stale_count,
      (coalesce(vfcr.unresolved_taxable_count, 0) > 0) AS has_unresolved_taxable_components,
      (coalesce(vfcr.stale_count, 0) > 0) AS has_stale_components,
      coalesce(vfcr.component_resolution_summary_json, '{}'::jsonb) AS component_resolution_summary_json
    FROM parsed_snoozes AS ps
    LEFT JOIN public.v_finance_cases_register AS vfcr
      ON vfcr.finance_case_id = ps.finance_case_id
    LEFT JOIN public.v_timesheets_summary AS vts
      ON vts.timesheet_id = ps.timesheet_id
    LEFT JOIN public.timesheets AS ts
      ON ts.timesheet_id = ps.timesheet_id
     AND ts.is_current IS TRUE
    LEFT JOIN public.candidates_summary AS cs
      ON cs.id = coalesce(vfcr.candidate_id, vts.candidate_id, ps.snooze_candidate_id)
    LEFT JOIN public.tms_users AS u_created
      ON u_created.id = ps.created_by_user_id
    LEFT JOIN public.tms_users AS u_updated
      ON u_updated.id = ps.updated_by_user_id
    LEFT JOIN public.tms_users AS u_cleared
      ON u_cleared.id = ps.cleared_by_user_id
    WHERE
      (p_candidate_id IS NULL OR coalesce(vfcr.candidate_id, vts.candidate_id, ps.snooze_candidate_id) = p_candidate_id)
      AND (p_client_id IS NULL OR coalesce(vfcr.client_id, vts.client_id) = p_client_id)
      AND (v_case_type IS NULL OR upper(coalesce(vfcr.case_type::text, '')) = v_case_type)
  ),
  filtered_rows AS (
    SELECT
      br.*
    FROM base_rows AS br
    WHERE
      v_status = 'ALL'
      OR (v_status = 'OUTSTANDING' AND br.linked_case_status = 'OUTSTANDING')
      OR (v_status = 'FULLY_PAID' AND br.linked_case_status = 'FULLY_PAID')
  ),
  ordered_rows AS (
    SELECT
      fr.*
    FROM filtered_rows AS fr
    ORDER BY
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'asc' THEN fr.created_at_utc END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'created_at' AND v_sort_dir = 'desc' THEN fr.created_at_utc END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'updated_at' AND v_sort_dir = 'asc' THEN fr.updated_at_utc END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'updated_at' AND v_sort_dir = 'desc' THEN fr.updated_at_utc END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.candidate_display_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'candidate' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.candidate_display_name, '')) END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'asc' THEN lower(coalesce(fr.client_name, '')) END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'client' AND v_sort_dir = 'desc' THEN lower(coalesce(fr.client_name, '')) END DESC NULLS LAST,

      CASE WHEN v_sort_key = 'snooze_until_date' AND v_sort_dir = 'asc' THEN fr.snooze_until_date END ASC NULLS LAST,
      CASE WHEN v_sort_key = 'snooze_until_date' AND v_sort_dir = 'desc' THEN fr.snooze_until_date END DESC NULLS LAST,

      fr.created_at_utc DESC,
      lower(coalesce(fr.candidate_display_name, '')) ASC
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'snooze_scope', orw.snooze_scope,
          'row_label', orw.row_label,
          'case_type', orw.case_type,
          'candidate_tms_ref', orw.candidate_tms_ref,
          'candidate_tms_ref_num', orw.candidate_tms_ref_num,
          'candidate_first_name', orw.candidate_first_name,
          'candidate_last_name', orw.candidate_last_name,
          'candidate_display_name', orw.candidate_display_name,
          'client_name', orw.client_name,
          'linked_timesheet_booking_id', orw.linked_timesheet_booking_id,
          'linked_timesheet_week_ending_date', CASE WHEN orw.linked_timesheet_week_ending_date IS NULL THEN NULL ELSE orw.linked_timesheet_week_ending_date::text END,
          'linked_timesheet_shift_label_norm', orw.linked_timesheet_shift_label_norm,
          'linked_timesheet_reference_number', orw.linked_timesheet_reference_number,
          'snooze_kind', orw.snooze_kind,
          'snooze_mode', orw.snooze_mode,
          'snooze_until_date', CASE WHEN orw.snooze_until_date IS NULL THEN NULL ELSE orw.snooze_until_date::text END,
          'note', orw.note,
          'created_at_utc', CASE WHEN orw.created_at_utc IS NULL THEN NULL ELSE orw.created_at_utc::text END,
          'created_by_display', orw.created_by_display,
          'updated_at_utc', CASE WHEN orw.updated_at_utc IS NULL THEN NULL ELSE orw.updated_at_utc::text END,
          'updated_by_display', orw.updated_by_display,
          'cleared_at_utc', CASE WHEN orw.cleared_at_utc IS NULL THEN NULL ELSE orw.cleared_at_utc::text END,
          'cleared_by_display', orw.cleared_by_display,
          'current_visibility_status', orw.current_visibility_status,
          'snooze_lifecycle_status', orw.snooze_lifecycle_status,
          'linked_case_status', orw.linked_case_status,
          'original_amount', orw.original_amount,
          'outstanding_amount', orw.outstanding_amount,
          'weekly_due', orw.weekly_due,
          'weeks_total', orw.weeks_total,
          'start_week_start', CASE WHEN orw.start_week_start IS NULL THEN NULL ELSE orw.start_week_start::text END,
          'next_due_week_start', CASE WHEN orw.next_due_week_start IS NULL THEN NULL ELSE orw.next_due_week_start::text END,
          'schedule_json', coalesce(orw.schedule_json, '[]'::jsonb),
          'adjustment_comment', orw.adjustment_comment,
          'snooze_component_scope', orw.snooze_component_scope,
          'snooze_component_scope_label', orw.snooze_component_scope_label,
          'is_mixed_case', orw.is_mixed_case,
          'open_taxable_count', orw.open_taxable_count,
          'open_reimbursement_count', orw.open_reimbursement_count,
          'unresolved_taxable_count', orw.unresolved_taxable_count,
          'stale_count', orw.stale_count,
          'has_unresolved_taxable_components', orw.has_unresolved_taxable_components,
          'has_stale_components', orw.has_stale_components,
          'component_resolution_summary_json', orw.component_resolution_summary_json
        )
      ),
      '[]'::jsonb
    ),
    jsonb_build_object(
      'total_count', count(*)::int,
      'finance_case_snooze_count', count(*) FILTER (WHERE orw.snooze_scope = 'FINANCE_CASE')::int,
      'timesheet_payment_snooze_count', count(*) FILTER (WHERE orw.snooze_scope = 'TIMESHEET_PAYMENT')::int,
      'active_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'ACTIVE')::int,
      'cleared_count', count(*) FILTER (WHERE orw.snooze_lifecycle_status = 'CLEARED')::int,
      'indefinite_count', count(*) FILTER (WHERE orw.snooze_mode = 'INDEFINITE')::int,
      'dated_count', count(*) FILTER (WHERE orw.snooze_mode = 'DATED')::int,
      'taxable_recovery_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'TAXABLE_RECOVERY')::int,
      'reimbursement_carry_forward_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'REIMBURSEMENT_CARRY_FORWARD')::int,
      'mixed_case_count', count(*) FILTER (WHERE orw.snooze_component_scope = 'MIXED_CASE')::int,
      'unresolved_case_count', count(*) FILTER (WHERE coalesce(orw.unresolved_taxable_count, 0) > 0)::int,
      'stale_case_count', count(*) FILTER (WHERE coalesce(orw.stale_count, 0) > 0)::int
    )
  INTO v_rows, v_summary
  FROM ordered_rows AS orw;

  v_meta := jsonb_build_object(
    'title', 'Snoozes Report',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'applied_filters', jsonb_build_object(
      'created_from', CASE WHEN p_created_from IS NULL THEN NULL ELSE p_created_from::text END,
      'created_to', CASE WHEN p_created_to IS NULL THEN NULL ELSE p_created_to::text END,
      'status', v_status,
      'candidate_id', CASE WHEN p_candidate_id IS NULL THEN NULL ELSE p_candidate_id::text END,
      'client_id', CASE WHEN p_client_id IS NULL THEN NULL ELSE p_client_id::text END,
      'case_type', v_case_type,
      'sort_key', v_sort_key,
      'sort_dir', v_sort_dir
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Snoozes Report',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_summary, '{}'::jsonb),
    'meta', v_meta,
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_snoozes_pdf_payload(
  p_actor_user_id uuid DEFAULT NULL::uuid,
  p_created_from date DEFAULT NULL::date,
  p_created_to date DEFAULT NULL::date,
  p_status text DEFAULT 'ALL'::text,
  p_candidate_id uuid DEFAULT NULL::uuid,
  p_client_id uuid DEFAULT NULL::uuid,
  p_case_type text DEFAULT NULL::text,
  p_sort_key text DEFAULT 'created_at'::text,
  p_sort_dir text DEFAULT 'desc'::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_base jsonb := '{}'::jsonb;
  v_rows jsonb := '[]'::jsonb;
  v_groups jsonb := '[]'::jsonb;
BEGIN
  v_base := public.pay_snoozes_export_rows(
    p_actor_user_id => p_actor_user_id,
    p_created_from => p_created_from,
    p_created_to => p_created_to,
    p_status => p_status,
    p_candidate_id => p_candidate_id,
    p_client_id => p_client_id,
    p_case_type => p_case_type,
    p_sort_key => p_sort_key,
    p_sort_dir => p_sort_dir
  );

  v_rows := coalesce(v_base->'rows', '[]'::jsonb);

  SELECT jsonb_build_array(
    jsonb_build_object(
      'row_group', 'FINANCE_CASE',
      'title', 'Finance-case Snoozes',
      'rows', coalesce(
        (
          SELECT jsonb_agg(e.elem)
          FROM jsonb_array_elements(v_rows) AS e(elem)
          WHERE e.elem->>'snooze_scope' = 'FINANCE_CASE'
        ),
        '[]'::jsonb
      )
    ),
    jsonb_build_object(
      'row_group', 'TIMESHEET_PAYMENT',
      'title', 'Timesheet-payment Snoozes',
      'rows', coalesce(
        (
          SELECT jsonb_agg(e.elem)
          FROM jsonb_array_elements(v_rows) AS e(elem)
          WHERE e.elem->>'snooze_scope' = 'TIMESHEET_PAYMENT'
        ),
        '[]'::jsonb
      )
    )
  )
  INTO v_groups;

  RETURN jsonb_build_object(
    'ok', true,
    'title', 'Snoozes Report',
    'orientation', 'LANDSCAPE',
    'generated_at_utc', now()::text,
    'summary', coalesce(v_base->'summary', '{}'::jsonb),
    'meta', coalesce(v_base->'meta', '{}'::jsonb),
    'groups', coalesce(v_groups, '[]'::jsonb),
    'rows', coalesce(v_rows, '[]'::jsonb)
  );
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_finance_component_fingerprint(
  p_source_family_key text,
  p_component_key_type text,
  p_component_key_value text,
  p_classification public.pay_finance_component_classification_enum,
  p_source_pay_method text,
  p_current_target_pay_method text,
  p_source_basis_json jsonb,
  p_source_amount numeric,
  p_relevant_erni_pct numeric DEFAULT NULL::numeric,
  p_target_basis_json jsonb DEFAULT NULL::jsonb
)
RETURNS text
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  SELECT md5(
    jsonb_build_object(
      'source_family_key', coalesce(btrim(p_source_family_key), ''),
      'component_key_type', coalesce(btrim(p_component_key_type), ''),
      'component_key_value', coalesce(btrim(p_component_key_value), ''),
      'classification', coalesce(p_classification::text, ''),
      'source_pay_method', upper(coalesce(btrim(p_source_pay_method), '')),
      'current_target_pay_method', upper(coalesce(btrim(p_current_target_pay_method), '')),
      'source_basis_json', coalesce(jsonb_strip_nulls(p_source_basis_json), '{}'::jsonb),
      'source_amount', round(coalesce(abs(p_source_amount), 0), 2),
      'relevant_erni_pct', CASE WHEN p_relevant_erni_pct IS NULL THEN NULL ELSE round(p_relevant_erni_pct, 6) END,
      'target_basis_json', coalesce(jsonb_strip_nulls(p_target_basis_json), '{}'::jsonb)
    )::text
  );
$function$;

CREATE OR REPLACE FUNCTION public.pay_finance_components_sync_from_preview(
  p_finance_case_id uuid,
  p_preview_lines_json jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_case_candidate_id uuid;
  v_case_client_id uuid;
  v_case_linked_timesheet_id uuid;
  v_case_current_pay_method text;

  v_input_json jsonb := coalesce(p_preview_lines_json, '[]'::jsonb);
  v_line_json jsonb;
  v_row_seq integer := 0;

  v_source_family_key text;
  v_component_key_type text;
  v_component_key_value text;
  v_raw_key_type text;
  v_raw_key_value text;
  v_raw_classification text;
  v_raw_item_type text;
  v_raw_source_ref text;
  v_raw_expense_kind text;
  v_source_pay_method text;
  v_current_target_pay_method text;

  v_source_amount_text text;
  v_remaining_amount_text text;
  v_relevant_erni_text text;
  v_allocation_group_text text;
  v_allocation_order_text text;

  v_source_amount numeric(12,2);
  v_incoming_remaining_source_amount numeric(12,2);
  v_incoming_remaining_is_explicit boolean;
  v_relevant_erni_pct numeric;
  v_allocation_priority_group integer;
  v_allocation_priority_order integer;

  v_source_basis_json jsonb;
  v_target_basis_json jsonb;
  v_current_basis_fingerprint text;
  v_classification public.pay_finance_component_classification_enum;

  v_line_candidate_id uuid;
  v_line_client_id uuid;
  v_line_linked_timesheet_id uuid;
  v_line_classification public.pay_finance_component_classification_enum;
  v_line_source_amount numeric(12,2);
  v_line_incoming_remaining_source_amount numeric(12,2);
  v_line_allocation_priority_group integer;
  v_line_allocation_priority_order integer;
  v_line_source_basis_json jsonb;
  v_line_current_target_pay_method text;
  v_line_source_pay_method text;

  v_existing_component public.pay_finance_case_components%ROWTYPE;
  v_reopen_component public.pay_finance_case_components%ROWTYPE;
  v_component_after public.pay_finance_case_components%ROWTYPE;

  v_before_json jsonb;
  v_after_json jsonb;

  v_has_saved_resolution boolean;
  v_should_be_stale boolean;
  v_stale_reason text;
  v_consumed_amount numeric(12,2);
  v_new_remaining_source_amount numeric(12,2);
  v_created_component_id uuid;

  v_inserted_count integer := 0;
  v_updated_count integer := 0;
  v_reopened_count integer := 0;
  v_closed_count integer := 0;
  v_stale_marked_count integer := 0;

  v_open_components_json jsonb := '[]'::jsonb;

  v_case_status text;
  v_case_written_off_at_utc timestamptz;
  v_case_cleared_at_utc timestamptz;
  v_case_has_protected_event boolean := false;
  v_case_is_protected boolean := false;
  v_protected_skip_count integer := 0;

  v_component_has_protected_event boolean := false;
  v_component_is_protected boolean := false;
  v_active_consumed_amount numeric(12,2);

  v_accepted_resolution_json jsonb;
  v_line_accepted_resolution_json jsonb;
  v_accepted_resolution_fingerprint text;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION 'p_finance_case_id is required';
  END IF;

  IF jsonb_typeof(v_input_json) <> 'array' THEN
    RAISE EXCEPTION 'p_preview_lines_json must be a jsonb array';
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_START',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'preview_line_count', jsonb_array_length(v_input_json),
      'actor_user_id', p_actor_user_id
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  SELECT
    pa.candidate_id,
    pa.client_id,
    pa.linked_timesheet_id,
    upper(coalesce(c.pay_method, '')),
    upper(coalesce(pa.status::text, '')),
    pa.written_off_at_utc,
    pa.cleared_at_utc
  INTO
    v_case_candidate_id,
    v_case_client_id,
    v_case_linked_timesheet_id,
    v_case_current_pay_method,
    v_case_status,
    v_case_written_off_at_utc,
    v_case_cleared_at_utc
  FROM public.pay_advances pa
  JOIN public.candidates c
    ON c.id = pa.candidate_id
  WHERE pa.id = p_finance_case_id
  FOR UPDATE OF pa;

  IF v_case_candidate_id IS NULL THEN
    RAISE EXCEPTION 'Finance case % not found in public.pay_advances', p_finance_case_id;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_finance_case_events AS protected_case_events
    WHERE protected_case_events.finance_case_id = p_finance_case_id
      AND (
        upper(btrim(coalesce(protected_case_events.event_type, ''))) LIKE '%WRITE%OFF%'
        OR upper(btrim(coalesce(protected_case_events.event_type, ''))) LIKE '%RESTRUCT%'
        OR upper(btrim(coalesce(protected_case_events.event_type, ''))) LIKE '%MANUAL%'
      )
  )
  INTO v_case_has_protected_event;

  v_case_is_protected := (
    v_case_written_off_at_utc IS NOT NULL
    OR v_case_cleared_at_utc IS NOT NULL
    OR coalesce(v_case_status, '') NOT IN ('ACTIVE', 'PAID_OFF')
    OR coalesce(v_case_has_protected_event, false)
  );

  IF v_case_is_protected THEN
    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      NULL,
      'SYNC_SKIPPED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      jsonb_build_object(
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event
      ),
      jsonb_build_object(
        'sync_skipped', true,
        'reason', 'PROTECTED_FINANCE_CASE'
      ),
      'COMPONENT_SYNC_SKIPPED_PROTECTED_CASE',
      'Skipped component sync because the finance case is written-off, cleared, closed, manually resolved, or already restructured.'
    );

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_SKIPPED_PROTECTED_CASE',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'status', v_case_status,
        'written_off_at_utc', v_case_written_off_at_utc,
        'cleared_at_utc', v_case_cleared_at_utc,
        'has_protected_event', v_case_has_protected_event
      ),
      'pay_finance_components',
      p_finance_case_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'skipped', true,
      'skip_reason', 'PROTECTED_FINANCE_CASE',
      'inserted_count', 0,
      'updated_count', 0,
      'reopened_count', 0,
      'closed_count', 0,
      'stale_marked_count', 0,
      'open_components', (
        SELECT coalesce(
          jsonb_agg(
            jsonb_build_object(
              'id', pfc.id::text,
              'finance_case_id', pfc.finance_case_id::text,
              'candidate_id', pfc.candidate_id::text,
              'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
              'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
              'source_family_key', pfc.source_family_key,
              'component_key_type', pfc.component_key_type,
              'component_key_value', pfc.component_key_value,
              'classification', pfc.classification::text,
              'source_pay_method', pfc.source_pay_method,
              'source_amount', round(coalesce(pfc.source_amount, 0), 2),
              'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
              'saved_target_pay_method', pfc.saved_target_pay_method,
              'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
              'is_resolution_stale', pfc.is_resolution_stale,
              'stale_reason', pfc.stale_reason,
              'allocation_priority_group', pfc.allocation_priority_group,
              'allocation_priority_order', pfc.allocation_priority_order,
              'created_at_utc', pfc.created_at_utc,
              'updated_at_utc', pfc.updated_at_utc
            )
            ORDER BY
              pfc.source_family_key,
              pfc.allocation_priority_group,
              pfc.allocation_priority_order,
              pfc.component_key_type,
              pfc.component_key_value
          ),
          '[]'::jsonb
        )
        FROM public.pay_finance_case_components AS pfc
        WHERE pfc.finance_case_id = p_finance_case_id
          AND pfc.closed_at_utc IS NULL
      )
    );
  END IF;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_sync_input (
    row_seq integer NOT NULL,
    source_family_key text NOT NULL,
    component_key_type text NOT NULL,
    component_key_value text NOT NULL,
    classification public.pay_finance_component_classification_enum NOT NULL,
    candidate_id uuid NOT NULL,
    client_id uuid NULL,
    linked_timesheet_id uuid NULL,
    source_pay_method text NOT NULL,
    current_target_pay_method text NULL,
    source_basis_json jsonb NOT NULL,
    target_basis_json jsonb NULL,
    accepted_resolution_json jsonb NULL,
    source_amount numeric(12,2) NOT NULL,
    incoming_remaining_source_amount numeric(12,2) NULL,
    incoming_remaining_is_explicit boolean NOT NULL,
    relevant_erni_pct numeric NULL,
    allocation_priority_group integer NOT NULL,
    allocation_priority_order integer NOT NULL,
    current_basis_fingerprint text NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_sync_input;

  FOR v_line_json IN
    SELECT x.value
    FROM jsonb_array_elements(v_input_json) AS x(value)
  LOOP
    v_row_seq := v_row_seq + 1;

    IF v_line_json IS NULL OR jsonb_typeof(v_line_json) <> 'object' THEN
      RAISE EXCEPTION 'Each preview line must be a jsonb object (row %)', v_row_seq;
    END IF;

    v_raw_key_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'component_key_type'), ''),
        nullif(btrim(v_line_json->>'key_type'), ''),
        ''
      )
    );

    v_raw_key_value := coalesce(
      nullif(btrim(v_line_json->>'component_key_value'), ''),
      nullif(btrim(v_line_json->>'key_value'), ''),
      ''
    );

    v_raw_classification := upper(
      coalesce(
        nullif(btrim(v_line_json->>'classification'), ''),
        nullif(btrim(v_line_json->>'component_classification'), ''),
        ''
      )
    );

    v_raw_item_type := upper(
      coalesce(
        nullif(btrim(v_line_json->>'item_type'), ''),
        nullif(btrim(v_line_json->>'line_type'), ''),
        ''
      )
    );

    v_raw_source_ref := upper(coalesce(nullif(btrim(v_line_json->>'source_ref'), ''), ''));
    v_raw_expense_kind := upper(
      coalesce(
        nullif(btrim(v_line_json->>'expense_kind'), ''),
        nullif(btrim(v_line_json->>'expense_code'), ''),
        nullif(btrim(v_line_json->>'expense_type'), ''),
        ''
      )
    );

    v_component_key_type := NULL;
    v_component_key_value := NULL;

    IF v_raw_key_type <> '' THEN
      v_component_key_type := v_raw_key_type;
    ELSIF v_raw_item_type = 'SEGMENT_DELTA' THEN
      IF coalesce(nullif(btrim(v_line_json->>'work_date'), ''), nullif(btrim(v_line_json->>'date'), '')) ~ '^\d{4}-\d{2}-\d{2}$' THEN
        v_component_key_type := 'TS_DAY';
      ELSE
        v_component_key_type := 'TS_TOTAL';
      END IF;
    ELSIF v_raw_item_type = 'ADDITIONAL_DELTA'
       OR nullif(btrim(v_line_json->>'additional_code'), '') IS NOT NULL THEN
      v_component_key_type := 'ADDITIONAL_CODE';
    ELSIF v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA', 'EXPENSE_DELTA')
       OR v_raw_expense_kind <> '' THEN
      v_component_key_type := 'EXPENSE_CODE';
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
      IF v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
        v_component_key_type := 'TS_TOTAL';
      ELSE
        v_component_key_type := 'EXPENSE_CODE';
      END IF;
    ELSE
      v_component_key_type := 'CASE_TOTAL';
    END IF;

    IF v_raw_key_value <> '' THEN
      v_component_key_value := v_raw_key_value;
    ELSIF v_component_key_type = 'TS_DAY' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'work_date'), ''),
        nullif(btrim(v_line_json->>'date'), ''),
        'UNKNOWN_DAY'
      );
    ELSIF v_component_key_type = 'TS_TOTAL' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'segment_id'), ''),
        CASE
          WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NULL THEN 'TOTAL'
          ELSE coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        END
      );
    ELSIF v_component_key_type = 'ADDITIONAL_CODE' THEN
      v_component_key_value := coalesce(
        nullif(btrim(v_line_json->>'additional_code'), ''),
        nullif(btrim(v_line_json->>'source_ref'), ''),
        nullif(btrim(v_line_json->>'code'), ''),
        'TOTAL'
      );
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF v_raw_item_type = 'ADJUSTMENT_DELTA' THEN
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'adjustment_code'), ''),
          nullif(btrim(v_line_json->>'adjustment_id'), ''),
          nullif(btrim(v_line_json->>'source_ref'), ''),
          'ADJUSTMENT'
        );
      ELSE
        v_component_key_value := coalesce(
          nullif(btrim(v_line_json->>'expense_code'), ''),
          nullif(btrim(v_line_json->>'expense_kind'), ''),
          nullif(btrim(v_line_json->>'expense_type'), ''),
          nullif(btrim(v_line_json->>'item_type'), ''),
          'EXPENSE'
        );
      END IF;
    ELSE
      v_component_key_value := 'TOTAL';
    END IF;

    IF v_raw_classification IN ('TAXABLE_CHANNEL_SENSITIVE', 'REIMBURSEMENT_GROSS_FIXED', 'NET_PAY_FIXED_RECOVERY') THEN
      v_classification := v_raw_classification::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type IN ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE', 'CASE_TOTAL') THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_raw_item_type = 'ADJUSTMENT_DELTA'
       OR v_raw_source_ref LIKE 'ADJ:%'
       OR v_raw_source_ref LIKE 'PREVIEW_SEG:%' THEN
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    ELSIF v_component_key_type = 'EXPENSE_CODE' THEN
      IF upper(v_component_key_value) IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_expense_kind IN (
           'MILEAGE',
           'TRAVEL',
           'ACCOMMODATION',
           'OTHER',
           'EXPENSE',
           'EXPENSES',
           'MILEAGE_PAY_EX_VAT',
           'TRAVEL_PAY_EX_VAT',
           'ACCOMMODATION_PAY_EX_VAT',
           'OTHER_PAY_EX_VAT',
           'EXPENSES_PAY_EX_VAT'
         )
         OR v_raw_item_type IN ('MILEAGE_DELTA', 'TRAVEL_DELTA', 'ACCOMMODATION_DELTA', 'OTHER_DELTA')
         OR v_raw_source_ref LIKE 'MILEAGE:%'
         OR v_raw_source_ref LIKE 'TRAVEL:%'
         OR v_raw_source_ref LIKE 'ACCOMMODATION:%'
         OR v_raw_source_ref LIKE 'OTHER:%'
         OR v_raw_source_ref LIKE 'EXPENSE:%'
      THEN
        v_classification := 'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum;
      ELSE
        v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
      END IF;
    ELSE
      v_classification := 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum;
    END IF;

    v_source_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'source_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_current_target_pay_method := upper(
      coalesce(
        nullif(btrim(v_line_json->>'current_target_pay_method'), ''),
        nullif(btrim(v_line_json->>'target_pay_method'), ''),
        v_case_current_pay_method
      )
    );

    v_source_amount_text := nullif(btrim(v_line_json->>'source_amount'), '');
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      v_source_amount_text := nullif(btrim(v_line_json->>'amount_ex_vat'), '');
    END IF;
    IF v_source_amount_text IS NULL THEN
      RAISE EXCEPTION 'Preview line % is missing source_amount/amount/amount_ex_vat', v_row_seq;
    END IF;
    IF v_source_amount_text !~ '^-?\d+(\.\d+)?$' THEN
      RAISE EXCEPTION 'Preview line % has invalid source amount: %', v_row_seq, v_source_amount_text;
    END IF;
    v_source_amount := round(abs(v_source_amount_text::numeric), 2)::numeric(12,2);

    v_remaining_amount_text := nullif(btrim(v_line_json->>'remaining_source_amount'), '');
    v_incoming_remaining_is_explicit := v_remaining_amount_text IS NOT NULL;
    IF v_incoming_remaining_is_explicit THEN
      IF v_remaining_amount_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid remaining_source_amount: %', v_row_seq, v_remaining_amount_text;
      END IF;
      v_incoming_remaining_source_amount := round(abs(v_remaining_amount_text::numeric), 2)::numeric(12,2);
    ELSE
      v_incoming_remaining_source_amount := NULL;
    END IF;

    v_relevant_erni_text := nullif(
      btrim(
        coalesce(
          v_line_json->>'relevant_erni_pct',
          v_line_json->>'erni_pct'
        )
      ),
      ''
    );
    IF v_relevant_erni_text IS NOT NULL THEN
      IF v_relevant_erni_text !~ '^-?\d+(\.\d+)?$' THEN
        RAISE EXCEPTION 'Preview line % has invalid relevant_erni_pct: %', v_row_seq, v_relevant_erni_text;
      END IF;
      v_relevant_erni_pct := round(v_relevant_erni_text::numeric, 6);
    ELSE
      v_relevant_erni_pct := NULL;
    END IF;

    v_allocation_group_text := nullif(btrim(v_line_json->>'allocation_priority_group'), '');
    IF v_allocation_group_text IS NOT NULL THEN
      IF v_allocation_group_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_group: %', v_row_seq, v_allocation_group_text;
      END IF;
      v_allocation_priority_group := v_allocation_group_text::integer;
    ELSE
      v_allocation_priority_group := CASE
        WHEN v_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN 0
        ELSE 1
      END;
    END IF;

    v_allocation_order_text := nullif(btrim(v_line_json->>'allocation_priority_order'), '');
    IF v_allocation_order_text IS NOT NULL THEN
      IF v_allocation_order_text !~ '^-?\d+$' THEN
        RAISE EXCEPTION 'Preview line % has invalid allocation_priority_order: %', v_row_seq, v_allocation_order_text;
      END IF;
      v_allocation_priority_order := v_allocation_order_text::integer;
    ELSE
      v_allocation_priority_order := v_row_seq;
    END IF;

    IF v_line_json ? 'source_basis_json'
       AND jsonb_typeof(v_line_json->'source_basis_json') IN ('object', 'array') THEN
      v_source_basis_json := v_line_json->'source_basis_json';
    ELSE
      v_source_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'linked_timesheet_id', coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text),
          'work_date', nullif(btrim(v_line_json->>'work_date'), ''),
          'date', nullif(btrim(v_line_json->>'date'), ''),
          'segment_id', nullif(btrim(v_line_json->>'segment_id'), ''),
          'item_type', nullif(btrim(v_line_json->>'item_type'), ''),
          'line_type', nullif(btrim(v_line_json->>'line_type'), ''),
          'source_ref', nullif(btrim(v_line_json->>'source_ref'), ''),
          'additional_code', nullif(btrim(v_line_json->>'additional_code'), ''),
          'expense_code', nullif(btrim(v_line_json->>'expense_code'), ''),
          'expense_kind', nullif(btrim(v_line_json->>'expense_kind'), ''),
          'adjustment_code', nullif(btrim(v_line_json->>'adjustment_code'), ''),
          'rate_code', nullif(btrim(v_line_json->>'rate_code'), ''),
          'units', nullif(btrim(v_line_json->>'units'), ''),
          'hours', nullif(btrim(v_line_json->>'hours'), ''),
          'rate', nullif(btrim(v_line_json->>'rate'), '')
        )
      );
    END IF;

    IF v_line_json ? 'target_basis_json'
       AND jsonb_typeof(v_line_json->'target_basis_json') IN ('object', 'array') THEN
      v_target_basis_json := v_line_json->'target_basis_json';
    ELSE
      v_target_basis_json := jsonb_strip_nulls(
        jsonb_build_object(
          'current_target_pay_method', v_current_target_pay_method,
          'relevant_erni_pct', v_relevant_erni_pct
        )
      );
    END IF;

    v_line_accepted_resolution_json := NULL;
    IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_resolution_json';
    ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
    ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
      v_line_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
    END IF;

    v_source_family_key := coalesce(
      nullif(btrim(v_line_json->>'source_family_key'), ''),
      CASE
        WHEN coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text) IS NOT NULL
          THEN 'timesheet:' || coalesce(nullif(btrim(v_line_json->>'linked_timesheet_id'), ''), v_case_linked_timesheet_id::text)
        ELSE 'case:' || p_finance_case_id::text
      END
    );

    v_current_basis_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => v_source_family_key,
      p_component_key_type        => v_component_key_type,
      p_component_key_value       => v_component_key_value,
      p_classification            => v_classification,
      p_source_pay_method         => v_source_pay_method,
      p_current_target_pay_method => v_current_target_pay_method,
      p_source_basis_json         => v_source_basis_json,
      p_source_amount             => v_source_amount,
      p_relevant_erni_pct         => v_relevant_erni_pct,
      p_target_basis_json         => v_target_basis_json
    );

    v_line_candidate_id := coalesce(
      CASE
        WHEN nullif(btrim(v_line_json->>'candidate_id'), '') IS NULL THEN NULL
        ELSE (nullif(btrim(v_line_json->>'candidate_id'), ''))::uuid
      END,
      v_case_candidate_id
    );

    v_line_client_id := CASE
      WHEN nullif(btrim(v_line_json->>'client_id'), '') IS NULL THEN v_case_client_id
      ELSE (nullif(btrim(v_line_json->>'client_id'), ''))::uuid
    END;

    v_line_linked_timesheet_id := CASE
      WHEN nullif(btrim(v_line_json->>'linked_timesheet_id'), '') IS NULL THEN v_case_linked_timesheet_id
      ELSE (nullif(btrim(v_line_json->>'linked_timesheet_id'), ''))::uuid
    END;

    INSERT INTO pg_temp.tmp_pay_finance_component_sync_input (
      row_seq,
      source_family_key,
      component_key_type,
      component_key_value,
      classification,
      candidate_id,
      client_id,
      linked_timesheet_id,
      source_pay_method,
      current_target_pay_method,
      source_basis_json,
      target_basis_json,
      accepted_resolution_json,
      source_amount,
      incoming_remaining_source_amount,
      incoming_remaining_is_explicit,
      relevant_erni_pct,
      allocation_priority_group,
      allocation_priority_order,
      current_basis_fingerprint
    )
    VALUES (
      v_row_seq,
      v_source_family_key,
      v_component_key_type,
      v_component_key_value,
      v_classification,
      v_line_candidate_id,
      v_line_client_id,
      v_line_linked_timesheet_id,
      v_source_pay_method,
      v_current_target_pay_method,
      v_source_basis_json,
      v_target_basis_json,
      v_line_accepted_resolution_json,
      v_source_amount,
      v_incoming_remaining_source_amount,
      v_incoming_remaining_is_explicit,
      v_relevant_erni_pct,
      v_allocation_priority_group,
      v_allocation_priority_order,
      v_current_basis_fingerprint
    );
  END LOOP;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id uuid NOT NULL PRIMARY KEY,
    active_consumed_source_amount numeric(12,2) NOT NULL
  ) ON COMMIT DROP;

  TRUNCATE TABLE pg_temp.tmp_pay_finance_component_active_recovered;

  INSERT INTO pg_temp.tmp_pay_finance_component_active_recovered (
    finance_component_id,
    active_consumed_source_amount
  )
  SELECT
    settled_component_amounts.finance_component_id,
    round(sum(settled_component_amounts.component_source_amount), 2)::numeric(12,2) AS active_consumed_source_amount
  FROM (
    SELECT
      coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) AS finance_component_id,
      abs(coalesce(
        public.pay_advance_reservations.reserved_source_amount,
        public._pay_batch_item_source_reservation_amount_ex_vat(public.pay_batch_items.id),
        public.pay_batch_items.frozen_source_amount,
        public.pay_batch_items.amount_ex_vat,
        public.pay_batch_items.amount_inc_vat,
        public.pay_advance_reservations.reserved_amount,
        0
      )) AS component_source_amount
    FROM public.pay_batch_items
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    JOIN public.pay_batches
      ON public.pay_batches.id = public.pay_batch_candidates.pay_batch_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN public.pay_advance_reservations
      ON public.pay_advance_reservations.pay_batch_item_id = public.pay_batch_items.id
    WHERE coalesce(public.pay_batch_items.is_voided, false) = false
      AND coalesce(public.pay_advance_reservations.finance_case_id, public.pay_batch_items.finance_case_id) = p_finance_case_id
      AND coalesce(public.pay_advance_reservations.finance_component_id, public.pay_batch_items.finance_component_id) IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS applied_corrections
        WHERE applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND applied_corrections.status = 'APPLIED'
          AND applied_corrections.correction_item_kind IN (
            'PRE_BANK_CANCEL',
            'NO_MONEY_UNWIND',
            'SETTLED_REVERSAL'
          )
      )
      AND (
        upper(btrim(coalesce(public.pay_batch_candidates.settlement_status, ''))) = 'SETTLED'
        OR public.pay_batch_candidates.settled_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_bank_transfers.status, ''))) = 'COMPLETED'
        OR public.pay_bank_transfers.completed_at_utc IS NOT NULL
        OR upper(btrim(coalesce(public.pay_advance_reservations.status, ''))) = 'SETTLED'
        OR public.pay_advance_reservations.settled_at_utc IS NOT NULL
      )
  ) AS settled_component_amounts
  WHERE settled_component_amounts.finance_component_id IS NOT NULL
    AND round(coalesce(settled_component_amounts.component_source_amount, 0), 2) > 0
  GROUP BY settled_component_amounts.finance_component_id;

  FOR v_existing_component IN
    SELECT
      pfc.*
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.closed_at_utc IS NULL
      AND NOT EXISTS (
        SELECT 1
        FROM (
          SELECT DISTINCT ON (
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          )
            src.source_family_key,
            src.component_key_type,
            src.component_key_value
          FROM pg_temp.tmp_pay_finance_component_sync_input src
          ORDER BY
            src.source_family_key,
            src.component_key_type,
            src.component_key_value,
            src.row_seq DESC
        ) keep_rows
        WHERE keep_rows.source_family_key = pfc.source_family_key
          AND keep_rows.component_key_type = pfc.component_key_type
          AND keep_rows.component_key_value = pfc.component_key_value
      )
  LOOP
    v_before_json := jsonb_build_object(
      'candidate_id', v_existing_component.candidate_id::text,
      'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
      'source_family_key', v_existing_component.source_family_key,
      'component_key_type', v_existing_component.component_key_type,
      'component_key_value', v_existing_component.component_key_value,
      'classification', v_existing_component.classification::text,
      'source_pay_method', v_existing_component.source_pay_method,
      'source_basis_json', v_existing_component.source_basis_json,
      'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_existing_component.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
      'resolution_fingerprint', v_existing_component.resolution_fingerprint,
      'is_resolution_stale', v_existing_component.is_resolution_stale,
      'stale_reason', v_existing_component.stale_reason,
      'closed_at_utc', v_existing_component.closed_at_utc
    );

    SELECT EXISTS (
      SELECT 1
      FROM public.pay_finance_case_events AS protected_component_events
      WHERE protected_component_events.finance_case_id = p_finance_case_id
        AND protected_component_events.finance_component_id = v_existing_component.id
        AND (
          upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
          OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%RESTRUCT%'
          OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%MANUAL%'
        )
    )
    INTO v_component_has_protected_event;

    v_component_is_protected := (
      coalesce(v_component_has_protected_event, false)
      OR (
        coalesce(v_existing_component.is_resolution_stale, false) = true
        AND upper(coalesce(v_existing_component.saved_resolution_mode::text, '')) IN (
          'MANUAL_REPLACEMENT_RATE',
          'MANUAL_AMOUNT',
          'MANUAL_TOTAL',
          'MANUAL_GROSS_TOTAL',
          'MANUAL_OVERRIDE'
        )
      )
    );

    IF v_component_is_protected THEN
      INSERT INTO public.pay_finance_case_events (
        finance_case_id,
        finance_component_id,
        event_type,
        event_at_utc,
        actor_user_id,
        pay_batch_id,
        reservation_id,
        before_json,
        after_json,
        reason,
        note
      )
      VALUES (
        p_finance_case_id,
        v_existing_component.id,
        'SYNC_SKIPPED',
        v_now_utc,
        p_actor_user_id,
        NULL,
        NULL,
        v_before_json,
        jsonb_build_object(
          'sync_skipped', true,
          'reason', 'PROTECTED_COMPONENT_NOT_CLOSED',
          'has_protected_event', v_component_has_protected_event,
          'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
          'is_resolution_stale', v_existing_component.is_resolution_stale
        ),
        'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
        'Skipped closing finance component because it is manually resolved, stale, or already restructured.'
      );
      v_protected_skip_count := v_protected_skip_count + 1;
      CONTINUE;
    END IF;

    UPDATE public.pay_finance_case_components pfc
    SET
      remaining_source_amount = 0,
      is_resolution_stale = false,
      stale_reason = NULL,
      closed_at_utc = v_now_utc,
      updated_at_utc = v_now_utc
    WHERE pfc.id = v_existing_component.id
    RETURNING pfc.* INTO v_component_after;

    v_after_json := jsonb_build_object(
      'candidate_id', v_component_after.candidate_id::text,
      'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
      'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
      'source_family_key', v_component_after.source_family_key,
      'component_key_type', v_component_after.component_key_type,
      'component_key_value', v_component_after.component_key_value,
      'classification', v_component_after.classification::text,
      'source_pay_method', v_component_after.source_pay_method,
      'source_basis_json', v_component_after.source_basis_json,
      'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_component_after.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
      'resolution_fingerprint', v_component_after.resolution_fingerprint,
      'is_resolution_stale', v_component_after.is_resolution_stale,
      'stale_reason', v_component_after.stale_reason,
      'closed_at_utc', v_component_after.closed_at_utc
    );

    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      p_finance_case_id,
      v_existing_component.id,
      'COMPONENT_CLOSED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      v_before_json,
      v_after_json,
      'COMPONENT_SYNC',
      'Closed finance component because it no longer exists in the current preview/truth line set'
    );

    v_closed_count := v_closed_count + 1;
  END LOOP;

  FOR v_line_json IN
    SELECT to_jsonb(src.*)
    FROM (
      SELECT DISTINCT ON (
        src.source_family_key,
        src.component_key_type,
        src.component_key_value
      )
        src.row_seq,
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.classification,
        src.candidate_id,
        src.client_id,
        src.linked_timesheet_id,
        src.source_pay_method,
        src.current_target_pay_method,
        src.source_basis_json,
        src.target_basis_json,
        src.accepted_resolution_json,
        src.source_amount,
        src.incoming_remaining_source_amount,
        src.incoming_remaining_is_explicit,
        src.relevant_erni_pct,
        src.allocation_priority_group,
        src.allocation_priority_order,
        src.current_basis_fingerprint
      FROM pg_temp.tmp_pay_finance_component_sync_input src
      ORDER BY
        src.source_family_key,
        src.component_key_type,
        src.component_key_value,
        src.row_seq DESC
    ) src
    ORDER BY
      (src.source_basis_json->>'work_date') NULLS LAST,
      src.allocation_priority_group,
      src.allocation_priority_order,
      src.row_seq
  LOOP
    v_line_candidate_id := (v_line_json->>'candidate_id')::uuid;
    v_line_client_id := CASE
      WHEN nullif(v_line_json->>'client_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'client_id')::uuid
    END;
    v_line_linked_timesheet_id := CASE
      WHEN nullif(v_line_json->>'linked_timesheet_id', '') IS NULL THEN NULL
      ELSE (v_line_json->>'linked_timesheet_id')::uuid
    END;
    v_line_classification := (v_line_json->>'classification')::public.pay_finance_component_classification_enum;
    v_line_source_pay_method := v_line_json->>'source_pay_method';
    v_line_current_target_pay_method := coalesce(v_line_json->>'current_target_pay_method', '');
    v_line_source_basis_json := v_line_json->'source_basis_json';
    v_line_source_amount := round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2)::numeric(12,2);
    v_line_incoming_remaining_source_amount := CASE
      WHEN (v_line_json->>'incoming_remaining_is_explicit')::boolean
        THEN round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2)::numeric(12,2)
      ELSE NULL
    END;
    v_line_allocation_priority_group := (v_line_json->>'allocation_priority_group')::integer;
    v_line_allocation_priority_order := (v_line_json->>'allocation_priority_order')::integer;

    SELECT
      pfc.*
    INTO
      v_existing_component
    FROM public.pay_finance_case_components pfc
    WHERE pfc.finance_case_id = p_finance_case_id
      AND pfc.source_family_key = v_line_json->>'source_family_key'
      AND pfc.component_key_type = v_line_json->>'component_key_type'
      AND pfc.component_key_value = v_line_json->>'component_key_value'
      AND pfc.closed_at_utc IS NULL
    ORDER BY
      pfc.updated_at_utc DESC,
      pfc.created_at_utc DESC,
      pfc.id DESC
    LIMIT 1;

    IF FOUND THEN
      SELECT recovered_amounts.active_consumed_source_amount
      INTO v_active_consumed_amount
      FROM pg_temp.tmp_pay_finance_component_active_recovered AS recovered_amounts
      WHERE recovered_amounts.finance_component_id = v_existing_component.id;

      v_consumed_amount := coalesce(
        v_active_consumed_amount,
        greatest(
          round(coalesce(v_existing_component.source_amount, 0), 2) - round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
          0
        )::numeric(12,2)
      );

      IF (v_line_json->>'incoming_remaining_is_explicit')::boolean THEN
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'incoming_remaining_source_amount')::numeric, 0), 2),
          0
        )::numeric(12,2);
      ELSE
        v_new_remaining_source_amount := greatest(
          round(coalesce((v_line_json->>'source_amount')::numeric, 0), 2) - v_consumed_amount,
          0
        )::numeric(12,2);
      END IF;

      v_has_saved_resolution := (
        v_existing_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
        AND (
          v_existing_component.saved_target_pay_method IS NOT NULL
          OR v_existing_component.saved_resolution_mode IS NOT NULL
          OR v_existing_component.saved_resolution_payload_json IS NOT NULL
          OR v_existing_component.saved_resolution_result_json IS NOT NULL
          OR v_existing_component.resolution_fingerprint IS NOT NULL
          OR v_existing_component.is_resolution_stale = true
        )
      );

      IF v_has_saved_resolution THEN
        IF v_existing_component.saved_target_pay_method IS NOT NULL
           AND upper(v_existing_component.saved_target_pay_method) IS DISTINCT FROM upper(v_line_current_target_pay_method) THEN
          v_should_be_stale := true;
          v_stale_reason := 'TARGET_PAY_METHOD_CHANGED';
        ELSIF v_existing_component.resolution_fingerprint IS NOT NULL
              AND v_existing_component.resolution_fingerprint IS DISTINCT FROM (v_line_json->>'current_basis_fingerprint') THEN
          v_should_be_stale := true;
          v_stale_reason := 'COMPONENT_BASIS_CHANGED';
        ELSE
          v_should_be_stale := false;
          v_stale_reason := NULL;
        END IF;
      ELSE
        v_should_be_stale := false;
        v_stale_reason := NULL;
      END IF;

      v_before_json := jsonb_build_object(
        'candidate_id', v_existing_component.candidate_id::text,
        'client_id', CASE WHEN v_existing_component.client_id IS NULL THEN NULL ELSE v_existing_component.client_id::text END,
        'linked_timesheet_id', CASE WHEN v_existing_component.linked_timesheet_id IS NULL THEN NULL ELSE v_existing_component.linked_timesheet_id::text END,
        'source_family_key', v_existing_component.source_family_key,
        'component_key_type', v_existing_component.component_key_type,
        'component_key_value', v_existing_component.component_key_value,
        'classification', v_existing_component.classification::text,
        'source_pay_method', v_existing_component.source_pay_method,
        'source_basis_json', v_existing_component.source_basis_json,
        'source_amount', round(coalesce(v_existing_component.source_amount, 0), 2),
        'remaining_source_amount', round(coalesce(v_existing_component.remaining_source_amount, 0), 2),
        'saved_target_pay_method', v_existing_component.saved_target_pay_method,
        'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
        'resolution_fingerprint', v_existing_component.resolution_fingerprint,
        'is_resolution_stale', v_existing_component.is_resolution_stale,
        'stale_reason', v_existing_component.stale_reason,
        'closed_at_utc', v_existing_component.closed_at_utc
      );

      SELECT EXISTS (
        SELECT 1
        FROM public.pay_finance_case_events AS protected_component_events
        WHERE protected_component_events.finance_case_id = p_finance_case_id
          AND protected_component_events.finance_component_id = v_existing_component.id
          AND (
            upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
            OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%RESTRUCT%'
            OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%MANUAL%'
          )
      )
      INTO v_component_has_protected_event;

      v_component_is_protected := (
        coalesce(v_component_has_protected_event, false)
        OR (
          coalesce(v_existing_component.is_resolution_stale, false) = true
          AND upper(coalesce(v_existing_component.saved_resolution_mode::text, '')) IN (
            'MANUAL_REPLACEMENT_RATE',
            'MANUAL_AMOUNT',
            'MANUAL_TOTAL',
            'MANUAL_GROSS_TOTAL',
            'MANUAL_OVERRIDE'
          )
        )
      );

      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        v_accepted_resolution_fingerprint := coalesce(
          nullif(btrim(v_accepted_resolution_json->>'component_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'resolution_fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json->>'fingerprint'), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['component_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['resolution_fingerprints', v_existing_component.id::text]), ''),
          nullif(btrim(v_accepted_resolution_json #>> ARRAY['validation', 'component_fingerprints', v_existing_component.id::text]), '')
        );

        IF v_component_is_protected
           OR v_existing_component.closed_at_utc IS NOT NULL
           OR v_accepted_resolution_fingerprint IS NULL
           OR v_accepted_resolution_fingerprint IS DISTINCT FROM (v_line_json->>'current_basis_fingerprint') THEN
          RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'ACCEPTED_RESOLUTION_STALE',
            'code', 'ACCEPTED_RESOLUTION_STALE',
            'message', 'Accepted suggested correction resolution is stale or no longer matches the open finance component state.',
            'finance_case_id', p_finance_case_id::text,
            'finance_component_id', v_existing_component.id::text,
            'component_still_open', v_existing_component.closed_at_utc IS NULL,
            'has_protected_event', v_component_has_protected_event,
            'accepted_fingerprint', v_accepted_resolution_fingerprint,
            'current_fingerprint', v_line_json->>'current_basis_fingerprint'
          )::text;
        END IF;
      END IF;

      IF v_component_is_protected THEN
        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
            'has_protected_event', v_component_has_protected_event,
            'saved_resolution_mode', CASE WHEN v_existing_component.saved_resolution_mode IS NULL THEN NULL ELSE v_existing_component.saved_resolution_mode::text END,
            'is_resolution_stale', v_existing_component.is_resolution_stale
          ),
          'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
          'Skipped updating finance component because it is manually resolved, stale, or already restructured.'
        );
        v_protected_skip_count := v_protected_skip_count + 1;
        CONTINUE;
      END IF;

      IF round(coalesce(v_existing_component.source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_line_source_amount, 0), 2)
         OR round(coalesce(v_existing_component.remaining_source_amount, 0), 2) IS DISTINCT FROM round(coalesce(v_new_remaining_source_amount, 0), 2)
         OR v_existing_component.candidate_id IS DISTINCT FROM v_line_candidate_id
         OR v_existing_component.client_id IS DISTINCT FROM v_line_client_id
         OR v_existing_component.linked_timesheet_id IS DISTINCT FROM v_line_linked_timesheet_id
         OR v_existing_component.source_pay_method IS DISTINCT FROM v_line_source_pay_method
         OR v_existing_component.source_basis_json IS DISTINCT FROM v_line_source_basis_json
         OR v_existing_component.classification IS DISTINCT FROM v_line_classification
         OR v_existing_component.allocation_priority_group IS DISTINCT FROM v_line_allocation_priority_group
         OR v_existing_component.allocation_priority_order IS DISTINCT FROM v_line_allocation_priority_order
         OR v_existing_component.is_resolution_stale IS DISTINCT FROM v_should_be_stale
         OR v_existing_component.stale_reason IS DISTINCT FROM v_stale_reason
      THEN
        SELECT EXISTS (
          SELECT 1
          FROM public.pay_finance_case_events AS protected_component_events
          WHERE protected_component_events.finance_case_id = p_finance_case_id
            AND protected_component_events.finance_component_id = v_existing_component.id
            AND (
              upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%WRITE%OFF%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%RESTRUCT%'
              OR upper(btrim(coalesce(protected_component_events.event_type, ''))) LIKE '%MANUAL%'
            )
        )
        INTO v_component_has_protected_event;

        v_component_is_protected := coalesce(v_component_has_protected_event, false);

        IF v_component_is_protected THEN
          INSERT INTO public.pay_finance_case_events (
            finance_case_id,
            finance_component_id,
            event_type,
            event_at_utc,
            actor_user_id,
            pay_batch_id,
            reservation_id,
            before_json,
            after_json,
            reason,
            note
          )
          VALUES (
            p_finance_case_id,
            v_existing_component.id,
            'SYNC_SKIPPED',
            v_now_utc,
            p_actor_user_id,
            NULL,
            NULL,
            v_before_json,
            jsonb_build_object(
              'sync_skipped', true,
              'reason', 'PROTECTED_COMPONENT_NOT_UPDATED',
              'has_protected_event', v_component_has_protected_event
            ),
            'COMPONENT_SYNC_SKIPPED_PROTECTED_COMPONENT',
            'Skipped updating finance component because it is manually resolved, already restructured, or otherwise protected.'
          );
          v_protected_skip_count := v_protected_skip_count + 1;
          CONTINUE;
        END IF;

        UPDATE public.pay_finance_case_components pfc
        SET
          candidate_id = v_line_candidate_id,
          client_id = v_line_client_id,
          linked_timesheet_id = v_line_linked_timesheet_id,
          classification = v_line_classification,
          source_pay_method = v_line_source_pay_method,
          source_basis_json = v_line_source_basis_json,
          source_amount = round(coalesce(v_line_source_amount, 0), 2)::numeric(12,2),
          remaining_source_amount = round(coalesce(v_new_remaining_source_amount, 0), 2)::numeric(12,2),
          is_resolution_stale = v_should_be_stale,
          stale_reason = v_stale_reason,
          allocation_priority_group = v_line_allocation_priority_group,
          allocation_priority_order = v_line_allocation_priority_order,
          updated_at_utc = v_now_utc
        WHERE pfc.id = v_existing_component.id
        RETURNING pfc.* INTO v_component_after;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_existing_component.id,
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN 'COMPONENT_STALE'
            ELSE 'COMPONENT_UPDATED'
          END,
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          v_after_json,
          'COMPONENT_SYNC',
          CASE
            WHEN v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true
              THEN 'Updated finance component and marked saved taxable resolution stale because the basis or target pay method changed materially'
            ELSE 'Updated finance component from current preview/truth line set'
          END
        );

        IF v_existing_component.is_resolution_stale IS DISTINCT FROM true AND v_should_be_stale = true THEN
          v_stale_marked_count := v_stale_marked_count + 1;
        END IF;

        v_updated_count := v_updated_count + 1;
      END IF;
    ELSE
      v_accepted_resolution_json := NULL;
      IF jsonb_typeof(v_line_json->'accepted_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_resolution_json';
      ELSIF jsonb_typeof(v_line_json->'accepted_suggested_resolution_json') = 'object' THEN
        v_accepted_resolution_json := v_line_json->'accepted_suggested_resolution_json';
      ELSIF jsonb_typeof(v_line_json #> '{correction,accepted_resolution_json}') = 'object' THEN
        v_accepted_resolution_json := v_line_json #> '{correction,accepted_resolution_json}';
      END IF;

      IF v_accepted_resolution_json IS NOT NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'ACCEPTED_RESOLUTION_STALE',
          'code', 'ACCEPTED_RESOLUTION_STALE',
          'message', 'Accepted suggested correction resolution cannot be applied because the finance component is no longer open.',
          'finance_case_id', p_finance_case_id::text,
          'source_family_key', v_line_json->>'source_family_key',
          'component_key_type', v_line_json->>'component_key_type',
          'component_key_value', v_line_json->>'component_key_value',
          'component_still_open', false
        )::text;
      END IF;

      SELECT
        pfc.*
      INTO
        v_reopen_component
      FROM public.pay_finance_case_components pfc
      WHERE pfc.finance_case_id = p_finance_case_id
        AND pfc.source_family_key = v_line_json->>'source_family_key'
        AND pfc.component_key_type = v_line_json->>'component_key_type'
        AND pfc.component_key_value = v_line_json->>'component_key_value'
        AND pfc.closed_at_utc IS NOT NULL
      ORDER BY
        pfc.closed_at_utc DESC,
        pfc.updated_at_utc DESC,
        pfc.created_at_utc DESC,
        pfc.id DESC
      LIMIT 1;

      IF FOUND THEN
        v_before_json := jsonb_build_object(
          'candidate_id', v_reopen_component.candidate_id::text,
          'client_id', CASE WHEN v_reopen_component.client_id IS NULL THEN NULL ELSE v_reopen_component.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_reopen_component.linked_timesheet_id IS NULL THEN NULL ELSE v_reopen_component.linked_timesheet_id::text END,
          'source_family_key', v_reopen_component.source_family_key,
          'component_key_type', v_reopen_component.component_key_type,
          'component_key_value', v_reopen_component.component_key_value,
          'classification', v_reopen_component.classification::text,
          'source_pay_method', v_reopen_component.source_pay_method,
          'source_basis_json', v_reopen_component.source_basis_json,
          'source_amount', round(coalesce(v_reopen_component.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_reopen_component.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_reopen_component.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_reopen_component.saved_resolution_mode IS NULL THEN NULL ELSE v_reopen_component.saved_resolution_mode::text END,
          'resolution_fingerprint', v_reopen_component.resolution_fingerprint,
          'is_resolution_stale', v_reopen_component.is_resolution_stale,
          'stale_reason', v_reopen_component.stale_reason,
          'closed_at_utc', v_reopen_component.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_reopen_component.id,
          'SYNC_SKIPPED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          v_before_json,
          jsonb_build_object(
            'sync_skipped', true,
            'reason', 'CLOSED_COMPONENT_PRESERVED',
            'new_component_will_be_created', true,
            'source_family_key', v_line_json->>'source_family_key',
            'component_key_type', v_line_json->>'component_key_type',
            'component_key_value', v_line_json->>'component_key_value'
          ),
          'COMPONENT_SYNC_CLOSED_COMPONENT_PRESERVED',
          'Preserved closed finance component and created a new open component for the current preview/truth line set instead of silently reopening or overwriting the closed component.'
        );

        v_protected_skip_count := v_protected_skip_count + 1;
      END IF;
        v_created_component_id := gen_random_uuid();

        INSERT INTO public.pay_finance_case_components (
          id,
          finance_case_id,
          candidate_id,
          client_id,
          linked_timesheet_id,
          source_family_key,
          component_key_type,
          component_key_value,
          classification,
          source_pay_method,
          source_basis_json,
          source_amount,
          remaining_source_amount,
          saved_target_pay_method,
          saved_resolution_mode,
          saved_resolution_payload_json,
          saved_resolution_result_json,
          resolution_fingerprint,
          is_resolution_stale,
          stale_reason,
          allocation_priority_group,
          allocation_priority_order,
          created_at_utc,
          updated_at_utc,
          resolved_at_utc,
          closed_at_utc
        )
        VALUES (
          v_created_component_id,
          p_finance_case_id,
          v_line_candidate_id,
          v_line_client_id,
          v_line_linked_timesheet_id,
          v_line_json->>'source_family_key',
          v_line_json->>'component_key_type',
          v_line_json->>'component_key_value',
          v_line_classification,
          v_line_source_pay_method,
          v_line_source_basis_json,
          round(coalesce(v_line_source_amount, 0), 2)::numeric(12,2),
          round(
            coalesce(
              CASE
                WHEN (v_line_json->>'incoming_remaining_is_explicit')::boolean
                  THEN (v_line_json->>'incoming_remaining_source_amount')::numeric
                ELSE (v_line_json->>'source_amount')::numeric
              END,
              0
            ),
            2
          )::numeric(12,2),
          NULL,
          NULL,
          NULL,
          NULL,
          NULL,
          false,
          NULL,
          v_line_allocation_priority_group,
          v_line_allocation_priority_order,
          v_now_utc,
          v_now_utc,
          NULL,
          NULL
        );

        SELECT
          pfc.*
        INTO
          v_component_after
        FROM public.pay_finance_case_components pfc
        WHERE pfc.id = v_created_component_id;

        v_after_json := jsonb_build_object(
          'candidate_id', v_component_after.candidate_id::text,
          'client_id', CASE WHEN v_component_after.client_id IS NULL THEN NULL ELSE v_component_after.client_id::text END,
          'linked_timesheet_id', CASE WHEN v_component_after.linked_timesheet_id IS NULL THEN NULL ELSE v_component_after.linked_timesheet_id::text END,
          'source_family_key', v_component_after.source_family_key,
          'component_key_type', v_component_after.component_key_type,
          'component_key_value', v_component_after.component_key_value,
          'classification', v_component_after.classification::text,
          'source_pay_method', v_component_after.source_pay_method,
          'source_basis_json', v_component_after.source_basis_json,
          'source_amount', round(coalesce(v_component_after.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(v_component_after.remaining_source_amount, 0), 2),
          'saved_target_pay_method', v_component_after.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN v_component_after.saved_resolution_mode IS NULL THEN NULL ELSE v_component_after.saved_resolution_mode::text END,
          'resolution_fingerprint', v_component_after.resolution_fingerprint,
          'is_resolution_stale', v_component_after.is_resolution_stale,
          'stale_reason', v_component_after.stale_reason,
          'closed_at_utc', v_component_after.closed_at_utc
        );

        INSERT INTO public.pay_finance_case_events (
          finance_case_id,
          finance_component_id,
          event_type,
          event_at_utc,
          actor_user_id,
          pay_batch_id,
          reservation_id,
          before_json,
          after_json,
          reason,
          note
        )
        VALUES (
          p_finance_case_id,
          v_created_component_id,
          'COMPONENT_CREATED',
          v_now_utc,
          p_actor_user_id,
          NULL,
          NULL,
          NULL,
          v_after_json,
          'COMPONENT_SYNC',
          'Created finance component from current preview/truth line set'
        );

        v_inserted_count := v_inserted_count + 1;
    END IF;
  END LOOP;

  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'id', pfc.id::text,
          'finance_case_id', pfc.finance_case_id::text,
          'candidate_id', pfc.candidate_id::text,
          'client_id', CASE WHEN pfc.client_id IS NULL THEN NULL ELSE pfc.client_id::text END,
          'linked_timesheet_id', CASE WHEN pfc.linked_timesheet_id IS NULL THEN NULL ELSE pfc.linked_timesheet_id::text END,
          'source_family_key', pfc.source_family_key,
          'component_key_type', pfc.component_key_type,
          'component_key_value', pfc.component_key_value,
          'classification', pfc.classification::text,
          'source_pay_method', pfc.source_pay_method,
          'source_amount', round(coalesce(pfc.source_amount, 0), 2),
          'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
          'saved_target_pay_method', pfc.saved_target_pay_method,
          'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
          'is_resolution_stale', pfc.is_resolution_stale,
          'stale_reason', pfc.stale_reason,
          'allocation_priority_group', pfc.allocation_priority_group,
          'allocation_priority_order', pfc.allocation_priority_order,
          'created_at_utc', pfc.created_at_utc,
          'updated_at_utc', pfc.updated_at_utc
        )
        ORDER BY
          pfc.source_family_key,
          pfc.allocation_priority_group,
          pfc.allocation_priority_order,
          pfc.component_key_type,
          pfc.component_key_value
      ),
      '[]'::jsonb
    )
  INTO
    v_open_components_json
  FROM public.pay_finance_case_components pfc
  WHERE pfc.finance_case_id = p_finance_case_id
    AND pfc.closed_at_utc IS NULL;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_RESULT',
    jsonb_build_object(
      'finance_case_id', p_finance_case_id,
      'inserted_count', v_inserted_count,
      'updated_count', v_updated_count,
      'reopened_count', v_reopened_count,
      'closed_count', v_closed_count,
      'stale_marked_count', v_stale_marked_count,
      'protected_skip_count', v_protected_skip_count
    ),
    'pay_finance_components',
    p_finance_case_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'inserted_count', v_inserted_count,
    'updated_count', v_updated_count,
    'reopened_count', v_reopened_count,
    'closed_count', v_closed_count,
    'stale_marked_count', v_stale_marked_count,
    'protected_skip_count', v_protected_skip_count,
    'open_components', v_open_components_json
  );
EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAY_FINANCE_COMPONENTS_SYNC_FROM_PREVIEW_ERROR',
      jsonb_build_object(
        'finance_case_id', p_finance_case_id,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_finance_components',
      COALESCE(p_finance_case_id::text, 'NO_FINANCE_CASE_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );
    RAISE;
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_finance_component_resolutions_apply(
  p_candidate_id uuid,
  p_component_resolutions jsonb,
  p_actor_user_id uuid,
  p_finance_case_id uuid DEFAULT NULL::uuid,
  p_reason text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_now_utc timestamptz := now();
  v_today_uk date := (now() at time zone 'Europe/London')::date;

  v_candidate record;
  v_finance_settings record;

  v_input_json jsonb := coalesce(p_component_resolutions, '[]'::jsonb);
  v_resolution_json jsonb;
  v_row_seq integer := 0;

  v_component_id_text text;
  v_component_id uuid;
  v_resolution_mode_text text;
  v_target_pay_method text;
  v_resolution_mode public.pay_finance_component_resolution_mode_enum;

  v_component record;

  v_before_json jsonb := null;
  v_after_json jsonb := null;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_target_units numeric := null;
  v_manual_replacement_rate numeric := null;
  v_manual_amount_ex_vat numeric := null;
  v_requested_target_units numeric := null;

  v_source_units numeric := null;
  v_source_rate numeric := null;
  v_source_charge_rate numeric := null;
  v_bucket_code text := null;
  v_component_semantics text := null;
  v_is_rate_bearing_row boolean := false;
  v_is_amount_led_row boolean := false;

  v_basis_amount_ex_vat numeric(12,2) := 0;
  v_target_amount_ex_vat numeric(12,2) := 0;
  v_target_amount_vat numeric(12,2) := 0;
  v_target_amount_inc_vat numeric(12,2) := 0;
  v_rate_precision numeric := null;

  v_target_amount_ex_vat_per_source numeric(18,10) := 0;
  v_target_amount_vat_per_source numeric(18,10) := 0;
  v_target_amount_inc_vat_per_source numeric(18,10) := 0;
  v_target_units_per_source numeric(18,10) := null;

  v_target_amounts_json jsonb := '{}'::jsonb;
  v_target_basis_json jsonb := '{}'::jsonb;
  v_resolution_payload_json jsonb := '{}'::jsonb;
  v_resolution_result_json jsonb := '{}'::jsonb;
  v_resolution_fingerprint text := null;

  v_applied_components jsonb := '[]'::jsonb;
  v_event_reason text := null;
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_ID_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: candidate_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: actor_user_id is required'
    )::text;
  END IF;

  IF jsonb_typeof(v_input_json) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'COMPONENT_RESOLUTIONS_ARRAY_REQUIRED',
      'message', 'pay_finance_component_resolutions_apply: component_resolutions must be a JSON array'
    )::text;
  END IF;

  SELECT
    c.id,
    upper(coalesce(c.pay_method, '')) AS pay_method
  INTO v_candidate
  FROM public.candidates c
  WHERE c.id = p_candidate_id
  LIMIT 1;

  IF v_candidate.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_finance_component_resolutions_apply: candidate not found',
      'candidate_id', p_candidate_id::text
    )::text;
  END IF;

  IF v_candidate.pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'CANDIDATE_PAY_METHOD_INVALID',
      'message', 'pay_finance_component_resolutions_apply: candidate pay_method must be PAYE or UMBRELLA',
      'candidate_id', p_candidate_id::text,
      'candidate_pay_method', v_candidate.pay_method
    )::text;
  END IF;

  SELECT
    sfp.vat_rate_pct,
    sfp.erni_pct
  INTO v_finance_settings
  FROM public.settings_finance_pick(v_today_uk) sfp
  LIMIT 1;

  IF v_finance_settings.vat_rate_pct IS NULL OR v_finance_settings.erni_pct IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_finance_component_resolutions_apply: finance settings missing vat_rate_pct and/or erni_pct'
    )::text;
  END IF;

  IF jsonb_array_length(v_input_json) = 0 THEN
    RETURN jsonb_build_object(
      'ok', true,
      'candidate_id', p_candidate_id::text,
      'finance_case_id', CASE WHEN p_finance_case_id IS NULL THEN NULL ELSE p_finance_case_id::text END,
      'applied_count', 0,
      'components', '[]'::jsonb
    );
  END IF;

  FOR v_resolution_json IN
    SELECT t_resolution.value
    FROM jsonb_array_elements(v_input_json) AS t_resolution(value)
  LOOP
    v_row_seq := v_row_seq + 1;

    IF v_resolution_json IS NULL OR jsonb_typeof(v_resolution_json) <> 'object' THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'INVALID_RESOLUTION_ROW',
        'message', 'pay_finance_component_resolutions_apply: each resolution row must be a JSON object',
        'row_index', v_row_seq
      )::text;
    END IF;

    v_component_id_text := nullif(btrim(coalesce(v_resolution_json->>'finance_component_id', '')), '');
    IF v_component_id_text IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_ID_REQUIRED',
        'message', 'pay_finance_component_resolutions_apply: finance_component_id is required for every resolution row',
        'row_index', v_row_seq
      )::text;
    END IF;

    BEGIN
      v_component_id := v_component_id_text::uuid;
    EXCEPTION WHEN others THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_ID_INVALID',
        'message', 'pay_finance_component_resolutions_apply: finance_component_id must be a valid UUID',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id_text
      )::text;
    END;

    v_resolution_mode_text := upper(coalesce(nullif(btrim(coalesce(v_resolution_json->>'resolution_mode', '')), ''), ''));
    IF v_resolution_mode_text NOT IN ('SUGGESTED_EQUIVALENT_BASIS', 'MANUAL_REPLACEMENT_RATE', 'MANUAL_AMOUNT') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'RESOLUTION_MODE_INVALID',
        'message', 'pay_finance_component_resolutions_apply: resolution_mode must be SUGGESTED_EQUIVALENT_BASIS, MANUAL_REPLACEMENT_RATE, or MANUAL_AMOUNT',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'resolution_mode', v_resolution_mode_text
      )::text;
    END IF;
    v_resolution_mode := v_resolution_mode_text::public.pay_finance_component_resolution_mode_enum;

    v_target_pay_method := upper(
      coalesce(
        nullif(btrim(coalesce(v_resolution_json->>'target_pay_method', '')), ''),
        v_candidate.pay_method
      )
    );

    IF v_target_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'TARGET_PAY_METHOD_INVALID',
        'message', 'pay_finance_component_resolutions_apply: target_pay_method must be PAYE or UMBRELLA',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'target_pay_method', v_target_pay_method
      )::text;
    END IF;

    IF v_target_pay_method IS DISTINCT FROM v_candidate.pay_method THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'TARGET_PAY_METHOD_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: target_pay_method must match the candidate current pay_method',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'target_pay_method', v_target_pay_method,
        'candidate_pay_method', v_candidate.pay_method
      )::text;
    END IF;

    SELECT
      pfc.id,
      pfc.finance_case_id,
      pfc.candidate_id,
      pfc.client_id,
      pfc.linked_timesheet_id,
      pfc.source_family_key,
      pfc.component_key_type,
      pfc.component_key_value,
      pfc.classification,
      upper(coalesce(pfc.source_pay_method, '')) AS source_pay_method,
      pfc.source_basis_json,
      round(coalesce(pfc.source_amount, 0), 2) AS source_amount,
      round(coalesce(pfc.remaining_source_amount, 0), 2) AS remaining_source_amount,
      pfc.saved_target_pay_method,
      pfc.saved_resolution_mode,
      pfc.saved_resolution_payload_json,
      pfc.saved_resolution_result_json,
      pfc.resolution_fingerprint,
      pfc.is_resolution_stale,
      pfc.stale_reason,
      pfc.resolved_at_utc,
      pfc.closed_at_utc,
      pa.case_type,
      pa.status AS finance_case_status
    INTO v_component
    FROM public.pay_finance_case_components pfc
    JOIN public.pay_advances pa
      ON pa.id = pfc.finance_case_id
    WHERE pfc.id = v_component_id
    FOR UPDATE;

    IF v_component.id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_NOT_FOUND',
        'message', 'pay_finance_component_resolutions_apply: finance component not found',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text
      )::text;
    END IF;

    IF v_component.candidate_id IS DISTINCT FROM p_candidate_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_CANDIDATE_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: finance component does not belong to the specified candidate',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'candidate_id', p_candidate_id::text,
        'component_candidate_id', v_component.candidate_id::text
      )::text;
    END IF;

    IF p_finance_case_id IS NOT NULL AND v_component.finance_case_id IS DISTINCT FROM p_finance_case_id THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_CASE_MISMATCH',
        'message', 'pay_finance_component_resolutions_apply: finance component does not belong to the specified finance case',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'finance_case_id', p_finance_case_id::text,
        'component_finance_case_id', v_component.finance_case_id::text
      )::text;
    END IF;

    IF v_component.closed_at_utc IS NOT NULL OR round(coalesce(v_component.remaining_source_amount, 0), 2) <= 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'FINANCE_COMPONENT_NOT_OPEN',
        'message', 'pay_finance_component_resolutions_apply: finance component must be open with remaining_source_amount > 0',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'closed_at_utc', v_component.closed_at_utc,
        'remaining_source_amount', round(coalesce(v_component.remaining_source_amount, 0), 2)
      )::text;
    END IF;

    IF v_component.classification IS DISTINCT FROM 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'REIMBURSEMENT_RESOLUTION_NOT_ALLOWED',
        'message', 'pay_finance_component_resolutions_apply: reimbursement components cannot be resolved through this path',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'classification', v_component.classification::text
      )::text;
    END IF;

    IF v_component.source_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'SOURCE_PAY_METHOD_INVALID',
        'message', 'pay_finance_component_resolutions_apply: source_pay_method must be PAYE or UMBRELLA on the component',
        'row_index', v_row_seq,
        'finance_component_id', v_component_id::text,
        'source_pay_method', v_component.source_pay_method
      )::text;
    END IF;

    v_source_units := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_units', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_units')::numeric, 6)
      ELSE NULL
    END;
    v_source_rate := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_rate')::numeric, 6)
      ELSE NULL
    END;
    v_source_charge_rate := CASE
      WHEN coalesce(v_component.source_basis_json->>'source_charge_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_component.source_basis_json->>'source_charge_rate')::numeric, 6)
      ELSE NULL
    END;
    v_bucket_code := nullif(upper(btrim(coalesce(v_component.source_basis_json->>'bucket_code', ''))), '');
    v_is_rate_bearing_row := (
      v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum
      and v_component.component_key_type in ('TS_DAY', 'TS_TOTAL', 'ADDITIONAL_CODE')
      and v_component.component_key_type <> 'ADJUSTMENT_CODE'
      and v_source_units is not null
      and v_source_units > 0
      and v_source_rate is not null
      and v_source_charge_rate is not null
    );
    v_is_amount_led_row := not v_is_rate_bearing_row;
    v_component_semantics := case when v_is_rate_bearing_row then 'RATE_BEARING' else 'AMOUNT_LED' end;

    v_basis_amount_ex_vat := round(coalesce(v_component.remaining_source_amount, 0), 2)::numeric(12,2);

    v_relevant_erni_pct := CASE
      WHEN coalesce(v_resolution_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'relevant_erni_pct')::numeric, 6)
      WHEN coalesce(v_component.saved_resolution_payload_json->>'relevant_erni_pct', v_component.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round(coalesce(v_component.saved_resolution_payload_json->>'relevant_erni_pct', v_component.saved_resolution_result_json->>'relevant_erni_pct')::numeric, 6)
      ELSE round(v_finance_settings.erni_pct, 6)
    END;

    v_vat_rate_pct := CASE
      WHEN coalesce(v_resolution_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'vat_rate_pct')::numeric, 6)
      WHEN coalesce(v_component.saved_resolution_payload_json->>'vat_rate_pct', v_component.saved_resolution_result_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
        THEN round(coalesce(v_component.saved_resolution_payload_json->>'vat_rate_pct', v_component.saved_resolution_result_json->>'vat_rate_pct')::numeric, 6)
      ELSE round(v_finance_settings.vat_rate_pct, 6)
    END;

    v_umbrella_vat_chargeable := coalesce(
      CASE
        WHEN lower(coalesce(v_resolution_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_resolution_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.saved_resolution_result_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.saved_resolution_result_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.source_basis_json->>'umbrella_vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.source_basis_json->>'umbrella_vat_chargeable')::boolean
        ELSE NULL
      END,
      CASE
        WHEN lower(coalesce(v_component.source_basis_json->>'vat_chargeable', '')) IN ('true', 'false')
          THEN (v_component.source_basis_json->>'vat_chargeable')::boolean
        ELSE NULL
      END,
      false
    );

    v_target_units := CASE
      WHEN coalesce(v_resolution_json->>'target_units', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_units')::numeric, 6)
      ELSE NULL
    END;
    v_requested_target_units := v_target_units;

    v_manual_replacement_rate := CASE
      WHEN coalesce(v_resolution_json->>'replacement_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'replacement_rate')::numeric, 6)
      WHEN coalesce(v_resolution_json->>'manual_replacement_rate', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'manual_replacement_rate')::numeric, 6)
      ELSE NULL
    END;

    v_manual_amount_ex_vat := CASE
      WHEN coalesce(v_resolution_json->>'target_amount_ex_vat', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_amount_ex_vat')::numeric, 2)
      WHEN coalesce(v_resolution_json->>'target_amount', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'target_amount')::numeric, 2)
      WHEN coalesce(v_resolution_json->>'manual_amount_ex_vat', '') ~ '^-?\d+(\.\d+)?$'
        THEN round((v_resolution_json->>'manual_amount_ex_vat')::numeric, 2)
      ELSE NULL
    END;

    IF v_is_rate_bearing_row AND v_resolution_mode = 'MANUAL_AMOUNT'::public.pay_finance_component_resolution_mode_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'MANUAL_AMOUNT_NOT_ALLOWED_FOR_RATE_BEARING_COMPONENT',
        'message', 'pay_finance_component_resolutions_apply: MANUAL_AMOUNT is not allowed for genuine rate-bearing taxable rows',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'component_semantics', v_component_semantics
      )::text;
    END IF;

    IF v_is_amount_led_row AND v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'MANUAL_REPLACEMENT_RATE_NOT_ALLOWED_FOR_AMOUNT_LED_COMPONENT',
        'message', 'pay_finance_component_resolutions_apply: MANUAL_REPLACEMENT_RATE is only allowed for genuine rate-bearing taxable rows',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'component_semantics', v_component_semantics
      )::text;
    END IF;

    IF v_is_rate_bearing_row THEN
      IF v_target_units IS NULL THEN
        v_target_units := round(v_source_units, 6);
      END IF;

      IF round(coalesce(v_target_units, 0), 6) <> round(coalesce(v_source_units, 0), 6) THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'RATE_BEARING_TARGET_UNITS_MISMATCH',
          'message', 'pay_finance_component_resolutions_apply: rate-bearing rows must preserve exact source units',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'source_units', v_source_units,
          'target_units', v_target_units
        )::text;
      END IF;
    ELSE
      v_target_units := NULL;
    END IF;

    v_target_amount_ex_vat := null;
    v_target_amount_vat := null;
    v_target_amount_inc_vat := null;
    v_target_amounts_json := '{}'::jsonb;
    v_target_basis_json := '{}'::jsonb;
    v_resolution_payload_json := '{}'::jsonb;
    v_resolution_result_json := '{}'::jsonb;
    v_resolution_fingerprint := null;
    v_target_amount_ex_vat_per_source := 0;
    v_target_amount_vat_per_source := 0;
    v_target_amount_inc_vat_per_source := 0;
    v_target_units_per_source := null;

    v_before_json := jsonb_build_object(
      'finance_component_id', v_component.id::text,
      'finance_case_id', v_component.finance_case_id::text,
      'classification', v_component.classification::text,
      'source_pay_method', v_component.source_pay_method,
      'source_basis_json', v_component.source_basis_json,
      'source_amount', round(coalesce(v_component.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(v_component.remaining_source_amount, 0), 2),
      'saved_target_pay_method', v_component.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN v_component.saved_resolution_mode IS NULL THEN NULL ELSE v_component.saved_resolution_mode::text END,
      'saved_resolution_payload_json', v_component.saved_resolution_payload_json,
      'saved_resolution_result_json', v_component.saved_resolution_result_json,
      'source_units', v_source_units,
      'source_rate', v_source_rate,
      'source_charge_rate', v_source_charge_rate,
      'bucket_code', v_bucket_code,
      'component_semantics', v_component_semantics,
      'is_rate_bearing_row', v_is_rate_bearing_row,
      'is_amount_led_row', v_is_amount_led_row,
      'resolution_fingerprint', v_component.resolution_fingerprint,
      'is_resolution_stale', v_component.is_resolution_stale,
      'stale_reason', v_component.stale_reason,
      'resolved_at_utc', v_component.resolved_at_utc
    );

    IF v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN
      IF v_component.source_pay_method = 'PAYE' AND v_target_pay_method = 'UMBRELLA' THEN
        v_target_amounts_json := public._pay_convert_paye_to_umbrella(
          v_basis_amount_ex_vat,
          v_relevant_erni_pct,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      ELSIF v_component.source_pay_method = 'UMBRELLA' AND v_target_pay_method = 'PAYE' THEN
        v_target_amount_ex_vat := public._pay_convert_umbrella_to_paye_ex(v_basis_amount_ex_vat, v_relevant_erni_pct);
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSIF v_component.source_pay_method = v_target_pay_method AND v_target_pay_method = 'PAYE' THEN
        v_target_amount_ex_vat := v_basis_amount_ex_vat;
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSIF v_component.source_pay_method = v_target_pay_method AND v_target_pay_method = 'UMBRELLA' THEN
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_basis_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      ELSE
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'UNSUPPORTED_SUGGESTED_CONVERSION',
          'message', 'pay_finance_component_resolutions_apply: unsupported suggested-equivalent conversion pair',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'source_pay_method', v_component.source_pay_method,
          'target_pay_method', v_target_pay_method
        )::text;
      END IF;

      IF v_target_units IS NOT NULL THEN
        IF v_target_units <= 0 THEN
          RAISE EXCEPTION '%', jsonb_build_object(
            'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
            'code', 'TARGET_UNITS_INVALID',
            'message', 'pay_finance_component_resolutions_apply: target_units must be > 0 when provided for suggested equivalent basis',
            'row_index', v_row_seq,
            'finance_component_id', v_component.id::text,
            'target_units', v_target_units
          )::text;
        END IF;
        v_rate_precision := round(v_target_amount_ex_vat / v_target_units, 6);
      ELSE
        v_rate_precision := null;
      END IF;
    ELSIF v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN
      IF v_target_units IS NULL OR v_target_units <= 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'TARGET_UNITS_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: target_units must be > 0 for MANUAL_REPLACEMENT_RATE',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'target_units', v_target_units
        )::text;
      END IF;

      IF v_manual_replacement_rate IS NULL OR v_manual_replacement_rate < 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'REPLACEMENT_RATE_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: replacement_rate must be >= 0 for MANUAL_REPLACEMENT_RATE',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'replacement_rate', v_manual_replacement_rate
        )::text;
      END IF;

      v_target_amount_ex_vat := round(v_target_units * v_manual_replacement_rate, 2);

      IF v_target_pay_method = 'PAYE' THEN
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSE
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_target_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      END IF;

      v_rate_precision := round(v_manual_replacement_rate, 6);
    ELSE
      IF v_manual_amount_ex_vat IS NULL OR v_manual_amount_ex_vat < 0 THEN
        RAISE EXCEPTION '%', jsonb_build_object(
          'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
          'code', 'TARGET_AMOUNT_REQUIRED',
          'message', 'pay_finance_component_resolutions_apply: target_amount_ex_vat must be >= 0 for MANUAL_AMOUNT',
          'row_index', v_row_seq,
          'finance_component_id', v_component.id::text,
          'target_amount_ex_vat', v_manual_amount_ex_vat
        )::text;
      END IF;

      v_target_amount_ex_vat := round(v_manual_amount_ex_vat, 2);

      IF v_target_pay_method = 'PAYE' THEN
        v_target_amount_vat := 0;
        v_target_amount_inc_vat := v_target_amount_ex_vat;
      ELSE
        v_target_amounts_json := public._pay_umbrella_vat_calc(
          v_target_amount_ex_vat,
          v_vat_rate_pct,
          v_umbrella_vat_chargeable
        );
        v_target_amount_ex_vat := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
        v_target_amount_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
        v_target_amount_inc_vat := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
      END IF;

      v_rate_precision := null;
    END IF;

    IF v_basis_amount_ex_vat <= 0 THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_COMPONENT_RESOLUTIONS_APPLY',
        'code', 'BASIS_AMOUNT_INVALID',
        'message', 'pay_finance_component_resolutions_apply: basis_source_amount_ex_vat must be > 0',
        'row_index', v_row_seq,
        'finance_component_id', v_component.id::text,
        'basis_source_amount_ex_vat', v_basis_amount_ex_vat
      )::text;
    END IF;

    v_target_amount_ex_vat_per_source := round(v_target_amount_ex_vat / v_basis_amount_ex_vat, 10);
    v_target_amount_vat_per_source := round(v_target_amount_vat / v_basis_amount_ex_vat, 10);
    v_target_amount_inc_vat_per_source := round(v_target_amount_inc_vat / v_basis_amount_ex_vat, 10);
    v_target_units_per_source := CASE
      WHEN v_target_units IS NOT NULL THEN round(v_target_units / v_basis_amount_ex_vat, 10)
      ELSE NULL
    END;

    v_target_basis_json := jsonb_strip_nulls(
      jsonb_build_object(
        'target_pay_method', v_target_pay_method,
        'calculation_kind', v_resolution_mode::text,
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'replacement_rate', CASE WHEN v_resolution_mode = 'MANUAL_REPLACEMENT_RATE'::public.pay_finance_component_resolution_mode_enum THEN round(v_manual_replacement_rate, 6) ELSE NULL END,
        'target_amount_ex_vat_per_source_ex_vat', v_target_amount_ex_vat_per_source,
        'target_amount_vat_per_source_ex_vat', v_target_amount_vat_per_source,
        'target_amount_inc_vat_per_source_ex_vat', v_target_amount_inc_vat_per_source,
        'target_units_per_source_ex_vat', v_target_units_per_source,
        'suggested_target_rate', CASE WHEN v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN v_rate_precision ELSE NULL END
      )
    );

    v_resolution_payload_json := jsonb_strip_nulls(
      jsonb_build_object(
        'resolution_mode', v_resolution_mode::text,
        'target_pay_method', v_target_pay_method,
        'applied_basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'requested_target_units', CASE WHEN v_requested_target_units IS NULL THEN NULL ELSE round(v_requested_target_units, 6) END,
        'target_units', CASE WHEN v_target_units IS NULL THEN NULL ELSE round(v_target_units, 6) END,
        'replacement_rate', CASE WHEN v_manual_replacement_rate IS NULL THEN NULL ELSE round(v_manual_replacement_rate, 6) END,
        'manual_amount_ex_vat', CASE WHEN v_manual_amount_ex_vat IS NULL THEN NULL ELSE round(v_manual_amount_ex_vat, 2) END,
        'suggested_target_rate', CASE WHEN v_resolution_mode = 'SUGGESTED_EQUIVALENT_BASIS'::public.pay_finance_component_resolution_mode_enum THEN v_rate_precision ELSE NULL END,
        'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
      )
    );

    v_resolution_result_json := jsonb_strip_nulls(
      jsonb_build_object(
        'target_pay_method', v_target_pay_method,
        'target_amount_ex_vat', round(v_target_amount_ex_vat, 2),
        'target_amount_vat', round(v_target_amount_vat, 2),
        'target_amount_inc_vat', round(v_target_amount_inc_vat, 2),
        'basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'applied_basis_source_amount_ex_vat', round(v_basis_amount_ex_vat, 2),
        'relevant_erni_pct', round(v_relevant_erni_pct, 6),
        'vat_rate_pct', round(v_vat_rate_pct, 6),
        'umbrella_vat_chargeable', v_umbrella_vat_chargeable,
        'bucket_code', v_bucket_code,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'requested_target_units', CASE WHEN v_requested_target_units IS NULL THEN NULL ELSE round(v_requested_target_units, 6) END,
        'target_units', CASE WHEN v_target_units IS NULL THEN NULL ELSE round(v_target_units, 6) END,
        'replacement_rate', CASE WHEN v_manual_replacement_rate IS NULL THEN NULL ELSE round(v_manual_replacement_rate, 6) END,
        'target_amount_ex_vat_per_source_ex_vat', v_target_amount_ex_vat_per_source,
        'target_amount_vat_per_source_ex_vat', v_target_amount_vat_per_source,
        'target_amount_inc_vat_per_source_ex_vat', v_target_amount_inc_vat_per_source,
        'target_units_per_source_ex_vat', v_target_units_per_source,
        'reuse_mode', 'PROPORTIONAL_TO_REMAINING_SOURCE_AMOUNT'
      )
    );

    v_resolution_fingerprint := public.pay_finance_component_fingerprint(
      p_source_family_key         => v_component.source_family_key,
      p_component_key_type        => v_component.component_key_type,
      p_component_key_value       => v_component.component_key_value,
      p_classification            => v_component.classification,
      p_source_pay_method         => v_component.source_pay_method,
      p_current_target_pay_method => v_target_pay_method,
      p_source_basis_json         => coalesce(v_component.source_basis_json, '{}'::jsonb),
      p_source_amount             => round(coalesce(v_component.source_amount, 0), 2),
      p_relevant_erni_pct         => round(v_relevant_erni_pct, 6),
      p_target_basis_json         => v_target_basis_json
    );

    UPDATE public.pay_finance_case_components pfc
    SET
      saved_target_pay_method = v_target_pay_method,
      saved_resolution_mode = v_resolution_mode,
      saved_resolution_payload_json = v_resolution_payload_json,
      saved_resolution_result_json = v_resolution_result_json,
      resolution_fingerprint = v_resolution_fingerprint,
      resolved_at_utc = v_now_utc,
      is_resolution_stale = false,
      stale_reason = NULL,
      updated_at_utc = v_now_utc
    WHERE pfc.id = v_component.id;

    SELECT jsonb_build_object(
      'finance_component_id', pfc.id::text,
      'finance_case_id', pfc.finance_case_id::text,
      'classification', pfc.classification::text,
      'source_pay_method', pfc.source_pay_method,
      'source_basis_json', pfc.source_basis_json,
      'source_amount', round(coalesce(pfc.source_amount, 0), 2),
      'remaining_source_amount', round(coalesce(pfc.remaining_source_amount, 0), 2),
      'saved_target_pay_method', pfc.saved_target_pay_method,
      'saved_resolution_mode', CASE WHEN pfc.saved_resolution_mode IS NULL THEN NULL ELSE pfc.saved_resolution_mode::text END,
      'saved_resolution_payload_json', pfc.saved_resolution_payload_json,
      'saved_resolution_result_json', pfc.saved_resolution_result_json,
      'source_units', v_source_units,
      'source_rate', v_source_rate,
      'source_charge_rate', v_source_charge_rate,
      'bucket_code', v_bucket_code,
      'component_semantics', v_component_semantics,
      'is_rate_bearing_row', v_is_rate_bearing_row,
      'is_amount_led_row', v_is_amount_led_row,
      'resolution_fingerprint', pfc.resolution_fingerprint,
      'is_resolution_stale', pfc.is_resolution_stale,
      'stale_reason', pfc.stale_reason,
      'resolved_at_utc', pfc.resolved_at_utc
    )
    INTO v_after_json
    FROM public.pay_finance_case_components pfc
    WHERE pfc.id = v_component.id;

    v_event_reason := coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'COMPONENT_RESOLUTION_APPLIED');

    INSERT INTO public.pay_finance_case_events (
      finance_case_id,
      finance_component_id,
      event_type,
      event_at_utc,
      actor_user_id,
      pay_batch_id,
      reservation_id,
      before_json,
      after_json,
      reason,
      note
    )
    VALUES (
      v_component.finance_case_id,
      v_component.id,
      'COMPONENT_RESOLUTION_APPLIED',
      v_now_utc,
      p_actor_user_id,
      NULL,
      NULL,
      v_before_json,
      v_after_json,
      v_event_reason,
      ('Applied ' || v_resolution_mode::text || ' to taxable finance component')
    );

    v_applied_components := v_applied_components || jsonb_build_array(
      jsonb_build_object(
        'finance_component_id', v_component.id::text,
        'finance_case_id', v_component.finance_case_id::text,
        'saved_target_pay_method', v_target_pay_method,
        'saved_resolution_mode', v_resolution_mode::text,
        'saved_resolution_payload_json', v_resolution_payload_json,
        'saved_resolution_result_json', v_resolution_result_json,
        'source_units', v_source_units,
        'source_rate', v_source_rate,
        'source_charge_rate', v_source_charge_rate,
        'bucket_code', v_bucket_code,
        'component_semantics', v_component_semantics,
        'is_rate_bearing_row', v_is_rate_bearing_row,
        'is_amount_led_row', v_is_amount_led_row,
        'resolution_fingerprint', v_resolution_fingerprint,
        'resolved_at_utc', v_now_utc
      )
    );
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'candidate_id', p_candidate_id::text,
    'finance_case_id', CASE WHEN p_finance_case_id IS NULL THEN NULL ELSE p_finance_case_id::text END,
    'applied_count', jsonb_array_length(v_applied_components),
    'components', v_applied_components
  );
END;
$function$;




DROP FUNCTION IF EXISTS public._pay_finance_case_oneoff_bank_remove(uuid,uuid,text);

CREATE OR REPLACE FUNCTION public._pay_finance_case_oneoff_bank_remove(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_reason text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_case public.pay_advances%rowtype;
  v_existing public.pay_finance_case_oneoff_payout_bank_details%rowtype;

  v_has_noncancelled_batch_item boolean := false;
  v_before_json jsonb := null;
  v_after_json jsonb := null;
  v_preview_blocked_until_reentered boolean := false;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_REMOVE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_finance_case_oneoff_bank_remove: finance_case_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_REMOVE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', '_pay_finance_case_oneoff_bank_remove: actor_user_id is required'
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  FOR UPDATE;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_REMOVE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_finance_case_oneoff_bank_remove: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  IF v_case.case_type NOT IN (
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_REMOVE',
      'code', 'CASE_TYPE_NOT_ELIGIBLE',
      'message', '_pay_finance_case_oneoff_bank_remove: one-off bank details can only be removed for payment advances or manual credit adjustments',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  END IF;

  SELECT exists (
    SELECT 1
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN public.pay_batches AS pb
      ON pb.id = pbc.pay_batch_id
    WHERE (
        pbi.finance_case_id = p_finance_case_id
        OR pbi.source_ref = ('advance:'::text || p_finance_case_id::text)
      )
      AND coalesce(pbi.is_voided, false) = false
      AND pb.cancelled_at_utc IS NULL
      AND upper(coalesce(pb.status, '')) <> 'CANCELLED'
  )
  INTO v_has_noncancelled_batch_item;

  IF v_case.payout_pay_batch_id IS NOT NULL OR v_has_noncancelled_batch_item THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_REMOVE',
      'code', 'ONEOFF_BANK_DETAILS_LOCKED',
      'message', '_pay_finance_case_oneoff_bank_remove: one-off bank details can only be removed while the item is Not processed yet',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT d.*
  INTO v_existing
  FROM public.pay_finance_case_oneoff_payout_bank_details AS d
  WHERE d.finance_case_id = p_finance_case_id
  FOR UPDATE;

  v_preview_blocked_until_reentered := coalesce(v_case.oneoff_bank_details_required, false);

  IF v_existing.finance_case_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'finance_case_id', p_finance_case_id::text,
      'removed', false,
      'preview_blocked_until_reentered', v_preview_blocked_until_reentered
    );
  END IF;

  v_before_json := jsonb_build_object(
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'beneficiary_name', v_existing.beneficiary_name,
    'sort_code_masked', CASE WHEN v_existing.sort_code IS NULL THEN NULL ELSE 'XX-XX-' || right(v_existing.sort_code, 2) END,
    'account_number_masked', CASE WHEN v_existing.account_number IS NULL THEN NULL ELSE lpad(right(v_existing.account_number, 4), length(v_existing.account_number), '*') END,
    'bank_details_hash', v_existing.bank_details_hash,
    'note', v_existing.note
  );

  DELETE FROM public.pay_finance_case_oneoff_payout_bank_details AS d
  WHERE d.finance_case_id = p_finance_case_id;

  v_after_json := jsonb_build_object(
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'oneoff_bank_details_present', false,
    'preview_blocked_until_reentered', v_preview_blocked_until_reentered
  );

  PERFORM public._audit_insert(
    'finance_case',
    p_finance_case_id::text,
    'ONEOFF_BANK_DETAILS_REMOVED',
    v_before_json,
    v_after_json,
    coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'ONE_OFF_PAYOUT_BANK_DETAILS'),
    p_actor_user_id
  );

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'removed', true,
    'preview_blocked_until_reentered', v_preview_blocked_until_reentered
  );
END;
$function$;

DROP FUNCTION IF EXISTS public._pay_finance_case_oneoff_bank_upsert(uuid,uuid,text,text,text,text,text);

CREATE OR REPLACE FUNCTION public._pay_finance_case_oneoff_bank_upsert(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_beneficiary_name text,
  p_sort_code text,
  p_account_number text,
  p_note text default null,
  p_reason text default null
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_case public.pay_advances%rowtype;
  v_candidate public.candidates%rowtype;
  v_existing public.pay_finance_case_oneoff_payout_bank_details%rowtype;

  v_effective jsonb := '{}'::jsonb;

  v_beneficiary_name_norm text := null;
  v_sort_digits text := null;
  v_sort_code_norm text := null;
  v_account_number_norm text := null;
  v_bank_details_hash text := null;
  v_note_norm text := null;

  v_before_json jsonb := null;
  v_after_json jsonb := null;
  v_action text := null;

  v_has_noncancelled_batch_item boolean := false;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_finance_case_oneoff_bank_upsert: finance_case_id is required'
    )::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', '_pay_finance_case_oneoff_bank_upsert: actor_user_id is required'
    )::text;
  END IF;

  v_beneficiary_name_norm := nullif(regexp_replace(btrim(coalesce(p_beneficiary_name, '')), '\s+', ' ', 'g'), '');
  v_sort_digits := nullif(regexp_replace(coalesce(p_sort_code, ''), '[^0-9]+', '', 'g'), '');
  v_account_number_norm := nullif(regexp_replace(coalesce(p_account_number, ''), '[^0-9]+', '', 'g'), '');
  v_note_norm := nullif(btrim(coalesce(p_note, '')), '');

  IF v_beneficiary_name_norm IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'BENEFICIARY_NAME_REQUIRED',
      'message', '_pay_finance_case_oneoff_bank_upsert: beneficiary_name is required'
    )::text;
  END IF;

  IF v_sort_digits IS NULL OR length(v_sort_digits) <> 6 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'SORT_CODE_INVALID',
      'message', '_pay_finance_case_oneoff_bank_upsert: sort_code must contain exactly 6 digits'
    )::text;
  END IF;

  IF v_account_number_norm IS NULL OR length(v_account_number_norm) < 6 OR length(v_account_number_norm) > 10 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'ACCOUNT_NUMBER_INVALID',
      'message', '_pay_finance_case_oneoff_bank_upsert: account_number must contain between 6 and 10 digits'
    )::text;
  END IF;

  v_sort_code_norm := substr(v_sort_digits, 1, 2) || '-' || substr(v_sort_digits, 3, 2) || '-' || substr(v_sort_digits, 5, 2);
  v_bank_details_hash := public._bank_hash(v_sort_code_norm, v_account_number_norm, v_beneficiary_name_norm);

  IF nullif(btrim(coalesce(v_bank_details_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'BANK_HASH_FAILED',
      'message', '_pay_finance_case_oneoff_bank_upsert: unable to compute bank_details_hash'
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  FOR UPDATE;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_finance_case_oneoff_bank_upsert: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT c.*
  INTO v_candidate
  FROM public.candidates AS c
  WHERE c.id = v_case.candidate_id
  LIMIT 1;

  IF v_candidate.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', '_pay_finance_case_oneoff_bank_upsert: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  END IF;

  v_effective := public._pay_finance_case_effective_payout_instruction(p_finance_case_id);

  IF upper(coalesce(v_candidate.pay_method, '')) <> 'UMBRELLA' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'PAY_METHOD_NOT_UMBRELLA',
      'message', '_pay_finance_case_oneoff_bank_upsert: one-off payout bank details are only valid for umbrella-routed one-off payouts',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_candidate.id::text,
      'pay_method', v_candidate.pay_method
    )::text;
  END IF;

  IF coalesce(v_effective ->> 'routing_kind', '') <> 'ONE_OFF_SPECIFIED_BANK_ACCOUNT' THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'ROUTING_KIND_NOT_ONEOFF',
      'message', '_pay_finance_case_oneoff_bank_upsert: finance case is not currently routed to a one-off specified bank account',
      'finance_case_id', p_finance_case_id::text,
      'routing_kind', v_effective ->> 'routing_kind'
    )::text;
  END IF;

  SELECT exists (
    SELECT 1
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN public.pay_batches AS pb
      ON pb.id = pbc.pay_batch_id
    WHERE (
        pbi.finance_case_id = p_finance_case_id
        OR pbi.source_ref = ('advance:'::text || p_finance_case_id::text)
      )
      AND coalesce(pbi.is_voided, false) = false
      AND pb.cancelled_at_utc IS NULL
      AND upper(coalesce(pb.status, '')) <> 'CANCELLED'
  )
  INTO v_has_noncancelled_batch_item;

  IF v_case.payout_pay_batch_id IS NOT NULL OR v_has_noncancelled_batch_item THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_ONEOFF_BANK_UPSERT',
      'code', 'ONEOFF_BANK_DETAILS_LOCKED',
      'message', '_pay_finance_case_oneoff_bank_upsert: one-off bank details can only be edited while the item is Not processed yet',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT d.*
  INTO v_existing
  FROM public.pay_finance_case_oneoff_payout_bank_details AS d
  WHERE d.finance_case_id = p_finance_case_id
  FOR UPDATE;

  IF v_existing.finance_case_id IS NOT NULL THEN
    v_before_json := jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'beneficiary_name', v_existing.beneficiary_name,
      'sort_code_masked', CASE WHEN v_existing.sort_code IS NULL THEN NULL ELSE 'XX-XX-' || right(v_existing.sort_code, 2) END,
      'account_number_masked', CASE WHEN v_existing.account_number IS NULL THEN NULL ELSE lpad(right(v_existing.account_number, 4), length(v_existing.account_number), '*') END,
      'bank_details_hash', v_existing.bank_details_hash,
      'note', v_existing.note
    );
  END IF;

  INSERT INTO public.pay_finance_case_oneoff_payout_bank_details(
    finance_case_id,
    candidate_id,
    beneficiary_name,
    sort_code,
    account_number,
    bank_details_hash,
    note,
    created_at_utc,
    created_by_user_id,
    updated_at_utc,
    updated_by_user_id
  )
  VALUES (
    p_finance_case_id,
    v_case.candidate_id,
    v_beneficiary_name_norm,
    v_sort_code_norm,
    v_account_number_norm,
    v_bank_details_hash,
    v_note_norm,
    now(),
    p_actor_user_id,
    now(),
    p_actor_user_id
  )
  ON CONFLICT (finance_case_id) DO UPDATE
  SET candidate_id = EXCLUDED.candidate_id,
      beneficiary_name = EXCLUDED.beneficiary_name,
      sort_code = EXCLUDED.sort_code,
      account_number = EXCLUDED.account_number,
      bank_details_hash = EXCLUDED.bank_details_hash,
      note = EXCLUDED.note,
      updated_at_utc = EXCLUDED.updated_at_utc,
      updated_by_user_id = EXCLUDED.updated_by_user_id;

  SELECT d.*
  INTO v_existing
  FROM public.pay_finance_case_oneoff_payout_bank_details AS d
  WHERE d.finance_case_id = p_finance_case_id
  LIMIT 1;

  v_after_json := jsonb_build_object(
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'beneficiary_name', v_existing.beneficiary_name,
    'sort_code_masked', CASE WHEN v_existing.sort_code IS NULL THEN NULL ELSE 'XX-XX-' || right(v_existing.sort_code, 2) END,
    'account_number_masked', CASE WHEN v_existing.account_number IS NULL THEN NULL ELSE lpad(right(v_existing.account_number, 4), length(v_existing.account_number), '*') END,
    'bank_details_hash', v_existing.bank_details_hash,
    'note', v_existing.note
  );

  IF v_before_json IS NULL THEN
    v_action := 'ONEOFF_BANK_DETAILS_CREATED';
  ELSIF v_before_json IS DISTINCT FROM v_after_json THEN
    v_action := 'ONEOFF_BANK_DETAILS_UPDATED';
  ELSE
    v_action := 'ONEOFF_BANK_DETAILS_UNCHANGED';
  END IF;

  IF v_action <> 'ONEOFF_BANK_DETAILS_UNCHANGED' THEN
    PERFORM public._audit_insert(
      'finance_case',
      p_finance_case_id::text,
      v_action,
      v_before_json,
      v_after_json,
      coalesce(nullif(btrim(coalesce(p_reason, '')), ''), 'ONE_OFF_PAYOUT_BANK_DETAILS'),
      p_actor_user_id
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_case.candidate_id::text,
    'action', v_action,
    'beneficiary_name', v_existing.beneficiary_name,
    'sort_code_masked', CASE WHEN v_existing.sort_code IS NULL THEN NULL ELSE 'XX-XX-' || right(v_existing.sort_code, 2) END,
    'account_number_masked', CASE WHEN v_existing.account_number IS NULL THEN NULL ELSE lpad(right(v_existing.account_number, 4), length(v_existing.account_number), '*') END,
    'bank_details_hash', v_existing.bank_details_hash,
    'note', v_existing.note,
    'preview_blocked_until_reentered', false
  );
END;
$function$;

DROP FUNCTION IF EXISTS public._pay_finance_case_effective_payout_instruction(uuid);

CREATE OR REPLACE FUNCTION public._pay_finance_case_effective_payout_instruction(
  p_finance_case_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_case public.pay_advances%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;

  v_component_classification public.pay_finance_component_classification_enum := null;
  v_taxability public.pay_finance_taxability_enum := null;
  v_routing_kind public.pay_finance_routing_kind_enum := null;

  v_pay_method text := null;
  v_pay_channel text := null;
  v_destination_label text := null;
  v_payee_entity_kind text := null;
  v_payee_entity_id uuid := null;

  v_bank_details_hash text := null;
  v_beneficiary_name text := null;
  v_masked_bank_account text := null;

  v_oneoff_bank_details_present boolean := false;
  v_oneoff_bank_details_required boolean := false;
  v_oneoff_bank_details_editable boolean := false;
  v_is_candidate_directed_oneoff_payout boolean := false;
  v_appears_on_umbrella_remittance boolean := false;
  v_generates_candidate_payment_advice boolean := false;

  v_has_noncancelled_batch_item boolean := false;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_EFFECTIVE_PAYOUT_INSTRUCTION',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_finance_case_effective_payout_instruction: finance_case_id is required'
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  LIMIT 1;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_EFFECTIVE_PAYOUT_INSTRUCTION',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_finance_case_effective_payout_instruction: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT c.*
  INTO v_candidate
  FROM public.candidates AS c
  WHERE c.id = v_case.candidate_id
  LIMIT 1;

  IF v_candidate.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_EFFECTIVE_PAYOUT_INSTRUCTION',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', '_pay_finance_case_effective_payout_instruction: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  END IF;

  v_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  IF v_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
    v_pay_method := null;
  END IF;

  IF v_candidate.umbrella_id IS NOT NULL THEN
    SELECT u.*
    INTO v_umbrella
    FROM public.umbrellas AS u
    WHERE u.id = v_candidate.umbrella_id
    LIMIT 1;
  END IF;

  SELECT pfc.classification
  INTO v_component_classification
  FROM public.pay_finance_case_components AS pfc
  WHERE pfc.finance_case_id = p_finance_case_id
    AND pfc.component_key_type = 'CASE_TOTAL'
    AND pfc.component_key_value = 'TOTAL'
    AND pfc.closed_at_utc IS NULL
  ORDER BY pfc.updated_at_utc DESC, pfc.created_at_utc DESC, pfc.id DESC
  LIMIT 1;

  v_taxability := v_case.taxability;
  IF v_taxability IS NULL THEN
    IF v_case.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum THEN
      v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
    ELSIF v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN
      v_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
    ELSIF v_component_classification IN (
      'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
    ) THEN
      v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
    END IF;
  END IF;

  v_routing_kind := v_case.routing_kind;
  IF v_routing_kind IS NULL THEN
    IF v_case.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSIF v_pay_method = 'UMBRELLA' THEN
        v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
      END IF;
    ELSIF v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSIF v_pay_method = 'UMBRELLA' AND v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum THEN
        v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
      ELSIF v_pay_method = 'UMBRELLA' AND v_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum THEN
        v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
      END IF;
    ELSIF v_case.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSIF v_pay_method = 'UMBRELLA' THEN
        v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
      END IF;
    END IF;
  END IF;

  v_oneoff_bank_details_required := coalesce(v_case.oneoff_bank_details_required, false);
  IF v_oneoff_bank_details_required = false THEN
    v_oneoff_bank_details_required := (
      v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
      AND v_case.case_type IN (
        'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
        'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      )
    );
  END IF;

  SELECT d.*
  INTO v_oneoff
  FROM public.pay_finance_case_oneoff_payout_bank_details AS d
  WHERE d.finance_case_id = p_finance_case_id
  LIMIT 1;

  v_oneoff_bank_details_present := (v_oneoff.finance_case_id IS NOT NULL);

  SELECT exists (
    SELECT 1
    FROM public.pay_batch_items AS pbi
    JOIN public.pay_batch_candidates AS pbc
      ON pbc.id = pbi.pay_batch_candidate_id
    JOIN public.pay_batches AS pb
      ON pb.id = pbc.pay_batch_id
    WHERE (
        pbi.finance_case_id = p_finance_case_id
        OR pbi.source_ref = ('advance:'::text || p_finance_case_id::text)
      )
      AND coalesce(pbi.is_voided, false) = false
      AND pb.cancelled_at_utc IS NULL
      AND upper(coalesce(pb.status, '')) <> 'CANCELLED'
  )
  INTO v_has_noncancelled_batch_item;

  v_oneoff_bank_details_editable := (
    v_oneoff_bank_details_required = true
    AND v_case.case_type IN (
      'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
      'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
    )
    AND v_case.payout_pay_batch_id IS NULL
    AND v_has_noncancelled_batch_item = false
  );

  IF v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum THEN
    v_destination_label := 'one-off specified bank account';
    v_payee_entity_kind := 'CANDIDATE';
    v_payee_entity_id := v_candidate.id;
    v_bank_details_hash := v_oneoff.bank_details_hash;
    v_beneficiary_name := v_oneoff.beneficiary_name;
    IF nullif(coalesce(v_oneoff.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_oneoff.account_number, 4), length(v_oneoff.account_number), '*');
    END IF;
  ELSIF v_routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum THEN
    v_destination_label := 'umbrella company';
    v_payee_entity_kind := 'UMBRELLA';
    v_payee_entity_id := v_candidate.umbrella_id;
    v_bank_details_hash := v_umbrella.bank_details_hash;
    v_beneficiary_name := v_umbrella.name;
    IF nullif(coalesce(v_umbrella.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_umbrella.account_number, 4), length(v_umbrella.account_number), '*');
    END IF;
  ELSE
    v_destination_label := 'normal PAYE route';
    v_payee_entity_kind := 'CANDIDATE';
    v_payee_entity_id := v_candidate.id;
    v_bank_details_hash := v_candidate.bank_details_hash;
    v_beneficiary_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
    IF nullif(coalesce(v_candidate.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_candidate.account_number, 4), length(v_candidate.account_number), '*');
    END IF;
  END IF;

  v_pay_channel := v_pay_method;

  v_is_candidate_directed_oneoff_payout := (
    v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum
    AND v_case.case_type IN (
      'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
      'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
    )
    AND (
      v_case.case_type <> 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum
      OR v_taxability = 'NON_TAXABLE'::public.pay_finance_taxability_enum
    )
  );

  v_appears_on_umbrella_remittance := (
    v_routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum
    AND v_case.case_type IN (
      'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum,
      'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
    )
  );

  v_generates_candidate_payment_advice := v_is_candidate_directed_oneoff_payout;

  RETURN jsonb_build_object(
    'finance_case_id', p_finance_case_id::text,
    'case_type', v_case.case_type::text,
    'candidate_id', v_candidate.id::text,
    'client_id', CASE WHEN v_case.client_id IS NULL THEN NULL ELSE v_case.client_id::text END,
    'pay_method', v_pay_method,
    'pay_channel', v_pay_channel,
    'taxability', CASE WHEN v_taxability IS NULL THEN NULL ELSE v_taxability::text END,
    'routing_kind', CASE WHEN v_routing_kind IS NULL THEN NULL ELSE v_routing_kind::text END,
    'destination_label', v_destination_label,
    'payee_entity_kind', v_payee_entity_kind,
    'payee_entity_id', CASE WHEN v_payee_entity_id IS NULL THEN NULL ELSE v_payee_entity_id::text END,
    'beneficiary_name', v_beneficiary_name,
    'bank_details_hash', v_bank_details_hash,
    'masked_bank_account', v_masked_bank_account,
    'oneoff_bank_details_required', v_oneoff_bank_details_required,
    'oneoff_bank_details_present', v_oneoff_bank_details_present,
    'oneoff_bank_details_editable', v_oneoff_bank_details_editable,
    'is_candidate_directed_oneoff_payout', v_is_candidate_directed_oneoff_payout,
    'appears_on_umbrella_remittance', v_appears_on_umbrella_remittance,
    'generates_candidate_payment_advice', v_generates_candidate_payment_advice
  );
END;
$function$;


DROP FUNCTION IF EXISTS public._pay_repayment_schedule_restore_after_snooze_clear(uuid,date);

CREATE OR REPLACE FUNCTION public._pay_repayment_schedule_restore_after_snooze_clear(
  p_finance_case_id uuid,
  p_effective_from_date date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_case public.pay_advances%rowtype;
  v_before_schedule_json jsonb := '[]'::jsonb;
  v_after_schedule_json jsonb := '[]'::jsonb;
  v_before_next_due_week_start date := null;
  v_after_next_due_week_start date := null;
  v_requested_week_start date := null;
  v_current_operating_week_start date := null;
  v_target_week_start date := null;
  v_installment_count integer := 0;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_repayment_schedule_restore_after_snooze_clear: finance_case_id is required'
    )::text;
  END IF;

  IF p_effective_from_date IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
      'code', 'EFFECTIVE_FROM_DATE_REQUIRED',
      'message', '_pay_repayment_schedule_restore_after_snooze_clear: effective_from_date is required'
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  LIMIT 1
  FOR UPDATE;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_repayment_schedule_restore_after_snooze_clear: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  IF v_case.case_type NOT IN (
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
      'code', 'CASE_TYPE_NOT_SNOOZEABLE',
      'message', '_pay_repayment_schedule_restore_after_snooze_clear: only repayment-type finance cases may be restored after snooze clear',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  END IF;

  v_before_schedule_json := coalesce(v_case.schedule_json, '[]'::jsonb);
  v_before_next_due_week_start := v_case.next_due_week_start;
  v_requested_week_start := public._pay_week_start_monday(p_effective_from_date);
  v_current_operating_week_start := public._pay_week_start_monday((now() at time zone 'Europe/London')::date);

  IF v_requested_week_start < v_current_operating_week_start THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_RESTORE_AFTER_SNOOZE_CLEAR',
      'code', 'EFFECTIVE_FROM_DATE_BEFORE_NOW',
      'message', '_pay_repayment_schedule_restore_after_snooze_clear: effective_from_date cannot restore the repayment schedule earlier than the current operating week',
      'finance_case_id', p_finance_case_id::text,
      'requested_week_start', v_requested_week_start::text,
      'current_operating_week_start', v_current_operating_week_start::text
    )::text;
  END IF;

  v_target_week_start := v_requested_week_start;

  WITH schedule_rows AS (
    SELECT
      row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
      round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
    FROM jsonb_array_elements(v_before_schedule_json) WITH ORDINALITY AS elem(value, ordinality)
    WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
          'amount', sr.amount_value
        )
        ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  INTO v_after_schedule_json, v_installment_count
  FROM schedule_rows AS sr;

  v_after_next_due_week_start := CASE WHEN v_installment_count > 0 THEN v_target_week_start ELSE null END;

  UPDATE public.pay_advances AS pa
  SET schedule_json = v_after_schedule_json,
      next_due_week_start = v_after_next_due_week_start,
      updated_at = now()
  WHERE pa.id = p_finance_case_id;

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'schedule_before_restore_json', v_before_schedule_json,
    'next_due_week_start_before_restore', case when v_before_next_due_week_start is null then null else v_before_next_due_week_start::text end,
    'requested_week_start', v_requested_week_start::text,
    'current_operating_week_start', v_current_operating_week_start::text,
    'schedule_after_restore_json', v_after_schedule_json,
    'next_due_week_start_after_restore', case when v_after_next_due_week_start is null then null else v_after_next_due_week_start::text end,
    'installment_count', v_installment_count
  );
END;
$function$;





DROP FUNCTION IF EXISTS public._pay_repayment_schedule_rebase_for_snooze(uuid,date);

CREATE OR REPLACE FUNCTION public._pay_repayment_schedule_rebase_for_snooze(
  p_finance_case_id uuid,
  p_snooze_until_date date
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_case public.pay_advances%rowtype;
  v_before_schedule_json jsonb := '[]'::jsonb;
  v_after_schedule_json jsonb := '[]'::jsonb;
  v_before_next_due_week_start date := null;
  v_after_next_due_week_start date := null;
  v_requested_week_start date := null;
  v_target_week_start date := null;
  v_installment_count integer := 0;
BEGIN
  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_repayment_schedule_rebase_for_snooze: finance_case_id is required'
    )::text;
  END IF;

  IF p_snooze_until_date IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'SNOOZE_UNTIL_DATE_REQUIRED',
      'message', '_pay_repayment_schedule_rebase_for_snooze: snooze_until_date is required'
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  LIMIT 1
  FOR UPDATE;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_repayment_schedule_rebase_for_snooze: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  IF v_case.case_type NOT IN (
    'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum,
    'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'CASE_TYPE_NOT_SNOOZEABLE',
      'message', '_pay_repayment_schedule_rebase_for_snooze: only repayment-type finance cases may be rebased for snooze',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  END IF;

  v_before_schedule_json := coalesce(v_case.schedule_json, '[]'::jsonb);
  v_before_next_due_week_start := v_case.next_due_week_start;
  v_requested_week_start := public._pay_week_start_monday(p_snooze_until_date);

  IF v_before_next_due_week_start IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'NEXT_DUE_MISSING',
      'message', '_pay_repayment_schedule_rebase_for_snooze: next_due_week_start is required on the finance case'
    )::text;
  END IF;

  IF v_requested_week_start < v_before_next_due_week_start THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_REPAYMENT_SCHEDULE_REBASE_FOR_SNOOZE',
      'code', 'SNOOZE_DATE_BEFORE_NEXT_DUE',
      'message', '_pay_repayment_schedule_rebase_for_snooze: snooze_until_date cannot move the repayment schedule earlier than the current next due week',
      'finance_case_id', p_finance_case_id::text,
      'current_next_due_week_start', v_before_next_due_week_start::text,
      'requested_week_start', v_requested_week_start::text
    )::text;
  END IF;

  v_target_week_start := CASE
    WHEN v_requested_week_start = v_before_next_due_week_start THEN (v_before_next_due_week_start + 7)
    ELSE v_requested_week_start
  END;

  WITH schedule_rows AS (
    SELECT
      row_number() OVER (ORDER BY (elem.value ->> 'week_start')::date ASC, elem.ordinality ASC) AS seq_no,
      round(coalesce((elem.value ->> 'amount')::numeric, 0), 2) AS amount_value
    FROM jsonb_array_elements(v_before_schedule_json) WITH ORDINALITY AS elem(value, ordinality)
    WHERE coalesce((elem.value ->> 'amount')::numeric, 0) < 0
  )
  SELECT
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'week_start', (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date,
          'amount', sr.amount_value
        )
        ORDER BY (v_target_week_start + (((sr.seq_no - 1)::integer) * 7))::date ASC
      ),
      '[]'::jsonb
    ),
    count(*)::integer
  INTO v_after_schedule_json, v_installment_count
  FROM schedule_rows AS sr;

  v_after_next_due_week_start := CASE WHEN v_installment_count > 0 THEN v_target_week_start ELSE null END;

  UPDATE public.pay_advances AS pa
  SET schedule_json = v_after_schedule_json,
      next_due_week_start = v_after_next_due_week_start,
      updated_at = now()
  WHERE pa.id = p_finance_case_id;

  RETURN jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'schedule_before_snooze_json', v_before_schedule_json,
    'next_due_week_start_before_snooze', case when v_before_next_due_week_start is null then null else v_before_next_due_week_start::text end,
    'requested_week_start', v_requested_week_start::text,
    'schedule_after_snooze_json', v_after_schedule_json,
    'next_due_week_start_after_snooze', case when v_after_next_due_week_start is null then null else v_after_next_due_week_start::text end,
    'installment_count', v_installment_count
  );
END;
$function$;




DROP FUNCTION IF EXISTS public._pay_finance_case_freeze_payout_instruction_to_batch_item(uuid,uuid);

CREATE OR REPLACE FUNCTION public._pay_finance_case_freeze_payout_instruction_to_batch_item(
  p_pay_batch_item_id uuid,
  p_finance_case_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_item public.pay_batch_items%rowtype;
  v_case public.pay_advances%rowtype;
  v_candidate public.candidates%rowtype;
  v_umbrella public.umbrellas%rowtype;
  v_oneoff public.pay_finance_case_oneoff_payout_bank_details%rowtype;
  v_component_classification public.pay_finance_component_classification_enum := null;
  v_taxability public.pay_finance_taxability_enum := null;
  v_routing_kind public.pay_finance_routing_kind_enum := null;
  v_pay_method text := null;
  v_pay_channel text := null;
  v_destination_label text := null;
  v_payee_entity_kind text := null;
  v_payee_entity_id uuid := null;
  v_beneficiary_name text := null;
  v_masked_bank_account text := null;
  v_bank_details_hash text := null;
  v_bank_details_note text := null;
  v_bank_details_created_by_user_id uuid := null;
  v_bank_details_updated_by_user_id uuid := null;
  v_is_candidate_directed_oneoff_payout boolean := false;
  v_appears_on_umbrella_remittance boolean := false;
  v_generates_candidate_payment_advice boolean := false;
  v_snapshot jsonb := '{}'::jsonb;
BEGIN
  IF p_pay_batch_item_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'PAY_BATCH_ITEM_ID_REQUIRED',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: pay_batch_item_id is required'
    )::text;
  END IF;

  IF p_finance_case_id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: finance_case_id is required'
    )::text;
  END IF;

  SELECT pbi.*
  INTO v_item
  FROM public.pay_batch_items AS pbi
  WHERE pbi.id = p_pay_batch_item_id
  LIMIT 1
  FOR UPDATE;

  IF v_item.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'PAY_BATCH_ITEM_NOT_FOUND',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: pay batch item not found',
      'pay_batch_item_id', p_pay_batch_item_id::text
    )::text;
  END IF;

  IF v_item.finance_case_id IS NOT NULL AND v_item.finance_case_id <> p_finance_case_id THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'FINANCE_CASE_ID_MISMATCH',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: item finance_case_id does not match input finance_case_id',
      'pay_batch_item_id', p_pay_batch_item_id::text,
      'item_finance_case_id', v_item.finance_case_id::text,
      'input_finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT pa.*
  INTO v_case
  FROM public.pay_advances AS pa
  WHERE pa.id = p_finance_case_id
  LIMIT 1;

  IF v_case.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  END IF;

  SELECT c.*
  INTO v_candidate
  FROM public.candidates AS c
  WHERE c.id = v_case.candidate_id
  LIMIT 1;

  IF v_candidate.id IS NULL THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  END IF;

  v_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  IF v_pay_method NOT IN ('PAYE', 'UMBRELLA') THEN
    RAISE EXCEPTION '%', jsonb_build_object(
      'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
      'code', 'PAY_METHOD_INVALID',
      'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_pay_method
    )::text;
  END IF;

  IF v_candidate.umbrella_id IS NOT NULL THEN
    SELECT u.*
    INTO v_umbrella
    FROM public.umbrellas AS u
    WHERE u.id = v_candidate.umbrella_id
    LIMIT 1;
  END IF;

  SELECT pfc.classification
  INTO v_component_classification
  FROM public.pay_finance_case_components AS pfc
  WHERE pfc.finance_case_id = p_finance_case_id
    AND pfc.component_key_type = 'CASE_TOTAL'
    AND pfc.component_key_value = 'TOTAL'
    AND pfc.closed_at_utc IS NULL
  ORDER BY pfc.updated_at_utc DESC, pfc.created_at_utc DESC, pfc.id DESC
  LIMIT 1;

  v_taxability := v_case.taxability;
  IF v_taxability IS NULL THEN
    IF v_case.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum THEN
      v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
    ELSIF v_component_classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum THEN
      v_taxability := 'TAXABLE'::public.pay_finance_taxability_enum;
    ELSIF v_component_classification IN (
      'REIMBURSEMENT_GROSS_FIXED'::public.pay_finance_component_classification_enum,
      'NET_PAY_FIXED_RECOVERY'::public.pay_finance_component_classification_enum
    ) THEN
      v_taxability := 'NON_TAXABLE'::public.pay_finance_taxability_enum;
    END IF;
  END IF;

  v_routing_kind := v_case.routing_kind;
  IF v_routing_kind IS NULL THEN
    IF v_case.case_type = 'PAYMENT_ADVANCE'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSE
        v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
      END IF;
    ELSIF v_case.case_type = 'MANUAL_CREDIT_ADJUSTMENT'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSIF v_taxability = 'TAXABLE'::public.pay_finance_taxability_enum THEN
        v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
      ELSE
        v_routing_kind := 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum;
      END IF;
    ELSIF v_case.case_type = 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum THEN
      IF v_pay_method = 'PAYE' THEN
        v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
      ELSE
        v_routing_kind := 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum;
      END IF;
    ELSE
      v_routing_kind := 'NORMAL_PAY_ROUTE'::public.pay_finance_routing_kind_enum;
    END IF;
  END IF;

  v_pay_channel := v_pay_method;

  IF v_routing_kind = 'ONE_OFF_SPECIFIED_BANK_ACCOUNT'::public.pay_finance_routing_kind_enum THEN
    SELECT d.*
    INTO v_oneoff
    FROM public.pay_finance_case_oneoff_payout_bank_details AS d
    WHERE d.finance_case_id = p_finance_case_id
    LIMIT 1;

    IF v_oneoff.finance_case_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
        'error', 'PAY_FINANCE_CASE_FREEZE_PAYOUT_INSTRUCTION_TO_BATCH_ITEM',
        'code', 'ONEOFF_BANK_DETAILS_MISSING',
        'message', '_pay_finance_case_freeze_payout_instruction_to_batch_item: one-off bank details are required for this finance case routing',
        'finance_case_id', p_finance_case_id::text,
        'routing_kind', v_routing_kind::text
      )::text;
    END IF;

    v_destination_label := 'one-off specified bank account';
    v_payee_entity_kind := 'CANDIDATE';
    v_payee_entity_id := v_candidate.id;
    v_beneficiary_name := v_oneoff.beneficiary_name;
    v_bank_details_hash := v_oneoff.bank_details_hash;
    v_bank_details_note := v_oneoff.note;
    v_bank_details_created_by_user_id := v_oneoff.created_by_user_id;
    v_bank_details_updated_by_user_id := v_oneoff.updated_by_user_id;
    IF nullif(coalesce(v_oneoff.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_oneoff.account_number, 4), length(v_oneoff.account_number), '*');
    END IF;
    v_is_candidate_directed_oneoff_payout := true;
    v_appears_on_umbrella_remittance := false;
    v_generates_candidate_payment_advice := true;
  ELSIF v_routing_kind = 'UMBRELLA_COMPANY'::public.pay_finance_routing_kind_enum THEN
    v_destination_label := 'umbrella company';
    v_payee_entity_kind := 'UMBRELLA';
    v_payee_entity_id := v_candidate.umbrella_id;
    v_beneficiary_name := nullif(btrim(coalesce(v_umbrella.name, '')), '');
    v_bank_details_hash := v_umbrella.bank_details_hash;
    IF nullif(coalesce(v_umbrella.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_umbrella.account_number, 4), length(v_umbrella.account_number), '*');
    END IF;
    v_is_candidate_directed_oneoff_payout := false;
    v_appears_on_umbrella_remittance := true;
    v_generates_candidate_payment_advice := false;
  ELSE
    v_destination_label := 'normal PAYE route';
    v_payee_entity_kind := 'CANDIDATE';
    v_payee_entity_id := v_candidate.id;
    v_beneficiary_name := nullif(btrim(coalesce(v_candidate.account_holder, v_candidate.display_name, concat_ws(' ', v_candidate.first_name, v_candidate.last_name))), '');
    v_bank_details_hash := v_candidate.bank_details_hash;
    IF nullif(coalesce(v_candidate.account_number, ''), '') IS NOT NULL THEN
      v_masked_bank_account := lpad(right(v_candidate.account_number, 4), length(v_candidate.account_number), '*');
    END IF;
    v_is_candidate_directed_oneoff_payout := false;
    v_appears_on_umbrella_remittance := false;
    v_generates_candidate_payment_advice := false;
  END IF;

  v_snapshot := jsonb_strip_nulls(
    jsonb_build_object(
      'taxability', case when v_taxability is null then null else v_taxability::text end,
      'routing_kind', case when v_routing_kind is null then null else v_routing_kind::text end,
      'destination_label', v_destination_label,
      'pay_channel', v_pay_channel,
      'payee_entity_kind', v_payee_entity_kind,
      'payee_entity_id', case when v_payee_entity_id is null then null else v_payee_entity_id::text end,
      'beneficiary_name', v_beneficiary_name,
      'masked_bank_account', v_masked_bank_account,
      'bank_details_hash', v_bank_details_hash,
      'bank_details_note', v_bank_details_note,
      'bank_details_created_by_user_id', case when v_bank_details_created_by_user_id is null then null else v_bank_details_created_by_user_id::text end,
      'bank_details_updated_by_user_id', case when v_bank_details_updated_by_user_id is null then null else v_bank_details_updated_by_user_id::text end,
      'appears_on_umbrella_remittance', v_appears_on_umbrella_remittance,
      'generates_candidate_payment_advice', v_generates_candidate_payment_advice,
      'is_candidate_directed_oneoff_payout', v_is_candidate_directed_oneoff_payout,
      'locked_at_draft', true,
      'finance_case_id', p_finance_case_id::text,
      'pay_batch_item_id', p_pay_batch_item_id::text
    )
  );

  UPDATE public.pay_batch_items AS pbi
  SET payout_instruction_snapshot_json = v_snapshot
  WHERE pbi.id = p_pay_batch_item_id;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_item_id', p_pay_batch_item_id::text,
    'finance_case_id', p_finance_case_id::text,
    'payout_instruction_snapshot_json', v_snapshot
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public._pay_candidate_arranged_pay_wtd_before(
  p_candidate_id uuid,
  p_week_start date,
  p_pay_date date,
  p_before_created_at_utc timestamptz DEFAULT NULL,
  p_before_pay_batch_id uuid DEFAULT NULL
)
RETURNS numeric
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $function$
DECLARE
  v_result numeric(12,2);
BEGIN
  IF p_candidate_id IS NULL THEN
    RAISE EXCEPTION 'public._pay_candidate_arranged_pay_wtd_before: p_candidate_id is required';
  END IF;

  IF p_week_start IS NULL THEN
    RAISE EXCEPTION 'public._pay_candidate_arranged_pay_wtd_before: p_week_start is required';
  END IF;

  IF p_pay_date IS NULL THEN
    RAISE EXCEPTION 'public._pay_candidate_arranged_pay_wtd_before: p_pay_date is required';
  END IF;

  SELECT
    round(
      coalesce(
        sum(
          CASE
            WHEN public.pay_batch_candidates.net_bank_amount IS NOT NULL THEN public.pay_batch_candidates.net_bank_amount
            WHEN public.pay_batch_candidates.gross_preview IS NOT NULL THEN public.pay_batch_candidates.gross_preview
            ELSE 0::numeric
          END
        ),
        0::numeric
      ),
      2
    )::numeric(12,2)
  INTO v_result
  FROM public.pay_batch_candidates
  JOIN public.pay_batches
    ON public.pay_batches.id = public.pay_batch_candidates.pay_batch_id
  WHERE public.pay_batch_candidates.candidate_id = p_candidate_id
    AND public.pay_batches.pay_date >= p_week_start
    AND public.pay_batches.pay_date < (p_week_start + 7)
    AND public.pay_batches.cancelled_at_utc IS NULL
    AND upper(coalesce(public.pay_batches.status::text, '')) <> 'CANCELLED'
    AND upper(coalesce(public.pay_batches.batch_kind_fixed::text, 'PAYROLL')) <> 'LOANS'
    AND (p_before_pay_batch_id IS NULL OR public.pay_batches.id <> p_before_pay_batch_id)
    AND (
      public.pay_batches.pay_date < p_pay_date
      OR (
        public.pay_batches.pay_date = p_pay_date
        AND (
          p_before_created_at_utc IS NULL
          OR public.pay_batches.created_at_utc < p_before_created_at_utc
          OR (
            public.pay_batches.created_at_utc = p_before_created_at_utc
            AND p_before_pay_batch_id IS NOT NULL
            AND public.pay_batches.id::text < p_before_pay_batch_id::text
          )
        )
      )
    );

  RETURN coalesce(v_result, 0::numeric(12,2));
END;
$function$;


CREATE OR REPLACE FUNCTION public.pay_manual_debt_adjustment_resolve_taxable_channel_change(
  p_finance_case_id uuid,
  p_actor_user_id uuid,
  p_resolution_path text,
  p_schedule_input_mode text DEFAULT NULL::text,
  p_weeks_total integer DEFAULT NULL::integer,
  p_weekly_due numeric DEFAULT NULL::numeric,
  p_manual_total_remaining numeric DEFAULT NULL::numeric,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
declare
  v_now_utc timestamptz := now();
  v_today_uk date := (now() at time zone 'Europe/London')::date;

  v_case public.pay_advances%rowtype;
  v_candidate record;
  v_component public.pay_finance_case_components%rowtype;
  v_updated_case public.pay_advances%rowtype;
  v_updated_component public.pay_finance_case_components%rowtype;
  v_finance_settings record;

  v_open_component_count integer := 0;
  v_resolution_path_norm text := upper(nullif(btrim(coalesce(p_resolution_path, '')), ''));
  v_schedule_input_mode_norm text := upper(nullif(btrim(coalesce(p_schedule_input_mode, '')), ''));
  v_candidate_pay_method text := null;
  v_case_is_taxable boolean := false;
  v_requires_restructure boolean := false;
  v_has_open_batch_item boolean := false;

  v_old_source_pay_method text := null;
  v_old_source_amount numeric(12,2) := 0;
  v_old_remaining_source_amount numeric(12,2) := 0;

  v_relevant_erni_pct numeric := null;
  v_vat_rate_pct numeric := null;
  v_umbrella_vat_chargeable boolean := false;

  v_default_remaining_weeks integer := null;
  v_selected_weeks_total integer := null;
  v_selected_weekly_due numeric(12,2) := null;
  v_restructure_start_week_start date := null;

  v_basis_remaining_source_amount numeric(12,2) := 0;
  v_confirmed_new_remaining_ex numeric(12,2) := 0;
  v_confirmed_new_remaining_vat numeric(12,2) := 0;
  v_confirmed_new_remaining_inc numeric(12,2) := 0;
  v_target_amounts_json jsonb := '{}'::jsonb;

  v_recovered_so_far_ex numeric(12,2) := 0;
  v_new_case_total_ex numeric(12,2) := 0;

  v_update_result jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_event_note text := null;
begin
  if p_finance_case_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'FINANCE_CASE_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance_case_id is required'
    )::text;
  end if;

  if p_actor_user_id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'ACTOR_USER_ID_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: actor_user_id is required'
    )::text;
  end if;

  if v_resolution_path_norm not in ('SUGGESTED', 'MANUAL') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'RESOLUTION_PATH_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: resolution_path must be SUGGESTED or MANUAL',
      'resolution_path', p_resolution_path
    )::text;
  end if;

  if v_schedule_input_mode_norm is null then
    if v_resolution_path_norm = 'SUGGESTED' then
      v_schedule_input_mode_norm := 'BY_WEEKS';
    else
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'SCHEDULE_INPUT_MODE_REQUIRED',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: schedule_input_mode is required for MANUAL resolution',
        'resolution_path', v_resolution_path_norm
      )::text;
    end if;
  end if;

  if v_schedule_input_mode_norm not in ('BY_WEEKS', 'BY_WEEKLY_DUE') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'SCHEDULE_INPUT_MODE_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: schedule_input_mode must be BY_WEEKS or BY_WEEKLY_DUE',
      'schedule_input_mode', p_schedule_input_mode
    )::text;
  end if;

  select pa.*
  into v_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id
  for update;

  if v_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'FINANCE_CASE_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case not found',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_case.case_type <> 'MANUAL_DEBT_ADJUSTMENT'::public.pay_finance_case_type_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_TYPE_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case must be MANUAL_DEBT_ADJUSTMENT',
      'finance_case_id', p_finance_case_id::text,
      'case_type', v_case.case_type::text
    )::text;
  end if;

  if v_case.status <> 'ACTIVE'::public.pay_advance_status_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_NOT_ACTIVE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case must be ACTIVE',
      'finance_case_id', p_finance_case_id::text,
      'status', v_case.status::text
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount, 0), 2) <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'NO_OUTSTANDING_BALANCE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case has no outstanding balance to restructure',
      'finance_case_id', p_finance_case_id::text,
      'outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2)
    )::text;
  end if;

  select
    c.id,
    upper(coalesce(c.pay_method, '')) as pay_method
  into v_candidate
  from public.candidates c
  where c.id = v_case.candidate_id
  limit 1;

  if v_candidate.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CANDIDATE_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: candidate not found for finance case',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text
    )::text;
  end if;

  v_candidate_pay_method := upper(coalesce(v_candidate.pay_method, ''));
  if v_candidate_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: candidate pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'pay_method', v_candidate_pay_method
    )::text;
  end if;

  select count(*)
  into v_open_component_count
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null;

  if v_open_component_count <> 1 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'COMPONENT_SHAPE_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: expected exactly one open finance component for the case',
      'finance_case_id', p_finance_case_id::text,
      'open_component_count', v_open_component_count
    )::text;
  end if;

  select pfc.*
  into v_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1
  for update;

  if v_component.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_TOTAL_COMPONENT_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: expected one open CASE_TOTAL/TOTAL component for the case',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_case_is_taxable := case
    when v_case.taxability is null then (v_component.classification = 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum)
    else (v_case.taxability = 'TAXABLE'::public.pay_finance_taxability_enum)
  end;

  if v_case_is_taxable is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_NOT_TAXABLE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case must be taxable',
      'finance_case_id', p_finance_case_id::text,
      'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
      'classification', v_component.classification::text
    )::text;
  end if;

  if v_component.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'COMPONENT_NOT_TAXABLE_CHANNEL_SENSITIVE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: component must be TAXABLE_CHANNEL_SENSITIVE',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'classification', v_component.classification::text
    )::text;
  end if;

  v_old_source_pay_method := upper(coalesce(v_component.source_pay_method, ''));
  if v_old_source_pay_method not in ('PAYE', 'UMBRELLA') then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'SOURCE_PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: component source_pay_method must be PAYE or UMBRELLA',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'source_pay_method', v_component.source_pay_method
    )::text;
  end if;

  v_old_source_amount := round(coalesce(v_component.source_amount, 0), 2);
  v_old_remaining_source_amount := round(coalesce(v_component.remaining_source_amount, 0), 2);

  if v_old_remaining_source_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'COMPONENT_NO_REMAINING_BALANCE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: component has no remaining source amount to restructure',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'remaining_source_amount', v_old_remaining_source_amount
    )::text;
  end if;

  if round(coalesce(v_case.outstanding_amount, 0), 2) <> v_old_remaining_source_amount then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_COMPONENT_BALANCE_MISMATCH',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance case outstanding_amount must match the open component remaining_source_amount',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'case_outstanding_amount', round(coalesce(v_case.outstanding_amount, 0), 2),
      'component_remaining_source_amount', v_old_remaining_source_amount
    )::text;
  end if;

  v_requires_restructure := (
    v_candidate_pay_method is distinct from v_old_source_pay_method
    or coalesce(v_component.is_resolution_stale, false) = true
    or nullif(btrim(coalesce(v_component.stale_reason, '')), '') is not null
  );

  if v_requires_restructure is distinct from true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'RESTRUCTURE_NOT_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: restructure is not required because the case is already aligned to the current pay channel and is not stale',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'source_pay_method', v_old_source_pay_method,
      'candidate_pay_method', v_candidate_pay_method,
      'is_resolution_stale', coalesce(v_component.is_resolution_stale, false),
      'stale_reason', v_component.stale_reason
    )::text;
  end if;

  select exists (
    select 1
    from public.pay_batch_items pbi
    join public.pay_batch_candidates pbc
      on pbc.id = pbi.pay_batch_candidate_id
    join public.pay_batches pb
      on pb.id = pbc.pay_batch_id
    where (
        pbi.finance_case_id = p_finance_case_id
        or pbi.source_ref = ('advance:' || p_finance_case_id::text)
      )
      and pbi.item_type = 'MANUAL_DEBT_RECOVERY'
      and coalesce(pbi.is_voided, false) = false
      and pb.cancelled_at_utc is null
      and upper(coalesce(pb.status, '')) not in ('CANCELLED', 'COMPLETED', 'SETTLED')
  )
  into v_has_open_batch_item;

  if v_has_open_batch_item then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CASE_ALREADY_IN_OPEN_BATCH',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: cannot restructure while the case is already included in an open pay batch',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  v_restructure_start_week_start := coalesce(v_case.next_due_week_start, v_case.start_week_start);
  if v_restructure_start_week_start is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'START_WEEK_START_REQUIRED',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: current next_due_week_start or start_week_start is required',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if public._pay_week_start_monday(v_restructure_start_week_start) <> v_restructure_start_week_start then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'START_WEEK_START_NOT_MONDAY',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: restructure start week must be a Monday',
      'finance_case_id', p_finance_case_id::text,
      'start_week_start', v_restructure_start_week_start::text
    )::text;
  end if;

  select
    sfp.vat_rate_pct,
    sfp.erni_pct
  into v_finance_settings
  from public.settings_finance_pick(v_today_uk) sfp
  limit 1;

  if v_finance_settings.vat_rate_pct is null or v_finance_settings.erni_pct is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'FINANCE_SETTINGS_MISSING',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: finance settings missing vat_rate_pct and/or erni_pct'
    )::text;
  end if;

  v_relevant_erni_pct := case
    when coalesce(v_component.saved_resolution_payload_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
      then round((v_component.saved_resolution_payload_json->>'relevant_erni_pct')::numeric, 6)
    when coalesce(v_component.saved_resolution_result_json->>'relevant_erni_pct', '') ~ '^-?\d+(\.\d+)?$'
      then round((v_component.saved_resolution_result_json->>'relevant_erni_pct')::numeric, 6)
    else round(v_finance_settings.erni_pct, 6)
  end;

  v_vat_rate_pct := case
    when coalesce(v_component.saved_resolution_payload_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
      then round((v_component.saved_resolution_payload_json->>'vat_rate_pct')::numeric, 6)
    when coalesce(v_component.saved_resolution_result_json->>'vat_rate_pct', '') ~ '^-?\d+(\.\d+)?$'
      then round((v_component.saved_resolution_result_json->>'vat_rate_pct')::numeric, 6)
    else round(v_finance_settings.vat_rate_pct, 6)
  end;

  v_umbrella_vat_chargeable := coalesce(
    case
      when lower(coalesce(v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable', '')) in ('true', 'false')
        then (v_component.saved_resolution_payload_json->>'umbrella_vat_chargeable')::boolean
      else null::boolean
    end,
    case
      when lower(coalesce(v_component.saved_resolution_result_json->>'umbrella_vat_chargeable', '')) in ('true', 'false')
        then (v_component.saved_resolution_result_json->>'umbrella_vat_chargeable')::boolean
      else null::boolean
    end,
    case
      when lower(coalesce(v_component.source_basis_json->>'umbrella_vat_chargeable', '')) in ('true', 'false')
        then (v_component.source_basis_json->>'umbrella_vat_chargeable')::boolean
      else null::boolean
    end,
    false
  );

  select count(*)::integer
  into v_default_remaining_weeks
  from jsonb_array_elements(coalesce(v_case.schedule_json, '[]'::jsonb)) as sched(schedule_row)
  where coalesce(sched.schedule_row->>'week_start', '') ~ '^\d{4}-\d{2}-\d{2}$'
    and (sched.schedule_row->>'week_start')::date >= v_restructure_start_week_start
    and coalesce(
      case
        when coalesce(sched.schedule_row->>'amount', '') ~ '^-?\d+(\.\d+)?$'
          then round((sched.schedule_row->>'amount')::numeric, 2)
        else null::numeric
      end,
      0::numeric
    ) < 0;

  if v_default_remaining_weeks is null or v_default_remaining_weeks < 1 then
    if round(coalesce(v_case.weekly_due, 0), 2) > 0 and round(coalesce(v_case.outstanding_amount, 0), 2) > 0 then
      v_default_remaining_weeks := greatest(ceil(round(coalesce(v_case.outstanding_amount, 0), 2) / round(coalesce(v_case.weekly_due, 0), 2))::integer, 1);
    elsif coalesce(v_case.weeks_total, 0) > 0 then
      v_default_remaining_weeks := v_case.weeks_total;
    else
      v_default_remaining_weeks := 1;
    end if;
  end if;

  if v_schedule_input_mode_norm = 'BY_WEEKS' then
    if p_weeks_total is not null and p_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'WEEKS_TOTAL_INVALID',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: weeks_total must be >= 1 when schedule_input_mode is BY_WEEKS',
        'weeks_total', p_weeks_total
      )::text;
    end if;

    if v_resolution_path_norm = 'MANUAL' and p_weeks_total is null then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'WEEKS_TOTAL_REQUIRED',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: weeks_total is required for MANUAL resolution when schedule_input_mode is BY_WEEKS',
        'schedule_input_mode', v_schedule_input_mode_norm,
        'resolution_path', v_resolution_path_norm
      )::text;
    end if;

    v_selected_weeks_total := coalesce(p_weeks_total, v_default_remaining_weeks);

    if v_selected_weeks_total is null or v_selected_weeks_total < 1 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'WEEKS_TOTAL_REQUIRED',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: weeks_total is required when schedule_input_mode is BY_WEEKS',
        'schedule_input_mode', v_schedule_input_mode_norm
      )::text;
    end if;
  else
    v_selected_weekly_due := case
      when p_weekly_due is null then null::numeric(12,2)
      else round(p_weekly_due, 2)
    end;

    if v_selected_weekly_due is null or v_selected_weekly_due <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'WEEKLY_DUE_REQUIRED',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: weekly_due must be > 0 when schedule_input_mode is BY_WEEKLY_DUE',
        'weekly_due', p_weekly_due
      )::text;
    end if;
  end if;

  v_basis_remaining_source_amount := v_old_remaining_source_amount;
  if v_basis_remaining_source_amount <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'BASIS_AMOUNT_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: basis remaining source amount must be > 0',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_component.id::text,
      'basis_remaining_source_amount', v_basis_remaining_source_amount
    )::text;
  end if;

  if v_resolution_path_norm = 'SUGGESTED' then
    if v_old_source_pay_method = 'PAYE' and v_candidate_pay_method = 'UMBRELLA' then
      v_target_amounts_json := public._pay_convert_paye_to_umbrella(
        v_basis_remaining_source_amount,
        v_relevant_erni_pct,
        v_vat_rate_pct,
        v_umbrella_vat_chargeable
      );
      v_confirmed_new_remaining_ex := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
      v_confirmed_new_remaining_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
      v_confirmed_new_remaining_inc := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
    elsif v_old_source_pay_method = 'UMBRELLA' and v_candidate_pay_method = 'PAYE' then
      v_confirmed_new_remaining_ex := public._pay_convert_umbrella_to_paye_ex(v_basis_remaining_source_amount, v_relevant_erni_pct);
      v_confirmed_new_remaining_vat := 0;
      v_confirmed_new_remaining_inc := v_confirmed_new_remaining_ex;
    elsif v_old_source_pay_method = v_candidate_pay_method and v_candidate_pay_method = 'PAYE' then
      v_confirmed_new_remaining_ex := v_basis_remaining_source_amount;
      v_confirmed_new_remaining_vat := 0;
      v_confirmed_new_remaining_inc := v_confirmed_new_remaining_ex;
    elsif v_old_source_pay_method = v_candidate_pay_method and v_candidate_pay_method = 'UMBRELLA' then
      v_target_amounts_json := public._pay_umbrella_vat_calc(
        v_basis_remaining_source_amount,
        v_vat_rate_pct,
        v_umbrella_vat_chargeable
      );
      v_confirmed_new_remaining_ex := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
      v_confirmed_new_remaining_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
      v_confirmed_new_remaining_inc := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
    else
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'UNSUPPORTED_SUGGESTED_CONVERSION',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: unsupported taxable channel conversion pair for suggested resolution',
        'finance_case_id', p_finance_case_id::text,
        'finance_component_id', v_component.id::text,
        'source_pay_method', v_old_source_pay_method,
        'target_pay_method', v_candidate_pay_method
      )::text;
    end if;
  else
    if p_manual_total_remaining is null or round(p_manual_total_remaining, 2) <= 0 then
      raise exception '%', jsonb_build_object(
        'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
        'code', 'MANUAL_TOTAL_REMAINING_REQUIRED',
        'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: manual_total_remaining must be > 0 for MANUAL resolution',
        'manual_total_remaining', p_manual_total_remaining
      )::text;
    end if;

    v_confirmed_new_remaining_ex := round(p_manual_total_remaining, 2);

    if v_candidate_pay_method = 'PAYE' then
      v_confirmed_new_remaining_vat := 0;
      v_confirmed_new_remaining_inc := v_confirmed_new_remaining_ex;
    else
      v_target_amounts_json := public._pay_umbrella_vat_calc(
        v_confirmed_new_remaining_ex,
        v_vat_rate_pct,
        v_umbrella_vat_chargeable
      );
      v_confirmed_new_remaining_ex := round(coalesce((v_target_amounts_json->>'ex')::numeric, 0), 2);
      v_confirmed_new_remaining_vat := round(coalesce((v_target_amounts_json->>'vat')::numeric, 0), 2);
      v_confirmed_new_remaining_inc := round(coalesce((v_target_amounts_json->>'inc')::numeric, 0), 2);
    end if;
  end if;

  if v_confirmed_new_remaining_ex <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'CONFIRMED_REMAINING_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: confirmed remaining amount must be > 0',
      'confirmed_remaining_amount_ex_vat', v_confirmed_new_remaining_ex
    )::text;
  end if;

  v_recovered_so_far_ex := round(greatest(coalesce(v_case.original_amount, 0) - coalesce(v_case.outstanding_amount, 0), 0), 2);
  v_new_case_total_ex := round(v_recovered_so_far_ex + v_confirmed_new_remaining_ex, 2);

  if v_new_case_total_ex <= 0 then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'NEW_CASE_TOTAL_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: recomputed case total must be > 0',
      'recovered_so_far_ex', v_recovered_so_far_ex,
      'confirmed_new_remaining_ex', v_confirmed_new_remaining_ex,
      'new_case_total_ex', v_new_case_total_ex
    )::text;
  end if;

  v_before_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_case.candidate_id::text,
      'finance_component_id', v_component.id::text,
      'case_type', v_case.case_type::text,
      'status', v_case.status::text,
      'taxability', case when v_case.taxability is null then null else v_case.taxability::text end,
      'routing_kind', case when v_case.routing_kind is null then null else v_case.routing_kind::text end,
      'source_pay_method_before', v_old_source_pay_method,
      'candidate_pay_method_before', v_candidate_pay_method,
      'source_amount_before', v_old_source_amount,
      'remaining_source_amount_before', v_old_remaining_source_amount,
      'original_amount_before', round(coalesce(v_case.original_amount, 0), 2),
      'outstanding_amount_before', round(coalesce(v_case.outstanding_amount, 0), 2),
      'weekly_due_before', round(coalesce(v_case.weekly_due, 0), 2),
      'weeks_total_before', v_case.weeks_total,
      'start_week_start_before', case when v_case.start_week_start is null then null else v_case.start_week_start::text end,
      'next_due_week_start_before', case when v_case.next_due_week_start is null then null else v_case.next_due_week_start::text end,
      'schedule_json_before', coalesce(v_case.schedule_json, '[]'::jsonb),
      'is_resolution_stale_before', coalesce(v_component.is_resolution_stale, false),
      'stale_reason_before', v_component.stale_reason,
      'saved_target_pay_method_before', v_component.saved_target_pay_method,
      'saved_resolution_mode_before', case when v_component.saved_resolution_mode is null then null else v_component.saved_resolution_mode::text end,
      'saved_resolution_payload_json_before', v_component.saved_resolution_payload_json,
      'saved_resolution_result_json_before', v_component.saved_resolution_result_json,
      'resolution_fingerprint_before', v_component.resolution_fingerprint
    )
  );

  v_update_result := public.pay_manual_debt_adjustment_update(
    p_finance_case_id => p_finance_case_id,
    p_actor_user_id => p_actor_user_id,
    p_amount => v_new_case_total_ex,
    p_weekly_due => case when v_schedule_input_mode_norm = 'BY_WEEKLY_DUE' then v_selected_weekly_due else null::numeric end,
    p_weeks_total => case when v_schedule_input_mode_norm = 'BY_WEEKS' then v_selected_weeks_total else null::integer end,
    p_start_week_start => v_restructure_start_week_start,
    p_adjustment_comment => null::text,
    p_note => null::text,
    p_minimum_earnings_threshold => null::numeric,
    p_take_home_floor_override => null::numeric,
    p_taxability => 'TAXABLE'
  );

  select pa.*
  into v_updated_case
  from public.pay_advances pa
  where pa.id = p_finance_case_id;

  if v_updated_case.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_CASE_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated finance case could not be reloaded',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  select pfc.*
  into v_updated_component
  from public.pay_finance_case_components pfc
  where pfc.finance_case_id = p_finance_case_id
    and pfc.closed_at_utc is null
    and pfc.component_key_type = 'CASE_TOTAL'
    and pfc.component_key_value = 'TOTAL'
  order by pfc.updated_at_utc desc, pfc.created_at_utc desc, pfc.id desc
  limit 1;

  if v_updated_component.id is null then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_COMPONENT_NOT_FOUND',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated component could not be reloaded',
      'finance_case_id', p_finance_case_id::text
    )::text;
  end if;

  if v_updated_component.classification <> 'TAXABLE_CHANNEL_SENSITIVE'::public.pay_finance_component_classification_enum then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_COMPONENT_CLASSIFICATION_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated component classification drifted from TAXABLE_CHANNEL_SENSITIVE',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_updated_component.id::text,
      'classification', v_updated_component.classification::text
    )::text;
  end if;

  if upper(coalesce(v_updated_component.source_pay_method, '')) <> v_candidate_pay_method then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_SOURCE_PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated component source_pay_method must match the candidate current pay method',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_updated_component.id::text,
      'updated_source_pay_method', v_updated_component.source_pay_method,
      'candidate_pay_method', v_candidate_pay_method
    )::text;
  end if;

  if round(coalesce(v_updated_case.outstanding_amount, 0), 2) <> round(coalesce(v_updated_component.remaining_source_amount, 0), 2) then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_BALANCE_MISMATCH',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated finance case outstanding_amount must match updated component remaining_source_amount',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_updated_component.id::text,
      'updated_case_outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2),
      'updated_component_remaining_source_amount', round(coalesce(v_updated_component.remaining_source_amount, 0), 2)
    )::text;
  end if;

  if round(coalesce(v_updated_case.outstanding_amount, 0), 2) <> v_confirmed_new_remaining_ex then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_REMAINING_AMOUNT_MISMATCH',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated outstanding_amount must match the confirmed new remaining amount',
      'finance_case_id', p_finance_case_id::text,
      'confirmed_new_remaining_ex', v_confirmed_new_remaining_ex,
      'updated_outstanding_amount', round(coalesce(v_updated_case.outstanding_amount, 0), 2)
    )::text;
  end if;

  if v_updated_component.saved_target_pay_method is distinct from v_candidate_pay_method then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_TARGET_PAY_METHOD_INVALID',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated component saved_target_pay_method must match the candidate current pay method',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_updated_component.id::text,
      'saved_target_pay_method', v_updated_component.saved_target_pay_method,
      'candidate_pay_method', v_candidate_pay_method
    )::text;
  end if;

  if coalesce(v_updated_component.is_resolution_stale, false) = true then
    raise exception '%', jsonb_build_object(
      'error', 'PAY_MANUAL_DEBT_ADJUSTMENT_RESOLVE_TAXABLE_CHANNEL_CHANGE',
      'code', 'UPDATED_COMPONENT_STILL_STALE',
      'message', 'pay_manual_debt_adjustment_resolve_taxable_channel_change: updated component must not remain stale after restructure',
      'finance_case_id', p_finance_case_id::text,
      'finance_component_id', v_updated_component.id::text,
      'stale_reason', v_updated_component.stale_reason
    )::text;
  end if;

  v_after_json := jsonb_strip_nulls(
    jsonb_build_object(
      'finance_case_id', p_finance_case_id::text,
      'candidate_id', v_updated_case.candidate_id::text,
      'finance_component_id', v_updated_component.id::text,
      'resolution_path', v_resolution_path_norm,
      'schedule_input_mode', v_schedule_input_mode_norm,
      'source_pay_method_before', v_old_source_pay_method,
      'target_pay_method_after', v_candidate_pay_method,
      'remaining_source_amount_before', v_old_remaining_source_amount,
      'confirmed_new_remaining_amount_ex_vat', v_confirmed_new_remaining_ex,
      'confirmed_new_remaining_amount_vat', v_confirmed_new_remaining_vat,
      'confirmed_new_remaining_amount_inc_vat', v_confirmed_new_remaining_inc,
      'recovered_so_far_ex', v_recovered_so_far_ex,
      'new_case_total_ex', v_new_case_total_ex,
      'weekly_due_after', round(coalesce(v_updated_case.weekly_due, 0), 2),
      'weeks_total_after', v_updated_case.weeks_total,
      'start_week_start_after', case when v_updated_case.start_week_start is null then null else v_updated_case.start_week_start::text end,
      'next_due_week_start_after', case when v_updated_case.next_due_week_start is null then null else v_updated_case.next_due_week_start::text end,
      'schedule_json_after', coalesce(v_updated_case.schedule_json, '[]'::jsonb),
      'source_amount_after', round(coalesce(v_updated_component.source_amount, 0), 2),
      'remaining_source_amount_after', round(coalesce(v_updated_component.remaining_source_amount, 0), 2),
      'source_pay_method_after', v_updated_component.source_pay_method,
      'saved_target_pay_method_after', v_updated_component.saved_target_pay_method,
      'saved_resolution_mode_after', case when v_updated_component.saved_resolution_mode is null then null else v_updated_component.saved_resolution_mode::text end,
      'saved_resolution_payload_json_after', v_updated_component.saved_resolution_payload_json,
      'saved_resolution_result_json_after', v_updated_component.saved_resolution_result_json,
      'resolution_fingerprint_after', v_updated_component.resolution_fingerprint,
      'is_resolution_stale_after', coalesce(v_updated_component.is_resolution_stale, false),
      'stale_reason_after', v_updated_component.stale_reason,
      'taxability_after', case when v_updated_case.taxability is null then null else v_updated_case.taxability::text end,
      'routing_kind_after', case when v_updated_case.routing_kind is null then null else v_updated_case.routing_kind::text end,
      'minimum_earnings_threshold_after', v_updated_case.minimum_earnings_threshold,
      'take_home_floor_override_after', v_updated_case.take_home_floor_override
    )
  );

  v_event_note := coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Resolved taxable manual debt adjustment channel change in Banking Pay');

  insert into public.pay_finance_case_events(
    finance_case_id,
    finance_component_id,
    event_type,
    event_at_utc,
    actor_user_id,
    pay_batch_id,
    before_json,
    after_json,
    reason,
    note
  )
  values (
    p_finance_case_id,
    v_updated_component.id,
    'TAXABLE_CHANNEL_RESTRUCTURE_APPLIED',
    v_now_utc,
    p_actor_user_id,
    null::uuid,
    v_before_json,
    v_after_json,
    v_resolution_path_norm,
    v_event_note
  );

  return jsonb_build_object(
    'ok', true,
    'finance_case_id', p_finance_case_id::text,
    'candidate_id', v_updated_case.candidate_id::text,
    'finance_component_id', v_updated_component.id::text,
    'source_pay_method_before', v_old_source_pay_method,
    'target_pay_method_after', v_candidate_pay_method,
    'confirmed_remaining_amount_ex_vat', v_confirmed_new_remaining_ex,
    'confirmed_remaining_amount_vat', v_confirmed_new_remaining_vat,
    'confirmed_remaining_amount_inc_vat', v_confirmed_new_remaining_inc,
    'weekly_due', round(coalesce(v_updated_case.weekly_due, 0), 2),
    'weeks_total', v_updated_case.weeks_total,
    'start_week_start', case when v_updated_case.start_week_start is null then null else v_updated_case.start_week_start::text end,
    'next_due_week_start', case when v_updated_case.next_due_week_start is null then null else v_updated_case.next_due_week_start::text end,
    'resolution_path', v_resolution_path_norm,
    'schedule_input_mode', v_schedule_input_mode_norm,
    'schedule_json', coalesce(v_updated_case.schedule_json, '[]'::jsonb),
    'recovered_so_far_ex', v_recovered_so_far_ex,
    'new_case_total_ex', v_new_case_total_ex,
    'minimum_earnings_threshold', v_updated_case.minimum_earnings_threshold,
    'take_home_floor_override', v_updated_case.take_home_floor_override,
    'update_result', v_update_result
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public._pay_payment_correction_selected_items(
  p_pay_batch_id uuid,
  p_selection_json jsonb,
  p_include_already_corrected boolean DEFAULT false
)
RETURNS TABLE(
  pay_batch_id uuid,
  pay_batch_candidate_id uuid,
  candidate_id uuid,
  candidate_display_name text,
  candidate_tms_ref text,
  pay_batch_item_id uuid,
  item_type text,
  timesheet_id uuid,
  pay_bank_transfer_id uuid,
  transfer_status text,
  transfer_amount numeric,
  transfer_group_key text,
  payee_entity_kind text,
  payee_entity_id uuid,
  umbrella_id uuid,
  umbrella_name text,
  finance_case_id uuid,
  finance_component_id uuid,
  reservation_id uuid,
  pay_channel text,
  frozen_source_pay_method text,
  frozen_target_pay_method text,
  current_candidate_pay_method text,
  economic_key_type text,
  economic_key_value text,
  source_amount_ex_vat numeric,
  target_amount_ex_vat numeric,
  key_resolution_source text,
  key_resolution_failure_reason text,
  amount_ex_vat numeric,
  amount_vat numeric,
  amount_inc_vat numeric,
  is_voided boolean,
  already_corrected boolean,
  applied_correction_kinds text[]
)
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_scope_type text;
  v_uuid_regex text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';

  v_pay_batch_candidate_ids uuid[] := ARRAY[]::uuid[];
  v_pay_bank_transfer_ids uuid[] := ARRAY[]::uuid[];
  v_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_expected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_finance_case_ids uuid[] := ARRAY[]::uuid[];
  v_finance_component_ids uuid[] := ARRAY[]::uuid[];
  v_reservation_ids uuid[] := ARRAY[]::uuid[];
  v_item_types text[] := ARRAY[]::text[];

  v_umbrella_id uuid;
  v_umbrella_id_text text;
  v_transfer_group_key text;
  v_expected_item_count integer := NULL::integer;
  v_expected_item_count_text text;
  v_work_unit text := NULL::text;
  v_source_correction_request_id_text text := NULL::text;
  v_explicit_item_ids_authoritative boolean := false;

  v_return_item_ids uuid[] := ARRAY[]::uuid[];
  v_selected_item_count integer := 0;
  v_selected_already_corrected_count integer := 0;
  v_return_item_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_returned_count integer := 0;
  v_sorted_return_item_ids uuid[] := ARRAY[]::uuid[];
  v_sorted_expected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_CORRECTION_SELECTED_ITEMS_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'selection_scope_type', CASE
        WHEN p_selection_json IS NULL THEN NULL
        ELSE p_selection_json->>'scope_type'
      END,
      'include_already_corrected', COALESCE(p_include_already_corrected, false),
      'selection_keys', CASE
        WHEN p_selection_json IS NULL OR jsonb_typeof(p_selection_json) <> 'object' THEN '[]'::jsonb
        ELSE COALESCE((
          SELECT jsonb_agg(selection_keys.key_name ORDER BY selection_keys.key_name)
          FROM jsonb_object_keys(p_selection_json) AS selection_keys(key_name)
        ), '[]'::jsonb)
      END
    ),
    'pay_payment_correction',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.pay_batches AS batch_check
    WHERE batch_check.id = p_pay_batch_id
  ) THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_scope_type := upper(nullif(btrim(coalesce(p_selection_json->>'scope_type', '')), ''));

  IF v_scope_type IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SCOPE_TYPE_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_SCOPE_TYPE_REQUIRED',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  IF v_scope_type = 'TIMESHEET'
     OR p_selection_json ? 'timesheet_id'
     OR p_selection_json ? 'timesheet_ids' THEN
    RAISE EXCEPTION 'TIMESHEET_SCOPE_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'TIMESHEET_SCOPE_NOT_ALLOWED',
              'pay_batch_id', p_pay_batch_id,
              'scope_type', v_scope_type
            )::text;
  END IF;

  IF v_scope_type NOT IN ('BATCH', 'CANDIDATES', 'TRANSFER', 'UMBRELLA_PAYMENT_GROUP') THEN
    RAISE EXCEPTION 'UNSUPPORTED_PAYMENT_CORRECTION_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'UNSUPPORTED_PAYMENT_CORRECTION_SCOPE',
              'pay_batch_id', p_pay_batch_id,
              'scope_type', v_scope_type,
              'supported_scope_types', jsonb_build_array(
                'BATCH',
                'CANDIDATES',
                'TRANSFER',
                'UMBRELLA_PAYMENT_GROUP'
              )
            )::text;
  END IF;

  IF p_selection_json ? 'pay_batch_candidate_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'pay_batch_candidate_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'PAY_BATCH_CANDIDATE_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANDIDATE_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'pay_bank_transfer_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'pay_bank_transfer_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFER_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'pay_batch_item_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'pay_batch_item_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'PAY_BATCH_ITEM_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ITEM_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'expected_pay_batch_item_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'EXPECTED_PAY_BATCH_ITEM_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'EXPECTED_PAY_BATCH_ITEM_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'finance_case_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'finance_case_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'FINANCE_CASE_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'FINANCE_CASE_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'finance_component_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'finance_component_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'FINANCE_COMPONENT_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'FINANCE_COMPONENT_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'reservation_ids'
     AND COALESCE(jsonb_typeof(p_selection_json->'reservation_ids'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'RESERVATION_IDS_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'RESERVATION_IDS_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF p_selection_json ? 'item_types'
     AND COALESCE(jsonb_typeof(p_selection_json->'item_types'), 'null') <> 'array' THEN
    RAISE EXCEPTION 'ITEM_TYPES_MUST_BE_ARRAY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'ITEM_TYPES_MUST_BE_ARRAY', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT candidate_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_batch_candidate_ids'), 'null') = 'array'
          THEN p_selection_json->'pay_batch_candidate_ids'
        ELSE '[]'::jsonb
      END
    ) AS candidate_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'pay_batch_candidate_id'
    WHERE p_selection_json ? 'pay_batch_candidate_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_candidate_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT candidate_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_batch_candidate_ids'), 'null') = 'array'
            THEN p_selection_json->'pay_batch_candidate_ids'
          ELSE '[]'::jsonb
        END
      ) AS candidate_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'pay_batch_candidate_id'
      WHERE p_selection_json ? 'pay_batch_candidate_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_PAY_BATCH_CANDIDATE_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_PAY_BATCH_CANDIDATE_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT transfer_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_bank_transfer_ids'), 'null') = 'array'
          THEN p_selection_json->'pay_bank_transfer_ids'
        ELSE '[]'::jsonb
      END
    ) AS transfer_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'pay_bank_transfer_id'
    WHERE p_selection_json ? 'pay_bank_transfer_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_bank_transfer_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT transfer_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_bank_transfer_ids'), 'null') = 'array'
            THEN p_selection_json->'pay_bank_transfer_ids'
          ELSE '[]'::jsonb
        END
      ) AS transfer_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'pay_bank_transfer_id'
      WHERE p_selection_json ? 'pay_bank_transfer_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_PAY_BANK_TRANSFER_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_PAY_BANK_TRANSFER_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT item_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_batch_item_ids'), 'null') = 'array'
          THEN p_selection_json->'pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS item_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'pay_batch_item_id'
    WHERE p_selection_json ? 'pay_batch_item_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_pay_batch_item_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT item_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'pay_batch_item_ids'), 'null') = 'array'
            THEN p_selection_json->'pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS item_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'pay_batch_item_id'
      WHERE p_selection_json ? 'pay_batch_item_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_PAY_BATCH_ITEM_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_PAY_BATCH_ITEM_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT expected_item_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
          THEN p_selection_json->'expected_pay_batch_item_ids'
        ELSE '[]'::jsonb
      END
    ) AS expected_item_array_values(raw_value)
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_expected_pay_batch_item_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT expected_item_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') = 'array'
            THEN p_selection_json->'expected_pay_batch_item_ids'
          ELSE '[]'::jsonb
        END
      ) AS expected_item_array_values(raw_value)
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_EXPECTED_PAY_BATCH_ITEM_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_EXPECTED_PAY_BATCH_ITEM_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT finance_case_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'finance_case_ids'), 'null') = 'array'
          THEN p_selection_json->'finance_case_ids'
        ELSE '[]'::jsonb
      END
    ) AS finance_case_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'finance_case_id'
    WHERE p_selection_json ? 'finance_case_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_finance_case_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT finance_case_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'finance_case_ids'), 'null') = 'array'
            THEN p_selection_json->'finance_case_ids'
          ELSE '[]'::jsonb
        END
      ) AS finance_case_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'finance_case_id'
      WHERE p_selection_json ? 'finance_case_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_FINANCE_CASE_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_FINANCE_CASE_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT finance_component_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'finance_component_ids'), 'null') = 'array'
          THEN p_selection_json->'finance_component_ids'
        ELSE '[]'::jsonb
      END
    ) AS finance_component_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'finance_component_id'
    WHERE p_selection_json ? 'finance_component_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_finance_component_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT finance_component_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'finance_component_ids'), 'null') = 'array'
            THEN p_selection_json->'finance_component_ids'
          ELSE '[]'::jsonb
        END
      ) AS finance_component_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'finance_component_id'
      WHERE p_selection_json ? 'finance_component_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_FINANCE_COMPONENT_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_FINANCE_COMPONENT_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT reservation_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'reservation_ids'), 'null') = 'array'
          THEN p_selection_json->'reservation_ids'
        ELSE '[]'::jsonb
      END
    ) AS reservation_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'reservation_id'
    WHERE p_selection_json ? 'reservation_id'
  ),
  cleaned_values AS (
    SELECT nullif(btrim(raw_values.raw_value), '') AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value::uuid), ARRAY[]::uuid[])
  INTO v_reservation_ids
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL
    AND cleaned_values.clean_value ~ v_uuid_regex;

  IF EXISTS (
    WITH raw_values AS (
      SELECT reservation_array_values.raw_value
      FROM jsonb_array_elements_text(
        CASE
          WHEN COALESCE(jsonb_typeof(p_selection_json->'reservation_ids'), 'null') = 'array'
            THEN p_selection_json->'reservation_ids'
          ELSE '[]'::jsonb
        END
      ) AS reservation_array_values(raw_value)
      UNION ALL
      SELECT p_selection_json->>'reservation_id'
      WHERE p_selection_json ? 'reservation_id'
    )
    SELECT 1
    FROM raw_values
    WHERE nullif(btrim(raw_values.raw_value), '') IS NOT NULL
      AND nullif(btrim(raw_values.raw_value), '') !~ v_uuid_regex
  ) THEN
    RAISE EXCEPTION 'INVALID_RESERVATION_ID'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'INVALID_RESERVATION_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  WITH raw_values AS (
    SELECT item_type_array_values.raw_value
    FROM jsonb_array_elements_text(
      CASE
        WHEN COALESCE(jsonb_typeof(p_selection_json->'item_types'), 'null') = 'array'
          THEN p_selection_json->'item_types'
        ELSE '[]'::jsonb
      END
    ) AS item_type_array_values(raw_value)
    UNION ALL
    SELECT p_selection_json->>'item_type'
    WHERE p_selection_json ? 'item_type'
  ),
  cleaned_values AS (
    SELECT upper(nullif(btrim(raw_values.raw_value), '')) AS clean_value
    FROM raw_values
  )
  SELECT COALESCE(array_agg(DISTINCT cleaned_values.clean_value), ARRAY[]::text[])
  INTO v_item_types
  FROM cleaned_values
  WHERE cleaned_values.clean_value IS NOT NULL;

  v_umbrella_id_text := nullif(btrim(coalesce(p_selection_json->>'umbrella_id', '')), '');
  v_transfer_group_key := nullif(btrim(coalesce(p_selection_json->>'transfer_group_key', '')), '');

  IF v_umbrella_id_text IS NOT NULL THEN
    IF v_umbrella_id_text !~ v_uuid_regex THEN
      RAISE EXCEPTION 'INVALID_UMBRELLA_ID'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object('code', 'INVALID_UMBRELLA_ID', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
    END IF;

    v_umbrella_id := v_umbrella_id_text::uuid;
  END IF;

  v_expected_item_count_text := nullif(btrim(coalesce(p_selection_json->>'expected_item_count', '')), '');
  IF v_expected_item_count_text IS NOT NULL THEN
    BEGIN
      v_expected_item_count := v_expected_item_count_text::integer;
    EXCEPTION
      WHEN OTHERS THEN
        RAISE EXCEPTION 'EXPECTED_ITEM_COUNT_MUST_BE_INTEGER'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'EXPECTED_ITEM_COUNT_MUST_BE_INTEGER',
                  'pay_batch_id', p_pay_batch_id,
                  'expected_item_count', v_expected_item_count_text
                )::text;
    END;

    IF v_expected_item_count < 0 THEN
      RAISE EXCEPTION 'EXPECTED_ITEM_COUNT_MUST_NOT_BE_NEGATIVE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'EXPECTED_ITEM_COUNT_MUST_NOT_BE_NEGATIVE',
                'pay_batch_id', p_pay_batch_id,
                'expected_item_count', v_expected_item_count
              )::text;
    END IF;
  END IF;

  v_work_unit := upper(NULLIF(btrim(COALESCE(p_selection_json->>'work_unit', '')), ''));
  v_source_correction_request_id_text := NULLIF(btrim(COALESCE(p_selection_json->>'source_correction_request_id', '')), '');

  v_explicit_item_ids_authoritative := (
    (
      COALESCE(array_length(v_pay_batch_item_ids, 1), 0) > 0
      OR COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0) > 0
    )
    AND (
      v_source_correction_request_id_text IS NOT NULL
      OR v_work_unit IN ('BATCH', 'CANDIDATE', 'TRANSFER', 'CANDIDATE_TRANSFER', 'FINANCE_CASE')
    )
  );

  IF COALESCE(v_explicit_item_ids_authoritative, false)
     AND COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0
     AND COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0) > 0 THEN
    v_pay_batch_item_ids := v_expected_pay_batch_item_ids;
  END IF;

  IF v_scope_type = 'CANDIDATES'
     AND COALESCE(array_length(v_pay_batch_candidate_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'PAY_BATCH_CANDIDATE_SELECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_CANDIDATE_SELECTION_REQUIRED', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF v_scope_type = 'TRANSFER'
     AND COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0 THEN
    RAISE EXCEPTION 'PAY_BANK_TRANSFER_SELECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BANK_TRANSFER_SELECTION_REQUIRED', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF v_scope_type = 'UMBRELLA_PAYMENT_GROUP'
     AND v_umbrella_id IS NULL THEN
    RAISE EXCEPTION 'UMBRELLA_SELECTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'UMBRELLA_SELECTION_REQUIRED', 'pay_batch_id', p_pay_batch_id, 'scope_type', v_scope_type)::text;
  END IF;

  IF COALESCE(array_length(v_pay_batch_item_ids, 1), 0) > 0 THEN
    IF EXISTS (
      SELECT 1
      FROM unnest(v_pay_batch_item_ids) AS requested_item_ids(requested_pay_batch_item_id)
      LEFT JOIN public.pay_batch_items AS requested_pay_batch_items
        ON requested_pay_batch_items.id = requested_item_ids.requested_pay_batch_item_id
      LEFT JOIN public.pay_batch_candidates AS requested_pay_batch_candidates
        ON requested_pay_batch_candidates.id = requested_pay_batch_items.pay_batch_candidate_id
      WHERE requested_pay_batch_items.id IS NULL
         OR requested_pay_batch_candidates.pay_batch_id IS DISTINCT FROM p_pay_batch_id
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE',
                'pay_batch_id', p_pay_batch_id,
                'scope_type', v_scope_type,
                'reason', 'One or more supplied pay_batch_item_ids do not exist in the selected batch.'
              )::text;
    END IF;
  END IF;

  IF COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0) > 0 THEN
    IF EXISTS (
      SELECT 1
      FROM unnest(v_expected_pay_batch_item_ids) AS expected_item_ids(expected_pay_batch_item_id)
      LEFT JOIN public.pay_batch_items AS expected_pay_batch_items
        ON expected_pay_batch_items.id = expected_item_ids.expected_pay_batch_item_id
      LEFT JOIN public.pay_batch_candidates AS expected_pay_batch_candidates
        ON expected_pay_batch_candidates.id = expected_pay_batch_items.pay_batch_candidate_id
      WHERE expected_pay_batch_items.id IS NULL
         OR expected_pay_batch_candidates.pay_batch_id IS DISTINCT FROM p_pay_batch_id
    ) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE',
                'pay_batch_id', p_pay_batch_id,
                'scope_type', v_scope_type,
                'reason', 'One or more supplied expected_pay_batch_item_ids do not exist in the selected batch.'
              )::text;
    END IF;
  END IF;

  WITH applied_correction_rows AS (
    SELECT
      public.pay_payment_correction_items.pay_batch_item_id AS correction_pay_batch_item_id,
      public.pay_payment_correction_items.correction_item_kind AS correction_item_kind
    FROM public.pay_payment_correction_items
    WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
      AND public.pay_payment_correction_items.pay_batch_item_id IS NOT NULL
      AND public.pay_payment_correction_items.status = 'APPLIED'
  ),
  applied_corrections AS (
    SELECT
      applied_correction_rows.correction_pay_batch_item_id AS correction_pay_batch_item_id,
      array_agg(DISTINCT applied_correction_rows.correction_item_kind ORDER BY applied_correction_rows.correction_item_kind) AS applied_correction_kinds
    FROM applied_correction_rows
    GROUP BY applied_correction_rows.correction_pay_batch_item_id
  ),
  base_scope_items AS (
    SELECT DISTINCT
      public.pay_batch_items.id AS selected_pay_batch_item_id
    FROM public.pay_batch_items
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
      AND (
        v_scope_type = 'BATCH'
        OR (
          v_scope_type = 'CANDIDATES'
          AND public.pay_batch_candidates.id = ANY(v_pay_batch_candidate_ids)
        )
        OR (
          v_scope_type = 'TRANSFER'
          AND public.pay_batch_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
        )
        OR (
          v_scope_type = 'UMBRELLA_PAYMENT_GROUP'
          AND (
            public.pay_batch_items.umbrella_id = v_umbrella_id
            OR public.pay_bank_transfers.umbrella_id = v_umbrella_id
            OR (
              upper(coalesce(public.pay_bank_transfers.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY')
              AND public.pay_bank_transfers.payee_entity_id = v_umbrella_id
            )
          )
          AND (
            v_transfer_group_key IS NULL
            OR public.pay_bank_transfers.transfer_group_key = v_transfer_group_key
          )
        )
      )
  ),
  raw_selected_items AS (
    SELECT DISTINCT
      public.pay_batch_items.id AS selected_pay_batch_item_id
    FROM public.pay_batch_items
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    JOIN base_scope_items
      ON base_scope_items.selected_pay_batch_item_id = public.pay_batch_items.id
    WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
      AND (
        COALESCE(array_length(v_pay_batch_item_ids, 1), 0) = 0
        OR public.pay_batch_items.id = ANY(v_pay_batch_item_ids)
      )
      AND (
        COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0) = 0
        OR public.pay_batch_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
      )
      AND (
        COALESCE(v_explicit_item_ids_authoritative, false)
        OR COALESCE(array_length(v_finance_case_ids, 1), 0) = 0
        OR public.pay_batch_items.finance_case_id = ANY(v_finance_case_ids)
      )
      AND (
        COALESCE(v_explicit_item_ids_authoritative, false)
        OR COALESCE(array_length(v_finance_component_ids, 1), 0) = 0
        OR public.pay_batch_items.finance_component_id = ANY(v_finance_component_ids)
      )
      AND (
        COALESCE(v_explicit_item_ids_authoritative, false)
        OR COALESCE(array_length(v_reservation_ids, 1), 0) = 0
        OR public.pay_batch_items.reservation_id = ANY(v_reservation_ids)
      )
      AND (
        COALESCE(array_length(v_item_types, 1), 0) = 0
        OR upper(coalesce(public.pay_batch_items.item_type, '')) = ANY(v_item_types)
      )
  ),
  requested_item_scope_violations AS (
    SELECT requested_item_ids.requested_pay_batch_item_id
    FROM unnest(v_pay_batch_item_ids) AS requested_item_ids(requested_pay_batch_item_id)
    LEFT JOIN base_scope_items
      ON base_scope_items.selected_pay_batch_item_id = requested_item_ids.requested_pay_batch_item_id
    WHERE base_scope_items.selected_pay_batch_item_id IS NULL
  ),
  decorated_selected_items AS (
    SELECT
      raw_selected_items.selected_pay_batch_item_id AS selected_pay_batch_item_id,
      COALESCE(array_length(applied_corrections.applied_correction_kinds, 1), 0) > 0 AS selected_item_already_corrected
    FROM raw_selected_items
    LEFT JOIN applied_corrections
      ON applied_corrections.correction_pay_batch_item_id = raw_selected_items.selected_pay_batch_item_id
  ),
  selection_aggregate AS (
    SELECT
      COALESCE(
        array_agg(decorated_selected_items.selected_pay_batch_item_id ORDER BY decorated_selected_items.selected_pay_batch_item_id)
          FILTER (
            WHERE COALESCE(p_include_already_corrected, false)
               OR NOT decorated_selected_items.selected_item_already_corrected
          ),
        ARRAY[]::uuid[]
      ) AS return_item_ids,
      count(*)::integer AS selected_item_count,
      (count(*) FILTER (WHERE decorated_selected_items.selected_item_already_corrected))::integer AS selected_already_corrected_count
    FROM decorated_selected_items
  )
  SELECT
    selection_aggregate.return_item_ids,
    selection_aggregate.selected_item_count,
    selection_aggregate.selected_already_corrected_count
  INTO
    v_return_item_ids,
    v_selected_item_count,
    v_selected_already_corrected_count
  FROM selection_aggregate;

  IF COALESCE(array_length(v_pay_batch_item_ids, 1), 0) > 0
     AND EXISTS (
       WITH base_scope_items AS (
         SELECT DISTINCT
           public.pay_batch_items.id AS selected_pay_batch_item_id
         FROM public.pay_batch_items
         JOIN public.pay_batch_candidates
           ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
         LEFT JOIN public.pay_bank_transfers
           ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
         WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
           AND (
             v_scope_type = 'BATCH'
             OR (
               v_scope_type = 'CANDIDATES'
               AND public.pay_batch_candidates.id = ANY(v_pay_batch_candidate_ids)
             )
             OR (
               v_scope_type = 'TRANSFER'
               AND public.pay_batch_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
             )
             OR (
               v_scope_type = 'UMBRELLA_PAYMENT_GROUP'
               AND (
                 public.pay_batch_items.umbrella_id = v_umbrella_id
                 OR public.pay_bank_transfers.umbrella_id = v_umbrella_id
                 OR (
                   upper(coalesce(public.pay_bank_transfers.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY')
                   AND public.pay_bank_transfers.payee_entity_id = v_umbrella_id
                 )
               )
               AND (
                 v_transfer_group_key IS NULL
                 OR public.pay_bank_transfers.transfer_group_key = v_transfer_group_key
               )
             )
           )
       )
       SELECT 1
       FROM unnest(v_pay_batch_item_ids) AS requested_item_ids(requested_pay_batch_item_id)
       LEFT JOIN base_scope_items
         ON base_scope_items.selected_pay_batch_item_id = requested_item_ids.requested_pay_batch_item_id
       WHERE base_scope_items.selected_pay_batch_item_id IS NULL
     ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE',
              'pay_batch_id', p_pay_batch_id,
              'scope_type', v_scope_type,
              'pay_batch_item_ids', to_jsonb(v_pay_batch_item_ids)
            )::text;
  END IF;

  IF COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0) > 0
     AND EXISTS (
       WITH base_scope_items AS (
         SELECT DISTINCT
           public.pay_batch_items.id AS selected_pay_batch_item_id
         FROM public.pay_batch_items
         JOIN public.pay_batch_candidates
           ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
         LEFT JOIN public.pay_bank_transfers
           ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
         WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
           AND (
             v_scope_type = 'BATCH'
             OR (
               v_scope_type = 'CANDIDATES'
               AND public.pay_batch_candidates.id = ANY(v_pay_batch_candidate_ids)
             )
             OR (
               v_scope_type = 'TRANSFER'
               AND public.pay_batch_items.pay_bank_transfer_id = ANY(v_pay_bank_transfer_ids)
             )
             OR (
               v_scope_type = 'UMBRELLA_PAYMENT_GROUP'
               AND (
                 public.pay_batch_items.umbrella_id = v_umbrella_id
                 OR public.pay_bank_transfers.umbrella_id = v_umbrella_id
                 OR (
                   upper(coalesce(public.pay_bank_transfers.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY')
                   AND public.pay_bank_transfers.payee_entity_id = v_umbrella_id
                 )
               )
               AND (
                 v_transfer_group_key IS NULL
                 OR public.pay_bank_transfers.transfer_group_key = v_transfer_group_key
               )
             )
           )
       )
       SELECT 1
       FROM unnest(v_expected_pay_batch_item_ids) AS expected_item_ids(expected_pay_batch_item_id)
       LEFT JOIN base_scope_items
         ON base_scope_items.selected_pay_batch_item_id = expected_item_ids.expected_pay_batch_item_id
       WHERE base_scope_items.selected_pay_batch_item_id IS NULL
     ) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_ITEM_SELECTION_OUT_OF_SCOPE',
              'pay_batch_id', p_pay_batch_id,
              'scope_type', v_scope_type,
              'expected_pay_batch_item_ids', to_jsonb(v_expected_pay_batch_item_ids),
              'reason', 'One or more expected_pay_batch_item_ids are outside the base correction scope.'
            )::text;
  END IF;

  v_return_item_count := COALESCE(array_length(v_return_item_ids, 1), 0);

  IF v_expected_item_count IS NOT NULL
     AND v_return_item_count IS DISTINCT FROM v_expected_item_count THEN
    RAISE EXCEPTION 'WORK_SELECTION_DRIFT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'WORK_SELECTION_DRIFT',
              'pay_batch_id', p_pay_batch_id,
              'scope_type', v_scope_type,
              'expected_item_count', v_expected_item_count,
              'resolved_item_count', v_return_item_count,
              'reason', 'Resolved correction item count no longer matches the expected work-item count.'
            )::text;
  END IF;

  IF COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0) > 0 THEN
    SELECT
      COALESCE(array_agg(DISTINCT returned_item_ids.returned_pay_batch_item_id ORDER BY returned_item_ids.returned_pay_batch_item_id), ARRAY[]::uuid[])
    INTO v_sorted_return_item_ids
    FROM unnest(v_return_item_ids) AS returned_item_ids(returned_pay_batch_item_id);

    SELECT
      COALESCE(array_agg(DISTINCT expected_item_ids.expected_pay_batch_item_id ORDER BY expected_item_ids.expected_pay_batch_item_id), ARRAY[]::uuid[])
    INTO v_sorted_expected_pay_batch_item_ids
    FROM unnest(v_expected_pay_batch_item_ids) AS expected_item_ids(expected_pay_batch_item_id);

    IF v_sorted_return_item_ids IS DISTINCT FROM v_sorted_expected_pay_batch_item_ids THEN
      RAISE EXCEPTION 'WORK_SELECTION_DRIFT'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'WORK_SELECTION_DRIFT',
                'pay_batch_id', p_pay_batch_id,
                'scope_type', v_scope_type,
                'expected_pay_batch_item_ids', to_jsonb(v_sorted_expected_pay_batch_item_ids),
                'resolved_pay_batch_item_ids', to_jsonb(v_sorted_return_item_ids),
                'reason', 'Resolved correction item ids no longer exactly match the expected work-item ids.'
              )::text;
    END IF;
  END IF;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_CORRECTION_SELECTED_ITEMS_RESOLVED_SCOPE',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope_type', v_scope_type,
      'include_already_corrected', COALESCE(p_include_already_corrected, false),
      'pay_batch_candidate_id_count', COALESCE(array_length(v_pay_batch_candidate_ids, 1), 0),
      'pay_bank_transfer_id_count', COALESCE(array_length(v_pay_bank_transfer_ids, 1), 0),
      'pay_batch_item_id_count', COALESCE(array_length(v_pay_batch_item_ids, 1), 0),
      'expected_pay_batch_item_id_count', COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0),
      'finance_case_id_count', COALESCE(array_length(v_finance_case_ids, 1), 0),
      'finance_component_id_count', COALESCE(array_length(v_finance_component_ids, 1), 0),
      'reservation_id_count', COALESCE(array_length(v_reservation_ids, 1), 0),
      'item_type_count', COALESCE(array_length(v_item_types, 1), 0),
      'umbrella_id', v_umbrella_id,
      'transfer_group_key', v_transfer_group_key,
      'expected_item_count', v_expected_item_count,
      'work_unit', v_work_unit,
      'source_correction_request_id_present', v_source_correction_request_id_text IS NOT NULL,
      'explicit_item_ids_authoritative', COALESCE(v_explicit_item_ids_authoritative, false),
      'selected_item_count', v_selected_item_count,
      'selected_already_corrected_count', v_selected_already_corrected_count,
      'return_item_count', v_return_item_count
    ),
    'pay_payment_correction',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF v_return_item_count = 0 THEN
    RETURN;
  END IF;

  WITH requested_item_ids AS (
    SELECT unnest(v_return_item_ids) AS requested_pay_batch_item_id
  ),
  economic_components AS (
    SELECT
      economic_component_rows.pay_batch_item_id AS economic_pay_batch_item_id,
      economic_component_rows.key_resolution_failure_reason AS economic_key_resolution_failure_reason
    FROM public._pay_batch_item_economic_components(NULL::uuid, v_return_item_ids) AS economic_component_rows
  )
  SELECT
    (count(*) FILTER (
      WHERE economic_components.economic_pay_batch_item_id IS NULL
         OR economic_components.economic_key_resolution_failure_reason IS NOT NULL
    ))::integer
  INTO v_key_resolution_failure_count
  FROM requested_item_ids
  LEFT JOIN economic_components
    ON economic_components.economic_pay_batch_item_id = requested_item_ids.requested_pay_batch_item_id;

  RETURN QUERY
  WITH applied_correction_rows AS (
    SELECT
      public.pay_payment_correction_items.pay_batch_item_id AS correction_pay_batch_item_id,
      public.pay_payment_correction_items.correction_item_kind AS correction_item_kind
    FROM public.pay_payment_correction_items
    WHERE public.pay_payment_correction_items.pay_batch_id = p_pay_batch_id
      AND public.pay_payment_correction_items.pay_batch_item_id IS NOT NULL
      AND public.pay_payment_correction_items.status = 'APPLIED'
  ),
  applied_corrections AS (
    SELECT
      applied_correction_rows.correction_pay_batch_item_id AS correction_pay_batch_item_id,
      array_agg(DISTINCT applied_correction_rows.correction_item_kind ORDER BY applied_correction_rows.correction_item_kind) AS applied_correction_kinds
    FROM applied_correction_rows
    GROUP BY applied_correction_rows.correction_pay_batch_item_id
  ),
  economic_components AS (
    SELECT
      economic_component_rows.pay_batch_id AS economic_pay_batch_id,
      economic_component_rows.pay_batch_item_id AS economic_pay_batch_item_id,
      economic_component_rows.timesheet_id AS economic_timesheet_id,
      economic_component_rows.item_type AS economic_item_type,
      economic_component_rows.key_type AS economic_key_type,
      economic_component_rows.key_value AS economic_key_value,
      economic_component_rows.source_amount_ex_vat AS economic_source_amount_ex_vat,
      economic_component_rows.source_amount_inc_vat AS economic_source_amount_inc_vat,
      economic_component_rows.target_amount_ex_vat AS economic_target_amount_ex_vat,
      economic_component_rows.key_resolution_source AS economic_key_resolution_source,
      economic_component_rows.key_resolution_failure_reason AS economic_key_resolution_failure_reason
    FROM public._pay_batch_item_economic_components(NULL::uuid, v_return_item_ids) AS economic_component_rows
  ),
  selected_batch_rows AS (
    SELECT
      public.pay_batch_candidates.pay_batch_id AS selected_pay_batch_id,
      public.pay_batch_candidates.id AS selected_pay_batch_candidate_id,
      public.pay_batch_candidates.candidate_id AS selected_candidate_id,
      COALESCE(
        NULLIF(btrim(public.pay_batch_candidates.candidate_display_name), ''),
        NULLIF(btrim(public.candidates.display_name), ''),
        NULLIF(btrim(concat_ws(' ', public.candidates.first_name, public.candidates.last_name)), ''),
        NULLIF(btrim(public.candidates.tms_ref), ''),
        public.pay_batch_candidates.candidate_id::text
      ) AS selected_candidate_display_name,
      COALESCE(
        NULLIF(btrim(public.pay_batch_candidates.candidate_tms_ref), ''),
        NULLIF(btrim(public.candidates.tms_ref), '')
      ) AS selected_candidate_tms_ref,
      public.pay_batch_items.id AS selected_pay_batch_item_id,
      public.pay_batch_items.item_type AS selected_item_type,
      public.pay_batch_items.timesheet_id AS selected_timesheet_id,
      public.pay_batch_items.pay_bank_transfer_id AS selected_pay_bank_transfer_id,
      public.pay_bank_transfers.status AS selected_transfer_status,
      public.pay_bank_transfers.amount AS selected_transfer_amount,
      public.pay_bank_transfers.transfer_group_key AS selected_transfer_group_key,
      public.pay_bank_transfers.payee_entity_kind AS selected_payee_entity_kind,
      public.pay_bank_transfers.payee_entity_id AS selected_payee_entity_id,
      COALESCE(
        public.pay_batch_items.umbrella_id,
        public.pay_bank_transfers.umbrella_id,
        CASE
          WHEN upper(coalesce(public.pay_bank_transfers.payee_entity_kind, '')) IN ('UMBRELLA', 'UMBRELLA_COMPANY')
            THEN public.pay_bank_transfers.payee_entity_id
          ELSE NULL::uuid
        END
      ) AS selected_umbrella_id,
      public.pay_batch_items.finance_case_id AS selected_finance_case_id,
      public.pay_batch_items.finance_component_id AS selected_finance_component_id,
      public.pay_batch_items.reservation_id AS selected_reservation_id,
      public.pay_batch_items.pay_channel AS selected_pay_channel,
      public.pay_batch_items.frozen_source_pay_method AS selected_frozen_source_pay_method,
      public.pay_batch_items.frozen_target_pay_method AS selected_frozen_target_pay_method,
      public.candidates.pay_method AS selected_current_candidate_pay_method,
      public.pay_batch_items.amount_ex_vat AS selected_amount_ex_vat,
      public.pay_batch_items.amount_vat AS selected_amount_vat,
      public.pay_batch_items.amount_inc_vat AS selected_amount_inc_vat,
      public.pay_batch_items.is_voided AS selected_is_voided,
      COALESCE(applied_corrections.applied_correction_kinds, ARRAY[]::text[]) AS selected_applied_correction_kinds
    FROM public.pay_batch_items
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.id = public.pay_batch_items.pay_batch_candidate_id
    JOIN public.candidates
      ON public.candidates.id = public.pay_batch_candidates.candidate_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN applied_corrections
      ON applied_corrections.correction_pay_batch_item_id = public.pay_batch_items.id
    WHERE public.pay_batch_candidates.pay_batch_id = p_pay_batch_id
      AND public.pay_batch_items.id = ANY(v_return_item_ids)
  )
  SELECT
    selected_batch_rows.selected_pay_batch_id AS pay_batch_id,
    selected_batch_rows.selected_pay_batch_candidate_id AS pay_batch_candidate_id,
    selected_batch_rows.selected_candidate_id AS candidate_id,
    selected_batch_rows.selected_candidate_display_name AS candidate_display_name,
    selected_batch_rows.selected_candidate_tms_ref AS candidate_tms_ref,
    selected_batch_rows.selected_pay_batch_item_id AS pay_batch_item_id,
    selected_batch_rows.selected_item_type AS item_type,
    selected_batch_rows.selected_timesheet_id AS timesheet_id,
    selected_batch_rows.selected_pay_bank_transfer_id AS pay_bank_transfer_id,
    selected_batch_rows.selected_transfer_status AS transfer_status,
    selected_batch_rows.selected_transfer_amount AS transfer_amount,
    selected_batch_rows.selected_transfer_group_key AS transfer_group_key,
    selected_batch_rows.selected_payee_entity_kind AS payee_entity_kind,
    selected_batch_rows.selected_payee_entity_id AS payee_entity_id,
    selected_batch_rows.selected_umbrella_id AS umbrella_id,
    public.umbrellas.name AS umbrella_name,
    selected_batch_rows.selected_finance_case_id AS finance_case_id,
    selected_batch_rows.selected_finance_component_id AS finance_component_id,
    selected_batch_rows.selected_reservation_id AS reservation_id,
    selected_batch_rows.selected_pay_channel AS pay_channel,
    selected_batch_rows.selected_frozen_source_pay_method AS frozen_source_pay_method,
    selected_batch_rows.selected_frozen_target_pay_method AS frozen_target_pay_method,
    selected_batch_rows.selected_current_candidate_pay_method AS current_candidate_pay_method,
    economic_components.economic_key_type AS economic_key_type,
    economic_components.economic_key_value AS economic_key_value,
    economic_components.economic_source_amount_ex_vat AS source_amount_ex_vat,
    economic_components.economic_target_amount_ex_vat AS target_amount_ex_vat,
    COALESCE(economic_components.economic_key_resolution_source, 'KEY_RESOLUTION_FAILED') AS key_resolution_source,
    CASE
      WHEN economic_components.economic_pay_batch_item_id IS NULL THEN 'ECONOMIC_COMPONENT_ROW_NOT_RETURNED'
      ELSE economic_components.economic_key_resolution_failure_reason
    END AS key_resolution_failure_reason,
    selected_batch_rows.selected_amount_ex_vat AS amount_ex_vat,
    selected_batch_rows.selected_amount_vat AS amount_vat,
    economic_components.economic_source_amount_inc_vat AS amount_inc_vat,
    selected_batch_rows.selected_is_voided AS is_voided,
    COALESCE(array_length(selected_batch_rows.selected_applied_correction_kinds, 1), 0) > 0 AS already_corrected,
    selected_batch_rows.selected_applied_correction_kinds AS applied_correction_kinds
  FROM selected_batch_rows
  LEFT JOIN economic_components
    ON economic_components.economic_pay_batch_item_id = selected_batch_rows.selected_pay_batch_item_id
  LEFT JOIN public.umbrellas
    ON public.umbrellas.id = selected_batch_rows.selected_umbrella_id
  ORDER BY
    selected_batch_rows.selected_candidate_display_name,
    selected_batch_rows.selected_transfer_group_key NULLS LAST,
    selected_batch_rows.selected_pay_bank_transfer_id NULLS LAST,
    selected_batch_rows.selected_pay_batch_item_id;

  GET DIAGNOSTICS v_returned_count = ROW_COUNT;

  PERFORM public._imp_debug_audit(
    NULL::uuid,
    'PAYMENT_CORRECTION_SELECTED_ITEMS_RETURNED',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope_type', v_scope_type,
      'include_already_corrected', COALESCE(p_include_already_corrected, false),
      'selected_item_count', v_selected_item_count,
      'selected_already_corrected_count', v_selected_already_corrected_count,
      'return_item_count', v_return_item_count,
      'returned_row_count', v_returned_count,
      'key_resolution_failure_count', v_key_resolution_failure_count,
      'expected_item_count', v_expected_item_count,
      'expected_pay_batch_item_id_count', COALESCE(array_length(v_expected_pay_batch_item_ids, 1), 0),
      'work_unit', v_work_unit,
      'source_correction_request_id_present', v_source_correction_request_id_text IS NOT NULL,
      'explicit_item_ids_authoritative', COALESCE(v_explicit_item_ids_authoritative, false)
    ),
    'pay_payment_correction',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN;

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      NULL::uuid,
      'PAYMENT_CORRECTION_SELECTED_ITEMS_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope_type', v_scope_type,
        'include_already_corrected', COALESCE(p_include_already_corrected, false),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM,
        'selection_json', p_selection_json
      ),
      'pay_payment_correction',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;




CREATE OR REPLACE FUNCTION public._pay_payment_movement_classify(
  p_pay_batch_id uuid,
  p_selection_json jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_selection_json jsonb := COALESCE(p_selection_json, '{}'::jsonb);
  v_diagnostic_json jsonb := '{}'::jsonb;
  v_lifecycle text := NULL::text;
  v_recommended_action text := NULL::text;
  v_classification text := NULL::text;
  v_blockers jsonb := '[]'::jsonb;
  v_manual_result jsonb := '{}'::jsonb;
  v_safe_to_auto_apply boolean := false;
BEGIN
  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR jsonb_typeof(p_selection_json) <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001', DETAIL = jsonb_build_object('code', 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT', 'pay_batch_id', p_pay_batch_id)::text;
  END IF;

  v_diagnostic_json := public.pay_payment_cancelability_diagnostic(p_pay_batch_id, v_selection_json, NULL::uuid);
  v_lifecycle := NULLIF(btrim(COALESCE(v_diagnostic_json->>'payment_lifecycle_state', '')), '');
  v_recommended_action := NULLIF(btrim(COALESCE(v_diagnostic_json->>'recommended_action', '')), '');
  v_manual_result := jsonb_build_object(
    'manual_adjustment_carry_forward_required', COALESCE(NULLIF(v_diagnostic_json->>'manual_adjustment_carry_forward_required', '')::boolean, false),
    'manual_adjustments_to_carry_forward', COALESCE(v_diagnostic_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_diagnostic_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'can_carry_forward_automatically', COALESCE(NULLIF(v_diagnostic_json->>'can_carry_forward_automatically', '')::boolean, true),
    'carry_forward_blockers', COALESCE(v_diagnostic_json->'carry_forward_blockers', '[]'::jsonb),
    'manual_adjustment_support_details_json', COALESCE(v_diagnostic_json->'manual_adjustment_support_details_json', '{}'::jsonb)
  );

  v_blockers := COALESCE(v_diagnostic_json->'blockers', '[]'::jsonb);

  IF v_lifecycle = 'PAID_OR_SETTLED' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'NO_MONEY_UNWIND_HAS_SETTLEMENT_EVIDENCE',
      'message', 'Payment has paid/settled evidence; use overpayment recovery instead of no-money unwind.',
      'required_action', 'AMEND_AND_RECOVER_OVERPAYMENT'
    ));
  END IF;

  IF v_lifecycle = 'PROVIDER_OUTCOME_UNKNOWN' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER',
      'message', 'Provider outcome is unknown; check provider before retry or unwind.',
      'required_action', 'CHECK_PROVIDER_STATUS'
    ));
  END IF;

  IF v_lifecycle = 'PROVIDER_SUBMITTED_PENDING' THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'PROVIDER_CANCELLATION_REQUIRED_BEFORE_UNWIND',
      'message', 'Provider submission is pending; provider state must be checked before unwind.',
      'required_action', 'CHECK_PROVIDER_STATUS'
    ));
  END IF;

  IF COALESCE(NULLIF(v_diagnostic_json#>>'{manual_adjustment_support_details_json,source_less_ambiguous_count}', '')::integer, 0) > 0
     OR COALESCE(jsonb_array_length(COALESCE(v_diagnostic_json->'carry_forward_blockers', '[]'::jsonb)), 0) > 0 THEN
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'SOURCE_LESS_MANUAL_ADJUSTMENT_AMBIGUOUS',
      'message', 'One or more source-less manual adjustments could not be carried forward automatically.',
      'carry_forward_blockers', COALESCE(v_diagnostic_json->'carry_forward_blockers', '[]'::jsonb)
    ));
  END IF;

  v_classification := CASE
    WHEN v_lifecycle = 'LOCAL_PREPARED_NOT_SENT' THEN 'LOCAL_PREPARED_NOT_SENT'
    WHEN v_lifecycle = 'SCHEDULED_LOCAL_NOT_SENT' THEN 'SCHEDULED_LOCAL_NOT_SENT'
    WHEN v_lifecycle = 'PROVIDER_SUBMITTED_PENDING' THEN 'PROVIDER_SUBMITTED_PENDING'
    WHEN v_lifecycle = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'PROVIDER_OUTAGE_RETRY_LATER'
    WHEN v_lifecycle = 'PROVIDER_OUTCOME_UNKNOWN' THEN 'PROVIDER_OUTCOME_UNKNOWN'
    WHEN v_lifecycle = 'PROVIDER_CANCELLED_NO_MONEY' THEN 'PROVIDER_CANCELLED_NO_MONEY'
    WHEN v_lifecycle = 'PROVIDER_FAILED_NO_MONEY' THEN 'PROVIDER_FAILED_NO_MONEY'
    WHEN v_lifecycle = 'PAID_OR_SETTLED' THEN 'PAID_OR_SETTLED'
    WHEN v_lifecycle = 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'CANCELLED_BEFORE_BANK_SUBMISSION'
    WHEN v_lifecycle = 'FINANCIALS_REWOUND' THEN 'FINANCIALS_REWOUND'
    ELSE 'PROVIDER_OUTCOME_UNKNOWN'
  END;

  v_safe_to_auto_apply := v_recommended_action IN ('PRE_PROVIDER_CANCEL_AND_RECALCULATE', 'NO_MONEY_UNWIND_AND_RECALCULATE')
    AND COALESCE(jsonb_array_length(COALESCE(v_blockers, '[]'::jsonb)), 0) = 0;

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id::text,
    'classification', v_classification,
    'payment_lifecycle_state', v_lifecycle,
    'recommended_action', v_recommended_action,
    'safe_to_auto_apply', v_safe_to_auto_apply,
    'can_pre_provider_cancel', COALESCE(NULLIF(v_diagnostic_json->>'can_pre_provider_cancel', '')::boolean, false),
    'can_no_money_unwind', COALESCE(NULLIF(v_diagnostic_json->>'can_no_money_unwind', '')::boolean, false),
    'can_recover_overpayment', COALESCE(NULLIF(v_diagnostic_json->>'can_recover_overpayment', '')::boolean, false),
    'requires_provider_cancel', COALESCE(NULLIF(v_diagnostic_json->>'requires_provider_cancel', '')::boolean, false),
    'requires_bank_check', COALESCE(NULLIF(v_diagnostic_json->>'requires_bank_check', '')::boolean, false),
    'requires_retry_later', COALESCE(NULLIF(v_diagnostic_json->>'requires_retry_later', '')::boolean, false),
    'blockers', COALESCE(v_blockers, '[]'::jsonb),
    'reasons', COALESCE(v_diagnostic_json->'warnings', '[]'::jsonb),
    'evidence', jsonb_build_object(
      'blocking_paid_evidence_json', COALESCE(v_diagnostic_json->'blocking_paid_evidence_json', '{}'::jsonb),
      'terminal_no_money_evidence_json', COALESCE(v_diagnostic_json->'terminal_no_money_evidence_json', '{}'::jsonb),
      'pending_provider_evidence_json', COALESCE(v_diagnostic_json->'pending_provider_evidence_json', '{}'::jsonb),
      'provider_evidence', COALESCE(v_diagnostic_json#>'{support_details_json,provider_evidence}', '{}'::jsonb)
    ),
    'manual_adjustment_carry_forward', v_manual_result,
    'resolved_full_payment_scope_json', COALESCE(v_diagnostic_json->'resolved_full_payment_scope_json', '{}'::jsonb),
    'finance_scope_json', COALESCE(v_diagnostic_json->'finance_scope_json', '{}'::jsonb),
    'diagnostic_payload', v_diagnostic_json,
    'policy_x_checked', true
  );
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_payment_correction_request_start(p_pay_batch_id uuid, p_selection_json jsonb, p_reason text, p_actor_user_id uuid, p_source_bank_event_id uuid DEFAULT NULL::uuid, p_auto_requested boolean DEFAULT false, p_accepted_resolution_json jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_exists boolean := false;
  v_actor_exists boolean := false;
  v_actor_active boolean := false;
  v_source_event_exists boolean := false;
  v_source_event_source text;
  v_source_event_mapping_status text;
  v_source_event_mapping_method text;
  v_source_event_transport text;
  v_source_event_signature_valid boolean := NULL::boolean;
  v_source_event_webhook_receipt_id uuid := NULL::uuid;
  v_source_event_provider_event_type text := NULL::text;
  v_source_event_provider_event_id text := NULL::text;
  v_source_event_provider_transaction_id text := NULL::text;
  v_source_event_provider_request_id text := NULL::text;
  v_source_event_provider_event_key text := NULL::text;
  v_source_event_failure_reason_group text := NULL::text;
  v_source_event_failure_reason_code text := NULL::text;
  v_plan jsonb := '{}'::jsonb;
  v_classification text := 'AMBIGUOUS_REVIEW_REQUIRED';
  v_plan_can_apply boolean := false;
  v_hard_blockers jsonb := '[]'::jsonb;
  v_effective_hard_blockers jsonb := '[]'::jsonb;
  v_suggested_resolution_required boolean := false;
  v_accepted_resolution_supplied boolean := false;
  v_accepted_resolution_is_stale boolean := false;
  v_safe_to_auto_apply boolean := false;
  v_ambiguous_mapping_count integer := 0;
  v_amount_mismatch_count integer := 0;
  v_aggregate_subset_issue_count integer := 0;
  v_correction_kind text;
  v_status text;
  v_required_quantity integer := 1;
  v_approved_count integer := 0;
  v_selection_hash text;
  v_plan_material_json jsonb;
  v_plan_hash text;
  v_accepted_resolution_hash text;
  v_finance_resolution_validation jsonb := NULL::jsonb;
  v_finance_resolution_blocker jsonb := NULL::jsonb;
  v_selected_scope_json jsonb := '{}'::jsonb;
  v_request public.pay_payment_correction_requests%rowtype;
  v_existing_request public.pay_payment_correction_requests%rowtype;
  v_draft_removal_requested boolean := false;
  v_draft_removal_auto_authorised boolean := false;
  v_selected_item_count integer := 0;
  v_expected_item_count integer := NULL::integer;
  v_expected_item_mismatch_count integer := 0;
  v_expected_item_id_count integer := 0;
  v_batch_pre_bank_safe boolean := false;
  v_bank_submission_evidence_count integer := 0;
  v_recommended_action text := NULL::text;
  v_requested_action_upper text := NULL::text;
  v_enriched_accepted_resolution_json jsonb := NULL::jsonb;
BEGIN
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_REQUEST_START_BEGIN',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'scope_type', CASE WHEN p_selection_json IS NULL THEN NULL ELSE p_selection_json->>'scope_type' END,
      'actor_user_id', p_actor_user_id,
      'source_bank_event_id', p_source_bank_event_id,
      'auto_requested', COALESCE(p_auto_requested, false),
      'accepted_resolution_supplied', p_accepted_resolution_json IS NOT NULL
    ),
    'pay_payment_correction',
    COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.pay_batches AS batch_check
    WHERE batch_check.id = p_pay_batch_id
  )
  INTO v_batch_exists;

  IF NOT COALESCE(v_batch_exists, false) THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  IF COALESCE(p_auto_requested, false) = false THEN
    IF p_actor_user_id IS NULL THEN
      RAISE EXCEPTION 'ACTOR_USER_ID_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'ACTOR_USER_ID_REQUIRED',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;

    SELECT
      true,
      COALESCE(public.tms_users.is_active, false)
    INTO
      v_actor_exists,
      v_actor_active
    FROM public.tms_users
    WHERE public.tms_users.id = p_actor_user_id;

    IF NOT COALESCE(v_actor_exists, false) THEN
      RAISE EXCEPTION 'ACTOR_USER_NOT_FOUND'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'ACTOR_USER_NOT_FOUND',
                'actor_user_id', p_actor_user_id
              )::text;
    END IF;

    IF NOT COALESCE(v_actor_active, false) THEN
      RAISE EXCEPTION 'ACTOR_USER_INACTIVE'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'ACTOR_USER_INACTIVE',
                'actor_user_id', p_actor_user_id
              )::text;
    END IF;

    IF NULLIF(btrim(COALESCE(p_reason, '')), '') IS NULL THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_REASON_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CORRECTION_REASON_REQUIRED',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;
  END IF;

  IF COALESCE(p_auto_requested, false) = true THEN
    IF p_source_bank_event_id IS NULL THEN
      RAISE EXCEPTION 'SOURCE_BANK_EVENT_REQUIRED_FOR_AUTO_CORRECTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SOURCE_BANK_EVENT_REQUIRED_FOR_AUTO_CORRECTION',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;
  END IF;

  IF p_source_bank_event_id IS NOT NULL THEN
    SELECT
      true,
      public.pay_bank_transfer_events.event_source,
      public.pay_bank_transfer_events.mapping_status,
      public.pay_bank_transfer_events.mapping_method,
      public.pay_bank_transfer_events.provider_event_transport,
      public.pay_bank_transfer_events.provider_signature_valid,
      public.pay_bank_transfer_events.provider_webhook_receipt_id,
      public.pay_bank_transfer_events.provider_event_type,
      public.pay_bank_transfer_events.provider_event_id,
      public.pay_bank_transfer_events.provider_transaction_id,
      public.pay_bank_transfer_events.provider_request_id,
      public.pay_bank_transfer_events.provider_event_key,
      public.pay_bank_transfer_events.provider_failure_reason_group,
      public.pay_bank_transfer_events.provider_failure_reason_code
    INTO
      v_source_event_exists,
      v_source_event_source,
      v_source_event_mapping_status,
      v_source_event_mapping_method,
      v_source_event_transport,
      v_source_event_signature_valid,
      v_source_event_webhook_receipt_id,
      v_source_event_provider_event_type,
      v_source_event_provider_event_id,
      v_source_event_provider_transaction_id,
      v_source_event_provider_request_id,
      v_source_event_provider_event_key,
      v_source_event_failure_reason_group,
      v_source_event_failure_reason_code
    FROM public.pay_bank_transfer_events
    WHERE public.pay_bank_transfer_events.id = p_source_bank_event_id
      AND public.pay_bank_transfer_events.pay_batch_id = p_pay_batch_id;

    IF NOT COALESCE(v_source_event_exists, false) THEN
      RAISE EXCEPTION 'SOURCE_BANK_EVENT_NOT_FOUND_FOR_BATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'SOURCE_BANK_EVENT_NOT_FOUND_FOR_BATCH',
                'pay_batch_id', p_pay_batch_id,
                'source_bank_event_id', p_source_bank_event_id
              )::text;
    END IF;
  END IF;

  IF p_accepted_resolution_json IS NOT NULL
     AND COALESCE(jsonb_typeof(p_accepted_resolution_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'ACCEPTED_RESOLUTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACCEPTED_RESOLUTION_JSON_MUST_BE_OBJECT',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_requested_action_upper := upper(btrim(COALESCE(
    p_selection_json->>'requested_action',
    p_selection_json->>'correction_kind',
    p_selection_json->>'correction_action',
    p_accepted_resolution_json->>'requested_action',
    p_accepted_resolution_json->>'correction_kind',
    ''
  )));

  IF v_requested_action_upper IN ('TRUE_SETTLED_REVERSAL_REQUIRED', 'SETTLED_REVERSAL', 'MANUAL_EVIDENCE_SETTLED_RETURN') THEN
    RAISE EXCEPTION 'PAID_SETTLED_RECOVERY_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAID_SETTLED_RECOVERY_REQUIRED',
              'message', 'Paid/settled payment states must be handled through amendment and recovery, not settled reversal correction requests.',
              'pay_batch_id', p_pay_batch_id,
              'requested_action', v_requested_action_upper
            )::text;
  END IF;

  v_plan := public.pay_payment_correction_plan(
    p_pay_batch_id,
    p_selection_json,
    p_actor_user_id
  );

  v_classification := COALESCE(
    NULLIF(btrim(v_plan->>'payment_lifecycle_state'), ''),
    NULLIF(btrim(v_plan->>'classification'), ''),
    'AMBIGUOUS_REVIEW_REQUIRED'
  );
  v_recommended_action := COALESCE(NULLIF(btrim(v_plan->>'recommended_action'), ''), NULLIF(btrim(v_plan->>'user_facing_recommended_action'), ''));
  v_plan_can_apply := COALESCE((v_plan->>'can_apply')::boolean, false);
  v_hard_blockers := COALESCE(v_plan->'hard_blockers', '[]'::jsonb);
  IF jsonb_array_length(COALESCE(v_plan->'carry_forward_blockers', '[]'::jsonb)) > 0 THEN
    v_hard_blockers := v_hard_blockers || COALESCE(v_plan->'carry_forward_blockers', '[]'::jsonb);
  END IF;
  v_suggested_resolution_required := COALESCE((v_plan->>'suggested_resolution_required')::boolean, false);
  v_accepted_resolution_supplied := p_accepted_resolution_json IS NOT NULL;
  v_safe_to_auto_apply := COALESCE((v_plan#>>'{movement_classification_detail,safe_to_auto_apply}')::boolean, false);
  v_ambiguous_mapping_count := COALESCE((v_plan#>>'{movement_classification_detail,counts,bank_event_ambiguous_mapping_count}')::integer, 0);
  v_amount_mismatch_count := COALESCE((v_plan#>>'{movement_classification_detail,counts,bank_event_amount_mismatch_count}')::integer, 0);
  v_aggregate_subset_issue_count := COALESCE((v_plan#>>'{movement_classification_detail,counts,aggregate_subset_issue_count}')::integer, 0);

  v_accepted_resolution_is_stale := p_accepted_resolution_json IS NOT NULL
    AND (
      lower(COALESCE(p_accepted_resolution_json->>'is_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(p_accepted_resolution_json->>'stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(p_accepted_resolution_json->>'resolution_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(p_accepted_resolution_json#>>'{validation,is_stale}', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(p_accepted_resolution_json#>>'{validation,stale}', 'false')) IN ('true', 't', 'yes', 'y', '1')
    );

  v_draft_removal_requested := COALESCE(NULLIF(btrim(p_selection_json->>'source_context'), ''), '') = 'DRAFT_REMOVE_FROM_BATCH'
    AND COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), '') = 'CANCEL_PAYMENT_ATTEMPT';

  SELECT COALESCE(jsonb_agg(blocker_elements.blocker_value ORDER BY blocker_elements.blocker_ordinal), '[]'::jsonb)
  INTO v_effective_hard_blockers
  FROM jsonb_array_elements(v_hard_blockers) WITH ORDINALITY AS blocker_elements(blocker_value, blocker_ordinal)
  WHERE NOT (
    v_suggested_resolution_required
    AND (
      v_accepted_resolution_supplied
      OR (v_draft_removal_requested AND v_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE')
    )
    AND COALESCE(blocker_elements.blocker_value->>'code', '') = 'SUGGESTED_RESOLUTION_REQUIRED'
  );

  IF v_accepted_resolution_is_stale THEN
    v_effective_hard_blockers := v_effective_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'ACCEPTED_RESOLUTION_STALE',
      'message', 'The accepted suggested finance resolution is stale and must be regenerated before correction request start.'
    ));
  END IF;

  IF v_draft_removal_requested
     AND v_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
     AND v_suggested_resolution_required THEN
    v_suggested_resolution_required := false;
    v_hard_blockers := v_effective_hard_blockers;
    v_plan := v_plan || jsonb_build_object(
      'suggested_resolution_required', false,
      'suggested_resolution', NULL::jsonb,
      'hard_blockers', v_effective_hard_blockers
    );

    IF NOT COALESCE(v_plan_can_apply, false)
       AND jsonb_array_length(v_effective_hard_blockers) = 0 THEN
      v_plan_can_apply := true;
      v_plan := v_plan || jsonb_build_object('can_apply', true);
    END IF;
  END IF;

  IF v_suggested_resolution_required AND v_accepted_resolution_supplied THEN
    v_finance_resolution_validation := public._pay_payment_correction_validate_accepted_finance_resolution(
      p_pay_batch_id => p_pay_batch_id,
      p_selection_json => p_selection_json,
      p_plan_json => v_plan,
      p_accepted_resolution_json => p_accepted_resolution_json,
      p_actor_user_id => p_actor_user_id
    );

    IF NOT COALESCE((v_finance_resolution_validation->>'ok')::boolean, false)
       OR NOT COALESCE((v_finance_resolution_validation->>'validated')::boolean, false) THEN
      v_finance_resolution_blocker := COALESCE(
        v_finance_resolution_validation->'blocker',
        jsonb_build_object(
          'code', 'ACCEPTED_RESOLUTION_VALIDATION_FAILED',
          'message', 'Accepted finance resolution validation failed before correction request start.'
        )
      );

      v_effective_hard_blockers := v_effective_hard_blockers || jsonb_build_array(v_finance_resolution_blocker);
    END IF;
  END IF;

  IF v_classification = 'AMBIGUOUS_REVIEW_REQUIRED' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_CLASSIFICATION_AMBIGUOUS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_CLASSIFICATION_AMBIGUOUS',
              'pay_batch_id', p_pay_batch_id,
              'classification', v_classification,
              'recommended_action', v_recommended_action,
              'blockers', v_effective_hard_blockers
            )::text;
  END IF;

  IF v_suggested_resolution_required AND NOT v_accepted_resolution_supplied THEN
    RAISE EXCEPTION 'SUGGESTED_RESOLUTION_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'SUGGESTED_RESOLUTION_REQUIRED',
              'pay_batch_id', p_pay_batch_id,
              'suggested_resolution', v_plan->'suggested_resolution'
            )::text;
  END IF;

  IF jsonb_array_length(v_effective_hard_blockers) > 0 THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PLAN_HAS_BLOCKERS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_PLAN_HAS_BLOCKERS',
              'pay_batch_id', p_pay_batch_id,
              'blockers', v_effective_hard_blockers
            )::text;
  END IF;

  IF COALESCE(v_recommended_action, '') IN ('CHECK_PROVIDER_STATUS', 'RETRY_PROVIDER_LATER', 'AMEND_AND_RECOVER_OVERPAYMENT')
     OR v_classification IN ('PROVIDER_SUBMITTED_PENDING', 'PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_OUTAGE_RETRY_LATER', 'PAID_OR_SETTLED') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ACTION_NOT_ALLOWED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', CASE
                WHEN COALESCE(v_recommended_action, '') = 'AMEND_AND_RECOVER_OVERPAYMENT' OR v_classification = 'PAID_OR_SETTLED' THEN 'PAID_SETTLED_RECOVERY_REQUIRED'
                WHEN COALESCE(v_recommended_action, '') = 'CHECK_PROVIDER_STATUS' OR v_classification IN ('PROVIDER_SUBMITTED_PENDING', 'PROVIDER_OUTCOME_UNKNOWN') THEN 'PAYMENT_OUTCOME_UNKNOWN_CHECK_PROVIDER'
                WHEN COALESCE(v_recommended_action, '') = 'RETRY_PROVIDER_LATER' OR v_classification = 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'RETRY_PROVIDER_LATER'
                ELSE 'PAYMENT_CORRECTION_REQUEST_ACTION_NOT_ALLOWED'
              END,
              'pay_batch_id', p_pay_batch_id,
              'payment_lifecycle_state', v_classification,
              'recommended_action', v_recommended_action,
              'blockers', v_effective_hard_blockers,
              'plan', v_plan
            )::text;
  END IF;

  IF NOT v_plan_can_apply
     AND NOT (v_suggested_resolution_required AND v_accepted_resolution_supplied AND jsonb_array_length(v_effective_hard_blockers) = 0) THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_PLAN_CANNOT_APPLY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_PLAN_CANNOT_APPLY',
              'pay_batch_id', p_pay_batch_id,
              'classification', v_classification,
              'can_apply', v_plan_can_apply,
              'blockers', v_effective_hard_blockers
            )::text;
  END IF;

  IF COALESCE(p_auto_requested, false) THEN
    IF NOT v_safe_to_auto_apply THEN
      RAISE EXCEPTION 'AUTO_PAYMENT_CORRECTION_NOT_SAFE_TO_APPLY'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'AUTO_PAYMENT_CORRECTION_NOT_SAFE_TO_APPLY',
                'pay_batch_id', p_pay_batch_id,
                'classification', v_classification,
                'safe_to_auto_apply', v_safe_to_auto_apply,
                'blockers', v_effective_hard_blockers
              )::text;
    END IF;

    IF v_suggested_resolution_required THEN
      RAISE EXCEPTION 'AUTO_PAYMENT_CORRECTION_BLOCKED_BY_SUGGESTED_RESOLUTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'AUTO_PAYMENT_CORRECTION_BLOCKED_BY_SUGGESTED_RESOLUTION',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;

    IF COALESCE(upper(v_source_event_mapping_status), '') <> 'MATCHED'
       OR COALESCE(upper(v_source_event_mapping_method), '') NOT IN (
         'TRANSFER_ID',
         'PROVIDER_EVENT_ID',
         'PROVIDER_REFERENCE',
         'PROVIDER_TRANSACTION_ID',
         'RAIL_TX_ID'
       )
       OR COALESCE(upper(COALESCE(v_source_event_transport, v_source_event_source, '')), '') NOT IN (
         'PROVIDER_RESPONSE',
         'PROVIDER_POLL',
         'PROVIDER_WEBHOOK',
         'FAILED_WEBHOOK_REPLAY'
       )
       OR (
         COALESCE(upper(COALESCE(v_source_event_transport, v_source_event_source, '')), '') IN ('PROVIDER_WEBHOOK', 'FAILED_WEBHOOK_REPLAY')
         AND (
           COALESCE(v_source_event_signature_valid, false) IS NOT TRUE
           OR v_source_event_webhook_receipt_id IS NULL
         )
       ) THEN
      RAISE EXCEPTION 'AUTO_PAYMENT_CORRECTION_REQUIRES_STRONG_BANK_EVENT_MAPPING'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'AUTO_PAYMENT_CORRECTION_REQUIRES_STRONG_BANK_EVENT_MAPPING',
                'pay_batch_id', p_pay_batch_id,
                'source_bank_event_id', p_source_bank_event_id,
                'mapping_status', v_source_event_mapping_status,
                'mapping_method', v_source_event_mapping_method,
                'provider_event_transport', v_source_event_transport,
                'event_source', v_source_event_source,
                'provider_signature_valid', v_source_event_signature_valid,
                'provider_webhook_receipt_id', CASE WHEN v_source_event_webhook_receipt_id IS NULL THEN NULL ELSE v_source_event_webhook_receipt_id::text END,
                'message', 'Automatic no-money correction requires verified provider evidence. Bare request IDs, payment references, and local/manual transfer selections are not sufficient.'
              )::text;
    END IF;

    IF v_ambiguous_mapping_count > 0 OR v_amount_mismatch_count > 0 OR v_aggregate_subset_issue_count > 0 THEN
      RAISE EXCEPTION 'AUTO_PAYMENT_CORRECTION_HAS_AMBIGUITY_OR_AMOUNT_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'AUTO_PAYMENT_CORRECTION_HAS_AMBIGUITY_OR_AMOUNT_MISMATCH',
                'pay_batch_id', p_pay_batch_id,
                'ambiguous_mapping_count', v_ambiguous_mapping_count,
                'amount_mismatch_count', v_amount_mismatch_count,
                'aggregate_subset_issue_count', v_aggregate_subset_issue_count
              )::text;
    END IF;
  END IF;

  v_correction_kind := CASE
    WHEN v_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN 'PRE_BANK_CANCEL'
    WHEN v_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE'
         AND COALESCE(upper(v_source_event_source), '') = 'MANUAL_EVIDENCE' THEN 'MANUAL_EVIDENCE_NO_MONEY'
    WHEN v_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE' THEN 'NO_MONEY_UNWIND'
    ELSE NULL
  END;

  IF v_correction_kind IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_KIND_COULD_NOT_BE_DETERMINED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_KIND_COULD_NOT_BE_DETERMINED',
              'pay_batch_id', p_pay_batch_id,
              'classification', v_classification,
              'recommended_action', v_recommended_action
            )::text;
  END IF;

  SELECT COALESCE(public.settings_defaults.payment_authoriser_quantity, 1)
  INTO v_required_quantity
  FROM public.settings_defaults
  ORDER BY public.settings_defaults.id
  LIMIT 1;

  v_required_quantity := GREATEST(COALESCE(v_required_quantity, 1), 1);

  IF COALESCE(p_auto_requested, false) THEN
    v_status := 'AUTHORISED';
    v_approved_count := v_required_quantity;
  ELSE
    v_status := 'AWAITING_AUTHORISATION';
    v_approved_count := 0;
  END IF;

  WITH selected_scope_rows AS (
    SELECT selected_items.*
    FROM public._pay_payment_correction_selected_items(
      p_pay_batch_id,
      p_selection_json,
      true
    ) AS selected_items
  )
  SELECT jsonb_build_object(
    'pay_batch_id', p_pay_batch_id,
    'requested_action', COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), ''),
    'correction_kind', v_correction_kind,
    'scope_type', COALESCE(NULLIF(btrim(p_selection_json->>'scope_type'), ''), ''),
    'transfer_group_key', COALESCE(NULLIF(btrim(p_selection_json->>'transfer_group_key'), ''), ''),
    'pay_batch_item_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.pay_batch_item_id ORDER BY selected_scope_rows.pay_batch_item_id) FILTER (WHERE selected_scope_rows.pay_batch_item_id IS NOT NULL), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.pay_bank_transfer_id ORDER BY selected_scope_rows.pay_bank_transfer_id) FILTER (WHERE selected_scope_rows.pay_bank_transfer_id IS NOT NULL), '[]'::jsonb),
    'pay_batch_candidate_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.pay_batch_candidate_id ORDER BY selected_scope_rows.pay_batch_candidate_id) FILTER (WHERE selected_scope_rows.pay_batch_candidate_id IS NOT NULL), '[]'::jsonb),
    'candidate_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.candidate_id ORDER BY selected_scope_rows.candidate_id) FILTER (WHERE selected_scope_rows.candidate_id IS NOT NULL), '[]'::jsonb),
    'finance_case_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.finance_case_id ORDER BY selected_scope_rows.finance_case_id) FILTER (WHERE selected_scope_rows.finance_case_id IS NOT NULL), '[]'::jsonb),
    'finance_component_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.finance_component_id ORDER BY selected_scope_rows.finance_component_id) FILTER (WHERE selected_scope_rows.finance_component_id IS NOT NULL), '[]'::jsonb),
    'reservation_ids', COALESCE(jsonb_agg(DISTINCT selected_scope_rows.reservation_id ORDER BY selected_scope_rows.reservation_id) FILTER (WHERE selected_scope_rows.reservation_id IS NOT NULL), '[]'::jsonb)
  )
  INTO v_selected_scope_json
  FROM selected_scope_rows;

  v_selected_scope_json := COALESCE(v_selected_scope_json, jsonb_build_object(
    'pay_batch_id', p_pay_batch_id,
    'requested_action', COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), ''),
    'correction_kind', v_correction_kind,
    'scope_type', COALESCE(NULLIF(btrim(p_selection_json->>'scope_type'), ''), ''),
    'transfer_group_key', COALESCE(NULLIF(btrim(p_selection_json->>'transfer_group_key'), ''), ''),
    'pay_batch_item_ids', '[]'::jsonb,
    'pay_bank_transfer_ids', '[]'::jsonb,
    'pay_batch_candidate_ids', '[]'::jsonb,
    'candidate_ids', '[]'::jsonb,
    'finance_case_ids', '[]'::jsonb,
    'finance_component_ids', '[]'::jsonb,
    'reservation_ids', '[]'::jsonb
  ));

  v_selection_hash := md5((v_selected_scope_json - 'requested_action' - 'correction_kind')::text);

  v_draft_removal_requested := COALESCE(NULLIF(btrim(p_selection_json->>'source_context'), ''), '') = 'DRAFT_REMOVE_FROM_BATCH'
    AND COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), '') = 'CANCEL_PAYMENT_ATTEMPT';

  IF v_draft_removal_requested THEN
    v_selected_item_count := COALESCE(jsonb_array_length(COALESCE(v_selected_scope_json->'pay_batch_item_ids', '[]'::jsonb)), 0);

    IF v_selected_item_count <= 0 THEN
      RAISE EXCEPTION 'DRAFT_REMOVE_SELECTED_ITEM_REQUIRED'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_REMOVE_SELECTED_ITEM_REQUIRED',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;

    IF NULLIF(btrim(COALESCE(p_selection_json->>'expected_item_count', '')), '') IS NOT NULL THEN
      IF (p_selection_json->>'expected_item_count') !~ '^\d+$' THEN
        RAISE EXCEPTION 'DRAFT_REMOVE_EXPECTED_ITEM_COUNT_INVALID'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'DRAFT_REMOVE_EXPECTED_ITEM_COUNT_INVALID',
                  'pay_batch_id', p_pay_batch_id,
                  'expected_item_count', p_selection_json->>'expected_item_count'
                )::text;
      END IF;
      v_expected_item_count := (p_selection_json->>'expected_item_count')::integer;
      IF v_expected_item_count IS DISTINCT FROM v_selected_item_count THEN
        RAISE EXCEPTION 'DRAFT_REMOVE_SELECTION_DRIFT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
                  'pay_batch_id', p_pay_batch_id,
                  'expected_item_count', v_expected_item_count,
                  'selected_item_count', v_selected_item_count
                )::text;
      END IF;
    END IF;

    IF COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') = 'array' THEN
      SELECT
        count(*)::integer,
        COALESCE(sum(CASE WHEN NOT EXISTS (
          SELECT 1
          FROM jsonb_array_elements_text(COALESCE(v_selected_scope_json->'pay_batch_item_ids', '[]'::jsonb)) AS selected_item_ids(value)
          WHERE selected_item_ids.value = expected_item_ids.value
        ) THEN 1 ELSE 0 END), 0)::integer
      INTO v_expected_item_id_count, v_expected_item_mismatch_count
      FROM jsonb_array_elements_text(p_selection_json->'expected_pay_batch_item_ids') AS expected_item_ids(value);

      IF v_expected_item_id_count IS DISTINCT FROM v_selected_item_count
         OR COALESCE(v_expected_item_mismatch_count, 0) > 0 THEN
        RAISE EXCEPTION 'DRAFT_REMOVE_SELECTION_DRIFT'
          USING ERRCODE = 'P0001',
                DETAIL = jsonb_build_object(
                  'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
                  'pay_batch_id', p_pay_batch_id,
                  'expected_item_id_count', v_expected_item_id_count,
                  'selected_item_count', v_selected_item_count,
                  'mismatch_count', v_expected_item_mismatch_count
                )::text;
      END IF;
    END IF;

    WITH batch_state AS (
      SELECT
        public.pay_batches.status,
        public.pay_batches.execution_commit_state,
        public.pay_batches.executing_started_at_utc,
        public.pay_batches.cancelled_at_utc
      FROM public.pay_batches
      WHERE public.pay_batches.id = p_pay_batch_id
    ),
    submission_evidence AS (
      SELECT public.pay_batch_submission_evidence(p_pay_batch_id, true) AS evidence_json
    )
    SELECT
      (
        UPPER(BTRIM(COALESCE(batch_state.status, ''))) IN ('DRAFT', 'DRAFT_CREATED')
        AND UPPER(BTRIM(COALESCE(batch_state.execution_commit_state, ''))) NOT IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'SETTLED', 'CANCELLED')
        AND batch_state.executing_started_at_utc IS NULL
        AND batch_state.cancelled_at_utc IS NULL
      ),
      CASE
        WHEN COALESCE((submission_evidence.evidence_json->>'has_external_provider_submission')::boolean, false)
          OR COALESCE((submission_evidence.evidence_json->>'has_pending_provider_outcome')::boolean, false)
          OR COALESCE((submission_evidence.evidence_json->>'has_unknown_provider_outcome')::boolean, false)
          OR COALESCE((submission_evidence.evidence_json->>'has_terminal_no_money')::boolean, false)
          OR COALESCE((submission_evidence.evidence_json->>'has_final_paid_or_settled')::boolean, false)
        THEN 1
        ELSE 0
      END
    INTO v_batch_pre_bank_safe, v_bank_submission_evidence_count
    FROM batch_state
    CROSS JOIN submission_evidence;

    IF NOT COALESCE(v_batch_pre_bank_safe, false) OR COALESCE(v_bank_submission_evidence_count, 0) > 0 THEN
      RAISE EXCEPTION 'DRAFT_REMOVE_NO_LONGER_PRE_BANK'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_REMOVE_NO_LONGER_PRE_BANK',
                'pay_batch_id', p_pay_batch_id,
                'bank_submission_evidence_count', v_bank_submission_evidence_count
              )::text;
    END IF;

    IF v_recommended_action <> 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' OR v_correction_kind IS DISTINCT FROM 'PRE_BANK_CANCEL' THEN
      RAISE EXCEPTION 'DRAFT_REMOVE_CLASSIFICATION_MISMATCH'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_REMOVE_CLASSIFICATION_MISMATCH',
                'pay_batch_id', p_pay_batch_id,
                'classification', v_classification,
                'correction_kind', v_correction_kind
              )::text;
    END IF;

    IF v_suggested_resolution_required THEN
      RAISE EXCEPTION 'DRAFT_REMOVE_BLOCKED_BY_SUGGESTED_RESOLUTION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'DRAFT_REMOVE_BLOCKED_BY_SUGGESTED_RESOLUTION',
                'pay_batch_id', p_pay_batch_id
              )::text;
    END IF;

    v_draft_removal_auto_authorised := true;
    v_status := 'AUTHORISED';
    v_approved_count := v_required_quantity;
  END IF;

  v_plan := COALESCE(v_plan, '{}'::jsonb) || jsonb_build_object(
    'payment_lifecycle_state', v_classification,
    'recommended_action', v_recommended_action,
    'provider_failure_reason_code', COALESCE(NULLIF(btrim(v_plan->>'provider_failure_reason_code'), ''), v_source_event_failure_reason_code),
    'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_plan->>'provider_failure_reason_group'), ''), v_source_event_failure_reason_group),
    'provider_failure_reason_label', NULLIF(btrim(COALESCE(v_plan->>'provider_failure_reason_label', '')), ''),
    'alert_candidate_kind', NULLIF(btrim(COALESCE(v_plan->>'alert_candidate_kind', '')), ''),
    'alert_candidate_severity', NULLIF(btrim(COALESCE(v_plan->>'alert_candidate_severity', '')), ''),
    'live_status_signature', COALESCE(NULLIF(btrim(v_plan->>'live_status_signature'), ''), NULLIF(btrim(v_plan->>'status_update_signature'), '')),
    'status_update_signature', COALESCE(NULLIF(btrim(v_plan->>'status_update_signature'), ''), NULLIF(btrim(v_plan->>'live_status_signature'), '')),
    'source_bank_event_links', jsonb_strip_nulls(jsonb_build_object(
      'source_bank_event_id', CASE WHEN p_source_bank_event_id IS NULL THEN NULL ELSE p_source_bank_event_id::text END,
      'event_source', v_source_event_source,
      'provider_event_transport', v_source_event_transport,
      'provider_webhook_receipt_id', CASE WHEN v_source_event_webhook_receipt_id IS NULL THEN NULL ELSE v_source_event_webhook_receipt_id::text END,
      'provider_event_type', v_source_event_provider_event_type,
      'provider_event_id', v_source_event_provider_event_id,
      'provider_transaction_id', v_source_event_provider_transaction_id,
      'provider_request_id', v_source_event_provider_request_id,
      'provider_event_key', v_source_event_provider_event_key,
      'provider_signature_valid', v_source_event_signature_valid,
      'mapping_status', v_source_event_mapping_status,
      'mapping_method', v_source_event_mapping_method
    )),
    'full_payment_scope', COALESCE(v_plan->'full_payment_scope', v_plan->'resolved_full_payment_scope_json', '{}'::jsonb),
    'finance_scope', COALESCE(v_plan->'finance_scope', v_plan->'finance_scope_json', '{}'::jsonb),
    'provider_evidence', COALESCE(v_plan->'provider_evidence', '{}'::jsonb),
    'paid_blockers', COALESCE(v_plan->'paid_evidence', v_plan->'blocking_paid_evidence_json', '{}'::jsonb),
    'carry_forward_detection', jsonb_build_object(
      'manual_adjustment_carry_forward_required', COALESCE(NULLIF(v_plan->>'manual_adjustment_carry_forward_required', '')::boolean, false),
      'manual_adjustments_to_carry_forward', COALESCE(v_plan->'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'safe_carry_forward_items', COALESCE(v_plan->'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'signed_carry_forward_amounts', COALESCE(v_plan->'manual_adjustments_to_carry_forward', '[]'::jsonb),
      'manual_adjustments_carried_forward_existing', COALESCE(v_plan->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
      'carry_forward_blockers', COALESCE(v_plan->'carry_forward_blockers', '[]'::jsonb),
      'manual_adjustment_support_details_json', COALESCE(v_plan->'manual_adjustment_support_details_json', '{}'::jsonb)
    ),
    'confirmation_payload', COALESCE(p_accepted_resolution_json, '{}'::jsonb),
    'idempotency_material', jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'source_bank_event_id', CASE WHEN p_source_bank_event_id IS NULL THEN NULL ELSE p_source_bank_event_id::text END,
      'auto_requested', COALESCE(p_auto_requested, false)
    )
  );

  v_plan_material_json := jsonb_build_object(
    'classification', v_classification,
    'recommended_action', v_plan->>'recommended_action',
    'selection', COALESCE(v_plan->'selection', '{}'::jsonb),
    'amounts', COALESCE(v_plan->'amounts', '{}'::jsonb),
    'hard_blockers', v_hard_blockers,
    'effective_hard_blockers', v_effective_hard_blockers,
    'suggested_resolution_required', v_suggested_resolution_required,
    'work_expansion_plan', COALESCE(v_plan->'work_expansion_plan', '{}'::jsonb),
    'movement_classification_detail', jsonb_build_object(
      'classification', v_plan#>>'{movement_classification_detail,classification}',
      'counts', COALESCE(v_plan#>'{movement_classification_detail,counts}', '{}'::jsonb),
      'blockers', COALESCE(v_plan#>'{movement_classification_detail,blockers}', '[]'::jsonb),
      'safe_to_auto_apply', COALESCE(v_plan#>'{movement_classification_detail,safe_to_auto_apply}', 'false'::jsonb)
    )
  );

  v_plan_hash := md5(v_plan_material_json::text);
  v_enriched_accepted_resolution_json := CASE
    WHEN p_accepted_resolution_json IS NULL THEN NULL::jsonb
    ELSE jsonb_strip_nulls(COALESCE(p_accepted_resolution_json, '{}'::jsonb) || jsonb_build_object(
      'confirmation_payload', COALESCE(p_accepted_resolution_json, '{}'::jsonb),
      'full_payment_scope', COALESCE(v_plan->'full_payment_scope', v_plan->'resolved_full_payment_scope_json', '{}'::jsonb),
      'selected_scope', v_selected_scope_json,
      'finance_scope', COALESCE(v_plan->'finance_scope', v_plan->'finance_scope_json', '{}'::jsonb),
      'payment_lifecycle_state', v_classification,
      'recommended_action', v_recommended_action,
      'provider_evidence', COALESCE(v_plan->'provider_evidence', '{}'::jsonb),
      'paid_blockers', COALESCE(v_plan->'paid_blockers', v_plan->'paid_evidence', v_plan->'blocking_paid_evidence_json', '{}'::jsonb),
      'carry_forward_detection', COALESCE(v_plan->'carry_forward_detection', '{}'::jsonb),
      'idempotency_material', jsonb_build_object(
        'pay_batch_id', p_pay_batch_id::text,
        'selection_hash', v_selection_hash,
        'correction_kind', v_correction_kind,
        'source_bank_event_id', CASE WHEN p_source_bank_event_id IS NULL THEN NULL ELSE p_source_bank_event_id::text END,
        'provider_event_key', v_source_event_provider_event_key,
        'auto_requested', COALESCE(p_auto_requested, false)
      ),
      'selection_scope_hash', v_selection_hash,
      'changed_scope_context', v_selected_scope_json,
      'signed_carry_forward_amounts', COALESCE(v_plan->'manual_adjustments_to_carry_forward', '[]'::jsonb)
    ))
  END;

  v_accepted_resolution_hash := CASE
    WHEN v_enriched_accepted_resolution_json IS NULL THEN NULL
    ELSE md5(v_enriched_accepted_resolution_json::text)
  END;

  SELECT public.pay_payment_correction_requests.*
  INTO v_existing_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.pay_batch_id = p_pay_batch_id
    AND public.pay_payment_correction_requests.selection_hash = v_selection_hash
    AND public.pay_payment_correction_requests.correction_kind = v_correction_kind
    AND public.pay_payment_correction_requests.status IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'EXPANDED', 'PROCESSING')
  ORDER BY public.pay_payment_correction_requests.created_at_utc
  LIMIT 1;

  IF v_existing_request.id IS NOT NULL THEN
    IF COALESCE(v_draft_removal_auto_authorised, false)
       AND v_existing_request.status <> 'AUTHORISED' THEN
      UPDATE public.pay_payment_correction_requests AS existing_draft_remove_request
      SET status = 'AUTHORISED',
          approved_count = GREATEST(COALESCE(existing_draft_remove_request.required_quantity, v_required_quantity, 1), 1),
          authorised_at_utc = COALESCE(existing_draft_remove_request.authorised_at_utc, now()),
          updated_at_utc = now()
      WHERE existing_draft_remove_request.id = v_existing_request.id
      RETURNING existing_draft_remove_request.* INTO v_existing_request;

      INSERT INTO public.pay_payment_correction_actions (
        correction_request_id,
        pay_batch_id,
        actor_kind,
        actor_user_id,
        action,
        action_at_utc,
        note,
        before_json,
        after_json,
        metadata_json
      )
      VALUES (
        v_existing_request.id,
        p_pay_batch_id,
        'USER',
        p_actor_user_id,
        'AUTHORISE',
        now(),
        'Auto-authorised draft removal after strict PRE_BANK_CANCEL validation.',
        NULL::jsonb,
        to_jsonb(v_existing_request),
        jsonb_build_object(
          'classification', v_classification,
          'correction_kind', v_correction_kind,
          'draft_removal_auto_authorised', true,
          'selection_hash', v_selection_hash,
          'selected_scope', v_selected_scope_json
        )
      );
    END IF;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_REQUEST_START_EXISTING_OPEN_REQUEST',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'existing_correction_request_id', v_existing_request.id,
        'correction_kind', v_existing_request.correction_kind,
        'status', v_existing_request.status
      ),
      'pay_payment_correction',
      p_pay_batch_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'existing_request', true,
      'correction_request_id', v_existing_request.id,
      'pay_batch_id', v_existing_request.pay_batch_id,
      'correction_kind', v_existing_request.correction_kind,
      'status', v_existing_request.status,
      'authorisation_required', v_existing_request.status <> 'AUTHORISED',
      'approved_count', v_existing_request.approved_count,
      'required_quantity', v_existing_request.required_quantity,
      'plan', v_existing_request.plan_json
    );
  END IF;

  INSERT INTO public.pay_payment_correction_requests (
    pay_batch_id,
    correction_kind,
    status,
    requested_by_user_id,
    requested_at_utc,
    required_quantity,
    approved_count,
    golden_key_used,
    golden_key_user_id,
    reason,
    selection_json,
    selection_hash,
    plan_json,
    plan_hash,
    accepted_resolution_json,
    accepted_resolution_hash,
    source_bank_event_id,
    auto_requested,
    created_at_utc,
    authorised_at_utc,
    applied_at_utc,
    cancelled_at_utc,
    updated_at_utc
  )
  VALUES (
    p_pay_batch_id,
    v_correction_kind,
    v_status,
    CASE WHEN COALESCE(p_auto_requested, false) THEN NULL::uuid ELSE p_actor_user_id END,
    now(),
    v_required_quantity,
    v_approved_count,
    false,
    NULL::uuid,
    NULLIF(btrim(COALESCE(p_reason, '')), ''),
    p_selection_json,
    v_selection_hash,
    v_plan,
    v_plan_hash,
    v_enriched_accepted_resolution_json,
    v_accepted_resolution_hash,
    p_source_bank_event_id,
    COALESCE(p_auto_requested, false),
    now(),
    CASE WHEN COALESCE(p_auto_requested, false) OR COALESCE(v_draft_removal_auto_authorised, false) THEN now() ELSE NULL::timestamptz END,
    NULL::timestamptz,
    NULL::timestamptz,
    now()
  )
  RETURNING public.pay_payment_correction_requests.* INTO v_request;

  INSERT INTO public.pay_payment_correction_actions (
    correction_request_id,
    pay_batch_id,
    actor_kind,
    actor_user_id,
    action,
    action_at_utc,
    note,
    before_json,
    after_json,
    metadata_json
  )
  VALUES (
    v_request.id,
    p_pay_batch_id,
    CASE WHEN COALESCE(p_auto_requested, false) THEN 'SYSTEM' ELSE 'USER' END,
    CASE WHEN COALESCE(p_auto_requested, false) THEN NULL::uuid ELSE p_actor_user_id END,
    'REQUEST',
    now(),
    NULLIF(btrim(COALESCE(p_reason, '')), ''),
    NULL::jsonb,
    to_jsonb(v_request),
    jsonb_build_object(
      'classification', v_classification,
      'correction_kind', v_correction_kind,
      'auto_requested', COALESCE(p_auto_requested, false),
      'source_bank_event_id', p_source_bank_event_id,
      'source_bank_event_links', COALESCE(v_plan->'source_bank_event_links', '{}'::jsonb),
      'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_plan->>'provider_failure_reason_group'), ''), v_source_event_failure_reason_group),
      'plan_hash', v_plan_hash,
      'selection_hash', v_selection_hash,
      'accepted_resolution_hash', v_accepted_resolution_hash,
      'selected_scope', v_selected_scope_json,
      'finance_resolution_validation', v_finance_resolution_validation,
      'draft_removal_auto_authorised', v_draft_removal_auto_authorised
    )
  );

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_REQUEST_START_CREATED',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'correction_request_id', v_request.id,
      'correction_kind', v_correction_kind,
      'status', v_status,
      'classification', v_classification,
      'auto_requested', COALESCE(p_auto_requested, false),
      'required_quantity', v_required_quantity,
      'approved_count', v_approved_count,
      'suggested_resolution_required', v_suggested_resolution_required,
      'accepted_resolution_supplied', v_accepted_resolution_supplied,
      'draft_removal_auto_authorised', v_draft_removal_auto_authorised
    ),
    'pay_payment_correction',
    p_pay_batch_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'existing_request', false,
    'correction_request_id', v_request.id,
    'pay_batch_id', v_request.pay_batch_id,
    'correction_kind', v_request.correction_kind,
    'status', v_request.status,
    'authorisation_required', NOT (COALESCE(v_request.auto_requested, false) OR COALESCE(v_draft_removal_auto_authorised, false)),
    'approved_count', v_request.approved_count,
    'required_quantity', v_request.required_quantity,
    'plan', v_plan,
    'selection_hash', v_selection_hash,
    'selection_scope_hash', v_selection_hash,
    'plan_hash', v_plan_hash,
    'accepted_resolution_hash', v_accepted_resolution_hash,
    'selected_scope', v_selected_scope_json,
    'changed_scope_context', v_selected_scope_json,
    'source_bank_event_links', COALESCE(v_plan->'source_bank_event_links', '{}'::jsonb),
    'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_plan->>'provider_failure_reason_group'), ''), v_source_event_failure_reason_group),
    'finance_resolution_validation', v_finance_resolution_validation,
    'draft_removal_auto_authorised', v_draft_removal_auto_authorised
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_REQUEST_START_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'scope_type', CASE WHEN p_selection_json IS NULL THEN NULL ELSE p_selection_json->>'scope_type' END,
        'source_bank_event_id', p_source_bank_event_id,
        'auto_requested', COALESCE(p_auto_requested, false),
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.pay_payment_correction_plan(
  p_pay_batch_id uuid,
  p_selection_json jsonb,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id uuid;
  v_batch_status text;
  v_batch_pay_date date;
  v_batch_authoritative_payment_date date;
  v_effective_pay_date date;
  v_batch_created_at_utc timestamptz;
  v_batch_execution_commit_state text;
  v_batch_execution_commit_ref text;
  v_classification_result jsonb := '{}'::jsonb;
  v_classification text := 'AMBIGUOUS_REVIEW_REQUIRED';
  v_recommended_action text := 'REVIEW_BANK_EVIDENCE';
  v_hard_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_selection_summary jsonb := '{}'::jsonb;
  v_affected_candidates jsonb := '[]'::jsonb;
  v_affected_transfers jsonb := '[]'::jsonb;
  v_affected_umbrellas jsonb := '[]'::jsonb;
  v_affected_items jsonb := '[]'::jsonb;
  v_affected_finance_cases jsonb := '[]'::jsonb;
  v_communication_effects jsonb := '{}'::jsonb;
  v_suggested_resolution_required boolean := false;
  v_suggested_resolution jsonb := NULL::jsonb;
  v_amounts jsonb := '{}'::jsonb;
  v_draft_interference jsonb := '[]'::jsonb;
  v_large_correction jsonb := '{}'::jsonb;
  v_work_expansion_plan jsonb := '{}'::jsonb;
  v_can_apply boolean := false;
  v_draft_removal_requested boolean := false;
  v_strict_draft_removal_pre_bank_cancel boolean := false;
  v_expected_item_count integer := NULL::integer;
  v_expected_item_id_count integer := 0;
  v_expected_item_mismatch_count integer := 0;

  v_selected_item_count integer := 0;
  v_selected_candidate_count integer := 0;
  v_selected_transfer_count integer := 0;
  v_selected_umbrella_count integer := 0;
  v_key_resolution_failure_count integer := 0;
  v_already_corrected_count integer := 0;
  v_voided_count integer := 0;
  v_pay_channel_change_count integer := 0;
  v_umbrella_change_count integer := 0;
  v_timesheet_item_count integer := 0;
  v_net_fixed_finance_item_count integer := 0;
  v_gross_channel_sensitive_item_count integer := 0;
  v_work_item_count integer := 0;
  v_large_correction_threshold integer := 100;
  v_recommended_chunk_size integer := 50;
  v_total_amount_ex_vat numeric := 0;
  v_total_amount_vat numeric := 0;
  v_total_amount_inc_vat numeric := 0;
  v_queued_unsent_count integer := 0;
  v_sent_notice_count integer := 0;
  v_subject_id text;
  v_scope_type text;
  v_selected_pay_batch_item_ids uuid[] := ARRAY[]::uuid[];
  v_selected_selection_hash text;
  v_selection_filters_applied jsonb := '{}'::jsonb;
  v_suggested_resolution_finance_cases jsonb := '[]'::jsonb;
  v_finance_case_record record;
  v_case_component_ids jsonb := '[]'::jsonb;
  v_case_component_fingerprints jsonb := '{}'::jsonb;
  v_case_suggestion jsonb := NULL::jsonb;
  v_case_suggestion_hash text := NULL::text;
  v_case_generation_error jsonb := NULL::jsonb;
  v_selected_mail_scope_json jsonb := '{}'::jsonb;
  v_mail_legacy_review_count integer := 0;
  v_mail_legacy_queued_review_count integer := 0;

  v_retry_eligible_count integer := 0;
  v_retry_ineligible_count integer := 0;
  v_retry_eligible_scope_json jsonb := '{}'::jsonb;
  v_retry_ineligible_summary_json jsonb := '[]'::jsonb;
  v_retry_in_progress boolean := false;
  v_retry_already_in_progress boolean := false;
  v_retry_operation_id uuid := NULL::uuid;
  v_retry_operation_status text := NULL::text;
  v_retry_button_visible boolean := false;
  v_retry_button_disabled_reason text := NULL::text;
  v_retry_scope_signature text := NULL::text;
  v_retry_status_label text := NULL::text;
  v_retry_button_label text := NULL::text;
  v_retry_running_label text := NULL::text;
  v_recovery_action_label text := NULL::text;
BEGIN
  v_subject_id := COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID');
  v_scope_type := upper(nullif(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''));

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PLAN_START',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'selection_scope_type', CASE WHEN p_selection_json IS NULL THEN NULL ELSE p_selection_json->>'scope_type' END,
      'actor_user_id', p_actor_user_id,
      'selection_json', p_selection_json
    ),
    'pay_payment_correction',
    v_subject_id,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_pay_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAY_BATCH_ID_REQUIRED')::text;
  END IF;

  IF p_selection_json IS NULL OR COALESCE(jsonb_typeof(p_selection_json), 'null') <> 'object' THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_SELECTION_JSON_MUST_BE_OBJECT',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  SELECT
    public.pay_batches.id,
    public.pay_batches.status,
    public.pay_batches.pay_date,
    public.pay_batches.authoritative_payment_date,
    public.pay_batches.created_at_utc,
    public.pay_batches.execution_commit_state,
    public.pay_batches.execution_commit_ref
  INTO
    v_batch_id,
    v_batch_status,
    v_batch_pay_date,
    v_batch_authoritative_payment_date,
    v_batch_created_at_utc,
    v_batch_execution_commit_state,
    v_batch_execution_commit_ref
  FROM public.pay_batches
  WHERE public.pay_batches.id = p_pay_batch_id;

  IF v_batch_id IS NULL THEN
    RAISE EXCEPTION 'PAY_BATCH_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAY_BATCH_NOT_FOUND',
              'pay_batch_id', p_pay_batch_id
            )::text;
  END IF;

  v_effective_pay_date := COALESCE(v_batch_authoritative_payment_date, v_batch_pay_date);

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_selected;
  CREATE TEMP TABLE _tmp_payment_correction_plan_selected ON COMMIT DROP AS
  SELECT
    selected_rows.pay_batch_id,
    selected_rows.pay_batch_candidate_id,
    selected_rows.candidate_id,
    selected_rows.candidate_display_name,
    selected_rows.candidate_tms_ref,
    selected_rows.pay_batch_item_id,
    selected_rows.item_type,
    selected_rows.timesheet_id,
    selected_rows.pay_bank_transfer_id,
    selected_rows.transfer_status,
    selected_rows.transfer_amount,
    selected_rows.transfer_group_key,
    selected_rows.payee_entity_kind,
    selected_rows.payee_entity_id,
    selected_rows.umbrella_id,
    selected_rows.umbrella_name,
    selected_rows.finance_case_id,
    selected_rows.finance_component_id,
    selected_rows.reservation_id,
    selected_rows.pay_channel,
    selected_rows.frozen_source_pay_method,
    selected_rows.frozen_target_pay_method,
    selected_rows.current_candidate_pay_method,
    selected_rows.economic_key_type,
    selected_rows.economic_key_value,
    selected_rows.source_amount_ex_vat,
    selected_rows.target_amount_ex_vat,
    selected_rows.key_resolution_source,
    selected_rows.key_resolution_failure_reason,
    selected_rows.amount_ex_vat,
    selected_rows.amount_vat,
    selected_rows.amount_inc_vat,
    selected_rows.is_voided,
    selected_rows.already_corrected,
    selected_rows.applied_correction_kinds
  FROM public._pay_payment_correction_selected_items(
    p_pay_batch_id,
    p_selection_json,
    true
  ) AS selected_rows;

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_batch_item_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_batch_candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (finance_case_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (finance_component_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (reservation_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_selected (timesheet_id, economic_key_type, economic_key_value);

  SELECT
    COALESCE(array_agg(plan_selected.pay_batch_item_id ORDER BY plan_selected.pay_batch_item_id), ARRAY[]::uuid[]),
    md5(COALESCE(string_agg(plan_selected.pay_batch_item_id::text, ',' ORDER BY plan_selected.pay_batch_item_id::text), 'NO_SELECTED_ITEMS'))
  INTO
    v_selected_pay_batch_item_ids,
    v_selected_selection_hash
  FROM pg_temp._tmp_payment_correction_plan_selected AS plan_selected;

  v_selection_filters_applied := jsonb_build_object(
    'scope_type', v_scope_type,
    'pay_batch_item_id_supplied', p_selection_json ? 'pay_batch_item_id',
    'pay_batch_item_ids_supplied', p_selection_json ? 'pay_batch_item_ids',
    'pay_bank_transfer_id_supplied', p_selection_json ? 'pay_bank_transfer_id',
    'pay_bank_transfer_ids_supplied', p_selection_json ? 'pay_bank_transfer_ids',
    'finance_case_id_supplied', p_selection_json ? 'finance_case_id',
    'finance_case_ids_supplied', p_selection_json ? 'finance_case_ids',
    'finance_component_id_supplied', p_selection_json ? 'finance_component_id',
    'finance_component_ids_supplied', p_selection_json ? 'finance_component_ids',
    'reservation_id_supplied', p_selection_json ? 'reservation_id',
    'reservation_ids_supplied', p_selection_json ? 'reservation_ids',
    'item_type_supplied', p_selection_json ? 'item_type',
    'item_types_supplied', p_selection_json ? 'item_types',
    'expected_item_count_supplied', p_selection_json ? 'expected_item_count',
    'expected_pay_batch_item_ids_supplied', p_selection_json ? 'expected_pay_batch_item_ids'
  );

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_detail;
  CREATE TEMP TABLE _tmp_payment_correction_plan_detail ON COMMIT DROP AS
  SELECT
    plan_selected.pay_batch_id,
    plan_selected.pay_batch_candidate_id,
    plan_selected.candidate_id,
    plan_selected.candidate_display_name,
    plan_selected.candidate_tms_ref,
    plan_selected.pay_batch_item_id,
    plan_selected.item_type,
    plan_selected.timesheet_id,
    plan_selected.pay_bank_transfer_id,
    plan_selected.transfer_status,
    plan_selected.transfer_amount,
    plan_selected.transfer_group_key,
    plan_selected.payee_entity_kind,
    plan_selected.payee_entity_id,
    plan_selected.umbrella_id,
    plan_selected.umbrella_name,
    plan_selected.finance_case_id,
    plan_selected.finance_component_id,
    plan_selected.reservation_id,
    plan_selected.pay_channel,
    plan_selected.frozen_source_pay_method,
    plan_selected.frozen_target_pay_method,
    plan_selected.current_candidate_pay_method,
    plan_selected.economic_key_type,
    plan_selected.economic_key_value,
    plan_selected.source_amount_ex_vat,
    plan_selected.target_amount_ex_vat,
    plan_selected.key_resolution_source,
    plan_selected.key_resolution_failure_reason,
    plan_selected.amount_ex_vat,
    plan_selected.amount_vat,
    plan_selected.amount_inc_vat,
    plan_selected.is_voided,
    plan_selected.already_corrected,
    plan_selected.applied_correction_kinds,
    public.candidates.pay_method AS live_candidate_pay_method,
    public.candidates.umbrella_id AS live_candidate_umbrella_id,
    public.pay_batch_items.frozen_component_classification::text AS frozen_component_classification,
    public.pay_batch_items.frozen_resolution_mode::text AS frozen_resolution_mode,
    public.pay_batch_items.frozen_resolution_payload_json AS frozen_resolution_payload_json,
    public.pay_batch_items.frozen_resolution_result_json AS frozen_resolution_result_json,
    public.pay_batch_items.payout_instruction_snapshot_json AS payout_instruction_snapshot_json,
    public.pay_finance_case_components.classification::text AS finance_component_classification,
    public.pay_finance_case_components.source_pay_method AS finance_component_source_pay_method,
    public.pay_finance_case_components.saved_target_pay_method AS finance_component_saved_target_pay_method,
    public.pay_finance_case_components.saved_resolution_mode::text AS finance_component_saved_resolution_mode,
    public.pay_finance_case_components.is_resolution_stale AS finance_component_is_resolution_stale,
    public.pay_finance_case_components.stale_reason AS finance_component_stale_reason,
    public.pay_finance_case_components.closed_at_utc AS finance_component_closed_at_utc,
    public.pay_advances.case_type::text AS finance_case_type,
    public.pay_advances.advance_kind::text AS finance_advance_kind,
    public.pay_advances.status::text AS finance_case_status,
    public.pay_advances.payout_status::text AS finance_payout_status,
    public.pay_advances.taxability::text AS finance_taxability,
    public.pay_advances.routing_kind::text AS finance_routing_kind,
    public.pay_advances.written_off_at_utc AS finance_written_off_at_utc,
    public.pay_advances.cleared_at_utc AS finance_cleared_at_utc
  FROM pg_temp._tmp_payment_correction_plan_selected AS plan_selected
  JOIN public.pay_batch_items
    ON public.pay_batch_items.id = plan_selected.pay_batch_item_id
  JOIN public.candidates
    ON public.candidates.id = plan_selected.candidate_id
  LEFT JOIN public.pay_finance_case_components
    ON public.pay_finance_case_components.id = plan_selected.finance_component_id
  LEFT JOIN public.pay_advances
    ON public.pay_advances.id = plan_selected.finance_case_id;

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (finance_case_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (finance_component_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (reservation_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_detail (timesheet_id, economic_key_type, economic_key_value);

  v_classification_result := public.pay_payment_cancelability_diagnostic(
    p_pay_batch_id,
    p_selection_json,
    p_actor_user_id
  );

  v_classification := COALESCE(
    NULLIF(btrim(v_classification_result->>'payment_lifecycle_state'), ''),
    NULLIF(btrim(v_classification_result->>'classification'), ''),
    'AMBIGUOUS_REVIEW_REQUIRED'
  );

  v_recommended_action := COALESCE(
    NULLIF(btrim(v_classification_result->>'recommended_action'), ''),
    CASE v_classification
      WHEN 'LOCAL_PREPARED_NOT_SENT' THEN 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
      WHEN 'SCHEDULED_LOCAL_NOT_SENT' THEN 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
      WHEN 'CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'PARTIALLY_CANCELLED_BEFORE_BANK_SUBMISSION' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'FINANCIALS_REWOUND' THEN 'VIEW_RECALCULATE_NEXT_STEP'
      WHEN 'PROVIDER_CANCELLED_NO_MONEY' THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
      WHEN 'PROVIDER_FAILED_NO_MONEY' THEN 'NO_MONEY_UNWIND_AND_RECALCULATE'
      WHEN 'PROVIDER_OUTAGE_RETRY_LATER' THEN 'RETRY_PROVIDER_LATER'
      WHEN 'PROVIDER_SUBMITTED_PENDING' THEN 'CHECK_PROVIDER_STATUS'
      WHEN 'PROVIDER_OUTCOME_UNKNOWN' THEN 'CHECK_PROVIDER_STATUS'
      WHEN 'PAID_OR_SETTLED' THEN 'AMEND_AND_RECOVER_OVERPAYMENT'
      ELSE 'CHECK_PROVIDER_STATUS'
    END
  );

  v_hard_blockers := COALESCE(v_classification_result->'blockers', '[]'::jsonb);

  IF jsonb_array_length(COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb)) > 0 THEN
    v_hard_blockers := v_hard_blockers || COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb);
  END IF;

  v_warnings := COALESCE(v_classification_result->'warnings', '[]'::jsonb);

  IF v_classification = 'AMBIGUOUS_REVIEW_REQUIRED'
     AND jsonb_array_length(v_hard_blockers) = 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'CLASSIFICATION_AMBIGUOUS_REVIEW_REQUIRED',
      'message', 'Payment correction action cannot be planned until provider/bank state is clarified.'
    ));
  END IF;

  SELECT
    count(*)::integer,
    count(DISTINCT plan_detail.candidate_id)::integer,
    count(DISTINCT plan_detail.pay_bank_transfer_id) FILTER (WHERE plan_detail.pay_bank_transfer_id IS NOT NULL)::integer,
    count(DISTINCT plan_detail.umbrella_id) FILTER (WHERE plan_detail.umbrella_id IS NOT NULL)::integer,
    count(*) FILTER (WHERE plan_detail.key_resolution_failure_reason IS NOT NULL OR plan_detail.economic_key_type IS NULL OR plan_detail.economic_key_value IS NULL)::integer,
    count(*) FILTER (WHERE COALESCE(plan_detail.already_corrected, false))::integer,
    count(*) FILTER (WHERE COALESCE(plan_detail.is_voided, false))::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_detail.item_type, ''))) IN ('SEGMENT_DELTA', 'EXPENSE_DELTA', 'ADJUSTMENT_DELTA', 'MILEAGE_DELTA')
    )::integer,
    count(*) FILTER (
      WHERE plan_detail.finance_case_id IS NOT NULL
        AND COALESCE(plan_detail.finance_component_classification, plan_detail.frozen_component_classification, '') IN ('REIMBURSEMENT_GROSS_FIXED', 'NET_PAY_FIXED_RECOVERY')
    )::integer,
    count(*) FILTER (
      WHERE (
        COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
        OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
        OR (
          COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
          AND plan_detail.finance_case_id IS NOT NULL
          AND (
            COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
            OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
            OR NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
            OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
          )
        )
      )
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method, ''))) IS DISTINCT FROM upper(btrim(COALESCE(plan_detail.frozen_target_pay_method, plan_detail.frozen_source_pay_method, plan_detail.pay_channel, '')))
        AND NULLIF(btrim(COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method, '')), '') IS NOT NULL
        AND NULLIF(btrim(COALESCE(plan_detail.frozen_target_pay_method, plan_detail.frozen_source_pay_method, plan_detail.pay_channel, '')), '') IS NOT NULL
    )::integer,
    count(*) FILTER (
      WHERE plan_detail.umbrella_id IS NOT NULL
        AND plan_detail.live_candidate_umbrella_id IS DISTINCT FROM plan_detail.umbrella_id
    )::integer,
    round(COALESCE(sum(COALESCE(plan_detail.amount_ex_vat, 0)), 0), 2)::numeric,
    round(COALESCE(sum(COALESCE(plan_detail.amount_vat, 0)), 0), 2)::numeric,
    round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)::numeric
  INTO
    v_selected_item_count,
    v_selected_candidate_count,
    v_selected_transfer_count,
    v_selected_umbrella_count,
    v_key_resolution_failure_count,
    v_already_corrected_count,
    v_voided_count,
    v_timesheet_item_count,
    v_net_fixed_finance_item_count,
    v_gross_channel_sensitive_item_count,
    v_pay_channel_change_count,
    v_umbrella_change_count,
    v_total_amount_ex_vat,
    v_total_amount_vat,
    v_total_amount_inc_vat
  FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail;

  v_draft_removal_requested := COALESCE(NULLIF(btrim(p_selection_json->>'source_context'), ''), '') = 'DRAFT_REMOVE_FROM_BATCH'
    AND COALESCE(NULLIF(btrim(p_selection_json->>'requested_action'), ''), '') = 'CANCEL_PAYMENT_ATTEMPT';

  IF v_draft_removal_requested THEN
    IF v_selected_item_count <= 0 THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_SELECTED_ITEM_REQUIRED',
        'message', 'Draft removal requires at least one selected non-voided frozen batch item.',
        'pay_batch_id', p_pay_batch_id::text
      ));
    END IF;

    IF NULLIF(btrim(COALESCE(p_selection_json->>'expected_item_count', '')), '') IS NOT NULL THEN
      IF (p_selection_json->>'expected_item_count') !~ '^\d+$' THEN
        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'DRAFT_REMOVE_EXPECTED_ITEM_COUNT_INVALID',
          'message', 'Draft removal expected_item_count must be a whole number.',
          'pay_batch_id', p_pay_batch_id::text,
          'expected_item_count', p_selection_json->>'expected_item_count'
        ));
      ELSE
        v_expected_item_count := (p_selection_json->>'expected_item_count')::integer;
        IF v_expected_item_count IS DISTINCT FROM v_selected_item_count THEN
          v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
            'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
            'message', 'Draft removal selection has changed since the UI built the request.',
            'pay_batch_id', p_pay_batch_id::text,
            'expected_item_count', v_expected_item_count,
            'selected_item_count', v_selected_item_count
          ));
        END IF;
      END IF;
    END IF;

    IF p_selection_json ? 'expected_pay_batch_item_ids' THEN
      IF COALESCE(jsonb_typeof(p_selection_json->'expected_pay_batch_item_ids'), 'null') <> 'array' THEN
        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'DRAFT_REMOVE_EXPECTED_ITEM_IDS_INVALID',
          'message', 'Draft removal expected_pay_batch_item_ids must be an array.',
          'pay_batch_id', p_pay_batch_id::text
        ));
      ELSE
        SELECT
          count(*)::integer,
          COALESCE(sum(CASE WHEN NOT EXISTS (
            SELECT 1
            FROM pg_temp._tmp_payment_correction_plan_selected AS selected_item_rows
            WHERE selected_item_rows.pay_batch_item_id::text = expected_item_ids.value
          ) THEN 1 ELSE 0 END), 0)::integer
        INTO
          v_expected_item_id_count,
          v_expected_item_mismatch_count
        FROM jsonb_array_elements_text(p_selection_json->'expected_pay_batch_item_ids') AS expected_item_ids(value);

        IF v_expected_item_id_count IS DISTINCT FROM v_selected_item_count
           OR COALESCE(v_expected_item_mismatch_count, 0) > 0 THEN
          v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
            'code', 'DRAFT_REMOVE_SELECTION_DRIFT',
            'message', 'Draft removal selected item ids have changed since the UI built the request.',
            'pay_batch_id', p_pay_batch_id::text,
            'expected_item_id_count', v_expected_item_id_count,
            'selected_item_count', v_selected_item_count,
            'mismatch_count', v_expected_item_mismatch_count
          ));
        END IF;
      END IF;
    END IF;

    IF v_recommended_action <> 'PRE_PROVIDER_CANCEL_AND_RECALCULATE' THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_CLASSIFICATION_MISMATCH',
        'message', 'Draft removal is only allowed while the selected payment is still a strict pre-bank cancel.',
        'pay_batch_id', p_pay_batch_id::text,
        'classification', v_classification
      ));
    END IF;

    IF upper(btrim(COALESCE(v_batch_status, ''))) NOT IN ('DRAFT', 'DRAFT_CREATED')
       OR upper(btrim(COALESCE(v_batch_execution_commit_state, ''))) IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'SETTLED', 'CANCELLED') THEN
      v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
        'code', 'DRAFT_REMOVE_NO_LONGER_PRE_BANK',
        'message', 'Draft removal is only allowed before the batch is submitted, executed, settled, cancelled, or committed.',
        'pay_batch_id', p_pay_batch_id::text,
        'batch_status', v_batch_status,
        'execution_commit_state', v_batch_execution_commit_state
      ));
    END IF;
  END IF;

  v_strict_draft_removal_pre_bank_cancel := v_draft_removal_requested
    AND v_recommended_action = 'PRE_PROVIDER_CANCEL_AND_RECALCULATE'
    AND v_selected_item_count > 0
    AND upper(btrim(COALESCE(v_batch_status, ''))) IN ('DRAFT', 'DRAFT_CREATED')
    AND upper(btrim(COALESCE(v_batch_execution_commit_state, ''))) NOT IN ('SUBMITTED_NOT_COMMITTED', 'COMMITTED', 'SETTLED', 'CANCELLED')
    AND jsonb_array_length(v_hard_blockers) = 0;

  IF v_gross_channel_sensitive_item_count > 0 AND NOT COALESCE(v_strict_draft_removal_pre_bank_cancel, false) THEN
    v_suggested_resolution_required := true;
  END IF;

  SELECT COALESCE(jsonb_agg(candidate_rows.candidate_json ORDER BY candidate_rows.candidate_display_name), '[]'::jsonb)
  INTO v_affected_candidates
  FROM (
    SELECT
      plan_detail.candidate_display_name,
      jsonb_build_object(
        'pay_batch_candidate_id', plan_detail.pay_batch_candidate_id,
        'candidate_id', plan_detail.candidate_id,
        'candidate_display_name', plan_detail.candidate_display_name,
        'candidate_tms_ref', plan_detail.candidate_tms_ref,
        'current_candidate_pay_method', COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method),
        'current_umbrella_id', plan_detail.live_candidate_umbrella_id,
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS candidate_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    GROUP BY
      plan_detail.pay_batch_candidate_id,
      plan_detail.candidate_id,
      plan_detail.candidate_display_name,
      plan_detail.candidate_tms_ref,
      COALESCE(plan_detail.current_candidate_pay_method, plan_detail.live_candidate_pay_method),
      plan_detail.live_candidate_umbrella_id
  ) AS candidate_rows;

  SELECT COALESCE(jsonb_agg(transfer_rows.transfer_json ORDER BY transfer_rows.transfer_group_key, transfer_rows.pay_bank_transfer_id), '[]'::jsonb)
  INTO v_affected_transfers
  FROM (
    SELECT
      plan_detail.pay_bank_transfer_id,
      plan_detail.transfer_group_key,
      jsonb_build_object(
        'pay_bank_transfer_id', plan_detail.pay_bank_transfer_id,
        'transfer_status', plan_detail.transfer_status,
        'transfer_amount', plan_detail.transfer_amount,
        'transfer_group_key', plan_detail.transfer_group_key,
        'payee_entity_kind', plan_detail.payee_entity_kind,
        'payee_entity_id', plan_detail.payee_entity_id,
        'candidate_count', count(DISTINCT plan_detail.candidate_id)::integer,
        'item_count', count(*)::integer,
        'selected_amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS transfer_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
    GROUP BY
      plan_detail.pay_bank_transfer_id,
      plan_detail.transfer_status,
      plan_detail.transfer_amount,
      plan_detail.transfer_group_key,
      plan_detail.payee_entity_kind,
      plan_detail.payee_entity_id
  ) AS transfer_rows;

  SELECT COALESCE(jsonb_agg(umbrella_rows.umbrella_json ORDER BY umbrella_rows.umbrella_name), '[]'::jsonb)
  INTO v_affected_umbrellas
  FROM (
    SELECT
      plan_detail.umbrella_name,
      jsonb_build_object(
        'umbrella_id', plan_detail.umbrella_id,
        'umbrella_name', plan_detail.umbrella_name,
        'candidate_count', count(DISTINCT plan_detail.candidate_id)::integer,
        'transfer_count', count(DISTINCT plan_detail.pay_bank_transfer_id) FILTER (WHERE plan_detail.pay_bank_transfer_id IS NOT NULL)::integer,
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
      ) AS umbrella_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.umbrella_id IS NOT NULL
    GROUP BY plan_detail.umbrella_id, plan_detail.umbrella_name
  ) AS umbrella_rows;

  SELECT COALESCE(jsonb_agg(item_rows.item_json ORDER BY item_rows.candidate_display_name, item_rows.pay_batch_item_id), '[]'::jsonb)
  INTO v_affected_items
  FROM (
    SELECT
      plan_detail.candidate_display_name,
      plan_detail.pay_batch_item_id,
      jsonb_build_object(
        'pay_batch_item_id', plan_detail.pay_batch_item_id,
        'pay_batch_candidate_id', plan_detail.pay_batch_candidate_id,
        'candidate_id', plan_detail.candidate_id,
        'candidate_display_name', plan_detail.candidate_display_name,
        'item_type', plan_detail.item_type,
        'timesheet_id', plan_detail.timesheet_id,
        'pay_bank_transfer_id', plan_detail.pay_bank_transfer_id,
        'finance_case_id', plan_detail.finance_case_id,
        'finance_component_id', plan_detail.finance_component_id,
        'reservation_id', plan_detail.reservation_id,
        'economic_key_type', plan_detail.economic_key_type,
        'economic_key_value', plan_detail.economic_key_value,
        'key_resolution_source', plan_detail.key_resolution_source,
        'key_resolution_failure_reason', plan_detail.key_resolution_failure_reason,
        'amount_ex_vat', plan_detail.amount_ex_vat,
        'amount_vat', plan_detail.amount_vat,
        'amount_inc_vat', plan_detail.amount_inc_vat,
        'is_voided', plan_detail.is_voided,
        'already_corrected', plan_detail.already_corrected,
        'applied_correction_kinds', plan_detail.applied_correction_kinds
      ) AS item_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
  ) AS item_rows;

  SELECT COALESCE(jsonb_agg(finance_case_rows.finance_case_json ORDER BY finance_case_rows.finance_case_id), '[]'::jsonb)
  INTO v_affected_finance_cases
  FROM (
    SELECT
      plan_detail.finance_case_id,
      jsonb_build_object(
        'finance_case_id', plan_detail.finance_case_id,
        'candidate_id', min(plan_detail.candidate_id::text),
        'case_type', max(plan_detail.finance_case_type),
        'advance_kind', max(plan_detail.finance_advance_kind),
        'status', max(plan_detail.finance_case_status),
        'payout_status', max(plan_detail.finance_payout_status),
        'taxability', max(plan_detail.finance_taxability),
        'routing_kind', max(plan_detail.finance_routing_kind),
        'written_off_at_utc', max(plan_detail.finance_written_off_at_utc),
        'cleared_at_utc', max(plan_detail.finance_cleared_at_utc),
        'component_ids', COALESCE(jsonb_agg(DISTINCT plan_detail.finance_component_id) FILTER (WHERE plan_detail.finance_component_id IS NOT NULL), '[]'::jsonb),
        'reservation_ids', COALESCE(jsonb_agg(DISTINCT plan_detail.reservation_id) FILTER (WHERE plan_detail.reservation_id IS NOT NULL), '[]'::jsonb),
        'item_count', count(*)::integer,
        'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2),
        'requires_suggested_resolution', bool_or(
          COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR (
            COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
            AND (
              NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
              OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
            )
          )
        )
      ) AS finance_case_json
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_case_id IS NOT NULL
    GROUP BY plan_detail.finance_case_id
  ) AS finance_case_rows;

  v_amounts := jsonb_build_object(
    'amount_ex_vat', v_total_amount_ex_vat,
    'amount_vat', v_total_amount_vat,
    'amount_inc_vat', v_total_amount_inc_vat,
    'by_pay_channel', COALESCE((
      SELECT jsonb_agg(channel_rows.channel_json ORDER BY channel_rows.pay_channel)
      FROM (
        SELECT
          COALESCE(plan_detail.pay_channel, 'UNKNOWN') AS pay_channel,
          jsonb_build_object(
            'pay_channel', COALESCE(plan_detail.pay_channel, 'UNKNOWN'),
            'item_count', count(*)::integer,
            'amount_ex_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_ex_vat, 0)), 0), 2),
            'amount_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_vat, 0)), 0), 2),
            'amount_inc_vat', round(COALESCE(sum(COALESCE(plan_detail.amount_inc_vat, 0)), 0), 2)
          ) AS channel_json
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        GROUP BY COALESCE(plan_detail.pay_channel, 'UNKNOWN')
      ) AS channel_rows
    ), '[]'::jsonb)
  );

  IF v_pay_channel_change_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'PAY_CHANNEL_CHANGED_AFTER_BATCH',
      'message', 'Correction will use the original frozen batch artifact. Any future replacement payment will use the candidate current live pay channel.',
      'affected_item_count', v_pay_channel_change_count
    ));
  END IF;

  IF v_umbrella_change_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'CANDIDATE_UMBRELLA_CHANGED_AFTER_BATCH',
      'message', 'One or more selected items were frozen against a different umbrella/payment group from the candidate current umbrella. Correction uses the frozen batch artifact; future replacement payment uses the current live umbrella routing.',
      'affected_item_count', v_umbrella_change_count
    ));
  END IF;

  IF v_timesheet_item_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'TIMESHEET_CORRECTION_USES_FROZEN_BATCH_METHOD',
      'message', 'Timesheet correction follows the old frozen batch artifact and does not recalculate the old payment from current live timesheet financials.',
      'affected_item_count', v_timesheet_item_count
    ));
  END IF;

  IF v_net_fixed_finance_item_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'NET_FIXED_FINANCE_ITEMS_NO_CHANNEL_CONVERSION',
      'message', 'Net/fixed finance items do not require PAYE/Umbrella amount conversion. Reservation and payout state still need correction handling.',
      'affected_item_count', v_net_fixed_finance_item_count
    ));
  END IF;

  IF v_suggested_resolution_required THEN
    v_suggested_resolution_finance_cases := '[]'::jsonb;

    FOR v_finance_case_record IN
      SELECT
        plan_detail.finance_case_id AS finance_case_id,
        (array_agg(DISTINCT plan_detail.candidate_id ORDER BY plan_detail.candidate_id))[1] AS candidate_id,
        COALESCE(jsonb_agg(DISTINCT plan_detail.finance_component_id) FILTER (WHERE plan_detail.finance_component_id IS NOT NULL), '[]'::jsonb) AS selected_component_ids
      FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
      WHERE plan_detail.finance_case_id IS NOT NULL
        AND (
          COALESCE(plan_detail.finance_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR COALESCE(plan_detail.frozen_component_classification, '') = 'TAXABLE_CHANNEL_SENSITIVE'
          OR (
            COALESCE(plan_detail.finance_taxability, '') = 'TAXABLE'
            AND (
              NULLIF(btrim(COALESCE(plan_detail.frozen_resolution_mode, '')), '') IS NOT NULL
              OR NULLIF(btrim(COALESCE(plan_detail.finance_component_saved_resolution_mode, '')), '') IS NOT NULL
            )
          )
        )
      GROUP BY plan_detail.finance_case_id
      ORDER BY plan_detail.finance_case_id
    LOOP
      SELECT
        COALESCE(jsonb_agg(finance_components.id ORDER BY finance_components.id), '[]'::jsonb),
        COALESCE(jsonb_object_agg(
          finance_components.id::text,
          COALESCE(
            NULLIF(btrim(finance_components.resolution_fingerprint), ''),
            md5(jsonb_build_object(
              'finance_component_id', finance_components.id,
              'finance_case_id', finance_components.finance_case_id,
              'classification', finance_components.classification::text,
              'source_pay_method', finance_components.source_pay_method,
              'source_amount', finance_components.source_amount,
              'remaining_source_amount', finance_components.remaining_source_amount,
              'saved_target_pay_method', finance_components.saved_target_pay_method,
              'saved_resolution_mode', finance_components.saved_resolution_mode::text,
              'saved_resolution_payload_json', finance_components.saved_resolution_payload_json,
              'saved_resolution_result_json', finance_components.saved_resolution_result_json,
              'is_resolution_stale', finance_components.is_resolution_stale,
              'closed_at_utc', finance_components.closed_at_utc,
              'updated_at_utc', finance_components.updated_at_utc
            )::text)
          )
        ), '{}'::jsonb)
      INTO
        v_case_component_ids,
        v_case_component_fingerprints
      FROM public.pay_finance_case_components AS finance_components
      WHERE finance_components.finance_case_id = v_finance_case_record.finance_case_id
        AND finance_components.id IN (
          SELECT DISTINCT plan_detail.finance_component_id
          FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
          WHERE plan_detail.finance_case_id = v_finance_case_record.finance_case_id
            AND plan_detail.finance_component_id IS NOT NULL
        );

      v_case_suggestion := NULL::jsonb;
      v_case_suggestion_hash := NULL::text;
      v_case_generation_error := NULL::jsonb;

      IF p_actor_user_id IS NULL THEN
        v_case_generation_error := jsonb_build_object(
          'code', 'ACTOR_USER_ID_REQUIRED_FOR_SUGGESTED_RESOLUTION',
          'message', 'A real taxable channel restructure suggestion requires an actor user id because the existing suggested-resolution function requires p_actor_user_id.'
        );

        v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
          'code', 'ACTOR_USER_ID_REQUIRED_FOR_SUGGESTED_RESOLUTION',
          'message', 'Gross/taxable/channel-sensitive finance items require a suggested resolution, but no actor user id was supplied to generate it.',
          'finance_case_id', v_finance_case_record.finance_case_id
        ));
      ELSE
        BEGIN
          v_case_suggestion := public.pay_finance_case_taxable_channel_restructure_suggestion(
            p_finance_case_id => v_finance_case_record.finance_case_id,
            p_actor_user_id => p_actor_user_id,
            p_effective_pay_date => v_effective_pay_date,
            p_resolution_path => 'SUGGESTED',
            p_schedule_input_mode => NULL::text,
            p_weeks_total => NULL::integer,
            p_weekly_due => NULL::numeric,
            p_manual_total_remaining => NULL::numeric,
            p_note => 'Generated for payment correction plan ' || p_pay_batch_id::text
          );

          v_case_suggestion_hash := md5(jsonb_build_object(
            'finance_case_id', v_finance_case_record.finance_case_id,
            'candidate_id', v_finance_case_record.candidate_id,
            'component_ids', v_case_component_ids,
            'selected_component_ids', v_finance_case_record.selected_component_ids,
            'component_fingerprints', v_case_component_fingerprints,
            'effective_pay_date', v_effective_pay_date,
            'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
            'resolution_path', COALESCE(v_case_suggestion->>'resolution_path', v_case_suggestion#>>'{request,resolution_path}', 'SUGGESTED'),
            'resolution_mode', COALESCE(v_case_suggestion->>'resolution_mode', v_case_suggestion#>>'{result,resolution_mode}', v_case_suggestion#>>'{suggestion,resolution_mode}'),
            'weeks_total', COALESCE(v_case_suggestion->>'weeks_total', v_case_suggestion#>>'{result,weeks_total}', v_case_suggestion#>>'{suggestion,weeks_total}'),
            'weekly_due', COALESCE(v_case_suggestion->>'weekly_due', v_case_suggestion#>>'{result,weekly_due}', v_case_suggestion#>>'{suggestion,weekly_due}'),
            'manual_total_remaining', COALESCE(v_case_suggestion->>'manual_total_remaining', v_case_suggestion#>>'{result,manual_total_remaining}', v_case_suggestion#>>'{suggestion,manual_total_remaining}'),
            'taxable_channel_result', COALESCE(
              v_case_suggestion->'taxable_channel_result',
              v_case_suggestion->'result',
              v_case_suggestion->'suggestion',
              v_case_suggestion
            ) - 'generated_at'
              - 'generated_at_utc'
              - 'created_at'
              - 'created_at_utc'
              - 'updated_at'
              - 'updated_at_utc'
              - 'audit'
              - 'debug'
          )::text);
        EXCEPTION
          WHEN OTHERS THEN
            v_case_generation_error := jsonb_build_object(
              'code', 'SUGGESTED_RESOLUTION_GENERATION_FAILED',
              'sqlstate', SQLSTATE,
              'message', SQLERRM
            );

            v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
              'code', 'SUGGESTED_RESOLUTION_GENERATION_FAILED',
              'message', 'A gross/taxable/channel-sensitive finance suggested resolution could not be generated using the existing suggested-resolution process.',
              'finance_case_id', v_finance_case_record.finance_case_id,
              'sqlstate', SQLSTATE,
              'error_message', SQLERRM
            ));
        END;
      END IF;

      v_suggested_resolution_finance_cases := v_suggested_resolution_finance_cases || jsonb_build_array(jsonb_build_object(
        'finance_case_id', v_finance_case_record.finance_case_id,
        'candidate_id', v_finance_case_record.candidate_id,
        'component_ids', v_case_component_ids,
        'selected_component_ids', v_finance_case_record.selected_component_ids,
        'current_component_fingerprints', v_case_component_fingerprints,
        'suggestion', v_case_suggestion,
        'suggestion_hash', v_case_suggestion_hash,
        'suggestion_hash_basis', jsonb_build_object(
          'finance_case_id', v_finance_case_record.finance_case_id,
          'candidate_id', v_finance_case_record.candidate_id,
          'component_ids', v_case_component_ids,
          'selected_component_ids', v_finance_case_record.selected_component_ids,
          'component_fingerprints', v_case_component_fingerprints,
          'effective_pay_date', v_effective_pay_date,
          'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure'
        ),
        'suggestion_generation_error', v_case_generation_error,
        'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
        'effective_pay_date', v_effective_pay_date,
        'accepted_payload_required', true
      ));
    END LOOP;

    v_suggested_resolution := jsonb_build_object(
      'required', true,
      'reason', 'Gross/taxable/channel-sensitive finance items are present and must use the existing suggested-resolution process before correction apply.',
      'must_be_accepted_before_apply', true,
      'must_be_applied_atomically_with_correction', true,
      'apply_surface', 'pay_finance_case_apply_taxable_channel_restructure',
      'finance_cases', v_suggested_resolution_finance_cases
    );

    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'SUGGESTED_RESOLUTION_REQUIRED',
      'message', 'Gross/taxable/channel-sensitive finance items require an accepted suggested resolution before this correction request can be started.',
      'affected_item_count', v_gross_channel_sensitive_item_count,
      'suggested_resolution', v_suggested_resolution
    ));
  ELSE
    v_suggested_resolution := NULL::jsonb;
  END IF;

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_overlap_items;
  CREATE TEMP TABLE _tmp_payment_correction_plan_overlap_items ON COMMIT DROP AS
  WITH selected_candidate_ids AS (
    SELECT DISTINCT plan_detail.candidate_id
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.candidate_id IS NOT NULL
  ),
  selected_economic_keys AS (
    SELECT DISTINCT
      plan_detail.candidate_id,
      plan_detail.timesheet_id,
      plan_detail.economic_key_type,
      plan_detail.economic_key_value
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.candidate_id IS NOT NULL
      AND plan_detail.timesheet_id IS NOT NULL
      AND plan_detail.economic_key_type IS NOT NULL
      AND plan_detail.economic_key_value IS NOT NULL
  ),
  selected_finance_scope AS (
    SELECT DISTINCT
      plan_detail.finance_case_id,
      plan_detail.finance_component_id,
      plan_detail.reservation_id
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_case_id IS NOT NULL
       OR plan_detail.finance_component_id IS NOT NULL
       OR plan_detail.reservation_id IS NOT NULL
  ),
  filtered_other_items AS (
    SELECT
      public.pay_batches.id AS other_pay_batch_id,
      public.pay_batches.status AS other_batch_status,
      public.pay_batches.created_at_utc AS other_batch_created_at_utc,
      public.pay_batches.execution_commit_state AS other_execution_commit_state,
      public.pay_batches.execution_commit_ref AS other_execution_commit_ref,
      public.pay_batch_candidates.candidate_id AS other_candidate_id,
      public.pay_batch_items.id AS other_pay_batch_item_id,
      public.pay_batch_items.pay_batch_candidate_id AS other_pay_batch_candidate_id,
      public.pay_batch_items.timesheet_id AS other_timesheet_id,
      public.pay_batch_items.finance_case_id AS other_finance_case_id,
      public.pay_batch_items.finance_component_id AS other_finance_component_id,
      public.pay_batch_items.reservation_id AS other_reservation_id,
      public.pay_batch_items.pay_bank_transfer_id AS other_pay_bank_transfer_id,
      other_economic_components.key_type AS other_economic_key_type,
      other_economic_components.key_value AS other_economic_key_value,
      public.pay_batch_candidates.settlement_status AS other_candidate_settlement_status,
      public.pay_batch_candidates.settled_at_utc AS other_candidate_settled_at_utc,
      public.pay_bank_transfers.status AS other_transfer_status,
      public.pay_bank_transfers.completed_at_utc AS other_transfer_completed_at_utc
    FROM public.pay_batches
    JOIN public.pay_batch_candidates
      ON public.pay_batch_candidates.pay_batch_id = public.pay_batches.id
    JOIN public.pay_batch_items
      ON public.pay_batch_items.pay_batch_candidate_id = public.pay_batch_candidates.id
    JOIN selected_candidate_ids
      ON selected_candidate_ids.candidate_id = public.pay_batch_candidates.candidate_id
    LEFT JOIN public.pay_bank_transfers
      ON public.pay_bank_transfers.id = public.pay_batch_items.pay_bank_transfer_id
    LEFT JOIN LATERAL public._pay_batch_item_economic_components(NULL::uuid, ARRAY[public.pay_batch_items.id]) AS other_economic_components
      ON true
    WHERE public.pay_batches.id <> p_pay_batch_id
      AND COALESCE(public.pay_batch_items.is_voided, false) = false
      AND NOT EXISTS (
        SELECT 1
        FROM public.pay_payment_correction_items AS other_applied_corrections
        WHERE other_applied_corrections.pay_batch_item_id = public.pay_batch_items.id
          AND other_applied_corrections.status = 'APPLIED'
      )
  )
  SELECT
    filtered_other_items.other_pay_batch_id,
    filtered_other_items.other_batch_status,
    filtered_other_items.other_batch_created_at_utc,
    filtered_other_items.other_execution_commit_state,
    filtered_other_items.other_execution_commit_ref,
    filtered_other_items.other_candidate_id,
    filtered_other_items.other_pay_batch_item_id,
    filtered_other_items.other_pay_batch_candidate_id,
    filtered_other_items.other_timesheet_id,
    filtered_other_items.other_finance_case_id,
    filtered_other_items.other_finance_component_id,
    filtered_other_items.other_reservation_id,
    filtered_other_items.other_pay_bank_transfer_id,
    filtered_other_items.other_economic_key_type,
    filtered_other_items.other_economic_key_value,
    filtered_other_items.other_candidate_settlement_status,
    filtered_other_items.other_candidate_settled_at_utc,
    filtered_other_items.other_transfer_status,
    filtered_other_items.other_transfer_completed_at_utc,
    CASE
      WHEN EXISTS (
        SELECT 1
        FROM selected_economic_keys
        WHERE selected_economic_keys.candidate_id = filtered_other_items.other_candidate_id
          AND selected_economic_keys.timesheet_id = filtered_other_items.other_timesheet_id
          AND selected_economic_keys.economic_key_type = filtered_other_items.other_economic_key_type
          AND selected_economic_keys.economic_key_value = filtered_other_items.other_economic_key_value
      ) THEN 'ECONOMIC_KEY'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.finance_case_id IS NOT NULL
          AND selected_finance_scope.finance_case_id = filtered_other_items.other_finance_case_id
      ) THEN 'FINANCE_CASE'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.finance_component_id IS NOT NULL
          AND selected_finance_scope.finance_component_id = filtered_other_items.other_finance_component_id
      ) THEN 'FINANCE_COMPONENT'
      WHEN EXISTS (
        SELECT 1
        FROM selected_finance_scope
        WHERE selected_finance_scope.reservation_id IS NOT NULL
          AND selected_finance_scope.reservation_id = filtered_other_items.other_reservation_id
      ) THEN 'RESERVATION'
      ELSE NULL
    END AS overlap_kind
  FROM filtered_other_items
  WHERE EXISTS (
      SELECT 1
      FROM selected_economic_keys
      WHERE selected_economic_keys.candidate_id = filtered_other_items.other_candidate_id
        AND selected_economic_keys.timesheet_id = filtered_other_items.other_timesheet_id
        AND selected_economic_keys.economic_key_type = filtered_other_items.other_economic_key_type
        AND selected_economic_keys.economic_key_value = filtered_other_items.other_economic_key_value
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.finance_case_id IS NOT NULL
        AND selected_finance_scope.finance_case_id = filtered_other_items.other_finance_case_id
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.finance_component_id IS NOT NULL
        AND selected_finance_scope.finance_component_id = filtered_other_items.other_finance_component_id
    )
    OR EXISTS (
      SELECT 1
      FROM selected_finance_scope
      WHERE selected_finance_scope.reservation_id IS NOT NULL
        AND selected_finance_scope.reservation_id = filtered_other_items.other_reservation_id
    );

  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (other_pay_batch_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (other_candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_plan_overlap_items (overlap_kind);

  SELECT COALESCE(jsonb_agg(overlap_batches.overlap_json ORDER BY overlap_batches.other_batch_created_at_utc, overlap_batches.other_pay_batch_id), '[]'::jsonb)
  INTO v_draft_interference
  FROM (
    SELECT
      overlap_items.other_pay_batch_id,
      min(overlap_items.other_batch_created_at_utc) AS other_batch_created_at_utc,
      jsonb_build_object(
        'pay_batch_id', overlap_items.other_pay_batch_id,
        'status', max(overlap_items.other_batch_status),
        'execution_commit_state', max(overlap_items.other_execution_commit_state),
        'execution_commit_ref', max(overlap_items.other_execution_commit_ref),
        'overlap_kinds', COALESCE(jsonb_agg(DISTINCT overlap_items.overlap_kind) FILTER (WHERE overlap_items.overlap_kind IS NOT NULL), '[]'::jsonb),
        'candidate_count', count(DISTINCT overlap_items.other_candidate_id)::integer,
        'item_count', count(DISTINCT overlap_items.other_pay_batch_item_id)::integer,
        'message', 'This correction cannot be applied because draft batch ' || overlap_items.other_pay_batch_id::text || ' already reserves affected items under the current pay channel. Delete/cancel draft batch ' || overlap_items.other_pay_batch_id::text || ' first, then retry.'
      ) AS overlap_json
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE public._pay_batch_status_is_active_reservation(overlap_items.other_batch_status)
    GROUP BY overlap_items.other_pay_batch_id
  ) AS overlap_batches;

  IF jsonb_array_length(v_draft_interference) > 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'OVERLAPPING_DRAFT_BATCH_RESERVES_AFFECTED_ITEMS',
      'message', 'This correction cannot be applied because another draft/reserved batch already reserves affected items. Delete/cancel the interfering draft batch first, then retry.',
      'draft_interference', v_draft_interference
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_batch_status, ''))) IN ('SCHEDULED', 'EXECUTING', 'WAITING_BANK_CONFIRM', 'AUTHORISED_FOR_PAYMENT', 'AWAITING_AUTHORISATION')
        OR upper(btrim(COALESCE(overlap_items.other_execution_commit_state, ''))) IN ('COMMITTED', 'SUBMITTED')
        OR NULLIF(btrim(COALESCE(overlap_items.other_execution_commit_ref, '')), '') IS NOT NULL
      )
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_AUTHORISED_OR_SUBMITTED_BATCH_OVERLAP',
      'message', 'A later authorised/submitted batch overlaps the selected correction scope. Manual review is required before correction can apply.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_batch_status, ''))) IN ('FAILED', 'PARTIAL')
      )
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_FAILED_OR_AMBIGUOUS_BATCH_OVERLAP',
      'message', 'A later failed or partial batch overlaps the selected correction scope. Manual review is required.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_overlap_items AS overlap_items
    WHERE overlap_items.other_batch_created_at_utc > v_batch_created_at_utc
      AND (
        upper(btrim(COALESCE(overlap_items.other_candidate_settlement_status, ''))) = 'SETTLED'
        OR overlap_items.other_candidate_settled_at_utc IS NOT NULL
        OR upper(btrim(COALESCE(overlap_items.other_transfer_status, ''))) = 'COMPLETED'
        OR overlap_items.other_transfer_completed_at_utc IS NOT NULL
      )
  ) THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'LATER_SETTLED_BATCH_OVERLAP_WARNING',
      'message', 'A later settled batch overlaps the candidate/economic scope. It must remain untouched; this correction only affects the selected old frozen batch artifacts.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_written_off_at_utc IS NOT NULL
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'FINANCE_CASE_WRITTEN_OFF',
      'message', 'One or more selected finance cases have been written off and require manual finance review.'
    ));
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
    WHERE plan_detail.finance_component_is_resolution_stale IS TRUE
  ) THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'FINANCE_COMPONENT_RESOLUTION_STALE',
      'message', 'One or more selected finance component resolutions are stale and must be regenerated before correction apply.'
    ));
  END IF;

  SELECT jsonb_build_object(
    'scope_type', v_scope_type,
    'work_unit', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'work_unit', '')), ''), v_scope_type, 'UNKNOWN'),
    'pay_batch_id', p_pay_batch_id::text,
    'pay_batch_ids', jsonb_build_array(p_pay_batch_id::text),
    'is_whole_batch', (
      v_scope_type = 'BATCH'
      AND NOT (COALESCE(p_selection_json, '{}'::jsonb) ?| ARRAY[
        'pay_batch_item_id',
        'pay_batch_item_ids',
        'selected_pay_batch_item_ids',
        'expected_pay_batch_item_ids',
        'pay_batch_candidate_id',
        'pay_batch_candidate_ids',
        'selected_pay_batch_candidate_ids',
        'candidate_id',
        'candidate_ids',
        'selected_candidate_ids',
        'pay_bank_transfer_id',
        'pay_bank_transfer_ids',
        'selected_pay_bank_transfer_ids',
        'umbrella_id',
        'umbrella_ids',
        'selected_umbrella_ids',
        'finance_case_id',
        'finance_case_ids',
        'selected_finance_case_ids',
        'finance_component_id',
        'finance_component_ids',
        'selected_finance_component_ids',
        'reservation_id',
        'reservation_ids',
        'selected_reservation_ids',
        'payout_transfer_id',
        'payout_transfer_ids',
        'selected_payout_transfer_ids',
        'transfer_group_key',
        'transfer_group_keys',
        'selected_transfer_group_keys'
      ]::text[])
    ),
    'selected_candidate_scope_complete', (
      v_scope_type = 'CANDIDATES'
      AND NOT (COALESCE(p_selection_json, '{}'::jsonb) ?| ARRAY[
        'pay_batch_item_id',
        'pay_batch_item_ids',
        'selected_pay_batch_item_ids',
        'expected_pay_batch_item_ids',
        'pay_bank_transfer_id',
        'pay_bank_transfer_ids',
        'selected_pay_bank_transfer_ids',
        'finance_case_id',
        'finance_case_ids',
        'selected_finance_case_ids',
        'finance_component_id',
        'finance_component_ids',
        'selected_finance_component_ids',
        'reservation_id',
        'reservation_ids',
        'selected_reservation_ids',
        'payout_transfer_id',
        'payout_transfer_ids',
        'selected_payout_transfer_ids',
        'transfer_group_key',
        'transfer_group_keys',
        'selected_transfer_group_keys'
      ]::text[])
    ),
    'pay_batch_item_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_batch_item_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_batch_item_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_batch_candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_batch_candidate_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_batch_candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'candidate_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.candidate_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.candidate_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'pay_bank_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'umbrella_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.umbrella_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.umbrella_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_case_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.finance_case_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.finance_case_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'finance_component_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.finance_component_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.finance_component_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'reservation_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.reservation_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.reservation_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'payout_transfer_ids', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.pay_bank_transfer_id::text AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE plan_detail.pay_bank_transfer_id IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb),
    'transfer_group_keys', COALESCE((
      SELECT jsonb_agg(selected_values.value_text ORDER BY selected_values.value_text)
      FROM (
        SELECT DISTINCT plan_detail.transfer_group_key AS value_text
        FROM pg_temp._tmp_payment_correction_plan_detail AS plan_detail
        WHERE NULLIF(btrim(COALESCE(plan_detail.transfer_group_key, '')), '') IS NOT NULL
      ) AS selected_values
    ), '[]'::jsonb)
  )
  INTO v_selected_mail_scope_json;

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_plan_mail;
  CREATE TEMP TABLE _tmp_payment_correction_plan_mail ON COMMIT DROP AS
  WITH candidate_mail AS (
    SELECT
      public.mail_outbox.id,
      public.mail_outbox.type,
      public.mail_outbox."to" AS mail_to,
      public.mail_outbox.subject,
      public.mail_outbox.status::text AS status,
      public.mail_outbox.created_at_utc,
      public.mail_outbox.sent_at,
      public.mail_outbox.failed_at,
      public.mail_outbox.reference,
      public.mail_outbox.recipient_kind,
      public.mail_outbox.recipient_id,
      public.mail_outbox.context_kind,
      public.mail_outbox.context_id,
      public.mail_outbox.email_type,
      COALESCE(public.mail_outbox.payment_scope_json, '{}'::jsonb) AS payment_scope_json
    FROM public.mail_outbox
    WHERE upper(btrim(COALESCE(public.mail_outbox.status::text, ''))) IN ('QUEUED', 'SENT')
      AND lower(concat_ws('|', public.mail_outbox.type, public.mail_outbox.email_type, public.mail_outbox.context_kind, public.mail_outbox.reference, COALESCE(public.mail_outbox.payment_scope_json::text, '{}'))) LIKE ANY (
        ARRAY['%remittance%', '%payout%', '%pay_batch%', '%finance_payout%']
      )
  ), matched_mail AS (
    SELECT
      candidate_mail.id,
      candidate_mail.type,
      candidate_mail.mail_to,
      candidate_mail.subject,
      candidate_mail.status,
      candidate_mail.created_at_utc,
      candidate_mail.sent_at,
      candidate_mail.failed_at,
      candidate_mail.reference,
      candidate_mail.recipient_kind,
      candidate_mail.recipient_id,
      candidate_mail.context_kind,
      candidate_mail.context_id,
      candidate_mail.email_type,
      candidate_mail.payment_scope_json,
      mail_match.match_result
    FROM candidate_mail
    CROSS JOIN LATERAL (
      SELECT public._pay_payment_correction_mail_scope_match(
        candidate_mail.id,
        p_pay_batch_id,
        p_selection_json,
        v_selected_mail_scope_json,
        false
      ) AS match_result
    ) AS mail_match
  )
  SELECT
    matched_mail.id,
    matched_mail.type,
    matched_mail.mail_to,
    matched_mail.subject,
    matched_mail.status,
    matched_mail.created_at_utc,
    matched_mail.sent_at,
    matched_mail.failed_at,
    matched_mail.reference,
    matched_mail.recipient_kind,
    matched_mail.recipient_id,
    matched_mail.context_kind,
    matched_mail.context_id,
    matched_mail.email_type,
    matched_mail.payment_scope_json,
    COALESCE(matched_mail.match_result->>'match_kind', 'NONE') AS scope_match,
    COALESCE(matched_mail.match_result->>'match_confidence', 'NONE') AS match_confidence,
    COALESCE(NULLIF(matched_mail.match_result->>'safe_to_cancel', '')::boolean, false) AS safe_to_cancel,
    COALESCE(NULLIF(matched_mail.match_result->>'requires_review', '')::boolean, false) AS requires_review,
    COALESCE(matched_mail.match_result->>'reason', 'NO_SCOPE_MATCH') AS match_reason,
    matched_mail.match_result AS match_result
  FROM matched_mail
  WHERE COALESCE(NULLIF(matched_mail.match_result->>'matched', '')::boolean, false);

  SELECT
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'SENT'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    )::integer,
    count(*) FILTER (
      WHERE COALESCE(plan_mail.requires_review, false)
    )::integer,
    count(*) FILTER (
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.requires_review, false)
    )::integer
  INTO
    v_queued_unsent_count,
    v_sent_notice_count,
    v_mail_legacy_review_count,
    v_mail_legacy_queued_review_count
  FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail;

  IF v_mail_legacy_queued_review_count > 0 THEN
    v_hard_blockers := v_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'MAIL_SCOPE_LEGACY_BROAD_MATCH_REQUIRES_REVIEW',
      'message', 'One or more queued payment notices only match the selected payment scope by broad legacy candidate, umbrella, recipient, or reference data. Manual review is required before applying this correction.',
      'queued_notice_count', v_mail_legacy_queued_review_count
    ));
  ELSIF v_mail_legacy_review_count > 0 THEN
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'MAIL_SCOPE_LEGACY_BROAD_MATCH_REQUIRES_REVIEW',
      'message', 'One or more payment notices only match the selected payment scope by broad legacy candidate, umbrella, recipient, or reference data and require review.',
      'notice_count', v_mail_legacy_review_count
    ));
  END IF;

  v_communication_effects := jsonb_build_object(
    'queued_unsent_to_cancel', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb)
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'QUEUED'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    ), '[]'::jsonb),
    'legacy_broad_matches_requiring_review', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'status', plan_mail.status,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb)
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE COALESCE(plan_mail.requires_review, false)
        AND COALESCE(plan_mail.safe_to_cancel, false) = false
    ), '[]'::jsonb),
    'sent_to_leave_as_audit', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'mail_outbox_id', plan_mail.id,
        'scope_match', plan_mail.scope_match,
        'match_confidence', plan_mail.match_confidence,
        'safe_to_cancel', plan_mail.safe_to_cancel,
        'requires_review', plan_mail.requires_review,
        'reason', plan_mail.match_reason,
        'type', plan_mail.type,
        'to', plan_mail.mail_to,
        'subject', plan_mail.subject,
        'recipient_kind', plan_mail.recipient_kind,
        'recipient_id', plan_mail.recipient_id,
        'context_kind', plan_mail.context_kind,
        'context_id', plan_mail.context_id,
        'reference', plan_mail.reference,
        'payment_scope_json', COALESCE(plan_mail.payment_scope_json, '{}'::jsonb),
        'sent_at', plan_mail.sent_at
      ) ORDER BY plan_mail.created_at_utc, plan_mail.id)
      FROM pg_temp._tmp_payment_correction_plan_mail AS plan_mail
      WHERE upper(btrim(COALESCE(plan_mail.status, ''))) = 'SENT'
        AND COALESCE(plan_mail.safe_to_cancel, false)
        AND (
          plan_mail.match_confidence = 'EXACT'
          OR plan_mail.scope_match = 'WHOLE_BATCH'
        )
    ), '[]'::jsonb),
    'external_correction_notice', false,
    'admin_notice_required', true,
    'queued_unsent_count', v_queued_unsent_count,
    'sent_notice_count', v_sent_notice_count,
    'legacy_broad_review_count', v_mail_legacy_review_count,
    'legacy_broad_queued_review_count', v_mail_legacy_queued_review_count,
    'selected_scope_json', v_selected_mail_scope_json
  );

  v_work_item_count := CASE
    WHEN v_selected_transfer_count > 0
      AND v_recommended_action = 'NO_MONEY_UNWIND_AND_RECALCULATE'
      THEN v_selected_transfer_count
    WHEN v_selected_candidate_count > 0
      THEN v_selected_candidate_count
    ELSE v_selected_item_count
  END;

  v_large_correction := jsonb_build_object(
    'large_correction', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
    'threshold', v_large_correction_threshold,
    'work_item_count', COALESCE(v_work_item_count, 0),
    'recommended_chunk_size', v_recommended_chunk_size
  );

  v_work_expansion_plan := jsonb_build_object(
    'recommended_action', v_recommended_action,
    'work_kind', NULL::text,
    'work_unit', CASE
      WHEN v_selected_transfer_count > 0 THEN 'TRANSFER'
      WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE'
      ELSE 'ITEM'
    END,
    'work_item_count', COALESCE(v_work_item_count, 0),
    'process_synchronously', COALESCE(v_work_item_count, 0) <= v_large_correction_threshold,
    'recommended_chunk_size', v_recommended_chunk_size,
    'requires_work_queue', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
    'selected_pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
    'selected_selection_hash', v_selected_selection_hash,
    'chunking_plan', jsonb_build_object(
      'default_limit', v_recommended_chunk_size,
      'hard_cap', 100,
      'requires_chunking', COALESCE(v_work_item_count, 0) > v_large_correction_threshold
    )
  );

  v_selection_summary := jsonb_build_object(
    'scope_type', upper(nullif(btrim(COALESCE(p_selection_json->>'scope_type', '')), '')),
    'selected_pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
    'selected_selection_hash', v_selected_selection_hash,
    'selection_filters_applied', v_selection_filters_applied,
    'selected_item_count', v_selected_item_count,
    'selected_candidate_count', v_selected_candidate_count,
    'selected_transfer_count', v_selected_transfer_count,
    'selected_umbrella_count', v_selected_umbrella_count,
    'key_resolution_failure_count', v_key_resolution_failure_count,
    'already_corrected_count', v_already_corrected_count,
    'voided_count', v_voided_count,
    'pay_channel_change_count', v_pay_channel_change_count,
    'umbrella_change_count', v_umbrella_change_count,
    'gross_channel_sensitive_item_count', v_gross_channel_sensitive_item_count,
    'net_fixed_finance_item_count', v_net_fixed_finance_item_count
  );

  v_can_apply := (
    v_recommended_action IN ('PRE_PROVIDER_CANCEL_AND_RECALCULATE', 'NO_MONEY_UNWIND_AND_RECALCULATE')
    AND v_classification NOT IN ('AMBIGUOUS_REVIEW_REQUIRED', 'PAID_OR_SETTLED', 'PROVIDER_SUBMITTED_PENDING', 'PROVIDER_OUTCOME_UNKNOWN', 'PROVIDER_OUTAGE_RETRY_LATER')
    AND jsonb_array_length(v_hard_blockers) = 0
    AND v_selected_item_count > 0
    AND NOT v_suggested_resolution_required
  );

  v_retry_scope_signature := md5(jsonb_build_object(
    'pay_batch_id', p_pay_batch_id::text,
    'selection_hash', COALESCE(v_selected_selection_hash, 'NO_SELECTED_ITEMS'),
    'classification', v_classification,
    'recommended_action', v_recommended_action,
    'pay_channel_scope', COALESCE(p_selection_json->>'pay_channel_scope', p_selection_json->>'pay_channel', 'ALL'),
    'retry_contract', 'RETRY_UNSENT_PAYMENTS'
  )::text);

  v_retry_status_label := 'Bank unavailable — unsent payments can be retried';
  v_retry_button_label := 'Retry unsent payments';
  v_retry_running_label := 'Retrying unsent payments';
  v_recovery_action_label := 'Recover overpayment in next pay run';

  IF v_recommended_action = 'RETRY_PROVIDER_LATER'
     AND v_classification = 'PROVIDER_OUTAGE_RETRY_LATER'
     AND jsonb_array_length(v_hard_blockers) = 0
     AND v_selected_item_count > 0 THEN
    v_retry_eligible_count := CASE
      WHEN COALESCE(v_selected_transfer_count, 0) > 0 THEN v_selected_transfer_count
      WHEN COALESCE(v_selected_candidate_count, 0) > 0 THEN v_selected_candidate_count
      ELSE v_selected_item_count
    END;
    v_retry_ineligible_count := 0;
    v_retry_eligible_scope_json := jsonb_build_object(
      'scope_type', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''), 'BATCH'),
      'pay_batch_id', p_pay_batch_id::text,
      'retry_scope_signature', v_retry_scope_signature,
      'pay_batch_item_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_item_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_candidate_ids', '[]'::jsonb),
      'candidate_ids', COALESCE(v_selected_mail_scope_json->'candidate_ids', '[]'::jsonb),
      'pay_bank_transfer_ids', COALESCE(v_selected_mail_scope_json->'pay_bank_transfer_ids', '[]'::jsonb),
      'transfer_group_keys', COALESCE(v_selected_mail_scope_json->'transfer_group_keys', '[]'::jsonb),
      'reason', 'Backend-confirmed provider request was not sent; eligible for Retry unsent payments.'
    );
  ELSE
    v_retry_eligible_count := 0;
    v_retry_ineligible_count := CASE
      WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN GREATEST(COALESCE(v_selected_transfer_count, 0), COALESCE(v_selected_candidate_count, 0), COALESCE(v_selected_item_count, 0))
      ELSE 0
    END;
    v_retry_eligible_scope_json := jsonb_build_object(
      'scope_type', COALESCE(NULLIF(btrim(COALESCE(p_selection_json->>'scope_type', '')), ''), 'BATCH'),
      'pay_batch_id', p_pay_batch_id::text,
      'retry_scope_signature', v_retry_scope_signature,
      'eligible', false
    );
    IF v_recommended_action = 'RETRY_PROVIDER_LATER' THEN
      v_retry_ineligible_summary_json := jsonb_build_array(jsonb_build_object(
        'code', 'RETRY_UNSENT_PAYMENTS_NOT_CURRENTLY_ELIGIBLE',
        'message', 'No selected payment scope is currently confirmed as unsent and retry-safe.',
        'classification', v_classification,
        'recommended_action', v_recommended_action
      ));
    END IF;
  END IF;

  SELECT operation_rows.id,
         operation_rows.status
  INTO v_retry_operation_id,
       v_retry_operation_status
  FROM public.banking_pay_operations AS operation_rows
  WHERE operation_rows.pay_batch_id = p_pay_batch_id
    AND upper(btrim(COALESCE(operation_rows.operation_type, ''))) = 'PAYMENT_RETRY_BLOCKED_FUNDS'
    AND upper(btrim(COALESCE(operation_rows.status, ''))) NOT IN ('COMPLETED', 'COMPLETE', 'SUCCEEDED', 'SUCCESS', 'FAILED', 'FAILED_FINAL', 'CANCELLED', 'CANCELED')
    AND (
      COALESCE(operation_rows.input_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(operation_rows.progress_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(operation_rows.result_json->>'retry_scope_signature', '') = v_retry_scope_signature
      OR COALESCE(v_retry_eligible_count, 0) > 0
    )
  ORDER BY operation_rows.created_at_utc DESC NULLS LAST, operation_rows.id DESC
  LIMIT 1;

  v_retry_in_progress := v_retry_operation_id IS NOT NULL;
  v_retry_already_in_progress := v_retry_in_progress;
  v_retry_button_visible := COALESCE(v_retry_eligible_count, 0) > 0 AND COALESCE(v_retry_in_progress, false) IS NOT TRUE;

  IF COALESCE(v_retry_in_progress, false) THEN
    v_retry_button_disabled_reason := 'Retry already in progress';
  ELSIF COALESCE(v_retry_eligible_count, 0) <= 0 AND v_recommended_action = 'RETRY_PROVIDER_LATER' THEN
    v_retry_button_disabled_reason := 'No unsent payments available to retry';
  ELSE
    v_retry_button_disabled_reason := NULL::text;
  END IF;

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_PLAN_RESULT',
    jsonb_build_object(
      'pay_batch_id', p_pay_batch_id,
      'classification', v_classification,
      'recommended_action', v_recommended_action,
      'can_apply', v_can_apply,
      'selected_item_count', v_selected_item_count,
      'selected_candidate_count', v_selected_candidate_count,
      'selected_transfer_count', v_selected_transfer_count,
      'hard_blocker_count', jsonb_array_length(v_hard_blockers),
      'warning_count', jsonb_array_length(v_warnings),
      'suggested_resolution_required', v_suggested_resolution_required,
      'umbrella_change_count', v_umbrella_change_count,
      'work_item_count', v_work_item_count,
      'large_correction', COALESCE(v_work_item_count, 0) > v_large_correction_threshold,
      'retry_eligible_count', v_retry_eligible_count,
      'retry_in_progress', v_retry_in_progress,
      'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END
    ),
    'pay_payment_correction',
    v_subject_id,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  RETURN jsonb_build_object(
    'ok', true,
    'pay_batch_id', p_pay_batch_id,
    'classification', v_classification,
    'recommended_action', v_recommended_action,
    'user_facing_recommended_action', v_recommended_action,
    'next_step', CASE WHEN v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP' THEN 'AMEND_TIMESHEET_AND_RECALCULATE' ELSE NULL::text END,
    'next_step_label', CASE WHEN v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP' THEN 'Amend timesheets and recalculate' ELSE NULL::text END,
    'display_only_action', v_recommended_action = 'VIEW_RECALCULATE_NEXT_STEP',
    'action_label', CASE WHEN v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN v_recovery_action_label WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_button_label ELSE NULL::text END,
    'status_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_status_label ELSE NULL::text END,
    'button_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_button_label ELSE NULL::text END,
    'running_label', CASE WHEN v_recommended_action = 'RETRY_PROVIDER_LATER' THEN v_retry_running_label ELSE NULL::text END,
    'recovery_action_label', CASE WHEN v_recommended_action = 'AMEND_AND_RECOVER_OVERPAYMENT' THEN v_recovery_action_label ELSE NULL::text END,
    'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
    'retry_ineligible_count', COALESCE(v_retry_ineligible_count, 0),
    'retry_eligible_scope_json', COALESCE(v_retry_eligible_scope_json, '{}'::jsonb),
    'retry_ineligible_summary_json', COALESCE(v_retry_ineligible_summary_json, '[]'::jsonb),
    'retry_in_progress', COALESCE(v_retry_in_progress, false),
    'retry_already_in_progress', COALESCE(v_retry_already_in_progress, false),
    'retry_operation_id', CASE WHEN v_retry_operation_id IS NULL THEN NULL ELSE v_retry_operation_id::text END,
    'retry_operation_status', v_retry_operation_status,
    'retry_button_visible', COALESCE(v_retry_button_visible, false),
    'retry_button_disabled_reason', v_retry_button_disabled_reason,
    'retry_scope_signature', v_retry_scope_signature,
    'payment_lifecycle_state', v_classification,
    'provider_failure_reason_code', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_code'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_code}'), '')),
    'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_group'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_group}'), '')),
    'provider_failure_reason_label', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_label'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_label}'), '')),
    'alert_candidate_kind', NULLIF(btrim(COALESCE(v_classification_result->>'alert_candidate_kind', '')), ''),
    'alert_candidate_severity', NULLIF(btrim(COALESCE(v_classification_result->>'alert_candidate_severity', '')), ''),
    'alert_candidate_is_success_only', COALESCE(NULLIF(v_classification_result->>'alert_candidate_is_success_only', '')::boolean, false),
    'live_status_signature', COALESCE(NULLIF(btrim(v_classification_result->>'live_status_signature'), ''), NULLIF(btrim(v_classification_result->>'status_update_signature'), ''), md5(jsonb_build_object('pay_batch_id', p_pay_batch_id::text, 'classification', v_classification, 'recommended_action', v_recommended_action, 'selection_hash', COALESCE(v_selected_selection_hash, ''))::text)),
    'status_update_signature', COALESCE(NULLIF(btrim(v_classification_result->>'status_update_signature'), ''), NULLIF(btrim(v_classification_result->>'live_status_signature'), ''), md5(jsonb_build_object('pay_batch_id', p_pay_batch_id::text, 'classification', v_classification, 'recommended_action', v_recommended_action, 'selection_hash', COALESCE(v_selected_selection_hash, ''))::text)),
    'can_apply', v_can_apply,
    'hard_blockers', v_hard_blockers,
    'warnings', v_warnings,
    'selection', v_selection_summary,
    'affected_candidates', v_affected_candidates,
    'affected_transfers', v_affected_transfers,
    'affected_umbrellas', v_affected_umbrellas,
    'affected_items', v_affected_items,
    'affected_finance_cases', v_affected_finance_cases,
    'communication_effects', v_communication_effects,
    'suggested_resolution_required', v_suggested_resolution_required,
    'suggested_resolution', v_suggested_resolution,
    'amounts', v_amounts
  ) || jsonb_build_object(
    'draft_interference', v_draft_interference,
    'large_correction', v_large_correction,
    'work_expansion_plan', v_work_expansion_plan,
    'chunking_plan', COALESCE(v_work_expansion_plan->'chunking_plan', '{}'::jsonb),
    'full_payment_scope', COALESCE(v_classification_result->'resolved_full_payment_scope_json', v_classification_result->'full_payment_scope', '{}'::jsonb),
    'resolved_full_payment_scope_json', COALESCE(v_classification_result->'resolved_full_payment_scope_json', v_classification_result->'full_payment_scope', '{}'::jsonb),
    'finance_scope', COALESCE(v_classification_result->'finance_scope_json', v_classification_result->'finance_scope', '{}'::jsonb),
    'finance_scope_json', COALESCE(v_classification_result->'finance_scope_json', v_classification_result->'finance_scope', '{}'::jsonb),
    'manual_adjustment_carry_forward_required', COALESCE(NULLIF(v_classification_result->>'manual_adjustment_carry_forward_required', '')::boolean, false),
    'manual_adjustments_to_carry_forward', COALESCE(v_classification_result->'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'safe_carry_forward_items', COALESCE(v_classification_result->'manual_adjustments_to_carry_forward', '[]'::jsonb),
    'manual_adjustments_carried_forward_existing', COALESCE(v_classification_result->'manual_adjustments_carried_forward_existing', '[]'::jsonb),
    'ambiguous_manual_adjustment_blockers', COALESCE(v_classification_result->'carry_forward_blockers', '[]'::jsonb),
    'provider_evidence', jsonb_build_object(
      'pending_provider_evidence_json', COALESCE(v_classification_result->'pending_provider_evidence_json', '{}'::jsonb),
      'terminal_no_money_evidence_json', COALESCE(v_classification_result->'terminal_no_money_evidence_json', '{}'::jsonb),
      'provider_outcome_unknown_evidence_json', COALESCE(v_classification_result->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
      'provider_webhook_evidence_json', COALESCE(v_classification_result->'provider_webhook_evidence_json', '{}'::jsonb),
      'provider_failure_reason_code', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_code'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_code}'), '')),
      'provider_failure_reason_group', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_group'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_group}'), '')),
      'provider_failure_reason_label', COALESCE(NULLIF(btrim(v_classification_result->>'provider_failure_reason_label'), ''), NULLIF(btrim(v_classification_result#>>'{provider_evidence,provider_failure_reason_label}'), ''))
    ),
    'provider_webhook_evidence_json', COALESCE(v_classification_result->'provider_webhook_evidence_json', '{}'::jsonb),
    'provider_outcome_unknown_evidence_json', COALESCE(v_classification_result->'provider_outcome_unknown_evidence_json', '{}'::jsonb),
    'paid_evidence', COALESCE(v_classification_result->'blocking_paid_evidence_json', '{}'::jsonb),
    'race_submission_blockers', COALESCE((
      SELECT jsonb_agg(race_blockers.blocker_value ORDER BY race_blockers.blocker_ordinal)
      FROM jsonb_array_elements(COALESCE(v_classification_result->'blockers', '[]'::jsonb)) WITH ORDINALITY AS race_blockers(blocker_value, blocker_ordinal)
      WHERE COALESCE(race_blockers.blocker_value->>'code', '') IN (
        'PROVIDER_SUBMISSION_ALREADY_CLAIMED',
        'PROVIDER_SUBMISSION_IN_PROGRESS',
        'CANCELLATION_RACED_WITH_PROVIDER_SUBMIT'
      )
    ), '[]'::jsonb),
    'movement_classification_detail', v_classification_result,
    'live_refresh_scope', jsonb_build_object(
      'pay_batch_id', p_pay_batch_id::text,
      'classification', v_classification,
      'recommended_action', v_recommended_action,
      'selected_selection_hash', v_selected_selection_hash,
      'pay_batch_item_ids', to_jsonb(v_selected_pay_batch_item_ids),
      'pay_bank_transfer_ids', COALESCE(v_selected_mail_scope_json->'pay_bank_transfer_ids', '[]'::jsonb),
      'pay_batch_candidate_ids', COALESCE(v_selected_mail_scope_json->'pay_batch_candidate_ids', '[]'::jsonb),
      'candidate_ids', COALESCE(v_selected_mail_scope_json->'candidate_ids', '[]'::jsonb),
      'finance_case_ids', COALESCE(v_selected_mail_scope_json->'finance_case_ids', '[]'::jsonb),
      'finance_component_ids', COALESCE(v_selected_mail_scope_json->'finance_component_ids', '[]'::jsonb),
      'reservation_ids', COALESCE(v_selected_mail_scope_json->'reservation_ids', '[]'::jsonb),
      'retry_scope_signature', v_retry_scope_signature,
      'retry_eligible_count', COALESCE(v_retry_eligible_count, 0),
      'retry_in_progress', COALESCE(v_retry_in_progress, false)
    ),
    'batch', jsonb_build_object(
      'status', v_batch_status,
      'pay_date', v_batch_pay_date,
      'authoritative_payment_date', v_batch_authoritative_payment_date,
      'effective_pay_date', v_effective_pay_date,
      'created_at_utc', v_batch_created_at_utc,
      'execution_commit_state', v_batch_execution_commit_state,
      'execution_commit_ref', v_batch_execution_commit_ref
    )
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_PLAN_ERROR',
      jsonb_build_object(
        'pay_batch_id', p_pay_batch_id,
        'selection_json', p_selection_json,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_pay_batch_id::text, 'NO_BATCH_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;




CREATE OR REPLACE FUNCTION public.pay_payment_correction_authorise(
  p_correction_request_id uuid,
  p_actor_user_id uuid,
  p_action text,
  p_note text DEFAULT NULL::text
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.pay_payment_correction_requests%rowtype;
  v_before_request jsonb;
  v_after_request jsonb;
  v_action text;
  v_actor_exists boolean := false;
  v_actor_active boolean := false;
  v_actor_payment_authoriser boolean := false;
  v_actor_payment_golden_key boolean := false;
  v_duplicate_authorisation boolean := false;
  v_new_approved_count integer := 0;
  v_fresh_plan jsonb := '{}'::jsonb;
  v_fresh_classification text := 'AMBIGUOUS_REVIEW_REQUIRED';
  v_fresh_plan_can_apply boolean := false;
  v_fresh_hard_blockers jsonb := '[]'::jsonb;
  v_effective_hard_blockers jsonb := '[]'::jsonb;
  v_suggested_resolution_required boolean := false;
  v_accepted_resolution_supplied boolean := false;
  v_accepted_resolution_is_stale boolean := false;
  v_fresh_plan_material_json jsonb;
  v_fresh_plan_hash text;
  v_block_reason text;
  v_expand_result jsonb := NULL::jsonb;
  v_work_item_counts jsonb := '{}'::jsonb;
  v_plan_changed_fields jsonb := '[]'::jsonb;
  v_plan_stale_detail jsonb := '{}'::jsonb;
  v_stored_effective_blocker_codes text := '';
  v_fresh_effective_blocker_codes text := '';
  v_finance_resolution_validation jsonb := NULL::jsonb;
  v_finance_resolution_blocker jsonb := NULL::jsonb;
  v_immediate_process_result jsonb := NULL::jsonb;
  v_total_work_item_count integer := 0;
  v_pending_work_item_count integer := 0;
BEGIN
  v_action := upper(nullif(btrim(COALESCE(p_action, '')), ''));

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_AUTHORISE_BEGIN',
    jsonb_build_object(
      'correction_request_id', p_correction_request_id,
      'actor_user_id', p_actor_user_id,
      'action', v_action
    ),
    'pay_payment_correction',
    COALESCE(p_correction_request_id::text, 'NO_CORRECTION_REQUEST_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_correction_request_id IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'CORRECTION_REQUEST_ID_REQUIRED')::text;
  END IF;

  IF p_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'ACTOR_USER_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACTOR_USER_ID_REQUIRED',
              'correction_request_id', p_correction_request_id
            )::text;
  END IF;

  IF v_action NOT IN ('AUTHORISE', 'USE_GOLDEN_KEY', 'REJECT', 'CANCEL') THEN
    RAISE EXCEPTION 'UNSUPPORTED_PAYMENT_CORRECTION_AUTHORISE_ACTION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'UNSUPPORTED_PAYMENT_CORRECTION_AUTHORISE_ACTION',
              'correction_request_id', p_correction_request_id,
              'action', p_action,
              'supported_actions', jsonb_build_array('AUTHORISE', 'USE_GOLDEN_KEY', 'REJECT', 'CANCEL')
            )::text;
  END IF;

  SELECT
    true,
    COALESCE(public.tms_users.is_active, false),
    COALESCE(public.tms_users.payment_authoriser, false),
    COALESCE(public.tms_users.payment_golden_key, false)
  INTO
    v_actor_exists,
    v_actor_active,
    v_actor_payment_authoriser,
    v_actor_payment_golden_key
  FROM public.tms_users
  WHERE public.tms_users.id = p_actor_user_id;

  IF NOT COALESCE(v_actor_exists, false) THEN
    RAISE EXCEPTION 'ACTOR_USER_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACTOR_USER_NOT_FOUND',
              'actor_user_id', p_actor_user_id
            )::text;
  END IF;

  IF NOT COALESCE(v_actor_active, false) THEN
    RAISE EXCEPTION 'ACTOR_USER_INACTIVE'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACTOR_USER_INACTIVE',
              'actor_user_id', p_actor_user_id
            )::text;
  END IF;

  IF v_action = 'AUTHORISE' AND NOT COALESCE(v_actor_payment_authoriser, false) THEN
    RAISE EXCEPTION 'ACTOR_IS_NOT_PAYMENT_AUTHORISER'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACTOR_IS_NOT_PAYMENT_AUTHORISER',
              'actor_user_id', p_actor_user_id,
              'correction_request_id', p_correction_request_id
            )::text;
  END IF;

  IF v_action = 'USE_GOLDEN_KEY' AND NOT COALESCE(v_actor_payment_golden_key, false) THEN
    RAISE EXCEPTION 'ACTOR_DOES_NOT_HAVE_PAYMENT_GOLDEN_KEY'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'ACTOR_DOES_NOT_HAVE_PAYMENT_GOLDEN_KEY',
              'actor_user_id', p_actor_user_id,
              'correction_request_id', p_correction_request_id
            )::text;
  END IF;

  SELECT public.pay_payment_correction_requests.*
  INTO v_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.id = p_correction_request_id
  FOR UPDATE;

  IF v_request.id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND',
              'correction_request_id', p_correction_request_id
            )::text;
  END IF;

  IF v_request.status IN ('APPLIED', 'APPLIED_WITH_BLOCKERS', 'FAILED', 'REJECTED', 'CANCELLED') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ALREADY_TERMINAL'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_ALREADY_TERMINAL',
              'correction_request_id', p_correction_request_id,
              'status', v_request.status
            )::text;
  END IF;

  v_before_request := to_jsonb(v_request);

  IF v_action = 'REJECT' THEN
    UPDATE public.pay_payment_correction_requests
    SET
      status = 'REJECTED',
      updated_at_utc = now()
    WHERE public.pay_payment_correction_requests.id = p_correction_request_id
    RETURNING public.pay_payment_correction_requests.* INTO v_request;

    v_after_request := to_jsonb(v_request);

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    )
    VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      'REJECT',
      now(),
      NULLIF(btrim(COALESCE(p_note, '')), ''),
      v_before_request,
      v_after_request,
      jsonb_build_object('previous_status', v_before_request->>'status', 'new_status', v_request.status)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'action', v_action,
      'status', v_request.status,
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'expanded', false,
      'progress', '{}'::jsonb
    );
  END IF;

  IF v_action = 'CANCEL' THEN
    UPDATE public.pay_payment_correction_work_items
    SET
      status = 'CANCELLED',
      locked_at_utc = NULL,
      locked_by = NULL,
      result_json = COALESCE(public.pay_payment_correction_work_items.result_json, '{}'::jsonb) || jsonb_build_object(
        'cancelled_by_user_id', p_actor_user_id,
        'cancelled_at_utc', now(),
        'cancel_note', NULLIF(btrim(COALESCE(p_note, '')), '')
      )
    WHERE public.pay_payment_correction_work_items.correction_request_id = p_correction_request_id
      AND public.pay_payment_correction_work_items.status = 'PENDING';

    UPDATE public.pay_payment_correction_requests
    SET
      status = 'CANCELLED',
      cancelled_at_utc = COALESCE(public.pay_payment_correction_requests.cancelled_at_utc, now()),
      updated_at_utc = now()
    WHERE public.pay_payment_correction_requests.id = p_correction_request_id
    RETURNING public.pay_payment_correction_requests.* INTO v_request;

    v_after_request := to_jsonb(v_request);

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    )
    VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      'CANCEL',
      now(),
      NULLIF(btrim(COALESCE(p_note, '')), ''),
      v_before_request,
      v_after_request,
      jsonb_build_object('previous_status', v_before_request->>'status', 'new_status', v_request.status)
    );

    RETURN jsonb_build_object(
      'ok', true,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'action', v_action,
      'status', v_request.status,
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'expanded', false,
      'progress', '{}'::jsonb
    );
  END IF;

  IF v_request.status NOT IN ('REQUESTED', 'AWAITING_AUTHORISATION', 'AUTHORISED', 'BLOCKED') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISABLE_IN_CURRENT_STATUS'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISABLE_IN_CURRENT_STATUS',
              'correction_request_id', p_correction_request_id,
              'status', v_request.status
            )::text;
  END IF;

  IF v_action = 'AUTHORISE' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.pay_payment_correction_actions AS existing_action
      WHERE existing_action.correction_request_id = p_correction_request_id
        AND existing_action.actor_user_id = p_actor_user_id
        AND existing_action.action = 'AUTHORISE'
    )
    INTO v_duplicate_authorisation;

    IF COALESCE(v_duplicate_authorisation, false) THEN
      RAISE EXCEPTION 'PAYMENT_CORRECTION_DUPLICATE_AUTHORISATION'
        USING ERRCODE = 'P0001',
              DETAIL = jsonb_build_object(
                'code', 'PAYMENT_CORRECTION_DUPLICATE_AUTHORISATION',
                'correction_request_id', p_correction_request_id,
                'actor_user_id', p_actor_user_id
              )::text;
    END IF;

    v_new_approved_count := LEAST(COALESCE(v_request.approved_count, 0) + 1, GREATEST(COALESCE(v_request.required_quantity, 1), 1));

    UPDATE public.pay_payment_correction_requests
    SET
      approved_count = v_new_approved_count,
      status = CASE
        WHEN v_new_approved_count >= GREATEST(COALESCE(public.pay_payment_correction_requests.required_quantity, 1), 1) THEN 'AUTHORISED'
        ELSE 'AWAITING_AUTHORISATION'
      END,
      authorised_at_utc = CASE
        WHEN v_new_approved_count >= GREATEST(COALESCE(public.pay_payment_correction_requests.required_quantity, 1), 1)
          THEN COALESCE(public.pay_payment_correction_requests.authorised_at_utc, now())
        ELSE public.pay_payment_correction_requests.authorised_at_utc
      END,
      updated_at_utc = now()
    WHERE public.pay_payment_correction_requests.id = p_correction_request_id
    RETURNING public.pay_payment_correction_requests.* INTO v_request;

    v_after_request := to_jsonb(v_request);

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    )
    VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      'AUTHORISE',
      now(),
      NULLIF(btrim(COALESCE(p_note, '')), ''),
      v_before_request,
      v_after_request,
      jsonb_build_object(
        'approved_count_before', COALESCE((v_before_request->>'approved_count')::integer, 0),
        'approved_count_after', v_request.approved_count,
        'required_quantity', v_request.required_quantity
      )
    );

    IF v_request.approved_count < GREATEST(COALESCE(v_request.required_quantity, 1), 1) THEN
      RETURN jsonb_build_object(
        'ok', true,
        'correction_request_id', v_request.id,
        'pay_batch_id', v_request.pay_batch_id,
        'action', v_action,
        'status', v_request.status,
        'approved_count', v_request.approved_count,
        'required_quantity', v_request.required_quantity,
        'authorised', false,
        'expanded', false,
        'progress', '{}'::jsonb
      );
    END IF;
  END IF;

  IF v_action = 'USE_GOLDEN_KEY' THEN
    UPDATE public.pay_payment_correction_requests
    SET
      golden_key_used = true,
      golden_key_user_id = p_actor_user_id,
      approved_count = GREATEST(COALESCE(public.pay_payment_correction_requests.required_quantity, 1), 1),
      status = 'AUTHORISED',
      authorised_at_utc = COALESCE(public.pay_payment_correction_requests.authorised_at_utc, now()),
      updated_at_utc = now()
    WHERE public.pay_payment_correction_requests.id = p_correction_request_id
    RETURNING public.pay_payment_correction_requests.* INTO v_request;

    v_after_request := to_jsonb(v_request);

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    )
    VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      'USE_GOLDEN_KEY',
      now(),
      NULLIF(btrim(COALESCE(p_note, '')), ''),
      v_before_request,
      v_after_request,
      jsonb_build_object(
        'required_quantity', v_request.required_quantity,
        'golden_key_user_id', p_actor_user_id
      )
    );
  END IF;

  v_fresh_plan := public.pay_payment_correction_plan(
    v_request.pay_batch_id,
    v_request.selection_json,
    p_actor_user_id
  );

  v_fresh_classification := COALESCE(v_fresh_plan->>'classification', 'AMBIGUOUS_REVIEW_REQUIRED');
  v_fresh_plan_can_apply := COALESCE((v_fresh_plan->>'can_apply')::boolean, false);
  v_fresh_hard_blockers := COALESCE(v_fresh_plan->'hard_blockers', '[]'::jsonb);
  v_suggested_resolution_required := COALESCE((v_fresh_plan->>'suggested_resolution_required')::boolean, false);
  v_accepted_resolution_supplied := v_request.accepted_resolution_json IS NOT NULL;

  SELECT COALESCE(jsonb_agg(blocker_elements.blocker_value ORDER BY blocker_elements.blocker_ordinal), '[]'::jsonb)
  INTO v_effective_hard_blockers
  FROM jsonb_array_elements(v_fresh_hard_blockers) WITH ORDINALITY AS blocker_elements(blocker_value, blocker_ordinal)
  WHERE NOT (
    v_suggested_resolution_required
    AND v_accepted_resolution_supplied
    AND COALESCE(blocker_elements.blocker_value->>'code', '') = 'SUGGESTED_RESOLUTION_REQUIRED'
  );

  v_accepted_resolution_is_stale := v_request.accepted_resolution_json IS NOT NULL
    AND (
      lower(COALESCE(v_request.accepted_resolution_json->>'is_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(v_request.accepted_resolution_json->>'stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(v_request.accepted_resolution_json->>'resolution_stale', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(v_request.accepted_resolution_json#>>'{validation,is_stale}', 'false')) IN ('true', 't', 'yes', 'y', '1')
      OR lower(COALESCE(v_request.accepted_resolution_json#>>'{validation,stale}', 'false')) IN ('true', 't', 'yes', 'y', '1')
    );

  IF v_accepted_resolution_is_stale THEN
    v_effective_hard_blockers := v_effective_hard_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'ACCEPTED_RESOLUTION_STALE',
      'message', 'The accepted suggested finance resolution is stale and must be regenerated before correction apply.'
    ));
  END IF;

  IF v_suggested_resolution_required AND v_accepted_resolution_supplied THEN
    v_finance_resolution_validation := public._pay_payment_correction_validate_accepted_finance_resolution(
      p_pay_batch_id => v_request.pay_batch_id,
      p_selection_json => v_request.selection_json,
      p_plan_json => v_fresh_plan,
      p_accepted_resolution_json => v_request.accepted_resolution_json,
      p_actor_user_id => p_actor_user_id
    );

    IF NOT COALESCE((v_finance_resolution_validation->>'ok')::boolean, false)
       OR NOT COALESCE((v_finance_resolution_validation->>'validated')::boolean, false) THEN
      v_finance_resolution_blocker := COALESCE(
        v_finance_resolution_validation->'blocker',
        jsonb_build_object(
          'code', 'ACCEPTED_RESOLUTION_VALIDATION_FAILED',
          'message', 'Accepted finance resolution validation failed before correction authorisation.'
        )
      );

      v_effective_hard_blockers := v_effective_hard_blockers || jsonb_build_array(v_finance_resolution_blocker);
    END IF;
  END IF;

  SELECT COALESCE(string_agg(stored_blocker_codes.blocker_code, '|' ORDER BY stored_blocker_codes.blocker_code), '')
  INTO v_stored_effective_blocker_codes
  FROM (
    SELECT DISTINCT COALESCE(NULLIF(btrim(stored_blocker.value->>'code'), ''), stored_blocker.value::text) AS blocker_code
    FROM jsonb_array_elements(COALESCE(v_request.plan_json->'hard_blockers', '[]'::jsonb)) AS stored_blocker(value)
    WHERE NOT (
      v_suggested_resolution_required
      AND v_accepted_resolution_supplied
      AND COALESCE(stored_blocker.value->>'code', '') = 'SUGGESTED_RESOLUTION_REQUIRED'
    )
  ) AS stored_blocker_codes;

  SELECT COALESCE(string_agg(fresh_blocker_codes.blocker_code, '|' ORDER BY fresh_blocker_codes.blocker_code), '')
  INTO v_fresh_effective_blocker_codes
  FROM (
    SELECT DISTINCT COALESCE(NULLIF(btrim(fresh_blocker.value->>'code'), ''), fresh_blocker.value::text) AS blocker_code
    FROM jsonb_array_elements(COALESCE(v_effective_hard_blockers, '[]'::jsonb)) AS fresh_blocker(value)
  ) AS fresh_blocker_codes;

  v_fresh_plan_material_json := jsonb_build_object(
    'classification', v_fresh_classification,
    'recommended_action', v_fresh_plan->>'recommended_action',
    'selection', COALESCE(v_fresh_plan->'selection', '{}'::jsonb),
    'amounts', COALESCE(v_fresh_plan->'amounts', '{}'::jsonb),
    'hard_blockers', v_fresh_hard_blockers,
    'effective_hard_blockers', v_effective_hard_blockers,
    'suggested_resolution_required', v_suggested_resolution_required,
    'work_expansion_plan', COALESCE(v_fresh_plan->'work_expansion_plan', '{}'::jsonb),
    'movement_classification_detail', jsonb_build_object(
      'classification', v_fresh_plan#>>'{movement_classification_detail,classification}',
      'counts', COALESCE(v_fresh_plan#>'{movement_classification_detail,counts}', '{}'::jsonb),
      'blockers', COALESCE(v_fresh_plan#>'{movement_classification_detail,blockers}', '[]'::jsonb),
      'safe_to_auto_apply', COALESCE(v_fresh_plan#>'{movement_classification_detail,safe_to_auto_apply}', 'false'::jsonb)
    )
  );

  v_fresh_plan_hash := md5(v_fresh_plan_material_json::text);

  SELECT COALESCE(jsonb_agg(plan_change.field_name ORDER BY plan_change.field_name), '[]'::jsonb)
  INTO v_plan_changed_fields
  FROM (
    VALUES
      ('amounts', COALESCE((v_request.plan_json->'amounts')::text, ''), COALESCE((v_fresh_plan->'amounts')::text, '')),
      ('classification', COALESCE(v_request.plan_json->>'classification', ''), COALESCE(v_fresh_classification, '')),
      ('effective_hard_blocker_codes', COALESCE(v_stored_effective_blocker_codes, ''), COALESCE(v_fresh_effective_blocker_codes, '')),
      ('recommended_action', COALESCE(v_request.plan_json->>'recommended_action', ''), COALESCE(v_fresh_plan->>'recommended_action', '')),
      ('selected_item_count', COALESCE(v_request.plan_json#>>'{selection,selected_item_count}', ''), COALESCE(v_fresh_plan#>>'{selection,selected_item_count}', '')),
      ('selected_selection_hash', COALESCE(v_request.plan_json#>>'{selection,selected_selection_hash}', ''), COALESCE(v_fresh_plan#>>'{selection,selected_selection_hash}', '')),
      ('suggested_resolution_required', COALESCE(v_request.plan_json->>'suggested_resolution_required', ''), COALESCE(v_suggested_resolution_required::text, '')),
      ('work_unit', COALESCE(v_request.plan_json#>>'{work_expansion_plan,work_unit}', ''), COALESCE(v_fresh_plan#>>'{work_expansion_plan,work_unit}', ''))
  ) AS plan_change(field_name, stored_value, fresh_value)
  WHERE plan_change.stored_value IS DISTINCT FROM plan_change.fresh_value;

  v_plan_stale_detail := jsonb_build_object(
    'stored_plan_hash', v_request.plan_hash,
    'fresh_plan_hash', v_fresh_plan_hash,
    'changed_fields', v_plan_changed_fields,
    'stored_summary', jsonb_build_object(
      'classification', v_request.plan_json->>'classification',
      'recommended_action', v_request.plan_json->>'recommended_action',
      'selected_item_count', v_request.plan_json#>>'{selection,selected_item_count}',
      'selected_selection_hash', v_request.plan_json#>>'{selection,selected_selection_hash}',
      'suggested_resolution_required', v_request.plan_json->>'suggested_resolution_required',
      'work_unit', v_request.plan_json#>>'{work_expansion_plan,work_unit}',
      'amounts', COALESCE(v_request.plan_json->'amounts', '{}'::jsonb),
      'hard_blockers', COALESCE(v_request.plan_json->'hard_blockers', '[]'::jsonb)
    ),
    'fresh_summary', jsonb_build_object(
      'classification', v_fresh_classification,
      'recommended_action', v_fresh_plan->>'recommended_action',
      'selected_item_count', v_fresh_plan#>>'{selection,selected_item_count}',
      'selected_selection_hash', v_fresh_plan#>>'{selection,selected_selection_hash}',
      'suggested_resolution_required', v_suggested_resolution_required,
      'work_unit', v_fresh_plan#>>'{work_expansion_plan,work_unit}',
      'amounts', COALESCE(v_fresh_plan->'amounts', '{}'::jsonb),
      'hard_blockers', v_fresh_hard_blockers,
      'effective_hard_blockers', v_effective_hard_blockers
    )
  );

  IF v_accepted_resolution_is_stale THEN
    v_block_reason := 'ACCEPTED_RESOLUTION_STALE';
  ELSIF v_finance_resolution_blocker IS NOT NULL THEN
    v_block_reason := COALESCE(NULLIF(btrim(v_finance_resolution_blocker->>'code'), ''), 'ACCEPTED_RESOLUTION_VALIDATION_FAILED');
  ELSIF jsonb_array_length(v_plan_changed_fields) > 0 THEN
    v_block_reason := 'PLAN_STALE';
  ELSIF v_fresh_classification = 'AMBIGUOUS_REVIEW_REQUIRED' THEN
    v_block_reason := 'CLASSIFICATION_AMBIGUOUS_REVIEW_REQUIRED';
  ELSIF jsonb_array_length(v_effective_hard_blockers) > 0 THEN
    v_block_reason := 'PLAN_HAS_BLOCKERS';
  ELSIF NOT v_fresh_plan_can_apply
        AND NOT (v_suggested_resolution_required AND v_accepted_resolution_supplied AND jsonb_array_length(v_effective_hard_blockers) = 0) THEN
    v_block_reason := 'PLAN_CANNOT_APPLY';
  ELSE
    v_block_reason := NULL;
  END IF;

  IF v_block_reason IS NOT NULL THEN
    v_before_request := to_jsonb(v_request);

    UPDATE public.pay_payment_correction_requests
    SET
      status = 'BLOCKED',
      updated_at_utc = now()
    WHERE public.pay_payment_correction_requests.id = p_correction_request_id
    RETURNING public.pay_payment_correction_requests.* INTO v_request;

    v_after_request := to_jsonb(v_request);

    INSERT INTO public.pay_payment_correction_actions (
      correction_request_id,
      pay_batch_id,
      actor_kind,
      actor_user_id,
      action,
      action_at_utc,
      note,
      before_json,
      after_json,
      metadata_json
    )
    VALUES (
      v_request.id,
      v_request.pay_batch_id,
      'USER',
      p_actor_user_id,
      'BLOCK',
      now(),
      v_block_reason,
      v_before_request,
      v_after_request,
      jsonb_build_object(
        'block_reason', v_block_reason,
        'stored_plan_hash', v_request.plan_hash,
        'fresh_plan_hash', v_fresh_plan_hash,
        'effective_hard_blockers', v_effective_hard_blockers,
        'fresh_classification', v_fresh_classification,
        'fresh_can_apply', v_fresh_plan_can_apply,
        'finance_resolution_validation', v_finance_resolution_validation,
        'plan_stale_detail', v_plan_stale_detail
      )
    );

    RETURN jsonb_build_object(
      'ok', false,
      'correction_request_id', v_request.id,
      'pay_batch_id', v_request.pay_batch_id,
      'action', v_action,
      'status', v_request.status,
      'block_reason', v_block_reason,
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'expanded', false,
      'fresh_plan', v_fresh_plan,
      'effective_hard_blockers', v_effective_hard_blockers,
      'stored_plan_hash', v_request.plan_hash,
      'fresh_plan_hash', v_fresh_plan_hash,
      'plan_changed_fields', v_plan_changed_fields,
      'plan_stale_detail', v_plan_stale_detail,
      'progress', '{}'::jsonb
    );
  END IF;

  v_expand_result := public.pay_payment_correction_expand_work(
    p_correction_request_id,
    p_actor_user_id
  );

  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_AUTHORISE_RESULT',
    jsonb_build_object(
      'correction_request_id', p_correction_request_id,
      'pay_batch_id', v_request.pay_batch_id,
      'action', v_action,
      'approved_count', v_request.approved_count,
      'required_quantity', v_request.required_quantity,
      'expand_result', v_expand_result,
      'immediate_process_result', v_immediate_process_result
    ),
    'pay_payment_correction',
    p_correction_request_id::text,
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  SELECT jsonb_build_object(
    'pending', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PENDING'),
    'processing', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PROCESSING'),
    'applied', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'APPLIED'),
    'skipped', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'SKIPPED'),
    'blocked', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'BLOCKED'),
    'failed_retryable', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_RETRYABLE'),
    'failed_final', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_FINAL'),
    'cancelled', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'CANCELLED'),
    'total', count(*)
  )
  INTO v_work_item_counts
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.correction_request_id = p_correction_request_id;

  v_total_work_item_count := COALESCE((v_work_item_counts->>'total')::integer, 0);
  v_pending_work_item_count := COALESCE((v_work_item_counts->>'pending')::integer, 0);

  IF v_total_work_item_count > 0
     AND v_total_work_item_count <= 50
     AND v_pending_work_item_count > 0 THEN
    v_immediate_process_result := public.pay_payment_correction_process_chunk(
      p_correction_request_id => p_correction_request_id,
      p_limit => 50,
      p_worker_id => 'correction-authorise',
      p_actor_user_id => p_actor_user_id
    );

    SELECT jsonb_build_object(
      'pending', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PENDING'),
      'processing', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PROCESSING'),
      'applied', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'APPLIED'),
      'skipped', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'SKIPPED'),
      'blocked', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'BLOCKED'),
      'failed_retryable', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_RETRYABLE'),
      'failed_final', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_FINAL'),
      'cancelled', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'CANCELLED'),
      'total', count(*)
    )
    INTO v_work_item_counts
    FROM public.pay_payment_correction_work_items
    WHERE public.pay_payment_correction_work_items.correction_request_id = p_correction_request_id;
  END IF;

  SELECT public.pay_payment_correction_requests.*
  INTO v_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.id = p_correction_request_id;

  RETURN jsonb_build_object(
    'ok', true,
    'correction_request_id', v_request.id,
    'pay_batch_id', v_request.pay_batch_id,
    'action', v_action,
    'status', v_request.status,
    'approved_count', v_request.approved_count,
    'required_quantity', v_request.required_quantity,
    'authorised', true,
    'expanded', true,
    'expand_result', v_expand_result,
    'immediate_process_result', v_immediate_process_result,
    'progress', v_work_item_counts
  );

EXCEPTION
  WHEN OTHERS THEN
    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_AUTHORISE_ERROR',
      jsonb_build_object(
        'correction_request_id', p_correction_request_id,
        'actor_user_id', p_actor_user_id,
        'action', p_action,
        'sqlstate', SQLSTATE,
        'error_message', SQLERRM
      ),
      'pay_payment_correction',
      COALESCE(p_correction_request_id::text, 'NO_CORRECTION_REQUEST_ID'),
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RAISE;
END;
$function$;



CREATE OR REPLACE FUNCTION public.pay_payment_correction_expand_work(
  p_correction_request_id uuid,
  p_actor_user_id uuid DEFAULT NULL::uuid
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_request public.pay_payment_correction_requests%rowtype;
  v_now timestamptz := now();
  v_work_kind text;
  v_plan_work_unit text;
  v_effective_work_unit text;
  v_existing_work_item_count integer := 0;
  v_inserted_work_item_count integer := 0;
  v_selected_item_count integer := 0;
  v_selected_candidate_count integer := 0;
  v_selected_transfer_count integer := 0;
  v_selected_finance_case_count integer := 0;
  v_progress jsonb := '{}'::jsonb;
  v_before_json jsonb := '{}'::jsonb;
  v_after_json jsonb := '{}'::jsonb;
  v_selected_pay_batch_item_ids jsonb := '[]'::jsonb;
  v_selected_pay_bank_transfer_ids jsonb := '[]'::jsonb;
  v_selected_finance_case_ids jsonb := '[]'::jsonb;
  v_selected_finance_component_ids jsonb := '[]'::jsonb;
  v_selected_reservation_ids jsonb := '[]'::jsonb;
  v_plan_provider_failure_reason_group text := NULL::text;
  v_plan_provider_failure_reason_code text := NULL::text;
  v_plan_provider_failure_reason_label text := NULL::text;
  v_plan_source_bank_event_links jsonb := '{}'::jsonb;
  v_plan_alert_candidate_kind text := NULL::text;
  v_plan_alert_candidate_severity text := NULL::text;
  v_plan_live_status_signature text := NULL::text;
BEGIN
  PERFORM public._imp_debug_audit(
    p_actor_user_id,
    'PAYMENT_CORRECTION_EXPAND_WORK_START',
    jsonb_build_object(
      'correction_request_id', p_correction_request_id,
      'actor_user_id', p_actor_user_id
    ),
    'pay_payment_correction',
    COALESCE(p_correction_request_id::text, 'NO_CORRECTION_REQUEST_ID'),
    NULL::jsonb,
    NULL::text,
    NULL::text,
    NULL::text
  );

  IF p_correction_request_id IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_ID_REQUIRED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object('code', 'PAYMENT_CORRECTION_REQUEST_ID_REQUIRED')::text;
  END IF;

  SELECT public.pay_payment_correction_requests.*
  INTO v_request
  FROM public.pay_payment_correction_requests
  WHERE public.pay_payment_correction_requests.id = p_correction_request_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_NOT_FOUND',
              'correction_request_id', p_correction_request_id
            )::text;
  END IF;

  v_before_json := jsonb_build_object(
    'status', v_request.status,
    'correction_kind', v_request.correction_kind,
    'approved_count', v_request.approved_count,
    'required_quantity', v_request.required_quantity,
    'plan_hash', v_request.plan_hash
  );

  IF v_request.status IN ('APPLIED', 'APPLIED_WITH_BLOCKERS', 'FAILED', 'REJECTED', 'CANCELLED') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_TERMINAL_CANNOT_EXPAND_WORK'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_TERMINAL_CANNOT_EXPAND_WORK',
              'correction_request_id', p_correction_request_id,
              'status', v_request.status
            )::text;
  END IF;

  IF v_request.status NOT IN ('AUTHORISED', 'EXPANDED', 'PROCESSING') THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISED_FOR_EXPANSION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_REQUEST_NOT_AUTHORISED_FOR_EXPANSION',
              'correction_request_id', p_correction_request_id,
              'status', v_request.status
            )::text;
  END IF;

  SELECT count(*)::integer
  INTO v_existing_work_item_count
  FROM public.pay_payment_correction_work_items
  WHERE public.pay_payment_correction_work_items.correction_request_id = p_correction_request_id;

  IF v_existing_work_item_count > 0 THEN
    IF v_request.status = 'AUTHORISED' THEN
      UPDATE public.pay_payment_correction_requests AS existing_work_request
      SET
        status = 'EXPANDED',
        updated_at_utc = v_now
      WHERE existing_work_request.id = p_correction_request_id
      RETURNING existing_work_request.*
      INTO v_request;
    END IF;

    SELECT jsonb_build_object(
      'total', count(*)::integer,
      'pending', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PENDING')::integer,
      'processing', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'PROCESSING')::integer,
      'applied', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'APPLIED')::integer,
      'skipped', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'SKIPPED')::integer,
      'blocked', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'BLOCKED')::integer,
      'failed_retryable', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_RETRYABLE')::integer,
      'failed_final', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'FAILED_FINAL')::integer,
      'cancelled', count(*) FILTER (WHERE public.pay_payment_correction_work_items.status = 'CANCELLED')::integer
    )
    INTO v_progress
    FROM public.pay_payment_correction_work_items
    WHERE public.pay_payment_correction_work_items.correction_request_id = p_correction_request_id;

    PERFORM public._imp_debug_audit(
      p_actor_user_id,
      'PAYMENT_CORRECTION_EXPAND_WORK_EXISTING',
      jsonb_build_object(
        'correction_request_id', p_correction_request_id,
        'pay_batch_id', v_request.pay_batch_id,
        'status', v_request.status,
        'existing_work_item_count', v_existing_work_item_count,
        'progress', v_progress
      ),
      'pay_payment_correction',
      p_correction_request_id::text,
      NULL::jsonb,
      NULL::text,
      NULL::text,
      NULL::text
    );

    RETURN jsonb_build_object(
      'ok', true,
      'already_expanded', true,
      'correction_request_id', p_correction_request_id,
      'pay_batch_id', v_request.pay_batch_id,
      'status', v_request.status,
      'work_kind', CASE v_request.correction_kind
        WHEN 'PRE_BANK_CANCEL' THEN 'PRE_BANK_CANCEL'
        WHEN 'NO_MONEY_UNWIND' THEN 'NO_MONEY_UNWIND'
        WHEN 'MANUAL_EVIDENCE_NO_MONEY' THEN 'NO_MONEY_UNWIND'
        ELSE NULL
      END,
      'inserted_work_item_count', 0,
      'existing_work_item_count', v_existing_work_item_count,
      'progress', v_progress
    );
  END IF;

  v_work_kind := CASE v_request.correction_kind
    WHEN 'PRE_BANK_CANCEL' THEN 'PRE_BANK_CANCEL'
    WHEN 'NO_MONEY_UNWIND' THEN 'NO_MONEY_UNWIND'
    WHEN 'MANUAL_EVIDENCE_NO_MONEY' THEN 'NO_MONEY_UNWIND'
    ELSE NULL
  END;

  v_plan_provider_failure_reason_group := NULLIF(btrim(COALESCE(v_request.plan_json->>'provider_failure_reason_group', '')), '');
  v_plan_provider_failure_reason_code := NULLIF(btrim(COALESCE(v_request.plan_json->>'provider_failure_reason_code', '')), '');
  v_plan_provider_failure_reason_label := NULLIF(btrim(COALESCE(v_request.plan_json->>'provider_failure_reason_label', '')), '');
  v_plan_source_bank_event_links := COALESCE(v_request.plan_json->'source_bank_event_links', '{}'::jsonb);
  v_plan_alert_candidate_kind := NULLIF(btrim(COALESCE(v_request.plan_json->>'alert_candidate_kind', '')), '');
  v_plan_alert_candidate_severity := NULLIF(btrim(COALESCE(v_request.plan_json->>'alert_candidate_severity', '')), '');
  v_plan_live_status_signature := COALESCE(NULLIF(btrim(v_request.plan_json->>'live_status_signature'), ''), NULLIF(btrim(v_request.plan_json->>'status_update_signature'), ''));

  IF v_work_kind IS NULL THEN
    RAISE EXCEPTION 'PAYMENT_CORRECTION_WORK_KIND_NOT_RESOLVED'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'PAYMENT_CORRECTION_WORK_KIND_NOT_RESOLVED',
              'correction_request_id', p_correction_request_id,
              'correction_kind', v_request.correction_kind
            )::text;
  END IF;

  v_plan_work_unit := upper(nullif(btrim(COALESCE(v_request.plan_json->'work_expansion_plan'->>'work_unit', '')), ''));

  DROP TABLE IF EXISTS pg_temp._tmp_payment_correction_expand_selected;
  CREATE TEMP TABLE _tmp_payment_correction_expand_selected ON COMMIT DROP AS
  SELECT
    expand_selected.pay_batch_id,
    expand_selected.pay_batch_candidate_id,
    expand_selected.candidate_id,
    expand_selected.candidate_display_name,
    expand_selected.pay_batch_item_id,
    expand_selected.item_type,
    expand_selected.timesheet_id,
    expand_selected.pay_bank_transfer_id,
    expand_selected.transfer_group_key,
    expand_selected.pay_channel,
    expand_selected.payee_entity_kind,
    expand_selected.payee_entity_id,
    expand_selected.umbrella_id,
    expand_selected.finance_case_id,
    expand_selected.finance_component_id,
    expand_selected.reservation_id,
    expand_selected.amount_inc_vat
  FROM public._pay_payment_correction_selected_items(
    v_request.pay_batch_id,
    v_request.selection_json,
    false
  ) AS expand_selected;

  CREATE INDEX ON pg_temp._tmp_payment_correction_expand_selected (pay_batch_candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_expand_selected (candidate_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_expand_selected (pay_bank_transfer_id);
  CREATE INDEX ON pg_temp._tmp_payment_correction_expand_selected (finance_case_id);

  SELECT
    count(*)::integer,
    count(DISTINCT expand_selected.pay_batch_candidate_id) FILTER (WHERE expand_selected.pay_batch_candidate_id IS NOT NULL)::integer,
    count(DISTINCT expand_selected.pay_bank_transfer_id) FILTER (WHERE expand_selected.pay_bank_transfer_id IS NOT NULL)::integer,
    count(DISTINCT expand_selected.finance_case_id) FILTER (WHERE expand_selected.finance_case_id IS NOT NULL)::integer
  INTO
    v_selected_item_count,
    v_selected_candidate_count,
    v_selected_transfer_count,
    v_selected_finance_case_count
  FROM pg_temp._tmp_payment_correction_expand_selected AS expand_selected;

  SELECT
    COALESCE(to_jsonb(array_agg(DISTINCT expand_selected.pay_batch_item_id::text ORDER BY expand_selected.pay_batch_item_id::text)), '[]'::jsonb),
    COALESCE(to_jsonb(array_agg(DISTINCT expand_selected.pay_bank_transfer_id::text ORDER BY expand_selected.pay_bank_transfer_id::text) FILTER (WHERE expand_selected.pay_bank_transfer_id IS NOT NULL)), '[]'::jsonb),
    COALESCE(to_jsonb(array_agg(DISTINCT expand_selected.finance_case_id::text ORDER BY expand_selected.finance_case_id::text) FILTER (WHERE expand_selected.finance_case_id IS NOT NULL)), '[]'::jsonb),
    COALESCE(to_jsonb(array_agg(DISTINCT expand_selected.finance_component_id::text ORDER BY expand_selected.finance_component_id::text) FILTER (WHERE expand_selected.finance_component_id IS NOT NULL)), '[]'::jsonb),
    COALESCE(to_jsonb(array_agg(DISTINCT expand_selected.reservation_id::text ORDER BY expand_selected.reservation_id::text) FILTER (WHERE expand_selected.reservation_id IS NOT NULL)), '[]'::jsonb)
  INTO
    v_selected_pay_batch_item_ids,
    v_selected_pay_bank_transfer_ids,
    v_selected_finance_case_ids,
    v_selected_finance_component_ids,
    v_selected_reservation_ids
  FROM pg_temp._tmp_payment_correction_expand_selected AS expand_selected;

  IF v_selected_item_count <= 0 THEN
    RAISE EXCEPTION 'NO_SELECTED_PAYMENT_ITEMS_FOR_WORK_EXPANSION'
      USING ERRCODE = 'P0001',
            DETAIL = jsonb_build_object(
              'code', 'NO_SELECTED_PAYMENT_ITEMS_FOR_WORK_EXPANSION',
              'correction_request_id', p_correction_request_id,
              'pay_batch_id', v_request.pay_batch_id
            )::text;
  END IF;

  v_effective_work_unit := CASE
    WHEN v_plan_work_unit IN ('TRANSFER', 'CANDIDATE', 'CANDIDATE_TRANSFER', 'FINANCE_CASE', 'BATCH') THEN v_plan_work_unit
    WHEN v_work_kind = 'NO_MONEY_UNWIND' AND v_selected_transfer_count > 0 THEN 'TRANSFER'
    WHEN v_selected_finance_case_count > 0 THEN 'FINANCE_CASE'
    WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE'
    ELSE 'BATCH'
  END;

  IF v_effective_work_unit = 'TRANSFER' AND v_selected_transfer_count = 0 THEN
    v_effective_work_unit := CASE WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE' ELSE 'BATCH' END;
  END IF;

  IF v_effective_work_unit = 'FINANCE_CASE' AND v_selected_finance_case_count = 0 THEN
    v_effective_work_unit := CASE WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE' ELSE 'BATCH' END;
  END IF;

  IF v_effective_work_unit = 'CANDIDATE' AND v_selected_candidate_count = 0 THEN
    v_effective_work_unit := 'BATCH';
  END IF;

  IF v_effective_work_unit = 'CANDIDATE_TRANSFER'
     AND (v_selected_candidate_count = 0 OR v_selected_transfer_count = 0) THEN
    v_effective_work_unit := CASE
      WHEN v_selected_transfer_count > 0 THEN 'TRANSFER'
      WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE'
      ELSE 'BATCH'
    END;
  END IF;

  IF v_effective_work_unit = 'BATCH' THEN
    v_effective_work_unit := CASE
      WHEN v_selected_transfer_count > 0 THEN 'TRANSFER'
      WHEN v_selected_candidate_count > 0 THEN 'CANDIDATE'
      ELSE 'CANDIDATE'
    END;
  END IF;

  IF v_work_kind IN ('PRE_BANK_CANCEL', 'NO_MONEY_UNWIND') THEN
    v_effective_work_unit := CASE
      WHEN v_selected_transfer_count > 0 THEN 'TRANSFER'
      ELSE 'CANDIDATE_PAYEE'
    END;
  END IF;

  IF v_effective_work_unit = 'BATCH' THEN
    INSERT INTO public.pay_payment_correction_work_items(
      correction_request_id,
      pay_batch_id,
      pay_batch_candidate_id,
      pay_bank_transfer_id,
      candidate_id,
      umbrella_id,
      work_kind,
      selection_json,
      selection_hash,
      status,
      attempt_count,
      last_error,
      locked_at_utc,
      locked_by,
      created_at_utc,
      processed_at_utc,
      result_json
    )
    VALUES (
      p_correction_request_id,
      v_request.pay_batch_id,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      NULL::uuid,
      v_work_kind,
      v_request.selection_json || jsonb_build_object(
        'work_unit', 'BATCH',
        'source_correction_request_id', p_correction_request_id::text,
        'expanded_by_user_id', CASE WHEN p_actor_user_id IS NULL THEN NULL ELSE p_actor_user_id::text END,
        'pay_batch_item_ids', v_selected_pay_batch_item_ids,
        'expected_pay_batch_item_ids', v_selected_pay_batch_item_ids,
        'expected_item_count', v_selected_item_count,
        'pay_bank_transfer_ids', v_selected_pay_bank_transfer_ids,
        'finance_case_ids', v_selected_finance_case_ids,
        'finance_component_ids', v_selected_finance_component_ids,
        'reservation_ids', v_selected_reservation_ids,
        'provider_failure_reason_group', v_plan_provider_failure_reason_group,
        'provider_failure_reason_code', v_plan_provider_failure_reason_code,
        'provider_failure_reason_label', v_plan_provider_failure_reason_label,
        'provider_evidence_snapshot', COALESCE(v_request.plan_json->'provider_evidence', '{}'::jsonb),
        'source_bank_event_links', v_plan_source_bank_event_links,
        'source_bank_event_id', CASE WHEN v_request.source_bank_event_id IS NULL THEN NULL ELSE v_request.source_bank_event_id::text END,
        'provider_webhook_receipt_id', v_plan_source_bank_event_links->>'provider_webhook_receipt_id',
        'provider_event_key', v_plan_source_bank_event_links->>'provider_event_key',
        'provider_event_type', v_plan_source_bank_event_links->>'provider_event_type',
        'provider_transaction_id', v_plan_source_bank_event_links->>'provider_transaction_id',
        'provider_request_id', v_plan_source_bank_event_links->>'provider_request_id',
        'alert_candidate_kind', v_plan_alert_candidate_kind,
        'alert_candidate_severity', v_plan_alert_candidate_severity,
        'live_status_signature', v_plan_live_status_signature,
        'expected_signed_amount_summary', jsonb_build_object('amount_inc_vat', COALESCE(NULLIF(btrim(v_request.plan_json#>>'{amounts,amount_inc_vat}'), '')::numeric, 0)),
        'carry_forward_source_item_ids', COALESCE(v_request.plan_json->'manual_adjustments_to_carry_forward', '[]'::jsonb),
        'existing_carry_forward_target_ids', COALESCE(v_request.plan_json->'manual_adjustments_carried_forward_existing', '[]'::jsonb)
      ),
      md5(jsonb_build_object(
        'correction_request_id', p_correction_request_id::text,
        'work_kind', v_work_kind,
        'work_unit', 'BATCH',
        'expected_pay_batch_item_ids', v_selected_pay_batch_item_ids,
        'pay_bank_transfer_ids', v_selected_pay_bank_transfer_ids,
        'finance_case_ids', v_selected_finance_case_ids,
        'finance_component_ids', v_selected_finance_component_ids,
        'reservation_ids', v_selected_reservation_ids
      )::text),
      'PENDING',
      0,
      NULL::text,
      NULL::timestamptz,
      NULL::text,
      v_now,
