    JOIN key_names ON true
    CROSS JOIN LATERAL jsonb_array_elements_text(
      COALESCE(
        CASE WHEN jsonb_typeof(scope_payloads.payload -> key_names.key_name) = 'array'
          THEN scope_payloads.payload -> key_names.key_name
